INSERT INTO balaw.jo (id, content, jang_id) VALUES (1, '제1조(목적) 이 영은 「환경범죄 등의 단속 및 가중처벌에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 1);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2, '제2조 삭제 <2020.11.10>', 1);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3, '제3조(과징금의 산정방법)', 1);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4, '제4조 삭제 <2020.11.10>', 1);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5, '제5조 삭제 <2020.11.10>', 1);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6, '제6조(과징금의 부과 및 납부)', 1);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7, '제7조 삭제 <2020.11.10>', 1);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8, '제8조(행정처분의 기준) 법 제13조제1항에 따른 행정처분(이하 "행정처분"이라 한다)의 기준은 별표 2와 같다. <개정 2025.9.23>', 1);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9, '제9조(표지판) 법 제13조제4항에 따른 불법배출시설 표지판은 별표 3과 같이 하며, 일반인이 보기 쉽도록 불법배출시설의 입구에 지상 1미터 이상의 높이에 설치하여야 한다.', 1);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10, '제9조의2(행정처분 이력 등의 확인)', 1);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (11, '제10조(포상금의 지급)', 1);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (12, '제11조(환경감시관의 자격ㆍ임명)', 1);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (13, '제12조(환경감시관의 임명의 해제)', 1);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (14, '제13조(환경감시관의 직무) 환경감시관의 구체적인 직무 범위는 다음 각 호와 같다. <개정 2020.11.10>', 1);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (15, '제14조(활동비 지급) 환경감시관에게는 예산의 범위에서 필요한 활동비를 지급한다.', 1);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (16, '제15조(증표)', 1);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (17, '제16조(오염도 검사기관) 법 제16조제2항에서 "대통령령으로 정하는 검사기관"이란 다음 각 호의 어느 하나에 해당하는 기관을 말한다.', 1);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (18, '제17조(권한의 위임)', 1);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (19, '제18조(보고) 시ㆍ도지사, 지방환경관서의 장은 제17조에 따라 위임받은 업무를 처리하였을 때에는 환경부장관이 정하는 바에 따라 그 내용을 환경부장관에게 보고하여야 한다.', 1);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (20, '제1조(목적) 이 규칙은 「형사소송법」(다음부터 "법"이라 한다)이 대법원규칙에 위임한 사항, 그 밖에 형사소송절차에 관하여 필요한 사항을 규정함을 목적으로 한다.', 2);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (21, '제2조(토지관할의 병합심리 신청 등)', 3);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (22, '제3조(토지관할의 병합심리절차)', 3);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (23, '제4조(사물관할의 병합심리)', 3);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (24, '제4조의2(항소사건의 병합심리)', 3);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (25, '제5조(관할지정 또는 관할이전의 신청 등)', 3);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (26, '제6조(관할지정 또는 관할이전의 결정에 의한 처리절차)', 3);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (27, '제7조(소송절차의 정지) 법원은 그 계속 중인 사건에 관하여 토지관할의 병합심리신청, 관할지정신청 또는 관할이전신청이 제기된 경우에는 그 신청에 대한 결정이 있기까지 소송절차를 정지하여야 한다. 다만, 급속을 요하는 경우에는 그러하지 아니하다.', 3);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (28, '제8조(소송기록 등의 송부방법 등)', 3);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (29, '제9조(기피신청의 방식 등)', 4);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (30, '제10조(피의자의 특별대리인 선임청구사건의 관할) 법 제28조제1항 후단의 규정에 의한 피의자의 특별대리인 선임청구는 그 피의사건을 수사 중인 검사 또는 사법경찰관이 소속된 관서의 소재지를 관할하는 지방법원에 이를 하여야 한다.', 5);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (31, '제11조(보조인의 신고)', 5);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (32, '제12조(법정대리인 등의 변호인 선임) 법 제30조제2항에 규정한 자가 변호인을 선임하는 때에는 그 자와 피고인 또는 피의자와의 신분관계를 소명하는 서면을 법 제32조제1항의 서면에 첨부하여 제출하여야 한다.', 6);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (33, '제13조(사건이 병합되었을 경우의 변호인 선임의 효력) 하나의 사건에 관하여 한 변호인 선임은 동일법원의 동일피고인에 대하여 병합된 다른 사건에 관하여도 그 효력이 있다. 다만, 피고인 또는 변호인이 이와 다른 의사표시를 한 때에는 그러하지 아니하다. <개정 1996.12.3>', 6);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (34, '제13조의2(대표변호인 지정등의 신청) 대표변호인의 지정, 지정의 철회 또는 변경의 신청은 그 사유를 기재한 서면으로 한다. 다만, 공판기일에서는 구술로 할 수 있다.', 6);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (35, '제13조의3(대표변호인의 지정등의 통지) 대표변호인의 지정, 지정의 철회 또는 변경은 피고인 또는 피의자의 신청에 의한 때에는 검사 및 대표변호인에게, 변호인의 신청에 의하거나 직권에 의한 때에는 피고인 또는 피의자 및 검사에게 이를 통지하여야 한다. <개정 2007.10.29>', 6);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (36, '제13조의4(기소전 대표변호인 지정의 효력) 법 제32조의2제5항에 의한 대표변호인의 지정은 기소후에도 그 효력이 있다.', 6);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (37, '제13조의5(준용규정) 제13조의 규정은 대표변호인의 경우에 이를 준용한다.', 6);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (38, '제14조(국선변호인의 자격)', 6);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (39, '제15조(변호인의 수)', 6);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (40, '제15조의2(국선전담변호사) 법원은 기간을 정하여 법원의 관할구역 안에 사무소를 둔 변호사(그 관할구역 안에 사무소를 둘 예정인 변호사를 포함한다) 중에서 국선변호를 전담하는 변호사를 지정할 수 있다.', 6);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (41, '제16조(공소가 제기되기 전의 국선변호인 선정)', 6);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (42, '제16조의2(국선변호인 예정자명부의 작성)', 6);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (43, '제17조(공소제기의 경우 국선변호인의 선정등)', 6);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (44, '제17조의2(국선변호인 선정청구 사유의 소명) 법 제33조제2항에 의하여 국선변호인 선정을 청구하는 경우 피고인은 소명자료를 제출하여야 한다. 다만, 기록에 의하여 그 사유가 소명되었다고 인정될 때에는 그러하지 아니하다.', 6);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (45, '제18조(선정취소)', 6);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (46, '제19조(법정에서의 선정등)', 6);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (47, '제20조(사임) 국선변호인은 다음 각호의 어느 하나에 해당하는 경우에는 법원 또는 지방법원 판사의 허가를 얻어 사임할 수 있다. <개정 2006.8.17>', 6);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (48, '제21조(감독) 법원은 국선변호인이 그 임무를 해태하여 국선변호인으로서의 불성실한 사적이 현저하다고 인정할 때에는 그 사유를 대한변호사협회장 또는 소속지방변호사회장에게 통고할 수 있다.', 6);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (49, '제22조 삭제 <1999.12.31>', 6);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (50, '제23조 삭제 <2007.10.29>', 6);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (51, '제24조(결정, 명령을 위한 사실조사)', 7);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (52, '제25조(재판서의 경정)', 7);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (53, '제25조의2(기명날인할 수 없는 재판서) 법 제41조제3항에 따라 서명날인에 갈음하여 기명날인할 수 없는 재판서는 판결과 각종 영장(감정유치장 및 감정처분허가장을 포함한다)을 말한다.', 7);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (54, '제26조(재판서의 등, 초본 청구권자의 범위)', 7);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (55, '제27조(소송에 관한 사항의 증명서의 청구) 피고인과 제26조제1항에 규정한 소송관계인 및 고소인, 고발인 또는 피해자는 소송에 관한 사항의 증명서의 교부를 청구할 수 있다. 다만, 고소인, 고발인 또는 피해자의 청구에 관하여는 제26조제2항 단서의 규정을 준용한다.', 7);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (56, '제28조(등, 초본 등의 작성방법) 법 제45조에 규정한 등본, 초본(제26조제2항에 규정한 등본, 초본을 포함한다) 또는 제27조에 규정한 증명서를 작성함에 있어서는 담당 법원서기관, 법원사무관, 법원주사, 법원주사보(이하 "법원사무관등"이라 한다)가 등본, 초본 또는 소송에 관한 사항의 증명서라는 취지를 기재하고 기명날인하여야 한다.', 7);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (57, '제29조(조서에의 인용)', 8);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (58, '제29조의2(변경청구나 이의제기가 있는 경우의 처리) 공판조서의 기재에 대하여 법 제54조제3항에 따른 변경청구나 이의제기가 있는 경우, 법원사무관 등은 신청의 연월일 및 그 요지와 그에 대한 재판장의 의견을 기재하여 조서를 작성한 후 당해 공판조서 뒤에 이를 첨부하여야 한다.', 8);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (59, '제30조(공판조서의 낭독 등) 법 제55조제2항에 따른 피고인의 낭독청구가 있는 때에는 재판장의 명에 의하여 법원사무관 등이 낭독하거나 녹음물 또는 영상녹화물을 재생한다.', 8);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (60, '제30조의2(속기 등의 신청)', 8);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (61, '제31조 삭제 <2007.10.29>', 8);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (62, '제32조 삭제 <2007.10.29>', 8);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (63, '제33조(속기록에 대한 조치) 속기를 하게 한 경우에 재판장은 법원사무관 등으로 하여금 속기록의 전부 또는 일부를 조서에 인용하고 소송기록에 첨부하여 조서의 일부로 하게 할 수 있다.', 8);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (64, '제34조(진술자에 대한 확인 등) 속기를 하게 한 경우 법 제48조제3항 또는 법 제52조 단서에 따른 절차의 이행은 법원사무관 등 또는 법원에 소속되어 있거나 법원이 선정한 속기능력소지자(다음부터 "속기사 등"이라고 한다)로 하여금 속기록의 내용을 읽어주게 하거나 진술자에게 속기록을 열람하도록 하는 방법에 의한다.', 8);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (65, '제35조 삭제 <2007.10.29>', 8);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (66, '제36조 삭제 <2007.10.29>', 8);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (67, '제37조 삭제 <2007.10.29>', 8);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (68, '제38조(녹취서의 작성등)', 8);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (69, '제38조의2(속기록, 녹음물 또는 영상녹화물의 사본 교부)', 8);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (70, '제39조(속기록 등의 보관과 폐기) 속기록, 녹음물, 영상녹화물 또는 녹취서는 전자적 형태로 이를 보관할 수 있으며, 재판이 확정되면 폐기한다. 다만, 속기록, 녹음물, 영상녹화물 또는 녹취서가 조서의 일부가 된 경우에는 그러하지 아니하다. <개정 2012.5.29>', 8);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (71, '제40조 삭제 <2007.10.29>', 8);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (72, '제40조의2', 8);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (73, '제41조(서명의 특칙) 공무원이 아닌 자가 서명날인을 하여야 할 경우에 서명을 할 수 없으면 타인이 대서한다. 이 경우에는 대서한 자가 그 사유를 기재하고 기명날인 또는 서명하여야 한다. <개정 2007.10.29>', 8);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (74, '제42조(법 제60조에 의한 법원소재지의 범위) 법 제60조제1항에 규정한 법원소재지는 당해 법원이 위치한 특별시, 광역시, 시 또는 군(다만, 廣域市내의 郡은 除外)으로 한다. <개정 1996.12.3>', 9);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (75, '제43조(공시송달을 명하는 재판) 법원은 공시송달의 사유가 있다고 인정한 때에는 직권으로 결정에 의하여 공시송달을 명한다.', 9);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (76, '제44조(법정기간의 연장)', 10);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (77, '제45조(소환의 유예기간) 피고인에 대한 소환장은 법 제269조의 경우를 제외하고는 늦어도 출석할 일시 12시간 이전에 송달하여야 한다. 다만, 피고인이 이의를 하지 아니하는 때에는 그러하지 아니하다.', 11);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (78, '제45조의2(비디오 등 중계장치에 의한 구속사유 고지)', 11);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (79, '제46조(구속영장의 기재사항) 구속영장에는 법 제75조에 규정한 사항외에 피고인의 주민등록번호(외국인인 경우에는 외국인등록번호, 위 번호들이 없거나 이를 알 수 없는 경우에는 생년월일 및 성별, 다음부터 \'주민등록번호 등\'이라 한다)ㆍ직업 및 법 제70조제1항 각호에 규정한 구속의 사유를 기재하여야 한다. <개정 1996.12.3, 2007.10.29>', 11);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (80, '제47조(수탁판사 또는 재판장 등의 구속영장 등의 기재요건) 수탁판사가 법 제77조제3항의 규정에 의하여 구속영장을 발부하는 때나 재판장 또는 합의부원이 법 제80조의 규정에 의하여 소환장 또는 구속영장을 발부하는 때에는 그 취지를 소환장 또는 구속영장에 기재하여야 한다.', 11);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (81, '제48조(검사에 대한 구속영장의 송부) 검사의 지휘에 의하여 구속영장을 집행하는 경우에는 구속영장을 발부한 법원이 그 원본을 검사에게 송부하여야 한다.', 11);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (82, '제49조(구속영장집행후의 조치)', 11);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (83, '제49조의2(구인을 위한 구속영장 집행후의 조치) 구인을 위한 구속영장의 집행에 관한 서류를 제출받은 법원의 재판장은 법원사무관 등에게 피고인이 인치된 일시를 구속영장에 기재하게 하여야 하고, 법 제71조의2에 따라 피고인을 유치할 경우에는 유치할 장소를 구속영장에 기재하고 서명날인하여야 한다.', 11);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (84, '제50조(구속영장등본의 교부청구)', 11);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (85, '제51조(구속의 통지)', 11);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (86, '제52조(구속과 범죄사실등의 고지) 법원 또는 법관은 법 제72조 및 법 제88조의 규정에 의한 고지를 할 때에는 법원사무관등을 참여시켜 조서를 작성하게 하거나 피고인 또는 피의자로 하여금 확인서 기타 서면을 작성하게 하여야 한다. <개정 1996.12.3, 1997.12.31>', 11);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (87, '제53조(보석 등의 청구)', 11);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (88, '제53조의2(진술서 등의 제출)', 11);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (89, '제54조(기록 등의 제출)', 11);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (90, '제54조의2(보석의 심리)', 11);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (91, '제55조(보석 등의 결정기한) 법원은 특별한 사정이 없는 한 보석 또는 구속취소의 청구를 받은 날부터 7일 이내에 그에 관한 결정을 하여야 한다.', 11);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (92, '제55조의2(불허가 결정의 이유) 보석을 허가하지 아니하는 결정을 하는 때에는 결정이유에 법 제95조 각호중 어느 사유에 해당하는지를 명시하여야 한다.', 11);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (93, '제55조의3(보석석방 후의 조치)', 11);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (94, '제55조의4(보석조건 변경의 통지) 법원은 보석을 허가한 후에 보석의 조건을 변경하거나 보석조건의 이행을 유예하는 결정을 한 경우에는 그 취지를 검사에게 지체없이 통지하여야 한다. <개정 2007.10.29>', 11);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (95, '제55조의5(보석조건의 위반과 피고인에 대한 과태료 등)', 11);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (96, '제56조(보석 등의 취소에 의한 재구금절차)', 11);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (97, '제57조(상소 등과 구속에 관한 결정)', 11);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (98, '제58조(압수수색영장의 기재사항) 압수수색영장에는 압수수색의 사유를 기재하여야 한다. <개정 1996.12.3>', 12);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (99, '제59조(준용규정) 제48조의 규정은 압수수색영장에 이를 준용한다.', 12);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (100, '제60조(압수와 수색의 참여)', 12);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (101, '제61조(수색증명서, 압수품목록의 작성등) 법 제128조에 규정된 증명서 또는 법 제129조에 규정된 목록은 제60조제1항의 규정에 의한 압수수색을 한 때에는 참여한 법원사무관등이 제60조제2항의 규정에 의한 압수수색을 한 때에는 그 집행을 한 자가 각 작성 교부한다.', 12);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (102, '제62조(압수수색조서의 기재) 압수수색에 있어서 제61조의 규정에 의한 증명서 또는 목록을 교부하거나 법 제130조의 규정에 의한 처분을 한 경우에는 압수수색의 조서에 그 취지를 기재하여야 한다.', 12);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (103, '제63조(압수수색영장 집행후의 조치) 압수수색영장의 집행에 관한 서류와 압수한 물건은 압수수색영장을 발부한 법원에 이를 제출하여야 한다. 다만, 검사의 지휘에 의하여 집행된 경우에는 검사를 경유하여야 한다.', 12);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (104, '제64조(피고인의 신체검사 소환장의 기재사항) 피고인에 대한 신체검사를 하기 위한 소환장에는 신체검사를 하기 위하여 소환한다는 취지를 기재하여야 한다.', 13);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (105, '제65조(피고인 아닌 자의 신체검사의 소환장의 기재사항) 피고인이 아닌 자에 대한 신체검사를 하기 위한 소환장에는 그 성명 및 주거, 피고인의 성명, 죄명, 출석일시 및 장소와 신체검사를 하기 위하여 소환한다는 취지를 기재하고 재판장 또는 수명법관이 기명날인하여야 한다. <개정 1996.12.3>', 13);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (106, '제66조(신문사항 등) 재판장은 피해자ㆍ증인의 인적사항의 공개 또는 누설을 방지하거나 그 밖에 피해자ㆍ증인의 안전을 위하여 필요하다고 인정할 때에는 증인의 신문을 청구한 자에 대하여 사전에 신문사항을 기재한 서면의 제출을 명할 수 있다.', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (107, '제67조(결정의 취소) 법원은 제66조의 명을 받은 자가 신속히 그 서면을 제출하지 아니한 경우에는 증거결정을 취소할 수 있다. <개정 2007.10.29>', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (108, '제67조의2(증인의 소환방법)', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (109, '제68조(소환장ㆍ구속영장의 기재사항)', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (110, '제68조의2(불출석의 신고) 증인이 출석요구를 받고 기일에 출석할 수 없을 경우에는 법원에 바로 그 사유를 밝혀 신고하여야 한다.', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (111, '제68조의3(증인에 대한 과태료 등) 법 제151조제1항에 따른 과태료와 소송비용 부담의 재판절차에 관하여는 비송사건절차법 제248조, 제250조(다만, 제248조제3항 후문과 검사에 관한 부분을 제외한다)를 준용한다.', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (112, '제68조의4(증인에 대한 감치)', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (113, '제69조(준용규정) 제48조, 제49조, 제49조의2 전단의 규정은 증인의 구인에 이를 준용한다. <개정 2007.10.29>', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (114, '제70조(소환의 유예기간) 증인에 대한 소환장은 늦어도 출석할 일시 24시간 이전에 송달하여야 한다. 다만, 급속을 요하는 경우에는 그러하지 아니하다.', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (115, '제70조의2(소환장이 송달불능된 때의 조치) 제68조에 따른 증인에 대한 소환장이 송달불능된 경우 증인을 신청한 자는 재판장의 명에 의하여 증인의 주소를 서면으로 보정하여야 하고, 이 때 증인의 소재, 연락처와 출석가능성 등을 충분히 조사하여 성실하게 기재하여야 한다.', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (116, '제71조(증인의 동일성 확인) 재판장은 증인으로부터 주민등록증 등 신분증을 제시받거나 그 밖의 적당한 방법으로 증인임이 틀림없음을 확인하여야 한다.', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (117, '제72조(선서취지의 설명) 증인이 선서의 취지를 이해할 수 있는가에 대하여 의문이 있는 때에는 선서전에 그 점에 대하여 신문하고, 필요하다고 인정할 때에는 선서의 취지를 설명하여야 한다.', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (118, '제73조(서면에 의한 신문) 증인이 들을 수 없는 때에는 서면으로 묻고 말할 수 없는 때에는 서면으로 답하게 할 수 있다.', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (119, '제74조(증인신문의 방법)', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (120, '제75조(주신문)', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (121, '제76조(반대신문)', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (122, '제77조(증언의 증명력을 다투기 위하여 필요한 사항의 신문)', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (123, '제78조(재 주신문)', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (124, '제79조(재판장의 허가에 의한 재신문) 검사, 피고인 또는 변호인은 주신문, 반대신문 및 재 주신문이 끝난 후에도 재판장의 허가를 얻어 다시 신문을 할 수 있다.', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (125, '제80조(재판장에 의한 신문순서 변경의 경우)', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (126, '제81조(직권에 의한 증인의 신문) 법 제161조의2제4항에 규정한 증인에 대하여 재판장이 신문한 후 검사, 피고인 또는 변호인이 신문하는 때에는 반대신문의 예에 의한다.', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (127, '제82조(서류 또는 물건에 관한 신문)', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (128, '제83조(기억의 환기가 필요한 경우)', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (129, '제84조(증언을 명확히 할 필요가 있는 경우)', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (130, '제84조의2(증인의 증인신문조서 열람 등) 증인은 자신에 대한 증인신문조서 및 그 일부로 인용된 속기록, 녹음물, 영상녹화물 또는 녹취서의 열람, 등사 또는 사본을 청구할 수 있다.', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (131, '제84조의3(신뢰관계에 있는 사람의 동석)', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (132, '제84조의4(비디오 등 중계장치 등에 의한 신문 여부의 결정)', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (133, '제84조의5(비디오 등 중계장치에 의한 신문의 실시) 제123조의13제1항내지 제4항과 제6항 내지 제8항은 법 제165조의2제1항, 제2항에 따라 비디오 등 중계장치에 의한 중계시설을 통하여 증인신문을 하는 경우에 준용한다.', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (134, '제84조의6(심리의 비공개)', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (135, '제84조의7(중계시설의 동석 등)', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (136, '제84조의8(증인을 위한 배려)', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (137, '제84조의9(차폐시설 등)', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (138, '제84조의10(증인지원시설의 설치 및 운영)', 14);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (139, '제85조(감정유치장의 기재사항 등)', 15);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (140, '제86조(간수의 신청방법) 법 제172조제5항의 규정에 의한 신청은 피고인의 간수를 필요로 하는 사유를 명시하여 서면으로 하여야 한다. <개정 1996.12.3>', 15);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (141, '제87조(비용의 지급)', 15);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (142, '제88조(준용규정) 구속에 관한 규정은 이 규칙에 특별한 규정이 없는 경우에는 감정하기 위한 피고인의 유치에 이를 준용한다. 다만, 보석에 관한 규정은 그러하지 아니하다.', 15);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (143, '제89조(감정허가장의 기재사항)', 15);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (144, '제89조의2(감정자료의 제공) 재판장은 필요하다고 인정하는 때에는 감정인에게 소송기록에 있는 감정에 참고가 될 자료를 제공할 수 있다.', 15);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (145, '제89조의3(감정서의 설명)', 15);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (146, '제90조(준용규정) 제12장의 규정은 구인에 관한 규정을 제외하고는 감정, 통역과 번역에 이를 준용한다. <개정 2021.10.29>', 15);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (147, '제91조(증거보전처분을 하여야 할 법관)', 16);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (148, '제92조(청구의 방식)', 16);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (149, '제92조의2(듣거나 말하는 데 장애가 있는 사람을 위한 비용 등) 듣거나 말하는 데 장애가 있는 사람을 위한 통역ㆍ속기ㆍ녹음ㆍ녹화 등에 드는 비용은 국고에서 부담하고, 형사소송법 제186조부터 제194조까지에 따라 피고인 등에게 부담하게 할 소송비용에 산입하지 아니한다.', 17);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (150, '제93조(영장청구의 방식)', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (151, '제94조(영장의 방식) 검사의 청구에 의하여 발부하는 영장에는 그 영장을 청구한 검사의 성명과 그 검사의 청구에 의하여 발부한다는 취지를 기재하여야 한다. <개정 1996.12.3>', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (152, '제95조(체포영장청구서의 기재사항) 체포영장의 청구서에는 다음 각 호의 사항을 기재하여야 한다.', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (153, '제95조의2(구속영장청구서의 기재사항) 구속영장의 청구서에는 다음 각 호의 사항을 기재하여야 한다.', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (154, '제96조(자료의 제출등)', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (155, '제96조의2(체포의 필요) 체포영장의 청구를 받은 판사는 체포의 사유가 있다고 인정 되는 경우에도 피의자의 연령과 경력, 가족관계나 교우관계, 범죄의 경중 및 태양 기타 제반 사정에 비추어 피의자가 도망할 염려가 없고 증거를 인멸할 염려가 없는 등 명백히 체포의 필요가 없다고 인정되는 때에는 체포영장의 청구를 기각하여야 한다.', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (156, '제96조의3(인치ㆍ구금할 장소의 변경) 검사는 체포영장을 발부받은 후 피의자를 체포하기 이전에 체포영장을 첨부하여 판사에게 인치ㆍ구금할 장소의 변경을 청구할 수 있다.', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (157, '제96조의4(체포영장의 갱신) 검사는 체포영장의 유효기간을 연장할 필요가 있다고 인정하는 때에는 그 사유를 소명하여 다시 체포영장을 청구하여야 한다.', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (158, '제96조의5(영장전담법관의 지정) 지방법원 또는 지원의 장은 구속영장청구에 대한 심사를 위한 전담법관을 지정할 수 있다.', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (159, '제96조의6 삭제 <2007.10.29>', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (160, '제96조의7 삭제 <2007.10.29>', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (161, '제96조의8 삭제 <2007.10.29>', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (162, '제96조의9 삭제 <2007.10.29>', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (163, '제96조의10 삭제 <2007.10.29>', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (164, '제96조의11(구인 피의자의 유치등)', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (165, '제96조의12(심문기일의 지정, 통지)', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (166, '제96조의13(피의자의 심문절차)', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (167, '제96조의14(심문의 비공개) 피의자에 대한 심문절차는 공개하지 아니한다. 다만, 판사는 상당하다고 인정하는 경우에는 피의자의 친족, 피해자 등 이해관계인의 방청을 허가할 수 있다.', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (168, '제96조의15(심문장소) 피의자의 심문은 법원청사내에서 하여야 한다. 다만, 피의자가 출석을 거부하거나 질병 기타 부득이한 사유로 법원에 출석할 수 없는 때에는 경찰서, 구치소 기타 적당한 장소에서 심문할 수 있다.', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (169, '제96조의16(심문기일의 절차)', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (170, '제96조의17 삭제 <2007.10.29>', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (171, '제96조의18(처리시각의 기재) 구속영장을 청구받은 판사가 피의자심문을 한 경우 법원사무관등은 구속영장에 구속영장청구서ㆍ수사관계서류 및 증거물을 접수한 시각과 이를 반환한 시각을 기재하여야 한다. 다만, 체포된 피의자 외의 피의자에 대하여는 그 반환 시각을 기재한다.', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (172, '제96조의19(영장발부와 통지)', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (173, '제96조의20(변호인의 접견 등)', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (174, '제96조의21(구속영장청구서 및 소명자료의 열람)', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (175, '제96조의22(심문기일의 변경) 판사는 지정된 심문기일에 피의자를 심문할 수 없는 특별한 사정이 있는 경우에는 그 심문기일을 변경할 수 있다.', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (176, '제97조(구속기간연장의 신청)', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (177, '제98조(구속기간연장기간의 계산) 구속기간연장허가결정이 있은 경우에 그 연장기간은 법 제203조의 규정에 의한 구속기간만료 다음날로부터 기산한다.', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (178, '제99조(재체포ㆍ 재구속영장의 청구)', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (179, '제100조(준용규정)', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (180, '제101조(체포ㆍ구속적부심청구권자의 체포ㆍ구속영장등본 교부청구등) 구속영장이 청구되거나 체포 또는 구속된 피의자, 그 변호인, 법정대리인, 배우자, 직계친족, 형제자매나 동거인 또는 고용주는 긴급체포서, 현행범인체포서, 체포영장, 구속영장 또는 그 청구서를 보관하고 있는 검사, 사법경찰관 또는 법원사무관등에게 그 등본의 교부를 청구할 수 있다. <개정 1989.6.7, 1996.12.3, 1997.12.31, 2007.10.29>', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (181, '제102조(체포ㆍ구속적부심사청구서의 기재사항) 체포 또는 구속의 적부심사청구서에는 다음 사항을 기재하여야 한다. <개정 1996.12.3, 2007.10.29>', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (182, '제103조 삭제 <2007.10.29>', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (183, '제104조(심문기일의 통지 및 수사관계서류 등의 제출)', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (184, '제104조의2(준용규정) 제96조의21의 규정은 체포ㆍ구속의 적부심사를 청구한 피의자의 변호인에게 이를 준용한다.', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (185, '제105조(심문기일의 절차)', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (186, '제106조(결정의 기한) 체포 또는 구속의 적부심사청구에 대한 결정은 체포 또는 구속된 피의자에 대한 심문이 종료된 때로부터 24시간 이내에 이를 하여야 한다. <개정 1996.12.3>', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (187, '제107조(압수, 수색, 검증 영장청구서의 기재사항)', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (188, '제108조(자료의 제출)', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (189, '제109조(준용규정) 제58조, 제62조의 규정은 검사 또는 사법경찰관의 압수, 수색에 제64조, 제65조의 규정은 검사 또는 사법경찰관의 검증에 각 이를 준용한다.', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (190, '제110조(압수, 수색, 검증의 참여) 검사 또는 사법경찰관이 압수, 수색, 검증을 함에는 법 제243조에 규정한 자를 각 참여하게 하여야 한다.', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (191, '제111조(제1회 공판기일 전 증인신문청구서의 기재사항) 법 제221조의2에 따른 증인신문 청구서에는 다음 각 호의 사항을 기재하여야 한다.', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (192, '제112조(증인신문등의 통지) 판사가 법 제221조의2에 따른 증인신문을 실시할 경우에는 피고인, 피의자 또는 변호인에게 신문기일과 장소 및 증인신문에 참여할 수 있다는 취지를 통지하여야 한다. <개정 2007.10.29>', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (193, '제113조(감정유치청구서의 기재사항) 법 제221조의3에 따른 감정유치청구서에는 다음 각호의 사항을 기재하여야 한다. <개정 2007.10.29>', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (194, '제114조(감정에 필요한 처분허가청구서의 기재사항) 법 제221조의4의 규정에 의한 처분허가청구서에는 다음 각호의 사항을 기재하여야 한다.', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (195, '제115조(준용규정) 제85조, 제86조 및 제88조의 규정은 법 제221조의3에 규정한 유치처분에, 제89조의 규정은 법 제221조의4에 규정한 허가장에 각 이를 준용한다.', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (196, '제116조(고소인의 신분관계 자료제출)', 19);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (197, '제117조(공소장의 기재요건)', 20);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (198, '제118조(공소장의 첨부서류)', 20);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (199, '제119조 삭제 <2007.10.29>', 20);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (200, '제120조(재정신청인에 대한 통지) 법원은 재정신청서를 송부받은 때에는 송부받은 날로부터 10일 이내에 피의자 이외에 재정신청인에게도 그 사유를 통지하여야 한다.', 20);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (201, '제121조(재정신청의 취소방식 및 취소의 통지)', 20);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (202, '제122조(재정신청에 대한 결정과 이유의 기재) 법 제262조제2항제2호에 따라 공소제기를 결정하는 때에는 죄명과 공소사실이 특정될 수 있도록 이유를 명시하여야 한다.', 20);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (203, '제122조의2(국가에 대한 비용부담의 범위) 법 제262조의3제1항에 따른 비용은 다음 각 호에 해당하는 것으로 한다. <개정 2020.6.26>', 20);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (204, '제122조의3(국가에 대한 비용부담의 절차)', 20);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (205, '제122조의4(피의자에 대한 비용지급의 범위)', 20);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (206, '제122조의5(피의자에 대한 비용지급의 절차)', 20);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (207, '제123조(제1회공판기일소환장의 송달시기) 피고인에 대한 제1회 공판기일소환장은 법 제266조의 규정에 의한 공소장부본의 송달전에는 이를 송달하여서는 아니된다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (208, '제123조의2(공소제기 후 검사가 보관하는 서류 등의 열람ㆍ등사 신청) 법 제266조의3제1항의 신청은 다음 사항을 기재한 서면으로 하여야 한다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (209, '제123조의3(영상녹화물과 열람ㆍ등사) 법 제221조ㆍ법 제244조의2에 따라 작성된 영상녹화물에 대한 법 제266조의3의 열람ㆍ등사는 원본과 함께 작성된 부본에 의하여 이를 행할 수 있다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (210, '제123조의4(법원에 대한 열람ㆍ등사 신청)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (211, '제123조의5(공판준비기일 또는 공판기일에서의 열람ㆍ등사)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (212, '제123조의6(재판의 고지 등에 관한 특례) 법원은 서면 이외에 전화ㆍ모사전송ㆍ전자우편ㆍ휴대전화 문자전송 그 밖에 적당한 방법으로 검사ㆍ피고인 또는 변호인에게 공판준비와 관련된 의견을 요청하거나 결정을 고지할 수 있다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (213, '제123조의7(쟁점의 정리)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (214, '제123조의8(심리계획의 수립)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (215, '제123조의9(기일외 공판준비)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (216, '제123조의10(공판준비기일의 변경) 검사ㆍ피고인 또는 변호인은 부득이한 사유로 공판준비기일을 변경할 필요가 있는 때에는 그 사유와 기간 등을 구체적으로 명시하여 공판준비기일의 변경을 신청할 수 있다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (217, '제123조의11(공판준비기일이 지정된 사건의 국선변호인 선정)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (218, '제123조의12(공판준비기일조서)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (219, '제123조의13(비디오 등 중계장치 등에 의한 공판준비기일)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (220, '제124조(공판개정시간의 구분 지정) 재판장은 가능한 한 각 사건에 대한 공판개정시간을 구분하여 지정하여야 한다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (221, '제124조의2(일괄 기일 지정과 당사자의 의견 청취) 재판장은 법 제267조의2제3항의 규정에 의하여 여러 공판기일을 일괄하여 지정할 경우에는 검사, 피고인 또는 변호인의 의견을 들어야 한다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (222, '제125조(공판기일 변경신청) 법 제270조제1항에 규정한 공판기일 변경신청에는 공판기일의 변경을 필요로 하는 사유와 그 사유가 계속되리라고 예상되는 기간을 명시하여야 하며 진단서 기타의 자료로써 이를 소명하여야 한다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (223, '제125조의2(변론의 방식) 공판정에서의 변론은 구체적이고 명료하게 하여야 한다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (224, '제126조(피고인의 대리인의 대리권) 피고인이 법 제276조 단서 또는 법 제277조에 따라 공판기일에 대리인을 출석하게 할 때에는 그 대리인에게 대리권을 수여한 사실을 증명하는 서면을 법원에 제출하여야 한다. <개정 2007.10.29>', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (225, '제126조의2(신뢰관계 있는 자의 동석)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (226, '제126조의3(불출석의 허가와 취소)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (227, '제126조의4(출석거부의 통지) 법 제277조의2의 사유가 발생하는 경우에는 교도소장은 즉시 그 취지를 법원에 통지하여야 한다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (228, '제126조의5(출석거부에 관한 조사)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (229, '제126조의6(피고인 또는 검사의 출석없이 공판절차를 진행한다는 취지의 고지) 법 제277조의2의 규정에 의하여 피고인의 출석없이 공판절차를 진행하는 경우 또는 법 제278조의 규정에 의하여 검사의 2회 이상 불출석으로 공판절차를 진행하는 경우에는 재판장은 공판정에서 소송관계인에게 그 취지를 고지하여야 한다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (230, '제126조의7(전문심리위원의 지정) 법원은 전문심리위원규칙에 따라 정해진 전문심리위원 후보자 중에서 전문심리위원을 지정하여야 한다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (231, '제126조의8(기일 외의 전문심리위원에 대한 설명 등의 요구와 통지) 재판장이 기일 외에서 전문심리위원에 대하여 설명 또는 의견을 요구한 사항이 소송관계를 분명하게 하는 데 중요한 사항일 때에는 법원사무관 등은 검사, 피고인 또는 변호인에게 그 사항을 통지하여야 한다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (232, '제126조의9(서면의 사본 송부) 전문심리위원이 설명이나 의견을 기재 한 서면을 제출한 경우에는 법원사무관등은 검사, 피고인 또는 변호인에게 그 사본을 보내야 한다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (233, '제126조의10(전문심리위원에 대한 준비지시)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (234, '제126조의11(증인신문기일에서의 재판장의 조치) 재판장은 전문심리위원의 말이 증인의 증언에 영향을 미치지 않게 하기 위하여 필요하다고 인정할 때에는 직권 또는 검사, 피고인 또는 변호인의 신청에 따라 증인의 퇴정 등 적절한 조치를 취할 수 있다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (235, '제126조의12(조서의 기재)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (236, '제126조의13(전문심리위원 참여 결정의 취소 신청방식 등)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (237, '제126조의14(수명법관 등의 권한) 수명법관 또는 수탁판사가 소송절차를 진행하는 경우에는 제126조의10부터 제126조의12까지의 규정에 따른 재판장의 직무는 그 수명법관이나 수탁판사가 행한다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (238, '제127조(피고인에 대한 진술거부권 등의 고지) 재판장은 법 제284조에 따른 인정신문을 하기 전에 피고인에게 진술을 하지 아니하거나 개개의 질문에 대하여 진술을 거부할 수 있고, 이익 되는 사실을 진술할 수 있음을 알려 주어야 한다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (239, '제127조의2(피고인의 모두진술)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (240, '제128조 삭제 <2007.10.29>', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (241, '제129조 삭제 <2007.10.29>', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (242, '제130조 삭제 <2007.10.29>', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (243, '제131조(간이공판절차의 결정전의 조치) 법원이 법 제286조의2의 규정에 의한 결정을 하고자 할 때에는 재판장은 이미 피고인에게 간이공판절차의 취지를 설명하여야 한다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (244, '제132조(증거의 신청)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (245, '제132조의2(증거신청의 방식)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (246, '제132조의3(수사기록의 일부에 대한 증거신청방식)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (247, '제132조의4(보관서류에 대한 송부요구)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (248, '제132조의5(민감정보 등의 처리)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (249, '제133조(증거신청의 순서) 증거신청은 검사가 먼저 이를 한 후 다음에 피고인 또는 변호인이 이를 한다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (250, '제134조(증거결정의 절차)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (251, '제134조의2(영상녹화물의 조사 신청)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (252, '제134조의3(제3자의 진술과 영상녹화물)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (253, '제134조의4(영상녹화물의 조사)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (254, '제134조의5(기억 환기를 위한 영상녹화물의 조사)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (255, '제134조의6(증거서류에 대한 조사방법)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (256, '제134조의7(컴퓨터용디스크 등에 기억된 문자정보 등에 대한 증거조사)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (257, '제134조의8(음성ㆍ영상자료 등에 대한 증거조사)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (258, '제134조의9(준용규정) 도면ㆍ사진 그 밖에 정보를 담기 위하여 만들어진 물건으로서 문서가 아닌 증거의 조사에 관하여는 특별한 규정이 없으면 법 제292조, 법 제292조의2의 규정을 준용한다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (259, '제134조의10(피해자등의 의견진술)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (260, '제134조의11(의견진술에 갈음한 서면의 제출)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (261, '제134조의12(의견진술ㆍ의견진술에 갈음한 서면) 제134조의10제1항에 따른 진술과 제134조의11제1항에 따른 서면은 범죄사실의 인정을 위한 증거로 할 수 없다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (262, '제134조의13(금전 공탁에 대한 피해자등의 의견 청취)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (263, '제134조의14(피해자 등의 공판기록 열람ㆍ등사)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (264, '제135조(자백의 조사 시기) 법 제312조 및 법 제313조에 따라 증거로 할 수 있는 피고인 또는 피고인 아닌 자의 진술을 기재한 조서 또는 서류가 피고인의 자백 진술을 내용으로 하는 경우에는 범죄사실에 관한 다른 증거를 조사한 후에 이를 조사하여야 한다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (265, '제135조의2(증거조사에 관한 이의신청의 사유) 법 제296조제1항의 규정에 의한 이의신청은 법령의 위반이 있거나 상당하지 아니함을 이유로 하여 이를 할 수 있다. 다만, 법 제295조의 규정에 의한 결정에 대한 이의신청은 법령의 위반이 있음을 이유로 하여서만 이를 할 수 있다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (266, '제136조(재판장의 처분에 대한 이의신청의 사유) 법 제304조제1항의 규정에 의한 이의신청은 법령의 위반이 있음을 이유로 하여서만 이를 할 수 있다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (267, '제137조(이의신청의 방식과 시기) 제135조의2 및 제136조에 규정한 이의신청(이하 이 절에서는 "이의신청"이라 한다)은 개개의 행위, 처분 또는 결정시마다 그 이유를 간결하게 명시하여 즉시 이를 하여야 한다. <개정 2025.2.28>', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (268, '제138조(이의신청에 대한 결정의 시기) 이의신청에 대한 법 제296조제2항 또는 법 제304조제2항의 결정은 이의신청이 있은 후 즉시 이를 하여야 한다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (269, '제139조(이의신청에 대한 결정의 방식)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (270, '제140조(중복된 이의신청의 금지) 이의신청에 대한 결정에 의하여 판단이 된 사항에 대하여는 다시 이의신청을 할 수 없다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (271, '제140조의2(피고인신문의 방법) 피고인을 신문함에 있어서 그 진술을 강요하거나 답변을 유도하거나 그 밖에 위압적ㆍ모욕적 신문을 하여서는 아니 된다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (272, '제140조의3(재정인의 퇴정) 재판장은 피고인이 어떤 재정인의 앞에서 충분한 진술을 할 수 없다고 인정한 때에는 그 재정인을 퇴정하게 하고 진술하게 할 수 있다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (273, '제141조(석명권등)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (274, '제142조(공소장의 변경)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (275, '제143조(공판절차정지후의 공판절차의 갱신) 공판개정후 법 제306조제1항의 규정에 의하여 공판절차가 정지된 경우에는 그 정지사유가 소멸한 후의 공판기일에 공판절차를 갱신하여야 한다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (276, '제144조(공판절차의 갱신절차)', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (277, '제145조(변론시간의 제한) 재판장은 필요하다고 인정하는 경우 검사, 피고인 또는 변호인의 본질적인 권리를 해치지 아니하는 범위내에서 법 제302조 및 법 제303조의 규정에 의한 의견진술의 시간을 제한할 수 있다.', 22);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (278, '제146조(판결서의 작성) 변론을 종결한 기일에 판결을 선고하는 경우에는 선고 후 5일 내에 판결서를 작성하여야 한다.', 23);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (279, '제147조(판결의 선고)', 23);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (280, '제147조의2(보호관찰의 취지등의 고지, 보호처분의 기간)', 23);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (281, '제147조의3(보호관찰의 판결등의 통지)', 23);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (282, '제147조의4(보호관찰등의 성적보고) 보호관찰등을 명한 판결을 선고한 법원은 보호관찰등의 기간 중 보호관찰소장에게 보호관찰 등을 받고 있는 자의 성적에 관하여 보고를 하게 할 수 있다.', 23);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (283, '제148조(피고인에 대한 판결서 등본 등의 송달)', 23);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (284, '제149조(집행유예취소청구의 방식) 법 제335조제1항의 규정한 형의 집행유예취소청구는 취소의 사유를 구체적으로 기재한 서면으로 하여야 한다.', 23);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (285, '제149조의2(자료의 제출) 형의 집행유예취소청구를 한 때에는 취소의 사유가 있다는 것을 인정할 수 있는 자료를 제출하여야 한다.', 23);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (286, '제149조의3(청구서부본의 제출과 송달)', 23);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (287, '제150조(출석명령) 형의 집행유예취소청구를 받은 법원은 법 제335조제2항의 규정에 의한 의견을 묻기 위하여 필요하다고 인정할 경우에는 집행유예의 선고를 받은 자 또는 그 대리인의 출석을 명할 수 있다. <개정 1996.12.3>', 23);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (288, '제150조의2(준용규정) 제149조 내지 제150조의 규정은 형법 제61조제2항의 규정에 의하여 유예한 형을 선고하는 경우에 준용한다.', 23);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (289, '제151조(경합범중 다시 형을 정하는 절차 등에의 준용) 제149조, 제149조의2 및 제150조의 규정은 법 제336조에 규정한 절차에 이를 준용한다. <개정 1996.12.3>', 23);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (290, '제152조(재소자의 상소장등의 처리)', 25);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (291, '제153조(상소의 포기 또는 취하에 관한 동의서의 제출)', 25);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (292, '제154조(상소의 포기 또는 취하의 효력을 다투는 절차)', 25);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (293, '제155조(항소이유서, 답변서의 기재) 항소이유서 또는 답변서에는 항소이유 또는 답변내용을 구체적으로 간결하게 명시하여야 한다.', 26);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (294, '제156조(항소이유서, 답변서의 부본제출) 항소이유서 또는 답변서에는 상대방의 수에 2를 더한 수의 부본을 첨부하여야 한다. <개정 1996.12.3>', 26);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (295, '제156조의2(국선변호인의 선정 및 소송기록접수통지)', 26);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (296, '제156조의3(항소이유 및 답변의 진술)', 26);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (297, '제156조의4(쟁점의 정리) 법원은 항소이유와 답변에 터잡아 해당 사건의 사실상ㆍ법률상 쟁점을 정리하여 밝히고 그 증명되어야 하는 사실을 명확히 하여야 한다.', 26);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (298, '제156조의5(항소심과 증거조사)', 26);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (299, '제156조의6(항소심에서의 피고인 신문)', 26);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (300, '제156조의7(항소심에서의 의견진술)', 26);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (301, '제157조(환송 또는 이송판결이 확정된 경우 소송기록 등의 송부) 법 제366조 또는 법 제367조 본문의 규정에 의한 환송 또는 이송판결이 확정된 경우에는 다음 각 호의 규정에 의하여 처리하여야 한다. <개정 1996.12.3, 2021.1.29>', 26);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (302, '제158조(변호인 선임의 효력) 원심법원에서의 변호인 선임은 법 제366조 또는 법 제367조의 규정에 의한 환송 또는 이송이 있은 후에도 효력이 있다.', 26);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (303, '제159조(준용규정) 제2편중 공판에 관한 규정은 항소법원의 공판절차에 이를 준용한다.', 26);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (304, '제160조(상고이유서, 답변서의 부본 제출) 상고이유서 또는 답변서에는 상대방의 수에 4를 더한 수의 부본을 첨부하여야 한다. <개정 1996.12.3>', 27);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (305, '제161조(피고인에 대한 공판기일의 통지등)', 27);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (306, '제161조의2(참고인 의견서 제출)', 27);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (307, '제162조(대법관전원합의체사건에 관하여 부에서 할 수 있는 재판) 대법관전원합의체에서 본안재판을 하는 사건에 관하여 구속, 구속기간의 갱신, 구속의 취소, 보석, 보석의 취소, 구속의 집행정지, 구속의 집행정지의 취소를 함에는 대법관 3인 이상으로써 구성된 부에서 재판할 수 있다. <개정 1988.3.23>', 27);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (308, '제163조(판결정정신청의 통지) 법 제400조제1항에 규정한 판결정정의 신청이 있는 때에는 즉시 그 취지를 상대방에게 통지하여야 한다.', 27);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (309, '제164조(준용규정) 제155조, 제156조의2, 제157조제1호, 제2호의 규정은 상고심의 절차에 이를 준용한다. <개정 1996.12.3>', 27);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (310, '제165조(항고법원의 결정등본의 송부) 항고법원이 법 제413조 또는 법 제414조에 규정한 결정을 한 때에는 즉시 그 결정의 등본을 원심법원에 송부하여야 한다.', 28);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (311, '제166조(재심청구의 방식) 재심의 청구를 함에는 재심청구의 취지 및 재심청구의 이유를 구체적으로 기재한 재심청구서에 원판결의 등본 및 증거자료를 첨부하여 관할법원에 제출하여야 한다.', 30);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (312, '제167조(재심청구 취하의 방식)', 30);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (313, '제168조(준용규정) 제152조의 규정은 재심의 청구와 그 취하에 이를 준용한다.', 30);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (314, '제169조(청구의 경합과 공판절차의 정지)', 30);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (315, '제170조(서류 등의 제출) 검사는 약식명령의 청구와 동시에 약식명령을 하는데 필요한 증거서류 및 증거물을 법원에 제출하여야 한다.', 31);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (316, '제171조(약식명령의 시기) 약식명령은 그 청구가 있은 날로부터 14일내에 이를 하여야 한다.', 31);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (317, '제172조(보통의 심판)', 31);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (318, '제173조(준용규정) 제153조의 규정은 정식재판청구의 취하에 이를 준용한다.', 31);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (319, '제174조(소송비용의 집행면제 등의 신청 등)', 32);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (320, '제175조(소송비용의 집행면제 등의 신청 등의 통지) 법원은 제174조제1항에 규정한 신청 또는 그 취하의 서면을 제출받은 경우에는 즉시 그 취지를 검사에게 통지하여야 한다.', 32);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (321, '제176조(신청 기타 진술의 방식)', 33);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (322, '제177조(재소자의 신청 기타 진술) 교도소장, 구치소장 또는 그 직무를 대리하는 자는 교도소 또는 구치소에 있는 피고인이나 피의자가 법원 또는 판사에 대한 신청 기타 진술에 관한 서면을 작성하고자 할 때에는 그 편의를 도모하여야 하고, 특히 피고인이나 피의자가 그 서면을 작성할 수 없을 때에는 법 제344조제2항의 규정에 준하는 조치를 취하여야 한다.', 33);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (323, '제177조의2(기일 외 주장 등의 금지)', 33);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (324, '제178조(영장의 유효기간) 영장의 유효기간은 7일로 한다. 다만, 법원 또는 법관이 상당하다고 인정하는 때에는 7일을 넘는 기간을 정할 수 있다.', 33);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (325, '제179조 삭제 <2016.11.29>', 33);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (326, '제1조(목적) 이 규칙은 형사소송비용등에관한법률(이하 "법"이라 한다)에 의하여 위임된 사항 및 기타 법원의 형사절차에서 지급하는 비용에 관하여 필요한 사항을 규정함을 목적으로 한다.', 34);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (327, '제2조(증인등의 일당) 법 제3조제2항, 제6조의 규정에 의한 증인ㆍ감정인ㆍ통역인 또는 번역인(이하 "증인등"이라 한다)의 일당은 매년 예산의 범위안에서 대법관회의에서 정한다.', 34);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (328, '제3조(증인등의 여비ㆍ숙박료)', 34);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (329, '제4조(증인등의 국외여행의 경우)', 34);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (330, '제5조(국선변호인의 일당등)', 34);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (331, '제6조(국선변호인의 보수)', 34);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (332, '제1조(목적) 이 규정은 「형사사법절차에서의 전자문서 이용 등에 관한 법률」에 따른 법원의 형사사법업무 전자화의 효율적인 추진을 위하여 법원행정처에 형사전자소송(위 법에 따라 전자화된 형태의 법원의 형사사법절차를 가리킨다, 이하 이 규칙에서 같다) 추진단(이하 "추진단"이라 한다)을 설치하고, 이를 운영함에 필요한 사항을 정함을 목적으로 한다.', 35);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (333, '제2조(추진단의 구성)', 35);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (334, '제3조(사무) 추진단은 다음 각 호의 사항을 담당한다.', 35);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (335, '제4조(협조요청 등)', 35);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (336, '제5조(조사연구위탁 등)', 35);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (337, '제6조(위임사항) 추진단의 운영 및 그 밖에 필요한 사항은 법원행정처내규로 정한다.', 35);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (338, '제1조(목적) 이 영은 「아동학대범죄의 처벌 등에 관한 특례법」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 36);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (339, '제2조(피해아동 보호의 원칙) 검사, 사법경찰관리, 보호관찰관, 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ도지사ㆍ특별자치도지사(이하 "시ㆍ도지사"라 한다), 시장ㆍ군수ㆍ구청장(자치구의 구청장을 말한다. 이하 같다), 「아동복지법」 제22조제4항에 따른 아동학대전담공무원(이하 "아동학대전담공무원"이라 한다), 같은 법 제45조에 따른 아동보호전문기관(이하 "아동보호전문기관"이라 한다)의 장과 그 직원 등은 「아동학대범죄의 처벌 등에 관한 특례법」(이하 "법"이라 한다)에 따른 처분 또는 청구 등을 할 경우에는 피해아동, 피해아동의 형제자매인 아동 및 피해아동과 동거하는 아동(이하 "피해아동등"이라 한다)의 안전과 보호 및 이익을 최우선으로 고려해야 한다. <개정 2020.9.29>', 36);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (340, '제3조(아동학대행위자의 재범 예방을 위한 시책 마련) 법무부장관은 법 제8조제1항에 따른 수강명령과 이수명령의 실시에 필요한 프로그램의 개발 및 관련 전문인력의 양성 등 아동학대행위자의 재범 예방을 위한 시책을 마련하여야 한다.', 36);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (341, '제4조(사건관리회의)', 36);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (342, '제5조(피해아동등의 의견 청취 등)', 36);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (343, '제5조의2(연고자 등의 기준) 법 제12조제1항제5호에 따른 연고자 등은 피해아동등의 친족이거나 피해아동등을 보호ㆍ양육한 이력이 있는 등 피해아동등과 특별한 연고가 있는 사람 중 피해아동등을 인도받기를 희망하는 사람이어야 한다.', 36);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (344, '제5조의3(피해아동등을 연고자 등에게 인도하는 절차 등)', 36);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (345, '제6조(아동학대전담공무원 등에 대한 교육) 법 제55조에 따라 아동학대전담공무원, 사법경찰관리 및 아동보호전문기관의 종사자에 대해 실시하는 교육에는 다음 각 호의 사항이 포함되어야 한다. <개정 2020.9.29, 2021.5.18>', 36);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (346, '제7조(민감정보 및 고유식별정보의 처리)', 36);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (347, '제8조(과태료의 부과기준) 법 제63조제1항에 따른 과태료의 부과기준은 별표 2와 같다. <개정 2025.6.20>', 36);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (348, '제1조(목적) 이 규칙은 해양경찰청 소속 경찰공무원인 사법경찰관리가 「형사소송법」 및 「검사와 사법경찰관의 상호협력과 일반적 수사준칙에 관한 규정」 등 수사 관계 법령에 따라 수사를 하는 데 필요한 사항을 규정함을 목적으로 한다.', 37);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (349, '제2조(인권 보호 및 적법절차의 준수)', 37);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (350, '제3조(협력의 방식 등)', 38);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (351, '제4조(중요사건 협력절차)', 38);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (352, '제5조(소재수사에 관한 협력)', 38);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (353, '제6조(시찰조회 요청에 관한 협력)', 38);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (354, '제7조(검사와의 협의 등)', 38);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (355, '제8조(사법경찰관리의 상호협력)', 38);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (356, '제9조(접수 전 점검 및 조치)', 40);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (357, '제10조(회피) 사법경찰관리는 수사준칙 제11조에 따라 수사를 회피하려는 경우에는 별지 제8호서식의 회피신청서를 소속해양경찰관서장에게 제출해야 한다.', 40);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (358, '제11조(수사 진행상황의 통지)', 40);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (359, '제12조(변호인의 피의자신문 참여)', 40);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (360, '제13조(신문 중 변호인 참여 제한)', 40);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (361, '제14조(사건관계인에 대한 적용) 사건관계인에 대한 조사ㆍ면담 시 변호인의 참여에 관하여는 제12조 및 제13조를 준용한다.', 40);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (362, '제15조(직무 관할) 사법경찰관리는 소속된 해양경찰관서의 관할구역에서 직무를 수행한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 관할구역이 아닌 곳에서도 그 직무를 수행할 수 있다.', 40);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (363, '제16조(사건의 단위) 법 제11조에 따른 관련사건은 1건으로 처리한다. 다만, 분리수사를 하는 경우에는 그렇지 않다.', 40);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (364, '제17조(심사관)', 40);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (365, '제18조(수사의 개시)', 41);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (366, '제19조(입건 전 조사)', 41);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (367, '제20조(불입건 결정 통지)', 41);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (368, '제21조(고소ㆍ고발의 수리)', 41);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (369, '제22조(고소인ㆍ고발인 진술조서 등)', 41);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (370, '제23조(고소의 대리 등)', 41);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (371, '제24조(고소ㆍ고발사건의 수사기간)', 41);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (372, '제25조(고소ㆍ고발 취소 등에 따른 조치)', 41);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (373, '제26조(변사사건 발생사실 통보)', 41);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (374, '제27조(변사자의 검시ㆍ검증)', 41);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (375, '제28조(검시ㆍ검증조서 등)', 41);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (376, '제29조(검시의 주의사항) 사법경찰관리는 검시할 때에는 다음 각 호의 사항에 주의해야 한다.', 41);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (377, '제30조(검시와 참여자) 사법경찰관리는 검시에 특별한 지장이 없다고 인정하면 변사자의 가족ㆍ친족, 이웃사람ㆍ친구, 시ㆍ군ㆍ구ㆍ읍ㆍ면ㆍ동의 공무원이나 그 밖에 필요하다고 인정하는 사람을 검시에 참여시켜야 한다.', 41);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (378, '제31조(사체의 인도)', 41);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (379, '제32조(검사 이송 사건의 처리) 사법경찰관은 수사준칙 제18조에 따라 검사로부터 사건을 이송받은 경우에는 지체 없이 접수하여 처리한다.', 41);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (380, '제33조(고위공직자범죄등 인지 통보) 사법경찰관은 「고위공직자범죄수사처 설치 및 운영에 관한 법률」 제24조제2항에 따라 고위공직자범죄등 인지 사실을 통보하는 경우에는 별지 제19호서식의 고위공직자범죄등 인지통보서에 따른다.', 41);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (381, '제34조(출석요구) 수사준칙 제19조제3항 본문 또는 같은 조 제6항에 따라 피의자 또는 피의자 외의 사람에게 출석요구를 하려는 경우에는 별지 제20호서식 또는 별지 제21호서식의 출석요구서에 따른다.', 43);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (382, '제35조(수사상 임의동행) 사법경찰관리는 수사준칙 제20조에 따른 임의동행 고지를 하고 임의동행한 경우에는 별지 제22호서식의 임의동행 동의서를 작성하여 사건기록에 편철하거나 별도로 보관해야 한다.', 43);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (383, '제36조(심야조사 제한)', 43);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (384, '제37조(장시간 조사 제한) 사법경찰관리는 피의자나 사건관계인으로부터 수사준칙 제22조제1항제1호에 따라 조서 열람을 위한 조사 연장을 요청받은 경우에는 별지 제23호서식의 조사연장 요청서를 제출받아야 한다.', 43);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (385, '제38조(신뢰관계인 동석)', 43);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (386, '제39조(조서와 진술서)', 43);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (387, '제40조(수사과정의 기록) 사법경찰관리는 수사준칙 제26조제1항에 따라 조사 과정의 진행경과를 별도의 서면에 기록하는 경우에는 별지 제30호서식 또는 별지 제31호서식의 수사 과정 확인서에 따른다.', 43);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (388, '제41조(실황조사)', 43);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (389, '제42조(감정의 위촉) 사법경찰관은 법 제221조제2항에 따라 감정을 위촉하는 경우에는 별지 제33호서식의 감정위촉서에 따른다. 법 제221조의4에 따라 감정에 필요한 허가장을 발부받아 위촉하는 경우에도 또한 같다.', 43);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (390, '제43조(영상녹화)', 44);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (391, '제44조(영상녹화물의 제작 및 보관)', 44);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (392, '제45조(지명수배)', 45);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (393, '제46조(지명수배자 발견 시 조치)', 45);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (394, '제47조(지명통보) 사법경찰관리는 다음 각 호의 어느 하나에 해당하는 사람의 소재를 알 수 없을 때에는 지명통보를 할 수 있다.', 45);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (395, '제48조(지명통보자 발견 시 조치) 사법경찰관리는 제47조에 따라 지명통보된 사람(이하 "지명통보자"라 한다)을 발견한 때에는 지명통보자에게 지명통보된 사실, 범죄사실의 요지 및 지명통보한 해양경찰관서(이하 이 조 및 제49조에서 "통보관서"라 한다)를 고지하고, 발견된 날부터 1개월 이내에 통보관서에 출석해야 한다는 내용과 정당한 사유 없이 출석하지 않을 경우 지명수배되어 체포될 수 있다는 내용을 통지해야 한다.', 45);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (396, '제49조(지명수배ㆍ지명통보 해제) 사법경찰관리는 다음 각 호의 어느 하나에 해당하는 경우에는 즉시 지명수배 또는 지명통보를 해제해야 한다.', 45);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (397, '제50조(체포영장의 신청) 사법경찰관은 법 제200조의2제1항에 따라 체포영장을 신청하는 경우에는 별지 제36호서식의 체포영장 신청서에 따른다. 이 경우 현재 수사 중인 다른 범죄사실에 관하여 그 피의자에 대해 발부된 유효한 체포영장이 있는지를 확인해야 하며 해당사항이 있는 경우에는 그 사실을 체포영장 신청서에 적어야 한다.', 47);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (398, '제51조(긴급체포)', 47);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (399, '제52조(현행범인 체포 및 인수)', 47);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (400, '제53조(현행범인 석방)', 47);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (401, '제54조(구속영장의 신청) 수사준칙 제29조에 따른 구속영장 신청서는 별지 제44호서식부터 별지 제47호서식까지에 따른다.', 47);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (402, '제55조(체포ㆍ구속영장의 집행)', 47);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (403, '제56조(호송)', 47);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (404, '제57조(체포ㆍ구속 통지 등) 사법경찰관은 수사준칙 제33조제1항(같은 조 제3항에서 준용하는 경우를 포함한다)에 따라 체포ㆍ구속의 통지를 하는 경우에는 별지 제48호서식의 체포ㆍ긴급체포ㆍ현행범인체포ㆍ구속 통지서에 따른다.', 47);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (405, '제58조(체포ㆍ구속영장의 반환) 수사준칙 제35조제2항에 따른 영장반환서는 별지 제49호서식에 따른다.', 47);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (406, '제59조(피의자 접견 등 금지)', 47);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (407, '제60조(피의자 석방 및 통보)', 47);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (408, '제61조(구속의 취소)', 47);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (409, '제62조(구속의 집행정지)', 47);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (410, '제63조(압수ㆍ수색 또는 검증영장의 신청 등)', 48);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (411, '제64조(압수조서 등)', 48);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (412, '제65조(수색조서 및 수색증명서)', 48);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (413, '제66조(압수물의 환부 및 가환부)', 48);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (414, '제67조(압수물 보관)', 48);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (415, '제68조(압수물 폐기)', 48);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (416, '제69조(압수물 대가보관)', 48);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (417, '제70조(검증조서) 수사준칙 제43조에 따른 검증조서는 별지 제16호서식에 따른다.', 48);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (418, '제71조(증거보전 신청) 사법경찰관은 미리 증거를 보전하지 않으면 그 증거를 사용하기 곤란한 경우에는 별지 제81호서식의 증거보전 신청서를 작성하여 검사에게 법 제184조제1항에 따른 증거보전의 청구를 신청할 수 있다.', 49);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (419, '제72조(증인신문 신청) 사법경찰관은 범죄의 수사에 없어서는 안 되는 사실을 안다고 명백히 인정되는 사람이 출석 또는 진술을 거부하는 경우에는 별지 제82호서식의 증인신문 신청서를 작성하여 검사에게 법 제221조의2제1항에 따른 증인신문의 청구를 신청할 수 있다.', 49);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (420, '제73조(감정유치 및 감정처분허가 신청)', 49);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (421, '제74조(영장심의위원회) 사법경찰관은 법 제221조의5제1항에 따라 영장 청구 여부에 대한 심의를 신청하는 경우에는 「영장심의위원회 규칙」 제13조에 따라 관할 고등검찰청에 심의신청을 해야 한다.', 49);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (422, '제75조(시정조치요구의 이행)', 50);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (423, '제76조(징계요구 처리 결과 등 통보) 소속해양경찰관서장은 수사준칙 제46조제2항에 따라 징계요구의 처리 결과와 그 이유를 통보하는 경우에는 별지 제87호서식의 징계요구 처리결과 통보서에 따른다.', 50);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (424, '제77조(구제신청 고지의 확인) 수사준칙 제47조에 따른 고지 확인서는 별지 제88호서식에 따른다.', 50);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (425, '제78조(수사의 경합 시 기록 열람)', 51);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (426, '제79조(피해자 보호의 원칙)', 52);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (427, '제80조(신변보호)', 52);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (428, '제81조(피해자에 대한 정보 제공) 사법경찰관리는 피해자를 조사하는 경우 다음 각 호의 정보를 피해자에게 제공해야 한다. 다만, 피해자에 대한 조사를 하지 않는 경우에는 수사준칙 제51조제1항에 따른 결정(이송 결정은 제외한다)을 하기 전까지 정보를 제공해야 한다.', 52);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (429, '제82조(회복적 대화)', 52);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (430, '제83조(범죄피해의 평가) 사법경찰관리는 피해자의 피해 정도를 파악하고 보호ㆍ지원의 필요성을 판단하기 위해 범죄피해평가를 실시할 수 있으며, 일정한 자격을 갖춘 단체 또는 개인에게 이를 의뢰할 수 있다.', 52);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (431, '제84조(문서의 서식) 이 규칙에서 정한 서식 외에 단순하고 정형적인 사건의 수사 등에 사용하는 서식은 해양경찰청장이 정한다.', 53);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (432, '제85조(장부와 비치서류)', 53);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (433, '제86조(범죄통계원표) 사법경찰관리는 범죄를 수사한 경우에는 형사사법정보시스템을 이용하여 사건마다 범죄통계원표를 작성한다.', 53);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (434, '제87조(수사서류 열람ㆍ복사)', 53);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (435, '제88조(혼획ㆍ좌초ㆍ표류된 고래류의 처리)', 55);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (436, '제89조(보호대상 고래류의 통보) 사법경찰관은 혼획ㆍ좌초 또는 표류로 신고된 고래류가 「야생생물 보호 및 관리에 관한 법률」 제2조제3호에 따른 국제적 멸종위기종 또는 「해양생태계의 보전 및 관리에 관한 법률」 제2조제11호에 따른 해양보호생물로 확인되거나 의심되는 경우에는 그 사실을 각각 환경부장관 또는 해양수산부장관에게 즉시 통보해야 한다.', 55);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (437, '제90조(소년에 대한 조사)', 56);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (438, '제91조(장애인에 대한 조사) 사법경찰관리는 청각장애인 및 언어장애인이나 그 밖에 의사소통이 어려운 장애인을 조사하는 경우에는 직권으로 또는 장애인 본인, 보호자, 법정대리인 등의 신청에 따라 수화ㆍ문자통역을 제공하거나 의사소통을 도울 수 있는 사람을 참여시켜야 한다.', 56);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (439, '제92조(외국인에 대한 조사)', 56);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (440, '제93조(국제법의 준수) 사법경찰관리는 외국인 관련 범죄, 우리나라 국민의 국외범, 대사관ㆍ공사관에 관한 범죄 및 그 밖에 외국에 관한 범죄의 수사를 할 때에는 조약과 그 밖의 국제법에 위배되는 일이 없도록 유의해야 한다.', 56);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (441, '제94조(한미행정협정사건의 통보)', 56);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (442, '제95조(몰수ㆍ부대보전 신청) 사법경찰관은 관계 법령에 따라 검사에게 몰수ㆍ부대보전을 신청하는 경우에는 별지 제94호서식의 몰수ㆍ부대보전 신청서에 따른다.', 57);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (443, '제96조(추징보전의 신청)', 57);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (444, '제97조(장기사건 수사종결)', 59);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (445, '제98조(사건 이송)', 59);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (446, '제99조(수사 결과의 통지)', 59);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (447, '제100조(수사중지 결정)', 60);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (448, '제101조(소재수사 등)', 60);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (449, '제102조(수사중지 시 지명수배ㆍ지명통보) 사법경찰관은 피의자의 소재불명을 이유로 수사중지 결정을 하려는 경우에는 지명수배 또는 지명통보를 해야 한다.', 60);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (450, '제103조(수사중지 결정에 대한 이의제기 절차)', 60);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (451, '제104조(수사중지사건 수사재개)', 60);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (452, '제105조(송치 서류)', 61);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (453, '제106조(추가송부) 수사준칙 제58조제3항에 따른 추가송부서는 별지 제116호서식에 따른다.', 61);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (454, '제107조(보완수사요구의 결과 통보 등)', 61);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (455, '제108조(직무배제 또는 징계 요구의 처리 등)', 61);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (456, '제109조(법원송치)', 61);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (457, '제110조(불송치 결정)', 62);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (458, '제111조(불송치 서류)', 62);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (459, '제112조(일부 결정 시 조치 등)', 62);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (460, '제113조(혐의없음 결정 시의 유의사항) 사법경찰관은 고소 또는 고발 사건에 관하여 제110조제1항제1호의 혐의없음 결정을 하는 경우에는 고소인 또는 고발인의 무고혐의의 유무를 판단해야 한다.', 62);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (461, '제114조(재수사 결과의 처리)', 62);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (462, '제115조(고소인등의 이의신청)', 62);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (463, '제1조(목적) 이 법은 스토킹범죄의 처벌 및 그 절차에 관한 특례와 스토킹범죄 피해자에 대한 보호절차를 규정함으로써 피해자를 보호하고 건강한 사회질서의 확립에 이바지함을 목적으로 한다.', 63);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (464, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다. <개정 2023.7.11>', 63);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (465, '제3조(스토킹행위 신고 등에 대한 응급조치) 사법경찰관리는 진행 중인 스토킹행위에 대하여 신고를 받은 경우 즉시 현장에 나가 다음 각 호의 조치를 하여야 한다. <개정 2023.7.11>', 64);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (466, '제4조(긴급응급조치)', 64);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (467, '제5조(긴급응급조치의 승인 신청)', 64);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (468, '제6조(긴급응급조치의 통지 등)', 64);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (469, '제7조(긴급응급조치의 변경 등)', 64);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (470, '제8조(잠정조치의 청구)', 64);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (471, '제9조(스토킹행위자에 대한 잠정조치)', 64);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (472, '제10조(잠정조치의 집행 등)', 64);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (473, '제11조(잠정조치의 변경 등)', 64);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (474, '제12조(항고)', 64);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (475, '제13조(항고장의 제출)', 64);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (476, '제14조(항고의 재판)', 64);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (477, '제15조(재항고)', 64);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (478, '제16조(집행의 부정지) 항고와 재항고는 결정의 집행을 정지하는 효력이 없다.', 64);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (479, '제17조(스토킹범죄의 피해자에 대한 전담조사제)', 64);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (480, '제17조의2(피해자 등에 대한 신변안전조치) 법원 또는 수사기관이 피해자등 또는 스토킹범죄를 신고(고소ㆍ고발을 포함한다. 이하 이 조에서 같다)한 사람을 증인으로 신문하거나 조사하는 경우의 신변안전조치에 관하여는 「특정범죄신고자 등 보호법」 제13조 및 제13조의2를 준용한다. 이 경우 "범죄신고자등"은 "피해자등 또는 스토킹범죄를 신고한 사람"으로 본다.', 64);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (481, '제17조의3(피해자등의 신원과 사생활 비밀 누설 금지)', 64);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (482, '제17조의4(피해자에 대한 변호사 선임의 특례)', 64);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (483, '제18조(스토킹범죄)', 65);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (484, '제19조(형벌과 수강명령 등의 병과)', 65);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (485, '제20조(벌칙)', 65);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (486, '제21조 삭제 <2023.7.11>', 65);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (487, '제1조(목적) 이 영은 「스토킹범죄의 처벌 등에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 66);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (488, '제2조(스토킹범죄를 저지른 사람의 재범 예방을 위한 시책 마련) 법무부장관은 「스토킹범죄의 처벌 등에 관한 법률」(이하 "법"이라 한다) 제19조제1항에 따른 수강명령과 스토킹 치료프로그램 이수명령의 실시에 필요한 프로그램의 개발과 관련 전문인력의 양성 등 스토킹범죄를 저지른 사람의 재범 예방을 위한 시책을 마련해야 한다.', 66);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (489, '제3조(민감정보 및 고유식별정보의 처리)', 66);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (490, '제4조(과태료의 부과기준) 법 제21조제1항 및 제2항에 따른 과태료의 부과기준은 별표와 같다.', 66);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (491, '제1조(목적) 이 법은 스토킹을 예방하고 피해자를 보호ㆍ지원함으로써 인권증진에 이바지함을 목적으로 한다.', 67);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (492, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다.', 67);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (493, '제3조(국가 등의 책무)', 67);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (494, '제4조(스토킹 실태조사)', 67);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (495, '제5조(스토킹 예방교육 등)', 67);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (496, '제6조(피해자 등에 대한 불이익조치의 금지 등)', 67);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (497, '제7조(취학 지원)', 67);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (498, '제8조(지원시설의 설치)', 67);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (499, '제9조(지원시설의 업무) 지원시설은 다음 각 호의 업무를 수행한다.', 67);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (500, '제10조(종사자 등의 자격기준)', 67);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (501, '제11조(교육의 실시)', 67);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (502, '제12조(피해자등의 의사 존중 의무) 지원시설의 장과 종사자는 피해자등이 분명히 밝힌 의사에 반하여 제9조에 따른 업무를 하여서는 아니 된다.', 67);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (503, '제13조(경찰관서의 협조)', 67);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (504, '제14조(사법경찰관리의 현장출동 등)', 67);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (505, '제15조(비밀 유지의 의무) 지원시설의 장 또는 종사자이거나 지원시설의 장이었던 자 또는 종사자이었던 자는 그 직무상 알게 된 비밀을 누설하여서는 아니 된다.', 67);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (506, '제16조(벌칙)', 67);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (507, '제17조(양벌규정) 법인의 대표자나 법인 또는 개인의 대리인, 사용인, 그 밖의 종사자가 그 법인 또는 개인의 업무에 관하여 제16조의 위반행위를 하면 그 행위자를 벌하는 외에 그 법인 또는 개인에게도 해당 조문의 벌금형을 과(科)한다. 다만, 법인 또는 개인이 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다.', 67);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (508, '제18조(과태료)', 67);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (509, '제1조(목적) 이 영은 「스토킹방지 및 피해자보호 등에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 68);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (510, '제2조(스토킹 실태조사)', 68);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (511, '제3조(스토킹 예방교육 등)', 68);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (512, '제4조(피해자등의 취학 지원)', 68);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (513, '제5조(피해자 지원시설의 설치ㆍ운영 기준) 법 제8조제1항에 따른 피해자 지원시설(이하 "지원시설"이라 한다)의 설치ㆍ운영 기준은 별표 1과 같다.', 68);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (514, '제6조(지원시설의 설치ㆍ운영 업무의 위탁) 법 제8조제2항에서 "대통령령으로 정하는 기관 또는 단체"란 다음 각 호의 기관 또는 단체를 말한다.', 68);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (515, '제7조(지원시설의 업무) 법 제9조제11호에서 "대통령령으로 정하는 업무"란 피해자등에 대한 보호ㆍ지원을 원활히 하기 위한 관련 시설과의 협력 업무를 말한다.', 68);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (516, '제8조(지원시설 종사자 등의 자격기준) 법 제10조제2항에서 "전문 지식이나 경력 등 대통령령으로 정하는 자격기준"이란 별표 2에 따른 자격기준을 말한다.', 68);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (517, '제9조(교육의 실시)', 68);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (518, '제10조(민감정보 및 고유식별정보의 처리)', 68);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (519, '제11조(규제의 재검토) 여성가족부장관은 다음 각 호의 사항에 대하여 2024년 1월 1일을 기준으로 3년마다(매 3년이 되는 해의 기준일과 같은 날 전까지를 말한다) 그 타당성을 검토하여 개선 등의 조치를 해야 한다.', 68);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (520, '제12조(과태료의 부과기준) 법 제18조제1항에 따른 과태료의 부과기준은 별표 3과 같다.', 68);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (521, '제1조(목적) 이 영은 「보호소년 등의 처우에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 69);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (522, '제2조(보호소년의 처우) 소년원장은 「보호소년 등의 처우에 관한 법률」(이하 "법"이라 한다) 제2조제2항에 따라 교육활동에 지장을 주지 않는 범위에서 보호소년에게 다음 각 호에 해당하는 향상된 처우를 할 수 있다. <개정 2021.4.20>', 69);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (523, '제3조(소년원의 기능별 분류ㆍ운영)', 69);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (524, '제4조 삭제 <2008.6.20>', 69);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (525, '제5조', 69);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (526, '제5조의2(생활실 수용정원) 법 제6조제2항에 따라 소년원 또는 소년분류심사원(이하 "소년원등"이라 한다)에 두는 생활실의 수용정원은 4명 이하로 한다. 다만, 소년원등의 기능ㆍ위치나 그 밖의 사정을 고려하여 수용인원을 증대할 수 있다. <개정 2021.4.20>', 69);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (527, '제6조(보호소년등의 인수)', 71);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (528, '제7조 삭제 <2008.6.20>', 71);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (529, '제8조(수용사실 통지) 원장은 법 제7조제3항에 따라 보호소년등의 보호자 또는 보호소년등이 지정하는 사람(이하 "보호자등"이라 한다)에게 보호소년등을 수용한 사실을 알릴 때에는 수용 경위, 처우의 개요, 면회ㆍ통신 방법, 그 밖에 필요한 사항을 함께 알려야 한다.', 71);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (530, '제9조(분류처우)', 71);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (531, '제10조(개별처우계획의 수립)', 71);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (532, '제11조(개별처우계획의 수정) 소년원장은 제10조제1항에 따라 수립한 보호소년의 개별처우계획을 변경할 필요가 있는 경우에는 지체 없이 처우ㆍ징계위원회의 심사를 거쳐 수정해야 한다. <개정 2021.4.20>', 71);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (533, '제12조(보호처분 취소대상자 통지) 원장은 보호소년등이 법원소년부의 보호처분 결정 당시 10세 미만(「소년법」 제32조제1항제10호 처분의 경우에는 12세 미만으로 한다)이었거나 19세 이상이었던 것으로 밝혀지면 지체 없이 해당 보호처분 결정을 한 법원소년부에 그 사실을 통지하여야 한다.', 71);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (534, '제13조(청원의 편의 제공)', 72);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (535, '제14조(수용인원의 조절을 위한 이송) 법무부장관은 분류수용이나 교육훈련을 위하여 수용인원을 조절할 필요가 있다고 인정되면 소년원장에게 보호소년을 다른 소년원으로 이송(移送)할 것을 지시할 수 있다.', 72);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (536, '제15조(청원에 따른 이송) 소년원장은 보호소년 또는 그 보호자등이 다른 소년원으로 이송해 줄 것을 청원한 경우에는 법무부장관의 허가를 받아 보호소년을 그 소년원으로 이송할 수 있다.', 72);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (537, '제16조(이송의 제한)', 72);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (538, '제17조(비상사태 등의 대비) 원장은 법 제13조에 따른 비상사태 등에 대비하여 소년원등 안에 대피시설을 마련해야 한다. <개정 2021.4.20>', 73);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (539, '제17조의2(소지금지물품) 보호소년등은 다음 각 호의 물품을 소지해서는 아니 된다.', 73);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (540, '제17조의3(신체 검사 등)', 73);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (541, '제18조(외부인의 출입통제)', 73);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (542, '제19조(심신안정실에의 수용)', 73);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (543, '제20조(사고발생 보고)', 73);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (544, '제21조(사체의 검사) 원장은 보호소년등이 사망한 경우에는 지체 없이 검사의 지휘에 따라 사체의 검사 등 필요한 조치를 하여야 한다.', 73);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (545, '제22조(사망 통지 및 사체의 인도) 원장은 보호소년등이 사망하면 지체 없이 병명, 사망 원인 및 사망 일시를 보호자등에게 알리고, 검사의 지휘에 따라 사체를 인도하여야 한다.', 73);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (546, '제23조(사체의 임시매장) 원장은 보호자등의 소재를 알 수 없거나 그 밖의 부득이한 사유로 제22조에 따라 사체를 인도할 수 없을 때에는 임시매장을 하고, 임시매장한 장소에 사망자의 성명, 생년월일 및 사망연월일을 새긴 표지를 세워야 한다. <개정 2015.12.30, 2021.1.5>', 73);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (547, '제23조의2 삭제 <2016.9.5>', 74);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (548, '제24조(징계)', 74);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (549, '제24조의2(징계대상행위의 조사)', 74);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (550, '제25조 삭제 <2016.9.5>', 74);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (551, '제26조(지정된 실내의 구조) 법 제15조제1항제7호에 따른 지정된 실내는 면적ㆍ채광ㆍ통풍ㆍ온도ㆍ습도 등이 보호소년등의 건강을 보호할 수 있도록 적절하여야 한다. <개정 2016.9.5>', 74);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (552, '제27조(징계 중의 지도)', 74);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (553, '제28조(이송 중의 규율위반자에 대한 징계) 보호소년이 이송 중에 규율을 위반한 경우 그 징계는 인수한 소년원장이 한다.', 74);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (554, '제29조(징계자의 처우 제한) 원장은 법 제15조에 따라 징계처분을 받은 보호소년등에 대하여 징계기간 중 교육활동의 일부를 제한할 수 있다.', 74);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (555, '제30조(징계집행의 유예ㆍ정지ㆍ면제) 원장은 정상을 특별히 참작할 사유가 있거나 환자인 경우에는 징계 집행을 면제하거나 사유가 없어질 때까지 징계 집행을 유예하거나 정지할 수 있다.', 74);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (556, '제30조의2(처우ㆍ징계위원회의 심의ㆍ의결사항) 처우ㆍ징계위원회는 법 제15조의2제1항에 따라 다음 각 호의 사항을 심의ㆍ의결한다.', 74);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (557, '제30조의3(처우ㆍ징계위원회의 구성)', 74);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (558, '제30조의4(위원의 제척ㆍ기피ㆍ회피)', 74);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (559, '제30조의5(처우ㆍ징계위원회의 위원장)', 74);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (560, '제30조의6(처우ㆍ징계위원회의 회의)', 74);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (561, '제30조의7(위원의 해촉) 위원장은 제30조의3제2항에 따라 위촉된 위원이 다음 각 호의 어느 하나에 해당하면 그 위원을 해촉(解觸)할 수 있다.', 74);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (562, '제30조의8(간사)', 74);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (563, '제30조의9(회의록의 작성 및 보관)', 74);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (564, '제30조의10(운영세칙) 이 영에서 규정한 것 외에 처우ㆍ징계위원회의 운영에 필요한 사항은 처우ㆍ징계위원회의 의결을 거쳐 위원장이 정한다.', 74);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (565, '제31조(포상)', 74);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (566, '제32조(특별급식) 원장은 국경일이나 그 밖에 필요하다고 인정할 때에는 보호소년등에게 특별급식을 할 수 있다.', 75);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (567, '제33조(음식물 등의 반입 허가)', 75);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (568, '제34조(금전 사용금지) 보호소년등은 통학, 통근취업 등 원장이 특히 필요하다고 인정하여 허가하는 경우가 아니면 금전을 소지하거나 직접 사용할 수 없다.', 75);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (569, '제35조 삭제 <2014.1.28>', 75);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (570, '제36조(면회 시간)', 76);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (571, '제37조(면회의 참석) 법 제18조제2항에 따라 면회에 참석하는 직원은 보호소년등이 규율을 위반하거나 면회인이 보호소년등에게 나쁜 영향을 준다고 인정되는 때에는 면회를 중지시킬 수 있다.', 76);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (572, '제38조(면회허가의 제한) 원장은 보호소년등을 면회하려는 사람이 다음 각 호의 어느 하나에 해당한다고 인정되면 면회를 허가하지 않을 수 있다. <개정 2014.1.28, 2021.4.20>', 76);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (573, '제39조(편지 왕래의 제한)', 76);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (574, '제39조의2(전화통화의 제한)', 76);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (575, '제40조(외출 기간) 법 제19조에 따른 외출 기간은 7일(공휴일과 토요일을 포함한다) 이내로 한다. 다만, 특별한 사유가 있을 때에는 그 기간을 연장할 수 있다. <개정 2021.4.20>', 76);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (576, '제41조(외출 시 준수사항의 부과)', 76);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (577, '제42조(건강진단 등) 원장은 보호소년등에 대하여 법 제7조제2항에 따른 건강진단 외에 정기ㆍ수시검진을 하고 그 결과를 기록ㆍ유지하여야 한다.', 77);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (578, '제43조(외부 의료기관 의료조치)', 77);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (579, '제44조(보호자등의 간호) 원장은 보호소년등이 법 제20조제2항에 따라 외부 의료기관에서 치료를 받는 경우 그 보호자등에게 간호하게 할 수 있다.', 77);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (580, '제44조의2(간호사의 의료행위) 법 제20조제4항에서 "대통령령으로 정하는 경미한 의료행위"란 다음 각 호의 의료행위를 말한다.', 77);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (581, '제45조(감염병의 예방)', 77);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (582, '제46조(감염병 발생 보고 등) 원장은 소년원등에서 감염병이 발생하면 지체 없이 그 발생 상황을 법무부장관에게 보고하고, 「감염병의 예방 및 관리에 관한 법률」 제12조에 따라 그 소년원등이 있는 지역의 보건소장에게 즉시 신고해야 한다. <개정 2010.12.29, 2021.4.20>', 77);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (583, '제47조(금품의 보관)', 78);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (584, '제48조(보관금품의 반환 등)', 78);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (585, '제49조(물품 등의 기증)', 78);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (586, '제50조(탁송금품의 반송) 원장은 보호소년등에게 탁송(託送)된 금품을 본인이 받기를 거부하거나 처우상 본인에게 교부하는 것이 적당하지 아니하다고 인정되면 지체 없이 이를 보낸 사람에게 반송하여야 한다.', 78);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (587, '제51조(분류심사의 영역)', 79);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (588, '제52조(상담조사 등)', 79);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (589, '제53조(분류심사관의 직무 등)', 79);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (590, '제54조(청소년심리검사 등)', 79);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (591, '제55조(교육계획)', 81);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (592, '제56조(교육단계)', 81);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (593, '제57조(교정성적의 평가)', 81);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (594, '제58조(소년관리기록부)', 81);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (595, '제59조(학교의 설치ㆍ운영 등)', 82);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (596, '제60조(교감의 겸직) 소년원학교가 설치된 소년원의 교무과장은 법 제30조제3항에 따라 그 소년원학교 교감의 직무를 겸임한다.', 82);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (597, '제61조(교원 등의 직무수행)', 82);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (598, '제62조(교원의 연수)', 82);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (599, '제63조(입학 또는 편입학)', 82);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (600, '제63조의2 삭제 <2014.1.28>', 82);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (601, '제64조(학교생활기록부) 소년원학교장은 「초ㆍ중등교육법」 제25조에 따라 보호소년의 인성발달상황과 학업성취도 등을 종합적으로 관찰ㆍ평가한 학교생활기록부를 작성ㆍ관리하여야 한다.', 82);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (602, '제64조의2(학적사항 통지 및 관리)', 82);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (603, '제65조(다른 학교로의 전학ㆍ편입학) 보호소년이 법 제32조에 따른 전적학교 등 다른 학교에 전학ㆍ편입학하려는 경우에는 전학ㆍ편입학 배정원서, 그 밖의 필요한 서류를 거주지 또는 전학ㆍ편입학 예정학교의 관할교육청의 장이나 전학ㆍ편입학 예정학교의 장에게 제출하여야 한다.', 82);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (604, '제66조(통학)', 82);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (605, '제67조(졸업사정 등)', 82);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (606, '제68조(졸업증명서 등의 발급) 소년원장은 보호소년이나 그 보호자의 신청을 받으면 졸업증명서, 성적증명서, 수료증명서 등을 발급하여야 한다.', 82);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (607, '제69조(학력인정 검정고시의 응시 특례) 소년원학교에 재학 중인 보호소년 중 다음 각 호 어느 하나에 해당하는 사람은 학력인정 검정고시에 응시할 수 있다. <개정 2015.1.6, 2015.9.15>', 82);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (608, '제70조(장학 협의) 소년원학교장은 관할 교육청의 장과 소년원학교의 학사운영에 관하여 장학(<img src="http://www.law.go.kr/flDownload.do?flSeq=97087181"  alt="img97087181" >學</img>) 협의를 할 수 있으며, 관할 교육청의 장은 필요한 권고를 할 수 있다.', 82);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (609, '제71조(직업능력개발훈련 방침)', 83);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (610, '제72조(공공직업훈련시설의 설치) 법무부장관은 「국민 평생 직업능력 개발법」 제27조에 따라 소년원에 공공직업훈련시설을 설치ㆍ운영할 수 있다. <개정 2022.2.17>', 83);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (611, '제73조(지원 직업능력개발훈련) 소년원장은 법 제35조제2항에 따라 산업체의 지원을 받아 직업능력개발훈련을 실시하려면 지원산업체와 지원목적, 기간, 내용, 그 밖의 지원에 관한 사항을 포함하는 지원약정서를 작성하여야 한다.', 83);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (612, '제74조(외부시설에서의 직업능력개발훈련) 소년원장은 법 제35조제2항에 따라 보호소년을 소년원 외의 시설에 통근시키거나 위탁하여 직업능력개발훈련을 실시할 수 있다.', 83);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (613, '제75조(직업능력개발훈련교사의 훈련) 법무부장관은 직업능력개발훈련교사의 능력개발을 위하여 해당 교사에게 「국민 평생 직업능력 개발법」 제37조제2항에 따른 보수교육을 정기적으로 이수하도록 해야 한다. <개정 2021.4.20, 2022.2.17>', 83);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (614, '제76조(통근취업의 원칙)', 83);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (615, '제77조(자립기반 조성) 법무부장관은 보호소년의 직업능력 향상과 성공적 자립기반 조성을 위하여 창업보육, 지원재단 설립 및 자립생활관 운영 등 필요한 사업을 할 수 있다.', 83);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (616, '제78조(생활지도의 목표) 원장은 법 제39조에 따라 생활지도를 할 때에는 보호소년등의 심신, 행동발달 및 품행 개선에 목표를 두고 지도하여야 한다.', 84);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (617, '제79조(상담ㆍ인성교육)', 84);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (618, '제80조(특별활동)', 84);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (619, '제81조(봉사활동) 소년원장은 보호소년의 공동체의식 함양과 체험을 통한 인성교육을 위하여 다양한 봉사활동 프로그램을 운영하여야 한다.', 84);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (620, '제82조(종교활동 등)', 84);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (621, '제83조(도서실 등의 설치ㆍ운영)', 84);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (622, '제84조(장학지도) 법무부장관은 법 제42조에 따른 장학지도를 할 때에는 매 학년도마다 장학지도의 대상ㆍ방법 및 결과처리 등에 관한 세부계획을 수립하고 이를 소년원학교에 미리 통보하여야 한다.', 84);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (623, '제85조(대안교육 대상자의 출석일수 인정)', 84);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (624, '제86조(보호자교육)', 84);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (625, '제87조(퇴원ㆍ임시퇴원의 취소 및 심사신청의 철회) 소년원장은 소년원 퇴원 또는 임시퇴원이 허가되었거나 퇴원 또는 임시퇴원 심사신청 중인 보호소년에게 징계사유 등 특별한 사유가 발생하면 보호관찰심사위원회에 퇴원 또는 임시퇴원 허가의 취소를 신청하거나 퇴원ㆍ임시퇴원  심사신청을 철회할 수 있다.', 85);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (626, '제87조의2(재ㆍ퇴원증명서의 발급) 원장은 다음 각 호의 어느 하나에 해당하는 자가 소년원등에 수용된 사실 또는 수용되었다가 출원한 사실 등에 관한 증명서의 발급을 신청하는 경우에는 법무부령으로 정하는 재ㆍ퇴원증명서를 발급할 수 있다. 이 경우 재ㆍ퇴원증명서의 발급 신청 및 발급은 「민원 처리에 관한 법률」 제12조의2제2항 및 제3항에 따른 전자민원창구를 통하여 처리할 수 있다. <개정 2021.4.20, 2022.7.11>', 85);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (627, '제88조(임시퇴원 취소자의 재수용)', 85);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (628, '제89조(외국인의 방문) 원장은 법 제49조에 따라 외국인의 방문을 허가하려면 법무부장관의 승인을 받아야 한다.', 87);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (629, '제90조(각종 자료 조회)', 87);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (630, '제90조의2(민감정보 및 고유식별정보의 처리)', 87);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (631, '제91조(지부 등의 설치) 법 제51조에 따라 설치된 소년보호협회(이하 "협회"라 한다)에는 소관 사업의 원활한 추진을 위하여 그 지부 또는 지회를 둘 수 있다.', 88);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (632, '제92조(정관)', 88);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (633, '제93조(임원)', 88);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (634, '제94조(임원의 직무)', 88);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (635, '제95조(이사회)', 88);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (636, '제96조(직원의 임면) 협회의 직원은 정관으로 정하는 바에 따라 이사장이 임면한다.', 88);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (637, '제97조(협회의 자산) 협회는 다음 각 호의 재산을 그 자산으로 한다.', 88);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (638, '제98조(협회의 사업)', 88);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (639, '제99조(사업 및 회계관리)', 88);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (640, '제100조(감독)', 88);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (641, '제101조(준용규정) 협회에 관하여는 이 영에서 규정한 것을 제외하고는 「공익법인의 설립ㆍ운영에 관한 법률」 및 「민법」 중 재단법인에 관한 규정을 준용한다.', 88);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (642, '제102조(기부금품의 접수 등)', 89);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (643, '제103조(범죄경력자료 등 조회 요청의 제한 등)', 90);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (644, '제1조(목적) 이 영은 「스토킹범죄의 처벌 등에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 91);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (645, '제2조(스토킹범죄를 저지른 사람의 재범 예방을 위한 시책 마련) 법무부장관은 「스토킹범죄의 처벌 등에 관한 법률」(이하 "법"이라 한다) 제19조제1항에 따른 수강명령과 스토킹 치료프로그램 이수명령의 실시에 필요한 프로그램의 개발과 관련 전문인력의 양성 등 스토킹범죄를 저지른 사람의 재범 예방을 위한 시책을 마련해야 한다.', 91);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (646, '제3조(민감정보 및 고유식별정보의 처리)', 91);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (647, '제4조(과태료의 부과기준) 법 제21조제1항 및 제2항에 따른 과태료의 부과기준은 별표와 같다.', 91);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (648, '제1조(목적) 이 영은 보건범죄단속에관한특별조치법(이하 "법"이라 한다) 및 동시행령(이하 "영"이라 한다)에서 위임된 사항과 보건복지부장관이 행하는 행정처분 기타 행정상 필요한 사항을 규정함을 목적으로 한다. <개정 2008.3.3, 2010.3.19>', 92);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (649, '제2조(지정공정서) 영 제5조제1항의 규정에 의하여 보건복지부장관이 지정하는 공정서는 다음 각호의 것을 말한다. <개정 2008.3.3, 2010.3.19>', 92);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (650, '제3조(최소유효량의 판정) 영 제5조제2항의 규정에 의한 의약품의 "최소유효량"은 국립보건연구원의 검정에 따라 보건복지부장관이 판정한다. <개정 2008.3.3, 2010.3.19>', 92);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (651, '제4조(현저한 유해등의 판정) 영 제5조의 규정에 의한 "현저한 유해"및 "현저한 부족"의 판정을 위한 검정은 별표에 의한 시공품량을 채취하여 행하여야 한다.', 92);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (652, '제5조(범죄통보의 처리)', 92);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (653, '제6조(상금의 청구) 법 제9조의 규정에 의한 상금의 급여신청은 당해사건의 통보자 또는 검거자가 별지 제1호서식에 의한 신청서에 다음 각호의 서류를 첨부하여 보건복지부장관에게 제출하여야 한다. <개정 2008.3.3, 2010.3.19>', 92);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (654, '제7조(통보인 또는 검거인이 2인이상인 경우의 상금의 지급기준) 통보인 또는 검거인이 2인이상인 경우에는 상금은 등분하여 이를 지급한다.', 92);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (655, '제8조(지급조서등의 작성) 보건복지부장관은 제6조 및 제7조에 따라 상금을 지급한 때에는 별지 제2호 및 제3호의 서식에 따른 상금지급조서와 지급대장을 작성하여 지급상황을 명확하게 적어 이를 비치해야 한다. <개정 1978.12.7, 2008.3.3, 2010.3.19, 2021.7.7>', 92);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (656, '제1조(목적) 이 영은 「군사경찰의 직무수행에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (657, '제2조(군사경찰) 「군사경찰의 직무수행에 관한 법률」(이하 "법"이라 한다) 제3조제1호에서 "대통령령으로 정하는 사람"이란 다음 각 호의 구분에 따라 국방부장관 또는 각 군 참모총장(해병대의 경우에는 해병대사령관을 말한다. 이하 같다)이 군사경찰로 임명한 사람을 말한다. 다만, 병(兵)의 경우에는 군사경찰부대가 설치되어 있는 부대의 장이 군사경찰로 임명한 사람을 말한다.', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (658, '제3조(증표) 국방부장관 및 각 군 참모총장은 제2조에 따라 군사경찰로 임명한 사람(병은 제외한다)에게 군사경찰 신분을 표시하는 증표를 발급해야 한다.', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (659, '제4조(군사경찰장구) 법 제3조제5호에서 "수갑ㆍ포승(捕繩)ㆍ경찰봉ㆍ전자충격기ㆍ전자충격총 및 방패 등 대통령령으로 정하는 장치와 기구"란 다음 각 호의 장치와 기구를 말한다.', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (660, '제5조(보고) 군사경찰은 다음 각 호에 해당하는 경우에는 군사경찰부대가 설치되어 있는 부대의 장에게 그 사실을 보고해야 한다.', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (661, '제6조(군사경찰의 직무수행을 위한 관계 기관 협조) 군사경찰은 법 제5조제1항제3호의 업무를 수행하기 위하여 필요한 경우 경찰관서 등 관계 기관에 신병 인계, 사건 이첩 및 사실조회에 관한 협조를 요청할 수 있다.', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (662, '제7조(군사경찰의 지휘ㆍ감독) 군사경찰부대가 설치되어 있는 부대의 장은 수사의 공정성을 확보하기 위하여 군사경찰이 법 제5조제1항제3호에 따른 직무를 수행할 때 독립성을 보장해야 한다.', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (663, '제8조(교통ㆍ운항ㆍ항행 질서 유지 등)', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (664, '제9조(위해성 군사경찰장비의 종류) 법 제11조제1항 단서에 따른 위해성 군사경찰장비의 종류는 다음 각 호와 같다.', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (665, '제10조(위해성 군사경찰장비 및 군사경찰장비의 안전교육) 법 제11조제1항 단서에 따른 위해성 군사경찰장비의 안전교육 기준 및 법 제15조제1항에 따른 군사경찰장비의 사용방법ㆍ관리 및 안전 등에 관한 교육 내용과 방법은 각각 별표 1과 같다.', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (666, '제11조(위해성 군사경찰장비의 안전검사 기준) 법 제11조제1항 단서 및 제15조제2항에 따른 위해성 군사경찰장비의 안전검사 기준은 각각 별표 2와 같다.', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (667, '제12조(위해성 군사경찰장비의 사용기준) 법 제11조제3항에 따른 위해성 군사경찰장비의 사용기준은 다음 각 호와 같다.', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (668, '제13조(신규 도입 위해성 군사경찰장비의 안전성 검사)', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (669, '제14조(손실보상의 기준 및 보상금액 등)', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (670, '제15조(손실보상의 지급절차 및 방법)', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (671, '제16조(손실보상심의위원회의 구성)', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (672, '제17조(위원장)', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (673, '제18조(위원회의 운영)', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (674, '제19조(위원의 제척ㆍ기피ㆍ회피)', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (675, '제20조(위원의 해촉) 국방부장관은 위원회의 위원이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 위원을 해촉(解囑)할 수 있다.', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (676, '제21조(비밀 누설의 금지) 위원회의 회의에 참석한 사람은 직무상 알게 된 비밀을 누설해서는 안 된다.', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (677, '제22조(위원회의 운영 등에 필요한 사항) 제16조부터 제21조까지에서 규정한 사항 외에 위원회의 운영 등에 필요한 사항은 국방부장관이 정한다.', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (678, '제23조(민감정보 및 고유식별정보의 처리) 군사경찰은 법 제5조제1항제3호(범죄의 정보수집에 관한 직무는 제외한다. 이하 이 조에서 같다) 및 제4호에 따른 직무를 수행하기 위하여 불가피한 경우 다음 각 호의 구분에 따른 정보가 포함된 자료를 처리할 수 있다.', 93);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (679, '제1조(목적) 이 규칙은 「형사소송법」 제245조의10제4항에 따른 검사의 수사지휘에 관한 구체적인 사항과 「사법경찰관리의 직무를 행할 자와 그 직무범위에 관한 법률」에 따라 사법경찰관리의 직무를 행하는 자의 범죄수사에 관한 집무상의 준칙을 규정함으로써 수사과정에서 국민의 인권을 보호하고, 수사절차의 투명성과 수사의 효율성을 보장함을 목적으로 한다.', 94);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (680, '제2조(특별사법경찰관리의 직무)', 94);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (681, '제3조(수사의 기본원칙)', 94);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (682, '제4조(불이익 금지 및 기밀엄수) 특별사법경찰관리는 피의자나 사건관계인이 인권침해 신고나 그 밖에 인권 구제를 위한 신고, 진정, 고소, 고발 등의 행위를 했다는 이유로 부당한 대우를 하거나 불이익을 주어서는 안 된다.', 94);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (683, '제5조(수사사건의 공개금지 등)', 94);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (684, '제6조(관할)', 96);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (685, '제7조(임의수사 우선의 원칙과 강제수사 시 유의사항)', 96);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (686, '제8조(회피) 특별사법경찰관리는 피의자나 사건관계인과 친족관계 또는 이에 준하는 관계가 있거나 그 밖에 수사의 공정성을 의심 받을 염려가 있는 사건에 대해서는 소속 기관의 장의 허가를 받아 그 수사를 회피해야 한다.', 96);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (687, '제9조(수사 진행상황의 통지) 특별사법경찰관리는 수사의 진행상황을 사건관계인에게 적절히 통지하도록 노력해야 한다.', 96);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (688, '제10조(변호인의 피의자신문 등 참여)', 96);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (689, '제11조(변호인의 의견진술)', 96);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (690, '제12조(피해자 보호)', 96);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (691, '제13조(수사의 협조) 특별사법경찰관리는 직무를 수행하면서 다른 사법경찰관리와 서로 성실하게 협조해야 한다.', 96);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (692, '제14조(사건의 단위) 다음 각 호의 어느 하나에 해당하는 범죄사건은 1건으로 처리한다.', 96);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (693, '제15조(사법경찰관리 지명서 휴대의무) 사법경찰직무법 제5조에 따라 지명된 특별사법경찰관리는 압수수색ㆍ조사 등 수사업무를 수행할 때에는 사법경찰관리로 지명된 사람임을 증명하는 서류를 항상 지니고 있어야 한다.', 96);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (694, '제16조(합동단속반의 설치ㆍ운영 등)', 96);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (695, '제17조(내사)', 97);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (696, '제18조(범죄인지서)', 97);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (697, '제19조(수사의 개시)', 97);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (698, '제20조(사건기록의 관리)', 97);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (699, '제21조(변사자의 검시)', 97);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (700, '제22조(검시할 때의 주의사항)', 97);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (701, '제23조(검시의 참여) 특별사법경찰관은 검시에 특별한 지장이 없다고 인정할 때에는 변사자의 가족ㆍ친족ㆍ이웃사람ㆍ친구, 공무원 또는 그 밖에 필요하다고 인정하는 사람을 검시에 참여시켜야 한다.', 97);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (702, '제24조(자살자의 검시) 특별사법경찰관은 자살한 사람을 검시할 때에는 자살을 교사하거나 방조한 사람이 있는지를 조사해야 하며, 유서가 있을 때에는 그 진위 여부를 조사해야 한다.', 97);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (703, '제25조(수사개시 보고) 특별사법경찰관은 사법경찰직무법 제6조에서 부여한 직무범위에서 다음 각 호의 어느 하나에 해당하는 범죄에 대하여 수사를 개시했을 때에는 즉시 관할 지방검찰청 검사장 또는 지청장에게 별지 제5호서식의 수사개시 보고서로 보고해야 한다.', 98);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (704, '제26조(직무범위 외의 범죄발생에 대한 보고) 특별사법경찰관은 그 직무범위에 속하지 않는 범죄나 이에 대한 증거자료를 발견한 경우에도 다음 각 호의 어느 하나에 해당할 때에는 발견한 범죄사실이나 증거자료를 검사의 지휘를 받아 수사기관에 통보해야 한다.', 98);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (705, '제27조(범죄통계원표 등)', 98);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (706, '제28조(수사지휘의 원칙) 검사는 특별사법경찰관을 존중하고, 법률에 따라 특별사법경찰관의 모든 수사를 적정하게 지휘한다.', 99);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (707, '제29조(수사지휘 일반)', 99);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (708, '제30조(수사지휘 건의)', 99);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (709, '제31조(수사지휘의 방식)', 99);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (710, '제32조(수사지휘에 대한 재지휘 건의)', 99);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (711, '제33조(신속한 수사지휘) 검사는 특별사법경찰관으로부터 제30조에 따른 수사지휘 건의나 제32조에 따른 재지휘 건의를 받은 경우에는 지체 없이 지휘해야 한다. 다만, 사안이 복잡하거나 장기간 검토해야 할 특별한 사정이 있을 때에는 그렇지 아니하다.', 99);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (712, '제34조(수사지휘 기한 준수)', 99);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (713, '제35조(중요범죄의 입건 등)', 99);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (714, '제36조(출석요구)', 100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (715, '제37조(수사상 임의동행 시의 고지) 특별사법경찰관은 임의동행을 요구하는 경우 상대방에게 동행을 거부할 수 있다는 것과 동행하는 경우에도 언제든지 자유롭게 동행 과정에서 이탈하거나 동행 장소에서 퇴거할 수 있다는 것을 알려야 한다.', 100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (716, '제38조(심야조사 제한)', 100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (717, '제39조(장시간 조사 제한)', 100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (718, '제40조(휴식시간 부여)', 100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (719, '제41조(신뢰관계인의 동석)', 100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (720, '제42조(자료ㆍ의견의 제출기회 보장)', 100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (721, '제43조(수사과정의 기록)', 100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (722, '제44조(피의자에 대한 조사사항) 특별사법경찰관리는 피의자를 조사할 때에는 다음 각 호의 사항을 유의해야 한다.', 100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (723, '제45조(조서와 진술서)', 100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (724, '제46조(진술거부권 등의 고지 확인) 특별사법경찰관은 피의자신문조서 작성을 갈음하여 피의자에게 진술서를 작성하도록 하는 경우 등 피의자신문조서를 작성하지 않은 경우에는 법 제244조의3에 따라 진술거부권 등을 고지한 사실과 진술거부권 등의 고지에 대한 피의자의 답변에 대하여 피의자로부터 별지 제24호서식의 진술거부권 및 변호인 조력권 고지 등 확인서를 제출받아 기록에 편철해야 한다.', 100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (725, '제47조(사건관계인의 조사)', 100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (726, '제48조(조서 및 자료의 편철) 특별사법경찰관은 조서, 수사보고서 등 수사관계 서류를 작성하거나 해당 사건에 관한 자료를 접수했을 때에는 작성 또는 접수 순서에 따라 사건기록에 편철하고, 이를 기록목록에 적어야 하며, 사건기록에는 매 장마다 장수를 적어야 한다. 다만, 범죄사실과 직접 관련이 없거나 중복하여 작성 또는 접수된 자료는 별도의 기록으로 분리하여 편철할 수 있다.', 100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (727, '제49조(영상녹화)', 100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (728, '제50조(영상녹화물의 제작 등)', 100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (729, '제51조(임상조사) 특별사법경찰관리는 치료중인 피의자나 참고인을 상대로 임상신문(臨床訊問)을 하려는 경우에는 상대방의 건강상태를 충분히 고려해야 하며, 수사에 중대한 지장이 없는 한 가족이나 의사, 간호사 또는 해당 의료기관의 관리자를 참여시켜야 한다.', 100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (730, '제52조(실황조사)', 100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (731, '제53조(수사관계사항의 조회) 특별사법경찰관은 법 제199조제2항에 따라 공무소 기타 공사단체에 필요한 사항의 보고를 요구하는 경우에는 별지 제27호서식의 수사사항조회서에 따른다.', 100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (732, '제54조(영장의 집행)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (733, '제55조(체포영장의 신청)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (734, '제56조(영장의 재신청) 특별사법경찰관은 다음 각 호의 어느 하나에 해당하는 경우 동일한 범죄사실로 다시 영장등의 발부를 신청할 때에는 그 취지를 검사에게 보고하고, 영장등의 신청서에 적어야 한다.', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (735, '제57조(긴급체포)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (736, '제58조(현행범인의 체포)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (737, '제59조(현행범인의 조사와 석방)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (738, '제60조(구속영장의 신청 등)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (739, '제61조(체포ㆍ구속의 통지 등)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (740, '제62조(체포ㆍ구속영장등본의 교부)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (741, '제63조(피의자의 접견 등)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (742, '제64조(피의자 유치 시 유의사항)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (743, '제65조(구금된 피의자의 처우) 특별사법경찰관리는 구금된 피의자에 대해서는 구금생활에 필요한 의류ㆍ침구, 그 밖의 생활용품과 식량 등을 지급해야 하며, 위생ㆍ의료 등에 있어서 상당한 처우를 해야 한다.', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (744, '제66조(구금과 건강상태) 특별사법경찰관은 피의자를 구금할 때에는 그의 건강상태를 조사하고 체포ㆍ구속으로 인하여 현저하게 건강을 해칠 염려가 있다고 인정할 때에는 그 사유를 검사에게 보고해야 한다.', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (745, '제67조(피의자의 석방)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (746, '제68조(체포ㆍ구속장소 감찰 관련 조치)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (747, '제69조(피의자의 도주 등) 특별사법경찰관은 체포하거나 구속한 피의자가 도주 또는 사망하거나, 그 밖의 이상이 발생한 때에는 즉시 관할 지방검찰청 또는 지청의 검사에게 보고해야 한다.', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (748, '제70조(압수ㆍ수색 또는 검증영장의 신청)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (749, '제71조(압수ㆍ수색 또는 검증영장의 제시)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (750, '제72조(전자정보의 압수ㆍ수색 또는 검증 방법)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (751, '제73조(전자정보의 압수ㆍ수색 또는 검증 시 유의사항)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (752, '제74조(압수조서의 작성)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (753, '제75조(증거물 등의 보전)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (754, '제76조(수색조서의 작성 등)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (755, '제77조(검증조서의 작성) 특별사법경찰관리가 검증을 한 경우에는 검증의 일시ㆍ장소, 검증 경위 등을 포함하여 별지 제66호서식의 검증조서를 작성해야 한다.', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (756, '제78조(압수물의 보관ㆍ폐기ㆍ환부 및 가환부)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (757, '제79조(범죄수사 목적 통신제한조치 허가신청 등)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (758, '제80조(통신제한조치의 집행 등)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (759, '제81조(통신제한조치로 취득한 자료의 관리)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (760, '제82조(통신제한조치 집행에 관한 통지 등)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (761, '제83조(송ㆍ수신이 완료된 전기통신에 대한 압수ㆍ수색ㆍ검증 집행사실 통지) 특별사법경찰관이 「통신비밀보호법」 제9조의3제2항에 따라 수사대상이 된 가입자에게 송ㆍ수신이 완료된 전기통신에 대한 압수ㆍ수색ㆍ검증의 집행사실을 통지하는 경우에는 별지 제94호서식의 송ㆍ수신이 완료된 전기통신에 대한 압수ㆍ수색ㆍ검증 집행사실 통지서에 따른다. 이 경우 특별사법경찰관은 별지 제95호서식의 송ㆍ수신이 완료된 전기통신에 대한 압수ㆍ수색ㆍ검증 집행사실 통지부에 해당 사항을 기재해야 한다.', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (762, '제84조(범죄수사를 위한 전기통신 보관 등의 승인청구 신청 등) 특별사법경찰관이 「통신비밀보호법」 제12조의2제2항에 따라 전기통신 보관 등의 승인 청구를 신청하는 경우에는 별지 제96호서식의 전기통신 보관 등 승인신청서에 따른다. 이 경우 특별사법경찰관은 별지 제97호서식의 전기통신 보관 등 승인신청부에 해당 사항을 기재해야 한다.', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (763, '제85조(통신사실 확인자료제공 요청 등)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (764, '제86조(통신사실 확인자료제공 요청 허가신청 등)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (765, '제87조(긴급 통신사실 확인자료제공 요청 등)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (766, '제88조(통신사실 확인자료제공에 관한 통지 등)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (767, '제89조(감정유치장 신청 등)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (768, '제90조(영장 등의 반환)', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (769, '제91조(증거보전의 신청) 특별사법경찰관은 미리 증거를 보전하지 않으면 그 증거를 사용하기 곤란한 사정이 있을 때에는 그 사유를 소명하여 별지 제119호서식의 증거보전신청서로 검사에게 증거보전의 청구를 신청해야 한다.', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (770, '제92조(증인신문의 신청) 특별사법경찰관리가 검사에게 법제221조의2에 따른 증인신문 청구를 신청하는 경우에는 별지 제120호서식의 증인신문 신청서에 따른다.', 101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (771, '제93조(고소사건 등에 대한 주의사항) 특별사법경찰관은 고소사건의 경우에는 고소한 사람에게 고소권이 있는지 여부를, 친고죄의 경우에는 법 제230조에 따른 고소기간을 지났는지 여부를, 피해자의 명시한 의사에 반하여 죄를 논할 수 없는 사건의 경우에는 처벌을 희망하는지 여부를 각각 조사해야 한다.', 102);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (772, '제94조(고소의 대리) 특별사법경찰관은 법 제236조에 따라 대리인이 고소를 하거나 고소를 취소하려는 경우에는 고소권자의 위임장을 제출받아야 한다.', 102);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (773, '제95조(고소사건의 수사기간)', 102);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (774, '제96조(고소 등의 취소)', 102);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (775, '제97조(소년사건수사의 기본원칙) 소년사건을 수사하는 경우에는 보호처분 또는 형사처분에 대한 특별한 심리자료를 제공하기 위한 것이라는 점에 유의해야 하며, 소년의 건전한 성장을 도모하는 자세로 수사해야 한다.', 103);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (776, '제98조(소년의 특성 고려) 소년사건을 수사하는 경우에는 소년의 특성에 비추어 되도록 다른 사람의 관심을 끌지 않는 조용한 장소에서 온정과 이해를 가지고 부드러운 말투로 조사해야 하며, 그 소년의 심정을 충분히 배려해야 한다.', 103);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (777, '제99조(범죄의 원인 등과 환경조사)', 103);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (778, '제100조(구속에 관한 주의) 소년을 구속하는 것은 되도록 피해야 하며, 소년을 구속 또는 동행하는 경우에도 그 시기와 방법에 관하여 특히 주의를 해야 한다.', 103);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (779, '제101조(보도상의 주의) 소년의 주거ㆍ성명ㆍ연령ㆍ직업ㆍ용모 등에 의하여 본인을 알 수 있는 정도의 사실이나 사진이 보도되지 않도록 특히 주의해야 한다.', 103);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (780, '제102조(장애인에 대한 조사)', 103);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (781, '제103조(외국인에 대한 통역) 특별사법경찰관은 외국인을 조사하는 경우에는 당사자가 이해할 수 있는 언어로 통역해 주어야 한다.', 103);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (782, '제104조(외국 영사관원과의 접견ㆍ통신)', 103);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (783, '제105조(수사서류의 작성) 특별사법경찰관리는 수사서류를 작성할 때에는 내용의 정확성과 진술의 임의성을 확보하기 위해 특히 다음 사항을 유의해야 한다.', 104);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (784, '제106조(외국어로 된 서면) 특별사법경찰관은 외국어로 작성된 서류에는 번역문을 첨부해야 한다.', 104);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (785, '제107조(범죄수익 몰수ㆍ부대보전ㆍ추징보전 신청)', 105);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (786, '제108조(마약류범죄 수사 관련 입국ㆍ상륙 절차 특례 등의 신청)', 105);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (787, '제109조(사건송치)', 106);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (788, '제110조(송치 전 지휘 등)', 106);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (789, '제111조(송치서류)', 106);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (790, '제112조(영상녹화물의 송부)', 106);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (791, '제113조(의견서 작성) 특별사법경찰관은 의견서를 작성하는 경우에는 별지 제136호서식에 따라 직접 작성해야 한다.', 106);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (792, '제114조(참고인 등의 소재수사)', 106);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (793, '제115조(추가 송부) 특별사법경찰관은 사건송치 후에 서류 또는 물건을 추가로 송부하는 경우에는 별지 제138호서식의 추가 송부서를 첨부해야 한다.', 106);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (794, '제116조(송치 후의 수사 등)', 106);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (795, '제117조(기소중지ㆍ참고인중지 처분된 자에 대한 수사)', 106);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (796, '제118조(수사촉탁)', 106);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (797, '제119조(행정고발사건의 수사기관) 특별사법경찰관리가 소속된 행정기관의 장이 고발한 사건은 해당 기관의 특별사법경찰관이 검사의 지휘를 받아 수사함을 원칙으로 한다. 다만, 검사가 직접 또는 다른 기관에서 수사함이 상당하다고 판단한 경우에는 해당 기관의 특별사법경찰관이 수사하지 않는다.', 106);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (798, '제120조(범죄사건부 등)', 106);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (799, '제121조(증언 준비) 특별사법경찰관리는 그 직무와 관련한 형사재판에서 증언하는 경우에는 공판에 관여하는 검사와 면담하는 등 사전에 필요한 준비를 해야 한다.', 106);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (800, '제122조(장부와 비치서류)', 107);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (801, '제123조(장부와 비치서류의 전자화)', 107);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (802, '제124조(수사관계예규철) 제122조제1항제1호의 수사관계예규철에는 검찰청이나 그 밖의 감독관청이 발령한 훈령ㆍ통첩ㆍ지령 등 관계 서류를 편철해야 한다.', 107);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (803, '제125조(수사종결사건철) 제122조제1항제2호의 수사종결사건(송치사건)철에는 검사에게 송치한 사건송치서, 기록목록 및 의견서의 사본을 편철해야 한다.', 107);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (804, '제126조(내사종결사건철) 제122조제1항제3호의 내사종결사건철에는 범죄를 내사한 결과 입건의 필요가 없다고 인정되어 완결된 기록을 편철해야 한다.', 107);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (805, '제127조(수사미제사건기록철) 제122조제1항제5호의 수사미제사건기록철에는 장차 검거할 가망이 없는 피해신고 사건 등의 기록을 편철해야 한다.', 107);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (806, '제128조(통계철) 제122조제1항제6호의 통계철에는 특별사법경찰업무에 관한 각종 통계서류를 편철해야 한다.', 107);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (807, '제129조(처분결과통지서철) 제122조제1항제7호의 처분결과통지서철에는 검사의 기소ㆍ불기소(기소유예, 혐의없음, 공소권없음, 죄가안됨, 각하)ㆍ기소중지ㆍ참고인중지ㆍ이송 등 결정과 각급 심의 재판결과에 관한 통지서를 편철해야 한다.', 107);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (808, '제130조(잡서류철) 제122조제1항제9호의 잡서류철에는 같은 항 제1호부터 제8호까지의 규정에 따른 서류철에 편철되지 않는 모든 서류를 편철해야 한다.', 107);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (809, '제131조(서류철의 색인목록)', 107);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (810, '제132조(임의장부 등) 특별사법경찰관은 필요하다고 인정할 때에는 제122조제1항 각 호의 장부와 서류 외에 필요한 장부나 서류철을 비치할 수 있다.', 107);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (811, '제133조(장부 등의 갱신)', 107);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (812, '제134조(장부와 서류의 보존기간) 제122조제1항 각 호의 장부와 서류는 다음 각 호의 구분에 따른 기간 동안 보존해야 한다.', 107);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (813, '제135조(보존기간의 기산 등)', 107);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (814, '제1조(목적) 이 영은 수형자나 그 밖에 법령에 따라 구속된 사람의 호송에 필요한 사항을 규정함을 목적으로 한다.', 108);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (815, '제2조(호송공무원) 교도소ㆍ구치소 및 그 지소(이하 "교정시설"이라 한다) 간의 호송은 교도관이 행하며, 그 밖의 호송은 경찰관 또는 「검찰청법」 제47조에 따라 사법경찰관리로서의 직무를 수행하는 검찰청 직원이 행한다. <개정 2018.2.20>', 108);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (816, '제3조(호송방법)', 108);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (817, '제4조(호송장등)', 108);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (818, '제5조(수송관서에의 통지) 발송관서는 미리 수송관서에 대하여 피호송자의 성명ㆍ발송시일ㆍ호송사유 및 방법을 통지하여야 한다.', 108);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (819, '제6조(영치금품의 처리) 피호송자의 영치금품은 다음과 같이 처리한다. <개정 2011.1.4>', 108);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (820, '제7조(호송시간) 호송은 일출전 또는 일몰후에는 행할 수 없다. 다만, 열차ㆍ선박ㆍ항공기를 이용하는 때 또는 특별한 사유가 있는 때에는 예외로 한다. <개정 2011.1.4>', 108);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (821, '제8조(피호송자의 숙박)', 108);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (822, '제9조(물품구매등의 허가)', 108);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (823, '제10조(피호송자의 도주 등)', 108);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (824, '제11조(피호송자의 질병등)', 108);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (825, '제12조(피호송자의 사망 등)', 108);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (826, '제13조(예비ㆍ호송비용의 부담)', 108);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (827, '제14조(호송비용) 피호송자를 교정시설이나 경찰관서가 아닌 장소에서 숙식하게 한 때의 비용은 「공무원 여비 규정」 제30조 및 별표 9 제5호를 준용한다. <개정 2011.1.4, 2018.2.20>', 108);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (828, '제15조(예외규정) 천재지변이나 그 밖의 특별한 사정이 있는 때에는 호송할 그 관서의 장은 법무부장관의 허가를 받아 제2조, 제4조부터 제7조까지, 제11조 및 제12조에 따르지 아니할 수 있다. <개정 2011.1.4>', 108);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (829, '제1조(목적) 이 법은 국제적으로 협력하여 마약류와 관련된 불법행위를 조장하는 행위 등을 방지함으로써 마약류범죄의 진압과 예방을 도모하고, 이에 관한 국제협약을 효율적으로 시행하기 위하여 「마약류관리에 관한 법률」과 그 밖의 관계 법률에 대한 특례 등을 규정함을 목적으로 한다.', 109);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (830, '제2조(정의)', 109);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (831, '제3조(입국 절차 및 상륙 절차의 특례)', 110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (832, '제4조(세관 절차의 특례)', 110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (833, '제5조(금융회사등에 의한 신고)', 110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (834, '제6조(업으로서 한 불법수입 등)', 111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (835, '제7조(불법수익등의 은닉 및 가장)', 111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (836, '제8조(불법수익등의 수수) 불법수익이라는 정황을 알면서 불법수익등을 수수한 자는 3년 이하의 징역 또는 1천만원 이하의 벌금에 처하거나 이를 병과할 수 있다. 다만, 법령에 따른 의무이행으로서 제공된 것을 수수한 자 또는 계약(채권자에게 상당한 재산상의 이익을 제공하는 것만 해당한다) 당시에 그 계약에 관련된 채무의 이행이 불법수익등에 의하여 이루어지는 것이라는 정황을 알지 못하고 그 계약에 관련된 채무의 이행으로서 제공된 것을 수수한 자의 경우에는 그러하지 아니하다.', 111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (837, '제9조(마약류 물품의 수입 등)', 111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (838, '제10조(선동 등) 마약류범죄(제9조 및 이 조의 범죄는 제외한다), 제7조 또는 제8조의 범죄의 실행 또는 마약류의 남용을 공연히 선동하거나 권유한 자는 3년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (839, '제11조(불법수익등에 대한 미신고 등) 제5조를 위반한 자는 2년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (840, '제12조(국외범) 제6조부터 제8조까지 및 제10조는 「형법」 제5조의 예에 따라 대한민국 영역 밖에서 해당 죄를 범한 외국인에게도 적용한다.', 111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (841, '제13조(불법수익등의 몰수)', 111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (842, '제14조(불법수익등이 합하여진 재산의 몰수) 제13조제1항 각 호 또는 같은 조 제3항 각 호에 따른 재산(이하 "불법재산"이라 한다)이 불법재산 외의 재산과 합하여진 경우 그 불법재산을 몰수하여야 할 때에는 그것이 합하여짐으로써 생긴 재산(이하 "혼합재산"이라 한다) 중 그 불법재산(합하여지는 데에 관련된 부분만 해당한다)의 금액 또는 수량에 상당하는 부분을 몰수할 수 있다.', 111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (843, '제15조(몰수의 요건 등)', 111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (844, '제16조(추징)', 111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (845, '제17조(불법수익의 추정) 제6조의 죄에 관계된 불법수익을 산정할 때에 같은 조에 따른 행위를 업으로 한 기간에 범인이 취득한 재산으로서 그 가액이 그 기간 동안 범인의 재산 운용 상황 또는 법령에 따른 지급금의 수령 상황 등에 비추어 현저하게 고액(高額)이라고 인정되고, 그 취득한 재산이 불법수익 금액 및 재산 취득 시기 등 모든 사정에 비추어 같은 조의 죄를 범하여 얻은 불법수익으로 형성되었다고 볼만한 상당한 개연성이 있는 경우에는 그 죄에 관계된 불법수익등으로 추정한다.', 111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (846, '제18조(양벌규정)', 111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (847, '제19조(권리 존속의 선고) 법원은 지상권ㆍ저당권 또는 그 밖의 권리가 그 위에 존재하는 재산을 몰수하는 경우, 제15조제2항에 따라 그 권리를 존속시킬 때에는 몰수의 선고와 동시에 그 취지를 선고하여야 한다.', 112);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (848, '제20조(몰수된 재산의 처분 등)', 112);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (849, '제21조(몰수재판에 따른 등기등)', 112);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (850, '제22조(형사보상의 특례) 부동산이나 동산이 아닌 재산의 몰수집행에 대한 형사보상에 관하여는 「형사보상 및 명예회복에 관한 법률」 제5조제6항을 준용한다. <개정 2011.5.23>', 112);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (851, '제23조(고지)', 113);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (852, '제24조(참가 절차)', 113);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (853, '제25조(참가인의 권리)', 113);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (854, '제26조(참가인의 출석 등)', 113);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (855, '제27조(증거)', 113);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (856, '제28조(몰수재판의 제한) 제3자가 참가허가를 받지 못한 경우에는 다음 각 호의 어느 하나에 해당하는 경우를 제외하고는 제3자가 가진 재산이나 제3자가 지상권ㆍ저당권 또는 그 밖의 권리를 그 위에 가지고 있는 재산에 대하여 몰수재판을 할 수 없다.', 113);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (857, '제29조(상소)', 113);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (858, '제30조(대리인)', 113);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (859, '제31조(「형사소송법」의 준용)', 113);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (860, '제32조(다른 절차와의 관계) 제23조제1항에 따른 재산을 몰수하는 재판은 자기의 책임으로 돌릴 수 없는 사유로 피고인에 대한 형사사건 절차에서 권리를 주장할 수 없었던 제3자의 권리에는 영향을 미치지 아니한다.', 113);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (861, '제33조(몰수보전명령)', 115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (862, '제34조(기소 전 몰수보전명령)', 115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (863, '제35조(몰수보전에 관한 재판의 집행)', 115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (864, '제36조(몰수보전의 효력) 몰수보전된 재산(이하 "몰수보전재산"이라 한다)에 대하여 그 보전 후에 된 처분은 몰수에 관하여 그 효력을 발생하지 아니한다. 다만, 제47조제1항 본문에 따른 경우(제50조제4항 및 제5항에 따라 준용되는 경우를 포함한다)와 몰수보전명령에 대항할 수 있는 담보권의 실행으로서의 처분인 경우에는 그러하지 아니하다.', 115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (865, '제37조(부동산의 몰수보전)', 115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (866, '제38조(선박 등의 몰수보전) 등기할 수 있는 선박, 「항공안전법」에 따라 등록된 항공기, 「자동차관리법」에 따라 등록된 자동차, 「건설기계관리법」에 따라 등록된 건설기계, 그 밖에 등기 또는 등록에 의하여 권리 변동이 이루어지는 물건 등의 몰수보전에 관하여는 부동산에 대한 몰수보전의 예에 따른다. <개정 2016.3.29>', 115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (867, '제39조(동산의 몰수보전)', 115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (868, '제40조(채권의 몰수보전)', 115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (869, '제41조(그 밖의 재산권에 대한 몰수보전)', 115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (870, '제42조(몰수보전명령의 취소)', 115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (871, '제43조(몰수보전명령의 실효)', 115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (872, '제44조(실효된 경우의 조치) 검사는 몰수보전이 실효된 때에는 지체 없이 몰수보전등기에 대한 말소 촉탁을 하고, 공시서를 제거하거나 그 밖에 필요한 조치를 하여야 한다.', 115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (873, '제45조(몰수보전재산에 대한 강제집행 절차의 제한)', 115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (874, '제46조(제3채무자의 공탁)', 115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (875, '제47조(강제집행의 대상이 된 재산의 몰수제한)', 115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (876, '제48조(강제집행의 정지)', 115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (877, '제49조(담보권의 실행을 위한 경매 절차와의 조정)', 115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (878, '제50조(그 밖의 절차와의 조정)', 115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (879, '제51조(부대보전명령의 효력 등)', 115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (880, '제52조(추징보전명령)', 116);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (881, '제53조(기소 전 추징보전명령)', 116);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (882, '제54조(추징보전명령의 집행)', 116);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (883, '제55조(금전채권 채무자의 공탁) 추징보전명령에 따라 추징보전이 집행된 금전채권의 채무자는 그 채권액에 상당하는 금액을 공탁할 수 있다. 이 경우 채권자의 공탁금 출급청구권에 대하여 추징보전집행이 된 것으로 본다.', 116);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (884, '제56조(추징보전해방금 공탁 및 추징 등에 대한 재판의 집행)', 116);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (885, '제57조(추징보전명령의 취소) 법원은 추징보전의 이유 또는 필요가 없게 되거나 추징보전기간이 부당하게 길어진 경우에는 검사, 피고인ㆍ피의자나 그 변호인의 청구 또는 법원의 직권에 의한 결정으로 추징보전명령을 전부 또는 일부 취소하여야 한다. 이 경우 제42조제2항을 준용한다. <개정 2020.6.9>', 116);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (886, '제58조(추징보전명령의 실효)', 116);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (887, '제59조(추징보전명령이 실효된 경우의 조치) 검사는 추징보전명령이 실효되거나 추징보전해방금이 공탁된 경우에는 신속하게 제54조제1항에 따른 명령을 취소함과 동시에 추징보전명령에 따른 추징보전집행의 정지 또는 취소를 위하여 필요한 조치를 하여야 한다.', 116);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (888, '제60조(송달) 몰수보전 또는 추징보전(추징보전명령에 따른 추징보전집행은 제외한다. 이하 이 절에서 같다)에 관한 서류의 송달에 관하여는 대법원규칙에 특별한 규정이 있는 경우를 제외하고는 민사소송에 관한 법령의 규정을 준용한다. 이 경우 「민사소송법」 제194조제1항에 따른 공시송달의 효력발생시기에 관하여는 같은 법 제196조제1항 본문 및 제2항에도 불구하고 그 기간을 7일로 한다.', 117);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (889, '제61조(상소제기기간 중의 처분 등) 상소제기기간에 발생한 사건으로서 아직 상소가 제기되지 아니한 사건과 상소하였으나 소송 기록이 상소법원에 도달하지 아니한 사건에 관하여 몰수보전 또는 추징보전에 관한 처분을 하여야 할 경우에는 원심법원이 그 처분을 하여야 한다.', 117);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (890, '제62조(불복신청)', 117);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (891, '제63조(준용) 몰수보전 및 추징보전에 관한 절차에 관하여는 이 법에 특별한 규정이 있는 경우를 제외하고는 「형사소송법」을 준용한다.', 117);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (892, '제64조(공조의 실시)', 118);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (893, '제65조(추징으로 보는 몰수)', 118);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (894, '제66조(요청의 접수) 공조요청의 접수는 외교부장관이 한다. 다만, 긴급한 조치가 필요한 경우나 특별한 사정이 있는 경우에는 법무부장관이 외교부장관의 동의를 받아 그 요청을 접수할 수 있다. <개정 2013.3.23>', 118);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (895, '제67조(법원의 심사)', 118);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (896, '제68조(항고)', 118);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (897, '제69조(결정의 효력) 몰수 또는 추징에 관한 확정재판 집행의 공조요청에 대하여 공조허가 결정이 확정되었을 때에는 그 몰수 또는 추징에 관한 확정재판은 공조의 실시에 관하여 대한민국 법원이 선고한 몰수 또는 추징의 확정재판으로 본다.', 118);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (898, '제70조(결정의 취소)', 118);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (899, '제71조(몰수보전의 청구)', 118);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (900, '제72조(추징보전의 청구)', 118);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (901, '제73조(공소 제기 전의 보전기간)', 118);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (902, '제74조(절차의 취소)', 118);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (903, '제75조(사실의 조사) 법원 또는 판사는 이 장에 따른 심사ㆍ몰수보전 또는 추징보전에 관한 처분을 할 필요가 있을 때에는 사실의 조사를 할 수 있다. 이 경우 증인을 신문하거나 검증을 할 수 있고 감정ㆍ통역 또는 번역을 명할 수 있다.', 118);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (904, '제76조(검사의 처분)', 118);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (905, '제77조(관할 법원) 이 장에 따른 심사, 몰수보전, 추징보전 또는 영장발급의 청구는 청구한 검사가 소속하는 검찰청의 소재지를 관할하는 지방법원이나 그 지원 또는 그에 소속된 판사에게 하여야 하고, 고위공직자범죄수사처에 소속된 검사의 경우에는 그에 대응하는 법원의 판사에게 하여야 한다. <개정 2021.1.5>', 118);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (906, '제78조(준용) 이 장에 특별한 규정이 있는 경우를 제외하고는 법원 또는 법관이 한 심사, 처분 또는 영장의 발급, 검사 또는 사법경찰관리 등이 한 처분, 이해관계인의 참가에 대하여는 이 법 제4장부터 제6장까지, 「형사소송법」, 「형사소송비용 등에 관한 법률」을 준용하고, 공조요청을 수리한 경우 그 조치에 대하여는 「국제형사사법 공조법」 및 「범죄인인도법」을 각각 그 성질에 반하지 아니하는 범위에서 준용한다.', 118);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (907, '제1조(목적) 이 영은 「마약류 불법거래 방지에 관한 특례법」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 119);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (908, '제2조 삭제 <2011.8.3>', 119);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (909, '제3조(금융기관의 신고사항) 「마약류 불법거래 방지에 관한 특례법」(이하 "법"이라 한다) 제5조제1항에 따라 금융기관에 종사하는 사람이 신고를 하는 경우에는 다음 각 호의 사항을 적은 서면을 검찰총장에게 제출하여야 한다.', 119);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (910, '제1조(목적) 이 영은 「형사사법절차에서의 전자문서 이용 등에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 120);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (911, '제2조(정의) 이 영에서 사용하는 용어의 뜻은 다음과 같다.', 120);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (912, '제3조(전자문서를 제출할 수 있는 자) 「형사사법절차에서의 전자문서 이용 등에 관한 법률」(이하 "법"이라 한다) 제5조제1항에 따라 피의자, 피고인, 피해자, 고소인, 고발인 및 변호인 외에 전산정보처리시스템을 통해 전자문서를 제출할 수 있는 자는 다음 각 호와 같다.', 120);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (913, '제4조(사용자등록)', 121);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (914, '제5조(사용자등록의 철회 등)', 121);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (915, '제6조(사용자등록의 말소 등)', 121);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (916, '제7조(전자서명 등)', 122);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (917, '제8조(전자문서의 접수 방법ㆍ절차 등)', 122);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (918, '제9조(전자문서의 제출 등)', 122);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (919, '제10조(전자문서의 동일성 확인 등)', 122);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (920, '제11조(전자화문서의 제출 등)', 122);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (921, '제12조(멀티미디어 자료의 제출 등)', 122);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (922, '제13조(제출된 전자문서의 보완 등)', 122);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (923, '제14조(수사 관련 자료의 요구)', 122);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (924, '제15조(전자문서로 작성하지 않을 수 있는 경우)', 123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (925, '제16조(피의자신문조서의 작성 등)', 123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (926, '제17조(「특정범죄신고자 등 보호법」에 따른 조서 등의 작성)', 123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (927, '제18조(전자화문서로의 변환ㆍ등재 제외 사유) 법 제11조제1항 단서에 따라 전자화대상문서를 전자적인 형태로 변환하는 것이 현저히 곤란하거나 적합하지 않은 경우로서 변환ㆍ등재하지 않을 수 있는 경우는 다음 각 호와 같다.', 123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (928, '제19조(전자화문서 등재 절차와 방법)', 123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (929, '제20조(전자화대상문서의 보관 및 확인)', 123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (930, '제21조(전자문서의 폐기ㆍ정정 등)', 123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (931, '제22조(전자문서의 유통 등)', 123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (932, '제23조(전자적 송달 또는 통지를 받을 자)', 124);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (933, '제24조(전자적 송달 또는 통지의 방법 등)', 124);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (934, '제25조(기간의 계산)', 124);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (935, '제26조(출력서면의 송달 등)', 124);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (936, '제27조(전자문서의 열람 등)', 125);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (937, '제28조(사건기록의 전자적 송부)', 125);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (938, '제29조(영장등의 사본 교부) 검사 또는 사법경찰관은 법 제17조제1항에 따라 전자문서로 발부된 영장, 감정유치장, 허가장, 형집행장, 허가서 및 요청서 등(이하 "영장등"이라 한다)을 제시하거나 전송하는 방법으로 집행을 완료한 후 그 사본을 교부하는 경우에는 해당 영장등의 사본이라는 표시를 한 파일을 전자우편, 문자전송 서비스 등을 통해 전송하거나 그러한 표시를 한 출력서면을 교부하는 방법으로 할 수 있다.', 125);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (939, '제30조(영장등의 반환) 검사 또는 사법경찰관은 법 제17조제1항에 따라 전자문서로 발부된 영장등을 「검사와 사법경찰관의 상호협력과 일반적 수사준칙에 관한 규정」 제35조에 따라 반환하는 경우 같은 조 제2항에 따른 반환사유 등에 관한 정보를 해당 영장등과 별개의 전자문서로 작성할 수 있다.', 125);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (940, '제31조(압수목록 등의 교부) 검사 또는 사법경찰관은 「형사소송법」 제128조(같은 법 제219조에 따라 준용되는 경우를 포함한다) 또는 제129조(같은 법 제219조에 따라 준용되는 경우를 포함한다)에 따라 증명서나 압수목록을 교부하는 경우 전자우편이나 문자전송 서비스 등을 통해 전송할 수 있다.', 125);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (941, '제32조(공판절차에서의 전자문서 제출 등)', 126);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (942, '제33조(이동통신단말장치의 활용)', 126);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (943, '제34조(재판의 집행지휘 시 전자문서 출력 등) 검사는 법 제19조제3항에 따라 전자문서를 출력하는 경우에는 전산정보처리시스템에 접속해 저장된 전자문서를 출력하는 방법으로 한다. 이 경우 출력하는 서면에 고유번호가 출력되도록 하는 등 전자문서의 동일성을 확보하기 위한 기술적 조치를 해야 한다.', 126);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (944, '제35조(전자문서의 이용ㆍ관리)', 127);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (945, '제36조(전산정보처리시스템의 운영)', 127);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (946, '제37조(전자문서의 폐기ㆍ보관)', 127);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (947, '제1조(목적) 이 규칙은 「가정폭력범죄의 처벌 등에 관한 특례법」에 따라 대법원규칙에 위임된 사항 등 가정보호사건, 피해자보호명령사건 및 배상명령의 처리에 필요한 사항을 규정함을 목적으로 한다.', 128);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (948, '제2조(관할)', 128);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (949, '제3조(결정서)', 128);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (950, '제4조(결정의 고지와 통지)', 128);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (951, '제5조(수탁기관 등에 대한 결정의 통지)', 128);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (952, '제6조(집행기관 등에 대한 결정의 통지)', 128);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (953, '제7조(검사에 대한 결정의 통지)', 128);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (954, '제8조(송치 및 이송의 방식)', 128);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (955, '제9조(임시조치 및 보호처분, 임시보호명령 및 피해자보호명령의 집행)', 128);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (956, '제10조(기록 등의 송부) 법원은 다음 각 호의 사건이 해당 호 각 목의 어느 하나에 해당하는 경우에는 사건기록(집행감독사건 기록을 포함한다)과 결정서를 대응하는 검찰청에 송부하여야 한다.', 128);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (957, '제11조(임시조치의 청구)', 130);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (958, '제12조(검사의 송치방식)', 130);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (959, '제13조(구속되어 인도된 행위자의 처리)', 130);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (960, '제14조(범죄사실 등의 고지) 판사는 가정보호사건을 접수한 때에는 행위자에게 다음 각 호의 사항을 서면으로 고지하여야 한다. 다만, 법 제12조에 따라 송치된 가정보호사건의 경우 행위자의 범죄사실은 고지하지 아니할 수 있다.', 130);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (961, '제15조(조회응답) 가정보호사건과 관계있는 기관은 그 사건내용에 관하여 재판, 수사 또는 다른 법률에 규정된 경우를 제외하고는 어떠한 조회에도 응하여서는 아니 된다.', 130);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (962, '제16조(조사의 방법)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (963, '제17조(조사보고서의 작성) 조사관은 조사의 결과를 의견을 붙인 서면으로 작성하여 보고하여야 한다.', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (964, '제18조(조사관에 대한 제척ㆍ기피ㆍ회피) 조사관에 대한 제척ㆍ기피ㆍ회피에 관하여는 「형사소송법」 제25조를 준용한다.', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (965, '제19조(소환)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (966, '제20조(수용 중인 행위자의 소환)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (967, '제21조(긴급동행영장의 기재사항) 긴급동행영장에는 법 제26조에서 정한 기재사항 외에 행위자가 소환에 응하지 아니할 우려가 있거나 피해자의 보호를 위하여 긴급히 필요한 이유를 기재하여야 한다.', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (968, '제22조(동행영장의 집행지휘)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (969, '제23조(동행영장의 집행)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (970, '제24조(동행영장에 따라 법원에 인치된 행위자의 처리)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (971, '제25조(보조인)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (972, '제26조(국선보조인) 국선보조인의 선임ㆍ보수 등 이 규칙에서 따로 정하지 아니한 사항에 관하여는 가정보호사건의 성질에 위반되지 아니하는 범위에서 「형사소송규칙」, 「형사소송비용 등에 관한 규칙」 중 국선변호인에 관한 규정을 준용한다.', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (973, '제27조(임시조치의 병과) 법 제29조제1항 각 호의 임시조치는 병과할 수 있다.', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (974, '제28조(임시위탁)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (975, '제29조(수탁기관의 지정)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (976, '제30조(임시위탁비용)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (977, '제31조(지급절차)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (978, '제32조(임시조치의 집행)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (979, '제33조(임시조치의 취소ㆍ변경)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (980, '제34조(이송 시 임시조치의 효력)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (981, '제35조(심리기일의 통지)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (982, '제36조(심리기일 변경 청구)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (983, '제37조(심리의 개시)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (984, '제38조(심리의 비공개)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (985, '제39조(심리의 방식 및 병합심리 등)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (986, '제40조(증인신문)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (987, '제41조(준용규정) 「형사소송규칙」 중 증인신문, 감정, 검증, 압수 또는 수색에 관한 규정은 가정보호사건의 성질에 위반되지 아니하는 범위에서 법 제34조ㆍ제35조에 따른 절차에 준용한다.', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (988, '제42조(심리조서)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (989, '제43조(서류 등의 열람ㆍ등사)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (990, '제44조(결정서의 등본ㆍ초본의 청구)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (991, '제45조(불처분 결정)', 131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (992, '제46조(보호처분)', 132);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (993, '제47조(친권 행사의 제한)', 132);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (994, '제48조(사회봉사ㆍ수강 명령 및 보호관찰)', 132);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (995, '제49조(감호ㆍ치료ㆍ상담 위탁)', 132);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (996, '제50조(치료ㆍ상담 위탁비용) 법 제40조제1항제7호ㆍ제8호의 보호처분에 따른 위탁비용의 예납 및 지급절차에 관하여는 제30조 및 제31조를 준용한다.', 132);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (997, '제51조(참고자료의 송부 등)', 132);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (998, '제52조(보호처분의 집행) 법 제43조제1항에 따른 보호처분의 집행지휘는 결정서 등본을 그 집행담당자에게 교부하는 것으로 한다.', 132);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (999, '제53조(몰수 결정의 집행 등) 몰수 결정의 집행, 몰수물의 처분 및 교부에 관하여는 판사가 「형사소송법」 중 몰수재판의 집행, 몰수물의 처분 및 교부에 관한 규정에 준하여 처리한다.', 132);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1000, '제54조(집행상황 보고)', 132);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1001, '제55조(보호처분의 변경ㆍ취소ㆍ종료)', 132);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1002, '제56조(보호처분과 형의 집행) 법 제40조제1항제1호부터 제3호까지 및 제6호부터 제8호까지의 보호처분이 집행 중인 행위자가 징역, 금고 또는 구류의 집행을 받게 된 때 및 법 제40조제1항제4호ㆍ제5호의 보호처분이 집행 중인 행위자가 구류의 집행을 받게 된 때에는 먼저 그 형을 집행한다. 이 경우 판사가 필요하다고 인정하는 경우에는 결정으로 그 보호처분을 종료할 수 있다.', 132);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1003, '제57조(항고 제기의 방식) 항고장에는 항고의 이유를 간결하게 명시하여야 한다.', 133);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1004, '제58조(임시조치에 대한 항고) 임시조치 및 그 연장ㆍ변경 결정에 대하여 항고가 제기된 경우 원심법원은 필요한 일부 기록의 등본을 항고법원으로 송부하고 기록의 원본에 의하여 이후의 절차를 진행할 수 있다.', 133);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1005, '제59조(항고의 취하)', 133);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1006, '제60조(수용 중인 행위자의 항고 제기)', 133);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1007, '제61조(항고법원의 조사)', 133);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1008, '제62조(항고법원의 사실조사)', 133);
