INSERT INTO balaw.jo (id, content, jang_id) VALUES (1012, '제66조(환송 또는 이송 후의 재판)', 133);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1013, '제67조(재항고법원의 재판)', 133);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1014, '제68조(재항고에 관한 준용) 재항고에 관하여는 그 성질에 위반되지 아니하는 범위에서 법 및 이 규칙의 항고에 관한 규정을 준용한다.', 133);
