INSERT INTO balaw.jo (id, content, jang_id) VALUES (1016, '제70조(보조인)', 135);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1017, '제71조(국선보조인)', 135);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1018, '제72조(이송)', 135);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1019, '제73조(청구의 취하 등)', 135);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1020, '제74조(임시보호명령)', 136);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1021, '제75조(임시보호명령의 병과) 법 제55조의2제1항 각 호에 해당하는 임시보호명령은 병과할 수 있다.', 136);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1022, '제76조(이송 시 임시보호명령의 효력) 제72조에 따라 피해자보호명령사건을 이송하는 경우에 이미 행하여진 임시보호명령은 그 효력을 잃지 않는다.', 136);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1023, '제77조(임시보호명령의 집행)', 136);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1024, '제78조(임시보호명령의 취소ㆍ변경)', 136);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1025, '제79조(조사의 방법)', 137);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1026, '제80조(심리기일의 지정)', 137);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1027, '제81조(소환)', 137);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1028, '제82조(심리의 개시)', 137);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1029, '제83조(병합심리 등)', 137);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1030, '제84조(증인신문) 법 제55조의7에 따라 준용되는 법 제32조제2항에 따른 증인신문의 비공개 신청에 대해서는 결정을 하고 신청인에게 그 결정을 통지하여야 한다.', 137);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1031, '제85조(준용규정) 「형사소송규칙」중 증인신문, 감정, 검증, 압수 또는 수색에 관한 규정은 피해자보호명령사건의 성질에 위배되지 아니하는 범위에서 법 제55조의7에 따라 준용되는 법 제34조ㆍ제35조에 따른 절차를 준용한다.', 137);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1032, '제86조(심리조서)', 137);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1033, '제87조(서류 등의 열람ㆍ등사)', 137);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1034, '제88조(결정서의 등본ㆍ초본의 청구)', 137);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1035, '제89조(기각결정)', 137);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1036, '제90조(준용규정) 피해자보호명령의 조사ㆍ심리에 관하여는 제17조, 제18조, 제20조, 제36조, 제38조를 준용한다.', 137);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1037, '제91조(피해자보호명령)', 138);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1038, '제92조(피해자보호명령의 집행) 피해자보호명령의 집행에 관하여는 제77조를 준용한다.', 138);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1039, '제93조(이행실태의 보고) 법 제55조의5제1항에 따른 이행실태의 조사명령을 받은 조사관 등은 의견을 붙인 서면으로 그 결과를 보고하여야 한다.', 138);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1040, '제94조(피해자보호명령의 취소ㆍ변경ㆍ연장)', 138);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1041, '제95조(준용규정) 친권 행사의 제한 및 가족관계등록부 기록의 촉탁에 관하여는 제47조를 준용한다.', 138);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1042, '제96조(파기자판)', 139);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1043, '제97조(항고ㆍ재항고의 추후 보완) 피해자, 청구인 및 행위자가 책임질 수 없는 사유로 항고기간 또는 재항고기간을 지킬 수 없었던 경우에는 그 사유가 없어진 날부터 7일 이내에 게을리 한 항고 또는 재항고를 보완할 수 있다. 다만, 그 사유가 없어질 당시 외국에 있던 피해자, 청구인 및 행위자에 대해서는 그 기간을 30일로 한다.', 139);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1044, '제98조(준용규정) 피해자보호명령 등의 항고 및 재항고에 관하여는 제57조부터 제62조까지, 제66조부터 제68조까지의 규정을 준용한다.', 139);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1045, '제99조(증거 신청)', 140);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1046, '제100조(증거조사)', 140);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1047, '제101조(피해자에 대한 통지)', 140);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1048, '제102조(배상명령에 대한 불복)', 140);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1049, '제103조(재판정본의 작성ㆍ보존)', 140);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1050, '제104조(재판정본의 교부)', 140);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1051, '제105조(준용규정) 「소송촉진 등에 관한 특례법」 제27조부터 제30조까지, 제34조제4항, 제35조 및 「소송촉진 등에 관한 특례규칙」 제20조부터 제23조까지의 규정은 가정보호사건의 성질에 반하지 아니하는 범위에서 배상명령절차에 준용한다.', 140);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1052, '제1조(목적) 이 영은 「특정경제범죄 가중처벌 등에 관한 법률」에서 위임된 사항과 그 시행에 관하여 필요한 사항을 정함을 목적으로 한다. <개정 2009.7.7>', 141);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1053, '제2조(대출등의 범위) 「특정경제범죄 가중처벌 등에 관한 법률」(이하 "법"이라 한다) 제2조제3호에서 "대통령령으로 정하는 것"이란 다음 각 호의 어느 하나에 해당하는 것을 말한다. <개정 2009.7.7, 2019.5.7>', 141);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1054, '제3조(감독기관의 감독업무에 종사하는 사람의 범위) 법 제12조제2항에 따른 감독기관의 감독업무에 종사하는 사람은 다음 각 호의 어느 하나에 해당하는 기관의 임ㆍ직원으로서 소관 금융회사등에 대한 감사 또는 검사의 직무(일시적인 감사 또는 검사의 직무의 경우를 포함한다)에 종사하는 사람 및 그 직무를 관장하는 상급자와 해당 감독기관의 장으로 한다. <개정 1998ㆍ4ㆍ1, 2019.5.7>', 141);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1055, '제4조 삭제 <2009.7.7>', 141);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1056, '제5조 삭제 <2009.7.7>', 141);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1057, '제6조 삭제 <2009.7.7>', 141);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1058, '제7조 삭제 <2009.7.7>', 141);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1059, '제8조 삭제 <2009.7.7>', 141);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1060, '제9조(수사기관의 통보등)', 141);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1061, '제10조(취업제한대상인 기관 및 기업체의 범위)', 141);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1062, '제11조(허가등이 금지되는 관허업의 범위) 법 제14조제2항에서 "대통령령으로 정하는 관허업"이란 특정한 사업ㆍ영업 또는 행위를 업으로 하기 위하여 행정기관으로부터 허가ㆍ인가ㆍ면허ㆍ등록ㆍ지정ㆍ승인 및 특허(이하 "허가등"이라 한다)를 받아야 할 대상으로서 그 처분청이 중앙행정기관의 장, 특별시장, 광역시장, 특별자치시장, 도지사 또는 특별자치도지사인 경우(법령에 따라 그 허가등의 권한이 하부기관 또는 다른 기관에 위임 또는 위탁된 경우를 포함한다)의 해당 사업ㆍ영업 또는 행위를 말한다. <개정 2019.5.7>', 141);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1063, '제12조(취업제한사실등의 통지) 법무부장관은 법 제3조ㆍ법 제4조제2항(미수범을 포함한다)ㆍ법 제5조제4항 또는 법 제8조의 죄를 범한 사람에 대한 재판결과를 항상 파악하여 그에 대한 유죄판결이 확정된 때에는 지체 없이 법 제14조제1항 및 제2항에 따른 취업제한 및 허가등 금지사실과 그 대상의 범위를 그 판결이 확정된 사람에게 통지하여야 한다. <개정 2009.7.7, 2019.5.7>', 141);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1064, '제13조(취업승인신청)', 141);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1065, '제14조(관허업의 허가등 승인신청)', 141);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1066, '제15조(민감정보 및 고유식별정보 등의 처리)', 141);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1067, '제1조(목적) 이 법은 전과기록(前科記錄) 및 수사경력자료의 관리와 형의 실효(失效)에 관한 기준을 정함으로써 전과자의 정상적인 사회복귀를 보장함을 목적으로 한다.', 142);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1068, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다. <개정 2021.3.16>', 142);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1069, '제3조(수형인명부) 지방검찰청 및 그 지청과 보통검찰부에서는 자격정지 이상의 형을 선고한 재판이 확정되면 지체 없이 그 형을 선고받은 수형인을 수형인명부에 기재하여야 한다.', 142);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1070, '제4조(수형인명표)', 142);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1071, '제5조(수사자료표)', 142);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1072, '제5조의2(수사자료표의 관리 등)', 142);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1073, '제6조(범죄경력조회ㆍ수사경력조회 및 회보의 제한 등)', 142);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1074, '제7조(형의 실효)', 142);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1075, '제8조(수형인명부 및 수형인명표의 정리)', 142);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1076, '제8조의2(수사경력자료의 정리)', 142);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1077, '제8조의3(자료제출 및 시정 요구)', 142);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1078, '제9조(벌칙)', 142);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1079, '제10조(벌칙)', 142);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1080, '제11조 삭제 <2002.12.5>', 142);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1081, '제1조(목적) 이 영은 「형의 실효 등에 관한 법률」에서 위임된 사항과 그 시행에 관하여 필요한 사항을 규정함을 목적으로 한다. <개정 2006.7.27, 2022.7.5>', 143);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1082, '제2조(수사자료표의 작성 등)', 143);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1083, '제2조의2 삭제 <2022.7.5>', 143);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1084, '제3조(고등검찰부에서의 수형인명부기재) 군사법원의 재판에 대한 상소심에서 자격정지 이상의 형을 선고한 재판이 확정된 경우에는 해당 고등검찰부에서도 그 사실을 수형인명부에 기재할 수 있다. <개정 1984ㆍ10ㆍ6, 1993ㆍ9ㆍ4, 2022.6.30>', 143);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1085, '제4조(수형인명표의 작성ㆍ송부) 「형의 실효 등에 관한 법률」(이하 "법"이라 한다) 제3조 및 이 영 제3조에 따라 자격정지 이상의 형을 선고한 재판이 확정된 사실을 수형인명부에 기재한 때에는 지체 없이 수형인명표를 작성하여 수형인의 등록기준지 시ㆍ구ㆍ읍ㆍ면사무소에 등기우편으로 송부하거나 「전자정부법」 제37조제1항에 따른 행정정보공동이용센터를 통하여 전자적인 방법으로 송부하여야 한다. <개정 1984ㆍ10ㆍ6, 2007.8.7, 2010.5.4, 2012.4.23, 2022.7.5>', 143);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1086, '제5조(집행유예실효 등의 통지) 제4조에 따라 수형인명표를 송부한 검찰청, 그 지청 또는 군검찰부는 수형인에 관하여 법 제4조제2항 각 호의 어느 하나에 해당되는 사유가 발생한 때에는 지체 없이 수형인명표를 송부한 관서에 그 사실을 등기우편으로 통지하거나 「전자정부법」 제37조제1항에 따라 설치된 행정정보공동이용센터를 통하여 전자적인 방법으로 통지하여야 한다. 다만, 제4조에 따라 수형인명표를 송부할 때에 미리 집행유예기간 또는 법 제7조에 따른 형의 실효기간을 부기(附記)한 경우에는 그 부기로써 법 제4조제2항 각 호의 사유의 통지 중 집행유예기간이 경과한 사실 또는 법 제7조에 따른 형의 실효사실의 통지에 갈음할 수 있다. <개정 2010.5.4, 2022.6.30>', 143);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1087, '제6조(수사자료표를 작성할 사법경찰관의 범위) 법 제5조제1항 각 호 외의 부분 본문에 따라 수사자료표를 작성할 사법경찰관의 범위는 다음 각 호와 같다.', 143);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1088, '제6조의2(전과기록 또는 수사경력자료의 보존ㆍ관리 및 회보 등)', 143);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1089, '제7조(수사자료표의 조회 및 회보 범위)', 143);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1090, '제7조의2(소년 및 실효된 형 등에 관한 회보 제한)', 143);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1091, '제8조(수형인명부 등의 정리)', 143);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1092, '제9조(수사자료표의 폐기)', 143);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1093, '제10조(민감정보 및 고유식별정보의 처리) 수사자료표, 전과기록 또는 수사경력자료의 보존ㆍ관리업무 및 조회ㆍ회보업무를 담당하는 기관의 장은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 범죄경력자료에 해당하는 정보, 「개인정보 보호법 시행령」 제18조제3호에 따른 개인의 신체적, 생리적, 행동적 특징에 관한 정보로서 특정 개인을 알아볼 목적으로 일정한 기술적 수단을 통해 생성한 정보(제2호의 사무를 수행하는 경우로 한정한다)와 같은 영 제19조제1호, 제2호 또는 제4호에 따른 주민등록번호, 여권번호 또는 외국인등록번호를 처리할 수 있다.', 143);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1094, '제1조(목적) 이 규칙은 「성폭력범죄의 처벌 등에 관한 특례법」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1095, '제2조(신상정보의 제출) 법 제43조제1항 및 제3항에 따른 기본신상정보 및 변경정보의 제출은 별지 제1호서식에 따른다.', 144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1096, '제3조(신상정보 제출 확인서 등)', 144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1097, '제4조(출소예정자에 대한 신상정보 제출내용 송부) 교정시설의 장 또는 치료감호시설의 장이 영 제3조제6항에 따라 법무부장관에게 법 제42조제1항에 따른 신상정보 등록대상자(이하 "등록대상자"라 한다) 사진의 전자기록 등을 송달할 때에는 별지 제4호서식에 따른다.', 144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1098, '제5조(출입국신고서)', 144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1099, '제6조(등록정보 원부의 작성) 영 제5조제1항에 따른 성범죄자 등록정보 원부는 별지 제7호서식과 같으며, 컴퓨터 파일로 작성ㆍ관리하여야 한다.', 144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1100, '제7조(등록정보의 통지 신청 등)', 144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1101, '제8조(등록정보 진위 여부 등의 확인 결과 송부) 법 제45조제7항 및 제8항에 따른 등록정보의 진위와 변경 여부 확인 결과의 송부는 별지 제10호서식에 따른다.', 144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1102, '제9조(신상정보 등록 면제 신청서 등)', 144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1103, '제10조(등록정보 폐기 사실의 통지 신청서 등)', 144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1104, '제11조(등록정보의 공개 및 고지에 필요한 정보의 송부) 영 제8조제1항에 따른 정보의 송부는 별지 제15호서식에 따른다.', 144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1105, '제1조(목적) 이 법은 「국제연합부패방지협약」 및 그 밖의 관련 국제협약을 효율적으로 이행하기 위하여 부패재산의 몰수 및 추징, 환수 등에 관한 특례를 규정함으로써 부패범죄를 조장하는 경제적 요인을 근원적으로 제거하여 부패범죄를 효과적으로 방지ㆍ척결하고 청렴한 국제사회질서 확립에 이바지함을 목적으로 한다.', 145);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1106, '제2조(정의) 이 법에서 사용하는 용어의 정의는 다음과 같다. <개정 2016.12.20, 2019.8.20>', 145);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1107, '제3조(부패재산의 몰수)', 146);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1108, '제4조(몰수의 요건 등)', 146);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1109, '제5조(추징)', 146);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1110, '제6조(범죄피해재산의 특례)', 146);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1111, '제7조(국제공조의 실시) 부패범죄에 해당하는 행위에 대한 외국의 형사사건과 관련하여 그 외국으로부터 집행재산등의 반환요청이 있는 때에는 다음 각 호의 어느 하나에 해당하는 경우를 제외하고는 그 요청에 관하여 공조할 수 있다.', 147);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1112, '제8조(「마약류 불법거래방지에 관한 특례법」의 준용) 이 법에 따른 몰수 및 추징과 국제공조에 관하여는 「마약류 불법거래방지에 관한 특례법」 제19조부터 제63조까지, 제64조제2항 및 제65조부터 제78조까지의 규정을 준용한다.', 147);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1113, '제9조(반환요청의 접수 및 집행재산등의 인도) 반환요청의 접수와 요청국에 대한 집행재산등의 인도는 외교부장관이 행한다. 다만, 긴급을 요하는 사정이나 특별한 사정이 있는 경우에는 법무부장관이 외교부장관의 동의를 받아 이를 행할 수 있다. <개정 2013.3.23>', 148);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1114, '제10조(반환요청서의 송부) 외교부장관은 요청국으로부터 집행재산등의 반환요청을 받은 때에는 반환요청서를 법무부장관에게 송부하여야 한다. <개정 2013.3.23>', 148);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1115, '제11조(집행재산등의 반환 결정 등)', 148);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1116, '제12조(반환 관련 협의) 법무부장관은 이 법에 따라 집행재산등을 반환할 수 없거나 반환하지 아니하는 것이 상당하다고 인정하는 경우 또는 반환을 연기하려는 경우에는 외교부장관과 협의하여야 한다. <개정 2013.3.23>', 148);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1117, '제13조(검사장의 조치)', 148);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1118, '제14조(집행재산등의 이관)', 148);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1119, '제15조(해외 부패재산의 환수요청)', 148);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1120, '제16조(환수요청서의 송부) 외교부장관은 법무부장관으로부터 제15조에 따른 환수요청서를 송부받은 때에는 이를 해당 국가에 송부하여야 한다. 다만, 외교관계상 환수요청하는 것이 상당하지 아니하다고 인정하는 경우에는 이에 관하여 법무부장관과 협의하여야 한다. <개정 2013.3.23>', 148);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1121, '제17조(해외 집행재산등의 환수 등)', 148);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1122, '제18조(해외 집행재산등의 처분)', 148);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1123, '제19조(부패범죄 신고자의 보호) 부패범죄 신고자의 보호에 관하여는 「특정범죄신고자 등 보호법」 제3조부터 제17조까지의 규정을 준용한다.', 149);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1124, '제20조(「형사소송법」의 준용 등)', 149);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1125, '제21조(검찰총장 경유) 이 법에 따라 법무부장관이 검사장 또는 검사에게 하는 명령ㆍ서류송부와 검사장 또는 검사가 법무부장관에게 하는 보고ㆍ서류송부는 검찰총장을 거쳐야 한다. 다만, 고위공직자범죄수사처장 또는 그 소속 검사의 경우에는 그러하지 아니하다. <개정 2021.1.5>', 149);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1126, '제1조(목적) 이 영은 「부패재산의 몰수 및 회복에 관한 특례법」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 150);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1127, '제2조(정의) 이 영에서 사용하는 용어의 뜻은 다음과 같다.', 150);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1128, '제3조(범죄피해재산 환부절차의 개시 등)', 150);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1129, '제4조(손해배상청구권 등과의 관계) 피해자등이 범죄피해재산의 전부　또는 일부를 반환받았거나 범죄피해재산에 관하여 손해배상을 받았을 때에는 그 반환받거나 배상받은 재산의 범위에서 회복대상재산을 환부하지 않는다.', 150);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1130, '제5조(통지 및 공고)', 150);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1131, '제6조(범죄피해재산의 환부청구)', 150);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1132, '제7조(회복대상재산 환부 여부의 결정 등)', 150);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1133, '제8조(회복대상재산의 환부 실시)', 150);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1134, '제9조(추가 환부 등) 검사는 범죄피해재산 환부절차를 종료한 후 회복대상재산이 남아 있거나 해당 절차와 관련된 회복대상재산을 추가로 보관하게 된 경우로서 피해자등에게 이미 환부한 재산이 피해인정재산에 미치지 못할 때에는 제3조부터 제8조까지의 규정에 따라 추가로 환부해야 한다.', 150);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1135, '제10조(이의신청)', 150);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1136, '제11조(범죄피해재산환부심의회)', 150);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1137, '제12조(준용규정) 회복대상재산의 수리(受理)ㆍ영치(領置) 및 처분 절차 등에 관하여는 그 성질에 반하지 않는 범위에서 「검찰청법」 제11조에 따른 압수물 사무, 재산형(財産刑)의 집행사무 또는 각급 검찰청의 사건사무에 관한 규정을 준용한다.', 150);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1138, '제13조(민감정보 및 고유식별정보의 처리) 법무부장관과 검사는 법 제6조에 따른 범죄피해재산의 환부에 관한 사무를 처리하기 위해 불가피한 경우 「개인정보 보호법 시행령」 제18조제2호에 따른 범죄경력자료에 해당하는 정보나 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 150);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1139, '제1조(목적) 이 규칙은 「부패재산의 몰수 및 회복에 관한 특례법」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 151);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1140, '제2조(비용) 「부패재산의 몰수 및 회복에 관한 특례법 시행령」(이하 "영"이라 한다) 제2조제4호에서 "통지ㆍ공고 등 법무부령으로 정하는 환부절차에 드는 비용"이란 다음 각 호의 비용을 말한다.', 151);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1141, '제3조(통지)', 151);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1142, '제4조(범죄피해재산 환부청구의 방법)', 151);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1143, '제5조(청구사항의 변경신고)', 151);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1144, '제6조(검사의 회복대상재산 환부결정)', 151);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1145, '제7조(범죄피해재산 환부관리부 작성) 범죄피해재산 환부절차를 담당하는 검사는 청구인에게 회복대상재산을 환부한 때에는 별지 제6호서식의 범죄피해재산 환부관리부를 작성하여 소속 검찰청에 보관해야 한다.', 151);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1146, '제8조(청구인의 이의신청)', 151);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1147, '제9조(이의신청에 대한 결정)', 151);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1148, '제10조(범죄피해재산환부심의회의 운영)', 151);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1149, '제11조(위원의 제척ㆍ기피ㆍ회피)', 151);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1150, '제12조(위원의 해촉) 각 검찰청의 장은 영 제11조제5항에 따라 위촉된 위원이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 위원을 해촉(解觸)할 수 있다.', 151);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1151, '제1조(목적) 이 법은 형사사건의 수사 또는 재판과 관련하여 외국의 요청에 따라 실시하는 공조(共助) 및 외국에 대하여 요청하는 공조의 범위와 절차 등을 정함으로써 범죄를 진압하고 예방하는 데에 국제적인 협력을 증진함을 목적으로 한다.', 152);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1152, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다.', 152);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1153, '제3조(공조조약과의 관계) 공조에 관하여 공조조약에 이 법과 다른 규정이 있는 경우에는 그 규정에 따른다.', 152);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1154, '제4조(상호주의) 공조조약이 체결되어 있지 아니한 경우에도 동일하거나 유사한 사항에 관하여 대한민국의 공조요청에 따른다는 요청국의 보증이 있는 경우에는 이 법을 적용한다.', 152);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1155, '제5조(공조의 범위) 공조의 범위는 다음 각 호와 같다.', 153);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1156, '제6조(공조의 제한) 다음 각 호의 어느 하나에 해당하는 경우에는 공조를 하지 아니할 수 있다.', 153);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1157, '제7조(공조의 연기) 대한민국에서 수사가 진행 중이거나 재판에 계속(係屬)된 범죄에 대하여 외국의 공조요청이 있는 경우에는 그 수사 또는 재판 절차가 끝날 때까지 공조를 연기할 수 있다.', 153);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1158, '제8조(물건의 인도)', 153);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1159, '제9조(요청국에서의 협조)', 153);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1160, '제10조(외국으로의 송환을 위한 구속)', 153);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1161, '제11조(공조요청의 접수 및 공조 자료의 송부) 공조요청 접수 및 요청국에 대한 공조 자료의 송부는 외교부장관이 한다. 다만, 긴급한 조치가 필요한 경우나 특별한 사정이 있는 경우에는 법무부장관이 외교부장관의 동의를 받아 이를 할 수 있다. <개정 2013.3.23>', 154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1162, '제12조(공조요청서)', 154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1163, '제13조(공조의 방식) 요청국에 대한 공조는 대한민국의 법률에서 정하는 방식으로 한다. 다만, 요청국이 요청한 공조 방식이 대한민국의 법률에 저촉되지 아니하는 경우에는 그 방식으로 할 수 있다.', 154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1164, '제14조(외교부장관의 조치) 외교부장관은 요청국으로부터 형사사건의 수사에 관한 공조요청을 받았을 때에는 공조요청서에 관계 자료 및 의견을 첨부하여 법무부장관에게 송부하여야 한다. <개정 2013.3.23>', 154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1165, '제15조(법무부장관의 조치)', 154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1166, '제16조(검사장 등의 조치) 제15조제1항제1호에 따른 명령 또는 요구를 받은 검사장 또는 고위공직자범죄수사처장은 소속 검사에게 공조에 필요한 자료를 수집하거나 그 밖에 필요한 조치를 하도록 명하여야 한다. <개정 2021.1.5>', 154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1167, '제17조(검사 등의 처분)', 154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1168, '제18조(증인신문의 청구) 검사는 공조요청이 증인신문에 관계되는 경우이거나 관계인이 제17조제1항에 따른 출석 또는 진술을 거부한 경우에는 판사에게 증인신문을 청구할 수 있다.', 154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1169, '제19조(영장 등 청구 시 첨부서류) 검사가 공조를 위하여 영장, 인도허가 또는 증인신문을 청구할 때에는 제14조에 따른 공조요청서 등본을 첨부하여야 한다.', 154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1170, '제20조(관할 법원)', 154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1171, '제21조(공조 자료 등의 송부 등)', 154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1172, '제22조(법무부장관의 공조 자료 송부 등)', 154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1173, '제23조(법무부장관의 조치)', 155);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1174, '제24조(법원행정처장의 조치) 법원행정처장은 법무부장관으로부터 제23조제1항에 따른 공조요청서를 받았을 때에는 이를 관할 지방법원장에게 송부하여야 한다.', 155);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1175, '제25조(관할 법원) 형사재판에 관한 공조는 서류 등의 송달에 관한 요청인 경우에는 송달할 장소를 관할하는 지방법원이 하고, 증거조사에 관한 요청인 경우에는 증인 등의 주거지나 증거물 또는 검증ㆍ감정 목적물의 소재지를 관할하는 지방법원이 한다.', 155);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1176, '제26조(이송) 공조요청서를 받은 법원은 요청 사항이 그 관할에 속하지 아니하는 경우에는 결정(決定)으로 공조요청서를 관할 법원에 이송하고, 그 사실을 법원행정처장에게 통지하여야 한다.', 155);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1177, '제27조(증명서 등의 송부)', 155);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1178, '제28조(준용규정) 외국의 요청에 따른 형사재판에 관한 공조에 관하여는 제11조부터 제14조까지, 제15조제3항 및 제22조를 준용한다.', 155);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1179, '제29조(검사 등의 공조요청) 검사 또는 고위공직자범죄수사처장은 외국에 수사에 관한 공조요청을 하려면 법무부장관에게 공조요청서를 송부하여야 하고, 사법경찰관은 검사에게 신청하여 법무부장관에게 공조요청서를 송부하여야 한다. <개정 2021.1.5>', 156);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1180, '제30조(법무부장관의 조치) 제29조에 따른 공조요청서를 받은 법무부장관은 외국에 공조요청하는 것이 타당하다고 인정하는 경우에는 그 공조요청서를 외교부장관에게 송부하여야 한다. 다만, 긴급한 조치가 필요한 경우나 특별한 사정이 있는 경우에는 외교부장관의 동의를 받아 공조요청서를 직접 외국에 송부할 수 있다. <개정 2013.3.23>', 156);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1181, '제31조(외교부장관의 조치) 외교부장관은 법무부장관으로부터 제30조에 따른 공조요청서를 받았을 때에는 이를 외국에 송부하여야 한다. 다만, 외교 관계상 공조요청하는 것이 타당하지 아니하다고 인정하는 경우에는 이에 관하여 법무부장관과 협의하여야 한다. <개정 2013.3.23>', 156);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1182, '제32조(번역문의 첨부) 외국에 공조요청을 하는 경우에는 그 외국의 공용어로 된 공조요청서와 그 밖의 관계 서류의 번역문을 첨부하여야 한다. 다만, 해당 외국의 공용어를 알 수 없는 경우에는 영어로 된 번역문을 첨부할 수 있다.', 156);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1183, '제33조(법원의 공조요청)', 157);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1184, '제34조(법원행정처장과의 협의) 제33조제2항에 따른 공조요청서를 받은 법무부장관은 외국에 공조요청을 하는 것이 타당하지 아니하다고 인정하는 경우에는 법원행정처장과 협의하여야 한다.', 157);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1185, '제35조(준용규정) 외국에 대한 형사재판에 관한 공조요청에 대하여는 제30조부터 제32조까지의 규정을 준용한다.', 157);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1186, '제36조(비용)', 158);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1187, '제37조(명령 등의 검찰총장 경유) 법무부장관이 이 법에 따라 검사장 또는 검사에게 하는 명령이나 서류송부, 검사장 또는 검사가 법무부장관에게 하는 보고나 서류송부는 검찰총장을 거쳐야 한다. 다만, 고위공직자범죄수사처장 또는 그 소속 검사의 경우에는 그러하지 아니하다. <개정 2021.1.5>', 158);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1188, '제38조(국제형사경찰기구와의 협력)', 158);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1189, '제39조(「형사소송법」의 준용) 이 법에 따라 법원이나 판사가 하는 재판, 판사가 하는 영장 발급이나 증인신문, 검사나 사법경찰관이 하는 처분 등과 그 불복절차에 대하여는 이 법에 특별한 규정이 있는 경우를 제외하고는 그 성질에 반하지 아니하는 범위에서 「형사소송법」을 준용한다.', 158);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1190, '제40조(대법원규칙) 이 법에 따른 영장 발급, 증거물의 인도허가 결정, 증인신문 등의 절차에 관하여 필요한 사항은 대법원규칙으로 정한다.', 158);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1191, '제1조(목적) 이 영은 「성폭력범죄자의 성충동 약물치료에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 159);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1192, '제2조(정신건강의학과 전문의의 진단 및 감정)', 160);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1193, '제3조(조사)', 160);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1194, '제4조(치료명령 청구서의 기재사항)', 160);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1195, '제4조의2(치료명령의 집행 면제 신청 등)', 160);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1196, '제5조(인지행동 치료 등 심리치료 프로그램)', 160);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1197, '제6조(집행지휘)', 161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1198, '제7조(치료명령의 집행)', 161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1199, '제8조(치료약물의 지정)', 161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1200, '제9조(치료기관)', 161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1201, '제10조(수용시설 수용자의 이송 등)', 161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1202, '제11조(부작용에 대한 검사 및 치료)', 161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1203, '제12조(집행이 정지된 치료명령의 잔여기간 집행)', 161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1204, '제13조(치료명령을 받은 사람의 의무 등)', 161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1205, '제14조(주거 이전, 국내여행 및 출국의 허가 등)', 161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1206, '제15조(치료기간 연장 등의 신청)', 161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1207, '제16조(치료명령의 가해제 신청)', 161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1208, '제17조(치료명령 가해제의 심사 및 결정)', 161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1209, '제18조(가해제의 취소 등)', 161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1210, '제19조(수용시설의 장의 설명 및 동의 여부 확인) 수용시설의 장은 법 제22조제1항에 따른 성폭력 수형자(이하 "성폭력수형자"라 한다) 가운데 「형의 집행 및 수용자의 처우에 관한 법률」 제121조제1항에 따라 가석방 적격심사 신청 대상자로 선정된 사람에게 법 제22조제2항제1호에 따라 약물치료에 관한 사항을 서면으로 제시하여 설명하고, 약물치료에 동의한 경우에는 이를 서면으로 확인하여야 한다.', 162);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1211, '제20조(수용시설의 장의 통보) 수용시설의 장은 성폭력수형자가 제19조에 따라 약물치료에 동의한 경우에는 수용시설 소재지를 관할하는 지방검찰청(지청을 포함한다)의 검사에게 지체 없이 다음 각 호의 사항을 통보하여야 한다.', 162);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1212, '제21조(조사) 검사는 법 제22조제2항제3호에 따라 보호관찰소의 장에게 조사를 요청할 때에는 제20조 각 호의 사항을 통보하여야 한다.', 162);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1213, '제22조(검사의 치료명령 청구 등)', 162);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1214, '제23조(치료명령 청구사실의 통보) 검사는 법 제22조제2항제5호에 따라 성폭력수형자에 대하여 치료명령을 청구한 경우에는 치료명령피청구자에게 지체 없이 청구서를 송부하여야 한다.', 162);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1215, '제24조(집행지휘 등)', 162);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1216, '제25조(치료명령 결정문 송부) 법원은 법 제22조제2항제6호에 따라 성폭력수형자에게 치료명령을 고지한 날부터 3일 이내에 치료명령을 고지 받은 사람의 주거지를 관할하는 보호관찰소의 장에게 결정문 등본을 송부하여야 한다.', 162);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1217, '제26조(비용부담)', 162);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1218, '제27조(치료감호심의위원회의 감정 의뢰)', 162);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1219, '제28조(가종료자등에 대한 치료명령 결정의 통지 등)', 162);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1220, '제29조(준용)', 162);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1221, '제30조(민감정보 및 고유식별정보의 처리)', 163);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1222, '제1조(목적) 이 규칙은 「국민의 형사재판참여에 관한 법률」(이하 "법"이라 한다) 제55조제2항에 따라 국민사법참여위원회(이하 "위원회"라 한다)의 조직과 활동, 그 밖에 필요한 사항을 정하는 것을 목적으로 한다.', 164);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1223, '제2조(위원회의 구성)', 164);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1224, '제3조(위원장의 직무)', 164);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1225, '제4조(간사와 서기)', 164);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1226, '제5조(회의)', 164);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1227, '제6조(전문위원)', 164);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1228, '제7조(관계기관의 협조 등)', 164);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1229, '제8조(의견의 수렴) 위원회는 필요한 경우 공청회, 토론회, 여론조사 등을 통하여 각계의 의견을 수렴할 수 있다.', 164);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1230, '제9조(수당 등의 지급) 위원, 전문위원 또는 제7조에 따라 조사ㆍ연구를 수행한 사람 등에게는 예산의 범위에서 수당, 여비, 조사연구비 및 그 밖에 필요한 경비를 지급할 수 있다.', 164);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1231, '제10조(운영세칙) 이 규칙에 규정한 것 이외에 위원회의 운영에 필요한 사항은 위원회의 의결을 거쳐 위원장이 정한다.', 164);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1232, '제1조(목적) 이 법은 형사소송비용의 범위와 법원의 형사절차에서 증인ㆍ감정인ㆍ통역인ㆍ번역인 또는 국선변호인에게 지급하는 비용의 지급기준 등에 관하여 필요한 사항을 규정함을 목적으로 한다.', 165);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1233, '제2조(형사소송비용의 범위) 「형사소송법」에 따른 소송비용은 다음 각 호의 어느 하나에 해당하는 것으로 한다.', 165);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1234, '제3조(증인 등의 일당)', 165);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1235, '제4조(증인 등의 여비)', 165);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1236, '제5조(증인 등의 숙박료)', 165);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1237, '제6조(국외여비 등의 금액) 증인ㆍ감정인ㆍ통역인 또는 번역인이 국내와 국외(공해를 포함한다) 사이를 여행하는 경우에 그 일당, 여비 및 숙박료는 제3조부터 제5조까지에 규정된 기준에 준하여 대법원규칙으로 정하는 범위에서 법원이 정한다.', 165);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1238, '제7조(감정료 등) 감정인ㆍ통역인 또는 번역인에게 지급할 감정료ㆍ통역료ㆍ번역료, 그 밖의 비용은 법원이 적절하다고 인정하는 금액으로 한다.', 165);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1239, '제8조(국선변호인의 일당 등)', 165);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1240, '제9조(여비 등의 계산) 일당, 여비(항공운임은 제외한다) 및 숙박료를 계산할 때 여행 일수는 흔히 이용하는 가장 경제적인 경로와 방법으로 여행하는 경우의 예에 따라 계산한다. 다만, 천재지변이나 그 밖의 부득이한 사유로 그와 같은 경로와 방법으로 여행하기 곤란한 경우에는 실제 경로와 방법으로 계산한다.', 165);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1241, '제10조(일당 등의 지급 요건) 증인ㆍ감정인ㆍ통역인 또는 번역인에게 지급하는 일당, 여비 및 숙박료는 법원이 정한 기일ㆍ장소에 출석하거나 조사받은 경우에만 지급하며, 국선변호인에게 지급하는 일당, 여비 및 숙박료는 국선변호인이 기일에 출석하거나 조사 또는 처분에 참여한 경우에만 지급한다.', 165);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1242, '제11조(소송비용의 청구기한) 제2조에 따른 소송비용은 다음 각 호의 구분에 따른 기한까지 청구하지 아니하면 지급하지 아니한다. 다만, 부득이한 사유로 해당 기한까지 청구하지 못한 경우에는 그러하지 아니하다.', 165);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1243, '제12조(법관이 정하는 경우)', 165);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1244, '제13조(대법원규칙) 이 법에서 규정한 사항 외에 법원의 형사절차에서 지급하는 비용에 관하여 필요한 사항은 대법원규칙으로 정한다.', 165);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1245, '제14조(자료의 제출) 법원은 필요하다고 인정하면 이 법에 따라 비용을 지급받을 자에게 비용 명세서나 그 밖의 자료 제출 등을 요구할 수 있다.', 165);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1246, '제1조(목적) 이 영은 보건범죄단속에관한특별조치법(이하 "법"이라 한다)의 시행에 관하여 필요한 사항을 규정함을 목적으로 한다.', 166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1247, '제2조(용어의 정의) 이 영에서 "주된 성분"이라 함은 의약품의 효능에 직접적인 영향을 미치는 주약으로서 부약ㆍ부형제 또는 첨가제등이 아닌 것을 말한다.', 166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1248, '제3조(특정의약품) 법 제3조제1항제1호의 규정에서 "대통령령으로 정하는 의약품"은 다음 각호의 것을 말한다.', 166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1249, '제4조(부정식품의 유해기준)', 166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1250, '제5조(부정의약품등의 유해기준등)', 166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1251, '제6조(상금의 지급액)', 166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1252, '제7조(시행규칙) 이 영 시행에 관하여 필요한 사항은 보건복지부령으로 정한다. <개정 1994.12.23, 2008.2.29, 2010.3.15>', 166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1253, '제1조 (목적) 이 규칙은 「국민의 형사재판참여에 관한 법률」(다음부터 "법"이라 한다) 제54조제3항에 따라 사법참여기획단(다음부터 "기획단"이라 한다)의 조직과 활동 그 밖에 필요한 사항을 정하는 것을 목적으로 한다.', 167);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1254, '제2조 (기획단의 구성)', 167);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1255, '제3조 (단장의 직무)', 167);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1256, '제4조 (기획단의 회의)', 167);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1257, '제5조 (관계기관의 협조 등)', 167);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1258, '제6조 (의견의 수렴) 기획단은 필요한 경우 공청회, 토론회, 여론조사 등을 통하여 각계의 의견을 수렴할 수 있다.', 167);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1259, '제7조 (수당 등의 지급) 기획단의 위원과 제5조에 의하여 조사ㆍ연구를 수행한 자 등에게는 예산의 범위 내에서 수당, 여비, 조사 연구비 및 그 밖에 필요한 경비를 지급할 수 있다.', 167);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1260, '제1조 (목적) 이 영은 국가보안법(이하 "법"이라 한다. 제16조제 3항의 규정에 의하여 공소보류의 결정을 받은 자(이하 "보류자"라한다)에 대한 감시 및 보도에 관한 사항을 규정함을 목적으로 한다.', 168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1261, '제2조 (훈계)', 168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1262, '제3조 (통지) 검사는 보류결정을 한 때는 지체없이 보류자의 거주지를 관할하는 경찰서장(이하 "경찰서장"이라 한다)과 그 사건을 수사한 기관의 장(이하 "수사기관의 장"이라 한다)에게 별지 제2호서식에 의하여 각각 통지하여야 한다.', 168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1263, '제4조 (감시)', 168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1264, '제5조 (협조의 요구) 검사 또는 수사기관의 장은 국가의 안전에 관련되는 범죄의 수사를 위하여 필요한 경우에는 보류자에게 협조를 요구할 수 있다.', 168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1265, '제6조 (신고)', 168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1266, '제7조 (보고) 경찰서장 또는 수사기관의 장은 다음 각호의 1에 해당하는 사유가 있을 때에는 지체없이 이를 검사에게 보고하여야 한다.', 168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1267, '제8조 (감독) 검사는 보류자의 감시 및 보도에 관하여 경찰서장 및 수사기관의 장을 감독하고, 필요한 지시를 할 수 있다.', 168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1268, '제9조 (공소보류자 명부) 지방검찰청 검사장 및 지방검찰청 지청장은 공소보류자 명부를 작성 비치하고, 보류자의 동태와 감시 및 보도에 관한 사항을 기재하여야 한다.', 168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1269, '제10조 (보도)', 168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1270, '제11조 (보호신청) 검사는 주거 및 연고자가 없는 자에 대하여 보류결정을 할 때에는 갱생보호법 제12조의 규정에 의하여 관할 갱생보호회지소장에게 보호신청을 하여야 한다.', 168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1271, '제12조 (보류결정의 취소) 검사는 보류자가 그 공소보류기간중에 다음의 각호에 해당하는 사유가 발생한 때에는 법 제16조제3항의 규정에 의하여 그 보류결정을 취소 할 수 있다.', 168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1272, '제13조 (취소시의 주의사항)', 168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1273, '제1조(목적) 이 영은 「중대재해 처벌 등에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 169);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1274, '제2조(직업성 질병자) 「중대재해 처벌 등에 관한 법률」(이하 "법"이라 한다) 제2조제2호다목에서 "대통령령으로 정하는 직업성 질병자"란 별표 1에서 정하는 직업성 질병에 걸린 사람을 말한다.', 169);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1275, '제3조(공중이용시설) 법 제2조제4호 각 목 외의 부분 본문에서 "대통령령으로 정하는 시설"이란 다음 각 호의 시설을 말한다. <개정 2025.8.26>', 169);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1276, '제4조(안전보건관리체계의 구축 및 이행 조치) 법 제4조제1항제1호에 따른 조치의 구체적인 사항은 다음 각 호와 같다.', 170);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1277, '제5조(안전ㆍ보건 관계 법령에 따른 의무이행에 필요한 관리상의 조치)', 170);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1278, '제6조(안전보건교육의 실시 등)', 170);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1279, '제7조(과태료의 부과기준) 법 제8조제2항에 따른 과태료의 부과기준은 별표 4와 같다.', 170);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1280, '제8조(원료ㆍ제조물 관련 안전보건관리체계의 구축 및 이행 조치) 법 제9조제1항제1호에 따른 조치의 구체적인 사항은 다음 각 호와 같다.', 171);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1281, '제9조(원료ㆍ제조물 관련 안전ㆍ보건 관계 법령에 따른 의무이행에 필요한 관리상의 조치)', 171);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1282, '제10조(공중이용시설ㆍ공중교통수단 관련 안전보건관리체계 구축 및 이행에 관한 조치) 법 제9조제2항제1호에 따른 조치의 구체적인 사항은 다음 각 호와 같다.', 171);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1283, '제11조(공중이용시설ㆍ공중교통수단 관련 안전ㆍ보건 관계 법령에 따른 의무이행에 필요한 관리상의 조치)', 171);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1284, '제12조(중대산업재해 발생사실의 공표)', 172);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1285, '제13조(조치 등의 이행사항에 관한 서면의 보관) 사업주 또는 경영책임자등(「소상공인기본법」 제2조에 따른 소상공인은 제외한다)은 제4조, 제5조 및 제8조부터 제11조까지의 규정에 따른 조치 등의 이행에 관한 사항을 서면(「전자문서 및 전자거래 기본법」 제2조제1호에 따른 전자문서를 포함한다)으로 작성하여 그 조치 등을 이행한 날부터 5년간 보관해야 한다.', 172);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1286, '제1조(목적) 이 영은 「민영교도소 등의 설치ㆍ운영에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1287, '제2조 삭제 <2009.9.3>', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1288, '제3조 삭제 <2009.9.3>', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1289, '제4조(위탁계약의 성립 등)', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1290, '제5조(교정법인의 정관변경) 법 제10조제2항 단서에서 "대통령령으로 정하는 경미한 사항"이란 다음 각 호의 어느 하나에 해당하는 사항을 말한다.', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1291, '제6조(교정법인 임원의 임기 등)', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1292, '제7조(임원의 직무)', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1293, '제8조(이사회의 회의 등)', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1294, '제9조(재산의 구분 등)', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1295, '제10조(기본재산의 처분) 법 제14조제2항 단서에서 "대통령령으로 정하는 경미한 사항"이란 다음 각 호의 어느 하나에 해당하는 경우를 말한다. 다만, 법 제14조제2항 본문에 따른 허가를 받지 아니할 목적으로 기본재산을 분할하거나 법, 이 영 또는 관계 법령을 위반하는 경우는 제외한다.', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1296, '제11조(처분할 수 없는 재산의 범위) 법 제14조제3항에서 "대통령령으로 정하는 것"이란 다음 각 호의 것을 말한다. <개정 2021.1.5>', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1297, '제12조(일반회계와 교도작업회계의 세입ㆍ세출)', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1298, '제13조(예산ㆍ결산 등의 제출)', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1299, '제14조(민영교도소등의 시설기준)', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1300, '제15조(수용자의 처우)', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1301, '제16조(직원의 임면 승인 범위) 법 제29조제1항 단서에서 "대통령령으로 정하는 직원"이란 「법무부와 그 소속기관 직제」에 따라 교도소등에 두는 과의 과장 이상의 직에 준하는 직위의 직원을 말한다.', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1302, '제17조(직원의 임용 자격 등)', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1303, '제18조(직무교육)', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1304, '제19조(직원의 직무) 민영교도소등의 직원은 「형의 집행 및 수용자의 처우에 관한 법률」에 따른 교도관의 직무 중 위탁계약에서 정하는 범위에서 그 직무를 수행한다.', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1305, '제20조(직권면직)', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1306, '제21조(징계처분)', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1307, '제22조(보고)', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1308, '제23조(손해배상의 담보) 교정법인은 법 제38조제1항에 따른 손해배상을 위하여 1억원 이상의 현금 또는 유가증권을 공탁하거나 이행보증보험에 가입하여야 한다.', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1309, '제24조(과태료의 부과기준) 법 제44조제1항부터 제3항까지의 규정에 따른 과태료의 부과기준은 별표와 같다.', 173);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1310, '제1조(목적) 이 규칙은 「성폭력범죄의 처벌 등에 관한 특례법」 제35조, 제35조의3 및 제36조(「다른 법률에서 준용하는 경우를 포함한다)에서 위임된 진술조력인의 자격, 양성, 배치 및 수사절차 참여 등에 관한 사항과 진술조력인 제도의 시행에 필요한 사항을 규정함을 목적으로 한다. <개정 2021.1.20, 2023.7.4>', 174);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1311, '제1조의2(정의) 이 규칙에서 "피해자등"이란 다음 각 호의 어느 하나에 해당하는 사람을 말한다.', 174);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1312, '제2조(적용 범위) 이 규칙은 「성폭력범죄의 처벌 등에 관한 특례법」(이하 "법"이라 한다) 제35조, 제35조의2, 제35조의3 및 제36조부터 제39조까지를 준용(일부를 준용하는 경우를 포함한다)하는 다음 각 호의 절차에서의 진술조력인 지원에 대해서도 적용한다.', 174);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1313, '제3조(진술조력인 양성 교육)', 175);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1314, '제4조(진술조력인 교육 대상자의 선발) 법무부장관은 다음 각 호의 어느 하나에 해당하는 사람 중에서 제3조제1항에 따른 교육 대상자를 선발한다.', 175);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1315, '제5조(진술조력인 자격의 부여)', 175);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1316, '제6조 삭제 <2021.1.20>', 175);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1317, '제7조(진술조력인 자격증의 발급) 법무부장관은 제5조에 따라 진술조력인 자격을 취득한 사람에게 자격 부여일부터 1개월 이내에 별지 제2호서식의 진술조력인 자격증을 발급하여야 한다.', 175);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1318, '제8조(진술조력인 자격의 관리ㆍ감독 등)', 175);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1319, '제9조(진술조력인 자문단의 구성 및 운영)', 175);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1320, '제10조(진술조력인 보수교육)', 175);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1321, '제11조(진술조력인의 자격취소 등)', 175);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1322, '제11조의2(진술조력인의 배치)', 175);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1323, '제12조(진술조력인명부의 작성)', 175);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1324, '제13조(진술조력인의 선정 절차)', 176);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1325, '제14조(진술조력인의 선정 금지) 다음 각 호의 어느 하나에 해당하는 사람은 해당 사건의 진술조력인으로 선정될 수 없다. <개정 2023.7.4>', 176);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1326, '제15조(진술조력인 선정의 취소)', 176);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1327, '제16조(진술조력인의 재선정) 검사 또는 사법경찰관은 제15조에 따라 진술조력인 선정을 취소한 경우에는 제13조에 따라 진술조력인을 다시 선정할 수 있다.', 176);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1328, '제17조(진술조력인의 참여 대상 범위) 법 제36조에 따라 진술조력인이 수사과정에 참여하여 의사소통을 중개하거나 보조할 수 있는 피해자 중 "신체적인 또는 정신적인 장애로 사물을 변별하거나 의사를 결정할 능력이 미약한 피해자"란 다음 각 호의 어느 하나에 해당하는 사람을 말한다. <개정 2024.4.1>', 177);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1329, '제18조(의사소통 중개ㆍ보조의 범위)', 177);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1330, '제19조(진술조서 등의 기재 사항 등)', 177);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1331, '제20조(조사 전 피해자등 면담)', 177);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1332, '제21조(조사 후 의견 제출)', 177);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1333, '제22조(수당 등의 기준) 진술조력인에게 지급하는 수당 등의 기준은 예산, 피해자등에 대한 지원 실적 등을 고려해 법무부장관이 정한다.', 177);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1334, '제1조(형의 집행정지 통지 등)', 178);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1335, '제2조(형집행정지자에 대한 관찰)', 178);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1336, '제3조(형의 집행정지 취소의 통지) 검사가 형의 집행정지처분을 취소한 때에는 형집행정지자의 거주지를 관할하는 경찰서장에게 통지하여야 한다.', 178);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1337, '제4조(노역장유치시의 준용) 제1조 내지 제3조의 규정은 노역장유치의 집행을 정지한 경우에 이를 준용한다. <개정 1979ㆍ7ㆍ6, 1991ㆍ6ㆍ19>', 178);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1338, '제5조(군사법원법에 의한 형의 집행정지에 의한 준용)', 178);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1339, '제1조(목적) 이 영은 「형사사법절차 전자화 촉진법」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1340, '제1조의2 삭제 <2022.4.5>', 179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1341, '제2조(형사사법정보시스템을 이용하는 것이 곤란한 문서) 「형사사법절차 전자화 촉진법」(이하 "법"이라 한다) 제5조제1항 단서에 따라 형사사법업무 처리기관은 다음 각 호의 문서를 저장ㆍ보관하는 경우에는 형사사법정보시스템(이하 "시스템"이라 한다)을 이용하지 않을 수 있다. <개정 2020.7.14, 2022.4.5>', 179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1342, '제3조(형사사법정보의 유통표준에 관한 준수사항)', 179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1343, '제4조(송신ㆍ수신되는 정보의 정확성 유지) 형사사법업무 처리기관은 법 제9조에 따른 형사사법정보체계 협의회(이하 "협의회"라 한다)가 법 제12조제1항에 따라 시스템을 통하여 다른 형사사법업무 처리기관에 제공하도록 정한 형사사법정보의 정확성을 유지하기 위하여 다음 각 호의 사항을 준수하여야 한다.', 179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1344, '제5조(시스템 운영세칙) 법무부장관, 검찰총장, 경찰청장, 해양경찰청장 및 고위공직자범죄수사처장은 법 제8조제1항에 따라 시스템을 안정적으로 운영ㆍ관리하기 위하여 기관별로 운영세칙을 수립ㆍ시행하여야 한다. <개정 2022.4.5>', 179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1345, '제6조(형사사법공통시스템 운영단의 구성 등)', 179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1346, '제7조(운영단의 기능) 운영단은 다음 각 호의 업무를 수행한다.', 179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1347, '제8조(운영단의 의무)', 179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1348, '제9조(관계 기관ㆍ단체 등에의 협조 요청) 운영단의 장은 운영단의 업무를 수행하기 위하여 필요한 경우에는 전문지식과 경험이 있는 관계 공무원 또는 관계 전문가에게 의견을 듣거나, 관계 기관ㆍ단체 등에 필요한 협조를 요청할 수 있다.', 179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1349, '제10조(보수 등)', 179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1350, '제11조(협의회의 위원장 등)', 179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1351, '제12조(협의회의 개최)', 179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1352, '제13조(협의회의 협의 등)', 179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1353, '제14조(회의록)', 179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1354, '제15조(형사사법정보체계 실무협의회의 구성) 법 제13조에 따른 형사사법정보체계 실무협의회(이하 "실무협의회"라 한다)의 위원은 판사, 검사, 고위공직자범죄수사처 검사, 총경 이상 경찰공무원, 형사사법업무 처리기관 소속의 4급 이상 일반직공무원, 운영단의 장 중에서 협의회의 위원 각자가 1명씩 지명하는 6명으로 한다. <개정 2022.4.5>', 179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1355, '제16조(실무협의회의 개최)', 179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1356, '제17조(회의록)', 179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1357, '제18조(민감정보 및 고유식별정보 등의 처리) 형사사법업무 처리기관(제5호의 사무에 대해서는 법 제8조제3항에 따라 형사사법업무 처리기관의 업무를 위탁받은 자를 포함한다)은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 민감정보, 같은 법 시행령 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호, 외국인등록번호나 그 밖의 개인정보가 포함된 자료를 처리할 수 있다.', 179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1358, '제1조(취지) 「마약류 불법거래방지에 관한 특례법」(이하 "법"이라 한다)에 의한 몰수보전 및 추징보전의 절차, 몰수재판 및 추징재판의 집행과 보전에 관한 국제공조절차등에 관하여는 법의 규정에 의하는 외에 이 규칙이 정하는 바에 의한다. <개정 2005.12.29>', 180);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1359, '제2조(몰수보전 청구의 방식) 몰수보전의 청구는 서면으로 하여야 한다.', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1360, '제3조(몰수보전 청구서의 기재사항)', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1361, '제4조(부대보전 청구의 방식) 부대보전(부대보전 명령에 의한 처분의 금지를 말한다. 이하 같다)의 청구는 서면으로 하여야 한다.', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1362, '제5조(부대보전 청구서의 기재사항)', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1363, '제6조(몰수보전명령의 기재사항) 몰수보전명령 및 부대보전명령을 발하는 경우 그 재판서에는 법 제33조제3항이 규정하는 사항외에 피고인 또는 피의자의 주민등록번호와 주거, 처분을 금지하는 재산 또는 권리를 가진 자의 주소를 기재하여야 한다.', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1364, '제7조(긴급을 요하는 경우의 기재사항) 법 제33조제4항의 규정에 의하여 몰수보전명령 또는 부대보전명령을 발하는 경우에는 재판서에 그 취지를 기재하여야 한다.', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1365, '제8조(몰수보전명령이 발하여진 경우의 공소장의 기재사항) 공소가 제기되기 전에 몰수보전명령이 발하여진 경우, 검사는 공소장에 몰수보전명령이 발하여졌다는 취지의 기재를 하여야 한다.', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1366, '제9조(몰수보전이 된 금전채권의 채무자가 공탁을 한 경우) 금전의 지급을 목적으로 하는 채권(이하 "금전채권"이라고 한다)에 대하여 몰수보전이 되어 그 채무자가 법 제40조제4항에 의하여 공탁을 한 경우 그 공탁을 수리한 공탁관은 몰수보전명령을 발한 법원 및 이에 대응하는 검찰청의 검사(이하 "검사"라고 한다) 또는 고위공직자범죄수사처에 소속된 검사(이하 "수사처검사"라고 한다)에게 공탁사실을 통지하여야 한다. <개정 2007.3.29, 2021.1.29>', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1367, '제10조(예탁유가증권의 몰수보전) 「자본시장과 금융투자업에 관한 법률」 제309조제2항에 따라 한국예탁결제원에 예탁된 유가증권(같은 법률 제310조제4항에 따라 한국예탁결제원에 예탁된 것으로 보는 경우를 포함한다. 이하 이 조에서 "예탁유가증권"이라 한다)에 대한 몰수보전은, 예탁유가증권에 대한 공유지분을 가지는 자(명의인이 다른 경우 명의인을 포함한다)에게는 계좌간 대체청구ㆍ증권반환청구, 그 밖의 처분을 금지하고, 한국예탁결제원에게는 예탁자에 대한 계좌간 대체와 증권의 반환을 금지하는 취지의 몰수보전명령에 의하여 한다. <개정 2005.12.29, 2019.11.29>', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1368, '제10조의2(전자등록주식등의 몰수보전) 「주식ㆍ사채 등의 전자등록에  관한 법률」 제2조제4호에 따른 전자등록주식등(이하 이 조에서 "전자등록주식등"이라 한다)에 대한 몰수보전은, 전자등록주식등의 권리자(명의인이 다른 경우 명의인을 포함한다)에게는 같은 법 제30조에 따른 계좌간 대체의 전자등록신청, 같은 법 제33조에 따른 변경ㆍ말소의 전자등록신청이나 추심, 그 밖의 처분을 금지하고, 같은 법 제2조제6호에 따른 전자등록기관 또는 같은 법 제2조제7호에 따른 계좌관리기관에게는 같은 법에 따른 계좌간 대체와 변경ㆍ말소를 금지하는 취지의 몰수보전명령에 의하여 한다.', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1369, '제11조(몰수보전명령의 취소청구의 방식)', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1370, '제12조(검사 또는 수사처검사의 의견서등의 제출) 검사 또는 수사처검사는 법원으로부터 몰수보전명령의 취소에 관한 의견요청이 있을 때에는 3일이내에 의견서를 법원에 제출하여야 하고, 아직 수사기록과 증거물을 법원에 증거로 제출하지 않은 경우에는 수사기록과 증거물도 함께 법원에 제출하여야 한다. <개정 2021.1.29>', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1371, '제13조(몰수보전재산에 대하여 강제집행에 의하여 압류등이 된 경우의 통지)', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1372, '제14조(몰수보전된 금전채권에 대하여 강제집행에 의하여 압류가 된 경우 공탁사유신고의 방식등)', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1373, '제14조의2(몰수보전된 금전채권에 대하여 체납처분에 의하여 압류가 된 경우의 공탁사유신고의 방식등)', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1374, '제15조(강제집행에 의하여 압류가 된 금전채권에 대하여 몰수보전이 된 경우 공탁사유신고의 방식등)', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1375, '제15조의2(체납처분에 의하여 압류가 된 금전채권에 대하여 몰수보전된 경우의 공탁사유신고의 방식등)', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1376, '제16조(강제집행에 의하여 압류등이 된 재산에 대하여 몰수보전이 된 경우의 통지)', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1377, '제17조(강제집행의 정지 및 그 결정의 취소청구방식)', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1378, '제18조(몰수보전과 담보권 실행 등을 위한 경매개시결정에 의한 압류가 경합하는 경우의 통지) 제13조제1항, 제3항 및 제16조제3항의 규정은 몰수보전이 된 재산에 대하여 담보권 실행 등을 위한 경매개시결정에 의하여 압류가 된 경우에, 제16조의 규정은 담보권 실행 등을 위한 경매개시결정에 의하여 압류가 된 재산에 대하여 몰수보전명령이 발하여진 경우에 각 준용한다. 이 경우 그 담보권에 대하여 부대보전이 된 때에는 제13조제3항 및 제16조제2항중 "몰수보전"은 "몰수보전 또는 부대보전"으로 본다. <개정 2005.12.29>', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1379, '제19조(몰수보전과 가압류의 집행이 경합하는 경우의 통지등)', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1380, '제20조(부대보전절차에의 준용) 부대보전의 절차에 관하여 이 규칙에 특별한 규정이 있는 경우를 제외하고는 몰수보전의 절차에 관한 규정을 준용한다.', 182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1381, '제21조(추징보전 청구의 방식) 추징보전의 청구는 서면으로 하여야 한다.', 183);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1382, '제22조(추징보전 청구서의 기재사항)', 183);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1383, '제23조(추징보전집행이 된 금전채권의 채무자의 공탁방법등) 추징보전집행된 금전채권의 채무자가 법 제55조에 의한 공탁을 한 경우 그 공탁을 수리한 공탁관은 추징보전명령을 발한 법원 및 검사 또는 수사처검사에게 공탁사실을 통지하여야 한다. <개정 2007.3.29, 2021.1.29>', 183);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1384, '제24조(추징보전해방금의 공탁 및 환부)', 183);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1385, '제25조(추징보전명령등에의 준용) 제6조, 제7조, 제8조, 제11조, 제12조의 규정은 추징보전명령 또는 추징보전에 관하여 준용한다. 이 경우 제6조중 "법 제33조제3항"은 "법 제52조제4항"으로, 제11조중 "법 제42조제1항"은 "법 제57조"로 각 본다.', 183);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1386, '제26조(「형사소송규칙」의 준용) 몰수보전 및 추징보전의 절차와 제3자 참가절차등의 특례에 관하여는 법 및 이 규칙에 특별한 규정이 있는 경우를 제외하고는 「형사소송규칙」의 규정을 준용한다. 이 경우 법 제24조의 규정에 의하여 형사사건절차에의 참가를 허가받은 자에 관하여는 피고인에 관한 규정을, 법 제30조의 규정에 의하여 선임된 대리인에 관하여는 변호인에 관한 규정을 준용한다. <개정 2005.12.29>', 184);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1387, '제27조(공조요청에 대한 심사청구의 방식)', 185);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1388, '제28조(집행공조허가결정의 취소청구의 방식)', 185);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1389, '제29조(공조요청에 의한 몰수보전등의 청구의 방식)', 185);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1390, '제30조(「형사소송규칙」등의 준용) 이 장에 특별한 규정이 있는 경우를 제외하고 법원 또는 법관이 하는 심사, 처분 및 영장의 발부와 검사 또는 사법경찰관리가 하는 처분 및 법원의 심사에의 이해관계인의 참가에 관한 절차에 관하여는 제2장 및 「형사소송규칙」(제1편제2장, 제5장 내지 제13장, 제2편제1장, 제3편제1장, 제3장, 제4장, 제5편 및 제6편에 한한다), 「국제형사사법 공조규칙」, 「범죄인인도법에 의한 인도심사 등의 절차에 관한 규칙」 제4조, 제12조, 제14조, 제15조를 각각 그 성질에 반하지 아니하는 범위안에서 준용한다. <개정 2005.12.29>', 185);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1391, '제1조(목적) 이 법은 인간의 존엄과 가치를 존중하고 국제사회의 정의를 실현하기 위하여 「국제형사재판소에 관한 로마규정」에 따른 국제형사재판소의 관할 범죄를 처벌하고 대한민국과 국제형사재판소 간의 협력에 관한 절차를 정함을 목적으로 한다.', 186);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1392, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다.', 186);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1393, '제3조(적용범위)', 186);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1394, '제4조(상급자의 명령에 따른 행위)', 186);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1395, '제5조(지휘관과 그 밖의 상급자의 책임) 군대의 지휘관(지휘관의 권한을 사실상 행사하는 사람을 포함한다. 이하 같다) 또는 단체ㆍ기관의 상급자(상급자의 권한을 사실상 행사하는 사람을 포함한다. 이하 같다)가 실효적인 지휘와 통제하에 있는 부하 또는 하급자가 집단살해죄등을 범하고 있거나 범하려는 것을 알고도 이를 방지하기 위하여 필요한 상당한 조치를 하지 아니하였을 때에는 그 집단살해죄등을 범한 사람을 처벌하는 외에 그 지휘관 또는 상급자도 각 해당 조문에서 정한 형으로 처벌한다.', 186);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1396, '제6조(시효의 적용 배제) 집단살해죄등에 대하여는 「형사소송법」 제249조부터 제253조까지 및 「군사법원법」 제291조부터 제295조까지의 규정에 따른 공소시효와 「형법」 제77조부터 제80조까지의 규정에 따른 형의 시효에 관한 규정을 적용하지 아니한다.', 186);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1397, '제7조(면소의 판결) 집단살해죄등의 피고사건에 관하여 이미 국제형사재판소에서 유죄 또는 무죄의 확정판결이 있은 경우에는 판결로써 면소(免訴)를 선고하여야 한다.', 186);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1398, '제8조(집단살해죄)', 187);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1399, '제9조(인도에 반한 죄)', 187);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1400, '제10조(사람에 대한 전쟁범죄)', 187);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1401, '제11조(재산 및 권리에 대한 전쟁범죄)', 187);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1402, '제12조(인도적 활동이나 식별표장 등에 관한 전쟁범죄)', 187);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1403, '제13조(금지된 방법에 의한 전쟁범죄)', 187);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1404, '제14조(금지된 무기를 사용한 전쟁범죄)', 187);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1405, '제15조(지휘관 등의 직무태만죄)', 187);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1406, '제16조(사법방해죄)', 187);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1407, '제17조(친고죄ㆍ반의사불벌죄의 배제) 집단살해죄등은 고소가 없거나 피해자의 명시적 의사에 반하여도 공소를 제기할 수 있다.', 187);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1408, '제18조(국제형사재판소규정 범죄구성요건의 고려) 제8조부터 제14조까지의 적용과 관련하여 필요할 때에는 국제형사재판소규정 제9조에 따라 2002년 9월 9일 국제형사재판소규정 당사국총회에서 채택된 범죄구성요건을 고려할 수 있다.', 187);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1409, '제19조(「범죄인 인도법」의 준용)', 188);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1410, '제20조(「국제형사사법 공조법」의 준용)', 188);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1411, '제1조(목적) 이 규칙은 「아동학대범죄의 처벌 등에 관한 특례법」(이하 "법"이라 한다)에 따라 대법원규칙에 위임된 사항 등 아동보호사건, 피해아동보호명령사건 및 배상명령의 처리에 관하여 필요한 사항을 정함을 목적으로 한다.', 189);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1412, '제2조(관할)', 189);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1413, '제3조(결정서)', 189);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1414, '제4조(결정의 고지와 통지)', 189);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1415, '제5조(수탁기관 등에 대한 결정의 통지)', 189);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1416, '제5조의2(집행기관 등에 대한 결정의 통지)', 189);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1417, '제6조(검사에 대한 결정의 통지)', 189);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1418, '제7조(송치 및 이송의 방식)', 189);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1419, '제8조(임시조치 및 보호처분, 임시보호명령 및 피해아동보호명령의 집행)', 189);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1420, '제9조(기록등의 송부) 법원은 다음 각 호의 1에 해당하는 때에는 사건기록(집행감독사건 기록을 포함한다)과 결정서를 대응하는 검찰청에 송부하여야 한다. <개정 2016.11.1, 2025.2.28>', 189);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1421, '제10조(임시조치의 청구 등)', 191);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1422, '제11조(검사의 송치방식)', 191);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1423, '제12조(구속되어 인도된 행위자의 처리)', 191);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1424, '제13조(범죄사실 등의 고지) 판사는 아동보호사건을 접수한 때에는 행위자에게 다음 각 호의 사항을 서면으로 고지하여야 한다. 다만, 법 제29조의 규정에 의하여 송치된 아동보호사건에 있어서는 행위자의 범죄사실은 이를 고지하지 아니할 수 있다. <개정 2016.11.1>', 191);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1425, '제14조(조회응답) 아동보호사건과 관계있는 기관은 그 사건내용에 관하여 재판, 수사 또는 다른 법률에 정함이 있는 경우를 제외하고는 어떠한 조회에도 응하여서는 아니된다.', 191);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1426, '제15조(조사의 방법)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1427, '제16조(조사보고서의 작성) 조사관은 조사의 결과를 의견을 붙인 서면으로 작성하여 보고하여야 한다.', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1428, '제17조(소환)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1429, '제17조의2(심리기일의 통지)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1430, '제18조(수용 중인 행위자의 소환)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1431, '제19조(긴급동행영장의 기재사항) 긴급동행영장에는 법 제44조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」제26조가 정한 기재사항 외에 행위자가 소환에 응하지 아니할 우려가 있거나 피해아동등의 보호를 위하여 긴급히 필요한 이유를 기재하여야 한다. <개정 2020.9.28>', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1432, '제20조(동행영장의 집행지휘)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1433, '제21조(동행영장의 집행)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1434, '제22조(동행영장에 의하여 법원에 인치된 행위자의 처리)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1435, '제23조(보조인)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1436, '제24조(아동보호사건의 국선보조인) 국선보조인의 선임ㆍ보수 등 이 규칙에서 따로 정하지 아니한 사항에 대하여는 아동보호사건의 성질에 위반되지 아니하는 범위 내에서 「형사소송규칙」, 「형사소송비용 등에 관한 규칙」 중 국선변호인에 관한 규정을 준용한다.', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1437, '제25조(의료기관 등에의 임시위탁)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1438, '제26조(가족관계등록부기록의 촉탁)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1439, '제27조(임시로 후견인의 임무를 수행할 사람의 선임, 사임허가 및 변경)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1440, '제28조(임시조치 불이행에 대한 경고) 법 제19조제1항제1호부터 제4호까지의 임시조치 결정을 통지함에는 이를 이행하지 아니할 경우 법 제59조제1항제1호에 따른 처벌을 받을 수 있음을, 법 제19조제1항제5호, 제6호의 임시조치결정을 통지함에는 위 결정을 이행하지 아니하거나 집행에 따르지 아니할 경우 법 제22조제4항에 따라 그 임시조치가 변경될 수 있음을 각 경고하여야 한다. <개정 2025.5.30>', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1441, '제29조(수탁기관의 지정)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1442, '제30조(임시위탁비용)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1443, '제31조(지급절차)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1444, '제32조(임시조치의 집행)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1445, '제33조(임시조치의 취소ㆍ변경ㆍ연장)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1446, '제34조(이송시 임시조치의 효력)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1447, '제35조(심리기일 변경청구)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1448, '제36조(심리의 개시)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1449, '제37조(심리의 비공개)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1450, '제38조(심리의 방식 및 병합심리등)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1451, '제39조(조사관에 대한 제척ㆍ기피ㆍ회피) 「형사소송법」 제25조는 조사관에게도 이를 준용한다.', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1452, '제40조(증인신문)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1453, '제41조(준용규정) 「형사소송규칙」 중 증인신문, 감정, 검증, 압수 또는 수색에 관한 규정은 아동보호사건의 성질에 위반되지 아니하는 한 법 제44조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제34조 및 제35조에 따른 절차에 이를 준용한다.', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1454, '제42조(심리조서)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1455, '제43조(서류의 열람ㆍ등사)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1456, '제44조(결정서의 등ㆍ초본의 청구)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1457, '제45조(불처분결정)', 192);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1458, '제46조(보호처분)', 193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1459, '제47조(준용규정) 법 제36조제1항제3호의 보호처분, 같은 조 제4항의 임시후견인에 관하여는 이 규칙 제26조, 제27조를 준용한다.', 193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1460, '제48조(사회봉사ㆍ수강명령ㆍ보호관찰)', 193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1461, '제49조(감호ㆍ치료ㆍ상담위탁)', 193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1462, '제50조(치료ㆍ상담위탁비용) 법 제36조제1항제7호 및 제8호의 위탁비용의 예납 및 그 지급절차에 관하여는 이 규칙 제30조 및 제31조를 준용한다.', 193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1463, '제51조(참고자료의 송부 등)', 193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1464, '제52조(보호처분의 집행) 법 제38조제1항의 규정에 의한 보호처분의 집행지휘는 결정서등본을 그 집행담당자에게 교부함으로써 한다.', 193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1465, '제53조(몰수결정의 집행 등) 몰수결정의 집행, 몰수물의 처분 및 교부에 관하여는 판사가 「형사소송법」 중 몰수재판의 집행, 몰수물의 처분 및 교부에 관한 규정에 준하여 행한다.', 193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1466, '제54조(집행상황보고)', 193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1467, '제55조(보호처분의 변경ㆍ취소ㆍ종료)', 193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1468, '제56조(보호처분과 형의 집행) 법 제36조제1항제1호부터 제3호까지 및 제6호부터 제8호까지의 보호처분의 계속중 행위자가 징역, 금고 또는 구류의 집행을 받게 된 때 및 법 제36조제1항제4호ㆍ제5호의 보호처분의 계속중 행위자가 구류의 집행을 받게 된 때에는 먼저 그 형을 집행한다. 이 경우 판사가 상당하다고 인정한 때에는 결정으로 그 보호처분을 종료할 수 있다.', 193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1469, '제57조(항고제기의 방식) 항고장에는 항고의 이유를 간결하게 명시하여야 한다.', 194);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1470, '제58조(임시조치에 대한 항고) 임시조치 및 그 연장ㆍ변경결정에 대하여 항고가 제기된 경우 원심법원은 필요한 일부 기록의 등본을 항고법원으로 송부하고 기록원본에 의하여 이후의 절차를 진행할 수 있다.', 194);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1471, '제59조(항고의 취하)', 194);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1472, '제60조(수용 중인 행위자의 항고제기)', 194);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1473, '제61조(항고법원의 조사)', 194);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1474, '제62조(항고법원의 사실조사)', 194);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1475, '제63조(취소환송ㆍ이송)', 194);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1476, '제64조(파기자판)', 194);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1477, '제65조(몰수ㆍ배상명령의 취소)', 194);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1478, '제66조(환송 또는 이송 후의 재판)', 194);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1479, '제67조(재항고법원의 재판)', 194);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1480, '제68조(재항고에 관한 준용) 재항고에 관하여는 그 성질에 위반되지 아니하는 한 법 및 이 규칙의 항고에 관한 규정을 준용한다.', 194);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1481, '제69조(준용규정)', 194);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1482, '제70조(청구의 방식)', 196);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1483, '제71조(피해아동보호명령사건의 국선보조인) 국선보조인의 선정ㆍ보수 등 이 규칙에서 따로 정하지 아니한 사항에 대하여는 피해아동보호명령사건의 성질에 위반되지 아니하는 범위 내에서 「형사소송규칙」, 「형사소송비용 등에 관한 규칙」 중 국선변호인에 관한 규정을 준용한다.', 196);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1484, '제72조(이송)', 196);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1485, '제73조(청구의 취하 등)', 196);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1486, '제74조(조사의 방법)', 197);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1487, '제75조(심리기일의 지정)', 197);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1488, '제76조(소환)', 197);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1489, '제77조(심리의 개시)', 197);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1490, '제78조(병합심리 등)', 197);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1491, '제79조(증인신문) 법 제56조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제32조제2항의 규정에 의한 신청에 대하여는 결정을 하고 신청인에게 이를 통지하여야 한다.', 197);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1492, '제80조(준용규정) 「형사소송규칙」중 증인신문, 감정, 검증, 압수 또는 수색에 관한 규정은 피해아동보호명령사건의 성질에 위배되지 아니하는 한 법 제56조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제34조 및 제35조에 따른 절차에 이를 준용한다.', 197);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1493, '제81조(심리조서)', 197);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1494, '제82조(기록의 열람ㆍ등사)', 197);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1495, '제83조(결정서의 등ㆍ초본의 청구)', 197);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1496, '제84조(기각결정)', 197);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1497, '제85조(준용규정) 피해아동보호명령사건의 조사ㆍ심리에 관하여는 제16조, 제18조, 제35조, 제37조, 제39조의 규정을 준용한다.', 197);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1498, '제86조(피해아동보호명령)', 198);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1499, '제87조(수탁기관의 지정 등)', 198);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1500, '제88조(수탁 연고자 등의 선정)', 198);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1501, '제89조(피해아동보호명령의 집행)', 198);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1502, '제90조(이행실태 및 집행과 관련한 사항의 보고) 법 제53조제1항에 따른 이행실태의 조사명령을 받은 조사관 등과 법 제50조제2항에 따라 집행과 관련한 사항의 조사명령을 받은 조사관은 의견을 붙인 서면으로 그 결과를 보고하여야 한다. <개정 2020.9.28>', 198);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1503, '제91조(피해아동보호명령의 취소ㆍ변경ㆍ연장)', 198);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1504, '제92조(준용규정) 법 제47조제1항제7호 및 제8호의 피해아동보호명령, 같은 조 제5항의 임시후견인에 관하여는 이 규칙 제26조 및 제27조를 준용한다. <개정 2025.2.28>', 198);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1505, '제93조(임시보호명령)', 199);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1506, '제94조(임시보호명령의 병과) 법 제47조제1항 각 호에 해당하는 임시보호명령은 병과할 수 있다. <개정 2025.2.28>', 199);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1507, '제95조(이송 시 임시보호명령의 효력) 제72조에 따라 피해아동보호명령사건을 이송하는 경우에 이미 행하여진 임시보호명령은 그 효력을 잃지 않는다.', 199);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1508, '제96조(임시보호명령의 집행) 임시보호명령의 집행에 관하여는 제89조를 준용한다.', 199);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1509, '제97조(임시보호명령의 취소ㆍ변경)', 199);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1510, '제98조(준용규정)', 199);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1511, '제99조 삭제 <2025.2.28>', 200);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1512, '제100조(항고의 취하)', 200);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1513, '제101조(파기자판)', 200);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1514, '제102조(항고ㆍ재항고의 추후보완) 피해아동, 청구인 및 행위자가 책임질 수 없는 사유로 말미암아 항고기간 또는 재항고기간을 지킬 수 없었던 경우에는 그 사유가 없어진 날부터 7일 이내에 게을리 한 항고 또는 재항고를 보완할 수 있다. 다만, 그 사유가 없어질 당시 외국에 있던 피해아동, 청구인 및 행위자에 대하여는 이 기간을 30일로 한다.', 200);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1515, '제103조(준용규정) 피해아동보호명령, 임시보호명령의 항고 및 재항고에 관하여는 제57조, 제58조, 제60조부터 제62조까지, 제66조부터 제68조까지의 규정을 준용한다. <개정 2025.2.28>', 200);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1516, '제104조(증거신청)', 201);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1517, '제105조(증거조사)', 201);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1518, '제106조(피해아동 등에 대한 통지)', 201);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1519, '제107조(배상명령에 대한 불복)', 201);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1520, '제108조(재판정본의 작성ㆍ보존)', 201);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1521, '제109조(재판정본의 교부)', 201);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1522, '제110조(준용규정) 「소송촉진 등에 관한 특례법」 제27조부터 제30조까지ㆍ제34조제4항ㆍ제35조 및 「소송촉진 등에 관한 특례규칙」 제20조부터 제23조까지는 아동보호사건의 성질에 반하지 아니하는 범위 내에서 배상명령절차에 이를 준용한다.', 201);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1523, '제1조(목적) 이 규칙은 「성매매알선 등 행위의 처벌에 관한 법률」과 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다. <개정 2011.1.25>', 202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1524, '제2조(보상금의 지급원칙)', 202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1525, '제3조(신고관련 사항의 누설금지) 보상금의 지급업무에 관여하는 자는 신고인의 인적사항 등 신고와 관련한 사항이 외부에 누설되지 아니하도록 유의하여야 한다.', 202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1526, '제4조(보상금의 지급신청)', 202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1527, '제5조(익명 또는 가명신청)', 202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1528, '제6조 삭제 <2011.1.25>', 202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1529, '제7조 삭제 <2011.1.25>', 202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1530, '제8조 삭제 <2011.1.25>', 202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1531, '제9조(의견청취 등) 법무부장관은 다음 각 호의 사항을 결정하기 위하여 필요한 때에는 신청인 또는 관계인의 의견을 들을 수 있고, 관계기관에 대하여 필요한 자료의 제출을 요청할 수 있다. <개정 2011.1.25>', 202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1532, '제10조 삭제 <2011.1.25>', 202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1533, '제11조 삭제 <2011.1.25>', 202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1534, '제12조 삭제 <2011.1.25>', 202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1535, '제13조(보상금의 지급기준)', 202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1536, '제14조(보상금의 분할지급) 신고를 한 사람이 2명 이상인 경우에는 각자의 공로, 신고인들 간의 합의내용 등을 고려하여 신고인 각자에게 보상금을 분할하여 지급할 수 있다. <개정 2022.2.7>', 202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1537, '제15조(보상금의 지급결정)', 202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1538, '제16조(보상금의 지급절차)', 202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1539, '제17조(보상금의 지급시기에 관한 특례)', 202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1540, '제18조(보상금지급조서의 작성 등)', 202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1541, '제19조(익명 또는 가명신청 관련 서류의 작성)', 202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1542, '제1조(목적) 이 법은 기본적 윤리와 사회질서를 침해하는 특정강력범죄에 대한 처벌과 그 절차에 관한 특례를 규정함으로써 국민의 생명과 신체의 안전을 보장하고 범죄로부터 사회를 지키는 것을 목적으로 한다.', 203);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1543, '제2조(적용 범위)', 203);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1544, '제3조(누범의 형) 특정강력범죄로 형(刑)을 선고받고 그 집행이 끝나거나 면제된 후 3년 이내에 다시 특정강력범죄를 범한 경우(「형법」 제337조의 죄 및 그 미수(未遂)의 죄를 범하여 「특정범죄 가중처벌 등에 관한 법률」 제5조의5에 따라 가중처벌되는 경우는 제외한다)에는 그 죄에 대하여 정하여진 형의 장기(長期) 및 단기(短期)의 2배까지 가중한다. <개정 2014.1.7>', 203);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1545, '제4조(소년에 대한 형)', 203);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1546, '제5조(집행유예의 결격기간) 특정강력범죄로 형을 선고받고 그 집행이 끝나거나 면제된 후 10년이 지나지 아니한 사람이 다시 특정강력범죄를 범한 경우에는 형의 집행을 유예하지 못한다.', 203);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1547, '제6조(보석 등의 취소) 법원은 특정강력범죄사건의 피고인이 피해자나 그 밖에 사건의 재판에 필요한 사실을 알고 있다고 인정되는 사람 또는 그 친족의 생명ㆍ신체나 재산에 해를 끼치거나 끼칠 염려가 있다고 믿을 만한 충분한 이유가 있을 때에는 법원의 직권 또는 검사의 청구에 의하여 결정으로 보석 또는 구속의 집행정지를 취소할 수 있다.', 203);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1548, '제7조(증인에 대한 신변안전조치)', 203);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1549, '제8조(출판물 게재 등으로부터의 피해자 보호) 특정강력범죄 중 제2조제1항제2호부터 제6호까지 및 같은 조 제2항(제1항제1호는 제외한다)에 규정된 범죄로 수사 또는 심리(審理) 중에 있는 사건의 피해자나 특정강력범죄로 수사 또는 심리 중에 있는 사건을 신고하거나 고발한 사람에 대하여는 성명, 나이, 주소, 직업, 용모 등에 의하여 그가 피해자이거나 신고 또는 고발한 사람임을 미루어 알 수 있는 정도의 사실이나 사진을 신문 또는 그 밖의 출판물에 싣거나 방송 또는 유선방송하지 못한다. 다만, 피해자, 신고하거나 고발한 사람 또는 그 법정대리인(피해자, 신고 또는 고발한 사람이 사망한 경우에는 그 배우자, 직계친족 또는 형제자매)이 명시적으로 동의한 경우에는 그러하지 아니하다.', 203);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1550, '제8조의2 삭제 <2023.10.24>', 203);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1551, '제9조(소송 진행의 협의)', 203);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1552, '제10조(집중심리)', 203);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1553, '제11조(공판정에서의 신체구속) 재판장은 특정강력범죄로 공소제기된 피고인이 폭력을 행사하거나 도망할 염려가 있다고 인정할 때에는 공판정에서 피고인의 신체를 구속할 것을 명하거나 그 밖에 필요한 조치를 할 수 있다.', 203);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1554, '제12조(간이공판절차의 결정)', 203);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1555, '제13조(판결선고) 법원은 특정강력범죄사건에 관하여 변론을 종결한 때에는 신속하게 판결을 선고하여야 한다. 복잡한 사건이거나 그 밖에 특별한 사정이 있는 경우에도 판결의 선고는 변론 종결일부터 14일을 초과하지 못한다.', 203);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1556, '제1조(목적) 이 법은 가정폭력범죄의 형사처벌 절차에 관한 특례를 정하고 가정폭력범죄를 범한 사람에 대하여 환경의 조정과 성행(性行)의 교정을 위한 보호처분을 함으로써 가정폭력범죄로 파괴된 가정의 평화와 안정을 회복하고 건강한 가정을 가꾸며 피해자와 가족구성원의 인권을 보호함을 목적으로 한다.', 204);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1557, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다. <개정 2011.7.25, 2011.8.4, 2012.1.17, 2014.12.30, 2016.1.6, 2020.10.20>', 204);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1558, '제3조(다른 법률과의 관계) 가정폭력범죄에 대하여는 이 법을 우선 적용한다. 다만, 아동학대범죄에 대하여는 「아동학대범죄의 처벌 등에 관한 특례법」을 우선 적용한다. <개정 2014.1.28>', 204);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1559, '제3조의2(형벌과 수강명령 등의 병과)', 204);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1560, '제4조(신고의무 등)', 206);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1561, '제5조(가정폭력범죄에 대한 응급조치) 진행 중인 가정폭력범죄에 대하여 신고를 받은 사법경찰관리는 즉시 현장에 나가서 다음 각 호의 조치를 하여야 한다. <개정 2020.10.20>', 206);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1562, '제6조(고소에 관한 특례)', 206);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1563, '제7조(사법경찰관의 사건 송치) 사법경찰관은 가정폭력범죄를 신속히 수사하여 사건을 검사에게 송치하여야 한다. 이 경우 사법경찰관은 해당 사건을 가정보호사건으로 처리하는 것이 적절한지에 관한 의견을 제시할 수 있다.', 206);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1564, '제8조(임시조치의 청구 등)', 206);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1565, '제8조의2(긴급임시조치)', 206);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1566, '제8조의3(긴급임시조치와 임시조치의 청구)', 206);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1567, '제9조(가정보호사건의 처리)', 206);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1568, '제9조의2(상담조건부 기소유예) 검사는 가정폭력사건을 수사한 결과 가정폭력행위자의 성행 교정을 위하여 필요하다고 인정하는 경우에는 상담조건부 기소유예를 할 수 있다.', 206);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1569, '제10조(관할)', 206);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1570, '제11조(검사의 송치)', 206);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1571, '제12조(법원의 송치) 법원은 가정폭력행위자에 대한 피고사건을 심리한 결과 이 법에 따른 보호처분을 하는 것이 적절하다고 인정하는 경우에는 결정으로 사건을 가정보호사건의 관할 법원에 송치할 수 있다. 이 경우 법원은 피해자의 의사를 존중하여야 한다.', 206);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1572, '제13조(송치 시의 가정폭력행위자 처리)', 206);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1573, '제14조(송치서)', 206);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1574, '제15조(이송)', 206);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1575, '제16조(보호처분의 효력) 제40조에 따른 보호처분이 확정된 경우에는 그 가정폭력행위자에 대하여 같은 범죄사실로 다시 공소를 제기할 수 없다. 다만, 제46조에 따라 송치된 경우에는 그러하지 아니하다.', 206);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1576, '제17조(공소시효의 정지와 효력)', 206);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1577, '제18조(비밀엄수 등의 의무)', 206);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1578, '제18조의2(「형사소송법」의 준용) 이 장에서 따로 정하지 아니한 사항에 대하여는 가정보호사건의 성질에 위배되지 아니하는 범위에서 「형사소송법」을 준용한다.', 206);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1579, '제19조(조사ㆍ심리의 방향) 법원은 가정보호사건을 조사ㆍ심리할 때에는 의학, 심리학, 사회학, 사회복지학, 그 밖의 전문적인 지식을 활용하여 가정폭력행위자, 피해자, 그 밖의 가정구성원의 성행, 경력, 가정 상황, 가정폭력범죄의 동기ㆍ원인 및 실태 등을 밝혀서 이 법의 목적을 달성할 수 있는 적정한 처분이 이루어지도록 노력하여야 한다.', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1580, '제20조(가정보호사건조사관)', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1581, '제21조(조사명령 등)', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1582, '제22조(전문가의 의견 조회)', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1583, '제23조(진술거부권의 고지) 판사 또는 가정보호사건조사관은 가정보호사건을 조사할 때에 미리 가정폭력행위자에 대하여 불리한 진술을 거부할 수 있음을 알려야 한다.', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1584, '제24조(소환 및 동행영장)', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1585, '제25조(긴급동행영장) 판사는 가정폭력행위자가 소환에 응하지 아니할 우려가 있거나 피해자 보호를 위하여 긴급히 필요하다고 인정하는 경우에는 제24조제1항에 따른 소환 없이 동행영장을 발부할 수 있다.', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1586, '제26조(동행영장의 방식) 동행영장에는 가정폭력행위자의 성명, 생년월일, 주거, 행위의 개요, 인치(引致)하거나 수용할 장소, 유효기간 및 그 기간이 지난 후에는 집행에 착수하지 못하며 영장을 반환하여야 한다는 취지와 발부 연월일을 적고 판사가 서명ㆍ날인하여야 한다.', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1587, '제27조(동행영장의 집행 등)', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1588, '제28조(보조인)', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1589, '제29조(임시조치)', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1590, '제29조의2(임시조치의 집행 등)', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1591, '제30조(심리기일의 지정)', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1592, '제31조(심리기일의 변경) 판사는 직권으로 또는 가정폭력행위자나 보조인의 청구에 의하여 심리기일을 변경할 수 있다. 이 경우 변경된 기일을 가정폭력행위자, 피해자 및 보조인에게 통지하여야 한다.', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1593, '제32조(심리의 비공개)', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1594, '제33조(피해자의 진술권 등)', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1595, '제34조(증인신문ㆍ감정ㆍ통역ㆍ번역)', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1596, '제35조(검증, 압수 및 수색)', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1597, '제36조(협조와 원조)', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1598, '제37조(처분을 하지 아니한다는 결정)', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1599, '제38조(처분의 기간 등) 가정보호사건은 다른 쟁송보다 우선하여 신속히 처리하여야 한다. 이 경우 처분의 결정은 특별한 사유가 없으면 송치받은 날부터 3개월 이내에, 이송받은 경우에는 이송받은 날부터 3개월 이내에 하여야 한다.', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1600, '제39조(위임규정) 가정보호사건의 조사ㆍ심리에 필요한 사항은 대법원규칙으로 정한다.', 207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1601, '제40조(보호처분의 결정 등)', 208);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1602, '제41조(보호처분의 기간) 제40조제1항제1호부터 제3호까지 및 제5호부터 제8호까지의 보호처분의 기간은 6개월을 초과할 수 없으며, 같은 항 제4호의 사회봉사ㆍ수강명령의 시간은 200시간을 각각 초과할 수 없다.', 208);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1603, '제42조(몰수) 판사는 보호처분을 하는 경우에 결정으로 가정폭력범죄에 제공하거나 제공하려고 한 물건으로서 가정폭력행위자 외의 자의 소유에 속하지 아니하는 물건을 몰수할 수 있다.', 208);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1604, '제43조(보호처분 결정의 집행)', 208);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1605, '제44조(보고와 의견 제출 등) 법원은 제40조제1항제4호부터 제8호까지의 보호처분을 결정한 경우에는 보호관찰관 또는 수탁기관의 장에게 가정폭력행위자에 관한 보고서 또는 의견서 제출을 요구할 수 있고, 그 집행에 대하여 필요한 지시를 할 수 있다.', 208);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1606, '제45조(보호처분의 변경)', 208);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1607, '제46조(보호처분의 취소) 법원은 보호처분을 받은 가정폭력행위자가 제40조제1항제4호부터 제8호까지의 보호처분 결정을 이행하지 아니하거나 그 집행에 따르지 아니하면 직권으로 또는 검사, 피해자, 보호관찰관 또는 수탁기관의 장의 청구에 의하여 결정으로 그 보호처분을 취소하고 다음 각 호의 구분에 따라 처리하여야 한다.', 208);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1608, '제47조(보호처분의 종료) 법원은 가정폭력행위자의 성행이 교정되어 정상적인 가정생활이 유지될 수 있다고 판단되거나 그 밖에 보호처분을 계속할 필요가 없다고 인정하는 경우에는 직권으로 또는 검사, 피해자, 보호관찰관 또는 수탁기관의 장의 청구에 의하여 결정으로 보호처분의 전부 또는 일부를 종료할 수 있다.', 208);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1609, '제48조(비용의 부담)', 208);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1610, '제49조(항고)', 209);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1611, '제50조(항고장의 제출)', 209);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1612, '제51조(항고의 재판)', 209);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1613, '제52조(재항고)', 209);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1614, '제53조(집행의 부정지) 항고와 재항고는 결정의 집행을 정지하는 효력이 없다.', 209);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1615, '제54조(종결된 사건 기록 등의 송부) 법원은 가정보호사건이 종결된 경우에는 지체 없이 사건기록과 결정서를 대응하는 검찰청 검사에게 보내야 한다.', 209);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1616, '제55조(피해자보호명령사건의 관할)', 210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1617, '제55조의2(피해자보호명령 등)', 210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1618, '제55조의3(피해자보호명령의 기간)', 210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1619, '제55조의4(임시보호명령)', 210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1620, '제55조의5(이행실태의 조사)', 210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1621, '제55조의6(병합심리) 법원은 다음 각 호의 어느 하나에 해당하는 경우에는 피해자보호명령사건과 가정보호사건을 병합하여 심리할 수 있다.', 210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1622, '제55조의7(준용) 피해자보호명령의 조사ㆍ심리에 관하여는 제19조부터 제22조까지, 제30조부터 제32조까지, 제34조부터 제36조까지의 규정을 준용한다.', 210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1623, '제55조의8(항고와 재항고)', 210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1624, '제55조의9(위임규정) 피해자보호명령사건의 조사ㆍ심리에 필요한 사항은 대법원규칙으로 정한다.', 210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1625, '제56조(배상신청)', 211);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1626, '제57조(배상명령)', 211);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1627, '제58조(배상명령의 선고)', 211);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1628, '제59조(신청의 각하)', 211);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1629, '제60조(불복)', 211);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1630, '제61조(배상명령의 효력과 강제집행)', 211);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1631, '제62조(다른 법률의 준용) 이 장에서 정하지 아니한 사항에 대하여는 「소송촉진 등에 관한 특례법」과 「민사소송법」의 관련 규정(「민사소송법」 제162조제2항은 제외한다)을 준용한다.', 211);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1632, '제63조(보호처분 등의 불이행죄)', 212);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1633, '제64조(비밀엄수 등 의무의 위반죄)', 212);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1634, '제65조(과태료) 다음 각 호의 어느 하나에 해당하는 사람에게는 500만원 이하의 과태료를 부과한다. <개정 2011.7.25>', 212);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1635, '제66조(과태료) 다음 각 호의 어느 하나에 해당하는 사람에게는 300만원 이하의 과태료를 부과한다.', 212);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1636, '제1조(목적) 이 영은 「가정폭력범죄의 처벌 등에 관한 특례법」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 213);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1637, '제2조(신변안전조치의 청구 등)', 213);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1638, '제3조(신변안전조치의 종류) 법 제55조의2제5항제3호에서 "그 밖에 피해자의 신변안전을 위하여 대통령령으로 정하는 조치"란 다음 각 호의 조치를 말한다.', 213);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1639, '제4조(신변안전조치 종류의 변경 청구 등)', 213);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1640, '제5조(신변안전조치의 집행 방법)', 213);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1641, '제6조(신변안전조치의 이행 통보 등)', 213);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1642, '제7조(전자문서) 제2조제1항에 따른 청구ㆍ요청, 제4조제1항ㆍ제2항에 따른 변경ㆍ추가 및 연장 청구, 같은 조 제3항에 따른 요청 및 제6조제1항ㆍ제2항에 따른 통보 등은 전자문서로 할 수 있다.', 213);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1643, '제1조(목적) 이 영은 「국가보안법」 제21조부터 제24조까지의 규정에 따른 상금 또는 보로금의 지급과 보상 및 국가보안유공자심사위원회의 조직ㆍ운영에 관한 사항을 규정함을 목적으로 한다. <개정 1997.9.30, 2016.12.30>', 214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1644, '제2조(정의) 「국가보안법」(이하 "법"이라 한다) 제21조제3항에서 "교전상태"란 전시ㆍ사변 또는 이에 준하는 국가비상사태하에서의 국방상 필요한 작전의 경우 이외의 교전상태를 말한다. <개정 2016.12.30>', 214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1645, '제3조(상금지급대상등의 조사)', 214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1646, '제4조(국가보안유공자심사위원회의 구성)', 214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1647, '제5조(위원회의 직원)', 214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1648, '제6조(위원회의 회의)', 214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1649, '제7조(통보등 증명서의 교부) 법 제21조제1항의 규정에 의한 통보나 체포된 범인의 인도 또는 법 제22조제2항의 규정에 의한 금품의 제공을 받은 수사 또는 정보기관의 장은 지체없이 통보자ㆍ인도자 또는 금품제공자에게 통보ㆍ인도 또는 제공사실을 증명하는 서면을 교부하여야 한다. 법 제21조제2항의 규정에 의하여 범인을 인지하여 체포한 수사 또는 정보기관의 종사자에 대하여도 또한 같다.', 214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1650, '제8조(상금등의 청구사건) 법 제21조제1항 및 제2항의 규정에 의한 상금과 법 제22조제1항의 규정에 의한 보로금은 그 사건이 공소제기되거나, 기소유예 또는 공소보류된 때에 한하여 청구할 수 있다. 다만, 반국가단체의 지령을 받고 법무부령이 정하는 무기를 소지ㆍ잠입한 자에 관한 경우에는 그러하지 아니하다.', 214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1651, '제9조(처분결과의 통지) 검사 또는 군검사는 법에 의한 상금 또는 보로금의 지급이나 보상대상이 되는 사건에 관하여 공소를 제기하거나 제기하지 아니하는 결정 또는 압수물에 대하여 이를 폐기하거나, 국고귀속처분을 한 때에는 지체없이 관계자에게 서면으로 그 뜻을 통지하여야 한다. <개정 2004.1.13, 2016.12.30, 2022.6.30>', 214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1652, '제10조(상금등의 청구기간) 법에 의한 상금 또는 보로금의 지급 및 보상의 청구는 제9조의 통지를 받은 날로부터 60일이내에 하도록 하여야 한다. 다만, 제8조 단서의 경우에는 그러하지 아니하다. <개정 1997.9.30>', 214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1653, '제11조(상금등의 청구절차) 상금 또는 보로금의 지급을 받고자 하는 자는 위원회에 대하여 다음 각호의 구분에 의한 서류를 첨부하여 서면으로 청구하여야 한다. 다만, 제8조 단서의 규정에 의하여 제9조의 통지를 받기전에 청구하는 때에는 제9조의 통지서를 첨부하지 아니한다. <개정 1982.12.31>', 214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1654, '제12조(상금 등의 지급기준)', 214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1655, '제13조(공동청구의 절차) 청구권자가 2인이상인 때에는 청구권자 전원의 연서로써 청구하여야 한다.', 214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1656, '제14조(보상의 청구절차)', 214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1657, '제15조(보상대상자의 결정) 위원회에서 법 제23조에 따른 보상대상자로 심의ㆍ결정될 수 있는 사람은 다음 각 호의 어느 하나에 해당하여야 한다. <개정 1987.10.26, 1987.12.31, 1997.9.30, 2004.1.13, 2016.12.30>', 214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1658, '제16조(심의결과의 통지)', 214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1659, '제16조의2(상금 등의 환수) 법무부장관은 법 제21조에 따라 상금을 받거나 법 제22조에 따라 보로금을 받은 사람이 다음 각 호의 어느 하나에 해당하는 경우에는 상금 및 보로금의 전부 또는 일부를 환수(還收)할 수 있다.', 214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1660, '제17조(보상대상자의 등록 및 보상)', 214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1661, '제18조(급여의 조정) 제17조에 따른 보상대상자가 같은 사유로 「공무원 재해보상법」ㆍ「군인 재해보상법」ㆍ「국가유공자 등 예우 및 지원에 관한 법률」 및 그 밖의 법령에 따라 국고 또는 지방자치단체의 부담으로 급여를 받은 때에는 그 금액에 상당하는 금액을 법 제23조에 따른 보상의 급여에서 공제하여 지급한다. <개정 1987.10.26, 1997.9.30, 2004.1.13, 2016.12.30, 2018.9.18, 2020.6.9>', 214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1662, '제19조(보상의 해지)', 214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1663, '제1조(목적) 이 영은 몰수금품등처리에관한임시특례법(이하 "법"이라 한다)의 시행에 관하여 필요한 사항을 규정함을 목적으로 한다.', 215);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1664, '제2조(각급 검사등의 통보) 검찰총장ㆍ고등검찰청 검사장ㆍ지방검찰청 검사장 및 국방부검찰단장, 각 군 검찰단장(이하 "각급 검사장"이라 한다)은 법 제2조의 몰수금품이 있을 때에는 지체없이 별지 제1호서식에 의하여 국가정보원장에게 통보하여야 한다. <개정 1999.3.31, 2022.6.30>', 215);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1665, '제3조(국가정보원장의 송부요청)', 215);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1666, '제4조(몰수금품의 송부) 전조제1항의 규정에 의하여 몰수금품의 송부요청을 받은 각급 검사장은 송부요청을 받은 날로부터 10일이내에 그 금품을 국가정보원장에게 송부하여야 한다. <개정 1999.3.31>', 215);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1667, '제5조(대통령의 승인)', 215);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1668, '제6조(반환) 국가정보원장은 제4조의 규정에 의하여 송부받은 금품에 관하여, 법 제3조제1항의 규정에 의한 대통령의 승인을 얻지 못하거나 승인을 받은 후 그 사용ㆍ처분의 필요성이 없어졌다고 인정할 때에는, 그 때부터 15일이내에 그 금품을 송부한 각급 검사장에게 이를 환송하여야 한다. <개정 1999.3.31>', 215);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1669, '제7조(국고납입) 법 제3조제2항의 규정에 의한 국고에의 납부는 납부할 금액을 국가정보원 세출예산중에서 지출하여 이를 국고에 납부함으로써 한다. <개정 1999.3.31>', 215);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1670, '제1조(목적) 이 규칙은 형사소송비용등에관한법률(이하 "법"이라 한다)에 의하여 위임된 사항 및 기타 법원의 형사절차에서 지급하는 비용에 관하여 필요한 사항을 규정함을 목적으로 한다.', 216);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1671, '제2조(증인등의 일당) 법 제3조제2항, 제6조의 규정에 의한 증인ㆍ감정인ㆍ통역인 또는 번역인(이하 "증인등"이라 한다)의 일당은 매년 예산의 범위안에서 대법관회의에서 정한다.', 216);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1672, '제3조(증인등의 여비ㆍ숙박료)', 216);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1673, '제4조(증인등의 국외여행의 경우)', 216);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1674, '제5조(국선변호인의 일당등)', 216);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1675, '제6조(국선변호인의 보수)', 216);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1676, '제1조(목적) 이 법은 국제상거래와 관련하여 외국공무원등에게 뇌물을 제공하는 행위를 처벌함으로써 건전한 국제상거래 질서의 확립에 기여하고 경제협력개발기구의 「국제상거래에 있어서 외국공무원에 대한 뇌물 제공행위 방지를 위한 협약」의 이행에 필요한 사항을 규정함을 목적으로 한다.', 217);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1677, '제2조(외국공무원등의 범위) 이 법에서 "외국공무원등"이란 다음 각 호의 어느 하나에 해당하는 사람을 말한다.', 217);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1678, '제3조(뇌물공여자 등의 형사책임)', 217);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1679, '제4조(양벌규정) 법인의 대표자나 대리인, 사용인, 그 밖의 종업원이 그 법인의 업무에 관하여 제3조제1항의 위반행위를 하면 그 행위자를 벌하는 외에 그 법인도 10억원 이하의 벌금에 처한다. 이 경우 범죄행위로 얻은 이익(이익이 공여액보다 적거나 산정할 수 없는 경우에는 공여액)이 5억원을 초과할 때에는 그 이익(이익이 공여액보다 적거나 산정할 수 없는 경우에는 공여액)의 2배 이상 5배 이하에 해당하는 벌금에 처한다. 다만, 법인이 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다. <개정 2020.2.4>', 217);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1680, '제5조(몰수) 이 법에 규정된 범죄행위에 제공된 뇌물로서 범인(제4조에 따라 처벌되는 법인을 포함한다)이 소유하거나 범인 외의 자가 그 정황을 알면서 취득한 것은 몰수한다.', 217);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1681, '제6조(공소시효에 관한 특례) 제4조에 따른 법인에 대한 공소시효는 7년이 지나면 완성된다.', 217);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1682, '제1조(목적) 이 규칙은 「경범죄 처벌법」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 218);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1683, '제2조(범칙금 납부통고서 등)', 218);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1684, '제3조(범칙금 징수사항 기록부) 영 제5조에 따른 범칙금 징수사항 기록부는 별지 제6호서식에 따른다. <개정 2016.7.19>', 218);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1685, '제4조(즉결심판 출석통지서 등)', 218);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1686, '제5조(즉결심판 통지예고서 등) 영 제7조제1항에 따른 즉결심판 통지예고서는 별지 제12호서식에 따르고, 즉결심판 대상자 적발통보서는 별지 제13호서식에 따른다.', 218);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1687, '제6조(통고처분 접수처리부) 영 제8조제2항에 따른 통고처분 접수처리부는 별지 제14호서식에 따른다.', 218);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1688, '제1조(목적) 이 규칙은 「국민의 형사재판 참여에 관한 법률」(다음부터 "법"이라 한다)이 대법원규칙에 위임한 사항, 그 밖에 국민참여재판절차에 관하여 필요한 사항을 규정함을 목적으로 한다.', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1689, '제2조 삭제 <2012.5.29>', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1690, '제3조(피고인 의사의 확인)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1691, '제3조의2(단독판사 관할사건에 대한 피고인 의사의 확인)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1692, '제4조(피고인 의사확인을 위한 심문기일 등)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1693, '제5조(공소장변경 또는 재정합의결 시 피고인 의사확인)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1694, '제6조(배제결정에 대한 의견)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1695, '제7조(지방법원 지원 관할 사건의 국민참여재판 회부절차)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1696, '제8조(통상절차 회부)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1697, '제9조(여비ㆍ일당 등)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1698, '제10조(여비ㆍ일당 등의 감면) 법원은 다음 각 호의 어느 하나에 해당하는 때에는 배심원ㆍ예비배심원 및 배심원후보자의 여비ㆍ일당 등을 감액하거나 지급하지 아니할 수 있다.', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1699, '제11조(배심원 직무의 면제)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1700, '제12조(주민등록정보)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1701, '제13조(배심원후보예정자명부의 작성)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1702, '제14조(배심원후보예정자명부의 관리)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1703, '제15조(전담관리자의 지정)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1704, '제16조(선정기일의 통지)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1705, '제17조(질문표)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1706, '제18조(배심원후보자의 의무)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1707, '제19조(배심원후보자의 호칭)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1708, '제20조(배심원후보자에 대한 질문)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1709, '제21조(무이유부기피신청)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1710, '제22조(배심원ㆍ예비배심원의 선정) 법원은 검사ㆍ피고인 또는 변호인에게 누가 배심원 또는 예비배심원으로 선정되었는지를 변론종결시까지 알리지 아니할 수 있다.', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1711, '제23조(선정기일 조서)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1712, '제24조(선정기일 조서의 증명력) 선정기일의 절차로서 선정기일조 서에 기재된 것은 그 조서만으로써 증명한다.', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1713, '제25조(배심원의 해임)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1714, '제26조(배심원의 사임)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1715, '제27조(공판준비절차) 법원은 법 제24조에 따른 배심원 선정기일 이전에 공판준비절차를 마쳐야 한다. 다만, 「형사소송법」 제266조의15에 따라 공판기일 사이에 공판준비기일을 진행하는 때에는 그러하지 아니하다.', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1716, '제28조(배심원에 대한 배려) 판사, 검사 및 변호인은 신속하고 이해하기 쉽게 심리를 진행하여 배심원과 예비배심원의 부담을 최소화하도록 노력하여야 한다.', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1717, '제29조(제1회 공판기일의 지정) 재판장은 특별한 사정이 없는 한 배심원 선정기일이 종료된 후 연속하여 제1회 공판기일이 진행되도록 기일을 지정하여야 한다.', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1718, '제30조(배심원의 좌석 등)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1719, '제31조(공판조서의 기재사항) 국민참여재판의 공판조서에는 「형사소송법」 제51조제2항제1호부터 제14호까지에 기재된 각 사항 이외에 법원이 배심원과 예비배심원에게 부여한 번호와 그 출석 여부를 기재하여야 한다.', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1720, '제32조(공판기일의 속행) 재판장은 공판기일을 속행하는 경우에는 배심원과 예비배심원에게 법 제41조제2항제2호 및 제3호에 규정된 의무를 주지시켜야 한다.', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1721, '제33조(배심원의 신문요청권)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1722, '제34조(배심원의 필기 등)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1723, '제35조(선서 등)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1724, '제36조(공판정 외에서의 검증, 증인신문 등)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1725, '제37조(재판장의 설명)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1726, '제38조(변론종결 후 예비배심원의 임무)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1727, '제39조(평의 등의 기일 지정과 비공개)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1728, '제40조(배심원 대표)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1729, '제41조(평의의 방식)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1730, '제42조(평결의 방식) 배심원 대표는 평의가 종료되면 배심원 전원에 대하여 개개인의 의사를 명확하게 확인한 후 유죄의견의 수, 무죄의견의 수로 구분하여 법 제46조제2항 또는 제3항에 따른 평결서를 작성한 후 배심원들의 서명 또는 날인을 받아 즉시 이를 재판장에게 전달하여야 한다.', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1731, '제43조(판결선고시의 배심원 불출석) 법 제48조제1항 단서에 따라 선고기일을 따로 지정한 경우에는 배심원의 출석 없이 개정할 수 있다.', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1732, '제44조(배심원 등의 개인정보 공개절차)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1733, '제45조(배심원 등에 대한 신변보호조치)', 219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1734, '제1조(목적) 이 영은 교통사고처리특례법(이하 "법"이라 한다)에서 위임된 사항과 그 시행에 관하여 필요한 사항을 규정함을 목적으로 한다.', 220);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1735, '제2조(우선 지급할 치료비에 관한 통상비용의 범위)', 220);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1736, '제3조(우선지급할 치료비외의 손해배상금의 범위)', 220);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1737, '제4조(손해배상금의 우선지급절차)', 220);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1738, '제5조(피해자에 대한 성실보호) 보험사업자 및 공제사업자는 보험 또는 공제와 관련된 교통사고 피해자의 보호관리업무를 성실히 수행하여야 한다.', 220);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1739, '제6조(법 제4조 내지 제6조의 시행일) 법 제4조 내지 제6조의 규정은 1982년 6월 30일부터 시행한다.', 220);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1740, '제1조(목적) 이 영은 「군에서의 형의 집행 및 군수용자의 처우에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 221);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1741, '제2조(군미결수용실의 설치) 「군에서의 형의 집행 및 군수용자의 처우에 관한 법률」(이하 "법"이라 한다) 제4조제2항에서 "대통령령으로 정하는 부대"란 장성급(將星級) 장교 또는 2급 이상 군무원이 지휘하는 부대를 말한다. <개정 2017.9.5, 2019.11.26>', 221);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1742, '제3조(군판사 등의 시찰)', 221);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1743, '제4조(참관)', 221);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1744, '제5조(수용거실의 설치) 군교정시설의 수용거실(이하 "거실"이라 한다)은 법 제13조에 따라 군수용자를 수용할 수 있도록 독거실(獨居室)과 혼거실(混居室)을 적정 비율로 설치하여야 한다.', 223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1745, '제6조(독거수용의 구분) 법 제13조에 따른 독거수용은 다음 각 호의 구분에 따른다.', 223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1746, '제7조(계호독거자의 시찰)', 223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1747, '제8조(여성 군수용자의 시찰) 소장은 여성 군수용자의 생명과 신체의 보호 또는 군교정시설의 안전과 질서유지를 위하여 특히 필요하다고 인정하는 경우가 아니면 야간에 남성 군교도관이 여성 군수용자가 있는 거실을 시찰하게 해서는 아니 된다.', 223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1748, '제9조(혼거수용 인원의 기준) 법 제14조에 따른 혼거수용 인원은 3명 이상으로 한다. 다만, 요양이나 교화, 그 밖에 부득이한 사정이 있는 경우에는 2명으로 할 수 있다.', 223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1749, '제10조(혼거수용의 제한) 소장은 노역장 유치명령을 받은 군수형자와 징역ㆍ금고 또는 구류의 형이 확정된 군수형자를 혼거수용해서는 아니 된다. 다만, 징역ㆍ금고 또는 구류의 형 집행을 마친 군수형자에 대한 노역장 유치명령을 집행하는 경우나, 수용시설이 부족한 경우 등 부득이한 사정이 있는 경우에는 그러하지 아니하다.', 223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1750, '제11조(군수용자의 자리 지정) 소장은 군수용자의 생명과 신체의 보호, 증거인멸의 방지 및 군교정시설의 안전과 질서유지를 위하여 필요하다고 인정하면 거실, 교육실, 강당, 작업장, 그 밖에 군수용자들이 서로 접촉할 수 있는 장소에서 군수용자의 자리를 지정할 수 있다.', 223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1751, '제12조(거실의 대체 사용 금지) 소장은 거실을 작업장으로 사용해서는 아니 된다. 다만, 군수용자의 심리적 안정, 교정ㆍ교화 또는 사회 적응 능력을 높이기 위하여 필요한 경우에는 그러하지 아니하다.', 223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1752, '제13조(현황표 등의 부착 등)', 223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1753, '제14조(신입자 등의 인수)', 223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1754, '제15조(신입자 등의 신체 등 검사) 소장은 신입자나 이입자를 인수하였을 때에는 즉시 군교도관에게 신입자나 이입자의 신체, 의류 및 휴대품을 검사하게 하여야 한다.', 223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1755, '제16조(신입자 등의 목욕) 소장은 신입자나 이입자가 질병에 걸렸거나 그 밖에 부득이한 사정이 있는 경우가 아니면 지체 없이 목욕을 하게 하여야 한다.', 223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1756, '제17조(신입자 등의 건강진단) 소장은 법 제15조제2항에 따라 신입자나 이입자가 수용된 날부터 3일 이내에 건강진단을 실시하여야 한다. 다만, 휴무일이 연속되는 등 부득이한 사정이 있는 경우에는 그러하지 아니하다.', 223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1757, '제18조(신입자 등의 신체 특징 기록 등)', 223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1758, '제19조(수용기록부 등의 작성) 소장은 신입자와 이입자를 수용한 날부터 3일 이내에 수용기록부, 군수용자명부 및 형기종료부를 작성하고 필요한 사항을 적어야 한다.', 223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1759, '제20조(신입자거실 등)', 223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1760, '제21조(신입자의 신원조사) 소장은 신입자의 신원에 관한 사항을 조사하여 제19조에 따른 수용기록부에 기록하여야 한다.', 223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1761, '제22조(형 또는 구속의 집행정지 사유의 통보) 소장은 군수용자에 대하여 건강상의 사유로 형의 집행정지나 구속의 집행정지를 할 필요가 있다고 인정하면 군의관의 진단서와 군수용자를 인수할 사람에 대한 확인서류를 첨부하여 군검사에게 통보하여야 한다. 이 경우 기소된 군수용자에 대하여 구속의 집행정지를 할 때에는 군사법원에도 통보하여야 한다. <개정 2022.6.30>', 223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1762, '제23조(이송 중지) 소장은 군의관으로부터 군수용자의 건강상태가 다른 교정시설로 이송하는 것을 감당하기 어렵다는 보고를 받은 경우에는 이송을 중지하고 그 사실을 이송받을 소장에게 알려야 한다.', 223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1763, '제24조(차량호송 시 군수용자의 분리) 이송이나 출정(出廷), 그 밖의 사유로 차량을 이용하여 군수용자를 호송하는 경우에는 군수형자와 군미결수용자, 여성 군수용자와 남성 군수용자의 좌석을 지정하는 등의 방법으로 분리하여 서로 접촉하지 못하도록 하여야 한다.', 223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1764, '제25조(의류 등의 지급) 소장은 법 제22조제1항에 따라 군수용자에게 의류, 침구, 그 밖의 생활용품(이하 "의류등"이라 한다)을 지급하는 경우에는 다른 사람이 사용한 의류등은 세탁하거나 소독하여 지급하여야 하고, 식기는 청결하게 관리할 수 있는 재질로 된 것으로 지급하여야 한다.', 224);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1765, '제26조(생활기구의 비치)', 224);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1766, '제27조(음식물의 구분) 법 제23조에 따라 군수용자에게 지급하는 음식물은 주식, 부식, 음료와 그 밖의 영양물로 한다.', 224);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1767, '제28조(주식의 지급기준) 군수용자에게 지급하는 주식은 현역 군인에 준하여 지급한다.', 224);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1768, '제29조(특식의 지급) 소장은 국경일이나 그 밖에 이에 준하는 날에는 특별한 음식물을 그 소속 현역 군인에 준하여 지급할 수 있다. <개정 2014.10.28>', 224);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1769, '제30조(환자의 음식물) 소장은 군의관의 의견을 고려하여 환자에게 지급하는 음식물의 종류 또는 정도를 달리 정할 수 있다.', 224);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1770, '제31조(자비구매 허가의 기준) 소장은 법 제24조에 따라 군수용자의 교화나 건전한 사회복귀에 적합하고 군교정시설의 안전이나 질서를 해칠 우려가 없다고 인정되는 음식물과 의류등을 군수용자 자신의 비용으로 구매하도록 허가할 수 있다.', 224);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1771, '제32조(자비구매 의류등의 사용) 소장은 군수용자가 자신의 비용으로 구매한 의류등을 영치(領置)한 후 그 군수용자가 사용하게 할 수 있다.', 224);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1772, '제33조(의류등의 세탁 등)', 224);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1773, '제34조(휴대품의 사용 등)', 225);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1774, '제35조(금품의 영치) 군수용자의 현금(자기앞수표를 포함한다. 이하 같다)을 영치하는 경우에는 영치금대장에 금액을 적고, 군수용자의 물품을 영치하는 경우에는 영치품대장에 품목, 수량 및 규격을 적어야 한다.', 225);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1775, '제36조(귀중품의 보관) 소장은 영치하는 물품이 금, 은, 보석, 유가증권, 도장, 그 밖에 특별히 보관할 필요가 있는 귀중품인 경우에는 잠금장치가 되어 있는 견고한 용기에 넣어 보관하여야 한다.', 225);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1776, '제37조(영치품 매각대금의 영치) 소장은 군수용자의 신청에 따라 영치품을 팔았을 때에는 판매 비용을 제외한 나머지 대금을 영치할 수 있다.', 225);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1777, '제38조(소지범위 초과 물품의 처리) 법 제26조제2항 및 제3항에 따른 소지범위를 벗어난 물품의 처분과 폐기에 관하여는 제34조제2항 및 제3항을 준용한다.', 225);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1778, '제39조(폐기 물품의 기록) 군수용자의 물품을 폐기하였을 때에는 그 품목, 수량, 이유 및 일시를 관계 장부에 기록하여야 한다.', 225);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1779, '제40조(금품 교부 신청자의 확인) 소장은 법 제27조제1항에 따른 군수용자에 대한 금품 교부를 허가하기 전에 교부를 신청한 사람의 성명, 주소 및 군수용자와의 관계를 확인하여야 한다.', 225);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1780, '제41조(교부 허가 금품의 검사 등)', 225);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1781, '제42조(유류금품의 교부 비용) 법 제28조제2항 또는 제3항에 따라 사망자나 도주자의 금품 또는 매각대금을 보내는 데에 드는 비용은 그 교부를 청구한 사람이 부담한다.', 225);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1782, '제43조(영치금의 사용 등)', 225);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1783, '제44조(보건ㆍ위생관리계획의 수립 등) 소장은 군수용자의 건강, 계절 및 시설 여건 등을 고려하여 보건ㆍ위생관리계획을 정기적으로 수립하여 시행하여야 한다.', 226);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1784, '제45조(시설의 청소ㆍ소독)', 226);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1785, '제46조(청결의무) 군수용자는 법 제33조제1항에 따라 자신이 사용하는 거실, 작업장, 그 밖의 수용시설의 청결을 유지하기 위한 군교도관의 지시에 따라야 한다.', 226);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1786, '제47조(실외운동) 소장은 법 제34조에 따라 군수용자가 매일(공휴일 및 국방부장관이 정하는 날은 제외한다) 군(軍) 표준일과표에 따른 근무시간에 1시간 이내의 실외운동을 할 수 있도록 하여야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 실외운동을 실시하지 아니할 수 있다.', 226);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1787, '제48조(목욕 횟수) 소장은 법 제34조에 따라 작업의 특성, 계절, 그 밖의 사정을 고려하여 군수용자의 목욕 횟수를 정하되, 특별한 사정이 없으면 매주 1회 이상이 되도록 한다.', 226);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1788, '제49조(건강검진 횟수)', 226);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1789, '제50조(감염병에 관한 조치)', 226);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1790, '제51조(의료용 거실에의 수용 등)', 226);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1791, '제52조(외부의료시설 진료 등)', 226);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1792, '제53조(접견)', 227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1793, '제54조(접견의 예외)', 227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1794, '제55조(접견 시 유의사항 고지) 소장은 법 제42조에 따라 접견하게 하는 경우에는 군수용자와 그 상대방에게 접견할 때의 유의사항을 방송이나 게시물 부착 등의 적절한 방법으로 알려주어야 한다.', 227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1795, '제56조(접견내용의 청취 등)', 227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1796, '제57조(접견기록물의 관리 등)', 227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1797, '제58조(접견 중지 사유의 고지) 군교도관이 법 제43조에 따라 군수용자의 접견을 중지하였을 때에는 그 사유를 즉시 알려주어야 한다.', 227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1798, '제59조(서신수수의 횟수) 군수용자가 법 제44조에 따라 보내거나 받을 수 있는 서신의 횟수는 제한하지 아니한다.', 227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1799, '제60조(서신 내용물의 확인)', 227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1800, '제61조(서신 내용의 검열)', 227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1801, '제62조(관계 기관 송부문서) 소장은 군사법원, 군사경찰부대, 그 밖의 관계 기관에서 군수용자에게 보내온 문서는 다른 법령에 특별한 규정이 없으면 열람한 후 본인에게 전달하여야 한다. <개정 2020.2.4>', 227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1802, '제63조(서신 등의 대서) 소장은 군수용자가 서신, 소송서류, 그 밖의 문서를 스스로 작성할 수 없어 대신 써 달라고 요청하는 경우에는 군교도관으로 하여금 대신 쓰게 할 수 있다.', 227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1803, '제64조(서신 등 발송비용의 부담) 군수용자의 서신, 소송서류, 그 밖의 문서를 보내는 데에 드는 비용은 군수용자가 부담한다. 다만, 소장은 군수용자가 그 비용을 부담할 수 없는 경우에는 예산의 범위에서 해당 비용을 부담할 수 있다. <개정 2014.10.28>', 227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1804, '제65조(전화통화의 허가 범위)', 227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1805, '제66조(전화통화 시간)', 227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1806, '제67조(통화내용의 청취ㆍ녹음)', 227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1807, '제68조(통화요금의 부담)', 227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1808, '제69조(준용) 전화통화 시 외국어의 사용 및 전화통화의 중지에 관하여는 제56조제2항 및 제58조를 준용한다.', 227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1809, '제70조(참고사항의 기록) 군교도관은 군수용자의 접견, 서신수수, 전화통화 등의 과정에서 군수용자의 처우에 특히 참고할 사항을 알게 된 경우에는 그 요지를 수용기록부에 기록하여야 한다.', 227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1810, '제71조(비치도서의 이용)', 228);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1811, '제72조(라디오 청취 등의 방법) 법 제49조제1항에 따른 군수용자의 라디오 청취와 텔레비전 시청은 군교정시설에 설치된 방송설비를 통하여 할 수 있다.', 228);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1812, '제73조(집필용구의 관리 등)', 228);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1813, '제74조(집필의 시간 등)', 228);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1814, '제75조(문서ㆍ도화의 외부 발송 등)', 228);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1815, '제76조(군수형자로서의 처우 개시)', 230);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1816, '제77조(군수형자의 처우등급 부여 등)', 230);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1817, '제78조(군수형자 취업알선 등) 소장은 군수형자의 건전한 사회복귀를 지원하기 위하여 취업알선 및 창업지원을 위해 노력하여야 한다.', 230);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1818, '제79조(교육)', 231);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1819, '제80조(정서교육) 소장은 군수형자의 정서 함양을 위하여 필요하다고 인정하면 연극ㆍ영화관람, 체육행사, 그 밖의 문화예술활동을 하게 할 수 있다.', 231);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1820, '제81조(작업)', 232);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1821, '제82조(작업실적의 확인) 소장은 군교도관에게 매일 군수형자의 작업실적을 확인하게 하여야 한다.', 232);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1822, '제83조(신청 작업의 취소) 소장은 법 제57조에 따라 작업이 부과된 군수형자가 작업의 취소를 요청하는 경우에는 그 군수형자의 의사(意思), 건강 및 군교도관의 의견 등을 고려하여 작업을 취소할 수 있다.', 232);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1823, '제84조(직업능력개발훈련 설비 등의 구비) 소장은 법 제59조에 따른 직업능력개발훈련을 하는 경우에는 그에 필요한 설비 및 실습 자재를 갖추어야 한다.', 232);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1824, '제85조(휴업일) 법 제60조제1항 및 제61조에서 "대통령령으로 정하는 휴일"이란 12월 31일, 「각종 기념일 등에 관한 규정」에 따른 교정의 날 및 소장이 지정하는 날을 말한다.', 232);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1825, '제86조(귀휴자에 대한 조치)', 233);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1826, '제87조(법률구조 지원) 소장은 군미결수용자가 빈곤하거나 무지하여 수사나 재판 과정에서 권리를 충분히 행사하지 못한다고 인정하는 경우에는 법률구조에 필요한 지원을 할 수 있다.', 234);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1827, '제88조(공범 분리) 소장은 이송이나 출정, 그 밖의 사유로 군미결수용자를 군교정시설 밖으로 호송하는 경우에는 해당 사건에 관련된 사람과 호송 차량의 좌석을 분리하는 등의 방법으로 서로 접촉하지 못하게 하여야 한다.', 234);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1828, '제89조(접견 횟수) 군미결수용자의 접견 횟수는 매일 1회로 한다. 이 경우 변호인과의 접견은 그 횟수에 포함하지 아니한다.', 234);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1829, '제90조(접견의 예외) 소장은 군미결수용자의 처우를 위하여 특히 필요하다고 인정하면 제53조제1항ㆍ제2항ㆍ제4항 및 제89조에도 불구하고 접견시간 외의 시간에도 접견하게 할 수 있고, 접견시간을 연장하거나 접견 횟수를 늘릴 수 있으며, 접견실 외의 장소에서 접견하게 할 수 있다.', 234);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1830, '제91조(교육ㆍ교화와 작업)', 234);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1831, '제92조(도주 등 통보) 소장은 군미결수용자가 도주하거나 도주한 군미결수용자를 체포한 경우에는 그 사실을 즉시 군검사에게 통보하여야 한다. 이 경우 군미결수용자가 기소된 때에는 군사법원에도 통보하여야 한다. <개정 2022.6.30>', 234);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1832, '제93조(사망 등 통보) 소장은 군미결수용자가 위독하거나 사망한 경우에는 그 사실을 즉시 군검사에게 통보하여야 한다. 이 경우 군미결수용자가 기소된 때에는 군사법원에도 통보하여야 한다. <개정 2022.6.30>', 234);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1833, '제94조(군의관이나 외부의사의 진찰 등) 군미결수용자가 「군사법원법」 제63조, 제129조 및 제246조에 따라 군의관이나 외부의사에게 진료를 받을 때에는 군교도관이 참여하여 그 경과를 제19조에 따른 수용기록부에 기록하여야 한다.', 234);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1834, '제95조(접견 횟수) 사형확정자의 접견 횟수는 매월 4회로 한다.', 235);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1835, '제96조(접견의 예외) 소장은 사형확정자의 교화나 심리적 안정을 도모하기 위하여 특히 필요하다고 인정하면 제53조제1항ㆍ제2항ㆍ제4항 및 제95조에도 불구하고 접견시간 외의 시간에도 접견을 하게 할 수 있고, 접견시간을 연장하거나 접견 횟수를 늘릴 수 있으며, 접견실 외의 장소에서 접견하게 할 수 있다.', 235);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1836, '제97조(사형 집행 후의 검시 등)', 235);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1837, '제98조(거실등에 대한 검사) 소장은 법 제80조에 따라 군교도관에게 거실등을 정기적으로 검사하게 하여야 한다. 다만, 법 제79조의 금지물품을 숨기고 있다고 의심되는 군수용자의 거실등은 수시로 검사하게 할 수 있다.', 236);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1838, '제99조(신체 등에 대한 검사) 소장은 법 제80조에 따라 군교도관에게 작업장이나 실외에서 거실로 돌아오는 군수용자의 신체, 의류 및 휴대품을 검사하게 하여야 한다. 다만, 교정성적 등을 고려하여 그 검사가 필요하지 아니하다고 인정되는 경우에는 예외로 할 수 있다.', 236);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1839, '제100조(검사장비의 이용) 군교도관은 법 제80조에 따른 검사를 위하여 탐지견(探知犬), 금속탐지기, 그 밖의 장비를 이용할 수 있다.', 236);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1840, '제101조(외부인의 출입) 군교도관 외의 사람은 군 표준일과표에 따른 근무시간 외에는 소장의 허가 없이 군교정시설에 출입하지 못한다.', 236);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1841, '제102조(외부와의 차단)', 236);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1842, '제103조(거실의 개방 금지) 군교도관은 수사, 재판, 운동, 접견, 진료 등 군수용자의 처우를 위한 경우나 자살방지, 화재진압 등 군교정시설의 안전과 질서유지를 위하여 필요한 경우가 아니면 거실문을 열거나 군수용자를 거실 밖으로 나오게 해서는 아니 된다.', 236);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1843, '제104조(장애물 방치 금지) 군교정시설의 구내에는 시야를 가리거나 그 밖에 계호상 장애가 되는 물건을 두어서는 아니 된다.', 236);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1844, '제105조(보호실 등 수용 중지)', 236);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1845, '제106조(보호장비의 사용 등)', 236);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1846, '제107조(보호장비 착용 군수용자의 거실 지정) 보호장비를 착용 중인 군수용자는 특별한 사정이 없으면 계호상 독거수용을 하여야 한다.', 236);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1847, '제108조(보호장비 사용의 감독)', 236);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1848, '제109조(강제력의 행사) 군교도관과 교도병은 소장의 명령 없이 법 제87조에 따른 강제력을 행사해서는 아니 된다. 다만, 그 명령을 받을 시간적 여유가 없는 경우에는 강제력을 행사한 후 소장에게 즉시 보고하여야 한다.', 236);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1849, '제110조(무기사용 보고) 군교도관과 교도병은 법 제88조에 따라 무기를 사용하였을 때에는 즉시 소장에게 보고하여야 하고, 보고를 받은 소장은 그 사실을 국방부장관에게 즉시 보고하여야 한다.', 236);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1850, '제111조(재난 시의 조치)', 236);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1851, '제112조(도주 등에 따른 조치)', 236);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1852, '제113조(징벌위원회 기능) 법 제97조에 따른 징벌위원회(이하 이 장에서 "위원회"라 한다)는 다음 각 호에 관한 사항을 심의ㆍ의결한다.', 237);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1853, '제114조(징벌위원회 외부 위원)', 237);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1854, '제115조(위원장의 직무)', 237);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1855, '제116조(간사)', 237);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1856, '제117조(수당 등) 위원회의 위원 등에 대해서는 예산의 범위에서 수당, 여비, 그 밖의 필요한 경비를 지급할 수 있다. 다만, 공무원인 위원이 그 소관 업무와 직접적으로 관련되어 위원회에 출석하는 경우에는 그러하지 아니하다.', 237);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1857, '제118조(운영세칙) 이 영에서 규정한 사항 외에 위원회의 운영에 필요한 사항은 위원회의 의결을 거쳐 위원장이 정한다.', 237);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1858, '제119조(징벌의 집행)', 237);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1859, '제120조(징벌 집행의 계속) 법 제94조제4호부터 제14호까지의 징벌 집행 중에 있는 군수용자가 다른 군교정시설로 이송되거나 군사법원 또는 군검찰부 등에 출석하는 경우에도 징벌집행이 계속되는 것으로 본다.', 237);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1860, '제121조(징벌기간의 계산) 소장은 법 제99조제1항에 따라 징벌 집행을 일시 정지한 경우 그 정지사유가 해소되었을 때에는 지체 없이 징벌 집행을 재개하여야 한다. 이 경우 집행을 정지한 다음 날부터 집행을 재개(再開)한 전날까지의 일수는 징벌기간으로 계산하지 아니한다.', 237);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1861, '제122조(이송된 사람의 징벌) 군수용자가 이송 중에 징벌 부과의 대상이 되는 행위를 하였거나 다른 군교정시설에서 징벌 부과의 대상이 되는 행위를 한 사실이 이송 후에 발각되었을 때에는 그 군수용자를 인수한 소장이 징벌을 부과한다.', 237);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1862, '제123조(징벌사항의 기록) 소장은 군수용자의 징벌에 관한 사항을 징벌집행부 및 제19조에 따른 수용기록부에 기록하여야 한다.', 237);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1863, '제124조(소장 면담)', 238);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1864, '제125조(순회점검공무원에 대한 청원)', 238);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1865, '제126조(가석방 허가 신청의 절차) 법 제107조제1항에 따라 가석방 허가를 신청하는 경우에는 다음 각 호의 서류를 첨부하여 군수형자가 소속되어 있거나 소속되었던 군의 법무실장을 거쳐 국방부장관에게 신청하여야 한다. <개정 2014.10.28>', 240);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1866, '제127조(가석방자 교육 등) 소장은 법 제107조제2항에 따라 가석방을 허가받은 군수형자에 대하여 가석방자 교육을 하고, 가석방자가 지켜야 할 준수사항을 알려주어야 하며, 가석방 증서를 발급한 후 석방하여야 한다.', 240);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1867, '제128조(석방 예정자에 대한 상담 등) 소장은 군수형자의 건전한 사회복귀를 위하여 필요하다고 인정하면 석방 전 3일 이내의 범위에서 석방 예정자를 별도의 거실에 수용하여 장래에 관한 상담과 지도를 할 수 있다.', 241);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1868, '제129조(형기 종료 석방 예정자의 사전조사) 소장은 형기 종료로 석방될 군수형자에 대해서는 석방 10일 전까지 석방 후 보호에 관한 사항을 조사하여야 한다.', 241);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1869, '제130조(석방 예정자의 교정성적 등 통보) 소장은 석방될 군수형자의 보호 및 재범 방지 등을 위하여 필요하다고 인정하면 군수형자의 성격, 교정성적 또는 보호에 관한 의견을 군수형자의 거주지를 관할하는 국가경찰관서나 군수형자를 인수하여 보호할 법인 또는 개인에게 통보할 수 있다. 다만, 법인 또는 개인에게 통보하는 경우에는 해당 군수형자의 동의를 받아야 한다.', 241);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1870, '제131조(석방된 사람의 보호) 소장은 군수형자를 석방할 때 필요하다고 인정하면 「보호관찰 등에 관한 법률」 제71조에 따른 한국법무보호복지공단에 석방된 사람의 보호를 요청할 수 있다.', 241);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1871, '제132조(귀가 여비 등의 회수) 소장은 법 제111조에 따라 석방된 사람에게 귀가 여비나 의류를 빌려주었을 때에는 특별한 사유가 없으면 이를 회수하여야 한다.', 241);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1872, '제133조(사망 통지) 소장은 법 제112조에 따라 군수용자의 사망 사실을 알리는 경우에는 사망 일시, 장소, 사유 및 법 제28조의 유류금품, 법 제63조제2항의 작업장려금, 법 제64조제2항의 조위금에 관한 사항도 같이 알려야 한다.', 242);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1873, '제134조(사망기록부)', 242);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1874, '제135조(화장한 유골의 처리)', 242);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1875, '제136조(임시 매장지의 표지 등)', 242);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1876, '제137조(교정위원)', 243);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1877, '제138조(기부금품의 접수 등)', 243);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1878, '제139조(권한의 위임)', 243);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1879, '제1조(목적) 이 영은 「형의 집행 및 수용자의 처우에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 244);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1880, '제1조의2(협의체의 구성 및 운영 등)', 244);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1881, '제2조(판사 등의 시찰)', 244);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1882, '제3조(참관)', 244);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1883, '제4조(독거실의 비율) 교정시설을 새로 설치하는 경우에는 법 제14조에 따른 수용자의 거실수용을 위하여 독거실(獨居室)과 혼거실(混居室)의 비율이 적정한 수준이 되도록 한다.', 246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1884, '제5조(독거수용의 구분) 독거수용은 다음 각 호와 같이 구분한다.', 246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1885, '제6조(계호상 독거수용자의 시찰)', 246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1886, '제7조(여성수용자에 대한 시찰) 소장은 특히 필요하다고 인정하는 경우가 아니면 남성교도관이 야간에 수용자거실에 있는 여성수용자를 시찰하게 하여서는 아니 된다.', 246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1887, '제8조(혼거수용 인원의 기준) 혼거수용 인원은 3명 이상으로 한다. 다만, 요양이나 그 밖의 부득이한 사정이 있는 경우에는 예외로 한다.', 246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1888, '제9조(혼거수용의 제한) 소장은 노역장 유치명령을 받은 수형자와 징역형ㆍ금고형 또는 구류형을 선고받아 형이 확정된 수형자를 혼거수용해서는 아니 된다. 다만, 징역형ㆍ금고형 또는 구류형의 집행을 마친 다음에 계속해서 노역장 유치명령을 집행하거나 그 밖에 부득이한 사정이 있는 경우에는 그러하지 아니하다.', 246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1889, '제10조(수용자의 자리 지정) 소장은 수용자의 생명ㆍ신체의 보호, 증거인멸의 방지 및 교정시설의 안전과 질서유지를 위하여 필요하다고 인정하면 혼거실ㆍ교육실ㆍ강당ㆍ작업장, 그 밖에 수용자들이 서로 접촉할 수 있는 장소에서 수용자의 자리를 지정할 수 있다.', 246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1890, '제11조(거실의 대용금지) 소장은 수용자거실을 작업장으로 사용해서는 아니 된다. 다만, 수용자의 심리적 안정, 교정교화 또는 사회적응능력 함양을 위하여 특히 필요하다고 인정하면 그러하지 아니하다.', 246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1891, '제12조(현황표 등의 부착 등)', 246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1892, '제13조(신입자의 인수)', 246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1893, '제14조(신입자의 신체 등 검사) 소장은 신입자를 인수한 경우에는 교도관에게 신입자의 신체ㆍ의류 및 휴대품을 지체 없이 검사하게 하여야 한다.', 246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1894, '제15조(신입자의 건강진단) 법 제16조제2항에 따른 신입자의 건강진단은 수용된 날부터 3일 이내에 하여야 한다. 다만, 휴무일이 연속되는 등 부득이한 사정이 있는 경우에는 예외로 한다.', 246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1895, '제16조(신입자의 목욕) 소장은 신입자에게 질병이나 그 밖의 부득이한 사정이 있는 경우가 아니면 지체 없이 목욕을 하게 하여야 한다.', 246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1896, '제17조(신입자의 신체 특징 기록 등)', 246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1897, '제18조(신입자거실 수용 등)', 246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1898, '제19조(수용기록부 등의 작성) 소장은 신입자 또는 이입자를 수용한 날부터 3일 이내에 수용기록부, 수용자명부 및 형기종료부를 작성ㆍ정비하고 필요한 사항을 기록하여야 한다.', 246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1899, '제20조(신입자의 신원조사)', 246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1900, '제21조(형 또는 구속의 집행정지 사유의 통보) 소장은 수용자에 대하여 건강상의 사유로 형의 집행정지 또는 구속의 집행정지를 할 필요가 있다고 인정하는 경우에는 의무관의 진단서와 인수인에 대한 확인서류를 첨부하여 그 사실을 검사에게, 기소된 상태인 경우에는 법원에도 지체 없이 통보하여야 한다.', 246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1901, '제22조(지방교정청장의 이송승인권)', 246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1902, '제23조(이송 중지) 소장은 수용자를 다른 교정시설에 이송하는 경우에 의무관으로부터 수용자가 건강상 감당하기 어렵다는 보고를 받으면 이송을 중지하고 그 사실을 이송받을 소장에게 알려야 한다.', 246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1903, '제24조(호송 시 분리) 수용자를 이송이나 출정(出廷), 그 밖의 사유로 호송하는 경우에는 수형자는 미결수용자와, 여성수용자는 남성수용자와, 19세 미만의 수용자는 19세 이상의 수용자와 각각 호송 차량의 좌석을 분리하는 등의 방법으로 서로 접촉하지 못하게 하여야 한다.', 246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1904, '제25조(생활용품 지급 시의 유의사항)', 247);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1905, '제26조(생활기구의 비치)', 247);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1906, '제27조(음식물의 지급) 법 제23조에 따라 수용자에게 지급하는 음식물은 주식ㆍ부식ㆍ음료, 그 밖의 영양물로 한다.', 247);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1907, '제28조(주식의 지급)', 247);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1908, '제29조(특식의 지급) 소장은 국경일이나 그 밖에 이에 준하는 날에는 특별한 음식물을 지급할 수 있다.', 247);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1909, '제30조(환자의 음식물) 소장은 의무관의 의견을 고려하여 환자에게 지급하는 음식물의 종류 또는 정도를 달리 정할 수 있다.', 247);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1910, '제31조(자비 구매 물품의 기준) 수용자가 자비로 구매하는 물품은 교화 또는 건전한 사회복귀에 적합하고 교정시설의 안전과 질서를 해칠 우려가 없는 것이어야 한다.', 247);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1911, '제32조(자비 구매 의류등의 사용) 소장은 수용자가 자비로 구매한 의류등을 보관한 후 그 수용자가 사용하게 할 수 있다. <개정 2020.8.5>', 247);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1912, '제33조(의류등의 세탁 등)', 247);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1913, '제34조(휴대금품의 정의 등)', 248);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1914, '제35조(금품의 보관) 수용자의 현금을 보관하는 경우에는 그 금액을 보관금대장에 기록하고 수용자의 물품을 보관하는 경우에는 그 품목ㆍ수량 및 규격을 보관품대장에 기록해야 한다. <개정 2020.8.5>', 248);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1915, '제36조(귀중품의 보관) 소장은 보관품이 금ㆍ은ㆍ보석ㆍ유가증권ㆍ인장, 그 밖에 특별히 보관할 필요가 있는 귀중품인 경우에는 잠금장치가 되어 있는 견고한 용기에 넣어 보관해야 한다. <개정 2020.8.5>', 248);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1916, '제37조(보관품 매각대금의 보관) 소장은 수용자의 신청에 따라 보관품을 팔 경우에는 그 비용을 제외한 나머지 대금을 보관할 수 있다. <개정 2020.8.5>', 248);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1917, '제38조(보관금의 사용 등)', 248);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1918, '제39조(지닐 수 없는 물품의 처리) 법 제26조제2항 및 제3항에 따라 지닐 수 있는 범위를 벗어난 수용자의 물품을 처분하거나 폐기하는 경우에는 제34조제3항 및 제4항을 준용한다. <개정 2020.8.5>', 248);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1919, '제40조(물품의 폐기) 수용자의 물품을 폐기하는 경우에는 그 품목ㆍ수량ㆍ이유 및 일시를 관계 장부에 기록하여야 한다.', 248);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1920, '제41조(금품전달 신청자의 확인) 소장은 수용자가 아닌 사람이 법 제27조제1항에 따라 수용자에게 금품을 건네줄 것을 신청하는 경우에는 그의 성명ㆍ주소 및 수용자와의 관계를 확인해야 한다. <개정 2020.8.5>', 248);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1921, '제42조(전달 허가금품의 사용 등)', 248);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1922, '제43조(전달 허가물품의 검사) 소장은 법 제27조제1항에 따라 건네줄 것을 허가한 물품은 검사할 필요가 없다고 인정되는 경우가 아니면 교도관으로 하여금 검사하게 해야 한다. 이 경우 그 물품이 의약품인 경우에는 의무관으로 하여금 검사하게 해야 한다. <개정 2020.8.5>', 248);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1923, '제44조(보관의 예외) 음식물은 보관의 대상이 되지 않는다. <개정 2020.8.5>', 248);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1924, '제45조(유류금품의 처리)', 248);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1925, '제46조(보건ㆍ위생관리계획의 수립 등) 소장은 수용자의 건강, 계절 및 시설여건 등을 고려하여 보건ㆍ위생관리계획을 정기적으로 수립하여 시행하여야 한다.', 249);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1926, '제47조(시설의 청소ㆍ소독)', 249);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1927, '제48조(청결의무) 수용자는 교도관이 법 제32조제1항에 따라 자신이 사용하는 거실, 작업장, 그 밖의 수용시설의 청결을 유지하기 위하여 필요한 지시를 한 경우에는 이에 따라야 한다.', 249);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1928, '제49조(실외운동) 소장은 수용자가 매일(공휴일 및 법무부장관이 정하는 날은 제외한다) 「국가공무원 복무규정」 제9조에 따른 근무시간 내에서 1시간 이내의 실외운동을 할 수 있도록 하여야 한다. 다만, 다음 각 호의 어느 하나에 해당하면 실외운동을 실시하지 아니할 수 있다.', 249);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1929, '제50조(목욕횟수) 소장은 작업의 특성, 계절, 그 밖의 사정을 고려하여 수용자의 목욕횟수를 정하되 부득이한 사정이 없으면 매주 1회 이상이 되도록 한다.', 249);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1930, '제51조(건강검진횟수)', 249);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1931, '제52조(감염병의 정의) 법 제18조제1항, 법 제53조제1항제3호 및 법 제128조제2항에서 "감염병"이란 「감염병의 예방 및 관리에 관한 법률」에 따른 감염병을 말한다. <개정 2010.12.29>', 249);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1932, '제53조(감염병에 관한 조치)', 249);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1933, '제54조(의료거실 수용 등) 소장은 수용자가 부상을 당하거나 질병에 걸린 경우에는 그 수용자를 의료거실에 수용하거나, 다른 수용자에게 그 수용자를 간병하게 할 수 있다.', 249);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1934, '제54조의2(간호사의 의료행위) 법 제36조제2항에서 "대통령령으로 정하는 경미한 의료행위"란 다음 각 호의 의료행위를 말한다.', 249);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1935, '제55조(외부의사의 치료) 소장은 특히 필요하다고 인정하면 외부 의료시설에서 근무하는 의사(이하 "외부의사"라 한다)에게 수용자를 치료하게 할 수 있다.', 249);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1936, '제56조(위독 사실의 알림) 소장은 수용자가 위독한 경우에는 그 사실을 가족에게 지체 없이 알려야 한다.', 249);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1937, '제57조(외부 의료시설 입원 등 보고) 소장은 법 제37조제1항에 따라 수용자를 외부 의료시설에 입원시키거나 입원 중인 수용자를 교정시설로 데려온 경우에는 그 사실을 법무부장관에게 지체 없이 보고하여야 한다.', 249);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1938, '제58조(접견)', 250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1939, '제59조(접견의 예외)', 250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1940, '제59조의2(변호사 와의 접견)', 250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1941, '제60조(접견 시 외국어 사용)', 250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1942, '제61조(접견 시 유의사항 고지) 소장은 법 제41조에 따라 접견을 하게 하는 경우에는 수용자와 그 상대방에게 접견 시 유의사항을 방송이나 게시물 부착 등 적절한 방법으로 알려줘야 한다.', 250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1943, '제62조(접견내용의 청취ㆍ기록ㆍ녹음ㆍ녹화)', 250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1944, '제63조(접견중지 사유의 고지) 교도관이 법 제42조에 따라 수용자의 접견을 중지한 경우에는 그 사유를 즉시 알려주어야 한다.', 250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1945, '제64조(편지수수의 횟수) 수용자가 보내거나 받는 편지는 법령에 어긋나지 않으면 횟수를 제한하지 않는다. <개정 2020.8.5>', 250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1946, '제65조(편지 내용물의 확인)', 250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1947, '제66조(편지 내용의 검열)', 250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1948, '제67조(관계기관 송부문서) 소장은 법원ㆍ경찰관서, 그 밖의 관계기관에서 수용자에게 보내온 문서는 다른 법령에 특별한 규정이 없으면 열람한 후 본인에게 전달하여야 한다.', 250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1949, '제68조(편지 등의 대서) 소장은 수용자가 편지, 소송서류, 그 밖의 문서를 스스로 작성할 수 없어 대신 써 달라고 요청하는 경우에는 교도관이 대신 쓰게 할 수 있다. <개정 2020.8.5>', 250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1950, '제69조(편지 등 발송비용의 부담) 수용자의 편지ㆍ소송서류, 그 밖의 문서를 보내는 경우에 드는 비용은 수용자가 부담한다. 다만, 소장은 수용자가 그 비용을 부담할 수 없는 경우에는 예산의 범위에서 해당 비용을 부담할 수 있다. <개정 2014.6.25, 2020.8.5>', 250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1951, '제70조(전화통화) 수용자의 전화통화에 관하여는 제60조제1항 및 제63조를 준용한다.', 250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1952, '제71조(참고사항의 기록) 교도관은 수용자의 접견, 편지수수, 전화통화 등의 과정에서 수용자의 처우에 특히 참고할 사항을 알게 된 경우에는 그 요지를 수용기록부에 기록해야 한다. <개정 2020.8.5>', 250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1953, '제72조(비치도서의 이용)', 251);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1954, '제73조(라디오 청취 등의 방법) 법 제48조제1항에 따른 수용자의 라디오 청취와 텔레비전 시청은 교정시설에 설치된 방송설비를 통하여 할 수 있다.', 251);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1955, '제74조(집필용구의 구입비용) 집필용구의 구입비용은 수용자가 부담한다. 다만, 소장은 수용자가 그 비용을 부담할 수 없는 경우에는 필요한 집필용구를 지급할 수 있다.', 251);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1956, '제75조(집필의 시간대ㆍ시간 및 장소)', 251);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1957, '제76조(문서ㆍ도화의 외부 발송 등)', 251);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1958, '제77조(여성수용자의 목욕)', 252);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1959, '제78조(출산의 범위) 법 제52조제1항에서 "출산(유산ㆍ사산을 포함한다)한 경우"란 출산(유산ㆍ사산한 경우를 포함한다) 후 60일이 지나지 아니한 경우를 말한다. <개정 2019.10.22>', 252);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1960, '제79조(유아의 양육) 소장은 법 제53조제1항에 따라 유아의 양육을 허가한 경우에는 교정시설에 육아거실을 지정ㆍ운영하여야 한다.', 252);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1961, '제80조(유아의 인도)', 252);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1962, '제81조(노인수용자 등의 정의)', 252);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1963, '제82조(수형자로서의 처우 개시)', 254);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1964, '제83조(경비등급별 설비 및 계호) 법 제57조제2항 각 호의 수용설비 및 계호의 정도는 다음 각 호의 규정에 어긋나지 않는 범위에서 법무부장관이 정한다.', 254);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1965, '제84조(수형자의 처우등급 부여 등)', 254);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1966, '제85조(수형자 취업알선 등 협의기구)', 254);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1967, '제86조(분류전담시설) 법무부장관은 법 제61조의 분류심사를 전담하는 교정시설을 지정ㆍ운영하는 경우에는 지방교정청별로 1개소 이상이 되도록 하여야 한다.', 255);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1968, '제87조(교육)', 256);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1969, '제88조(정서교육) 소장은 수형자의 정서 함양을 위하여 필요하다고 인정하면 연극ㆍ영화관람, 체육행사, 그 밖의 문화예술활동을 하게 할 수 있다.', 256);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1970, '제89조(작업의 종류) 소장은 법무부장관의 승인을 받아 수형자에게 부과하는 작업의 종류를 정한다.', 257);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1971, '제90조(소년수형자의 작업 등) 소장은 19세 미만의 수형자에게 작업을 부과하는 경우에는 정신적ㆍ신체적 성숙 정도, 교육적 효과 등을 고려하여야 한다.', 257);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1972, '제91조(작업의 고지 등)', 257);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1973, '제92조(작업실적의 확인) 소장은 교도관에게 매일 수형자의 작업실적을 확인하게 하여야 한다.', 257);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1974, '제93조(신청 작업의 취소) 소장은 법 제67조에 따라 작업이 부과된 수형자가 작업의 취소를 요청하는 경우에는 그 수형자의 의사(意思), 건강 및 교도관의 의견 등을 고려하여 작업을 취소할 수 있다.', 257);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1975, '제94조(직업능력개발훈련 설비 등의 구비) 소장은 법 제69조에 따른 직업능력개발훈련을 하는 경우에는 그에 필요한 설비 및 실습 자재를 갖추어야 한다.', 257);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1976, '제95조(집중근로) 법 제70조제1항에서 "집중적인 근로가 필요한 작업"이란 수형자의 신청에 따라 1일 작업시간 중 접견ㆍ전화통화ㆍ교육 및 공동행사 참가 등을 하지 아니하고 휴게시간을 제외한 작업시간 내내 하는 작업을 말한다.', 257);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1977, '제96조(휴업일) 법 제71조에서 "그 밖의 휴일"이란 「각종 기념일 등에 관한 규정」에 따른 교정의 날 및 소장이 특히 지정하는 날을 말한다. <개정 2017.9.19>', 257);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1978, '제97조(귀휴자에 대한 조치)', 258);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1979, '제98조(미결수용시설의 설비 및 계호의 정도) 미결수용자를 수용하는 시설의 설비 및 계호의 정도는 법 제57조제2항제3호의 일반경비시설에 준한다.', 259);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1980, '제99조(법률구조 지원) 소장은 미결수용자가 빈곤하거나 무지하여 수사 및 재판 과정에서 권리를 충분히 행사하지 못한다고 인정하는 경우에는 법률구조에 필요한 지원을 할 수 있다.', 259);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1981, '제100조(공범 분리) 소장은 이송이나 출정, 그 밖의 사유로 미결수용자를 교정시설 밖으로 호송하는 경우에는 해당 사건에 관련된 사람과 호송 차량의 좌석을 분리하는 등의 방법으로 서로 접촉하지 못하게 하여야 한다.', 259);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1982, '제101조(접견 횟수) 미결수용자의 접견 횟수는 매일 1회로 하되, 변호인과의 접견은 그 횟수에 포함시키지 않는다.', 259);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1983, '제102조(접견의 예외) 소장은 미결수용자의 처우를 위하여 특히 필요하다고 인정하면 제58조제1항에도 불구하고 접견 시간대 외에도 접견하게 할 수 있고, 변호인이 아닌 사람과 접견하는 경우에도 제58조제2항 및 제101조에도 불구하고 접견시간을 연장하거나 접견 횟수를 늘릴 수 있다. <개정 2019.10.22>', 259);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1984, '제103조(교육ㆍ교화와 작업)', 259);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1985, '제104조(도주 등 통보) 소장은 미결수용자가 도주하거나 도주한 미결수용자를 체포한 경우에는 그 사실을 검사에게 통보하고, 기소된 상태인 경우에는 법원에도 지체 없이 통보하여야 한다.', 259);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1986, '제105조(사망 등 통보) 소장은 미결수용자가 위독하거나 사망한 경우에는 그 사실을 검사에게 통보하고, 기소된 상태인 경우에는 법원에도 지체 없이 통보하여야 한다.', 259);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1987, '제106조(외부의사의 진찰 등) 미결수용자가 「형사소송법」 제34조, 제89조 및 제209조에 따라 외부의사의 진료를 받는 경우에는 교도관이 참여하고 그 경과를 수용기록부에 기록하여야 한다.', 259);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1988, '제107조(유치장 수용기간) 경찰관서에 설치된 유치장에는 수형자를 30일 이상 수용할 수 없다.', 259);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1989, '제108조(사형확정자 수용시설의 설비 및 계호의 정도) 사형확정자를 수용하는 시설의 설비 및 계호의 정도는 법 제57조제2항제3호의 일반경비시설 또는 같은 항 제4호의 중경비시설에 준한다. <개정 2017.9.19>', 260);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1990, '제109조(접견 횟수) 사형확정자의 접견 횟수는 매월 4회로 한다.', 260);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1991, '제110조(접견의 예외) 소장은 제58조제1항ㆍ제2항 및 제109조에도 불구하고 사형확정자의 교화나 심리적 안정을 도모하기 위하여 특히 필요하다고 인정하면 접견 시간대 외에도 접견을 하게 할 수 있고 접견시간을 연장하거나 접견 횟수를 늘릴 수 있다. <개정 2019.10.22>', 260);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1992, '제111조(사형집행 후의 검시) 소장은 사형을 집행하였을 경우에는 시신을 검사한 후 5분이 지나지 아니하면 교수형에 사용한 줄을 풀지 못한다. <개정 2014.6.25>', 260);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1993, '제112조(거실 등에 대한 검사) 소장은 교도관에게 수용자의 거실, 작업장, 그 밖에 수용자가 생활하는 장소(이하 이 조에서 "거실등"이라 한다)를 정기적으로 검사하게 하여야 한다. 다만, 법 제92조의 금지물품을 숨기고 있다고 의심되는 수용자와 법 제104조제1항의 마약류사범ㆍ조직폭력사범 등 법무부령으로 정하는 수용자의 거실등은 수시로 검사하게 할 수 있다.', 261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1994, '제113조(신체 등에 대한 검사) 소장은 교도관에게 작업장이나 실외에서 수용자거실로 돌아오는 수용자의 신체ㆍ의류 및 휴대품을 검사하게 하여야 한다. 다만, 교정성적 등을 고려하여 그 검사가 필요하지 아니하다고 인정되는 경우에는 예외로 할 수 있다.', 261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1995, '제114조(검사장비의 이용) 교도관은 법 제93조에 따른 검사를 위하여 탐지견, 금속탐지기, 그 밖의 장비를 이용할 수 있다.', 261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1996, '제115조(외부인의 출입)', 261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1997, '제116조(외부와의 차단)', 261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1998, '제117조(거실 개문 등 제한) 교도관은 수사ㆍ재판ㆍ운동ㆍ접견ㆍ진료 등 수용자의 처우 또는 자살방지, 화재진압 등 교정시설의 안전과 질서유지를 위하여 필요한 경우가 아니면 수용자거실의 문을 열거나 수용자를 거실 밖으로 나오게 해서는 아니 된다.', 261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (1999, '제118조(장애물 방치 금지) 교정시설의 구내에는 시야를 가리거나 그 밖에 계호상 장애가 되는 물건을 두어서는 아니 된다.', 261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2000, '제119조(보호실 등 수용중지)', 261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2001, '제120조(보호장비의 사용)', 261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2002, '제121조(보호장비 사용중지 등)', 261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2003, '제122조(보호장비 사용사유의 고지) 보호장비를 사용하는 경우에는 수용자에게 그 사유를 알려주어야 한다.', 261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2004, '제123조(보호장비 착용 수용자의 거실 지정) 보호장비를 착용 중인 수용자는 특별한 사정이 없으면 계호상 독거수용한다.', 261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2005, '제124조(보호장비 사용의 감독)', 261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2006, '제125조(강제력의 행사) 교도관은 소장의 명령 없이 법 제100조에 따른 강제력을 행사해서는 아니 된다. 다만, 그 명령을 받을 시간적 여유가 없는 경우에는 강제력을 행사한 후 소장에게 즉시 보고하여야 한다. <개정 2014.6.25>', 261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2007, '제126조(무기사용 보고) 교도관은 법 제101조에 따라 무기를 사용한 경우에는 소장에게 즉시 보고하고, 보고를 받은 소장은 그 사실을 법무부장관에게 즉시 보고하여야 한다. <개정 2014.6.25>', 261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2008, '제127조(재난 시의 조치)', 261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2009, '제128조(도주 등에 따른 조치)', 261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2010, '제128조의2(포상금 지급)', 261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2011, '제128조의3(포상금의 지급 신청)', 261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2012, '제128조의4(포상금의 환수) 법무부장관은 제128조의2제1항에 따라 포상금을 지급한 후 다음 각 호의 어느 하나에 해당하는 사실이 발견된 경우에는 해당 포상금을 환수할 수 있다.', 261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2013, '제129조(징벌위원회의 소집) 법 제111조에 따른 징벌위원회(이하 이 장에서 "위원회"라 한다)의 위원장은 소장의 징벌요구에 따라 위원회를 소집한다.', 262);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2014, '제130조(위원장의 직무대행) 위원회의 위원장이 불가피한 사정으로 그 직무를 수행하기 어려운 경우에는 위원장이 미리 지정한 위원이 그 직무를 대행한다.', 262);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2015, '제131조(위원의 제척) 위원회의 위원이 해당 징벌대상 행위의 조사를 담당한 경우에는 해당 위원회에 참석할 수 없다.', 262);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2016, '제132조(징벌의결 통고) 위원회가 징벌을 의결한 경우에는 이를 소장에게 즉시 통고하여야 한다.', 262);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2017, '제133조(징벌의 집행)', 262);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2018, '제134조(징벌집행의 계속) 법 제108조제4호부터 제14호까지의 징벌 집행 중인 수용자가 다른 교정시설로 이송되거나 법원 또는 검찰청 등에 출석하는 경우에는 징벌집행이 계속되는 것으로 본다.', 262);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2019, '제135조(징벌기간의 계산) 소장은 법 제113조제1항에 따라 징벌집행을 일시 정지한 경우 그 정지사유가 해소되었을 때에는 지체 없이 징벌집행을 재개하여야 한다. 이 경우 집행을 정지한 다음날부터 집행을 재개한 전날까지의 일수는 징벌기간으로 계산하지 아니한다.', 262);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2020, '제136조(이송된 사람의 징벌) 수용자가 이송 중에 징벌대상 행위를 하거나 다른 교정시설에서 징벌대상 행위를 한 사실이 이송된 후에 발각된 경우에는 그 수용자를 인수한 소장이 징벌을 부과한다.', 262);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2021, '제137조(징벌사항의 기록) 소장은 수용자의 징벌에 관한 사항을 수용기록부 및 징벌집행부에 기록하여야 한다.', 262);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2022, '제138조(소장 면담)', 263);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2023, '제139조(순회점검공무원에 대한 청원)', 263);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2024, '제139조의2(정보공개의 예상비용 등)', 263);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2025, '제140조(가석방자가 지켜야 할 사항의 알림 등) 소장은 법 제122조제2항의 가석방 허가에 따라 수형자를 가석방하는 경우에는 가석방자 교육을 하고, 지켜야 할 사항을 알려준 후 증서를 발급해야 한다. <개정 2020.8.5>', 265);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2026, '제141조(석방예정자 상담 등) 소장은 수형자의 건전한 사회복귀를 위하여 필요하다고 인정하면 석방 전 3일 이내의 범위에서 석방예정자를 별도의 거실에 수용하여 장래에 관한 상담과 지도를 할 수 있다.', 266);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2027, '제142조(형기종료 석방예정자의 사전조사) 소장은 형기종료로 석방될 수형자에 대하여는 석방 10일 전까지 석방 후의 보호에 관한 사항을 조사하여야 한다.', 266);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2028, '제143조(석방예정자의 수용이력 등 통보)', 266);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2029, '제144조(석방예정자의 보호조치) 소장은 수형자를 석방하는 경우 특히 필요하다고 인정하면 한국법무보호복지공단에 그에 대한 보호를 요청할 수 있다. <개정 2009.3.18>', 266);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2030, '제145조(귀가여비 등의 회수) 소장은 법 제126조에 따라 피석방자에게 귀가 여비 또는 의류를 빌려준 경우에는 특별한 사유가 없으면 이를 회수한다.', 266);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2031, '제145조의2(증명서의 발급) 소장은 다음 각 호에 해당하는 사람의 신청에 따라 교정시설에 수용된 사실 또는 수용되었다가 석방된 사실에 관한 증명서를 발급할 수 있다. <개정 2020.8.5>', 266);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2032, '제145조의3(고유식별정보의 처리) 소장은 제145조의2에 따른 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법 시행령」 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 266);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2033, '제146조(사망 알림) 소장은 법 제127조에 따라 수용자의 사망 사실을 알리는 경우에는 사망 일시ㆍ장소 및 사유도 같이 알려야 한다.', 267);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2034, '제147조(검시) 소장은 수용자가 사망한 경우에는 그 시신을 검사하여야 한다. <개정 2014.6.25>', 267);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2035, '제148조(사망 등 기록)', 267);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2036, '제149조 삭제 <2015.12.10>', 267);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2037, '제150조(임시 매장지의 표지 등)', 267);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2038, '제151조(교정위원)', 268);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2039, '제152조(외부인사가 지켜야 할 사항) 교정위원, 교정자문위원, 그 밖에 교정시설에서 활동하는 외부인사는 활동 중에 알게 된 교정시설의 안전과 질서 및 수용자의 신상에 관한 사항을 외부에 누설하거나 공개해서는 안 된다. <개정 2020.8.5>', 268);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2040, '제153조(기부금품의 접수 등)', 268);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2041, '제1조(목적) 이 법은 건전한 국민경제윤리에 반하는 특정경제범죄에 대한 가중처벌과 그 범죄행위자에 대한 취업제한 등을 규정함으로써 경제질서를 확립하고 나아가 국민경제 발전에 이바지함을 목적으로 한다.', 269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2042, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다. <개정 2016.3.29, 2016.5.29>', 269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2043, '제3조(특정재산범죄의 가중처벌)', 269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2044, '제4조(재산국외도피의 죄)', 269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2045, '제5조(수재 등의 죄)', 269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2046, '제6조(증재 등의 죄)', 269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2047, '제7조(알선수재의 죄) 금융회사등의 임직원의 직무에 속하는 사항의 알선에 관하여 금품이나 그 밖의 이익을 수수, 요구 또는 약속한 사람 또는 제3자에게 이를 공여하게 하거나 공여하게 할 것을 요구 또는 약속한 사람은 5년 이하의 징역 또는 5천만원 이하의 벌금에 처한다.', 269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2048, '제8조(사금융 알선 등의 죄) 금융회사등의 임직원이 그 지위를 이용하여 자기의 이익 또는 소속 금융회사등 외의 제3자의 이익을 위하여 자기의 계산으로 또는 소속 금융회사등 외의 제3자의 계산으로 금전의 대부, 채무의 보증 또는 인수를 하거나 이를 알선하였을 때에는 7년 이하의 징역 또는 7천만원 이하의 벌금에 처한다.', 269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2049, '제9조(저축 관련 부당행위의 죄)', 269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2050, '제10조(몰수ㆍ추징)', 269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2051, '제11조(무인가 단기금융업의 가중처벌)', 269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2052, '제12조(보고의무 등)', 269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2053, '제13조 삭제 <2009.5.8>', 269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2054, '제14조(일정 기간의 취업제한 및 인가ㆍ허가 금지 등)', 269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2055, '제1조(목적) 이 영은 「특정경제범죄 가중처벌 등에 관한 법률」에서 위임된 사항과 그 시행에 관하여 필요한 사항을 정함을 목적으로 한다. <개정 2009.7.7>', 270);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2056, '제2조(대출등의 범위) 「특정경제범죄 가중처벌 등에 관한 법률」(이하 "법"이라 한다) 제2조제3호에서 "대통령령으로 정하는 것"이란 다음 각 호의 어느 하나에 해당하는 것을 말한다. <개정 2009.7.7, 2019.5.7>', 270);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2057, '제3조(감독기관의 감독업무에 종사하는 사람의 범위) 법 제12조제2항에 따른 감독기관의 감독업무에 종사하는 사람은 다음 각 호의 어느 하나에 해당하는 기관의 임ㆍ직원으로서 소관 금융회사등에 대한 감사 또는 검사의 직무(일시적인 감사 또는 검사의 직무의 경우를 포함한다)에 종사하는 사람 및 그 직무를 관장하는 상급자와 해당 감독기관의 장으로 한다. <개정 1998ㆍ4ㆍ1, 2019.5.7>', 270);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2058, '제4조 삭제 <2009.7.7>', 270);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2059, '제5조 삭제 <2009.7.7>', 270);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2060, '제6조 삭제 <2009.7.7>', 270);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2061, '제7조 삭제 <2009.7.7>', 270);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2062, '제8조 삭제 <2009.7.7>', 270);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2063, '제9조(수사기관의 통보등)', 270);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2064, '제10조(취업제한대상인 기관 및 기업체의 범위)', 270);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2065, '제11조(허가등이 금지되는 관허업의 범위) 법 제14조제2항에서 "대통령령으로 정하는 관허업"이란 특정한 사업ㆍ영업 또는 행위를 업으로 하기 위하여 행정기관으로부터 허가ㆍ인가ㆍ면허ㆍ등록ㆍ지정ㆍ승인 및 특허(이하 "허가등"이라 한다)를 받아야 할 대상으로서 그 처분청이 중앙행정기관의 장, 특별시장, 광역시장, 특별자치시장, 도지사 또는 특별자치도지사인 경우(법령에 따라 그 허가등의 권한이 하부기관 또는 다른 기관에 위임 또는 위탁된 경우를 포함한다)의 해당 사업ㆍ영업 또는 행위를 말한다. <개정 2019.5.7>', 270);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2066, '제12조(취업제한사실등의 통지) 법무부장관은 법 제3조ㆍ법 제4조제2항(미수범을 포함한다)ㆍ법 제5조제4항 또는 법 제8조의 죄를 범한 사람에 대한 재판결과를 항상 파악하여 그에 대한 유죄판결이 확정된 때에는 지체 없이 법 제14조제1항 및 제2항에 따른 취업제한 및 허가등 금지사실과 그 대상의 범위를 그 판결이 확정된 사람에게 통지하여야 한다. <개정 2009.7.7, 2019.5.7>', 270);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2067, '제13조(취업승인신청)', 270);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2068, '제14조(관허업의 허가등 승인신청)', 270);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2069, '제15조(민감정보 및 고유식별정보 등의 처리)', 270);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2070, '제1조(국내재산의 범위) 「국내재산 도피 방지법」(이하 "법"이라 한다) 제1조에 따른 재산은 다음 각 호의 어느 하나에 해당하는 것으로 한다.', 271);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2071, '제2조(재산 이동의 허가신청) 법 제3조제1호에 따른 정부의 허가를 받으려는 자는 다음 각 호의 사항을 적은 신청서를 기획재정부장관에게 제출하여야 한다. 다만, 「관세법」이나 그 밖의 법령에 따라 소관 관청의 허가를 받은 경우에는 예외로 한다.', 271);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2072, '제3조(허가) 기획재정부장관은 제2조에 따른 신청서를 받았을 때에는 이를 심사하여 법 제1조에 따른 재산 도피의 목적이 아닌 경우에만 허가한다.', 271);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2073, '제4조(재산 이동의 절차) 제3조에 따라 허가를 받은 자는 그 허가서를 세관이나 그 밖의 관계기관에 제시하고 재산 이동에 필요한 절차를 밟아야 한다.', 271);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2074, '제5조(검사 등) 기획재정부장관은 필요하다고 인정할 때에는 소속 공무원을 파견하여 제2조에 따라 신청한 재산을 검사하게 하거나 그 재산에 관한 보고를 하게 할 수 있다.', 271);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2075, '제1조 (목적) 이 규칙은 「벌금 미납자의 사회봉사 집행에 관한 특례법」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 272);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2076, '제2조 (사회봉사 신청서) 「벌금 미납자의 사회봉사 집행에 관한 특례법」(이하 "법"이라 한다) 제4조제1항에 따른 사회봉사 신청은 별지 제1호 서식에 따른다.', 272);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2077, '제3조 (사회봉사 허가청구서) 「벌금 미납자의 사회봉사 집행에 관한 특례법 시행령」(이하 "영"이라 한다) 제4조에 따른 사회봉사 허가청구서는 별지 제2호 서식에 따른다.', 272);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2078, '제4조 (신청인의 자료제출 동의서) 영 제5조에 따른 신청인의 자료제출 동의서는 별지 제3호 서식에 따른다.', 272);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2079, '제5조 (자료제출 요구서) 법 제5조제2항에 따른 공공기관, 민간단체 등에 대한 벌금 납입 능력 확인에 필요한 자료의 제출 요구는 별지 제4호 서식에 따른다. 다만, 금융거래정보, 신용정보 등 그 제출 요구에 관하여 다른 법령에 따른 서식이 있는 경우에는 그에 따를 수 있다.', 272);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2080, '제6조 (사회봉사 신청 기각 통보서) 법 제5조제5항에 따른 사회봉사 신청에 대한 기각 사실의 통보는 별지 제5호 서식에 따른다.', 272);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2081, '제7조 (사회봉사 신고서) 법 제8조에 따른 보호관찰소의 장에 대한 신고는 별지 제6호 서식에 따른다.', 272);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2082, '제8조 (사회봉사 집행개시 통지서) 보호관찰관은 사회봉사 집행 전에 미리 사회봉사 집행 일시와 장소 등을 정하여 사회봉사 대상자에게 별지 제7호 서식의 사회봉사 집행개시 통지서를 발급하여야 한다.', 272);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2083, '제9조 (집행기간 연장허가 신청서) 영 제10조제1항에 따른 집행기간 연장허가 신청은 별지 제8호 서식에 따른다.', 272);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2084, '제10조 (사회봉사 집행확인서) 법 제12조제2항에 따른 사회봉사 집행확인서는 별지 제9호 서식에 따른다.', 272);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2085, '제11조 (벌금 납입 사실 등의 통보)', 272);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2086, '제12조 (사회봉사 허가의 취소 신청 등) 법 제14조제1항에 따른 사회봉사 허가의 취소 신청 및 취소 청구는 별지 제12호 서식에 따른다.', 272);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2087, '제13조 (사회봉사 허가의 취소 신청에 대한 결과 통보) 법 제14조제6항에 따른 보호관찰소의 장에 대한 통보는 검사가 법원으로부터 받은 결정 고지 서면의 위쪽에 그 결정 내용을 확인하였다는 사실을 적고 서명 또는 날인한 다음, 그 사본을 보호관찰소의 장에게 송부하는 방법으로 한다.', 272);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2088, '제1조(목적) 이 법은 수사ㆍ재판ㆍ집행 등 형사사법 절차에서 전자장치를 효율적으로 활용하여 불구속재판을 확대하고, 범죄인의 사회복귀를 촉진하며, 범죄로부터 국민을 보호함을 목적으로 한다.', 273);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2089, '제2조(정의) 이 법에서 사용하는 용어의 정의는 다음과 같다. <개정 2007.8.3, 2009.5.8, 2009.6.9, 2010.4.15, 2012.12.18, 2013.4.5, 2017.10.31, 2023.7.11>', 273);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2090, '제3조(국가의 책무) 국가는 이 법의 집행과정에서 국민의 인권이 부당하게 침해되지 아니하도록 주의하여야 한다.', 273);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2091, '제3조의2(연구개발사업의 추진)', 273);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2092, '제4조(적용 범위) 만 19세 미만의 자에 대하여 부착명령을 선고한 때에는 19세에 이르기까지 이 법에 따른 전자장치를 부착할 수 없다. <개정 2009.5.8>', 273);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2093, '제5조(전자장치 부착명령의 청구)', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2094, '제6조(조사)', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2095, '제7조(부착명령 청구사건의 관할)', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2096, '제8조(부착명령 청구서의 기재사항 등)', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2097, '제9조(부착명령의 판결 등)', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2098, '제9조의2(준수사항)', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2099, '제10조(부착명령 판결 등에 따른 조치)', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2100, '제11조(국선변호인 등) 부착명령 청구사건에 관하여는 「형사소송법」 제282조 및 제283조를 준용한다. <개정 2010.4.15>', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2101, '제12조(집행지휘)', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2102, '제13조(부착명령의 집행)', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2103, '제14조(피부착자의 의무)', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2104, '제14조의2(부착기간의 연장 등)', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2105, '제14조의3(피부착명령자에 대한 준수사항의 부과 등) 피부착명령자의 재범의 위험성에 관하여 행형(行刑) 성적 등 자료에 의해 판결 선고 당시에 예상하지 못한 새로운 사정이 소명되는 등 특별한 사정이 있는 경우 법원은 보호관찰소의 장의 신청에 따른 검사의 청구로 제9조의2제1항의 준수사항을 부과, 추가, 변경 또는 삭제하는 결정을 할 수 있다.', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2106, '제15조(보호관찰관의 임무)', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2107, '제16조(수신자료의 보존ㆍ사용ㆍ폐기 등)', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2108, '제16조의2(피부착자의 신상정보 제공 등)', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2109, '제16조의3(위치추적 관제센터의 설치ㆍ운영 등)', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2110, '제17조(부착명령의 임시해제 신청 등)', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2111, '제18조(부착명령 임시해제의 심사 및 결정)', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2112, '제19조(임시해제의 취소 등)', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2113, '제20조(부착명령 집행의 종료) 제9조에 따라 선고된 부착명령은 다음 각 호의 어느 하나에 해당하는 때에 그 집행이 종료된다. <개정 2020.2.4>', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2114, '제21조(부착명령의 시효)', 274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2115, '제21조의2(보호관찰명령의 청구) 검사는 다음 각 호의 어느 하나에 해당하는 사람에 대하여 형의 집행이 종료된 때부터 「보호관찰 등에 관한 법률」에 따른 보호관찰을 받도록 하는 명령(이하 "보호관찰명령"이라 한다)을 법원에 청구할 수 있다. <개정 2023.7.11>', 275);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2116, '제21조의3(보호관찰명령의 판결)', 275);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2117, '제21조의4(준수사항)', 275);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2118, '제21조의5(보호관찰명령의 집행) 보호관찰명령은 특정범죄사건에 대한  형의 집행이 종료되거나 면제ㆍ가석방되는 날 또는 치료감호 집행이 종료ㆍ가종료되는 날부터 집행한다. 다만, 보호관찰명령의 원인이 된 특정범죄사건이 아닌 다른 범죄사건으로 형이나 치료감호의 집행이 계속될 경우에는 보호관찰명령의 원인이 된 특정범죄사건이 아닌 다른 범죄사건에 대한 형의 집행이 종료되거나 면제ㆍ가석방되는 날 또는 치료감호의 집행이 종료ㆍ가종료되는 날부터 집행한다.', 275);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2119, '제21조의6(보호관찰대상자의 의무)', 275);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2120, '제21조의7(보호관찰 기간의 연장 등)', 275);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2121, '제21조의8(준용규정) 보호관찰대상자에 대해서는 제5조제6항ㆍ제8항, 제6조부터 제8조까지, 제9조제2항부터 제9항까지, 제9조의2, 제10조부터 제12조까지, 제13조제5항부터 제9항까지, 제15조 및 제17조부터 제21조까지의 규정을 준용하되, "부착명령"은 "보호관찰명령"으로, "부착기간"은 "보호관찰 기간"으로, "피부착명령청구자"는 "피보호관찰명령청구자"로, "피부착자"는 "보호관찰대상자"로, "전자장치 부착"은 "보호관찰"로 본다. <개정 2017.10.31, 2017.12.12, 2023.7.11>', 275);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2122, '제22조(가석방과 전자장치 부착)', 276);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2123, '제23조(가종료 등과 전자장치 부착)', 276);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2124, '제24조(전자장치의 부착)', 276);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2125, '제25조(부착집행의 종료) 제22조 및 제23조에 따른 전자장치 부착은 다음 각 호의 어느 하나에 해당하는 때에 그 집행이 종료된다. <개정 2010.4.15>', 276);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2126, '제26조(수신자료의 활용) 보호관찰관은 수신자료를 준수사항 이행여부 확인 등 「보호관찰 등에 관한 법률」에 따른 보호관찰대상자의 지도ㆍ감독 및 원호에 활용할 수 있다.', 276);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2127, '제27조(준용) 이 장에 따른 전자장치 부착에 관하여는 제13조제4항ㆍ제6항제1호ㆍ제8항제1호ㆍ제9항, 제14조, 제15조, 제16조, 제16조의2, 제16조의3 및 제17조부터 제19조까지의 규정을 준용한다. <개정 2010.4.15, 2017.10.31, 2017.12.12, 2022.1.4>', 276);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2128, '제28조(형의 집행유예와 부착명령)', 277);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2129, '제29조(부착명령의 집행)', 277);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2130, '제30조(부착명령 집행의 종료) 제28조의 부착명령은 다음 각 호의 어느 하나에 해당하는 때에 그 집행이 종료된다.', 277);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2131, '제31조(준용) 이 장에 따른 부착명령에 관하여는 제6조, 제9조제5항부터 제7항까지, 제10조제1항, 제12조, 제13조제4항ㆍ제6항제1호ㆍ제8항제1호ㆍ제9항, 제14조, 제15조제1항, 제16조, 제16조의2, 제16조의3, 제17조부터 제19조까지 및 제26조를 준용한다. <개정 2010.4.15, 2017.10.31, 2017.12.12, 2022.1.4>', 277);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2132, '제31조의2(보석과 전자장치 부착)', 278);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2133, '제31조의3(전자장치 부착의 집행)', 278);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2134, '제31조의4(보석조건 이행 상황 등 통지)', 278);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2135, '제31조의5(전자장치 부착의 종료) 제31조의2제1항에 따른 전자장치의 부착은 다음 각 호의 어느 하나에 해당하는 경우에 그 집행이 종료된다.', 278);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2136, '제31조의6(전자장치 부착의 집행)', 279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2137, '제31조의7(전자장치 부착의 종료) 제31조의6에 따른 전자장치 부착은 다음 각 호의 어느 하나에 해당하는 때에 그 집행이 종료된다.', 279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2138, '제31조의8(스토킹행위자 수신자료의 보존ㆍ사용ㆍ폐기 등)', 279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2139, '제32조(전자장치 부착기간의 계산)', 280);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2140, '제32조의2(부착명령 등 집행전담 보호관찰관의 지정) 보호관찰소의 장은 소속 보호관찰관 중에서 다음 각 호의 사항을 전담하는 보호관찰관을 지정하여야 한다. 다만, 보호관찰소의 장은 19세 미만의 사람에 대해서 성폭력범죄를 저지른 피부착자 중 재범의 위험성이 현저히 높은 사람에 대해서는 일정기간 그 피부착자 1명만을 전담하는 보호관찰관을 지정하여야 한다. <개정 2012.12.18, 2019.4.16>', 280);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2141, '제33조(전자장치 부착 임시해제의 의제) 보호관찰이 임시해제된 경우에는 전자장치 부착이 임시해제된 것으로 본다. <개정 2020.2.4>', 280);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2142, '제33조의2(범죄경력자료 등의 조회 요청)', 280);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2143, '제34조(군법 피적용자에 대한 특칙) 이 법을 적용함에 있어서 「군사법원법」 제2조제1항 각 호의 어느 하나에 해당하는 자에 대하여는 군사법원은 법원의, 군검사는 검사의, 군사법경찰관리는 사법경찰관리의, 군교도소장은 교도소장의 이 법에 따른 직무를 각각 행한다. <개정 2016.1.6>', 280);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2144, '제35조(다른 법률의 준용) 이 법을 적용함에 있어서 이 법에 규정이 있는 경우를 제외하고는 그 성질에 반하지 아니하는 범위 안에서 「형사소송법」 및 「보호관찰 등에 관한 법률」의 규정을 준용한다.', 280);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2145, '제36조(벌칙)', 281);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2146, '제37조(벌칙)', 281);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2147, '제38조(벌칙)', 281);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2148, '제39조(벌칙)', 281);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2149, '제1조(목적) 이 영은 「전자장치 부착 등에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다. <개정 2009.7.30, 2013.5.31, 2020.8.5>', 282);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2150, '제2조(위치추적 전자장치의 구성) 「전자장치 부착 등에 관한 법률」(이하 "법"이라 한다) 제2조제4호에 따른 위치추적 전자장치(이하 "전자장치"라 한다)는 다음 각 호로 구성한다. <개정 2009.7.30, 2013.5.31, 2018.2.13, 2020.8.5>', 282);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2151, '제3조 삭제 <2021.9.14>', 282);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2152, '제3조의2(출연금 등의 지급ㆍ사용 및 관리)', 282);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2153, '제4조(조사)', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2154, '제5조(부착명령 청구서의 기재사항 및 방식)', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2155, '제6조(집행지휘) 검사는 부착명령의 판결이 확정되면 지체 없이 부착명령을 선고받은 사람(이하 "피부착명령자"라 한다)의 주거지를 관할하는 보호관찰소의 장에게 법 제12조제2항의 부착명령 집행을 지휘한 서면을 보내야 한다.', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2156, '제7조(부착명령의 집행)', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2157, '제8조(부착명령의 집행정지)', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2158, '제9조(부착명령 집행정지자의 이송) 수용기관의 장은 법 제13조제6항에 따라 부착명령의 집행이 정지된 사람을 다른 수용기관으로 이송할 경우에는 그의 주거지를 관할하는 보호관찰소의 장과 해당 수용기관의 장에게 그 사실을 통보하여야 한다. <개정 2010.7.12, 2018.6.12>', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2159, '제10조(전자장치의 일시 분리)', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2160, '제11조(전자장치의 효용 유지 의무) 피부착자는 전자장치의 부착기간 중 법 제14조제1항에 따라 전자장치의 효용 유지를 위하여 다음 각 호의 사항을 준수하여야 한다.', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2161, '제12조(주거이전ㆍ국내여행 및 출국 허가 등)', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2162, '제12조의2(부착기간의 연장 등의 신청)', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2163, '제13조(상담치료 등의 집행)', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2164, '제14조(수신자료의 사용) 보호관찰소의 장 및 법 제16조의3에 따른 위치추적 관제센터(이하 "위치추적 관제센터"라 한다)의 장은 법 제16조제2항제1호, 제3호 및 제4호에 따라 수신자료가 사용된 경우에는 그 사실을 대장에 적고 이를 비치해야 한다. <개정 2010.7.12, 2018.6.12, 2021.9.14, 2024.1.9>', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2165, '제14조의2(수신자료 열람 또는 조회)', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2166, '제14조의3(긴급 수신자료 열람 또는 조회)', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2167, '제14조의4(열람 또는 조회한 수신자료의 보존ㆍ폐기 등)', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2168, '제14조의5(수신자료 사용사건의 결과 통지 등)', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2169, '제14조의6(수신자료 관련 비밀누설 금지 등) 수신자료를 열람 또는 조회한 사람은 그로 인하여 알게 된 타인의 비밀을 누설하거나 피부착자의 명예를 훼손하지 아니하도록 하여야 한다.', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2170, '제15조(수신자료의 폐기)', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2171, '제15조의2(피부착자의 신상정보 제공 등)', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2172, '제16조(부착명령의 임시해제 신청)', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2173, '제17조(부착명령 임시해제의 심사 및 결정)', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2174, '제18조(임시해제의 취소 등)', 283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2175, '제18조의2(보호관찰 기간의 연장 등)', 284);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2176, '제18조의3(준용규정) 보호관찰대상자의 조사, 집행지휘, 주거이전 허가, 상담치료, 임시해제 및 취소 등에 관하여는 제4조부터 제6조까지, 제12조제1항부터 제7항까지, 제13조, 제16조, 제17조제1항ㆍ제2항ㆍ제4항 및 제18조제1항ㆍ제2항을 준용한다. 이 경우 "부착명령"은 "보호관찰명령"으로, "부착기간"은 "보호관찰 기간"으로, "피부착명령청구자"는 "피보호관찰명령청구자"로, "피부착명령자"는 "피보호관찰명령자"로, "피부착자"는 "보호관찰대상자"로, "전자장치 부착"은 "보호관찰"로 본다. <개정 2020.8.5>', 284);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2177, '제19조(전자장치 부착 적합성조사)', 285);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2178, '제19조의2(결정의 고지 등)', 285);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2179, '제20조(치료감호시설의 장 등의 통보)', 285);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2180, '제21조(준용) 이 장에 따른 전자장치 부착에 관하여는 제7조부터 제12조까지, 제12조의2 및 제13조부터 제18조까지의 규정을 준용한다. <개정 2010.7.12>', 285);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2181, '제22조(집행유예와 부착명령의 집행) 법 제28조제1항에 따라 집행유예와 함께 전자장치 부착을 명하는 법원의 판결이 확정된 사람은 판결 확정 후 10일 이내에 보호관찰소에 출석하여 법 제29조제1항에 따른 부착명령의 집행에 따라야 한다.', 286);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2182, '제23조(준용) 이 장에 따른 부착명령에 관하여는 제4조, 제6조부터 제12조까지, 제12조의2 및 제13조부터 제18조까지의 규정을 준용한다. <개정 2010.7.12>', 286);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2183, '제23조의2(보석조건 전자장치 부착 결정 전 조사)', 287);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2184, '제23조의3(보석허가 결정문의 송부 등) 법원은 긴급한 필요가 있는 경우 법 제31조의3제1항에 따라 보호관찰소의 장에게 결정문의 등본을 송부하기 전에 팩스ㆍ전자우편 등의 방법으로 그 사본을 먼저 송부할 수 있다.', 287);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2185, '제23조의4(전자장치 부착 보석 피고인의 신고) 법 제31조의2제1항에 따라 보석조건으로 전자장치 부착명령을 받고 석방된 피고인(이하 "전자장치 보석피고인"이라 한다)은 법 제31조의3제2항에 따라 주거지를 관할하는 보호관찰소에 출석하여 신고하는 경우 법무부령으로 정하는 신고서를 제출해야 한다.', 287);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2186, '제23조의5(전자장치 부착 등)', 287);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2187, '제23조의6(보석조건 이행 상황 통지)', 287);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2188, '제23조의7(보석조건 위반 통지)', 287);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2189, '제23조의8(보석조건 변경 및 보석취소 통지) 법원은 「형사소송법」 제102조제1항 또는 제2항에 따라 보석조건을 변경하거나 취소한 경우 보호관찰소의 장에게 보석조건 변경이나 보석취소 결정문의 등본을 송부해야 한다. 이 경우 긴급한 경우에는 전화ㆍ팩스ㆍ전자우편 등의 방법으로 먼저 통지할 수 있다.', 287);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2190, '제23조의9(준용 규정) 이 장에 따른 전자장치 부착 등에 관하여는 제10조, 제14조의6 및 제15조를 준용한다. 이 경우 "피부착자"는 "전자장치 보석피고인"으로 본다.', 287);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2191, '제23조의10(잠정조치 결정문의 송부) 법원은 긴급한 필요가 있는 경우 법 제31조의6제1항에 따라 다음 각 호의 사람에게 결정문의 등본을 송부하기 전에 팩스ㆍ전자우편 등의 방법으로 그 사본을 먼저 송부할 수 있다.', 288);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2192, '제23조의11(전자장치 스토킹행위자의 신고)', 288);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2193, '제23조의12(전자장치의 부착 등)', 288);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2194, '제23조의13(전자장치 부착 사실의 통지 등)', 288);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2195, '제23조의14(피해자의 보호)', 288);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2196, '제23조의15(잠정조치의 연장ㆍ변경ㆍ취소 통지) 법원은 잠정조치의 연장ㆍ변경ㆍ취소 결정을 한 경우 법 제31조의6제7항에 따라 관할경찰관서의 장과 보호관찰소의 장에게 그 결정문의 등본을 지체 없이 송부해야 한다. 이 경우 긴급한 경우에는 전화ㆍ팩스ㆍ전자우편 등의 방법으로 먼저 통지할 수 있다.', 288);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2197, '제23조의16(불기소처분의 통지) 검사는 전자장치 스토킹행위자에 대해 불기소처분을 하여 「스토킹범죄의 처벌 등에 관한 법률」 제11조제5항에 따라 잠정조치 결정이 효력을 상실한 때에는 보호관찰소의 장에게 이를 지체 없이 통지해야 한다.', 288);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2198, '제23조의17(스토킹행위자 수신자료의 사용) 보호관찰소의 장 및 위치추적 관제센터의 장은 법 제31조의8제2항제1호, 제3호 및 제4호에 따라 스토킹행위자 수신자료가 사용된 경우에는 그 사실을 대장에 적고 이를 비치해야 한다.', 288);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2199, '제23조의18(스토킹행위자 수신자료의 폐기) 보호관찰소의 장 및 위치추적 관제센터의 장은 법 제31조의8제4항제1호 및 제2호에 따른 스토킹행위자 수신자료의 폐기를 위해 「형사사법절차 전자화 촉진법」 제2조제2호에 따른 형사사법업무 처리기관에 다음 각 호의 사항을 알아보거나 관련 자료의 열람 등 협조를 요청할 수 있다.', 288);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2200, '제23조의19(준용규정) 이 장에 따른 전자장치 부착 등에 관하여는 제7조제3항, 제10조, 제14조의2부터 제14조의6까지 및 제15조제2항을 준용한다. 이 경우 "피부착명령자" 및 "피부착자"는 각각 "전자장치 스토킹행위자"로, "수신자료"는 "스토킹행위자 수신자료"로 본다.', 288);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2201, '제24조(출소자 등의 인적사항 등 통보)', 289);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2202, '제25조(조사) 검사는 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제2호 및 제3항제2호에 따라 보호관찰소의 장에게 출소자등에 대한 법 제6조에 따른 조사를 요청할 때에는 수용시설의 장으로부터 통보받은 제24조제1항 각 호의 사항과 출소자등에 대한 범죄경력조회서, 연락처, 면담결과서 등을 통보하여야 한다.', 289);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2203, '제26조(부착명령 청구 사실의 통보) 검사는 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제4호 및 제3항제4호에 따라 출소자등에 대하여 부착명령을 청구한 경우에는 피청구인에게 지체 없이 서면으로 청구 사실을 통보하여야 한다.', 289);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2204, '제27조(부착명령 결정의 통지)', 289);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2205, '제28조(집행지휘)', 289);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2206, '제29조(민감정보 및 고유식별정보의 처리)', 289);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2207, '제1조(목적) 이 규칙은 「전자장치 부착 등에 관한 법률」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다. <개정 2009.7.30, 2013.5.31, 2020.8.5>', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2208, '제2조 삭제 <2010.7.15>', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2209, '제3조(조사의 요청)', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2210, '제4조(부착명령청구의 방식)', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2211, '제5조(교도소장 등의 석방예정 통보) 법 제10조제2항, 제22조제5항, 제23조제3항, 영 제7조제5항, 제8조제5항, 제20조제2항 및 제27조제3항의 통보는 별지 제4호서식의 석방예정통보서에 따른다. 다만, 영 제7조제5항의 경우로서 전자장치가 부착된 사람(이하 "피부착자"라 한다)이 벌금 완납으로 석방되는 등의 긴급한 사유로 별지 제4호서식에 따른 통보가 곤란한 경우에는 유선으로 통보할 수 있다. <개정 2010.7.15, 2013.5.31, 2015.9.7, 2020.8.5>', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2212, '제6조(집행지휘)', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2213, '제7조(구금 통보 등) 영 제8조제2항, 제4항 및 제5항(영 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 통보는 각각 별지 제6호서식의 구금(구금해제 결정)통보서에 따른다. <개정 2013.5.31>', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2214, '제8조(부착명령 집행정지자의 이송 통보 등) 영 제9조(영 제21조 및 제23조에 따라 준용되는 경우를 포함한다) 및 제20조제1항의 통보는 별지 제7호서식의 부착명령 집행정지자(피부착결정자) 이송통보서에 따른다.', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2215, '제9조(일시분리 대장) 영 제10조제2항(영 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 일시분리 대장은 별지 제8호서식에 따른다.', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2216, '제10조(주거이전, 국내여행 및 출국 허가서 등)', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2217, '제10조의2(부착기간의 연장 등의 신청 등)', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2218, '제10조의3(치료기관 등의 지정)', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2219, '제10조의4(수용 중 생활실태자료 확보 등)', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2220, '제11조(수신자료 사용대장) 영 제14조(영 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 수신자료 사용대장은 별지 제22호서식에 따른다. <개정 2013.5.31>', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2221, '제11조의2(수신자료 열람 또는 조회)', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2222, '제11조의3(긴급 수신자료 열람 또는 조회)', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2223, '제11조의4(열람 또는 조회한 수신자료의 보존ㆍ폐기 등)', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2224, '제11조의5(수신자료 사용사건의 결과 통지) 영 제14조의5제1항에 따른 검사 또는 사법경찰관의 서면 통지는 별지 제34호서식에 따른다.', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2225, '제11조의6(보호관찰소의 장의 수사기관 통보 등) 영 제15조의2제2항에 따른 보호관찰소의 장의 수사기관에 대한 통보는 별지 제35호서식에 따른다.', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2226, '제11조의7(영상정보 열람사실의 통지)', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2227, '제12조(임시해제 신청서 등) 영 제16조제1항의 임시해제 신청(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다) 및 영 제18조제1항의 임시해제 취소 신청(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)은 각각 별지 제36호서식의 부착명령 임시해제(임시해제 취소) 신청서에 따른다. <개정 2013.5.31, 2020.8.5>', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2228, '제12조의2(임시해제의 심사ㆍ결정기준) 「보호관찰 등에 관한 법률」 제5조에 따른 보호관찰 심사위원회가 법 제18조제1항ㆍ제4항ㆍ제5항(법 제21조의8, 제27조 및 제31조에 따라 준용되는 경우를 포함한다) 및 영 제17조제1항(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)에 따라 임시해제를 심사ㆍ결정할 때에는 피부착자 또는 보호관찰대상자의 연령, 건강상태, 가족관계, 가정환경, 범죄경력, 집행기간, 준수사항의 이행정도, 재범위험성 평가결과 및 그 밖에 필요한 사항을 고려해야 한다. <개정 2020.8.5>', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2229, '제13조(결정서) 법 제18조제4항ㆍ제5항(법 제21조의8, 제27조 및 제31조에 따라 준용되는 경우를 포함한다) 및 영 제17조(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)에 따른 임시해제 결정과 법 제19조제1항(법 제21조의8, 제27조 및 제31조에 따라 준용되는 경우를 포함한다) 및 영 제18조제2항(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)에 따른 임시해제 취소 결정은 각각 별지 제37호서식의 부착명령(보호관찰명령) 임시해제(임시해제 취소) 결정서에 따른다. <개정 2020.8.5>', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2230, '제13조의2(보호관찰명령 청구의 방식)', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2231, '제13조의3(집행지휘)', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2232, '제13조의4(보호관찰기간의 연장 등 신청) 법 제21조의7에 따른 보호관찰소의 장의 보호관찰기간의 연장 또는 준수사항의 추가ㆍ변경ㆍ삭제의 신청은 별지 제41호서식에 따르고, 법 제21조의7에 따른 검사의 보호관찰기간의 연장 또는 준수사항의 추가ㆍ변경ㆍ삭제의 청구는 별지 제42호서식에 따른다.', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2233, '제13조의5(수용 중 생활실태 자료 확보 등) 법 제21조의8에 따라 준용되는 법 제15조제3항에 따른 보호관찰명령 집행을 위한 수용 중 생활실태 자료 확보 등에 관하여는 제10조의4를 준용한다.', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2234, '제14조(전자장치 부착대상자 통보 등)', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2235, '제14조의2(조사의 의뢰) 법 제31조의2제2항 및 영 제23조의2제1항에 따른 조사의 의뢰는 별지 제44호의2서식에 따른다.', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2236, '제14조의3(보석 피고인 신고서) 법 제31조의3제2항 및 영 제23조의4에 따른 신고서는 별지 제44호의3서식에 따른다.', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2237, '제14조의4(보석조건 이행 상황 통지) 법 제31조의4제1항 및 영 제23조의6에 따른 보석조건 이행 상황의 통지는 별지 제44호의4서식에 따른다.', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2238, '제14조의5(보석조건 위반 통지) 법 제31조의4제2항 및 영 제23조의7에 따른 보석조건 위반 통지는 별지 제44호의5서식에 따른다.', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2239, '제14조의6(스토킹행위자 신고서) 법 제31조의6제2항 및 영 제23조의11제1항에 따른 신고는 별지 제44호의6서식에 따른다.', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2240, '제14조의7(전자장치 부착 사실의 통지) 법 제31조의6제3항 각 호 외의 부분 및 영 제23조의13제1항에 따른 전자장치 부착 사실의 통지는 별지 제44호의7서식에 따른다.', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2241, '제14조의8(피해자 관련 사항의 통지) 법 제31조의6제3항 및 영 제23조의13제2항에 따른 피해자 관련 사항의 통지는 별지 제44호의8서식에 따른다.', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2242, '제14조의9(잠정조치 결정의 효력 상실 통지) 법 제31조의6제6항 또는 영 제23조의16에 따른 잠정조치 결정의 효력 상실 통지는 별지 제44호의9서식에 따른다.', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2243, '제14조의10(스토킹행위자 수신자료 사용대장) 영 제23조의17에 따른 스토킹행위자 수신자료 사용대장은 별지 제44호의10서식에 따른다.', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2244, '제15조(출소자등 통보서) 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제1호, 제3항제1호 및 영 제24조에 따른 출소자 등의 인적사항 등 통보는 별지 제45호서식의 출소자등 통보서에 따른다. <개정 2013.5.31>', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2245, '제16조(출석요구서) 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제5호에 따른 출석 요구는 별지 제46호서식의 출석요구서에 따른다. <개정 2013.5.31>', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2246, '제17조(구인영장 청구서 등)', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2247, '제18조(구인영장)', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2248, '제19조(부착명령 집행장)', 290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2249, '제1조(목적) 이 규칙은 경찰공무원(해양경찰청 소속 경찰공무원은 제외한다)인 사법경찰관리가 「형사소송법」 및 「검사와 사법경찰관의 상호협력과 일반적 수사준칙에 관한 규정」 등 수사 관계 법령에 따라 수사를 하는 데 필요한 사항을 규정함을 목적으로 한다.', 291);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2250, '제2조(인권 보호 및 적법절차의 준수)', 291);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2251, '제3조(협력의 방식 등)', 292);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2252, '제4조(중요사건 협력절차)', 292);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2253, '제5조(소재수사에 관한 협력)', 292);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2254, '제6조(시찰조회 요청에 관한 협력)', 292);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2255, '제7조(검사와의 협의 등)', 292);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2256, '제8조(사법경찰관리의 상호협력)', 292);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2257, '제9조(접수 전 점검 및 조치)', 294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2258, '제10조(회피) 사법경찰관리는 수사준칙 제11조에 따라 수사를 회피하려는 경우에는 별지 제8호서식의 회피신청서를 소속경찰관서장에게 제출해야 한다.', 294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2259, '제11조(수사 진행상황의 통지)', 294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2260, '제12조(변호인의 피의자신문 참여)', 294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2261, '제13조(신문 중 변호인 참여 제한)', 294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2262, '제14조(사건관계인에 대한 적용) 사건관계인에 대한 조사ㆍ면담 시 변호인의 참여에 관하여는 제12조 및 제13조를 준용한다.', 294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2263, '제15조(직무 관할) 사법경찰관리는 소속된 경찰관서의 관할구역에서 직무를 수행한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 관할구역이 아닌 곳에서도 그 직무를 수행할 수 있다.', 294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2264, '제16조(사건의 단위) 법 제11조에 따른 관련사건은 1건으로 처리한다. 다만, 분리수사를 하는 경우에는 그렇지 않다.', 294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2265, '제17조(심사관)', 294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2266, '제18조(수사의 개시)', 295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2267, '제19조(입건 전 조사)', 295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2268, '제20조(불입건 결정 통지)', 295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2269, '제21조(고소ㆍ고발의 수리)', 295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2270, '제22조(고소인ㆍ고발인 진술조서 등)', 295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2271, '제23조(고소의 대리 등)', 295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2272, '제24조(고소ㆍ고발사건의 수사기간)', 295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2273, '제25조(고소ㆍ고발 취소 등에 따른 조치)', 295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2274, '제26조(변사사건 발생사실 통보)', 295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2275, '제27조(변사자의 검시ㆍ검증)', 295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2276, '제28조(검시ㆍ검증조서 등)', 295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2277, '제29조(검시의 주의사항) 사법경찰관리는 검시할 때에는 다음 각 호의 사항에 주의해야 한다.', 295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2278, '제30조(검시와 참여자) 사법경찰관리는 검시에 특별한 지장이 없다고 인정하면 변사자의 가족ㆍ친족, 이웃사람ㆍ친구, 시ㆍ군ㆍ구ㆍ읍ㆍ면ㆍ동의 공무원이나 그 밖에 필요하다고 인정하는 사람을 검시에 참여시켜야 한다.', 295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2279, '제31조(사체의 인도)', 295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2280, '제32조(검사 이송 사건의 처리) 사법경찰관은 수사준칙 제18조에 따라 검사로부터 사건을 이송받은 경우에는 지체 없이 접수하여 처리한다.', 295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2281, '제33조(고위공직자범죄등 인지 통보) 사법경찰관은 「고위공직자범죄수사처 설치 및 운영에 관한 법률」 제24조제2항에 따라 고위공직자범죄등 인지 사실을 통보하는 경우에는 별지 제20호서식의 고위공직자범죄등 인지통보서에 따른다.', 295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2282, '제34조(출석요구) 수사준칙 제19조제3항 본문 또는 같은 조 제6항에 따라 피의자 또는 피의자 외의 사람에게 출석요구를 하려는 경우에는 별지 제21호서식 또는 별지 제22호서식의 출석요구서에 따른다.', 297);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2283, '제35조(수사상 임의동행) 사법경찰관리는 수사준칙 제20조에 따른 임의동행 고지를 하고 임의동행한 경우에는 별지 제23호서식의 임의동행 동의서를 작성하여 사건기록에 편철하거나 별도로 보관해야 한다.', 297);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2284, '제36조(심야조사 제한)', 297);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2285, '제37조(장시간 조사 제한) 사법경찰관리는 피의자나 사건관계인으로부터 수사준칙 제22조제1항제1호에 따라 조서 열람을 위한 조사 연장을 요청받은 경우에는 별지 제24호서식의 조사연장 요청서를 제출받아야 한다.', 297);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2286, '제38조(신뢰관계인 동석)', 297);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2287, '제39조(조서와 진술서)', 297);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2288, '제40조(수사과정의 기록) 사법경찰관리는 수사준칙 제26조제1항에 따라 조사 과정의 진행경과를 별도의 서면에 기록하는 경우에는 별지 제31호서식 또는 별지 제32호서식의 수사 과정 확인서에 따른다.', 297);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2289, '제41조(실황조사)', 297);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2290, '제42조(감정의 위촉) 사법경찰관은 법 제221조제2항에 따라 감정을 위촉하는 경우에는 별지 제34호서식의 감정위촉서에 따른다. 법 제221조의4에 따라 감정에 필요한 허가장을 발부받아 위촉하는 경우에도 또한 같다.', 297);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2291, '제43조(영상녹화)', 298);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2292, '제44조(영상녹화물의 제작 및 보관)', 298);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2293, '제45조(지명수배)', 299);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2294, '제46조(지명수배자 발견 시 조치)', 299);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2295, '제47조(지명통보) 사법경찰관리는 다음 각 호의 어느 하나에 해당하는 사람의 소재를 알 수 없을 때에는 지명통보를 할 수 있다.', 299);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2296, '제48조(지명통보자 발견 시 조치) 사법경찰관리는 제47조에 따라 지명통보된 사람(이하 "지명통보자"라 한다)을 발견한 때에는 지명통보자에게 지명통보된 사실, 범죄사실의 요지 및 지명통보한 경찰관서(이하 이 조 및 제49조에서 "통보관서"라 한다)를 고지하고, 발견된 날부터 1개월 이내에 통보관서에 출석해야 한다는 내용과 정당한 사유 없이 출석하지 않을 경우 지명수배되어 체포될 수 있다는 내용을 통지해야 한다.', 299);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2297, '제49조(지명수배ㆍ지명통보 해제) 사법경찰관리는 다음 각 호의 어느 하나에 해당하는 경우에는 즉시 지명수배 또는 지명통보를 해제해야 한다.', 299);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2298, '제50조(체포영장의 신청) 사법경찰관은 법 제200조의2제1항에 따라 체포영장을 신청하는 경우에는 별지 제37호서식의 체포영장 신청서에 따른다. 이 경우 현재 수사 중인 다른 범죄사실에 관하여 그 피의자에 대해 발부된 유효한 체포영장이 있는지를 확인해야 하며 해당사항이 있는 경우에는 그 사실을 체포영장 신청서에 적어야 한다.', 301);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2299, '제51조(긴급체포)', 301);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2300, '제52조(현행범인 체포 및 인수)', 301);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2301, '제53조(현행범인 석방)', 301);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2302, '제54조(구속영장의 신청) 수사준칙 제29조에 따른 구속영장 신청서는 별지 제45호서식부터 별지 제48호서식까지에 따른다.', 301);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2303, '제55조(체포ㆍ구속영장의 집행)', 301);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2304, '제56조(호송)', 301);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2305, '제57조(체포ㆍ구속 통지 등) 사법경찰관은 수사준칙 제33조제1항(같은 조 제3항에서 준용되는 경우를 포함한다)에 따라 체포ㆍ구속의 통지를 하는 경우에는 별지 제49호서식의 체포ㆍ긴급체포ㆍ현행범인체포ㆍ구속 통지서에 따른다.', 301);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2306, '제58조(체포ㆍ구속영장의 반환) 수사준칙 제35조제2항에 따른 영장반환서는 별지 제50호서식에 따른다.', 301);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2307, '제59조(피의자 접견 등 금지)', 301);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2308, '제60조(피의자 석방 및 통보)', 301);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2309, '제61조(구속의 취소)', 301);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2310, '제62조(구속의 집행정지)', 301);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2311, '제63조(압수ㆍ수색 또는 검증영장의 신청 등)', 302);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2312, '제64조(압수조서 등)', 302);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2313, '제65조(수색조서 및 수색증명서)', 302);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2314, '제66조(압수물의 환부 및 가환부)', 302);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2315, '제67조(압수물 보관)', 302);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2316, '제68조(압수물 폐기)', 302);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2317, '제69조(압수물 대가보관)', 302);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2318, '제70조(검증조서) 수사준칙 제43조에 따른 검증조서는 별지 제17호서식에 따른다.', 302);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2319, '제71조(증거보전 신청) 사법경찰관은 미리 증거를 보전하지 않으면 그 증거를 사용하기 곤란한 경우에는 별지 제82호서식의 증거보전 신청서를 작성하여 검사에게 법 제184조제1항에 따른 증거보전의 청구를 신청할 수 있다.', 303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2320, '제72조(증인신문 신청) 사법경찰관은 범죄의 수사에 없어서는 안 되는 사실을 안다고 명백히 인정되는 사람이 출석 또는 진술을 거부하는 경우에는 별지 제83호서식의 증인신문 신청서를 작성하여 검사에게 법 제221조의2제1항에 따른 증인신문의 청구를 신청할 수 있다.', 303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2321, '제73조(감정유치 및 감정처분허가 신청)', 303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2322, '제74조(영장심의위원회) 사법경찰관은 법 제221조의5제1항에 따라 영장 청구 여부에 대한 심의를 신청하는 경우에는 「영장심의위원회 규칙」 제13조에 따라 관할 고등검찰청에 심의신청을 해야 한다.', 303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2323, '제75조(시정조치요구의 이행)', 304);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2324, '제76조(징계요구 처리 결과 등 통보) 소속경찰관서장은 수사준칙 제46조제2항에 따라 징계요구의 처리 결과와 그 이유를 통보하는 경우에는 별지 제88호서식의 징계요구 처리결과 통보서에 따른다.', 304);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2325, '제77조(구제신청 고지의 확인) 수사준칙 제47조에 따른 고지 확인서는 별지 제89호서식에 따른다.', 304);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2326, '제78조(수사의 경합 시 기록 열람)', 305);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2327, '제79조(피해자 보호의 원칙)', 306);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2328, '제80조(신변보호)', 306);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2329, '제81조(피해자에 대한 정보 제공) 사법경찰관리는 피해자를 조사하는 경우 다음 각 호의 정보를 피해자에게 제공해야 한다. 다만, 피해자에 대한 조사를 하지 않는 경우에는 수사준칙 제51조제1항에 따른 결정(이송 결정은 제외한다)을 하기 전까지 정보를 제공해야 한다.', 306);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2330, '제82조(회복적 대화)', 306);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2331, '제83조(범죄피해의 평가) 사법경찰관리는 피해자의 피해정도를 파악하고 보호ㆍ지원의 필요성을 판단하기 위해 범죄피해평가를 실시할 수 있으며, 일정한 자격을 갖춘 단체 또는 개인에게 이를 의뢰할 수 있다.', 306);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2332, '제84조(문서의 서식) 이 규칙에서 정한 서식 외에 단순하고 정형적인 사건의 수사 등에 사용하는 서식은 경찰청장이 정한다.', 307);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2333, '제85조(장부와 비치서류)', 307);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2334, '제86조(범죄통계원표) 사법경찰관리는 범죄를 수사한 경우에는 형사사법정보시스템을 이용하여 사건마다 범죄통계원표를 작성한다.', 307);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2335, '제87조(수사서류 열람ㆍ복사)', 307);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2336, '제88조(전자약식절차)', 309);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2337, '제89조(소년에 대한 조사)', 310);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2338, '제90조(장애인에 대한 조사) 사법경찰관리는 청각장애인 및 언어장애인이나 그 밖에 의사소통이 어려운 장애인을 조사하는 경우에는 직권으로 또는 장애인 본인, 보호자, 법정대리인 등의 신청에 따라 수화ㆍ문자통역을 제공하거나 의사소통을 도울 수 있는 사람을 참여시켜야 한다.', 310);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2339, '제91조(외국인에 대한 조사)', 310);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2340, '제92조(한미행정협정사건의 통보)', 310);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2341, '제93조(몰수ㆍ부대보전 신청) 사법경찰관은 관계 법령에 따라 검사에게 몰수ㆍ부대보전을 신청하는 경우에는 별지 제96호서식의 몰수ㆍ부대보전 신청서에 따른다.', 311);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2342, '제94조(추징보전의 신청)', 311);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2343, '제95조(장기사건 수사종결)', 313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2344, '제96조(사건 이송)', 313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2345, '제97조(수사 결과의 통지)', 313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2346, '제98조(수사중지 결정)', 314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2347, '제99조(소재수사 등)', 314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2348, '제100조(수사중지 시 지명수배ㆍ지명통보) 사법경찰관은 피의자의 소재불명을 이유로 수사중지 결정을 하려는 경우에는 지명수배 또는 지명통보를 해야 한다.', 314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2349, '제101조(수사중지 결정에 대한 이의제기 절차)', 314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2350, '제102조(수사중지사건 수사재개)', 314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2351, '제103조(송치 서류)', 315);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2352, '제104조(추가송부) 수사준칙 제58조제3항에 따른 추가송부서는 별지 제118호서식에 따른다.', 315);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2353, '제105조(보완수사요구의 결과 통보 등)', 315);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2354, '제106조(직무배제 또는 징계 요구의 처리 등)', 315);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2355, '제107조(법원송치)', 315);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2356, '제108조(불송치 결정)', 316);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2357, '제109조(불송치 서류)', 316);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2358, '제110조(일부 결정 시 조치 등)', 316);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2359, '제111조(혐의없음 결정 시의 유의사항) 사법경찰관은 고소 또는 고발 사건에 관하여 제108조제1항제1호의 혐의없음 결정을 하는 경우에는 고소인 또는 고발인의 무고혐의의 유무를 판단해야 한다.', 316);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2360, '제112조(재수사 결과의 처리)', 316);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2361, '제113조(고소인등의 이의신청)', 316);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2362, '제1조(목적) 이 규칙은 군사법경찰관리가 「군사법원법」 및 「군검사와 군사법경찰관의 수사준칙에 관한 규정」 등 수사 관계 법령에 따라 수사를 하는 데 필요한 사항을 규정함을 목적으로 한다.', 317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2363, '제2조(인권 보호 및 적법절차의 준수)', 317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2364, '제3조(군사법경찰관리의 상호협력) 군사법경찰관리는 수사에 필요한 경우에는 다른 군사법경찰관리에게 피의자의 체포ㆍ출석요구ㆍ조사ㆍ호송, 압수ㆍ수색ㆍ검증, 참고인의 출석요구ㆍ조사 등 그 밖에 필요한 조치에 대한 협력을 요청할 수 있다. 이 경우 요청을 받은 군사법경찰관리는 정당한 이유가 없으면 이에 적극 협조해야 한다.', 317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2365, '제4조(회피) 군사법경찰관리는 수사준칙 제6조에 따라 수사를 회피하려는 경우에는 별지 제1호서식의 회피신청서를 소속 부대 또는 기관의 장에게 제출해야 한다.', 319);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2366, '제5조(수사 진행 상황의 통지)', 319);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2367, '제6조(변호인의 피의자신문 참여)', 319);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2368, '제7조(신문 중 변호인 참여 제한)', 319);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2369, '제8조(사건관계인에 대한 적용) 사건관계인에 대한 조사ㆍ면담 시 변호인의 참여에 관하여는 제6조 및 제7조를 준용한다.', 319);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2370, '제9조(피해자 보호의 원칙)', 319);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2371, '제10조(사건의 단위) 법 제13조에 따른 관련사건은 1건으로 처리한다. 다만, 분리수사를 하는 경우에는 그렇지 않다.', 319);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2372, '제11조(심사관) 국군방첩사령관, 국방부조사본부장, 각 군 및 해병대 수사단장은 수사의 책임성과 적법성 등을 확보하기 위하여 예하 수사업무 담당 부대(이하 "수사부대"라 한다)의 수사에 관한 적법성ㆍ타당성 심사 및 수사 전반에 대한 점검 등의 업무를 수행하는 심사관을 둘 수 있다.', 319);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2373, '제12조(수사의 개시)', 320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2374, '제13조(입건 전 조사)', 320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2375, '제14조(불입건 결정 통지)', 320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2376, '제15조(고소ㆍ고발의 수리)', 320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2377, '제16조(고소인ㆍ고발인 진술조서 등)', 320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2378, '제17조(고소의 대리 등)', 320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2379, '제18조(고소ㆍ고발사건의 수사기간)', 320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2380, '제19조(고소ㆍ고발 취소 등에 따른 조치)', 320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2381, '제20조(촉탁 수사 등의 결과 통보) 법 제228조제4항에 따라 수사 또는 영장의 집행을 촉탁받은 군사법경찰관이 그 결과를 통보할 때에는 별지 제7호서식의 촉탁 수사 등 결과 통보서로 회답해야 한다.', 320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2382, '제21조(변사자의 검시ㆍ검증) 군사법경찰관은 법 제264조제1항ㆍ제2항 및 제4항에 따라 검시(檢屍)를 할 때에는 군의관 또는 의사를 참여시켜야 하며, 그 군의관 또는 의사로 하여금 검안서를 작성하게 해야 한다.', 320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2383, '제22조(검시ㆍ검증조서 등)', 320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2384, '제23조(검시의 주의사항) 군사법경찰관리는 검시할 때에는 다음 각 호의 사항에 주의해야 한다.', 320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2385, '제24조(검시와 참여자) 군사법경찰관리는 검시에 특별한 지장이 없다고 인정하면 변사자의 가족ㆍ친족, 소속 부대원이나 그 밖에 필요하다고 인정하는 사람을 검시에 참여시켜야 한다.', 320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2386, '제25조(사체의 인도)', 320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2387, '제26조(고위공직자범죄 등의 인지 통보) 군사법경찰관은 「고위공직자범죄수사처 설치 및 운영에 관한 법률」 제24조제2항에 따라 고위공직자범죄등(같은 법 제2조제5호에 따른 죄를 말한다. 이하 같다) 인지사실을 통보할 때에는 별지 제11호서식의 고위공직자범죄등 인지 통보서에 따른다.', 320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2388, '제27조(군검사와의 의견 제시ㆍ교환)', 320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2389, '제28조(출석요구) 수사준칙 제13조제2항 본문 또는 같은 조 제4항에 따라 피의자 또는 피의자 외의 사람에게 출석요구를 하려는 경우에는 별지 제14호서식 또는 별지 제15호서식의 출석요구서에 따른다.', 322);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2390, '제29조(수사상 임의동행) 군사법경찰관은 수사준칙 제14조에 따른 임의동행 고지를 하고 임의동행한 경우에는 별지 제16호서식의 임의동행 동의서를 작성하여 사건기록에 편철하거나 별도로 보관해야 한다.', 322);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2391, '제30조(장시간 조사 제한) 군사법경찰관은 피의자나 사건관계인으로부터 수사준칙 제16조제1항제1호에 따라 조서 열람을 위한 조사 연장을 요청받은 경우에는 별지 제17호서식의 조사시간 연장 요청서를 제출받아야 한다.', 322);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2392, '제31조(신뢰관계인의 동석)', 322);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2393, '제32조(조서와 진술서)', 322);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2394, '제33조(수사과정의 기록) 군사법경찰관리는 수사준칙 제20조에 따라 조사 과정의 진행경과를 별도의 서면에 기록할 때에는 별지 제24호서식 또는 별지 제25호서식의 수사과정 확인서에 따른다.', 322);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2395, '제34조(실황조사)', 322);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2396, '제35조(감정의 위촉) 군사법경찰관은 법 제260조제2항에 따라 감정을 위촉할 때에는 별지 제27호서식의 감정위촉서에 따른다. 법 제263조에 따라 감정에 필요한 허가장을 발급받아 위촉하는 경우에도 또한 같다.', 322);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2397, '제36조(영상녹화)', 323);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2398, '제37조(영상녹화물의 제작 및 보관)', 323);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2399, '제38조(체포영장의 신청) 군사법경찰관은 법 제232조의2제1항에 따라 체포영장을 신청할 때에는 별지 제29호서식의 체포영장 신청서에 따른다. 이 경우 현재 수사 중인 다른 범죄사실에 관하여 그 피의자에 대해 발부된 유효한 체포영장이 있는지를 확인해야 하며, 해당 사항이 있는 경우에는 그 사실을 체포영장 신청서에 적어야 한다.', 325);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2400, '제39조(긴급체포)', 325);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2401, '제40조(현행범인 체포 및 인수)', 325);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2402, '제41조(현행범인 석방)', 325);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2403, '제42조(구속영장의 신청) 수사준칙 제23조에 따른 구속영장 신청서는 별지 제37호서식부터 별지 제40호서식까지에 따른다.', 325);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2404, '제43조(체포ㆍ구속영장의 집행)', 325);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2405, '제44조(호송)', 325);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2406, '제45조(체포ㆍ구속의 통지 등) 군사법경찰관은 수사준칙 제27조제1항에 따라 체포ㆍ구속의 통지를 할 때에는 별지 제42호서식의 체포ㆍ긴급체포ㆍ현행범인체포ㆍ구속 통지서에 따른다.', 325);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2407, '제46조(체포ㆍ구속영장의 반환) 수사준칙 제29조제2항에 따른 영장반환서는 별지 제43호서식에 따른다.', 325);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2408, '제47조(피의자 접견 등 금지)', 325);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2409, '제48조(피의자 석방 및 통보)', 325);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2410, '제49조(구속의 취소)', 325);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2411, '제50조(구속의 집행정지)', 325);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2412, '제51조(압수ㆍ수색 또는 검증영장의 신청 등)', 326);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2413, '제52조(압수조서 등)', 326);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2414, '제53조(수색조서 및 수색증명서)', 326);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2415, '제54조(압수물의 환부 및 가환부)', 326);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2416, '제55조(압수물 보관)', 326);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2417, '제56조(압수물 폐기)', 326);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2418, '제57조(압수물 대가보관)', 326);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2419, '제58조(검증조서) 수사준칙 제37조에 따른 검증조서는 별지 제9호서식에 따른다.', 326);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2420, '제59조(증거보전 신청) 군사법경찰관은 미리 증거를 보전하지 않으면 그 증거를 사용하기 곤란한 경우에는 군검사에게 법 제226조제1항에 따른 증거보전의 청구를 신청할 수 있다. 이 경우 증거보전 청구 신청서는 별지 제75호서식에 따른다.', 327);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2421, '제60조(증인신문 신청) 군사법경찰관은 범죄 수사에 없어서는 아니 될 사실을 안다고 명백히 인정되는 사람이 법 제260조에 따른 출석 또는 진술을 거부할 때에는 군검사에게 법 제261조제1항에 따른 증인신문의 청구를 신청할 수 있다. 이 경우 증인신문 청구 신청서는 별지 제76호서식에 따른다.', 327);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2422, '제61조(감정유치 및 감정처분허가 신청)', 327);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2423, '제62조(수사서류 등의 열람ㆍ복사)', 328);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2424, '제63조(사건 이송)', 329);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2425, '제64조(사건송치 등)', 329);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2426, '제65조(송치 서류)', 329);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2427, '제66조(보완수사요구의 결과 통보 등)', 329);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2428, '제1조(목적) 이 규칙은 「형사소송법」 제245조의10제4항에 따른 검사의 수사지휘에 관한 구체적인 사항과 「사법경찰관리의 직무를 행할 자와 그 직무범위에 관한 법률」에 따라 사법경찰관리의 직무를 행하는 자의 범죄수사에 관한 집무상의 준칙을 규정함으로써 수사과정에서 국민의 인권을 보호하고, 수사절차의 투명성과 수사의 효율성을 보장함을 목적으로 한다.', 330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2429, '제2조(특별사법경찰관리의 직무)', 330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2430, '제3조(수사의 기본원칙)', 330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2431, '제4조(불이익 금지 및 기밀엄수) 특별사법경찰관리는 피의자나 사건관계인이 인권침해 신고나 그 밖에 인권 구제를 위한 신고, 진정, 고소, 고발 등의 행위를 했다는 이유로 부당한 대우를 하거나 불이익을 주어서는 안 된다.', 330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2432, '제5조(수사사건의 공개금지 등)', 330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2433, '제6조(관할)', 332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2434, '제7조(임의수사 우선의 원칙과 강제수사 시 유의사항)', 332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2435, '제8조(회피) 특별사법경찰관리는 피의자나 사건관계인과 친족관계 또는 이에 준하는 관계가 있거나 그 밖에 수사의 공정성을 의심 받을 염려가 있는 사건에 대해서는 소속 기관의 장의 허가를 받아 그 수사를 회피해야 한다.', 332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2436, '제9조(수사 진행상황의 통지) 특별사법경찰관리는 수사의 진행상황을 사건관계인에게 적절히 통지하도록 노력해야 한다.', 332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2437, '제10조(변호인의 피의자신문 등 참여)', 332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2438, '제11조(변호인의 의견진술)', 332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2439, '제12조(피해자 보호)', 332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2440, '제13조(수사의 협조) 특별사법경찰관리는 직무를 수행하면서 다른 사법경찰관리와 서로 성실하게 협조해야 한다.', 332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2441, '제14조(사건의 단위) 다음 각 호의 어느 하나에 해당하는 범죄사건은 1건으로 처리한다.', 332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2442, '제15조(사법경찰관리 지명서 휴대의무) 사법경찰직무법 제5조에 따라 지명된 특별사법경찰관리는 압수수색ㆍ조사 등 수사업무를 수행할 때에는 사법경찰관리로 지명된 사람임을 증명하는 서류를 항상 지니고 있어야 한다.', 332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2443, '제16조(합동단속반의 설치ㆍ운영 등)', 332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2444, '제17조(내사)', 333);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2445, '제18조(범죄인지서)', 333);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2446, '제19조(수사의 개시)', 333);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2447, '제20조(사건기록의 관리)', 333);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2448, '제21조(변사자의 검시)', 333);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2449, '제22조(검시할 때의 주의사항)', 333);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2450, '제23조(검시의 참여) 특별사법경찰관은 검시에 특별한 지장이 없다고 인정할 때에는 변사자의 가족ㆍ친족ㆍ이웃사람ㆍ친구, 공무원 또는 그 밖에 필요하다고 인정하는 사람을 검시에 참여시켜야 한다.', 333);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2451, '제24조(자살자의 검시) 특별사법경찰관은 자살한 사람을 검시할 때에는 자살을 교사하거나 방조한 사람이 있는지를 조사해야 하며, 유서가 있을 때에는 그 진위 여부를 조사해야 한다.', 333);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2452, '제25조(수사개시 보고) 특별사법경찰관은 사법경찰직무법 제6조에서 부여한 직무범위에서 다음 각 호의 어느 하나에 해당하는 범죄에 대하여 수사를 개시했을 때에는 즉시 관할 지방검찰청 검사장 또는 지청장에게 별지 제5호서식의 수사개시 보고서로 보고해야 한다.', 334);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2453, '제26조(직무범위 외의 범죄발생에 대한 보고) 특별사법경찰관은 그 직무범위에 속하지 않는 범죄나 이에 대한 증거자료를 발견한 경우에도 다음 각 호의 어느 하나에 해당할 때에는 발견한 범죄사실이나 증거자료를 검사의 지휘를 받아 수사기관에 통보해야 한다.', 334);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2454, '제27조(범죄통계원표 등)', 334);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2455, '제28조(수사지휘의 원칙) 검사는 특별사법경찰관을 존중하고, 법률에 따라 특별사법경찰관의 모든 수사를 적정하게 지휘한다.', 335);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2456, '제29조(수사지휘 일반)', 335);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2457, '제30조(수사지휘 건의)', 335);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2458, '제31조(수사지휘의 방식)', 335);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2459, '제32조(수사지휘에 대한 재지휘 건의)', 335);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2460, '제33조(신속한 수사지휘) 검사는 특별사법경찰관으로부터 제30조에 따른 수사지휘 건의나 제32조에 따른 재지휘 건의를 받은 경우에는 지체 없이 지휘해야 한다. 다만, 사안이 복잡하거나 장기간 검토해야 할 특별한 사정이 있을 때에는 그렇지 아니하다.', 335);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2461, '제34조(수사지휘 기한 준수)', 335);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2462, '제35조(중요범죄의 입건 등)', 335);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2463, '제36조(출석요구)', 336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2464, '제37조(수사상 임의동행 시의 고지) 특별사법경찰관은 임의동행을 요구하는 경우 상대방에게 동행을 거부할 수 있다는 것과 동행하는 경우에도 언제든지 자유롭게 동행 과정에서 이탈하거나 동행 장소에서 퇴거할 수 있다는 것을 알려야 한다.', 336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2465, '제38조(심야조사 제한)', 336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2466, '제39조(장시간 조사 제한)', 336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2467, '제40조(휴식시간 부여)', 336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2468, '제41조(신뢰관계인의 동석)', 336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2469, '제42조(자료ㆍ의견의 제출기회 보장)', 336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2470, '제43조(수사과정의 기록)', 336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2471, '제44조(피의자에 대한 조사사항) 특별사법경찰관리는 피의자를 조사할 때에는 다음 각 호의 사항을 유의해야 한다.', 336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2472, '제45조(조서와 진술서)', 336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2473, '제46조(진술거부권 등의 고지 확인) 특별사법경찰관은 피의자신문조서 작성을 갈음하여 피의자에게 진술서를 작성하도록 하는 경우 등 피의자신문조서를 작성하지 않은 경우에는 법 제244조의3에 따라 진술거부권 등을 고지한 사실과 진술거부권 등의 고지에 대한 피의자의 답변에 대하여 피의자로부터 별지 제24호서식의 진술거부권 및 변호인 조력권 고지 등 확인서를 제출받아 기록에 편철해야 한다.', 336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2474, '제47조(사건관계인의 조사)', 336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2475, '제48조(조서 및 자료의 편철) 특별사법경찰관은 조서, 수사보고서 등 수사관계 서류를 작성하거나 해당 사건에 관한 자료를 접수했을 때에는 작성 또는 접수 순서에 따라 사건기록에 편철하고, 이를 기록목록에 적어야 하며, 사건기록에는 매 장마다 장수를 적어야 한다. 다만, 범죄사실과 직접 관련이 없거나 중복하여 작성 또는 접수된 자료는 별도의 기록으로 분리하여 편철할 수 있다.', 336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2476, '제49조(영상녹화)', 336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2477, '제50조(영상녹화물의 제작 등)', 336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2478, '제51조(임상조사) 특별사법경찰관리는 치료중인 피의자나 참고인을 상대로 임상신문(臨床訊問)을 하려는 경우에는 상대방의 건강상태를 충분히 고려해야 하며, 수사에 중대한 지장이 없는 한 가족이나 의사, 간호사 또는 해당 의료기관의 관리자를 참여시켜야 한다.', 336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2479, '제52조(실황조사)', 336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2480, '제53조(수사관계사항의 조회) 특별사법경찰관은 법 제199조제2항에 따라 공무소 기타 공사단체에 필요한 사항의 보고를 요구하는 경우에는 별지 제27호서식의 수사사항조회서에 따른다.', 336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2481, '제54조(영장의 집행)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2482, '제55조(체포영장의 신청)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2483, '제56조(영장의 재신청) 특별사법경찰관은 다음 각 호의 어느 하나에 해당하는 경우 동일한 범죄사실로 다시 영장등의 발부를 신청할 때에는 그 취지를 검사에게 보고하고, 영장등의 신청서에 적어야 한다.', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2484, '제57조(긴급체포)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2485, '제58조(현행범인의 체포)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2486, '제59조(현행범인의 조사와 석방)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2487, '제60조(구속영장의 신청 등)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2488, '제61조(체포ㆍ구속의 통지 등)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2489, '제62조(체포ㆍ구속영장등본의 교부)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2490, '제63조(피의자의 접견 등)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2491, '제64조(피의자 유치 시 유의사항)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2492, '제65조(구금된 피의자의 처우) 특별사법경찰관리는 구금된 피의자에 대해서는 구금생활에 필요한 의류ㆍ침구, 그 밖의 생활용품과 식량 등을 지급해야 하며, 위생ㆍ의료 등에 있어서 상당한 처우를 해야 한다.', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2493, '제66조(구금과 건강상태) 특별사법경찰관은 피의자를 구금할 때에는 그의 건강상태를 조사하고 체포ㆍ구속으로 인하여 현저하게 건강을 해칠 염려가 있다고 인정할 때에는 그 사유를 검사에게 보고해야 한다.', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2494, '제67조(피의자의 석방)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2495, '제68조(체포ㆍ구속장소 감찰 관련 조치)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2496, '제69조(피의자의 도주 등) 특별사법경찰관은 체포하거나 구속한 피의자가 도주 또는 사망하거나, 그 밖의 이상이 발생한 때에는 즉시 관할 지방검찰청 또는 지청의 검사에게 보고해야 한다.', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2497, '제70조(압수ㆍ수색 또는 검증영장의 신청)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2498, '제71조(압수ㆍ수색 또는 검증영장의 제시)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2499, '제72조(전자정보의 압수ㆍ수색 또는 검증 방법)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2500, '제73조(전자정보의 압수ㆍ수색 또는 검증 시 유의사항)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2501, '제74조(압수조서의 작성)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2502, '제75조(증거물 등의 보전)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2503, '제76조(수색조서의 작성 등)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2504, '제77조(검증조서의 작성) 특별사법경찰관리가 검증을 한 경우에는 검증의 일시ㆍ장소, 검증 경위 등을 포함하여 별지 제66호서식의 검증조서를 작성해야 한다.', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2505, '제78조(압수물의 보관ㆍ폐기ㆍ환부 및 가환부)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2506, '제79조(범죄수사 목적 통신제한조치 허가신청 등)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2507, '제80조(통신제한조치의 집행 등)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2508, '제81조(통신제한조치로 취득한 자료의 관리)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2509, '제82조(통신제한조치 집행에 관한 통지 등)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2510, '제83조(송ㆍ수신이 완료된 전기통신에 대한 압수ㆍ수색ㆍ검증 집행사실 통지) 특별사법경찰관이 「통신비밀보호법」 제9조의3제2항에 따라 수사대상이 된 가입자에게 송ㆍ수신이 완료된 전기통신에 대한 압수ㆍ수색ㆍ검증의 집행사실을 통지하는 경우에는 별지 제94호서식의 송ㆍ수신이 완료된 전기통신에 대한 압수ㆍ수색ㆍ검증 집행사실 통지서에 따른다. 이 경우 특별사법경찰관은 별지 제95호서식의 송ㆍ수신이 완료된 전기통신에 대한 압수ㆍ수색ㆍ검증 집행사실 통지부에 해당 사항을 기재해야 한다.', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2511, '제84조(범죄수사를 위한 전기통신 보관 등의 승인청구 신청 등) 특별사법경찰관이 「통신비밀보호법」 제12조의2제2항에 따라 전기통신 보관 등의 승인 청구를 신청하는 경우에는 별지 제96호서식의 전기통신 보관 등 승인신청서에 따른다. 이 경우 특별사법경찰관은 별지 제97호서식의 전기통신 보관 등 승인신청부에 해당 사항을 기재해야 한다.', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2512, '제85조(통신사실 확인자료제공 요청 등)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2513, '제86조(통신사실 확인자료제공 요청 허가신청 등)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2514, '제87조(긴급 통신사실 확인자료제공 요청 등)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2515, '제88조(통신사실 확인자료제공에 관한 통지 등)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2516, '제89조(감정유치장 신청 등)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2517, '제90조(영장 등의 반환)', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2518, '제91조(증거보전의 신청) 특별사법경찰관은 미리 증거를 보전하지 않으면 그 증거를 사용하기 곤란한 사정이 있을 때에는 그 사유를 소명하여 별지 제119호서식의 증거보전신청서로 검사에게 증거보전의 청구를 신청해야 한다.', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2519, '제92조(증인신문의 신청) 특별사법경찰관리가 검사에게 법제221조의2에 따른 증인신문 청구를 신청하는 경우에는 별지 제120호서식의 증인신문 신청서에 따른다.', 337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2520, '제93조(고소사건 등에 대한 주의사항) 특별사법경찰관은 고소사건의 경우에는 고소한 사람에게 고소권이 있는지 여부를, 친고죄의 경우에는 법 제230조에 따른 고소기간을 지났는지 여부를, 피해자의 명시한 의사에 반하여 죄를 논할 수 없는 사건의 경우에는 처벌을 희망하는지 여부를 각각 조사해야 한다.', 338);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2521, '제94조(고소의 대리) 특별사법경찰관은 법 제236조에 따라 대리인이 고소를 하거나 고소를 취소하려는 경우에는 고소권자의 위임장을 제출받아야 한다.', 338);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2522, '제95조(고소사건의 수사기간)', 338);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2523, '제96조(고소 등의 취소)', 338);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2524, '제97조(소년사건수사의 기본원칙) 소년사건을 수사하는 경우에는 보호처분 또는 형사처분에 대한 특별한 심리자료를 제공하기 위한 것이라는 점에 유의해야 하며, 소년의 건전한 성장을 도모하는 자세로 수사해야 한다.', 339);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2525, '제98조(소년의 특성 고려) 소년사건을 수사하는 경우에는 소년의 특성에 비추어 되도록 다른 사람의 관심을 끌지 않는 조용한 장소에서 온정과 이해를 가지고 부드러운 말투로 조사해야 하며, 그 소년의 심정을 충분히 배려해야 한다.', 339);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2526, '제99조(범죄의 원인 등과 환경조사)', 339);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2527, '제100조(구속에 관한 주의) 소년을 구속하는 것은 되도록 피해야 하며, 소년을 구속 또는 동행하는 경우에도 그 시기와 방법에 관하여 특히 주의를 해야 한다.', 339);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2528, '제101조(보도상의 주의) 소년의 주거ㆍ성명ㆍ연령ㆍ직업ㆍ용모 등에 의하여 본인을 알 수 있는 정도의 사실이나 사진이 보도되지 않도록 특히 주의해야 한다.', 339);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2529, '제102조(장애인에 대한 조사)', 339);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2530, '제103조(외국인에 대한 통역) 특별사법경찰관은 외국인을 조사하는 경우에는 당사자가 이해할 수 있는 언어로 통역해 주어야 한다.', 339);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2531, '제104조(외국 영사관원과의 접견ㆍ통신)', 339);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2532, '제105조(수사서류의 작성) 특별사법경찰관리는 수사서류를 작성할 때에는 내용의 정확성과 진술의 임의성을 확보하기 위해 특히 다음 사항을 유의해야 한다.', 340);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2533, '제106조(외국어로 된 서면) 특별사법경찰관은 외국어로 작성된 서류에는 번역문을 첨부해야 한다.', 340);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2534, '제107조(범죄수익 몰수ㆍ부대보전ㆍ추징보전 신청)', 341);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2535, '제108조(마약류범죄 수사 관련 입국ㆍ상륙 절차 특례 등의 신청)', 341);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2536, '제109조(사건송치)', 342);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2537, '제110조(송치 전 지휘 등)', 342);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2538, '제111조(송치서류)', 342);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2539, '제112조(영상녹화물의 송부)', 342);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2540, '제113조(의견서 작성) 특별사법경찰관은 의견서를 작성하는 경우에는 별지 제136호서식에 따라 직접 작성해야 한다.', 342);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2541, '제114조(참고인 등의 소재수사)', 342);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2542, '제115조(추가 송부) 특별사법경찰관은 사건송치 후에 서류 또는 물건을 추가로 송부하는 경우에는 별지 제138호서식의 추가 송부서를 첨부해야 한다.', 342);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2543, '제116조(송치 후의 수사 등)', 342);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2544, '제117조(기소중지ㆍ참고인중지 처분된 자에 대한 수사)', 342);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2545, '제118조(수사촉탁)', 342);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2546, '제119조(행정고발사건의 수사기관) 특별사법경찰관리가 소속된 행정기관의 장이 고발한 사건은 해당 기관의 특별사법경찰관이 검사의 지휘를 받아 수사함을 원칙으로 한다. 다만, 검사가 직접 또는 다른 기관에서 수사함이 상당하다고 판단한 경우에는 해당 기관의 특별사법경찰관이 수사하지 않는다.', 342);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2547, '제120조(범죄사건부 등)', 342);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2548, '제121조(증언 준비) 특별사법경찰관리는 그 직무와 관련한 형사재판에서 증언하는 경우에는 공판에 관여하는 검사와 면담하는 등 사전에 필요한 준비를 해야 한다.', 342);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2549, '제122조(장부와 비치서류)', 343);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2550, '제123조(장부와 비치서류의 전자화)', 343);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2551, '제124조(수사관계예규철) 제122조제1항제1호의 수사관계예규철에는 검찰청이나 그 밖의 감독관청이 발령한 훈령ㆍ통첩ㆍ지령 등 관계 서류를 편철해야 한다.', 343);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2552, '제125조(수사종결사건철) 제122조제1항제2호의 수사종결사건(송치사건)철에는 검사에게 송치한 사건송치서, 기록목록 및 의견서의 사본을 편철해야 한다.', 343);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2553, '제126조(내사종결사건철) 제122조제1항제3호의 내사종결사건철에는 범죄를 내사한 결과 입건의 필요가 없다고 인정되어 완결된 기록을 편철해야 한다.', 343);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2554, '제127조(수사미제사건기록철) 제122조제1항제5호의 수사미제사건기록철에는 장차 검거할 가망이 없는 피해신고 사건 등의 기록을 편철해야 한다.', 343);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2555, '제128조(통계철) 제122조제1항제6호의 통계철에는 특별사법경찰업무에 관한 각종 통계서류를 편철해야 한다.', 343);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2556, '제129조(처분결과통지서철) 제122조제1항제7호의 처분결과통지서철에는 검사의 기소ㆍ불기소(기소유예, 혐의없음, 공소권없음, 죄가안됨, 각하)ㆍ기소중지ㆍ참고인중지ㆍ이송 등 결정과 각급 심의 재판결과에 관한 통지서를 편철해야 한다.', 343);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2557, '제130조(잡서류철) 제122조제1항제9호의 잡서류철에는 같은 항 제1호부터 제8호까지의 규정에 따른 서류철에 편철되지 않는 모든 서류를 편철해야 한다.', 343);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2558, '제131조(서류철의 색인목록)', 343);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2559, '제132조(임의장부 등) 특별사법경찰관은 필요하다고 인정할 때에는 제122조제1항 각 호의 장부와 서류 외에 필요한 장부나 서류철을 비치할 수 있다.', 343);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2560, '제133조(장부 등의 갱신)', 343);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2561, '제134조(장부와 서류의 보존기간) 제122조제1항 각 호의 장부와 서류는 다음 각 호의 구분에 따른 기간 동안 보존해야 한다.', 343);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2562, '제135조(보존기간의 기산 등)', 343);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2563, '제1조(목적) 이 규칙은 해양경찰청 소속 경찰공무원인 사법경찰관리가 「형사소송법」 및 「검사와 사법경찰관의 상호협력과 일반적 수사준칙에 관한 규정」 등 수사 관계 법령에 따라 수사를 하는 데 필요한 사항을 규정함을 목적으로 한다.', 344);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2564, '제2조(인권 보호 및 적법절차의 준수)', 344);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2565, '제3조(협력의 방식 등)', 345);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2566, '제4조(중요사건 협력절차)', 345);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2567, '제5조(소재수사에 관한 협력)', 345);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2568, '제6조(시찰조회 요청에 관한 협력)', 345);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2569, '제7조(검사와의 협의 등)', 345);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2570, '제8조(사법경찰관리의 상호협력)', 345);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2571, '제9조(접수 전 점검 및 조치)', 347);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2572, '제10조(회피) 사법경찰관리는 수사준칙 제11조에 따라 수사를 회피하려는 경우에는 별지 제8호서식의 회피신청서를 소속해양경찰관서장에게 제출해야 한다.', 347);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2573, '제11조(수사 진행상황의 통지)', 347);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2574, '제12조(변호인의 피의자신문 참여)', 347);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2575, '제13조(신문 중 변호인 참여 제한)', 347);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2576, '제14조(사건관계인에 대한 적용) 사건관계인에 대한 조사ㆍ면담 시 변호인의 참여에 관하여는 제12조 및 제13조를 준용한다.', 347);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2577, '제15조(직무 관할) 사법경찰관리는 소속된 해양경찰관서의 관할구역에서 직무를 수행한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 관할구역이 아닌 곳에서도 그 직무를 수행할 수 있다.', 347);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2578, '제16조(사건의 단위) 법 제11조에 따른 관련사건은 1건으로 처리한다. 다만, 분리수사를 하는 경우에는 그렇지 않다.', 347);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2579, '제17조(심사관)', 347);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2580, '제18조(수사의 개시)', 348);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2581, '제19조(입건 전 조사)', 348);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2582, '제20조(불입건 결정 통지)', 348);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2583, '제21조(고소ㆍ고발의 수리)', 348);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2584, '제22조(고소인ㆍ고발인 진술조서 등)', 348);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2585, '제23조(고소의 대리 등)', 348);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2586, '제24조(고소ㆍ고발사건의 수사기간)', 348);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2587, '제25조(고소ㆍ고발 취소 등에 따른 조치)', 348);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2588, '제26조(변사사건 발생사실 통보)', 348);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2589, '제27조(변사자의 검시ㆍ검증)', 348);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2590, '제28조(검시ㆍ검증조서 등)', 348);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2591, '제29조(검시의 주의사항) 사법경찰관리는 검시할 때에는 다음 각 호의 사항에 주의해야 한다.', 348);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2592, '제30조(검시와 참여자) 사법경찰관리는 검시에 특별한 지장이 없다고 인정하면 변사자의 가족ㆍ친족, 이웃사람ㆍ친구, 시ㆍ군ㆍ구ㆍ읍ㆍ면ㆍ동의 공무원이나 그 밖에 필요하다고 인정하는 사람을 검시에 참여시켜야 한다.', 348);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2593, '제31조(사체의 인도)', 348);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2594, '제32조(검사 이송 사건의 처리) 사법경찰관은 수사준칙 제18조에 따라 검사로부터 사건을 이송받은 경우에는 지체 없이 접수하여 처리한다.', 348);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2595, '제33조(고위공직자범죄등 인지 통보) 사법경찰관은 「고위공직자범죄수사처 설치 및 운영에 관한 법률」 제24조제2항에 따라 고위공직자범죄등 인지 사실을 통보하는 경우에는 별지 제19호서식의 고위공직자범죄등 인지통보서에 따른다.', 348);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2596, '제34조(출석요구) 수사준칙 제19조제3항 본문 또는 같은 조 제6항에 따라 피의자 또는 피의자 외의 사람에게 출석요구를 하려는 경우에는 별지 제20호서식 또는 별지 제21호서식의 출석요구서에 따른다.', 350);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2597, '제35조(수사상 임의동행) 사법경찰관리는 수사준칙 제20조에 따른 임의동행 고지를 하고 임의동행한 경우에는 별지 제22호서식의 임의동행 동의서를 작성하여 사건기록에 편철하거나 별도로 보관해야 한다.', 350);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2598, '제36조(심야조사 제한)', 350);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2599, '제37조(장시간 조사 제한) 사법경찰관리는 피의자나 사건관계인으로부터 수사준칙 제22조제1항제1호에 따라 조서 열람을 위한 조사 연장을 요청받은 경우에는 별지 제23호서식의 조사연장 요청서를 제출받아야 한다.', 350);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2600, '제38조(신뢰관계인 동석)', 350);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2601, '제39조(조서와 진술서)', 350);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2602, '제40조(수사과정의 기록) 사법경찰관리는 수사준칙 제26조제1항에 따라 조사 과정의 진행경과를 별도의 서면에 기록하는 경우에는 별지 제30호서식 또는 별지 제31호서식의 수사 과정 확인서에 따른다.', 350);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2603, '제41조(실황조사)', 350);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2604, '제42조(감정의 위촉) 사법경찰관은 법 제221조제2항에 따라 감정을 위촉하는 경우에는 별지 제33호서식의 감정위촉서에 따른다. 법 제221조의4에 따라 감정에 필요한 허가장을 발부받아 위촉하는 경우에도 또한 같다.', 350);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2605, '제43조(영상녹화)', 351);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2606, '제44조(영상녹화물의 제작 및 보관)', 351);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2607, '제45조(지명수배)', 352);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2608, '제46조(지명수배자 발견 시 조치)', 352);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2609, '제47조(지명통보) 사법경찰관리는 다음 각 호의 어느 하나에 해당하는 사람의 소재를 알 수 없을 때에는 지명통보를 할 수 있다.', 352);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2610, '제48조(지명통보자 발견 시 조치) 사법경찰관리는 제47조에 따라 지명통보된 사람(이하 "지명통보자"라 한다)을 발견한 때에는 지명통보자에게 지명통보된 사실, 범죄사실의 요지 및 지명통보한 해양경찰관서(이하 이 조 및 제49조에서 "통보관서"라 한다)를 고지하고, 발견된 날부터 1개월 이내에 통보관서에 출석해야 한다는 내용과 정당한 사유 없이 출석하지 않을 경우 지명수배되어 체포될 수 있다는 내용을 통지해야 한다.', 352);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2611, '제49조(지명수배ㆍ지명통보 해제) 사법경찰관리는 다음 각 호의 어느 하나에 해당하는 경우에는 즉시 지명수배 또는 지명통보를 해제해야 한다.', 352);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2612, '제50조(체포영장의 신청) 사법경찰관은 법 제200조의2제1항에 따라 체포영장을 신청하는 경우에는 별지 제36호서식의 체포영장 신청서에 따른다. 이 경우 현재 수사 중인 다른 범죄사실에 관하여 그 피의자에 대해 발부된 유효한 체포영장이 있는지를 확인해야 하며 해당사항이 있는 경우에는 그 사실을 체포영장 신청서에 적어야 한다.', 354);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2613, '제51조(긴급체포)', 354);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2614, '제52조(현행범인 체포 및 인수)', 354);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2615, '제53조(현행범인 석방)', 354);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2616, '제54조(구속영장의 신청) 수사준칙 제29조에 따른 구속영장 신청서는 별지 제44호서식부터 별지 제47호서식까지에 따른다.', 354);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2617, '제55조(체포ㆍ구속영장의 집행)', 354);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2618, '제56조(호송)', 354);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2619, '제57조(체포ㆍ구속 통지 등) 사법경찰관은 수사준칙 제33조제1항(같은 조 제3항에서 준용하는 경우를 포함한다)에 따라 체포ㆍ구속의 통지를 하는 경우에는 별지 제48호서식의 체포ㆍ긴급체포ㆍ현행범인체포ㆍ구속 통지서에 따른다.', 354);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2620, '제58조(체포ㆍ구속영장의 반환) 수사준칙 제35조제2항에 따른 영장반환서는 별지 제49호서식에 따른다.', 354);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2621, '제59조(피의자 접견 등 금지)', 354);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2622, '제60조(피의자 석방 및 통보)', 354);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2623, '제61조(구속의 취소)', 354);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2624, '제62조(구속의 집행정지)', 354);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2625, '제63조(압수ㆍ수색 또는 검증영장의 신청 등)', 355);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2626, '제64조(압수조서 등)', 355);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2627, '제65조(수색조서 및 수색증명서)', 355);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2628, '제66조(압수물의 환부 및 가환부)', 355);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2629, '제67조(압수물 보관)', 355);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2630, '제68조(압수물 폐기)', 355);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2631, '제69조(압수물 대가보관)', 355);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2632, '제70조(검증조서) 수사준칙 제43조에 따른 검증조서는 별지 제16호서식에 따른다.', 355);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2633, '제71조(증거보전 신청) 사법경찰관은 미리 증거를 보전하지 않으면 그 증거를 사용하기 곤란한 경우에는 별지 제81호서식의 증거보전 신청서를 작성하여 검사에게 법 제184조제1항에 따른 증거보전의 청구를 신청할 수 있다.', 356);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2634, '제72조(증인신문 신청) 사법경찰관은 범죄의 수사에 없어서는 안 되는 사실을 안다고 명백히 인정되는 사람이 출석 또는 진술을 거부하는 경우에는 별지 제82호서식의 증인신문 신청서를 작성하여 검사에게 법 제221조의2제1항에 따른 증인신문의 청구를 신청할 수 있다.', 356);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2635, '제73조(감정유치 및 감정처분허가 신청)', 356);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2636, '제74조(영장심의위원회) 사법경찰관은 법 제221조의5제1항에 따라 영장 청구 여부에 대한 심의를 신청하는 경우에는 「영장심의위원회 규칙」 제13조에 따라 관할 고등검찰청에 심의신청을 해야 한다.', 356);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2637, '제75조(시정조치요구의 이행)', 357);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2638, '제76조(징계요구 처리 결과 등 통보) 소속해양경찰관서장은 수사준칙 제46조제2항에 따라 징계요구의 처리 결과와 그 이유를 통보하는 경우에는 별지 제87호서식의 징계요구 처리결과 통보서에 따른다.', 357);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2639, '제77조(구제신청 고지의 확인) 수사준칙 제47조에 따른 고지 확인서는 별지 제88호서식에 따른다.', 357);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2640, '제78조(수사의 경합 시 기록 열람)', 358);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2641, '제79조(피해자 보호의 원칙)', 359);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2642, '제80조(신변보호)', 359);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2643, '제81조(피해자에 대한 정보 제공) 사법경찰관리는 피해자를 조사하는 경우 다음 각 호의 정보를 피해자에게 제공해야 한다. 다만, 피해자에 대한 조사를 하지 않는 경우에는 수사준칙 제51조제1항에 따른 결정(이송 결정은 제외한다)을 하기 전까지 정보를 제공해야 한다.', 359);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2644, '제82조(회복적 대화)', 359);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2645, '제83조(범죄피해의 평가) 사법경찰관리는 피해자의 피해 정도를 파악하고 보호ㆍ지원의 필요성을 판단하기 위해 범죄피해평가를 실시할 수 있으며, 일정한 자격을 갖춘 단체 또는 개인에게 이를 의뢰할 수 있다.', 359);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2646, '제84조(문서의 서식) 이 규칙에서 정한 서식 외에 단순하고 정형적인 사건의 수사 등에 사용하는 서식은 해양경찰청장이 정한다.', 360);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2647, '제85조(장부와 비치서류)', 360);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2648, '제86조(범죄통계원표) 사법경찰관리는 범죄를 수사한 경우에는 형사사법정보시스템을 이용하여 사건마다 범죄통계원표를 작성한다.', 360);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2649, '제87조(수사서류 열람ㆍ복사)', 360);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2650, '제88조(혼획ㆍ좌초ㆍ표류된 고래류의 처리)', 362);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2651, '제89조(보호대상 고래류의 통보) 사법경찰관은 혼획ㆍ좌초 또는 표류로 신고된 고래류가 「야생생물 보호 및 관리에 관한 법률」 제2조제3호에 따른 국제적 멸종위기종 또는 「해양생태계의 보전 및 관리에 관한 법률」 제2조제11호에 따른 해양보호생물로 확인되거나 의심되는 경우에는 그 사실을 각각 환경부장관 또는 해양수산부장관에게 즉시 통보해야 한다.', 362);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2652, '제90조(소년에 대한 조사)', 363);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2653, '제91조(장애인에 대한 조사) 사법경찰관리는 청각장애인 및 언어장애인이나 그 밖에 의사소통이 어려운 장애인을 조사하는 경우에는 직권으로 또는 장애인 본인, 보호자, 법정대리인 등의 신청에 따라 수화ㆍ문자통역을 제공하거나 의사소통을 도울 수 있는 사람을 참여시켜야 한다.', 363);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2654, '제92조(외국인에 대한 조사)', 363);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2655, '제93조(국제법의 준수) 사법경찰관리는 외국인 관련 범죄, 우리나라 국민의 국외범, 대사관ㆍ공사관에 관한 범죄 및 그 밖에 외국에 관한 범죄의 수사를 할 때에는 조약과 그 밖의 국제법에 위배되는 일이 없도록 유의해야 한다.', 363);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2656, '제94조(한미행정협정사건의 통보)', 363);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2657, '제95조(몰수ㆍ부대보전 신청) 사법경찰관은 관계 법령에 따라 검사에게 몰수ㆍ부대보전을 신청하는 경우에는 별지 제94호서식의 몰수ㆍ부대보전 신청서에 따른다.', 364);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2658, '제96조(추징보전의 신청)', 364);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2659, '제97조(장기사건 수사종결)', 366);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2660, '제98조(사건 이송)', 366);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2661, '제99조(수사 결과의 통지)', 366);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2662, '제100조(수사중지 결정)', 367);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2663, '제101조(소재수사 등)', 367);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2664, '제102조(수사중지 시 지명수배ㆍ지명통보) 사법경찰관은 피의자의 소재불명을 이유로 수사중지 결정을 하려는 경우에는 지명수배 또는 지명통보를 해야 한다.', 367);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2665, '제103조(수사중지 결정에 대한 이의제기 절차)', 367);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2666, '제104조(수사중지사건 수사재개)', 367);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2667, '제105조(송치 서류)', 368);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2668, '제106조(추가송부) 수사준칙 제58조제3항에 따른 추가송부서는 별지 제116호서식에 따른다.', 368);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2669, '제107조(보완수사요구의 결과 통보 등)', 368);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2670, '제108조(직무배제 또는 징계 요구의 처리 등)', 368);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2671, '제109조(법원송치)', 368);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2672, '제110조(불송치 결정)', 369);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2673, '제111조(불송치 서류)', 369);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2674, '제112조(일부 결정 시 조치 등)', 369);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2675, '제113조(혐의없음 결정 시의 유의사항) 사법경찰관은 고소 또는 고발 사건에 관하여 제110조제1항제1호의 혐의없음 결정을 하는 경우에는 고소인 또는 고발인의 무고혐의의 유무를 판단해야 한다.', 369);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2676, '제114조(재수사 결과의 처리)', 369);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2677, '제115조(고소인등의 이의신청)', 369);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2678, '제1조(목적) 이 법은 보호소년 등의 처우 및 교정교육과 소년원과 소년분류심사원의 조직, 기능 및 운영에 관하여 필요한 사항을 규정함을 목적으로 한다.', 370);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2679, '제1조의2(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다.', 370);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2680, '제2조(처우의 기본원칙)', 370);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2681, '제3조(임무)', 370);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2682, '제4조(관장 및 조직)', 370);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2683, '제5조(소년원의 분류 등)', 370);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2684, '제6조(소년원 등의 규모 등)', 370);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2685, '제7조(수용절차)', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2686, '제8조(분류처우)', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2687, '제8조의2 삭제 <2016.3.29>', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2688, '제9조(보호처분의 변경 등)', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2689, '제10조(원장의 면접) 원장은 보호소년등으로부터 처우나 일신상의 사정에 관한 의견을 듣기 위하여 수시로 보호소년등과 면접을 하여야 한다.', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2690, '제11조(청원) 보호소년등은 그 처우에 대하여 불복할 때에는 법무부장관에게 문서로 청원할 수 있다.', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2691, '제12조(이송)', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2692, '제13조(비상사태 등의 대비)', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2693, '제14조(사고 방지 등)', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2694, '제14조의2(보호장비의 사용)', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2695, '제14조의3(전자장비의 설치ㆍ운영)', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2696, '제14조의4(규율 위반 행위) 보호소년등은 다음 각 호의 행위를 하여서는 아니 된다.', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2697, '제15조(징계)', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2698, '제15조의2(보호소년등처우ㆍ징계위원회)', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2699, '제16조(포상)', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2700, '제17조(급여품 등)', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2701, '제18조(면회ㆍ편지ㆍ전화통화)', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2702, '제19조(외출) 소년원장은 보호소년에게 다음 각 호의 어느 하나에 해당하는 사유가 있을 때에는 본인이나 보호자등의 신청에 따라 또는 직권으로 외출을 허가할 수 있다. <개정 2013.7.30>', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2703, '제20조(환자의 치료)', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2704, '제20조의2(진료기록부 등의 관리)', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2705, '제20조의3(출원생의 외래진료)', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2706, '제21조(감염병의 예방과 응급조치)', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2707, '제22조(금품의 보관 및 반환)', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2708, '제23조(친권 또는 후견) 원장은 미성년자인 보호소년등이 친권자나 후견인이 없거나 있어도 그 권리를 행사할 수 없을 때에는 법원의 허가를 받아 그 보호소년등을 위하여 친권자나 후견인의 직무를 행사할 수 있다.', 371);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2709, '제24조(분류심사)', 372);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2710, '제25조(분류심사관)', 372);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2711, '제26조(청소년심리검사 등) 소년분류심사원장은 「청소년기본법」 제3조제1호에 따른 청소년이나 그 보호자가 적성검사 등 진로탐색을 위한 청소년심리검사 또는 상담을 의뢰하면 이를 할 수 있다. 이 경우에는 법무부장관이 정하는 바에 따라 실비를 받을 수 있다.', 372);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2712, '제27조(분류심사 결과 등의 통지)', 372);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2713, '제28조(교정교육의 원칙) 소년원의 교정교육은 규율있는 생활 속에서 초ㆍ중등교육, 직업능력개발훈련, 인성교육, 심신의 보호ㆍ지도 등을 통하여 보호소년이 전인적인 성장ㆍ발달을 이루고 사회생활에 원만하게 적응할 수 있도록 하여야 한다.', 373);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2714, '제29조(학교의 설치ㆍ운영) 법무부장관은 대통령령으로 정하는 바에 따라 소년원에 「초ㆍ중등교육법」 제2조제1호부터 제4호까지의 학교(이하 "소년원학교"라 한다)를 설치ㆍ운영할 수 있다. <개정 2016.3.29>', 373);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2715, '제29조의2(「초ㆍ중등교육법」에 관한 특례)', 373);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2716, '제29조의3(「학교폭력예방 및 대책에 관한 법률」에 관한 특례) 소년원학교에 대해서는 「학교폭력예방 및 대책에 관한 법률」 제12조부터 제16조까지, 제16조의2, 제17조, 제17조의2 및 제18조부터 제20조까지의 규정을 적용하지 아니한다.', 373);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2717, '제30조(교원 등)', 373);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2718, '제31조(학적관리)', 373);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2719, '제32조(다른 학교로의 전학ㆍ편입학) 보호소년이 소년원학교에서 교육과정을 밟는 중에 소년원에서 퇴원하거나 임시퇴원하여 전적학교 등 다른 학교에 전학이나 편입학을 신청하는 경우 전적학교 등 다른 학교의 장은 정당한 사유를 제시하지 아니하는 한 이를 허가하여야 한다.', 373);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2720, '제33조(통학) 소년원장은 교정성적이 양호한 보호소년의 원활한 학업 연계를 위하여 필요하다고 판단되면 보호소년을 전적학교 등 다른 학교로 통학하게 할 수 있다.', 373);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2721, '제34조(전적학교의 졸업장 수여)', 373);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2722, '제35조(직업능력개발훈련)', 373);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2723, '제36조(직업능력개발훈련교사) 직업능력개발훈련을 실시하는 소년원에는 「국민 평생 직업능력 개발법」으로 정한 자격을 갖춘 직업능력개발훈련교사를 둔다. <개정 2021.8.17>', 373);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2724, '제37조(통근취업)', 373);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2725, '제38조(안전관리)', 373);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2726, '제39조(생활지도) 원장은 보호소년등의 자율성을 높이고 각자가 당면한 문제를 스스로 해결하여 사회생활에 적응할 수 있는 능력을 기르도록 생활지도를 하여야 한다.', 373);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2727, '제40조(특별활동) 소년원장은 보호소년의 취미와 특기를 신장하고 집단생활의 경험을 통하여 민주적이고 협동적인 생활태도를 기르도록 특별활동지도를 하여야 한다.', 373);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2728, '제41조(교육계획 등)', 373);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2729, '제42조(장학지도) 법무부장관은 교정교육 성과를 평가하고 개선하기 위하여 소속 공무원으로 하여금 장학지도를 하게 할 수 있다.', 373);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2730, '제42조의2(대안교육 및 비행예방 등)', 373);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2731, '제42조의3(보호자교육)', 373);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2732, '제43조(퇴원)', 374);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2733, '제44조(임시퇴원) 소년원장은 교정성적이 양호한 자 중 보호관찰의 필요성이 있다고 인정되는 보호소년(「소년법」 제32조제1항제8호에 따라 송치된 보호소년은 제외한다)에 대하여는 「보호관찰 등에 관한 법률」 제22조제1항에 따라 보호관찰심사위원회에 임시퇴원을 신청하여야 한다. <개정 2016.3.29>', 374);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2734, '제44조의2(보호소년의 출원) 소년원장은 제43조제3항 및 제44조의 신청에 대하여 「보호관찰 등에 관한 법률」 제25조에 따른 법무부장관의 퇴원ㆍ임시퇴원 허가를 통보받으면 해당 허가서에 기재되어 있는 출원예정일에 해당 보호소년을 출원시켜야 한다. 다만, 제46조에 따라 계속 수용하는 경우(제45조제3항의 경우를 포함한다)에는 그러하지 아니하다.', 374);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2735, '제45조(보호소년의 인도)', 374);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2736, '제45조의2(사회정착지원)', 374);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2737, '제46조(퇴원자 또는 임시퇴원자의 계속 수용)', 374);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2738, '제47조(물품 또는 귀가여비의 지급) 소년원장은 보호소년이 퇴원허가 또는 임시퇴원허가를 받거나 「소년법」 제37조제1항에 따라 처분변경 결정을 받았을 때에는 필요한 경우 물품 또는 귀가여비를 지급할 수 있다.', 374);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2739, '제48조(임시퇴원 취소자의 재수용)', 374);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2740, '제49조(방문 허가 등)', 375);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2741, '제50조(협조 요청)', 375);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2742, '제50조의2(청소년심리상담실)', 375);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2743, '제51조(소년보호협회)', 375);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2744, '제51조의2(소년보호위원)', 375);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2745, '제52조(소년분류심사원이 설치되지 아니한 지역에서의 소년분류심사원의 임무수행) 소년분류심사원이 설치되지 아니한 지역에서는 소년분류심사원이 설치될 때까지 소년분류심사원의 임무는 소년원이 수행하고, 위탁소년 및 유치소년은 소년원의 구획된 장소에 수용한다. <개정 2013.7.30>', 375);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2746, '제53조(기부금품의 접수)', 375);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2747, '제54조(범죄경력자료 등의 조회 요청)', 375);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2748, '제1조(목적) 이 영은 「보호소년 등의 처우에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 376);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2749, '제2조(보호소년의 처우) 소년원장은 「보호소년 등의 처우에 관한 법률」(이하 "법"이라 한다) 제2조제2항에 따라 교육활동에 지장을 주지 않는 범위에서 보호소년에게 다음 각 호에 해당하는 향상된 처우를 할 수 있다. <개정 2021.4.20>', 376);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2750, '제3조(소년원의 기능별 분류ㆍ운영)', 376);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2751, '제4조 삭제 <2008.6.20>', 376);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2752, '제5조', 376);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2753, '제5조의2(생활실 수용정원) 법 제6조제2항에 따라 소년원 또는 소년분류심사원(이하 "소년원등"이라 한다)에 두는 생활실의 수용정원은 4명 이하로 한다. 다만, 소년원등의 기능ㆍ위치나 그 밖의 사정을 고려하여 수용인원을 증대할 수 있다. <개정 2021.4.20>', 376);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2754, '제6조(보호소년등의 인수)', 378);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2755, '제7조 삭제 <2008.6.20>', 378);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2756, '제8조(수용사실 통지) 원장은 법 제7조제3항에 따라 보호소년등의 보호자 또는 보호소년등이 지정하는 사람(이하 "보호자등"이라 한다)에게 보호소년등을 수용한 사실을 알릴 때에는 수용 경위, 처우의 개요, 면회ㆍ통신 방법, 그 밖에 필요한 사항을 함께 알려야 한다.', 378);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2757, '제9조(분류처우)', 378);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2758, '제10조(개별처우계획의 수립)', 378);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2759, '제11조(개별처우계획의 수정) 소년원장은 제10조제1항에 따라 수립한 보호소년의 개별처우계획을 변경할 필요가 있는 경우에는 지체 없이 처우ㆍ징계위원회의 심사를 거쳐 수정해야 한다. <개정 2021.4.20>', 378);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2760, '제12조(보호처분 취소대상자 통지) 원장은 보호소년등이 법원소년부의 보호처분 결정 당시 10세 미만(「소년법」 제32조제1항제10호 처분의 경우에는 12세 미만으로 한다)이었거나 19세 이상이었던 것으로 밝혀지면 지체 없이 해당 보호처분 결정을 한 법원소년부에 그 사실을 통지하여야 한다.', 378);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2761, '제13조(청원의 편의 제공)', 379);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2762, '제14조(수용인원의 조절을 위한 이송) 법무부장관은 분류수용이나 교육훈련을 위하여 수용인원을 조절할 필요가 있다고 인정되면 소년원장에게 보호소년을 다른 소년원으로 이송(移送)할 것을 지시할 수 있다.', 379);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2763, '제15조(청원에 따른 이송) 소년원장은 보호소년 또는 그 보호자등이 다른 소년원으로 이송해 줄 것을 청원한 경우에는 법무부장관의 허가를 받아 보호소년을 그 소년원으로 이송할 수 있다.', 379);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2764, '제16조(이송의 제한)', 379);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2765, '제17조(비상사태 등의 대비) 원장은 법 제13조에 따른 비상사태 등에 대비하여 소년원등 안에 대피시설을 마련해야 한다. <개정 2021.4.20>', 380);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2766, '제17조의2(소지금지물품) 보호소년등은 다음 각 호의 물품을 소지해서는 아니 된다.', 380);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2767, '제17조의3(신체 검사 등)', 380);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2768, '제18조(외부인의 출입통제)', 380);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2769, '제19조(심신안정실에의 수용)', 380);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2770, '제20조(사고발생 보고)', 380);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2771, '제21조(사체의 검사) 원장은 보호소년등이 사망한 경우에는 지체 없이 검사의 지휘에 따라 사체의 검사 등 필요한 조치를 하여야 한다.', 380);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2772, '제22조(사망 통지 및 사체의 인도) 원장은 보호소년등이 사망하면 지체 없이 병명, 사망 원인 및 사망 일시를 보호자등에게 알리고, 검사의 지휘에 따라 사체를 인도하여야 한다.', 380);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2773, '제23조(사체의 임시매장) 원장은 보호자등의 소재를 알 수 없거나 그 밖의 부득이한 사유로 제22조에 따라 사체를 인도할 수 없을 때에는 임시매장을 하고, 임시매장한 장소에 사망자의 성명, 생년월일 및 사망연월일을 새긴 표지를 세워야 한다. <개정 2015.12.30, 2021.1.5>', 380);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2774, '제23조의2 삭제 <2016.9.5>', 381);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2775, '제24조(징계)', 381);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2776, '제24조의2(징계대상행위의 조사)', 381);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2777, '제25조 삭제 <2016.9.5>', 381);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2778, '제26조(지정된 실내의 구조) 법 제15조제1항제7호에 따른 지정된 실내는 면적ㆍ채광ㆍ통풍ㆍ온도ㆍ습도 등이 보호소년등의 건강을 보호할 수 있도록 적절하여야 한다. <개정 2016.9.5>', 381);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2779, '제27조(징계 중의 지도)', 381);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2780, '제28조(이송 중의 규율위반자에 대한 징계) 보호소년이 이송 중에 규율을 위반한 경우 그 징계는 인수한 소년원장이 한다.', 381);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2781, '제29조(징계자의 처우 제한) 원장은 법 제15조에 따라 징계처분을 받은 보호소년등에 대하여 징계기간 중 교육활동의 일부를 제한할 수 있다.', 381);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2782, '제30조(징계집행의 유예ㆍ정지ㆍ면제) 원장은 정상을 특별히 참작할 사유가 있거나 환자인 경우에는 징계 집행을 면제하거나 사유가 없어질 때까지 징계 집행을 유예하거나 정지할 수 있다.', 381);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2783, '제30조의2(처우ㆍ징계위원회의 심의ㆍ의결사항) 처우ㆍ징계위원회는 법 제15조의2제1항에 따라 다음 각 호의 사항을 심의ㆍ의결한다.', 381);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2784, '제30조의3(처우ㆍ징계위원회의 구성)', 381);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2785, '제30조의4(위원의 제척ㆍ기피ㆍ회피)', 381);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2786, '제30조의5(처우ㆍ징계위원회의 위원장)', 381);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2787, '제30조의6(처우ㆍ징계위원회의 회의)', 381);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2788, '제30조의7(위원의 해촉) 위원장은 제30조의3제2항에 따라 위촉된 위원이 다음 각 호의 어느 하나에 해당하면 그 위원을 해촉(解觸)할 수 있다.', 381);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2789, '제30조의8(간사)', 381);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2790, '제30조의9(회의록의 작성 및 보관)', 381);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2791, '제30조의10(운영세칙) 이 영에서 규정한 것 외에 처우ㆍ징계위원회의 운영에 필요한 사항은 처우ㆍ징계위원회의 의결을 거쳐 위원장이 정한다.', 381);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2792, '제31조(포상)', 381);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2793, '제32조(특별급식) 원장은 국경일이나 그 밖에 필요하다고 인정할 때에는 보호소년등에게 특별급식을 할 수 있다.', 382);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2794, '제33조(음식물 등의 반입 허가)', 382);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2795, '제34조(금전 사용금지) 보호소년등은 통학, 통근취업 등 원장이 특히 필요하다고 인정하여 허가하는 경우가 아니면 금전을 소지하거나 직접 사용할 수 없다.', 382);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2796, '제35조 삭제 <2014.1.28>', 382);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2797, '제36조(면회 시간)', 383);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2798, '제37조(면회의 참석) 법 제18조제2항에 따라 면회에 참석하는 직원은 보호소년등이 규율을 위반하거나 면회인이 보호소년등에게 나쁜 영향을 준다고 인정되는 때에는 면회를 중지시킬 수 있다.', 383);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2799, '제38조(면회허가의 제한) 원장은 보호소년등을 면회하려는 사람이 다음 각 호의 어느 하나에 해당한다고 인정되면 면회를 허가하지 않을 수 있다. <개정 2014.1.28, 2021.4.20>', 383);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2800, '제39조(편지 왕래의 제한)', 383);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2801, '제39조의2(전화통화의 제한)', 383);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2802, '제40조(외출 기간) 법 제19조에 따른 외출 기간은 7일(공휴일과 토요일을 포함한다) 이내로 한다. 다만, 특별한 사유가 있을 때에는 그 기간을 연장할 수 있다. <개정 2021.4.20>', 383);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2803, '제41조(외출 시 준수사항의 부과)', 383);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2804, '제42조(건강진단 등) 원장은 보호소년등에 대하여 법 제7조제2항에 따른 건강진단 외에 정기ㆍ수시검진을 하고 그 결과를 기록ㆍ유지하여야 한다.', 384);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2805, '제43조(외부 의료기관 의료조치)', 384);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2806, '제44조(보호자등의 간호) 원장은 보호소년등이 법 제20조제2항에 따라 외부 의료기관에서 치료를 받는 경우 그 보호자등에게 간호하게 할 수 있다.', 384);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2807, '제44조의2(간호사의 의료행위) 법 제20조제4항에서 "대통령령으로 정하는 경미한 의료행위"란 다음 각 호의 의료행위를 말한다.', 384);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2808, '제45조(감염병의 예방)', 384);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2809, '제46조(감염병 발생 보고 등) 원장은 소년원등에서 감염병이 발생하면 지체 없이 그 발생 상황을 법무부장관에게 보고하고, 「감염병의 예방 및 관리에 관한 법률」 제12조에 따라 그 소년원등이 있는 지역의 보건소장에게 즉시 신고해야 한다. <개정 2010.12.29, 2021.4.20>', 384);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2810, '제47조(금품의 보관)', 385);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2811, '제48조(보관금품의 반환 등)', 385);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2812, '제49조(물품 등의 기증)', 385);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2813, '제50조(탁송금품의 반송) 원장은 보호소년등에게 탁송(託送)된 금품을 본인이 받기를 거부하거나 처우상 본인에게 교부하는 것이 적당하지 아니하다고 인정되면 지체 없이 이를 보낸 사람에게 반송하여야 한다.', 385);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2814, '제51조(분류심사의 영역)', 386);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2815, '제52조(상담조사 등)', 386);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2816, '제53조(분류심사관의 직무 등)', 386);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2817, '제54조(청소년심리검사 등)', 386);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2818, '제55조(교육계획)', 388);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2819, '제56조(교육단계)', 388);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2820, '제57조(교정성적의 평가)', 388);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2821, '제58조(소년관리기록부)', 388);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2822, '제59조(학교의 설치ㆍ운영 등)', 389);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2823, '제60조(교감의 겸직) 소년원학교가 설치된 소년원의 교무과장은 법 제30조제3항에 따라 그 소년원학교 교감의 직무를 겸임한다.', 389);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2824, '제61조(교원 등의 직무수행)', 389);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2825, '제62조(교원의 연수)', 389);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2826, '제63조(입학 또는 편입학)', 389);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2827, '제63조의2 삭제 <2014.1.28>', 389);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2828, '제64조(학교생활기록부) 소년원학교장은 「초ㆍ중등교육법」 제25조에 따라 보호소년의 인성발달상황과 학업성취도 등을 종합적으로 관찰ㆍ평가한 학교생활기록부를 작성ㆍ관리하여야 한다.', 389);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2829, '제64조의2(학적사항 통지 및 관리)', 389);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2830, '제65조(다른 학교로의 전학ㆍ편입학) 보호소년이 법 제32조에 따른 전적학교 등 다른 학교에 전학ㆍ편입학하려는 경우에는 전학ㆍ편입학 배정원서, 그 밖의 필요한 서류를 거주지 또는 전학ㆍ편입학 예정학교의 관할교육청의 장이나 전학ㆍ편입학 예정학교의 장에게 제출하여야 한다.', 389);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2831, '제66조(통학)', 389);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2832, '제67조(졸업사정 등)', 389);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2833, '제68조(졸업증명서 등의 발급) 소년원장은 보호소년이나 그 보호자의 신청을 받으면 졸업증명서, 성적증명서, 수료증명서 등을 발급하여야 한다.', 389);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2834, '제69조(학력인정 검정고시의 응시 특례) 소년원학교에 재학 중인 보호소년 중 다음 각 호 어느 하나에 해당하는 사람은 학력인정 검정고시에 응시할 수 있다. <개정 2015.1.6, 2015.9.15>', 389);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2835, '제70조(장학 협의) 소년원학교장은 관할 교육청의 장과 소년원학교의 학사운영에 관하여 장학(<img src="http://www.law.go.kr/flDownload.do?flSeq=97087181"  alt="img97087181" >學</img>) 협의를 할 수 있으며, 관할 교육청의 장은 필요한 권고를 할 수 있다.', 389);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2836, '제71조(직업능력개발훈련 방침)', 390);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2837, '제72조(공공직업훈련시설의 설치) 법무부장관은 「국민 평생 직업능력 개발법」 제27조에 따라 소년원에 공공직업훈련시설을 설치ㆍ운영할 수 있다. <개정 2022.2.17>', 390);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2838, '제73조(지원 직업능력개발훈련) 소년원장은 법 제35조제2항에 따라 산업체의 지원을 받아 직업능력개발훈련을 실시하려면 지원산업체와 지원목적, 기간, 내용, 그 밖의 지원에 관한 사항을 포함하는 지원약정서를 작성하여야 한다.', 390);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2839, '제74조(외부시설에서의 직업능력개발훈련) 소년원장은 법 제35조제2항에 따라 보호소년을 소년원 외의 시설에 통근시키거나 위탁하여 직업능력개발훈련을 실시할 수 있다.', 390);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2840, '제75조(직업능력개발훈련교사의 훈련) 법무부장관은 직업능력개발훈련교사의 능력개발을 위하여 해당 교사에게 「국민 평생 직업능력 개발법」 제37조제2항에 따른 보수교육을 정기적으로 이수하도록 해야 한다. <개정 2021.4.20, 2022.2.17>', 390);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2841, '제76조(통근취업의 원칙)', 390);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2842, '제77조(자립기반 조성) 법무부장관은 보호소년의 직업능력 향상과 성공적 자립기반 조성을 위하여 창업보육, 지원재단 설립 및 자립생활관 운영 등 필요한 사업을 할 수 있다.', 390);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2843, '제78조(생활지도의 목표) 원장은 법 제39조에 따라 생활지도를 할 때에는 보호소년등의 심신, 행동발달 및 품행 개선에 목표를 두고 지도하여야 한다.', 391);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2844, '제79조(상담ㆍ인성교육)', 391);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2845, '제80조(특별활동)', 391);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2846, '제81조(봉사활동) 소년원장은 보호소년의 공동체의식 함양과 체험을 통한 인성교육을 위하여 다양한 봉사활동 프로그램을 운영하여야 한다.', 391);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2847, '제82조(종교활동 등)', 391);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2848, '제83조(도서실 등의 설치ㆍ운영)', 391);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2849, '제84조(장학지도) 법무부장관은 법 제42조에 따른 장학지도를 할 때에는 매 학년도마다 장학지도의 대상ㆍ방법 및 결과처리 등에 관한 세부계획을 수립하고 이를 소년원학교에 미리 통보하여야 한다.', 391);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2850, '제85조(대안교육 대상자의 출석일수 인정)', 391);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2851, '제86조(보호자교육)', 391);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2852, '제87조(퇴원ㆍ임시퇴원의 취소 및 심사신청의 철회) 소년원장은 소년원 퇴원 또는 임시퇴원이 허가되었거나 퇴원 또는 임시퇴원 심사신청 중인 보호소년에게 징계사유 등 특별한 사유가 발생하면 보호관찰심사위원회에 퇴원 또는 임시퇴원 허가의 취소를 신청하거나 퇴원ㆍ임시퇴원  심사신청을 철회할 수 있다.', 392);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2853, '제87조의2(재ㆍ퇴원증명서의 발급) 원장은 다음 각 호의 어느 하나에 해당하는 자가 소년원등에 수용된 사실 또는 수용되었다가 출원한 사실 등에 관한 증명서의 발급을 신청하는 경우에는 법무부령으로 정하는 재ㆍ퇴원증명서를 발급할 수 있다. 이 경우 재ㆍ퇴원증명서의 발급 신청 및 발급은 「민원 처리에 관한 법률」 제12조의2제2항 및 제3항에 따른 전자민원창구를 통하여 처리할 수 있다. <개정 2021.4.20, 2022.7.11>', 392);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2854, '제88조(임시퇴원 취소자의 재수용)', 392);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2855, '제89조(외국인의 방문) 원장은 법 제49조에 따라 외국인의 방문을 허가하려면 법무부장관의 승인을 받아야 한다.', 394);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2856, '제90조(각종 자료 조회)', 394);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2857, '제90조의2(민감정보 및 고유식별정보의 처리)', 394);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2858, '제91조(지부 등의 설치) 법 제51조에 따라 설치된 소년보호협회(이하 "협회"라 한다)에는 소관 사업의 원활한 추진을 위하여 그 지부 또는 지회를 둘 수 있다.', 395);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2859, '제92조(정관)', 395);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2860, '제93조(임원)', 395);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2861, '제94조(임원의 직무)', 395);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2862, '제95조(이사회)', 395);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2863, '제96조(직원의 임면) 협회의 직원은 정관으로 정하는 바에 따라 이사장이 임면한다.', 395);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2864, '제97조(협회의 자산) 협회는 다음 각 호의 재산을 그 자산으로 한다.', 395);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2865, '제98조(협회의 사업)', 395);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2866, '제99조(사업 및 회계관리)', 395);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2867, '제100조(감독)', 395);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2868, '제101조(준용규정) 협회에 관하여는 이 영에서 규정한 것을 제외하고는 「공익법인의 설립ㆍ운영에 관한 법률」 및 「민법」 중 재단법인에 관한 규정을 준용한다.', 395);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2869, '제102조(기부금품의 접수 등)', 396);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2870, '제103조(범죄경력자료 등 조회 요청의 제한 등)', 397);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2871, '제1조(목적) 이 규칙은 「보호소년 등의 처우에 관한 법률」 및 「보호소년 등의 처우에 관한 법률 시행령」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 398);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2872, '제2조 삭제 <2021.4.20>', 398);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2873, '제3조 삭제 <2021.4.20>', 398);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2874, '제4조 삭제 <2021.4.20>', 398);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2875, '제5조 삭제 <2021.4.20>', 398);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2876, '제6조 삭제 <2021.4.20>', 398);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2877, '제7조 삭제 <2008.6.20>', 398);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2878, '제8조 삭제 <2008.6.20>', 398);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2879, '제9조(보호소년등의 인수절차)', 400);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2880, '제9조의2 삭제 <2014.1.29>', 400);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2881, '제10조(수용사실 통지) 영 제8조에 따른 수용사실의 통지는 별지 제2호서식에 따른다. 다만, 보호소년등의 보호자 또는 보호소년등이 지정하는 사람(이하 "보호자등"이라 한다)이 원하는 때에는 정보통신망을 이용하여 통지할 수 있다. 이 경우 그 통지 사실을 기록ㆍ유지하여야 한다.', 400);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2882, '제11조(분류처우) 원장은 영 제9조에 따라 다음 각 호의 어느 하나에 해당하는 보호소년등은 다른 보호소년등과 생활실 및 처우과정을 달리해야 한다. 다만, 원장은 시설여건이나 교육과정 운영을 위하여 특히 필요한 경우에는 「보호소년 등의 처우에 관한 법률」(이하 "법"이라 한다)제15조의2에 따른 보호소년등처우ㆍ징계위원회(이하 "처우ㆍ징계위원회"라 한다)의 심의를 거쳐 이를 조정ㆍ운영할 수 있다. <개정 2014.1.29, 2021.4.20>', 400);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2883, '제12조(처우ㆍ징계위원회의 개별처우계획 심사) 영 제10조 및 영 제11조에 따른 처우ㆍ징계위원회의 개별처우계획 심사는 심사 사유가 발생한 날부터 10일 이내에 실시해야 한다. <개정 2021.4.20>', 400);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2884, '제13조 삭제 <2008.6.20>', 400);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2885, '제14조 삭제 <2008.6.20>', 400);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2886, '제15조 삭제 <2008.6.20>', 400);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2887, '제16조(이탈한 사람에 대한 조치)', 400);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2888, '제17조(청원의 처리절차)', 401);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2889, '제18조(여론조사) 원장은 보호소년등을 적절하게 처우하기 위하여 보호소년등을 대상으로 월 1회 이상 처우에 관한 의견을 조사하고 그 처리결과를 보호소년등에게 알려야 한다.', 401);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2890, '제19조(이송)', 401);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2891, '제20조 삭제 <2008.6.20>', 401);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2892, '제21조(의료재활처우소년의 이송)', 401);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2893, '제22조(의료재활소년원 이송절차 등)', 401);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2894, '제23조(수용사고 방지계획 등의 수립) 원장은 보호소년등의 이탈ㆍ난동ㆍ폭행ㆍ자해 그 밖의 수용사고의 방지를 위한 종합대책 및 세부적인 생활지도계획을 수립ㆍ시행하여야 한다.', 402);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2895, '제24조(보호소년등의 감호)', 402);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2896, '제24조의2(보호장비의 사용방법)', 402);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2897, '제24조의3(보호장비의 관리)', 402);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2898, '제24조의4(전자장비의 종류) 법 제14조의3에 따라 소년원 또는 소년분류심사원(이하 "소년원등"이라 한다)에 설치하여 운영할 수 있는 전자장비는 다음 각 호와 같다. <개정 2021.4.20, 2022.2.7>', 402);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2899, '제24조의5(통제실의 운영)', 402);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2900, '제24조의6(영상정보처리기기의 설치 및 운영)', 402);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2901, '제24조의7(전자감지기의 설치) 전자감지기는 소년원등의 외곽 담장, 그 밖에 보호소년등의 이탈이나 외부로부터의 침입을 방지하기 위하여 필요한 장소로서 법무부장관이 정하는 장소에 설치한다. <개정 2021.4.20>', 402);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2902, '제24조의8(전자이름표의 사용) 원장은 수용 중인 보호소년등의 안전사고 방지, 출석관리 등을 위하여 소년원등의 시설 내에서 보호소년등에게 전자이름표를 휴대하도록 할 수 있다. <개정 2021.4.20, 2022.2.7>', 402);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2903, '제24조의9(물품검색기 설치 및 사용)', 402);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2904, '제24조의10(증거수집장비의 사용) 소속공무원은 보호소년등이 사후에 증명이 필요하다고 인정되는 행위를 하거나 사후 증명이 필요한 상태에 있는 경우 보호소년등에 대하여 증거수집장비를 사용할 수 있다.', 402);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2905, '제24조의11(녹음ㆍ녹화 기록물의 관리) 원장은 전자장비로 녹음ㆍ녹화된 기록물을 「공공기록물 관리에 관한 법률」에 따라 관리하여야 한다.', 402);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2906, '제25조(소지품검사 및 시설점검)', 402);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2907, '제26조(행동관찰) 원장은 보호소년등의 행동을 수시로 관찰하고 특이사항을 기록ㆍ유지하여 감호ㆍ분류심사 및 교정교육의 자료로 활용하여야 한다.', 402);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2908, '제27조(사고발생보고) 원장은 영 제20조제1항에 따라 사고발생사실을 법무부장관에게 보고하는 경우에는 관련 자료와 대상자의 인적사항, 사고발생 일시ㆍ장소ㆍ내용ㆍ조치사항 등이 작성된 보고서를 첨부하여야 한다.', 402);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2909, '제27조의2(규율 위반) 법 제14조의4제6호에서 "법무부령으로 정하는 규율을 위반하는 행위"란 다음 각 호의 행위를 말한다. <개정 2016.9.29>', 402);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2910, '제28조(징계양정)', 403);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2911, '제28조의2(징계대상행위 조사 시 준수사항) 영 제24조의2에 따라 징계대상행위에 대하여 조사하는 직원은 다음 각 호의 사항을 준수하여야 한다.', 403);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2912, '제29조(포상) 원장은 별표 2의2의 보호소년등의 포상기준에 따라 교정성적이 우수한 학생에 대하여 처우ㆍ징계위원회의 심사를 거쳐 포상을 할 수 있다. 다만, 모범상 및 공로상은 직원 2명 이상의 추천을 받아야 한다. <개정 2021.4.20>', 403);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2913, '제30조(징계ㆍ포상의 기록) 원장은 보호소년등의 징계 또는 포상에 관한 사항을 소년관리기록부 및 별지 제6호서식의 상벌대장에 기록ㆍ관리하여야 한다.', 403);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2914, '제31조(급여품관리부의 작성) 보호소년등에게 물품을 급여 또는 대여할 때에는 별지 제7호서식의 개인별 급여품관리부에 그 내용을 기록ㆍ관리하여야 한다.', 404);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2915, '제32조(물품반입)', 404);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2916, '제33조(면회장소)', 405);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2917, '제34조(면회절차)', 405);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2918, '제35조(공휴일의 면회) 원장은 보호소년등을 면회할 목적으로 방문하는 민원인의 편의를 도모하기 위하여 제36조 각 호의 어느 하나에 해당하는 특별한 사유가 있는 경우에는 공휴일에도 별도의 면회장소 및 시간을 지정하여 면회를 허가할 수 있다. 이 경우 별지 제9호서식의 시간외 면회부에 그 내용을 기록ㆍ관리하여야 한다. <개정 2014.1.29>', 405);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2919, '제36조(면회의 특례) 영 제36조제1항 단서에 따른 특별한 사유는 다음 각 호의 어느 하나에 해당하는 경우를 말한다.', 405);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2920, '제36조의2(전화통화의 방법 등)', 405);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2921, '제37조(외출의 신청)', 405);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2922, '제38조 삭제 <2014.1.29>', 405);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2923, '제39조(외출시 준수사항)', 405);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2924, '제40조(보건ㆍ위생관리계획 수립 등)', 406);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2925, '제41조(청결의 유지)', 406);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2926, '제42조(이발과 목욕) 원장은 위생을 위해 보호소년등이 이발과 목욕을 수시로 하게 해야 한다.', 406);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2927, '제43조(체력검사 등)', 406);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2928, '제44조(환자발생 보고) 영 제43조에 따른 외부 의료기관 의료조치에 관한 보고는 제27조를 준용한다. <개정 2021.4.20>', 406);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2929, '제44조의2(진료기록부등의 보존) 법무부장관은 법 제20조의2제1항에 따른 진료기록부등(이하 "진료기록부등"이라 한다)을 「의료법 시행규칙」 제15조제1항에 따른 기간 동안 보존해야 한다.', 406);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2930, '제44조의3(진료기록부등의 송부 및 요청)', 406);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2931, '제44조의4(출원생의 외래진료의 기간ㆍ방법)', 406);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2932, '제44조의5(출원생의 외래진료 진료비용 지원)', 406);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2933, '제45조(물품의 보관) 원장은 보호소년등의 물품을 보관할 때에는 세탁ㆍ소독 그 밖의 적당한 조치를 한 후 주의하여 보관하여야 한다.', 407);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2934, '제46조(보관금품 보관증) 영 제47조 전단에 따른 보관금품 보관증은 별지 제12호서식에 따른다.', 407);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2935, '제47조(기증품 사용관리) 원장은 영 제49조제1항에 따라 기증품을 접수하면 기증인에게 별지 제13호서식에 따른 영수증을 발급하고, 별지 제14호서식에 따른 기증품관리대장에 기록한 후 사용하여야 하며, 그 사용결과를 기증자에게 통보하여야 한다.', 407);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2936, '제48조(분류심사의 방법 및 구분 등)', 408);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2937, '제49조(면접조사)', 408);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2938, '제50조(행동관찰)', 408);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2939, '제51조(분류심사관의 임명 등)', 408);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2940, '제52조(분류심사 결과 등의 통지) 법 제26조에 따른 청소년심리검사 등의 결과 및 법 제27조에 따른 분류심사 결과 등을 통지할 때에는 법무부장관이 별도로 정한 서식에 따른다.', 408);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2941, '제53조(신입자교육)', 410);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2942, '제54조(기본교육) 소년원장은 제53조에 따른 신입자교육을 마친 보호소년에 대하여는 인문ㆍ실업ㆍ특성화ㆍ인성교육 또는 직업능력개발훈련, 특별활동, 생활지도 그 밖에 필요한 기본교육을 실시하여야 한다.', 410);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2943, '제55조(사회복귀교육)', 410);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2944, '제56조 삭제 <2014.1.29>', 410);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2945, '제57조(여름철 및 겨울철의 지도) 소년원장은 여름철과 겨울철에 상당기간을 방학기간으로 정하여 특별활동 및 생활지도 중심의 교정교육을 할 수 있다.', 410);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2946, '제58조 삭제 <2008.6.20>', 410);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2947, '제59조(소년관리기록부 등)', 410);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2948, '제60조(학칙)', 411);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2949, '제61조(학칙 등에 관한 통지) 소년원학교장은 학사운영에 관한 긴밀한 협력을 도모하기 위하여 관할 시ㆍ도교육감 또는 시ㆍ군ㆍ자치구 교육장에게 소년원학교에 관한 다음 각 호의 사항을 통지하여야 한다.', 411);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2950, '제62조(업무연구 등) 원장은 교정교육 전반을 창의적으로 개선하고 업무능률을 향상시키기 위하여 직원으로 하여금 업무연구 또는 연구수업을 실시하게 하고, 연구발표회 등의 참관을 적극 권장하여야 한다.', 411);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2951, '제63조(보충수업) 소년원학교장은 보호소년의 학력신장과 수업일수의 충족 등을 위하여 필요하다고 인정하면 평일의 경우 1일 2시간, 휴업일의 경우 1일 8시간의 범위에서 보충수업을 실시할 수 있다. <개정 2014.1.29, 2021.4.20>', 411);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2952, '제64조(학적자료 송부 등) 소년원학교장은 보호소년이 법 제32조에 따라 다른 학교로 전학하거나 편입학을 하는 경우에는 전학 또는 편입학한 학교에 학교생활기록부 전산자료와 용지에 출력한 출력물 및 건강기록부를 송부하고, 소년원학교에는 그 사본을 소년관리기록부와 함께 보관하여야 한다.', 411);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2953, '제65조(졸업장의 발급 등)', 411);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2954, '제66조(졸업증명서 등 서식) 영 제68조에 따른 졸업증명서ㆍ성적증명서ㆍ수료(제적)증명서ㆍ재학증명서는 각각 별지 제20호서식부터 별지 제23호서식까지에 따른다.', 411);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2955, '제67조(직종의 신설 또는 폐지)', 412);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2956, '제68조(직업능력개발훈련 대상자)', 412);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2957, '제69조(통근취업 보호소년의 관리)', 412);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2958, '제70조(보호소년등의 일과)', 413);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2959, '제71조(종교활동) 종교활동은 휴업일에 하는 것을 원칙으로 한다. 다만, 원장이 필요하다고 인정하면 교육과정의 이수에 지장이 없는 범위에서 휴업일이 아닌 날에도 할 수 있다. <개정 2021.4.20>', 413);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2960, '제72조(보호소년자치회)', 413);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2961, '제73조(대안교육)', 413);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2962, '제74조(보호자상담 등)', 413);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2963, '제75조(퇴원ㆍ임시퇴원 심사의 신청)', 414);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2964, '제76조(재ㆍ퇴원증명서) 영 제87조의2에서 "법무부령으로 정하는 재ㆍ퇴원증명서"란 다음 각 호의 구분에 따른 서식을 말한다.', 414);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2965, '제77조(특별 임시퇴원) 소년원장은 보호소년이 다음 각 호의 어느 하나에 해당하는 사유가 있는 경우에는 증빙서류를 첨부하여 특별 임시퇴원허가를 신청할 수 있다. <개정 2021.4.20>', 414);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2966, '제78조(임시퇴원자의 보호관찰자료 제공 등)', 414);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2967, '제79조(퇴원증 또는 임시퇴원증의 교부 등)', 414);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2968, '제80조(보호소년의 인도)', 414);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2969, '제81조(사회정착지원)', 414);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2970, '제81조의2 삭제 <2021.4.20>', 414);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2971, '제82조 삭제 <2016.9.29>', 414);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2972, '제83조(퇴원 또는 임시퇴원자의 계속수용)', 414);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2973, '제84조(임시퇴원취소자 인수소년원의 사후조치)', 414);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2974, '제85조(임시퇴원취소로 재수용된 사람의 처우)', 414);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2975, '제86조(청소년심리상담실의 운영) 법 제50조의2에 따른 청소년심리상담실에는 법 제24조제2항에 따른 전문적 지식과 기술을 갖춘 직원을 상시 배치하여야 한다.', 415);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2976, '제87조(실비 징수)', 415);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2977, '제88조(소년보호위원의 위촉 및 해촉)', 415);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2978, '제89조(소년보호위원의 자격기준 등) 소년보호위원의 세부적인 자격기준, 활동 등에 관한 사항은 법무부장관이 정한다.', 415);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2979, '제90조(소년보호협회의 수익사업 등)', 415);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2980, '제91조(기부금품의 접수 영수증 등)', 415);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2981, '제1조(목적) 이 법은 특정공무원범죄(特定公務員犯罪)를 범한 사람이 그 범죄행위를 통하여 취득한 불법수익 등을 철저히 추적ㆍ환수(還收)하기 위하여 몰수 등에 관한 특례를 규정함으로써 공직사회의 부정부패 요인을 근원적으로 제거하고 깨끗한 공직 풍토를 조성함을 목적으로 한다.', 416);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2982, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다.', 416);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2983, '제3조(불법재산의 몰수)', 417);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2984, '제4조(불법재산이 합하여진 재산의 몰수방법) 불법재산이 불법재산 외의 재산과 합하여진 경우에 제3조제1항에 따라 그 불법재산을 몰수하여야 할 때에는 불법재산과 불법재산 외의 재산이 합하여진 재산(이하 "혼합재산"이라 한다) 중 불법재산의 비율에 해당하는 부분을 몰수한다.', 417);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2985, '제5조(몰수의 요건 등)', 417);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2986, '제6조(추징) 불법재산을 몰수할 수 없거나 제3조제2항에 따라 몰수하지 아니하는 경우에는 그 가액(價額)을 범인에게서 추징(追徵)한다.', 417);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2987, '제7조(불법재산의 증명) 특정공무원범죄 후 범인이 취득한 재산으로서 그 가액이 취득 당시의 범인의 재산 운용 상황 또는 법령에 따른 지급금의 수령 상황 등에 비추어 현저하게 고액(高額)이고, 그 취득한 재산이 불법수익 금액 및 재산 취득시기 등 모든 사정에 비추어 특정공무원범죄로 얻은 불법수익으로 형성되었다고 볼 만한 상당한 개연성이 있는 경우에는 특정공무원범죄로 얻은 불법수익이 그 재산의 취득에 사용된 것으로 인정할 수 있다.', 417);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2988, '제8조(제3자의 권리 존속 등) 지상권ㆍ저당권 또는 그 밖의 권리가 그 위에 존재하는 재산을 몰수하는 경우에 제5조제2항에 따라 해당 권리를 존속시키려면 법원은 몰수를 선고하는 동시에 그 취지를 선고하여야 한다.', 418);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2989, '제9조(몰수된 재산의 처분 등)', 418);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2990, '제9조의2(불법재산 등에 대한 추징) 제6조의 추징은 범인 외의 자가 그 정황을 알면서 취득한 불법재산 및 그로부터 유래한 재산에 대하여 그 범인 외의 자를 상대로 집행할 수 있다.', 418);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2991, '제9조의3(몰수ㆍ추징 집행을 위한 검사 처분)', 418);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2992, '제9조의4(몰수ㆍ추징의 시효) 특정공무원범죄에 관한 몰수ㆍ추징의 시효는 「형법」 제78조에도 불구하고 10년으로 한다.', 418);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2993, '제10조(몰수재판에 따른 등기 등) 권리를 이전(移轉)할 때 등기 또는 등록(이하 "등기등"이라 한다)이 필요한 재산을 몰수하는 재판에 따라 권리의 이전 등의 등기등을 관계 기관에 촉탁(囑託)하는 경우, 다음 각 호의 어느 하나의 경우에는 해당 각 등기등도 말소를 촉탁한 것으로 본다.', 418);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2994, '제11조(형사보상의 특례) 채권 등의 몰수 집행에 대한 「형사보상 및 명예회복에 관한 법률」에 따른 보상의 내용에 관하여는 같은 법 제5조제6항을 준용한다. <개정 2011.5.23>', 418);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2995, '제12조(몰수재산 처분의 특례)', 418);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2996, '제13조(고지)', 419);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2997, '제14조(참가 절차)', 419);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2998, '제15조(참가인의 권리)', 419);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (2999, '제16조(참가인의 출석 등)', 419);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3000, '제17조(증거)', 419);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3001, '제18조(몰수재판의 제한) 제3자가 참가허가를 받지 못하였을 때에는 다음 각 호의 어느 하나에 해당하는 경우를 제외하고는 몰수재판을 할 수 없다.', 419);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3002, '제19조(상소)', 419);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3003, '제20조(대리인)', 419);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3004, '제21조(「형사소송법」의 준용)', 419);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3005, '제22조(다른 절차와의 관계) 제13조제1항에 규정된 재산을 몰수하는 재판은 자기의 책임으로 돌릴 수 없는 사유로 피고인에 대한 형사사건 절차에서 권리를 주장할 수 없었던 제3자의 권리에는 영향을 미치지 아니한다.', 419);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3006, '제23조(몰수보전명령)', 421);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3007, '제24조(기소 전 몰수보전명령)', 421);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3008, '제25조(몰수보전에 관한 재판의 집행)', 421);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3009, '제26조(몰수보전의 효력) 몰수보전된 재산(이하 "몰수보전재산"이라 한다)에 대하여 그 보전 이후에 된 처분은 몰수에 관하여 그 효력을 발생하지 아니한다. 다만, 제37조제1항 본문에 규정된 경우(제40조제4항 및 제5항에 따라 준용하는 경우를 포함한다) 및 몰수보전명령에 대항할 수 있는 담보권의 실행으로서의 처분에 관하여는 그러하지 아니하다.', 421);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3010, '제27조(부동산의 몰수보전)', 421);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3011, '제28조(선박 등의 몰수보전) 등기할 수 있는 선박, 「항공안전법」에 따라 등록된 항공기, 「자동차관리법」에 따라 등록된 자동차, 「건설기계관리법」에 따라 등록된 건설기계의 몰수보전에 관하여는 부동산에 대한 몰수보전의 예에 따른다. <개정 2016.3.29>', 421);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3012, '제29조(동산의 몰수보전)', 421);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3013, '제30조(채권의 몰수보전)', 421);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3014, '제31조(그 밖의 재산권의 몰수보전)', 421);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3015, '제32조(몰수보전명령의 취소)', 421);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3016, '제33조(몰수보전명령의 실효)', 421);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3017, '제34조(실효된 경우의 조치) 검사는 몰수보전이 실효된 때에는 지체 없이 몰수보전등기 등에 대한 말소 촉탁을 하고, 공시서를 제거하거나 그 밖에 필요한 조치를 하여야 한다.', 421);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3018, '제35조(몰수보전재산에 대한 강제집행 절차의 제한)', 421);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3019, '제36조(제3채무자의 공탁)', 421);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3020, '제37조(강제집행의 대상이 된 재산의 몰수 제한)', 421);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3021, '제38조(강제집행의 정지)', 421);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3022, '제39조(담보권의 실행을 위한 경매 절차와의 조정)', 421);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3023, '제40조(그 밖의 절차와의 조정)', 421);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3024, '제41조(부대보전명령의 효력 등)', 421);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3025, '제42조(추징보전명령)', 422);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3026, '제43조(기소 전 추징보전명령)', 422);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3027, '제44조(추징보전명령의 집행)', 422);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3028, '제45조(금전채권 채무자의 공탁) 추징보전명령에 따라 추징보전이 집행된 금전채권의 채무자는 그 채권액에 상당한 금액을 공탁할 수 있다. 이 경우 채권자의 공탁금출급청구권(供託金出給請求權)에 대하여 추징보전이 집행된 것으로 본다.', 422);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3029, '제46조(추징보전해방금의 공탁과 추징 등의 재판의 집행)', 422);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3030, '제47조(추징보전명령의 취소) 법원은 추징보전의 이유 또는 필요가 없게 되거나 추징보전기간이 부당하게 길어진 때에는 검사, 피고인ㆍ피의자 및 그 변호인의 청구 또는 법원의 직권에 의한 결정으로 추징보전명령을 취소하여야 한다. 이 경우 제32조제2항을 준용한다.', 422);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3031, '제48조(추징보전명령의 실효)', 422);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3032, '제49조(추징보전명령이 실효된 경우의 조치) 검사는 추징보전명령이 실효되거나 추징보전해방금이 공탁된 경우 신속하게 제44조제1항에 따른 명령을 취소함과 동시에 추징보전명령에 따른 추징보전 집행의 정지 또는 취소를 위하여 필요한 조치를 하여야 한다.', 422);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3033, '제50조(송달) 몰수보전 또는 추징보전(추징보전명령에 따른 추징보전 집행은 제외한다. 이하 이 절에서 같다)에 관한 서류의 송달에 관하여는 대법원규칙으로 특별히 정한 경우를 제외하고는 민사소송에 관한 법령의 규정을 준용한다. 이 경우 「민사소송법」 제194조제1항에 규정된 공시송달의 효력 발생시기는 같은 법 제196조제1항 본문 및 제2항에도 불구하고 7일로 한다.', 423);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3034, '제51조(상소 제기기간 중의 처분 등) 상소 제기기간에 발생한 사건으로서 아직 상소가 제기되지 아니한 사건과 상소하였으나 소송기록이 상소법원에 도달하지 아니한 사건에 관하여 몰수보전 또는 추징보전에 관한 처분을 하여야 할 경우에는 원심법원이 그 처분을 하여야 한다.', 423);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3035, '제52조(불복신청)', 423);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3036, '제1조(취지) 「공무원범죄에 관한 몰수특례법」(이하 "법"이라 한다)에 의한 몰수보전 및 추징보전의 절차등에 관하여는 법의 규정에 의하는 외에 이 규칙이 정하는 바에 의한다. <개정 2005.12.29>', 424);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3037, '제2조(몰수보전 청구의 방식) 몰수보전의 청구는 서면으로 하여야 한다.', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3038, '제3조(몰수보전 청구서의 기재사항)', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3039, '제4조(부대보전 청구의 방식) 부대보전(부대보전명령에 의한 처분의 금지를 말한다. 이하 같다)의 청구는 서면으로 하여야 한다.', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3040, '제5조(부대보전청구서의 기재사항)', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3041, '제6조(몰수보전명령의 기재사항) 몰수보전명령 및 부대보전명령을 발하는 경우 그 재판서에는 법 제23조제3항이 규정하는 사항외에 피고인 또는 피의자의 주민등록번호와 주거, 처분을 금지하는 재산 또는 권리를 가진 자(명의인이 다른 경우 명의인을 포함한다)의 주소를 기재하여야 한다.', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3042, '제7조(긴급을 요하는 경우의 기재사항) 법 제23조제4항의 규정에 의하여 몰수보전명령 또는 부대보전명령을 발하는 경우에는 재판서에 그 취지를 기재하여야 한다.', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3043, '제8조(몰수보전명령이 발하여진 경우의 공소장의 기재사항) 공소가 제기되기 전에 몰수보전명령이 발하여진 경우, 검사는 공소장에 몰수보전명령이 발하여졌다는 취지의 기재를 하여야 한다.', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3044, '제9조(몰수보전이 된 금전채권의 채무자가 공탁을 한 경우) 금전의 지급을 목적으로 하는 채권(이하 "금전채권"이라고 한다)에 대하여 몰수보전이 되어 그 채무자가 공탁을 한 경우 그 공탁을 수리한 공탁관은 몰수보전명령을 발한 법원 및 이에 대응하는 검찰청의 검사(이하 "검사"라고 한다) 또는 고위공직자범죄수사처에 소속된 검사(이하 "수사처검사"라고 한다)에게 공탁사실을 통지하여야 한다. <개정 2007.3.29, 2021.1.29>', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3045, '제10조(예탁유가증권의 몰수보전) 「자본시장과 금융투자업에 관한 법률」 제309조제2항에 따라 한국예탁결제원에 예탁된 유가증권(같은 법률 제310조제4항에 따라 한국예탁결제원에 예탁된 것으로 보는 경우를 포함한다. 이하 이 조에서 "예탁유가증권"이라 한다)에 대한 몰수보전은, 예탁유가증권에 대한 공유지분을 가지는 자(명의인이 다른 경우 명의인을 포함한다)에게는 계좌간 대체청구ㆍ증권반환청구, 그 밖의 처분을 금지하고, 한국예탁결제원에게는 예탁자에 대한 계좌간 대체와 증권의 반환을 금지하는 취지의 몰수보전명령에 의하여 한다. <개정 2005.12.29, 2019.11.29>', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3046, '제10조의2(전자등록주식등의 몰수보전) 「주식ㆍ사채 등의 전자등록에 관한 법률」 제2조제4호에 따른 전자등록주식등(이하 이 조에서 "전자등록주식등"이라 한다)에 대한 몰수보전은, 전자등록주식등의 권리자(명의인이 다른 경우 명의인을 포함한다)에게는 같은 법 제30조에 따른 계좌간 대체의 전자등록신청, 같은 법 제33조에 따른 변경ㆍ말소의 전자등록신청이나 추심, 그 밖의 처분을 금지하고, 같은 법 제2조제6호에 따른 전자등록기관 또는 같은 법 제2조제7호에 따른 계좌관리기관에게는 같은 법에 따른 계좌간 대체와 변경ㆍ말소를 금지하는 취지의 몰수보전명령에 의하여 한다.', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3047, '제11조(몰수보전명령의 취소청구의 방식)', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3048, '제12조(검사 또는 수사처검사의 의견서등의 제출) 검사 또는 수사처검사는 법원으로부터 몰수보전명령의 취소에 관한 의견요청이 있을 때에는 3일이내에 의견서를 법원에 제출하여야 하고, 아직 수사기록과 증거물을 법원에 증거로 제출하지 않은 경우에는 수사기록과 증거물도 함께 법원에 제출하여야 한다. <개정 2021.1.29>', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3049, '제13조(몰수보전재산에 대하여 강제집행에 의하여 압류등이 된 경우의 통지)', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3050, '제14조(몰수보전된 금전채권에 대하여 강제집행에 의하여 압류가 된 경우 공탁사유신고의 방식등)', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3051, '제14조의2(몰수보전된 금전채권에 대하여 체납처분에 의하여 압류가 된 경우의 공탁사유신고의 방식등)', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3052, '제15조(강제집행에 의하여 압류가 된 금전채권에 대하여 몰수보전이 된 경우 공탁사유신고의 방식등)', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3053, '제15조의2(체납처분에 의하여 압류가 된 금전채권에 대하여 몰수보전된 경우의 공탁사유신고의 방식등)', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3054, '제16조(강제집행에 의하여 압류등이 된 재산에 대하여 몰수보전이 된 경우의 통지)', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3055, '제17조(강제집행의 정지 및 그 결정의 취소청구방식)', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3056, '제18조(몰수보전과 담보권 실행 등을 위한 경매개시결정에 의한 압류가 경합하는 경우의 통지) 제13조제1항, 제3항 및 제16조제3항의 규정은 몰수보전이 된 재산에 대하여 담보권 실행 등을 위한 경매개시결정에 의하여 압류가 된 경우에, 제16조의 규정은 담보권 실행 등을 위한 경매개시결정에 의하여 압류가 된 재산에 대하여 몰수보전명령이 발하여진 경우에 각 준용한다. 이 경우 그 담보권에 대하여 부대보전이 된 때에는 제13조제3항 및 제16조제2항중 "몰수보전"은 "몰수보전 또는 부대보전"으로 본다. <개정 2005.12.29>', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3057, '제19조(몰수보전과 가압류의 집행이 경합하는 경우의 통지등)', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3058, '제20조(부대보전절차에의 준용) 부대보전의 절차에 관하여는 이 규칙에 특별한 규정이 있는 경우를 제외하고는 몰수보전의 절차에 관한 규정을 준용한다.', 425);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3059, '제21조(추징보전 청구의 방식) 추징보전의 청구는 서면으로 하여야 한다.', 426);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3060, '제22조(추징보전 청구서의 기재사항)', 426);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3061, '제23조(추징보전집행이 된 금전채권의 채무자의 공탁방법등) 추징보전집행된 금전채권의 채무자가 법 제45조에 의한 공탁을 한 경우 그 공탁을 수리한 공탁관은 추징보전명령을 발한 법원 및 검사 또는 수사처검사에게 공탁사실을 통지하여야 한다. <개정 2007.3.29, 2021.1.29>', 426);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3062, '제24조(추징보전해방금의 공탁 및 환부) 추징보전명령이 실효되거나 취소된 때에는 추징보전명령을 발한 법원은 공탁된 추징보전해방금을 환부하여야 한다.', 426);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3063, '제25조(추징보전명령등에의 준용) 제6조, 제7조, 제8조, 제11조, 제12조의 규정은 추징보전명령 또는 추징보전에 관하여 준용한다. 이 경우 제6조중 "법 제23조제3항"은 "법 제42조제4항"으로, 제11조중 "법 제32조제1항"은 "법 제47조"로 각 본다.', 426);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3064, '제26조(「형사소송규칙」의 준용) 몰수보전 및 추징보전의 절차와 제3자 참가절차등의 특례에 관하여는 법 및 이 규칙에 특별한 규정이 있는 경우를 제외하고는 「형사소송규칙」의 규정을 준용한다. 이 경우 법 제14조의 규정에 의하여 형사사건절차에의 참가를 허가받은 자에 관하여는 피고인에 관한 규정을, 법 제20조의 규정에 의하여 선임된 대리인에 관하여는 변호인에 관한 규정을 준용한다. <개정 2005.12.29>', 427);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3065, '제1조(목적) 이 영은 「질서위반행위규제법」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3066, '제2조(질서위반행위에서 제외되는 행위)', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3067, '제2조의2(과태료 감경)', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3068, '제3조(사전통지 및 의견제출 등)', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3069, '제4조(과태료 부과 고지서) 법 제17조제1항에 따라 행정청이 과태료를 부과하는 경우에는 다음 각 호의 사항을 모두 적은 서면(당사자가 동의하는 경우에는 전자문서를 포함한다)으로 하여야 한다. <개정 2011.6.24, 2013.5.10>', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3070, '제4조의2(신용카드 등에 의한 과태료의 납부)', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3071, '제5조(자진납부자에 대한 과태료 감경) 법 제18조제1항에 따라 자진납부하는 경우 감경할 수 있는 금액은 부과될 과태료의 100분의 20의 범위 이내로 한다.', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3072, '제6조(질서위반행위의 조사)', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3073, '제7조(공공기관) 법 제23조에서 "그 밖에 대통령령으로 정하는 공공기관"이란 「공공기관의 운영에 관한 법률」 제4조에 따라 공공기관으로 지정된 기관을 말한다.', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3074, '제7조의2(과태료의 징수유예등)', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3075, '제7조의3(징수유예등의 신청 등)', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3076, '제7조의4(징수유예등의 취소)', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3077, '제7조의5(결손처분)', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3078, '제8조(징수 절차)', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3079, '제9조(이의신청) 법 제46조제1항에 따른 이의신청은 별지 제3호서식의 약식재판에 대한 이의신청서로 한다. <개정 2017.6.2>', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3080, '제10조(이의신청 취하) 법 제47조제1항에 따른 이의신청 취하는 별지 제4호서식의 약식재판에 대한 이의신청취하서로 한다. <개정 2017.6.2>', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3081, '제11조(관허사업 제한의 기준 등)', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3082, '제12조(신용정보 제공사실 통보) 법 제53조에 따라 행정청이 체납 또는 결손처분 자료를 제공한 경우에는 그로부터 30일 이내에 별지 제5호서식의 신용정보 제공사실 통보서로 그 사실을 체납자에게 알려야 한다. <개정 2017.6.2>', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3083, '제13조(감치기준)', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3084, '제14조(자동차 등록번호판의 영치)', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3085, '제14조의2(자동차 등록번호판의 영치 일시 해제)', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3086, '제15조(고유식별정보의 처리) 행정청 또는 검사는 법 및 이 영에 따른 과태료의 부과ㆍ징수 및 재판 등에 관한 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법 시행령」 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 428);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3087, '제1조(목적) 이 법은 범죄인 인도(引渡)에 관하여 그 범위와 절차 등을 정함으로써 범죄 진압 과정에서의 국제적인 협력을 증진함을 목적으로 한다.', 429);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3088, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다.', 429);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3089, '제3조(범죄인 인도사건의 전속관할) 이 법에 규정된 범죄인의 인도심사 및 그 청구와 관련된 사건은 서울고등법원과 서울고등검찰청의 전속관할로 한다.', 429);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3090, '제3조의2(인도조약과의 관계) 범죄인 인도에 관하여 인도조약에 이 법과 다른 규정이 있는 경우에는 그 규정에 따른다.', 429);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3091, '제4조(상호주의) 인도조약이 체결되어 있지 아니한 경우에도 범죄인의 인도를 청구하는 국가가 같은 종류 또는 유사한 인도범죄에 대한 대한민국의 범죄인 인도청구에 응한다는 보증을 하는 경우에는 이 법을 적용한다.', 429);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3092, '제5조(인도에 관한 원칙) 대한민국 영역에 있는 범죄인은 이 법에서 정하는 바에 따라 청구국의 인도청구에 의하여 소추(訴追), 재판 또는 형의 집행을 위하여 청구국에 인도할 수 있다.', 431);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3093, '제6조(인도범죄) 대한민국과 청구국의 법률에 따라 인도범죄가 사형, 무기징역, 무기금고, 장기(長期) 1년 이상의 징역 또는 금고에 해당하는 경우에만 범죄인을 인도할 수 있다.', 431);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3094, '제7조(절대적 인도거절 사유) 다음 각 호의 어느 하나에 해당하는 경우에는 범죄인을 인도하여서는 아니 된다.', 431);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3095, '제8조(정치적 성격을 지닌 범죄 등의 인도거절)', 431);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3096, '제9조(임의적 인도거절 사유) 다음 각 호의 어느 하나에 해당하는 경우에는 범죄인을 인도하지 아니할 수 있다.', 431);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3097, '제10조(인도가 허용된 범죄 외의 범죄에 대한 처벌 금지에 관한 보증) 인도된 범죄인이 다음 각 호의 어느 하나에 해당하는 경우를 제외하고는 인도가 허용된 범죄 외의 범죄로 처벌받지 아니하고 제3국에 인도되지 아니한다는 청구국의 보증이 없는 경우에는 범죄인을 인도하여서는 아니 된다.', 431);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3098, '제10조의2(동의 요청에 대한 법무부장관의 조치) 법무부장관은 범죄인을 인도받은 청구국으로부터 인도가 허용된 범죄 외의 범죄로 처벌하거나 범죄인을 제3국으로 다시 인도하는 것에 관한 동의 요청을 받은 경우 그 요청에 타당한 이유가 있다고 인정될 때에는 이를 승인할 수 있다. 다만, 청구국이나 제3국에서 처벌하려는 범죄가 제7조 각 호 또는 제8조에 해당되는 경우에는 그 요청을 승인하여서는 아니 된다.', 431);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3099, '제11조(인도청구를 받은 외교부장관의 조치) 외교부장관은 청구국으로부터 범죄인의 인도청구를 받았을 때에는 인도청구서와 관련 자료를 법무부장관에게 송부하여야 한다. <개정 2013.3.23>', 432);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3100, '제12조(법무부장관의 인도심사청구명령)', 432);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3101, '제13조(인도심사청구)', 432);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3102, '제14조(법원의 인도심사)', 432);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3103, '제15조(법원의 결정)', 432);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3104, '제15조의2(범죄인의 인도 동의)', 432);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3105, '제16조(인도청구의 경합)', 432);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3106, '제17조(물건의 양도)', 432);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3107, '제18조(인도심사청구명령의 취소)', 432);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3108, '제19조(인도구속영장의 발부)', 433);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3109, '제20조(인도구속영장의 집행)', 433);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3110, '제21조(교도소 등에의 구금) 검사는 인도구속영장에 의하여 구속된 범죄인을 인치받으면 인도구속영장에 기재된 사람과 동일인인지를 확인한 후 지체 없이 교도소, 구치소 또는 그 밖에 인도구속영장에 기재된 장소에 구금하여야 한다.', 433);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3111, '제22조(인도구속의 적부심사)', 433);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3112, '제23조(인도구속의 집행정지와 효력 상실)', 433);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3113, '제24조(긴급인도구속의 청구를 받은 외교부장관의 조치) 외교부장관은 청구국으로부터 범죄인의 긴급인도구속을 청구받았을 때에는 긴급인도구속 청구서와 관련 자료를 법무부장관에게 송부하여야 한다. <개정 2013.3.23>', 433);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3114, '제25조(긴급인도구속에 관한 법무부장관의 조치) 법무부장관은 제24조에 따른 서류를 송부받은 경우에 범죄인을 긴급인도구속하는 것이 타당하다고 인정할 때에는 그 서류를 서울고등검찰청 검사장에게 송부하고 그 소속 검사로 하여금 범죄인을 긴급인도구속하도록 명하여야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 긴급인도구속을 명할 수 없다.', 433);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3115, '제26조(긴급인도구속영장에 의한 구속)', 433);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3116, '제27조(긴급인도구속된 범죄인의 석방)', 433);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3117, '제28조(범죄인에 대한 통지)', 433);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3118, '제29조(인도 불청구 통지 시의 석방)', 433);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3119, '제30조(검사의 조치사항) 검사는 긴급인도구속영장에 의하여 구속된 범죄인에 대하여 그가 구속된 날부터 2개월 이내에 법무부장관의 인도심사청구명령이 없을 때에는 범죄인을 석방하고, 법무부장관에게 그 내용을 보고하여야 한다.', 433);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3120, '제31조(긴급인도구속에 대한 인도구속의 준용)', 433);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3121, '제32조(범죄인의 석방)', 434);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3122, '제33조(결정서 등본 등의 송부) 검사는 제15조제4항에 따른 결정서 등본을 송달받았을 때에는 지체 없이 그 결정서 등본에 관계 서류를 첨부하여 법무부장관에게 송부하여야 한다.', 434);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3123, '제34조(인도에 관한 법무부장관의 명령 등)', 434);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3124, '제35조(인도장소와 인도기한)', 434);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3125, '제36조(인도장과 인수허가장의 송부)', 434);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3126, '제37조(인도를 위한 구속)', 434);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3127, '제38조(법무부장관의 통지) 법무부장관은 제23조제5항 또는 제37조제5항에 따른 보고를 받았을 때에는 지체 없이 외교부장관에게 범죄인을 인도할 장소에 구속하였다는 사실과 인도할 기한을 통지하여야 한다. <개정 2013.3.23>', 434);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3128, '제39조(청구국에의 통지)', 434);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3129, '제40조(교도소장 등의 인도)', 434);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3130, '제41조(청구국의 범죄인 호송) 제40조제1항에 따라 범죄인을 인도받은 청구국의 공무원은 지체 없이 범죄인을 청구국으로 호송하여야 한다.', 434);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3131, '제42조(법무부장관의 인도청구 등)', 435);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3132, '제42조의2(검사장 등의 조치)', 435);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3133, '제42조의3(검사의 범죄인 인도청구 등의 건의)', 435);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3134, '제42조의4(외국에 대한 동의 요청)', 435);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3135, '제43조(인도청구서 등의 송부) 법무부장관은 제42조 및 제42조의4에 따라 범죄인 인도청구, 긴급인도구속청구, 동의 요청 등을 결정한 경우에는 인도청구서 등과 관계 자료를 외교부장관에게 송부하여야 한다. <개정 2013.3.23>', 435);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3136, '제44조(외교부장관의 조치) 외교부장관은 법무부장관으로부터 제43조에 따른 인도청구서 등을 송부받았을 때에는 이를 해당 국가에 송부하여야 한다. <개정 2013.3.23>', 435);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3137, '제45조(통과호송 승인)', 436);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3138, '제45조의2(통과호송 승인 요청)', 436);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3139, '제46조(비용) 범죄인의 인도에 드는 비용에 관하여 청구국과 특별한 약정이 없는 경우 청구국의 공무원에게 범죄인을 인도할 때까지 범죄인의 구속 등으로 인하여 대한민국의 영역에서 발생하는 비용은 대한민국이 부담하고, 청구국의 공무원이 범죄인을 대한민국으로부터 인도받은 후에 발생하는 비용은 청구국이 부담한다.', 436);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3140, '제47조(검찰총장 경유) 이 법에 따라 법무부장관이 검사장 등에게 하는 명령과 검사장ㆍ지청장 또는 검사가 법무부장관에게 하는 건의ㆍ보고 또는 서류 송부는 검찰총장을 거쳐야 한다. 다만, 고위공직자범죄수사처장 또는 그 소속 검사의 경우에는 그러하지 아니하다. <개정 2021.1.5>', 436);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3141, '제48조(인도조약 효력 발생 전의 범죄에 관한 인도청구) 인도조약에 특별한 규정이 없는 경우에는 인도조약의 효력 발생 전에 범한 범죄에 관한 범죄인의 인도청구에 대하여도 이 법을 적용한다.', 436);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3142, '제49조(대법원규칙) 법원의 인도심사 절차와 인도구속영장 및 긴급인도구속영장의 발부 절차 등에 관하여 필요한 사항은 대법원규칙으로 정한다.', 436);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3143, '제50조(시행령) 제49조에 따라 대법원규칙으로 정하는 사항 외에 이 법 시행에 필요한 사항은 대통령령으로 정한다.', 436);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3144, '제51조(출입국에 관한 특칙)', 436);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3145, '제1조 (목적) 이 규칙은 범죄인인도법(이하 "법"이라 한다)의 규정에 의한 법원의 인도심사절차 및 인도구속영장, 긴급인도구속영장의 발부절차등에 관하여 필요한 사항을 규정함을 목적으로 한다.', 437);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3146, '제2조 (정의)', 437);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3147, '제3조 (준용규정) 법원직원의 제척, 기피, 회피, 서류 및 송달에 관한 사항은 법 또는 이 규칙에 특별한 규정이 있는 경우를 제외하고는, 그 성질에 반하지 아니하는 범위안에서 형사소송법 및 형사소송규칙을 준용한다.', 437);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3148, '제4조 (번역문의 첨부) 외국어로 기재된 서면에는 그 번역문을 첨부하여야 한다.', 437);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3149, '제5조 (인도심사청구서의 기재요건)', 438);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3150, '제6조 (구속관련사항의 기재)', 438);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3151, '제7조 (자료제출명령) 재판장은 검사, 범죄인 또는 그 변호인에 대하여 인도심사에 필요한 자료의 제출을 명할 수 있다.', 438);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3152, '제8조 (통지의무) 검사는 인도심사청구후 다음 각호의 사유가 발생한 때에는 지체없이 법원에 서면으로 그 사실을 통지하여야 한다.', 438);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3153, '제9조 (변호인의 선임)', 438);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3154, '제10조 (준용규정) 제9조 및 법 제14조제3항의 규정에 의하여 범죄인등이 변호인을 선임하는 경우 또는 법 제14조제4항의 규정에 의하여 법원이 국선변호인을 선정하는 경우에, 변호인의 자격, 선정의 절차 및 변호인의 권한에 관하여는, 성질에 반하지 아니하는 범위안에서 형사소송법 제31조 본문, 제34조 내지 제36조 및 형사소송규칙 제1편 제4장을 준용한다.', 438);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3155, '제11조 (준용규정) 법 제14조제6항에 의하여 증인을 신문하거나 감정을 명하는 경우에는, 그 성질에 반하지 아니하는 범위안에서 형사소송규칙 제1편 제12장 및 제13장을 준용한다.', 438);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3156, '제12조 (심문기일)', 438);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3157, '제13조 (절차의 공개) 심문기일에서 절차는 이를 공개한다. 다만 국가의 안전보장ㆍ안녕질서 또는 선량한 풍속을 해할 염려가 있는 때에는 법원은 결정으로 이를 공개하지 아니할 수 있다.', 438);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3158, '제14조 (검사등의 신문권) 심문기일에 출석한 검사 또는 범죄인의 변호인은 법원의 신문이 끝난후 범죄인, 증인 및 감정인등을 신문할 수 있다.', 438);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3159, '제15조 (청구국대리인등의 참여) 청구국의 공무원 또는 그 대리인이 심문기일에 참여하거나 의견을 진술함에는 법원의 허가를 얻어야 한다.', 438);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3160, '제16조 (법원사무관등의 참여) 심문기일에는 법원사무관, 법원주사 또는 법원주사보를 참여시켜 조서를 작성하게 하여야 한다.', 438);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3161, '제17조 (결정서의 서명날인) 법 및 이 규칙에 의하여 작성되는 결정서에는 관여한 법관이 서명날인하여야 한다.', 438);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3162, '제18조 (결정주문의 통지) 법 제15조제3항의 규정에 의한 통지는 결정주문이 기재된 서면을 검사에게 송부함으로써 이를 행한다.', 438);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3163, '제19조 (변호인에의 송달) 법원이 법 제15조제1항의 규정에 의한 결정을 한 때에는 그 결정서의 등본을 범죄인의 변호인에게 송달하여야 한다.', 438);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3164, '제20조 (병합심리) 법 제16조제1항의 규정에 의하여, 동일한 범죄인에 대한 인도심사청구가 경합된 경우에는 이를 병합하여 심리할 수 있다.', 438);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3165, '제21조 (물건의 양도)', 438);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3166, '제22조 (준용규정) 법 제17조제2항의 규정에 의한 압수, 수색영장의 발부 및 집행절차에 대하여는 그 성질에 반하지 아니하는 범위안에서 형사소송규칙 제1편 제10장을 준용한다.', 438);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3167, '제23조 (인도구속영장청구의 방식)', 439);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3168, '제24조 (소명자료의 제출)', 439);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3169, '제25조 (인도구속영장의 기각)', 439);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3170, '제26조 (인도구속영장의 기재요건)', 439);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3171, '제27조 (수통의 인도구속영장의 발부)', 439);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3172, '제28조 (준용규정) 형사소송규칙 제49조제1항 및 제51조의 규정은 인도구속영장에 의한 구속에 관하여 이를 준용한다.', 439);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3173, '제29조 (인도구속적부심사청구서의 기재사항) 법 제22조제1항의 규정에 의한 인도 구속에 대한 적부심사는 다음 각호의 사항을 기재한 서면으로 하되 필요한 소명자료를 첨부하여야 한다.', 439);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3174, '제30조 (인도구속영장등본교부청구권) 법 제22조제1항에 규정된 자는 인도구속영장 원본을 보관하고 있는 검사 또는 사법경찰관에게 인도구속영장의 등본의 교부를 청구할 수 있다.', 439);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3175, '제31조 (준용규정) 인도구속의 적부심사절차에 관하여는 그 성질에 반하지 아니하는 범위안에서 형사소송규칙 제16조 및 제104조부터 제106조까지의 규정을 준용한다. <개정 2007.10.29>', 439);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3176, '제32조 (재구속영장의 기재사항) 법원의 인도구속적부심사결과 석방명령을 받아 석방된 범죄인을 재구속하기 위한 인도구속영장청구서에는 제23조에 규정한 사항외에 재구속영장의 청구라는 취지와 범죄인이 도망하거나 죄증을 인멸한 사실을 기재하여야 한다.', 439);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3177, '제33조 (긴급인도구속의 경우) 법 제26조제1항의 규정에 의한 긴급인도구속영장의 청구 및 발부절차에 관하여는 그 성질에 반하지 아니하는 범위안에서 제23조 내지 제32조의 규정을 준용한다.', 439);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3178, '제34조 (인도조약효력발생전의 범죄에 관한 인도청구) 이 규칙은 법 제48조의 규정에 의하여 법이 적용되는 인도청구의 경우에도 이를 적용한다.', 440);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3179, '제1조(목적) 이 법은 특정범죄에 관한 형사절차에서 국민이 안심하고 자발적으로 협조할 수 있도록 그 범죄신고자 등을 실질적으로 보호함으로써 범죄로부터 사회를 방위(防衛)하는 데에 이바지함을 목적으로 한다.', 441);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3180, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다. <개정 2016.3.3, 2016.12.20>', 441);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3181, '제3조(적용 범위) 이 법은 특정범죄에 관한 범죄신고자등이나 그 친족등이 보복을 당할 우려가 있는 경우에 한정하여 적용한다.', 441);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3182, '제4조(국가의 책무)', 441);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3183, '제5조(불이익 처우의 금지) 범죄신고자등을 고용하고 있는 자(고용주를 위하여 근로자에 관한 업무를 행하는 자를 포함한다)는 피고용자가 범죄신고등을 하였다는 이유로 해고나 그 밖의 불이익한 처우를 하여서는 아니 된다.', 441);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3184, '제6조(범죄신고자등보좌인)', 441);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3185, '제7조(인적 사항의 기재 생략)', 441);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3186, '제8조(인적 사항의 공개 금지) 이 법에 규정된 경우를 제외하고는 누구든지 이 법에 따라 보호되고 있는 범죄신고자등이라는 정황을 알면서 그 인적 사항 또는 범죄신고자등임을 미루어 알 수 있는 사실을 다른 사람에게 알려주거나 공개 또는 보도하여서는 아니 된다.', 441);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3187, '제9조(신원관리카드의 열람)', 441);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3188, '제10조(영상물 촬영)', 441);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3189, '제11조(증인 소환 및 신문의 특례 등)', 441);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3190, '제12조(소송진행의 협의 등)', 441);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3191, '제13조(신변안전조치)', 441);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3192, '제13조의2(신변안전조치의 종류) 신변안전조치의 종류는 다음과 같다.', 441);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3193, '제14조(범죄신고자등 구조금)', 441);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3194, '제15조(피고인 등과 관련된 주요 변동 상황 통지) 범죄신고자등이나 그 친족등이 보복을 당할 우려가 있는 경우에는 검사 또는 사법경찰관은 직권으로 또는 범죄신고자등, 그 법정대리인이나 친족등의 신청에 의하여 피의자 또는 피고인의 체포ㆍ구속 및 석방과 관련된 사법경찰관ㆍ검사 및 법원의 처분 내용, 재판선고기일이나 선고 내용 및 가석방ㆍ형집행정지ㆍ형기만료나 보안처분종료 등으로 인한 교정시설 등에서의 출소사실이나 도주사실 등 재판 및 신병(身柄)에 관련된 변동 상황을 범죄신고자등, 그 법정대리인 또는 친족등에게 통지할 수 있다.', 441);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3195, '제16조(범죄신고자등에 대한 형의 감면) 범죄신고등을 함으로써 그와 관련된 자신의 범죄가 발견된 경우 그 범죄신고자등에 대하여 형을 감경하거나 면제할 수 있다.', 441);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3196, '제17조(벌칙)', 441);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3197, '제1조(목적) 이 영은 특정범죄신고자등보호법에서 위임된 사항과 그 시행에 관하여 필요한 사항을 규정함을 목적으로 한다.', 442);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3198, '제2조(범죄신고자등보좌인의 자격) 특정범죄신고자등보호법(이하 "법"이라 한다)제6조제2항에서 "대통령령이 정하는 자"라 함은 다음 각호의 1에 해당하는 자를 말한다.', 442);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3199, '제3조(보좌인에 대한 실비지급 등)', 442);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3200, '제4조(신원관리카드의 기재사항)', 442);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3201, '제5조(신원관리카드의 관리)', 442);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3202, '제6조(신변안전조치의 요청 등)', 442);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3203, '제7조(신변안전조치의 종류) 법 제13조제1항의 규정에 의한 신변안전조치의 종류는 다음 각호의 1과 같다.', 442);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3204, '제8조(신변안전조치 이행통보 등)', 442);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3205, '제9조(구조금의 산정)', 442);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3206, '제10조(구조금의 신청) 범죄신고자등, 그 법정대리인 또는 친족등이 법 제14조의규정에 의한 구조금을 지급받고자 하는 때에는 법 제2조제2호의 규정에 의한 범죄신고등이 이루어진 지역을 관할하는 지방검찰청 범죄신고자등구조심의회(이하"심의회"라 한다)에 이를 신청하여야 한다. 이 경우 법 제7조제4항의 규정에 의하여 조서등에 성명을 기재하지 아니한 범죄신고자등은 가명으로 이를 신청할 수 있다.', 442);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3207, '제11조(구조결정)', 442);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3208, '제12조(심의회의 관할) 심의회의 관할구역은 심의회가 설치된 지방검찰청의관할구역(지청이 있는 경우에는 지청의 관할구역을 포함한다)으로 한다.', 442);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3209, '제13조(심의회의 구성) 심의회는 당해 심의회가 설치된 지방검찰청의 차장검사를 위원장으로 하고, 당해 지방검찰청 소속 공무원 및 법관의 자격을 가진 자중에서 법무부장관이 임명 또는 위촉하는 위원 4인으로 구성한다.', 442);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3210, '제14조(위원장)', 442);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3211, '제15조(심의회의 의사)', 442);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3212, '제16조(사무직원)', 442);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3213, '제17조(법무부장관의 지휘ㆍ감독)', 442);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3214, '제18조(결정 및 통지)', 442);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3215, '제19조(구조금의 지급청구)', 442);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3216, '제20조(서식 등) 법 및 이 영의 시행에 관하여 필요한 서식 등에 관한 사항은 법무부령으로 정한다.', 442);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3217, '제1조(목적) 이 규칙은 특정범죄신고자등보호법 및 동법시행령의 시행에 관하여 필요한 사항을 규정함을 목적으로 한다.', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3218, '제2조(범죄신고자등보좌인의 지정ㆍ취소 또는 교체신청) 특정범죄신고자등보호법(이하 "법"이라 한다) 제6조제1항 및 제5항제1호의 규정에 의한 범죄신고자등보좌인(이하 "보좌인"이라 한다)의 지정ㆍ취소 또는 교체신청은 별지 제1호서식에 의한다.', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3219, '제3조(보좌인의 지정ㆍ취소 또는 교체) 법 제6조제1항 및 제5항의 규정에 의한 보좌인의 지정ㆍ취소 또는 교체는 별지 제2호서식에 의한다.', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3220, '제4조(보좌인의 지정ㆍ취소 또는 교체의 허가) 법 제6조제7항의 규정에 의하여 사법경찰관이 보좌인을 지정ㆍ취소 또는 교체하고자 하는 때에는 별지 제3호서식에 의하여 검사의 허가를 얻어야 한다.', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3221, '제5조(보고) 법 제7조제2항의 규정에 의한 범죄신고자등 인적 사항 미기재사유의 보고는 별지 제4호서식에 의한다.', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3222, '제6조(신원관리카드의 작성) 법 제7조제3항의 규정에 의한 범죄신고자등신원관리카드(이하 "신원관리카드"라 한다)의 작성은 별지 제5호서식에 의한다.', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3223, '제7조(신원관리카드봉인봉투의 양식) 특정범죄신고자등보호법시행령(이하 "영"이라 한다) 제5조제1항의 규정에 의한 신원관리카드 봉인봉투는 별지 제6호서식에 의한다.', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3224, '제8조(신원관리카드의 인계 등)', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3225, '제9조(신원관리카드 등 서류의 보존기간) 신원관리카드를 관리하는 검사가 보관하는 신원관리카드 등 서류의 보존기간은 원사건기록의 보존기간으로 한다. 다만, 원사건기록의 보존기간보다 신변안전조치의 기간이 장기인 경우에는 그 신변안전조치의 종료일까지 신원관리카드 등 서류를 보존하여야 한다.', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3226, '제10조(신원관리카드의 열람허가신청 등)', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3227, '제11조(면담신청) 법 제9조제3항의 규정에 의한 면담신청은 별지 제10호서식에 의한다.', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3228, '제12조(면담신청사실 통지)', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3229, '제13조(이의신청 방법)', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3230, '제14조(신원관리카드의 작성 및 관리의 요청) 법 제11조제2항 후단의 규정에 의한 신원관리카드의 작성 및 관리의 요청은 이를 서면으로 하여야 한다. 다만, 검사가 출석한 공판정에서는 검사에게 구두로 이를 요청할 수 있다.', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3231, '제15조(신변안전조치의 지시 등) 법 제13조제1항 전단 및 영 제6조제4항의 규정에 의한 신변안전조치의 지시는 별지 제13호서식(앞면)에 의하고, 그 이행보고는 별지 제13호서식(뒷면)에 의한다.', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3232, '제16조(신변안전조치의 신청 등) 법 제13조제1항 전단의 규정에 의한 신변안전조치의 요청은 별지 제14호서식에 의하고, 법 제13조제2항 및 제3항의 규정에 의한 신변안전조치의 신청 또는 요청은 별지 제15호서식에 의한다.', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3233, '제17조(신변안전조치의 이행통보) 영 제8조제1항의 규정에 의한 신변안전조치의 이행통보는 별지 제16호서식에 의한다.', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3234, '제18조(구조금의 신청) 영 제10조의 규정에 의한 구조금의 신청은 별지 제17호서식에 의한다. 이 경우 가명으로 구조금을 신청하는 때에는 신원관리카드에 기재된 가명으로 하여야 한다.', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3235, '제19조(구조심의결과 통보) 범죄신고자등구조심의회(이하 "심의회"라 한다)가 영 제11조의 규정에 의하여 구조결정을 한 때에는 심의회의 간사는 신원관리카드를 관리하는 검사에게 별지 제18호서식에 의하여 범죄신고자등구조심의결과를 통보하여야 한다.', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3236, '제20조(구조결정서의 작성 등)', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3237, '제21조(구조금의 지급청구) 영 제19조의 규정에 의한 구조금의 지급청구는 별지 제22호서식에 의한다.', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3238, '제22조(장부 등의 비치) 심의회는 다음 각호의 장부 및 서류를 비치하여야 한다.', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3239, '제23조(법무부장관에의 보고) 심의회는 매분기말 다음달 5일까지 별지 제25호서식에 의한 범죄신고자등구조금지급분기보고서를 대검찰청을 경유하여 법무부장관에게 제출하여야 한다. 이 경우 제20조제1항의 규정에 의한 가구조결정서 또는 동조제2항의 규정에 의한 구조결정서 등본 1통을 첨부하여야 한다.', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3240, '제24조(주요변동상황의 통지신청 등) 법 제15조의 규정에 의한 피고인등에 관련된 주요변동상황의 통지신청은 별지 제26호서식에 의하고, 주요변동상황의 통지는 별지 제27호서식에 의한다.', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3241, '제25조(서식 등의 관리 등)', 443);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3242, '제1조(목적) 이 법은 교도작업의 관리 및 교도작업특별회계의 설치ㆍ운용에 관한 사항을 규정함으로써 효율적이고 합리적인 교도작업의 운영을 도모함을 목적으로 한다.', 444);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3243, '제2조(정의) 이 법에서 사용하는 용어의 정의는 다음과 같다.', 444);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3244, '제3조(다른 법률의 적용) 교도작업에 관하여 이 법에 규정된 것을 제외하고는 「형의 집행 및 수용자의 처우에 관한 법률」을 적용한다.', 444);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3245, '제4조(교도작업제품의 공고) 법무부장관은 교도작업으로 생산되는 제품의 종류와 수량을 회계연도 개시 1개월 전까지 공고하여야 한다.', 444);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3246, '제5조(교도작업제품의 우선구매) 국가, 지방자치단체 또는 공공기관은 그가 필요로 하는 물품이 제4조에 따라 공고된 것인 경우에는 공고된 제품 중에서 우선적으로 구매하여야 한다.', 444);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3247, '제6조(교도작업에의 민간참여)', 444);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3248, '제7조(교도작업제품의 민간판매) 교도작업으로 생산된 제품은 민간기업 등에 직접 판매하거나 위탁하여 판매할 수 있다.', 444);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3249, '제8조(교도작업특별회계의 설치ㆍ운용)', 444);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3250, '제9조(특별회계의 세입ㆍ세출)', 444);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3251, '제10조(일반회계로부터의 전입) 특별회계는 세입총액이 세출총액에 미달된 경우 또는 시설 개량이나 확장에 필요한 경우에는 예산의 범위에서 일반회계로부터 전입을 받을 수 있다.', 444);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3252, '제11조(일시 차입 등)', 444);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3253, '제11조의2(잉여금의 처리) 특별회계의 결산상 잉여금은 다음 연도의 세입에 이입한다.', 444);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3254, '제12조(예비비) 특별회계는 예측할 수 없는 예산 외의 지출 또는 예산을 초과하는 지출에 충당하기 위하여 세출예산에 예비비를 계상(計上)할 수 있다.', 444);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3255, '제1조(목적) 이 영은 「교도작업의 운영 및 특별회계에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 445);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3256, '제2조(다른 법령과의 관계) 「교도작업의 운영 및 특별회계에 관한 법률」(이하 "법"이라 한다)에 따른 교도작업의 운영 및 교도작업특별회계(이하 "특별회계"라 한다)에 관하여 다른 법령에 특별한 규정이 있는 경우를 제외하고는 이 영에서 정하는 바에 따른다.', 445);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3257, '제3조(생산공급계획의 보고) 교도작업으로 생산되는 제품(이하 "교도작업제품"이라 한다)을 생산하는 교정시설의 장(이하 "소장"이라 한다)은 국가, 지방자치단체 또는 공공기관(이하 "수요기관"이라 한다)의 수요량과 해당 지역의 생산실태 등을 조사하여 법무부령으로 정하는 사항이 포함된 다음 연도의 생산공급계획을 수립하여 매년 10월 30일까지 법무부장관에게 보고하여야 한다.', 445);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3258, '제4조(공고에 필요한 조사)', 445);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3259, '제5조(교도작업제품의 종류 및 수량의 공고)', 445);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3260, '제6조(교도작업의 종류)', 445);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3261, '제7조(교도작업제품의 판매방법) 법무부장관은 교도작업제품의 전시 및 판매를 위하여 필요한 시설을 설치ㆍ운영하거나 전자상거래 등의 방법으로 교도작업제품을 판매할 수 있다.', 445);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3262, '제8조(특별회계의 회계기준)', 445);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3263, '제9조(일반경쟁계약) 특별회계의 세입ㆍ세출의 원인이 되는 계약을 담당하는 공무원(이하 "계약담당자"라 한다)은 다음 각 호의 어느 하나에 해당하는 계약으로서 추정가격이 「국가를 당사자로 하는 계약에 관한 법률 시행령」 제26조제1항제5호가목에 따른 추정가격의 2배를 초과하는 계약을 하려는 경우에는 일반경쟁에 부쳐야 한다. <개정 2010.7.21>', 445);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3264, '제10조(수의계약) 계약담당자는 제9조에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 수의계약으로 할 수 있다.', 445);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3265, '제1조(목적) 이 규칙은 「교도작업의 운영 및 특별회계에 관한 법률」 및 「교도작업의 운영 및 특별회계에 관한 법률 시행령」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 446);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3266, '제2조(다른 법령과의 관계) 「교도작업의 운영 및 특별회계에 관한 법률」(이하 "법"이라 한다)에 따른 교도작업의 운영 및 교도작업특별회계(이하 "특별회계"라 한다)에 관하여 다른 법령에 특별한 규정이 있는 경우를 제외하고는 이 규칙에서 정하는 바에 따른다.', 446);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3267, '제3조(생산공급계획의 보고) 교정시설의 장(이하 "소장"이라 한다)이 「교도작업의 운영 및 특별회계에 관한 법률 시행령」(이하 "영"이라 한다) 제3조에 따라 법무부장관에게 보고하는 다음 연도의 생산공급계획서에는 다음 각 호의 사항이 포함되어야 한다.', 446);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3268, '제4조(교도작업 참여 신청 등)', 446);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3269, '제5조(단기계약)', 446);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3270, '제6조(교도작업의 종류)', 446);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3271, '제7조(계약서 작성요령) 특별회계의 세입ㆍ세출의 원인이 되는 계약을 담당하는 공무원(이하 "계약담당자"라 한다)은 계약서를 작성할 때에는 다음 각 호의 사항을 유의하여야 한다.', 446);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3272, '제8조(낙찰가격과 예정가격 명세의 재조정) 계약의 목적을 구성하는 내용이 두 종류 이상일 경우에는 낙찰자 또는 계약의 상대방으로 하여금 낙찰총액에 부합되는 명세서를 제출하게 하여, 그 명세서상 금액과 예정가격의 명세금액을 낙찰액과 예정가격과의 비율에 해당하는 금액의 범위 내로 조정한 금액을 계약금액의 명세로 하여야 한다.', 446);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3273, '제9조(수의계약의 절차)', 446);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3274, '제10조(계약불이행) 계약담당자는 상대방의 계약불이행으로 인한 손해배상금ㆍ지체상금(遲滯償金) 또는 계약보증금 등을 지출액과 상계(相計)하여야 할 때에는 그 관계 서류와 산출계산명세서를 관계 지출관 또는 출납공무원에게 제출하여야 한다.', 446);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3275, '제1조(목적) 이 규칙은 「약식절차에서의 전자문서 이용 등에 관한 법률」(이하 "법"이라 한다)이 대법원규칙에 위임한 사항, 법에 따른 약식절차에서의 전자적 송달과 통지의 구체적 절차, 전자문서의 이용ㆍ관리 등에 관하여 필요한 사항을 규정함을 목적으로 한다.', 447);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3276, '제2조(전자화문서의 작성과 예외)', 447);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3277, '제3조(문서의 전자적 접수 등)', 447);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3278, '제4조(피고인에 대한 약식명령 등의 전자적 송달ㆍ통지)', 447);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3279, '제5조(검사에 대한 약식명령 등의 전자적 송달 또는 통지)', 447);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3280, '제6조(출력물로써 하는 약식명령 등의 송달) 법원은 약식명령이나 그 밖의 소송에 관한 서류의 송달에 관한 사항이 제4조제1항의 전자우편 또는 휴대전화 문자서비스로 도달하지 아니하였음이 객관적으로 증명되는 때 또는 그 밖에 피고인이 자신에게 책임질 수 없는 사유로 전자적 송달을 받을 수 없음을 소명한 경우에는 법 제9조제1항에 의하여 약식명령이나 그 밖의 소송에 관한 서류를 종이문서로 출력하여 송달할 수 있다.', 447);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3281, '제7조(정식재판청구) 「형사소송법」 제453조에 따른 약식명령에 대한 정식재판의 청구는 종이문서로 법원에 제출하여야 한다.', 447);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3282, '제8조(공판절차에 의하여 심판하는 경우의 처리) 「형사소송법」 제450조 또는 제453조에 따라 공판절차에 의하여 심판하는 경우 법원은 검사에게 그 사실을 전자적으로 통지하고, 다음 문서를 전자적으로 송부하여야 한다.', 447);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3283, '제9조(이송) 법원이 「형사소송법」 제16조의2에 의하여 법에 따른 약식사건을 군사법원으로 이송할 경우 법원사무관등은 해당 약식사건의 전자문서 및 전자화문서를 종이문서로 출력하여 이송받을 군사법원으로 송부한다.', 447);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3284, '제10조(약식명령의 경정)', 447);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3285, '제11조(전자문서의 열람ㆍ출력)', 447);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3286, '제1조(목적) 이 법은 생활환경 또는 자연환경 등에 위해(危害)를 끼치는 환경오염 또는 환경훼손 행위에 대한 가중처벌 및 단속ㆍ예방 등에 관한 사항을 정함으로써 환경보전에 이바지하는 것을 목적으로 한다.', 448);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3287, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다. <개정 2011.7.21, 2011.7.28, 2011.8.4, 2013.5.22, 2013.6.4, 2015.12.22, 2017.1.17, 2024.2.6, 2025.3.25>', 448);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3288, '제3조(오염물질 불법배출의 가중처벌)', 448);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3289, '제4조(환경보호지역 오염행위 등의 가중처벌)', 448);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3290, '제5조(과실범)', 448);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3291, '제6조(멸종위기 야생생물의 포획 등의 가중처벌) 매매를 목적으로 「야생생물 보호 및 관리에 관한 법률」 제67조, 제68조제1항제1호부터 제3호까지 또는 제69조제1항제1호의 죄를 범한 자는 같은 법 각 해당 조에서 정한 징역과 매매로 인하여 취득하였거나 취득할 수 있는 가액(價額)의 2배 이상 10배 이하에 해당하는 벌금을 병과(倂科)한다. <개정 2011.7.28, 2014.3.24>', 448);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3292, '제7조(폐기물 불법처리의 가중처벌) 단체 또는 집단의 구성원으로서 영리를 목적으로 「폐기물관리법」 제63조의 죄를 범한 자는 2년 이상 10년 이하의 징역과 폐기물을 버리거나 매립함으로 인하여 취득한 가액의 2배 이상 10배 이하에 해당하는 벌금을 병과한다.', 448);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3293, '제8조(누범의 가중) 제3조부터 제5조까지 또는 제7조의 죄로 금고 이상의 형을 선고받고 그 집행이 끝나거나 집행을 면제받은 지 3년 내에 제3조제1항, 제4조제3항 또는 제7조의 죄를 범한 자는 무기 또는 5년 이상의 유기징역에 처한다. 이 경우 제7조의 죄를 범한 자는 폐기물을 버리거나 매립함으로 인하여 취득한 가액의 2배 이상 10배 이하에 해당하는 벌금을 병과한다.', 448);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3294, '제9조(명령 불이행자에 대한 처벌 등)', 448);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3295, '제10조(양벌규정) 법인의 대표자나 법인 또는 개인의 대리인, 사용인, 그 밖의 종업원이 그 법인 또는 개인의 업무에 관하여 제5조부터 제7조까지의 어느 하나에 해당하는 위반행위를 하면 그 행위자를 벌하는 외에 그 법인 또는 개인에게도 해당 조문의 벌금형을 과(科)한다. 다만, 법인 또는 개인이 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니하였을 경우에는 그러하지 아니하다.', 448);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3296, '제11조(추정) 사람의 생명ㆍ신체, 상수원 또는 자연생태계 등(이하 "생명ㆍ신체등"이라 한다)에 위해(제3조제3항 각 호의 어느 하나에 해당하는 경우를 포함한다. 이하 이 조에서 같다)를 끼칠 정도로 오염물질을 불법배출한 사업자가 있는 경우 그 오염물질의 불법배출에 의하여 위해가 발생할 수 있는 지역에서 같은 종류의 오염물질로 인하여 생명ㆍ신체등에 위해가 발생하고 그 불법배출과 발생한 위해 사이에 상당한 개연성이 있는 때에는 그 위해는 그 사업자가 불법배출한 물질로 인하여 발생한 것으로 추정한다.', 448);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3297, '제12조(과징금)', 448);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3298, '제13조(행정처분 등)', 448);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3299, '제14조(행정처분 효과의 승계)', 448);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3300, '제15조(포상금) 환경법위반행위가 발각되기 전에 수사기관, 환경부장관, 지방환경관서의 장, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장(자치구의 구청장을 말한다)에게 신고한 자에게는 대통령령으로 정하는 바에 따라 포상금을 지급할 수 있다. <개정 2013.5.22>', 448);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3301, '제15조의2(환경감시관)', 448);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3302, '제15조의3(환경감시조직) 국가는 환경법위반행위의 감시 및 단속을 위하여 관계 행정기관과 지방자치단체의 공무원으로 구성된 환경감시조직을 설치ㆍ운영할 수 있다.', 448);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3303, '제16조(사업장의 출입 등)', 448);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3304, '제17조(관계 기관의 협조) 환경부장관은 관계 기관의 장에게 이 법에 따른 행정처분과 환경법위반행위의 단속 및 예방을 위하여 필요한 자료의 제출을 요구할 수 있다. 이 경우 관계 기관의 장은 특별한 사유가 없으면 요구받은 자료를 제출하여야 한다. <개정 2025.3.25>', 448);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3305, '제18조(자료의 전산관리) 환경부장관은 환경법위반행위의 단속 및 예방을 위하여 필요한 자료를 전산관리할 수 있다.', 448);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3306, '제19조(권한의 위임) 이 법에 따른 환경부장관의 권한은 대통령령으로 정하는 바에 따라 그 일부를 시ㆍ도지사 또는 지방환경관서의 장에게 위임할 수 있다.', 448);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3307, '제1조(목적) 이 영은 「환경범죄 등의 단속 및 가중처벌에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 449);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3308, '제2조 삭제 <2020.11.10>', 449);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3309, '제3조(과징금의 산정방법)', 449);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3310, '제4조 삭제 <2020.11.10>', 449);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3311, '제5조 삭제 <2020.11.10>', 449);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3312, '제6조(과징금의 부과 및 납부)', 449);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3313, '제7조 삭제 <2020.11.10>', 449);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3314, '제8조(행정처분의 기준) 법 제13조제1항에 따른 행정처분(이하 "행정처분"이라 한다)의 기준은 별표 2와 같다. <개정 2025.9.23>', 449);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3315, '제9조(표지판) 법 제13조제4항에 따른 불법배출시설 표지판은 별표 3과 같이 하며, 일반인이 보기 쉽도록 불법배출시설의 입구에 지상 1미터 이상의 높이에 설치하여야 한다.', 449);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3316, '제9조의2(행정처분 이력 등의 확인)', 449);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3317, '제10조(포상금의 지급)', 449);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3318, '제11조(환경감시관의 자격ㆍ임명)', 449);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3319, '제12조(환경감시관의 임명의 해제)', 449);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3320, '제13조(환경감시관의 직무) 환경감시관의 구체적인 직무 범위는 다음 각 호와 같다. <개정 2020.11.10>', 449);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3321, '제14조(활동비 지급) 환경감시관에게는 예산의 범위에서 필요한 활동비를 지급한다.', 449);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3322, '제15조(증표)', 449);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3323, '제16조(오염도 검사기관) 법 제16조제2항에서 "대통령령으로 정하는 검사기관"이란 다음 각 호의 어느 하나에 해당하는 기관을 말한다.', 449);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3324, '제17조(권한의 위임)', 449);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3325, '제18조(보고) 시ㆍ도지사, 지방환경관서의 장은 제17조에 따라 위임받은 업무를 처리하였을 때에는 환경부장관이 정하는 바에 따라 그 내용을 환경부장관에게 보고하여야 한다.', 449);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3326, '제1조(목적) 이 법은 아동학대범죄의 처벌 및 그 절차에 관한 특례와 피해아동에 대한 보호절차 및 아동학대행위자에 대한 보호처분을 규정함으로써 아동을 보호하여 아동이 건강한 사회 구성원으로 성장하도록 함을 목적으로 한다.', 450);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3327, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다. <개정 2016.1.6, 2016.5.29, 2021.3.16>', 450);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3328, '제3조(다른 법률과의 관계) 아동학대범죄에 대하여는 이 법을 우선 적용한다. 다만, 「성폭력범죄의 처벌 등에 관한 특례법」, 「아동ㆍ청소년의 성보호에 관한 법률」에서 가중처벌되는 경우에는 그 법에서 정한 바에 따른다.', 450);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3329, '제4조(아동학대살해ㆍ치사)', 451);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3330, '제5조(아동학대중상해) 제2조제4호가목부터 다목까지의 아동학대범죄를 범한 사람이 아동의 생명에 대한 위험을 발생하게 하거나 불구 또는 난치의 질병에 이르게 한 때에는 3년 이상의 징역에 처한다.', 451);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3331, '제6조(상습범) 상습적으로 제2조제4호가목부터 파목까지의 아동학대범죄를 범한 자는 그 죄에 정한 형의 2분의 1까지 가중한다. 다만, 다른 법률에 따라 상습범으로 가중처벌되는 경우에는 그러하지 아니하다.', 451);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3332, '제7조(아동복지시설의 종사자 등에 대한 가중처벌) 제10조제2항 각 호에 따른 아동학대 신고의무자가 보호하는 아동에 대하여 아동학대범죄를 범한 때에는 그 죄에 정한 형의 2분의 1까지 가중한다.', 451);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3333, '제8조(형벌과 수강명령 등의 병과)', 451);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3334, '제9조(친권상실청구 등)', 451);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3335, '제10조(아동학대범죄 신고의무와 절차)', 452);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3336, '제10조의2(불이익조치의 금지) 누구든지 아동학대범죄신고자등에게 아동학대범죄신고등을 이유로 불이익조치를 하여서는 아니 된다.', 452);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3337, '제10조의3(아동학대범죄신고자등에 대한 보호조치) 아동학대범죄신고자등에 대하여는 「특정범죄신고자 등 보호법」 제7조부터 제13조까지의 규정을 준용한다.', 452);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3338, '제10조의4(고소에 대한 특례)', 452);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3339, '제11조(현장출동)', 452);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3340, '제11조의2(조사)', 452);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3341, '제12조(피해아동 등에 대한 응급조치)', 452);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3342, '제13조(아동학대행위자에 대한 긴급임시조치)', 452);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3343, '제14조(임시조치의 청구)', 452);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3344, '제15조(응급조치ㆍ긴급임시조치 후 임시조치의 청구)', 452);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3345, '제16조(피해아동에 대한 변호사 선임의 특례)', 452);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3346, '제17조(준용)', 452);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3347, '제17조의2(증인에 대한 신변안전조치)', 452);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3348, '제18조(관할)', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3349, '제19조(아동학대행위자에 대한 임시조치)', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3350, '제20조(임시조치의 고지) 법원은 제19조제1항제6호 및 제7호의 조치를 한 경우에는 그 사실을 아동학대행위자의 보조인(제44조에서 준용하는 「가정폭력범죄의 처벌 등에 관한 특례법」 제28조에 따른 보조인을 말한다. 이하 같다)이 있는 경우에는 보조인에게, 보조인이 없는 경우에는 아동학대행위자가 지정한 사람에게 통지하여야 한다. 이 경우 제19조제1항제7호의 조치를 하였을 때에는 아동학대행위자에게 변호사 등 보조인을 선임할 수 있으며 항고를 제기할 수 있음을 고지하여야 한다.', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3351, '제21조(임시조치의 집행)', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3352, '제22조(임시조치의 변경)', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3353, '제23조(임시로 후견인의 임무를 수행할 사람)', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3354, '제24조(사법경찰관의 사건송치) 사법경찰관은 아동학대범죄를 신속히 수사하여 사건을 검사에게 송치하여야 한다. 이 경우 사법경찰관은 해당 사건을 아동보호사건으로 처리하는 것이 적절한 지에 관한 의견을 제시할 수 있다.', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3355, '제25조(검사의 결정 전 조사)', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3356, '제26조(조건부 기소유예) 검사는 아동학대범죄를 수사한 결과 다음 각 호의 사유를 고려하여 필요하다고 인정하는 경우에는 아동학대행위자에 대하여 상담, 치료 또는 교육 받는 것을 조건으로 기소유예를 할 수 있다.', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3357, '제27조(아동보호사건의 처리)', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3358, '제28조(검사의 송치)', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3359, '제29조(법원의 송치) 법원은 아동학대행위자에 대한 피고사건을 심리한 결과 제36조에 따른 보호처분을 하는 것이 적절하다고 인정하는 경우에는 결정으로 사건을 관할 법원에 송치할 수 있다.', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3360, '제30조(송치 시의 아동학대행위자 처리)', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3361, '제31조(송치서)', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3362, '제32조(이송)', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3363, '제33조(보호처분의 효력) 제36조에 따른 보호처분이 확정된 경우에는 그 아동학대행위자에 대하여 같은 범죄사실로 다시 공소를 제기할 수 없다. 다만, 제41조제1호에 따라 송치된 경우에는 그러하지 아니하다.', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3364, '제34조(공소시효의 정지와 효력)', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3365, '제35조(비밀엄수 등의 의무)', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3366, '제36조(보호처분의 결정 등)', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3367, '제37조(보호처분의 기간) 제36조제1항제1호부터 제3호까지 및 제5호부터 제8호까지의 규정에 따른 보호처분의 기간은 1년을 초과할 수 없으며, 같은 항 제4호의 사회봉사ㆍ수강명령의 시간은 각각 200시간을 초과할 수 없다.', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3368, '제38조(보호처분 결정의 집행)', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3369, '제39조(보고와 의견 제출 등)', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3370, '제40조(보호처분의 변경)', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3371, '제41조(보호처분의 취소) 법원은 보호처분을 받은 아동학대행위자가 제36조제1항제4호부터 제8호까지의 규정에 따른 보호처분 결정을 이행하지 아니하거나 그 집행에 따르지 아니하면 직권 또는 검사, 피해아동, 그 법정대리인, 변호사, 시ㆍ도지사, 시장ㆍ군수ㆍ구청장, 보호관찰관이나 수탁기관의 장의 청구에 의하여 결정으로 그 보호처분을 취소하고 다음 각 호에 따라 처리하여야 한다. <개정 2020.3.24>', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3372, '제42조(보호처분의 종료) 법원은 아동학대행위자의 성행이 교정되어 정상적인 가정생활이 유지될 수 있다고 판단되거나 그 밖에 보호처분을 계속할 필요가 없다고 인정하는 경우에는 직권 또는 검사, 피해아동, 그 법정대리인, 변호사, 시ㆍ도지사, 시장ㆍ군수ㆍ구청장, 보호관찰관이나 수탁기관의 장의 청구에 의하여 결정으로 보호처분의 전부 또는 일부를 종료할 수 있다. <개정 2020.3.24>', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3373, '제43조(비용의 부담)', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3374, '제44조(준용) 아동보호사건의 조사ㆍ심리ㆍ보호처분 및 민사처리에 관한 특례 등에 대하여는 「가정폭력범죄의 처벌 등에 관한 특례법」 제18조의2, 제19조부터 제28조까지, 제30조부터 제39조까지, 제42조, 제56조부터 제62조까지의 규정을 준용한다. 이 경우 "가정보호사건"은 "아동보호사건"으로, "가정폭력행위자"는 "아동학대행위자"로, "피해자"는 "피해아동"으로, "가정폭력범죄"는 "아동학대범죄"로 본다.', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3375, '제45조(항고와 재항고)', 453);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3376, '제46조(피해아동보호명령사건의 관할)', 454);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3377, '제47조(가정법원의 피해아동에 대한 보호명령)', 454);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3378, '제48조(보조인)', 454);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3379, '제49조(국선보조인)', 454);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3380, '제50조(피해아동보호명령의 집행 및 취소와 변경)', 454);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3381, '제51조(피해아동보호명령의 기간)', 454);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3382, '제52조(피해아동에 대한 임시보호명령)', 454);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3383, '제53조(이행실태의 조사)', 454);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3384, '제54조(병합심리) 법원은 사건의 관련성이 인정되어 병합하여 심리할 필요성이 있는 경우에는 피해아동보호명령사건과 아동보호사건을 병합하여 심리할 수 있다.', 454);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3385, '제55조(아동학대전담공무원 등에 대한 교육) 법무부장관 등 관계 행정기관의 장은 아동학대전담공무원, 사법경찰관리 및 아동보호전문기관의 종사자에게 아동학대사건의 조사와 사례관리에 필요한 전문지식, 이 법에서 정한 절차, 관련 법제도, 국제인권조약에 명시된 아동의 인권 및 피해아동 보호를 위한 조사방법 등에 관하여 교육을 실시하여야 한다. <개정 2020.3.24, 2021.1.26>', 454);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3386, '제55조의2(자료요청 및 면담)', 454);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3387, '제56조(준용)', 454);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3388, '제57조(항고와 재항고)', 454);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3389, '제58조(위임규정) 피해아동보호명령사건의 조사ㆍ심리에 필요한 사항은 대법원규칙으로 정한다.', 454);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3390, '제59조(보호처분 등의 불이행죄)', 455);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3391, '제60조(피해자 등에 대한 강요행위) 폭행이나 협박으로 아동학대범죄의 피해아동 또는 제2조제2호에 따른 보호자를 상대로 합의를 강요한 사람은 7년 이하의 징역에 처한다.', 455);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3392, '제61조(업무수행 등의 방해죄)', 455);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3393, '제62조(비밀엄수 등 의무의 위반죄)', 455);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3394, '제62조의2(불이익조치 금지 위반죄)', 455);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3395, '제63조(과태료)', 455);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3396, '제64조(벌칙적용에 있어서 공무원의 의제) 아동보호전문기관의 장과 그 직원 및 진술조력인은 「형법」 제129조부터 제132조까지의 규정에 따른 벌칙의 적용에서는 공무원으로 본다.', 455);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3397, '제1조(목적) 이 영은 「아동학대범죄의 처벌 등에 관한 특례법」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 456);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3398, '제2조(피해아동 보호의 원칙) 검사, 사법경찰관리, 보호관찰관, 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ도지사ㆍ특별자치도지사(이하 "시ㆍ도지사"라 한다), 시장ㆍ군수ㆍ구청장(자치구의 구청장을 말한다. 이하 같다), 「아동복지법」 제22조제4항에 따른 아동학대전담공무원(이하 "아동학대전담공무원"이라 한다), 같은 법 제45조에 따른 아동보호전문기관(이하 "아동보호전문기관"이라 한다)의 장과 그 직원 등은 「아동학대범죄의 처벌 등에 관한 특례법」(이하 "법"이라 한다)에 따른 처분 또는 청구 등을 할 경우에는 피해아동, 피해아동의 형제자매인 아동 및 피해아동과 동거하는 아동(이하 "피해아동등"이라 한다)의 안전과 보호 및 이익을 최우선으로 고려해야 한다. <개정 2020.9.29>', 456);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3399, '제3조(아동학대행위자의 재범 예방을 위한 시책 마련) 법무부장관은 법 제8조제1항에 따른 수강명령과 이수명령의 실시에 필요한 프로그램의 개발 및 관련 전문인력의 양성 등 아동학대행위자의 재범 예방을 위한 시책을 마련하여야 한다.', 456);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3400, '제4조(사건관리회의)', 456);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3401, '제5조(피해아동등의 의견 청취 등)', 456);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3402, '제5조의2(연고자 등의 기준) 법 제12조제1항제5호에 따른 연고자 등은 피해아동등의 친족이거나 피해아동등을 보호ㆍ양육한 이력이 있는 등 피해아동등과 특별한 연고가 있는 사람 중 피해아동등을 인도받기를 희망하는 사람이어야 한다.', 456);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3403, '제5조의3(피해아동등을 연고자 등에게 인도하는 절차 등)', 456);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3404, '제6조(아동학대전담공무원 등에 대한 교육) 법 제55조에 따라 아동학대전담공무원, 사법경찰관리 및 아동보호전문기관의 종사자에 대해 실시하는 교육에는 다음 각 호의 사항이 포함되어야 한다. <개정 2020.9.29, 2021.5.18>', 456);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3405, '제7조(민감정보 및 고유식별정보의 처리)', 456);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3406, '제8조(과태료의 부과기준) 법 제63조제1항에 따른 과태료의 부과기준은 별표 2와 같다. <개정 2025.6.20>', 456);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3407, '제1조(목적) 이 규칙은 「아동학대범죄의 처벌 등에 관한 특례법」 및 같은 법 시행령의 시행에 필요한 사항을 규정함을 목적으로 한다.', 457);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3408, '제2조(친권상실청구 등)', 457);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3409, '제3조(현장출동)', 457);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3410, '제3조의2(조사)', 457);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3411, '제4조(피해아동에 대한 응급조치)', 457);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3412, '제5조(긴급임시조치)', 457);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3413, '제6조(임시조치의 청구)', 457);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3414, '제7조(임시조치의 변경)', 457);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3415, '제8조(검사의 결정 전 조사) 검사가 법 제25조제1항에 따라 보호관찰소의 장에게 결정 전 조사를 요구할 때에는 별지 제25호서식에 따르고, 법 제25조제4항에 따라 시ㆍ도지사, 시장ㆍ군수ㆍ구청장 또는 아동보호전문기관의 장에게 자료의 제출을 요구할 때에는 별지 제26호서식에 따른다. <개정 2020.9.28>', 457);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3416, '제9조(송치)', 457);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3417, '제9조의2(보호처분 결정의 집행) 법 제38조제2항에 따라 보호처분의 집행담당자가 아동학대행위자의 보호처분 이행상황에 대해 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 통보할 때에는 별지 제28호의2서식에 따른다.', 457);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3418, '제10조(보호처분의 변경 등)', 457);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3419, '제10조의2(피해아동보호명령의 청구 등)', 457);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3420, '제10조의3(피해아동보호명령의 취소와 종류변경 신청 등)', 457);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3421, '제11조(의무위반사실의 통보) 사법경찰관리, 보호관찰관, 수탁기관의 장 등은 법 제63조제1항제2호부터 제5호까지에 따른 의무위반사실을 알게 된 때에는 그 사실을 별지 제32호서식에 따라 관계 행정기관의 장에게 통보할 수 있다. <개정 2020.9.28>', 457);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3422, '제1조(목적) 이 영은 「전자장치 부착 등에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다. <개정 2009.7.30, 2013.5.31, 2020.8.5>', 458);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3423, '제2조(위치추적 전자장치의 구성) 「전자장치 부착 등에 관한 법률」(이하 "법"이라 한다) 제2조제4호에 따른 위치추적 전자장치(이하 "전자장치"라 한다)는 다음 각 호로 구성한다. <개정 2009.7.30, 2013.5.31, 2018.2.13, 2020.8.5>', 458);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3424, '제3조 삭제 <2021.9.14>', 458);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3425, '제3조의2(출연금 등의 지급ㆍ사용 및 관리)', 458);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3426, '제4조(조사)', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3427, '제5조(부착명령 청구서의 기재사항 및 방식)', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3428, '제6조(집행지휘) 검사는 부착명령의 판결이 확정되면 지체 없이 부착명령을 선고받은 사람(이하 "피부착명령자"라 한다)의 주거지를 관할하는 보호관찰소의 장에게 법 제12조제2항의 부착명령 집행을 지휘한 서면을 보내야 한다.', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3429, '제7조(부착명령의 집행)', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3430, '제8조(부착명령의 집행정지)', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3431, '제9조(부착명령 집행정지자의 이송) 수용기관의 장은 법 제13조제6항에 따라 부착명령의 집행이 정지된 사람을 다른 수용기관으로 이송할 경우에는 그의 주거지를 관할하는 보호관찰소의 장과 해당 수용기관의 장에게 그 사실을 통보하여야 한다. <개정 2010.7.12, 2018.6.12>', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3432, '제10조(전자장치의 일시 분리)', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3433, '제11조(전자장치의 효용 유지 의무) 피부착자는 전자장치의 부착기간 중 법 제14조제1항에 따라 전자장치의 효용 유지를 위하여 다음 각 호의 사항을 준수하여야 한다.', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3434, '제12조(주거이전ㆍ국내여행 및 출국 허가 등)', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3435, '제12조의2(부착기간의 연장 등의 신청)', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3436, '제13조(상담치료 등의 집행)', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3437, '제14조(수신자료의 사용) 보호관찰소의 장 및 법 제16조의3에 따른 위치추적 관제센터(이하 "위치추적 관제센터"라 한다)의 장은 법 제16조제2항제1호, 제3호 및 제4호에 따라 수신자료가 사용된 경우에는 그 사실을 대장에 적고 이를 비치해야 한다. <개정 2010.7.12, 2018.6.12, 2021.9.14, 2024.1.9>', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3438, '제14조의2(수신자료 열람 또는 조회)', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3439, '제14조의3(긴급 수신자료 열람 또는 조회)', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3440, '제14조의4(열람 또는 조회한 수신자료의 보존ㆍ폐기 등)', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3441, '제14조의5(수신자료 사용사건의 결과 통지 등)', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3442, '제14조의6(수신자료 관련 비밀누설 금지 등) 수신자료를 열람 또는 조회한 사람은 그로 인하여 알게 된 타인의 비밀을 누설하거나 피부착자의 명예를 훼손하지 아니하도록 하여야 한다.', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3443, '제15조(수신자료의 폐기)', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3444, '제15조의2(피부착자의 신상정보 제공 등)', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3445, '제16조(부착명령의 임시해제 신청)', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3446, '제17조(부착명령 임시해제의 심사 및 결정)', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3447, '제18조(임시해제의 취소 등)', 459);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3448, '제18조의2(보호관찰 기간의 연장 등)', 460);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3449, '제18조의3(준용규정) 보호관찰대상자의 조사, 집행지휘, 주거이전 허가, 상담치료, 임시해제 및 취소 등에 관하여는 제4조부터 제6조까지, 제12조제1항부터 제7항까지, 제13조, 제16조, 제17조제1항ㆍ제2항ㆍ제4항 및 제18조제1항ㆍ제2항을 준용한다. 이 경우 "부착명령"은 "보호관찰명령"으로, "부착기간"은 "보호관찰 기간"으로, "피부착명령청구자"는 "피보호관찰명령청구자"로, "피부착명령자"는 "피보호관찰명령자"로, "피부착자"는 "보호관찰대상자"로, "전자장치 부착"은 "보호관찰"로 본다. <개정 2020.8.5>', 460);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3450, '제19조(전자장치 부착 적합성조사)', 461);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3451, '제19조의2(결정의 고지 등)', 461);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3452, '제20조(치료감호시설의 장 등의 통보)', 461);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3453, '제21조(준용) 이 장에 따른 전자장치 부착에 관하여는 제7조부터 제12조까지, 제12조의2 및 제13조부터 제18조까지의 규정을 준용한다. <개정 2010.7.12>', 461);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3454, '제22조(집행유예와 부착명령의 집행) 법 제28조제1항에 따라 집행유예와 함께 전자장치 부착을 명하는 법원의 판결이 확정된 사람은 판결 확정 후 10일 이내에 보호관찰소에 출석하여 법 제29조제1항에 따른 부착명령의 집행에 따라야 한다.', 462);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3455, '제23조(준용) 이 장에 따른 부착명령에 관하여는 제4조, 제6조부터 제12조까지, 제12조의2 및 제13조부터 제18조까지의 규정을 준용한다. <개정 2010.7.12>', 462);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3456, '제23조의2(보석조건 전자장치 부착 결정 전 조사)', 463);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3457, '제23조의3(보석허가 결정문의 송부 등) 법원은 긴급한 필요가 있는 경우 법 제31조의3제1항에 따라 보호관찰소의 장에게 결정문의 등본을 송부하기 전에 팩스ㆍ전자우편 등의 방법으로 그 사본을 먼저 송부할 수 있다.', 463);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3458, '제23조의4(전자장치 부착 보석 피고인의 신고) 법 제31조의2제1항에 따라 보석조건으로 전자장치 부착명령을 받고 석방된 피고인(이하 "전자장치 보석피고인"이라 한다)은 법 제31조의3제2항에 따라 주거지를 관할하는 보호관찰소에 출석하여 신고하는 경우 법무부령으로 정하는 신고서를 제출해야 한다.', 463);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3459, '제23조의5(전자장치 부착 등)', 463);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3460, '제23조의6(보석조건 이행 상황 통지)', 463);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3461, '제23조의7(보석조건 위반 통지)', 463);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3462, '제23조의8(보석조건 변경 및 보석취소 통지) 법원은 「형사소송법」 제102조제1항 또는 제2항에 따라 보석조건을 변경하거나 취소한 경우 보호관찰소의 장에게 보석조건 변경이나 보석취소 결정문의 등본을 송부해야 한다. 이 경우 긴급한 경우에는 전화ㆍ팩스ㆍ전자우편 등의 방법으로 먼저 통지할 수 있다.', 463);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3463, '제23조의9(준용 규정) 이 장에 따른 전자장치 부착 등에 관하여는 제10조, 제14조의6 및 제15조를 준용한다. 이 경우 "피부착자"는 "전자장치 보석피고인"으로 본다.', 463);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3464, '제23조의10(잠정조치 결정문의 송부) 법원은 긴급한 필요가 있는 경우 법 제31조의6제1항에 따라 다음 각 호의 사람에게 결정문의 등본을 송부하기 전에 팩스ㆍ전자우편 등의 방법으로 그 사본을 먼저 송부할 수 있다.', 464);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3465, '제23조의11(전자장치 스토킹행위자의 신고)', 464);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3466, '제23조의12(전자장치의 부착 등)', 464);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3467, '제23조의13(전자장치 부착 사실의 통지 등)', 464);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3468, '제23조의14(피해자의 보호)', 464);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3469, '제23조의15(잠정조치의 연장ㆍ변경ㆍ취소 통지) 법원은 잠정조치의 연장ㆍ변경ㆍ취소 결정을 한 경우 법 제31조의6제7항에 따라 관할경찰관서의 장과 보호관찰소의 장에게 그 결정문의 등본을 지체 없이 송부해야 한다. 이 경우 긴급한 경우에는 전화ㆍ팩스ㆍ전자우편 등의 방법으로 먼저 통지할 수 있다.', 464);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3470, '제23조의16(불기소처분의 통지) 검사는 전자장치 스토킹행위자에 대해 불기소처분을 하여 「스토킹범죄의 처벌 등에 관한 법률」 제11조제5항에 따라 잠정조치 결정이 효력을 상실한 때에는 보호관찰소의 장에게 이를 지체 없이 통지해야 한다.', 464);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3471, '제23조의17(스토킹행위자 수신자료의 사용) 보호관찰소의 장 및 위치추적 관제센터의 장은 법 제31조의8제2항제1호, 제3호 및 제4호에 따라 스토킹행위자 수신자료가 사용된 경우에는 그 사실을 대장에 적고 이를 비치해야 한다.', 464);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3472, '제23조의18(스토킹행위자 수신자료의 폐기) 보호관찰소의 장 및 위치추적 관제센터의 장은 법 제31조의8제4항제1호 및 제2호에 따른 스토킹행위자 수신자료의 폐기를 위해 「형사사법절차 전자화 촉진법」 제2조제2호에 따른 형사사법업무 처리기관에 다음 각 호의 사항을 알아보거나 관련 자료의 열람 등 협조를 요청할 수 있다.', 464);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3473, '제23조의19(준용규정) 이 장에 따른 전자장치 부착 등에 관하여는 제7조제3항, 제10조, 제14조의2부터 제14조의6까지 및 제15조제2항을 준용한다. 이 경우 "피부착명령자" 및 "피부착자"는 각각 "전자장치 스토킹행위자"로, "수신자료"는 "스토킹행위자 수신자료"로 본다.', 464);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3474, '제24조(출소자 등의 인적사항 등 통보)', 465);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3475, '제25조(조사) 검사는 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제2호 및 제3항제2호에 따라 보호관찰소의 장에게 출소자등에 대한 법 제6조에 따른 조사를 요청할 때에는 수용시설의 장으로부터 통보받은 제24조제1항 각 호의 사항과 출소자등에 대한 범죄경력조회서, 연락처, 면담결과서 등을 통보하여야 한다.', 465);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3476, '제26조(부착명령 청구 사실의 통보) 검사는 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제4호 및 제3항제4호에 따라 출소자등에 대하여 부착명령을 청구한 경우에는 피청구인에게 지체 없이 서면으로 청구 사실을 통보하여야 한다.', 465);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3477, '제27조(부착명령 결정의 통지)', 465);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3478, '제28조(집행지휘)', 465);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3479, '제29조(민감정보 및 고유식별정보의 처리)', 465);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3480, '제1조(목적) 이 영은 「형사소송법」 제195조에 따라 검사와 사법경찰관의 상호협력과 일반적 수사준칙에 관한 사항을 규정함으로써 수사과정에서 국민의 인권을 보호하고, 수사절차의 투명성과 수사의 효율성을 보장함을 목적으로 한다.', 466);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3481, '제2조(적용 범위) 검사와 사법경찰관의 협력관계, 일반적인 수사의 절차와 방법에 관하여 다른 법령에 특별한 규정이 있는 경우를 제외하고는 이 영이 정하는 바에 따른다.', 466);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3482, '제3조(수사의 기본원칙)', 466);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3483, '제4조(불이익 금지) 검사와 사법경찰관은 피의자나 사건관계인이 인권침해 신고나 그 밖에 인권 구제를 위한 신고, 진정, 고소, 고발 등의 행위를 하였다는 이유로 부당한 대우를 하거나 불이익을 주어서는 안 된다.', 466);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3484, '제5조(형사사건의 공개금지 등)', 466);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3485, '제6조(상호협력의 원칙)', 467);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3486, '제7조(중요사건 협력절차)', 467);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3487, '제8조(검사와 사법경찰관의 협의)', 467);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3488, '제9조(수사기관협의회)', 467);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3489, '제10조(임의수사 우선의 원칙과 강제수사 시 유의사항)', 469);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3490, '제11조(회피) 검사 또는 사법경찰관리는 피의자나 사건관계인과 친족관계 또는 이에 준하는 관계가 있거나 그 밖에 수사의 공정성을 의심 받을 염려가 있는 사건에 대해서는 소속 기관의 장의 허가를 받아 그 수사를 회피해야 한다.', 469);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3491, '제12조(수사 진행상황의 통지)', 469);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3492, '제13조(변호인의 피의자신문 참여ㆍ조력)', 469);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3493, '제14조(변호인의 의견진술)', 469);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3494, '제15조(피해자 보호)', 469);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3495, '제16조(수사의 개시)', 470);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3496, '제16조의2(고소ㆍ고발 사건의 수리 등)', 470);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3497, '제17조(변사자의 검시 등)', 470);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3498, '제18조(검사의 사건 이송 등)', 470);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3499, '제19조(출석요구)', 471);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3500, '제20조(수사상 임의동행 시의 고지) 검사 또는 사법경찰관은 임의동행을 요구하는 경우 상대방에게 동행을 거부할 수 있다는 것과 동행하는 경우에도 언제든지 자유롭게 동행 과정에서 이탈하거나 동행 장소에서 퇴거할 수 있다는 것을 알려야 한다.', 471);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3501, '제21조(심야조사 제한)', 471);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3502, '제22조(장시간 조사 제한)', 471);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3503, '제23조(휴식시간 부여)', 471);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3504, '제24조(신뢰관계인의 동석)', 471);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3505, '제25조(자료ㆍ의견의 제출기회 보장)', 471);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3506, '제26조(수사과정의 기록)', 471);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3507, '제27조(긴급체포)', 472);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3508, '제28조(현행범인 조사 및 석방)', 472);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3509, '제29조(구속영장의 청구ㆍ신청)', 472);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3510, '제30조(구속 전 피의자 심문) 사법경찰관은 법 제201조의2제3항 및 같은 조 제10항에서 준용하는 법 제81조제1항에 따라 판사가 통지한 피의자 심문 기일과 장소에 체포된 피의자를 출석시켜야 한다.', 472);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3511, '제31조(체포ㆍ구속영장의 재청구ㆍ재신청) 검사 또는 사법경찰관은 동일한 범죄사실로 다시 체포ㆍ구속영장을 청구하거나 신청하는 경우(체포ㆍ구속영장의 청구 또는 신청이 기각된 후 다시 체포ㆍ구속영장을 청구하거나 신청하는 경우와 이미 발부받은 체포ㆍ구속영장과 동일한 범죄사실로 다시 체포ㆍ구속영장을 청구하거나 신청하는 경우를 말한다)에는 그 취지를 체포ㆍ구속영장 청구서 또는 신청서에 적어야 한다.', 472);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3512, '제32조(체포ㆍ구속영장 집행 시의 권리 고지)', 472);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3513, '제32조의2(체포ㆍ구속영장 사본의 교부)', 472);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3514, '제33조(체포ㆍ구속 등의 통지)', 472);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3515, '제34조(체포ㆍ구속영장 등본의 교부) 검사 또는 사법경찰관은 법 제214조의2제1항에 따른 자가 체포ㆍ구속영장 등본의 교부를 청구하면 그 등본을 교부해야 한다.', 472);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3516, '제35조(체포ㆍ구속영장의 반환)', 472);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3517, '제36조(피의자의 석방)', 472);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3518, '제37조(압수ㆍ수색 또는 검증영장의 청구ㆍ신청) 검사 또는 사법경찰관은 압수ㆍ수색 또는 검증영장을 청구하거나 신청할 때에는 압수ㆍ수색 또는 검증의 범위를 범죄 혐의의 소명에 필요한 최소한으로 정해야 하고, 수색 또는 검증할 장소ㆍ신체ㆍ물건 및 압수할 물건 등을 구체적으로 특정해야 한다. 이 경우 수사기밀이나 사건관계인의 개인정보가 압수ㆍ수색 또는 검증을 필요로 하는 사유의 소명에 필요한 정도를 넘어 불필요하게 노출되지 않도록 유의해야 한다. <개정 2023.10.17>', 472);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3519, '제38조(압수ㆍ수색 또는 검증영장의 제시ㆍ교부)', 472);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3520, '제39조(압수ㆍ수색 또는 검증영장의 재청구ㆍ재신청 등) 압수ㆍ수색 또는 검증영장의 재청구ㆍ재신청(압수ㆍ수색 또는 검증영장의 청구 또는 신청이 기각된 후 다시 압수ㆍ수색 또는 검증영장을 청구하거나 신청하는 경우와 이미 발부받은 압수ㆍ수색 또는 검증영장과 동일한 범죄사실로 다시 압수ㆍ수색 또는 검증영장을 청구하거나 신청하는 경우를 말한다)과 반환에 관해서는 제31조 및 제35조를 준용한다.', 472);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3521, '제40조(압수조서와 압수목록) 검사 또는 사법경찰관은 증거물 또는 몰수할 물건을 압수했을 때에는 압수의 일시ㆍ장소, 압수 경위 등을 적은 압수조서와 압수물건의 품종ㆍ수량 등을 적은 압수목록을 작성해야 한다. 다만, 피의자신문조서, 진술조서, 검증조서에 압수의 취지를 적은 경우에는 그렇지 않다.', 472);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3522, '제41조(전자정보의 압수ㆍ수색 또는 검증 방법)', 472);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3523, '제42조(전자정보의 압수ㆍ수색 또는 검증 시 유의사항)', 472);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3524, '제43조(검증조서) 검사 또는 사법경찰관은 검증을 한 경우에는 검증의 일시ㆍ장소, 검증 경위 등을 적은 검증조서를 작성해야 한다.', 472);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3525, '제44조(영장심의위원회) 법 제221조의5에 따른 영장심의위원회의 위원은 해당 업무에 전문성을 가진 중립적 외부 인사 중에서 위촉해야 하며, 영장심의위원회의 운영은 독립성ㆍ객관성ㆍ공정성이 보장되어야 한다.', 472);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3526, '제45조(시정조치 요구의 방법 및 절차 등)', 473);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3527, '제46조(징계요구의 방법 등)', 473);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3528, '제47조(구제신청 고지의 확인) 사법경찰관은 법 제197조의3제8항에 따라 검사에게 구제를 신청할 수 있음을 피의자에게 알려준 경우에는 피의자로부터 고지 확인서를 받아 사건기록에 편철한다. 다만, 피의자가 고지 확인서에 기명날인 또는 서명하는 것을 거부하는 경우에는 사법경찰관이 고지 확인서 끝부분에 그 사유를 적고 기명날인 또는 서명해야 한다.', 473);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3529, '제48조(동일한 범죄사실 여부의 판단 등)', 474);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3530, '제49조(수사경합에 따른 사건송치)', 474);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3531, '제50조(중복수사의 방지) 검사는 법 제197조의4제2항 단서에 따라 사법경찰관이 범죄사실을 계속 수사할 수 있게 된 경우에는 정당한 사유가 있는 경우를 제외하고는 그와 동일한 범죄사실에 대한 사건을 이송하는 등 중복수사를 피하기 위해 노력해야 한다.', 474);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3532, '제51조(사법경찰관의 결정)', 476);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3533, '제52조(검사의 결정)', 476);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3534, '제53조(수사 결과의 통지)', 476);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3535, '제54조(수사중지 결정에 대한 이의제기 등)', 476);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3536, '제55조(소재수사에 관한 협력 등)', 476);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3537, '제56조(사건기록의 등본)', 476);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3538, '제57조(송치사건 관련 자료 제공) 검사는 사법경찰관이 송치한 사건에 대해 검사의 공소장, 불기소결정서, 송치결정서 및 법원의 판결문을 제공할 것을 요청하는 경우 이를 사법경찰관에게 지체 없이 제공해야 한다.', 476);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3539, '제58조(사법경찰관의 사건송치)', 477);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3540, '제59조(보완수사요구의 대상과 범위)', 477);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3541, '제60조(보완수사요구의 방법과 절차)', 477);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3542, '제61조(직무배제 또는 징계 요구의 방법과 절차)', 477);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3543, '제62조(사법경찰관의 사건불송치)', 478);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3544, '제63조(재수사요청의 절차 등)', 478);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3545, '제64조(재수사 결과의 처리)', 478);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3546, '제65조(재수사 중의 이의신청) 사법경찰관은 법 제245조의8제2항에 따라 재수사 중인 사건에 대해 법 제245조의7제1항에 따른 이의신청이 있는 경우에는 재수사를 중단해야 하며, 같은 조 제2항에 따라 해당 사건을 지체 없이 검사에게 송치하고 관계 서류와 증거물을 송부해야 한다.', 478);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3547, '제66조(재정신청 접수에 따른 절차)', 479);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3548, '제67조(형사사법정보시스템의 이용) 검사 또는 사법경찰관은 「형사사법절차 전자화 촉진법」 제2조제1호에 따른 형사사법업무와 관련된 문서를 작성할 때에는 형사사법정보시스템을 이용해야 하며, 그에 따라 작성한 문서는 형사사법정보시스템에 저장ㆍ보관해야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 문서로서 형사사법정보시스템을 이용하는 것이 곤란한 경우는 그렇지 않다.', 479);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3549, '제68조(사건 통지 시 주의사항 등) 검사 또는 사법경찰관은 제12조에 따라 수사 진행상황을 통지하거나 제53조에 따라 수사 결과를 통지할 때에는 해당 사건의 피의자 또는 사건관계인의 명예나 권리 등이 부당하게 침해되지 않도록 주의해야 한다.', 479);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3550, '제69조(수사서류 등의 열람ㆍ복사)', 479);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3551, '제70조(영의 해석 및 개정)', 479);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3552, '제71조(민감정보 및 고유식별정보 등의 처리) 검사 또는 사법경찰관리는 범죄 수사 업무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 민감정보, 같은 법 시행령 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호나 그 밖의 개인정보가 포함된 자료를 처리할 수 있다.', 479);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3553, '제1조(목적) 이 영은 「보호관찰 등에 관한 법률」(이하 "법"이라 한다)에서 위임된 사항과 그 시행에 관하여 필요한 사항을 규정함을 목적으로 한다. <개정 2006.3.23>', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3554, '제2조(보호관찰심사위원회의 위원장)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3555, '제3조(위원의 자격 및 임명)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3556, '제4조(심사위원회의 간사 및 서기)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3557, '제5조(심사)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3558, '제6조(의결 및 결정)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3559, '제6조의2(교육훈련)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3560, '제7조(판결 및 결정 전 조사) 법원은 보호관찰소의 장에게 법 제19조제1항 또는 제19조의2제1항에 따른 조사를 요구하는 때에는 피고인 또는 소년의 인적사항 및 범죄사실의 요지를 통보하여야 한다. 이 경우 필요하다고 인정하는 때에는 참고자료를 송부할 수 있다. <개정 2009.3.18>', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3561, '제8조(수용기관의 장의 통보의무)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3562, '제9조(가석방ㆍ퇴원 및 임시퇴원의 신청) 수용기관의 장은 법 제22조에 따라 가석방, 퇴원 또는 임시퇴원의 심사를 신청하고자 하는 경우에는 소년수형자 또는 보호소년의 신상에 관한 사항, 범죄 및 비행에 관한 사항, 교정성적 등을 종합적으로 고려하여야 한다. <개정 2008.6.20, 2009.3.18>', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3563, '제10조(직권심사) 심사위원회는 법 제23조제2항, 법 제48조제1항, 법 제50조제1항, 법 제52조제1항ㆍ제3항 또는 법 제53조제1항의 규정에 의하여 직권으로 심사를 하는 경우에는 심사대상자를 수용하는 수용기관의 장 또는 관할보호관찰소의 장의 의견을 들어야 한다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3564, '제11조(가석방등의 결정)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3565, '제12조(환경조사)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3566, '제13조(환경개선활동의 방법) 보호관찰소의 장은 법 제27조제1항의 규정에 의한 환경개선활동을 하는 경우에는 수용자와의 면접 또는 통신, 가족 및 관계인과의 협의, 수용기관 기타 관계기관의 협조 등의 방법으로 지속적으로 실시하여야 하며, 본인의 의사를 존중하고 본인ㆍ가족 및 관계인의 신뢰와 협력을 얻도록 노력하여야 한다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3567, '제14조(보호관찰사안조사) 교도소ㆍ구치소ㆍ소년교도소의 장은 법 제28조제1항의 규정에 의하여 가석방심사신청대상자의 명단과 신상조사서를 심사위원회에 송부한 후 그 대상자의 신상에 변동이 있을 때에는 심사위원회에 그 사실을 통지하여야 한다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3568, '제15조(수용기관의 장의 협조) 수용기관의 장은 심사위원회 또는 보호관찰소의 장으로부터 수용자와의 면접, 관계기록의 열람 등 필요한 협조요청을 받은 경우에는 이에 응하여야 한다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3569, '제16조(보호관찰대상자의 신고의무) 법 제3조제1항의 규정에 의한 보호관찰대상자(이하 "보호관찰대상자"라 한다)는 다음 각 호의 어느 하나에 해당하는 때에는 10일이내에 주거지를 관할하는 보호관찰소에 출석하여 서면으로 법 제29조제2항의 규정에 의한 신고를 하여야 한다. <개정 2006.3.23, 2008.6.20, 2009.3.18, 2019.11.5>', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3570, '제17조(준수사항의 부과 및 훈계) 법원 또는 심사위원회는 법 제32조의 규정에 의하여 보호관찰대상자에게 준수사항을 과할 때에는 보호관찰의 취지를 설명하고, 준수사항을 기재한 서면을 교부하여야 하며, 적절한 훈계를 할 수 있다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3571, '제18조(주거이전등의 신고)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3572, '제19조(특별준수사항) 법 제32조제3항제10호에서 "대통령령으로 정하는 사항"이란 다음 각 호의 사항을 말한다. <개정 2021.1.5>', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3573, '제19조의2(준수사항의 추가 등 신청)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3574, '제19조의3(분류처우계획의 수립 등)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3575, '제20조(응급구호의 범위)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3576, '제20조의2(정신질환 보호관찰 종료사실 통보 절차 등)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3577, '제21조(보호관찰대상자등의 소환 및 조사)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3578, '제22조(보호관찰대상자에 대한 경고) 보호관찰소의 장은 법 제38조의 규정에 의하여 경고를 하는 때에는 보호관찰대상자에게 경고이유등을 서면으로 고지하여야 한다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3579, '제23조(구인신청의 방식) 보호관찰소의 장은 법 제39조제1항의 규정에 의하여 보호관찰대상자의 구인을 신청하는 때에는 다음 각호의 사항을 기재한 서면에 의하여야 한다. <개정 2009.11.23>', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3580, '제24조(구인장의 방식) 법 제39조제1항의 규정에 의하여 판사가 발부하는 구인장에는 청구한 검사의 관직ㆍ성명 및 제23조 각호의 사항을 기재하여야 한다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3581, '제25조(구인장의 집행의뢰) 보호관찰관은 법 제39조제2항 단서의 규정에 의하여 사법경찰관리에게 구인장의 집행을 의뢰하는 때에는 그 사유를 기재한 서면으로 하되, 검사의 지휘를 받아야 한다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3582, '제26조(긴급구인승인신청등)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3583, '제27조(구인후 조사 및 심문)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3584, '제28조(유치허가신청의 방식) 보호관찰소의 장은 법 제42조제2항의 규정에 의하여 보호관찰대상자의 유치허가신청을 하는 때에는 다음 각호의 사항을 기재한 서면에 의하여야 한다. <개정 2009.11.23>', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3585, '제29조(유치허가장의 방식) 법 제42조제2항의 규정에 의하여 판사가 발부하는 유치허가장에는 청구한 검사의 관직ㆍ성명ㆍ발부일시 및 제28조 각호의 사항을 기재하여야 한다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3586, '제30조(구인ㆍ긴급구인승인 및 유치허가신청의 관할) 보호관찰소의 장은 그 소재지를 관할하는 지방검찰청 또는 지청의 검사에게 구인ㆍ긴급구인승인 및 유치허가의 신청을 한다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3587, '제31조(유치기간연장결정의 통지) 법원은 법 제43조제2항의 규정에 의하여 유치기간을 연장한 때에는 지체없이 보호관찰소의 장에게 그 사실을 통지하여야 한다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3588, '제32조(보호관찰을 조건으로 한 형의 선고유예의 실효 및 집행유예의 취소청구신청등)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3589, '제33조(취소청구신청에 대한 결과 통지) 검사는 법 제42조제1항제1호의 신청을 기각한 때 또는 보호관찰을 조건으로 한 형의 선고유예의 실효 및 집행유예의 취소청구에 대한 법원의 결정이 있는 때에는 지체없이 보호관찰소의 장에게 그 사실을 통지하여야 한다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3590, '제34조(가석방 및 임시퇴원의 취소와 재수용)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3591, '제35조(보호처분의 변경신청)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3592, '제36조(보호관찰정지자 소재 파악시의 통보) 보호관찰소의 장은 보호관찰정지중인 자의 소재를 파악한 때에는 지체없이 심사위원회에 그 사실을 통보하여야 한다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3593, '제36조의2(기부금품의 접수 등)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3594, '제36조의3(보호관찰 종료사실 등의 통보 절차) 법 제55조의3제1항에 따른 가석방자의 보호관찰 종료사실 등의 통보는 보호관찰소의 장이 관리하는 법 제55조의3제2항 각 호에 대한 전자기록을 「형사사법절차 전자화 촉진법」 제2조제4호에 따른 형사사법정보시스템에 등록하고, 경찰관서의 장이 이를 조회하는 방식 등으로 할 수 있다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3595, '제37조(사회봉사ㆍ수강명령 집행위탁의 통보) 보호관찰관이 법 제61조제2항의 규정에 의하여 사회봉사명령 또는 수강명령의 집행위탁 사실을 법원 또는 법원의 장에게 통보하는 때에는 집행위탁을 받은 기관의 명칭 및 주소, 위탁인원, 집행위탁의 내용 등을 기재한 서면에 의하여야 한다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3596, '제38조(사회봉사ㆍ수강명령 집행위탁의 취소에 따른 조치) 법원이 법 제61조제3항의 규정에 의하여 사회봉사명령 또는 수강명령의 집행위탁을 취소한 경우에는 보호관찰관이 남은 기간의 사회봉사명령 또는 수강명령을 직접 집행하거나 적합한 다른 국ㆍ공립기관 기타 단체에 위탁하여 집행하여야 한다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3597, '제39조(준용)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3598, '제40조(갱생보호)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3599, '제41조(숙식 제공)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3600, '제41조의2(주거 지원) 법 제65조제1항제2호에 따른 주거 지원은 갱생보호 대상자에게 주택의 임차에 필요한 지원을 하는 것으로 한다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3601, '제41조의3(창업 지원) 법 제65조제1항제3호에 따른 창업 지원은 갱생보호 대상자에게 창업에 필요한 사업장 임차보증금 등을 지원하는 것으로 한다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3602, '제42조 삭제 <2014.11.19>', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3603, '제43조 삭제 <2014.11.19>', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3604, '제44조(직업훈련)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3605, '제45조(취업 지원) 법 제65조제1항제4호에 따른 취업 지원은 갱생보호 대상자에게 직장을 알선하고 필요한 경우 신원을 보증하는 것으로 한다. <개정 2014.11.19>', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3606, '제45조의2(출소예정자 사전상담)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3607, '제45조의3(갱생보호 대상자의 가족에 대한 지원) 법 제65조제1항제6호에 따른 갱생보호 대상자의 가족에 대한 지원은 갱생보호 대상자의 가족에게 심리상담 및 심리치료, 취업 지원, 학업 지원 등을 하는 것으로 한다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3608, '제45조의4(심리상담 및 심리치료) 법 제65조제1항제7호에 따른 심리상담 및 심리치료는 갱생보호 대상자에게 심리적 안정과 사회적응을 위한 상담 및 「정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률」에 따른 정신건강전문요원 등 전문가에 의한 치료를 실시하는 것으로 한다. <개정 2017.5.29>', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3609, '제45조의5(사후관리) 법 제65조제1항제8호에 따른 사후관리는 같은 항 제1호부터 제7호까지 또는 제9호의 갱생보호를 받은 갱생보호 대상자에게 사회복귀 상황을 점검하여 필요한 조언을 하는 것으로 한다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3610, '제46조(자립 지원) 법 제65조제1항제9호에 따른 갱생보호 대상자에 대한 자립 지원은 사회복지시설에의 의탁 알선, 가족관계 등록 창설, 주민등록, 결혼 주선, 입양 및 의료 시혜 등 갱생보호 대상자의 자립을 위하여 필요한 사항을 지원하는 것으로 한다. <개정 2014.11.19>', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3611, '제46조의2(갱생보호 대상자 수용기간 등의 통보 요청)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3612, '제47조(공단의 기부금품 접수 등) 법 제85조에 따른 기부금품의 접수  등에 관하여는 제36조의2제1항 및 제3항부터 제6항까지의 규정을 준용한다. 이 경우 "보호관찰소의 장"은 "공단"으로 본다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3613, '제48조(기금의 운용ㆍ관리) 공단은 법 제86조에 따라 설치된 갱생보호기금(이하 "기금"이라 한다)을 별도 계정으로 관리하여야 한다. <개정 2009.3.18, 2014.11.19>', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3614, '제49조(기금의 운용ㆍ관리계획)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3615, '제50조(기금운용에 관한 보고)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3616, '제51조(민감정보 및 고유식별정보의 처리)', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3617, '제52조(과태료의 부과기준) 법 제101조제1항에 따른 과태료의 부과기준은 별표와 같다.', 480);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3618, '제1조(목적) 이 영은 「전자장치 부착 등에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다. <개정 2009.7.30, 2013.5.31, 2020.8.5>', 481);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3619, '제2조(위치추적 전자장치의 구성) 「전자장치 부착 등에 관한 법률」(이하 "법"이라 한다) 제2조제4호에 따른 위치추적 전자장치(이하 "전자장치"라 한다)는 다음 각 호로 구성한다. <개정 2009.7.30, 2013.5.31, 2018.2.13, 2020.8.5>', 481);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3620, '제3조 삭제 <2021.9.14>', 481);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3621, '제3조의2(출연금 등의 지급ㆍ사용 및 관리)', 481);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3622, '제4조(조사)', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3623, '제5조(부착명령 청구서의 기재사항 및 방식)', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3624, '제6조(집행지휘) 검사는 부착명령의 판결이 확정되면 지체 없이 부착명령을 선고받은 사람(이하 "피부착명령자"라 한다)의 주거지를 관할하는 보호관찰소의 장에게 법 제12조제2항의 부착명령 집행을 지휘한 서면을 보내야 한다.', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3625, '제7조(부착명령의 집행)', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3626, '제8조(부착명령의 집행정지)', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3627, '제9조(부착명령 집행정지자의 이송) 수용기관의 장은 법 제13조제6항에 따라 부착명령의 집행이 정지된 사람을 다른 수용기관으로 이송할 경우에는 그의 주거지를 관할하는 보호관찰소의 장과 해당 수용기관의 장에게 그 사실을 통보하여야 한다. <개정 2010.7.12, 2018.6.12>', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3628, '제10조(전자장치의 일시 분리)', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3629, '제11조(전자장치의 효용 유지 의무) 피부착자는 전자장치의 부착기간 중 법 제14조제1항에 따라 전자장치의 효용 유지를 위하여 다음 각 호의 사항을 준수하여야 한다.', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3630, '제12조(주거이전ㆍ국내여행 및 출국 허가 등)', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3631, '제12조의2(부착기간의 연장 등의 신청)', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3632, '제13조(상담치료 등의 집행)', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3633, '제14조(수신자료의 사용) 보호관찰소의 장 및 법 제16조의3에 따른 위치추적 관제센터(이하 "위치추적 관제센터"라 한다)의 장은 법 제16조제2항제1호, 제3호 및 제4호에 따라 수신자료가 사용된 경우에는 그 사실을 대장에 적고 이를 비치해야 한다. <개정 2010.7.12, 2018.6.12, 2021.9.14, 2024.1.9>', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3634, '제14조의2(수신자료 열람 또는 조회)', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3635, '제14조의3(긴급 수신자료 열람 또는 조회)', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3636, '제14조의4(열람 또는 조회한 수신자료의 보존ㆍ폐기 등)', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3637, '제14조의5(수신자료 사용사건의 결과 통지 등)', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3638, '제14조의6(수신자료 관련 비밀누설 금지 등) 수신자료를 열람 또는 조회한 사람은 그로 인하여 알게 된 타인의 비밀을 누설하거나 피부착자의 명예를 훼손하지 아니하도록 하여야 한다.', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3639, '제15조(수신자료의 폐기)', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3640, '제15조의2(피부착자의 신상정보 제공 등)', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3641, '제16조(부착명령의 임시해제 신청)', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3642, '제17조(부착명령 임시해제의 심사 및 결정)', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3643, '제18조(임시해제의 취소 등)', 482);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3644, '제18조의2(보호관찰 기간의 연장 등)', 483);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3645, '제18조의3(준용규정) 보호관찰대상자의 조사, 집행지휘, 주거이전 허가, 상담치료, 임시해제 및 취소 등에 관하여는 제4조부터 제6조까지, 제12조제1항부터 제7항까지, 제13조, 제16조, 제17조제1항ㆍ제2항ㆍ제4항 및 제18조제1항ㆍ제2항을 준용한다. 이 경우 "부착명령"은 "보호관찰명령"으로, "부착기간"은 "보호관찰 기간"으로, "피부착명령청구자"는 "피보호관찰명령청구자"로, "피부착명령자"는 "피보호관찰명령자"로, "피부착자"는 "보호관찰대상자"로, "전자장치 부착"은 "보호관찰"로 본다. <개정 2020.8.5>', 483);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3646, '제19조(전자장치 부착 적합성조사)', 484);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3647, '제19조의2(결정의 고지 등)', 484);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3648, '제20조(치료감호시설의 장 등의 통보)', 484);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3649, '제21조(준용) 이 장에 따른 전자장치 부착에 관하여는 제7조부터 제12조까지, 제12조의2 및 제13조부터 제18조까지의 규정을 준용한다. <개정 2010.7.12>', 484);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3650, '제22조(집행유예와 부착명령의 집행) 법 제28조제1항에 따라 집행유예와 함께 전자장치 부착을 명하는 법원의 판결이 확정된 사람은 판결 확정 후 10일 이내에 보호관찰소에 출석하여 법 제29조제1항에 따른 부착명령의 집행에 따라야 한다.', 485);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3651, '제23조(준용) 이 장에 따른 부착명령에 관하여는 제4조, 제6조부터 제12조까지, 제12조의2 및 제13조부터 제18조까지의 규정을 준용한다. <개정 2010.7.12>', 485);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3652, '제23조의2(보석조건 전자장치 부착 결정 전 조사)', 486);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3653, '제23조의3(보석허가 결정문의 송부 등) 법원은 긴급한 필요가 있는 경우 법 제31조의3제1항에 따라 보호관찰소의 장에게 결정문의 등본을 송부하기 전에 팩스ㆍ전자우편 등의 방법으로 그 사본을 먼저 송부할 수 있다.', 486);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3654, '제23조의4(전자장치 부착 보석 피고인의 신고) 법 제31조의2제1항에 따라 보석조건으로 전자장치 부착명령을 받고 석방된 피고인(이하 "전자장치 보석피고인"이라 한다)은 법 제31조의3제2항에 따라 주거지를 관할하는 보호관찰소에 출석하여 신고하는 경우 법무부령으로 정하는 신고서를 제출해야 한다.', 486);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3655, '제23조의5(전자장치 부착 등)', 486);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3656, '제23조의6(보석조건 이행 상황 통지)', 486);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3657, '제23조의7(보석조건 위반 통지)', 486);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3658, '제23조의8(보석조건 변경 및 보석취소 통지) 법원은 「형사소송법」 제102조제1항 또는 제2항에 따라 보석조건을 변경하거나 취소한 경우 보호관찰소의 장에게 보석조건 변경이나 보석취소 결정문의 등본을 송부해야 한다. 이 경우 긴급한 경우에는 전화ㆍ팩스ㆍ전자우편 등의 방법으로 먼저 통지할 수 있다.', 486);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3659, '제23조의9(준용 규정) 이 장에 따른 전자장치 부착 등에 관하여는 제10조, 제14조의6 및 제15조를 준용한다. 이 경우 "피부착자"는 "전자장치 보석피고인"으로 본다.', 486);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3660, '제23조의10(잠정조치 결정문의 송부) 법원은 긴급한 필요가 있는 경우 법 제31조의6제1항에 따라 다음 각 호의 사람에게 결정문의 등본을 송부하기 전에 팩스ㆍ전자우편 등의 방법으로 그 사본을 먼저 송부할 수 있다.', 487);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3661, '제23조의11(전자장치 스토킹행위자의 신고)', 487);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3662, '제23조의12(전자장치의 부착 등)', 487);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3663, '제23조의13(전자장치 부착 사실의 통지 등)', 487);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3664, '제23조의14(피해자의 보호)', 487);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3665, '제23조의15(잠정조치의 연장ㆍ변경ㆍ취소 통지) 법원은 잠정조치의 연장ㆍ변경ㆍ취소 결정을 한 경우 법 제31조의6제7항에 따라 관할경찰관서의 장과 보호관찰소의 장에게 그 결정문의 등본을 지체 없이 송부해야 한다. 이 경우 긴급한 경우에는 전화ㆍ팩스ㆍ전자우편 등의 방법으로 먼저 통지할 수 있다.', 487);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3666, '제23조의16(불기소처분의 통지) 검사는 전자장치 스토킹행위자에 대해 불기소처분을 하여 「스토킹범죄의 처벌 등에 관한 법률」 제11조제5항에 따라 잠정조치 결정이 효력을 상실한 때에는 보호관찰소의 장에게 이를 지체 없이 통지해야 한다.', 487);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3667, '제23조의17(스토킹행위자 수신자료의 사용) 보호관찰소의 장 및 위치추적 관제센터의 장은 법 제31조의8제2항제1호, 제3호 및 제4호에 따라 스토킹행위자 수신자료가 사용된 경우에는 그 사실을 대장에 적고 이를 비치해야 한다.', 487);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3668, '제23조의18(스토킹행위자 수신자료의 폐기) 보호관찰소의 장 및 위치추적 관제센터의 장은 법 제31조의8제4항제1호 및 제2호에 따른 스토킹행위자 수신자료의 폐기를 위해 「형사사법절차 전자화 촉진법」 제2조제2호에 따른 형사사법업무 처리기관에 다음 각 호의 사항을 알아보거나 관련 자료의 열람 등 협조를 요청할 수 있다.', 487);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3669, '제23조의19(준용규정) 이 장에 따른 전자장치 부착 등에 관하여는 제7조제3항, 제10조, 제14조의2부터 제14조의6까지 및 제15조제2항을 준용한다. 이 경우 "피부착명령자" 및 "피부착자"는 각각 "전자장치 스토킹행위자"로, "수신자료"는 "스토킹행위자 수신자료"로 본다.', 487);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3670, '제24조(출소자 등의 인적사항 등 통보)', 488);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3671, '제25조(조사) 검사는 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제2호 및 제3항제2호에 따라 보호관찰소의 장에게 출소자등에 대한 법 제6조에 따른 조사를 요청할 때에는 수용시설의 장으로부터 통보받은 제24조제1항 각 호의 사항과 출소자등에 대한 범죄경력조회서, 연락처, 면담결과서 등을 통보하여야 한다.', 488);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3672, '제26조(부착명령 청구 사실의 통보) 검사는 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제4호 및 제3항제4호에 따라 출소자등에 대하여 부착명령을 청구한 경우에는 피청구인에게 지체 없이 서면으로 청구 사실을 통보하여야 한다.', 488);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3673, '제27조(부착명령 결정의 통지)', 488);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3674, '제28조(집행지휘)', 488);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3675, '제29조(민감정보 및 고유식별정보의 처리)', 488);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3676, '제1조(목적) 이 규칙은 「보호소년 등의 처우에 관한 법률」 및 「보호소년 등의 처우에 관한 법률 시행령」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 489);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3677, '제2조 삭제 <2021.4.20>', 489);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3678, '제3조 삭제 <2021.4.20>', 489);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3679, '제4조 삭제 <2021.4.20>', 489);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3680, '제5조 삭제 <2021.4.20>', 489);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3681, '제6조 삭제 <2021.4.20>', 489);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3682, '제7조 삭제 <2008.6.20>', 489);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3683, '제8조 삭제 <2008.6.20>', 489);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3684, '제9조(보호소년등의 인수절차)', 491);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3685, '제9조의2 삭제 <2014.1.29>', 491);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3686, '제10조(수용사실 통지) 영 제8조에 따른 수용사실의 통지는 별지 제2호서식에 따른다. 다만, 보호소년등의 보호자 또는 보호소년등이 지정하는 사람(이하 "보호자등"이라 한다)이 원하는 때에는 정보통신망을 이용하여 통지할 수 있다. 이 경우 그 통지 사실을 기록ㆍ유지하여야 한다.', 491);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3687, '제11조(분류처우) 원장은 영 제9조에 따라 다음 각 호의 어느 하나에 해당하는 보호소년등은 다른 보호소년등과 생활실 및 처우과정을 달리해야 한다. 다만, 원장은 시설여건이나 교육과정 운영을 위하여 특히 필요한 경우에는 「보호소년 등의 처우에 관한 법률」(이하 "법"이라 한다)제15조의2에 따른 보호소년등처우ㆍ징계위원회(이하 "처우ㆍ징계위원회"라 한다)의 심의를 거쳐 이를 조정ㆍ운영할 수 있다. <개정 2014.1.29, 2021.4.20>', 491);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3688, '제12조(처우ㆍ징계위원회의 개별처우계획 심사) 영 제10조 및 영 제11조에 따른 처우ㆍ징계위원회의 개별처우계획 심사는 심사 사유가 발생한 날부터 10일 이내에 실시해야 한다. <개정 2021.4.20>', 491);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3689, '제13조 삭제 <2008.6.20>', 491);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3690, '제14조 삭제 <2008.6.20>', 491);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3691, '제15조 삭제 <2008.6.20>', 491);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3692, '제16조(이탈한 사람에 대한 조치)', 491);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3693, '제17조(청원의 처리절차)', 492);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3694, '제18조(여론조사) 원장은 보호소년등을 적절하게 처우하기 위하여 보호소년등을 대상으로 월 1회 이상 처우에 관한 의견을 조사하고 그 처리결과를 보호소년등에게 알려야 한다.', 492);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3695, '제19조(이송)', 492);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3696, '제20조 삭제 <2008.6.20>', 492);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3697, '제21조(의료재활처우소년의 이송)', 492);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3698, '제22조(의료재활소년원 이송절차 등)', 492);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3699, '제23조(수용사고 방지계획 등의 수립) 원장은 보호소년등의 이탈ㆍ난동ㆍ폭행ㆍ자해 그 밖의 수용사고의 방지를 위한 종합대책 및 세부적인 생활지도계획을 수립ㆍ시행하여야 한다.', 493);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3700, '제24조(보호소년등의 감호)', 493);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3701, '제24조의2(보호장비의 사용방법)', 493);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3702, '제24조의3(보호장비의 관리)', 493);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3703, '제24조의4(전자장비의 종류) 법 제14조의3에 따라 소년원 또는 소년분류심사원(이하 "소년원등"이라 한다)에 설치하여 운영할 수 있는 전자장비는 다음 각 호와 같다. <개정 2021.4.20, 2022.2.7>', 493);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3704, '제24조의5(통제실의 운영)', 493);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3705, '제24조의6(영상정보처리기기의 설치 및 운영)', 493);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3706, '제24조의7(전자감지기의 설치) 전자감지기는 소년원등의 외곽 담장, 그 밖에 보호소년등의 이탈이나 외부로부터의 침입을 방지하기 위하여 필요한 장소로서 법무부장관이 정하는 장소에 설치한다. <개정 2021.4.20>', 493);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3707, '제24조의8(전자이름표의 사용) 원장은 수용 중인 보호소년등의 안전사고 방지, 출석관리 등을 위하여 소년원등의 시설 내에서 보호소년등에게 전자이름표를 휴대하도록 할 수 있다. <개정 2021.4.20, 2022.2.7>', 493);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3708, '제24조의9(물품검색기 설치 및 사용)', 493);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3709, '제24조의10(증거수집장비의 사용) 소속공무원은 보호소년등이 사후에 증명이 필요하다고 인정되는 행위를 하거나 사후 증명이 필요한 상태에 있는 경우 보호소년등에 대하여 증거수집장비를 사용할 수 있다.', 493);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3710, '제24조의11(녹음ㆍ녹화 기록물의 관리) 원장은 전자장비로 녹음ㆍ녹화된 기록물을 「공공기록물 관리에 관한 법률」에 따라 관리하여야 한다.', 493);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3711, '제25조(소지품검사 및 시설점검)', 493);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3712, '제26조(행동관찰) 원장은 보호소년등의 행동을 수시로 관찰하고 특이사항을 기록ㆍ유지하여 감호ㆍ분류심사 및 교정교육의 자료로 활용하여야 한다.', 493);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3713, '제27조(사고발생보고) 원장은 영 제20조제1항에 따라 사고발생사실을 법무부장관에게 보고하는 경우에는 관련 자료와 대상자의 인적사항, 사고발생 일시ㆍ장소ㆍ내용ㆍ조치사항 등이 작성된 보고서를 첨부하여야 한다.', 493);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3714, '제27조의2(규율 위반) 법 제14조의4제6호에서 "법무부령으로 정하는 규율을 위반하는 행위"란 다음 각 호의 행위를 말한다. <개정 2016.9.29>', 493);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3715, '제28조(징계양정)', 494);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3716, '제28조의2(징계대상행위 조사 시 준수사항) 영 제24조의2에 따라 징계대상행위에 대하여 조사하는 직원은 다음 각 호의 사항을 준수하여야 한다.', 494);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3717, '제29조(포상) 원장은 별표 2의2의 보호소년등의 포상기준에 따라 교정성적이 우수한 학생에 대하여 처우ㆍ징계위원회의 심사를 거쳐 포상을 할 수 있다. 다만, 모범상 및 공로상은 직원 2명 이상의 추천을 받아야 한다. <개정 2021.4.20>', 494);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3718, '제30조(징계ㆍ포상의 기록) 원장은 보호소년등의 징계 또는 포상에 관한 사항을 소년관리기록부 및 별지 제6호서식의 상벌대장에 기록ㆍ관리하여야 한다.', 494);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3719, '제31조(급여품관리부의 작성) 보호소년등에게 물품을 급여 또는 대여할 때에는 별지 제7호서식의 개인별 급여품관리부에 그 내용을 기록ㆍ관리하여야 한다.', 495);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3720, '제32조(물품반입)', 495);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3721, '제33조(면회장소)', 496);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3722, '제34조(면회절차)', 496);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3723, '제35조(공휴일의 면회) 원장은 보호소년등을 면회할 목적으로 방문하는 민원인의 편의를 도모하기 위하여 제36조 각 호의 어느 하나에 해당하는 특별한 사유가 있는 경우에는 공휴일에도 별도의 면회장소 및 시간을 지정하여 면회를 허가할 수 있다. 이 경우 별지 제9호서식의 시간외 면회부에 그 내용을 기록ㆍ관리하여야 한다. <개정 2014.1.29>', 496);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3724, '제36조(면회의 특례) 영 제36조제1항 단서에 따른 특별한 사유는 다음 각 호의 어느 하나에 해당하는 경우를 말한다.', 496);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3725, '제36조의2(전화통화의 방법 등)', 496);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3726, '제37조(외출의 신청)', 496);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3727, '제38조 삭제 <2014.1.29>', 496);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3728, '제39조(외출시 준수사항)', 496);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3729, '제40조(보건ㆍ위생관리계획 수립 등)', 497);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3730, '제41조(청결의 유지)', 497);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3731, '제42조(이발과 목욕) 원장은 위생을 위해 보호소년등이 이발과 목욕을 수시로 하게 해야 한다.', 497);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3732, '제43조(체력검사 등)', 497);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3733, '제44조(환자발생 보고) 영 제43조에 따른 외부 의료기관 의료조치에 관한 보고는 제27조를 준용한다. <개정 2021.4.20>', 497);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3734, '제44조의2(진료기록부등의 보존) 법무부장관은 법 제20조의2제1항에 따른 진료기록부등(이하 "진료기록부등"이라 한다)을 「의료법 시행규칙」 제15조제1항에 따른 기간 동안 보존해야 한다.', 497);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3735, '제44조의3(진료기록부등의 송부 및 요청)', 497);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3736, '제44조의4(출원생의 외래진료의 기간ㆍ방법)', 497);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3737, '제44조의5(출원생의 외래진료 진료비용 지원)', 497);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3738, '제45조(물품의 보관) 원장은 보호소년등의 물품을 보관할 때에는 세탁ㆍ소독 그 밖의 적당한 조치를 한 후 주의하여 보관하여야 한다.', 498);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3739, '제46조(보관금품 보관증) 영 제47조 전단에 따른 보관금품 보관증은 별지 제12호서식에 따른다.', 498);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3740, '제47조(기증품 사용관리) 원장은 영 제49조제1항에 따라 기증품을 접수하면 기증인에게 별지 제13호서식에 따른 영수증을 발급하고, 별지 제14호서식에 따른 기증품관리대장에 기록한 후 사용하여야 하며, 그 사용결과를 기증자에게 통보하여야 한다.', 498);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3741, '제48조(분류심사의 방법 및 구분 등)', 499);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3742, '제49조(면접조사)', 499);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3743, '제50조(행동관찰)', 499);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3744, '제51조(분류심사관의 임명 등)', 499);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3745, '제52조(분류심사 결과 등의 통지) 법 제26조에 따른 청소년심리검사 등의 결과 및 법 제27조에 따른 분류심사 결과 등을 통지할 때에는 법무부장관이 별도로 정한 서식에 따른다.', 499);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3746, '제53조(신입자교육)', 501);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3747, '제54조(기본교육) 소년원장은 제53조에 따른 신입자교육을 마친 보호소년에 대하여는 인문ㆍ실업ㆍ특성화ㆍ인성교육 또는 직업능력개발훈련, 특별활동, 생활지도 그 밖에 필요한 기본교육을 실시하여야 한다.', 501);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3748, '제55조(사회복귀교육)', 501);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3749, '제56조 삭제 <2014.1.29>', 501);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3750, '제57조(여름철 및 겨울철의 지도) 소년원장은 여름철과 겨울철에 상당기간을 방학기간으로 정하여 특별활동 및 생활지도 중심의 교정교육을 할 수 있다.', 501);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3751, '제58조 삭제 <2008.6.20>', 501);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3752, '제59조(소년관리기록부 등)', 501);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3753, '제60조(학칙)', 502);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3754, '제61조(학칙 등에 관한 통지) 소년원학교장은 학사운영에 관한 긴밀한 협력을 도모하기 위하여 관할 시ㆍ도교육감 또는 시ㆍ군ㆍ자치구 교육장에게 소년원학교에 관한 다음 각 호의 사항을 통지하여야 한다.', 502);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3755, '제62조(업무연구 등) 원장은 교정교육 전반을 창의적으로 개선하고 업무능률을 향상시키기 위하여 직원으로 하여금 업무연구 또는 연구수업을 실시하게 하고, 연구발표회 등의 참관을 적극 권장하여야 한다.', 502);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3756, '제63조(보충수업) 소년원학교장은 보호소년의 학력신장과 수업일수의 충족 등을 위하여 필요하다고 인정하면 평일의 경우 1일 2시간, 휴업일의 경우 1일 8시간의 범위에서 보충수업을 실시할 수 있다. <개정 2014.1.29, 2021.4.20>', 502);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3757, '제64조(학적자료 송부 등) 소년원학교장은 보호소년이 법 제32조에 따라 다른 학교로 전학하거나 편입학을 하는 경우에는 전학 또는 편입학한 학교에 학교생활기록부 전산자료와 용지에 출력한 출력물 및 건강기록부를 송부하고, 소년원학교에는 그 사본을 소년관리기록부와 함께 보관하여야 한다.', 502);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3758, '제65조(졸업장의 발급 등)', 502);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3759, '제66조(졸업증명서 등 서식) 영 제68조에 따른 졸업증명서ㆍ성적증명서ㆍ수료(제적)증명서ㆍ재학증명서는 각각 별지 제20호서식부터 별지 제23호서식까지에 따른다.', 502);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3760, '제67조(직종의 신설 또는 폐지)', 503);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3761, '제68조(직업능력개발훈련 대상자)', 503);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3762, '제69조(통근취업 보호소년의 관리)', 503);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3763, '제70조(보호소년등의 일과)', 504);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3764, '제71조(종교활동) 종교활동은 휴업일에 하는 것을 원칙으로 한다. 다만, 원장이 필요하다고 인정하면 교육과정의 이수에 지장이 없는 범위에서 휴업일이 아닌 날에도 할 수 있다. <개정 2021.4.20>', 504);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3765, '제72조(보호소년자치회)', 504);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3766, '제73조(대안교육)', 504);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3767, '제74조(보호자상담 등)', 504);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3768, '제75조(퇴원ㆍ임시퇴원 심사의 신청)', 505);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3769, '제76조(재ㆍ퇴원증명서) 영 제87조의2에서 "법무부령으로 정하는 재ㆍ퇴원증명서"란 다음 각 호의 구분에 따른 서식을 말한다.', 505);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3770, '제77조(특별 임시퇴원) 소년원장은 보호소년이 다음 각 호의 어느 하나에 해당하는 사유가 있는 경우에는 증빙서류를 첨부하여 특별 임시퇴원허가를 신청할 수 있다. <개정 2021.4.20>', 505);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3771, '제78조(임시퇴원자의 보호관찰자료 제공 등)', 505);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3772, '제79조(퇴원증 또는 임시퇴원증의 교부 등)', 505);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3773, '제80조(보호소년의 인도)', 505);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3774, '제81조(사회정착지원)', 505);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3775, '제81조의2 삭제 <2021.4.20>', 505);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3776, '제82조 삭제 <2016.9.29>', 505);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3777, '제83조(퇴원 또는 임시퇴원자의 계속수용)', 505);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3778, '제84조(임시퇴원취소자 인수소년원의 사후조치)', 505);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3779, '제85조(임시퇴원취소로 재수용된 사람의 처우)', 505);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3780, '제86조(청소년심리상담실의 운영) 법 제50조의2에 따른 청소년심리상담실에는 법 제24조제2항에 따른 전문적 지식과 기술을 갖춘 직원을 상시 배치하여야 한다.', 506);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3781, '제87조(실비 징수)', 506);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3782, '제88조(소년보호위원의 위촉 및 해촉)', 506);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3783, '제89조(소년보호위원의 자격기준 등) 소년보호위원의 세부적인 자격기준, 활동 등에 관한 사항은 법무부장관이 정한다.', 506);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3784, '제90조(소년보호협회의 수익사업 등)', 506);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3785, '제91조(기부금품의 접수 영수증 등)', 506);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3786, '제1조(목적) 이 법은 심신장애 상태, 마약류ㆍ알코올이나 그 밖의 약물중독 상태, 정신성적(精神性的) 장애가 있는 상태 등에서 범죄행위를 한 자로서 재범(再犯)의 위험성이 있고 특수한 교육ㆍ개선 및 치료가 필요하다고 인정되는 자에 대하여 적절한 보호와 치료를 함으로써 재범을 방지하고 사회복귀를 촉진하는 것을 목적으로 한다.', 507);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3787, '제2조(치료감호대상자)', 507);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3788, '제2조의2(치료감호 대상 성폭력범죄의 범위) 제2조제1항제3호의 성폭력범죄는 다음 각 호의 범죄를 말한다. <개정 2010.4.15, 2012.12.18, 2013.7.30>', 507);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3789, '제2조의3(치료명령대상자) 이 법에서 "치료명령대상자"란 다음 각 호의 어느 하나에 해당하는 자로서 통원치료를 받을 필요가 있고 재범의 위험성이 있는 자를 말한다. <개정 2017.12.12, 2020.10.20>', 507);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3790, '제3조(관할)', 507);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3791, '제4조(검사의 치료감호 청구)', 508);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3792, '제5조(조사)', 508);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3793, '제6조(치료감호영장)', 508);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3794, '제7조(치료감호의 독립 청구) 검사는 다음 각 호의 어느 하나에 해당하는 경우에는 공소를 제기하지 아니하고 치료감호만을 청구할 수 있다.', 508);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3795, '제8조(치료감호 청구와 구속영장의 효력) 구속영장에 의하여 구속된 피의자에 대하여 검사가 공소를 제기하지 아니하는 결정을 하고 치료감호 청구만을 하는 때에는 구속영장은 치료감호영장으로 보며 그 효력을 잃지 아니한다.', 508);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3796, '제9조(피치료감호청구인의 불출석) 법원은 피치료감호청구인이 「형법」 제10조제1항에 따른 심신장애로 공판기일에의 출석이 불가능한 경우에는 피치료감호청구인의 출석 없이 개정(開廷)할 수 있다.', 508);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3797, '제10조(공판절차로의 이행)', 508);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3798, '제11조(공판 내용의 고지) 제10조에 따라 공판절차로 이행하는 경우 피고인의 출석 없이 진행된 공판의 내용은 공판조서의 낭독이나 그 밖의 적당한 방법으로 피고인에게 고지(告知)하여야 한다.', 508);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3799, '제12조(치료감호의 판결 등)', 508);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3800, '제13조(전문가의 감정 등) 법원은 제4조제2항에 따른 정신건강의학과 전문의 등의 진단 또는 감정의견만으로 피치료감호청구인의 심신장애 또는 정신성적 장애가 있는지의 여부를 판단하기 어려울 때에는 정신건강의학과 전문의 등에게 다시 감정을 명할 수 있다. <개정 2011.8.4>', 508);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3801, '제14조(항소 등)', 508);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3802, '제15조(준용규정)', 508);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3803, '제16조(치료감호의 내용)', 509);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3804, '제16조의2(치료감호시설)', 509);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3805, '제17조(집행 지휘)', 509);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3806, '제18조(집행 순서 및 방법) 치료감호와 형(刑)이 병과(倂科)된 경우에는 치료감호를 먼저 집행한다. 이 경우 치료감호의 집행기간은 형 집행기간에 포함한다.', 509);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3807, '제19조(구분 수용) 피치료감호자는 특별한 사정이 없으면 제2조제1항 각 호의 구분에 따라 구분하여 수용하여야 한다.', 509);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3808, '제20조(치료감호 내용 등의 공개) 이 법에 따른 치료감호의 내용과 실태는 대통령령으로 정하는 바에 따라 공개하여야 한다. 이 경우 피치료감호자나 그의 보호자가 동의한 경우 외에는 피치료감호자의 개인신상에 관한 것은 공개하지 아니한다.', 509);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3809, '제21조(소환 및 치료감호 집행)', 509);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3810, '제21조의2(치료감호시설 간 이송)', 509);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3811, '제22조(가종료 등의 심사ㆍ결정) 제37조에 따른 치료감호심의위원회는 피치료감호자에 대하여 치료감호 집행을 시작한 후 매 6개월마다 치료감호의 종료 또는 가종료(假終了) 여부를 심사ㆍ결정하고, 가종료 또는 치료위탁된 피치료감호자에 대하여는 가종료 또는 치료위탁 후 매 6개월마다 종료 여부를 심사ㆍ결정한다.', 509);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3812, '제23조(치료의 위탁)', 509);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3813, '제24조(치료감호의 집행정지) 피치료감호자에 대하여 「형사소송법」 제471조제1항 각 호의 어느 하나에 해당하는 사유가  있을 때에는 같은 조에 따라 검사는 치료감호의 집행을 정지할 수 있다. 이 경우 치료감호의 집행이 정지된 자에 대한 관찰은 형집행정지자에 대한 관찰의 예에 따른다.', 509);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3814, '제25조(피치료감호자의 처우)', 510);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3815, '제25조의2(피치료감호청구인의 처우)', 510);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3816, '제25조의3(격리 등 제한의 금지)', 510);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3817, '제26조(면회 등) 치료감호시설의 장은 수용질서 유지나 치료를 위하여 필요한 경우 외에는 피치료감호자등의 면회, 편지의 수신ㆍ발신, 전화통화 등을 보장하여야 한다. <개정 2017.12.12>', 510);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3818, '제27조(텔레비전 시청 등) 피치료감호자등의 텔레비전 시청, 라디오 청취, 신문ㆍ도서의 열람은 일과시간이나 취침시간 등을 제외하고는 자유롭게 보장된다. <개정 2017.12.12>', 510);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3819, '제28조(환자의 치료)', 510);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3820, '제29조(근로보상금 등의 지급) 근로에 종사하는 피치료감호자에게는 근로의욕을 북돋우고 석방 후 사회정착에 도움이 될 수 있도록 법무부장관이 정하는 바에 따라 근로보상금을 지급하여야 한다.', 510);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3821, '제30조(처우개선의 청원)', 510);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3822, '제31조(운영실태 등 점검) 법무부장관은 연 2회 이상 치료감호시설의 운영실태 및 피치료감호자등에 대한 처우상태를 점검하여야 한다. <개정 2017.12.12>', 510);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3823, '제31조의2(피감정유치자의 처우) 「형사소송법」 또는 그 밖에 다른 법률에 따라 정신감정을 위하여 치료감호시설에 유치된 자에 대하여는 제25조의2, 제25조의3, 제26조부터 제28조까지, 제30조 및 제31조를 준용한다.', 510);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3824, '제32조(보호관찰)', 511);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3825, '제33조(피보호관찰자의 준수사항)', 511);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3826, '제33조의2(유치 및 유치기간 등)', 511);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3827, '제34조(피보호관찰자 등의 신고 의무)', 511);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3828, '제35조(치료감호의 종료)', 511);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3829, '제36조(가종료 취소와 치료감호의 재집행) 제37조에 따른 치료감호심의위원회는 피보호관찰자(제32조제1항제3호에 따라 치료감호기간 만료 후 피보호관찰자가 된 사람은 제외한다)가 다음 각 호의 어느 하나에 해당할 때에는 결정으로 가종료등을 취소하고 다시 치료감호를 집행할 수 있다. <개정 2017.12.12>', 511);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3830, '제36조의2(치료감호시설 출소자의 정신건강복지센터 등록 등) 치료감호가 종료 또는 가종료되거나 제24조에 따라 집행정지된 사람(이하 "치료감호시설 출소자"라 한다)은 정신건강복지센터에 등록하여 상담, 진료, 사회복귀훈련 등 정신건강복지센터의 정신보건서비스를 받을 수 있다. <개정 2016.5.29, 2017.12.12>', 512);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3831, '제36조의3(외래진료)', 512);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3832, '제36조의4(보호관찰소와 정신건강복지센터의 공조)', 512);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3833, '제37조(치료감호심의위원회)', 513);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3834, '제38조(결격사유) 다음 각 호의 어느 하나에 해당하는 자는 위원회의 위원이 될 수 없다.', 513);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3835, '제39조(위원의 해촉) 법무부장관은 위원회의 위원이 다음 각 호의 어느 하나에 해당하면 그 위원을 해촉할 수 있다.', 513);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3836, '제40조(심사)', 513);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3837, '제41조(의결 및 결정)', 513);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3838, '제42조(위원의 기피)', 513);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3839, '제43조(검사의 심사신청)', 513);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3840, '제44조(피치료감호자 등의 심사신청)', 513);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3841, '제44조의2(선고유예 시 치료명령 등)', 514);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3842, '제44조의3(판결 전 조사)', 514);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3843, '제44조의4(전문가의 진단 등) 법원은 제44조의2에 따른 치료를 명하기 위하여 필요하다고 인정하는 때에는 정신건강의학과 전문의에게 피고인의 정신적 상태, 알코올 의존도 등에 대한 진단을 요구할 수 있다. <개정 2016.5.29, 2017.12.12>', 514);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3844, '제44조의5(준수사항) 치료명령을 받은 사람은 다음 각 호의 사항을 준수하여야 한다.', 514);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3845, '제44조의6(치료명령의 집행)', 514);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3846, '제44조의7(치료기관의 지정 등)', 514);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3847, '제44조의8(선고유예의 실효 등)', 514);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3848, '제44조의9(비용부담)', 514);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3849, '제45조(치료감호 청구의 시효)', 515);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3850, '제46조(치료감호의 시효)', 515);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3851, '제47조(치료감호의 선고와 자격정지) 피치료감호자는 그 치료감호의 집행이 종료되거나 면제될 때까지 다음 각 호의 자격이 정지된다.', 515);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3852, '제48조(치료감호의 실효)', 515);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3853, '제49조(기간의 계산)', 515);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3854, '제50조(군법 적용 대상자에 대한 특칙)', 515);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3855, '제50조의2(기부금품의 접수)', 515);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3856, '제51조(다른 법률의 준용) 치료감호 및 치료명령에 관하여는 이 법에 특별한 규정이 있는 경우 외에는 그 성질에 반하지 아니하는 범위에서 「형사소송법」과 「형의 집행 및 수용자의 처우에 관한 법률」 및 「보호관찰 등에 관한 법률」을 준용한다. <개정 2015.12.1>', 515);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3857, '제52조(벌칙)', 516);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3858, '제1조(목적) 이 영은 「치료감호 등에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다. <개정 2016.11.29>', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3859, '제2조(마약류 등의 종류) 「치료감호 등에 관한 법률」(이하 "법"이라 한다) 제2조제1항제2호에 따른 마약ㆍ향정신성의약품ㆍ대마, 그 밖에 남용되거나 해독(害毒)을 끼칠 우려가 있는 물질의 종류는 다음과 같다. <개정 2012.6.7, 2014.12.9, 2016.11.29>', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3860, '제2조의2(남용되거나 해독을 끼칠 우려가 있는 물질) 법 제2조의3제3호에서 "마약ㆍ향정신성의약품ㆍ대마, 그 밖에 대통령령으로 정하는 남용되거나 해독을 끼칠 우려가 있는 물질"이란 제2조 각 호의 물질을 말한다.', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3861, '제3조(감호청구서의 기재사항 및 방식)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3862, '제4조(치료감호의 방법)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3863, '제4조의2(치료감호 기간 연장 신청)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3864, '제4조의3(지정법무병원의 지정절차)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3865, '제4조의4(지정법무병원의 운영 및 치료)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3866, '제4조의5(지정법무병원에 대한 경비보조)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3867, '제5조(동태의 보고 등)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3868, '제6조(치료감호 내용 등의 공개)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3869, '제6조의2(재이송의 신청 및 결정)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3870, '제7조(치료의 위탁) 법 제23조제3항에 따른 치료의 위탁을 받을 수 있는 피치료감호자의 법정대리인, 배우자, 직계친족, 형제자매(이하 "법정대리인등"이라 한다)가 위원회에 제출할 서약서에는 그 법정대리인등과 피치료감호자의 성명, 연령, 등록기준지, 주거, 직업 및 치료를 받을 병원명 등을 적고 입원보증서 등 자료를 첨부하여야 한다.', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3871, '제7조의2(피치료감호청구인의 처우)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3872, '제7조의3(격리 등 제한의 금지)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3873, '제8조(처우개선의 청원)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3874, '제9조(피보호관찰자의 준수사항)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3875, '제9조의2(피보호관찰자의 준수사항 변경 등)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3876, '제9조의3(피보호관찰자에 대한 경고) 보호관찰소의 장은 법 제33조제5항에 따라 피보호관찰자에게 경고를 하는 경우에는 문서로 하여야 한다.', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3877, '제10조(피보호관찰자 등의 신고의무)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3878, '제11조(보호관찰관의 임무)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3879, '제11조의2(유치허가신청의 방식 등)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3880, '제11조의3(유치허가신청의 관할) 제11조의2제1항에 따른 유치허가신청을 할 때에는 해당 보호관찰소의 소재지 관할 지방검찰청 또는 지청의 검사에게 하여야 한다.', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3881, '제11조의4(가종료등의 취소 신청 등)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3882, '제11조의5(유치기간연장결정의 통지) 관할 지방법원 판사는 법 제33조의2제6항 단서에 따라 유치기간을 연장한 경우에는 지체 없이 보호관찰소의 장에게 그 사실을 알려야 한다.', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3883, '제12조(신고 의무의 고지) 치료감호시설의 장은 피보호관찰자가 출소할 때에는 죄를 다시 범하지 아니하도록 엄중 훈계하고, 법 제34조제2항에 따른 출소 후 신고를 관할 보호관찰관에게 할 것을 고지하여야 한다. <개정 2014.1.28>', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3884, '제13조(신고와 출소 통보)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3885, '제13조의2(보호관찰소와 정신건강복지센터의 공조 범위)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3886, '제14조(위원회의 구성)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3887, '제15조(위원회의 직원)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3888, '제16조(심사자료 송부 요청) 위원회는 법 제37조제3항에 규정된 사항(이하 "치료감호사안"이라 한다)을 심사할 때 검사, 치료감호시설의 장 또는 보호관찰관에게 치료감호사안 조사기록, 형 및 치료감호 집행기록 또는 보호관찰부 등 심사 자료의 송부를 요청할 수 있다. <개정 2014.1.28>', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3889, '제17조(검사의 심사신청)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3890, '제18조(피치료감호자 등의 심사신청)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3891, '제19조(위원회의 결정) 위원회는 다음 각 호의 어느 하나에 해당하는 경우에는 지체 없이 이를 심사ㆍ결정하고, 위원장과 출석위원이 기명ㆍ날인한 결정서를 작성해야 한다. <개정 2021.4.6>', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3892, '제20조(결정서의 기재 요건) 결정서에는 피치료감호자의 성명ㆍ연령ㆍ등록기준지ㆍ주거 및 감호소의 명칭과 결정 주문(主文) 및 이유를 적어야 한다. 법 제43조에 따른 검사의 심사신청에 대하여는 결정서에 검사의 관직 및 성명을 함께 적는다.', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3893, '제21조(결정의 송달 등)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3894, '제22조(회의록)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3895, '제23조(수당 등)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3896, '제24조(위원회의 운영세칙) 이 영에 규정된 사항 외에 위원회의 운영에 필요한 사항은 위원회의 의결을 거쳐 위원장이 정한다.', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3897, '제25조(판결 전 조사) 법원은 법 제44조의3제1항에 따라 피고인의 주거지 또는 그 법원의 소재지를 관할하는 보호관찰소의 장에게 조사를 요구하는 경우에는 피고인의 인적사항 및 범죄사실의 요지를 통보하여야 한다. 이 경우 필요하다고 인정하면 참고자료를 송부할 수 있다.', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3898, '제25조의2', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3899, '제26조(집행지휘의 방식) 검사는 법 제44조의6제1항에 따라 치료명령의 집행을 지휘하는 경우에는 법 제44조의2제1항에 따른 치료를 명하는 판결이 확정된 후 지체 없이 치료명령을 선고받은 사람(이하 "피치료명령자"라 한다)의 주거지를 관할하는 보호관찰소의 장에게 판결문 등본을 첨부한 지휘 서면을 송부하여야 한다.', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3900, '제27조(치료명령 집행 전의 준비 등)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3901, '제28조(치료명령 집행계획의 수립) 보호관찰관은 법 제44조의6제1항에 따라 피치료명령자에 대한 치료명령을 집행하기 전에 다음 각 호의 사항을 종합적으로 고려한 치료명령 집행계획을 수립하여야 한다.', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3902, '제29조(인지행동 치료 등 심리치료 프로그램 등)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3903, '제30조(치료명령의 집행 확인 등)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3904, '제31조(치료명령 집행 협의체) 보호관찰소의 장은 치료명령의 집행에 관한 다음 각 호의 사항을 협의하기 위하여 필요하다고 인정하는 경우에는 보호관찰관, 정신건강의학과 전문의 및 「정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률」에 따른 정신건강전문요원 등 전문가로 구성된 치료명령 집행 협의체를 운영할 수 있다. <개정 2017.5.29>', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3905, '제32조(치료비용의 국가부담)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3906, '제33조(군치료감호심의위원회) 법 제50조제2항에 따른 군치료감호심의위원회에 관하여는 제14조부터 제24조까지를 준용한다. 이 경우 "법무부장관"은 "국방부장관"으로, "법무부"는 "국방부"로 본다.', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3907, '제34조(기부금품의 접수 등)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3908, '제35조(민감정보 및 고유식별정보의 처리)', 517);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3909, '제1조(목적) 이 규칙은 「치료감호 등에 관한 법률」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다. <개정 2016.12.2>', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3910, '제2조 삭제 <2008.12.12>', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3911, '제3조(치료감호청구의 방식)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3912, '제4조(조사사항)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3913, '제5조(치료감호영장청구서 등) 법 제6조제1항의 치료감호영장청구는 별지 제3호서식의 치료감호영장청구서로 하여야 하고, 같은 조 제2항의 치료감호영장신청은 별지 제4호서식의 치료감호영장신청서로 하여야 한다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3914, '제6조(송치서류)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3915, '제7조(치료감호불청구의 방식) 검사는 사법경찰관이 치료감호청구의견으로 송치한 사건이나 검사가 수사결과 보호구속한 사건에 대하여 치료감호를 청구하지 아니한다는 결정을 한 때에는 별지 제5호서식의 치료감호불청구결정서를 작성하고, 치료감호사건의 요지와 조사의 결과 및 청구를 하지 아니하는 이유를 적어야 한다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3916, '제8조(치료감호사건의 보고)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3917, '제9조(재판 결과의 통보) 지방검찰청 또는 지청에서는 치료감호사건에 대한 재판이 확정된 때에는 지체 없이 그 재판 결과를 송치사건처리결과통지 및 처분결과통보서송부표에 적어서 송치관서에 송부하여야 한다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3918, '제9조의2(치료감호 기간의 연장 신청 등)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3919, '제9조의3(경비보조 청구) 영 제4조의5제2항에 따른 경비보조 청구서는 별지 제5호의5서식과 같다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3920, '제10조(치료감호의 집행지휘서 등)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3921, '제11조(치료감호의 집행 지휘 등)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3922, '제12조(피치료감호자 동태보고서)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3923, '제12조의2(재이송 신청서) 영 제6조의2제1항에 따른 지정법무병원의 장의 피치료감호자 재이송 신청은 별지 제8호의3서식에 따른다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3924, '제13조(서약서)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3925, '제13조의2(피치료감호자등 보호원부) 영 제7조의3제5항에 따른 피치료감호자등 보호원부는 별지 제9호의2서식에 따른다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3926, '제14조(청원함 설치 등) 치료감호시설의 장은 법 제30조 및 영 제8조에 따른 피치료감호자 처우개선에 관한 청원을 보장하기 위하여 병동 등 이용하기 쉬운 장소에 청원함을 설치하고 안내문을 게시하여야 하며, 청원의 접수ㆍ처리 등을 위하여 별지 제10호서식의 청원관리부를 갖춰 두고 운용하여야 한다. <개정 2014.1.29>', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3927, '제15조(보호관찰에 관한 지시)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3928, '제16조(진술서)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3929, '제16조의2(준수사항의 추가ㆍ변경 또는 삭제 신청 등) 법 제33조제3항 및 영 제9조의2제2항에 따른 피보호관찰자의 준수사항 전부 또는 일부의 추가ㆍ변경 또는 삭제의 신청은 별지 제12호의2서식에 따른다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3930, '제16조의3(경고장) 영 제9조의3에 따른 피보호관찰자에 대한 경고는 별지 제12호의3서식에 따른다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3931, '제17조(피보호관찰자 정기신고서) 영 제10조제1항의 정기신고는 별지 제13호서식의 피보호관찰자 정기신고서로 하여야 한다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3932, '제18조(신고접수부 및 피보호관찰자의 주거이전ㆍ여행 신고)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3933, '제18조의2(유치허가신청서 등)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3934, '제18조의3(가종료 또는 치료 위탁의 취소 신청 및 결정 통보)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3935, '제19조(보호관찰부)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3936, '제20조(보호관찰관의 보고) 보호관찰관은 영 제11조제3항ㆍ제4항ㆍ제7항, 영 제13조제6항 또는 이 규칙 제15조제2항에 따른 보고를 할 때에는 별지 제18호서식의 보호관찰보고서 2부를 작성하여 1부는 검사에게 송부하고, 1부는 위원회에 송부한다. <개정 2014.1.29>', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3937, '제21조(여행지 보호관찰관의 임무)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3938, '제22조(검사의 자료 이송) 피보호관찰자가 주거를 이전한 경우 피보호관찰자에 대한 자료를 보존 중인 검찰청의 검사는 피보호관찰자의 새 주거지 관할 검찰청에 그 자료를 송부하여야 한다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3939, '제23조(출소신고서 등)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3940, '제24조(가종료 등의 취소와 치료감호의 재집행)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3941, '제25조(이송을 위한 수용) 치료감호가 종료된 수형자를 치료감호시설에서 교도소 또는 소년교도소로 이송하는 경우에는 이송에 필요한 기간 동안 치료감호시설에 일시 수용할 수 있다. <개정 2014.1.29>', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3942, '제26조(보호관찰관 등의 주의 의무) 보호관찰관이 피보호관찰자를 출석하게 하여 법 제33조에 따른 준수사항 또는 그 밖에 지도ㆍ감독상 필요한 사실을 확인하는 경우, 관계자의 협조를 요청하는 경우, 검사 또는 사법경찰관리가 특히 치료감호만을 청구하기 위하여 조사를 하는 경우에는 치료감호대상자나 그 밖의 관계자의 생업에 지장을 초래하거나 명예를 훼손하지 아니하도록 주의하여야 한다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3943, '제26조의2(외래진료의 기간ㆍ방법 등)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3944, '제26조의3(외래진료비용)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3945, '제26조의4(정신보건 관련 정보 요청서 등)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3946, '제27조(가종료 등의 결정기준) 위원회가 법 제37조제3항에 규정된 사항(이하 "치료감호사안"이라 한다)을 심사ㆍ결정할 때에는 피치료감호자의 연령ㆍ건강상태ㆍ경력ㆍ가족관계ㆍ가정환경ㆍ범죄경력ㆍ치료 경과ㆍ준수사항의 이행 여부, 그 밖에 필요한 사항을 고려하여야 한다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3947, '제28조(조사공무원의 임명) 법 제40조제2항에 따라 위원회의 명을 받아 조사의 직무를 수행할 조사공무원은 법무부 소속 공무원 중에서 법무부장관이 임명한다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3948, '제29조(조사의 촉탁) 검사인 조사공무원은 치료감호사안을 조사하는 데에 필요하면 지방검찰청 또는 지청의 검사에게 그 조사를 촉탁할 수 있다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3949, '제30조(조사공무원의 의견) 조사공무원은 위원회에 제출하는 조사보고서에 의견을 첨부할 수 있다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3950, '제31조(심사신청서 등)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3951, '제32조(위원회의 결정서) 영 제19조에 따른 결정서의 서식은 별지 제28호서식과 같다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3952, '제33조(송달 등의 방법)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3953, '제34조(수당 등) 영 제23조에 따른 출석수당 및 여비는 별표와 같다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3954, '제35조(장부 및 서류의 비치) 치료감호대상사건 및 치료감호사안의 조사 사무를 처리하는 관서에는 다음 각 호의 장부 및 서류를 갖춰 두어야 한다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3955, '제36조(장부 및 서류의 보존기간) 장부 및 서류는 다음의 기간 동안 보존하여야 한다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3956, '제37조(치료감호사건기록의 보존기간) 완결된 치료감호사건기록은 치료감호의 시효가 완성될 때까지 보존하여야 한다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3957, '제38조(치료감호사안 조사기록의 보존기관 등)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3958, '제39조(「검찰사건사무규칙」 등의 준용) 치료감호대상사건이나 치료감호사안의 조사ㆍ보고 및 집행의 절차와 서식에 관하여 이 규칙에 특별한 규정이 있는 경우를 제외하고는 그 성질에 반하지 아니하는 범위에서 「검사와 사법경찰관의 상호협력과 일반적 수사준칙에 관한 규정」 및 「검찰사건사무규칙」, 「검찰압수물 사무규칙」, 「자유형등에 관한 검찰집행사무규칙」, 「검찰보존사무규칙」, 「검찰보고사무규칙」을 준용한다. <개정 2011.12.30, 2021.1.1>', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3959, '제40조(집행지휘 서면) 영 제26조에 따른 지휘 서면은 별지 제30호서식에 따른다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3960, '제41조(치료기관의 지정기준 등)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3961, '제42조(치료비용 국가부담 신청서) 영 제32조제2항에 따른 치료비용 국가부담 신청서는 별지 제31호서식에 따른다.', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3962, '제43조(자료제출 요청 등)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3963, '제44조(기부금품의 접수 영수증 등)', 518);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3964, '제1조(목적) 이 법은 헌법의 존립을 해치거나 헌정질서의 파괴를 목적으로 하는 헌정질서 파괴범죄에 대한 공소시효의 배제 등에 관한 사항을 규정함으로써 헌법상 자유민주적 기본질서를 수호함을 목적으로 한다.', 519);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3965, '제2조(정의) 이 법에서 "헌정질서 파괴범죄"란 「형법」 제2편제1장 내란의 죄, 제2장 외환의 죄와 「군형법」 제2편제1장 반란의 죄, 제2장 이적(利敵)의 죄를 말한다.', 519);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3966, '제3조(공소시효의 적용 배제) 다음 각 호의 범죄에 대하여는 「형사소송법」 제249조부터 제253조까지 및 「군사법원법」 제291조부터 제295조까지에 규정된 공소시효를 적용하지 아니한다.', 519);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3967, '제4조(재정신청에 관한 특례)', 519);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3968, '제1조(목적) 이 법은 죄를 지은 사람으로서 재범 방지를 위하여 보호관찰, 사회봉사, 수강(受講) 및 갱생보호(更生保護) 등 체계적인 사회 내 처우가 필요하다고 인정되는 사람을 지도하고 보살피며 도움으로써 건전한 사회 복귀를 촉진하고, 효율적인 범죄예방 활동을 전개함으로써 개인 및 공공의 복지를 증진함과 아울러 사회를 보호함을 목적으로 한다.', 520);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3969, '제2조(국민의 협력 등)', 520);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3970, '제3조(대상자)', 520);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3971, '제4조(운영의 기준) 보호관찰, 사회봉사, 수강 또는 갱생보호는 해당 대상자의 교화, 개선 및 범죄예방을 위하여 필요하고도 적절한 한도 내에서 이루어져야 하며, 대상자의 나이, 경력, 심신상태, 가정환경, 교우관계, 그 밖의 모든 사정을 충분히 고려하여 가장 적합한 방법으로 실시되어야 한다.', 520);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3972, '제5조(설치)', 522);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3973, '제6조(관장 사무) 심사위원회는 이 법에 따른 다음 각 호의 사항을 심사ㆍ결정한다.', 522);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3974, '제7조(구성)', 522);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3975, '제8조(위원의 임기) 위원의 임기는 2년으로 하되, 연임할 수 있다. 다만, 공무원인 비상임위원의 임기는 그 직위에 있는 기간으로 한다.', 522);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3976, '제9조(위원의 해임 및 해촉) 위원이 다음 각 호의 어느 하나에 해당하면 해임하거나 해촉할 수 있다.', 522);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3977, '제10조(위원의 신분 등)', 522);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3978, '제11조(심사)', 522);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3979, '제12조(의결 및 결정)', 522);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3980, '제12조의2(벌칙 적용에서 공무원 의제) 심사위원회의 위원 중 공무원이 아닌 사람은 「형법」 제127조 및 제129조부터 제132조까지의 규정을 적용할 때에는 공무원으로 본다.', 522);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3981, '제13조(명칭, 관할 구역, 운영 등) 심사위원회의 명칭, 관할 구역 및 직무범위와 위원의 임명 또는 위촉, 그 밖에 심사위원회의 운영에 필요한 사항은 대통령령으로 정한다.', 522);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3982, '제14조(보호관찰소의 설치)', 523);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3983, '제15조(보호관찰소의 관장 사무) 보호관찰소(보호관찰지소를 포함한다. 이하 같다)는 다음 각 호의 사무를 관장한다.', 523);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3984, '제16조(보호관찰관)', 523);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3985, '제17조(보호관찰소의 명칭 등) 보호관찰소의 명칭, 관할 구역, 조직 및 정원, 그 밖에 필요한 사항은 대통령령으로 정한다.', 523);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3986, '제18조(범죄예방 자원봉사위원)', 523);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3987, '제19조(판결 전 조사)', 525);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3988, '제19조의2(결정 전 조사)', 525);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3989, '제20조(판결의 통지 등)', 526);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3990, '제21조(교도소장 등의 통보의무)', 527);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3991, '제22조(가석방ㆍ퇴원 및 임시퇴원의 신청)', 527);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3992, '제23조(가석방ㆍ퇴원 및 임시퇴원의 심사와 결정)', 527);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3993, '제24조(성인수형자에 대한 보호관찰의 심사와 결정)', 527);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3994, '제25조(법무부장관의 허가) 심사위원회는 제23조에 따른 심사 결과 가석방, 퇴원 또는 임시퇴원이 적절하다고 결정한 경우 및 제24조에 따른 심사 결과 보호관찰이 필요없다고 결정한 경우에는 결정서에 관계 서류를 첨부하여 법무부장관에게 이에 대한 허가를 신청하여야 하며, 법무부장관은 심사위원회의 결정이 정당하다고 인정하면 이를 허가할 수 있다.', 527);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3995, '제26조(환경조사)', 528);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3996, '제27조(환경개선활동)', 528);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3997, '제28조(성인수형자에 대한 보호관찰 사안조사)', 528);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3998, '제29조(보호관찰의 개시 및 신고)', 529);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (3999, '제30조(보호관찰의 기간) 보호관찰 대상자는 다음 각 호의 구분에 따른 기간에 보호관찰을 받는다.', 529);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4000, '제31조(보호관찰 담당자) 보호관찰은 보호관찰 대상자의 주거지를 관할하는 보호관찰소 소속 보호관찰관이 담당한다.', 529);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4001, '제32조(보호관찰 대상자의 준수사항)', 529);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4002, '제33조(지도ㆍ감독)', 529);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4003, '제33조의2(분류처우)', 529);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4004, '제34조(원호)', 529);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4005, '제35조(응급구호) 보호관찰소의 장은 보호관찰 대상자에게 부상, 질병, 그 밖의 긴급한 사유가 발생한 경우에는 대통령령으로 정하는 바에 따라 필요한 구호를 할 수 있다.', 529);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4006, '제36조(갱생보호사업자 등의 원조와 협력) 보호관찰소의 장은 제34조에 따른 원호와 제35조에 따른 응급구호를 위하여 필요한 경우에는 국공립기관, 제67조제1항에 따라 갱생보호사업 허가를 받은 자, 제71조에 따른 한국법무보호복지공단, 그 밖의 단체에 대하여 숙식 제공이나 그 밖의 적절한 원조 또는 협력을 요청할 수 있다. 이 경우 필요한 비용은 국가가 예산의 범위에서 지급한다.', 529);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4007, '제36조의2(정신질환 보호관찰 대상자의 치료 등을 위한 협력)', 529);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4008, '제37조(보호관찰 대상자 등의 조사)', 529);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4009, '제38조(경고) 보호관찰소의 장은 보호관찰 대상자가 제32조의 준수사항을 위반하거나 위반할 위험성이 있다고 인정할 상당한 이유가 있는 경우에는 준수사항의 이행을 촉구하고 형의 집행 등 불리한 처분을 받을 수 있음을 경고할 수 있다.', 529);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4010, '제39조(구인)', 529);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4011, '제40조(긴급구인)', 529);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4012, '제41조(구인 기간) 보호관찰소의 장은 제39조 또는 제40조에 따라 보호관찰 대상자를 구인하였을 때에는 제42조에 따라 유치(留置) 허가를 청구한 경우를 제외하고는 구인한 때부터 48시간 이내에 석방하여야 한다. 다만, 제42조제2항에 따른 유치 허가를 받지 못하면 즉시 보호관찰 대상자를 석방하여야 한다. <개정 2014.12.30>', 529);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4013, '제42조(유치)', 529);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4014, '제43조(유치기간)', 529);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4015, '제44조(유치의 해제) 보호관찰소의 장은 다음 각 호의 어느 하나에 해당하는 경우에는 유치를 해제하고 보호관찰 대상자를 즉시 석방하여야 한다.', 529);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4016, '제45조(유치기간의 형기 산입) 제42조에 따라 유치된 사람에 대하여 보호관찰을 조건으로 한 형의 선고유예가 실효되거나 집행유예가 취소된 경우 또는 가석방이 취소된 경우에는 그 유치기간을 형기에 산입한다.', 529);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4017, '제45조의2 삭제 <2019.4.16>', 529);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4018, '제46조(준용 규정) 보호관찰 대상자의 구인 및 유치에 관하여는 「형사소송법」 제72조, 제75조, 제82조, 제83조, 제85조제1항ㆍ제3항ㆍ제4항, 제86조, 제87조, 제89조, 제204조, 제214조의2 및 제214조의3을 준용한다.', 529);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4019, '제46조의2(보호장구의 사용)', 530);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4020, '제46조의3(보호장구의 종류 및 사용요건)', 530);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4021, '제46조의4(보호장구 사용의 고지 등)', 530);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4022, '제46조의5(보호장구 남용 금지) 제46조의3제1항에 따른 보호장구는 필요한 최소한의 범위에서 사용하여야 하며, 보호장구를 사용할 필요가 없게 되면 지체 없이 사용을 중지하여야 한다.', 530);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4023, '제47조(보호관찰을 조건으로 한 형의 선고유예의 실효 및 집행유예의 취소)', 531);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4024, '제48조(가석방 및 임시퇴원의 취소)', 531);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4025, '제49조(보호처분의 변경)', 531);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4026, '제50조(부정기형의 종료 등)', 531);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4027, '제51조(보호관찰의 종료)', 531);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4028, '제52조(임시해제)', 531);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4029, '제53조(보호관찰의 정지)', 531);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4030, '제54조(직무상 비밀과 증언 거부) 심사위원회 및 보호관찰소의 직원이거나 직원이었던 사람이 다른 법률에 따라 증인으로 신문(訊問)을 받는 경우에는 그 직무상 알게 된 다른 사람의 비밀에 대하여 증언을 거부할 수 있다. 다만, 본인의 승낙이 있거나 중대한 공익상 필요가 있는 경우에는 그러하지 아니하다.', 532);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4031, '제55조(보호관찰사건의 이송) 보호관찰소의 장은 보호관찰 대상자가 주거지를 이동한 경우에는 새 주거지를 관할하는 보호관찰소의 장에게 보호관찰사건을 이송할 수 있다.', 532);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4032, '제55조의2(기부금품의 접수)', 532);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4033, '제55조의3(보호관찰 종료사실 등의 통보)', 532);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4034, '제55조의4(범죄경력자료 등의 조회 요청)', 532);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4035, '제56조(군법 적용 대상자에 대한 특례) 「군사법원법」 제2조제1항 각 호의 어느 하나에 해당하는 사람에게는 이 법을 적용하지 아니한다.', 532);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4036, '제57조(「형사소송법」의 준용) 보호관찰에 관하여 이 법에 특별한 규정이 있는 경우를 제외하고는 그 성질에 반하지 아니하는 범위에서 「형사소송법」을 준용한다.', 532);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4037, '제58조(「형의 집행 및 수용자의 처우에 관한 법률」 적용의 일부 배제) 이 법(제28조는 제외한다)에 따른 가석방에 관하여는 「형의 집행 및 수용자의 처우에 관한 법률」 제119조부터 제122조까지의 규정을 적용하지 아니한다.', 532);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4038, '제59조(사회봉사명령ㆍ수강명령의 범위)', 533);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4039, '제60조(판결의 통지 등)', 533);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4040, '제61조(사회봉사ㆍ수강명령 집행 담당자)', 533);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4041, '제62조(사회봉사ㆍ수강명령 대상자의 준수사항)', 533);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4042, '제63조(사회봉사ㆍ수강의 종료)', 533);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4043, '제64조(준용 규정)', 533);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4044, '제65조(갱생보호의 방법)', 535);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4045, '제66조(갱생보호의 신청 및 조치)', 535);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4046, '제67조(갱생보호사업의 허가)', 536);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4047, '제68조(허가의 기준) 법무부장관은 다음 각 호의 기준에 맞지 아니할 때에는 갱생보호사업의 허가를 하여서는 아니 된다.', 536);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4048, '제69조(보고의무) 갱생보호사업의 허가를 받은 자(이하 "사업자"라 한다)는 법무부령으로 정하는 바에 따라 다음 해의 사업계획과 전년도의 회계 상황 및 사업 실적을 법무부장관에게 보고하여야 한다.', 536);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4049, '제70조(갱생보호사업의 허가 취소 등) 법무부장관은 사업자가 다음 각 호의 어느 하나에 해당할 때에는 그 허가를 취소하거나 6개월 이내의 기간을 정하여 그 사업의 전부 또는 일부의 정지를 명할 수 있다. 다만, 제1호 또는 제4호에 해당하는 때에는 그 허가를 취소하여야 한다.', 536);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4050, '제70조의2(청문) 법무부장관은 제70조에 따라 갱생보호사업의 허가를 취소하거나 정지하려는 경우에는 청문을 하여야 한다. <개정 2014.5.20>', 536);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4051, '제71조(한국법무보호복지공단의 설립) 갱생보호사업을 효율적으로 추진하기 위하여 한국법무보호복지공단(이하 "공단"이라 한다)을 설립한다.', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4052, '제72조(법인격) 공단은 법인으로 한다.', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4053, '제73조(사무소)', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4054, '제74조(정관)', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4055, '제75조(등기) 공단은 그 주된 사무소의 소재지에서 설립등기를 함으로써 성립한다.', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4056, '제76조(임원 및 그 임기)', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4057, '제77조(임원의 직무)', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4058, '제78조(임원의 결격사유) 다음 각 호의 어느 하나에 해당하는 사람은 공단의 임원이 될 수 없다.', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4059, '제79조(임원의 해임)', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4060, '제80조(이사회)', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4061, '제81조(직원의 임면) 공단의 직원은 정관으로 정하는 바에 따라 이사장이 임면(任免)한다.', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4062, '제82조(공단의 사업) 공단은 그 목적을 달성하기 위하여 다음 각 호의 사업을 한다.', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4063, '제83조(공단의 자산) 공단은 다음 각 호의 재산을 그 자산으로 한다.', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4064, '제84조(공단의 사업계획 등)', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4065, '제85조(기부금품의 접수 및 보고)', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4066, '제86조(갱생보호기금의 설치) 갱생보호사업의 추진에 필요한 재원을 확보하기 위하여 공단에 갱생보호기금(이하 "기금"이라 한다)을 설치한다.', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4067, '제87조(기금의 재원) 기금은 다음 각 호의 재원으로 조성한다.', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4068, '제88조(기금의 운용ㆍ관리)', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4069, '제89조(기금의 사용) 기금은 제82조 각 호의 사업을 위하여 사용한다.', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4070, '제90조(자금의 차입) 공단은 기금 운용에 필요하다고 인정하면 법무부장관의 승인을 받아 기금의 부담으로 자금을 차입할 수 있다.', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4071, '제91조(이익금의 처리) 공단은 매 사업연도의 결산 결과 이익금이 생기면 이월손실금의 보전(補塡)에 충당하고, 그 나머지는 기금으로 적립하여야 한다.', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4072, '제92조(준용 규정) 공단에 관하여 이 법에서 규정한 것을 제외하고는 「민법」 중 재단법인에 관한 규정을 준용한다.', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4073, '제93조(벌칙 적용 시의 공무원 의제) 공단의 임직원은 「형법」과 그 밖의 법률에 따른 벌칙을 적용할 때에는 공무원으로 본다.', 537);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4074, '제94조(보조금) 국가나 지방자치단체는 사업자와 공단에 대하여 보조할 수 있다.', 538);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4075, '제95조(조세감면) 국가나 지방자치단체는 갱생보호사업에 대하여 「조세특례제한법」 및 「지방세특례제한법」에서 정하는 바에 따라 국세 또는 지방세를 감면할 수 있다. <개정 2010.3.31>', 538);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4076, '제96조(수익사업)', 538);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4077, '제97조(감독)', 538);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4078, '제98조(유사명칭의 사용금지)', 538);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4079, '제99조(벌칙) 다음 각 호의 어느 하나에 해당하는 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 2014.1.7>', 539);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4080, '제100조(양벌규정) 법인의 대표자나 법인 또는 개인의 대리인, 사용인, 그 밖의 종업원이 그 법인 또는 개인의 업무에 관하여 제99조의 위반행위를 하면 그 행위자를 벌하는 외에 그 법인 또는 개인에게도 해당 조문의 벌금형을 과(科)한다. 다만, 법인 또는 개인이 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다.', 539);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4081, '제101조(과태료)', 539);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4082, '제1조(목적) 이 영은 「보호관찰 등에 관한 법률」(이하 "법"이라 한다)에서 위임된 사항과 그 시행에 관하여 필요한 사항을 규정함을 목적으로 한다. <개정 2006.3.23>', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4083, '제2조(보호관찰심사위원회의 위원장)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4084, '제3조(위원의 자격 및 임명)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4085, '제4조(심사위원회의 간사 및 서기)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4086, '제5조(심사)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4087, '제6조(의결 및 결정)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4088, '제6조의2(교육훈련)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4089, '제7조(판결 및 결정 전 조사) 법원은 보호관찰소의 장에게 법 제19조제1항 또는 제19조의2제1항에 따른 조사를 요구하는 때에는 피고인 또는 소년의 인적사항 및 범죄사실의 요지를 통보하여야 한다. 이 경우 필요하다고 인정하는 때에는 참고자료를 송부할 수 있다. <개정 2009.3.18>', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4090, '제8조(수용기관의 장의 통보의무)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4091, '제9조(가석방ㆍ퇴원 및 임시퇴원의 신청) 수용기관의 장은 법 제22조에 따라 가석방, 퇴원 또는 임시퇴원의 심사를 신청하고자 하는 경우에는 소년수형자 또는 보호소년의 신상에 관한 사항, 범죄 및 비행에 관한 사항, 교정성적 등을 종합적으로 고려하여야 한다. <개정 2008.6.20, 2009.3.18>', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4092, '제10조(직권심사) 심사위원회는 법 제23조제2항, 법 제48조제1항, 법 제50조제1항, 법 제52조제1항ㆍ제3항 또는 법 제53조제1항의 규정에 의하여 직권으로 심사를 하는 경우에는 심사대상자를 수용하는 수용기관의 장 또는 관할보호관찰소의 장의 의견을 들어야 한다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4093, '제11조(가석방등의 결정)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4094, '제12조(환경조사)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4095, '제13조(환경개선활동의 방법) 보호관찰소의 장은 법 제27조제1항의 규정에 의한 환경개선활동을 하는 경우에는 수용자와의 면접 또는 통신, 가족 및 관계인과의 협의, 수용기관 기타 관계기관의 협조 등의 방법으로 지속적으로 실시하여야 하며, 본인의 의사를 존중하고 본인ㆍ가족 및 관계인의 신뢰와 협력을 얻도록 노력하여야 한다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4096, '제14조(보호관찰사안조사) 교도소ㆍ구치소ㆍ소년교도소의 장은 법 제28조제1항의 규정에 의하여 가석방심사신청대상자의 명단과 신상조사서를 심사위원회에 송부한 후 그 대상자의 신상에 변동이 있을 때에는 심사위원회에 그 사실을 통지하여야 한다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4097, '제15조(수용기관의 장의 협조) 수용기관의 장은 심사위원회 또는 보호관찰소의 장으로부터 수용자와의 면접, 관계기록의 열람 등 필요한 협조요청을 받은 경우에는 이에 응하여야 한다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4098, '제16조(보호관찰대상자의 신고의무) 법 제3조제1항의 규정에 의한 보호관찰대상자(이하 "보호관찰대상자"라 한다)는 다음 각 호의 어느 하나에 해당하는 때에는 10일이내에 주거지를 관할하는 보호관찰소에 출석하여 서면으로 법 제29조제2항의 규정에 의한 신고를 하여야 한다. <개정 2006.3.23, 2008.6.20, 2009.3.18, 2019.11.5>', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4099, '제17조(준수사항의 부과 및 훈계) 법원 또는 심사위원회는 법 제32조의 규정에 의하여 보호관찰대상자에게 준수사항을 과할 때에는 보호관찰의 취지를 설명하고, 준수사항을 기재한 서면을 교부하여야 하며, 적절한 훈계를 할 수 있다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4100, '제18조(주거이전등의 신고)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4101, '제19조(특별준수사항) 법 제32조제3항제10호에서 "대통령령으로 정하는 사항"이란 다음 각 호의 사항을 말한다. <개정 2021.1.5>', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4102, '제19조의2(준수사항의 추가 등 신청)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4103, '제19조의3(분류처우계획의 수립 등)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4104, '제20조(응급구호의 범위)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4105, '제20조의2(정신질환 보호관찰 종료사실 통보 절차 등)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4106, '제21조(보호관찰대상자등의 소환 및 조사)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4107, '제22조(보호관찰대상자에 대한 경고) 보호관찰소의 장은 법 제38조의 규정에 의하여 경고를 하는 때에는 보호관찰대상자에게 경고이유등을 서면으로 고지하여야 한다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4108, '제23조(구인신청의 방식) 보호관찰소의 장은 법 제39조제1항의 규정에 의하여 보호관찰대상자의 구인을 신청하는 때에는 다음 각호의 사항을 기재한 서면에 의하여야 한다. <개정 2009.11.23>', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4109, '제24조(구인장의 방식) 법 제39조제1항의 규정에 의하여 판사가 발부하는 구인장에는 청구한 검사의 관직ㆍ성명 및 제23조 각호의 사항을 기재하여야 한다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4110, '제25조(구인장의 집행의뢰) 보호관찰관은 법 제39조제2항 단서의 규정에 의하여 사법경찰관리에게 구인장의 집행을 의뢰하는 때에는 그 사유를 기재한 서면으로 하되, 검사의 지휘를 받아야 한다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4111, '제26조(긴급구인승인신청등)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4112, '제27조(구인후 조사 및 심문)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4113, '제28조(유치허가신청의 방식) 보호관찰소의 장은 법 제42조제2항의 규정에 의하여 보호관찰대상자의 유치허가신청을 하는 때에는 다음 각호의 사항을 기재한 서면에 의하여야 한다. <개정 2009.11.23>', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4114, '제29조(유치허가장의 방식) 법 제42조제2항의 규정에 의하여 판사가 발부하는 유치허가장에는 청구한 검사의 관직ㆍ성명ㆍ발부일시 및 제28조 각호의 사항을 기재하여야 한다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4115, '제30조(구인ㆍ긴급구인승인 및 유치허가신청의 관할) 보호관찰소의 장은 그 소재지를 관할하는 지방검찰청 또는 지청의 검사에게 구인ㆍ긴급구인승인 및 유치허가의 신청을 한다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4116, '제31조(유치기간연장결정의 통지) 법원은 법 제43조제2항의 규정에 의하여 유치기간을 연장한 때에는 지체없이 보호관찰소의 장에게 그 사실을 통지하여야 한다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4117, '제32조(보호관찰을 조건으로 한 형의 선고유예의 실효 및 집행유예의 취소청구신청등)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4118, '제33조(취소청구신청에 대한 결과 통지) 검사는 법 제42조제1항제1호의 신청을 기각한 때 또는 보호관찰을 조건으로 한 형의 선고유예의 실효 및 집행유예의 취소청구에 대한 법원의 결정이 있는 때에는 지체없이 보호관찰소의 장에게 그 사실을 통지하여야 한다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4119, '제34조(가석방 및 임시퇴원의 취소와 재수용)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4120, '제35조(보호처분의 변경신청)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4121, '제36조(보호관찰정지자 소재 파악시의 통보) 보호관찰소의 장은 보호관찰정지중인 자의 소재를 파악한 때에는 지체없이 심사위원회에 그 사실을 통보하여야 한다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4122, '제36조의2(기부금품의 접수 등)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4123, '제36조의3(보호관찰 종료사실 등의 통보 절차) 법 제55조의3제1항에 따른 가석방자의 보호관찰 종료사실 등의 통보는 보호관찰소의 장이 관리하는 법 제55조의3제2항 각 호에 대한 전자기록을 「형사사법절차 전자화 촉진법」 제2조제4호에 따른 형사사법정보시스템에 등록하고, 경찰관서의 장이 이를 조회하는 방식 등으로 할 수 있다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4124, '제37조(사회봉사ㆍ수강명령 집행위탁의 통보) 보호관찰관이 법 제61조제2항의 규정에 의하여 사회봉사명령 또는 수강명령의 집행위탁 사실을 법원 또는 법원의 장에게 통보하는 때에는 집행위탁을 받은 기관의 명칭 및 주소, 위탁인원, 집행위탁의 내용 등을 기재한 서면에 의하여야 한다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4125, '제38조(사회봉사ㆍ수강명령 집행위탁의 취소에 따른 조치) 법원이 법 제61조제3항의 규정에 의하여 사회봉사명령 또는 수강명령의 집행위탁을 취소한 경우에는 보호관찰관이 남은 기간의 사회봉사명령 또는 수강명령을 직접 집행하거나 적합한 다른 국ㆍ공립기관 기타 단체에 위탁하여 집행하여야 한다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4126, '제39조(준용)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4127, '제40조(갱생보호)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4128, '제41조(숙식 제공)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4129, '제41조의2(주거 지원) 법 제65조제1항제2호에 따른 주거 지원은 갱생보호 대상자에게 주택의 임차에 필요한 지원을 하는 것으로 한다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4130, '제41조의3(창업 지원) 법 제65조제1항제3호에 따른 창업 지원은 갱생보호 대상자에게 창업에 필요한 사업장 임차보증금 등을 지원하는 것으로 한다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4131, '제42조 삭제 <2014.11.19>', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4132, '제43조 삭제 <2014.11.19>', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4133, '제44조(직업훈련)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4134, '제45조(취업 지원) 법 제65조제1항제4호에 따른 취업 지원은 갱생보호 대상자에게 직장을 알선하고 필요한 경우 신원을 보증하는 것으로 한다. <개정 2014.11.19>', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4135, '제45조의2(출소예정자 사전상담)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4136, '제45조의3(갱생보호 대상자의 가족에 대한 지원) 법 제65조제1항제6호에 따른 갱생보호 대상자의 가족에 대한 지원은 갱생보호 대상자의 가족에게 심리상담 및 심리치료, 취업 지원, 학업 지원 등을 하는 것으로 한다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4137, '제45조의4(심리상담 및 심리치료) 법 제65조제1항제7호에 따른 심리상담 및 심리치료는 갱생보호 대상자에게 심리적 안정과 사회적응을 위한 상담 및 「정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률」에 따른 정신건강전문요원 등 전문가에 의한 치료를 실시하는 것으로 한다. <개정 2017.5.29>', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4138, '제45조의5(사후관리) 법 제65조제1항제8호에 따른 사후관리는 같은 항 제1호부터 제7호까지 또는 제9호의 갱생보호를 받은 갱생보호 대상자에게 사회복귀 상황을 점검하여 필요한 조언을 하는 것으로 한다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4139, '제46조(자립 지원) 법 제65조제1항제9호에 따른 갱생보호 대상자에 대한 자립 지원은 사회복지시설에의 의탁 알선, 가족관계 등록 창설, 주민등록, 결혼 주선, 입양 및 의료 시혜 등 갱생보호 대상자의 자립을 위하여 필요한 사항을 지원하는 것으로 한다. <개정 2014.11.19>', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4140, '제46조의2(갱생보호 대상자 수용기간 등의 통보 요청)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4141, '제47조(공단의 기부금품 접수 등) 법 제85조에 따른 기부금품의 접수  등에 관하여는 제36조의2제1항 및 제3항부터 제6항까지의 규정을 준용한다. 이 경우 "보호관찰소의 장"은 "공단"으로 본다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4142, '제48조(기금의 운용ㆍ관리) 공단은 법 제86조에 따라 설치된 갱생보호기금(이하 "기금"이라 한다)을 별도 계정으로 관리하여야 한다. <개정 2009.3.18, 2014.11.19>', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4143, '제49조(기금의 운용ㆍ관리계획)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4144, '제50조(기금운용에 관한 보고)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4145, '제51조(민감정보 및 고유식별정보의 처리)', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4146, '제52조(과태료의 부과기준) 법 제101조제1항에 따른 과태료의 부과기준은 별표와 같다.', 540);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4147, '제1조(목적) 이 규칙은 「보호관찰 등에 관한 법률」 및 같은 법 시행령에서 위임된 사항과 그 시행에 관하여 필요한 사항을 규정함을 목적으로 한다. <개정 2009.3.19>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4148, '제2조(수당 및 여비) 「보호관찰 등에 관한 법률」(이하 "법"이라 한다) 제5조의 규정에 의한 보호관찰심사위원회(이하 "심사위원회"라 한다)의 위원장 및 비상임위원의 출석수당과 공무원이 아닌 위원의 여비는 별표와 같다. <개정 2009.3.19>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4149, '제3조(심사사건의 수리) 심사위원회는 법 제11조에 따라 심사를 하는 때에는 별지 제1호서식의 심사사건부에 정해진 사항을 기재해야 한다. <개정 2022.2.7>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4150, '제4조(면접조사표) 심사위원회의 상임위원 또는 보호관찰관은 법 제11조제2항의 규정에 의하여 보호관찰대상자 기타 관계인을 조사한 때에는 별지 제2호서식의 면접조사표를 작성하여야 한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4151, '제5조(결정서 등)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4152, '제6조(회의록 작성)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4153, '제7조(심사위원회의 운영세칙) 이 규칙에 규정된 사항외에 심사위원회의 운영에 관하여 필요한 사항은 심사위원회의 의결을 거쳐 위원장이 정한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4154, '제7조의2(교육훈련)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4155, '제7조의3(조사관)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4156, '제8조(범죄예방자원봉사위원의 위촉 및 해촉)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4157, '제9조(범죄예방위원의 정원) 범죄예방위원의 정원은 시(구가 설치되지 아니한 시를 말한다)ㆍ군ㆍ구별로 그 지역의 인구ㆍ범죄상황 기타 사정을 고려하여 인구 1천명당 1인의 범위내에서 법무부장관이 정한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4158, '제10조(범죄예방위원의 직무) 범죄예방위원은 다음 각호의 직무를 수행한다. <개정 2009.11.27>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4159, '제11조(범죄예방위원의 조직) 범죄예방위원의 체계적인 활동을 도모하기 위하여 법무부장관이 정하는 바에 의하여 범죄예방지도협의회와 범죄예방위원의 자치조직을 둘 수 있다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4160, '제11조의2(특별범죄예방자원봉사위원)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4161, '제12조(비용의 지급) 범죄예방위원과 특별범죄예방위원에 대하여는 예산의 범위안에서 그 직무수행에 필요한 실비를 지급한다. <개정 2009.11.27>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4162, '제13조(기간경과통보서) 영 제8조의 규정에 의한 기간경과통보서는 별지 제4호서식에 의한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4163, '제14조(기간경과통보서접수부) 심사위원회는 기간경과통보서를 접수한 때에는 별지 제5호서식의 기간경과통보서접수부에 정해진 사항을 기재해야 한다. <개정 2022.2.7>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4164, '제15조(수용자의 이송통지)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4165, '제16조(가석방 등의 심사신청서)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4166, '제17조(가석방ㆍ퇴원 및 임시퇴원의 결과통보) 심사위원회는 가석방 또는 임시퇴원이 허가된 자를 수용하는 수용기관의 장과 그의 주거지를 관할하는 보호관찰소의 장에게 그 명단과 결정서등본을 송부하여야 한다. 다만, 퇴원이 허가된 자 또는 가석방이 허가된 자중 법무부장관이 보호관찰이 필요없다고 인정한 자에 대하여는 수용기관의 장에게만 그 명단과 결정서등본을 송부한다. <개정 2009.3.19>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4167, '제18조(환경조사서) 법 제26조제2항의 규정에 의한 환경조사의 통보는 별지 제8호서식에 의한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4168, '제19조(환경개선활동결과통보서) 법 제27조제3항의 규정에 의한 환경개선활동결과통보는 별지 제9호서식에 의한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4169, '제20조(신고서) 영 제16조 및 제39조제1항에 따른 신고는 별지 제10호서식에 의한다. <개정 2009.11.27>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4170, '제21조(보호관찰사건부등)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4171, '제22조(보호관찰기간의 계산) 보호관찰기간은 법 제29조제1항의 규정에 의하여 보호관찰이 개시된 때부터 진행한다. 이 경우 초일은 보호관찰기간에 산입한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4172, '제23조(보호관찰담당자의 지명 및 임무)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4173, '제24조(주거이전 및 여행신고서) 영 제18조의 규정에 의한 주거이전 및 여행의 신고는 별지 제15호서식에 의한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4174, '제24조의2(준수사항의 추가 등) 법 제32조제4항에 따른 준수사항의 추가, 변경 또는 삭제의 신청 및 청구는 별지 제15호의2서식에 따른다. <개정 2019.10.17>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4175, '제25조(원호 및 응급구호부) 보호관찰관이 법 제34조에 따라 원호를 실시하거나 보호관찰소의 장이 법 제35조에 따라 응급구호를 실시한 때에는 별지 제16호서식의 원호 및 응급구호부에 정해진 사항을 기재해야 한다. <개정 2022.2.7>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4176, '제25조의2(원호협의회)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4177, '제25조의3(보호관찰 종료사실의 통보)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4178, '제26조(출석요구서) 영 제21조제1항의 규정에 의한 출석요구서는 별지 제17호서식에 의한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4179, '제27조(진술조서) 영 제21조제2항의 규정에 의한 조사는 별지 제18호서식에 의한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4180, '제28조(경고장) 영 제22조에 따른 경고는 별지 제19호서식에 따른다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4181, '제29조(구인장신청서등)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4182, '제30조(구인장) 영 제24조 및 제39조제2항에 따른 구인장은 별지 제22호서식에 의한다. <개정 2009.11.27>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4183, '제31조(구인장의 집행지휘) 검사는 구인장 위쪽에 집행을 지휘한다는 내용을 기재하고 서명 또는 기명날인의 방법으로 영 제25조의 규정에 의한 구인장의 집행을 지휘할 수 있다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4184, '제31조의2(보호장구의 사용절차 및 방법) 보호관찰소 소속 공무원은 법 제46조의2에 따라 보호장구를 사용하기 위해서는 사전에 보호관찰소의 장의 허가를 받아 별표 2의 방법으로 사용하여야 한다. 다만, 긴급한 경우에는 사용 후 즉시 보호관찰소의 장에게 보고하여야 한다. <개정 2019.10.17>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4185, '제32조(긴급구인서) 영 제26조 및 제39조제2항에 따른 긴급구인서는 별지 제23호서식에 의한다. <개정 2009.11.27>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4186, '제33조(유치허가신청서) 영 제28조에 따른 유치허가신청은 별지 제24호서식에 따른다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4187, '제34조(유치허가장) 영 제29조 및 제39조제2항에 따른 유치허가장은 별지 제25호서식에 의한다. <개정 2009.11.27>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4188, '제35조(보호관찰을 조건으로 한 형의 선고유예의 실효 및 집행유예의 취소신청서) 영 제32조 및 제39조제2항에 따른 선고유예의 실효 및 집행유예의 취소신청은 별지 제26호서식에 의한다. <개정 2009.11.27>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4189, '제36조(가석방 및 임시퇴원의 취소신청서) 법 제48조제1항의 규정에 의한 가석방 또는 임시퇴원의 취소신청은 별지 제27호서식에 의한다. <개정 2008.6.20>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4190, '제37조(가석방 및 임시퇴원의 취소사실 통보) 심사위원회는 가석방 또는 임시퇴원이 취소된 자의 명단과 결정서등본을 관할보호관찰소의 장과 가석방 또는 임시퇴원이 취소된 자를 수용할 수용기관의 장에게 송부하여야 한다. <개정 2008.6.20>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4191, '제38조(보호처분변경신청서) 영 제35조제1항의 규정에 의한 보호처분의 변경신청은 별지 제28호서식에 의한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4192, '제39조(부정기형종료신청서) 법 제50조제1항의 규정에 의한 부정기형 종료의 신청은 별지 제29호서식에 의한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4193, '제40조(부정기형종료결정 통보) 심사위원회는 법 제50조의 규정에 의하여 부정기형종료결정을 한 때에는 그 결과를 관할보호관찰소의 장에게 통보하여야 한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4194, '제41조(임시해제 신청서) 법 제52조제1항의 규정에 의한 보호관찰의 임시해제 신청은 별지 제30호서식에 의한다. <개정 2009.11.27>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4195, '제41조의2(임시해제 취소 신청서) 법 제52조제3항에 따른 보호관찰의 임시해제 취소 신청서는 별지 제30호의2서식에 따른다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4196, '제42조(임시해제 결정통보) 심사위원회는 법 제52조제1항의 규정에 의하여 임시해제 결정을 한 때에는 그 사실을 관할보호관찰소의 장에게 통보하여야 한다. <개정 2009.11.27>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4197, '제43조(보호관찰의 정지 및 정지해제신청서) 법 제53조제1항의 규정에 의한 보호관찰의 정지결정 및 법 제53조제2항의 규정에 의한 보호관찰정지해제결정의 신청은 별지 제31호서식에 의한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4198, '제44조(보호관찰정지 및 정지해제결정통보) 심사위원회는 법 제53조제1항 또는 동조제2항의 규정에 의하여 보호관찰의 정지 또는 정지해제결정을 한 때에는 그 결과를 관할보호관찰소의 장에게 통보하여야 한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4199, '제45조(보호관찰정지자 명부) 보호관찰소의 장은 법 제53조제1항에 따라 보호관찰을 정지하는 결정을 받은 자에 대하여 별지 제32호서식의 보호관찰정지자명부에 정해진 사항을 기재해야 한다. <개정 2022.2.7>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4200, '제46조(보호관찰사건이송) 보호관찰소의 장은 보호관찰대상자가 다른 보호관찰소의 관할구역안에 거주하고 있는 사실이 확인된 때에는 별지 제33호서식의 보호관찰사건이송서에 관계기록을 첨부하여 신주거지를 관할하는 보호관찰소의 장에게 이송하여야 한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4201, '제46조의2(기부금품의 접수 영수증 등)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4202, '제47조(준용) 제21조(보호관찰사건부등)ㆍ제22조(보호관찰기간의 계산)ㆍ제23조(보호관찰담당자의 지명 및 임무) 및 제46조(보호관찰사건이송)의 규정은 법 제3조제2항의 규정에 의한 사회봉사ㆍ수강명령대상자에 대하여 이를 준용한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4203, '제48조(갱생보호시설의 설치ㆍ운영 기준) 법 제65조제3항 및 제4항에 따른 갱생보호시설의 설치 및 운영 기준은 별표 3과 같다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4204, '제49조(사무실 및 상담실) 갱생보호시설에는 일반사무를 집행하는 사무실과 갱생보호를 받을 사람(이하 "갱생보호대상자"라 한다)과의 상담을 위한 상담실을 설치하여야 한다. 다만, 상담실을 별도로 설치하지 아니하여도 사무실내에서 갱생보호대상자와 상담할 수 있는 경우 및 갱생보호의 성질상 상담이 필요하지 아니한 갱생보호를 실시하는 경우에는 상담실을 설치하지 아니할 수 있다. <개정 2014.11.19>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4205, '제50조(생활관)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4206, '제51조(갱생보호의 신청 및 조치)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4207, '제52조(숙식제공의 대상) 생활관에는 갱생보호대상자가 아닌 자를 숙식하게 할 수 없다. 다만, 갱생보호대상자의 배우자, 직계존ㆍ비속에 대하여는 1주일이내의 기간동안 숙식을 제공할 수 있다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4208, '제53조(갱생자립계획 및 생활지도)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4209, '제54조(거실의 배정) 갱생보호대상자에 대하여 거실을 배정함에 있어서는 갱생보호대상자의 연령ㆍ전과ㆍ성격 등을 고려하여야 한다. <개정 2014.11.19>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4210, '제55조(금품사용에 관한 지도 및 금품보관)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4211, '제56조(건강관리)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4212, '제57조(의복) 갱생보호대상자에게 지급하는 의복은 계절에 적합하고 사회적 체면을 유지할 수 있는 것이어야 한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4213, '제58조(식사) 생활관에서 제공하는 식사는 주간 또는 월간차림표에 의하여 조리하되, 갱생보호대상자의 건강을 유지하기에 충분한 열량과 영양성분이 포함되어 있도록 하여야 한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4214, '제59조(교양 및 여가활동)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4215, '제60조(숙식제공기간의 연장) 사업자 또는 공단은 영 제41조제2항 단서의 규정에 의하여 갱생보호대상자에 대한 숙식제공의 기간을 연장하고자 할 때에는 본인의 신청에 의하되, 자립의 정도, 계속보호의 필요성 기타 사항을 고려하여 이를 결정하여야 한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4216, '제61조 삭제 <2014.11.19>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4217, '제62조 삭제 <2014.11.19>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4218, '제63조 삭제 <2014.11.19>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4219, '제64조 삭제 <2014.11.19>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4220, '제65조(직업훈련)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4221, '제66조(취업 지원 등)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4222, '제67조(임금지급) 사업자 또는 공단은 갱생보호대상자를 부설작업장에 취업하게 한 경우에는 상당한 보수를 지급하여야 한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4223, '제68조(갱생보호사업의 허가) 법 제67조제1항의 규정에 의하여 갱생보호사업의 허가를 받고자 하는 자는 다음 각호의 사항을 기재한 허가신청서에 정관 기타 관계서류를 첨부하여 법무부장관에게 제출하여야 한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4224, '제69조 삭제 <2014.11.19>', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4225, '제70조(허가사항의 변경) 사업자가 제68조제1호부터 제3호까지, 제5호 또는 제6호의 사항을 변경하거나 정관을 변경하려는 경우에는 그 변경 사유를 명시한 변경허가신청서에 변경된 정관 및 관계 서류를 첨부하여 법무부장관의 허가를 받아야 한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4226, '제71조(사업자의 사업계획등)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4227, '제72조(공단의 사업계획등)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4228, '제73조(수익사업 승인신청등) 사업자 또는 공단은 법 제96조제1항의 규정에 의하여 수익사업 경영의 승인 또는 변경승인을 신청하는 경우에는 승인신청서에 다음의 서류를 법무부장관에게 제출하여야 한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4229, '제74조(수익사업의 요건) 사업자 또는 공단은 수익사업의 경영으로 갱생보호사업에 지장을 초래하여서는 아니되며, 그 수익을 갱생보호사업을 위하여 사용하여야 한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4230, '제75조(보고) 사업자 또는 공단은 다음 각호의 사항에 관하여 법무부장관에게 보고하여야 한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4231, '제76조(개선명령)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4232, '제77조(회계)', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4233, '제78조(장부의 비치) 사업자 및 공단은 다음의 장부를 비치하여야 한다.', 541);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4234, '제1조(목적) 이 법은 수사ㆍ재판ㆍ집행 등 형사사법 절차에서 전자장치를 효율적으로 활용하여 불구속재판을 확대하고, 범죄인의 사회복귀를 촉진하며, 범죄로부터 국민을 보호함을 목적으로 한다.', 542);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4235, '제2조(정의) 이 법에서 사용하는 용어의 정의는 다음과 같다. <개정 2007.8.3, 2009.5.8, 2009.6.9, 2010.4.15, 2012.12.18, 2013.4.5, 2017.10.31, 2023.7.11>', 542);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4236, '제3조(국가의 책무) 국가는 이 법의 집행과정에서 국민의 인권이 부당하게 침해되지 아니하도록 주의하여야 한다.', 542);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4237, '제3조의2(연구개발사업의 추진)', 542);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4238, '제4조(적용 범위) 만 19세 미만의 자에 대하여 부착명령을 선고한 때에는 19세에 이르기까지 이 법에 따른 전자장치를 부착할 수 없다. <개정 2009.5.8>', 542);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4239, '제5조(전자장치 부착명령의 청구)', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4240, '제6조(조사)', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4241, '제7조(부착명령 청구사건의 관할)', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4242, '제8조(부착명령 청구서의 기재사항 등)', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4243, '제9조(부착명령의 판결 등)', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4244, '제9조의2(준수사항)', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4245, '제10조(부착명령 판결 등에 따른 조치)', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4246, '제11조(국선변호인 등) 부착명령 청구사건에 관하여는 「형사소송법」 제282조 및 제283조를 준용한다. <개정 2010.4.15>', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4247, '제12조(집행지휘)', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4248, '제13조(부착명령의 집행)', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4249, '제14조(피부착자의 의무)', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4250, '제14조의2(부착기간의 연장 등)', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4251, '제14조의3(피부착명령자에 대한 준수사항의 부과 등) 피부착명령자의 재범의 위험성에 관하여 행형(行刑) 성적 등 자료에 의해 판결 선고 당시에 예상하지 못한 새로운 사정이 소명되는 등 특별한 사정이 있는 경우 법원은 보호관찰소의 장의 신청에 따른 검사의 청구로 제9조의2제1항의 준수사항을 부과, 추가, 변경 또는 삭제하는 결정을 할 수 있다.', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4252, '제15조(보호관찰관의 임무)', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4253, '제16조(수신자료의 보존ㆍ사용ㆍ폐기 등)', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4254, '제16조의2(피부착자의 신상정보 제공 등)', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4255, '제16조의3(위치추적 관제센터의 설치ㆍ운영 등)', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4256, '제17조(부착명령의 임시해제 신청 등)', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4257, '제18조(부착명령 임시해제의 심사 및 결정)', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4258, '제19조(임시해제의 취소 등)', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4259, '제20조(부착명령 집행의 종료) 제9조에 따라 선고된 부착명령은 다음 각 호의 어느 하나에 해당하는 때에 그 집행이 종료된다. <개정 2020.2.4>', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4260, '제21조(부착명령의 시효)', 543);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4261, '제21조의2(보호관찰명령의 청구) 검사는 다음 각 호의 어느 하나에 해당하는 사람에 대하여 형의 집행이 종료된 때부터 「보호관찰 등에 관한 법률」에 따른 보호관찰을 받도록 하는 명령(이하 "보호관찰명령"이라 한다)을 법원에 청구할 수 있다. <개정 2023.7.11>', 544);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4262, '제21조의3(보호관찰명령의 판결)', 544);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4263, '제21조의4(준수사항)', 544);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4264, '제21조의5(보호관찰명령의 집행) 보호관찰명령은 특정범죄사건에 대한  형의 집행이 종료되거나 면제ㆍ가석방되는 날 또는 치료감호 집행이 종료ㆍ가종료되는 날부터 집행한다. 다만, 보호관찰명령의 원인이 된 특정범죄사건이 아닌 다른 범죄사건으로 형이나 치료감호의 집행이 계속될 경우에는 보호관찰명령의 원인이 된 특정범죄사건이 아닌 다른 범죄사건에 대한 형의 집행이 종료되거나 면제ㆍ가석방되는 날 또는 치료감호의 집행이 종료ㆍ가종료되는 날부터 집행한다.', 544);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4265, '제21조의6(보호관찰대상자의 의무)', 544);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4266, '제21조의7(보호관찰 기간의 연장 등)', 544);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4267, '제21조의8(준용규정) 보호관찰대상자에 대해서는 제5조제6항ㆍ제8항, 제6조부터 제8조까지, 제9조제2항부터 제9항까지, 제9조의2, 제10조부터 제12조까지, 제13조제5항부터 제9항까지, 제15조 및 제17조부터 제21조까지의 규정을 준용하되, "부착명령"은 "보호관찰명령"으로, "부착기간"은 "보호관찰 기간"으로, "피부착명령청구자"는 "피보호관찰명령청구자"로, "피부착자"는 "보호관찰대상자"로, "전자장치 부착"은 "보호관찰"로 본다. <개정 2017.10.31, 2017.12.12, 2023.7.11>', 544);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4268, '제22조(가석방과 전자장치 부착)', 545);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4269, '제23조(가종료 등과 전자장치 부착)', 545);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4270, '제24조(전자장치의 부착)', 545);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4271, '제25조(부착집행의 종료) 제22조 및 제23조에 따른 전자장치 부착은 다음 각 호의 어느 하나에 해당하는 때에 그 집행이 종료된다. <개정 2010.4.15>', 545);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4272, '제26조(수신자료의 활용) 보호관찰관은 수신자료를 준수사항 이행여부 확인 등 「보호관찰 등에 관한 법률」에 따른 보호관찰대상자의 지도ㆍ감독 및 원호에 활용할 수 있다.', 545);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4273, '제27조(준용) 이 장에 따른 전자장치 부착에 관하여는 제13조제4항ㆍ제6항제1호ㆍ제8항제1호ㆍ제9항, 제14조, 제15조, 제16조, 제16조의2, 제16조의3 및 제17조부터 제19조까지의 규정을 준용한다. <개정 2010.4.15, 2017.10.31, 2017.12.12, 2022.1.4>', 545);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4274, '제28조(형의 집행유예와 부착명령)', 546);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4275, '제29조(부착명령의 집행)', 546);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4276, '제30조(부착명령 집행의 종료) 제28조의 부착명령은 다음 각 호의 어느 하나에 해당하는 때에 그 집행이 종료된다.', 546);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4277, '제31조(준용) 이 장에 따른 부착명령에 관하여는 제6조, 제9조제5항부터 제7항까지, 제10조제1항, 제12조, 제13조제4항ㆍ제6항제1호ㆍ제8항제1호ㆍ제9항, 제14조, 제15조제1항, 제16조, 제16조의2, 제16조의3, 제17조부터 제19조까지 및 제26조를 준용한다. <개정 2010.4.15, 2017.10.31, 2017.12.12, 2022.1.4>', 546);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4278, '제31조의2(보석과 전자장치 부착)', 547);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4279, '제31조의3(전자장치 부착의 집행)', 547);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4280, '제31조의4(보석조건 이행 상황 등 통지)', 547);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4281, '제31조의5(전자장치 부착의 종료) 제31조의2제1항에 따른 전자장치의 부착은 다음 각 호의 어느 하나에 해당하는 경우에 그 집행이 종료된다.', 547);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4282, '제31조의6(전자장치 부착의 집행)', 548);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4283, '제31조의7(전자장치 부착의 종료) 제31조의6에 따른 전자장치 부착은 다음 각 호의 어느 하나에 해당하는 때에 그 집행이 종료된다.', 548);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4284, '제31조의8(스토킹행위자 수신자료의 보존ㆍ사용ㆍ폐기 등)', 548);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4285, '제32조(전자장치 부착기간의 계산)', 549);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4286, '제32조의2(부착명령 등 집행전담 보호관찰관의 지정) 보호관찰소의 장은 소속 보호관찰관 중에서 다음 각 호의 사항을 전담하는 보호관찰관을 지정하여야 한다. 다만, 보호관찰소의 장은 19세 미만의 사람에 대해서 성폭력범죄를 저지른 피부착자 중 재범의 위험성이 현저히 높은 사람에 대해서는 일정기간 그 피부착자 1명만을 전담하는 보호관찰관을 지정하여야 한다. <개정 2012.12.18, 2019.4.16>', 549);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4287, '제33조(전자장치 부착 임시해제의 의제) 보호관찰이 임시해제된 경우에는 전자장치 부착이 임시해제된 것으로 본다. <개정 2020.2.4>', 549);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4288, '제33조의2(범죄경력자료 등의 조회 요청)', 549);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4289, '제34조(군법 피적용자에 대한 특칙) 이 법을 적용함에 있어서 「군사법원법」 제2조제1항 각 호의 어느 하나에 해당하는 자에 대하여는 군사법원은 법원의, 군검사는 검사의, 군사법경찰관리는 사법경찰관리의, 군교도소장은 교도소장의 이 법에 따른 직무를 각각 행한다. <개정 2016.1.6>', 549);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4290, '제35조(다른 법률의 준용) 이 법을 적용함에 있어서 이 법에 규정이 있는 경우를 제외하고는 그 성질에 반하지 아니하는 범위 안에서 「형사소송법」 및 「보호관찰 등에 관한 법률」의 규정을 준용한다.', 549);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4291, '제36조(벌칙)', 550);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4292, '제37조(벌칙)', 550);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4293, '제38조(벌칙)', 550);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4294, '제39조(벌칙)', 550);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4295, '제1조(목적) 이 영은 「전자장치 부착 등에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다. <개정 2009.7.30, 2013.5.31, 2020.8.5>', 551);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4296, '제2조(위치추적 전자장치의 구성) 「전자장치 부착 등에 관한 법률」(이하 "법"이라 한다) 제2조제4호에 따른 위치추적 전자장치(이하 "전자장치"라 한다)는 다음 각 호로 구성한다. <개정 2009.7.30, 2013.5.31, 2018.2.13, 2020.8.5>', 551);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4297, '제3조 삭제 <2021.9.14>', 551);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4298, '제3조의2(출연금 등의 지급ㆍ사용 및 관리)', 551);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4299, '제4조(조사)', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4300, '제5조(부착명령 청구서의 기재사항 및 방식)', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4301, '제6조(집행지휘) 검사는 부착명령의 판결이 확정되면 지체 없이 부착명령을 선고받은 사람(이하 "피부착명령자"라 한다)의 주거지를 관할하는 보호관찰소의 장에게 법 제12조제2항의 부착명령 집행을 지휘한 서면을 보내야 한다.', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4302, '제7조(부착명령의 집행)', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4303, '제8조(부착명령의 집행정지)', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4304, '제9조(부착명령 집행정지자의 이송) 수용기관의 장은 법 제13조제6항에 따라 부착명령의 집행이 정지된 사람을 다른 수용기관으로 이송할 경우에는 그의 주거지를 관할하는 보호관찰소의 장과 해당 수용기관의 장에게 그 사실을 통보하여야 한다. <개정 2010.7.12, 2018.6.12>', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4305, '제10조(전자장치의 일시 분리)', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4306, '제11조(전자장치의 효용 유지 의무) 피부착자는 전자장치의 부착기간 중 법 제14조제1항에 따라 전자장치의 효용 유지를 위하여 다음 각 호의 사항을 준수하여야 한다.', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4307, '제12조(주거이전ㆍ국내여행 및 출국 허가 등)', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4308, '제12조의2(부착기간의 연장 등의 신청)', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4309, '제13조(상담치료 등의 집행)', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4310, '제14조(수신자료의 사용) 보호관찰소의 장 및 법 제16조의3에 따른 위치추적 관제센터(이하 "위치추적 관제센터"라 한다)의 장은 법 제16조제2항제1호, 제3호 및 제4호에 따라 수신자료가 사용된 경우에는 그 사실을 대장에 적고 이를 비치해야 한다. <개정 2010.7.12, 2018.6.12, 2021.9.14, 2024.1.9>', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4311, '제14조의2(수신자료 열람 또는 조회)', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4312, '제14조의3(긴급 수신자료 열람 또는 조회)', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4313, '제14조의4(열람 또는 조회한 수신자료의 보존ㆍ폐기 등)', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4314, '제14조의5(수신자료 사용사건의 결과 통지 등)', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4315, '제14조의6(수신자료 관련 비밀누설 금지 등) 수신자료를 열람 또는 조회한 사람은 그로 인하여 알게 된 타인의 비밀을 누설하거나 피부착자의 명예를 훼손하지 아니하도록 하여야 한다.', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4316, '제15조(수신자료의 폐기)', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4317, '제15조의2(피부착자의 신상정보 제공 등)', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4318, '제16조(부착명령의 임시해제 신청)', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4319, '제17조(부착명령 임시해제의 심사 및 결정)', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4320, '제18조(임시해제의 취소 등)', 552);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4321, '제18조의2(보호관찰 기간의 연장 등)', 553);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4322, '제18조의3(준용규정) 보호관찰대상자의 조사, 집행지휘, 주거이전 허가, 상담치료, 임시해제 및 취소 등에 관하여는 제4조부터 제6조까지, 제12조제1항부터 제7항까지, 제13조, 제16조, 제17조제1항ㆍ제2항ㆍ제4항 및 제18조제1항ㆍ제2항을 준용한다. 이 경우 "부착명령"은 "보호관찰명령"으로, "부착기간"은 "보호관찰 기간"으로, "피부착명령청구자"는 "피보호관찰명령청구자"로, "피부착명령자"는 "피보호관찰명령자"로, "피부착자"는 "보호관찰대상자"로, "전자장치 부착"은 "보호관찰"로 본다. <개정 2020.8.5>', 553);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4323, '제19조(전자장치 부착 적합성조사)', 554);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4324, '제19조의2(결정의 고지 등)', 554);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4325, '제20조(치료감호시설의 장 등의 통보)', 554);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4326, '제21조(준용) 이 장에 따른 전자장치 부착에 관하여는 제7조부터 제12조까지, 제12조의2 및 제13조부터 제18조까지의 규정을 준용한다. <개정 2010.7.12>', 554);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4327, '제22조(집행유예와 부착명령의 집행) 법 제28조제1항에 따라 집행유예와 함께 전자장치 부착을 명하는 법원의 판결이 확정된 사람은 판결 확정 후 10일 이내에 보호관찰소에 출석하여 법 제29조제1항에 따른 부착명령의 집행에 따라야 한다.', 555);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4328, '제23조(준용) 이 장에 따른 부착명령에 관하여는 제4조, 제6조부터 제12조까지, 제12조의2 및 제13조부터 제18조까지의 규정을 준용한다. <개정 2010.7.12>', 555);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4329, '제23조의2(보석조건 전자장치 부착 결정 전 조사)', 556);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4330, '제23조의3(보석허가 결정문의 송부 등) 법원은 긴급한 필요가 있는 경우 법 제31조의3제1항에 따라 보호관찰소의 장에게 결정문의 등본을 송부하기 전에 팩스ㆍ전자우편 등의 방법으로 그 사본을 먼저 송부할 수 있다.', 556);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4331, '제23조의4(전자장치 부착 보석 피고인의 신고) 법 제31조의2제1항에 따라 보석조건으로 전자장치 부착명령을 받고 석방된 피고인(이하 "전자장치 보석피고인"이라 한다)은 법 제31조의3제2항에 따라 주거지를 관할하는 보호관찰소에 출석하여 신고하는 경우 법무부령으로 정하는 신고서를 제출해야 한다.', 556);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4332, '제23조의5(전자장치 부착 등)', 556);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4333, '제23조의6(보석조건 이행 상황 통지)', 556);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4334, '제23조의7(보석조건 위반 통지)', 556);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4335, '제23조의8(보석조건 변경 및 보석취소 통지) 법원은 「형사소송법」 제102조제1항 또는 제2항에 따라 보석조건을 변경하거나 취소한 경우 보호관찰소의 장에게 보석조건 변경이나 보석취소 결정문의 등본을 송부해야 한다. 이 경우 긴급한 경우에는 전화ㆍ팩스ㆍ전자우편 등의 방법으로 먼저 통지할 수 있다.', 556);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4336, '제23조의9(준용 규정) 이 장에 따른 전자장치 부착 등에 관하여는 제10조, 제14조의6 및 제15조를 준용한다. 이 경우 "피부착자"는 "전자장치 보석피고인"으로 본다.', 556);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4337, '제23조의10(잠정조치 결정문의 송부) 법원은 긴급한 필요가 있는 경우 법 제31조의6제1항에 따라 다음 각 호의 사람에게 결정문의 등본을 송부하기 전에 팩스ㆍ전자우편 등의 방법으로 그 사본을 먼저 송부할 수 있다.', 557);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4338, '제23조의11(전자장치 스토킹행위자의 신고)', 557);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4339, '제23조의12(전자장치의 부착 등)', 557);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4340, '제23조의13(전자장치 부착 사실의 통지 등)', 557);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4341, '제23조의14(피해자의 보호)', 557);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4342, '제23조의15(잠정조치의 연장ㆍ변경ㆍ취소 통지) 법원은 잠정조치의 연장ㆍ변경ㆍ취소 결정을 한 경우 법 제31조의6제7항에 따라 관할경찰관서의 장과 보호관찰소의 장에게 그 결정문의 등본을 지체 없이 송부해야 한다. 이 경우 긴급한 경우에는 전화ㆍ팩스ㆍ전자우편 등의 방법으로 먼저 통지할 수 있다.', 557);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4343, '제23조의16(불기소처분의 통지) 검사는 전자장치 스토킹행위자에 대해 불기소처분을 하여 「스토킹범죄의 처벌 등에 관한 법률」 제11조제5항에 따라 잠정조치 결정이 효력을 상실한 때에는 보호관찰소의 장에게 이를 지체 없이 통지해야 한다.', 557);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4344, '제23조의17(스토킹행위자 수신자료의 사용) 보호관찰소의 장 및 위치추적 관제센터의 장은 법 제31조의8제2항제1호, 제3호 및 제4호에 따라 스토킹행위자 수신자료가 사용된 경우에는 그 사실을 대장에 적고 이를 비치해야 한다.', 557);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4345, '제23조의18(스토킹행위자 수신자료의 폐기) 보호관찰소의 장 및 위치추적 관제센터의 장은 법 제31조의8제4항제1호 및 제2호에 따른 스토킹행위자 수신자료의 폐기를 위해 「형사사법절차 전자화 촉진법」 제2조제2호에 따른 형사사법업무 처리기관에 다음 각 호의 사항을 알아보거나 관련 자료의 열람 등 협조를 요청할 수 있다.', 557);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4346, '제23조의19(준용규정) 이 장에 따른 전자장치 부착 등에 관하여는 제7조제3항, 제10조, 제14조의2부터 제14조의6까지 및 제15조제2항을 준용한다. 이 경우 "피부착명령자" 및 "피부착자"는 각각 "전자장치 스토킹행위자"로, "수신자료"는 "스토킹행위자 수신자료"로 본다.', 557);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4347, '제24조(출소자 등의 인적사항 등 통보)', 558);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4348, '제25조(조사) 검사는 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제2호 및 제3항제2호에 따라 보호관찰소의 장에게 출소자등에 대한 법 제6조에 따른 조사를 요청할 때에는 수용시설의 장으로부터 통보받은 제24조제1항 각 호의 사항과 출소자등에 대한 범죄경력조회서, 연락처, 면담결과서 등을 통보하여야 한다.', 558);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4349, '제26조(부착명령 청구 사실의 통보) 검사는 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제4호 및 제3항제4호에 따라 출소자등에 대하여 부착명령을 청구한 경우에는 피청구인에게 지체 없이 서면으로 청구 사실을 통보하여야 한다.', 558);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4350, '제27조(부착명령 결정의 통지)', 558);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4351, '제28조(집행지휘)', 558);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4352, '제29조(민감정보 및 고유식별정보의 처리)', 558);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4353, '제1조(목적) 이 규칙은 「전자장치 부착 등에 관한 법률」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다. <개정 2009.7.30, 2013.5.31, 2020.8.5>', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4354, '제2조 삭제 <2010.7.15>', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4355, '제3조(조사의 요청)', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4356, '제4조(부착명령청구의 방식)', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4357, '제5조(교도소장 등의 석방예정 통보) 법 제10조제2항, 제22조제5항, 제23조제3항, 영 제7조제5항, 제8조제5항, 제20조제2항 및 제27조제3항의 통보는 별지 제4호서식의 석방예정통보서에 따른다. 다만, 영 제7조제5항의 경우로서 전자장치가 부착된 사람(이하 "피부착자"라 한다)이 벌금 완납으로 석방되는 등의 긴급한 사유로 별지 제4호서식에 따른 통보가 곤란한 경우에는 유선으로 통보할 수 있다. <개정 2010.7.15, 2013.5.31, 2015.9.7, 2020.8.5>', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4358, '제6조(집행지휘)', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4359, '제7조(구금 통보 등) 영 제8조제2항, 제4항 및 제5항(영 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 통보는 각각 별지 제6호서식의 구금(구금해제 결정)통보서에 따른다. <개정 2013.5.31>', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4360, '제8조(부착명령 집행정지자의 이송 통보 등) 영 제9조(영 제21조 및 제23조에 따라 준용되는 경우를 포함한다) 및 제20조제1항의 통보는 별지 제7호서식의 부착명령 집행정지자(피부착결정자) 이송통보서에 따른다.', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4361, '제9조(일시분리 대장) 영 제10조제2항(영 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 일시분리 대장은 별지 제8호서식에 따른다.', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4362, '제10조(주거이전, 국내여행 및 출국 허가서 등)', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4363, '제10조의2(부착기간의 연장 등의 신청 등)', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4364, '제10조의3(치료기관 등의 지정)', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4365, '제10조의4(수용 중 생활실태자료 확보 등)', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4366, '제11조(수신자료 사용대장) 영 제14조(영 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 수신자료 사용대장은 별지 제22호서식에 따른다. <개정 2013.5.31>', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4367, '제11조의2(수신자료 열람 또는 조회)', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4368, '제11조의3(긴급 수신자료 열람 또는 조회)', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4369, '제11조의4(열람 또는 조회한 수신자료의 보존ㆍ폐기 등)', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4370, '제11조의5(수신자료 사용사건의 결과 통지) 영 제14조의5제1항에 따른 검사 또는 사법경찰관의 서면 통지는 별지 제34호서식에 따른다.', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4371, '제11조의6(보호관찰소의 장의 수사기관 통보 등) 영 제15조의2제2항에 따른 보호관찰소의 장의 수사기관에 대한 통보는 별지 제35호서식에 따른다.', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4372, '제11조의7(영상정보 열람사실의 통지)', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4373, '제12조(임시해제 신청서 등) 영 제16조제1항의 임시해제 신청(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다) 및 영 제18조제1항의 임시해제 취소 신청(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)은 각각 별지 제36호서식의 부착명령 임시해제(임시해제 취소) 신청서에 따른다. <개정 2013.5.31, 2020.8.5>', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4374, '제12조의2(임시해제의 심사ㆍ결정기준) 「보호관찰 등에 관한 법률」 제5조에 따른 보호관찰 심사위원회가 법 제18조제1항ㆍ제4항ㆍ제5항(법 제21조의8, 제27조 및 제31조에 따라 준용되는 경우를 포함한다) 및 영 제17조제1항(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)에 따라 임시해제를 심사ㆍ결정할 때에는 피부착자 또는 보호관찰대상자의 연령, 건강상태, 가족관계, 가정환경, 범죄경력, 집행기간, 준수사항의 이행정도, 재범위험성 평가결과 및 그 밖에 필요한 사항을 고려해야 한다. <개정 2020.8.5>', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4375, '제13조(결정서) 법 제18조제4항ㆍ제5항(법 제21조의8, 제27조 및 제31조에 따라 준용되는 경우를 포함한다) 및 영 제17조(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)에 따른 임시해제 결정과 법 제19조제1항(법 제21조의8, 제27조 및 제31조에 따라 준용되는 경우를 포함한다) 및 영 제18조제2항(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)에 따른 임시해제 취소 결정은 각각 별지 제37호서식의 부착명령(보호관찰명령) 임시해제(임시해제 취소) 결정서에 따른다. <개정 2020.8.5>', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4376, '제13조의2(보호관찰명령 청구의 방식)', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4377, '제13조의3(집행지휘)', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4378, '제13조의4(보호관찰기간의 연장 등 신청) 법 제21조의7에 따른 보호관찰소의 장의 보호관찰기간의 연장 또는 준수사항의 추가ㆍ변경ㆍ삭제의 신청은 별지 제41호서식에 따르고, 법 제21조의7에 따른 검사의 보호관찰기간의 연장 또는 준수사항의 추가ㆍ변경ㆍ삭제의 청구는 별지 제42호서식에 따른다.', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4379, '제13조의5(수용 중 생활실태 자료 확보 등) 법 제21조의8에 따라 준용되는 법 제15조제3항에 따른 보호관찰명령 집행을 위한 수용 중 생활실태 자료 확보 등에 관하여는 제10조의4를 준용한다.', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4380, '제14조(전자장치 부착대상자 통보 등)', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4381, '제14조의2(조사의 의뢰) 법 제31조의2제2항 및 영 제23조의2제1항에 따른 조사의 의뢰는 별지 제44호의2서식에 따른다.', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4382, '제14조의3(보석 피고인 신고서) 법 제31조의3제2항 및 영 제23조의4에 따른 신고서는 별지 제44호의3서식에 따른다.', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4383, '제14조의4(보석조건 이행 상황 통지) 법 제31조의4제1항 및 영 제23조의6에 따른 보석조건 이행 상황의 통지는 별지 제44호의4서식에 따른다.', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4384, '제14조의5(보석조건 위반 통지) 법 제31조의4제2항 및 영 제23조의7에 따른 보석조건 위반 통지는 별지 제44호의5서식에 따른다.', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4385, '제14조의6(스토킹행위자 신고서) 법 제31조의6제2항 및 영 제23조의11제1항에 따른 신고는 별지 제44호의6서식에 따른다.', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4386, '제14조의7(전자장치 부착 사실의 통지) 법 제31조의6제3항 각 호 외의 부분 및 영 제23조의13제1항에 따른 전자장치 부착 사실의 통지는 별지 제44호의7서식에 따른다.', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4387, '제14조의8(피해자 관련 사항의 통지) 법 제31조의6제3항 및 영 제23조의13제2항에 따른 피해자 관련 사항의 통지는 별지 제44호의8서식에 따른다.', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4388, '제14조의9(잠정조치 결정의 효력 상실 통지) 법 제31조의6제6항 또는 영 제23조의16에 따른 잠정조치 결정의 효력 상실 통지는 별지 제44호의9서식에 따른다.', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4389, '제14조의10(스토킹행위자 수신자료 사용대장) 영 제23조의17에 따른 스토킹행위자 수신자료 사용대장은 별지 제44호의10서식에 따른다.', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4390, '제15조(출소자등 통보서) 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제1호, 제3항제1호 및 영 제24조에 따른 출소자 등의 인적사항 등 통보는 별지 제45호서식의 출소자등 통보서에 따른다. <개정 2013.5.31>', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4391, '제16조(출석요구서) 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제5호에 따른 출석 요구는 별지 제46호서식의 출석요구서에 따른다. <개정 2013.5.31>', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4392, '제17조(구인영장 청구서 등)', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4393, '제18조(구인영장)', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4394, '제19조(부착명령 집행장)', 559);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4395, '제1조(취지) 「공무원범죄에 관한 몰수특례법」(이하 "법"이라 한다)에 의한 몰수보전 및 추징보전의 절차등에 관하여는 법의 규정에 의하는 외에 이 규칙이 정하는 바에 의한다. <개정 2005.12.29>', 560);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4396, '제2조(몰수보전 청구의 방식) 몰수보전의 청구는 서면으로 하여야 한다.', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4397, '제3조(몰수보전 청구서의 기재사항)', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4398, '제4조(부대보전 청구의 방식) 부대보전(부대보전명령에 의한 처분의 금지를 말한다. 이하 같다)의 청구는 서면으로 하여야 한다.', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4399, '제5조(부대보전청구서의 기재사항)', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4400, '제6조(몰수보전명령의 기재사항) 몰수보전명령 및 부대보전명령을 발하는 경우 그 재판서에는 법 제23조제3항이 규정하는 사항외에 피고인 또는 피의자의 주민등록번호와 주거, 처분을 금지하는 재산 또는 권리를 가진 자(명의인이 다른 경우 명의인을 포함한다)의 주소를 기재하여야 한다.', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4401, '제7조(긴급을 요하는 경우의 기재사항) 법 제23조제4항의 규정에 의하여 몰수보전명령 또는 부대보전명령을 발하는 경우에는 재판서에 그 취지를 기재하여야 한다.', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4402, '제8조(몰수보전명령이 발하여진 경우의 공소장의 기재사항) 공소가 제기되기 전에 몰수보전명령이 발하여진 경우, 검사는 공소장에 몰수보전명령이 발하여졌다는 취지의 기재를 하여야 한다.', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4403, '제9조(몰수보전이 된 금전채권의 채무자가 공탁을 한 경우) 금전의 지급을 목적으로 하는 채권(이하 "금전채권"이라고 한다)에 대하여 몰수보전이 되어 그 채무자가 공탁을 한 경우 그 공탁을 수리한 공탁관은 몰수보전명령을 발한 법원 및 이에 대응하는 검찰청의 검사(이하 "검사"라고 한다) 또는 고위공직자범죄수사처에 소속된 검사(이하 "수사처검사"라고 한다)에게 공탁사실을 통지하여야 한다. <개정 2007.3.29, 2021.1.29>', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4404, '제10조(예탁유가증권의 몰수보전) 「자본시장과 금융투자업에 관한 법률」 제309조제2항에 따라 한국예탁결제원에 예탁된 유가증권(같은 법률 제310조제4항에 따라 한국예탁결제원에 예탁된 것으로 보는 경우를 포함한다. 이하 이 조에서 "예탁유가증권"이라 한다)에 대한 몰수보전은, 예탁유가증권에 대한 공유지분을 가지는 자(명의인이 다른 경우 명의인을 포함한다)에게는 계좌간 대체청구ㆍ증권반환청구, 그 밖의 처분을 금지하고, 한국예탁결제원에게는 예탁자에 대한 계좌간 대체와 증권의 반환을 금지하는 취지의 몰수보전명령에 의하여 한다. <개정 2005.12.29, 2019.11.29>', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4405, '제10조의2(전자등록주식등의 몰수보전) 「주식ㆍ사채 등의 전자등록에 관한 법률」 제2조제4호에 따른 전자등록주식등(이하 이 조에서 "전자등록주식등"이라 한다)에 대한 몰수보전은, 전자등록주식등의 권리자(명의인이 다른 경우 명의인을 포함한다)에게는 같은 법 제30조에 따른 계좌간 대체의 전자등록신청, 같은 법 제33조에 따른 변경ㆍ말소의 전자등록신청이나 추심, 그 밖의 처분을 금지하고, 같은 법 제2조제6호에 따른 전자등록기관 또는 같은 법 제2조제7호에 따른 계좌관리기관에게는 같은 법에 따른 계좌간 대체와 변경ㆍ말소를 금지하는 취지의 몰수보전명령에 의하여 한다.', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4406, '제11조(몰수보전명령의 취소청구의 방식)', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4407, '제12조(검사 또는 수사처검사의 의견서등의 제출) 검사 또는 수사처검사는 법원으로부터 몰수보전명령의 취소에 관한 의견요청이 있을 때에는 3일이내에 의견서를 법원에 제출하여야 하고, 아직 수사기록과 증거물을 법원에 증거로 제출하지 않은 경우에는 수사기록과 증거물도 함께 법원에 제출하여야 한다. <개정 2021.1.29>', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4408, '제13조(몰수보전재산에 대하여 강제집행에 의하여 압류등이 된 경우의 통지)', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4409, '제14조(몰수보전된 금전채권에 대하여 강제집행에 의하여 압류가 된 경우 공탁사유신고의 방식등)', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4410, '제14조의2(몰수보전된 금전채권에 대하여 체납처분에 의하여 압류가 된 경우의 공탁사유신고의 방식등)', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4411, '제15조(강제집행에 의하여 압류가 된 금전채권에 대하여 몰수보전이 된 경우 공탁사유신고의 방식등)', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4412, '제15조의2(체납처분에 의하여 압류가 된 금전채권에 대하여 몰수보전된 경우의 공탁사유신고의 방식등)', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4413, '제16조(강제집행에 의하여 압류등이 된 재산에 대하여 몰수보전이 된 경우의 통지)', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4414, '제17조(강제집행의 정지 및 그 결정의 취소청구방식)', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4415, '제18조(몰수보전과 담보권 실행 등을 위한 경매개시결정에 의한 압류가 경합하는 경우의 통지) 제13조제1항, 제3항 및 제16조제3항의 규정은 몰수보전이 된 재산에 대하여 담보권 실행 등을 위한 경매개시결정에 의하여 압류가 된 경우에, 제16조의 규정은 담보권 실행 등을 위한 경매개시결정에 의하여 압류가 된 재산에 대하여 몰수보전명령이 발하여진 경우에 각 준용한다. 이 경우 그 담보권에 대하여 부대보전이 된 때에는 제13조제3항 및 제16조제2항중 "몰수보전"은 "몰수보전 또는 부대보전"으로 본다. <개정 2005.12.29>', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4416, '제19조(몰수보전과 가압류의 집행이 경합하는 경우의 통지등)', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4417, '제20조(부대보전절차에의 준용) 부대보전의 절차에 관하여는 이 규칙에 특별한 규정이 있는 경우를 제외하고는 몰수보전의 절차에 관한 규정을 준용한다.', 561);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4418, '제21조(추징보전 청구의 방식) 추징보전의 청구는 서면으로 하여야 한다.', 562);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4419, '제22조(추징보전 청구서의 기재사항)', 562);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4420, '제23조(추징보전집행이 된 금전채권의 채무자의 공탁방법등) 추징보전집행된 금전채권의 채무자가 법 제45조에 의한 공탁을 한 경우 그 공탁을 수리한 공탁관은 추징보전명령을 발한 법원 및 검사 또는 수사처검사에게 공탁사실을 통지하여야 한다. <개정 2007.3.29, 2021.1.29>', 562);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4421, '제24조(추징보전해방금의 공탁 및 환부) 추징보전명령이 실효되거나 취소된 때에는 추징보전명령을 발한 법원은 공탁된 추징보전해방금을 환부하여야 한다.', 562);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4422, '제25조(추징보전명령등에의 준용) 제6조, 제7조, 제8조, 제11조, 제12조의 규정은 추징보전명령 또는 추징보전에 관하여 준용한다. 이 경우 제6조중 "법 제23조제3항"은 "법 제42조제4항"으로, 제11조중 "법 제32조제1항"은 "법 제47조"로 각 본다.', 562);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4423, '제26조(「형사소송규칙」의 준용) 몰수보전 및 추징보전의 절차와 제3자 참가절차등의 특례에 관하여는 법 및 이 규칙에 특별한 규정이 있는 경우를 제외하고는 「형사소송규칙」의 규정을 준용한다. 이 경우 법 제14조의 규정에 의하여 형사사건절차에의 참가를 허가받은 자에 관하여는 피고인에 관한 규정을, 법 제20조의 규정에 의하여 선임된 대리인에 관하여는 변호인에 관한 규정을 준용한다. <개정 2005.12.29>', 563);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4424, '제1조(목적) 이 법은 법률상 의무의 효율적인 이행을 확보하고 국민의 권리와 이익을 보호하기 위하여 질서위반행위의 성립요건과 과태료의 부과ㆍ징수 및 재판 등에 관한 사항을 규정하는 것을 목적으로 한다.', 564);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4425, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다.', 564);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4426, '제3조(법 적용의 시간적 범위)', 564);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4427, '제4조(법 적용의 장소적 범위)', 564);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4428, '제5조(다른 법률과의 관계) 과태료의 부과ㆍ징수, 재판 및 집행 등의 절차에 관한 다른 법률의 규정 중 이 법의 규정에 저촉되는 것은 이 법으로 정하는 바에 따른다.', 564);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4429, '제6조(질서위반행위 법정주의) 법률에 따르지 아니하고는 어떤 행위도 질서위반행위로 과태료를 부과하지 아니한다.', 565);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4430, '제7조(고의 또는 과실) 고의 또는 과실이 없는 질서위반행위는 과태료를 부과하지 아니한다.', 565);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4431, '제8조(위법성의 착오) 자신의 행위가 위법하지 아니한 것으로 오인하고 행한 질서위반행위는 그 오인에 정당한 이유가 있는 때에 한하여 과태료를 부과하지 아니한다.', 565);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4432, '제9조(책임연령) 14세가 되지 아니한 자의 질서위반행위는 과태료를 부과하지 아니한다. 다만, 다른 법률에 특별한 규정이 있는 경우에는 그러하지 아니하다.', 565);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4433, '제10조(심신장애)', 565);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4434, '제11조(법인의 처리 등)', 565);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4435, '제12조(다수인의 질서위반행위 가담)', 565);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4436, '제13조(수개의 질서위반행위의 처리)', 565);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4437, '제14조(과태료의 산정) 행정청 및 법원은 과태료를 정함에 있어서 다음 각 호의 사항을 고려하여야 한다.', 565);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4438, '제15조(과태료의 시효)', 565);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4439, '제16조(사전통지 및 의견 제출 등)', 566);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4440, '제17조(과태료의 부과)', 566);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4441, '제17조의2(신용카드 등에 의한 과태료의 납부)', 566);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4442, '제18조(자진납부자에 대한 과태료 감경)', 566);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4443, '제19조(과태료 부과의 제척기간)', 566);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4444, '제20조(이의제기)', 566);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4445, '제21조(법원에의 통보)', 566);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4446, '제22조(질서위반행위의 조사)', 566);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4447, '제23조(자료제공의 요청) 행정청은 과태료의 부과ㆍ징수를 위하여 필요한 때에는 관계 행정기관, 지방자치단체, 그 밖에 대통령령으로 정하는 공공기관(이하 "공공기관등"이라 한다)의 장에게 그 필요성을 소명하여 자료 또는 정보의 제공을 요청할 수 있으며, 그 요청을 받은 공공기관등의 장은 특별한 사정이 없는 한 이에 응하여야 한다.', 566);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4448, '제24조(가산금 징수 및 체납처분 등)', 566);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4449, '제24조의2(상속재산 등에 대한 집행)', 566);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4450, '제24조의3(과태료의 징수유예 등)', 566);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4451, '제24조의4(결손처분)', 566);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4452, '제25조(관할 법원) 과태료 사건은 다른 법령에 특별한 규정이 있는 경우를 제외하고는 당사자의 주소지의 지방법원 또는 그 지원의 관할로 한다.', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4453, '제26조(관할의 표준이 되는 시기) 법원의 관할은 행정청이 제21조제1항 및 제2항에 따라 이의제기 사실을 통보한 때를 표준으로 정한다.', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4454, '제27조(관할위반에 따른 이송)', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4455, '제28조(준용규정) 「비송사건절차법」 제2조부터 제4조까지, 제6조, 제7조, 제10조(인증과 감정을 제외한다) 및 제24조부터 제26조까지의 규정은 이 법에 따른 과태료 재판(이하 "과태료 재판"이라 한다)에 준용한다.', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4456, '제29조(법원직원의 제척 등) 법원직원의 제척ㆍ기피 및 회피에 관한 「민사소송법」의 규정은 과태료 재판에 준용한다.', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4457, '제30조(행정청 통보사실의 통지) 법원은 제21조제1항 및 제2항에 따른 행정청의 통보가 있는 경우 이를 즉시 검사에게 통지하여야 한다.', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4458, '제31조(심문 등)', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4459, '제32조(행정청에 대한 출석 요구 등)', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4460, '제33조(직권에 의한 사실탐지와 증거조사)', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4461, '제34조(촉탁할 수 있는 사항) 사실탐지ㆍ소환 및 고지에 관한 행위는 촉탁할 수 있다.', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4462, '제35조(조서의 작성) 법원서기관ㆍ법원사무관ㆍ법원주사 또는 법원주사보(이하 "법원사무관등"이라 한다)는 증인 또는 감정인의 심문에 관하여는 조서를 작성하고, 그 밖의 심문에 관하여는 필요하다고 인정하는 경우에 한하여 조서를 작성한다.', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4463, '제36조(재판)', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4464, '제37조(결정의 고지)', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4465, '제38조(항고)', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4466, '제39조(항고법원의 재판) 항고법원의 과태료 재판에는 이유를 적어야 한다.', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4467, '제40조(항고의 절차) 「민사소송법」의 항고에 관한 규정은 특별한 규정이 있는 경우를 제외하고는 이 법에 따른 항고에 준용한다.', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4468, '제41조(재판비용)', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4469, '제42조(과태료 재판의 집행)', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4470, '제43조(과태료 재판 집행의 위탁)', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4471, '제44조(약식재판) 법원은 상당하다고 인정하는 때에는 제31조제1항에 따른 심문 없이 과태료 재판을 할 수 있다.', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4472, '제45조(이의신청)', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4473, '제46조(이의신청 방식)', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4474, '제47조(이의신청 취하)', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4475, '제48조(이의신청 각하)', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4476, '제49조(약식재판의 확정) 약식재판은 다음 각 호의 어느 하나에 해당하는 때에 확정된다.', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4477, '제50조(이의신청에 따른 정식재판절차로의 이행)', 567);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4478, '제51조(자료제출 요구) 법무부장관은 과태료 징수 관련 통계 작성 등 이 법의 운용과 관련하여 필요한 경우에는 중앙행정기관의 장이나 그 밖의 관계 기관의 장에게 과태료 징수 현황 등에 관한 자료의 제출을 요구할 수 있다.', 568);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4479, '제52조(관허사업의 제한)', 568);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4480, '제53조(신용정보의 제공 등)', 568);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4481, '제54조(고액ㆍ상습체납자에 대한 제재)', 568);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4482, '제55조(자동차 관련 과태료 체납자에 대한 자동차 등록번호판의 영치)', 568);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4483, '제56조(자동차 관련 과태료 납부증명서의 제출) 자동차 관련 과태료와 관계된 자동차가 그 자동차 관련 과태료의 체납으로 인하여 압류등록된 경우 그 자동차에 대하여 소유권 이전등록을 하려는 자는 압류등록의 원인이 된 자동차 관련 과태료(제24조에 따른 가산금 및 중가산금을 포함한다)를 납부한 증명서를 제출하여야 한다. 다만, 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 납부사실을 확인할 수 있는 경우에는 그러하지 아니하다.', 568);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4484, '제57조(과태료)', 568);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4485, '제1조(목적) 이 영은 「질서위반행위규제법」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4486, '제2조(질서위반행위에서 제외되는 행위)', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4487, '제2조의2(과태료 감경)', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4488, '제3조(사전통지 및 의견제출 등)', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4489, '제4조(과태료 부과 고지서) 법 제17조제1항에 따라 행정청이 과태료를 부과하는 경우에는 다음 각 호의 사항을 모두 적은 서면(당사자가 동의하는 경우에는 전자문서를 포함한다)으로 하여야 한다. <개정 2011.6.24, 2013.5.10>', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4490, '제4조의2(신용카드 등에 의한 과태료의 납부)', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4491, '제5조(자진납부자에 대한 과태료 감경) 법 제18조제1항에 따라 자진납부하는 경우 감경할 수 있는 금액은 부과될 과태료의 100분의 20의 범위 이내로 한다.', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4492, '제6조(질서위반행위의 조사)', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4493, '제7조(공공기관) 법 제23조에서 "그 밖에 대통령령으로 정하는 공공기관"이란 「공공기관의 운영에 관한 법률」 제4조에 따라 공공기관으로 지정된 기관을 말한다.', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4494, '제7조의2(과태료의 징수유예등)', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4495, '제7조의3(징수유예등의 신청 등)', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4496, '제7조의4(징수유예등의 취소)', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4497, '제7조의5(결손처분)', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4498, '제8조(징수 절차)', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4499, '제9조(이의신청) 법 제46조제1항에 따른 이의신청은 별지 제3호서식의 약식재판에 대한 이의신청서로 한다. <개정 2017.6.2>', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4500, '제10조(이의신청 취하) 법 제47조제1항에 따른 이의신청 취하는 별지 제4호서식의 약식재판에 대한 이의신청취하서로 한다. <개정 2017.6.2>', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4501, '제11조(관허사업 제한의 기준 등)', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4502, '제12조(신용정보 제공사실 통보) 법 제53조에 따라 행정청이 체납 또는 결손처분 자료를 제공한 경우에는 그로부터 30일 이내에 별지 제5호서식의 신용정보 제공사실 통보서로 그 사실을 체납자에게 알려야 한다. <개정 2017.6.2>', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4503, '제13조(감치기준)', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4504, '제14조(자동차 등록번호판의 영치)', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4505, '제14조의2(자동차 등록번호판의 영치 일시 해제)', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4506, '제15조(고유식별정보의 처리) 행정청 또는 검사는 법 및 이 영에 따른 과태료의 부과ㆍ징수 및 재판 등에 관한 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법 시행령」 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 569);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4507, '제1조(목적) 이 법은 특정범죄를 범한 자에 대하여 재범의 위험성을 예방하고 건전한 사회복귀를 촉진하기 위하여 보안관찰처분을 함으로써 국가의 안전과 사회의 안녕을 유지함을 목적으로 한다.', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4508, '제2조(보안관찰해당범죄) 이 법에서 "보안관찰해당범죄"라 함은 다음 각호의 1에 해당하는 죄를 말한다.', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4509, '제3조(보안관찰처분대상자) 이 법에서 "보안관찰처분대상자"라 함은 보안관찰해당범죄 또는 이와 경합된 범죄로 금고 이상의 형의 선고를 받고 그 형기합계가 3년 이상인 자로서 형의 전부 또는 일부의 집행을 받은 사실이 있는 자를 말한다.', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4510, '제4조(보안관찰처분)', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4511, '제5조(보안관찰처분의 기간)', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4512, '제6조(보안관찰처분대상자의 신고)', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4513, '제7조(보안관찰처분의 청구) 보안관찰처분청구는 검사가 행한다.', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4514, '제8조(청구의 방법)', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4515, '제9조(조사)', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4516, '제10조(심사)', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4517, '제11조(보안관찰처분의 면제)', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4518, '제12조(보안관찰처분심의위원회)', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4519, '제13조(피청구자의 자료제출등)', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4520, '제14조(결정)', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4521, '제15조(의결서등)', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4522, '제16조(결정의 취소등)', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4523, '제17조(보안관찰처분의 집행)', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4524, '제18조(신고사항)', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4525, '제19조(지도)', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4526, '제20조(보호)', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4527, '제21조(응급구호) 검사 및 사법경찰관리는 피보안관찰자에게 부상ㆍ질병 기타 긴급한 사유가 발생하였을 때에는 대통령령이 정하는 바에 따라 필요한 구호를 할 수 있다.', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4528, '제22조(경고) 검사 및 사법경찰관리는 피보안관찰자가 의무를 위반하였거나 위반할 위험성이 있다고 의심할 상당한 이유가 있는 때에는 그 이행을 촉구하고 형사처벌등 불이익한 처분을 받을 수 있음을 경고할 수 있다.', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4529, '제23조(행정소송) 이 법에 의한 법무부장관의 결정을 받은 자가 그 결정에 이의가 있을 때에는 행정소송법이 정하는 바에 따라 그 결정이 집행된 날부터 60일 이내에 서울고등법원에 소를 제기할 수 있다. 다만, 제11조의 규정에 의한 면제결정신청에 대한 기각결정을 받은 자가 그 결정에 이의가 있을 때에는 그 결정이 있는 날부터 60일 이내에 서울고등법원에 소를 제기할 수 있다.', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4530, '제24조(행정소송법의 준용) 제23조의 소송에 관하여 이 법에 규정한 것을 제외하고는 행정소송법을 준용한다. 다만, 행정소송법 제18조의 규정은 준용하지 아니한다. <개정 2002.1.26, 2004.10.16>', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4531, '제25조(기간의 계산)', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4532, '제26조(군법피적용자에 대한 특칙등)', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4533, '제27조(벌칙)', 570);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4534, '제1조(목적) 이 영은 보안관찰법(이하 "법"이라 한다)에서 위임된 사항과 그 시행에 관하여 필요한 사항을 규정함을 목적으로 한다.', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4535, '제2조(정의) 이 영에서 사용하는 용어의 정의는 다음과 같다.', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4536, '제3조(형기계산) 법 제3조에 규정된 형기합계를 계산함에 있어 소년법 제60조제1항의 규정에 의한 부정기형이 선고된 경우에는 그 단기를 형기로 한다.', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4537, '제4조(보안관찰)', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4538, '제5조(동태보고등)', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4539, '제6조(보안관찰처분대상자의 신고)', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4540, '제7조(신고의무의 고지) 교도소등의 장은 수용되어 있는 보안관찰처분대상자가 출소할 때에는 법 제6조제1항 및 제2항의 규정에 의하여 거주예정지 관할경찰서장에게 신고할 것을 고지하여야 한다.', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4541, '제8조(출소통보등)', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4542, '제9조(출소사실 신고등)', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4543, '제10조(보안관찰처분대상자 발생통고등)', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4544, '제11조(보안관찰처분대상자의 동태보고) 관할경찰서장은 그 관할구역내에 거주하는 보안관찰처분대상자에 대하여 다음 각호의 1에 해당하는 사유가 발생한 때에는 지체없이 이를 주거지 관할검사에게 보고하여야 한다.', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4545, '제12조(보안관찰처분청구서등)', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4546, '제13조(조사) 검사 또는 사법경찰관리(특별사법경찰관리를 포함한다. 이하 같다)는 법 제9조의 규정에 의한 조사를 위하여 필요한 경우에는 다음의 조치를 할 수 있다.', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4547, '제14조(보안관찰처분 면제결정 신청등)', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4548, '제15조(위원회에의 회부ㆍ의결)', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4549, '제16조(위원회의 직원)', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4550, '제17조(회의록)', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4551, '제18조(수당) 위원회에 출석한 위원에 대하여는 예산의 범위안에서 수당을 지급할 수 있다. 다만, 공무원인 위원이 그 소관업무와 직접적으로 관련하여 위원회에 출석하는 경우에는 그러하지 아니하다.', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4552, '제19조(위원회의 운영세칙) 이 영에 규정한 사항외에 위원회의 운영에 관하여 필요한 사항은 위원회의 의결을 거쳐 위원장이 정한다.', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4553, '제20조(결정서) 보안관찰처분결정서에는 보안관찰처분청구를 한 검사의 직위ㆍ성명과 피청구자의 성명ㆍ연령ㆍ직업ㆍ주거ㆍ결정주문 및 이유와 적용법조를 기재하여야 한다.', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4554, '제21조(결정의 고지) 보안관찰처분에 관한 결정의 고지는 검사가 피청구자 또는 신청인에게 결정서등본을 송달하는 방법으로 한다. 다만, 법 제11조제3항의 규정에 의한 청구를 기각하는 결정에 대하여는 고지하지 아니한다.', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4555, '제22조(지휘ㆍ감독) 검사는 법을 집행함에 있어서는 경찰서장ㆍ사법경찰관리ㆍ교도소등의 장을 지휘ㆍ감독하고 필요한 지시를 할 수 있다.', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4556, '제23조(보안관찰처분 집행중지결정의 신청등)', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4557, '제24조(피보안관찰자의 신고사항등)', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4558, '제25조(지도의 방법)', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4559, '제26조(거소제공의 방법)', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4560, '제27조(거소변경의 절차)', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4561, '제28조(임시거소의 제공)', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4562, '제29조(사회복지시설의 범위등)', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4563, '제30조(응급구호의 범위)', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4564, '제31조(경고의 방법) 법 제22조의 규정에 의한 검사 및 사법경찰관리의 경고는 경고일시, 경고이유, 경고내용 및 그에 위반하는 경우 형사처벌등 불이익한 처분을 받을 수 있음을 기재한 서면에 의하여야 한다. 다만, 긴급을 요하는 때에는 구두로 경고할 수 있다.', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4565, '제32조(군보안관찰처분심의위원회에의 준용) 제15조 내지 제19조의 규정은 군보안관찰처분심의위원회에 이를 준용한다.', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4566, '제32조의2(민감정보 및 고유식별정보의 처리) 관할 검사ㆍ경찰서장, 교도소등의 장 또는 사법경찰관리 등 법에 따라 보안관찰 관련 사무를 처리하는 기관은 그 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 민감정보 또는 같은 법 시행령 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호, 외국인등록번호를 처리할 수 있다.', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4567, '제33조(시행규칙) 이 영 시행에 관하여 필요한 사항은 법무부령으로 정한다. 다만, 군사법원법 제2조제1항 각호의 1에 해당하는 자에 관한 사항은 법무부장관과 협의하여 국방부령으로 정한다.', 571);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4568, '제1조(목적) 이 규칙은 보안관찰법(이하 "법"이라 한다) 및 동법시행령(이하 "영"이라 한다)의 시행에 관하여 필요한 사항을 규정함을 목적으로 한다.', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4569, '제2조(정의) 이 규칙에서 사용하는 용어의 정의는 다음과 같다.', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4570, '제3조(보안관찰부) 영 제4조제2항의 규정에 의한 보안관찰부는 별지 제1호서식에 의한다.', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4571, '제4조(동태보고) 영 제5조제1항 및 제2항의 규정에 의한 보고는 별지 제2호서식에 의한다.', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4572, '제5조(보안관찰처분대상자신고)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4573, '제6조(출소통보)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4574, '제7조(출소사실신고서등)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4575, '제8조(보안관찰처분대상자의 발생통고등)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4576, '제9조(보안관찰처분대상자의 동태보고)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4577, '제10조(보안관찰처분청구서 등) 영 제12조제1항의 규정에 의한 보안관찰처분청구서는 별지 제16호서식, 영 제12조제2항의 규정에 의한 의견서는 별지 제17호서식에 의한다.', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4578, '제11조(관할) 검사 및 사법경찰관리(특별사법경찰관리를 포함한다. 이하 같다)는 각 소속관서의 관할구역내에서 직무를 행한다. 다만, 관할구역내의 사안과 관련이 있는 사실의 조사를 위하여 필요하거나 긴급을 요하는 때에는 관할구역 외에서도 그 직무를 행할 수 있다.', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4579, '제12조(조사의 협조)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4580, '제13조(비밀의 유지와 명예훼손 금지) 검사 및 사법경찰관리는 사안을 조사함에 있어  비밀을 유지하고, 용의자 기타 관계인의 명예를 훼손하지 아니하도록 하여야 한다.', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4581, '제14조(조사의 회피) 검사 또는 사법경찰관리는 용의자 또는 그 관계인과 친족 기타 특별한 관계로 인하여 조사의 공정성을 잃거나 의심을 받을 염려가 있다고 인정되는 사안에 대하여는 소속관서의 장의 허가를 받아 그 조사를 회피하여야 한다.', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4582, '제15조(조사서류의 작성)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4583, '제16조(외국어로 작성된 서류) 외국어로 작성된 서류는 번역문을 첨부하여야 한다.', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4584, '제17조(사안인지)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4585, '제18조(출석요구)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4586, '제19조(용의자에 대한 조사사항) 검사 또는 사법경찰관리는 용의자를 조사하는 때에는 다음 각호의 사항에 유의하여 용의자 신문조서를 작성하여야 한다.', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4587, '제20조(참고인의 진술)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4588, '제21조(임상의 조사) 치료 중인 용의자나 참고인이 있는 곳에서 임상신문을 하는 경우에는 상대방의 건강상태를 충분히 고려하여 조사에 중대한 지장이 없는 한 가족ㆍ의사나 그 밖의 적당한 사람을 참여시켜야 한다. <개정 2022.2.7>', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4589, '제22조(보관조서등)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4590, '제23조(보관물의 보관등)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4591, '제24조(소년용의자에 대한 유의사항)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4592, '제25조(환경조사서등)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4593, '제26조(학생인 용의자에 대한 준용) 학생인 용의자에 대하여는 소년이 아닌 경우에도 제24조 및 제25조의 규정을 준용한다.', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4594, '제27조(사안송치)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4595, '제28조(송치서류)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4596, '제29조(서류 등의 추송) 사법경찰관리는 사안송치 후 서류 또는 물건을 추송하고자 하는 때에는 이미 송치한 사안명ㆍ송치연월일ㆍ용의자의 성명을 기재한 추송서를 작성하고 추송할 서류 및 보관물등을 첨부하여야 한다.', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4597, '제30조(송치 후의 조사등)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4598, '제31조(보안관찰처분 청구등)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4599, '제32조(증명자료) 검사는 보안관찰처분청구를 하는 때에는 청구의 원인이 되는 사실을 증명할 수 있는 피청구자에 대한 다음 각호의 자료를 첨부하여야 한다. 다만, 특별한 사유가 있는 경우에는 해당자료 중 일부를 첨부하지 아니할 수 있다.', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4600, '제33조(보안관찰처분의 기간갱신)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4601, '제34조(검사의 조치결과 통보) 검사는 제27조제1항의 규정에 의하여 송치된 사안에 대하여 보안관찰처분 또는 그 기간갱신을 청구하거나 청구하지 아니하는 조치를 한 때에는 지체없이 그 결과를 당해사안을 송치한 관서의 장에게 통보하여야 한다.', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4602, '제35조(문서의 양식)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4603, '제36조(보안관찰처분면제결정 신청에 관한 조사 등)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4604, '제37조(위원회에의 회부등)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4605, '제38조(보안관찰처분결정통보등)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4606, '제39조(보안관찰처분의 집행지휘)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4607, '제40조(보안관찰처분집행중지결정등과 조사)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4608, '제41조(피보안관찰자의 신고)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4609, '제42조(여행목적지 관할경찰서장의 통보)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4610, '제43조(지도의 방법)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4611, '제44조(거소제공의 청구등)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4612, '제45조(거소변경 신청등)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4613, '제46조(사회복지시설등의 장의 통보) 영 제29조제3항의 규정에 의한 통보는 별지 제67호서식에 의한다.', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4614, '제47조(응급구호) 사법경찰관리가 영 제30조제2항의 규정에 의하여 보고를 하는 때에는 별지 제2호서식에 의하되, 응급구호일시 및 내용 기타 필요한 사항을 기재하여야 한다.', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4615, '제48조(경고서) 영 제31조의 규정에 의한 경고는 별지 제68호서식에 의한다.', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4616, '제49조(장부와 비치서류)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4617, '제50조(서류철의 색인목록)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4618, '제51조(갱신)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4619, '제52조(장부ㆍ서류의 보존기간) 장부 및 서류는 다음의 기간 이를 보존하여야 한다.', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4620, '제53조(보존기간의 기산등)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4621, '제54조(사안기록등의 보관ㆍ보존)', 572);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4622, '제1조(목적) 이 규칙은 「군사법원법」 제2조제1항 각 호의 어느 하나에 해당하는 사람에 대하여 「보안관찰법」 및 같은 법 시행령을 시행하는 데 필요한 사항을 규정함을 목적으로 한다.', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4623, '제2조(정의) 이 규칙에서 사용하는 용어의 뜻은 다음과 같다. <개정 2023.12.13>', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4624, '제3조(보안관찰) 관할방첩부대장은 별지 제1호서식에 따른 보안관찰부를 작성ㆍ비치하여야 하며, 피보안관찰자에 대하여 매월 1회 이상 동태를 관찰하여 그 결과를 보안관찰부에 기록하여야 한다. <개정 2023.12.13>', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4625, '제4조(동태보고) 관할방첩부대장은 「보안관찰법 시행령」(이하 "영"이라 한다) 제5조제1항 및 제2항에 따른 피보안관찰자의 정기ㆍ수시 동태보고서를 별지 제2호서식에 따라 작성하여 피보안관찰자의 소속 부대를 관할하는 군검사에게 보고해야 한다.', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4626, '제5조(보안관찰처분대상자 신고)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4627, '제6조(출소통보) 거주예정지 관할경찰서장은 영 제8조제1항에 따른 출소통보를 받거나 영 제8조제2항에 따른 보고를 하였을 때에는 그 사실을 관할방첩부대장에게 통보하여야 하며, 통보를 받은 관할방첩부대장은 보안관찰처분대상자 관리부에 통보받은 내용을 기록하여야 한다. <개정 2023.12.13>', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4628, '제7조(출소사실 신고서 등) 거주예정지 관할경찰서장은 영 제9조제1항 또는 제2항에 따라 신고서를 받은 경우에는 해당 신고서 사본 1부를 관할방첩부대장에게 송부하여야 하며, 신고서를 받은 관할방첩부대장은 신고사항을 보안관찰처분대상자 관리부에 기록하여야 한다. <개정 2023.12.13>', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4629, '제8조(보안관찰처분대상자의 발생통고 등)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4630, '제9조(보안관찰처분대상자의 동태보고)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4631, '제10조(보안관찰처분 청구서 등) 영 제12조제1항에 따른 보안관찰처분 청구서는 별지 제10호서식과 같고, 영 제12조제2항에 따른 의견서는 별지 제11호서식과 같다.', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4632, '제11조(관할) 군검사와 군사법경찰관리는 각 소속 기관의 관할구역에서 직무를 수행한다. 다만, 관할구역 내의 사안과 관련이 있는 사실을 조사하기 위하여 필요하거나 긴급한 경우에는 관할구역 외에서도 그 직무를 수행할 수 있다. <개정 2023.12.13>', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4633, '제12조(조사의 협조)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4634, '제13조(비밀 유지와 명예훼손 금지) 군검사와 군사법경찰관리는 사안을 조사할 때 비밀을 유지하고, 용의자와 그 밖의 관계인의 명예를 훼손하지 아니하도록 하여야 한다. <개정 2023.12.13>', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4635, '제14조(조사의 회피) 군검사 또는 군사법경찰관리는 용의자 또는 그 관계인과 친족이거나 그 밖의 특별한 관계로 인하여 조사의 공정성을 잃거나 그 공정성에 의심을 받을 염려가 있다고 인정되는 사안에 대해서는 소속 기관의 장의 허가를 받아 그 조사를 회피하여야 한다. <개정 2023.12.13>', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4636, '제15조(조사서류의 작성)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4637, '제16조(외국어로 작성된 서류) 외국어로 작성된 서류는 번역문을 첨부하여야 한다.', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4638, '제17조(사안의 인지)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4639, '제18조(출석요구)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4640, '제19조(용의자에 대한 조사사항) 군검사 또는 군사법경찰관리는 용의자를 조사할 때에는 다음 각 호의 사항에 유의하여 용의자 신문조서를 작성하여야 한다. <개정 2020.7.28, 2023.12.13>', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4641, '제20조(참고인의 진술)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4642, '제21조(임상조사) 치료 중인 용의자나 참고인이 있는 곳에서 임상신문(臨床訊問)을 하는 경우에는 상대방의 건강상태를 충분히 고려하여 조사에 중대한 지장이 없는 한 가족, 군의관, 그 밖에 적당한 사람을 참여시켜야 한다.', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4643, '제22조(보관조서 등)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4644, '제23조(보관물의 보관 등)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4645, '제24조(소년인 용의자에 대한 유의사항)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4646, '제25조(환경조사서 등)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4647, '제26조(사안의 송치)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4648, '제27조(송치서류)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4649, '제28조(서류 등의 추가 송치) 군사법경찰관리는 사안 송치 후 서류나 물건을 추가로 송치할 때에는 이미 송치한 사안명, 송치 연월일, 용의자의 성명을 적은 추송서를 작성하고 추가로 송치할 서류 및 보관물 등을 첨부하여야 한다.', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4650, '제29조(송치 후의 조사 등)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4651, '제30조(보안관찰처분 청구 등)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4652, '제31조(증명자료) 군검사는 보안관찰처분 청구를 할 때에는 청구의 원인이 되는 사실을 증명할 수 있는 피청구자에 대한 다음 각 호의 자료를 첨부하여야 한다. 다만, 특별한 사유가 있는 경우에는 해당 자료 중 일부를 첨부하지 아니할 수 있다. <개정 2023.12.13>', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4653, '제32조(보안관찰처분의 기간갱신)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4654, '제33조(군검사의 조치 결과 통보) 군검사는 제26조제1항에 따라 송치된 사안에 대하여 보안관찰처분 또는 그 기간갱신을 청구하거나 청구하지 아니하는 조치를 하였을 때에는 지체 없이 그 결과를 해당 사안을 송치한 부대의 장에게 통보하여야 한다. <개정 2023.12.13>', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4655, '제34조(문서와 장부의 양식)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4656, '제35조(보안관찰처분 면제결정 신청에 관한 조사 등)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4657, '제36조(위원회에의 회부 등)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4658, '제37조(보안관찰처분 결정통보 등)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4659, '제38조(보안관찰처분의 집행지휘)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4660, '제39조(보안관찰처분 집행중지결정 등과 조사)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4661, '제40조(피보안관찰자의 신고)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4662, '제41조(휴가 등 목적지 방첩부대장의 통보)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4663, '제42조(지도의 방법)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4664, '제43조(거소제공의 청구 등)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4665, '제44조(거소변경 신청 등)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4666, '제45조(응급구호) 군사법경찰관리가 영 제30조제2항에 따라 보고를 할 때에는 별지 제2호서식에 따르되, 응급구호 일시 및 내용, 그 밖에 필요한 사항을 적어야 한다.', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4667, '제46조(경고서) 영 제31조에 따른 경고는 별지 제54호서식에 따른다.', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4668, '제47조(장부와 비치서류)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4669, '제48조(서류철의 찾아보기 목록)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4670, '제49조(갱신)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4671, '제50조(장부ㆍ서류의 보존기간) 장부와 서류는 다음 각 호의 구분에 따른 기간 동안 보존하여야 한다.', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4672, '제51조(보존기간의 기산 등)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4673, '제52조(사안기록 등의 보관ㆍ보존)', 573);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4674, '제1조 (목적) 이 규칙은 배타적경제수역에서의외국인어업등에대한주권적권리의행사에관한법률(이하 "법"이라 한다) 제23조 및 제24조의 규정에 의한 위반선박등에 대한 사법절차와 담보금에 관하여 필요한 사항을 규정함을 목적으로 한다.', 574);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4675, '제2조 (위반선박등에 대한 조치)', 574);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4676, '제3조 (담보금납입 등)', 574);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4677, '제4조 (위반자의 석방 등)', 574);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4678, '제5조 (담보금의 국고귀속)', 574);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4679, '제6조 (담보금의 환부 등)', 574);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4680, '제1조(목적) 이 영은 「가정폭력범죄의 처벌 등에 관한 특례법」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 575);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4681, '제2조(신변안전조치의 청구 등)', 575);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4682, '제3조(신변안전조치의 종류) 법 제55조의2제5항제3호에서 "그 밖에 피해자의 신변안전을 위하여 대통령령으로 정하는 조치"란 다음 각 호의 조치를 말한다.', 575);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4683, '제4조(신변안전조치 종류의 변경 청구 등)', 575);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4684, '제5조(신변안전조치의 집행 방법)', 575);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4685, '제6조(신변안전조치의 이행 통보 등)', 575);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4686, '제7조(전자문서) 제2조제1항에 따른 청구ㆍ요청, 제4조제1항ㆍ제2항에 따른 변경ㆍ추가 및 연장 청구, 같은 조 제3항에 따른 요청 및 제6조제1항ㆍ제2항에 따른 통보 등은 전자문서로 할 수 있다.', 575);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4687, '제1조(목적) 이 영은 「마약류 불법거래 방지에 관한 특례법」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 576);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4688, '제2조 삭제 <2011.8.3>', 576);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4689, '제3조(금융기관의 신고사항) 「마약류 불법거래 방지에 관한 특례법」(이하 "법"이라 한다) 제5조제1항에 따라 금융기관에 종사하는 사람이 신고를 하는 경우에는 다음 각 호의 사항을 적은 서면을 검찰총장에게 제출하여야 한다.', 576);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4690, '제1조 (목적) 이 규칙은 「질서위반행위규제법」(다음부터 "법"이라고 한다) 제54조에 따라 감치에 처하는 재판절차 및 집행 그 밖의 필요한 사항을 정하는 것을 목적으로 한다.', 577);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4691, '제2조 (관할) 감치청구 사건은 청구 당시 체납자(법인인 경우에는 대표자를 말한다. 다음부터 같다)의 주소지를 관할하는 지방법원 또는 그 지원의 전속관할로 한다.', 577);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4692, '제3조 (감치재판의 청구) 법 제54조제1항에 따른 감치재판의 청구는 다음 각 호의 사항을 기재하고, 검사가 기명날인 또는 서명한 서면으로 한다.', 577);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4693, '제4조 (청구각하의 결정)', 577);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4694, '제5조 (재판기일의 지정 등) 법 제54조제1항에 따른 청구가 이유 있다고 인정한 때에는 재판장은 재판기일을 정하여 체납자를 소환하고, 검사에게 그 기일을 통지하여야 한다.', 577);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4695, '제6조 (감치의 재판 등)', 577);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4696, '제7조 (즉시항고)', 577);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4697, '제8조 (재항고) 항고법원의 결정에 대하여는 재판에 영향을 미친 헌법ㆍ법률ㆍ명령 또는 규칙의 위반을 이유로 드는 때에만 재항고할 수 있다.', 577);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4698, '제9조 (집행지휘)', 577);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4699, '제10조 (감치기간의 계산) 감치의 기간은 감치에 처하는 재판의 집행 또는 그 집행을 위한 구인에 의하여 체납자가 실제로 구속된 날부터 기산하고, 초일은 그 시간에 불구하고 이를 1일로 산정한다.', 577);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4700, '제11조 (감치의 집행방법) 감치에 처하는 재판을 받은 체납자를 감치시설에 유치하는 때에는 「행형법」 중 미결수용자에 대한 수용절차에 의한다.', 577);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4701, '제12조 (과태료 납부에 의한 감치집행의 종료)', 577);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4702, '제13조 (준용규정)', 577);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4703, '제1조(목적) 이 법은 건전한 국민경제윤리에 반하는 특정경제범죄에 대한 가중처벌과 그 범죄행위자에 대한 취업제한 등을 규정함으로써 경제질서를 확립하고 나아가 국민경제 발전에 이바지함을 목적으로 한다.', 578);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4704, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다. <개정 2016.3.29, 2016.5.29>', 578);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4705, '제3조(특정재산범죄의 가중처벌)', 578);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4706, '제4조(재산국외도피의 죄)', 578);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4707, '제5조(수재 등의 죄)', 578);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4708, '제6조(증재 등의 죄)', 578);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4709, '제7조(알선수재의 죄) 금융회사등의 임직원의 직무에 속하는 사항의 알선에 관하여 금품이나 그 밖의 이익을 수수, 요구 또는 약속한 사람 또는 제3자에게 이를 공여하게 하거나 공여하게 할 것을 요구 또는 약속한 사람은 5년 이하의 징역 또는 5천만원 이하의 벌금에 처한다.', 578);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4710, '제8조(사금융 알선 등의 죄) 금융회사등의 임직원이 그 지위를 이용하여 자기의 이익 또는 소속 금융회사등 외의 제3자의 이익을 위하여 자기의 계산으로 또는 소속 금융회사등 외의 제3자의 계산으로 금전의 대부, 채무의 보증 또는 인수를 하거나 이를 알선하였을 때에는 7년 이하의 징역 또는 7천만원 이하의 벌금에 처한다.', 578);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4711, '제9조(저축 관련 부당행위의 죄)', 578);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4712, '제10조(몰수ㆍ추징)', 578);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4713, '제11조(무인가 단기금융업의 가중처벌)', 578);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4714, '제12조(보고의무 등)', 578);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4715, '제13조 삭제 <2009.5.8>', 578);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4716, '제14조(일정 기간의 취업제한 및 인가ㆍ허가 금지 등)', 578);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4717, '제1조(목적) 이 영은 「특정경제범죄 가중처벌 등에 관한 법률」에서 위임된 사항과 그 시행에 관하여 필요한 사항을 정함을 목적으로 한다. <개정 2009.7.7>', 579);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4718, '제2조(대출등의 범위) 「특정경제범죄 가중처벌 등에 관한 법률」(이하 "법"이라 한다) 제2조제3호에서 "대통령령으로 정하는 것"이란 다음 각 호의 어느 하나에 해당하는 것을 말한다. <개정 2009.7.7, 2019.5.7>', 579);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4719, '제3조(감독기관의 감독업무에 종사하는 사람의 범위) 법 제12조제2항에 따른 감독기관의 감독업무에 종사하는 사람은 다음 각 호의 어느 하나에 해당하는 기관의 임ㆍ직원으로서 소관 금융회사등에 대한 감사 또는 검사의 직무(일시적인 감사 또는 검사의 직무의 경우를 포함한다)에 종사하는 사람 및 그 직무를 관장하는 상급자와 해당 감독기관의 장으로 한다. <개정 1998ㆍ4ㆍ1, 2019.5.7>', 579);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4720, '제4조 삭제 <2009.7.7>', 579);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4721, '제5조 삭제 <2009.7.7>', 579);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4722, '제6조 삭제 <2009.7.7>', 579);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4723, '제7조 삭제 <2009.7.7>', 579);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4724, '제8조 삭제 <2009.7.7>', 579);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4725, '제9조(수사기관의 통보등)', 579);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4726, '제10조(취업제한대상인 기관 및 기업체의 범위)', 579);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4727, '제11조(허가등이 금지되는 관허업의 범위) 법 제14조제2항에서 "대통령령으로 정하는 관허업"이란 특정한 사업ㆍ영업 또는 행위를 업으로 하기 위하여 행정기관으로부터 허가ㆍ인가ㆍ면허ㆍ등록ㆍ지정ㆍ승인 및 특허(이하 "허가등"이라 한다)를 받아야 할 대상으로서 그 처분청이 중앙행정기관의 장, 특별시장, 광역시장, 특별자치시장, 도지사 또는 특별자치도지사인 경우(법령에 따라 그 허가등의 권한이 하부기관 또는 다른 기관에 위임 또는 위탁된 경우를 포함한다)의 해당 사업ㆍ영업 또는 행위를 말한다. <개정 2019.5.7>', 579);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4728, '제12조(취업제한사실등의 통지) 법무부장관은 법 제3조ㆍ법 제4조제2항(미수범을 포함한다)ㆍ법 제5조제4항 또는 법 제8조의 죄를 범한 사람에 대한 재판결과를 항상 파악하여 그에 대한 유죄판결이 확정된 때에는 지체 없이 법 제14조제1항 및 제2항에 따른 취업제한 및 허가등 금지사실과 그 대상의 범위를 그 판결이 확정된 사람에게 통지하여야 한다. <개정 2009.7.7, 2019.5.7>', 579);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4729, '제13조(취업승인신청)', 579);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4730, '제14조(관허업의 허가등 승인신청)', 579);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4731, '제15조(민감정보 및 고유식별정보 등의 처리)', 579);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4732, '제1조(목적) 이 법은 「형법」, 「관세법」, 「조세범 처벌법」, 「지방세기본법」, 「산림자원의 조성 및 관리에 관한 법률」 및 「마약류관리에 관한 법률」에 규정된 특정범죄에 대한 가중처벌 등을 규정함으로써 건전한 사회질서의 유지와 국민경제의 발전에 이바지함을 목적으로 한다. <개정 2011.12.31>', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4733, '제2조(뇌물죄의 가중처벌)', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4734, '제3조(알선수재) 공무원의 직무에 속한 사항의 알선에 관하여 금품이나 이익을 수수ㆍ요구 또는 약속한 사람은 5년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4735, '제4조(뇌물죄 적용대상의 확대)', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4736, '제4조의2(체포ㆍ감금 등의 가중처벌)', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4737, '제4조의3(공무상 비밀누설의 가중처벌) 「국회법」 제54조의2제2항을 위반한 사람은 5년 이하의 징역 또는 500만원 이하의 벌금에 처한다.', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4738, '제5조(국고 등 손실) 「회계관계직원 등의 책임에 관한 법률」 제2조제1호ㆍ제2호 또는 제4호(제1호 또는 제2호에 규정된 사람의 보조자로서 그 회계사무의 일부를 처리하는 사람만 해당한다)에 규정된 사람이 국고(國庫) 또는 지방자치단체에 손실을 입힐 것을 알면서 그 직무에 관하여 「형법」 제355조의 죄를 범한 경우에는 다음 각 호의 구분에 따라 가중처벌한다.', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4739, '제5조의2(약취ㆍ유인죄의 가중처벌)', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4740, '제5조의3(도주차량 운전자의 가중처벌)', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4741, '제5조의4(상습 강도ㆍ절도죄 등의 가중처벌)', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4742, '제5조의5(강도상해 등 재범자의 가중처벌) 「형법」 제337조ㆍ제339조의 죄 또는 그 미수죄로 형을 선고받고 그 집행이 끝나거나 면제된 후 3년 내에 다시 이들 죄를 범한 사람은 사형, 무기 또는 10년 이상의 징역에 처한다.', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4743, '제5조의6 삭제 <1994.1.5>', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4744, '제5조의7 삭제 <1994.1.5>', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4745, '제5조의8 삭제 <2013.4.5>', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4746, '제5조의9(보복범죄의 가중처벌 등)', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4747, '제5조의10(운행 중인 자동차 운전자에 대한 폭행 등의 가중처벌)', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4748, '제5조의11(위험운전 등 치사상)', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4749, '제5조의12(도주선박의 선장 또는 승무원에 대한 가중처벌) 「해사안전기본법」 제3조제2호에 따른 선박의 교통으로 인하여 「형법」 제268조의 죄를 범한 해당 선박의 선장 또는 승무원이 피해자를 구호하는 등 「수상에서의 수색ㆍ구조 등에 관한 법률」 제18조제1항 단서에 따른 조치를 하지 아니하고 도주한 경우에는 다음 각 호의 구분에 따라 가중 처벌한다. <개정 2015.7.24, 2023.7.25>', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4750, '제5조의13(어린이 보호구역에서 어린이 치사상의 가중처벌) 자동차등의 운전자가 「도로교통법」 제12조제3항에 따른 어린이 보호구역에서 같은 조 제1항에 따른 조치를 준수하고 어린이의 안전에 유의하면서 운전하여야 할 의무를 위반하여 어린이(13세 미만인 사람을 말한다. 이하 같다)에게 「교통사고처리 특례법」 제3조제1항의 죄를 범한 경우에는 다음 각 호의 구분에 따라 가중처벌한다. <개정 2022.12.27>', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4751, '제6조(「관세법」 위반행위의 가중처벌)', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4752, '제7조(관계 공무원의 무기 사용) 「관세법」 위반사범을 단속할 권한이 있는 공무원은 해상(海上)에서 「관세법」 제269조 또는 제270조에 규정된 죄를 범한 사람이 정지명령을 받고 도피하는 경우에 이를 제지(制止)하기 위하여 필요하다고 인정되는 상당한 이유가 있을 때에는 총기(銃器)를 사용할 수 있다.', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4753, '제8조(조세 포탈의 가중처벌)', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4754, '제8조의2(세금계산서 교부의무 위반 등의 가중처벌)', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4755, '제9조(「산림자원의 조성 및 관리에 관한 법률」 등 위반행위의 가중처벌)', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4756, '제10조 삭제 <2016.1.6>', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4757, '제11조(마약사범 등의 가중처벌)', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4758, '제12조(외국인을 위한 탈법행위) 외국인에 의한 취득이 금지 또는 제한된 재산권을 외국인을 위하여 외국인의 자금으로 취득한 사람은 다음 각 호의 구분에 따라 처벌한다.', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4759, '제13조(몰수) 제3조 또는 제12조의 죄를 범하여 범인이 취득한 해당 재산은 몰수하며, 몰수할 수 없을 때에는 그 가액을 추징(追徵)한다.', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4760, '제14조(무고죄) 이 법에 규정된 죄에 대하여 「형법」 제156조에 규정된 죄를 범한 사람은 3년 이상의 유기징역에 처한다.', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4761, '제15조(특수직무유기) 범죄 수사의 직무에 종사하는 공무원이 이 법에 규정된 죄를 범한 사람을 인지하고 그 직무를 유기한 경우에는 1년 이상의 유기징역에 처한다.', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4762, '제16조(소추에 관한 특례) 제6조 및 제8조의 죄에 대한 공소(公訴)는 고소 또는 고발이 없는 경우에도 제기할 수 있다.', 580);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4763, '제1조(목적) 이 영은 「특정범죄 가중처벌 등에 관한 법률」 제4조에 따라 뇌물죄가 적용되는 기관 또는 단체 및 간부직원의 범위를 규정함을 목적으로 한다.', 581);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4764, '제2조(기관 또는 단체의 범위) 「특정범죄 가중처벌 등에 관한 법률」(이하 "법"이라 한다) 제4조제1항에 따른 기관 또는 단체의 범위는 다음과 같다. <개정 2012.1.25, 2015.7.24, 2016.5.31, 2016.8.31, 2019.1.15, 2019.4.2, 2020.9.10, 2020.12.8, 2021.8.31>', 581);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4765, '제3조(간부직원의 범위) 법 제4조제2항에 따른 기관 또는 단체의 간부직원의 범위는 다음 각 호와 같다. 다만, 다른 법령에 따라 공무원 또는 공무원에 준하는 신분을 가지는 경우에는 그 법령의 적용을 배제하지 아니한다.', 581);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4766, '제1조(목적) 이 법은 군사경찰의 직무수행에 필요한 사항을 규정함으로써 적법한 직무의 집행을 보장하고 직무를 수행하면서 발생할 수 있는 인권 침해를 방지함을 목적으로 한다.', 582);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4767, '제2조(직무수행의 기본원칙)', 582);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4768, '제3조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다. <개정 2022.12.13>', 582);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4769, '제4조(적용대상)', 582);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4770, '제5조(군사경찰의 직무범위와 지휘ㆍ감독)', 582);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4771, '제6조(군인권보호관에 대한 협조) 군사경찰은 「군인의 지위 및 복무에 관한 기본법」 제42조에 따른 군인권보호관(이하 "군인권보호관"이라 한다)이 그 직무수행을 목적으로 요청하는 사항에 대하여 특별한 사정이 없으면 협조하여야 한다.', 582);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4772, '제7조(직무질문 및 동행요구)', 582);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4773, '제8조(범죄의 예방과 제지) 군사경찰은 군사지역에서 범죄행위가 목전(目前)에 행하여지려고 하고 있다고 인정될 때에는 이를 예방하기 위하여 관계인에게 필요한 경고를 하고, 그 행위로 인하여 사람의 생명ㆍ신체에 위해를 끼치거나 재산에 중대한 손해를 끼칠 우려가 있는 긴급한 경우에는 그 행위를 제지할 수 있다.', 582);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4774, '제9조(위험방지를 위한 출입)', 582);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4775, '제10조(교통ㆍ운항ㆍ항행 질서 유지 등)', 582);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4776, '제11조(군사경찰장비의 사용)', 582);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4777, '제12조(군사경찰장구의 사용) 군사경찰은 다음 각 호의 직무를 수행하기 위하여 필요하다고 인정되는 상당한 이유가 있을 때에는 그 사태를 합리적으로 판단하여 최소한의 범위에서 군사경찰장구를 사용할 수 있다.', 582);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4778, '제13조(분사기등의 사용) 군사경찰은 다음 각 호의 직무를 수행하기 위하여 부득이한 경우 현장책임자의 판단으로 필요한 최소한의 범위에서 분사기등을 사용할 수 있다.', 582);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4779, '제14조(무기의 사용)', 582);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4780, '제15조(군사경찰장비에 대한 안전교육 등)', 582);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4781, '제16조(사용기록의 보관) 전자충격기, 전자충격총, 분사기등 또는 무기를 사용한 경우 그 사용자가 소속된 군사경찰부대의 지휘관은 사용일시ㆍ장소ㆍ대상ㆍ현장책임자ㆍ종류 및 수량 등을 기록하여 보관하여야 한다.', 582);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4782, '제17조 삭제 <2025.1.7>', 582);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4783, '제17조의2(소송 지원) 국방부장관, 각 군 참모총장 또는 군사경찰부대가 설치되어 있는 부대의 장(이하 "국방부장관등"이라 한다)은 군사경찰이 제5조제1항 각 호에 따른 직무의 수행으로 인하여 민ㆍ형사상 책임과 관련된 소송을 수행할 경우 변호인 선임 등 소송 수행에 필요한 지원을 할 수 있다. 이 경우 민ㆍ형사상 책임이 군사경찰의 고의 또는 중대한 과실로 인하여 발생한 경우, 국방부장관등은 해당 군사경찰에게 소송비용 등에 대한 구상권을 행사할 수 있다.', 582);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4784, '제17조의3(직무수행으로 인한 형의 감면) 군사지역에서 다음 각 호의 범죄행위가 목전에 행하여지려고 하거나 행하여지고 있어 타인의 생명ㆍ신체에 대한 위해 발생의 우려가 명백하고 긴급한 상황에서, 군사경찰이 그 위해를 예방하거나 진압하기 위한 행위 또는 범인의 검거 과정에서 군사경찰을 향한 직접적인 유형력 행사에 대응하는 행위를 하여 그로 인하여 타인에게 피해가 발생한 경우, 그 군사경찰의 직무수행이 불가피한 것이고 필요한 최소한의 범위에서 이루어졌으며 해당 군사경찰에게 고의 또는 중대한 과실이 없는 때에는 그 정상을 참작하여 형을 감경하거나 면제할 수 있다.', 582);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4785, '제18조(인권지도 및 감독) 군사경찰부대의 지휘관은 소속 군사경찰이 직무를 수행하는 과정에서 인권을 침해하지 아니하도록 지도하고 인권을 침해하였는지 여부를 감독할 책임이 있으며 인권침해와 관련된 사실을 인지할 경우 이를 군인권보호관 또는 「군인사법」 제59조의2에 따른 인권담당 군법무관에게 통보하고 적절한 조치를 취하여야 한다.', 582);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4786, '제19조(벌칙)', 582);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4787, '제1조(목적) 이 영은 「군사경찰의 직무수행에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4788, '제2조(군사경찰) 「군사경찰의 직무수행에 관한 법률」(이하 "법"이라 한다) 제3조제1호에서 "대통령령으로 정하는 사람"이란 다음 각 호의 구분에 따라 국방부장관 또는 각 군 참모총장(해병대의 경우에는 해병대사령관을 말한다. 이하 같다)이 군사경찰로 임명한 사람을 말한다. 다만, 병(兵)의 경우에는 군사경찰부대가 설치되어 있는 부대의 장이 군사경찰로 임명한 사람을 말한다.', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4789, '제3조(증표) 국방부장관 및 각 군 참모총장은 제2조에 따라 군사경찰로 임명한 사람(병은 제외한다)에게 군사경찰 신분을 표시하는 증표를 발급해야 한다.', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4790, '제4조(군사경찰장구) 법 제3조제5호에서 "수갑ㆍ포승(捕繩)ㆍ경찰봉ㆍ전자충격기ㆍ전자충격총 및 방패 등 대통령령으로 정하는 장치와 기구"란 다음 각 호의 장치와 기구를 말한다.', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4791, '제5조(보고) 군사경찰은 다음 각 호에 해당하는 경우에는 군사경찰부대가 설치되어 있는 부대의 장에게 그 사실을 보고해야 한다.', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4792, '제6조(군사경찰의 직무수행을 위한 관계 기관 협조) 군사경찰은 법 제5조제1항제3호의 업무를 수행하기 위하여 필요한 경우 경찰관서 등 관계 기관에 신병 인계, 사건 이첩 및 사실조회에 관한 협조를 요청할 수 있다.', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4793, '제7조(군사경찰의 지휘ㆍ감독) 군사경찰부대가 설치되어 있는 부대의 장은 수사의 공정성을 확보하기 위하여 군사경찰이 법 제5조제1항제3호에 따른 직무를 수행할 때 독립성을 보장해야 한다.', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4794, '제8조(교통ㆍ운항ㆍ항행 질서 유지 등)', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4795, '제9조(위해성 군사경찰장비의 종류) 법 제11조제1항 단서에 따른 위해성 군사경찰장비의 종류는 다음 각 호와 같다.', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4796, '제10조(위해성 군사경찰장비 및 군사경찰장비의 안전교육) 법 제11조제1항 단서에 따른 위해성 군사경찰장비의 안전교육 기준 및 법 제15조제1항에 따른 군사경찰장비의 사용방법ㆍ관리 및 안전 등에 관한 교육 내용과 방법은 각각 별표 1과 같다.', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4797, '제11조(위해성 군사경찰장비의 안전검사 기준) 법 제11조제1항 단서 및 제15조제2항에 따른 위해성 군사경찰장비의 안전검사 기준은 각각 별표 2와 같다.', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4798, '제12조(위해성 군사경찰장비의 사용기준) 법 제11조제3항에 따른 위해성 군사경찰장비의 사용기준은 다음 각 호와 같다.', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4799, '제13조(신규 도입 위해성 군사경찰장비의 안전성 검사)', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4800, '제14조(손실보상의 기준 및 보상금액 등)', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4801, '제15조(손실보상의 지급절차 및 방법)', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4802, '제16조(손실보상심의위원회의 구성)', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4803, '제17조(위원장)', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4804, '제18조(위원회의 운영)', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4805, '제19조(위원의 제척ㆍ기피ㆍ회피)', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4806, '제20조(위원의 해촉) 국방부장관은 위원회의 위원이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 위원을 해촉(解囑)할 수 있다.', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4807, '제21조(비밀 누설의 금지) 위원회의 회의에 참석한 사람은 직무상 알게 된 비밀을 누설해서는 안 된다.', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4808, '제22조(위원회의 운영 등에 필요한 사항) 제16조부터 제21조까지에서 규정한 사항 외에 위원회의 운영 등에 필요한 사항은 국방부장관이 정한다.', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4809, '제23조(민감정보 및 고유식별정보의 처리) 군사경찰은 법 제5조제1항제3호(범죄의 정보수집에 관한 직무는 제외한다. 이하 이 조에서 같다) 및 제4호에 따른 직무를 수행하기 위하여 불가피한 경우 다음 각 호의 구분에 따른 정보가 포함된 자료를 처리할 수 있다.', 583);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4810, '제1조(목적) 이 영은 「스토킹방지 및 피해자보호 등에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 584);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4811, '제2조(스토킹 실태조사)', 584);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4812, '제3조(스토킹 예방교육 등)', 584);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4813, '제4조(피해자등의 취학 지원)', 584);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4814, '제5조(피해자 지원시설의 설치ㆍ운영 기준) 법 제8조제1항에 따른 피해자 지원시설(이하 "지원시설"이라 한다)의 설치ㆍ운영 기준은 별표 1과 같다.', 584);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4815, '제6조(지원시설의 설치ㆍ운영 업무의 위탁) 법 제8조제2항에서 "대통령령으로 정하는 기관 또는 단체"란 다음 각 호의 기관 또는 단체를 말한다.', 584);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4816, '제7조(지원시설의 업무) 법 제9조제11호에서 "대통령령으로 정하는 업무"란 피해자등에 대한 보호ㆍ지원을 원활히 하기 위한 관련 시설과의 협력 업무를 말한다.', 584);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4817, '제8조(지원시설 종사자 등의 자격기준) 법 제10조제2항에서 "전문 지식이나 경력 등 대통령령으로 정하는 자격기준"이란 별표 2에 따른 자격기준을 말한다.', 584);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4818, '제9조(교육의 실시)', 584);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4819, '제10조(민감정보 및 고유식별정보의 처리)', 584);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4820, '제11조(규제의 재검토) 여성가족부장관은 다음 각 호의 사항에 대하여 2024년 1월 1일을 기준으로 3년마다(매 3년이 되는 해의 기준일과 같은 날 전까지를 말한다) 그 타당성을 검토하여 개선 등의 조치를 해야 한다.', 584);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4821, '제12조(과태료의 부과기준) 법 제18조제1항에 따른 과태료의 부과기준은 별표 3과 같다.', 584);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4822, '제1조(목적) 이 규칙은 「보호관찰 등에 관한 법률」 및 같은 법 시행령에서 위임된 사항과 그 시행에 관하여 필요한 사항을 규정함을 목적으로 한다. <개정 2009.3.19>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4823, '제2조(수당 및 여비) 「보호관찰 등에 관한 법률」(이하 "법"이라 한다) 제5조의 규정에 의한 보호관찰심사위원회(이하 "심사위원회"라 한다)의 위원장 및 비상임위원의 출석수당과 공무원이 아닌 위원의 여비는 별표와 같다. <개정 2009.3.19>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4824, '제3조(심사사건의 수리) 심사위원회는 법 제11조에 따라 심사를 하는 때에는 별지 제1호서식의 심사사건부에 정해진 사항을 기재해야 한다. <개정 2022.2.7>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4825, '제4조(면접조사표) 심사위원회의 상임위원 또는 보호관찰관은 법 제11조제2항의 규정에 의하여 보호관찰대상자 기타 관계인을 조사한 때에는 별지 제2호서식의 면접조사표를 작성하여야 한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4826, '제5조(결정서 등)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4827, '제6조(회의록 작성)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4828, '제7조(심사위원회의 운영세칙) 이 규칙에 규정된 사항외에 심사위원회의 운영에 관하여 필요한 사항은 심사위원회의 의결을 거쳐 위원장이 정한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4829, '제7조의2(교육훈련)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4830, '제7조의3(조사관)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4831, '제8조(범죄예방자원봉사위원의 위촉 및 해촉)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4832, '제9조(범죄예방위원의 정원) 범죄예방위원의 정원은 시(구가 설치되지 아니한 시를 말한다)ㆍ군ㆍ구별로 그 지역의 인구ㆍ범죄상황 기타 사정을 고려하여 인구 1천명당 1인의 범위내에서 법무부장관이 정한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4833, '제10조(범죄예방위원의 직무) 범죄예방위원은 다음 각호의 직무를 수행한다. <개정 2009.11.27>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4834, '제11조(범죄예방위원의 조직) 범죄예방위원의 체계적인 활동을 도모하기 위하여 법무부장관이 정하는 바에 의하여 범죄예방지도협의회와 범죄예방위원의 자치조직을 둘 수 있다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4835, '제11조의2(특별범죄예방자원봉사위원)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4836, '제12조(비용의 지급) 범죄예방위원과 특별범죄예방위원에 대하여는 예산의 범위안에서 그 직무수행에 필요한 실비를 지급한다. <개정 2009.11.27>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4837, '제13조(기간경과통보서) 영 제8조의 규정에 의한 기간경과통보서는 별지 제4호서식에 의한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4838, '제14조(기간경과통보서접수부) 심사위원회는 기간경과통보서를 접수한 때에는 별지 제5호서식의 기간경과통보서접수부에 정해진 사항을 기재해야 한다. <개정 2022.2.7>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4839, '제15조(수용자의 이송통지)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4840, '제16조(가석방 등의 심사신청서)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4841, '제17조(가석방ㆍ퇴원 및 임시퇴원의 결과통보) 심사위원회는 가석방 또는 임시퇴원이 허가된 자를 수용하는 수용기관의 장과 그의 주거지를 관할하는 보호관찰소의 장에게 그 명단과 결정서등본을 송부하여야 한다. 다만, 퇴원이 허가된 자 또는 가석방이 허가된 자중 법무부장관이 보호관찰이 필요없다고 인정한 자에 대하여는 수용기관의 장에게만 그 명단과 결정서등본을 송부한다. <개정 2009.3.19>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4842, '제18조(환경조사서) 법 제26조제2항의 규정에 의한 환경조사의 통보는 별지 제8호서식에 의한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4843, '제19조(환경개선활동결과통보서) 법 제27조제3항의 규정에 의한 환경개선활동결과통보는 별지 제9호서식에 의한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4844, '제20조(신고서) 영 제16조 및 제39조제1항에 따른 신고는 별지 제10호서식에 의한다. <개정 2009.11.27>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4845, '제21조(보호관찰사건부등)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4846, '제22조(보호관찰기간의 계산) 보호관찰기간은 법 제29조제1항의 규정에 의하여 보호관찰이 개시된 때부터 진행한다. 이 경우 초일은 보호관찰기간에 산입한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4847, '제23조(보호관찰담당자의 지명 및 임무)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4848, '제24조(주거이전 및 여행신고서) 영 제18조의 규정에 의한 주거이전 및 여행의 신고는 별지 제15호서식에 의한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4849, '제24조의2(준수사항의 추가 등) 법 제32조제4항에 따른 준수사항의 추가, 변경 또는 삭제의 신청 및 청구는 별지 제15호의2서식에 따른다. <개정 2019.10.17>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4850, '제25조(원호 및 응급구호부) 보호관찰관이 법 제34조에 따라 원호를 실시하거나 보호관찰소의 장이 법 제35조에 따라 응급구호를 실시한 때에는 별지 제16호서식의 원호 및 응급구호부에 정해진 사항을 기재해야 한다. <개정 2022.2.7>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4851, '제25조의2(원호협의회)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4852, '제25조의3(보호관찰 종료사실의 통보)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4853, '제26조(출석요구서) 영 제21조제1항의 규정에 의한 출석요구서는 별지 제17호서식에 의한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4854, '제27조(진술조서) 영 제21조제2항의 규정에 의한 조사는 별지 제18호서식에 의한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4855, '제28조(경고장) 영 제22조에 따른 경고는 별지 제19호서식에 따른다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4856, '제29조(구인장신청서등)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4857, '제30조(구인장) 영 제24조 및 제39조제2항에 따른 구인장은 별지 제22호서식에 의한다. <개정 2009.11.27>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4858, '제31조(구인장의 집행지휘) 검사는 구인장 위쪽에 집행을 지휘한다는 내용을 기재하고 서명 또는 기명날인의 방법으로 영 제25조의 규정에 의한 구인장의 집행을 지휘할 수 있다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4859, '제31조의2(보호장구의 사용절차 및 방법) 보호관찰소 소속 공무원은 법 제46조의2에 따라 보호장구를 사용하기 위해서는 사전에 보호관찰소의 장의 허가를 받아 별표 2의 방법으로 사용하여야 한다. 다만, 긴급한 경우에는 사용 후 즉시 보호관찰소의 장에게 보고하여야 한다. <개정 2019.10.17>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4860, '제32조(긴급구인서) 영 제26조 및 제39조제2항에 따른 긴급구인서는 별지 제23호서식에 의한다. <개정 2009.11.27>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4861, '제33조(유치허가신청서) 영 제28조에 따른 유치허가신청은 별지 제24호서식에 따른다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4862, '제34조(유치허가장) 영 제29조 및 제39조제2항에 따른 유치허가장은 별지 제25호서식에 의한다. <개정 2009.11.27>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4863, '제35조(보호관찰을 조건으로 한 형의 선고유예의 실효 및 집행유예의 취소신청서) 영 제32조 및 제39조제2항에 따른 선고유예의 실효 및 집행유예의 취소신청은 별지 제26호서식에 의한다. <개정 2009.11.27>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4864, '제36조(가석방 및 임시퇴원의 취소신청서) 법 제48조제1항의 규정에 의한 가석방 또는 임시퇴원의 취소신청은 별지 제27호서식에 의한다. <개정 2008.6.20>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4865, '제37조(가석방 및 임시퇴원의 취소사실 통보) 심사위원회는 가석방 또는 임시퇴원이 취소된 자의 명단과 결정서등본을 관할보호관찰소의 장과 가석방 또는 임시퇴원이 취소된 자를 수용할 수용기관의 장에게 송부하여야 한다. <개정 2008.6.20>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4866, '제38조(보호처분변경신청서) 영 제35조제1항의 규정에 의한 보호처분의 변경신청은 별지 제28호서식에 의한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4867, '제39조(부정기형종료신청서) 법 제50조제1항의 규정에 의한 부정기형 종료의 신청은 별지 제29호서식에 의한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4868, '제40조(부정기형종료결정 통보) 심사위원회는 법 제50조의 규정에 의하여 부정기형종료결정을 한 때에는 그 결과를 관할보호관찰소의 장에게 통보하여야 한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4869, '제41조(임시해제 신청서) 법 제52조제1항의 규정에 의한 보호관찰의 임시해제 신청은 별지 제30호서식에 의한다. <개정 2009.11.27>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4870, '제41조의2(임시해제 취소 신청서) 법 제52조제3항에 따른 보호관찰의 임시해제 취소 신청서는 별지 제30호의2서식에 따른다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4871, '제42조(임시해제 결정통보) 심사위원회는 법 제52조제1항의 규정에 의하여 임시해제 결정을 한 때에는 그 사실을 관할보호관찰소의 장에게 통보하여야 한다. <개정 2009.11.27>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4872, '제43조(보호관찰의 정지 및 정지해제신청서) 법 제53조제1항의 규정에 의한 보호관찰의 정지결정 및 법 제53조제2항의 규정에 의한 보호관찰정지해제결정의 신청은 별지 제31호서식에 의한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4873, '제44조(보호관찰정지 및 정지해제결정통보) 심사위원회는 법 제53조제1항 또는 동조제2항의 규정에 의하여 보호관찰의 정지 또는 정지해제결정을 한 때에는 그 결과를 관할보호관찰소의 장에게 통보하여야 한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4874, '제45조(보호관찰정지자 명부) 보호관찰소의 장은 법 제53조제1항에 따라 보호관찰을 정지하는 결정을 받은 자에 대하여 별지 제32호서식의 보호관찰정지자명부에 정해진 사항을 기재해야 한다. <개정 2022.2.7>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4875, '제46조(보호관찰사건이송) 보호관찰소의 장은 보호관찰대상자가 다른 보호관찰소의 관할구역안에 거주하고 있는 사실이 확인된 때에는 별지 제33호서식의 보호관찰사건이송서에 관계기록을 첨부하여 신주거지를 관할하는 보호관찰소의 장에게 이송하여야 한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4876, '제46조의2(기부금품의 접수 영수증 등)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4877, '제47조(준용) 제21조(보호관찰사건부등)ㆍ제22조(보호관찰기간의 계산)ㆍ제23조(보호관찰담당자의 지명 및 임무) 및 제46조(보호관찰사건이송)의 규정은 법 제3조제2항의 규정에 의한 사회봉사ㆍ수강명령대상자에 대하여 이를 준용한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4878, '제48조(갱생보호시설의 설치ㆍ운영 기준) 법 제65조제3항 및 제4항에 따른 갱생보호시설의 설치 및 운영 기준은 별표 3과 같다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4879, '제49조(사무실 및 상담실) 갱생보호시설에는 일반사무를 집행하는 사무실과 갱생보호를 받을 사람(이하 "갱생보호대상자"라 한다)과의 상담을 위한 상담실을 설치하여야 한다. 다만, 상담실을 별도로 설치하지 아니하여도 사무실내에서 갱생보호대상자와 상담할 수 있는 경우 및 갱생보호의 성질상 상담이 필요하지 아니한 갱생보호를 실시하는 경우에는 상담실을 설치하지 아니할 수 있다. <개정 2014.11.19>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4880, '제50조(생활관)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4881, '제51조(갱생보호의 신청 및 조치)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4882, '제52조(숙식제공의 대상) 생활관에는 갱생보호대상자가 아닌 자를 숙식하게 할 수 없다. 다만, 갱생보호대상자의 배우자, 직계존ㆍ비속에 대하여는 1주일이내의 기간동안 숙식을 제공할 수 있다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4883, '제53조(갱생자립계획 및 생활지도)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4884, '제54조(거실의 배정) 갱생보호대상자에 대하여 거실을 배정함에 있어서는 갱생보호대상자의 연령ㆍ전과ㆍ성격 등을 고려하여야 한다. <개정 2014.11.19>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4885, '제55조(금품사용에 관한 지도 및 금품보관)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4886, '제56조(건강관리)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4887, '제57조(의복) 갱생보호대상자에게 지급하는 의복은 계절에 적합하고 사회적 체면을 유지할 수 있는 것이어야 한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4888, '제58조(식사) 생활관에서 제공하는 식사는 주간 또는 월간차림표에 의하여 조리하되, 갱생보호대상자의 건강을 유지하기에 충분한 열량과 영양성분이 포함되어 있도록 하여야 한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4889, '제59조(교양 및 여가활동)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4890, '제60조(숙식제공기간의 연장) 사업자 또는 공단은 영 제41조제2항 단서의 규정에 의하여 갱생보호대상자에 대한 숙식제공의 기간을 연장하고자 할 때에는 본인의 신청에 의하되, 자립의 정도, 계속보호의 필요성 기타 사항을 고려하여 이를 결정하여야 한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4891, '제61조 삭제 <2014.11.19>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4892, '제62조 삭제 <2014.11.19>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4893, '제63조 삭제 <2014.11.19>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4894, '제64조 삭제 <2014.11.19>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4895, '제65조(직업훈련)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4896, '제66조(취업 지원 등)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4897, '제67조(임금지급) 사업자 또는 공단은 갱생보호대상자를 부설작업장에 취업하게 한 경우에는 상당한 보수를 지급하여야 한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4898, '제68조(갱생보호사업의 허가) 법 제67조제1항의 규정에 의하여 갱생보호사업의 허가를 받고자 하는 자는 다음 각호의 사항을 기재한 허가신청서에 정관 기타 관계서류를 첨부하여 법무부장관에게 제출하여야 한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4899, '제69조 삭제 <2014.11.19>', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4900, '제70조(허가사항의 변경) 사업자가 제68조제1호부터 제3호까지, 제5호 또는 제6호의 사항을 변경하거나 정관을 변경하려는 경우에는 그 변경 사유를 명시한 변경허가신청서에 변경된 정관 및 관계 서류를 첨부하여 법무부장관의 허가를 받아야 한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4901, '제71조(사업자의 사업계획등)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4902, '제72조(공단의 사업계획등)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4903, '제73조(수익사업 승인신청등) 사업자 또는 공단은 법 제96조제1항의 규정에 의하여 수익사업 경영의 승인 또는 변경승인을 신청하는 경우에는 승인신청서에 다음의 서류를 법무부장관에게 제출하여야 한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4904, '제74조(수익사업의 요건) 사업자 또는 공단은 수익사업의 경영으로 갱생보호사업에 지장을 초래하여서는 아니되며, 그 수익을 갱생보호사업을 위하여 사용하여야 한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4905, '제75조(보고) 사업자 또는 공단은 다음 각호의 사항에 관하여 법무부장관에게 보고하여야 한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4906, '제76조(개선명령)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4907, '제77조(회계)', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4908, '제78조(장부의 비치) 사업자 및 공단은 다음의 장부를 비치하여야 한다.', 585);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4909, '제1조(목적) 이 규칙은 「전자장치 부착 등에 관한 법률」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다. <개정 2009.7.30, 2013.5.31, 2020.8.5>', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4910, '제2조 삭제 <2010.7.15>', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4911, '제3조(조사의 요청)', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4912, '제4조(부착명령청구의 방식)', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4913, '제5조(교도소장 등의 석방예정 통보) 법 제10조제2항, 제22조제5항, 제23조제3항, 영 제7조제5항, 제8조제5항, 제20조제2항 및 제27조제3항의 통보는 별지 제4호서식의 석방예정통보서에 따른다. 다만, 영 제7조제5항의 경우로서 전자장치가 부착된 사람(이하 "피부착자"라 한다)이 벌금 완납으로 석방되는 등의 긴급한 사유로 별지 제4호서식에 따른 통보가 곤란한 경우에는 유선으로 통보할 수 있다. <개정 2010.7.15, 2013.5.31, 2015.9.7, 2020.8.5>', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4914, '제6조(집행지휘)', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4915, '제7조(구금 통보 등) 영 제8조제2항, 제4항 및 제5항(영 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 통보는 각각 별지 제6호서식의 구금(구금해제 결정)통보서에 따른다. <개정 2013.5.31>', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4916, '제8조(부착명령 집행정지자의 이송 통보 등) 영 제9조(영 제21조 및 제23조에 따라 준용되는 경우를 포함한다) 및 제20조제1항의 통보는 별지 제7호서식의 부착명령 집행정지자(피부착결정자) 이송통보서에 따른다.', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4917, '제9조(일시분리 대장) 영 제10조제2항(영 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 일시분리 대장은 별지 제8호서식에 따른다.', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4918, '제10조(주거이전, 국내여행 및 출국 허가서 등)', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4919, '제10조의2(부착기간의 연장 등의 신청 등)', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4920, '제10조의3(치료기관 등의 지정)', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4921, '제10조의4(수용 중 생활실태자료 확보 등)', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4922, '제11조(수신자료 사용대장) 영 제14조(영 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 수신자료 사용대장은 별지 제22호서식에 따른다. <개정 2013.5.31>', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4923, '제11조의2(수신자료 열람 또는 조회)', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4924, '제11조의3(긴급 수신자료 열람 또는 조회)', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4925, '제11조의4(열람 또는 조회한 수신자료의 보존ㆍ폐기 등)', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4926, '제11조의5(수신자료 사용사건의 결과 통지) 영 제14조의5제1항에 따른 검사 또는 사법경찰관의 서면 통지는 별지 제34호서식에 따른다.', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4927, '제11조의6(보호관찰소의 장의 수사기관 통보 등) 영 제15조의2제2항에 따른 보호관찰소의 장의 수사기관에 대한 통보는 별지 제35호서식에 따른다.', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4928, '제11조의7(영상정보 열람사실의 통지)', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4929, '제12조(임시해제 신청서 등) 영 제16조제1항의 임시해제 신청(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다) 및 영 제18조제1항의 임시해제 취소 신청(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)은 각각 별지 제36호서식의 부착명령 임시해제(임시해제 취소) 신청서에 따른다. <개정 2013.5.31, 2020.8.5>', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4930, '제12조의2(임시해제의 심사ㆍ결정기준) 「보호관찰 등에 관한 법률」 제5조에 따른 보호관찰 심사위원회가 법 제18조제1항ㆍ제4항ㆍ제5항(법 제21조의8, 제27조 및 제31조에 따라 준용되는 경우를 포함한다) 및 영 제17조제1항(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)에 따라 임시해제를 심사ㆍ결정할 때에는 피부착자 또는 보호관찰대상자의 연령, 건강상태, 가족관계, 가정환경, 범죄경력, 집행기간, 준수사항의 이행정도, 재범위험성 평가결과 및 그 밖에 필요한 사항을 고려해야 한다. <개정 2020.8.5>', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4931, '제13조(결정서) 법 제18조제4항ㆍ제5항(법 제21조의8, 제27조 및 제31조에 따라 준용되는 경우를 포함한다) 및 영 제17조(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)에 따른 임시해제 결정과 법 제19조제1항(법 제21조의8, 제27조 및 제31조에 따라 준용되는 경우를 포함한다) 및 영 제18조제2항(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)에 따른 임시해제 취소 결정은 각각 별지 제37호서식의 부착명령(보호관찰명령) 임시해제(임시해제 취소) 결정서에 따른다. <개정 2020.8.5>', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4932, '제13조의2(보호관찰명령 청구의 방식)', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4933, '제13조의3(집행지휘)', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4934, '제13조의4(보호관찰기간의 연장 등 신청) 법 제21조의7에 따른 보호관찰소의 장의 보호관찰기간의 연장 또는 준수사항의 추가ㆍ변경ㆍ삭제의 신청은 별지 제41호서식에 따르고, 법 제21조의7에 따른 검사의 보호관찰기간의 연장 또는 준수사항의 추가ㆍ변경ㆍ삭제의 청구는 별지 제42호서식에 따른다.', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4935, '제13조의5(수용 중 생활실태 자료 확보 등) 법 제21조의8에 따라 준용되는 법 제15조제3항에 따른 보호관찰명령 집행을 위한 수용 중 생활실태 자료 확보 등에 관하여는 제10조의4를 준용한다.', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4936, '제14조(전자장치 부착대상자 통보 등)', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4937, '제14조의2(조사의 의뢰) 법 제31조의2제2항 및 영 제23조의2제1항에 따른 조사의 의뢰는 별지 제44호의2서식에 따른다.', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4938, '제14조의3(보석 피고인 신고서) 법 제31조의3제2항 및 영 제23조의4에 따른 신고서는 별지 제44호의3서식에 따른다.', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4939, '제14조의4(보석조건 이행 상황 통지) 법 제31조의4제1항 및 영 제23조의6에 따른 보석조건 이행 상황의 통지는 별지 제44호의4서식에 따른다.', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4940, '제14조의5(보석조건 위반 통지) 법 제31조의4제2항 및 영 제23조의7에 따른 보석조건 위반 통지는 별지 제44호의5서식에 따른다.', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4941, '제14조의6(스토킹행위자 신고서) 법 제31조의6제2항 및 영 제23조의11제1항에 따른 신고는 별지 제44호의6서식에 따른다.', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4942, '제14조의7(전자장치 부착 사실의 통지) 법 제31조의6제3항 각 호 외의 부분 및 영 제23조의13제1항에 따른 전자장치 부착 사실의 통지는 별지 제44호의7서식에 따른다.', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4943, '제14조의8(피해자 관련 사항의 통지) 법 제31조의6제3항 및 영 제23조의13제2항에 따른 피해자 관련 사항의 통지는 별지 제44호의8서식에 따른다.', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4944, '제14조의9(잠정조치 결정의 효력 상실 통지) 법 제31조의6제6항 또는 영 제23조의16에 따른 잠정조치 결정의 효력 상실 통지는 별지 제44호의9서식에 따른다.', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4945, '제14조의10(스토킹행위자 수신자료 사용대장) 영 제23조의17에 따른 스토킹행위자 수신자료 사용대장은 별지 제44호의10서식에 따른다.', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4946, '제15조(출소자등 통보서) 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제1호, 제3항제1호 및 영 제24조에 따른 출소자 등의 인적사항 등 통보는 별지 제45호서식의 출소자등 통보서에 따른다. <개정 2013.5.31>', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4947, '제16조(출석요구서) 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제5호에 따른 출석 요구는 별지 제46호서식의 출석요구서에 따른다. <개정 2013.5.31>', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4948, '제17조(구인영장 청구서 등)', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4949, '제18조(구인영장)', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4950, '제19조(부착명령 집행장)', 586);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4951, '제1조(목적) 이 규칙은 「성폭력범죄자의 성충동 약물치료에 관한 법률」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4952, '제2조(정신과 전문의의 진단 및 감정) 「성폭력범죄자의 성충동 약물치료에 관한 법률」(이하 "법"이라 한다) 제4조제2항 및 제22조제2항제5호 전단에 따라 정신과 전문의에게 진단이나 감정을 요청하는 경우에는 별지 제1호서식에 따른다. 이 경우 진단 및 감정사항에는 다음 각 호의 내용이 포함되어야 한다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4953, '제3조(조사의 요청)', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4954, '제4조(치료명령 청구의 방식)', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4955, '제5조(치료명령 청구사건의 보고)', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4956, '제5조의2(치료명령의 집행 면제 신청서) 법 제8조의2제1항부터 제3항까지 및 영 제4조의2에 따른 치료명령의 집행 면제 신청은 별지 제4호의2 서식에 따른다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4957, '제6조(교도소장 등의 석방 예정 통보) 법 제11조제2항ㆍ제22조제12항 및 영 제10조제3항에 따른 석방 예정 통보는 별지 제5호서식에 따른다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4958, '제7조(집행지휘)', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4959, '제8조(치료명령 집행을 위한 통지) 보호관찰관은 법 제13조 및 영 제6조에 따른 집행지휘를 받거나 영 제12조제1항제1호에 따라 치료명령의 잔여기간을 집행하여야 할 사유를 확인한 경우에는 지체 없이 치료명령을 받은 사람을 수용하고 있는 교도소ㆍ소년교도소ㆍ구치소ㆍ군교도소(이하 "수용시설"이라 한다)의 장에게 별지 제7호서식에 따라 통지하여야 한다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4960, '제9조(약물치료에 관한 설명) 법 제14조제2항 및 영 제7조제2항에 따른 약물치료에 관한 설명은 별지 제8호서식에 따른다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4961, '제10조(담당 보호관찰관의 지명 등)', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4962, '제11조(치료명령을 받은 사람의 이송 통보) 영 제10조제2항 및 제12조제1항제1호에 따른 치료명령을 받은 사람의 이송 통보는 별지 제10호서식에 따른다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4963, '제12조(약물 투여 일시 중단 대장) 보호관찰관은 영 제11조제2항에 따라 약물 투여를 일시 중단하는 경우에는 별지 제11호서식의 약물 투여 일시 중단 대장을 작성하여야 한다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4964, '제13조(약물 투여 일시 중단의 승인 신청) 영 제11조제3항에 따른 약물 투여 일시 중단의 승인 신청은 별지 제12호서식에 따른다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4965, '제14조(약물 투여 일시 중단의 승인) 영 제11조제4항에 따른 심사위원회의 승인 결정은 별지 제13호서식에 따른다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4966, '제15조(치료명령을 받은 사람의 부작용 치료 내용 등 보고) 영 제11조제5항에 따른 부작용 치료 내용 등의 보고는 별지 제14호서식에 따른다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4967, '제16조(약물 투여 재개 결정서) 영 제11조제6항에 따른 약물 투여 재개 결정은 별지 제15호서식에 따른다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4968, '제17조(약물치료 집행정지 대장) 보호관찰관은 법 제14조제4항에 따라 약물치료의 집행이 정지되는 경우에는 별지 제16호서식의 약물치료 집행정지 대장을 작성하여야 한다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4969, '제18조(구금해제 통보) 법 제14조제5항제1호 및 영 제12조제4항에 따른 구금해제 통보는 별지 제17호서식에 따른다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4970, '제19조(호르몬 수치 등 검사 의뢰) 영 제13조제3항에 따른 호르몬 수치 등 검사 의뢰는 별지 제18호서식에 따른다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4971, '제20조(주거 이전 신고 등)', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4972, '제21조(치료기간 연장 등의 신청)', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4973, '제22조(치료명령 가해제 신청 등) 법 제17조제1항 및 영 제16조제1항에 따른 가해제 신청, 법 제19조제1항 전단 및 영 제18조제1항에 따른 가해제 취소 신청은 별지 제26호서식에 따른다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4974, '제23조(치료명령 가해제 결정 등) 법 제18조제4항 및 제5항에 따른 가해제 결정, 법 제19조제1항 후단에 따른 가해제 취소 결정은 별지 제27호서식에 따른다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4975, '제24조(약물치료 동의 여부 확인) 법 제22조제2항제1호 및 영 제19조, 법 제22조제2항제5호 및 영 제22조제1항에 따른 동의 여부 확인은 별지 제28호서식에 따른다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4976, '제25조(성폭력 수형자의 약물치료 동의 사실 등 통보) 법 제22조제2항제2호 및 영 제20조에 따른 약물치료 동의 사실 등의 통보는 별지 제29호서식에 따른다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4977, '제26조(가석방 적격심사 신청) 영 제24조제1항에 따라 치료명령 결정 사실을 통보받은 수용시설의 장은 통보받은 날부터 1개월 이내에 「형의 집행 및 수용자의 처우에 관한 법률」 제121조에 따라 가석방 적격심사를 신청하여야 한다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4978, '제27조(치료비용 납부 명령서) 영 제26조제1항에 따른 치료비용 납부명령은 별지 제30호서식에 따른다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4979, '제28조(치료비용 국가 부담 신청서) 영 제26조제3항에 따른 치료비용 국가 부담 신청서는 별지 제31호서식에 따른다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4980, '제29조(자료 제출 동의 등)', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4981, '제30조(치료감호심의위원회의 진단 및 감정 의뢰) 영 제27조제1항 및 제2항에 따른 치료감호심의위원회의 진단 및 감정 의뢰는 별지 제34호서식에 따른다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4982, '제31조(치료명령 결정서 등)', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4983, '제32조(준용) 법 제29조 및 영 제29조에 따라 다른 규정을 준용하는 경우에 필요한 서식은 각각 해당 규정에서 정한 서식에 따른다.', 587);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4984, '제1조(목적) 이 규칙은 「보호소년 등의 처우에 관한 법률」 제17조제3항에 따라 보호소년, 위탁소년 또는 유치소년에게 급여 또는 대여하는 물품에 관하여 필요한 사항을 정함을 목적으로 한다. <개정 2016.10.31>', 588);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4985, '제2조(주ㆍ부식의 기준열량) 보호소년, 위탁소년 또는 유치소년(이하 "보호소년등"이라 한다) 1명당 한 끼에 급여하는 주식 및 부식의 열량은 900킬로칼로리(여성은 667킬로칼로리) 이상으로 한다. <개정 2016.10.31, 2019.3.27>', 588);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4986, '제3조(주식의 급여)', 588);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4987, '제4조(부식의 급여)', 588);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4988, '제5조(특별급식)', 588);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4989, '제6조(주식의 확보) 원장은 보호소년등에 대한 원활한 급식을 위하여 평균 급식 인원의 1개월분에 상당하는 주식을 항상 확보하고 있어야 한다.', 588);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4990, '제7조(피복 및 침구 등의 급여)', 588);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4991, '제8조(피복등의 착용 등)', 588);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4992, '제9조(교과서 및 학용품의 급여)', 588);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4993, '제10조(생활용품 등의 급여 또는 대여)', 588);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4994, '제11조(대여품의 회수) 원장은 보호소년등이 퇴원, 임시퇴원, 그 밖의 사유로 출원(出院)할 때에는 이들에게 대여한 피복등 및 그 밖의 물품을 회수하여야 한다. 다만, 회수하기 어려운 특별한 사정이 있을 때에는 그러하지 아니하다.', 588);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4995, '제1조(목적) 이 법은 사업 또는 사업장, 공중이용시설 및 공중교통수단을 운영하거나 인체에 해로운 원료나 제조물을 취급하면서 안전ㆍ보건 조치의무를 위반하여 인명피해를 발생하게 한 사업주, 경영책임자, 공무원 및 법인의 처벌 등을 규정함으로써 중대재해를 예방하고 시민과 종사자의 생명과 신체를 보호함을 목적으로 한다.', 589);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4996, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다.', 589);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4997, '제3조(적용범위) 상시 근로자가 5명 미만인 사업 또는 사업장의 사업주(개인사업주에 한정한다. 이하 같다) 또는 경영책임자등에게는 이 장의 규정을 적용하지 아니한다.', 590);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4998, '제4조(사업주와 경영책임자등의 안전 및 보건 확보의무)', 590);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (4999, '제5조(도급, 용역, 위탁 등 관계에서의 안전 및 보건 확보의무) 사업주 또는 경영책임자등은 사업주나 법인 또는 기관이 제3자에게 도급,  용역, 위탁 등을 행한 경우에는 제3자의 종사자에게 중대산업재해가 발생하지 아니하도록 제4조의 조치를 하여야 한다. 다만, 사업주나 법인 또는 기관이 그 시설, 장비, 장소 등에 대하여 실질적으로 지배ㆍ운영ㆍ관리하는 책임이 있는 경우에 한정한다.', 590);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5000, '제6조(중대산업재해 사업주와 경영책임자등의 처벌)', 590);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5001, '제7조(중대산업재해의 양벌규정) 법인 또는 기관의 경영책임자등이 그 법인 또는 기관의 업무에 관하여 제6조에 해당하는 위반행위를 하면 그 행위자를 벌하는 외에 그 법인 또는 기관에 다음 각 호의 구분에 따른 벌금형을 과(科)한다. 다만, 법인 또는 기관이 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다.', 590);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5002, '제8조(안전보건교육의 수강)', 590);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5003, '제9조(사업주와 경영책임자등의 안전 및 보건 확보의무)', 591);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5004, '제10조(중대시민재해 사업주와 경영책임자등의 처벌)', 591);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5005, '제11조(중대시민재해의 양벌규정) 법인 또는 기관의 경영책임자등이 그 법인 또는 기관의 업무에 관하여 제10조에 해당하는 위반행위를 하면 그 행위자를 벌하는 외에 그 법인 또는 기관에게 다음 각 호의 구분에 따른 벌금형을 과(科)한다. 다만, 법인 또는 기관이 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다.', 591);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5006, '제12조(형 확정 사실의 통보) 법무부장관은 제6조, 제7조, 제10조 또는 제11조에 따른 범죄의 형이 확정되면 그 범죄사실을 관계 행정기관의 장에게 통보하여야 한다.', 592);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5007, '제13조(중대산업재해 발생사실 공표)', 592);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5008, '제14조(심리절차에 관한 특례)', 592);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5009, '제15조(손해배상의 책임)', 592);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5010, '', 592);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5011, '제1조(목적) 이 영은 「중대재해 처벌 등에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 593);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5012, '제2조(직업성 질병자) 「중대재해 처벌 등에 관한 법률」(이하 "법"이라 한다) 제2조제2호다목에서 "대통령령으로 정하는 직업성 질병자"란 별표 1에서 정하는 직업성 질병에 걸린 사람을 말한다.', 593);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5013, '제3조(공중이용시설) 법 제2조제4호 각 목 외의 부분 본문에서 "대통령령으로 정하는 시설"이란 다음 각 호의 시설을 말한다. <개정 2025.8.26>', 593);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5014, '제4조(안전보건관리체계의 구축 및 이행 조치) 법 제4조제1항제1호에 따른 조치의 구체적인 사항은 다음 각 호와 같다.', 594);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5015, '제5조(안전ㆍ보건 관계 법령에 따른 의무이행에 필요한 관리상의 조치)', 594);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5016, '제6조(안전보건교육의 실시 등)', 594);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5017, '제7조(과태료의 부과기준) 법 제8조제2항에 따른 과태료의 부과기준은 별표 4와 같다.', 594);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5018, '제8조(원료ㆍ제조물 관련 안전보건관리체계의 구축 및 이행 조치) 법 제9조제1항제1호에 따른 조치의 구체적인 사항은 다음 각 호와 같다.', 595);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5019, '제9조(원료ㆍ제조물 관련 안전ㆍ보건 관계 법령에 따른 의무이행에 필요한 관리상의 조치)', 595);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5020, '제10조(공중이용시설ㆍ공중교통수단 관련 안전보건관리체계 구축 및 이행에 관한 조치) 법 제9조제2항제1호에 따른 조치의 구체적인 사항은 다음 각 호와 같다.', 595);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5021, '제11조(공중이용시설ㆍ공중교통수단 관련 안전ㆍ보건 관계 법령에 따른 의무이행에 필요한 관리상의 조치)', 595);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5022, '제12조(중대산업재해 발생사실의 공표)', 596);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5023, '제13조(조치 등의 이행사항에 관한 서면의 보관) 사업주 또는 경영책임자등(「소상공인기본법」 제2조에 따른 소상공인은 제외한다)은 제4조, 제5조 및 제8조부터 제11조까지의 규정에 따른 조치 등의 이행에 관한 사항을 서면(「전자문서 및 전자거래 기본법」 제2조제1호에 따른 전자문서를 포함한다)으로 작성하여 그 조치 등을 이행한 날부터 5년간 보관해야 한다.', 596);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5024, '제1조(목적) 이 영은 「특정경제범죄 가중처벌 등에 관한 법률」에서 위임된 사항과 그 시행에 관하여 필요한 사항을 정함을 목적으로 한다. <개정 2009.7.7>', 597);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5025, '제2조(대출등의 범위) 「특정경제범죄 가중처벌 등에 관한 법률」(이하 "법"이라 한다) 제2조제3호에서 "대통령령으로 정하는 것"이란 다음 각 호의 어느 하나에 해당하는 것을 말한다. <개정 2009.7.7, 2019.5.7>', 597);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5026, '제3조(감독기관의 감독업무에 종사하는 사람의 범위) 법 제12조제2항에 따른 감독기관의 감독업무에 종사하는 사람은 다음 각 호의 어느 하나에 해당하는 기관의 임ㆍ직원으로서 소관 금융회사등에 대한 감사 또는 검사의 직무(일시적인 감사 또는 검사의 직무의 경우를 포함한다)에 종사하는 사람 및 그 직무를 관장하는 상급자와 해당 감독기관의 장으로 한다. <개정 1998ㆍ4ㆍ1, 2019.5.7>', 597);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5027, '제4조 삭제 <2009.7.7>', 597);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5028, '제5조 삭제 <2009.7.7>', 597);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5029, '제6조 삭제 <2009.7.7>', 597);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5030, '제7조 삭제 <2009.7.7>', 597);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5031, '제8조 삭제 <2009.7.7>', 597);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5032, '제9조(수사기관의 통보등)', 597);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5033, '제10조(취업제한대상인 기관 및 기업체의 범위)', 597);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5034, '제11조(허가등이 금지되는 관허업의 범위) 법 제14조제2항에서 "대통령령으로 정하는 관허업"이란 특정한 사업ㆍ영업 또는 행위를 업으로 하기 위하여 행정기관으로부터 허가ㆍ인가ㆍ면허ㆍ등록ㆍ지정ㆍ승인 및 특허(이하 "허가등"이라 한다)를 받아야 할 대상으로서 그 처분청이 중앙행정기관의 장, 특별시장, 광역시장, 특별자치시장, 도지사 또는 특별자치도지사인 경우(법령에 따라 그 허가등의 권한이 하부기관 또는 다른 기관에 위임 또는 위탁된 경우를 포함한다)의 해당 사업ㆍ영업 또는 행위를 말한다. <개정 2019.5.7>', 597);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5035, '제12조(취업제한사실등의 통지) 법무부장관은 법 제3조ㆍ법 제4조제2항(미수범을 포함한다)ㆍ법 제5조제4항 또는 법 제8조의 죄를 범한 사람에 대한 재판결과를 항상 파악하여 그에 대한 유죄판결이 확정된 때에는 지체 없이 법 제14조제1항 및 제2항에 따른 취업제한 및 허가등 금지사실과 그 대상의 범위를 그 판결이 확정된 사람에게 통지하여야 한다. <개정 2009.7.7, 2019.5.7>', 597);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5036, '제13조(취업승인신청)', 597);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5037, '제14조(관허업의 허가등 승인신청)', 597);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5038, '제15조(민감정보 및 고유식별정보 등의 처리)', 597);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5039, '제1조(목적) 이 영은 「특정범죄 가중처벌 등에 관한 법률」 제4조에 따라 뇌물죄가 적용되는 기관 또는 단체 및 간부직원의 범위를 규정함을 목적으로 한다.', 598);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5040, '제2조(기관 또는 단체의 범위) 「특정범죄 가중처벌 등에 관한 법률」(이하 "법"이라 한다) 제4조제1항에 따른 기관 또는 단체의 범위는 다음과 같다. <개정 2012.1.25, 2015.7.24, 2016.5.31, 2016.8.31, 2019.1.15, 2019.4.2, 2020.9.10, 2020.12.8, 2021.8.31>', 598);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5041, '제3조(간부직원의 범위) 법 제4조제2항에 따른 기관 또는 단체의 간부직원의 범위는 다음 각 호와 같다. 다만, 다른 법령에 따라 공무원 또는 공무원에 준하는 신분을 가지는 경우에는 그 법령의 적용을 배제하지 아니한다.', 598);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5042, '제1조(목적) 이 영은 특정범죄신고자등보호법에서 위임된 사항과 그 시행에 관하여 필요한 사항을 규정함을 목적으로 한다.', 599);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5043, '제2조(범죄신고자등보좌인의 자격) 특정범죄신고자등보호법(이하 "법"이라 한다)제6조제2항에서 "대통령령이 정하는 자"라 함은 다음 각호의 1에 해당하는 자를 말한다.', 599);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5044, '제3조(보좌인에 대한 실비지급 등)', 599);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5045, '제4조(신원관리카드의 기재사항)', 599);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5046, '제5조(신원관리카드의 관리)', 599);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5047, '제6조(신변안전조치의 요청 등)', 599);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5048, '제7조(신변안전조치의 종류) 법 제13조제1항의 규정에 의한 신변안전조치의 종류는 다음 각호의 1과 같다.', 599);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5049, '제8조(신변안전조치 이행통보 등)', 599);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5050, '제9조(구조금의 산정)', 599);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5051, '제10조(구조금의 신청) 범죄신고자등, 그 법정대리인 또는 친족등이 법 제14조의규정에 의한 구조금을 지급받고자 하는 때에는 법 제2조제2호의 규정에 의한 범죄신고등이 이루어진 지역을 관할하는 지방검찰청 범죄신고자등구조심의회(이하"심의회"라 한다)에 이를 신청하여야 한다. 이 경우 법 제7조제4항의 규정에 의하여 조서등에 성명을 기재하지 아니한 범죄신고자등은 가명으로 이를 신청할 수 있다.', 599);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5052, '제11조(구조결정)', 599);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5053, '제12조(심의회의 관할) 심의회의 관할구역은 심의회가 설치된 지방검찰청의관할구역(지청이 있는 경우에는 지청의 관할구역을 포함한다)으로 한다.', 599);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5054, '제13조(심의회의 구성) 심의회는 당해 심의회가 설치된 지방검찰청의 차장검사를 위원장으로 하고, 당해 지방검찰청 소속 공무원 및 법관의 자격을 가진 자중에서 법무부장관이 임명 또는 위촉하는 위원 4인으로 구성한다.', 599);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5055, '제14조(위원장)', 599);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5056, '제15조(심의회의 의사)', 599);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5057, '제16조(사무직원)', 599);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5058, '제17조(법무부장관의 지휘ㆍ감독)', 599);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5059, '제18조(결정 및 통지)', 599);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5060, '제19조(구조금의 지급청구)', 599);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5061, '제20조(서식 등) 법 및 이 영의 시행에 관하여 필요한 서식 등에 관한 사항은 법무부령으로 정한다.', 599);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5062, '제1조(목적) 이 규칙은 「부패재산의 몰수 및 회복에 관한 특례법」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 600);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5063, '제2조(비용) 「부패재산의 몰수 및 회복에 관한 특례법 시행령」(이하 "영"이라 한다) 제2조제4호에서 "통지ㆍ공고 등 법무부령으로 정하는 환부절차에 드는 비용"이란 다음 각 호의 비용을 말한다.', 600);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5064, '제3조(통지)', 600);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5065, '제4조(범죄피해재산 환부청구의 방법)', 600);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5066, '제5조(청구사항의 변경신고)', 600);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5067, '제6조(검사의 회복대상재산 환부결정)', 600);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5068, '제7조(범죄피해재산 환부관리부 작성) 범죄피해재산 환부절차를 담당하는 검사는 청구인에게 회복대상재산을 환부한 때에는 별지 제6호서식의 범죄피해재산 환부관리부를 작성하여 소속 검찰청에 보관해야 한다.', 600);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5069, '제8조(청구인의 이의신청)', 600);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5070, '제9조(이의신청에 대한 결정)', 600);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5071, '제10조(범죄피해재산환부심의회의 운영)', 600);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5072, '제11조(위원의 제척ㆍ기피ㆍ회피)', 600);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5073, '제12조(위원의 해촉) 각 검찰청의 장은 영 제11조제5항에 따라 위촉된 위원이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 위원을 해촉(解觸)할 수 있다.', 600);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5074, '제1조(목적) 이 법은 사법의 민주적 정당성과 신뢰를 높이기 위하여 국민이 형사재판에 참여하는 제도를 시행함에 있어서 참여에 따른 권한과 책임을 명확히 하고, 재판절차의 특례와 그 밖에 필요한 사항에 관하여 규정함을 목적으로 한다.', 601);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5075, '제2조(정의) 이 법에서 사용하는 용어의 정의는 다음과 같다.', 601);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5076, '제3조(국민의 권리와 의무)', 601);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5077, '제4조(다른 법령과의 관계) 국민참여재판에 관하여 이 법에 특별한 규정이 없는 때에는 「법원조직법」ㆍ「형사소송법」 등 다른 법령을 적용한다.', 601);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5078, '제5조(대상사건)', 602);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5079, '제6조(공소사실의 변경 등)', 602);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5080, '제7조(필요적 국선변호) 이 법에 따른 국민참여재판에 관하여 변호인이 없는 때에는 법원은 직권으로 변호인을 선정하여야 한다.', 602);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5081, '제8조(피고인 의사의 확인)', 602);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5082, '제9조(배제결정)', 602);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5083, '제10조(지방법원 지원 관할 사건의 특례)', 602);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5084, '제11조(통상절차 회부)', 602);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5085, '제12조(배심원의 권한과 의무)', 604);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5086, '제13조(배심원의 수)', 604);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5087, '제14조(예비배심원)', 604);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5088, '제15조(여비ㆍ일당 등) 대법원규칙으로 정하는 바에 따라 배심원ㆍ예비배심원 및 배심원후보자에게 여비ㆍ일당 등을 지급한다.', 604);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5089, '제16조(배심원의 자격) 배심원은 만 20세 이상의 대한민국 국민 중에서 이 법으로 정하는 바에 따라 선정된다.', 605);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5090, '제17조(결격사유) 다음 각 호의 어느 하나에 해당하는 사람은 배심원으로 선정될 수 없다. <개정 2016.1.19>', 605);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5091, '제18조(직업 등에 따른 제외사유) 다음 각 호의 어느 하나에 해당하는 사람을 배심원으로 선정하여서는 아니 된다. <개정 2016.5.29>', 605);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5092, '제19조(제척사유) 다음 각 호의 어느 하나에 해당하는 사람은 당해 사건의 배심원으로 선정될 수 없다.', 605);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5093, '제20조(면제사유) 법원은 직권 또는 신청에 따라 다음 각 호의 어느 하나에 해당하는 사람에 대하여 배심원 직무의 수행을 면제할 수 있다.', 605);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5094, '제21조(보고ㆍ서류송부 요구) 지방법원장 또는 재판장은 국가, 지방자치단체, 공공단체, 그 밖의 법인ㆍ단체에 배심원후보자ㆍ배심원ㆍ예비배심원의 선정 또는 해임에 관한 판단을 위하여 필요한 사항의 보고 또는 그 보관서류의 송부를 요구할 수 있다.', 605);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5095, '제22조(배심원후보예정자명부의 작성)', 606);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5096, '제23조(배심원후보자의 결정 및 출석통지)', 606);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5097, '제24조(선정기일의 진행)', 606);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5098, '제25조(질문표)', 606);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5099, '제26조(후보자명부 송부 등)', 606);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5100, '제27조(선정기일의 참여자)', 606);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5101, '제28조(배심원후보자에 대한 질문과 기피신청)', 606);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5102, '제29조(이의신청)', 606);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5103, '제30조(무이유부기피신청)', 606);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5104, '제31조(선정결정 및 불선정결정)', 606);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5105, '제32조(배심원의 해임)', 607);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5106, '제33조(배심원의 사임)', 607);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5107, '제34조(배심원의 추가선정 등)', 607);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5108, '제35조(배심원 등의 임무 종료) 배심원과 예비배심원의 임무는 다음 각 호의 어느 하나에 해당하면 종료한다.', 607);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5109, '제36조(공판준비절차)', 609);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5110, '제37조(공판준비기일)', 609);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5111, '제38조(공판기일의 통지) 공판기일은 배심원과 예비배심원에게 통지하여야 한다.', 610);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5112, '제39조(소송관계인의 좌석)', 610);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5113, '제40조(공판정에서의 속기ㆍ녹취)', 610);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5114, '제41조(배심원의 절차상 권리와 의무)', 610);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5115, '제42조(선서 등)', 610);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5116, '제43조(간이공판절차 규정의 배제) 국민참여재판에는 「형사소송법」 제286조의2를 적용하지 아니한다.', 610);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5117, '제44조(배심원의 증거능력 판단 배제) 배심원 또는 예비배심원은 법원의 증거능력에 관한 심리에 관여할 수 없다.', 610);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5118, '제45조(공판절차의 갱신)', 610);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5119, '제46조(재판장의 설명ㆍ평의ㆍ평결ㆍ토의 등)', 611);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5120, '제47조(평의 등의 비밀) 배심원은 평의ㆍ평결 및 토의 과정에서 알게 된 판사 및 배심원 각자의 의견과 그 분포 등을 누설하여서는 아니 된다.', 611);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5121, '제48조(판결선고기일)', 611);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5122, '제49조(판결서의 기재사항)', 611);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5123, '제50조(불이익취급의 금지) 누구든지 배심원ㆍ예비배심원 또는 배심원후보자인 사실을 이유로 해고하거나 그 밖의 불이익한 처우를 하여서는 아니 된다.', 612);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5124, '제51조(배심원 등에 대한 접촉의 규제)', 612);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5125, '제52조(배심원 등의 개인정보 공개금지)', 612);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5126, '제53조(배심원 등에 대한 신변보호조치)', 612);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5127, '제54조(사법참여기획단)', 613);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5128, '제55조(국민사법참여위원회)', 613);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5129, '제56조(배심원 등에 대한 청탁죄)', 614);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5130, '제57조(배심원 등에 대한 위협죄)', 614);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5131, '제58조(배심원 등에 의한 비밀누설죄)', 614);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5132, '제59조(배심원 등의 금품 수수 등)', 614);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5133, '제60조(배심원후보자의 불출석 등에 대한 과태료)', 614);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5134, '제1조(목적) 이 규칙은 「교도작업의 운영 및 특별회계에 관한 법률」 및 「교도작업의 운영 및 특별회계에 관한 법률 시행령」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 615);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5135, '제2조(다른 법령과의 관계) 「교도작업의 운영 및 특별회계에 관한 법률」(이하 "법"이라 한다)에 따른 교도작업의 운영 및 교도작업특별회계(이하 "특별회계"라 한다)에 관하여 다른 법령에 특별한 규정이 있는 경우를 제외하고는 이 규칙에서 정하는 바에 따른다.', 615);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5136, '제3조(생산공급계획의 보고) 교정시설의 장(이하 "소장"이라 한다)이 「교도작업의 운영 및 특별회계에 관한 법률 시행령」(이하 "영"이라 한다) 제3조에 따라 법무부장관에게 보고하는 다음 연도의 생산공급계획서에는 다음 각 호의 사항이 포함되어야 한다.', 615);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5137, '제4조(교도작업 참여 신청 등)', 615);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5138, '제5조(단기계약)', 615);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5139, '제6조(교도작업의 종류)', 615);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5140, '제7조(계약서 작성요령) 특별회계의 세입ㆍ세출의 원인이 되는 계약을 담당하는 공무원(이하 "계약담당자"라 한다)은 계약서를 작성할 때에는 다음 각 호의 사항을 유의하여야 한다.', 615);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5141, '제8조(낙찰가격과 예정가격 명세의 재조정) 계약의 목적을 구성하는 내용이 두 종류 이상일 경우에는 낙찰자 또는 계약의 상대방으로 하여금 낙찰총액에 부합되는 명세서를 제출하게 하여, 그 명세서상 금액과 예정가격의 명세금액을 낙찰액과 예정가격과의 비율에 해당하는 금액의 범위 내로 조정한 금액을 계약금액의 명세로 하여야 한다.', 615);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5142, '제9조(수의계약의 절차)', 615);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5143, '제10조(계약불이행) 계약담당자는 상대방의 계약불이행으로 인한 손해배상금ㆍ지체상금(遲滯償金) 또는 계약보증금 등을 지출액과 상계(相計)하여야 할 때에는 그 관계 서류와 산출계산명세서를 관계 지출관 또는 출납공무원에게 제출하여야 한다.', 615);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5144, '제1조(목적) 이 규칙은 즉결심판에 관한 절차법(이하 "법"이라 한다) 제8조의2제3항의 규정에 의하여 불출석심판의 청구와 그 허가절차 기타 필요한 사항을 규정함을 목적으로 한다. <개정 2014.4.3>', 616);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5145, '제2조(불출석심판을 청구할 수 있는 자의 범위) 법 제8조의2제2항의 규정에 의한 불출석심판청구는 다음 각호의 1에 해당하는 자에 한하여 이를 할 수 있다. <개정 2000.6.3, 2003.5.29, 2014.4.3>', 616);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5146, '제3조(불출석심판청구의 방식등)', 616);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5147, '제4조(허부의 결정등)', 616);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5148, '제5조(허부의 결정에 따른 조치)', 616);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5149, '제1조(목적) 이 영은 「부정수표 단속법」을 시행하는 데 필요한 사항을 규정함을 목적으로 한다.', 617);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5150, '제2조(금융기관의 범위 등)', 617);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5151, '제1조 (목적) 이 규칙은 범죄인인도법(이하 "법"이라 한다)의 규정에 의한 법원의 인도심사절차 및 인도구속영장, 긴급인도구속영장의 발부절차등에 관하여 필요한 사항을 규정함을 목적으로 한다.', 618);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5152, '제2조 (정의)', 618);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5153, '제3조 (준용규정) 법원직원의 제척, 기피, 회피, 서류 및 송달에 관한 사항은 법 또는 이 규칙에 특별한 규정이 있는 경우를 제외하고는, 그 성질에 반하지 아니하는 범위안에서 형사소송법 및 형사소송규칙을 준용한다.', 618);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5154, '제4조 (번역문의 첨부) 외국어로 기재된 서면에는 그 번역문을 첨부하여야 한다.', 618);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5155, '제5조 (인도심사청구서의 기재요건)', 619);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5156, '제6조 (구속관련사항의 기재)', 619);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5157, '제7조 (자료제출명령) 재판장은 검사, 범죄인 또는 그 변호인에 대하여 인도심사에 필요한 자료의 제출을 명할 수 있다.', 619);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5158, '제8조 (통지의무) 검사는 인도심사청구후 다음 각호의 사유가 발생한 때에는 지체없이 법원에 서면으로 그 사실을 통지하여야 한다.', 619);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5159, '제9조 (변호인의 선임)', 619);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5160, '제10조 (준용규정) 제9조 및 법 제14조제3항의 규정에 의하여 범죄인등이 변호인을 선임하는 경우 또는 법 제14조제4항의 규정에 의하여 법원이 국선변호인을 선정하는 경우에, 변호인의 자격, 선정의 절차 및 변호인의 권한에 관하여는, 성질에 반하지 아니하는 범위안에서 형사소송법 제31조 본문, 제34조 내지 제36조 및 형사소송규칙 제1편 제4장을 준용한다.', 619);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5161, '제11조 (준용규정) 법 제14조제6항에 의하여 증인을 신문하거나 감정을 명하는 경우에는, 그 성질에 반하지 아니하는 범위안에서 형사소송규칙 제1편 제12장 및 제13장을 준용한다.', 619);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5162, '제12조 (심문기일)', 619);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5163, '제13조 (절차의 공개) 심문기일에서 절차는 이를 공개한다. 다만 국가의 안전보장ㆍ안녕질서 또는 선량한 풍속을 해할 염려가 있는 때에는 법원은 결정으로 이를 공개하지 아니할 수 있다.', 619);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5164, '제14조 (검사등의 신문권) 심문기일에 출석한 검사 또는 범죄인의 변호인은 법원의 신문이 끝난후 범죄인, 증인 및 감정인등을 신문할 수 있다.', 619);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5165, '제15조 (청구국대리인등의 참여) 청구국의 공무원 또는 그 대리인이 심문기일에 참여하거나 의견을 진술함에는 법원의 허가를 얻어야 한다.', 619);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5166, '제16조 (법원사무관등의 참여) 심문기일에는 법원사무관, 법원주사 또는 법원주사보를 참여시켜 조서를 작성하게 하여야 한다.', 619);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5167, '제17조 (결정서의 서명날인) 법 및 이 규칙에 의하여 작성되는 결정서에는 관여한 법관이 서명날인하여야 한다.', 619);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5168, '제18조 (결정주문의 통지) 법 제15조제3항의 규정에 의한 통지는 결정주문이 기재된 서면을 검사에게 송부함으로써 이를 행한다.', 619);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5169, '제19조 (변호인에의 송달) 법원이 법 제15조제1항의 규정에 의한 결정을 한 때에는 그 결정서의 등본을 범죄인의 변호인에게 송달하여야 한다.', 619);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5170, '제20조 (병합심리) 법 제16조제1항의 규정에 의하여, 동일한 범죄인에 대한 인도심사청구가 경합된 경우에는 이를 병합하여 심리할 수 있다.', 619);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5171, '제21조 (물건의 양도)', 619);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5172, '제22조 (준용규정) 법 제17조제2항의 규정에 의한 압수, 수색영장의 발부 및 집행절차에 대하여는 그 성질에 반하지 아니하는 범위안에서 형사소송규칙 제1편 제10장을 준용한다.', 619);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5173, '제23조 (인도구속영장청구의 방식)', 620);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5174, '제24조 (소명자료의 제출)', 620);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5175, '제25조 (인도구속영장의 기각)', 620);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5176, '제26조 (인도구속영장의 기재요건)', 620);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5177, '제27조 (수통의 인도구속영장의 발부)', 620);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5178, '제28조 (준용규정) 형사소송규칙 제49조제1항 및 제51조의 규정은 인도구속영장에 의한 구속에 관하여 이를 준용한다.', 620);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5179, '제29조 (인도구속적부심사청구서의 기재사항) 법 제22조제1항의 규정에 의한 인도 구속에 대한 적부심사는 다음 각호의 사항을 기재한 서면으로 하되 필요한 소명자료를 첨부하여야 한다.', 620);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5180, '제30조 (인도구속영장등본교부청구권) 법 제22조제1항에 규정된 자는 인도구속영장 원본을 보관하고 있는 검사 또는 사법경찰관에게 인도구속영장의 등본의 교부를 청구할 수 있다.', 620);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5181, '제31조 (준용규정) 인도구속의 적부심사절차에 관하여는 그 성질에 반하지 아니하는 범위안에서 형사소송규칙 제16조 및 제104조부터 제106조까지의 규정을 준용한다. <개정 2007.10.29>', 620);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5182, '제32조 (재구속영장의 기재사항) 법원의 인도구속적부심사결과 석방명령을 받아 석방된 범죄인을 재구속하기 위한 인도구속영장청구서에는 제23조에 규정한 사항외에 재구속영장의 청구라는 취지와 범죄인이 도망하거나 죄증을 인멸한 사실을 기재하여야 한다.', 620);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5183, '제33조 (긴급인도구속의 경우) 법 제26조제1항의 규정에 의한 긴급인도구속영장의 청구 및 발부절차에 관하여는 그 성질에 반하지 아니하는 범위안에서 제23조 내지 제32조의 규정을 준용한다.', 620);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5184, '제34조 (인도조약효력발생전의 범죄에 관한 인도청구) 이 규칙은 법 제48조의 규정에 의하여 법이 적용되는 인도청구의 경우에도 이를 적용한다.', 621);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5185, '제1조(목적) 이 규칙은 「스토킹범죄의 처벌 등에 관한 법률」(이하 "법"이라 한다)의 스토킹범죄 사건의 심리와 재판 절차 등에 관하여 필요한 사항을 정함을 목적으로 한다.', 622);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5186, '제2조(의견청취절차)', 622);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5187, '제3조(피해자의 변호사) 법 제17조의4제3항에 따라 피해자의 변호사가 피의자에 대한 구속 전 피의자심문, 증거보전절차, 공판준비기일 및 공판절차에서 의견을 진술하는 경우에는 「성폭력범죄 등 사건의 심리ㆍ재판 및 피해자 보호에 관한 규칙」 제3장의 규정을 준용한다.', 622);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5188, '제4조(미결구금일수의 산입) 법 제9조제1항제4호의 조치가 있었을 때에는 그 유치기간은 「형법」 제57조제1항의 판결선고 전의 구금일수로 본다.', 622);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5189, '제1조(목적) 이 법은 1979년 12월 12일과 1980년 5월 18일을 전후하여 발생한 헌정질서 파괴범죄와 반인도적 범죄에 대한 공소시효 정지 등에 관한 사항 등을 규정함으로써 국가기강을 바로잡고 민주화를 정착시키며 민족정기를 함양함을 목적으로 한다. <개정 2021.1.5>', 623);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5190, '제1조의2(정의)', 623);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5191, '제2조(공소시효의 정지) 1979년 12월 12일과 1980년 5월 18일을 전후하여 발생한 「헌정질서 파괴범죄의 공소시효 등에 관한 특례법」 제2조의 헌정질서 파괴범죄와 반인도적 범죄에 대하여 해당 범죄행위의 종료일부터 1993년 2월 24일까지의 기간은 공소시효의 진행이 정지된 것으로 본다. <개정 2021.1.5>', 623);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5192, '제3조(재정신청에 관한 특례)', 623);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5193, '제4조(특별재심)', 623);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5194, '제5조(기념사업) 정부는 5ㆍ18민주화운동 정신을 계승하는 기념사업을 추진하여야 한다.', 623);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5195, '제6조(배상 의제) 「5ㆍ18민주화운동 관련자 보상 등에 관한 법률」에 따른 보상은 배상(賠償)으로 본다.', 623);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5196, '제7조(상훈 박탈) 정부는 5ㆍ18민주화운동과 관련하여 상훈(賞勳)을 받은 자에 대하여 심사한 결과 오로지 5ㆍ18민주화운동을 진압한 것이 공로로 인정되어 받은 상훈은 「상훈법」 제8조에 따라 서훈(敍勳)을 취소하고, 훈장 등을 환수한다.', 623);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5197, '제8조(5ㆍ18민주화운동에 대한 허위사실 유포 금지)', 623);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5198, '제1조(목적) 이 규칙은 보안관찰법(이하 "법"이라 한다) 및 동법시행령(이하 "영"이라 한다)의 시행에 관하여 필요한 사항을 규정함을 목적으로 한다.', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5199, '제2조(정의) 이 규칙에서 사용하는 용어의 정의는 다음과 같다.', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5200, '제3조(보안관찰부) 영 제4조제2항의 규정에 의한 보안관찰부는 별지 제1호서식에 의한다.', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5201, '제4조(동태보고) 영 제5조제1항 및 제2항의 규정에 의한 보고는 별지 제2호서식에 의한다.', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5202, '제5조(보안관찰처분대상자신고)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5203, '제6조(출소통보)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5204, '제7조(출소사실신고서등)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5205, '제8조(보안관찰처분대상자의 발생통고등)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5206, '제9조(보안관찰처분대상자의 동태보고)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5207, '제10조(보안관찰처분청구서 등) 영 제12조제1항의 규정에 의한 보안관찰처분청구서는 별지 제16호서식, 영 제12조제2항의 규정에 의한 의견서는 별지 제17호서식에 의한다.', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5208, '제11조(관할) 검사 및 사법경찰관리(특별사법경찰관리를 포함한다. 이하 같다)는 각 소속관서의 관할구역내에서 직무를 행한다. 다만, 관할구역내의 사안과 관련이 있는 사실의 조사를 위하여 필요하거나 긴급을 요하는 때에는 관할구역 외에서도 그 직무를 행할 수 있다.', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5209, '제12조(조사의 협조)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5210, '제13조(비밀의 유지와 명예훼손 금지) 검사 및 사법경찰관리는 사안을 조사함에 있어  비밀을 유지하고, 용의자 기타 관계인의 명예를 훼손하지 아니하도록 하여야 한다.', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5211, '제14조(조사의 회피) 검사 또는 사법경찰관리는 용의자 또는 그 관계인과 친족 기타 특별한 관계로 인하여 조사의 공정성을 잃거나 의심을 받을 염려가 있다고 인정되는 사안에 대하여는 소속관서의 장의 허가를 받아 그 조사를 회피하여야 한다.', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5212, '제15조(조사서류의 작성)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5213, '제16조(외국어로 작성된 서류) 외국어로 작성된 서류는 번역문을 첨부하여야 한다.', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5214, '제17조(사안인지)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5215, '제18조(출석요구)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5216, '제19조(용의자에 대한 조사사항) 검사 또는 사법경찰관리는 용의자를 조사하는 때에는 다음 각호의 사항에 유의하여 용의자 신문조서를 작성하여야 한다.', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5217, '제20조(참고인의 진술)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5218, '제21조(임상의 조사) 치료 중인 용의자나 참고인이 있는 곳에서 임상신문을 하는 경우에는 상대방의 건강상태를 충분히 고려하여 조사에 중대한 지장이 없는 한 가족ㆍ의사나 그 밖의 적당한 사람을 참여시켜야 한다. <개정 2022.2.7>', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5219, '제22조(보관조서등)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5220, '제23조(보관물의 보관등)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5221, '제24조(소년용의자에 대한 유의사항)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5222, '제25조(환경조사서등)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5223, '제26조(학생인 용의자에 대한 준용) 학생인 용의자에 대하여는 소년이 아닌 경우에도 제24조 및 제25조의 규정을 준용한다.', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5224, '제27조(사안송치)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5225, '제28조(송치서류)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5226, '제29조(서류 등의 추송) 사법경찰관리는 사안송치 후 서류 또는 물건을 추송하고자 하는 때에는 이미 송치한 사안명ㆍ송치연월일ㆍ용의자의 성명을 기재한 추송서를 작성하고 추송할 서류 및 보관물등을 첨부하여야 한다.', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5227, '제30조(송치 후의 조사등)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5228, '제31조(보안관찰처분 청구등)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5229, '제32조(증명자료) 검사는 보안관찰처분청구를 하는 때에는 청구의 원인이 되는 사실을 증명할 수 있는 피청구자에 대한 다음 각호의 자료를 첨부하여야 한다. 다만, 특별한 사유가 있는 경우에는 해당자료 중 일부를 첨부하지 아니할 수 있다.', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5230, '제33조(보안관찰처분의 기간갱신)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5231, '제34조(검사의 조치결과 통보) 검사는 제27조제1항의 규정에 의하여 송치된 사안에 대하여 보안관찰처분 또는 그 기간갱신을 청구하거나 청구하지 아니하는 조치를 한 때에는 지체없이 그 결과를 당해사안을 송치한 관서의 장에게 통보하여야 한다.', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5232, '제35조(문서의 양식)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5233, '제36조(보안관찰처분면제결정 신청에 관한 조사 등)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5234, '제37조(위원회에의 회부등)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5235, '제38조(보안관찰처분결정통보등)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5236, '제39조(보안관찰처분의 집행지휘)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5237, '제40조(보안관찰처분집행중지결정등과 조사)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5238, '제41조(피보안관찰자의 신고)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5239, '제42조(여행목적지 관할경찰서장의 통보)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5240, '제43조(지도의 방법)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5241, '제44조(거소제공의 청구등)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5242, '제45조(거소변경 신청등)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5243, '제46조(사회복지시설등의 장의 통보) 영 제29조제3항의 규정에 의한 통보는 별지 제67호서식에 의한다.', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5244, '제47조(응급구호) 사법경찰관리가 영 제30조제2항의 규정에 의하여 보고를 하는 때에는 별지 제2호서식에 의하되, 응급구호일시 및 내용 기타 필요한 사항을 기재하여야 한다.', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5245, '제48조(경고서) 영 제31조의 규정에 의한 경고는 별지 제68호서식에 의한다.', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5246, '제49조(장부와 비치서류)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5247, '제50조(서류철의 색인목록)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5248, '제51조(갱신)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5249, '제52조(장부ㆍ서류의 보존기간) 장부 및 서류는 다음의 기간 이를 보존하여야 한다.', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5250, '제53조(보존기간의 기산등)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5251, '제54조(사안기록등의 보관ㆍ보존)', 624);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5252, '제1조(목적) 이 법은 형사사법절차의 전자화를 촉진하여 신속하고 공정하며 투명한 형사사법절차를 실현하고, 형사사법 분야의 대국민 서비스를 개선하여 국민의 권익 신장에 이바지함을 목적으로 한다.', 625);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5253, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다. <개정 2014.3.18, 2014.11.19, 2017.7.26, 2021.12.28>', 625);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5254, '제3조(형사사법절차의 전자화 촉진)', 625);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5255, '제4조(형사사법절차 전자화 계획) 형사사법업무 처리기관이 수립하는 「국가정보화 기본법」 제6조제4항의 국가정보화에 관한 부문계획에는 다음 각 호의 사항이 포함되어야 한다.', 625);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5256, '제5조(시스템의 안정적 운영을 위한 협력 의무)', 625);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5257, '제6조(정보의 공동 활용을 위한 협력 의무)', 625);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5258, '제7조(대국민 포털서비스) 형사사법업무 처리기관은 형사사법정보에 국민이 쉽고 신속하게 접근할 수 있도록 형사사법포털을 통하여 형사사법 관련 서비스를 종합적으로 제공한다.', 625);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5259, '제8조(시스템의 운영 주체)', 625);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5260, '제9조(형사사법정보체계 협의회) 시스템의 유통표준에 영향을 미치는 변경, 개발 및 개선에 관한 사항 및 전자화를 통한 형사사법절차의 개선 등을 협의ㆍ조정하기 위하여 형사사법정보체계 협의회(이하 "협의회"라 한다)를 구성한다.', 625);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5261, '제10조(협의회의 구성)', 625);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5262, '제11조(협의회의 회의)', 625);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5263, '제12조(협의회의 기능)', 625);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5264, '제13조(실무협의회)', 625);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5265, '제14조(형사사법정보의 보호 및 유출금지)', 625);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5266, '제15조(벌칙)', 625);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5267, '제16조(벌칙 적용 시의 공무원 의제) 제8조제3항에 따라 위탁받은 업무에 종사하는 법인의 직원은 「형법」 제129조부터 제132조까지의 규정에 따른 벌칙을 적용할 때에는 공무원으로 본다.', 625);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5268, '제17조(위임규정) 형사사법정보의 정확성 유지 등 이 법 시행에 필요한 사항 중 법무부, 검찰청, 경찰청, 해양경찰청 및 고위공직자범죄수사처 관련 사항은 대통령령으로 정하고, 법원 관련 사항은 대법원규칙으로 정한다. <개정 2014.3.18, 2014.11.19, 2017.7.26, 2021.12.28>', 625);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5269, '제1조(목적) 이 영은 「형사사법절차 전자화 촉진법」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 626);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5270, '제1조의2 삭제 <2022.4.5>', 626);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5271, '제2조(형사사법정보시스템을 이용하는 것이 곤란한 문서) 「형사사법절차 전자화 촉진법」(이하 "법"이라 한다) 제5조제1항 단서에 따라 형사사법업무 처리기관은 다음 각 호의 문서를 저장ㆍ보관하는 경우에는 형사사법정보시스템(이하 "시스템"이라 한다)을 이용하지 않을 수 있다. <개정 2020.7.14, 2022.4.5>', 626);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5272, '제3조(형사사법정보의 유통표준에 관한 준수사항)', 626);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5273, '제4조(송신ㆍ수신되는 정보의 정확성 유지) 형사사법업무 처리기관은 법 제9조에 따른 형사사법정보체계 협의회(이하 "협의회"라 한다)가 법 제12조제1항에 따라 시스템을 통하여 다른 형사사법업무 처리기관에 제공하도록 정한 형사사법정보의 정확성을 유지하기 위하여 다음 각 호의 사항을 준수하여야 한다.', 626);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5274, '제5조(시스템 운영세칙) 법무부장관, 검찰총장, 경찰청장, 해양경찰청장 및 고위공직자범죄수사처장은 법 제8조제1항에 따라 시스템을 안정적으로 운영ㆍ관리하기 위하여 기관별로 운영세칙을 수립ㆍ시행하여야 한다. <개정 2022.4.5>', 626);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5275, '제6조(형사사법공통시스템 운영단의 구성 등)', 626);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5276, '제7조(운영단의 기능) 운영단은 다음 각 호의 업무를 수행한다.', 626);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5277, '제8조(운영단의 의무)', 626);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5278, '제9조(관계 기관ㆍ단체 등에의 협조 요청) 운영단의 장은 운영단의 업무를 수행하기 위하여 필요한 경우에는 전문지식과 경험이 있는 관계 공무원 또는 관계 전문가에게 의견을 듣거나, 관계 기관ㆍ단체 등에 필요한 협조를 요청할 수 있다.', 626);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5279, '제10조(보수 등)', 626);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5280, '제11조(협의회의 위원장 등)', 626);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5281, '제12조(협의회의 개최)', 626);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5282, '제13조(협의회의 협의 등)', 626);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5283, '제14조(회의록)', 626);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5284, '제15조(형사사법정보체계 실무협의회의 구성) 법 제13조에 따른 형사사법정보체계 실무협의회(이하 "실무협의회"라 한다)의 위원은 판사, 검사, 고위공직자범죄수사처 검사, 총경 이상 경찰공무원, 형사사법업무 처리기관 소속의 4급 이상 일반직공무원, 운영단의 장 중에서 협의회의 위원 각자가 1명씩 지명하는 6명으로 한다. <개정 2022.4.5>', 626);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5285, '제16조(실무협의회의 개최)', 626);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5286, '제17조(회의록)', 626);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5287, '제18조(민감정보 및 고유식별정보 등의 처리) 형사사법업무 처리기관(제5호의 사무에 대해서는 법 제8조제3항에 따라 형사사법업무 처리기관의 업무를 위탁받은 자를 포함한다)은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 민감정보, 같은 법 시행령 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호, 외국인등록번호나 그 밖의 개인정보가 포함된 자료를 처리할 수 있다.', 626);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5288, '제1조(목적) 이 영은 「성매매알선 등 행위의 처벌에 관한 법률」에서 위임된 사항과 그 시행에 관하여 필요한 사항을 규정함을 목적으로 한다. <개정 2019.3.5>', 627);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5289, '제2조(중대한 장애가 있는 사람의 범위) 「성매매알선 등 행위의 처벌에 관한 법률」(이하 "법"이라 한다) 제2조제1항제3호 나목ㆍ제4호 다목, 제8조제3항 및 제18조제2항제2호에서 "대통령령으로 정하는 중대한 장애가 있는 사람"이란 별표에서 규정한 사람 또는 이에 준하는 사람으로서 타인의 보호ㆍ감독이 없으면 정상적으로 일상생활 또는 사회생활을 영위하기 어렵고, 이로 인하여 타인의 부당한 압력이나 기망(欺罔)ㆍ유인에 대한 저항능력이 취약한 사람을 말한다. <개정 2019.3.5>', 627);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5290, '제3조(증인신문의 비공개 신청) 법 제9조제2항의 규정에 의한 증인신문의 비공개신청은 법정(증인신문이 진행 중인 경우를 포함한다)에서 구두로도 할 수 있다.', 627);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5291, '제4조(보호처분의 필요성 등의 판단기준) 법원과 검사는 성매매를 한 자에 대한 보호처분의 필요성, 종류 및 기간 등을 판단함에 있어서 성매매 동기, 행위자의 성행(性行) 외에 행위자의 직장, 가족관계, 재범의 위험성 및 보호처분의 효과 등 여러 정황을 충분히 참작하여야 한다.', 627);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5292, '제5조(보상금의 지급신청)', 627);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5293, '제6조(보상금의 지급)', 627);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5294, '제7조 삭제 <2008.10.20>', 627);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5295, '제8조(보상금의 지급 제한) 다음 각호의 1에 해당하는 경우에는 보상금을 지급하지 아니한다.', 627);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5296, '제9조(보상금의 환수) 법무부장관은 보상금을 지급한 후에 허위 그 밖의 부정한 방법으로 보상금을 지급받거나 제8조 각호의 사유가 있음이 확인된 경우에는 보상금을 환수할 수 있다.', 627);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5297, '제10조(보상금 지급조서의 작성 등) 법무부장관은 보상금을 지급하는 때에는 법무부령이 정하는 바에 의하여 보상금 지급조서 및 지급대장을 작성ㆍ비치하고 지급상황을 기재하여야 한다.', 627);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5298, '제1조(목적) 이 법은 「형법」 제69조제2항의 벌금 미납자에 대한 노역장 유치를 사회봉사로 대신하여 집행할 수 있는 특례와 절차를 규정함으로써 경제적인 이유로 벌금을 낼 수 없는 사람의 노역장 유치로 인한 구금을 최소화하여 그 편익을 도모함을 목적으로 한다.', 628);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5299, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다.', 628);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5300, '제3조(국가의 책무) 국가는 경제적인 이유로 인한 노역장 유치를 최소화하기 위하여 벌금 미납자에 대한 사회봉사 집행 등에 관한 시책을 적극적으로 수립ㆍ시행하여야 한다.', 628);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5301, '제4조(사회봉사의 신청)', 628);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5302, '제5조(사회봉사의 청구)', 628);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5303, '제6조(사회봉사 허가)', 628);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5304, '제7조(사회봉사 허가 여부에 대한 통지)', 628);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5305, '제8조(사회봉사의 신고)', 628);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5306, '제9조(사회봉사의 집행담당자)', 628);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5307, '제10조(사회봉사의 집행)', 628);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5308, '제11조(사회봉사의 집행기간) 사회봉사의 집행은 사회봉사가 허가된 날부터 6개월 이내에 마쳐야 한다. 다만, 보호관찰관은 특별한 사정이 있으면 검사의 허가를 받아 6개월의 범위에서 한 번 그 기간을 연장하여 집행할 수 있다.', 628);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5309, '제12조(사회봉사 대상자의 벌금 납입)', 628);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5310, '제13조(사회봉사 이행의 효과) 이 법에 따른 사회봉사를 전부 또는 일부 이행한 경우에는 집행한 사회봉사시간에 상응하는 벌금액을 낸 것으로 본다.', 628);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5311, '제14조(사회봉사 허가의 취소)', 628);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5312, '제15조(사회봉사의 종료)', 628);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5313, '제16조(즉시항고) 신청인과 검사는 제6조제1항의 사회봉사 허가 여부 결정 및 제14조제4항의 사회봉사 허가의 취소 여부 결정에 대하여는 즉시항고 할 수 있다.', 628);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5314, '제17조(사회봉사 대상자에 대한 준용)', 628);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5315, '제1조(목적) 이 영은 「벌금 미납자의 사회봉사 집행에 관한 특례법」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 629);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5316, '제2조(사회봉사의 신청과 벌금액) 「벌금 미납자의 사회봉사 집행에 관한 특례법」(이하 "법"이라 한다) 제4조제1항 본문에 따른 벌금형의 금액은 500만원으로 한다. <개정 2020.1.7>', 629);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5317, '제3조(사회봉사 신청에 필요한 서류 및 제출방법) 법 제4조제1항에 따라 사회봉사를 신청하는 사람은 다음 각 호의 서류를 첨부하여 주거지를 관할하는 지방검찰청(지방검찰청 지청을 포함한다. 이하 같다)의 검사에게 신청서를 제출하여야 한다.', 629);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5318, '제4조(사회봉사의 청구) 법 제5조제1항에 따라 검사가 사회봉사의 허가를 청구할 때에는 사회봉사 청구서와 함께 사회봉사 신청인이 제출한 자료 및 관련 소명자료를 관할 법원에 제출하여야 한다.', 629);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5319, '제5조(신청인의 자료제출 동의) 검사는 법 제5조제2항에 따라 공공기관, 민간단체 등에 벌금 납입 능력 확인에 필요한 자료의 제출을 요구할 때에는 다음 각 호의 사항이 적힌 신청인의 동의서를 첨부하여야 한다.', 629);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5320, '제6조(사회봉사의 신고) 사회봉사 대상자는 법 제8조제1항에서 정한 사항 외에 다음 각 호의 사항을 주거지를 관할하는 보호관찰소에 출석하여 서면으로 신고하여야 한다.', 629);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5321, '제7조(집행 개시 시기) 법 제8조에 따라 사회봉사 대상자의 신고를 받은 보호관찰소의 장은 보호관찰관에게 사회봉사 집행 장소 등 집행 여건을 갖추어 지체 없이 사회봉사를 집행하게 하여야 한다. 다만, 사회봉사 대상자의 생업, 학업, 질병 등을 고려하여 집행 개시 시기를 조정할 수 있다.', 629);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5322, '제8조(집행시간)', 629);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5323, '제9조(집행 대상 인원) 보호관찰관은 사회봉사 집행의 분야 및 장소 등을 고려하여 적절한 사회봉사 집행 대상 인원을 결정하여야 한다.', 629);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5324, '제10조(집행기간의 연장)', 629);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5325, '제11조(미납 벌금액과 남은 사회봉사시간의 산정)', 629);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5326, '제12조(벌금 납입에 따른 검사의 통보)', 629);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5327, '제13조(민감정보 및 고유식별정보의 처리)', 629);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5328, '제1조 (목적) 이 규칙은 「벌금 미납자의 사회봉사 집행에 관한 특례법」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 630);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5329, '제2조 (사회봉사 신청서) 「벌금 미납자의 사회봉사 집행에 관한 특례법」(이하 "법"이라 한다) 제4조제1항에 따른 사회봉사 신청은 별지 제1호 서식에 따른다.', 630);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5330, '제3조 (사회봉사 허가청구서) 「벌금 미납자의 사회봉사 집행에 관한 특례법 시행령」(이하 "영"이라 한다) 제4조에 따른 사회봉사 허가청구서는 별지 제2호 서식에 따른다.', 630);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5331, '제4조 (신청인의 자료제출 동의서) 영 제5조에 따른 신청인의 자료제출 동의서는 별지 제3호 서식에 따른다.', 630);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5332, '제5조 (자료제출 요구서) 법 제5조제2항에 따른 공공기관, 민간단체 등에 대한 벌금 납입 능력 확인에 필요한 자료의 제출 요구는 별지 제4호 서식에 따른다. 다만, 금융거래정보, 신용정보 등 그 제출 요구에 관하여 다른 법령에 따른 서식이 있는 경우에는 그에 따를 수 있다.', 630);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5333, '제6조 (사회봉사 신청 기각 통보서) 법 제5조제5항에 따른 사회봉사 신청에 대한 기각 사실의 통보는 별지 제5호 서식에 따른다.', 630);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5334, '제7조 (사회봉사 신고서) 법 제8조에 따른 보호관찰소의 장에 대한 신고는 별지 제6호 서식에 따른다.', 630);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5335, '제8조 (사회봉사 집행개시 통지서) 보호관찰관은 사회봉사 집행 전에 미리 사회봉사 집행 일시와 장소 등을 정하여 사회봉사 대상자에게 별지 제7호 서식의 사회봉사 집행개시 통지서를 발급하여야 한다.', 630);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5336, '제9조 (집행기간 연장허가 신청서) 영 제10조제1항에 따른 집행기간 연장허가 신청은 별지 제8호 서식에 따른다.', 630);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5337, '제10조 (사회봉사 집행확인서) 법 제12조제2항에 따른 사회봉사 집행확인서는 별지 제9호 서식에 따른다.', 630);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5338, '제11조 (벌금 납입 사실 등의 통보)', 630);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5339, '제12조 (사회봉사 허가의 취소 신청 등) 법 제14조제1항에 따른 사회봉사 허가의 취소 신청 및 취소 청구는 별지 제12호 서식에 따른다.', 630);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5340, '제13조 (사회봉사 허가의 취소 신청에 대한 결과 통보) 법 제14조제6항에 따른 보호관찰소의 장에 대한 통보는 검사가 법원으로부터 받은 결정 고지 서면의 위쪽에 그 결정 내용을 확인하였다는 사실을 적고 서명 또는 날인한 다음, 그 사본을 보호관찰소의 장에게 송부하는 방법으로 한다.', 630);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5341, '제1조(목적) 이 영은 「성폭력범죄의 처벌 등에 관한 특례법」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5342, '제1조의2(성적 목적을 위한 공공장소 침입행위) 「성폭력범죄의 처벌 등에 관한 특례법」(이하 "법"이라 한다) 제12조에서 "「공중화장실 등에 관한 법률」 제2조제1호부터 제5호까지에 따른 공중화장실 등 및 「공중위생관리법」 제2조제1항제3호에 따른 목욕장업의 목욕장 등 대통령령으로 정하는 공공장소"란 다음 각 호의 어느 하나에 해당하는 장소를 말한다.', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5343, '제2조(성폭력범죄자의 재범 예방을 위한 시책 마련) 법무부장관은 법 제16조제2항에 따른 수강명령과 성폭력 치료프로그램의 이수명령의 실시에 필요한 프로그램의 개발 및 관련 전문인력의 양성 등 성폭력범죄자의 재범 예방을 위한 시책을 마련하여야 한다. <개정 2013.6.17>', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5344, '제2조의2(신분비공개수사ㆍ신분위장수사 시 준수사항)', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5345, '제2조의3(신분비공개수사의 방법)', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5346, '제2조의4(신분위장수사에 대한 피해자 동의 절차 등)', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5347, '제2조의5(신분비공개수사의 승인 절차 등)', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5348, '제2조의6(신분비공개수사에 대한 통제)', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5349, '제2조의7(보호시설 및 상담시설) 법 제23조의2제2항에서 "대통령령으로 정하는 보호시설 또는 상담시설"이란 다음 각 호의 보호시설 또는 상담시설을 말한다.', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5350, '제3조(신상정보의 제출 내용 등)', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5351, '제4조(신상정보의 송달) 법 제43조제5항에 따른 기본신상정보 및 변경정보의 송달은 등기우편으로 하고, 전자기록의 송달은 행정기관의 정보통신망 등을 이용하여 한다. <개정 2017.6.20>', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5352, '제4조의2(출입국 시 신고 등)', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5353, '제5조(신상정보의 등록 등)', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5354, '제5조의2(등록정보의 열람 방법 등)', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5355, '제5조의3(등록정보의 통지 방법 및 절차)', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5356, '제6조(등록정보의 관리)', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5357, '제6조의2(신상정보 등록의 면제 신청 등)', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5358, '제6조의3(등록정보 폐기 사실의 열람 방법 등)', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5359, '제6조의4(등록정보 폐기 사실의 통지 방법 및 절차)', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5360, '제7조(등록정보의 활용 등)', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5361, '제8조(등록정보의 송부)', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5362, '제9조(민감정보 및 고유식별정보의 처리)', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5363, '제10조(과태료의 부과기준) 법 제52조제2항에 따른 과태료 부과 기준은 별표와 같다.', 631);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5364, '제1조(목적) 이 법은 성폭력범죄의 처벌 및 그 절차에 관한 특례를 규정함으로써 성폭력범죄 피해자의 생명과 신체의 안전을 보장하고 건강한 사회질서의 확립에 이바지함을 목적으로 한다.', 632);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5365, '제2조(정의)', 632);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5366, '제3조(특수강도강간 등)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5367, '제4조(특수강간 등)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5368, '제5조(친족관계에 의한 강간 등)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5369, '제6조(장애인에 대한 강간ㆍ강제추행 등)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5370, '제7조(13세 미만의 미성년자에 대한 강간, 강제추행 등)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5371, '제8조(강간 등 상해ㆍ치상)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5372, '제9조(강간 등 살인ㆍ치사)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5373, '제10조(업무상 위력 등에 의한 추행)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5374, '제11조(공중 밀집 장소에서의 추행) 대중교통수단, 공연ㆍ집회 장소, 그 밖에 공중(公衆)이 밀집하는 장소에서 사람을 추행한 사람은 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다. <개정 2020.5.19>', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5375, '제12조(성적 목적을 위한 다중이용장소 침입행위) 자기의 성적 욕망을 만족시킬 목적으로 화장실, 목욕장ㆍ목욕실 또는 발한실(發汗室), 모유수유시설, 탈의실 등 불특정 다수가 이용하는 다중이용장소에 침입하거나 같은 장소에서 퇴거의 요구를 받고 응하지 아니하는 사람은 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 2017.12.12, 2020.5.19>', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5376, '제13조(통신매체를 이용한 음란행위) 자기 또는 다른 사람의 성적 욕망을 유발하거나 만족시킬 목적으로 전화, 우편, 컴퓨터, 그 밖의 통신매체를 통하여 성적 수치심이나 혐오감을 일으키는 말, 음향, 글, 그림, 영상 또는 물건을 상대방에게 도달하게 한 사람은 2년 이하의 징역 또는 2천만원 이하의 벌금에 처한다. <개정 2020.5.19>', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5377, '제14조(카메라 등을 이용한 촬영)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5378, '제14조의2(허위영상물 등의 반포등)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5379, '제14조의3(촬영물과 편집물 등을 이용한 협박ㆍ강요)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5380, '제15조(미수범) 제3조부터 제9조까지, 제14조, 제14조의2 및 제14조의3의 미수범은 처벌한다.', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5381, '제15조의2(예비, 음모) 제3조부터 제7조까지의 죄를 범할 목적으로 예비 또는 음모한 사람은 3년 이하의 징역에 처한다.', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5382, '제15조의3(몰수 및 추징)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5383, '제16조(형벌과 수강명령 등의 병과)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5384, '제17조(판결 전 조사)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5385, '제18조(고소 제한에 대한 예외) 성폭력범죄에 대하여는 「형사소송법」 제224조(고소의 제한) 및 「군사법원법」 제266조에도 불구하고 자기 또는 배우자의 직계존속을 고소할 수 있다. <개정 2013.4.5>', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5386, '제19조 삭제 <2013.4.5>', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5387, '제20조(「형법」상 감경규정에 관한 특례) 음주 또는 약물로 인한 심신장애 상태에서 성폭력범죄(제2조제1항제1호의 죄는 제외한다)를 범한 때에는 「형법」 제10조제1항ㆍ제2항 및 제11조를 적용하지 아니할 수 있다.', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5388, '제21조(공소시효에 관한 특례)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5389, '제22조(「특정강력범죄의 처벌에 관한 특례법」의 준용) 성폭력범죄에 대한 처벌절차에는 「특정강력범죄의 처벌에 관한 특례법」 제7조(증인에 대한 신변안전조치), 제8조(출판물 게재 등으로부터의 피해자 보호), 제9조(소송 진행의 협의), 제12조(간이공판절차의 결정) 및 제13조(판결선고)를 준용한다.', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5390, '제22조의2(디지털 성범죄의 수사 특례)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5391, '제22조의3(디지털 성범죄 수사 특례의 절차)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5392, '제22조의4(디지털 성범죄에 대한 긴급 신분비공개수사)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5393, '제22조의5(디지털 성범죄에 대한 긴급 신분위장수사)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5394, '제22조의6(디지털 성범죄에 대한 신분비공개수사 또는 신분위장수사로 수집한 증거 및 자료 등의 사용제한) 사법경찰관리가 제22조의2부터 제22조의5까지에 따라 수집한 증거 및 자료 등은 다음 각 호의 어느 하나에 해당하는 경우 외에는 사용할 수 없다.', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5395, '제22조의7(국가경찰위원회와 국회의 통제)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5396, '제22조의8(비밀준수의 의무)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5397, '제22조의9(준수사항) 사법경찰관리는 제22조의2부터 제22조의5까지에 따른 신분비공개수사 또는 신분위장수사를 할 때에는 수사 관련 법령을 준수하고, 본래 범의(犯意)를 가지지 아니한 자에게 범의를 유발하는 행위를 하지 아니하는 등 적법한 절차와 방식을 따라야 한다.', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5398, '제22조의10(면책)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5399, '제22조의11(수사 지원 및 교육) 상급 경찰관서 수사부서의 장은 신분비공개수사 또는 신분위장수사를 승인하거나 보고받은 경우 사법경찰관리에게 수사에 필요한 인적ㆍ물적 지원을 하고, 전문지식과 피해자 보호를 위한 수사방법 및 수사절차 등에 관한 교육을 실시하여야 한다.', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5400, '제23조(피해자, 신고인 등에 대한 보호조치) 법원 또는 수사기관이 성폭력범죄의 피해자, 성폭력범죄를 신고(고소ㆍ고발을 포함한다)한 사람을 증인으로 신문하거나 조사하는 경우에는 「특정범죄신고자 등 보호법」 제5조 및 제7조부터 제13조까지의 규정을 준용한다. 이 경우 「특정범죄신고자 등 보호법」 제9조와 제13조를 제외하고는 보복을 당할 우려가 있음을 요하지 아니한다.', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5401, '제23조의2(디지털 성범죄의 피해확대 방지 및 피해자 보호 등을 위한 조치)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5402, '제24조(피해자의 신원과 사생활 비밀 누설 금지)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5403, '제25조 삭제 <2023.10.24>', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5404, '제26조(성폭력범죄의 피해자에 대한 전담조사제)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5405, '제27조(성폭력범죄 피해자에 대한 변호사 선임의 특례)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5406, '제28조(성폭력범죄에 대한 전담재판부) 지방법원장 또는 고등법원장은 특별한 사정이 없으면 성폭력범죄 전담재판부를 지정하여 성폭력범죄에 대하여 재판하게 하여야 한다.', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5407, '제29조(수사 및 재판절차에서의 배려)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5408, '제30조(19세미만피해자등 진술 내용 등의 영상녹화 및 보존 등)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5409, '제30조의2(영상녹화물의 증거능력 특례)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5410, '제31조(심리의 비공개)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5411, '제32조(증인지원시설의 설치ㆍ운영 등)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5412, '제33조(전문가의 의견 조회)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5413, '제34조(신뢰관계에 있는 사람의 동석)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5414, '제35조(진술조력인 양성 등)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5415, '제35조의2(진술조력인의 결격사유) 다음 각 호의 어느 하나에 해당하는 사람은 진술조력인이 될 수 없다.', 633);
