INSERT INTO balaw.jo (id, content, jang_id) VALUES (5420, '제39조(벌칙적용에 있어서 공무원의 의제) 진술조력인은 「형법」 제129조부터 제132조까지에 따른 벌칙의 적용에 있어서 이를 공무원으로 본다.', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5421, '제40조(비디오 등 중계장치에 의한 증인신문)', 633);
