INSERT INTO balaw.jo (id, content, jang_id) VALUES (5423, '제40조의3(19세미만피해자등의 증인신문 장소 등에 대한 특례)', 633);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5424, '제41조(증거보전의 특례)', 633);
