INSERT INTO balaw.jo (id, content, jang_id) VALUES (5426, '제43조(신상정보의 제출 의무)', 634);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5427, '제43조의2(출입국 시 신고의무 등)', 634);
