INSERT INTO balaw.jo (id, content, jang_id) VALUES (5429, '제45조(등록정보의 관리)', 634);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5430, '제45조의2(신상정보 등록의 면제)', 634);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5431, '제45조의3(신상정보 등록의 종료)', 634);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5432, '제46조(등록정보의 활용 등)', 634);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5433, '제47조(등록정보의 공개)', 634);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5434, '제48조(비밀준수) 등록대상자의 신상정보의 등록ㆍ보존 및 관리 업무에 종사하거나 종사하였던 자는 직무상 알게 된 등록정보를 누설하여서는 아니 된다.', 634);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5435, '제49조(등록정보의 고지)', 634);
