INSERT INTO balaw.jo (id, content, jang_id) VALUES (5437, '제50조(벌칙)', 635);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5438, '제51조(양벌규정) 법인의 대표자나 법인 또는 개인의 대리인, 사용인, 그 밖의 종업원이 그 법인 또는 개인의 업무에 관하여 제13조 또는 제43조의 위반행위를 하면 그 행위자를 벌하는 외에 그 법인 또는 개인에게도 해당 조문의 벌금형을 과(科)한다. 다만, 법인 또는 개인이 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다.', 635);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5439, '제52조(과태료)', 635);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5440, '제1조(목적) 이 영은 「성폭력범죄의 처벌 등에 관한 특례법」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 636);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5441, '제1조의2(성적 목적을 위한 공공장소 침입행위) 「성폭력범죄의 처벌 등에 관한 특례법」(이하 "법"이라 한다) 제12조에서 "「공중화장실 등에 관한 법률」 제2조제1호부터 제5호까지에 따른 공중화장실 등 및 「공중위생관리법」 제2조제1항제3호에 따른 목욕장업의 목욕장 등 대통령령으로 정하는 공공장소"란 다음 각 호의 어느 하나에 해당하는 장소를 말한다.', 636);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5442, '제2조(성폭력범죄자의 재범 예방을 위한 시책 마련) 법무부장관은 법 제16조제2항에 따른 수강명령과 성폭력 치료프로그램의 이수명령의 실시에 필요한 프로그램의 개발 및 관련 전문인력의 양성 등 성폭력범죄자의 재범 예방을 위한 시책을 마련하여야 한다. <개정 2013.6.17>', 636);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5443, '제2조의2(신분비공개수사ㆍ신분위장수사 시 준수사항)', 636);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5444, '제2조의3(신분비공개수사의 방법)', 636);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5445, '제2조의4(신분위장수사에 대한 피해자 동의 절차 등)', 636);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5446, '제2조의5(신분비공개수사의 승인 절차 등)', 636);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5447, '제2조의6(신분비공개수사에 대한 통제)', 636);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5448, '제2조의7(보호시설 및 상담시설) 법 제23조의2제2항에서 "대통령령으로 정하는 보호시설 또는 상담시설"이란 다음 각 호의 보호시설 또는 상담시설을 말한다.', 636);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5449, '제3조(신상정보의 제출 내용 등)', 636);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5450, '제4조(신상정보의 송달) 법 제43조제5항에 따른 기본신상정보 및 변경정보의 송달은 등기우편으로 하고, 전자기록의 송달은 행정기관의 정보통신망 등을 이용하여 한다. <개정 2017.6.20>', 636);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5451, '제4조의2(출입국 시 신고 등)', 636);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5452, '제5조(신상정보의 등록 등)', 636);
