INSERT INTO balaw.jo (id, content, jang_id) VALUES (5459, '제7조(등록정보의 활용 등)', 636);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5460, '제8조(등록정보의 송부)', 636);
