INSERT INTO balaw.jo (id, content, jang_id) VALUES (5462, '제10조(과태료의 부과기준) 법 제52조제2항에 따른 과태료 부과 기준은 별표와 같다.', 636);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5463, '제1조(목적) 이 규칙은 「성폭력범죄의 처벌 등에 관한 특례법」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 637);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5464, '제2조(신상정보의 제출) 법 제43조제1항 및 제3항에 따른 기본신상정보 및 변경정보의 제출은 별지 제1호서식에 따른다.', 637);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5465, '제3조(신상정보 제출 확인서 등)', 637);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5466, '제4조(출소예정자에 대한 신상정보 제출내용 송부) 교정시설의 장 또는 치료감호시설의 장이 영 제3조제6항에 따라 법무부장관에게 법 제42조제1항에 따른 신상정보 등록대상자(이하 "등록대상자"라 한다) 사진의 전자기록 등을 송달할 때에는 별지 제4호서식에 따른다.', 637);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5467, '제5조(출입국신고서)', 637);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5468, '제6조(등록정보 원부의 작성) 영 제5조제1항에 따른 성범죄자 등록정보 원부는 별지 제7호서식과 같으며, 컴퓨터 파일로 작성ㆍ관리하여야 한다.', 637);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5469, '제7조(등록정보의 통지 신청 등)', 637);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5470, '제8조(등록정보 진위 여부 등의 확인 결과 송부) 법 제45조제7항 및 제8항에 따른 등록정보의 진위와 변경 여부 확인 결과의 송부는 별지 제10호서식에 따른다.', 637);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5471, '제9조(신상정보 등록 면제 신청서 등)', 637);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5472, '제10조(등록정보 폐기 사실의 통지 신청서 등)', 637);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5473, '제11조(등록정보의 공개 및 고지에 필요한 정보의 송부) 영 제8조제1항에 따른 정보의 송부는 별지 제15호서식에 따른다.', 637);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5474, '제1조(목적) 이 법은 업무상과실(業務上過失) 또는 중대한 과실로 교통사고를 일으킨 운전자에 관한 형사처벌 등의 특례를 정함으로써 교통사고로 인한 피해의 신속한 회복을 촉진하고 국민생활의 편익을 증진함을 목적으로 한다.', 638);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5475, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다. <개정 2011.6.8>', 638);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5476, '제3조(처벌의 특례)', 638);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5477, '제4조(보험 등에 가입된 경우의 특례)', 638);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5478, '제5조(벌칙)', 638);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5479, '제6조(양벌규정) 법인의 대표자, 대리인, 사용인, 그 밖의 종업원이 그 법인의 업무에 관하여 제5조의 위반행위를 하면 그 행위자를 벌하는 외에 그 법인에도 해당 조문의 벌금형을 과(科)한다. 다만, 법인이 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다.', 638);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5480, '제1조(목적) 이 영은 교통사고처리특례법(이하 "법"이라 한다)에서 위임된 사항과 그 시행에 관하여 필요한 사항을 규정함을 목적으로 한다.', 639);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5481, '제2조(우선 지급할 치료비에 관한 통상비용의 범위)', 639);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5482, '제3조(우선지급할 치료비외의 손해배상금의 범위)', 639);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5483, '제4조(손해배상금의 우선지급절차)', 639);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5484, '제5조(피해자에 대한 성실보호) 보험사업자 및 공제사업자는 보험 또는 공제와 관련된 교통사고 피해자의 보호관리업무를 성실히 수행하여야 한다.', 639);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5485, '제6조(법 제4조 내지 제6조의 시행일) 법 제4조 내지 제6조의 규정은 1982년 6월 30일부터 시행한다.', 639);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5486, '제1조(목적) 이 영은 「디엔에이신원확인정보의 이용 및 보호에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 640);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5487, '제2조(정의) 이 영에서 사용하는 용어의 뜻은 다음과 같다.', 640);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5488, '제3조(디엔에이인적관리시스템의 운영)', 640);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5489, '제4조(디엔에이인적관리자)', 640);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5490, '제5조(데이터베이스의 연계) 검찰총장 및 경찰청장은 법 제4조제3항에 따라 데이터베이스를 서로 연계하여 운영할 때에는 데이터베이스의 수록내용을 상호 열람, 검색할 수 있도록 전자적으로 연계하여야 한다.', 640);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5491, '제6조(디엔에이감식시료 채취의 위탁)', 640);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5492, '제7조(디엔에이감식시료채취영장의 집행 등)', 640);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5493, '제8조(디엔에이감식시료의 채취 방법 및 관리)', 640);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5494, '제9조(디엔에이감식시료 채취사실의 기록) 검사 또는 사법경찰관은 법 제6조 및 제7조제1항에 따라 디엔에이감식시료를 채취한 경우 채취 일시와 장소 및 방법, 채취한 디엔에이감식시료의 종류와 채취 사유 등을 적은 서류를 작성하여 사건기록에 첨부하여야 한다.', 640);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5495, '제10조(수형인등 또는 구속피의자등으로부터 채취한 디엔에이감식시료의 송부)', 640);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5496, '제11조(범죄현장등으로부터 채취한 디엔에이감식시료의 송부)', 640);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5497, '제12조(업무의 위임 및 위탁)', 640);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5498, '제13조(디엔에이감식 등)', 640);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5499, '제14조(데이터베이스의 관리 등)', 640);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5500, '제15조(디엔에이신원확인정보의 검색 및 회보)', 640);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5501, '제16조(디엔에이감식시료의 폐기)', 640);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5502, '제17조(디엔에이신원확인정보의 삭제 방법, 절차 등)', 640);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5503, '제18조(디엔에이신원확인정보데이터베이스관리위원회의 심의사항) 법 제14조제1항제4호에서 "대통령령으로 정하는 사항"이란 다음 각 호와 같다.', 640);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5504, '제19조(디엔에이신원확인정보데이터베이스관리위원회의의 구성 및 운영)', 640);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5505, '제19조의2(위원회 위원의 해촉) 국무총리는 법 제14조제3항에 따른 위원회의 위원이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 위원을 해촉(解囑)할 수 있다.', 640);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5506, '제20조(위원회의 의견제출) 위원회가 법 제14조제6항에 따라 검찰총장 또는 경찰청장에게 의견을 제시한 경우 검찰총장 또는 경찰청장은 의견의 시행 경과 및 결과를 위원회에 통보하여야 한다.', 640);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5507, '제1조(목적) 이 규칙은 「성폭력범죄의 처벌 등에 관한 특례법」의 성폭력범죄, 「아동ㆍ청소년의 성보호에 관한 법률」의 아동ㆍ청소년대상 성범죄 및 「아동학대범죄의 처벌 등에 관한 특례법」의 아동학대범죄 사건의 심리ㆍ재판 절차 및 피해자(성폭력범죄의 피해자, 아동ㆍ청소년대상 성범죄의 피해아동ㆍ청소년, 아동학대범죄의 피해아동, 범죄사건의 피해자인 장애인을 말한다) 등의 보호조치에 관하여 필요한 사항을 규정함을 목적으로 한다. <개정 2022.1.28>', 641);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5508, '제2조(보호와 배려)', 641);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5509, '제3조 삭제 <2016.11.29>', 642);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5510, '제4조(공판기일의 통지)', 643);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5511, '제5조(피해자 변호사의 좌석) 피해자 변호사는 법관의 정면에 위치한다.', 643);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5512, '제6조(의견의 진술)', 643);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5513, '제7조(의견진술 기일의 통지)', 643);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5514, '제8조(의견진술에 갈음한 서면의 제출)', 643);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5515, '제9조(의견진술ㆍ의견진술에 갈음하여 제출된 서면) 제6조제1항에 따른 진술과 제8조제1항에 따른 서면은 범죄사실의 인정을 위한 증거로 할 수 없다.', 643);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5516, '제10조(국선변호사 선정의 취소요청) 재판장은 「성폭력범죄의 처벌 등에 관한 특례법」 제27조제6항(다른 법률에서 위 규정을 준용하는 경우를 포함한다) 또는 「아동학대범죄의 처벌 등에 관한 특례법」제16조제6항에 따라 선정된 국선변호사가 그 업무를 성실하게 수행하지 아니하거나 그 밖의 사유로 공판절차에 계속 관여하는 것이 적절하지 아니하다고 인정하는 때에는 피해자 보호를 위하여 검사에게 그 국선변호사 선정의 취소를 요청할 수 있다. <개정 2014.9.1, 2021.6.28>', 643);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5517, '제11조(구속 전 피의자심문, 증거보전절차, 공판준비기일에의 준용) 제4조부터 제10조까지의 규정은 피의자에 대한 구속 전 피의자심문, 증거보전절차, 공판준비기일의 절차에 준용한다.', 643);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5518, '제12조(열람ㆍ등사의 신청)', 643);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5519, '제13조(자격)', 644);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5520, '제14조(교육)', 644);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5521, '제15조(업무)', 644);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5522, '제16조(증인지원위원회)', 644);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5523, '제17조(진술조력인의 재판과정 참여 신청)', 645);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5524, '제18조(신청권의 고지)', 645);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5525, '제19조(진술조력인의 선정)', 645);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5526, '제20조(선정의 취소 등)', 645);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5527, '제21조(진술조력인 참여 기일의 통지)', 645);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5528, '제22조(진술조력인의 좌석)', 645);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5529, '제23조(진술조력인의 중개ㆍ보조)', 645);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5530, '제24조(조서의 기재) 진술조력인을 증인신문에 참여하게 한 때에는 공판조서에 진술조력인의 성명, 출석여부 및 진술조력인을 통하여 증인과의 의사소통을 중개 또는 보조하도록 하였다는 취지를 기재하여야 한다.', 645);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5531, '제25조(진술조력인의 수당 등)', 645);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5532, '제26조(비디오 등 중계장치에 의한 신문)', 645);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5533, '제1조(목적) 이 법은 「형의 집행 및 수용자의 처우에 관한 법률」 제7조에 따라 교도소 등의 설치ㆍ운영에 관한 업무의 일부를 민간에 위탁하는 데에 필요한 사항을 정함으로써 교도소 등의 운영의 효율성을 높이고 수용자(收容者)의 처우 향상과 사회 복귀를 촉진함을 목적으로 한다.', 646);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5534, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다.', 646);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5535, '제3조(교정업무의 민간 위탁)', 646);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5536, '제4조(위탁계약의 체결)', 646);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5537, '제5조(위탁계약의 내용)', 646);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5538, '제6조(위탁업무의 정지)', 646);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5539, '제7조(위탁계약의 해지)', 646);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5540, '제8조(위탁계약 해지 시의 업무 처리) 위탁계약이 해지된 경우 국가가 부득이한 사정으로 위탁업무를 즉시 처리할 수 없을 때에는 수탁자나 그의 승계인은 국가가 업무를 처리할 수 있을 때까지 종전의 위탁계약에 따라 업무 처리를 계속하여야 한다.', 646);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5541, '제9조(청문) 법무부장관이 제7조제1항에 따라 위탁계약을 해지하려면 청문을 하여야 한다.', 646);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5542, '제10조(교정법인의 정관 변경 등)', 647);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5543, '제11조(임원)', 647);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5544, '제12조(임원취임의 승인 취소) 임원이 다음 각 호의 어느 하나에 해당하는 행위를 하면 법무부장관은 취임 승인을 취소할 수 있다.', 647);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5545, '제13조(임원 등의 겸직 금지)', 647);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5546, '제14조(재산)', 647);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5547, '제15조(회계의 구분)', 647);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5548, '제16조(예산 및 결산)', 647);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5549, '제17조(합병 및 해산의 인가)', 647);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5550, '제18조(잔여재산의 귀속)', 647);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5551, '제19조(다른 법률과의 관계) 교정법인에 관하여는 이 법에 규정된 것 외에는 그 법인의 설립 형태에 따라 「민법」 중 사단법인이나 재단법인에 관한 규정, 「상법」 중 회사에 관한 규정, 그 밖의 설립 근거 법률을 적용한다.', 647);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5552, '제20조(민영교도소등의 시설) 교정법인이 민영교도소등을 설치ㆍ운영할 때에는 대통령령으로 정하는 기준에 따른 시설을 갖추어야 한다.', 648);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5553, '제21조(민영교도소등의 조직 등)', 648);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5554, '제22조(민영교도소등의 검사)', 648);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5555, '제23조(운영 경비)', 648);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5556, '제24조(수용 의제) 민영교도소등에 수용된 수용자는 「형의 집행 및 수용자의 처우에 관한 법률」에 따른 교도소등에 수용된 것으로 본다.', 648);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5557, '제25조(수용자의 처우)', 648);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5558, '제26조(작업 수입) 민영교도소등에 수용된 수용자가 작업하여 생긴 수입은 국고수입으로 한다.', 648);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5559, '제27조(보호장비의 사용 등)', 648);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5560, '제28조(결격사유) 다음 각 호의 어느 하나에 해당하는 자는 민영교도소등의 직원으로 임용될 수 없으며, 임용 후 다음 각 호의 어느 하나에 해당하는 자가 되면 당연히 퇴직한다.', 649);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5561, '제29조(임면 등)', 649);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5562, '제30조(직원의 직무)', 649);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5563, '제31조(제복 착용과 무기 구입)', 649);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5564, '제32조(지원) 법무부장관은 필요하다고 인정하면 직권으로 또는 해당 교정법인이나 민영교도소등의 장의 신청을 받아 민영교도소등에 소속 공무원을 파견하여 업무를 지원하게 할 수 있다.', 650);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5565, '제33조(감독 등)', 650);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5566, '제34조(보고ㆍ검사)', 650);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5567, '제35조(위탁업무의 감사)', 650);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5568, '제36조(징계처분명령 등)', 650);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5569, '제37조(공무원 의제 등)', 651);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5570, '제38조(손해배상)', 651);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5571, '제39조(권한의 위임) 법무부장관은 이 법에 따른 권한의 일부를 관할 지방교정청장에게 위임할 수 있다.', 651);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5572, '제40조(「형의 집행 및 수용자의 처우에 관한 법률」의 준용) 민영교도소등에 수용된 자에 관하여 성질상 허용되지 아니하는 경우와 이 법 및 위탁계약으로 달리 정한 경우 외에는 「형의 집행 및 수용자의 처우에 관한 법률」을 준용한다.', 651);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5573, '제41조(부분위탁) 국가가 운영하는 교도소등의 업무 중 직업훈련ㆍ교도작업 등 일부 교정업무를 특정하여 위탁하는 경우 그 수탁자에 관하여는 성질상 허용되지 아니하는 경우와 위탁계약으로 달리 정한 경우 외에는 교정법인에 관한 규정을 준용한다.', 651);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5574, '제42조(벌칙)', 652);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5575, '제43조(양벌규정) 교정법인의 임직원(교정법인이 운영하는 민영교도소등의 직원을 포함한다)이 그 법인의 업무에 관하여 제42조의 위반행위를 하면 그 행위자를 벌하는 외에 그 법인에도 해당 조문의 벌금형을 과(科)한다. 다만, 법인이 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다.', 652);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5576, '제44조(과태료)', 652);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5577, '제1조(목적) 이 영은 「민영교도소 등의 설치ㆍ운영에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5578, '제2조 삭제 <2009.9.3>', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5579, '제3조 삭제 <2009.9.3>', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5580, '제4조(위탁계약의 성립 등)', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5581, '제5조(교정법인의 정관변경) 법 제10조제2항 단서에서 "대통령령으로 정하는 경미한 사항"이란 다음 각 호의 어느 하나에 해당하는 사항을 말한다.', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5582, '제6조(교정법인 임원의 임기 등)', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5583, '제7조(임원의 직무)', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5584, '제8조(이사회의 회의 등)', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5585, '제9조(재산의 구분 등)', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5586, '제10조(기본재산의 처분) 법 제14조제2항 단서에서 "대통령령으로 정하는 경미한 사항"이란 다음 각 호의 어느 하나에 해당하는 경우를 말한다. 다만, 법 제14조제2항 본문에 따른 허가를 받지 아니할 목적으로 기본재산을 분할하거나 법, 이 영 또는 관계 법령을 위반하는 경우는 제외한다.', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5587, '제11조(처분할 수 없는 재산의 범위) 법 제14조제3항에서 "대통령령으로 정하는 것"이란 다음 각 호의 것을 말한다. <개정 2021.1.5>', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5588, '제12조(일반회계와 교도작업회계의 세입ㆍ세출)', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5589, '제13조(예산ㆍ결산 등의 제출)', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5590, '제14조(민영교도소등의 시설기준)', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5591, '제15조(수용자의 처우)', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5592, '제16조(직원의 임면 승인 범위) 법 제29조제1항 단서에서 "대통령령으로 정하는 직원"이란 「법무부와 그 소속기관 직제」에 따라 교도소등에 두는 과의 과장 이상의 직에 준하는 직위의 직원을 말한다.', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5593, '제17조(직원의 임용 자격 등)', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5594, '제18조(직무교육)', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5595, '제19조(직원의 직무) 민영교도소등의 직원은 「형의 집행 및 수용자의 처우에 관한 법률」에 따른 교도관의 직무 중 위탁계약에서 정하는 범위에서 그 직무를 수행한다.', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5596, '제20조(직권면직)', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5597, '제21조(징계처분)', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5598, '제22조(보고)', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5599, '제23조(손해배상의 담보) 교정법인은 법 제38조제1항에 따른 손해배상을 위하여 1억원 이상의 현금 또는 유가증권을 공탁하거나 이행보증보험에 가입하여야 한다.', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5600, '제24조(과태료의 부과기준) 법 제44조제1항부터 제3항까지의 규정에 따른 과태료의 부과기준은 별표와 같다.', 653);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5601, '제1조(목적) 이 규칙은 「민영교도소 등의 설치ㆍ운영에 관한 법률」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5602, '제2조 삭제 <2009.9.3>', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5603, '제3조(교정법인의 정관변경 인가신청) 교정법인이 「민영교도소 등의 설치ㆍ운영에 관한 법률」(이하 "법"이라 한다) 제10조제2항에 따라 정관 변경의 인가를 받으려는 경우에는 정관 변경 인가신청서에 다음 각 호의 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5604, '제4조(임원취임 승인신청)', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5605, '제5조(기본재산의 처분)', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5606, '제6조(사업계획 등의 제출)', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5607, '제7조(예산편성 요강)', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5608, '제8조(회계원칙) 교정법인의 회계는 이 규칙에 특별한 규정이 있는 경우를 제외하고는 모든 회계거래를 발생의 사실에 의하여 기업회계의 원칙에 따라 처리한다.', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5609, '제9조(합병인가 신청)', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5610, '제10조(분할인가 신청) 교정법인이 법 제17조제1항제2호에 따른 분할의 인가를 신청할 경우에는 분할인가 신청서에 다음 각 호의 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5611, '제11조(해산인가 신청) 교정법인이 법 제17조제1항제3호에 따라 해산의 인가를 신청하는 경우에는 해산사유, 수용자 처리계획 및 직원 처리계획이 포함된 해산인가 신청서에 다음 각 호의 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5612, '제12조(합병ㆍ분할ㆍ해산의 인가 시에 붙일 조건)', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5613, '제13조(시설 등 검사절차)', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5614, '제14조(시설검사 방법) 법 제22조에 따라 민영교도소등의 시설을 검사를 하는 경우 유의할 사항은 다음 각 호와 같다.', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5615, '제15조(운영 경비)', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5616, '제16조(설치비용 지급)', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5617, '제17조(직원의 임면승인)', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5618, '제18조 삭제 <2025.5.27>', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5619, '제19조(교육 등)', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5620, '제20조(제복 및 사복 착용)', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5621, '제21조(신분증명서)', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5622, '제22조(무기ㆍ탄약의 배정 등)', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5623, '제23조(장부와 비치서류)', 654);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5624, '제1조(목적) 이 법은 국민의 생명ㆍ신체 및 재산을 보호하고 공공의 안녕과 질서를 유지하기 위하여 화염병을 제조ㆍ보관ㆍ운반ㆍ소지 또는 사용한 사람을 처벌함을 목적으로 한다.', 655);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5625, '제2조(정의) 이 법에서 "화염병"이란 유리병이나 그 밖의 용기에 휘발유나 등유, 그 밖에 불붙기 쉬운 물질을 넣고 그 물질이 흘러나오거나 흩날리는 경우 이것을 연소(燃燒)시키기 위하여 발화장치 또는 점화장치를 한 물건으로서 사람의 생명ㆍ신체 또는 재산에 위해(危害)를 끼치는 데에 사용되는 것을 말한다.', 655);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5626, '제3조(화염병의 사용)', 655);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5627, '제4조(화염병의 제조ㆍ소지 등)', 655);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5628, '제1조(목적) 이 규칙은 「형사소송법」(이하 "법"이라 한다) 제59조의3제2항 및 제6항이 대법원규칙에서 정하도록 한 사항과 그밖에 법 제59조의3에 따른 판결서 등의 열람 및 복사에 필요한 사항을 규정함을 목적으로 한다.', 656);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5629, '제2조(정의) 이 규칙에서 사용하는 용어의 뜻은 다음과 같다.', 656);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5630, '제3조(증거목록ㆍ기록목록의 전자파일 등록) 법원사무관 등은 형사사건의 증거목록과 기록목록을 작성한 경우 전자파일의 형태로 전산정보처리시스템에 등록하여야 한다.', 656);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5631, '제4조(비실명 처리) 법원사무관 등은 전산정보처리시스템에 등록된 판결서 등에 대하여 개인정보 보호를 위한 비실명 처리를 하여야 한다.', 656);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5632, '제5조(열람ㆍ복사의 방법과 절차)', 656);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5633, '제6조(열람ㆍ복사의 제한)', 656);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5634, '제7조(재정보증) 법원행정처장은 판결서 등의 비실명 처리를 담당하는 법원사무관 등의 재정보증에 관한 사항을 정하여 운용할 수 있다.', 656);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5635, '제1조(목적) 이 법은 경범죄의 종류 및 처벌에 필요한 사항을 정함으로써 국민의 자유와 권리를 보호하고 사회공공의 질서유지에 이바지함을 목적으로 한다.', 657);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5636, '제2조(남용금지) 이 법을 적용할 때에는 국민의 권리를 부당하게 침해하지 아니하도록 세심한 주의를 기울여야 하며, 본래의 목적에서 벗어나 다른 목적을 위하여 이 법을 적용하여서는 아니 된다.', 657);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5637, '제3조(경범죄의 종류)', 658);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5638, '제4조(교사ㆍ방조) 제3조의 죄를 짓도록 시키거나 도와준 사람은 죄를 지은 사람에 준하여 벌한다.', 658);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5639, '제5조(형의 면제와 병과) 제3조에 따라 사람을 벌할 때에는 그 사정과 형편을 헤아려서 그 형을 면제하거나 구류와 과료를 함께 과(科)할 수 있다.', 658);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5640, '제6조(정의)', 659);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5641, '제7조(통고처분)', 659);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5642, '제8조(범칙금의 납부)', 659);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5643, '제8조의2(범칙금의 납부)', 659);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5644, '제9조(통고처분 불이행자 등의 처리)', 659);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5645, '제1조(목적) 이 영은 「경범죄 처벌법」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 660);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5646, '제2조(범칙행위의 범위와 범칙금의 액수) 「경범죄 처벌법」(이하 "법"이라 한다) 제6조제1항에 따른 범칙행위의 구체적인 범위와 법 제7조제2항에 따른 범칙금의 액수는 별표와 같다.', 660);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5647, '제3조(범칙금의 납부 통고 등)', 660);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5648, '제4조(범칙금의 납부 등)', 660);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5649, '제4조의2(신용카드 등을 이용한 범칙금의 납부방법)', 660);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5650, '제5조(범칙금 징수사항 기록부의 비치) 경찰서장등은 제4조제4항에 따라 수납기관으로부터 범칙금 수납 사실을 통보받은 때마다 그 징수사항을 범칙금 징수사항 기록부에 기록하거나 전자매체를 통하여 전산으로 저장ㆍ관리하여야 한다.', 660);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5651, '제6조(즉결심판 대상자에 대한 처리)', 660);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5652, '제7조(철도특별사법경찰대장의 즉결심판 대상자 적발 통보 등)', 660);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5653, '제8조(자료 요청 등)', 660);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5654, '제9조(민감정보 및 고유식별정보의 처리) 경찰서장등은 법 및 이 영에 따른 범칙금에 관한 사무 수행을 위하여 불가피한 경우 「개인정보 보호법 시행령」 제18조제2호에 따른 범죄경력자료에 해당하는 정보와 같은 영 제19조제1호ㆍ제2호 또는 제4호에 따른 주민등록번호ㆍ여권번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 660);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5655, '제1조(목적) 이 규칙은 「경범죄 처벌법」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 661);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5656, '제2조(범칙금 납부통고서 등)', 661);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5657, '제3조(범칙금 징수사항 기록부) 영 제5조에 따른 범칙금 징수사항 기록부는 별지 제6호서식에 따른다. <개정 2016.7.19>', 661);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5658, '제4조(즉결심판 출석통지서 등)', 661);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5659, '제5조(즉결심판 통지예고서 등) 영 제7조제1항에 따른 즉결심판 통지예고서는 별지 제12호서식에 따르고, 즉결심판 대상자 적발통보서는 별지 제13호서식에 따른다.', 661);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5660, '제6조(통고처분 접수처리부) 영 제8조제2항에 따른 통고처분 접수처리부는 별지 제14호서식에 따른다.', 661);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5661, '제1조(목적) 이 법은 집단적 또는 상습적으로 폭력행위 등을 범하거나 흉기 또는 그 밖의 위험한 물건을 휴대하여 폭력행위 등을 범한 사람 등을 처벌함을 목적으로 한다.', 662);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5662, '제2조(폭행 등)', 662);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5663, '제3조(집단적 폭행 등)', 662);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5664, '제4조(단체 등의 구성ㆍ활동)', 662);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5665, '제5조(단체 등의 이용ㆍ지원)', 662);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5666, '제6조(미수범) 제2조, 제3조, 제4조제2항[「형법」 제136조, 제255조, 제314조, 제315조, 제335조, 제337조(강도치상의 죄에 한정한다), 제340조제2항(해상강도치상의 죄에 한정한다) 또는 제343조의 죄를 범한 경우는 제외한다] 및 제5조의 미수범은 처벌한다.', 662);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5667, '제7조(우범자) 정당한 이유 없이 이 법에 규정된 범죄에 공용(供用)될 우려가 있는 흉기나 그 밖의 위험한 물건을 휴대하거나 제공 또는 알선한 사람은 3년 이하의 징역 또는 300만원 이하의 벌금에 처한다.', 662);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5668, '제8조(정당방위 등)', 662);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5669, '제9조(사법경찰관리의 직무유기)', 662);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5670, '제10조(사법경찰관리의 행정적 책임)', 662);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5671, '제1조(목적) 이 법은 외국에서 형집행중인 대한민국 국민의 국내이송과 대한민국에서 형집행중인 외국인의 국외이송에 관한 요건과 절차 등을 규정함으로써 이들의 원활한 갱생 및 조속한 사회복귀를 도모함을 목적으로 한다.', 663);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5672, '제2조(정의) 이 법에서 사용하는 용어의 정의는 다음과 같다.', 663);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5673, '제3조(조약과의 관계) 국제수형자이송은 대한민국과 외국간에 조약이 체결되어 있는 경우에 한하여 이 법과 그 조약이 정하는 바에 따라 실시한다. 이 경우 조약에 이 법과 다른 규정이 있는 때에는 그 조약의 규정에 의한다.', 663);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5674, '제4조(국제수형자이송관련 문서 등의 접수 및 송부)', 663);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5675, '제5조 삭제 <2009.3.25>', 664);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5676, '제6조 삭제 <2009.3.25>', 664);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5677, '제7조 삭제 <2009.3.25>', 664);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5678, '제8조 삭제 <2009.3.25>', 664);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5679, '제9조 삭제 <2009.3.25>', 664);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5680, '제10조 삭제 <2009.3.25>', 664);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5681, '제11조(국내이송의 요건)', 665);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5682, '제12조(국내이송 요청 등)', 665);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5683, '제13조(국내이송 명령 등)', 665);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5684, '제14조(국내이송집행장의 발부)', 665);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5685, '제15조(외국법원 판결의 효력) 국내이송에 의하여 국내이송대상수형자에게 선고된 자유형을 국내에서 집행함에 있어서 그 외국법원의 판결은 대한민국 법률에 의한 대한민국 법원의 판결과 동일한 효력이 있는 것으로 본다.', 665);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5686, '제16조(집행할 자유형의 형기 및 집행방법)', 665);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5687, '제17조(형집행시의 적용법률) 국내이송수형자에 대한 가석방ㆍ사면ㆍ감형 등 자유형의 집행에 관하여 필요한 사항은 형법ㆍ「형의 집행 및 수용자의 처우에 관한 법률」 등 대한민국의 관련 법률이 정하는 바에 의한다. <개정 2007.12.21>', 665);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5688, '제18조(공소제기의 제한) 국내이송수형자에 대하여 외국에서 선고된 자유형을 집행중인 때와 그 자유형의 집행을 종료하거나 집행을 하지 아니하기로 확정된 때에는 동일한 범죄사실에 대하여 공소를 제기할 수 없다.', 665);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5689, '제19조(외국법원 판결의 취소 등)', 665);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5690, '제20조(자유형의 종류 또는 기간의 변경)', 665);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5691, '제21조(국내이송후 외국에 대한 통지) 법무부장관은 다음 각호의 1에 해당하는 사유가 발생한 때에는 지체없이 외국에 이를 통지하여야 한다.', 665);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5692, '제22조(조약사항의 고지) 교도소등의 장은 외국인이 자유형을 선고받고 그 확정판결의 집행을 위하여 교도소등에 수용되는 때에는 조약이 정하는 사항을 고지하여야 한다.', 666);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5693, '제23조(국외이송의 요건)', 666);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5694, '제24조(동의확인을 위한 접견) 「형의 집행 및 수용자의 처우에 관한 법률」 제2조제4호의 교정시설의 장은 다음 각호의 1에 해당하는 자가 조약에 의하여 국외이송에 동의하는지 여부를 확인하기 위하여 그 교정시설에 수용되어 있는 국외이송대상수형자와의 접견을 요구하는 때에는 같은 법 등 대한민국의 관련 법률이 정하는 범위안에서 이를 허가하여야 한다. <개정 2007.12.21>', 666);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5695, '제25조(국외이송 요청 등)', 666);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5696, '제26조(국외이송 명령 등)', 666);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5697, '제27조(국외이송지휘서의 발부)', 666);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5698, '제28조(교도소등의 장의 조치) 제27조제2항의 규정에 의하여 검사로부터 국외이송지휘를 받은 교도소등의 장은 외국의 공무원으로부터 인수허가장의 제시와 함께 국외이송대상수형자의 인도를 요청받은 때에는 국외이송지휘서에 기재된 장소에서 외국의 공무원에게 국외이송대상수형자를 인도하여야 한다.', 666);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5699, '제29조(국외이송수형자에 대한 형집행의 종료) 제28조의 규정에 의하여 외국에 인도된 국외이송대상수형자(이하 "국외이송수형자"라 한다)에 대하여 선고ㆍ확정된 자유형은 외국에서 그 형에 상응하는 외국 법령상의 형의 집행이 종료(종료한 것으로 간주하는 경우를 포함한다)된 때에 그 집행이 종료된 것으로 본다.', 666);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5700, '제30조(국외이송후 외국에 대한 통지) 법무부장관은 다음 각호의 1에 해당하는 때에는 지체없이 외국에 그 취지를 통지하여야 한다.', 666);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5701, '제31조(군교도소에 수용중인 국외이송대상수형자의 이감)', 666);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5702, '제32조(통과호송)', 667);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5703, '제33조(비용) 국내이송에 소요되는 비용중 대한민국이 국내이송수형자 본인과 관련하여 지출하는 비용은 국내이송수형자의 부담으로 한다. 다만, 법무부장관은 국내이송수형자의 경제적 사정을 감안하여 이를 감면할 수 있다.', 667);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5704, '제34조(검찰총장 경유) 이 법의 규정에 의하여 법무부장관이 검사장등에게 하는 명령 또는 서류송부와 검사장등이 법무부장관에게 하는 보고 또는 서류송부는 검찰총장을 경유하여야 한다.', 667);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5705, '제1조(국내재산 도피 금지) 누구든지 국내에 있는 재산을 도피시킬 목적으로 외국 또는 군사분계선 이북의 지역으로 재산을 이동하거나 이동하는 결과를 생기게 하는 행위를 할 수 없다.', 668);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5706, '제2조(벌칙) 제1조를 위반하는 자는 10년 이하의 징역이나 금고 또는 100만원(圓) 이하의 벌금에 처한다. 다만, 해당 범죄행위의 목적물의 가격의 3배가 100만원(圓)을 초과할 때에는 벌금액은 해당 가격의 3배 이하로 한다.', 668);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5707, '제3조(적용 배제) 다음 각 호의 어느 하나에 해당하는 경우에는 제1조를 적용하지 아니한다.', 668);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5708, '제4조(양벌규정) 법인의 대표자, 대리인, 사용인, 그 밖의 종업원이 그 법인의 업무에 관하여 제1조의 위반행위를 하면 그 행위자를 벌하는 외에 그 법인에도 제2조의 벌금형을 과(科)한다. 다만, 법인이 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다.', 668);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5709, '제5조 삭제 <2010.3.31>', 668);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5710, '제1조(국내재산의 범위) 「국내재산 도피 방지법」(이하 "법"이라 한다) 제1조에 따른 재산은 다음 각 호의 어느 하나에 해당하는 것으로 한다.', 669);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5711, '제2조(재산 이동의 허가신청) 법 제3조제1호에 따른 정부의 허가를 받으려는 자는 다음 각 호의 사항을 적은 신청서를 기획재정부장관에게 제출하여야 한다. 다만, 「관세법」이나 그 밖의 법령에 따라 소관 관청의 허가를 받은 경우에는 예외로 한다.', 669);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5712, '제3조(허가) 기획재정부장관은 제2조에 따른 신청서를 받았을 때에는 이를 심사하여 법 제1조에 따른 재산 도피의 목적이 아닌 경우에만 허가한다.', 669);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5713, '제4조(재산 이동의 절차) 제3조에 따라 허가를 받은 자는 그 허가서를 세관이나 그 밖의 관계기관에 제시하고 재산 이동에 필요한 절차를 밟아야 한다.', 669);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5714, '제5조(검사 등) 기획재정부장관은 필요하다고 인정할 때에는 소속 공무원을 파견하여 제2조에 따라 신청한 재산을 검사하게 하거나 그 재산에 관한 보고를 하게 할 수 있다.', 669);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5715, '제1조(목적) 이 법은 부정수표(不正手票) 등의 발행을 단속ㆍ처벌함으로써 국민의 경제생활의 안전과 유통증권인 수표의 기능을 보장함을 목적으로 한다.', 670);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5716, '제2조(부정수표 발행인의 형사책임)', 670);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5717, '제3조(법인ㆍ단체 등의 형사책임)', 670);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5718, '제4조(거짓 신고자의 형사책임) 수표금액의 지급 또는 거래정지처분을 면할 목적으로 금융기관에 거짓 신고를 한 자는 10년 이하의 징역 또는 20만원 이하의 벌금에 처한다.', 670);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5719, '제5조(위조ㆍ변조자의 형사책임) 수표를 위조하거나 변조한 자는 1년 이상의 유기징역과 수표금액의 10배 이하의 벌금에 처한다.', 670);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5720, '제6조(「형사소송법」의 특례) 이 법에 따라 벌금을 선고하는 경우 「형사소송법」 제334조제1항에 따른 가납판결(假納判決)을 하여야 하며, 구속된 피고인에 대하여는 같은 법 제331조에도 불구하고 벌금을 가납할 때까지 계속 구속한다.', 670);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5721, '제7조(금융기관의 고발의무)', 670);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5722, '제1조(목적) 이 영은 「부정수표 단속법」을 시행하는 데 필요한 사항을 규정함을 목적으로 한다.', 671);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5723, '제2조(금융기관의 범위 등)', 671);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5724, '제1조 (목적) 이 규칙은 형의실효등에관한법률 제2조제4호 및 동법시행령(이하 "영"이라 한다) 제2조제2항의 규정에 의하여 수사자료표를 작성함에 있어서 지문을 채취할 피의자의 범위를 정함을 목적으로 한다.', 672);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5725, '제2조 (지문을 채취할 피의자의 범위)', 672);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5726, '제1조 (목적) 이 규칙은 국제형사사법공조법(이하 "법"이라 한다) 제40조의 규정에 의하여 영장발부, 증거물의 인도허가결정, 증인신문 등의 절차를 정함을 목적으로 한다.', 673);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5727, '제2조 (증거물의 인도허가청구서의 기재사항)', 673);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5728, '제3조 (자료의 제출)', 673);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5729, '제4조 (인도허가에 관한 결정) 법원은 증거물이 제출된 사건의 재판에 지장이 없다고 인정한 때에 한하여 결정으로 증거물의 인도를 허가할 수 있다.', 673);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5730, '제5조 (영장의 발부등) 법 제10조제1항 및 제17조제2항의 규정에 의한 영장의 발부, 법 제18조의 규정에 의한 증인신문 등의 절차에 관하여는 그 성질에 반하지 아니하는 한 형사소송규칙의 규정을 준용한다.', 673);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5731, '제1조(목적) 이 규칙은 「아동학대범죄의 처벌 등에 관한 특례법」 및 같은 법 시행령의 시행에 필요한 사항을 규정함을 목적으로 한다.', 674);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5732, '제2조(친권상실청구 등)', 674);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5733, '제3조(현장출동)', 674);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5734, '제3조의2(조사)', 674);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5735, '제4조(피해아동에 대한 응급조치)', 674);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5736, '제5조(긴급임시조치)', 674);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5737, '제6조(임시조치의 청구)', 674);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5738, '제7조(임시조치의 변경)', 674);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5739, '제8조(검사의 결정 전 조사) 검사가 법 제25조제1항에 따라 보호관찰소의 장에게 결정 전 조사를 요구할 때에는 별지 제25호서식에 따르고, 법 제25조제4항에 따라 시ㆍ도지사, 시장ㆍ군수ㆍ구청장 또는 아동보호전문기관의 장에게 자료의 제출을 요구할 때에는 별지 제26호서식에 따른다. <개정 2020.9.28>', 674);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5740, '제9조(송치)', 674);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5741, '제9조의2(보호처분 결정의 집행) 법 제38조제2항에 따라 보호처분의 집행담당자가 아동학대행위자의 보호처분 이행상황에 대해 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 통보할 때에는 별지 제28호의2서식에 따른다.', 674);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5742, '제10조(보호처분의 변경 등)', 674);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5743, '제10조의2(피해아동보호명령의 청구 등)', 674);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5744, '제10조의3(피해아동보호명령의 취소와 종류변경 신청 등)', 674);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5745, '제11조(의무위반사실의 통보) 사법경찰관리, 보호관찰관, 수탁기관의 장 등은 법 제63조제1항제2호부터 제5호까지에 따른 의무위반사실을 알게 된 때에는 그 사실을 별지 제32호서식에 따라 관계 행정기관의 장에게 통보할 수 있다. <개정 2020.9.28>', 674);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5746, '제1조(목적) 이 법은 「형사소송법」 제245조의10제1항에 따라 사법경찰관리의 직무를 수행할 자와 그 직무범위를 정함을 목적으로 한다. <개정 2021.3.16>', 675);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5747, '제2조 삭제 <1981.12.31>', 675);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5748, '제3조(교도소장 등)', 675);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5749, '제4조(산림 보호에 종사하는 공무원) 산림청과 그 소속 기관(산림항공관리소는 제외한다), 특별시ㆍ광역시ㆍ특별자치시ㆍ도ㆍ특별자치도(이하 "특별시ㆍ광역시ㆍ도"라 한다) 및 시ㆍ군ㆍ구(자치구를 말한다. 이하 같다)에서 산림 보호를 위한 단속 사무를 전담할 자로서 그 소속 기관의 장이 관할 지방검찰청검사장에게 보고한 임업주사 및 임업주사보는 사법경찰관의 직무를, 임업서기 및 임업서기보는 사법경찰리의 직무를 수행한다. <개정 2010.5.4, 2015.8.11>', 675);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5750, '제5조(검사장의 지명에 의한 사법경찰관리) 다음 각 호에 규정된 자로서 그 소속 관서의 장의 제청에 의하여 그 근무지를 관할하는 지방검찰청검사장이 지명한 자 중 7급 이상의 국가공무원 또는 지방공무원 및 소방위 이상의 소방공무원은 사법경찰관의 직무를, 8급ㆍ9급의 국가공무원 또는 지방공무원 및 소방장 이하의 소방공무원은 사법경찰리의 직무를 수행한다. <개정 2010.1.18, 2010.5.4, 2011.7.14, 2011.7.21, 2012.1.17, 2012.6.1, 2013.3.23, 2014.12.30, 2015.8.11, 2016.1.6, 2016.5.29, 2016.12.20, 2017.7.26, 2017.12.19, 2018.12.18, 2019.12.10, 2020.12.8, 2021.6.15, 2021.8.17, 2021.11.30, 2022.4.26, 2023.3.4, 2023.5.16, 2023.7.18, 2024.1.16, 2024.2.13, 2025.3.18>', 675);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5751, '제6조(직무범위와 수사 관할) 제4조와 제5조에 따라 사법경찰관리의 직무를 수행할 자의 직무범위와 수사 관할은 다음 각 호에 규정된 범죄로 한정한다. <개정 2008.12.31, 2009.4.22, 2009.6.9, 2010.1.1, 2010.2.4, 2010.5.4, 2011.4.28, 2011.5.19, 2011.5.30, 2011.7.21, 2011.7.28, 2011.8.4, 2011.9.15, 2012.1.17, 2012.2.1, 2012.6.1, 2013.6.4, 2013.7.30, 2014.12.30, 2015.2.3, 2015.8.11, 2015.12.22, 2016.1.6, 2016.5.29, 2016.12.20, 2017.1.17, 2017.12.19, 2018.12.18, 2019.4.2, 2019.8.27, 2020.1.29, 2020.12.8, 2021.8.17, 2021.11.30, 2023.7.18, 2023.8.8, 2024.1.16, 2024.3.19, 2025.3.18>', 675);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5752, '제6조의2(근로감독관 등)', 675);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5753, '제7조(선장과 해원 등)', 675);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5754, '제7조의2(국립공원공단 임직원) 국립공원공단 또는 그 분사무소에 근무하는 임직원으로서 국립공원공단이사장의 추천에 의하여 그 근무지를 관할하는 지방검찰청검사장이 지명한 자 중 임원 및 분사무소의 장은 관할 공원구역에서 발생하는 「경범죄 처벌법」 제6조제1항에 따른 범칙행위 중 같은 법 제3조제1항제11호, 제12호, 제15호, 제17호, 제19호부터 제21호까지, 제23호부터 제25호까지, 제27호부터 제29호까지, 제32호, 제36호 및 제37호에 해당하는 위반행위에 해당하는 범죄의 현행범에 관하여 사법경찰관의 직무를, 그 외의 직원은 그 범죄에 관하여 사법경찰리의 직무를 수행한다. <개정 2008.12.31, 2012.3.21, 2018.10.16>', 675);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5755, '제7조의3(금융감독원 직원)', 675);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5756, '제8조 삭제 <2020.12.15>', 675);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5757, '제9조(군사법경찰관리)', 675);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5758, '제10조(자치경찰공무원) 「제주특별자치도 설치 및 국제자유도시 조성을 위한 특별법」에 따른 자치경찰공무원 중 자치경무관ㆍ자치총경ㆍ자치경정ㆍ자치경감ㆍ자치경위는 제주특별자치도의 관할 구역에서 발생하는 범죄 가운데 이 법 제6조제5호(제5조제6호 및 제7호에 해당하는 자의 소관만 해당한다)ㆍ제6호ㆍ제7호ㆍ제11호ㆍ제13호ㆍ제15호ㆍ제18호ㆍ제19호ㆍ제21호ㆍ제22호ㆍ제24호ㆍ제25호ㆍ제26호ㆍ제28호ㆍ제29호ㆍ제31호ㆍ제32호 및 제41호부터 제46호까지의 범죄와 「제주특별자치도 설치 및 국제자유도시 조성을 위한 특별법」 제471조ㆍ제473조 및 이와 관련되는 같은 법 제477조ㆍ제478조에 규정된 범죄에 관하여 사법경찰관의 직무를, 자치경사ㆍ자치경장ㆍ자치순경은 그 범죄에 관하여 사법경찰리의 직무를 수행한다. <개정 2010.5.4, 2015.7.24, 2015.8.11>', 675);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5759, '제11조(범죄경력조회 및 수사경력조회) 지방검찰청 검사장은 이 법에 따른 사법경찰관리 및 군사법경찰관리의 지명, 적격 여부 확인 등을 위하여 「형의 실효 등에 관한 법률」 제6조에 따른 범죄경력조회 및 수사경력조회를 할 수 있다.', 675);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5760, '제12조(사법경찰 직무 전담 부서 설치) 이 법에 따른 사법경찰관리의 소속 관서의 장은 사법경찰 직무의 효율적인 수행을 위하여 그 직무를 전담하는 부서를 설치할 수 있다.', 675);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5761, '제1조(목적) 이 규칙은 특정범죄신고자등보호법 및 동법시행령의 시행에 관하여 필요한 사항을 규정함을 목적으로 한다.', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5762, '제2조(범죄신고자등보좌인의 지정ㆍ취소 또는 교체신청) 특정범죄신고자등보호법(이하 "법"이라 한다) 제6조제1항 및 제5항제1호의 규정에 의한 범죄신고자등보좌인(이하 "보좌인"이라 한다)의 지정ㆍ취소 또는 교체신청은 별지 제1호서식에 의한다.', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5763, '제3조(보좌인의 지정ㆍ취소 또는 교체) 법 제6조제1항 및 제5항의 규정에 의한 보좌인의 지정ㆍ취소 또는 교체는 별지 제2호서식에 의한다.', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5764, '제4조(보좌인의 지정ㆍ취소 또는 교체의 허가) 법 제6조제7항의 규정에 의하여 사법경찰관이 보좌인을 지정ㆍ취소 또는 교체하고자 하는 때에는 별지 제3호서식에 의하여 검사의 허가를 얻어야 한다.', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5765, '제5조(보고) 법 제7조제2항의 규정에 의한 범죄신고자등 인적 사항 미기재사유의 보고는 별지 제4호서식에 의한다.', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5766, '제6조(신원관리카드의 작성) 법 제7조제3항의 규정에 의한 범죄신고자등신원관리카드(이하 "신원관리카드"라 한다)의 작성은 별지 제5호서식에 의한다.', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5767, '제7조(신원관리카드봉인봉투의 양식) 특정범죄신고자등보호법시행령(이하 "영"이라 한다) 제5조제1항의 규정에 의한 신원관리카드 봉인봉투는 별지 제6호서식에 의한다.', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5768, '제8조(신원관리카드의 인계 등)', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5769, '제9조(신원관리카드 등 서류의 보존기간) 신원관리카드를 관리하는 검사가 보관하는 신원관리카드 등 서류의 보존기간은 원사건기록의 보존기간으로 한다. 다만, 원사건기록의 보존기간보다 신변안전조치의 기간이 장기인 경우에는 그 신변안전조치의 종료일까지 신원관리카드 등 서류를 보존하여야 한다.', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5770, '제10조(신원관리카드의 열람허가신청 등)', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5771, '제11조(면담신청) 법 제9조제3항의 규정에 의한 면담신청은 별지 제10호서식에 의한다.', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5772, '제12조(면담신청사실 통지)', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5773, '제13조(이의신청 방법)', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5774, '제14조(신원관리카드의 작성 및 관리의 요청) 법 제11조제2항 후단의 규정에 의한 신원관리카드의 작성 및 관리의 요청은 이를 서면으로 하여야 한다. 다만, 검사가 출석한 공판정에서는 검사에게 구두로 이를 요청할 수 있다.', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5775, '제15조(신변안전조치의 지시 등) 법 제13조제1항 전단 및 영 제6조제4항의 규정에 의한 신변안전조치의 지시는 별지 제13호서식(앞면)에 의하고, 그 이행보고는 별지 제13호서식(뒷면)에 의한다.', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5776, '제16조(신변안전조치의 신청 등) 법 제13조제1항 전단의 규정에 의한 신변안전조치의 요청은 별지 제14호서식에 의하고, 법 제13조제2항 및 제3항의 규정에 의한 신변안전조치의 신청 또는 요청은 별지 제15호서식에 의한다.', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5777, '제17조(신변안전조치의 이행통보) 영 제8조제1항의 규정에 의한 신변안전조치의 이행통보는 별지 제16호서식에 의한다.', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5778, '제18조(구조금의 신청) 영 제10조의 규정에 의한 구조금의 신청은 별지 제17호서식에 의한다. 이 경우 가명으로 구조금을 신청하는 때에는 신원관리카드에 기재된 가명으로 하여야 한다.', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5779, '제19조(구조심의결과 통보) 범죄신고자등구조심의회(이하 "심의회"라 한다)가 영 제11조의 규정에 의하여 구조결정을 한 때에는 심의회의 간사는 신원관리카드를 관리하는 검사에게 별지 제18호서식에 의하여 범죄신고자등구조심의결과를 통보하여야 한다.', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5780, '제20조(구조결정서의 작성 등)', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5781, '제21조(구조금의 지급청구) 영 제19조의 규정에 의한 구조금의 지급청구는 별지 제22호서식에 의한다.', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5782, '제22조(장부 등의 비치) 심의회는 다음 각호의 장부 및 서류를 비치하여야 한다.', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5783, '제23조(법무부장관에의 보고) 심의회는 매분기말 다음달 5일까지 별지 제25호서식에 의한 범죄신고자등구조금지급분기보고서를 대검찰청을 경유하여 법무부장관에게 제출하여야 한다. 이 경우 제20조제1항의 규정에 의한 가구조결정서 또는 동조제2항의 규정에 의한 구조결정서 등본 1통을 첨부하여야 한다.', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5784, '제24조(주요변동상황의 통지신청 등) 법 제15조의 규정에 의한 피고인등에 관련된 주요변동상황의 통지신청은 별지 제26호서식에 의하고, 주요변동상황의 통지는 별지 제27호서식에 의한다.', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5785, '제25조(서식 등의 관리 등)', 676);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5786, '제1조(목적) 이 규칙은 「군에서의 형의 집행 및 군수용자의 처우에 관한 법률」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 677);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5787, '제2조(정의) 이 규칙에서 사용하는 용어의 뜻은 다음과 같다.', 677);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5788, '제3조(직무의 처리 등)', 678);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5789, '제4조(응급조치) 군교도관은 천재지변이나 그 밖의 위급한 사태가 발생하였을 때에는 군수용자의 생명과 안전을 위하여 필요한 응급조치를 할 수 있다.', 678);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5790, '제5조(군교도관에 대한 교육) 소장은 군교도관에게 직무수행에 필요한 교육과 훈련을 하여야 하고, 필요하다고 인정하는 경우에는 다른 기관에 위탁하여 교육을 실시할 수 있다.', 678);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5791, '제6조(군교도관회의)', 678);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5792, '제7조(의류의 지급기준)', 680);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5793, '제8조(침구 그 밖의 생활용품의 지급기준)', 680);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5794, '제9조(음식물의 지급기준) 법 제23조에 따라 군수용자에게 지급하는 구체적인 음식물의 지급기준은 「군인 급식 규정」에 따른 현역 군인의 급식기준에 따른다. <개정 2014.11.3>', 680);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5795, '제10조(임산부군수용자에 대한 특칙) 소장은 임산부인 군수용자가 있는 경우 군의관의 의견을 들어 필요한 양의 쌀밥ㆍ죽 등의 주식과 특별히 마련된 부식을 지급할 수 있다.', 680);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5796, '제11조(자비구매물품의 종류 등)', 681);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5797, '제12조(구매허가 및 신청제한)', 681);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5798, '제13조(우선 공급) 소장은 교도작업제품(군교정시설 안에서 군수용자에게 부과된 작업에 따라 생산된 물품을 말한다)으로서 자비구매물품으로 적합한 것은 우선하여 공급할 수 있다.', 681);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5799, '제14조(제품 검수)', 681);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5800, '제15조(주요사항 고지 등)', 681);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5801, '제16조(교부금품의 허가)', 681);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5802, '제17조(의료설비의 기준)', 682);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5803, '제18조(비상의료용품 기준)', 682);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5804, '제19조(종교행사의 종류) 법 제46조에 따른 종교행사의 종류는 다음 각 호와 같다.', 684);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5805, '제20조(종교행사의 방법)', 684);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5806, '제21조(종교행사의 참석대상) 군수용자는 자신이 신봉하는 종교행사에 참석할 수 있다. 다만, 소장은 군수용자가 다음 각 호의 어느 하나에 해당하는 경우에는 종교행사의 참석을 제한할 수 있다. <개정 2014.11.3>', 684);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5807, '제22조(종교상담 등)', 684);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5808, '제23조(종교물품 등의 개인 소지) 소장은 군수용자의 신앙생활에 필요하다고 인정하는 경우에는 다음 각 호의 어느 하나에 해당하는 경우를 제외하고 외부에서 제작된 휴대용 종교서적 및 성물을 군수용자가 소지하게 할 수 있다.', 684);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5809, '제24조(구독신청 범위 및 수량) 군수용자가 법 제48조에 따라 구독을 신청할 수 있는 신문ㆍ잡지 또는 도서(이하 이 절에서 "신문등"이라 한다)의 범위와 수량은 군교정시설의 보관범위 및 군수용자의 소지범위에서 신문은 월 3종류 이내로, 도서(잡지를 포함한다)는 월 10권 이내로 한다. 다만, 소장은 군수용자의 지식 함양 및 교양 습득에 특히 필요하다고 인정하는 경우에는 신문등의 신청 수량을 늘릴 수 있다.', 685);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5810, '제25조(구독허가의 취소) 소장은 신문등을 구독하는 군수용자가 다음 각 호의 어느 하나에 해당하는 경우에는 구독의 허가를 취소할 수 있다.', 685);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5811, '제26조(소유자 불명 도서) 소장은 소유자 명의가 분명하지 아니한 도서는 회수하여 비치도서로 전환하거나 폐기할 수 있다.', 685);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5812, '제27조(방송의 기본원칙)', 686);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5813, '제28조(방송설비)', 686);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5814, '제29조(방송편성시간) 소장은 군수용자의 건강과 일과시간 등을 고려하여 1일 6시간 이내에서 방송편성시간을 정한다. 다만, 토요일ㆍ공휴일, 작업ㆍ교육실태 및 군수용자의 특성을 고려하여 방송편성시간을 조정할 수 있다.', 686);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5815, '제30조(방송프로그램)', 686);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5816, '제31조(군수용자 준수사항 등)', 686);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5817, '제31조의2(서신검열 등의 대상) 영 제60조제1항제1호 및 영 제61조제1항제4호에서 "마약류사범이나 조직폭력사범 등 국방부령으로 정하는 군수용자"란 다음 각 호의 어느 하나에 해당하는 군수용자를 말한다.', 687);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5818, '제32조(처우등급 심사기준) 영 제77조에 따라 군수형자에게 부여하는 처우등급은 뉘우친 정도, 품행, 책임감, 작업등급 및 교육ㆍ훈련성적을 기준으로 심사한다.', 690);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5819, '제33조(심사의 종류) 처우등급 심사는 다음 각호와 같이 구분하여 실시한다.', 690);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5820, '제34조(정기심사)', 690);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5821, '제35조(형기의 3분의 1 심사) 형기의 3분의 1 심사는 다음 각 호의 구분에 따라 실시한다.', 690);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5822, '제36조(특별심사)', 690);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5823, '제37조(처우등급) 군수형자의 처우등급은 다음 각 호와 같다.', 690);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5824, '제38조(처우등급의 부여) 군수형자의 처우등급은 제32조에 따른 처우등급 심사기준에 따라 군교도관회의 의결로 결정한다.', 690);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5825, '제39조(처우등급의 변경)', 690);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5826, '제40조(수형태도ㆍ실적 관찰표의 제출) 군교도관은 처우등급 심사일 1주일 전까지 담당하고 있는 군수형자의 수형생활 태도와 작업ㆍ교육 실적을 별지 제1호서식의 수용태도ㆍ실적 관찰표에 기록하여 소장에게 제출하여야 한다.', 690);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5827, '제41조(처우등급심사표의 관리 등)', 690);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5828, '제42조(처우등급 심사의 통지) 소장은 처우등급 심사에 따라 군수형자의 처우등급을 승급시키거나 강등하였을 때에는 그 사실을 해당 군수형자를 담당하는 군교도관에게 알려야 하고, 군교도관은 그 사실을 군수형자에게 알려야 한다.', 690);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5829, '제43조(재수용 군수형자의 처우등급 부여 등)', 690);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5830, '제44조(일반교도소 이송 시 통보사항) 소장은 법 제20조에 따라 군수형자를 일반교도소나 구치소로 이송할 때에는 해당 군수형자의 수형생활 또는 처우 등에 관한 사항을 통보하여야 한다.', 690);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5831, '제45조(물품 지급) 소장은 군수형자의 처우등급에 따라 물품에 차이를 두어 지급할 수 있다. 다만, 주식ㆍ부식ㆍ음료 그 밖에 건강유지에 필요한 물품은 그러하지 아니하다.', 691);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5832, '제46조(봉사원 선정)', 691);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5833, '제47조(자치생활)', 691);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5834, '제48조(접견) 군수형자의 처우등급별 접견의 허용횟수는 다음 각 호와 같다.', 691);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5835, '제49조(접견장소) 소장은 처우등급 1급인 군수형자에 대해서는 국방부장관이 정하는 바에 따라 접촉차단시설이 설치된 장소(이하 "접견실"이라 한다) 외의 적당한 곳에서 접견하도록 할 수 있다. 다만, 처우상 특히 필요하다고 인정하는 경우에는 1급의 군수형자 외의 군수형자에 대해서도 이를 허용할 수 있다.', 691);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5836, '제50조(가족 만남의 날 행사 등)', 691);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5837, '제51조(전화통화 등)', 691);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5838, '제52조(교육ㆍ작업 등의 지도 보조) 소장은 처우등급 2급 이상인 군수형자 중에서 교육ㆍ작업 등의 성적이 우수하고 관련 기술이 있는 사람에게 군교도관의 작업 지도를 보조하게 할 수 있다.', 691);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5839, '제53조(개인작업)', 691);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5840, '제54조(외부 직업훈련)', 691);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5841, '제55조(교육대상자 선발 등)', 693);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5842, '제56조(교육대상자 선발 취소 등)', 693);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5843, '제57조(교육ㆍ훈련과정) 법 제53조에 따라 군교도소에서 실시하는 교육ㆍ훈련은 다음 각 호의 과정으로 한다.', 693);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5844, '제58조(검정고시반 설치 및 운영)', 693);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5845, '제59조(방송통신고등학교 교육과정 설치 및 운영)', 693);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5846, '제60조(정보화 교육과정 설치 및 운영) 소장은 군수형자에게 지식정보사회에 적응할 수 있는 교육기회를 부여하기 위하여 정보화 교육과정을 설치ㆍ운영할 수 있다.', 693);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5847, '제61조(군사교육훈련과정)', 693);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5848, '제62조(교육시간 등) 제57조 각 호에 따른 교육ㆍ훈련과정의 총교육시간, 교육과목, 학급편성 및 교육평가 등에 관한 사항은 국방부조사본부장이 정한다. <개정 2014.11.3>', 693);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5849, '제63조(교과서 등의 대여 등) 소장은 교육ㆍ훈련과정에 선발된 군수형자에게 교과서, 참고서 그 밖의 학용품을 대여하거나 지급할 수 있다.', 693);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5850, '제64조(교관) 제57조에 따른 교육ㆍ훈련은 소장이 소속 장교ㆍ준사관ㆍ부사관 및 군무원 중에서 임명한 교관 및 조교가 담당한다.', 693);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5851, '제65조(교육평가 등)', 693);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5852, '제66조(상장의 수여) 소장은 각 교육ㆍ훈련과정을 수료한 군수형자 중에서 성적이 우수하여 다른 사람의 모범이 되는 사람에게는 별지 제3호서식의 상장을 수여한다.', 693);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5853, '제67조(비치서류) 군교도소에는 각 교육ㆍ훈련과정별로 별지 제4호서식의 출석부, 별지 제5호서식의 학적부 및 교안을 작성ㆍ비치하여야 한다.', 693);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5854, '제68조(교육실시결과의 보고) 소장은 연 1회 교육ㆍ훈련 실시결과를 국방부조사본부장에게 보고하여야 한다. <개정 2014.11.3>', 693);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5855, '제69조(교화프로그램의 종류) 교화프로그램의 종류는 다음 각 호와 같다.', 694);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5856, '제70조(문화프로그램) 소장은 군수형자의 인성 함양, 자아존중감 회복 등을 위하여 음악ㆍ미술ㆍ독서ㆍ원예 등 다양한 문화예술관련 프로그램을 도입하거나 개발하여 실시할 수 있다.', 694);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5857, '제71조(문제행동 예방프로그램) 소장은 군수형자의 죄명ㆍ죄질 등을 구분하여 그에 따른 심리측정ㆍ평가ㆍ진단ㆍ치료 등의 문제행동예방프로그램을 도입하거나 개발하여 실시할 수 있다.', 694);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5858, '제72조(가족관계 회복프로그램)', 694);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5859, '제73조(교화상담)', 694);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5860, '제74조(교화프로그램 운영방법)', 694);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5861, '제75조(작업의 종류 및 시간)', 696);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5862, '제76조(작업종류의 변경 금지) 소장은 군수형자에게 일정한 작업을 부과하였을 때에는 특별한 이유가 없는 한 그 작업종류를 변경하여서는 아니 된다.', 696);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5863, '제77조(작업등급)', 696);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5864, '제78조(외부통근작업자의 선정기준)', 696);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5865, '제79조(선정 취소) 소장은 외부통근자가 법령을 위반하는 행위를 하거나 국방부장관 또는 소장이 정하는 준수사항을 위반한 경우에는 외부통근자 선정을 취소할 수 있다.', 696);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5866, '제80조(외부통근자 교육) 소장은 외부통근자로 선정된 군수형자에게 자치활동, 행동수칙, 안전수칙, 작업기술 및 현장적응훈련에 대한 교육을 실시하여야 한다.', 696);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5867, '제81조(자치생활) 소장은 외부통근자의 사회 적응 능력을 기르고 원활한 사회복귀를 촉진하기 위하여 필요하다고 인정하는 경우에는 제47조에 따른 자치생활을 하게 할 수 있다.', 696);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5868, '제82조(작업도구의 파손 등에 대한 변상) 군수형자가 고의 또는 중대한 과실로 작업도구ㆍ원료ㆍ제품 또는 시설물을 파손하거나 잃어버렸을 때에는 그 군수형자에게 지급할 작업장려금으로 이를 변상하게 할 수 있다.', 696);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5869, '제83조(직업훈련 직종 선정 등)', 697);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5870, '제84조(직업훈련 대상자 선정기준) 소장은 다음 각 호의 요건을 갖춘 군수형자 중 군수형자의 의사(意思), 적성, 나이 및 학력 등을 고려하여 직업훈련 대상자로 선정할 수 있다.', 697);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5871, '제85조(직업훈련 대상자 선정의 제한) 소장은 제84조에도 불구하고 군수형자가 다음 각 호의 어느 하나에 해당하는 경우에는 직업훈련 대상자로 선정해서는 아니 된다.', 697);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5872, '제86조(직업훈련 대상자 이송)', 697);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5873, '제87조(직업훈련의 보류 및 취소 등)', 697);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5874, '제88조(귀휴 사유)', 699);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5875, '제89조(귀휴 심사)', 699);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5876, '제90조(설치) 법 제66조에 따른 군수형자의 귀휴허가에 관한 심사를 하기 위하여 군교도소에 귀휴심사위원회(이하 이 절에서 "위원회"라 한다)를 둔다.', 700);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5877, '제91조(기능) 위원회는 귀휴심사대상자(이하 이 장에서 "심사대상자"라 한다)에 대하여 다음 각 호의 사항을 심사한다.', 700);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5878, '제92조(구성)', 700);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5879, '제93조(위원의 임기 등)', 700);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5880, '제94조(위원장의 직무)', 700);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5881, '제95조(회의)', 700);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5882, '제96조(간사)', 700);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5883, '제97조(귀휴심사에 필요한 서류)', 700);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5884, '제98조(사실조회 등)', 700);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5885, '제99조(귀휴심사 보고) 소장이 귀휴대상자를 위원회의 심사에 회부한 때에는 그 명부를 작성하여 국방부조사본부장을 거쳐 국방부장관에게 보고하여야 한다. <개정 2014.11.3>', 700);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5886, '제100조(귀휴허가증 발급 등) 소장은 법 제66조제1항 및 제2항에 따라 귀휴를 허가하였을 때에는 별지 제11호서식의 귀휴허가부에 기록하고 귀휴허가를 받은 군수형자(이하 "귀휴자"라 한다)에게 별지 제12호서식의 귀휴허가증을 발급하여야 한다.', 701);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5887, '제101조(귀휴조건) 법 제66조제3항에 따라 소장이 귀휴자에게 붙일 수 있는 조건(이하 "귀휴조건"이라 한다)은 다음 각 호와 같다.', 701);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5888, '제102조(동행귀휴 등)', 701);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5889, '제103조(귀휴비용 등)', 701);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5890, '제104조(귀휴조건 위반에 대한 조치)', 701);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5891, '제105조(번호표 등 표시) 사형확정자의 번호표 및 거실표의 색상은 붉은색으로 한다. 다만, 소장은 사형확정자의 심리적 안정과 원만한 수용생활을 위하여 필요하다고 인정하는 경우에는 이와 달리 시행할 수 있다.', 702);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5892, '제106조(상담)', 702);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5893, '제107조(혼거수용 및 작업)', 702);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5894, '제108조(교화프로그램) 소장은 법 제77조제3항에 따라 사형확정자에 대하여 심리상담, 종교상담, 심리치료 등의 교화프로그램을 실시하는 경우에는 전문가에 의하여 집중적이고 지속적으로 이루어질 수 있도록 계획을 수립ㆍ시행하여야 한다.', 702);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5895, '제109조(전화통화) 소장은 사형확정자의 심리적 안정과 원만한 수용생활을 위하여 필요하다고 인정하는 경우에는 매월 3회 이내의 범위에서 전화통화를 허가할 수 있다.', 702);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5896, '제110조(교정장비의 종류) 교정장비의 종류는 다음 각 호와 같다.', 705);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5897, '제111조(교정장비의 관리)', 705);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5898, '제112조(교정장비 보유기준 등) 군교정시설별 교정장비의 보유기준 및 관리방법 등에 관하여 필요한 사항은 국방부장관이 정한다.', 705);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5899, '제113조(전자장비의 종류) 군교도관이 법 제81조에 따라 군수용자 또는 시설을 계호하는 경우에 사용할 수 있는 전자장비는 다음 각 호와 같다.', 706);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5900, '제114조(중앙통제실의 운영)', 706);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5901, '제115조(영상정보처리기기 설치)', 706);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5902, '제116조(거실에 있는 군수용자의 계호)', 706);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5903, '제117조(전자감지기의 설치) 전자감지기는 군교정시설의 벽둘레ㆍ울타리 그 밖에 군수용자의 도주와 외부로부터의 침입을 방지하기 위하여 필요한 장소에 설치한다. <개정 2020.2.3>', 706);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5904, '제118조(전자경보기의 사용) 전자경보기는 외부의료시설 입원, 이송ㆍ출정, 그 밖의 사유로 군교정시설 밖에서 군수용자를 계호하는 경우에 보호장비나 군수용자의 팔목 등에 부착하여 사용할 수 있다.', 706);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5905, '제119조(물품검색기 설치 및 사용)', 706);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5906, '제120조(증거수집장비의 사용) 군교도관은 군수용자가 사후(事後)에 입증이 필요하다고 인정되는 행위를 하거나 상태에 있는 경우에 군수용자에 대하여 증거수집장비를 사용할 수 있다.', 706);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5907, '제121조(녹음ㆍ녹화 기록물의 관리) 소장은 전자장비로 녹음ㆍ녹화된 기록물을 「공공기록물 관리에 관한 법률」에 따라 관리하여야 한다.', 706);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5908, '제122조(보호장비의 종류) 군교도관이 법 제85조제1항에 따라 사용할 수 있는 보호장비의 종류는 다음 각 호와 같다.', 707);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5909, '제123조(보호장비의 규격)', 707);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5910, '제124조(보호장비사용 명령) 소장은 영 제106조제1항에 따라 보호장비 사용을 명령하거나 승인하는 경우에는 보호장비의 종류 및 사용방법을 구체적으로 지정하여야 하며, 이 규칙에서 정한 방법 외의 방법으로 보호장비를 사용하게 하여서는 아니 된다.', 707);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5911, '제125조(수갑의 사용방법)', 707);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5912, '제126조(머리보호장비의 사용방법) 머리보호장비의 사용은 별표 7의 방법으로 한다. 이 경우 군수용자가 머리보호장비를 임의로 해제하지 못하도록 다른 보호장비를 함께 사용할 수 있다.', 707);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5913, '제127조(발목보호장비의 사용방법) 발목보호장비의 사용방법은 다음 각 호와 같다.', 707);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5914, '제128조(보호대의 사용방법) 보호대의 사용방법은 다음 각 호와 같다.', 707);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5915, '제129조(보호의자의 사용방법)', 707);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5916, '제130조(보호침대의 사용방법)', 707);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5917, '제131조(보호복의 사용방법)', 707);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5918, '제132조(포승의 사용방법)', 707);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5919, '제133조(둘 이상의 보호장비 사용) 하나의 보호장비로 사용목적을 달성할 수 없는 경우에는 둘 이상의 보호장비를 사용할 수 있다. 다만, 보호의자 및 보호침대는 다른 보호장비와 같이 사용할 수 없다.', 707);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5920, '제134조(보호장비 사용의 기록) 군교도관은 법 제84조제1항에 따라 보호장비를 사용하는 경우에는 별지 제17호서식의 보호장비사용 심사부에 사용내용을 기록하여야 한다. 다만, 법 제84조제1항제1호에 따라 보호장비를 사용하는 경우에는 호송계획서나 수용기록부의 내용 등으로 기록을 갈음할 수 있다.', 707);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5921, '제135조(군의관의 건강확인 등) 군의관은 법 제84조제3항에 따라 보호장비 착용 군수용자의 건강상태를 확인한 결과 특이사항을 발견한 경우에는 보호장비사용 심사부에 이를 기록하여야 한다.', 707);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5922, '제136조(보호장비의 계속 사용)', 707);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5923, '제137조(보호장비 사용의 해제)', 707);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5924, '제138조(보호장비 착용 군수용자의 관찰 등) 소장은 제122조제5호부터 제7호까지의 보호장비를 사용하거나 제8호의 보호장비를 별표 17의 방법으로 사용하게 하는 경우에는 군교도관으로 하여금 수시로 해당 군수용자의 상태를 확인하고 1시간마다 별지 제18호서식의 보호장비 착용자 관찰부에 확인사항을 기록하게 하여야 한다.', 707);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5925, '제139조(보안장비의 종류) 군교도관등이 법 제87조에 따라 강제력을 행사하는 경우에 사용할 수 있는 보안장비는 다음 각 호와 같다.', 708);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5926, '제140조(보안장비의 종류별 사용요건)', 708);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5927, '제141조(보안장비의 종류별 사용기준) 보안장비의 종류별 사용기준은 다음 각 호와 같다.', 708);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5928, '제142조(무기의 종류) 군교도관등이 법 제88조에 따라 사용할 수 있는 무기의 종류는 다음 각 호와 같다.', 709);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5929, '제143조(무기의 종류별 사용요건)', 709);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5930, '제144조(기관총의 설치 등) 기관총은 대공초소 또는 집중사격을 하기 가장 쉬운 장소에 설치하고, 유사시 즉시 사용할 수 있도록 충분한 인원의 사수(射手)ㆍ부사수ㆍ탄약수를 미리 지정하여야 한다.', 709);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5931, '제145조(총기의 사용절차) 군교도관등이 총기를 사용하는 경우에는 구두경고, 공포탄 발사, 위협사격, 조준사격의 순서에 따라야 한다. 다만, 상황이 긴급하여 시간적 여유가 없는 경우는 예외로 한다.', 709);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5932, '제146조(총기 교육 등)', 709);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5933, '제147조(포상)', 711);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5934, '제148조(규율) 군수용자가 법 제93조제6호에 따라 시설의 안전과 질서유지를 위하여 해서는 안 될 행위는 다음 각 호와 같다.', 712);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5935, '제149조(징벌사유의 경합) 법 제95조제2항제1호에 따른 징벌의 경중(輕重)은 제150조 각 호의 순서에 따른다. 이 경우 같은 조 제2호부터 제5호까지의 경우에는 각 목의 순서에 따른다.', 712);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5936, '제150조(징벌의 부과기준) 법 제95조제6항에 따른 징벌의 부과기준은 다음 각 호와 같다.', 712);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5937, '제151조(징벌 부과 시 고려사항) 제150조에 따라 징벌을 부과하는 경우에는 다음 각 호의 사항을 고려하여야 한다.', 712);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5938, '제152조(징벌대상자의 조사 시 준수사항) 군교도관이 법 제96조제1항에 따라 징벌사유에 해당하는 행위를 하였다고 의심할 만한 충분한 이유가 있는 군수용자(이하 "징벌대상자"라 한다) 또는 참고인 등을 조사하는 경우에는 다음 각 호의 사항을 준수하여야 한다.', 712);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5939, '제153조(조사기간)', 712);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5940, '제154조(징벌대상자의 처우제한 통지) 소장은 법 제96조제3항에 따라 조사기간 중 접견, 서신수수 또는 전화통화를 제한하는 경우에는 징벌대상자의 가족 등에게 그 사실을 알려야 한다. 다만, 징벌대상자가 원하지 아니하는 경우에는 그러하지 아니하다.', 712);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5941, '제155조(조사의 일시정지)', 712);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5942, '제156조(징벌의결의 요구)', 712);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5943, '제157조(징벌대상자에 대한 출석통지)', 712);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5944, '제158조(징벌위원회의 회의 및 의결)', 712);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5945, '제159조(집행절차) 소장은 징벌을 집행하려면 징벌의결의 내용과 징벌처분에 대한 불복방법을 기록한 별지 제25호서식의 징벌집행통지서에 징벌의결서 부본(副本)을 첨부하여 해당 군수용자에게 전달하여야 한다.', 712);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5946, '제160조(징벌의 집행순서)', 712);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5947, '제161조(징벌의 집행방법)', 712);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5948, '제162조(금치 집행 중 생활용품 등의 별도 보관) 소장은 금치 중인 군수용자가 생활용품 등으로 자살ㆍ자해할 우려가 있거나 군교정시설의 안전과 질서를 해칠 우려가 있는 경우에는 그 물품을 따로 보관하고 필요한 경우에만 이를 사용하게 할 수 있다.', 712);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5949, '제163조(징벌 집행 중인 군수용자의 상담) 소장은 징벌 집행 중인 군수용자에 대하여 군교도관 또는 교정참여인사와의 상담을 실시하여 징벌대상행위의 재발방지에 노력하여야 한다.', 712);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5950, '제164조(양형 참고자료의 통보) 소장은 군미결수용자에게 징벌을 부과하였을 때에는 징벌대상행위 등에 관한 양형 참고자료를 작성하여 관할 군검찰부 검찰관 또는 관할 군사법원에 통보할 수 있다.', 712);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5951, '제165조(기능) 법 제104조에 따른 가석방심사위원회(이하 이 편에서 "위원회"라 한다)는 법 제106조에 따른 가석방 적격심사와 「형법」 제75조에 따른 가석방의 취소 등에 관한 사항을 심사한다.', 714);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5952, '제166조(위원회의 구성 등)', 714);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5953, '제167조(위원의 임기) 제166조제1항제2호 및 제3호의 위원 임기는 2년으로 한다', 714);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5954, '제168조(위원장의 직무)', 714);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5955, '제169조(회의)', 714);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5956, '제170조(간사와 서기)', 714);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5957, '제171조(회의록의 작성)', 714);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5958, '제172조(수당 등) 위원회의 회의에 출석한 위원에 대해서는 예산의 범위에서 수당과 여비를 지급할 수 있다.', 714);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5959, '제173조(운영세칙) 이 규칙에 규정된 사항 외에 위원회의 운영에 관하여 필요한 사항은 위원회의 의결을 거쳐 위원장이 정한다.', 714);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5960, '제174조(가석방 적격심사의 기본원칙) 가석방 적격심사는 객관적 자료와 기준에 따라 공정하게 하여야 하며, 심사과정에서 알게 된 비밀은 누설하여서는 아니 된다.', 715);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5961, '제175조(심사 대상자의 선정)', 715);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5962, '제176조(사전조사) 소장은 군수형자의 가석방 적격심사를 위하여 다음 각 호의 사항을 미리 조사하여야 한다. 이 경우 특히 필요하다고 인정하면 군수형자, 그 가족, 그 밖의 사람과 면담 등을 할 수 있다.', 715);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5963, '제177조(사전조사 유의사항) 제176조에 따른 사전조사 중 가석방 적격심사와 관련하여 특히 피해자의 감정 및 합의 여부, 출소시 피해자에 대한 보복성 범죄 가능성 등에 유의하여야 한다.', 715);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5964, '제178조(사전조사 시기 등)', 715);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5965, '제179조(심사서류)', 715);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5966, '제180조(누범자에 대한 심사) 위원회가 같거나 유사한 죄로 2회 이상 징역형 또는 금고형의 집행을 받은 군수형자에 대하여 가석방 적격심사를 할 때에는 뉘우치는 정도, 노동능력 및 의욕, 근면성, 그 밖에 정상적인 업무에 취업할 수 있는 생활계획과 보호관계에 관하여 중점적으로 심사하여야 한다.', 715);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5967, '제181조(범죄 동기에 대한 심사)', 715);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5968, '제182조(사회의 감정에 대한 심사) 다음 각 호에 해당하는 군수형자를 심사하는 경우에는 특히 그 범죄에 대한 사회의 감정에 유의하여야 한다.', 715);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5969, '제183조(군에 대한 피해정도에 관한 심사) 범죄의 수단 및 결과를 심사하는 경우 다음 각 호에 따라 그 범죄에 의한 군의 피해정도에 유의하여야 한다.', 715);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5970, '제184조(재산범에 대한 심사)', 715);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5971, '제185조(관계 기관에 대한 조회)', 715);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5972, '제186조(감정의 촉탁)', 715);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5973, '제187조(재회부) 소장은 위원회에서 가석방 부적격으로 결정된 군수형자에 대하여 그 후 가석방을 하는 것이 적절하다고 인정하는 경우에는 다시 가석방 적격심사를 위원회에 회부할 수 있다.', 715);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5974, '제188조(가석방 결정)', 715);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5975, '제189조(가석방증) 「가석방자관리규정」 제4조제2항에 따른 가석방증은 별지 제31호서식에 따른다.', 715);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5976, '제190조(가석방의 보고) 소장은 군수형자를 가석방하였을 때에는 국방부장관이 발행한 가석방 허가서가 도착한 날짜와 실제 석방한 날짜를 국방부조사본부장을 거쳐 국방부장관에게 보고하여야 한다. <개정 2014.11.3>', 715);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5977, '제191조(재복무 대상 가석방자의 보호와 감독) 가석방자 중 군에 다시 복무할 사람에 대한 보호ㆍ감독의 업무는 소속 부대장이 수행한다. 다만, 소속 부대로 복귀할 때까지 가석방자에 대한 보호ㆍ감독업무는 소장이 한다.', 715);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5978, '제192조(가석방 취소) 가석방자가 가석방 기간 중 「가석방자관리규정」 제5조부터 제7조까지, 제10조, 제13조제1항 및 제14조부터 제16조까지의 규정에서 정한 준수사항을 위반하거나 관할 경찰서장의 명령 또는 조치를 따르지 아니하면 「형법」 제75조에 따라 가석방을 취소할 수 있다.', 716);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5979, '제193조(가석방 취소의 신청)', 716);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5980, '제194조(위원회의 심사)', 716);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5981, '제195조(남은 형의 집행)', 716);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5982, '제196조(가석방의 실효와 보고) 소장은 형법 제74조에 따라 가석방이 실효된 것을 알았을 때에는 지체 없이 남은 형의 집행에 필요한 조치를 하고, 그 결과를 국방부장관에게 보고하여야 한다.', 716);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5983, '제197조(추천) 소장이 교정위원을 추천하는 경우에는 별지 32호서식의 교정위원 추천서를 각군의 참모총장 또는 국방부조사본부장에게 제출하여야 한다. 다만, 재위촉의 경우에는 소장의 의견서로 그 제출을 갈음한다. <개정 2014.11.3>', 717);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5984, '제1조(목적) 이 규칙은 「형의 집행 및 수용자의 처우에 관한 법률」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 718);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5985, '제2조(정의) 이 규칙에서 사용하는 용어의 뜻은 다음과 같다. <개정 2010.5.31, 2014.11.17, 2020.8.5>', 718);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5986, '제3조(범죄횟수)', 718);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5987, '제4조(의류의 품목)', 721);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5988, '제5조(의류의 품목별 착용 시기 및 대상) 수용자 의류의 품목별 착용 시기 및 대상은 다음 각 호와 같다. <개정 2010.5.31, 2013.4.16, 2014.11.17>', 721);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5989, '제6조(침구의 품목) 수용자 침구의 품목은 이불 2종(솜이불ㆍ겹이불), 매트리스 2종(일반매트리스ㆍ환자매트리스), 담요 및 베개로 구분한다.', 721);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5990, '제7조(침구의 품목별 사용 시기 및 대상) 수용자 침구의 품목별 사용 시기 및 대상은 다음 각 호와 같다. <개정 2013.4.16>', 721);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5991, '제8조(의류ㆍ침구 등 생활용품의 지급기준)', 721);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5992, '제9조(의류ㆍ침구의 색채ㆍ규격) 수용자 의류ㆍ침구의 품목별 색채 및 규격은 법무부장관이 정한다.', 721);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5993, '제10조(주식의 지급) 소장이 「형의 집행 및 수용자의 처우에 관한 법률 시행령」(이하 "영"이라 한다) 제28조제2항에 따라 주식을 쌀과 보리 등 잡곡의 혼합곡으로 하거나 대용식을 지급하는 경우에는 법무부장관이 정하는 바에 따른다.', 722);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5994, '제11조(주식의 지급)', 722);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5995, '제12조(주식의 확보) 소장은 수용자에 대한 원활한 급식을 위하여 해당 교정시설의 직전 분기 평균 급식 인원을 기준으로 1개월분의 주식을 항상 확보하고 있어야 한다.', 722);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5996, '제13조(부식)', 722);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5997, '제14조(주ㆍ부식의 지급횟수 등)', 722);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5998, '제15조(특식 등 지급)', 722);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (5999, '제16조(자비구매물품의 종류 등)', 723);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6000, '제17조(구매허가 및 신청제한)', 723);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6001, '제18조(우선 공급) 소장은 교도작업제품(교정시설 안에서 수용자에게 부과된 작업에 의하여 생산된 물품을 말한다)으로서 자비구매물품으로 적합한 것은 제21조에 따라 지정받은 자비구매물품 공급자를 거쳐 우선하여 공급할 수 있다.', 723);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6002, '제19조(제품 검수)', 723);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6003, '제20조(주요사항 고지 등)', 723);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6004, '제21조(공급업무의 담당자 지정)', 723);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6005, '제22조(전달금품의 허가)', 723);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6006, '제23조(의료설비의 기준)', 724);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6007, '제24조(비상의료용품 기준)', 724);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6008, '제25조(전화통화의 허가)', 725);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6009, '제26조(전화이용시간)', 725);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6010, '제27조(통화허가의 취소) 소장은 다음 각 호의 어느 하나에 해당할 때에는 전화통화의 허가를 취소할 수 있다.', 725);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6011, '제28조(통화내용의 청취ㆍ녹음)', 725);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6012, '제29조(통화요금의 부담)', 725);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6013, '제29조의2(세부사항) 이 규칙에서 정한 사항 외에 전화통화의 허가범위, 통화내용의 청취ㆍ녹음 등에 필요한 세부사항은 법무부장관이 정한다.', 725);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6014, '제29조의3(소송사건의 대리인인 변호사 등의 접견 등 신청)', 725);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6015, '제30조(종교행사의 종류) 「형의 집행 및 수용자의 처우에 관한 법률」(이하 "법"이라 한다) 제45조에 따른 종교행사의 종류는 다음 각 호와 같다.', 727);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6016, '제31조(종교행사의 방법)', 727);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6017, '제32조(종교행사의 참석대상) 수용자는 자신이 신봉하는 종교행사에 참석할 수 있다. 다만, 소장은 다음 각 호의 어느 하나에 해당할 때에는 수용자의 종교행사 참석을 제한할 수 있다.', 727);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6018, '제33조(종교상담) 소장은 수용자가 종교상담을 신청하거나 수용자에게 종교상담이 필요한 경우에는 해당 종교를 신봉하는 교도관 또는 교정참여인사(법 제130조의 교정위원, 그 밖에 교정행정에 참여하는 사회 각 분야의 사람 중 학식과 경험이 풍부한 사람을 말한다)로 하여금 상담하게 할 수 있다. <개정 2020.8.5>', 727);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6019, '제34조(종교물품 등을 지닐 수 있는 범위)', 727);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6020, '제35조(구독신청 수량) 법 제47조에 따라 수용자가 구독을 신청할 수 있는 신문ㆍ잡지 또는 도서(이하 이 절에서 "신문등"이라 한다)는 교정시설의 보관범위 및 수용자가 지닐 수 있는 범위를 벗어나지 않는 범위에서 신문은 월 3종 이내로, 도서(잡지를 포함한다)는 월 10권 이내로 한다. 다만, 소장은 수용자의 지식함양 및 교양습득에 특히 필요하다고 인정하는 경우에는 신문등의 신청 수량을 늘릴 수 있다. <개정 2020.8.5>', 728);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6021, '제36조(구독허가의 취소 등)', 728);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6022, '제37조(방송의 기본원칙)', 729);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6023, '제38조(방송설비)', 729);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6024, '제39조(방송편성시간) 소장은 수용자의 건강과 일과시간 등을 고려하여 1일 6시간 이내에서 방송편성시간을 정한다. 다만, 토요일ㆍ공휴일, 작업ㆍ교육실태 및 수용자의 특성을 고려하여 방송편성시간을 조정할 수 있다.', 729);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6025, '제40조(방송프로그램)', 729);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6026, '제41조(수용자가 지켜야 할 사항 등)', 729);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6027, '제42조(임산부수용자 등에 대한 특칙) 소장은 임산부인 수용자 및 법 제53조에 따라 유아의 양육을 허가받은 수용자에 대하여 필요하다고 인정하는 경우에는 교정시설에 근무하는 의사(공중보건의사를 포함한다. 이하 "의무관"이라 한다)의 의견을 들어 필요한 양의 죽 등의 주식과 별도로 마련된 부식을 지급할 수 있으며, 양육유아에 대하여는 분유 등의 대체식품을 지급할 수 있다. <개정 2014.11.17>', 731);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6028, '제43조(전담교정시설)', 732);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6029, '제44조(수용거실)', 732);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6030, '제45조(주ㆍ부식 등 지급) 소장은 노인수용자의 나이ㆍ건강상태 등을 고려하여 필요하다고 인정하면 제4조부터 제8조까지의 규정, 제10조, 제11조, 제13조 및 제14조에 따른 수용자의 지급기준을 초과하여 주ㆍ부식, 의류ㆍ침구, 그 밖의 생활용품을 지급할 수 있다.', 732);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6031, '제46조(운동ㆍ목욕)', 732);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6032, '제47조(전문의료진 등)', 732);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6033, '제48조(교육ㆍ교화프로그램 및 작업)', 732);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6034, '제49조(정의) "장애인수용자"란 「장애인복지법 시행령」 별표 1의 제1호부터 제15호까지의 규정에 해당하는 사람으로서 시각ㆍ청각ㆍ언어ㆍ지체(肢體) 등의 장애로 통상적인 수용생활이 특히 곤란하다고 인정되는 수용자를 말한다. <개정 2013.4.16>', 733);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6035, '제50조(전담교정시설)', 733);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6036, '제51조(수용거실)', 733);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6037, '제52조(전문의료진 등) 장애인수형자 전담교정시설의 장은 장애인의 재활에 관한 전문적인 지식을 가진 의료진과 장비를 갖추도록 노력하여야 한다.', 733);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6038, '제53조(직업훈련) 장애인수형자 전담교정시설의 장은 장애인수형자에 대한 직업훈련이 석방 후의 취업과 연계될 수 있도록 그 프로그램의 편성 및 운영에 특히 유의하여야 한다.', 733);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6039, '제54조(준용규정) 장애인수용자의 장애정도, 건강 등을 고려하여 필요하다고 인정하는 경우 주ㆍ부식 등의 지급, 운동ㆍ목욕 및 교육ㆍ교화프로그램ㆍ작업에 관하여 제45조ㆍ제46조 및 제48조를 준용한다.', 733);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6040, '제55조(전담교정시설) 법 제57조제6항에 따라 법무부장관이 외국인수형자의 처우를 전담하도록 정하는 시설의 장은 외국인의 특성에 알맞은 교화프로그램 등을 개발하여 시행하여야 한다. <개정 2015.12.10>', 734);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6041, '제56조(전담요원 지정)', 734);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6042, '제57조(수용거실 지정)', 734);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6043, '제58조(주ㆍ부식 지급)', 734);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6044, '제59조(위독 또는 사망 시의 조치) 소장은 외국인수용자가 질병 등으로 위독하거나 사망한 경우에는 그의 국적이나 시민권이 속하는 나라의 외교공관 또는 영사관의 장이나 그 관원 또는 가족에게 이를 즉시 알려야 한다. <개정 2020.8.5>', 734);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6045, '제59조의2(전담교정시설)', 735);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6046, '제59조의3(수용거실)', 735);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6047, '제59조의4(의류) 법무부장관은 제4조 및 제5조에도 불구하고 소년수용자의 나이ㆍ적성 등을 고려하여 필요하다고 인정하는 경우 의류의 품목과 품목별 착용 시기 및 대상을 달리 정할 수 있다.', 735);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6048, '제59조의5(접견ㆍ전화) 소장은 소년수형자등의 나이ㆍ적성 등을 고려하여 필요하다고 인정하면 제87조 및 제90조에 따른 접견 및 전화통화 횟수를 늘릴 수 있다.', 735);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6049, '제59조의6(사회적 처우) 제92조제1항에도 불구하고 소장은 소년수형자등의 나이ㆍ적성 등을 고려하여 필요하다고 인정하면 소년수형자등에게 같은 항 각 호에 해당하는 활동을 허가할 수 있다. 이 경우 소장이 허가할 수 있는 활동에는 발표회 및 공연 등 참가 활동을 포함한다.', 735);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6050, '제59조의7(준용규정) 소년수용자의 나이ㆍ건강상태 등을 고려하여 필요하다고 인정하는 경우 주ㆍ부식 등의 지급, 운동ㆍ목욕, 전문의료진 등 및 작업에 관하여 제45조부터 제48조까지의 규정을 준용한다. <개정 2024.2.8>', 735);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6051, '제60조(이송ㆍ재수용 수형자의 개별처우계획 등)', 738);
