INSERT INTO balaw.jo (id, content, jang_id) VALUES (6146, '제152조(상담)', 752);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6147, '제153조(작업)', 752);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6148, '제154조(교화프로그램) 소장은 사형확정자에 대하여 심리상담, 종교상담, 심리치료 등의 교화프로그램을 실시하는 경우에는 전문가에 의하여 집중적이고 지속적으로 이루어질 수 있도록 계획을 수립ㆍ시행하여야 한다.', 752);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6149, '제155조(전담교정시설 수용) 사형확정자에 대한 교육ㆍ교화프로그램, 작업 등의 처우를 위하여 법무부장관이 정하는 전담교정시설에 수용할 수 있다.', 752);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6150, '제156조(전화통화) 소장은 사형확정자의 심리적 안정과 원만한 수용생활을 위하여 필요하다고 인정하는 경우에는 월 3회 이내의 범위에서 전화통화를 허가할 수 있다.', 752);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6151, '제157조(교정장비의 종류) 교정장비의 종류는 다음 각 호와 같다.', 755);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6152, '제158조(교정장비의 관리)', 755);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6153, '제159조(교정장비 보유기준 등) 교정장비의 교정시설별 보유기준 및 관리방법 등에 관하여 필요한 사항은 법무부장관이 정한다.', 755);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6154, '제160조(전자장비의 종류) 교도관이 법 제94조에 따라 수용자 또는 시설을 계호하는 경우 사용할 수 있는 전자장비는 다음 각 호와 같다.', 756);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6155, '제161조(중앙통제실의 운영)', 756);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6156, '제162조(영상정보처리기기 설치)', 756);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6157, '제163조(거실수용자 계호)', 756);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6158, '제164조(전자감지기의 설치) 전자감지기는 교정시설의 주벽ㆍ울타리, 그 밖에 수용자의 도주 및 외부로부터의 침입을 방지하기 위하여 필요한 장소에 설치한다.', 756);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6159, '제165조(전자경보기의 사용) 교도관은 외부의료시설 입원, 이송ㆍ출정, 그 밖의 사유로 교정시설 밖에서 수용자를 계호하는 경우 보호장비나 수용자의 팔목 등에 전자경보기를 부착하여 사용할 수 있다.', 756);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6160, '제166조(물품검색기 설치 및 사용)', 756);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6161, '제167조(증거수집장비의 사용) 교도관은 수용자가 사후에 증명이 필요하다고 인정되는 행위를 하거나 사후 증명이 필요한 상태에 있는 경우 수용자에 대하여 증거수집장비를 사용할 수 있다.', 756);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6162, '제168조(녹음ㆍ녹화 기록물의 관리) 소장은 전자장비로 녹음ㆍ녹화된 기록물을 「공공기록물 관리에 관한 법률」에 따라 관리하여야 한다.', 756);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6163, '제169조(보호장비의 종류) 교도관이 법 제98조제1항에 따라 사용할 수 있는 보호장비는 다음 각 호로 구분한다. <개정 2018.5.2, 2020.8.5>', 757);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6164, '제170조(보호장비의 규격)', 757);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6165, '제171조(보호장비 사용 명령) 소장은 영 제120조제1항에 따라 보호장비 사용을 명령하거나 승인하는 경우에는 보호장비의 종류 및 사용방법을 구체적으로 지정하여야 하며, 이 규칙에서 정하지 아니한 방법으로 보호장비를 사용하게 해서는 아니 된다.', 757);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6166, '제172조(수갑의 사용방법)', 757);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6167, '제173조(머리보호장비의 사용방법) 머리보호장비는 별표 9의 방법으로 사용하며, 수용자가 머리보호장비를 임의로 해제하지 못하도록 다른 보호장비를 함께 사용할 수 있다.', 757);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6168, '제174조(발목보호장비의 사용방법) 발목보호장비의 사용방법은 다음 각 호와 같다.', 757);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6169, '제175조(보호대의 사용방법) 보호대의 사용방법은 다음 각 호와 같다. <개정 2024.2.8>', 757);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6170, '제176조(보호의자의 사용방법)', 757);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6171, '제177조(보호침대의 사용방법)', 757);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6172, '제178조(보호복의 사용방법)', 757);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6173, '제179조(포승의 사용방법)', 757);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6174, '제180조(둘 이상의 보호장비 사용) 하나의 보호장비로 사용목적을 달성할 수 없는 경우에는 둘 이상의 보호장비를 사용할 수 있다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 다른 보호장비와 같이 사용할 수 없다.', 757);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6175, '제181조(보호장비 사용의 기록) 교도관은 법 제97조제1항에 따라 보호장비를 사용하는 경우에는 별지 제10호서식의 보호장비 사용 심사부에 기록해야 한다. 다만, 법 제97조제1항제1호에 따라 보호장비를 사용하거나 같은 항 제2호부터 제4호까지의 규정에 따라 양손수갑을 사용하는 경우에는 호송계획서나 수용기록부의 내용 등으로 그 기록을 갈음할 수 있다. <개정 2024.2.8>', 757);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6176, '제182조(의무관의 건강확인) 의무관은 법 제97조제3항에 따라 보호장비 착용 수용자의 건강상태를 확인한 결과 특이사항을 발견한 경우에는 별지 제10호 서식의 보호장비 사용 심사부에 기록하여야 한다.', 757);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6177, '제183조(보호장비의 계속사용)', 757);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6178, '제184조(보호장비 사용의 중단)', 757);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6179, '제185조(보호장비 착용 수용자의 관찰 등) 소장은 제169조제5호부터 제7호까지의 규정에 따른 보호장비를 사용하거나 같은 조 제8호의 보호장비를 별표 19의 방법으로 사용하게 하는 경우에는 교도관으로 하여금 수시로 해당 수용자의 상태를 확인하고 매 시간마다 별지 제11호서식의 보호장비 착용자 관찰부에 기록하게 하여야 한다. 다만, 소장은 보호장비 착용자를 법 제94조에 따라 전자영상장비로 계호할 때에는 별지 제9호서식의 거실수용자 영상계호부에 기록하게 할 수 있다. <개정 2013.4.16>', 757);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6180, '제186조(보안장비의 종류) 교도관이 법 제100조에 따라 강제력을 행사하는 경우 사용할 수 있는 보안장비는 다음 각 호와 같다. <개정 2014.11.17>', 758);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6181, '제187조(보안장비의 종류별 사용요건)', 758);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6182, '제188조(보안장비의 종류별 사용기준) 보안장비의 종류별 사용기준은 다음 각 호와 같다.', 758);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6183, '제189조(무기의 종류) 교도관이 법 제101조에 따라 사용할 수 있는 무기의 종류는 다음 각 호와 같다. <개정 2014.11.17>', 759);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6184, '제190조(무기의 종류별 사용요건)', 759);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6185, '제191조(기관총의 설치) 기관총은 대공초소 또는 집중사격이 가장 용이한 장소에 설치하고, 유사 시 즉시 사용할 수 있도록 충분한 인원의 사수(射手)ㆍ부사수ㆍ탄약수를 미리 지정하여야 한다.', 759);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6186, '제192조(총기의 사용절차) 교도관이 총기를 사용하는 경우에는 구두경고, 공포탄 발사, 위협사격, 조준사격의 순서에 따라야 한다. 다만, 상황이 긴급하여 시간적 여유가 없을 때에는 예외로 한다. <개정 2014.11.17>', 759);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6187, '제193조(총기 교육 등)', 759);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6188, '제194조(엄중관리대상자의 구분) 법 제104조에 따라 교정시설의 안전과 질서유지를 위하여 다른 수용자와의 접촉을 차단하거나 계호를 엄중히 하여야 하는 수용자(이하 이 장에서 "엄중관리대상자"라 한다)는 다음 각 호와 같이 구분한다.', 761);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6189, '제195조(번호표 등 표시)', 761);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6190, '제196조(상담)', 761);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6191, '제197조(작업 부과) 소장은 엄중관리대상자에게 작업을 부과할 때에는 법 제59조제3항에 따른 조사나 검사 등의 결과를 고려하여야 한다.', 761);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6192, '제198조(지정대상) 조직폭력수용자의 지정대상은 다음 각 호와 같다. <개정 2013.4.16, 2014.11.17>', 762);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6193, '제199조(지정 및 해제)', 762);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6194, '제200조(수용자를 대표하는 직책 부여 금지) 소장은 조직폭력수용자에게 거실 및 작업장 등의 봉사원, 반장, 조장, 분임장, 그 밖에 수용자를 대표하는 직책을 부여해서는 아니 된다.', 762);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6195, '제201조(수형자 간 연계활동 차단을 위한 이송) 소장은 조직폭력수형자가 작업장 등에서 다른 수형자와 음성적으로 세력을 형성하는 등 집단화할 우려가 있다고 인정하는 경우에는 법무부장관에게 해당 조직폭력수형자의 이송을 지체 없이 신청하여야 한다.', 762);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6196, '제202조(처우상 유의사항) 소장은 조직폭력수용자가 다른 사람과 접견할 때에는 외부 폭력조직과의 연계가능성이 높은 점 등을 고려하여 접촉차단시설이 있는 장소에서 하게 하여야 하며, 귀휴나 그 밖의 특별한 이익이 되는 처우를 결정하는 경우에는 해당 처우의 허용 요건에 관한 규정을 엄격히 적용하여야 한다.', 762);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6197, '제203조(특이사항의 통보) 소장은 조직폭력수용자의 편지 및 접견의 내용 중 특이사항이 있는 경우에는 검찰청, 경찰서 등 관계기관에 통보할 수 있다. <개정 2020.8.5>', 762);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6198, '제204조(지정대상) 마약류수용자의 지정대상은 다음 각 호와 같다. <개정 2014.11.17>', 763);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6199, '제205조(지정 및 해제)', 763);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6200, '제206조(마약반응검사)', 763);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6201, '제207조(물품전달 제한) 소장은 수용자 외의 사람이 마약류수용자에게 물품을 건네줄 것을 신청하는 경우에는 마약류 반입 등을 차단하기 위하여 신청을 허가하지 않는다. 다만, 다음 각 호의 어느 하나에 해당하는 물품을 건네줄 것을 신청한 경우에는 예외로 할 수 있다. <개정 2020.8.5>', 763);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6202, '제208조(보관품 등 수시점검) 담당교도관은 마약류수용자의 보관품 및 지니는 물건의 변동 상황을 수시로 점검하고, 특이사항이 있는 경우에는 감독교도관에게 보고해야 한다. <개정 2020.8.5>', 763);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6203, '제209조(재활교육)', 763);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6204, '제210조(지정대상) 관심대상수용자의 지정대상은 다음 각 호와 같다. <개정 2013.4.16, 2014.11.17>', 764);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6205, '제211조(지정 및 해제)', 764);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6206, '제212조 삭제 <2010.5.31>', 764);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6207, '제213조(수용동 및 작업장 계호 배치) 소장은 다수의 관심대상수용자가 수용되어 있는 수용동 및 작업장에는 사명감이 투철한 교도관을 엄선하여 배치하여야 한다. <개정 2013.4.16>', 764);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6208, '제214조(규율) 수용자는 다음 각 호에 해당하는 행위를 해서는 안 된다. <개정 2014.11.17, 2017.8.22, 2020.8.5, 2024.2.8>', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6209, '제214조의2(포상) 법 제106조에 따른 포상기준은 다음 각 호와 같다. <개정 2017.8.22>', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6210, '제215조(징벌 부과기준) 수용자가 징벌대상행위를 한 경우 부과하는 징벌의 기준은 다음 각 호의 구분에 따른다. <개정 2010.5.31, 2014.11.17, 2020.8.5, 2024.2.8>', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6211, '제215조의2(금치 집행 중 실외운동의 제한) 법 제112조제4항제4호에서 "법무부령으로 정하는 경우"란 다음 각 호와 같다.', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6212, '제216조(징벌부과 시 고려사항) 제215조의 기준에 따라 징벌을 부과하는 경우에는 다음 각 호의 사항을 고려하여야 한다. <개정 2018.12.28>', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6213, '제217조(교사와 방조)', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6214, '제218조(징벌대상행위의 경합)', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6215, '제219조(조사 시 지켜야 할 사항) 징벌대상행위에 대하여 조사하는 교도관이 징벌대상자 또는 참고인 등을 조사할 때에는 다음 각 호의 사항을 지켜야 한다. <개정 2020.8.5>', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6216, '제219조의2(징벌대상자에 대한 심리상담) 소장은 특별한 사유가 없으면 교도관으로 하여금 징벌대상자에 대한 심리상담을 하도록 해야 한다.', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6217, '제220조(조사기간)', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6218, '제221조(조사의 일시정지)', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6219, '제222조(징벌대상자 처우제한의 알림) 소장은 법 제110조제2항에 따라 접견ㆍ편지수수 또는 전화통화를 제한하는 경우에는 징벌대상자의 가족 등에게 그 사실을 알려야 한다. 다만, 징벌대상자가 알리기를 원하지 않는 경우에는 그렇지 않다. <개정 2020.8.5>', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6220, '제223조(징벌위원회 외부위원)', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6221, '제224조(징벌위원회 위원장) 법 제111조제2항에서 "소장의 바로 다음 순위자"는 「법무부와 그 소속기관 직제 시행규칙」의 직제순위에 따른다.', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6222, '제225조(징벌위원회 심의ㆍ의결대상) 징벌위원회는 다음 각 호의 사항을 심의ㆍ의결한다.', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6223, '제226조(징벌의결의 요구)', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6224, '제227조(징벌대상자에 대한 출석 통지)', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6225, '제228조(징벌위원회의 회의)', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6226, '제229조(집행절차)', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6227, '제230조(징벌의 집행순서)', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6228, '제231조(징벌의 집행방법)', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6229, '제232조(금치 집행 중 생활용품 등의 별도 보관) 소장은 금치 중인 수용자가 생활용품 등으로 자살ㆍ자해할 우려가 있거나 교정시설의 안전과 질서를 해칠 우려가 있는 경우에는 그 물품을 따로 보관하고 필요한 경우에만 이를 사용하게 할 수 있다.', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6230, '제233조(징벌집행 중인 수용자의 심리상담 등)', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6231, '제234조(징벌의 실효)', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6232, '제235조 삭제 <2020.8.5>', 765);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6233, '제236조(심사대상) 법 제119조의 가석방심사위원회(이하 이 편에서 "위원회"라 한다)는 법 제121조에 따른 가석방 적격 여부 및 이 규칙 제262조에 따른 가석방 취소 등에 관한 사항을 심사한다.', 768);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6234, '제237조(심사의 기본원칙)', 768);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6235, '제238조(위원장의 직무)', 768);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6236, '제239조(위원의 임명 또는 위촉) 법무부장관은 다음 각 호의 사람 중에서 위원회의 위원을 임명하거나 위촉한다.', 768);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6237, '제239조의2(위원의 해촉) 법무부장관은 위원회의 위원이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 위원을 해촉할 수 있다.', 768);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6238, '제240조(위원의 임기) 제239조제2호 및 제3호의 위원의 임기는 2년으로 하며, 한 차례만 연임할 수 있다. <개정 2016.6.28>', 768);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6239, '제241조(간사와 서기)', 768);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6240, '제242조(회의)', 768);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6241, '제243조(회의록의 작성)', 768);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6242, '제244조(수당 등) 위원회의 회의에 출석한 위원에게는 예산의 범위에서 수당과 여비를 지급할 수 있다.', 768);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6243, '제245조(적격심사신청 대상자 선정)', 769);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6244, '제246조(사전조사) 소장은 수형자의 가석방 적격심사신청을 위하여 다음 각 호의 사항을 사전에 조사해야 한다. 이 경우 조사의 방법에 관하여는 제70조를 준용한다. <개정 2010.5.31, 2020.8.5, 2024.2.8>', 769);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6245, '제247조(사전조사 유의사항) 제246조에 따른 사전조사 중 가석방 적격심사신청과 관련하여 특히 피해자의 감정 및 합의여부, 출소 시 피해자에 대한 보복성 범죄 가능성 등에 유의하여야 한다. <개정 2010.5.31>', 769);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6246, '제248조(사전조사 결과)', 769);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6247, '제249조(사전조사 시기 등)', 769);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6248, '제250조(적격심사신청)', 769);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6249, '제251조(재신청) 소장은 가석방이 허가되지 아니한 수형자에 대하여 그 후에 가석방을 허가하는 것이 적당하다고 인정하는 경우에는 다시 가석방 적격심사신청을 할 수 있다. <개정 2010.5.31>', 769);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6250, '제252조(누범자에 대한 심사) 위원회가 동일하거나 유사한 죄로 2회 이상 징역형 또는 금고형의 집행을 받은 수형자에 대하여 적격심사할 때에는 뉘우치는 정도, 노동 능력 및 의욕, 근면성, 그 밖에 정상적인 업무에 취업할 수 있는 생활계획과 보호관계에 관하여 중점적으로 심사하여야 한다. <개정 2010.5.31>', 770);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6251, '제253조(범죄동기에 대한 심사)', 770);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6252, '제254조(사회의 감정에 대한 심사) 다음 각 호에 해당하는 수형자에 대하여 적격심사할 때에는 특히 그 범죄에 대한 사회의 감정에 유의하여야 한다. <개정 2010.5.31>', 770);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6253, '제255조(재산범에 대한 심사)', 770);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6254, '제255조의2(심층면접)', 770);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6255, '제256조(관계기관 조회)', 770);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6256, '제257조(감정의 촉탁)', 770);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6257, '제258조(가석방 결정) 위원회가 법 제121조제2항에 따라 가석방의 적격 여부에 대한 결정을 한 경우에는 별지 제23호서식의 결정서를 작성하여야 한다. <개정 2010.5.31>', 770);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6258, '제259조(가석방증) 소장은 수형자의 가석방이 허가된 경우에는 주거지, 관할 경찰서 또는 보호관찰소에 출석할 기한 등을 기록한 별지 제24호서식의 가석방증을 가석방자에게 발급하여야 한다.', 770);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6259, '제260조(취소사유) 가석방자는 가석방 기간 중 「가석방자관리규정」 제5조부터 제7조까지, 제10조, 제13조제1항, 제15조 및 제16조에 따른 지켜야 할 사항 및 관할 경찰서장의 명령 또는 조치를 따라야 하며 이를 위반하는 경우에는 「형법」 제75조에 따라 가석방을 취소할 수 있다. <개정 2018.12.28, 2020.8.5>', 771);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6260, '제261조(취소신청)', 771);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6261, '제262조(취소심사)', 771);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6262, '제263조(남은 형기의 집행)', 771);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6263, '제263조의2(석방예정자의 수용이력 등 통보) 영 제143조제3항에 따른 석방예정자의 수용이력 통보서의 양식은 별지 제28호의2서식에 따르고, 석방예정자의 사회복귀에 관한 의견 통보서의 양식은 별지 제28호의3서식에 따른다.', 772);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6264, '제263조의3(사망 기록) 영 제148조에 따른 사망장의 양식은 별지 제28호의4서식에 따른다.', 773);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6265, '제264조(기능) 법 제129조제1항의 교정자문위원회(이하 이 편에서 "위원회"라 한다)의 기능은 다음 각 호와 같다. <개정 2019.10.22, 2022.2.7>', 774);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6266, '제265조(구성)', 774);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6267, '제266조(임기)', 774);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6268, '제267조(위원장의 직무)', 774);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6269, '제268조(회의)', 774);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6270, '제269조(지켜야 할 사항)', 774);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6271, '제270조(위원의 해촉) 법무부장관은 외부위원이 다음 각 호의 어느 하나에 해당하는 경우에는 지방교정청장의 건의를 받아 해당 위원을 해촉할 수 있다. <개정 2019.10.22, 2020.8.5>', 774);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6272, '제271조(간사)', 774);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6273, '제272조(수당) 지방교정청장은 위원회의 회의에 참석한 위원에게는 예산의 범위에서 수당을 지급할 수 있다. <개정 2019.10.22>', 774);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6274, '제1조(목적) 이 영은 「특정중대범죄 피의자 등 신상정보 공개에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 775);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6275, '제2조(촬영 방법) 검사와 사법경찰관은 「특정중대범죄 피의자 등 신상정보 공개에 관한 법률」(이하 "법"이라 한다) 제4조제5항(법 제5조제7항에서 준용하는 경우를 포함한다)에 따라 특정중대범죄사건의 피의자 또는 피고인(이하 "피의자등"이라 한다)의 얼굴을 촬영하는 경우에는 피의자등의 정면ㆍ왼쪽ㆍ오른쪽 얼굴 컬러사진을 촬영하여 전자기록으로 저장ㆍ보관해야 한다.', 775);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6276, '제3조(피의자의 의견진술)', 775);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6277, '제4조(피의자 신상정보 공개 결정의 통지 등)', 775);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6278, '제5조(피의자 신상정보 공개 방법 및 공개의 종료 등)', 775);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6279, '제6조(불기소처분 통보 등)', 775);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6280, '제7조(피고인의 신상정보 공개)', 775);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6281, '제8조(신상정보공개심의위원회)', 775);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6282, '제9조(민감정보 및 고유식별정보의 처리) 검사와 사법경찰관은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 민감정보나 같은 법 시행령 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 775);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6283, '제1조(목적) 이 규칙은 「전자장치 부착 등에 관한 법률」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다. <개정 2009.7.30, 2013.5.31, 2020.8.5>', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6284, '제2조 삭제 <2010.7.15>', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6285, '제3조(조사의 요청)', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6286, '제4조(부착명령청구의 방식)', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6287, '제5조(교도소장 등의 석방예정 통보) 법 제10조제2항, 제22조제5항, 제23조제3항, 영 제7조제5항, 제8조제5항, 제20조제2항 및 제27조제3항의 통보는 별지 제4호서식의 석방예정통보서에 따른다. 다만, 영 제7조제5항의 경우로서 전자장치가 부착된 사람(이하 "피부착자"라 한다)이 벌금 완납으로 석방되는 등의 긴급한 사유로 별지 제4호서식에 따른 통보가 곤란한 경우에는 유선으로 통보할 수 있다. <개정 2010.7.15, 2013.5.31, 2015.9.7, 2020.8.5>', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6288, '제6조(집행지휘)', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6289, '제7조(구금 통보 등) 영 제8조제2항, 제4항 및 제5항(영 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 통보는 각각 별지 제6호서식의 구금(구금해제 결정)통보서에 따른다. <개정 2013.5.31>', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6290, '제8조(부착명령 집행정지자의 이송 통보 등) 영 제9조(영 제21조 및 제23조에 따라 준용되는 경우를 포함한다) 및 제20조제1항의 통보는 별지 제7호서식의 부착명령 집행정지자(피부착결정자) 이송통보서에 따른다.', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6291, '제9조(일시분리 대장) 영 제10조제2항(영 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 일시분리 대장은 별지 제8호서식에 따른다.', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6292, '제10조(주거이전, 국내여행 및 출국 허가서 등)', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6293, '제10조의2(부착기간의 연장 등의 신청 등)', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6294, '제10조의3(치료기관 등의 지정)', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6295, '제10조의4(수용 중 생활실태자료 확보 등)', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6296, '제11조(수신자료 사용대장) 영 제14조(영 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 수신자료 사용대장은 별지 제22호서식에 따른다. <개정 2013.5.31>', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6297, '제11조의2(수신자료 열람 또는 조회)', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6298, '제11조의3(긴급 수신자료 열람 또는 조회)', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6299, '제11조의4(열람 또는 조회한 수신자료의 보존ㆍ폐기 등)', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6300, '제11조의5(수신자료 사용사건의 결과 통지) 영 제14조의5제1항에 따른 검사 또는 사법경찰관의 서면 통지는 별지 제34호서식에 따른다.', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6301, '제11조의6(보호관찰소의 장의 수사기관 통보 등) 영 제15조의2제2항에 따른 보호관찰소의 장의 수사기관에 대한 통보는 별지 제35호서식에 따른다.', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6302, '제11조의7(영상정보 열람사실의 통지)', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6303, '제12조(임시해제 신청서 등) 영 제16조제1항의 임시해제 신청(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다) 및 영 제18조제1항의 임시해제 취소 신청(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)은 각각 별지 제36호서식의 부착명령 임시해제(임시해제 취소) 신청서에 따른다. <개정 2013.5.31, 2020.8.5>', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6304, '제12조의2(임시해제의 심사ㆍ결정기준) 「보호관찰 등에 관한 법률」 제5조에 따른 보호관찰 심사위원회가 법 제18조제1항ㆍ제4항ㆍ제5항(법 제21조의8, 제27조 및 제31조에 따라 준용되는 경우를 포함한다) 및 영 제17조제1항(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)에 따라 임시해제를 심사ㆍ결정할 때에는 피부착자 또는 보호관찰대상자의 연령, 건강상태, 가족관계, 가정환경, 범죄경력, 집행기간, 준수사항의 이행정도, 재범위험성 평가결과 및 그 밖에 필요한 사항을 고려해야 한다. <개정 2020.8.5>', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6305, '제13조(결정서) 법 제18조제4항ㆍ제5항(법 제21조의8, 제27조 및 제31조에 따라 준용되는 경우를 포함한다) 및 영 제17조(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)에 따른 임시해제 결정과 법 제19조제1항(법 제21조의8, 제27조 및 제31조에 따라 준용되는 경우를 포함한다) 및 영 제18조제2항(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)에 따른 임시해제 취소 결정은 각각 별지 제37호서식의 부착명령(보호관찰명령) 임시해제(임시해제 취소) 결정서에 따른다. <개정 2020.8.5>', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6306, '제13조의2(보호관찰명령 청구의 방식)', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6307, '제13조의3(집행지휘)', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6308, '제13조의4(보호관찰기간의 연장 등 신청) 법 제21조의7에 따른 보호관찰소의 장의 보호관찰기간의 연장 또는 준수사항의 추가ㆍ변경ㆍ삭제의 신청은 별지 제41호서식에 따르고, 법 제21조의7에 따른 검사의 보호관찰기간의 연장 또는 준수사항의 추가ㆍ변경ㆍ삭제의 청구는 별지 제42호서식에 따른다.', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6309, '제13조의5(수용 중 생활실태 자료 확보 등) 법 제21조의8에 따라 준용되는 법 제15조제3항에 따른 보호관찰명령 집행을 위한 수용 중 생활실태 자료 확보 등에 관하여는 제10조의4를 준용한다.', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6310, '제14조(전자장치 부착대상자 통보 등)', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6311, '제14조의2(조사의 의뢰) 법 제31조의2제2항 및 영 제23조의2제1항에 따른 조사의 의뢰는 별지 제44호의2서식에 따른다.', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6312, '제14조의3(보석 피고인 신고서) 법 제31조의3제2항 및 영 제23조의4에 따른 신고서는 별지 제44호의3서식에 따른다.', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6313, '제14조의4(보석조건 이행 상황 통지) 법 제31조의4제1항 및 영 제23조의6에 따른 보석조건 이행 상황의 통지는 별지 제44호의4서식에 따른다.', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6314, '제14조의5(보석조건 위반 통지) 법 제31조의4제2항 및 영 제23조의7에 따른 보석조건 위반 통지는 별지 제44호의5서식에 따른다.', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6315, '제14조의6(스토킹행위자 신고서) 법 제31조의6제2항 및 영 제23조의11제1항에 따른 신고는 별지 제44호의6서식에 따른다.', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6316, '제14조의7(전자장치 부착 사실의 통지) 법 제31조의6제3항 각 호 외의 부분 및 영 제23조의13제1항에 따른 전자장치 부착 사실의 통지는 별지 제44호의7서식에 따른다.', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6317, '제14조의8(피해자 관련 사항의 통지) 법 제31조의6제3항 및 영 제23조의13제2항에 따른 피해자 관련 사항의 통지는 별지 제44호의8서식에 따른다.', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6318, '제14조의9(잠정조치 결정의 효력 상실 통지) 법 제31조의6제6항 또는 영 제23조의16에 따른 잠정조치 결정의 효력 상실 통지는 별지 제44호의9서식에 따른다.', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6319, '제14조의10(스토킹행위자 수신자료 사용대장) 영 제23조의17에 따른 스토킹행위자 수신자료 사용대장은 별지 제44호의10서식에 따른다.', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6320, '제15조(출소자등 통보서) 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제1호, 제3항제1호 및 영 제24조에 따른 출소자 등의 인적사항 등 통보는 별지 제45호서식의 출소자등 통보서에 따른다. <개정 2013.5.31>', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6321, '제16조(출석요구서) 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제5호에 따른 출석 요구는 별지 제46호서식의 출석요구서에 따른다. <개정 2013.5.31>', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6322, '제17조(구인영장 청구서 등)', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6323, '제18조(구인영장)', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6324, '제19조(부착명령 집행장)', 776);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6325, '제1조(목적) 이 법은 성매매, 성매매알선 등 행위 및 성매매 목적의 인신매매를 근절하고, 성매매피해자의 인권을 보호함을 목적으로 한다.', 777);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6326, '제2조(정의)', 777);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6327, '제3조(국가 등의 책무)', 777);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6328, '제4조(금지행위) 누구든지 다음 각 호의 어느 하나에 해당하는 행위를 하여서는 아니 된다.', 777);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6329, '제5조(다른 법률과의 관계) 이 법에서 규정한 사항에 관하여 「아동ㆍ청소년의 성보호에 관한 법률」 및 「대중문화예술산업발전법」에 특별한 규정이 있는 경우에는 그 법에서 정하는 바에 따른다. <개정 2014.1.28>', 777);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6330, '제6조(성매매피해자에 대한 처벌특례와 보호)', 778);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6331, '제7조(신고의무 등)', 778);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6332, '제8조(신뢰관계에 있는 사람의 동석)', 778);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6333, '제9조(심리의 비공개)', 778);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6334, '제10조(불법원인으로 인한 채권무효)', 778);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6335, '제11조(외국인여성에 대한 특례)', 778);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6336, '제12조(보호사건의 처리)', 779);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6337, '제13조(관할)', 779);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6338, '제14조(보호처분의 결정 등)', 779);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6339, '제15조(보호처분의 기간) 제14조제1항제1호ㆍ제2호 및 제4호에 따른 보호처분 기간은 6개월을, 같은 항 제3호에 따른 사회봉사ㆍ수강명령은 100시간을 각각 초과할 수 없다.', 779);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6340, '제16조(보호처분의 변경)', 779);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6341, '제17조(다른 법률의 준용)', 779);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6342, '제18조(벌칙)', 780);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6343, '제19조(벌칙)', 780);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6344, '제20조(벌칙)', 780);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6345, '제21조(벌칙)', 780);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6346, '제22조(범죄단체의 가중처벌) 제18조 또는 제19조에 규정된 범죄를 목적으로 단체 또는 집단을 구성하거나 그러한 단체 또는 집단에 가입한 사람은 「폭력행위 등 처벌에 관한 법률」 제4조의 예에 따라 처벌한다.', 780);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6347, '제23조(미수범) 제18조부터 제20조까지에 규정된 죄의 미수범은 처벌한다.', 780);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6348, '제24조(징역과 벌금의 병과) 제18조제1항, 제19조, 제20조 및 제23조(제18조제2항부터 제4항까지에 규정된 죄의 미수범은 제외한다)의 경우에는 징역과 벌금을 병과할 수 있다.', 780);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6349, '제25조(몰수 및 추징) 제18조부터 제20조까지에 규정된 죄를 범한 사람이 그 범죄로 인하여 얻은 금품이나 그 밖의 재산은 몰수하고, 몰수할 수 없는 경우에는 그 가액(價額)을 추징한다.', 780);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6350, '제26조(형의 감면) 이 법에 규정된 죄를 범한 사람이 수사기관에 신고하거나 자수한 경우에는 형을 감경하거나 면제할 수 있다.', 780);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6351, '제27조(양벌규정) 법인의 대표자나 법인 또는 개인의 대리인, 사용인, 그 밖의 종업원이 그 법인 또는 개인의 업무에 관하여 제18조부터 제23조까지의 어느 하나에 해당하는 위반행위를 하면 그 행위자를 벌하는 외에 그 법인 또는 개인에게도 해당 조문의 벌금형을 과(科)하고, 벌금형이 규정되어 있지 아니한 경우에는 1억원 이하의 벌금에 처한다. 다만, 법인 또는 개인이 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다.', 780);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6352, '제28조(보상금)', 780);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6353, '제1조(목적) 이 영은 「성매매알선 등 행위의 처벌에 관한 법률」에서 위임된 사항과 그 시행에 관하여 필요한 사항을 규정함을 목적으로 한다. <개정 2019.3.5>', 781);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6354, '제2조(중대한 장애가 있는 사람의 범위) 「성매매알선 등 행위의 처벌에 관한 법률」(이하 "법"이라 한다) 제2조제1항제3호 나목ㆍ제4호 다목, 제8조제3항 및 제18조제2항제2호에서 "대통령령으로 정하는 중대한 장애가 있는 사람"이란 별표에서 규정한 사람 또는 이에 준하는 사람으로서 타인의 보호ㆍ감독이 없으면 정상적으로 일상생활 또는 사회생활을 영위하기 어렵고, 이로 인하여 타인의 부당한 압력이나 기망(欺罔)ㆍ유인에 대한 저항능력이 취약한 사람을 말한다. <개정 2019.3.5>', 781);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6355, '제3조(증인신문의 비공개 신청) 법 제9조제2항의 규정에 의한 증인신문의 비공개신청은 법정(증인신문이 진행 중인 경우를 포함한다)에서 구두로도 할 수 있다.', 781);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6356, '제4조(보호처분의 필요성 등의 판단기준) 법원과 검사는 성매매를 한 자에 대한 보호처분의 필요성, 종류 및 기간 등을 판단함에 있어서 성매매 동기, 행위자의 성행(性行) 외에 행위자의 직장, 가족관계, 재범의 위험성 및 보호처분의 효과 등 여러 정황을 충분히 참작하여야 한다.', 781);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6357, '제5조(보상금의 지급신청)', 781);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6358, '제6조(보상금의 지급)', 781);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6359, '제7조 삭제 <2008.10.20>', 781);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6360, '제8조(보상금의 지급 제한) 다음 각호의 1에 해당하는 경우에는 보상금을 지급하지 아니한다.', 781);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6361, '제9조(보상금의 환수) 법무부장관은 보상금을 지급한 후에 허위 그 밖의 부정한 방법으로 보상금을 지급받거나 제8조 각호의 사유가 있음이 확인된 경우에는 보상금을 환수할 수 있다.', 781);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6362, '제10조(보상금 지급조서의 작성 등) 법무부장관은 보상금을 지급하는 때에는 법무부령이 정하는 바에 의하여 보상금 지급조서 및 지급대장을 작성ㆍ비치하고 지급상황을 기재하여야 한다.', 781);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6363, '제1조(목적) 이 규칙은 「성매매알선 등 행위의 처벌에 관한 법률」과 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다. <개정 2011.1.25>', 782);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6364, '제2조(보상금의 지급원칙)', 782);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6365, '제3조(신고관련 사항의 누설금지) 보상금의 지급업무에 관여하는 자는 신고인의 인적사항 등 신고와 관련한 사항이 외부에 누설되지 아니하도록 유의하여야 한다.', 782);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6366, '제4조(보상금의 지급신청)', 782);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6367, '제5조(익명 또는 가명신청)', 782);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6368, '제6조 삭제 <2011.1.25>', 782);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6369, '제7조 삭제 <2011.1.25>', 782);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6370, '제8조 삭제 <2011.1.25>', 782);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6371, '제9조(의견청취 등) 법무부장관은 다음 각 호의 사항을 결정하기 위하여 필요한 때에는 신청인 또는 관계인의 의견을 들을 수 있고, 관계기관에 대하여 필요한 자료의 제출을 요청할 수 있다. <개정 2011.1.25>', 782);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6372, '제10조 삭제 <2011.1.25>', 782);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6373, '제11조 삭제 <2011.1.25>', 782);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6374, '제12조 삭제 <2011.1.25>', 782);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6375, '제13조(보상금의 지급기준)', 782);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6376, '제14조(보상금의 분할지급) 신고를 한 사람이 2명 이상인 경우에는 각자의 공로, 신고인들 간의 합의내용 등을 고려하여 신고인 각자에게 보상금을 분할하여 지급할 수 있다. <개정 2022.2.7>', 782);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6377, '제15조(보상금의 지급결정)', 782);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6378, '제16조(보상금의 지급절차)', 782);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6379, '제17조(보상금의 지급시기에 관한 특례)', 782);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6380, '제18조(보상금지급조서의 작성 등)', 782);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6381, '제19조(익명 또는 가명신청 관련 서류의 작성)', 782);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6382, '제1조(목적) 이 법은 군수형자의 교정ㆍ교화와 건전한 사회복귀를 도모하고, 군수용자의 처우와 권리 및 군교정시설의 운영에 필요한 사항을 규정함을 목적으로 한다.', 783);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6383, '제2조(용어의 정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다.', 783);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6384, '제3조(적용 범위) 이 법은 군교정시설의 구내와 군교도관(이하 "교도관"이라 한다)이 군수용자를 계호하고 있는 그 밖의 장소로서 교도관의 통제가 필요한 공간에 대하여 적용한다.', 783);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6385, '제4조(군교정시설의 설치 등)', 783);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6386, '제5조(인권의 존중) 이 법을 집행할 때 군수용자의 인권을 최대한 존중하여야 한다.', 783);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6387, '제6조(차별금지) 군수용자는 합리적인 이유 없이 성별, 종교, 장애, 나이, 사회적 신분, 출신지역, 용모 등 신체조건, 병력(病歷), 혼인 여부, 정치적 의견 및 성적(性的) 지향 등을 이유로 차별받지 아니한다.', 783);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6388, '제7조(군교정시설의 순회점검) 국방부장관은 군교정시설의 운영, 교도관의 복무, 군수용자의 처우 및 인권 실태 등을 파악하기 위하여 매년 한 번 이상 군교정시설을 순회점검하거나 소속 공무원으로 하여금 순회점검하게 하여야 한다. <개정 2014.5.20>', 783);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6389, '제8조(군교정시설의 시찰 및 참관)', 783);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6390, '제9조(교도관의 직무) 이 법에서 규정한 사항 외에 교도관의 직무에 관하여는 국방부령으로 정한다.', 783);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6391, '제10조(구분수용) 군수용자는 다음 각 호에 따라 구분하여 수용한다.', 785);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6392, '제11조(구분수용의 예외)', 785);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6393, '제12조(분리수용)', 785);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6394, '제13조(독거수용)', 785);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6395, '제14조(혼거수용)', 785);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6396, '제15조(신입자의 수용 등)', 785);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6397, '제16조(감염병환자의 수용)', 785);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6398, '제17조(고지사항) 소장은 교도관으로 하여금 신입자와 다른 군교정시설에서 이송되어 온 사람에게 말이나 글로 다음 각 호의 사항을 알려주도록 하여야 한다.', 785);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6399, '제18조(사진촬영 등)', 785);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6400, '제19조(군수용자의 이송) 소장은 군수용자의 수용ㆍ작업ㆍ교화ㆍ의료, 그 밖의 처우를 위하여 필요하거나 시설이 부족하거나 시설의 안전과 질서유지를 위하여 필요하다고 인정하면 국방부장관의 승인을 받아 군수용자를 다른 군교정시설로 이송할 수 있다. <개정 2014.5.20>', 785);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6401, '제20조(군수용자의 일반교도소 등으로의 이송)', 785);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6402, '제21조(수용사실의 가족 통지) 소장은 신입자나 다른 군교정시설에서 이송되어 온 사람이 있으면 그 사실을 군수용자의 가족(배우자, 직계 존속ㆍ비속 또는 형제자매를 말한다. 이하 같다)에게 지체 없이 통지하여야 한다. 다만, 군수용자가 통지를 원하지 아니하면 그러하지 아니하다.', 785);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6403, '제22조(의류 및 침구 등의 지급)', 786);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6404, '제23조(음식물의 지급)', 786);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6405, '제24조(물품의 자비구매)', 786);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6406, '제25조(휴대금품의 영치 등)', 787);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6407, '제26조(군수용자의 물품 소지 등)', 787);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6408, '제27조(군수용자에 대한 금품 교부)', 787);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6409, '제28조(유류금품의 교부)', 787);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6410, '제29조(영치금품의 사용허가) 소장은 군수용자가 영치금품으로 부모ㆍ배우자 또는 자녀의 생계부조, 그 밖의 정당한 용도에 사용할 것을 신청하면 대통령령으로 정하는 기준과 절차에 따라 허가할 수 있다.', 787);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6411, '제30조(영치금품의 반환) 군수용자의 영치금품은 석방할 때 본인에게 돌려주어야 한다.', 787);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6412, '제31조(위생ㆍ의료 조치의무) 소장은 군수용자가 건강한 생활을 하는 데에 필요한 위생상 및 의료상 적절한 조치를 하여야 한다.', 788);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6413, '제32조(청결 유지) 소장은 군수용자가 사용하는 모든 설비와 기구가 항상 청결하게 유지되도록 하여야 한다.', 788);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6414, '제33조(청결의무)', 788);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6415, '제34조(운동 및 목욕)', 788);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6416, '제35조(건강검진)', 788);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6417, '제36조(감염병 등에 관한 조치)', 788);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6418, '제37조(부상자 등 치료) 소장은 군수용자가 부상을 당하거나 질병에 걸리면 적절한 치료를 받도록 하여야 하고, 그 밖에 대통령령으로 정하는 바에 따라 필요한 조치를 할 수 있다.', 788);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6419, '제38조(군병원 및 외부의료시설 진료 등)', 788);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6420, '제39조(자비치료) 소장은 군수용자가 자신의 비용으로 외부의료시설에서 근무하는 의사(이하 "외부의사"라 한다)에게 치료받기를 원하면 군의관의 의견을 참고하여 치료를 허가할 수 있다.', 788);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6421, '제40조(진료환경 등)', 788);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6422, '제41조(군수용자의 의사에 반하는 의료조치)', 788);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6423, '제42조(접견)', 789);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6424, '제43조(접견의 중지 등) 교도관은 접견 중인 군수용자나 그 상대방이 다음 각 호의 어느 하나에 해당하면 접견을 중지할 수 있다.', 789);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6425, '제44조(서신수수)', 789);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6426, '제45조(전화통화)', 789);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6427, '제46조(종교행사의 참석 등)', 790);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6428, '제47조(도서비치 및 이용) 소장은 군수용자의 지식 함양과 교양 습득에 필요한 도서를 갖추어 두고 군수용자가 이용할 수 있도록 하여야 한다.', 790);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6429, '제48조(신문 등의 구독)', 790);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6430, '제49조(라디오 청취와 텔레비전 시청)', 790);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6431, '제50조(집필)', 790);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6432, '제51조(군수형자 처우의 원칙)', 792);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6433, '제52조(외부전문가의 상담 등) 소장은 군수형자의 교화나 건전한 사회복귀를 위하여 필요하면 교육학, 교정학, 범죄학, 사회학, 심리학, 의학 등에 관한 학식 또는 교정에 관한 경험이 풍부한 외부전문가로 하여금 군수형자에 대한 상담ㆍ심리치료 또는 생활지도 등을 하게 할 수 있다.', 792);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6434, '제53조(교육)', 793);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6435, '제54조(교화프로그램)', 793);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6436, '제55조(작업의 부과)', 794);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6437, '제56조(작업의무) 군수형자는 자신에게 부과된 작업과 그 밖의 노역을 수행하여야 할 의무가 있다.', 794);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6438, '제57조(신청에 따른 작업) 소장은 금고형이나 구류형의 집행 중에 있는 사람에 대하여는 신청에 따라 작업을 부과할 수 있다.', 794);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6439, '제58조(외부 통근 작업 등)', 794);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6440, '제59조(직업능력개발훈련)', 794);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6441, '제60조(집중근로에 따른 처우)', 794);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6442, '제61조(휴일의 작업) 공휴일, 토요일과 그 밖에 대통령령으로 정하는 휴일에는 작업을 부과하지 아니한다. 다만, 취사, 청소, 간호, 그 밖에 특별히 필요한 작업은 그러하지 아니하다.', 794);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6443, '제62조(작업의 면제)', 794);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6444, '제63조(작업수입 등)', 794);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6445, '제64조(위로금ㆍ조위금)', 794);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6446, '제65조(다른 보상ㆍ배상과의 관계) 제64조에 따른 위로금이나 조위금을 받을 사람이 국가로부터 동일한 사유로 「민법」이나 그 밖의 법령에 따라 해당 위로금이나 조위금에 상당하는 금액을 받았을 때에는 그 금액은 위로금이나 조위금으로 지급하지 아니한다.', 794);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6447, '제66조(귀휴)', 795);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6448, '제67조(귀휴의 취소) 소장은 귀휴 중인 군수형자가 다음 각 호의 어느 하나에 해당하면 귀휴를 취소할 수 있다.', 795);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6449, '제68조(군미결수용자 처우의 원칙) 군미결수용자는 무죄의 추정을 받으며 그에 합당한 처우를 받는다.', 796);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6450, '제69조(참관 금지) 군판사, 군검사, 소장, 교도관 및 교도병(군교정시설에서 교도관의 업무를 보조하는 병을 말한다. 이하 같다)이 아닌 사람은 군미결수용자가 수용된 거실은 참관할 수 없다. <개정 2016.1.6>', 796);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6451, '제70조(분리수용) 소장은 군미결수용자로서 사건에 서로 관련이 있는 사람은 분리수용하고 서로 간의 접촉을 금지하여야 한다.', 796);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6452, '제71조(군복 착용 등)', 796);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6453, '제72조(이발) 군미결수용자의 머리나 수염은 특별히 필요한 경우가 아니면 본인의 의사에 반하여 짧게 깎지 못한다. 다만, 군인이나 군무원인 군미결수용자의 머리나 수염에 관하여는 일반 군인이나 군무원에 준하여 깎도록 할 수 있다.', 796);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6454, '제73조(변호인과의 접견 및 서신수수)', 796);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6455, '제74조(조사 등에서의 특칙) 소장은 군미결수용자가 징벌대상자로서 조사받고 있거나 징벌 집행 중인 경우에도 소송서류의 작성, 변호인과의 접견ㆍ서신수수, 그 밖의 수사 및 재판 과정에서의 권리행사를 보장하여야 한다.', 796);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6456, '제75조(작업과 교화)', 796);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6457, '제76조(준용규정) 형사사건으로 수사 또는 재판을 받고 있는 군수형자와 사형확정자에 대하여는 제73조 및 제74조를 준용한다.', 796);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6458, '제77조(사형확정자의 수용과 심리상담 등)', 797);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6459, '제78조(공휴일 등의 사형 집행 금지) 공휴일과 토요일에는 사형을 집행하지 아니한다.', 797);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6460, '제79조(금지물품) 군수용자는 다음 각 호의 물품을 소지하여서는 아니 된다.', 798);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6461, '제80조(신체검사 등)', 798);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6462, '제81조(전자장비를 이용한 계호)', 798);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6463, '제82조(보호실 수용)', 798);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6464, '제83조(진정실 수용)', 798);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6465, '제84조(보호장비의 사용)', 798);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6466, '제85조(보호장비의 종류 및 사용요건)', 798);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6467, '제86조(보호장비의 남용 금지)', 798);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6468, '제87조(강제력의 행사)', 798);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6469, '제88조(무기의 사용)', 798);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6470, '제89조(재난 시의 조치)', 798);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6471, '제90조(수용을 위한 체포)', 798);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6472, '제91조(규율 등)', 799);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6473, '제92조(포상) 소장은 군수용자가 다음 각 호의 어느 하나에 해당하면 국방부령으로 정하는 바에 따라 포상할 수 있다.', 799);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6474, '제93조(징벌) 소장은 군수용자가 다음 각 호의 어느 하나에 해당하는 행위를 하면 제97조에 따른 징벌위원회의 의결에 따라 징벌을 부과할 수 있다.', 799);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6475, '제94조(징벌의 종류) 징벌의 종류는 다음 각 호와 같다.', 799);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6476, '제95조(징벌의 부과)', 799);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6477, '제96조(징벌대상자의 조사)', 799);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6478, '제97조(징벌위원회)', 799);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6479, '제98조(징벌의 집행)', 799);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6480, '제99조(징벌 집행의 정지ㆍ면제)', 799);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6481, '제100조(징벌 집행의 유예 등)', 799);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6482, '제101조(소장 면담)', 800);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6483, '제102조(청원)', 800);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6484, '제103조(불이익처우 금지) 군수용자는 청원, 진정, 소장과의 면담, 그 밖에 권리구제를 위한 행위를 하였다는 이유로 불리한 처우를 받지 아니한다.', 800);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6485, '제104조(가석방심사위원회) 「형법」 제72조에 따른 가석방의 적격 여부를 심사하기 위하여 교도소에 가석방심사위원회(이하 이 장에서 "위원회"라 한다)를 둔다.', 802);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6486, '제105조(위원회의 구성)', 802);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6487, '제106조(가석방 적격심사)', 802);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6488, '제107조(가석방 허가)', 802);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6489, '제108조(석방) 군수용자의 석방은 사면(赦免)이나 형기 종료 또는 권한 있는 사람의 명령에 따라 소장이 한다.', 803);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6490, '제109조(석방시기)', 803);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6491, '제110조(석방된 사람의 일시 수용) 소장은 석방된 사람이 질병이나 그 밖에 피할 수 없는 사정으로 귀가하기 어려울 때 본인이 신청하면 일시적으로 군교정시설에 수용할 수 있다.', 803);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6492, '제111조(귀가 여비 등의 대여) 소장은 석방된 사람에게 귀가에 필요한 여비나 의류가 없으면 빌려줄 수 있다.', 803);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6493, '제112조(검시 및 사망 통지) 소장은 군수용자가 사망하였을 때에는 즉시 그 시신을 검시하고, 사망 사실을 사망한 사람의 가족(가족이 없을 때에는 다른 친족을 말한다)에게 통지하여야 한다.', 804);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6494, '제113조(시신의 인도 등)', 804);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6495, '제114조(교정위원)', 805);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6496, '제115조(기부금품의 접수)', 805);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6497, '제115조의2(권한의 위임) 이 법에 따른 국방부장관의 권한은 대통령령으로 정하는 바에 따라 그 일부를 각 군의 참모총장 또는 국방부장관 소속 기관의 장에게 위임할 수 있다.', 805);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6498, '제115조의3(벌칙 적용에서 공무원 의제) 징벌위원회 또는 가석방심사위원회의 위원 중 공무원이 아닌 사람은 「형법」 제127조 및 제129조부터 제132조까지의 규정을 적용할 때에는 공무원으로 본다.', 805);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6499, '제116조(주류의 반입 등)', 806);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6500, '제117조(출석의무의 위반 등) 다음 각 호의 어느 하나에 해당하는 행위를 한 군수용자는 1년 이하의 징역에 처한다. <개정 2020.2.4>', 806);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6501, '제1조(목적) 이 영은 「군에서의 형의 집행 및 군수용자의 처우에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 807);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6502, '제2조(군미결수용실의 설치) 「군에서의 형의 집행 및 군수용자의 처우에 관한 법률」(이하 "법"이라 한다) 제4조제2항에서 "대통령령으로 정하는 부대"란 장성급(將星級) 장교 또는 2급 이상 군무원이 지휘하는 부대를 말한다. <개정 2017.9.5, 2019.11.26>', 807);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6503, '제3조(군판사 등의 시찰)', 807);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6504, '제4조(참관)', 807);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6505, '제5조(수용거실의 설치) 군교정시설의 수용거실(이하 "거실"이라 한다)은 법 제13조에 따라 군수용자를 수용할 수 있도록 독거실(獨居室)과 혼거실(混居室)을 적정 비율로 설치하여야 한다.', 809);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6506, '제6조(독거수용의 구분) 법 제13조에 따른 독거수용은 다음 각 호의 구분에 따른다.', 809);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6507, '제7조(계호독거자의 시찰)', 809);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6508, '제8조(여성 군수용자의 시찰) 소장은 여성 군수용자의 생명과 신체의 보호 또는 군교정시설의 안전과 질서유지를 위하여 특히 필요하다고 인정하는 경우가 아니면 야간에 남성 군교도관이 여성 군수용자가 있는 거실을 시찰하게 해서는 아니 된다.', 809);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6509, '제9조(혼거수용 인원의 기준) 법 제14조에 따른 혼거수용 인원은 3명 이상으로 한다. 다만, 요양이나 교화, 그 밖에 부득이한 사정이 있는 경우에는 2명으로 할 수 있다.', 809);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6510, '제10조(혼거수용의 제한) 소장은 노역장 유치명령을 받은 군수형자와 징역ㆍ금고 또는 구류의 형이 확정된 군수형자를 혼거수용해서는 아니 된다. 다만, 징역ㆍ금고 또는 구류의 형 집행을 마친 군수형자에 대한 노역장 유치명령을 집행하는 경우나, 수용시설이 부족한 경우 등 부득이한 사정이 있는 경우에는 그러하지 아니하다.', 809);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6511, '제11조(군수용자의 자리 지정) 소장은 군수용자의 생명과 신체의 보호, 증거인멸의 방지 및 군교정시설의 안전과 질서유지를 위하여 필요하다고 인정하면 거실, 교육실, 강당, 작업장, 그 밖에 군수용자들이 서로 접촉할 수 있는 장소에서 군수용자의 자리를 지정할 수 있다.', 809);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6512, '제12조(거실의 대체 사용 금지) 소장은 거실을 작업장으로 사용해서는 아니 된다. 다만, 군수용자의 심리적 안정, 교정ㆍ교화 또는 사회 적응 능력을 높이기 위하여 필요한 경우에는 그러하지 아니하다.', 809);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6513, '제13조(현황표 등의 부착 등)', 809);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6514, '제14조(신입자 등의 인수)', 809);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6515, '제15조(신입자 등의 신체 등 검사) 소장은 신입자나 이입자를 인수하였을 때에는 즉시 군교도관에게 신입자나 이입자의 신체, 의류 및 휴대품을 검사하게 하여야 한다.', 809);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6516, '제16조(신입자 등의 목욕) 소장은 신입자나 이입자가 질병에 걸렸거나 그 밖에 부득이한 사정이 있는 경우가 아니면 지체 없이 목욕을 하게 하여야 한다.', 809);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6517, '제17조(신입자 등의 건강진단) 소장은 법 제15조제2항에 따라 신입자나 이입자가 수용된 날부터 3일 이내에 건강진단을 실시하여야 한다. 다만, 휴무일이 연속되는 등 부득이한 사정이 있는 경우에는 그러하지 아니하다.', 809);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6518, '제18조(신입자 등의 신체 특징 기록 등)', 809);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6519, '제19조(수용기록부 등의 작성) 소장은 신입자와 이입자를 수용한 날부터 3일 이내에 수용기록부, 군수용자명부 및 형기종료부를 작성하고 필요한 사항을 적어야 한다.', 809);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6520, '제20조(신입자거실 등)', 809);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6521, '제21조(신입자의 신원조사) 소장은 신입자의 신원에 관한 사항을 조사하여 제19조에 따른 수용기록부에 기록하여야 한다.', 809);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6522, '제22조(형 또는 구속의 집행정지 사유의 통보) 소장은 군수용자에 대하여 건강상의 사유로 형의 집행정지나 구속의 집행정지를 할 필요가 있다고 인정하면 군의관의 진단서와 군수용자를 인수할 사람에 대한 확인서류를 첨부하여 군검사에게 통보하여야 한다. 이 경우 기소된 군수용자에 대하여 구속의 집행정지를 할 때에는 군사법원에도 통보하여야 한다. <개정 2022.6.30>', 809);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6523, '제23조(이송 중지) 소장은 군의관으로부터 군수용자의 건강상태가 다른 교정시설로 이송하는 것을 감당하기 어렵다는 보고를 받은 경우에는 이송을 중지하고 그 사실을 이송받을 소장에게 알려야 한다.', 809);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6524, '제24조(차량호송 시 군수용자의 분리) 이송이나 출정(出廷), 그 밖의 사유로 차량을 이용하여 군수용자를 호송하는 경우에는 군수형자와 군미결수용자, 여성 군수용자와 남성 군수용자의 좌석을 지정하는 등의 방법으로 분리하여 서로 접촉하지 못하도록 하여야 한다.', 809);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6525, '제25조(의류 등의 지급) 소장은 법 제22조제1항에 따라 군수용자에게 의류, 침구, 그 밖의 생활용품(이하 "의류등"이라 한다)을 지급하는 경우에는 다른 사람이 사용한 의류등은 세탁하거나 소독하여 지급하여야 하고, 식기는 청결하게 관리할 수 있는 재질로 된 것으로 지급하여야 한다.', 810);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6526, '제26조(생활기구의 비치)', 810);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6527, '제27조(음식물의 구분) 법 제23조에 따라 군수용자에게 지급하는 음식물은 주식, 부식, 음료와 그 밖의 영양물로 한다.', 810);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6528, '제28조(주식의 지급기준) 군수용자에게 지급하는 주식은 현역 군인에 준하여 지급한다.', 810);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6529, '제29조(특식의 지급) 소장은 국경일이나 그 밖에 이에 준하는 날에는 특별한 음식물을 그 소속 현역 군인에 준하여 지급할 수 있다. <개정 2014.10.28>', 810);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6530, '제30조(환자의 음식물) 소장은 군의관의 의견을 고려하여 환자에게 지급하는 음식물의 종류 또는 정도를 달리 정할 수 있다.', 810);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6531, '제31조(자비구매 허가의 기준) 소장은 법 제24조에 따라 군수용자의 교화나 건전한 사회복귀에 적합하고 군교정시설의 안전이나 질서를 해칠 우려가 없다고 인정되는 음식물과 의류등을 군수용자 자신의 비용으로 구매하도록 허가할 수 있다.', 810);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6532, '제32조(자비구매 의류등의 사용) 소장은 군수용자가 자신의 비용으로 구매한 의류등을 영치(領置)한 후 그 군수용자가 사용하게 할 수 있다.', 810);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6533, '제33조(의류등의 세탁 등)', 810);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6534, '제34조(휴대품의 사용 등)', 811);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6535, '제35조(금품의 영치) 군수용자의 현금(자기앞수표를 포함한다. 이하 같다)을 영치하는 경우에는 영치금대장에 금액을 적고, 군수용자의 물품을 영치하는 경우에는 영치품대장에 품목, 수량 및 규격을 적어야 한다.', 811);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6536, '제36조(귀중품의 보관) 소장은 영치하는 물품이 금, 은, 보석, 유가증권, 도장, 그 밖에 특별히 보관할 필요가 있는 귀중품인 경우에는 잠금장치가 되어 있는 견고한 용기에 넣어 보관하여야 한다.', 811);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6537, '제37조(영치품 매각대금의 영치) 소장은 군수용자의 신청에 따라 영치품을 팔았을 때에는 판매 비용을 제외한 나머지 대금을 영치할 수 있다.', 811);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6538, '제38조(소지범위 초과 물품의 처리) 법 제26조제2항 및 제3항에 따른 소지범위를 벗어난 물품의 처분과 폐기에 관하여는 제34조제2항 및 제3항을 준용한다.', 811);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6539, '제39조(폐기 물품의 기록) 군수용자의 물품을 폐기하였을 때에는 그 품목, 수량, 이유 및 일시를 관계 장부에 기록하여야 한다.', 811);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6540, '제40조(금품 교부 신청자의 확인) 소장은 법 제27조제1항에 따른 군수용자에 대한 금품 교부를 허가하기 전에 교부를 신청한 사람의 성명, 주소 및 군수용자와의 관계를 확인하여야 한다.', 811);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6541, '제41조(교부 허가 금품의 검사 등)', 811);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6542, '제42조(유류금품의 교부 비용) 법 제28조제2항 또는 제3항에 따라 사망자나 도주자의 금품 또는 매각대금을 보내는 데에 드는 비용은 그 교부를 청구한 사람이 부담한다.', 811);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6543, '제43조(영치금의 사용 등)', 811);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6544, '제44조(보건ㆍ위생관리계획의 수립 등) 소장은 군수용자의 건강, 계절 및 시설 여건 등을 고려하여 보건ㆍ위생관리계획을 정기적으로 수립하여 시행하여야 한다.', 812);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6545, '제45조(시설의 청소ㆍ소독)', 812);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6546, '제46조(청결의무) 군수용자는 법 제33조제1항에 따라 자신이 사용하는 거실, 작업장, 그 밖의 수용시설의 청결을 유지하기 위한 군교도관의 지시에 따라야 한다.', 812);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6547, '제47조(실외운동) 소장은 법 제34조에 따라 군수용자가 매일(공휴일 및 국방부장관이 정하는 날은 제외한다) 군(軍) 표준일과표에 따른 근무시간에 1시간 이내의 실외운동을 할 수 있도록 하여야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 실외운동을 실시하지 아니할 수 있다.', 812);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6548, '제48조(목욕 횟수) 소장은 법 제34조에 따라 작업의 특성, 계절, 그 밖의 사정을 고려하여 군수용자의 목욕 횟수를 정하되, 특별한 사정이 없으면 매주 1회 이상이 되도록 한다.', 812);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6549, '제49조(건강검진 횟수)', 812);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6550, '제50조(감염병에 관한 조치)', 812);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6551, '제51조(의료용 거실에의 수용 등)', 812);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6552, '제52조(외부의료시설 진료 등)', 812);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6553, '제53조(접견)', 813);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6554, '제54조(접견의 예외)', 813);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6555, '제55조(접견 시 유의사항 고지) 소장은 법 제42조에 따라 접견하게 하는 경우에는 군수용자와 그 상대방에게 접견할 때의 유의사항을 방송이나 게시물 부착 등의 적절한 방법으로 알려주어야 한다.', 813);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6556, '제56조(접견내용의 청취 등)', 813);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6557, '제57조(접견기록물의 관리 등)', 813);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6558, '제58조(접견 중지 사유의 고지) 군교도관이 법 제43조에 따라 군수용자의 접견을 중지하였을 때에는 그 사유를 즉시 알려주어야 한다.', 813);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6559, '제59조(서신수수의 횟수) 군수용자가 법 제44조에 따라 보내거나 받을 수 있는 서신의 횟수는 제한하지 아니한다.', 813);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6560, '제60조(서신 내용물의 확인)', 813);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6561, '제61조(서신 내용의 검열)', 813);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6562, '제62조(관계 기관 송부문서) 소장은 군사법원, 군사경찰부대, 그 밖의 관계 기관에서 군수용자에게 보내온 문서는 다른 법령에 특별한 규정이 없으면 열람한 후 본인에게 전달하여야 한다. <개정 2020.2.4>', 813);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6563, '제63조(서신 등의 대서) 소장은 군수용자가 서신, 소송서류, 그 밖의 문서를 스스로 작성할 수 없어 대신 써 달라고 요청하는 경우에는 군교도관으로 하여금 대신 쓰게 할 수 있다.', 813);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6564, '제64조(서신 등 발송비용의 부담) 군수용자의 서신, 소송서류, 그 밖의 문서를 보내는 데에 드는 비용은 군수용자가 부담한다. 다만, 소장은 군수용자가 그 비용을 부담할 수 없는 경우에는 예산의 범위에서 해당 비용을 부담할 수 있다. <개정 2014.10.28>', 813);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6565, '제65조(전화통화의 허가 범위)', 813);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6566, '제66조(전화통화 시간)', 813);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6567, '제67조(통화내용의 청취ㆍ녹음)', 813);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6568, '제68조(통화요금의 부담)', 813);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6569, '제69조(준용) 전화통화 시 외국어의 사용 및 전화통화의 중지에 관하여는 제56조제2항 및 제58조를 준용한다.', 813);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6570, '제70조(참고사항의 기록) 군교도관은 군수용자의 접견, 서신수수, 전화통화 등의 과정에서 군수용자의 처우에 특히 참고할 사항을 알게 된 경우에는 그 요지를 수용기록부에 기록하여야 한다.', 813);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6571, '제71조(비치도서의 이용)', 814);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6572, '제72조(라디오 청취 등의 방법) 법 제49조제1항에 따른 군수용자의 라디오 청취와 텔레비전 시청은 군교정시설에 설치된 방송설비를 통하여 할 수 있다.', 814);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6573, '제73조(집필용구의 관리 등)', 814);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6574, '제74조(집필의 시간 등)', 814);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6575, '제75조(문서ㆍ도화의 외부 발송 등)', 814);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6576, '제76조(군수형자로서의 처우 개시)', 816);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6577, '제77조(군수형자의 처우등급 부여 등)', 816);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6578, '제78조(군수형자 취업알선 등) 소장은 군수형자의 건전한 사회복귀를 지원하기 위하여 취업알선 및 창업지원을 위해 노력하여야 한다.', 816);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6579, '제79조(교육)', 817);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6580, '제80조(정서교육) 소장은 군수형자의 정서 함양을 위하여 필요하다고 인정하면 연극ㆍ영화관람, 체육행사, 그 밖의 문화예술활동을 하게 할 수 있다.', 817);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6581, '제81조(작업)', 818);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6582, '제82조(작업실적의 확인) 소장은 군교도관에게 매일 군수형자의 작업실적을 확인하게 하여야 한다.', 818);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6583, '제83조(신청 작업의 취소) 소장은 법 제57조에 따라 작업이 부과된 군수형자가 작업의 취소를 요청하는 경우에는 그 군수형자의 의사(意思), 건강 및 군교도관의 의견 등을 고려하여 작업을 취소할 수 있다.', 818);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6584, '제84조(직업능력개발훈련 설비 등의 구비) 소장은 법 제59조에 따른 직업능력개발훈련을 하는 경우에는 그에 필요한 설비 및 실습 자재를 갖추어야 한다.', 818);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6585, '제85조(휴업일) 법 제60조제1항 및 제61조에서 "대통령령으로 정하는 휴일"이란 12월 31일, 「각종 기념일 등에 관한 규정」에 따른 교정의 날 및 소장이 지정하는 날을 말한다.', 818);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6586, '제86조(귀휴자에 대한 조치)', 819);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6587, '제87조(법률구조 지원) 소장은 군미결수용자가 빈곤하거나 무지하여 수사나 재판 과정에서 권리를 충분히 행사하지 못한다고 인정하는 경우에는 법률구조에 필요한 지원을 할 수 있다.', 820);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6588, '제88조(공범 분리) 소장은 이송이나 출정, 그 밖의 사유로 군미결수용자를 군교정시설 밖으로 호송하는 경우에는 해당 사건에 관련된 사람과 호송 차량의 좌석을 분리하는 등의 방법으로 서로 접촉하지 못하게 하여야 한다.', 820);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6589, '제89조(접견 횟수) 군미결수용자의 접견 횟수는 매일 1회로 한다. 이 경우 변호인과의 접견은 그 횟수에 포함하지 아니한다.', 820);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6590, '제90조(접견의 예외) 소장은 군미결수용자의 처우를 위하여 특히 필요하다고 인정하면 제53조제1항ㆍ제2항ㆍ제4항 및 제89조에도 불구하고 접견시간 외의 시간에도 접견하게 할 수 있고, 접견시간을 연장하거나 접견 횟수를 늘릴 수 있으며, 접견실 외의 장소에서 접견하게 할 수 있다.', 820);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6591, '제91조(교육ㆍ교화와 작업)', 820);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6592, '제92조(도주 등 통보) 소장은 군미결수용자가 도주하거나 도주한 군미결수용자를 체포한 경우에는 그 사실을 즉시 군검사에게 통보하여야 한다. 이 경우 군미결수용자가 기소된 때에는 군사법원에도 통보하여야 한다. <개정 2022.6.30>', 820);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6593, '제93조(사망 등 통보) 소장은 군미결수용자가 위독하거나 사망한 경우에는 그 사실을 즉시 군검사에게 통보하여야 한다. 이 경우 군미결수용자가 기소된 때에는 군사법원에도 통보하여야 한다. <개정 2022.6.30>', 820);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6594, '제94조(군의관이나 외부의사의 진찰 등) 군미결수용자가 「군사법원법」 제63조, 제129조 및 제246조에 따라 군의관이나 외부의사에게 진료를 받을 때에는 군교도관이 참여하여 그 경과를 제19조에 따른 수용기록부에 기록하여야 한다.', 820);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6595, '제95조(접견 횟수) 사형확정자의 접견 횟수는 매월 4회로 한다.', 821);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6596, '제96조(접견의 예외) 소장은 사형확정자의 교화나 심리적 안정을 도모하기 위하여 특히 필요하다고 인정하면 제53조제1항ㆍ제2항ㆍ제4항 및 제95조에도 불구하고 접견시간 외의 시간에도 접견을 하게 할 수 있고, 접견시간을 연장하거나 접견 횟수를 늘릴 수 있으며, 접견실 외의 장소에서 접견하게 할 수 있다.', 821);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6597, '제97조(사형 집행 후의 검시 등)', 821);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6598, '제98조(거실등에 대한 검사) 소장은 법 제80조에 따라 군교도관에게 거실등을 정기적으로 검사하게 하여야 한다. 다만, 법 제79조의 금지물품을 숨기고 있다고 의심되는 군수용자의 거실등은 수시로 검사하게 할 수 있다.', 822);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6599, '제99조(신체 등에 대한 검사) 소장은 법 제80조에 따라 군교도관에게 작업장이나 실외에서 거실로 돌아오는 군수용자의 신체, 의류 및 휴대품을 검사하게 하여야 한다. 다만, 교정성적 등을 고려하여 그 검사가 필요하지 아니하다고 인정되는 경우에는 예외로 할 수 있다.', 822);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6600, '제100조(검사장비의 이용) 군교도관은 법 제80조에 따른 검사를 위하여 탐지견(探知犬), 금속탐지기, 그 밖의 장비를 이용할 수 있다.', 822);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6601, '제101조(외부인의 출입) 군교도관 외의 사람은 군 표준일과표에 따른 근무시간 외에는 소장의 허가 없이 군교정시설에 출입하지 못한다.', 822);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6602, '제102조(외부와의 차단)', 822);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6603, '제103조(거실의 개방 금지) 군교도관은 수사, 재판, 운동, 접견, 진료 등 군수용자의 처우를 위한 경우나 자살방지, 화재진압 등 군교정시설의 안전과 질서유지를 위하여 필요한 경우가 아니면 거실문을 열거나 군수용자를 거실 밖으로 나오게 해서는 아니 된다.', 822);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6604, '제104조(장애물 방치 금지) 군교정시설의 구내에는 시야를 가리거나 그 밖에 계호상 장애가 되는 물건을 두어서는 아니 된다.', 822);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6605, '제105조(보호실 등 수용 중지)', 822);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6606, '제106조(보호장비의 사용 등)', 822);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6607, '제107조(보호장비 착용 군수용자의 거실 지정) 보호장비를 착용 중인 군수용자는 특별한 사정이 없으면 계호상 독거수용을 하여야 한다.', 822);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6608, '제108조(보호장비 사용의 감독)', 822);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6609, '제109조(강제력의 행사) 군교도관과 교도병은 소장의 명령 없이 법 제87조에 따른 강제력을 행사해서는 아니 된다. 다만, 그 명령을 받을 시간적 여유가 없는 경우에는 강제력을 행사한 후 소장에게 즉시 보고하여야 한다.', 822);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6610, '제110조(무기사용 보고) 군교도관과 교도병은 법 제88조에 따라 무기를 사용하였을 때에는 즉시 소장에게 보고하여야 하고, 보고를 받은 소장은 그 사실을 국방부장관에게 즉시 보고하여야 한다.', 822);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6611, '제111조(재난 시의 조치)', 822);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6612, '제112조(도주 등에 따른 조치)', 822);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6613, '제113조(징벌위원회 기능) 법 제97조에 따른 징벌위원회(이하 이 장에서 "위원회"라 한다)는 다음 각 호에 관한 사항을 심의ㆍ의결한다.', 823);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6614, '제114조(징벌위원회 외부 위원)', 823);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6615, '제115조(위원장의 직무)', 823);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6616, '제116조(간사)', 823);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6617, '제117조(수당 등) 위원회의 위원 등에 대해서는 예산의 범위에서 수당, 여비, 그 밖의 필요한 경비를 지급할 수 있다. 다만, 공무원인 위원이 그 소관 업무와 직접적으로 관련되어 위원회에 출석하는 경우에는 그러하지 아니하다.', 823);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6618, '제118조(운영세칙) 이 영에서 규정한 사항 외에 위원회의 운영에 필요한 사항은 위원회의 의결을 거쳐 위원장이 정한다.', 823);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6619, '제119조(징벌의 집행)', 823);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6620, '제120조(징벌 집행의 계속) 법 제94조제4호부터 제14호까지의 징벌 집행 중에 있는 군수용자가 다른 군교정시설로 이송되거나 군사법원 또는 군검찰부 등에 출석하는 경우에도 징벌집행이 계속되는 것으로 본다.', 823);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6621, '제121조(징벌기간의 계산) 소장은 법 제99조제1항에 따라 징벌 집행을 일시 정지한 경우 그 정지사유가 해소되었을 때에는 지체 없이 징벌 집행을 재개하여야 한다. 이 경우 집행을 정지한 다음 날부터 집행을 재개(再開)한 전날까지의 일수는 징벌기간으로 계산하지 아니한다.', 823);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6622, '제122조(이송된 사람의 징벌) 군수용자가 이송 중에 징벌 부과의 대상이 되는 행위를 하였거나 다른 군교정시설에서 징벌 부과의 대상이 되는 행위를 한 사실이 이송 후에 발각되었을 때에는 그 군수용자를 인수한 소장이 징벌을 부과한다.', 823);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6623, '제123조(징벌사항의 기록) 소장은 군수용자의 징벌에 관한 사항을 징벌집행부 및 제19조에 따른 수용기록부에 기록하여야 한다.', 823);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6624, '제124조(소장 면담)', 824);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6625, '제125조(순회점검공무원에 대한 청원)', 824);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6626, '제126조(가석방 허가 신청의 절차) 법 제107조제1항에 따라 가석방 허가를 신청하는 경우에는 다음 각 호의 서류를 첨부하여 군수형자가 소속되어 있거나 소속되었던 군의 법무실장을 거쳐 국방부장관에게 신청하여야 한다. <개정 2014.10.28>', 826);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6627, '제127조(가석방자 교육 등) 소장은 법 제107조제2항에 따라 가석방을 허가받은 군수형자에 대하여 가석방자 교육을 하고, 가석방자가 지켜야 할 준수사항을 알려주어야 하며, 가석방 증서를 발급한 후 석방하여야 한다.', 826);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6628, '제128조(석방 예정자에 대한 상담 등) 소장은 군수형자의 건전한 사회복귀를 위하여 필요하다고 인정하면 석방 전 3일 이내의 범위에서 석방 예정자를 별도의 거실에 수용하여 장래에 관한 상담과 지도를 할 수 있다.', 827);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6629, '제129조(형기 종료 석방 예정자의 사전조사) 소장은 형기 종료로 석방될 군수형자에 대해서는 석방 10일 전까지 석방 후 보호에 관한 사항을 조사하여야 한다.', 827);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6630, '제130조(석방 예정자의 교정성적 등 통보) 소장은 석방될 군수형자의 보호 및 재범 방지 등을 위하여 필요하다고 인정하면 군수형자의 성격, 교정성적 또는 보호에 관한 의견을 군수형자의 거주지를 관할하는 국가경찰관서나 군수형자를 인수하여 보호할 법인 또는 개인에게 통보할 수 있다. 다만, 법인 또는 개인에게 통보하는 경우에는 해당 군수형자의 동의를 받아야 한다.', 827);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6631, '제131조(석방된 사람의 보호) 소장은 군수형자를 석방할 때 필요하다고 인정하면 「보호관찰 등에 관한 법률」 제71조에 따른 한국법무보호복지공단에 석방된 사람의 보호를 요청할 수 있다.', 827);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6632, '제132조(귀가 여비 등의 회수) 소장은 법 제111조에 따라 석방된 사람에게 귀가 여비나 의류를 빌려주었을 때에는 특별한 사유가 없으면 이를 회수하여야 한다.', 827);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6633, '제133조(사망 통지) 소장은 법 제112조에 따라 군수용자의 사망 사실을 알리는 경우에는 사망 일시, 장소, 사유 및 법 제28조의 유류금품, 법 제63조제2항의 작업장려금, 법 제64조제2항의 조위금에 관한 사항도 같이 알려야 한다.', 828);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6634, '제134조(사망기록부)', 828);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6635, '제135조(화장한 유골의 처리)', 828);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6636, '제136조(임시 매장지의 표지 등)', 828);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6637, '제137조(교정위원)', 829);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6638, '제138조(기부금품의 접수 등)', 829);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6639, '제139조(권한의 위임)', 829);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6640, '제1조(목적) 이 규칙은 「군에서의 형의 집행 및 군수용자의 처우에 관한 법률」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 830);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6641, '제2조(정의) 이 규칙에서 사용하는 용어의 뜻은 다음과 같다.', 830);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6642, '제3조(직무의 처리 등)', 831);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6643, '제4조(응급조치) 군교도관은 천재지변이나 그 밖의 위급한 사태가 발생하였을 때에는 군수용자의 생명과 안전을 위하여 필요한 응급조치를 할 수 있다.', 831);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6644, '제5조(군교도관에 대한 교육) 소장은 군교도관에게 직무수행에 필요한 교육과 훈련을 하여야 하고, 필요하다고 인정하는 경우에는 다른 기관에 위탁하여 교육을 실시할 수 있다.', 831);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6645, '제6조(군교도관회의)', 831);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6646, '제7조(의류의 지급기준)', 833);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6647, '제8조(침구 그 밖의 생활용품의 지급기준)', 833);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6648, '제9조(음식물의 지급기준) 법 제23조에 따라 군수용자에게 지급하는 구체적인 음식물의 지급기준은 「군인 급식 규정」에 따른 현역 군인의 급식기준에 따른다. <개정 2014.11.3>', 833);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6649, '제10조(임산부군수용자에 대한 특칙) 소장은 임산부인 군수용자가 있는 경우 군의관의 의견을 들어 필요한 양의 쌀밥ㆍ죽 등의 주식과 특별히 마련된 부식을 지급할 수 있다.', 833);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6650, '제11조(자비구매물품의 종류 등)', 834);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6651, '제12조(구매허가 및 신청제한)', 834);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6652, '제13조(우선 공급) 소장은 교도작업제품(군교정시설 안에서 군수용자에게 부과된 작업에 따라 생산된 물품을 말한다)으로서 자비구매물품으로 적합한 것은 우선하여 공급할 수 있다.', 834);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6653, '제14조(제품 검수)', 834);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6654, '제15조(주요사항 고지 등)', 834);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6655, '제16조(교부금품의 허가)', 834);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6656, '제17조(의료설비의 기준)', 835);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6657, '제18조(비상의료용품 기준)', 835);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6658, '제19조(종교행사의 종류) 법 제46조에 따른 종교행사의 종류는 다음 각 호와 같다.', 837);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6659, '제20조(종교행사의 방법)', 837);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6660, '제21조(종교행사의 참석대상) 군수용자는 자신이 신봉하는 종교행사에 참석할 수 있다. 다만, 소장은 군수용자가 다음 각 호의 어느 하나에 해당하는 경우에는 종교행사의 참석을 제한할 수 있다. <개정 2014.11.3>', 837);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6661, '제22조(종교상담 등)', 837);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6662, '제23조(종교물품 등의 개인 소지) 소장은 군수용자의 신앙생활에 필요하다고 인정하는 경우에는 다음 각 호의 어느 하나에 해당하는 경우를 제외하고 외부에서 제작된 휴대용 종교서적 및 성물을 군수용자가 소지하게 할 수 있다.', 837);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6663, '제24조(구독신청 범위 및 수량) 군수용자가 법 제48조에 따라 구독을 신청할 수 있는 신문ㆍ잡지 또는 도서(이하 이 절에서 "신문등"이라 한다)의 범위와 수량은 군교정시설의 보관범위 및 군수용자의 소지범위에서 신문은 월 3종류 이내로, 도서(잡지를 포함한다)는 월 10권 이내로 한다. 다만, 소장은 군수용자의 지식 함양 및 교양 습득에 특히 필요하다고 인정하는 경우에는 신문등의 신청 수량을 늘릴 수 있다.', 838);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6664, '제25조(구독허가의 취소) 소장은 신문등을 구독하는 군수용자가 다음 각 호의 어느 하나에 해당하는 경우에는 구독의 허가를 취소할 수 있다.', 838);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6665, '제26조(소유자 불명 도서) 소장은 소유자 명의가 분명하지 아니한 도서는 회수하여 비치도서로 전환하거나 폐기할 수 있다.', 838);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6666, '제27조(방송의 기본원칙)', 839);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6667, '제28조(방송설비)', 839);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6668, '제29조(방송편성시간) 소장은 군수용자의 건강과 일과시간 등을 고려하여 1일 6시간 이내에서 방송편성시간을 정한다. 다만, 토요일ㆍ공휴일, 작업ㆍ교육실태 및 군수용자의 특성을 고려하여 방송편성시간을 조정할 수 있다.', 839);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6669, '제30조(방송프로그램)', 839);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6670, '제31조(군수용자 준수사항 등)', 839);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6671, '제31조의2(서신검열 등의 대상) 영 제60조제1항제1호 및 영 제61조제1항제4호에서 "마약류사범이나 조직폭력사범 등 국방부령으로 정하는 군수용자"란 다음 각 호의 어느 하나에 해당하는 군수용자를 말한다.', 840);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6672, '제32조(처우등급 심사기준) 영 제77조에 따라 군수형자에게 부여하는 처우등급은 뉘우친 정도, 품행, 책임감, 작업등급 및 교육ㆍ훈련성적을 기준으로 심사한다.', 843);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6673, '제33조(심사의 종류) 처우등급 심사는 다음 각호와 같이 구분하여 실시한다.', 843);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6674, '제34조(정기심사)', 843);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6675, '제35조(형기의 3분의 1 심사) 형기의 3분의 1 심사는 다음 각 호의 구분에 따라 실시한다.', 843);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6676, '제36조(특별심사)', 843);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6677, '제37조(처우등급) 군수형자의 처우등급은 다음 각 호와 같다.', 843);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6678, '제38조(처우등급의 부여) 군수형자의 처우등급은 제32조에 따른 처우등급 심사기준에 따라 군교도관회의 의결로 결정한다.', 843);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6679, '제39조(처우등급의 변경)', 843);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6680, '제40조(수형태도ㆍ실적 관찰표의 제출) 군교도관은 처우등급 심사일 1주일 전까지 담당하고 있는 군수형자의 수형생활 태도와 작업ㆍ교육 실적을 별지 제1호서식의 수용태도ㆍ실적 관찰표에 기록하여 소장에게 제출하여야 한다.', 843);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6681, '제41조(처우등급심사표의 관리 등)', 843);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6682, '제42조(처우등급 심사의 통지) 소장은 처우등급 심사에 따라 군수형자의 처우등급을 승급시키거나 강등하였을 때에는 그 사실을 해당 군수형자를 담당하는 군교도관에게 알려야 하고, 군교도관은 그 사실을 군수형자에게 알려야 한다.', 843);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6683, '제43조(재수용 군수형자의 처우등급 부여 등)', 843);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6684, '제44조(일반교도소 이송 시 통보사항) 소장은 법 제20조에 따라 군수형자를 일반교도소나 구치소로 이송할 때에는 해당 군수형자의 수형생활 또는 처우 등에 관한 사항을 통보하여야 한다.', 843);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6685, '제45조(물품 지급) 소장은 군수형자의 처우등급에 따라 물품에 차이를 두어 지급할 수 있다. 다만, 주식ㆍ부식ㆍ음료 그 밖에 건강유지에 필요한 물품은 그러하지 아니하다.', 844);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6686, '제46조(봉사원 선정)', 844);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6687, '제47조(자치생활)', 844);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6688, '제48조(접견) 군수형자의 처우등급별 접견의 허용횟수는 다음 각 호와 같다.', 844);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6689, '제49조(접견장소) 소장은 처우등급 1급인 군수형자에 대해서는 국방부장관이 정하는 바에 따라 접촉차단시설이 설치된 장소(이하 "접견실"이라 한다) 외의 적당한 곳에서 접견하도록 할 수 있다. 다만, 처우상 특히 필요하다고 인정하는 경우에는 1급의 군수형자 외의 군수형자에 대해서도 이를 허용할 수 있다.', 844);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6690, '제50조(가족 만남의 날 행사 등)', 844);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6691, '제51조(전화통화 등)', 844);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6692, '제52조(교육ㆍ작업 등의 지도 보조) 소장은 처우등급 2급 이상인 군수형자 중에서 교육ㆍ작업 등의 성적이 우수하고 관련 기술이 있는 사람에게 군교도관의 작업 지도를 보조하게 할 수 있다.', 844);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6693, '제53조(개인작업)', 844);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6694, '제54조(외부 직업훈련)', 844);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6695, '제55조(교육대상자 선발 등)', 846);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6696, '제56조(교육대상자 선발 취소 등)', 846);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6697, '제57조(교육ㆍ훈련과정) 법 제53조에 따라 군교도소에서 실시하는 교육ㆍ훈련은 다음 각 호의 과정으로 한다.', 846);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6698, '제58조(검정고시반 설치 및 운영)', 846);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6699, '제59조(방송통신고등학교 교육과정 설치 및 운영)', 846);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6700, '제60조(정보화 교육과정 설치 및 운영) 소장은 군수형자에게 지식정보사회에 적응할 수 있는 교육기회를 부여하기 위하여 정보화 교육과정을 설치ㆍ운영할 수 있다.', 846);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6701, '제61조(군사교육훈련과정)', 846);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6702, '제62조(교육시간 등) 제57조 각 호에 따른 교육ㆍ훈련과정의 총교육시간, 교육과목, 학급편성 및 교육평가 등에 관한 사항은 국방부조사본부장이 정한다. <개정 2014.11.3>', 846);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6703, '제63조(교과서 등의 대여 등) 소장은 교육ㆍ훈련과정에 선발된 군수형자에게 교과서, 참고서 그 밖의 학용품을 대여하거나 지급할 수 있다.', 846);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6704, '제64조(교관) 제57조에 따른 교육ㆍ훈련은 소장이 소속 장교ㆍ준사관ㆍ부사관 및 군무원 중에서 임명한 교관 및 조교가 담당한다.', 846);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6705, '제65조(교육평가 등)', 846);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6706, '제66조(상장의 수여) 소장은 각 교육ㆍ훈련과정을 수료한 군수형자 중에서 성적이 우수하여 다른 사람의 모범이 되는 사람에게는 별지 제3호서식의 상장을 수여한다.', 846);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6707, '제67조(비치서류) 군교도소에는 각 교육ㆍ훈련과정별로 별지 제4호서식의 출석부, 별지 제5호서식의 학적부 및 교안을 작성ㆍ비치하여야 한다.', 846);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6708, '제68조(교육실시결과의 보고) 소장은 연 1회 교육ㆍ훈련 실시결과를 국방부조사본부장에게 보고하여야 한다. <개정 2014.11.3>', 846);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6709, '제69조(교화프로그램의 종류) 교화프로그램의 종류는 다음 각 호와 같다.', 847);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6710, '제70조(문화프로그램) 소장은 군수형자의 인성 함양, 자아존중감 회복 등을 위하여 음악ㆍ미술ㆍ독서ㆍ원예 등 다양한 문화예술관련 프로그램을 도입하거나 개발하여 실시할 수 있다.', 847);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6711, '제71조(문제행동 예방프로그램) 소장은 군수형자의 죄명ㆍ죄질 등을 구분하여 그에 따른 심리측정ㆍ평가ㆍ진단ㆍ치료 등의 문제행동예방프로그램을 도입하거나 개발하여 실시할 수 있다.', 847);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6712, '제72조(가족관계 회복프로그램)', 847);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6713, '제73조(교화상담)', 847);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6714, '제74조(교화프로그램 운영방법)', 847);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6715, '제75조(작업의 종류 및 시간)', 849);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6716, '제76조(작업종류의 변경 금지) 소장은 군수형자에게 일정한 작업을 부과하였을 때에는 특별한 이유가 없는 한 그 작업종류를 변경하여서는 아니 된다.', 849);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6717, '제77조(작업등급)', 849);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6718, '제78조(외부통근작업자의 선정기준)', 849);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6719, '제79조(선정 취소) 소장은 외부통근자가 법령을 위반하는 행위를 하거나 국방부장관 또는 소장이 정하는 준수사항을 위반한 경우에는 외부통근자 선정을 취소할 수 있다.', 849);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6720, '제80조(외부통근자 교육) 소장은 외부통근자로 선정된 군수형자에게 자치활동, 행동수칙, 안전수칙, 작업기술 및 현장적응훈련에 대한 교육을 실시하여야 한다.', 849);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6721, '제81조(자치생활) 소장은 외부통근자의 사회 적응 능력을 기르고 원활한 사회복귀를 촉진하기 위하여 필요하다고 인정하는 경우에는 제47조에 따른 자치생활을 하게 할 수 있다.', 849);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6722, '제82조(작업도구의 파손 등에 대한 변상) 군수형자가 고의 또는 중대한 과실로 작업도구ㆍ원료ㆍ제품 또는 시설물을 파손하거나 잃어버렸을 때에는 그 군수형자에게 지급할 작업장려금으로 이를 변상하게 할 수 있다.', 849);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6723, '제83조(직업훈련 직종 선정 등)', 850);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6724, '제84조(직업훈련 대상자 선정기준) 소장은 다음 각 호의 요건을 갖춘 군수형자 중 군수형자의 의사(意思), 적성, 나이 및 학력 등을 고려하여 직업훈련 대상자로 선정할 수 있다.', 850);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6725, '제85조(직업훈련 대상자 선정의 제한) 소장은 제84조에도 불구하고 군수형자가 다음 각 호의 어느 하나에 해당하는 경우에는 직업훈련 대상자로 선정해서는 아니 된다.', 850);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6726, '제86조(직업훈련 대상자 이송)', 850);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6727, '제87조(직업훈련의 보류 및 취소 등)', 850);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6728, '제88조(귀휴 사유)', 852);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6729, '제89조(귀휴 심사)', 852);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6730, '제90조(설치) 법 제66조에 따른 군수형자의 귀휴허가에 관한 심사를 하기 위하여 군교도소에 귀휴심사위원회(이하 이 절에서 "위원회"라 한다)를 둔다.', 853);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6731, '제91조(기능) 위원회는 귀휴심사대상자(이하 이 장에서 "심사대상자"라 한다)에 대하여 다음 각 호의 사항을 심사한다.', 853);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6732, '제92조(구성)', 853);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6733, '제93조(위원의 임기 등)', 853);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6734, '제94조(위원장의 직무)', 853);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6735, '제95조(회의)', 853);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6736, '제96조(간사)', 853);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6737, '제97조(귀휴심사에 필요한 서류)', 853);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6738, '제98조(사실조회 등)', 853);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6739, '제99조(귀휴심사 보고) 소장이 귀휴대상자를 위원회의 심사에 회부한 때에는 그 명부를 작성하여 국방부조사본부장을 거쳐 국방부장관에게 보고하여야 한다. <개정 2014.11.3>', 853);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6740, '제100조(귀휴허가증 발급 등) 소장은 법 제66조제1항 및 제2항에 따라 귀휴를 허가하였을 때에는 별지 제11호서식의 귀휴허가부에 기록하고 귀휴허가를 받은 군수형자(이하 "귀휴자"라 한다)에게 별지 제12호서식의 귀휴허가증을 발급하여야 한다.', 854);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6741, '제101조(귀휴조건) 법 제66조제3항에 따라 소장이 귀휴자에게 붙일 수 있는 조건(이하 "귀휴조건"이라 한다)은 다음 각 호와 같다.', 854);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6742, '제102조(동행귀휴 등)', 854);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6743, '제103조(귀휴비용 등)', 854);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6744, '제104조(귀휴조건 위반에 대한 조치)', 854);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6745, '제105조(번호표 등 표시) 사형확정자의 번호표 및 거실표의 색상은 붉은색으로 한다. 다만, 소장은 사형확정자의 심리적 안정과 원만한 수용생활을 위하여 필요하다고 인정하는 경우에는 이와 달리 시행할 수 있다.', 855);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6746, '제106조(상담)', 855);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6747, '제107조(혼거수용 및 작업)', 855);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6748, '제108조(교화프로그램) 소장은 법 제77조제3항에 따라 사형확정자에 대하여 심리상담, 종교상담, 심리치료 등의 교화프로그램을 실시하는 경우에는 전문가에 의하여 집중적이고 지속적으로 이루어질 수 있도록 계획을 수립ㆍ시행하여야 한다.', 855);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6749, '제109조(전화통화) 소장은 사형확정자의 심리적 안정과 원만한 수용생활을 위하여 필요하다고 인정하는 경우에는 매월 3회 이내의 범위에서 전화통화를 허가할 수 있다.', 855);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6750, '제110조(교정장비의 종류) 교정장비의 종류는 다음 각 호와 같다.', 858);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6751, '제111조(교정장비의 관리)', 858);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6752, '제112조(교정장비 보유기준 등) 군교정시설별 교정장비의 보유기준 및 관리방법 등에 관하여 필요한 사항은 국방부장관이 정한다.', 858);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6753, '제113조(전자장비의 종류) 군교도관이 법 제81조에 따라 군수용자 또는 시설을 계호하는 경우에 사용할 수 있는 전자장비는 다음 각 호와 같다.', 859);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6754, '제114조(중앙통제실의 운영)', 859);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6755, '제115조(영상정보처리기기 설치)', 859);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6756, '제116조(거실에 있는 군수용자의 계호)', 859);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6757, '제117조(전자감지기의 설치) 전자감지기는 군교정시설의 벽둘레ㆍ울타리 그 밖에 군수용자의 도주와 외부로부터의 침입을 방지하기 위하여 필요한 장소에 설치한다. <개정 2020.2.3>', 859);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6758, '제118조(전자경보기의 사용) 전자경보기는 외부의료시설 입원, 이송ㆍ출정, 그 밖의 사유로 군교정시설 밖에서 군수용자를 계호하는 경우에 보호장비나 군수용자의 팔목 등에 부착하여 사용할 수 있다.', 859);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6759, '제119조(물품검색기 설치 및 사용)', 859);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6760, '제120조(증거수집장비의 사용) 군교도관은 군수용자가 사후(事後)에 입증이 필요하다고 인정되는 행위를 하거나 상태에 있는 경우에 군수용자에 대하여 증거수집장비를 사용할 수 있다.', 859);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6761, '제121조(녹음ㆍ녹화 기록물의 관리) 소장은 전자장비로 녹음ㆍ녹화된 기록물을 「공공기록물 관리에 관한 법률」에 따라 관리하여야 한다.', 859);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6762, '제122조(보호장비의 종류) 군교도관이 법 제85조제1항에 따라 사용할 수 있는 보호장비의 종류는 다음 각 호와 같다.', 860);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6763, '제123조(보호장비의 규격)', 860);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6764, '제124조(보호장비사용 명령) 소장은 영 제106조제1항에 따라 보호장비 사용을 명령하거나 승인하는 경우에는 보호장비의 종류 및 사용방법을 구체적으로 지정하여야 하며, 이 규칙에서 정한 방법 외의 방법으로 보호장비를 사용하게 하여서는 아니 된다.', 860);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6765, '제125조(수갑의 사용방법)', 860);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6766, '제126조(머리보호장비의 사용방법) 머리보호장비의 사용은 별표 7의 방법으로 한다. 이 경우 군수용자가 머리보호장비를 임의로 해제하지 못하도록 다른 보호장비를 함께 사용할 수 있다.', 860);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6767, '제127조(발목보호장비의 사용방법) 발목보호장비의 사용방법은 다음 각 호와 같다.', 860);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6768, '제128조(보호대의 사용방법) 보호대의 사용방법은 다음 각 호와 같다.', 860);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6769, '제129조(보호의자의 사용방법)', 860);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6770, '제130조(보호침대의 사용방법)', 860);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6771, '제131조(보호복의 사용방법)', 860);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6772, '제132조(포승의 사용방법)', 860);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6773, '제133조(둘 이상의 보호장비 사용) 하나의 보호장비로 사용목적을 달성할 수 없는 경우에는 둘 이상의 보호장비를 사용할 수 있다. 다만, 보호의자 및 보호침대는 다른 보호장비와 같이 사용할 수 없다.', 860);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6774, '제134조(보호장비 사용의 기록) 군교도관은 법 제84조제1항에 따라 보호장비를 사용하는 경우에는 별지 제17호서식의 보호장비사용 심사부에 사용내용을 기록하여야 한다. 다만, 법 제84조제1항제1호에 따라 보호장비를 사용하는 경우에는 호송계획서나 수용기록부의 내용 등으로 기록을 갈음할 수 있다.', 860);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6775, '제135조(군의관의 건강확인 등) 군의관은 법 제84조제3항에 따라 보호장비 착용 군수용자의 건강상태를 확인한 결과 특이사항을 발견한 경우에는 보호장비사용 심사부에 이를 기록하여야 한다.', 860);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6776, '제136조(보호장비의 계속 사용)', 860);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6777, '제137조(보호장비 사용의 해제)', 860);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6778, '제138조(보호장비 착용 군수용자의 관찰 등) 소장은 제122조제5호부터 제7호까지의 보호장비를 사용하거나 제8호의 보호장비를 별표 17의 방법으로 사용하게 하는 경우에는 군교도관으로 하여금 수시로 해당 군수용자의 상태를 확인하고 1시간마다 별지 제18호서식의 보호장비 착용자 관찰부에 확인사항을 기록하게 하여야 한다.', 860);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6779, '제139조(보안장비의 종류) 군교도관등이 법 제87조에 따라 강제력을 행사하는 경우에 사용할 수 있는 보안장비는 다음 각 호와 같다.', 861);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6780, '제140조(보안장비의 종류별 사용요건)', 861);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6781, '제141조(보안장비의 종류별 사용기준) 보안장비의 종류별 사용기준은 다음 각 호와 같다.', 861);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6782, '제142조(무기의 종류) 군교도관등이 법 제88조에 따라 사용할 수 있는 무기의 종류는 다음 각 호와 같다.', 862);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6783, '제143조(무기의 종류별 사용요건)', 862);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6784, '제144조(기관총의 설치 등) 기관총은 대공초소 또는 집중사격을 하기 가장 쉬운 장소에 설치하고, 유사시 즉시 사용할 수 있도록 충분한 인원의 사수(射手)ㆍ부사수ㆍ탄약수를 미리 지정하여야 한다.', 862);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6785, '제145조(총기의 사용절차) 군교도관등이 총기를 사용하는 경우에는 구두경고, 공포탄 발사, 위협사격, 조준사격의 순서에 따라야 한다. 다만, 상황이 긴급하여 시간적 여유가 없는 경우는 예외로 한다.', 862);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6786, '제146조(총기 교육 등)', 862);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6787, '제147조(포상)', 864);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6788, '제148조(규율) 군수용자가 법 제93조제6호에 따라 시설의 안전과 질서유지를 위하여 해서는 안 될 행위는 다음 각 호와 같다.', 865);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6789, '제149조(징벌사유의 경합) 법 제95조제2항제1호에 따른 징벌의 경중(輕重)은 제150조 각 호의 순서에 따른다. 이 경우 같은 조 제2호부터 제5호까지의 경우에는 각 목의 순서에 따른다.', 865);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6790, '제150조(징벌의 부과기준) 법 제95조제6항에 따른 징벌의 부과기준은 다음 각 호와 같다.', 865);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6791, '제151조(징벌 부과 시 고려사항) 제150조에 따라 징벌을 부과하는 경우에는 다음 각 호의 사항을 고려하여야 한다.', 865);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6792, '제152조(징벌대상자의 조사 시 준수사항) 군교도관이 법 제96조제1항에 따라 징벌사유에 해당하는 행위를 하였다고 의심할 만한 충분한 이유가 있는 군수용자(이하 "징벌대상자"라 한다) 또는 참고인 등을 조사하는 경우에는 다음 각 호의 사항을 준수하여야 한다.', 865);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6793, '제153조(조사기간)', 865);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6794, '제154조(징벌대상자의 처우제한 통지) 소장은 법 제96조제3항에 따라 조사기간 중 접견, 서신수수 또는 전화통화를 제한하는 경우에는 징벌대상자의 가족 등에게 그 사실을 알려야 한다. 다만, 징벌대상자가 원하지 아니하는 경우에는 그러하지 아니하다.', 865);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6795, '제155조(조사의 일시정지)', 865);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6796, '제156조(징벌의결의 요구)', 865);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6797, '제157조(징벌대상자에 대한 출석통지)', 865);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6798, '제158조(징벌위원회의 회의 및 의결)', 865);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6799, '제159조(집행절차) 소장은 징벌을 집행하려면 징벌의결의 내용과 징벌처분에 대한 불복방법을 기록한 별지 제25호서식의 징벌집행통지서에 징벌의결서 부본(副本)을 첨부하여 해당 군수용자에게 전달하여야 한다.', 865);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6800, '제160조(징벌의 집행순서)', 865);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6801, '제161조(징벌의 집행방법)', 865);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6802, '제162조(금치 집행 중 생활용품 등의 별도 보관) 소장은 금치 중인 군수용자가 생활용품 등으로 자살ㆍ자해할 우려가 있거나 군교정시설의 안전과 질서를 해칠 우려가 있는 경우에는 그 물품을 따로 보관하고 필요한 경우에만 이를 사용하게 할 수 있다.', 865);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6803, '제163조(징벌 집행 중인 군수용자의 상담) 소장은 징벌 집행 중인 군수용자에 대하여 군교도관 또는 교정참여인사와의 상담을 실시하여 징벌대상행위의 재발방지에 노력하여야 한다.', 865);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6804, '제164조(양형 참고자료의 통보) 소장은 군미결수용자에게 징벌을 부과하였을 때에는 징벌대상행위 등에 관한 양형 참고자료를 작성하여 관할 군검찰부 검찰관 또는 관할 군사법원에 통보할 수 있다.', 865);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6805, '제165조(기능) 법 제104조에 따른 가석방심사위원회(이하 이 편에서 "위원회"라 한다)는 법 제106조에 따른 가석방 적격심사와 「형법」 제75조에 따른 가석방의 취소 등에 관한 사항을 심사한다.', 867);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6806, '제166조(위원회의 구성 등)', 867);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6807, '제167조(위원의 임기) 제166조제1항제2호 및 제3호의 위원 임기는 2년으로 한다', 867);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6808, '제168조(위원장의 직무)', 867);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6809, '제169조(회의)', 867);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6810, '제170조(간사와 서기)', 867);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6811, '제171조(회의록의 작성)', 867);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6812, '제172조(수당 등) 위원회의 회의에 출석한 위원에 대해서는 예산의 범위에서 수당과 여비를 지급할 수 있다.', 867);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6813, '제173조(운영세칙) 이 규칙에 규정된 사항 외에 위원회의 운영에 관하여 필요한 사항은 위원회의 의결을 거쳐 위원장이 정한다.', 867);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6814, '제174조(가석방 적격심사의 기본원칙) 가석방 적격심사는 객관적 자료와 기준에 따라 공정하게 하여야 하며, 심사과정에서 알게 된 비밀은 누설하여서는 아니 된다.', 868);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6815, '제175조(심사 대상자의 선정)', 868);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6816, '제176조(사전조사) 소장은 군수형자의 가석방 적격심사를 위하여 다음 각 호의 사항을 미리 조사하여야 한다. 이 경우 특히 필요하다고 인정하면 군수형자, 그 가족, 그 밖의 사람과 면담 등을 할 수 있다.', 868);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6817, '제177조(사전조사 유의사항) 제176조에 따른 사전조사 중 가석방 적격심사와 관련하여 특히 피해자의 감정 및 합의 여부, 출소시 피해자에 대한 보복성 범죄 가능성 등에 유의하여야 한다.', 868);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6818, '제178조(사전조사 시기 등)', 868);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6819, '제179조(심사서류)', 868);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6820, '제180조(누범자에 대한 심사) 위원회가 같거나 유사한 죄로 2회 이상 징역형 또는 금고형의 집행을 받은 군수형자에 대하여 가석방 적격심사를 할 때에는 뉘우치는 정도, 노동능력 및 의욕, 근면성, 그 밖에 정상적인 업무에 취업할 수 있는 생활계획과 보호관계에 관하여 중점적으로 심사하여야 한다.', 868);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6821, '제181조(범죄 동기에 대한 심사)', 868);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6822, '제182조(사회의 감정에 대한 심사) 다음 각 호에 해당하는 군수형자를 심사하는 경우에는 특히 그 범죄에 대한 사회의 감정에 유의하여야 한다.', 868);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6823, '제183조(군에 대한 피해정도에 관한 심사) 범죄의 수단 및 결과를 심사하는 경우 다음 각 호에 따라 그 범죄에 의한 군의 피해정도에 유의하여야 한다.', 868);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6824, '제184조(재산범에 대한 심사)', 868);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6825, '제185조(관계 기관에 대한 조회)', 868);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6826, '제186조(감정의 촉탁)', 868);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6827, '제187조(재회부) 소장은 위원회에서 가석방 부적격으로 결정된 군수형자에 대하여 그 후 가석방을 하는 것이 적절하다고 인정하는 경우에는 다시 가석방 적격심사를 위원회에 회부할 수 있다.', 868);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6828, '제188조(가석방 결정)', 868);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6829, '제189조(가석방증) 「가석방자관리규정」 제4조제2항에 따른 가석방증은 별지 제31호서식에 따른다.', 868);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6830, '제190조(가석방의 보고) 소장은 군수형자를 가석방하였을 때에는 국방부장관이 발행한 가석방 허가서가 도착한 날짜와 실제 석방한 날짜를 국방부조사본부장을 거쳐 국방부장관에게 보고하여야 한다. <개정 2014.11.3>', 868);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6831, '제191조(재복무 대상 가석방자의 보호와 감독) 가석방자 중 군에 다시 복무할 사람에 대한 보호ㆍ감독의 업무는 소속 부대장이 수행한다. 다만, 소속 부대로 복귀할 때까지 가석방자에 대한 보호ㆍ감독업무는 소장이 한다.', 868);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6832, '제192조(가석방 취소) 가석방자가 가석방 기간 중 「가석방자관리규정」 제5조부터 제7조까지, 제10조, 제13조제1항 및 제14조부터 제16조까지의 규정에서 정한 준수사항을 위반하거나 관할 경찰서장의 명령 또는 조치를 따르지 아니하면 「형법」 제75조에 따라 가석방을 취소할 수 있다.', 869);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6833, '제193조(가석방 취소의 신청)', 869);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6834, '제194조(위원회의 심사)', 869);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6835, '제195조(남은 형의 집행)', 869);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6836, '제196조(가석방의 실효와 보고) 소장은 형법 제74조에 따라 가석방이 실효된 것을 알았을 때에는 지체 없이 남은 형의 집행에 필요한 조치를 하고, 그 결과를 국방부장관에게 보고하여야 한다.', 869);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6837, '제197조(추천) 소장이 교정위원을 추천하는 경우에는 별지 32호서식의 교정위원 추천서를 각군의 참모총장 또는 국방부조사본부장에게 제출하여야 한다. 다만, 재위촉의 경우에는 소장의 의견서로 그 제출을 갈음한다. <개정 2014.11.3>', 870);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6838, '제1조(목적) 이 법은 수형자의 교정교화와 건전한 사회복귀를 도모하고, 수용자의 처우와 권리 및 교정시설의 운영에 관하여 필요한 사항을 규정함을 목적으로 한다.', 871);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6839, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다. <개정 2016.12.2>', 871);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6840, '제3조(적용범위) 이 법은 교정시설의 구내와 교도관이 수용자를 계호(戒護)하고 있는 그 밖의 장소로서 교도관의 통제가 요구되는 공간에 대하여 적용한다.', 871);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6841, '제4조(인권의 존중) 이 법을 집행하는 때에 수용자의 인권은 최대한으로 존중되어야 한다.', 871);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6842, '제5조(차별금지) 수용자는 합리적인 이유 없이 성별, 종교, 장애, 나이, 사회적 신분, 출신지역, 출신국가, 출신민족, 용모 등 신체조건, 병력(病歷), 혼인 여부, 정치적 의견 및 성적(性的) 지향 등을 이유로 차별받지 아니한다.', 871);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6843, '제5조의2(기본계획의 수립)', 871);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6844, '제5조의3(협의체의 설치 및 운영)', 871);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6845, '제6조(교정시설의 규모 및 설비)', 871);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6846, '제7조(교정시설 설치ㆍ운영의 민간위탁)', 871);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6847, '제8조(교정시설의 순회점검) 법무부장관은 교정시설의 운영, 교도관의 복무, 수용자의 처우 및 인권실태 등을 파악하기 위하여 매년 1회 이상 교정시설을 순회점검하거나 소속 공무원으로 하여금 순회점검하게 하여야 한다. <개정 2016.5.29>', 871);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6848, '제9조(교정시설의 시찰 및 참관)', 871);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6849, '제10조(교도관의 직무) 이 법에 규정된 사항 외에 교도관의 직무에 관하여는 따로 법률로 정한다.', 871);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6850, '제11조(구분수용)', 873);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6851, '제12조(구분수용의 예외)', 873);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6852, '제13조(분리수용)', 873);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6853, '제14조(독거수용) 수용자는 독거수용한다. 다만, 다음 각 호의 어느 하나에 해당하는 사유가 있으면 혼거수용할 수 있다.', 873);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6854, '제15조(수용거실 지정) 소장은 수용자의 거실을 지정하는 경우에는 죄명ㆍ형기ㆍ죄질ㆍ성격ㆍ범죄전력ㆍ나이ㆍ경력 및 수용생활 태도, 그 밖에 수용자의 개인적 특성을 고려하여야 한다.', 873);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6855, '제16조(신입자의 수용 등)', 873);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6856, '제16조의2(간이입소절차) 다음 각 호의 어느 하나에 해당하는 신입자의 경우에는 법무부장관이 정하는 바에 따라 간이입소절차를 실시한다.', 873);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6857, '제17조(고지사항) 신입자 및 다른 교정시설로부터 이송되어 온 사람에게는 말이나 서면으로 다음 각 호의 사항을 알려 주어야 한다. <개정 2020.2.4>', 873);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6858, '제18조(수용의 거절)', 873);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6859, '제19조(사진촬영 등)', 873);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6860, '제20조(수용자의 이송)', 873);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6861, '제21조(수용사실의 알림) 소장은 신입자 또는 다른 교정시설로부터 이송되어 온 사람이 있으면 그 사실을 수용자의 가족(배우자, 직계 존속ㆍ비속 또는 형제자매를 말한다. 이하 같다)에게 지체 없이 알려야 한다. 다만, 수용자가 알리는 것을 원하지 아니하면 그러하지 아니하다. <개정 2020.2.4>', 873);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6862, '제22조(의류 및 침구 등의 지급)', 874);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6863, '제23조(음식물의 지급)', 874);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6864, '제24조(물품의 자비구매)', 874);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6865, '제25조(휴대금품의 보관 등)', 875);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6866, '제26조(수용자가 지니는 물품 등)', 875);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6867, '제27조(수용자에 대한 금품 전달)', 875);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6868, '제28조(유류금품의 처리)', 875);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6869, '제29조(보관금품의 반환 등)', 875);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6870, '제30조(위생ㆍ의료 조치의무) 소장은 수용자가 건강한 생활을 하는 데에 필요한 위생 및 의료상의 적절한 조치를 하여야 한다.', 876);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6871, '제31조(청결유지) 소장은 수용자가 사용하는 모든 설비와 기구가 항상 청결하게 유지되도록 하여야 한다.', 876);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6872, '제32조(청결의무)', 876);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6873, '제33조(운동 및 목욕)', 876);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6874, '제34조(건강검진)', 876);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6875, '제35조(감염병 등에 관한 조치) 소장은 감염병이나 그 밖에 감염의 우려가 있는 질병의 발생과 확산을 방지하기 위하여 필요한 경우 수용자에 대하여 예방접종ㆍ격리수용ㆍ이송, 그 밖에 필요한 조치를 하여야 한다. <개정 2016.12.2>', 876);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6876, '제36조(부상자 등 치료)', 876);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6877, '제37조(외부의료시설 진료 등)', 876);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6878, '제38조(자비치료) 소장은 수용자가 자신의 비용으로 외부의료시설에서 근무하는 의사(이하 "외부의사"라 한다)에게 치료받기를 원하면 교정시설에 근무하는 의사(공중보건의사를 포함하며, 이하 "의무관"이라 한다)의 의견을 고려하여 이를 허가할 수 있다.', 876);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6879, '제39조(진료환경 등)', 876);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6880, '제40조(수용자의 의사에 반하는 의료조치)', 876);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6881, '제41조(접견)', 877);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6882, '제42조(접견의 중지 등) 교도관은 접견 중인 수용자 또는 그 상대방이 다음 각 호의 어느 하나에 해당하면 접견을 중지할 수 있다.', 877);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6883, '제43조(편지수수)', 877);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6884, '제44조(전화통화)', 877);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6885, '제45조(종교행사의 참석 등)', 878);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6886, '제46조(도서비치 및 이용) 소장은 수용자의 지식함양 및 교양습득에 필요한 도서를 비치하고 수용자가 이용할 수 있도록 하여야 한다.', 878);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6887, '제47조(신문등의 구독)', 878);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6888, '제48조(라디오 청취와 텔레비전 시청)', 878);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6889, '제49조(집필)', 878);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6890, '제50조(여성수용자의 처우)', 879);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6891, '제51조(여성수용자 처우 시의 유의사항)', 879);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6892, '제52조(임산부인 수용자의 처우)', 879);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6893, '제53조(유아의 양육)', 879);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6894, '제53조의2(수용자의 미성년 자녀 보호에 대한 지원)', 879);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6895, '제54조(수용자에 대한 특별한 처우)', 879);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6896, '제55조(수형자 처우의 원칙) 수형자에 대하여는 교육ㆍ교화프로그램, 작업, 직업훈련 등을 통하여 교정교화를 도모하고 사회생활에 적응하는 능력을 함양하도록 처우하여야 한다.', 881);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6897, '제56조(개별처우계획의 수립 등)', 881);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6898, '제57조(처우)', 881);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6899, '제58조(외부전문가의 상담 등) 소장은 수형자의 교화 또는 건전한 사회복귀를 위하여 필요하면 교육학ㆍ교정학ㆍ범죄학ㆍ사회학ㆍ심리학ㆍ의학 등에 관한 학식 또는 교정에 관한 경험이 풍부한 외부전문가로 하여금 수형자에 대한 상담ㆍ심리치료 또는 생활지도 등을 하게 할 수 있다.', 881);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6900, '제59조(분류심사)', 882);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6901, '제60조(관계기관등에 대한 사실조회 등)', 882);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6902, '제61조(분류전담시설) 법무부장관은 수형자를 과학적으로 분류하기 위하여 분류심사를 전담하는 교정시설을 지정ㆍ운영할 수 있다.', 882);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6903, '제62조(분류처우위원회)', 882);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6904, '제63조(교육)', 883);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6905, '제64조(교화프로그램)', 883);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6906, '제65조(작업의 부과)', 884);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6907, '제66조(작업의무) 수형자는 자신에게 부과된 작업과 그 밖의 노역을 수행하여야 할 의무가 있다.', 884);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6908, '제67조(신청에 따른 작업) 소장은 금고형 또는 구류형의 집행 중에 있는 사람에 대하여는 신청에 따라 작업을 부과할 수 있다.', 884);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6909, '제68조(외부 통근 작업 등)', 884);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6910, '제69조(직업능력개발훈련)', 884);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6911, '제70조(집중근로에 따른 처우)', 884);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6912, '제71조(작업시간 등)', 884);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6913, '제72조(작업의 면제)', 884);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6914, '제73조(작업수입 등)', 884);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6915, '제74조(위로금ㆍ조위금)', 884);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6916, '제75조(다른 보상ㆍ배상과의 관계) 위로금 또는 조위금을 지급받을 사람이 국가로부터 동일한 사유로 「민법」이나 그 밖의 법령에 따라 제74조의 위로금 또는 조위금에 상당하는 금액을 지급받은 경우에는 그 금액을 위로금 또는 조위금으로 지급하지 아니한다.', 884);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6917, '제76조(위로금ㆍ조위금을 지급받을 권리의 보호)', 884);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6918, '제77조(귀휴)', 885);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6919, '제78조(귀휴의 취소) 소장은 귀휴 중인 수형자가 다음 각 호의 어느 하나에 해당하면 그 귀휴를 취소할 수 있다.', 885);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6920, '제79조(미결수용자 처우의 원칙) 미결수용자는 무죄의 추정을 받으며 그에 합당한 처우를 받는다.', 886);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6921, '제80조(참관금지) 미결수용자가 수용된 거실은 참관할 수 없다.', 886);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6922, '제81조(분리수용) 소장은 미결수용자로서 사건에 서로 관련이 있는 사람은 분리수용하고 서로 간의 접촉을 금지하여야 한다.', 886);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6923, '제82조(사복착용) 미결수용자는 수사ㆍ재판ㆍ국정감사 또는 법률로 정하는 조사에 참석할 때에는 사복을 착용할 수 있다. 다만, 소장은 도주우려가 크거나 특히 부적당한 사유가 있다고 인정하면 교정시설에서 지급하는 의류를 입게 할 수 있다.', 886);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6924, '제83조(이발) 미결수용자의 머리카락과 수염은 특히 필요한 경우가 아니면 본인의 의사에 반하여 짧게 깎지 못한다. <개정 2020.2.4>', 886);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6925, '제84조(변호인과의 접견 및 편지수수)', 886);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6926, '제85조(조사 등에서의 특칙) 소장은 미결수용자가 징벌대상자로서 조사받고 있거나 징벌집행 중인 경우에도 소송서류의 작성, 변호인과의 접견ㆍ편지수수, 그 밖의 수사 및 재판 과정에서의 권리행사를 보장하여야 한다. <개정 2020.2.4>', 886);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6927, '제86조(작업과 교화)', 886);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6928, '제87조(유치장) 경찰관서에 설치된 유치장은 교정시설의 미결수용실로 보아 이 법을 준용한다.', 886);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6929, '제88조(준용규정) 형사사건으로 수사 또는 재판을 받고 있는 수형자와 사형확정자에 대하여는 제82조, 제84조 및 제85조를 준용한다. <개정 2008.12.11, 2016.12.2>', 886);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6930, '제89조(사형확정자의 수용)', 887);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6931, '제90조(개인상담 등)', 887);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6932, '제91조(사형의 집행)', 887);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6933, '제92조(금지물품)', 888);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6934, '제93조(신체검사 등)', 888);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6935, '제94조(전자장비를 이용한 계호)', 888);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6936, '제95조(보호실 수용)', 888);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6937, '제96조(진정실 수용)', 888);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6938, '제97조(보호장비의 사용)', 888);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6939, '제98조(보호장비의 종류 및 사용요건)', 888);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6940, '제99조(보호장비 남용 금지)', 888);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6941, '제100조(강제력의 행사)', 888);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6942, '제101조(무기의 사용)', 888);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6943, '제102조(재난 시의 조치)', 888);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6944, '제103조(수용을 위한 체포)', 888);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6945, '제104조(마약류사범 등의 관리)', 888);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6946, '제105조(규율 등)', 889);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6947, '제106조(포상) 소장은 수용자가 다음 각 호의 어느 하나에 해당하면 법무부령으로 정하는 바에 따라 포상할 수 있다.', 889);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6948, '제107조(징벌) 소장은 수용자가 다음 각 호의 어느 하나에 해당하는 행위를 하면 제111조의 징벌위원회의 의결에 따라 징벌을 부과할 수 있다. <개정 2019.4.23, 2020.2.4>', 889);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6949, '제108조(징벌의 종류) 징벌의 종류는 다음 각 호와 같다. <개정 2019.4.23, 2020.2.4>', 889);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6950, '제109조(징벌의 부과)', 889);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6951, '제110조(징벌대상자의 조사)', 889);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6952, '제111조(징벌위원회)', 889);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6953, '제111조의2(징벌대상행위에 관한 양형 참고자료 통보) 소장은 미결수용자에게 징벌을 부과한 경우에는 그 징벌대상행위를 양형(量刑) 참고자료로 작성하여 관할 검찰청 검사 또는 관할 법원에 통보할 수 있다.', 889);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6954, '제112조(징벌의 집행)', 889);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6955, '제113조(징벌집행의 정지ㆍ면제)', 889);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6956, '제114조(징벌집행의 유예)', 889);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6957, '제115조(징벌의 실효 등)', 889);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6958, '제116조(소장 면담)', 890);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6959, '제117조(청원)', 890);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6960, '제117조의2(정보공개청구)', 890);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6961, '제118조(불이익처우 금지) 수용자는 청원, 진정, 소장과의 면담, 그 밖의 권리구제를 위한 행위를 하였다는 이유로 불이익한 처우를 받지 아니한다.', 890);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6962, '제119조(가석방심사위원회) 「형법」 제72조에 따른 가석방의 적격 여부를 심사하기 위하여 법무부장관 소속으로 가석방심사위원회(이하 이 장에서 "위원회"라 한다)를 둔다.', 892);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6963, '제120조(위원회의 구성)', 892);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6964, '제121조(가석방 적격심사)', 892);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6965, '제122조(가석방 허가)', 892);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6966, '제123조(석방) 소장은 사면ㆍ형기종료 또는 권한이 있는 사람의 명령에 따라 수용자를 석방한다. <개정 2020.2.4>', 893);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6967, '제124조(석방시기)', 893);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6968, '제125조(피석방자의 일시수용) 소장은 피석방자가 질병이나 그 밖에 피할 수 없는 사정으로 귀가하기 곤란한 경우에 본인의 신청이 있으면 일시적으로 교정시설에 수용할 수 있다.', 893);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6969, '제126조(귀가여비의 지급 등) 소장은 피석방자에게 귀가에 필요한 여비 또는 의류가 없으면 법무부장관이 정하는 범위에서 이를 지급하거나 빌려 줄 수 있다.', 893);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6970, '제126조의2(석방예정자의 수용이력 등 통보)', 893);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6971, '제127조(사망 알림) 소장은 수용자가 사망한 경우에는 그 사실을 즉시 그 가족(가족이 없는 경우에는 다른 친족)에게 알려야 한다. <개정 2020.2.4>', 894);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6972, '제128조(시신의 인도 등)', 894);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6973, '제129조(교정자문위원회)', 895);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6974, '제130조(교정위원)', 895);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6975, '제131조(기부금품의 접수) 소장은 기관ㆍ단체 또는 개인이 수용자의 교화 등을 위하여 교정시설에 자발적으로 기탁하는 금품을 받을 수 있다.', 895);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6976, '제132조(금지물품을 지닌 경우)', 896);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6977, '제133조(금지물품의 반입)', 896);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6978, '제134조(출석의무 위반 등) 다음 각 호의 어느 하나에 해당하는 행위를 한 수용자는 1년 이하의 징역에 처한다. <개정 2020.2.4>', 896);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6979, '제135조(녹화 등의 금지) 소장의 허가 없이 교정시설 내부를 녹화ㆍ촬영한 사람은 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 896);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6980, '제136조(미수범) 제133조 및 제135조의 미수범은 처벌한다.', 896);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6981, '제137조(몰수) 제132조 및 제133조에 해당하는 금지물품은 몰수한다.', 896);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6982, '제1조(목적) 이 영은 「형의 집행 및 수용자의 처우에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 897);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6983, '제1조의2(협의체의 구성 및 운영 등)', 897);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6984, '제2조(판사 등의 시찰)', 897);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6985, '제3조(참관)', 897);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6986, '제4조(독거실의 비율) 교정시설을 새로 설치하는 경우에는 법 제14조에 따른 수용자의 거실수용을 위하여 독거실(獨居室)과 혼거실(混居室)의 비율이 적정한 수준이 되도록 한다.', 899);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6987, '제5조(독거수용의 구분) 독거수용은 다음 각 호와 같이 구분한다.', 899);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6988, '제6조(계호상 독거수용자의 시찰)', 899);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6989, '제7조(여성수용자에 대한 시찰) 소장은 특히 필요하다고 인정하는 경우가 아니면 남성교도관이 야간에 수용자거실에 있는 여성수용자를 시찰하게 하여서는 아니 된다.', 899);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6990, '제8조(혼거수용 인원의 기준) 혼거수용 인원은 3명 이상으로 한다. 다만, 요양이나 그 밖의 부득이한 사정이 있는 경우에는 예외로 한다.', 899);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6991, '제9조(혼거수용의 제한) 소장은 노역장 유치명령을 받은 수형자와 징역형ㆍ금고형 또는 구류형을 선고받아 형이 확정된 수형자를 혼거수용해서는 아니 된다. 다만, 징역형ㆍ금고형 또는 구류형의 집행을 마친 다음에 계속해서 노역장 유치명령을 집행하거나 그 밖에 부득이한 사정이 있는 경우에는 그러하지 아니하다.', 899);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6992, '제10조(수용자의 자리 지정) 소장은 수용자의 생명ㆍ신체의 보호, 증거인멸의 방지 및 교정시설의 안전과 질서유지를 위하여 필요하다고 인정하면 혼거실ㆍ교육실ㆍ강당ㆍ작업장, 그 밖에 수용자들이 서로 접촉할 수 있는 장소에서 수용자의 자리를 지정할 수 있다.', 899);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6993, '제11조(거실의 대용금지) 소장은 수용자거실을 작업장으로 사용해서는 아니 된다. 다만, 수용자의 심리적 안정, 교정교화 또는 사회적응능력 함양을 위하여 특히 필요하다고 인정하면 그러하지 아니하다.', 899);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6994, '제12조(현황표 등의 부착 등)', 899);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6995, '제13조(신입자의 인수)', 899);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6996, '제14조(신입자의 신체 등 검사) 소장은 신입자를 인수한 경우에는 교도관에게 신입자의 신체ㆍ의류 및 휴대품을 지체 없이 검사하게 하여야 한다.', 899);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6997, '제15조(신입자의 건강진단) 법 제16조제2항에 따른 신입자의 건강진단은 수용된 날부터 3일 이내에 하여야 한다. 다만, 휴무일이 연속되는 등 부득이한 사정이 있는 경우에는 예외로 한다.', 899);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6998, '제16조(신입자의 목욕) 소장은 신입자에게 질병이나 그 밖의 부득이한 사정이 있는 경우가 아니면 지체 없이 목욕을 하게 하여야 한다.', 899);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (6999, '제17조(신입자의 신체 특징 기록 등)', 899);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7000, '제18조(신입자거실 수용 등)', 899);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7001, '제19조(수용기록부 등의 작성) 소장은 신입자 또는 이입자를 수용한 날부터 3일 이내에 수용기록부, 수용자명부 및 형기종료부를 작성ㆍ정비하고 필요한 사항을 기록하여야 한다.', 899);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7002, '제20조(신입자의 신원조사)', 899);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7003, '제21조(형 또는 구속의 집행정지 사유의 통보) 소장은 수용자에 대하여 건강상의 사유로 형의 집행정지 또는 구속의 집행정지를 할 필요가 있다고 인정하는 경우에는 의무관의 진단서와 인수인에 대한 확인서류를 첨부하여 그 사실을 검사에게, 기소된 상태인 경우에는 법원에도 지체 없이 통보하여야 한다.', 899);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7004, '제22조(지방교정청장의 이송승인권)', 899);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7005, '제23조(이송 중지) 소장은 수용자를 다른 교정시설에 이송하는 경우에 의무관으로부터 수용자가 건강상 감당하기 어렵다는 보고를 받으면 이송을 중지하고 그 사실을 이송받을 소장에게 알려야 한다.', 899);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7006, '제24조(호송 시 분리) 수용자를 이송이나 출정(出廷), 그 밖의 사유로 호송하는 경우에는 수형자는 미결수용자와, 여성수용자는 남성수용자와, 19세 미만의 수용자는 19세 이상의 수용자와 각각 호송 차량의 좌석을 분리하는 등의 방법으로 서로 접촉하지 못하게 하여야 한다.', 899);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7007, '제25조(생활용품 지급 시의 유의사항)', 900);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7008, '제26조(생활기구의 비치)', 900);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7009, '제27조(음식물의 지급) 법 제23조에 따라 수용자에게 지급하는 음식물은 주식ㆍ부식ㆍ음료, 그 밖의 영양물로 한다.', 900);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7010, '제28조(주식의 지급)', 900);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7011, '제29조(특식의 지급) 소장은 국경일이나 그 밖에 이에 준하는 날에는 특별한 음식물을 지급할 수 있다.', 900);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7012, '제30조(환자의 음식물) 소장은 의무관의 의견을 고려하여 환자에게 지급하는 음식물의 종류 또는 정도를 달리 정할 수 있다.', 900);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7013, '제31조(자비 구매 물품의 기준) 수용자가 자비로 구매하는 물품은 교화 또는 건전한 사회복귀에 적합하고 교정시설의 안전과 질서를 해칠 우려가 없는 것이어야 한다.', 900);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7014, '제32조(자비 구매 의류등의 사용) 소장은 수용자가 자비로 구매한 의류등을 보관한 후 그 수용자가 사용하게 할 수 있다. <개정 2020.8.5>', 900);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7015, '제33조(의류등의 세탁 등)', 900);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7016, '제34조(휴대금품의 정의 등)', 901);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7017, '제35조(금품의 보관) 수용자의 현금을 보관하는 경우에는 그 금액을 보관금대장에 기록하고 수용자의 물품을 보관하는 경우에는 그 품목ㆍ수량 및 규격을 보관품대장에 기록해야 한다. <개정 2020.8.5>', 901);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7018, '제36조(귀중품의 보관) 소장은 보관품이 금ㆍ은ㆍ보석ㆍ유가증권ㆍ인장, 그 밖에 특별히 보관할 필요가 있는 귀중품인 경우에는 잠금장치가 되어 있는 견고한 용기에 넣어 보관해야 한다. <개정 2020.8.5>', 901);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7019, '제37조(보관품 매각대금의 보관) 소장은 수용자의 신청에 따라 보관품을 팔 경우에는 그 비용을 제외한 나머지 대금을 보관할 수 있다. <개정 2020.8.5>', 901);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7020, '제38조(보관금의 사용 등)', 901);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7021, '제39조(지닐 수 없는 물품의 처리) 법 제26조제2항 및 제3항에 따라 지닐 수 있는 범위를 벗어난 수용자의 물품을 처분하거나 폐기하는 경우에는 제34조제3항 및 제4항을 준용한다. <개정 2020.8.5>', 901);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7022, '제40조(물품의 폐기) 수용자의 물품을 폐기하는 경우에는 그 품목ㆍ수량ㆍ이유 및 일시를 관계 장부에 기록하여야 한다.', 901);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7023, '제41조(금품전달 신청자의 확인) 소장은 수용자가 아닌 사람이 법 제27조제1항에 따라 수용자에게 금품을 건네줄 것을 신청하는 경우에는 그의 성명ㆍ주소 및 수용자와의 관계를 확인해야 한다. <개정 2020.8.5>', 901);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7024, '제42조(전달 허가금품의 사용 등)', 901);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7025, '제43조(전달 허가물품의 검사) 소장은 법 제27조제1항에 따라 건네줄 것을 허가한 물품은 검사할 필요가 없다고 인정되는 경우가 아니면 교도관으로 하여금 검사하게 해야 한다. 이 경우 그 물품이 의약품인 경우에는 의무관으로 하여금 검사하게 해야 한다. <개정 2020.8.5>', 901);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7026, '제44조(보관의 예외) 음식물은 보관의 대상이 되지 않는다. <개정 2020.8.5>', 901);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7027, '제45조(유류금품의 처리)', 901);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7028, '제46조(보건ㆍ위생관리계획의 수립 등) 소장은 수용자의 건강, 계절 및 시설여건 등을 고려하여 보건ㆍ위생관리계획을 정기적으로 수립하여 시행하여야 한다.', 902);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7029, '제47조(시설의 청소ㆍ소독)', 902);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7030, '제48조(청결의무) 수용자는 교도관이 법 제32조제1항에 따라 자신이 사용하는 거실, 작업장, 그 밖의 수용시설의 청결을 유지하기 위하여 필요한 지시를 한 경우에는 이에 따라야 한다.', 902);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7031, '제49조(실외운동) 소장은 수용자가 매일(공휴일 및 법무부장관이 정하는 날은 제외한다) 「국가공무원 복무규정」 제9조에 따른 근무시간 내에서 1시간 이내의 실외운동을 할 수 있도록 하여야 한다. 다만, 다음 각 호의 어느 하나에 해당하면 실외운동을 실시하지 아니할 수 있다.', 902);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7032, '제50조(목욕횟수) 소장은 작업의 특성, 계절, 그 밖의 사정을 고려하여 수용자의 목욕횟수를 정하되 부득이한 사정이 없으면 매주 1회 이상이 되도록 한다.', 902);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7033, '제51조(건강검진횟수)', 902);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7034, '제52조(감염병의 정의) 법 제18조제1항, 법 제53조제1항제3호 및 법 제128조제2항에서 "감염병"이란 「감염병의 예방 및 관리에 관한 법률」에 따른 감염병을 말한다. <개정 2010.12.29>', 902);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7035, '제53조(감염병에 관한 조치)', 902);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7036, '제54조(의료거실 수용 등) 소장은 수용자가 부상을 당하거나 질병에 걸린 경우에는 그 수용자를 의료거실에 수용하거나, 다른 수용자에게 그 수용자를 간병하게 할 수 있다.', 902);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7037, '제54조의2(간호사의 의료행위) 법 제36조제2항에서 "대통령령으로 정하는 경미한 의료행위"란 다음 각 호의 의료행위를 말한다.', 902);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7038, '제55조(외부의사의 치료) 소장은 특히 필요하다고 인정하면 외부 의료시설에서 근무하는 의사(이하 "외부의사"라 한다)에게 수용자를 치료하게 할 수 있다.', 902);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7039, '제56조(위독 사실의 알림) 소장은 수용자가 위독한 경우에는 그 사실을 가족에게 지체 없이 알려야 한다.', 902);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7040, '제57조(외부 의료시설 입원 등 보고) 소장은 법 제37조제1항에 따라 수용자를 외부 의료시설에 입원시키거나 입원 중인 수용자를 교정시설로 데려온 경우에는 그 사실을 법무부장관에게 지체 없이 보고하여야 한다.', 902);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7041, '제58조(접견)', 903);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7042, '제59조(접견의 예외)', 903);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7043, '제59조의2(변호사 와의 접견)', 903);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7044, '제60조(접견 시 외국어 사용)', 903);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7045, '제61조(접견 시 유의사항 고지) 소장은 법 제41조에 따라 접견을 하게 하는 경우에는 수용자와 그 상대방에게 접견 시 유의사항을 방송이나 게시물 부착 등 적절한 방법으로 알려줘야 한다.', 903);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7046, '제62조(접견내용의 청취ㆍ기록ㆍ녹음ㆍ녹화)', 903);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7047, '제63조(접견중지 사유의 고지) 교도관이 법 제42조에 따라 수용자의 접견을 중지한 경우에는 그 사유를 즉시 알려주어야 한다.', 903);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7048, '제64조(편지수수의 횟수) 수용자가 보내거나 받는 편지는 법령에 어긋나지 않으면 횟수를 제한하지 않는다. <개정 2020.8.5>', 903);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7049, '제65조(편지 내용물의 확인)', 903);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7050, '제66조(편지 내용의 검열)', 903);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7051, '제67조(관계기관 송부문서) 소장은 법원ㆍ경찰관서, 그 밖의 관계기관에서 수용자에게 보내온 문서는 다른 법령에 특별한 규정이 없으면 열람한 후 본인에게 전달하여야 한다.', 903);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7052, '제68조(편지 등의 대서) 소장은 수용자가 편지, 소송서류, 그 밖의 문서를 스스로 작성할 수 없어 대신 써 달라고 요청하는 경우에는 교도관이 대신 쓰게 할 수 있다. <개정 2020.8.5>', 903);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7053, '제69조(편지 등 발송비용의 부담) 수용자의 편지ㆍ소송서류, 그 밖의 문서를 보내는 경우에 드는 비용은 수용자가 부담한다. 다만, 소장은 수용자가 그 비용을 부담할 수 없는 경우에는 예산의 범위에서 해당 비용을 부담할 수 있다. <개정 2014.6.25, 2020.8.5>', 903);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7054, '제70조(전화통화) 수용자의 전화통화에 관하여는 제60조제1항 및 제63조를 준용한다.', 903);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7055, '제71조(참고사항의 기록) 교도관은 수용자의 접견, 편지수수, 전화통화 등의 과정에서 수용자의 처우에 특히 참고할 사항을 알게 된 경우에는 그 요지를 수용기록부에 기록해야 한다. <개정 2020.8.5>', 903);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7056, '제72조(비치도서의 이용)', 904);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7057, '제73조(라디오 청취 등의 방법) 법 제48조제1항에 따른 수용자의 라디오 청취와 텔레비전 시청은 교정시설에 설치된 방송설비를 통하여 할 수 있다.', 904);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7058, '제74조(집필용구의 구입비용) 집필용구의 구입비용은 수용자가 부담한다. 다만, 소장은 수용자가 그 비용을 부담할 수 없는 경우에는 필요한 집필용구를 지급할 수 있다.', 904);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7059, '제75조(집필의 시간대ㆍ시간 및 장소)', 904);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7060, '제76조(문서ㆍ도화의 외부 발송 등)', 904);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7061, '제77조(여성수용자의 목욕)', 905);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7062, '제78조(출산의 범위) 법 제52조제1항에서 "출산(유산ㆍ사산을 포함한다)한 경우"란 출산(유산ㆍ사산한 경우를 포함한다) 후 60일이 지나지 아니한 경우를 말한다. <개정 2019.10.22>', 905);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7063, '제79조(유아의 양육) 소장은 법 제53조제1항에 따라 유아의 양육을 허가한 경우에는 교정시설에 육아거실을 지정ㆍ운영하여야 한다.', 905);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7064, '제80조(유아의 인도)', 905);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7065, '제81조(노인수용자 등의 정의)', 905);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7066, '제82조(수형자로서의 처우 개시)', 907);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7067, '제83조(경비등급별 설비 및 계호) 법 제57조제2항 각 호의 수용설비 및 계호의 정도는 다음 각 호의 규정에 어긋나지 않는 범위에서 법무부장관이 정한다.', 907);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7068, '제84조(수형자의 처우등급 부여 등)', 907);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7069, '제85조(수형자 취업알선 등 협의기구)', 907);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7070, '제86조(분류전담시설) 법무부장관은 법 제61조의 분류심사를 전담하는 교정시설을 지정ㆍ운영하는 경우에는 지방교정청별로 1개소 이상이 되도록 하여야 한다.', 908);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7071, '제87조(교육)', 909);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7072, '제88조(정서교육) 소장은 수형자의 정서 함양을 위하여 필요하다고 인정하면 연극ㆍ영화관람, 체육행사, 그 밖의 문화예술활동을 하게 할 수 있다.', 909);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7073, '제89조(작업의 종류) 소장은 법무부장관의 승인을 받아 수형자에게 부과하는 작업의 종류를 정한다.', 910);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7074, '제90조(소년수형자의 작업 등) 소장은 19세 미만의 수형자에게 작업을 부과하는 경우에는 정신적ㆍ신체적 성숙 정도, 교육적 효과 등을 고려하여야 한다.', 910);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7075, '제91조(작업의 고지 등)', 910);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7076, '제92조(작업실적의 확인) 소장은 교도관에게 매일 수형자의 작업실적을 확인하게 하여야 한다.', 910);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7077, '제93조(신청 작업의 취소) 소장은 법 제67조에 따라 작업이 부과된 수형자가 작업의 취소를 요청하는 경우에는 그 수형자의 의사(意思), 건강 및 교도관의 의견 등을 고려하여 작업을 취소할 수 있다.', 910);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7078, '제94조(직업능력개발훈련 설비 등의 구비) 소장은 법 제69조에 따른 직업능력개발훈련을 하는 경우에는 그에 필요한 설비 및 실습 자재를 갖추어야 한다.', 910);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7079, '제95조(집중근로) 법 제70조제1항에서 "집중적인 근로가 필요한 작업"이란 수형자의 신청에 따라 1일 작업시간 중 접견ㆍ전화통화ㆍ교육 및 공동행사 참가 등을 하지 아니하고 휴게시간을 제외한 작업시간 내내 하는 작업을 말한다.', 910);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7080, '제96조(휴업일) 법 제71조에서 "그 밖의 휴일"이란 「각종 기념일 등에 관한 규정」에 따른 교정의 날 및 소장이 특히 지정하는 날을 말한다. <개정 2017.9.19>', 910);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7081, '제97조(귀휴자에 대한 조치)', 911);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7082, '제98조(미결수용시설의 설비 및 계호의 정도) 미결수용자를 수용하는 시설의 설비 및 계호의 정도는 법 제57조제2항제3호의 일반경비시설에 준한다.', 912);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7083, '제99조(법률구조 지원) 소장은 미결수용자가 빈곤하거나 무지하여 수사 및 재판 과정에서 권리를 충분히 행사하지 못한다고 인정하는 경우에는 법률구조에 필요한 지원을 할 수 있다.', 912);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7084, '제100조(공범 분리) 소장은 이송이나 출정, 그 밖의 사유로 미결수용자를 교정시설 밖으로 호송하는 경우에는 해당 사건에 관련된 사람과 호송 차량의 좌석을 분리하는 등의 방법으로 서로 접촉하지 못하게 하여야 한다.', 912);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7085, '제101조(접견 횟수) 미결수용자의 접견 횟수는 매일 1회로 하되, 변호인과의 접견은 그 횟수에 포함시키지 않는다.', 912);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7086, '제102조(접견의 예외) 소장은 미결수용자의 처우를 위하여 특히 필요하다고 인정하면 제58조제1항에도 불구하고 접견 시간대 외에도 접견하게 할 수 있고, 변호인이 아닌 사람과 접견하는 경우에도 제58조제2항 및 제101조에도 불구하고 접견시간을 연장하거나 접견 횟수를 늘릴 수 있다. <개정 2019.10.22>', 912);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7087, '제103조(교육ㆍ교화와 작업)', 912);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7088, '제104조(도주 등 통보) 소장은 미결수용자가 도주하거나 도주한 미결수용자를 체포한 경우에는 그 사실을 검사에게 통보하고, 기소된 상태인 경우에는 법원에도 지체 없이 통보하여야 한다.', 912);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7089, '제105조(사망 등 통보) 소장은 미결수용자가 위독하거나 사망한 경우에는 그 사실을 검사에게 통보하고, 기소된 상태인 경우에는 법원에도 지체 없이 통보하여야 한다.', 912);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7090, '제106조(외부의사의 진찰 등) 미결수용자가 「형사소송법」 제34조, 제89조 및 제209조에 따라 외부의사의 진료를 받는 경우에는 교도관이 참여하고 그 경과를 수용기록부에 기록하여야 한다.', 912);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7091, '제107조(유치장 수용기간) 경찰관서에 설치된 유치장에는 수형자를 30일 이상 수용할 수 없다.', 912);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7092, '제108조(사형확정자 수용시설의 설비 및 계호의 정도) 사형확정자를 수용하는 시설의 설비 및 계호의 정도는 법 제57조제2항제3호의 일반경비시설 또는 같은 항 제4호의 중경비시설에 준한다. <개정 2017.9.19>', 913);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7093, '제109조(접견 횟수) 사형확정자의 접견 횟수는 매월 4회로 한다.', 913);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7094, '제110조(접견의 예외) 소장은 제58조제1항ㆍ제2항 및 제109조에도 불구하고 사형확정자의 교화나 심리적 안정을 도모하기 위하여 특히 필요하다고 인정하면 접견 시간대 외에도 접견을 하게 할 수 있고 접견시간을 연장하거나 접견 횟수를 늘릴 수 있다. <개정 2019.10.22>', 913);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7095, '제111조(사형집행 후의 검시) 소장은 사형을 집행하였을 경우에는 시신을 검사한 후 5분이 지나지 아니하면 교수형에 사용한 줄을 풀지 못한다. <개정 2014.6.25>', 913);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7096, '제112조(거실 등에 대한 검사) 소장은 교도관에게 수용자의 거실, 작업장, 그 밖에 수용자가 생활하는 장소(이하 이 조에서 "거실등"이라 한다)를 정기적으로 검사하게 하여야 한다. 다만, 법 제92조의 금지물품을 숨기고 있다고 의심되는 수용자와 법 제104조제1항의 마약류사범ㆍ조직폭력사범 등 법무부령으로 정하는 수용자의 거실등은 수시로 검사하게 할 수 있다.', 914);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7097, '제113조(신체 등에 대한 검사) 소장은 교도관에게 작업장이나 실외에서 수용자거실로 돌아오는 수용자의 신체ㆍ의류 및 휴대품을 검사하게 하여야 한다. 다만, 교정성적 등을 고려하여 그 검사가 필요하지 아니하다고 인정되는 경우에는 예외로 할 수 있다.', 914);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7098, '제114조(검사장비의 이용) 교도관은 법 제93조에 따른 검사를 위하여 탐지견, 금속탐지기, 그 밖의 장비를 이용할 수 있다.', 914);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7099, '제115조(외부인의 출입)', 914);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7100, '제116조(외부와의 차단)', 914);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7101, '제117조(거실 개문 등 제한) 교도관은 수사ㆍ재판ㆍ운동ㆍ접견ㆍ진료 등 수용자의 처우 또는 자살방지, 화재진압 등 교정시설의 안전과 질서유지를 위하여 필요한 경우가 아니면 수용자거실의 문을 열거나 수용자를 거실 밖으로 나오게 해서는 아니 된다.', 914);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7102, '제118조(장애물 방치 금지) 교정시설의 구내에는 시야를 가리거나 그 밖에 계호상 장애가 되는 물건을 두어서는 아니 된다.', 914);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7103, '제119조(보호실 등 수용중지)', 914);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7104, '제120조(보호장비의 사용)', 914);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7105, '제121조(보호장비 사용중지 등)', 914);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7106, '제122조(보호장비 사용사유의 고지) 보호장비를 사용하는 경우에는 수용자에게 그 사유를 알려주어야 한다.', 914);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7107, '제123조(보호장비 착용 수용자의 거실 지정) 보호장비를 착용 중인 수용자는 특별한 사정이 없으면 계호상 독거수용한다.', 914);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7108, '제124조(보호장비 사용의 감독)', 914);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7109, '제125조(강제력의 행사) 교도관은 소장의 명령 없이 법 제100조에 따른 강제력을 행사해서는 아니 된다. 다만, 그 명령을 받을 시간적 여유가 없는 경우에는 강제력을 행사한 후 소장에게 즉시 보고하여야 한다. <개정 2014.6.25>', 914);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7110, '제126조(무기사용 보고) 교도관은 법 제101조에 따라 무기를 사용한 경우에는 소장에게 즉시 보고하고, 보고를 받은 소장은 그 사실을 법무부장관에게 즉시 보고하여야 한다. <개정 2014.6.25>', 914);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7111, '제127조(재난 시의 조치)', 914);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7112, '제128조(도주 등에 따른 조치)', 914);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7113, '제128조의2(포상금 지급)', 914);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7114, '제128조의3(포상금의 지급 신청)', 914);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7115, '제128조의4(포상금의 환수) 법무부장관은 제128조의2제1항에 따라 포상금을 지급한 후 다음 각 호의 어느 하나에 해당하는 사실이 발견된 경우에는 해당 포상금을 환수할 수 있다.', 914);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7116, '제129조(징벌위원회의 소집) 법 제111조에 따른 징벌위원회(이하 이 장에서 "위원회"라 한다)의 위원장은 소장의 징벌요구에 따라 위원회를 소집한다.', 915);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7117, '제130조(위원장의 직무대행) 위원회의 위원장이 불가피한 사정으로 그 직무를 수행하기 어려운 경우에는 위원장이 미리 지정한 위원이 그 직무를 대행한다.', 915);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7118, '제131조(위원의 제척) 위원회의 위원이 해당 징벌대상 행위의 조사를 담당한 경우에는 해당 위원회에 참석할 수 없다.', 915);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7119, '제132조(징벌의결 통고) 위원회가 징벌을 의결한 경우에는 이를 소장에게 즉시 통고하여야 한다.', 915);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7120, '제133조(징벌의 집행)', 915);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7121, '제134조(징벌집행의 계속) 법 제108조제4호부터 제14호까지의 징벌 집행 중인 수용자가 다른 교정시설로 이송되거나 법원 또는 검찰청 등에 출석하는 경우에는 징벌집행이 계속되는 것으로 본다.', 915);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7122, '제135조(징벌기간의 계산) 소장은 법 제113조제1항에 따라 징벌집행을 일시 정지한 경우 그 정지사유가 해소되었을 때에는 지체 없이 징벌집행을 재개하여야 한다. 이 경우 집행을 정지한 다음날부터 집행을 재개한 전날까지의 일수는 징벌기간으로 계산하지 아니한다.', 915);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7123, '제136조(이송된 사람의 징벌) 수용자가 이송 중에 징벌대상 행위를 하거나 다른 교정시설에서 징벌대상 행위를 한 사실이 이송된 후에 발각된 경우에는 그 수용자를 인수한 소장이 징벌을 부과한다.', 915);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7124, '제137조(징벌사항의 기록) 소장은 수용자의 징벌에 관한 사항을 수용기록부 및 징벌집행부에 기록하여야 한다.', 915);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7125, '제138조(소장 면담)', 916);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7126, '제139조(순회점검공무원에 대한 청원)', 916);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7127, '제139조의2(정보공개의 예상비용 등)', 916);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7128, '제140조(가석방자가 지켜야 할 사항의 알림 등) 소장은 법 제122조제2항의 가석방 허가에 따라 수형자를 가석방하는 경우에는 가석방자 교육을 하고, 지켜야 할 사항을 알려준 후 증서를 발급해야 한다. <개정 2020.8.5>', 918);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7129, '제141조(석방예정자 상담 등) 소장은 수형자의 건전한 사회복귀를 위하여 필요하다고 인정하면 석방 전 3일 이내의 범위에서 석방예정자를 별도의 거실에 수용하여 장래에 관한 상담과 지도를 할 수 있다.', 919);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7130, '제142조(형기종료 석방예정자의 사전조사) 소장은 형기종료로 석방될 수형자에 대하여는 석방 10일 전까지 석방 후의 보호에 관한 사항을 조사하여야 한다.', 919);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7131, '제143조(석방예정자의 수용이력 등 통보)', 919);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7132, '제144조(석방예정자의 보호조치) 소장은 수형자를 석방하는 경우 특히 필요하다고 인정하면 한국법무보호복지공단에 그에 대한 보호를 요청할 수 있다. <개정 2009.3.18>', 919);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7133, '제145조(귀가여비 등의 회수) 소장은 법 제126조에 따라 피석방자에게 귀가 여비 또는 의류를 빌려준 경우에는 특별한 사유가 없으면 이를 회수한다.', 919);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7134, '제145조의2(증명서의 발급) 소장은 다음 각 호에 해당하는 사람의 신청에 따라 교정시설에 수용된 사실 또는 수용되었다가 석방된 사실에 관한 증명서를 발급할 수 있다. <개정 2020.8.5>', 919);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7135, '제145조의3(고유식별정보의 처리) 소장은 제145조의2에 따른 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법 시행령」 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 919);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7136, '제146조(사망 알림) 소장은 법 제127조에 따라 수용자의 사망 사실을 알리는 경우에는 사망 일시ㆍ장소 및 사유도 같이 알려야 한다.', 920);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7137, '제147조(검시) 소장은 수용자가 사망한 경우에는 그 시신을 검사하여야 한다. <개정 2014.6.25>', 920);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7138, '제148조(사망 등 기록)', 920);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7139, '제149조 삭제 <2015.12.10>', 920);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7140, '제150조(임시 매장지의 표지 등)', 920);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7141, '제151조(교정위원)', 921);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7142, '제152조(외부인사가 지켜야 할 사항) 교정위원, 교정자문위원, 그 밖에 교정시설에서 활동하는 외부인사는 활동 중에 알게 된 교정시설의 안전과 질서 및 수용자의 신상에 관한 사항을 외부에 누설하거나 공개해서는 안 된다. <개정 2020.8.5>', 921);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7143, '제153조(기부금품의 접수 등)', 921);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7144, '제1조(목적) 이 규칙은 「형의 집행 및 수용자의 처우에 관한 법률」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 922);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7145, '제2조(정의) 이 규칙에서 사용하는 용어의 뜻은 다음과 같다. <개정 2010.5.31, 2014.11.17, 2020.8.5>', 922);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7146, '제3조(범죄횟수)', 922);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7147, '제4조(의류의 품목)', 925);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7148, '제5조(의류의 품목별 착용 시기 및 대상) 수용자 의류의 품목별 착용 시기 및 대상은 다음 각 호와 같다. <개정 2010.5.31, 2013.4.16, 2014.11.17>', 925);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7149, '제6조(침구의 품목) 수용자 침구의 품목은 이불 2종(솜이불ㆍ겹이불), 매트리스 2종(일반매트리스ㆍ환자매트리스), 담요 및 베개로 구분한다.', 925);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7150, '제7조(침구의 품목별 사용 시기 및 대상) 수용자 침구의 품목별 사용 시기 및 대상은 다음 각 호와 같다. <개정 2013.4.16>', 925);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7151, '제8조(의류ㆍ침구 등 생활용품의 지급기준)', 925);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7152, '제9조(의류ㆍ침구의 색채ㆍ규격) 수용자 의류ㆍ침구의 품목별 색채 및 규격은 법무부장관이 정한다.', 925);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7153, '제10조(주식의 지급) 소장이 「형의 집행 및 수용자의 처우에 관한 법률 시행령」(이하 "영"이라 한다) 제28조제2항에 따라 주식을 쌀과 보리 등 잡곡의 혼합곡으로 하거나 대용식을 지급하는 경우에는 법무부장관이 정하는 바에 따른다.', 926);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7154, '제11조(주식의 지급)', 926);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7155, '제12조(주식의 확보) 소장은 수용자에 대한 원활한 급식을 위하여 해당 교정시설의 직전 분기 평균 급식 인원을 기준으로 1개월분의 주식을 항상 확보하고 있어야 한다.', 926);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7156, '제13조(부식)', 926);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7157, '제14조(주ㆍ부식의 지급횟수 등)', 926);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7158, '제15조(특식 등 지급)', 926);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7159, '제16조(자비구매물품의 종류 등)', 927);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7160, '제17조(구매허가 및 신청제한)', 927);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7161, '제18조(우선 공급) 소장은 교도작업제품(교정시설 안에서 수용자에게 부과된 작업에 의하여 생산된 물품을 말한다)으로서 자비구매물품으로 적합한 것은 제21조에 따라 지정받은 자비구매물품 공급자를 거쳐 우선하여 공급할 수 있다.', 927);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7162, '제19조(제품 검수)', 927);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7163, '제20조(주요사항 고지 등)', 927);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7164, '제21조(공급업무의 담당자 지정)', 927);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7165, '제22조(전달금품의 허가)', 927);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7166, '제23조(의료설비의 기준)', 928);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7167, '제24조(비상의료용품 기준)', 928);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7168, '제25조(전화통화의 허가)', 929);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7169, '제26조(전화이용시간)', 929);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7170, '제27조(통화허가의 취소) 소장은 다음 각 호의 어느 하나에 해당할 때에는 전화통화의 허가를 취소할 수 있다.', 929);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7171, '제28조(통화내용의 청취ㆍ녹음)', 929);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7172, '제29조(통화요금의 부담)', 929);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7173, '제29조의2(세부사항) 이 규칙에서 정한 사항 외에 전화통화의 허가범위, 통화내용의 청취ㆍ녹음 등에 필요한 세부사항은 법무부장관이 정한다.', 929);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7174, '제29조의3(소송사건의 대리인인 변호사 등의 접견 등 신청)', 929);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7175, '제30조(종교행사의 종류) 「형의 집행 및 수용자의 처우에 관한 법률」(이하 "법"이라 한다) 제45조에 따른 종교행사의 종류는 다음 각 호와 같다.', 931);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7176, '제31조(종교행사의 방법)', 931);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7177, '제32조(종교행사의 참석대상) 수용자는 자신이 신봉하는 종교행사에 참석할 수 있다. 다만, 소장은 다음 각 호의 어느 하나에 해당할 때에는 수용자의 종교행사 참석을 제한할 수 있다.', 931);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7178, '제33조(종교상담) 소장은 수용자가 종교상담을 신청하거나 수용자에게 종교상담이 필요한 경우에는 해당 종교를 신봉하는 교도관 또는 교정참여인사(법 제130조의 교정위원, 그 밖에 교정행정에 참여하는 사회 각 분야의 사람 중 학식과 경험이 풍부한 사람을 말한다)로 하여금 상담하게 할 수 있다. <개정 2020.8.5>', 931);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7179, '제34조(종교물품 등을 지닐 수 있는 범위)', 931);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7180, '제35조(구독신청 수량) 법 제47조에 따라 수용자가 구독을 신청할 수 있는 신문ㆍ잡지 또는 도서(이하 이 절에서 "신문등"이라 한다)는 교정시설의 보관범위 및 수용자가 지닐 수 있는 범위를 벗어나지 않는 범위에서 신문은 월 3종 이내로, 도서(잡지를 포함한다)는 월 10권 이내로 한다. 다만, 소장은 수용자의 지식함양 및 교양습득에 특히 필요하다고 인정하는 경우에는 신문등의 신청 수량을 늘릴 수 있다. <개정 2020.8.5>', 932);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7181, '제36조(구독허가의 취소 등)', 932);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7182, '제37조(방송의 기본원칙)', 933);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7183, '제38조(방송설비)', 933);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7184, '제39조(방송편성시간) 소장은 수용자의 건강과 일과시간 등을 고려하여 1일 6시간 이내에서 방송편성시간을 정한다. 다만, 토요일ㆍ공휴일, 작업ㆍ교육실태 및 수용자의 특성을 고려하여 방송편성시간을 조정할 수 있다.', 933);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7185, '제40조(방송프로그램)', 933);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7186, '제41조(수용자가 지켜야 할 사항 등)', 933);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7187, '제42조(임산부수용자 등에 대한 특칙) 소장은 임산부인 수용자 및 법 제53조에 따라 유아의 양육을 허가받은 수용자에 대하여 필요하다고 인정하는 경우에는 교정시설에 근무하는 의사(공중보건의사를 포함한다. 이하 "의무관"이라 한다)의 의견을 들어 필요한 양의 죽 등의 주식과 별도로 마련된 부식을 지급할 수 있으며, 양육유아에 대하여는 분유 등의 대체식품을 지급할 수 있다. <개정 2014.11.17>', 935);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7188, '제43조(전담교정시설)', 936);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7189, '제44조(수용거실)', 936);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7190, '제45조(주ㆍ부식 등 지급) 소장은 노인수용자의 나이ㆍ건강상태 등을 고려하여 필요하다고 인정하면 제4조부터 제8조까지의 규정, 제10조, 제11조, 제13조 및 제14조에 따른 수용자의 지급기준을 초과하여 주ㆍ부식, 의류ㆍ침구, 그 밖의 생활용품을 지급할 수 있다.', 936);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7191, '제46조(운동ㆍ목욕)', 936);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7192, '제47조(전문의료진 등)', 936);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7193, '제48조(교육ㆍ교화프로그램 및 작업)', 936);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7194, '제49조(정의) "장애인수용자"란 「장애인복지법 시행령」 별표 1의 제1호부터 제15호까지의 규정에 해당하는 사람으로서 시각ㆍ청각ㆍ언어ㆍ지체(肢體) 등의 장애로 통상적인 수용생활이 특히 곤란하다고 인정되는 수용자를 말한다. <개정 2013.4.16>', 937);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7195, '제50조(전담교정시설)', 937);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7196, '제51조(수용거실)', 937);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7197, '제52조(전문의료진 등) 장애인수형자 전담교정시설의 장은 장애인의 재활에 관한 전문적인 지식을 가진 의료진과 장비를 갖추도록 노력하여야 한다.', 937);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7198, '제53조(직업훈련) 장애인수형자 전담교정시설의 장은 장애인수형자에 대한 직업훈련이 석방 후의 취업과 연계될 수 있도록 그 프로그램의 편성 및 운영에 특히 유의하여야 한다.', 937);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7199, '제54조(준용규정) 장애인수용자의 장애정도, 건강 등을 고려하여 필요하다고 인정하는 경우 주ㆍ부식 등의 지급, 운동ㆍ목욕 및 교육ㆍ교화프로그램ㆍ작업에 관하여 제45조ㆍ제46조 및 제48조를 준용한다.', 937);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7200, '제55조(전담교정시설) 법 제57조제6항에 따라 법무부장관이 외국인수형자의 처우를 전담하도록 정하는 시설의 장은 외국인의 특성에 알맞은 교화프로그램 등을 개발하여 시행하여야 한다. <개정 2015.12.10>', 938);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7201, '제56조(전담요원 지정)', 938);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7202, '제57조(수용거실 지정)', 938);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7203, '제58조(주ㆍ부식 지급)', 938);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7204, '제59조(위독 또는 사망 시의 조치) 소장은 외국인수용자가 질병 등으로 위독하거나 사망한 경우에는 그의 국적이나 시민권이 속하는 나라의 외교공관 또는 영사관의 장이나 그 관원 또는 가족에게 이를 즉시 알려야 한다. <개정 2020.8.5>', 938);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7205, '제59조의2(전담교정시설)', 939);
