INSERT INTO balaw.jo (id, content, jang_id) VALUES (7207, '제59조의4(의류) 법무부장관은 제4조 및 제5조에도 불구하고 소년수용자의 나이ㆍ적성 등을 고려하여 필요하다고 인정하는 경우 의류의 품목과 품목별 착용 시기 및 대상을 달리 정할 수 있다.', 939);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7208, '제59조의5(접견ㆍ전화) 소장은 소년수형자등의 나이ㆍ적성 등을 고려하여 필요하다고 인정하면 제87조 및 제90조에 따른 접견 및 전화통화 횟수를 늘릴 수 있다.', 939);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7209, '제59조의6(사회적 처우) 제92조제1항에도 불구하고 소장은 소년수형자등의 나이ㆍ적성 등을 고려하여 필요하다고 인정하면 소년수형자등에게 같은 항 각 호에 해당하는 활동을 허가할 수 있다. 이 경우 소장이 허가할 수 있는 활동에는 발표회 및 공연 등 참가 활동을 포함한다.', 939);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7210, '제59조의7(준용규정) 소년수용자의 나이ㆍ건강상태 등을 고려하여 필요하다고 인정하는 경우 주ㆍ부식 등의 지급, 운동ㆍ목욕, 전문의료진 등 및 작업에 관하여 제45조부터 제48조까지의 규정을 준용한다. <개정 2024.2.8>', 939);
