INSERT INTO balaw.jo (id, content, jang_id) VALUES (7215, '제64조(신입심사 시기) 개별처우계획을 수립하기 위한 분류심사(이하 "신입심사"라 한다)는 매월 초일부터 말일까지 형집행지휘서가 접수된 수형자를 대상으로 하며, 그 다음 달까지 완료하여야 한다. 다만, 특별한 사유가 있는 경우에는 그 기간을 연장할 수 있다.', 942);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7216, '제65조(재심사의 구분) 개별처우계획을 조정할 것인지를 결정하기 위한 분류심사(이하 "재심사"라 한다)는 다음 각 호와 같이 구분한다.', 942);
