INSERT INTO balaw.jo (id, content, jang_id) VALUES (7293, '제139조(귀휴허가증 발급 등) 소장은 귀휴를 허가한 때에는 별지 제4호서식의 귀휴허가부에 기록하고 귀휴허가를 받은 수형자(이하 "귀휴자"라 한다)에게 별지 제5호서식의 귀휴허가증을 발급하여야 한다.', 954);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7294, '제140조(귀휴조건) 귀휴를 허가하는 경우 법 제77조제3항에 따라 붙일 수 있는 조건(이하 "귀휴조건"이라 한다)은 다음 각 호와 같다.', 954);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7295, '제141조(동행귀휴 등)', 954);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7296, '제142조(귀휴비용 등)', 954);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7297, '제143조(귀휴조건 위반에 대한 조치) 소장은 귀휴자가 귀휴조건을 위반한 경우에는 법 제78조에 따라 귀휴를 취소하거나 이의 시정을 위하여 필요한 조치를 하여야 한다.', 954);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7298, '제144조(기능) 영 제85조제1항에 따른 수형자 취업지원협의회(이하 이 장에서 "협의회"라 한다)의 기능은 다음 각 호와 같다. <개정 2010.5.31>', 955);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7299, '제145조(구성)', 955);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7300, '제146조(외부위원)', 955);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7301, '제147조(회장의 직무)', 955);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7302, '제148조(회의)', 955);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7303, '제149조(간사)', 955);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7304, '제150조(구분수용 등)', 956);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7305, '제151조(이송) 소장은 사형확정자의 교육ㆍ교화프로그램, 작업 등을 위하여 필요하거나 교정시설의 안전과 질서유지를 위하여 특히 필요하다고 인정하는 경우에는 법무부장관의 승인을 받아 사형확정자를 다른 교정시설로 이송할 수 있다.', 956);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7306, '제152조(상담)', 956);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7307, '제153조(작업)', 956);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7308, '제154조(교화프로그램) 소장은 사형확정자에 대하여 심리상담, 종교상담, 심리치료 등의 교화프로그램을 실시하는 경우에는 전문가에 의하여 집중적이고 지속적으로 이루어질 수 있도록 계획을 수립ㆍ시행하여야 한다.', 956);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7309, '제155조(전담교정시설 수용) 사형확정자에 대한 교육ㆍ교화프로그램, 작업 등의 처우를 위하여 법무부장관이 정하는 전담교정시설에 수용할 수 있다.', 956);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7310, '제156조(전화통화) 소장은 사형확정자의 심리적 안정과 원만한 수용생활을 위하여 필요하다고 인정하는 경우에는 월 3회 이내의 범위에서 전화통화를 허가할 수 있다.', 956);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7311, '제157조(교정장비의 종류) 교정장비의 종류는 다음 각 호와 같다.', 959);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7312, '제158조(교정장비의 관리)', 959);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7313, '제159조(교정장비 보유기준 등) 교정장비의 교정시설별 보유기준 및 관리방법 등에 관하여 필요한 사항은 법무부장관이 정한다.', 959);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7314, '제160조(전자장비의 종류) 교도관이 법 제94조에 따라 수용자 또는 시설을 계호하는 경우 사용할 수 있는 전자장비는 다음 각 호와 같다.', 960);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7315, '제161조(중앙통제실의 운영)', 960);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7316, '제162조(영상정보처리기기 설치)', 960);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7317, '제163조(거실수용자 계호)', 960);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7318, '제164조(전자감지기의 설치) 전자감지기는 교정시설의 주벽ㆍ울타리, 그 밖에 수용자의 도주 및 외부로부터의 침입을 방지하기 위하여 필요한 장소에 설치한다.', 960);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7319, '제165조(전자경보기의 사용) 교도관은 외부의료시설 입원, 이송ㆍ출정, 그 밖의 사유로 교정시설 밖에서 수용자를 계호하는 경우 보호장비나 수용자의 팔목 등에 전자경보기를 부착하여 사용할 수 있다.', 960);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7320, '제166조(물품검색기 설치 및 사용)', 960);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7321, '제167조(증거수집장비의 사용) 교도관은 수용자가 사후에 증명이 필요하다고 인정되는 행위를 하거나 사후 증명이 필요한 상태에 있는 경우 수용자에 대하여 증거수집장비를 사용할 수 있다.', 960);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7322, '제168조(녹음ㆍ녹화 기록물의 관리) 소장은 전자장비로 녹음ㆍ녹화된 기록물을 「공공기록물 관리에 관한 법률」에 따라 관리하여야 한다.', 960);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7323, '제169조(보호장비의 종류) 교도관이 법 제98조제1항에 따라 사용할 수 있는 보호장비는 다음 각 호로 구분한다. <개정 2018.5.2, 2020.8.5>', 961);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7324, '제170조(보호장비의 규격)', 961);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7325, '제171조(보호장비 사용 명령) 소장은 영 제120조제1항에 따라 보호장비 사용을 명령하거나 승인하는 경우에는 보호장비의 종류 및 사용방법을 구체적으로 지정하여야 하며, 이 규칙에서 정하지 아니한 방법으로 보호장비를 사용하게 해서는 아니 된다.', 961);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7326, '제172조(수갑의 사용방법)', 961);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7327, '제173조(머리보호장비의 사용방법) 머리보호장비는 별표 9의 방법으로 사용하며, 수용자가 머리보호장비를 임의로 해제하지 못하도록 다른 보호장비를 함께 사용할 수 있다.', 961);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7328, '제174조(발목보호장비의 사용방법) 발목보호장비의 사용방법은 다음 각 호와 같다.', 961);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7329, '제175조(보호대의 사용방법) 보호대의 사용방법은 다음 각 호와 같다. <개정 2024.2.8>', 961);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7330, '제176조(보호의자의 사용방법)', 961);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7331, '제177조(보호침대의 사용방법)', 961);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7332, '제178조(보호복의 사용방법)', 961);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7333, '제179조(포승의 사용방법)', 961);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7334, '제180조(둘 이상의 보호장비 사용) 하나의 보호장비로 사용목적을 달성할 수 없는 경우에는 둘 이상의 보호장비를 사용할 수 있다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 다른 보호장비와 같이 사용할 수 없다.', 961);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7335, '제181조(보호장비 사용의 기록) 교도관은 법 제97조제1항에 따라 보호장비를 사용하는 경우에는 별지 제10호서식의 보호장비 사용 심사부에 기록해야 한다. 다만, 법 제97조제1항제1호에 따라 보호장비를 사용하거나 같은 항 제2호부터 제4호까지의 규정에 따라 양손수갑을 사용하는 경우에는 호송계획서나 수용기록부의 내용 등으로 그 기록을 갈음할 수 있다. <개정 2024.2.8>', 961);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7336, '제182조(의무관의 건강확인) 의무관은 법 제97조제3항에 따라 보호장비 착용 수용자의 건강상태를 확인한 결과 특이사항을 발견한 경우에는 별지 제10호 서식의 보호장비 사용 심사부에 기록하여야 한다.', 961);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7337, '제183조(보호장비의 계속사용)', 961);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7338, '제184조(보호장비 사용의 중단)', 961);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7339, '제185조(보호장비 착용 수용자의 관찰 등) 소장은 제169조제5호부터 제7호까지의 규정에 따른 보호장비를 사용하거나 같은 조 제8호의 보호장비를 별표 19의 방법으로 사용하게 하는 경우에는 교도관으로 하여금 수시로 해당 수용자의 상태를 확인하고 매 시간마다 별지 제11호서식의 보호장비 착용자 관찰부에 기록하게 하여야 한다. 다만, 소장은 보호장비 착용자를 법 제94조에 따라 전자영상장비로 계호할 때에는 별지 제9호서식의 거실수용자 영상계호부에 기록하게 할 수 있다. <개정 2013.4.16>', 961);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7340, '제186조(보안장비의 종류) 교도관이 법 제100조에 따라 강제력을 행사하는 경우 사용할 수 있는 보안장비는 다음 각 호와 같다. <개정 2014.11.17>', 962);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7341, '제187조(보안장비의 종류별 사용요건)', 962);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7342, '제188조(보안장비의 종류별 사용기준) 보안장비의 종류별 사용기준은 다음 각 호와 같다.', 962);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7343, '제189조(무기의 종류) 교도관이 법 제101조에 따라 사용할 수 있는 무기의 종류는 다음 각 호와 같다. <개정 2014.11.17>', 963);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7344, '제190조(무기의 종류별 사용요건)', 963);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7345, '제191조(기관총의 설치) 기관총은 대공초소 또는 집중사격이 가장 용이한 장소에 설치하고, 유사 시 즉시 사용할 수 있도록 충분한 인원의 사수(射手)ㆍ부사수ㆍ탄약수를 미리 지정하여야 한다.', 963);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7346, '제192조(총기의 사용절차) 교도관이 총기를 사용하는 경우에는 구두경고, 공포탄 발사, 위협사격, 조준사격의 순서에 따라야 한다. 다만, 상황이 긴급하여 시간적 여유가 없을 때에는 예외로 한다. <개정 2014.11.17>', 963);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7347, '제193조(총기 교육 등)', 963);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7348, '제194조(엄중관리대상자의 구분) 법 제104조에 따라 교정시설의 안전과 질서유지를 위하여 다른 수용자와의 접촉을 차단하거나 계호를 엄중히 하여야 하는 수용자(이하 이 장에서 "엄중관리대상자"라 한다)는 다음 각 호와 같이 구분한다.', 965);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7349, '제195조(번호표 등 표시)', 965);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7350, '제196조(상담)', 965);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7351, '제197조(작업 부과) 소장은 엄중관리대상자에게 작업을 부과할 때에는 법 제59조제3항에 따른 조사나 검사 등의 결과를 고려하여야 한다.', 965);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7352, '제198조(지정대상) 조직폭력수용자의 지정대상은 다음 각 호와 같다. <개정 2013.4.16, 2014.11.17>', 966);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7353, '제199조(지정 및 해제)', 966);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7354, '제200조(수용자를 대표하는 직책 부여 금지) 소장은 조직폭력수용자에게 거실 및 작업장 등의 봉사원, 반장, 조장, 분임장, 그 밖에 수용자를 대표하는 직책을 부여해서는 아니 된다.', 966);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7355, '제201조(수형자 간 연계활동 차단을 위한 이송) 소장은 조직폭력수형자가 작업장 등에서 다른 수형자와 음성적으로 세력을 형성하는 등 집단화할 우려가 있다고 인정하는 경우에는 법무부장관에게 해당 조직폭력수형자의 이송을 지체 없이 신청하여야 한다.', 966);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7356, '제202조(처우상 유의사항) 소장은 조직폭력수용자가 다른 사람과 접견할 때에는 외부 폭력조직과의 연계가능성이 높은 점 등을 고려하여 접촉차단시설이 있는 장소에서 하게 하여야 하며, 귀휴나 그 밖의 특별한 이익이 되는 처우를 결정하는 경우에는 해당 처우의 허용 요건에 관한 규정을 엄격히 적용하여야 한다.', 966);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7357, '제203조(특이사항의 통보) 소장은 조직폭력수용자의 편지 및 접견의 내용 중 특이사항이 있는 경우에는 검찰청, 경찰서 등 관계기관에 통보할 수 있다. <개정 2020.8.5>', 966);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7358, '제204조(지정대상) 마약류수용자의 지정대상은 다음 각 호와 같다. <개정 2014.11.17>', 967);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7359, '제205조(지정 및 해제)', 967);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7360, '제206조(마약반응검사)', 967);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7361, '제207조(물품전달 제한) 소장은 수용자 외의 사람이 마약류수용자에게 물품을 건네줄 것을 신청하는 경우에는 마약류 반입 등을 차단하기 위하여 신청을 허가하지 않는다. 다만, 다음 각 호의 어느 하나에 해당하는 물품을 건네줄 것을 신청한 경우에는 예외로 할 수 있다. <개정 2020.8.5>', 967);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7362, '제208조(보관품 등 수시점검) 담당교도관은 마약류수용자의 보관품 및 지니는 물건의 변동 상황을 수시로 점검하고, 특이사항이 있는 경우에는 감독교도관에게 보고해야 한다. <개정 2020.8.5>', 967);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7363, '제209조(재활교육)', 967);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7364, '제210조(지정대상) 관심대상수용자의 지정대상은 다음 각 호와 같다. <개정 2013.4.16, 2014.11.17>', 968);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7365, '제211조(지정 및 해제)', 968);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7366, '제212조 삭제 <2010.5.31>', 968);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7367, '제213조(수용동 및 작업장 계호 배치) 소장은 다수의 관심대상수용자가 수용되어 있는 수용동 및 작업장에는 사명감이 투철한 교도관을 엄선하여 배치하여야 한다. <개정 2013.4.16>', 968);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7368, '제214조(규율) 수용자는 다음 각 호에 해당하는 행위를 해서는 안 된다. <개정 2014.11.17, 2017.8.22, 2020.8.5, 2024.2.8>', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7369, '제214조의2(포상) 법 제106조에 따른 포상기준은 다음 각 호와 같다. <개정 2017.8.22>', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7370, '제215조(징벌 부과기준) 수용자가 징벌대상행위를 한 경우 부과하는 징벌의 기준은 다음 각 호의 구분에 따른다. <개정 2010.5.31, 2014.11.17, 2020.8.5, 2024.2.8>', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7371, '제215조의2(금치 집행 중 실외운동의 제한) 법 제112조제4항제4호에서 "법무부령으로 정하는 경우"란 다음 각 호와 같다.', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7372, '제216조(징벌부과 시 고려사항) 제215조의 기준에 따라 징벌을 부과하는 경우에는 다음 각 호의 사항을 고려하여야 한다. <개정 2018.12.28>', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7373, '제217조(교사와 방조)', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7374, '제218조(징벌대상행위의 경합)', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7375, '제219조(조사 시 지켜야 할 사항) 징벌대상행위에 대하여 조사하는 교도관이 징벌대상자 또는 참고인 등을 조사할 때에는 다음 각 호의 사항을 지켜야 한다. <개정 2020.8.5>', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7376, '제219조의2(징벌대상자에 대한 심리상담) 소장은 특별한 사유가 없으면 교도관으로 하여금 징벌대상자에 대한 심리상담을 하도록 해야 한다.', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7377, '제220조(조사기간)', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7378, '제221조(조사의 일시정지)', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7379, '제222조(징벌대상자 처우제한의 알림) 소장은 법 제110조제2항에 따라 접견ㆍ편지수수 또는 전화통화를 제한하는 경우에는 징벌대상자의 가족 등에게 그 사실을 알려야 한다. 다만, 징벌대상자가 알리기를 원하지 않는 경우에는 그렇지 않다. <개정 2020.8.5>', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7380, '제223조(징벌위원회 외부위원)', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7381, '제224조(징벌위원회 위원장) 법 제111조제2항에서 "소장의 바로 다음 순위자"는 「법무부와 그 소속기관 직제 시행규칙」의 직제순위에 따른다.', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7382, '제225조(징벌위원회 심의ㆍ의결대상) 징벌위원회는 다음 각 호의 사항을 심의ㆍ의결한다.', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7383, '제226조(징벌의결의 요구)', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7384, '제227조(징벌대상자에 대한 출석 통지)', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7385, '제228조(징벌위원회의 회의)', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7386, '제229조(집행절차)', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7387, '제230조(징벌의 집행순서)', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7388, '제231조(징벌의 집행방법)', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7389, '제232조(금치 집행 중 생활용품 등의 별도 보관) 소장은 금치 중인 수용자가 생활용품 등으로 자살ㆍ자해할 우려가 있거나 교정시설의 안전과 질서를 해칠 우려가 있는 경우에는 그 물품을 따로 보관하고 필요한 경우에만 이를 사용하게 할 수 있다.', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7390, '제233조(징벌집행 중인 수용자의 심리상담 등)', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7391, '제234조(징벌의 실효)', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7392, '제235조 삭제 <2020.8.5>', 969);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7393, '제236조(심사대상) 법 제119조의 가석방심사위원회(이하 이 편에서 "위원회"라 한다)는 법 제121조에 따른 가석방 적격 여부 및 이 규칙 제262조에 따른 가석방 취소 등에 관한 사항을 심사한다.', 972);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7394, '제237조(심사의 기본원칙)', 972);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7395, '제238조(위원장의 직무)', 972);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7396, '제239조(위원의 임명 또는 위촉) 법무부장관은 다음 각 호의 사람 중에서 위원회의 위원을 임명하거나 위촉한다.', 972);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7397, '제239조의2(위원의 해촉) 법무부장관은 위원회의 위원이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 위원을 해촉할 수 있다.', 972);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7398, '제240조(위원의 임기) 제239조제2호 및 제3호의 위원의 임기는 2년으로 하며, 한 차례만 연임할 수 있다. <개정 2016.6.28>', 972);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7399, '제241조(간사와 서기)', 972);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7400, '제242조(회의)', 972);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7401, '제243조(회의록의 작성)', 972);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7402, '제244조(수당 등) 위원회의 회의에 출석한 위원에게는 예산의 범위에서 수당과 여비를 지급할 수 있다.', 972);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7403, '제245조(적격심사신청 대상자 선정)', 973);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7404, '제246조(사전조사) 소장은 수형자의 가석방 적격심사신청을 위하여 다음 각 호의 사항을 사전에 조사해야 한다. 이 경우 조사의 방법에 관하여는 제70조를 준용한다. <개정 2010.5.31, 2020.8.5, 2024.2.8>', 973);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7405, '제247조(사전조사 유의사항) 제246조에 따른 사전조사 중 가석방 적격심사신청과 관련하여 특히 피해자의 감정 및 합의여부, 출소 시 피해자에 대한 보복성 범죄 가능성 등에 유의하여야 한다. <개정 2010.5.31>', 973);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7406, '제248조(사전조사 결과)', 973);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7407, '제249조(사전조사 시기 등)', 973);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7408, '제250조(적격심사신청)', 973);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7409, '제251조(재신청) 소장은 가석방이 허가되지 아니한 수형자에 대하여 그 후에 가석방을 허가하는 것이 적당하다고 인정하는 경우에는 다시 가석방 적격심사신청을 할 수 있다. <개정 2010.5.31>', 973);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7410, '제252조(누범자에 대한 심사) 위원회가 동일하거나 유사한 죄로 2회 이상 징역형 또는 금고형의 집행을 받은 수형자에 대하여 적격심사할 때에는 뉘우치는 정도, 노동 능력 및 의욕, 근면성, 그 밖에 정상적인 업무에 취업할 수 있는 생활계획과 보호관계에 관하여 중점적으로 심사하여야 한다. <개정 2010.5.31>', 974);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7411, '제253조(범죄동기에 대한 심사)', 974);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7412, '제254조(사회의 감정에 대한 심사) 다음 각 호에 해당하는 수형자에 대하여 적격심사할 때에는 특히 그 범죄에 대한 사회의 감정에 유의하여야 한다. <개정 2010.5.31>', 974);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7413, '제255조(재산범에 대한 심사)', 974);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7414, '제255조의2(심층면접)', 974);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7415, '제256조(관계기관 조회)', 974);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7416, '제257조(감정의 촉탁)', 974);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7417, '제258조(가석방 결정) 위원회가 법 제121조제2항에 따라 가석방의 적격 여부에 대한 결정을 한 경우에는 별지 제23호서식의 결정서를 작성하여야 한다. <개정 2010.5.31>', 974);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7418, '제259조(가석방증) 소장은 수형자의 가석방이 허가된 경우에는 주거지, 관할 경찰서 또는 보호관찰소에 출석할 기한 등을 기록한 별지 제24호서식의 가석방증을 가석방자에게 발급하여야 한다.', 974);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7419, '제260조(취소사유) 가석방자는 가석방 기간 중 「가석방자관리규정」 제5조부터 제7조까지, 제10조, 제13조제1항, 제15조 및 제16조에 따른 지켜야 할 사항 및 관할 경찰서장의 명령 또는 조치를 따라야 하며 이를 위반하는 경우에는 「형법」 제75조에 따라 가석방을 취소할 수 있다. <개정 2018.12.28, 2020.8.5>', 975);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7420, '제261조(취소신청)', 975);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7421, '제262조(취소심사)', 975);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7422, '제263조(남은 형기의 집행)', 975);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7423, '제263조의2(석방예정자의 수용이력 등 통보) 영 제143조제3항에 따른 석방예정자의 수용이력 통보서의 양식은 별지 제28호의2서식에 따르고, 석방예정자의 사회복귀에 관한 의견 통보서의 양식은 별지 제28호의3서식에 따른다.', 976);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7424, '제263조의3(사망 기록) 영 제148조에 따른 사망장의 양식은 별지 제28호의4서식에 따른다.', 977);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7425, '제264조(기능) 법 제129조제1항의 교정자문위원회(이하 이 편에서 "위원회"라 한다)의 기능은 다음 각 호와 같다. <개정 2019.10.22, 2022.2.7>', 978);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7426, '제265조(구성)', 978);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7427, '제266조(임기)', 978);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7428, '제267조(위원장의 직무)', 978);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7429, '제268조(회의)', 978);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7430, '제269조(지켜야 할 사항)', 978);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7431, '제270조(위원의 해촉) 법무부장관은 외부위원이 다음 각 호의 어느 하나에 해당하는 경우에는 지방교정청장의 건의를 받아 해당 위원을 해촉할 수 있다. <개정 2019.10.22, 2020.8.5>', 978);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7432, '제271조(간사)', 978);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7433, '제272조(수당) 지방교정청장은 위원회의 회의에 참석한 위원에게는 예산의 범위에서 수당을 지급할 수 있다. <개정 2019.10.22>', 978);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7434, '제1조(목적) 이 영은 「경범죄 처벌법」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 979);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7435, '제2조(범칙행위의 범위와 범칙금의 액수) 「경범죄 처벌법」(이하 "법"이라 한다) 제6조제1항에 따른 범칙행위의 구체적인 범위와 법 제7조제2항에 따른 범칙금의 액수는 별표와 같다.', 979);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7436, '제3조(범칙금의 납부 통고 등)', 979);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7437, '제4조(범칙금의 납부 등)', 979);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7438, '제4조의2(신용카드 등을 이용한 범칙금의 납부방법)', 979);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7439, '제5조(범칙금 징수사항 기록부의 비치) 경찰서장등은 제4조제4항에 따라 수납기관으로부터 범칙금 수납 사실을 통보받은 때마다 그 징수사항을 범칙금 징수사항 기록부에 기록하거나 전자매체를 통하여 전산으로 저장ㆍ관리하여야 한다.', 979);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7440, '제6조(즉결심판 대상자에 대한 처리)', 979);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7441, '제7조(철도특별사법경찰대장의 즉결심판 대상자 적발 통보 등)', 979);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7442, '제8조(자료 요청 등)', 979);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7443, '제9조(민감정보 및 고유식별정보의 처리) 경찰서장등은 법 및 이 영에 따른 범칙금에 관한 사무 수행을 위하여 불가피한 경우 「개인정보 보호법 시행령」 제18조제2호에 따른 범죄경력자료에 해당하는 정보와 같은 영 제19조제1호ㆍ제2호 또는 제4호에 따른 주민등록번호ㆍ여권번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 979);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7444, '제1조(목적) 이 영은 「치료감호 등에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다. <개정 2016.11.29>', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7445, '제2조(마약류 등의 종류) 「치료감호 등에 관한 법률」(이하 "법"이라 한다) 제2조제1항제2호에 따른 마약ㆍ향정신성의약품ㆍ대마, 그 밖에 남용되거나 해독(害毒)을 끼칠 우려가 있는 물질의 종류는 다음과 같다. <개정 2012.6.7, 2014.12.9, 2016.11.29>', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7446, '제2조의2(남용되거나 해독을 끼칠 우려가 있는 물질) 법 제2조의3제3호에서 "마약ㆍ향정신성의약품ㆍ대마, 그 밖에 대통령령으로 정하는 남용되거나 해독을 끼칠 우려가 있는 물질"이란 제2조 각 호의 물질을 말한다.', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7447, '제3조(감호청구서의 기재사항 및 방식)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7448, '제4조(치료감호의 방법)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7449, '제4조의2(치료감호 기간 연장 신청)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7450, '제4조의3(지정법무병원의 지정절차)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7451, '제4조의4(지정법무병원의 운영 및 치료)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7452, '제4조의5(지정법무병원에 대한 경비보조)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7453, '제5조(동태의 보고 등)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7454, '제6조(치료감호 내용 등의 공개)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7455, '제6조의2(재이송의 신청 및 결정)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7456, '제7조(치료의 위탁) 법 제23조제3항에 따른 치료의 위탁을 받을 수 있는 피치료감호자의 법정대리인, 배우자, 직계친족, 형제자매(이하 "법정대리인등"이라 한다)가 위원회에 제출할 서약서에는 그 법정대리인등과 피치료감호자의 성명, 연령, 등록기준지, 주거, 직업 및 치료를 받을 병원명 등을 적고 입원보증서 등 자료를 첨부하여야 한다.', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7457, '제7조의2(피치료감호청구인의 처우)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7458, '제7조의3(격리 등 제한의 금지)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7459, '제8조(처우개선의 청원)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7460, '제9조(피보호관찰자의 준수사항)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7461, '제9조의2(피보호관찰자의 준수사항 변경 등)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7462, '제9조의3(피보호관찰자에 대한 경고) 보호관찰소의 장은 법 제33조제5항에 따라 피보호관찰자에게 경고를 하는 경우에는 문서로 하여야 한다.', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7463, '제10조(피보호관찰자 등의 신고의무)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7464, '제11조(보호관찰관의 임무)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7465, '제11조의2(유치허가신청의 방식 등)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7466, '제11조의3(유치허가신청의 관할) 제11조의2제1항에 따른 유치허가신청을 할 때에는 해당 보호관찰소의 소재지 관할 지방검찰청 또는 지청의 검사에게 하여야 한다.', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7467, '제11조의4(가종료등의 취소 신청 등)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7468, '제11조의5(유치기간연장결정의 통지) 관할 지방법원 판사는 법 제33조의2제6항 단서에 따라 유치기간을 연장한 경우에는 지체 없이 보호관찰소의 장에게 그 사실을 알려야 한다.', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7469, '제12조(신고 의무의 고지) 치료감호시설의 장은 피보호관찰자가 출소할 때에는 죄를 다시 범하지 아니하도록 엄중 훈계하고, 법 제34조제2항에 따른 출소 후 신고를 관할 보호관찰관에게 할 것을 고지하여야 한다. <개정 2014.1.28>', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7470, '제13조(신고와 출소 통보)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7471, '제13조의2(보호관찰소와 정신건강복지센터의 공조 범위)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7472, '제14조(위원회의 구성)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7473, '제15조(위원회의 직원)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7474, '제16조(심사자료 송부 요청) 위원회는 법 제37조제3항에 규정된 사항(이하 "치료감호사안"이라 한다)을 심사할 때 검사, 치료감호시설의 장 또는 보호관찰관에게 치료감호사안 조사기록, 형 및 치료감호 집행기록 또는 보호관찰부 등 심사 자료의 송부를 요청할 수 있다. <개정 2014.1.28>', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7475, '제17조(검사의 심사신청)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7476, '제18조(피치료감호자 등의 심사신청)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7477, '제19조(위원회의 결정) 위원회는 다음 각 호의 어느 하나에 해당하는 경우에는 지체 없이 이를 심사ㆍ결정하고, 위원장과 출석위원이 기명ㆍ날인한 결정서를 작성해야 한다. <개정 2021.4.6>', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7478, '제20조(결정서의 기재 요건) 결정서에는 피치료감호자의 성명ㆍ연령ㆍ등록기준지ㆍ주거 및 감호소의 명칭과 결정 주문(主文) 및 이유를 적어야 한다. 법 제43조에 따른 검사의 심사신청에 대하여는 결정서에 검사의 관직 및 성명을 함께 적는다.', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7479, '제21조(결정의 송달 등)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7480, '제22조(회의록)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7481, '제23조(수당 등)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7482, '제24조(위원회의 운영세칙) 이 영에 규정된 사항 외에 위원회의 운영에 필요한 사항은 위원회의 의결을 거쳐 위원장이 정한다.', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7483, '제25조(판결 전 조사) 법원은 법 제44조의3제1항에 따라 피고인의 주거지 또는 그 법원의 소재지를 관할하는 보호관찰소의 장에게 조사를 요구하는 경우에는 피고인의 인적사항 및 범죄사실의 요지를 통보하여야 한다. 이 경우 필요하다고 인정하면 참고자료를 송부할 수 있다.', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7484, '제25조의2', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7485, '제26조(집행지휘의 방식) 검사는 법 제44조의6제1항에 따라 치료명령의 집행을 지휘하는 경우에는 법 제44조의2제1항에 따른 치료를 명하는 판결이 확정된 후 지체 없이 치료명령을 선고받은 사람(이하 "피치료명령자"라 한다)의 주거지를 관할하는 보호관찰소의 장에게 판결문 등본을 첨부한 지휘 서면을 송부하여야 한다.', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7486, '제27조(치료명령 집행 전의 준비 등)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7487, '제28조(치료명령 집행계획의 수립) 보호관찰관은 법 제44조의6제1항에 따라 피치료명령자에 대한 치료명령을 집행하기 전에 다음 각 호의 사항을 종합적으로 고려한 치료명령 집행계획을 수립하여야 한다.', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7488, '제29조(인지행동 치료 등 심리치료 프로그램 등)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7489, '제30조(치료명령의 집행 확인 등)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7490, '제31조(치료명령 집행 협의체) 보호관찰소의 장은 치료명령의 집행에 관한 다음 각 호의 사항을 협의하기 위하여 필요하다고 인정하는 경우에는 보호관찰관, 정신건강의학과 전문의 및 「정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률」에 따른 정신건강전문요원 등 전문가로 구성된 치료명령 집행 협의체를 운영할 수 있다. <개정 2017.5.29>', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7491, '제32조(치료비용의 국가부담)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7492, '제33조(군치료감호심의위원회) 법 제50조제2항에 따른 군치료감호심의위원회에 관하여는 제14조부터 제24조까지를 준용한다. 이 경우 "법무부장관"은 "국방부장관"으로, "법무부"는 "국방부"로 본다.', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7493, '제34조(기부금품의 접수 등)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7494, '제35조(민감정보 및 고유식별정보의 처리)', 980);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7495, '제1조(목적) 이 법은 보호소년 등의 처우 및 교정교육과 소년원과 소년분류심사원의 조직, 기능 및 운영에 관하여 필요한 사항을 규정함을 목적으로 한다.', 981);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7496, '제1조의2(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다.', 981);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7497, '제2조(처우의 기본원칙)', 981);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7498, '제3조(임무)', 981);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7499, '제4조(관장 및 조직)', 981);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7500, '제5조(소년원의 분류 등)', 981);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7501, '제6조(소년원 등의 규모 등)', 981);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7502, '제7조(수용절차)', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7503, '제8조(분류처우)', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7504, '제8조의2 삭제 <2016.3.29>', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7505, '제9조(보호처분의 변경 등)', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7506, '제10조(원장의 면접) 원장은 보호소년등으로부터 처우나 일신상의 사정에 관한 의견을 듣기 위하여 수시로 보호소년등과 면접을 하여야 한다.', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7507, '제11조(청원) 보호소년등은 그 처우에 대하여 불복할 때에는 법무부장관에게 문서로 청원할 수 있다.', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7508, '제12조(이송)', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7509, '제13조(비상사태 등의 대비)', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7510, '제14조(사고 방지 등)', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7511, '제14조의2(보호장비의 사용)', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7512, '제14조의3(전자장비의 설치ㆍ운영)', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7513, '제14조의4(규율 위반 행위) 보호소년등은 다음 각 호의 행위를 하여서는 아니 된다.', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7514, '제15조(징계)', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7515, '제15조의2(보호소년등처우ㆍ징계위원회)', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7516, '제16조(포상)', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7517, '제17조(급여품 등)', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7518, '제18조(면회ㆍ편지ㆍ전화통화)', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7519, '제19조(외출) 소년원장은 보호소년에게 다음 각 호의 어느 하나에 해당하는 사유가 있을 때에는 본인이나 보호자등의 신청에 따라 또는 직권으로 외출을 허가할 수 있다. <개정 2013.7.30>', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7520, '제20조(환자의 치료)', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7521, '제20조의2(진료기록부 등의 관리)', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7522, '제20조의3(출원생의 외래진료)', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7523, '제21조(감염병의 예방과 응급조치)', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7524, '제22조(금품의 보관 및 반환)', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7525, '제23조(친권 또는 후견) 원장은 미성년자인 보호소년등이 친권자나 후견인이 없거나 있어도 그 권리를 행사할 수 없을 때에는 법원의 허가를 받아 그 보호소년등을 위하여 친권자나 후견인의 직무를 행사할 수 있다.', 982);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7526, '제24조(분류심사)', 983);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7527, '제25조(분류심사관)', 983);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7528, '제26조(청소년심리검사 등) 소년분류심사원장은 「청소년기본법」 제3조제1호에 따른 청소년이나 그 보호자가 적성검사 등 진로탐색을 위한 청소년심리검사 또는 상담을 의뢰하면 이를 할 수 있다. 이 경우에는 법무부장관이 정하는 바에 따라 실비를 받을 수 있다.', 983);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7529, '제27조(분류심사 결과 등의 통지)', 983);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7530, '제28조(교정교육의 원칙) 소년원의 교정교육은 규율있는 생활 속에서 초ㆍ중등교육, 직업능력개발훈련, 인성교육, 심신의 보호ㆍ지도 등을 통하여 보호소년이 전인적인 성장ㆍ발달을 이루고 사회생활에 원만하게 적응할 수 있도록 하여야 한다.', 984);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7531, '제29조(학교의 설치ㆍ운영) 법무부장관은 대통령령으로 정하는 바에 따라 소년원에 「초ㆍ중등교육법」 제2조제1호부터 제4호까지의 학교(이하 "소년원학교"라 한다)를 설치ㆍ운영할 수 있다. <개정 2016.3.29>', 984);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7532, '제29조의2(「초ㆍ중등교육법」에 관한 특례)', 984);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7533, '제29조의3(「학교폭력예방 및 대책에 관한 법률」에 관한 특례) 소년원학교에 대해서는 「학교폭력예방 및 대책에 관한 법률」 제12조부터 제16조까지, 제16조의2, 제17조, 제17조의2 및 제18조부터 제20조까지의 규정을 적용하지 아니한다.', 984);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7534, '제30조(교원 등)', 984);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7535, '제31조(학적관리)', 984);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7536, '제32조(다른 학교로의 전학ㆍ편입학) 보호소년이 소년원학교에서 교육과정을 밟는 중에 소년원에서 퇴원하거나 임시퇴원하여 전적학교 등 다른 학교에 전학이나 편입학을 신청하는 경우 전적학교 등 다른 학교의 장은 정당한 사유를 제시하지 아니하는 한 이를 허가하여야 한다.', 984);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7537, '제33조(통학) 소년원장은 교정성적이 양호한 보호소년의 원활한 학업 연계를 위하여 필요하다고 판단되면 보호소년을 전적학교 등 다른 학교로 통학하게 할 수 있다.', 984);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7538, '제34조(전적학교의 졸업장 수여)', 984);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7539, '제35조(직업능력개발훈련)', 984);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7540, '제36조(직업능력개발훈련교사) 직업능력개발훈련을 실시하는 소년원에는 「국민 평생 직업능력 개발법」으로 정한 자격을 갖춘 직업능력개발훈련교사를 둔다. <개정 2021.8.17>', 984);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7541, '제37조(통근취업)', 984);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7542, '제38조(안전관리)', 984);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7543, '제39조(생활지도) 원장은 보호소년등의 자율성을 높이고 각자가 당면한 문제를 스스로 해결하여 사회생활에 적응할 수 있는 능력을 기르도록 생활지도를 하여야 한다.', 984);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7544, '제40조(특별활동) 소년원장은 보호소년의 취미와 특기를 신장하고 집단생활의 경험을 통하여 민주적이고 협동적인 생활태도를 기르도록 특별활동지도를 하여야 한다.', 984);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7545, '제41조(교육계획 등)', 984);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7546, '제42조(장학지도) 법무부장관은 교정교육 성과를 평가하고 개선하기 위하여 소속 공무원으로 하여금 장학지도를 하게 할 수 있다.', 984);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7547, '제42조의2(대안교육 및 비행예방 등)', 984);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7548, '제42조의3(보호자교육)', 984);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7549, '제43조(퇴원)', 985);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7550, '제44조(임시퇴원) 소년원장은 교정성적이 양호한 자 중 보호관찰의 필요성이 있다고 인정되는 보호소년(「소년법」 제32조제1항제8호에 따라 송치된 보호소년은 제외한다)에 대하여는 「보호관찰 등에 관한 법률」 제22조제1항에 따라 보호관찰심사위원회에 임시퇴원을 신청하여야 한다. <개정 2016.3.29>', 985);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7551, '제44조의2(보호소년의 출원) 소년원장은 제43조제3항 및 제44조의 신청에 대하여 「보호관찰 등에 관한 법률」 제25조에 따른 법무부장관의 퇴원ㆍ임시퇴원 허가를 통보받으면 해당 허가서에 기재되어 있는 출원예정일에 해당 보호소년을 출원시켜야 한다. 다만, 제46조에 따라 계속 수용하는 경우(제45조제3항의 경우를 포함한다)에는 그러하지 아니하다.', 985);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7552, '제45조(보호소년의 인도)', 985);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7553, '제45조의2(사회정착지원)', 985);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7554, '제46조(퇴원자 또는 임시퇴원자의 계속 수용)', 985);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7555, '제47조(물품 또는 귀가여비의 지급) 소년원장은 보호소년이 퇴원허가 또는 임시퇴원허가를 받거나 「소년법」 제37조제1항에 따라 처분변경 결정을 받았을 때에는 필요한 경우 물품 또는 귀가여비를 지급할 수 있다.', 985);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7556, '제48조(임시퇴원 취소자의 재수용)', 985);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7557, '제49조(방문 허가 등)', 986);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7558, '제50조(협조 요청)', 986);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7559, '제50조의2(청소년심리상담실)', 986);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7560, '제51조(소년보호협회)', 986);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7561, '제51조의2(소년보호위원)', 986);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7562, '제52조(소년분류심사원이 설치되지 아니한 지역에서의 소년분류심사원의 임무수행) 소년분류심사원이 설치되지 아니한 지역에서는 소년분류심사원이 설치될 때까지 소년분류심사원의 임무는 소년원이 수행하고, 위탁소년 및 유치소년은 소년원의 구획된 장소에 수용한다. <개정 2013.7.30>', 986);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7563, '제53조(기부금품의 접수)', 986);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7564, '제54조(범죄경력자료 등의 조회 요청)', 986);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7565, '제1조(목적) 이 영은 「보호소년 등의 처우에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 987);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7566, '제2조(보호소년의 처우) 소년원장은 「보호소년 등의 처우에 관한 법률」(이하 "법"이라 한다) 제2조제2항에 따라 교육활동에 지장을 주지 않는 범위에서 보호소년에게 다음 각 호에 해당하는 향상된 처우를 할 수 있다. <개정 2021.4.20>', 987);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7567, '제3조(소년원의 기능별 분류ㆍ운영)', 987);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7568, '제4조 삭제 <2008.6.20>', 987);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7569, '제5조', 987);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7570, '제5조의2(생활실 수용정원) 법 제6조제2항에 따라 소년원 또는 소년분류심사원(이하 "소년원등"이라 한다)에 두는 생활실의 수용정원은 4명 이하로 한다. 다만, 소년원등의 기능ㆍ위치나 그 밖의 사정을 고려하여 수용인원을 증대할 수 있다. <개정 2021.4.20>', 987);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7571, '제6조(보호소년등의 인수)', 989);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7572, '제7조 삭제 <2008.6.20>', 989);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7573, '제8조(수용사실 통지) 원장은 법 제7조제3항에 따라 보호소년등의 보호자 또는 보호소년등이 지정하는 사람(이하 "보호자등"이라 한다)에게 보호소년등을 수용한 사실을 알릴 때에는 수용 경위, 처우의 개요, 면회ㆍ통신 방법, 그 밖에 필요한 사항을 함께 알려야 한다.', 989);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7574, '제9조(분류처우)', 989);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7575, '제10조(개별처우계획의 수립)', 989);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7576, '제11조(개별처우계획의 수정) 소년원장은 제10조제1항에 따라 수립한 보호소년의 개별처우계획을 변경할 필요가 있는 경우에는 지체 없이 처우ㆍ징계위원회의 심사를 거쳐 수정해야 한다. <개정 2021.4.20>', 989);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7577, '제12조(보호처분 취소대상자 통지) 원장은 보호소년등이 법원소년부의 보호처분 결정 당시 10세 미만(「소년법」 제32조제1항제10호 처분의 경우에는 12세 미만으로 한다)이었거나 19세 이상이었던 것으로 밝혀지면 지체 없이 해당 보호처분 결정을 한 법원소년부에 그 사실을 통지하여야 한다.', 989);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7578, '제13조(청원의 편의 제공)', 990);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7579, '제14조(수용인원의 조절을 위한 이송) 법무부장관은 분류수용이나 교육훈련을 위하여 수용인원을 조절할 필요가 있다고 인정되면 소년원장에게 보호소년을 다른 소년원으로 이송(移送)할 것을 지시할 수 있다.', 990);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7580, '제15조(청원에 따른 이송) 소년원장은 보호소년 또는 그 보호자등이 다른 소년원으로 이송해 줄 것을 청원한 경우에는 법무부장관의 허가를 받아 보호소년을 그 소년원으로 이송할 수 있다.', 990);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7581, '제16조(이송의 제한)', 990);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7582, '제17조(비상사태 등의 대비) 원장은 법 제13조에 따른 비상사태 등에 대비하여 소년원등 안에 대피시설을 마련해야 한다. <개정 2021.4.20>', 991);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7583, '제17조의2(소지금지물품) 보호소년등은 다음 각 호의 물품을 소지해서는 아니 된다.', 991);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7584, '제17조의3(신체 검사 등)', 991);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7585, '제18조(외부인의 출입통제)', 991);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7586, '제19조(심신안정실에의 수용)', 991);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7587, '제20조(사고발생 보고)', 991);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7588, '제21조(사체의 검사) 원장은 보호소년등이 사망한 경우에는 지체 없이 검사의 지휘에 따라 사체의 검사 등 필요한 조치를 하여야 한다.', 991);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7589, '제22조(사망 통지 및 사체의 인도) 원장은 보호소년등이 사망하면 지체 없이 병명, 사망 원인 및 사망 일시를 보호자등에게 알리고, 검사의 지휘에 따라 사체를 인도하여야 한다.', 991);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7590, '제23조(사체의 임시매장) 원장은 보호자등의 소재를 알 수 없거나 그 밖의 부득이한 사유로 제22조에 따라 사체를 인도할 수 없을 때에는 임시매장을 하고, 임시매장한 장소에 사망자의 성명, 생년월일 및 사망연월일을 새긴 표지를 세워야 한다. <개정 2015.12.30, 2021.1.5>', 991);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7591, '제23조의2 삭제 <2016.9.5>', 992);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7592, '제24조(징계)', 992);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7593, '제24조의2(징계대상행위의 조사)', 992);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7594, '제25조 삭제 <2016.9.5>', 992);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7595, '제26조(지정된 실내의 구조) 법 제15조제1항제7호에 따른 지정된 실내는 면적ㆍ채광ㆍ통풍ㆍ온도ㆍ습도 등이 보호소년등의 건강을 보호할 수 있도록 적절하여야 한다. <개정 2016.9.5>', 992);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7596, '제27조(징계 중의 지도)', 992);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7597, '제28조(이송 중의 규율위반자에 대한 징계) 보호소년이 이송 중에 규율을 위반한 경우 그 징계는 인수한 소년원장이 한다.', 992);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7598, '제29조(징계자의 처우 제한) 원장은 법 제15조에 따라 징계처분을 받은 보호소년등에 대하여 징계기간 중 교육활동의 일부를 제한할 수 있다.', 992);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7599, '제30조(징계집행의 유예ㆍ정지ㆍ면제) 원장은 정상을 특별히 참작할 사유가 있거나 환자인 경우에는 징계 집행을 면제하거나 사유가 없어질 때까지 징계 집행을 유예하거나 정지할 수 있다.', 992);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7600, '제30조의2(처우ㆍ징계위원회의 심의ㆍ의결사항) 처우ㆍ징계위원회는 법 제15조의2제1항에 따라 다음 각 호의 사항을 심의ㆍ의결한다.', 992);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7601, '제30조의3(처우ㆍ징계위원회의 구성)', 992);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7602, '제30조의4(위원의 제척ㆍ기피ㆍ회피)', 992);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7603, '제30조의5(처우ㆍ징계위원회의 위원장)', 992);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7604, '제30조의6(처우ㆍ징계위원회의 회의)', 992);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7605, '제30조의7(위원의 해촉) 위원장은 제30조의3제2항에 따라 위촉된 위원이 다음 각 호의 어느 하나에 해당하면 그 위원을 해촉(解觸)할 수 있다.', 992);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7606, '제30조의8(간사)', 992);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7607, '제30조의9(회의록의 작성 및 보관)', 992);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7608, '제30조의10(운영세칙) 이 영에서 규정한 것 외에 처우ㆍ징계위원회의 운영에 필요한 사항은 처우ㆍ징계위원회의 의결을 거쳐 위원장이 정한다.', 992);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7609, '제31조(포상)', 992);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7610, '제32조(특별급식) 원장은 국경일이나 그 밖에 필요하다고 인정할 때에는 보호소년등에게 특별급식을 할 수 있다.', 993);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7611, '제33조(음식물 등의 반입 허가)', 993);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7612, '제34조(금전 사용금지) 보호소년등은 통학, 통근취업 등 원장이 특히 필요하다고 인정하여 허가하는 경우가 아니면 금전을 소지하거나 직접 사용할 수 없다.', 993);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7613, '제35조 삭제 <2014.1.28>', 993);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7614, '제36조(면회 시간)', 994);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7615, '제37조(면회의 참석) 법 제18조제2항에 따라 면회에 참석하는 직원은 보호소년등이 규율을 위반하거나 면회인이 보호소년등에게 나쁜 영향을 준다고 인정되는 때에는 면회를 중지시킬 수 있다.', 994);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7616, '제38조(면회허가의 제한) 원장은 보호소년등을 면회하려는 사람이 다음 각 호의 어느 하나에 해당한다고 인정되면 면회를 허가하지 않을 수 있다. <개정 2014.1.28, 2021.4.20>', 994);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7617, '제39조(편지 왕래의 제한)', 994);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7618, '제39조의2(전화통화의 제한)', 994);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7619, '제40조(외출 기간) 법 제19조에 따른 외출 기간은 7일(공휴일과 토요일을 포함한다) 이내로 한다. 다만, 특별한 사유가 있을 때에는 그 기간을 연장할 수 있다. <개정 2021.4.20>', 994);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7620, '제41조(외출 시 준수사항의 부과)', 994);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7621, '제42조(건강진단 등) 원장은 보호소년등에 대하여 법 제7조제2항에 따른 건강진단 외에 정기ㆍ수시검진을 하고 그 결과를 기록ㆍ유지하여야 한다.', 995);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7622, '제43조(외부 의료기관 의료조치)', 995);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7623, '제44조(보호자등의 간호) 원장은 보호소년등이 법 제20조제2항에 따라 외부 의료기관에서 치료를 받는 경우 그 보호자등에게 간호하게 할 수 있다.', 995);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7624, '제44조의2(간호사의 의료행위) 법 제20조제4항에서 "대통령령으로 정하는 경미한 의료행위"란 다음 각 호의 의료행위를 말한다.', 995);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7625, '제45조(감염병의 예방)', 995);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7626, '제46조(감염병 발생 보고 등) 원장은 소년원등에서 감염병이 발생하면 지체 없이 그 발생 상황을 법무부장관에게 보고하고, 「감염병의 예방 및 관리에 관한 법률」 제12조에 따라 그 소년원등이 있는 지역의 보건소장에게 즉시 신고해야 한다. <개정 2010.12.29, 2021.4.20>', 995);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7627, '제47조(금품의 보관)', 996);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7628, '제48조(보관금품의 반환 등)', 996);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7629, '제49조(물품 등의 기증)', 996);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7630, '제50조(탁송금품의 반송) 원장은 보호소년등에게 탁송(託送)된 금품을 본인이 받기를 거부하거나 처우상 본인에게 교부하는 것이 적당하지 아니하다고 인정되면 지체 없이 이를 보낸 사람에게 반송하여야 한다.', 996);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7631, '제51조(분류심사의 영역)', 997);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7632, '제52조(상담조사 등)', 997);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7633, '제53조(분류심사관의 직무 등)', 997);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7634, '제54조(청소년심리검사 등)', 997);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7635, '제55조(교육계획)', 999);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7636, '제56조(교육단계)', 999);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7637, '제57조(교정성적의 평가)', 999);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7638, '제58조(소년관리기록부)', 999);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7639, '제59조(학교의 설치ㆍ운영 등)', 1000);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7640, '제60조(교감의 겸직) 소년원학교가 설치된 소년원의 교무과장은 법 제30조제3항에 따라 그 소년원학교 교감의 직무를 겸임한다.', 1000);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7641, '제61조(교원 등의 직무수행)', 1000);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7642, '제62조(교원의 연수)', 1000);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7643, '제63조(입학 또는 편입학)', 1000);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7644, '제63조의2 삭제 <2014.1.28>', 1000);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7645, '제64조(학교생활기록부) 소년원학교장은 「초ㆍ중등교육법」 제25조에 따라 보호소년의 인성발달상황과 학업성취도 등을 종합적으로 관찰ㆍ평가한 학교생활기록부를 작성ㆍ관리하여야 한다.', 1000);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7646, '제64조의2(학적사항 통지 및 관리)', 1000);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7647, '제65조(다른 학교로의 전학ㆍ편입학) 보호소년이 법 제32조에 따른 전적학교 등 다른 학교에 전학ㆍ편입학하려는 경우에는 전학ㆍ편입학 배정원서, 그 밖의 필요한 서류를 거주지 또는 전학ㆍ편입학 예정학교의 관할교육청의 장이나 전학ㆍ편입학 예정학교의 장에게 제출하여야 한다.', 1000);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7648, '제66조(통학)', 1000);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7649, '제67조(졸업사정 등)', 1000);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7650, '제68조(졸업증명서 등의 발급) 소년원장은 보호소년이나 그 보호자의 신청을 받으면 졸업증명서, 성적증명서, 수료증명서 등을 발급하여야 한다.', 1000);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7651, '제69조(학력인정 검정고시의 응시 특례) 소년원학교에 재학 중인 보호소년 중 다음 각 호 어느 하나에 해당하는 사람은 학력인정 검정고시에 응시할 수 있다. <개정 2015.1.6, 2015.9.15>', 1000);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7652, '제70조(장학 협의) 소년원학교장은 관할 교육청의 장과 소년원학교의 학사운영에 관하여 장학(<img src="http://www.law.go.kr/flDownload.do?flSeq=97087181"  alt="img97087181" >學</img>) 협의를 할 수 있으며, 관할 교육청의 장은 필요한 권고를 할 수 있다.', 1000);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7653, '제71조(직업능력개발훈련 방침)', 1001);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7654, '제72조(공공직업훈련시설의 설치) 법무부장관은 「국민 평생 직업능력 개발법」 제27조에 따라 소년원에 공공직업훈련시설을 설치ㆍ운영할 수 있다. <개정 2022.2.17>', 1001);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7655, '제73조(지원 직업능력개발훈련) 소년원장은 법 제35조제2항에 따라 산업체의 지원을 받아 직업능력개발훈련을 실시하려면 지원산업체와 지원목적, 기간, 내용, 그 밖의 지원에 관한 사항을 포함하는 지원약정서를 작성하여야 한다.', 1001);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7656, '제74조(외부시설에서의 직업능력개발훈련) 소년원장은 법 제35조제2항에 따라 보호소년을 소년원 외의 시설에 통근시키거나 위탁하여 직업능력개발훈련을 실시할 수 있다.', 1001);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7657, '제75조(직업능력개발훈련교사의 훈련) 법무부장관은 직업능력개발훈련교사의 능력개발을 위하여 해당 교사에게 「국민 평생 직업능력 개발법」 제37조제2항에 따른 보수교육을 정기적으로 이수하도록 해야 한다. <개정 2021.4.20, 2022.2.17>', 1001);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7658, '제76조(통근취업의 원칙)', 1001);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7659, '제77조(자립기반 조성) 법무부장관은 보호소년의 직업능력 향상과 성공적 자립기반 조성을 위하여 창업보육, 지원재단 설립 및 자립생활관 운영 등 필요한 사업을 할 수 있다.', 1001);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7660, '제78조(생활지도의 목표) 원장은 법 제39조에 따라 생활지도를 할 때에는 보호소년등의 심신, 행동발달 및 품행 개선에 목표를 두고 지도하여야 한다.', 1002);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7661, '제79조(상담ㆍ인성교육)', 1002);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7662, '제80조(특별활동)', 1002);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7663, '제81조(봉사활동) 소년원장은 보호소년의 공동체의식 함양과 체험을 통한 인성교육을 위하여 다양한 봉사활동 프로그램을 운영하여야 한다.', 1002);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7664, '제82조(종교활동 등)', 1002);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7665, '제83조(도서실 등의 설치ㆍ운영)', 1002);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7666, '제84조(장학지도) 법무부장관은 법 제42조에 따른 장학지도를 할 때에는 매 학년도마다 장학지도의 대상ㆍ방법 및 결과처리 등에 관한 세부계획을 수립하고 이를 소년원학교에 미리 통보하여야 한다.', 1002);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7667, '제85조(대안교육 대상자의 출석일수 인정)', 1002);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7668, '제86조(보호자교육)', 1002);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7669, '제87조(퇴원ㆍ임시퇴원의 취소 및 심사신청의 철회) 소년원장은 소년원 퇴원 또는 임시퇴원이 허가되었거나 퇴원 또는 임시퇴원 심사신청 중인 보호소년에게 징계사유 등 특별한 사유가 발생하면 보호관찰심사위원회에 퇴원 또는 임시퇴원 허가의 취소를 신청하거나 퇴원ㆍ임시퇴원  심사신청을 철회할 수 있다.', 1003);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7670, '제87조의2(재ㆍ퇴원증명서의 발급) 원장은 다음 각 호의 어느 하나에 해당하는 자가 소년원등에 수용된 사실 또는 수용되었다가 출원한 사실 등에 관한 증명서의 발급을 신청하는 경우에는 법무부령으로 정하는 재ㆍ퇴원증명서를 발급할 수 있다. 이 경우 재ㆍ퇴원증명서의 발급 신청 및 발급은 「민원 처리에 관한 법률」 제12조의2제2항 및 제3항에 따른 전자민원창구를 통하여 처리할 수 있다. <개정 2021.4.20, 2022.7.11>', 1003);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7671, '제88조(임시퇴원 취소자의 재수용)', 1003);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7672, '제89조(외국인의 방문) 원장은 법 제49조에 따라 외국인의 방문을 허가하려면 법무부장관의 승인을 받아야 한다.', 1005);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7673, '제90조(각종 자료 조회)', 1005);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7674, '제90조의2(민감정보 및 고유식별정보의 처리)', 1005);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7675, '제91조(지부 등의 설치) 법 제51조에 따라 설치된 소년보호협회(이하 "협회"라 한다)에는 소관 사업의 원활한 추진을 위하여 그 지부 또는 지회를 둘 수 있다.', 1006);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7676, '제92조(정관)', 1006);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7677, '제93조(임원)', 1006);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7678, '제94조(임원의 직무)', 1006);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7679, '제95조(이사회)', 1006);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7680, '제96조(직원의 임면) 협회의 직원은 정관으로 정하는 바에 따라 이사장이 임면한다.', 1006);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7681, '제97조(협회의 자산) 협회는 다음 각 호의 재산을 그 자산으로 한다.', 1006);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7682, '제98조(협회의 사업)', 1006);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7683, '제99조(사업 및 회계관리)', 1006);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7684, '제100조(감독)', 1006);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7685, '제101조(준용규정) 협회에 관하여는 이 영에서 규정한 것을 제외하고는 「공익법인의 설립ㆍ운영에 관한 법률」 및 「민법」 중 재단법인에 관한 규정을 준용한다.', 1006);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7686, '제102조(기부금품의 접수 등)', 1007);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7687, '제103조(범죄경력자료 등 조회 요청의 제한 등)', 1008);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7688, '제1조(목적) 이 규칙은 「보호소년 등의 처우에 관한 법률」 및 「보호소년 등의 처우에 관한 법률 시행령」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 1009);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7689, '제2조 삭제 <2021.4.20>', 1009);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7690, '제3조 삭제 <2021.4.20>', 1009);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7691, '제4조 삭제 <2021.4.20>', 1009);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7692, '제5조 삭제 <2021.4.20>', 1009);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7693, '제6조 삭제 <2021.4.20>', 1009);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7694, '제7조 삭제 <2008.6.20>', 1009);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7695, '제8조 삭제 <2008.6.20>', 1009);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7696, '제9조(보호소년등의 인수절차)', 1011);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7697, '제9조의2 삭제 <2014.1.29>', 1011);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7698, '제10조(수용사실 통지) 영 제8조에 따른 수용사실의 통지는 별지 제2호서식에 따른다. 다만, 보호소년등의 보호자 또는 보호소년등이 지정하는 사람(이하 "보호자등"이라 한다)이 원하는 때에는 정보통신망을 이용하여 통지할 수 있다. 이 경우 그 통지 사실을 기록ㆍ유지하여야 한다.', 1011);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7699, '제11조(분류처우) 원장은 영 제9조에 따라 다음 각 호의 어느 하나에 해당하는 보호소년등은 다른 보호소년등과 생활실 및 처우과정을 달리해야 한다. 다만, 원장은 시설여건이나 교육과정 운영을 위하여 특히 필요한 경우에는 「보호소년 등의 처우에 관한 법률」(이하 "법"이라 한다)제15조의2에 따른 보호소년등처우ㆍ징계위원회(이하 "처우ㆍ징계위원회"라 한다)의 심의를 거쳐 이를 조정ㆍ운영할 수 있다. <개정 2014.1.29, 2021.4.20>', 1011);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7700, '제12조(처우ㆍ징계위원회의 개별처우계획 심사) 영 제10조 및 영 제11조에 따른 처우ㆍ징계위원회의 개별처우계획 심사는 심사 사유가 발생한 날부터 10일 이내에 실시해야 한다. <개정 2021.4.20>', 1011);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7701, '제13조 삭제 <2008.6.20>', 1011);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7702, '제14조 삭제 <2008.6.20>', 1011);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7703, '제15조 삭제 <2008.6.20>', 1011);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7704, '제16조(이탈한 사람에 대한 조치)', 1011);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7705, '제17조(청원의 처리절차)', 1012);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7706, '제18조(여론조사) 원장은 보호소년등을 적절하게 처우하기 위하여 보호소년등을 대상으로 월 1회 이상 처우에 관한 의견을 조사하고 그 처리결과를 보호소년등에게 알려야 한다.', 1012);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7707, '제19조(이송)', 1012);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7708, '제20조 삭제 <2008.6.20>', 1012);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7709, '제21조(의료재활처우소년의 이송)', 1012);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7710, '제22조(의료재활소년원 이송절차 등)', 1012);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7711, '제23조(수용사고 방지계획 등의 수립) 원장은 보호소년등의 이탈ㆍ난동ㆍ폭행ㆍ자해 그 밖의 수용사고의 방지를 위한 종합대책 및 세부적인 생활지도계획을 수립ㆍ시행하여야 한다.', 1013);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7712, '제24조(보호소년등의 감호)', 1013);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7713, '제24조의2(보호장비의 사용방법)', 1013);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7714, '제24조의3(보호장비의 관리)', 1013);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7715, '제24조의4(전자장비의 종류) 법 제14조의3에 따라 소년원 또는 소년분류심사원(이하 "소년원등"이라 한다)에 설치하여 운영할 수 있는 전자장비는 다음 각 호와 같다. <개정 2021.4.20, 2022.2.7>', 1013);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7716, '제24조의5(통제실의 운영)', 1013);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7717, '제24조의6(영상정보처리기기의 설치 및 운영)', 1013);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7718, '제24조의7(전자감지기의 설치) 전자감지기는 소년원등의 외곽 담장, 그 밖에 보호소년등의 이탈이나 외부로부터의 침입을 방지하기 위하여 필요한 장소로서 법무부장관이 정하는 장소에 설치한다. <개정 2021.4.20>', 1013);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7719, '제24조의8(전자이름표의 사용) 원장은 수용 중인 보호소년등의 안전사고 방지, 출석관리 등을 위하여 소년원등의 시설 내에서 보호소년등에게 전자이름표를 휴대하도록 할 수 있다. <개정 2021.4.20, 2022.2.7>', 1013);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7720, '제24조의9(물품검색기 설치 및 사용)', 1013);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7721, '제24조의10(증거수집장비의 사용) 소속공무원은 보호소년등이 사후에 증명이 필요하다고 인정되는 행위를 하거나 사후 증명이 필요한 상태에 있는 경우 보호소년등에 대하여 증거수집장비를 사용할 수 있다.', 1013);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7722, '제24조의11(녹음ㆍ녹화 기록물의 관리) 원장은 전자장비로 녹음ㆍ녹화된 기록물을 「공공기록물 관리에 관한 법률」에 따라 관리하여야 한다.', 1013);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7723, '제25조(소지품검사 및 시설점검)', 1013);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7724, '제26조(행동관찰) 원장은 보호소년등의 행동을 수시로 관찰하고 특이사항을 기록ㆍ유지하여 감호ㆍ분류심사 및 교정교육의 자료로 활용하여야 한다.', 1013);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7725, '제27조(사고발생보고) 원장은 영 제20조제1항에 따라 사고발생사실을 법무부장관에게 보고하는 경우에는 관련 자료와 대상자의 인적사항, 사고발생 일시ㆍ장소ㆍ내용ㆍ조치사항 등이 작성된 보고서를 첨부하여야 한다.', 1013);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7726, '제27조의2(규율 위반) 법 제14조의4제6호에서 "법무부령으로 정하는 규율을 위반하는 행위"란 다음 각 호의 행위를 말한다. <개정 2016.9.29>', 1013);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7727, '제28조(징계양정)', 1014);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7728, '제28조의2(징계대상행위 조사 시 준수사항) 영 제24조의2에 따라 징계대상행위에 대하여 조사하는 직원은 다음 각 호의 사항을 준수하여야 한다.', 1014);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7729, '제29조(포상) 원장은 별표 2의2의 보호소년등의 포상기준에 따라 교정성적이 우수한 학생에 대하여 처우ㆍ징계위원회의 심사를 거쳐 포상을 할 수 있다. 다만, 모범상 및 공로상은 직원 2명 이상의 추천을 받아야 한다. <개정 2021.4.20>', 1014);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7730, '제30조(징계ㆍ포상의 기록) 원장은 보호소년등의 징계 또는 포상에 관한 사항을 소년관리기록부 및 별지 제6호서식의 상벌대장에 기록ㆍ관리하여야 한다.', 1014);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7731, '제31조(급여품관리부의 작성) 보호소년등에게 물품을 급여 또는 대여할 때에는 별지 제7호서식의 개인별 급여품관리부에 그 내용을 기록ㆍ관리하여야 한다.', 1015);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7732, '제32조(물품반입)', 1015);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7733, '제33조(면회장소)', 1016);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7734, '제34조(면회절차)', 1016);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7735, '제35조(공휴일의 면회) 원장은 보호소년등을 면회할 목적으로 방문하는 민원인의 편의를 도모하기 위하여 제36조 각 호의 어느 하나에 해당하는 특별한 사유가 있는 경우에는 공휴일에도 별도의 면회장소 및 시간을 지정하여 면회를 허가할 수 있다. 이 경우 별지 제9호서식의 시간외 면회부에 그 내용을 기록ㆍ관리하여야 한다. <개정 2014.1.29>', 1016);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7736, '제36조(면회의 특례) 영 제36조제1항 단서에 따른 특별한 사유는 다음 각 호의 어느 하나에 해당하는 경우를 말한다.', 1016);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7737, '제36조의2(전화통화의 방법 등)', 1016);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7738, '제37조(외출의 신청)', 1016);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7739, '제38조 삭제 <2014.1.29>', 1016);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7740, '제39조(외출시 준수사항)', 1016);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7741, '제40조(보건ㆍ위생관리계획 수립 등)', 1017);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7742, '제41조(청결의 유지)', 1017);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7743, '제42조(이발과 목욕) 원장은 위생을 위해 보호소년등이 이발과 목욕을 수시로 하게 해야 한다.', 1017);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7744, '제43조(체력검사 등)', 1017);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7745, '제44조(환자발생 보고) 영 제43조에 따른 외부 의료기관 의료조치에 관한 보고는 제27조를 준용한다. <개정 2021.4.20>', 1017);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7746, '제44조의2(진료기록부등의 보존) 법무부장관은 법 제20조의2제1항에 따른 진료기록부등(이하 "진료기록부등"이라 한다)을 「의료법 시행규칙」 제15조제1항에 따른 기간 동안 보존해야 한다.', 1017);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7747, '제44조의3(진료기록부등의 송부 및 요청)', 1017);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7748, '제44조의4(출원생의 외래진료의 기간ㆍ방법)', 1017);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7749, '제44조의5(출원생의 외래진료 진료비용 지원)', 1017);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7750, '제45조(물품의 보관) 원장은 보호소년등의 물품을 보관할 때에는 세탁ㆍ소독 그 밖의 적당한 조치를 한 후 주의하여 보관하여야 한다.', 1018);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7751, '제46조(보관금품 보관증) 영 제47조 전단에 따른 보관금품 보관증은 별지 제12호서식에 따른다.', 1018);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7752, '제47조(기증품 사용관리) 원장은 영 제49조제1항에 따라 기증품을 접수하면 기증인에게 별지 제13호서식에 따른 영수증을 발급하고, 별지 제14호서식에 따른 기증품관리대장에 기록한 후 사용하여야 하며, 그 사용결과를 기증자에게 통보하여야 한다.', 1018);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7753, '제48조(분류심사의 방법 및 구분 등)', 1019);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7754, '제49조(면접조사)', 1019);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7755, '제50조(행동관찰)', 1019);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7756, '제51조(분류심사관의 임명 등)', 1019);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7757, '제52조(분류심사 결과 등의 통지) 법 제26조에 따른 청소년심리검사 등의 결과 및 법 제27조에 따른 분류심사 결과 등을 통지할 때에는 법무부장관이 별도로 정한 서식에 따른다.', 1019);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7758, '제53조(신입자교육)', 1021);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7759, '제54조(기본교육) 소년원장은 제53조에 따른 신입자교육을 마친 보호소년에 대하여는 인문ㆍ실업ㆍ특성화ㆍ인성교육 또는 직업능력개발훈련, 특별활동, 생활지도 그 밖에 필요한 기본교육을 실시하여야 한다.', 1021);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7760, '제55조(사회복귀교육)', 1021);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7761, '제56조 삭제 <2014.1.29>', 1021);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7762, '제57조(여름철 및 겨울철의 지도) 소년원장은 여름철과 겨울철에 상당기간을 방학기간으로 정하여 특별활동 및 생활지도 중심의 교정교육을 할 수 있다.', 1021);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7763, '제58조 삭제 <2008.6.20>', 1021);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7764, '제59조(소년관리기록부 등)', 1021);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7765, '제60조(학칙)', 1022);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7766, '제61조(학칙 등에 관한 통지) 소년원학교장은 학사운영에 관한 긴밀한 협력을 도모하기 위하여 관할 시ㆍ도교육감 또는 시ㆍ군ㆍ자치구 교육장에게 소년원학교에 관한 다음 각 호의 사항을 통지하여야 한다.', 1022);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7767, '제62조(업무연구 등) 원장은 교정교육 전반을 창의적으로 개선하고 업무능률을 향상시키기 위하여 직원으로 하여금 업무연구 또는 연구수업을 실시하게 하고, 연구발표회 등의 참관을 적극 권장하여야 한다.', 1022);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7768, '제63조(보충수업) 소년원학교장은 보호소년의 학력신장과 수업일수의 충족 등을 위하여 필요하다고 인정하면 평일의 경우 1일 2시간, 휴업일의 경우 1일 8시간의 범위에서 보충수업을 실시할 수 있다. <개정 2014.1.29, 2021.4.20>', 1022);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7769, '제64조(학적자료 송부 등) 소년원학교장은 보호소년이 법 제32조에 따라 다른 학교로 전학하거나 편입학을 하는 경우에는 전학 또는 편입학한 학교에 학교생활기록부 전산자료와 용지에 출력한 출력물 및 건강기록부를 송부하고, 소년원학교에는 그 사본을 소년관리기록부와 함께 보관하여야 한다.', 1022);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7770, '제65조(졸업장의 발급 등)', 1022);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7771, '제66조(졸업증명서 등 서식) 영 제68조에 따른 졸업증명서ㆍ성적증명서ㆍ수료(제적)증명서ㆍ재학증명서는 각각 별지 제20호서식부터 별지 제23호서식까지에 따른다.', 1022);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7772, '제67조(직종의 신설 또는 폐지)', 1023);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7773, '제68조(직업능력개발훈련 대상자)', 1023);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7774, '제69조(통근취업 보호소년의 관리)', 1023);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7775, '제70조(보호소년등의 일과)', 1024);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7776, '제71조(종교활동) 종교활동은 휴업일에 하는 것을 원칙으로 한다. 다만, 원장이 필요하다고 인정하면 교육과정의 이수에 지장이 없는 범위에서 휴업일이 아닌 날에도 할 수 있다. <개정 2021.4.20>', 1024);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7777, '제72조(보호소년자치회)', 1024);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7778, '제73조(대안교육)', 1024);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7779, '제74조(보호자상담 등)', 1024);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7780, '제75조(퇴원ㆍ임시퇴원 심사의 신청)', 1025);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7781, '제76조(재ㆍ퇴원증명서) 영 제87조의2에서 "법무부령으로 정하는 재ㆍ퇴원증명서"란 다음 각 호의 구분에 따른 서식을 말한다.', 1025);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7782, '제77조(특별 임시퇴원) 소년원장은 보호소년이 다음 각 호의 어느 하나에 해당하는 사유가 있는 경우에는 증빙서류를 첨부하여 특별 임시퇴원허가를 신청할 수 있다. <개정 2021.4.20>', 1025);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7783, '제78조(임시퇴원자의 보호관찰자료 제공 등)', 1025);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7784, '제79조(퇴원증 또는 임시퇴원증의 교부 등)', 1025);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7785, '제80조(보호소년의 인도)', 1025);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7786, '제81조(사회정착지원)', 1025);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7787, '제81조의2 삭제 <2021.4.20>', 1025);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7788, '제82조 삭제 <2016.9.29>', 1025);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7789, '제83조(퇴원 또는 임시퇴원자의 계속수용)', 1025);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7790, '제84조(임시퇴원취소자 인수소년원의 사후조치)', 1025);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7791, '제85조(임시퇴원취소로 재수용된 사람의 처우)', 1025);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7792, '제86조(청소년심리상담실의 운영) 법 제50조의2에 따른 청소년심리상담실에는 법 제24조제2항에 따른 전문적 지식과 기술을 갖춘 직원을 상시 배치하여야 한다.', 1026);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7793, '제87조(실비 징수)', 1026);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7794, '제88조(소년보호위원의 위촉 및 해촉)', 1026);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7795, '제89조(소년보호위원의 자격기준 등) 소년보호위원의 세부적인 자격기준, 활동 등에 관한 사항은 법무부장관이 정한다.', 1026);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7796, '제90조(소년보호협회의 수익사업 등)', 1026);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7797, '제91조(기부금품의 접수 영수증 등)', 1026);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7798, '제1조(목적) 이 법은 반사회성(反社會性)이 있는 소년의 환경 조정과 품행 교정(矯正)을 위한 보호처분 등의 필요한 조치를 하고, 형사처분에 관한 특별조치를 함으로써 소년이 건전하게 성장하도록 돕는 것을 목적으로 한다.', 1027);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7799, '제2조(소년 및 보호자) 이 법에서 "소년"이란 19세 미만인 자를 말하며, "보호자"란 법률상 감호교육(監護敎育)을 할 의무가 있는 자 또는 현재 감호하는 자를 말한다.', 1027);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7800, '제3조(관할 및 직능)', 1029);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7801, '제4조(보호의 대상과 송치 및 통고)', 1029);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7802, '제5조(송치서) 소년 보호사건을 송치하는 경우에는 송치서에 사건 본인의 주거ㆍ성명ㆍ생년월일 및 행위의 개요와 가정 상황을 적고, 그 밖의 참고자료를 첨부하여야 한다.', 1029);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7803, '제6조(이송)', 1029);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7804, '제7조(형사처분 등을 위한 관할 검찰청으로의 송치)', 1029);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7805, '제8조(통지) 소년부는 제6조와 제7조에 따른 결정을 하였을 때에는 지체 없이 그 사유를 사건 본인과 그 보호자에게 알려야 한다.', 1029);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7806, '제9조(조사 방침) 조사는 의학ㆍ심리학ㆍ교육학ㆍ사회학이나 그 밖의 전문적인 지식을 활용하여 소년과 보호자 또는 참고인의 품행, 경력, 가정 상황, 그 밖의 환경 등을 밝히도록 노력하여야 한다.', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7807, '제10조(진술거부권의 고지) 소년부 또는 조사관이 범죄 사실에 관하여 소년을 조사할 때에는 미리 소년에게 불리한 진술을 거부할 수 있음을 알려야 한다.', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7808, '제11조(조사명령)', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7809, '제12조(전문가의 진단) 소년부는 조사 또는 심리를 할 때에 정신건강의학과의사ㆍ심리학자ㆍ사회사업가ㆍ교육자나 그 밖의 전문가의 진단, 소년 분류심사원의 분류심사 결과와 의견, 보호관찰소의 조사결과와 의견 등을 고려하여야 한다. <개정 2011.8.4>', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7810, '제13조(소환 및 동행영장)', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7811, '제14조(긴급동행영장) 소년부 판사는 사건 본인을 보호하기 위하여 긴급조치가 필요하다고 인정하면 제13조제1항에 따른 소환 없이 동행영장을 발부할 수 있다.', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7812, '제15조(동행영장의 방식) 동행영장에는 다음 각 호의 사항을 적고 소년부 판사가 서명날인하여야 한다.', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7813, '제16조(동행영장의 집행)', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7814, '제17조(보조인 선임)', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7815, '제17조의2(국선보조인)', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7816, '제18조(임시조치)', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7817, '제19조(심리 불개시의 결정)', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7818, '제20조(심리 개시의 결정)', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7819, '제21조(심리 기일의 지정)', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7820, '제22조(기일 변경) 소년부 판사는 직권에 의하거나 사건 본인, 보호자 또는 보조인의 청구에 의하여 심리 기일을 변경할 수 있다. 기일을 변경한 경우에는 이를 사건 본인, 보호자 또는 보조인에게 알려야 한다.', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7821, '제23조(심리의 개시)', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7822, '제24조(심리의 방식)', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7823, '제25조(의견의 진술)', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7824, '제25조의2(피해자 등의 진술권) 소년부 판사는 피해자 또는 그 법정대리인ㆍ변호인ㆍ배우자ㆍ직계친족ㆍ형제자매(이하 이 조에서 "대리인등"이라 한다)가 의견진술을 신청할 때에는 피해자나 그 대리인등에게 심리 기일에 의견을 진술할 기회를 주어야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그러하지 아니하다.', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7825, '제25조의3(화해권고)', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7826, '제26조(증인신문, 감정, 통역ㆍ번역)', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7827, '제27조(검증, 압수, 수색)', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7828, '제28조(원조, 협력)', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7829, '제29조(불처분 결정)', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7830, '제30조(기록의 작성)', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7831, '제30조의2(기록의 열람ㆍ등사) 소년 보호사건의 기록과 증거물은 소년부 판사의 허가를 받은 경우에만 열람하거나 등사할 수 있다. 다만, 보조인이 심리 개시 결정 후에 소년 보호사건의 기록과 증거물을 열람하는 경우에는 소년부 판사의 허가를 받지 아니하여도 된다.', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7832, '제31조(위임규정) 소년 보호사건의 심리에 필요한 사항은 대법원규칙으로 정한다.', 1030);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7833, '제32조(보호처분의 결정)', 1031);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7834, '제32조의2(보호관찰처분에 따른 부가처분 등)', 1031);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7835, '제33조(보호처분의 기간)', 1031);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7836, '제34조(몰수의 대상)', 1031);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7837, '제35조(결정의 집행) 소년부 판사는 제32조제1항 또는 제32조의2에 따른 처분 결정을 하였을 때에는 조사관, 소년부 법원서기관ㆍ법원사무관ㆍ법원주사ㆍ법원주사보, 보호관찰관, 소년원 또는 소년분류심사원 소속 공무원, 그 밖에 위탁 또는 송치받을 기관 소속의 직원에게 그 결정을 집행하게 할 수 있다.', 1031);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7838, '제36조(보고와 의견 제출)', 1031);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7839, '제37조(처분의 변경)', 1031);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7840, '제38조(보호처분의 취소)', 1031);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7841, '제39조(보호처분과 유죄판결) 보호처분이 계속 중일 때에 사건 본인에 대하여 유죄판결이 확정된 경우에 보호처분을 한 소년부 판사는 그 처분을 존속할 필요가 없다고 인정하면 결정으로써 보호처분을 취소할 수 있다.', 1031);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7842, '제40조(보호처분의 경합) 보호처분이 계속 중일 때에 사건 본인에 대하여 새로운 보호처분이 있었을 때에는 그 처분을 한 소년부 판사는 이전의 보호처분을 한 소년부에 조회하여 어느 하나의 보호처분을 취소하여야 한다.', 1031);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7843, '제41조(비용의 보조) 제18조제1항제1호ㆍ제2호의 조치에 관한 결정이나 제32조제1항제1호ㆍ제6호ㆍ제7호(「보호소년 등의 처우에 관한 법률」에 따른 의료재활소년원 위탁처분은 제외한다)의 처분을 받은 소년의 보호자는 위탁받은 자에게 그 감호에 관한 비용의 전부 또는 일부를 지급하여야 한다. 다만, 보호자가 지급할 능력이 없을 때에는 소년부가 지급할 수 있다. <개정 2020.10.20>', 1031);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7844, '제42조(증인 등의 비용)', 1031);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7845, '제43조(항고)', 1032);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7846, '제44조(항고장의 제출)', 1032);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7847, '제45조(항고의 재판)', 1032);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7848, '제46조(집행 정지) 항고는 결정의 집행을 정지시키는 효력이 없다.', 1032);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7849, '제47조(재항고)', 1032);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7850, '제48조(준거법례) 소년에 대한 형사사건에 관하여는 이 법에 특별한 규정이 없으면 일반 형사사건의 예에 따른다.', 1034);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7851, '제49조(검사의 송치)', 1034);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7852, '제49조의2(검사의 결정 전 조사)', 1034);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7853, '제49조의3(조건부 기소유예) 검사는 피의자에 대하여 다음 각 호에 해당하는 선도(善導) 등을 받게 하고, 피의사건에 대한 공소를 제기하지 아니할 수 있다. 이 경우 소년과 소년의 친권자ㆍ후견인 등 법정대리인의 동의를 받아야 한다.', 1034);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7854, '제50조(법원의 송치) 법원은 소년에 대한 피고사건을 심리한 결과 보호처분에 해당할 사유가 있다고 인정하면 결정으로써 사건을 관할 소년부에 송치하여야 한다.', 1034);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7855, '제51조(이송) 소년부는 제50조에 따라 송치받은 사건을 조사 또는 심리한 결과 사건의 본인이 19세 이상인 것으로 밝혀지면 결정으로써 송치한 법원에 사건을 다시 이송하여야 한다.', 1034);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7856, '제52조(소년부 송치 시의 신병 처리)', 1034);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7857, '제53조(보호처분의 효력) 제32조의 보호처분을 받은 소년에 대하여는 그 심리가 결정된 사건은 다시 공소를 제기하거나 소년부에 송치할 수 없다. 다만, 제38조제1항제1호의 경우에는 공소를 제기할 수 있다.', 1034);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7858, '제54조(공소시효의 정지) 제20조에 따른 심리 개시 결정이 있었던 때로부터 그 사건에 대한 보호처분의 결정이 확정될 때까지 공소시효는 그 진행이 정지된다.', 1034);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7859, '제55조(구속영장의 제한)', 1034);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7860, '제56조(조사의 위촉) 법원은 소년에 대한 형사사건에 관하여 필요한 사항을 조사하도록 조사관에게 위촉할 수 있다.', 1035);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7861, '제57조(심리의 분리) 소년에 대한 형사사건의 심리는 다른 피의사건과 관련된 경우에도 심리에 지장이 없으면 그 절차를 분리하여야 한다.', 1035);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7862, '제58조(심리의 방침)', 1035);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7863, '제59조(사형 및 무기형의 완화) 죄를 범할 당시 18세 미만인 소년에 대하여 사형 또는 무기형(無期刑)으로 처할 경우에는 15년의 유기징역으로 한다.', 1035);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7864, '제60조(부정기형)', 1035);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7865, '제61조(미결구금일수의 산입) 제18조제1항제3호의 조치가 있었을 때에는 그 위탁기간은 「형법」 제57조제1항의 판결선고 전 구금일수(拘禁日數)로 본다.', 1035);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7866, '제62조(환형처분의 금지) 18세 미만인 소년에게는 「형법」 제70조에 따른 유치선고를 하지 못한다. 다만, 판결선고 전 구속되었거나 제18조제1항제3호의 조치가 있었을 때에는 그 구속 또는 위탁의 기간에 해당하는 기간은 노역장(勞役場)에 유치된 것으로 보아 「형법」 제57조를 적용할 수 있다.', 1035);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7867, '제63조(징역ㆍ금고의 집행) 징역 또는 금고를 선고받은 소년에 대하여는 특별히 설치된 교도소 또는 일반 교도소 안에 특별히 분리된 장소에서 그 형을 집행한다. 다만, 소년이 형의 집행 중에 23세가 되면 일반 교도소에서 집행할 수 있다.', 1035);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7868, '제64조(보호처분과 형의 집행) 보호처분이 계속 중일 때에 징역, 금고 또는 구류를 선고받은 소년에 대하여는 먼저 그 형을 집행한다.', 1035);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7869, '제65조(가석방) 징역 또는 금고를 선고받은 소년에 대하여는 다음 각 호의 기간이 지나면 가석방(假釋放)을 허가할 수 있다.', 1035);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7870, '제66조(가석방 기간의 종료) 징역 또는 금고를 선고받은 소년이 가석방된 후 그 처분이 취소되지 아니하고 가석방 전에 집행을 받은 기간과 같은 기간이 지난 경우에는 형의 집행을 종료한 것으로 한다. 다만, 제59조의 형기(刑期) 또는 제60조제1항에 따른 장기의 기간이 먼저 지난 경우에는 그 때에 형의 집행을 종료한 것으로 한다.', 1035);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7871, '제67조(자격에 관한 법령의 적용)', 1035);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7872, '제67조의2(비행 예방정책) 법무부장관은 제4조제1항에 해당하는 자(이하 "비행소년"이라 한다)가 건전하게 성장하도록 돕기 위하여 다음 각 호의 사항에 대한 필요한 조치를 취하여야 한다.', 1036);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7873, '제68조(보도 금지)', 1037);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7874, '제69조(나이의 거짓 진술) 성인(成人)이 고의로 나이를 거짓으로 진술하여 보호처분이나 소년 형사처분을 받은 경우에는 1년 이하의 징역에 처한다.', 1037);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7875, '제70조(조회 응답)', 1037);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7876, '제71조(소환의 불응 및 보호자 특별교육명령 불응) 다음 각 호의 어느 하나에 해당하는 자에게는 300만원 이하의 과태료를 부과한다. <개정 2014.12.30>', 1037);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7877, '제1조(목적) 이 법은 「청소년 기본법」 제49조제4항에 따라 학교 밖 청소년 지원에 관한 사항을 규정함으로써 학교 밖 청소년이 건강한 사회구성원으로 성장할 수 있도록 함을 목적으로 한다.', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7878, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다.', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7879, '제3조(국가와 지방자치단체의 책무)', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7880, '제4조(다른 법률과의 관계) 학교 밖 청소년 지원에 관하여 다른 법률에 특별한 규정이 있는 경우를 제외하고는 이 법에 따른다.', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7881, '제5조(학교 밖 청소년 지원계획)', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7882, '제6조(실태조사)', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7883, '제7조(학교 밖 청소년 지원 위원회)', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7884, '제8조(상담지원)', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7885, '제9조(교육지원)', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7886, '제10조(직업체험 및 취업지원)', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7887, '제11조(자립지원)', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7888, '제11조의2(건강진단)', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7889, '제12조(학교 밖 청소년 지원센터)', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7890, '제12조의2(지원센터의 평가)', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7891, '제13조(지원센터의 지정 취소 등)', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7892, '제14조(지역사회 청소년통합지원체계와의 연계) 지원센터는 학교 밖 청소년 지원업무를 수행함에 있어 「청소년복지 지원법」 제9조의 지역사회 청소년통합지원체계를 구성하는 기관과 연계 및 협력하여야 한다.', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7893, '제15조(지원센터에의 연계)', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7894, '제16조(비밀유지 의무) 학교 밖 청소년 지원 관련 업무에 종사하거나 종사하였던 자는 그 직무상 알게 된 비밀을 다른 사람에게 누설하거나 직무상 목적 외의 용도로 이용하여서는 아니 된다.', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7895, '제17조(관계 기관의 협조) 여성가족부장관은 이 법의 목적을 달성하기 위하여 필요하다고 인정하는 경우에는 대통령령으로 정하는 사항에 대하여 관계 중앙행정기관의 장 또는 지방자치단체의 장에게 필요한 시책을 마련하거나 조치할 것을 요청할 수 있다. 이 경우 관계 중앙행정기관의 장 또는 지방자치단체의 장은 특별한 사유가 없으면 협조하여야 한다.', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7896, '제18조(권한의 위임과 위탁)', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7897, '제19조(유사 명칭의 사용 금지) 이 법에 따른 지원센터가 아니면 학교 밖 청소년 지원센터 또는 이와 유사한 명칭을 사용하지 못한다.', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7898, '제20조(벌칙) 제16조를 위반하여 직무상 알게 된 비밀을 누설하거나 직무상 목적 외에 이용한 사람은 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7899, '제21조(과태료)', 1038);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7900, '제1조(목적) 이 영은 「학교 밖 청소년 지원에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 1039);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7901, '제2조(학교 밖 청소년 지원계획의 수립) 여성가족부장관은 「학교 밖 청소년 지원에 관한 법률」(이하 "법"이라 한다) 제5조제1항 각 호의 사항에 대한 계획을 수립하기 위한 지침을 「청소년 기본법 시행령」 제16조제1항에 따른 연도별 시행계획 수립지침에 포함하여 관계 중앙행정기관의 장과 지방자치단체의 장에게 통보하여야 한다.', 1039);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7902, '제3조(학교 밖 청소년 지원 위원회의 구성)', 1039);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7903, '제4조(지원위원회의 운영)', 1039);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7904, '제5조(자립지원) 국가와 지방자치단체는 법 제11조제1항에 따른 학교 밖 청소년에 대한 자립지원을 위하여 학교 밖 청소년의 자립 역량 강화를 위한 지원 프로그램 등을 운영할 수 있다.', 1039);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7905, '제6조(지원센터의 설치기준 등)', 1039);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7906, '제7조(지원센터의 지정 취소 등)', 1039);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7907, '제8조(관계 기관의 협조사항) 법 제17조 전단에서 "대통령령으로 정하는 사항" 이란 다음 각 호의 사항을 말한다.', 1039);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7908, '제9조(권한의 위임) 여성가족부장관은 법 제18조제1항에 따라 법 제12조 및 제13조에 따른 지원센터의 지정 및 지정 취소 등에 관한 권한을 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ도지사ㆍ특별자치도지사, 시장ㆍ군수ㆍ구청장(자치구의 구청장을 말한다)에게 위임한다.', 1039);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7909, '제9조의2(고유식별정보의 처리) 여성가족부장관(제9조에 따라 여성가족부장관의 권한을 위임받은 자를 포함한다) 또는 지방자치단체의 장은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법 시행령」 제19조제1호에 따른 주민등록번호가 포함된 자료를 처리할 수 있다.', 1039);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7910, '제9조의3(규제의 재검토) 여성가족부장관은 다음 각 호의 사항에 대하여 다음 각 호의 기준일을 기준으로 3년마다(매 3년이 되는 해의 기준일과 같은 날 전까지를 말한다) 그 타당성을 검토하여 개선 등의 조치를 해야 한다.', 1039);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7911, '제10조(과태료의 부과기준) 법 제21조제1항에 따른 과태료의 부과기준은 별표 3과 같다.', 1039);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7912, '제1조(목적) 이 규칙은 「학교 밖 청소년 지원에 관한 법률」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 1040);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7913, '제2조(실태조사의 내용과 방법 등)', 1040);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7914, '제3조(상담의 방법과 내용)', 1040);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7915, '제4조(교육지원의 방법 등)', 1040);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7916, '제5조(직업체험 및 취업지원)', 1040);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7917, '제5조의2(자립지원)', 1040);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7918, '제5조의3(건강진단)', 1040);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7919, '제6조(지원센터의 지정절차 등)', 1040);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7920, '제6조의2(지원센터의 평가)', 1040);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7921, '제7조(지원센터와의 연계)', 1040);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7922, '제1조(목적) 이 규칙은 「형사소송법」 제221조의5제5항에 따라 영장심의위원회 구성과 운영 등에 필요한 사항을 규정하는 것을 목적으로 한다.', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7923, '제2조(영장심의위원회의 심의대상) 「형사소송법」(이하 "법"이라 한다) 제221조의5제2항에 따른 영장심의위원회(이하 "심의위원회"라 한다)는 법 제221조의5제1항에 따른 신청(이하 "심의신청"이라 한다)에 따라 다음 각 호의 영장 청구 여부에 관한 사항을 심의한다.', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7924, '제3조(후보단의 구성)', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7925, '제4조(위원후보의 직무윤리 사전진단 등)', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7926, '제5조(심의위원회의 구성)', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7927, '제6조(위원장 등의 임기)', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7928, '제7조(위원 등의 해촉) 각 고등검찰청 검사장은 위원 또는 위원후보가 다음 각 호의 어느 하나에 해당하는 경우에는 해당 위원 또는 위원후보를 해촉(解囑)할 수 있다.', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7929, '제8조(위원 등의 결격사유)', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7930, '제9조(위원의 제척ㆍ기피ㆍ회피)', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7931, '제10조(위원장의 직무)', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7932, '제11조(간사)', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7933, '제12조(심의의 공정성 등 유지) 각 고등검찰청 검사장은 심의위원회가 검사 등 검찰청 소속 공무원의 범죄에 관한 영장 청구 여부에 대하여 심의할 때 공정성ㆍ객관성을 유지할 수 있도록 심의위원회를 구성ㆍ운영해야 한다.', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7934, '제13조(심의신청 절차)', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7935, '제14조(심의신청의 철회)', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7936, '제15조(심의절차의 종료) 사법경찰관이 제13조제1항제2호 또는 제3호에 따라 심의신청을 한 이후 심의위원회의 회의가 개최되기 전에 검사(담당검사가 아닌 검사를 포함한다)가 심의대상 영장을 청구한 경우에는 심의절차가 종료된 것으로 본다.', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7937, '제16조(심의신청 접수사실 통보 등)', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7938, '제17조(사법경찰관의 의견서 제출 등)', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7939, '제18조(검사의 의견서 제출 등)', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7940, '제19조(피의자ㆍ변호인의 의견서 제출) 제16조제2항에 따른 통보를 받은 피의자 또는 변호인은 심의위원회에 의견서를 제출할 수 있다. 이 경우 피의자 또는 변호인은 의견서 원본 및 부본 각 1부를 제16조제2항의 통보를 받은 날부터 5일(토요일과 공휴일은 제외한다) 이내에 심의위원회에 제출해야 한다.', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7941, '제20조(심의위원회의 회의)', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7942, '제21조(의견 개진 및 질의 등)', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7943, '제22조(심의위원회의 심의)', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7944, '제23조(심의의견서 작성)', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7945, '제24조(회의록 작성) 간사는 회의록에 다음 각 호의 사항을 작성하고, 위원장의 서명 또는 날인을 받아 보관한다.', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7946, '제25조(심의 결과 통보 등)', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7947, '제26조(재신청의 제한) 사법경찰관은 심의위원회의 심의가 있었거나 제14조제1항 또는 제2항에 따라 심의신청이 철회된 경우에는 심의대상이었던 영장과 동일한 내용의 영장 청구 여부에 대하여 다시 심의신청을 할 수 없다. 다만, 심의신청을 한 이후 영장 청구 여부에 직접적인 영향을 미치는 중요한 증거가 새로 발견된 경우에는 그렇지 않다.', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7948, '제27조(심의 비공개 등)', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7949, '제28조(직무상 알게 된 사실의 누설 금지) 심의위원회의 회의에 참석한 사람은 수사사항 등 심의위원회의 심의과정에서 알게 된 사실을 누설해서는 안 된다.', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7950, '제29조(수당 등) 각 고등검찰청 검사장은 심의위원회의 심의에 참여한 위원에게 예산의 범위에서 수당과 여비를 지급할 수 있다.', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7951, '제30조(위임규정) 이 규칙에서 규정한 것 외에 심의위원회 운영에 필요한 사항은 법무부장관이 정한다.', 1041);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7952, '제1조(목적) 이 법은 「국가보안법」에서 정한 죄를 범한 자로부터 몰수하거나 국고귀속명령된 금품을 다른 법령의 규정에도 불구하고 국가안전보장을 위하여 신속하고 유효적절하게 처리함을 목적으로 한다. <개정 1980.12.31, 2018.12.18>', 1042);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7953, '제2조(몰수금품의 정의) 이 법에서 몰수금품이라 함은 다음 각 호의 어느 하나에 해당하는 자로부터 몰수한 무기류, 통신기재, 장비, 그 밖의 물품과 유가증권, 통화 등 공작금품으로서 확정판결에서 몰수되거나 「국가보안법」 제15조제2항 및 제22조에 따라 국고귀속명령된 것을 말한다. <개정 1980.12.31, 2018.9.18, 2018.12.18>', 1042);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7954, '제3조(몰수금품의 처리)', 1042);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7955, '제4조(시행령) 이 법 시행에 필요한 사항은 대통령령으로 정한다.', 1042);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7956, '제1조(목적) 이 영은 몰수금품등처리에관한임시특례법(이하 "법"이라 한다)의 시행에 관하여 필요한 사항을 규정함을 목적으로 한다.', 1043);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7957, '제2조(각급 검사등의 통보) 검찰총장ㆍ고등검찰청 검사장ㆍ지방검찰청 검사장 및 국방부검찰단장, 각 군 검찰단장(이하 "각급 검사장"이라 한다)은 법 제2조의 몰수금품이 있을 때에는 지체없이 별지 제1호서식에 의하여 국가정보원장에게 통보하여야 한다. <개정 1999.3.31, 2022.6.30>', 1043);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7958, '제3조(국가정보원장의 송부요청)', 1043);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7959, '제4조(몰수금품의 송부) 전조제1항의 규정에 의하여 몰수금품의 송부요청을 받은 각급 검사장은 송부요청을 받은 날로부터 10일이내에 그 금품을 국가정보원장에게 송부하여야 한다. <개정 1999.3.31>', 1043);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7960, '제5조(대통령의 승인)', 1043);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7961, '제6조(반환) 국가정보원장은 제4조의 규정에 의하여 송부받은 금품에 관하여, 법 제3조제1항의 규정에 의한 대통령의 승인을 얻지 못하거나 승인을 받은 후 그 사용ㆍ처분의 필요성이 없어졌다고 인정할 때에는, 그 때부터 15일이내에 그 금품을 송부한 각급 검사장에게 이를 환송하여야 한다. <개정 1999.3.31>', 1043);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7962, '제7조(국고납입) 법 제3조제2항의 규정에 의한 국고에의 납부는 납부할 금액을 국가정보원 세출예산중에서 지출하여 이를 국고에 납부함으로써 한다. <개정 1999.3.31>', 1043);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7963, '제1조(목적) 이 규칙은 「형사소송법」 제245조의2 및 제245조의3에 따른 전문수사자문위원 제도의 시행에 필요한 사항을 규정함을 목적으로 한다.', 1044);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7964, '제2조(전문수사자문위원 후보자 관리)', 1044);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7965, '제3조(전문수사자문위원의 지정)', 1044);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7966, '제4조(결격사유) 다음 각 호의 어느 하나에 해당하는 사람은 전문수사자문위원이 될 수 없다. <개정 2018.3.21>', 1044);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7967, '제5조(지정의 취소)', 1044);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7968, '제6조(이의 제기)', 1044);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7969, '제7조(의견진술) 전문수사자문위원이 수사절차에 참여하여 전문적인 지식에 의한 설명 또는 의견을 진술하거나 이를 기재한 서면을 제출한 경우 검사는 공소 제기 여부를 결정하기 전에 피의자 또는 변호인에게 구두 또는 서면으로 의견을 진술할 기회를 주어야 한다.', 1044);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7970, '제8조(수당 등)', 1044);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7971, '제9조 삭제 <2017.3.27>', 1044);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7972, '제1조(목적) 이 영은 「형사보상 및 명예회복에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 1045);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7973, '제2조(보상의 한도) 「형사보상 및 명예회복에 관한 법률」(이하 "법"이라 한다) 제5조제1항에 따른 구금(拘禁)에 대한 보상금의 한도는 1일당 보상청구의 원인이 발생한 해의 「최저임금법」에 따른 일급(日給) 최저임금액의 5배로 한다.', 1045);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7974, '제3조(피의자보상심의회의 구성) 법 제27조제3항에 따른 피의자보상심의회(이하 "심의회"라 한다)는 그 심의회가 설치된 지방검찰청의 차장검사를 위원장으로 하고, 다음 각 호의 사람 중에서 법무부장관이 임명하거나 위촉하는 위원 4명으로 구성한다.', 1045);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7975, '제4조(심의회 위원장) 심의회의 위원장(이하 "위원장"이라 한다)은 심의회의 업무를 총괄하고, 심의회를 대표한다.', 1045);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7976, '제5조(심의회의 의사(議事))', 1045);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7977, '제6조(위원 수당) 심의회의 회의에 출석한 위원에게는 예산의 범위에서 수당을 지급한다.', 1045);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7978, '제7조(법무부장관의 지휘ㆍ감독)', 1045);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7979, '제8조(보상청구서)', 1045);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7980, '제9조(필요한 조사)', 1045);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7981, '제10조(결정 및 통지)', 1045);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7982, '제11조(피의자 보상 지급의 청구) 제10조제3항에 따른 보상결정통지서를 받은 청구인이 보상금을 받으려면 다음 각 호의 사항을 적은 청구서를 보상결정을 한 심의회가 설치되어 있는 지방검찰청에 제출하여야 한다.', 1045);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7983, '제12조(무죄재판서 게재 전담부서의 지정) 법무부장관은 법 제30조에 따른 무죄재판사건의 재판서(이하 "무죄재판서"라 한다) 게재 업무를 효율적으로 처리하기 위하여 필요하면 해당 업무를 담당할 전담부서를 지정할 수 있다.', 1045);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7984, '제13조(전담직원의 지정 등)', 1045);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7985, '제1조(목적) 이 규칙은 「민영교도소 등의 설치ㆍ운영에 관한 법률」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7986, '제2조 삭제 <2009.9.3>', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7987, '제3조(교정법인의 정관변경 인가신청) 교정법인이 「민영교도소 등의 설치ㆍ운영에 관한 법률」(이하 "법"이라 한다) 제10조제2항에 따라 정관 변경의 인가를 받으려는 경우에는 정관 변경 인가신청서에 다음 각 호의 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7988, '제4조(임원취임 승인신청)', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7989, '제5조(기본재산의 처분)', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7990, '제6조(사업계획 등의 제출)', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7991, '제7조(예산편성 요강)', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7992, '제8조(회계원칙) 교정법인의 회계는 이 규칙에 특별한 규정이 있는 경우를 제외하고는 모든 회계거래를 발생의 사실에 의하여 기업회계의 원칙에 따라 처리한다.', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7993, '제9조(합병인가 신청)', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7994, '제10조(분할인가 신청) 교정법인이 법 제17조제1항제2호에 따른 분할의 인가를 신청할 경우에는 분할인가 신청서에 다음 각 호의 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7995, '제11조(해산인가 신청) 교정법인이 법 제17조제1항제3호에 따라 해산의 인가를 신청하는 경우에는 해산사유, 수용자 처리계획 및 직원 처리계획이 포함된 해산인가 신청서에 다음 각 호의 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7996, '제12조(합병ㆍ분할ㆍ해산의 인가 시에 붙일 조건)', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7997, '제13조(시설 등 검사절차)', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7998, '제14조(시설검사 방법) 법 제22조에 따라 민영교도소등의 시설을 검사를 하는 경우 유의할 사항은 다음 각 호와 같다.', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (7999, '제15조(운영 경비)', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8000, '제16조(설치비용 지급)', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8001, '제17조(직원의 임면승인)', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8002, '제18조 삭제 <2025.5.27>', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8003, '제19조(교육 등)', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8004, '제20조(제복 및 사복 착용)', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8005, '제21조(신분증명서)', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8006, '제22조(무기ㆍ탄약의 배정 등)', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8007, '제23조(장부와 비치서류)', 1046);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8008, '제1조(목적) 이 규칙은 「치료감호 등에 관한 법률」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다. <개정 2016.12.2>', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8009, '제2조 삭제 <2008.12.12>', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8010, '제3조(치료감호청구의 방식)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8011, '제4조(조사사항)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8012, '제5조(치료감호영장청구서 등) 법 제6조제1항의 치료감호영장청구는 별지 제3호서식의 치료감호영장청구서로 하여야 하고, 같은 조 제2항의 치료감호영장신청은 별지 제4호서식의 치료감호영장신청서로 하여야 한다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8013, '제6조(송치서류)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8014, '제7조(치료감호불청구의 방식) 검사는 사법경찰관이 치료감호청구의견으로 송치한 사건이나 검사가 수사결과 보호구속한 사건에 대하여 치료감호를 청구하지 아니한다는 결정을 한 때에는 별지 제5호서식의 치료감호불청구결정서를 작성하고, 치료감호사건의 요지와 조사의 결과 및 청구를 하지 아니하는 이유를 적어야 한다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8015, '제8조(치료감호사건의 보고)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8016, '제9조(재판 결과의 통보) 지방검찰청 또는 지청에서는 치료감호사건에 대한 재판이 확정된 때에는 지체 없이 그 재판 결과를 송치사건처리결과통지 및 처분결과통보서송부표에 적어서 송치관서에 송부하여야 한다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8017, '제9조의2(치료감호 기간의 연장 신청 등)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8018, '제9조의3(경비보조 청구) 영 제4조의5제2항에 따른 경비보조 청구서는 별지 제5호의5서식과 같다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8019, '제10조(치료감호의 집행지휘서 등)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8020, '제11조(치료감호의 집행 지휘 등)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8021, '제12조(피치료감호자 동태보고서)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8022, '제12조의2(재이송 신청서) 영 제6조의2제1항에 따른 지정법무병원의 장의 피치료감호자 재이송 신청은 별지 제8호의3서식에 따른다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8023, '제13조(서약서)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8024, '제13조의2(피치료감호자등 보호원부) 영 제7조의3제5항에 따른 피치료감호자등 보호원부는 별지 제9호의2서식에 따른다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8025, '제14조(청원함 설치 등) 치료감호시설의 장은 법 제30조 및 영 제8조에 따른 피치료감호자 처우개선에 관한 청원을 보장하기 위하여 병동 등 이용하기 쉬운 장소에 청원함을 설치하고 안내문을 게시하여야 하며, 청원의 접수ㆍ처리 등을 위하여 별지 제10호서식의 청원관리부를 갖춰 두고 운용하여야 한다. <개정 2014.1.29>', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8026, '제15조(보호관찰에 관한 지시)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8027, '제16조(진술서)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8028, '제16조의2(준수사항의 추가ㆍ변경 또는 삭제 신청 등) 법 제33조제3항 및 영 제9조의2제2항에 따른 피보호관찰자의 준수사항 전부 또는 일부의 추가ㆍ변경 또는 삭제의 신청은 별지 제12호의2서식에 따른다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8029, '제16조의3(경고장) 영 제9조의3에 따른 피보호관찰자에 대한 경고는 별지 제12호의3서식에 따른다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8030, '제17조(피보호관찰자 정기신고서) 영 제10조제1항의 정기신고는 별지 제13호서식의 피보호관찰자 정기신고서로 하여야 한다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8031, '제18조(신고접수부 및 피보호관찰자의 주거이전ㆍ여행 신고)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8032, '제18조의2(유치허가신청서 등)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8033, '제18조의3(가종료 또는 치료 위탁의 취소 신청 및 결정 통보)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8034, '제19조(보호관찰부)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8035, '제20조(보호관찰관의 보고) 보호관찰관은 영 제11조제3항ㆍ제4항ㆍ제7항, 영 제13조제6항 또는 이 규칙 제15조제2항에 따른 보고를 할 때에는 별지 제18호서식의 보호관찰보고서 2부를 작성하여 1부는 검사에게 송부하고, 1부는 위원회에 송부한다. <개정 2014.1.29>', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8036, '제21조(여행지 보호관찰관의 임무)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8037, '제22조(검사의 자료 이송) 피보호관찰자가 주거를 이전한 경우 피보호관찰자에 대한 자료를 보존 중인 검찰청의 검사는 피보호관찰자의 새 주거지 관할 검찰청에 그 자료를 송부하여야 한다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8038, '제23조(출소신고서 등)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8039, '제24조(가종료 등의 취소와 치료감호의 재집행)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8040, '제25조(이송을 위한 수용) 치료감호가 종료된 수형자를 치료감호시설에서 교도소 또는 소년교도소로 이송하는 경우에는 이송에 필요한 기간 동안 치료감호시설에 일시 수용할 수 있다. <개정 2014.1.29>', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8041, '제26조(보호관찰관 등의 주의 의무) 보호관찰관이 피보호관찰자를 출석하게 하여 법 제33조에 따른 준수사항 또는 그 밖에 지도ㆍ감독상 필요한 사실을 확인하는 경우, 관계자의 협조를 요청하는 경우, 검사 또는 사법경찰관리가 특히 치료감호만을 청구하기 위하여 조사를 하는 경우에는 치료감호대상자나 그 밖의 관계자의 생업에 지장을 초래하거나 명예를 훼손하지 아니하도록 주의하여야 한다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8042, '제26조의2(외래진료의 기간ㆍ방법 등)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8043, '제26조의3(외래진료비용)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8044, '제26조의4(정신보건 관련 정보 요청서 등)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8045, '제27조(가종료 등의 결정기준) 위원회가 법 제37조제3항에 규정된 사항(이하 "치료감호사안"이라 한다)을 심사ㆍ결정할 때에는 피치료감호자의 연령ㆍ건강상태ㆍ경력ㆍ가족관계ㆍ가정환경ㆍ범죄경력ㆍ치료 경과ㆍ준수사항의 이행 여부, 그 밖에 필요한 사항을 고려하여야 한다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8046, '제28조(조사공무원의 임명) 법 제40조제2항에 따라 위원회의 명을 받아 조사의 직무를 수행할 조사공무원은 법무부 소속 공무원 중에서 법무부장관이 임명한다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8047, '제29조(조사의 촉탁) 검사인 조사공무원은 치료감호사안을 조사하는 데에 필요하면 지방검찰청 또는 지청의 검사에게 그 조사를 촉탁할 수 있다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8048, '제30조(조사공무원의 의견) 조사공무원은 위원회에 제출하는 조사보고서에 의견을 첨부할 수 있다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8049, '제31조(심사신청서 등)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8050, '제32조(위원회의 결정서) 영 제19조에 따른 결정서의 서식은 별지 제28호서식과 같다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8051, '제33조(송달 등의 방법)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8052, '제34조(수당 등) 영 제23조에 따른 출석수당 및 여비는 별표와 같다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8053, '제35조(장부 및 서류의 비치) 치료감호대상사건 및 치료감호사안의 조사 사무를 처리하는 관서에는 다음 각 호의 장부 및 서류를 갖춰 두어야 한다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8054, '제36조(장부 및 서류의 보존기간) 장부 및 서류는 다음의 기간 동안 보존하여야 한다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8055, '제37조(치료감호사건기록의 보존기간) 완결된 치료감호사건기록은 치료감호의 시효가 완성될 때까지 보존하여야 한다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8056, '제38조(치료감호사안 조사기록의 보존기관 등)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8057, '제39조(「검찰사건사무규칙」 등의 준용) 치료감호대상사건이나 치료감호사안의 조사ㆍ보고 및 집행의 절차와 서식에 관하여 이 규칙에 특별한 규정이 있는 경우를 제외하고는 그 성질에 반하지 아니하는 범위에서 「검사와 사법경찰관의 상호협력과 일반적 수사준칙에 관한 규정」 및 「검찰사건사무규칙」, 「검찰압수물 사무규칙」, 「자유형등에 관한 검찰집행사무규칙」, 「검찰보존사무규칙」, 「검찰보고사무규칙」을 준용한다. <개정 2011.12.30, 2021.1.1>', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8058, '제40조(집행지휘 서면) 영 제26조에 따른 지휘 서면은 별지 제30호서식에 따른다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8059, '제41조(치료기관의 지정기준 등)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8060, '제42조(치료비용 국가부담 신청서) 영 제32조제2항에 따른 치료비용 국가부담 신청서는 별지 제31호서식에 따른다.', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8061, '제43조(자료제출 요청 등)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8062, '제44조(기부금품의 접수 영수증 등)', 1047);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8063, '제1조(목적) 이 법은 국가, 사회, 개인에게 중대한 해악을 끼치는 특정중대범죄 사건에 대하여 수사 및 재판 단계에서 피의자 또는 피고인의 신상정보 공개에 대한 대상과 절차 등을 규정함으로써 국민의 알권리를 보장하고 범죄를 예방하여 안전한 사회를 구현하는 것을 목적으로 한다.', 1048);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8064, '제2조(정의) 이 법에서 "특정중대범죄"란 다음 각 호의 어느 하나에 해당하는 죄를 말한다.', 1048);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8065, '제3조(다른 법률과의 관계) 수사 및 재판 단계에서 신상정보의 공개에 대하여는 다른 법률의 규정에도 불구하고 이 법을 우선 적용한다.', 1048);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8066, '제4조(피의자의 신상정보 공개)', 1048);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8067, '제5조(피고인의 신상정보 공개)', 1048);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8068, '제6조(피의자에 대한 보상)', 1048);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8069, '제7조(피고인에 대한 보상)', 1048);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8070, '제8조(신상정보공개심의위원회)', 1048);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8071, '제9조(비밀누설죄) 제8조제4항을 위반하여 비밀을 외부에 공개하거나 누설한 사람은 1년 이하의 징역이나 금고 또는 1천만원 이하의 벌금에 처한다.', 1048);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8072, '제1조(목적) 이 영은 「특정중대범죄 피의자 등 신상정보 공개에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 1049);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8073, '제2조(촬영 방법) 검사와 사법경찰관은 「특정중대범죄 피의자 등 신상정보 공개에 관한 법률」(이하 "법"이라 한다) 제4조제5항(법 제5조제7항에서 준용하는 경우를 포함한다)에 따라 특정중대범죄사건의 피의자 또는 피고인(이하 "피의자등"이라 한다)의 얼굴을 촬영하는 경우에는 피의자등의 정면ㆍ왼쪽ㆍ오른쪽 얼굴 컬러사진을 촬영하여 전자기록으로 저장ㆍ보관해야 한다.', 1049);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8074, '제3조(피의자의 의견진술)', 1049);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8075, '제4조(피의자 신상정보 공개 결정의 통지 등)', 1049);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8076, '제5조(피의자 신상정보 공개 방법 및 공개의 종료 등)', 1049);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8077, '제6조(불기소처분 통보 등)', 1049);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8078, '제7조(피고인의 신상정보 공개)', 1049);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8079, '제8조(신상정보공개심의위원회)', 1049);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8080, '제9조(민감정보 및 고유식별정보의 처리) 검사와 사법경찰관은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 민감정보나 같은 법 시행령 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 1049);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8081, '제1조(목적) 이 법은 형사소송 절차에서 무죄재판 등을 받은 자에 대한 형사보상 및 명예회복을 위한 방법과 절차 등을 규정함으로써 무죄재판 등을 받은 자에 대한 정당한 보상과 실질적 명예회복에 이바지함을 목적으로 한다.', 1050);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8082, '제2조(보상 요건)', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8083, '제3조(상속인에 의한 보상청구)', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8084, '제4조(보상하지 아니할 수 있는 경우) 다음 각 호의 어느 하나에 해당하는 경우에는 법원은 재량(裁量)으로 보상청구의 전부 또는 일부를 기각(棄却)할 수 있다.', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8085, '제5조(보상의 내용)', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8086, '제6조(손해배상과의 관계)', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8087, '제7조(관할법원) 보상청구는 무죄재판을 한 법원에 대하여 하여야 한다.', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8088, '제8조(보상청구의 기간) 보상청구는 무죄재판이 확정된 사실을 안 날부터 3년, 무죄재판이 확정된 때부터 5년 이내에 하여야 한다.', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8089, '제9조(보상청구의 방식)', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8090, '제10조(상속인의 소명) 상속인이 보상을 청구할 때에는 본인과의 관계와 같은 순위의 상속인 유무를 소명(疏明)할 수 있는 자료를 제출하여야 한다.', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8091, '제11조(상속인의 보상청구의 효과)', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8092, '제12조(보상청구의 취소)', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8093, '제13조(대리인에 의한 보상청구) 보상청구는 대리인을 통하여서도 할 수 있다.', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8094, '제14조(보상청구에 대한 재판)', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8095, '제15조(직권조사사항) 법원은 보상청구의 원인이 된 사실인 구금일수 또는 형 집행의 내용에 관하여 직권으로 조사를 하여야 한다.', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8096, '제16조(보상청구 각하의 결정) 법원은 다음 각 호의 어느 하나에 해당하는 경우에는 보상청구를 각하(却下)하는 결정을 하여야 한다.', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8097, '제17조(보상 또는 청구기각의 결정)', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8098, '제18조(결정의 효과) 보상청구를 할 수 있는 같은 순위의 상속인이 여러 명인 경우에 그 중 1명에 대한 제17조의 보상결정이나 청구기각의 결정은 같은 순위자 모두에 대하여 한 것으로 본다.', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8099, '제19조(보상청구의 중단과 승계)', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8100, '제20조(불복신청)', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8101, '제21조(보상금 지급청구)', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8102, '제21조의2(보상금 지급기한 등)', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8103, '제22조(보상금 지급의 효과) 보상금을 받을 수 있는 자가 여러 명인 경우에는 그 중 1명에 대한 보상금 지급은 그 모두에 대하여 효력이 발생한다.', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8104, '제23조(보상청구권의 양도 및 압류의 금지) 보상청구권은 양도하거나 압류할 수 없다. 보상금 지급청구권도 또한 같다.', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8105, '제24조(준용규정) 이 법에 따른 결정과 즉시항고에 관하여는 이 법에 특별한 규정이 있는 것을 제외하고는 「형사소송법」의 규정을 준용한다. 기간에 관하여도 또한 같다.', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8106, '제25조(보상결정의 공시)', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8107, '제26조(면소 등의 경우)', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8108, '제27조(피의자에 대한 보상)', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8109, '제28조(피의자보상의 청구 등)', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8110, '제29조(준용규정)', 1051);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8111, '제30조(무죄재판서 게재 청구) 무죄재판을 받아 확정된 사건(이하 "무죄재판사건"이라 한다)의 피고인은 무죄재판이 확정된 때부터 3년 이내에 확정된 무죄재판사건의 재판서(이하 "무죄재판서"라 한다)를 법무부 인터넷 홈페이지에 게재하도록 해당 사건을 기소한 검사가 소속된 지방검찰청(지방검찰청 지청을 포함한다)에 청구할 수 있다.', 1052);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8112, '제31조(청구방법)', 1052);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8113, '제32조(청구에 대한 조치)', 1052);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8114, '제33조(청구에 대한 조치의 통지 등)', 1052);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8115, '제34조(면소 등의 경우)', 1052);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8116, '제35조(준용규정) 다음 각 호의 어느 하나에 해당하는 자에 대한 명예회복에 대하여는 이 장의 규정을 준용한다. 이 경우 "법원"은 "군사법원"으로, "검찰청"은 "군검찰부"로, "법무부장관"은 "국방부장관"으로 본다.', 1052);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8117, '제1조(목적) 이 영은 「형사보상 및 명예회복에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 1053);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8118, '제2조(보상의 한도) 「형사보상 및 명예회복에 관한 법률」(이하 "법"이라 한다) 제5조제1항에 따른 구금(拘禁)에 대한 보상금의 한도는 1일당 보상청구의 원인이 발생한 해의 「최저임금법」에 따른 일급(日給) 최저임금액의 5배로 한다.', 1053);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8119, '제3조(피의자보상심의회의 구성) 법 제27조제3항에 따른 피의자보상심의회(이하 "심의회"라 한다)는 그 심의회가 설치된 지방검찰청의 차장검사를 위원장으로 하고, 다음 각 호의 사람 중에서 법무부장관이 임명하거나 위촉하는 위원 4명으로 구성한다.', 1053);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8120, '제4조(심의회 위원장) 심의회의 위원장(이하 "위원장"이라 한다)은 심의회의 업무를 총괄하고, 심의회를 대표한다.', 1053);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8121, '제5조(심의회의 의사(議事))', 1053);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8122, '제6조(위원 수당) 심의회의 회의에 출석한 위원에게는 예산의 범위에서 수당을 지급한다.', 1053);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8123, '제7조(법무부장관의 지휘ㆍ감독)', 1053);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8124, '제8조(보상청구서)', 1053);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8125, '제9조(필요한 조사)', 1053);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8126, '제10조(결정 및 통지)', 1053);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8127, '제11조(피의자 보상 지급의 청구) 제10조제3항에 따른 보상결정통지서를 받은 청구인이 보상금을 받으려면 다음 각 호의 사항을 적은 청구서를 보상결정을 한 심의회가 설치되어 있는 지방검찰청에 제출하여야 한다.', 1053);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8128, '제12조(무죄재판서 게재 전담부서의 지정) 법무부장관은 법 제30조에 따른 무죄재판사건의 재판서(이하 "무죄재판서"라 한다) 게재 업무를 효율적으로 처리하기 위하여 필요하면 해당 업무를 담당할 전담부서를 지정할 수 있다.', 1053);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8129, '제13조(전담직원의 지정 등)', 1053);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8130, '제1조(목적) 이 법은 특정범죄와 관련된 범죄수익(犯罪收益)의 취득 등에 관한 사실을 가장(假裝)하거나 특정범죄를 조장할 목적 또는 적법하게 취득한 재산으로 가장할 목적으로 범죄수익을 은닉(隱匿)하는 행위를 규제하고, 특정범죄와 관련된 범죄수익의 몰수 및 추징(追徵)에 관한 특례를 규정함으로써 특정범죄를 조장하는 경제적 요인을 근원적으로 제거하여 건전한 사회질서의 유지에 이바지함을 목적으로 한다.', 1054);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8131, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다. <개정 2014.5.28, 2014.11.19, 2022.1.4>', 1054);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8132, '제3조(범죄수익등의 은닉 및 가장)', 1054);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8133, '제4조(범죄수익등의 수수) 그 정황을 알면서 범죄수익등을 수수(收受)한 자는 3년 이하의 징역 또는 2천만원 이하의 벌금에 처한다. 다만, 법령에 따른 의무 이행으로서 제공된 것을 수수한 자 또는 계약(채권자가 상당한 재산상의 이익을 제공하는 것만 해당한다) 시에 그 계약에 관련된 채무의 이행이 범죄수익등에 의하여 행하여지는 것이라는 정황을 알지 못하고 그 계약과 관련된 채무의 이행으로서 제공된 것을 수수한 자의 경우에는 그러하지 아니하다.', 1054);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8134, '제5조(금융회사등의 신고 등)', 1054);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8135, '제6조(징역과 벌금의 병과) 제3조, 제4조 및 제5조제3항에 따른 죄를 범한 자에게는 징역과 벌금을 병과(倂科)할 수 있다.', 1054);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8136, '제7조(양벌규정) 법인의 대표자나 법인 또는 개인의 대리인, 사용인, 그 밖의 종업원이 그 법인 또는 개인의 업무에 관하여 제3조부터 제5조까지의 어느 하나에 해당하는 위반행위를 하면 그 행위자를 벌하는 외에 그 법인 또는 개인에게도 해당 조문의 벌금형을 과(科)한다. 다만, 법인 또는 개인이 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다.', 1054);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8137, '제7조의2(국외범) 제3조 및 제4조는 대한민국 영역 밖에서 해당 죄를 범한 내국인에게도 적용한다.', 1054);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8138, '제8조(범죄수익등의 몰수)', 1054);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8139, '제9조(몰수의 요건 등)', 1054);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8140, '제10조(추징)', 1054);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8141, '제10조의2(추징 집행의 특례) 다중인명피해사고 발생에 형사적 책임이 있는 개인, 법인 및 경영지배ㆍ경제적 연관 또는 의사결정에의 참여 등을 통해 그 법인을 실질적으로 지배하는 자에 대한 이 법에 따른 몰수대상재산에 관한 추징은 범인 외의 자가 그 정황을 알면서 취득한 몰수대상재산 및 그로부터 유래한 재산에 대하여 그 범인 외의 자를 상대로 집행할 수 있다.', 1054);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8142, '제10조의3(몰수ㆍ추징의 집행을 위한 검사의 처분)', 1054);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8143, '제10조의4(범죄수익등의 추정) 다음 각 호에 해당하는 죄에 관계된 범죄수익등을 산정할 때에는 범죄행위를 한 기간에 범인이 취득한 재산으로서 그 취득한 재산이 범죄수익등의 금액 및 재산 취득 시기 등 제반 사정에 비추어 같은 조의 죄를 범하여 얻은 범죄수익등으로 형성되었다고 볼만한 상당한 개연성이 있는 경우에는 그 죄에 관계된 범죄수익등으로 추정한다.', 1054);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8144, '제11조(국제 공조) 특정범죄와 제3조 및 제4조의 죄에 해당하는 행위에 대한 외국의 형사사건에 관하여 그 외국으로부터 몰수 또는 추징의 확정재판의 집행이나 몰수 또는 추징을 위한 재산 보전(保全)의 공조(共助) 요청이 있을 때에는 다음 각 호의 어느 하나에 해당하는 경우를 제외하고는 그 요청에 관하여 공조할 수 있다.', 1054);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8145, '제12조(「마약류 불법거래 방지에 관한 특례법」의 준용) 이 법에 따른 몰수 및 추징과 국제 공조에 관하여는 「마약류 불법거래 방지에 관한 특례법」 제19조부터 제63조까지, 제64조제2항 및 제65조부터 제78조까지의 규정을 준용한다.', 1054);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8146, '제13조(포상금 지급)', 1054);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8147, '제1조(목적) 이 영은 「범죄수익은닉의 규제 및 처벌 등에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 1055);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8148, '제2조(신고 또는 공로의 범위)', 1055);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8149, '제3조(포상금의 지급 기준 등)', 1055);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8150, '제4조(포상금의 지급 신청)', 1055);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8151, '제5조(포상금의 환수) 법무부장관은 포상금을 지급받은 자가 다음 각 호의 어느 하나에 해당하는 경우에는 그 포상금을 환수할 수 있다. 다만, 제1호의 경우에는 포상금을 환수하여야 한다.', 1055);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8152, '제6조(민감정보 및 고유식별정보의 처리) 법무부장관과 지방검찰청 검사장은 포상금의 지급에 관한 사무를 처리하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 민감정보나 같은 법 시행령 제19조제1호부터 제4호까지의 규정에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호를 처리할 수 있다.', 1055);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8153, '제1조(목적) 이 법은 운항 중인 선박 및 해상구조물에 대한 위해행위(危害行爲)를 방지함으로써 선박의 안전한 운항과 해상구조물의 안전을 보호함을 목적으로 한다.', 1056);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8154, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다.', 1056);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8155, '제3조(외국인에 대한 적용 범위) 이 법은 다음 각 호의 어느 하나에 해당하는 외국인에게도 적용한다.', 1056);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8156, '제4조(범죄인의 인도)', 1056);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8157, '제5조(폭행ㆍ협박ㆍ상해ㆍ살인죄)', 1056);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8158, '제6조(선박 납치죄)', 1056);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8159, '제7조(선박 등의 손괴죄) 운항 중인 선박 또는 해상구조물을 파괴하거나, 운항 중인 선박이나 해상구조물 또는 그에 적재된 화물에 그 안전을 위험하게 할 만한 손상을 입힌 사람은 3년 이상의 유기징역에 처한다.', 1056);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8160, '제8조(선박 운항 관련 기기ㆍ시설의 손괴죄 등) 운항 중인 선박의 안전을 위험하게 할 목적으로 그 선박 운항과 관련된 기기ㆍ시설을 파괴하거나 중대한 손상을 가하거나 기능장애 상태를 발생시킨 사람은 10년 이하의 징역에 처한다.', 1056);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8161, '제9조(위험 물건 설치ㆍ탑재죄) 운항 중인 선박 또는 해상구조물의 안전을 위험하게 할 만한 물건을 그 선박 또는 해상구조물에 설치하거나 탑재한 사람은 7년 이하의 징역에 처한다.', 1056);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8162, '제10조(거짓 정보 전달죄) 거짓된 정보를 전달하여 선박의 안전운항을 위험하게 한 사람은 7년 이하의 징역 또는 5천만원 이하의 벌금에 처한다. <개정 2017.12.12>', 1056);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8163, '제11조(미수범) 제5조제1항ㆍ제2항(폭행은 제외한다), 제6조제1항 및 제7조부터 제10조까지에 규정된 죄의 미수범은 처벌한다.', 1056);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8164, '제12조(선박 납치 등 살인ㆍ치사죄, 상해ㆍ치상죄)', 1056);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8165, '제13조(협박죄) 다른 사람의 권리행사를 방해하거나 의무가 없는 일을 하게 할 목적으로 제5조제1항ㆍ제2항, 제7조 또는 제8조의 죄를 범하여 운항 중인 선박 또는 해상구조물의 안전을 위험하게 할 것이라고 고지함으로써 다른 사람을 협박한 사람은 5년 이하의 징역 또는 3천만원 이하의 벌금에 처한다. <개정 2017.12.12>', 1056);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8166, '제1조(목적) 이 법은 대한민국 국민이 적법한 절차를 밟지 아니하고 대한민국 외의 지역으로 도항(渡航)하는 것을 방지함을 목적으로 한다.', 1057);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8167, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다.', 1057);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8168, '제3조(밀항ㆍ이선 등)', 1057);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8169, '제4조(밀항 등 알선)', 1057);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8170, '제4조의2(몰수ㆍ추징)', 1057);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8171, '제5조(형의 가중) 상습적으로 제3조 또는 제4조의 죄를 범한 사람은 각 죄에 정한 형의 2분의 1까지 가중한다.', 1057);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8172, '제6조(형의 감면 등)', 1057);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8173, '제7조(사건 통보 등)', 1057);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8174, '제8조 삭제 <1989.12.27>', 1057);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8175, '제9조 삭제 <1989.12.27>', 1057);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8176, '제1조(목적) 이 법은 디엔에이신원확인정보의 수집ㆍ이용 및 보호에 필요한 사항을 정함으로써 범죄수사 및 범죄예방에 이바지하고 국민의 권익을 보호함을 목적으로 한다.', 1058);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8177, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다.', 1058);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8178, '제3조(국가의 책무)', 1058);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8179, '제4조(디엔에이신원확인정보의 사무관장)', 1058);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8180, '제5조(수형인등으로부터의 디엔에이감식시료 채취)', 1058);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8181, '제6조(구속피의자등으로부터의 디엔에이감식시료 채취) 검사 또는 사법경찰관(군사법경찰관을 포함한다. 이하 같다)은 제5조제1항 각 호의 어느 하나에 해당하는 죄 또는 이와 경합된 죄를 범하여 구속된 피의자 또는 「치료감호법」에 따라 보호구속된 치료감호대상자(이하 "구속피의자등"이라 한다)로부터 디엔에이감식시료를 채취할 수 있다. 다만, 제5조에 따라 디엔에이감식시료를 채취하여 디엔에이신원확인정보가 이미 수록되어 있는 경우는 제외한다.', 1058);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8182, '제7조(범죄현장등으로부터의 디엔에이감식시료 채취)', 1058);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8183, '제8조(디엔에이감식시료채취영장)', 1058);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8184, '제8조의2(불복절차)', 1058);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8185, '제9조(디엔에이감식시료의 채취 방법)', 1058);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8186, '제10조(디엔에이신원확인정보의 수록 등)', 1058);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8187, '제11조(디엔에이신원확인정보의 검색ㆍ회보)', 1058);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8188, '제12조(디엔에이감식시료의 폐기)', 1058);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8189, '제13조(디엔에이신원확인정보의 삭제)', 1058);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8190, '제14조(디엔에이신원확인정보데이터베이스관리위원회)', 1058);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8191, '제15조(업무목적 외 사용 등의 금지) 디엔에이신원확인정보담당자는 업무상 취득한 디엔에이감식시료 또는 디엔에이신원확인정보를 업무목적 외에 사용하거나 타인에게 제공 또는 누설하여서는 아니 된다.', 1058);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8192, '제16조(벌칙 적용 시 공무원 의제) 디엔에이신원확인정보담당자 중 공무원이 아닌 사람은 「형법」이나 그 밖의 법률에 따른 벌칙을 적용할 때에는 공무원으로 본다.', 1058);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8193, '제17조(벌칙)', 1058);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8194, '제1조(목적) 이 영은 「디엔에이신원확인정보의 이용 및 보호에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 1059);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8195, '제2조(정의) 이 영에서 사용하는 용어의 뜻은 다음과 같다.', 1059);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8196, '제3조(디엔에이인적관리시스템의 운영)', 1059);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8197, '제4조(디엔에이인적관리자)', 1059);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8198, '제5조(데이터베이스의 연계) 검찰총장 및 경찰청장은 법 제4조제3항에 따라 데이터베이스를 서로 연계하여 운영할 때에는 데이터베이스의 수록내용을 상호 열람, 검색할 수 있도록 전자적으로 연계하여야 한다.', 1059);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8199, '제6조(디엔에이감식시료 채취의 위탁)', 1059);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8200, '제7조(디엔에이감식시료채취영장의 집행 등)', 1059);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8201, '제8조(디엔에이감식시료의 채취 방법 및 관리)', 1059);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8202, '제9조(디엔에이감식시료 채취사실의 기록) 검사 또는 사법경찰관은 법 제6조 및 제7조제1항에 따라 디엔에이감식시료를 채취한 경우 채취 일시와 장소 및 방법, 채취한 디엔에이감식시료의 종류와 채취 사유 등을 적은 서류를 작성하여 사건기록에 첨부하여야 한다.', 1059);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8203, '제10조(수형인등 또는 구속피의자등으로부터 채취한 디엔에이감식시료의 송부)', 1059);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8204, '제11조(범죄현장등으로부터 채취한 디엔에이감식시료의 송부)', 1059);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8205, '제12조(업무의 위임 및 위탁)', 1059);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8206, '제13조(디엔에이감식 등)', 1059);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8207, '제14조(데이터베이스의 관리 등)', 1059);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8208, '제15조(디엔에이신원확인정보의 검색 및 회보)', 1059);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8209, '제16조(디엔에이감식시료의 폐기)', 1059);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8210, '제17조(디엔에이신원확인정보의 삭제 방법, 절차 등)', 1059);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8211, '제18조(디엔에이신원확인정보데이터베이스관리위원회의 심의사항) 법 제14조제1항제4호에서 "대통령령으로 정하는 사항"이란 다음 각 호와 같다.', 1059);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8212, '제19조(디엔에이신원확인정보데이터베이스관리위원회의의 구성 및 운영)', 1059);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8213, '제19조의2(위원회 위원의 해촉) 국무총리는 법 제14조제3항에 따른 위원회의 위원이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 위원을 해촉(解囑)할 수 있다.', 1059);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8214, '제20조(위원회의 의견제출) 위원회가 법 제14조제6항에 따라 검찰총장 또는 경찰청장에게 의견을 제시한 경우 검찰총장 또는 경찰청장은 의견의 시행 경과 및 결과를 위원회에 통보하여야 한다.', 1059);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8215, '제1조(목적) 이 영은 「벌금 미납자의 사회봉사 집행에 관한 특례법」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 1060);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8216, '제2조(사회봉사의 신청과 벌금액) 「벌금 미납자의 사회봉사 집행에 관한 특례법」(이하 "법"이라 한다) 제4조제1항 본문에 따른 벌금형의 금액은 500만원으로 한다. <개정 2020.1.7>', 1060);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8217, '제3조(사회봉사 신청에 필요한 서류 및 제출방법) 법 제4조제1항에 따라 사회봉사를 신청하는 사람은 다음 각 호의 서류를 첨부하여 주거지를 관할하는 지방검찰청(지방검찰청 지청을 포함한다. 이하 같다)의 검사에게 신청서를 제출하여야 한다.', 1060);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8218, '제4조(사회봉사의 청구) 법 제5조제1항에 따라 검사가 사회봉사의 허가를 청구할 때에는 사회봉사 청구서와 함께 사회봉사 신청인이 제출한 자료 및 관련 소명자료를 관할 법원에 제출하여야 한다.', 1060);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8219, '제5조(신청인의 자료제출 동의) 검사는 법 제5조제2항에 따라 공공기관, 민간단체 등에 벌금 납입 능력 확인에 필요한 자료의 제출을 요구할 때에는 다음 각 호의 사항이 적힌 신청인의 동의서를 첨부하여야 한다.', 1060);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8220, '제6조(사회봉사의 신고) 사회봉사 대상자는 법 제8조제1항에서 정한 사항 외에 다음 각 호의 사항을 주거지를 관할하는 보호관찰소에 출석하여 서면으로 신고하여야 한다.', 1060);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8221, '제7조(집행 개시 시기) 법 제8조에 따라 사회봉사 대상자의 신고를 받은 보호관찰소의 장은 보호관찰관에게 사회봉사 집행 장소 등 집행 여건을 갖추어 지체 없이 사회봉사를 집행하게 하여야 한다. 다만, 사회봉사 대상자의 생업, 학업, 질병 등을 고려하여 집행 개시 시기를 조정할 수 있다.', 1060);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8222, '제8조(집행시간)', 1060);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8223, '제9조(집행 대상 인원) 보호관찰관은 사회봉사 집행의 분야 및 장소 등을 고려하여 적절한 사회봉사 집행 대상 인원을 결정하여야 한다.', 1060);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8224, '제10조(집행기간의 연장)', 1060);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8225, '제11조(미납 벌금액과 남은 사회봉사시간의 산정)', 1060);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8226, '제12조(벌금 납입에 따른 검사의 통보)', 1060);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8227, '제13조(민감정보 및 고유식별정보의 처리)', 1060);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8228, '제1조(목적) 이 법은 범증이 명백하고 죄질이 경미한 범죄사건을 신속ㆍ적정한 절차로 심판하기 위하여 즉결심판에 관한 절차를 정함을 목적으로 한다. <개정 1994ㆍ7ㆍ27>', 1061);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8229, '제2조(즉결심판의 대상) 지방법원, 지원 또는 시ㆍ군법원의 판사(이하 "判事"라 한다)는 즉결심판절차에 의하여 피고인에게 20만원 이하의 벌금, 구류 또는 과료에 처할 수 있다. <개정 1994ㆍ7ㆍ27>', 1061);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8230, '제3조(즉결심판청구)', 1061);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8231, '제3조의2(관할에 대한 특례) 지방법원 또는 그 지원의 판사는 소속 지방법원장의 명령을 받아 소속 법원의 관할사무와 관계없이 즉결심판청구사건을 심판할 수 있다.', 1061);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8232, '제4조(서류ㆍ증거물의 제출) 경찰서장은 즉결심판의 청구와 동시에 즉결심판을 함에 필요한 서류 또는 증거물을 판사에게 제출하여야 한다.', 1061);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8233, '제5조(청구의 기각등)', 1061);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8234, '제6조(심판) 즉결심판의 청구가 있는 때에는 판사는 제5조제1항의 경우를 제외하고 즉시 심판을 하여야 한다.', 1061);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8235, '제7조(개정)', 1061);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8236, '제8조(피고인의 출석) 피고인이 기일에 출석하지 아니한 때에는 이 법 또는 다른 법률에 특별한 규정이 있는 경우를 제외하고는 개정할 수 없다.', 1061);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8237, '제8조의2(불출석심판)', 1061);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8238, '제9조(기일의 심리)', 1061);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8239, '제10조(증거능력) 즉결심판절차에 있어서는 형사소송법 제310조, 제312조제3항 및 제313조의 규정은 적용하지 아니한다. <개정 1991ㆍ11ㆍ22, 2007.12.21>', 1061);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8240, '제11조(즉결심판의 선고)', 1061);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8241, '제12조(즉결심판서)', 1061);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8242, '제13조(즉결심판서등의 보존) 즉결심판의 판결이 확정된 때에는 즉결심판서 및 관계서류와 증거는 관할경찰서 또는 지방해양경찰관서가 이를 보존한다. <개정 1996ㆍ8ㆍ8, 2014.11.19, 2017.7.26>', 1061);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8243, '제14조(정식재판의 청구)', 1061);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8244, '제15조(즉결심판의 실효) 즉결심판은 정식재판의 청구에 의한 판결이 있는 때에는 그 효력을 잃는다.', 1061);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8245, '제16조(즉결심판의 효력) 즉결심판은 정식재판의 청구기간의 경과, 정식재판청구권의 포기 또는 그 청구의 취하에 의하여 확정판결과 동일한 효력이 생긴다. 정식재판청구를 기각하는 재판이 확정된 때에도 같다.', 1061);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8246, '제17조(유치명령등)', 1061);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8247, '제18조(형의 집행)', 1061);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8248, '제19조(형사소송법의 준용) 즉결심판절차에 있어서 이 법에 특별한 규정이 없는 한 그 성질에 반하지 아니한 것은 형사소송법의 규정을 준용한다.', 1061);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8249, '제1조(목적) 이 규칙은 「소년법」(이하 "법"이라 한다)에 따른 소년 보호사건 및 형사사건의 처리에 관하여 필요한 사항을 정함을 목적으로 한다. <개정 2016.11.29>', 1062);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8250, '제2조(결정서)', 1064);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8251, '제3조(결정의 고지와 통지)', 1064);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8252, '제4조(위탁받은 자 등에 대한 결정의 통지)', 1064);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8253, '제5조(통지의 방식) 법 및 이 규칙에 따라 결정을 통지할 때에는 결정 서등본의 송달 그 밖에 적당하다고 인정하는 방식으로 할 수 있다.', 1064);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8254, '제6조(통고의 방식 등)', 1064);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8255, '제7조(소년 보호사건의 송치방식등)', 1064);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8256, '제8조(검사에의 송치방식 등)', 1064);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8257, '제9조(비행사실 등의 고지) 소년부 판사는 소년 보호사건을 접수한 때에는 소년 및 보호자 또는  보조인 중 적당하다고 인정되는 사람에게 다음 각 호의 사항을 서면으로 고지하여야 한다. 다만, 법 제50조에 따라 송치된 소년 보호사건에 있어서는 소년의 비행사실은 이를 고지하지 아니할 수 있다.', 1064);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8258, '제10조(비밀유지의무) 소년 보호사건을 다루는 관계인들은 조사, 심리, 소환 또는 집행 등 사건처리 과정에서 나타나는 소년의 출생, 성장과정, 가족관계 등 사생활의 비밀이 소년 및 타인에게 알려지지 아니하도록 주의를 기울여야 한다.', 1064);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8259, '제11조(조사의 방법)', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8260, '제12조(조사관의 조사보고)', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8261, '제13조(전문가의 진단을 위한 조치) 소년부 판사는 법 제12조에 따른 전문가의 진단을 위하여 필요한 경우에 법 제18조에 따른 임시조치를 하거나 이를 변경할 수 있다.', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8262, '제14조(소환의 방법 등)', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8263, '제15조(위탁소년의 출석)', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8264, '제16조(동행영장의 기재사항 등)', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8265, '제17조(동행영장의 집행지휘)', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8266, '제18조(동행영장의 집행과 집행 후의 처리 등)', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8267, '제19조 삭제 <2008.6.5>', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8268, '제19조의2(국선보조인)', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8269, '제20조(임시조치의 통지) 법 제18조제1항 및 제6항에 따른 결정은 소 년 및 보호자 또는 보조인중 적당하다고 인정되는 사람과 위탁받은 자에게, 법 제18조제3항 단서에 따른 결정은 소년 및 위탁받은 자에게 각 통지하여야 한다.', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8270, '제21조(임시조치 결정의 집행지휘) 법 제18조제5항에 따른 집행지휘는 결정서의 등본을 그 집행담당자에게 교부함으로써 한다.', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8271, '제22조(심리 개시 결정의 취소) 심리 개시 결정은 법 제23조에 따른 심 리가 개시되기 전까지 결정으로써 이를 취소할 수 있다.', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8272, '제23조(조사관 등에 대한 출석요구) 소년부 판사는 심리 기일에 의견 진술을 필요로 하는 조사관 또는 소년분류심사원 및 보호관찰소 소속 공무원 등에게 심리 기일에 출석할 것을 요구할 수 있다.', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8273, '제24조(소년 및 보조인의 출석권)', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8274, '제25조(심리의 방식 및 병합심리 등)', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8275, '제26조(판사 등의 회피)', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8276, '제26조의2(화해권고절차의 회부)', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8277, '제26조의3(화해권고기관) 소년부 판사는 스스로 화해를 권고하거나, 화해의 권고에 관한 사무를 처리하는 사람(이하 "화해권고위원"이라 한다)으로 하여금 화해를 권고하게 할 수 있다.', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8278, '제26조의4(화해권고위원의 위촉과 지정 등)', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8279, '제26조의5(화해권고의 원칙) 소년부 판사와 화해권고위원은 소년과 피해자 또는 지역사회 구성원 등이 사건 해결과정에 자발적으로 참여하여 범죄로 인하여 발생한 피해를 실질적으로 회복하고, 소년의 건전한 사회복귀를 추구할 수 있도록 노력하여야 한다.', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8280, '제26조의6(화해권고기일 등)', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8281, '제26조의7(화해권고기일조서)', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8282, '제26조의8(화해권고절차의 종료)', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8283, '제26조의9(위임규정) 화해권고절차와 관련하여 필요한 사항 중 이 규칙에서 정하고 있지 아니한 사항은 가정법원 및 지방법원 내규로 정한다.', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8284, '제27조(준용규정) 「형사소송규칙」 중 증인신문, 감정, 검증, 압수 또 는 수색에 관한 규정은 소년 보호사건의 성질에 어긋나지 아니하는 한 법 제26조, 법 제27조에 따른 절차에 이를 준용한다.', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8285, '제28조(심리조서)', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8286, '제29조 삭제 <2007.12.31>', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8287, '제30조(결정서 등ㆍ초본의 청구)', 1065);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8288, '제31조(보호처분 결정 등의 고지)', 1066);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8289, '제32조(참고자료의 반환) 법 제32조제5항에 따라 참고자료를 넘겨 받은 소년원, 보호관찰소 이외의 위탁받은 자는 보호처분이 종료 또는 취소된 때에는 즉시 이를 소년부에 반환하여야 한다.', 1066);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8290, '제33조(위탁보호위원의 위촉 등)', 1066);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8291, '제34조(위탁받는 기관 등의 지정)', 1066);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8292, '제35조(장기 보호관찰기간의 연장 신청)', 1066);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8293, '제36조(몰수결정의 집행 등) 몰수결정의 집행, 몰수물의 처분 및 교부 에 관하여는 소년부 판사가 「형사소송법」 중 몰수재판의 집행, 몰수물의 처분 및 교부에 관한 규정에 준하여 행한다.', 1066);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8294, '제37조(보호처분 결정의 집행지휘) 법 제35조에 따른 집행지휘에 관하여는 제21조를 준용한다.', 1066);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8295, '제38조(조사관의 보고방법)', 1066);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8296, '제39조(보호처분ㆍ부가처분의 변경)', 1066);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8297, '제40조(검사에 대한 통지) 소년부 판사가 법 제38조제1항제2호, 법 제51조에 따라 이송결정을 한 때에는 이송받을 법원에 대응하는 검찰청 검사에게 그 결정을 통지하여야 한다.', 1066);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8298, '제41조(송치 또는 이송의 방식) 법 제38조제1항, 법 제49조제2항, 법 제51조에 따라 사건을 송치하거나 이송할 경우에는 제8조제2항을 준용한다.', 1066);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8299, '제42조(10세 미만자에 대한 처분)', 1066);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8300, '제43조(증인 등의 비용) 법 제42조에 따라 증인등에게 지급할 비용에 관하여는 「형사소송비용 등에 관한 법률」 및 「형사소송비용 등에 관한 규칙」을 준용한다.', 1066);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8301, '제44조(항고제기의 방식) 항고장에는 항고의 이유를 간결하게 명시하여야 한다.', 1067);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8302, '제45조(항고의 취하)', 1067);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8303, '제46조(시설에 수용중인 소년의 항고제기 등)', 1067);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8304, '제47조(항고법원의 조사)', 1067);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8305, '제48조(항고법원의 사실조사)', 1067);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8306, '제49조(원결정의 취소와 시설의 장에 대한 통지)', 1067);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8307, '제50조(환송 또는 이송 후의 임시조치) 항고법원으로부터 사건을 환송 또는 이송받은 소년부 판사는 법 제18조에 따른 조치를 할 수 있다. 이 경우에는 제20조와 제21조를 준용한다.', 1067);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8308, '제51조(환송 또는 이송 후의 재판)', 1067);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8309, '제52조(재항고법원의 재판)', 1067);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8310, '제53조(재항고에 관한 준용) 재항고에 관하여는 그 성질에 위반되지 아니하는 한 법의 항고에관한규정 및 이 규칙의 항고에관한규정을 준용한다.', 1067);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8311, '제54조(과태료 통지) 법 제32조의2제3항의 특별교육을 실시하는 기관의 장은 법 제71조제2호의 사유가 있다고 인정할 때에는 지체 없이 과태료에 처할 자의 주소지를 관할하는 가정법원소년부 또는 지방법원소년부에 통지하여야 한다.', 1068);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8312, '제55조(공판기일 지정) 재판장은 소년에 대한 형사사건에 관하여 공소가 제기되면 다른 사건에 우선하여 최대한 빨리 제1회 공판기일을 지정하여야 한다.', 1069);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8313, '제56조(조사의 위촉) 법원은 소년에 대한 형사사건의 심리에 필요하다고 인정하면 조사관에게 다음 각 호의 사항에 관한 조사를 위촉할 수 있다.', 1069);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8314, '제1조(목적) 이 법은 군용물(軍用物) 등에 대한 범죄의 처벌 등에 관한 사항을 규정함을 목적으로 한다.', 1070);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8315, '제2조(적용 범위)', 1070);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8316, '제3조(군용물범죄에 대한 형의 가중)', 1070);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8317, '제4조(군용시설 등에의 침입)', 1070);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8318, '제5조(다른 법률과의 관계) 이 법에 규정된 형보다 무거운 형이 다른 법에 규정되어 있을 때에는 그 무거운 형으로 처벌한다.', 1070);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8319, '제6조(검사의 수사지휘 등)', 1070);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8320, '제1조(목적) 이 규칙은 「도로교통법」 제165조제2항, 경범죄 처벌법 제9조제2항의 규정에 의한 즉결심판청구의 취소절차에 필요한 사항을 규정함을 목적으로 한다. <개정 2009.1.9, 2014.4.3>', 1071);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8321, '제2조(즉결심판청구 취소의 방식)', 1071);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8322, '제3조(즉결심판청구 취소의 효력) 제2조제1항의 규정에 의한 즉결심판청구의 취소가 있으면 그 사건에 관한 즉결심판절차는 취소시에 종료된다.', 1071);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8323, '제1조(검찰청법 일부개정법률의 시행일) 법률 제16908호 검찰청법 일부개정법률은 2021년 1월 1일부터 시행한다.', 1072);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8324, '제2조(형사소송법 일부개정법률의 시행일) 법률 제16924호 형사소송법 일부개정법률은 2021년 1월 1일부터 시행한다. 다만, 제312조제1항의 개정규정은 2022년 1월 1일부터 시행한다.', 1072);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8325, '제1조(목적) 이 법은 부정식품 및 첨가물, 부정의약품 및 부정유독물의 제조나 무면허 의료행위 등의 범죄에 대하여 가중처벌 등을 함으로써 국민보건 향상에 이바지함을 목적으로 한다.', 1073);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8326, '제2조(부정식품 제조 등의 처벌)', 1073);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8327, '제3조(부정의약품 제조 등의 처벌)', 1073);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8328, '제3조의2(재범자의 특수가중) 제2조 또는 제3조의 죄로 형을 받아 그 집행을 종료하거나 면제받은 후 3년 내에 다시 제2조제1항제1호 또는 제3조제1항제1호의 죄를 범한 사람은 사형, 무기 또는 5년 이상의 징역에 처한다.', 1073);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8329, '제4조(부정유독물 제조 등의 처벌)', 1073);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8330, '제5조(부정의료업자의 처벌) 「의료법」 제27조를 위반하여 영리를 목적으로 다음 각 호의 어느 하나에 해당하는 행위를 한 사람은 무기 또는 2년 이상의 징역에 처한다. 이 경우 100만원 이상 1천만원 이하의 벌금을 병과한다.', 1073);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8331, '제6조(양벌규정) 법인의 대표자나 법인 또는 개인의 대리인, 사용인, 그 밖의 종업원이 그 법인 또는 개인의 업무에 관하여 제2조, 제3조, 제4조 및 제5조의 어느 하나에 해당하는 위반행위를 하면 그 행위자를 벌하는 외에 그 법인 또는 개인을 1억원 이하의 벌금에 처한다. 다만, 법인 또는 개인이 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다.', 1073);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8332, '제7조(허가 취소)', 1073);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8333, '제8조(유해 등의 기준) 제2조, 제3조, 제4조 및 제7조 중 "현저히 유해" 및 "현저히 부족"의 기준은 따로 대통령령으로 정한다.', 1073);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8334, '제9조(상금 등)', 1073);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8335, '제10조(적용 범위) 「축산물위생관리법」 제22조, 「주류 면허 등에 관한 법률」 제3조, 「농약관리법」 제3조 및 제8조에 따라 그 제조, 가공 또는 판매에 관하여 허가 또는 면허를 받거나 등록을 하여야 할 축산물, 주류 또는 유독성 농약은 각각 「식품위생법」 또는 「화학물질관리법」에 따른 식품, 유해화학물질의 예에 따라 이 법을 적용한다. <개정 2020.12.29, 2024.2.6>', 1073);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8336, '제1조(목적) 이 영은 보건범죄단속에관한특별조치법(이하 "법"이라 한다)의 시행에 관하여 필요한 사항을 규정함을 목적으로 한다.', 1074);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8337, '제2조(용어의 정의) 이 영에서 "주된 성분"이라 함은 의약품의 효능에 직접적인 영향을 미치는 주약으로서 부약ㆍ부형제 또는 첨가제등이 아닌 것을 말한다.', 1074);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8338, '제3조(특정의약품) 법 제3조제1항제1호의 규정에서 "대통령령으로 정하는 의약품"은 다음 각호의 것을 말한다.', 1074);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8339, '제4조(부정식품의 유해기준)', 1074);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8340, '제5조(부정의약품등의 유해기준등)', 1074);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8341, '제6조(상금의 지급액)', 1074);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8342, '제7조(시행규칙) 이 영 시행에 관하여 필요한 사항은 보건복지부령으로 정한다. <개정 1994.12.23, 2008.2.29, 2010.3.15>', 1074);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8343, '제1조(목적) 이 영은 보건범죄단속에관한특별조치법(이하 "법"이라 한다) 및 동시행령(이하 "영"이라 한다)에서 위임된 사항과 보건복지부장관이 행하는 행정처분 기타 행정상 필요한 사항을 규정함을 목적으로 한다. <개정 2008.3.3, 2010.3.19>', 1075);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8344, '제2조(지정공정서) 영 제5조제1항의 규정에 의하여 보건복지부장관이 지정하는 공정서는 다음 각호의 것을 말한다. <개정 2008.3.3, 2010.3.19>', 1075);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8345, '제3조(최소유효량의 판정) 영 제5조제2항의 규정에 의한 의약품의 "최소유효량"은 국립보건연구원의 검정에 따라 보건복지부장관이 판정한다. <개정 2008.3.3, 2010.3.19>', 1075);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8346, '제4조(현저한 유해등의 판정) 영 제5조의 규정에 의한 "현저한 유해"및 "현저한 부족"의 판정을 위한 검정은 별표에 의한 시공품량을 채취하여 행하여야 한다.', 1075);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8347, '제5조(범죄통보의 처리)', 1075);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8348, '제6조(상금의 청구) 법 제9조의 규정에 의한 상금의 급여신청은 당해사건의 통보자 또는 검거자가 별지 제1호서식에 의한 신청서에 다음 각호의 서류를 첨부하여 보건복지부장관에게 제출하여야 한다. <개정 2008.3.3, 2010.3.19>', 1075);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8349, '제7조(통보인 또는 검거인이 2인이상인 경우의 상금의 지급기준) 통보인 또는 검거인이 2인이상인 경우에는 상금은 등분하여 이를 지급한다.', 1075);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8350, '제8조(지급조서등의 작성) 보건복지부장관은 제6조 및 제7조에 따라 상금을 지급한 때에는 별지 제2호 및 제3호의 서식에 따른 상금지급조서와 지급대장을 작성하여 지급상황을 명확하게 적어 이를 비치해야 한다. <개정 1978.12.7, 2008.3.3, 2010.3.19, 2021.7.7>', 1075);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8351, '제1조(목적) 이 규칙은 「형사사법절차에서의 전자문서 이용 등에 관한 법률」(다음부터 "법"이라 한다)에 따른 법원의 형사사법업무에서의 전자문서 이용ㆍ관리에 관한 사항 및 전산정보처리시스템의 운영 등에 관하여 필요한 사항을 규정함으로써, 적법하고 투명한 절차에 따른 공정하고 신속한 재판을 실현하는 데 이바지함을 목적으로 한다.', 1076);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8352, '제2조(정의)', 1076);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8353, '제3조(전자문서를 제출할 수 있는 자) 법 제5조제1항에 따라 피의자, 피고인, 피해자, 고소인, 고발인, 변호인 이외에 전자소송시스템을 통하여 전자문서를 제출할 수 있는 자는 다음과 같다.', 1076);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8354, '제4조(전자소송의 동의 및 철회)', 1077);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8355, '제5조(사용자등록)', 1077);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8356, '제6조(사용자등록의 철회 등)', 1077);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8357, '제7조(사용자등록의 말소 등)', 1077);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8358, '제8조(전자서명 등)', 1078);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8359, '제9조(전자문서로 작성하지 아니할 수 있는 경우)', 1078);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8360, '제10조(전자문서로 제출할 의무 등)', 1078);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8361, '제11조(전자문서의 작성ㆍ제출)', 1078);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8362, '제12조(전자문서의 파일 형식 등 주의사항)', 1078);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8363, '제13조(멀티미디어 자료의 제출 등)', 1078);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8364, '제14조(전자소송시스템 등을 이용할 수 없는 경우의 제출방법)', 1078);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8365, '제15조(전자문서화)', 1078);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8366, '제16조(전자문서의 접수 등)', 1078);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8367, '제17조(제출된 전자문서 등의 확인)', 1078);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8368, '제18조(제출된 전자문서의 보완)', 1078);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8369, '제19조(조서 등의 폐기 또는 정정)', 1078);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8370, '제20조(전자문서의 반환ㆍ폐기)', 1078);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8371, '제21조(법원사무관등에 의한 전자기록 관리)', 1078);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8372, '제22조(전자적 송부를 받을 기관)', 1079);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8373, '제23조(전자적 송달ㆍ통지를 받을 자)', 1079);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8374, '제24조(전자적 송달ㆍ통지의 방법 등)', 1079);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8375, '제25조(법정에서의 전자문서 송달) 전자소송시스템에 의하여 제출된 소송서류를 법정에서 법 제14조제1항 각 호의 자에게 송달할 필요가 있을 때에는 「민사소송법」 제177조에 의한 방법 이외에 그 제출자로 하여금 해당 전자문서의 요지를 설명하게 하고, 송달받을 자의 요청에 따라 컴퓨터 등 정보처리능력을 갖춘 장치에 의하여 전자문서를 현출한 화면을 이용하여 주요 부분을 즉석에서 열람하는 방법으로 할 수 있다.', 1079);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8376, '제26조(기간의 계산)', 1079);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8377, '제27조(출력서면의 송달 등)', 1079);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8378, '제28조(전자기록의 열람 등)', 1080);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8379, '제29조(전자기록의 열람 등에 따른 수수료)', 1080);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8380, '제30조(전자문서에 의한 변론 등의 방법)', 1081);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8381, '제31조(전자문서에 대한 증거신청 등)', 1081);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8382, '제32조(문자등 정보에 대한 증거조사)', 1081);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8383, '제33조(음성ㆍ영상등 정보에 대한 증거조사)', 1081);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8384, '제34조(전자문서 등을 이용한 신문ㆍ설명)', 1081);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8385, '제35조(공무소등에 대한 조회의 특칙)', 1081);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8386, '제36조(영장등의 전자적 제시 또는 전송)', 1082);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8387, '제37조(영장등을 출력한 서면의 집행)', 1082);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8388, '제38조(영장등의 사본 교부)', 1082);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8389, '제39조(보호사건의 집행지휘 방식에 관한 특례)', 1082);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8390, '제40조(전자문서의 이용ㆍ관리)', 1083);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8391, '제41조(전자소송시스템의 운영)', 1083);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8392, '제42조(전자문서 보관ㆍ폐기에 관한 특칙)', 1083);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8393, '제1조(목적) 이 법은 군수형자의 교정ㆍ교화와 건전한 사회복귀를 도모하고, 군수용자의 처우와 권리 및 군교정시설의 운영에 필요한 사항을 규정함을 목적으로 한다.', 1084);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8394, '제2조(용어의 정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다.', 1084);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8395, '제3조(적용 범위) 이 법은 군교정시설의 구내와 군교도관(이하 "교도관"이라 한다)이 군수용자를 계호하고 있는 그 밖의 장소로서 교도관의 통제가 필요한 공간에 대하여 적용한다.', 1084);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8396, '제4조(군교정시설의 설치 등)', 1084);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8397, '제5조(인권의 존중) 이 법을 집행할 때 군수용자의 인권을 최대한 존중하여야 한다.', 1084);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8398, '제6조(차별금지) 군수용자는 합리적인 이유 없이 성별, 종교, 장애, 나이, 사회적 신분, 출신지역, 용모 등 신체조건, 병력(病歷), 혼인 여부, 정치적 의견 및 성적(性的) 지향 등을 이유로 차별받지 아니한다.', 1084);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8399, '제7조(군교정시설의 순회점검) 국방부장관은 군교정시설의 운영, 교도관의 복무, 군수용자의 처우 및 인권 실태 등을 파악하기 위하여 매년 한 번 이상 군교정시설을 순회점검하거나 소속 공무원으로 하여금 순회점검하게 하여야 한다. <개정 2014.5.20>', 1084);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8400, '제8조(군교정시설의 시찰 및 참관)', 1084);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8401, '제9조(교도관의 직무) 이 법에서 규정한 사항 외에 교도관의 직무에 관하여는 국방부령으로 정한다.', 1084);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8402, '제10조(구분수용) 군수용자는 다음 각 호에 따라 구분하여 수용한다.', 1086);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8403, '제11조(구분수용의 예외)', 1086);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8404, '제12조(분리수용)', 1086);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8405, '제13조(독거수용)', 1086);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8406, '제14조(혼거수용)', 1086);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8407, '제15조(신입자의 수용 등)', 1086);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8408, '제16조(감염병환자의 수용)', 1086);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8409, '제17조(고지사항) 소장은 교도관으로 하여금 신입자와 다른 군교정시설에서 이송되어 온 사람에게 말이나 글로 다음 각 호의 사항을 알려주도록 하여야 한다.', 1086);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8410, '제18조(사진촬영 등)', 1086);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8411, '제19조(군수용자의 이송) 소장은 군수용자의 수용ㆍ작업ㆍ교화ㆍ의료, 그 밖의 처우를 위하여 필요하거나 시설이 부족하거나 시설의 안전과 질서유지를 위하여 필요하다고 인정하면 국방부장관의 승인을 받아 군수용자를 다른 군교정시설로 이송할 수 있다. <개정 2014.5.20>', 1086);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8412, '제20조(군수용자의 일반교도소 등으로의 이송)', 1086);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8413, '제21조(수용사실의 가족 통지) 소장은 신입자나 다른 군교정시설에서 이송되어 온 사람이 있으면 그 사실을 군수용자의 가족(배우자, 직계 존속ㆍ비속 또는 형제자매를 말한다. 이하 같다)에게 지체 없이 통지하여야 한다. 다만, 군수용자가 통지를 원하지 아니하면 그러하지 아니하다.', 1086);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8414, '제22조(의류 및 침구 등의 지급)', 1087);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8415, '제23조(음식물의 지급)', 1087);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8416, '제24조(물품의 자비구매)', 1087);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8417, '제25조(휴대금품의 영치 등)', 1088);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8418, '제26조(군수용자의 물품 소지 등)', 1088);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8419, '제27조(군수용자에 대한 금품 교부)', 1088);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8420, '제28조(유류금품의 교부)', 1088);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8421, '제29조(영치금품의 사용허가) 소장은 군수용자가 영치금품으로 부모ㆍ배우자 또는 자녀의 생계부조, 그 밖의 정당한 용도에 사용할 것을 신청하면 대통령령으로 정하는 기준과 절차에 따라 허가할 수 있다.', 1088);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8422, '제30조(영치금품의 반환) 군수용자의 영치금품은 석방할 때 본인에게 돌려주어야 한다.', 1088);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8423, '제31조(위생ㆍ의료 조치의무) 소장은 군수용자가 건강한 생활을 하는 데에 필요한 위생상 및 의료상 적절한 조치를 하여야 한다.', 1089);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8424, '제32조(청결 유지) 소장은 군수용자가 사용하는 모든 설비와 기구가 항상 청결하게 유지되도록 하여야 한다.', 1089);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8425, '제33조(청결의무)', 1089);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8426, '제34조(운동 및 목욕)', 1089);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8427, '제35조(건강검진)', 1089);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8428, '제36조(감염병 등에 관한 조치)', 1089);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8429, '제37조(부상자 등 치료) 소장은 군수용자가 부상을 당하거나 질병에 걸리면 적절한 치료를 받도록 하여야 하고, 그 밖에 대통령령으로 정하는 바에 따라 필요한 조치를 할 수 있다.', 1089);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8430, '제38조(군병원 및 외부의료시설 진료 등)', 1089);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8431, '제39조(자비치료) 소장은 군수용자가 자신의 비용으로 외부의료시설에서 근무하는 의사(이하 "외부의사"라 한다)에게 치료받기를 원하면 군의관의 의견을 참고하여 치료를 허가할 수 있다.', 1089);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8432, '제40조(진료환경 등)', 1089);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8433, '제41조(군수용자의 의사에 반하는 의료조치)', 1089);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8434, '제42조(접견)', 1090);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8435, '제43조(접견의 중지 등) 교도관은 접견 중인 군수용자나 그 상대방이 다음 각 호의 어느 하나에 해당하면 접견을 중지할 수 있다.', 1090);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8436, '제44조(서신수수)', 1090);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8437, '제45조(전화통화)', 1090);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8438, '제46조(종교행사의 참석 등)', 1091);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8439, '제47조(도서비치 및 이용) 소장은 군수용자의 지식 함양과 교양 습득에 필요한 도서를 갖추어 두고 군수용자가 이용할 수 있도록 하여야 한다.', 1091);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8440, '제48조(신문 등의 구독)', 1091);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8441, '제49조(라디오 청취와 텔레비전 시청)', 1091);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8442, '제50조(집필)', 1091);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8443, '제51조(군수형자 처우의 원칙)', 1093);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8444, '제52조(외부전문가의 상담 등) 소장은 군수형자의 교화나 건전한 사회복귀를 위하여 필요하면 교육학, 교정학, 범죄학, 사회학, 심리학, 의학 등에 관한 학식 또는 교정에 관한 경험이 풍부한 외부전문가로 하여금 군수형자에 대한 상담ㆍ심리치료 또는 생활지도 등을 하게 할 수 있다.', 1093);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8445, '제53조(교육)', 1094);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8446, '제54조(교화프로그램)', 1094);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8447, '제55조(작업의 부과)', 1095);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8448, '제56조(작업의무) 군수형자는 자신에게 부과된 작업과 그 밖의 노역을 수행하여야 할 의무가 있다.', 1095);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8449, '제57조(신청에 따른 작업) 소장은 금고형이나 구류형의 집행 중에 있는 사람에 대하여는 신청에 따라 작업을 부과할 수 있다.', 1095);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8450, '제58조(외부 통근 작업 등)', 1095);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8451, '제59조(직업능력개발훈련)', 1095);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8452, '제60조(집중근로에 따른 처우)', 1095);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8453, '제61조(휴일의 작업) 공휴일, 토요일과 그 밖에 대통령령으로 정하는 휴일에는 작업을 부과하지 아니한다. 다만, 취사, 청소, 간호, 그 밖에 특별히 필요한 작업은 그러하지 아니하다.', 1095);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8454, '제62조(작업의 면제)', 1095);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8455, '제63조(작업수입 등)', 1095);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8456, '제64조(위로금ㆍ조위금)', 1095);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8457, '제65조(다른 보상ㆍ배상과의 관계) 제64조에 따른 위로금이나 조위금을 받을 사람이 국가로부터 동일한 사유로 「민법」이나 그 밖의 법령에 따라 해당 위로금이나 조위금에 상당하는 금액을 받았을 때에는 그 금액은 위로금이나 조위금으로 지급하지 아니한다.', 1095);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8458, '제66조(귀휴)', 1096);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8459, '제67조(귀휴의 취소) 소장은 귀휴 중인 군수형자가 다음 각 호의 어느 하나에 해당하면 귀휴를 취소할 수 있다.', 1096);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8460, '제68조(군미결수용자 처우의 원칙) 군미결수용자는 무죄의 추정을 받으며 그에 합당한 처우를 받는다.', 1097);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8461, '제69조(참관 금지) 군판사, 군검사, 소장, 교도관 및 교도병(군교정시설에서 교도관의 업무를 보조하는 병을 말한다. 이하 같다)이 아닌 사람은 군미결수용자가 수용된 거실은 참관할 수 없다. <개정 2016.1.6>', 1097);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8462, '제70조(분리수용) 소장은 군미결수용자로서 사건에 서로 관련이 있는 사람은 분리수용하고 서로 간의 접촉을 금지하여야 한다.', 1097);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8463, '제71조(군복 착용 등)', 1097);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8464, '제72조(이발) 군미결수용자의 머리나 수염은 특별히 필요한 경우가 아니면 본인의 의사에 반하여 짧게 깎지 못한다. 다만, 군인이나 군무원인 군미결수용자의 머리나 수염에 관하여는 일반 군인이나 군무원에 준하여 깎도록 할 수 있다.', 1097);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8465, '제73조(변호인과의 접견 및 서신수수)', 1097);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8466, '제74조(조사 등에서의 특칙) 소장은 군미결수용자가 징벌대상자로서 조사받고 있거나 징벌 집행 중인 경우에도 소송서류의 작성, 변호인과의 접견ㆍ서신수수, 그 밖의 수사 및 재판 과정에서의 권리행사를 보장하여야 한다.', 1097);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8467, '제75조(작업과 교화)', 1097);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8468, '제76조(준용규정) 형사사건으로 수사 또는 재판을 받고 있는 군수형자와 사형확정자에 대하여는 제73조 및 제74조를 준용한다.', 1097);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8469, '제77조(사형확정자의 수용과 심리상담 등)', 1098);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8470, '제78조(공휴일 등의 사형 집행 금지) 공휴일과 토요일에는 사형을 집행하지 아니한다.', 1098);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8471, '제79조(금지물품) 군수용자는 다음 각 호의 물품을 소지하여서는 아니 된다.', 1099);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8472, '제80조(신체검사 등)', 1099);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8473, '제81조(전자장비를 이용한 계호)', 1099);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8474, '제82조(보호실 수용)', 1099);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8475, '제83조(진정실 수용)', 1099);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8476, '제84조(보호장비의 사용)', 1099);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8477, '제85조(보호장비의 종류 및 사용요건)', 1099);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8478, '제86조(보호장비의 남용 금지)', 1099);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8479, '제87조(강제력의 행사)', 1099);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8480, '제88조(무기의 사용)', 1099);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8481, '제89조(재난 시의 조치)', 1099);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8482, '제90조(수용을 위한 체포)', 1099);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8483, '제91조(규율 등)', 1100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8484, '제92조(포상) 소장은 군수용자가 다음 각 호의 어느 하나에 해당하면 국방부령으로 정하는 바에 따라 포상할 수 있다.', 1100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8485, '제93조(징벌) 소장은 군수용자가 다음 각 호의 어느 하나에 해당하는 행위를 하면 제97조에 따른 징벌위원회의 의결에 따라 징벌을 부과할 수 있다.', 1100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8486, '제94조(징벌의 종류) 징벌의 종류는 다음 각 호와 같다.', 1100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8487, '제95조(징벌의 부과)', 1100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8488, '제96조(징벌대상자의 조사)', 1100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8489, '제97조(징벌위원회)', 1100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8490, '제98조(징벌의 집행)', 1100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8491, '제99조(징벌 집행의 정지ㆍ면제)', 1100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8492, '제100조(징벌 집행의 유예 등)', 1100);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8493, '제101조(소장 면담)', 1101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8494, '제102조(청원)', 1101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8495, '제103조(불이익처우 금지) 군수용자는 청원, 진정, 소장과의 면담, 그 밖에 권리구제를 위한 행위를 하였다는 이유로 불리한 처우를 받지 아니한다.', 1101);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8496, '제104조(가석방심사위원회) 「형법」 제72조에 따른 가석방의 적격 여부를 심사하기 위하여 교도소에 가석방심사위원회(이하 이 장에서 "위원회"라 한다)를 둔다.', 1103);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8497, '제105조(위원회의 구성)', 1103);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8498, '제106조(가석방 적격심사)', 1103);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8499, '제107조(가석방 허가)', 1103);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8500, '제108조(석방) 군수용자의 석방은 사면(赦免)이나 형기 종료 또는 권한 있는 사람의 명령에 따라 소장이 한다.', 1104);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8501, '제109조(석방시기)', 1104);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8502, '제110조(석방된 사람의 일시 수용) 소장은 석방된 사람이 질병이나 그 밖에 피할 수 없는 사정으로 귀가하기 어려울 때 본인이 신청하면 일시적으로 군교정시설에 수용할 수 있다.', 1104);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8503, '제111조(귀가 여비 등의 대여) 소장은 석방된 사람에게 귀가에 필요한 여비나 의류가 없으면 빌려줄 수 있다.', 1104);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8504, '제112조(검시 및 사망 통지) 소장은 군수용자가 사망하였을 때에는 즉시 그 시신을 검시하고, 사망 사실을 사망한 사람의 가족(가족이 없을 때에는 다른 친족을 말한다)에게 통지하여야 한다.', 1105);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8505, '제113조(시신의 인도 등)', 1105);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8506, '제114조(교정위원)', 1106);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8507, '제115조(기부금품의 접수)', 1106);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8508, '제115조의2(권한의 위임) 이 법에 따른 국방부장관의 권한은 대통령령으로 정하는 바에 따라 그 일부를 각 군의 참모총장 또는 국방부장관 소속 기관의 장에게 위임할 수 있다.', 1106);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8509, '제115조의3(벌칙 적용에서 공무원 의제) 징벌위원회 또는 가석방심사위원회의 위원 중 공무원이 아닌 사람은 「형법」 제127조 및 제129조부터 제132조까지의 규정을 적용할 때에는 공무원으로 본다.', 1106);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8510, '제116조(주류의 반입 등)', 1107);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8511, '제117조(출석의무의 위반 등) 다음 각 호의 어느 하나에 해당하는 행위를 한 군수용자는 1년 이하의 징역에 처한다. <개정 2020.2.4>', 1107);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8512, '제1조(목적) 이 영은 「군에서의 형의 집행 및 군수용자의 처우에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 1108);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8513, '제2조(군미결수용실의 설치) 「군에서의 형의 집행 및 군수용자의 처우에 관한 법률」(이하 "법"이라 한다) 제4조제2항에서 "대통령령으로 정하는 부대"란 장성급(將星級) 장교 또는 2급 이상 군무원이 지휘하는 부대를 말한다. <개정 2017.9.5, 2019.11.26>', 1108);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8514, '제3조(군판사 등의 시찰)', 1108);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8515, '제4조(참관)', 1108);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8516, '제5조(수용거실의 설치) 군교정시설의 수용거실(이하 "거실"이라 한다)은 법 제13조에 따라 군수용자를 수용할 수 있도록 독거실(獨居室)과 혼거실(混居室)을 적정 비율로 설치하여야 한다.', 1110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8517, '제6조(독거수용의 구분) 법 제13조에 따른 독거수용은 다음 각 호의 구분에 따른다.', 1110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8518, '제7조(계호독거자의 시찰)', 1110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8519, '제8조(여성 군수용자의 시찰) 소장은 여성 군수용자의 생명과 신체의 보호 또는 군교정시설의 안전과 질서유지를 위하여 특히 필요하다고 인정하는 경우가 아니면 야간에 남성 군교도관이 여성 군수용자가 있는 거실을 시찰하게 해서는 아니 된다.', 1110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8520, '제9조(혼거수용 인원의 기준) 법 제14조에 따른 혼거수용 인원은 3명 이상으로 한다. 다만, 요양이나 교화, 그 밖에 부득이한 사정이 있는 경우에는 2명으로 할 수 있다.', 1110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8521, '제10조(혼거수용의 제한) 소장은 노역장 유치명령을 받은 군수형자와 징역ㆍ금고 또는 구류의 형이 확정된 군수형자를 혼거수용해서는 아니 된다. 다만, 징역ㆍ금고 또는 구류의 형 집행을 마친 군수형자에 대한 노역장 유치명령을 집행하는 경우나, 수용시설이 부족한 경우 등 부득이한 사정이 있는 경우에는 그러하지 아니하다.', 1110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8522, '제11조(군수용자의 자리 지정) 소장은 군수용자의 생명과 신체의 보호, 증거인멸의 방지 및 군교정시설의 안전과 질서유지를 위하여 필요하다고 인정하면 거실, 교육실, 강당, 작업장, 그 밖에 군수용자들이 서로 접촉할 수 있는 장소에서 군수용자의 자리를 지정할 수 있다.', 1110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8523, '제12조(거실의 대체 사용 금지) 소장은 거실을 작업장으로 사용해서는 아니 된다. 다만, 군수용자의 심리적 안정, 교정ㆍ교화 또는 사회 적응 능력을 높이기 위하여 필요한 경우에는 그러하지 아니하다.', 1110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8524, '제13조(현황표 등의 부착 등)', 1110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8525, '제14조(신입자 등의 인수)', 1110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8526, '제15조(신입자 등의 신체 등 검사) 소장은 신입자나 이입자를 인수하였을 때에는 즉시 군교도관에게 신입자나 이입자의 신체, 의류 및 휴대품을 검사하게 하여야 한다.', 1110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8527, '제16조(신입자 등의 목욕) 소장은 신입자나 이입자가 질병에 걸렸거나 그 밖에 부득이한 사정이 있는 경우가 아니면 지체 없이 목욕을 하게 하여야 한다.', 1110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8528, '제17조(신입자 등의 건강진단) 소장은 법 제15조제2항에 따라 신입자나 이입자가 수용된 날부터 3일 이내에 건강진단을 실시하여야 한다. 다만, 휴무일이 연속되는 등 부득이한 사정이 있는 경우에는 그러하지 아니하다.', 1110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8529, '제18조(신입자 등의 신체 특징 기록 등)', 1110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8530, '제19조(수용기록부 등의 작성) 소장은 신입자와 이입자를 수용한 날부터 3일 이내에 수용기록부, 군수용자명부 및 형기종료부를 작성하고 필요한 사항을 적어야 한다.', 1110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8531, '제20조(신입자거실 등)', 1110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8532, '제21조(신입자의 신원조사) 소장은 신입자의 신원에 관한 사항을 조사하여 제19조에 따른 수용기록부에 기록하여야 한다.', 1110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8533, '제22조(형 또는 구속의 집행정지 사유의 통보) 소장은 군수용자에 대하여 건강상의 사유로 형의 집행정지나 구속의 집행정지를 할 필요가 있다고 인정하면 군의관의 진단서와 군수용자를 인수할 사람에 대한 확인서류를 첨부하여 군검사에게 통보하여야 한다. 이 경우 기소된 군수용자에 대하여 구속의 집행정지를 할 때에는 군사법원에도 통보하여야 한다. <개정 2022.6.30>', 1110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8534, '제23조(이송 중지) 소장은 군의관으로부터 군수용자의 건강상태가 다른 교정시설로 이송하는 것을 감당하기 어렵다는 보고를 받은 경우에는 이송을 중지하고 그 사실을 이송받을 소장에게 알려야 한다.', 1110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8535, '제24조(차량호송 시 군수용자의 분리) 이송이나 출정(出廷), 그 밖의 사유로 차량을 이용하여 군수용자를 호송하는 경우에는 군수형자와 군미결수용자, 여성 군수용자와 남성 군수용자의 좌석을 지정하는 등의 방법으로 분리하여 서로 접촉하지 못하도록 하여야 한다.', 1110);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8536, '제25조(의류 등의 지급) 소장은 법 제22조제1항에 따라 군수용자에게 의류, 침구, 그 밖의 생활용품(이하 "의류등"이라 한다)을 지급하는 경우에는 다른 사람이 사용한 의류등은 세탁하거나 소독하여 지급하여야 하고, 식기는 청결하게 관리할 수 있는 재질로 된 것으로 지급하여야 한다.', 1111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8537, '제26조(생활기구의 비치)', 1111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8538, '제27조(음식물의 구분) 법 제23조에 따라 군수용자에게 지급하는 음식물은 주식, 부식, 음료와 그 밖의 영양물로 한다.', 1111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8539, '제28조(주식의 지급기준) 군수용자에게 지급하는 주식은 현역 군인에 준하여 지급한다.', 1111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8540, '제29조(특식의 지급) 소장은 국경일이나 그 밖에 이에 준하는 날에는 특별한 음식물을 그 소속 현역 군인에 준하여 지급할 수 있다. <개정 2014.10.28>', 1111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8541, '제30조(환자의 음식물) 소장은 군의관의 의견을 고려하여 환자에게 지급하는 음식물의 종류 또는 정도를 달리 정할 수 있다.', 1111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8542, '제31조(자비구매 허가의 기준) 소장은 법 제24조에 따라 군수용자의 교화나 건전한 사회복귀에 적합하고 군교정시설의 안전이나 질서를 해칠 우려가 없다고 인정되는 음식물과 의류등을 군수용자 자신의 비용으로 구매하도록 허가할 수 있다.', 1111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8543, '제32조(자비구매 의류등의 사용) 소장은 군수용자가 자신의 비용으로 구매한 의류등을 영치(領置)한 후 그 군수용자가 사용하게 할 수 있다.', 1111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8544, '제33조(의류등의 세탁 등)', 1111);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8545, '제34조(휴대품의 사용 등)', 1112);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8546, '제35조(금품의 영치) 군수용자의 현금(자기앞수표를 포함한다. 이하 같다)을 영치하는 경우에는 영치금대장에 금액을 적고, 군수용자의 물품을 영치하는 경우에는 영치품대장에 품목, 수량 및 규격을 적어야 한다.', 1112);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8547, '제36조(귀중품의 보관) 소장은 영치하는 물품이 금, 은, 보석, 유가증권, 도장, 그 밖에 특별히 보관할 필요가 있는 귀중품인 경우에는 잠금장치가 되어 있는 견고한 용기에 넣어 보관하여야 한다.', 1112);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8548, '제37조(영치품 매각대금의 영치) 소장은 군수용자의 신청에 따라 영치품을 팔았을 때에는 판매 비용을 제외한 나머지 대금을 영치할 수 있다.', 1112);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8549, '제38조(소지범위 초과 물품의 처리) 법 제26조제2항 및 제3항에 따른 소지범위를 벗어난 물품의 처분과 폐기에 관하여는 제34조제2항 및 제3항을 준용한다.', 1112);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8550, '제39조(폐기 물품의 기록) 군수용자의 물품을 폐기하였을 때에는 그 품목, 수량, 이유 및 일시를 관계 장부에 기록하여야 한다.', 1112);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8551, '제40조(금품 교부 신청자의 확인) 소장은 법 제27조제1항에 따른 군수용자에 대한 금품 교부를 허가하기 전에 교부를 신청한 사람의 성명, 주소 및 군수용자와의 관계를 확인하여야 한다.', 1112);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8552, '제41조(교부 허가 금품의 검사 등)', 1112);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8553, '제42조(유류금품의 교부 비용) 법 제28조제2항 또는 제3항에 따라 사망자나 도주자의 금품 또는 매각대금을 보내는 데에 드는 비용은 그 교부를 청구한 사람이 부담한다.', 1112);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8554, '제43조(영치금의 사용 등)', 1112);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8555, '제44조(보건ㆍ위생관리계획의 수립 등) 소장은 군수용자의 건강, 계절 및 시설 여건 등을 고려하여 보건ㆍ위생관리계획을 정기적으로 수립하여 시행하여야 한다.', 1113);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8556, '제45조(시설의 청소ㆍ소독)', 1113);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8557, '제46조(청결의무) 군수용자는 법 제33조제1항에 따라 자신이 사용하는 거실, 작업장, 그 밖의 수용시설의 청결을 유지하기 위한 군교도관의 지시에 따라야 한다.', 1113);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8558, '제47조(실외운동) 소장은 법 제34조에 따라 군수용자가 매일(공휴일 및 국방부장관이 정하는 날은 제외한다) 군(軍) 표준일과표에 따른 근무시간에 1시간 이내의 실외운동을 할 수 있도록 하여야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 실외운동을 실시하지 아니할 수 있다.', 1113);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8559, '제48조(목욕 횟수) 소장은 법 제34조에 따라 작업의 특성, 계절, 그 밖의 사정을 고려하여 군수용자의 목욕 횟수를 정하되, 특별한 사정이 없으면 매주 1회 이상이 되도록 한다.', 1113);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8560, '제49조(건강검진 횟수)', 1113);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8561, '제50조(감염병에 관한 조치)', 1113);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8562, '제51조(의료용 거실에의 수용 등)', 1113);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8563, '제52조(외부의료시설 진료 등)', 1113);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8564, '제53조(접견)', 1114);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8565, '제54조(접견의 예외)', 1114);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8566, '제55조(접견 시 유의사항 고지) 소장은 법 제42조에 따라 접견하게 하는 경우에는 군수용자와 그 상대방에게 접견할 때의 유의사항을 방송이나 게시물 부착 등의 적절한 방법으로 알려주어야 한다.', 1114);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8567, '제56조(접견내용의 청취 등)', 1114);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8568, '제57조(접견기록물의 관리 등)', 1114);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8569, '제58조(접견 중지 사유의 고지) 군교도관이 법 제43조에 따라 군수용자의 접견을 중지하였을 때에는 그 사유를 즉시 알려주어야 한다.', 1114);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8570, '제59조(서신수수의 횟수) 군수용자가 법 제44조에 따라 보내거나 받을 수 있는 서신의 횟수는 제한하지 아니한다.', 1114);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8571, '제60조(서신 내용물의 확인)', 1114);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8572, '제61조(서신 내용의 검열)', 1114);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8573, '제62조(관계 기관 송부문서) 소장은 군사법원, 군사경찰부대, 그 밖의 관계 기관에서 군수용자에게 보내온 문서는 다른 법령에 특별한 규정이 없으면 열람한 후 본인에게 전달하여야 한다. <개정 2020.2.4>', 1114);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8574, '제63조(서신 등의 대서) 소장은 군수용자가 서신, 소송서류, 그 밖의 문서를 스스로 작성할 수 없어 대신 써 달라고 요청하는 경우에는 군교도관으로 하여금 대신 쓰게 할 수 있다.', 1114);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8575, '제64조(서신 등 발송비용의 부담) 군수용자의 서신, 소송서류, 그 밖의 문서를 보내는 데에 드는 비용은 군수용자가 부담한다. 다만, 소장은 군수용자가 그 비용을 부담할 수 없는 경우에는 예산의 범위에서 해당 비용을 부담할 수 있다. <개정 2014.10.28>', 1114);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8576, '제65조(전화통화의 허가 범위)', 1114);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8577, '제66조(전화통화 시간)', 1114);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8578, '제67조(통화내용의 청취ㆍ녹음)', 1114);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8579, '제68조(통화요금의 부담)', 1114);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8580, '제69조(준용) 전화통화 시 외국어의 사용 및 전화통화의 중지에 관하여는 제56조제2항 및 제58조를 준용한다.', 1114);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8581, '제70조(참고사항의 기록) 군교도관은 군수용자의 접견, 서신수수, 전화통화 등의 과정에서 군수용자의 처우에 특히 참고할 사항을 알게 된 경우에는 그 요지를 수용기록부에 기록하여야 한다.', 1114);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8582, '제71조(비치도서의 이용)', 1115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8583, '제72조(라디오 청취 등의 방법) 법 제49조제1항에 따른 군수용자의 라디오 청취와 텔레비전 시청은 군교정시설에 설치된 방송설비를 통하여 할 수 있다.', 1115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8584, '제73조(집필용구의 관리 등)', 1115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8585, '제74조(집필의 시간 등)', 1115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8586, '제75조(문서ㆍ도화의 외부 발송 등)', 1115);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8587, '제76조(군수형자로서의 처우 개시)', 1117);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8588, '제77조(군수형자의 처우등급 부여 등)', 1117);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8589, '제78조(군수형자 취업알선 등) 소장은 군수형자의 건전한 사회복귀를 지원하기 위하여 취업알선 및 창업지원을 위해 노력하여야 한다.', 1117);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8590, '제79조(교육)', 1118);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8591, '제80조(정서교육) 소장은 군수형자의 정서 함양을 위하여 필요하다고 인정하면 연극ㆍ영화관람, 체육행사, 그 밖의 문화예술활동을 하게 할 수 있다.', 1118);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8592, '제81조(작업)', 1119);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8593, '제82조(작업실적의 확인) 소장은 군교도관에게 매일 군수형자의 작업실적을 확인하게 하여야 한다.', 1119);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8594, '제83조(신청 작업의 취소) 소장은 법 제57조에 따라 작업이 부과된 군수형자가 작업의 취소를 요청하는 경우에는 그 군수형자의 의사(意思), 건강 및 군교도관의 의견 등을 고려하여 작업을 취소할 수 있다.', 1119);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8595, '제84조(직업능력개발훈련 설비 등의 구비) 소장은 법 제59조에 따른 직업능력개발훈련을 하는 경우에는 그에 필요한 설비 및 실습 자재를 갖추어야 한다.', 1119);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8596, '제85조(휴업일) 법 제60조제1항 및 제61조에서 "대통령령으로 정하는 휴일"이란 12월 31일, 「각종 기념일 등에 관한 규정」에 따른 교정의 날 및 소장이 지정하는 날을 말한다.', 1119);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8597, '제86조(귀휴자에 대한 조치)', 1120);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8598, '제87조(법률구조 지원) 소장은 군미결수용자가 빈곤하거나 무지하여 수사나 재판 과정에서 권리를 충분히 행사하지 못한다고 인정하는 경우에는 법률구조에 필요한 지원을 할 수 있다.', 1121);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8599, '제88조(공범 분리) 소장은 이송이나 출정, 그 밖의 사유로 군미결수용자를 군교정시설 밖으로 호송하는 경우에는 해당 사건에 관련된 사람과 호송 차량의 좌석을 분리하는 등의 방법으로 서로 접촉하지 못하게 하여야 한다.', 1121);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8600, '제89조(접견 횟수) 군미결수용자의 접견 횟수는 매일 1회로 한다. 이 경우 변호인과의 접견은 그 횟수에 포함하지 아니한다.', 1121);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8601, '제90조(접견의 예외) 소장은 군미결수용자의 처우를 위하여 특히 필요하다고 인정하면 제53조제1항ㆍ제2항ㆍ제4항 및 제89조에도 불구하고 접견시간 외의 시간에도 접견하게 할 수 있고, 접견시간을 연장하거나 접견 횟수를 늘릴 수 있으며, 접견실 외의 장소에서 접견하게 할 수 있다.', 1121);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8602, '제91조(교육ㆍ교화와 작업)', 1121);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8603, '제92조(도주 등 통보) 소장은 군미결수용자가 도주하거나 도주한 군미결수용자를 체포한 경우에는 그 사실을 즉시 군검사에게 통보하여야 한다. 이 경우 군미결수용자가 기소된 때에는 군사법원에도 통보하여야 한다. <개정 2022.6.30>', 1121);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8604, '제93조(사망 등 통보) 소장은 군미결수용자가 위독하거나 사망한 경우에는 그 사실을 즉시 군검사에게 통보하여야 한다. 이 경우 군미결수용자가 기소된 때에는 군사법원에도 통보하여야 한다. <개정 2022.6.30>', 1121);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8605, '제94조(군의관이나 외부의사의 진찰 등) 군미결수용자가 「군사법원법」 제63조, 제129조 및 제246조에 따라 군의관이나 외부의사에게 진료를 받을 때에는 군교도관이 참여하여 그 경과를 제19조에 따른 수용기록부에 기록하여야 한다.', 1121);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8606, '제95조(접견 횟수) 사형확정자의 접견 횟수는 매월 4회로 한다.', 1122);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8607, '제96조(접견의 예외) 소장은 사형확정자의 교화나 심리적 안정을 도모하기 위하여 특히 필요하다고 인정하면 제53조제1항ㆍ제2항ㆍ제4항 및 제95조에도 불구하고 접견시간 외의 시간에도 접견을 하게 할 수 있고, 접견시간을 연장하거나 접견 횟수를 늘릴 수 있으며, 접견실 외의 장소에서 접견하게 할 수 있다.', 1122);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8608, '제97조(사형 집행 후의 검시 등)', 1122);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8609, '제98조(거실등에 대한 검사) 소장은 법 제80조에 따라 군교도관에게 거실등을 정기적으로 검사하게 하여야 한다. 다만, 법 제79조의 금지물품을 숨기고 있다고 의심되는 군수용자의 거실등은 수시로 검사하게 할 수 있다.', 1123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8610, '제99조(신체 등에 대한 검사) 소장은 법 제80조에 따라 군교도관에게 작업장이나 실외에서 거실로 돌아오는 군수용자의 신체, 의류 및 휴대품을 검사하게 하여야 한다. 다만, 교정성적 등을 고려하여 그 검사가 필요하지 아니하다고 인정되는 경우에는 예외로 할 수 있다.', 1123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8611, '제100조(검사장비의 이용) 군교도관은 법 제80조에 따른 검사를 위하여 탐지견(探知犬), 금속탐지기, 그 밖의 장비를 이용할 수 있다.', 1123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8612, '제101조(외부인의 출입) 군교도관 외의 사람은 군 표준일과표에 따른 근무시간 외에는 소장의 허가 없이 군교정시설에 출입하지 못한다.', 1123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8613, '제102조(외부와의 차단)', 1123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8614, '제103조(거실의 개방 금지) 군교도관은 수사, 재판, 운동, 접견, 진료 등 군수용자의 처우를 위한 경우나 자살방지, 화재진압 등 군교정시설의 안전과 질서유지를 위하여 필요한 경우가 아니면 거실문을 열거나 군수용자를 거실 밖으로 나오게 해서는 아니 된다.', 1123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8615, '제104조(장애물 방치 금지) 군교정시설의 구내에는 시야를 가리거나 그 밖에 계호상 장애가 되는 물건을 두어서는 아니 된다.', 1123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8616, '제105조(보호실 등 수용 중지)', 1123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8617, '제106조(보호장비의 사용 등)', 1123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8618, '제107조(보호장비 착용 군수용자의 거실 지정) 보호장비를 착용 중인 군수용자는 특별한 사정이 없으면 계호상 독거수용을 하여야 한다.', 1123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8619, '제108조(보호장비 사용의 감독)', 1123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8620, '제109조(강제력의 행사) 군교도관과 교도병은 소장의 명령 없이 법 제87조에 따른 강제력을 행사해서는 아니 된다. 다만, 그 명령을 받을 시간적 여유가 없는 경우에는 강제력을 행사한 후 소장에게 즉시 보고하여야 한다.', 1123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8621, '제110조(무기사용 보고) 군교도관과 교도병은 법 제88조에 따라 무기를 사용하였을 때에는 즉시 소장에게 보고하여야 하고, 보고를 받은 소장은 그 사실을 국방부장관에게 즉시 보고하여야 한다.', 1123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8622, '제111조(재난 시의 조치)', 1123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8623, '제112조(도주 등에 따른 조치)', 1123);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8624, '제113조(징벌위원회 기능) 법 제97조에 따른 징벌위원회(이하 이 장에서 "위원회"라 한다)는 다음 각 호에 관한 사항을 심의ㆍ의결한다.', 1124);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8625, '제114조(징벌위원회 외부 위원)', 1124);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8626, '제115조(위원장의 직무)', 1124);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8627, '제116조(간사)', 1124);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8628, '제117조(수당 등) 위원회의 위원 등에 대해서는 예산의 범위에서 수당, 여비, 그 밖의 필요한 경비를 지급할 수 있다. 다만, 공무원인 위원이 그 소관 업무와 직접적으로 관련되어 위원회에 출석하는 경우에는 그러하지 아니하다.', 1124);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8629, '제118조(운영세칙) 이 영에서 규정한 사항 외에 위원회의 운영에 필요한 사항은 위원회의 의결을 거쳐 위원장이 정한다.', 1124);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8630, '제119조(징벌의 집행)', 1124);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8631, '제120조(징벌 집행의 계속) 법 제94조제4호부터 제14호까지의 징벌 집행 중에 있는 군수용자가 다른 군교정시설로 이송되거나 군사법원 또는 군검찰부 등에 출석하는 경우에도 징벌집행이 계속되는 것으로 본다.', 1124);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8632, '제121조(징벌기간의 계산) 소장은 법 제99조제1항에 따라 징벌 집행을 일시 정지한 경우 그 정지사유가 해소되었을 때에는 지체 없이 징벌 집행을 재개하여야 한다. 이 경우 집행을 정지한 다음 날부터 집행을 재개(再開)한 전날까지의 일수는 징벌기간으로 계산하지 아니한다.', 1124);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8633, '제122조(이송된 사람의 징벌) 군수용자가 이송 중에 징벌 부과의 대상이 되는 행위를 하였거나 다른 군교정시설에서 징벌 부과의 대상이 되는 행위를 한 사실이 이송 후에 발각되었을 때에는 그 군수용자를 인수한 소장이 징벌을 부과한다.', 1124);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8634, '제123조(징벌사항의 기록) 소장은 군수용자의 징벌에 관한 사항을 징벌집행부 및 제19조에 따른 수용기록부에 기록하여야 한다.', 1124);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8635, '제124조(소장 면담)', 1125);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8636, '제125조(순회점검공무원에 대한 청원)', 1125);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8637, '제126조(가석방 허가 신청의 절차) 법 제107조제1항에 따라 가석방 허가를 신청하는 경우에는 다음 각 호의 서류를 첨부하여 군수형자가 소속되어 있거나 소속되었던 군의 법무실장을 거쳐 국방부장관에게 신청하여야 한다. <개정 2014.10.28>', 1127);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8638, '제127조(가석방자 교육 등) 소장은 법 제107조제2항에 따라 가석방을 허가받은 군수형자에 대하여 가석방자 교육을 하고, 가석방자가 지켜야 할 준수사항을 알려주어야 하며, 가석방 증서를 발급한 후 석방하여야 한다.', 1127);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8639, '제128조(석방 예정자에 대한 상담 등) 소장은 군수형자의 건전한 사회복귀를 위하여 필요하다고 인정하면 석방 전 3일 이내의 범위에서 석방 예정자를 별도의 거실에 수용하여 장래에 관한 상담과 지도를 할 수 있다.', 1128);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8640, '제129조(형기 종료 석방 예정자의 사전조사) 소장은 형기 종료로 석방될 군수형자에 대해서는 석방 10일 전까지 석방 후 보호에 관한 사항을 조사하여야 한다.', 1128);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8641, '제130조(석방 예정자의 교정성적 등 통보) 소장은 석방될 군수형자의 보호 및 재범 방지 등을 위하여 필요하다고 인정하면 군수형자의 성격, 교정성적 또는 보호에 관한 의견을 군수형자의 거주지를 관할하는 국가경찰관서나 군수형자를 인수하여 보호할 법인 또는 개인에게 통보할 수 있다. 다만, 법인 또는 개인에게 통보하는 경우에는 해당 군수형자의 동의를 받아야 한다.', 1128);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8642, '제131조(석방된 사람의 보호) 소장은 군수형자를 석방할 때 필요하다고 인정하면 「보호관찰 등에 관한 법률」 제71조에 따른 한국법무보호복지공단에 석방된 사람의 보호를 요청할 수 있다.', 1128);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8643, '제132조(귀가 여비 등의 회수) 소장은 법 제111조에 따라 석방된 사람에게 귀가 여비나 의류를 빌려주었을 때에는 특별한 사유가 없으면 이를 회수하여야 한다.', 1128);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8644, '제133조(사망 통지) 소장은 법 제112조에 따라 군수용자의 사망 사실을 알리는 경우에는 사망 일시, 장소, 사유 및 법 제28조의 유류금품, 법 제63조제2항의 작업장려금, 법 제64조제2항의 조위금에 관한 사항도 같이 알려야 한다.', 1129);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8645, '제134조(사망기록부)', 1129);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8646, '제135조(화장한 유골의 처리)', 1129);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8647, '제136조(임시 매장지의 표지 등)', 1129);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8648, '제137조(교정위원)', 1130);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8649, '제138조(기부금품의 접수 등)', 1130);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8650, '제139조(권한의 위임)', 1130);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8651, '제1조(목적) 이 규칙은 「군에서의 형의 집행 및 군수용자의 처우에 관한 법률」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 1131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8652, '제2조(정의) 이 규칙에서 사용하는 용어의 뜻은 다음과 같다.', 1131);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8653, '제3조(직무의 처리 등)', 1132);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8654, '제4조(응급조치) 군교도관은 천재지변이나 그 밖의 위급한 사태가 발생하였을 때에는 군수용자의 생명과 안전을 위하여 필요한 응급조치를 할 수 있다.', 1132);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8655, '제5조(군교도관에 대한 교육) 소장은 군교도관에게 직무수행에 필요한 교육과 훈련을 하여야 하고, 필요하다고 인정하는 경우에는 다른 기관에 위탁하여 교육을 실시할 수 있다.', 1132);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8656, '제6조(군교도관회의)', 1132);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8657, '제7조(의류의 지급기준)', 1134);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8658, '제8조(침구 그 밖의 생활용품의 지급기준)', 1134);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8659, '제9조(음식물의 지급기준) 법 제23조에 따라 군수용자에게 지급하는 구체적인 음식물의 지급기준은 「군인 급식 규정」에 따른 현역 군인의 급식기준에 따른다. <개정 2014.11.3>', 1134);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8660, '제10조(임산부군수용자에 대한 특칙) 소장은 임산부인 군수용자가 있는 경우 군의관의 의견을 들어 필요한 양의 쌀밥ㆍ죽 등의 주식과 특별히 마련된 부식을 지급할 수 있다.', 1134);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8661, '제11조(자비구매물품의 종류 등)', 1135);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8662, '제12조(구매허가 및 신청제한)', 1135);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8663, '제13조(우선 공급) 소장은 교도작업제품(군교정시설 안에서 군수용자에게 부과된 작업에 따라 생산된 물품을 말한다)으로서 자비구매물품으로 적합한 것은 우선하여 공급할 수 있다.', 1135);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8664, '제14조(제품 검수)', 1135);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8665, '제15조(주요사항 고지 등)', 1135);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8666, '제16조(교부금품의 허가)', 1135);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8667, '제17조(의료설비의 기준)', 1136);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8668, '제18조(비상의료용품 기준)', 1136);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8669, '제19조(종교행사의 종류) 법 제46조에 따른 종교행사의 종류는 다음 각 호와 같다.', 1138);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8670, '제20조(종교행사의 방법)', 1138);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8671, '제21조(종교행사의 참석대상) 군수용자는 자신이 신봉하는 종교행사에 참석할 수 있다. 다만, 소장은 군수용자가 다음 각 호의 어느 하나에 해당하는 경우에는 종교행사의 참석을 제한할 수 있다. <개정 2014.11.3>', 1138);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8672, '제22조(종교상담 등)', 1138);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8673, '제23조(종교물품 등의 개인 소지) 소장은 군수용자의 신앙생활에 필요하다고 인정하는 경우에는 다음 각 호의 어느 하나에 해당하는 경우를 제외하고 외부에서 제작된 휴대용 종교서적 및 성물을 군수용자가 소지하게 할 수 있다.', 1138);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8674, '제24조(구독신청 범위 및 수량) 군수용자가 법 제48조에 따라 구독을 신청할 수 있는 신문ㆍ잡지 또는 도서(이하 이 절에서 "신문등"이라 한다)의 범위와 수량은 군교정시설의 보관범위 및 군수용자의 소지범위에서 신문은 월 3종류 이내로, 도서(잡지를 포함한다)는 월 10권 이내로 한다. 다만, 소장은 군수용자의 지식 함양 및 교양 습득에 특히 필요하다고 인정하는 경우에는 신문등의 신청 수량을 늘릴 수 있다.', 1139);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8675, '제25조(구독허가의 취소) 소장은 신문등을 구독하는 군수용자가 다음 각 호의 어느 하나에 해당하는 경우에는 구독의 허가를 취소할 수 있다.', 1139);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8676, '제26조(소유자 불명 도서) 소장은 소유자 명의가 분명하지 아니한 도서는 회수하여 비치도서로 전환하거나 폐기할 수 있다.', 1139);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8677, '제27조(방송의 기본원칙)', 1140);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8678, '제28조(방송설비)', 1140);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8679, '제29조(방송편성시간) 소장은 군수용자의 건강과 일과시간 등을 고려하여 1일 6시간 이내에서 방송편성시간을 정한다. 다만, 토요일ㆍ공휴일, 작업ㆍ교육실태 및 군수용자의 특성을 고려하여 방송편성시간을 조정할 수 있다.', 1140);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8680, '제30조(방송프로그램)', 1140);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8681, '제31조(군수용자 준수사항 등)', 1140);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8682, '제31조의2(서신검열 등의 대상) 영 제60조제1항제1호 및 영 제61조제1항제4호에서 "마약류사범이나 조직폭력사범 등 국방부령으로 정하는 군수용자"란 다음 각 호의 어느 하나에 해당하는 군수용자를 말한다.', 1141);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8683, '제32조(처우등급 심사기준) 영 제77조에 따라 군수형자에게 부여하는 처우등급은 뉘우친 정도, 품행, 책임감, 작업등급 및 교육ㆍ훈련성적을 기준으로 심사한다.', 1144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8684, '제33조(심사의 종류) 처우등급 심사는 다음 각호와 같이 구분하여 실시한다.', 1144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8685, '제34조(정기심사)', 1144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8686, '제35조(형기의 3분의 1 심사) 형기의 3분의 1 심사는 다음 각 호의 구분에 따라 실시한다.', 1144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8687, '제36조(특별심사)', 1144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8688, '제37조(처우등급) 군수형자의 처우등급은 다음 각 호와 같다.', 1144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8689, '제38조(처우등급의 부여) 군수형자의 처우등급은 제32조에 따른 처우등급 심사기준에 따라 군교도관회의 의결로 결정한다.', 1144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8690, '제39조(처우등급의 변경)', 1144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8691, '제40조(수형태도ㆍ실적 관찰표의 제출) 군교도관은 처우등급 심사일 1주일 전까지 담당하고 있는 군수형자의 수형생활 태도와 작업ㆍ교육 실적을 별지 제1호서식의 수용태도ㆍ실적 관찰표에 기록하여 소장에게 제출하여야 한다.', 1144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8692, '제41조(처우등급심사표의 관리 등)', 1144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8693, '제42조(처우등급 심사의 통지) 소장은 처우등급 심사에 따라 군수형자의 처우등급을 승급시키거나 강등하였을 때에는 그 사실을 해당 군수형자를 담당하는 군교도관에게 알려야 하고, 군교도관은 그 사실을 군수형자에게 알려야 한다.', 1144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8694, '제43조(재수용 군수형자의 처우등급 부여 등)', 1144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8695, '제44조(일반교도소 이송 시 통보사항) 소장은 법 제20조에 따라 군수형자를 일반교도소나 구치소로 이송할 때에는 해당 군수형자의 수형생활 또는 처우 등에 관한 사항을 통보하여야 한다.', 1144);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8696, '제45조(물품 지급) 소장은 군수형자의 처우등급에 따라 물품에 차이를 두어 지급할 수 있다. 다만, 주식ㆍ부식ㆍ음료 그 밖에 건강유지에 필요한 물품은 그러하지 아니하다.', 1145);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8697, '제46조(봉사원 선정)', 1145);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8698, '제47조(자치생활)', 1145);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8699, '제48조(접견) 군수형자의 처우등급별 접견의 허용횟수는 다음 각 호와 같다.', 1145);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8700, '제49조(접견장소) 소장은 처우등급 1급인 군수형자에 대해서는 국방부장관이 정하는 바에 따라 접촉차단시설이 설치된 장소(이하 "접견실"이라 한다) 외의 적당한 곳에서 접견하도록 할 수 있다. 다만, 처우상 특히 필요하다고 인정하는 경우에는 1급의 군수형자 외의 군수형자에 대해서도 이를 허용할 수 있다.', 1145);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8701, '제50조(가족 만남의 날 행사 등)', 1145);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8702, '제51조(전화통화 등)', 1145);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8703, '제52조(교육ㆍ작업 등의 지도 보조) 소장은 처우등급 2급 이상인 군수형자 중에서 교육ㆍ작업 등의 성적이 우수하고 관련 기술이 있는 사람에게 군교도관의 작업 지도를 보조하게 할 수 있다.', 1145);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8704, '제53조(개인작업)', 1145);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8705, '제54조(외부 직업훈련)', 1145);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8706, '제55조(교육대상자 선발 등)', 1147);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8707, '제56조(교육대상자 선발 취소 등)', 1147);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8708, '제57조(교육ㆍ훈련과정) 법 제53조에 따라 군교도소에서 실시하는 교육ㆍ훈련은 다음 각 호의 과정으로 한다.', 1147);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8709, '제58조(검정고시반 설치 및 운영)', 1147);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8710, '제59조(방송통신고등학교 교육과정 설치 및 운영)', 1147);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8711, '제60조(정보화 교육과정 설치 및 운영) 소장은 군수형자에게 지식정보사회에 적응할 수 있는 교육기회를 부여하기 위하여 정보화 교육과정을 설치ㆍ운영할 수 있다.', 1147);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8712, '제61조(군사교육훈련과정)', 1147);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8713, '제62조(교육시간 등) 제57조 각 호에 따른 교육ㆍ훈련과정의 총교육시간, 교육과목, 학급편성 및 교육평가 등에 관한 사항은 국방부조사본부장이 정한다. <개정 2014.11.3>', 1147);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8714, '제63조(교과서 등의 대여 등) 소장은 교육ㆍ훈련과정에 선발된 군수형자에게 교과서, 참고서 그 밖의 학용품을 대여하거나 지급할 수 있다.', 1147);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8715, '제64조(교관) 제57조에 따른 교육ㆍ훈련은 소장이 소속 장교ㆍ준사관ㆍ부사관 및 군무원 중에서 임명한 교관 및 조교가 담당한다.', 1147);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8716, '제65조(교육평가 등)', 1147);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8717, '제66조(상장의 수여) 소장은 각 교육ㆍ훈련과정을 수료한 군수형자 중에서 성적이 우수하여 다른 사람의 모범이 되는 사람에게는 별지 제3호서식의 상장을 수여한다.', 1147);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8718, '제67조(비치서류) 군교도소에는 각 교육ㆍ훈련과정별로 별지 제4호서식의 출석부, 별지 제5호서식의 학적부 및 교안을 작성ㆍ비치하여야 한다.', 1147);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8719, '제68조(교육실시결과의 보고) 소장은 연 1회 교육ㆍ훈련 실시결과를 국방부조사본부장에게 보고하여야 한다. <개정 2014.11.3>', 1147);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8720, '제69조(교화프로그램의 종류) 교화프로그램의 종류는 다음 각 호와 같다.', 1148);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8721, '제70조(문화프로그램) 소장은 군수형자의 인성 함양, 자아존중감 회복 등을 위하여 음악ㆍ미술ㆍ독서ㆍ원예 등 다양한 문화예술관련 프로그램을 도입하거나 개발하여 실시할 수 있다.', 1148);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8722, '제71조(문제행동 예방프로그램) 소장은 군수형자의 죄명ㆍ죄질 등을 구분하여 그에 따른 심리측정ㆍ평가ㆍ진단ㆍ치료 등의 문제행동예방프로그램을 도입하거나 개발하여 실시할 수 있다.', 1148);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8723, '제72조(가족관계 회복프로그램)', 1148);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8724, '제73조(교화상담)', 1148);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8725, '제74조(교화프로그램 운영방법)', 1148);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8726, '제75조(작업의 종류 및 시간)', 1150);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8727, '제76조(작업종류의 변경 금지) 소장은 군수형자에게 일정한 작업을 부과하였을 때에는 특별한 이유가 없는 한 그 작업종류를 변경하여서는 아니 된다.', 1150);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8728, '제77조(작업등급)', 1150);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8729, '제78조(외부통근작업자의 선정기준)', 1150);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8730, '제79조(선정 취소) 소장은 외부통근자가 법령을 위반하는 행위를 하거나 국방부장관 또는 소장이 정하는 준수사항을 위반한 경우에는 외부통근자 선정을 취소할 수 있다.', 1150);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8731, '제80조(외부통근자 교육) 소장은 외부통근자로 선정된 군수형자에게 자치활동, 행동수칙, 안전수칙, 작업기술 및 현장적응훈련에 대한 교육을 실시하여야 한다.', 1150);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8732, '제81조(자치생활) 소장은 외부통근자의 사회 적응 능력을 기르고 원활한 사회복귀를 촉진하기 위하여 필요하다고 인정하는 경우에는 제47조에 따른 자치생활을 하게 할 수 있다.', 1150);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8733, '제82조(작업도구의 파손 등에 대한 변상) 군수형자가 고의 또는 중대한 과실로 작업도구ㆍ원료ㆍ제품 또는 시설물을 파손하거나 잃어버렸을 때에는 그 군수형자에게 지급할 작업장려금으로 이를 변상하게 할 수 있다.', 1150);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8734, '제83조(직업훈련 직종 선정 등)', 1151);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8735, '제84조(직업훈련 대상자 선정기준) 소장은 다음 각 호의 요건을 갖춘 군수형자 중 군수형자의 의사(意思), 적성, 나이 및 학력 등을 고려하여 직업훈련 대상자로 선정할 수 있다.', 1151);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8736, '제85조(직업훈련 대상자 선정의 제한) 소장은 제84조에도 불구하고 군수형자가 다음 각 호의 어느 하나에 해당하는 경우에는 직업훈련 대상자로 선정해서는 아니 된다.', 1151);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8737, '제86조(직업훈련 대상자 이송)', 1151);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8738, '제87조(직업훈련의 보류 및 취소 등)', 1151);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8739, '제88조(귀휴 사유)', 1153);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8740, '제89조(귀휴 심사)', 1153);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8741, '제90조(설치) 법 제66조에 따른 군수형자의 귀휴허가에 관한 심사를 하기 위하여 군교도소에 귀휴심사위원회(이하 이 절에서 "위원회"라 한다)를 둔다.', 1154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8742, '제91조(기능) 위원회는 귀휴심사대상자(이하 이 장에서 "심사대상자"라 한다)에 대하여 다음 각 호의 사항을 심사한다.', 1154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8743, '제92조(구성)', 1154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8744, '제93조(위원의 임기 등)', 1154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8745, '제94조(위원장의 직무)', 1154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8746, '제95조(회의)', 1154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8747, '제96조(간사)', 1154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8748, '제97조(귀휴심사에 필요한 서류)', 1154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8749, '제98조(사실조회 등)', 1154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8750, '제99조(귀휴심사 보고) 소장이 귀휴대상자를 위원회의 심사에 회부한 때에는 그 명부를 작성하여 국방부조사본부장을 거쳐 국방부장관에게 보고하여야 한다. <개정 2014.11.3>', 1154);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8751, '제100조(귀휴허가증 발급 등) 소장은 법 제66조제1항 및 제2항에 따라 귀휴를 허가하였을 때에는 별지 제11호서식의 귀휴허가부에 기록하고 귀휴허가를 받은 군수형자(이하 "귀휴자"라 한다)에게 별지 제12호서식의 귀휴허가증을 발급하여야 한다.', 1155);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8752, '제101조(귀휴조건) 법 제66조제3항에 따라 소장이 귀휴자에게 붙일 수 있는 조건(이하 "귀휴조건"이라 한다)은 다음 각 호와 같다.', 1155);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8753, '제102조(동행귀휴 등)', 1155);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8754, '제103조(귀휴비용 등)', 1155);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8755, '제104조(귀휴조건 위반에 대한 조치)', 1155);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8756, '제105조(번호표 등 표시) 사형확정자의 번호표 및 거실표의 색상은 붉은색으로 한다. 다만, 소장은 사형확정자의 심리적 안정과 원만한 수용생활을 위하여 필요하다고 인정하는 경우에는 이와 달리 시행할 수 있다.', 1156);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8757, '제106조(상담)', 1156);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8758, '제107조(혼거수용 및 작업)', 1156);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8759, '제108조(교화프로그램) 소장은 법 제77조제3항에 따라 사형확정자에 대하여 심리상담, 종교상담, 심리치료 등의 교화프로그램을 실시하는 경우에는 전문가에 의하여 집중적이고 지속적으로 이루어질 수 있도록 계획을 수립ㆍ시행하여야 한다.', 1156);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8760, '제109조(전화통화) 소장은 사형확정자의 심리적 안정과 원만한 수용생활을 위하여 필요하다고 인정하는 경우에는 매월 3회 이내의 범위에서 전화통화를 허가할 수 있다.', 1156);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8761, '제110조(교정장비의 종류) 교정장비의 종류는 다음 각 호와 같다.', 1159);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8762, '제111조(교정장비의 관리)', 1159);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8763, '제112조(교정장비 보유기준 등) 군교정시설별 교정장비의 보유기준 및 관리방법 등에 관하여 필요한 사항은 국방부장관이 정한다.', 1159);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8764, '제113조(전자장비의 종류) 군교도관이 법 제81조에 따라 군수용자 또는 시설을 계호하는 경우에 사용할 수 있는 전자장비는 다음 각 호와 같다.', 1160);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8765, '제114조(중앙통제실의 운영)', 1160);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8766, '제115조(영상정보처리기기 설치)', 1160);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8767, '제116조(거실에 있는 군수용자의 계호)', 1160);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8768, '제117조(전자감지기의 설치) 전자감지기는 군교정시설의 벽둘레ㆍ울타리 그 밖에 군수용자의 도주와 외부로부터의 침입을 방지하기 위하여 필요한 장소에 설치한다. <개정 2020.2.3>', 1160);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8769, '제118조(전자경보기의 사용) 전자경보기는 외부의료시설 입원, 이송ㆍ출정, 그 밖의 사유로 군교정시설 밖에서 군수용자를 계호하는 경우에 보호장비나 군수용자의 팔목 등에 부착하여 사용할 수 있다.', 1160);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8770, '제119조(물품검색기 설치 및 사용)', 1160);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8771, '제120조(증거수집장비의 사용) 군교도관은 군수용자가 사후(事後)에 입증이 필요하다고 인정되는 행위를 하거나 상태에 있는 경우에 군수용자에 대하여 증거수집장비를 사용할 수 있다.', 1160);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8772, '제121조(녹음ㆍ녹화 기록물의 관리) 소장은 전자장비로 녹음ㆍ녹화된 기록물을 「공공기록물 관리에 관한 법률」에 따라 관리하여야 한다.', 1160);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8773, '제122조(보호장비의 종류) 군교도관이 법 제85조제1항에 따라 사용할 수 있는 보호장비의 종류는 다음 각 호와 같다.', 1161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8774, '제123조(보호장비의 규격)', 1161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8775, '제124조(보호장비사용 명령) 소장은 영 제106조제1항에 따라 보호장비 사용을 명령하거나 승인하는 경우에는 보호장비의 종류 및 사용방법을 구체적으로 지정하여야 하며, 이 규칙에서 정한 방법 외의 방법으로 보호장비를 사용하게 하여서는 아니 된다.', 1161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8776, '제125조(수갑의 사용방법)', 1161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8777, '제126조(머리보호장비의 사용방법) 머리보호장비의 사용은 별표 7의 방법으로 한다. 이 경우 군수용자가 머리보호장비를 임의로 해제하지 못하도록 다른 보호장비를 함께 사용할 수 있다.', 1161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8778, '제127조(발목보호장비의 사용방법) 발목보호장비의 사용방법은 다음 각 호와 같다.', 1161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8779, '제128조(보호대의 사용방법) 보호대의 사용방법은 다음 각 호와 같다.', 1161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8780, '제129조(보호의자의 사용방법)', 1161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8781, '제130조(보호침대의 사용방법)', 1161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8782, '제131조(보호복의 사용방법)', 1161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8783, '제132조(포승의 사용방법)', 1161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8784, '제133조(둘 이상의 보호장비 사용) 하나의 보호장비로 사용목적을 달성할 수 없는 경우에는 둘 이상의 보호장비를 사용할 수 있다. 다만, 보호의자 및 보호침대는 다른 보호장비와 같이 사용할 수 없다.', 1161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8785, '제134조(보호장비 사용의 기록) 군교도관은 법 제84조제1항에 따라 보호장비를 사용하는 경우에는 별지 제17호서식의 보호장비사용 심사부에 사용내용을 기록하여야 한다. 다만, 법 제84조제1항제1호에 따라 보호장비를 사용하는 경우에는 호송계획서나 수용기록부의 내용 등으로 기록을 갈음할 수 있다.', 1161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8786, '제135조(군의관의 건강확인 등) 군의관은 법 제84조제3항에 따라 보호장비 착용 군수용자의 건강상태를 확인한 결과 특이사항을 발견한 경우에는 보호장비사용 심사부에 이를 기록하여야 한다.', 1161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8787, '제136조(보호장비의 계속 사용)', 1161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8788, '제137조(보호장비 사용의 해제)', 1161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8789, '제138조(보호장비 착용 군수용자의 관찰 등) 소장은 제122조제5호부터 제7호까지의 보호장비를 사용하거나 제8호의 보호장비를 별표 17의 방법으로 사용하게 하는 경우에는 군교도관으로 하여금 수시로 해당 군수용자의 상태를 확인하고 1시간마다 별지 제18호서식의 보호장비 착용자 관찰부에 확인사항을 기록하게 하여야 한다.', 1161);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8790, '제139조(보안장비의 종류) 군교도관등이 법 제87조에 따라 강제력을 행사하는 경우에 사용할 수 있는 보안장비는 다음 각 호와 같다.', 1162);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8791, '제140조(보안장비의 종류별 사용요건)', 1162);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8792, '제141조(보안장비의 종류별 사용기준) 보안장비의 종류별 사용기준은 다음 각 호와 같다.', 1162);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8793, '제142조(무기의 종류) 군교도관등이 법 제88조에 따라 사용할 수 있는 무기의 종류는 다음 각 호와 같다.', 1163);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8794, '제143조(무기의 종류별 사용요건)', 1163);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8795, '제144조(기관총의 설치 등) 기관총은 대공초소 또는 집중사격을 하기 가장 쉬운 장소에 설치하고, 유사시 즉시 사용할 수 있도록 충분한 인원의 사수(射手)ㆍ부사수ㆍ탄약수를 미리 지정하여야 한다.', 1163);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8796, '제145조(총기의 사용절차) 군교도관등이 총기를 사용하는 경우에는 구두경고, 공포탄 발사, 위협사격, 조준사격의 순서에 따라야 한다. 다만, 상황이 긴급하여 시간적 여유가 없는 경우는 예외로 한다.', 1163);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8797, '제146조(총기 교육 등)', 1163);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8798, '제147조(포상)', 1165);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8799, '제148조(규율) 군수용자가 법 제93조제6호에 따라 시설의 안전과 질서유지를 위하여 해서는 안 될 행위는 다음 각 호와 같다.', 1166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8800, '제149조(징벌사유의 경합) 법 제95조제2항제1호에 따른 징벌의 경중(輕重)은 제150조 각 호의 순서에 따른다. 이 경우 같은 조 제2호부터 제5호까지의 경우에는 각 목의 순서에 따른다.', 1166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8801, '제150조(징벌의 부과기준) 법 제95조제6항에 따른 징벌의 부과기준은 다음 각 호와 같다.', 1166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8802, '제151조(징벌 부과 시 고려사항) 제150조에 따라 징벌을 부과하는 경우에는 다음 각 호의 사항을 고려하여야 한다.', 1166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8803, '제152조(징벌대상자의 조사 시 준수사항) 군교도관이 법 제96조제1항에 따라 징벌사유에 해당하는 행위를 하였다고 의심할 만한 충분한 이유가 있는 군수용자(이하 "징벌대상자"라 한다) 또는 참고인 등을 조사하는 경우에는 다음 각 호의 사항을 준수하여야 한다.', 1166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8804, '제153조(조사기간)', 1166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8805, '제154조(징벌대상자의 처우제한 통지) 소장은 법 제96조제3항에 따라 조사기간 중 접견, 서신수수 또는 전화통화를 제한하는 경우에는 징벌대상자의 가족 등에게 그 사실을 알려야 한다. 다만, 징벌대상자가 원하지 아니하는 경우에는 그러하지 아니하다.', 1166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8806, '제155조(조사의 일시정지)', 1166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8807, '제156조(징벌의결의 요구)', 1166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8808, '제157조(징벌대상자에 대한 출석통지)', 1166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8809, '제158조(징벌위원회의 회의 및 의결)', 1166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8810, '제159조(집행절차) 소장은 징벌을 집행하려면 징벌의결의 내용과 징벌처분에 대한 불복방법을 기록한 별지 제25호서식의 징벌집행통지서에 징벌의결서 부본(副本)을 첨부하여 해당 군수용자에게 전달하여야 한다.', 1166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8811, '제160조(징벌의 집행순서)', 1166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8812, '제161조(징벌의 집행방법)', 1166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8813, '제162조(금치 집행 중 생활용품 등의 별도 보관) 소장은 금치 중인 군수용자가 생활용품 등으로 자살ㆍ자해할 우려가 있거나 군교정시설의 안전과 질서를 해칠 우려가 있는 경우에는 그 물품을 따로 보관하고 필요한 경우에만 이를 사용하게 할 수 있다.', 1166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8814, '제163조(징벌 집행 중인 군수용자의 상담) 소장은 징벌 집행 중인 군수용자에 대하여 군교도관 또는 교정참여인사와의 상담을 실시하여 징벌대상행위의 재발방지에 노력하여야 한다.', 1166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8815, '제164조(양형 참고자료의 통보) 소장은 군미결수용자에게 징벌을 부과하였을 때에는 징벌대상행위 등에 관한 양형 참고자료를 작성하여 관할 군검찰부 검찰관 또는 관할 군사법원에 통보할 수 있다.', 1166);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8816, '제165조(기능) 법 제104조에 따른 가석방심사위원회(이하 이 편에서 "위원회"라 한다)는 법 제106조에 따른 가석방 적격심사와 「형법」 제75조에 따른 가석방의 취소 등에 관한 사항을 심사한다.', 1168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8817, '제166조(위원회의 구성 등)', 1168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8818, '제167조(위원의 임기) 제166조제1항제2호 및 제3호의 위원 임기는 2년으로 한다', 1168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8819, '제168조(위원장의 직무)', 1168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8820, '제169조(회의)', 1168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8821, '제170조(간사와 서기)', 1168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8822, '제171조(회의록의 작성)', 1168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8823, '제172조(수당 등) 위원회의 회의에 출석한 위원에 대해서는 예산의 범위에서 수당과 여비를 지급할 수 있다.', 1168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8824, '제173조(운영세칙) 이 규칙에 규정된 사항 외에 위원회의 운영에 관하여 필요한 사항은 위원회의 의결을 거쳐 위원장이 정한다.', 1168);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8825, '제174조(가석방 적격심사의 기본원칙) 가석방 적격심사는 객관적 자료와 기준에 따라 공정하게 하여야 하며, 심사과정에서 알게 된 비밀은 누설하여서는 아니 된다.', 1169);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8826, '제175조(심사 대상자의 선정)', 1169);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8827, '제176조(사전조사) 소장은 군수형자의 가석방 적격심사를 위하여 다음 각 호의 사항을 미리 조사하여야 한다. 이 경우 특히 필요하다고 인정하면 군수형자, 그 가족, 그 밖의 사람과 면담 등을 할 수 있다.', 1169);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8828, '제177조(사전조사 유의사항) 제176조에 따른 사전조사 중 가석방 적격심사와 관련하여 특히 피해자의 감정 및 합의 여부, 출소시 피해자에 대한 보복성 범죄 가능성 등에 유의하여야 한다.', 1169);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8829, '제178조(사전조사 시기 등)', 1169);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8830, '제179조(심사서류)', 1169);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8831, '제180조(누범자에 대한 심사) 위원회가 같거나 유사한 죄로 2회 이상 징역형 또는 금고형의 집행을 받은 군수형자에 대하여 가석방 적격심사를 할 때에는 뉘우치는 정도, 노동능력 및 의욕, 근면성, 그 밖에 정상적인 업무에 취업할 수 있는 생활계획과 보호관계에 관하여 중점적으로 심사하여야 한다.', 1169);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8832, '제181조(범죄 동기에 대한 심사)', 1169);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8833, '제182조(사회의 감정에 대한 심사) 다음 각 호에 해당하는 군수형자를 심사하는 경우에는 특히 그 범죄에 대한 사회의 감정에 유의하여야 한다.', 1169);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8834, '제183조(군에 대한 피해정도에 관한 심사) 범죄의 수단 및 결과를 심사하는 경우 다음 각 호에 따라 그 범죄에 의한 군의 피해정도에 유의하여야 한다.', 1169);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8835, '제184조(재산범에 대한 심사)', 1169);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8836, '제185조(관계 기관에 대한 조회)', 1169);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8837, '제186조(감정의 촉탁)', 1169);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8838, '제187조(재회부) 소장은 위원회에서 가석방 부적격으로 결정된 군수형자에 대하여 그 후 가석방을 하는 것이 적절하다고 인정하는 경우에는 다시 가석방 적격심사를 위원회에 회부할 수 있다.', 1169);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8839, '제188조(가석방 결정)', 1169);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8840, '제189조(가석방증) 「가석방자관리규정」 제4조제2항에 따른 가석방증은 별지 제31호서식에 따른다.', 1169);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8841, '제190조(가석방의 보고) 소장은 군수형자를 가석방하였을 때에는 국방부장관이 발행한 가석방 허가서가 도착한 날짜와 실제 석방한 날짜를 국방부조사본부장을 거쳐 국방부장관에게 보고하여야 한다. <개정 2014.11.3>', 1169);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8842, '제191조(재복무 대상 가석방자의 보호와 감독) 가석방자 중 군에 다시 복무할 사람에 대한 보호ㆍ감독의 업무는 소속 부대장이 수행한다. 다만, 소속 부대로 복귀할 때까지 가석방자에 대한 보호ㆍ감독업무는 소장이 한다.', 1169);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8843, '제192조(가석방 취소) 가석방자가 가석방 기간 중 「가석방자관리규정」 제5조부터 제7조까지, 제10조, 제13조제1항 및 제14조부터 제16조까지의 규정에서 정한 준수사항을 위반하거나 관할 경찰서장의 명령 또는 조치를 따르지 아니하면 「형법」 제75조에 따라 가석방을 취소할 수 있다.', 1170);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8844, '제193조(가석방 취소의 신청)', 1170);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8845, '제194조(위원회의 심사)', 1170);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8846, '제195조(남은 형의 집행)', 1170);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8847, '제196조(가석방의 실효와 보고) 소장은 형법 제74조에 따라 가석방이 실효된 것을 알았을 때에는 지체 없이 남은 형의 집행에 필요한 조치를 하고, 그 결과를 국방부장관에게 보고하여야 한다.', 1170);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8848, '제197조(추천) 소장이 교정위원을 추천하는 경우에는 별지 32호서식의 교정위원 추천서를 각군의 참모총장 또는 국방부조사본부장에게 제출하여야 한다. 다만, 재위촉의 경우에는 소장의 의견서로 그 제출을 갈음한다. <개정 2014.11.3>', 1171);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8849, '제1조(적용대상자)', 1172);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8850, '제1조의2(장소적 적용범위) 이 법은 제1조에 규정된 사람이 대한민국의 영역 밖에서 이 법에 규정된 죄(제1조제4항의 적용을 받는 사람에 대하여는 같은 항 각 호에 정한 죄만 해당한다)를 범한 경우에도 적용한다.', 1172);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8851, '제2조(용어의 정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다.', 1172);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8852, '제3조(사형 집행) 사형은 소속 군 참모총장이 지정한 장소에서 총살로써 집행한다. <개정 2021.9.24>', 1172);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8853, '제4조(다른 법의 적용례) 제1조에 따른 이 법의 적용대상자가 범한 죄에 관하여 이 법에 특별한 규정이 없으면 다른 법령에서 정하는 바에 따른다.', 1172);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8854, '제5조(반란) 작당(作黨)하여 병기를 휴대하고 반란을 일으킨 사람은 다음 각 호의 구분에 따라 처벌한다.', 1174);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8855, '제6조(반란 목적의 군용물 탈취) 반란을 목적으로 작당하여 병기, 탄약 또는 그 밖에 군용에 공(供)하는 물건을 탈취한 사람은 제5조의 예에 따라 처벌한다.', 1174);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8856, '제7조(미수범) 제5조와 제6조의 미수범은 처벌한다.', 1174);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8857, '제8조(예비, 음모, 선동, 선전)', 1174);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8858, '제9조(반란 불보고)', 1174);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8859, '제10조(동맹국에 대한 행위) 이 장의 규정은 대한민국의 동맹국에 대한 행위에도 적용한다.', 1174);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8860, '제11조(군대 및 군용시설 제공)', 1175);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8861, '제12조(군용시설 등 파괴) 적을 위하여 제11조에 규정된 군용시설 또는 그 밖의 물건을 파괴하거나 사용할 수 없게 한 사람은 사형에 처한다.', 1175);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8862, '제13조(간첩)', 1175);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8863, '제14조(일반이적) 제11조부터 제13조까지의 행위 외에 다음 각 호의 어느 하나에 해당하는 행위를 한 사람은 사형, 무기 또는 5년 이상의 징역에 처한다.', 1175);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8864, '제15조(미수범) 제11조부터 제14조까지의 미수범은 처벌한다.', 1175);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8865, '제16조(예비, 음모, 선동, 선전)', 1175);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8866, '제17조(동맹국에 대한 행위) 이 장의 규정은 대한민국의 동맹국에 대한 행위에도 적용한다.', 1175);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8867, '제18조(불법 전투 개시) 지휘관이 정당한 사유 없이 외국에 대하여 전투를 개시한 경우에는 사형에 처한다.', 1176);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8868, '제19조(불법 전투 계속) 지휘관이 휴전 또는 강화(講和)의 고지를 받고도 정당한 사유 없이 전투를 계속한 경우에는 사형에 처한다.', 1176);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8869, '제20조(불법 진퇴) 전시, 사변 시 또는 계엄지역에서 지휘관이 권한을 남용하여 부득이한 사유 없이 부대, 함선 또는 항공기를 진퇴(進退)시킨 경우에는 사형, 무기 또는 7년 이상의 징역이나 금고에 처한다.', 1176);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8870, '제21조(미수범) 이 장의 미수범은 처벌한다.', 1176);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8871, '제22조(항복) 지휘관이 그 할 바를 다하지 아니하고 적에게 항복하거나 부대, 요새, 진영, 함선 또는 항공기를 적에게 방임(放任)한 경우에는 사형에 처한다.', 1177);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8872, '제23조(부대 인솔 도피) 지휘관이 적전에서 그 할 바를 다하지 아니하고 부대를 인솔하여 도피한 경우에는 사형에 처한다.', 1177);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8873, '제24조(직무유기) 지휘관이 정당한 사유 없이 직무수행을 거부하거나 직무를 유기(遺棄)한 경우에는 다음 각 호의 구분에 따라 처벌한다.', 1177);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8874, '제25조(미수범) 제22조 및 제23조의 미수범은 처벌한다.', 1177);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8875, '제26조(예비, 음모) 제22조 또는 제23조의 죄를 범할 목적으로 예비 또는 음모를 한 사람은 3년 이상의 유기징역에 처한다.', 1177);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8876, '제27조(지휘관의 수소 이탈) 지휘관이 정당한 사유 없이 부대를 인솔하여 수소를 이탈하거나 배치구역에 임하지 아니한 경우에는 다음 각 호의 구분에 따라 처벌한다.', 1178);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8877, '제28조(초병의 수소 이탈) 초병이 정당한 사유 없이 수소를 이탈하거나 지정된 시간까지 수소에 임하지 아니한 경우에는 다음 각 호의 구분에 따라 처벌한다.', 1178);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8878, '제29조(미수범) 이 장의 미수범은 처벌한다.', 1178);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8879, '제30조(군무 이탈)', 1179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8880, '제31조(특수 군무 이탈) 위험하거나 중요한 임무를 회피할 목적으로 배치지 또는 직무를 이탈한 사람도 제30조의 예에 따른다.', 1179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8881, '제32조(이탈자 비호) 제30조 또는 제31조의 죄를 범한 사람을 숨기거나 비호한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8882, '제33조(적진으로의 도주) 적진으로 도주한 사람은 사형에 처한다.', 1179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8883, '제34조(미수범) 이 장의 미수범은 처벌한다.', 1179);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8884, '제35조(근무 태만) 근무를 게을리하여 다음 각 호의 어느 하나에 해당하는 사람은 무기 또는 1년 이상의 징역에 처한다.', 1180);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8885, '제36조(비행군기 문란) 비행(飛行)에 관한 법규 또는 명령을 위반하여 항공기를 조종함으로써 비행군기를 문란하게 한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1180);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8886, '제37조(위계로 인한 항행 위험) 거짓 신호를 하거나 그 밖의 방법으로 군용에 공하는 함선 또는 항공기의 항행(航行)에 위험을 발생시킨 사람은 다음 각 호의 구분에 따라 처벌한다.', 1180);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8887, '제38조(거짓 명령, 통보, 보고)', 1180);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8888, '제39조(명령 등의 거짓 전달) 전시, 사변 시 또는 계엄지역에서 군사에 관한 명령, 통보 또는 보고를 전달하는 사람이 거짓으로 전달하거나 전달하지 아니한 경우에는 제38조의 예에 따른다.', 1180);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8889, '제40조(초령 위반)', 1180);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8890, '제41조(근무 기피 목적의 사술)', 1180);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8891, '제42조(유해 음식물 공급)', 1180);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8892, '제43조(출병 거부) 지휘관이 출병(出兵)을 요구할 수 있는 권한을 가진 사람으로부터 그 요구를 받고 상당한 이유 없이 이에 응하지 아니한 경우에는 7년 이하의 징역이나 금고에 처한다.', 1180);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8893, '제44조(항명) 상관의 정당한 명령에 반항하거나 복종하지 아니한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1181);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8894, '제45조(집단 항명) 집단을 이루어 제44조의 죄를 범한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1181);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8895, '제46조(상관의 제지 불복종) 폭행을 하는 사람이 상관의 제지에 복종하지 아니한 경우에는 3년 이하의 징역에 처한다.', 1181);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8896, '제47조(명령 위반) 정당한 명령 또는 규칙을 준수할 의무가 있는 사람이 이를 위반하거나 준수하지 아니한 경우에는 2년 이하의 징역이나 금고에 처한다.', 1181);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8897, '제48조(상관에 대한 폭행, 협박) 상관을 폭행하거나 협박한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8898, '제49조(상관에 대한 집단 폭행, 협박 등)', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8899, '제50조(상관에 대한 특수 폭행, 협박) 흉기나 그 밖의 위험한 물건을 휴대하고 제48조의 죄를 범한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8900, '제51조 삭제 <2009.11.2>', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8901, '제52조(상관에 대한 폭행치사상)', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8902, '제52조의2(상관에 대한 상해) 상관의 신체를 상해한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8903, '제52조의3(상관에 대한 집단상해 등)', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8904, '제52조의4(상관에 대한 특수상해) 흉기나 그 밖의 위험한 물건을 휴대하고 제52조의2의 죄를 범한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8905, '제52조의5(상관에 대한 중상해) 제52조제2항 및 제52조의2부터 제52조의4까지의 죄를 범하여 상관의 생명에 위험을 발생하게 하거나 불구 또는 불치나 난치의 질병에 이르게 한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8906, '제52조의6(상관에 대한 상해치사) 제52조의2부터 제52조의5까지의 죄를 범하여 상관을 사망에 이르게 한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8907, '제53조(상관 살해와 예비, 음모)', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8908, '제54조(초병에 대한 폭행, 협박) 초병에게 폭행 또는 협박을 한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8909, '제55조(초병에 대한 집단 폭행, 협박 등)', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8910, '제56조(초병에 대한 특수 폭행, 협박) 흉기나 그 밖의 위험한 물건을 휴대하고 제54조의 죄를 범한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8911, '제57조 삭제 <2009.11.2>', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8912, '제58조(초병에 대한 폭행치사상)', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8913, '제58조의2(초병에 대한 상해) 초병의 신체를 상해한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8914, '제58조의3(초병에 대한 집단상해 등)', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8915, '제58조의4(초병에 대한 특수상해) 흉기나 그 밖의 위험한 물건을 휴대하고 제58조의2의 죄를 범한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8916, '제58조의5(초병에 대한 중상해) 제58조제2항, 제58조의2 및 제58조의3제2항의 죄를 범하여 초병의 생명에 대한 위험을 발생하게 하거나 불구 또는 불치나 난치의 질병에 이르게 한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8917, '제58조의6(초병에 대한 상해치사) 제58조의2부터 제58조의5까지의 죄를 범하여 초병을 사망에 이르게 한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8918, '제59조(초병살해와 예비, 음모)', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8919, '제60조(직무수행 중인 군인등에 대한 폭행, 협박 등)', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8920, '제60조의2(직무수행 중인 군인등에 대한 상해) 상관 또는 초병 외의 직무수행 중인 군인등의 신체를 상해한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8921, '제60조의3(직무수행 중인 군인등에 대한 집단상해 등)', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8922, '제60조의4(직무수행 중인 군인등에 대한 중상해) 제60조제5항, 제60조의2 및 제60조의3제2항의 죄를 범하여 상관 또는 초병 외의 직무수행 중인 군인등의 생명에 대한 위험을 발생하게 하거나 불구 또는 불치나 난치의 질병에 이르게 한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8923, '제60조의5(직무수행 중인 군인등에 대한 상해치사) 제60조의2부터 제60조의4까지의 죄를 범하여 상관 또는 초병 외의 직무수행 중인 군인등을 사망에 이르게 한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8924, '제60조의6(군인등에 대한 폭행죄, 협박죄의 특례) 군인등이 다음 각 호의 어느 하나에 해당하는 장소에서 군인등을 폭행 또는 협박한 경우에는 「형법」 제260조제3항 및 제283조제3항을 적용하지 아니한다.', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8925, '제61조(특수소요) 집단을 이루어 흉기나 그 밖의 위험한 물건을 휴대하고 폭행, 협박 또는 손괴의 행위를 한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8926, '제62조(가혹행위)', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8927, '제63조(미수범) 제52조의2부터 제52조의4까지, 제53조제1항, 제58조의2부터 제58조의4까지, 제59조제1항, 제60조의2 및 제60조의3의 미수범은 처벌한다.', 1182);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8928, '제64조(상관 모욕 등)', 1183);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8929, '제65조(초병 모욕) 초병을 그 면전에서 모욕한 사람은 1년 이하의 징역이나 금고에 처한다.', 1183);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8930, '제66조(군용시설 등에 대한 방화)', 1184);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8931, '제67조(노적 군용물에 대한 방화) 불을 놓아 노적(露積)한 병기, 탄약, 차량, 장구(裝具), 기재(器材), 식량, 피복 또는 그 밖에 군용에 공하는 물건을 소훼한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1184);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8932, '제68조(폭발물 파열) 화약, 기관(汽罐) 또는 그 밖의 폭발성 있는 물건을 파열하게 하여 제66조와 제67조에 규정된 물건을 손괴한 사람도 제66조 및 제67조의 예에 따른다.', 1184);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8933, '제69조(군용시설 등 손괴) 제66조에 규정된 물건 또는 군용에 공하는 철도, 전선 또는 그 밖의 시설이나 물건을 손괴하거나 그 밖의 방법으로 그 효용을 해한 사람은 무기 또는 2년 이상의 징역에 처한다.', 1184);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8934, '제70조(노획물 훼손) 적과 싸워서 얻은 물건을 횡령하거나 소훼 또는 손괴한 사람은 1년 이상 10년 이하의 징역에 처한다.', 1184);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8935, '제71조(함선ㆍ항공기의 복몰 또는 손괴)', 1184);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8936, '제72조(미수범) 제66조부터 제70조까지 및 제71조제1항ㆍ제2항의 미수범은 처벌한다.', 1184);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8937, '제73조(과실범)', 1184);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8938, '제74조(군용물 분실) 총포, 탄약, 폭발물, 차량, 장구, 기재, 식량, 피복 또는 그 밖에 군용에 공하는 물건을 보관할 책임이 있는 사람으로서 이를 분실한 사람은 5년 이하의 징역 또는 300만원 이하의 벌금에 처한다.', 1184);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8939, '제75조(군용물 등 범죄에 대한 형의 가중)', 1184);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8940, '제76조(예비, 음모) 제66조부터 제69조까지와 제71조의 죄를 범할 목적으로 예비 또는 음모를 한 사람은 7년 이하의 징역이나 금고에 처한다. 다만, 그 목적한 죄의 실행에 이르기 전에 자수한 경우에는 그 형을 감경하거나 면제한다.', 1184);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8941, '제77조(외국의 군용시설 또는 군용물에 대한 행위) 이 장의 규정은 국군과 공동작전에 종사하고 있는 외국군의 군용시설 또는 군용에 공하는 물건에 대한 행위에도 적용한다.', 1184);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8942, '제78조(초소 침범) 초병을 속여서 초소를 통과하거나 초병의 제지에 불응한 사람은 다음 각 호의 구분에 따라 처벌한다.', 1185);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8943, '제79조(무단 이탈) 허가 없이 근무장소 또는 지정장소를 일시적으로 이탈하거나 지정한 시간까지 지정한 장소에 도달하지 못한 사람은 1년 이하의 징역이나 금고 또는 300만원 이하의 벌금에 처한다.', 1185);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8944, '제80조(군사기밀 누설)', 1185);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8945, '제81조(암호 부정사용) 다음 각 호의 어느 하나에 해당하는 사람은 2년 이상의 유기징역이나 유기금고에 처한다.', 1185);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8946, '제82조(약탈)', 1186);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8947, '제83조(약탈로 인한 치사상)', 1186);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8948, '제84조(전지 강간)', 1186);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8949, '제85조(미수범) 이 장의 미수범은 처벌한다.', 1186);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8950, '제86조(포로) 적에게 포로가 된 사람이 우군(友軍)부대 또는 진지로 귀환할 수 있는데도 귀환할 적절한 행동을 하지 아니하거나 다른 우군포로가 귀환하지 못하게 한 사람은 2년 이하의 징역에 처한다.', 1187);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8951, '제87조(간수자의 포로 도주 원조) 포로를 간수 또는 호송하는 사람이 그 포로를 도주하게 한 경우에는 3년 이상의 유기징역에 처한다.', 1187);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8952, '제88조(포로 도주 원조)', 1187);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8953, '제89조(포로 탈취) 포로를 탈취한 사람은 2년 이상의 유기징역에 처한다.', 1187);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8954, '제90조(도주포로 비호) 도주한 포로를 숨기거나 비호한 사람은 5년 이하의 징역에 처한다.', 1187);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8955, '제91조(미수범) 제87조부터 제90조까지의 미수범은 처벌한다.', 1187);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8956, '제92조(강간) 폭행이나 협박으로 제1조제1항부터 제3항까지에 규정된 사람을 강간한 사람은 5년 이상의 유기징역에 처한다. <개정 2013.4.5>', 1188);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8957, '제92조의2(유사강간) 폭행이나 협박으로 제1조제1항부터 제3항까지에 규정된 사람에 대하여 구강, 항문 등 신체(성기는 제외한다)의 내부에 성기를 넣거나 성기, 항문에 손가락 등 신체(성기는 제외한다)의 일부 또는 도구를 넣는 행위를 한 사람은 3년 이상의 유기징역에 처한다.', 1188);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8958, '제92조의3(강제추행) 폭행이나 협박으로 제1조제1항부터 제3항까지에 규정된 사람에 대하여 추행을 한 사람은 1년 이상의 유기징역에 처한다.', 1188);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8959, '제92조의4(준강간, 준강제추행) 제1조제1항부터 제3항까지에 규정된 사람의 심신상실 또는 항거불능 상태를 이용하여 간음 또는 추행을 한 사람은 제92조, 제92조의2 및 제92조의3의 예에 따른다. <개정 2013.4.5>', 1188);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8960, '제92조의5(미수범) 제92조, 제92조의2부터 제92조의4까지의 미수범은 처벌한다. <개정 2013.4.5>', 1188);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8961, '제92조의6(추행) 제1조제1항부터 제3항까지에 규정된 사람에 대하여 항문성교나 그 밖의 추행을 한 사람은 2년 이하의 징역에 처한다. <개정 2013.4.5>', 1188);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8962, '제92조의7(강간 등 상해ㆍ치상) 제92조 및 제92조의2부터 제92조의5까지의 죄를 범한 사람이 제1조제1항부터 제3항까지에 규정된 사람을 상해하거나 상해에 이르게 한 때에는 무기 또는 7년 이상의 징역에 처한다. <개정 2013.4.5>', 1188);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8963, '제92조의8(강간 등 살인ㆍ치사) 제92조 및 제92조의2부터 제92조의5까지의 죄를 범한 사람이 제1조제1항부터 제3항까지에 규정된 사람을 살해한 때에는 사형 또는 무기징역에 처하고, 사망에 이르게 한 때에는 사형, 무기 또는 10년 이상의 징역에 처한다. <개정 2013.4.5>', 1188);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8964, '제93조(부하범죄 부진정) 부하가 다수 공동하여 죄를 범함을 알고도 그 진정(鎭定)을 위하여 필요한 방법을 다하지 아니한 사람은 3년 이하의 징역이나 금고에 처한다.', 1189);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8965, '제94조(정치 관여)', 1189);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8966, '제1조(범죄의 성립과 처벌)', 1191);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8967, '제2조(국내범) 본법은 대한민국영역내에서 죄를 범한 내국인과 외국인에게 적용한다.', 1191);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8968, '제3조(내국인의 국외범) 본법은 대한민국영역외에서 죄를 범한 내국인에게 적용한다.', 1191);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8969, '제4조(국외에 있는 내국선박 등에서 외국인이 범한 죄) 본법은 대한민국영역외에 있는 대한민국의 선박 또는 항공기내에서 죄를 범한 외국인에게 적용한다.', 1191);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8970, '제5조(외국인의 국외범) 본법은 대한민국영역외에서 다음에 기재한 죄를 범한 외국인에게 적용한다.', 1191);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8971, '제6조(대한민국과 대한민국국민에 대한 국외범) 본법은 대한민국영역외에서 대한민국 또는 대한민국국민에 대하여 전조에 기재한 이외의 죄를 범한 외국인에게 적용한다. 단 행위지의 법률에 의하여 범죄를 구성하지 아니하거나 소추 또는 형의 집행을 면제할 경우에는 예외로 한다.', 1191);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8972, '제7조(외국에서 집행된 형의 산입) 죄를 지어 외국에서 형의 전부 또는 일부가 집행된 사람에 대해서는 그 집행된 형의 전부 또는 일부를 선고하는 형에 산입한다.', 1191);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8973, '제8조(총칙의 적용) 본법 총칙은 타법령에 정한 죄에 적용한다. 단, 그 법령에 특별한 규정이 있는 때에는 예외로 한다.', 1191);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8974, '제9조(형사미성년자) 14세되지 아니한 자의 행위는 벌하지 아니한다.', 1193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8975, '제10조(심신장애인)', 1193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8976, '제11조(청각 및 언어 장애인) 듣거나 말하는 데 모두 장애가 있는 사람의 행위에 대해서는 형을 감경한다.', 1193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8977, '제12조(강요된 행위) 저항할 수 없는 폭력이나 자기 또는 친족의 생명, 신체에 대한 위해를 방어할 방법이 없는 협박에 의하여 강요된 행위는 벌하지 아니한다.', 1193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8978, '제13조(고의) 죄의 성립요소인 사실을 인식하지 못한 행위는 벌하지 아니한다. 다만, 법률에 특별한 규정이 있는 경우에는 예외로 한다.', 1193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8979, '제14조(과실) 정상적으로 기울여야 할 주의(注意)를 게을리하여 죄의 성립요소인 사실을 인식하지 못한 행위는 법률에 특별한 규정이 있는 경우에만 처벌한다.', 1193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8980, '제15조(사실의 착오)', 1193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8981, '제16조(법률의 착오) 자기의 행위가 법령에 의하여 죄가 되지 아니하는 것으로 오인한 행위는 그 오인에 정당한 이유가 있는 때에 한하여 벌하지 아니한다.', 1193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8982, '제17조(인과관계) 어떤 행위라도 죄의 요소되는 위험발생에 연결되지 아니한 때에는 그 결과로 인하여 벌하지 아니한다.', 1193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8983, '제18조(부작위범) 위험의 발생을 방지할 의무가 있거나 자기의 행위로 인하여 위험발생의 원인을 야기한 자가 그 위험발생을 방지하지 아니한 때에는 그 발생된 결과에 의하여 처벌한다.', 1193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8984, '제19조(독립행위의 경합) 동시 또는 이시의 독립행위가 경합한 경우에 그 결과발생의 원인된 행위가 판명되지 아니한 때에는 각 행위를 미수범으로 처벌한다.', 1193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8985, '제20조(정당행위) 법령에 의한 행위 또는 업무로 인한 행위 기타 사회상규에 위배되지 아니하는 행위는 벌하지 아니한다.', 1193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8986, '제21조(정당방위)', 1193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8987, '제22조(긴급피난)', 1193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8988, '제23조(자구행위)', 1193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8989, '제24조(피해자의 승낙) 처분할 수 있는 자의 승낙에 의하여 그 법익을 훼손한 행위는 법률에 특별한 규정이 없는 한 벌하지 아니한다.', 1193);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8990, '제25조(미수범)', 1194);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8991, '제26조(중지범) 범인이 실행에 착수한 행위를 자의(自意)로 중지하거나 그 행위로 인한 결과의 발생을 자의로 방지한 경우에는 형을 감경하거나 면제한다.', 1194);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8992, '제27조(불능범) 실행의 수단 또는 대상의 착오로 인하여 결과의 발생이 불가능하더라도 위험성이 있는 때에는 처벌한다. 단, 형을 감경 또는 면제할 수 있다.', 1194);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8993, '제28조(음모, 예비) 범죄의 음모 또는 예비행위가 실행의 착수에 이르지 아니한 때에는 법률에 특별한 규정이 없는 한 벌하지 아니한다.', 1194);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8994, '제29조(미수범의 처벌) 미수범을 처벌할 죄는 각칙의 해당 죄에서 정한다.', 1194);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8995, '제30조(공동정범) 2인 이상이 공동하여 죄를 범한 때에는 각자를 그 죄의 정범으로 처벌한다.', 1195);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8996, '제31조(교사범)', 1195);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8997, '제32조(종범)', 1195);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8998, '제33조(공범과 신분) 신분이 있어야 성립되는 범죄에 신분 없는 사람이 가담한 경우에는 그 신분 없는 사람에게도 제30조부터 제32조까지의 규정을 적용한다. 다만, 신분 때문에 형의 경중이 달라지는 경우에 신분이 없는 사람은 무거운 형으로 벌하지 아니한다.', 1195);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (8999, '제34조(간접정범, 특수한 교사, 방조에 대한 형의 가중)', 1195);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9000, '제35조(누범)', 1196);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9001, '제36조(판결선고후의 누범발각) 판결선고후 누범인 것이 발각된 때에는 그 선고한 형을 통산하여 다시 형을 정할 수 있다. 단, 선고한 형의 집행을 종료하거나 그 집행이 면제된 후에는 예외로 한다.', 1196);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9002, '제37조(경합범) 판결이 확정되지 아니한 수개의 죄 또는 금고 이상의 형에 처한 판결이 확정된 죄와 그 판결확정전에 범한 죄를 경합범으로 한다. <개정 2004.1.20>', 1197);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9003, '제38조(경합범과 처벌례)', 1197);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9004, '제39조(판결을 받지 아니한 경합범, 수개의 판결과 경합범, 형의 집행과 경합범)', 1197);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9005, '제40조(상상적 경합) 한 개의 행위가 여러 개의 죄에 해당하는 경우에는 가장 무거운 죄에 대하여 정한 형으로 처벌한다.', 1197);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9006, '제41조(형의 종류) 형의 종류는 다음과 같다.', 1199);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9007, '제42조(징역 또는 금고의 기간) 징역 또는 금고는 무기 또는 유기로 하고 유기는 1개월 이상 30년 이하로 한다. 단, 유기징역 또는 유기금고에 대하여 형을 가중하는 때에는 50년까지로 한다. <개정 2010.4.15>', 1199);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9008, '제43조(형의 선고와 자격상실, 자격정지)', 1199);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9009, '제44조(자격정지)', 1199);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9010, '제45조(벌금) 벌금은 5만원 이상으로 한다. 다만, 감경하는 경우에는 5만원 미만으로 할 수 있다. <개정 1995.12.29>', 1199);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9011, '제46조(구류) 구류는 1일 이상 30일 미만으로 한다.', 1199);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9012, '제47조(과료) 과료는 2천원 이상 5만원 미만으로 한다. <개정 1995.12.29>', 1199);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9013, '제48조(몰수의 대상과 추징)', 1199);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9014, '제49조(몰수의 부가성) 몰수는 타형에 부가하여 과한다. 단, 행위자에게 유죄의 재판을 아니할 때에도 몰수의 요건이 있는 때에는 몰수만을 선고할 수 있다.', 1199);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9015, '제50조(형의 경중)', 1199);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9016, '제51조(양형의 조건) 형을 정함에 있어서는 다음 사항을 참작하여야 한다.', 1200);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9017, '제52조(자수, 자복)', 1200);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9018, '제53조(정상참작감경) 범죄의 정상(情狀)에 참작할 만한 사유가 있는 경우에는 그 형을 감경할 수 있다.', 1200);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9019, '제54조(선택형과 정상참작감경) 한 개의 죄에 정한 형이 여러 종류인 때에는 먼저 적용할 형을 정하고 그 형을 감경한다.', 1200);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9020, '제55조(법률상의 감경)', 1200);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9021, '제56조(가중ㆍ감경의 순서) 형을 가중ㆍ감경할 사유가 경합하는 경우에는 다음 각 호의 순서에 따른다.', 1200);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9022, '제57조(판결선고전 구금일수의 통산)', 1200);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9023, '제58조(판결의 공시)', 1200);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9024, '제59조(선고유예의 요건)', 1201);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9025, '제59조의2(보호관찰)', 1201);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9026, '제60조(선고유예의 효과) 형의 선고유예를 받은 날로부터 2년을 경과한 때에는 면소된 것으로 간주한다.', 1201);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9027, '제61조(선고유예의 실효)', 1201);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9028, '제62조(집행유예의 요건)', 1202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9029, '제62조의2(보호관찰, 사회봉사ㆍ수강명령)', 1202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9030, '제63조(집행유예의 실효) 집행유예의 선고를 받은 자가 유예기간 중 고의로 범한 죄로 금고 이상의 실형을 선고받아 그 판결이 확정된 때에는 집행유예의 선고는 효력을 잃는다. <개정 2005.7.29>', 1202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9031, '제64조(집행유예의 취소)', 1202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9032, '제65조(집행유예의 효과) 집행유예의 선고를 받은 후 그 선고의 실효 또는 취소됨이 없이 유예기간을 경과한 때에는 형의 선고는 효력을 잃는다.', 1202);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9033, '제66조(사형) 사형은 교정시설 안에서 교수(絞首)하여 집행한다.', 1203);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9034, '제67조(징역) 징역은 교정시설에 수용하여 집행하며, 정해진 노역(勞役)에 복무하게 한다.', 1203);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9035, '제68조(금고와 구류) 금고와 구류는 교정시설에 수용하여 집행한다.', 1203);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9036, '제69조(벌금과 과료)', 1203);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9037, '제70조(노역장 유치)', 1203);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9038, '제71조(유치일수의 공제) 벌금이나 과료의 선고를 받은 사람이 그 금액의 일부를 납입한 경우에는 벌금 또는 과료액과 노역장 유치기간의 일수(日數)에 비례하여 납입금액에 해당하는 일수를 뺀다.', 1203);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9039, '제72조(가석방의 요건)', 1204);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9040, '제73조(판결선고 전 구금과 가석방)', 1204);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9041, '제73조의2(가석방의 기간 및 보호관찰)', 1204);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9042, '제74조(가석방의 실효) 가석방 기간 중 고의로 지은 죄로 금고 이상의 형을 선고받아 그 판결이 확정된 경우에 가석방 처분은 효력을 잃는다.', 1204);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9043, '제75조(가석방의 취소) 가석방의 처분을 받은 자가 감시에 관한 규칙을 위배하거나, 보호관찰의 준수사항을 위반하고 그 정도가 무거운 때에는 가석방처분을 취소할 수 있다.', 1204);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9044, '제76조(가석방의 효과)', 1204);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9045, '제77조(형의 시효의 효과) 형(사형은 제외한다)을 선고받은 자에 대해서는 시효가 완성되면 그 집행이 면제된다. <개정 2023.8.8>', 1205);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9046, '제78조(형의 시효의 기간) 시효는 형을 선고하는 재판이 확정된 후 그 집행을 받지 아니하고 다음 각 호의 구분에 따른 기간이 지나면 완성된다. <개정 2017.12.12, 2020.12.8, 2023.8.8>', 1205);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9047, '제79조(형의 시효의 정지)', 1205);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9048, '제80조(형의 시효의 중단) 시효는 징역, 금고 및 구류의 경우에는 수형자를 체포한 때, 벌금, 과료, 몰수 및 추징의 경우에는 강제처분을 개시한 때에 중단된다.', 1205);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9049, '제81조(형의 실효) 징역 또는 금고의 집행을 종료하거나 집행이 면제된 자가 피해자의 손해를 보상하고 자격정지 이상의 형을 받음이 없이 7년을 경과한 때에는 본인 또는 검사의 신청에 의하여 그 재판의 실효를 선고할 수 있다.', 1206);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9050, '제82조(복권) 자격정지의 선고를 받은 자가 피해자의 손해를 보상하고 자격정지 이상의 형을 받음이 없이 정지기간의 2분의 1을 경과한 때에는 본인 또는 검사의 신청에 의하여 자격의 회복을 선고할 수 있다.', 1206);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9051, '제83조(기간의 계산) 연(年) 또는 월(月)로 정한 기간은 연 또는 월 단위로 계산한다.', 1207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9052, '제84조(형기의 기산)', 1207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9053, '제85조(형의 집행과 시효기간의 초일) 형의 집행과 시효기간의 초일은 시간을 계산함이 없이 1일로 산정한다.', 1207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9054, '제86조(석방일) 석방은 형기종료일에 하여야 한다.', 1207);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9055, '제87조(내란) 대한민국 영토의 전부 또는 일부에서 국가권력을 배제하거나 국헌을 문란하게 할 목적으로 폭동을 일으킨 자는 다음 각 호의 구분에 따라 처벌한다.', 1209);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9056, '제88조(내란목적의 살인) 대한민국 영토의 전부 또는 일부에서 국가권력을 배제하거나 국헌을 문란하게 할 목적으로 사람을 살해한 자는 사형, 무기징역 또는 무기금고에 처한다.', 1209);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9057, '제89조(미수범) 전2조의 미수범은 처벌한다.', 1209);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9058, '제90조(예비, 음모, 선동, 선전)', 1209);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9059, '제91조(국헌문란의 정의) 본장에서 국헌을 문란할 목적이라 함은 다음 각호의 1에 해당함을 말한다.', 1209);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9060, '제92조(외환유치) 외국과 통모하여 대한민국에 대하여 전단을 열게 하거나 외국인과 통모하여 대한민국에 항적한 자는 사형 또는 무기징역에 처한다.', 1210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9061, '제93조(여적) 적국과 합세하여 대한민국에 항적한 자는 사형에 처한다.', 1210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9062, '제94조(모병이적)', 1210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9063, '제95조(시설제공이적)', 1210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9064, '제96조(시설파괴이적) 적국을 위하여 전조에 기재한 군용시설 기타 물건을 파괴하거나 사용할 수 없게 한 자는 사형 또는 무기징역에 처한다.', 1210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9065, '제97조(물건제공이적) 군용에 공하지 아니하는 병기, 탄약 또는 전투용에 공할 수 있는 물건을 적국에 제공한 자는 무기 또는 5년 이상의 징역에 처한다.', 1210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9066, '제98조(간첩)', 1210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9067, '제99조(일반이적) 전7조에 기재한 이외에 대한민국의 군사상 이익을 해하거나 적국에 군사상 이익을 공여한 자는 무기 또는 3년 이상의 징역에 처한다.', 1210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9068, '제100조(미수범) 전8조의 미수범은 처벌한다.', 1210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9069, '제101조(예비, 음모, 선동, 선전)', 1210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9070, '제102조(준적국) 제93조 내지 전조의 죄에 있어서는 대한민국에 적대하는 외국 또는 외국인의 단체는 적국으로 간주한다.', 1210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9071, '제103조(전시군수계약불이행)', 1210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9072, '제104조(동맹국) 본장의 규정은 동맹국에 대한 행위에 적용한다.', 1210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9073, '제104조의2 삭제 <1988.12.31>', 1210);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9074, '제105조(국기, 국장의 모독) 대한민국을 모욕할 목적으로 국기 또는 국장을 손상, 제거 또는 오욕한 자는 5년 이하의 징역이나 금고, 10년 이하의 자격정지 또는 700만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1211);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9075, '제106조(국기, 국장의 비방) 전조의 목적으로 국기 또는 국장을 비방한 자는 1년 이하의 징역이나 금고, 5년 이하의 자격정지 또는 200만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1211);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9076, '제107조(외국원수에 대한 폭행 등)', 1212);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9077, '제108조(외국사절에 대한 폭행 등)', 1212);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9078, '제109조(외국의 국기, 국장의 모독) 외국을 모욕할 목적으로 그 나라의 공용에 공하는 국기 또는 국장을 손상, 제거 또는 오욕한 자는 2년 이하의 징역이나 금고 또는 300만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1212);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9079, '제110조(피해자의 의사) 제107조 내지 제109조의 죄는 그 외국정부의 명시한 의사에 반하여 공소를 제기할 수 없다. <개정 1995.12.29>', 1212);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9080, '제111조(외국에 대한 사전)', 1212);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9081, '제112조(중립명령위반) 외국간의 교전에 있어서 중립에 관한 명령에 위반한 자는 3년 이하의 금고 또는 500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1212);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9082, '제113조(외교상기밀의 누설)', 1212);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9083, '제114조(범죄단체 등의 조직) 사형, 무기 또는 장기 4년 이상의 징역에 해당하는 범죄를 목적으로 하는 단체 또는 집단을 조직하거나 이에 가입 또는 그 구성원으로 활동한 사람은 그 목적한 죄에 정한 형으로 처벌한다. 다만, 형을 감경할 수 있다.', 1213);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9084, '제115조(소요) 다중이 집합하여 폭행, 협박 또는 손괴의 행위를 한 자는 1년 이상 10년 이하의 징역이나 금고 또는 1천500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1213);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9085, '제116조(다중불해산) 폭행, 협박 또는 손괴의 행위를 할 목적으로 다중이 집합하여 그를 단속할 권한이 있는 공무원으로부터 3회 이상의 해산명령을 받고 해산하지 아니한 자는 2년 이하의 징역이나 금고 또는 300만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1213);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9086, '제116조의2(공중협박)', 1213);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9087, '제116조의3(공공장소 흉기소지) 정당한 이유 없이 도로ㆍ공원 등 불특정 또는 다수의 사람이 이용하거나 통행할 수 있는 공공장소에서 사람의 생명, 신체에 위해를 가할 수 있는 흉기를 소지하고 이를 드러내어 공중에게 불안감 또는 공포심을 일으킨 사람은 3년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 1213);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9088, '제117조(전시공수계약불이행)', 1213);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9089, '제118조(공무원자격의 사칭) 공무원의 자격을 사칭하여 그 직권을 행사한 자는 3년 이하의 징역 또는 700만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1213);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9090, '제119조(폭발물 사용)', 1214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9091, '제120조(예비, 음모, 선동)', 1214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9092, '제121조(전시폭발물제조 등) 전쟁 또는 사변에 있어서 정당한 이유없이 폭발물을 제조, 수입, 수출, 수수 또는 소지한 자는 10년 이하의 징역에 처한다.', 1214);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9093, '제122조(직무유기) 공무원이 정당한 이유없이 그 직무수행을 거부하거나 그 직무를 유기한 때에는 1년 이하의 징역이나 금고 또는 3년 이하의 자격정지에 처한다.', 1215);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9094, '제123조(직권남용) 공무원이 직권을 남용하여 사람으로 하여금 의무없는 일을 하게 하거나 사람의 권리행사를 방해한 때에는 5년 이하의 징역, 10년 이하의 자격정지 또는 1천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1215);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9095, '제124조(불법체포, 불법감금)', 1215);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9096, '제125조(폭행, 가혹행위) 재판, 검찰, 경찰 그 밖에 인신구속에 관한 직무를 수행하는 자 또는 이를 보조하는 자가 그 직무를 수행하면서 형사피의자나 그 밖의 사람에 대하여 폭행 또는 가혹행위를 한 경우에는 5년 이하의 징역과 10년 이하의 자격정지에 처한다.', 1215);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9097, '제126조(피의사실공표) 검찰, 경찰 그 밖에 범죄수사에 관한 직무를 수행하는 자 또는 이를 감독하거나 보조하는 자가 그 직무를 수행하면서 알게 된 피의사실을 공소제기 전에 공표(公表)한 경우에는 3년 이하의 징역 또는 5년 이하의 자격정지에 처한다.', 1215);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9098, '제127조(공무상 비밀의 누설) 공무원 또는 공무원이었던 자가 법령에 의한 직무상 비밀을 누설한 때에는 2년 이하의 징역이나 금고 또는 5년 이하의 자격정지에 처한다.', 1215);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9099, '제128조(선거방해) 검찰, 경찰 또는 군의 직에 있는 공무원이 법령에 의한 선거에 관하여 선거인, 입후보자 또는 입후보자되려는 자에게 협박을 가하거나 기타 방법으로 선거의 자유를 방해한 때에는 10년 이하의 징역과 5년 이상의 자격정지에 처한다.', 1215);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9100, '제129조(수뢰, 사전수뢰)', 1215);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9101, '제130조(제삼자뇌물제공) 공무원 또는 중재인이 그 직무에 관하여 부정한 청탁을 받고 제3자에게 뇌물을 공여하게 하거나 공여를 요구 또는 약속한 때에는 5년 이하의 징역 또는 10년 이하의 자격정지에 처한다.', 1215);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9102, '제131조(수뢰후부정처사, 사후수뢰)', 1215);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9103, '제132조(알선수뢰) 공무원이 그 지위를 이용하여 다른 공무원의 직무에 속한 사항의 알선에 관하여 뇌물을 수수, 요구 또는 약속한 때에는 3년 이하의 징역 또는 7년 이하의 자격정지에 처한다.', 1215);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9104, '제133조(뇌물공여 등)', 1215);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9105, '제134조(몰수, 추징) 범인 또는 사정을 아는 제3자가 받은 뇌물 또는 뇌물로 제공하려고 한 금품은 몰수한다. 이를 몰수할 수 없을 경우에는 그 가액을 추징한다.', 1215);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9106, '제135조(공무원의 직무상 범죄에 대한 형의 가중) 공무원이 직권을 이용하여 본장 이외의 죄를 범한 때에는 그 죄에 정한 형의 2분의 1까지 가중한다. 단 공무원의 신분에 의하여 특별히 형이 규정된 때에는 예외로 한다.', 1215);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9107, '제136조(공무집행방해)', 1216);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9108, '제137조(위계에 의한 공무집행방해) 위계로써 공무원의 직무집행을 방해한 자는 5년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1216);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9109, '제138조(법정 또는 국회회의장모욕) 법원의 재판 또는 국회의 심의를 방해 또는 위협할 목적으로 법정이나 국회회의장 또는 그 부근에서 모욕 또는 소동한 자는 3년 이하의 징역 또는 700만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1216);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9110, '제139조(인권옹호직무방해) 경찰의 직무를 행하는 자 또는 이를 보조하는 자가 인권옹호에 관한 검사의 직무집행을 방해하거나 그 명령을 준수하지 아니한 때에는 5년 이하의 징역 또는 10년 이하의 자격정지에 처한다.', 1216);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9111, '제140조(공무상비밀표시무효)', 1216);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9112, '제140조의2(부동산강제집행효용침해) 강제집행으로 명도 또는 인도된 부동산에 침입하거나 기타 방법으로 강제집행의 효용을 해한 자는 5년 이하의 징역 또는 700만원 이하의 벌금에 처한다.', 1216);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9113, '제141조(공용서류 등의 무효, 공용물의 파괴)', 1216);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9114, '제142조(공무상 보관물의 무효) 공무소로부터 보관명령을 받거나 공무소의 명령으로 타인이 관리하는 자기의 물건을 손상 또는 은닉하거나 기타 방법으로 그 효용을 해한 자는 5년 이하의 징역 또는 700만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1216);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9115, '제143조(미수범) 제140조 내지 전조의 미수범은 처벌한다.', 1216);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9116, '제144조(특수공무방해)', 1216);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9117, '제145조(도주, 집합명령위반)', 1217);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9118, '제146조(특수도주) 수용설비 또는 기구를 손괴하거나 사람에게 폭행 또는 협박을 가하거나 2인 이상이 합동하여 전조제1항의 죄를 범한 자는 7년 이하의 징역에 처한다.', 1217);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9119, '제147조(도주원조) 법률에 의하여 구금된 자를 탈취하거나 도주하게 한 자는 10년 이하의 징역에 처한다.', 1217);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9120, '제148조(간수자의 도주원조) 법률에 의하여 구금된 자를 간수 또는 호송하는 자가 이를 도주하게 한 때에는 1년 이상 10년 이하의 징역에 처한다.', 1217);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9121, '제149조(미수범) 전4조의 미수범은 처벌한다.', 1217);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9122, '제150조(예비, 음모) 제147조와 제148조의 죄를 범할 목적으로 예비 또는 음모한 자는 3년 이하의 징역에 처한다.', 1217);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9123, '제151조(범인은닉과 친족간의 특례)', 1217);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9124, '제152조(위증, 모해위증)', 1218);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9125, '제153조(자백, 자수) 전조의 죄를 범한 자가 그 공술한 사건의 재판 또는 징계처분이 확정되기 전에 자백 또는 자수한 때에는 그 형을 감경 또는 면제한다.', 1218);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9126, '제154조(허위의 감정, 통역, 번역) 법률에 의하여 선서한 감정인, 통역인 또는 번역인이 허위의 감정, 통역 또는 번역을 한 때에는 전2조의 예에 의한다.', 1218);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9127, '제155조(증거인멸 등과 친족간의 특례)', 1218);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9128, '제156조(무고) 타인으로 하여금 형사처분 또는 징계처분을 받게 할 목적으로 공무소 또는 공무원에 대하여 허위의 사실을 신고한 자는 10년 이하의 징역 또는 1천500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9129, '제157조(자백ㆍ자수) 제153조는 전조에 준용한다.', 1219);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9130, '제158조(장례식등의 방해) 장례식, 제사, 예배 또는 설교를 방해한 자는 3년 이하의 징역 또는 500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1220);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9131, '제159조(시체 등의 오욕) 시체, 유골 또는 유발(遺髮)을 오욕한 자는 2년 이하의 징역 또는 500만원 이하의 벌금에 처한다.', 1220);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9132, '제160조(분묘의 발굴) 분묘를 발굴한 자는 5년 이하의 징역에 처한다.', 1220);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9133, '제161조(시체 등의 유기 등)', 1220);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9134, '제162조(미수범) 전2조의 미수범은 처벌한다.', 1220);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9135, '제163조(변사체 검시 방해) 변사자의 시체 또는 변사(變死)로 의심되는 시체를 은닉하거나 변경하거나 그 밖의 방법으로 검시(檢視)를 방해한 자는 700만원 이하의 벌금에 처한다.', 1220);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9136, '제164조(현주건조물 등 방화)', 1221);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9137, '제165조(공용건조물 등 방화) 불을 놓아 공용(公用)으로 사용하거나 공익을 위해 사용하는 건조물, 기차, 전차, 자동차, 선박, 항공기 또는 지하채굴시설을 불태운 자는 무기 또는 3년 이상의 징역에 처한다.', 1221);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9138, '제166조(일반건조물 등 방화)', 1221);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9139, '제167조(일반물건 방화)', 1221);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9140, '제168조(연소)', 1221);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9141, '제169조(진화방해) 화재에 있어서 진화용의 시설 또는 물건을 은닉 또는 손괴하거나 기타 방법으로 진화를 방해한 자는 10년 이하의 징역에 처한다.', 1221);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9142, '제170조(실화)', 1221);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9143, '제171조(업무상실화, 중실화) 업무상과실 또는 중대한 과실로 인하여 제170조의 죄를 범한 자는 3년 이하의 금고 또는 2천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1221);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9144, '제172조(폭발성물건파열)', 1221);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9145, '제172조의2(가스ㆍ전기등 방류)', 1221);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9146, '제173조(가스ㆍ전기등 공급방해)', 1221);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9147, '제173조의2(과실폭발성물건파열등)', 1221);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9148, '제174조(미수범) 제164조제1항, 제165조, 제166조제1항, 제172조제1항, 제172조의2제1항, 제173조제1항과 제2항의 미수범은 처벌한다.', 1221);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9149, '제175조(예비, 음모) 제164조제1항, 제165조, 제166조제1항, 제172조제1항, 제172조의2제1항, 제173조제1항과 제2항의 죄를 범할 목적으로 예비 또는 음모한 자는 5년 이하의 징역에 처한다. 단 그 목적한 죄의 실행에 이르기 전에 자수한 때에는 형을 감경 또는 면제한다. <개정 1995.12.29>', 1221);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9150, '제176조(타인의 권리대상이 된 자기의 물건) 자기의 소유에 속하는 물건이라도 압류 기타 강제처분을 받거나 타인의 권리 또는 보험의 목적물이 된 때에는 본장의 규정의 적용에 있어서 타인의 물건으로 간주한다.', 1221);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9151, '제177조(현주건조물등에의 일수)', 1222);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9152, '제178조(공용건조물 등에의 일수) 물을 넘겨 공용 또는 공익에 공하는 건조물, 기차, 전차, 자동차, 선박, 항공기 또는 광갱을 침해한 자는 무기 또는 2년 이상의 징역에 처한다.', 1222);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9153, '제179조(일반건조물 등에의 일수)', 1222);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9154, '제180조(방수방해) 수재에 있어서 방수용의 시설 또는 물건을 손괴 또는 은닉하거나 기타 방법으로 방수를 방해한 자는 10년 이하의 징역에 처한다.', 1222);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9155, '제181조(과실일수) 과실로 인하여 제177조 또는 제178조에 기재한 물건을 침해한 자 또는 제179조에 기재한 물건을 침해하여 공공의 위험을 발생하게 한 자는 1천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1222);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9156, '제182조(미수범) 제177조 내지 제179조제1항의 미수범은 처벌한다.', 1222);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9157, '제183조(예비, 음모) 제177조 내지 제179조제1항의 죄를 범할 목적으로 예비 또는 음모한 자는 3년 이하의 징역에 처한다.', 1222);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9158, '제184조(수리방해) 둑을 무너뜨리거나 수문을 파괴하거나 그 밖의 방법으로 수리(水利)를 방해한 자는 5년 이하의 징역 또는 700만원 이하의 벌금에 처한다.', 1222);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9159, '제185조(일반교통방해) 육로, 수로 또는 교량을 손괴 또는 불통하게 하거나 기타 방법으로 교통을 방해한 자는 10년 이하의 징역 또는 1천500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9160, '제186조(기차, 선박 등의 교통방해) 궤도, 등대 또는 표지를 손괴하거나 기타 방법으로 기차, 전차, 자동차, 선박 또는 항공기의 교통을 방해한 자는 1년 이상의 유기징역에 처한다.', 1223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9161, '제187조(기차 등의 전복 등) 사람의 현존하는 기차, 전차, 자동차, 선박 또는 항공기를 전복, 매몰, 추락 또는 파괴한 자는 무기 또는 3년 이상의 징역에 처한다.', 1223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9162, '제188조(교통방해치사상) 제185조 내지 제187조의 죄를 범하여 사람을 상해에 이르게 한 때에는 무기 또는 3년 이상의 징역에 처한다. 사망에 이르게 한 때에는 무기 또는 5년 이상의 징역에 처한다.', 1223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9163, '제189조(과실, 업무상과실, 중과실)', 1223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9164, '제190조(미수범) 제185조 내지 제187조의 미수범은 처벌한다.', 1223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9165, '제191조(예비, 음모) 제186조 또는 제187조의 죄를 범할 목적으로 예비 또는 음모한 자는 3년 이하의 징역에 처한다.', 1223);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9166, '제192조(먹는 물의 사용방해)', 1224);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9167, '제193조(수돗물의 사용방해)', 1224);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9168, '제194조(먹는 물 혼독치사상) 제192조제2항 또는 제193조제2항의 죄를 지어 사람을 상해에 이르게 한 경우에는 무기 또는 3년 이상의 징역에 처한다. 사망에 이르게 한 경우에는 무기 또는 5년 이상의 징역에 처한다.', 1224);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9169, '제195조(수도불통) 공중이 먹는 물을 공급하는 수도 그 밖의 시설을 손괴하거나 그 밖의 방법으로 불통(不通)하게 한 자는 1년 이상 10년 이하의 징역에 처한다.', 1224);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9170, '제196조(미수범) 제192조제2항, 제193조제2항과 전조의 미수범은 처벌한다.', 1224);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9171, '제197조(예비, 음모) 제192조제2항, 제193조제2항 또는 제195조의 죄를 범할 목적으로 예비 또는 음모한 자는 2년 이하의 징역에 처한다.', 1224);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9172, '제198조(아편 등의 제조 등) 아편, 몰핀 또는 그 화합물을 제조, 수입 또는 판매하거나 판매할 목적으로 소지한 자는 10년 이하의 징역에 처한다.', 1225);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9173, '제199조(아편흡식기의 제조 등) 아편을 흡식하는 기구를 제조, 수입 또는 판매하거나 판매할 목적으로 소지한 자는 5년 이하의 징역에 처한다.', 1225);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9174, '제200조(세관 공무원의 아편 등의 수입) 세관의 공무원이 아편, 몰핀이나 그 화합물 또는 아편흡식기구를 수입하거나 그 수입을 허용한 때에는 1년 이상의 유기징역에 처한다.', 1225);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9175, '제201조(아편흡식 등, 동장소제공)', 1225);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9176, '제202조(미수범) 전4조의 미수범은 처벌한다.', 1225);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9177, '제203조(상습범) 상습으로 전5조의 죄를 범한 때에는 각조에 정한 형의 2분의 1까지 가중한다.', 1225);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9178, '제204조(자격정지 또는 벌금의 병과) 제198조 내지 제203조의 경우에는 10년 이하의 자격정지 또는 2천만원 이하의 벌금을 병과할 수 있다. <개정 1995.12.29>', 1225);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9179, '제205조(아편 등의 소지) 아편, 몰핀이나 그 화합물 또는 아편흡식기구를 소지한 자는 1년 이하의 징역 또는 500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1225);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9180, '제206조(몰수, 추징) 본장의 죄에 제공한 아편, 몰핀이나 그 화합물 또는 아편흡식기구는 몰수한다. 그를 몰수하기 불능한 때에는 그 가액을 추징한다.', 1225);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9181, '제207조(통화의 위조 등)', 1226);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9182, '제208조(위조통화의 취득) 행사할 목적으로 위조 또는 변조한 제207조 기재의 통화를 취득한 자는 5년 이하의 징역 또는 1천500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1226);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9183, '제209조(자격정지 또는 벌금의 병과) 제207조 또는 제208조의 죄를 범하여 유기징역에 처할 경우에는 10년 이하의 자격정지 또는 2천만원 이하의 벌금을 병과할 수 있다. <개정 1995.12.29>', 1226);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9184, '제210조(위조통화 취득 후의 지정행사) 제207조에 기재한 통화를 취득한 후 그 사정을 알고 행사한 자는 2년 이하의 징역 또는 500만원 이하의 벌금에 처한다.', 1226);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9185, '제211조(통화유사물의 제조 등)', 1226);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9186, '제212조(미수범) 제207조, 제208조와 전조의 미수범은 처벌한다.', 1226);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9187, '제213조(예비, 음모) 제207조제1항 내지 제3항의 죄를 범할 목적으로 예비 또는 음모한 자는 5년 이하의 징역에 처한다. 단, 그 목적한 죄의 실행에 이르기 전에 자수한 때에는 그 형을 감경 또는 면제한다.', 1226);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9188, '제214조(유가증권의 위조 등)', 1227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9189, '제215조(자격모용에 의한 유가증권의 작성) 행사할 목적으로 타인의 자격을 모용하여 유가증권을 작성하거나 유가증권의 권리 또는 의무에 관한 사항을 기재한 자는 10년 이하의 징역에 처한다.', 1227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9190, '제216조(허위유가증권의 작성 등) 행사할 목적으로 허위의 유가증권을 작성하거나 유가증권에 허위사항을 기재한 자는 7년 이하의 징역 또는 3천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9191, '제217조(위조유가증권 등의 행사 등) 위조, 변조, 작성 또는 허위기재한 전3조 기재의 유가증권을 행사하거나 행사할 목적으로 수입 또는 수출한 자는 10년 이하의 징역에 처한다.', 1227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9192, '제218조(인지ㆍ우표의 위조등)', 1227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9193, '제219조(위조인지ㆍ우표등의 취득) 행사할 목적으로 위조 또는 변조한 대한민국 또는 외국의 인지, 우표 기타 우편요금을 표시하는 증표를 취득한 자는 3년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9194, '제220조(자격정지 또는 벌금의 병과) 제214조 내지 제219조의 죄를 범하여 징역에 처하는 경우에는 10년 이하의 자격정지 또는 2천만원 이하의 벌금을 병과할 수 있다.', 1227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9195, '제221조(소인말소) 행사할 목적으로 대한민국 또는 외국의 인지, 우표 기타 우편요금을 표시하는 증표의 소인 기타 사용의 표지를 말소한 자는 1년 이하의 징역 또는 300만원 이하의 벌금에 처한다.', 1227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9196, '제222조(인지ㆍ우표유사물의 제조 등)', 1227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9197, '제223조(미수범) 제214조 내지 제219조와 전조의 미수범은 처벌한다.', 1227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9198, '제224조(예비, 음모) 제214조, 제215조와 제218조제1항의 죄를 범할 목적으로 예비 또는 음모한 자는 2년 이하의 징역에 처한다.', 1227);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9199, '제225조(공문서등의 위조ㆍ변조) 행사할 목적으로 공무원 또는 공무소의 문서 또는 도화를 위조 또는 변조한 자는 10년 이하의 징역에 처한다. <개정 1995.12.29>', 1228);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9200, '제226조(자격모용에 의한 공문서 등의 작성) 행사할 목적으로 공무원 또는 공무소의 자격을 모용하여 문서 또는 도화를 작성한 자는 10년 이하의 징역에 처한다. <개정 1995.12.29>', 1228);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9201, '제227조(허위공문서작성등) 공무원이 행사할 목적으로 그 직무에 관하여 문서 또는 도화를 허위로 작성하거나 변개한 때에는 7년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.', 1228);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9202, '제227조의2(공전자기록위작ㆍ변작) 사무처리를 그르치게 할 목적으로 공무원 또는 공무소의 전자기록등 특수매체기록을 위작 또는 변작한 자는 10년 이하의 징역에 처한다.', 1228);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9203, '제228조(공정증서원본 등의 부실기재)', 1228);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9204, '제229조(위조등 공문서의 행사) 제225조 내지 제228조의 죄에 의하여 만들어진 문서, 도화, 전자기록등 특수매체기록, 공정증서원본, 면허증, 허가증, 등록증 또는 여권을 행사한 자는 그 각 죄에 정한 형에 처한다.', 1228);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9205, '제230조(공문서 등의 부정행사) 공무원 또는 공무소의 문서 또는 도화를 부정행사한 자는 2년 이하의 징역이나 금고 또는 500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1228);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9206, '제231조(사문서등의 위조ㆍ변조) 행사할 목적으로 권리ㆍ의무 또는 사실증명에 관한 타인의 문서 또는 도화를 위조 또는 변조한 자는 5년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1228);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9207, '제232조(자격모용에 의한 사문서의 작성) 행사할 목적으로 타인의 자격을 모용하여 권리ㆍ의무 또는 사실증명에 관한 문서 또는 도화를 작성한 자는 5년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1228);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9208, '제232조의2(사전자기록위작ㆍ변작) 사무처리를 그르치게 할 목적으로 권리ㆍ의무 또는 사실증명에 관한 타인의 전자기록등 특수매체기록을 위작 또는 변작한 자는 5년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 1228);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9209, '제233조(허위진단서등의 작성) 의사, 한의사, 치과의사 또는 조산사가 진단서, 검안서 또는 생사에 관한 증명서를 허위로 작성한 때에는 3년 이하의 징역이나 금고, 7년 이하의 자격정지 또는 3천만원 이하의 벌금에 처한다.', 1228);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9210, '제234조(위조사문서등의 행사) 제231조 내지 제233조의 죄에 의하여 만들어진 문서, 도화 또는 전자기록등 특수매체기록을 행사한 자는 그 각 죄에 정한 형에 처한다.', 1228);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9211, '제235조(미수범) 제225조 내지 제234조의 미수범은 처벌한다. <개정 1995.12.29>', 1228);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9212, '제236조(사문서의 부정행사) 권리ㆍ의무 또는 사실증명에 관한 타인의 문서 또는 도화를 부정행사한 자는 1년 이하의 징역이나 금고 또는 300만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1228);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9213, '제237조(자격정지의 병과) 제225조 내지 제227조의2 및 그 행사죄를 범하여 징역에 처할 경우에는 10년 이하의 자격정지를 병과할 수 있다. <개정 1995.12.29>', 1228);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9214, '제237조의2(복사문서등) 이 장의 죄에 있어서 전자복사기, 모사전송기 기타 이와 유사한 기기를 사용하여 복사한 문서 또는 도화의 사본도 문서 또는 도화로 본다.', 1228);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9215, '제238조(공인 등의 위조, 부정사용)', 1229);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9216, '제239조(사인등의 위조, 부정사용)', 1229);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9217, '제240조(미수범) 본장의 미수범은 처벌한다.', 1229);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9218, '제241조 삭제 <2016.1.6>', 1230);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9219, '제242조(음행매개) 영리의 목적으로 사람을 매개하여 간음하게 한 자는 3년 이하의 징역 또는 1천500만원 이하의 벌금에 처한다. <개정 1995.12.29, 2012.12.18>', 1230);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9220, '제243조(음화반포등) 음란한 문서, 도화, 필름 기타 물건을 반포, 판매 또는 임대하거나 공연히 전시 또는 상영한 자는 1년 이하의 징역 또는 500만원 이하의 벌금에 처한다.', 1230);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9221, '제244조(음화제조 등) 제243조의 행위에 공할 목적으로 음란한 물건을 제조, 소지, 수입 또는 수출한 자는 1년 이하의 징역 또는 500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1230);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9222, '제245조(공연음란) 공연히 음란한 행위를 한 자는 1년 이하의 징역, 500만원 이하의 벌금, 구류 또는 과료에 처한다. <개정 1995.12.29>', 1230);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9223, '제246조(도박, 상습도박)', 1231);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9224, '제247조(도박장소 등 개설) 영리의 목적으로 도박을 하는 장소나 공간을 개설한 사람은 5년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.', 1231);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9225, '제248조(복표의 발매 등)', 1231);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9226, '제249조(벌금의 병과) 제246조제2항, 제247조와 제248조제1항의 죄에 대하여는 1천만원 이하의 벌금을 병과할 수 있다.', 1231);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9227, '제250조(살인, 존속살해)', 1232);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9228, '제251조 삭제 <2023.8.8>', 1232);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9229, '제252조(촉탁, 승낙에 의한 살인 등)', 1232);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9230, '제253조(위계 등에 의한 촉탁살인 등) 전조의 경우에 위계 또는 위력으로써 촉탁 또는 승낙하게 하거나 자살을 결의하게 한 때에는 제250조의 예에 의한다.', 1232);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9231, '제254조(미수범) 제250조, 제252조 및 제253조의 미수범은 처벌한다.', 1232);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9232, '제255조(예비, 음모) 제250조와 제253조의 죄를 범할 목적으로 예비 또는 음모한 자는 10년 이하의 징역에 처한다.', 1232);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9233, '제256조(자격정지의 병과) 제250조, 제252조 또는 제253조의 경우에 유기징역에 처할 때에는 10년 이하의 자격정지를 병과할 수 있다.', 1232);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9234, '제257조(상해, 존속상해)', 1233);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9235, '제258조(중상해, 존속중상해)', 1233);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9236, '제258조의2(특수상해)', 1233);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9237, '제259조(상해치사)', 1233);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9238, '제260조(폭행, 존속폭행)', 1233);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9239, '제261조(특수폭행) 단체 또는 다중의 위력을 보이거나 위험한 물건을 휴대하여 제260조제1항 또는 제2항의 죄를 범한 때에는 5년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1233);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9240, '제262조(폭행치사상) 제260조와 제261조의 죄를 지어 사람을 사망이나 상해에 이르게 한 경우에는 제257조부터 제259조까지의 예에 따른다.', 1233);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9241, '제263조(동시범) 독립행위가 경합하여 상해의 결과를 발생하게 한 경우에 있어서 원인된 행위가 판명되지 아니한 때에는 공동정범의 예에 의한다.', 1233);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9242, '제264조(상습범) 상습으로 제257조, 제258조, 제258조의2, 제260조 또는 제261조의 죄를 범한 때에는 그 죄에 정한 형의 2분의 1까지 가중한다. <개정 2016.1.6>', 1233);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9243, '제265조(자격정지의 병과) 제257조제2항, 제258조, 제258조의2, 제260조제2항, 제261조 또는 전조의 경우에는 10년 이하의 자격정지를 병과할 수 있다. <개정 2016.1.6>', 1233);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9244, '제266조(과실치상)', 1234);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9245, '제267조(과실치사) 과실로 인하여 사람을 사망에 이르게 한 자는 2년 이하의 금고 또는 700만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1234);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9246, '제268조(업무상과실ㆍ중과실 치사상) 업무상과실 또는 중대한 과실로 사람을 사망이나 상해에 이르게 한 자는 5년 이하의 금고 또는 2천만원 이하의 벌금에 처한다.', 1234);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9247, '제269조(낙태)', 1235);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9248, '제270조(의사 등의 낙태, 부동의낙태)', 1235);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9249, '제271조(유기, 존속유기)', 1236);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9250, '제272조 삭제 <2023.8.8>', 1236);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9251, '제273조(학대, 존속학대)', 1236);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9252, '제274조(아동혹사) 자기의 보호 또는 감독을 받는 16세 미만의 자를 그 생명 또는 신체에 위험한 업무에 사용할 영업자 또는 그 종업자에게 인도한 자는 5년 이하의 징역에 처한다. 그 인도를 받은 자도 같다.', 1236);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9253, '제275조(유기등 치사상)', 1236);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9254, '제276조(체포, 감금, 존속체포, 존속감금)', 1237);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9255, '제277조(중체포, 중감금, 존속중체포, 존속중감금)', 1237);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9256, '제278조(특수체포, 특수감금) 단체 또는 다중의 위력을 보이거나 위험한 물건을 휴대하여 전 2조의 죄를 범한 때에는 그 죄에 정한 형의 2분의 1까지 가중한다.', 1237);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9257, '제279조(상습범) 상습으로 제276조 또는 제277조의 죄를 범한 때에는 전조의 예에 의한다.', 1237);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9258, '제280조(미수범) 전4조의 미수범은 처벌한다.', 1237);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9259, '제281조(체포ㆍ감금등의 치사상)', 1237);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9260, '제282조(자격정지의 병과) 본장의 죄에는 10년 이하의 자격정지를 병과할 수 있다.', 1237);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9261, '제283조(협박, 존속협박)', 1238);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9262, '제284조(특수협박) 단체 또는 다중의 위력을 보이거나 위험한 물건을 휴대하여 전조제1항, 제2항의 죄를 범한 때에는 7년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1238);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9263, '제285조(상습범) 상습으로 제283조제1항, 제2항 또는 전조의 죄를 범한 때에는 그 죄에 정한 형의 2분의 1까지 가중한다.', 1238);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9264, '제286조(미수범) 전3조의 미수범은 처벌한다.', 1238);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9265, '제287조(미성년자의 약취, 유인) 미성년자를 약취 또는 유인한 사람은 10년 이하의 징역에 처한다.', 1239);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9266, '제288조(추행 등 목적 약취, 유인 등)', 1239);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9267, '제289조(인신매매)', 1239);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9268, '제290조(약취, 유인, 매매, 이송 등 상해ㆍ치상)', 1239);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9269, '제291조(약취, 유인, 매매, 이송 등 살인ㆍ치사)', 1239);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9270, '제292조(약취, 유인, 매매, 이송된 사람의 수수ㆍ은닉 등)', 1239);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9271, '제293조 삭제 <2013.4.5>', 1239);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9272, '제294조(미수범) 제287조부터 제289조까지, 제290조제1항, 제291조제1항과 제292조제1항의 미수범은 처벌한다.', 1239);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9273, '제295조(벌금의 병과) 제288조부터 제291조까지, 제292조제1항의 죄와 그 미수범에 대하여는 5천만원 이하의 벌금을 병과할 수 있다.', 1239);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9274, '제295조의2(형의 감경) 제287조부터 제290조까지, 제292조와 제294조의 죄를 범한 사람이 약취, 유인, 매매 또는 이송된 사람을 안전한 장소로 풀어준 때에는 그 형을 감경할 수 있다.', 1239);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9275, '제296조(예비, 음모) 제287조부터 제289조까지, 제290조제1항, 제291조제1항과 제292조제1항의 죄를 범할 목적으로 예비 또는 음모한 사람은 3년 이하의 징역에 처한다.', 1239);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9276, '제296조의2(세계주의) 제287조부터 제292조까지 및 제294조는 대한민국 영역 밖에서 죄를 범한 외국인에게도 적용한다.', 1239);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9277, '제297조(강간) 폭행 또는 협박으로 사람을 강간한 자는 3년 이상의 유기징역에 처한다. <개정 2012.12.18>', 1240);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9278, '제297조의2(유사강간) 폭행 또는 협박으로 사람에 대하여 구강, 항문 등 신체(성기는 제외한다)의 내부에 성기를 넣거나 성기, 항문에 손가락 등 신체(성기는 제외한다)의 일부 또는 도구를 넣는 행위를 한 사람은 2년 이상의 유기징역에 처한다.', 1240);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9279, '제298조(강제추행) 폭행 또는 협박으로 사람에 대하여 추행을 한 자는 10년 이하의 징역 또는 1천500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1240);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9280, '제299조(준강간, 준강제추행) 사람의 심신상실 또는 항거불능의 상태를 이용하여 간음 또는 추행을 한 자는 제297조, 제297조의2 및 제298조의 예에 의한다. <개정 2012.12.18>', 1240);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9281, '제300조(미수범) 제297조, 제297조의2, 제298조 및 제299조의 미수범은 처벌한다. <개정 2012.12.18>', 1240);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9282, '제301조(강간 등 상해ㆍ치상) 제297조, 제297조의2 및 제298조부터 제300조까지의 죄를 범한 자가 사람을 상해하거나 상해에 이르게 한 때에는 무기 또는 5년 이상의 징역에 처한다. <개정 2012.12.18>', 1240);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9283, '제301조의2(강간등 살인ㆍ치사) 제297조, 제297조의2 및 제298조부터 제300조까지의 죄를 범한 자가 사람을 살해한 때에는 사형 또는 무기징역에 처한다. 사망에 이르게 한 때에는 무기 또는 10년 이상의 징역에 처한다. <개정 2012.12.18>', 1240);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9284, '제302조(미성년자 등에 대한 간음) 미성년자 또는 심신미약자에 대하여 위계 또는 위력으로써 간음 또는 추행을 한 자는 5년 이하의 징역에 처한다.', 1240);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9285, '제303조(업무상위력 등에 의한 간음)', 1240);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9286, '제304조 삭제 <2012.12.18>', 1240);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9287, '제305조(미성년자에 대한 간음, 추행)', 1240);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9288, '제305조의2(상습범) 상습으로 제297조, 제297조의2, 제298조부터 제300조까지, 제302조, 제303조 또는 제305조의 죄를 범한 자는 그 죄에 정한 형의 2분의 1까지 가중한다. <개정 2012.12.18>', 1240);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9289, '제305조의3(예비, 음모) 제297조, 제297조의2, 제299조(준강간죄에 한정한다), 제301조(강간 등 상해죄에 한정한다) 및 제305조의 죄를 범할 목적으로 예비 또는 음모한 사람은 3년 이하의 징역에 처한다.', 1240);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9290, '제306조 삭제 <2012.12.18>', 1240);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9291, '제307조(명예훼손)', 1241);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9292, '제308조(사자의 명예훼손) 공연히 허위의 사실을 적시하여 사자의 명예를 훼손한 자는 2년 이하의 징역이나 금고 또는 500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1241);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9293, '제309조(출판물 등에 의한 명예훼손)', 1241);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9294, '제310조(위법성의 조각) 제307조제1항의 행위가 진실한 사실로서 오로지 공공의 이익에 관한 때에는 처벌하지 아니한다.', 1241);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9295, '제311조(모욕) 공연히 사람을 모욕한 자는 1년 이하의 징역이나 금고 또는 200만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1241);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9296, '제312조(고소와 피해자의 의사)', 1241);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9297, '제313조(신용훼손) 허위의 사실을 유포하거나 기타 위계로써 사람의 신용을 훼손한 자는 5년 이하의 징역 또는 1천500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1242);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9298, '제314조(업무방해)', 1242);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9299, '제315조(경매, 입찰의 방해) 위계 또는 위력 기타 방법으로 경매 또는 입찰의 공정을 해한 자는 2년 이하의 징역 또는 700만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1242);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9300, '제316조(비밀침해)', 1243);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9301, '제317조(업무상비밀누설)', 1243);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9302, '제318조(고소) 본장의 죄는 고소가 있어야 공소를 제기할 수 있다. <개정 1995.12.29>', 1243);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9303, '제319조(주거침입, 퇴거불응)', 1244);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9304, '제320조(특수주거침입) 단체 또는 다중의 위력을 보이거나 위험한 물건을 휴대하여 전조의 죄를 범한 때에는 5년 이하의 징역에 처한다.', 1244);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9305, '제321조(주거ㆍ신체 수색) 사람의 신체, 주거, 관리하는 건조물, 자동차, 선박이나 항공기 또는 점유하는 방실을 수색한 자는 3년 이하의 징역에 처한다. <개정 1995.12.29>', 1244);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9306, '제322조(미수범) 본장의 미수범은 처벌한다.', 1244);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9307, '제323조(권리행사방해) 타인의 점유 또는 권리의 목적이 된 자기의 물건 또는 전자기록등 특수매체기록을 취거, 은닉 또는 손괴하여 타인의 권리행사를 방해한 자는 5년 이하의 징역 또는 700만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1245);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9308, '제324조(강요)', 1245);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9309, '제324조의2(인질강요) 사람을 체포ㆍ감금ㆍ약취 또는 유인하여 이를 인질로 삼아 제3자에 대하여 권리행사를 방해하거나 의무없는 일을 하게 한 자는 3년 이상의 유기징역에 처한다.', 1245);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9310, '제324조의3(인질상해ㆍ치상) 제324조의2의 죄를 범한 자가 인질을 상해하거나 상해에 이르게 한 때에는 무기 또는 5년 이상의 징역에 처한다.', 1245);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9311, '제324조의4(인질살해ㆍ치사) 제324조의2의 죄를 범한 자가 인질을 살해한 때에는 사형 또는 무기징역에 처한다. 사망에 이르게 한 때에는 무기 또는 10년 이상의 징역에 처한다.', 1245);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9312, '제324조의5(미수범) 제324조 내지 제324조의4의 미수범은 처벌한다.', 1245);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9313, '제324조의6(형의 감경) 제324조의2 또는 제324조의3의 죄를 범한 자 및 그 죄의 미수범이 인질을 안전한 장소로 풀어준 때에는 그 형을 감경할 수 있다.', 1245);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9314, '제325조(점유강취, 준점유강취)', 1245);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9315, '제326조(중권리행사방해) 제324조 또는 제325조의 죄를 범하여 사람의 생명에 대한 위험을 발생하게 한 자는 10년 이하의 징역에 처한다. <개정 1995.12.29>', 1245);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9316, '제327조(강제집행면탈) 강제집행을 면할 목적으로 재산을 은닉, 손괴, 허위양도 또는 허위의 채무를 부담하여 채권자를 해한 자는 3년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1245);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9317, '제328조(친족간의 범행과 고소)', 1245);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9318, '제329조(절도) 타인의 재물을 절취한 자는 6년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9319, '제330조(야간주거침입절도) 야간에 사람의 주거, 관리하는 건조물, 선박, 항공기 또는 점유하는 방실(房室)에 침입하여 타인의 재물을 절취(竊取)한 자는 10년 이하의 징역에 처한다.', 1246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9320, '제331조(특수절도)', 1246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9321, '제331조의2(자동차등 불법사용) 권리자의 동의없이 타인의 자동차, 선박, 항공기 또는 원동기장치자전거를 일시 사용한 자는 3년 이하의 징역, 500만원 이하의 벌금, 구류 또는 과료에 처한다.', 1246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9322, '제332조(상습범) 상습으로 제329조 내지 제331조의2의 죄를 범한 자는 그 죄에 정한 형의 2분의 1까지 가중한다. <개정 1995.12.29>', 1246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9323, '제333조(강도) 폭행 또는 협박으로 타인의 재물을 강취하거나 기타 재산상의 이익을 취득하거나 제삼자로 하여금 이를 취득하게 한 자는 3년 이상의 유기징역에 처한다.', 1246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9324, '제334조(특수강도)', 1246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9325, '제335조(준강도) 절도가 재물의 탈환에 항거하거나 체포를 면탈하거나 범죄의 흔적을 인멸할 목적으로 폭행 또는 협박한 때에는 제333조 및 제334조의 예에 따른다.', 1246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9326, '제336조(인질강도) 사람을 체포ㆍ감금ㆍ약취 또는 유인하여 이를 인질로 삼아 재물 또는 재산상의 이익을 취득하거나 제3자로 하여금 이를 취득하게 한 자는 3년 이상의 유기징역에 처한다.', 1246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9327, '제337조(강도상해, 치상) 강도가 사람을 상해하거나 상해에 이르게 한때에는 무기 또는 7년 이상의 징역에 처한다. <개정 1995.12.29>', 1246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9328, '제338조(강도살인ㆍ치사) 강도가 사람을 살해한 때에는 사형 또는 무기징역에 처한다. 사망에 이르게 한 때에는 무기 또는 10년 이상의 징역에 처한다.', 1246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9329, '제339조(강도강간) 강도가 사람을 강간한 때에는 무기 또는 10년 이상의 징역에 처한다. <개정 2012.12.18>', 1246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9330, '제340조(해상강도)', 1246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9331, '제341조(상습범) 상습으로 제333조, 제334조, 제336조 또는 전조제1항의 죄를 범한 자는 무기 또는 10년 이상의 징역에 처한다.', 1246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9332, '제342조(미수범) 제329조 내지 제341조의 미수범은 처벌한다.', 1246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9333, '제343조(예비, 음모) 강도할 목적으로 예비 또는 음모한 자는 7년 이하의 징역에 처한다.', 1246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9334, '제344조(친족간의 범행) 제328조의 규정은 제329조 내지 제332조의 죄 또는 미수범에 준용한다.', 1246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9335, '제345조(자격정지의 병과) 본장의 죄를 범하여 유기징역에 처할 경우에는 10년 이하의 자격정지를 병과할 수 있다.', 1246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9336, '제346조(동력) 본장의 죄에 있어서 관리할 수 있는 동력은 재물로 간주한다.', 1246);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9337, '제347조(사기)', 1247);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9338, '제347조의2(컴퓨터등 사용사기) 컴퓨터등 정보처리장치에 허위의 정보 또는 부정한 명령을 입력하거나 권한 없이 정보를 입력ㆍ변경하여 정보처리를 하게 함으로써 재산상의 이익을 취득하거나 제3자로 하여금 취득하게 한 자는 10년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.', 1247);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9339, '제348조(준사기)', 1247);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9340, '제348조의2(편의시설부정이용) 부정한 방법으로 대가를 지급하지 아니하고 자동판매기, 공중전화 기타 유료자동설비를 이용하여 재물 또는 재산상의 이익을 취득한 자는 3년 이하의 징역, 500만원 이하의 벌금, 구류 또는 과료에 처한다.', 1247);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9341, '제349조(부당이득)', 1247);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9342, '제350조(공갈)', 1247);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9343, '제350조의2(특수공갈) 단체 또는 다중의 위력을 보이거나 위험한 물건을 휴대하여 제350조의 죄를 범한 자는 1년 이상 15년 이하의 징역에 처한다.', 1247);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9344, '제351조(상습범) 상습으로 제347조 내지 전조의 죄를 범한 자는 그 죄에 정한 형의 2분의 1까지 가중한다.', 1247);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9345, '제352조(미수범) 제347조 내지 제348조의2, 제350조, 제350조의2와 제351조의 미수범은 처벌한다. <개정 2016.1.6>', 1247);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9346, '제353조(자격정지의 병과) 본장의 죄에는 10년 이하의 자격정지를 병과할 수 있다.', 1247);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9347, '제354조(친족간의 범행, 동력) 제328조와 제346조의 규정은 본장의 죄에 준용한다.', 1247);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9348, '제355조(횡령, 배임)', 1248);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9349, '제356조(업무상의 횡령과 배임) 업무상의 임무에 위배하여 제355조의 죄를 범한 자는 10년 이하의 징역 또는 3천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1248);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9350, '제357조(배임수증재)', 1248);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9351, '제358조(자격정지의 병과) 전3조의 죄에는 10년 이하의 자격정지를 병과할 수 있다.', 1248);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9352, '제359조(미수범) 제355조 내지 제357조의 미수범은 처벌한다.', 1248);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9353, '제360조(점유이탈물횡령)', 1248);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9354, '제361조(친족간의 범행, 동력) 제328조와 제346조의 규정은 본장의 죄에 준용한다.', 1248);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9355, '제362조(장물의 취득, 알선 등)', 1249);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9356, '제363조(상습범)', 1249);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9357, '제364조(업무상과실, 중과실) 업무상과실 또는 중대한 과실로 인하여 제362조의 죄를 범한 자는 1년 이하의 금고 또는 500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1249);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9358, '제365조(친족간의 범행)', 1249);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9359, '제366조(재물손괴등) 타인의 재물, 문서 또는 전자기록등 특수매체기록을 손괴 또는 은닉 기타 방법으로 기 효용을 해한 자는 3년이하의 징역 또는 700만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9360, '제367조(공익건조물파괴) 공익에 공하는 건조물을 파괴한 자는 10년 이하의 징역 또는 2천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9361, '제368조(중손괴)', 1250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9362, '제369조(특수손괴)', 1250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9363, '제370조(경계침범) 경계표를 손괴, 이동 또는 제거하거나 기타 방법으로 토지의 경계를 인식 불능하게 한 자는 3년 이하의 징역 또는 500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 1250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9364, '제371조(미수범) 제366조, 제367조와 제369조의 미수범은 처벌한다.', 1250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9365, '제372조(동력) 본장의 죄에는 제346조를 준용한다.', 1250);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9366, '제1조(목적) 이 법은 수형자의 교정교화와 건전한 사회복귀를 도모하고, 수용자의 처우와 권리 및 교정시설의 운영에 관하여 필요한 사항을 규정함을 목적으로 한다.', 1251);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9367, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다. <개정 2016.12.2>', 1251);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9368, '제3조(적용범위) 이 법은 교정시설의 구내와 교도관이 수용자를 계호(戒護)하고 있는 그 밖의 장소로서 교도관의 통제가 요구되는 공간에 대하여 적용한다.', 1251);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9369, '제4조(인권의 존중) 이 법을 집행하는 때에 수용자의 인권은 최대한으로 존중되어야 한다.', 1251);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9370, '제5조(차별금지) 수용자는 합리적인 이유 없이 성별, 종교, 장애, 나이, 사회적 신분, 출신지역, 출신국가, 출신민족, 용모 등 신체조건, 병력(病歷), 혼인 여부, 정치적 의견 및 성적(性的) 지향 등을 이유로 차별받지 아니한다.', 1251);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9371, '제5조의2(기본계획의 수립)', 1251);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9372, '제5조의3(협의체의 설치 및 운영)', 1251);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9373, '제6조(교정시설의 규모 및 설비)', 1251);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9374, '제7조(교정시설 설치ㆍ운영의 민간위탁)', 1251);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9375, '제8조(교정시설의 순회점검) 법무부장관은 교정시설의 운영, 교도관의 복무, 수용자의 처우 및 인권실태 등을 파악하기 위하여 매년 1회 이상 교정시설을 순회점검하거나 소속 공무원으로 하여금 순회점검하게 하여야 한다. <개정 2016.5.29>', 1251);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9376, '제9조(교정시설의 시찰 및 참관)', 1251);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9377, '제10조(교도관의 직무) 이 법에 규정된 사항 외에 교도관의 직무에 관하여는 따로 법률로 정한다.', 1251);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9378, '제11조(구분수용)', 1253);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9379, '제12조(구분수용의 예외)', 1253);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9380, '제13조(분리수용)', 1253);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9381, '제14조(독거수용) 수용자는 독거수용한다. 다만, 다음 각 호의 어느 하나에 해당하는 사유가 있으면 혼거수용할 수 있다.', 1253);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9382, '제15조(수용거실 지정) 소장은 수용자의 거실을 지정하는 경우에는 죄명ㆍ형기ㆍ죄질ㆍ성격ㆍ범죄전력ㆍ나이ㆍ경력 및 수용생활 태도, 그 밖에 수용자의 개인적 특성을 고려하여야 한다.', 1253);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9383, '제16조(신입자의 수용 등)', 1253);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9384, '제16조의2(간이입소절차) 다음 각 호의 어느 하나에 해당하는 신입자의 경우에는 법무부장관이 정하는 바에 따라 간이입소절차를 실시한다.', 1253);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9385, '제17조(고지사항) 신입자 및 다른 교정시설로부터 이송되어 온 사람에게는 말이나 서면으로 다음 각 호의 사항을 알려 주어야 한다. <개정 2020.2.4>', 1253);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9386, '제18조(수용의 거절)', 1253);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9387, '제19조(사진촬영 등)', 1253);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9388, '제20조(수용자의 이송)', 1253);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9389, '제21조(수용사실의 알림) 소장은 신입자 또는 다른 교정시설로부터 이송되어 온 사람이 있으면 그 사실을 수용자의 가족(배우자, 직계 존속ㆍ비속 또는 형제자매를 말한다. 이하 같다)에게 지체 없이 알려야 한다. 다만, 수용자가 알리는 것을 원하지 아니하면 그러하지 아니하다. <개정 2020.2.4>', 1253);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9390, '제22조(의류 및 침구 등의 지급)', 1254);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9391, '제23조(음식물의 지급)', 1254);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9392, '제24조(물품의 자비구매)', 1254);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9393, '제25조(휴대금품의 보관 등)', 1255);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9394, '제26조(수용자가 지니는 물품 등)', 1255);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9395, '제27조(수용자에 대한 금품 전달)', 1255);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9396, '제28조(유류금품의 처리)', 1255);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9397, '제29조(보관금품의 반환 등)', 1255);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9398, '제30조(위생ㆍ의료 조치의무) 소장은 수용자가 건강한 생활을 하는 데에 필요한 위생 및 의료상의 적절한 조치를 하여야 한다.', 1256);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9399, '제31조(청결유지) 소장은 수용자가 사용하는 모든 설비와 기구가 항상 청결하게 유지되도록 하여야 한다.', 1256);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9400, '제32조(청결의무)', 1256);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9401, '제33조(운동 및 목욕)', 1256);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9402, '제34조(건강검진)', 1256);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9403, '제35조(감염병 등에 관한 조치) 소장은 감염병이나 그 밖에 감염의 우려가 있는 질병의 발생과 확산을 방지하기 위하여 필요한 경우 수용자에 대하여 예방접종ㆍ격리수용ㆍ이송, 그 밖에 필요한 조치를 하여야 한다. <개정 2016.12.2>', 1256);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9404, '제36조(부상자 등 치료)', 1256);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9405, '제37조(외부의료시설 진료 등)', 1256);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9406, '제38조(자비치료) 소장은 수용자가 자신의 비용으로 외부의료시설에서 근무하는 의사(이하 "외부의사"라 한다)에게 치료받기를 원하면 교정시설에 근무하는 의사(공중보건의사를 포함하며, 이하 "의무관"이라 한다)의 의견을 고려하여 이를 허가할 수 있다.', 1256);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9407, '제39조(진료환경 등)', 1256);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9408, '제40조(수용자의 의사에 반하는 의료조치)', 1256);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9409, '제41조(접견)', 1257);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9410, '제42조(접견의 중지 등) 교도관은 접견 중인 수용자 또는 그 상대방이 다음 각 호의 어느 하나에 해당하면 접견을 중지할 수 있다.', 1257);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9411, '제43조(편지수수)', 1257);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9412, '제44조(전화통화)', 1257);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9413, '제45조(종교행사의 참석 등)', 1258);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9414, '제46조(도서비치 및 이용) 소장은 수용자의 지식함양 및 교양습득에 필요한 도서를 비치하고 수용자가 이용할 수 있도록 하여야 한다.', 1258);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9415, '제47조(신문등의 구독)', 1258);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9416, '제48조(라디오 청취와 텔레비전 시청)', 1258);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9417, '제49조(집필)', 1258);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9418, '제50조(여성수용자의 처우)', 1259);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9419, '제51조(여성수용자 처우 시의 유의사항)', 1259);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9420, '제52조(임산부인 수용자의 처우)', 1259);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9421, '제53조(유아의 양육)', 1259);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9422, '제53조의2(수용자의 미성년 자녀 보호에 대한 지원)', 1259);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9423, '제54조(수용자에 대한 특별한 처우)', 1259);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9424, '제55조(수형자 처우의 원칙) 수형자에 대하여는 교육ㆍ교화프로그램, 작업, 직업훈련 등을 통하여 교정교화를 도모하고 사회생활에 적응하는 능력을 함양하도록 처우하여야 한다.', 1261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9425, '제56조(개별처우계획의 수립 등)', 1261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9426, '제57조(처우)', 1261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9427, '제58조(외부전문가의 상담 등) 소장은 수형자의 교화 또는 건전한 사회복귀를 위하여 필요하면 교육학ㆍ교정학ㆍ범죄학ㆍ사회학ㆍ심리학ㆍ의학 등에 관한 학식 또는 교정에 관한 경험이 풍부한 외부전문가로 하여금 수형자에 대한 상담ㆍ심리치료 또는 생활지도 등을 하게 할 수 있다.', 1261);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9428, '제59조(분류심사)', 1262);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9429, '제60조(관계기관등에 대한 사실조회 등)', 1262);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9430, '제61조(분류전담시설) 법무부장관은 수형자를 과학적으로 분류하기 위하여 분류심사를 전담하는 교정시설을 지정ㆍ운영할 수 있다.', 1262);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9431, '제62조(분류처우위원회)', 1262);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9432, '제63조(교육)', 1263);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9433, '제64조(교화프로그램)', 1263);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9434, '제65조(작업의 부과)', 1264);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9435, '제66조(작업의무) 수형자는 자신에게 부과된 작업과 그 밖의 노역을 수행하여야 할 의무가 있다.', 1264);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9436, '제67조(신청에 따른 작업) 소장은 금고형 또는 구류형의 집행 중에 있는 사람에 대하여는 신청에 따라 작업을 부과할 수 있다.', 1264);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9437, '제68조(외부 통근 작업 등)', 1264);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9438, '제69조(직업능력개발훈련)', 1264);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9439, '제70조(집중근로에 따른 처우)', 1264);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9440, '제71조(작업시간 등)', 1264);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9441, '제72조(작업의 면제)', 1264);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9442, '제73조(작업수입 등)', 1264);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9443, '제74조(위로금ㆍ조위금)', 1264);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9444, '제75조(다른 보상ㆍ배상과의 관계) 위로금 또는 조위금을 지급받을 사람이 국가로부터 동일한 사유로 「민법」이나 그 밖의 법령에 따라 제74조의 위로금 또는 조위금에 상당하는 금액을 지급받은 경우에는 그 금액을 위로금 또는 조위금으로 지급하지 아니한다.', 1264);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9445, '제76조(위로금ㆍ조위금을 지급받을 권리의 보호)', 1264);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9446, '제77조(귀휴)', 1265);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9447, '제78조(귀휴의 취소) 소장은 귀휴 중인 수형자가 다음 각 호의 어느 하나에 해당하면 그 귀휴를 취소할 수 있다.', 1265);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9448, '제79조(미결수용자 처우의 원칙) 미결수용자는 무죄의 추정을 받으며 그에 합당한 처우를 받는다.', 1266);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9449, '제80조(참관금지) 미결수용자가 수용된 거실은 참관할 수 없다.', 1266);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9450, '제81조(분리수용) 소장은 미결수용자로서 사건에 서로 관련이 있는 사람은 분리수용하고 서로 간의 접촉을 금지하여야 한다.', 1266);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9451, '제82조(사복착용) 미결수용자는 수사ㆍ재판ㆍ국정감사 또는 법률로 정하는 조사에 참석할 때에는 사복을 착용할 수 있다. 다만, 소장은 도주우려가 크거나 특히 부적당한 사유가 있다고 인정하면 교정시설에서 지급하는 의류를 입게 할 수 있다.', 1266);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9452, '제83조(이발) 미결수용자의 머리카락과 수염은 특히 필요한 경우가 아니면 본인의 의사에 반하여 짧게 깎지 못한다. <개정 2020.2.4>', 1266);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9453, '제84조(변호인과의 접견 및 편지수수)', 1266);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9454, '제85조(조사 등에서의 특칙) 소장은 미결수용자가 징벌대상자로서 조사받고 있거나 징벌집행 중인 경우에도 소송서류의 작성, 변호인과의 접견ㆍ편지수수, 그 밖의 수사 및 재판 과정에서의 권리행사를 보장하여야 한다. <개정 2020.2.4>', 1266);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9455, '제86조(작업과 교화)', 1266);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9456, '제87조(유치장) 경찰관서에 설치된 유치장은 교정시설의 미결수용실로 보아 이 법을 준용한다.', 1266);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9457, '제88조(준용규정) 형사사건으로 수사 또는 재판을 받고 있는 수형자와 사형확정자에 대하여는 제82조, 제84조 및 제85조를 준용한다. <개정 2008.12.11, 2016.12.2>', 1266);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9458, '제89조(사형확정자의 수용)', 1267);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9459, '제90조(개인상담 등)', 1267);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9460, '제91조(사형의 집행)', 1267);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9461, '제92조(금지물품)', 1268);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9462, '제93조(신체검사 등)', 1268);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9463, '제94조(전자장비를 이용한 계호)', 1268);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9464, '제95조(보호실 수용)', 1268);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9465, '제96조(진정실 수용)', 1268);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9466, '제97조(보호장비의 사용)', 1268);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9467, '제98조(보호장비의 종류 및 사용요건)', 1268);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9468, '제99조(보호장비 남용 금지)', 1268);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9469, '제100조(강제력의 행사)', 1268);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9470, '제101조(무기의 사용)', 1268);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9471, '제102조(재난 시의 조치)', 1268);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9472, '제103조(수용을 위한 체포)', 1268);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9473, '제104조(마약류사범 등의 관리)', 1268);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9474, '제105조(규율 등)', 1269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9475, '제106조(포상) 소장은 수용자가 다음 각 호의 어느 하나에 해당하면 법무부령으로 정하는 바에 따라 포상할 수 있다.', 1269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9476, '제107조(징벌) 소장은 수용자가 다음 각 호의 어느 하나에 해당하는 행위를 하면 제111조의 징벌위원회의 의결에 따라 징벌을 부과할 수 있다. <개정 2019.4.23, 2020.2.4>', 1269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9477, '제108조(징벌의 종류) 징벌의 종류는 다음 각 호와 같다. <개정 2019.4.23, 2020.2.4>', 1269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9478, '제109조(징벌의 부과)', 1269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9479, '제110조(징벌대상자의 조사)', 1269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9480, '제111조(징벌위원회)', 1269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9481, '제111조의2(징벌대상행위에 관한 양형 참고자료 통보) 소장은 미결수용자에게 징벌을 부과한 경우에는 그 징벌대상행위를 양형(量刑) 참고자료로 작성하여 관할 검찰청 검사 또는 관할 법원에 통보할 수 있다.', 1269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9482, '제112조(징벌의 집행)', 1269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9483, '제113조(징벌집행의 정지ㆍ면제)', 1269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9484, '제114조(징벌집행의 유예)', 1269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9485, '제115조(징벌의 실효 등)', 1269);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9486, '제116조(소장 면담)', 1270);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9487, '제117조(청원)', 1270);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9488, '제117조의2(정보공개청구)', 1270);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9489, '제118조(불이익처우 금지) 수용자는 청원, 진정, 소장과의 면담, 그 밖의 권리구제를 위한 행위를 하였다는 이유로 불이익한 처우를 받지 아니한다.', 1270);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9490, '제119조(가석방심사위원회) 「형법」 제72조에 따른 가석방의 적격 여부를 심사하기 위하여 법무부장관 소속으로 가석방심사위원회(이하 이 장에서 "위원회"라 한다)를 둔다.', 1272);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9491, '제120조(위원회의 구성)', 1272);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9492, '제121조(가석방 적격심사)', 1272);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9493, '제122조(가석방 허가)', 1272);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9494, '제123조(석방) 소장은 사면ㆍ형기종료 또는 권한이 있는 사람의 명령에 따라 수용자를 석방한다. <개정 2020.2.4>', 1273);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9495, '제124조(석방시기)', 1273);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9496, '제125조(피석방자의 일시수용) 소장은 피석방자가 질병이나 그 밖에 피할 수 없는 사정으로 귀가하기 곤란한 경우에 본인의 신청이 있으면 일시적으로 교정시설에 수용할 수 있다.', 1273);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9497, '제126조(귀가여비의 지급 등) 소장은 피석방자에게 귀가에 필요한 여비 또는 의류가 없으면 법무부장관이 정하는 범위에서 이를 지급하거나 빌려 줄 수 있다.', 1273);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9498, '제126조의2(석방예정자의 수용이력 등 통보)', 1273);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9499, '제127조(사망 알림) 소장은 수용자가 사망한 경우에는 그 사실을 즉시 그 가족(가족이 없는 경우에는 다른 친족)에게 알려야 한다. <개정 2020.2.4>', 1274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9500, '제128조(시신의 인도 등)', 1274);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9501, '제129조(교정자문위원회)', 1275);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9502, '제130조(교정위원)', 1275);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9503, '제131조(기부금품의 접수) 소장은 기관ㆍ단체 또는 개인이 수용자의 교화 등을 위하여 교정시설에 자발적으로 기탁하는 금품을 받을 수 있다.', 1275);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9504, '제132조(금지물품을 지닌 경우)', 1276);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9505, '제133조(금지물품의 반입)', 1276);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9506, '제134조(출석의무 위반 등) 다음 각 호의 어느 하나에 해당하는 행위를 한 수용자는 1년 이하의 징역에 처한다. <개정 2020.2.4>', 1276);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9507, '제135조(녹화 등의 금지) 소장의 허가 없이 교정시설 내부를 녹화ㆍ촬영한 사람은 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 1276);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9508, '제136조(미수범) 제133조 및 제135조의 미수범은 처벌한다.', 1276);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9509, '제137조(몰수) 제132조 및 제133조에 해당하는 금지물품은 몰수한다.', 1276);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9510, '제1조(목적) 이 영은 「형의 집행 및 수용자의 처우에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 1277);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9511, '제1조의2(협의체의 구성 및 운영 등)', 1277);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9512, '제2조(판사 등의 시찰)', 1277);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9513, '제3조(참관)', 1277);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9514, '제4조(독거실의 비율) 교정시설을 새로 설치하는 경우에는 법 제14조에 따른 수용자의 거실수용을 위하여 독거실(獨居室)과 혼거실(混居室)의 비율이 적정한 수준이 되도록 한다.', 1279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9515, '제5조(독거수용의 구분) 독거수용은 다음 각 호와 같이 구분한다.', 1279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9516, '제6조(계호상 독거수용자의 시찰)', 1279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9517, '제7조(여성수용자에 대한 시찰) 소장은 특히 필요하다고 인정하는 경우가 아니면 남성교도관이 야간에 수용자거실에 있는 여성수용자를 시찰하게 하여서는 아니 된다.', 1279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9518, '제8조(혼거수용 인원의 기준) 혼거수용 인원은 3명 이상으로 한다. 다만, 요양이나 그 밖의 부득이한 사정이 있는 경우에는 예외로 한다.', 1279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9519, '제9조(혼거수용의 제한) 소장은 노역장 유치명령을 받은 수형자와 징역형ㆍ금고형 또는 구류형을 선고받아 형이 확정된 수형자를 혼거수용해서는 아니 된다. 다만, 징역형ㆍ금고형 또는 구류형의 집행을 마친 다음에 계속해서 노역장 유치명령을 집행하거나 그 밖에 부득이한 사정이 있는 경우에는 그러하지 아니하다.', 1279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9520, '제10조(수용자의 자리 지정) 소장은 수용자의 생명ㆍ신체의 보호, 증거인멸의 방지 및 교정시설의 안전과 질서유지를 위하여 필요하다고 인정하면 혼거실ㆍ교육실ㆍ강당ㆍ작업장, 그 밖에 수용자들이 서로 접촉할 수 있는 장소에서 수용자의 자리를 지정할 수 있다.', 1279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9521, '제11조(거실의 대용금지) 소장은 수용자거실을 작업장으로 사용해서는 아니 된다. 다만, 수용자의 심리적 안정, 교정교화 또는 사회적응능력 함양을 위하여 특히 필요하다고 인정하면 그러하지 아니하다.', 1279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9522, '제12조(현황표 등의 부착 등)', 1279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9523, '제13조(신입자의 인수)', 1279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9524, '제14조(신입자의 신체 등 검사) 소장은 신입자를 인수한 경우에는 교도관에게 신입자의 신체ㆍ의류 및 휴대품을 지체 없이 검사하게 하여야 한다.', 1279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9525, '제15조(신입자의 건강진단) 법 제16조제2항에 따른 신입자의 건강진단은 수용된 날부터 3일 이내에 하여야 한다. 다만, 휴무일이 연속되는 등 부득이한 사정이 있는 경우에는 예외로 한다.', 1279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9526, '제16조(신입자의 목욕) 소장은 신입자에게 질병이나 그 밖의 부득이한 사정이 있는 경우가 아니면 지체 없이 목욕을 하게 하여야 한다.', 1279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9527, '제17조(신입자의 신체 특징 기록 등)', 1279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9528, '제18조(신입자거실 수용 등)', 1279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9529, '제19조(수용기록부 등의 작성) 소장은 신입자 또는 이입자를 수용한 날부터 3일 이내에 수용기록부, 수용자명부 및 형기종료부를 작성ㆍ정비하고 필요한 사항을 기록하여야 한다.', 1279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9530, '제20조(신입자의 신원조사)', 1279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9531, '제21조(형 또는 구속의 집행정지 사유의 통보) 소장은 수용자에 대하여 건강상의 사유로 형의 집행정지 또는 구속의 집행정지를 할 필요가 있다고 인정하는 경우에는 의무관의 진단서와 인수인에 대한 확인서류를 첨부하여 그 사실을 검사에게, 기소된 상태인 경우에는 법원에도 지체 없이 통보하여야 한다.', 1279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9532, '제22조(지방교정청장의 이송승인권)', 1279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9533, '제23조(이송 중지) 소장은 수용자를 다른 교정시설에 이송하는 경우에 의무관으로부터 수용자가 건강상 감당하기 어렵다는 보고를 받으면 이송을 중지하고 그 사실을 이송받을 소장에게 알려야 한다.', 1279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9534, '제24조(호송 시 분리) 수용자를 이송이나 출정(出廷), 그 밖의 사유로 호송하는 경우에는 수형자는 미결수용자와, 여성수용자는 남성수용자와, 19세 미만의 수용자는 19세 이상의 수용자와 각각 호송 차량의 좌석을 분리하는 등의 방법으로 서로 접촉하지 못하게 하여야 한다.', 1279);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9535, '제25조(생활용품 지급 시의 유의사항)', 1280);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9536, '제26조(생활기구의 비치)', 1280);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9537, '제27조(음식물의 지급) 법 제23조에 따라 수용자에게 지급하는 음식물은 주식ㆍ부식ㆍ음료, 그 밖의 영양물로 한다.', 1280);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9538, '제28조(주식의 지급)', 1280);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9539, '제29조(특식의 지급) 소장은 국경일이나 그 밖에 이에 준하는 날에는 특별한 음식물을 지급할 수 있다.', 1280);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9540, '제30조(환자의 음식물) 소장은 의무관의 의견을 고려하여 환자에게 지급하는 음식물의 종류 또는 정도를 달리 정할 수 있다.', 1280);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9541, '제31조(자비 구매 물품의 기준) 수용자가 자비로 구매하는 물품은 교화 또는 건전한 사회복귀에 적합하고 교정시설의 안전과 질서를 해칠 우려가 없는 것이어야 한다.', 1280);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9542, '제32조(자비 구매 의류등의 사용) 소장은 수용자가 자비로 구매한 의류등을 보관한 후 그 수용자가 사용하게 할 수 있다. <개정 2020.8.5>', 1280);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9543, '제33조(의류등의 세탁 등)', 1280);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9544, '제34조(휴대금품의 정의 등)', 1281);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9545, '제35조(금품의 보관) 수용자의 현금을 보관하는 경우에는 그 금액을 보관금대장에 기록하고 수용자의 물품을 보관하는 경우에는 그 품목ㆍ수량 및 규격을 보관품대장에 기록해야 한다. <개정 2020.8.5>', 1281);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9546, '제36조(귀중품의 보관) 소장은 보관품이 금ㆍ은ㆍ보석ㆍ유가증권ㆍ인장, 그 밖에 특별히 보관할 필요가 있는 귀중품인 경우에는 잠금장치가 되어 있는 견고한 용기에 넣어 보관해야 한다. <개정 2020.8.5>', 1281);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9547, '제37조(보관품 매각대금의 보관) 소장은 수용자의 신청에 따라 보관품을 팔 경우에는 그 비용을 제외한 나머지 대금을 보관할 수 있다. <개정 2020.8.5>', 1281);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9548, '제38조(보관금의 사용 등)', 1281);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9549, '제39조(지닐 수 없는 물품의 처리) 법 제26조제2항 및 제3항에 따라 지닐 수 있는 범위를 벗어난 수용자의 물품을 처분하거나 폐기하는 경우에는 제34조제3항 및 제4항을 준용한다. <개정 2020.8.5>', 1281);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9550, '제40조(물품의 폐기) 수용자의 물품을 폐기하는 경우에는 그 품목ㆍ수량ㆍ이유 및 일시를 관계 장부에 기록하여야 한다.', 1281);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9551, '제41조(금품전달 신청자의 확인) 소장은 수용자가 아닌 사람이 법 제27조제1항에 따라 수용자에게 금품을 건네줄 것을 신청하는 경우에는 그의 성명ㆍ주소 및 수용자와의 관계를 확인해야 한다. <개정 2020.8.5>', 1281);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9552, '제42조(전달 허가금품의 사용 등)', 1281);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9553, '제43조(전달 허가물품의 검사) 소장은 법 제27조제1항에 따라 건네줄 것을 허가한 물품은 검사할 필요가 없다고 인정되는 경우가 아니면 교도관으로 하여금 검사하게 해야 한다. 이 경우 그 물품이 의약품인 경우에는 의무관으로 하여금 검사하게 해야 한다. <개정 2020.8.5>', 1281);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9554, '제44조(보관의 예외) 음식물은 보관의 대상이 되지 않는다. <개정 2020.8.5>', 1281);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9555, '제45조(유류금품의 처리)', 1281);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9556, '제46조(보건ㆍ위생관리계획의 수립 등) 소장은 수용자의 건강, 계절 및 시설여건 등을 고려하여 보건ㆍ위생관리계획을 정기적으로 수립하여 시행하여야 한다.', 1282);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9557, '제47조(시설의 청소ㆍ소독)', 1282);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9558, '제48조(청결의무) 수용자는 교도관이 법 제32조제1항에 따라 자신이 사용하는 거실, 작업장, 그 밖의 수용시설의 청결을 유지하기 위하여 필요한 지시를 한 경우에는 이에 따라야 한다.', 1282);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9559, '제49조(실외운동) 소장은 수용자가 매일(공휴일 및 법무부장관이 정하는 날은 제외한다) 「국가공무원 복무규정」 제9조에 따른 근무시간 내에서 1시간 이내의 실외운동을 할 수 있도록 하여야 한다. 다만, 다음 각 호의 어느 하나에 해당하면 실외운동을 실시하지 아니할 수 있다.', 1282);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9560, '제50조(목욕횟수) 소장은 작업의 특성, 계절, 그 밖의 사정을 고려하여 수용자의 목욕횟수를 정하되 부득이한 사정이 없으면 매주 1회 이상이 되도록 한다.', 1282);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9561, '제51조(건강검진횟수)', 1282);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9562, '제52조(감염병의 정의) 법 제18조제1항, 법 제53조제1항제3호 및 법 제128조제2항에서 "감염병"이란 「감염병의 예방 및 관리에 관한 법률」에 따른 감염병을 말한다. <개정 2010.12.29>', 1282);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9563, '제53조(감염병에 관한 조치)', 1282);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9564, '제54조(의료거실 수용 등) 소장은 수용자가 부상을 당하거나 질병에 걸린 경우에는 그 수용자를 의료거실에 수용하거나, 다른 수용자에게 그 수용자를 간병하게 할 수 있다.', 1282);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9565, '제54조의2(간호사의 의료행위) 법 제36조제2항에서 "대통령령으로 정하는 경미한 의료행위"란 다음 각 호의 의료행위를 말한다.', 1282);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9566, '제55조(외부의사의 치료) 소장은 특히 필요하다고 인정하면 외부 의료시설에서 근무하는 의사(이하 "외부의사"라 한다)에게 수용자를 치료하게 할 수 있다.', 1282);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9567, '제56조(위독 사실의 알림) 소장은 수용자가 위독한 경우에는 그 사실을 가족에게 지체 없이 알려야 한다.', 1282);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9568, '제57조(외부 의료시설 입원 등 보고) 소장은 법 제37조제1항에 따라 수용자를 외부 의료시설에 입원시키거나 입원 중인 수용자를 교정시설로 데려온 경우에는 그 사실을 법무부장관에게 지체 없이 보고하여야 한다.', 1282);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9569, '제58조(접견)', 1283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9570, '제59조(접견의 예외)', 1283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9571, '제59조의2(변호사 와의 접견)', 1283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9572, '제60조(접견 시 외국어 사용)', 1283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9573, '제61조(접견 시 유의사항 고지) 소장은 법 제41조에 따라 접견을 하게 하는 경우에는 수용자와 그 상대방에게 접견 시 유의사항을 방송이나 게시물 부착 등 적절한 방법으로 알려줘야 한다.', 1283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9574, '제62조(접견내용의 청취ㆍ기록ㆍ녹음ㆍ녹화)', 1283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9575, '제63조(접견중지 사유의 고지) 교도관이 법 제42조에 따라 수용자의 접견을 중지한 경우에는 그 사유를 즉시 알려주어야 한다.', 1283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9576, '제64조(편지수수의 횟수) 수용자가 보내거나 받는 편지는 법령에 어긋나지 않으면 횟수를 제한하지 않는다. <개정 2020.8.5>', 1283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9577, '제65조(편지 내용물의 확인)', 1283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9578, '제66조(편지 내용의 검열)', 1283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9579, '제67조(관계기관 송부문서) 소장은 법원ㆍ경찰관서, 그 밖의 관계기관에서 수용자에게 보내온 문서는 다른 법령에 특별한 규정이 없으면 열람한 후 본인에게 전달하여야 한다.', 1283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9580, '제68조(편지 등의 대서) 소장은 수용자가 편지, 소송서류, 그 밖의 문서를 스스로 작성할 수 없어 대신 써 달라고 요청하는 경우에는 교도관이 대신 쓰게 할 수 있다. <개정 2020.8.5>', 1283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9581, '제69조(편지 등 발송비용의 부담) 수용자의 편지ㆍ소송서류, 그 밖의 문서를 보내는 경우에 드는 비용은 수용자가 부담한다. 다만, 소장은 수용자가 그 비용을 부담할 수 없는 경우에는 예산의 범위에서 해당 비용을 부담할 수 있다. <개정 2014.6.25, 2020.8.5>', 1283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9582, '제70조(전화통화) 수용자의 전화통화에 관하여는 제60조제1항 및 제63조를 준용한다.', 1283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9583, '제71조(참고사항의 기록) 교도관은 수용자의 접견, 편지수수, 전화통화 등의 과정에서 수용자의 처우에 특히 참고할 사항을 알게 된 경우에는 그 요지를 수용기록부에 기록해야 한다. <개정 2020.8.5>', 1283);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9584, '제72조(비치도서의 이용)', 1284);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9585, '제73조(라디오 청취 등의 방법) 법 제48조제1항에 따른 수용자의 라디오 청취와 텔레비전 시청은 교정시설에 설치된 방송설비를 통하여 할 수 있다.', 1284);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9586, '제74조(집필용구의 구입비용) 집필용구의 구입비용은 수용자가 부담한다. 다만, 소장은 수용자가 그 비용을 부담할 수 없는 경우에는 필요한 집필용구를 지급할 수 있다.', 1284);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9587, '제75조(집필의 시간대ㆍ시간 및 장소)', 1284);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9588, '제76조(문서ㆍ도화의 외부 발송 등)', 1284);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9589, '제77조(여성수용자의 목욕)', 1285);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9590, '제78조(출산의 범위) 법 제52조제1항에서 "출산(유산ㆍ사산을 포함한다)한 경우"란 출산(유산ㆍ사산한 경우를 포함한다) 후 60일이 지나지 아니한 경우를 말한다. <개정 2019.10.22>', 1285);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9591, '제79조(유아의 양육) 소장은 법 제53조제1항에 따라 유아의 양육을 허가한 경우에는 교정시설에 육아거실을 지정ㆍ운영하여야 한다.', 1285);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9592, '제80조(유아의 인도)', 1285);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9593, '제81조(노인수용자 등의 정의)', 1285);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9594, '제82조(수형자로서의 처우 개시)', 1287);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9595, '제83조(경비등급별 설비 및 계호) 법 제57조제2항 각 호의 수용설비 및 계호의 정도는 다음 각 호의 규정에 어긋나지 않는 범위에서 법무부장관이 정한다.', 1287);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9596, '제84조(수형자의 처우등급 부여 등)', 1287);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9597, '제85조(수형자 취업알선 등 협의기구)', 1287);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9598, '제86조(분류전담시설) 법무부장관은 법 제61조의 분류심사를 전담하는 교정시설을 지정ㆍ운영하는 경우에는 지방교정청별로 1개소 이상이 되도록 하여야 한다.', 1288);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9599, '제87조(교육)', 1289);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9600, '제88조(정서교육) 소장은 수형자의 정서 함양을 위하여 필요하다고 인정하면 연극ㆍ영화관람, 체육행사, 그 밖의 문화예술활동을 하게 할 수 있다.', 1289);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9601, '제89조(작업의 종류) 소장은 법무부장관의 승인을 받아 수형자에게 부과하는 작업의 종류를 정한다.', 1290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9602, '제90조(소년수형자의 작업 등) 소장은 19세 미만의 수형자에게 작업을 부과하는 경우에는 정신적ㆍ신체적 성숙 정도, 교육적 효과 등을 고려하여야 한다.', 1290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9603, '제91조(작업의 고지 등)', 1290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9604, '제92조(작업실적의 확인) 소장은 교도관에게 매일 수형자의 작업실적을 확인하게 하여야 한다.', 1290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9605, '제93조(신청 작업의 취소) 소장은 법 제67조에 따라 작업이 부과된 수형자가 작업의 취소를 요청하는 경우에는 그 수형자의 의사(意思), 건강 및 교도관의 의견 등을 고려하여 작업을 취소할 수 있다.', 1290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9606, '제94조(직업능력개발훈련 설비 등의 구비) 소장은 법 제69조에 따른 직업능력개발훈련을 하는 경우에는 그에 필요한 설비 및 실습 자재를 갖추어야 한다.', 1290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9607, '제95조(집중근로) 법 제70조제1항에서 "집중적인 근로가 필요한 작업"이란 수형자의 신청에 따라 1일 작업시간 중 접견ㆍ전화통화ㆍ교육 및 공동행사 참가 등을 하지 아니하고 휴게시간을 제외한 작업시간 내내 하는 작업을 말한다.', 1290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9608, '제96조(휴업일) 법 제71조에서 "그 밖의 휴일"이란 「각종 기념일 등에 관한 규정」에 따른 교정의 날 및 소장이 특히 지정하는 날을 말한다. <개정 2017.9.19>', 1290);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9609, '제97조(귀휴자에 대한 조치)', 1291);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9610, '제98조(미결수용시설의 설비 및 계호의 정도) 미결수용자를 수용하는 시설의 설비 및 계호의 정도는 법 제57조제2항제3호의 일반경비시설에 준한다.', 1292);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9611, '제99조(법률구조 지원) 소장은 미결수용자가 빈곤하거나 무지하여 수사 및 재판 과정에서 권리를 충분히 행사하지 못한다고 인정하는 경우에는 법률구조에 필요한 지원을 할 수 있다.', 1292);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9612, '제100조(공범 분리) 소장은 이송이나 출정, 그 밖의 사유로 미결수용자를 교정시설 밖으로 호송하는 경우에는 해당 사건에 관련된 사람과 호송 차량의 좌석을 분리하는 등의 방법으로 서로 접촉하지 못하게 하여야 한다.', 1292);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9613, '제101조(접견 횟수) 미결수용자의 접견 횟수는 매일 1회로 하되, 변호인과의 접견은 그 횟수에 포함시키지 않는다.', 1292);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9614, '제102조(접견의 예외) 소장은 미결수용자의 처우를 위하여 특히 필요하다고 인정하면 제58조제1항에도 불구하고 접견 시간대 외에도 접견하게 할 수 있고, 변호인이 아닌 사람과 접견하는 경우에도 제58조제2항 및 제101조에도 불구하고 접견시간을 연장하거나 접견 횟수를 늘릴 수 있다. <개정 2019.10.22>', 1292);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9615, '제103조(교육ㆍ교화와 작업)', 1292);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9616, '제104조(도주 등 통보) 소장은 미결수용자가 도주하거나 도주한 미결수용자를 체포한 경우에는 그 사실을 검사에게 통보하고, 기소된 상태인 경우에는 법원에도 지체 없이 통보하여야 한다.', 1292);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9617, '제105조(사망 등 통보) 소장은 미결수용자가 위독하거나 사망한 경우에는 그 사실을 검사에게 통보하고, 기소된 상태인 경우에는 법원에도 지체 없이 통보하여야 한다.', 1292);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9618, '제106조(외부의사의 진찰 등) 미결수용자가 「형사소송법」 제34조, 제89조 및 제209조에 따라 외부의사의 진료를 받는 경우에는 교도관이 참여하고 그 경과를 수용기록부에 기록하여야 한다.', 1292);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9619, '제107조(유치장 수용기간) 경찰관서에 설치된 유치장에는 수형자를 30일 이상 수용할 수 없다.', 1292);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9620, '제108조(사형확정자 수용시설의 설비 및 계호의 정도) 사형확정자를 수용하는 시설의 설비 및 계호의 정도는 법 제57조제2항제3호의 일반경비시설 또는 같은 항 제4호의 중경비시설에 준한다. <개정 2017.9.19>', 1293);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9621, '제109조(접견 횟수) 사형확정자의 접견 횟수는 매월 4회로 한다.', 1293);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9622, '제110조(접견의 예외) 소장은 제58조제1항ㆍ제2항 및 제109조에도 불구하고 사형확정자의 교화나 심리적 안정을 도모하기 위하여 특히 필요하다고 인정하면 접견 시간대 외에도 접견을 하게 할 수 있고 접견시간을 연장하거나 접견 횟수를 늘릴 수 있다. <개정 2019.10.22>', 1293);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9623, '제111조(사형집행 후의 검시) 소장은 사형을 집행하였을 경우에는 시신을 검사한 후 5분이 지나지 아니하면 교수형에 사용한 줄을 풀지 못한다. <개정 2014.6.25>', 1293);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9624, '제112조(거실 등에 대한 검사) 소장은 교도관에게 수용자의 거실, 작업장, 그 밖에 수용자가 생활하는 장소(이하 이 조에서 "거실등"이라 한다)를 정기적으로 검사하게 하여야 한다. 다만, 법 제92조의 금지물품을 숨기고 있다고 의심되는 수용자와 법 제104조제1항의 마약류사범ㆍ조직폭력사범 등 법무부령으로 정하는 수용자의 거실등은 수시로 검사하게 할 수 있다.', 1294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9625, '제113조(신체 등에 대한 검사) 소장은 교도관에게 작업장이나 실외에서 수용자거실로 돌아오는 수용자의 신체ㆍ의류 및 휴대품을 검사하게 하여야 한다. 다만, 교정성적 등을 고려하여 그 검사가 필요하지 아니하다고 인정되는 경우에는 예외로 할 수 있다.', 1294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9626, '제114조(검사장비의 이용) 교도관은 법 제93조에 따른 검사를 위하여 탐지견, 금속탐지기, 그 밖의 장비를 이용할 수 있다.', 1294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9627, '제115조(외부인의 출입)', 1294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9628, '제116조(외부와의 차단)', 1294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9629, '제117조(거실 개문 등 제한) 교도관은 수사ㆍ재판ㆍ운동ㆍ접견ㆍ진료 등 수용자의 처우 또는 자살방지, 화재진압 등 교정시설의 안전과 질서유지를 위하여 필요한 경우가 아니면 수용자거실의 문을 열거나 수용자를 거실 밖으로 나오게 해서는 아니 된다.', 1294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9630, '제118조(장애물 방치 금지) 교정시설의 구내에는 시야를 가리거나 그 밖에 계호상 장애가 되는 물건을 두어서는 아니 된다.', 1294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9631, '제119조(보호실 등 수용중지)', 1294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9632, '제120조(보호장비의 사용)', 1294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9633, '제121조(보호장비 사용중지 등)', 1294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9634, '제122조(보호장비 사용사유의 고지) 보호장비를 사용하는 경우에는 수용자에게 그 사유를 알려주어야 한다.', 1294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9635, '제123조(보호장비 착용 수용자의 거실 지정) 보호장비를 착용 중인 수용자는 특별한 사정이 없으면 계호상 독거수용한다.', 1294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9636, '제124조(보호장비 사용의 감독)', 1294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9637, '제125조(강제력의 행사) 교도관은 소장의 명령 없이 법 제100조에 따른 강제력을 행사해서는 아니 된다. 다만, 그 명령을 받을 시간적 여유가 없는 경우에는 강제력을 행사한 후 소장에게 즉시 보고하여야 한다. <개정 2014.6.25>', 1294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9638, '제126조(무기사용 보고) 교도관은 법 제101조에 따라 무기를 사용한 경우에는 소장에게 즉시 보고하고, 보고를 받은 소장은 그 사실을 법무부장관에게 즉시 보고하여야 한다. <개정 2014.6.25>', 1294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9639, '제127조(재난 시의 조치)', 1294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9640, '제128조(도주 등에 따른 조치)', 1294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9641, '제128조의2(포상금 지급)', 1294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9642, '제128조의3(포상금의 지급 신청)', 1294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9643, '제128조의4(포상금의 환수) 법무부장관은 제128조의2제1항에 따라 포상금을 지급한 후 다음 각 호의 어느 하나에 해당하는 사실이 발견된 경우에는 해당 포상금을 환수할 수 있다.', 1294);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9644, '제129조(징벌위원회의 소집) 법 제111조에 따른 징벌위원회(이하 이 장에서 "위원회"라 한다)의 위원장은 소장의 징벌요구에 따라 위원회를 소집한다.', 1295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9645, '제130조(위원장의 직무대행) 위원회의 위원장이 불가피한 사정으로 그 직무를 수행하기 어려운 경우에는 위원장이 미리 지정한 위원이 그 직무를 대행한다.', 1295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9646, '제131조(위원의 제척) 위원회의 위원이 해당 징벌대상 행위의 조사를 담당한 경우에는 해당 위원회에 참석할 수 없다.', 1295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9647, '제132조(징벌의결 통고) 위원회가 징벌을 의결한 경우에는 이를 소장에게 즉시 통고하여야 한다.', 1295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9648, '제133조(징벌의 집행)', 1295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9649, '제134조(징벌집행의 계속) 법 제108조제4호부터 제14호까지의 징벌 집행 중인 수용자가 다른 교정시설로 이송되거나 법원 또는 검찰청 등에 출석하는 경우에는 징벌집행이 계속되는 것으로 본다.', 1295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9650, '제135조(징벌기간의 계산) 소장은 법 제113조제1항에 따라 징벌집행을 일시 정지한 경우 그 정지사유가 해소되었을 때에는 지체 없이 징벌집행을 재개하여야 한다. 이 경우 집행을 정지한 다음날부터 집행을 재개한 전날까지의 일수는 징벌기간으로 계산하지 아니한다.', 1295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9651, '제136조(이송된 사람의 징벌) 수용자가 이송 중에 징벌대상 행위를 하거나 다른 교정시설에서 징벌대상 행위를 한 사실이 이송된 후에 발각된 경우에는 그 수용자를 인수한 소장이 징벌을 부과한다.', 1295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9652, '제137조(징벌사항의 기록) 소장은 수용자의 징벌에 관한 사항을 수용기록부 및 징벌집행부에 기록하여야 한다.', 1295);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9653, '제138조(소장 면담)', 1296);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9654, '제139조(순회점검공무원에 대한 청원)', 1296);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9655, '제139조의2(정보공개의 예상비용 등)', 1296);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9656, '제140조(가석방자가 지켜야 할 사항의 알림 등) 소장은 법 제122조제2항의 가석방 허가에 따라 수형자를 가석방하는 경우에는 가석방자 교육을 하고, 지켜야 할 사항을 알려준 후 증서를 발급해야 한다. <개정 2020.8.5>', 1298);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9657, '제141조(석방예정자 상담 등) 소장은 수형자의 건전한 사회복귀를 위하여 필요하다고 인정하면 석방 전 3일 이내의 범위에서 석방예정자를 별도의 거실에 수용하여 장래에 관한 상담과 지도를 할 수 있다.', 1299);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9658, '제142조(형기종료 석방예정자의 사전조사) 소장은 형기종료로 석방될 수형자에 대하여는 석방 10일 전까지 석방 후의 보호에 관한 사항을 조사하여야 한다.', 1299);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9659, '제143조(석방예정자의 수용이력 등 통보)', 1299);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9660, '제144조(석방예정자의 보호조치) 소장은 수형자를 석방하는 경우 특히 필요하다고 인정하면 한국법무보호복지공단에 그에 대한 보호를 요청할 수 있다. <개정 2009.3.18>', 1299);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9661, '제145조(귀가여비 등의 회수) 소장은 법 제126조에 따라 피석방자에게 귀가 여비 또는 의류를 빌려준 경우에는 특별한 사유가 없으면 이를 회수한다.', 1299);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9662, '제145조의2(증명서의 발급) 소장은 다음 각 호에 해당하는 사람의 신청에 따라 교정시설에 수용된 사실 또는 수용되었다가 석방된 사실에 관한 증명서를 발급할 수 있다. <개정 2020.8.5>', 1299);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9663, '제145조의3(고유식별정보의 처리) 소장은 제145조의2에 따른 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법 시행령」 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 1299);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9664, '제146조(사망 알림) 소장은 법 제127조에 따라 수용자의 사망 사실을 알리는 경우에는 사망 일시ㆍ장소 및 사유도 같이 알려야 한다.', 1300);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9665, '제147조(검시) 소장은 수용자가 사망한 경우에는 그 시신을 검사하여야 한다. <개정 2014.6.25>', 1300);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9666, '제148조(사망 등 기록)', 1300);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9667, '제149조 삭제 <2015.12.10>', 1300);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9668, '제150조(임시 매장지의 표지 등)', 1300);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9669, '제151조(교정위원)', 1301);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9670, '제152조(외부인사가 지켜야 할 사항) 교정위원, 교정자문위원, 그 밖에 교정시설에서 활동하는 외부인사는 활동 중에 알게 된 교정시설의 안전과 질서 및 수용자의 신상에 관한 사항을 외부에 누설하거나 공개해서는 안 된다. <개정 2020.8.5>', 1301);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9671, '제153조(기부금품의 접수 등)', 1301);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9672, '제1조(목적) 이 규정은 「형사사법절차에서의 전자문서 이용 등에 관한 법률」에 따른 법원의 형사사법업무 전자화의 효율적인 추진을 위하여 법원행정처에 형사전자소송(위 법에 따라 전자화된 형태의 법원의 형사사법절차를 가리킨다, 이하 이 규칙에서 같다) 추진단(이하 "추진단"이라 한다)을 설치하고, 이를 운영함에 필요한 사항을 정함을 목적으로 한다.', 1302);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9673, '제2조(추진단의 구성)', 1302);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9674, '제3조(사무) 추진단은 다음 각 호의 사항을 담당한다.', 1302);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9675, '제4조(협조요청 등)', 1302);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9676, '제5조(조사연구위탁 등)', 1302);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9677, '제6조(위임사항) 추진단의 운영 및 그 밖에 필요한 사항은 법원행정처내규로 정한다.', 1302);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9678, '제1조(목적) 이 법은 형사사법절차에서 전자문서의 이용 및 관리 등에 관한 기본 원칙과 절차를 규정함으로써 형사사법절차의 전자화를 실현하여 형사사법절차의 신속성과 투명성을 높이고 국민의 권익 보호에 이바지함을 목적으로 한다.', 1303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9679, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다.', 1303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9680, '제3조(적용 범위) 이 법은 다음 각 호의 법률에 따른 형사사법절차에 적용한다.', 1303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9681, '제4조(다른 법률과의 관계)', 1303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9682, '제5조(전자문서에 의한 형사사법절차의 수행)', 1303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9683, '제6조(전산정보처리시스템의 운영)', 1303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9684, '제7조(사용자등록)', 1303);
