INSERT INTO balaw.jo (id, content, jang_id) VALUES (9687, '제10조(전자문서의 작성)', 1303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9688, '제11조(전자화문서의 작성)', 1303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9689, '제12조(전자화대상문서의 보관)', 1303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9690, '제13조(전자문서의 유통)', 1303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9691, '제14조(전자적 송달 또는 통지)', 1303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9692, '제15조(전자문서를 출력한 서면에 의한 송달)', 1303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9693, '제16조(전자문서의 열람ㆍ복사 등)', 1303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9694, '제17조(영장 등의 집행에 관한 특례)', 1303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9695, '제18조(증거조사에 관한 특례) 「형사소송법」 제292조 및 제292조의3에도 불구하고 형사재판에서 전자문서에 대한 증거조사는 다음 각 호의 구분에 따른 방법으로 할 수 있다.', 1303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9696, '제19조(재판의 집행지휘 방식에 관한 특례)', 1303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9697, '제20조(전자문서의 폐기)', 1303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9698, '제21조(위임규정) 이 법에서 대통령령 또는 대법원규칙으로 위임한 사항 및 이 법에서 규정한 사항 외에 형사사법절차에서의 전자문서의 이용ㆍ관리 및 전산정보처리시스템의 운영 등에 필요한 사항 중 법원 외의 형사사법업무 처리기관의 형사사법업무에 관하여는 대통령령으로, 법원의 형사사법업무에 관하여는 대법원규칙으로 정한다.', 1303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9699, '제22조(벌칙) 제16조제4항을 위반하여 전자문서를 다른 사람에게 전송하거나 교부 또는 제시한 사람은 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 1303);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9700, '제1조(목적) 이 영은 「형사사법절차에서의 전자문서 이용 등에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 1304);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9701, '제2조(정의) 이 영에서 사용하는 용어의 뜻은 다음과 같다.', 1304);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9702, '제3조(전자문서를 제출할 수 있는 자) 「형사사법절차에서의 전자문서 이용 등에 관한 법률」(이하 "법"이라 한다) 제5조제1항에 따라 피의자, 피고인, 피해자, 고소인, 고발인 및 변호인 외에 전산정보처리시스템을 통해 전자문서를 제출할 수 있는 자는 다음 각 호와 같다.', 1304);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9703, '제4조(사용자등록)', 1305);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9704, '제5조(사용자등록의 철회 등)', 1305);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9705, '제6조(사용자등록의 말소 등)', 1305);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9706, '제7조(전자서명 등)', 1306);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9707, '제8조(전자문서의 접수 방법ㆍ절차 등)', 1306);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9708, '제9조(전자문서의 제출 등)', 1306);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9709, '제10조(전자문서의 동일성 확인 등)', 1306);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9710, '제11조(전자화문서의 제출 등)', 1306);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9711, '제12조(멀티미디어 자료의 제출 등)', 1306);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9712, '제13조(제출된 전자문서의 보완 등)', 1306);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9713, '제14조(수사 관련 자료의 요구)', 1306);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9714, '제15조(전자문서로 작성하지 않을 수 있는 경우)', 1307);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9715, '제16조(피의자신문조서의 작성 등)', 1307);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9716, '제17조(「특정범죄신고자 등 보호법」에 따른 조서 등의 작성)', 1307);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9717, '제18조(전자화문서로의 변환ㆍ등재 제외 사유) 법 제11조제1항 단서에 따라 전자화대상문서를 전자적인 형태로 변환하는 것이 현저히 곤란하거나 적합하지 않은 경우로서 변환ㆍ등재하지 않을 수 있는 경우는 다음 각 호와 같다.', 1307);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9718, '제19조(전자화문서 등재 절차와 방법)', 1307);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9719, '제20조(전자화대상문서의 보관 및 확인)', 1307);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9720, '제21조(전자문서의 폐기ㆍ정정 등)', 1307);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9721, '제22조(전자문서의 유통 등)', 1307);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9722, '제23조(전자적 송달 또는 통지를 받을 자)', 1308);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9723, '제24조(전자적 송달 또는 통지의 방법 등)', 1308);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9724, '제25조(기간의 계산)', 1308);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9725, '제26조(출력서면의 송달 등)', 1308);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9726, '제27조(전자문서의 열람 등)', 1309);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9727, '제28조(사건기록의 전자적 송부)', 1309);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9728, '제29조(영장등의 사본 교부) 검사 또는 사법경찰관은 법 제17조제1항에 따라 전자문서로 발부된 영장, 감정유치장, 허가장, 형집행장, 허가서 및 요청서 등(이하 "영장등"이라 한다)을 제시하거나 전송하는 방법으로 집행을 완료한 후 그 사본을 교부하는 경우에는 해당 영장등의 사본이라는 표시를 한 파일을 전자우편, 문자전송 서비스 등을 통해 전송하거나 그러한 표시를 한 출력서면을 교부하는 방법으로 할 수 있다.', 1309);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9729, '제30조(영장등의 반환) 검사 또는 사법경찰관은 법 제17조제1항에 따라 전자문서로 발부된 영장등을 「검사와 사법경찰관의 상호협력과 일반적 수사준칙에 관한 규정」 제35조에 따라 반환하는 경우 같은 조 제2항에 따른 반환사유 등에 관한 정보를 해당 영장등과 별개의 전자문서로 작성할 수 있다.', 1309);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9730, '제31조(압수목록 등의 교부) 검사 또는 사법경찰관은 「형사소송법」 제128조(같은 법 제219조에 따라 준용되는 경우를 포함한다) 또는 제129조(같은 법 제219조에 따라 준용되는 경우를 포함한다)에 따라 증명서나 압수목록을 교부하는 경우 전자우편이나 문자전송 서비스 등을 통해 전송할 수 있다.', 1309);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9731, '제32조(공판절차에서의 전자문서 제출 등)', 1310);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9732, '제33조(이동통신단말장치의 활용)', 1310);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9733, '제34조(재판의 집행지휘 시 전자문서 출력 등) 검사는 법 제19조제3항에 따라 전자문서를 출력하는 경우에는 전산정보처리시스템에 접속해 저장된 전자문서를 출력하는 방법으로 한다. 이 경우 출력하는 서면에 고유번호가 출력되도록 하는 등 전자문서의 동일성을 확보하기 위한 기술적 조치를 해야 한다.', 1310);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9734, '제35조(전자문서의 이용ㆍ관리)', 1311);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9735, '제36조(전산정보처리시스템의 운영)', 1311);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9736, '제37조(전자문서의 폐기ㆍ보관)', 1311);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9737, '제1조(목적) 이 영은 「형의 실효 등에 관한 법률」에서 위임된 사항과 그 시행에 관하여 필요한 사항을 규정함을 목적으로 한다. <개정 2006.7.27, 2022.7.5>', 1312);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9738, '제2조(수사자료표의 작성 등)', 1312);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9739, '제2조의2 삭제 <2022.7.5>', 1312);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9740, '제3조(고등검찰부에서의 수형인명부기재) 군사법원의 재판에 대한 상소심에서 자격정지 이상의 형을 선고한 재판이 확정된 경우에는 해당 고등검찰부에서도 그 사실을 수형인명부에 기재할 수 있다. <개정 1984ㆍ10ㆍ6, 1993ㆍ9ㆍ4, 2022.6.30>', 1312);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9741, '제4조(수형인명표의 작성ㆍ송부) 「형의 실효 등에 관한 법률」(이하 "법"이라 한다) 제3조 및 이 영 제3조에 따라 자격정지 이상의 형을 선고한 재판이 확정된 사실을 수형인명부에 기재한 때에는 지체 없이 수형인명표를 작성하여 수형인의 등록기준지 시ㆍ구ㆍ읍ㆍ면사무소에 등기우편으로 송부하거나 「전자정부법」 제37조제1항에 따른 행정정보공동이용센터를 통하여 전자적인 방법으로 송부하여야 한다. <개정 1984ㆍ10ㆍ6, 2007.8.7, 2010.5.4, 2012.4.23, 2022.7.5>', 1312);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9742, '제5조(집행유예실효 등의 통지) 제4조에 따라 수형인명표를 송부한 검찰청, 그 지청 또는 군검찰부는 수형인에 관하여 법 제4조제2항 각 호의 어느 하나에 해당되는 사유가 발생한 때에는 지체 없이 수형인명표를 송부한 관서에 그 사실을 등기우편으로 통지하거나 「전자정부법」 제37조제1항에 따라 설치된 행정정보공동이용센터를 통하여 전자적인 방법으로 통지하여야 한다. 다만, 제4조에 따라 수형인명표를 송부할 때에 미리 집행유예기간 또는 법 제7조에 따른 형의 실효기간을 부기(附記)한 경우에는 그 부기로써 법 제4조제2항 각 호의 사유의 통지 중 집행유예기간이 경과한 사실 또는 법 제7조에 따른 형의 실효사실의 통지에 갈음할 수 있다. <개정 2010.5.4, 2022.6.30>', 1312);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9743, '제6조(수사자료표를 작성할 사법경찰관의 범위) 법 제5조제1항 각 호 외의 부분 본문에 따라 수사자료표를 작성할 사법경찰관의 범위는 다음 각 호와 같다.', 1312);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9744, '제6조의2(전과기록 또는 수사경력자료의 보존ㆍ관리 및 회보 등)', 1312);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9745, '제7조(수사자료표의 조회 및 회보 범위)', 1312);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9746, '제7조의2(소년 및 실효된 형 등에 관한 회보 제한)', 1312);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9747, '제8조(수형인명부 등의 정리)', 1312);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9748, '제9조(수사자료표의 폐기)', 1312);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9749, '제10조(민감정보 및 고유식별정보의 처리) 수사자료표, 전과기록 또는 수사경력자료의 보존ㆍ관리업무 및 조회ㆍ회보업무를 담당하는 기관의 장은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 범죄경력자료에 해당하는 정보, 「개인정보 보호법 시행령」 제18조제3호에 따른 개인의 신체적, 생리적, 행동적 특징에 관한 정보로서 특정 개인을 알아볼 목적으로 일정한 기술적 수단을 통해 생성한 정보(제2호의 사무를 수행하는 경우로 한정한다)와 같은 영 제19조제1호, 제2호 또는 제4호에 따른 주민등록번호, 여권번호 또는 외국인등록번호를 처리할 수 있다.', 1312);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9750, '제1조(목적) 이 영은 가석방자에 대한 가석방 기간 중의 보호와 감독에 필요한 사항을 규정함을 목적으로 한다.', 1313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9751, '제2조(정의) 이 영에서 "가석방자"란 징역 또는 금고 형의 집행 중에 있는 사람으로서 「형법」 제72조 및 「형의 집행 및 수용자의 처우에 관한 법률」 제122조에 따라 가석방된 사람(「보호관찰 등에 관한 법률」에 따른 보호관찰 대상자는 제외한다)을 말한다.', 1313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9752, '제3조(가석방자의 보호와 감독) 가석방자는 그의 주거지를 관할하는 경찰서(경찰서의 지구대를 포함한다. 이하 같다)의 장의 보호와 감독을 받는다.', 1313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9753, '제4조(가석방 사실의 통보)', 1313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9754, '제5조(가석방자의 출석의무) 가석방자는 제4조제2항에 따른 가석방증에 적힌 기한 내에 관할경찰서에 출석하여 가석방증에 출석확인을 받아야 한다. 다만, 천재지변, 질병, 그 밖의 부득이한 사유로 기한 내에 출석할 수 없거나 출석하지 아니하였을 때에는 지체 없이 그 사유를 가장 가까운 경찰서의 장에게 신고하고 별지 제1호서식의 확인서를 받아 관할경찰서의 장에게 제출하여야 한다. <개정 2016.1.22>', 1313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9755, '제6조(가석방자의 신고의무)', 1313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9756, '제7조(관할경찰서의 장의 조치)', 1313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9757, '제8조(가석방자에 대한 조사) 관할경찰서의 장은 6개월마다 가석방자의 품행, 직업의 종류, 생활 정도, 가족과의 관계, 가족의 보호 여부 및 그 밖의 참고사항에 관하여 조사서를 작성하고 관계기관의 장에게 통보하여야 한다. 다만, 변동 사항이 없는 경우에는 그러하지 아니하다.', 1313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9758, '제9조(보호와 감독의 위임)', 1313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9759, '제10조(국내 주거지 이전 및 여행)', 1313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9760, '제11조(국내주거지 이전등의 신고에 따른 조치)', 1313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9761, '제12조(국내주거지 이전등 신고 사실의 통보) 관할경찰서의 장은 제10조에 따라 국내주거지 이전등의 신고를 받은 경우에는 가석방자의 새 주거지를 관할하는 지방검찰청의 장 및 경찰서의 장에게 신고 사실을 통보하고, 해당 경찰서의 장에게 관계서류를 송부하여야 한다. <개정 2016.1.22>', 1313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9762, '제13조(국외 이주 및 여행)', 1313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9763, '제14조 삭제 <2016.1.22>', 1313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9764, '제15조(국외 이주등 중지의 신고) 제13조에 따라 신고한 가석방자는 국외 이주등을 중지하였을 때에는 지체 없이 그 사실을 관할경찰서의 장에게 신고하여야 한다. <개정 2016.1.22>', 1313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9765, '제16조(국외 여행자의 귀국신고) 국외 여행을 한 가석방자는 귀국하여  주거지에 도착하였을 때에는 지체 없이 그 사실을 관할경찰서의 장에게 신고하여야 한다. 국외 이주한 가석방자가 입국하였을 때에도 또한 같다.', 1313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9766, '제17조(신고사항의 통보) 제13조, 제15조 및 제16조에 따른 신고를 받은 관할경찰서의 장은 그 사실을 관계기관의 장에게 통보하여야 한다. <개정 2016.1.22>', 1313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9767, '제18조(가석방의 실효 등 보고) 각 지방검찰청의 장, 경찰서의 장 및 교정시설의 장은 가석방자가 「형법」 제74조 또는 제75조에 해당하게 된 사실을 알았을 때에는 지체 없이 석방시설의 장에게 통보하여야 하며, 통보를 받은 석방시설의 장은 지체 없이 법무부장관에게 보고하여야 한다.', 1313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9768, '제19조(가석방의 취소 등)', 1313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9769, '제20조(사망 통보)', 1313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9770, '제21조(준용규정) 군사법원에서 형의 선고를 받은 사람에 대한 법무부장관의 직무는 국방부장관이 수행하고, 검사의 직무는 형을 선고한 군사법원에 대응하는 군검찰부의 군검사가 수행한다. <개정 2022.6.30>', 1313);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9771, '제1조(목적) 이 법은 사면(赦免), 감형(減刑) 및 복권(復權)에 관한 사항을 규정한다.', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9772, '제2조(사면의 종류) 사면은 일반사면과 특별사면으로 구분한다.', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9773, '제3조(사면 등의 대상) 사면, 감형 및 복권의 대상은 다음 각 호와 같다.', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9774, '제4조(사면규정의 준용) 행정법규 위반에 대한 범칙(犯則) 또는 과벌(科罰)의 면제와 징계법규에 따른 징계 또는 징벌의 면제에 관하여는 이 법의 사면에 관한 규정을 준용한다.', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9775, '제5조(사면 등의 효과)', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9776, '제6조(복권의 제한) 복권은 형의 집행이 끝나지 아니한 자 또는 집행이 면제되지 아니한 자에 대하여는 하지 아니한다.', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9777, '제7조(집행유예를 선고받은 자에 대한 사면 등) 형의 집행유예를 선고받은 자에 대하여는 형 선고의 효력을 상실하게 하는 특별사면 또는 형을 변경하는 감형을 하거나 그 유예기간을 단축할 수 있다.', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9778, '제8조(일반사면 등의 실시) 일반사면, 죄 또는 형의 종류를 정하여 하는 감형 및 일반에 대한 복권은 대통령령으로 한다. 이 경우 일반사면은 죄의 종류를 정하여 한다.', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9779, '제9조(특별사면 등의 실시) 특별사면, 특정한 자에 대한 감형 및 복권은 대통령이 한다.', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9780, '제10조(특별사면 등의 상신)', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9781, '제10조의2(사면심사위원회)', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9782, '제11조(특별사면 등 상신의 신청) 검찰총장은 직권으로 또는 형의 집행을 지휘한 검찰청 검사의 보고 또는 수형자가 수감되어 있는 교정시설의 장의 보고에 의하여 법무부장관에게 특별사면 또는 특정한 자에 대한 감형을 상신할 것을 신청할 수 있다.', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9783, '제12조(특별사면 등의 제청)', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9784, '제13조(검사의 의견 첨부) 검사가 제12조제2항의 서류를 접수하였을 때에는 제14조제3호에 따른 사항을 조사하여 그에 대한 의견을 첨부하여 검찰총장에게 송부하여야 한다.', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9785, '제14조(특별사면 등 상신 신청의 첨부서류) 특별사면 또는 특정한 자에 대한 감형의 상신을 신청하는 신청서에는 다음 각 호의 서류를 첨부하여야 한다.', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9786, '제15조(복권 상신의 신청)', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9787, '제16조(복권 상신 신청의 첨부서류) 복권의 상신을 신청하는 신청서에는 다음 각 호의 서류를 첨부하여야 한다.', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9788, '제17조(특정한 자격에 대한 복권의 출원) 특정한 자격에 대한 복권을 출원하는 경우에는 회복하려는 자격의 종류를 분명히 밝혀야 한다.', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9789, '제18조(본인에 의한 복권의 출원) 복권을 사건 본인이 출원하는 경우에는 형의 집행을 지휘한 검찰청의 검사를 거쳐야 한다.', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9790, '제19조(검사의 의견 첨부) 검사가 제18조의 서류를 접수하였을 때에는 제16조제3호에 따른 사항을 조사하여 그에 대한 의견을 첨부하여 검찰총장에게 송부하여야 한다.', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9791, '제20조(상신 신청의 기각)', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9792, '제21조(사면장 등의 송부) 법무부장관은 대통령으로부터 특별사면, 특정한 자에 대한 감형 또는 복권의 명이 있을 때에는 검찰총장에게 사면장(赦免狀), 감형장 또는 복권장을 송부한다.', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9793, '제22조(사면장 등의 부여) 검찰총장은 사면장, 감형장 또는 복권장을 접수하였을 때에는 관계 검찰청의 검사를 거쳐 지체 없이 이를 사건 본인에게 내준다. 이 경우 사건 본인이 수감되어 있을 때에는 교정시설의 장을 거친다.', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9794, '제23조(교정시설의 장 등에의 통지)', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9795, '제24조(사면장 등 부여의 촉탁)', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9796, '제25조(판결원본에의 부기 등)', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9797, '제26조(사면장 등 부여의 보고) 검사가 사면장, 감형장 또는 복권장을 사건 본인에게 내주었을 때에는 지체 없이 법무부장관에게 보고하여야 한다.', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9798, '제27조(군사법원에서 형을 선고받은 자의 사면 등) 군사법원(「군사법원법」 제11조에 따라 군사법원에 재판권이 있는 사건을 심판하는 고등법원을 포함한다. 이하 이 조에서 같다)에서 형을 선고받은 자에 대하여는 이 법에 따른 법무부장관의 직무는 국방부장관이 수행하고, 검찰총장과 검사의 직무는 형을 선고한 군사법원에서 군검사의 직무를 수행한 군법무관이 수행한다. <개정 2016.1.6, 2021.9.24>', 1314);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9799, '제1조(목적) 이 규칙은 「사면법」 제10조의2제8항에 따라 사면심사위원회에 관하여 필요한 사항을 규정함을 목적으로 한다.', 1315);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9800, '제2조(사면심사위원회의 기능) 사면심사위원회(이하 "위원회"라 한다)는 「사면법」 제10조제1항에 따른 법무부장관의 특별사면, 특정한 자에 대한 감형 및 복권(이하 "특별사면등" 이라 한다)의 상신(上申)이 적정하게 이루어질 수 있도록 심사ㆍ자문함을 목적으로 한다.', 1315);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9801, '제3조(위원의 임명 및 위촉) 위원회의 위원은 다음 각 호의 자 중에서 법무부장관이 임명하거나 위촉한다.', 1315);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9802, '제4조(공무원인 위원의 승계) 제3조제1호의 직위에 있는 자가 위원으로 임명된 경우 인사이동 등의 사유로 그 직위가 변동되었을 때에는 법무부장관이 달리 임명하지 아니하는 한 그 직위의 후임자가 위원직을 승계하는 것으로 본다.', 1315);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9803, '제5조(위원의 회피)', 1315);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9804, '제6조(위원장의 직무)', 1315);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9805, '제7조(회의)', 1315);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9806, '제8조(간사 등)', 1315);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9807, '제9조(심사 및 의견제출) 위원회는 법무부장관의 요청에 따라 특별사면등 상신의 적정성 여부를 심사하고 그에 관한 의견을 법무부장관에게 제출한다.', 1315);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9808, '제10조(심의서)', 1315);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9809, '제11조(회의록)', 1315);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9810, '제12조(위원의 해임 및 해촉) 법무부장관은 위원회의 위원이 다음 각호의 어느 하나에 해당하는 경우에는 해임하거나 해촉할 수 있다.', 1315);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9811, '제13조(수당 등) 위원회의 위원에게는 예산의 범위에서 수당과 여비를 지급할 수 있다. 다만, 공무원인 위원이 그 소관업무와 직접적으로 관련되어 위원회에 출석하는 경우에는 그러하지 아니하다.', 1315);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9812, '제14조(운영세칙) 이 규칙에서 규정한 것 외에 위원회의 운영에 필요한 사항은 위원장이 정한다.', 1315);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9813, '제1조(목적) 이 영은 「범죄수익은닉의 규제 및 처벌 등에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 1316);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9814, '제2조(신고 또는 공로의 범위)', 1316);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9815, '제3조(포상금의 지급 기준 등)', 1316);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9816, '제4조(포상금의 지급 신청)', 1316);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9817, '제5조(포상금의 환수) 법무부장관은 포상금을 지급받은 자가 다음 각 호의 어느 하나에 해당하는 경우에는 그 포상금을 환수할 수 있다. 다만, 제1호의 경우에는 포상금을 환수하여야 한다.', 1316);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9818, '제6조(민감정보 및 고유식별정보의 처리) 법무부장관과 지방검찰청 검사장은 포상금의 지급에 관한 사무를 처리하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 민감정보나 같은 법 시행령 제19조제1호부터 제4호까지의 규정에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호를 처리할 수 있다.', 1316);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9819, '제1조(목적) 이 영은 보안관찰법(이하 "법"이라 한다)에서 위임된 사항과 그 시행에 관하여 필요한 사항을 규정함을 목적으로 한다.', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9820, '제2조(정의) 이 영에서 사용하는 용어의 정의는 다음과 같다.', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9821, '제3조(형기계산) 법 제3조에 규정된 형기합계를 계산함에 있어 소년법 제60조제1항의 규정에 의한 부정기형이 선고된 경우에는 그 단기를 형기로 한다.', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9822, '제4조(보안관찰)', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9823, '제5조(동태보고등)', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9824, '제6조(보안관찰처분대상자의 신고)', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9825, '제7조(신고의무의 고지) 교도소등의 장은 수용되어 있는 보안관찰처분대상자가 출소할 때에는 법 제6조제1항 및 제2항의 규정에 의하여 거주예정지 관할경찰서장에게 신고할 것을 고지하여야 한다.', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9826, '제8조(출소통보등)', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9827, '제9조(출소사실 신고등)', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9828, '제10조(보안관찰처분대상자 발생통고등)', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9829, '제11조(보안관찰처분대상자의 동태보고) 관할경찰서장은 그 관할구역내에 거주하는 보안관찰처분대상자에 대하여 다음 각호의 1에 해당하는 사유가 발생한 때에는 지체없이 이를 주거지 관할검사에게 보고하여야 한다.', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9830, '제12조(보안관찰처분청구서등)', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9831, '제13조(조사) 검사 또는 사법경찰관리(특별사법경찰관리를 포함한다. 이하 같다)는 법 제9조의 규정에 의한 조사를 위하여 필요한 경우에는 다음의 조치를 할 수 있다.', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9832, '제14조(보안관찰처분 면제결정 신청등)', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9833, '제15조(위원회에의 회부ㆍ의결)', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9834, '제16조(위원회의 직원)', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9835, '제17조(회의록)', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9836, '제18조(수당) 위원회에 출석한 위원에 대하여는 예산의 범위안에서 수당을 지급할 수 있다. 다만, 공무원인 위원이 그 소관업무와 직접적으로 관련하여 위원회에 출석하는 경우에는 그러하지 아니하다.', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9837, '제19조(위원회의 운영세칙) 이 영에 규정한 사항외에 위원회의 운영에 관하여 필요한 사항은 위원회의 의결을 거쳐 위원장이 정한다.', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9838, '제20조(결정서) 보안관찰처분결정서에는 보안관찰처분청구를 한 검사의 직위ㆍ성명과 피청구자의 성명ㆍ연령ㆍ직업ㆍ주거ㆍ결정주문 및 이유와 적용법조를 기재하여야 한다.', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9839, '제21조(결정의 고지) 보안관찰처분에 관한 결정의 고지는 검사가 피청구자 또는 신청인에게 결정서등본을 송달하는 방법으로 한다. 다만, 법 제11조제3항의 규정에 의한 청구를 기각하는 결정에 대하여는 고지하지 아니한다.', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9840, '제22조(지휘ㆍ감독) 검사는 법을 집행함에 있어서는 경찰서장ㆍ사법경찰관리ㆍ교도소등의 장을 지휘ㆍ감독하고 필요한 지시를 할 수 있다.', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9841, '제23조(보안관찰처분 집행중지결정의 신청등)', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9842, '제24조(피보안관찰자의 신고사항등)', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9843, '제25조(지도의 방법)', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9844, '제26조(거소제공의 방법)', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9845, '제27조(거소변경의 절차)', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9846, '제28조(임시거소의 제공)', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9847, '제29조(사회복지시설의 범위등)', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9848, '제30조(응급구호의 범위)', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9849, '제31조(경고의 방법) 법 제22조의 규정에 의한 검사 및 사법경찰관리의 경고는 경고일시, 경고이유, 경고내용 및 그에 위반하는 경우 형사처벌등 불이익한 처분을 받을 수 있음을 기재한 서면에 의하여야 한다. 다만, 긴급을 요하는 때에는 구두로 경고할 수 있다.', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9850, '제32조(군보안관찰처분심의위원회에의 준용) 제15조 내지 제19조의 규정은 군보안관찰처분심의위원회에 이를 준용한다.', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9851, '제32조의2(민감정보 및 고유식별정보의 처리) 관할 검사ㆍ경찰서장, 교도소등의 장 또는 사법경찰관리 등 법에 따라 보안관찰 관련 사무를 처리하는 기관은 그 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 민감정보 또는 같은 법 시행령 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호, 외국인등록번호를 처리할 수 있다.', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9852, '제33조(시행규칙) 이 영 시행에 관하여 필요한 사항은 법무부령으로 정한다. 다만, 군사법원법 제2조제1항 각호의 1에 해당하는 자에 관한 사항은 법무부장관과 협의하여 국방부령으로 정한다.', 1317);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9853, '제1조(목적) 이 영은 「부패재산의 몰수 및 회복에 관한 특례법」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 1318);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9854, '제2조(정의) 이 영에서 사용하는 용어의 뜻은 다음과 같다.', 1318);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9855, '제3조(범죄피해재산 환부절차의 개시 등)', 1318);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9856, '제4조(손해배상청구권 등과의 관계) 피해자등이 범죄피해재산의 전부　또는 일부를 반환받았거나 범죄피해재산에 관하여 손해배상을 받았을 때에는 그 반환받거나 배상받은 재산의 범위에서 회복대상재산을 환부하지 않는다.', 1318);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9857, '제5조(통지 및 공고)', 1318);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9858, '제6조(범죄피해재산의 환부청구)', 1318);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9859, '제7조(회복대상재산 환부 여부의 결정 등)', 1318);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9860, '제8조(회복대상재산의 환부 실시)', 1318);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9861, '제9조(추가 환부 등) 검사는 범죄피해재산 환부절차를 종료한 후 회복대상재산이 남아 있거나 해당 절차와 관련된 회복대상재산을 추가로 보관하게 된 경우로서 피해자등에게 이미 환부한 재산이 피해인정재산에 미치지 못할 때에는 제3조부터 제8조까지의 규정에 따라 추가로 환부해야 한다.', 1318);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9862, '제10조(이의신청)', 1318);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9863, '제11조(범죄피해재산환부심의회)', 1318);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9864, '제12조(준용규정) 회복대상재산의 수리(受理)ㆍ영치(領置) 및 처분 절차 등에 관하여는 그 성질에 반하지 않는 범위에서 「검찰청법」 제11조에 따른 압수물 사무, 재산형(財産刑)의 집행사무 또는 각급 검찰청의 사건사무에 관한 규정을 준용한다.', 1318);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9865, '제13조(민감정보 및 고유식별정보의 처리) 법무부장관과 검사는 법 제6조에 따른 범죄피해재산의 환부에 관한 사무를 처리하기 위해 불가피한 경우 「개인정보 보호법 시행령」 제18조제2호에 따른 범죄경력자료에 해당하는 정보나 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 1318);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9866, '제1조(목적) 이 법은 사람에 대하여 성폭력범죄를 저지른 성도착증 환자로서 성폭력범죄를 다시 범할 위험성이 있다고 인정되는 사람에 대하여 성충동 약물치료를 실시하여 성폭력범죄의 재범을 방지하고 사회복귀를 촉진하는 것을 목적으로 한다. <개정 2012.12.18>', 1319);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9867, '제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다. <개정 2011.8.4, 2012.12.18, 2016.1.19, 2017.10.31, 2017.12.19>', 1319);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9868, '제3조(약물치료의 요건) 약물치료는 다음 각 호의 요건을 모두 갖추어야 한다.', 1319);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9869, '제4조(치료명령의 청구)', 1320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9870, '제5조(조사)', 1320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9871, '제6조(치료명령 청구사건의 관할)', 1320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9872, '제7조(치료명령 청구서의 기재사항)', 1320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9873, '제8조(치료명령의 판결 등)', 1320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9874, '제8조의2(치료명령의 집행 면제 신청 등)', 1320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9875, '제8조의3(치료감호심의위원회의 치료명령 집행 면제 등)', 1320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9876, '제8조의4(치료명령의 집행 면제 결정 통지) 법원 또는 치료감호심의위원회는 제8조의2제4항 또는 제8조의3제1항에 따라 치료명령의 집행 면제에 관한 결정을 한 때에는 지체 없이 신청인 또는 피치료감호자, 신청인 또는 피치료감호자의 주거지를 관할하는 보호관찰소의 장, 교도소ㆍ구치소 또는 치료감호시설의 장에게 결정문 등본을 송부하여야 한다.', 1320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9877, '제9조(전문가의 감정 등) 법원은 제4조제2항에 따른 정신건강의학과 전문의의 진단 또는 감정의견만으로 치료명령 피청구자의 성도착증 여부를 판단하기 어려울 때에는 다른 정신건강의학과 전문의에게 다시 진단 또는 감정을 명할 수 있다. <개정 2011.8.4>', 1320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9878, '제10조(준수사항)', 1320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9879, '제11조(치료명령 판결 등의 통지)', 1320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9880, '제12조(국선변호인 등) 치료명령 청구사건에 관하여는 「형사소송법」 제282조 및 제283조를 준용한다.', 1320);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9881, '제13조(집행지휘)', 1321);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9882, '제14조(치료명령의 집행)', 1321);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9883, '제15조(치료명령을 받은 사람의 의무)', 1321);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9884, '제16조(치료기간의 연장 등)', 1321);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9885, '제17조(치료명령의 임시해제 신청 등)', 1321);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9886, '제18조(치료명령 임시해제의 심사 및 결정)', 1321);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9887, '제19조(임시해제의 취소 등)', 1321);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9888, '제20조(치료명령 집행의 종료) 제8조제1항에 따라 선고된 치료명령은 다음 각 호의 어느 하나에 해당하는 때에 그 집행이 종료된다. <개정 2020.2.4>', 1321);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9889, '제21조(치료명령의 시효)', 1321);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9890, '제22조(성폭력 수형자에 대한 치료명령 청구)', 1322);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9891, '제23조(가석방)', 1322);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9892, '제24조(비용부담)', 1322);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9893, '제25조(가종료 등과 치료명령)', 1322);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9894, '제26조(준수사항) 치료감호심의위원회는 제25조에 따른 치료명령을 부과하는 경우 치료기간의 범위에서 준수기간을 정하여 「보호관찰 등에 관한 법률」 제32조제3항 각 호의 준수사항 중 하나 이상을 부과할 수 있다.', 1322);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9895, '제27조(치료명령의 집행) 보호관찰관은 가종료자 등이 가종료ㆍ치료위탁 또는 가출소 되기 전 2개월 이내에 치료명령을 집행하여야 한다. 다만, 치료감호와 형이 병과된 가종료자의 경우 집행할 잔여 형기가 있는 때에는 그 형의 집행이 종료되거나 면제되어 석방되기 전 2개월 이내에 치료명령을 집행하여야 한다.', 1322);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9896, '제28조(치료명령 집행의 종료) 제25조에 따른 약물치료는 다음 각 호의 어느 하나에 해당하는 때에 그 집행이 종료된다.', 1322);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9897, '제29조(준용)', 1322);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9898, '제30조(치료기간의 계산) 치료기간은 최초로 성 호르몬 조절약물을 투여한 날 또는 제14조제1항에 따른 심리치료 프로그램의 실시를 시작한 날부터 기산하되, 초일은 시간을 계산함이 없이 1일로 산정한다. <개정 2017.12.19>', 1323);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9899, '제31조(치료명령 등 집행전담 보호관찰관의 지정) 보호관찰소의 장은 소속 보호관찰관 중에서 다음 각 호의 사항을 전담하는 보호관찰관을 지정하여야 한다.', 1323);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9900, '제32조(수용시설의 장 등의 협조) 제14조제3항 및 제27조에 따른 보호관찰관의 치료명령 집행에 수용시설의 장, 치료감호시설의 장, 보호감호시설의 장은 약물의 제공, 의사ㆍ간호사 등 의료인력 지원 등의 협조를 하여야 한다.', 1323);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9901, '제33조(군법 피적용자에 대한 특칙) 이 법을 적용함에 있어서 「군사법원법」 제2조제1항 각 호의 어느 하나에 해당하는 자에 대하여는 군사법원은 법원의, 군검사는 검사의, 군사법경찰관리는 사법경찰관리의, 군교도소장은 교도소장의 이 법에 따른 직무를 각각 행한다. <개정 2016.1.6>', 1323);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9902, '제34조(다른 법률의 준용) 이 법을 적용함에 있어서 이 법에 규정이 있는 경우를 제외하고는 그 성질에 반하지 아니하는 범위에서 「형사소송법」 및 「보호관찰 등에 관한 법률」을 준용한다.', 1323);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9903, '제35조(벌칙)', 1324);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9904, '제1조(목적) 이 영은 「성폭력범죄자의 성충동 약물치료에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 1325);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9905, '제2조(정신건강의학과 전문의의 진단 및 감정)', 1326);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9906, '제3조(조사)', 1326);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9907, '제4조(치료명령 청구서의 기재사항)', 1326);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9908, '제4조의2(치료명령의 집행 면제 신청 등)', 1326);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9909, '제5조(인지행동 치료 등 심리치료 프로그램)', 1326);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9910, '제6조(집행지휘)', 1327);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9911, '제7조(치료명령의 집행)', 1327);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9912, '제8조(치료약물의 지정)', 1327);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9913, '제9조(치료기관)', 1327);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9914, '제10조(수용시설 수용자의 이송 등)', 1327);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9915, '제11조(부작용에 대한 검사 및 치료)', 1327);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9916, '제12조(집행이 정지된 치료명령의 잔여기간 집행)', 1327);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9917, '제13조(치료명령을 받은 사람의 의무 등)', 1327);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9918, '제14조(주거 이전, 국내여행 및 출국의 허가 등)', 1327);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9919, '제15조(치료기간 연장 등의 신청)', 1327);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9920, '제16조(치료명령의 가해제 신청)', 1327);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9921, '제17조(치료명령 가해제의 심사 및 결정)', 1327);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9922, '제18조(가해제의 취소 등)', 1327);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9923, '제19조(수용시설의 장의 설명 및 동의 여부 확인) 수용시설의 장은 법 제22조제1항에 따른 성폭력 수형자(이하 "성폭력수형자"라 한다) 가운데 「형의 집행 및 수용자의 처우에 관한 법률」 제121조제1항에 따라 가석방 적격심사 신청 대상자로 선정된 사람에게 법 제22조제2항제1호에 따라 약물치료에 관한 사항을 서면으로 제시하여 설명하고, 약물치료에 동의한 경우에는 이를 서면으로 확인하여야 한다.', 1328);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9924, '제20조(수용시설의 장의 통보) 수용시설의 장은 성폭력수형자가 제19조에 따라 약물치료에 동의한 경우에는 수용시설 소재지를 관할하는 지방검찰청(지청을 포함한다)의 검사에게 지체 없이 다음 각 호의 사항을 통보하여야 한다.', 1328);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9925, '제21조(조사) 검사는 법 제22조제2항제3호에 따라 보호관찰소의 장에게 조사를 요청할 때에는 제20조 각 호의 사항을 통보하여야 한다.', 1328);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9926, '제22조(검사의 치료명령 청구 등)', 1328);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9927, '제23조(치료명령 청구사실의 통보) 검사는 법 제22조제2항제5호에 따라 성폭력수형자에 대하여 치료명령을 청구한 경우에는 치료명령피청구자에게 지체 없이 청구서를 송부하여야 한다.', 1328);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9928, '제24조(집행지휘 등)', 1328);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9929, '제25조(치료명령 결정문 송부) 법원은 법 제22조제2항제6호에 따라 성폭력수형자에게 치료명령을 고지한 날부터 3일 이내에 치료명령을 고지 받은 사람의 주거지를 관할하는 보호관찰소의 장에게 결정문 등본을 송부하여야 한다.', 1328);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9930, '제26조(비용부담)', 1328);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9931, '제27조(치료감호심의위원회의 감정 의뢰)', 1328);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9932, '제28조(가종료자등에 대한 치료명령 결정의 통지 등)', 1328);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9933, '제29조(준용)', 1328);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9934, '제30조(민감정보 및 고유식별정보의 처리)', 1329);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9935, '제1조(목적) 이 규칙은 「성폭력범죄자의 성충동 약물치료에 관한 법률」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9936, '제2조(정신과 전문의의 진단 및 감정) 「성폭력범죄자의 성충동 약물치료에 관한 법률」(이하 "법"이라 한다) 제4조제2항 및 제22조제2항제5호 전단에 따라 정신과 전문의에게 진단이나 감정을 요청하는 경우에는 별지 제1호서식에 따른다. 이 경우 진단 및 감정사항에는 다음 각 호의 내용이 포함되어야 한다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9937, '제3조(조사의 요청)', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9938, '제4조(치료명령 청구의 방식)', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9939, '제5조(치료명령 청구사건의 보고)', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9940, '제5조의2(치료명령의 집행 면제 신청서) 법 제8조의2제1항부터 제3항까지 및 영 제4조의2에 따른 치료명령의 집행 면제 신청은 별지 제4호의2 서식에 따른다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9941, '제6조(교도소장 등의 석방 예정 통보) 법 제11조제2항ㆍ제22조제12항 및 영 제10조제3항에 따른 석방 예정 통보는 별지 제5호서식에 따른다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9942, '제7조(집행지휘)', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9943, '제8조(치료명령 집행을 위한 통지) 보호관찰관은 법 제13조 및 영 제6조에 따른 집행지휘를 받거나 영 제12조제1항제1호에 따라 치료명령의 잔여기간을 집행하여야 할 사유를 확인한 경우에는 지체 없이 치료명령을 받은 사람을 수용하고 있는 교도소ㆍ소년교도소ㆍ구치소ㆍ군교도소(이하 "수용시설"이라 한다)의 장에게 별지 제7호서식에 따라 통지하여야 한다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9944, '제9조(약물치료에 관한 설명) 법 제14조제2항 및 영 제7조제2항에 따른 약물치료에 관한 설명은 별지 제8호서식에 따른다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9945, '제10조(담당 보호관찰관의 지명 등)', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9946, '제11조(치료명령을 받은 사람의 이송 통보) 영 제10조제2항 및 제12조제1항제1호에 따른 치료명령을 받은 사람의 이송 통보는 별지 제10호서식에 따른다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9947, '제12조(약물 투여 일시 중단 대장) 보호관찰관은 영 제11조제2항에 따라 약물 투여를 일시 중단하는 경우에는 별지 제11호서식의 약물 투여 일시 중단 대장을 작성하여야 한다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9948, '제13조(약물 투여 일시 중단의 승인 신청) 영 제11조제3항에 따른 약물 투여 일시 중단의 승인 신청은 별지 제12호서식에 따른다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9949, '제14조(약물 투여 일시 중단의 승인) 영 제11조제4항에 따른 심사위원회의 승인 결정은 별지 제13호서식에 따른다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9950, '제15조(치료명령을 받은 사람의 부작용 치료 내용 등 보고) 영 제11조제5항에 따른 부작용 치료 내용 등의 보고는 별지 제14호서식에 따른다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9951, '제16조(약물 투여 재개 결정서) 영 제11조제6항에 따른 약물 투여 재개 결정은 별지 제15호서식에 따른다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9952, '제17조(약물치료 집행정지 대장) 보호관찰관은 법 제14조제4항에 따라 약물치료의 집행이 정지되는 경우에는 별지 제16호서식의 약물치료 집행정지 대장을 작성하여야 한다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9953, '제18조(구금해제 통보) 법 제14조제5항제1호 및 영 제12조제4항에 따른 구금해제 통보는 별지 제17호서식에 따른다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9954, '제19조(호르몬 수치 등 검사 의뢰) 영 제13조제3항에 따른 호르몬 수치 등 검사 의뢰는 별지 제18호서식에 따른다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9955, '제20조(주거 이전 신고 등)', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9956, '제21조(치료기간 연장 등의 신청)', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9957, '제22조(치료명령 가해제 신청 등) 법 제17조제1항 및 영 제16조제1항에 따른 가해제 신청, 법 제19조제1항 전단 및 영 제18조제1항에 따른 가해제 취소 신청은 별지 제26호서식에 따른다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9958, '제23조(치료명령 가해제 결정 등) 법 제18조제4항 및 제5항에 따른 가해제 결정, 법 제19조제1항 후단에 따른 가해제 취소 결정은 별지 제27호서식에 따른다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9959, '제24조(약물치료 동의 여부 확인) 법 제22조제2항제1호 및 영 제19조, 법 제22조제2항제5호 및 영 제22조제1항에 따른 동의 여부 확인은 별지 제28호서식에 따른다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9960, '제25조(성폭력 수형자의 약물치료 동의 사실 등 통보) 법 제22조제2항제2호 및 영 제20조에 따른 약물치료 동의 사실 등의 통보는 별지 제29호서식에 따른다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9961, '제26조(가석방 적격심사 신청) 영 제24조제1항에 따라 치료명령 결정 사실을 통보받은 수용시설의 장은 통보받은 날부터 1개월 이내에 「형의 집행 및 수용자의 처우에 관한 법률」 제121조에 따라 가석방 적격심사를 신청하여야 한다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9962, '제27조(치료비용 납부 명령서) 영 제26조제1항에 따른 치료비용 납부명령은 별지 제30호서식에 따른다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9963, '제28조(치료비용 국가 부담 신청서) 영 제26조제3항에 따른 치료비용 국가 부담 신청서는 별지 제31호서식에 따른다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9964, '제29조(자료 제출 동의 등)', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9965, '제30조(치료감호심의위원회의 진단 및 감정 의뢰) 영 제27조제1항 및 제2항에 따른 치료감호심의위원회의 진단 및 감정 의뢰는 별지 제34호서식에 따른다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9966, '제31조(치료명령 결정서 등)', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9967, '제32조(준용) 법 제29조 및 영 제29조에 따라 다른 규정을 준용하는 경우에 필요한 서식은 각각 해당 규정에서 정한 서식에 따른다.', 1330);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9968, '제1조(목적등)', 1331);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9969, '제2조(정의)', 1331);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9970, '제3조(반국가단체의 구성등)', 1332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9971, '제4조(목적수행)', 1332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9972, '제5조(자진지원ㆍ금품수수)', 1332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9973, '제6조(잠입ㆍ탈출)', 1332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9974, '제7조(찬양ㆍ고무등)', 1332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9975, '제8조(회합ㆍ통신등)', 1332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9976, '제9조(편의제공)', 1332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9977, '제10조(불고지) 제3조, 제4조, 제5조제1항ㆍ제3항(第1項의 未遂犯에 한한다)ㆍ제4항의 죄를 범한 자라는 정을 알면서 수사기관 또는 정보기관에 고지하지 아니한 자는 5년 이하의 징역 또는 200만원 이하의 벌금에 처한다. 다만, 본범과 친족관계가 있는 때에는 그 형을 감경 또는 면제한다.', 1332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9978, '제11조(특수직무유기) 범죄수사 또는 정보의 직무에 종사하는 공무원이 이 법의 죄를 범한 자라는 정을 알면서 그 직무를 유기한 때에는 10년 이하의 징역에 처한다. 다만, 본범과 친족관계가 있는 때에는 그 형을 감경 또는 면제할 수 있다.', 1332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9979, '제12조(무고, 날조)', 1332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9980, '제13조(특수가중) 이 법, 군형법 제13조ㆍ제15조 또는 형법 제2편제1장 내란의 죄ㆍ제2장 외환의 죄를 범하여 금고 이상의 형의 선고를 받고 그 형의 집행을 종료하지 아니한 자 또는 그 집행을 종료하거나 집행을 받지 아니하기로 확정된 후 5년이 경과하지 아니한 자가 제3조제1항제3호 및 제2항 내지 제5항, 제4조제1항제1호중 형법 제94조제2항ㆍ제97조 및 제99조, 동항제5호 및 제6호, 제2항 내지 제4항, 제5조, 제6조제1항 및 제4항 내지 제6항, 제7조 내지 제9조의 죄를 범한 때에는 그 죄에 대한 법정형의 최고를 사형으로 한다.', 1332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9981, '제14조(자격정지의 병과) 이 법의 죄에 관하여 유기징역형을 선고할 때에는 그 형의 장기 이하의 자격정지를 병과할 수 있다. <개정 1991ㆍ5ㆍ31>', 1332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9982, '제15조(몰수ㆍ추징)', 1332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9983, '제16조(형의 감면) 다음 각호의 1에 해당한 때에는 그 형을 감경 또는 면제한다.', 1332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9984, '제17조(타법적용의 배제) 이 법의 죄를 범한 자에 대하여는 노동조합및노동관계조정법 제39조의 규정을 적용하지 아니한다. <개정 1997ㆍ12ㆍ13>', 1332);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9985, '제18조(참고인의 구인ㆍ유치)', 1333);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9986, '제19조(구속기간의 연장)', 1333);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9987, '제20조(공소보류)', 1333);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9988, '제21조(상금)', 1334);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9989, '제22조(보로금)', 1334);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9990, '제23조(보상) 이 법의 죄를 범한 자를 신고 또는 체포하거나 이에 관련하여 상이를 입은 자와 사망한 자의 유족은 대통령령이 정하는 바에 따라 「국가유공자 등 예우 및 지원에 관한 법률」에 따른 공상군경 또는 순직군경의 유족이나 「보훈보상대상자 지원에 관한 법률」에 따른 재해부상군경 또는 재해사망군경의 유족으로 보아 보상할 수 있다. <개정 1997ㆍ1ㆍ13, 2011.9.15>', 1334);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9991, '제24조(국가보안유공자 심사위원회)', 1334);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9992, '제25조(군법 피적용자에 대한 준용규정) 이 법의 죄를 범한 자가 군사법원법 제2조제1항 각호의 1에 해당하는 자인 때에는 이 법의 규정중 판사는 군사법원군판사로, 검사는 군검찰부 군검사로, 사법경찰관은 군사법경찰관으로 본다. <개정 1987ㆍ12ㆍ4, 1994ㆍ1ㆍ5, 2016.1.6>', 1334);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9993, '제1조(목적) 이 영은 「교도작업의 운영 및 특별회계에 관한 법률」에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.', 1335);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9994, '제2조(다른 법령과의 관계) 「교도작업의 운영 및 특별회계에 관한 법률」(이하 "법"이라 한다)에 따른 교도작업의 운영 및 교도작업특별회계(이하 "특별회계"라 한다)에 관하여 다른 법령에 특별한 규정이 있는 경우를 제외하고는 이 영에서 정하는 바에 따른다.', 1335);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9995, '제3조(생산공급계획의 보고) 교도작업으로 생산되는 제품(이하 "교도작업제품"이라 한다)을 생산하는 교정시설의 장(이하 "소장"이라 한다)은 국가, 지방자치단체 또는 공공기관(이하 "수요기관"이라 한다)의 수요량과 해당 지역의 생산실태 등을 조사하여 법무부령으로 정하는 사항이 포함된 다음 연도의 생산공급계획을 수립하여 매년 10월 30일까지 법무부장관에게 보고하여야 한다.', 1335);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9996, '제4조(공고에 필요한 조사)', 1335);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9997, '제5조(교도작업제품의 종류 및 수량의 공고)', 1335);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9998, '제6조(교도작업의 종류)', 1335);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (9999, '제7조(교도작업제품의 판매방법) 법무부장관은 교도작업제품의 전시 및 판매를 위하여 필요한 시설을 설치ㆍ운영하거나 전자상거래 등의 방법으로 교도작업제품을 판매할 수 있다.', 1335);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10000, '제8조(특별회계의 회계기준)', 1335);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10001, '제9조(일반경쟁계약) 특별회계의 세입ㆍ세출의 원인이 되는 계약을 담당하는 공무원(이하 "계약담당자"라 한다)은 다음 각 호의 어느 하나에 해당하는 계약으로서 추정가격이 「국가를 당사자로 하는 계약에 관한 법률 시행령」 제26조제1항제5호가목에 따른 추정가격의 2배를 초과하는 계약을 하려는 경우에는 일반경쟁에 부쳐야 한다. <개정 2010.7.21>', 1335);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10002, '제10조(수의계약) 계약담당자는 제9조에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 수의계약으로 할 수 있다.', 1335);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10003, '제1조(목적) 이 법은 경제 사정의 변동에 따른 벌금, 과료 또는 과태료의 금액에 관한 특례를 정함을 목적으로 한다.', 1336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10004, '제2조 삭제 <1962.5.31>', 1336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10005, '제3조(벌금의 액수에 관한 특례) 이 법 또는 다른 법령에 따라 산출되거나 다른 법령에 규정된 벌금의 다액(多額)이 10만원 미만일 때에는 그 다액을 10만원으로 한다.', 1336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10006, '제4조(벌금 등의 적용)', 1336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10007, '제5조(적용 제외) 벌금, 과료 또는 과태료의 금액을 일정한 금액에 배수를 곱하여 정할 때에는 제4조를 적용하지 아니한다.', 1336);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10008, '제1조(목적) 이 규칙은 「사면법」 제10조의2제8항에 따라 사면심사위원회에 관하여 필요한 사항을 규정함을 목적으로 한다.', 1337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10009, '제2조(사면심사위원회의 기능) 사면심사위원회(이하 "위원회"라 한다)는 「사면법」 제10조제1항에 따른 법무부장관의 특별사면, 특정한 자에 대한 감형 및 복권(이하 "특별사면등" 이라 한다)의 상신(上申)이 적정하게 이루어질 수 있도록 심사ㆍ자문함을 목적으로 한다.', 1337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10010, '제3조(위원의 임명 및 위촉) 위원회의 위원은 다음 각 호의 자 중에서 법무부장관이 임명하거나 위촉한다.', 1337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10011, '제4조(공무원인 위원의 승계) 제3조제1호의 직위에 있는 자가 위원으로 임명된 경우 인사이동 등의 사유로 그 직위가 변동되었을 때에는 법무부장관이 달리 임명하지 아니하는 한 그 직위의 후임자가 위원직을 승계하는 것으로 본다.', 1337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10012, '제5조(위원의 회피)', 1337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10013, '제6조(위원장의 직무)', 1337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10014, '제7조(회의)', 1337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10015, '제8조(간사 등)', 1337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10016, '제9조(심사 및 의견제출) 위원회는 법무부장관의 요청에 따라 특별사면등 상신의 적정성 여부를 심사하고 그에 관한 의견을 법무부장관에게 제출한다.', 1337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10017, '제10조(심의서)', 1337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10018, '제11조(회의록)', 1337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10019, '제12조(위원의 해임 및 해촉) 법무부장관은 위원회의 위원이 다음 각호의 어느 하나에 해당하는 경우에는 해임하거나 해촉할 수 있다.', 1337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10020, '제13조(수당 등) 위원회의 위원에게는 예산의 범위에서 수당과 여비를 지급할 수 있다. 다만, 공무원인 위원이 그 소관업무와 직접적으로 관련되어 위원회에 출석하는 경우에는 그러하지 아니하다.', 1337);
INSERT INTO balaw.jo (id, content, jang_id) VALUES (10021, '제14조(운영세칙) 이 규칙에서 규정한 것 외에 위원회의 운영에 필요한 사항은 위원장이 정한다.', 1337);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1, '① 「환경범죄 등의 단속 및 가중처벌에 관한 법률」(이하 "법"이라 한다) 제12조제1항 각 호 외의 부분 단서에서 "대통령령으로 정하는 경우"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다.', 3);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2, '② 법 제12조제4항에 따른 과징금의 부과기준은 별표 1과 같다.', 3);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3, '③ 법 제12조제6항에 따라 환경부장관은 같은 조 제1항 각 호의 위반 사실을 알게 된 즉시 이를 신고하고 시정한 자에 대해서는 다음 각 호의 구분에 따라 과징금을 감면한다.', 3);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4, '④ 제3항 각 호의 구분에 따른 과징금 감면금액의 세부 기준은 환경부장관이 정하여 고시한다.', 3);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5, '① 환경부장관은 법 제12조에 따라 과징금을 부과하려면 위반행위의 종류와 해당 과징금의 금액을 분명하게 밝혀 이를 납부할 것을 서면으로 통지해야 한다.', 6);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6, '② 제1항에 따라 통지를 받은 자는 통지를 받은 날부터 60일 이내에 과징금을 환경부장관이 정하는 수납기관에 내야 한다. <개정 2023.12.12>', 6);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7, '③ 제2항에 따라 과징금을 받은 수납기관은 그 납부자에게 영수증을 발급해야 한다.', 6);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8, '④ 과징금 수납기관이 제2항에 따라 과징금을 수납한 때에는 지체 없이 그 사실을 환경부장관에게 통보해야 한다.', 6);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9, '⑤ 제1항부터 제4항까지에서 규정한 사항 외에 과징금의 부과 및 납부에 필요한 세부 사항은 환경부장관이 정하여 고시한다.', 6);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10, '① 양수인, 상속인 또는 합병 후 존속하는 법인이나 합병으로 새로 설립되는 법인이 법 제14조제2항에 따라 종전 사업자의 행정처분 절차 진행 여부 및 행정처분 이력 유무(이하 "종전사업자의 행정처분이력등"이라 한다)에 대한 확인을 환경부장관에게 요청하려면 별지 제1호서식의 행정처분 이력 등 확인 요청서를 제출해야 한다.', 10);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11, '② 제1항에 따라 요청서를 받은 환경부장관은 요청일부터 5일 이내에 종전사업자의 행정처분이력등을 확인하여 별지 제2호서식의 행정처분 이력 등 확인서를 요청인에게 발급해야 한다.', 10);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12, '① 삭제 <2013.10.22>', 11);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13, '② 법 제15조에 따라 범죄의 신고를 받은 수사기관, 환경부장관 및 지방환경관서의 장은 그 사건의 개요를 관할 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장(자치구의 구청장을 말한다)에게 통지하여야 한다.', 11);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14, '③ 법 제15조에 따라 범죄의 신고를 받거나 제2항에 따라 통지를 받은 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장(자치구의 구청장을 말한다)은 그 신고내용이 환경법위반행위에 해당된다고 인정하는 경우에는 예산의 범위에서 포상금을 지급할 수 있다. <개정 2013.10.22>', 11);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15, '④ 제3항에 따른 포상금은 300만원의 범위에서 지급하며, 포상금의 금액ㆍ지급시기 및 지급절차 등에 관하여 필요한 사항은 환경부장관이 정하여 고시한다.', 11);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16, '① 다음 각 호의 어느 하나에 해당하는 일반직공무원은 그 직위에 임용된 날부터 법 제15조의2제1항 각 호 외의 부분에 따른 환경감시관(이하 "환경감시관"이라 한다)에 임명된 것으로 본다. <개정 2020.11.10>', 12);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (17, '② 제1항의 경우 환경부 또는 지방환경관서에서 근무한 경력이 1년 미만인 공무원은 그 근무경력이 1년이 되는 날부터 환경감시관에 임명된 것으로 본다.', 12);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (18, '③ 환경부장관 또는 지방환경관서의 장은 법과 법 제15조의2제1항 각 호의 법률에서 규정하는 위반행위(이하 "환경관계법령위반행위"라 한다)의 단속 및 예방을 위하여 한시적으로 전담반을 구성할 특별한 필요가 있을 때에는 그 환경관계법령위반행위와 관련된 업무를 담당하고 있는 공무원을 환경감시관으로 임명할 수 있다. <개정 2020.11.10>', 12);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (19, '① 제11조에 따라 환경감시관으로 임명된 사람이 다음 각 호의 어느 하나에 해당하는 경우 환경감시관 임명이 해제된 것으로 본다.', 13);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (20, '② 환경부장관 또는 지방환경관서의 장은 제11조에 따라 환경감시관으로 임명된 사람이 환경관계법령위반행위의 단속 및 예방 업무와 관련하여 징계처분을 받거나 「국가공무원법」 제61조ㆍ제65조 또는 제66조를 위반하여 징계처분을 받은 경우에는 그 환경감시관의 임명을 지체 없이 해제해야 한다. <개정 2020.11.10>', 13);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (21, '③ 환경부장관 또는 지방환경관서의 장은 환경관계법령위반행위의 단속 및 예방 업무와 관련하여 징계처분을 받거나 「국가공무원법」 제61조ㆍ제65조 또는 제66조를 위반하여 징계처분을 받은 사람에 대해서는 그 처분을 받은 날부터 다음 각 호의 구분에 따른 기간 동안 환경감시관으로 임명해서는 안 된다. <개정 2020.11.10>', 13);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (22, null, 14);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (23, '① 환경부장관 또는 지방환경관서의 장은 환경감시관의 신분을 표시하는 증표를 발급하여야 한다.', 16);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (24, '② 제1항에 따른 증표의 발급에 필요한 사항은 환경부장관이 정한다.', 16);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (25, null, 17);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (26, '① 환경부장관은 법 제19조에 따라 다음 각 호의 권한을 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ도지사ㆍ특별자치도지사(이하 "시ㆍ도지사"라 한다)에게 위임한다. 다만, 제2항에 해당하는 권한 및 법 제2조제3호사목에 따른 배출시설에 대한 다음 각 호의 권한은 제외한다. <개정 2020.11.10, 2025.9.23>', 18);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (27, '② 환경부장관은 다음 각 호의 어느 하나에 해당하는 자에 대한 제1항 각 호의 권한(법 제2조제3호사목에 따른 배출시설에 대한 권한은 제외한다)을 지방환경관서의 장에게 위임한다. <개정 2020.11.10, 2025.8.5, 2025.9.23>', 18);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (28, '①법 제6조의 규정에 의한 신청을 함에는 그 사유를 기재한 신청서를 공통되는 직근 상급법원에 제출하여야 한다.', 21);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (29, '②검사의 신청서에는 피고인의 수에 상응한 부본을, 피고인의 신청서에는 부본 1통을 각 첨부하여야 한다.', 21);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (30, '③법 제6조의 신청을 받은 법원은 지체없이 각 사건계속법원에 그 취지를 통지하고 제2항의 신청서 부본을 신청인의 상대방에게 송달하여야 한다.', 21);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (31, '④사건계속법원과 신청인의 상대방은 제3항의 송달을 받은 날로부터 3일 이내에 의견서를 제1항의 법원에 제출할 수 있다. <개정 1991.8.3>', 21);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (32, '①법 제6조의 신청을 받은 법원이 신청을 이유있다고 인정한 때에는 관련사건을 병합심리할 법원을 지정하여 그 법원으로 하여금 병합심리하게 하는 취지의 결정을, 이유없다고 인정한 때에는 신청을 기각하는 취지의 결정을 각하고, 그 결정등본을 신청인과 그 상대방에게 송달하고 사건계속법원에 송부하여야 한다.', 22);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (33, '②제1항의 결정에 의하여 병합심리하게 된 법원 이외의 법원은 그 결정등본을 송부받은 날로부터 7일 이내에 소송기록과 증거물을 병합심리하게 된 법원에 송부하여야 한다.', 22);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (34, '①법 제10조의 규정은 법원합의부와 단독판사에 계속된 각 사건이 토지관할을 달리하는 경우에도 이를 적용한다.', 23);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (35, '②단독판사는 그가 심리 중인 사건과 관련된 사건이 합의부에 계속된 사실을 알게 된 때에는 즉시 합의부의 재판장에게 그 사실을 통지하여야 한다.', 23);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (36, '③합의부가 법 제10조의 규정에 의한 병합심리 결정을 한 때에는 즉시 그 결정등본을 단독판사에게 송부하여야 하고, 단독판사는 그 결정등본을 송부받은 날로부터 5일 이내에 소송기록과 증거물을 합의부에 송부하여야 한다.', 23);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (37, '①사물관할을 달리하는 수개의 관련항소사건이 각각 고등법원과 지방법원본원합의부에 계속된 때에는 고등법원은 결정으로 지방법원본원합의부에 계속한 사건을 병합하여 심리할 수 있다. 수개의 관련항소사건이 토지관할을 달리하는 경우에도 같다.', 24);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (38, '②지방법원본원합의부의 재판장은 그 부에서 심리 중인 항소사건과 관련된 사건이 고등법원에 계속된 사실을 알게 된 때에는 즉시 고등법원의 재판장에게 그 사실을 통지하여야 한다.', 24);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (39, '③고등법원이 제1항의 규정에 의한 병합심리결정을 한 때에는 즉시 그 결정등본을 지방법원본원합의부에 송부하여야 하고, 지방법원본원합의부는 그 결정등본을 송부받은 날로부터 5일 이내에 소송기록과 증거물을 고등법원에 송부하여야 한다.', 24);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (40, '①법 제16조제1항의 규정에 의하여, 검사가 관할지정 또는 관할이전의 신청서를 제출할 때에는 피고인 또는 피의자의 수에 상응한 부본을, 피고인이 관할이전의 신청서를 제출할 때에는 부본 1통을 각 첨부하여야 한다.', 25);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (41, '②제1항의 신청서를 제출받은 법원은 지체없이 검사의 신청서 부본을 피고인 또는 피의자에게 송달하여야 하고, 피고인의 신청서 부본을 검사에게 송달함과 함께 공소를 접수한 법원에 그 취지를 통지하여야 한다.', 25);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (42, '③검사, 피고인 또는 피의자는 제2항의 신청서 부본을 송부받은 날로부터 3일 이내에 의견서를 제2항의 법원에 제출할 수 있다.', 25);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (43, '①공소 제기전의 사건에 관하여 관할지정 또는 관할이전의 결정을 한 경우 결정을 한 법원은 결정등본을 검사와 피의자에게 각 송부하여야 하며, 검사가 그 사건에 관하여 공소를 제기할 때에는 공소장에 그 결정등본을 첨부하여야 한다.', 26);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (44, '②공소가 제기된 사건에 관하여 관할지정 또는 관할이전의 결정을 한 경우 결정을 한 법원은 결정등본을 검사와 피고인 및 사건계속법원에 각 송부하여야 한다.', 26);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (45, '③제2항의 경우 사건계속법원은 지체없이 소송기록과 증거물을 제2항의 결정등본과 함께 그 지정 또는 이전된 법원에 송부하여야 한다. 다만, 사건계속법원이 관할법원으로 지정된 경우에는 그러하지 아니하다.', 26);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (46, '①제3조제2항, 제4조제3항, 제4조의2제3항 또는 제6조제3항의 각 규정에 의하여 또는 법 제8조의 규정에 의한 이송결정에 의하여 소송기록과 증거물을 다른 법원으로 송부할 때에는 이를 송부받을 법원으로 직접 송부한다.', 28);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (47, '②제1항의 송부를 한 법원 및 송부를 받은 법원은 각각 그 법원에 대응하는 검찰청 검사 또는 고위공직자범죄수사처에 소속된 검사(이하 "수사처검사"라고 한다)에게 그 사실을 통지하여야 한다. <개정 2021.1.29>', 28);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (48, '①법 제18조의 규정에 의한 기피신청을 함에 있어서는 기피의 원인되는 사실을 구체적으로 명시하여야 한다.', 29);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (49, '②제1항에 위배된 기피신청의 처리는 법 제20조제1항의 규정에 의한다.', 29);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (50, '①법 제29조제2항에 따른 보조인의 신고는 보조인이 되고자 하는 자와 피고인 또는 피의자 사이의 신분관계를 소명하는 서면을 첨부하여 이를 하여야 한다. <개정 2007.10.29>', 31);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (51, '②공소제기전의 보조인 신고는 제1심에도 그 효력이 있다.', 31);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (52, '①국선변호인은 법원의 관할구역안에 사무소를 둔 변호사, 그 관할구역안에서 근무하는 공익법무관에관한법률에 의한 공익법무관(법무부와 그 소속기관 및 각급검찰청에서 근무하는 공익법무관을 제외한다. 이하 "공익법무관"이라 한다) 또는 그 관할구역안에서 수습 중인 사법연수생 중에서 이를 선정한다.', 38);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (53, '②제1항의 변호사, 공익법무관 또는 사법연수생이 없거나 기타 부득이한 때에는 인접한 법원의 관할구역안에 사무소를 둔 변호사, 그 관할구역안에서 근무하는 공익법무관 또는 그 관할구역안에서 수습 중인 사법연수생 중에서 이를 선정할 수 있다.', 38);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (54, '③제1항 및 제2항의 변호사, 공익법무관 또는 사법연수생이 없거나 기타 부득이한 때에는 법원의 관할 구역안에서 거주하는 변호사 아닌 자 중에서 이를 선정할 수 있다.', 38);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (55, '①국선변호인은 피고인 또는 피의자마다 1인을 선정한다. 다만, 사건의 특수성에 비추어 필요하다고 인정할 때에는 1인의 피고인 또는 피의자에게 수인의 국선변호인을 선정할 수 있다.', 39);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (56, '②피고인 또는 피의자 수인간에 이해가 상반되지 아니할 때에는 그 수인의 피고인 또는 피의자를 위하여 동일한 국선변호인을 선정할 수 있다.', 39);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (57, '① 법 제201조의2에 따라 심문할 피의자에게 변호인이 없거나 법 제214조의2에 따라 체포 또는 구속의 적부심사가 청구된 피의자에게 변호인이 없는 때에는 법원 또는 지방법원 판사는 지체 없이 국선변호인을 선정하고, 피의자와 변호인에게 그 뜻을 고지하여야 한다. <개정 2007.10.29>', 41);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (58, '②제1항의 경우 국선변호인에게 피의사실의 요지 및 피의자의 연락처 등을 함께 고지할 수 있다. <개정 2007.10.29>', 41);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (59, '③제1항의 고지는 서면 이외에 구술ㆍ전화ㆍ모사전송ㆍ전자우편ㆍ휴대전화 문자전송 그 밖에 적당한 방법으로 할 수 있다. <개정 2007.10.29>', 41);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (60, '④구속영장이 청구된 후 또는 체포ㆍ구속의 적부심사를 청구한 후에 변호인이 없게 된 때에도 제1항 및 제2항의 규정을 준용한다.', 41);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (61, '①지방법원 또는 지원은 국선변호를 담당할 것으로 예정한 변호사, 공익법무관, 사법연수생 등을 일괄 등재한 국선변호인 예정자명부(이하 ‘명부’라고 한다)를 작성할 수 있다. 이 경우 국선변호 업무의 내용 및 국선변호 예정일자를 미리 지정할 수 있다.', 42);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (62, '②지방법원 또는 지원의 장은 제1항의 명부 작성에 관하여 관할구역 또는 인접한 법원의 관할구역 안에 있는 지방변호사회장에게 협조를 요청할 수 있다.', 42);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (63, '③지방법원 또는 지원은 제1항의 명부를 작성한 후 지체없이 국선변호인 예정자에게 명부의 내용을 고지하여야 한다. 이 경우 제16조제3항의 규정을 적용한다.', 42);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (64, '④제1항의 명부에 기재된 국선변호인 예정자는 제3항의 고지를 받은 후 3일 이내에 명부의 변경을 요청할 수 있다.', 42);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (65, '⑤제1항의 명부가 작성된 경우 법원 또는 지방법원 판사는 특별한 사정이 없는 한 명부의 기재에 따라 국선변호인을 선정하여야 한다.', 42);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (66, '①재판장은 공소제기가 있는 때에는 변호인 없는 피고인에게 다음 각호의 취지를 고지한다.', 43);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (67, '②제1항의 고지는 서면으로 하여야 한다.', 43);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (68, '③법원은 제1항의 고지를 받은 피고인이 변호인을 선임하지 아니한 때 및 법 제33조제2항의 규정에 의하여 국선변호인 선정청구가 있거나 같은 조 제3항에 의하여 국선변호인을 선정하여야 할 때에는 지체없이 국선변호인을 선정하고, 피고인 및 변호인에게 그 뜻을 고지하여야 한다.', 43);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (69, '④공소제기가 있은 후 변호인이 없게 된 때에도 제1항 내지 제3항의 규정을 준용한다.', 43);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (70, '①법원 또는 지방법원 판사는 다음 각호의 어느 하나에 해당하는 때에는 국선변호인의 선정을 취소하여야 한다. <개정 2006.8.17>', 45);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (71, '②법원 또는 지방법원 판사는 다음 각호의 어느 하나에 해당하는 때에는 국선변호인의 선정을 취소할 수 있다. <개정 2006.8.17>', 45);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (72, '③법원이 국선변호인의 선정을 취소한 때에는 지체없이 그 뜻을 해당되는 국선변호인과 피고인 또는 피의자에게 통지하여야 한다.', 45);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (73, '①제16조제1항 또는 법 제283조의 규정에 의하여 국선변호인을 선정할 경우에 이미 선임된 변호인 또는 선정된 국선변호인이 출석하지 아니하거나 퇴정한 경우에 부득이한 때에는 피고인 또는 피의자의 의견을 들어 재정 중인 변호사 등 제14조에 규정된 사람을 국선변호인으로 선정할 수 있다. <개정 1995.7.10, 2006.8.17>', 46);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (74, '②제1항의 경우에는 이미 선정되었던 국선변호인에 대하여 그 선정을 취소할 수 있다.', 46);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (75, '③국선변호인이 공판기일 또는 피의자 심문기일에 출석할 수 없는 사유가 발생한 때에는 지체없이 법원 또는 지방법원 판사에게 그 사유를 소명하여 통지하여야 한다. <개정 2006.8.17>', 46);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (76, null, 47);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (77, '①결정 또는 명령을 함에 있어 법 제37조제3항의 규정에 의하여 사실을 조사하는 때 필요한 경우에는 법 및 이 규칙의 정하는 바에 따라 증인을 신문하거나 감정을 명할 수 있다.', 51);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (78, '②제1항의 경우에는 검사, 피고인, 피의자 또는 변호인을 참여하게 할 수 있다.', 51);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (79, '① 재판서에 잘못된 계산이나 기재, 그 밖에 이와 비슷한 잘못이 있음이 분명한 때에는 법원은 직권으로 또는 당사자의 신청에 따라 경정결정(更正決定)을 할 수 있다. <개정 2007.10.29>', 52);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (80, '②경정결정은 재판서의 원본과 등본에 덧붙여 적어야 한다. 다만, 등본에 덧붙여 적을 수 없을 때에는 경정결정의 등본을 작성하여 재판서의 등본을 송달받은 자에게 송달하여야 한다. <개정 2007.10.29>', 52);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (81, '③경정결정에 대하여는 즉시 항고를 할 수 있다. 다만, 재판에 대하여 적법한 상소가 있는 때에는 그러하지 아니하다.', 52);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (82, '①법 제45조에 규정한 기타의 소송관계인이라 함은 검사, 변호인, 보조인, 법인인 피고인의 대표자, 법 제28조의 규정에 의한 특별대리인, 법 제340조 및 제341조제1항의 규정에 의한 상소권자를 말한다.', 54);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (83, '②고소인, 고발인 또는 피해자는 비용을 납입하고 재판서 또는 재판을 기재한 조서의 등본 또는 초본의 교부를 청구할 수 있다. 다만, 그 청구하는 사유를 소명하여야 한다.', 54);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (84, '① 조서에는 서면, 사진, 속기록, 녹음물, 영상녹화물, 녹취서 등 법원이 적당하다고 인정한 것을 인용하고 소송기록에 첨부하거나 전자적 형태로 보관하여 조서의 일부로 할 수 있다. <개정 2014.12.30>', 57);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (85, '② 제1항에 따라 속기록, 녹음물, 영상녹화물, 녹취서를 조서의 일부로 한 경우라도 재판장은 법원사무관 등으로 하여금 피고인, 증인, 그 밖의 소송관계인의 진술 중 중요한 사항을 요약하여 조서의 일부로 기재하게 할 수 있다. <신설 2014.12.30>', 57);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (86, '① 속기, 녹음 또는 영상녹화(녹음이 포함된 것을 말한다. 다음부터 같다)의 신청은 공판기일ㆍ공판준비기일을 열기 전까지 하여야 한다. <개정 2014.12.30>', 60);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (87, '② 피고인, 변호인 또는 검사의 신청이 있음에도 불구하고 특별한 사정이 있는 때에는 속기, 녹음 또는 영상녹화를 하지 아니하거나 신청하는 것과 다른 방법으로 속기, 녹음 또는 영상녹화를 할 수 있다. 다만, 이 경우 재판장은 공판기일에 그 취지를 고지하여야 한다.', 60);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (88, '① 재판장은 필요하다고 인정하는 때에는 법원사무관 등 또는 속기사 등에게 녹음 또는 영상녹화된 내용의 전부 또는 일부를 녹취할 것을 명할 수 있다. <개정 2007.10.29>', 68);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (89, '② 재판장은 법원사무관 등으로 하여금 제1항에 따라 작성된 녹취서의 전부 또는 일부를 조서에 인용하고 소송기록에 첨부하여 조서의 일부로 하게 할 수 있다. <개정 2007.10.29>', 68);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (90, '① 재판장은 법 제56조의2제3항에도 불구하고 피해자 또는 그 밖의 소송관계인의 사생활에 관한 비밀 보호 또는 신변에 대한 위해 방지 등을 위하여 특히 필요하다고 인정하는 경우에는 속기록, 녹음물 또는 영상녹화물의 사본의 교부를 불허하거나 그 범위를 제한할 수 있다. <개정 2014.12.30>', 69);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (91, '② 법 제56조의2제3항에 따라 속기록, 녹음물 또는 영상녹화물의 사본을 교부받은 사람은 그 사본을 당해 사건 또는 관련 소송의 수행과 관계 없는 용도로 사용하여서는 아니 된다.', 69);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (92, '①소송행위를 할 자가 국내에 있는 경우 주거 또는 사무소의 소재지와 법원 또는 검찰청, 고위공직자범죄수사처(이하 "수사처"라고 한다) 소재지와의 거리에 따라 해로는 100킬로미터, 육로는 200킬로미터마다 각 1일을 부가한다. 그 거리의 전부 또는 잔여가 기준에 미달할지라도 50킬로미터이상이면 1일을 부가한다. 다만, 법원은 홍수, 천재지변등 불가피한 사정이 있거나 교통통신의 불편정도를 고려하여 법정기간을 연장함이 상당하다고 인정하는 때에는 이를 연장할 수 있다. <개정 2021.1.29>', 76);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (93, '②소송행위를 할 자가 외국에 있는 경우의 법정기간에는 그 거주국의 위치에 따라 다음 각호의 기간을 부가한다.', 76);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (94, '① 법 제72조의2제2항에 따른 절차를 위한 기일의 통지는 서면 이외에 전화ㆍ모사전송ㆍ전자우편ㆍ휴대전화 문자전송 그 밖에 적당한 방법으로 할 수 있다. 이 경우 통지의 증명은 그 취지를 조서에 기재함으로써 할 수 있다.', 78);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (95, '② 법 제72조의2제2항에 따른 절차 진행에 관하여는 제123조의13제1항 내지 제4항과 제6항 내지 제8항을 준용한다.', 78);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (96, '①구속영장집행사무를 담당한 자가 구속영장을 집행한 때에는 구속영장에 집행일시와 장소를, 집행할 수 없었을 때에는 그 사유를 각 기재하고 기명날인하여야 한다. <개정 1996.12.3>', 82);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (97, '②구속영장의 집행에 관한 서류는 집행을 지휘한 검사 또는 수탁판사를 경유하여 구속영장을 발부한 법원에 이를 제출하여야 한다.', 82);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (98, '③ 삭제 <2007.10.29>', 82);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (99, '①피고인, 변호인, 피고인의 법정대리인, 법 제28조에 따른 피고인의 특별대리인, 배우자, 직계친족과 형제자매는 구속영장을 발부한 법원에 구속영장의 등본의 교부를 청구할 수 있다. <개정 1996.12.3, 2007.10.29>', 84);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (100, '②제1항의 경우에 고소인, 고발인 또는 피해자에 대하여는 제26조제2항의 규정을 준용한다.', 84);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (101, '①피고인을 구속한 때에 그 변호인이나 법 제30조제2항에 규정한 자가 없는 경우에는 피고인이 지정하는 자 1인에게 법 제87조제1항에 규정한 사항을 통지하여야 한다. <개정 1996.12.3>', 85);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (102, '②구속의 통지는 구속을 한 때로부터 늦어도 24시간이내에 서면으로 하여야 한다. 제1항에 규정한 자가 없어 통지를 하지 못한 경우에는 그 취지를 기재한 서면을 기록에 철하여야 한다. <개정 1996.12.3>', 85);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (103, '③급속을 요하는 경우에는 구속되었다는 취지 및 구속의 일시ㆍ장소를 전화 또는 모사전송기 기타 상당한 방법에 의하여 통지할 수 있다. 다만, 이 경우에도 구속통지는 다시 서면으로 하여야 한다. <신설 1996.12.3>', 85);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (104, '① 보석청구서 또는 구속취소청구서에는 다음 사항을 기재하여야 한다.', 87);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (105, '② 보석의 청구를 하거나 검사 아닌 자가 구속취소의 청구를 할 때에는 그 청구서의 부본을 첨부하여야 한다.', 87);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (106, '③ 법원은 제1항의 보석 또는 구속취소에 관하여 검사의 의견을 물을 때에는 제2항의 부본을 첨부하여야 한다.', 87);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (107, '① 보석의 청구인은 적합한 보석조건에 관한 의견을 밝히고 이에 관한 소명자료를 낼 수 있다.', 88);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (108, '② 보석의 청구인은 보석조건을 결정함에 있어 법 제99조제2항에 따른 이행가능한 조건인지 여부를 판단하기 위하여 필요한 범위 내에서 피고인(피고인이 미성년자인 경우에는 그 법정대리인 등)의 자력 또는 자산 정도에 관한 서면을 제출하여야 한다.', 88);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (109, '①검사는 법원으로부터 보석, 구속취소 또는 구속집행정지에 관한 의견요청이 있을 때에는 의견서와 소송서류 및 증거물을 지체 없이 법원에 제출하여야 한다. 이 경우 특별한 사정이 없는 한 의견요청을 받은 날의 다음날까지 제출하여야 한다. <개정 2007.10.29>', 89);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (110, '②보석에 대한 의견요청을 받은 검사는 보석허가가 상당하지 아니하다는 의견일 때에는 그 사유를 명시하여야 한다. <신설 1997.12.31>', 89);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (111, '③제2항의 경우 보석허가가 상당하다는 의견일 때에는 보석조건에 대하여 의견을 나타낼 수 있다. <신설 1997.12.31, 2007.10.29>', 89);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (112, '①보석의 청구를 받은 법원은 지체없이 심문기일을 정하여 구속된 피고인을 심문하여야 한다. 다만, 다음 각호의 어느 하나에 해당하는 때에는 그러하지 아니하다. <개정 2007.10.29>', 90);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (113, '②제1항의 규정에 의하여 심문기일을 정한 법원은 즉시 검사, 변호인, 보석청구인 및 피고인을 구금하고 있는 관서의 장에게 심문기일과 장소를 통지하여야 하고, 피고인을 구금하고 있는 관서의 장은 위 심문기일에 피고인을 출석시켜야 한다.', 90);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (114, '③제2항의 통지는 서면외에 전화ㆍ모사전송ㆍ전자우편ㆍ휴대전화 문자전송 그 밖에 적당한 방법으로 할 수 있다. 이 경우 통지의 증명은 그 취지를 심문조서에 기재함으로써 할 수 있다. <신설 1996.12.3, 2007.10.29>', 90);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (115, '④피고인, 변호인, 보석청구인은 피고인에게 유리한 자료를 낼 수 있다. <개정 1996.12.3, 2007.10.29>', 90);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (116, '⑤검사, 변호인, 보석청구인은 제1항의 심문기일에 출석하여 의견을 진술할 수 있다.', 90);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (117, '⑥ 법원은 피고인, 변호인 또는 보석청구인에게 보석조건을 결정함에 있어 필요한 자료의 제출을 요구할 수 있다. <신설 2007.10.29>', 90);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (118, '⑦법원은 피고인의 심문을 합의부원에게 명할 수 있다. <신설 1996.12.3, 2007.10.29>', 90);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (119, '① 법원은 법 제98조제3호의 보석조건으로 석방된 피고인이 보석조건을 이행함에 있어 피고인의 주거지를 관할하는 경찰서장에게 피고인이 주거제한을 준수하고 있는지 여부 등에 관하여 조사할 것을 요구하는 등 보석조건의 준수를 위하여 적절한 조치를 취할 것을 요구할 수 있다.', 93);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (120, '② 법원은 법 제98조제6호의 보석조건을 정한 경우 출입국사무를 관리하는 관서의 장에게 피고인에 대한 출국을 금지하는 조치를 취할 것을 요구할 수 있다.', 93);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (121, '③ 법 제100조제5항에 따라 보석조건 준수에 필요한 조치를 요구받은 관공서 그 밖의 공사단체의 장은 그 조치의 내용과 경과 등을 법원에 통지하여야 한다.', 93);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (122, '① 법 제102조제3항ㆍ제4항에 따른 과태료 재판의 절차에 관하여는 비송사건절차법 제248조, 제250조(다만, 검사에 관한 부분을 제외한다)를 준용한다.', 95);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (123, '② 법 제102조제3항에 따른 감치재판절차는 법원의 감치재판개시결정에 따라 개시된다. 이 경우 감치사유가 있은 날부터 20일이 지난 때에는 감치재판개시결정을 할 수 없다.', 95);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (124, '③ 법원은 감치재판절차를 개시한 이후에도 감치에 처함이 상당하지 아니하다고 인정되는 때에는 불처벌의 결정을 할 수 있다.', 95);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (125, '④ 제2항의 감치재판개시결정과 제3항의 불처벌결정에 대하여는 불복할 수 없다.', 95);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (126, '⑤ 제2항부터 제4항까지 및 법 제102조제3항ㆍ제4항에 따른 감치절차에 관하여는 「법정 등의 질서유지를 위한 재판에 관한 규칙」 제3조, 제6조, 제7조의2, 제8조, 제10조, 제11조, 제13조, 제15조, 제16조, 제18조, 제19조, 제21조부터 제23조, 제25조제1항을 준용한다.', 95);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (127, '①법 제102조제2항에 따른 보석취소 또는 구속집행정지취소의 결정이 있는 때 또는 기간을 정한 구속집행정지결정의 기간이 만료된 때에는 검사는 그 취소결정의 등본 또는 기간을 정한 구속집행정지결정의 등본에 의하여 피고인을 재구금하여야 한다. 다만, 급속을 요하는 경우에는 재판장, 수명법관 또는 수탁판사가 재구금을 지휘할 수 있다. <개정 1996.12.3, 2007.10.29>', 96);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (128, '②제1항 단서의 경우에는 법원사무관등에게 그 집행을 명할 수 있다. 이 경우에 법원사무관등은 그 집행에 관하여 필요한 때에는 사법경찰관리 또는 교도관에게 보조를 요구할 수 있으며 관할구역외에서도 집행할 수 있다. <신설 1996.12.3>', 96);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (129, '①상소기간중 또는 상소 중의 사건에 관한 피고인의 구속, 구속기간갱신, 구속취소, 보석, 보석의 취소, 구속집행정지와 그 정지의 취소의 결정은 소송기록이 상소법원에 도달하기까지는 원심법원이 이를 하여야 한다. <개정 1997.12.31>', 97);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (130, '②이송, 파기환송 또는 파기이송 중의 사건에 관한 제1항의 결정은 소송기록이 이송 또는 환송법원에 도달하기까지는 이송 또는 환송한 법원이 이를 하여야 한다.', 97);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (131, '①법원이 압수수색을 할 때에는 법원사무관등을 참여하게 하여야 한다.', 100);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (132, '②법원사무관등 또는 사법경찰관리가 압수수색영장에 의하여 압수수색을 할 때에는 다른 법원사무관등 또는 사법경찰관리를 참여하게 하여야 한다.', 100);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (133, '① 법 제150조의2제1항에 따른 증인의 소환은 소환장의 송달, 전화, 전자우편, 모사전송, 휴대전화 문자전송 그 밖에 적당한 방법으로 할 수 있다.', 108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (134, '② 증인을 신청하는 자는 증인의 소재, 연락처와 출석 가능성 및 출석 가능 일시 그 밖에 증인의 소환에 필요한 사항을 미리 확인하는 등 증인 출석을 위한 합리적인 노력을 다하여야 한다.', 108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (135, '①증인에 대한 소환장에는 그 성명, 피고인의 성명, 죄명, 출석일시 및 장소, 정당한 이유없이 출석하지 아니할 경우에는 과태료에 처하거나 출석하지 아니함으로써 생긴 비용의 배상을 명할 수 있고 또 구인할 수 있음을 기재하고 재판장이 기명날인하여야 한다. <개정 1996.12.3>', 109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (136, '②증인에 대한 구속영장에는 그 성명, 주민등록번호(住民登錄番號가 없거나 이를 알 수 없는 경우에는 生年月日), 직업 및 주거, 피고인의 성명, 죄명, 인치할 일시 및 장소, 발부 연월일 및 유효기간과 그 기간이 경과한 후에는 집행에 착수하지 못하고 구속영장을 반환하여야 한다는 취지를 기재하고 재판장이 서명날인하여야 한다. <개정 1996.12.3>', 109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (137, '① 법 제151조제2항부터 제8항까지의 감치재판절차는 법원의 감치재판개시결정에 따라 개시된다. 이 경우 감치사유가 발생한 날부터 20일이 지난 때에는 감치재판개시결정을 할 수 없다.', 112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (138, '② 감치재판절차를 개시한 후 감치결정 전에 그 증인이 증언을 하거나 그 밖에 감치에 처하는 것이 상당하지 아니하다고 인정되는 때에는 법원은 불처벌결정을 하여야 한다.', 112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (139, '③ 제1항의 감치재판개시결정과 제2항의 불처벌결정에 대하여는 불복할 수 없다.', 112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (140, '④ 법 제151조제7항의 규정에 따라 증인을 석방한 때에는 재판장은 바로 감치시설의 장에게 그 취지를 서면으로 통보하여야 한다.', 112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (141, '⑤ 제1항부터 제4항 및 법 제151조제2항부터 제8항까지에 따른 감치절차에 관하여는 「법정 등의 질서유지를 위한 재판에 관한 규칙」 제3조, 제6조부터 제8조까지, 제10조, 제11조, 제13조, 제15조부터 제19조까지, 제21조부터 제23조까지 및 제25조제1항(다만, 제23조제8항 중 "감치의 집행을 한 날"은 "법 제151조제5항의 규정에 따른 통보를 받은 날"로 고쳐 적용한다)을 준용한다.', 112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (142, '①재판장은 증인신문을 행함에 있어서 증명할 사항에 관하여 가능한 한 증인으로 하여금 개별적이고 구체적인 내용을 진술하게 하여야 한다. <개정 1996.12.3>', 119);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (143, '②다음 각호의 1에 규정한 신문을 하여서는 아니된다. 다만, 제2호 내지 제4호의 신문에 관하여 정당한 이유가 있는 경우에는 그러하지 아니하다.', 119);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (144, '①법 제161조의2제1항 전단의 규정에 의한 신문(이하 "주신문"이라 한다)은 증명할 사항과 이에 관련된 사항에 관하여 한다.', 120);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (145, '②주신문에 있어서는 유도신문을 하여서는 아니된다. 다만, 다음 각호의 1의 경우에는 그러하지 아니하다.', 120);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (146, '③재판장은 제2항 단서의 각호에 해당하지 아니하는 경우의 유도신문은 이를 제지하여야 하고, 유도신문의 방법이 상당하지 아니하다고 인정할 때에는 이를 제한할 수 있다.', 120);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (147, '①법 제161조의2제1항 후단의 규정에 의한 신문(이하 "반대신문"이라 한다)은 주신문에 나타난 사항과 이에 관련된 사항에 관하여 한다.', 121);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (148, '②반대신문에 있어서 필요할 때에는 유도신문을 할 수 있다.', 121);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (149, '③재판장은 유도신문의 방법이 상당하지 아니하다고 인정할 때에는 이를 제한할 수 있다.', 121);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (150, '④반대신문의 기회에 주신문에 나타나지 아니한 새로운 사항에 관하여 신문하고자 할 때에는 재판장의 허가를 받아야 한다.', 121);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (151, '⑤제4항의 신문은 그 사항에 관하여는 주신문으로 본다.', 121);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (152, '①주신문 또는 반대신문의 경우에는 증언의 증명력을 다투기 위하여 필요한 사항에 관한 신문을 할 수 있다.', 122);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (153, '②제1항에 규정한 신문은 증인의 경험, 기억 또는 표현의 정확성등 증언의 신빙성에 관한 사항 및 증인의 이해관계, 편견 또는 예단 등 증인의 신용성에 관한 사항에 관하여 한다. 다만, 증인의 명예를 해치는 내용의 신문을 하여서는 아니된다.', 122);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (154, '①주신문을 한 검사, 피고인 또는 변호인은 반대신문이 끝난 후 반대신문에 나타난 사항과 이와 관련된 사항에 관하여 다시 신문(이하 "재 주신문"이라 한다)을 할 수 있다.', 123);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (155, '②재 주신문은 주신문의 예에 의한다.', 123);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (156, '③제76조제4항, 제5항의 규정은 재 주신문의 경우에 이를 준용한다.', 123);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (157, '①재판장이 법 제161조의2제3항 전단의 규정에 의하여 검사, 피고인 및 변호인에 앞서 신문을 한 경우에 있어서 그 후에 하는 검사, 피고인 및 변호인의 신문에 관하여는 이를 신청한 자와 상대방의 구별에 따라 제75조 내지 제79조의 규정을 각 준용한다.', 125);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (158, '②재판장이 법 제161조의2제3항 후단의 규정에 의하여 신문순서를 변경한 경우의 신문방법은 재판장이 정하는 바에 의한다.', 125);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (159, '①증인에 대하여 서류 또는 물건의 성립, 동일성 기타 이에 준하는 사항에 관한 신문을 할 때에는 그 서류 또는 물건을 제시할 수 있다.', 127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (160, '②제1항의 서류 또는 물건이 증거조사를 마치지 않은 것일 때에는 먼저 상대방에게 이를 열람할 기회를 주어야 한다. 다만, 상대방이 이의하지 아니할 때에는 그러하지 아니한다.', 127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (161, '①증인의 기억이 명백치 아니한 사항에 관하여 기억을 환기시켜야 할 필요가 있을 때에는 재판장의 허가를 얻어 서류 또는 물건을 제시하면서 신문할 수 있다.', 128);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (162, '②제1항의 경우에는 제시하는 서류의 내용이 증인의 진술에 부당한 영향을 미치지 아니하도록 하여야 한다.', 128);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (163, '③제82조제2항의 규정은 제1항의 경우에 이를 준용한다.', 128);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (164, '①증인의 진술을 명확히 할 필요가 있을 때에는 도면, 사진, 모형, 장치등을 이용하여 신문할 수 있다.', 129);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (165, '②제83조제2항의 규정은 제1항의 경우에 이를 준용한다.', 129);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (166, '① 법 제163조의2에 따라 피해자와 동석할 수 있는 신뢰관계에 있는 사람은 피해자의 배우자, 직계친족, 형제자매, 가족, 동거인, 고용주, 변호사, 그 밖에 피해자의 심리적 안정과 원활한 의사소통에 도움을 줄 수 있는 사람을 말한다. <개정 2012.5.29>', 131);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (167, '② 법 제163조의2제1항에 따른 동석 신청에는 동석하고자 하는 자와 피해자 사이의 관계, 동석이 필요한 사유 등을 명시하여야 한다.', 131);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (168, '③ 재판장은 법 제163조의2제1항 또는 제2항에 따라 동석한 자가 부당하게 재판의 진행을 방해하는 때에는 동석을 중지시킬 수 있다.', 131);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (169, '① 법원은 신문할 증인이 법 제165조의2제1항에서 정한 자에 해당한다고 인정될 경우, 증인으로 신문하는 결정을 할 때 비디오 등 중계장치에 의한 중계시설 또는 차폐시설을 통한 신문 여부를 함께 결정하여야 한다. 이 때 증인의 연령, 증언할 당시의 정신적ㆍ심리적 상태, 범행의 수단과 결과 및 범행 후의 피고인이나 사건관계인의 태도 등을 고려하여 판단하여야 한다. <개정 2021.10.29>', 132);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (170, '② 법원은 증인신문 전 또는 증인신문 중에도 비디오 등 중계장치에 의한 중계시설 또는 차폐시설을 통하여 신문할 것을 결정할 수 있다.', 132);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (171, '① 법원은 법 제165조의2제1항에 따라 비디오 등 중계장치에 의한 중계시설 또는 차폐시설을 통하여 증인을 신문하는 경우, 증인의 보호를 위하여 필요하다고 인정하는 경우에는 결정으로 이를 공개하지 아니할 수 있다. <개정 2021.10.29>', 134);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (172, '② 증인으로 소환받은 증인과 그 가족은 증인보호 등의 사유로 증인신문의 비공개를 신청할 수 있다.', 134);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (173, '③ 재판장은 제2항의 신청이 있는 때에는 그 허가 여부 및 공개, 법정외의 장소에서의 신문 등 증인의 신문방식 및 장소에 관하여 결정하여야 한다.', 134);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (174, '④ 제1항의 결정을 한 경우에도 재판장은 적당하다고 인정되는 자의 재정을 허가할 수 있다.', 134);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (175, '① 법원은 비디오 등 중계장치에 의한 중계시설을 통하여 증인신문을 하는 경우, 법 제163조의2의 규정에 의하여 신뢰관계에 있는 자를 동석하게 할 때에는 제84조의5에 정한 비디오 등 중계장치에 의한 중계시설에 동석하게 한다. <개정 2021.10.29>', 135);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (176, '② 법원은 법원 직원이나 비디오 등 중계장치에 의한 중계시설을 관리하는 사람으로 하여금 비디오 등 중계장치의 조작과 증인신문 절차를 보조하게 할 수 있다. <개정 2021.10.29>', 135);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (177, '① 법 제165조의2제1항에 따라 증인신문을 하는 경우, 증인은 증언을 보조할 수 있는 인형, 그림 그 밖에 적절한 도구를 사용할 수 있다. <개정 2021.10.29>', 136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (178, '② 제1항의 증인은 증언을 하는 동안 담요, 장난감, 인형 등 증인이 선택하는 물품을 소지할 수 있다.', 136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (179, '① 법원은 법 제165조의2제1항에 따라 차폐시설을 설치함에 있어 피고인과 증인이 서로의 모습을 볼 수 없도록 필요한 조치를 취하여야 한다. <개정 2021.10.29>', 137);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (180, '② 법 제165조의2제1항에 따라 비디오 등 중계장치에 의한 중계시설을 통하여 증인신문을 할 때 중계장치를 통하여 증인이 피고인을 대면하거나 피고인이 증인을 대면하는 것이 증인의 보호를 위하여 상당하지 않다고 인정되는 경우 재판장은 검사, 변호인의 의견을 들어 증인 또는 피고인이 상대방을 영상으로 인식할 수 있는 장치의 작동을 중지시킬 수 있다. <신설 2021.10.29>', 137);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (181, '① 법원은 특별한 사정이 없는 한 예산의 범위 안에서 증인의 보호 및 지원에 필요한 시설을 설치한다.', 138);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (182, '② 법원은 제1항의 시설을 설치한 경우, 예산의 범위 안에서 그 시설을 관리ㆍ운영하고 증인의 보호 및 지원을 담당하는 직원을 둔다.', 138);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (183, '①감정유치장에는 피고인의 성명, 주민등록번호 등, 직업, 주거, 죄명, 범죄사실의 요지, 유치할 장소, 유치기간, 감정의 목적 및 유효기간과 그 기간 경과후에는 집행에 착수하지 못하고 영장을 반환하여야 한다는 취지를 기재하고 재판장 또는 수명법관이 서명날인하여야 한다. <개정 1996.12.3, 2007.10.29>', 139);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (184, '②감정유치기간의 연장이나 단축 또는 유치할 장소의 변경 등은 결정으로 한다.', 139);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (185, '①법원은 감정하기 위하여 피고인을 병원 기타 장소에 유치한 때에는 그 관리자의 청구에 의하여 입원료 기타 수용에 필요한 비용을 지급하여야 한다.', 141);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (186, '②제1항의 비용은 법원이 결정으로 정한다.', 141);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (187, '①감정에 필요한 처분의 허가장에는 법 제173조제2항에 규정한 사항외에 감정인의 직업, 유효기간을 경과하면 허가된 처분에 착수하지 못하며 허가장을 반환하여야 한다는 취지 및 발부연월일을 기재하고 재판장 또는 수명법관이 서명날인하여야 한다.', 143);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (188, '②법원이 감정에 필요한 처분의 허가에 관하여 조건을 붙인 경우에는 제1항의 허가장에 이를 기재하여야 한다.', 143);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (189, '①법 제179조의2제2항의 규정에 의하여 감정서의 설명을 하게 할 때에는 검사, 피고인 또는 변호인을 참여하게 하여야 한다.', 145);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (190, '②제1항의 설명의 요지는 조서에 기재하여야 한다.', 145);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (191, '①증거보전의 청구는 다음 지역을 관할하는 지방법원판사에게 하여야 한다.', 147);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (192, '②감정의 청구는 제1항제4호의 규정에 불구하고 감정함에 편리한 지방법원판사에게 할 수 있다.', 147);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (193, '①증거보전청구서에는 다음 사항을 기재하여야 한다.', 148);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (194, '② 삭제 <1996.12.3>', 148);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (195, '①영장의 청구는 서면으로 하여야 한다.', 150);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (196, '② 체포영장 및 구속영장의 청구서에는 범죄사실의 요지를 따로 기재한 서면 1통(수통의 영장을 청구하는 때에는 그에 상응하는 통수)을 첨부하여야 한다. <개정 2007.10.29>', 150);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (197, '③ 압수ㆍ수색ㆍ검증영장의 청구서에는 범죄사실의 요지, 압수ㆍ수색ㆍ검증의 장소 및 대상을 따로 기재한 서면 1통(수통의 영장을 청구하는 때에는 그에 상응하는 통수)을 첨부하여야 한다. <신설 2007.10.29>', 150);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (198, null, 152);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (199, null, 153);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (200, '①체포영장의 청구에는 체포의 사유 및 필요를 인정할 수 있는 자료를 제출하여야 한다.', 154);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (201, '②체포영장에 의하여 체포된 자 또는 현행범인으로 체포된 자에 대하여 구속영장을 청구하는 경우에는 법 제201조제2항에 규정한 자료외에 다음 각호의 자료를 제출하여야 한다.', 154);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (202, '③법 제214조의2제1항에 규정한 자는 체포영장 또는 구속영장의 청구를 받은 판사에게 유리한 자료를 제출할 수 있다.', 154);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (203, '④판사는 영장 청구서의 기재사항에 흠결이 있는 경우에는 전화 기타 신속한 방법으로 영장을 청구한 검사에게 그 보정을 요구할 수 있다. <신설 1997.12.31>', 154);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (204, '①구인을 위한 구속영장의 집행을 받아 인치된 피의자를 법원에 유치한 경우에 법원사무관등은 피의자의 도망을 방지하기 위한 적절한 조치를 취하여야 한다.', 164);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (205, '②제1항의 피의자를 법원외의 장소에 유치하는 경우에 판사는 구인을 위한 구속영장에 유치할 장소를 기재하고 서명날인하여 이를 교부하여야 한다.', 164);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (206, '① 삭제 <2007.10.29>', 165);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (207, '②체포된 피의자외의 피의자에 대한 심문기일은 관계인에 대한 심문기일의 통지 및 그 출석에 소요되는 시간 등을 고려하여 피의자가 법원에 인치된 때로부터 가능한 한 빠른 일시로 지정하여야 한다. <신설 1997.12.31>', 165);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (208, '③심문기일의 통지는 서면 이외에 구술ㆍ전화ㆍ모사전송ㆍ전자우편ㆍ휴대전화 문자전송 그 밖에 적당한 방법으로 신속하게 하여야 한다. 이 경우 통지의 증명은 그 취지를 심문조서에 기재함으로써 할 수 있다. <개정 1997.12.31, 2007.10.29>', 165);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (209, '① 판사는 피의자가 심문기일에의 출석을 거부하거나 질병 그 밖의 사유로 출석이 현저하게 곤란하고, 피의자를 심문 법정에 인치할 수 없다고 인정되는 때에는 피의자의 출석 없이 심문절차를 진행할 수 있다.', 166);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (210, '② 검사는 피의자가 심문기일에의 출석을 거부하는 때에는 판사에게 그 취지 및 사유를 기재한 서면을 작성 제출하여야 한다.', 166);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (211, '③ 제1항의 규정에 의하여 심문절차를 진행할 경우에는 출석한 검사 및 변호인의 의견을 듣고, 수사기록 그 밖에 적당하다고 인정하는 방법으로 구속사유의 유무를 조사할 수 있다.', 166);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (212, '① 판사는 피의자에게 구속영장청구서에 기재된 범죄사실의 요지를 고지하고, 피의자에게 일체의 진술을 하지 아니하거나 개개의 질문에 대하여 진술을 거부할 수 있으며, 이익 되는 사실을 진술할 수 있음을 알려주어야 한다.', 169);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (213, '② 판사는 구속 여부를 판단하기 위하여 필요한 사항에 관하여 신속하고 간결하게 심문하여야 한다. 증거인멸 또는 도망의 염려를 판단하기 위하여 필요한 때에는 피의자의 경력, 가족관계나 교우관계 등 개인적인 사항에 관하여 심문할 수 있다.', 169);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (214, '③ 검사와 변호인은 판사의 심문이 끝난 후에 의견을 진술할 수 있다. 다만, 필요한 경우에는 심문 도중에도 판사의 허가를 얻어 의견을 진술할 수 있다.', 169);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (215, '④ 피의자는 판사의 심문 도중에도 변호인에게 조력을 구할 수 있다.', 169);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (216, '⑤ 판사는 구속 여부의 판단을 위하여 필요하다고 인정하는 때에는 심문장소에 출석한 피해자 그 밖의 제3자를 심문할 수 있다.', 169);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (217, '⑥ 구속영장이 청구된 피의자의 법정대리인, 배우자, 직계친족, 형제자매나 가족, 동거인 또는 고용주는 판사의 허가를 얻어 사건에 관한 의견을 진술할 수 있다.', 169);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (218, '⑦ 판사는 심문을 위하여 필요하다고 인정하는 경우에는 호송경찰관 기타의 자를 퇴실하게 하고 심문을 진행할 수 있다.', 169);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (219, '①법 제204조의 규정에 의한 통지는 다음 각호의 1에 해당하는 사유가 발생한 경우에 이를 하여야 한다.', 172);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (220, '②제1항의 통지서에는 다음 각호의 사항을 기재하여야 한다.', 172);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (221, '③제1항제1호에 해당하는 경우에는 체포영장 또는 구속영장의 원본을 첨부하여야 한다.', 172);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (222, '①변호인은 구속영장이 청구된 피의자에 대한 심문 시작 전에 피의자와 접견할 수 있다.', 173);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (223, '②지방법원 판사는 심문할 피의자의 수, 사건의 성격 등을 고려하여 변호인과 피의자의 접견 시간을 정할 수 있다.', 173);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (224, '③지방법원 판사는 검사 또는 사법경찰관에게 제1항의 접견에 필요한 조치를 요구할 수 있다.', 173);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (225, '①피의자 심문에 참여할 변호인은 지방법원 판사에게 제출된 구속영장청구서 및 그에 첨부된 고소ㆍ고발장, 피의자의 진술을 기재한 서류와 피의자가 제출한 서류를 열람할 수 있다.', 174);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (226, '②검사는 증거인멸 또는 피의자나 공범 관계에 있는 자가 도망할 염려가 있는 등 수사에 방해가 될 염려가 있는 때에는 지방법원 판사에게 제1항에 규정된 서류(구속영장청구서는 제외한다)의 열람 제한에 관한 의견을 제출할 수 있고, 지방법원 판사는 검사의 의견이 상당하다고 인정하는 때에는 그 전부 또는 일부의 열람을 제한할 수 있다. <개정 2011.12.30>', 174);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (227, '③지방법원 판사는 제1항의 열람에 관하여 그 일시, 장소를 지정할 수 있다.', 174);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (228, '①구속기간연장의 신청은 서면으로 하여야 한다.', 176);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (229, '②제1항의 서면에는 수사를 계속하여야 할 상당한 이유와 연장을 구하는 기간을 기재하여야 한다.', 176);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (230, '①재체포영장의 청구서에는 재체포영장의 청구라는 취지와 법 제200조의2제4항에 규정한 재체포의 이유 또는 법 제214조의3에 규정한 재체포의 사유를 기재하여야 한다. <개정 1996.12.3>', 178);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (231, '②재구속영장의 청구서에는 재구속영장의 청구라는 취지와 법 제208조제1항 또는 법 제214조의3에 규정한 재구속의 사유를 기재하여야 한다. <개정 1996.12.3>', 178);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (232, '③제95조, 제95조의2, 제96조, 제96조의2 및 제96조의4의 규정은 재체포 또는 재구속의 영장의 청구 및 그 심사에 이를 준용한다. <신설 1996.12.3, 2007.10.29>', 178);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (233, '①제46조, 제49조제1항 및 제51조의 규정은 검사 또는 사법경찰관의 피의자 체포 또는 구속에 이를 준용한다. 다만, 체포영장에는 법 제200조의2제1항에서 규정한 체포의 사유를 기재하여야 한다. <개정 1996.12.3>', 179);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (234, '②체포영장에 의하여 체포되었거나 현행범으로 체포된 피의자에 대하여 구속영장청구가 기각된 경우에는 법 제200조의4제2항의 규정을 준용한다. <신설 1996.12.3>', 179);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (235, '③ 제96조의3의 규정은 구속영장의 인치ㆍ구금할 장소의 변경 청구에 준용한다. <신설 2020.12.28>', 179);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (236, null, 181);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (237, '①체포 또는 구속의 적부심사의 청구를 받은 법원은 지체 없이 청구인, 변호인, 검사 및 피의자를 구금하고 있는 관서(경찰서, 교도소 또는 구치소 등)의 장에게 심문기일과 장소를 통지하여야 한다. <개정 2007.10.29>', 183);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (238, '②사건을 수사 중인 검사 또는 사법경찰관은 제1항의 심문기일까지 수사관계서류와 증거물을 법원에 제출하여야 하고, 피의자를 구금하고 있는 관서의 장은 위 심문기일에 피의자를 출석시켜야 한다. 법원사무관 등은 체포적부심사청구사건의 기록표지에 수사관계서류와 증거물의 접수 및 반환의 시각을 기재하여야 한다. <개정 1996.12.3>', 183);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (239, '③제54조의2제3항의 규정은 제1항에 따른 통지에 이를 준용한다. <개정 1996.12.3, 2007.10.29>', 183);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (240, '① 법 제214조의2제9항에 따라 심문기일에 출석한 검사ㆍ변호인ㆍ청구인은 법원의 심문이 끝난 후 의견을 진술할 수 있다. 다만, 필요한 경우에는 심문 도중에도 판사의 허가를 얻어 의견을 진술할 수 있다.', 185);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (241, '② 피의자는 판사의 심문 도중에도 변호인에게 조력을 구할 수 있다.', 185);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (242, '③ 체포 또는 구속된 피의자, 변호인, 청구인은 피의자에게 유리한 자료를 낼 수 있다.', 185);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (243, '④ 법원은 피의자의 심문을 합의부원에게 명할 수 있다.', 185);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (244, '①압수, 수색 또는 검증을 위한 영장의 청구서에는 다음 각호의 사항을 기재하여야 한다. <개정 1996.12.3, 2007.10.29, 2011.12.30>', 187);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (245, '②신체검사를 내용으로 하는 검증을 위한 영장의 청구서에는 제1항 각호의 사항외에 신체검사를 필요로 하는 이유와 신체검사를 받을 자의 성별, 건강상태를 기재하여야 한다.', 187);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (246, '①법 제215조의 규정에 의한 청구를 할 때에는 피의자에게 범죄의 혐의가 있다고 인정되는 자료와 압수, 수색 또는 검증의 필요 및 해당 사건과의 관련성을 인정할 수 있는 자료를 제출하여야 한다. <개정 2011.12.30>', 188);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (247, '②피의자 아닌 자의 신체, 물건, 주거 기타 장소의 수색을 위한 영장의 청구를 할 때에는 압수하여야 할 물건이 있다고 인정될 만한 자료를 제출하여야 한다.', 188);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (248, null, 191);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (249, null, 193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (250, null, 194);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (251, '①법 제225조 내지 제227조의 규정에 의하여 고소할 때에는 고소인과 피해자와의 신분관계를 소명하는 서면을, 법 제229조에 의하여 고소할 때에는 혼인의 해소 또는 이혼소송의 제기사실을 소명하는 서면을 각 제출하여야 한다.', 196);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (252, '②법 제228조의 규정에 의하여 검사의 지정을 받은 고소인이 고소할 때에는 그 지정받은 사실을 소명하는 서면을 제출하여야 한다.', 196);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (253, '①공소장에는 법 제254조제3항에 규정한 사항외에 다음 각호의 사항을 기재하여야 한다. <개정 1996.12.3, 2007.10.29>', 197);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (254, '②제1항제1호에 규정한 사항이 명백하지 아니할 때에는 그 취지를 기재하여야 한다.', 197);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (255, '① 공소장에는, 공소제기전에 변호인이 선임되거나 보조인의 신고가 있는 경우 그 변호인선임서 또는 보조인신고서를, 공소제기전에 특별대리인의 선임이 있는 경우 그 특별대리인 선임결정등본을, 공소제기당시 피고인이 구속되어 있거나, 체포 또는 구속된 후 석방된 경우 체포영장, 긴급체포서, 구속영장 기타 구속에 관한 서류를 각 첨부하여야 한다. <개정 1996.12.3>', 198);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (256, '②공소장에는 제1항에 규정한 서류외에 사건에 관하여 법원에 예단이 생기게 할 수 있는 서류 기타 물건을 첨부하거나 그 내용을 인용하여서는 아니된다. <개정 1996.12.3>', 198);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (257, '①법 제264조제2항에 규정된 취소는 관할고등법원에 서면으로 하여야 한다. 다만, 기록이 관할고등법원에 송부되기 전에는 그 기록이 있는 검찰청 검사장 또는 지청장에게 하여야 한다.', 201);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (258, '②제1항의 취소서를 제출받은 고등법원의 법원사무관등은 즉시 관할 고등검찰청 검사장 및 피의자에게 그 사유를 통지하여야 한다. <개정 2007.10.29>', 201);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (259, null, 203);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (260, '① 법 제262조의3제1항에 따른 재판의 집행에 관하여는 법 제477조의 규정을 준용한다.', 204);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (261, '② 제1항의 비용의 부담을 명하는 재판에 그 금액을 표시하지 아니한 때에는 집행을 지휘하는 검사가 산정한다.', 204);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (262, '① 법 제262조의3제2항과 관련한 비용은 다음 각 호에 해당하는 것으로 한다.', 205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (263, '② 제1항제2호의 비용을 계산함에 있어 선임료를 부담하였거나 부담할 변호인이 여러 명이 있은 경우에는 그 중 가장 고액의 선임료를 상한으로 한다.', 205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (264, '③ 제1항제2호의 변호사 선임료는 사안의 성격ㆍ난이도, 조사에 소요된 기간 그 밖에 변호인의 변론활동에 소요된 노력의 정도 등을 종합적으로 고려하여 상당하다고 인정되는 금액으로 정한다.', 205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (265, '① 피의자가 법 제262조의3제2항에 따른 신청을 할 때에는 다음 각 호의 사항을 기재한 서면을 재정신청사건의 관할 법원에 제출하여야 한다.', 206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (266, '② 피의자는 제1항의 서면을 제출함에 있어 비용명세서 그 밖에 비용액을 소명하는 데 필요한 서면과 고소인 수에 상응하는 부본을 함께 제출하여야 한다.', 206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (267, '③ 법원은 제1항 및 제2항의 서면의 부본을 재정신청인에게 송달하여야 하고, 재정신청인은 위 서면을 송달받은 날로부터 10일 이내에 이에 대한 의견을 서면으로 법원에 낼 수 있다.', 206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (268, '④ 법원은 필요하다고 인정하는 경우에는 피의자 또는 변호인에게 비용액의 심리를 위하여 필요한 자료의 제출 등을 요구할 수 있고, 재정신청인, 피의자 또는 변호인을 심문할 수 있다.', 206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (269, '⑤ 비용지급명령에는 피의자 및 재정신청인, 지급을 명하는 금액을 표시하여야 한다. 비용지급명령의 이유는 특히 필요하다고 인정되는 경우가 아니면 이를 기재하지 아니한다.', 206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (270, '⑥ 비용지급명령은 피의자 및 재정신청인에게 송달하여야 하고, 법 제262조의3제3항에 따른 즉시항고기간은 피의자 또는 재정신청인이 비용지급명령서를 송달받은 날부터 진행한다.', 206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (271, '⑦ 확정된 비용지급명령정본은 「민사집행법」에 따른 강제집행에 관하여는 민사절차에서의 집행력 있는 판결정본과 동일한 효력이 있다.', 206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (272, null, 208);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (273, '① 법 제266조의4제1항의 신청은 다음 사항을 기재한 서면으로 하여야 한다.', 210);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (274, '② 제1항의 신청서에는 다음 각 호의 서류를 첨부하여야 한다.', 210);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (275, '③ 법원은 제1항의 신청이 있는 경우, 즉시 신청서 부본을 검사에게 송부하여야 하고, 검사는 이에 대한 의견을 제시할 수 있다.', 210);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (276, '④ 제1항, 제2항제1호ㆍ제3호의 규정은 법 제266조의11제3항에 따른 검사의 신청에 이를 준용한다. 법원은 검사의 신청이 있는 경우 즉시 신청서 부본을 피고인 또는 변호인에게 송부하여야 하고, 피고인 또는 변호인은 이에 대한 의견을 제시할 수 있다.', 210);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (277, '① 검사, 피고인 또는 변호인은 공판준비 또는 공판기일에서 법원의 허가를 얻어 구두로 상대방에게 법 제266조의3ㆍ제266조의11에 따른 서류 등의 열람 또는 등사를 신청할 수 있다.', 211);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (278, '② 상대방이 공판준비 또는 공판기일에서 서류 등의 열람 또는 등사를 거부하거나 그 범위를 제한한 때에는 법원은 법 제266조의4제2항의 결정을 할 수 있다.', 211);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (279, '③ 제1항, 제2항에 따른 신청과 결정은 공판준비 또는 공판기일의 조서에 기재하여야 한다.', 211);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (280, '① 사건이 공판준비절차에 부쳐진 때에는 검사는 증명하려는 사실을 밝히고 이를 증명하는 데 사용할 증거를 신청하여야 한다.', 213);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (281, '② 피고인 또는 변호인은 검사의 증명사실과 증거신청에 대한 의견을 밝히고, 공소사실에 관한 사실상ㆍ법률상 주장과 그에 대한 증거를 신청하여야 한다.', 213);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (282, '③ 검사ㆍ피고인 또는 변호인은 필요한 경우 상대방의 주장 및 증거신청에 대하여 필요한 의견을 밝히고, 그에 관한 증거를 신청할 수 있다.', 213);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (283, '① 법원은 사건을 공판준비절차에 부친 때에는 집중심리를 하는 데 필요한 심리계획을 수립하여야 한다.', 214);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (284, '② 검사ㆍ피고인 또는 변호인은 특별한 사정이 없는 한 필요한 증거를 공판준비절차에서 일괄하여 신청하여야 한다.', 214);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (285, '③ 법원은 증인을 신청한 자에게 증인의 소재, 연락처, 출석 가능성 및 출석이 가능한 일시 등 증인의 신문에 필요한 사항의 준비를 명할 수 있다.', 214);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (286, '① 재판장은 검사ㆍ피고인 또는 변호인에게 기한을 정하여 공판준비 절차의 진행에 필요한 사항을 미리 준비하게 하거나 그 밖에 공판준비에 필요한 명령을 할 수 있다.', 215);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (287, '② 재판장은 기한을 정하여 법 제266조의6제2항에 규정된 서면의 제출을 명할 수 있다.', 215);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (288, '③ 제2항에 따른 서면에는 필요한 사항을 구체적이고 간결하게 기재하여야 하고, 증거로 할 수 없거나 증거로 신청할 의사가 없는 자료에 기초하여 법원에 사건에 대한 예단 또는 편견을 발생하게 할 염려가 있는 사항을 기재하여서는 아니 된다.', 215);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (289, '④ 피고인이 제2항에 따른 서면을 낼 때에는 1통의 부본을, 검사가 제2항에 따른 서면을 낼 때에는 피고인의 수에 1을 더한 수에 해당하는 부본을 함께 제출하여야 한다. 다만, 여러 명의 피고인에 대하여 동일한 변호인이 선임된 경우에는 검사는 변호인의 수에 1을 더한 수에 해당하는 부본만을 낼 수 있다.', 215);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (290, '① 법 제266조의7에 따라 공판준비 기일이 지정된 사건에 관하여 피고인에게 변호인이 없는 때에는 법원은 지체 없이 국선변호인을 선정하고, 피고인 및 변호인에게 그 뜻을 고지하여야 한다.', 217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (291, '② 공판준비기일이 지정된 후에 변호인이 없게 된 때에도 제1항을 준용한다.', 217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (292, '① 법원이 공판준비기일을 진행한 경우에는 참여한 법원사무관 등이 조서를 작성하여야 한다.', 218);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (293, '② 제1항의 조서에는 피고인, 증인, 감정인, 통역인 또는 번역인의 진술의 요지와 쟁점 및 증거에 관한 정리결과 그 밖에 필요한 사항을 기재하여야 한다.', 218);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (294, '③ 제1항, 제2항의 조서에는 재판장 또는 법관과 참여한 법원사무관 등이 기명날인 또는 서명하여야 한다.', 218);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (295, '① 법 제266조의17제1항에 따른 공판준비기일(이하 "영상공판준비기일"이라 한다)은 검사, 변호인을 비디오 등 중계장치에 의한 중계시설에 출석하게 하거나 인터넷 화상장치를 이용하여 지정된 인터넷주소에 접속하게 하고, 영상과 음향의 송수신에 의하여 법관, 검사, 변호인이 상대방을 인식할 수 있는 방법으로 한다.', 219);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (296, '② 제1항의 비디오 등 중계장치에 의한 중계시설은 법원 청사 안에 설치하되, 필요한 경우 법원 청사 밖의 적당한 곳에 설치할 수 있다.', 219);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (297, '③ 법원은 제2항 후단에 따라 비디오 등 중계장치에 의한 중계시설이 설치된 관공서나 그 밖의 공사단체의 장에게 영상공판준비기일의 원활한 진행에 필요한 조치를 요구할 수 있다.', 219);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (298, '④ 영상공판준비기일에서의 서류 등의 제시는 비디오 등 중계장치에 의한 중계시설이나 인터넷 화상장치를 이용하거나 모사전송, 전자우편, 그 밖에 이에 준하는 방법으로 할 수 있다.', 219);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (299, '⑤ 인터넷 화상장치를 이용하는 경우 영상공판준비기일에 지정된 인터넷 주소에 접속하지 아니한 때에는 불출석한 것으로 본다. 다만, 당사자가 책임질 수 없는 사유로 접속할 수 없었던 때에는 그러하지 아니하다.', 219);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (300, '⑥ 통신불량, 소음, 서류 등 확인의 불편, 제3자 관여 우려 등의 사유로 영상공판준비기일의 실시가 상당하지 아니한 당사자가 있는 경우 법원은 기일을 연기 또는 속행하면서 그 당사자가 법정에 직접 출석하는 기일을 지정할 수 있다.', 219);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (301, '⑦ 법원조직법 제58조제2항에 따른 명령을 위반하는 행위, 같은 법 제59조에 위반하는 행위, 심리방해행위 또는 재판의 위신을 현저히 훼손하는 행위가 있는 경우 감치 또는 과태료에 처하는 재판에 관하여는 법정등의질서유지를위한재판에관한규칙에 따른다.', 219);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (302, '⑧ 영상공판준비기일을 실시한 경우 그 취지를 조서에 적어야 한다.', 219);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (303, '① 법 제276조의2제1항에 따라 피고인과 동석할 수 있는 신뢰관계에 있는 자는 피고인의 배우자, 직계친족, 형제자매, 가족, 동거인, 고용주 그 밖에 피고인의 심리적 안정과 원활한 의사소통에 도움을 줄 수 있는 자를 말한다.', 225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (304, '② 법 제276조의2제1항에 따른 동석 신청에는 동석하고자 하는 자와 피고인 사이의 관계, 동석이 필요한 사유 등을 밝혀야 한다.', 225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (305, '③ 피고인과 동석한 신뢰관계에 있는 자는 재판의 진행을 방해하여서는 아니 되며, 재판장은 동석한 신뢰관계 있는 자가 부당하게 재판의 진행을 방해하는 때에는 동석을 중지시킬 수 있다.', 225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (306, '① 법 제277조 제3호에 규정한 불출석허가신청은 공판기일에 출석하여 구술로 하거나 공판기일 외에서 서면으로 할 수 있다.', 226);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (307, '② 법원은 피고인의 불출석허가신청에 대한 허가 여부를 결정하여야 한다.', 226);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (308, '③ 법원은 피고인의 불출석을 허가한 경우에도 피고인의 권리보호 등을 위하여 그 출석이 필요하다고 인정되는 때에는 불출석 허가를 취소할 수 있다.', 226);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (309, '① 법원이 법 제277조의2에 따라 피고인의 출석 없이 공판절차를 진행하고자 하는 경우에는 미리 그 사유가 존재하는가의 여부를 조사하여야 한다. <개정 2007.10.29>', 228);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (310, '② 법원이 제1항의 조사를 함에 있어서 필요하다고 인정하는 경우에는 교도관리 기타 관계자의 출석을 명하여 진술을 듣거나 그들로 하여금 보고서를 제출하도록 명할 수 있다. <개정 2007.10.29>', 228);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (311, '③법원은 합의부원으로 하여금 제1항의 조사를 하게 할 수 있다.', 228);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (312, '① 재판장은 전문심리위원을 소송절차에 참여시키기 위하여 필요하다고 인정한 때에는 쟁점의 확인 등 적절한 준비를 지시할 수 있다.', 233);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (313, '② 재판장이 제1항의 준비를 지시한 때에는 법원사무관등은 검사, 피고인 또는 변호인에게 그 취지를 통지하여야 한다.', 233);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (314, '① 전문심리위원이 공판준비기일 또는 공판기일에 참여한 때에는 조서에 그 성명을 기재하여야 한다.', 235);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (315, '② 전문심리위원이 재판장, 수명법관 또는 수탁판사의 허가를 받아 소송관계인에게 질문을 한 때에는 조서에 그 취지를 기재하여야 한다.', 235);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (316, '① 법 제279조의2 제1항에 따른 결정의 취소 신청은 기일에서 하는 경우를 제외하고는 서면으로 하여야 한다.', 236);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (317, '② 제1항의 신청을 할 때에는 신청 이유를 밝혀야 한다. 다만, 검사와 피고인 또는 변호인이 동시에 신청할 때에는 그러하지 아니하다.', 236);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (318, '① 재판장은 법 제285조에 따른 검사의 모두진술 절차를 마친 뒤에 피고인에게 공소사실을 인정하는지 여부에 관하여 물어야 한다.', 239);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (319, '② 피고인 및 변호인은 공소에 관한 의견 그 밖에 이익이 되는 사실 등을 진술할 수 있다.', 239);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (320, '① 검사, 피고인 또는 변호인은 특별한 사정이 없는 한 증거를 일괄하여 신청하여야 한다.', 244);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (321, '② 검사, 피고인 또는 변호인은 증명하려는 사실과 관련되고 그 사실의 증명에 필요한 증거만을 선별하여 신청하여야 한다.', 244);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (322, '③ 법원은 제1항 및 제2항을 위반하거나 재판에 부당한 지연을 초래하는 증거신청을 기각할 수 있다.', 244);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (323, '①검사, 피고인 또는 변호인이 증거신청을 함에 있어서는 그 증거와 증명하고자 하는 사실과의 관계를 구체적으로 명시하여야 한다.', 245);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (324, '②피고인의 자백을 보강하는 증거나 정상에 관한 증거는 보강증거 또는 정상에 관한 증거라는 취지를 특히 명시하여 그 조사를 신청하여야 한다.', 245);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (325, '③서류나 물건의 일부에 대한 증거신청을 함에 있어서는 증거로 할 부분을 특정하여 명시하여야 한다.', 245);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (326, '④법원은 필요하다고 인정할 때에는 증거신청을 한 자에게, 신문할 증인, 감정인, 통역인 또는 번역인의 성명, 주소, 서류나 물건의 표목 및 제1항 내지 제3항에 규정된 사항을 기재한 서면의 제출을 명할 수 있다.', 245);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (327, '⑤제1항 내지 제4항의 규정에 위반한 증거신청은 이를 기각할 수 있다.', 245);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (328, '① 법 제311조부터 법 제315조까지 또는 법 제318조에 따라 증거로 할 수 있는 서류나 물건이 수사기록의 일부인 때에는 검사는 이를 특정하여 개별적으로 제출함으로써 그 조사를 신청하여야 한다. 수사기록의 일부인 서류나 물건을 자백에 대한 보강증거나 피고인의 정상에 관한 증거로 낼 경우 또는 법 제274조에 따라 공판기일전에 서류나 물건을 낼 경우에도 이와 같다. <개정 2007.10.29>', 246);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (329, '②제1항의 규정에 위반한 증거신청은 이를 기각할 수 있다.', 246);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (330, '①법 제272조에 따른 보관서류의 송부요구신청은 법원, 검찰청, 수사처, 기타의 공무소 또는 공사단체(이하 "法院등"이라고 한다)가 보관하고 있는 서류의 일부에 대하여도 할 수 있다. <개정 2007.10.29, 2021.1.29>', 247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (331, '②제1항의 신청을 받은 법원이 송부요구신청을 채택하는 경우에는 서류를 보관하고 있는 법원등에 대하여 그 서류 중 신청인 또는 변호인이 지정하는 부분의 인증등본을 송부하여 줄 것을 요구할 수 있다.', 247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (332, '③제2항의 규정에 의한 요구를 받은 법원등은 당해서류를 보관하고 있지 아니하거나 기타 송부요구에 응할 수 없는 사정이 있는 경우를 제외하고는 신청인 또는 변호인에게 당해서류를 열람하게 하여 필요한 부분을 지정할 수 있도록 하여야 하며 정당한 이유없이 이에 대한 협력을 거절하지 못한다.', 247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (333, '④서류의 송부요구를 받은 법원등이 당해서류를 보관하고 있지 아니하거나 기타 송부요구에 응할 수 없는 사정이 있는 때에는 그 사유를 요구법원에 통지하여야 한다.', 247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (334, '① 법원은 재판업무 및 그에 부수하는 업무의 수행을 위하여 필요한 경우 「개인정보 보호법」제23조의 민감정보, 제24조의 고유식별정보, 제24조의2의 주민등록번호 및 그 밖의 개인정보를 처리할 수 있다. <개정 2014.8.6>', 248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (335, '② 법원은 필요하다고 인정하는 경우 법 제272조에 따라 법원등에 대하여 제1항의 민감정보, 고유식별정보, 주민등록번호 및 그 밖의 개인정보가 포함된 자료의 송부를 요구할 수 있다. <개정 2014.8.6>', 248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (336, '③ 제2항에 따른 송부에 관하여는 제132조의4제2항부터 제4항까지의 규정을 준용한다.', 248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (337, '①법원은 증거결정을 함에 있어서 필요하다고 인정할 때에는 그 증거에 대한 검사, 피고인 또는 변호인의 의견을 들을 수 있다.', 250);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (338, '②법원은 서류 또는 물건이 증거로 제출된 경우에 이에 관한 증거결정을 함에 있어서는 제출한 자로 하여금 그 서류 또는 물건을 상대방에게 제시하게 하여 상대방으로 하여금 그 서류 또는 물건의 증거능력 유무에 관한 의견을 진술하게 하여야 한다. 다만, 법 제318조의3의 규정에 의하여 동의가 있는 것으로 간주되는 경우에는 그러하지 아니하다.', 250);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (339, '③ 삭제 <2021.12.31>', 250);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (340, '④ 법원은 증거신청을 기각ㆍ각하하거나, 증거신청에 대한 결정을 보류하는 경우, 증거신청인으로부터 당해 증거서류 또는 증거물을 제출받아서는 아니 된다. <신설 2007.10.29>', 250);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (341, '① 검사는 피고인이 아닌 피의자의 진술을 영상녹화한 사건에서 피고인이 아닌 피의자가 그 조서에 기재된 내용이 자신이 진술한 내용과 동일하게 기재되어 있음을 인정하지 아니하는 경우 그 부분의 성립의 진정을 증명하기 위하여 영상녹화물의 조사를 신청할 수 있다. <개정 2020.12.28>', 251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (342, '② 삭제 <2020.12.28>', 251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (343, '③ 제1항의 영상녹화물은 조사가 개시된 시점부터 조사가 종료되어 피의자가 조서에 기명날인 또는 서명을 마치는 시점까지 전과정이 영상녹화된 것으로, 다음 각 호의 내용을 포함하는 것이어야 한다.', 251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (344, '④ 제1항의 영상녹화물은 조사가 행해지는 동안 조사실 전체를 확인할 수 있도록 녹화된 것으로 진술자의 얼굴을 식별할 수 있는 것이어야 한다.', 251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (345, '⑤ 제1항의 영상녹화물의 재생 화면에는 녹화 당시의 날짜와 시간이 실시간으로 표시되어야 한다.', 251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (346, '⑥ 삭제 <2020.12.28>', 251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (347, '① 검사는 피의자가 아닌 자가 공판준비 또는 공판기일에서 조서가 자신이 검사 또는 사법경찰관 앞에서 진술한 내용과 동일하게 기재되어 있음을 인정하지 아니하는 경우 그 부분의 성립의 진정을 증명하기 위하여 영상녹화물의 조사를 신청할 수 있다.', 252);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (348, '② 검사는 제1항에 따라 영상녹화물의 조사를 신청하는 때에는 피의자가 아닌 자가 영상녹화에 동의하였다는 취지로 기재하고 기명날인 또는 서명한 서면을 첨부하여야 한다.', 252);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (349, '③ 제134조의2제3항제1호부터 제3호, 제5호, 제6호, 제4항, 제5항은 검사가 피의자가 아닌 자에 대한 영상녹화물의 조사를 신청하는 경우에 준용한다.', 252);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (350, '① 법원은 검사가 영상녹화물의 조사를 신청한 경우 이에 관한 결정을 함에 있어 원진술자와 함께 피고인 또는 변호인으로 하여금 그 영상녹화물이 적법한 절차와 방식에 따라 작성되어 봉인된 것인지 여부에 관한 의견을 진술하게 하여야 한다. <개정 2020.12.28>', 253);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (351, '② 삭제 <2020.12.28>', 253);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (352, '③ 법원은 공판준비 또는 공판기일에서 봉인을 해체하고 영상녹화물의 전부 또는 일부를 재생하는 방법으로 조사하여야 한다. 이 때 영상녹화물은 그 재생과 조사에 필요한 전자적 설비를 갖춘 법정 외의 장소에서 이를 재생할 수 있다.', 253);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (353, '④ 재판장은 조사를 마친 후 지체 없이 법원사무관 등으로 하여금 다시 원본을 봉인하도록 하고, 원진술자와 함께 피고인 또는 변호인에게 기명날인 또는 서명하도록 하여 검사에게 반환한다. 다만, 피고인의 출석 없이 개정하는 사건에서 변호인이 없는 때에는 피고인 또는 변호인의 기명날인 또는 서명을 요하지 아니한다.', 253);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (354, '① 법 제318조의2제2항에 따른 영상녹화물의 재생은 검사의 신청이 있는 경우에 한하고, 기억의 환기가 필요한 피고인 또는 피고인 아닌 자에게만 이를 재생하여 시청하게 하여야 한다.', 254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (355, '② 제134조의2제3항부터 제5항까지와 제134조의4는 검사가 법 제318조의2제2항에 의하여 영상녹화물의 재생을 신청하는 경우에 준용한다.', 254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (356, '① 법 제292조제3항에 따른 증거서류 내용의 고지는 그 요지를 고지하는 방법으로 한다.', 255);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (357, '② 재판장은 필요하다고 인정하는 때에는 법 제292조제1항ㆍ제2항ㆍ제4항의 낭독에 갈음하여 그 요지를 진술하게 할 수 있다.', 255);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (358, '① 컴퓨터용디스크 그 밖에 이와 비슷한 정보저장매체(다음부터 이 조문 안에서 이 모두를 "컴퓨터디스크 등"이라 한다)에 기억된 문자정보를 증거자료로 하는 경우에는 읽을 수 있도록 출력하여 인증한 등본을 낼 수 있다.', 256);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (359, '② 컴퓨터디스크 등에 기억된 문자정보를 증거로 하는 경우에 증거조사를 신청한 당사자는 법원이 명하거나 상대방이 요구한 때에는 컴퓨터디스크 등에 입력한 사람과 입력한 일시, 출력한 사람과 출력한 일시를 밝혀야 한다.', 256);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (360, '③ 컴퓨터디스크 등에 기억된 정보가 도면ㆍ사진 등에 관한 것인 때에는 제1항과 제2항의 규정을 준용한다.', 256);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (361, '① 녹음ㆍ녹화테이프, 컴퓨터용디스크, 그 밖에 이와 비슷한 방법으로 음성이나 영상을 녹음 또는 녹화(다음부터 이 조문 안에서 "녹음ㆍ녹화 등"이라 한다)하여 재생할 수 있는 매체(다음부터 이 조문 안에서 "녹음ㆍ녹화매체 등"이라 한다)에 대한 증거조사를 신청하는 때에는 음성이나 영상이 녹음ㆍ녹화 등이 된 사람, 녹음ㆍ녹화 등을 한 사람 및 녹음ㆍ녹화 등을 한 일시 ㆍ 장소를 밝혀야 한다.', 257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (362, '② 녹음ㆍ녹화매체 등에 대한 증거조사를 신청한 당사자는 법원이 명하거나 상대방이 요구한 때에는 녹음ㆍ녹음매체 등의 녹취서, 그 밖에 그 내용을 설명하는 서면을 제출하여야 한다.', 257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (363, '③ 녹음ㆍ녹화매체 등에 대한 증거조사는 녹음ㆍ녹화매체 등을 재생하여 청취 또는 시청하는 방법으로 한다.', 257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (364, '④ 제3항의 경우 재판장은 검사, 피고인 또는 변호인의 의견을 들어 녹음ㆍ녹화매체 등의 중요 부분만을 재생하여 청취 또는 시청할 수 있다. <신설 2025.2.28>', 257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (365, '① 법원은 필요하다고 인정하는 경우에는 직권으로 또는 법 제294조의2제1항에 정한 피해자등(이하 이 조 및 제134조의11에서 ‘피해자등’이라 한다)의 신청에 따라 피해자등을 공판기일에 출석하게 하여 법 제294조의2제2항에 정한 사항으로서 범죄사실의 인정에 해당하지 않는 사항에 관하여 증인신문에 의하지 아니하고 의견을 진술하게 할 수 있다.', 259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (366, '② 재판장은 재판의 진행상황 등을 고려하여 피해자등의 의견진술에 관한 사항과 그 시간을 미리 정할 수 있다.', 259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (367, '③ 재판장은 피해자등의 의견진술에 대하여 그 취지를 명확하게 하기 위하여 피해자등에게 질문할 수 있고, 설명을 촉구할 수 있다.', 259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (368, '④ 합의부원은 재판장에게 알리고 제3항의 행위를 할 수 있다.', 259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (369, '⑤ 검사, 피고인 또는 변호인은 피해자등이 의견을 진술한 후 그 취지를 명확하게 하기 위하여 재판장의 허가를 받아 피해자등에게 질문할 수 있다.', 259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (370, '⑥ 재판장은 다음 각 호의 어느 하나에 해당하는 경우에는 피해자등의 의견진술이나 검사, 피고인 또는 변호인의 피해자등에 대한 질문을 제한할 수 있다.', 259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (371, '⑦ 제1항의 경우 법 제163조의2제1항, 제3항 및 제84조의3을 준용한다.', 259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (372, '① 재판장은 재판의 진행상황, 그 밖의 사정을 고려하여 피해자등에게 제134조의10제1항의 의견진술에 갈음하여 의견을 기재한 서면을 제출하게 할 수 있다.', 260);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (373, '② 피해자등의 의견진술에 갈음하는 서면이 법원에 제출된 때에는 검사 및 피고인 또는 변호인에게 그 취지를 통지하여야 한다.', 260);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (374, '③ 제1항에 따라 서면이 제출된 경우 재판장은 공판기일에서 의견진술에 갈음하는 서면의 취지를 명확하게 하여야 한다. 이 경우 재판장은 상당하다고 인정하는 때에는 그 서면을 낭독하거나 요지를 고지할 수 있다.', 260);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (375, '④ 제2항의 통지는 서면, 전화, 전자우편, 모사전송, 휴대전화 문자전송 그 밖에 적당한 방법으로 할 수 있다.', 260);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (376, '① 법원이 법 제294조의5제1항 본문에 따라 피해자 또는 그 법정대리인(피해자가 사망한 경우에는 배우자ㆍ직계친족ㆍ형제자매를 포함한다. 이하 이 조에서 ‘피해자등’이라 한다)의 의견을 듣는 경우에는 다음 각 호의 어느 하나에 해당하는 방법으로 한다.', 262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (377, '② 법 제294조의5제1항 단서에서 "대법원규칙으로 정하는 특별한 사정이 있는 경우"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다.', 262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (378, '③ 법 제294조의5에 따라 피해자등이 제출한 의견은 범죄사실의 인정을 위한 증거로 할 수 없다.', 262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (379, '① 법 제294조의4제1항의 신청은 다음 사항을 기재한 서면으로 하여야 한다.', 263);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (380, '② 제1항의 신청을 할 때에는 법 제294조의4제1항에서 정하는 신청인의 자격과 제1항제4호의 사유를 소명하여야 한다.', 263);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (381, '③ 재판장이 열람ㆍ등사를 허가하지 않는 경우 법원사무관등은 지체 없이 서면, 전화, 전자우편, 모사전송, 휴대전화 문자전송 등의 방법으로 신청인에게 그 이유를 통지하여야 한다.', 263);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (382, '④ 재판장이 법 제294조의4제4항에 따라 등사한 소송기록의 사용목적을 제한하거나 조건을 붙이는 경우 제1항의 신청서에 그 이유를 기재하여야 하고, 법원사무관등은 지체 없이 그 이유가 기재된 신청서 사본을 신청인에게 교부하여야 한다.', 263);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (383, '①시기에 늦은 이의신청, 소송지연만을 목적으로 하는 것임이 명백한 이의신청은 결정으로 이를 기각하여야 한다. 다만, 시기에 늦은 이의신청이 중요한 사항을 대상으로 하고 있는 경우에는 시기에 늦은 것만을 이유로 하여 기각하여서는 아니된다.', 269);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (384, '②이의신청이 이유없다고 인정되는 경우에는 결정으로 이를 기각하여야 한다.', 269);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (385, '③이의신청이 이유있다고 인정되는 경우에는 결정으로 이의신청의 대상이 된 행위, 처분 또는 결정을 중지, 철회, 취소, 변경하는 등 그 이의신청에 상응하는 조치를 취하여야 한다.', 269);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (386, '④증거조사를 마친 증거가 증거능력이 없음을 이유로 한 이의신청을 이유있다고 인정할 경우에는 그 증거의 전부 또는 일부를 배제한다는 취지의 결정을 하여야 한다.', 269);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (387, '①재판장은 소송관계를 명료하게 하기 위하여 검사, 피고인 또는 변호인에게 사실상과 법률상의 사항에 관하여 석명을 구하거나 입증을 촉구할 수 있다.', 273);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (388, '②합의부원은 재판장에게 고하고 제1항의 조치를 할 수 있다.', 273);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (389, '③검사, 피고인 또는 변호인은 재판장에 대하여 제1항의 석명을 위한 발문을 요구할 수 있다.', 273);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (390, '①검사가 법 제298조제1항에 따라 공소장에 기재한 공소사실 또는 적용법조의 추가, 철회 또는 변경(이하 "공소장의 변경"이라 한다)을 하고자 하는 때에는 그 취지를 기재한 공소장변경허가신청서를 법원에 제출하여야 한다. <개정 2007.10.29>', 274);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (391, '②제1항의 공소장변경허가신청서에는 피고인의 수에 상응한 부본을 첨부하여야 한다.', 274);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (392, '③법원은 제2항의 부본을 피고인 또는 변호인에게 즉시 송달하여야 한다.', 274);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (393, '④ 공소장의 변경이 허가된 때에는 검사는 공판기일에 제1항의 공소장변경허가신청서에 의하여 변경된 공소사실ㆍ죄명 및 적용법조를 낭독하여야 한다. 다만, 재판장은 필요하다고 인정하는 때에는 공소장변경의 요지를 진술하게 할 수 있다. <개정 2007.10.29>', 274);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (394, '⑤법원은 제1항의 규정에도 불구하고 피고인이 재정하는 공판정에서는 피고인에게 이익이 되거나 피고인이 동의하는 경우 구술에 의한 공소장변경을 허가할 수 있다. <신설 1996.12.3>', 274);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (395, '① 법 제301조, 법 제301조의2 또는 제143조에 따른 공판절차의 갱신은 다음 각 호의 규정에 의한다. <개정 2025.2.28>', 276);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (396, '② 재판장은 제1항제4호 및 제5호에 규정한 서류 또는 물건에 관하여 증거조사를 함에 있어서 검사, 피고인 및 변호인의 동의가 있는 때에는 그 전부 또는 일부에 관하여 법 제292조ㆍ제292조의2ㆍ제292조의3에 규정한 방법에 갈음하여 상당하다고 인정하는 방법으로 이를 할 수 있다.', 276);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (397, '③ 제1항제4호 단서에 따라 녹취서를 조사할 때 검사, 피고인 또는 변호인이 녹취서의 기재가 녹음물의 내용과 불일치한다고 이의하거나 법원이 필요하다고 인정하는 경우, 법원은 녹음물의 전부 또는 일부를 청취하면서 녹취서 기재내용의 오류 여부나 녹음물과의 일치 여부를 확인할 수 있다. <신설 2025.2.28>', 276);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (398, '① 재판장은 판결을 선고할 때 피고인에게 이유의 요지를 말이나 판결서 등본 또는 판결서 초본의 교부 등 적절한 방법으로 설명한다.', 279);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (399, '② 재판장은 판결을 선고하면서 피고인에게 적절한 훈계를 할 수 있다.', 279);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (400, '①재판장은 판결을 선고함에 있어서 피고인에게 형법 제59조의2, 형법 제62조의2의 규정에 의하여 보호관찰, 사회봉사 또는 수강(이하 "保護觀察등"이라고 한다)을 명하는 경우에는 그 취지 및 필요하다고 인정하는 사항이 적힌 서면을 교부하여야 한다. <개정 2016.2.19>', 280);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (401, '②법원은 판결을 선고함에 있어 형법 제62조의2의 규정에 의하여 사회봉사 또는 수강을 명하는 경우에는 피고인이 이행하여야 할 총 사회봉사시간 또는 수강시간을 정하여야 한다. 이 경우 필요하다고 인정하는 때에는 사회봉사 또는 수강할 강의의 종류나 방법 및 그 시설 등을 지정할 수 있다.', 280);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (402, '③형법 제62조의2제2항의 사회봉사명령은 500시간, 수강명령은 200시간을 각 초과할 수 없으며, 보호관찰관이 그 명령을 집행함에는 본인의 정상적인 생활을 방해하지 아니하도록 한다. <개정 1998.6.20>', 280);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (403, '④형법 제62조의2제1항의 보호관찰ㆍ사회봉사ㆍ수강명령은 둘 이상 병과할 수 있다. <신설 1998.6.20>', 280);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (404, '⑤사회봉사ㆍ수강명령이 보호관찰과 병과하여 부과된 때에는 보호관찰기간내에 이를 집행하여야 한다. <신설 1998.6.20>', 280);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (405, '①보호관찰등을 조건으로 한 판결이 확정된 때에 당해 사건이 확정된 법원의 법원사무관등은 3일 이내에 판결문등본을 대상자의 주거지를 관할하는 보호관찰소의 장에게 송부하여야 한다. <개정 1998.6.20>', 281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (406, '②제1항의 서면에는 법원의 의견 기타 보호관찰등의 자료가 될 만한 사항을 기재한 서면을 첨부할 수 있다.', 281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (407, '① 법원은 피고인에 대하여 판결을 선고한 때에는 선고일부터 7일 이내에 피고인에게 그 판결서 등본을 송달하여야 한다. 다만, 피고인이 동의하는 경우에는 그 판결서 초본을 송달할 수 있다.', 283);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (408, '② 제1항에 불구하고 불구속 피고인과 법 제331조의 규정에 의하여 구속영장의 효력이 상실된 구속 피고인에 대하여는 피고인이 송달을 신청하는 경우에 한하여 판결서 등본 또는 판결서 초본을 송달한다.', 283);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (409, '①형법 제64조제2항의 규정에 의한 집행유예취소청구를 한 때에는 검사는 청구와 동시에 청구서의 부본을 법원에 제출하여야 한다.', 286);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (410, '②법원은 제1항의 부본을 받은 때에는 지체없이 집행유예의 선고를 받은 자에게 송달하여야 한다.', 286);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (411, '①교도소장, 구치소장 또는 그 직무를 대리하는 자가 법 제344조제1항의 규정에 의하여 상소장을 제출받은 때에는 그 제출받은 연월일을 상소장에 부기하여 즉시 이를 원심법원에 송부하여야 한다.', 290);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (412, '② 제1항의 규정은 교도소장, 구치소장 또는 그 직무를 대리하는 자가 법 제355조에 따라 정식재판청구나 상소권회복청구 또는 상소의 포기나 취하의 서면 및 상소이유서를 제출받은 때 및 법 제487조부터 법 제489조까지의 신청과 그 취하에 이를 준용한다. <개정 2007.10.29>', 290);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (413, '①법 제350조에 규정한 피고인이 상소의 포기 또는 취하를 할 때에는 법정대리인이 이에 동의하는 취지의 서면을 제출하여야 한다.', 291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (414, '②피고인의 법정대리인 또는 법 제341조에 규정한 자가 상소의 취하를 할 때에는 피고인이 이에 동의하는 취지의 서면을 제출하여야 한다.', 291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (415, '①상소의 포기 또는 취하가 부존재 또는 무효임을 주장하는 자는 그 포기 또는 취하당시 소송기록이 있었던 법원에 절차속행의 신청을 할 수 있다.', 292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (416, '②제1항의 신청을 받은 법원은 신청이 이유있다고 인정하는 때에는 신청을 인용하는 결정을 하고 절차를 속행하여야 하며, 신청이 이유없다고 인정하는 때에는 결정으로 신청을 기각하여야 한다.', 292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (417, '③제2항 후단의 신청기각결정에 대하여는 즉시 항고할 수 있다.', 292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (418, '①기록의 송부를 받은 항소법원은 법 제33조제1항제1호부터 제6호까지의 필요적 변호사건에 있어서 변호인이 없는 경우에는 지체없이 변호인을 선정한 후 그 변호인에게 소송기록접수통지를 하여야 한다. 법 제33조제3항에 의하여 국선변호인을 선정한 경우에도 그러하다. <개정 2006.3.23, 2006.8.17, 2016.6.27>', 295);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (419, '②항소법원은 항소이유서 제출기간이 도과하기 전에 피고인으로부터 법 제33조제2항의 규정에 따른 국선변호인 선정청구가 있는 경우에는 지체없이 그에 관한 결정을 하여야 하고, 이 때 변호인을 선정한 경우에는 그 변호인에게 소송기록접수통지를 하여야 한다. <신설 2006.3.23, 2006.8.17>', 295);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (420, '③제1항, 제2항의 규정에 따라 국선변호인 선정결정을 한 후 항소이유서 제출기간 내에 피고인이 책임질 수 없는 사유로 그 선정결정을 취소하고 새로운 국선변호인을 선정한 경우에도 그 변호인에게 소송기록접수통지를 하여야 한다. <신설 2006.3.23>', 295);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (421, '④항소법원이 제2항의 국선변호인 선정청구를 기각한 경우에는 피고인이 국선변호인 선정청구를 한 날로부터 선정청구기각결정등본을 송달받은 날까지의 기간을 법 제361조의3제1항이 정한 항소이유서 제출기간에 산입하지 아니한다. 다만, 피고인이 최초의 국선변호인 선정청구기각결정을 받은 이후 같은 법원에 다시 선정청구를 한 경우에는 그 국선변호인 선정청구일로부터 선정청구기각결정등본 송달일까지의 기간에 대해서는 그러하지 아니하다. <신설 2006.3.23>', 295);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (422, '① 항소인은 그 항소이유를 구체적으로 진술하여야 한다.', 296);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (423, '② 상대방은 항소인의 항소이유 진술이 끝난 뒤에 항소이유에 대한 답변을 구체적으로 진술하여야 한다.', 296);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (424, '③ 피고인 및 변호인은 이익이 되는 사실 등을 진술할 수 있다.', 296);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (425, '① 재판장은 증거조사절차에 들어가기에 앞서 제1심의 증거관계와 증거조사결과의 요지를 고지하여야 한다.', 298);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (426, '② 항소심 법원은 다음 각호의 어느 하나에 해당하는 경우에 한하여 증인을 신문할 수 있다.', 298);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (427, '① 검사 또는 변호인은 항소심의 증거조사가 종료한 후 항소이유의 당부를 판단함에 필요한 사항에 한하여 피고인을 신문할 수 있다.', 299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (428, '② 재판장은 제1항에 따라 피고인 신문을 실시하는 경우에도 제1심의 피고인 신문과 중복되거나 항소이유의 당부를 판단하는 데 필요 없다고 인정하는 때에는 그 신문의 전부 또는 일부를 제한할 수 있다.', 299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (429, '③ 재판장은 필요하다고 인정하는 때에는 피고인을 신문할 수 있다.', 299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (430, '① 항소심의 증거조사와 피고인 신문절차가 종료한 때에는 검사는 원심 판결의 당부와 항소이유에 대한 의견을 구체적으로 진술하여야 한다.', 300);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (431, '② 재판장은 검사의 의견을 들은 후 피고인과 변호인에게도 제1항의 의견을 진술할 기회를 주어야 한다.', 300);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (432, null, 301);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (433, '①법원사무관 등은 피고인에게 공판기일통지서를 송달하여야 한다. <개정 1996.12.3>', 305);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (434, '②상고심에서는 공판기일을 지정하는 경우에도 피고인의 이감을 요하지 아니한다. <개정 1996.12.3>', 305);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (435, '③상고한 피고인에 대하여 이감이 있는 경우에는 검사는 지체없이 이를 대법원에 통지하여야 한다. <신설 1996.12.3>', 305);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (436, '① 국가기관과 지방자치단체는 공익과 관련된 사항에 관하여 대법원에 재판에 관한 의견서를 제출할 수 있고, 대법원은 이들에게 의견서를 제출하게 할 수 있다.', 306);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (437, '② 대법원은 소송관계를 분명하게 하기 위하여 공공단체 등 그 밖의 참고인에게 의견서를 제출하게 할 수 있다.', 306);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (438, '①재심청구의 취하는 서면으로 하여야 한다. 다만, 공판정에서는 구술로 할 수 있다.', 312);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (439, '②구술로 재심청구의 취하를 한 경우에는 그 사유를 조서에 기재하여야 한다.', 312);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (440, '①항소기각의 확정판결과 그 판결에 의하여 확정된 제1심판결에 대하여 각각 재심의 청구가 있는 경우에 항소법원은 결정으로 제1심법원의 소송절차가 종료할 때까지 소송절차를 정지하여야 한다.', 314);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (441, '②상고기각의 판결과 그 판결에 의하여 확정된 제1심 또는 제2심의 판결에 대하여 각각 재심의 청구가 있는 경우에 상고법원은 결정으로 제1심법원 또는 항소법원의 소송절차가 종료할 때까지 소송절차를 정지하여야 한다.', 314);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (442, '①법원사무관등은 약식명령의 청구가 있는 사건을 법 제450조의 규정에 따라 공판절차에 의하여 심판하기로 한 때에는 즉시 그 취지를 검사에게 통지하여야 한다. <개정 1996.12.3>', 317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (443, '②제1항의 통지를 받은 검사는 5일이내에 피고인수에 상응한 공소장 부본을 법원에 제출하여야 한다. <개정 1996.12.3>', 317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (444, '③법원은 제2항의 공소장 부본에 관하여 법 제266조에 규정한 조치를 취하여야 한다.', 317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (445, '①법 제487조 내지 법 제489조의 규정에 의한 신청 및 그 취하는 서면으로 하여야 한다.', 319);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (446, '②제152조의 규정은 제1항의 신청과 그 취하에 이를 준용한다.', 319);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (447, '①법원 또는 판사에 대한 신청 기타 진술은 법 및 이 규칙에 다른 규정이 없으면 서면 또는 구술로 할 수 있다.', 321);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (448, '②구술에 의하여 신청 기타의 진술을 할 때에는 법원사무관등의 면전에서 하여야 한다.', 321);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (449, '③제2항의 경우에 법원사무관등은 조서를 작성하고 기명날인하여야 한다. <개정 1996.12.3>', 321);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (450, '① 소송관계인은 기일 외에서 구술, 전화, 휴대전화 문자전송, 그 밖에 이와 유사한 방법으로 신체구속, 공소사실 또는 양형에 관하여 법률상ㆍ사실상 주장을 하는 등 법령이나 재판장의 지휘에 어긋나는 절차와 방식으로 소송행위를 하여서는 아니 된다.', 323);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (451, '② 재판장은 제1항을 어긴 소송관계인에게 주의를 촉구하고 기일에서 그 위반사실을 알릴 수 있다.', 323);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (452, '①법 제4조제1항에서 규정하고 있는 "기타 이에 준하는 비용"의 항목은 식비로 한다. <개정 2003.9.13>', 328);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (453, '②법 제4조제2항, 제5조제2항의 규정에 의한 증인등의 국내 여비 및 숙박료는 법원공무원여비규칙 제10조제1항, 제11조제1항, 제12조제1항, 제13조제1항, 제16조제1항의 별표 2 국내여비지급표에 정한 제2호 해당자 지급액으로 하며, 철도운임의 경우 위 규칙 제10조제1항 단서의 규정을 준용한다. <개정 2009.1.9>', 328);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (454, '①법 제6조의 규정에 의한 증인등의 일당ㆍ여비 및 숙박료는 증인등이 국외로부터 국내로, 국내로부터 국외로 여행하거나 또는 국내로 입국하기 위하여 국외에서 여행(이하 이를 합하여 "국외여행"이라 한다)하는 경우에 이를 지급한다.', 329);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (455, '②증인등이 국외여행하는 경우의 운임은 다음 각호의 구분에 의하되, 통행세를 가산한다.', 329);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (456, '③증인등이 국외여행하는 경우의 운임을 제외한 여비 및 숙박료는 법원공무원여비규칙 제16조제1항의 별표 4 "국외여비정액표"에 정한 별표 1 여비지급구분표의 제2호 나목 해당자 소정액으로 한다. <개정 2009.1.9>', 329);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (457, '①법 제8조제1항의 규정에 의한 국선변호인의 일당은 매년 예산의 범위안에서 대법관회의에서 정한다.', 330);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (458, '②국선변호인의 국내여비 및 숙박료에 관하여는 제3조제2항의 규정을 준용한다. <개정 2009.1.9>', 330);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (459, '③국선변호인이 국외여행하는 경우의 여비 및 숙박료에 관하여는 제4조제2항, 제3항의 규정을 준용하되, 이 경우 "중간 등급 이하의 운임"은 "최상등급의 운임"으로, 별표 1 여비지급구분표의 제2호 나목 해당자는 별표 1 여비지급구분표의 제1호 라목 해당자로 본다. <개정 2009.1.9>', 330);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (460, '①법 제8조제2항의 규정에 의한 국선변호인의 보수는 매년 예산의 범위안에서 대법관회의에서 정하며 그 보수는 심급별로 지급하되, 체포 또는 구속적부심에 있어서는 심급에 관계없이 별도로 지급한다.', 331);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (461, '②제1항의 보수는 사안의 난이, 국선변호인이 수행한 직무의 내용, 사건처리에 소요된 시간 등을 참작하여 예산의 범위안에서 당해재판장이 이를 증액할 수 있다. <개정 2008.6.5>', 331);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (462, '③공익법무관, 사법연수생, 변호사자격이 있는 장교, 군법무관시보인 국선변호인에 대하여는 보수를 지급하지 아니한다. 다만, 피고인 또는 피의자의 접견을 위한 비용 기타 재판장이 인정하는 실비를 변상할 수 있다. <개정 2022.6.30>', 331);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (463, '① 추진단은 단장, 형사전자소송심의관, 형사전자소송담당관 및 단원으로 구성한다.', 333);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (464, '② 단장과 형사전자소송심의관은 판사로 보한다.', 333);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (465, '③ 형사전자소송담당관은 4급 이상 법원직원으로 보한다.', 333);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (466, null, 334);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (467, '① 단장은 추진단 업무를 수행하기 위하여 필요한 때에는 관계 기관, 단체 등에 대하여 자료 또는 의견의 제출 및 지원 활동 등 필요한 협조를 요청할 수 있다.', 335);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (468, '② 단장은 추진단 업무를 수행하기 위하여 필요한 때에는 법원행정처장의 허가를 받아, 법원행정처 내 각 실ㆍ국과 관계 기관에 형사전자소송 사업의 수행을 위하여 필요한 인원의 파견을 요청할 수 있다.', 335);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (469, '① 단장은 형사전자소송 시스템 구축 사업의 수행을 위하여 필요한 경우에는 법관, 법원직원 또는 외부전문가에게 협조를 구하거나 조사연구를 위탁할 수 있다.', 336);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (470, '② 제1항의 경우 추진단은 예산의 범위에서 그 수당 및 여비, 그 밖에 필요한 경비를 지급할 수 있다. 다만, 법관과 법원직원이 그 소관 업무와 관련하여 협조에 응할 경우에는 여비 등 필요한 경비만을 지급할 수 있다.', 336);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (471, '① 검사는 다음 각 호의 조치를 하기 위해 아동학대전담공무원, 아동보호전문기관의 장, 법 제36조제5항 본문에 따른 수탁기관(이하 "수탁기관"이라 한다)의 장, 사법경찰관, 보호관찰관, 의사, 변호사 및 「아동복지법」 제13조에 따른 아동복지전담공무원 등을 구성원으로 하는 사건관리회의(이하 이 조에서 "회의"라 한다)를 열어 의견 청취 등을 할 수 있다. <개정 2025.6.20>', 341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (472, '② 회의의 구성원은 회의에 필요한 조사 결과, 자료 등을 제출하거나 보고할 수 있다. <개정 2025.6.20>', 341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (473, '③ 검사는 회의의 운영을 위하여 필요한 경우에는 회의의 구성원에게 조사 결과, 자료 등의 제출 또는 보고를 요구할 수 있다. <개정 2025.6.20>', 341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (474, '① 아동학대전담공무원이나 사법경찰관리는 피해아동등이 법 제12조에 따른 응급조치 또는 법 제47조에 따른 피해아동보호명령 등에 따라 보호시설, 의료기관, 아동복지시설 등의 시설이나 기관에 인도되거나 위탁된 경우 또는 법 제12조제1항제5호에 따른 연고자 등에게 인도된 경우에는 주기적으로 피해아동등을 방문하여 보호자와의 의사소통을 중개하거나 피해아동등의 상황 등에 관한 의견을 청취할 수 있다. 다만, 보호자와의 의사소통 중개는 피해아동등이 원하는 경우에만 할 수 있다. <개정 2020.9.29, 2025.6.20>', 342);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (475, '② 아동학대전담공무원이나 사법경찰관리는 제1항에 따라 의사소통을 중개하거나 의견을 청취할 때 피해아동등이 편안한 상태에서 말할 수 있는 환경을 조성하도록 노력해야 한다. <개정 2020.9.29>', 342);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (476, '③ 시ㆍ도지사, 시장ㆍ군수ㆍ구청장, 가정보호사건조사관, 법원공무원, 사법경찰관리, 보호관찰관, 아동보호전문기관의 장이나 수탁기관의 장은 법 제25조제4항에 따른 자료 제출, 법 제39조에 따른 보고서ㆍ의견서 제출 또는 법 제53조제1항에 따른 이행실태 조사를 위하여 필요한 경우에는 보호시설, 의료기관 및 아동복지시설 등의 장에게 피해아동등 또는 아동학대행위자에 관한 자료의 제출을 요청할 수 있다. <개정 2020.9.29>', 342);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (477, '① 사법경찰관리 또는 아동학대전담공무원은 법 제12조제1항제5호에 따라 피해아동등을 제5조의2에 따른 연고자 등(이하 "연고자등"이라 한다)에게 인도하려는 경우에는 연고자등에게 인도하는 것이 적합한지를 판단하기 위해 해당 연고자등에게 다음 각 호의 사항에 대해 질문할 수 있다.', 344);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (478, '② 사법경찰관리 또는 아동학대전담공무원은 피해아동등을 연고자등에게 인도하는 경우에는 다음 각 호의 사항을 미리 해당 연고자등에게 알려주어야 한다.', 344);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (479, '③ 사법경찰관리 또는 아동학대전담공무원은 법 제12조제1항제5호에 따라 피해아동등을 연고자등에게 인도하기 전에 해당 연고자등으로부터 법무부령으로 정하는 범죄경력 조회 동의서를 제출받아 다음 각 호의 구분에 따라 해당 연고자등에게 별표 1에 규정된 범죄경력이 있는지를 확인해야 한다. 이 경우 제2호에 따른 범죄경력 조회 요청을 받은 경찰관서의 장은 특별한 사유가 없으면 이에 따라야 한다.', 344);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (480, '④ 사법경찰관리 또는 아동학대전담공무원은 제3항에 따른 범죄경력 조회 결과 연고자등에게 별표 1에 규정된 범죄경력이 확인된 경우에는 해당 연고자등에게 피해아동동을 인도해서는 안 된다.', 344);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (481, '⑤ 법 제12조제1항제5호에 따라 피해아동등을 인도받은 연고자등은 응급조치 기간 동안 제5조에 따른 사법경찰관리 또는 아동학대전담공무원의 방문, 피해아동등의 상황 등에 관한 의견청취 등 피해아동등을 보호하기 위한 절차에 성실히 응해야 한다.', 344);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (482, null, 345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (483, '① 법무부장관 등 관계 행정기관의 장, 검사, 보호관찰소의 장, 교정시설의 장, 사법경찰관리, 보호관찰관, 시ㆍ도지사, 시장ㆍ군수ㆍ구청장, 아동학대전담공무원, 아동보호전문기관, 가정위탁지원센터, 아동복지시설의 장과 그 종사자, 수탁기관의 장과 그 직원은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호 및 제2호에 따른 유전정보와 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2020.9.29, 2021.5.18, 2025.6.20>', 346);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (484, '② 수사기관, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장, 아동학대전담공무원, 아동보호전문기관의 장과 그 종사자, 신고의무자는 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보 및 같은 법 시행령 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2020.9.29>', 346);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (485, '③ 법무부장관, 검사 또는 사법경찰관리는 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2021.5.18, 2025.6.20>', 346);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (486, '④ 다음 각 호의 자는 해당 업무와 그에 부수되는 업무를 수행하기 위하여 불가피한 경우 제3항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <개정 2021.5.18>', 346);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (487, '① 사법경찰관리는 수사를 할 때에는 합리적 이유 없이 피의자와 그 밖의 피해자ㆍ참고인 등(이하 "사건관계인"이라 한다)의 성별, 종교, 나이, 장애, 사회적 신분, 출신지역, 인종, 국적, 외모 등 신체조건, 병력(病歷), 혼인 여부, 정치적 의견 및 성적(性的) 지향 등을 이유로 차별해서는 안 된다.', 349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (488, '② 사법경찰관리는 「형사소송법」(이하 "법"이라 한다) 및 「검사와 사법경찰관의 상호협력과 일반적 수사준칙에 관한 규정」(이하 "수사준칙"이라 한다) 등 관계 법령을 준수하고 적법한 절차와 방식에 따라 수사해야 한다.', 349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (489, '① 사법경찰관리는 수사준칙 제6조에 따라 검사가 수사, 공소제기 및 공소유지와 관련하여 협력의 요청ㆍ요구ㆍ신청 등(이하 "협력요청등"이라 한다)을 하는 경우에는 상호 존중을 바탕으로 적극 협조해야 한다.', 350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (490, '② 사법경찰관리는 검사에게 협력요청등을 하는 경우에는 「형사사법절차 전자화 촉진법」 제2조제4호에 따른 형사사법정보시스템(이하 "형사사법정보시스템"이라 한다) 또는 서면으로 해야 한다.', 350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (491, '③ 천재지변 또는 긴급한 상황이 발생하거나 수사 현장에서 협력요청등을 하는 경우 등 제2항의 방식으로 협력요청등을 하는 것이 불가능하거나 현저히 곤란한 경우에는 구두(口頭)나 전화 등 간편한 방식으로 협력요청등을 할 수 있다.', 350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (492, '④ 사법경찰관리는 신속한 수사가 필요한 경우에는 적정한 기간을 정하여 검사에게 협력요청등을 할 수 있다.', 350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (493, '⑤ 사법경찰관리는 검사로부터 기간이 정해진 협력요청등을 받은 경우에는 그 기간 내에 이행하도록 노력해야 한다. 다만, 그 기간 내에 이행하기 곤란하거나 이행하지 못하는 경우에는 추가로 필요한 기간을 검사와 협의할 수 있다.', 350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (494, '① 사법경찰관리는 수사준칙 제7조에 따라 검사에게 중요사건에 대한 의견의 제시ㆍ교환을 요청하는 경우에는 별지 제1호서식의 의견요청서에 따른다.', 351);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (495, '② 사법경찰관리는 수사준칙 제7조에 따라 검사로부터 중요사건에 대한 의견의 제시ㆍ교환 요청을 받아 의견을 제시ㆍ교환하는 경우에는 별지 제2호서식의 의견서에 따른다.', 351);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (496, '① 사법경찰관리는 수사준칙 제55조제1항에 따라 소재불명(所在不明)인 피의자나 참고인을 발견하여 통보하는 경우에는 별지 제3호서식 또는 별지 제4호서식의 소재불명자 발견 통보서에 따른다.', 352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (497, '② 사법경찰관리는 수사준칙 제55조제2항에 따른 검사의 소재수사 요청에 협력하여 소재 확인을 한 경우에는 별지 제5호서식의 소재수사 결과 통보서를 작성하여 검사에게 통보해야 한다.', 352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (498, '① 사법경찰관리는 사법경찰관리가 수사 중인 사건에 대하여 검사로부터 「검찰사건사무규칙」에 따른 시찰조회를 요청받은 경우에는 협력해야 한다.', 353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (499, '② 사법경찰관리는 사법경찰관리가 수사 중인 사건이 아닌 사건에 대하여 검사로부터 시찰조회를 요청받은 경우에는 사건의 내용, 시찰조회 요청 사유 및 직무 수행 지장 여부 등을 종합적으로 검토하여 협력 여부를 결정할 수 있다.', 353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (500, '① 사법경찰관리는 수사준칙 제8조제1항에 따라 검사와의 협의를 요청하려는 경우에는 별지 제6호서식의 협의요청서에 요청 사항과 그 사유를 적어 검사에게 통보해야 한다.', 354);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (501, '② 사법경찰관리는 수사준칙 제8조제2항 각 호의 어느 하나에 해당하는 경우 제1항에 따른 해당 검사와의 협의에도 불구하고 이견이 해소되지 않으면 이를 즉시 소속된 해양경찰관서의 장(이하 "소속해양경찰관서장"이라 한다)에게 보고해야 한다. <개정 2024.6.19>', 354);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (502, '③ 제2항의 보고를 받은 소속해양경찰관서장은 수사준칙 제8조제2항에 따른 협의가 필요하다고 판단하면 별지 제7호서식의 협의요청서에 요청 사항과 그 사유를 적어 제2항에 따른 해당 검사가 소속된 검찰청의 장에게 통보해야 한다.', 354);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (503, '④ 사법경찰관리 또는 소속해양경찰관서장은 제1항 또는 제3항에 따라 검사 또는 검찰청의 장과 협의한 사항이 있으면 그 협의사항을 성실하게 이행하도록 노력해야 한다.', 354);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (504, '① 사법경찰관리는 수사에 필요한 경우에는 다른 사법경찰관리에게 피의자의 체포ㆍ출석요구ㆍ조사ㆍ호송, 압수ㆍ수색ㆍ검증, 참고인의 출석요구ㆍ조사 등 그 밖의 필요한 조치에 대한 협력을 요청할 수 있다. 이 경우 요청을 받은 사법경찰관리는 정당한 이유가 없으면 이에 적극 협조해야 한다.', 355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (505, '② 사법경찰관리는 수사에 필요한 경우에는 법 제245조의10에 따른 특별사법경찰관리와 긴밀히 협력해야 한다. 이 경우 협력의 구체적인 내용ㆍ범위 및 방법 등은 상호 협의하여 정한다.', 355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (506, '① 사건기록담당직원은 법 및 관련 법령에 따라 검사로부터 요구ㆍ요청 등을 받거나 사건 기록과 증거물을 반환받은 때에는 관계 서류 등이 법령에 따라 작성ㆍ편철됐는지 및 검사가 법령에 따라 필요한 행위를 했는지를 점검해야 한다.', 356);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (507, '② 사건기록담당직원은 제1항에 따른 점검 결과 관계 서류 등이 법 및 관련 법령에 따라 작성ㆍ편철되지 않거나, 검사가 법 및 관련 법령에 따라 필요한 행위를 하지 않은 경우에는 검사에게 그 보완을 요구하는 등 필요한 조치를 할 수 있다.', 356);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (508, '③ 사건기록담당직원은 제1항에 따라 요구ㆍ요청 등을 받거나 사건 기록과 증거물을 반환받아 이를 접수한 경우에는 접수대장에 접수일시, 검사 또는 검찰청 직원의 성명 등을 기재하고, 검사 또는 검찰청 직원이 제시하는 접수기록부 등에 접수일시와 접수자의 직급 및 서명을 기재한다.', 356);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (509, '① 사법경찰관은 다음 각 호의 어느 하나에 해당하는 날부터 7일 이내에 고소인ㆍ고발인ㆍ피해자 또는 그 법정대리인(피해자가 사망한 경우에는 그 배우자ㆍ직계친족ㆍ형제자매를 포함한다. 이하 "고소인등"이라 한다)에게 수사 진행상황을 통지해야 한다. 다만, 고소인등의 연락처를 모르거나 소재가 확인되지 않으면 연락처나 소재를 알게 된 날부터 7일 이내에 수사 진행상황을 통지해야 한다. <개정 2024.6.19>', 358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (510, '② 제1항제2호에 따른 수사 진행상황 통지 후에 고소인등의 요청이 있거나 그 밖에 사법경찰관이 필요하다고 인정하는 경우에도 수사 진행상황을 통지할 수 있다. <신설 2024.6.19>', 358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (511, '③ 제1항 및 제2항에 따른 통지는 서면, 전화, 팩스, 전자우편, 문자메시지 등 고소인등이 요청한 방법으로 할 수 있으며, 고소인등이 별도로 요청한 방법이 없는 경우에는 서면 또는 문자메시지로 통지한다. 이 경우 서면으로 하는 통지는 별지 제9호서식의 수사 진행상황 통지서에 따른다. <개정 2024.6.19>', 358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (512, '④ 사법경찰관은 수사 진행상황을 서면으로 통지한 경우에는 그 사본을, 그 밖의 방법으로 통지한 경우에는 그 취지를 적은 서면을 사건기록에 편철해야 한다. <개정 2024.6.19>', 358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (513, '⑤ 사법경찰관은 제1항 및 제2항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 수사 진행상황을 통지하지 않을 수 있다. 이 경우 그 사실을 수사보고서로 작성하여 사건기록에 편철해야 한다. <개정 2024.6.19>', 358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (514, '① 사법경찰관리는 법 제243조의2제1항에 따라 피의자 또는 그 변호인ㆍ법정대리인ㆍ배우자ㆍ직계친족ㆍ형제자매의 신청이 있는 경우 변호인의 참여로 인하여 신문이 방해되거나, 수사기밀이 누설되는 등 정당한 사유가 있는 경우를 제외하고는 피의자에 대한 신문에 변호인을 참여하게 해야 한다.', 359);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (515, '② 제1항의 변호인의 피의자신문 참여 신청을 받은 사법경찰관리는 신청인으로부터 변호인의 피의자신문 참여 전에 다음 각 호의 서면을 제출받아야 한다.', 359);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (516, '① 사법경찰관리는 변호인의 참여로 증거를 인멸ㆍ은닉ㆍ조작할 위험이 구체적으로 드러나거나, 신문 방해, 수사기밀 누설 등 수사에 현저한 지장을 초래하는 경우에는 피의자신문 중이라도 변호인의 참여를 제한할 수 있다. 이 경우 피의자와 변호인에게 변호인의 참여를 제한하는 처분에 대해 법 제417조에 따른 준항고를 제기할 수 있다는 사실을 고지해야 한다.', 360);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (517, '② 제1항에 따라 변호인 참여를 제한하는 경우 사법경찰관리는 피의자 또는 변호인에게 그 사유를 설명하고 의견을 진술할 기회와 다른 변호인을 참여시킬 기회를 주어야 한다.', 360);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (518, '③ 제1항에 따라 변호인의 참여를 제한한 후 그 사유가 해소된 때에는 변호인을 신문에 참여하게 해야 한다.', 360);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (519, null, 362);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (520, '① 해양경찰청장은 수사의 책임성과 완결성 확보를 위해 해양경찰관서에 해양경찰청장이 정하는 자격을 갖춘 심사관을 둘 수 있다.', 364);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (521, '② 제1항에 따른 심사관은 강제수사의 적법성ㆍ타당성 심사, 불송치 사건 및 수사 전반에 대한 점검 등의 업무를 수행한다.', 364);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (522, '① 사법경찰관은 법 제197조제1항에 따라 구체적인 사실에 근거를 둔 범죄의 혐의를 인식한 때에는 수사를 개시한다.', 365);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (523, '② 사법경찰관은 제1항에 따라 수사를 개시할 때에는 지체 없이 별지 제11호서식의 범죄인지서를 작성하여 사건기록에 편철해야 한다.', 365);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (524, '① 사법경찰관은 수사준칙 제16조제3항에 따른 입건 전에 범죄를 의심할 만한 정황이 있어 수사 개시 여부를 결정하기 위한 사실관계의 확인 등 필요한 조사(이하 "입건전조사"라고 한다)에 착수하기 위해서는 그 사건을 수리하고, 해당 사법경찰관이 소속된 해양경찰관서의 수사 부서의 장(이하 "소속수사부서장"이라 한다)의 지휘를 받아야 한다. <개정 2022.11.15, 2024.6.19>', 366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (525, '② 사법경찰관은 입건전조사한 사건을 다음 각 호의 구분에 따라 처리해야 한다. <개정 2022.11.15, 2024.6.19>', 366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (526, '③ 제1항 및 제2항에서 규정한 사항 외에 입건전조사 사건의 분류, 수리 및 조사의 진행과 기록관리 등에 필요한 세부사항은 해양경찰청장이 정한다. <신설 2024.6.19>', 366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (527, '① 사법경찰관은 수사준칙 제16조제4항에 따라 피혐의자(제19조제2항제2호에 따라 입건전조사 종결한 경우만 해당한다)와 진정인ㆍ탄원인ㆍ피해자 또는 그 법정대리인(피해자가 사망한 경우에는 그 배우자ㆍ직계친족ㆍ형제자매를 포함한다. 이하 "진정인등"이라 한다)에게 입건하지 않는 결정을 통지하는 경우에는 그 결정을 한 날부터 7일 이내에 통지해야 한다. 다만, 피혐의자나 진정인등의 연락처를 모르거나 소재가 확인되지 않으면 연락처나 소재를 알게 된 날부터 7일 이내에 통지해야 한다. <개정 2022.11.15>', 367);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (528, '② 제1항에 따른 통지는 서면, 전화, 팩스, 전자우편, 문자메시지 등 피혐의자 또는 진정인등이 요청한 방법으로 할 수 있으며, 별도로 요청한 방법이 없는 경우에는 서면 또는 문자메시지로 한다. 이 경우 서면으로 하는 통지는 별지 제12호서식 또는 별지 제13호서식의 불입건 결정 통지서에 따른다.', 367);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (529, '③ 사법경찰관은 서면으로 통지한 경우에는 그 사본을, 그 밖의 방법으로 통지한 경우에는 그 취지를 적은 서면을 사건기록에 편철해야 한다.', 367);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (530, '④ 사법경찰관은 제1항에도 불구하고 통지로 인해 보복범죄 또는 2차 피해 등이 우려되는 다음 각 호의 경우에는 불입건 결정을 통지하지 않을 수 있다. 이 경우 그 사실을 입건전조사 보고서로 작성하여 사건기록에 편철해야 한다. <개정 2022.11.15>', 367);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (531, '① 사법경찰관리는 진정인ㆍ탄원인 등 민원인이 제출하는 서류가 고소ㆍ고발의 요건을 갖추었다고 판단하는 경우 이를 고소ㆍ고발로 수리한다.', 368);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (532, '② 사법경찰관리는 고소장 또는 고발장의 명칭으로 제출된 서류가 다음 각 호의 어느 하나에 해당하는 경우에는 이를 진정(陳情)으로 처리할 수 있다. <개정 2024.6.19>', 368);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (533, '① 사법경찰관리는 구술로 제출된 고소ㆍ고발을 수리한 경우에는 진술조서를 작성해야 한다.', 369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (534, '② 사법경찰관리는 서면으로 제출된 고소ㆍ고발을 수리했으나 추가 진술이 필요하다고 판단하는 경우 고소인ㆍ고발인으로부터 보충 서면을 제출받거나 추가로 진술을 들어야 한다.', 369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (535, '③ 자수하는 경우 진술조서의 작성 및 추가 진술에 관하여는 제1항 및 제2항을 준용한다.', 369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (536, '① 사법경찰관리는 법 제236조에 따라 대리인으로부터 고소를 수리하는 경우에는 고소인 본인의 위임장을 제출받아야 한다.', 370);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (537, '② 사법경찰관리는 법 제225조부터 제228조까지의 규정에 따른 고소권자로부터 고소를 수리하는 경우에는 그 자격을 증명하는 서면을 제출받아야 한다.', 370);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (538, '③ 사법경찰관리는 제2항에 따른 고소권자의 대리인으로부터 고소를 수리하는 경우에는 제1항 및 제2항에 따른 위임장 및 자격을 증명하는 서면을 함께 제출받아야 한다.', 370);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (539, '④ 고소의 취소에 관하여는 제1항부터 제3항까지의 규정을 준용한다.', 370);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (540, '① 사법경찰관리는 고소ㆍ고발을 수리한 날부터 3개월 이내에 수사를 마쳐야 한다.', 371);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (541, '② 사법경찰관리는 제1항의 기간 내에 수사를 완료하지 못한 경우에는 그 이유를 소속수사부서장에게 보고하고 수사기간 연장을 승인받아야 한다.', 371);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (542, '① 사법경찰관리는 고소ㆍ고발의 취소가 있을 때에는 그 취지를 명확하게 확인해야 한다.', 372);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (543, '② 피해자의 명시한 의사에 반하여 공소를 제기할 수 없는 범죄에 대해 처벌을 희망하는 의사표시의 철회가 있을 때에도 제1항과 같다.', 372);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (544, '① 사법경찰관은 수사준칙 제17조제1항에 따라 변사사건 발생사실을 검사에게 통보하는 경우에는 별지 제14호서식의 변사사건 발생 통보서에 따른다.', 373);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (545, '② 사법경찰관은 긴급한 상황 등 제1항의 방식으로 통보하는 것이 불가능하거나 현저히 곤란한 경우에는 구두ㆍ전화ㆍ팩스ㆍ전자우편 등 간편한 방식으로 통보할 수 있다. 이 경우 사후에 지체 없이 서면으로 변사사건 발생사실을 통보해야 한다.', 373);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (546, '① 사법경찰관은 법 제222조제1항 및 제3항에 따라 검시를 하는 경우에는 의사를 참여시켜야 하며, 그 의사로 하여금 검안서를 작성하게 해야 한다. 이 경우 사법경찰관은 검시 조사관을 참여시킬 수 있다.', 374);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (547, '② 사법경찰관은 법 제222조에 따른 검시 또는 검증 결과 사망의 원인이 범죄로 인한 것으로 판단하는 경우에는 신속하게 수사를 개시해야 한다.', 374);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (548, '① 수사준칙 제17조제3항에 따른 검시조서는 별지 제15호서식에 따르고, 검증조서는 별지 제16호서식에 따른다.', 375);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (549, '② 사법경찰관은 수사준칙 제17조제3항에 따라 검사에게 제1항의 검시조서 또는 검증조서를 송부하는 경우에는 의사의 검안서, 감정서 및 촬영한 사진 등 관련 자료를 첨부해야 한다.', 375);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (550, '③ 사법경찰관은 수사준칙 제17조제4항에 따라 검시를 한 사건에 대해 검사와 의견을 제시ㆍ교환하는 경우에는 별지 제17호서식의 변사사건 처리 등에 관한 의견서에 따른다.', 375);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (551, null, 376);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (552, '① 사법경찰관은 변사자에 대한 검시 또는 검증이 종료된 때에는 사체를 소지품 등과 함께 신속히 유족 등에게 인도한다. 다만, 사체를 인수할 사람이 없거나 변사자의 신원이 판명되지 않은 경우에는 사체가 현존하는 지역의 특별자치시장ㆍ특별자치도지사ㆍ시장ㆍ군수 또는 자치구의 구청장에게 인도해야 한다.', 378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (553, '② 제1항 본문에서 검시 또는 검증이 종료된 때는 다음 각 호의 구분에 따른 때를 말한다.', 378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (554, '③ 사법경찰관은 제1항에 따라 사체를 인도한 경우에는 인수자로부터 별지 제18호서식의 사체 및 소지품 인수서를 받아야 한다.', 378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (555, '① 사법경찰관은 수사준칙 제21조제2항제4호에 따라 심야조사를 하려는 경우에는 심야조사의 내용 및 심야조사가 필요한 사유를 소속 해양경찰관서에서 인권보호 업무를 담당하는 부서의 장에게 보고하고 허가를 받아야 한다.', 383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (556, '② 사법경찰관은 제1항에 따라 허가를 받은 경우 수사보고서를 작성하여 사건기록에 편철해야 한다.', 383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (557, '① 수사준칙 제24조제2항에 따른 동석신청서는 별지 제24호서식 또는 별지 제25호서식에 따른다.', 385);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (558, '② 사법경찰관은 피의자, 피해자 또는 그 법정대리인이 제1항의 동석신청서를 작성할 시간적 여유가 없는 경우 등에는 이를 제출받지 않고 조서 또는 수사보고서에 그 취지를 기재하는 것으로 동석신청서 작성을 갈음할 수 있으며, 조사의 긴급성 또는 동석의 필요성 등이 현저한 경우에는 예외적으로 동석 조사 이후에 신뢰관계인과 피의자와의 관계를 소명할 자료를 제출받아 기록에 편철할 수 있다.', 385);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (559, '③ 사법경찰관은 동석 신청이 없더라도 동석이 필요하다고 인정되면 피의자 또는 피해자와의 신뢰관계 유무를 확인한 후 직권으로 신뢰관계에 있는 사람을 동석하게 할 수 있다. 이 경우 그 관계 및 취지를 조서나 수사보고서에 적어야 한다.', 385);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (560, '④ 사법경찰관은 신뢰관계인의 동석으로 인하여 신문이 방해되거나, 수사기밀이 누설되는 등 정당한 사유가 있는 경우에는 동석을 거부할 수 있으며, 신뢰관계인이 피의자신문 또는 피해자 조사를 방해하거나 그 진술의 내용에 부당한 영향을 미칠 수 있는 행위를 하는 등 수사에 현저한 지장을 초래하는 경우에는 피의자신문 또는 피해자 조사 중에도 동석을 제한할 수 있다.', 385);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (561, '⑤ 피해자 이외의 사건관계인 조사에 관하여는 제1항부터 제4항까지의 규정을 준용한다.', 385);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (562, '① 사법경찰관리가 법 제244조제1항에 따라 피의자의 진술을 조서에 적는 경우에는 별지 제26호서식 또는 별지 제27호서식의 피의자신문조서에 따른다.', 386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (563, '② 사법경찰관리가 피의자가 아닌 사람의 진술을 조서에 적는 경우에는 별지 제28호서식 또는 별지 제29호서식의 진술조서에 따른다.', 386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (564, '③ 사법경찰관리는 피의자 또는 피의자가 아닌 사람의 진술을 듣는 경우 진술 사항이 복잡하거나 진술인이 서면진술을 원하면 진술서를 작성하여 제출하게 할 수 있다.', 386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (565, '④ 피의자신문조서와 진술조서에는 진술자로 하여금 간인(間印)한 후 기명날인 또는 서명하게 한다.', 386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (566, '① 사법경찰관리는 범죄의 현장 또는 그 밖의 장소에서 피의사실을 확인하거나 증거물의 증명력을 확보하기 위해 필요한 경우 실황조사를 할 수 있다.', 388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (567, '② 사법경찰관리는 실황조사를 하는 경우에는 거주자, 관리자 그 밖의 관계자 등을 참여하게 할 수 있다.', 388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (568, '③ 사법경찰관리는 실황조사를 한 경우에는 별지 제32호서식의 실황조사서에 조사 내용을 상세하게 적고, 현장도면이나 사진이 있으면 이를 실황조사서에 첨부해야 한다.', 388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (569, '① 사법경찰관리는 법 제221조제1항 또는 제244조의2제1항에 따라 피의자 또는 피의자가 아닌 사람을 영상녹화하는 경우 그 조사의 시작부터 조서에 기명날인 또는 서명을 마치는 시점까지의 모든 과정을 영상녹화해야 한다. 다만, 조사 도중 영상녹화의 필요성이 발생한 때에는 그 시점에서 진행 중인 조사를 중단하고, 중단한 조사를 다시 시작하는 때부터 조서에 기명날인 또는 서명을 마치는 시점까지의 모든 과정을 영상녹화해야 한다.', 390);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (570, '② 사법경찰관리는 제1항에도 불구하고 조사를 마친 후 조서 정리에 오랜 시간이 필요한 경우에는 조서 정리과정을 영상녹화하지 않고, 조서 열람 시부터 영상녹화를 다시 시작할 수 있다.', 390);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (571, '③ 제1항 및 제2항에 따른 영상녹화는 조사실 전체를 확인할 수 있고 조사받는 사람의 얼굴과 음성을 식별할 수 있도록 해야 한다.', 390);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (572, '④ 사법경찰관리는 피의자에 대한 조사 과정을 영상녹화하는 경우 다음 각 호의 사항을 고지해야 한다.', 390);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (573, '⑤ 사법경찰관리는 피의자가 아닌 사람의 조사 과정을 영상녹화하는 경우에는 별지 제34호서식의 영상녹화 동의서로 영상녹화 동의 여부를 확인하고, 제4항제1호, 제2호 및 제4호의 사항을 고지해야 한다. 다만, 피혐의자에 대해서는 제4항제1호부터 제4호까지의 규정에 따른 사항을 고지해야 한다.', 390);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (574, '① 사법경찰관리는 조사 시 영상녹화를 한 경우에는 영상녹화용 컴퓨터에 저장된 영상녹화 파일을 이용하여 영상녹화물(CD, DVD 등을 말한다. 이하 같다) 2개를 제작하여 그 중 하나를 피조사자의 기명날인 또는 서명을 받아 피조사자 또는 변호인 앞에서 봉인한 후, 봉인하지 않은 나머지 하나와 함께 수사기록에 편철한다. <개정 2024.6.19>', 391);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (575, '② 사법경찰관리는 제1항에 따라 영상녹화물을 제작한 후 영상녹화용 컴퓨터에 저장되어 있는 영상녹화 파일을 데이터베이스 서버에 전송하여 보관할 수 있다.', 391);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (576, '③ 사법경찰관리는 손상 또는 분실 등으로 제1항의 영상녹화물을 사용할 수 없는 경우에는 데이터베이스 서버에 보관되어 있는 영상녹화 파일을 이용하여 다시 영상녹화물을 제작할 수 있다.', 391);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (577, '① 사법경찰관리는 다음 각 호의 어느 하나에 해당하는 사람의 소재를 알 수 없을 때에는 지명수배를 할 수 있다.', 392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (578, '② 제1항에도 불구하고 법 제200조의3제1항에 따른 긴급체포를 하지 않으면 수사에 현저한 지장을 초래하는 경우에는 영장을 발부받지 않고 지명수배할 수 있다. 이 경우 지명수배 후 신속히 체포영장을 발부받아야 하며, 체포영장을 발부받지 못한 때에는 즉시 지명수배를 해제해야 한다.', 392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (579, '① 사법경찰관리는 제45조제1항에 따라 지명수배된 사람(이하 "지명수배자"라 한다)을 발견한 때에는 체포영장 또는 구속영장을 제시하고, 수사준칙 제32조제1항에 따라 권리 등을 고지한 후 체포 또는 구속하며 별지 제35호서식의 권리 고지 확인서를 받아야 한다. 다만, 체포영장 또는 구속영장을 소지하지 않은 경우 긴급하게 필요하면 지명수배자에게 영장이 발부되었음을 고지한 후 체포 또는 구속할 수 있으며 사후에 지체 없이 그 영장을 제시해야 한다.', 393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (580, '② 사법경찰관은 제45조제2항에 따라 영장을 발부받지 않고 지명수배한 경우에는 지명수배자에게 긴급체포한다는 사실과 수사준칙 제32조제1항에 따른 권리 등을 고지한 후 긴급체포해야 한다. 이 경우 지명수배자로부터 별지 제35호서식의 권리 고지 확인서를 받고 제51조제1항에 따른 긴급체포서를 작성해야 한다.', 393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (581, null, 394);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (582, null, 396);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (583, '① 법 제200조의3제3항에 따른 긴급체포서는 별지 제37호서식에 따른다.', 398);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (584, '② 수사준칙 제27조제2항 본문에 따른 긴급체포 승인요청서는 별지 제38호서식에 따른다.', 398);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (585, '③ 사법경찰관은 수사준칙 제27조제4항 후단에 따라 긴급체포된 피의자의 석방 일시와 사유 등을 검사에게 통보하는 경우에는 별지 제39호서식의 석방 통보서에 따른다.', 398);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (586, '① 사법경찰관리는 법 제212조에 따라 현행범인을 체포할 때에는 현행범인에게 도망 또는 증거인멸의 우려가 있는 등 당장에 체포하지 않으면 안 될 정도의 급박한 사정이 있는지 또는 체포 외에는 현행범인의 위법행위를 제지할 다른 방법이 없는지 등을 고려해야 한다.', 399);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (587, '② 사법경찰관리는 법 제212조에 따라 현행범인을 체포한 때에는 별지 제40호서식의 현행범인체포서를 작성하고, 법 제213조에 따라 현행범인을 인도받은 때에는 별지 제41호서식의 현행범인인수서를 작성해야 한다.', 399);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (588, '③ 사법경찰관리는 제2항의 현행범인체포서 또는 현행범인인수서를 작성하는 경우 현행범인에 대해서는 범죄와의 시간적 접착성과 범죄의 명백성이 인정되는 상황을, 준현행범인에 대해서는 범죄와의 관련성이 인정되는 상황을 구체적으로 적어야 한다.', 399);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (589, '① 수사준칙 제28조제2항 전단에 따른 피의자 석방서는 별지 제42호서식에 따른다.', 400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (590, '② 사법경찰관은 수사준칙 제28조제2항 후단에 따라 검사에게 현행범인의 석방사실을 통보하는 경우에는 별지 제43호서식의 석방 통보서에 따른다.', 400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (591, '① 사법경찰관리는 체포영장 또는 구속영장을 집행할 때에는 신속하고 정확하게 해야 한다.', 402);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (592, '② 체포영장 또는 구속영장의 집행은 검사가 서명 또는 날인하여 교부한 영장이나 검사가 영장의 집행에 관한 사항을 적어 교부한 서면에 따른다.', 402);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (593, '③ 수사준칙 제32조제3항에 따른 권리 고지 확인서는 별지 제35호서식에 따른다. 다만, 피의자가 권리 고지 확인서에 기명날인 또는 서명하기를 거부하는 경우에는 피의자를 체포ㆍ구속하는 사법경찰관리가 확인서 끝부분에 그 사유를 적고 기명날인 또는 서명해야 한다.', 402);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (594, '④ 수사준칙 제32조의2제3항에 따른 영장 사본 교부 확인서는 별지 제47호의2서식에 따른다. 다만, 피의자가 영장 사본의 수령을 거부하거나 영장 사본 교부 확인서에 기명날인 또는 서명하는 것을 거부하는 경우에는 체포영장 또는 구속영장을 집행하는 사법경찰관리가 영장 사본 교부 확인서 끝 부분에 그 사유를 적고 기명날인 또는 서명해야 한다. <신설 2024.6.19>', 402);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (595, '① 사법경찰관리는 체포ㆍ구속한 피의자를 호송할 때에는 피의자의 도망ㆍ자살ㆍ신변안전ㆍ증거인멸 등에 주의해야 한다.', 403);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (596, '② 사법경찰관리는 체포ㆍ구속한 피의자를 호송할 때 필요한 경우에는 가장 근접한 경찰관서에 피의자를 임시로 유치할 수 있다.', 403);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (597, '① 사법경찰관은 법 제200조의6 및 제209조에서 준용하는 법 제91조 또는 「형의 집행 및 수용자의 처우에 관한 법률」 제87조에서 준용하는 같은 법 제41조에 따라 체포 또는 구속된 피의자와 법 제34조에서 규정한 사람이 아닌 사람과의 접견 등을 금지하려는 경우에는 별지 제50호서식의 피의자 접견 등 금지 결정서에 따른다.', 406);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (598, '② 사법경찰관은 제1항의 결정을 취소하는 것이 타당하다고 인정되어 피의자 접견 등의 금지를 취소하는 경우에는 별지 제51호서식의 피의자 접견 등 금지 취소 결정서에 따른다.', 406);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (599, '③ 제1항의 피의자 접견 등 금지 결정은 사법경찰관의 사건 송치와 동시에 그 효력을 상실한다.', 406);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (600, '① 수사준칙 제36조제1항에 따른 피의자 석방서는 별지 제52호서식 또는 별지 제53호서식에 따른다.', 407);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (601, '② 사법경찰관은 검사에게 수사준칙 제36조제2항제1호에 따라 석방사실을 통보하는 경우에는 별지 제54호서식의 석방 통보서에 따르고, 같은 항 제2호에 따라 석방사실을 보고하는 경우에는 별지 제55호서식의 석방 보고서에 따른다.', 407);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (602, '① 사법경찰관은 법 제209조에서 준용하는 법 제93조에 따라 구속을 취소하여 피의자를 석방하는 경우에는 별지 제56호서식의 구속취소 결정서에 따른다. 다만, 법 제245조의5제1호에 따라 검사에게 송치해야 하는 사건인 경우에는 사전에 별지 제57호서식의 구속취소 동의 요청서에 따라 검사의 동의를 받아야 한다.', 408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (603, '② 제1항에 따라 구속을 취소한 사법경찰관은 지체 없이 별지 제58호서식의 석방 통보서를 작성하여 검사에게 석방사실을 통보하고, 그 통보서 사본을 사건기록에 편철해야 한다.', 408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (604, '① 사법경찰관은 법 제209조에서 준용하는 법 제101조제1항에 따라 구속의 집행을 정지하는 경우에는 별지 제59호서식의 구속집행정지 결정서에 따른다.', 409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (605, '② 제1항에 따라 구속의 집행을 정지한 사법경찰관은 지체 없이 별지 제60호서식의 구속집행정지 통보서를 작성하여 검사에게 그 사실을 통보하고, 그 통보서 사본을 사건기록에 편철해야 한다.', 409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (606, '③ 사법경찰관은 법 제209조에서 준용하는 법 제102조제2항에 따라 구속집행정지 결정을 취소하는 경우에는 별지 제61호서식의 구속집행정지 취소 결정서에 따른다.', 409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (607, '① 사법경찰관은 수사준칙 제37조에 따라 압수ㆍ수색 또는 검증영장을 신청하는 경우에는 별지 제62호서식부터 별지 제64호서식까지의 압수ㆍ수색ㆍ검증영장 신청서에 따른다. 이 경우 압수ㆍ수색 또는 검증의 필요성 및 해당 사건과의 관련성을 인정할 수 있는 자료를 신청서에 첨부해야 한다.', 410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (608, '② 압수ㆍ수색 또는 검증영장의 집행 및 반환에 관하여는 제55조제1항ㆍ제2항 및 제58조를 준용한다.', 410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (609, '③ 수사준칙 제38조제4항에 따른 영장 사본 교부 확인서는 별지 제47호의2서식에 따른다. 다만, 피의자가 영장 사본의 수령을 거부하거나 영장 사본 교부 확인서에 기명날인 또는 서명하는 것을 거부하는 경우에는 압수ㆍ수색 또는 검증영장을 집행하는 사법경찰관리가 영장 사본 교부 확인서 끝 부분에 그 사유를 적고 기명날인 또는 서명해야 한다. <신설 2024.6.19>', 410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (610, '① 수사준칙 제40조 본문에 따른 압수조서는 별지 제65호서식에 따르고, 압수목록은 별지 제66호서식에 따른다.', 411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (611, '② 법 제219조에서 준용하는 법 제129조에 따라 압수목록을 교부하는 경우에는 별지 제67호서식의 압수목록 교부서에 따른다. 이 경우 수사준칙 제41조제1항에 따른 전자정보에 대한 압수목록 교부서는 전자파일의 형태로 복사해 주거나 전자우편으로 전송하는 등의 방식으로 교부할 수 있다.', 411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (612, '③ 수사준칙 제42조제2항 후단에 따른 삭제ㆍ폐기ㆍ반환 확인서는 별지 제68호서식에 따른다. 다만, 제2항에 따른 압수목록 교부서에 삭제ㆍ폐기 또는 반환했다는 내용을 포함시켜 교부하는 경우에는 삭제ㆍ폐기ㆍ반환 확인서를 교부하지 않을 수 있다.', 411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (613, '① 사법경찰관은 법 제215조에 따라 수색을 한 경우에는 수색의 상황과 결과를 명백히 한 별지 제69호서식의 수색조서를 작성해야 한다.', 412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (614, '② 법 제219조에서 준용하는 법 제128조에 따라 증거물 또는 몰수할 물건이 없다는 취지의 증명서를 교부하는 경우에는 별지 제70호서식의 수색증명서에 따른다.', 412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (615, '① 사법경찰관은 법 제218조의2제1항 및 제4항에 따라 압수물에 대해 그 소유자, 소지자, 보관자 또는 제출인(이하 이 조에서 "소유자등"이라 한다)으로부터 환부 또는 가환부의 청구를 받거나 법 제219조에서 준용하는 법 제134조에 따라 압수장물을 피해자에게 환부하려는 경우에는 별지 제71호서식의 압수물 처분 지휘 요청서를 작성하여 검사에게 제출해야 한다.', 413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (616, '② 사법경찰관은 제1항에 따른 압수물의 환부 또는 가환부의 청구를 받은 경우 소유자등으로부터 별지 제72호서식의 압수물 환부ㆍ가환부 청구서를 제출받아 별지 제71호서식의 압수물 처분 지휘 요청서에 첨부한다.', 413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (617, '③ 사법경찰관은 압수물을 환부 또는 가환부한 경우에는 피해자 및 소유자등으로부터 별지 제73호서식의 압수물 환부ㆍ가환부 영수증을 받아야 한다.', 413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (618, '① 사법경찰관은 압수물에 사건명, 피의자의 성명, 제64조제1항의 압수목록에 적힌 순위ㆍ번호를 기입한 표찰을 붙여야 한다.', 414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (619, '② 사법경찰관은 법 제219조에서 준용하는 법 제130조제1항에 따라 압수물을 다른 사람에게 보관하게 하려는 경우에는 별지 제74호서식의 압수물 처분 지휘요청서를 작성하여 검사에게 제출해야 한다.', 414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (620, '③ 사법경찰관은 제2항에 따라 압수물을 다른 사람에게 보관하게 하는 경우 적절한 보관인을 선정하여 성실하게 보관하게 하고, 보관인으로부터 별지 제75호서식의 압수물 보관 서약서를 받아야 한다.', 414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (621, '① 사법경찰관은 법 제219조에서 준용하는 법 제130조제2항 및 제3항에 따라 압수물을 폐기하려는 경우에는 별지 제76호서식의 압수물 처분 지휘요청서를 작성하여 검사에게 제출해야 한다.', 415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (622, '② 사법경찰관은 제1항에 따라 압수물을 폐기하는 경우에는 별지 제77호서식의 압수물 폐기 조서를 작성하고 사진을 촬영하여 사건기록에 편철해야 한다.', 415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (623, '③ 사법경찰관은 법 제219조에서 준용하는 법 제130조제3항에 따라 압수물을 폐기하는 경우에는 소유자 등 권한 있는 사람으로부터 별지 제78호서식의 압수물 폐기 동의서를 제출받거나 진술조서 등에 그 취지를 적어야 한다.', 415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (624, '① 사법경찰관은 법 제219조에서 준용하는 법 제132조에 따라 압수물을 매각하여 대가를 보관하려는 경우에는 별지 제79호서식의 압수물 처분 지휘요청서를 작성하여 검사에게 제출해야 한다.', 416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (625, '② 사법경찰관은 제1항에 따라 대가보관의 처분을 했을 때에는 별지 제80호서식의 압수물 대가보관 조서를 작성한다.', 416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (626, '① 사법경찰관은 법 제221조제2항의 감정을 위해 법 제172조제3항에 따른 유치가 필요한 경우에는 별지 제83호서식의 감정유치장 신청서를 작성하여 검사에게 제출해야 한다.', 420);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (627, '② 사법경찰관은 법 제221조의4제1항에 따라 법 제173조제1항에 따른 처분을 위한 허가가 필요한 경우에는 별지 제84호서식의 감정처분허가장 신청서를 작성하여 검사에게 제출해야 한다.', 420);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (628, '① 사법경찰관은 수사준칙 제45조제2항에 따라 사건기록 등본을 검사에게 송부하는 경우에는 별지 제85호서식의 사건기록 등본 송부서를 작성하여 사건기록 등본에 편철해야 한다.', 422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (629, '② 사법경찰관은 제1항에 따라 사건기록 등본을 송부하는 경우에는 해당 사건기록 전체의 등본을 송부한다. 다만, 등본송부 요구의 사유가 사건기록의 일부와 관련된 경우에는 사전에 검사와 합의하고 해당 부분에 대해서만 등본을 송부할 수 있다.', 422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (630, '③ 사법경찰관은 필요하다고 인정하는 경우 제1항에 따라 사건기록 등본을 송부하면서 의견을 함께 제출할 수 있다.', 422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (631, '④ 사법경찰관은 수사준칙 제45조제4항에 따라 검사에게 시정조치 이행 결과를 통보하는 경우 별지 제86호서식의 시정조치 결과 통보서에 따른다. 다만, 법률상ㆍ사실상 시정이 불가능한 경우 등 정당한 이유가 있어 시정조치요구를 이행하지 않은 경우에는 그 내용과 사유를 시정조치 결과 통보서에 구체적으로 적어 통보해야 한다.', 422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (632, '① 사법경찰관은 수사준칙 제48조제1항에 따라 검사에게 사건기록의 열람을 요청하는 경우에는 별지 제89호서식의 사건기록 열람요청서에 따른다.', 425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (633, '② 사법경찰관은 검사로부터 수사준칙 제48조제1항에 따른 사건기록의 열람을 요청하는 서면을 받은 경우에는 그 요청 서면을 검토하여 열람 허용 여부 및 범위를 신속하게 결정한다.', 425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (634, '③ 사법경찰관이 검사에게 열람을 허용할 수 있는 사건기록의 범위는 다음 각 호와 같다. 다만, 예외적으로 그 외 사건기록의 열람을 허용할 필요가 있는 경우에는 달리 정할 수 있다.', 425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (635, '④ 사법경찰관은 별지 제90호서식의 열람허가서에 열람을 허용하는 사건기록의 범위를 기재하여 제2항의 사건기록 중 열람을 허용한 사건기록 등본과 함께 사건기록담당직원에게 인계한다.', 425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (636, '⑤ 사건기록담당직원은 검사에게 기록을 열람하게 하고, 관리대장에 열람 일시, 열람 검사의 성명 등을 기재한다.', 425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (637, '① 사법경찰관리는 피해자[타인의 범죄행위로 피해를 당한 사람과 그 배우자(사실상의 혼인관계에 있는 자를 포함한다), 직계친족 및 형제자매를 말한다. 이하 이 장에서 같다]의 심정을 이해하고 그 인격을 존중하며 피해자가 범죄피해 상황에서 조속히 회복하여 인간의 존엄성을 보장받을 수 있도록 노력해야 한다.', 426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (638, '② 사법경찰관리는 피해자의 명예와 사생활의 평온을 보호하고 해당 사건과 관련하여 각종 법적 절차에 참여할 권리를 보장해야 한다.', 426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (639, '① 수사준칙 제15조제2항에 따른 신변보호에 필요한 조치의 유형은 다음 각 호와 같다.', 427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (640, '② 범죄신고자 등 참고인으로서 범죄수사와 관련하여 보복을 당할 우려가 있는 경우에 관하여는 제1항을 준용한다.', 427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (641, null, 428);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (642, '① 사법경찰관리는 피해자가 입은 피해의 실질적인 회복 등을 위해 필요하다고 인정하면 피해자 또는 가해자의 신청과 그 상대방의 동의에 따라 서로 대화할 수 있는 기회를 제공할 수 있다.', 429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (643, '② 제1항에 따라 대화 기회를 제공하는 경우 사법경찰관리는 피해자와 가해자 간 대화가 원활하게 진행될 수 있도록 전문가에게 회복적 대화 진행을 의뢰할 수 있다.', 429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (644, '① 사법경찰관은 수사에 필요한 장부와 서류철을 갖추어 두고 보존기간을 정하여 관리해야 한다.', 432);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (645, '② 제1항의 장부와 서류철은 형사사법정보시스템을 통해 전자적으로 작성ㆍ저장ㆍ관리ㆍ보존할 수 있다. 이 경우 전자 장부와 서류철은 종이 장부와 서류철의 개별 항목을 포함해야 한다.', 432);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (646, '① 수사준칙 제69조(같은 영 제16조제6항에서 준용하는 경우를 포함한다)에 따른 수사서류 열람ㆍ복사 신청은 해당 수사서류를 보유ㆍ관리하는 해양경찰관서의 장에게 해야 한다.', 434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (647, '② 제1항의 신청을 받은 해양경찰관서의 장은 신청을 받은 날부터 10일 이내에 다음 각 호의 어느 하나에 해당하는 결정을 해야 한다.', 434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (648, '③ 해양경찰관서의 장은 제2항에도 불구하고 피의자 및 사건관계인, 그 변호인이 조사 당일 본인의 진술이 기재된 조서에 대해 열람ㆍ복사를 신청하는 경우에는 공개 여부에 대해 지체 없이 검토한 후 제공 여부를 결정해야 한다.', 434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (649, '④ 해양경찰관서의 장은 해당 관서에서 보유ㆍ관리하지 않는 수사서류에 대해 열람ㆍ복사 신청을 접수한 경우에는 그 신청을 해당 수사서류를 보유ㆍ관리하는 기관으로 이송하거나 신청인에게 부존재 통지를 해야 한다.', 434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (650, '⑤ 해양경찰관서의 장은 제2항제1호 또는 제2호에 따라 수사서류를 제공하는 경우에는 사건관계인의 개인정보가 공개되지 않도록 비실명처리 등 보호조치를 해야 한다.', 434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (651, '⑥ 제1항부터 제5항까지에서 규정한 사항 외에 수사서류 열람ㆍ복사에 필요한 세부 사항은 해양경찰청장이 따로 정한다.', 434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (652, '① 사법경찰관리는 혼획ㆍ좌초 또는 표류된 고래류 신고를 접수하였을 때에는 현장조사를 하여 불법포획 등 위법행위 여부를 조사해야 한다.', 435);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (653, '② 사법경찰관은 제1항에 따른 조사 결과, 위법행위가 확인되지 않은 경우에는 신고인이 희망하는 위판장을 지정하여 신고인에게 해양수산부장관이 정하여 고시하는 고래류 처리확인서를 발급해야 한다.', 435);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (654, '① 사법경찰관리는 소년을 조사하는 경우에는 행위의 동기, 그 소년의 성품과 행실, 경력, 가정 상황, 교우관계, 그 밖의 환경 등을 상세히 조사하여 그 결과를 서면으로 적어야 한다.', 437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (655, '② 사법경찰관리는 소년에 대한 출석요구나 조사를 하는 경우에는 지체 없이 그 소년의 보호자 또는 보호자를 대신하여 소년을 보호할 수 있는 사람에게 연락해야 한다. 다만, 연락하는 것이 그 소년의 복리상 부적당하다고 인정되는 경우에는 그렇지 않다.', 437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (656, '③ 사법경찰관리는 소년인 피의자에 대해서는 가급적 구속을 피하고, 부득이하게 체포ㆍ구속 또는 임의동행하는 경우에는 그 시기와 방법에 특히 주의해야 한다.', 437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (657, '④ 사법경찰관리는 소년인 피의자가 체포ㆍ구속된 경우에는 다른 사건보다 우선하여 그 사건을 조사하는 등 신속한 수사를 위해 노력해야 한다.', 437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (658, '① 사법경찰관리는 외국인을 조사하는 경우에는 조사를 받는 외국인이 이해할 수 있는 언어로 통역해 주어야 한다.', 439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (659, '② 사법경찰관리는 외국인을 체포ㆍ구속하는 경우 국내 법령을 위반하지 않는 범위에서 영사관원과 자유롭게 접견ㆍ교통할 수 있고, 체포ㆍ구속된 사실을 영사기관에 통보해 줄 것을 요청할 수 있다는 사실을 알려야 한다.', 439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (660, '③ 사법경찰관리는 체포ㆍ구속된 외국인이 제2항에 따른 통보를 요청하는 경우에는 별지 제91호서식의 영사기관 체포ㆍ구속 통보서를 작성하여 지체 없이 해당 영사기관에 체포ㆍ구속 사실을 통보해야 한다.', 439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (661, '④ 사법경찰관리는 외국인 변사사건이 발생한 경우에는 별지 제92호서식의 영사기관 사망 통보서를 작성하여 지체 없이 해당 영사기관에 통보해야 한다.', 439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (662, '① 사법경찰관은 주한 미합중국 군대의 구성원ㆍ외국인군무원 및 그 가족이나 초청계약자의 범죄 관련 사건을 인지하거나 고소ㆍ고발 등을 수리한 때에는 7일 이내에 별지 제93호서식의 한미행정협정사건 통보서를 검사에게 통보해야 한다.', 441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (663, '② 사법경찰관은 주한 미합중국 군당국으로부터 공무증명서를 제출받은 경우 지체 없이 공무증명서의 사본을 검사에게 송부해야 한다.', 441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (664, '③ 사법경찰관은 검사로부터 주한 미합중국 군당국의 재판권포기 요청 사실을 통보받은 날부터 14일 이내에 검사에게 사건을 송치 또는 송부해야 한다. 다만, 검사의 동의를 받아 그 기간을 연장할 수 있다.', 441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (665, '① 사법경찰관은 관계 법령에 따라 검사에게 추징보전을 신청하는 경우에는 별지 제95호서식의 추징보전 신청서에 따른다.', 443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (666, '② 사법경찰관은 검사에게 추징보전명령의 취소를 신청하는 경우에는 별지 제96호서식의 추징보전명령 취소 신청서에 따른다.', 443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (667, '① 사법경찰관리는 범죄 인지 후 1년이 지난 사건에 대해서는 수사준칙 제51조제1항에 따른 결정을 해야 한다. 다만, 다수의 사건관계인 조사, 관련 자료 추가확보ㆍ분석, 외부 전문기관 감정의 장기화, 범인 미검거 등으로 계속하여 수사가 필요한 경우에는 해당 사법경찰관리가 소속된 바로 위 상급해양경찰관서 수사 부서의 장의 승인을 받아 연장할 수 있다.', 444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (668, '② 사법경찰관리는 제1항 단서에 따른 승인을 받으려면 수사기간 연장의 필요성을 소명해야 한다.', 444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (669, '① 사법경찰관은 사건이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 사건을 다른 해양경찰관서 또는 기관에 이송해야 한다.', 445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (670, '② 사법경찰관은 사건이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 사건을 다른 해양경찰관서 또는 기관(해당 기관과 협의된 경우로 한정한다)에 이송할 수 있다.', 445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (671, '③ 사법경찰관은 제1항 또는 제2항에 따라 사건을 이송하는 경우에는 별지 제97호서식의 사건이송서를 사건기록에 편철하고 관계 서류와 증거물을 다른 해양경찰관서 또는 기관에 송부해야 한다.', 445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (672, '① 사법경찰관은 수사준칙 제53조에 따라 피의자와 고소인등에게 수사 결과를 통지하는 경우에는 사건을 송치하거나 사건기록을 송부한 날부터 7일 이내에 해야 한다. 다만, 피의자나 고소인등의 연락처를 모르거나 소재가 확인되지 않는 경우에는 연락처나 소재를 안 날부터 7일 이내에 통지를 해야 한다.', 446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (673, '② 제1항의 통지(법 제245조의6에 따른 고소인등에 대한 불송치 통지는 제외한다)는 서면, 전화, 팩스, 전자우편, 문자메시지 등 피의자나 고소인등이 요청한 방법으로 할 수 있으며, 별도로 요청한 방법이 없는 경우에는 서면으로 한다. 이 경우 서면으로 하는 통지는 별지 제98호서식부터 별지 제100호서식까지의 수사결과 통지서에 따른다.', 446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (674, '③ 법 제245조의6에 따른 고소인등에 대한 불송치 통지는 별지 제101호서식의 수사결과 통지서에 따른다.', 446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (675, '④ 제2항 후단 및 제3항에도 불구하고 하나의 사건에 수사준칙 제51조제1항 각 호에 따른 법원송치, 검찰송치, 불송치, 수사중지 및 이송 결정이 병존하는 사건의 수사 결과를 통지하는 경우에는 별지 제101호의2서식 또는 별지 제101호의3서식의 수사결과 통지서에 따를 수 있다. <신설 2024.6.19>', 446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (676, '⑤ 사법경찰관은 서면으로 통지한 경우에는 그 사본을, 그 외의 방법으로 통지한 경우에는 그 취지를 적은 서면을 사건기록에 편철해야 한다. <개정 2024.6.19>', 446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (677, '⑥ 수사준칙 제53조제2항에 따른 고소인등의 통지 요구는 별지 제102호서식의 불송치 통지요구서에 따른다. <개정 2024.6.19>', 446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (678, '⑦ 사법경찰관은 고소인, 고발인 또는 피의자가 불송치 결정에 관한 사실증명을 청구한 경우에는 지체 없이 별지 제103호서식 또는 별지 제104호서식의 불송치 결정 증명서를 발급해야 한다. <개정 2024.6.19>', 446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (679, '⑧ 사법경찰관은 고소인등에게 수사중지 결정의 통지를 하는 경우에는 수사준칙 제54조제3항에 따라 검사에게 신고할 수 있다는 내용을 통지서에 기재해야 한다. <개정 2024.6.19>', 446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (680, '① 사법경찰관은 다음 각 호의 구분에 해당하는 경우에는 그 사유가 해소될 때까지 수사준칙 제51조제1항제4호에 따른 수사중지 결정을 할 수 있다.', 447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (681, '② 사법경찰관은 제1항에 따라 수사중지의 결정을 하는 경우에는 별지 제105호서식의 수사중지 결정서를 작성하여 사건기록에 편철해야 한다.', 447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (682, '③ 사법경찰관은 수사준칙 제51조제4항에 따라 검사에게 사건기록을 송부하는 경우에는 별지 제106호서식의 수사중지 사건기록 송부서를 사건기록에 편철해야 한다.', 447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (683, '④ 사법경찰관리는 제1항제1호나목 또는 다목의 사유로 수사중지 결정을 한 경우에는 매월 1회 이상 해당 수사중지 사유가 해소되었는지를 확인해야 한다.', 447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (684, '① 사법경찰관은 소재불명의 사유로 수사중지를 하려는 경우에는 별지 제107호서식의 소재수사 보고서를 작성하여 사건기록에 편철해야 한다.', 448);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (685, '② 사법경찰관리는 소재불명의 사유로 수사중지된 사건의 경우 매 분기 1회 이상 소재수사를 하는 등 수사중지 사유 해소를 위해 노력해야 한다.', 448);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (686, '① 수사준칙 제54조제1항에 따라 이의제기를 하려는 사람은 수사중지 결정을 통지받은 날부터 30일 이내에 해당 사법경찰관이 소속된 바로 위 상급해양경찰관서의 장(이하 "소속상급해양경찰관서장"이라 한다)에게 별지 제108호서식의 수사중지 결정 이의제기서를 제출해야 한다.', 450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (687, '② 제1항에 따른 이의제기서는 해당 사법경찰관이 소속된 해양경찰관서에 제출할 수 있다. 이 경우 이의제기서를 제출받은 해양경찰관서의 장은 이를 지체 없이 소속상급해양경찰관서장에게 송부해야 한다.', 450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (688, '③ 소속상급해양경찰관서장은 제1항 또는 제2항에 따라 이의제기서를 제출받거나 송부받은 날부터 30일 이내에 다음 각 호의 구분에 따른 결정을 하고 해당 사법경찰관의 소속수사부서장에게 이를 통보해야 한다.', 450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (689, '④ 제3항제1호에 따른 결정을 통보받은 소속수사부서장은 지체 없이 이를 이행하고 소속상급해양경찰관서장에게 이행 결과를 보고해야 한다.', 450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (690, '⑤ 소속상급해양경찰관서장은 제3항의 결정을 한 날부터 7일 이내에 별지 제109호서식의 수사중지사건 이의처리결과 통지서에 처리 결과와 그 이유를 적어 이의를 제기한 사람에게 통지해야 한다.', 450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (691, '⑥ 사법경찰관은 제1항부터 제4항까지의 규정에 따른 절차의 진행 중에 수사준칙 제51조제4항 후단에 따라 검사의 시정조치요구를 받은 경우에는 지체 없이 소속상급해양경찰관서장에게 보고해야 한다.', 450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (692, '① 사법경찰관은 수사중지된 사건의 피의자를 발견하는 등 수사중지 사유가 해소된 때에는 별지 제110호서식의 수사중지사건 수사재개서를 작성하여 사건기록에 편철하고 즉시 수사를 진행해야 한다.', 451);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (693, '② 사법경찰관은 수사준칙 제51조제5항 전단에 따라 피의자 등의 소재 발견 및 수사 재개 사실을 검사에게 통보하는 경우에는 별지 제111호서식의 피의자 등 소재발견 통보서에 따른다.', 451);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (694, '① 수사준칙 제58조제1항에 따른 송치 결정서는 별지 제112호서식에 따르고, 압수물 총목록은 별지 제113호서식에 따르며, 기록목록은 별지 제114호서식에 따른다.', 452);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (695, '② 송치 서류는 다음 순서에 따라 편철한다.', 452);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (696, '③ 수사준칙 제58조에 따라 사건을 송치하는 경우에는 소속해양경찰관서장 또는 소속수사부서장의 명의로 한다.', 452);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (697, '④ 제1항의 송치 결정서는 사법경찰관이 작성해야 한다.', 452);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (698, '① 사법경찰관은 법 제197조의2제2항에 따라 보완수사 이행 결과를 통보하는 경우에는 별지 제117호서식의 보완수사 결과 통보서에 따른다. 다만, 수사준칙 제59조에 따른 보완수사요구의 대상이 아니거나 그 범위를 벗어난 경우 등 정당한 이유가 있어 보완수사를 이행하지 않은 경우에는 그 내용과 사유를 보완수사 결과 통보서에 적어 검사에게 통보해야 한다.', 454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (699, '② 사법경찰관은 법 제197조의2제1항제1호에 따른 보완수사요구 결과를 통보하면서 새로운 증거물, 서류 및 그 밖의 자료를 검사에게 송부하는 경우에는 수사준칙 제58조제3항에 따른다.', 454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (700, '③ 사법경찰관은 법 제197조의2제1항제2호에 따른 보완수사요구를 이행한 경우에는 다음 각 호의 구분에 따라 처리한다.', 454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (701, '④ 사법경찰관은 수사준칙 제60조제5항에 따라 사건을 불송치하거나 수사중지하는 경우에는 기존 송치 결정을 취소해야 한다. <개정 2024.6.19>', 454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (702, '① 소속해양경찰관서장은 수사준칙 제61조제2항에 따라 직무배제를 하는 경우 지체 없이 사건 담당 사법경찰관리를 교체해야 한다.', 455);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (703, '② 소속해양경찰관서장은 수사준칙 제61조제3항에 따라 직무배제 또는 징계 요구의 처리 결과와 그 이유를 통보하는 경우에는 별지 제118호서식의 직무배제요구 처리결과 통보서 또는 별지 제87호서식의 징계요구 처리결과 통보서에 따른다.', 455);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (704, '① 해양경찰서장은 「소년법」 제4조제2항에 따라 소년 보호사건을 법원에 송치하는 경우에는 별지 제119호서식의 소년 보호사건 송치서를 작성하여 사건기록에 편철하고 관계 서류와 증거물을 관할 가정법원 소년부 또는 지방법원 소년부에 송부해야 한다.', 456);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (705, '② 제1항의 송치 서류에 관하여는 제105조를 준용한다.', 456);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (706, '① 불송치 결정의 주문(主文)은 다음과 같이 한다. <개정 2024.6.19>', 457);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (707, '② 사법경찰관은 압수물의 환부 또는 가환부를 받을 사람이 없는 등 특별한 사유가 있는 경우를 제외하고는 제1항에 따른 결정을 하기 전에 압수물 처분을 완료하도록 노력해야 한다. 수사준칙 제64조제1항제2호에 따라 재수사 결과를 처리하는 경우에도 또한 같다.', 457);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (708, '① 수사준칙 제62조제1항에 따른 불송치 결정서는 별지 제120호서식에 따르고, 압수물 총목록은 별지 제113호서식에 따르며, 기록목록은 별지 제114호서식에 따른다.', 458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (709, '② 불송치 서류는 다음 순서에 따라 편철한다.', 458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (710, '③ 불송치 사건기록 송부서 명의인 및 불송치 결정서 작성인에 관하여는 제105조제3항 및 제4항을 준용한다.', 458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (711, '① 하나의 사건에 수사준칙 제51조제1항제2호부터 제4호까지의 규정에 따른 검찰송치, 불송치 및 수사중지 결정이 병존하는 병존사건의 경우 사법경찰관은 기록을 분리하여 송치 및 송부하도록 노력해야 한다.', 459);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (712, '② 제1항에도 불구하고 기록을 분리할 수 없는 경우에 사법경찰관은 관계 서류와 증거물을 원본과 다름이 없음을 인증하여 등사 보관하고 송치 결정서, 불송치 결정서 및 수사중지 결정서를 작성하여 그 결정서별로 압수물 총목록과 기록목록 등을 첨부한 후 각 별책으로 편철하여 관계 서류와 증거물 원본과 함께 검사에게 송치 및 송부한다.', 459);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (713, '③ 검사가 제2항에 따라 송치 및 송부된 사건을 공소제기(수사준칙 제52조제1항제7호에 따른 이송 중 타 기관 이송 및 같은 항 제8호부터 제11호까지의 규정에 따른 사건송치 결정을 포함한다)한 이후, 사법경찰관이 고소인등의 이의신청에 따라 사건을 송치하거나 수사중지 사건을 재개수사하여 송치 또는 송부할 때에는 추가된 새로운 증거물, 관계 서류와 함께 제2항의 관계 서류와 증거물 등본 중 관련 부분을 검사에게 송부해야 한다. 다만, 고소인등의 이의신청이나 수사중지 사건의 재개에 따라 불송치하거나 수사중지 결정한 부분을 모두 송치 또는 송부하는 경우에는 등본 전체를 검사에게 송부해야 한다.', 459);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (714, '① 사법경찰관은 수사준칙 제64조제1항제1호에 따라 사건을 송치하는 경우에는 기존 불송치 결정을 취소해야 한다.', 461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (715, '② 사법경찰관은 수사준칙 제64조제2항 단서에 따라 사건을 송치하는 경우에는 기존 불송치 결정을 변경해야 한다.', 461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (716, '③ 수사준칙 제64조제1항제2호에 따른 재수사 결과서는 별지 제122호서식에 따른다.', 461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (717, '① 법 제245조의7제1항에 따른 이의신청은 별지 제123호서식의 불송치 결정 이의신청서에 따른다.', 462);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (718, '② 사법경찰관은 제1항의 이의신청이 있는 경우 지체 없이 수사준칙 제58조제1항에 따라 사건을 송치한다. 이 경우 관계 서류와 증거물을 검사가 보관하는 경우(제112조제3항을 적용받는 경우는 제외한다)에는 관계 서류 및 증거물을 송부하지 않고 사건송치서 및 송치 결정서만으로 사건을 송치한다.', 462);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (719, '③ 사법경찰관은 법 제245조의7제2항에 따라 신청인에게 통지하는 경우에는 서면, 전화, 팩스, 전자우편, 문자메시지 등 신청인이 요청한 방법으로 통지할 수 있으며, 별도로 요청한 방법이 없는 경우에는 서면 또는 문자메시지로 한다. 이 경우 서면으로 하는 통지는 별지 제124호서식의 이의신청에 따른 사건송치 통지서에 따른다.', 462);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (720, '④ 사법경찰관은 법 제245조의7제2항에 따라 사건을 송치하는 경우에는 기존 불송치 결정을 변경해야 한다.', 462);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (721, null, 464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (722, null, 465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (723, '① 사법경찰관은 스토킹행위 신고와 관련하여 스토킹행위가 지속적 또는 반복적으로 행하여질 우려가 있고 스토킹범죄의 예방을 위하여 긴급을 요하는 경우 스토킹행위자에게 직권으로 또는 스토킹행위의 상대방이나 그 법정대리인 또는 스토킹행위를 신고한 사람의 요청에 의하여 다음 각 호에 따른 조치를 할 수 있다. <개정 2023.7.11>', 466);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (724, '② 사법경찰관은 제1항에 따른 조치(이하 "긴급응급조치"라 한다)를 하였을 때에는 즉시 스토킹행위의 요지, 긴급응급조치가 필요한 사유, 긴급응급조치의 내용 등이 포함된 긴급응급조치결정서를 작성하여야 한다.', 466);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (725, '① 사법경찰관은 긴급응급조치를 하였을 때에는 지체 없이 검사에게 해당 긴급응급조치에 대한 사후승인을 지방법원 판사에게 청구하여 줄 것을 신청하여야 한다.', 467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (726, '② 제1항의 신청을 받은 검사는 긴급응급조치가 있었던 때부터 48시간 이내에 지방법원 판사에게 해당 긴급응급조치에 대한 사후승인을 청구한다. 이 경우 제4조제2항에 따라 작성된 긴급응급조치결정서를 첨부하여야 한다.', 467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (727, '③ 지방법원 판사는 스토킹행위가 지속적 또는 반복적으로 행하여지는 것을 예방하기 위하여 필요하다고 인정하는 경우에는 제2항에 따라 청구된 긴급응급조치를 승인할 수 있다.', 467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (728, '④ 사법경찰관은 검사가 제2항에 따라 긴급응급조치에 대한 사후승인을 청구하지 아니하거나 지방법원 판사가 제2항의 청구에 대하여 사후승인을 하지 아니한 때에는 즉시 그 긴급응급조치를 취소하여야 한다.', 467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (729, '⑤ 긴급응급조치기간은 1개월을 초과할 수 없다.', 467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (730, '① 사법경찰관은 긴급응급조치를 하는 경우에는 스토킹행위의 상대방등이나 그 법정대리인에게 통지하여야 한다. <개정 2023.7.11>', 468);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (731, '② 사법경찰관은 긴급응급조치를 하는 경우에는 해당 긴급응급조치의 대상자(이하 "긴급응급조치대상자"라 한다)에게 조치의 내용 및 불복방법 등을 고지하여야 한다.', 468);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (732, '① 긴급응급조치대상자나 그 법정대리인은 긴급응급조치의 취소 또는 그 종류의 변경을 사법경찰관에게 신청할 수 있다.', 469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (733, '② 스토킹행위의 상대방등이나 그 법정대리인은 제4조제1항제1호의 긴급응급조치가 있은 후 스토킹행위의 상대방등이 주거등을 옮긴 경우에는 사법경찰관에게 긴급응급조치의 변경을 신청할 수 있다. <개정 2023.7.11>', 469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (734, '③ 스토킹행위의 상대방이나 그 법정대리인은 긴급응급조치가 필요하지 아니한 경우에는 사법경찰관에게 해당 긴급응급조치의 취소를 신청할 수 있다.', 469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (735, '④ 사법경찰관은 정당한 이유가 있다고 인정하는 경우에는 직권으로 또는 제1항부터 제3항까지의 규정에 따른 신청에 의하여 해당 긴급응급조치를 취소할 수 있고, 지방법원 판사의 승인을 받아 긴급응급조치의 종류를 변경할 수 있다.', 469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (736, '⑤ 사법경찰관은 제4항에 따라 긴급응급조치를 취소하거나 그 종류를 변경하였을 때에는 스토킹행위의 상대방등 및 긴급응급조치대상자 등에게 다음 각 호의 구분에 따라 통지 또는 고지하여야 한다. <신설 2023.7.11>', 469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (737, '⑥ 긴급응급조치(제4항에 따라 그 종류를 변경한 경우를 포함한다. 이하 이 항에서 같다)는 다음 각 호의 어느 하나에 해당하는 때에 그 효력을 상실한다. <개정 2023.7.11>', 469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (738, '① 검사는 스토킹범죄가 재발될 우려가 있다고 인정하면 직권 또는 사법경찰관의 신청에 따라 법원에 제9조제1항 각 호의 조치를 청구할 수 있다.', 470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (739, '② 피해자 또는 그 법정대리인은 검사 또는 사법경찰관에게 제1항에 따른 조치의 청구 또는 그 신청을 요청하거나, 이에 관하여 의견을 진술할 수 있다.', 470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (740, '③ 사법경찰관은 제2항에 따른 신청 요청을 받고도 제1항에 따른 신청을 하지 아니하는 경우에는 검사에게 그 사유를 보고하여야 하고, 피해자 또는 그 법정대리인에게 그 사실을 지체 없이 알려야 한다. <개정 2023.7.11>', 470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (741, '④ 검사는 제2항에 따른 청구 요청을 받고도 제1항에 따른 청구를 하지 아니하는 경우에는 피해자 또는 그 법정대리인에게 그 사실을 지체 없이 알려야 한다. <신설 2023.7.11>', 470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (742, '① 법원은 스토킹범죄의 원활한 조사ㆍ심리 또는 피해자 보호를 위하여 필요하다고 인정하는 경우에는 결정으로 스토킹행위자에게 다음 각 호의 어느 하나에 해당하는 조치(이하 "잠정조치"라 한다)를 할 수 있다. <개정 2023.7.11>', 471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (743, '② 제1항 각 호의 잠정조치는 병과(倂科)할 수 있다.', 471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (744, '③ 법원은 제1항제3호의2 또는 제4호의 조치에 관한 결정을 하기 전 잠정조치의 사유를 판단하기 위하여 필요하다고 인정하는 때에는 검사, 스토킹행위자, 피해자, 기타 참고인으로부터 의견을 들을 수 있다. 의견을 듣는 방법과 절차, 그 밖에 필요한 사항은 대법원규칙으로 정한다. <신설 2023.7.11>', 471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (745, '④ 제1항제3호의2에 따라 전자장치가 부착된 사람은 잠정조치기간 중 전자장치의 효용을 해치는 다음 각 호의 행위를 하여서는 아니된다. <신설 2023.7.11>', 471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (746, '⑤ 법원은 잠정조치를 결정한 경우에는 검사와 피해자 또는 그의 동거인, 가족, 그 법정대리인에게 통지하여야 한다. <개정 2023.7.11>', 471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (747, '⑥ 법원은 제1항제4호에 따른 잠정조치를 한 경우에는 스토킹행위자에게 변호인을 선임할 수 있다는 것과 제12조에 따라 항고할 수 있다는 것을 고지하고, 다음 각 호의 구분에 따른 사람에게 해당 잠정조치를 한 사실을 통지하여야 한다. <개정 2023.7.11>', 471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (748, '⑦ 제1항제2호ㆍ제3호 및 제3호의2에 따른 잠정조치기간은 3개월, 같은 항 제4호에 따른 잠정조치기간은 1개월을 초과할 수 없다. 다만, 법원은 피해자의 보호를 위하여 그 기간을 연장할 필요가 있다고 인정하는 경우에는 결정으로 제1항제2호ㆍ제3호 및 제3호의2에 따른 잠정조치에 대하여 두 차례에 한정하여 각 3개월의 범위에서 연장할 수 있다. <개정 2023.7.11>', 471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (749, '① 법원은 잠정조치 결정을 한 경우에는 법원공무원, 사법경찰관리, 구치소 소속 교정직공무원 또는 보호관찰관으로 하여금 집행하게 할 수 있다. <개정 2023.7.11>', 472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (750, '② 제1항에 따라 잠정조치 결정을 집행하는 사람은 스토킹행위자에게 잠정조치의 내용, 불복방법 등을 고지하여야 한다.', 472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (751, '③ 피해자 또는 그의 동거인, 가족, 그 법정대리인은 제9조제1항제2호의 잠정조치 결정이 있은 후 피해자 또는 그의 동거인, 가족이 주거등을 옮긴 경우에는 법원에 잠정조치 결정의 변경을 신청할 수 있다. <개정 2023.7.11>', 472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (752, '④ 제3항의 신청에 따른 변경 결정의 스토킹행위자에 대한 고지에 관하여는 제2항을 준용한다. <신설 2023.7.11>', 472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (753, '⑤ 제1항부터 제4항까지에서 규정한 사항 외에 제9조제1항제3호의2에 따른 잠정조치 결정의 집행 등에 관하여는 「전자장치 부착 등에 관한 법률」 제5장의2에 따른다. <신설 2023.7.11>', 472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (754, '① 스토킹행위자나 그 법정대리인은 잠정조치 결정의 취소 또는 그 종류의 변경을 법원에 신청할 수 있다.', 473);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (755, '② 검사는 수사 또는 공판과정에서 잠정조치가 계속 필요하다고 인정하는 경우에는 직권이나 사법경찰관의 신청에 따라 법원에 해당 잠정조치기간의 연장 또는 그 종류의 변경을 청구할 수 있고, 잠정조치가 필요하지 아니하다고 인정하는 경우에는 직권이나 사법경찰관의 신청에 따라 법원에 해당 잠정조치의 취소를 청구할 수 있다. <개정 2023.7.11>', 473);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (756, '③ 법원은 정당한 이유가 있다고 인정하는 경우에는 직권 또는 제1항의 신청이나 제2항의 청구에 의하여 결정으로 해당 잠정조치의 취소, 기간의 연장 또는 그 종류의 변경을 할 수 있다.', 473);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (757, '④ 법원은 제3항에 따라 잠정조치의 취소, 기간의 연장 또는 그 종류의 변경을 하였을 때에는 검사와 피해자 및 스토킹행위자 등에게 다음 각 호의 구분에 따라 통지 또는 고지하여야 한다. <신설 2023.7.11>', 473);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (758, '⑤ 잠정조치 결정(제3항에 따라 잠정조치기간을 연장하거나 그 종류를 변경하는 결정을 포함한다. 이하 제12조 및 제14조에서 같다)은 스토킹행위자에 대해 검사가 불기소처분을 한 때 또는 사법경찰관이 불송치결정을 한 때에 그 효력을 상실한다. <개정 2023.7.11>', 473);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (759, '① 검사, 스토킹행위자 또는 그 법정대리인은 긴급응급조치 또는 잠정조치에 대한 결정이 다음 각 호의 어느 하나에 해당하는 경우에는 항고할 수 있다.', 474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (760, '② 제1항에 따른 항고는 그 결정을 고지받은 날부터 7일 이내에 하여야 한다.', 474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (761, '① 제12조에 따른 항고를 할 때에는 원심법원에 항고장을 제출하여야 한다.', 475);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (762, '② 항고장을 받은 법원은 3일 이내에 의견서를 첨부하여 기록을 항고법원에 보내야 한다.', 475);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (763, '① 항고법원은 항고의 절차가 법률에 위반되거나 항고가 이유 없다고 인정하는 경우에는 결정으로 항고를 기각(棄却)하여야 한다.', 476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (764, '② 항고법원은 항고가 이유 있다고 인정하는 경우에는 원결정(原決定)을 취소하고 사건을 원심법원에 환송하거나 다른 관할법원에 이송하여야 한다. 다만, 환송 또는 이송하기에 급박하거나 그 밖에 필요하다고 인정할 때에는 원결정을 파기하고 스스로 적절한 잠정조치 결정을 할 수 있다.', 476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (765, '① 항고의 기각 결정에 대해서는 그 결정이 법령에 위반된 경우에만 대법원에 재항고를 할 수 있다.', 477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (766, '② 제1항에 따른 재항고의 기간, 재항고장의 제출 및 재항고의 재판에 관하여는 제12조제2항, 제13조 및 제14조를 준용한다.', 477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (767, '① 검찰총장은 각 지방검찰청 검사장에게 스토킹범죄 전담 검사를 지정하도록 하여 특별한 사정이 없으면 스토킹범죄 전담 검사가 피해자를 조사하게 하여야 한다.', 479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (768, '② 경찰관서의 장(국가수사본부장, 시ㆍ도경찰청장 및 경찰서장을 의미한다. 이하 같다)은 스토킹범죄 전담 사법경찰관을 지정하여 특별한 사정이 없으면 스토킹범죄 전담 사법경찰관이 피해자를 조사하게 하여야 한다.', 479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (769, '③ 검찰총장 및 경찰관서의 장은 제1항의 스토킹범죄 전담 검사 및 제2항의 스토킹범죄 전담 사법경찰관에게 스토킹범죄의 수사에 필요한 전문지식과 피해자 보호를 위한 수사방법 및 수사절차 등에 관한 교육을 실시하여야 한다.', 479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (770, '① 다음 각 호의 어느 하나에 해당하는 업무를 담당하거나 그에 관여하는 공무원 또는 그 직에 있었던 사람은 피해자등의 주소, 성명, 나이, 직업, 학교, 용모, 인적사항, 사진 등 피해자등을 특정하여 파악할 수 있게 하는 정보 또는 피해자등의 사생활에 관한 비밀을 공개하거나 다른 사람에게 누설하여서는 아니 된다.', 481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (771, '② 누구든지 피해자등의 동의를 받지 아니하고 피해자등의 주소, 성명, 나이, 직업, 학교, 용모, 인적 사항, 사진 등 피해자등을 특정하여 파악할 수 있게 하는 정보를 신문 등 인쇄물에 싣거나 「방송법」 제2조제1호에 따른 방송 또는 정보통신망을 통하여 공개하여서는 아니 된다.', 481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (772, '① 피해자 및 그 법정대리인은 형사절차상 입을 수 있는 피해를 방어하고 법률적 조력을 보장받기 위하여 변호사를 선임할 수 있다.', 482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (773, '② 제1항에 따라 선임된 변호사(이하 이 조에서 "변호사"라 한다)는 검사 또는 사법경찰관의 피해자 및 그 법정대리인에 대한 조사에 참여하여 의견을 진술할 수 있다. 다만, 조사 도중에는 검사 또는 사법경찰관의 승인을 받아 의견을 진술할 수 있다.', 482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (774, '③ 변호사는 피의자에 대한 구속 전 피의자심문, 증거보전절차, 공판준비기일 및 공판절차에 출석하여 의견을 진술할 수 있다. 이 경우 필요한 절차에 관한 구체적 사항은 대법원규칙으로 정한다.', 482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (775, '④ 변호사는 증거보전 후 관계 서류나 증거물, 소송계속 중의 관계 서류나 증거물을 열람하거나 복사할 수 있다.', 482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (776, '⑤ 변호사는 형사절차에서 피해자 및 법정대리인의 대리가 허용될 수 있는 모든 소송행위에 대한 포괄적인 대리권을 가진다.', 482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (777, '⑥ 검사는 피해자에게 변호사가 없는 경우 국선변호사를 선정하여 형사절차에서 피해자의 권익을 보호할 수 있다.', 482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (778, '① 스토킹범죄를 저지른 사람은 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.', 483);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (779, '② 흉기 또는 그 밖의 위험한 물건을 휴대하거나 이용하여 스토킹범죄를 저지른 사람은 5년 이하의 징역 또는 5천만원 이하의 벌금에 처한다.', 483);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (780, '③ 삭제 <2023.7.11>', 483);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (781, '① 법원은 스토킹범죄를 저지른 사람에 대하여 유죄판결(선고유예는 제외한다)을 선고하거나 약식명령을 고지하는 경우에는 200시간의 범위에서 다음 각 호의 구분에 따라 재범 예방에 필요한 수강명령(「보호관찰 등에 관한 법률」에 따른 수강명령을 말한다. 이하 같다) 또는 스토킹 치료프로그램의 이수명령(이하 "이수명령"이라 한다)을 병과할 수 있다.', 484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (782, '② 법원은 스토킹범죄를 저지른 사람에 대하여 형의 집행을 유예하는 경우에는 제1항에 따른 수강명령 외에 그 집행유예기간 내에서 보호관찰 또는 사회봉사 중 하나 이상의 처분을 병과할 수 있다.', 484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (783, '③ 제1항에 따른 수강명령 또는 이수명령의 내용은 다음 각 호와 같다.', 484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (784, '④ 제1항에 따른 수강명령 또는 이수명령은 다음 각 호의 구분에 따라 각각 집행한다.', 484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (785, '⑤ 제1항에 따른 수강명령 또는 이수명령이 벌금형 또는 형의 집행유예와 병과된 경우에는 보호관찰소의 장이 집행하고, 징역형의 실형과 병과된 경우에는 교정시설의 장이 집행한다. 다만, 징역형의 실형과 병과된 이수명령을 모두 이행하기 전에 석방 또는 가석방되거나 미결구금일수 산입 등의 사유로 형을 집행할 수 없게 된 경우에는 보호관찰소의 장이 남은 이수명령을 집행한다.', 484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (786, '⑥ 형벌에 병과하는 보호관찰, 사회봉사, 수강명령 또는 이수명령에 관하여 이 법에서 규정한 사항 외에는 「보호관찰 등에 관한 법률」을 준용한다.', 484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (787, '① 다음 각 호의 어느 하나에 해당하는 사람은 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다. <신설 2023.7.11>', 485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (788, '② 제9조제1항제2호 또는 제3호의 잠정조치를 이행하지 아니한 사람은 2년 이하의 징역 또는 2천만원 이하의 벌금에 처한다. <개정 2023.7.11>', 485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (789, '③ 긴급응급조치(검사가 제5조제2항에 따른 긴급응급조치에 대한 사후승인을 청구하지 아니하거나 지방법원 판사가 같은 조 제3항에 따른 승인을 하지 아니한 경우는 제외한다)를 이행하지 아니한 사람은 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <신설 2023.7.11>', 485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (790, '④ 제19조제1항에 따라 이수명령을 부과받은 후 정당한 사유 없이 보호관찰소의 장 또는 교정시설의 장의 이수명령 이행에 관한 지시에 따르지 아니하여 「보호관찰 등에 관한 법률」 또는 「형의 집행 및 수용자의 처우에 관한 법률」에 따른 경고를 받은 후 다시 정당한 사유 없이 이수명령 이행에 관한 지시를 따르지 아니한 경우에는 다음 각 호에 따른다. <신설 2023.7.11>', 485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (791, '① 검사 또는 사법경찰관리는 다음 각 호의 사무(그 사무를 수행하기 위하여 부수적으로 필요한 사무를 포함한다)를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호에 따른 유전정보, 같은 조 제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (792, '② 사법경찰관은 법 제6조에 따른 긴급응급조치의 통지 및 고지에 관한 사무(그 사무를 수행하기 위하여 부수적으로 필요한 사무를 포함한다)를 수행하기 위하여 불가피한 경우 「개인정보 보호법 시행령」 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (793, '③ 보호관찰소의 장, 교정시설의 장 또는 보호관찰관은 법 제19조에 따른 수강명령 또는 이수명령의 집행에 관한 사무(그 사무를 수행하기 위하여 부수적으로 필요한 사무를 포함한다)를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (794, null, 492);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (795, '① 국가와 지방자치단체는 스토킹의 예방ㆍ방지와 피해자의 보호ㆍ지원을 위하여 다음 각 호의 조치를 하여야 한다.', 493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (796, '② 국가와 지방자치단체는 제1항에 따른 책무를 다하기 위하여 이에 따른 예산상의 조치를 하여야 한다.', 493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (797, '① 여성가족부장관은 3년마다 스토킹에 대한 실태조사를 실시하여 그 결과를 발표하고, 이를 스토킹 방지를 위한 정책수립의 기초자료로 활용하여야 한다.', 494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (798, '② 제1항에 따른 실태조사의 내용과 방법 등에 관하여 필요한 사항은 대통령령으로 정한다.', 494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (799, '① 국가기관, 지방자치단체, 「초ㆍ중등교육법」에 따른 각급 학교 및 대통령령으로 정하는 공공단체의 장은 스토킹의 예방과 방지를 위하여 필요한 교육을 실시할 수 있다. 다만, 수사기관의 장은 사건 담당자 등 업무 관련자를 대상으로 필요한 교육을 실시하여야 한다.', 495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (800, '② 제1항에 따라 스토킹 예방교육을 실시하는 경우 「가정폭력방지 및 피해자보호 등에 관한 법률」 제4조의3에 따른 가정폭력 예방교육, 「성매매방지 및 피해자보호 등에 관한 법률」 제5조에 따른 성매매 예방교육, 「성폭력방지 및 피해자보호 등에 관한 법률」 제5조에 따른 성교육 및 성폭력 예방교육, 「양성평등기본법」 제31조에 따른 성희롱 예방교육 등을 성평등 관점에서 통합하여 실시할 수 있다.', 495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (801, '③ 국가기관, 지방자치단체의 장 및 대통령령으로 정하는 공공단체의 장은 스토킹 방지를 위한 자체 예방지침 마련, 사건 발생 시 재발방지대책 수립ㆍ시행 등 필요한 대책을 마련하여야 한다.', 495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (802, '④ 「양성평등기본법」 제3조제3호에 따른 사용자는 스토킹 예방교육을 실시하는 등 직장 내 스토킹 예방을 위한 노력을 하여야 한다.', 495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (803, '⑤ 여성가족부장관은 제1항에 따른 교육의 확산을 위하여 교육에 필요한 자료 또는 프로그램을 개발ㆍ보급하여야 한다.', 495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (804, '⑥ 제3항에 따른 재발방지대책에 포함되어야 할 사항은 대통령령으로 정한다.', 495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (805, '① 피해자 또는 스토킹 사실을 신고한 자를 고용하고 있는 자는 피해자 또는 스토킹 사실을 신고한 자에게 스토킹으로 피해를 입은 것 또는 신고를 한 것을 이유로 다음 각 호의 어느 하나에 해당하는 불이익조치를 하여서는 아니 된다.', 496);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (806, '② 피해자를 고용하고 있는 자는 피해자의 요청이 있으면 업무 연락처 및 근무 장소의 변경, 배치 전환 등의 적절한 조치를 할 수 있다.', 496);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (807, '① 국가나 지방자치단체는 피해자나 그 가족구성원(이하 "피해자등"이라 한다)이 「초ㆍ중등교육법」에 따른 각급 학교의 학생인 경우로서 주소지 외의 지역에서 취학(입학ㆍ재입학ㆍ전학 및 편입학을 포함한다. 이하 같다)할 필요가 있는 경우에는 그 취학이 원활히 이루어지도록 지원하여야 한다.', 497);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (808, '② 제1항에 따른 취학 지원에 필요한 사항은 대통령령으로 정한다.', 497);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (809, '① 국가나 지방자치단체는 피해자등의 보호ㆍ지원과 효과적인 피해 방지를 위하여 피해자 지원시설(이하 "지원시설"이라 한다)을 설치ㆍ운영할 수 있다.', 498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (810, '② 여성가족부장관이나 지방자치단체의 장은 지원시설의 설치ㆍ운영 업무를 대통령령으로 정하는 기관 또는 단체에 위탁할 수 있다.', 498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (811, '③ 여성가족부장관이나 지방자치단체의 장은 제2항에 따라 지원시설의 설치ㆍ운영 업무를 위탁하는 경우에는 그에 필요한 경비를 지원할 수 있다.', 498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (812, '④ 제1항에 따른 지원시설의 설치ㆍ운영 기준 등에 필요한 사항은 대통령령으로 정한다.', 498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (813, null, 499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (814, '① 다음 각 호의 어느 하나에 해당하는 사람은 지원시설의 장 또는 종사자가 될 수 없다.', 500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (815, '② 지원시설에서 종사하려는 사람은 전문 지식이나 경력 등 대통령령으로 정하는 자격기준을 갖추어야 한다.', 500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (816, '① 여성가족부장관이나 지방자치단체의 장은 지원시설 종사자의 자질을 향상시키기 위하여 필요한 교육을 실시하여야 한다.', 501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (817, '② 여성가족부장관이나 지방자치단체의 장은 대통령령으로 정하는 전문기관으로 하여금 제1항에 따른 교육 업무를 수행하게 할 수 있다.', 501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (818, '③ 제1항에 따른 교육의 시간ㆍ방법 및 내용 등에 관하여 필요한 사항은 대통령령으로 정한다.', 501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (819, '① 지원시설의 장은 스토킹행위자로부터 피해자등을 긴급히 구조할 필요가 있을 때에는 경찰관서(지구대ㆍ파출소 및 출장소를 포함한다)의 장에게 그 소속 직원의 동행을 요청할 수 있다.', 503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (820, '② 제1항에 따른 요청을 받은 경찰관서의 장은 특별한 사유가 없으면 그 요청에 따라야 한다.', 503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (821, '① 사법경찰관리는 스토킹의 신고가 접수된 때에는 지체 없이 신고된 현장에 출동하여야 한다.', 504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (822, '② 제1항에 따라 출동한 사법경찰관리는 신고된 현장 또는 사건조사를 위한 관련 장소에 출입하여 관계인에 대하여 조사를 하거나 질문을 할 수 있다.', 504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (823, '③ 제2항에 따라 출입, 조사 또는 질문을 하는 사법경찰관리는 그 권한을 표시하는 증표를 지니고 이를 관계인에게 내보여야 한다.', 504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (824, '④ 제2항에 따라 조사 또는 질문을 하는 사법경찰관리는 피해자ㆍ신고자ㆍ목격자 등이 자유롭게 진술할 수 있도록 스토킹행위자로부터 분리된 곳에서 조사하는 등 필요한 조치를 하여야 한다.', 504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (825, '⑤ 누구든지 정당한 사유 없이 제2항에 따른 사법경찰관리의 현장조사를 거부하는 등 그 업무 수행을 방해하는 행위를 하여서는 아니 된다.', 504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (826, '① 제6조제1항을 위반하여 신고자 또는 피해자에게 해고나 그 밖의 불이익조치를 한 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.', 506);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (827, '② 제15조에 따른 비밀 유지의 의무를 위반한 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 506);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (828, '① 제14조제5항을 위반하여 정당한 사유 없이 사법경찰관리의 업무 수행을 방해한 자에게는 1천만원 이하의 과태료를 부과한다.', 508);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (829, '② 제1항에 따른 과태료는 대통령령으로 정하는 바에 따라 여성가족부장관이나 지방자치단체의 장이 부과ㆍ징수한다.', 508);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (830, '① 「스토킹방지 및 피해자보호 등에 관한 법률」(이하 "법"이라 한다) 제4조제1항에 따른 스토킹에 대한 실태조사(이하 이 조에서 "실태조사"라 한다)에는 다음 각 호의 사항이 포함되어야 한다.', 510);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (831, '② 여성가족부장관은 실태조사를 스토킹에 관한 전문성과 인력ㆍ장비를 갖춘 연구기관ㆍ법인 또는 단체에 의뢰하여 실시할 수 있다.', 510);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (832, '① 법 제5조제1항 본문에서 "대통령령으로 정하는 공공단체"란 다음 각 호의 기관 또는 단체를 말한다.', 511);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (833, '② 법 제5조제3항에서 "대통령령으로 정하는 공공단체"란 다음 각 호의 기관 또는 단체를 말한다.', 511);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (834, '③ 국가기관, 지방자치단체의 장 및 제2항 각 호에 따른 공공단체의 장은 법 제5조제3항에 따라 스토킹 방지를 위한 자체 예방지침을 마련하는 경우 「성폭력방지 및 피해자보호 등에 관한 법률」 제5조제1항에 따른 자체 예방지침 및 「양성평등기본법」 제31조제1항에 따른 자체 예방지침과 통합하여 마련할 수 있다.', 511);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (835, '④ 법 제5조제3항에 따른 재발방지대책에는 다음 각 호의 사항이 포함되어야 한다.', 511);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (836, '⑤ 국가기관, 지방자치단체의 장 및 제2항 각 호에 따른 공공단체의 장은 법 제5조제3항에 따른 재발방지대책을 수립ㆍ시행하는 경우 스토킹이 「성폭력방지 및 피해자보호 등에 관한 법률」에 따른 성폭력 또는 「양성평등기본법」에 따른 성희롱과 결합된 사건인 경우에는 「성폭력방지 및 피해자보호 등에 관한 법률」 제5조제1항에 따른 재발방지대책 및 「양성평등기본법」 제31조제1항에 따른 재발방지대책과 통합하여 수립ㆍ시행할 수 있다.', 511);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (837, '① 법 제7조제1항에 따라 피해자나 그 가족구성원(이하 "피해자등"이라 한다)을 주소지 외의 지역에 취학(입학ㆍ재입학ㆍ전학 및 편입학을 포함한다. 이하 이 조에서 같다)시키려는 경우 다음 각 호의 절차에 따라야 한다.', 512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (838, '② 「초ㆍ중등교육법」 제2조에 따른 각급 학교의 장, 교육장 또는 교육감은 피해자등을 보호하기 위하여 제1항 각 호에 따라 조치한 사실이 취학 업무 관계자가 아닌 사람에게 공개되지 않도록 관리ㆍ감독해야 한다.', 512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (839, '③ 제1항에 따른 절차에 따라 취학에 걸린 기간은 피해자등의 출석일수에 산입한다.', 512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (840, null, 514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (841, '① 법 제11조제1항에 따른 교육은 지원시설의 장 및 상담원에 대하여 연간 8시간 이상 20시간 이하로 실시해야 한다. 이 경우 집합교육 또는 인터넷 강의 등의 방법으로 실시할 수 있다.', 517);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (842, '② 제1항에 따른 교육에는 다음 각 호의 내용을 포함해야 한다.', 517);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (843, '③ 법 제11조제2항에서 "대통령령으로 정하는 전문기관"이란 「양성평등기본법」 제46조의2에 따른 한국여성인권진흥원을 말한다.', 517);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (844, '① 국가기관, 지방자치단체의 장(해당 권한이 위임ㆍ위탁된 경우에는 그 권한을 위임ㆍ위탁받은 자를 포함한다) 또는 지원시설의 장은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법 시행령」 제19조제1호 또는 제4호에 따른 주민등록번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (845, '② 지원시설의 장은 법 제9조제5호에 따른 의료 지원 업무에 관한 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보가 포함된 자료를 처리할 수 있다.', 518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (846, null, 519);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (847, null, 522);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (848, '① 법 제5조에 따라 소년원을 다음 각 호와 같이 분류한다. <개정 2021.4.20, 2022.2.17>', 523);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (849, '② 제1항에 따른 소년원의 세부분류ㆍ운영기준은 법무부장관이 정한다.', 523);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (850, '①소년원장 또는 소년분류심사원장(이하 "원장"이라 한다)은 법 제7조 또는 법 제12조에 따라 보호소년등을 새로 수용할 때에는 법원소년부의 결정서, 법무부장관의 이송허가서 또는 지방법원 판사의 유치허가장을 통하여 본인임을 확인한 후 인수하고, 인도기관에 인수서를 내주어야 한다. <개정 2014.1.28, 2021.4.20>', 527);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (851, '② 보호관찰소의 장은 유치소년을 원장에게 인도할 때에는 원본과 대조ㆍ확인한 유치허가장 사본을 제출하여야 한다. <신설 2014.1.28>', 527);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (852, '① 원장은 법 제8조제1항에 따라 분류처우를 할 때에는 분류심사 결과와 법원소년부로부터 송부된 자료를 고려하여야 한다. <개정 2016.9.5>', 530);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (853, '② 원장은 법 제8조제2항에 따라 보호소년등을 분리수용하는 경우 비행, 공범관계, 처우과정 등을 고려하여 법무부령으로 정하는 바에 따라 생활실을 구분할 수 있다. <개정 2016.9.5>', 530);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (854, '① 소년원장은 제9조에 따른 분류처우 대상 보호소년에 대하여 법 제15조의2에 따른 보호소년등처우ㆍ징계위원회(이하 "처우ㆍ징계위원회"라 한다)의 심사를 거쳐 개별처우계획을 수립해야 한다. <개정 2021.4.20>', 531);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (855, '② 제1항에 따른 개별처우계획에는 초ㆍ중등교육, 직업능력개발훈련, 의료재활, 인성교육 등 개별 교육ㆍ처우의 방향이 제시돼야 한다. 이 경우 보호소년과 보호자등의 의견을 고려해야 한다. <개정 2021.4.20>', 531);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (856, '③ 제1항 및 제2항에 따라 수립된 개별처우계획은 교정교육에 지장이 없는 범위에서 그 내용을 본인 및 보호자등에게 알려 보호소년이 스스로 교육에 참여하고, 자기 개선을 위하여 노력하도록 하여야 한다.', 531);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (857, '① 원장은 법 제11조에 따른 청원서를 접수하면 지체 없이 이를 법무부장관에게 보내야 한다.', 534);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (858, '② 원장은 법 제11조에 따른 청원을 할 수 있다는 안내문을 보기 쉬운 곳에 게시하는 등 청원의 편의를 제공하여야 한다.', 534);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (859, '③ 원장은 보호소년등이 청원을 못하게 하거나 청원을 하였다는 이유로 불이익한 처우를 하여서는 아니 된다.', 534);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (860, '① 소년원장은 이송할 보호소년에 대하여 건강진단을 하고 건강상태가 이송해 갈 소년원의 교육활동에 적합하지 아니하다고 판명되면 이송을 중지하여야 한다.', 537);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (861, '② 소년원장은 다음 각 호의 어느 하나에 해당하는 보호소년을 다른 소년원으로 이송해서는 안 된다. <개정 2021.1.5, 2021.4.20>', 537);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (862, '③ 소년원장은 제2항에도 불구하고 처우상 특히 필요하다고 인정되는 사유가 있으면 처우ㆍ징계위원회의 심의를 거쳐 법무부장관의 허가를 받아 보호소년을 다른 소년원으로 이송할 수 있다. <개정 2021.4.20>', 537);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (863, null, 539);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (864, '① 원장은 시설의 안전과 질서 유지를 위하여 필요하다고 인정하는 경우에는 보호소년등의 신체ㆍ의류ㆍ휴대품ㆍ생활실 등을 검사할 수 있다.', 540);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (865, '② 원장은 보호소년등의 신체를 검사하는 경우에는 해당 보호소년등이 불필요한 고통이나 수치심을 느끼지 않도록 유의해야 하며, 특히 신체를 면밀히 검사할 필요가 있으면 다른 보호소년등이 볼 수 없는 차단된 장소에서 해야 한다. <개정 2021.4.20>', 540);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (866, '③ 원장은 여성인 보호소년등의 신체ㆍ의류 및 휴대품을 검사하는 경우에는 소속 여성 공무원이 하게 하여야 한다.', 540);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (867, '④ 원장은 제1항에 따라 검사한 결과 제17조의2에 따른 소지금지물품(이하 "금지물품"이라 한다)이 발견되면 이를 보호소년등에게 알린 후 폐기한다.', 540);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (868, '⑤ 제4항에도 불구하고 폐기하는 것이 적당하지 아니한 물품은 소년원등에 보관하거나 보호자등에게 전달할 수 있다. 이 경우 보관 물품의 처리는 법 제22조에 따른다. <개정 2021.4.20>', 540);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (869, '①원장은 소년원등에 출입하는 외부인의 출입 목적과 신원을 확인하고, 시설의 안전과 질서 유지를 위하여 필요하다고 인정하면 출입자의 의류와 휴대품을 검사할 수 있다. <개정 2014.1.28>', 541);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (870, '② 원장은 제1항에 따른 검사 결과 출입자가 금지물품을 소지하고 있으면 소년원등에 맡기게 하여야 하며, 이에 따르지 아니하면 출입을 금지할 수 있다. <신설 2014.1.28>', 541);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (871, '③ 원장은 여성 출입자의 의류 및 휴대품을 검사하는 경우에는 소속 여성 공무원이 하게 하여야 한다. <신설 2014.1.28>', 541);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (872, '① 원장은 보호소년등이 다음 각 호의 어느 하나에 해당할 때에는 의사의 의견을 고려하여 심신안정실(자살 및 자해 방지 등의 설비를 갖춘 생활실을 말한다. 이하 같다)에 수용할 수 있다. <개정 2016.9.5>', 542);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (873, '② 제1항제1호 및 제2호에 따른 심신안정실의 수용기간은 15일 이내로 한다. 다만, 원장은 특별히 계속하여 수용할 필요가 있으면 의사의 의견을 고려하여 7일을 초과하지 아니하는 범위에서 한 차례만 그 기간을 연장할 수 있다.', 542);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (874, '③ 제1항제3호 및 제4호에 따른 심신안정실 수용기간은 24시간 이내로 한다. 다만, 원장은 특별히 계속하여 수용할 필요가 있으면 의사의 의견을 고려하여 12시간을 초과하지 아니하는 범위에서 한 차례만 그 기간을 연장할 수 있다.', 542);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (875, '④ 원장은 보호소년등을 심신안정실에 수용하거나 그 수용기간을 연장하는 경우에는 그 사유를 본인에게 알려주어야 한다.', 542);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (876, '⑤ 원장은 의사 및 간호사로 하여금 심신안정실에 수용된 보호소년등의 건강상태를 수시로 확인하게 하여야 한다.', 542);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (877, '⑥ 원장은 심신안정실에 수용할 사유가 소멸하면 심신안정실 수용을 즉시 중단하여야 한다.', 542);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (878, '① 원장은 보호소년등의 사망, 이탈, 난동, 그 밖의 중대한 사고가 발생하면 지체 없이 법무부장관에게 보고하여야 한다.', 543);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (879, '② 원장은 조사ㆍ심리(審理)를 받고 있는 위탁소년 또는 항고 중의 보호소년이 사망하거나 이탈한 경우 또는 이탈한 보호소년등을 재수용한 경우에는 지체 없이 그 사실을 사건이 계류되어 있는 법원에 통지하여야 한다.', 543);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (880, '① 원장은 법 제15조에 따라 보호소년등을 징계할 때에는 다음 각 호의 사항을 고려하여야 한다. <개정 2014.1.28>', 548);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (881, '② 원장은 제1항에 따라 보호소년등을 징계할 때에는 증거에 의하여 징계 정도를 공정하게 정하고 교육적 효과를 고려하여야 한다.', 548);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (882, '① 보호소년등의 징계대상행위에 대한 조사기간(조사를 시작한 날부터 조사를 완료하여 처우ㆍ징계위원회 개최 통보를 한 날까지를 말한다. 이하 같다)은 7일 이내로 한다. 다만, 원장은 특별히 필요하다고 인정하는 경우에는 3일을 초과하지 아니하는 범위에서 한 차례만 그 기간을 연장할 수 있다. <개정 2021.4.20>', 549);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (883, '② 원장은 규율을 위반하여 징계가 필요하다고 의심할 만한 상당한 이유가 있는 보호소년등이 다음 각 호의 어느 하나에 해당하면 조사기간 중 분리하여 수용할 수 있다.', 549);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (884, '③ 제2항에 따른 분리수용기간은 징계기간에 포함한다.', 549);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (885, '④ 원장은 조사대상자의 질병이나 그 밖의 특별한 사정으로 조사를 계속하기 어려운 경우에는 그 사유가 없어질 때까지 조사를 일시적으로 정지할 수 있다. 이 경우 조사가 정지된 다음 날부터 정지사유가 소멸한 전날까지의 기간은 조사기간에 포함하지 아니한다.', 549);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (886, '⑤ 제1항부터 제4항까지에서 규정한 사항 외에 징계대상행위 조사에 관한 세부 사항은 법무부령으로 정한다.', 549);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (887, '① 원장은 보호소년등을 징계할 때에는 지도계획을 수립하여 시행하여야 한다.', 552);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (888, '② 원장은 징계 중인 보호소년등을 매주 1회 이상 면접하고 개별지도를 하여야 한다.', 552);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (889, '③ 원장은 징계 중인 보호소년등의 처우를 제한하는 경우에는 그 사실을 그 보호소년등의 가족이나 친지에게 알려야 한다.', 552);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (890, '④ 원장은 징계 중인 보호소년등에 대하여는 의사 및 간호사에게 수시로 건강진단을 하도록 하여야 한다.', 552);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (891, null, 556);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (892, '① 처우ㆍ징계위원회의 위원장(이하 "위원장"이라 한다)은 원장이 된다.', 557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (893, '② 처우ㆍ징계위원회의 위원(이하 "위원"이라 한다)은 다음 각 호에 해당하는 사람 중에서 위원장이 성별을 고려하여 임명하거나 위촉한다. 이 경우 의료재활소년원에 두는 처우ㆍ징계위원회의 위원에는 의무직공무원 및 간호직공무원이 포함돼야 한다.', 557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (894, '③ 「국가공무원법」 제33조 각 호에 해당하는 사람은 위원이 될 수 없다.', 557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (895, '④ 제2항에 따라 위촉된 위원의 임기는 2년으로 한다.', 557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (896, '① 위원이 다음 각 호의 어느 하나에 해당하는 경우에는 처우ㆍ징계위원회의 심의ㆍ의결에서 제척(除斥)된다.', 558);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (897, '② 해당 안건의 당사자는 위원에게 공정한 심의ㆍ의결을 기대하기 어려운 사정이 있는 경우에는 처우ㆍ징계위원회에 기피 신청을 할 수 있고, 처우ㆍ징계위원회는 의결로 기피 여부를 결정한다. 이 경우 기피 신청의 대상인 위원은 그 의결에 참여할 수 없다.', 558);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (898, '③ 위원이 제1항 각 호에 따른 제척사유나 제2항 전단에 따른 기피사유에 해당하는 경우에는 스스로 해당 안건의 심의ㆍ의결에서 회피해야 한다.', 558);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (899, '① 위원장은 처우ㆍ징계위원회를 대표하고, 처우ㆍ징계위원회의 업무를 총괄한다.', 559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (900, '② 위원장이 부득이한 사유로 직무를 수행할 수 없을 경우에는 위원장이 미리 지정한 위원이 그 직무를 대행한다.', 559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (901, '① 위원장은 다음 각 호의 어느 하나에 해당하는 경우에 처우ㆍ징계위원회의 회의를 소집한다.', 560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (902, '② 처우ㆍ징계위원회의 회의는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.', 560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (903, '③ 처우ㆍ징계위원회의 회의에 출석한 위원과 관계 전문가 등에게는 예산의 범위에서 수당과 여비, 그 밖에 필요한 경비를 지급할 수 있다. 다만, 공무원이 그 소관 업무와 직접 관련하여 출석하는 경우에는 지급하지 않는다.', 560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (904, null, 561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (905, '① 처우ㆍ징계위원회의 사무를 처리하기 위해 처우ㆍ징계위원회에 2명 이내의 간사를 둔다.', 562);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (906, '② 간사는 위원장이 해당 소년원등에 소속된 공무원 중에서 임명한다.', 562);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (907, '① 간사는 처우ㆍ징계위원회의 회의록을 작성ㆍ보관해야 한다.', 563);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (908, '② 제1항에 따른 회의록에는 위원장 및 출석위원이 서명 또는 날인해야 한다.', 563);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (909, '① 원장은 법 제16조제1항에 따라 선정된 보호소년등에게는 상장ㆍ상품 등을 주거나 그 밖의 포상을 할 수 있다.', 565);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (910, '② 원장은 제1항에 따라 포상을 받은 보호소년등에 대하여 제2조 각 호의 특별처우를 할 수 있다. <개정 2021.4.20>', 565);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (911, '① 원장은 교정교육이나 위생에 해가 없다고 인정되는 경우에만 보호자나 그 밖의 관계인으로부터 음식물ㆍ의류ㆍ학용품 등을 반입하도록 허가할 수 있다.', 567);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (912, '② 원장은 제1항에 따른 반입품이 유해한지를 검사하여야 한다.', 567);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (913, '① 보호소년등의 면회는 평일[원장이 필요하다고 인정하는 경우에는 토요일(공휴일은 제외한다)을 포함한다]에 교육 등 일과 진행에 지장이 없는 범위에서 1일 1회 40분 이내로 한다. 다만, 특별한 사유가 있을 때에는 그렇지 않다. <개정 2014.1.28, 2021.4.20>', 570);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (914, '② 제1항에 따른 면회의 장소ㆍ절차 등에 관하여 필요한 사항은 법무부령으로 정한다.', 570);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (915, null, 572);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (916, '① 원장은 법 제18조제4항에 따라 편지를 검사한 결과 다음 각 호의 어느 하나에 해당하는 경우에는 편지의 왕래를 제한할 수 있다. <개정 2016.9.5>', 573);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (917, '② 제1항에 따른 편지 왕래의 제한은 다음 각 호의 어느 하나에 해당하는 방법으로 한다.', 573);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (918, '③ 정보통신매체를 통한 편지의 제한에 관하여는 제1항 및 제2항을 준용한다.', 573);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (919, '① 원장은 전화통화 허가를 신청한 보호소년등에게 다음 각 호의 어느 하나에 해당하는 사유가 있는 경우에는 전화통화를 허가하지 않을 수 있다. <개정 2021.4.20>', 574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (920, '② 원장은 다음 각 호의 어느 하나에 해당하는 경우에는 보호소년등의 전화통화를 중지시킬 수 있다.', 574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (921, '③ 제2항에 따라 보호소년등의 전화통화를 중지시키려면 미리 보호소년등에게 경고하여야 하며, 전화통화를 중지시킬 경우 통화상대방에게도 그 사유를 알려야 한다.', 574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (922, '① 소년원장은 외출허가를 받은 보호소년에게 지켜야 할 사항을 부과하여야 한다.', 576);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (923, '② 소년원장은 보호소년이 준수사항을 위반하면 지체 없이 외출허가를 취소하고 복귀에 필요한 조치를 하여야 한다.', 576);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (924, '① 원장은 제42조에 따른 건강진단이나 정기ㆍ수시검진 결과 중한 질병이 있다는 사실을 알았거나, 외부 의료기관에서 입원ㆍ수술 등의 처치를 받아야 할 사유가 발생하면 지체 없이 그 사실을 법무부장관에게 보고하고 보호자등에게 알려야 한다. <개정 2021.4.20>', 578);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (925, '② 원장은 법 제20조제2항에 따라 보호소년등을 외부 의료기관에 입원시킨 경우에는 지체 없이 법무부장관에게 보고하여야 한다.', 578);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (926, null, 580);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (927, '① 원장은 보호소년등에 대한 예방접종과 방역소독 등 감염병 예방에 필요한 조치를 하여야 한다. <개정 2010.12.29>', 581);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (928, '② 원장은 감염병이 유행하고 있을 때에는 감염병 유행지역 거주자의 면회, 음식물ㆍ피복이나 그 밖의 물품의 반입을 금지할 수 있다. <개정 2010.12.29>', 581);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (929, '③ 원장은 보호소년등이 감염병에 감염되었다고 의심되는 경우에는 감염병의 증상 또는 전염력이 없어질 때까지 격리수용하고, 소지품에 대한 소독 등 필요한 조치를 하여야 한다. <개정 2010.12.29>', 581);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (930, '① 원장은 법 제22조제1항에 따라 보호소년등의 금품을 보관할 때에는 본인이 참여한 가운데 점검하고, 법무부령으로 정하는 보관금품 보관증(이하 "보관증"으로 한다)에 품명ㆍ수량ㆍ규격과 그 밖에 필요한 사항을 기재한 후 본인이 확인ㆍ서명하게 하여야 한다. 이 경우 보관증은 원장과 보호소년등이 각각 한 부씩 보관한다. <개정 2016.9.5>', 583);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (931, '② 제1항의 경우 보호소년등이 소지한 물품이 보관하기에 부적당하다고 인정되면 보호자등에게 반환하거나 본인의 승낙을 받아 매각하고 그 대금을 보관할 수 있다. 다만, 물품 중 가치가 없다고 인정되는 것은 본인이 폐기하게 할 수 있다.', 583);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (932, '③ 원장은 필요하다고 인정하면 보관한 물품을 보호소년등이 사용하게 할 수 있다.', 583);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (933, '① 법 제22조제2항에 따라 보관금품을 반환하는 때에는 보관증에 그 사유를 기재하고 수령인에게 확인ㆍ서명하도록 하여야 한다. <개정 2016.9.5>', 584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (934, '② 원장은 법 제22조제2항에도 불구하고 출원하는 보호소년등이 보관금품을 반환받기를 원하지 아니하면 반환하지 않을 수 있다.', 584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (935, '③ 제2항에 따라 보관금품을 반환하지 않을 때에는 보관증에 그 사유를 기재하고 해당 보호소년등에게 확인ㆍ서명하도록 하여야 한다. <개정 2016.9.5>', 584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (936, '① 원장은 소년원등에서 사용할 물품을 기증하려는 자가 있을 경우에는 보호와 교정교육에 필요한 물품만 기증받을 수 있다. <개정 2021.4.20>', 585);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (937, '② 원장은 기증자가 제1항의 물품 기증을 목적으로 현금을 기탁하는 경우에는 이를 접수하여 해당 물품을 대신 구입할 수 있다. 이 경우 관련 증빙서류를 첨부하여 기증자에게 알려야 한다.', 585);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (938, '① 법 제3조제2항제1호 및 제2호에 따른 분류심사를 할 때는 다음 각 호의 사항을 종합ㆍ분석해야 한다. <개정 2014.1.28, 2021.4.20>', 587);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (939, '② 제1항에 따른 분류심사를 할 때에는 각종 기록 및 상담 결과, 관계인과의 면접, 그 밖의 객관적인 자료를 토대로 하여야 한다.', 587);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (940, '① 법 제3조제2항제3호부터 제5호까지의 규정에 따른 상담조사, 검사의 결정 전 조사, 분류심사 업무를 할 때에는 의뢰기관이 요청한 영역에 대하여 실시한다. <개정 2014.1.28, 2021.4.20>', 588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (941, '② 법 제3조제2항제3호의 경우 소년의 진로지도 및 품행 개선을 위한 교육을 실시할 수 있다. 이 경우 상담조사 기간의 출석일수 인정 등에 관하여는 제85조를 준용한다. <개정 2014.1.28, 2021.4.20>', 588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (942, '① 분류심사관은 제51조에 따른 분류심사자료를 종합하여 분류심사서를 작성하여야 한다.', 589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (943, '② 소년분류심사원장은 분류심사관의 원활한 직무수행을 위하여 필요한 소양과 전문지식을 갖춘 분류심사 전문요원을 두고 제51조제1항 각 호의 자료수집과 심리검사 등을 하게 할 수 있다.', 589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (944, '① 법 제26조에 따라 심리검사 등을 요청하려는 사람은 소년분류심사원장에게 법무부장관이 정한 방법과 절차에 따라 심리검사를 의뢰하여야 한다.', 590);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (945, '② 소년분류심사원장은 제1항에 따른 청소년 심리검사 등을 의뢰받았을 때에는 심리검사 등의 일시와 장소, 그 밖에 필요한 사항 등 협조사항을 미리 알려야 한다.', 590);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (946, '① 소년원장은 보호소년이 정해진 교육기간에 교정목적을 달성할 수 있도록 법 제41조에 따른 교육계획을 수립하여 시행하여야 한다.', 591);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (947, '② 제1항에 따른 교육계획에는 교육과정, 특별활동 및 생활지도 등에 관한 구체적 내용이 포함되어야 한다.', 591);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (948, '① 교정교육은 보호소년이 소년원에 입원할 때부터 출원할 때까지의 전 과정을 신입자교육, 기본교육, 사회복귀교육의 3단계로 구분하여 순차적으로 실시해야 한다. <개정 2021.4.20>', 592);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (949, '② 제1항에 따른 단계별 교육에 관한 세부사항은 법무부령으로 정한다.', 592);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (950, '① 보호소년의 교정성적은 교육성과 및 생활성적을 종합하여 평가한다.', 593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (951, '② 그 밖에 보호소년의 교정성적 평가에 필요한 사항은 법무부장관이 정한다.', 593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (952, '① 원장은 보호소년등의 처우와 교정성적 관리를 적절하게 하기 위하여 개인별로 소년관리기록부를 갖추고 출원 시까지의 모든 상황을 정해진 양식에 따라 계속 기록ㆍ유지하여야 한다.', 594);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (953, '② 소년분류심사원장은 위탁소년, 유치소년 또는 법 제3조제2항제3호에 따른 상담조사 대상 소년이 법원소년부의 심리 결과 소년원 송치처분을 받게 된 때에는 지체 없이 그 소년의 소년관리기록부 원본을 해당 소년원에 송부해야 한다. <개정 2014.1.28, 2021.4.20>', 594);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (954, '① 법 제29조에 따른 소년원학교(이하 "소년원학교"라 한다)를 설치하는 경우에는 「초ㆍ중등교육법」에서 정하는 기준에 따라야 한다.', 595);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (955, '② 소년원학교의 원활한 운영과 소년보호 교육기관의 특성을 고려하여 "소년원"과 "소년원의 각급학교 명칭"을 함께 사용할 수 있다.', 595);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (956, '① 법 제30조제1항에 따라 임용된 소년원학교의 교원은 학생의 수업, 생활지도, 그 밖에 필요한 직무를 수행하여야 한다.', 597);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (957, '② 소년원학교장은 소년원학교 교육을 원활하게 하기 위하여 필요하다고 판단되면 법무부장관의 승인을 받아 관련 학과 학사학위 이상 소지자, 청소년상담사, 청소년지도사, 정보통신ㆍ어학 관련 국가공인 자격 소지자 등 정해진 자격요건을 갖춘 소속 공무원에게 제1항에 따른 직무를 담당하도록 할 수 있다.', 597);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (958, '① 법무부장관은 「교육공무원법」 및 「교원 등의 연수에 관한 규정」에서 정하는 바에 따라 소년원학교 교원을 각급학교의 교육연수원에서 연수하게 하거나 법무연수원에서 연수하게 해야 한다. <개정 2021.4.20>', 598);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (959, '② 소년원학교장은 제1항에 따른 연수대상자를 선발하려면 관할 교육감 또는 법무연수원장과 협의해야 한다. <개정 2021.4.20>', 598);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (960, '① 소년원학교장은 학년 초부터 60일 이내에 입교한 보호소년이 각급학교를 졸업하였거나 같은 수준 이상의 학력이 있다고 인정되는 경우에는 상급학교 교육과정에 입학시킬 수 있다.', 599);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (961, '② 소년원학교장은 보호소년이 학적을 가졌던 학년의 입교 당시 학기에 전학ㆍ편입학시킬 수 있다. 다만, 입교 당시 학기에 전학ㆍ편입학 시킬 수 없을 경우에는 같은 학년 이하의 학기에 전학ㆍ편입학시킬 수 있다.', 599);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (962, '③ 「소년법」 제32조제1항제8호에 따라 소년원에 송치된 소년에 대하여는 제1항 및 제2항을 적용하지 아니한다.', 599);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (963, '① 소년원학교장은 법 제31조제1항에 따라 보호소년이 편입학한 경우에는 편입학사항을 보호소년이 최종적으로 재학하였던 학교[이하 "전적학교(前籍學校)"라 한다]의 장에게 통지하여야 한다.', 602);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (964, '② 소년원학교장은 보호소년의 학적기록사항을 매 학기 또는 매 학년이 종료되기 이전까지 전적학교의 장에게 보내야 한다.', 602);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (965, '③ 소년원학교장은 보호소년이 출원하면 그 출원일부터 10일 이내에 학적기록 전부를 전적학교의 장에게 보내야 한다.', 602);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (966, '④ 전적학교의 장은 제1항부터 제3항까지의 규정에 따라 학적사항을 접수하면 이를 재학생에 준하여 관리하여야 한다.', 602);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (967, '① 소년원장은 보호소년이 수용으로 인하여 학교 입학ㆍ복학 또는 편입학에 지장을 줄 염려가 있는 경우에는 보호소년에게 준수사항을 부과하여 통학하도록 할 수 있다.', 604);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (968, '② 소년원장은 제1항에 따라 통학을 허가받은 보호소년이 통학기간 중 준수사항을 현저하게 위반하거나 통학을 계속해서는 아니 된다고 판단되는 사유가 있으면 통학허가를 취소할 수 있다.', 604);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (969, '① 소년원학교의 학년별 과정 이수 및 졸업 여부는 처우ㆍ징계위원회에서 다음 각 호의 사항을 심의하여 결정한다. <개정 2021.4.20>', 605);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (970, '② 제1항제2호에 따른 총 수업시간 수 또는 수업일수는 각 소년원학교별 수업시간수를 더하여 산정하되, 그 기간이 「초ㆍ중등교육법 시행령」 제50조제2항에 따른 기간을 넘으면 졸업요건을 충족한 것으로 본다.', 605);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (971, null, 607);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (972, '① 소년원의 직업능력개발훈련은 보호소년이 근로의 소중함을 깨닫고 직업에 대한 올바른 태도와 능력을 길러 건전한 직업생활을 할 수 있도록 하여야 한다.', 609);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (973, '② 소년원의 직업능력개발훈련은 학교교육 및 산업사회와 밀접한 관련을 갖도록 실시하여야 한다.', 609);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (974, '① 보호소년의 통근취업 대상 산업체는 소년원 출원 후 직업 선택이 쉽고 건전한 직업의식과 가치관을 기를 수 있는 업체로 선정해야 한다. <개정 2021.4.20>', 614);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (975, '② 소년원장은 법 제37조제1항에 따라 보호소년을 통근취업시키려면 통근취업 대상 산업체와 보수, 취업기간, 취업조건, 그 밖에 필요한 사항을 포함하는 취업약정서를 작성하여야 한다.', 614);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (976, '③ 소년원장은 통근취업을 하는 보호소년에게 준수사항을 부과하여 이를 지키도록 지도하여야 한다.', 614);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (977, '④ 소년원장은 산업체가 제2항의 취업약정사항을 위반하였을 때 또는 보호소년이 준수사항을 현저하게 위반하거나 통근취업을 계속하여서는 아니 된다고 판단되는 사유가 있을 때에는 통근취업을 금지할 수 있다.', 614);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (978, '① 원장은 보호소년등이 지닌 모든 문제와 그들의 욕구를 효과적으로 해소하여 교정목표를 조기에 달성할 수 있도록 체계적인 상담과 심리치료 등 인성교육을 하여야 한다.', 617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (979, '② 원장은 보호자등이 보호소년등의 처우 또는 개인 사정에 관하여 상담을 신청하면 이에 응하여야 한다.', 617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (980, '③ 원장은 제1항의 직무를 수행하기 위하여 해당 분야에 전문성과 소양을 갖춘 전담직원을 배치하거나 지정하여야 한다.', 617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (981, '① 원장은 법 제40조에 따라 보호소년등의 정서를 순화하고 특기를 살리기 위하여 적당한 특별활동에 참여하게 하여야 한다.', 618);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (982, '② 제1항에 따른 특별활동은 체육, 독서, 음악, 연극지도 등 교내 특별활동과 전시관 및 산업시설 견학, 문화유적지 답사, 문화예술 공연 관람, 야영, 소풍 등 다양한 체험학습을 하는 교외 특별활동으로 한다.', 618);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (983, '① 원장은 교육과정 운영에 지장을 주지 않는 범위에서 종교를 가진 보호소년등에게 지정된 장소에서 자유롭게 종교의식에 참여하도록 하여야 한다.', 620);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (984, '② 원장은 신부, 목사, 승려, 그 밖의 종교인에게 보호소년등에 대하여 종교에 관한 지도를 하도록 할 수 있다.', 620);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (985, '① 원장은 교정교육에 필요한 도서실ㆍ상담실ㆍ방송실ㆍ심리검사실ㆍ교육자료실 및 종교실 등을 설치ㆍ운영할 수 있다.', 621);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (986, '② 원장은 보호소년등이 제1항의 시설을 이용할 수 있도록 필요한 지원을 하여야 한다.', 621);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (987, '① 법 제42조의2제1항에 따라 판사 또는 검사가 의뢰한 대안교육 대상 소년이 소년원등에서 정해진 교육과정을 이수했을 때에는 그 기간을 재적학교의 출석일수로 인정해야 한다. <개정 2021.4.20>', 623);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (988, '② 원장은 법 제31조제2항에 따른 위탁소년이나 그 보호자 또는 제1항에 따른 대안교육 대상 소년이나 그 보호자가 원하는 경우에는 소년원등의 교육과정 이수사실이나 대안교육 이수사실을 소년의 재적학교의 장에게 통지할 수 있다. <개정 2021.4.20>', 623);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (989, '① 원장은 법 제42조의3에 따라 보호자교육이 필요하다고 인정되면 교육목적과 대상, 시간 및 장소, 프로그램 등의 내용이 포함되는 교육계획을 수립ㆍ시행하여야 한다.', 624);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (990, '② 제1항에 따른 교육 프로그램에는 다음 각 호의 내용을 포함하여야 한다.', 624);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (991, null, 626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (992, '① 「보호관찰 등에 관한 법률」 제48조에 따라 임시퇴원이 취소된 소년의 경우 임시퇴원 당시의 소년원장은 보호관찰관으로부터 그 소년을 인수하여 지체 없이 재수용하여야 한다.', 627);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (993, '② 제1항에도 불구하고 임시퇴원 당시의 소년원과 임시퇴원 취소자(여성인 임시퇴원 취소자는 제외한다. 이하 이 항에서 같다)의 현재지(現在地)의 시ㆍ도가 달라 재수용이 지체될 우려가 있으면 임시퇴원 취소자의 현재지와 인접한 소년원에서 소년을 인수할 수 있다. <개정 2021.4.20>', 627);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (994, '③ 제주지역을 현재지로 하여 임시퇴원이 취소된 사람은 제주소년원에 재수용한다. 다만, 임시퇴원 취소자의 주된 거주지와 제주소년원의 시ㆍ도가 다르면 청원이나 그 밖에 처우상 필요에 따라 임시퇴원 당시의 소년원에서 인수할 수 있다.', 627);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (995, '① 원장은 법 제50조에 따라 보호소년등의 교정교육과 분류심사를 위하여 필요한 경우에는 다음 각 호의 자료를 해당 기관에 요청할 수 있다.', 629);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (996, '② 직무상 제1항의 자료조회를 요청하는 사람 또는 이를 취급하는 사람은 그 내용을 직무와 직접 관련되지 아니하는 사람에게 누설하여서는 아니 된다.', 629);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (997, '① 원장은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2016.9.5, 2021.4.20>', 630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (998, '② 원장은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법 시행령」 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2014.6.30, 2020.3.3>', 630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (999, '① 협회의 정관에는 다음 각 호의 사항이 포함되어야 한다.', 632);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1000, '② 협회는 정관을 변경할 때에는 이사회의 의결을 거쳐 법무부장관의 허가를 받아야 한다.', 632);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1001, '① 협회에는 다음 각 호의 임원을 둔다.', 633);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1002, '② 이사장은 법무부장관이 임명하고, 이사장 및 상임이사를 제외한 이사 중 1명은 법무부 소속 공무원 중에서 법무부장관이 지명하며, 이사장과 법무부장관이 지명한 이사(이하 "당연직이사"라 한다)를 제외한 임원은 이사회에서 선임하되, 법무부장관의 승인을 받아 취임한다.', 633);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1003, '③ 이사장 및 감사의 임기는 2년으로 하고, 당연직이사를 제외한 이사의 임기는 3년으로 한다.', 633);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1004, '④ 당연직이사를 제외한 임원은 법무부장관의 승인을 받아 연임할 수 있다. 다만, 임원의 재임(在任)기간은 이사장의 경우 6년을 초과할 수 없고, 이사의 경우 이사장 임기를 포함하여 10년을 초과할 수 없다.', 633);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1005, '① 이사장은 협회를 대표하고 협회의 업무를 총괄한다.', 634);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1006, '② 이사장은 이사회를 소집하며, 이사회의 의장이 된다.', 634);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1007, '③ 이사장이 부득이한 사유로 직무를 수행할 수 없을 때에는 상임이사가 이사장의 직무를 대행한다.', 634);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1008, '④ 이사는 이사회에 출석하여 협회의 중요 사항을 심의ㆍ의결하며, 이사회 또는 이사장으로부터 위임받은 업무를 처리한다.', 634);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1009, '⑤ 감사는 협회의 업무 및 회계를 감사한다.', 634);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1010, '① 협회의 업무에 관한 주요 사항을 심의ㆍ의결하기 위하여 협회에 이사장과 이사로 구성된 이사회를 둔다.', 635);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1011, '② 감사는 이사회에 출석하여 의견을 진술할 수 있다.', 635);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1012, null, 637);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1013, '① 협회는 그 설립목적을 달성하기 위하여 다음 각 호의 목적사업을 한다. <개정 2016.9.5>', 638);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1014, '② 협회는 그 설립목적을 달성하기 위하여 수익사업을 할 수 있다.', 638);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1015, '③ 협회는 제2항의 수익사업을 하려는 경우에는 사업마다 미리 법무부장관의 승인을 받아야 한다. 이를 변경하려는 경우에도 또한 같다.', 638);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1016, '① 협회의 회계연도는 정부의 회계연도에 따른다.', 639);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1017, '② 협회는 매 회계연도 개시 전까지 해당 회계연도에 수행할 사업계획 및 예산안을 작성하여 이사회의 의결을 거친 후 법무부장관에게 제출하여 승인을 받아야 한다. 이를 변경할 때에도 또한 같다.', 639);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1018, '③ 협회는 매 회계연도의 사업실적과 결산서를 작성하여 이사회의 의결을 거친 후 다음 회계연도 2월 말일까지 법무부장관에게 제출하여야 한다.', 639);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1019, '④ 협회는 국고보조금의 집행결과를 분기마다 법무부장관에게 보고하여야 한다.', 639);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1020, '① 법무부장관은 협회를 지휘ㆍ감독한다.', 640);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1021, '② 법무부장관은 협회에 대하여 감독상 필요한 경우에는 그 업무에 관한 사항을 보고하게 하거나 자료의 제출, 그 밖에 필요한 명령을 할 수 있으며, 소속 공무원에게 협회 운영 실태를 조사하게 할 수 있다.', 640);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1022, '③ 법무부장관은 협회의 국고보조금 집행에 관하여 감사를 할 수 있다.', 640);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1023, '① 원장은 법 제53조제1항에 따라 기부금품을 접수하는 경우 기부자에게 영수증을 발급하여야 한다. 다만, 익명으로 기부하거나 기부자를 알 수 없는 경우에는 영수증을 발급하지 아니할 수 있다.', 642);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1024, '② 원장은 제1항에 따른 기부자가 다음 각 호의 어느 하나의 경우에 해당하는 사실을 알게 된 경우에는 기부금품을 접수해서는 아니 된다.', 642);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1025, '③ 원장은 제1항에 따른 기부자가 기부금품의 용도를 지정한 경우에는 그 용도로만 사용하여야 한다. 다만, 기부자가 지정한 용도로 사용하기 어려운 경우에는 특별한 사정이 없는 한 기부자의 동의를 받아 다른 용도로 사용할 수 있다.', 642);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1026, '④ 원장은 모든 기부금의 수입 및 지출을 기부금 전용계좌를 통하여 처리하여야 한다.', 642);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1027, '⑤ 원장은 기부금품의 접수현황 및 사용실적 등에 관한 장부를 갖추어 두고 기부자가 열람할 수 있도록 하여야 한다.', 642);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1028, '⑥ 원장은 매 반기별로 기부금품의 접수현황 및 사용실적 등에 관한 사항을 법무부장관에게 보고하여야 한다.', 642);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1029, '① 법무부장관이 법 제54조에 따라 범죄경력자료와 수사경력자료의 조회를 요청하는 경우 「형의 실효 등에 관한 법률」 제6조제1항에 따라 소년원에서 퇴원한 보호소년의 재범 여부를 조사하고 소년원 교정교육의 효과를 평가하기 위해 필요한 최소한의 범위에서 요청해야 한다.', 643);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1030, '② 범죄경력자료 또는 수사경력자료를 관리하는 사람이나 직무상 범죄경력자료 또는 수사경력자료를 조회하거나 열람한 사람은 그 내용을 누설해서는 안 된다.', 643);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1031, '③ 제1항 및 제2항에서 규정한 사항 외에 범죄경력자료와 수사경력자료의 조회 요청 방법, 자료 관리 등에 필요한 세부사항은 법무부장관이 정한다.', 643);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1032, '① 검사 또는 사법경찰관리는 다음 각 호의 사무(그 사무를 수행하기 위하여 부수적으로 필요한 사무를 포함한다)를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호에 따른 유전정보, 같은 조 제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1033, '② 사법경찰관은 법 제6조에 따른 긴급응급조치의 통지 및 고지에 관한 사무(그 사무를 수행하기 위하여 부수적으로 필요한 사무를 포함한다)를 수행하기 위하여 불가피한 경우 「개인정보 보호법 시행령」 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1034, '③ 보호관찰소의 장, 교정시설의 장 또는 보호관찰관은 법 제19조에 따른 수강명령 또는 이수명령의 집행에 관한 사무(그 사무를 수행하기 위하여 부수적으로 필요한 사무를 포함한다)를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1035, null, 649);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1036, '①수사기관원 또는 감독청의 관계직원은 법 제9조의 규정에 의한 통보를 받은 때에는 지체없이 그 소속기관의 장에게 보고하여야 한다.', 652);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1037, '②소속기관의 장은 전항의 보고를 받은 때에는 지체없이 그 통보인에게 통보증명서를 교부하여야 한다.', 652);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1038, null, 653);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1039, null, 657);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1040, null, 659);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1041, null, 660);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1042, '① 군사경찰은 법 제10조제1항에 따른 단속을 하기 전에 제3조에 따른 신분을 표시하는 증표를 단속 대상자에게 보여줘야 한다.', 663);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1043, '② 군사경찰은 법 제10조제2항에 따른 단속행위를 한 경우 별지 제1호서식의 음주 단속 보고서를 작성해야 한다.', 663);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1044, '③ 제1항 및 제2항에서 규정한 사항 외에 단속행위의 세부 절차와 방법, 단속 결과의 처리 등 필요한 사항은 국방부장관이 정한다.', 663);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1045, null, 664);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1046, null, 667);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1047, '① 국방부장관은 위해성 군사경찰장비를 새로 도입하려는 경우 법 제11조제4항에 따라 안전성 검사를 실시하여 새로 도입하려는 위해성 군사경찰장비(이하 이 조에서 "신규도입장비"라 한다)가 사람의 생명이나 신체에 미치는 영향을 평가해야 한다.', 668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1048, '② 제1항에 따른 안전성 검사는 신규도입장비와 관련된 분야의 외부 전문가가 신규도입장비의 주요 특성이나 작동원리에 기초하여 제시하는 검사방법 및 기준에 따라 실시한다. 이 경우 신규도입장비에 대하여 일반적으로 인정되는 합리적인 검사방법이나 기준이 있을 때에는 그 검사방법이나 기준에 따라 안전성 검사를 실시할 수 있다.', 668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1049, '③ 법 제11조제4항 후단에 따라 안전성 검사에 참여한 외부 전문가는 안전성 검사가 끝난 날부터 30일 이내에 신규도입장비의 안전성 여부에 대한 의견을 국방부장관에게 제출해야 한다.', 668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1050, '④ 국방부장관은 법 제11조제4항 전단에 따라 신규도입장비에 대한 안전성 검사를 실시한 날부터 3개월 이내에 다음 각 호의 내용이 포함된 안전성 검사 결과보고서를 국회 소관 상임위원회에 제출해야 한다.', 668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1051, '① 법 제17조제1항에 따라 손실보상을 할 때 생명ㆍ신체상의 손실의 경우에는 별표 3의 기준에 따라 보상한다.', 669);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1052, '② 법 제17조제1항에 따라 손실보상을 할 때 재산상 손실 중 물건의 멸실ㆍ훼손으로 인한 손실의 경우에는 다음 각 호의 기준에 따라 보상한다.', 669);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1053, '③ 법 제17조제1항에 따라 손실보상을 할 때 물건의 멸실ㆍ훼손으로 인한 손실 외의 재산상 손실에 대해서는 직무집행과 상당한 인과관계가 있는 범위에서 보상한다.', 669);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1054, '④ 법 제17조제1항에 따라 보상금을 지급받을 사람이 동일한 원인으로 다른 법령에 따라 보상금 등을 지급받은 경우에는 그 보상금 등에 해당하는 금액을 제외하고 보상금을 지급한다.', 669);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1055, '① 법 제17조제1항에 따라 손실을 보상받으려는 사람은 별지 제2호서식의 보상금 지급 청구서에 손실내용과 손실금액을 증명할 수 있는 서류를 첨부하여 손실보상청구 사건 발생지를 작전지역으로 하는 부대의 장에게 제출해야 한다.', 670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1056, '② 제1항에 따라 보상금 지급 청구서를 받은 부대의 장은 해당 청구서를 국방부장관에게 보내야 한다.', 670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1057, '③ 제2항에 따라 보상금 지급 청구서를 받은 국방부장관은 법 제17조제3항에 따른 손실보상심의위원회의 심의ㆍ의결을 거쳐 보상 여부 및 보상금액을 결정하되, 다음 각 호의 어느 하나에 해당하는 경우에는 그 청구를 각하하는 결정을 해야 한다.', 670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1058, '④ 국방부장관은 제3항에 따른 결정일부터 10일 이내에 다음 각 호의 구분에 따른 통지서에 결정 내용을 적어서 청구인에게 통지해야 한다.', 670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1059, '⑤ 보상금은 다른 법률에 특별한 규정이 있는 경우를 제외하고는 현금으로 지급해야 한다.', 670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1060, '⑥ 보상금은 일시금으로 지급하되, 예산 부족 등의 사유로 일시금으로 지급할 수 없는 특별한 사정이 있는 경우에는 청구인의 동의를 받아 분할하여 지급할 수 있다.', 670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1061, '⑦ 보상금을 지급받은 사람은 보상금을 지급받은 원인과 동일한 원인으로 인한 부상이 악화되거나 새로 발견되어 다음 각 호의 어느 하나에 해당하는 경우에는 보상금의 추가 지급을 청구할 수 있다. 이 경우 보상금 지급 청구, 보상금액 결정, 보상금 지급 결정에 대한 통지, 보상금 지급방법 등에 관하여는 제1항부터 제6항까지의 규정을 준용한다.', 670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1062, '⑧ 제1항부터 제7항까지에서 규정한 사항 외에 손실보상의 청구 및 지급에 필요한 사항은 국방부장관이 정한다.', 670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1063, '① 법 제17조제3항에 따른 손실보상심의위원회(이하 "위원회"라 한다)는 위원장 1명을 포함하여 5명 이상 7명 이하의 위원으로 구성한다.', 671);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1064, '② 위원회의 위원은 국방부 소속 군사경찰 중 영관급 및 장성급 장교와 다음 각 호의 어느 하나에 해당하는 사람 중에서 국방부장관이 위촉하거나 임명한다. 이 경우 위원의 과반수는 군사경찰이 아닌 사람으로 해야 한다.', 671);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1065, '③ 위촉위원의 임기는 2년으로 한다.', 671);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1066, '④ 위원회의 사무를 처리하기 위하여 위원회에 간사 1명을 두며, 간사는 소속 공무원 중에서 국방부장관이 임명한다.', 671);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1067, '① 위원장은 위원 중에서 호선(互選)한다.', 672);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1068, '② 위원장은 위원회를 대표하며, 위원회의 업무를 총괄한다.', 672);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1069, '③ 위원장이 부득이한 사유로 직무를 수행할 수 없는 때에는 위원장이 미리 지명한 위원이 그 직무를 대행한다.', 672);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1070, '① 위원장은 위원회의 회의를 소집하고, 그 의장이 된다.', 673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1071, '② 위원회의 회의는 재적위원 과반수의 출석으로 개의(開議)하고, 출석위원 과반수의 찬성으로 의결한다.', 673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1072, '③ 위원회는 심의를 위하여 필요한 경우에는 관계 공무원이나 관계 기관에 사실조사나 자료의 제출 등을 요구할 수 있으며, 관계 전문가에게 필요한 정보의 제공이나 의견의 진술 등을 요청할 수 있다.', 673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1073, '① 위원회의 위원이 다음 각 호의 어느 하나에 해당하는 경우에는 위원회의 심의ㆍ의결에서 제척(除斥)된다.', 674);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1074, '② 청구인은 위원에게 공정한 심의ㆍ의결을 기대하기 어려운 사정이 있는 경우에는 위원회에 기피 신청을 할 수 있고, 위원회는 의결로 기피 여부를 결정한다. 이 경우 기피 신청의 대상인 위원은 그 의결에 참여할 수 없다.', 674);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1075, '③ 위원이 제1항 각 호에 따른 제척 사유에 해당하는 경우에는 스스로 해당 안건의 심의ㆍ의결에서 회피(回避)해야 한다.', 674);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1076, null, 675);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1077, null, 678);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1078, '① 「사법경찰관리의 직무를 행할 자와 그 직무범위에 관한 법률」(이하 "사법경찰직무법"이라 한다)에 따라 사법경찰관의 직무를 행하는 자(이하 "특별사법경찰관"이라 한다)는 사법경찰직무법에 따른 직무의 범위에서 범인과 범죄사실을 수사하고 그에 관한 증거를 수집하는 것을 그 직무로 한다.', 680);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1079, '② 법에 따라 사법경찰리의 직무를 행하는 자(이하 "특별사법경찰리"라 한다)는 특별사법경찰관의 수사를 보조하는 것을 그 직무로 한다.', 680);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1080, '③ 특별사법경찰관 및 특별사법경찰리(이하 "특별사법경찰관리"라 한다)는 범죄를 수사하거나 그 수사를 보조하는 경우에는 검사의 지휘를 받아야 한다.', 680);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1081, '① 특별사법경찰관리는 모든 수사과정에서 헌법과 법률에 따라 보장되는 피의자와 그 밖의 피해자ㆍ참고인 등(이하 "사건관계인"이라 한다)의 권리를 보호하고, 적법한 절차에 따라야 한다.', 681);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1082, '② 특별사법경찰관리는 예단(豫斷)이나 편견 없이 신속하게 수사해야 하고, 주어진 권한을 자의적으로 행사하거나 남용해서는 안 된다.', 681);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1083, '③ 특별사법경찰관리는 다른 사건의 수사를 통해 확보된 증거 또는 자료를 내세워 관련이 없는 사건에 대한 자백이나 진술을 강요해서는 안 된다.', 681);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1084, '① 특별사법경찰관리는 범죄를 수사할 때에는 기밀을 엄수해야 하며, 수사의 모든 과정에서 피의자와 사건관계인의 사생활의 비밀을 보호하고 그들의 명예나 신용이 훼손되지 않도록 노력해야 한다.', 683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1085, '② 특별사법경찰관리는 수사 관련 사항, 피의자와 사건관계인의 개인정보, 그 밖에 직무상 알게 된 사실을 누설(구체적 사건의 수사와 관련하여 수사권한이나 수사지휘 권한이 없는 상급자에게 누설하는 것을 포함한다)해서는 안 된다.', 683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1086, '① 특별사법경찰관리는 법령에 따라 정해진 관할구역에서 직무를 수행한다. 다만, 관할구역의 사건과 관련성이 있는 사실을 발견하기 위해 필요한 때에는 관할구역 밖에서도 그 직무를 수행할 수 있다.', 684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1087, '② 특별사법경찰관리는 관할구역 밖에서 수사하려는 경우에는 관할 지방검찰청 검사장 또는 지청장에게 미리 보고해야 한다. 다만, 「형사소송법」(이하 "법"이라 한다) 제200조의3, 제212조, 제214조, 제216조 및 제217조에 따른 수사를 하는 경우로서 긴급을 요구하여 미리 보고할 시간적 여유가 없을 때에는 사후에 보고할 수 있다.', 684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1088, '① 특별사법경찰관리는 수사를 할 때 수사 대상자의 자유로운 의사에 따른 임의수사를 원칙으로 해야 하고, 강제수사는 법률에서 정한 바에 따라 필요한 경우에만 최소한의 범위에서 하되, 수사 대상자의 권익 침해의 정도가 더 적은 절차와 방법을 선택해야 한다.', 685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1089, '② 특별사법경찰관리는 피의자를 체포ㆍ구속하는 과정에서 피의자 및 현장에 있는 가족 등 지인들의 인격과 명예를 침해하지 않도록 유의해야 한다.', 685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1090, '③ 특별사법경찰관리는 압수ㆍ수색 과정에서 사생활의 비밀, 주거의 평온을 최대한 보장하고, 피의자 및 현장에 있는 가족 등 지인들의 인격과 명예를 침해하지 않도록 유의해야 한다.', 685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1091, '① 특별사법경찰관은 법 제243조의2제1항에 따라 피의자 또는 그 변호인ㆍ법정대리인ㆍ배우자ㆍ직계친족ㆍ형제자매의 신청이 있는 경우에는 변호인의 참여로 인하여 신문이 방해되거나, 수사기밀이 누설되는 등 정당한 사유가 있는 경우를 제외하고는 피의자에 대한 신문에 변호인을 참여하게 해야 한다.', 688);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1092, '② 피의자 또는 그 변호인ㆍ법정대리인ㆍ배우자ㆍ직계친족ㆍ형제자매가 법 제243조의2제1항에 따른 피의자에 대한 신문의 변호인 참여를 신청하는 경우에는 별지 제1호서식의 변호인ㆍ변호사 참여신청서 또는 구술로 할 수 있다.', 688);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1093, '③ 특별사법경찰관은 변호인의 참여로 증거를 인멸ㆍ은닉ㆍ조작할 위험이 구체적으로 드러나거나, 신문 방해, 수사기밀 누설 등 수사에 현저한 지장을 초래하는 경우에는 피의자신문 중이라도 변호인의 참여를 제한할 수 있다. 이 경우 특별사법경찰관은 피의자와 변호인에게 변호인 참여를 제한하는 처분에 대해 법 제417조에 따른 준항고를 제기할 수 있다는 사실을 고지하고, 피의자에게 다른 변호인을 참여시킬 기회를 주어야 한다.', 688);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1094, '④ 특별사법경찰관은 피의자신문에 참여한 변호인이 피의자의 옆자리 등 실질적인 조력을 할 수 있는 위치에 앉도록 해야 하고, 정당한 사유가 없으면 피의자에 대한 법적인 조언ㆍ상담을 보장해야 하며, 법적인 조언ㆍ상담을 위한 변호인의 메모를 허용해야 한다.', 688);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1095, '⑤ 특별사법경찰관은 피의자에 대한 신문이 아닌 단순 면담 등이라는 이유로 변호인의 참여ㆍ조력을 제한해서는 안 된다.', 688);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1096, '⑥ 제1항부터 제5항까지의 규정은 특별사법경찰관의 사건관계인에 대한 조사ㆍ면담 등의 경우에도 적용한다.', 688);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1097, '⑦ 특별사법경찰관은 변호인이 여럿 있을 때에는 법 제32조의2에 따른 대표변호인의 지정, 지정의 철회 또는 변경을 별지 제2호서식의 대표변호인 지정 등 건의서로 검사에게 건의할 수 있다.', 688);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1098, '① 피의자신문에 참여한 변호인은 신문 후 조서를 열람하고 의견을 진술할 수 있다. 이 경우 변호인은 별도의 서면으로 의견을 제출할 수 있으며, 특별사법경찰관은 해당 서면을 사건기록에 편철한다.', 689);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1099, '② 피의자신문에 참여한 변호인은 신문 중이라도 특별사법경찰관의 승인을 받아 의견을 진술할 수 있다. 이 경우 특별사법경찰관은 정당한 사유가 있는 경우를 제외하고는 변호인의 의견진술 요청을 승인해야 한다.', 689);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1100, '③ 피의자신문에 참여한 변호인은 제2항에도 불구하고 부당한 신문방법에 대해서는 특별사법경찰관의 승인 없이 이의를 제기할 수 있다.', 689);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1101, '④ 특별사법경찰관은 제1항부터 제3항까지의 규정에 따른 의견진술 또는 이의제기가 있는 경우 해당 내용을 조서에 적어야 한다.', 689);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1102, '① 특별사법경찰관리는 피해자의 명예와 사생활의 평온을 보호하기 위해 「범죄피해자 보호법」 등 피해자 보호 관련 법령의 규정을 준수해야 한다.', 690);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1103, '② 특별사법경찰관리는 피의자의 범죄수법, 범행 동기, 피해자와의 관계, 언동 및 그 밖의 상황으로 보아 피해자가 피의자 또는 그 밖의 사람으로부터 생명ㆍ신체에 위해를 입거나 입을 염려가 있다고 인정되는 경우에는 직권 또는 피해자의 신청에 따라 신변보호에 필요한 조치를 강구해야 한다.', 690);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1104, null, 692);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1105, '① 지방검찰청 검사장이나 지청장은 범죄의 태양(態樣), 범죄가 미치는 사회적 영향 등을 고려하여 특정 범죄(사법경찰직무법 제8조 및 제9조에 따른 사법경찰관리의 직무범위에 속하는 범죄는 제외한다)를 중점적으로 단속할 필요가 있거나 특정사범에 대한 일반사법경찰관리와 특별사법경찰관리의 중복단속을 피하기 위해 필요한 때에는 관계 행정기관의 장과 협의하여 합동단속반을 설치ㆍ운영할 수 있다.', 694);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1106, '② 지방검찰청 검사장 또는 지청장은 합동단속이나 실태조사 또는 특별사법경찰관리의 전문지식과 인권의식 함양 등을 위해 필요한 때에는 특별사법경찰관리가 소속된 행정기관의 장에게 특별사법경찰관리의 파견, 특별사법경찰관리의 직무를 소관으로 하는 부서에서의 일정기간 근무, 수사실무나 수사 관계 법률 또는 인권에 관한 교육의 수강 등 필요한 사항의 협조를 요청할 수 있다.', 694);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1107, '① 특별사법경찰관은 직무범위에 속하는 범죄에 관한 신문ㆍ방송이나 그 밖의 보도매체의 기사, 익명의 신고 또는 풍문이 있는 경우에는 특히 출처에 주의하여 진상을 내사하고, 내사 결과 범죄의 혐의가 있다고 인정할 때에는 즉시 수사를 개시해야 한다.', 695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1108, '② 특별사법경찰관은 내사 결과 범죄의 혐의가 없다고 인정될 때에는 즉시 내사를 종결해야 한다.', 695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1109, '③ 특별사법경찰관은 익명이나 가공인물의 이름으로 이루어진 진정ㆍ탄원 및 투서의 내용을 정확히 판단하여 수사 단서로서 가치가 없다고 인정할 때에는 내사하지 않을 수 있다.', 695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1110, '④ 특별사법경찰관은 진정ㆍ탄원 및 투서의 내용이 소관으로 하는 형벌법규에 저촉되지 않는 것이 명백하다고 인정할 때에는 진정인ㆍ탄원인 및 투서인에게 그 뜻을 통지하고 내사하지 않을 수 있다.', 695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1111, '① 특별사법경찰관이 수사를 개시한 경우에는 별지 제3호서식의 범죄인지서를 작성해야 한다.', 696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1112, '② 제1항에 따른 범죄인지서에는 피의자의 성명ㆍ주민등록번호ㆍ직업ㆍ주거ㆍ범죄경력, 수사경력, 죄명, 범죄사실 및 적용될 법조문을 적어야 하며, 범죄사실에는 범죄의 일시ㆍ장소ㆍ방법 등을 명시하고 특히 수사의 단서와 범죄사실을 인지하게 된 경위를 구체적으로 적어야 한다.', 696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1113, '① 특별사법경찰관이 다음 각 호의 어느 하나에 해당하는 행위에 착수한 때에는 수사를 개시한 것으로 본다. 이 경우 특별사법경찰관은 해당 사건을 즉시 입건해야 한다.', 697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1114, '② 특별사법경찰관은 수사 중인 사건의 범죄 혐의를 밝히기 위한 목적으로 관련 없는 사건의 수사를 개시하거나 수사기간을 부당하게 연장해서는 안 된다.', 697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1115, '③ 특별사법경찰관은 입건 전에 범죄를 의심할 만한 정황이 있어 수사 개시 여부를 결정하기 위한 사실관계의 확인 등 필요한 조사를 할 때에는 적법절차를 준수하고 사건관계인의 인권을 존중하며, 조사가 부당하게 장기화되지 않도록 신속하게 진행해야 한다.', 697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1116, '④ 특별사법경찰관은 제3항에 따른 조사 결과 입건하지 않는 결정을 한 때에는 피해자에 대한 보복범죄나 2차 피해가 우려되는 경우 등을 제외하고는 피혐의자 및 사건관계인에게 통지해야 한다.', 697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1117, '① 특별사법경찰관리는 다음 각 호의 어느 하나에 해당하는 행위를 한 후 제18조에 따른 범죄인지서를 작성하지 않은 사건에 대해서는 매 분기마다 해당 사건의 목록과 요지를 검사에게 제출해야 한다.', 698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1118, '② 검사는 제1항 각 호의 행위가 다음 각 호의 어느 하나에 해당하는 경우에는 구체적 사건을 특정하여 특별사법경찰관리에게 관계 서류와 증거물을 제출할 것을 서면으로 지시할 수 있다. 이 경우 특별사법경찰관리는 그 지시에 따라야 한다.', 698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1119, '① 특별사법경찰관은 변사자 또는 변사한 것으로 의심되는 시체가 있으면 변사사건 발생사실을 즉시 관할 지방검찰청 또는 지청의 검사에게 보고하고 지휘를 받아야 한다.', 699);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1120, '② 특별사법경찰관이 검사의 명령으로 법 제222조제1항 및 제3항에 따라 검시를 했을 때에는 별지 제4호서식의 검시조서를 작성해야 한다.', 699);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1121, '① 특별사법경찰관리는 검시에 착수하기 전에 변사자의 위치ㆍ상태 등이 변하지 않도록 현장을 보존해야 한다.', 700);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1122, '② 특별사법경찰관리는 변사자의 소지품이나 그 밖에 변사자가 남겨 놓은 물건이 수사에 필요하다고 인정될 때에는 이를 주의하여 보존해야 한다.', 700);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1123, '③ 특별사법경찰관리는 검시를 할 때에는 잠재지문과 변사자의 지문을 주의하여 채취하고, 의사로 하여금 사체검안서를 작성하게 해야 한다.', 700);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1124, null, 703);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1125, null, 704);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1126, '① 특별사법경찰관은 사건마다 범죄통계원표(발생사건표, 검거사건표 및 피의자표를 말한다)를 작성하여 검찰총장이나 관할 지방검찰청 검사장 또는 지청장에게 제출해야 한다.', 705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1127, '② 특별사법경찰관은 사건을 인지할 때에는 피의자의 지문을 채취하여 별지 제6호서식의 수사자료표 송부서에 따라 지문대조조회를 해야 한다.', 705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1128, '③ 특별사법경찰관이 고소ㆍ고발을 받은 사건을 직접 수사할 때에는 피의자의 지문을 채취하여 별지 제6호서식의 수사자료표 송부서에 따라 지문대조조회를 해야 한다. 다만, 고소ㆍ고발을 받은 사건이 다음 각 호의 어느 하나에 해당하는 경우로서 피의자가 「지문을 채취할 형사피의자의 범위에 관한 규칙」 제2조제2항제1호ㆍ제2호 또는 제4호의 어느 하나에 해당하지 않는 경우에는 피의자에 대한 지문채취 및 지문대조조회를 하지 않을 수 있다.', 705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1129, '① 검찰총장, 지방검찰청 검사장 또는 지청장은 국민의 인권을 보호하고 수사절차의 투명성과 수사의 효율성을 보장하기 위해 특별사법경찰관리에게 필요한 일반적 수사준칙 또는 지침을 마련하여 시행할 수 있다.', 707);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1130, '② 지방검찰청 검사장 또는 지청장이 제1항에 따라 일반적 수사지휘를 하거나 세부 지침 등을 마련하여 시행하는 경우에는 법무부장관과 검찰총장에게 일반적 수사지휘 또는 세부 지침 등의 내용을 보고해야 한다.', 707);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1131, '① 특별사법경찰관은 사건을 수사할 때 검사의 지휘가 필요하면 검사에게 별지 제7호서식의 수사지휘 건의서로 건의하여 구체적 지휘를 받아 수사할 수 있다. 다만, 범법자 출입국 규제 요청과 관련하여 지휘건의를 하는 경우에는 별지 제8호서식의 범법자 출입국 규제 요청 지휘 건의서에 따른다.', 708);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1132, '② 특별사법경찰관은 사건 수사와 관련하여 일반사법경찰관리 또는 다른 기관의 특별사법경찰관리와 업무권한의 충돌이나 분쟁이 생겨 기관 간의 업무 조정이 필요한 경우에도 별지 제7호서식의 수사지휘 건의서로 건의하여 구체적 지휘를 받아 수사할 수 있다.', 708);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1133, '① 검사는 특별사법경찰관리에게 사건에 대한 구체적 지휘를 할 때에는 서면 또는 「형사사법절차 전자화 촉진법」에 따른 형사사법정보시스템(이하 "형사사법정보시스템"이라 한다)을 이용하여 지휘해야 한다. 다만, 천재지변, 긴급한 상황, 이미 수사지휘한 내용을 보완하거나 지휘 내용이 명확한 경우, 수사 현장에서 지휘하는 경우 등 서면 또는 형사사법정보시스템에 의한 지휘가 불가능하거나 필요 없다고 인정되는 경우에는 구두나 전화 등 간편한 방식으로 지휘할 수 있다.', 709);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1134, '② 특별사법경찰관은 검사가 제1항 단서에 따라 간편한 방식으로 지휘하였을 때에는 서면 또는 형사사법정보시스템을 이용하여 지휘해 줄 것을 요청할 수 있다.', 709);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1135, '③ 검사는 수사지휘를 위해 필요할 때에는 특별사법경찰관리에게 모든 관계 서류와 증거물을 송부할 것을 지시할 수 있다.', 709);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1136, '④ 검사는 사건이 복잡하여 설명이 필요한 경우 특별사법경찰관에게 대면하여 설명할 것을 요구할 수 있고, 특별사법경찰관은 수사 중인 사건에 관하여 필요할 때에는 검사에게 대면하여 보고할 수 있다.', 709);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1137, '① 특별사법경찰관은 다음 각 호의 어느 하나에 해당하는 경우에는 해당 검사에게 의견을 밝히고 재지휘를 건의할 수 있다.', 710);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1138, '② 검사는 제1항에 따른 재지휘 건의를 받은 때에는 재지휘 여부를 결정하고, 필요한 조치를 해야 한다.', 710);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1139, '① 특별사법경찰관은 검사가 기한을 지정하였을 때에는 그 기한 내에 지휘 사항을 이행해야 한다.', 712);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1140, '② 특별사법경찰관이 검사가 지휘한 기한 내에 지휘 사항을 이행하지 못하였을 때에는 그 사유를 소명하여 검사에게 별지 제9호서식의 수사기일 연장지휘 건의서로 수사기일 연장지휘를 건의해야 한다.', 712);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1141, '① 특별사법경찰관은 다음 각 호의 어느 하나에 해당하는 범죄에 대하여 수사를 개시했을 때에는 검사에게 지휘를 건의하고 입건 여부에 대한 검사의 의견에 따라야 한다.', 713);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1142, '② 특별사법경찰관은 제1항 각 호 외의 범죄에 대해서도 사안의 중대성 등을 고려하여 필요한 경우 검사에게 입건 여부에 대한 지휘를 받을 수 있다.', 713);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1143, '③ 특별사법경찰관은 제20조제2항에 따라 관계 서류와 증거물을 제출한 사건을 입건하거나 사건을 종결하려면 미리 검사의 지휘를 받아야 한다.', 713);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1144, '① 특별사법경찰관은 피의자에게 출석요구를 할 때에는 다음 각 호의 사항을 유의해야 한다.', 714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1145, '② 특별사법경찰관은 피의자에게 출석요구를 하려는 경우 피의자와 조사의 일시ㆍ장소에 관하여 협의해야 한다. 이 경우 변호인이 있는 경우에는 변호인과도 협의해야 한다.', 714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1146, '③ 특별사법경찰관은 피의자에게 출석요구를 하려는 경우 피의사실의 요지 등 출석요구의 취지를 구체적으로 적은 별지 제10호서식의 출석요구서를 발송해야 한다. 다만, 신속한 출석요구가 필요한 경우 등 부득이한 사정이 있는 경우에는 전화, 문자메시지, 그 밖의 상당한 방법으로 출석요구를 할 수 있다.', 714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1147, '④ 특별사법경찰관은 제3항 본문에 따른 방법으로 출석요구를 했을 때에는 출석요구서의 사본을, 같은 항 단서에 따른 방법으로 출석요구를 했을 때에는 그 취지를 적은 수사보고서를 각각 사건기록에 편철한다.', 714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1148, '⑤ 특별사법경찰관은 피의자가 치료 등 수사관서에 출석하여 조사를 받는 것이 현저히 곤란한 사정이 있는 경우에는 수사관서 외의 장소에서 조사할 수 있다.', 714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1149, '⑥ 제1항부터 제5항까지의 규정은 피의자가 아닌 사람에 대한 출석요구의 경우에도 적용한다. 이 경우 피의자가 아닌 사람에 대한 출석요구는 별지 제11호서식의 참고인 출석요구서에 따른다.', 714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1150, '⑦ 특별사법경찰관은 제3항 또는 제6항에 따라 피의자 또는 피의자가 아닌 사람에게 출석요구를 한 경우에는 별지 제12호서식의 출석요구통지부에 해당 사항을 적어야 한다.', 714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1151, '① 특별사법경찰관은 조사, 신문, 면담 등 그 명칭을 불문하고 피의자나 사건관계인에 대해 오후 9시부터 오전 6시까지 사이에 조사(이하 "심야조사"라 한다)를 해서는 안 된다. 다만, 이미 작성된 조서의 열람을 위한 절차는 자정 이전까지 진행할 수 있다.', 716);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1152, '② 제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 심야조사를 할 수 있다. 이 경우 심야조사의 사유를 조서에 명확하게 적어야 한다.', 716);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1153, '① 특별사법경찰관은 조사, 신문, 면담 등 그 명칭을 불문하고 피의자나 사건관계인을 조사하는 경우에는 대기시간, 휴식시간, 식사시간 등 모든 시간을 합산한 조사시간(이하 "총조사시간"이라 한다)이 12시간을 초과하지 않도록 해야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 예외로 한다.', 717);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1154, '② 특별사법경찰관은 특별한 사정이 없으면 총조사시간 중 식사시간, 휴식시간 및 조서의 열람시간 등을 제외한 실제 조사시간이 8시간을 초과하지 않도록 해야 한다.', 717);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1155, '③ 특별사법경찰관은 피의자나 사건관계인에 대한 조사를 마친 때부터 8시간이 지나기 전에는 다시 조사할 수 없다. 다만, 제1항제2호에 해당하는 경우에는 예외로 한다.', 717);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1156, '① 특별사법경찰관은 조사에 상당한 시간이 소요되는 경우에는 특별한 사정이 없으면 피의자 또는 사건관계인에게 조사 도중에 최소한 2시간마다 10분 이상의 휴식시간을 주어야 한다.', 718);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1157, '② 특별사법경찰관은 조사 도중 피의자, 사건관계인 또는 그 변호인으로부터 휴식시간의 부여를 요청받았을 때에는 그때까지 조사에 소요된 시간, 피의자 또는 사건관계인의 건강상태 등을 고려해 적정하다고 판단될 경우 휴식시간을 주어야 한다.', 718);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1158, '③ 특별사법경찰관은 조사 중인 피의자 또는 사건관계인의 건강상태에 이상 징후가 발견되면 의사의 진료를 받게 하거나 휴식하게 하는 등 필요한 조치를 해야 한다.', 718);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1159, '① 법 제244조의5에 따라 피의자와 동석할 수 있는 신뢰관계에 있는 사람과 법 제221조제3항에서 준용하는 법 제163조의2에 따라 피의자 또는 피해자와 동석할 수 있는 신뢰관계에 있는 사람은 피의자 또는 피해자의 직계친족, 형제자매, 배우자, 가족, 동거인, 보호ㆍ교육시설의 보호ㆍ교육담당자 등 피의자 또는 피해자의 심리적 안정과 원활한 의사소통에 도움을 줄 수 있는 사람으로 한다.', 719);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1160, '② 피의자, 피해자 또는 그 법정대리인이 제1항에 따른 신뢰관계에 있는 사람(이하 "신뢰관계인"이라 한다)의 동석을 신청한 경우 특별사법경찰관은 그 관계를 포함하는 별지 제13호서식 또는 별지 제14호서식의 동석신청서를 제출받거나 조서 또는 수사보고서에 그 관계를 적어야 한다.', 719);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1161, '③ 제2항의 경우 특별사법경찰관은 신뢰관계인으로 동석할 사람과 피의자 또는 피해자와의 관계를 소명할 수 있는 자료를 제출받아 기록에 편철한다. 다만, 조사의 긴급성 또는 동석의 필요성 등이 현저한 경우에는 예외적으로 동석 조사 이후에 해당 자료를 제출받아 기록에 편철할 수 있다.', 719);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1162, '④ 특별사법경찰관은 신뢰관계인의 동석으로 인하여 신문이 방해되거나, 수사기밀이 누설되는 등 정당한 사유가 있는 경우에는 동석을 거부할 수 있으며, 신뢰관계인이 피의자신문 또는 피해자 조사를 방해하거나 그 진술의 내용에 부당한 영향을 미칠 수 있는 행위를 하는 등 수사에 현저한 지장을 초래하는 경우에는 피의자신문 또는 피해자 조사 중에도 동석을 제한할 수 있다.', 719);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1163, '① 특별사법경찰관은 피의자 또는 사건관계인을 조사하기에 앞서 조사 대상자에게 조사의 경위 및 이유를 설명해야 하고, 유리한 자료를 제출할 기회를 주거나, 조사 대상자로부터 피의사실에 대한 의견 및 조사 요구 사항 등을 들을 수 있다.', 720);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1164, '② 특별사법경찰관은 조사과정에서 피의자, 사건관계인 또는 그 변호인이 사실관계 등의 확인을 위해 자료를 제출하는 경우 그 자료를 수사기록에 편철한다.', 720);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1165, '③ 특별사법경찰관은 조사를 종결하기 전에 피의자, 사건관계인 또는 그 변호인에게 자료 또는 의견을 제출할 의사가 있는지를 확인하고, 자료 또는 의견을 제출받은 경우에는 해당 자료 및 의견을 수사기록에 편철한다.', 720);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1166, '① 특별사법경찰관은 법 제244조의4에 따라 조사(신문, 면담 등 명칭을 불문한다. 이하 이 조에서 같다) 과정의 진행경과를 다음 각 호의 구분에 따른 방법으로 기록해야 한다.', 721);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1167, '② 제1항에 따라 조사과정의 진행경과를 기록할 때에는 다음 각 호의 구분에 따른 사항을 구체적으로 적어야 한다.', 721);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1168, null, 722);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1169, '① 특별사법경찰관이 피의자를 신문하고 조서를 작성하는 경우에는 별지 제17호서식 및 별지 제18호서식(피의자를 추가로 신문하는 경우로 한정한다)의 피의자신문조서에 따른다.', 723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1170, '② 특별사법경찰관이 피의자가 아닌 사람의 진술을 듣고 조서를 작성하는 경우에는 별지 제19호서식 및 별지 제20호서식(피의자가 아닌 사람의 진술을 추가로 듣는 경우로 한정한다)의 진술조서에 따른다.', 723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1171, '③ 제1항의 피의자신문조서 및 제2항의 진술조서는 진술을 한 피의자 또는 피의자가 아닌 사람(이하 "진술인"이라 한다)에게 열람하게 하거나 읽어 들려주어야 하며, 진술한 대로 기재되지 않았거나 사실과 다른 부분이 있는지를 물어 진술인이 기재 내용의 증감 또는 변경을 청구하는 등 이의를 제기하거나 의견을 진술했을 때에는 이를 조서에 추가로 적어야 한다. 이 경우 진술인이 이의를 제기하였던 부분은 읽을 수 있도록 남겨두어야 한다.', 723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1172, '④ 진술인이 조서에 대하여 이의나 의견이 없음을 진술한 때에는 진술인으로 하여금 그 취지를 별지 제21호서식 또는 제22호서식(진술인이 외국인인 경우로 한정한다)에 따라 자필로 기재하게 한 후 조서에 편철하고, 간인(間印)을 한 후 기명날인 또는 서명하게 해야 한다.', 723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1173, '⑤ 법 제243조의2제4항에 따라 변호인의 의견을 기재한 피의자신문조서는 변호인에게 열람하게 한 후 변호인이 그 조서에 기명날인 또는 서명하게 해야 한다.', 723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1174, '⑥ 특별사법경찰관은 변호인의 신문참여 및 그 제한에 관한 사항을 피의자신문조서에 적어야 한다.', 723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1175, '⑦ 특별사법경찰관은 피의자 또는 피의자가 아닌 사람의 진술을 들어야 하는 경우에 다음 각 호의 어느 하나에 해당할 때에는 피의자 또는 피의자가 아닌 사람에게 별지 제23호서식에 따라 진술서를 작성하도록 할 수 있다.', 723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1176, '⑧ 특별사법경찰관은 제7항의 경우 피의자 또는 피의자가 아닌 사람이 자필로 진술서를 작성하도록 해야 하고, 특별사법경찰관리가 대신 진술서를 작성해서는 안 된다.', 723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1177, '① 특별사법경찰관은 사건관계인이 출석한 경우 지체 없이 조사하고, 부득이한 사유로 조사의 시작이 늦어지거나 조사를 하지 못할 경우에는 그 사유를 설명해야 한다.', 725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1178, '② 특별사법경찰관은 조사 과정을 녹음 또는 녹화하거나 같은 날 여러 명에 대해 출석요구하는 경우에는 시차를 두고 출석을 요구하는 등 불필요한 출석 요구나 장시간 대기를 방지해야 한다.', 725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1179, '③ 특별사법경찰관은 피의자와 사건관계인의 대질조사는 불가피한 사정이 있고 사건관계인이 동의한 경우에만 할 수 있다.', 725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1180, '④ 특별사법경찰관은 사건관계인을 조사할 때에는 폭언 또는 강압적이거나 모멸감을 주거나 공정성을 의심받을 수 있는 언행을 해서는 안 되고, 사생활에 대한 조사는 수사상 반드시 필요한 경우만 할 수 있다.', 725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1181, '① 특별사법경찰관은 피의자 또는 참고인에 대한 조서를 작성할 때에는 필요한 경우 그 조사과정을 영상녹화할 수 있다.', 727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1182, '② 특별사법경찰관은 조사과정을 영상녹화하는 경우 해당 조사의 시작부터 피조사자가 조서에 기명날인 또는 서명을 마치는 시점까지의 전 과정을 영상녹화해야 하며, 조사를 시작한 후에 영상녹화를 할 필요가 있게 된 경우에는 그 시점에서 진행 중인 조사를 종료하고, 그 다음 조사의 시작부터 조서에 피조사자가 서명날인 또는 서명을 마치는 시점까지의 전 과정을 영상녹화해야 한다.', 727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1183, '③ 제2항에도 불구하고 특별사법경찰관은 조사를 마친 후 조서 정리에 장시간을 요하는 경우에는 조서정리과정을 영상녹화하지 않고, 조서 열람 시부터 영상녹화를 재개할 수 있다.', 727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1184, '④ 특별사법경찰관은 피의자에 대한 조사과정을 영상녹화하는 경우 피의자에게 다음 각 호의 사항을 고지해야 한다.', 727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1185, '⑤ 특별사법경찰관은 참고인에 대한 조사과정을 영상녹화하는 경우 별지 제25호서식의 영상녹화 동의서에 따라 영상녹화에 대한 동의 여부를 확인하고, 제4항제1호, 제2호 및 제4호의 사항을 고지해야 한다.', 727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1186, '⑥ 특별사법경찰관은 영상녹화를 할 때에는 조사실 전체를 확인할 수 있도록 하고, 피조사자의 얼굴과 음성을 식별할 수 있도록 해야 한다.', 727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1187, '⑦ 특별사법경찰관은 피의자에 대한 조사과정을 영상녹화하는 경우 법 제243조에 따라 참여자를 참여하게 해야 한다. 이 경우, 참여자는 반드시 조사실에 동석해야 한다.', 727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1188, '① 특별사법경찰관은 영상녹화를 실시한 경우 영상녹화용 컴퓨터에 저장된 영상녹화파일을 이용하여 영상녹화물(CD, DVD 등) 1개를 제작하고, 피조사자의 기명날인 또는 서명을 받아 피조사자 또는 변호인의 면전에서 봉인하여 수사기록에 편철한다.', 728);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1189, '② 특별사법경찰관은 영상녹화물을 제작한 후 영상녹화용 컴퓨터에 저장되어 있는 영상녹화파일을 데이터베이스 서버에 전송하여 보관할 수 있다.', 728);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1190, '③ 특별사법경찰관은 제1항의 영상녹화물이 손상 또는 분실 등으로 인하여 사용될 수 없게 된 경우에는 데이터베이스 서버에 저장되어 있는 영상녹화파일을 이용하여 다시 영상녹화물을 제작할 수 있다.', 728);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1191, '① 특별사법경찰관은 수사상 필요하다고 인정되는 경우에는 범죄현장이나 그 밖의 장소에 가서 실황을 조사해야 한다.', 730);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1192, '② 특별사법경찰관은 제1항의 조사를 하였을 때에는 별지 제26호서식에 따라 실황조사서를 작성해야 한다.', 730);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1193, '① 특별사법경찰관리는 영장, 감정유치장, 허가장, 허가서 및 요청서 등(이하 "영장등"이라 한다)을 신속하고 정확하게 집행해야 한다.', 732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1194, '② 특별사법경찰관리가 영장등을 집행할 때에는 피의자나 사건관계인의 신체와 명예를 보전(保全)하는데 유의해야 한다.', 732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1195, '③ 영장은 검사의 서명ㆍ날인 또는 집행지휘서에 따라 집행한다.', 732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1196, '④ 특별사법경찰관리는 법 제81조제1항 단서에 따라 재판장ㆍ수명법관 또는 수탁판사가 구속영장의 집행을 지휘할 때에는 즉시 구속영장을 집행해야 한다.', 732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1197, '⑤ 특별사법경찰관은 피의자를 체포하거나 구속할 때에는 법 제200조의5(법 제209조에서 준용하는 경우를 포함한다)에 따라 피의자에게 피의사실의 요지, 체포ㆍ구속의 이유와 변호인을 선임할 수 있음을 말하고, 변명할 기회를 주어야 하며, 진술거부권을 알려주어야 한다.', 732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1198, '⑥ 제5항에 따라 피의자에게 알려주어야 하는 진술거부권의 내용은 법 제244조의3제1항제1호부터 제3호까지의 사항으로 한다.', 732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1199, '⑦ 특별사법경찰관은 제5항에 따라 피의자에게 진술거부권 등의 권리를 알려준 경우에는 피의자로부터 별지 제28호서식의 권리 고지 확인서를 받아 사건기록에 편철해야 한다. 다만, 피의자가 확인서에 기명날인 또는 서명하기를 거부할 때에는 별지 제28호서식의 권리 고지 확인서의 끝부분에 그 사유를 기재하고 기명날인 또는 서명해야 한다.', 732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1200, '⑧ 특별사법경찰관리는 영장을 집행할 때에는 법 제89조 및 제90조를 준수해야 한다.', 732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1201, '⑨ 특별사법경찰관은 제1항에 따라 체포ㆍ구속영장을 집행한 때에는 별지 제29호서식의 체포ㆍ구속영장 집행원부에 해당 사항을 기재해야 한다.', 732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1202, '① 특별사법경찰관은 법 제200조의2에 따라 검사에게 체포영장을 신청하려는 경우에는 별지 제30호서식의 체포영장신청서로 신청해야 한다.', 733);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1203, '② 특별사법경찰관은 제1항에 따라 체포영창을 신청하는 경우에는 해당 사항을 별지 제31호서식의 체포영장신청부에 기재해야 한다.', 733);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1204, null, 734);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1205, '① 특별사법경찰관이 법 제200조의3제1항에 따라 긴급체포를 하는 경우에는 피의자의 연령ㆍ경력ㆍ범죄성향, 범죄의 경중ㆍ양상, 그 밖의 여러 사정을 고려하여 인권의 침해가 없도록 신중을 기해야 한다.', 735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1206, '② 특별사법경찰관이 피의자를 긴급체포한 때에는 즉시 별지 제32호서식의 긴급체포서를 작성하고 별지 제33호서식의 긴급체포원부에 그 내용을 적어야 한다.', 735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1207, '③ 특별사법경찰관은 긴급체포 후 12시간 이내에 관할 지방검찰청 또는 지청의 검사에게 긴급체포를 승인하여 줄 것을 건의해야 한다. 다만, 기소중지된 피의자를 해당 기관 또는 관서가 위치하는 특별시ㆍ광역시ㆍ특별자치시ㆍ도 또는 특별자치도 외의 지역이나 「연안관리법」 제2조제2호나목의 바다에서 긴급체포한 때에는 긴급체포 후 24시간 내에 긴급체포에 대한 승인건의를 할 수 있다.', 735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1208, '④ 특별사법경찰관이 제3항에 따라 긴급체포에 대한 승인을 건의할 때에는 범죄사실의 요지, 긴급체포의 일시ㆍ장소, 긴급체포의 사유, 체포를 계속해야 하는 사유 등을 포함하는 별지 제34호서식의 긴급체포승인건의서에 따른다. 다만, 긴급한 경우에는 형사사법정보시스템 또는 팩스를 이용하여 긴급체포에 대한 승인건의를 할 수 있다.', 735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1209, '⑤ 특별사법경찰관은 긴급체포한 피의자를 석방했을 때에는 별지 제33호서식의 긴급체포원부에 석방일시와 석방사유를 적어야 한다.', 735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1210, '⑥ 특별사법경찰관이 피의자를 긴급체포하는 경우의 진술거부권 등 권리 고지에 관하여는 제54조제5항부터 제8항까지의 규정을 준용한다.', 735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1211, '① 특별사법경찰관리가 현행범인을 체포한 때에는 체포의 경위를 상세히 적은 별지 제35호서식의 현행범인체포서를 작성해야 한다.', 736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1212, '② 특별사법경찰관리가 현행범인을 인도받은 경우에는 현행범인을 체포한 사람으로부터 그의 성명ㆍ주민등록번호ㆍ직업ㆍ주거, 체포의 일시ㆍ장소ㆍ사유를 듣고 별지 제36호서식의 현행범인인수서를 작성해야 한다.', 736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1213, '③ 특별사법경찰관리가 현행범인을 체포하거나 현행범인을 인도받는 경우에는 특히 인권의 침해가 없도록 신중을 기해야 한다.', 736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1214, '④ 특별사법경찰관이 현행범인을 체포하거나 인수하는 경우의 진술거부권 등 권리 고지에 관하여는 제54조제5항부터 제8항까지의 규정을 준용한다.', 736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1215, '① 특별사법경찰관리는 현행범인을 체포하거나 체포된 현행범인을 인수한 경우에는 조사가 현저히 곤란하다고 인정되는 경우가 아니면 지체 없이 조사하고, 계속 체포하거나 구금할 필요가 없다고 인정될 때에는 즉시 석방해야 한다.', 737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1216, '② 특별사법경찰관은 제1항에 따라 현행범인을 석방했을 때에는 지체 없이 검사에게 보고하고, 석방일시와 석방사유를 기재한 별지 제37호서식의 피의자 석방보고서를 작성하여 수사기록에 편철해야 한다.', 737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1217, '③ 체포한 현행범인을 석방할 때에는 별지 제38호서식의 현행범인체포원부에 석방일시와 석방사유를 적어야 한다.', 737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1218, '① 특별사법경찰관이 검사에게 구속영장을 신청하는 경우에는 다음 각 호의 구분에 따른 신청서와 서류를 제출해야 한다.', 738);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1219, '② 특별사법경찰관은 피의자에 대하여 구속영장을 신청할 때 법 제209조에서 준용하는 법 제70조제2항의 필요적 고려사항이 있는 경우에는 제1항 각 호의 구속영장신청서에 이를 기재한다.', 738);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1220, '③ 특별사법경찰관은 검사로부터 법 제201조의2제3항 전단에 따른 심문기일과 장소를 통지받은 때에는 검사의 지휘를 받아 지정된 기일과 장소에 체포된 피의자를 출석시켜야 한다.', 738);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1221, '④ 특별사법경찰관은 제1항에 따라 구속영장을 신청한 경우에는 별지 제43호서식의 구속영장신청부에 해당 사항을 기재해야 한다.', 738);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1222, '① 특별사법경찰관은 법 제200조의6 또는 제209조에서 준용하는 법 제87조에 따라 체포ㆍ구속의 통지를 하는 경우에는 별지 제44호서식의 체포ㆍ구속 통지서에 따른다.', 739);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1223, '② 특별사법경찰관은 제1항에 따른 통지를 하는 경우에는 각 호의 구분에 따른 사람에게 체포ㆍ구속한 때부터 늦어도 24시간 내에 서면으로 사건명, 체포ㆍ구속의 일시ㆍ장소, 범죄사실의 요지, 체포ㆍ구속의 이유와 변호인을 선임할 수 있음을 통지해야 한다.', 739);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1224, '③ 특별사법경찰관은 제2항제2호의 경우에 법 제30조제2항에서 규정한 사람이 없어 체포ㆍ구속의 통지를 할 수 없는 경우에는 그 취지를 수사보고서에 적어 수사기록에 편철해야 한다.', 739);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1225, '④ 특별사법경찰관은 긴급을 요할 때에는 전화ㆍ모사전송 또는 이에 상응하는 방법으로 체포ㆍ구속의 통지를 할 수 있다. 이 경우 체포ㆍ구속한 때부터 늦어도 24시간 내에 다시 서면으로 체포ㆍ구속의 통지를 해야 한다.', 739);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1226, '⑤ 제1항에 따른 체포ㆍ구속의 통지서 사본은 수사기록에 편철해야 한다.', 739);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1227, '⑥ 법 제214조의2제2항에 따라 법 제214조의2제1항에서 규정한 사람 중에서 피의자가 지정한 사람에게 적부심사를 청구할 수 있음을 통지하는 경우에도 제1항부터 제3항까지의 규정을 준용한다.', 739);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1228, '① 특별사법경찰관은 법 제214조의2제1항에서 규정한 사람이 체포ㆍ구속영장의 등본을 교부하여 줄 것을 청구하는 경우에는 그 등본을 교부해야 한다.', 740);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1229, '② 특별사법경찰관은 제1항에 따라 체포ㆍ구속영장 등본을 교부했을 때에는 별지 제45호서식의 체포ㆍ구속영장등본교부대장을 작성해야 한다.', 740);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1230, '① 특별사법경찰관리는 변호인 또는 변호인이 되려는 사람이 체포ㆍ구속된 피의자와의 접견, 서류ㆍ물건의 수수(授受) 또는 의사에 의한 피의자의 진료를 요청할 때에는 친절하게 응해야 한다.', 741);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1231, '② 특별사법경찰관리는 변호인 또는 변호인이 되려는 사람이 아닌 사람이 체포ㆍ구속된 피의자와의 접견, 서류ㆍ물건의 수수 또는 의사에 의한 피의자의 진료를 요청하는 경우 법 제200조의6에서 준용하는 법 제91조에 따라 피의자 접견 등을 금지하는 결정이 없는 때에는 제1항에 준하여 처리해야 한다.', 741);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1232, '③ 제1항에 따른 접견 등은 접촉차단시설이 없는 장소에서 하도록 해야 하며, 제2항에 따른 접견 등은 접견 장소 부족, 접견시설의 질서 유지, 접견 사무의 장애 등 특별한 사유가 없으면 유치장 외의 방실에서 하도록 해야 한다.', 741);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1233, '④ 특별사법경찰관리는 제1항 및 제2항에 따른 접견 등의 신청을 받아 접견 등을 하도록 했을 때에는 다음 각 호의 구분에 따른 서류를 작성해야 한다.', 741);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1234, '① 특별사법경찰관은 피의자를 유치할 때에 위험물 또는 휴대금품을 보관하는 경우에는 유치인에게 별지 제49호서식의 임치증명서를 교부해야 한다.', 742);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1235, '② 특별사법경찰관은 피의자를 유치한 경우에는 별지 제50호서식의 임치 및 급식상황표에 임치금품의 처리현황, 급식상황 등을 기재해야 한다.', 742);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1236, '③ 특별사법경찰관은 유치인에게 자기 용도를 위한 차입물품을 사용하는 것을 허가하는 경우에는 별지 제51호서식의 물품차입부에 해당 사항을 기재해야 한다.', 742);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1237, '① 특별사법경찰관은 법 제200조의2 또는 제212조에 따라 체포한 피의자나 법 제200조의3에 따라 긴급체포한 피의자 또는 구속한 피의자를 석방할 때에는 미리 검사의 지휘를 받아야 한다.', 745);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1238, '② 특별사법경찰관은 제1항에 따른 검사의 석방지휘가 있을 때에는 즉시 체포 또는 긴급체포한 피의자나 구속한 피의자를 석방해야 한다.', 745);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1239, '③ 특별사법경찰관은 피의자를 석방했을 때에는 그 사실을 다음 각 호의 구분에 따른 서식에 따라 검사에게 지체 없이 보고해야 하며, 석방일시와 석방사유를 기재한 서면을 작성하여 수사기록에 편철해야 한다.', 745);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1240, '④ 특별사법경찰관은 제1항에 따라 석방을 건의하는 경우에는 별지 제53호서식의 피의자 석방 건의서로 한다. 다만, 긴급을 요하는 경우에는 전화, 팩스, 전자우편, 그 밖의 상당한 방법으로 석방을 건의할 수 있다.', 745);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1241, '① 특별사법경찰관은 법 제198조의2에 따른 검사의 체포ㆍ구속장소 감찰과 관련하여 별지 제54호서식의 체포ㆍ구속인명부를 작성하여 관리해야 한다.', 746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1242, '② 특별사법경찰관은 검사가 법 제198조의2에 따라 체포ㆍ구속장소를 감찰한 후 체포 또는 구속된 피의자의 석방을 명하거나 사건을 송치할 것을 명한 때에는 즉시 피의자를 석방하거나 사건을 송치하고, 피의자석방명령서 또는 사건송치명령서를 수사기록에 편철해야 한다.', 746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1243, '① 특별사법경찰관은 압수ㆍ수색 또는 검증영장을 신청하는 경우 압수ㆍ수색 또는 검증의 범위를 범죄 혐의의 소명에 필요한 최소한으로 정해야 하고, 수색 또는 검증할 장소ㆍ신체ㆍ물건 및 압수할 물건 등을 구체적으로 특정해야 한다.', 748);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1244, '② 특별사법경찰관은 검사에게 압수ㆍ수색 또는 검증영장을 신청할 때에는 다음 각 호의 구분에 따른 신청서를 검사에게 제출해야 한다.', 748);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1245, '③ 특별사법경찰관은 제2항에 따라 압수ㆍ수색 또는 검증영장을 신청했을 때에는 별지 제58호서식의 압수ㆍ수색ㆍ검증영장 신청부를 작성해야 한다.', 748);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1246, '① 특별사법경찰관은 법 제219조에서 준용하는 법 제118조에 따라 영장을 제시할 때에는 피압수자에게 법관이 발부한 영장에 따른 압수ㆍ수색 또는 검증이라는 사실과 영장에 기재된 범죄사실 및 수색 또는 검증할 장소ㆍ신체ㆍ물건, 압수할 물건 등을 명확히 알리고, 피압수자가 해당 영장을 열람할 수 있도록 해야 한다.', 749);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1247, '② 압수ㆍ수색 또는 검증의 처분을 받는 자가 여럿인 경우에는 모두에게 개별적으로 영장을 제시해야 한다.', 749);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1248, '① 특별사법경찰관은 법 제219조에서 준용하는 법 제106조제3항에 따라 컴퓨터용 디스크 및 그 밖에 이와 비슷한 정보저장매체(이하 이 항에서 "정보저장매체등"이라 한다)에 기억된 정보(이하 "전자정보"라 한다)를 압수하는 경우에는 해당 정보저장매체등의 소재지에서 수색 또는 검증한 후 범죄사실과 관련된 전자정보의 범위를 정하여 출력하거나 복제하는 방법으로 한다.', 750);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1249, '② 제1항에도 불구하고 제1항에 따른 압수 방법의 실행이 불가능하거나 그 방법으로는 압수의 목적을 달성하는 것이 현저히 곤란한 경우에는 압수ㆍ수색 또는 검증 현장에서 정보저장매체등에 들어 있는 전자정보 전부를 복제하여 그 복제본을 정보저장매체등의 소재지 외의 장소로 반출할 수 있다.', 750);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1250, '③ 제1항 및 제2항에도 불구하고 제1항 및 제2항에 따른 압수 방법의 실행이 불가능하거나 그 방법으로는 압수의 목적을 달성하는 것이 현저히 곤란한 경우에는 피압수자 또는 법 제123조에 따라 압수ㆍ수색영장을 집행할 때 참여하게 해야 하는 사람(이하 "피압수자등"이라 한다)이 참여한 상태에서 정보저장매체등의 원본을 봉인(封印)하여 정보저장매체등의 소재지 외의 장소로 반출할 수 있다.', 750);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1251, '① 특별사법경찰관은 전자정보의 탐색ㆍ복제ㆍ출력을 완료한 경우에는 지체 없이 피압수자등에게 압수한 전자정보의 목록을 교부해야 한다.', 751);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1252, '② 특별사법경찰관은 제1항의 목록에 포함되지 않은 전자정보가 있는 경우에는 해당 전자정보를 지체 없이 삭제 또는 폐기하거나 반환해야 한다. 이 경우 별지 제59호서식의 전자정보 삭제ㆍ폐기 또는 반환확인서를 작성하여 피압수자등에게 교부해야 한다.', 751);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1253, '③ 특별사법경찰관은 전자정보의 복제본을 취득하거나 전자정보를 복제할 때에는 해시값(파일의 고유값으로서 일종의 전자지문을 말한다)을 확인하거나 압수ㆍ수색 또는 검증의 과정을 촬영하는 등 전자적 증거의 동일성과 무결성(無缺性)을 보장할 수 있는 적절한 방법과 조치를 취해야 한다.', 751);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1254, '④ 특별사법경찰관은 압수ㆍ수색 또는 검증의 전 과정에 걸쳐 피압수자등이나 변호인의 참여권을 보장해야 하며, 피압수자등과 변호인이 참여를 거부하는 경우에는 신뢰성과 전문성을 담보할 수 있는 상당한 방법으로 압수ㆍ수색 또는 검증을 해야 한다.', 751);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1255, '⑤ 특별사법경찰관은 제4항에 따라 참여한 피압수자등이나 변호인이 압수 대상 전자정보와 사건의 관련성에 관하여 의견을 제시한 때에는 이를 조서에 적어야 한다.', 751);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1256, '⑥ 제72조제2항 또는 제3항에 따라 전자정보 전부를 복제하여 그 복제본을 반출하거나 정보저장매체등 원본을 반출하는 경우에는 피압수자등에게 전자정보의 탐색ㆍ복제ㆍ출력 절차에 참여할 수 있음을 고지한 후 다음 각 호의 구분에 따른 확인서를 작성하여 피압수자등의 서명을 받아야 한다. 다만, 서명을 받기 어려운 사정이 있는 경우에는 그 사유를 해당 확인서에 기재하고 기록에 편철한다.', 751);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1257, '① 특별사법경찰관은 증거물이나 몰수할 물건을 압수한 경우에는 별지 제62호서식의 압수조서와 별지 제63호서식의 압수목록을 작성해야 한다.', 752);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1258, '② 압수조서에는 압수의 일시ㆍ장소, 압수의 경위 등을, 압수목록에는 압수물건의 품종ㆍ수량 등을 각각 구체적으로 적어야 한다.', 752);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1259, '③ 제1항에도 불구하고 피의자신문조서ㆍ진술조서ㆍ검증조서 또는 실황조사서에 압수의 취지를 기재하여 압수조서의 작성을 갈음할 수 있다.', 752);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1260, '④ 특별사법경찰관이 법 제218조에 따라 유류(遺留)한 물건 또는 임의로 제출하는 물건을 압수하여 압수조서와 압수목록을 작성하는 경우에는 제1항 및 제2항을 준용한다.', 752);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1261, '① 특별사법경찰관리는 멸실할 우려가 있는 증거물은 특히 보전에 유의해야 하며, 검증조서 또는 다른 조서에 그 성질과 형상을 상세히 기재하거나 촬영해야 한다.', 753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1262, '② 특별사법경찰관은 증거물이 훼손되거나 형상이 변경될 우려가 있는 검증이나 감정을 위촉할 때에는 검증조서 또는 다른 조서에 그 성질과 형상을 상세히 기재하거나 촬영하는 등 변경 전의 형상을 알 수 있도록 특히 유의해야 한다.', 753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1263, '① 특별사법경찰관리가 수색을 한 경우에는 수색의 일시ㆍ장소, 참여인 등을 포함하여 별지 제64호서식의 수색조서를 작성해야 한다.', 754);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1264, '② 특별사법경찰관리는 수색을 한 결과 증거물 또는 몰수할 물건이 없을 때에는 그 처분을 받는 자에게 그 취지를 기재한 별지 제65호서식의 수색결과 증명서를 교부해야 한다.', 754);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1265, '① 특별사법경찰관은 법 제218조의2제4항에서 준용하는 같은 조 제1항부터 제3항까지에 따른 압수물의 환부 또는 가환부 처분을 하거나 법 제219조에서 준용하는 법 제130조, 제132조 및 제134조에 따라 압수물의 보관, 폐기, 대가보관 또는 피해자환부의 처분을 하려는 경우에는 그 처분유형과 처분사유를 기재한 다음 각 호의 구분에 따른 지휘건의서를 검사에게 제출하여 압수물의 처분에 대한 검사의 지휘를 받아야 한다.', 756);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1266, '② 특별사법경찰관이 법 제130조제1항에 따라 압수물을 다른 사람에게 보관하게 하는 경우에는 압수물에 사건명, 피의자의 성명, 압수목록에 기재한 순위ㆍ번호를 표시하고, 보관자로부터 별지 제70호서식의 압수물 보관 서약서를 받아 사건기록에 첨부해야 한다.', 756);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1267, '③ 특별사법경찰관은 압수물이 유가증권인 경우에는 지체 없이 별지 제71호서식의 유가증권 원형보존 등 지휘건의서를 검사에게 제출하여 원형보존 또는 환전보관 여부에 관한 검사의 지휘를 받아야 한다.', 756);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1268, '④ 특별사법경찰관은 법 제130조제2항 또는 제3항에 따라 압수물을 폐기하는 경우에는 별지 제72호서식의 폐기조서를 작성하고 압수물 사진 및 압수물 폐기에 관한 증빙자료를 수사기록에 첨부해야 한다.', 756);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1269, '⑤ 특별사법경찰관이 법 제133조에 따라 압수물을 환부ㆍ가환부하거나 법 제134조에 따라 압수장물을 피해자환부하는 경우에는 피해자, 피의자 또는 변호인에게 지체 없이 통지를 한 후 신속히 환부해야 한다.', 756);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1270, '① 특별사법경찰관이 「통신비밀보호법」 제6조제2항에 따라 검사에게 통신제한조치에 대한 허가를 신청하는 경우에는 별지 제73호서식의 통신제한조치허가 신청서에 따르고, 같은 조 제7항 단서에 따라 통신제한조치기간의 연장허가 청구를 신청하는 경우에는 별지 제74호서식의 통신제한조치기간 연장허가 신청서에 따른다.', 757);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1271, '② 특별사법경찰관은 제1항에 따라 검사가 통신제한조치에 대한 허가를 신청하거나 통신제한조치의 연장 청구를 신청하는 경우에는 별지 제75호서식의 통신제한조치허가 신청부에 해당 사항을 기재한다.', 757);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1272, '③ 특별사법경찰관은 「통신비밀보호법」 제8조제3항 본문에 따라 긴급통신제한조치에 대하여 검사에게 지휘를 건의하는 경우에는 별지 제76호서식의 긴급통신제한조치 지휘건의서에 따르고, 같은 항 단서에 따라 검사에게 승인을 건의하는 경우에는 별지 제77호서식의 긴급통신제한조치 승인건의서에 따른다.', 757);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1273, '④ 특별사법경찰관은 「통신비밀보호법」 제8조제1항에 따라 긴급통신제한조치를 하는 경우에는 별지 제78호서식의 긴급검열(감청)서에 따른다. 이 경우 특별사법경찰관은 별지 제79호서식의 긴급통신제한조치대장을 작성하여 소속기관에 비치해야 한다.', 757);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1274, '⑤ 특별사법경찰관이 「통신비밀보호법」 제8조제2항에 따라 긴급통신제한조치를 한 후에 검사에게 허가청구를 신청하는 경우에는 별지 제80호서식의 통신제한조치허가 신청서(사후)에 따른다.', 757);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1275, '⑥ 특별사법경찰관이 「통신비밀보호법」 제8조제5항에 따라 긴급통신제한조치를 한 후에 법원의 허가를 받을 필요가 없어 긴급통신제한조치 사실을 법원에 통보하는 경우에는 별지 제81호서식의 긴급통신제한조치통보서에 따른다. 이 경우 특별사법경찰관은 별지 제82호서식의 긴급통신제한조치 통보서 발송부를 작성하여 소속기관에 비치해야 한다.', 757);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1276, '① 특별사법경찰관이 「통신비밀보호법」 제9조제1항 후단에 따라 통신제한조치 집행을 위탁하는 경우에는 별지 제83호서식의 통신제한조치 집행위탁 의뢰서에 따른다.', 758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1277, '② 특별사법경찰관이 집행위탁한 통신제한조치의 허가기간이 연장된 경우에는 별지 제84호서식의 통신제한조치 기간연장 통지서로 수탁기관에 통지한다.', 758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1278, '③ 특별사법경찰관은 제1항 및 제2항에 따라 통신제한조치 집행을 위탁하거나 통신제한조치의 허가기간 연장을 통지한 경우에는 별지 제85호서식의 통신제한조치 집행위탁허가 신청부에 해당 사항을 기재해야 한다.', 758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1279, '④ 통신제한조치를 집행한 특별사법경찰관은 별지 제86호서식의 통신제한조치 집행조서를 작성해야 한다.', 758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1280, '⑤ 특별사법경찰관은 통신제한조치를 집행한 후 수사 또는 내사한 사건을 종결하는 경우 그 결과를 별지 제87호서식의 통신제한조치 집행결과 보고서에 따라 검사에게 보고해야 한다.', 758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1281, '⑥ 다른 관서에서 통신제한조치를 집행한 사건을 이송받아 내사한 후 내사를 종결하는 경우 내사를 종결한 관서는 허가서를 청구한 검찰청에 집행결과를 검사에게 보고한 후 허가서를 신청한 관서에 사건처리결과를 통보해야 한다.', 758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1282, '⑦ 특별사법경찰관은 통신제한조치의 집행이 필요 없게 되어 통신제한조치를 중단하려는 경우에는 별지 제88호서식의 통신제한조치 집행중지통지서에 따라 이를 수탁기관에 통지한다.', 758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1283, '① 특별사법경찰관은 「통신비밀보호법」에 따른 통신제한조치 집행으로 취득한 자료를 같은 법 제6조 및 제8조에 따른 통신제한조치허가서, 별지 제86호서식의 통신제한조치 집행조서 및 같은 법 제12조의2제4항에 따라 법원이 발부한 승인서와 함께 봉인한 후 통신제한조치 허가번호 및 보존기간을 표기하여 별도로 보관하고, 수사담당자 외의 사람이 열람할 수 없도록 해야 한다.', 759);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1284, '② 특별사법경찰관은 통신제한조치를 집행하고 제18조에 따른 범죄인지서를 작성하지 않았을 때에는 그 집행으로 취득한 자료 등은 보존기간이 지난 후 검사의 지휘를 받아 즉시 폐기해야 한다.', 759);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1285, '① 특별사법경찰관이 「통신비밀보호법」 제9조의2제2항에 따라 통신제한조치를 집행한 사실 등을 통지하는 경우에는 별지 제89호서식의 통신제한조치 집행사실 통지서에 따른다. 이 경우 특별사법경찰관은 별지 제90호서식의 통신제한조치 집행사실 통지부에 해당 사항을 기재해야 한다.', 760);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1286, '② 특별사법경찰관은 「통신비밀보호법」 제9조의2제5항에 따라 통지유예에 대한 관할 지방검찰청 검사장의 승인을 신청하는 경우에는 별지 제91호서식의 통신제한조치 집행사실 통지유예 승인신청서에 따른다. 이 경우 특별사법경찰관은 별지 제92호서식의 통신제한조치 집행사실통지 유예승인신청부에 해당 사항을 기재해야 한다.', 760);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1287, '③ 특별사법경찰관은 「통신비밀보호법」 제9조의2제6항에 따라 통지유예의 사유가 해소된 날부터 30일 이내에 유예했던 통지를 한 경우에는 그 사실을 별지 제93호서식의 통신제한조치 집행사실 통지보고서에 따라 관할 지방검찰청 검사장에게 보고해야 한다.', 760);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1288, '① 특별사법경찰관이 「통신비밀보호법」 제13조제1항에 따라 통신사실 확인자료제공을 요청하는 경우에는 별지 제98호서식의 통신사실 확인자료제공 요청서에 따르고, 별지 제99호서식의 통신사실 확인자료제공 요청 집행대장에 해당 사항을 기재해야 한다.', 763);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1289, '② 제1항에 따라 통신사실 확인자료제공을 요청한 특별사법경찰관은 별지 제100호서식의 통신사실 확인자료제공 요청 집행조서를 작성해야 한다.', 763);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1290, '③ 특별사법경찰관은 제1항에 따라 전기통신사업자로부터 통신사실 확인자료를 제공받은 경우에는 이를 별지 제101호서식의 통신사실 확인자료 회신대장에 기재해야 한다.', 763);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1291, '④ 특별사법경찰관은 통신사실 확인자료제공 요청이 필요없게 된 경우에는 별지 제102호서식의 통신사실 확인자료제공 요청중지통지서로 해당 전기통신사업자에게 이를 통지해야 한다.', 763);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1292, '⑤ 특별사법경찰관은 통신사실 확인자료제공을 요청한 후 수사 또는 내사한 사건을 종결하는 경우 그 결과를 별지 제103호서식의 통신사실 확인자료제공 요청 집행결과보고서에 따라 검사에게 보고해야 한다.', 763);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1293, '⑥ 다른 관서에서 통신사실 확인자료제공을 요청한 사건을 이송받아 내사한 후 내사를 종결하는 경우 내사를 종결한 관서는 허가서를 청구한 검찰청에 집행결과를 검사에게 보고한 후 허가서를 신청한 관서에 사건처리결과를 통보해야 한다.', 763);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1294, '① 특별사법경찰관이 「통신비밀보호법」 제13조제3항 본문에 따른 통신사실 확인자료제공 요청허가를 검사에게 신청하는 경우에는 별지 제104호서식의 통신사실 확인자료제공 요청허가 신청서에 따른다.', 764);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1295, '② 특별사법경찰관은 제1항 및 제87조제2항에 따라 통신사실 확인자료제공 요청허가를 신청하는 경우에는 별지 제105호서식의 통신사실 확인자료제공 요청허가 신청부에 해당 사항을 기재해야 한다.', 764);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1296, '① 특별사법경찰관이 「통신비밀보호법」 제13조제3항 단서에 따라 긴급 통신사실 확인자료제공을 요청하는 경우에는 별지 제106호서식의 긴급 통신사실 확인자료제공 요청서에 따른다. 이 경우 특별사법경찰관은 별지 제107호서식의 긴급 통신사실 확인자료제공 요청대장에 해당 사항을 기재해야 한다.', 765);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1297, '② 특별사법경찰관이 「통신비밀보호법」 제13조제3항 단서에 따라 통신사실 확인자료제공 요청허가를 검사에게 신청하는 경우에는 별지 제108호서식의 통신사실 확인자료제공 요청허가 신청서(사후)에 따른다.', 765);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1298, '① 특별사법경찰관이 「통신비밀보호법」 제13조의3제1항에 따라 통신사실 확인자료제공의 대상이 된 당사자에게 통지를 하는 경우에는 별지 제109호서식의 통신사실 확인자료제공 요청 집행사실 통지서에 따른다. 이 경우 특별사법경찰관은 별지 제110호서식의 통신사실 확인자료제공 요청 집행사실 통지부에 해당 사항을 기재해야 한다.', 766);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1299, '② 특별사법경찰관은 「통신비밀보호법」 제13조의3제3항에 따라 통지유예에 대하여 관할 지방검찰청 검사장의 승인을 신청하는 경우에는 별지 제111호서식의 통신사실 확인자료제공 요청 집행사실 통지유예 승인신청서에 따른다. 이 경우 특별사법경찰관은 별지 제112호서식의 통신사실 확인자료제공 요청 집행사실 통지유예 승인신청부에 해당 사항을 기재해야 한다.', 766);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1300, '③ 특별사법경찰관은 「통신비밀보호법」 제13조의3제4항에 따라 통지유예의 사유가 해소된 날부터 30일 이내에 유예했던 통지를 한 경우에는 그 사실을 별지 제113호서식의 통신제한조치 집행사실 통지 보고서에 따라 관할 지방검찰청 검사장에게 보고해야 한다.', 766);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1301, '① 특별사법경찰관리가 검사에게 법 제221조의3제1항에 따른 감정유치의 청구를 신청하는 경우에는 별지 제114호서식의 감정유치장 신청서에 따른다.', 767);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1302, '② 특별사법경찰관리가 검사에게 법 제221조의4제1항 및 제2항에 따른 감정처분허가의 청구를 신청하는 경우에는 별지 제115호서식의 감정처분허가장 신청서에 따른다.', 767);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1303, '③ 특별사법경찰관리가 법 제221조제2항에 따라 감정을 위촉하는 경우에는 별지 제116호서식의 감정위촉서에 따른다.', 767);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1304, '④ 특별사법경찰관리가 법 제221조의4제3항에 따라 발부된 감정처분허가장에 따라 감정을 위촉하는 경우에는 별지 제117호서식의 감정위촉서에 따른다.', 767);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1305, '① 특별사법경찰관은 체포ㆍ구속영장의 유효기간 내에 영장의 집행에 착수하지 못했거나, 그 밖의 사유로 영장의 집행이 불가능하거나 불필요하게 되었을 때에는 즉시 해당 영장을 법원에 반환해야 한다. 이 경우 체포ㆍ구속영장이 여러 통 발부된 경우에는 모두 반환해야 한다.', 768);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1306, '② 특별사법경찰관은 제1항에 따라 체포ㆍ구속영장을 반환하는 경우에는 별지 제118호서식의 영장반환 보고서에 발행통수와 집행불능 등 영장반환 사유를 적어 검사에게 제출하고, 그 사본을 사건기록에 편철한다.', 768);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1307, '① 특별사법경찰관이 고소나 고발에 의하여 범죄를 수사하는 경우에는 고소나 고발이 있은 날부터 2개월 이내에 수사를 완료해야 한다.', 773);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1308, '② 제1항에 따른 기간에 수사를 완료하지 못한 경우에는 관할 지방검찰청 또는 지청의 검사의 지휘를 받아야 한다.', 773);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1309, null, 774);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1310, '① 소년사건을 수사할 때에는 범죄의 원인 및 동기와 그 소년의 성격, 경력, 교육 정도, 가정상황, 교우관계, 그 밖의 환경 등을 상세히 조사하여 별지 제121호서식의 소년환경 조사서를 작성해야 한다.', 777);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1311, '② 소년의 심신에 이상이 있다고 인정되는 때에는 지체 없이 의사의 진단을 받도록 해야 한다.', 777);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1312, '① 특별사법경찰관은 청각 및 언어장애인이나 그 밖에 의사소통이 어려운 장애인을 조사하는 경우에는 수화ㆍ문자통역을 제공하거나 의사소통을 도울 수 있는 사람을 참여시켜야 한다.', 780);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1313, '② 특별사법경찰관은 장애인인 피의자에게 대한법률구조공단의 법률구조 신청에 대하여 안내해야 한다.', 780);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1314, '① 특별사법경찰관은 외국인을 체포ㆍ구속하는 경우에는 우리나라 주재 본국 영사관원과 자유롭게 접견ㆍ통신할 수 있고, 체포ㆍ구속된 사실을 영사기관에 통지하여 줄 것을 요청할 수 있다는 사실을 알려야 한다.', 782);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1315, '② 특별사법경찰관은 체포ㆍ구속된 외국인이 제1항에 따른 통지를 요청할 경우에는 지체 없이 해당 영사기관에 체포ㆍ구속된 사실을 통지해야 한다.', 782);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1316, null, 783);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1317, '① 특별사법경찰관이 「마약류 불법거래 방지에 관한 특례법」(이하 "마약거래방지법"이라 한다) 제34조제1항 및 제53조제1항(「범죄수익은닉의 규제 및 처벌 등에 관한 법률」 제12조에서 준용하는 경우를 포함한다)에 따라 검사에게 몰수ㆍ부대보전 또는 추징보전을 신청할 때에는 별지 제122호서식의 몰수ㆍ부대보전 신청서 또는 별지 제123호서식의 추징보전 신청서를 제출해야 한다.', 785);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1318, '② 특별사법경찰관이 제1항에 따라 몰수ㆍ부대보전 또는 추징보전을 신청했을 때에는 별지 제124호서식의 몰수ㆍ부대보전 신청부 또는 별지 제125호서식의 추징보전 신청부를 작성하고, 필요한 사항을 적어야 한다.', 785);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1319, '③ 특별사법경찰관은 마약거래방지법 제53조제3항(「범죄수익은닉의 규제 및 처벌 등에 관한 법률」 제12조에서 준용하는 경우를 포함한다. 이하 이 조에서 같다)에 따라 검사가 추징보전과 관련한 신청, 보완ㆍ수정, 취소 등의 요구를 한 경우에는 검사의 요구에 따른 조치를 취한 다음 지체 없이 그 결과를 검사에게 보고해야 한다.', 785);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1320, '④ 특별사법경찰관은 마약거래방지법 제53조제3항에 따른 검사의 요구에 따라 추징보전명령 취소신청을 하려는 경우에는 별지 제126호서식에 따라 추징보전명령 취소신청서를 제출해야 한다.', 785);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1321, '⑤ 특별사법경찰관은 제4항에 따라 취소신청을 하였을 때에는 별지 제127호서식의 추징보전 취소신청부를 작성하고, 필요한 사항을 적어야 한다.', 785);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1322, '① 특별사법경찰관은 마약거래방지법 제3조제5항에 따른 입국ㆍ상륙 허가의 요청 또는 체류 부적당 통보를 검사에게 신청할 때에는 별지 제128호서식의 입국ㆍ상륙허가요청 신청서 또는 별지 제129호서식의 체류부적당통보 신청서를 제출해야 한다.', 786);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1323, '② 특별사법경찰관은 마약거래방지법 제4조제3항에 따라 세관 절차 특례에 대한 요청을 검사에게 신청하는 경우에는 별지 제130호서식의 세관절차 특례요청 신청서를 제출해야 한다.', 786);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1324, '③ 특별사법경찰관은 제1항 및 제2항에 따라 신청을 하였을 때에는 별지 제131호서식의 특례조치 등 신청부를 작성해야 한다.', 786);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1325, '① 특별사법경찰관이 수사를 종결한 때에는 관할 지방검찰청 검사장 또는 지청장에게 사건을 송치해야 한다.', 787);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1326, '② 특별사법경찰관은 제1항에 따라 사건을 송치하는 경우에는 다음 각 호의 구분에 따른 명의로 해야 한다.', 787);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1327, '① 특별사법경찰관은 다음 각 호의 어느 하나에 해당하는 사건에 대해서는 사건을 송치하기 전에 검사의 구체적 지휘를 받아야 한다.', 788);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1328, '② 특별사법경찰관은 「출입국관리법」 위반범죄, 「관세법」 위반범죄 및 「조세범 처벌법」 위반범죄 등 관계 행정기관의 장의 고발을 공소제기 요건으로 하는 범죄를 수사하는 경우에는 송치 등 사건을 종결하는 처분을 하기 전에 해당 사건의 증거 판단, 소추요건, 법령의 해석ㆍ적용 등에 관하여 검사의 지휘를 받아야 한다. 다만, 관계 행정기관의 장이 법무부장관이나 검찰총장, 관할 지방검찰청 검사장 또는 지청장과 미리 협의하여 정한 처리기준에 따라 처리할 때에는 검사의 지휘를 받지 않고 사건을 종결하는 처분을 할 수 있다.', 788);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1329, '③ 검사는 제1항 및 제2항 본문에 따른 지휘 건의가 있을 때에는 7일 이내에 의견을 제시해야 한다. 다만, 사안이 복잡하거나 장시간의 검토를 필요로 하는 등의 특별한 사정이 있을 때에는 14일 이내에 의견을 제시할 수 있다.', 788);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1330, '④ 제1항 및 제2항 본문에 따른 검사의 지휘를 받은 특별사법경찰관은 사건송치서 등 수사기록 표지의 비고란에 지휘검사의 성명 및 지휘일자를 기재하고, 수사기록에 수사지휘서 또는 수사지휘내용을 기재한 수사보고서를 편철해야 한다.', 788);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1331, '① 특별사법경찰관은 사건을 송치할 때에는 수사기록에 제4항 각 호의 서류를 첨부해야 한다. 다만, 「형의 실효 등에 관한 법률」 제5조제1항제2호에 해당하는 경우로서 「지문을 채취할 형사피의자의 범위에 관한 규칙」 제2조제2항제1호ㆍ제2호 또는 제4호에 해당하지 않는 피의자에 대하여 다음 각 호의 어느 하나에 해당하는 의견으로 송치할 때에는 범죄경력ㆍ수사경력 조회 결과를 첨부하지 않을 수 있다.', 789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1332, '② 사건을 송치하기 전에 범죄경력ㆍ수사경력 조회 결과를 받지 못한 경우에는 사건송치서에 그 사유를 기재하고, 송치 후에 범죄경력 또는 수사경력을 발견한 때에는 즉시 주임검사에게 보고해야 한다.', 789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1333, '③ 특별사법경찰관은 사건을 기소중지 의견으로 송치하는 경우에는 소재불명 피의자의 지명수배ㆍ통보 내용, 사진, 별지 제132호서식의 인상서 등 관련 자료를 첨부해야 한다.', 789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1334, '④ 송치서류는 다음 각 호의 순서에 따라 편철한다.', 789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1335, '⑤ 사건을 송치하는 특별사법경찰관은 제4항제2호부터 제4호까지의 규정에 따른 서류에 직접 간인을 해야 한다.', 789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1336, '⑥ 제4항제4호의 서류에는 각 장마다 면수를 기입하되, 1장으로 이루어진 경우에는 1로 표시하고, 2장 이상으로 이루어진 경우에는 1-1, 1-2, 1-3 등으로 표시해야 한다.', 789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1337, '⑦ 제4항제5호의 서류는 접수하거나 작성한 순서에 따라 편철한다. 이 경우 순서대로 각 장마다 2부터 시작하여 2, 3, 4 등으로 면수를 표시해야 한다. <개정 2021.2.3>', 789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1338, '⑧ 특별사법경찰관은 「검찰압수물사무규칙」 제2조에 따른 특수압수물을 송부하는 경우에는 수사기록에 감정서 원본을 편철하여 사본 2부와 함께 제출해야 한다. 다만, 통화ㆍ외국환 및 유가증권과 이에 준하는 증서를 송부하는 경우에는 감정서를 첨부하지 않을 수 있다.', 789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1339, '⑨ 수사담당 특별사법경찰관은 통신제한조치를 집행한 사건을 송치하는 경우에는 수사기록 표지의 증거품 관련 난에 "통신제한조치"라고 표기하고, 통신제한조치집행으로 취득한 물건을 직접 「검찰압수물사무규칙」에 따른 압수물 송부의 방법으로 송부해야 한다.', 789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1340, '⑩ 제4항ㆍ제5항 및 제7항은 사건송치 전에 영장등을 신청하거나 신병지휘건의 등을 하는 경우에 영장등의 신청서류 및 신병지휘건의서류 등의 편철, 간인 및 면수 표시 방법에 관하여도 적용한다.', 789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1341, '① 특별사법경찰관은 영상녹화를 실시한 경우 사건 송치 시 봉인된 영상녹화물을 기록과 함께 송부해야 한다.', 790);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1342, '② 특별사법경찰관은 영상녹화물을 송부하는 경우에는 송치서 표지의 비고란에 영상녹화물의 종류와 개수를 표시해야 한다.', 790);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1343, '① 특별사법경찰관이 참고인중지의견으로 사건을 송치할 때에는 별지 제137호서식의 참고인 등 소재수사 지휘부를 작성하여 별도로 편철하여 관리하고, 그 사본 1부를 수사기록에 편철해야 한다.', 792);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1344, '② 특별사법경찰관리는 분기마다 1회 이상 참고인 등에 대한 소재수사를 행해야 한다. 다만, 검사가 특별사법경찰관의 송치의견과 다른 결정을 한 경우에는 참고인 등 소재수사 지휘부에 그 취지를 기재하고 소재수사를 하지 않을 수 있다.', 792);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1345, '① 특별사법경찰관리는 사건을 송치한 후에 해당 사건을 계속 수사하려는 경우에는 미리 주임검사의 지휘를 받아야 한다.', 794);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1346, '② 특별사법경찰관리는 사건을 송치한 후에 해당 사건의 피의자가 저지른 다른 범죄의 혐의를 발견한 경우에는 즉시 주임검사에게 보고하고 지휘를 받아야 한다.', 794);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1347, '① 특별사법경찰관은 다음 각 호의 어느 하나에 해당하는 경우에는 즉시 수사에 착수하고 관할 지방검찰청 또는 지청의 검사에게 그 사실을 보고해야 한다.', 795);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1348, '② 사법경찰관은 제1항에 따른 보고를 하는 경우에는 다음 각 호의 서식에 따른다.', 795);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1349, '③ 특별사법경찰관은 기소중지된 피의자가 다른 기관에서 검거된 경우에는 즉시 그 피의자에 대한 체포영장의 집행ㆍ호송 등 필요한 조치를 취해야 한다.', 795);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1350, '④ 특별사법경찰관은 참고인중지의 경우 그 참고인이 교도소, 구치소 등에 구금되어 있는 것을 확인했을 때에는 즉시 검사의 지휘를 받아 출장조사, 공조수사 촉탁 등 필요한 조치를 해야 한다.', 795);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1351, '⑤ 특별사법경찰관은 제1항에 따라 수사에 착수한 경우에는 별지 제141호서식의 피의자 등 소재발견처리부에 이를 적어야 한다.', 795);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1352, '① 특별사법경찰관이 수사촉탁을 하는 경우에는 촉탁사항을 구체적으로 기재한 별지 제142호서식의 촉탁서에 수사진행 상황을 알 수 있는 수사기록 원본 또는 사본의 전부나 일부를 첨부하여 발송한다.', 796);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1353, '② 수탁관서는 촉탁사항에 대한 수사를 완료한 후 별지 제143호서식의 회답서를 작성하여 관계 서류 전부와 함께 신속히 송부해야 한다.', 796);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1354, '① 특별사법경찰관은 범죄사건을 접수하거나 입건ㆍ수사 또는 송치하는 경우에는 별지 제144호서식의 범죄사건부에 접수일시, 접수구분, 수사담당자, 피의자, 죄명, 범죄일시, 장소, 피해정도, 피해자 등을 기재해야 한다.', 798);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1355, '② 특별사법경찰관은 압수물건이 있는 경우에는 별지 제145호서식의 압수부에 압수연월일, 압수 물건의 품종, 수량 등을 기재해야 한다.', 798);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1356, '① 특별사법경찰사무를 처리하는 행정기관은 다음 각 호의 장부와 서류를 비치해야 한다. 다만, 제22호부터 제35호까지의 규정에 따른 장부와 서류를 비치해야 하는 기관은 「통신비밀보호법」 제5조에 따른 범죄의 수사를 직무로 하는 기관으로 한정한다.', 800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1357, '② 특별사법경찰관은 미리 제1항제20호의 체포ㆍ구속인명부 및 같은 항 제41호의 범죄사건부의 매 장마다 관할 지방검찰청 검사장 또는 지청장의 간인을 받아야 한다.', 800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1358, '① 특별사법경찰사무를 처리하는 행정기관이 형사사법정보시스템 또는 형사사법정보시스템에 준하는 시스템(「형사사법절차 전자화 촉진법」에 따른 형사사법정보시스템에 준하여 같은 법 제2조에 따른 형사사법정보를 작성, 취득, 저장, 저장 및 관리하는 데 이용할 수 있도록 구현된 것으로서 시스템의 각 기능 및 운영 상황 등에 대해 검찰총장이나 관할 지방검찰청 검사장 또는 지청장의 점검을 받은 시스템을 말한다)을 갖춘 경우에는 제122조제1항제41호의 범죄사건부를 전자적으로 관리할 수 있다. 이 경우 전자적으로 관리하는 범죄사건부에 대해서는 같은 조 제2항을 적용하지 않는다.', 801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1359, '② 제1항 전단에 따라 전자적으로 관리하는 범죄사건부는 별지 제144호서식의 개별 항목을 포함해야 한다.', 801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1360, '① 서류철에는 색인목록을 붙여야 한다.', 809);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1361, '② 서류를 철한 후 일부를 빼낼 때에는 그 색인목록의 비고란에 그 연월일과 사유를 기재하고 담당 특별사법경찰관이 날인해야 한다.', 809);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1362, '① 특별사법경찰사무에 관한 장부와 서류철은 해마다 갱신해야 한다.', 811);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1363, '② 제1항에도 불구하고 계속 사용할 필요가 있는 경우에는 해마다 갱신하지 않고 사용할 수 있다. 이 경우 연도 구분을 명백히 표시해야 한다.', 811);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1364, null, 812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1365, '① 제134조에 따른 보존기간은 사건처리를 완결하거나 최종절차를 마친 다음 해 1월 1일부터 기산한다.', 813);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1366, '② 보존기간이 경과한 장부와 서류철은 폐기목록을 작성한 후 폐기해야 한다.', 813);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1367, '③ 제3항에 따라 장부와 서류철을 폐기하는 경우에는 「공공기록물 관리에 관한 법률 시행령」 제43조에 따라 해당 기관 기록물관리 전문요원의 심사 및 기록물평가심의회의 심의 절차를 거쳐야 한다.', 813);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1368, '①호송은 피호송자를 받아야 할 관서 또는 출두하여야 할 장소와 유치할 장소에 곧바로 호송한다. <개정 2011.1.4>', 816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1369, '②호송은 필요에 의하여 차례로 여러곳을 거쳐서 행할 수 있다.', 816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1370, '①발송관서는 호송관에게 피호송자를 인도하는 동시에 별지 서식의 호송장 기타 필요한 서류를 내어주어야 한다.', 817);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1371, '②교도관이 호송하는 때에는 신분장 및 영치금품 송부서를 호송장으로 대용할 수 있다.', 817);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1372, null, 819);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1373, '①피호송자의 숙박은 열차ㆍ선박 및 항공기를 제외하고는 경찰관서 또는 교정시설을 이용하여야 하며, 숙박의뢰를 받은 경찰관서의 장 또는 교정시설의 장은 부득이 한 경우를 제외하고는 이를 거절할 수 없다. <개정 2011.1.4, 2018.2.20>', 821);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1374, '②제1항에 의하기 곤란한 때에는 다른 숙소를 정할 수 있다. <개정 2011.1.4>', 821);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1375, '①피호송자가 법령에 의하여 필요한 물품을 자신의 비용으로 구입할 수 있는 때에는 호송관은 물품의 구매를 허가할 수 있다. <개정 2011.1.4>', 822);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1376, '②제1항의 구매품의 대가를 제6조제2호의 금전중에서 지출할 때에는 호송관은 본인의 확인서를 받아야 한다. <개정 2011.1.4>', 822);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1377, '①피호송자가 도주한 때에는 호송관은 즉시 그 지방 및 인근 경찰관서와 호송관서에 통지하여야 하며, 호송관서는 관할 지방검찰청, 사건소관 검찰청, 호송을 명령한 관서, 발송관서 및 수송관서에 통지하여야 한다. <개정 2011.1.4>', 823);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1378, '②제1항의 경우에는 서류와 금품은 발송관서에 반환하여야 한다. <개정 2011.1.4>', 823);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1379, '①피호송자가 질병에 걸렸을 때에는 적당한 치료를 하여야 하며, 호송을 계속할 수 없다고 인정한 때에는 피호송자를 그 서류 및 금품과 함께 인근 교정시설 또는 경찰관서에 일시 유치할 수 있다. <개정 2011.1.4, 2018.2.20>', 824);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1380, '② 제1항에 따라 피호송자를 유치한 관서는 피호송자의 치료 등에 적극 협조하여야 한다. <개정 2011.1.4>', 824);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1381, '③질병이 치유된 때에는 제1항의 관서는 즉시 호송을 계속 진행하고 발송관서에 통지해야 한다. <개정 2021.1.5>', 824);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1382, '① 피호송자가 사망한 경우 호송관서는 사망지 관할 검사의 지휘에 따라 그 인근 경찰관서 또는 교정시설의 협조를 얻어 피호송자의 사망에 따른 업무를 처리한다. <개정 2018.2.20>', 825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1383, '② 피호송자가 열차ㆍ선박 또는 항공기에서 사망한 경우 호송관서는 최초 도착한 곳의 관할 검사의 지휘에 따라 그 인근 경찰관서 또는 교정시설의 협조를 얻어 제1항에 따른 업무를 처리한다. <개정 2018.2.20>', 825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1384, '③ 호송관서는 피호송자가 사망한 즉시 발송관서ㆍ수송관서 및 사망자의 가족(가족이 없는 경우 다른 친족을 말한다. 이하 이 조에서 같다)에게 사망일시, 장소 및 원인 등을 통지하여야 한다.', 825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1385, '④ 제3항에 따른 통지를 받을 가족이 없거나, 통지를 받은 가족이 통지를 받은 날부터 3일 내에 그 시신을 인수하지 않으면 임시로 매장하여야 한다.', 825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1386, '①호송관의 여비나 피호송자의 호송비용은 호송관서가 부담한다. 다만, 피호송자를 교정시설이나 경찰관서에 숙식하게 한 때에는 그 비용은 교정시설이나 경찰관서가 부담한다. <개정 2018.2.20>', 826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1387, '②제11조와 제12조에 의한 비용은 각각 그 교부를 받은 관서가 부담한다.', 826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1388, '① 이 법에서 "마약류"란 「마약류 관리에 관한 법률」 제2조제2호에 따른 마약, 같은 조 제3호에 따른 향정신성의약품 및 같은 조 제4호에 따른 대마를 말한다. <개정 2011.6.7>', 830);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1389, '② 이 법에서 "마약류범죄"란 다음 각 호의 죄[그 죄와 다른 죄가 「형법」 제40조에 따른 상상적 경합(想像的 競合) 관계에 있는 경우에는 그 다른 죄를 포함한다]를 말한다.', 830);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1390, '③ 이 법에서 "불법수익"이란 마약류범죄의 범죄행위로 얻은 재산, 그 범죄행위의 보수(報酬)로 얻은 재산이나 「마약류 관리에 관한 법률」 제60조제1항제1호 또는 제61조제1항제1호(미수범을 포함한다)의 죄에 관계된 자금을 말한다. <개정 2011.6.7>', 830);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1391, '④ 이 법에서 "불법수익에서 유래한 재산"이란 불법수익의 과실(果實)로서 얻은 재산, 불법수익의 대가(對價)로서 얻은 재산, 이들 재산의 대가로서 얻은 재산, 그 밖에 불법수익의 보유 또는 처분으로 얻은 재산을 말한다.', 830);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1392, '⑤ 이 법에서 "불법수익등"이란 불법수익, 불법수익에서 유래한 재산 및 그 재산과 그 재산 외의 재산이 합하여진 재산을 말한다.', 830);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1393, '① 출입국관리 공무원은 「출입국관리법」 제11조제1항제1호에 해당하는 사람으로 의심되는 외국인으로부터 입국허가 신청을 받은 경우, 마약류의 분산 및 그 외국인의 도주를 방지하기 위하여 충분한 감시체제가 확보되어 있는 마약류범죄의 수사에 관하여 그 외국인을 입국시킬 필요가 있다는 검사의 요청이 있을 때에는 법무부장관의 승인을 받아 「출입국관리법」 제11조제1항제1호에도 불구하고 그 외국인의 입국을 허가할 수 있다.', 831);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1394, '② 출입국관리 공무원은 「출입국관리법」 제11조제1항제1호에 해당하는 사람으로 의심되는 외국인으로부터 같은 법 제14조제1항에 따른 상륙허가 신청을 받은 경우, 마약류의 분산 및 그 외국인의 도주를 방지하기 위하여 충분한 감시체제가 확보되어 있는  마약류범죄의 수사에 관하여 그 외국인을 상륙시킬 필요가 있다는 검사의 요청이 있을 때에는 법무부장관의 승인을 받아 같은 법 제14조제1항 단서에도 불구하고 그 외국인의 상륙을 허가할 수 있다.', 831);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1395, '③ 출입국관리 공무원은 제1항에 따른 입국허가 또는 제2항에 따른 상륙허가를 받은 외국인에 대하여 검사로부터 계속 대한민국에 체류하도록 하는 것이 적당하지 아니하다는 통보를 받았을 때에는 즉시 그 외국인의 입국 또는 상륙 당시 그 외국인이 「출입국관리법」 제11조제1항제1호에 해당하였는지를 심사하여야 한다.', 831);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1396, '④ 출입국관리 공무원은 제3항에 따른 심사 결과 그 외국인이 「출입국관리법」 제11조제1항제1호에 해당한다고 인정할 때에는 법무부장관의 승인을 받아 그 외국인에 대한 입국허가 또는 상륙허가를 취소하여야 한다.', 831);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1397, '⑤ 사법경찰관은 제1항부터 제3항까지의 규정에 따라 요청 또는 통보를 할 것을 검사에게 신청할 수 있다. 이 경우 신청을 받은 검사가 제1항부터 제3항까지의 규정에 따른 요청 또는 통보를 한다.', 831);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1398, '① 세관장은 「관세법」 제246조에 따라 화물을 검사할 때에 화물에 마약류가 감추어져 있다고 밝혀지거나 그러한 의심이 드는 경우, 그 마약류의 분산을 방지하기 위하여 충분한 감시체제가 확보되어 있는 마약류범죄의 수사에 관하여 그 마약류가 외국으로 반출되거나 대한민국으로 반입될 필요가 있다는 검사의 요청이 있을 때에는 다음 각 호의 조치를 할 수 있다. 다만, 그 조치를 하는 것이 관세 관계 법령의 입법 목적에 비추어 타당하지 아니하다고 인정할 때에는 요청한 검사와의 협의를 거쳐 그 조치를 하지 아니할 수 있다.', 832);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1399, '② 제1항(같은 항 제1호는 제외한다)은 「관세법」 제257조에 따라 우편물을 검사할 때에 그 물건에 마약류가 감추어져 있는 것이 밝혀지거나 그러한 의심이 드는 경우에 준용한다. 이 경우 그 마약류에 대하여는 「관세법」 제240조를 적용하지 아니한다.', 832);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1400, '③ 사법경찰관은 제1항 및 제2항에 따라 요청을 할 것을 검사에게 신청할 수 있다. 이 경우 검사가 제1항 및 제2항에 따른 요청을 한다.', 832);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1401, '① 「금융실명거래 및 비밀보장에 관한 법률」 제2조제1호에 따른 금융회사등(이하 "금융회사등"이라 한다)에 종사하는 사람으로서 같은 조 제3호에 따른 금융거래를 수행하는 사람은 그 업무를 하면서 수수(收受)한 재산이 불법수익등임을 알게 되었을 때 또는 그 업무에 관계된 거래 상대방이 제7조의 죄에 해당하는 행위를 하였음을 알게 되었을 때에는 다른 법령의 규정에도 불구하고 지체 없이 대통령령으로 정하는 바에 따라 서면으로 검찰총장에게 신고하여야 한다. <개정 2011.7.14>', 833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1402, '② 제1항의 경우 금융회사등에 종사하는 사람은 같은 항에 따라 신고를 하려고 하거나 신고한 경우, 그 사실을 그 신고에 관련된 거래 상대방 및 그 거래 상대방과 관계된 자에게 누설하여서는 아니 된다. <개정 2011.7.14>', 833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1403, '① 「마약류관리에 관한 법률」 제58조(같은 조 제4항은 제외한다), 제59조제1항부터 제3항까지(같은 조 제1항제1호부터 제4호까지 및 제9호에 관련된 행위만 해당하며, 같은 항 제4호 중 향정신성의약품은 제외한다) 또는 제60조제1항제4호(상습범 및 미수범을 포함한다)에 해당하는 행위를 업(業)으로 한 자(이들 행위와 제9조에 해당하는 행위를 함께 하는 것을 업으로 한 자를 포함한다)는 사형, 무기징역 또는 10년 이상의 징역에 처한다. 이 경우 1억원 이하의 벌금을 병과(倂科)한다. <개정 2011.6.7>', 834);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1404, '② 「마약류관리에 관한 법률」 제59조제1항부터 제3항까지(같은 조 제1항제4호부터 제7호까지 및 제10호부터 제13호까지의 규정에 관련된 행위만 해당하며, 같은 항 제4호 중 마약은 제외한다) 또는 제60조제1항제2호(미수범 및 상습범을 포함한다)ㆍ제3호(미수범 및 상습범을 포함한다)에 해당하는 행위를 업으로 한 자(이들 행위와 제9조에 해당하는 행위를 함께 하는 것을 업으로 한 자를 포함한다)는 3년 이상의 유기징역에 처한다. 이 경우 3천만원 이하의 벌금을 병과한다. <개정 2011.6.7>', 834);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1405, '① 마약류범죄의 발견 또는 불법수익등의 출처에 관한 수사를 방해하거나 불법수익등의 몰수를 회피할 목적으로 불법수익등의 성질, 소재(所在), 출처 또는 귀속(歸屬) 관계를 숨기거나 가장(假裝)한 자는 7년 이하의 징역 또는 3천만원 이하의 벌금에 처하거나 이를 병과할 수 있다.', 835);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1406, '② 제1항의 미수범은 처벌한다.', 835);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1407, '③ 제1항의 죄를 범할 목적으로 예비하거나 음모한 자는 2년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 835);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1408, '① 마약류범죄(마약류의 수입 또는 수출에 관련된 것으로 한정한다)를 범할 목적으로 마약류로 인식하고 교부받거나 취득한 약물 또는 그 밖의 물품을 수입하거나 수출한 자는 3년 이상의 유기징역에 처한다.', 837);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1409, '② 마약류범죄(마약류의 양도ㆍ양수 또는 소지에 관련된 것으로 한정한다)를 범할 목적으로 약물이나 그 밖의 물품을 마약류로 인식하고 양도ㆍ양수하거나 소지한 자는 5년 이하의 징역 또는 500만원 이하의 벌금에 처한다. <개정 2011.5.19>', 837);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1410, '① 다음 각 호에 해당하는 재산은 몰수한다. 다만, 제7조제1항ㆍ제2항 또는 제8조의 죄가 불법수익 또는 불법수익에서 유래한 재산과 이들 재산 외의 재산이 합하여진 재산에 관계된 경우 그 범죄에 대하여 제3호부터 제5호까지의 규정에 따른 재산의 전부를 몰수하는 것이 타당하지 아니하다고 인정되는 경우에는 그 일부만을 몰수할 수 있다.', 841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1411, '② 제1항에 따라 몰수하여야 할 재산의 성질, 사용 상황 또는 그 재산에 관한 범인 외의 자의 권리 유무, 그 밖의 사정을 고려한 결과 그 재산을 몰수하는 것이 타당하지 아니하다고 인정할 때에는 제1항에도 불구하고 몰수하지 아니할 수 있다.', 841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1412, '③ 다음 각 호의 어느 하나에 해당하는 재산은 몰수할 수 있다.', 841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1413, '① 제13조에 따른 몰수는 불법재산 또는 혼합재산이 범인 외의 자에게 귀속되지 아니한 경우로 한정한다. 다만, 범인 외의 자가 범죄 후 그 정황을 알면서 그 불법재산 또는 혼합재산을 취득한 경우(그 불법재산 또는 혼합재산의 취득이 제8조 단서에 따른 불법수익등의 수수에 해당하는 경우는 제외한다)에는 그 불법재산 또는 혼합재산이 범인 외의 자에게 귀속된 경우에도 그 재산을 몰수할 수 있다.', 843);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1414, '② 지상권ㆍ저당권 또는 그 밖의 권리가 그 위에 존재하는 재산을 제13조에 따라 몰수하는 경우, 범인 외의 자가 범죄 전에 그 권리를 취득한 때 또는 범인 외의 자가 범죄 후 그 정황을 알지 못하고 그 권리를 취득한 때에는 그 권리를 존속시킨다.', 843);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1415, '① 제13조제1항에 따라 몰수하여야 할 재산을 몰수할 수 없거나 같은 조 제2항에 따라 몰수하지 아니하는 경우에는 그 가액(價額)을 범인으로부터 추징(追徵)한다.', 844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1416, '② 제13조제3항에 따른 재산을 몰수할 수 없거나 그 재산의 성질, 사용 상황 또는 그 재산에 관한 범인 외의 자의 권리 유무, 그 밖의 사정을 고려한 결과 그 재산을 몰수하는 것이 타당하지 아니하다고 인정할 때에는 그 가액을 범인으로부터 추징할 수 있다.', 844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1417, '① 법인의 대표자나 법인 또는 개인의 대리인, 사용인, 그 밖의 종업원이 그 법인 또는 개인의 업무에 관하여 제6조부터 제8조까지, 제9조제2항, 제10조 또는 제11조의 어느 하나에 해당하는 위반행위를 하면 그 행위자를 벌하는 외에 그 법인 또는 개인에게도 해당 조문의 벌금형을 과(科)한다. 다만, 법인 또는 개인이 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다.', 846);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1418, '② 법인의 대표자나 법인 또는 개인의 대리인, 사용인, 그 밖의 종업원이 그 법인 또는 개인의 업무에 관하여 제9조제1항의 위반행위를 하면 그 행위자를 벌하는 외에 그 법인 또는 개인에게도 1억원 이하의 벌금형을 과한다. 다만, 법인 또는 개인이 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다.', 846);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1419, '① 몰수된 재산은 검사가 처분하여야 한다.', 848);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1420, '② 검사는 채권에 대한 몰수재판이 확정된 경우 그 채권의 채무자에게 몰수재판의 초본을 송부하여 그 요지를 통지하여야 한다.', 848);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1421, '① 권리를 이전할 때에 등기 또는 등록(이하 "등기등"이라 한다)이 필요한 재산을 몰수하는 재판에 따른 권리 이전 등의 등기등은 검사가 촉탁한다.', 849);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1422, '② 검사가 제1항에 따른 등기등을 관계 기관에 촉탁하는 경우, 몰수에 의하여 효력을 잃은 처분의 제한에 관련된 등기등 또는 몰수에 의하여 소멸된 권리의 취득에 관련된 등기등이 되어 있거나 그 몰수에 관하여 제6장제1절에 따라 몰수보전명령(沒收保全命令) 또는 부대보전명령(附帶保全命令)에 관련된 등기등이 되어 있을 때에는 그 등기등의 말소도 각각 촉탁한 것으로 본다.', 849);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1423, '① 검사가 공소를 제기할 때에는 이 법에 따라 피고인 외의 자의 재산이나 지상권ㆍ저당권 또는 그 밖의 권리가 그 위에 존재하는 재산에 대하여 몰수가 필요하다고 인정하는 경우에는 즉시 그 재산을 가진 자나 그 재산상에 지상권ㆍ저당권 또는 그 밖의 권리를 가진 자로서 피고인 외의 자(이하 "제3자"라 한다)에게 서면으로 다음 사항을 고지하여야 한다.', 851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1424, '② 검사는 제3자의 소재를 알 수 없거나 그 밖의 사유로 제1항에 따른 고지를 할 수 없을 때에는 제1항 각 호의 사항을 관보 또는 일간신문에 싣고 소속 지방검찰청 또는 지청, 고위공직자범죄수사처의 게시판에 14일간 게시하여 공고하여야 한다. <개정 2021.1.5>', 851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1425, '③ 검사가 제1항이나 제2항에 따른 고지 또는 공고를 하였을 때에는 그 사실을 증명하는 서면을 법원에 제출하여야 한다.', 851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1426, '① 몰수될 염려가 있는 재산을 가진 제3자는 제1심재판이 있기 전까지(약식절차에 따른 재판이 있는 경우에는 정식재판 청구가 가능한 기간이 지나기 전까지를 말하며, 이 경우 정식재판 청구가 있을 때에는 통상의 공판절차에 따른 제1심재판이 있기 전까지를 말한다. 이하 같다) 피고인에 대한 형사사건이 계속 중인 법원에 대하여 서면으로 피고인에 대한 형사사건 절차에 대한 참가신청을 할 수 있다. 다만, 제23조제1항 또는 제2항에 따른 고지 또는 공고가 있은 때에는 고지 또는 공고가 있었던 날부터 14일 이내에 참가신청을 할 수 있다.', 852);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1427, '② 제23조제3항에 따라 고지 또는 공고에 관한 서면을 제출받은 법원이 피고인에 대한 형사사건을 다른 법원에 이송한 후에 참가신청을 받았을 때에는 피고인에 대한 형사사건을 이송받은 법원에 그 신청서면을 송부하여야 한다. 이 경우에는 피고인에 대한 형사사건을 이송한 법원에 대하여 참가신청을 한 때에 참가신청을 한 것으로 본다.', 852);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1428, '③ 법원은 제3자의 참가신청이 다음 각 호의 어느 하나에 해당하는 경우에는 기각하여야 한다. 다만, 제1항 단서에 따른 기간에 참가신청을 하지 아니한 것이 신청인의 책임으로 돌릴 수 없는 사유에 의한 것이라고 인정할 때에는 제1심재판이 있기 전까지 참가를 허가할 수 있다.', 852);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1429, '④ 법원은 제3항 각 호의 경우를 제외하고는 참가신청을 허가하여야 한다. 다만, 몰수가 불가능하거나 불필요하다는 검사의 의견이 타당하다고 인정할 때에는 참가신청을 기각할 수 있다.', 852);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1430, '⑤ 법원이 참가를 허가한 경우 몰수하여야 할 재산이나 몰수하여야 할 재산상에 존재하는 지상권ㆍ저당권 또는 그 밖의 권리가 참가가 허가된 사람(이하 이 장에서 "참가인"이라 한다)에게 귀속하지 아니함이 명백하게 되었을 때에는 참가를 허가한 재판을 취소하여야 하며, 몰수가 불가능하거나 불필요하다는 검사의 의견이 타당하다고 인정할 때에는 참가를 허가한 재판을 취소할 수 있다.', 852);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1431, '⑥ 참가에 관한 재판은 검사, 참가신청인, 참가인, 피고인 또는 변호인의 의견을 듣고 결정하여야 한다.', 852);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1432, '⑦ 검사, 참가신청인 또는 참가인은 참가신청을 기각한 결정 또는 참가를 허가한 재판을 취소한 결정에 대하여 즉시항고(卽時抗告)할 수 있다.', 852);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1433, '⑧ 참가신청의 취하(取下)는 서면으로 하여야 한다. 다만, 공판기일에는 말로써 할 수 있다.', 852);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1434, '① 참가인은 이 법에 특별한 규정이 있는 경우를 제외하고는 몰수에 관하여 피고인과 동일한 소송상(訴訟上)의 권리를 가진다.', 853);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1435, '② 제1항은 참가인을 증인으로서 신문(訊問)하는 것을 방해하지 아니한다.', 853);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1436, '① 참가인은 공판기일에 출석하지 아니하여도 된다.', 854);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1437, '② 법원이 참가인의 소재를 알 수 없을 때에는 공판기일의 통지나 그 밖의 서류의 송달을 하지 아니하여도 된다.', 854);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1438, '③ 법원은 공판기일에 출석한 참가인에게 몰수의 이유가 되는 사실의 요지, 참가 전의 공판기일에 있어서의 심리(審理)에 관한 중요한 사항, 그 밖에 참가인의 권리를 보호하기 위하여 필요하다고 인정하는 사항을 고지하고, 몰수에 관하여 진술할 기회를 주어야 한다.', 854);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1439, '① 참가인의 참가는 「형사소송법」 제310조의2, 제311조부터 제318조까지, 제318조의2 및 제318조의3을 적용하는 데 영향을 미치지 아니한다.', 855);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1440, '② 법원은 「형사소송법」 제318조 및 제318조의3 본문에 따라 증거로 하는 것이 가능한 서면 또는 진술을 조사한 경우, 참가인이 그 서면 또는 진술의 내용이 된 진술을 한 사람을 증인으로 조사할 것을 청구하였을 때에는 참가인의 권리 보호에 필요하다고 인정하면 이를 조사하여야 한다. 참가인이 참가하기 전에 조사한 증인에 대하여 참가인이 다시 그 조사를 청구한 경우에도 또한 같다.', 855);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1441, null, 856);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1442, '① 원심의 참가인은 상소심(上訴審)에서도 참가인으로서의 지위를 가진다.', 857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1443, '② 참가인이 상소를 하면 검사 또는 피고인이 상소를 하지 아니하거나 상소의 포기 또는 취하를 한 경우에도 원심재판 중 몰수에 관한 부분은 확정되지 아니한다.', 857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1444, '③ 제2항의 경우 피고인은 상소심 및 그 후의 심급(審級)에서는 공판기일에 출석하지 아니하여도 된다. 이 경우 「형사소송법」 제33조ㆍ제282조 및 제283조는 적용하지 아니한다.', 857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1445, '④ 약식절차에 의한 재판에 대하여 참가인이 정식재판을 청구한 경우에는 제2항 및 제3항을 준용한다.', 857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1446, '① 이 법에 따라 피고인에 대한 형사사건 절차에 관여하는 제3자는 변호사 중에서 대리인을 선임하여 소송행위를 대리하게 할 수 있다. 이 경우에는 「형사소송법」 제32조제1항 및 제35조를 준용한다.', 858);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1447, '② 대리인은 참가인의 서면에 의한 동의가 없으면 참가의 취하, 정식재판 청구의 취하, 상소의 포기 또는 취하를 할 수 없다.', 858);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1448, '① 제3자의 소송능력에 관하여는 「형사소송법」 제26조부터 제28조까지의 규정을 준용하고, 제3자의 소송비용부담에 관하여는 같은 법 제186조 및 제191조를 준용한다.', 859);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1449, '② 제23조제1항에 따른 재산을 몰수하는 절차에 관하여는 이 법에 특별한 규정이 있는 경우를 제외하고는 「형사소송법」을 준용한다.', 859);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1450, '① 법원은 마약류범죄 등에 관련된 피고인에 대한 형사사건에 관하여 이 법, 「마약류관리에 관한 법률」, 그 밖의 법령에 따라 몰수할 수 있는 재산(이하 "몰수대상재산"이라 한다)에 해당한다고 판단할 만한 상당한 이유가 있고 그 재산을 몰수하기 위하여 필요하다고 인정하면 검사의 청구를 받아 또는 법원의 직권으로 몰수보전명령을 함으로써 그 재산에 관한 처분을 금지할 수 있다.', 861);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1451, '② 법원은 지상권ㆍ저당권 또는 그 밖의 권리가 그 위에 존재하는 재산에 대하여 몰수보전명령을 한 경우 또는 하려는 경우, 그 권리가 몰수에 의하여 소멸된다고 볼만한 상당한 이유가 있고 그 재산을 몰수하기 위하여 필요하다고 인정할 때 또는 그 권리가 가장된 것이라고 볼 만한 상당한 이유가 있다고 인정할 때에는 검사의 청구에 의하여 또는 법원의 직권으로 별도의 부대보전명령을 하여 그 권리의 처분을 금지할 수 있다.', 861);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1452, '③ 몰수보전명령서 또는 부대보전명령서에는 피고인의 성명, 죄명, 공소사실의 요지, 몰수의 근거가 되는 법령의 조항, 처분을 금지하는 재산 또는 권리의 표시, 이들 재산이나 권리를 가진 자의 성명, 발급연월일, 그 밖에 대법원규칙으로 정하는 사항을 적고 재판한 법관이 서명날인하여야 한다.', 861);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1453, '④ 재판장은 긴급한 조치가 필요한 경우에는 제1항 또는 제2항에 따른 처분을 하거나 합의부의 구성원에게 그 처분을 하게 할 수 있다.', 861);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1454, '⑤ 부동산 또는 동산에 대한 몰수보전은 「형사소송법」에 따른 압수를 방해하지 아니한다.', 861);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1455, '① 검사는 제33조제1항 또는 제2항에 따른 이유와 필요가 있다고 인정하는 경우에는 공소가 제기되기 전이라도 지방법원판사에게 청구하여 같은 조 제1항 또는 제2항에 따른 처분을 받을 수 있으며, 사법경찰관은 검사에게 신청하여 검사의 청구로 처분을 받을 수 있다.', 862);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1456, '② 사법경찰관은 몰수보전명령 또는 부대보전명령이 내려진 경우에는 지체 없이 관계 서류를 검사에게 송부하여야 한다.', 862);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1457, '③ 제1항에 따른 청구는 검사가 소속된 지방검찰청 또는 지청 소재지를 관할하는 지방법원 또는 지원의 판사에게 하여야 하고, 고위공직자범죄수사처에 소속된 검사의 경우에는 그에 대응하는 법원의 판사에게 하여야 한다. <개정 2021.1.5>', 862);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1458, '④ 제1항에 따른 청구를 받은 판사는 몰수보전에 관하여 법원 또는 재판장과 동일한 권한을 가진다.', 862);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1459, '⑤ 검사는 제1항에 따른 몰수보전 후 공소를 제기한 경우에는 그 요지를 몰수보전명령을 받은 자(피고인은 제외한다)에게 통지하여야 한다. 다만, 그 사람의 소재가 분명하지 아니하거나 그 밖의 이유로 통지를 할 수 없을 때에는 통지를 갈음하여 그 요지를 소속 지방검찰청이나 그 지청 또는 고위공직자범죄수사처의 게시판에 7일간 게시하여 공고하여야 한다. <개정 2021.1.5>', 862);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1460, '① 몰수보전에 관한 재판은 검사의 지휘에 따라 집행한다.', 863);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1461, '② 제1항에 따른 몰수보전명령의 집행은 그 명령에 따라 처분이 금지되는 재산을 가진 자에게 그 명령의 등본이 송달되기 전에도 할 수 있다.', 863);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1462, '① 부동산의 몰수보전은 그 처분을 금지하는 내용의 몰수보전명령에 따라 한다.', 865);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1463, '② 제1항의 몰수보전명령의 등본은 부동산의 소유자에게 송달하여야 한다.', 865);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1464, '③ 부동산에 대한 몰수보전명령의 집행은 몰수보전등기를 하는 방법으로 한다.', 865);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1465, '④ 제3항의 등기는 검사가 촉탁한다.', 865);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1466, '⑤ 부동산에 대한 몰수보전의 효력은 몰수보전등기가 된 때에 발생한다.', 865);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1467, '⑥ 부동산에 대하여 등기청구권을 보전하기 위한 처분금지가처분(處分禁止假處分)의 등기가 된 후 몰수보전등기가 된 경우에 그 가처분채권자가 보전하려는 등기청구권에 따라 등기를 할 때에는 몰수보전등기에 의한 처분의 제한은 그 가처분등기에 따른 권리의 취득 또는 소멸에 영향을 미치지 아니한다.', 865);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1468, '⑦ 부동산의 몰수보전에 관하여는 「민사집행법」 제83조제2항, 제94조제2항 및 제95조를 준용한다. 이 경우 「민사집행법」 제83조제2항 중 "채무자"는 "몰수보전재산을 가진 자"로 보고, 같은 법 제94조제2항 중 "제1항" 및 같은 법 제95조 중 "제94조"는 "「마약류 불법거래 방지에 관한 특례법」 제37조제4항"으로 보며, 「민사집행법」 제95조 중 "법원"은 "검사"로 본다.', 865);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1469, '① 동산(제38조에서 규정한 것 외의 것을 말한다. 이하 이 조에서 같다)의 몰수보전은 그 처분을 금지하는 내용의 몰수보전명령에 따라 한다.', 867);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1470, '② 제1항의 몰수보전명령의 등본은 동산의 소유자(점유자가 다른 경우 그 점유자를 포함한다)에게 송달하여야 한다.', 867);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1471, '③ 「형사소송법」에 따라 압수되지 아니한 동산 또는 같은 법 제130조제1항에 따라 간수자(看守者)를 두거나 소유자 또는 적당한 자에게 보관하게 할 수 있는 동산에 관하여 몰수보전명령이 있는 때에는 검사는 공시서(公示書)를 첨부시키거나 그 밖의 적절한 방법으로 그 취지를 공시하는 조치를 하여야 한다.', 867);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1472, '④ 동산에 대한 몰수보전의 효력은 몰수보전명령 등본이 소유자에게 송달된 때에 발생한다.', 867);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1473, '① 채권의 몰수보전은 채권자에게는 채권의 처분과 영수(領收)를 금지하고, 채무자에게는 채권자에 대한 지급을 금지하는 내용의 몰수보전명령에 따라 한다.', 868);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1474, '② 제1항의 몰수보전명령 등본은 채권자 및 채무자에게 송달하여야 한다.', 868);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1475, '③ 채권에 대한 몰수보전의 효력은 몰수보전명령 등본이 채무자에게 송달된 때에 발생한다.', 868);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1476, '④ 몰수보전명령에 따라 몰수보전된 금전의 지급을 목적으로 하는 채권(이하 "금전채권"이라 한다)의 채무자(이하 제46조 및 제50조에서 "제3채무자"라 한다)는 그 채권액에 상당하는 금액을 공탁할 수 있다. 이 경우 채권자의 공탁금 출급청구권에 대하여 몰수보전집행이 된 것으로 본다.', 868);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1477, '⑤ 채권의 몰수보전에 관하여는 「민사집행법」 제228조를 준용한다. 이 경우 「민사집행법」 제228조제1항 중 "압류"는 "몰수보전"으로, "채권자"는 "검사"로 보고, 같은 조 제1항 및 제2항 중 "압류명령"은 "몰수보전명령"으로 본다.', 868);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1478, '① 제37조부터 제40조까지의 규정에 따른 재산 외의 재산권(이하 이 조에서 "그 밖의 재산권"이라 한다)의 몰수보전에 관하여는 이 조에 특별히 정한 사항을 제외하고는 채권의 몰수보전의 예에 따른다.', 869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1479, '② 그 밖의 재산권 중 채무자 또는 이에 준하는 자가 없는 경우(제3항의 경우는 제외한다) 몰수보전의 효력은 몰수보전명령 등본이 그 권리자에게 송달된 때에 발생한다.', 869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1480, '③ 그 밖의 재산권 중 권리 이전을 할 때 등기등이 필요한 경우에 관하여는 제37조제3항부터 제6항까지, 「민사집행법」 제94조제2항 및 제95조를 준용한다. 이 경우 「민사집행법」 제94조제2항 중 "제1항" 및 같은 법 제95조 중 "제94조"는 "「마약류 불법거래 방지에 관한 특례법」 제41조제3항에 따라 준용되는 제37조제4항"으로 보고, 「민사집행법」 제95조 중 "법원"은 "검사"로 본다.', 869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1481, '① 법원은 몰수보전의 이유 또는 필요가 없어지거나 몰수보전의 기간이 부당하게 길어진 때에는 검사 또는 몰수보전재산을 가진 자(그 사람이 피고인 또는 피의자인 경우에는 그 변호인을 포함한다)의 청구 또는 법원의 직권에 의한 결정으로 몰수보전명령을 취소하여야 한다.', 870);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1482, '② 법원은 검사의 청구에 의한 경우를 제외하고는 제1항의 결정을 할 때에 검사의 의견을 들어야 한다.', 870);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1483, '① 몰수보전명령은 몰수선고가 없는 재판(「형사소송법」 제327조제2호에 따른 경우는 제외한다)이 확정된 때에는 그 효력을 잃는다.', 871);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1484, '② 「형사소송법」 제327조제2호에 따른 공소기각(公訴棄却)의 판결이 있는 경우 그 판결이 확정된 날부터 30일 이내에 그 사건에 대하여 공소가 제기되지 아니한 때에는 몰수보전명령은 그 효력을 잃는다.', 871);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1485, '① 몰수보전이 된 후에 그 몰수보전의 대상이 된 부동산 또는 제38조에 따른 선박ㆍ항공기ㆍ자동차 또는 건설기계, 그 밖에 등기 또는 등록에 의하여 권리변동이 이루어지는 물건 등에 대하여 강제경매 개시가 결정된 경우 또는 그 몰수보전의 대상이 된 유체동산(有體動産)이 강제집행에 의하여 압류된 경우에는 강제집행에 의한 환가(換價) 절차는 몰수보전이 실효된 후가 아니면 진행할 수 없다.', 873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1486, '② 몰수보전된 채권에 대하여 강제집행에 의한 압류명령이 내려진 경우 그 압류채권자는 압류된 채권 중 몰수보전된 부분에 대하여는 몰수보전이 실효되지 아니하면 채권을 영수할 수 없다.', 873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1487, '③ 몰수보전이 된 후에 강제집행에 의하여 압류된 채권이 조건부 또는 기한부(期限附)이거나 반대의무의 이행과 관련되어 있거나 그 밖의 사유로 추심(推尋)하기 곤란한 경우에는 제1항을 준용한다.', 873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1488, '④ 몰수보전된 그 밖의 재산권(「민사집행법」 제251조제1항에 따른 그 밖의 재산권을 말한다)에 대한 강제집행에 관하여는 몰수보전된 채권에 대한 강제집행의 예에 따른다.', 873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1489, '① 금전채권의 제3채무자는 그 채권이 몰수보전된 후에 그 몰수보전의 대상이 된 채권에 대하여 강제집행에 의한 압류명령을 송달받았을 때에는 그 채권의 전액을 채무 이행지(履行地)를 관할하는 지방법원 또는 지원에 공탁할 수 있다.', 874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1490, '② 제3채무자가 제1항에 따른 공탁을 하였을 때에는 그 사유를 몰수보전명령을 한 법원에 신고하여야 한다.', 874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1491, '③ 제3채무자가 제1항에 따라 공탁을 하였을 때에는 집행법원은 공탁된 금액 중에서 몰수보전된 금전채권의 금액에 상당하는 부분에 관하여는 몰수보전이 실효된 때에, 그 나머지 부분에 관하여는 공탁된 때에 각각 배당 절차를 시작한다.', 874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1492, '④ 강제집행에 의하여 압류된 금전채권에 관하여 몰수보전이 된 경우 제3채무자의 공탁에 관하여는 제1항 및 제2항을 준용한다. 이 경우 "몰수보전명령을 한 법원"은 "압류명령을 한 법원"으로 본다.', 874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1493, '⑤ 제3채무자가 제1항(제4항에서 준용하는 경우를 포함한다)에 따라 공탁한 경우 「민사집행법」 제247조를 적용할 때에 같은 조 제1항제1호의 "제248조제4항"은 "「마약류 불법거래 방지에 관한 특례법」 제46조제2항(같은 조 제4항에서 준용하는 경우를 포함한다)"으로 본다.', 874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1494, '① 몰수보전되기 전에 강제경매 개시 결정 또는 강제집행에 의하여 압류된 재산에 대하여는 몰수재판을 할 수 없다. 다만, 다음 각 호의 어느 하나에 해당하면 몰수재판을 할 수 있다.', 875);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1495, '② 몰수대상재산상에 존재하는 지상권ㆍ저당권 또는 그 밖의 권리로서 부대보전명령에 따라 처분이 금지된 것에 대하여 그 처분금지 전에 강제경매 개시 결정 또는 강제집행에 의하여 압류된 경우 그 재산을 몰수할 때에는 그 권리는 존속시키는 것으로 하고 몰수의 선고와 동시에 그 취지를 선고하여야 한다. 다만, 다음 각 호의 어느 하나에 해당하면 그러하지 아니하다.', 875);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1496, '③ 강제경매 개시 결정 또는 강제집행에 의하여 압류된 재산에 대하여 몰수보전명령이 내려진 경우 그 재산에 관하여 압류채권자(피고인인 압류채권자는 제외한다)가 해당 형사사건 절차에 참가를 허가받지 못하였을 때에는 그 재산에 대하여 몰수재판을 할 수 없다. 제2항에 따른 재산의 몰수에 있어서도 또한 같다.', 875);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1497, '④ 제3항의 몰수에 관한 절차에 관하여는 제5장의 제3자 참가신청 등의 특례에 관한 규정을 준용한다.', 875);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1498, '① 법원은 강제경매 개시 결정 또는 강제집행에 의하여 압류된 재산에 대하여 몰수보전명령을 한 경우 또는 하려는 경우, 제47조제1항 단서에 따른 사유가 있다고 판단할 만한 상당한 이유가 있을 때에는 검사의 청구 또는 법원의 직권에 의한 결정으로 강제집행의 정지를 명할 수 있다.', 876);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1499, '② 검사가 제1항의 결정서 등본을 집행법원에 제출하였을 때에는 집행법원은 강제집행을 정지하여야 한다. 이 경우 「민사집행법」의 규정을 적용할 때에는 같은 법 제49조제2호의 서류가 제출된 것으로 본다.', 876);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1500, '③ 법원은 몰수보전이 실효된 때, 제1항의 이유가 없어진 때 또는 강제집행정지기간이 부당하게 길어진 때에는 검사나 압류채권자의 청구 또는 법원의 직권에 의하여 제1항의 결정을 취소하여야 한다.', 876);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1501, '④ 제3항의 경우에는 제42조제2항을 준용한다.', 876);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1502, '① 몰수보전재산상에 존재하는 담보권이 몰수보전된 후에 성립되거나 부대보전명령에 따라 처분이 금지된 경우 그 담보권의 실행(압류는 제외한다)은 몰수보전명령 또는 부대보전명령에 따른 처분금지가 실효되지 아니하면 할 수 없다.', 877);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1503, '② 담보권을 실행하기 위한 경매 절차가 시작된 후 그 담보권에 대하여 부대보전명령이 내려진 경우 검사가 그 명령의 등본을 제출하였을 때에는 집행법원은 그 절차를 정지하여야 한다. 이 경우 「민사집행법」을 적용할 때에는 같은 법 제266조제1항제5호(같은 법 제269조 및 제272조에서 준용하는 경우를 포함한다)의 문서가 제출된 것으로 본다.', 877);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1504, '① 다음 각 호의 어느 하나에 해당하는 경우 그 절차의 제한에 관하여는 제45조를 준용한다. <개정 2010.3.31, 2016.12.27>', 878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1505, '② 다음 각 호의 어느 하나에 해당하는 경우 제3채무자의 공탁에 관하여는 제46조를 준용한다.', 878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1506, '③ 다음 각 호의 어느 하나에 해당하는 경우 제3채무자의 공탁에 관하여는 제46조제1항 및 제2항을 준용한다.', 878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1507, '④ 다음 각 호의 어느 하나에 해당하는 경우 이러한 재산의 몰수제한에 관하여는 제47조를 준용한다.', 878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1508, '⑤ 다음 각 호의 어느 하나에 해당하는 경우 이러한 재산의 몰수제한에 관하여는 제47조제1항 본문을 준용한다.', 878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1509, '⑥ 몰수대상재산상에 존재하는 지상권ㆍ저당권 또는 그 밖의 권리로서 부대보전명령에 따라 처분이 금지된 것에 관하여 다음 각 호의 어느 하나에 해당하는 경우 그 재산의 몰수제한에 관하여는 제47조제2항 본문을 준용한다.', 878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1510, '⑦ 가압류된 재산에 대하여 몰수보전명령을 한 경우 또는 하려는 경우 강제집행정지에 관하여는 제48조를 준용한다.', 878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1511, '① 부대보전명령은 그 명령에 관계된 몰수보전의 효력이 존속하는 동안 그 효력이 있다.', 879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1512, '② 부대보전명령에 따른 처분금지에 관하여는 이 법에 특별한 규정이 있는 경우를 제외하고는 몰수보전에 관한 규정을 준용한다.', 879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1513, '① 법원은 마약류범죄 등에 관련된 피고인에 대한 형사사건에 관하여 제16조에 따라 추징하여야 할 경우에 해당한다고 판단할 만한 상당한 이유가 있는 경우로서 추징재판을 집행할 수 없게 될 염려가 있거나 집행이 현저히 곤란하게 될 염려가 있다고 인정할 때에는 검사의 청구에 의하여 또는 법원의 직권으로 추징보전명령을 하여 피고인에 대하여 재산의 처분을 금지할 수 있다.', 880);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1514, '② 추징보전명령은 추징재판을 집행하기 위하여 보전하는 것이 상당하다고 인정되는 금액(이하 이 조에서 "추징보전액"이라 한다)을 정한 후 특정재산에 대하여 하여야 한다. 다만, 유체동산에 관하여는 그 목적물을 특별히 정하지 아니할 수 있다.', 880);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1515, '③ 추징보전명령에는 추징보전명령의 집행정지나 집행처분의 취소를 위하여 피고인이 공탁하여야 할 금액(이하 "추징보전해방금"이라 한다)을 정하여야 한다.', 880);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1516, '④ 추징보전명령서에는 피고인의 성명, 죄명, 공소사실의 요지, 추징의 근거가 되는 법령의 조항, 추징보전액, 처분을 금지하는 재산의 표시, 추징보전해방금, 발급연월일, 그 밖에 대법원규칙으로 정하는 사항을 적고 재판한 법관이 서명날인하여야 한다.', 880);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1517, '⑤ 추징보전에 관하여는 제33조제4항을 준용한다.', 880);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1518, '① 검사는 제52조제1항에 따른 추징보전의 이유와 필요가 있다고 인정하는 경우에는 공소가 제기되기 전이라도 지방법원판사에게 청구하여 같은 항에 규정된 처분을 받을 수 있으며, 사법경찰관은 검사에게 신청하여 검사의 청구로 처분을 받을 수 있다. <개정 2020.6.9>', 881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1519, '② 사법경찰관은 추징보전명령이 내려진 경우에는 지체 없이 관계 서류를 검사에게 송부하여야 한다. <신설 2020.6.9>', 881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1520, '③ 검사는 사법경찰관에게 추징보전과 관련한 신청, 보완ㆍ수정, 취소 등의 요구를 할 수 있다. <신설 2020.6.9>', 881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1521, '④ 제3항의 요구가 있는 경우 사법경찰관은 지체 없이 검사의 요구에 따른 조치를 취하여야 한다. <신설 2020.6.9>', 881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1522, '⑤ 제1항에 따른 추징보전에 관하여는 제34조제3항 및 제4항을 준용한다. <개정 2020.6.9>', 881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1523, '① 추징보전명령은 검사의 명령에 따라 집행한다. 이 경우 검사의 명령은 「민사집행법」에 따른 가압류명령과 동일한 효력을 가진다.', 882);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1524, '② 추징보전명령의 집행은 추징보전명령 등본이 피고인 또는 피의자에게 송달되기 전에도 할 수 있다.', 882);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1525, '③ 추징보전명령의 집행에 관하여는 이 법에 특별한 규정이 있는 경우를 제외하고는 「민사집행법」이나 그 밖에 가압류집행의 절차에 관한 법령의 규정을 준용한다. 이 경우 법령에 따라 가압류명령을 한 법원이 가압류 집행법원으로서 관할하도록 되어 있는 가압류의 집행에 관하여는 제1항에 따른 명령을 한 검사가 소속하는 검찰청 또는 고위공직자범죄수사처에 대응하는 법원이 관할한다. <개정 2021.1.5>', 882);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1526, '① 추징보전해방금이 공탁된 후에 추징재판이 확정된 때 또는 가납재판(假納裁判)이 선고된 때에는 공탁된 금액의 범위에서 추징 또는 가납재판의 집행이 있은 것으로 본다.', 884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1527, '② 추징선고된 경우 공탁된 추징보전해방금이 추징금액을 초과할 때에는 법원은 그 초과액을 피고인에게 돌려주어야 한다.', 884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1528, '① 추징보전명령은 추징선고가 없는 재판(「형사소송법」 제327조제2호에 따른 경우는 제외한다)이 확정된 때에는 그 효력을 잃는다.', 886);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1529, '② 「형사소송법」 제327조제2호에 따른 공소기각의 판결이 있는 경우 추징보전명령의 효력에 관하여는 제43조제2항을 준용한다.', 886);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1530, '① 몰수보전 또는 추징보전에 관한 법원의 결정에 대하여는 항고할 수 있다.', 890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1531, '② 몰수보전 또는 추징보전에 관한 법관의 재판에 불복하는 자는 그 법관이 소속한 법원에 그 재판의 취소 또는 변경을 청구할 수 있다.', 890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1532, '③ 제2항에 따른 불복신청의 절차에 관하여는 「형사소송법」 제416조제1항에 따른 재판의 취소 또는 변경의 청구에 관련되는 절차 규정을 준용한다.', 890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1533, '① 마약류범죄 등에 해당하는 행위에 대한 외국의 형사사건에 관하여 그 외국으로부터 조약에 따라 몰수 또는 추징에 관한 확정재판의 집행이나 몰수 또는 추징을 위한 재산 보전(保全)의 공조요청이 있을 때에는 다음 각 호의 어느 하나에 해당하는 경우를 제외하고는 그 요청에 관하여 공조를 할 수 있다.', 892);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1534, '② 지상권ㆍ저당권 또는 그 밖의 권리가 설정된 재산에 관하여 몰수 확정재판의 집행공조를 할 때에 대한민국의 법령에 따라 그 재산을 몰수할 경우 그 권리를 존속시켜야 할 경우에 해당되면 그 권리를 존속시켜야 한다.', 892);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1535, '① 불법재산을 갈음하여 그 가액이 불법재산의 가액에 상당하는 재산으로서 그 재판을 받은 자가 가지는 재산을 몰수하는 확정재판의 집행에 관한 공조를 요청하는 경우, 그 확정재판은 이 법에 따른 공조 실시에 관하여는 그 자로부터 그 재산의 가액을 추징하는 확정재판으로 본다.', 893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1536, '② 불법재산을 갈음하여 그 가액이 불법재산의 가액에 상당하는 재산을 몰수하는 것을 목적으로 한 보전공조요청에 관하여도 제1항을 준용한다.', 893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1537, '① 검사는 공조요청이 몰수 또는 추징 확정재판의 집행에 관한 것일 경우에는 법원에 대하여 공조를 할 수 있는 경우에 해당하는지에 관하여 심사를 청구하여야 한다.', 895);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1538, '② 법원은 심사 결과 심사청구가 적법하지 아니하면 이를 각하하는 결정을 하여야 하고, 공조요청에 관계된 확정재판의 전부 또는 일부에 대하여 공조할 수 있는 경우에 해당하면 해당 부분에 대한 공조허가 결정을 하여야 하며, 그 전부에 대하여 공조할 수 없는 경우에 해당하면 공조거절 결정을 하여야 한다.', 895);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1539, '③ 법원은 몰수 확정재판 집행의 공조요청에 대하여 공조허가 결정을 하는 경우 제64조제2항에 따라 존속시켜야 할 권리가 있을 때에는 그 권리를 존속시키는 취지의 결정을 동시에 하여야 한다.', 895);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1540, '④ 법원은 추징 확정재판 집행의 공조요청에 대하여 공조허가 결정을 할 때에는 추징하여야 할 금액을 대한민국의 원화로 환산하여 같이 표시하여야 한다.', 895);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1541, '⑤ 법원은 제1항에 따른 심사를 할 때에 공조요청에 관련한 확정재판의 당부(當否)에 대하여는 심사할 수 없다.', 895);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1542, '⑥ 제1항에 따른 심사를 하는 경우 다음 각 호의 자(이하 "이해관계인"이라 한다)가 해당 심사청구사건의 절차에 참가하는 것을 허가하지 아니한 경우에는 공조허가 결정을 할 수 없다.', 895);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1543, '⑦ 법원은 심사청구에 관하여 결정을 할 때에는 검사 및 심사청구사건의 절차에 참가가 허가된 사람(이하 "공조심사참가인"이라 한다)의 의견을 들어야 한다.', 895);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1544, '⑧ 법원은 공조심사참가인이 말로 의견을 진술하려는 경우 또는 법원이 증인이나 감정인을 신문하는 경우에는 신문일(訊問日)을 정하여 공조심사참가인에게 지정된 신문일에 출석할 기회를 주어야 한다. 이 경우 공조심사참가인이 출석할 수 없어 신문일에 대리인을 출석시켰을 때 또는 공조심사참가인에게 서면으로 의견을 진술할 기회를 주었을 때에는 공조심사참가인에게 출석할 기회를 준 것으로 본다.', 895);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1545, '⑨ 검사는 제8항에 따른 신문일의 절차에 참여할 수 있다.', 895);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1546, '① 검사 및 공조심사참가인은 심사청구에 관한 결정에 대하여 항고할 수 있다.', 896);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1547, '② 제1항의 항고제기기간은 14일로 한다.', 896);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1548, '① 법원은 몰수 또는 추징에 관한 확정재판 집행의 공조요청에 대하여 공조허가 결정이 확정된 경우 그 몰수 또는 추징에 관한 확정재판이 취소되거나 그 밖에 그 효력이 없어진 경우에는 검사 또는 이해관계인의 청구에 의하여 결정으로 공조허가 결정을 취소하여야 한다.', 898);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1549, '② 제1항의 취소 결정이 확정되었을 때에는 「형사보상 및 명예회복에 관한 법률」에 따른 몰수 또는 추징집행으로 인한 보상의 예에 따라 보상한다. <개정 2011.5.23>', 898);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1550, '③ 제1항의 청구에 의한 결정에 관하여는 제68조를 준용한다.', 898);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1551, '① 검사는 공조요청이 몰수를 목적으로 한 보전에 관한 것일 때에는 판사에게 몰수보전명령을 청구하여야 한다. 이 경우 검사는 필요하다고 인정하면 부대보전명령을 청구할 수 있다.', 899);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1552, '② 제67조제1항의 심사청구가 있은 후에는 몰수보전에 관한 처분은 심사청구를 받은 법원이 집행한다.', 899);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1553, '① 검사는 공조요청이 추징을 목적으로 한 보전에 관한 것일 때에는 판사에게 추징보전명령을 청구하여야 한다.', 900);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1554, '② 추징보전에 관한 처분에 관하여는 제71조제2항을 준용한다.', 900);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1555, '① 몰수 또는 추징을 목적으로 하는 보전공조요청이 공소가 제기되지 아니한 사건에 대한 것인 경우에는 몰수보전명령 또는 추징보전명령이 내려진 날부터 45일 이내에 요청국으로부터 그 사건에 대하여 공소가 제기되었다는 취지의 통지가 없을 때에는 그 몰수보전명령 또는 추징보전명령은 효력을 잃는다.', 901);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1556, '② 법관은 요청국으로부터 부득이한 사유로 제1항에 따른 기간에 공소를 제기할 수 없다는 취지의 통지가 있는 때에는 검사의 청구에 의하여 30일을 초과하지 아니하는 범위에서 보전기간을 갱신할 수 있다. 부득이한 사유로 갱신된 기간에 공소를 제기할 수 없다는 취지의 통지가 있는 경우에도 또한 같다.', 901);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1557, '① 검사는 공조요청을 철회하는 취지의 통지가 있을 때에는 지체 없이 심사청구, 몰수보전청구 또는 추징보전청구를 취소하거나 몰수보전명령 또는 추징보전명령의 취소를 청구하여야 한다.', 902);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1558, '② 법원 또는 법관은 제1항에 따른 몰수보전명령 또는 추징보전명령의 취소청구가 있을 때에는 지체 없이 몰수보전명령 또는 추징보전명령을 취소하여야 한다.', 902);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1559, '① 검사는 이 장에 따른 몰수보전 또는 추징보전청구, 몰수보전명령 또는 추징보전명령의 집행에 관하여 필요하다고 인정하면 관계인의 출석을 요구하여 진술을 들을 수 있고, 감정ㆍ통역 또는 번역을 촉탁하거나 실황(實況)을 조사할 수 있으며, 서류나 그 밖의 물건의 소유자ㆍ소지자 또는 보관자에게 그 제출을 요구하거나, 공공기관이나 그 밖의 단체에 대하여 그 사실을 조회하거나 필요한 사항을 보고하도록 요구할 수 있다.', 904);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1560, '② 검사는 이 장에 따른 몰수보전 또는 추징보전의 청구, 몰수보전명령 또는 추징보전명령의 집행에 관하여 필요하다고 인정하면 지방법원판사에게 청구하여 발급받은 영장에 의하여 압수ㆍ수색 또는 검증을 할 수 있다.', 904);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1561, '③ 검사는 사법경찰관리에게 제1항 및 제2항에 따른 처분을 명할 수 있다.', 904);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1562, null, 909);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1563, null, 911);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1564, null, 912);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1565, '① 법 제7조제1항에 따라 사용자등록을 하려는 자는 형사사법포털에 접속해 다음 각 호의 유형별로 필요한 정보를 해당란에 입력한 후 전자서명을 위한 인증서(서명자의 실지명의를 확인할 수 있는 것으로서 법무부장관이 지정해 형사사법포털에 공고하는 것을 말한다. 이하 같다)로 같은 항에 따른 사용자등록(이하 "사용자등록"이라 한다)을 신청해야 한다. 이 경우 사용자등록을 한 자(이하 "등록사용자"라 한다)의 등록 정보는 인증서의 내용과 일치해야 한다.', 913);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1566, '② 제1항제2호 및 제3호의 등록사용자는 이용권한의 범위를 정해 자기 소속의 사용자를 지정할 수 있고, 그에 따라 지정된 자는 형사사법포털에 접속해 소속사용자로 등록을 할 수 있다.', 913);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1567, '③ 수사기관등은 사건기록이 전자기록으로 관리되는 사건(이하 "전자기록사건"이라 한다)에서 다음 각 호의 자에 대해 사용자등록을 할 것을 권고할 수 있다.', 913);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1568, '① 법 제7조제2항에 따라 사용자등록을 철회하려는 등록사용자는 형사사법포털에 접속해 사용자등록 철회의 취지를 입력하는 방법으로 사용자등록을 철회할 수 있다.', 914);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1569, '② 제1항에 따라 사용자등록을 철회하더라도 철회 이전에 등록사용자가 제출한 문서의 효력 및 수사기관등이 등록사용자에게 전산정보처리시스템을 통해 전자적으로 한 송달 또는 통지의 효력에는 영향을 미치지 않는다.', 914);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1570, '① 수사기관등의 장은 법 제7조제3항에 따라 등록사용자 외에 제4조제2항에 따라 등록된 소속사용자(이하 "소속사용자"라 한다)에 대해서도 전산정보처리시스템 사용을 정지하거나 소속사용자의 등록을 말소할 수 있다.', 915);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1571, '② 수사기관등의 장이 법 제7조제3항제5호에 따라 등록사용자(소속사용자를 포함한다. 이하 같다)의 전산정보처리시스템 사용을 정지하거나 사용자등록(제1항에 따른 소속사용자의 등록을 포함한다. 이하 같다)을 말소할 수 있는 사유는 다음 각 호와 같다.', 915);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1572, '③ 수사기관등의 장은 법 제7조제3항 각 호(제3호는 제외한다)의 사유에 해당하는지를 결정하기 위해 필요하다고 인정할 경우에는 말소 여부가 결정될 때까지 해당 등록사용자의 사용을 일시적으로 정지할 수 있다. 이 경우 수사기관등의 장은 등록사용자에게 전자우편이나 문자전송 서비스 등을 통해 그 사실을 통지해야 한다.', 915);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1573, '④ 수사기관등의 장은 법 제7조제3항에 따라 사용자등록을 말소(이 조 제2항제3호의 사유로 말소하는 경우는 제외한다)하기 전에 해당 등록사용자에게 미리 그 사유를 전자우편이나 문자전송 서비스 등을 통해 통지하고 소명의 기회를 부여해야 한다.', 915);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1574, '① 법 제8조제1항에 따라 수사기관등에 전자문서를 제출하려는 자는 이 영에서 달리 정하는 경우를 제외하고는 전자문서에 행정전자서명을 하거나 인증서로 전자서명을 해야 한다.', 916);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1575, '② 법 제8조제1항 본문에 따른 전자서명(서명자의 실지명의를 확인할 수 있는 것으로 한정한다)을 이용할 수 없는 자가 전자문서를 제출하려는 경우에는 해당 수사기관등으로부터 신원을 확인받은 후 컴퓨터 등 정보처리장치를 이용해 전자서명을 할 수 있다.', 916);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1576, '③ 법 제8조제1항 본문에 따른 전자서명(서명자의 실지명의를 확인할 수 있는 것으로 한정한다)을 이용할 수 없는 자가 전자문서를 제출하려는 경우에는 해당 수사기관등으로부터 신원을 확인받은 후 전자문서가 저장된 정보저장매체를 제출하는 방식으로 전자문서를 제출할 수 있다. 이 경우 전자문서를 제출받은 수사기관등의 소속 공무원은 제출받은 전자문서에 행정전자서명을 마친 후 전자문서를 전산정보처리시스템에 등재해야 한다.', 916);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1577, '④ 수사기관등의 소속 공무원은 법 제8조제3항에 따라 결정문, 조서, 보고서 등을 전자문서로 작성하는 경우에는 「전자정부법 시행령」 제30조에 따른 행정전자서명 인증서로 행정전자서명을 한 후 전산정보처리시스템에 저장해야 한다. 이 경우 법 제3조 각 호의 법률에 따른 형사사법절차에서 진술자의 서명을 필요로 하는 경우에는 신원이 확인된 진술자에게 조서 등에 전자서명을 하게 해야 한다.', 916);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1578, '① 법무부장관은 법 제9조제2항 전단에 따라 전산정보처리시스템을 통해 제출할 수 있는 전자문서의 파일 형식, 구성 방식 및 그 밖의 사항을 지정해 형사사법포털에 공고해야 한다.', 917);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1579, '② 등록사용자는 주장, 증거 또는 그 밖의 사항을 합쳐 하나의 파일로 제출해서는 안 되고, 형사사법포털에서 요구하는 방식에 따라 각각 별도의 파일로 구분하여 제출해야 한다.', 917);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1580, '③ 등록사용자는 부득이한 사정이 없는 한 문자정보의 검색 및 추출이 가능한 형식으로 전자문서를 제출해야 한다.', 917);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1581, '① 등록사용자는 형사사법포털에서 요구하는 방식에 따라 해당 사항을 입력하거나 전자문서를 등재하는 방식으로 서류를 전자문서로 작성하거나 제출할 수 있다.', 918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1582, '② 공동의 이해관계를 가진 여러 등록사용자는 다음 각 호의 어느 하나에 해당하는 방법에 따라 공동명의로 하나의 전자문서를 제출할 수 있다.', 918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1583, '③ 「공증인법」 제5장의2에 따른 인증이 부여된 전자문서를 제출하는 경우에는 그 취지와 인증의 증명에 관한 사항을 밝혀야 한다.', 918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1584, '④ 소속사용자 중 전자문서의 제출 권한을 지정받은 소속사용자는 다음 각 호의 어느 하나에 해당하는 방법으로 전자문서를 제출할 수 있다.', 918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1585, '⑤ 수사기관등의 장은 등록사용자가 제출한 전자문서의 동일성 확인을 위해 접수 당시 전자문서의 해시값(Hash value: 전자문서 파일로부터 추출된 고유의 식별값을 말한다. 이하 같다)을 저장하는 등의 기술적 조치를 해야 한다.', 918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1586, '① 전자문서를 제출한 등록사용자는 법 제9조제3항에 따라 전자문서를 제출한 날부터 14일 이내에 전자문서의 동일성 확인을 요구해야 한다.', 919);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1587, '② 수사기관등은 법 제9조제3항에 따라 등록사용자로부터 전자문서의 동일성 확인을 요구받은 경우에는 컴퓨터 등 정보처리장치를 이용해 전자문서를 열람하게 하는 방법으로 그 동일성을 확인할 수 있도록 해야 한다.', 919);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1588, '③ 수사기관등은 법 제9조제4항에 따라 등록사용자로부터 전자문서의 수정을 요구받은 경우에는 그 요구를 받은 날부터 14일 이내에 등록사용자가 제출한 전자문서와 접수된 전자문서가 동일한지를 판단하고 수정 여부를 결정해야 한다.', 919);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1589, '① 등록사용자는 형사사법포털을 통해 전자화문서를 제출하는 경우 전자화대상문서(종이문서나 그 밖에 전자적인 형태로 작성되지 않은 서류 또는 도면ㆍ사진ㆍ음성ㆍ영상자료 등을 말한다. 이하 같다)의 원본을 해당 형사사법절차가 확정될 때까지 보관해야 한다.', 920);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1590, '② 법 제9조제5항에 따라 수사기관등으로부터 전자문서 원본의 제시나 제출을 요구받은 등록사용자는 그 요구에 따라야 한다.', 920);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1591, '③ 수사기관등은 등록사용자가 법 제9조제5항에 따른 원본의 제시 또는 제출 요구에 따르지 않는 경우에는 제출된 전자화문서를 폐기할 수 있다. 이 경우 등록사용자가 요청하면 제출된 전자화문서를 폐기하기 전에 그 전자화문서를 복제해 교부할 수 있다.', 920);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1592, '① 등록사용자는 음성이나 영상정보 등 멀티미디어 방식의 자료를 형사사법포털을 통해 제출할 수 있다. 이 경우 형사사법포털에서 요구하는 방식에 따라 제출하되, 해당 자료의 주요 내용, 제출 취지 및 용량을 밝혀야 한다.', 921);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1593, '② 수사기관등은 제1항 후단에 따라 밝힌 멀티미디어 자료의 주요 내용, 제출 취지 및 용량의 기재가 충분하지 않은 경우 제출자에게 보완을 요구할 수 있다.', 921);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1594, '① 수사기관등은 변환ㆍ제출된 전자문서의 판독이 곤란하거나 그 밖에 원본을 확인할 필요가 있는 경우에는 상당한 기간을 정해 해당 전자문서를 제출한 자에 대하여 판독이 가능한 전자문서를 다시 제출하거나 원본을 제출할 것을 요구할 수 있다.', 922);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1595, '② 제1항에 따라 전자문서를 제출한 자가 판독이 가능한 전자문서 또는 원본을 다시 제출한 경우에는 전자문서를 최초로 제출한 때에 판독이 가능한 전자문서 또는 원본을 제출한 것으로 본다.', 922);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1596, '③ 등록사용자가 형사사법포털을 이용해 전자문서를 제출하여 접수된 후에는 이를 삭제하거나 내용을 수정해 다시 제출할 수 없다.', 922);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1597, '④ 수사기관등은 전자문서를 제출한 자의 의견을 들어 전자문서가 필요하지 않다고 판단한 경우에는 해당 전자문서를 폐기할 수 있다. 이 경우 전자문서를 제출한 자가 요청하면 제출된 전자문서를 폐기하기 전에 그 전자문서를 복제해 교부할 수 있다.', 922);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1598, '① 수사기관등은 「형사소송법」 제199조제2항에 따라 공무소나 그 밖의 공사단체에 자료의 제출을 요구하는 경우 전자적 송달 또는 통지의 방법으로 할 수 있다.', 923);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1599, '② 전자기록사건에서 공무소나 그 밖의 공사단체가 전자문서로 보유하고 있는 자료를 「형사소송법」 제199조제2항에 따라 제출하는 경우에는 전산정보처리시스템을 통해 제출할 수 있다.', 923);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1600, '③ 수사기관등은 공무소나 그 밖의 공사단체가 제2항에 따라 제출하는 자료가 전자문서가 아닌 경우 이를 전자문서로 변환한 후 전송해 줄 것을 요청할 수 있다.', 923);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1601, '① 법 제10조제1항 단서에 따라 전자문서로 작성하지 않을 수 있는 경우는 다음 각 호와 같다.', 924);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1602, '② 제1항에도 불구하고 수사기관등은 다음 각 호의 경우에는 전자문서로 작성하지 않은 문서를 전자문서화해야 한다.', 924);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1603, '① 수사기관등의 소속 공무원은 「형사소송법」에 따른 피의자신문조서를 컴퓨터 등 정보처리장치를 이용해 피의자에게 열람하게 할 수 있다.', 925);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1604, '② 「형사소송법」 제244조제2항에 따라 피의자가 피의자신문조서의 증감 또는 변경의 청구 등 이의를 제기하거나 의견을 진술해 이를 추가로 기재하는 경우에는 컴퓨터 등 정보처리장치를 이용해 기재하고 전자서명을 할 수 있다.', 925);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1605, '③ 제2항에도 불구하고 피의자가 종이문서에 기재할 것을 요구하는 경우에는 피의자신문조서를 출력해 종이문서로 해당 내용을 작성하고 해당 종이문서를 전자적인 형태로 변환해 전산정보처리시스템에 등재해야 한다.', 925);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1606, '④ 「형사소송법」 제244조의2제2항 및 「성폭력범죄의 처벌 등에 관한 특례법」 제30조제4항에 따른 영상녹화 후 기명날인 또는 서명 등의 절차는 영상녹화를 완료한 후 그 영상의 해시값을 전산정보처리시스템에 저장하고 당사자가 이를 확인하는 방식으로 한다.', 925);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1607, '⑤ 「형사소송법」 제312조제4항에 따른 조서를 작성하는 경우(인터넷 화상장치 등으로 조사해 작성하는 경우를 포함한다)에는 제1항부터 제4항까지의 규정을 준용한다.', 925);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1608, '① 수사기관등의 소속 공무원은 「특정범죄신고자 등 보호법」 제7조제1항에 따른 조서나 그 밖의 서류(이하 이 조에서 "조서등"이라 한다) 및 같은 조 제3항에 따른 범죄신고자등 신원관리카드(이하 이 조에서 "범죄신고자등 신원관리카드"라 한다)를 전자문서로 작성할 수 있다.', 926);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1609, '② 수사기관등의 소속 공무원은 제1항에 따라 전자문서로 작성한 조서등 및 범죄신고자등 신원관리카드에 「특정범죄신고자 등 보호법」 제2조제3호의 범죄신고자등이 같은 법에 따라 서명 또는 무인(拇印)을 해야 하는 경우에는 서명 또는 무인 대신 가명으로 전자서명을 하게 해야 한다. 이 경우 가명으로 된 전자서명은 본명(本名)의 서명과 동일한 효력이 있다.', 926);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1610, null, 927);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1611, '① 수사기관등의 소속 공무원은 전자화대상문서를 제출받은 경우 전자적인 형태로 변환하고 행정전자서명을 마친 후 전산정보처리시스템에 등재해야 한다.', 928);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1612, '② 수사기관등의 장은 법 제11조제1항에 따라 전자화대상문서를 전자적인 형태로 변환해 전산정보처리시스템에 등재하는 경우에는 접수 당시 전자화문서의 해시값을 저장하는 등의 기술적 조치를 해야 한다.', 928);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1613, '① 법 제12조제1항에 따른 전자화대상문서의 보관기간은 법 제20조제1항 각 호의 구분에 따라 정해진 때까지로 한다.', 929);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1614, '② 수사기관등은 법 제12조제2항에 따라 전자화대상문서의 반환을 요청받은 경우에는 요청을 받은 날부터 14일 이내에 전자화대상문서를 반환할 것인지를 결정해야 한다.', 929);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1615, '③ 수사기관등은 전자화대상문서를 제출한 사람에게 법 제12조제3항에 따라 전자화문서와 전자화대상문서의 동일성을 확인할 수 있는 기회를 주는 경우에는 컴퓨터 등 정보처리장치를 이용해 전자화문서를 열람하게 하는 방법으로 그 동일성을 확인할 수 있도록 해야 한다.', 929);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1616, '④ 법 제12조제3항에 따라 형사사법업무 처리기관으로부터 전자화대상문서를 반환받은 사람은 전자화대상문서의 원본을 해당 형사사법절차가 확정될 때까지 보관해야 한다.', 929);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1617, '① 수사기관등의 소속 공무원은 전자문서에 오류가 있는 것을 확인한 경우 전산정보처리시스템을 이용해 다음 각 호의 구분에 따라 이를 바로잡을 수 있다.', 930);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1618, '② 제1항에 따라 전자문서를 폐기하거나 정정한 경우에는 전자문서가 폐기 또는 정정되었다는 사실을 전산정보처리시스템에 기록하고 폐기하거나 정정하기 전의 전자문서를 저장ㆍ보관해야 한다.', 930);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1619, '③ 제1항 및 제2항의 폐기 또는 정정의 세부적인 절차 및 방법은 각 수사기관등의 장이 정한다.', 930);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1620, '① 형사사법업무 처리기관은 법 제13조제1항에 따라 전자문서를 다른 형사사법업무 처리기관에 전산정보처리시스템을 통해 송부하는 경우 특별한 사정이 없는 한 문자정보의 검색 및 추출이 가능한 형식으로 송부해야 한다.', 931);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1621, '② 제1항에 따라 송부된 전자문서는 송부받는 형사사법업무 처리기관의 전산정보처리시스템에 전자적으로 기록된 때에 접수된 것으로 본다.', 931);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1622, '③ 법 제13조제2항 본문에 따라 전산정보처리시스템을 통해 전자문서를 출력하는 경우 전산정보처리시스템에 접속해 해당 시스템에 저장된 전자문서를 출력하는 방법으로 한다. 이 경우 형사사법업무 처리기관의 장은 출력하는 서면에 고유번호가 출력되도록 하는 등 전자문서의 동일성을 확보하기 위한 기술적 조치를 해야 한다.', 931);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1623, '④ 법 제13조제2항 단서에 따라 전자문서를 전자적 방법으로 송부받을 수 있는 기관은 전자문서를 송신ㆍ수신할 수 있는 시스템을 갖춘 기관 중 형사사법절차와 관련해 전자문서의 유통 필요성이 인정되는 기관으로서 법무부장관이 지정해 형사사법포털에 공고하는 기관으로 한다.', 931);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1624, '① 법 제14조제1항제3호에 따라 전자적 송달 및 통지에 동의하여 송달 또는 통지를 전산정보처리시스템을 통해 전자적으로 받을 수 있는 등록사용자는 다음 각 호와 같다.', 932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1625, '② 수사기관등이 제1항 각 호의 등록사용자에게 전산정보처리시스템을 이용해 전자문서로 송달ㆍ통지하는 경우에는 종이문서를 송달ㆍ통지하는 것과 동일한 효력이 있다.', 932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1626, '① 법 제14조제1항 및 제2항에 따라 전자문서를 전산정보처리시스템에 등재하고 그 사실을 송달ㆍ통지하는 방법은 다음 각 호의 방식에 따른다.', 933);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1627, '② 「형사소송법」 제65조에 따라 준용되는 「민사소송법」 제182조에 따라 교도소ㆍ구치소 또는 국가경찰관서의 유치장에 체포ㆍ구속ㆍ구금 또는 유치(留置)되어 있는 사람에게 전자적 송달 또는 통지를 하는 경우에는 그 교도소ㆍ구치소 또는 국가경찰관서의 장에게 전산정보처리시스템을 통해 전자적으로 송달ㆍ통지한다.', 933);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1628, '③ 법 제14조제1항에 따라 전자적으로 송달ㆍ통지한 경우에는 다음 각 호의 구분에 따른 때에 송달ㆍ통지된 것으로 본다.', 933);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1629, '④ 제1항제2호에 따른 방법으로 송달 또는 통지를 받은 등록사용자는 형사사법포털에 접속해 전산정보처리시스템에 등재된 전자문서를 확인 또는 출력할 수 있다.', 933);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1630, '⑤ 법 제14조제4항 단서에 따라 피의자 또는 피고인 등의 형사사법절차상 권리를 보호하기 위해 필요한 경우로서 통지된 것으로 보지 않는 경우는 다음 각 호의 경우를 말한다.', 933);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1631, '⑥ 전산정보처리시스템을 이용해 송달ㆍ통지된 전자문서를 출력한 서면은 전자문서와 동일한 효력이 있다.', 933);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1632, '① 전산정보처리시스템 또는 정보통신망에 장애가 발생해 송달 또는 통지를 받을 자가 전자문서를 확인할 수 없는 기간이 1일당 1시간을 초과하는 경우에는 그 날을 법 제14조제4항 본문에 따른 기간에 산입하지 않는다.', 934);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1633, '② 제1항에도 불구하고 수사기관등이 제36조제1항에 따라 전산정보처리시스템의 점검을 위해 일시적으로 전산정보처리시스템의 사용이 중단된다는 사실을 사전에 공지한 경우로서 사용이 중단된 시간이 4시간 이내인 경우에는 그 날을 법 제14조제4항 본문에 따른 기간에 산입한다.', 934);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1634, '① 법 제15조제1항제3호에 따라 전산정보처리시스템을 통해 전자문서를 출력한 서면을 「형사소송법」 제60조부터 제65조까지의 규정에 따른 방법으로 송달해야 하는 경우는 다음 각 호와 같다.', 935);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1635, '② 법 제15조제1항에 따라 전자문서를 서면으로 출력하는 경우 전산정보처리시스템에 접속해 시스템에 저장된 전자문서를 출력하는 방법으로 한다. 이 경우 수사기관등의 장은 출력하는 서면에 고유번호가 출력되도록 하는 등 전자문서의 동일성을 확보하기 위한 기술적 조치를 해야 한다.', 935);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1636, '③ 수사기관등의 소속 공무원은 법 제15조제1항에 따라 전자문서를 출력한 서면을 송달하는 경우 「우편법」 제15조제3항에 따른 선택적 우편역무 중 법무부장관이 정하는 방식으로 송달할 수 있다.', 935);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1637, '① 등록사용자는 다음 각 호의 경우 형사사법포털에 접속해 전산정보처리시스템에 저장된 전자문서의 내용을 확인하고 이를 서면으로 출력하거나 해당 사항을 자신의 정보저장매체 등에 내려받는 방식으로 전자문서를 열람ㆍ등사 또는 복사하거나 교부받을 수 있다.', 936);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1638, '② 수사기관등은 등록사용자가 아닌 자가 제1항 각 호에 따라 전자문서 또는 전자기록의 열람ㆍ등사ㆍ복사 또는 교부를 신청하는 경우 해당 전자문서 또는 전자기록을 정보저장매체 등에 복사해 교부할 수 있다.', 936);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1639, '③ 전자문서 또는 전자기록을 열람ㆍ등사 또는 복사하거나 교부받으려는 사람이 교도소ㆍ구치소 또는 국가경찰관서의 유치장에 체포ㆍ구속ㆍ구금 또는 유치되어 있는 경우에는 전산정보처리시스템을 통해 전자문서를 출력한 서면을 교부하거나 제4항에 따른 방법으로 열람하게 한다.', 936);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1640, '④ 수사기관등은 다음 각 호의 경우에는 컴퓨터 등 정보처리장치를 이용해 전자문서를 열람하게 할 수 있다.', 936);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1641, '⑤ 제4항에도 불구하고 질병이나 부상 등의 사유로 컴퓨터 등 정보처리장치를 이용해 열람하기 어려운 경우에는 전자문서를 출력한 서면을 이용해 열람하게 할 수 있다. 이 경우 출력한 서면은 열람을 마친 후 회수한다.', 936);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1642, '⑥ 수사기관등의 장은 전자문서를 열람ㆍ등사ㆍ복사 또는 출력할 때 전산정보처리시스템에 저장된 전자문서와 동일한 전자문서가 열람ㆍ등사ㆍ복사 또는 출력될 수 있도록 해시값을 비교하거나 출력하는 서면에 고유번호가 출력되도록 하는 등의 기술적 조치를 해야 한다.', 936);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1643, '⑦ 수사기관등의 장은 전자문서를 열람ㆍ등사ㆍ복사 또는 출력할 때 개인정보의 일부 또는 전부를 삭제하거나 대체함으로써 특정 개인을 식별할 수 없도록 하는 비식별화 조치를 한 전자문서가 열람ㆍ등사ㆍ복사 또는 출력되도록 할 수 있다.', 936);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1644, '① 형사사법업무 처리기관 상호 간에 사건기록을 송부하는 경우에는 전산정보처리시스템을 통해 전자기록을 전송하는 방법으로 한다.', 937);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1645, '② 제1항에 따라 사건기록을 전송한 경우로서 법 제11조제1항 단서에 따라 변환ㆍ등재하지 않은 전자화대상문서를 보관하거나 법 제12조제1항에 따라 전자화대상문서를 보관해야 하는 경우 해당 전자화대상문서는 법령에 따라 사건기록을 보존해야 하는 형사사법업무 처리기관에서 보관한다.', 937);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1646, '③ 제2항에 따라 보관하는 전자화대상문서의 송부시기와 방법 등은 해당 형사사법업무 처리기관이 협의하여 정한다.', 937);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1647, '① 검사는 다음 각 호의 경우를 제외하고는 전산정보처리시스템을 통해 형사사법절차에 관한 법원의 전자소송시스템(이하 "전자소송시스템"이라 한다)으로 전자문서나 전자기록을 제출해야 한다.', 941);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1648, '② 검사는 법원에 제출해야 하는 문서 등이 전자문서로 작성되었으나 제1항 각 호의 어느 하나에 해당하는 경우에는 전자문서나 전자기록을 전산정보처리시스템을 통해 출력하여 제출하거나 정보저장매체에 저장하여 제출할 수 있다.', 941);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1649, '① 검사는 공판정에서 컴퓨터, 이동통신단말장치(「전파법」에 따라 할당받은 주파수를 사용하는 기간통신역무를 이용하기 위해 필요한 단말장치를 말한다. 이하 같다) 또는 그 밖에 이에 준하는 정보처리능력을 갖춘 장치로 전산정보처리시스템에 접속해 전자기록ㆍ신원관리카드 등의 열람, 공판카드의 작성, 증거의 신청ㆍ제출 등 공소유지 업무를 수행할 수 있다.', 942);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1650, '② 검사는 공판정에서 컴퓨터, 이동통신단말장치 또는 그 밖에 이에 준하는 정보처리능력을 갖춘 장치를 이용해 증거신청서, 증거 목록, 증인신문청구서, 공소장변경신청서 등 공소유지에 필요한 전자문서를 전자소송시스템으로 송부할 수 있다.', 942);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1651, '① 수사기관등은 전산정보처리시스템에 기록된 전자문서에 대해 위작ㆍ변작ㆍ훼손ㆍ유출 등을 방지하기 위한 기술적 조치(「개인정보 보호법」 제29조에 따른 안전성 확보에 필요한 조치를 포함한다)를 해야 한다.', 944);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1652, '② 수사기관등의 소속 공무원은 현장검증, 재택근무, 현장수사, 현장 지도ㆍ감독 그 밖의 업무상 필요하다고 인정되는 경우에는 수사기관등의 청사 외의 곳에서 컴퓨터, 이동통신단말장치 또는 그 밖에 이에 준하는 정보처리능력을 갖춘 장치를 이용해 전자기록을 사용할 수 있다. 이 경우 전자기록이 정당한 사유 없이 공개ㆍ위작ㆍ변작ㆍ훼손 또는 유출되지 않도록 해야 한다.', 944);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1653, '① 수사기관등의 장은 전산정보처리시스템의 점검을 위해 필요한 시간 동안 전산정보처리시스템의 이용을 일시적으로 제한할 수 있다.', 945);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1654, '② 수사기관등의 장은 전산정보처리시스템에 장애가 발생하거나 그 밖의 부득이한 사정으로 전산정보처리시스템을 사용할 수 없는 때에는 장애가 발생한 사실을, 장애를 복구한 때에는 그 복구한 사실을 각각 수사기관등의 홈페이지 및 형사사법포털에 게시해야 한다.', 945);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1655, '① 수사기관등은 법 제20조제2항에 따라 교정기관의 수용ㆍ구금ㆍ교정 또는 형집행과 관련된 전자문서나 다음 각 호의 어느 하나에 해당하는 사건의 전자기록을 영구 보관하거나 같은 조 제1항에 따른 폐기 시기를 늦출 수 있다.', 946);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1656, '② 제1항에 따라 전자문서를 영구 보관하거나 폐기 시기를 늦추려는 경우에는 「공공기록물 관리에 관한 법률 시행령」 제43조에 따른 절차를 거쳐야 한다.', 946);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1657, '① 가정보호사건 및 피해자보호명령사건을 관할하는 가정법원 및 지방법원과 그 지원의 관할구역은 다음 각 호와 같다.', 948);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1658, '② 제1항제1호에도 불구하고 서울특별시 관할구역의 「가정폭력범죄의 처벌 등에 관한 특례법」(이하 "법"이라 한다) 제8조에 따른 검사의 임시조치청구 사건의 관할 법원은 「각급 법원의 설치와 관할구역에 관한 법률」 별표 3에 따른다. 다만, 서울중앙지방법원 관할구역의 임시조치청구 사건은 서울가정법원의 관할로 한다.', 948);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1659, '③ 검사의 청구에 따라 임시조치를 결정한 사건이 다음 각 호의 어느 하나에 해당하는 경우에는 그 임시조치를 결정한 법원에 법 제29조제10항에 따른 취소ㆍ변경 신청 또는 법 제29조의2제2항에 따른 변경 신청을 할 수 있고, 그 임시조치를 결정한 법원은 법 제29조제11항에 따른 취소ㆍ변경 및 법 제29조제5항에 따른 연장을 할 수 있다.', 948);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1660, '④ 가정법원이 설치되지 아니한 지역의 지방법원과 그 지원의 단독판사 또는 합의부가 가정폭력행위자(이하 "행위자"라 한다)에 대한 피고사건을 심리한 결과 보호처분을 하는 것이 적절하다고 인정하여 법 제12조의 결정을 한 경우에는 그 결정을 한 단독판사 또는 합의부의 구성원이 가정보호사건으로 심리할 수 있다.', 948);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1661, '⑤ 가정법원이 한 배상명령에 대한 청구이의의 소는 해당 가정법원의 소재지를 관할하는 지방법원에 제기하여야 한다.', 948);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1662, '① 법 및 이 규칙에 따른 결정을 할 때에는 결정서를 작성하고 판사가 서명날인하여야 한다. 다만, 다음 각 호의 결정을 제외하고는 결정서에 기명날인할 수 있고, 결정의 내용을 조서에 기재하게 함으로써 결정서의 작성을 갈음할 수 있다.', 949);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1663, '② 결정서에는 행위자의 성명, 주민등록번호, 직업, 주거, 등록기준지 및 주문과 이유를 기재하여야 한다. 다만, 제1항제1호 및 제4호 결정의 결정서에는 행위자의 성명, 주민등록번호, 주거, 등록기준지(다만, 제4호에 한한다) 및 주문 외의 기재를 생략할 수 있다.', 949);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1664, '③ 피해자보호명령 및 임시보호명령의 결정서에는 제2항의 행위자에 관한 사항 외에 피해자의 성명, 주민등록번호 및 주거와 보조인의 성명 및 주소(보조인이 있는 경우만 해당한다)를 각각 기재하여야 한다. 다만, 피해자 및 보조인의 안전에 위협이 될 우려가 있는 경우에는 피해자 및 보조인의 주거 또는 주소의 기재를 생략할 수 있다.', 949);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1665, '① 보호처분 결정 및 피해자보호명령 결정은 심리기일에 결정서에 의하여 고지하여야 한다. 다만, 심리기일에 결정서를 미리 작성하기 어려운 사정이 있는 경우에는 결정을 고지한 후에 결정서를 작성할 수 있다.', 950);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1666, '② 제1항의 결정 외의 결정은 법 및 이 규칙에 특별히 정하지 아니한 경우에도 행위자에게 통지하여야 한다. 다만, 법 제27조제2항에 따른 결정은 그러하지 아니하다.', 950);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1667, '③ 제3조제1항 각 호의 결정(피해자보호명령 결정은 제외한다)은 법 및 이 규칙에 특별히 정하지 아니한 경우에도 피해자에게 통지하여야 한다.', 950);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1668, '④ 법 및 이 규칙에 따라 결정을 통지할 때에는 결정서 등본의 송달이나 그 밖에 적당하다고 인정하는 방식으로 할 수 있다.', 950);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1669, '⑤ 제4항의 송달에 관하여는 「민사소송법」중 송달에 관한 규정 및 「형사소송법」 제76조제2항부터 제5항까지의 규정을 준용한다.', 950);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1670, '① 법 제29조제1항제4호ㆍ제5호의 임시조치 결정을 하였을 때에는 수탁ㆍ유치기관의 장에게 그 결정을 통지하여야 한다.', 951);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1671, '② 법 제29조제1항제4호ㆍ제5호의 임시조치 결정에 따라 위탁ㆍ유치된 행위자에 관하여 이송ㆍ보호처분 결정을 하였을 때에는 해당 수탁ㆍ유치기관의 장에게 즉시 그 결정을 통지하여야 한다.', 951);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1672, '③ 법 제29조제1항제4호ㆍ제5호의 임시조치가 계속 중인 행위자 및 법 제40조제1항제4호부터 제8호까지의 보호처분이 계속 중인 행위자에 관하여 다음 각 호의 결정을 하였을 때에는 해당 수탁ㆍ유치기관 또는 보호관찰소의 장에게 즉시 그 결정을 통지하여야 한다.', 951);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1673, '① 임시조치 결정을 한 후에 다음 각 호의 결정을 하였을 때에는 그 임시조치의 집행을 담당한 경찰서의 장 또는 구치소의 장에게 그 결정을 통지하여야 한다.', 952);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1674, '② 보호처분 결정을 한 후에 다음 각 호의 결정을 하였을 때에는 그 보호처분의 집행을 담당한 경찰서의 장에게 그 결정을 통지하여야 한다.', 952);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1675, '③ 임시보호명령을 한 후에 다음 각 호의 결정을 하였을 때에는 그 임시보호명령의 집행을 담당한 경찰서의 장에게 그 결정을 통지하여야 한다.', 952);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1676, '④ 피해자보호명령을 한 후에 다음 각 호의 결정을 하였을 때에는 그 피해자보호명령의 집행을 담당한 경찰서의 장에게 그 결정을 통지하여야 한다.', 952);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1677, '① 법 제12조에 따라 송치 결정을 하였을 때에는 해당 사건을 기소한 검찰청의 검사에게 그 결정을 통지하여야 한다.', 953);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1678, '② 임시조치ㆍ이송ㆍ불처분ㆍ보호처분 결정과 보호처분의 변경ㆍ종료 결정을 검사에게 통지할 때에는 해당 사건을 송치한 검찰청의 검사에게 한다.', 953);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1679, '① 법원이 법 제27조제2항에 따라 사건을 검사에게 송치하는 결정을 하거나 법 제37조제2항제1호ㆍ제46조제1호에 따라 검사에게 송치할 경우에는 사건기록, 결정서 및 증거물을 피고사건의 관할법원에 대응하는 검찰청에 송부한다. 이 경우 법 제37조제2항제1호 및 제46조제1호에 따른 송치의 경우에는 각각 같은 조에 따른 결정이 확정된 때에 송부한다.', 954);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1680, '② 법 제29조제1항제5호의 임시조치에 따라 집행된 유치기간은 「형법」 제57조제1항의 판결선고전의 구금일수로 본다.', 954);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1681, '③ 법 제37조제2항제2호 및 제46조제2호에 따라 사건을 송치한 법원으로 이송하는 경우에는 사건기록, 결정서 및 증거물을 이송받는 법원에 직접 송부한다.', 954);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1682, '① 임시조치 및 보호처분, 임시보호명령 및 피해자보호명령은 결정을 한 때부터 집행한다. 다만, 법 제40조제1항제4호ㆍ제5호의 보호처분은 결정이 확정된 때부터 집행하고, 임시조치 및 보호처분, 피해자보호명령의 기간을 연장하는 결정은 원래의 임시조치 및 보호처분, 피해자보호명령에 계속하여 집행한다.', 955);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1683, '② 제1항에 따라 집행하는 경우 집행기간을 계산할 때 초일은 시간으로 계산하지 아니하고 1일로 산정한다.', 955);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1684, '③ 법 및 이 규칙에 따라 유치집행 또는 위탁집행이 되지 아니한 기간은 집행기간에 산입하지 아니한다.', 955);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1685, null, 956);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1686, '① 법 제8조에 따른 임시조치의 청구는 서면으로 한다. 이 경우 청구서에는 범죄사실의 요지 및 법 제29조제1항제1호, 제2호, 제3호 또는 제5호의 임시조치를 필요로 하는 사유를 기재하고 그 사유를 소명하여야 한다.', 957);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1687, '② 제1항의 청구를 받은 판사는 신속히 임시조치의 여부를 결정하여야 하고, 임시조치의 사유를 판단하기 위하여 필요하다고 인정하는 경우에는 행위자ㆍ피해자ㆍ가정구성원, 그 밖의 참고인을 소환하거나 동행영장을 발부하여 필요한 사항을 조사ㆍ심리할 수 있다.', 957);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1688, '③ 제1항의 청구를 받은 판사가 임시조치 결정 또는 임시조치청구를 기각하는 결정을 하였을 때에는 결정서 등본을 검사에게 송달하고, 검사 또는 사법경찰관은 그 등본을 수사기록에 편철하여야 한다.', 957);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1689, '④ 법원은 제1항의 청구에 따라 임시조치를 결정할 때에는 검사ㆍ행위자ㆍ피해자에게 그 결정을 통지하여야 한다. 행위자에게 법 제29조제1항제1호부터 제3호까지의 임시조치를 통지할 때에는 이를 이행하지 아니할 경우 법 제63조에 따른 처벌을 받을 수 있음을 경고하여야 한다.', 957);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1690, '⑤ 검사가 사건을 불기소하는 때에는 이미 행하여진 임시조치는 그 효력을 잃는다. 이 경우 검사는 그 취지를 행위자, 피해자, 임시조치의 집행을 담당한 경찰서의 장 또는 구치소의 장, 수탁ㆍ유치기관ㆍ상담수탁기관 등에 통지하여야 한다.', 957);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1691, '① 검사가 법원에 가정보호사건을 송치하는 경우에는 송치서에 범죄사실, 적용법조 및 구속여부를 명시하여야 한다. 이 경우 검사는 보호처분에 관한 의견을 기재할 수 있다.', 958);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1692, '② 법 제14조제2항에 따라 송치서에 첨부하여야 하는 참고자료는 수사기록과 증거물 전부를 말한다.', 958);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1693, '③ 공범이 있거나 법 제11조제2항 등의 사유로 송치서에 제2항의 참고자료를 첨부할 수 없는 경우에는 그 중 가정보호사건과 관련되는 부분의 등본을 첨부하여야 한다.', 958);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1694, '① 검사 또는 법원이 구금된 피고인을 가정보호사건으로 송치한 경우에 판사가 법 제29조제1항제1호부터 제3호까지의 임시조치를 결정하거나 임시조치를 할 필요가 없다고 인정한 때에는 행위자를 즉시 석방하여야 한다.', 959);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1695, '② 제1항의 경우 판사는 구속영장의 적당한 여백에 석방지휘 일시를 기재하고 서명날인 한 후 그 등본을 구금시설의 장에게 교부한다.', 959);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1696, null, 960);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1697, '① 법 제20조에 따른 가정보호사건조사관(이하 "조사관"이라 한다)은 행위자ㆍ피해자 및 가정구성원에게 출석을 요구하거나 방문하여 면접ㆍ관찰ㆍ심문 등을 할 수 있다. 이 경우 출석요구는 출석요구서의 송달이나 그 밖의 적당한 방법으로 할 수 있다.', 962);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1698, '② 조사관은 제1항에도 불구하고 질병이나 그 밖의 부득이한 사정으로 대면조사를 하기 어려운 경우, 영상 또는 전화 조사 등 적당한 방법으로 면접ㆍ심문 등을 할 수 있다.', 962);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1699, '③ 조사관은 다음 각 호의 사항이 필요하다고 인정할 때에는 판사에게 그 의견을 진술할 수 있다.', 962);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1700, '④ 조사는 다음 각 호의 사항에 관하여 한다.', 962);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1701, '① 행위자ㆍ피해자ㆍ가정구성원, 그 밖의 참고인의 소환은 소환장을 송달하는 것으로 한다.', 965);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1702, '② 제1항의 소환장에는 사건명, 행위자의 성명 및 소환되는 사람의 성명, 가정보호사건에 관하여 소환된다는 뜻, 출석할 일시와 장소, 행위자가 정당한 이유 없이 소환에 응하지 아니할 때에는 동행영장을 발부할 수 있다는 뜻을 기재하고 판사가 기명날인하여야 한다.', 965);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1703, '③ 출석요구서 및 소환장의 송달에 관하여는 「민사소송법」 중 송달에 관한 규정(같은 법 제187조 및 제194조부터 제196조까지의 규정은 제외한다) 및 「형사소송법」 제76조제2항부터 제5항까지의 규정을 준용한다.', 965);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1704, '① 법 제29조제1항제4호ㆍ제5호의 임시조치에 따라 수탁ㆍ유치기관에 수용 중인 행위자가 이 규칙 제16조제1항에 따른 출석요구 또는 법 제24조제1항에 따른 소환을 받은 경우 그 수탁ㆍ유치기관의 장은 소속 직원으로 하여금 행위자를 호송하고 당일의 조사ㆍ심리가 종료될 때까지 법원청사 내에서 행위자를 감호하게 하여야 한다.', 966);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1705, '② 행위자가 의료기관이나 그 밖의 요양소에 위탁된 경우 법원은 그 수탁기관의 소재지를 관할하는 경찰관서에 제1항의 조치를 요청할 수 있다.', 966);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1706, '① 동행영장은 판사의 지휘에 따라 집행한다.', 968);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1707, '② 제1항의 집행지휘는 동행영장을 법 제27조제1항에서 정한 집행담당자에게 교부하는 것으로 한다.', 968);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1708, '① 동행영장을 집행할 때에는 행위자에게 동행영장을 제시하고 신속히 법원에 인치하여야 한다.', 969);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1709, '② 제1항에도 불구하고 동행영장을 소지하지 않은 경우로서 긴급한 집행이 필요한 경우에는 행위자에게 행위의 개요 및 동행영장 발부 사실을 고지하고 집행할 수 있다. 이 경우 집행이 완료된 후 신속히 동행영장을 제시하여야 한다.', 969);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1710, '③ 동행영장을 집행하였을 때에는 집행일시와 장소 및 법원에 인치한 일시를, 집행할 수 없었을 때에는 그 사유를 각각 동행영장에 기재하고 기명날인하여 법원에 제출하여야 한다.', 969);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1711, '① 동행영장의 집행에 따라 법원에 인치된 행위자를 법원 외의 장소에 수용할 필요가 있는 경우 판사는 동행영장의 집행담당자에게 동행영장에 기재된 수용할 장소에 행위자를 수용할 것을 지휘할 수 있다. 이 경우 수용된 행위자의 소환에 관하여는 제20조제1항을 준용한다.', 970);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1712, '② 판사가 법 제29조제1항제1호부터 제3호까지의 임시조치를 결정하거나 임시조치를 할 필요가 없다고 인정한 때에는 행위자를 즉시 석방하여야 한다.', 970);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1713, '① 행위자가 보조인을 선임하려는 경우에는 보조인과 연명날인한 서면을 제출하여야 한다. 이 경우 변호사가 아닌 사람을 보조인으로 선임하려는 경우에는 위 서면에 행위자와 보조인과의 관계를 기재하고 그 관계를 소명하는 서면을 첨부하여야 한다.', 971);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1714, '② 판사는 언제든지 법 제28조제2항 단서의 허가를 취소할 수 있다.', 971);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1715, '③ 보조인의 선임은 심급마다 하여야 한다.', 971);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1716, '④ 「형사소송법」 중 변호인의 권리ㆍ의무에 관한 규정은 가정보호사건의 성질에 위반되지 아니하는 범위에서 보조인에게도 준용한다.', 971);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1717, '① 행위자의 정신질환ㆍ약물남용 등으로 인하여 의학적인 치료와 요양이 시급히 필요하거나 전문가의 진단소견 또는 의견조회를 위하여 필요하다고 인정하여 법 제29조제1항제4호의 임시조치를 할 때에는 행위자를 수탁기관에 수용할 수 있다.', 974);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1718, '② 제1항의 임시조치를 할 때에는 사전에 그 수탁기관의 장에게 도주방지 등 행위자를 감호하는 데 필요한 사항을 고지하고 동의를 받아야 한다.', 974);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1719, '③ 수탁기관의 장은 수용 중인 행위자가 도주하는 등 행위자의 신상에 변동을 초래할 만한 사유가 발생하였을 때에는 지체 없이 그 사실을 법원에 보고하여야 한다.', 974);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1720, '① 법원장ㆍ지원장은 매년 12월 말까지 법 제29조제1항제4호 및 제6호의 임시조치 집행을 위한 수탁기관을 지정하여야 한다.', 975);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1721, '② 제1항에 따라 수탁기관으로 지정할 시설은 행위자에 대한 상담, 치료와 환경의 조정 및 성행의 교정을 하기에 적당한 곳이어야 하며, 해당 시설을 수탁기관으로 지정하려면 미리 그 시설의 운영자와 협의하여야 한다.', 975);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1722, '③ 법원장ㆍ지원장은 언제든지 조사관이나 법원서기관ㆍ법원사무관ㆍ법원주사ㆍ법원주사보(이하 "법원사무관등"이라 한다)로 하여금 제1항에 따라 지정된 수탁기관이 행위자를 보호하기에 충분한 시설을 가지고 있는지 여부와 그 운영실태를 조사ㆍ보고하도록 하고, 행위자 보호에 부적당하다고 인정되는 경우에는 그 지정을 취소할 수 있다.', 975);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1723, '① 판사는 필요한 경우에 수탁기관의 장으로 하여금 위탁에 드는 비용의 예상액과 그 산출근거를 기재한 예상비용산정서를 제출하게 할 수 있다.', 976);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1724, '② 판사는 수탁기관의 장이 제출한 예상비용산정서, 행위자의 경제적 능력 등을 종합하여 위탁비용의 예납액을 산출하고, 그 금액을 행위자 또는 그 법정대리인에게 서면으로 통지하여야 한다.', 976);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1725, '③ 판사는 행위자가 위탁에 드는 비용을 부담할 경제적 능력이 없다고 인정할 때에는 그 비용의 전부 또는 일부를 국가가 부담하기로 결정하고 위탁을 할 수 있다. 다만, 「국민건강보험법」,「의료급여법」이나 그 밖의 다른 법령의 적용을 받아 정신질환자 또는 그 보호의무자가 부담하지 아니하는 비용은 제외한다.', 976);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1726, '① 수탁기관의 장은 위탁종료 시 법원에 구체적인 산출근거를 상세히 기재한 비용산정서 및 청구서를 제출하여야 한다.', 977);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1727, '② 판사는 수탁기관의 장이 제출한 비용산정서와 그 밖의 구체적 사정을 고려하여 위탁비용을 결정한다.', 977);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1728, '③ 판사가 위탁비용을 지급하게 할 경우에는 비용청구서의 적당한 여백에 결정된 비용을 기재하고 날인하여 사건담임자에게 교부한다.', 977);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1729, '④ 제3항에 따라 판사로부터 비용청구서를 교부받은 사건담임자는 그 청구서를 즉시 회계관계공무원에게 보내는 방식으로 지급의뢰를 하여야 한다.', 977);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1730, '⑤ 제4항에 따라 비용청구서를 받은 회계관계공무원은 특별한 사정이 없으면 30일 이내에 위탁비용을 입금한다.', 977);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1731, '⑥ 회계관계공무원은 제5항의 기간에 위탁비용을 입금하지 못한 경우에는 사건번호, 수탁기관의 명칭, 위탁종료일 및 지급의뢰일, 미지급한 위탁비용의 금액, 입금 지연사유를 법원행정처장에게 보고하여야 한다.', 977);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1732, '① 법 제29조제9항에 따른 임시조치의 집행지휘는 결정서 등본을 그 집행담당자에게 교부하는 것으로 한다.', 978);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1733, '② 판사는 조사관으로 하여금 법 제29조제1항 각 호의 임시조치에 관한 집행상황을 보고하게 할 수 있다.', 978);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1734, '③ 법 제29조제1항제5호의 임시조치 결정은 결정한 때부터 3개월이 경과하면 집행에 착수하지 못한다.', 978);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1735, '④ 유치시설의 장은 행위자를 유치한 때와 그 집행을 종료한 때에는 지체 없이 수용통보서 또는 석방통보서를 법원에 보내 그 사실을 알려야 한다.', 978);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1736, '⑤ 법 제29조제1항제5호에 따라 행위자를 유치시설에 유치할 때에는 「형의 집행 및 수용자의 처우에 관한 법률」 중 미결수용자에 대한 수용절차에 따른다.', 978);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1737, '① 법 제29조제10항에 따른 임시조치의 취소ㆍ변경 신청과 법 제29조의2제2항에 따른 임시조치의 변경 신청은 서면으로 한다. 이 경우 신청서에는 임시조치의 취소ㆍ변경이 필요한 이유를 기재하고 그 이유를 소명하여야 한다.', 979);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1738, '② 판사는 임시조치를 취소ㆍ변경할 때 필요하다고 인정하는 경우에는 행위자ㆍ피해자ㆍ가정구성원, 그 밖의 참고인을 소환하여 필요한 사항을 조사ㆍ심리할 수 있다.', 979);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1739, '③ 임시조치의 취소ㆍ변경은 임시조치 결정이 통지된 때부터 할 수 있다.', 979);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1740, '④ 제1항의 신청에 대해서는 결정을 하고 신청인에게 그 결정을 통지하여야 한다.', 979);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1741, '⑤ 법 제29조제1항제4호 및 제6호의 임시조치 결정이 있은 다음 행위자의 거주지 또는 현재지가 임시조치 결정을 한 법원ㆍ지원의 관할구역 밖으로 변경되었을 경우, 판사는 직권으로 또는 행위자나 수탁기관의 신청에 따라 그 임시조치 결정의 수탁기관을 관할구역 외 법원ㆍ지원의 수탁기관으로 변경할 수 있다.', 979);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1742, '① 법 제15조에 따라 가정보호사건을 이송하는 경우에 이미 행하여진 임시조치는 그 효력을 잃지 않는다.', 980);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1743, '② 법 제15조에 따른 이송 결정 시 판사는 법 제29조제1항제4호부터 제6호까지의 위탁ㆍ유치ㆍ상담위탁장소를 변경할 수 있다. 이 경우 제32조제1항을 준용한다.', 980);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1744, '① 피해자ㆍ보조인ㆍ가정구성원, 그 밖의 참고인 등에 대한 심리기일의 통지는 기일통지서 또는 출석요구서를 송달하는 방법으로 한다.', 981);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1745, '② 제1항에도 불구하고 긴급한 필요가 있는 경우에는 전화ㆍ팩스ㆍ보통우편 또는 전자우편이나 그 밖의 적당한 방법으로 통지할 수 있다.', 981);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1746, '③ 제2항의 방법으로 심리기일을 통지한 경우 법원사무관등은 그 방법과 날짜를 소송기록에 표시하여야 한다.', 981);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1747, '① 법 제31조에 따른 심리기일 변경 청구에는 심리기일의 변경을 필요로 하는 사유와 그 사유가 계속되리라고 예상되는 기간을 명시하여야 하며, 진단서나 그 밖의 자료로 그 사유와 기간에 대해 소명하여야 한다.', 982);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1748, '② 제1항의 청구를 기각한 명령은 송달하지 아니한다.', 982);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1749, '① 법정에서의 좌석의 위치에 관하여는 「법정 좌석에 관한 규칙」을 준용하며, 행위자는 피고인 또는 원ㆍ피고석에, 보조인은 변호인석 또는 행위자 옆에, 조사관은 검사 또는 법원사무관등석에 각각 배치한다.', 983);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1750, '② 판사는 심리기일에 의견진술을 필요로 하는 조사관에게 심리기일에 출석할 것을 명할 수 있다.', 983);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1751, '③ 행위자가 심리기일에 출석하지 아니하였을 때에는 심리를 할 수 없다. 다만, 법 제37조제1항에 따라 불처분 결정으로 종결할 사건의 경우에는 그러하지 아니하다.', 983);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1752, '① 법 제32조제1항에 따른 심리의 비공개 결정은 이유를 밝혀 고지한다.', 984);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1753, '② 판사는 제1항의 결정을 한 경우에도 적당하다고 인정되는 사람의 방청을 허가할 수 있다.', 984);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1754, '① 판사가 심리를 할 때에는 행위자에게 범죄사실의 내용 및 불리한 진술을 거부할 수 있고 이익이 되는 사실을 진술할 수 있음을 고지하여야 한다.', 985);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1755, '② 동일 행위자에 대한 2개 이상의 가정보호사건 및 관련 보호사건은 될 수 있으면 병합하여 심리하여야 한다.', 985);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1756, '① 법 제32조제2항ㆍ제33조제1항에 따른 신청에 대해서는 결정을 하고, 신청인에게 그 결정을 통지하여야 한다.', 986);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1757, '② 행위자가 범죄사실을 부인하고 타인의 진술조서의 내용을 다투는 경우 법원은 원진술자를 증인으로 신문하여야 한다. 다만, 다른 증거에 비추어 원진술자의 진술이 신빙할 수 있는 상태에서 행하여진 경우에는 그러하지 아니하다.', 986);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1758, '① 심리에 참여한 법원사무관등은 심리기일의 절차에 관하여 심리조서를 작성하여야 한다.', 988);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1759, '② 심리조서에는 다음 각 호의 사항을 기재하여야 한다.', 988);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1760, '③ 법원사무관등은 판사의 허가가 있을 때에는 제2항의 기재사항 중 일부를 생략할 수 있다.', 988);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1761, '④ 심리조서에 관하여 이 규칙에서 규정하지 아니한 사항은 가정보호사건의 성질에 반하지 아니하는 범위에서 「형사소송법」 제48조부터 제59조까지 및 「형사소송규칙」 제29조부터 제41조까지의 규정을 준용한다.', 988);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1762, '① 행위자 및 보조인은 심리가 계속 중인 사건의 관계 서류 또는 증거물을 열람 또는 등사할 수 있다.', 989);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1763, '② 행위자 및 보조인의 열람 또는 등사에 관하여는 「재판기록 열람ㆍ복사 규칙」 제7조를 준용한다.', 989);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1764, '① 행위자ㆍ보조인 및 피해자는 결정서 또는 결정을 기재한 조서의 등본ㆍ초본이나 심판에 관한 사항의 증명서를 교부하여 줄 것을 법원사무관등에게 청구할 수 있다. 다만, 피해자는 그 청구하는 사유를 소명하여야 한다.', 990);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1765, '② 법원사무관등은 제1항의 등본ㆍ초본 또는 증명서를 작성할 때에는 등본ㆍ초본 또는 심판에 관한 사항의 증명서라는 취지를 기재한 후 기명날인하여야 한다.', 990);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1766, '① 판사가 법 제37조제1항제1호의 사유로 불처분 결정을 한 경우에는 이미 행하여진 임시조치를 취소하여야 한다.', 991);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1767, '② 판사가 법 제37조제1항제2호의 사유로 불처분 결정을 한 경우에는 그 결정이 확정된 때에 이미 행하여진 임시조치를 취소할 수 있다. 이 경우 행위자가 수탁ㆍ유치기관에 수용 중이면 수탁ㆍ유치기관의 장에게 그 결정을 통지하기 전에 사건을 송치받을 검찰청에 미리 서면, 전화, 팩스, 그 밖의 신속한 방법으로 통지하여야 한다.', 991);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1768, '① 판사가 법 제40조제1항에 따라 보호처분을 한 때에는 이미 행하여진 임시조치는 그 효력을 잃는다.', 992);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1769, '② 보호처분을 고지할 때에는 항고기간, 항고장 제출법원 및 항고법원을 알려주어야 한다.', 992);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1770, '③ 법 제40조제1항제1호부터 제3호까지의 보호처분을 고지할 때에는 이를 이행하지 아니할 경우 법 제63조에 따른 처벌을 받을 수 있음을, 법 제40조제1항제4호부터 제8호까지의 보호처분을 고지할 때에는 이를 이행하지 아니하거나 집행에 응하지 아니할 경우 보호처분이 취소되고 검사에게 송치되거나 법원에 이송될 수 있음을 각각 경고하여야 한다.', 992);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1771, '① 친권 행사의 제한 결정을 할 때에는 친권, 법률행위대리권 또는 재산관리권의 전부 또는 일부의 행사를 정지할 수 있다.', 993);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1772, '② 제1항의 결정을 한 경우 판사는 지체 없이 가족관계등록사무를 관장하는 자에게 가족관계등록부에 기록할 것을 촉탁하여야 한다.', 993);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1773, '③ 제2항에 따른 가족관계등록부 기록의 촉탁에 관하여는 「가사소송규칙」 제5조제2항, 제6조를 준용한다.', 993);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1774, '① 사회봉사명령과 수강명령은 병과할 수 있다.', 994);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1775, '② 사회봉사명령 또는 수강명령이 보호관찰에 병과하여 부과된 경우에는 보호관찰기간에 그 명령을 집행하여야 한다.', 994);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1776, '③ 사회봉사ㆍ수강 명령 및 보호관찰에 관하여는 가정보호사건의 성질에 반하지 아니하는 범위에서 「보호관찰 등에 관한 법률」을 준용한다.', 994);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1777, '① 법원장ㆍ지원장은 매년 12월 말까지 법 제40조제1항제6호부터 제8호까지의 보호처분 집행을 위한 수탁기관을 지정하여야 한다.', 995);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1778, '② 제1항에 따른 수탁기관의 지정 및 그 취소에 관하여는 제29조제2항 및 제3항을 준용한다.', 995);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1779, '③ 행위자의 정신질환ㆍ약물남용 등으로 인하여 치료와 요양이 필요하다고 인정하여 법 제40조제1항제7호의 보호처분을 할 때에는 행위자를 수탁기관에 수용할 수 있다. 이 경우 수탁기관의 동의 및 보고 등에 관하여는 제28조제2항 및 제3항을 준용한다.', 995);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1780, '① 법 제40조제5항에 따라 행위자의 교정에 필요한 참고자료를 수탁기관의 장 등에게 송부할 때에는 그 등본으로 할 수 있다.', 997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1781, '② 제1항에 따른 참고자료를 원본으로 송부받은 수탁기관의 장 등은 보호처분이 종료 또는 취소된 때에는 즉시 그 원본을 송부한 법원에 반환하여야 한다.', 997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1782, '① 판사는 조사관으로 하여금 법 제40조제1항 각 호의 보호처분에 관한 집행상황을 보고하게 할 수 있다.', 1000);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1783, '② 제1항의 명을 받은 조사관은 법 제44조에 따른 지시사항의 이행 여부, 수탁기관의 감호 상황 또는 판사가 특히 필요하다고 인정하는 사항을 조사하여 의견을 붙인 서면으로 보고하여야 한다.', 1000);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1784, '① 법 제45조제1항ㆍ제46조ㆍ제47조에 따른 보호처분의 변경ㆍ취소ㆍ종료의 청구는 그 보호처분을 결정한 법원에 서면으로 하여야 한다.', 1001);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1785, '② 제1항에 따른 청구서에는 보호처분의 변경ㆍ취소ㆍ종료가 필요한 이유를 기재하고 그 이유를 소명하여야 한다.', 1001);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1786, '③ 판사는 보호처분을 변경ㆍ취소ㆍ종료할 때 필요하다고 인정하는 경우에는 행위자ㆍ피해자ㆍ가정구성원, 그 밖의 참고인을 소환하여 필요한 사항을 조사ㆍ심리할 수 있고, 보호처분의 종류를 변경할 때 필요하다고 인정하는 경우에는 법 제29조제1항 각 호의 임시조치를 할 수 있다.', 1001);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1787, '④ 보호처분의 변경ㆍ취소는 보호처분 결정이 고지된 때부터 할 수 있다.', 1001);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1788, '⑤ 제1항의 청구에 대해서는 결정을 하고 청구인에게 그 결정을 통지하여야 한다.', 1001);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1789, '⑥ 법 제40조제1항제7호 및 제8호의 보호처분 결정이 있은 다음 행위자의 거주지 또는 현재지가 보호처분 결정을 한 법원ㆍ지원의 관할구역 밖으로 변경되었을 경우, 판사는 직권으로 또는 행위자나 수탁기관의 신청에 따라 그 보호처분 결정의 수탁기관을 관할구역 외 법원ㆍ지원의 수탁기관으로 변경할 수 있다.', 1001);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1790, '① 법정대리인이 있는 행위자 또는 피해자가 항고를 취하할 때에는 각각 그 법정대리인의 동의를 얻어야 한다. 다만, 법정대리인의 사망, 그 밖의 사유로 동의를 얻을 수 없을 때에는 예외로 한다.', 1005);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1791, '② 행위자의 법정대리인 또는 보조인은 행위자의 동의를 얻어, 피해자의 법정대리인은 피해자의 동의를 얻어 각각 항고를 취하할 수 있다.', 1005);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1792, '① 법 제29조제1항제4호ㆍ제5호 또는 제40조제1항제6호ㆍ제7호에 따라 수탁ㆍ유치기관에 수용 중인 행위자가 항고 제기 기간에 항고장을 그 기관의 장 또는 그 직무를 대리하는 사람에게 제출한 때에는 항고 제기 기간에 항고한 것으로 본다.', 1006);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1793, '② 제1항에 따라 항고장을 제출받은 기관의 장 또는 그 대리자는 항고장에 접수 연월일을 기재하여 즉시 임시조치 또는 보호처분 결정을 한 법원에 송부하여야 한다.', 1006);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1794, '① 항고법원은 항고이유에 기재된 사항에 관하여 조사하여야 한다.', 1007);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1795, '② 항고법원은 법 제49조제1항에 규정된 사유에 관하여는 직권으로 조사할 수 있다.', 1007);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1796, '① 항고법원은 필요한 경우에 사실조사를 할 수 있다.', 1008);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1797, '② 제1항의 조사는 합의부원에게 명하거나 가정법원 또는 지방법원과 그 지원의 판사에게 촉탁하여 할 수 있다.', 1008);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1798, '① 수탁ㆍ유치기관에 수용 중인 행위자에 대하여 항고법원이 원결정을 취소하고 사건을 원심법원에 환송하거나 다른 관할법원에 이송하는 경우에는 그 결정을 수탁ㆍ유치기관의 장에게 통지하기 전에 미리 환송 또는 이송받을 법원에 통지하여야 한다.', 1009);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1799, '② 수탁ㆍ유치기관의 장이 제1항의 취소환송ㆍ이송 결정 통지를 받은 때에는 즉시 행위자를 환송 또는 이송받을 법원으로 인도하여야 한다.', 1009);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1800, '③ 항고법원으로부터 사건을 환송 또는 이송받은 법원의 판사는 법 제29조제1항 각 호의 임시조치를 할 수 있다.', 1009);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1801, '① 항고법원이 원결정을 파기하고 스스로 임시조치, 불처분 또는 보호처분의 결정을 하는 경우에는 각각 그 결정에 관한 법 및 이 규칙의 규정을 준용한다.', 1010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1802, '② 항고법원이 원심법원의 임시조치 및 그 연장ㆍ변경 결정을 파기하고 자판하는 경우에는 임시조치를 하지 않는다는 뜻의 결정을 할 수 있다.', 1010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1803, '③ 검사의 청구에 의한 임시조치에 대하여 제기된 항고가 이유 있다고 인정할 때에는 원심법원의 임시조치 결정을 파기하고 검사의 청구를 기각한다는 뜻의 결정을 할 수 있다.', 1010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1804, '① 항고법원이 원심의 보호처분 결정을 취소하고 스스로 불처분 결정을 하는 때에는 원심의 몰수 결정 또는 배상명령을 취소하여야 한다. 이 경우 항고법원이 원심의 몰수 결정 또는 배상명령을 취소하지 아니한 때에는 그 결정 또는 명령을 취소한 것으로 본다.', 1011);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1805, '② 원심에서 법 제57조제2항에 따라 배상명령을 한 때에는 제1항을 적용하지 아니한다.', 1011);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1806, '① 항고법원으로부터 사건을 환송 또는 이송받은 법원의 판사는 환송 또는 이송받은 사건에 관하여 다시 심리하여야 한다.', 1012);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1807, '② 제1항의 경우에 원결정을 한 판사는 심리에 관여할 수 없다.', 1012);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1808, '① 대법원은 법 제52조에 따른 재항고의 절차가 법 및 이 규칙의 규정에 위반되거나 재항고가 이유 없다고 인정될 때에는 결정으로 재항고를 기각하여야 한다.', 1013);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1809, '② 재항고가 이유 있다고 인정할 때에는 원결정을 취소하고 사건을 항고법원에 환송하거나 동등한 다른 법원에 이송하여야 한다. 다만, 대법원이 원결정을 파기한 경우에 그 기록 및 항고법원과 제1심법원이 조사한 증거에 의하여 결정하기 충분하다고 인정할 때에는 사건에 대하여 직접 결정을 할 수 있다.', 1013);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1810, '① 피해자보호명령의 청구는 서면 또는 말로 할 수 있다.', 1015);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1811, '② 서면으로 청구하는 경우에는 청구서에 다음 각 호의 사항을 적고 청구인, 법정대리인이나 보조인이 기명날인 또는 서명하여야 한다.', 1015);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1812, '③ 말로 청구하는 경우에는 법원사무관등의 앞에서 하여야 한다.', 1015);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1813, '④ 제3항의 경우에 법원사무관등은 제2항 각 호의 사항을 적은 조서를 작성하고 기명날인하여야 한다.', 1015);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1814, '① 피해자 및 행위자는 피해자보호명령사건에 대하여 각자 보조인을 선임할 수 있다.', 1016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1815, '② 피해자 및 행위자의 법정대리인ㆍ배우자ㆍ직계친족ㆍ형제자매, 법 제4조제3항에서 정한 상담소등(이하 "상담소등"이라 한다)의 상담원과 그 기관장은 보조인이 될 수 있다.', 1016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1816, '③ 제1항에 따라 변호사가 아닌 사람을 보조인으로 선임하거나, 제2항에 따라 보조인이 되려면 법원의 허가를 받아야 한다.', 1016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1817, '④ 판사는 언제든지 제3항의 허가를 취소할 수 있다.', 1016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1818, '⑤ 제1항에 따라 보조인을 선임하려는 경우에는 심급마다 보조인과 연명날인한 서면을 제출하여야 한다.', 1016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1819, '⑥ 제2항에 따라 보조인이 되려는 사람은 심급별로 그 취지를 적은 서면을 제출하여야 한다. 이 경우 보조인이 되려는 사람과 피해자ㆍ행위자 사이의 신분관계 또는 보조인이 되려는 사람의 직위를 소명하는 서면을 첨부하여야 한다.', 1016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1820, '⑦ 제1항에 따른 보조인은 독립하여 절차행위를 할 수 있고, 제2항에 따른 보조인은 독립하여 피해자 또는 행위자의 명시한 의사에 반하지 아니하는 절차행위를 할 수 있다. 다만, 법률에 다른 규정이 있는 경우에는 예외로 한다.', 1016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1821, '① 법원은 피해자가 다음 각 호의 어느 하나에 해당하는 경우에는 직권으로 또는 피해자나 그 법정대리인ㆍ직계친족ㆍ형제자매의 신청에 따라 변호사를 피해자의 보조인으로 선정할 수 있다.', 1017);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1822, '② 법원은 행위자가 「형사소송법」 제33조제1항 각 호의 어느 하나에 해당하는 경우에는 직권으로 변호사를 행위자의 보조인으로 선정할 수 있다.', 1017);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1823, '③ 제1항 또는 제2항에 따라 선정된 보조인에게 지급하는 비용에 관하여는 「형사소송비용 등에 관한 법률」을 준용하고, 그 밖에 이 규칙에서 따로 정하지 아니한 사항에 관하여는 피해자보호명령의 성질에 위반되지 아니하는 범위에서 「형사소송규칙」, 「형사소송비용 등에 관한 규칙」 중 국선변호인에 관한 규정을 준용한다.', 1017);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1824, '① 법원은 피해자보호명령사건이 그 관할에 속하지 아니하거나 적정한 조사ㆍ심리를 위하여 필요하다고 인정하는 경우에는 결정으로 그 사건을 즉시 다른 관할법원에 이송하여야 한다.', 1018);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1825, '② 법원은 제1항에 따른 이송 결정을 한 경우에는 지체 없이 그 사유를 첨부하여 피해자, 청구인 및 행위자에게 통지하여야 한다.', 1018);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1826, '① 피해자는 제1심의 피해자보호명령의 결정이 있을 때까지 행위자의 동의 없이 청구를 취하할 수 있다.', 1019);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1827, '② 검사는 피해자의 동의를 얻어 제1심의 피해자보호명령의 결정이 있을 때까지 행위자의 동의 없이 청구를 취하할 수 있다.', 1019);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1828, '③ 청구의 취하는 서면으로 하여야 한다. 다만, 심리기일에는 말로 할 수 있다.', 1019);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1829, '④ 청구서를 행위자에게 송달한 뒤에는 취하의 서면도 송달하여야 한다.', 1019);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1830, '⑤ 제3항 단서의 경우 행위자가 심리기일에 출석하지 아니한 때에는 그 기일의 조서 등본을 송달하여야 한다.', 1019);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1831, '⑥ 법 제55조의4제1항에 따른 임시보호명령이 행하여진 이후에 피해자보호명령 청구가 취하된 경우 법원은 임시보호명령을 취소하여야 한다.', 1019);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1832, '① 법 제55조의4에 따른 임시보호명령의 결정을 한 때에는 피해자, 청구인 및 행위자에게 그 결정을 통지하여야 한다.', 1020);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1833, '② 제1항에 따라 결정을 통지할 때에는 항고기간과 항고장 제출법원 및 항고법원을 알려주어야 하고, 행위자에게는 임시보호명령을 이행하지 아니할 경우 법 제63조에 따른 처벌을 받을 수 있음을 경고하여야 한다.', 1020);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1834, '① 판사는 임시보호명령을 한 경우에는 조사관, 법원사무관등, 사법경찰관리로 하여금 임시보호명령을 집행하게 할 수 있다.', 1023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1835, '② 제1항의 집행지휘는 결정서 등본을 제1항에서 정한 집행담당자에게 교부하는 것으로 한다.', 1023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1836, '③ 판사는 조사관으로 하여금 임시보호명령에 관한 집행상황을 보고하게 할 수 있다.', 1023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1837, '① 법 제55조의4제3항에 따른 임시보호명령의 취소ㆍ변경 신청은 서면으로 한다. 이 경우 신청서에는 임시보호명령의 취소ㆍ변경이 필요한 이유를 기재하고 그 이유를 소명하여야 한다.', 1024);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1838, '② 판사는 임시보호명령을 취소ㆍ변경할 때 필요하다고 인정하는 경우에는 청구인ㆍ행위자ㆍ피해자ㆍ가정구성원, 그 밖의 참고인을 소환하여 필요한 사항을 조사ㆍ심리할 수 있다.', 1024);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1839, '③ 임시보호명령의 취소ㆍ변경은 임시보호명령이 통지된 때부터 할 수 있다.', 1024);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1840, '④ 제1항의 신청에 대한 결정은 피해자, 신청인 및 행위자에게 통지하여야 한다.', 1024);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1841, '⑤ 임시보호명령 변경 결정의 집행에 관하여는 제77조를 준용한다.', 1024);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1842, '① 법원이 피해자보호명령사건을 심리할 때에는 직권으로 사실조사 및 필요한 증거조사를 하여야 하며, 언제든지 피해자 및 행위자, 법정대리인, 보조인, 가정구성원 또는 상담소등의 장 등 그 밖의 참고인을 심문할 수 있다.', 1025);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1843, '② 조사관은 피해자ㆍ행위자, 가정구성원 및 상담소등의 장 등 그 밖의 참고인에게 출석을 요구하거나 방문하여 면접ㆍ관찰ㆍ심문 등을 할 수 있다. 이 경우 출석요구는 출석요구서의 송달이나 그 밖의 적당한 방법으로 할 수 있다.', 1025);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1844, '③ 조사관은 제2항에도 불구하고 질병이나 그 밖의 부득이한 사정으로 대면조사를 하기 어려운 경우, 영상 또는 전화 조사 등 적당한 방법으로 면접ㆍ심문 등을 할 수 있다.', 1025);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1845, '④ 조사관은 다음 각 호의 사항이 필요하다고 인정할 때에는 판사에게 그 의견을 진술할 수 있다.', 1025);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1846, '⑤ 조사는 다음 각 호의 사항에 관하여 한다.', 1025);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1847, '① 판사는 가능한 신속하게 심리기일을 지정하고, 피해자ㆍ청구인 및 행위자를 소환하여야 한다.', 1026);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1848, '② 제1항의 심리기일은 보조인에게 통지하여야 한다.', 1026);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1849, '① 피해자ㆍ행위자ㆍ가정구성원, 그 밖의 참고인의 소환은 소환장을 송달하는 것으로 한다.', 1027);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1850, '② 제1항의 소환장에는 사건명, 피해자와 행위자의 성명 및 소환되는 사람의 성명, 피해자보호명령사건에 관하여 소환된다는 뜻, 출석할 일시와 장소 등을 기재하고 판사가 기명날인하여야 한다.', 1027);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1851, '③ 행위자에게 제1회 심리기일 소환장을 송달할 때에는 피해자보호명령 청구서 부본을 함께 송달한다. 이 경우 피해자 및 보조인의 안전에 위협이 될 우려가 있으면 피해자보호명령 청구서 부본 상의 피해자 및 보조인의 주거, 주소, 연락처 등 개인정보의 전부 또는 일부를 가리고 송달할 수 있다.', 1027);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1852, '④ 소환장의 송달에 관하여는 「민사소송법」 중 송달에 관한 규정 및 「형사소송법」 제76조제2항부터 제5항까지의 규정을 준용한다.', 1027);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1853, '① 법정에서의 좌석의 위치에 관하여는 피해자보호명령사건의 성질에 반하지 아니하는 범위에서 「법정 좌석에 관한 규칙」을 준용한다. 다만, 법원청사의 사정상 필요한 경우에는 피해자보호명령사건의 성질에 반하지 아니하는 범위에서 달리 정할 수 있다.', 1028);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1854, '② 판사는 심리기일에 의견진술을 필요로 하는 조사관에게 심리기일에 출석할 것을 명할 수 있다.', 1028);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1855, '③ 피해자보호명령의 심리는 피해자, 청구인 또는 행위자가 심리기일에 출석하지 아니한 때에도 할 수 있다. 다만, 피해자, 청구인이 제81조에 따라 소환되었음에도 2회에 걸쳐 모두 출석하지 아니한 때에는 피해자보호명령 청구를 취하한 것으로 본다.', 1028);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1856, '① 법 제55조의6에 따라 피해자보호명령사건과 가정보호사건을 병합하여 심리한 경우에는 주문에 피해자보호명령에 따른 결정과 보호처분에 따른 결정이 구분될 수 있도록 표기하여야 한다.', 1029);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1857, '② 피해자보호명령과 보호처분은 각 효력에 영향을 미치지 아니한다.', 1029);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1858, '① 심리에 참여한 법원사무관등은 심리기일의 절차에 관하여 심리조서를 작성하여야 한다.', 1032);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1859, '② 심리조서에는 다음 각 호의 사항을 기재하여야 한다.', 1032);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1860, '③ 법원사무관등은 판사의 허가가 있을 때에는 제2항의 기재사항 중 일부를 생략할 수 있다.', 1032);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1861, '④ 심리조서에 관하여 이 규칙에서 규정하지 아니한 사항은 피해자보호명령사건의 성질에 반하지 아니하는 범위에서 「형사소송법」 제48조부터 제59조까지 및 「형사소송규칙」 제29조부터 제41조까지의 규정을 준용한다.', 1032);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1862, '① 피해자, 행위자 및 보조인은 판사의 허가를 받은 경우에만 심리가 계속 중인 사건의 관계 서류 또는 증거물을 열람 또는 등사할 수 있다.', 1033);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1863, '② 피해자보호명령사건이 가정보호사건과 병합되어 심리되는 경우 병합 이후 편철된 기록에 대한 열람ㆍ등사는 제43조를 준용한다.', 1033);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1864, '① 피해자, 행위자 및 보조인은 결정서 또는 결정을 기재한 조서의 등본ㆍ초본이나 심판에 관한 사항의 증명서를 교부하여 줄 것을 법원사무관등에게 청구할 수 있다.', 1034);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1865, '② 법원사무관등은 제1항의 등본ㆍ초본 또는 증명서를 작성할 때에는 등본ㆍ초본 또는 심판에 관한 사항의 증명서라는 취지를 기재한 후 기명날인하여야 한다.', 1034);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1866, '① 판사는 피해자보호명령사건을 심리한 결과 피해자보호명령을 할 수 없거나 할 필요가 없다고 인정하는 경우에는 기각 결정을 하여야 한다.', 1035);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1867, '② 제1항에 따른 결정을 한 경우에는 피해자, 청구인 및 행위자에게 그 결정을 통지하여야 한다.', 1035);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1868, '① 피해자보호명령을 고지할 때에는 항고기간, 항고장 제출법원 및 항고법원을 알려주어야 한다.', 1037);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1869, '② 행위자에게 피해자보호명령을 고지할 때에는 그 명령을 이행하지 아니할 경우 법 제63조에 따른 처벌을 받을 수 있음을 경고하여야 한다.', 1037);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1870, '③ 심리기일에 출석하지 아니한 피해자 및 행위자에 대한 피해자보호명령 결정의 고지는 결정서를 송달하는 것으로 한다.', 1037);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1871, '① 법 제55조의2제3항에 따른 피해자보호명령의 취소ㆍ변경 신청과 법 제55조의3제1항에 따른 피해자보호명령의 기간 연장 신청은 서면으로 한다. 이 경우 신청서에는 피해자보호명령의 취소ㆍ변경ㆍ연장이 필요한 이유를 기재하고 그 이유를 소명하여야 한다.', 1040);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1872, '② 판사는 피해자보호명령을 취소ㆍ변경ㆍ연장할 때 필요하다고 인정하는 경우에는 청구인ㆍ피해자ㆍ행위자ㆍ가정구성원, 그 밖의 참고인을 소환하여 필요한 사항을 조사ㆍ심리할 수 있다.', 1040);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1873, '③ 피해자보호명령의 취소ㆍ변경ㆍ연장 결정은 피해자보호명령이 고지된 때부터 할 수 있다.', 1040);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1874, '④ 제1항의 신청에 대한 결정은 피해자, 신청인 및 행위자에게 통지하여야 한다.', 1040);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1875, '① 항고법원이 원결정을 파기하고 스스로 임시보호명령 또는 피해자보호명령의 결정을 하는 경우에는 각각 그 결정에 관한 법 및 이 규칙의 규정을 준용한다.', 1042);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1876, '② 항고법원이 원심법원의 임시보호명령 및 그 변경 결정을 파기하고 자판하는 경우에는 임시보호명령을 하지 않는다는 뜻의 결정을 할 수 있다.', 1042);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1877, '① 행위자 및 그 보조인은 심리절차를 현저히 지연시키지 않는 범위에서 판사의 허가를 받아 배상책임의 유무와 그 범위에 관하여 필요한 증거를 제출할 수 있다.', 1045);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1878, '② 제1항의 허가를 하지 아니한 재판에 대해서는 불복을 신청하지 못한다.', 1045);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1879, '① 법원은 필요할 때에는 언제든지 행위자의 배상책임 유무와 그 범위를 인정하는 데에 필요한 증거를 조사할 수 있다.', 1046);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1880, '② 가정보호사건의 범죄사실을 인정할 증거는 행위자의 배상책임 유무와 그 범위를 인정할 증거로 할 수 있다.', 1046);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1881, '③ 제2항에 규정된 증거 외의 증거를 조사할 경우 증거조사의 방식에 관하여는 「민사소송법」의 관계 규정에 따른다.', 1046);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1882, '① 보호처분 결정과 따로 배상신청 각하 결정을 하거나 배상명령을 취소하는 결정을 한 때에는 피해자에게 그 결정을 통지하여야 한다.', 1047);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1883, '② 배상명령을 한 경우에 행위자로부터 보호처분에 대한 불복 또는 그 포기ㆍ취하, 상소권회복의 청구가 있는 때에는 그 취지를 피해자에게 통지하여야 한다.', 1047);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1884, '① 행위자가 배상명령에 대해서만 항고를 제기한 경우 원심법원은 기록과 증거물을 14일 이내에 항고법원에 송부하여야 한다.', 1048);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1885, '② 제1항은 행위자가 배상명령 또는 배상명령에 대한 항고 기각 결정에 대하여 재항고를 제기한 경우에 준용한다.', 1048);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1886, '③ 법 제60조제5항에 따라 집행이 정지되지 아니한 배상명령은 가집행선고부 배상명령으로 본다.', 1048);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1887, '① 배상명령이 제1심에서 확정된 경우 제1심 법원사무관등은 그 재판정본을 작성하여야 한다.', 1049);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1888, '② 배상명령이 제1심 외의 법원에서 확정된 경우 그 법원의 법원사무관등은 각 심급의 재판정본을 작성하여 지체 없이 제1심 법원에 송부하여야 한다. 다만, 항고법원이 제1심의 배상명령을 변경한 경우 제1심의 재판정본은 작성하지 아니한다.', 1049);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1889, '③ 제1심 법원은 확정된 배상명령의 재판정본을 영구보존하여야 한다.', 1049);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1890, '① 배상명령이 확정된 경우 제1심 또는 기록을 보관하고 있는 상급심 법원의 법원사무관등은 「민사집행법」에서 규정한 집행력 있는 정본의 부여 절차에 따라 확정된 재판정본을 교부하여야 한다.', 1050);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1891, '② 가집행선고부 배상명령이 있는 경우에는 기록을 보관하고 있는 법원이 제1항의 절차에 따라 재판정본을 교부하여야 한다.', 1050);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1892, null, 1053);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1893, null, 1054);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1894, '①지방검찰청 또는 지방검찰청지청의 장은 법 제3조ㆍ법 제4조제2항 (미수범을 포함한다)ㆍ법 제5조제4항 또는 법 제8조의 죄를 범한 사람에 대하여 공소가 제기된 경우에는 지체 없이 그 사실을 법무부장관에게 보고하여야 한다. <개정 2009.7.7, 2019.5.7>', 1060);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1895, '② 고위공직자범죄수사처장은 제1항에서 규정한 죄를 범한 사람에 대하여 공소가 제기된 경우에는 지체 없이 그 사실을 법무부장관에게 통보해야 한다. <신설 2020.7.14>', 1060);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1896, '③법무부장관은 경제사범의 관리를 위하여 필요할 경우 관계기관 또는 관계기업체의 장에게 자료의 제출을 요청할 수 있다. <개정 2009.7.7, 2020.7.14>', 1060);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1897, '① 법 제14조제1항 본문에 따른 국가ㆍ지방자치단체가 자본금의 전부 또는 일부를 출자한 기관 및 그 출연(出捐)이나 보조를 받는 기관은 별표 1부터 별표 3까지에 해당하는 기관으로 한다. <개정 2019.5.7>', 1061);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1898, '②법 제14조제1항 본문에 따른 유죄판결된 범죄행위와 밀접한 관련이 있는 기업체는 다음 각 호의 어느 하나에 해당하는 기업체로 한다. <개정 2019.5.7>', 1061);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1899, '①법 제14조제1항 단서에 따라 법무부장관의 취업승인을 받으려는 사람은 취업하려는 날의 1개월 전까지 법무부장관에게 취업승인신청서를 제출하여야 한다. <개정 2009.7.7, 2019.5.7>', 1064);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1900, '② 법무부장관은 법 제14조제1항 단서에 따른 취업의 승인 여부를 결정한 때에는 지체 없이 그 결정내용을 신청인에게 통지하여야 한다. <개정 2009.7.7>', 1064);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1901, '①제11조에 따른 관허업을 영위하기 위하여 법 제14조제2항 단서에 따른 법무부장관의 승인을 받으려는 사람은 승인신청서를 해당 관허업의 허가등에 관한 소관 행정기관의 장에게 제출하여야 한다. <개정 2009.7.7, 2019.5.7>', 1065);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1902, '②제1항에 따른 승인신청서에는 관허업의 허가등에 관한 신청서류의 사본 1부를 첨부하여야 한다. <개정 2019.5.7>', 1065);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1903, '③ 소관 행정기관의 장은 제1항에 따른 승인신청서를 받은 때에는 관허업의 허가등에 관한 신청서류의 사본이 원본과 다름없음을 확인한 후 지체 없이 이를 법무부장관에게 송부하여야 한다. <개정 2009.7.7, 2019.5.7>', 1065);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1904, '④법무부장관이 제3항에 따른 승인신청서를 송부받아 그 승인여부를 결정한 때에는 지체 없이 그 내용을 그 승인신청을 한 사람과 소관 행정기관의 장에게 통지하여야 한다. <개정 2009.7.7, 2019.5.7>', 1065);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1905, '① 법무부장관은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 민감정보, 같은 법 시행령 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호, 외국인등록번호나 그 밖의 개인정보가 포함된 자료를 처리할 수 있다.', 1066);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1906, '② 허가등에 관한 소관 행정기관의 장은 법 제14조제2항 및 이 영 제14조에 따른 허가등의 승인 신청에 관한 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다.', 1066);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1907, null, 1068);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1908, '① 지방검찰청 및 그 지청과 보통검찰부에서는 자격정지 이상의 형을 선고받은 수형인에 대한 수형인명표를 작성하여 수형인의 등록기준지 시ㆍ구ㆍ읍ㆍ면 사무소에 송부하여야 한다.', 1070);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1909, '② 지방검찰청 및 그 지청과 보통검찰부에서는 다음 각 호의 어느 하나에 해당할 때에는 수형인명표를 송부한 관서에 그 사실을 통지하여야 한다.', 1070);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1910, '① 사법경찰관은 피의자에 대한 수사자료표를 작성하여 경찰청에 송부하여야 한다. 다만, 다음 각 호의 자에 대하여는 그러하지 아니하다. <개정 2021.3.16>', 1071);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1911, '② 수사자료표를 작성할 사법경찰관의 범위는 대통령령으로 정한다.', 1071);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1912, '① 경찰청장은 수사자료표의 보존ㆍ관리를 위하여 책임자를 지정하여야 한다.', 1072);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1913, '② 경찰청장은 수사자료표를 범죄경력자료와 수사경력자료로 구분하여 전산입력한 후 관리하여야 한다.', 1072);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1914, '③ 범죄경력조회 또는 수사경력조회에 대하여 회보할 때에는 그 용도, 작성자ㆍ조회자의 성명 및 작성일시, 그 밖에 필요한 사항을 구체적으로 밝혀야 한다.', 1072);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1915, '① 수사자료표에 의한 범죄경력조회 및 수사경력조회와 그에 대한 회보는 다음 각 호의 어느 하나에 해당하는 경우에 그 전부 또는 일부에 대하여 조회 목적에 필요한 최소한의 범위에서 할 수 있다. 다만, 제8조의2제2항제3호 단서 또는 같은 조 제3항제1호에 따라 보존하는 불송치결정과 관련된 수사경력자료에 대한 조회 및 회보는 제1호에 해당하는 경우로 한정한다. <개정 2013.6.4, 2015.8.11, 2017.12.19, 2020.12.15, 2021.3.16, 2023.7.6>', 1073);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1916, '② 수사자료표를 관리하는 사람이나 직무상 수사자료표에 의한 범죄경력조회 또는 수사경력조회를 하는 사람은 그 수사자료표의 내용을 누설하여서는 아니 된다.', 1073);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1917, '③ 누구든지 제1항에서 정하는 경우 외의 용도에 사용할 목적으로 범죄경력자료 또는 수사경력자료를 취득하여서는 아니 된다.', 1073);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1918, '④ 제1항에 따라 범죄경력자료 또는 수사경력자료를 회보받거나 취득한 자는 법령에 규정된 용도 외에는 이를 사용하여서는 아니 된다.', 1073);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1919, '⑤ 제1항 각 호에 따라 범죄경력조회 및 수사경력조회와 그에 대한 회보를 할 수 있는 구체적인 범위는 대통령령으로 정한다.', 1073);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1920, '① 수형인이 자격정지 이상의 형을 받지 아니하고 형의 집행을 종료하거나 그 집행이 면제된 날부터 다음 각 호의 구분에 따른 기간이 경과한 때에 그 형은 실효된다. 다만, 구류(拘留)와 과료(科料)는 형의 집행을 종료하거나 그 집행이 면제된 때에 그 형이 실효된다.', 1074);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1921, '② 하나의 판결로 여러 개의 형이 선고된 경우에는 각 형의 집행을 종료하거나 그 집행이 면제된 날부터 가장 무거운 형에 대한 제1항의 기간이 경과한 때에 형의 선고는 효력을 잃는다. 다만, 제1항제1호 및 제2호를 적용할 때 징역과 금고는 같은 종류의 형으로 보고 각 형기(刑期)를 합산한다.', 1074);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1922, '① 다음 각 호의 어느 하나에 해당하는 경우에는 수형인명부의 해당란을 삭제하고 수형인명표를 폐기한다.', 1075);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1923, '② 제1항에 따라 수형인명부의 해당란을 삭제하는 방법 등은 대통령령으로 정한다.', 1075);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1924, '① 다음 각 호의 어느 하나에 해당하는 경우에는 제2항부터 제4항까지에 따른 보존기간이 지나면 전산입력된 수사경력자료의 해당 사항을 삭제한다. <개정 2023.7.6>', 1076);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1925, '② 제1항제1호부터 제4호까지의 경우에 대한 수사경력자료의 보존기간은 다음 각 호의 구분에 따른다. 이 경우 그 기간은 불송치결정 또는 불기소처분이 있은 날이나 판결 또는 결정이 확정된 날부터 기산(起算)한다. <개정 2021.3.16, 2023.7.6>', 1076);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1926, '③ 제2항에도 불구하고 제1항제1호ㆍ제2호의 불송치결정ㆍ불기소처분 당시 또는 같은 항 제3호ㆍ제4호의 판결ㆍ결정의 확정 당시 「소년법」 제2조의 소년에 대한 수사경력자료의 보존기간은 다음 각 호의 구분에 따른다. <개정 2023.7.6>', 1076);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1927, '④ 제1항제5호의 경우에 대한 수사경력자료의 보존기간은 3년으로 한다. 이 경우 그 기간은 불처분 결정 또는 심리불개시 결정이 있은 날부터 기산한다. <신설 2023.7.6>', 1076);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1928, '⑤ 제1항에 따라 수사경력자료의 해당 사항을 삭제하는 방법은 대통령령으로 정한다. <개정 2023.7.6>', 1076);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1929, '① 법무부장관은 전과기록이나 수사경력자료의 보관ㆍ관리 또는 조회와 관련된 업무의 개선이나 위법ㆍ부당한 사항의 시정 등을 위하여 필요하다고 인정하면 전과기록이나 수사경력자료의 보관ㆍ관리 또는 조회 업무를 담당하는 기관의 장에게 조회ㆍ회보 대장 등 관련 자료의 제출을 요청할 수 있다. 이 경우 자료의 제출을 요청받은 기관의 장은 특별한 사유가 없으면 요청에 따라야 한다.', 1077);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1930, '② 법무부장관은 제1항에 따라 제출받은 자료를 검토한 결과 개선이나 시정이 필요한 사항이 발견되었을 때에는 해당 기관의 장에게 시정 등 필요한 조치를 할 것을 요구할 수 있다.', 1077);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1931, '① 전과기록이나 수사경력자료를 관리하는 사람이 부정한 청탁을 받고 다음 각 호의 어느 하나에 해당하는 행위를 하였을 때에는 1년 이상의 유기징역에 처한다.', 1078);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1932, '② 전과기록 또는 수사경력자료의 작성에 필요한 서류에 대하여 다음 각 호의 어느 하나에 해당하는 행위를 한 사람도 제1항과 같은 형에 처한다.', 1078);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1933, '① 제6조제1항 또는 제2항을 위반하여 수사자료표의 내용을 회보하거나 누설한 사람은 5년 이하의 징역 또는 5천만원 이하의 벌금에 처한다.', 1079);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1934, '② 제6조제3항을 위반하여 범죄경력자료 또는 수사경력자료를 취득한 사람은 2년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.', 1079);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1935, '③ 제6조제4항을 위반하여 범죄경력자료 및 수사경력자료를 사용한 사람도 제2항과 같은 형에 처한다.', 1079);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1936, '① 수사자료표에는 다음 각 호의 사항을 기재한다. <개정 2022.7.5>', 1082);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1937, '② 검찰청ㆍ사법경찰관서 등 수사기관의 장은 수사자료표의 정확한 관리를 위해 입건현황과 처분현황 또는 선고현황 등을 지체 없이 경찰청에 송부해야 한다. <개정 2024.4.2>', 1082);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1938, '③ 경찰청장은 수사자료표의 내용 중 피의자의 인적사항이 일치하지 않는 등으로 처분결과 또는 선고결과가 확인되지 않는 경우에는 관계 기관에 확인을 하는 등 정확한 처분현황 또는 선고현황을 관리하기 위해 필요한 조치를 해야 한다. <개정 2024.4.2>', 1082);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1939, '④ 수사자료표를 작성하는 경우 지문을 채취할 피의자의 범위와 그 밖에 필요한 사항은 법무부령으로 정한다. <개정 2024.4.2>', 1082);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1940, null, 1087);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1941, '①전과기록 또는 수사경력자료의 보존ㆍ관리 또는 조회관련 업무를 담당하는 기관의 장은 그 업무를 직접 담당하고 있는 부서의 최상급책임자를 관리책임자로 지정하여 그 보존ㆍ관리 또는 조회에 관한 운영 및 지도업무를 담당하도록 하여야 한다.', 1088);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1942, '②제1항의 규정에 의한 관리책임자는 조회ㆍ회보대장을 비치하고 조회목적, 조회요청자의 소속ㆍ성명, 작성자 및 작성일시 그 밖에 필요한 사항을 기재하여야 한다.', 1088);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1943, '③전과기록 또는 수사경력자료의 보존ㆍ관리 또는 조회관련 업무를 담당하는 기관의 장은 전과기록 또는 수사경력자료의 내용이 불법유출되거나 범죄수사ㆍ재판 등 법 및 다른 법령에 규정된 목적외의 다른 목적으로 사용되지 아니하도록 조회ㆍ회보대장을 수시로 점검하는 등 필요한 조치를 하여야 한다.', 1088);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1944, '④ 삭제 <2006.7.27>', 1088);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1945, '①법 제6조제1항제1호부터 제4호까지의 경우에는 범죄경력자료 및 수사경력자료 전부에 대하여 범죄경력조회ㆍ수사경력조회 및 그 회보를 할 수 있다. <개정 2022.7.5>', 1089);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1946, '②법 제6조제1항제5호부터 제9호까지의 규정에 따라 수사자료표에 의한 범죄경력조회ㆍ수사경력조회 및 그 회보를 할 수 있는 범위는 다음 각 호와 같다. <개정 2006.7.27, 2015.11.4>', 1089);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1947, '③법 제6조제1항제10호의 경우에는 다른 법률에서 구체적으로 정한 범위에 한하여 조회 및 그 회보를 할 수 있다. <개정 2006.7.27>', 1089);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1948, '④ 삭제 <2007.12.28>', 1089);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1949, '① 「소년법」상의 소년부송치 및 보호처분은 제7조제1항에 해당하는 경우가 아니면 그 결정이 있은 때부터 3년이 지난 후에는 회보를 하여서는 아니 된다.', 1090);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1950, '② 제7조제1항에도 불구하고 법 제6조제1항제4호에 따라 수사자료표의 내용을 확인하기 위하여 본인이 신청하는 경우에는 본인이 별도로 요구하지 아니하는 한 다음 각 호의 사항을 제외하고 회보하여야 한다. <개정 2015.11.4, 2024.4.2>', 1090);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1951, '③ 제7조제1항에도 불구하고 법 제6조제1항제4호에 따라 외국 입국ㆍ체류 허가에 필요하여 본인이 신청하는 경우에는 다음 각 호의 사항을 제외하고 회보하여야 한다. <신설 2015.11.4, 2024.4.2>', 1090);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1952, '①법 제8조제2항의 규정에 의한 수형인명부의 해당란의 삭제는 수형인명부의 해당란에 가로로 두 줄을 긋고 수형인명부관리자의 직인을 날인하는 방법으로 한다. <개정 2003.9.29, 2006.7.27>', 1091);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1953, '② 법 제8조의2제1항에 따른 수사경력자료의 해당 사항 삭제는 같은 조 제2항부터 제4항까지에 따른 수사경력자료의 보존기간이 경과한 때에 해당 사항을 전산자료에서 지체 없이 삭제하는 방법으로 하되, 삭제한 사람의 소속과 성명 및 삭제 일시 등 삭제에 관한 사항을 삭제한 날부터 5년간 전산으로 관리해야 한다. <개정 2024.4.2>', 1091);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1954, '①경찰청장은 수사자료표에 등재된 사람이 사망한 때에는 그 수사자료표를 폐기할 수 있다.', 1092);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1955, '②경찰청장은 수사자료표를 마이크로필름 또는 전산자료의 형태로 관리ㆍ보존하는 경우에는 종전의 수사자료표를 폐기할 수 있다.', 1092);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1956, null, 1093);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1957, '① 「성폭력범죄의 처벌 등에 관한 특례법 시행령」(이하 "영"이라 한다) 제3조제4항 전단에 따른 신상정보의 제출 확인서는 별지 제2호서식과 같다.', 1096);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1958, '② 영 제3조제4항 후단에 따른 안내문은 별지 제3호서식과 같다.', 1096);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1959, '① 영 제4조의2제1항에 따른 출국신고서는 별지 제5호서식과 같다.', 1098);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1960, '② 영 제4조의2제3항에 따른 입국신고서는 별지 제6호서식과 같다.', 1098);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1961, '① 영 제5조의3제1항에 따른 통지의 신청 또는 그 철회의 신청은 별지 제8호서식에 따른다.', 1100);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1962, '② 영 제5조의3제2항에 따른 등록정보의 통지는 별지 제9호서식에 따른다.', 1100);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1963, '① 법 제45조의2제2항 및 영 제6조의2제1항에 따른 신상정보 등록 면제 신청서는 별지 제11호서식과 같다.', 1102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1964, '② 영 제6조의2제3항 단서에 따른 신상정보 등록 면제 신청 결과의 통지는 별지 제12호서식에 따른다.', 1102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1965, '① 영 제6조의4제1항에 따른 등록정보 폐기 사실의 통지 신청 또는 그 철회 신청은 별지 제13호서식에 따른다.', 1103);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1966, '② 영 제6조의4제2항 및 제3항에 따른 등록정보 폐기 사실의 통지는 별지 제14호서식에 따른다.', 1103);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1967, null, 1106);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1968, '① 부패재산은 몰수할 수 있다. 다만, 다른 법령에 따라 부패재산을 몰수하여야 하는 경우에는 그 법령에 따라 몰수한다.', 1107);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1969, '② 제1항에 따라 몰수하는 부패재산이 부패재산 외의 재산과 합하여진 경우에는 부패재산과 그 외의 재산이 합하여진 재산(이하 "혼합재산"이라 한다) 중 부패재산의 비율에 상당하는 부분을 몰수할 수 있다.', 1107);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1970, '① 제3조에 따른 몰수는 부패재산 또는 혼합재산이 범인 외의 자에게 귀속되지 아니한 경우에 한한다. 다만, 범인외의 자가 범죄 후 그 정(情)을 알면서 그 부패재산 또는 혼합재산을 취득한 경우(그 부패재산 또는 혼합재산의 취득이 「범죄수익은닉의 규제 및 처벌 등에 관한 법률」 제4조 단서에 해당하는 경우에는 제외한다)에는 그 부패재산 또는 혼합재산이 범인 외의 자에게 귀속된 경우에도 몰수할 수 있다.', 1108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1971, '② 부패재산 또는 혼합재산이 범인 외의 자에게 상속이나 증여 등으로 무상(無償) 또는 현저한 저가(低價)로 귀속된 경우에는 범인 외의 자가 그 정을 알지 못하고 그 부패재산 또는 혼합재산을 취득한 때에도 전부 또는 일부를 몰수할 수 있다.', 1108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1972, '③ 지상권, 저당권, 그 밖의 권리가 그 위에 존재하는 재산을 제3조에 따라 몰수하는 경우에 범인 외의 자가 범죄 전에 그 권리를 취득한 때 또는 범인 외의 자가 범죄 후 그 정을 알지 못하고 그 권리를 취득한 때에는 이를 존속시킨다.', 1108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1973, '① 부패재산을 몰수할 수 없거나 그 재산의 성질, 사용상황, 그 재산에 관한 범인 외의 자의 권리 유무, 그 밖의 사정으로 인하여 이를 몰수함이 상당하지 아니하다고 인정될 때에는 그 가액(價額)을 범인으로부터 추징한다.', 1109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1974, '② 제4조제1항 또는 제2항에 따라 범인 외의 자로부터 추징하는 경우에는 제1항을 준용한다.', 1109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1975, '① 제3조의 재산이 범죄피해재산으로서 범죄피해자가 그 재산에 관하여 범인에 대한 재산반환청구권 또는 손해배상청구권 등을 행사할 수 없는 등 피해회복이 심히 곤란하다고 인정되는 경우에는 몰수ㆍ추징할 수 있다.', 1110);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1976, '② 이 법에 따라 몰수ㆍ추징된 범죄피해재산은 피해자에게 환부(還付)한다.', 1110);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1977, '③ 범죄피해재산의 환부 요건 및 절차 등 범죄피해재산의 환부에 필요한 사항은 대통령령으로 정한다.', 1110);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1978, null, 1111);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1979, '① 법무부장관은 요청국으로부터 집행재산등의 반환요청이 있는 때에는 그 전부 또는 일부의 반환을 결정할 수 있다. 다만, 요청국에서 반환요청을 철회하거나 집행재산등의 가치가 미미하거나 주권(主權), 국가안전보장, 안녕질서 또는 미풍양속 등 대한민국의 중대한 이익 보호를 위하여 집행재산등을 반환하는 것이 적당하지 아니하다고 인정되는 경우에는 그러하지 아니하다.', 1115);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1980, '② 법무부장관은 집행재산등의 전부 또는 일부를 반환하기로 결정한 때에는 그 반환을 위하여 상당하다고 인정되는 지방검찰청검사장(이하 "검사장"이라 한다)에게 제7조에 따른 공조에 필요한 조치를 명하고, 그 집행재산등을 반환하기 위하여 보관할 것을 명하여야 한다.', 1115);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1981, '③ 법무부장관은 다음 각 호의 어느 하나에 해당하는 경우에는 제2항에 따른 결정을 하기 전이라도 필요하다고 인정하는 때에는 검사장에게 제8조에 따른 국제공조에 필요한 조치를 명하거나 집행재산등의 전부 또는 일부를 임시보관할 것을 명할 수 있다.', 1115);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1982, '① 제11조제2항에 따른 명령을 받은 검사장은 소속 검사에게 집행재산등의 반환에 필요한 조치를 취하도록 명하여야 한다.', 1117);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1983, '② 제11조제2항에 따른 명령을 받은 검사장은 반환을 위한 집행재산등의 보관을 종료한 때에는 지체 없이 집행재산등을 법무부장관에게 인도하여야 한다.', 1117);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1984, '① 법무부장관은 제13조에 따른 집행재산등을 인도받은 때에는 이를 외교부장관에게 이관하여야 한다. <개정 2013.3.23>', 1118);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1985, '② 법무부장관은 제1항에 따라 집행재산등을 이관하는 경우에 그 집행재산등의 사용ㆍ반환 등에 관하여 요청국이 지켜야 할 준수사항을 정하여 그 이행의 보증을 요구하도록 외교부장관에게 요청할 수 있다. <개정 2013.3.23>', 1118);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1986, '③ 외교부장관은 법무부장관으로부터 제2항에 따른 요청을 받은 때에는 적절한 조치를 취하고 그 결과를 법무부장관에게 통지하여야 한다. <개정 2013.3.23>', 1118);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1987, '① 법무부장관은 외국에 대하여 몰수 또는 추징의 확정재판 집행이나 몰수 또는 추징을 위한 재산보존의 공조를 요청할 수 있다. 이 경우 법무부장관은 집행재산등의 환수(還收)를 요청할 수 있다.', 1119);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1988, '② 법무부장관은 제1항에 따라 집행재산등의 환수를 요청하는 경우 환수요청서를 외교부장관에게 송부하여야 한다. 다만, 긴급을 요하는 사정이나 특별한 사정이 있는 경우에는 외교부장관의 동의를 받아 환수요청서를 직접 외국에 송부할 수 있다. <개정 2013.3.23>', 1119);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1989, '③ 고위공직자범죄수사처장은 외국에 대하여 몰수 또는 추징을 위한 재산보존의 공조요청을 하려면 법무부장관에게 공조요청서를 송부하여야 한다. <신설 2021.1.5>', 1119);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1990, '① 외국으로부터 집행재산등의 환수는 외교부장관이 행한다. <개정 2013.3.23>', 1121);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1991, '② 외교부장관은 환수받은 집행재산등을 법무부장관에게 이관하여야 한다. <개정 2013.3.23>', 1121);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1992, '① 법무부장관은 송부받은 집행재산등이 금전 이외의 재산인 때에는 검사로 하여금 이를 환가(換價)하거나 징수하게 할 수 있다.', 1122);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1993, '② 제1항에도 불구하고 환수받은 집행재산등의 가액이 현저하게 낮거나 집행재산등의 매각에 있어 경제적 효용성이 없는 등의 사유로 매수인이 없거나 매각하더라도 매수인이 없을 것이 분명한 때에는 그 집행재산등을 폐기할 수 있다.', 1122);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1994, '③ 검사는 외국에 대하여 집행재산등의 매각을 공조요청할 필요가 있는 경우에는 법무부장관에게 매각요청서를 송부하여야 하고, 법무부장관은 공조요청하는 것이 상당하다고 인정하는 경우에는 이를 외교부장관에게 송부하여야 한다. <개정 2013.3.23>', 1122);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1995, '① 이 법에 따른 몰수ㆍ추징의 집행 및 처분에 있어서 이 법에 특별한 규정이 없는 한 그 성질에 반하지 아니한 것은 「형사소송법」을 준용한다.', 1124);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1996, '② 제18조에 규정된 집행재산등의 처분은 「검찰청법」 제11조에 따른 압수물 및 징수 사무에 관한 규정에 따라 절차를 진행한다.', 1124);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1997, null, 1127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1998, '① 검사는 회복대상재산을 보관하게 된 때에는 피해자등에게 회복대상재산을 환부하기 위한 절차(이하 "범죄피해재산 환부절차"라 한다)를 개시해야 한다. 다만, 회복대상재산의 가액이 비용에 미치지 못할 것으로 예상되는 등 범죄피해재산 환부절차를 개시하는 것이 적절하지 않다고 인정하는 경우에는 그렇지 않다.', 1128);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (1999, '② 검사는 회복대상재산을 추가적으로 보관하게 될 가능성이나 회복대상재산의 환가(換價) 절차에 걸리는 기간 등을 고려하여 제1항에 따른 범죄피해재산 환부절차의 개시시기를 조정할 수 있다.', 1128);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2000, '③ 검사는 회복대상재산이 금전 외의 재산으로서 그 재산의 성질, 권리관계 등에 비추어 그대로 보관하는 것이 적절하지 않다고 인정하는 경우에는 이를 환가하거나 징수해서 금전으로 보관할 수 있다.', 1128);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2001, '① 검사는 범죄피해재산 환부절차를 개시한 경우 다음 각 호의 사항을 피해자등에게 신속하게 통지해야 한다.', 1130);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2002, '② 검사는 피해자등이 소재불명(所在不明)이거나 그 밖의 사유로 제1항에 따른 통지를 할 수 없는 경우에는 제1항 각 호의 사항을 관보와 검사가 소속된 검찰청 인터넷 홈페이지에 공고해야 한다.', 1130);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2003, '③ 제1항에 따른 통지 및 제2항에 따른 공고에 필요한 사항은 법무부령으로 정한다.', 1130);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2004, '① 피해자등은 회복대상재산의 환부를 받으려는 경우에는 제5조제1항에 따른 통지를 받은 날 또는 같은 조 제2항에 따른 공고일부터 60일 이내에 회복대상재산을 보관하고 있는 검사에게 다음 각 호의 사항을 적은 청구서를 작성하여 법무부령으로 정하는 바에 따라 회복대상재산의 환부를 청구해야 한다. 이 경우 청구서에는 다음 각 호의 사항을 소명(疏明)할 수 있는 자료를 첨부해야 한다.', 1131);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2005, '② 청구인은 제1항에 따라 청구서를 제출한 후 청구사항을 변경하려는 경우에는 제7조에 따른 회복대상재산 환부결정이 있기 전에 제1항에 따른 청구를 한 검사에게 법무부령으로 정하는 바에 따라 변경사항을 신고해야 한다.', 1131);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2006, '① 검사는 제6조에 따른 환부청구를 받은 경우에는 다음 각 호의 구분에 따라 신속하게 피해인정재산 및 그 가액과 회복대상재산의 환부 여부를 결정해야 한다.', 1132);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2007, '② 검사는 제1항 각 호에 따른 결정을 하는 데 필요한 조사를 할 수 있다.', 1132);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2008, '③ 검사는 제1항 각 호에 따른 결정을 했을 때에는 지체 없이 그 결정 취지와 이유를 법무부령으로 정하는 바에 따라 청구인에게 통지해야 한다.', 1132);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2009, '① 검사는 제7조제1항제1호 또는 제3호의 결정을 했을 때에는 지체 없이 청구인에게 피해인정재산의 범위에서 각 호의 구분에 따라 회복대상재산을 환부해야 한다.', 1133);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2010, '② 청구인은 제1항제1호에 따라 금전 외의 재산을 환부받으려는 경우에는 검사가 소속된 검찰청에 비용을 납부해야 한다.', 1133);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2011, '③ 검사는 제7조제1항제1호 또는 제3호의 결정을 받은 청구인이 2인 이상인 경우로서 보관하고 있는 회복대상재산으로 각 청구인의 피해인정재산을 모두 환부할 수 없을 때에는 각 청구인의 피해인정재산의 가액에 비례하여 환부한다.', 1133);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2012, '① 청구인은 제7조제1항제2호부터 제4호까지에 따른 결정에 불복하는 경우 그 결정에 대한 통지를 받은 날부터 30일 이내에 해당 결정을 한 검사가 소속된 검찰청의 장에게 법무부령으로 정하는 바에 따라 이의신청을 할 수 있다.', 1135);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2013, '② 제1항에 따른 이의신청을 받은 검찰청의 장은 제11조에 따른 범죄피해재산환부심의회를 거쳐 다음 각 호의 구분에 따라 결정한다.', 1135);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2014, '③ 검찰청의 장은 제2항 각 호에 따른 결정을 한 경우 지체 없이 결정의 취지와 이유를 법무부령으로 정하는 바에 따라 이의신청을 한 청구인에게 통지해야 한다.', 1135);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2015, '① 회복대상재산의 환부에 관한 사항을 심의하기 위해 각 검찰청에 범죄피해재산환부심의회(이하 "심의회"라 한다)를 둔다.', 1136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2016, '② 심의회는 다음 각 호의 사항을 심의한다.', 1136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2017, '③ 심의회는 위원장 1명을 포함하여 4명 이상 7명 이내의 위원으로 구성한다.', 1136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2018, '④ 심의회의 위원장은 각 검찰청의 장이 소속 직원 중에서 지명한다.', 1136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2019, '⑤ 심의회의 위원(이하 "위원"이라 한다)은 각 검찰청의 장이 위촉하거나 임명하되, 변호사 자격이 있는 사람을 2명 이상 포함해야 한다.', 1136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2020, '⑥ 제5항에 따라 위촉된 위원의 임기는 2년으로 하고, 한 차례만 연임할 수 있다.', 1136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2021, '⑦ 심의회의 사무를 처리하기 위해 심의회에 간사를 두며, 간사는 범죄피해재산 환부절차를 담당하는 검사가 된다.', 1136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2022, '⑧ 제1항부터 제7항까지에서 규정한 사항 외에 심의회의 구성 및 운영에 필요한 사항은 법무부령으로 정한다.', 1136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2023, null, 1140);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2024, '① 영 및 이 규칙에 따른 통지를 할 때에는 「우편법 시행규칙」 제25조제1항제6호에 따른 특별송달로써 해야 한다.', 1141);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2025, '② 영 제5조제1항에 따른 범죄피해재산 환부절차 개시에 관한 통지는 별지 제1호서식에 따른다.', 1141);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2026, '① 청구인은 영 제6조제1항에 따라 회복대상재산의 환부를 청구하려는 경우에는 별지 제2호서식의 청구서에 다음 각 호의 서류를 첨부하여 청구해야 한다.', 1142);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2027, '② 영 제6조제1항제4호에서 "범죄피해재산의 환부청구를 위해 필요한 사항으로서 법무부령으로 정하는 사항"이란 다음 각 호의 사항을 말한다.', 1142);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2028, '③ 검사는 제1항에 따른 청구서를 제출받은 경우에는 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통해 다음 각 호의 서류를 확인해야 한다. 다만, 청구인이 제1호의 서류 확인에 동의하지 않은 경우에는 그 서류를 첨부하게 해야 한다.', 1142);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2029, '① 청구인은 영 제6조제2항에 따라 청구사항을 변경하려는 경우에는 별지 제3호서식의 변경신고서에 그 변경사항을 소명하는 자료를 첨부하여 범죄피해재산 환부절차를 담당하는 검사에게 제출해야 한다.', 1143);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2030, '② 검사는 제1항에 따른 변경신고서를 제출받은 경우에는 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통해 다음 각 호의 서류를 확인해야 한다. 다만, 청구인이 제1호의 서류 확인에 동의하지 않은 경우에는 그 서류를 첨부하게 해야 한다.', 1143);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2031, '① 영 제7조제1항에 따른 결정은 별지 제4호서식의 회복대상재산 환부결정서에 따른다.', 1144);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2032, '② 검사가 영 제7조제3항에 따라 회복대상재산 환부 여부의 결정 취지와 이유를 청구인에게 통지할 때에는 별지 제5호서식에 따른다.', 1144);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2033, '① 청구인은 영 제10조제1항에 따라 이의신청을 하려는 경우에는 별지 제7호서식의 이의신청서에 다음 각 호의 서류를 첨부하여 신청해야 한다.', 1146);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2034, '② 검사는 제1항에 따른 이의신청서를 제출받은 경우에는 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통해 다음 각 호의 서류를 확인해야 한다. 다만, 이의신청을 한 청구인이 제1호의 서류 확인에 동의하지 않은 경우에는 그 서류를 첨부하게 해야 한다.', 1146);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2035, '① 영 제10조제2항에 따른 이의신청에 대한 결정은 별지 제8호서식의 결정서에 따른다.', 1147);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2036, '② 검찰청의 장은 영 제10조제3항에 따라 이의신청을 한 청구인에게 이의신청에 대한 결정의 취지와 이유를 통지할 때에는 별지 제9호서식에 따른다.', 1147);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2037, '① 영 제11조에 따른 범죄피해재산환부심의회(이하 "심의회"라 한다)의 위원장(이하 "위원장"이라 한다)은 심의회를 대표하고 심의회의 업무를 총괄한다.', 1148);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2038, '② 위원장은 심의회를 소집하고 그 의장이 된다.', 1148);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2039, '③ 심의회는 심의회의 위원(이하 "위원"이라 한다) 과반수의 출석으로 개의(開議)하고, 출석위원 과반수의 찬성으로 의결한다.', 1148);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2040, '④ 심의회에 참석한 위원에게는 예산의 범위에서 수당을 지급할 수 있다.', 1148);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2041, '⑤ 제1항부터 제4항까지에서 규정한 사항 외에 심의회의 구성 및 운영에 필요한 사항은 각 검찰청의 장이 정한다.', 1148);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2042, '① 위원이 다음 각 호의 어느 하나에 해당하는 경우에는 심의회의 심의ㆍ의결에서 제척(除斥)된다.', 1149);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2043, '② 해당 안건의 당사자는 위원에게 공정한 심의ㆍ의결을 기대하기 어려운 사정이 있는 경우에는 심의회에 기피 신청을 할 수 있고, 심의회는 의결로 기피 여부를 결정한다. 이 경우 기피 신청의 대상인 위원은 그 의결에 참여할 수 없다.', 1149);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2044, '③ 위원이 제1항 각 호에 따른 제척사유에 해당하는 경우에는 스스로 해당 안건의 심의ㆍ의결에서 회피해야 한다.', 1149);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2045, null, 1150);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2046, null, 1152);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2047, null, 1155);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2048, null, 1156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2049, '① 다음 각 호의 어느 하나에 해당하는 물건은 요청국에 인도할 수 있다. 다만, 그 물건에 대한 제3자의 권리는 침해하지 못한다.', 1158);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2050, '② 제1항에 따라 물건을 인도할 때에는 대한민국이 그 물건에 대한 권리를 포기한 경우가 아니면 그 반환에 대한 요청국의 보증이 있어야 한다.', 1158);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2051, '① 요청국으로부터 공조범죄와 관계있는 사람 등에 대하여 수사 또는 재판 절차에 협조하도록 요청받은 경우에는, 그 요청된 당사자가 서면으로 동의하는 경우에만 요청국에서 협조하게 할 수 있다.', 1159);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2052, '② 제1항의 경우 협조요청의 당사자에 대하여는 그 이전에 한 행위로 요청국에서 기소되거나 처벌받지 아니하고 자유를 제한당하지 아니한다는 요청국의 보증이 있어야 한다.', 1159);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2053, '③ 교정시설(矯正施設)에서 형을 받고 있는 사람(이하 "수형자"라 한다)이 제1항에 따른 요청의 당사자인 경우 그 수형자에 대하여는 제2항에도 불구하고 대한민국의 요구대로 계속 구금되며 구금 상태로 대한민국으로 송환된다는 요청국의 보증이 있어야 한다. 이 경우 요청국에서 구금한 기간은 대한민국에서 집행할 구금 일수에 포함한다.', 1159);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2054, '① 외국에서 구금되어 있던 사람이 공조에 따라 대한민국에 인도되는 경우에는, 공조 목적을 이행한 후 그 사람을 다시 외국으로 송환하기 위하여 공조요청한 곳을 관할하는 지방법원 판사가 발부한 영장에 의하여 구속할 수 있다.', 1160);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2055, '② 제1항의 구속영장에는 다음 각 호의 사항을 기재하고 판사가 서명날인하여야 한다.', 1160);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2056, '③ 제1항의 송환에 관하여는 그 성질에 반하지 아니하는 범위에서 「범죄인인도법」 제2장제3절 및 제4절을 준용한다.', 1160);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2057, '① 공조요청은 다음 각 호의 사항을 기재한 서면(이하 "공조요청서"라 한다)으로 한다.', 1162);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2058, '② 공조요청이 증인신문, 물건의 인도, 요청국에서의 증언 등의 협조에 관한 것일 때에는 그것이 수사 또는 재판에 반드시 필요하다는 요청국의 소명(疏明)이 있어야 한다.', 1162);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2059, '① 공조요청서를 받은 법무부장관은 공조요청에 응하는 것이 타당하다고 인정하는 경우에는 제2항의 경우를 제외하고는 다음 각 호의 어느 하나의 조치를 하여야 한다. <개정 2021.1.5>', 1165);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2060, '② 법무부장관은 공조요청이 법원이나 검사 또는 고위공직자범죄수사처장이 보관하는 소송서류의 제공에 관한 것일 경우에는 그 서류를 보관하고 있는 법원이나 검사 또는 고위공직자범죄수사처장에게 공조요청서를 송부하여야 한다. <개정 2021.1.5>', 1165);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2061, '③ 법무부장관은 이 법 또는 공조조약에 따라 공조할 수 없거나 공조하지 아니하는 것이 타당하다고 인정하는 경우 또는 공조를 연기하려는 경우에는 외교부장관과 협의하여야 한다. <개정 2013.3.23>', 1165);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2062, '① 검사는 공조에 필요한 자료를 수집하기 위하여 관계인의 출석을 요구하여 진술을 들을 수 있고, 감정ㆍ통역 또는 번역을 촉탁할 수 있으며, 서류나 그 밖의 물건의 소유자ㆍ소지자(所持者) 또는 보관자에게 그 제출을 요구하거나, 행정기관이나 그 밖의 공사단체(公私團體)에 공조에 필요한 사실을 조회하거나 필요한 사항의 보고를 요구할 수 있다.', 1167);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2063, '② 검사는 공조에 필요한 경우에는 판사에게 청구하여 발급받은 영장에 의하여 압수ㆍ수색 또는 검증을 할 수 있다.', 1167);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2064, '③ 검사는 요청국에 인도하여야 할 증거물 등이 법원에 제출되어 있는 경우에는 법원의 인도허가 결정을 받아야 한다.', 1167);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2065, '④ 검사는 사법경찰관리를 지휘하여 제1항의 수사를 하게 할 수 있고, 사법경찰관은 검사에게 신청하여 검사의 청구로 판사가 발부한 영장에 의하여 제2항에 따른 압수ㆍ수색 또는 검증을 할 수 있다.', 1167);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2066, '① 제17조제2항에 따른 영장 청구와 제18조에 따른 증인신문 청구는 그 검사가 소속한 지방검찰청 또는 고위공직자범죄수사처에 대응하는 지방법원의 판사에게 하여야 한다. <개정 2021.1.5>', 1170);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2067, '② 제17조제3항에 따른 증거물 등의 인도허가 청구는 그 증거물 등이 제출되어 있는 법원에 하여야 한다.', 1170);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2068, '① 제15조제1항제1호에 따른 명령 또는 요구를 받은 검사장 또는 고위공직자범죄수사처장은 공조에 필요한 조치를 마치면 지체 없이 수집한 공조 자료 등을 법무부장관에게 송부하여야 한다. <개정 2021.1.5>', 1171);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2069, '② 제15조제1항제2호에 따른 명령을 받은 교정시설의 장은 수형자를 이송하는 데 필요한 조치를 마치면 지체 없이 법무부장관에게 보고하여야 한다.', 1171);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2070, '③ 제15조제2항에 따라 공조요청서를 받은 법원 또는 검사는 지체 없이 의견을 첨부하여 소송서류 또는 그 등본을 법무부장관에게 송부하여야 하고, 송부할 수 없는 경우에는 이유를 붙여 그 공조요청서를 법무부장관에게 반송하여야 한다.', 1171);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2071, '① 법무부장관은 제21조에 따른 공조 자료 등을 받거나 보고받았을 때에는 공조에 필요한 자료를 외교부장관에게 송부하여야 한다. <개정 2013.3.23>', 1172);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2072, '② 법무부장관은 제1항에 따라 자료를 송부할 때에는 그 자료 등의 사용ㆍ반환 또는 기밀 유지 등에 관하여 요청국이 지켜야 할 준수사항을 정하여, 그 이행에 대한 보증을 요구하도록 외교부장관에게 요청할 수 있다. <개정 2013.3.23>', 1172);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2073, '③ 외교부장관은 법무부장관으로부터 제2항에 따른 요청을 받았을 때에는 적절한 조치를 한 후 그 결과를 법무부장관에게 통지하여야 한다. <개정 2013.3.23>', 1172);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2074, '① 법무부장관은 법원에서 하여야 할 형사재판에 관한 공조요청서를 받았을 때에는 이를 법원행정처장에게 송부하여야 한다. 다만, 이 법 또는 공조조약에 따라 공조할 수 없거나 공조하지 아니하는 것이 타당하다고 인정하는 경우에는 그러하지 아니하다.', 1173);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2075, '② 법무부장관은 제1항 단서에 따라 공조하지 아니하는 것이 타당하다고 인정하는 경우에는 법원행정처장과 협의하여야 한다.', 1173);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2076, '① 제24조에 따라 공조요청서를 받은 관할 지방법원장은 서류 등의 송달에 관한 요청인 경우에는 송달 결과에 관한 증명서를 법원행정처장에게 송부하고, 증거조사에 관한 요청인 경우에는 증인신문 조서나 그 밖에 증거조사 결과를 기재한 조서 또는 증거조사가 불가능하게 된 사유를 기재한 서면을 법원행정처장에게 송부하여야 한다.', 1177);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2077, '② 법원행정처장은 관할 지방법원장으로부터 제1항에 따른 자료를 받았을 때에는 이를 법무부장관에게 송부하여야 한다.', 1177);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2078, '① 법원이 형사재판에 관하여 외국에 공조요청을 하는 경우에는 법원행정처장에게 공조요청서를 송부하여야 한다. 이 경우 법원은 그 사실을 검사에게 통지하여야 한다.', 1183);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2079, '② 법원행정처장은 제1항에 따른 공조요청서를 받았을 때에는 법무부장관에게 이를 송부하여야 한다.', 1183);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2080, '① 외국의 공조요청에 드는 비용은 요청국과 특별한 약정이 없으면 요청국이 부담한다. 다만, 대한민국의 영역에서 발생하는 비용은 대한민국이 부담할 수 있다.', 1186);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2081, '② 이 법 또는 공조조약에 따라 요청국이 공조에 드는 비용을 부담하도록 되어 있는 경우에는 요청국으로부터 그 비용 지급에 대한 보증을 받아야 한다.', 1186);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2082, '① 행정안전부장관은 국제형사경찰기구로부터 외국의 형사사건 수사에 대하여 협력을 요청받거나 국제형사경찰기구에 협력을 요청하는 경우에는 다음 각 호의 조치를 취할 수 있다. <개정 2013.3.23, 2014.11.19, 2017.7.26>', 1188);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2083, '② 제1항 각 호를 제외한 협력요청이 이 법에 따른 공조에 관한 것인 경우에는 이 법에 따른다.', 1188);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2084, '① 「성폭력범죄자의 성충동 약물치료에 관한 법률」(이하 "법"이라 한다) 제4조제2항 및 제6항에 따라 검사는 같은 조 제1항에 따른 성충동 약물치료명령(이하 "치료명령"이라 한다)을 청구하기 전에 다음 각 호의 어느 하나에 해당하는 시설 또는 기관의 정신건강의학과 전문의에게 치료명령 청구대상자(이하 "치료명령피청구자"라 한다)에 대한 진단이나 감정을 의뢰하여야 한다. <개정 2011.11.23, 2016.11.29, 2017.5.29>', 1192);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2085, '② 제1항에 따라 치료명령피청구자를 진단하거나 감정하는 정신건강의학과 전문의는 치료명령피청구자를 직접 면접하여 진단이나 감정을 실시하여야 하며, 진단이나 감정에 필요하면 심리적ㆍ생리적 평가도구를 사용할 수 있다. <개정 2011.11.23>', 1192);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2086, '① 검사는 법 제5조제1항에 따라 보호관찰소(지소를 포함한다. 이하 같다)의 장에게 조사를 요청할 때에는 치료명령피청구자의 인적사항 및 범죄사실의 요지를 통보하여야 한다. 이 경우 법무부령으로 정하는 참고자료를 함께 보낼 수 있다.', 1193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2087, '② 보호관찰소의 장은 법 제5조제1항에 따른 조사를 위하여 필요하면 교도소ㆍ소년교도소ㆍ구치소ㆍ군교도소(이하 "수용시설"이라 한다)의 장, 경찰서장, 치료감호시설의 장에게 필요한 협조를 요청할 수 있다. 이 경우 요청을 받은 기관의 장은 특별한 사유가 없으면 협조하여야 한다.', 1193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2088, '① 법 제7조제1항제1호에서 "치료명령 피청구자를 특정할 수 있는 사항"이란 다음 각 호의 사항을 말한다.', 1194);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2089, '② 법 제7조제1항제4호에서 "대통령령으로 정하는 사항"이란 다음 각 호의 사항을 말한다.', 1194);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2090, '① 법 제8조의2제1항부터 제3항까지의 규정에 따라 치료명령의 집행 면제를 신청하려는 사람은 법무부령으로 정하는 신청서를 주거지 또는 현재지를 관할하는 지방법원(지원을 포함한다)에 제출하여야 한다.', 1195);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2091, '② 법원은 보호관찰소의 장에게 법 제8조의2제5항에 따라 필요한 사항의 조사를 요청하는 경우에는 치료명령을 받은 사람의 인적사항 및 범죄사실의 요지를 통보하여야 한다. 이 경우 법원은 필요하다고 인정하는 경우에는 참고자료를 송부할 수 있다.', 1195);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2092, '① 법 제10조제1항제3호에 따른 인지행동 치료 등 심리치료 프로그램(이하 "심리치료프로그램"이라 한다)은 다음 각 호의 내용을 포함하여야 한다.', 1196);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2093, '② 심리치료프로그램은 성충동 약물치료(이하 "약물치료"라 한다) 기간 동안 월 1회 이상 실시되어야 한다.', 1196);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2094, '③ 법무부장관은 심리치료프로그램의 개발과 전문 집행 인력의 양성을 위하여 노력하여야 한다.', 1196);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2095, '① 검사는 치료명령의 판결이 확정된 경우에는 지체 없이 치료명령을 선고받은 사람(이하 "치료명령을 받은 사람"이라 한다)의 주거지를 관할하는 보호관찰소의 장에게 법 제13조제2항에 따라 지휘 서면을 보내야 한다.', 1197);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2096, '② 제1항에 따른 지휘 서면에는 법 제4조제2항에 따른 정신건강의학과 전문의의 감정서를 첨부하여야 한다. <개정 2011.11.23>', 1197);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2097, '① 법 제13조제1항에 따라 치료명령을 집행하는 보호관찰관은 치료명령을 집행하기 전에 다음 각 호의 서류 모두를 확인하여야 한다. <개정 2011.11.23, 2017.12.29>', 1198);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2098, '② 보호관찰관은 치료명령을 집행하기 전에 치료명령을 받은 사람에게 다음 각 호의 사항 모두를 알려 주어야 한다.', 1198);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2099, '③ 보호관찰관은 약물 투여의 방법으로 치료명령을 집행할 때에는 치료기관 의사의 진단과 처방에 따라 약물을 투여하여야 하며, 약물 투여와 함께 호르몬 수치 검사를 실시하여야 한다.', 1198);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2100, '① 법 제14조제1항에 따라 치료명령을 받은 사람에게 투여할 약물은 다음 각 호의 약물 중에서 법무부장관이 정하여 고시하는 약물로 한다.', 1199);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2101, '② 법무부장관은 제1항에 따라 약물을 지정ㆍ고시할 때에는 반드시 정신건강의학과 전문의, 비뇨의학과 전문의 등 관계 전문가의 의견을 들어야 한다. <개정 2011.11.23, 2017.11.21>', 1199);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2102, '① 법 제14조제1항 및 제6항에 따라 보호관찰관은 다음 각 호의 시설 또는 기관(이하 "치료기관"이라 한다)으로 하여금 약물치료를 실시하게 할 수 있다. <개정 2017.5.29>', 1200);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2103, '② 제1항에 따라 약물치료를 실시한 치료기관에 대해서는 예산의 범위에서 치료비용의 전부를 지급하여야 한다.', 1200);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2104, '① 치료명령을 받은 사람을 수용하고 있는 수용시설의 장은 치료명령을 받은 사람이 형의 집행이 종료되거나 면제ㆍ가석방 등의 사유로 석방되기 3개월 전부터 2개월 전까지 사이에 「형의 집행 및 수용자의 처우에 관한 법률」 제37조제2항에 따라 치료명령을 받은 사람을 치료감호시설로 이송하여야 한다.', 1201);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2105, '② 치료감호시설의 장은 제1항에 따라 치료명령을 받은 사람을 이송 받은 경우에는 지체 없이 그 사실을 그 사람의 주거지를 관할하는 보호관찰소의 장에게 통보하여야 한다.', 1201);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2106, '③ 치료감호시설의 장은 치료명령을 받은 사람이 형 또는 치료감호의 집행이 종료되거나 면제ㆍ가석방, 가종료 등의 사유로 석방되기 5일 전까지 석방 예정 사실을 그 사람의 주거지를 관할하는 보호관찰소의 장에게 통보하여야 한다.', 1201);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2107, '① 보호관찰관은 약물 투여의 방법으로 치료명령을 집행하는 경우에는 치료기관의 의사로 하여금 부작용에 대한 검사 및 치료도 함께 실시하게 하여야 한다. 이 경우 치료기관에서 부작용에 대한 검사 및 치료를 실시하기 어려운 때에는 치료기관의 장으로 하여금 「의료법」에 따른 의료기관(이하 "의료기관"이라 한다)과 연계하여 부작용에 대한 검사 및 치료를 실시하게 할 수 있다.', 1202);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2108, '② 보호관찰관은 제1항에 따른 검사 결과 치료명령을 받은 사람의 신체에 회복하기 어려운 손상이 발생할 수 있다는 의사의 소견이 있거나 그 밖에 약물 투여에 따른 부작용이 크다고 인정되는 경우에는 약물 투여를 일시 중단할 수 있다.', 1202);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2109, '③ 제2항에 따라 약물 투여를 일시 중단한 경우 보호관찰관이 소속된 보호관찰소의 장은 즉시 「보호관찰 등에 관한 법률」 제5조에 따른 보호관찰 심사위원회(이하 "심사위원회"라 한다)에 약물 투여 일시 중단의 승인을 서면으로 신청하여야 한다.', 1202);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2110, '④ 심사위원회는 제3항의 신청을 받은 때에는 지체 없이 약물 투여 일시 중단의 승인 여부를 결정하여야 한다. 이 경우 심사위원회는 의료기관에 치료명령을 받은 사람에 대한 약물치료 부작용 관련 진단을 의뢰할 수 있다.', 1202);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2111, '⑤ 보호관찰관은 제4항에 따른 약물 투여 일시 중단의 승인일부터 1개월마다 치료명령을 받은 사람의 부작용 치료 내용, 신체상태의 변화 및 약물 투여 적합 여부 등에 대한 의사의 진단과 처방 결과를 심사위원회에 보고하여야 한다.', 1202);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2112, '⑥ 심사위원회는 제5항에 따른 보호관찰관의 보고에 따라 약물 투여 재개 여부를 심사ㆍ결정하여야 한다.', 1202);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2113, '⑦ 심사위원회가 제3항에 따른 신청을 기각하거나 제6항에 따라 약물 투여 재개를 결정하였을 때에는 보호관찰관은 지체 없이 치료명령을 다시 집행하여야 한다.', 1202);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2114, '① 법 제14조제4항에 따라 집행이 정지된 치료명령의 잔여기간은 다음 각 호의 구분에 따라 집행한다.', 1203);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2115, '② 제1항제2호의 경우에 치료명령을 받은 사람은 석방된 날부터 10일 이내에 주거지를 관할하는 보호관찰소에 출석하여 신고하고, 보호관찰관의 치료명령 집행 지시에 따라야 한다.', 1203);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2116, '③ 제1항에 따른 치료명령의 집행기간은 다시 치료 약물을 투여한 날부터 진행한다.', 1203);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2117, '④ 수용시설 또는 치료감호시설의 장은 법 제14조제5항에 따른 치료명령의 잔여기간 집행 사유가 발생하였을 때에는 치료명령의 집행이 정지된 사람이 석방되기 5일 전까지 석방 예정 사실을 그 사람의 주거지를 관할하는 보호관찰소의 장에게 통보하여야 한다.', 1203);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2118, '① 보호관찰관은 치료명령을 받은 사람이 법 제15조제1항에 따른 의무를 준수하는지 확인할 필요가 있으면 호르몬 수치 검사 또는 상쇄약물 투약 여부 검사를 실시할 수 있다.', 1204);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2119, '② 치료명령을 받은 사람은 보호관찰관이 제1항에 따른 검사를 위하여 소변 등 시료(試料)의 제출을 지시할 때에는 이에 따라야 한다.', 1204);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2120, '③ 보호관찰소의 장은 치료명령을 받은 사람이 제출한 소변 등의 시료를 대검찰청 또는 국립과학수사연구원에 송부하여 제1항에 따른 검사를 의뢰하여야 한다. <개정 2015.12.30>', 1204);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2121, '① 보호관찰관은 법 제15조제3항에 따라 주거 이전 등의 허가 신청을 받은 때에는 그 신청을 받은 날부터 7일 이내에 다음 각 호의 사항을 종합적으로 고려하여 허가 여부를 결정하여야 한다.', 1205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2122, '② 법 제15조제3항에 따라 치료명령을 받은 사람이 주거 이전 허가를 받아 다른 보호관찰소의 관할구역으로 주거를 이전한 경우에는 3일 이내에 새로운 주거지를 관할하는 보호관찰소에 출석하여 주거이전의 신고를 하여야 한다.', 1205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2123, '③ 보호관찰소의 장은 소속 보호관찰관이 제1항에 따라 치료명령을 받은 사람의 출국을 허가한 경우에는 출입국 사무를 관장하는 기관의 장에게 치료명령을 받은 사람의 출입국 사실을 통보하여 줄 것을 요청할 수 있다.', 1205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2124, '① 보호관찰소의 장은 법 제16조제1항 또는 제2항에 따라 치료기간의 연장 또는 준수사항의 추가ㆍ변경을 신청하는 경우에는 다음 각 호의 사항을 적은 서면으로 하여야 한다.', 1206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2125, '② 보호관찰소의 장은 제1항에 따른 신청을 할 때에는 신청 사유를 소명할 수 있는 자료를 함께 제출하여야 한다.', 1206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2126, '③ 법원은 법 제16조에 따른 청구의 심리를 위하여 필요하면 담당 보호관찰관을 출석시켜 의견을 들을 수 있고, 치료명령을 받은 사람을 소환하여 심문하거나 필요한 사항을 확인할 수 있다.', 1206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2127, '① 법 제17조제1항에 따른 치료명령의 가해제 신청은 심사위원회에 서면으로 하여야 한다.', 1207);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2128, '② 심사위원회는 치료명령을 받은 사람 또는 그 법정대리인이 치료명령의 가해제를 신청한 경우에는 지체 없이 그 사실을 보호관찰소의 장에게 통보하여야 한다.', 1207);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2129, '① 심사위원회는 법 제18조제1항에 따라 치료명령의 가해제를 심사할 때에는 치료를 실시한 정신건강의학과 전문의와 보호관찰관의 의견을 들어야 하며, 필요하면 그 밖의 전문가의 의견을 들을 수 있다. <개정 2011.11.23>', 1208);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2130, '② 심사위원회는 법 제18조제4항 및 제5항에 따른 결정을 한 때에는 지체 없이 그 결정서 등본을 관할 보호관찰소의 장과 신청인에게 송달하여야 한다.', 1208);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2131, '③ 제1항에 따라 심사위원회에 의견 또는 자료를 제출한 정신건강의학과 전문의, 그 밖의 전문가 등에게는 예산의 범위에서 수당 또는 비용을 지급할 수 있다. <개정 2011.11.23>', 1208);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2132, '① 법 제19조제1항에 따른 가해제 취소 신청은 심사위원회에 서면으로 하여야 한다.', 1209);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2133, '② 심사위원회는 법 제19조제1항에 따라 치료명령의 가해제 취소 결정을 한 때에는 지체 없이 그 사실을 관할 보호관찰소의 장과 가해제가 취소된 사람에게 통보하여야 한다.', 1209);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2134, '③ 가해제가 취소된 경우에 치료명령의 집행기간은 가해제 취소 후 최초로 성호르몬 조절약물을 투여한 날부터 진행한다.', 1209);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2135, null, 1211);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2136, '① 검사는 법 제22조제2항제5호에 따라 약물치료 동의 여부를 확인할 때에는 약물치료에 관한 사항을 서면으로 제시하여 설명하고, 약물치료에 동의한 경우에는 이를 서면으로 확인하여야 한다.', 1213);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2137, '② 법 제22조제2항제5호에 따른 정신건강의학과 전문의의 진단이나 감정 및 치료명령의 청구에 관하여는 제2조 및 제4조를 각각 준용한다. <개정 2011.11.23>', 1213);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2138, '① 검사는 법 제22조제2항제6호에 따라 치료명령이 결정된 경우에는 지체 없이 그 사실을 성폭력수형자를 수용하고 있는 수용시설의 장에게 통보하여야 한다.', 1215);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2139, '② 법 제22조제2항제6호에 따라 치료명령이 결정된 경우에 검사의 집행지휘에 관하여는 제6조를 준용한다.', 1215);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2140, '① 보호관찰관은 법 제22조제2항제6호에 따라 치료명령의 결정을 받은 사람에게 치료행위마다 금액을 특정하여 서면으로 치료비용의 납부를 명하여야 한다.', 1217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2141, '② 치료명령을 받은 사람은 제1항의 서면을 받은 날부터 30일 이내에 치료비용을 내야 한다.', 1217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2142, '③ 치료명령을 받은 사람이 치료비용을 부담할 경제력이 없는 경우에는 제1항에 따라 치료비용 납부를 명하는 서면을 받을 때마다 다음 각 호의 서류를 보호관찰관에게 제출하여 치료비용 국가 부담 결정을 받아야 한다.', 1217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2143, '④ 제3항에 따른 신청을 받은 보호관찰관은 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 다음 각 호의 행정정보를 확인하여야 한다. 다만, 신청인이 확인에 동의하지 아니하는 경우에는 그 서류를 첨부하게 하여야 한다.', 1217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2144, '⑤ 보호관찰관은 제3항에 따른 결정을 위하여 필요한 경우에는 치료명령을 받은 사람에게 출석 또는 자료의 제출을 요구하거나, 치료명령을 받은 사람의 동의를 받아 공공기관ㆍ민간단체 등에 치료비용 부담 능력 확인에 필요한 자료의 제출을 요구할 수 있다.', 1217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2145, '⑥ 보호관찰관은 제5항에 따라 공공기관ㆍ민간단체 등에 치료비용 부담 능력 확인에 필요한 자료의 제출을 요구할 때에는 다음 각 호의 사항이 적힌 치료명령을 받은 사람의 동의서를 첨부하여야 한다.', 1217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2146, '⑦ 보호관찰관은 제3항에 따라 국가 부담 결정을 하였을 때에는 치료기관에 대하여 치료행위마다 예산의 범위에서 비용의 전부를 지급하여야 한다.', 1217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2147, '① 「치료감호 등에 관한 법률」 제37조에 따른 치료감호심의위원회(이하 "치료감호심의위원회"라 한다)는 법 제25조제1항에 따른 가종료자 등(이하 "가종료자등"이라 한다)에 대하여 치료명령을 부과할 필요가 있다고 인정되는 경우에는 치료감호시설의 정신건강의학과 전문의에게 진단 및 감정을 의뢰하여야 한다. <개정 2011.11.23, 2016.11.29>', 1218);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2148, '② 치료감호심의위원회는 제1항에 따른 치료감호시설의 정신건강의학과 전문의의 진단 및 감정만으로 성도착증 여부를 판단하기 어려울 때에는 다른 정신건강의학과 전문의에게 다시 진단 및 감정을 의뢰할 수 있다. <개정 2011.11.23>', 1218);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2149, '③ 치료감호심의위원회가 피보호감호자에 대하여 제1항에 따른 진단 및 감정을 의뢰한 경우 보호감호시설의 장은 「형의 집행 및 수용자의 처우에 관한 법률」 제37조제2항에 따라 피보호감호자를 치료감호시설로 이송하여야 한다.', 1218);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2150, '① 치료감호심의위원회는 법 제25조제1항에 따라 치료명령을 부과한 경우 가종료자등에게는 그 결정서를, 치료감호시설 또는 보호감호시설(이하 "감호시설"이라 한다)의 장에게는 결정서 등본을 각각 송달하여야 한다.', 1219);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2151, '② 제1항에 따라 결정서 등본을 송달받은 감호시설의 장은 치료명령을 받게 될 피치료감호자 또는 피보호감호자에게 약물치료의 내용ㆍ방법ㆍ절차ㆍ효과ㆍ부작용 등에 관하여 알려 주어야 한다.', 1219);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2152, '① 법 제4장(제22조부터 제29조까지)에 따른 치료명령에 관하여는 제7조부터 제14조까지 및 제16조부터 제18조까지의 규정을 준용한다.', 1220);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2153, '② 법 제22조에 따른 치료명령에 관하여는 제1항에서 준용하는 규정 외에 제4조, 제6조 및 제15조를 준용한다.', 1220);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2154, '① 검사는 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보, 같은 영 제19조제1호 또는 제4호에 따른 주민등록번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 1221);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2155, '② 교도소, 소년교도소, 구치소 또는 치료감호시설의 장은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다.', 1221);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2156, '③ 심사위원회는 법 제18조제4항ㆍ제5항 또는 제19조제1항에 따른 치료명령 가해제 또는 가해제 취소 결정에 관한 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다.', 1221);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2157, '④ 치료감호심의위원회는 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <개정 2017.12.29>', 1221);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2158, '⑤ 보호관찰소의 장 또는 보호관찰관은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <개정 2017.12.29>', 1221);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2159, '① 위원회는 위원장 1인을 포함한 13인의 비상근 위원으로 구성한다.', 1223);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2160, '② 위원장은 15년 이상 다음 각 호의 직에 있던 사람 중에서 대법원장이 임명 또는 위촉한다.', 1223);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2161, '③ 위원회의 위원은 다음 각 호의 사람을 대법원장이 임명 또는 위촉한다.', 1223);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2162, '④ 위원장은 위원 중 1인을 주무위원으로 지명한다.', 1223);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2163, '⑤ 위원장과 위원의 임기는 1년으로 하고, 연임할 수 있다.', 1223);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2164, '⑥ 위원이 부득이한 사유로 직무를 수행할 수 없다고 인정되는 때 또는 위원이 직무상 의무를 위반하는 등 위원으로서의 자격유지가 부적합하다고 인정되는 때에는 대법원장은 그 위원을 해임 또는 해촉할 수 있으며, 법관ㆍ검사의 직에 있는 사람으로서 위원으로 임명된 사람이 그 직을 퇴직하는 경우에는 해임된 것으로 본다.', 1223);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2165, '① 위원장은 위원회를 대표하고 위원회의 회의를 주재하며 사무를 통할한다.', 1224);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2166, '② 위원장은 주무위원에게 그 직무를 위임할 수 있다.', 1224);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2167, '① 위원회에는 위원장이 지명한 간사 1인과 서기 1인을 둔다.', 1225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2168, '② 간사는 위원장의 명을 받아 위원회의 사무를 처리한다.', 1225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2169, '③ 서기는 위원장의 명을 받아 회의의 준비, 회의록의 작성, 그 밖에 필요한 사무를 처리한다.', 1225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2170, '① 위원장은 필요한 때에 위원회의 회의를 소집할 수 있다.', 1226);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2171, '② 위원회의 회의는 재적위원 과반수의 찬성으로 의결한다.', 1226);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2172, '③ 위원회의 회의는 공개하지 아니함을 원칙으로 한다. 다만, 위원회는 의결을 통하여 회의자료 또는 회의 내용의 전부 또는 일부를 공개할 수 있다.', 1226);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2173, '① 위원회에서 심의할 사항에 관한 전문적인 조사ㆍ연구 등을 위하여 위원회에 15인 이내의 비상근 전문위원을 둘 수 있다.', 1227);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2174, '② 전문위원은 국민참여재판에 관한 전문적인 식견을 갖춘 법관, 검사, 변호사, 교수 또는 기타 전문가 중에서 위원장이 위촉한다.', 1227);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2175, '③ 전문위원은 다음 각 호의 업무를 담당한다.', 1227);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2176, '④ 위원회는 필요한 경우 전문위원을 회의에 출석시켜 의견을 듣거나 설명하게 할 수 있다.', 1227);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2177, '① 위원회는 국민의 형사재판 참여에 관한 조사ㆍ연구를 위하여 필요한 경우 관계 전문가 또는 관계 기관ㆍ단체 등에게 조사ㆍ연구를 의뢰할 수 있다.', 1228);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2178, '② 위원회는 필요한 경우 관계 공무원 또는 전문가를 회의에 출석하게 하여 의견을 청취할 수 있고, 관계 국가기관ㆍ연구기관ㆍ단체 또는 전문가 등에 대하여 의견 조회, 자료 제출 및 그 밖의 협력을 요청할 수 있다.', 1228);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2179, null, 1233);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2180, '① 증인ㆍ감정인ㆍ통역인 또는 번역인의 일당은 출석 또는 조사와 이를 위한 여행(이하 "출석등"이라 한다)에 필요한 일수(日數)에 따라 지급한다.', 1234);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2181, '② 일당의 금액은 대법원규칙으로 정하는 범위에서 법원이 정한다.', 1234);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2182, '① 증인ㆍ감정인ㆍ통역인 또는 번역인의 여비는 운임과 그 밖에 이에 준하는 비용으로 하고, 운임은 철도운임ㆍ선박운임ㆍ자동차운임 및 항공운임 네 종류로 구분하되, 법원이 적절하다고 인정하는 교통수단을 기준으로 하여 지급한다.', 1235);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2183, '② 여비의 항목과 그 금액은 대법원규칙으로 정하는 범위에서 법원이 정한다.', 1235);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2184, '① 증인ㆍ감정인ㆍ통역인 또는 번역인의 숙박료는 출석등에 필요한 밤[야]의 수에 따라 지급한다.', 1236);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2185, '② 숙박료의 금액은 대법원규칙으로 정하는 범위에서 법원이 정한다.', 1236);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2186, '① 국선변호인에게 지급할 일당, 여비 및 숙박료의 금액은 제3조부터 제6조까지에 규정된 기준에 준하여 대법원규칙으로 정하는 범위에서 법원이 정한다.', 1239);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2187, '② 국선변호인에게 지급할 보수의 기준 및 금액은 대법원규칙으로 정하는 범위에서 법원이 정한다.', 1239);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2188, null, 1242);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2189, '① 수명법관(受命法官) 또는 수탁판사(受託判事)가 증인신문(證人訊問)이나 그 밖의 절차를 이행한 경우에는 이 법에 따라 법원이 정할 사항은 해당 법관이 정한다. 다만, 해당 법관이 정하는 것이 적절하지 아니하다고 인정하는 경우에는 그러하지 아니하다.', 1243);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2190, '② 수명법관 또는 수탁판사 외의 법관이 절차를 이행한 경우에는 제1항 본문을 준용한다.', 1243);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2191, null, 1248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2192, null, 1249);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2193, '①법 제3조제1항제1호의 규정에 의한 "인체에 현저한 유해"의 기준은 대한약전 또는 보건복지부장관이 지정하는 공정서에 극량이 표시된 의약품으로서 그 함량이 극량을 초과한 경우를 말한다. <개정 1994.12.23, 2008.2.29, 2010.3.15>', 1250);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2194, '②법 제3조제1항 및 제7조제1항의 규정에 의한 "효능 또는 함량의 현저한 부족"의 기준은 의약품 또는 화장품의 주된 성분의 총함량이 제조당시를 기준으로 하여 최소유효량에 미달하는 경우를 말한다.', 1250);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2195, '①법 제9조제1항의 규정에 의한 상금의 지급액은 당해 사건으로 부과된 벌금액의 100분의 20상당액으로 하되, 상금의 총액은 50만원을 초과할 수 없다.', 1251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2196, '②당해 사건이 검사의 기소유예처분을 받은 경우에는 전항의 규정에 불구하고 3만원이하의 범위안에서 그 공로, 범죄의 경중 기타의 사정을 참작하여 보건복지부장관이 정하는 금액으로 한다. <개정 1994.12.23, 2008.2.29, 2010.3.15>', 1251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2197, '① 기획단은 단장 1인을 포함한 11인의 비상근 위원으로 구성한다.', 1254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2198, '② 단장은 15년 이상 다음 각 호의 직에 있던 자 중에서 법원행정처장이 임명 또는 위촉한다.', 1254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2199, '③ 단장은 위원 중 1인을 주무위원으로 지명한다.', 1254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2200, '④ 기획단의 위원은 다음 각 호의 자를 법원행정처장이 임명 또는 위촉한다.', 1254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2201, '⑤ 위원의 임기는 1년으로 하고, 연임할 수 있다.', 1254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2202, '⑥ 기획단에는 단장이 지명한 간사 1인과 서기 1인을 둔다.', 1254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2203, '① 단장은 기획단을 대표하고, 기획단의 직무를 통할한다.', 1255);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2204, '② 단장이 부득이한 사유로 그 직무를 수행할 수 없는 경우에는 주무위원이 그 직무를 대행한다.', 1255);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2205, '① 단장은 필요한 때에 기획단의 회의를 소집할 수 있다.', 1256);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2206, '② 기획단의 회의는 재적위원 과반수의 출석으로 개회한다.', 1256);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2207, '③ 기획단의 회의는 공개하지 아니한다.', 1256);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2208, '① 기획단은 국민의 형사재판 참여에 관한 조사ㆍ연구를 위하여 필요한 경우 관계 전문가 또는 관계 기관ㆍ단체 등에게 조사ㆍ연구를 의뢰할 수 있다.', 1257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2209, '② 기획단은 필요한 경우 관계 공무원 또는 전문가를 회의에 출석하게 하여 의견을 청취할 수 있고, 관계 국가기관ㆍ연구기관ㆍ단체 또는 전문가 등에 대하여 의견 조회, 자료 제출 및 그 밖의 협력을 요청할 수 있다.', 1257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2210, '①검사는 법 제16조제 1항의 규정에 의하여 공소보류의 결정(이하 "보류결정"이라 한다)을 한 때에는 보류자에 대하여 이 영을 준수할 것을 고지하고 엄중히 훈계하여야 한다.', 1261);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2211, '②전항의 규정에 의한 훈계를 받은 보류자는 훈계를 받은 때로부터 24시간 이내에 별지 제1호서식에 의한 서약서를 공소보류의 결정을한 검사(이하 "검사"라 한다)에게 제출하여야 한다.', 1261);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2212, '①전조의 규정에 의한 통지를 받은 경찰서장은 보류자의 동태 감시, 파악하여야 하며 출석 기타 감시상 필요한 조치를 할 수 있다.', 1263);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2213, '②경찰서장은 보류자에 대한 관찰부를 별지 제3호서식에 의하여 작성ㆍ비치하고 매월 1회이상 보류자의 동태를 기재하여야 한다.', 1263);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2214, '①보류자는 제2조제2항의 규정에 의하여 서약서를 제출한 날로부터 7일이내에, 앞으로의 생업ㆍ가족관계ㆍ재산 및 생활관계 기타 필요한 사항에 관한 신고서를 경찰서장을 거쳐 검사에게 제출하여야 한다. 신고한 사항에 변동이 생긴 경우에는 또한 같다.', 1265);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2215, '②전항의 신고서는 별지 제4호서식에 의하여 작성하여야 하며 2인이상의 신원보증인이 연서ㆍ날인하여야 한다.', 1265);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2216, null, 1266);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2217, '①검사ㆍ경찰서장 및 수사기관의 장은 보류자에 대하여 생계 및 취업 기타 필요하다고 인정되는 사항에 관한 보도를 할 수 있다.', 1269);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2218, '②경찰서장 또는 수사기관의 장이 전항의 규정에 의한 보도를 하고자 할 때에는 미리 검사의 지시를 받아야 한다.', 1269);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2219, null, 1271);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2220, '①검사가 보류결정을 취소함에 있어서는, 취소사유를 충분히 검토하여야 한다.', 1272);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2221, '②검사가 보류결정을 취소한 때에는 지체없이 이를 경찰서장과 수사기관의 장에게 통지하여야 한다.', 1272);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2222, null, 1275);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2223, null, 1276);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2224, '① 법 제4조제1항제4호에서 "안전ㆍ보건 관계 법령"이란 해당 사업 또는 사업장에 적용되는 것으로서 종사자의 안전ㆍ보건을 확보하는 데 관련되는 법령을 말한다.', 1277);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2225, '② 법 제4조제1항제4호에 따른 조치에 관한 구체적인 사항은 다음 각 호와 같다.', 1277);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2226, '① 법 제8조제1항에 따른 안전보건교육(이하 "안전보건교육"이라 한다)은 총 20시간의 범위에서 고용노동부장관이 정하는 바에 따라 이수해야 한다.', 1278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2227, '② 안전보건교육에는 다음 각 호의 사항이 포함되어야 한다.', 1278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2228, '③ 고용노동부장관은 「한국산업안전보건공단법」에 따른 한국산업안전보건공단이나 「산업안전보건법」 제33조에 따라 등록된 안전보건교육기관(이하 "안전보건교육기관등"이라 한다)에 안전보건교육을 의뢰하여 실시할 수 있다.', 1278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2229, '④ 고용노동부장관은 분기별로 중대산업재해가 발생한 법인 또는 기관을 대상으로 안전보건교육을 이수해야 할 교육대상자를 확정하고 안전보건교육 실시일 30일 전까지 다음 각 호의 사항을 해당 교육대상자에게 통보해야 한다.', 1278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2230, '⑤ 제4항에 따른 통보를 받은 교육대상자는 해당 교육일정에 참여할 수 없는 정당한 사유가 있는 경우에는 안전보건교육 실시일 7일 전까지 고용노동부장관에게 안전보건교육의 연기를 한 번만 요청할 수 있다.', 1278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2231, '⑥ 고용노동부장관은 제5항에 따른 연기 요청을 받은 날부터 3일 이내에 연기 가능 여부를 교육대상자에게 통보해야 한다.', 1278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2232, '⑦ 안전보건교육을 연기하는 경우 교육일정 등의 통보에 관하여는 제4항을 준용한다.', 1278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2233, '⑧ 안전보건교육에 드는 비용은 안전보건교육기관등에서 수강하는 교육대상자가 부담한다.', 1278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2234, '⑨ 안전보건교육기관등은 안전보건교육을 실시한 경우에는 지체 없이 안전보건교육 이수자 명단을 고용노동부장관에게 통보해야 한다.', 1278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2235, '⑩ 안전보건교육을 이수한 교육대상자는 필요한 경우 안전보건교육이수확인서를 발급해 줄 것을 고용노동부장관에게 요청할 수 있다.', 1278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2236, '⑪ 제10항에 따른 요청을 받은 고용노동부장관은 고용노동부장관이 정하는 바에 따라 안전보건교육이수확인서를 지체 없이 내주어야 한다.', 1278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2237, null, 1280);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2238, '① 법 제9조제1항제4호에서 "안전ㆍ보건 관계 법령"이란 해당 사업 또는 사업장에서 생산ㆍ제조ㆍ판매ㆍ유통 중인 원료나 제조물에 적용되는 것으로서 그 원료나 제조물이 사람의 생명ㆍ신체에 미칠 수 있는 유해ㆍ위험 요인을 예방하고 안전하게 관리하는 데 관련되는 법령을 말한다.', 1281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2239, '② 법 제9조제1항제4호에 따른 조치의 구체적인 사항은 다음 각 호와 같다.', 1281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2240, null, 1282);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2241, '① 법 제9조제2항제4호에서 "안전ㆍ보건 관계 법령"이란 해당 공중이용시설ㆍ공중교통수단에 적용되는 것으로서 이용자나 그 밖의 사람의 안전ㆍ보건을 확보하는 데 관련되는 법령을 말한다.', 1283);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2242, '② 법 제9조제2항제4호에 따른 조치의 구체적인 사항은 다음 각 호와 같다.', 1283);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2243, '① 법 제13조제1항에 따른 공표(이하 이 조에서 "공표"라 한다)는 법 제4조에 따른 의무를 위반하여 발생한 중대산업재해로 법 제12조에 따라 범죄의 형이 확정되어 통보된 사업장을 대상으로 한다.', 1284);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2244, '② 공표 내용은 다음 각 호의 사항으로 한다.', 1284);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2245, '③ 고용노동부장관은 공표하기 전에 해당 사업장의 사업주 또는 경영책임자등에게 공표하려는 내용을 통지하고 30일 이상의 기간을 정하여 그에 대해 소명자료를 제출하게 하거나 의견을 진술할 수 있는 기회를 주어야 한다.', 1284);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2246, '④ 공표는 관보, 고용노동부나 「한국산업안전보건공단법」에 따른 한국산업안전보건공단의 홈페이지에 게시하는 방법으로 한다.', 1284);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2247, '⑤ 제4항에 따라 홈페이지에 게시하는 방법으로 공표하는 경우 공표기간은 1년으로 한다.', 1284);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2248, '①「민영교도소 등의 설치ㆍ운영에 관한 법률」(이하 "법"이라 한다) 제4조제1항에 따른 위탁계약은 법무부장관과 법 제3조제2항에 따라 선정된 수탁자가 법 제5조제1항 각 호의 사항에 관하여 약정하고 해당 계약서에 각각 서명날인함으로써 성립한다.', 1289);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2249, '② 법무부장관은 위탁계약을 체결할 때 계약사항의 누락을 방지하고, 계약내용의 일관성을 유지하며, 계약체결의 효율성과 공정성을 높이기 위하여 교정업무의 민간위탁에 관한 표준계약서를 정할 수 있다.', 1289);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2250, null, 1290);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2251, '① 교정법인의 임원의 임기는 해당 법인의 정관에서 정하는 바에 따르고, 정관에서 특별히 정하지 않은 경우에는 3년으로 하며, 연임할 수 있다.', 1291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2252, '② 교정법인은 해당 법인의 이사(위탁업무를 전담하는 이사만 해당한다. 이하 이 조에서 같다) 또는 감사 중에 결원이 생겼을 때에는 그 사유가 발생한 날부터 2개월 이내에 보충하여야 한다.', 1291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2253, '③ 법무부장관은 교정법인이 제2항에 따라 이사의 결원을 보충하지 않아 해당 교정법인의 목적을 달성할 수 없거나 손해가 생길 우려가 있다고 인정되면 이해관계인의 청구나 직권에 의하여 임시이사를 선임(選任)할 수 있다.', 1291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2254, '① 교정법인의 대표자(이하 "대표자"라 한다)는 교정법인을 대표하며, 법인의 업무를 총괄한다.', 1292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2255, '② 대표자가 공석이 되거나 부득이한 사유로 직무를 수행할 수 없을 때에는 정관에서 미리 정한 사람이 그 직무를 대행하되, 정관에서 특별히 정하지 않은 경우에는 이사 중에서 호선(互選)한 사람이 그 직무를 대행한다.', 1292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2256, '③ 이사는 이사회에 출석하여 교정법인의 업무에 관한 사항을 심의ㆍ의결하며, 이사회나 대표자로부터 위임받은 사항을 처리한다.', 1292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2257, '④ 감사는 다음 각 호의 직무를 수행한다.', 1292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2258, '① 대표자는 이사회를 소집하고, 그 의장이 된다.', 1293);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2259, '② 이사회는 다음 각 호의 사항을 심의ㆍ의결한다.', 1293);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2260, '① 교정법인의 재산 중 다음 각 호의 어느 하나에 해당하는 재산은 법 제14조제1항에 따른 기본재산으로 한다.', 1294);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2261, '② 교정법인의 재산 중 제1항 각 호 외의 재산은 보통재산으로 한다.', 1294);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2262, '③ 제1항에 따른 기본재산은 교도소ㆍ소년교도소 또는 구치소 및 그 지소(이하 "교도소등"이라 한다)의 부지매입, 설계 및 건축에 필요한 재원(교정법인이 교도소등의 설치비용을 부담하는 경우만 해당한다)과 직원교육, 손해배상 등 교도소등의 운영에 드는 경비를 충당할 수 있어야 한다.', 1294);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2263, null, 1295);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2264, null, 1296);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2265, '① 법 제15조제2항에 따른 민영교도소등의 설치ㆍ운영에 관한 회계 중 일반회계의 세입은 다음 각 호의 수입으로 한다.', 1297);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2266, '② 일반회계의 세출은 다음 각 호의 경비로 한다.', 1297);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2267, '③ 법 제15조제2항에 따른 민영교도소등의 설치ㆍ운영에 관한 회계 중 교도작업회계의 세입은 다음 각 호의 수입으로 한다.', 1297);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2268, '④ 교도작업회계의 세출은 교도작업을 위하여 필요한 모든 경비로 한다.', 1297);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2269, '① 교정법인은 법 제16조제2항에 따라 법무부장관에게 법 제15조제2항에 따른 민영교도소등의 설치ㆍ운영에 관한 회계의 사업계획과 예산을 매 회계연도가 시작되기 8개월 이전에 제출하고, 사업실적과 결산을 매 회계연도가 끝난 후 2개월 이내에 제출하여야 한다.', 1298);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2270, '② 교정법인은 연도 중에 해당 예산을 추가하거나 경정(更正)할 때에는 추가하거나 경정한 날부터 15일 이내에 해당 예산을 법무부장관에게 제출하여야 한다.', 1298);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2271, '③ 법 제16조제3항에 따른 공인회계사 등의 감사증명서를 제출하여야 할 교정법인의 범위는 다음 각 호와 같다.', 1298);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2272, '① 교정법인이 설치ㆍ운영하는 교도소등은 위탁수용 대상자의 특성을 고려하여 위탁계약에서 달리 정한 경우를 제외하고는 다음 각 호의 시설을 갖추어야 한다. <개정 2021.1.5>', 1299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2273, '② 교정법인은 「형의 집행 및 수용자의 처우에 관한 법률」 제45조에 따른 종교행사를 치르기 위하여 마련된 장소를 제외하고는 그 법인이 운영하는 교도소등의 시설에서 수용자가 항상 출입하거나 접근할 수 있는 장소에 특정종교의 상징물을 설치해서는 아니 된다. 다만, 법무부장관이 국가의 종교적 중립성과 종파간의 형평성을 해치지 아니하는 범위에서 특별히 허가한 경우에는 그러하지 아니하다.', 1299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2274, '① 민영교도소등의 장과 직원은 수용자에게 특정 종교의 교리ㆍ교의에 따른 교육ㆍ교화ㆍ의식과 그 밖에 행사의 참가를 강요해서는 아니 된다.', 1300);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2275, '② 민영교도소등의 장과 직원은 수용자가 특정 종교를 신봉하지 아니한다는 이유로 불리한 처우를 해서는 아니 된다.', 1300);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2276, '① 법 제29조제3항에 따라 민영교도소등의 직원으로 임용되려면 18세 이상이어야 한다. <개정 2025.5.27>', 1302);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2277, '② 교정법인은 민영교도소등의 직원을 임용하였을 때에는 10일 이내에 그 임용사항을 법무부장관에게 보고하여야 한다. 민영교도소등의 직원이 퇴직하였을 때에도 또한 같다.', 1302);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2278, '① 교정법인은 민영교도소등의 직원으로 임용된 사람에 대하여 민영교도소등에 배치하기 전에 자체 교육기관이나 교정공무원 교육기관에서 직무수행에 필요한 교육을 받게 하여야 한다. 다만, 자체 교육기관이나 교정공무원 교육기관의 교육계획상 부득이 하다고 인정되는 경우에는 임용 후 1년 이내에 교육을 받게 할 수 있다.', 1303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2279, '② 교정공무원이나 민영교도소등의 직원으로 근무하다가 퇴직한 사람이 퇴직한 날부터 2년 이내에 민영교도소등의 직원으로 임용된 경우에는 제1항에 따른 교육을 면제할 수 있다. <개정 2016.11.29>', 1303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2280, '③ 제1항의 교육기간, 교육과목, 수업시간과 그 밖에 교육 실시에 필요한 사항은 법무부장관이 정한다.', 1303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2281, '① 교정법인은 민영교도소등의 직원이 신체적ㆍ정신적 이상으로 직무를 감당하지 못하거나 인원의 감축으로 정원(定員)이 초과되었을 때 또는 위탁업무의 정지명령을 받았거나 위탁계약이 해지되었을 때에는 직권으로 면직시킬 수 있다.', 1305);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2282, '② 교정법인이 제1항에 따라 민영교도소등의 직원을 직권으로 면직시켰을 때에는 5일 이내에 그 사실을 법무부장관에게 보고하여야 한다.', 1305);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2283, '① 교정법인은 민영교도소등의 직원이 다음 각 호의 어느 하나에 해당하는 경우에는 그에 대하여 징계처분을 하여야 한다.', 1306);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2284, '② 민영교도소등의 직원에 대한 징계의 종류는 해임ㆍ정직ㆍ감봉ㆍ견책으로 하되, 정직은 1개월 이상 3개월 이하의 기간 동안 직무에 종사하지 못하게 하고 보수의 전액을 감하며, 감봉은 1개월 이상 3개월 이하의 기간 동안 보수의 3분의 1을 줄인다. <개정 2025.5.27>', 1306);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2285, '① 민영교도소등의 장은 매월 법 제34조제1항제1호ㆍ제2호ㆍ제4호 및 제6호부터 제8호까지의 사항을 법무부장관에게 보고하여야 한다.', 1307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2286, '② 민영교도소등의 장은 매 분기 법 제34조제1항제3호ㆍ제5호 및 제9호의 사항을 법무부장관에게 보고하여야 한다.', 1307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2287, null, 1311);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2288, null, 1312);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2289, '① 법무부장관은 진술조력인을 양성하기 위하여 법 제35조제2항 전단에 따른 아동ㆍ장애인의 심리나 의사소통에 관한 전문지식 또는 관련 분야에 종사한 경력이 있는 사람을 대상으로 다음 각 호의 내용이 포함된 교육 과정을 운영하여야 한다. <개정 2023.7.4>', 1313);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2290, '② 제4조제3호에 해당하는 교육 대상자에 대해서는 제1항 각 호의 내용 중 일부를 생략할 수 있다.', 1313);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2291, null, 1314);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2292, '① 법무부장관은 제3조에 따른 교육 과정을 이수한 사람에게 진술조력인 자격을 부여할 수 있다.', 1315);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2293, '② 법무부장관은 제1항에 따라 진술조력인 자격을 부여한 때에는 진술조력인마다 별지 제1호서식의 자격 부여 대장을 작성하여 보관하여야 한다.', 1315);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2294, '① 법무부장관은 진술조력인이 진술조력인 제도의 도입 취지에 부합하게 활동하고 있는지 등을 관리ㆍ감독하기 위하여 수사기관 등 관련 기관이나 조사 현장을 방문하거나, 관련자로부터 의견을 조회하거나, 진술조력인에 대하여 자료 제출을 요구하는 등 필요한 조치를 할 수 있다. 이 경우 진술조력인은 법무부장관의 요구에 지체 없이 따라야 한다.', 1318);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2295, '② 진술조력인은 피해자등에 대한 조력 과정에서 작성하는 보고서 등 진술 조력 업무의 수행과 관련된 기록을 문서화하고 저장ㆍ보존하여야 한다. <개정 2023.7.4>', 1318);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2296, '① 법무부장관은 진술조력인의 업무를 지원하기 위해 진술조력인 자문단을 둘 수 있다.', 1319);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2297, '② 제1항에 따른 진술조력인 자문단은 성별을 고려해 5명 이내의 자문위원으로 구성한다.', 1319);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2298, '③ 제2항에서 규정한 내용 외에 진술조력인 자문단의 구성, 수당 지급 등 자문단의 운영에 필요한 사항은 법무부장관이 정한다.', 1319);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2299, '① 법무부장관은 진술조력인을 대상으로 연 1회 이상 보수교육을 실시하여야 한다.', 1320);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2300, '② 제1항에 따른 보수교육의 내용에 관하여는 제3조를 준용한다.', 1320);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2301, '③ 제1항 및 제2항에서 규정한 사항 외에 보수교육의 시간, 실시 방법 등 진술조력인 보수교육에 필요한 사항은 법무부장관이 정한다.', 1320);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2302, '① 법 제35조의3제1항에 따라 진술조력인 자격이 취소된 사람은 진술조력인 자격 취소의 통지를 받은 날부터 15일 이내에 제7조에 따른 진술조력인 자격증을 법무부장관에게 반납해야 한다. <개정 2024.4.1>', 1321);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2303, '② 법 제35조의3제1항제6호 및 제7호에 따른 진술조력인의 자격취소 사유의 구체적인 내용과 자격취소 절차 등에 관한 세부사항은 법무부장관이 정한다. <신설 2024.4.1>', 1321);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2304, '① 법무부장관은 진술조력인에 대한 지역별 수요를 고려하여 범죄피해자 지원, 성폭력 범죄와 아동학대 범죄의 예방 등을 목적으로 하는 공공기관이나 비영리단체에 상시 근무하는 진술조력인이 배치될 수 있도록 지원할 수 있다.', 1322);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2305, '② 법무부장관은 진술조력인의 균형적인 배치를 위하여 제1항에 따른 공공기관이나 비영리단체와 협의할 수 있다.', 1322);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2306, '③ 법무부장관은 진술조력인의 배치사업을 운영하는 공공기관이나 비영리단체에 필요한 예산을 지원할 수 있다.', 1322);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2307, '① 법 제35조제3항에 따른 진술조력인 명부(이하 "진술조력인명부"라 한다)는 별지 제3호서식에 따른다. 진술조력인명부에는 해당 진술조력인이 원활하게 조력할 수 있는 피해자의 연령, 장애 특성, 범죄 종류 등을 전문분야로 기재할 수 있다.', 1323);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2308, '② 법무부장관은 진술조력인 자격 등이 변경된 경우에는 그 내용을 진술조력인명부에 기재하여야 한다.', 1323);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2309, '③ 법무부장관은 작성한 진술조력인명부를 법원행정처장, 검찰총장, 경찰청장 및 해양경찰청장에게 송부하여야 한다. <개정 2023.7.4>', 1323);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2310, '④ 법무부장관은 직무범위 및 수사관할 등을 고려해 진술조력인명부를 국방부장관, 고위공직자범죄수사처장 또는 「사법경찰관리의 직무를 수행할 자와 그 직무범위에 관한 법률」에 따라 사법경찰관리의 직무를 수행하는 자가 소속된 기관의 장에게 송부할 수 있다. <신설 2023.7.4>', 1323);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2311, '① 검사 또는 사법경찰관은 법 제36조제1항에 따라 진술조력인으로 하여금 조사과정에 참여하여 의사소통을 중개하거나 보조하게 하려면 조사 전에 진술조력인을 선정하여야 한다.', 1324);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2312, '② 검사 또는 사법경찰관은 제1항에 따라 진술조력인을 선정한 경우에는 별지 제4호서식의 선정서를 작성하여 진술조력인에게 교부하고 그 사본을 수사기록에 편철하여야 한다.', 1324);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2313, '③ 피해자등, 그 법정대리인[법정대리인이 법 제2조에 따른 성폭력범죄를 저지른 사람, 「아동학대범죄의 처벌 등에 관한 특례법」 제2조제5호의 아동학대행위자 또는 「장애인복지법」 제2조제3항에 따른 장애인학대를 한 사람(이하 "장애인학대행위자"라 한다) 등인 경우를 제외하며, 이하 같다], 「장애인복지법」 제59조의8에 따른 보조인(보조인이 장애인학대행위자인 경우를 제외하며, 이하 "보조인"이라 한다) 또는 변호사가 법 제36조제1항에 따라 진술조력인 선정 신청을 할 때에는 말로 하거나 별지 제5호서식의 진술조력인 선정 신청서를 제출하여야 한다. <개정 2023.7.4>', 1324);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2314, '④ 검사 또는 사법경찰관은 법 제36조제2항 또는 「장애인복지법」 제59조의16제2항에 따라 피해자등, 그 법정대리인, 보조인 또는 변호사에게 진술조력인에 의한 의사소통의 중개나 보조를 신청할 수 있음을 고지할 때에는 말로 하거나 별지 제6호서식의 고지서로 한다. 이 경우 검사 또는 사법경찰관은 별지 제7호서식의 확인서를 받아 기록에 편철하여야 한다. <개정 2023.7.4>', 1324);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2315, '⑤ 법 제36조제5항에 따른 검증에 관하여는 제1항부터 제4항까지의 규정을 준용한다. 이 경우 "조사"는 "검증"으로 본다.', 1324);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2316, null, 1325);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2317, '① 검사 또는 사법경찰관은 다음 각 호의 어느 하나에 해당하는 경우에는 해당 사건의 진술조력인 선정을 취소할 수 있다. 다만, 제1호 또는 제2호에 해당하는 경우에는 선정을 취소하여야 한다. <개정 2021.1.20, 2023.7.4>', 1326);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2318, '② 검사 또는 사법경찰관은 진술조력인 선정을 취소한 경우에 그 사실을 지체 없이 피해자등, 그 법정대리인, 보조인 또는 변호사와 진술조력인에게 통지하여야 한다. <개정 2023.7.4>', 1326);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2319, '③ 제2항의 통지는 서면 외에 구술, 전화, 팩스, 전자우편, 휴대전화 문자전송이나 그 밖에 적당한 방법으로 할 수 있다.', 1326);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2320, null, 1328);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2321, '① 진술조력인은 법 제36조제1항에 따라 의사소통을 중개하거나 보조하기 위해 다음 각 호의 어느 하나에 해당하는 업무를 수행한다. <개정 2023.7.4>', 1329);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2322, '② 진술조력인은 피해자등의 진술에 개입해서는 아니 되며, 검사 또는 사법경찰관이 직접 피해자등의 진술을 청취한 이후에만 피해자등의 진술을 그의 의사표현적 특징 등에 비추어 설명할 수 있다. 다만, 이 경우에도 피해자등의 진술 내용을 변경해서는 아니 된다. <개정 2023.7.4>', 1329);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2323, '① 검사 또는 사법경찰관은 법 제36조제1항에 따라 조사과정에 진술조력인을 참여하게 하여 진술조서를 작성하는 경우에는 그 진술조서에 진술조력인을 통하여 피해자등과의 의사소통을 중개 또는 보조하도록 하였다는 취지를 적고, 진술조력인의 기명날인 또는 서명을 받아야 한다. <개정 2023.7.4>', 1330);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2324, '② 검사 또는 사법경찰관은 법 제36조제1항에 따라 조사과정에 진술조력인을 참여하게 하여 영상녹화를 실시한 경우에는 제작된 영상녹화물(CD, DVD 등을 말한다)에 조사자 및 피조사자의 기명날인 또는 서명과 함께 진술조력인의 기명날인 또는 서명을 받아야 한다.', 1330);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2325, '① 진술조력인이 법 제36조제3항에 따라 조사 전에 피해자등을 면담하려는 경우에는 수사기관은 진술조력인 조력 필요성에 관하여 평가할 수 있는 충분한 시간을 제공하여야 한다. <개정 2023.7.4>', 1331);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2326, '② 진술조력인은 법 제36조제3항에 따라 조사 전에 피해자등과 면담하는 경우 피해사실이나 해당 사건 내용 등에 관한 면담을 하여서는 아니 된다. <개정 2023.7.4>', 1331);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2327, '③ 진술조력인은 법 제36조제3항에 따라 진술조력인 조력 필요성에 관하여 평가한 의견을 수사기관에 제출하는 경우 구두 또는 서면으로 할 수 있다.', 1331);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2328, '④ 진술조력인이 제3항에 따라 제출하는 의견에는 다음 각 호의 내용이 포함되어야 한다.', 1331);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2329, '① 진술조력인은 법 제36조제4항에 따라 피해자등의 의사소통이나 표현 능력, 특성 등에 관한 의견을 수사기관에 제출하는 경우 서면으로 하여야 한다. <개정 2023.7.4>', 1332);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2330, '② 진술조력인이 제1항에 따라 제출하는 의견에는 피해자등의 진술에 관한 신빙성 또는 사실관계를 평가하는 내용 등을 포함해서는 아니 된다. <개정 2023.7.4>', 1332);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2331, '③ 제1항 및 제2항에서 규정한 사항 외에 진술조력인의 조사 후 의견 제출에 필요한 사항에 관하여는 법무부장관이 정한다.', 1332);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2332, '①검사는 「형사소송법」 제470조 또는 제471조에 따라 징역, 금고 또는 구류의 선고를 받은 자에 대하여 형의 집행을 정지한 때에는 다음 각 호의 사항을 형의 집행정지처분을 받은 자(이하 "형집행정지자"라 한다)의 거주지를 관할하는 경찰서장에게 통지하여야 한다. <개정 2012.4.23>', 1334);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2333, '②형의 집행정지처분을 한 검사가 형집행정지자의 거주지를 관할하는 지방검찰청 또는 지청이 아닌 검찰청에 소속하는 경우에는 그 검사는 특별한 사유가 있는 경우를 제외하고는 집행정지에 관한 서류를 형집행정지자의 거주지를 관할하는 지방검찰청 또는 지청의 검사에게 송부하고, 그 송부를 받은 검사가 제1항의 규정에 의한 통지를 하여야 한다. <개정 1991ㆍ6ㆍ19>', 1334);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2334, '①제1조의 규정에 의한 통지를 받은 경찰서장은 형집행정지자에 대하여 그 집행정지사유의 존속여부를 관찰하고 다음 각호의 1에 해당하는 사유가 생긴 때에는 지체없이 제1조의 규정에 의한 통지를 한 검사에게 그 뜻을 보고하여야 한다. <개정 1979ㆍ7ㆍ6>', 1335);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2335, '②경찰서장은 제1항각호에 정한 사유의 발생을 확인 또는 예방하기 위하여 필요한 조치를 취할 수 있다. <신설 1979ㆍ7ㆍ6>', 1335);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2336, '③경찰서장은 형집행정지자가 그의 관할구역 밖으로 거주를 이전한 때에는 제1조제1항각호의 사항을 신거주지를 관할하는 경찰서장에게 통지하여야 한다. <개정 1979ㆍ7ㆍ6>', 1335);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2337, '①이 영은 군사법원법 제513조 또는 제514조의 규정에 의하여 형의 집행을 정지한 경우에 이를 준용한다. <개정 1991ㆍ6ㆍ19>', 1338);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2338, '②제1항의 경우에는 군검사를 검사로 보며 형집행정지자가 군병원에 수용된 때에는 그 군병원을 관할하는 군사경찰부대장을 경찰서장으로 본다. <개정 1979ㆍ7ㆍ6, 1991ㆍ6ㆍ19, 2020.2.4, 2022.6.30>', 1338);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2339, null, 1341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2340, '① 형사사법업무 처리기관은 법 제5조제2항에 따른 형사사법정보의 유통표준을 정할 때 다음 각 호의 사항을 준수하여야 한다.', 1342);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2341, '② 전자문서 출력물의 간인(間印)은 면수 및 총면수를 표시하는 방법으로 한다.', 1342);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2342, null, 1343);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2343, '① 법 제8조제1항 단서에 따라 형사사법정보공통시스템(이하 "공통시스템"이라 한다)을 운영ㆍ관리하기 위하여 법무부에 형사사법공통시스템 운영단(이하 "운영단"이라 한다)을 둔다.', 1345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2344, '② 운영단은 법무부 소속 공무원과 형사사법업무 처리기관이나 관계 행정기관에서 파견된 공무원으로 구성한다.', 1345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2345, '③ 법무부장관은 운영단을 운영하기 위하여 필요한 경우에는 다른 형사사법업무 처리기관이나 관계 행정기관에 소속 공무원의 파견을 요청할 수 있다.', 1345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2346, '④ 운영단의 조직 및 정원에 관한 세부사항은 법무부령으로 정한다.', 1345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2347, null, 1346);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2348, '① 운영단은 형사사법업무 처리기관이 형사사법업무를 처리하는 데에 지장이 없도록 공통시스템을 안정적으로 관리하여야 한다.', 1347);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2349, '② 운영단은 형사사법업무 처리기관의 시스템이 변경되어 공통시스템의 변경이 필요한 경우 적극 협조하여야 한다.', 1347);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2350, '① 운영단에 파견된 공무원의 보수는 원소속 기관에서 지급한다.', 1349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2351, '② 운영단에 파견된 공무원에게는 예산의 범위에서 수당 및 여비, 그 밖에 필요한 경비를 지급할 수 있다.', 1349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2352, '① 협의회 위원장(이하 "위원장"이라 한다)의 임기는 2년으로 한다.', 1350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2353, '② 위원장은 동일한 형사사법업무 처리기관 소속 위원이 연임할 수 없다.', 1350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2354, '③ 협의회에 간사 1명을 두며, 간사는 위원장이 속한 기관의 법 제13조에 따른 형사사법정보체계 실무협의회의 위원(이하 "실무협의회 주관위원"이라 한다)이 된다.', 1350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2355, '① 법 제11조제1항에 따른 협의회의 정기회의는 특별한 사정이 없으면 매년 3월, 9월에 개최한다.', 1351);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2356, '② 협의회의 각 위원은 서면으로 법 제11조제2항에 따른 임시협의회의 개최를 요구할 수 있다.', 1351);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2357, '③ 제2항에 따른 요구가 있는 경우 위원장은 특별한 사유가 없으면 요구가 있은 날부터 14일 이내에 임시협의회를 개최하여야 한다.', 1351);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2358, '④ 위원장이 정기회의 또는 임시협의회를 소집할 때에는 회의 개최 7일 전까지 회의 안건, 일시 및 장소를 각 위원에게 서면으로 알려야 한다.', 1351);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2359, '⑤ 법 제11조제4항에 따라 대한변호사협회의 의견을 들어야 하는 경우 위원장은 회의 개최 7일 전까지 회의 안건, 일시 및 장소를 대한변호사협회에 통보하여 의견을 제출하도록 하여야 한다.', 1351);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2360, '① 협의회는 업무를 수행하기 위하여 필요한 경우에는 전문적인 지식과 경험이 있는 관계 공무원 또는 전문가 등을 회의에 참석하게 하여 의견을 들을 수 있다.', 1352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2361, '② 위원장은 필요하다고 인정하는 경우에는 협의회 위원 전원의 합의를 거쳐 회의를 비공개로 진행할 수 있다.', 1352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2362, '③ 협의회 위원 전원이 합의한 내용은 회의록 외의 별도 서면으로 작성할 수 있다.', 1352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2363, '① 협의회는 회의록을 작성하여 갖추어 두어야 한다.', 1353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2364, '② 회의록은 협의회의 각 위원이 열람한 후 서명함으로써 확정된다.', 1353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2365, '③ 위원장은 협의회의 각 위원에게 확정된 회의록 사본 1부씩을 내주어야 한다.', 1353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2366, '④ 회의록은 위원장이 관리하며, 10년간 보존한다.', 1353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2367, '① 실무협의회의 회의는 정기회의와 임시회의로 구분한다.', 1355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2368, '② 실무협의회 정기회의는 특별한 사정이 없으면 매년 3월, 9월에 개최한다.', 1355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2369, '③ 법 제11조제2항에 따른 임시협의회의 안건을 미리 검토ㆍ조정할 필요가 있는 경우 또는 실무협의회의 각 위원이 실무협의회 임시회의의 개최를 요구하는 경우에는 실무협의회 임시회의를 개최할 수 있다.', 1355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2370, '④ 실무협의회의 회의는 실무협의회 주관위원이 주관한다.', 1355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2371, '⑤ 실무협의회의 각 위원은 실무협의회 주관위원에게 서면으로 제3항에 따른 임시회의의 개최를 요구할 수 있다.', 1355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2372, '⑥ 제5항에 따른 요구가 있는 경우 실무협의회 주관위원은 요구가 있은 날부터 14일 이내에 회의를 개최하여야 한다.', 1355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2373, '⑦ 실무협의회 주관위원은 회의 개최 7일 전까지 회의 안건, 일시 및 장소를 실무협의회의 각 위원에게 서면으로 알려야 한다.', 1355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2374, '① 실무협의회는 회의록을 작성하여 갖추어 두어야 한다.', 1356);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2375, '② 회의록은 실무협의회의 각 위원이 열람한 후 서명함으로써 확정된다.', 1356);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2376, '③ 실무협의회 주관위원은 실무협의회의 각 위원에게 확정된 회의록 사본 1부씩을 내주어야 한다.', 1356);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2377, '④ 회의록은 실무협의회 주관위원이 관리하며, 10년간 보존한다.', 1356);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2378, null, 1357);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2379, '①몰수보전 청구서에는 다음 각호의 사항을 기재하고 청구하는 검사가 서명날인을 하여야 한다. <개정 2005.12.29>', 1360);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2380, '②몰수보전 청구서에는 공소사실 또는 피의사실의 요지를 따로 기재한 서면 1통을 첨부하여야 한다. <개정 2005.12.29>', 1360);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2381, '③몰수보전의 청구를 하는 때에는 법 제33조제1항이 규정하는 사유를 인정할 수 있는 자료를 제출하여야 한다.', 1360);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2382, '①부대보전 청구서에는 제3조제1항 각호의 사항을 기재하는 외에, 몰수보전의 청구와 함께 하는 경우에는 다음 제2호 및 제3호의 사항을, 몰수보전의 청구와 별도로 하는 경우에는 다음 각호의 사항을 각 기재하고 청구하는 검사가 서명날인을 하여야 한다. <개정 2005.12.29>', 1362);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2383, '②부대보전의 청구를 하는 때에는 법 제33조제2항이 규정하는 사유를 인정할 수 있는 자료를 제출하여야 한다.', 1362);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2384, '③제3조제2항은 부대보전의 청구에 이를 준용한다.', 1362);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2385, '①몰수보전명령의 취소청구는 다음 각호의 사항을 기재한 서면으로 하여야 한다.', 1369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2386, '②몰수보전명령의 취소청구를 하는 때에는 법 제42조제1항이 규정하는 사유를 인정할 수 있는 자료를 제출하여야 한다.', 1369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2387, '③검사 또는 수사처검사 아닌 자가 제1항의 취소청구를 할 때에는 그 청구서의 부본을 첨부하여야 한다. <개정 2021.1.29>', 1369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2388, '④법원이 몰수보전명령의 취소에 관하여 검사 또는 수사처검사의 의견을 물을 때에는 제3항의 청구서 부본을 첨부하여야 한다. <개정 2021.1.29>', 1369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2389, '①몰수보전된 재산에 대하여 강제경매개시결정 또는 강제집행에 의하여 압류가 된 때에는, 집행법원의 법원서기관, 법원사무관, 법원주사 또는 법원주사보(이하 "법원사무관등"이라고 한다. 동산의 경우에는 집행관)는 검사 또는 수사처검사에게 그 사실을 통지하여야 한다. <개정 2002.6.28, 2021.1.29>', 1371);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2390, '②제1항의 경우 강제집행신청이 취하된 때 또는 강제집행절차를 취소하는 결정이 확정된 때에는 집행법원의 법원사무관등(동산의 경우에는 집행관)은 검사 또는 수사처검사에게 그 사실을 통지하여야 한다. <개정 2002.6.28, 2021.1.29>', 1371);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2391, '③제1항의 경우 몰수의 재판이 확정되거나 몰수보전이 효력을 상실한 때에는 검사 또는 수사처검사는 집행법원(동산의 경우에는 집행관)에 그 사실을 통지하여야 한다. <개정 2002.6.28, 2021.1.29>', 1371);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2392, '①법 제46조제2항의 규정에 의한 신고는 다음 각호의 사항을 기재한 서면으로 하여야 한다. <개정 2005.12.29>', 1372);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2393, '②제1항의 서면에는 공탁서를 첨부하여야 한다. <개정 2005.12.29>', 1372);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2394, '③제1항의 신고가 있은 경우 몰수보전명령을 발한 법원의 법원사무관등은 압류명령을 발한 법원 및 검사 또는 수사처검사에게 그 사실을 통지하여야 한다. <개정 2021.1.29>', 1372);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2395, '①법 제50조제2항에 의하여 준용되는 법 제46조제2항의 규정에 의한 신고는 다음 각 호의 사항을 기재한 서면으로 하여야 한다.', 1373);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2396, '②제1항의 서면에는 공탁서를 첨부하여야 한다.', 1373);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2397, '③제1항의 신고가 있는 경우 몰수보전명령을 발한 법원의 법원사무관등은 체납처분을 한 「국세기본법」 제2조제17호 및 「지방세법」 제1조제1항제3호의 세무공무원과 그 밖에 체납처분을 집행하는 권한이 있는 자 또는 한국자산관리공사가 세무서장을 대행하여 공매, 배분 및 권리이전등기의 촉탁을 대행하는 경우에는 한국자산관리공사 및 그 직원(이하 "세무공무원등"이라고 한다) 및 검사 또는 수사처검사에게 그 사실을 통지하여야 한다. <개정 2021.1.29>', 1373);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2398, '①제14조제1항 및 제2항은 법 제46조제4항에 의하여 준용되는 같은 조 제2항의 규정에 의한 공탁사유신고에 준용한다.', 1374);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2399, '②제1항의 신고가 있은 경우 압류명령을 발한 법원의 법원사무관등은 몰수보전명령을 발한 법원 및 검사 또는 수사처검사에게 그 사실을 통지하여야 한다. <개정 2021.1.29>', 1374);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2400, '①법 제50조제2항 및 제46조제4항에 의하여 준용되는 법 제46조제2항에 의한 신고는 체납처분을 한 세무공무원등에 하여야 한다.', 1375);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2401, '②제1항의 경우 제14조의2제1항ㆍ제2항의 규정을 준용한다.', 1375);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2402, '①강제경매개시결정 또는 강제집행에 의하여 압류가 된 재산에 대하여 몰수보전명령이 발하여진 때에는 검사 또는 수사처검사는 집행법원(동산의 경우에는 집행관)에 그 사실을 통지하여야 한다. <개정 2002.6.28, 2021.1.29>', 1376);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2403, '②제1항의 경우 몰수의 재판이 확정된 때 또는 몰수보전이 효력을 상실한 때에는 검사 또는 수사처검사는 집행법원(동산의 경우에는 집행관)에 그 사실을 통지하여야 한다. <개정 2002.6.28, 2021.1.29>', 1376);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2404, '③제1항의 경우 강제집행신청의 취하에 의하여 압류의 효력이 소멸하거나 강제집행절차를 취소하는 결정이 확정된 때 또는 강제집행절차에 의하여 재산이 매각된 때에는 집행법원의 법원사무관등(동산의 경우 집행관)은 검사 또는 수사처검사에게 그 사실을 통지하여야 한다. 「민사집행법」 제223조가 규정하는 채권(같은 법 제251조제1항에 의하여 같은 법 제2편제2장제4절제3관의 규정이 준용되는 재산권을 포함한다)에 대하여 같은 법 제236조제1항의 신고가 있는때, 같은 법 제256조의 규정에 의하여 배당이 실시된 때, 같은 법 제229조제3항의 전부명령 또는 같은 법 제241조의 양도명령이 확정된 때에도 그 사실을 통지하여야 한다. <개정 2002.6.28, 2005.12.29, 2021.1.29>', 1376);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2405, '①법 제48조제1항의 강제집행의 정지의 청구는 다음 각호의 사항을 기재한 서면으로 하여야 한다.', 1377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2406, '②제1항의 청구를 하는 경우에는 제1항제2호의 이유가 있다고 인정할 수 있는 자료를 제출하여야 한다.', 1377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2407, '③제11조의 규정은 법 제48조제3항의 강제집행 정지결정의 취소청구에 관하여 준용한다. 이 경우 제11조제1항의 "몰수보전사건의 표시"는 "강제집행정지사건의 표시"로, 같은조 제1항 및 제2항의 각 "법 제42조제1항"은 각 "법 제48조제3항"으로 본다.', 1377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2408, '①제13조의 규정은 몰수보전이 된 재산에 대하여 가압류의 집행이 있는 경우에 준용한다.', 1379);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2409, '②제14조의 규정은 몰수보전이 된 금전채권에 대하여 가압류의 집행이 있는 경우 당해 금전채권의 채무자의 공탁에 관하여, 제15조의 규정은 가압류된 금전채권에 대하여 몰수보전이 된 경우 당해 금전채권의 채무자의 공탁에 관하여 각 준용한다.', 1379);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2410, '③제16조의 규정은 가압류된 재산에 대하여 몰수보전명령이 발하여진 경우에 준용한다.', 1379);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2411, '④제17조의 규정은 가압류된 재산에 대하여 몰수보전명령을 발한 경우 또는 발하려고 하는 경우에 있어서 강제집행의 정지의 청구 및 그 정지결정의 취소청구에 관하여 준용한다.', 1379);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2412, '①추징보전 청구서에는 다음 각호의 사항을 기재하고 검사 또는 수사처검사가 서명날인하여야 한다. <개정 2005.12.29, 2021.1.29>', 1382);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2413, '②추징보전 청구서에는 공소사실 또는 피의사실의 요지를 따로 기재한 서면 1통을 첨부하여야 한다. <개정 2005.12.29>', 1382);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2414, '③추징보전의 청구를 하는 때에는 법 제52조제1항이 규정하는 사유를 인정할 수 있는 자료를 제출하여야 한다.', 1382);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2415, '① 삭제 <2005.12.29>', 1384);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2416, '②추징보전명령이 실효되거나 취소된 때에는 추징보전명령을 발한 법원은 공탁된 추징보전해방금을 환부하여야 한다. <개정 2005.12.29>', 1384);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2417, '①몰수의 확정재판의 집행에 관한 공조요청의 심사청구는 다음의 각호의 사항을 기재한 서면으로 하여야 한다.', 1387);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2418, '②추징의 확정재판의 집행에 관한 공조요청의 심사청구는 서면으로 하여야 하고, 그 서면에는 제1항제1호, 제2호, 제4호의 사항을 기재하는 외에 다음의 각호의 사항을 기재하여야 한다.', 1387);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2419, '①법 제70조제1항의 규정에 의한 취소청구는 다음의 각호의 사항을 기재한 서면으로 하여야 한다.', 1388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2420, '②제1항의 취소청구를 하는 때에는 법 제70조제1항이 규정하는 사유를 인정할 수 있는 자료를 제출하여야 한다.', 1388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2421, '①법 제71조제1항 전문의 규정에 의한 청구(이하 "공조몰수보전청구"라 한다)는 서면으로 하여야 하고, 그 서면에는 제27조제1항제1호 내지 제3호 및 제5호의 사항을 기재하는 외에 다음 각호의 사항을 기재하여야 한다.', 1389);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2422, '②법 제72조제1항의 규정에 의한 청구(이하 "공조추징보전청구"라 한다)는 서면으로 하여야 하고, 그 서면에는 제27조제1항제1호, 제2호 및 같은 조 제2항제3호의 사항을 기재하는 외에 다음 각호의 사항을 기재하여야 한다.', 1389);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2423, '③공조몰수보전청구 또는 공조추징보전청구가 공조요청을 한 외국의 법원 또는 법관이 한 몰수ㆍ추징을 위한 보전의 재판에 기한 요청인 때 또는 몰수ㆍ추징의 재판의 확정후의 요청인 때에는 제1항제3호 또는 제2항제5호의 사항에 갈음하여 그 취지를 기재한다.', 1389);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2424, '④공조몰수보전청구 또는 공조추징보전청구를 하는 때에는 몰수보전명령 또는 추징보전명령을 발할 수 있는 요건이 있다고 인정할 수 있는 자료를 제출하여야 한다.', 1389);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2425, null, 1392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2426, '① 이 법은 대한민국 영역 안에서 이 법으로 정한 죄를 범한 내국인과 외국인에게 적용한다.', 1393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2427, '② 이 법은 대한민국 영역 밖에서 이 법으로 정한 죄를 범한 내국인에게 적용한다.', 1393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2428, '③ 이 법은 대한민국 영역 밖에 있는 대한민국의 선박 또는 항공기 안에서 이 법으로 정한 죄를 범한 외국인에게 적용한다.', 1393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2429, '④ 이 법은 대한민국 영역 밖에서 대한민국 또는 대한민국 국민에 대하여 이 법으로 정한 죄를 범한 외국인에게 적용한다.', 1393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2430, '⑤ 이 법은 대한민국 영역 밖에서 집단살해죄등을 범하고 대한민국영역 안에 있는 외국인에게 적용한다.', 1393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2431, '① 정부 또는 상급자의 명령에 복종할 법적 의무가 있는 사람이 그 명령에 따른 자기의 행위가 불법임을 알지 못하고 집단살해죄등을 범한 경우에는 명령이 명백한 불법이 아니고 그 오인(誤認)에 정당한 이유가 있을 때에만 처벌하지 아니한다.', 1394);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2432, '② 제1항의 경우에 제8조 또는 제9조의 죄를 범하도록 하는 명령은 명백히 불법인 것으로 본다.', 1394);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2433, '① 국민적ㆍ인종적ㆍ민족적 또는 종교적 집단 자체를 전부 또는 일부 파괴할 목적으로 그 집단의 구성원을 살해한 사람은 사형, 무기 또는 7년 이상의 징역에 처한다.', 1398);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2434, '② 제1항과 같은 목적으로 다음 각 호의 어느 하나에 해당하는 행위를 한 사람은 무기 또는 5년 이상의 징역에 처한다.', 1398);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2435, '③ 제2항 각 호의 어느 하나에 해당하는 행위를 하여 사람을 사망에 이르게 한 사람은 제1항에서 정한 형에 처한다.', 1398);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2436, '④ 제1항 또는 제2항의 죄를 선동한 사람은 5년 이상의 유기징역에 처한다.', 1398);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2437, '⑤ 제1항 또는 제2항에 규정된 죄의 미수범은 처벌한다.', 1398);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2438, '① 민간인 주민을 공격하려는 국가 또는 단체ㆍ기관의 정책과 관련하여 민간인 주민에 대한 광범위하거나 체계적인 공격으로 사람을 살해한 사람은 사형, 무기 또는 7년 이상의 징역에 처한다.', 1399);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2439, '② 민간인 주민을 공격하려는 국가 또는 단체ㆍ기관의 정책과 관련하여 민간인 주민에 대한 광범위하거나 체계적인 공격으로 다음 각 호의 어느 하나에 해당하는 행위를 한 사람은 무기 또는 5년 이상의 징역에 처한다.', 1399);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2440, '③ 인종집단의 구성원으로서 다른 인종집단을 조직적으로 억압하고 지배하는 체제를 유지할 목적으로 제1항 또는 제2항에 따른 행위를 한 사람은 각 항에서 정한 형으로 처벌한다.', 1399);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2441, '④ 제2항 각 호의 어느 하나에 해당하는 행위 또는 제3항의 행위(제2항 각 호의 어느 하나에 해당하는 행위로 한정한다)를 하여 사람을 사망에 이르게 한 사람은 제1항에서 정한 형에 처한다.', 1399);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2442, '⑤ 제1항부터 제3항까지에 규정된 죄의 미수범은 처벌한다.', 1399);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2443, '① 국제적 무력충돌 또는 비국제적 무력충돌(폭동이나 국지적이고 산발적인 폭력행위와 같은 국내적 소요나 긴장 상태는 제외한다. 이하 같다)과 관련하여 인도에 관한 국제법규에 따라 보호되는 사람을 살해한 사람은 사형, 무기 또는 7년 이상의 징역에 처한다.', 1400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2444, '② 국제적 무력충돌 또는 비국제적 무력충돌과 관련하여 다음 각 호의 어느 하나에 해당하는 행위를 한 사람은 무기 또는 5년 이상의 징역에 처한다.', 1400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2445, '③ 국제적 무력충돌 또는 비국제적 무력충돌과 관련하여 다음 각 호의 어느 하나에 해당하는 행위를 한 사람은 3년 이상의 유기징역에 처한다.', 1400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2446, '④ 국제적 무력충돌 또는 비국제적 무력충돌과 관련하여 인도에 관한 국제법규에 따라 보호되는 사람을 중대하게 모욕하거나 품위를 떨어뜨리는 처우를 한 사람은 1년 이상의 유기징역에 처한다.', 1400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2447, '⑤ 국제적 무력충돌과 관련하여 다음 각 호의 어느 하나에 해당하는 행위를 한 사람은 3년 이상의 유기징역에 처한다.', 1400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2448, '⑥ 제2항ㆍ제3항 또는 제5항의 죄를 범하여 사람을 사망에 이르게 한 사람은 사형, 무기 또는 7년 이상의 징역에 처한다.', 1400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2449, '⑦ 제1항부터 제5항까지에 규정된 죄의 미수범은 처벌한다.', 1400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2450, '① 국제적 무력충돌 또는 비국제적 무력충돌과 관련하여 적국 또는 적대 당사자의 재산을 약탈하거나 무력충돌의 필요상 불가피하지 아니한데도 적국 또는 적대 당사자의 재산을 국제법규를 위반하여 광범위하게 파괴ㆍ징발하거나 압수한 사람은 무기 또는 3년 이상의 징역에 처한다.', 1401);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2451, '② 국제적 무력충돌과 관련하여 국제법규를 위반하여 적국의 국민 전부 또는 다수의 권리나 소송행위가 법정에서 폐지ㆍ정지되거나 허용되지 아니한다고 선언한 사람은 3년 이상의 유기징역에 처한다.', 1401);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2452, '③ 제1항 또는 제2항에 규정된 죄의 미수범은 처벌한다.', 1401);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2453, '① 국제적 무력충돌 또는 비국제적 무력충돌과 관련하여 다음 각 호의 어느 하나에 해당하는 행위를 한 사람은 3년 이상의 유기징역에 처한다.', 1402);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2454, '② 국제적 무력충돌 또는 비국제적 무력충돌과 관련하여 제네바협약에 규정된 식별표장ㆍ휴전기(休戰旗), 적이나 국제연합의 깃발ㆍ군사표지 또는 제복을 부정한 방법으로 사용하여 사람을 사망에 이르게 하거나 사람의 신체에 중대한 손상을 입힌 사람은 다음의 구분에 따라 처벌한다.', 1402);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2455, '③ 제1항 또는 제2항에 규정된 죄의 미수범은 처벌한다.', 1402);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2456, '① 국제적 무력충돌 또는 비국제적 무력충돌과 관련하여 다음 각 호의 어느 하나에 해당하는 행위를 한 사람은 무기 또는 3년 이상의 징역에 처한다.', 1403);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2457, '② 제1항제1호부터 제6호까지의 죄를 범하여 인도에 관한 국제법규에 따라 보호되는 사람을 사망 또는 상해에 이르게 한 사람은 다음의 구분에 따라 처벌한다.', 1403);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2458, '③ 국제적 무력충돌 또는 비국제적 무력충돌과 관련하여 자연환경에 군사작전상 필요한 것보다 지나치게 광범위하고 장기간의 중대한 훼손을 가하는 것이 명백한 공격 행위를 한 사람은 3년 이상의 유기징역에 처한다.', 1403);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2459, '④ 제1항 또는 제3항에 규정된 죄의 미수범은 처벌한다.', 1403);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2460, '① 국제적 무력충돌 또는 비국제적 무력충돌과 관련하여 다음 각 호의 어느 하나에 해당하는 무기를 사용한 사람은 무기 또는 5년 이상의 징역에 처한다.', 1404);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2461, '② 제1항의 죄를 범하여 사람의 생명ㆍ신체 또는 재산을 침해한 사람은 사형, 무기 또는 7년 이상의 징역에 처한다.', 1404);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2462, '③ 제1항에 규정된 죄의 미수범은 처벌한다.', 1404);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2463, '① 군대의 지휘관 또는 단체ㆍ기관의 상급자로서 직무를 게을리하거나 유기(遺棄)하여 실효적인 지휘와 통제하에 있는 부하가 집단살해죄등을 범하는 것을 방지하거나 제지하지 못한 사람은 7년 이하의 징역에 처한다.', 1405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2464, '② 과실로 제1항의 행위에 이른 사람은 5년 이하의 징역에 처한다.', 1405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2465, '③ 군대의 지휘관 또는 단체ㆍ기관의 상급자로서 집단살해죄등을 범한 실효적인 지휘와 통제하에 있는 부하 또는 하급자를 수사기관에 알리지 아니한 사람은 5년 이하의 징역에 처한다.', 1405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2466, '① 국제형사재판소에서 수사 또는 재판 중인 사건과 관련하여 다음 각 호의 어느 하나에 해당하는 사람은 5년 이하의 징역 또는 1천500만원 이하의 벌금에 처하거나 이를 병과(倂科)할 수 있다.', 1406);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2467, '② 제1항은 국제형사재판소의 청구 또는 요청에 의하여 대한민국 내에서 진행되는 절차에 대하여도 적용된다.', 1406);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2468, '③ 제1항의 사건과 관련하여 「형법」 제152조, 제154조 또는 제155조제1항부터 제3항까지의 규정이나 「특정범죄 가중처벌 등에 관한 법률」 제5조의9에 따른 행위를 한 사람은 각 해당 규정에서 정한 형으로 처벌한다. 이 경우 「형법」 제155조제4항은 적용하지 아니한다.', 1406);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2469, '④ 제1항의 사건과 관련하여 국제형사재판소 직원에게 「형법」 제136조, 제137조 또는 제144조에 따른 행위를 한 사람은 각 해당 규정에서 정한 형으로 처벌한다. 이 경우 국제형사재판소 직원은 각 해당 규정에 따른 공무원으로 본다.', 1406);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2470, '⑤ 제1항의 사건과 관련하여 국제형사재판소 직원에게 「형법」 제133조의 행위를 한 사람은 같은 조에서 정한 형으로 처벌한다. 이 경우 국제형사재판소 직원은 해당 조문에 따른 공무원으로 본다.', 1406);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2471, '⑥ 이 조에서 "국제형사재판소 직원"이란 재판관, 소추관, 부소추관, 사무국장 및 사무차장을 포함하여 국제형사재판소규정에 따라 국제형사재판소의 사무를 담당하는 사람을 말한다.', 1406);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2472, '① 대한민국과 국제형사재판소 간의 범죄인 인도에 관하여는 「범죄인 인도법」을 준용한다. 다만, 국제형사재판소규정에 「범죄인 인도법」과 다른 규정이 있는 경우에는 그 규정에 따른다.', 1409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2473, '② 제1항의 경우 「범죄인 인도법」 중 "청구국"은 "국제형사재판소"로, "인도조약"은 "국제형사재판소규정"으로 본다.', 1409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2474, '① 국제형사재판소의 형사사건 수사 또는 재판과 관련하여 국제형사재판소의 요청에 따라 실시하는 공조 및 국제형사재판소에 대하여 요청하는 공조에 관하여는 「국제형사사법 공조법」을 준용한다. 다만, 국제형사재판소규정에 「국제형사사법 공조법」과 다른 규정이 있는 경우에는 그 규정에 따른다.', 1410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2475, '② 제1항의 경우 「국제형사사법 공조법」 중 "외국"은 "국제형사재판소"로, "공조조약"은 "국제형사재판소규정"으로 본다.', 1410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2476, '① 아동보호사건 및 피해아동보호명령사건을 관할하는 가정법원 및 지방법원과 그 지원의 관할구역은 다음 각 호와 같다. <개정 2025.2.28>', 1412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2477, '② 제1항제1호 단서에도 불구하고 법 제14조에 따른 검사의 임시조치청구 사건은 위 법률 별표 3에 따라 서울특별시 내의 관할구역을 관할하는 법원의 관할로 한다. 다만, 서울중앙지방법원 관할구역의 임시조치청구 사건은 서울가정법원의 관할로 한다. <개정 2025.2.28>', 1412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2478, '③ 검사의 청구에 따라 임시조치를 결정한 사건이 다음 각 호의 어느 하나에 해당하는 경우에는 그 임시조치를 결정한 법원에 법 제22조제1항에 따른 취소ㆍ변경 신청, 법 제22조제2항에 따른 연장ㆍ변경ㆍ취소 청구 또는 법 제21조제3항, 제22조제4항에 따른 변경 신청 및 청구를 할 수 있고, 당해 임시조치를 결정한 법원은 법 제22조제3항, 제4항에 따른 취소ㆍ변경 및 연장을 할 수 있다. <신설 2025.2.28, 2025.5.30>', 1412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2479, '④ 가정법원이 설치되지 아니한 지역의 지방법원과 그 지원의 단독판사 또는 합의부가 아동학대행위자(이하 "행위자"라 한다)에 대한 피고사건을 심리한 결과 보호처분에 처함이 상당하다고 인정하여 법 제29조의 결정을 한 때에는 당해단독판사 또는 합의부의 구성원이 아동보호사건으로 심리할 수 있다. <개정 2025.2.28>', 1412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2480, '⑤ 가정법원이 한 배상명령에 대한 청구이의의 소는 해당 가정법원의 소재지를 관할하는 지방법원에 제기하여야 한다. <개정 2025.2.28>', 1412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2481, '① 법 및 이 규칙에 의한 결정을 함에는 결정서를 작성하고 판사가 서명날인 하여야 한다. 다만, 다음 각 호의 결정 이외에는 결정서에 기명날인할 수 있고, 결정의 내용을 조서에 기재하게 하여 결정서의 작성에 갈음할 수 있다.', 1413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2482, '② 결정서에는 행위자의 성명, 주민등록번호, 직업, 주거, 등록기준지 및 주문과 이유를 기재하여야 한다. 다만, 제1항제1호 및 제4호 결정의 결정서에는 행위자의 성명, 주민등록번호, 주거, 등록기준지 및 주문 이외의 기재를 생략할 수 있다.', 1413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2483, '③ 법 제19조제1항제4호 및 법 제36조제1항제3호 결정의 결정서, 피해아동보호명령 및 임시보호명령의 결정서에는 제2항의 행위자에 관한 사항 이외에 피해아동의 성명, 주민등록번호, 주거, 등록기준지 및 보조인이 있는 경우 보조인의 성명, 주소를 각 기재하여야 한다. 다만, 피해아동 및 보조인의 안전에 위협이 될 우려가 있는 경우에는 피해아동 및 보조인의 주거 또는 주소 기재를 생략할 수 있다.', 1413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2484, '① 보호처분결정 및 피해아동보호명령은 심리기일에 결정서에 의하여 고지하여야 한다. 다만, 심리기일에 결정서를 미리 작성하기 어려운 사정이 있는 경우 결정의 고지 후에 결정서를 작성할 수 있다. <개정 2025.2.28>', 1414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2485, '② 제1항의 결정 이외의 결정은 법 및 이 규칙에 특별한 정함이 없는 경우에도 행위자에게 통지하여야 한다. 다만, 법 제44조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제27조제2항의 규정에 의한 결정은 그러하지 아니하다.', 1414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2486, '③ 제3조제1항 단서 각 호의 결정(피해아동보호명령 결정을 제외한다)은 법 및 이 규칙에 특별한 정함이 없는 경우에도 피해아동, 법정대리인(아동학대행위자를 제외한다, 이하 같다), 변호사(법 제16조에 따른 변호사를 말한다. 이 규칙 제13조 및 제23조를 제외하고는 이하 같다)에게 통지하여야 한다. <신설 2016.11.1>', 1414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2487, '④ 법 및 이 규칙에 의하여 결정을 통지함에는 결정서 등본의 송달 기타 적당하다고 인정하는 방식에 의할 수 있다. <개정 2016.11.1>', 1414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2488, '⑤ 제4항의 송달에 관하여는 「민사소송법」중 송달에 관한 규정 및 「형사소송법」 제76조제2항부터 제5항까지를 준용한다. <개정 2016.11.1>', 1414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2489, '① 법 제19조제1항제5호부터 제7호까지의 임시조치결정을 한 때에는 수탁ㆍ유치기관의 장에게 결정을 통지하여야 한다.', 1415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2490, '② 법 제19조제1항제5호부터 제7호까지의 임시조치결정에 의하여 위탁ㆍ유치된 행위자에 관하여 이송ㆍ보호처분결정을 한 때에는 그 수탁ㆍ유치기관의 장에게 즉시 결정을 통지하여야 한다.', 1415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2491, '③ 법 제19조제1항제5호부터 제7호까지의 임시조치가 계속중인 행위자 및 법 제36조제1항제4호부터 제8호까지의 보호처분이 계속중인 행위자에 관하여 임시조치의 연장ㆍ취소ㆍ변경결정, 보호처분의 취소ㆍ종료결정 또는 법 제45조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제51조제2항 및 이 규칙 제67조제2항에 따른 결정을 한 때에는 수탁ㆍ유치기관 또는 보호관찰소의 장에게 즉시 결정을 통지하여야 한다.', 1415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2492, '④ 법 제52조제1항, 법 제47조제1항제4호부터 제6호까지의 임시보호명령 또는 법 제47조제1항제4호부터 제6호까지의 피해아동보호명령을 한 때에는 수탁기관의 장 또는 수탁 연고자에게 그 결정을 통지하여야 한다. <신설 2016.11.1>', 1415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2493, '⑤ 법 제52조제1항, 법 제47조제1항제4호부터 제6호까지의 임시보호명령에 따라 위탁된 피해아동에 관하여 이송결정ㆍ피해아동보호명령을 한 때에는 그 수탁기관의 장 또는 수탁 연고자에게 즉시 그 결정을 통지하여야 한다. <신설 2016.11.1>', 1415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2494, '⑥ 법 제52조제1항, 법 제47조제1항제4호부터 제6호까지의 임시보호명령이 계속 중인 피해아동 및 법 제47조제1항제4호부터 제6호까지의 피해아동보호명령이 계속 중인 피해아동에 관하여 임시보호명령의 취소ㆍ변경결정, 피해아동보호명령의 연장ㆍ취소ㆍ변경결정 또는 법 제57조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제51조제2항 및 이 규칙 제103조, 제67조제2항에 따른 결정을 한 때에는 수탁기관의 장 또는 수탁 연고자에게 즉시 그 결정을 통지하여야 한다. <신설 2016.11.1>', 1415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2495, '① 임시조치결정을 한 후에 이송ㆍ보호처분결정을 하거나 그 임시조치의 연장ㆍ취소ㆍ변경결정 또는 법 제45조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제51조제2항 및 이 규칙 제67조제2항에 따른 결정을 한 때에는 그 임시조치의 집행을 담당한 경찰서의 장 또는 구치소의 장에게 그 결정을 통지하여야 한다.', 1416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2496, '② 보호처분결정을 한 후에 그 보호처분의 변경ㆍ취소ㆍ종료결정 또는 법 제45조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제51조제2항 및 이 규칙 제67조제2항에 따른 결정을 한 때에는 그 보호처분의 집행을 담당한 경찰서의 장에게 그 결정을 통지하여야 한다.', 1416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2497, '③ 임시보호명령을 한 후에 이송결정ㆍ피해아동보호명령을 하거나 그 임시보호명령의 취소ㆍ변경결정 또는 법 제57조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제51조제2항 및 이 규칙 제103조, 제67조제2항에 따른 결정을 한 때에는 그 임시보호명령의 집행을 담당한 경찰서의 장이나 구치소의 장 또는 이를 위임받은 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 그 결정을 통지하여야 한다. <개정 2020.9.28>', 1416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2498, '④ 피해아동보호명령을 한 후에 그 피해아동보호명령의 취소ㆍ변경ㆍ연장결정 또는 법 제57조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제51조제2항 및 이 규칙 제103조, 제67조제2항에 따른 결정을 한 때에는 그 피해아동보호명령의 집행을 담당한 경찰서의 장이나 구치소의 장 또는 이를 위임받은 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 그 결정을 통지하여야 한다. <개정 2020.9.28>', 1416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2499, '① 법 제29조의 규정에 의한 송치결정을 한 때에는 당해사건을 기소한 검찰청의 검사에게 결정을 통지하여야 한다.', 1417);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2500, '② 임시조치ㆍ이송ㆍ불처분ㆍ보호처분ㆍ보호처분의 변경ㆍ보호처분의 종료 결정을 검사에게 통지할 때에는 당해 사건을 송치한 검찰청의 검사에게 한다.', 1417);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2501, '① 법원이 법 제44조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제27조제2항의 규정에 의하여 사건을 검사에게 송치하는 결정을 하거나 법 제44조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제37조제2항제1호 및 법 제41조제1호에 의하여 검사에게 송치할 경우에는 사건기록, 결정서 및 증거물을 피고사건의 관할법원에 대응하는 검찰청에 송부한다. 다만, 법 제44조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제37조제2항제1호 및 법 제41조제1호의 규정에 의한 결정을 한 때에는 그 결정이 확정된 때에 송부한다.', 1418);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2502, '② 법 제19조제1항제7호의 조치가 있었을 때에는 그 유치기간은 형법 제57조제1항의 판결선고전의 구금일수로 본다.', 1418);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2503, '③ 법 제44조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제37조제2항제2호 및 법 제41조제2호의 경우에는 사건기록, 결정서 및 증거물을 송치받은 법원에 직접 송부한다.', 1418);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2504, '① 임시조치 및 보호처분, 임시보호명령 및 피해아동보호명령은 결정을 한 때부터 집행한다. 다만, 법 제36조제1항제4호, 제5호의 보호처분은 결정이 확정된 때부터 집행하고, 임시조치 및 보호처분, 피해아동보호명령의 기간을 연장하는 결정은 원래의 임시조치 및 보호처분, 피해아동보호명령에 계속하여 집행한다. <개정 2016.11.1>', 1419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2505, '② 제1항의 경우 초일은 시간을 계산함이 없이 1일로 산정한다.', 1419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2506, '③ 법 및 이 규칙에 의하여 유치집행 또는 위탁집행이 되지 아니한 기간은 집행기간에 산입하지 아니한다.', 1419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2507, null, 1420);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2508, '① 법 제14조에 따른 임시조치의 청구는 서면으로 하되 그 청구서에는 범죄사실의 요지 및 법 제19조제1항 각 호의 임시조치를 필요로 하는 사유를 기재하고 이를 소명하여야 한다. 또한 피해아동등의 법정대리인, 변호사, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장 및 피해아동등을 보호하고 있는 기관의 장이 있는 경우에는 그 성명, 통지할 장소를 기재하여야 한다. <개정 2016.11.1, 2020.9.28, 2025.2.28>', 1421);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2509, '② 제1항의 청구를 받은 판사는 신속히 임시조치의 여부를 결정하여야 하고, 임시조치의 사유를 판단하기 위하여 필요하다고 인정하는 때에는 행위자ㆍ피해아동등ㆍ가정구성원 기타 참고인을 소환하거나 동행영장을 발부하여 필요한 사항을 조사ㆍ심리할 수 있다. <개정 2020.9.28>', 1421);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2510, '③ 제1항의 청구를 받은 판사가 임시조치 결정 또는 임시조치청구를 기각하는 결정을 한 때에는 결정서 등본을 검사에게 송달하고, 검사 또는 사법경찰관은 이를 수사기록에 편철하여야 한다.', 1421);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2511, '④ 법원은 제1항의 청구에 의하여 임시조치를 결정할 때에는 검사, 행위자 및 피해아동등, 그 법정대리인, 변호사, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장 및 피해아동등을 보호하고 있는 기관의 장에게 결정을 통지하여야 한다. <개정 2020.9.28, 2025.2.28>', 1421);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2512, '⑤ 검사가 사건을 불기소하는 때에는 이미 행하여진 임시조치는 그 효력을 잃는다. 이 경우 검사는 그 취지를 행위자 및 피해아동등, 그 법정대리인, 변호사, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장 및 피해아동등을 보호하고 있는 기관의 장, 임시조치의 집행을 담당한 경찰서의 장 또는 구치소의 장, 수탁ㆍ유치기관 등에 통지하여야 한다. <개정 2025.2.28>', 1421);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2513, '⑥ 삭제 <2025.2.28>', 1421);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2514, '① 검사가 법원에 아동보호사건을 송치하는 경우에는 송치서에 범죄사실, 적용법조 및 구속여부를 명시하여야 한다. 이 경우 검사는 보호처분에 관한 의견을 기재할 수 있고, 피해아동의 법정대리인, 변호사 또는 피해아동을 보호하고 있는 기관의 장이 있는 경우에는 그 성명, 통지 및 송달할 장소를 기재하여야 한다.', 1422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2515, '② 법 제31조제2항에 규정된 참고자료는 수사기록과 증거물 전부를 말한다.', 1422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2516, '③ 공범이 있거나 법 제28조제2항등의 사유로 송치서에 전항의 참고자료를 첨부할 수 없는 경우에는 그중 아동보호사건과 관련되는 부분의 등본을 첨부하여야 한다.', 1422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2517, '① 검사 또는 법원이 구금된 피고인을 아동보호사건으로 송치한 경우에 판사가 법 제19조제1항제1호부터 제5호까지의 임시조치를 결정하거나 임시조치를 할 필요가 없다고 인정한 때에는 행위자를 즉시 석방하여야 한다.', 1423);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2518, '② 제1항의 경우 판사는 구속영장의 적당한 여백에 석방지휘 일시를 기재하고 서명날인 한 후 그 등본을 구금시설의 장에게 교부한다.', 1423);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2519, null, 1424);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2520, '① 조사관은 행위자ㆍ피해아동등 및 가정구성원의 출석을 요구하거나 방문하여 면접ㆍ관찰ㆍ심문 등을 할 수 있다. 이 경우의 출석요구는 출석요구서의 송달이나 그 밖의 적당한 방법으로 할 수 있다. <개정 2020.9.28, 2025.2.28>', 1426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2521, '② 조사관은 제1항에도 불구하고 질병이나 그 밖의 부득이한 사정으로 대면조사를 하기 어려운 경우,  영상 또는 전화 조사 등 적당한 방법으로 면접ㆍ심문 등을 할 수 있다. <신설 2025.2.28>', 1426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2522, '③ 조사관은 법 제44조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제22조의 진단소견ㆍ의견조회, 법 제19조제1항 각 호의 임시조치 또는 법 제44조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제36조의 원조ㆍ협조가 필요하다고 인정한 때에는 판사에게 그 의견을 진술할 수 있다. <개정 2025.2.28>', 1426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2523, '④ 조사는 다음 각 호의 사항에 관하여 한다. <개정 2020.9.28, 2025.2.28>', 1426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2524, '① 행위자ㆍ피해아동등ㆍ가정구성원 기타 참고인의 소환은 소환장의 송달에 의한다. <개정 2020.9.28>', 1428);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2525, '② 제1항의 소환장에는 사건명, 행위자의 성명 및 소환되는 사람의 성명, 아동보호사건에 관하여 소환되는 뜻, 출석할 일시와 장소, 행위자가 정당한 이유없이 소환에 응하지 아니할 때에는 동행영장을 발부할 수 있다는 뜻을 기재하고 판사가 기명날인하여야 한다.', 1428);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2526, '③ 출석요구서 및 소환장의 송달에 관하여는 이 규칙 제4조제5항을 준용한다. 다만, 「민사소송법」 제187조 및 제194조부터 제196조까지는 이를 준용하지 아니한다. <개정 2016.11.1>', 1428);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2527, '① 피해아동등ㆍ보조인ㆍ가정구성원, 그 밖의 참고인 등에 대한 심리기일의 통지는 기일통지서 또는 출석요구서를 송달하는 방법으로 한다.', 1429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2528, '② 제1항에도 불구하고 긴급한 필요가 있는 경우에는 전화ㆍ팩스ㆍ보통우편 또는 전자우편이나 그 밖에 적당한 방법으로 통지할 수 있다.', 1429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2529, '③ 제2항의 방법으로 심리기일을 통지한 경우 법원서기관ㆍ법원사무관ㆍ법원주사 또는 법원주사보(이하 "법원사무관등"이라고 한다)는 그 방법과 날짜를 소송기록에 표시하여야 한다.', 1429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2530, '① 법 제19조제1항제6호 및 제7호의 임시조치에 의하여 수탁ㆍ유치기관에 수용 중인 행위자가 이 규칙 제15조제1항에 따른 출석요구 또는 법 제44조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」제24조제1항에 따른 소환을 받은 때에는 그 수탁ㆍ유치기관의 장은 소속직원으로 하여금 행위자를 호송하고 당일의 조사ㆍ심리가 종료될 때까지 법원청사 내에서 행위자를 감호하게 하여야 한다. <개정 2016.11.1>', 1430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2531, '② 행위자가 의료기관 기타 요양시설에 위탁된 경우에 법원은 그 수탁기관의 소재지를 관할하는 경찰관서에 전항의 조치를 요청할 수 있다.', 1430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2532, '① 동행영장은 판사의 지휘에 의하여 집행한다.', 1432);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2533, '② 제1항의 집행지휘는 동행영장을 법 제44조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제27조제1항에 정한 집행담당자에게 교부함으로써 한다.', 1432);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2534, '① 동행영장을 집행함에는 행위자에게 이를 제시하고 신속히 법원에 인치하여야 한다.', 1433);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2535, '② 동행영장을 소지하지 않은 경우 급속을 요할 때에는 제1항의 규정에 불구하고 행위자에게 행위의 개요 및 동행영장이 발부되었음을 고지하고 집행할 수 있다. 이 경우에는 집행완료 후 신속히 동행영장을 제시하여야 한다.', 1433);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2536, '③ 동행영장을 집행한 때에는 동행영장에 집행일시와 장소 및 법원에 인치한 일시를, 집행할 수 없었을 때에는 그 사유를 각 기재하고 기명날인하여 법원에 제출하여야 한다.', 1433);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2537, '① 동행영장에 의하여 법원에 인치된 행위자를 법원외의 장소에 수용할 필요가 있을 때에는 판사는 동행영장의 집행담당자에게 동행영장에 기재된 수용할 장소에 행위자를 수용할 것을 지휘할 수 있다. 이 경우 수용된 행위자의 소환에 대하여는 이 규칙 제18조제1항을 준용한다.', 1434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2538, '② 판사가 법 제19조제1항제1호부터 제5호까지의 임시조치를 결정하거나 임시조치를 할 필요가 없다고 인정한 때에는 행위자를 즉시 석방하여야 한다.', 1434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2539, '① 행위자가 보조인을 선임함에는 보조인과 연명날인한 서면을 제출하여야 한다. 변호사가 아닌 사람을 보조인으로 선임할 경우에는 위 서면에 행위자와 보조인과의 관계를 기재하고 이를 소명하는 서면을 첨부하여야 한다.', 1435);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2540, '② 판사는 언제든지 법 제44조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제28조제2항 단서의 허가를 취소할 수 있다.', 1435);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2541, '③ 보조인의 선임은 심급마다 하여야 한다.', 1435);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2542, '④ 「형사소송법」 중 변호인의 권리의무에 관한 규정은 아동보호사건의 성질에 위반되지 아니하는 한 보조인에 이를 준용한다.', 1435);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2543, '① 행위자의 정신질환ㆍ약물남용 등으로 인하여 의학적인 치료와 요양이 시급히 필요하거나 전문가의 진단소견 또는 의견조회를 위하여 필요하다고 인정하여 법 제19조제1항제6호의 임시조치를 할 때에는 행위자를 수탁기관에 수용할 수 있다.', 1437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2544, '② 제1항의 임시조치를 함에는 사전에 그 수탁기관의 장에게 도주방지등 행위자를 감호하는데 필요한 사항을 고지하고 동의를 얻어야 한다.', 1437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2545, '③ 수탁기관의 장은 수용 중인 행위자가 도주하는등 행위자의 신상에 변동을 초래할 만한 사유가 발생하였을 때에는 지체 없이 이를 법원에 보고하여야 한다.', 1437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2546, '① 법 제19조제1항제4호의 임시조치를 한 때에는 판사는 지체 없이 가족관계등록사무를 관장하는 자에게 가족관계등록부기록을 촉탁하여야 한다.', 1438);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2547, '② 가족관계등록부기록의 촉탁에 관하여는 「가사소송규칙」 제5조제2항, 제6조를 준용한다.', 1438);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2548, '① 판사는 법 제19조제1항제4호의 임시조치로 인하여 피해아동등에게 친권을 행사하거나 후견인의 임무를 수행할 사람이 없는 경우에는 특별한 사정이 없는 한 위 임시조치와 동시에 법 제23조제1항에 따라 임시로 후견인의 임무를 수행할 사람(이하 ‘임시후견인’이라고 한다)을 선임하여야 한다. <개정 2020.9.28>', 1439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2549, '② 판사는 임시후견인에게 정당한 사유가 있는 경우 그 사임을 허가할 수 있다. 이 경우 판사는 특별한 사정이 없는 한 그 사임 허가와 동시에 새로운 임시후견인을 선임하여야 한다.', 1439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2550, '③ 판사는 피해아동등의 복리를 위하여 임시후견인을 변경할 필요가 있다고 인정하면 언제든지 임시후견인을 변경할 수 있다. <개정 2020.9.28>', 1439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2551, '④ 임시후견인의 선임, 사임허가 및 변경의 재판은 결정으로 하고, 판사는 필요하다고 인정하면 피해아동등, 변호사, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장, 아동보호전문기관의 장 및 가정위탁지원센터의 장 등 피해아동등을 보호하고 있는 사람, 임시후견인, 임시후견인이 될 자 등의 의견을 구술 또는 서면 등 상당한 방법으로 들을 수 있다. <개정 2016.11.1, 2020.9.28>', 1439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2552, '⑤ 제2항에 따른 임시후견인 사임허가 및 제3항에 따른 임시후견인 변경의 경우에는 법 제23조제3항을 준용한다.', 1439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2553, '⑥ 판사는 임시후견인에게 그 후견사무에 관하여 필요하다고 인정되는 사항을 지시할 수 있다.', 1439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2554, '⑦ 법 제19조제1항제4호의 임시조치가 법 및 이 규칙에 따라 그 효력을 상실하게 된 때에는 위 임시조치에 따른 임시후견인은 그 지위를 상실한다.', 1439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2555, '⑧ 임시후견인의 선임, 사임허가 및 변경 결정을 한 때, 제7항에 따라 임시후견인의 지위가 상실된 때에는 제26조를 준용한다.', 1439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2556, '⑨ 법 제23조제3항에 따른 고지를 함에는 결정서 등본의 송달 기타 적당하다고 인정하는 방식에 의할 수 있다. <신설 2022.2.25>', 1439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2557, '① 법원장ㆍ지원장은 매년 12월 말까지 관할구역 또는 인접관할구역 내의 아동보호전문기관, 의료기관, 요양시설 등 중에서 법 제19조제1항제5호 및 제6호의 임시조치 집행을 위한 수탁기관을 지정하여야 한다. <개정 2025.2.28>', 1441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2558, '② 제1항에 따라 수탁기관으로 지정할 시설은 행위자에 대한 상담과 교육, 치료와 환경의 조정 및 성행의 교정에 적당한 곳이어야 하며, 해당 시설을 수탁기관으로 지정하려면 미리 그 시설의 운영자와 협의하여야 한다. <개정 2025.2.28>', 1441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2559, '③ 법원장ㆍ지원장은 언제든지 조사관이나 법원사무관등으로 하여금 제1항에 따라 지정된 수탁기관이 행위자를 보호하기에 충분한 시설을 가지고 있는지 여부와 그 운영실태를 조사ㆍ보고하도록 하고, 행위자 보호에 부적당하다고 인정되는 경우에는 그 지정을 취소할 수 있다. <개정 2025.2.28>', 1441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2560, '① 판사는 필요한 경우에 수탁기관의 장으로 하여금 위탁에 소요되는 비용의 예상액과 그 산출근거를 기재한 예상비용산정서를 제출하게 할 수 있다.', 1442);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2561, '② 판사는 수탁기관의 장이 제출한 예상비용산정서, 행위자의 경제적 능력 등을 종합하여 위탁비용의 예납액을 산출하고 이를 행위자 또는 그 법정대리인에게 서면으로 통지하여야 한다.', 1442);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2562, '③ 판사는 행위자가 위탁에 소요되는 비용을 부담할 경제적 능력이 없다고 인정하는 때에는 위탁에 필요한 비용의 전부 또는 일부를 국가가 부담하기로 결정하고 위탁을 할 수 있다. 다만, 「국민건강보험법」ㆍ「의료급여법」 기타 다른 법령의 적용을 받아 정신질환자 또는 그 보호의무자가 부담하지 아니하는 비용을 제외한다.', 1442);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2563, '① 수탁기관의 장은 위탁종료 시 법원에 구체적인 산출근거를 상세히 기재한 비용산정서 및 청구서를 제출하여야 한다.', 1443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2564, '② 판사는 수탁기관의 장이 제출한 비용산정서 기타 구체적 사정을 고려하여 위탁비용을 결정한다.', 1443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2565, '③ 판사가 위탁비용을 지급하게 할 경우에는 비용청구서의 적당한 여백에 결정된 비용을 기재하고 날인한 다음 이를 사건담임자에게 교부한다.', 1443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2566, '④ 제3항에 따라 판사로부터 비용청구서를 교부받은 사건담임자는 바로 이를 회계관계공무원에게 보내는 방식으로 지급의뢰를 하여야 한다. <신설 2024.1.25>', 1443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2567, '⑤ 제4항에 따라 비용청구서를 받은 회계관계공무원은 특별한 사정이 없는 한 30일 이내에 위탁비용을 입금한다. <신설 2024.1.25>', 1443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2568, '⑥ 제5항의 기간 내에 위탁비용을 입금하지 못하는 경우 회계관계공무원은 사건번호, 수탁기관의 기관명, 위탁종료일 및 지급의뢰일, 미지급한 위탁비용 상당의 금액, 입금지연사유를 법원행정처장에게 보고하여야 한다. <신설 2024.1.25>', 1443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2569, '① 법 제21조제1항의 규정에 의한 임시조치의 집행지휘는 결정서 등본을 그 집행담당자에게 교부함으로써 한다.', 1444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2570, '② 판사는 조사관으로 하여금 법 제19조제1항 각 호의 임시조치에 관한 집행상황을 보고하게 할 수 있다.', 1444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2571, '③ 법 제19조제1항제7호의 임시조치 결정은 결정한 때로부터 3개월이 경과하면 집행에 착수하지 못한다.', 1444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2572, '④ 유치시설의 장은 행위자를 유치한 때와 그 집행을 종료한 때에는 수용통보서 또는 석방통보서에 의하여 지체 없이 법원에 그 사실을 통보하여야 한다.', 1444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2573, '⑤ 법 제19조제1항제7호에 따라 행위자를 유치시설에 유치함에 있어서는 「형의 집행 및 수용자의 처우에 관한 법률」 중 미결수용자에 대한 수용절차에 의한다.', 1444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2574, '① 법 제21조제3항, 제22조제1항, 제2항 및 제4항에 따른 임시조치의 취소ㆍ변경ㆍ연장의 신청 및 청구는 서면으로 하고 그 신청서 및 청구서에는 임시조치를 취소ㆍ변경ㆍ연장할 상당한 이유를 기재하고 이를 소명하여야 한다. <개정 2020.9.28, 2025.5.30>', 1445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2575, '② 판사는 임시조치를 취소ㆍ변경ㆍ연장함에 있어 필요하다고 인정하는 때에는 행위자ㆍ피해아동등ㆍ가정구성원 기타 참고인을 소환하여 필요한 사항을 조사ㆍ심리할 수 있다. <개정 2020.9.28, 2025.5.30>', 1445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2576, '③ 임시조치의 취소ㆍ변경ㆍ연장은 임시조치 결정이 통지된 때부터 할 수 있다. <개정 2025.2.28, 2025.5.30>', 1445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2577, '④ 제1항의 신청 및 청구에 대하여는 결정을 하고 신청인 및 청구인에게 이를 통지하여야 한다.', 1445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2578, '⑤ 법 제19조제1항제5호 및 제6호의 임시조치 결정이 있은 다음 행위자의 거주지 또는 현재지가 임시조치 결정을 한 법원ㆍ지원의 관할구역 밖으로 변경되었을 경우, 판사는 직권으로 또는 행위자나 수탁기관의 신청에 따라 그 임시조치 결정의 수탁기관을 관할구역 외 법원ㆍ지원의 수탁기관으로 변경할 수 있다. <신설 2025.2.28>', 1445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2579, '① 법 제32조의 규정에 의하여 아동보호사건을 이송하는 경우에 이미 행하여진 임시조치는 그 효력을 잃지 않는다.', 1446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2580, '② 법 제32조에 따른 이송결정시 판사는 법 제19조제1항제5호부터 제7호까지의 위탁ㆍ유치장소를 변경할 수 있다. 이 경우 이 규칙 제32조제1항을 준용한다.', 1446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2581, '① 법 제44조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제31조의 규정에 의한 심리기일 변경청구에는 심리기일의 변경을 필요로 하는 사유와 그 사유가 계속되리라고 예상되는 기간을 명시하여야 하며 진단서 기타의 자료로써 이를 소명하여야 한다.', 1447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2582, '② 제1항의 청구를 기각한 명령은 송달하지 아니한다.', 1447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2583, '① 법정에서의 좌석의 위치에 관하여는 「법정 좌석에 관한 규칙」을 준용하되, 행위자는 피고인 또는 원ㆍ피고석에, 보조인은 변호인석 또는 행위자 옆에, 조사관은 검사 또는 법원사무관등석에 배치한다.', 1448);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2584, '② 판사는 심리기일에 의견진술을 필요로 하는 조사관에게 심리기일에 출석할 것을 명할 수 있다.', 1448);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2585, '③ 행위자가 심리기일에 출석하지 아니한 때에는 심리를 할 수 없다. 다만, 법 제44조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제37조제1항에 따라 불처분 결정으로 종결할 사건의 경우에는 그러하지 아니하다. <개정 2025.2.28>', 1448);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2586, '① 법 제44조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제32조제1항의 규정에 의한 심리의 비공개결정은 이유를 밝혀 고지한다.', 1449);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2587, '② 제1항의 결정을 한 경우에도 판사는 적당하다고 인정되는 자의 방청을 허가할 수 있다.', 1449);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2588, '① 판사가 심리를 함에는 행위자에게 범죄사실의 내용 및 불리한 진술을 거부할 수 있고 이익되는 사실을 진술할 수 있음을 고지하여야 한다.', 1450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2589, '② 동일 행위자에 대한 2개 이상의 아동보호사건 및 관련보호사건은 될 수 있는 한 병합하여 심리하여야 한다.', 1450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2590, '① 법 제44조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제32조제2항 및 제33조제1항의 규정에 의한 신청에 대하여는 결정을 하고 신청인에게 이를 통지하여야 한다.', 1452);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2591, '② 행위자가 범죄사실을 부인하고 타인의 진술조서의 내용을 다투는 경우 법원은 원진술자를 증인으로 신문하여야 한다. 다만, 다른 증거에 비추어 원진술자의 진술이 신빙할 수 있는 상태에서 행하여진 때에는 그러하지 아니하다.', 1452);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2592, '① 심리기일의 절차에 관하여는 참여한 법원사무관등이 심리조서를 작성하여야 한다.', 1454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2593, '② 심리조서에는 다음 사항을 기재하여야 한다. <개정 2025.2.28>', 1454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2594, '③ 심리에 참여한 법원사무관등은 판사의 허가가 있을 때에는 제2항의 기재사항 중 일부를 생략할 수 있다.', 1454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2595, '④ 심리조서에 관하여 이 규칙에 규정하지 않은 사항은 아동보호사건의 성질에 반하지 아니하는 한 「형사소송법」 제48조부터 제59조까지 및 「형사소송규칙」 제29조부터 제41조까지를 준용한다.', 1454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2596, '① 행위자 및 보조인은 심리계속중의 관계서류 또는 증거물을 열람 또는 등사할 수 있다.', 1455);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2597, '② 행위자 및 보조인의 열람 또는 등사에 관하여는 「재판기록 열람ㆍ복사 규칙」 제7조를 준용한다. <개정 2022.2.25>', 1455);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2598, '① 행위자ㆍ보조인 및 피해아동등, 그 법정대리인 또는 변호사는 결정서 또는 결정을 기재한 조서의 등본, 초본 또는 심판에 관한 사항의 증명서의 교부를 법원사무관등에게 청구할 수 있다. 다만, 피해아동, 그 법정대리인 또는 변호사는 그 청구하는 사유를 소명하여야 한다. <개정 2020.9.28>', 1456);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2599, '② 법원사무관등은 제1항의 등본, 초본 또는 증명서를 작성할 때에는 등본, 초본 또는 심판에 관한 사항의 증명서라는 취지를 기재한 후 기명날인하여야 한다.', 1456);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2600, '① 판사가 법 제44조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제37조제1항제1호의 사유로 불처분결정을 함에는 이미 행하여진 임시조치를 취소하여야 한다.', 1457);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2601, '② 판사가 법 제44조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제37조제1항제2호의 사유로 불처분결정을 한 경우에는 위 결정이 확정된 때에 이미 행하여진 임시조치를 취소할 수 있다. 이 경우 행위자가 수탁ㆍ유치기관에 수용 중인 때에는 수탁ㆍ유치기관의 장에게 위 결정을 통지하기 전에 사건을 송치받을 검찰청에 미리 서면, 전화 또는 팩스 그 밖의 신속한 방법으로 통지하여야 한다. <개정 2025.2.28>', 1457);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2602, '① 판사가 법 제36조제1항의 규정에 의하여 보호처분을 한 때에는 이미 행하여진 임시조치는 그 효력을 잃는다.', 1458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2603, '② 보호처분을 고지함에는 항고기간과 항고장 제출법원 및 항고법원을 알려주어야 한다.', 1458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2604, '③ 법 제36조제1항제1호부터 제3호까지의 보호처분을 고지함에는 이를 이행하지 아니할 경우 법 제59조에 따른 처벌을 받을 수 있음을, 법 제36조제1항제4호부터 제8호까지의 보호처분을 고지함에는 위 결정을 이행하지 아니하거나 집행에 응하지 아니할 경우 보호처분이 취소되고 검사에게 송치되거나 법원에 이송될 수 있음을 각 경고하여야 한다.', 1458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2605, '① 사회봉사ㆍ수강명령은 이를 병과할 수 있다.', 1460);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2606, '② 사회봉사ㆍ수강명령이 보호관찰에 병과하여 부과된 때에는 보호관찰기간 내에 이를 집행하여야 한다.', 1460);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2607, '③ 사회봉사ㆍ수강명령ㆍ보호관찰에 관하여는 아동보호사건의 성질에 반하지 아니하는 한 「보호관찰 등에 관한 법률」을 준용한다.', 1460);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2608, '① 법원장ㆍ지원장은 매년 12월 말까지 법 제36조제1항제6호부터 제8호까지의 수탁기관을 지정하여야 한다. <개정 2025.2.28>', 1461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2609, '② 제1항의 수탁기관 지정 및 그 취소에 대하여는 이 규칙 제29조제2항 및 제3항의 규정을 준용한다.', 1461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2610, '③ 행위자의 정신질환ㆍ약물남용 등으로 인하여 치료와 요양이 필요하다고 인정하여 법 제36조제1항제7호의 보호처분을 할 때에는 수탁기관에 수용할 수 있다. 이 경우 이 규칙 제25조제2항 및 제3항을 준용한다.', 1461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2611, '① 법 제36조제6항의 규정에 의한 참고자료의 송부는 그 등본으로써 할 수 있다.', 1463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2612, '② 전항의 참고자료 원본을 송부받은 보호관찰소 또는 수탁기관의 장은 보호처분이 종료 또는 취소된 때에는 즉시 이를 당해법원에 반환하여야 한다.', 1463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2613, '① 판사는 법 제40조제2항에 따라 법 제38조제1항이 정한 집행담당자로 하여금 법 제36조제1항 각 호의 보호처분에 관한 집행상황을 보고하게 할 수 있다. <개정 2016.11.1, 2020.9.28, 2025.2.28>', 1466);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2614, '② 법 제40조제2항에 따라 집행상황 조사를 명받은 조사관은 법 제39조제1항의 규정에 의한 지시사항의 이행여부, 수탁기관의 감호상황 또는 판사가 특히 필요하다고 인정하는 사항을 조사하여 의견을 붙인 서면으로 보고하여야 한다. <개정 2020.9.28>', 1466);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2615, '① 법 제40조제1항ㆍ제41조ㆍ제42조의 규정에 의한 보호처분의 변경ㆍ취소ㆍ종료의 청구는 당해 보호처분을 결정한 법원에 하여야 한다. <개정 2025.2.28>', 1467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2616, '② 제1항의 청구는 서면으로 하여야 하고 그 서면에는 보호처분을 변경ㆍ취소ㆍ종료할 상당한 이유를 기재하고 이를 소명하여야 한다.', 1467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2617, '③ 판사는 보호처분을 변경ㆍ취소ㆍ종료함에 있어 필요하다고 인정하는 때에는 행위자ㆍ피해아동ㆍ가정구성원 기타 참고인을 소환하고, 필요한 사항을 조사, 심리할 수 있으며, 보호처분의 종류를 변경함에 있어 필요하다고 인정하는 때에는 법 제19조제1항 각 호의 임시조치를 할 수 있다. <개정 2016.11.1, 2025.2.28>', 1467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2618, '④ 보호처분의 변경ㆍ취소는 보호처분결정이 고지된 때부터 할 수 있다.', 1467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2619, '⑤ 제1항의 청구에 대하여는 결정을 하고 청구인에게 이를 통지하여야 한다.', 1467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2620, '⑥ 법 제36조제1항제7호 및 제8호의 보호처분 결정이 있은 다음 행위자의 거주지 또는 현재지가 보호처분 결정을 한 법원ㆍ지원의 관할구역 밖으로 변경되었을 경우, 판사는 직권으로 또는 행위자나 수탁기관의 신청에 따라 그 보호처분 결정의 수탁기관을 관할구역 외 법원ㆍ지원의 수탁기관으로 변경할 수 있다. <신설 2025.2.28>', 1467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2621, '① 법정대리인이 있는 행위자 또는 피해아동이 항고를 취하할 때에는 각 그 법정대리인의 동의를 얻어야 한다. 단, 법정대리인의 사망 기타 사유로 인하여 그 동의를 얻을 수 없는 때에는 예외로 한다. <개정 2025.2.28>', 1471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2622, '② 행위자의 법정대리인 또는 보조인은 행위자의 동의를 얻어, 피해아동의 법정대리인 또는 변호사는 피해아동의 동의를 얻어 각 항고를 취하할 수 있다. 단, 피해아동의 나이 기타 사유로 인하여 피해아동의 동의를 얻을 수 없는 때에는 예외로 한다. <개정 2025.2.28>', 1471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2623, '① 법 제19조제1항제6호 및 제7호 또는 제36조제1항제6호 및 제7호에 따라 수탁ㆍ유치기관에 수용 중인 행위자가 항고제기 기간 내에 항고장을 그 기관의 장 또는 그 직무를 대리하는 사람에게 제출한 때에는 항고제기 기간 내에 항고한 것으로 본다. <개정 2025.2.28>', 1472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2624, '② 제1항의 규정에 의하여 항고장을 제출받은 기관의 장 또는 그 대리자는 항고장에 접수연월일을 기재하여 즉시 보호처분결정을 한 법원에 송부하여야 한다.', 1472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2625, '① 항고법원은 항고이유에 기재된 사항에 관하여 조사하여야 한다.', 1473);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2626, '② 항고법원은 법 제45조제1항에 규정된 사유에 관하여는 직권으로 조사할 수 있다.', 1473);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2627, '① 항고법원은 필요한 경우에 사실조사를 할 수 있다.', 1474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2628, '② 제1항의 조사는 이를 합의부원에게 명하거나 가정법원 또는 지방법원과 그 지원의 판사에게 촉탁하여 할 수 있다.', 1474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2629, '① 수탁ㆍ유치기관에 수용 중인 행위자에 대하여 항고법원이 원결정을 취소하고 사건을 원심법원에 환송하거나 다른 관할법원에 이송하는 때에는 수탁ㆍ유치기관의 장에게 결정을 통지하기 전에 사건을 환송 또는 이송받을 법원에 미리 그 결정을 통지하여야 한다. <개정 2025.2.28>', 1475);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2630, '② 수탁ㆍ유치기관의 장이 제1항의 통지를 받은 때에는 즉시 행위자를 환송 또는 이송받을 법원으로 인도하여야 한다.', 1475);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2631, '③ 항고법원으로부터 사건을 환송 또는 이송받은 법원의 판사는 법 제19조제1항 각 호의 임시조치를 할 수 있다.', 1475);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2632, '① 항고법원이 원결정을 파기하고 스스로 임시조치, 불처분 또는 보호처분의 결정을 하는 경우에는 각 그 결정에 관하여 법 및 이 규칙을 준용한다.', 1476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2633, '② 항고법원이 원심법원의 임시조치 및 그 연장ㆍ변경결정을 파기하고 자판하는 경우에는 임시조치를 하지 않는다는 뜻의 결정을 할 수 있다.', 1476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2634, '③ 검사의 청구에 의한 임시조치에 대한 항고가 이유있다고 인정한 때에는 원심법원의 임시조치결정을 파기하고 검사의 청구를 기각한다는 뜻의 결정을 할 수 있다.', 1476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2635, '① 항고법원이 원심의 보호처분결정을 취소하고 스스로 불처분결정을 하는 때에는 원심의 몰수결정 또는 배상명령을 취소하여야 한다. 이 경우 항고법원이 원심의 몰수결정 또는 배상명령을 취소하지 아니한 때에는 이를 취소한 것으로 본다.', 1477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2636, '② 원심에서 법 제44조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」제57조제2항의 규정에 의하여 배상명령을 한 때에는 제1항의 규정을 적용하지 아니한다.', 1477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2637, '① 항고법원으로부터 사건을 환송 또는 이송받은 법원의 판사는 환송 또는 이송받은 사건에 관하여 다시 심리하여야 한다.', 1478);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2638, '② 제1항의 경우에 원결정을 한 판사는 심리에 관여할 수 없다.', 1478);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2639, '① 대법원은 법 제45조제4항에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」제52조의 규정에 의한 재항고의 절차가 법 및 이 규칙의 규정에 위반되거나 재항고이유가 없다고 인정될 때에는 결정으로 재항고를 기각하여야 한다.', 1479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2640, '② 재항고가 이유있다고 인정할 때에는 원결정을 취소하고 사건을 항고법원에 환송하거나 동등한 다른 법원에 이송하여야 한다. 다만, 대법원이 원결정을 파기한 경우에 그 기록 및 항고법원과 제1심 법원이 조사한 증거에 의하여 결정하기 충분하다고 인정한 때에는 사건에 대하여 직접 결정을 할 수 있다. <개정 2025.2.28>', 1479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2641, '① 아동보호사건의 변호사 및 조사ㆍ심리에 관하여 이 규칙이 따로 정하지 아니한 사항에 대해서는 아동보호사건의 성질에 위반되지 아니하는 한 「성폭력범죄 등 사건의 심리ㆍ재판 및 피해자 보호에 관한 규칙」을 준용한다.', 1481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2642, '② 가정법원 및 그 지원에는 증인지원관을 둔다.', 1481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2643, '① 피해아동보호명령의 청구는 서면 또는 말로 할 수 있다.', 1482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2644, '② 서면으로 청구하는 경우에는 청구서에 다음 각 호의 사항을 적고 청구인, 법정대리인이나 보조인이 기명날인 또는 서명하여야 한다. <개정 2022.2.25, 2025.5.30>', 1482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2645, '③ 말로 청구하는 경우에는 법원사무관등의 앞에서 하여야 한다.', 1482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2646, '④ 제3항의 경우에 법원사무관등은 제2항 각 호의 사항을 적은 조서를 작성하고 기명날인하여야 한다.', 1482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2647, '① 법원은 피해아동보호명령사건이 그 관할에 속하지 아니하거나 적정한 조사ㆍ심리를 위하여 필요하다고 인정하는 경우에는 결정으로 그 사건을 즉시 다른 관할법원에 이송하여야 한다.', 1484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2648, '② 법원은 제1항에 따른 이송결정을 한 경우에는 지체 없이 그 사유를 첨부하여 피해아동, 청구인 및 행위자에게 통지하여야 한다.', 1484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2649, '① 피해아동은 그 법정대리인의 동의를 얻어 제1심의 피해아동보호명령의 결정이 있을 때까지 행위자의 동의 없이 청구를 취하할 수 있다. 단, 법정대리인의 사망 기타 사유로 인하여 그 동의를 얻을 수 없는 때에는 예외로 한다.', 1485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2650, '② 피해아동의 법정대리인, 검사, 변호사, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 피해아동의 동의를 얻어 제1심의 피해아동보호명령의 결정이 있을 때까지 행위자의 동의 없이 청구를 취하할 수 있다. 단, 피해아동의 나이 기타 사유로 인하여 그 동의를 얻을 수 없는 때에는 재판장의 허가를 받아 취하할 수 있다. <개정 2022.2.25, 2025.2.28, 2025.5.30>', 1485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2651, '③ 제1항, 제2항의 경우 재판장은 피해아동의 의사 확인 등을 위하여 조사관에게 피해아동에 대한 조사를 명할 수 있다. <신설 2025.2.28>', 1485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2652, '④ 청구의 취하는 서면으로 하여야 한다. 다만, 심리기일에서는 말로 할 수 있다. <개정 2025.2.28>', 1485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2653, '⑤ 청구서를 송달한 뒤에는 취하의 서면을 행위자에게 송달하여야 한다. <개정 2025.2.28>', 1485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2654, '⑥ 제4항 단서의 경우에 행위자가 심리기일에 출석하지 아니한 때에는 그 기일의 조서등본을 송달하여야 한다. <개정 2025.2.28>', 1485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2655, '⑦ 법 제52조제1항에 따른 피해아동에 대한 임시보호명령이 행하여진 이후에 피해아동보호명령 청구가 취하된 경우에는 법원은 피해아동에 대한 임시보호명령을 취소하여야 한다. <개정 2025.2.28>', 1485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2656, '① 법원이 피해아동보호명령사건을 심리할 때에는 직권으로 사실조사 및 필요한 증거조사를 하여야 하며, 언제든지 피해아동 및 행위자, 법정대리인, 보조인, 가정구성원 또는 변호사, 아동보호전문기관의 장 등 그 밖의 참고인을 소환하여 심문할 수 있다.', 1486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2657, '② 조사관은 피해아동ㆍ행위자 및 가정구성원, 변호사, 아동보호전문기관의 장의 출석을 요구하거나 방문하여 면접ㆍ관찰ㆍ심문 등을 할 수 있다. 이 경우 출석요구는 출석요구서의 송달이나 그 밖의 적당한 방법으로 할 수 있다. <개정 2025.2.28>', 1486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2658, '③ 조사관은 제2항에도 불구하고 질병이나 그 밖의 부득이한 사정으로 대면조사를 하기 어려운 경우, 영상 또는 전화 조사 등 적당한 방법으로 면접ㆍ심문 등을 할 수 있다. <신설 2025.2.28>', 1486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2659, '④ 조사관은 다음 각 호의 사항이 필요하다고 인정할 때에는 판사에게 그 의견을 진술할 수 있다. <개정 2025.2.28>', 1486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2660, '⑤ 조사는 다음 각 호의 사항에 관하여 한다. <개정 2025.2.28>', 1486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2661, '① 판사는 가능한 신속하게 심리기일을 지정하고, 피해아동, 청구인 및 행위자를 소환하여야 한다.', 1487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2662, '② 제1항의 심리기일은 보조인에게 통지하여야 한다.', 1487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2663, '① 피해아동ㆍ행위자ㆍ가정구성원, 청구인, 그 밖의 참고인의 소환은 소환장의 송달에 의한다.', 1488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2664, '② 제1항의 소환장에는 사건명, 피해아동, 청구인과 행위자의 성명 및 소환되는 사람의 성명, 피해아동보호명령사건에 관하여 소환되는 뜻, 출석할 일시와 장소 등을 기재하고 판사가 기명날인하여야 한다.', 1488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2665, '③ 행위자에게 제1회 심리기일소환장을 송달할 때에는 피해아동보호명령 청구서 부본을 함께 송달한다. 이 경우 피해아동 및 보조인의 안전에 위협이 될 우려가 있으면 피해아동보호명령 청구서 부본 상의 피해아동 및 보조인의 주거, 주소, 연락처 등 개인정보의 전부 또는 일부를 가리고 송달할 수 있다. <개정 2016.11.1, 2025.2.28>', 1488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2666, '④ 소환장의 송달에 관하여는 제4조제5항을 준용한다. <개정 2016.11.1>', 1488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2667, '① 법정에서의 좌석의 위치에 관하여는 피해아동보호명령사건의 성질에 반하지 아니하는 한 「법정 좌석에 관한 규칙」제2조제2항을 준용한다. 다만, 법원청사 사정상 필요한 경우에는 피해아동보호명령사건의 성질에 반하지 아니하는 한 달리 정할 수 있다.', 1489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2668, '② 판사는 심리기일에 의견진술을 필요로 하는 조사관에게 심리기일에 출석할 것을 명할 수 있다.', 1489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2669, '③ 피해아동보호명령사건의 심리는 피해아동, 청구인 또는 행위자가 심리기일에 출석하지 아니한 때에도 할 수 있다. <개정 2025.2.28>', 1489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2670, '④ 피해아동, 청구인이 제76조에 따라 소환되었음에도 2회에 걸쳐 피해아동, 청구인 모두 출석하지 아니한 때에는 피해아동보호명령 청구를 취하한 것으로 본다. 다만, 제75조제2항에 따라 심리기일을 통지받은 피해아동의 보조인이 출석한 경우에는 예외로 한다. <신설 2025.2.28>', 1489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2671, '① 법 제54조에 따라 피해아동보호명령사건과 아동보호사건을 병합하여 심리한 경우 주문에 피해아동보호명령에 따른 결정과 보호처분에 따른 결정이 구분될 수 있도록 표기하여야 한다.', 1490);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2672, '② 피해아동보호명령과 보호처분은 각 효력에 영향을 미치지 아니한다.', 1490);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2673, '① 심리기일의 절차에 관하여는 참여한 법원사무관등이 심리조서를 작성하여야 한다.', 1493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2674, '② 심리조서에는 다음 사항을 기재하여야 한다.', 1493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2675, '③ 심리에 참여한 법원사무관등은 판사의 허가가 있을 때에는 제2항의 기재사항 중 일부를 생략할 수 있다.', 1493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2676, '④ 심리조서에 관하여 이 규칙에 규정하지 않은 사항은 피해아동보호명령사건의 성질에 반하지 아니하는 한 「형사소송법」 제48조부터 제59조까지 및 「형사소송규칙」제29조부터 제41조까지를 준용한다.', 1493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2677, '① 피해아동, 청구인, 행위자 및 보조인은 판사의 허가를 받은 경우에만 심리계속 중의 관계 서류 또는 증거물을 열람 또는 등사할 수 있다.', 1494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2678, '② 피해아동보호명령사건이 아동보호사건과 병합되어 심리되는 경우에 병합 이후 편철된 기록에 대한 열람ㆍ등사는 제43조를 준용한다.', 1494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2679, '① 피해아동, 청구인, 행위자 및 보조인은 결정서 또는 결정을 기재한 조서의 등본, 초본 또는 심판에 관한 사항의 증명서의 교부를 법원사무관등에게 청구할 수 있다.', 1495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2680, '② 법원사무관등은 제1항의 등본, 초본 또는 증명서를 작성할 때에는 등본, 초본 또는 심판에 관한 사항의 증명서라는 취지를 기재한 후 기명날인하여야 한다.', 1495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2681, '① 판사는 피해아동보호명령사건을 심리한 결과 피해아동보호명령을 할 수 없거나 할 필요가 없다고 인정하는 경우에는 기각결정을 하여야 한다.', 1496);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2682, '② 제1항에 따른 결정을 한 경우에는 이를 피해아동, 청구인 및 행위자에게 통지하여야 한다.', 1496);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2683, '① 피해아동보호명령을 고지함에는 항고기간과 항고장 제출법원 및 항고법원을 알려주어야 한다.', 1498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2684, '② 법 제47조제1항 각 호의 피해아동보호명령을 고지함에는 행위자에게 이를 이행하지 아니할 경우 법 제59조에 따른 처벌을 받을 수 있음을 경고하여야 한다.', 1498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2685, '③ 심리기일에 출석하지 아니한 피해아동, 청구인 및 행위자에 대한 피해아동보호명령결정의 고지는 결정서의 송달에 의한다.', 1498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2686, '① 법원장ㆍ지원장은 매년 12월 말까지 관할구역 또는 인접관할구역 내의 아동복지시설, 장애인복지시설, 의료기관, 아동보호전문기관, 상담소 중에서 법 제47조제1항제4호, 제5호 및 제5호의2의 피해아동보호명령 집행을 위한 수탁기관을 지정하여야 한다. <개정 2018.4.27, 2025.2.28>', 1499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2687, '② 제1항에 따라 수탁기관으로 지정할 시설은 아동이 건강한 사회 구성원으로 성장하도록 보호하기에 적당한 곳이어야 하며, 해당 시설을 수탁기관으로 지정하려면 미리 그 시설의 운영자와 협의하여야 한다. <개정 2025.2.28>', 1499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2688, '③ 법원장ㆍ지원장은 언제든지 조사관이나 법원사무관등으로 하여금 제1항에 따라 지정된 수탁기관이 피해아동을 보호하기에 충분한 시설을 가지고 있는지 여부와 그 운영실태를 조사ㆍ보고하도록 하고, 피해아동 보호에 부적당하다고 인정되는 경우에는 그 지정을 취소할 수 있다. <개정 2025.2.28>', 1499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2689, '④ 법원은 법 제47조제1항제4호, 제5호 또는 제5호의2의 규정에 따른 보호명령을 결정한 경우에는 수탁기관의 장에게 피해아동에 관한 보고서 또는 의견서 제출을 요구할 수 있다. <신설 2016.11.1, 2018.4.27>', 1499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2690, '⑤ 수탁기관의 장은 피해아동이 법 제47조제1항제4호, 제5호 또는 제5호의2의 규정에 따른 보호명령의 집행에 따르지 아니하는 경우에는 보호명령의 이행 실태에 대한 보고서 또는 의견서를 법원에 제출하여야 한다. <신설 2016.11.1, 2018.4.27>', 1499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2691, '⑥ 법원은 제1항의 수탁기관에 그 집행에 관한 비용의 전부 또는 일부를 지급할 수 있다. 다만 「국민건강보험법」, 「의료급여법」이나 그 밖의 다른 법령의 적용을 받아 피해아동 또는 그 보호자가 부담하지 아니하는 비용은 제외한다. <신설 2016.11.1, 2025.2.28>', 1499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2692, '⑦ 제6항 본문에 따른 비용 지급 절차에 관하여는 이 규칙 제31조를 준용한다. <신설 2024.1.25>', 1499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2693, '① 판사는 법 제47조제1항제6호의 가정위탁을 하고자 할 때에는 피해아동의 친족 기타 피해아동과 특별한 연고가 있는 자 또는 아동의 보호를 희망하는 사람(이하 "연고자 등"이라 한다) 중에서 성범죄, 가정폭력, 아동학대, 정신질환 등의 전력이 없고 피해아동의 보호에 적당한 환경을 갖춘 자를 선정하여야 한다. <개정 2025.2.28>', 1500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2694, '② 판사는 제1항에 따라 수탁 연고자 등을 선정할 때에는 연고자 등의 직업, 소득, 성행, 범죄경력, 가정환경, 피해아동의 의사 등을 고려하여야 하고, 미리 연고자 등의 의견을 상당한 방법으로 들어야 한다. <개정 2025.2.28>', 1500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2695, '③ 판사는 제1항에 따라 수탁 연고자 등을 선정할 때에는 시ㆍ도지사ㆍ시장ㆍ군수ㆍ구청장ㆍ아동보호전문기관의 장 및 가정위탁지원센터의 장에게 연고자 등의 추천을 의뢰할 수 있다. <개정 2016.11.1, 2020.9.28, 2025.2.28>', 1500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2696, '① 피해아동보호명령의 집행지휘 또는 집행위임은 결정서 등본을 법 제50조제1항이 정한 집행담당자에게 교부하는 것으로 한다. <개정 2025.2.28>', 1501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2697, '② 판사는 법 제50조제2항에 따라 법 제50조제1항에서 정한 집행담당자로 하여금 피해아동보호명령에 관한 집행상황을 보고하게 할 수 있다. <개정 2020.9.28, 2025.2.28>', 1501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2698, '① 법 제50조제3항에 따른 피해아동보호명령의 취소ㆍ변경 신청과 법 제51조제1항에 따른 피해아동보호명령의 기간 연장 청구는 서면으로 한다. 이 경우 신청서 및 청구서에는 피해아동보호명령의 취소ㆍ변경ㆍ연장이 필요한 이유를 기재하고 그 이유를 소명하여야 한다. <개정 2025.2.28, 2025.5.30>', 1503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2699, '② 판사는 피해아동보호명령을 취소ㆍ변경ㆍ연장할 때 필요하다고 인정하는 경우에는 피해아동ㆍ행위자ㆍ가정구성원, 그 밖의 참고인을 소환하여 필요한 사항을 조사ㆍ심리할 수 있다. <개정 2025.2.28>', 1503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2700, '③ 피해아동보호명령의 취소ㆍ변경ㆍ연장 결정은 피해아동보호명령이 고지된 때부터 할 수 있다. <개정 2025.2.28>', 1503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2701, '④ 제1항의 신청 및 청구에 대한 결정은 피해아동, 신청인, 청구인 및 행위자에게 통지하여야 한다. <개정 2025.2.28, 2025.5.30>', 1503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2702, '⑤ 피해아동보호명령 변경 결정의 집행에 관하여는 제89조를 준용한다. <신설 2025.2.28>', 1503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2703, '⑥ 법 제47조제1항제4호, 제5호 및 제5호의2의 피해아동보호명령이 있은 다음 피해아동의 거주지 또는 현재지가 피해아동보호명령을 한 법원ㆍ지원의 관할구역 밖으로 변경되었을 경우, 판사는 직권으로 또는 피해아동, 그 법정대리인, 변호사나 수탁기관의 신청에 따라 그 피해아동보호명령의 수탁기관을 관할구역 외 법원ㆍ지원의 수탁기관으로 변경할 수 있다. <신설 2025.2.28>', 1503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2704, '① 법 제52조에 따른 피해아동에 대한 임시보호명령의 결정을 한 때에는 피해아동, 청구인 및 행위자에게 그 결정을 통지하여야 한다. <개정 2025.2.28>', 1505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2705, '② 제1항에 따라 결정을 통지할 때에는 항고기간과 항고장 제출법원 및 항고법원을 알려주어야 하고, 행위자에게는 임시보호명령을 이행하지 아니할 경우 법 제59조에 따른 처벌을 받을 수 있음을 경고하여야 한다. <개정 2025.2.28>', 1505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2706, '① 법 제52조제4항에 따른 임시보호명령의 취소ㆍ변경 신청은 서면으로 한다. 이 경우 신청서에는 임시보호명령의 취소ㆍ변경이 필요한 이유를 기재하고 그 이유를 소명하여야 한다. <개정 2025.2.28>', 1509);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2707, '② 판사는 임시보호명령을 취소ㆍ변경할 때 필요하다고 인정하는 경우에는 행위자ㆍ피해아동ㆍ가정구성원, 그 밖의 참고인을 소환하여 필요한 사항을 조사ㆍ심리할 수 있다. <개정 2025.2.28>', 1509);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2708, '③ 임시보호명령의 취소ㆍ변경은 임시보호명령이 통지된 때부터 할 수 있다. <개정 2025.2.28>', 1509);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2709, '④ 제1항의 신청에 대한 결정은 피해아동, 신청인 및 행위자에게 통지하여야 한다. <개정 2025.2.28>', 1509);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2710, '⑤ 임시보호명령 변경 결정의 집행에 관하여는 제89조를 준용한다. <신설 2025.2.28>', 1509);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2711, '⑥ 법 제52조, 제47조제1항제4호, 제5호 및 제5호의2의 임시보호명령이 있은 다음 피해아동의 거주지 또는 현재지가 임시보호명령을 한 법원ㆍ지원의 관할구역 밖으로 변경되었을 경우, 판사는 직권으로 또는 피해아동, 그 법정대리인, 변호사나 수탁기관의 신청에 따라 그 임시보호명령의 수탁기관을 관할구역 외 법원ㆍ지원의 수탁기관으로 변경할 수 있다. <신설 2025.2.28>', 1509);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2712, '① 법 제52조제1항, 제47조제1항제4호ㆍ제5호ㆍ제5호의2 및 제6호의 임시보호명령에 관하여는 이 규칙 제87조 및 제88조를 준용한다. <개정 2018.4.27>', 1510);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2713, '② 법 제52조제1항, 제47조제1항제7호ㆍ제8호의 임시보호명령, 법 제52조제3항의 임시후견인에 관하여는 이 규칙 제26조 및 제27조를 준용한다.', 1510);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2714, '③ 임시보호명령의 이행실태 조사에 관하여 이 규칙 제90조를 준용한다.', 1510);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2715, '① 법정대리인이 있는 행위자 또는 피해아동이 항고를 취하할 때에는 각 그 법정대리인의 동의를 얻어야 한다. 단, 법정대리인의 사망 기타 사유로 인하여 그 동의를 얻을 수 없는 때에는 예외로 한다. <개정 2025.2.28>', 1512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2716, '② 행위자의 법정대리인 또는 보조인은 행위자의 동의를 얻어, 피해아동의 법정대리인, 보조인, 변호사, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 피해아동의 동의를 얻어 각 항고를 취하할 수 있다. 단, 피해아동의 나이 기타 사유로 인하여 피해아동의 동의를 얻을 수 없는 때에는 예외로 한다. <개정 2022.2.25, 2025.2.28>', 1512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2717, '① 항고법원이 원결정을 파기하고 스스로 임시보호명령 또는 피해아동보호명령의 결정을 하는 경우에는 각 그 결정에 관하여 법 및 이 규칙을 준용한다.', 1513);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2718, '② 항고법원이 원심법원의 임시보호명령 및 변경결정을 파기하고 자판하는 경우에는 임시보호명령을 하지 않는다는 뜻의 결정을 할 수 있다.', 1513);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2719, '① 행위자 및 그 보조인은 심리절차를 현저히 지연시키지 않는 범위 안에서 판사의 허가를 받아 배상책임의 유무와 그 범위에 관하여 필요한 증거를 제출할 수 있다.', 1516);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2720, '② 제1항의 허가를 하지 아니한 재판에 대하여는 불복을 신청하지 못한다.', 1516);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2721, '① 법원은 필요한 때에는 언제든지 행위자의 배상책임 유무와 그 범위를 인정함에 필요한 증거를 조사할 수 있다.', 1517);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2722, '② 아동보호사건의 범죄사실을 인정할 증거는 행위자의 배상책임 유무와 그 범위를 인정할 증거로 할 수 있다.', 1517);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2723, '③ 제2항에 규정된 증거 외의 증거를 조사할 경우 증거조사의 방식에 관하여는 「민사소송법」의 관계규정을 따른다.', 1517);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2724, '① 보호처분결정과 따로 배상신청 각하결정을 한 때 및 배상명령을 취소하는 결정을 한 때에는 피해아동, 그 법정대리인, 변호사 또는 피해아동을 보호하고 있는 기관의 장에게 이를 통지하여야 한다.', 1518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2725, '② 배상명령을 한 경우에 행위자로부터 보호처분에 대한 불복 또는 그 포기ㆍ취하ㆍ상소권회복청구가 있는 때에는 그 취지를 피해아동, 그 법정대리인, 변호사 또는 피해아동을 보호하고 있는 기관의 장에게 통지하여야 한다.', 1518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2726, '① 행위자가 배상명령에 대하여만 항고를 제기한 때에는 원심법원은 기록과 증거물을 14일 이내에 항고법원에 송부하여야 한다.', 1519);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2727, '② 제1항의 규정은 행위자가 배상명령 또는 배상명령에 대한 항고기각결정에 대하여 재항고를 제기한 때에 이를 준용한다.', 1519);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2728, '③ 법 제44조에 따라 준용되는 「가정폭력범죄의 처벌 등에 관한 특례법」 제60조제5항의 배상명령은 이를 가집행선고부 배상명령으로 본다.', 1519);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2729, '① 배상명령이 제1심에서 확정된 때에는 제1심 법원사무관등은 그 재판정본을 작성하여야 한다.', 1520);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2730, '② 배상명령이 제1심 이외의 법원에서 확정된 때에는 그 법원의 법원사무관등은 각 심급의 재판정본을 작성하여 지체 없이 제1심 법원에 송부하여야 한다. 다만, 항고법원이 제1심의 배상명령을 변경한 때에는 제1심의 재판정본은 작성하지 아니한다.', 1520);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2731, '③ 제1심 법원은 확정된 배상명령의 재판정본을 영구보존하여야 한다.', 1520);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2732, '① 배상명령이 확정된 때에는 제1심 또는 기록을 보관하고 있는 상급심 법원의 법원사무관등은 「민사집행법」이 규정한 집행력 있는 정본의 부여절차에 의하여 확정된 재판정본을 교부하여야 한다. <개정 2025.2.28>', 1521);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2733, '② 가집행선고부 배상명령이 있는 때에는 기록을 보관하고 있는 법원이 제1항의 규정에 의한 절차에 의하여 재판정본을 교부하여야 한다.', 1521);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2734, '①「성매매알선 등 행위의 처벌에 관한 법률」(이하 "법"이라 한다) 제28조에 따른 신고(고소ㆍ고발을 포함한다. 이하 같다)에 대한 보상금(이하 "보상금"이라 한다)은 그 지급대상자가 해당 사건의 해결에 기여한 공로, 신고로 인한 경제적 손실, 신고대상이 된 범죄에의 관여 여부 등 여러 정황을 참작하여 공정하게 지급하여야 한다. <개정 2011.1.25>', 1524);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2735, '②보상금은 동일한 공로에 대하여 중복하여 지급할 수 없다.', 1524);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2736, '①성매매알선등행위의처벌에관한법률시행령(이하 "영"이라 한다) 제5조제1항의 규정에 의하여 보상금의 지급신청을 하고자 하는 자는 별지 제1호서식에 의한 보상금지급신청서를 관할 지방검찰청 검사장(지청장을 포함한다. 이하 같다)에게 제출하여야 한다.', 1526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2737, '②지방검찰청 검사장은 제1항의 규정에 의한 보상금지급신청서를 접수한 때에는 다음 각호의 서류를 첨부하여 매년 2월과 8월에 일괄하여 검찰총장을 거쳐 법무부장관에게 송부하여야 한다.', 1526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2738, '③지방검찰청 검사장 또는 검찰총장은 접수된 보상금지급신청서를 심사한 결과 흠이 있거나 증빙이 부족하다고 판단되는 때에는 그에 대한 보완을 요구할 수 있고, 보상금 지급액의 산정에 관한 의견을 첨부할 수 있다.', 1526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2739, '①영 제5조제2항 전단의 규정에 의하여 익명 또는 가명으로 보상금의 지급을 신청하는 경우에는 당해 사건의 담당검사의 승인을 얻어야 한다.', 1527);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2740, '②제1항의 규정에 의하여 익명으로 보상금의 지급을 신청하는 경우에는 신청인을 당해 사건의 담당검사로 기재하되, 익명임을 표시하여야 한다.', 1527);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2741, '③제1항의 규정에 의한 담당검사의 승인 및 영 제5조제2항 후단의 규정에 의한 신고를 접수한 기관의 장의 확인은 별지 제1호서식 하단에 의한다.', 1527);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2742, null, 1531);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2743, '① 보상금은 법 제28조제1항에 따라 보상금 지급대상이 되는 범죄(이하 "대상범죄"라 한다)에 대하여 신고를 한 경우에 다음 각 호에서 정한 보상금 상한액의 범위에서 지급한다. <개정 2011.1.25>', 1535);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2744, '②제1항의 규정에 의하여 보상금 액수를 결정함에 있어서 다음 각호의 사항을 참작하여야 한다.', 1535);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2745, '③당해 사건의 해결이 국내외적으로 중요하거나 대형범죄, 조직범죄의 근절 등 범죄진압에 현저히 기여한 경우에는 2천만원을 초과하지 아니하는 범위안에서 제1항의 규정에 의한 지급기준보다 보상금을 증액하여 지급할 수 있다.', 1535);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2746, '④ 삭제 <2011.1.25>', 1535);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2747, '① 삭제 <2011.1.25>', 1537);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2748, '②법무부장관은 보상금 지급결정을 한 경우 별지 제4호서식의 보상금지급결정서를 작성하여야 한다. <개정 2011.1.25>', 1537);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2749, '①제15조제2항의 규정에 의한 보상금지급결정서는 검찰총장을 거쳐 관할 지방검찰청 검사장에게 송부하고, 지방검찰청 검사장은 신청인에게 지체없이 지급결정 사실을 통보하여야 한다.', 1538);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2750, '②보상금은 관할 지방검찰청 검사장이 신청인에게 지급하되, 익명으로 보상금지급신청서가 제출되어 지급결정된 경우에는 신청한 검사가 수령하여 대상자에게 지급한다.', 1538);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2751, '①법무부장관은 지방검찰청 검사장으로부터 신고를 한 자에 대한 보상이 시급하다는 이유로 보상금의 가지급 요청이 있는 때에는 검찰총장의 의견을 참작하여 당해 사건의 종국처분 이전이라도 전년도 지급기준에 의한 예상 보상금 액수의 10분의 8의 범위안에서 보상금을 가지급할 수 있다. 이 경우 별지 각 서식에 준하여 가지급 관련 서류를 작성하되, 가지급금인 사실과 예상보상금 액수, 가지급을 필요로 하는 사유를 기재하여야 한다.', 1539);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2752, '②법무부장관은 보상금 지급사무의 적정을 기하기 위하여 필요하다고 인정하는 때에는 지방검찰청 검사장 및 검찰총장의 의견을 참작하여 판결이 확정될 때까지 그 지급여부 및 보상금 지급액의 결정을 유예할 수 있다. <개정 2011.1.25>', 1539);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2753, '①법무부장관은 지방검찰청 검사장으로 하여금 영 제10조의 규정에 의한 보상금지급조서 및 보상금지급대장을 각각 별지 제5호서식 및 별지 제6호서식에 의하여 작성ㆍ비치하도록 할 수 있다.', 1540);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2754, '②보상금지급조서 및 보상금지급대장에는 수령인이 작성한 영수증이나 보상금을 송금한 예금통장 사본 등 지급 근거 서류를 첨부하여 보존하여야 한다.', 1540);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2755, '①제5조제1항의 규정에 의하여 익명 또는 가명으로 보상금이 신청된 경우에는 그 공로조서, 보상금지급심의서, 보상금지급결정서에는 익명 또는 가명을 기재하고, 주민등록번호 및 주소 등 인적사항을 확인할 수 있는 내용을 기재하여서는 아니된다.', 1541);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2756, '②보상금지급조서 및 보상금지급대장에는 신청인의 실명을 기재하되, 보상금지급신청서에 기재된 익명 또는 가명을 부기하여야 한다.', 1541);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2757, '① 이 법에서 "특정강력범죄"란 다음 각 호의 어느 하나에 해당하는 죄를 말한다. <개정 2010.4.15, 2011.3.7, 2012.12.18, 2013.4.5, 2016.1.6>', 1543);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2758, '② 제1항 각 호의 범죄로서 다른 법률에 따라 가중처벌하는 죄는 특정강력범죄로 본다.', 1543);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2759, '① 특정강력범죄를 범한 당시 18세 미만인 소년을 사형 또는 무기형에 처하여야 할 때에는 「소년법」 제59조에도 불구하고 그 형을 20년의 유기징역으로 한다.', 1545);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2760, '② 특정강력범죄를 범한 소년에 대하여 부정기형(不定期刑)을 선고할 때에는 「소년법」 제60조제1항 단서에도 불구하고 장기는 15년, 단기는 7년을 초과하지 못한다.', 1545);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2761, '① 검사는 특정강력범죄사건의 증인이 피고인 또는 그 밖의 사람으로부터 생명ㆍ신체에 해를 입거나 입을 염려가 있다고 인정될 때에는 관할 경찰서장에게 증인의 신변안전을 위하여 필요한 조치를 할 것을 요청하여야 한다.', 1548);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2762, '② 증인은 검사에게 제1항의 조치를 하도록 청구할 수 있다.', 1548);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2763, '③ 재판장은 검사에게 제1항의 조치를 하도록 요청할 수 있다.', 1548);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2764, '④ 제1항의 요청을 받은 관할 경찰서장은 즉시 증인의 신변안전을 위하여 필요한 조치를 하고 그 사실을 검사에게 통보하여야 한다.', 1548);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2765, '① 법원은 특정강력범죄에 관하여 검사 및 변호인과 공판기일의 지정이나 그 밖에 소송의 진행에 필요한 사항을 협의할 수 있다.', 1551);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2766, '② 제1항의 협의는 소송 진행에 필요한 최소한의 범위에서 하여야 하며, 판결에 영향을 주어서는 아니 된다.', 1551);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2767, '③ 특정강력범죄에 관하여 증거서류 또는 증거물의 조사를 청구하는 경우에는 상대방에게 미리 열람할 기회를 주어야 한다. 다만, 상대방이 이의를 제기하지 아니하는 경우에는 그러하지 아니하다.', 1551);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2768, '① 법원은 특정강력범죄사건의 심리를 하는 데에 2일 이상이 걸리는 경우에는 가능하면 매일 계속 개정(開廷)하여 집중심리(集中審理)를 하여야 한다.', 1552);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2769, '② 재판장은 특별한 사정이 없으면 직전 공판기일부터 7일 이내로 다음 공판기일을 지정하여야 한다.', 1552);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2770, '③ 재판장은 소송 관계인이 공판기일을 준수하도록 요청하여야 하며, 이에 필요한 조치를 할 수 있다.', 1552);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2771, '① 특정강력범죄의 피고인이 공판정에서 공소사실을 자백한 경우에는 법원은 간이공판절차에 따라 심판할 것을 결정할 수 있다. 특정강력범죄와 다른 죄가 병합(倂合)된 경우에도 같다.', 1554);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2772, '② 제1항의 결정이 있는 사건에 대하여는 「형사소송법」 제286조의3, 제297조의2, 제301조의2 및 제318조의3을 준용한다.', 1554);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2773, null, 1557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2774, '① 법원은 가정폭력행위자에 대하여 유죄판결(선고유예는 제외한다)을 선고하거나 약식명령을 고지하는 경우에는 200시간의 범위에서 재범예방에 필요한 수강명령(「보호관찰 등에 관한 법률」에 따른 수강명령을 말한다. 이하 같다) 또는 가정폭력 치료프로그램의 이수명령(이하 "이수명령"이라 한다)을 병과할 수 있다.', 1559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2775, '② 가정폭력행위자에 대하여 제1항의 수강명령은 형의 집행을 유예할 경우에 그 집행유예기간 내에서 병과하고, 이수명령은 징역형의 실형 또는 벌금형을 선고하거나 약식명령을 고지할 경우에 병과한다.', 1559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2776, '③ 법원이 가정폭력행위자에 대하여 형의 집행을 유예하는 경우에는 제1항에 따른 수강명령 외에 그 집행유예기간 내에서 보호관찰 또는 사회봉사 중 하나 이상의 처분을 병과할 수 있다.', 1559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2777, '④ 제1항에 따른 수강명령 또는 이수명령은 형의 집행을 유예할 경우에는 그 집행유예기간 내에, 징역형의 실형을 선고할 경우에는 형기 내에, 벌금형을 선고하거나 약식명령을 고지할 경우에는 형 확정일부터 6개월 이내에 각각 집행한다.', 1559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2778, '⑤ 제1항에 따른 수강명령 또는 이수명령이 형의 집행유예 또는 벌금형과 병과된 경우에는 보호관찰소의 장이 집행하고, 징역형의 실형과 병과된 경우에는 교정시설의 장이 집행한다. 다만, 징역형의 실형과 병과된 이수명령을 모두 이행하기 전에 석방 또는 가석방되거나 미결구금일수 산입 등의 사유로 형을 집행할 수 없게 된 경우에는 보호관찰소의 장이 남은 이수명령을 집행한다.', 1559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2779, '⑥ 제1항에 따른 수강명령 또는 이수명령은 다음 각 호의 내용으로 한다.', 1559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2780, '⑦ 형벌과 병과하는 보호관찰, 사회봉사, 수강명령 및 이수명령에 관하여 이 법에서 규정한 사항 외에는 「보호관찰 등에 관한 법률」을 준용한다.', 1559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2781, '① 누구든지 가정폭력범죄를 알게 된 경우에는 수사기관에 신고할 수 있다.', 1560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2782, '② 다음 각 호의 어느 하나에 해당하는 사람이 직무를 수행하면서 가정폭력범죄를 알게 된 경우에는 정당한 사유가 없으면 즉시 수사기관에 신고하여야 한다. <개정 2012.1.17, 2014.12.30>', 1560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2783, '③ 「아동복지법」에 따른 아동상담소, 「가정폭력방지 및 피해자보호 등에 관한 법률」에 따른 가정폭력 관련 상담소 및 보호시설, 「성폭력방지 및 피해자보호 등에 관한 법률」에 따른 성폭력피해상담소 및 보호시설(이하 "상담소등"이라 한다)에 근무하는 상담원과 그 기관장은 피해자 또는 피해자의 법정대리인 등과의 상담을 통하여 가정폭력범죄를 알게 된 경우에는 가정폭력피해자의 명시적인 반대의견이 없으면 즉시 신고하여야 한다. <개정 2012.1.17, 2017.10.31>', 1560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2784, '④ 누구든지 제1항부터 제3항까지의 규정에 따라 가정폭력범죄를 신고한 사람(이하 "신고자"라 한다)에게 그 신고행위를 이유로 불이익을 주어서는 아니 된다.', 1560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2785, null, 1561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2786, '① 피해자 또는 그 법정대리인은 가정폭력행위자를 고소할 수 있다. 피해자의 법정대리인이 가정폭력행위자인 경우 또는 가정폭력행위자와 공동으로 가정폭력범죄를 범한 경우에는 피해자의 친족이 고소할 수 있다.', 1562);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2787, '② 피해자는 「형사소송법」 제224조에도 불구하고 가정폭력행위자가 자기 또는 배우자의 직계존속인 경우에도 고소할 수 있다. 법정대리인이 고소하는 경우에도 또한 같다.', 1562);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2788, '③ 피해자에게 고소할 법정대리인이나 친족이 없는 경우에 이해관계인이 신청하면 검사는 10일 이내에 고소할 수 있는 사람을 지정하여야 한다.', 1562);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2789, '① 검사는 가정폭력범죄가 재발될 우려가 있다고 인정하는 경우에는 직권으로 또는 사법경찰관의 신청에 의하여 법원에 제29조제1항제1호ㆍ제2호 또는 제3호의 임시조치를 청구할 수 있다.', 1564);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2790, '② 검사는 가정폭력행위자가 제1항의 청구에 의하여 결정된 임시조치를 위반하여 가정폭력범죄가 재발될 우려가 있다고 인정하는 경우에는 직권으로 또는 사법경찰관의 신청에 의하여 법원에 제29조제1항제5호의 임시조치를 청구할 수 있다.', 1564);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2791, '③ 제1항 및 제2항의 경우 피해자 또는 그 법정대리인은 검사 또는 사법경찰관에게 제1항 및 제2항에 따른 임시조치의 청구 또는 그 신청을 요청하거나 이에 관하여 의견을 진술할 수 있다.', 1564);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2792, '④ 제3항에 따른 요청을 받은 사법경찰관은 제1항 및 제2항에 따른 임시조치를 신청하지 아니하는 경우에는 검사에게 그 사유를 보고하여야 한다.', 1564);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2793, '① 사법경찰관은 제5조에 따른 응급조치에도 불구하고 가정폭력범죄가 재발될 우려가 있고, 긴급을 요하여 법원의 임시조치 결정을 받을 수 없을 때에는 직권 또는 피해자나 그 법정대리인의 신청에 의하여 제29조제1항제1호부터 제3호까지의 어느 하나에 해당하는 조치(이하 "긴급임시조치"라 한다)를 할 수 있다.', 1565);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2794, '② 사법경찰관은 제1항에 따라 긴급임시조치를 한 경우에는 즉시 긴급임시조치결정서를 작성하여야 한다.', 1565);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2795, '③ 제2항에 따른 긴급임시조치결정서에는 범죄사실의 요지, 긴급임시조치가 필요한 사유 등을 기재하여야 한다.', 1565);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2796, '① 사법경찰관이 제8조의2제1항에 따라 긴급임시조치를 한 때에는 지체 없이 검사에게 제8조에 따른 임시조치를 신청하고, 신청받은 검사는 법원에 임시조치를 청구하여야 한다. 이 경우 임시조치의 청구는 긴급임시조치를 한 때부터 48시간 이내에 청구하여야 하며, 제8조의2제2항에 따른 긴급임시조치결정서를 첨부하여야 한다.', 1566);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2797, '② 제1항에 따라 임시조치를 청구하지 아니하거나 법원이 임시조치의 결정을 하지 아니한 때에는 즉시 긴급임시조치를 취소하여야 한다.', 1566);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2798, '① 검사는 가정폭력범죄로서 사건의 성질ㆍ동기 및 결과, 가정폭력행위자의 성행 등을 고려하여 이 법에 따른 보호처분을 하는 것이 적절하다고 인정하는 경우에는 가정보호사건으로 처리할 수 있다. 이 경우 검사는 피해자의 의사를 존중하여야 한다.', 1567);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2799, '② 다음 각 호의 경우에는 제1항을 적용할 수 있다.', 1567);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2800, '① 가정보호사건의 관할은 가정폭력행위자의 행위지, 거주지 또는 현재지를 관할하는 가정법원으로 한다. 다만, 가정법원이 설치되지 아니한 지역에서는 해당 지역의 지방법원(지원을 포함한다. 이하 같다)으로 한다.', 1569);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2801, '② 가정보호사건의 심리와 결정은 단독판사(이하 "판사"라 한다)가 한다.', 1569);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2802, '① 검사는 제9조에 따라 가정보호사건으로 처리하는 경우에는 그 사건을 관할 가정법원 또는 지방법원(이하 "법원"이라 한다)에 송치하여야 한다.', 1570);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2803, '② 검사는 가정폭력범죄와 그 외의 범죄가 경합(競合)하는 경우에는 가정폭력범죄에 대한 사건만을 분리하여 관할 법원에 송치할 수 있다.', 1570);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2804, '① 제11조제1항 또는 제12조에 따른 송치결정이 있는 경우 가정폭력행위자를 구금하고 있는 시설의 장은 검사의 이송지휘를 받은 때부터 제10조에 따른 관할 법원이 있는 시(특별시, 광역시 및 「제주특별자치도 설치 및 국제자유도시 조성을 위한 특별법」 제10조제2항에 따른 행정시를 포함한다. 이하 같다)ㆍ군에서는 24시간 이내에, 그 밖의 시ㆍ군에서는 48시간 이내에 가정폭력행위자를 관할 법원에 인도하여야 한다. 이 경우 법원은 가정폭력행위자에 대하여 제29조에 따른 임시조치 여부를 결정하여야 한다. <개정 2015.7.24>', 1572);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2805, '② 제1항에 따른 인도와 결정은 「형사소송법」 제92조, 제203조 또는 제205조의 구속기간 내에 이루어져야 한다.', 1572);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2806, '③ 구속영장의 효력은 제1항 후단에 따라 임시조치 여부를 결정한 때에 상실된 것으로 본다.', 1572);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2807, '① 제11조 및 제12조에 따라 사건을 가정보호사건으로 송치하는 경우에는 송치서를 보내야 한다.', 1573);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2808, '② 제1항의 송치서에는 가정폭력행위자의 성명, 주소, 생년월일, 직업, 피해자와의 관계 및 행위의 개요와 가정 상황을 적고 그 밖의 참고자료를 첨부하여야 한다.', 1573);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2809, '① 가정보호사건을 송치받은 법원은 사건이 그 관할에 속하지 아니하거나 적정한 조사ㆍ심리를 위하여 필요하다고 인정하는 경우에는 결정으로 그 사건을 즉시 다른 관할 법원에 이송하여야 한다.', 1574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2810, '② 법원은 제1항에 따른 이송결정을 한 경우에는 지체 없이 그 사유를 첨부하여 가정폭력행위자와 피해자 및 검사에게 통지하여야 한다.', 1574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2811, '① 가정폭력범죄에 대한 공소시효는 해당 가정보호사건이 법원에 송치된 때부터 시효 진행이 정지된다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그 때부터 진행된다.', 1576);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2812, '② 공범 중 1명에 대한 제1항의 시효정지는 다른 공범자에게도 효력을 미친다.', 1576);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2813, '① 가정폭력범죄의 수사 또는 가정보호사건의 조사ㆍ심리 및 그 집행을 담당하거나 이에 관여하는 공무원, 보조인, 상담소등에 근무하는 상담원과 그 기관장 및 제4조제2항제1호에 규정된 사람(그 직에 있었던 사람을 포함한다)은 그 직무상 알게 된 비밀을 누설하여서는 아니 된다.', 1577);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2814, '② 이 법에 따른 가정보호사건에 대하여는 가정폭력행위자, 피해자, 고소인, 고발인 또는 신고인의 주소, 성명, 나이, 직업, 용모, 그 밖에 이들을 특정하여 파악할 수 있는 인적 사항이나 사진 등을 신문 등 출판물에 싣거나 방송매체를 통하여 방송할 수 없다.', 1577);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2815, '③ 피해자가 보호하고 있는 아동이나 피해자인 아동의 교육 또는 보육을 담당하는 학교의 교직원 또는 보육교직원은 정당한 사유가 없으면 해당 아동의 취학, 진학, 전학 또는 입소(그 변경을 포함한다)의 사실을 가정폭력행위자인 친권자를 포함하여 누구에게든지 누설하여서는 아니 된다. <개정 2011.6.7>', 1577);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2816, '① 가정보호사건을 조사ㆍ심리하기 위하여 법원에 가정보호사건조사관을 둔다.', 1580);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2817, '② 가정보호사건조사관의 자격, 임면(任免), 그 밖에 필요한 사항은 대법원규칙으로 정한다.', 1580);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2818, '① 판사는 가정보호사건조사관, 그 법원의 소재지 또는 가정폭력행위자의 주거지를 관할하는 보호관찰소의 장에게 가정폭력행위자, 피해자 및 가정구성원에 대한 심문(審問)이나 그들의 정신ㆍ심리상태, 가정폭력범죄의 동기ㆍ원인 및 실태 등의 조사를 명하거나 요구할 수 있다.', 1581);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2819, '② 제1항에 따라 판사가 보호관찰소의 장에게 하는 조사요구에 관하여는 「보호관찰 등에 관한 법률」 제19조제2항 및 제3항을 준용한다.', 1581);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2820, '① 법원은 정신건강의학과의사, 심리학자, 사회학자, 사회복지학자, 그 밖의 관련 전문가에게 가정폭력행위자, 피해자 또는 가정구성원의 정신ㆍ심리상태에 대한 진단소견 및 가정폭력범죄의 원인에 관한 의견을 조회할 수 있다. <개정 2011.8.4>', 1582);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2821, '② 법원은 가정보호사건을 조사ㆍ심리할 때 제1항에 따른 의견 조회의 결과를 고려하여야 한다.', 1582);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2822, '① 판사는 조사ㆍ심리에 필요하다고 인정하는 경우에는 기일을 지정하여 가정폭력행위자, 피해자, 가정구성원, 그 밖의 참고인을 소환할 수 있다.', 1584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2823, '② 판사는 가정폭력행위자가 정당한 이유 없이 제1항에 따른 소환에 응하지 아니하는 경우에는 동행영장을 발부할 수 있다.', 1584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2824, '① 동행영장은 가정보호사건조사관이나 법원의 법원서기관ㆍ법원사무관ㆍ법원주사ㆍ법원주사보(이하 "법원공무원"이라 한다) 또는 사법경찰관리로 하여금 집행하게 할 수 있다.', 1587);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2825, '② 법원은 가정폭력행위자의 소재가 분명하지 아니하여 1년 이상 동행영장을 집행하지 못한 경우 사건을 관할 법원에 대응하는 검찰청 검사에게 송치할 수 있다.', 1587);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2826, '③ 법원은 동행영장을 집행한 경우에는 그 사실을 즉시 가정폭력행위자의 법정대리인 또는 보조인에게 통지하여야 한다.', 1587);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2827, '① 가정폭력행위자는 자신의 가정보호사건에 대하여 보조인을 선임(選任)할 수 있다.', 1588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2828, '② 변호사, 가정폭력행위자의 법정대리인ㆍ배우자ㆍ직계친족ㆍ형제자매, 상담소등의 상담원과 그 기관장은 보조인이 될 수 있다. 다만, 변호사가 아닌 사람을 보조인으로 선임하려면 법원의 허가를 받아야 한다.', 1588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2829, '③ 제2항에 따라 선임된 변호사가 아닌 보조인은 금품, 향응, 그 밖의 이익을 받거나 받을 것을 약속하거나 제3자에게 이를 제공하게 하거나 제공하게 할 것을 약속하여서는 아니 된다.', 1588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2830, '④ 법원은 가정폭력행위자가 「형사소송법」 제33조제1항 각 호의 어느 하나에 해당하는 경우에는 직권으로 변호사를 가정폭력행위자의 보조인으로 선임할 수 있다.', 1588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2831, '⑤ 제4항에 따라 선임된 보조인에게 지급하는 비용에 대하여는 「형사소송비용 등에 관한 법률」을 준용한다.', 1588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2832, '① 판사는 가정보호사건의 원활한 조사ㆍ심리 또는 피해자 보호를 위하여 필요하다고 인정하는 경우에는 결정으로 가정폭력행위자에게 다음 각 호의 어느 하나에 해당하는 임시조치를 할 수 있다. <개정 2020.10.20>', 1589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2833, '② 동행영장에 의하여 동행한 가정폭력행위자 또는 제13조에 따라 인도된 가정폭력행위자에 대하여는 가정폭력행위자가 법원에 인치된 때부터 24시간 이내에 제1항의 조치 여부를 결정하여야 한다.', 1589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2834, '③ 법원은 제1항에 따른 조치를 결정한 경우에는 검사와 피해자에게 통지하여야 한다.', 1589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2835, '④ 법원은 제1항제4호 또는 제5호의 조치를 한 경우에는 그 사실을 가정폭력행위자의 보조인이 있는 경우에는 보조인에게, 보조인이 없는 경우에는 법정대리인 또는 가정폭력행위자가 지정한 사람에게 통지하여야 한다. 이 경우 제1항제5호의 조치를 하였을 때에는 가정폭력행위자에게 변호사 등 보조인을 선임할 수 있으며 제49조제1항의 항고를 제기할 수 있음을 고지하여야 한다.', 1589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2836, '⑤ 제1항제1호부터 제3호까지의 임시조치기간은 2개월, 같은 항 제4호부터 제6호까지의 임시조치기간은 1개월을 초과할 수 없다. 다만, 피해자의 보호를 위하여 그 기간을 연장할 필요가 있다고 인정하는 경우에는 결정으로 제1항제1호부터 제3호까지의 임시조치는 두 차례만, 같은 항 제4호부터 제6호까지의 임시조치는 한 차례만 각 기간의 범위에서 연장할 수 있다. <개정 2020.10.20>', 1589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2837, '⑥ 제1항제4호의 위탁을 하는 경우에는 의료기관 등의 장에게 가정폭력행위자를 보호하는 데에 필요한 사항을 부과할 수 있다.', 1589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2838, '⑦ 민간이 운영하는 의료기관 등에 위탁하려는 경우에는 제6항에 따라 부과할 사항을 그 의료기관 등의 장에게 미리 고지하고 동의를 받아야 한다.', 1589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2839, '⑧ 제1항제6호에 따른 상담을 한 상담소등의 장은 그 결과보고서를 판사와 검사에게 제출하여야 한다. <신설 2020.10.20>', 1589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2840, '⑨ 판사는 제1항 각 호에 규정된 임시조치의 결정을 한 경우에는 가정보호사건조사관, 법원공무원, 사법경찰관리 또는 구치소 소속 교정직공무원으로 하여금 집행하게 할 수 있다. <개정 2020.10.20>', 1589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2841, '⑩ 가정폭력행위자, 그 법정대리인이나 보조인은 제1항에 따른 임시조치 결정의 취소 또는 그 종류의 변경을 신청할 수 있다. <개정 2020.10.20>', 1589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2842, '⑪ 판사는 직권으로 또는 제10항에 따른 신청에 정당한 이유가 있다고 인정하는 경우에는 결정으로 해당 임시조치를 취소하거나 그 종류를 변경할 수 있다. <개정 2020.10.20>', 1589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2843, '⑫ 제1항제4호 및 제6호의 위탁의 대상이 되는 의료기관, 요양소 및 상담소등의 기준과 그 밖에 필요한 사항은 대법원규칙으로 정한다. <개정 2020.10.20>', 1589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2844, '① 제29조제9항에 따라 임시조치 결정을 집행하는 사람은 가정폭력행위자에게 임시조치의 내용, 불복방법 등을 고지하여야 한다. <개정 2020.10.20>', 1590);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2845, '② 피해자 또는 가정구성원은 제29조제1항제1호 및 제2호의 임시조치 후 주거나 직장 등을 옮긴 경우에는 관할 법원에 임시조치 결정의 변경을 신청할 수 있다.', 1590);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2846, '① 판사는 심리기일을 지정하고 가정폭력행위자를 소환하여야 한다. 이 경우 판사는 가정보호사건의 요지 및 보조인을 선임할 수 있다는 취지를 미리 고지하여야 한다.', 1591);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2847, '② 제1항의 심리기일은 보조인과 피해자에게 통지하여야 한다.', 1591);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2848, '① 판사는 가정보호사건을 심리할 때 사생활 보호나 가정의 평화와 안정을 위하여 필요하거나 선량한 풍속을 해칠 우려가 있다고 인정하는 경우에는 결정으로 심리를 공개하지 아니할 수 있다.', 1593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2849, '② 증인으로 소환된 피해자 또는 가정구성원은 사생활 보호나 가정의 평화와 안정의 회복을 이유로 하여 판사에게 증인신문(證人訊問)의 비공개를 신청할 수 있다. 이 경우 판사는 그 허가 여부와 공개법정 외의 장소에서의 신문 등 증인신문의 방식 및 장소에 관하여 결정을 할 수 있다.', 1593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2850, '① 법원은 피해자가 신청하는 경우에는 그 피해자를 증인으로 신문하여야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그러하지 아니하다.', 1594);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2851, '② 법원은 제1항에 따라 피해자를 신문하는 경우에는 해당 가정보호사건에 관한 의견을 진술할 기회를 주어야 한다.', 1594);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2852, '③ 법원은 심리를 할 때에 필요하다고 인정하는 경우에는 피해자 또는 가정보호사건조사관에게 의견 진술 또는 자료 제출을 요구할 수 있다. 이 경우 판사는 공정한 의견 진술 등을 위하여 필요하다고 인정할 때에는 가정폭력행위자의 퇴장을 명할 수 있다.', 1594);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2853, '④ 제1항부터 제3항까지의 경우 피해자는 변호사, 법정대리인, 배우자, 직계친족, 형제자매, 상담소등의 상담원 또는 그 기관장으로 하여금 대리하여 의견을 진술하게 할 수 있다.', 1594);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2854, '⑤ 제1항에 따른 신청인이 소환을 받고도 정당한 이유 없이 출석하지 아니한 경우에는 그 신청을 철회한 것으로 본다.', 1594);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2855, '① 법원은 증인을 신문하고 감정(鑑定)을 명하며 통역 또는 번역을 하게 할 수 있다.', 1595);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2856, '② 제1항의 경우에는 가정보호사건의 성질에 위배되지 아니하는 범위에서 「형사소송법」 중 법원의 증인신문과 감정, 통역 및 번역에 관한 규정을 준용한다.', 1595);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2857, '③ 증인, 감정인, 통역인, 번역인에게 지급하는 비용, 숙박료, 그 밖의 비용에 대하여는 「형사소송법」 중 비용에 관한 규정 및 「형사소송비용 등에 관한 법률」을 준용한다.', 1595);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2858, '① 법원은 검증, 압수 및 수색을 할 수 있다.', 1596);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2859, '② 제1항의 경우에는 가정보호사건의 성질에 위배되지 아니하는 범위에서 「형사소송법」 중 법원의 검증, 압수 및 수색에 관한 규정을 준용한다.', 1596);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2860, '① 법원은 가정보호사건의 조사ㆍ심리에 필요한 경우 관계 행정기관, 상담소등 또는 의료기관, 그 밖의 단체에 협조와 원조를 요청할 수 있다.', 1597);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2861, '② 제1항의 요청을 받은 관계 행정기관, 상담소등 또는 의료기관, 그 밖의 단체가 그 요청을 거부할 때에는 정당한 이유를 제시하여야 한다.', 1597);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2862, '① 판사는 가정보호사건을 심리한 결과 다음 각 호의 어느 하나에 해당하는 경우에는 처분을 하지 아니한다는 결정을 하여야 한다.', 1598);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2863, '② 법원은 제1항제2호의 사유로 처분을 하지 아니한다는 결정을 한 경우에는 다음 각 호의 구분에 따라 처리하여야 한다.', 1598);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2864, '③ 제1항에 따른 결정을 한 경우에는 이를 가정폭력행위자, 피해자 및 검사에게 통지하여야 한다.', 1598);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2865, '① 판사는 심리의 결과 보호처분이 필요하다고 인정하는 경우에는 결정으로 다음 각 호의 어느 하나에 해당하는 처분을 할 수 있다. <개정 2022.12.13>', 1601);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2866, '② 제1항 각 호의 처분은 병과(倂科)할 수 있다.', 1601);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2867, '③ 제1항제3호의 처분을 하는 경우에는 피해자를 다른 친권자나 친족 또는 적당한 시설로 인도할 수 있다.', 1601);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2868, '④ 법원은 보호처분의 결정을 한 경우에는 지체 없이 그 사실을 검사, 가정폭력행위자, 피해자, 보호관찰관 및 보호처분을 위탁받아 하는 보호시설, 의료기관 또는 상담소등(이하 "수탁기관"이라 한다)의 장에게 통지하여야 한다. 다만, 수탁기관이 민간에 의하여 운영되는 기관인 경우에는 그 기관의 장으로부터 수탁에 대한 동의를 받아야 한다.', 1601);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2869, '⑤ 제1항제4호부터 제8호까지의 처분을 한 경우에는 가정폭력행위자의 교정에 필요한 참고자료를 보호관찰관 또는 수탁기관의 장에게 보내야 한다.', 1601);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2870, '⑥ 제1항제6호의 감호위탁기관은 가정폭력행위자에 대하여 그 성행을 교정하기 위한 교육을 하여야 한다.', 1601);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2871, '① 법원은 가정보호사건조사관, 법원공무원, 사법경찰관리, 보호관찰관 또는 수탁기관 소속 직원으로 하여금 보호처분의 결정을 집행하게 할 수 있다.', 1604);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2872, '② 보호처분의 집행에 관하여 이 법에서 정하지 아니한 사항에 대하여는 가정보호사건의 성질에 위배되지 아니하는 범위에서 「형사소송법」, 「보호관찰 등에 관한 법률」 및 「정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률」을 준용한다. <개정 2016.5.29>', 1604);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2873, '① 법원은 보호처분이 진행되는 동안 필요하다고 인정하는 경우에는 직권으로 또는 검사, 보호관찰관 또는 수탁기관의 장의 청구에 의하여 결정으로 한 차례만 보호처분의 종류와 기간을 변경할 수 있다.', 1606);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2874, '② 제1항에 따라 보호처분의 종류와 기간을 변경하는 경우 종전의 처분기간을 합산하여 제40조제1항제1호부터 제3호까지 및 제5호부터 제8호까지의 보호처분의 기간은 1년을, 같은 항 제4호의 사회봉사ㆍ수강명령의 시간은 400시간을 각각 초과할 수 없다.', 1606);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2875, '③ 제1항의 처분변경 결정을 한 경우에는 지체 없이 그 사실을 검사, 가정폭력행위자, 법정대리인, 보조인, 피해자, 보호관찰관 및 수탁기관에 통지하여야 한다.', 1606);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2876, null, 1607);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2877, '① 제29조제1항제4호 및 제6호의 위탁 결정 또는 제40조제1항제7호 및 제8호의 보호처분을 받은 가정폭력행위자는 위탁 또는 보호처분에 필요한 비용을 부담한다. 다만, 가정폭력행위자가 지급할 능력이 없는 경우에는 국가가 부담할 수 있다. <개정 2020.10.20>', 1609);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2878, '② 판사는 가정폭력행위자에게 제1항 본문에 따른 비용의 예납(豫納)을 명할 수 있다.', 1609);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2879, '③ 제1항에 따라 가정폭력행위자가 부담할 비용의 계산, 청구 및 지급 절차, 그 밖에 필요한 사항은 대법원규칙으로 정한다.', 1609);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2880, '① 제8조 또는 제29조에 따른 임시조치(연장 또는 변경의 결정을 포함한다. 이하 같다), 제40조의 보호처분, 제45조의 보호처분의 변경 및 제46조의 보호처분의 취소에 있어서 그 결정에 영향을 미칠 법령 위반이 있거나 중대한 사실 오인(誤認)이 있는 경우 또는 그 결정이 현저히 부당한 경우에는 검사, 가정폭력행위자, 법정대리인 또는 보조인은 가정법원 본원합의부에 항고할 수 있다. 다만, 가정법원이 설치되지 아니한 지역에서는 지방법원 본원합의부에 하여야 한다.', 1610);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2881, '② 법원이 제37조에 따라 처분을 하지 아니한다는 결정을 한 경우 그 결정이 현저히 부당할 때에는 검사, 피해자 또는 그 법정대리인은 항고할 수 있다. 이 경우 항고법원에 관하여는 제1항을 준용한다.', 1610);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2882, '③ 항고는 그 결정을 고지받은 날부터 7일 이내에 하여야 한다.', 1610);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2883, '① 항고를 할 때에는 항고장을 원심 법원에 제출하여야 한다.', 1611);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2884, '② 항고장을 받은 법원은 3일 이내에 의견서를 첨부하여 기록을 항고법원에 보내야 한다.', 1611);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2885, '① 항고법원은 항고의 절차가 법률에 위반되거나 항고가 이유 없다고 인정하는 경우에는 결정으로 항고를 기각(棄却)하여야 한다.', 1612);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2886, '② 항고법원은 항고가 이유 있다고 인정하는 경우에는 원결정(原決定)을 취소하고 사건을 원심법원에 환송하거나 다른 관할 법원에 이송하여야 한다. 이 경우 환송 또는 이송하기에 급박하거나 그 밖에 필요하다고 인정할 때에는 원결정을 파기하고 스스로 적절한 임시조치, 처분을 하지 아니한다는 결정 또는 보호처분의 결정을 할 수 있다.', 1612);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2887, '① 항고의 기각 결정에 대하여는 그 결정이 법령에 위반된 경우에만 대법원에 재항고를 할 수 있다.', 1613);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2888, '② 제1항의 재항고에 관하여는 제49조제3항을 준용한다.', 1613);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2889, '① 피해자보호명령사건의 관할은 가정폭력행위자의 행위지ㆍ거주지 또는 현재지 및 피해자의 거주지 또는 현재지를 관할하는 가정법원으로 한다. 다만, 가정법원이 설치되지 아니하는 지역에 있어서는 해당 지역의 지방법원으로 한다.', 1616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2890, '② 피해자보호명령사건의 심리와 결정은 판사가 한다.', 1616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2891, '① 판사는 피해자의 보호를 위하여 필요하다고 인정하는 때에는 피해자, 그 법정대리인 또는 검사의 청구에 따라 결정으로 가정폭력행위자에게 다음 각 호의 어느 하나에 해당하는 피해자보호명령을 할 수 있다. <개정 2020.10.20>', 1617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2892, '② 제1항 각 호의 피해자보호명령은 이를 병과할 수 있다.', 1617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2893, '③ 피해자, 그 법정대리인 또는 검사는 제1항에 따른 피해자보호명령의 취소 또는 그 종류의 변경을 신청할 수 있다. <개정 2020.10.20>', 1617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2894, '④ 판사는 직권 또는 제3항에 따른 신청에 상당한 이유가 있다고 인정하는 때에는 결정으로 해당 피해자보호명령을 취소하거나 그 종류를 변경할 수 있다.', 1617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2895, '⑤ 법원은 피해자의 보호를 위하여 필요하다고 인정하는 경우에는 피해자 또는 그 법정대리인의 청구 또는 직권으로 일정 기간 동안 검사에게 피해자에 대하여 다음 각 호의 어느 하나에 해당하는 신변안전조치를 하도록 요청할 수 있다. 이 경우 검사는 피해자의 주거지 또는 현재지를 관할하는 경찰서장에게 신변안전조치를 하도록 요청할 수 있으며, 해당 경찰서장은 특별한 사유가 없으면 이에 따라야 한다. <신설 2014.12.30>', 1617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2896, '⑥ 제5항에 따른 신변안전조치의 집행방법, 기간, 절차, 그 밖에 필요한 사항은 대통령령으로 정한다. <신설 2014.12.30>', 1617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2897, '① 제55조의2제1항 각 호의 피해자보호명령의 기간은 1년을 초과할 수 없다. 다만, 피해자의 보호를 위하여 그 기간의 연장이 필요하다고 인정하는 경우에는 직권이나 피해자, 그 법정대리인 또는 검사의 청구에 따른 결정으로 2개월 단위로 연장할 수 있다. <개정 2020.10.20>', 1618);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2898, '② 제1항 및 제55조의2제3항에 따라 피해자보호명령의 기간을 연장하거나 그 종류를 변경하는 경우 종전의 처분기간을 합산하여 3년을 초과할 수 없다. <개정 2020.10.20>', 1618);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2899, '① 판사는 제55조의2제1항에 따른 피해자보호명령의 청구가 있는 경우에 피해자의 보호를 위하여 필요하다고 인정하는 경우에는 결정으로 제55조의2제1항 각 호의 어느 하나에 해당하는 임시보호명령을 할 수 있다.', 1619);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2900, '② 임시보호명령의 기간은 피해자보호명령의 결정 시까지로 한다. 다만, 판사는 필요하다고 인정하는 경우에 그 기간을 제한할 수 있다.', 1619);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2901, '③ 임시보호명령의 취소 또는 그 종류의 변경에 대하여는 제55조의2제3항 및 제4항을 준용한다. 이 경우 "피해자보호명령"은 "임시보호명령"으로 본다.', 1619);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2902, '① 법원은 가정보호사건조사관, 법원공무원, 사법경찰관리 또는 보호관찰관 등으로 하여금 임시보호명령 및 피해자보호명령의 이행실태에 대하여 수시로 조사하게 하고, 지체 없이 그 결과를 보고하도록 할 수 있다.', 1620);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2903, '② 법원은 임시보호명령 또는 피해자보호명령을 받은 가정폭력행위자가 그 결정을 이행하지 아니하거나 집행에 따르지 아니하는 때에는 그 사실을 관할법원에 대응하는 검찰청 검사에게 통보할 수 있다.', 1620);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2904, null, 1621);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2905, '① 제55조의2에 따른 피해자보호명령(제55조의3에 따른 연장의 결정을 포함한다) 및 그 취소 또는 종류의 변경, 제55조의4에 따른 임시보호명령 및 그 취소 또는 종류의 변경에 있어서 그 결정에 영향을 미칠 법령위반이 있거나 중대한 사실오인이 있는 때 또는 그 결정이 현저히 부당한 때에는 검사, 피해자, 가정폭력행위자, 법정대리인 또는 보조인은 가정법원본원합의부에 항고할 수 있다. 다만, 가정법원이 설치되지 아니한 지역에서는 지방법원본원합의부에 하여야 한다. <개정 2020.10.20>', 1623);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2906, '② 판사가 피해자보호명령을 기각한 경우 피해자, 그 법정대리인 또는 검사는 항고할 수 있다. 이 경우 항고법원에 관하여는 제1항을 준용한다. <개정 2020.10.20>', 1623);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2907, '③ 피해자보호명령 등의 항고 및 재항고에 관하여는 제49조제3항, 제50조부터 제54조까지의 규정을 준용한다.', 1623);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2908, '① 피해자는 가정보호사건이 계속(繫屬)된 제1심 법원에 제57조의 배상명령을 신청할 수 있다. 이 경우 인지를 붙이지 아니한다.', 1625);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2909, '② 제1항의 경우 「소송촉진 등에 관한 특례법」 제26조제2항부터 제8항까지의 규정을 준용한다.', 1625);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2910, '① 법원은 제1심의 가정보호사건 심리 절차에서 보호처분을 선고할 경우 직권으로 또는 피해자의 신청에 의하여 다음 각 호의 금전 지급이나 배상(이하 "배상"이라 한다)을 명할 수 있다.', 1626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2911, '② 법원은 가정보호사건에서 가정폭력행위자와 피해자 사이에 합의된 배상액에 관하여도 제1항에 따라 배상을 명할 수 있다.', 1626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2912, '③ 제1항의 경우에는 「소송촉진 등에 관한 특례법」 제25조제3항(제2호의 경우는 제외한다)을 준용한다.', 1626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2913, '① 배상명령은 보호처분의 결정과 동시에 하여야 한다.', 1627);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2914, '② 배상명령은 일정액의 금전지급을 명함으로써 하고 배상의 대상과 금액을 보호처분 결정서의 주문(主文)에 표시하여야 한다. 이 경우 배상명령의 이유는 특히 필요하다고 인정되는 경우가 아니면 적지 아니할 수 있다.', 1627);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2915, '③ 배상명령은 가집행할 수 있음을 선고할 수 있다.', 1627);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2916, '④ 제3항의 경우에는 「민사소송법」 제213조제3항, 제215조, 제500조 및 제501조를 준용한다.', 1627);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2917, '⑤ 배상명령을 한 경우에는 보호처분 결정서의 정본(正本)을 가정폭력행위자와 피해자에게 지체 없이 송달하여야 한다.', 1627);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2918, '① 배상신청이 부적법한 경우 또는 그 신청이 이유 없거나 배상명령을 하는 것이 적절하지 아니하다고 인정되는 경우에는 결정으로 각하(却下)하여야 한다.', 1628);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2919, '② 보호처분의 결정과 동시에 제1항의 재판을 할 때에는 이를 보호처분 결정서의 주문에 표시할 수 있다.', 1628);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2920, '③ 신청을 각하하거나 그 일부를 인용(認容)한 재판에 대하여 신청인은 불복을 신청하지 못하며 다시 동일한 배상신청을 할 수 없다.', 1628);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2921, '① 보호처분에 대한 항고가 있는 경우에는 배상명령은 가정보호사건과 함께 항고심에 이심(移審)된다. 보호처분에 대한 재항고가 있는 경우에도 또한 같다.', 1629);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2922, '② 항고심에서 제1심 결정을 유지하는 경우에도 배상명령에 대하여는 취소하거나 변경할 수 있다.', 1629);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2923, '③ 가정폭력행위자는 보호처분 결정에 대하여 항고하지 아니하고 배상명령에 대하여만 항고할 수 있다. 이 경우 항고는 7일 이내에 하여야 한다.', 1629);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2924, '④ 제3항에 따른 항고의 기각결정에 대하여는 그 결정이 법령에 위반된 경우에만 대법원에 7일 이내에 재항고할 수 있다. 제1항 전단에 따른 항고심 결정에 대하여 배상명령에 대하여만 재항고하는 경우에도 또한 같다.', 1629);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2925, '⑤ 제1항, 제3항 및 제4항에 따른 항고와 재항고는 배상명령의 집행을 정지하는 효력이 없다.', 1629);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2926, '① 확정된 배상명령 또는 가집행선고가 있는 배상명령이 적혀 있는 보호처분 결정서의 정본은 「민사집행법」에 따른 강제집행에 관하여는 집행력 있는 민사판결 정본과 동일한 효력이 있다.', 1630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2927, '② 이 법에 따른 배상명령이 확정된 경우에는 그 인용금액의 범위에서 피해자는 다른 절차에 따른 손해배상을 청구할 수 없다.', 1630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2928, '①다음 각 호의 어느 하나에 해당하는 가정폭력행위자는 2년 이하의 징역 또는 2천만원 이하의 벌금 또는 구류(拘留)에 처한다. <개정 2012.1.17>', 1632);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2929, '② 정당한 사유 없이 제29조제1항제1호부터 제3호까지의 어느 하나에 해당하는 임시조치를 이행하지 아니한 가정폭력행위자는 1년 이하의 징역 또는 1천만원 이하의 벌금 또는 구류에 처한다. <신설 2020.10.20>', 1632);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2930, '③ 상습적으로 제1항 및 제2항의 죄를 범한 가정폭력행위자는 3년 이하의 징역이나 3천만원 이하의 벌금에 처한다. <신설 2012.1.17, 2020.10.20>', 1632);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2931, '④ 제3조의2제1항에 따라 이수명령을 부과받은 사람이 보호관찰소의 장 또는 교정시설의 장의 이수명령 이행에 관한 지시에 불응하여 「보호관찰 등에 관한 법률」 또는 「형의 집행 및 수용자의 처우에 관한 법률」에 따른 경고를 받은 후 재차 정당한 사유 없이 이수명령 이행에 관한 지시에 불응한 경우 다음 각 호에 따른다. <신설 2020.10.20>', 1632);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2932, '① 제18조제1항에 따른 비밀엄수 의무를 위반한 보조인(변호사는 제외한다), 상담소등의 상담원 또는 그 기관장(그 직에 있었던 사람을 포함한다)은 1년 이하의 징역이나 2년 이하의 자격정지 또는 1천만원 이하의 벌금에 처한다.', 1633);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2933, '② 제18조제2항의 보도 금지 의무를 위반한 신문의 편집인ㆍ발행인 또는 그 종사자, 방송사의 편집책임자, 그 기관장 또는 종사자, 그 밖의 출판물의 저작자와 발행인은 500만원 이하의 벌금에 처한다.', 1633);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2934, null, 1634);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2935, null, 1635);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2936, '① 「가정폭력범죄의 처벌 등에 관한 특례법」(이하 "법"이라 한다) 제55조의2제5항에 따른 신변안전조치의 청구 및 요청은 각각 별지 제1호서식의 신변안전조치 청구서 및 별지 제2호서식의 신변안전조치 요청서로 하여야 한다. 다만, 긴급한 경우에는 구두(口頭)로 또는 전화 등으로 할 수 있으며, 사후에 지체 없이 관련 서면을 제출하거나 송부하여야 한다.', 1637);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2937, '② 제1항에 따른 신변안전조치를 청구하거나 요청할 때에는 신변안전조치가 필요한 사유, 신변안전조치의 종류 및 기간을 구체적으로 기재하여야 하며, 그 내용을 입증할 수 있는 자료 등을 첨부할 수 있다.', 1637);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2938, null, 1638);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2939, '① 피해자 또는 그 법정대리인은 신변안전조치 종류의 변경이 필요하거나 또는 추가적인 신변안전조치가 필요한 경우 별지 제3호서식으로 법원에 신변안전조치의 종류 변경 또는 신변안전조치의 추가를 청구할 수 있다. 이 경우 제2조제1항 단서 및 제2항을 준용한다.', 1639);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2940, '② 피해자 또는 그 법정대리인은 신변안전조치의 기간 중에 신변안전조치의 연장이 필요한 사유 및 그 기간을 구체적으로 기재하여 별지 제3호서식으로 법원에 신변안전조치의 연장을 청구할 수 있다. 이 경우 제2조제1항 단서 및 제2항을 준용한다.', 1639);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2941, '③ 법원은 피해자 보호를 위하여 신변안전조치의 종류 변경, 신변안전조치의 추가 또는 기간 연장이 필요하다고 인정하는 경우에는 직권으로 또는 제1항ㆍ제2항에 따른 청구에 의하여 별지 제2호서식으로 검사에게 신변안전조치의 종류 변경, 신변안전조치의 추가 또는 기간 연장을 요청할 수 있다. 이 경우 제2조제1항 단서 및 제2항을 준용한다.', 1639);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2942, '① 검사는 법원으로부터 법 제55조의2제5항 전단 또는 이 영 제4조제3항에 따른 요청을 받은 경우에는 별지 제2호서식으로 피해자의 주거지 또는 현재지를 관할하는 경찰서장에게 해당 조치를 하도록 요청할 수 있다. 이 경우 제2조제1항 단서 및 제2항을 준용한다.', 1640);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2943, '② 제1항에 따라 신변안전조치를 요청받은 경찰서장은 신변안전조치의 필요성이 소멸하는 등 특별한 사유가 없으면 제1항에 따라 검사가 요청한 조치를 하여야 한다.', 1640);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2944, '① 경찰서장이 법 제55조의2제5항에 따른 신변안전조치 및 제5조에 따른 조치를 하였을 때에는 지체 없이 그 조치를 요청한 검사에게 별지 제4호서식의 신변안전조치 이행 통보서로 통보하여야 한다.', 1641);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2945, '② 검사는 제1항에 따른 통보를 받았을 때에는 제5조제1항에 따른 요청을 한 법원에 그 사실을 별지 제4호서식의 신변안전조치 이행 통보서로 통보하여야 한다.', 1641);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2946, '③ 제1항과 제2항에 따른 통보 서류 및 신변안전조치와 관련된 서류는 공개해서는 아니 된다.', 1641);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2947, '①경찰서장ㆍ해양경찰서장 또는 군수사기관의 장은 법에 규정된 죄를 범한 자(이하 "범인"이라 한다)의 신고 또는 체포와 관련하여 신고자등이 부상 또는 사망하거나, 범인을 살해하거나, 범인을 자살하게 한 것을 안 때에는 지체없이 관할 지방검찰청 검사장이나 지청장 또는 국방부검찰단장이나 각 군 검찰단장에게 그 사실을 보고하여야 한다. <개정 1996.8.8, 2004.1.13, 2014.11.19, 2017.7.26, 2022.6.30>', 1645);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2948, '②국가정보원장ㆍ지방검찰청 검사장이나 지청장 또는 국방부검찰단장이나 각 군 검찰단장은 제1항의 보고나 타인의 통보를 받은 때 또는 직권으로 국가정보원직원ㆍ검사 또는 군검사로 하여금 그 사건을 조사하고, 법 제21조제3항 및 제22조제1항의 규정에 의한 상금 또는 보로금의 지급대상이나 법 제23조의 규정에 의한 보상대상에의 해당여부를 조사한 후 공적평가서를 작성하여 관계자에게 그 등본을 교부하게 하여야 한다. <개정 1997.9.30, 1999.3.31, 2004.1.13, 2022.6.30>', 1645);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2949, '①국가보안유공자심사위원회(이하 "위원회"라 한다)는 위원장 1인, 위원 6인 및 대리위원 6인으로 구성한다.', 1646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2950, '②위원장은 법무부 검찰국장이 되고, 위원 및 대리위원은 법무부소속 검사와 기획재정부ㆍ국방부ㆍ행정안전부ㆍ국가정보원 및 국가보훈부소속 3급 내지 5급 일반직공무원 또는 고위공무원단에 속하는 일반직공무원(이에 상당하는 특정직 또는 별정직공무원을 포함한다)중에서 위원장이 지명 또는 위촉하는 자가 된다. <개정 1987.10.26, 1994.12.23, 1999.3.31, 1999.5.24, 2004.1.13, 2006.6.12, 2008.2.29, 2013.3.23, 2014.11.19, 2017.7.26, 2023.4.11>', 1646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2951, '③위원장은 위원회를 대표하고, 위원회의 업무를 총괄한다. <개정 2021.1.5>', 1646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2952, '④위원장이 사고가 있을 때에는 법무부소속 공무원인 위원이 그 직무를 대행한다.', 1646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2953, '⑤대리위원은 그 소속기관의 위원이 사고가 있을 때에 위원의 직무를 대행한다.', 1646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2954, '①위원회의 사무를 처리하게 하기 위하여 위원회에 간사 및 서기 각 2인을 둔다.', 1647);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2955, '②간사는 법무부소속 검사 또는 4급 내지 5급 공무원중에서, 서기는 법무부소속 공무원중에서 위원장이 지명한다. <개정 2004.1.13>', 1647);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2956, '①위원장은 상금 또는 보로금의 지급이나 보상의 청구가 있을 때에 위원회의 회의를 소집하고, 그 의장이 된다. <개정 1997.9.30>', 1648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2957, '②위원회의 회의는 위원장을 포함한 위원 4인이상의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다. <개정 2004.1.13>', 1648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2958, null, 1653);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2959, '① 법 제21조에 따른 상금은 그 공로, 범죄의 경중, 그 밖의 사정을 고려하여 결정하되, 다음 각 호의 금액을 초과할 수 없다. <개정 2011.10.12, 2016.12.30>', 1654);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2960, '②법 제22조에 따른 보로금은 압수물 또는 제공된 금품의 공매가격, 압수 또는 제공 당시의 시가로 산출한 금액의 2분의 1에 상당하는 범위에서 결정하되, 3천만원을 초과할 수 없다. <개정 2004.1.13, 2011.10.12>', 1654);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2961, '③상금 또는 보로금을 받을 권리(이하 "청구권"이라 한다)의 경합은 같은 사건에 대하여 공로 간에 상당한 인과관계가 있는 범위에서 정한다. <개정 2011.10.12>', 1654);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2962, '④경합된 청구에 대해서는 공로의 비중을 고려하여 배당액을 결정한다. <개정 2011.10.12>', 1654);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2963, '⑤제4항의 결정을 하는 경우 청구권자 간에 배당액에 관하여 미리 합의한 때에는 그 합의된 비율에 따른다. 다만, 합의된 비율이 현저하게 부당한 때에는 위원회의 의결로 이를 변경할 수 있다. <개정 2011.10.12>', 1654);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2964, '①법 제23조의 규정에 의하여 보상을 받고자 하는 자는 청구서(전자문서로 된 청구서를 포함한다)에 다음 각호의 서류(전자문서를 포함한다)를 첨부하여 위원회에 제출하여야 한다. 다만, 범인이 체포되지 아니한 때에는 제2호의 서류는 이를 첨부하지 아니한다. <개정 1982.12.31, 1997.9.30, 2004.3.17, 2010.11.2>', 1656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2965, '② 삭제 <2010.11.2>', 1656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2966, null, 1657);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2967, '①위원회는 상금 또는 보로금에 관한 결정을 한 때에는 지체없이 법무부장관 및 청구자에게, 보상의 여부에 관한 결정을 한 때에는 국가보훈부장관 및 청구자에게 그 결과를 통지하여야 한다. <개정 1987.10.26, 1997.9.30, 2023.4.11>', 1658);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2968, '②국가보훈부장관 및 청구자에 대한 제1항의 통지는 결정서 정본의 송달에 의한다. <개정 1987.10.26, 2023.4.11>', 1658);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2969, '③법무부장관은 제1항의 규정에 의한 지급통지를 받은 때에는 지체없이 청구자에게 상금 또는 보로금을 지급하여야 한다.', 1658);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2970, null, 1659);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2971, '① 위원회에서 법 제23조에 따른 보상대상자로 결정되어 제16조제1항의 통지를 받은 사람은 「국가유공자 등 예우 및 지원에 관한 법률」 제6조제1항에 따라 등록을 신청하여야 한다. <개정 2016.12.30>', 1660);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2972, '② 국가보훈부장관은 제1항에 따른 등록신청을 한 사람 중 제15조제1호에 따라 보상대상자로 결정된 사람을 「국가유공자 등 예우 및 지원에 관한 법률」에 따른 공상군경으로, 제15조제2호에 따라 보상대상자로 결정된 사람을 같은 법에 따른 순직군경의 유족으로 각각 보아 같은 법에 따른 보상을 한다. <개정 2016.12.30, 2023.4.11>', 1660);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2973, '①제17조의 규정에 의한 보상대상자가 법에 규정된 죄를 범하여 금고이상의 형을 받은 때에는 그 형이 확정된 날 이후의 보상은 이를 하지 아니한다. <개정 1997.9.30>', 1662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2974, '② 삭제 <1987.10.26>', 1662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2975, '①국가정보원장은 전조의 규정에 의하여 통보받은 몰수금품중 법 제3조제1항의 규정에 의하여 직접 사용 또는 처분이 필요하다고 인정되는 금품이 있을 때에는 통보를 받은 날로부터 30일이내에 그 송부를 별지 제2호서식에 의하여 관계 각급 검사장에게 요청하여야 한다. <개정 1999.3.31>', 1665);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2976, '②국가정보원장은 통보받은 몰수금품중에 직접 사용 또는 처분할 금품이 없다고 인정되는 때에도 전항의 기간내에 그 뜻을 관계 각급 검사장에게 통보하여야 한다. <개정 1999.3.31>', 1665);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2977, '①국가정보원장이 법 제3조제1항의 규정에 의한 대통령의 승인을 얻고자 할 때에는 다음 각호의 사항을 기재한 문서로써 하여야 한다. <개정 1999.3.31>', 1667);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2978, '②전항의 규정에 의하여 대통령의 승인을 얻은 후 그 몰수금품의 사용 또는 처분의 목적을 변경하고자 할 때의 승인절차도 전항에 준한다.', 1667);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2979, '①법 제4조제1항에서 규정하고 있는 "기타 이에 준하는 비용"의 항목은 식비로 한다. <개정 2003.9.13>', 1672);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2980, '②법 제4조제2항, 제5조제2항의 규정에 의한 증인등의 국내 여비 및 숙박료는 법원공무원여비규칙 제10조제1항, 제11조제1항, 제12조제1항, 제13조제1항, 제16조제1항의 별표 2 국내여비지급표에 정한 제2호 해당자 지급액으로 하며, 철도운임의 경우 위 규칙 제10조제1항 단서의 규정을 준용한다. <개정 2009.1.9>', 1672);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2981, '①법 제6조의 규정에 의한 증인등의 일당ㆍ여비 및 숙박료는 증인등이 국외로부터 국내로, 국내로부터 국외로 여행하거나 또는 국내로 입국하기 위하여 국외에서 여행(이하 이를 합하여 "국외여행"이라 한다)하는 경우에 이를 지급한다.', 1673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2982, '②증인등이 국외여행하는 경우의 운임은 다음 각호의 구분에 의하되, 통행세를 가산한다.', 1673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2983, '③증인등이 국외여행하는 경우의 운임을 제외한 여비 및 숙박료는 법원공무원여비규칙 제16조제1항의 별표 4 "국외여비정액표"에 정한 별표 1 여비지급구분표의 제2호 나목 해당자 소정액으로 한다. <개정 2009.1.9>', 1673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2984, '①법 제8조제1항의 규정에 의한 국선변호인의 일당은 매년 예산의 범위안에서 대법관회의에서 정한다.', 1674);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2985, '②국선변호인의 국내여비 및 숙박료에 관하여는 제3조제2항의 규정을 준용한다. <개정 2009.1.9>', 1674);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2986, '③국선변호인이 국외여행하는 경우의 여비 및 숙박료에 관하여는 제4조제2항, 제3항의 규정을 준용하되, 이 경우 "중간 등급 이하의 운임"은 "최상등급의 운임"으로, 별표 1 여비지급구분표의 제2호 나목 해당자는 별표 1 여비지급구분표의 제1호 라목 해당자로 본다. <개정 2009.1.9>', 1674);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2987, '①법 제8조제2항의 규정에 의한 국선변호인의 보수는 매년 예산의 범위안에서 대법관회의에서 정하며 그 보수는 심급별로 지급하되, 체포 또는 구속적부심에 있어서는 심급에 관계없이 별도로 지급한다.', 1675);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2988, '②제1항의 보수는 사안의 난이, 국선변호인이 수행한 직무의 내용, 사건처리에 소요된 시간 등을 참작하여 예산의 범위안에서 당해재판장이 이를 증액할 수 있다. <개정 2008.6.5>', 1675);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2989, '③공익법무관, 사법연수생, 변호사자격이 있는 장교, 군법무관시보인 국선변호인에 대하여는 보수를 지급하지 아니한다. 다만, 피고인 또는 피의자의 접견을 위한 비용 기타 재판장이 인정하는 실비를 변상할 수 있다. <개정 2022.6.30>', 1675);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2990, null, 1677);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2991, '① 국제상거래와 관련하여 부정한 이익을 얻을 목적으로 외국공무원등에게 그 업무와 관련하여 뇌물을 약속 또는 공여하거나 공여의 의사를 표시한 자는 5년 이하의 징역 또는 5천만원 이하의 벌금에 처한다. 이 경우 범죄행위로 얻은 이익(이익이 공여액보다 적거나 산정할 수 없는 경우에는 공여액)이 1천만원을 초과할 때에는 5년 이하의 징역 또는 그 이익(이익이 공여액보다 적거나 산정할 수 없는 경우에는 공여액)의 2배 이상 5배 이하에 해당하는 벌금에 처한다. <개정 2020.2.4>', 1678);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2992, '② 제1항의 행위에 공할 목적으로 제3자에게 뇌물을 교부하거나 그 정을 알면서 교부를 받은 자도 제1항의 형과 같다. <신설 2018.12.18>', 1678);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2993, '③ 제1항 또는 제2항의 경우 다음 각 호의 어느 하나에 해당하는 경우는 예외로 한다. <개정 2018.12.18>', 1678);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2994, '④ 제1항 또는 제2항의 죄를 범하여 징역에 처하는 경우에는 제1항 또는 제2항에서 정한 벌금을 병과(倂科)한다. <개정 2018.12.18>', 1678);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2995, '① 「경범죄 처벌법」(이하 "법"이라 한다) 제7조 및 「경범죄 처벌법 시행령」(이하 "영"이라 한다) 제3조제1항에 따른 범칙금 납부통고서 및 범칙금 영수증은 별지 제1호서식에 따르고, 범칙금 납부고지서는 별지 제2호서식에 따른다.', 1683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2996, '② 제1항에도 불구하고 휴대용 컴퓨터 등을 이용하여 범칙금의 납부를 통고하는 경우 범칙금 납부통고서, 범칙금 영수증 및 범칙금 납부고지서는 별지 제3호서식에 따르되, 「도로교통법 시행규칙」 별지 제159호의2서식을 사용할 수 있다.', 1683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2997, '③ 영 제3조제1항에 따른 범칙금 납부고지서 발행원부 및 범칙자 적발보고서는 별지 제4호서식에 따른다.', 1683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2998, '④ 영 제3조제2항에 따른 통고처분처리부는 별지 제5호서식에 따른다.', 1683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (2999, '① 법 제9조제1항제1호에 해당하는 사람에게 영 제6조제1항에 따라 발부하는 즉결심판 출석통지서는 별지 제7호서식에 따르고,  영 제6조제3항에 따라 발부하는 즉결심판 출석최고서는 별지 제7호의2서식에 따른다. <개정 2016.7.19>', 1685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3000, '② 제1항에도 불구하고 경찰서장, 해양경찰서장 및 제주특별자치도지사는 휴대용 컴퓨터 등을 이용하여 별지 제8호서식에 따른 현장 즉결심판 출석통지서로 즉결심판 출석통지를 할 수 있다. <신설 2015.7.2, 2016.7.19, 2017.7.26>', 1685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3001, '③ 법 제9조제1항제2호에 해당하는 사람에게 영 제6조제2항 및 제3항에 따라 발부하는 즉결심판 출석통지서(최고서), 범칙금등 영수증 및 범칙금등 납부고지서는 별지 제9호서식에 따른다. <개정 2015.7.2>', 1685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3002, '④ 영 제6조제5항에 따른 즉결심판사범 적발보고서는 별지 제10호서식에 따르고, 즉결심판청구서는 별지 제11호서식에 따른다. <개정 2015.7.2>', 1685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3003, '① 법원은 대상사건에 대한 공소의 제기가 있는 때에는 공소장 부본과 함께 피고인 또는 변호인에게 국민참여재판의 절차, 법 제8조제2항에 따른 서면의 제출, 법 제8조제4항에 따른 의사번복의 제한, 그 밖의 주의사항이 기재된 국민참여재판에 관한 안내서를 송달하여야 한다.', 1690);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3004, '② 피고인이 법 제8조제2항의 서면을 법원에 제출할 때에는 다음 각 호의 사항을 기재하고, 기명날인 또는 서명하여야 한다.', 1690);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3005, '③ 법 제8조제2항의 서면이 제출된 때에는 법원은 검사에게 그 취지와 서면의 내용을 통지하여야 한다.', 1690);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3006, '④ 제3항의 통지는 서면사본의 송달 외에 전화, 모사전송, 전자우편 그 밖에 상당한 방법으로 이를 할 수 있다.', 1690);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3007, '⑤ 제3항의 통지의 증명은 그 취지를 기재한 법원서기관 ㆍ 법원사무관 ㆍ 법원주사 또는 법원주사보(다음부터 "법원사무관등"이라 한다)의 보고서로써 할 수 있다.', 1690);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3008, '① 법원은 지방법원이나 그 지원의 단독판사 관할사건의 피고인에 대하여도 국민참여재판을 원하는지 여부에 관한 의사를 서면 등의 방법으로 확인할 수 있다.', 1691);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3009, '② 제1항에 따른 피고인 의사의 확인절차에 관하여는 대상사건에 대한 피고인 의사의 확인절차에 관한 법 제8조제2항부터 제4항까지 및 이 규칙 제3조, 제4조를 각각 준용한다. 이 경우 법 제8조제4항의 "공판준비기일"과 "제1회 공판기일"은 "법원조직법 제32조제1항제1호의 결정(이하, ‘재정합의결정’이라 한다)으로 대상사건이 된 이후의 공판준비기일"과 "재정합의결정으로 대상사건이 된 이후의 첫 공판기일"로, 이 규칙 제4조제1항의 "법 제8조제1항"은 "이 규칙 제3조의2제1항"으로 각각 본다.', 1691);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3010, '③ 제1항, 제2항에 따라 피고인의 의사를 확인할 단독판사 관할사건의 구체적인 범위, 그 밖에 필요한 사항은 대법원예규로 정한다.', 1691);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3011, '① 법 제8조제1항에 의하여 피고인이 제출한 서면만으로는 피고인의 의사를 확인할 수 없는 경우에는 법원은 심문기일을 정하여 피고인을 심문하거나 서면 기타 상당한 방법으로 피고인의 의사를 확인하여야 한다. 피고인이 위 서면을 제출하지 아니한 경우에도 법원은 위와 같은 방법으로 피고인의 의사를 확인할 수 있다. <개정 2012.5.29>', 1692);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3012, '② 법원은 제1항에 따라 심문기일을 정한 때에는 검사, 피고인 또는 변호인, 피고인을 구금하고 있는 관서의 장에게 심문기일과 장소를 통지하여야 하고, 피고인을 구금하고 있는 관서의 장은 위 심문기일에 피고인을 출석시켜야 한다.', 1692);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3013, '③ 제3조제4항의 규정은 제2항에 따른 통지에 이를 준용한다. 이 경우 통지의 증명은 그 취지를 심문조서에 기재함으로써 할 수 있다.', 1692);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3014, '④ 법원은 피고인의 심문을 합의부원에게 명할 수 있다.', 1692);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3015, '① 법원은 공소장변경 또는 재정합의결정으로 대상사건이 된 사건에 대하여 피고인 또는 변호인에게 제3조제1항에 따른 국민참여재판에 관한 안내서를 지체 없이 송달하여야 한다. 다만, 재정합의결정으로 대상사건이 된 사건에 대하여 제3조의2제1항에 따라 피고인의 의사를 미리 확인한 경우에는 그러하지 아니하다. <개정 2015.6.2>', 1693);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3016, '② 제1항 본문의 경우에 법 제8조제2항의 "공소장 부본을 송달받은 날부터 7일 이내"를 "공소장변경허가결정을 고지받은 날부터 7일 이내(공소장변경으로 대상사건이 된 사건의 경우)" 또는 "국민참여재판에 관한 안내서를 송달받은 날부터 7일 이내(재정합의결정으로 대상사건이 된 사건의 경우)"로, 법 제8조제4항의 "제1회 공판기일"을 "피고인의 의사가 기재된 서면이 제출된 이후의 첫 공판기일"로 각각 본다. <개정 2015.6.2>', 1693);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3017, '① 법원은 법 제9조제1항에 따른 배제결정을 하기 전에 기간을 정하여 검사, 피고인 또는 변호인에게 배제결정에 관한 의견을 제출하도록 통지하여야 한다.', 1694);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3018, '② 제1항의 의견은 서면으로 제출되어야 한다. 단, 심문기일이나 공판준비기일을 연 경우에는 구술로 할 수 있다.', 1694);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3019, '③ 제1항의 경우에는 제3조제4항 및 제5항의 규정을 준용한다.', 1694);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3020, '① 지방법원 지원 합의부는 법 제10조제1항에 따라 국민참여재판절차 회부결정을 한 날부터 3일 이내에 소송기록과 증거물을 지방법원본원 합의부로 송부하여야 한다.', 1695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3021, '② 제1항의 송부를 받은 법원은 지체 없이 그 법원에 대응하는 검찰청 검사 또는 고위공직자범죄수사처에 소속된 검사(이하 "수사처검사"라고 한다)에게 그 사실을 통지하여야 한다. <개정 2021.1.29>', 1695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3022, '③ 피고인이 교도소 또는 구치소에 있는 경우에는 지방법원 본원에 대응한 검찰청 검사 또는 수사처검사는 제2항의 통지를 받은 날부터 7일 이내에 피고인을 지방법원 본원 소재지의 교도소나 구치소로 이감한다. <개정 2021.1.29>', 1695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3023, '① 검사ㆍ피고인ㆍ변호인이나 「성폭력범죄의 처벌 등에 관한 특례법」제2조의 범죄로 인한 피해자(이하 "성폭력범죄 피해자"라 한다) 또는 법정대리인이 법 제11조제1항에 따른 통상절차회부 신청을 하는 때에는 그 사유를 적은 신청서를 제출하여야 한다. <개정 2012.5.29>', 1696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3024, '② 법원은 제1항에 따른 신청이 있는 때에는 그 취지를 신청을 하지 아니한 검사ㆍ피고인 또는 변호인에게 통지하여야 한다. <개정 2012.5.29>', 1696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3025, '③ 제2항의 경우에는 제3조제4항의 규정을 준용한다.', 1696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3026, '④ 통상절차회부 신청을 하지 아니한 검사ㆍ피고인 또는 변호인은 제2항의 통지를 받은 날부터 3일 이내에 의견서를 법원에 제출하여야 한다. <개정 2012.5.29>', 1696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3027, '⑤ 제1항에 불구하고 검사ㆍ피고인ㆍ변호인이나 성폭력범죄 피해자 또는 법정대리인은 공판준비기일 또는 공판기일에 구술로 그 사유를 주장하여 통상회부신청을 할 수 있다. 이 경우 법원사무관등은 통상회부신청의 취지와 그 사유의 요지를 공판준비기일 또는 공판기일 조서에 기재하여야 하고, 출석하지 아니한 검사ㆍ피고인 또는 변호인에게 조서의 등본을 송달하여야 한다. <개정 2012.5.29>', 1696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3028, '① 법원은 배심원ㆍ예비배심원 및 배심원후보자의 출석 일수에 따른 일당과 여비를 지급하고, 배심원ㆍ예비배심원이 법 제53조제1항에 따라 격리된 때에는 격리된 일수에 따라 수당을 지급한다. <개정 2008.3.31>', 1697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3029, '② 배심원ㆍ예비배심원 및 배심원후보자의 식비는 법원이 상당하다고 인정하는 경우에 한하여 지급한다. <개정 2008.3.31>', 1697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3030, '③ 배심원ㆍ예비배심원 및 배심원후보자의 숙박료는 출석 등에 필요한 밤의 수에 따라 지급한다.', 1697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3031, '④ 숙박료의 항목과 그 금액은 「법원공무원 여비규칙」 제16조제1항의 별표 2 국내여비지급표에 정한 제2호 해당자 지급액으로 한다. <개정 2008.3.31, 2009.1.9>', 1697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3032, '⑤ 제1항에 따른 여비ㆍ일당 및 수당의 금액은 매년 예산의 범위 내에서 대법관회의에서 정한다. <개정 2008.3.31>', 1697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3033, null, 1698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3034, '① 법 제20조에 따른 면제신청은 다음 각 호의 사항을 적어 서면으로 하여야 한다. 다만, 선정기일에서는 구술로 할 수 있다.', 1699);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3035, '② 제1항제3호의 면제사유는 소명하여야 한다.', 1699);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3036, '③ 배심원후보자가 선정기일 전에 면제신청서를 제출하였으나 법원으로부터 법 제23조제3항에 따른 출석통지를 취소하는 통지를 받지 못한 때에는 선정기일에 법원에 출석하여야 한다.', 1699);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3037, '④ 법원은 제1항의 서면에 의한 면제신청에 대하여 필요한 때에는 선정기일에 출석한 배심원후보자를 심문한 후 이를 결정할 수 있다.', 1699);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3038, '① 지방법원장은 매년 9월 30일까지 행정안전부장관에게 법 제22조제1항에 따른 주민등록정보의 송부를 요청하여야 한다. <개정 2012.5.29>', 1700);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3039, '② 법 제22조제2항의 주민등록자료는 무작위로 추출되어야 하고, 배심원후보예정자의 성별 및 생년월일은 주민등록번호의 기재로 갈음할 수 있다.', 1700);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3040, '③ 법령에서 정하는 경우를 제외하고는 누구든지 법 제22조에 따라 송부된 주민등록자료에 포함된 정보를 공개하여서는 아니 된다.', 1700);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3041, '① 지방법원장은 매년 12월 31일까지 법 제22조제2항에 따라 송부된 주민등록정보를 활용하여 배심원후보예정자명부를 작성한다.', 1701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3042, '② 배심원후보예정자명부는 전산자료의 형태로 작성할 수 있다.', 1701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3043, '① 지방법원장은 배심원후보 예정자가 다음 각 호의 사유에 해당함을 안 때에는 해당자를 배심원 후보예정자명부에서 삭제한다.', 1702);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3044, '② 지방법원장은 필요한 때에는 행정안전부장관에게 관할 구역 내에 거주하는 만 20세 이상 국민의 주민등록정보를 추가로 제공하여 줄 것을 요청할 수 있고, 송부된 주민등록정보를 활용하여 배심원후보예정자명부에 추가할 수 있다. <개정 2012.5.29>', 1702);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3045, '① 지방법원장은 배심원후보예정자명부 의 작성 및 관리, 배심원후보자의 선정과 관련한 업무를 전담하는 직원(다음부터 "전담관리자"라 한다)을 지정하여야 한다.', 1703);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3046, '② 전담관리자는 배심원 선정과 관련하여 필요한 경우에 한하여 주민등록정보를 검색ㆍ출력할 수 있고, 그 주민등록정보가 배심원 선정 외의 목적으로 사용되지 않도록 하여야 한다.', 1703);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3047, '③ 누구든지 전담관리자가 아니면 제2항의 주민등록정보를 검색ㆍ출력할 수 없다.', 1703);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3048, '① 선정기일 통지서에는 다음의 사항을 기재하여 배심원후보자에게 송달하여야 한다.', 1704);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3049, '② 법원은 선정기일 통지서와 함께 법 제25조제1항에 따른 질문표를 송달할 수 있다.', 1704);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3050, '① 법 제25조제1항의 질문표에는 다음 각 호의 내 용이 포함되어야 한다.', 1705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3051, '② 법원은 배심원후보자가 답변을 기재하여 제출한 질문표를 재판기록과 별도로 관리하여야 한다.', 1705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3052, '① 배심원후보자는 질문표에 기재된 질문에 답하여 법원에서 정한 기간 내에 법원에 제출하여야 한다.', 1706);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3053, '② 선정기일 통지를 받은 배심원후보자가 선정기일에 출석하지 못할 정당한 사유가 있는 경우에는 서면으로 출석하지 못하는 취지와 그 사유를 법원에 신고하고 이를 소명하여야 한다.', 1706);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3054, '① 법원은 선정기일에 배심원후보자 에게 번호를 부여한다.', 1707);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3055, '② 배심원후보자는 선정기일에서 제1항의 번호로만 호칭되어야 한다.', 1707);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3056, '① 선정기일에서의 질문은 배심원을 공정하게 선정하기 위하여 필요한 범위에 한정되어야 하고, 배심원후보자의 명예나 사생활이 침해되지 않도록 하여야 한다.', 1708);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3057, '② 재판장 또는 수명법관은 필요한 때에는 검사 또는 변호인의 배심원후보자에 대한 질문을 제한할 수 있다.', 1708);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3058, '① 검사와 변호인은 법 제30조에 따른 무이유부기피신청을 함에 있어 편견에 기초하거나 배심원후보자들을 의도적으로 차별해서는 아니 된다.', 1709);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3059, '② 법원은 피고인이 2인 이상인 때에는 피고인별로 법 제30조제1항 각 호의 범위 내에서 무이유부기피신청을 할 수 있는 인원을 정할 수 있다. 다만, 이 때에 피고인별로 무이유부기피신청할 수 있는 인원은 같아야 한다.', 1709);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3060, '③ 검사는 제2항의 경우에 법원이 정한 피고인별 무이유부기피신청 인원을 합한 총수의 범위 내에서 무이유부기피신청할 수 있다.', 1709);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3061, '④ 검사와 변호인은 법 제34조에 따라 배심원을 추가선정하는 때에는 각자 법 제30조제1항에 따른 무이유부기피신청 인원에서 선정기일에 행사한 무이유부기피신청 인원을 공제한 나머지 인원의 범위 내에서 배심원후보자에 대하여 무이유부기피신청을 할 수 있다.', 1709);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3062, '① 선정기일의 절차에 관하여는 참여한 법 원사무관등이 조서를 작성하여야 한다.', 1711);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3063, '② 선정기일 조서에는 다음 각 호의 사항을 기재하여야 한다.', 1711);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3064, '① 검사ㆍ피고인 또는 변호인이 법 제32조제1항에 따라 해임신청을 하는 때에는 다음 각 호의 사항을 적어 서면으로 하여야 한다.', 1713);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3065, '② 제1항제4호의 해임사유는 소명하여야 한다.', 1713);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3066, '③ 법 제32조제1항에 따른 해임신청 및 그에 대한 의견청취절차에 관하여는 제8조제2항부터 제5항까지를 준용한다.', 1713);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3067, '① 배심원ㆍ예비배심원이 법 제33조제1항에 따라 사임신청을 하는 때에는 다음 각 호의 사항을 적어 서면으로 하여야 한다. 다만, 공판정에서는 구술로 할 수 있다.', 1714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3068, '② 제1항제3호의 사임사유는 소명하여야 한다.', 1714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3069, '③ 구술로 신청하는 경우에는 그 사유를 공판조서에 기재하여야 한다.', 1714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3070, '④ 법원은 배심원 또는 예비배심원이 제1항에 따라 사임신청을 한 때에는 지체 없이 검사ㆍ피고인 또는 변호인에게 그 취지와 서면의 내용을 통지하여야 한다.', 1714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3071, '⑤ 제4항의 통지 방법과 증명에 관하여는 제3조제4항 및 제5항의 규정을 준용한다.', 1714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3072, '⑥ 검사ㆍ피고인 또는 변호인은 제4항의 통지를 받은 날로부터 3일 이내에 의견서를 법원에 제출하여야 한다.', 1714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3073, '① 법원은 배심원과 예비배심원에게 번호를 부여하여 그 순서에 따라 착석하도록 하고, 필요하다고 인정되는 경우에는 변론이 종결될 때까지 배심원과 예비배심원을 따로 구분하지 아니할 수 있다.', 1718);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3074, '② 배심원과 예비배심원은 공판기일에 제1항의 번호로만 호칭되어야 한다.', 1718);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3075, '① 법 제41조제1항제1호에 따른 신문요청은 피고인 또는 증인에 대한 신문이 종료된 직후 서면에 의하여 하여야 한다.', 1721);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3076, '② 재판장은 공판의 원활한 진행을 위하여 필요한 때에는 배심원 또는 예비배심원에 의하여 요청된 신문 사항을 수정하여 신문하거나 신문하지 아니할 수 있다.', 1721);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3077, '① 재판장은 공판 진행에 지장을 초래하 는 등 필요하다고 인정되는 경우에는 법 제41조제1항제2호에 따라 허용한 필기를 언제든지 다시 금지할 수 있다.', 1722);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3078, '② 재판장은 필기를 하여 이를 평의에 사용하도록 허용한 경우에는 배심원과 예비배심원에게 평의 도중을 제외한 어떤 경우에도 자신의 필기 내용을 다른 사람이 알 수 없도록 할 것을 주지시켜야 한다.', 1722);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3079, '① 재판장은 피고인에게 진술거부권을 고지하기 전에 배심원과 예비배심원으로 하여금 법 제42조제1항에 따른 선서를 하도록 하고, 법 제42조제2항에 따른 설명을 하여야 한다.', 1723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3080, '② 재판장이 배심원과 예비배심원에게 법 제42조제2항에 따른 설명을 할 때에는 법 제41조제1항 각 호의 규정에 의한 행위를 할 수 있음을 알려야 한다.', 1723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3081, '① 배심원과 예비배심 원은 공판정 외에서 검증, 증인신문 등 증거조사가 이루어지는 경우에도 출석하여야 한다.', 1724);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3082, '② 법원은 배심원과 예비배심원에게 공판정 외 증거조사기일의 일시와 장소를 통지하여야 한다.', 1724);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3083, '① 재판장이 법 제46조제1항에 따라 배심원에게 그 밖에 유의할 사항에 관한 설명을 할 때에는 다음 각 호의 내용을 포함한다.', 1725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3084, '② 검사ㆍ피고인 또는 변호인은 재판장에게 당해 사건과 관련하여 설명이 필요한 법률적 사항을 특정하여 제1항의 설명에 포함하여 줄 것을 서면으로 요청할 수 있다.', 1725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3085, '① 재판장은 종국재판의 고지 전까지 필요하다고 인정되는 경우 예비배심원으로 하여금 법원 내 지정된 장소로 출석하여 그 곳에서 대기하도록 명할 수 있다.', 1726);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3086, '② 재판장은 변론을 종결하면서 예비배심원에게 법 제41조제2항제2호 및 제3호에 규정된 의무를 주지시켜야 한다.', 1726);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3087, '① 법 제46조제2항부터 제4 항까지에 따른 평의ㆍ평결 및 양형에 관한 토의는 변론이 종결된 후 연속하여 진행하여야 한다. 다만, 재판장은 평의 등에 소요되는 시간 등을 고려하여 필요하다고 인정하는 때에는 변론 종결일로부터 3일 이내의 범위 내에서 평의ㆍ평결 및 양형에 관한 토의를 위한 기일을 따로 지정할 수 있다.', 1727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3088, '② 평의ㆍ평결 및 양형에 관한 토의는 평의실에서 행하고, 재판장의 허가를 받지 아니하고는 배심원 이외의 누구도 평의실에 출입할 수 없다.', 1727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3089, '③ 재판장은 법원경위 등으로 하여금 평의실의 출입을 통제하도록 하여야 한다.', 1727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3090, '④ 평의ㆍ평결 및 양형에 관한 토의는 공개하지 않는다.', 1727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3091, '⑤ 법원사무관등은 평의ㆍ평결 및 양형에 관한 토의가 종료된 직후 배심원이 당해 재판과 관련하여 작성한 서류를 지체 없이 수거하여 폐기하여야 한다.', 1727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3092, '① 배심원은 평의를 진행하기에 앞서 호선으로 배심원 대표를 선출하여야 한다. 다만, 호선되지 않는 경우에는 재판장이 배심원 대표를 지정한다.', 1728);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3093, '② 배심원 대표는 아래 각 호의 임무를 수행한다.', 1728);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3094, '① 배심원 대표는 평의를 주재하면서 배심원 각자가 충분하게 의견을 진술할 수 있는 기회를 동등하게 부여하여야 한다.', 1729);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3095, '② 배심원은 평의를 진행하는 도중 필요한 경우에는 배심원 대표를 통하여 재판장에게 공소장 사본, 재판장 설명서가 존재하는 경우 그 사본, 증거서류 사본 및 증거물의 제공을 요청할 수 있다.', 1729);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3096, '③ 재판장은 필요하다고 인정하는 경우에는 제2항의 요청에 의하여 배심원에게 공소장 사본, 재판장 설명서 사본, 증거서류 사본 및 증거물을 제공할 수 있다.', 1729);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3097, '④ 재판장은 평의가 시작된 후 예비배심원이 배심원으로 추가 선정된 경우에는 배심원들로 하여금 평의를 처음부터 다시 시작하도록 하여야 한다.', 1729);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3098, '⑤ 법 제46조제2항 단서 및 제3항에 따라 심리에 관여한 판사가 의견을 진술하는 경우에도 유무죄에 관한 의견을 진술하여서는 아니 된다.', 1729);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3099, '① 법 제52조에 따른 개인 정보는 배심원ㆍ예비배심원 또는 배심원후보자에 관한 정보로서 당해 정보에 포함되어 있는 성명ㆍ주민등록번호ㆍ주소 등의 사항에 의하여 당해 개인을 식별할 수 있는 정보(당해 정보만으로는 특정 개인을 식별할 수 없더라도 다른 정보와 용이하게 결합하여 식별할 수 있는 것을 포함한다)를 말한다.', 1732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3100, '② 법원은「공공기관의 정보공개에 관한 법률」 제10조에 따라 배심원ㆍ예비배심원 또는 배심원후보자의 개인정보에 대한 정보공개청구가 있는 경우 그 사실을 배심원ㆍ예비배심원 또는 배심원후보자에게 지체 없이 통지하고 정보공개청구에 대한 동의 여부에 관한 의견을 확인하여야 한다.', 1732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3101, '③ 제2항에 따른 동의여부 확인은 서면에 의한다. 다만, 법원이 필요하다고 인정한 때나 배심원ㆍ예비배심원 또는 배심원후보자가 원하는 때에는 구술로 할 수 있다.', 1732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3102, '④ 제2항에 의하여 공개청구된 사실을 통지받은 배심원ㆍ예비배심원 또는 배심원후보자는 통지받은 날부터 7일 이내에 법원에 개인정보공개의 동의 여부에 관한 서면을 제출할 수 있다. 다만, 배심원ㆍ예비배심원 또는 배심원후보자가 위 기간 내에 개인정보 공개에 동의하는 서면을 제출하지 아니한 경우에는 개인정보 공개에 대하여 동의하지 아니한 것으로 본다.', 1732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3103, '⑤ 제3항 단서에 따라 구술로 동의 여부를 확인한 담당공무원 등은 그 내용을 기록하고 본인의 확인을 받아야 한다.', 1732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3104, '① 재판장은 법 제53조제1 항에 따라 배심원ㆍ예비배심원을 격리하는 경우에 신문ㆍ방송 시청 금지, 전화ㆍ인터넷 사용 금지 등의 필요한 조치를 취할 수 있다.', 1733);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3105, '② 법 제53조제2항에 따른 신변안전조치의 요청은 이를 서면으로 하여야 한다. 다만, 선정기일 또는 공판기일에서는 구술로 할 수 있고, 법원사무관등은 요청의 취지와 사유의 요지를 조서에 기재하여야 한다.', 1733);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3106, '③ 제2항 본문에 따른 서면에는 다음 각 호의 사항을 기재하여야 한다.', 1733);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3107, '①법 제4조제2항에 따라 우선 지급해야 할 치료비에 관한 통상비용의 범위는 다음 각 호와 같다. <개정 2021.1.5>', 1735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3108, '②치료비에 관한 통상비용의 계산에 있어서 피해자가 외국에서 치료를 받은 경우의 제1항 각호의 비용은 국내의료기관에서 동일한 치료를 하는 경우 그에 상당한 비용으로 한다. 다만, 국내의료기관에서 치료가 불가능하여 외국에서 치료를 받은 경우에는 그에 소요되는 비용으로 한다.', 1735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3109, '①법 제4조제2항의 규정에 의하여 우선지급하여야 할 치료비외의 손해배상금의 범위는 다음 각호와 같다.', 1736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3110, '②제1항제1호 및 제2호의 규정에 의한 위자료가 중복되는 경우에는 보험약관 또는 공제약관이 정하는 바에 의하여 지급한다.', 1736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3111, '①피해자가 제2조 및 제3조의 규정에 의한 손해배상금의 우선지급을 받고자 하는 때에는 금융위원회 또는 국토교통부장관이 정하는 바에 의하여 보험사업자 또는 공제사업자에게 손해배상금우선지급의 청구를 하여야 한다. <개정 1994ㆍ12ㆍ23, 1999.5.24, 2008.2.29, 2008.12.31, 2013.3.23>', 1737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3112, '②제1항의 규정에 의하여 손해배상금우선지급의 청구를 받은 보험사업자 또는 공제사업자는 그 청구를 받은 날로부터 7일이내에 이를 지급하여야 한다.', 1737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3113, '③피해자가 「자동차손해배상 보장법」 제10조 및 제11조에 따라 손해배상액 또는 가불금을 지급받은 때에는 보험사업자 또는 공제사업자는 손해배상금의 우선지급액에서 이를 공제할 수 있다. <개정 2008.9.25>', 1737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3114, '① 군판사와 군검사가 법 제8조제1항에 따라 군교도소, 군교도소 지소(支所) 및 군미결수용실(이하 "군교정시설"이라 한다)을 시찰하려면 신분을 나타내는 증표를 소장에게 보여주고 시찰부에 서명 또는 날인하여야 한다. <개정 2022.6.30>', 1742);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3115, '② 소장은 군교도관에게 군판사나 군검사를 시찰하려는 장소로 안내하게 하고, 시찰한 시간을 시찰부에 기록하여야 한다. <개정 2022.6.30>', 1742);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3116, '① 군판사와 군검사 외의 사람이 법 제8조제2항에 따라  군교정시설을 참관하려면 다음 각 호의 사항을 적은 신청서를 소장에게 제출하여야 한다. <개정 2022.6.30>', 1743);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3117, '② 제1항에 따라 신청서를 받은 소장은 참관하려는 사람의 신분과 참관 목적 등을 확인한 후 허가 여부를 결정하여야 한다.', 1743);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3118, '③ 소장은 외국인에게 참관을 허가하려면 국방부장관의 승인을 받아야 한다. <개정 2014.10.28>', 1743);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3119, '④ 소장은 참관을 허가한 사람에게 미리 참관할 때의 주의사항을 알려주어야 한다.', 1743);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3120, null, 1745);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3121, '① 군교도관은 제6조제2호의 계호상 독거수용을 한 군수용자(이하 "계호독거자"라 한다)를 수시로 시찰하여 건강과 교화에 이상이 없는지 살펴야 한다.', 1746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3122, '② 군교도관은 계호독거자가 건강에 이상이 있다고 보일 때에는 즉시 해당 군교정시설을 담당하는 군의관에게 그 사실을 알려야 하고, 교화에 문제가 있다고 인정되면 즉시 소장에게 보고하여야 한다.', 1746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3123, '③ 제2항에 따라 통보받은 군의관은 즉시 계호독거자를 상담ㆍ진찰하는 등 적절한 의료조치를 하여야 하고, 독거수용을 계속하게 되면 건강을 해치게 된다고 판단될 때에는 그 사실을 즉시 소장에게 보고하여야 한다.', 1746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3124, '④ 소장은 계호독거자를 계속 독거수용하는 것이 건강이나 교화에 해롭다고 인정되면 즉시 독거수용을 중단하여야 한다.', 1746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3125, '① 소장은 거실에 면적, 정원 및 현재인원을 적은 현황표를 붙여야 한다.', 1752);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3126, '② 소장은 거실 앞에 군수용자의 이름표를 붙여야 한다. 이 경우 이름표 윗부분에는 군수용자의 성명, 출생연도, 죄명, 형명(刑名) 및 형기(刑期)를 적고, 아랫부분에는 군수용자 번호와 입소한 날짜를 적되, 윗부분의 내용은 보이지 않도록 하여야 한다. <개정 2014.10.28>', 1752);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3127, '③ 소장은 군수용자가 법령에 따라 지켜야 할 사항과 군수용자의 권리구제 절차에 관한 사항을 거실 안 군수용자가 보기 쉬운 곳에 붙이는 등의 방법으로 비치하여야 한다. <개정 2014.10.28>', 1752);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3128, '① 소장은 군사법원, 군검찰부, 군사경찰부대 등에서 처음으로 군교정시설에 수용되는 사람(이하 "신입자"라 한다)이나 다른 군교정시설로부터 이송(移送)되어 온 사람(이하 "이입자"라 한다)을 인수하였을 때에는 호송인(護送人)에게 인수서를 써 주어야 한다. 이 경우 신입자나 이입자에게 부상이나 질병, 그 밖에 건강에 이상이 있을 때에는 호송인으로부터 그 사실에 대한 확인서를 받아야 한다. <개정 2020.2.4>', 1753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3129, '② 신입자나 이입자를 인수한 군교도관은 제1항 전단의 인수서에 성명, 나이 및 인수 일시를 적고 서명 또는 날인하여야 한다.', 1753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3130, '③ 소장은 제1항 후단에 따라 확인서를 받았을 때에는 호송인에게 신입자나 이입자의 성명, 나이, 인계 일시 및 부상의 정도나 질병의 상태 등에 관한 사실을 적고 서명 또는 날인하도록 하여야 한다.', 1753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3131, '④ 소장은 신입자나 이입자가 감염병(「감염병의 예방 및 관리에 관한 법률」 제2조제2호에 따른 감염병을 말한다. 이하 같다)에 걸린 때에는 인수를 거부할 수 있다. 이 경우 수용을 지휘한 군검사와 소속 부대장 또는 이송 보낸 소장에게 즉시 그 사유를 통보하고 국방부장관에게 보고하여야 한다. <개정 2010.12.29, 2022.6.30>', 1753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3132, '⑤ 소장은 제4항에도 불구하고 감염병에 걸린 신입자나 이입자가 위독하여 다른 곳으로 이송할 만한 시간적 여유가 없을 때에는 그를 격리수용하고 즉시 필요한 조치를 하여야 한다. <개정 2010.12.29>', 1753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3133, '① 소장은 신입자의 키, 용모, 문신, 흉터 등 신체의 특징과 가족이나 보호자 등의 연락처를 제19조에 따른 수용기록부에 기록하여야 한다.', 1757);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3134, '② 소장은 업무상 필요한 경우가 아니면 군교도관이 제1항의 수용기록부를 열람하지 못하도록 하여야 한다.', 1757);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3135, '③ 소장은 신입자와 이입자에게 군수용자 번호를 지정하고, 상의 왼쪽 가슴 부위에 번호표를 붙이게 하여야 한다. 다만, 군수용자의 교화 또는 건전한 사회복귀를 위하여 특히 필요하다고 인정하면 번호표를 붙이지 아니할 수 있다.', 1757);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3136, '① 소장은 신입자 또는 이입자가 환자이거나 그 밖에 부득이한 사정이 있는 경우가 아니면 수용된 날부터 7일 동안 신입자만을 수용하는 거실(이하 "신입자거실"이라 한다)에 수용하여야 한다.', 1759);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3137, '② 소장은 신입자거실에 수용된 사람에게는 작업을 부과해서는 아니 된다.', 1759);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3138, '③ 소장은 신입자나 이입자의 처우를 위하여 특히 필요하다고 인정하면 제1항의 기간을 30일까지 연장할 수 있다.', 1759);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3139, '① 소장은 거실, 작업장, 그 밖에 군수용자가 생활하는 장소(이하 "거실등"이라 한다)에 수용생활에 필요한 기구를 갖춰 두어야 한다.', 1765);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3140, '② 거실등에는 제1항에 따라 갖춰 둔 기구의 품목과 수량을 기록한 품목표를 붙여 두어야 한다.', 1765);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3141, '① 소장은 군수용자가 사용하는 의류등을 적당한 시기에 세탁, 수선 또는 교체하여야 한다.', 1772);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3142, '② 자신의 비용으로 구매한 의류등의 세탁이나 수선에 필요한 비용은 군수용자가 부담한다.', 1772);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3143, '① 법 제25조제1항 각 호의 어느 하나에 해당하지 아니하는 휴대품은 영치한 후 사용하게 할 수 있다.', 1773);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3144, '② 소장은 법 제25조제1항 단서에 따라 군수용자의 휴대품을 팔 경우에는 그 비용을 제외한 나머지 대금을 영치할 수 있다.', 1773);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3145, '③ 소장은 법 제25조제1항 각 호의 어느 하나에 해당하는 휴대품을 국방부장관이 정한 기간 내에 처분하지 아니하면 폐기한다는 사실을 군수용자에게 알리고, 군수용자가 그 기간이 지날 때까지 처분하지 아니하면 이를 폐기하여야 한다.', 1773);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3146, '① 소장은 법 제27조제1항에 따라 교부를 허가한 금품의 내용이나 용도가 분명하여 검사할 필요가 없다고 인정되는 경우 외에는 군교도관에게 위해성(危害性)이나 안전성 등에 대하여 검사하게 하여야 한다. 이 경우 물품이 의약품인 경우에는 군의관에게 검사하게 하여야 한다.', 1780);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3147, '② 소장은 제1항에 따라 검사를 마친 금품을 영치한 후 사용하게 할 수 있다.', 1780);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3148, '① 소장은 법 제29조에 따라 군수용자가 영치금 사용을 신청한 경우에는 영치금이 정당한 용도에 사용되는지를 확인하고 허가할 수 있다.', 1782);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3149, '② 제1항에 따라 영치금을 사용하는 경우 발생하는 비용은 군수용자가 부담한다.', 1782);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3150, '③ 영치금의 출납, 예탁(預託), 영치금품의 보관 등에 필요한 사항은 국방부장관이 정한다.', 1782);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3151, '① 소장은 거실등과 목욕탕, 취사장, 주식ㆍ부식 저장고, 그 밖에 음식물 공급과 관련된 시설을 수시로 청소ㆍ소독하여야 한다.', 1784);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3152, '② 소장은 저수조(貯水槽) 등 급수시설을 6개월에 1회 이상 청소ㆍ소독하여야 한다.', 1784);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3153, null, 1786);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3154, '① 소장은 법 제35조에 따라 군수용자에 대하여 1년에 1회 이상 건강검진을 하여야 한다. 다만, 계호독거자에 대해서는 6개월에 1회 이상 하여야 한다.', 1788);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3155, '② 제1항의 건강검진은 「건강검진기본법」 제14조에 따라 지정된 건강검진기관에 의뢰하여 할 수 있다.', 1788);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3156, '① 소장은 법 제36조에 따라 군수용자가 감염병에 걸렸다고 의심되는 경우에는 1주 이상 격리수용하고, 그의 휴대품을 소독하여야 한다. <개정 2010.12.29>', 1789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3157, '② 소장은 감염병이 유행하고 있을 때에는 군수용자가 자신의 비용으로 구매한 음식물의 공급을 중지할 수 있다. <개정 2010.12.29>', 1789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3158, '③ 소장은 군수용자가 감염병에 걸렸을 때에는 즉시 격리수용하고, 그가 사용하였던 물품과 설비를 철저히 소독하여야 한다. <개정 2010.12.29>', 1789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3159, '④ 제3항의 경우 소장은 군수용자가 감염병에 걸린 사실을 지체 없이 국방부장관에게 보고하고, 관할 보건기관의 장에게 알려야 한다. <개정 2010.12.29>', 1789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3160, '① 소장은 법 제37조에 따라 군수용자가 부상을 당하거나 질병에 걸렸을 때에는 의료용 거실에 수용하거나 다른 군수용자에게 그를 간병(看病)하게 할 수 있다.', 1790);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3161, '② 소장은 특히 필요하다고 인정하면 군병원이 아닌 의료시설(이하 "외부의료시설"이라 한다)에서 근무하는 의사에게 군수용자를 치료하게 할 수 있다.', 1790);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3162, '③ 소장은 군수용자가 위독한 경우에는 그 사실을 가족에게 지체 없이 알려야 한다.', 1790);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3163, '① 소장은 법 제38조제1항에 따라 군수용자를 외부의료시설에서 진료를 받도록 결정하기 전에 미리 군의관의 의견을 들어야 한다.', 1791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3164, '② 소장은 법 제38조제1항에 따라 군수용자를 외부의료시설에 입원시키거나 입원 중인 군수용자를 군교정시설로 데려왔을 때에는 그 사실을 국방부장관에게 지체 없이 보고하여야 한다.', 1791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3165, '① 법 제42조제1항에 따른 군수용자의 접견은 매일(공휴일 및 국방부장관이 정한 날은 제외한다) 군 표준일과표에 따른 근무시간에 한다.', 1792);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3166, '② 군수용자의 접견시간은 1회당 30분 이내로 한다. 다만, 군미결수용자가 변호인과 접견하는 경우에는 접견시간을 제한하지 아니한다.', 1792);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3167, '③ 군수형자의 접견 횟수는 매월 4회 이상으로 하되, 제77조제2항에 따라 부여한 처우등급별 접견 횟수는 국방부령으로 정한다.', 1792);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3168, '④ 군수용자의 접견은 접촉 차단시설이 설치된 장소(이하 "접견실"이라 한다)에서 하게 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그러하지 아니하다. <개정 2014.10.28>', 1792);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3169, '⑤ 법 및 이 영에서 규정한 사항 외에 군수형자, 사형확정자 및 군미결수용자 외의 군수용자에 대한 접견 횟수ㆍ시간ㆍ장소 등에 관하여 필요한 사항은 국방부장관이 정한다.', 1792);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3170, '① 소장은 제53조제1항 및 제2항에도 불구하고 군수형자의 교화 또는 건전한 사회복귀를 위하여 특히 필요하다고 인정하면 군 표준일과표에 따른 근무시간 외의 시간에도 접견하게 할 수 있고, 접견시간을 연장할 수 있다.', 1793);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3171, '② 소장은 제53조제3항에도 불구하고 군수형자가 다음 각 호의 어느 하나에 해당하는 경우에는 접견 횟수를 늘릴 수 있다.', 1793);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3172, '③ 소장은 제53조제4항 본문에도 불구하고 군수형자가 제2항 각 호에 해당하는 경우에는 접견실 외의 장소에서 접견하게 할 수 있다.', 1793);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3173, '① 소장은 법 제42조제2항에 따라 접견내용을 청취ㆍ기록하기 위하여 군교도관이나 교도병(군교정시설에서 군교도관의 업무를 보조하는 병을 말한다. 이하 같다)을 접견에 참여하게 할 수 있다. 다만, 군미결수용자가 변호인과 접견하는 경우는 제외한다.', 1795);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3174, '② 소장은 법 제42조제2항 후단에 따라 군수용자와 군수용자가 아닌 사람에게 외국어를 사용하게 할 때에는 군교도관이나 통역인으로 하여금 통역하게 할 수 있다.', 1795);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3175, '③ 소장은 법 제42조제3항에 따라 군수용자와 그 상대방에게 접견실에 들어가기 전에 미리 접견내용을 청취ㆍ녹음 또는 녹화한다는 사실을 말이나 서면 등 적절한 방법으로 알려주어야 한다.', 1795);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3176, '① 소장은 접견내용을 청취ㆍ기록ㆍ녹음 및 녹화한 경우의 접견기록물에 대한 보호ㆍ관리를 위하여 접견정보 취급자를 지정하여야 한다.', 1796);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3177, '② 제1항에 따라 지정된 접견정보 취급자는 직무상 알게 된 접견정보를 누설하거나, 권한 없이 처리하거나, 다른 사람이 이용하도록 제공하는 등 부당한 목적을 위하여 사용해서는 아니 된다.', 1796);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3178, '③ 소장은 다음 각 호의 어느 하나에 해당하는 경우에는 접견기록물을 관계 기관에 제공할 수 있다.', 1796);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3179, '④ 소장은 제3항에 따라 접견기록물을 제공할 때에는 제1항에 따라 지정된 접견정보 취급자에게 접견기록물을 요청한 기관의 명칭, 받으려는 목적, 제공 근거, 제공을 요청한 범위, 그 밖에 필요한 사항을 접견기록물 관리부에 기록하게 하고, 따로 이동식 저장매체에 옮겨 담아 제공하여야 한다.', 1796);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3180, '① 군수용자는 서신을 보내려는 경우 해당 서신을 봉함하여 군교정시설에 제출한다. 다만, 소장은 다음 각 호의 어느 하나에 해당하는 경우로서 법 제44조제3항에 따른 금지물품의 확인을 위하여 필요한 경우에는 서신을 봉함하지 아니한 상태로 제출하게 할 수 있다. <개정 2013.9.26>', 1799);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3181, '② 소장은 군수용자에게 온 서신에 법령에서 금지한 물품이 들어 있는지를 개봉하여 확인할 수 있다.', 1799);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3182, '① 법 제44조제4항제4호에서 "대통령령으로 정하는 군수용자 사이의 서신"이란 다음 각 호의 어느 하나에 해당하는 군수용자가 다른 군수용자와 주고받는 서신을 말한다.', 1800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3183, '② 군수용자 사이에 오가는 서신에 대한 검열은 서신을 보내는 군교정시설에서 한다. 다만, 특히 필요하다고 인정되는 경우에는 서신을 받는 군교정시설에서도 할 수 있다.', 1800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3184, '③ 소장은 군수용자가 주고받는 서신이 법 제44조제4항 각 호의 어느 하나에 해당하면 이를 개봉한 후 검열할 수 있다. <신설 2013.9.26>', 1800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3185, '④ 소장은 제3항에 따라 서신을 검열한 결과 그 내용이 법 제44조제5항의 발신 또는 수신 금지사유에 해당하지 아니하면 발신서신은 봉함한 후 발송하고, 수신서신은 군수용자에게 교부한다. <신설 2013.9.26>', 1800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3186, '⑤ 소장은 서신의 내용을 검열하였을 때에는 그 사실을 해당 군수용자에게 지체 없이 알려 주어야 한다. <신설 2013.9.26>', 1800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3187, '① 군수용자는 법 제45조에 따라 전화통화를 허가받으려면 미리 전화번호와 수신자를 지정하여 신청하여야 한다.', 1804);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3188, '② 전화통화는 발신(發信)으로 한정하고, 통화시간은 특별한 사정이 없으면 3분 이내로 한다.', 1804);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3189, '① 법 제45조에 따른 전화통화는 매일(공휴일 및 국방부장관이 정한 날은 제외한다) 군 표준일과표에 따른 근무시간에 할 수 있다.', 1805);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3190, '② 소장은 제1항에도 불구하고 평일에 전화통화가 곤란한 특별한 사유가 있는 군수용자에 대해서는 전화통화 시간을 따로 정할 수 있다.', 1805);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3191, '① 소장은 법 제45조제2항에 따라 전화통화를 허가할 때에는 법 제42조제2항 각 호의 어느 하나에 해당하지 아니한다고 명백히 인정되는 경우 외에는 군수용자의 통화내용을 청취 또는 녹음하는 것을 조건으로 붙여야 한다.', 1806);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3192, '② 소장은 제45조제4항에 따라 군수용자에게 전화통화를 하기 전에 미리 통화내용을 청취하거나 녹음한다는 사실을 말이나 서면 등 적절한 방법으로 알려주어야 한다.', 1806);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3193, '③ 제1항에 따라 녹음한 기록물은 「공공기록물 관리에 관한 법률」에 따라 관리하고, 특히 녹음한 기록물이 손상되지 않도록 그 보존에 주의하여야 한다.', 1806);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3194, '④ 군교도관은 군수용자 전화통화의 청취ㆍ녹음을 통하여 알게 된 내용을 누설하거나, 권한 없이 처리하거나, 타인의 이용에 제공하는 등 부당한 목적으로 사용해서는 아니 된다.', 1806);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3195, '⑤ 제1항에 따라 녹음한 기록물을 관계 기관에 제공하는 것에 관하여는 제57조제3항 및 제4항을 준용한다.', 1806);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3196, '① 군수용자의 전화통화 요금은 군수용자의 부담으로 한다.', 1807);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3197, '② 소장은 군수용자가 교정성적이 양호하거나 영치금이 없는 등 특히 필요하다고 인정하는 경우에는 예산의 범위에서 요금을 부담할 수 있다.', 1807);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3198, '① 소장은 법 제47조에 따라 군수용자가 쉽게 이용할 수 있도록 도서를 갖춰 두고 그 목록을 정기적으로 공개하여야 한다.', 1810);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3199, '② 제1항에 따라 갖춰 둔 도서의 열람방법, 열람기간 등에 관하여 필요한 사항은 국방부장관이 정한다.', 1810);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3200, '① 법 제50조에 따른 집필에 필요한 집필용구는 거실의 집필용구 보관함에 보관하여 관리한다.', 1812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3201, '② 거실에는 집필용구의 품목과 수량을 기록한 집필용구 품목표를 붙여 두어야 한다.', 1812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3202, '③ 집필용구의 구입비용은 군수용자가 부담한다. 다만, 소장은 군수용자가 그 비용을 부담할 수 없는 경우에는 필요한 집필용구를 지급할 수 있다.', 1812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3203, '① 군수용자는 휴업일과 휴게시간에 시간의 제한 없이 집필할 수 있다. 다만, 부득이한 사정이 있는 경우에는 그러하지 아니하다.', 1813);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3204, '② 군수용자는 거실, 작업장, 그 밖에 지정된 장소에서 집필할 수 있다.', 1813);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3205, '① 소장은 군수용자가 자신이 작성하거나 집필한 문서 또는 도화를 외부로 보내거나 내가려고 하는 경우에는 그 내용을 확인하여 법 제44조제5항 각 호의 어느 하나에 해당하지 아니하면 허가하여야 한다.', 1814);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3206, '② 제1항에 따라 문서 또는 도화를 외부로 보내거나 내가는 데에 드는 비용은 군수용자가 부담한다.', 1814);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3207, '③ 법 및 이 영에서 규정한 사항 외에 군수용자의 집필에 필요한 사항은 국방부장관이 정한다.', 1814);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3208, '① 소장은 자유형(自由刑)이 확정된 군미결수용자에 대해서는 군검사의 집행 지휘서가 도달된 때부터 군수형자로 처우하여야 한다. <개정 2022.6.30>', 1815);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3209, '② 군검사는 집행 지휘를 한 날부터 10일 이내에 재판서(裁判書)나 그 밖에 적법한 서류를 소장에게 보내야 한다. <개정 2022.6.30>', 1815);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3210, '① 소장은 법 제51조에 따른 군수형자의 처우를 위하여 개별처우계획을 수립하여야 한다.', 1816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3211, '② 소장은 제1항에 따른 개별처우계획의 시행에 적합하게 정하거나 조정하기 위하여 교정성적에 따라 처우등급을 부여할 수 있다.', 1816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3212, '③ 군수형자에게 부여하는 처우등급에 관하여 필요한 사항은 국방부령으로 정한다.', 1816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3213, '① 소장은 법 제53조에 따른 교육을 효과적으로 시행하기 위하여 교육실을 설치하는 등 교육에 적합한 환경을 조성하여야 한다.', 1818);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3214, '② 소장은 교육 대상자, 시설 여건 등을 고려하여 교육계획을 수립하여 시행하여야 한다.', 1818);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3215, '① 소장은 법 제55조에 따라 군수형자에게 작업을 부과하는 경우에는 작업의 종류와 작업과정을 정하여 알려야 한다.', 1820);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3216, '② 제1항의 작업과정은 작업성적, 작업시간, 작업의 난이도 및 숙련도를 고려하여 정한다. 이 경우 작업과정을 정하기 어려우면 작업시간을 작업과정으로 본다.', 1820);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3217, '③ 군수형자에게 부과하는 작업의 종류, 작업과정 및 작업시간 등의 세부 사항은 국방부령으로 정한다.', 1820);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3218, '① 소장은 법 제66조에 따라 2일 이상의 귀휴(歸休)를 허가하였을 때에는 귀휴를 허가받은 군수형자의 귀휴지(법 제66조제1항에 따라 정한 행선지를 말한다)를 관할하는 군사경찰부대나 국가경찰관서의 장에게 그 사실을 통보하여야 한다. <개정 2020.2.4>', 1825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3219, '② 귀휴 중인 군수형자는 천재지변이나 그 밖의 사유로 자신의 신상에 중대한 사고가 발생하였을 때에는 가까운 군교정시설, 군사경찰부대 또는 국가경찰관서에 신고하여야 하고, 필요한 보호를 요청할 수 있다. <개정 2020.2.4>', 1825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3220, '③ 제2항에 따른 보호 요청을 받은 군교정시설, 군사경찰부대 또는 국가경찰관서의 장은 귀휴를 허가한 소장에게 그 사실을 지체 없이 통보하고 적절한 보호조치를 하여야 한다. <개정 2020.2.4>', 1825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3221, '① 법 제75조제1항에 따른 군미결수용자에 대한 교육ㆍ교화 프로그램이나 작업은 군교정시설 밖에서 실시하거나 부과하지 아니한다.', 1830);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3222, '② 소장은 법 제75조제1항에 따라 작업이 부과된 군미결수용자가 작업의 취소를 요청하는 경우에는 그 군미결수용자의 의사, 건강 및 군교도관의 의견 등을 고려하여 작업을 취소할 수 있다.', 1830);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3223, '① 소장은 사형을 집행하였을 때에는 군의관에게 시신을 검사하게 하여 사망하였음을 확인한 후가 아니면 시신의 이전 등 다른 조치를 하지 못한다. <개정 2014.10.28>', 1836);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3224, '② 사형 집행 시 군검사는 사형확정자의 유언을 기록하고 날인한 후 친족 또는 친지에게 전달하여야 한다. <개정 2022.6.30>', 1836);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3225, '① 군교정시설의 바깥문, 출입구, 거실, 작업장, 그 밖에 군수용자를 수용하고 있는 장소는 외부와 차단하여야 한다. 다만, 필요에 따라 일시 개방하는 경우에는 그 장소를 경비하여야 한다.', 1841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3226, '② 군교도관은 접견, 상담, 진료, 그 밖에 군수용자의 처우를 위하여 필요한 경우가 아니면 군수용자와 외부인이 접촉하게 해서는 아니 된다.', 1841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3227, '① 법 제82조제5항 및 제83조제4항에 따라 군의관이 보호실이나 진정실에 수용된 군수용자의 건강을 확인한 결과 보호실이나 진정실에 계속 수용하는 것이 부적당하다고 인정하는 경우에는 소장에게 즉시 보고하여야 한다. 이 경우 소장은 특별한 사유가 없으면 보호실이나 진정실에 수용하는 것을 즉시 중지하여야 한다.', 1844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3228, '② 소장은 군의관이 출장, 휴가, 그 밖의 부득이한 사유로 법 제82조제5항 또는 제83조제4항의 직무를 수행할 수 없을 때에는 군교정시설에 근무하는 의료 관계자에게 그 직무를 대행하게 할 수 있다.', 1844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3229, '① 군교도관은 소장의 명령 없이 군수용자에게 법 제85조제1항에 따른 보호장비를 사용해서는 아니 된다. 다만, 소장의 명령을 받을 시간적 여유가 없는 경우에는 보호장비를 사용한 후 소장에게 즉시 보고하여야 한다.', 1845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3230, '② 군교도관이 보호장비를 사용할 때에는 군수용자에게 그 사유를 알려주어야 한다.', 1845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3231, '③ 군의관은 군수용자에게 보호장비를 계속 사용하는 것이 건강상 부적당하다고 인정하는 경우에는 소장에게 즉시 보고하여야 한다. 이 경우 소장은 특별한 사유가 없으면 보호장비 사용을 즉시 중지하여야 한다.', 1845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3232, '④ 군의관이 출장, 휴가, 그 밖의 부득이한 사유로 법 제84조제3항의 직무를 수행할 수 없을 때에는 군교정시설에 근무하는 의료관계자에게 그 직무를 대행하게 할 수 있다.', 1845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3233, '① 소장은 제106조제1항에 따라 보호장비의 사용을 명령한 경우에는 수시로 그 사용 실태를 확인ㆍ점검하여야 한다.', 1847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3234, '② 국방부장관은 군교정시설의 보호장비 사용 실태를 정기적으로 점검하여야 한다. <개정 2014.10.28>', 1847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3235, '① 소장은 교정성적이 우수한 군수형자를 선정하여 법 제89조제1항에 따른 응급용무의 보조에 필요한 훈련을 시킬 수 있다.', 1850);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3236, '② 소장은 법 제89조제3항에 따라 군수용자를 일시 석방할 때에는 출석하여야 할 시한과 출석할 장소를 미리 알려주어야 한다.', 1850);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3237, '① 소장은 군수용자가 도주하거나 법 제117조 각 호의 어느 하나에 해당하는 행위(이하 이 조에서 "도주등"이라 한다)를 하였을 때에는 군교정시설의 소재지와 그 인접 지역 또는 도주등을 한 사람(이하 이 조에서 "도주자등"이라 한다)이 숨을 만한 지역의 군사경찰부대나 국가경찰관서에 도주자등의 사진이나 인상착의를 기록한 서면을 첨부하여 그 사실을 지체 없이 통보하여야 한다. <개정 2020.2.4>', 1851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3238, '② 소장은 군수용자가 도주등을 하거나 도주자등을 체포한 경우에는 국방부장관에게 지체 없이 보고하여야 한다.', 1851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3239, null, 1852);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3240, '① 위원회의 외부인사인 위원은 다음 각 호의 어느 하나에 해당하는 사람 중에서 소장이 위촉한다. <개정 2012.2.29>', 1853);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3241, '② 제1항에 따라 위촉된 위원의 임기는 2년으로 한다.', 1853);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3242, '③ 소장은 제1항에 따라 위촉된 위원이 직무를 게을리하거나, 품위를 손상하였거나, 특정한 종파나 특정한 사상에 치우쳐 징벌의 공정성을 해칠 우려가 있다고 인정되면 그 위원을 해촉할 수 있다.', 1853);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3243, '① 위원장은 위원회를 대표하고, 위원회의 업무를 총괄한다.', 1854);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3244, '② 위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 위원장이 미리 지명한 위원이 그 직무를 대행한다.', 1854);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3245, '① 위원회에 위원회의 사무를 처리할 간사 1명을 둔다.', 1855);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3246, '② 간사는 군교도관 중에서 소장이 임명한다.', 1855);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3247, '① 소장은 법 제98조에 따라 위원회가 의결한 징벌을 지체 없이 집행하여야 한다.', 1858);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3248, '② 소장은 군수용자에 대하여 법 제94조제9호의 전화통화 제한, 같은 조 제11호의 서신수수 제한 또는 같은 조 제12호의 접견 제한 징벌을 부과하였을 때에는 군수용자의 가족에게 그 사실을 알려야 한다. 다만, 군수용자가 통지를 원하지 아니하면 그러하지 아니하다.', 1858);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3249, '③ 소장은 법 제94조제14호의 금치(禁置) 징벌을 집행할 때에도 군수용자의 기본적인 건강유지를 위하여 필요하다고 인정하면 실외운동을 허가할 수 있다.', 1858);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3250, '④ 소장은 법 제98조제13호의 실외운동 정지나 같은 조 제14호의 금치 징벌의 집행을 마쳤을 때에는 군의관에게 해당 군수용자의 건강 상태를 지체 없이 확인하게 하여야 한다.', 1858);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3251, '⑤ 군의관이 출장, 휴가, 그 밖의 부득이한 사유로 법 제98조제4항이나 이 조 제4항의 직무를 수행할 수 없을 때에는 군교정시설에 근무하는 의료 관계자에게 그 직무를 대행하게 할 수 있다.', 1858);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3252, '① 소장은 법 제101조제1항에 따라 군수용자가 면담을 신청하였을 때에는 군수용자의 인적사항을 면담부에 적고, 특별한 사정이 없으면 신청한 순서에 따라 면담하여야 한다.', 1863);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3253, '② 소장은 제1항에 따라 군수용자를 면담하였을 때에는 그 요지를 면담부에 적어야 한다.', 1863);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3254, '③ 소장은 법 제101조제2항 각 호의 어느 하나에 해당하여 군수용자의 면담 신청을 받아들이지 아니하였을 때에는 그 사유를 해당 군수용자에게 알려주어야 한다.', 1863);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3255, '① 소장은 군수용자가 법 제102조제1항에 따라 순회점검공무원(법 제7조에 따라 국방부장관으로부터 순회점검의 명을 받은 공무원을 말한다. 이하 같다)에게 청원하는 경우에는 그 인적사항을 청원부에 기록하여야 한다. <개정 2014.10.28>', 1864);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3256, '② 순회점검공무원은 법 제102조제2항 단서에 따라 군수용자가 말로 청원하는 경우에는 그 요지를 청원부에 기록하여야 한다. <개정 2014.10.28>', 1864);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3257, '③ 순회점검공무원은 법 제102조에 따른 군수용자의 청원에 대하여 결정하였을 때에는 그 요지를 청원부에 기록하여야 한다. <개정 2014.10.28>', 1864);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3258, '④ 순회점검공무원은 법 제102조에 따른 군수용자의 청원에 대하여 스스로 결정하는 것이 부적당하다고 인정하는 경우에는 그 내용을 국방부장관에게 보고하여야 한다. <개정 2014.10.28>', 1864);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3259, '⑤ 군수용자의 청원 처리의 기준ㆍ절차 등에 관하여 필요한 사항은 국방부장관이 정한다.', 1864);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3260, null, 1865);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3261, '① 군의관은 군수용자가 질병으로 사망한 경우에는 사망기록부에 병명, 병력(病歷), 사인 및 사망 일시를 기록하고 서명하여야 한다.', 1873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3262, '② 소장은 군수용자가 자살하거나 변사(變事)한 경우에는 그 사실을 즉시 군검사(기소된 군수용자인 경우에는 군사법원을 포함한다)에게 통보하고, 그 시신을 검사한 후 사망기록부에 검시자와 참여자의 성명, 신분 및 검시 결과를 기록하여야 한다. <개정 2014.10.28, 2022.6.30>', 1873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3263, '③ 소장은 법 제78조에 따라 사형을 집행하였을 때에는 사망기록부에 집행일시, 집행장소, 검시자와 참여자의 성명 및 유언이 있었는지를 기록하여야 한다.', 1873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3264, '④ 소장은 법 제113조에 따라 시신을 인도(引渡)하거나, 화장(火葬), 임시 매장 또는 합장(合葬)한 경우에는 그 사실을 사망기록부에 기록하여야 한다.', 1873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3265, '① 소장은 법 제113조제2항 단서에 따라 시신을 화장하였을 때에는 유골을 인수할 사람이 없으면 임시 매장하고, 임시 매장 후 2년이 지나도 인도를 청구하는 사람이 없으면 합장할 수 있다.', 1874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3266, '② 소장은 법 제113조제3항에 따라 시신을 화장한 경우에는 그 유골을 합장할 수 있다.', 1874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3267, '① 소장은 법 제113조제2항에 따라 시신을 임시 매장한 경우에는 그 장소에 사망자의 가족관계등록기준지, 성명, 사망 일시를 적은 표지를 세워야 한다.', 1875);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3268, '② 소장은 법 제113조제3항에 따라 시신 또는 유골을 합장한 경우에는 합장된 사람의 가족관계등록기준지, 성명, 사망 일시를 합장기록부에 기록하고 그 장소에 묘비를 세워야 한다.', 1875);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3269, '① 소장은 군수용자의 안정된 수용생활과 교화를 위하여 법 제114조에 따른 교정위원에게 군수용자를 교화상담하게 할 수 있다.', 1876);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3270, '② 교정위원은 군수용자의 고충 처리나 교정ㆍ교화를 위하여 필요한 의견을 소장에게 건의할 수 있다.', 1876);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3271, '① 소장은 법 제115조에 따라 기부금품을 접수하였을 때에는 기부금품 접수대장에 등록하고, 기부한 기관, 단체 또는 개인(이하 이 조에서 "기부자"라 한다)에게 영수증을 발급하여야 한다. 다만, 익명으로 기부하거나 기부자를 알 수 없는 경우에는 영수증을 발급하지 아니한다.', 1877);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3272, '② 소장은 기부자가 용도를 지정하여 금품을 기부한 경우에는 기부금품을 그 용도에 사용하여야 한다. 다만, 지정한 용도로 사용하기 어려운 특별한 사유가 있는 경우에는 기부자의 동의를 받아 다른 용도로 사용할 수 있다.', 1877);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3273, '③ 소장은 기부금품 접수대장과 기부금품의 사용결과를 기록한 장부를 갖춰 두고, 기부자가 열람할 수 있도록 하여야 한다.', 1877);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3274, '④ 제1항부터 제3항까지에서 규정한 사항 외에 군교정시설의 기부금품 접수ㆍ사용 등에 필요한 사항은 국방부장관이 정한다.', 1877);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3275, '① 국방부장관은 법 제115조의2에 따라 다음 각 호의 업무에 관한 권한을 각 군의 참모총장에게 위임한다.', 1878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3276, '② 국방부장관은 법 제115조의2에 따라 다음 각 호의 업무에 관한 권한을 국방부조사본부장에게 위임한다.', 1878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3277, '① 「형의 집행 및 수용자의 처우에 관한 법률」(이하 "법"이라 한다) 제5조의3에 따른 협의체(이하 "협의체"라 한다)는 위원장을 포함하여 12명의 위원으로 구성한다.', 1880);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3278, '② 협의체의 위원장은 법무부차관이 되고, 협의체의 위원은 다음 각 호의 사람이 된다.', 1880);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3279, '③ 협의체의 위원장은 협의체 회의를 소집하며, 회의 개최 7일 전까지 회의의 일시ㆍ장소 및 안건 등을 각 위원에게 알려야 한다.', 1880);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3280, '④ 협의체의 위원장은 협의체의 회의 결과를 위원이 소속된 기관의 장에게 통보해야 한다.', 1880);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3281, '① 판사 또는 검사가 법 제9조제1항에 따라 교도소ㆍ구치소 및 그 지소(이하 "교정시설"이라 한다)를 시찰할 경우에는 미리 그 신분을 나타내는 증표를 교정시설의 장(이하 "소장"이라 한다)에게 제시해야 한다. <개정 2018.12.24, 2019.10.22>', 1881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3282, '② 소장은 제1항의 경우에 교도관에게 시찰을 요구받은 장소를 안내하게 해야 한다. <개정 2018.12.24>', 1881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3283, '① 소장은 법 제9조제2항에 따라 판사와 검사 외의 사람이 교정시설의 참관을 신청하는 경우에는 그 성명ㆍ직업ㆍ주소ㆍ나이ㆍ성별 및 참관 목적을 확인한 후 허가 여부를 결정하여야 한다.', 1882);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3284, '② 소장은 외국인에게 참관을 허가할 경우에는 미리 관할 지방교정청장의 승인을 받아야 한다.', 1882);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3285, '③ 소장은 제1항 및 제2항에 따라 허가를 받은 사람에게 참관할 때의 주의사항을 알려주어야 한다.', 1882);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3286, null, 1884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3287, '① 교도관은 제5조제2호에 따라 독거수용된 사람(이하 "계호상 독거수용자"라 한다)을 수시로 시찰하여 건강상 또는 교화상 이상이 없는지 살펴야 한다.', 1885);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3288, '② 교도관은 제1항의 시찰 결과, 계호상 독거수용자가 건강상 이상이 있는 것으로 보이는 경우에는 교정시설에 근무하는 의사(공중보건의사를 포함한다. 이하 "의무관"이라 한다)에게 즉시 알려야 하고, 교화상 문제가 있다고 인정하는 경우에는 소장에게 지체 없이 보고하여야 한다.', 1885);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3289, '③ 의무관은 제2항의 통보를 받은 즉시 해당 수용자를 상담ㆍ진찰하는 등 적절한 의료조치를 하여야 하며, 계호상 독거수용자를 계속하여 독거수용하는 것이 건강상 해롭다고 인정하는 경우에는 그 의견을 소장에게 즉시 보고하여야 한다.', 1885);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3290, '④ 소장은 계호상 독거수용자를 계속하여 독거수용하는 것이 건강상 또는 교화상 해롭다고 인정하는 경우에는 이를 즉시 중단하여야 한다.', 1885);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3291, '① 소장은 수용자거실에 면적, 정원 및 현재인원을 적은 현황표를 붙여야 한다.', 1891);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3292, '② 소장은 수용자거실 앞에 이름표를 붙이되, 이름표 윗부분에는 수용자의 성명ㆍ출생연도ㆍ죄명ㆍ형명(刑名) 및 형기(刑期)를 적고, 그 아랫부분에는 수용자번호 및 입소일을 적되, 윗부분의 내용이 보이지 않도록 해야 한다. <개정 2014.6.25, 2020.8.5>', 1891);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3293, '③ 소장은 수용자가 법령에 따라 지켜야 할 사항과 수용자의 권리구제 절차에 관한 사항을 수용자거실의 보기 쉬운 장소에 붙이는 등의 방법으로 비치하여야 한다. <개정 2014.6.25>', 1891);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3294, '① 소장은 법원ㆍ검찰청ㆍ경찰관서 등으로부터 처음으로 교정시설에 수용되는 사람(이하 "신입자"라 한다)을 인수한 경우에는 호송인(護送人)에게 인수서를 써 주어야 한다. 이 경우 신입자에게 부상ㆍ질병, 그 밖에 건강에 이상(이하 이 조에서 "부상등"이라 한다)이 있을 때에는 호송인으로부터 그 사실에 대한 확인서를 받아야 한다.', 1892);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3295, '② 신입자를 인수한 교도관은 제1항의 인수서에 신입자의 성명, 나이 및 인수일시를 적고 서명 또는 날인하여야 한다.', 1892);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3296, '③ 소장은 제1항 후단에 따라 확인서를 받는 경우에는 호송인에게 신입자의 성명, 나이, 인계일시 및 부상등의 사실을 적고 서명 또는 날인하도록 하여야 한다.', 1892);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3297, '① 소장은 신입자의 키ㆍ용모ㆍ문신ㆍ흉터 등 신체 특징과 가족 등 보호자의 연락처를 수용기록부에 기록하여야 하며, 교도관이 업무상 필요한 경우가 아니면 이를 열람하지 못하도록 하여야 한다.', 1896);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3298, '② 소장은 신입자 및 다른 교정시설로부터 이송(移送)되어 온 사람(이하 "이입자"라 한다)에 대하여 수용자번호를 지정하고 수용 중 번호표를 상의의 왼쪽 가슴에 붙이게 하여야 한다. 다만, 수용자의 교화 또는 건전한 사회복귀를 위하여 특히 필요하다고 인정하면 번호표를 붙이지 아니할 수 있다.', 1896);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3299, '① 소장은 신입자가 환자이거나 부득이한 사정이 있는 경우가 아니면 수용된 날부터 3일 동안 신입자거실에 수용하여야 한다.', 1897);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3300, '② 소장은 제1항에 따라 신입자거실에 수용된 사람에게는 작업을 부과해서는 아니 된다.', 1897);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3301, '③ 소장은 19세 미만의 신입자 그 밖에 특히 필요하다고 인정하는 수용자에 대하여는 제1항의 기간을 30일까지 연장할 수 있다.', 1897);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3302, '①소장은 신입자의 신원에 관한 사항을 조사하여 수용기록부에 기록하여야 한다. <개정 2012.1.6>', 1899);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3303, '② 소장은 신입자의 본인 확인 및 수용자의 처우 등을 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보, 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <신설 2012.1.6>', 1899);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3304, '① 지방교정청장은 법 제20조제2항에 따라 다음 각 호의 어느 하나에 해당하는 경우에는 수용자의 이송을 승인할 수 있다.', 1901);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3305, '② 제1항에 따른 지방교정청장의 이송승인은 관할 내 이송으로 한정한다.', 1901);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3306, '① 소장은 법 제22조제1항에 따라 의류ㆍ침구, 그 밖의 생활용품(이하 "의류등"이라 한다)을 지급하는 경우에는 수용자의 건강, 계절 등을 고려하여야 한다.', 1904);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3307, '② 소장은 수용자에게 특히 청결하게 관리할 수 있는 재질의 식기를 지급하여야 하며, 다른 사람이 사용한 의류등을 지급하는 경우에는 세탁하거나 소독하여 지급하여야 한다.', 1904);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3308, '① 소장은 거실ㆍ작업장, 그 밖에 수용자가 생활하는 장소(이하 이 조에서 "거실등"이라 한다)에 수용생활에 필요한 기구를 갖춰 둬야 한다.', 1905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3309, '② 거실등에는 갖춰 둔 기구의 품목ㆍ수량을 기록한 품목표를 붙여야 한다.', 1905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3310, '① 수용자에게 지급하는 주식은 쌀로 한다. <개정 2014.6.25>', 1907);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3311, '② 소장은 쌀 수급이 곤란하거나 그 밖에 필요하다고 인정하면 주식을 쌀과 보리 등 잡곡의 혼합곡으로 하거나 대용식을 지급할 수 있다. <개정 2014.6.25>', 1907);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3312, '① 소장은 수용자가 사용하는 의류등을 적당한 시기에 세탁ㆍ수선 또는 교체(이하 이 조에서 "세탁등"이라 한다)하도록 하여야 한다.', 1912);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3313, '② 자비로 구매한 의류등을 세탁등을 하는 경우 드는 비용은 수용자가 부담한다.', 1912);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3314, '① 법 제25조에서 "휴대금품"이란 신입자가 교정시설에 수용될 때에 지니고 있는 현금(자기앞수표를 포함한다. 이하 같다)과 휴대품을 말한다.', 1913);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3315, '② 법 제25조제1항 각 호의 어느 하나에 해당하지 아니한 신입자의 휴대품은 보관한 후 사용하게 할 수 있다. <개정 2020.8.5>', 1913);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3316, '③ 법 제25조제1항 단서에 따라 신입자의 휴대품을 팔 경우에는 그 비용을 제외한 나머지 대금을 보관할 수 있다. <개정 2020.8.5>', 1913);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3317, '④ 소장은 신입자가 법 제25조제1항 각 호의 어느 하나에 해당하는 휴대품을 법무부장관이 정한 기간에 처분하지 않은 경우에는 본인에게 그 사실을 고지한 후 폐기한다.', 1913);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3318, '① 소장은 수용자가 그의 가족(배우자, 직계존비속 또는 형제자매를 말한다. 이하 같다) 또는 배우자의 직계존속에게 도움을 주거나 그 밖에 정당한 용도로 사용하기 위하여 보관금의 사용을 신청한 경우에는 그 사정을 고려하여 허가할 수 있다. <개정 2020.8.5>', 1917);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3319, '② 제1항에 따라 보관금을 사용하는 경우 발생하는 비용은 수용자가 부담한다. <개정 2020.8.5>', 1917);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3320, '③ 보관금의 출납ㆍ예탁(預託), 보관금품의 보관 등에 관하여 필요한 사항은 법무부장관이 정한다. <개정 2020.8.5>', 1917);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3321, '① 소장은 법 제27조제1항에 따라 수용자에 대한 금품의 전달을 허가한 경우에는 그 금품을 보관한 후 해당 수용자가 사용하게 할 수 있다. <개정 2020.8.5>', 1921);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3322, '② 법 제27조제1항에 따라 수용자에게 건네주려고 하는 금품의 허가범위 등에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2020.8.5>', 1921);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3323, '① 소장은 사망자의 유류품을 건네받을 사람이 원거리에 있는 등 특별한 사정이 있는 경우에는 유류품을 받을 사람의 청구에 따라 유류품을 팔아 그 대금을 보낼 수 있다. <개정 2020.8.5>', 1924);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3324, '② 법 제28조에 따라 사망자의 유류금품을 보내거나 제1항에 따라 유류품을 팔아 대금을 보내는 경우에 드는 비용은 유류금품의 청구인이 부담한다.', 1924);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3325, '① 소장은 거실ㆍ작업장ㆍ목욕탕, 그 밖에 수용자가 공동으로 사용하는 시설과 취사장, 주식ㆍ부식 저장고, 그 밖에 음식물 공급과 관련된 시설을 수시로 청소ㆍ소독하여야 한다.', 1926);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3326, '② 소장은 저수조 등 급수시설을 6개월에 1회 이상 청소ㆍ소독하여야 한다.', 1926);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3327, null, 1928);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3328, '① 소장은 수용자에 대하여 1년에 1회 이상 건강검진을 하여야 한다. 다만, 19세 미만의 수용자와 계호상 독거수용자에 대하여는 6개월에 1회 이상 하여야 한다.', 1930);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3329, '② 제1항의 건강검진은 「건강검진기본법」 제14조에 따라 지정된 건강검진기관에 의뢰하여 할 수 있다. <개정 2009.3.18>', 1930);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3330, '① 소장은 수용자가 감염병에 걸렸다고 의심되는 경우에는 1주 이상 격리수용하고 그 수용자의 휴대품을 소독하여야 한다. <개정 2010.12.29>', 1932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3331, '② 소장은 감염병이 유행하는 경우에는 수용자가 자비로 구매하는 음식물의 공급을 중지할 수 있다. <개정 2010.12.29>', 1932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3332, '③ 소장은 수용자가 감염병에 걸린 경우에는 즉시 격리수용하고 그 수용자가 사용한 물품과 설비를 철저히 소독하여야 한다. <개정 2010.12.29>', 1932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3333, '④ 소장은 제3항의 사실을 지체 없이 법무부장관에게 보고하고 관할 보건기관의 장에게 알려야 한다.', 1932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3334, null, 1934);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3335, '① 수용자의 접견은 매일(공휴일 및 법무부장관이 정한 날은 제외한다) 「국가공무원 복무규정」 제9조에 따른 근무시간 내에서 한다.', 1938);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3336, '② 변호인(변호인이 되려고 하는 사람을 포함한다. 이하 같다)과 접견하는 미결수용자를 제외한 수용자의 접견시간은 회당 30분 이내로 한다. <개정 2014.6.25>', 1938);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3337, '③ 수형자의 접견 횟수는 매월 4회로 한다.', 1938);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3338, '④ 삭제 <2019.10.22>', 1938);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3339, '⑤ 법 및 이 영에 규정된 사항 외에 수형자, 사형확정자 및 미결수용자를 제외한 수용자의 접견 횟수ㆍ시간ㆍ장소 등에 관하여 필요한 사항은 법무부장관이 정한다.', 1938);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3340, '⑥ 소장은 교정시설의 외부에 있는 사람의 수용자 접견에 관한 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 시행령 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <신설 2012.1.6>', 1938);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3341, '① 소장은 제58조제1항 및 제2항에도 불구하고 수형자의 교화 또는 건전한 사회복귀를 위하여 특히 필요하다고 인정하면 접견 시간대 외에도 접견을 하게 할 수 있고 접견시간을 연장할 수 있다.', 1939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3342, '② 소장은 제58조제3항에도 불구하고 수형자가 다음 각 호의 어느 하나에 해당하면 접견 횟수를 늘릴 수 있다.', 1939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3343, '③ 법 제41조제3항제2호에서 "대통령령으로 정하는 경우"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다. <개정 2019.10.22>', 1939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3344, '① 제58조제2항에도 불구하고 수용자가 다음 각 호의 어느 하나에 해당하는 변호사와 접견하는 시간은 회당 60분으로 한다. <개정 2019.10.22>', 1940);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3345, '② 수용자가 제1항 각 호의 변호사와 접견하는 횟수는 다음 각 호의 구분에 따르되, 이를 제58조제3항, 제101조 및 제109조의 접견 횟수에 포함시키지 아니한다. <개정 2019.10.22>', 1940);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3346, '③ 소장은 제58조제1항과 이 조 제1항 및 제2항에도 불구하고 소송사건의 수 또는 소송내용의 복잡성 등을 고려하여 소송의 준비를 위하여 특히 필요하다고 인정하면 접견 시간대 외에도 접견을 하게 할 수 있고, 접견 시간 및 횟수를 늘릴 수 있다.', 1940);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3347, '④ 소장은 제1항 및 제2항에도 불구하고 접견 수요 또는 접견실 사정 등을 고려하여 원활한 접견 사무 진행에 현저한 장애가 발생한다고 판단하면 접견 시간 및 횟수를 줄일 수 있다. 이 경우 줄어든 시간과 횟수는 다음 접견 시에 추가하도록 노력하여야 한다.', 1940);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3348, '⑤ 수용자가 「형사소송법」에 따른 상소권회복 또는 재심 청구사건의 대리인이 되려는 변호사와 접견하는 경우에는 교정시설의 안전 또는 질서를 해칠 우려가 없는 한 접촉차단시설이 설치되지 않은 장소에서 접견하게 한다. <신설 2019.10.22>', 1940);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3349, '⑥ 제1항부터 제5항까지에서 규정한 사항 외에 수용자와 제1항 각 호의 변호사의 접견에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2019.10.22>', 1940);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3350, '① 수용자와 교정시설 외부의 사람이 접견하는 경우에 법 제41조제4항에 따라 접견내용이 청취ㆍ녹음 또는 녹화될 때에는 외국어를 사용해서는 아니 된다. 다만, 국어로 의사소통하기 곤란한 사정이 있는 경우에는 외국어를 사용할 수 있다. <개정 2019.10.22>', 1941);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3351, '② 소장은 제1항 단서의 경우에 필요하다고 인정하면 교도관 또는 통역인으로 하여금 통역하게 할 수 있다.', 1941);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3352, '① 소장은 법 제41조제4항의 청취ㆍ기록을 위하여 다음 각 호의 사람을 제외한 수용자의 접견에 교도관을 참여하게 할 수 있다. <개정 2016.6.28, 2019.10.22>', 1943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3353, '② 소장은 특별한 사정이 없으면 교도관으로 하여금 법 제41조제5항에 따라 수용자와 그 상대방에게 접견내용의 녹음ㆍ녹화 사실을 수용자와 그 상대방이 접견실에 들어가기 전에 미리 말이나 서면 등 적절한 방법으로 알려 주게 하여야 한다. <개정 2019.10.22>', 1943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3354, '③ 소장은 법 제41조제4항에 따라 청취ㆍ녹음ㆍ녹화한 경우의 접견기록물에 대한 보호ㆍ관리를 위하여 접견정보 취급자를 지정하여야 하고, 접견정보 취급자는 직무상 알게 된 접견정보를 누설하거나 권한 없이 처리하거나 다른 사람이 이용하도록 제공하는 등 부당한 목적을 위하여 사용해서는 아니 된다. <개정 2019.10.22>', 1943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3355, '④ 소장은 관계기관으로부터 다음 각 호의 어느 하나에 해당하는 사유로 제3항의 접견기록물의 제출을 요청받은 경우에는 기록물을 제공할 수 있다.', 1943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3356, '⑤ 소장은 제4항에 따라 녹음ㆍ녹화 기록물을 제공할 경우에는 제3항의 접견정보 취급자로 하여금 녹음ㆍ녹화기록물을 요청한 기관의 명칭, 제공받는 목적, 제공 근거, 제공을 요청한 범위, 그 밖에 필요한 사항을 녹음ㆍ녹화기록물 관리프로그램에 입력하게 하고, 따로 이동식 저장매체에 옮겨 담아 제공한다.', 1943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3357, '① 수용자는 편지를 보내려는 경우 해당 편지를 봉함하여 교정시설에 제출한다. 다만, 소장은 다음 각 호의 어느 하나에 해당하는 경우로서 법 제43조제3항에 따른 금지물품의 확인을 위하여 필요한 경우에는 편지를 봉함하지 않은 상태로 제출하게 할 수 있다. <개정 2013.2.5, 2017.9.19, 2020.8.5>', 1946);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3358, '② 소장은 수용자에게 온 편지에 금지물품이 들어 있는지를 개봉하여 확인할 수 있다. <개정 2020.8.5>', 1946);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3359, '① 소장은 법 제43조제4항제4호에 따라 다음 각 호의 어느 하나에 해당하는 수용자가 다른 수용자와 편지를 주고받는 때에는 그 내용을 검열할 수 있다. <개정 2020.8.5>', 1947);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3360, '② 수용자 간에 오가는 편지에 대한 제1항의 검열은 편지를 보내는 교정시설에서 한다. 다만, 특히 필요하다고 인정되는 경우에는 편지를 받는 교정시설에서도 할 수 있다. <개정 2020.8.5>', 1947);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3361, '③ 소장은 수용자가 주고받는 편지가 법 제43조제4항 각 호의 어느 하나에 해당하면 이를 개봉한 후 검열할 수 있다. <신설 2013.2.5, 2020.8.5>', 1947);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3362, '④ 소장은 제3항에 따라 검열한 결과 편지의 내용이 법 제43조제5항의 발신 또는 수신 금지사유에 해당하지 아니하면 발신편지는 봉함한 후 발송하고, 수신편지는 수용자에게 건네준다. <신설 2013.2.5, 2020.8.5>', 1947);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3363, '⑤ 소장은 편지의 내용을 검열했을 때에는 그 사실을 해당 수용자에게 지체 없이 알려주어야 한다. <신설 2013.2.5, 2020.8.5>', 1947);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3364, '① 소장은 수용자가 쉽게 이용할 수 있도록 비치도서의 목록을 정기적으로 공개하여야 한다.', 1953);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3365, '② 비치도서의 열람방법, 열람기간 등에 관하여 필요한 사항은 법무부장관이 정한다.', 1953);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3366, '① 수용자는 휴업일 및 휴게시간 내에 시간의 제한 없이 집필할 수 있다. 다만, 부득이한 사정이 있는 경우에는 그러하지 아니하다.', 1956);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3367, '② 수용자는 거실ㆍ작업장, 그 밖에 지정된 장소에서 집필할 수 있다.', 1956);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3368, '① 소장은 수용자 본인이 작성 또는 집필한 문서나 도화(<img src="http://www.law.go.kr/flDownload.do?flSeq=72505057"  alt="img72505057" >圖</img>)를 외부에 보내거나 내가려고 할 때에는 그 내용을 확인하여 법 제43조제5항 각 호의 어느 하나에 해당하지 않으면 허가해야 한다. <개정 2020.8.5>', 1957);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3369, '② 제1항에 따라 문서나 도화를 외부로 보내거나 내갈 때 드는 비용은 수용자가 부담한다.', 1957);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3370, '③ 법 및 이 영에 규정된 사항 외에 수용자의 집필에 필요한 사항은 법무부장관이 정한다.', 1957);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3371, '① 소장은 제50조에 따라 여성수용자의 목욕횟수를 정하는 경우에는 그 신체적 특성을 특히 고려하여야 한다.', 1958);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3372, '② 소장은 여성수용자가 목욕을 하는 경우에 계호가 필요하다고 인정하면 여성교도관이 하도록 하여야 한다.', 1958);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3373, '① 소장은 유아의 양육을 허가하지 아니하는 경우에는 수용자의 의사를 고려하여 유아보호에 적당하다고 인정하는 법인 또는 개인에게 그 유아를 보낼 수 있다. 다만, 적당한 법인 또는 개인이 없는 경우에는 그 유아를 해당 교정시설의 소재지를 관할하는 시장ㆍ군수 또는 구청장에게 보내서 보호하게 하여야 한다.', 1961);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3374, '② 법 제53조제1항에 따라 양육이 허가된 유아가 출생 후 18개월이 지나거나, 유아양육의 허가를 받은 수용자가 허가의 취소를 요청하는 때 또는 법 제53조제1항 각 호의 어느 하나에 해당되는 때에도 제1항과 같다.', 1961);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3375, '① 법 제54조제1항에서 "노인수용자"란 65세 이상인 수용자를 말한다.', 1962);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3376, '② 법 제54조제2항에서 "장애인수용자"란 시각ㆍ청각ㆍ언어ㆍ지체(肢體) 등의 장애로 통상적인 수용생활이 특히 곤란하다고 인정되는 사람으로서 법무부령으로 정하는 수용자를 말한다.', 1962);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3377, '③ 법 제54조제3항에서 "외국인수용자"란 대한민국의 국적을 가지지 아니한 수용자를 말한다. <신설 2015.12.10>', 1962);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3378, '④ 법 제54조제4항에서 "소년수용자"란 다음 각 호의 사람을 말한다. <신설 2015.12.10>', 1962);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3379, '① 소장은 미결수용자로서 자유형이 확정된 사람에 대하여는 검사의 집행 지휘서가 도달된 때부터 수형자로 처우할 수 있다.', 1963);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3380, '② 제1항의 경우 검사는 집행 지휘를 한 날부터 10일 이내에 재판서나 그 밖에 적법한 서류를 소장에게 보내야 한다.', 1963);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3381, null, 1964);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3382, '① 법 제57조제3항에서 "교정성적"이란 수형자의 수용생활 태도, 상벌 유무, 교육 및 작업의 성과 등을 종합적으로 평가한 결과를 말한다.', 1965);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3383, '② 소장은 수형자의 처우수준을 개별처우계획의 시행에 적합하게 정하거나 조정하기 위하여 교정성적에 따라 처우등급을 부여할 수 있다.', 1965);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3384, '③ 수형자에게 부여하는 처우등급에 관하여 필요한 사항은 법무부령으로 정한다.', 1965);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3385, '① 수형자의 건전한 사회복귀를 지원하기 위하여 교정시설에 취업알선 및 창업지원에 관한 협의기구를 둘 수 있다.', 1966);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3386, '② 제1항의 협의기구의 조직ㆍ운영, 그 밖에 활동에 필요한 사항은 법무부령으로 정한다.', 1966);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3387, '① 소장은 법 제63조에 따른 교육을 효과적으로 시행하기 위하여 교육실을 설치하는 등 교육에 적합한 환경을 조성하여야 한다.', 1968);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3388, '② 소장은 교육 대상자, 시설 여건 등을 고려하여 교육계획을 수립하여 시행하여야 한다.', 1968);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3389, '① 소장은 수형자에게 작업을 부과하는 경우에는 작업의 종류 및 작업과정을 정하여 고지하여야 한다.', 1972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3390, '② 제1항의 작업과정은 작업성적, 작업시간, 작업의 난이도 및 숙련도를 고려하여 정한다. 작업과정을 정하기 어려운 경우에는 작업시간을 작업과정으로 본다.', 1972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3391, '① 소장은 법 제77조에 따라 2일 이상의 귀휴를 허가한 경우에는 귀휴를 허가받은 사람(이하 "귀휴자"라 한다)의 귀휴지를 관할하는 경찰관서의 장에게 그 사실을 통보하여야 한다.', 1978);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3392, '② 귀휴자는 귀휴 중 천재지변이나 그 밖의 사유로 자신의 신상에 중대한 사고가 발생한 경우에는 가까운 교정시설이나 경찰관서에 신고하여야 하고 필요한 보호를 요청할 수 있다.', 1978);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3393, '③ 제2항의 보호 요청을 받은 교정시설이나 경찰관서의 장은 귀휴를 허가한 소장에게 그 사실을 지체 없이 통보하고 적절한 보호조치를 하여야 한다.', 1978);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3394, '① 법 제86조제1항의 미결수용자에 대한 교육ㆍ교화프로그램 또는 작업은 교정시설 밖에서 행하는 것은 포함하지 아니한다.', 1984);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3395, '② 소장은 법 제86조제1항에 따라 작업이 부과된 미결수용자가 작업의 취소를 요청하는 경우에는 그 미결수용자의 의사, 건강 및 교도관의 의견 등을 고려하여 작업을 취소할 수 있다.', 1984);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3396, '①교도관 외의 사람은 「국가공무원 복무규정」 제9조에 따른 근무시간 외에는 소장의 허가 없이 교정시설에 출입하지 못한다. <개정 2014.8.6>', 1996);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3397, '② 소장은 외부인의 교정시설 출입에 관한 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법 시행령」 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <신설 2014.8.6>', 1996);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3398, '① 교정시설의 바깥문, 출입구, 거실, 작업장, 그 밖에 수용자를 수용하고 있는 장소는 외부와 차단하여야 한다. 다만, 필요에 따라 일시 개방하는 경우에는 그 장소를 경비하여야 한다.', 1997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3399, '② 교도관은 접견ㆍ상담ㆍ진료, 그 밖에 수용자의 처우를 위하여 필요한 경우가 아니면 수용자와 외부인이 접촉하게 해서는 아니 된다.', 1997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3400, '① 법 제95조제5항 및 법 제96조제4항에 따라 의무관이 보호실이나 진정실 수용자의 건강을 확인한 결과 보호실 또는 진정실에 계속 수용하는 것이 부적당하다고 인정하는 경우에는 소장에게 즉시 보고하여야 한다. 이 경우 소장은 특별한 사유가 없으면 보호실 또는 진정실 수용을 즉시 중지하여야 한다.', 2000);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3401, '② 소장은 의무관이 출장ㆍ휴가, 그 밖의 부득이한 사유로 법 제95조제5항 및 법 제96조제4항의 직무를 수행할 수 없을 때에는 그 교정시설에 근무하는 의료관계 직원에게 대행하게 할 수 있다.', 2000);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3402, '① 교도관은 소장의 명령 없이 수용자에게 보호장비를 사용하여서는 아니 된다. 다만, 소장의 명령을 받을 시간적 여유가 없는 경우에는 사용 후 소장에게 즉시 보고하여야 한다.', 2001);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3403, '② 법 및 이 영에 규정된 사항 외에 보호장비의 규격과 사용방법 등에 관하여 필요한 사항은 법무부령으로 정한다.', 2001);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3404, '① 의무관은 수용자에게 보호장비를 계속 사용하는 것이 건강상 부적당하다고 인정하는 경우에는 소장에게 즉시 보고하여야 한다. 이 경우 소장은 특별한 사유가 없으면 보호장비 사용을 즉시 중지하여야 한다.', 2002);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3405, '② 의무관이 출장ㆍ휴가, 그 밖의 부득이한 사유로 법 제97조제3항의 직무를 수행할 수 없을 때에는 제119조제2항을 준용한다.', 2002);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3406, '① 소장은 보호장비의 사용을 명령한 경우에는 수시로 그 사용 실태를 확인ㆍ점검하여야 한다.', 2005);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3407, '② 지방교정청장은 소속 교정시설의 보호장비 사용 실태를 정기적으로 점검하여야 한다.', 2005);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3408, '① 소장은 법 제102조제1항에 따른 응급용무의 보조를 위하여 교정성적이 우수한 수형자를 선정하여 필요한 훈련을 시킬 수 있다.', 2008);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3409, '② 소장은 법 제102조제3항에 따라 수용자를 일시석방하는 경우에는 같은 조 제4항의 출석 시한과 장소를 알려주어야 한다.', 2008);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3410, '① 소장은 수용자가 도주하거나 법 제134조 각 호의 어느 하나에 해당하는 행위(이하 이 조에서 "도주등"이라 한다)를 한 경우에는 교정시설의 소재지 및 인접지역 또는 도주등을 한 사람(이하 이 조에서 "도주자"라 한다)이 숨을 만한 지역의 경찰관서에 도주자의 사진이나 인상착의를 기록한 서면을 첨부하여 그 사실을 지체 없이 통보하여야 한다. <개정 2019.10.22>', 2009);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3411, '② 소장은 수용자가 도주등을 하거나 도주자를 체포한 경우에는 법무부장관에게 지체 없이 보고하여야 한다.', 2009);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3412, '① 법무부장관은 「형법」 제145조ㆍ제146조 또는 법 제134조 각 호에 규정된 죄를 지은 수용자를 체포하거나 행정기관 또는 수사기관에 정보를 제공하여 체포하게 한 사람에게 예산의 범위에서 포상금을 지급할 수 있다. <개정 2019.10.22>', 2010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3413, '② 포상금의 지급기준ㆍ지급방법, 그 밖에 필요한 사항은 법무부장관이 정한다.', 2010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3414, '① 포상금을 받으려는 사람은 법무부장관이 정하는 바에 따라 포상금 지급 신청서를 지방교정청장에게 제출해야 한다. <개정 2020.8.5>', 2011);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3415, '② 제1항에 따른 신청서를 접수한 지방교정청장은 그 신청서에 법무부장관이 정하는 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 2011);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3416, null, 2012);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3417, '① 소장은 제132조의 통고를 받은 경우에는 징벌을 지체 없이 집행하여야 한다.', 2017);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3418, '② 소장은 수용자가 징벌처분을 받아 접견, 편지수수 또는 전화통화가 제한된 경우에는 그의 가족에게 그 사실을 알려야 한다. 다만, 수용자가 알리는 것을 원하지 않으면 알리지 않는다. <개정 2014.6.25, 2020.8.5>', 2017);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3419, '③ 삭제 <2017.9.19>', 2017);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3420, '④ 소장은 법 제108조제13호 및 제14호의 징벌집행을 마친 경우에는 의무관에게 해당 수용자의 건강을 지체 없이 확인하게 하여야 한다.', 2017);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3421, '⑤ 의무관이 출장, 휴가, 그 밖의 부득이한 사유로 법 제112조제5항 및 이 조 제4항의 직무를 수행할 수 없는 경우에는 제119조제2항을 준용한다. <개정 2019.10.22>', 2017);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3422, '① 소장은 법 제116조제1항에 따라 수용자가 면담을 신청한 경우에는 그 인적사항을 면담부에 기록하고 특별한 사정이 없으면 신청한 순서에 따라 면담하여야 한다.', 2022);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3423, '② 소장은 제1항에 따라 수용자를 면담한 경우에는 그 요지를 면담부에 기록하여야 한다.', 2022);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3424, '③ 소장은 법 제116조제2항 각 호의 어느 하나에 해당하여 수용자의 면담 신청을 받아들이지 아니하는 경우에는 그 사유를 해당 수용자에게 알려주어야 한다.', 2022);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3425, '① 소장은 법 제117조제1항에 따라 수용자가 순회점검공무원(법 제8조에 따라 법무부장관으로부터 순회점검의 명을 받은 법무부 또는 그 소속기관에 근무하는 공무원을 말한다. 이하 같다)에게 청원하는 경우에는 그 인적사항을 청원부에 기록하여야 한다.', 2023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3426, '② 순회점검공무원은 법 제117조제2항 단서에 따라 수용자가 말로 청원하는 경우에는 그 요지를 청원부에 기록하여야 한다.', 2023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3427, '③ 순회점검공무원은 법 제117조제1항의 청원에 관하여 결정을 한 경우에는 그 요지를 청원부에 기록하여야 한다.', 2023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3428, '④ 순회점검공무원은 법 제117조제1항의 청원을 스스로 결정하는 것이 부적당하다고 인정하는 경우에는 그 내용을 법무부장관에게 보고하여야 한다.', 2023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3429, '⑤ 수용자의 청원처리의 기준ㆍ절차 등에 관하여 필요한 사항은 법무부장관이 정한다.', 2023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3430, '① 법 제117조의2제2항에 따른 예상비용은 「공공기관의 정보공개에 관한 법률 시행령」 제17조에 따른 수수료와 우편요금(공개되는 정보의 사본ㆍ출력물ㆍ복제물 또는 인화물을 우편으로 송부하는 경우로 한정한다)을 기준으로 공개를 청구한 정보가 모두 공개되었을 경우에 예상되는 비용으로 한다.', 2024);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3431, '② 법무부장관, 지방교정청장 또는 소장은 법 제117조의2제2항에 해당하는 수용자가 정보공개의 청구를 한 경우에는 청구를 한 날부터 7일 이내에 제1항에 따른 비용을 산정하여 해당 수용자에게 미리 납부할 것을 통지할 수 있다.', 2024);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3432, '③ 제2항에 따라 비용납부의 통지를 받은 수용자는 그 통지를 받은 날부터 7일 이내에 현금 또는 수입인지로 법무부장관, 지방교정청장 또는 소장에게 납부하여야 한다.', 2024);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3433, '④ 법무부장관, 지방교정청장 또는 소장은 수용자가 제1항에 따른 비용을 제3항에 따른 납부기한까지 납부하지 아니한 경우에는 해당 수용자에게 정보공개 여부 결정의 유예를 통지할 수 있다.', 2024);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3434, '⑤ 법무부장관, 지방교정청장 또는 소장은 제1항에 따른 비용이 납부되면 신속하게 정보공개 여부의 결정을 하여야 한다.', 2024);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3435, '⑥ 법무부장관, 지방교정청장 또는 소장은 비공개 결정을 한 경우에는 제3항에 따라 납부된 비용의 전부를 반환하고 부분공개 결정을 한 경우에는 공개 결정한 부분에 대하여 드는 비용을 제외한 금액을 반환하여야 한다.', 2024);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3436, '⑦ 제2항부터 제5항까지의 규정에도 불구하고 법무부장관, 지방교정청장 또는 소장은 제1항에 따른 비용이 납부되기 전에 정보공개 여부의 결정을 할 수 있다.', 2024);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3437, '⑧ 제1항에 따른 비용의 세부적인 납부방법 및 반환방법 등에 관하여 필요한 사항은 법무부장관이 정한다.', 2024);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3438, '① 법 제126조의2제1항 본문에 따라 통보하는 수용이력에는 다음 각 호의 사항이 포함되어야 한다.', 2028);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3439, '② 법 제126조의2제1항 본문에 따라 통보하는 사회복귀에 관한 의견에는 다음 각 호의 사항이 포함되어야 한다.', 2028);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3440, '③ 법 제126조의2제1항 본문에 따른 통보를 위한 수용이력 통보서와 사회복귀에 관한 의견 통보서의 서식은 법무부령으로 정한다.', 2028);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3441, '④ 법 제126조의2제1항 본문에 따라 석방될 수형자의 수용이력 또는 사회복귀에 관한 의견을 그의 거주지를 관할하는 경찰관서에 통보하는 경우에는 「형사사법절차 전자화 촉진법」 제2조제4호에 따른 형사사법정보시스템을 통해 통보할 수 있다.', 2028);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3442, null, 2031);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3443, '① 의무관은 수용자가 질병으로 사망한 경우에는 사망장에 그 병명ㆍ병력(病歷)ㆍ사인 및 사망일시를 기록하고 서명하여야 한다.', 2035);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3444, '② 소장은 수용자가 자살이나 그 밖에 변사한 경우에는 그 사실을 검사에게 통보하고, 기소된 상태인 경우에는 법원에도 통보하여야 하며 검시가 끝난 후에는 검시자ㆍ참여자의 신분ㆍ성명과 검시 결과를 사망장에 기록하여야 한다.', 2035);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3445, '③ 소장은 법 제128조에 따라 시신을 인도, 화장(火葬), 임시 매장, 집단 매장 또는 자연장(自然葬)을 한 경우에는 그 사실을 사망장에 기록하여야 한다. <개정 2015.12.10>', 2035);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3446, '① 소장은 시신을 임시 매장하거나 봉안한 경우에는 그 장소에 사망자의 성명을 적은 표지를 비치하고, 별도의 장부에 가족관계 등록기준지, 성명, 사망일시를 기록하여 관리하여야 한다. <개정 2015.12.10>', 2037);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3447, '② 소장은 시신 또는 유골을 집단 매장한 경우에는 집단 매장된 사람의 가족관계 등록기준지, 성명, 사망일시를 집단 매장부에 기록하고 그 장소에 묘비를 세워야 한다. <개정 2015.12.10>', 2037);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3448, '① 소장은 법 제130조에 따라 교정위원을 두는 경우 수용자의 개선을 촉구하고 안정된 수용생활을 하게 하기 위하여 교정위원에게 수용자를 교화상담하게 할 수 있다.', 2038);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3449, '② 교정위원은 수용자의 고충 해소 및 교정ㆍ교화를 위하여 필요한 의견을 소장에게 건의할 수 있다.', 2038);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3450, '③ 교정위원의 임기, 위촉 및 해촉, 지켜야 할 사항 등에 관하여 필요한 사항은 법무부장관이 정한다. <개정 2020.8.5>', 2038);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3451, '① 소장은 법 제131조의 기부금품을 접수하는 경우에는 기부한 기관ㆍ단체 또는 개인(이하 이 장에서 "기부자"라 한다)에게 영수증을 발급하여야 한다. 다만, 익명으로 기부하거나 기부자를 알 수 없는 경우에는 그러하지 아니하다.', 2040);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3452, '② 소장은 기부자가 용도를 지정하여 금품을 기부한 경우에는 기부금품을 그 용도에 사용하여야 한다. 다만, 지정한 용도로 사용하기 어려운 특별한 사유가 있는 경우에는 기부자의 동의를 받아 다른 용도로 사용할 수 있다.', 2040);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3453, '③ 교정시설의 기부금품 접수ㆍ사용 등에 관하여 필요한 사항은 법무부장관이 정한다.', 2040);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3454, null, 2042);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3455, '① 「형법」 제347조(사기), 제347조의2(컴퓨터등 사용사기), 제350조(공갈), 제350조의2(특수공갈), 제351조(제347조, 제347조의2, 제350조 및 제350조의2의 상습범만 해당한다), 제355조(횡령ㆍ배임) 또는 제356조(업무상의 횡령과 배임)의 죄를 범한 사람은 그 범죄행위로 인하여 취득하거나 제3자로 하여금 취득하게 한 재물 또는 재산상 이익의 가액(이하 이 조에서 "이득액"이라 한다)이 5억원 이상일 때에는 다음 각 호의 구분에 따라 가중처벌한다. <개정 2016.1.6, 2017.12.19>', 2043);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3456, '② 제1항의 경우 이득액 이하에 상당하는 벌금을 병과(倂科)할 수 있다.', 2043);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3457, '① 법령을 위반하여 대한민국 또는 대한민국국민의 재산을 국외로 이동하거나 국내로 반입하여야 할 재산을 국외에서 은닉 또는 처분하여 도피시켰을 때에는 1년 이상의 유기징역 또는 해당 범죄행위의 목적물 가액(이하 이 조에서 "도피액"이라 한다)의 2배 이상 10배 이하에 상당하는 벌금에 처한다.', 2044);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3458, '② 제1항의 경우 도피액이 5억원 이상일 때에는 다음 각 호의 구분에 따라 가중처벌한다.', 2044);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3459, '③ 제1항 또는 제2항의 미수범은 각 죄에 해당하는 형으로 처벌한다.', 2044);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3460, '④ 법인의 대표자나 법인 또는 개인의 대리인, 사용인, 그 밖의 종업원이 그 법인 또는 개인의 업무에 관하여 제1항부터 제3항까지의 어느 하나에 해당하는 위반행위를 하면 그 행위자를 벌하는 외에 그 법인 또는 개인에게도 제1항의 벌금형을 과(科)한다. 다만, 법인 또는 개인이 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다.', 2044);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3461, '① 금융회사등의 임직원이 그 직무에 관하여 금품이나 그 밖의 이익을 수수(收受), 요구 또는 약속하였을 때에는 5년 이하의 징역 또는 10년 이하의 자격정지에 처한다.', 2045);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3462, '② 금융회사등의 임직원이 그 직무에 관하여 부정한 청탁을 받고 제3자에게 금품이나 그 밖의 이익을 공여(供與)하게 하거나 공여하게 할 것을 요구 또는 약속하였을 때에는 제1항과 같은 형에 처한다.', 2045);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3463, '③ 금융회사등의 임직원이 그 지위를 이용하여 소속 금융회사등 또는 다른 금융회사등의 임직원의 직무에 속하는 사항의 알선에 관하여 금품이나 그 밖의 이익을 수수, 요구 또는 약속하였을 때에는 제1항과 같은 형에 처한다.', 2045);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3464, '④ 제1항부터 제3항까지의 경우에 수수, 요구 또는 약속한 금품이나 그 밖의 이익의 가액(이하 이 조에서 "수수액"이라 한다)이 3천만원 이상일 때에는 다음 각 호의 구분에 따라 가중처벌한다.', 2045);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3465, '⑤ 제1항부터 제4항까지의 경우에 수수액의 2배 이상 5배 이하의 벌금을 병과한다.', 2045);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3466, '① 제5조에 따른 금품이나 그 밖의 이익을 약속, 공여 또는 공여의 의사를 표시한 사람은 5년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.', 2046);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3467, '② 제1항의 행위에 제공할 목적으로 제3자에게 금품을 교부하거나 그 정황을 알면서 교부받은 사람은 제1항과 같은 형에 처한다.', 2046);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3468, '① 저축을 하는 사람 또는 저축을 중개하는 사람이 금융회사등의 임직원으로부터 그 저축에 관하여 법령 또는 약관이나 그 밖에 이에 준하는 금융회사등의 규정에 따라 정하여진 이자, 복금(福金), 보험금, 배당금, 보수 외에 어떤 명목으로든 금품이나 그 밖의 이익을 수수하거나 제3자에게 공여하게 하였을 때에는 5년 이하의 징역 또는 5천만원 이하의 벌금에 처한다.', 2049);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3469, '② 저축을 하는 사람이 그 저축과 관련하여 그 저축을 중개하는 자 또는 그 저축과 관계없는 제3자에게 금융회사등으로부터 대출등을 받게 하였을 때 또는 저축을 중개하는 사람이 그 저축과 관련하여 금융회사등으로부터 대출등을 받거나 그 저축과 관계없는 제3자에게 대출등을 받게 하였을 때에는 제1항과 같은 형에 처한다.', 2049);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3470, '③ 금융회사등의 임직원이 제1항 또는 제2항에 규정된 금품이나 그 밖의 이익을 공여하거나 대출등을 하였을 때에는 제1항 또는 제2항과 같은 형에 처한다.', 2049);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3471, '④ 제1항부터 제3항까지의 경우 징역과 벌금을 병과할 수 있다.', 2049);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3472, '⑤ 금융회사등의 임직원이 소속 금융회사등의 업무에 관하여 제3항의 위반행위를 하면 그 행위자를 벌하는 외에 그 소속 금융회사등에도 같은 항의 벌금형을 과(科)한다. 다만, 소속 금융회사등이 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다.', 2049);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3473, '① 제4조제1항부터 제3항까지의 경우 범인이 도피시키거나 도피시키려고 한 재산은 몰수한다.', 2050);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3474, '② 제5조부터 제7조까지 및 제9조제1항ㆍ제3항의 경우 범인 또는 정황을 아는 제3자가 받은 금품이나 그 밖의 이익은 몰수한다.', 2050);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3475, '③ 제1항 또는 제2항의 경우 몰수할 수 없을 때에는 그 가액을 추징한다.', 2050);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3476, '① 「자본시장과 금융투자업에 관한 법률」 제444조제22호(단기금융업무만 해당한다)의 죄를 범한 사람은 그 영업으로 인하여 취득한 이자, 할인 및 수입료 또는 그 밖의 수수료의 금액(이하 이 조에서 "수수료액"이라 한다)이 연 1억원 이상일 때에는 다음 각 호의 구분에 따라 가중처벌한다.', 2051);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3477, '② 제1항의 경우에 취득한 수수료액의 100분의 10 이상 수수료액 이하에 상당하는 벌금을 병과한다.', 2051);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3478, '① 금융회사등의 임직원은 그의 감독을 받는 사람이 그 직무에 관하여 이 법에 규정된 죄를 범한 정황을 알았을 때에는 지체 없이 소속 금융회사등의 장이나 감사 또는 검사(檢査)의 직무를 담당하는 부서의 장에게 보고하여야 한다.', 2052);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3479, '② 금융회사등의 장이나 감사 또는 검사의 직무에 종사하는 임직원 또는 감독기관의 감독업무에 종사하는 사람은 그 직무를 수행할 때 금융회사등의 임직원이 그 직무에 관하여 이 법에 규정된 죄를 범한 정황을 알았을 때에는 지체 없이 수사기관에 알려야 한다.', 2052);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3480, '③ 정당한 사유 없이 제1항을 위반한 사람은 100만원 이하의 벌금에 처한다.', 2052);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3481, '④ 정당한 사유 없이 제2항을 위반한 사람은 200만원 이하의 벌금에 처한다.', 2052);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3482, '⑤ 제3항 또는 제4항의 죄를 범한 사람이 본범과 친족일 때에는 그 형을 감경하거나 면제할 수 있다.', 2052);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3483, '⑥ 제2항에 따른 감독기관 및 감독업무에 종사하는 사람의 범위는 대통령령으로 정한다.', 2052);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3484, '① 제3조, 제4조제2항(미수범을 포함한다), 제5조제4항 또는 제8조에 따라 유죄판결을 받은 사람은 다음 각 호의 기간 동안 금융회사등, 국가ㆍ지방자치단체가 자본금의 전부 또는 일부를 출자한 기관 및 그 출연(出捐)이나 보조를 받는 기관과 유죄판결된 범죄행위와 밀접한 관련이 있는 기업체에 취업할 수 없다. 다만, 대통령령으로 정하는 바에 따라 법무부장관의 승인을 받은 경우에는 그러하지 아니하다.', 2054);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3485, '② 제1항에 규정된 사람 또는 그를 대표자나 임원으로 하는 기업체는 제1항 각 호의 기간 동안 대통령령으로 정하는 관허업(官許業)의 허가ㆍ인가ㆍ면허ㆍ등록ㆍ지정 등(이하 이 조에서 "허가등"이라 한다)을 받을 수 없다. 다만, 대통령령으로 정하는 바에 따라 법무부장관의 승인을 받은 경우에는 그러하지 아니하다.', 2054);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3486, '③ 제1항의 경우 국가ㆍ지방자치단체가 자본금의 전부 또는 일부를 출자한 기관 및 그 출연이나 보조를 받는 기관과 유죄판결된 범죄행위와 밀접한 관련이 있는 기업체의 범위는 대통령령으로 정한다.', 2054);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3487, '④ 법무부장관은 제1항 또는 제2항을 위반한 사람이 있을 때에는 그 사람이 취업하고 있는 기관이나 기업체의 장 또는 허가등을 한 행정기관의 장에게 그의 해임(解任)이나 허가등의 취소를 요구하여야 한다.', 2054);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3488, '⑤ 제4항에 따라 해임 요구를 받은 기관이나 기업체의 장은 지체 없이 그 요구에 따라야 한다.', 2054);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3489, '⑥ 제1항, 제2항 또는 제5항을 위반한 자는 1년 이하의 징역 또는 500만원 이하의 벌금에 처한다.', 2054);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3490, null, 2056);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3491, null, 2057);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3492, '①지방검찰청 또는 지방검찰청지청의 장은 법 제3조ㆍ법 제4조제2항 (미수범을 포함한다)ㆍ법 제5조제4항 또는 법 제8조의 죄를 범한 사람에 대하여 공소가 제기된 경우에는 지체 없이 그 사실을 법무부장관에게 보고하여야 한다. <개정 2009.7.7, 2019.5.7>', 2063);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3493, '② 고위공직자범죄수사처장은 제1항에서 규정한 죄를 범한 사람에 대하여 공소가 제기된 경우에는 지체 없이 그 사실을 법무부장관에게 통보해야 한다. <신설 2020.7.14>', 2063);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3494, '③법무부장관은 경제사범의 관리를 위하여 필요할 경우 관계기관 또는 관계기업체의 장에게 자료의 제출을 요청할 수 있다. <개정 2009.7.7, 2020.7.14>', 2063);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3495, '① 법 제14조제1항 본문에 따른 국가ㆍ지방자치단체가 자본금의 전부 또는 일부를 출자한 기관 및 그 출연(出捐)이나 보조를 받는 기관은 별표 1부터 별표 3까지에 해당하는 기관으로 한다. <개정 2019.5.7>', 2064);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3496, '②법 제14조제1항 본문에 따른 유죄판결된 범죄행위와 밀접한 관련이 있는 기업체는 다음 각 호의 어느 하나에 해당하는 기업체로 한다. <개정 2019.5.7>', 2064);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3497, '①법 제14조제1항 단서에 따라 법무부장관의 취업승인을 받으려는 사람은 취업하려는 날의 1개월 전까지 법무부장관에게 취업승인신청서를 제출하여야 한다. <개정 2009.7.7, 2019.5.7>', 2067);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3498, '② 법무부장관은 법 제14조제1항 단서에 따른 취업의 승인 여부를 결정한 때에는 지체 없이 그 결정내용을 신청인에게 통지하여야 한다. <개정 2009.7.7>', 2067);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3499, '①제11조에 따른 관허업을 영위하기 위하여 법 제14조제2항 단서에 따른 법무부장관의 승인을 받으려는 사람은 승인신청서를 해당 관허업의 허가등에 관한 소관 행정기관의 장에게 제출하여야 한다. <개정 2009.7.7, 2019.5.7>', 2068);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3500, '②제1항에 따른 승인신청서에는 관허업의 허가등에 관한 신청서류의 사본 1부를 첨부하여야 한다. <개정 2019.5.7>', 2068);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3501, '③ 소관 행정기관의 장은 제1항에 따른 승인신청서를 받은 때에는 관허업의 허가등에 관한 신청서류의 사본이 원본과 다름없음을 확인한 후 지체 없이 이를 법무부장관에게 송부하여야 한다. <개정 2009.7.7, 2019.5.7>', 2068);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3502, '④법무부장관이 제3항에 따른 승인신청서를 송부받아 그 승인여부를 결정한 때에는 지체 없이 그 내용을 그 승인신청을 한 사람과 소관 행정기관의 장에게 통지하여야 한다. <개정 2009.7.7, 2019.5.7>', 2068);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3503, '① 법무부장관은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 민감정보, 같은 법 시행령 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호, 외국인등록번호나 그 밖의 개인정보가 포함된 자료를 처리할 수 있다.', 2069);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3504, '② 허가등에 관한 소관 행정기관의 장은 법 제14조제2항 및 이 영 제14조에 따른 허가등의 승인 신청에 관한 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다.', 2069);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3505, null, 2070);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3506, null, 2071);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3507, '① 법 제12조제4항 및 영 제12조제1항에 따른 벌금의 전부 납입 사실의 통보는 별지 제10호 서식에 따른다.', 2085);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3508, '② 법 제12조제5항 및 영 제12조제2항에 따른 벌금의 일부 납입 사실 및 남은 사회봉사시간의 통보는 별지 제11호 서식에 따른다.', 2085);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3509, null, 2089);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3510, '① 법무부장관은 제1조의 목적을 달성하기 위하여 필요한 연구ㆍ실험ㆍ조사ㆍ기술개발(이하 "연구개발사업"이라 한다) 및 전문인력 양성 등 소관 분야의 과학기술진흥을 위한 시책을 마련하여 시행할 수 있다.', 2091);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3511, '② 제1항에 따른 연구개발사업은 단계별ㆍ분야별 연구개발과제를 선정하여 「국가연구개발혁신법」 제2조제3호의 기관 또는 단체와 협약을 맺어 실시하게 할 수 있다.', 2091);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3512, '③ 법무부장관은 제2항에 따라 협약을 맺은 기관 또는 단체에 연구개발사업을 실시하는 데 필요한 자금의 전부 또는 일부를 출연하거나 보조할 수 있다.', 2091);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3513, '④ 제3항에 따른 출연금 및 보조금의 지급ㆍ사용 및 관리 등에 필요한 사항은 대통령령으로 정한다.', 2091);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3514, '①검사는 다음 각 호의 어느 하나에 해당하고, 성폭력범죄를 다시 범할 위험성이 있다고 인정되는 사람에 대하여 전자장치를 부착하도록 하는 명령(이하 "부착명령"이라 한다)을 법원에 청구할 수 있다. <개정 2008.6.13, 2010.4.15, 2012.12.18>', 2093);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3515, '② 검사는 미성년자 대상 유괴범죄를 저지른 사람으로서 미성년자 대상 유괴범죄를 다시 범할 위험성이 있다고 인정되는 사람에 대하여 부착명령을 법원에 청구할 수 있다. 다만, 유괴범죄로 징역형의 실형 이상의 형을 선고받아 그 집행이 종료 또는 면제된 후 다시 유괴범죄를 저지른 경우에는 부착명령을 청구하여야 한다. <신설 2009.5.8, 2010.4.15>', 2093);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3516, '③ 검사는 살인범죄를 저지른 사람으로서 살인범죄를 다시 범할 위험성이 있다고 인정되는 사람에 대하여 부착명령을 법원에 청구할 수 있다. 다만, 살인범죄로 징역형의 실형 이상의 형을 선고받아 그 집행이 종료 또는 면제된 후 다시 살인범죄를 저지른 경우에는 부착명령을 청구하여야 한다. <신설 2010.4.15>', 2093);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3517, '④ 검사는 다음 각 호의 어느 하나에 해당하고 강도범죄를 다시 범할 위험성이 있다고 인정되는 사람에 대하여 부착명령을 법원에 청구할 수 있다. <신설 2012.12.18>', 2093);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3518, '⑤ 검사는 다음 각 호의 어느 하나에 해당하고 스토킹범죄를 다시 범할 위험성이 있다고 인정되는 사람에 대하여 부착명령을 법원에 청구할 수 있다. <신설 2023.7.11>', 2093);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3519, '⑥제1항부터 제5항까지의 규정에 따른 부착명령의 청구는 공소가 제기된 특정범죄사건의 항소심 변론종결 시까지 하여야 한다. <개정 2009.5.8, 2010.4.15, 2012.12.18, 2023.7.11>', 2093);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3520, '⑦법원은 공소가 제기된 특정범죄사건을 심리한 결과 부착명령을 선고할 필요가 있다고 인정하는 때에는 검사에게 부착명령의 청구를 요구할 수 있다. <개정 2009.5.8, 2010.4.15, 2012.12.18, 2023.7.11>', 2093);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3521, '⑧제1항부터 제5항까지의 규정에 따른 특정범죄사건에 대하여 판결의 확정 없이 공소가 제기된 때부터 15년이 경과한 경우에는 부착명령을 청구할 수 없다. <개정 2009.5.8, 2010.4.15, 2012.12.18, 2023.7.11>', 2093);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3522, '①검사는 부착명령을 청구하기 위하여 필요하다고 인정하는 때에는 피의자의 주거지 또는 소속 검찰청(지청을 포함한다. 이하 같다) 소재지를 관할하는 보호관찰소(지소를 포함한다. 이하 같다)의 장에게 범죄의 동기, 피해자와의 관계, 심리상태, 재범의 위험성 등 피의자에 관하여 필요한 사항의 조사를 요청할 수 있다.', 2094);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3523, '②제1항의 요청을 받은 보호관찰소의 장은 조사할 보호관찰관을 지명하여야 한다.', 2094);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3524, '③제2항에 따라 지명된 보호관찰관은 지체 없이 필요한 사항을 조사한 후 검사에게 조사보고서를 제출하여야 한다. <개정 2012.12.18>', 2094);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3525, '④ 검사는 제1항의 요청을 받은 보호관찰소의 장에게 조사진행상황의 보고를 요구할 수 있다. <신설 2012.12.18>', 2094);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3526, '⑤검사는 부착명령을 청구함에 있어서 필요한 경우에는 피의자에 대한 정신감정이나 그 밖에 전문가의 진단 등의 결과를 참고하여야 한다. <개정 2012.12.18>', 2094);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3527, '①부착명령 청구사건의 관할은 부착명령 청구사건과 동시에 심리하는 특정범죄사건의 관할에 따른다. <개정 2009.5.8>', 2095);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3528, '②부착명령 청구사건의 제1심 재판은 지방법원 합의부(지방법원지원 합의부를 포함한다. 이하 같다)의 관할로 한다.', 2095);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3529, '①부착명령 청구서에는 다음 각 호의 사항을 기재하여야 한다.', 2096);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3530, '②법원은 부착명령 청구가 있는 때에는 지체 없이 부착명령 청구서의 부본을 피부착명령청구자 또는 그의 변호인에게 송부하여야 한다. 이 경우 특정범죄사건에 대한 공소제기와 동시에 부착명령 청구가 있는 때에는 제1회 공판기일 5일 전까지, 특정범죄사건의 심리 중에 부착명령 청구가 있는 때에는 다음 공판기일 5일 전까지 송부하여야 한다. <개정 2009.5.8>', 2096);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3531, '①법원은 부착명령 청구가 이유 있다고 인정하는 때에는 다음 각 호에 따른 기간의 범위 내에서 부착기간을 정하여 판결로 부착명령을 선고하여야 한다. 다만, 19세 미만의 사람에 대하여 특정범죄를 저지른 경우에는 부착기간 하한을 다음 각 호에 따른 부착기간 하한의 2배로 한다. <개정 2008.6.13, 2010.4.15, 2012.12.18>', 2097);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3532, '② 여러 개의 특정범죄에 대하여 동시에 부착명령을 선고할 때에는 법정형이 가장 중한 죄의 부착기간 상한의 2분의 1까지 가중하되, 각 죄의 부착기간의 상한을 합산한 기간을 초과할 수 없다. 다만, 하나의 행위가 여러 특정범죄에 해당하는 경우에는 가장 중한 죄의 부착기간을 부착기간으로 한다. <신설 2010.4.15>', 2097);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3533, '③ 부착명령을 선고받은 사람은 부착기간 동안 「보호관찰 등에 관한 법률」에 따른 보호관찰을 받는다. <신설 2010.4.15>', 2097);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3534, '④법원은 다음 각 호의 어느 하나에 해당하는 때에는 판결로 부착명령 청구를 기각하여야 한다. <개정 2008.6.13, 2009.5.8, 2010.4.15>', 2097);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3535, '⑤부착명령 청구사건의 판결은 특정범죄사건의 판결과 동시에 선고하여야 한다. <개정 2009.5.8, 2010.4.15>', 2097);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3536, '⑥부착명령 선고의 판결이유에는 요건으로 되는 사실, 증거의 요지 및 적용 법조를 명시하여야 한다. <개정 2010.4.15>', 2097);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3537, '⑦부착명령의 선고는 특정범죄사건의 양형에 유리하게 참작되어서는 아니 된다. <개정 2009.5.8, 2010.4.15>', 2097);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3538, '⑧특정범죄사건의 판결에 대하여 상소 및 상소의 포기ㆍ취하가 있는 때에는 부착명령 청구사건의 판결에 대하여도 상소 및 상소의 포기ㆍ취하가 있는 것으로 본다. 상소권회복 또는 재심의 청구나 비상상고가 있는 때에도 또한 같다. <개정 2009.5.8, 2010.4.15>', 2097);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3539, '⑨제8항에도 불구하고 검사 또는 피부착명령청구자 및 「형사소송법」 제340조ㆍ제341조에 규정된 자는 부착명령에 대하여 독립하여 상소 및 상소의 포기ㆍ취하를 할 수 있다. 상소권회복 또는 재심의 청구나 비상상고의 경우에도 또한 같다. <개정 2010.4.15>', 2097);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3540, '① 법원은 제9조제1항에 따라 부착명령을 선고하는 경우 부착기간의 범위에서 준수기간을 정하여 다음 각 호의 준수사항 중 하나 이상을 부과할 수 있다. 다만, 제4호의 준수사항은 500시간의 범위에서 그 기간을 정하여야 한다. <개정 2010.4.15, 2020.12.15>', 2098);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3541, '② 삭제 <2010.4.15>', 2098);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3542, '③ 제1항에도 불구하고 법원은 성폭력범죄를 저지른 사람(19세 미만의 사람을 대상으로 성폭력범죄를 저지른 사람으로 한정한다) 또는 스토킹범죄를 저지른 사람에 대해서 제9조제1항에 따라 부착명령을 선고하는 경우에는 다음 각 호의 구분에 따라 제1항의 준수사항을 부과하여야 한다. <개정 2023.7.11>', 2098);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3543, '①법원은 제9조에 따라 부착명령을 선고한 때에는 그 판결이 확정된 날부터 3일 이내에 부착명령을 선고받은 자(이하 "피부착명령자"라 한다)의 주거지를 관할하는 보호관찰소의 장에게 판결문의 등본을 송부하여야 한다.', 2099);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3544, '②교도소, 소년교도소, 구치소, 국립법무병원 및 군교도소의 장(이하 "교도소장등"이라 한다)은 피부착명령자가 석방되기 5일 전까지 피부착명령자의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다. <개정 2008.6.13, 2022.1.4>', 2099);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3545, '①부착명령은 검사의 지휘를 받아 보호관찰관이 집행한다.', 2101);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3546, '②제1항에 따른 지휘는 판결문 등본을 첨부한 서면으로 한다.', 2101);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3547, '①부착명령은 특정범죄사건에 대한 형의 집행이 종료되거나 면제ㆍ가석방되는 날 또는 치료감호의 집행이 종료ㆍ가종료되는 날 석방 직전에 피부착명령자의 신체에 전자장치를 부착함으로써 집행한다. 다만, 다음의 경우에는 각 호의 구분에 따라 집행한다. <개정 2008.6.13, 2009.5.8, 2012.12.18, 2017.10.31>', 2102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3548, '② 제1항제2호에 따라 부착명령을 집행하는 경우 보호관찰소의 장은 피부착명령자를 소환할 수 있으며, 피부착명령자가 소환에 따르지 아니하는 때에는 관할 지방검찰청의 검사에게 신청하여 부착명령 집행장을 발부받아 구인할 수 있다. <신설 2017.10.31>', 2102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3549, '③ 보호관찰소의 장은 제2항에 따라 피부착명령자를 구인한 경우에는 부착명령의 집행을 마친 즉시 석방하여야 한다. <신설 2017.10.31>', 2102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3550, '④부착명령의 집행은 신체의 완전성을 해하지 아니하는 범위 내에서 이루어져야 한다. <개정 2017.10.31>', 2102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3551, '⑤ 부착명령이 여러 개인 경우 확정된 순서에 따라 집행한다. <신설 2010.4.15, 2017.10.31>', 2102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3552, '⑥다음 각 호의 어느 하나에 해당하는 때에는 부착명령의 집행이 정지된다. <개정 2008.6.13, 2010.4.15, 2017.10.31>', 2102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3553, '⑦ 제6항제1호에도 불구하고 구속영장의 집행을 받아 구금된 후에 다음 각 호의 어느 하나에 해당하는 사유로 구금이 종료되는 경우 그 구금기간 동안에는 부착명령이 집행된 것으로 본다. 다만, 제1호 및 제2호의 경우 법원의 판결에 따라 유죄로 확정된 경우는 제외한다. <신설 2017.12.12, 2021.3.16>', 2102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3554, '⑧제6항에 따라 집행이 정지된 부착명령의 잔여기간에 대하여는 다음 각 호의 구분에 따라 집행한다. <개정 2008.6.13, 2010.4.15, 2017.10.31, 2017.12.12>', 2102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3555, '⑨제1항부터 제8항까지 규정된 사항 외에 부착명령의 집행 및 정지에 관하여 필요한 사항은 대통령령으로 정한다. <개정 2010.4.15, 2017.10.31, 2017.12.12>', 2102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3556, '①전자장치가 부착된 자(이하 "피부착자"라 한다)는 전자장치의 부착기간 중 전자장치를 신체에서 임의로 분리ㆍ손상, 전파 방해 또는 수신자료의 변조, 그 밖의 방법으로 그 효용을 해하여서는 아니 된다.', 2103);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3557, '② 피부착자는 특정범죄사건에 대한 형의 집행이 종료되거나 면제ㆍ가석방되는 날부터 10일 이내에 주거지를 관할하는 보호관찰소에 출석하여 대통령령으로 정하는 신상정보 등을 서면으로 신고하여야 한다. <신설 2010.4.15, 2017.12.12>', 2103);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3558, '③피부착자는 주거를 이전하거나 7일 이상의 국내여행을 하거나 출국할 때에는 미리 보호관찰관의 허가를 받아야 한다. <개정 2010.4.15>', 2103);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3559, '① 피부착자가 다음 각 호의 어느 하나에 해당하는 경우에는 법원은 보호관찰소의 장의 신청에 따른 검사의 청구로 1년의 범위에서 부착기간을 연장하거나 제9조의2제1항의 준수사항을 추가 또는 변경하는 결정을 할 수 있다. <개정 2018.3.20>', 2104);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3560, '② 제1항 각 호에 규정된 사항 외의 사정변경이 있는 경우에도 법원은 상당한 이유가 있다고 인정되면 보호관찰소의 장의 신청에 따른 검사의 청구로 제9조의2제1항의 준수사항을 부과, 추가, 변경 또는 삭제하는 결정을 할 수 있다. <개정 2020.12.15>', 2104);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3561, '①보호관찰관은 피부착자의 재범방지와 건전한 사회복귀를 위하여 필요한 지도와 원호를 한다.', 2106);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3562, '②보호관찰관은 전자장치 부착기간 중 피부착자의 소재지 인근 의료기관에서의 치료, 상담시설에서의 상담치료 등 피부착자의 재범방지 및 수치심으로 인한 과도한 고통의 방지를 위하여 필요한 조치를 할 수 있다. <개정 2012.12.18>', 2106);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3563, '③ 보호관찰관은 필요한 경우 부착명령의 집행을 개시하기 전에 교도소장등에게 요청하여 「형의 집행 및 수용자의 처우에 관한 법률」 제63조의 교육, 제64조의 교화프로그램 및 제107조의 징벌에 관한 자료 등 피부착자의 형 또는 치료감호 집행 중의 생활실태를 확인할 수 있는 자료를 확보하고, 형 또는 치료감호의 집행을 받고 있는 피부착자를 면접할 수 있다. 이 경우 교도소장등은 보호관찰관에게 협조하여야 한다. <신설 2012.12.18>', 2106);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3564, '①보호관찰소의 장은 피부착자의 전자장치로부터 발신되는 전자파를 수신하여 그 자료(이하 "수신자료"라 한다)를 보존하여야 한다.', 2107);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3565, '②수신자료는 다음 각 호의 경우 외에는 열람ㆍ조회ㆍ제공 또는 공개할 수 없다. <개정 2009.5.8, 2017.12.12, 2020.2.4>', 2107);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3566, '③ 삭제 <2012.12.18>', 2107);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3567, '④검사 또는 사법경찰관은 제2항제1호에 해당하는 사유로 수신자료를 열람 또는 조회하는 경우 관할 지방법원(군사법원을 포함한다) 또는 지원의 허가를 받아야 한다. 다만, 관할 지방법원 또는 지원의 허가를 받을 수 없는 긴급한 사유가 있는 때에는 수신자료 열람 또는 조회를 요청한 후 지체 없이 그 허가를 받아 보호관찰소의 장에게 송부하여야 한다. <개정 2012.12.18, 2017.12.12, 2021.9.24>', 2107);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3568, '⑤ 검사 또는 사법경찰관은 제4항 단서에 따라 긴급한 사유로 수신자료를 열람 또는 조회하였으나 지방법원 또는 지원의 허가를 받지 못한 경우에는 지체 없이 열람 또는 조회한 수신자료를 폐기하고, 그 사실을 보호관찰소의 장에게 통지하여야 한다. <신설 2012.12.18>', 2107);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3569, '⑥보호관찰소의 장은 다음 각 호의 어느 하나에 해당하는 때에는 수신자료를 폐기하여야 한다. <개정 2010.4.15, 2012.12.18>', 2107);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3570, '⑦제1항부터 제6항까지에서 규정한 사항 외에 수신자료의 보존ㆍ사용ㆍ열람ㆍ조회ㆍ제공ㆍ폐기 등에 관하여 필요한 사항은 대통령령으로 정한다. <개정 2012.12.18, 2017.12.12>', 2107);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3571, '① 보호관찰소의 장은 범죄예방 및 수사에 필요하다고 판단하는 경우 피부착자가 제14조제2항에 따라 신고한 신상정보 및 피부착자에 대한 지도ㆍ감독 중 알게 된 사실 등의 자료를 피부착자의 주거지를 관할하는 경찰관서의 장 등 수사기관에 제공할 수 있다. <개정 2017.12.12>', 2108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3572, '② 수사기관은 범죄예방 및 수사활동 중 인지한 사실이 피부착자 지도ㆍ감독에 활용할 만한 자료라고 판단할 경우 이를 보호관찰소의 장에게 제공할 수 있다. <개정 2017.12.12>', 2108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3573, '③ 보호관찰소의 장은 피부착자가 범죄를 저질렀거나 저질렀다고 의심할만한 상당한 이유가 있을 때에는 이를 수사기관에 통보하여야 한다.', 2108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3574, '④ 수사기관은 체포 또는 구속한 사람이 피부착자임을 알게 된 경우에는 피부착자의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다.', 2108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3575, '⑤ 제1항부터 제4항에 따른 제공 및 통보의 절차와 관리 등에 필요한 사항은 대통령령으로 정한다.', 2108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3576, '① 법무부장관은 보호관찰소의 장 및 보호관찰관이 피부착자의 위치를 확인하고 이동경로를 탐지하며, 전자장치로부터 발신되는 전자파를 수신한 자료를 보존ㆍ사용ㆍ폐기하는 업무를 지원하기 위하여 위치추적 관제센터를 설치하여 운영할 수 있다. <개정 2022.1.4>', 2109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3577, '② 위치추적 관제센터의 장은 피부착자가 제9조의2제1항 각 호(제4호 및 제6호는 제외한다)에 따른 준수사항 또는 제14조제1항에 따른 효용 유지 의무를 위반하거나, 위반하였다고 의심할만한 상당한 이유가 있고 피부착자에 대한 신속한 지도ㆍ감독을 위하여 긴급히 필요한 경우 지방자치단체의 장에게 「개인정보 보호법」 제2조제7호에 따른 고정형 영상정보처리기기를 통하여 수집된 영상정보의 제공 등 협조를 요청할 수 있다. <신설 2022.1.4, 2023.3.14>', 2109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3578, '③ 제2항에 따라 피부착자에 관한 영상정보를 제공받은 위치추적 관제센터의 장은 영상정보의 열람이 종료된 후 그 사실을 해당 피부착자에게 통지하여야 한다. <신설 2022.1.4>', 2109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3579, '④ 제3항에 따른 통지의 시기 및 방법 등 영상정보 열람사실의 통지에 필요한 사항은 법무부령으로 정한다. <신설 2022.1.4>', 2109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3580, '①보호관찰소의 장 또는 피부착자 및 그 법정대리인은 해당 보호관찰소를 관할하는 심사위원회에 부착명령의 임시해제를 신청할 수 있다. <개정 2020.2.4>', 2110);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3581, '②제1항의 신청은 부착명령의 집행이 개시된 날부터 3개월이 경과한 후에 하여야 한다. 신청이 기각된 경우에는 기각된 날부터 3개월이 경과한 후에 다시 신청할 수 있다.', 2110);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3582, '③제2항에 따라 임시해제의 신청을 할 때에는 신청서에 임시해제의 심사에 참고가 될 자료를 첨부하여 제출하여야 한다. <개정 2020.2.4>', 2110);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3583, '①심사위원회는 임시해제를 심사할 때에는 피부착자의 인격, 생활태도, 부착명령 이행상황 및 재범의 위험성에 대하여 보호관찰관 등 전문가의 의견을 고려하여야 한다. <개정 2012.12.18, 2020.2.4>', 2111);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3584, '②심사위원회는 임시해제의 심사를 위하여 필요한 때에는 보호관찰소의 장으로 하여금 필요한 사항을 조사하게 하거나 피부착자나 그 밖의 관계인을 직접 소환ㆍ심문 또는 조사할 수 있다. <개정 2020.2.4>', 2111);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3585, '③제2항의 요구를 받은 보호관찰소의 장은 필요한 사항을 조사하여 심사위원회에 통보하여야 한다.', 2111);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3586, '④심사위원회는 피부착자가 부착명령이 계속 집행될 필요가 없을 정도로 개선되어 재범의 위험성이 없다고 인정하는 때에는 부착명령의 임시해제를 결정할 수 있다. 이 경우 피부착자로 하여금 주거이전 상황 등을 보호관찰소의 장에게 정기적으로 보고하도록 할 수 있다. <개정 2020.2.4>', 2111);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3587, '⑤심사위원회는 부착명령의 임시해제를 하지 아니하기로 결정한 때에는 결정서에 그 이유를 명시하여야 한다. <개정 2020.2.4>', 2111);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3588, '⑥ 제4항에 따라 부착명령이 임시해제된 경우에는 제9조제3항에 따른 보호관찰과 제9조의2에 따른 준수사항 및 「아동ㆍ청소년의 성보호에 관한 법률」 제61조제3항에 따른 보호관찰이 임시해제된 것으로 본다. 다만, 심사위원회에서 보호관찰 또는 준수사항 부과가 필요하다고 결정한 경우에는 그러하지 아니하다. <신설 2008.6.13, 2010.4.15, 2012.12.18, 2016.12.20, 2020.2.4>', 2111);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3589, '①보호관찰소의 장은 부착명령이 임시해제된 자가 특정범죄를 저지르거나 주거이전 상황 등의 보고에 불응하는 등 재범의 위험성이 있다고 판단되는 때에는 심사위원회에 임시해제의 취소를 신청할 수 있다. 이 경우 심사위원회는 임시해제된 자의 재범의 위험성이 현저하다고 인정될 때에는 임시해제를 취소하여야 한다. <개정 2009.5.8, 2020.2.4>', 2112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3590, '②제1항에 따라 임시해제가 취소된 자는 잔여 부착명령기간 동안 전자장치를 부착하여야 하고, 부착명령할 때 개시된 보호관찰을 받아야 하며, 부과된 준수사항(준수기간이 종료되지 않은 경우에 한정한다)을 준수하여야 한다. 이 경우 임시해제기간은 부착명령기간에 산입하지 아니한다. <개정 2016.12.20, 2020.2.4>', 2112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3591, null, 2113);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3592, '①피부착명령자는 그 판결이 확정된 후 집행을 받지 아니하고 함께 선고된 특정범죄사건의 형의 시효가 완성되면 그 집행이 면제된다. <개정 2009.5.8>', 2114);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3593, '②부착명령의 시효는 피부착명령자를 체포함으로써 중단된다.', 2114);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3594, null, 2115);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3595, '① 법원은 제21조의2 각 호의 어느 하나에 해당하는 사람이 금고 이상의 선고형에 해당하고 보호관찰명령의 청구가 이유 있다고 인정하는 때에는 2년 이상 5년 이하의 범위에서 기간을 정하여 보호관찰명령을 선고하여야 한다. <개정 2017.12.12>', 2116);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3596, '② 법원은 제1항에도 불구하고 제9조제4항제1호에 따라 부착명령 청구를 기각하는 경우로서 제21조의2 각 호의 어느 하나에 해당하여 보호관찰명령을 선고할 필요가 있다고 인정하는 때에는 직권으로 제1항에 따른 기간을 정하여 보호관찰명령을 선고할 수 있다. <신설 2017.12.12>', 2116);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3597, '① 법원은 제21조의3에 따라 보호관찰명령을 선고하는 경우 제9조의2제1항 각 호의 준수사항 중 하나 이상을 부과할 수 있다. 다만, 제9조의2제1항제4호의 준수사항은 300시간의 범위에서 그 기간을 정하여야 한다. <개정 2019.4.16>', 2117);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3598, '② 제1항 본문에도 불구하고 법원은 성폭력범죄를 저지른 사람(19세 미만의 사람을 대상으로 성폭력범죄를 저지른 사람으로 한정한다) 또는 스토킹범죄를 저지른 사람에 대해서는 제21조의3에 따라 보호관찰명령을 선고하는 경우 제9조의2제1항제3호를 포함하여 준수사항을 부과하여야 한다. <신설 2019.4.16, 2023.7.11>', 2117);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3599, '① 보호관찰대상자는 특정범죄사건에 대한 형의 집행이 종료되거나 면제ㆍ가석방되는 날부터 10일 이내에 주거지를 관할하는 보호관찰소에 출석하여 서면으로 신고하여야 한다.', 2119);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3600, '② 보호관찰대상자는 주거를 이전하거나 7일 이상의 국내여행을 하거나 출국할 때에는 미리 보호관찰관의 허가를 받아야 한다.', 2119);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3601, '① 보호관찰대상자가 정당한 사유 없이 제21조의4 또는 「보호관찰 등에 관한 법률」 제32조에 따른 준수사항을 위반하거나 제21조의6에 따른 의무를 위반한 때에는 법원은 보호관찰소의 장의 신청에 따른 검사의 청구로 다음 각 호의 결정을 할 수 있다. <개정 2023.7.11>', 2120);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3602, '② 제1항 각 호의 처분은 병과할 수 있다.', 2120);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3603, '③ 제1항에 규정된 사항 외의 사정변경이 있는 경우에도 법원은 상당한 이유가 있다고 인정하면 보호관찰소의 장의 신청에 따른 검사의 청구로 제21조의4에 따른 준수사항을 추가, 변경 또는 삭제하는 결정을 할 수 있다.', 2120);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3604, '①제9조에 따른 부착명령 판결을 선고받지 아니한 특정 범죄자로서 형의 집행 중 가석방되어 보호관찰을 받게 되는 자는 준수사항 이행 여부 확인 등을 위하여 가석방기간 동안 전자장치를 부착하여야 한다. 다만, 심사위원회가 전자장치 부착이 필요하지 아니하다고 결정한 경우에는 그러하지 아니하다. <개정 2009.5.8, 2012.12.18>', 2122);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3605, '② 심사위원회는 특정범죄 이외의 범죄로 형의 집행 중 가석방되어 보호관찰을 받는 사람의 준수사항 이행 여부 확인 등을 위하여 가석방 예정자의 범죄내용, 개별적 특성 등을 고려하여 가석방 기간의 전부 또는 일부의 기간을 정하여 전자장치를 부착하게 할 수 있다. <신설 2020.2.4>', 2122);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3606, '③ 심사위원회는 제1항 및 제2항의 결정을 위하여 가석방 예정자에 대한 전자장치 부착의 필요성과 적합성 여부 등을 조사하여야 한다. <신설 2020.2.4>', 2122);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3607, '④심사위원회는 제1항 및 제2항에 따라 전자장치를 부착하게 되는 자의 주거지를 관할하는 보호관찰소의 장에게 가석방자의 인적사항 등 전자장치 부착에 필요한 사항을 즉시 통보하여야 한다. <개정 2020.2.4>', 2122);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3608, '⑤교도소장등은 제1항 및 제2항에 따른 가석방 예정자가 석방되기 5일 전까지 그의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다. <개정 2020.2.4>', 2122);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3609, '①「치료감호 등에 관한 법률」 제37조에 따른 치료감호심의위원회(이하 "치료감호심의위원회"라 한다)는 제9조에 따른 부착명령 판결을 선고받지 아니한 특정 범죄자로서 치료감호의 집행 중 가종료 또는 치료위탁되는 피치료감호자나 보호감호의 집행 중 가출소되는 피보호감호자(이하 "가종료자등"이라 한다)에 대하여 「치료감호 등에 관한 법률」 또는 「사회보호법」(법률 제7656호로 폐지되기 전의 법률을 말한다)에 따른 준수사항 이행 여부 확인 등을 위하여 보호관찰 기간의 범위에서 기간을 정하여 전자장치를 부착하게 할 수 있다. <개정 2008.6.13, 2009.5.8, 2010.4.15, 2023.7.11>', 2123);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3610, '②치료감호심의위원회는 제1항에 따라 전자장치 부착을 결정한 경우에는 즉시 피부착결정자의 주거지를 관할하는 보호관찰소의 장에게 통보하여야 한다.', 2123);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3611, '③치료감호시설의 장ㆍ보호감호시설의 장 또는 교도소의 장은 가종료자등이 가종료 또는 치료위탁되거나 가출소되기 5일 전까지 가종료자등의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다. <개정 2010.4.15>', 2123);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3612, '①전자장치 부착은 보호관찰관이 집행한다.', 2124);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3613, '②전자장치는 다음 각 호의 어느 하나에 해당하는 때 석방 직전에 부착한다. <개정 2010.4.15, 2017.12.12>', 2124);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3614, '③전자장치 부착집행 중 보호관찰 준수사항 위반으로 유치허가장의 집행을 받아 유치된 때에는 부착집행이 정지된다. 이 경우 심사위원회가 보호관찰소의 장의 가석방 취소신청을 기각한 날 또는 법무부장관이 심사위원회의 허가신청을 불허한 날부터 그 잔여기간을 집행한다.', 2124);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3615, null, 2125);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3616, '①법원은 특정범죄를 범한 자에 대하여 형의 집행을 유예하면서 보호관찰을 받을 것을 명할 때에는 보호관찰 기간의 범위 내에서 기간을 정하여 준수사항의 이행여부 확인 등을 위하여 전자장치를 부착할 것을 명할 수 있다. <개정 2009.5.8, 2023.7.11>', 2128);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3617, '②법원은 제1항에 따른 부착명령기간 중 소재지 인근 의료기관에서의 치료, 지정 상담시설에서의 상담치료 등 대상자의 재범방지를 위하여 필요한 조치들을 과할 수 있다.', 2128);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3618, '③법원은 제1항에 따른 전자장치 부착을 명하기 위하여 필요하다고 인정하는 때에는 피고인의 주거지 또는 그 법원의 소재지를 관할하는 보호관찰소의 장에게 범죄의 동기, 피해자와의 관계, 심리상태, 재범의 위험성 등 피고인에 관하여 필요한 사항의 조사를 요청할 수 있다.', 2128);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3619, '①부착명령은 전자장치 부착을 명하는 법원의 판결이 확정된 때부터 집행한다.', 2129);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3620, '②부착명령의 집행 중 보호관찰 준수사항 위반으로 유치허가장의 집행을 받아 유치된 때에는 부착명령 집행이 정지된다. 이 경우 검사가 보호관찰소의 장의 집행유예 취소신청을 기각한 날 또는 법원이 검사의 집행유예취소청구를 기각한 날부터 그 잔여기간을 집행한다.', 2129);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3621, null, 2130);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3622, '① 법원은 「형사소송법」 제98조제9호에 따른 보석조건으로 피고인에게 전자장치 부착을 명할 수 있다.', 2132);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3623, '② 법원은 제1항에 따른 전자장치 부착을 명하기 위하여 필요하다고 인정하면 그 법원의 소재지 또는 피고인의 주거지를 관할하는 보호관찰소의 장에게 피고인의 직업, 경제력, 가족상황, 주거상태, 생활환경 및 피해회복 여부 등 피고인에 관한 사항의 조사를 의뢰할 수 있다.', 2132);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3624, '③ 제2항의 의뢰를 받은 보호관찰소의 장은 지체 없이 조사하여 서면으로 법원에 통보하여야 하며, 조사를 위하여 필요한 경우에는 피고인이나 그 밖의 관계인을 소환하여 심문하거나 소속 보호관찰관에게 필요한 사항을 조사하게 할 수 있다.', 2132);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3625, '④ 보호관찰소의 장은 제3항의 조사를 위하여 필요하다고 인정하면 국공립 기관이나 그 밖의 단체에 사실을 알아보거나 관련 자료의 열람 등 협조를 요청할 수 있다.', 2132);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3626, '① 법원은 제31조의2제1항에 따라 전자장치 부착을 명한 경우 지체 없이 그 결정문의 등본을 피고인의 주거지를 관할하는 보호관찰소의 장에게 송부하여야 한다.', 2133);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3627, '② 제31조의2제1항에 따라 전자장치 부착명령을 받고 석방된 피고인은 법원이 지정한 일시까지 주거지를 관할하는 보호관찰소에 출석하여 신고한 후 보호관찰관의 지시에 따라 전자장치를 부착하여야 한다.', 2133);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3628, '③ 보호관찰소의 장은 제31조의2제1항에 따른 피고인의 보석조건 이행 여부 확인을 위하여 적절한 조치를 하여야 한다.', 2133);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3629, '④ 전자장치 부착 집행의 절차 및 방법 등에 관한 사항은 대통령령으로 정한다.', 2133);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3630, '① 보호관찰소의 장은 제31조의2제1항에 따른 피고인의 보석조건 이행 상황을 법원에 정기적으로 통지하여야 한다.', 2134);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3631, '② 보호관찰소의 장은 피고인이 제31조의2제1항에 따른 전자장치 부착명령을 위반한 경우 및 전자장치 부착을 통하여 피고인에게 부과된 주거의 제한 등 「형사소송법」에 따른 다른 보석조건을 위반하였음을 확인한 경우 지체 없이 법원과 검사에게 이를 통지하여야 한다.', 2134);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3632, '③ 제2항에 따른 통지를 받은 법원은 「형사소송법」 제102조에 따라 피고인의 보석조건을 변경하거나 보석을 취소하는 경우 이를 지체 없이 보호관찰소의 장에게 통지하여야 한다.', 2134);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3633, '④ 제1항부터 제3항까지의 규정에 따른 통지의 절차 및 방법 등에 관한 사항은 대통령령으로 정한다.', 2134);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3634, null, 2135);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3635, '① 법원은 「스토킹범죄의 처벌 등에 관한 법률」 제9조제1항제3호의2에 따른 잠정조치(이하 이 장에서 "잠정조치"라 한다)로 전자장치의 부착을 결정한 경우 그 결정문의 등본을 스토킹행위자의 사건 수사를 관할하는 경찰관서(이하 이 장에서 "관할경찰관서"라 한다)의 장과 스토킹행위자의 주거지를 관할하는 보호관찰소(이하 이 장에서 "보호관찰소"라 한다)의 장에게 지체 없이 송부하여야 한다.', 2136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3636, '② 잠정조치 결정을 받은 스토킹행위자는 법원이 지정한 일시까지 보호관찰소에 출석하여 대통령령으로 정하는 신상정보 등을 서면으로 신고한 후 보호관찰관의 지시에 따라 전자장치를 부착하여야 한다.', 2136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3637, '③ 보호관찰소의 장은 스토킹행위자가 제2항에 따라 전자장치를 부착하면 관할경찰관서의 장에게 이를 즉시 통지하여야 하고, 관할경찰관서의 장은 「스토킹범죄의 처벌 등에 관한 법률」 제9조제1항제2호 및 제3호의2에 따른 스토킹행위자의 잠정조치 이행 여부를 확인하기 위하여 피해자에 대한 다음 각 호의 사항을 보호관찰소의 장에게 즉시 통지하여야 한다.', 2136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3638, '④ 보호관찰소의 장은 스토킹행위자가 다음 각 호의 어느 하나에 해당하는 경우 그 사실을 관할경찰관서의 장에게 즉시 통지하여야 한다.', 2136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3639, '⑤ 관할경찰관서의 장은 제4항에 따른 통지가 있는 경우 즉시 스토킹행위자가 소재한 현장에 출동하는 등의 방법으로 그 사유를 확인하고, 「스토킹범죄의 처벌 등에 관한 법률」 제9조제1항제4호에 따른 유치 신청 등 피해자 보호에 필요한 적절한 조치를 하여야 한다.', 2136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3640, '⑥ 관할경찰관서의 장은 「스토킹범죄의 처벌 등에 관한 법률」 제11조제5항에 따라 잠정조치 결정이 효력을 상실하는 때에는 보호관찰소의 장에게 이를 지체 없이 통지하여야 한다.', 2136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3641, '⑦ 법원은 잠정조치의 연장ㆍ변경ㆍ취소 결정을 하는 경우 관할경찰관서의 장과 보호관찰소의 장에게 이를 지체 없이 통지하여야 한다.', 2136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3642, '⑧ 제1항부터 제7항까지에 따른 전자장치 부착의 집행 등에 필요한 사항은 대통령령으로 정한다.', 2136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3643, null, 2137);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3644, '① 보호관찰소의 장은 제31조의6제2항에 따라 전자장치를 부착한 스토킹행위자의 전자장치로부터 발신되는 전자파를 수신하여 그 자료(이하 "스토킹행위자 수신자료"라 한다)를 보존하여야 한다.', 2138);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3645, '② 스토킹행위자 수신자료는 다음 각 호의 경우 외에는 열람ㆍ조회ㆍ제공 또는 공개할 수 없다.', 2138);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3646, '③ 검사 또는 사법경찰관이 제2항제1호에 해당하는 사유로 스토킹행위자 수신자료를 열람 또는 조회하는 경우 그 절차에 관하여는 제16조제4항 및 제5항을 준용한다.', 2138);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3647, '④ 보호관찰소의 장은 다음 각 호의 어느 하나에 해당하는 때에는 스토킹행위자 수신자료를 폐기하여야 한다.', 2138);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3648, '①전자장치 부착기간은 이를 집행한 날부터 기산하되, 초일은 시간을 계산함이 없이 1일로 산정한다.', 2139);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3649, '② 다음 각 호의 어느 하나에 해당하는 기간은 전자장치 부착기간에 산입하지 아니한다. 다만, 보호관찰이 부과된 사람의 전자장치 부착기간은 보호관찰 기간을 초과할 수 없다. <개정 2018.3.20, 2023.7.11>', 2139);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3650, null, 2140);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3651, '① 법무부장관은 이 법에 따른 부착명령 또는 보호관찰명령의 집행이 종료된 사람의 재범 여부를 조사하고 부착명령 또는 보호관찰명령의 효과를 평가하기 위하여 필요한 경우에는 그 집행이 종료된 때부터 5년 동안 관계 기관에 그 사람에 관한 범죄경력자료와 수사경력자료에 대한 조회를 요청할 수 있다.', 2142);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3652, '② 제1항의 요청을 받은 관계 기관의 장은 정당한 사유 없이 이를 거부하여서는 아니 된다.', 2142);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3653, '①전자장치 부착 업무를 담당하는 자가 정당한 사유 없이 피부착자의 전자장치를 해제하거나 손상한 때에는 1년 이상의 유기징역에 처한다.', 2145);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3654, '②전자장치 부착 업무를 담당하는 자가 금품을 수수ㆍ요구 또는 약속하고 제1항의 죄를 범한 때에는 2년 이상의 유기징역에 처한다.', 2145);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3655, '③수신자료(스토킹행위자 수신자료를 포함한다)를 관리하는 자가 제16조제2항 또는 제31조의8제2항을 위반한 때에는 1년 이상의 유기징역에 처한다. <개정 2023.7.11>', 2145);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3656, '① 타인으로 하여금 부착명령 또는 보호관찰명령을 받게 할 목적으로 공무소 또는 공무원에 대하여 허위의 사실을 신고하거나 「형법」 제152조제1항의 죄를 범한 때에는 10년 이하의 징역에 처한다. <개정 2012.12.18>', 2146);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3657, '②제2장의 부착명령 또는 보호관찰명령 청구사건에 관하여 피부착명령청구자 또는 피보호관찰명령청구자를 모해할 목적으로 「형법」 제154조ㆍ제233조 또는 제234조(허위작성진단서의 행사에 한한다)의 죄를 범한 때에는 10년 이하의 징역에 처한다. 이 경우 10년 이하의 자격정지를 병과한다. <개정 2012.12.18, 2014.1.7>', 2146);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3658, '① 피부착자가 제14조제1항(제27조 및 제31조에 따라 준용되는 경우를 포함한다)을 위반하여 전자장치의 부착기간 중 전자장치를 신체에서 임의로 분리ㆍ손상, 전파 방해 또는 수신자료의 변조, 그 밖의 방법으로 그 효용을 해한 때에는 7년 이하의 징역 또는 2천만원 이하의 벌금에 처한다. <개정 2017.12.12>', 2147);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3659, '② 제1항의 미수범은 처벌한다. <신설 2017.12.12>', 2147);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3660, '① 피부착자 또는 보호관찰대상자가 제9조의2제1항제3호 또는 제4호의 준수사항을 정당한 사유 없이 위반한 때에는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다. <개정 2012.12.18, 2020.12.15>', 2148);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3661, '② 피부착자 또는 보호관찰대상자가 정당한 사유 없이 「보호관찰 등에 관한 법률」 제32조제2항 또는 제3항에 따른 준수사항을 위반하여 같은 법 제38조에 따른 경고를 받은 후 다시 정당한 사유 없이 같은 법 제32조제2항 또는 제3항에 따른 준수사항을 위반한 경우 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <신설 2012.12.18, 2020.12.15>', 2148);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3662, '③ 피부착자 또는 보호관찰대상자가 제9조의2제1항제1호ㆍ제2호ㆍ제2호의2ㆍ제5호 또는 제6호의 준수사항을 정당한 사유 없이 위반한 때에는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 2010.4.15, 2012.12.18, 2020.12.15>', 2148);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3663, null, 2150);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3664, '① 법무부장관은 법 제3조의2제2항에 따라 협약을 맺은 기관 또는 단체(이하 "연구개발기관"이라 한다)에 같은 조 제3항에 따라 출연금을 지급하는 경우 연구개발사업의 규모, 착수시기 및 정부의 재정 사정 등을 고려해 한꺼번에 지급하거나 나누어 지급할 수 있다.', 2152);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3665, '② 제1항에 따라 출연금을 지급받은 연구개발기관은 그 출연금을 별도의 계정(計定)을 설정하여 관리해야 한다.', 2152);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3666, '③ 제1항에 따라 출연금을 지급받은 연구개발기관은 그 출연금을 「국가연구개발혁신법 시행령」 별표 2에 따른 연구개발비 사용용도로만 사용해야 한다.', 2152);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3667, '④ 법무부장관은 연구개발기관이 정당한 사유 없이 제3항에 따른 용도 외의 용도로 제1항에 따라 지급받은 출연금을 사용한 경우에는 해당 금액을 회수해야 한다.', 2152);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3668, '⑤ 법 제3조의2제4항에 따른 보조금의 지급ㆍ사용 및 관리에 관하여는 「보조금 관리에 관한 법률」에서 정하는 바에 따른다.', 2152);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3669, '① 검사는 법 제6조제1항에 따라 보호관찰소(지소를 포함한다. 이하 같다)의 장에게 조사를 요청할 때에는 법 제5조제1항부터 제5항까지의 규정에 따른 전자장치를 부착하도록 하는 명령(이하 "부착명령"이라 한다)을 청구하는 피의자의 인적사항 및 범죄사실의 요지를 통보해야 한다. 이 경우 법무부령으로 정하는 참고자료를 보낼 수 있다. <개정 2009.7.30, 2010.7.12, 2013.5.31, 2024.1.9>', 2153);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3670, '② 보호관찰소의 장은 법 제6조제1항의 조사를 위해 교도소ㆍ소년교도소ㆍ구치소ㆍ군교도소의 장, 경찰서장, 국립법무병원장(이하 "수용기관의 장"이라 한다)에게 협조를 요청할 수 있다. 이 경우 수용기관의 장은 특별한 사유가 없으면 협조해야 한다. <개정 2024.1.9>', 2153);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3671, '① 법 제8조제1항제1호에서 "그 밖에 피부착명령청구자를 특정할 수 있는 사항"이란 피부착명령청구자의 주민등록번호, 직업, 주거, 등록기준지를 말하고, 같은 항 제4호에서 "대통령령으로 정하는 사항"이란 피부착명령청구자의 죄명을 말한다. <개정 2010.7.12>', 2154);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3672, '② 검사가 공소 제기와 동시에 부착명령을 청구할 경우에는 공소장에 부착명령 청구의 원인이 되는 사실과 적용 법조문을 추가하여 적는 것으로 부착명령 청구서를 대신할 수 있다.', 2154);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3673, '① 보호관찰관은 피부착명령자에 대한 판결문 등본, 법 제12조제2항의 부착명령 집행을 지휘한 서면, 그 밖의 관련 서류를 확인한 후 부착명령을 집행하여야 한다.', 2156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3674, '② 보호관찰관은 법 제13조제1항에 따라 부착명령을 집행하기에 앞서 피부착명령자에게 법 제14조와 이 영에 따른 피부착자의 의무사항 및 법 제38조 및 제39조에 따른 벌칙에 관한 사항을 알려야 한다.', 2156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3675, '③ 부착명령은 다음 각 호의 방법으로 집행한다. <개정 2018.2.13>', 2156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3676, '④ 보호관찰소의 장은 소속 보호관찰관이 부착명령을 집행하기 위하여 필요하면 수용기관의 장에게 협조를 요청할 수 있다. 이 경우 수용기관의 장은 특별한 사유가 없으면 협조하여야 한다.', 2156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3677, '⑤ 수용기관의 장은 피부착자가 부착명령의 집행 중 「형법」 제70조에 따른 노역장유치의 집행을 받게 된 경우 피부착자의 주거지를 관할하는 보호관찰소의 장에게 통보하여 담당 보호관찰관이 전자장치를 분리하여 회수하도록 하여야 하며, 피부착자가 노역장유치의 집행을 마치고 석방되기 전에 피부착자의 주거지를 관할하는 보호관찰소의 장에게 석방예정 사실을 통보하여 석방 전에 담당 보호관찰관이 피부착자에게 전자장치를 부착할 수 있도록 하여야 한다. <신설 2013.5.31>', 2156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3678, '① 보호관찰관은 법 제13조제6항에 따라 부착명령의 집행이 정지되면 지체 없이 전자장치를 분리하여 회수하여야 한다. 이 경우 부착명령의 집행기간은 신체에서 부착장치를 분리한 때부터 정지된다. <개정 2010.7.12, 2018.6.12>', 2157);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3679, '② 수용기관의 장은 법 제13조제6항 각 호의 사유로 피부착자가 구금된 경우에는 즉시 그의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다. <개정 2010.7.12, 2018.6.12>', 2157);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3680, '③ 보호관찰관은 법 제13조제8항에 따른 부착명령의 잔여기간 집행사유가 발생한 경우 다시 전자장치를 부착하여야 한다. 이 경우 부착명령의 집행기간은 신체에 부착장치를 부착한 때부터 진행한다. <개정 2010.7.12, 2018.6.12>', 2157);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3681, '④ 수용기관의 장은 법 제13조제8항제1호에 따른 부착명령의 잔여기간 집행사유가 발생한 경우 구금을 해제하기 전에 피부착명령자의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다. <개정 2010.7.12, 2018.6.12>', 2157);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3682, '⑤ 수용기관의 장은 법 제13조제8항제2호 및 제3호에 따른 부착명령의 잔여기간 집행사유가 발생한 경우 부착명령의 집행이 정지된 사람이 석방되기 5일 전까지 그의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다. <신설 2010.7.12, 2018.6.12>', 2157);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3683, '① 보호관찰관은 피부착자의 치료, 전자장치의 교체, 그 밖에 전자장치를 일시 분리할 필요가 있는 경우 보호관찰소의 장의 승인을 받아 전자장치의 전부 또는 일부를 피부착자의 신체 또는 주거에서 일시적으로 분리할 수 있다. 다만, 승인을 받을 시간적 여유가 없을 경우에는 분리한 후 지체 없이 보고하여야 한다.', 2159);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3684, '② 보호관찰관은 제1항의 일시 분리 사실을 대장에 적고 그 대장을 비치하여야 한다.', 2159);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3685, null, 2160);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3686, '① 법 제14조제2항에서 "대통령령으로 정하는 신상정보 등"이란 제15조의2제1항제1호부터 제8호까지의 사항 및 그 밖에 피부착자에 대한 지도ㆍ감독에 필요한 사항을 말한다. <개정 2018.6.12>', 2161);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3687, '② 피부착자는 법 제14조제3항에 따른 주거이전 등의 허가를 받으려고 할 때에는 본인의 성명, 주거, 주거이전 예정지나 국내여행 예정지 또는 출국 예정지, 주거이전 이유나 국내여행 목적 또는 출국 목적, 주거이전 일자나 국내여행 기간 또는 출국 기간 등을 적은 허가신청서와 소명자료를 보호관찰소에 출석하여 제출하여야 한다.', 2161);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3688, '③ 제2항에 따른 허가 신청을 받은 보호관찰관은 신청일부터 7일 이내에 주거이전 예정지나 국내여행 예정지 또는 출국 예정지, 주거이전 이유나 국내여행 목적, 출국의 목적 또는 법 제9조의2 및 「보호관찰 등에 관한 법률」 제32조에 따른 준수사항 이행 정도 등을 종합적으로 고려하여 허가 여부를 결정하여야 한다. <개정 2013.5.31>', 2161);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3689, '④ 보호관찰관은 제3항에 따라 피부착자의 출국 허가를 결정할 경우 피부착자가 다음 각 호의 어느 하나에 해당하는 경우에는 출국을 허가하지 아니할 수 있다. 다만, 제1호의 경우에는 출국을 허가하지 아니하여야 한다. <신설 2013.5.31>', 2161);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3690, '⑤ 보호관찰관은 제3항에 따라 피부착자의 출국 허가를 결정할 경우 그 허가기간을 출국일부터 3개월 이내의 범위에서 정하되, 불가피한 경우에만 이를 초과하여 정할 수 있다. <신설 2013.5.31>', 2161);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3691, '⑥ 피부착자는 주거이전 허가를 받아 다른 보호관찰소의 관할 구역으로 주거를 이전한 경우 3일 이내에 새로운 주거지를 관할하는 보호관찰소에 출석하여 제1항의 신고를 하여야 한다. <개정 2013.5.31>', 2161);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3692, '⑦ 보호관찰소의 장은 소속 보호관찰관이 제3항에 따라 피부착자에게 출국을 허가한 경우 법무부장관에게 피부착자의 출입국 사실을 통보하여 줄 것을 요청하여야 한다. <개정 2013.5.31>', 2161);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3693, '⑧ 법무부장관은 제7항에 따른 요청을 받은 경우에는 피부착자의 출입국 시 지체 없이 그 사실을 보호관찰소의 장에게 통보하여야 한다. <개정 2013.5.31>', 2161);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3694, '⑨ 제3항에 따른 출국 허가를 받아 출국했던 피부착자는 입국한 후 지체 없이 관할 보호관찰소에 출석하여 전자장치가 정상적으로 작동하는지를 확인받아야 한다. <개정 2013.5.31>', 2161);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3695, '① 보호관찰소의 장은 법 제14조의2에 따라 부착기간의 연장을 신청하거나 같은 조 또는 법 제14조의3에 따라 준수사항의 부과ㆍ추가ㆍ변경ㆍ삭제를 신청하는 경우에는 다음 각 호의 사항을 적은 서면으로 신청해야 한다. <개정 2021.9.14>', 2162);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3696, '② 보호관찰소의 장은 제1항의 신청을 할 때 신청사유를 소명할 수 있는 자료를 제출하여야 한다.', 2162);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3697, '③ 법원은 법 제14조의2 또는 제14조의3에 따른 청구의 심리를 위하여 필요한 경우에는 담당 보호관찰관을 출석시켜 의견을 들을 수 있고, 피부착자 또는 피부착명령자를 소환하여 심문하거나 필요한 사항을 확인할 수 있다. <개정 2021.9.14>', 2162);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3698, '① 법무부장관은 다음 각 호의 시설 또는 단체를 지정하여 법 제15조제2항의 치료 및 상담치료 등을 실시하게 할 수 있다. <개정 2009.7.30, 2010.12.29, 2017.5.29>', 2163);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3699, '② 법무부장관은 제1항의 치료 및 상담치료 등에 대하여 예산의 범위에서 비용의 전부 또는 일부를 지급할 수 있다.', 2163);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3700, '③ 법무부장관은 제1항의 치료 및 상담치료에 필요한 프로그램의 개발과 전문인력의 양성을 위하여 노력하여야 한다.', 2163);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3701, '④ 법무부장관은 제1항에 따른 지정을 받은 시설 또는 단체가 치료 및 상담치료 등을 실시하기에 부적당한 경우 그 지정을 취소할 수 있다. <신설 2010.7.12>', 2163);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3702, '① 검사는 법 제16조제4항 본문에 따라 수신자료를 열람 또는 조회하려는 경우에는 관할 법원에 피부착자에 대한 수신자료의 열람 또는 조회를 허가하여 줄 것을 청구할 수 있다.', 2165);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3703, '② 사법경찰관은 법 제16조제4항 본문에 따라 수신자료를 열람 또는 조회하려는 경우 검사에게 피부착자에 대한 수신자료의 열람 또는 조회에 대한 허가를 신청하고, 검사는 관할 법원에 그 허가를 청구할 수 있다.', 2165);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3704, '③ 제1항 및 제2항에 따른 수신자료 열람 또는 조회의 허가 청구 또는 신청은 피부착자의 인적사항, 수신자료 제공기관, 청구ㆍ신청 사유 및 필요한 자료의 범위를 적은 서면으로 하여야 한다.', 2165);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3705, '④ 검사 또는 사법경찰관은 법 제16조제4항 본문에 따라 수신자료를 열람 또는 조회하는 경우에는 보호관찰소의 장(위치추적 관제센터의 장을 포함한다. 이하 제14조의3부터 제14조의6까지에서 같다)에게 관할 법원의 허가서 사본을 내주어야 한다. <개정 2021.9.14, 2024.1.9>', 2165);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3706, '① 검사 또는 사법경찰관은 법 제16조제4항 단서에 따라 수신자료의 열람 또는 조회를 요청하는 경우에는 보호관찰소의 장에게 다음 각 호의 서류를 팩스 등의 방법으로 제시하여야 한다.', 2166);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3707, '② 검사는 제1항에 따른 긴급 수신자료 열람 또는 조회를 요청한 경우에는 지체 없이 관할 법원에 그 허가를 청구하여야 한다.', 2166);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3708, '③ 사법경찰관은 제1항에 따른 긴급 수신자료 열람 또는 조회를 요청한 경우에는 지체 없이 검사에게 긴급 수신자료 열람 또는 조회에 대한 허가를 신청하고, 검사는 관할 법원에 그 허가를 청구할 수 있다.', 2166);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3709, '④ 검사 또는 사법경찰관이 법 제16조제4항 단서에 따라 보호관찰소의 장에게 송부하여야 할 자료는 관할 법원의 허가서 사본으로 한다.', 2166);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3710, '① 검사 또는 사법경찰관은 법 제16조제4항과 제5항에 따른 수신자료의 열람 또는 조회 허가 신청 및 청구 현황, 수신자료 열람 또는 조회 사실을 적은 대장을 3년간 소속 기관에 갖추어 두어야 한다.', 2167);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3711, '② 보호관찰소의 장은 검사 또는 사법경찰관에게 수신자료를 열람 또는 조회하게 하였을 때에는 해당 수신자료 열람 또는 조회 사실을 적은 대장과 수신자료 열람ㆍ조회 요청서 등 관련 자료를 3년간 갖추어 두어야 한다.', 2167);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3712, '③ 검사가 제14조의3제3항에 따른 사법경찰관의 허가 신청을 기각하면 사법경찰관은 지체 없이 열람 또는 조회한 수신자료를 폐기하여야 한다.', 2167);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3713, '④ 검사 또는 사법경찰관은 법 제16조제5항 또는 이 조 제3항에 따라 열람 또는 조회한 수신자료를 폐기하였을 때에는 지체 없이 그 사실을 서면으로 보호관찰소의 장에게 통지하여야 한다.', 2167);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3714, '① 검사 또는 사법경찰관은 수신자료를 열람 또는 조회하여 수사한 사건에 관하여 공소를 제기하거나 공소의 제기 또는 입건을 하지 아니하는 처분(기소중지결정은 제외한다)을 하였을 때에는 그 처분의 결과를 수신자료를 제공한 보호관찰소의 장에게 서면으로 통지하여야 한다.', 2168);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3715, '② 사법경찰관은 수신자료를 열람 또는 조회하여 수사한 사건을 종결하는 경우에는 그 결과를 검사에게 보고하여야 한다. 다만, 그 사건을 검찰에 송치하는 경우에는 그러하지 아니하다.', 2168);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3716, '① 전자장치 부착기간이 끝난 사람이 부착을 마친 날부터 5년 내에 자격정지 이상의 형을 받은 경우에는 그 형의 집행이 끝난 날부터 5년이 지난 때에 수신자료를 폐기한다.', 2170);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3717, '② 수신자료의 폐기는 전산자료에서 삭제하는 방법으로 한다.', 2170);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3718, '① 법 제16조의2제1항에 따라 보호관찰소의 장이 피부착자의 주거지를 관할하는 경찰관서의 장 등 수사기관에 제공할 수 있는 피부착자의 신상정보는 다음 각 호와 같다. <개정 2015.1.20>', 2171);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3719, '② 법 제16조의2제3항에 따라 보호관찰소의 장이 수사기관에 통보하는 사항은 다음 각 호와 같다.', 2171);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3720, '③ 법 제16조의2제4항에 따라 수사기관이 보호관찰소의 장에게 통보하는 사항은 다음 각 호와 같다.', 2171);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3721, '④ 제1항에 따른 피부착자 신상정보의 제공은 보호관찰소의 장이 관리하는 제1항 각 호의 피부착자 신상정보에 관한 전자기록을 「형사사법절차 전자화 촉진법」 제2조제4호에 따른 형사사법정보시스템에 등록하고, 수사기관은 이를 조회하는 방식 등으로 할 수 있다.', 2171);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3722, '⑤ 수사기관의 장은 제4항에 따라 조회한 피부착자의 신상정보를 문서로 출력한 경우 제1항제7호에 따른 전자장치 부착기간이 끝나면 그 문서를 폐기하여야 한다.', 2171);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3723, '① 법 제17조제1항에 따른 부착명령의 임시해제 신청은 「보호관찰 등에 관한 법률」 제5조에 따른 보호관찰심사위원회(이하 "심사위원회"라 한다)에 서면으로 해야 한다. <개정 2020.8.5>', 2172);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3724, '② 심사위원회는 피부착자 또는 그 법정대리인이 부착명령의 임시해제를 신청한 경우 지체 없이 그 사실을 보호관찰소의 장에게 통보해야 한다. <개정 2020.8.5>', 2172);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3725, '① 심사위원회는 법 제18조제1항에 따라 부착명령의 임시해제를 심사할 때에는 보호관찰관, 정신건강의학과 의사, 정신보건임상심리사, 그 밖의 전문가의 의견을 고려해야 한다. <개정 2011.11.23, 2013.5.31, 2020.8.5>', 2173);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3726, '② 심사위원회는 법 제18조제4항 및 제5항의 결정을 하면 지체 없이 그 결정서 등본을 관할 보호관찰소의 장과 신청인에게 송달하여야 한다.', 2173);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3727, '③ 보호관찰관은 법 제18조제4항의 부착명령 임시해제 결정이 있으면 결정서에 기재된 임시해제일에 전자장치를 회수해야 한다. <개정 2020.8.5>', 2173);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3728, '④ 심사위원회가 제1항에 따라 전문가 의견을 고려한 경우 의견을 진술하거나 자료를 제출한 전문가에게는 예산의 범위에서 필요한 비용의 전부 또는 일부를 지급할 수 있다. <신설 2010.7.12>', 2173);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3729, '① 법 제19조제1항에 따른 임시해제의 취소신청은 심사위원회에 서면으로 해야 한다. <신설 2013.5.31, 2020.8.5>', 2174);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3730, '② 심사위원회는 법 제19조제1항에 따라 부착명령의 임시해제 취소 결정을 했을 때에는 지체 없이 그 사실을 관할 보호관찰소의 장에게 통보해야 한다. <개정 2013.5.31, 2020.8.5>', 2174);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3731, '③ 보호관찰관은 부착명령의 임시해제 취소결정이 있으면 피부착명령자에게 결정서를 제시한 후 전자장치를 부착해야 한다. <개정 2013.5.31, 2020.8.5>', 2174);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3732, '④ 임시해제가 취소된 경우 부착명령 집행기간은 부착장치를 피부착명령자의 신체에 부착한 때부터 진행한다. <개정 2013.5.31, 2020.8.5>', 2174);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3733, '① 보호관찰소의 장은 법 제21조의7에 따라 보호관찰 기간의 연장 또는 준수사항의 추가ㆍ변경ㆍ삭제를 신청하는 경우에는 다음 각 호의 사항을 적은 서면으로 하여야 한다.', 2175);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3734, '② 보호관찰소의 장은 제1항의 신청을 할 때 신청사유를 소명할 수 있는 자료를 제출하여야 한다.', 2175);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3735, '③ 법원은 법 제21조의7에 따른 청구의 심리를 위하여 필요한 경우에는 담당 보호관찰관을 출석시켜 의견을 들을 수 있으며, 보호관찰대상자를 소환하여 심문(審問)하거나 필요한 사항을 확인할 수 있다.', 2175);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3736, '① 교도소ㆍ소년교도소ㆍ구치소의 장은 가석방 예정자에 대한 심사위원회의 법 제22조제3항에 따른 전자장치 부착의 필요성과 적합성 여부 등의 조사(이하 "전자장치 부착 적합성조사"라 한다)를 위해 「형의 집행 및 수용자의 처우에 관한 법률」 및 관계 법령에 따라 가석방 적격심사 신청 대상자가 선정되면 지체 없이 해당 대상자에 대한 다음 각 호의 사항이 포함된 자료를 해당 교도소ㆍ소년교도소ㆍ구치소의 소재지를 관할하는 심사위원회에 보내야 한다.', 2177);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3737, '② 심사위원회는 제1항에 따라 교도소ㆍ소년교도소ㆍ구치소의 장으로부터 자료를 받은 경우에는 가석방 예정자에 대한 전자장치 부착 적합성조사를 하거나, 교도소ㆍ소년교도소ㆍ구치소의 소재지 또는 해당 가석방 예정자의 거주예정지를 관할하는 보호관찰소의 장과 협의하여 보호관찰소의 장에게 전자장치 부착 적합성조사를 위하여 필요한 사항의 조사를 의뢰할 수 있다.', 2177);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3738, '③ 보호관찰소의 장은 제2항에 따른 의뢰를 받은 경우에는 필요한 조사를 하고 그 결과를 심사위원회에 통보해야 한다.', 2177);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3739, '④ 교도소ㆍ소년교도소ㆍ구치소의 장은 심사위원회 또는 보호관찰소의 장으로부터 제2항 또는 제3항에 따른 전자장치 부착 적합성조사 등을 위한 가석방 예정자 면담 등 필요한 협조를 요청받은 경우 특별한 사정이 없으면 이에 협조해야 한다.', 2177);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3740, '⑤ 심사위원회 또는 보호관찰소의 장은 전자장치 부착 적합성조사를 위해 필요하다고 인정하면 국가기관, 지방자치단체 또는 공공기관의 장에게 사실을 알아보거나 관련 자료의 열람 등 협조를 요청할 수 있다. 이 경우 해당 기관의 장은 특별한 사정이 없는 한 이에 협조해야 한다.', 2177);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3741, '⑥ 전자장치 부착 적합성조사의 내용에는 가석방 예정자의 범죄경력, 범죄내용 및 직업, 경제력, 생활환경 등 개별적 특성에 관한 사항이 포함되어야 한다.', 2177);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3742, '① 심사위원회는 「보호관찰 등에 관한 법률」 제24조제1항에 따른 보호관찰 결정서 등본을 수용기관의 장에게 송달하면서 법 제22조제1항 및 제2항에 따른 전자장치 부착에 관한 사항을 함께 통보해야 한다. <개정 2020.8.5>', 2178);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3743, '② 「치료감호 등에 관한 법률」 제37조에 따른 치료감호심의위원회는 법 제23조제1항에 따라 피치료감호자 또는 피보호감호자에게 전자장치를 부착하는 결정을 한 경우 그 결정서를 피치료감호자 또는 피보호감호자에게, 결정서 등본을 수용기관의 장(보호감호시설의 장을 포함한다. 이하 이 장에서 같다)에게 각각 송달하여야 한다. <개정 2010.7.12, 2016.11.29>', 2178);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3744, '③ 제1항 또는 제2항에 따라 결정서 등본을 송달받은 수용기관의 장은 전자장치를 부착하게 될 가석방예정자, 피치료감호자 또는 피보호감호자에게 전자장치 부착에 관한 내용을 알려주어야 한다. <개정 2010.7.12>', 2178);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3745, '① 치료감호시설의 장 및 보호감호시설의 장은 법 제23조제1항에 따라 전자장치 부착결정을 받은 사람(이하 "피부착결정자"라 한다)을 다른 수용기관으로 이송할 경우 그 수용기관의 장에게 이송되는 사람이 전자장치 부착결정을 받았음을 통보하여야 한다. <개정 2010.7.12>', 2179);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3746, '② 제1항에 따라 피부착결정자를 인수한 수용기관의 장은 그가 출소하기 5일 전까지 그 주거지를 관할하는 보호관찰소의 장에게 피부착결정자의 석방 예정 사실을 통보하여야 한다.', 2179);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3747, '① 법원은 법 제31조의2제2항에 따라 보호관찰소의 장에게 조사를 의뢰하는 경우에는 피고인의 인적사항 및 범죄사실의 요지를 통보해야 한다. 이 경우 필요하면 참고자료를 보낼 수 있다.', 2183);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3748, '② 보호관찰소의 장은 법 제31조의2제3항에 따른 조사를 위해 수용기관의 장에게 협조를 요청할 수 있다. 이 경우 수용기관의 장은 특별한 사유가 없으면 이에 협조해야 한다.', 2183);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3749, '① 보호관찰관은 법 제31조의3제2항에 따라 부착명령을 집행하는 경우 같은 조 제1항에 따라 송부된 전자장치 보석피고인에 대한 결정문 등본(제23조의3에 따른 사본을 포함한다)을 확인한 후 전자장치를 부착해야 한다.', 2186);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3750, '② 보호관찰관은 제1항에 따라 전자장치를 부착하기 전에 전자장치 보석피고인에게 다음 각 호의 내용을 알려주어야 한다.', 2186);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3751, '③ 전자장치의 부착은 다음 각 호의 방법으로 한다.', 2186);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3752, '④ 보호관찰소의 장은 법 제31조의3제3항에 따라 피고인의 보석조건 이행 여부를 확인하기 위하여 국가기관, 지방자치단체 또는 공공기관의 장에게 사실을 알아보거나 관련 자료의 열람 등 협조를 요청할 수 있다. 이 경우 해당 기관의 장은 특별한 사정이 없는 한 이에 협조해야 한다. <신설 2021.9.14>', 2186);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3753, '① 보호관찰소의 장은 법 제31조의4제1항에 따라 피고인의 보석조건 이행상황을 매월 말일을 기준으로 작성하여 그 다음달 10일까지 보석결정을 한 법원에 송부해야 한다.', 2187);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3754, '② 제1항에도 불구하고 법원은 피고인의 재판을 위해 피고인의 보석조건 이행상황을 신속하게 파악할 필요가 있는 경우에는 보호관찰소의 장에게 피고인의 보석조건 이행상황에 관한 자료를 요청할 수 있다.', 2187);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3755, '① 보호관찰소의 장은 전자장치 보석피고인이 다음 각 호의 어느 하나에 해당하는 경우 법 제31조의4제2항에 따라 보석결정을 한 법원과 그 법원에 대응하는 검찰청 검사에게 지체 없이 통지해야 한다.', 2188);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3756, '② 제1항에 따른 통지는 인편 또는 등기우편의 방법으로 한다. 다만, 긴급한 경우에는 전화ㆍ팩스ㆍ전자우편 등의 방법으로 먼저 통지하고 사후에 인편 또는 등기우편의 방법으로 할 수 있다.', 2188);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3757, null, 2191);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3758, '① 법 제31조의6제2항에서 "대통령령으로 정하는 신상정보 등"이란 다음 각 호의 사항을 말한다.', 2192);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3759, '② 전자장치 스토킹행위자는 전자장치 부착의 집행 중 제1항제1호, 제2호 및 제4호부터 제6호까지의 사항이 변경된 경우에는 주거지를 관할하는 보호관찰소의 장에게 전화 등의 방법으로 지체 없이 그 사실을 신고해야 한다.', 2192);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3760, '③ 전자장치 스토킹행위자는 전자장치 부착의 집행 중 제1항제3호의 사항이 변경된 경우에는 지체 없이 주거지를 관할하는 보호관찰소에 출석하여 그 사실을 신고해야 한다.', 2192);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3761, '④ 제3항에도 불구하고 전자장치 스토킹행위자는 전자장치 부착의 집행 중 다른 보호관찰소의 관할 구역으로 주거지를 이전한 경우에는 3일 이내에 새로운 주거지를 관할하는 보호관찰소에 출석하여 제1항 각 호의 사항을 서면으로 신고해야 한다.', 2192);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3762, '⑤ 전자장치 스토킹행위자의 주거지를 관할하는 보호관찰소(이하 이 장에서 "보호관찰소"라 한다)의 장은 제2항부터 제4항까지의 규정에 따른 신고를 받은 경우에는 관할경찰관서의 장에게 지체 없이 그 사실을 통지해야 한다.', 2192);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3763, '① 보호관찰관은 법 제31조의6제2항에 따라 전자장치를 부착하는 경우 같은 조 제1항에 따라 송부된 전자장치 스토킹행위자에 대한 결정문 등본(제23조의10에 따른 사본을 포함한다)을 확인한 후 전자장치를 부착해야 한다.', 2193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3764, '② 보호관찰관은 제1항에 따라 전자장치를 부착하기 전에 전자장치 스토킹행위자에게 전자장치 효용 유지를 위해 필요한 다음 각 호의 의무 사항을 알려주어야 한다.', 2193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3765, '③ 보호관찰관은 제1항에 따라 전자장치를 부착하면 지체 없이 전자장치 스토킹행위자와 피해자가 서로 근접하는지 여부를 확인할 수 있는 장치 또는 시스템(이하 이 항에서 "피해자장치등"이라 한다)을 피해자에게 제공해야 한다. 다만, 피해자와 연락이 되지 않거나 피해자가 피해자장치등의 수령을 거부하는 등의 사유로 피해자장치등을 제공할 수 없는 경우에는 피해자 보호 업무를 담당하는 사법경찰관리에게 휴대전화 문자전송, 전자우편, 팩스 또는 전화 등의 방법으로 지체 없이 그 사실을 통지해야 한다.', 2193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3766, '① 보호관찰소의 장은 법 제31조의6제3항 각 호 외의 부분에 따라 관할경찰관서의 장에게 전자장치 스토킹행위자가 전자장치를 부착한 사실을 통지할 때에는 제23조의11제1항 각 호의 사항과 그 밖에 피해자 보호를 위해 필요한 사항을 함께 통지해야 한다.', 2194);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3767, '② 법 제31조의6제3항제6호에서 "대통령령으로 정하는 피해자의 보호를 위하여 필요한 사항"이란 다음 각 호의 사항을 말한다.', 2194);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3768, '③ 관할경찰관서의 장은 전자장치 부착의 집행 중 법 제31조의6제3항 각 호의 사항이 변경된 것을 안 때에는 보호관찰소의 장에게 즉시 그 사실을 통지해야 한다.', 2194);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3769, '① 법 제31조의6제4항제4호에서 "대통령령으로 정하는 사유가 있는 경우"란 다음 각 호의 경우를 말한다.', 2195);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3770, '② 보호관찰소의 장 또는 위치추적 관제센터의 장은 전자장치 스토킹행위자가 법 제31조의6제4항 각 호의 어느 하나에 해당하는 경우에는 관할경찰관서의 장 또는 시ㆍ도경찰청 112치안종합상황실장에게 휴대전화 문자전송, 전자우편, 팩스 또는 전화 등의 방법으로 즉시 그 사실을 통지해야 한다.', 2195);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3771, '③ 제1항 및 제2항에서 규정한 사항 외에 피해자의 보호 방법 및 절차 등에 관한 세부 사항은 경찰청장이 법무부장관과 협의하여 정한다.', 2195);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3772, null, 2199);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3773, '① 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제1호 및 제3항제1호에 따라 성폭력범죄를 저질러 2008년 9월 1일 이전에 제1심판결을 선고받아 2010년 7월 16일 기준으로 징역형 이상의 형, 치료감호 또는 보호감호(이하 "징역형등"이라 한다)의 집행 종료일까지 6개월 이상이 남은 사람(이하 "출소예정자"라 한다), 징역형등의 집행 종료일까지 6개월 미만이 남은 사람(이하 "출소임박자"라 한다) 및 징역형등의 집행이 종료, 가종료ㆍ가출소ㆍ가석방 또는 면제된 후 3년이 경과되지 아니한 사람(이하 "출소자"라 한다)에 대하여 교도소ㆍ구치소ㆍ치료감호시설ㆍ보호감호시설(이하 "수용시설"이라 한다)의 장이 수용시설의 소재지를 관할하는 지방검찰청의 검사에게 통보하여야 할 사항은 다음 각 호와 같다.', 2201);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3774, '② 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제1호 및 제3항제1호에 따라 성폭력범죄를 저질러 2008년 9월 1일 이전에 제1심판결을 선고받아 2010년 7월 16일 기준으로 출소예정자, 출소임박자, 출소자(이하 "출소자등"이라 한다)인 사람에 대하여 수용시설의 장이 수용시설의 소재지를 관할하는 보호관찰소의 장에게 통보하여야 할 사항은 출소자등의 성명, 주민등록번호, 주소, 출소예정일 및 죄명으로 한다.', 2201);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3775, '① 법원은 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제5호 및 제3항제8호에 따라 출소자등에 대하여 부착명령을 결정한 경우에는 부착명령을 받은 사람에게 그 결정을 고지하여야 한다.', 2204);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3776, '② 법원은 제1항에 따라 결정이 고지된 날부터 3일 이내에 부착명령을 고지받은 사람의 주거지를 관할하는 보호관찰소의 장에게 결정문 등본을 송부하여야 한다.', 2204);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3777, '③ 수용시설의 장은 부착명령을 고지받은 사람이 석방되기 5일 전까지 그의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다.', 2204);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3778, '① 출소자등에 대한 부착명령은 부착명령이 고지된 후 지체 없이 검사의 지휘를 받아 보호관찰관이 집행한다.', 2205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3779, '② 제1항에 따른 지휘는 결정문 등본을 첨부한 서면으로 한다.', 2205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3780, '① 법무부장관은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 2206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3781, '② 검사는 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호 또는 제2호에 따른 유전정보 또는 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. 다만, 제9호의2의 사무의 경우에는 「개인정보 보호법」 제23조에 따른 성생활에 관한 정보 및 같은 법 시행령 제18조제1호에 따른 유전정보에 해당하는 정보는 제외한다. <개정 2021.9.14, 2024.1.9>', 2206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3782, '③ 보호관찰소의 장 또는 보호관찰관은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호 또는 제2호에 따른 유전정보 또는 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. 다만, 제16호의2 및 제16호의3의 사무의 경우에는 「개인정보 보호법」 제23조에 따른 성생활에 관한 정보 및 같은 법 시행령 제18조제1호에 따른 유전정보에 해당하는 정보는 제외한다. <개정 2021.9.14, 2024.1.9>', 2206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3783, '④ 심사위원회는 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호 또는 제2호에 따른 유전정보 또는 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 2206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3784, '⑤ 치료감호심의위원회는 법 제23조 및 제24조에 따른 전자장치 부착에 관한 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호 또는 제2호에 따른 유전정보 또는 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 2206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3785, '⑥ 수용기관의 장 또는 수용시설의 장은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 2206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3786, '⑦ 경찰관서의 장 등 수사기관은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2024.1.9>', 2206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3787, '⑧ 사법경찰관은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2024.1.9>', 2206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3788, '① 「전자장치 부착 등에 관한 법률」(이하 "법"이라 한다) 제6조제1항, 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제2호 및 제3항제2호에 따른 조사요청은 별지 제1호서식의 부착명령 청구 전 조사 요청서에 따른다. <개정 2009.7.30, 2010.7.15, 2013.5.31, 2020.8.5>', 2209);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3789, '② 「전자장치 부착 등에 관한 법률 시행령」(이하 "영"이라 한다) 제4조제1항 후단에 따른 참고자료란 피의자 신문조서, 피해자 진술조서, 범죄경력자료 및 수사경력자료 등을 말한다. <개정 2010.7.15, 2013.5.31, 2020.8.5>', 2209);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3790, '① 법 제8조의 부착명령청구서는 별지 제2호서식과 같다. 다만, 공소제기와 동시에 부착명령을 청구하는 경우에는 영 제5조제2항에 따라 별지 제3호서식의 공소장 및 부착명령청구서로 할 수 있다.', 2210);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3791, '② 공소를 제기한 후에 부착명령을 청구하는 경우에는 부착명령 청구사건과 병합심리할 피고사건의 법원명, 사건번호, 피고인명, 죄명 등을 명시하여 부착명령 청구사건의 관할법원에 병합심리를 신청하여야 한다.', 2210);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3792, '① 법 제12조(법 제31조에 따라 준용되는 경우를 포함한다) 및 영 제28조제1항의 집행지휘는 별지 제5호서식의 부착명령 집행지휘서에 따른다. <개정 2010.7.15>', 2212);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3793, '② 검사는 부착명령과 병과된 형의 집행지휘서의 비고란에 "부착명령"이라고 붉은 색으로 적어야 한다.', 2212);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3794, '① 영 제12조제1항(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 신고는 별지 제9호서식의 신고서에 따른다. <개정 2013.5.31>', 2216);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3795, '② 영 제12조제2항 및 제3항(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 허가 신청 및 허가는 각각 별지 제10호서식의 주거이전, 국내여행 또는 출국 허가신청서와 별지 제11호서식의 주거이전, 국내여행 또는 출국 허가서에 따른다. <개정 2013.5.31>', 2216);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3796, '③ 영 제12조제7항(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 통보요청은 별지 제12호서식의 출입국사실 통보 요청서에 따른다. <개정 2013.5.31>', 2216);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3797, '① 법 제14조의2, 제14조의3 및 영 제12조의2에 따른 부착기간의 연장 또는 준수사항의 부과ㆍ추가ㆍ변경ㆍ삭제의 신청은 별지 제13호서식에 따른다.', 2217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3798, '② 법 제14조의2 또는 제14조의3에 따른 부착기간의 연장 또는 준수사항의 부과ㆍ추가ㆍ변경ㆍ삭제의 청구는 별지 제14호서식에 따른다.', 2217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3799, '① 영 제13조제1항에 따라 치료 및 상담치료 등을 실시할 수 있는 시설 또는 단체로 지정을 받으려는 자(이하 "신청인"이라 한다)는 별지 제15호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정 신청서에 다음 각 호의 서류를 첨부하여 주소지를 관할하는 보호관찰소(지소를 포함한다. 이하 같다)의 장에게 제출해야 한다. <개정 2013.5.31, 2022.2.7, 2022.12.19>', 2218);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3800, '② 제1항에 따른 신청서를 받은 담당 공무원은 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 다음 각 호의 서류의 내용을 확인하여야 한다.', 2218);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3801, '③ 제1항에 따른 신청을 받은 경우 보호관찰소의 장은 신청일부터 14일 이내에 별지 제16호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정신청에 대한 의견서와 함께 신청인이 제출한 특정 범죄자 치료기관 또는 상담치료기관 지정 신청서와 첨부서류를 법무부장관에게 보내야 한다. <개정 2013.5.31>', 2218);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3802, '④ 법무부장관은 영 제13조제1항에 따라 신청인을 치료 및 상담치료 등을 실시할 수 있는 시설 또는 단체로 지정할 때에는 신청인에게 별지 제17호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정서를 발급하여야 한다. <개정 2013.5.31>', 2218);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3803, '⑤ 영 제13조제1항에 따른 지정을 받은 시설 또는 단체는 다음 각 호의 어느 하나에 해당하는 사항을 변경하려면 별지 제18호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정사항 변경신청서에 변경된 사항을 증명하는 서류 등을 첨부하여 주소지를 관할하는 보호관찰소의 장에게 제출하여야 한다. <개정 2013.5.31>', 2218);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3804, '⑥ 제5항에 따른 변경신청을 받은 경우 보호관찰소의 장은 변경신청일부터 14일 이내에 별지 제19호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정사항 변경신청에 대한 의견서와 변경신청을 한 시설 또는 단체가 제출한 특정 범죄자 치료기관 또는 상담치료기관 지정사항 변경신청서 및 첨부서류를 법무부장관에게 보내야 한다. <개정 2013.5.31>', 2218);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3805, '⑦ 법무부장관은 제5항에 따른 지정사항 변경신청이 적정하다고 판단되는 경우 변경내용이 기재된 제17호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정서를 신청인에게 다시 발급하여야 한다. <개정 2013.5.31>', 2218);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3806, '⑧ 보호관찰소의 장은 법무부장관에게 영 제13조제1항에 따른 지정을 받은 시설 또는 단체의 시설이나 특정 범죄자 치료 및 교정 프로그램이 특정 범죄자의 치료ㆍ개선에 적당한지 여부와 그 운영실태를 정기적으로 보고하여야 한다.', 2218);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3807, '⑨ 법무부장관은 제8항에 따른 보고 결과 영 제13조제1항에 따른 지정을 받은 시설 또는 단체의 시설이나 특정 범죄자 치료 및 교정 프로그램이 특정 범죄자의 치료ㆍ개선에 부적당하다고 인정하면 지정을 취소할 수 있다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 지정을 취소하여야 한다. <개정 2013.5.31>', 2218);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3808, '① 보호관찰관은 법 제15조제3항에 따라 피부착자의 형 또는 치료감호 집행 중의 생활실태를 확인할 수 있는 자료를 요청하거나 피부착자를 면접하려는 경우에는 보호관찰소의 장을 통하여 교도소, 소년교도소, 구치소, 국립법무병원 및 군교도소의 장(이하 "교도소장등"이라 한다)에게 다음 사항을 적은 서면(전자문서를 포함한다)을 제출하여야 한다. <개정 2022.7.4>', 2219);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3809, '② 교도소장등은 제1항의 요청에 대하여 보호관찰소의 장에게 서면(전자문서를 포함한다)으로 회신하여야 한다. 다만, 생활실태 확인을 위한 자료는 「형사사법절차 전자화 촉진법」에 따른 형사사법정보시스템을 통하여 보호관찰소의 장에게 제공하는 방법으로 회신할 수 있다.', 2219);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3810, '③ 제1항에 따른 보호관찰관의 자료 또는 면접 요청은 별지 제20호서식에 따른다.', 2219);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3811, '④ 제2항 본문에 따른 교도소장등의 회신은 별지 제21호서식에 따른다.', 2219);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3812, '① 검사가 영 제14조의2제1항에 따라 수신자료의 열람ㆍ조회 허가청구를 하는 경우에는 별지 제23호서식에 따른다.', 2221);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3813, '② 사법경찰관이 영 제14조의2제2항에 따른 수신자료 열람ㆍ조회 허가신청을 하는 경우에는 별지 제24호서식에 따른다.', 2221);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3814, '③ 검사가 영 제14조의2제2항에 따라 사법경찰관으로부터 수신자료의 열람ㆍ조회 허가신청을 받아 수신자료 열람ㆍ조회 허가청구를 하는 경우에는 별지 제25호서식에 따른다.', 2221);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3815, '① 검사 또는 사법경찰관이 영 제14조의3제1항에 따라 보호관찰소의 장에게 긴급 수신자료 열람ㆍ조회를 요청하는 경우에는 별지 제26호서식에 따른다.', 2222);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3816, '② 영 제14조의3제2항에 따른 긴급 수신자료 열람 또는 조회의 허가청구는 별지 제27호서식에 따른다.', 2222);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3817, '③ 영 제14조의3제3항에 따른 긴급 수신자료 열람 또는 조회의 허가신청 및 허가청구는 각각 별지 제28호서식 및 별지 제29호서식에 따른다.', 2222);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3818, '① 검사 또는 사법경찰관은 법 제16조제4항 본문에 따라 수신자료를 열람 또는 조회한 때에는 별지 제30호서식의 수신자료 열람ㆍ조회 대장에 해당 사항을 적어야 하고, 법 제16조제4항 단서에 따라 수신자료를 열람 또는 조회한 때에는 별지 제31호서식의 긴급 수신자료 열람ㆍ조회 대장에 해당 사항을 적어야 한다.', 2223);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3819, '② 보호관찰소의 장은 법 제16조제4항에 따라 수신자료를 열람 또는 조회하게 한 때에는 별지 제32호서식의 수신자료 열람ㆍ조회 접수 대장에 해당 사항을 적어야 한다.', 2223);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3820, '③ 영 제14조의4제4항에 따른 검사 또는 사법경찰관의 수신자료 폐기사실의 통지는 별지 제33호서식에 따른다.', 2223);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3821, '① 법 제16조의3제2항에 따라 피부착자에 관한 영상정보를 제공받은 위치추적 관제센터의 장은 같은 조 제3항에 따라 해당 영상정보의 열람이 종료된 날부터 30일 이내에 열람 사실을 해당 피부착자에게 통지해야 한다.', 2226);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3822, '② 제1항에 따른 통지는 휴대전화 문자전송, 전자우편, 팩스, 전화 또는 우편 등의 방법으로 한다.', 2226);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3823, '① 법 제21조의2에 따른 보호관찰명령의 청구는 별지 제38호서식에 따른다. 다만, 공소제기와 동시에 보호관찰명령을 청구하는 경우에는 별지 제39호서식의 공소장 및 보호관찰명령 청구서로 할 수 있다.', 2230);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3824, '② 검사가 공소를 제기한 후에 보호관찰명령을 청구하는 경우에는 보호관찰명령 청구사건과 병합심리할 피고사건의 법원명, 사건번호, 피고인명 및 죄명 등을 명시하여 보호관찰명령 청구사건의 관할 법원에 병합심리를 신청하여야 한다.', 2230);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3825, '① 법 제21조의3에 따라 선고된 보호관찰명령의 집행지휘는 별지 제40호서식의 보호관찰명령 집행지휘서에 따른다.', 2231);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3826, '② 검사는 보호관찰명령과 병과된 형의 집행지휘서의 비고란에 "보호관찰명령"이라고 붉은 색으로 적어야 한다.', 2231);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3827, '① 법 제22조제4항 및 제23조제2항에 따른 전자장치 부착대상자 통보는 별지 제43호서식의 전자장치 부착대상자 통보서에 따른다. <개정 2013.5.31, 2020.8.5>', 2234);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3828, '② 영 제19조의2제2항의 결정서는 별지 제44호서식에 따른다. <개정 2013.5.31, 2020.8.5>', 2234);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3829, '① 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제6호에 따른 구인영장의 청구와 신청은 각각 별지 제47호서식과 별지 제48호서식에 따른다. <개정 2013.5.31>', 2246);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3830, '② 보호관찰소의 장은 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제6호에 따라 검사에게 구인영장을 신청할 때에는 별지 제49호서식의 구인영장 신청부에 정해진 사항을 적어야 한다. <개정 2013.5.31, 2022.2.7>', 2246);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3831, '① 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제6호에 따른 구인영장은 별지 제50호서식에 따른다. <개정 2013.5.31>', 2247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3832, '② 검사는 구인영장 위쪽에 집행을 지휘한다는 내용을 기재하고 서명 또는 기명날인의 방법으로 구인영장의 집행을 지휘할 수 있다.', 2247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3833, '① 법 제13조제2항 및 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제10호에 따른 부착명령 집행장의 신청은 별지 제51호서식에 따른다. <개정 2013.5.31, 2018.2.2>', 2248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3834, '② 법 제13조제2항 및 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제10호에 따른 부착명령 집행장은 별지 제52호서식에 따른다. <개정 2013.5.31, 2018.2.2>', 2248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3835, '① 사법경찰관리는 수사를 할 때에는 합리적 이유 없이 피의자와 그 밖의 피해자ㆍ참고인 등(이하 "사건관계인"이라 한다)의 성별, 종교, 나이, 장애, 사회적 신분, 출신지역, 인종, 국적, 외모 등 신체조건, 병력(病歷), 혼인 여부, 정치적 의견 및 성적(性的) 지향 등을 이유로 차별해서는 안 된다.', 2250);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3836, '② 사법경찰관리는 「형사소송법」(이하 "법"이라 한다) 및 「검사와 사법경찰관의 상호협력과 일반적 수사준칙에 관한 규정」(이하 "수사준칙"이라 한다) 등 관계 법령을 준수하고 적법한 절차와 방식에 따라 수사해야 한다.', 2250);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3837, '① 사법경찰관리는 수사준칙 제6조에 따라 검사가 수사, 공소제기 및 공소유지와 관련하여 협력의 요청ㆍ요구ㆍ신청 등(이하 "협력요청등"이라 한다)을 하는 경우에는 상호 존중을 바탕으로 적극 협조해야 한다.', 2251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3838, '② 사법경찰관리는 검사에게 협력요청등을 하는 경우에는 「형사사법절차 전자화 촉진법」 제2조제4호에 따른 형사사법정보시스템(이하 "형사사법정보시스템"이라 한다) 또는 서면으로 해야 한다.', 2251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3839, '③ 천재지변 또는 긴급한 상황이 발생하거나 수사 현장에서 협력요청등을 하는 경우 등 제2항의 방식으로 협력요청등을 하는 것이 불가능하거나 현저히 곤란한 경우에는 구두(口頭)나 전화 등 간편한 방식으로 협력요청등을 할 수 있다.', 2251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3840, '④ 사법경찰관리는 신속한 수사가 필요한 경우에는 적정한 기간을 정하여 검사에게 협력요청등을 할 수 있다.', 2251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3841, '⑤ 사법경찰관리는 검사로부터 기간이 정해진 협력요청등을 받은 경우에는 그 기간 내에 이행하도록 노력해야 한다. 다만, 그 기간 내에 이행하기 곤란하거나 이행하지 못하는 경우에는 추가로 필요한 기간을 검사와 협의할 수 있다.', 2251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3842, '① 사법경찰관리는 수사준칙 제7조에 따라 검사에게 중요사건에 대한 의견의 제시ㆍ교환을 요청하는 경우에는 별지 제1호서식의 의견요청서에 따른다.', 2252);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3843, '② 사법경찰관리는 수사준칙 제7조에 따라 검사로부터 중요사건에 대한 의견 제시ㆍ교환 요청을 받아 의견을 제시ㆍ교환하는 경우에는 별지 제2호서식의 의견서에 따른다.', 2252);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3844, '① 사법경찰관리는 수사준칙 제55조제1항에 따라 소재불명(所在不明)인 피의자나 참고인을 발견하여 통보하는 경우에는 별지 제3호서식 또는 별지 제4호서식의 소재불명자 발견 통보서에 따른다.', 2253);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3845, '② 사법경찰관리는 수사준칙 제55조제2항에 따른 검사의 소재수사 요청에 협력하여 소재 확인을 한 경우에는 별지 제5호서식의 소재수사 결과 통보서를 작성하여 검사에게 통보해야 한다.', 2253);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3846, '① 사법경찰관리는 사법경찰관리가 수사 중인 사건에 대하여 검사로부터 「검찰사건사무규칙」에 따른 시찰조회를 요청받은 경우에는 협력해야 한다.', 2254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3847, '② 사법경찰관리는 사법경찰관리가 수사 중인 사건이 아닌 사건에 대하여 검사로부터 시찰조회를 요청받은 경우에는 사건의 내용, 시찰조회 요청 사유 및 직무 수행 지장 여부 등을 종합적으로 검토하여 협력 여부를 결정할 수 있다.', 2254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3848, '① 사법경찰관리는 수사준칙 제8조제1항에 따라 검사와의 협의를 요청하려는 경우에는 별지 제6호서식의 협의요청서에 요청 사항과 그 사유를 적어 검사에게 통보해야 한다.', 2255);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3849, '② 사법경찰관리는 수사준칙 제8조제2항 각 호의 어느 하나에 해당하는 경우 제1항에 따른 해당 검사와의 협의에도 불구하고 이견이 해소되지 않으면 이를 즉시 소속된 경찰관서의 장(이하 "소속경찰관서장"이라 한다)에게 보고해야 한다. <개정 2024.5.24>', 2255);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3850, '③ 제2항의 보고를 받은 소속경찰관서장은 수사준칙 제8조제2항에 따른 협의가 필요하다고 판단하면 별지 제7호서식의 협의요청서에 요청 사항과 그 사유를 적어 제2항에 따른 해당 검사가 소속된 검찰청의 장에게 통보해야 한다.', 2255);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3851, '④ 사법경찰관리 또는 소속경찰관서장은 제1항 또는 제3항에 따라 검사 또는 검찰청의 장과 협의한 사항이 있으면 그 협의사항을 성실하게 이행하도록 노력해야 한다.', 2255);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3852, '① 사법경찰관리는 수사에 필요한 경우에는 다른 사법경찰관리에게 피의자의 체포ㆍ출석요구ㆍ조사ㆍ호송, 압수ㆍ수색ㆍ검증, 참고인의 출석요구ㆍ조사 등 그 밖에 필요한 조치에 대한 협력을 요청할 수 있다. 이 경우 요청을 받은 사법경찰관리는 정당한 이유가 없으면 이에 적극 협조해야 한다.', 2256);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3853, '② 사법경찰관리는 수사에 필요한 경우에는 법 제245조의10에 따른 특별사법경찰관리와 긴밀히 협력해야 한다. 이 경우 협력의 구체적인 내용ㆍ범위 및 방법 등은 상호 협의하여 정한다.', 2256);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3854, '① 사건기록담당직원은 법 및 관련 법령에 따라 검사로부터 요구ㆍ요청 등을 받거나 사건 기록과 증거물을 반환받은 때에는 관계 서류 등이 법령에 따라 작성ㆍ편철됐는지 및 검사가 법령에 따라 필요한 행위를 했는지를 점검해야 한다.', 2257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3855, '② 사건기록담당직원은 제1항에 따른 점검 결과 관계 서류 등이 법 및 관련 법령에 따라 작성ㆍ편철되지 않거나, 검사가 법 및 관련 법령에 따라 필요한 행위를 하지 않은 경우에는 검사에게 그 보완을 요구하는 등 필요한 조치를 할 수 있다.', 2257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3856, '③ 사건기록담당직원은 제1항에 따라 요구ㆍ요청 등을 받거나 사건 기록과 증거물을 반환받아 이를 접수한 경우에는 접수대장에 접수일시, 검사 또는 검찰청 직원의 성명 등을 기재하고, 검사 또는 검찰청 직원이 제시하는 접수기록부 등에 접수일시와 접수자의 직급 및 서명을 기재한다.', 2257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3857, '① 사법경찰관은 다음 각 호의 어느 하나에 해당하는 날부터 7일 이내에 고소인ㆍ고발인ㆍ피해자 또는 그 법정대리인(피해자가 사망한 경우에는 그 배우자ㆍ직계친족ㆍ형제자매를 포함한다. 이하 "고소인등"이라 한다)에게 수사 진행상황을 통지해야 한다. 다만, 고소인등의 연락처를 모르거나 소재가 확인되지 않으면 연락처나 소재를 알게 된 날부터 7일 이내에 수사 진행상황을 통지해야 한다. <개정 2024.5.24>', 2259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3858, '② 제1항제2호에 따른 수사 진행상황 통지 후에 고소인등의 요청이 있거나 그 밖에 사법경찰관이 필요하다고 인정하는 경우에도 수사 진행상황을 통지할 수 있다. <신설 2024.5.24>', 2259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3859, '③ 제1항 및 제2항에 따른 통지는 서면, 전화, 팩스, 전자우편, 문자메시지 등 고소인등이 요청한 방법으로 할 수 있으며, 고소인등이 별도로 요청한 방법이 없는 경우에는 서면 또는 문자메시지로 통지한다. 이 경우 서면으로 하는 통지는 별지 제9호서식의 수사 진행상황 통지서에 따른다. <개정 2024.5.24>', 2259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3860, '④ 사법경찰관은 수사 진행상황을 서면으로 통지한 경우에는 그 사본을, 그 밖의 방법으로 통지한 경우에는 그 취지를 적은 서면을 사건기록에 편철해야 한다. <개정 2024.5.24>', 2259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3861, '⑤ 사법경찰관은 제1항 및 제2항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 수사 진행상황을 통지하지 않을 수 있다. 이 경우 그 사실을 수사보고서로 작성하여 사건기록에 편철해야 한다. <개정 2024.5.24>', 2259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3862, '① 사법경찰관리는 법 제243조의2제1항에 따라 피의자 또는 그 변호인ㆍ법정대리인ㆍ배우자ㆍ직계친족ㆍ형제자매의 신청이 있는 경우 변호인의 참여로 인하여 신문이 방해되거나, 수사기밀이 누설되는 등 정당한 사유가 있는 경우를 제외하고는 피의자에 대한 신문에 변호인을 참여하게 해야 한다.', 2260);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3863, '② 제1항의 변호인의 피의자신문 참여 신청을 받은 사법경찰관리는 신청인으로부터 변호인의 피의자신문 참여 전에 다음 각 호의 서면을 제출받아야 한다.', 2260);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3864, '① 사법경찰관리는 변호인의 참여로 증거를 인멸ㆍ은닉ㆍ조작할 위험이 구체적으로 드러나거나, 신문 방해, 수사기밀 누설 등 수사에 현저한 지장을 초래하는 경우에는 피의자신문 중이라도 변호인의 참여를 제한할 수 있다. 이 경우 피의자와 변호인에게 변호인의 참여를 제한하는 처분에 대해 법 제417조에 따른 준항고를 제기할 수 있다는 사실을 고지해야 한다.', 2261);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3865, '② 제1항에 따라 변호인 참여를 제한하는 경우 사법경찰관리는 피의자 또는 변호인에게 그 사유를 설명하고 의견을 진술할 기회와 다른 변호인을 참여시킬 기회를 주어야 한다.', 2261);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3866, '③ 제1항에 따라 변호인의 참여를 제한한 후 그 사유가 해소된 때에는 변호인을 신문에 참여하게 해야 한다.', 2261);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3867, null, 2263);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3868, '① 경찰청장은 수사의 책임성과 완결성 확보를 위하여 경찰관서에 경찰청장이 정하는 자격을 갖춘 심사관을 둘 수 있다.', 2265);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3869, '② 제1항에 따른 심사관은 강제수사의 적법성ㆍ타당성 심사, 불송치 사건 및 수사 전반에 대한 점검 등의 업무를 수행한다.', 2265);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3870, '① 사법경찰관은 법 제197조제1항에 따라 구체적인 사실에 근거를 둔 범죄의 혐의를 인식한 때에는 수사를 개시한다.', 2266);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3871, '② 사법경찰관은 제1항에 따라 수사를 개시할 때에는 지체 없이 별지 제11호서식의 범죄인지서를 작성하여 사건기록에 편철해야 한다.', 2266);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3872, '① 사법경찰관은 수사준칙 제16조제3항에 따른 입건 전에 범죄를 의심할 만한 정황이 있어 수사 개시 여부를 결정하기 위한 사실관계의 확인 등 필요한 조사(이하 "입건전조사"라 한다)에 착수하기 위해서는 그 사건을 수리하고, 해당 사법경찰관이 소속된 경찰관서의 수사 부서의 장(이하 "소속수사부서장"이라 한다)의 지휘를 받아야 한다. <개정 2022.1.4, 2024.5.24>', 2267);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3873, '② 사법경찰관은 입건전조사한 사건을 다음 각 호의 구분에 따라 처리해야 한다. <개정 2022.1.4, 2024.5.24>', 2267);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3874, '③ 제1항 및 제2항에서 규정한 사항 외에 입건전조사 사건의 분류, 수리 및 조사의 진행과 기록관리 등에 필요한 세부사항은 경찰청장이 정한다. <신설 2024.5.24>', 2267);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3875, '① 사법경찰관은 수사준칙 제16조제4항에 따라 피혐의자(제19조제2항제2호에 따라 입건전조사 종결한 경우만 해당한다)와 진정인ㆍ탄원인ㆍ피해자 또는 그 법정대리인(피해자가 사망한 경우에는 그 배우자ㆍ직계친족ㆍ형제자매를 포함한다. 이하 "진정인등"이라 한다)에게 입건하지 않는 결정을 통지하는 경우에는 그 결정을 한 날부터 7일 이내에 통지해야 한다. 다만, 피혐의자나 진정인등의 연락처를 모르거나 소재가 확인되지 않으면 연락처나 소재를 알게 된 날부터 7일 이내에 통지해야 한다. <개정 2022.1.4>', 2268);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3876, '② 제1항에 따른 통지는 서면, 전화, 팩스, 전자우편, 문자메시지 등 피혐의자 또는 진정인등이 요청한 방법으로 할 수 있으며, 별도로 요청한 방법이 없는 경우에는 서면 또는 문자메시지로 한다. 이 경우 서면으로 하는 통지는 별지 제12호서식 또는 별지 제13호서식의 불입건 결정 통지서에 따른다.', 2268);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3877, '③ 사법경찰관은 서면으로 통지한 경우에는 그 사본을, 그 밖의 방법으로 통지한 경우에는 그 취지를 적은 서면을 사건기록에 편철해야 한다.', 2268);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3878, '④ 사법경찰관은 제1항에도 불구하고 통지로 인해 보복범죄 또는 2차 피해 등이 우려되는 다음 각 호의 경우에는 불입건 결정을 통지하지 않을 수 있다. 이 경우 그 사실을 입건전조사 보고서로 작성하여 사건기록에 편철해야 한다. <개정 2022.1.4>', 2268);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3879, '① 사법경찰관리는 진정인ㆍ탄원인 등 민원인이 제출하는 서류가 고소ㆍ고발의 요건을 갖추었다고 판단하는 경우 이를 고소ㆍ고발로 수리한다.', 2269);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3880, '② 사법경찰관리는 고소장 또는 고발장의 명칭으로 제출된 서류가 다음 각 호의 어느 하나에 해당하는 경우에는 이를 진정(陳情)으로 처리할 수 있다. <개정 2024.5.24>', 2269);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3881, '① 사법경찰관리는 구술로 제출된 고소ㆍ고발을 수리한 경우에는 진술조서를 작성해야 한다.', 2270);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3882, '② 사법경찰관리는 서면으로 제출된 고소ㆍ고발을 수리했으나 추가 진술이 필요하다고 판단하는 경우 고소인ㆍ고발인으로부터 보충 서면을 제출받거나 추가로 진술을 들어야 한다.', 2270);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3883, '③ 자수하는 경우 진술조서의 작성 및 추가 진술에 관하여는 제1항 및 제2항을 준용한다.', 2270);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3884, '① 사법경찰관리는 법 제236조에 따라 대리인으로부터 고소를 수리하는 경우에는 고소인 본인의 위임장을 제출받아야 한다.', 2271);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3885, '② 사법경찰관리는 법 제225조부터 제228조까지의 규정에 따른 고소권자로부터 고소를 수리하는 경우에는 그 자격을 증명하는 서면을 제출받아야 한다.', 2271);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3886, '③ 사법경찰관리는 제2항에 따른 고소권자의 대리인으로부터 고소를 수리하는 경우에는 제1항 및 제2항에 따른 위임장 및 자격을 증명하는 서면을 함께 제출받아야 한다.', 2271);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3887, '④ 고소의 취소에 관하여는 제1항부터 제3항까지의 규정을 준용한다.', 2271);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3888, '① 사법경찰관리는 고소ㆍ고발을 수리한 날부터 3개월 이내에 수사를 마쳐야 한다.', 2272);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3889, '② 사법경찰관리는 제1항의 기간 내에 수사를 완료하지 못한 경우에는 그 이유를 소속수사부서장에게 보고하고 수사기간 연장을 승인받아야 한다.', 2272);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3890, '① 사법경찰관리는 고소ㆍ고발의 취소가 있을 때에는 그 취지를 명확하게 확인해야 한다.', 2273);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3891, '② 피해자의 명시한 의사에 반하여 공소를 제기할 수 없는 범죄에 대해 처벌을 희망하는 의사표시의 철회가 있을 때에도 제1항과 같다.', 2273);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3892, '① 사법경찰관은 수사준칙 제17조제1항에 따라 변사사건 발생사실을 검사에게 통보하는 경우에는 별지 제14호서식의 변사사건 발생 통보서 또는 별지 제15호서식의 교통사고 변사사건 발생 통보서에 따른다.', 2274);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3893, '② 사법경찰관은 긴급한 상황 등 제1항의 방식으로 통보하는 것이 불가능하거나 현저히 곤란한 경우에는 구두ㆍ전화ㆍ팩스ㆍ전자우편 등 간편한 방식으로 통보할 수 있다. 이 경우 사후에 지체 없이 서면으로 변사사건 발생사실을 통보해야 한다.', 2274);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3894, '① 사법경찰관은 법 제222조제1항 및 제3항에 따라 검시를 하는 경우에는 의사를 참여시켜야 하며, 그 의사로 하여금 검안서를 작성하게 해야 한다. 이 경우 사법경찰관은 검시 조사관을 참여시킬 수 있다.', 2275);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3895, '② 사법경찰관은 법 제222조에 따른 검시 또는 검증 결과 사망의 원인이 범죄로 인한 것으로 판단하는 경우에는 신속하게 수사를 개시해야 한다.', 2275);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3896, '① 수사준칙 제17조제3항에 따른 검시조서는 별지 제16호서식에 따르고, 검증조서는 별지 제17호서식에 따른다.', 2276);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3897, '② 사법경찰관은 수사준칙 제17조제3항에 따라 검사에게 제1항의 검시조서 또는 검증조서를 송부하는 경우에는 의사의 검안서, 감정서 및 촬영한 사진 등 관련 자료를 첨부해야 한다.', 2276);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3898, '③ 사법경찰관은 수사준칙 제17조제4항에 따라 검시를 한 사건에 대해 검사와 의견을 제시ㆍ교환하는 경우에는 별지 제18호서식의 변사사건 처리 등에 관한 의견서에 따른다.', 2276);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3899, null, 2277);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3900, '① 사법경찰관은 변사자에 대한 검시 또는 검증이 종료된 때에는 사체를 소지품 등과 함께 신속히 유족 등에게 인도한다. 다만, 사체를 인수할 사람이 없거나 변사자의 신원이 판명되지 않은 경우에는 사체가 현존하는 지역의 특별자치시장ㆍ특별자치도지사ㆍ시장ㆍ군수 또는 자치구의 구청장에게 인도해야 한다.', 2279);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3901, '② 제1항 본문에서 검시 또는 검증이 종료된 때는 다음 각 호의 구분에 따른 때를 말한다.', 2279);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3902, '③ 사법경찰관은 제1항에 따라 사체를 인도한 경우에는 인수자로부터 별지 제19호서식의 사체 및 소지품 인수서를 받아야 한다.', 2279);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3903, '① 사법경찰관은 수사준칙 제21조제2항제4호에 따라 심야조사를 하려는 경우에는 심야조사의 내용 및 심야조사가 필요한 사유를 소속 경찰관서에서 인권보호 업무를 담당하는 부서의 장에게 보고하고 허가를 받아야 한다.', 2284);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3904, '② 사법경찰관은 제1항에 따라 허가를 받은 경우 수사보고서를 작성하여 사건기록에 편철해야 한다.', 2284);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3905, '① 수사준칙 제24조제2항에 따른 동석신청서는 별지 제25호서식 또는 별지 제26호서식에 따른다.', 2286);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3906, '② 사법경찰관은 피의자, 피해자 또는 그 법정대리인이 제1항의 동석신청서를 작성할 시간적 여유가 없는 경우 등에는 이를 제출받지 않고 조서 또는 수사보고서에 그 취지를 기재하는 것으로 동석신청서 작성을 갈음할 수 있으며, 조사의 긴급성 또는 동석의 필요성 등이 현저한 경우에는 예외적으로 동석 조사 이후에 신뢰관계인과 피의자와의 관계를 소명할 자료를 제출받아 기록에 편철할 수 있다.', 2286);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3907, '③ 사법경찰관은 동석 신청이 없더라도 동석이 필요하다고 인정되면 피의자 또는 피해자와의 신뢰관계 유무를 확인한 후 직권으로 신뢰관계에 있는 사람을 동석하게 할 수 있다. 이 경우 그 관계 및 취지를 조서나 수사보고서에 적어야 한다.', 2286);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3908, '④ 사법경찰관은 신뢰관계인의 동석으로 인하여 신문이 방해되거나, 수사기밀이 누설되는 등 정당한 사유가 있는 경우에는 동석을 거부할 수 있으며, 신뢰관계인이 피의자신문 또는 피해자 조사를 방해하거나 그 진술의 내용에 부당한 영향을 미칠 수 있는 행위를 하는 등 수사에 현저한 지장을 초래하는 경우에는 피의자신문 또는 피해자 조사 중에도 동석을 제한할 수 있다.', 2286);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3909, '⑤ 피해자 이외의 사건관계인 조사에 관하여는 제1항부터 제4항까지의 규정을 준용한다.', 2286);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3910, '① 사법경찰관리가 법 제244조제1항에 따라 피의자의 진술을 조서에 적는 경우에는 별지 제27호서식 또는 별지 제28호서식의 피의자신문조서에 따른다.', 2287);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3911, '② 사법경찰관리가 피의자가 아닌 사람의 진술을 조서에 적는 경우에는 별지 제29호서식 또는 별지 제30호서식의 진술조서에 따른다.', 2287);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3912, '③ 사법경찰관리는 피의자 또는 피의자가 아닌 사람의 진술을 듣는 경우 진술 사항이 복잡하거나 진술인이 서면진술을 원하면 진술서를 작성하여 제출하게 할 수 있다.', 2287);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3913, '④ 피의자신문조서와 진술조서에는 진술자로 하여금 간인(間印)한 후 기명날인 또는 서명하게 한다.', 2287);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3914, '① 사법경찰관리는 범죄의 현장 또는 그 밖의 장소에서 피의사실을 확인하거나 증거물의 증명력을 확보하기 위해 필요한 경우 실황조사를 할 수 있다.', 2289);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3915, '② 사법경찰관리는 실황조사를 하는 경우에는 거주자, 관리자 그 밖의 관계자 등을 참여하게 할 수 있다.', 2289);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3916, '③ 사법경찰관리는 실황조사를 한 경우에는 별지 제33호서식의 실황조사서에 조사 내용을 상세하게 적고, 현장도면이나 사진이 있으면 이를 실황조사서에 첨부해야 한다.', 2289);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3917, '① 사법경찰관리는 법 제221조제1항 또는 제244조의2제1항에 따라 피의자 또는 피의자가 아닌 사람을 영상녹화하는 경우 그 조사의 시작부터 조서에 기명날인 또는 서명을 마치는 시점까지의 모든 과정을 영상녹화해야 한다. 다만, 조사 도중 영상녹화의 필요성이 발생한 때에는 그 시점에서 진행 중인 조사를 중단하고, 중단한 조사를 다시 시작하는 때부터 조서에 기명날인 또는 서명을 마치는 시점까지의 모든 과정을 영상녹화해야 한다.', 2291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3918, '② 사법경찰관리는 제1항에도 불구하고 조사를 마친 후 조서 정리에 오랜 시간이 필요한 경우에는 조서 정리과정을 영상녹화하지 않고, 조서 열람 시부터 영상녹화를 다시 시작할 수 있다.', 2291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3919, '③ 제1항 및 제2항에 따른 영상녹화는 조사실 전체를 확인할 수 있고 조사받는 사람의 얼굴과 음성을 식별할 수 있도록 해야 한다.', 2291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3920, '④ 사법경찰관리는 피의자에 대한 조사 과정을 영상녹화하는 경우 다음 각 호의 사항을 고지해야 한다.', 2291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3921, '⑤ 사법경찰관리는 피의자가 아닌 사람의 조사 과정을 영상녹화하는 경우에는 별지 제35호서식의 영상녹화 동의서로 영상녹화 동의 여부를 확인하고, 제4항제1호, 제2호 및 제4호의 사항을 고지해야 한다. 다만, 피혐의자에 대해서는 제4항제1호부터 제4호까지의 규정에 따른 사항을 고지해야 한다.', 2291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3922, '① 사법경찰관리는 조사 시 영상녹화를 한 경우에는 영상녹화용 컴퓨터에 저장된 영상녹화 파일을 이용하여 영상녹화물(CD, DVD 등을 말한다. 이하 같다) 2개를 제작하여 그 중 하나를 피조사자의 기명날인 또는 서명을 받아 피조사자 또는 변호인 앞에서 봉인한 후, 봉인하지 않은 나머지 하나와 함께 수사기록에 편철한다. <개정 2024.5.24>', 2292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3923, '② 사법경찰관리는 제1항에 따라 영상녹화물을 제작한 후 영상녹화용 컴퓨터에 저장되어 있는 영상녹화 파일을 데이터베이스 서버에 전송하여 보관할 수 있다.', 2292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3924, '③ 사법경찰관리는 손상 또는 분실 등으로 제1항의 영상녹화물을 사용할 수 없는 경우에는 데이터베이스 서버에 보관되어 있는 영상녹화 파일을 이용하여 다시 영상녹화물을 제작할 수 있다.', 2292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3925, '① 사법경찰관리는 다음 각 호의 어느 하나에 해당하는 사람의 소재를 알 수 없을 때에는 지명수배를 할 수 있다.', 2293);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3926, '② 제1항에도 불구하고 법 제200조의3제1항에 따른 긴급체포를 하지 않으면 수사에 현저한 지장을 초래하는 경우에는 영장을 발부받지 않고 지명수배할 수 있다. 이 경우 지명수배 후 신속히 체포영장을 발부받아야 하며, 체포영장을 발부받지 못한 때에는 즉시 지명수배를 해제해야 한다.', 2293);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3927, '① 사법경찰관리는 제45조제1항에 따라 지명수배된 사람(이하 "지명수배자"라 한다)을 발견한 때에는 체포영장 또는 구속영장을 제시하고, 수사준칙 제32조제1항에 따라 권리 등을 고지한 후 체포 또는 구속하며 별지 제36호서식의 권리 고지 확인서를 받아야 한다. 다만, 체포영장 또는 구속영장을 소지하지 않은 경우 긴급하게 필요하면 지명수배자에게 영장이 발부되었음을 고지한 후 체포 또는 구속할 수 있으며 사후에 지체 없이 그 영장을 제시해야 한다.', 2294);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3928, '② 사법경찰관은 제45조제2항에 따라 영장을 발부받지 않고 지명수배한 경우에는 지명수배자에게 긴급체포한다는 사실과 수사준칙 제32조제1항에 따른 권리 등을 고지한 후 긴급체포해야 한다. 이 경우 지명수배자로부터 별지 제36호서식의 권리 고지 확인서를 받고 제51조제1항에 따른 긴급체포서를 작성해야 한다.', 2294);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3929, null, 2295);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3930, null, 2297);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3931, '① 법 제200조의3제3항에 따른 긴급체포서는 별지 제38호서식에 따른다.', 2299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3932, '② 수사준칙 제27조제2항 본문에 따른 긴급체포 승인요청서는 별지 제39호서식에 따른다.', 2299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3933, '③ 사법경찰관은 수사준칙 제27조제4항 후단에 따라 긴급체포된 피의자의 석방 일시와 사유 등을 검사에게 통보하는 경우에는 별지 제40호서식의 석방 통보서에 따른다.', 2299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3934, '① 사법경찰관리는 법 제212조에 따라 현행범인을 체포할 때에는 현행범인에게 도망 또는 증거인멸의 우려가 있는 등 당장에 체포하지 않으면 안 될 정도의 급박한 사정이 있는지 또는 체포 외에는 현행범인의 위법행위를 제지할 다른 방법이 없는지 등을 고려해야 한다.', 2300);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3935, '② 사법경찰관리는 법 제212조에 따라 현행범인을 체포한 때에는 별지 제41호서식의 현행범인체포서를 작성하고, 법 제213조에 따라 현행범인을 인도받은 때에는 별지 제42호서식의 현행범인인수서를 작성해야 한다.', 2300);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3936, '③ 사법경찰관리는 제2항의 현행범인체포서 또는 현행범인인수서를 작성하는 경우 현행범인에 대해서는 범죄와의 시간적 접착성과 범죄의 명백성이 인정되는 상황을, 준현행범인에 대해서는 범죄와의 관련성이 인정되는 상황을 구체적으로 적어야 한다.', 2300);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3937, '① 수사준칙 제28조제2항 전단에 따른 피의자 석방서는 별지 제43호서식에 따른다.', 2301);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3938, '② 사법경찰관은 수사준칙 제28조제2항 후단에 따라 검사에게 현행범인의 석방사실을 통보하는 경우에는 별지 제44호서식의 석방 통보서에 따른다.', 2301);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3939, '① 사법경찰관리는 체포영장 또는 구속영장을 집행할 때에는 신속하고 정확하게 해야 한다.', 2303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3940, '② 체포영장 또는 구속영장의 집행은 검사가 서명 또는 날인하여 교부한 영장이나 검사가 영장의 집행에 관한 사항을 적어 교부한 서면에 따른다.', 2303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3941, '③ 수사준칙 제32조제3항에 따른 권리 고지 확인서는 별지 제36호서식에 따른다. 다만, 피의자가 권리 고지 확인서에 기명날인 또는 서명하기를 거부하는 경우에는 피의자를 체포ㆍ구속하는 사법경찰관리가 확인서 끝부분에 그 사유를 적고 기명날인 또는 서명해야 한다.', 2303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3942, '④ 수사준칙 제32조의2제3항에 따른 영장 사본 교부 확인서는 별지 제36호의2서식에 따른다. 다만, 피의자가 영장 사본의 수령을 거부하거나 영장 사본 교부 확인서에 기명날인 또는 서명하는 것을 거부하는 경우에는 체포영장 또는 구속영장을 집행하는 사법경찰관리가 영장 사본 교부 확인서 끝 부분에 그 사유를 적고 기명날인 또는 서명해야 한다. <신설 2024.5.24>', 2303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3943, '① 사법경찰관리는 체포ㆍ구속한 피의자를 호송할 때에는 피의자의 도망ㆍ자살ㆍ신변안전ㆍ증거인멸 등에 주의해야 한다.', 2304);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3944, '② 사법경찰관리는 체포ㆍ구속한 피의자를 호송할 때 필요한 경우에는 가장 근접한 경찰관서에 피의자를 임시로 유치할 수 있다.', 2304);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3945, '① 사법경찰관은 법 제200조의6 및 제209조에서 준용하는 법 제91조 또는 「형의 집행 및 수용자의 처우에 관한 법률」 제87조에서 준용하는 같은 법 제41조에 따라 체포 또는 구속된 피의자와 법 제34조에서 규정한 사람이 아닌 사람과의 접견 등을 금지하려는 경우에는 별지 제51호서식의 피의자 접견 등 금지 결정서에 따른다.', 2307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3946, '② 사법경찰관은 제1항의 결정을 취소하는 것이 타당하다고 인정되어 피의자 접견 등의 금지를 취소하는 경우에는 별지 제52호서식의 피의자 접견 등 금지 취소 결정서에 따른다.', 2307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3947, '③ 제1항의 피의자 접견 등 금지 결정은 사법경찰관의 사건 송치와 동시에 그 효력을 상실한다.', 2307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3948, '① 수사준칙 제36조제1항에 따른 피의자 석방서는 별지 제53호서식 또는 별지 제54호서식에 따른다.', 2308);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3949, '② 사법경찰관은 검사에게 수사준칙 제36조제2항제1호에 따라 석방사실을 통보하는 경우에는 별지 제55호서식의 석방 통보서에 따르고, 같은 항 제2호에 따라 석방사실을 보고하는 경우에는 별지 제56호서식의 석방 보고서에 따른다.', 2308);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3950, '① 사법경찰관은 법 제209조에서 준용하는 법 제93조에 따라 구속을 취소하여 피의자를 석방하는 경우에는 별지 제57호서식의 구속취소 결정서에 따른다. 다만, 법 제245조의5제1호에 따라 검사에게 송치해야 하는 사건인 경우에는 사전에 별지 제58호서식의 구속취소 동의 요청서에 따라 검사의 동의를 받아야 한다.', 2309);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3951, '② 제1항에 따라 구속을 취소한 사법경찰관은 지체 없이 별지 제59호서식의 석방 통보서를 작성하여 검사에게 석방사실을 통보하고, 그 통보서 사본을 사건기록에 편철해야 한다.', 2309);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3952, '① 사법경찰관은 법 제209조에서 준용하는 법 제101조제1항에 따라 구속의 집행을 정지하는 경우에는 별지 제60호서식의 구속집행정지 결정서에 따른다.', 2310);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3953, '② 제1항에 따라 구속의 집행을 정지한 사법경찰관은 지체 없이 별지 제61호서식의 구속집행정지 통보서를 작성하여 검사에게 그 사실을 통보하고, 그 통보서 사본을 사건기록에 편철해야 한다.', 2310);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3954, '③ 사법경찰관은 법 제209조에서 준용하는 법 제102조제2항에 따라 구속집행정지 결정을 취소하는 경우에는 별지 제62호서식의 구속집행정지 취소 결정서에 따른다.', 2310);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3955, '① 사법경찰관은 수사준칙 제37조에 따라 압수ㆍ수색 또는 검증영장을 신청하는 경우에는 별지 제63호서식부터 별지 제65호서식까지의 압수ㆍ수색ㆍ검증영장 신청서에 따른다. 이 경우 압수ㆍ수색 또는 검증의 필요성 및 해당 사건과의 관련성을 인정할 수 있는 자료를 신청서에 첨부해야 한다.', 2311);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3956, '② 압수ㆍ수색 또는 검증영장의 집행 및 반환에 관하여는 제55조제1항ㆍ제2항 및 제58조를 준용한다.', 2311);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3957, '③ 수사준칙 제38조제4항에 따른 영장 사본 교부 확인서는 별지 제36호의2서식에 따른다. 다만, 피의자가 영장 사본의 수령을 거부하거나 영장 사본 교부 확인서에 기명날인 또는 서명하는 것을 거부하는 경우에는 압수ㆍ수색 또는 검증영장을 집행하는 사법경찰관리가 영장 사본 교부 확인서 끝 부분에 그 사유를 적고 기명날인 또는 서명해야 한다. <신설 2024.5.24>', 2311);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3958, '① 수사준칙 제40조 본문에 따른 압수조서는 별지 제66호서식에 따르고, 압수목록은 별지 제67호서식에 따른다.', 2312);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3959, '② 법 제219조에서 준용하는 법 제129조에 따라 압수목록을 교부하는 경우에는 별지 제68호서식의 압수목록 교부서에 따른다. 이 경우 수사준칙 제41조제1항에 따른 전자정보에 대한 압수목록 교부서는 전자파일의 형태로 복사해 주거나 전자우편으로 전송하는 등의 방식으로 교부할 수 있다.', 2312);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3960, '③ 수사준칙 제42조제2항 후단에 따른 삭제ㆍ폐기ㆍ반환 확인서는 별지 제69호서식에 따른다. 다만, 제2항에 따른 압수목록 교부서에 삭제ㆍ폐기 또는 반환했다는 내용을 포함시켜 교부하는 경우에는 삭제ㆍ폐기ㆍ반환 확인서를 교부하지 않을 수 있다.', 2312);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3961, '① 사법경찰관은 법 제215조에 따라 수색을 한 경우에는 수색의 상황과 결과를 명백히 한 별지 제70호서식의 수색조서를 작성해야 한다.', 2313);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3962, '② 법 제219조에서 준용하는 법 제128조에 따라 증거물 또는 몰수할 물건이 없다는 취지의 증명서를 교부하는 경우에는 별지 제71호서식의 수색증명서에 따른다.', 2313);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3963, '① 사법경찰관은 법 제218조의2제1항 및 제4항에 따라 압수물에 대해 그 소유자, 소지자, 보관자 또는 제출인(이하 이 조에서 "소유자등"이라 한다)으로부터 환부 또는 가환부의 청구를 받거나 법 제219조에서 준용하는 법 제134조에 따라 압수장물을 피해자에게 환부하려는 경우에는 별지 제72호서식의 압수물 처분 지휘요청서를 작성하여 검사에게 제출해야 한다.', 2314);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3964, '② 사법경찰관은 제1항에 따른 압수물의 환부 또는 가환부의 청구를 받은 경우 소유자등으로부터 별지 제73호서식의 압수물 환부ㆍ가환부 청구서를 제출받아 별지 제72호서식의 압수물 처분 지휘요청서에 첨부한다.', 2314);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3965, '③ 사법경찰관은 압수물을 환부 또는 가환부한 경우에는 피해자 및 소유자등으로부터 별지 제74호서식의 압수물 환부ㆍ가환부 영수증을 받아야 한다.', 2314);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3966, '① 사법경찰관은 압수물에 사건명, 피의자의 성명, 제64조제1항의 압수목록에 적힌 순위ㆍ번호를 기입한 표찰을 붙여야 한다.', 2315);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3967, '② 사법경찰관은 법 제219조에서 준용하는 법 제130조제1항에 따라 압수물을 다른 사람에게 보관하게 하려는 경우에는 별지 제75호서식의 압수물 처분 지휘요청서를 작성하여 검사에게 제출해야 한다.', 2315);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3968, '③ 사법경찰관은 제2항에 따라 압수물을 다른 사람에게 보관하게 하는 경우 적절한 보관인을 선정하여 성실하게 보관하게 하고 보관인으로부터 별지 제76호서식의 압수물 보관 서약서를 받아야 한다.', 2315);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3969, '① 사법경찰관은 법 제219조에서 준용하는 법 제130조제2항 및 제3항에 따라 압수물을 폐기하려는 경우에는 별지 제77호서식의 압수물 처분 지휘요청서를 작성하여 검사에게 제출해야 한다.', 2316);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3970, '② 사법경찰관은 제1항에 따라 압수물을 폐기하는 경우에는 별지 제78호서식의 압수물 폐기 조서를 작성하고 사진을 촬영하여 사건기록에 편철해야 한다.', 2316);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3971, '③ 사법경찰관은 법 제219조에서 준용하는 법 제130조제3항에 따라 압수물을 폐기하는 경우에는 소유자 등 권한 있는 사람으로부터 별지 제79호서식의 압수물 폐기 동의서를 제출받거나 진술조서 등에 그 취지를 적어야 한다.', 2316);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3972, '① 사법경찰관은 법 제219조에서 준용하는 법 제132조에 따라 압수물을 매각하여 대가를 보관하려는 경우에는 별지 제80호서식의 압수물 처분 지휘요청서를 작성하여 검사에게 제출해야 한다.', 2317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3973, '② 사법경찰관은 제1항에 따라 대가보관의 처분을 했을 때에는 별지 제81호서식의 압수물 대가보관 조서를 작성한다.', 2317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3974, '① 사법경찰관은 법 제221조제2항의 감정을 위하여 법 제172조제3항에 따른 유치가 필요한 경우에는 별지 제84호서식의 감정유치장 신청서를 작성하여 검사에게 제출해야 한다.', 2321);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3975, '② 사법경찰관은 법 제221조의4제1항에 따라 법 제173조제1항에 따른 처분을 위한 허가가 필요한 경우에는 별지 제85호서식의 감정처분허가장 신청서를 작성하여 검사에게 제출해야 한다.', 2321);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3976, '① 사법경찰관은 수사준칙 제45조제2항에 따라 사건기록 등본을 검사에게 송부하는 경우에는 별지 제86호서식의 사건기록 등본 송부서를 작성하여 사건기록 등본에 편철해야 한다.', 2323);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3977, '② 사법경찰관은 제1항에 따라 사건기록 등본을 송부하는 경우에는 해당 사건기록 전체의 등본을 송부한다. 다만, 등본송부 요구의 사유가 사건기록의 일부와 관련된 경우에는 사전에 검사와 합의하고 해당 부분에 대해서만 등본을 송부할 수 있다.', 2323);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3978, '③ 사법경찰관은 필요하다고 인정하는 경우 제1항에 따라 사건기록 등본을 송부하면서 의견을 함께 제출할 수 있다.', 2323);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3979, '④ 사법경찰관은 수사준칙 제45조제4항에 따라 검사에게 시정조치 이행 결과를 통보하는 경우 별지 제87호서식의 시정조치 결과 통보서에 따른다. 다만, 법률상ㆍ사실상 시정이 불가능한 경우 등 정당한 이유가 있어 시정조치요구를 이행하지 않은 경우에는 그 내용과 사유를 시정조치 결과 통보서에 구체적으로 적어 통보해야 한다.', 2323);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3980, '① 사법경찰관은 수사준칙 제48조제1항에 따라 검사에게 사건기록의 열람을 요청하는 경우에는 별지 제90호서식의 사건기록 열람요청서에 따른다.', 2326);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3981, '② 사법경찰관은 검사로부터 수사준칙 제48조제1항에 따른 사건기록의 열람을 요청하는 서면을 받은 경우에는 그 요청 서면을 검토하여 열람 허용 여부 및 범위를 신속하게 결정한다.', 2326);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3982, '③ 사법경찰관이 검사에게 열람을 허용할 수 있는 사건기록의 범위는 다음 각 호와 같다. 다만, 예외적으로 그 외 사건기록의 열람을 허용할 필요가 있는 경우에는 달리 정할 수 있다.', 2326);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3983, '④ 사법경찰관은 별지 제91호서식의 열람허가서에 열람을 허용하는 사건기록의 범위를 기재하여 제2항의 사건기록 중 열람을 허용한 사건기록 등본과 함께 사건기록담당직원에게 인계한다.', 2326);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3984, '⑤ 사건기록담당직원은 검사에게 기록을 열람하게 하고, 관리대장에 열람 일시, 열람 검사의 성명 등을 기재한다.', 2326);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3985, '① 사법경찰관리는 피해자[타인의 범죄행위로 피해를 당한 사람과 그 배우자(사실상의 혼인관계를 포함한다), 직계친족 및 형제자매를 말한다. 이하 이 장에서 같다]의 심정을 이해하고 그 인격을 존중하며 피해자가 범죄피해 상황에서 조속히 회복하여 인간의 존엄성을 보장받을 수 있도록 노력해야 한다.', 2327);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3986, '② 사법경찰관리는 피해자의 명예와 사생활의 평온을 보호하고 해당 사건과 관련하여 각종 법적 절차에 참여할 권리를 보장해야 한다.', 2327);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3987, '① 수사준칙 제15조제2항에 따른 신변보호에 필요한 조치의 유형은 다음 각 호와 같다.', 2328);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3988, '② 범죄신고자 등 참고인으로서 범죄수사와 관련하여 보복을 당할 우려가 있는 경우에 관하여는 제1항을 준용한다.', 2328);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3989, null, 2329);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3990, '① 사법경찰관리는 피해자가 입은 피해의 실질적인 회복 등을 위하여 필요하다고 인정하면 피해자 또는 가해자의 신청과 그 상대방의 동의에 따라 서로 대화할 수 있는 기회를 제공할 수 있다.', 2330);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3991, '② 제1항에 따라 대화 기회를 제공하는 경우 사법경찰관리는 피해자와 가해자 간 대화가 원활하게 진행될 수 있도록 전문가에게 회복적 대화 진행을 의뢰할 수 있다.', 2330);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3992, '① 사법경찰관은 수사에 필요한 장부와 서류철을 갖추어 두고 보존기간을 정하여 관리해야 한다.', 2333);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3993, '② 제1항의 장부와 서류철은 형사사법정보시스템을 통해 전자적으로 작성ㆍ저장ㆍ관리ㆍ보존할 수 있다. 이 경우 전자 장부와 서류철은 종이 장부와 서류철의 개별 항목을 포함해야 한다.', 2333);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3994, '① 수사준칙 제69조(같은 영 제16조제6항에서 준용하는 경우를 포함한다)에 따른 수사서류 열람ㆍ복사 신청은 해당 수사서류를 보유ㆍ관리하는 경찰관서의 장에게 해야 한다.', 2335);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3995, '② 제1항의 신청을 받은 경찰관서의 장은 신청을 받은 날부터 10일 이내에 다음 각 호의 어느 하나에 해당하는 결정을 해야 한다.', 2335);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3996, '③ 경찰관서의 장은 제2항에도 불구하고 피의자 및 사건관계인, 그 변호인이 조사 당일 본인의 진술이 기재된 조서에 대해 열람ㆍ복사를 신청하는 경우에는 공개 여부에 대해 지체 없이 검토한 후 제공 여부를 결정해야 한다.', 2335);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3997, '④ 경찰관서의 장은 해당 관서에서 보유ㆍ관리하지 않는 수사서류에 대해 열람ㆍ복사 신청을 접수한 경우에는 그 신청을 해당 수사서류를 보유ㆍ관리하는 기관으로 이송하거나 신청인에게 부존재 통지를 해야 한다.', 2335);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3998, '⑤ 경찰관서의 장은 제2항제1호 또는 제2호에 따라 수사서류를 제공하는 경우에는 사건관계인의 개인정보가 공개되지 않도록 비실명처리 등 보호조치를 해야 한다.', 2335);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (3999, '⑥ 제1항부터 제5항까지에서 규정한 사항 외에 수사서류 열람ㆍ복사에 필요한 세부 사항은 경찰청장이 따로 정한다.', 2335);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4000, '① 사법경찰관리는 「약식절차 등에서의 전자문서 이용 등에 관한 법률」(이하 "약식전자문서법"이라 한다) 제3조에따른 같은 법의 적용 대상 사건을 수사하는 경우에는 피의자를 신문하기 전에 전자문서 등을 이용하여 처리되는 약식절차(이하 이 조에서 "전자약식절차"라 한다)에 관하여 안내하고 동의 여부를 확인해야 한다. 이 경우 피의자가 동의하면 별지 제92호서식의 전자약식절차 동의서를 형사사법정보시스템을 통해 전자문서로 작성해야 한다.', 2336);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4001, '② 사법경찰관리는 제1항에도 불구하고 약식전자문서법 제3조제3항제2호에 해당하여 전자약식절차에 따르는 것이 적절하지 않은 경우에는 그 취지를 적은 수사보고서를 작성하여 사건기록에 편철해야 한다.', 2336);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4002, '① 사법경찰관리는 소년을 조사하는 경우에는 행위의 동기, 그 소년의 성품과 행실, 경력, 가정 상황, 교우관계, 그 밖의 환경 등을 상세히 조사하여 그 결과를 서면으로 적어야 한다.', 2337);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4003, '② 사법경찰관리는 소년에 대한 출석요구나 조사를 하는 경우에는 지체 없이 그 소년의 보호자 또는 보호자를 대신하여 소년을 보호할 수 있는 사람에게 연락해야 한다. 다만, 연락하는 것이 그 소년의 복리상 부적당하다고 인정되는 경우에는 그렇지 않다.', 2337);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4004, '③ 사법경찰관리는 소년인 피의자에 대해서는 가급적 구속을 피하고, 부득이하게 체포ㆍ구속 또는 임의동행하는 경우에는 그 시기와 방법에 특히 주의해야 한다.', 2337);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4005, '④ 사법경찰관리는 소년인 피의자가 체포ㆍ구속된 경우에는 다른 사건보다 우선하여 그 사건을 조사하는 등 신속한 수사를 위해 노력해야 한다.', 2337);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4006, '① 사법경찰관리는 외국인을 조사하는 경우에는 조사를 받는 외국인이 이해할 수 있는 언어로 통역해 주어야 한다.', 2339);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4007, '② 사법경찰관리는 외국인을 체포ㆍ구속하는 경우 국내 법령을 위반하지 않는 범위에서 영사관원과 자유롭게 접견ㆍ교통할 수 있고, 체포ㆍ구속된 사실을 영사기관에 통보해 줄 것을 요청할 수 있다는 사실을 알려야 한다.', 2339);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4008, '③ 사법경찰관리는 체포ㆍ구속된 외국인이 제2항에 따른 통보를 요청하는 경우에는 별지 제93호서식의 영사기관 체포ㆍ구속 통보서를 작성하여 지체 없이 해당 영사기관에 체포ㆍ구속 사실을 통보해야 한다.', 2339);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4009, '④ 사법경찰관리는 외국인 변사사건이 발생한 경우에는 제94호서식의 영사기관 사망 통보서를 작성하여 지체 없이 해당 영사기관에 통보해야 한다.', 2339);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4010, '① 사법경찰관은 주한 미합중국 군대의 구성원ㆍ외국인군무원 및 그 가족이나 초청계약자의 범죄 관련 사건을 인지하거나 고소ㆍ고발 등을 수리한 때에는 7일 이내에 별지 제95호서식의 한미행정협정사건 통보서를 검사에게 통보해야 한다.', 2340);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4011, '② 사법경찰관은 주한 미합중국 군당국으로부터 공무증명서를 제출받은 경우 지체 없이 공무증명서의 사본을 검사에게 송부해야 한다.', 2340);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4012, '③ 사법경찰관은 검사로부터 주한 미합중국 군당국의 재판권포기 요청 사실을 통보받은 날부터 14일 이내에 검사에게 사건을 송치 또는 송부해야 한다. 다만, 검사의 동의를 받아 그 기간을 연장할 수 있다.', 2340);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4013, '① 사법경찰관은 관계 법령에 따라 검사에게 추징보전을 신청하는 경우에는 별지 제97호서식의 추징보전 신청서에 따른다.', 2342);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4014, '② 사법경찰관은 검사에게 추징보전명령의 취소를 신청하는 경우에는 별지 제98호서식의 추징보전명령 취소 신청서에 따른다.', 2342);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4015, '① 사법경찰관리는 범죄 인지 후 1년이 지난 사건에 대해서는 수사준칙 제51조제1항에 따른 결정을 해야 한다. 다만, 다수의 사건관계인 조사, 관련 자료 추가확보ㆍ분석, 외부 전문기관 감정의 장기화, 범인 미검거 등으로 계속하여 수사가 필요한 경우에는 해당 사법경찰관리가 소속된 바로 위 상급경찰관서 수사 부서의 장의 승인을 받아 연장할 수 있다.', 2343);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4016, '② 사법경찰관리는 제1항 단서에 따른 승인을 받으려면 수사기간 연장의 필요성을 소명해야 한다.', 2343);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4017, '① 사법경찰관은 사건이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 사건을 다른 경찰관서 또는 기관에 이송해야 한다.', 2344);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4018, '② 사법경찰관은 사건이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 사건을 다른 경찰관서 또는 기관(해당 기관과 협의된 경우로 한정한다)에 이송할 수 있다.', 2344);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4019, '③ 사법경찰관은 제1항 또는 제2항에 따라 사건을 이송하는 경우에는 별지 제99호서식의 사건이송서를 사건기록에 편철하고 관계 서류와 증거물을 다른 경찰관서 또는 기관에 송부해야 한다.', 2344);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4020, '① 사법경찰관은 수사준칙 제53조에 따라 피의자와 고소인등에게 수사 결과를 통지하는 경우에는 사건을 송치하거나 사건기록을 송부한 날부터 7일 이내에 해야 한다. 다만, 피의자나 고소인등의 연락처를 모르거나 소재가 확인되지 않는 경우에는 연락처나 소재를 안 날부터 7일 이내에 통지를 해야 한다.', 2345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4021, '② 제1항의 통지(법 제245조의6에 따른 고소인등에 대한 불송치 통지는 제외한다)는 서면, 전화, 팩스, 전자우편, 문자메시지 등 피의자나 고소인등이 요청한 방법으로 할 수 있으며, 별도로 요청한 방법이 없는 경우에는 서면으로 한다. 이 경우 서면으로 하는 통지는 별지 제100호서식부터 별지 제102호서식까지의 수사결과 통지서에 따른다.', 2345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4022, '③ 법 제245조의6에 따른 고소인등에 대한 불송치 통지는 별지 제103호서식의 수사결과 통지서에 따른다.', 2345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4023, '④ 제2항 후단 및 제3항에도 불구하고 하나의 사건에 수사준칙 제51조제1항 각 호에 따른 법원송치, 검찰송치, 불송치, 수사중지 및 이송 결정이 병존하는 사건의 수사 결과를 통지하는 경우에는 별지 제103호의2서식 또는 별지 제103호의3서식의 수사결과 통지서에 따를 수 있다. <신설 2024.5.24>', 2345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4024, '⑤ 사법경찰관은 서면으로 통지한 경우에는 그 사본을, 그 외의 방법으로 통지한 경우에는 그 취지를 적은 서면을 사건기록에 편철해야 한다. <개정 2024.5.24>', 2345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4025, '⑥ 수사준칙 제53조제2항에 따른 고소인등의 통지 요구는 별지 제104호서식의 불송치 통지요구서에 따른다. <개정 2024.5.24>', 2345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4026, '⑦ 사법경찰관은 고소인, 고발인 또는 피의자가 불송치 결정에 관한 사실증명을 청구한 경우에는 지체 없이 별지 제105호서식 또는 별지 제106호서식의 불송치 결정 증명서를 발급해야 한다. <개정 2024.5.24>', 2345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4027, '⑧ 사법경찰관은 고소인등에게 수사중지 결정의 통지를 하는 경우에는 수사준칙 제54조제3항에 따라 검사에게 신고할 수 있다는 내용을 통지서에 기재해야 한다. <개정 2024.5.24>', 2345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4028, '① 사법경찰관은 다음 각 호의 구분에 해당하는 경우에는 그 사유가 해소될 때까지 수사준칙 제51조제1항제4호에 따른 수사중지 결정을 할 수 있다.', 2346);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4029, '② 사법경찰관은 제1항에 따라 수사중지의 결정을 하는 경우에는 별지 제107호서식의 수사중지 결정서를 작성하여 사건기록에 편철해야 한다.', 2346);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4030, '③ 사법경찰관은 수사준칙 제51조제4항에 따라 검사에게 사건기록을 송부하는 경우에는 별지 제108호서식의 수사중지 사건기록 송부서를 사건기록에 편철해야 한다.', 2346);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4031, '④ 사법경찰관리는 제1항제1호나목 또는 다목의 사유로 수사중지 결정을 한 경우에는 매월 1회 이상 해당 수사중지 사유가 해소되었는지를 확인해야 한다.', 2346);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4032, '① 사법경찰관은 소재불명의 사유로 수사중지를 하려는 경우에는 별지 제109호서식의 소재수사 보고서를 작성하여 사건기록에 편철해야 한다.', 2347);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4033, '② 사법경찰관리는 소재불명의 사유로 수사중지된 사건의 경우 매 분기 1회 이상 소재수사를 하는 등 수사중지 사유 해소를 위해 노력해야 한다.', 2347);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4034, '① 수사준칙 제54조제1항에 따라 이의제기를 하려는 사람은 수사중지 결정을 통지받은 날부터 30일 이내에 해당 사법경찰관이 소속된 바로 위 상급경찰관서의 장(이하 "소속상급경찰관서장"이라 한다)에게 별지 제110호서식의 수사중지 결정 이의제기서를 제출해야 한다.', 2349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4035, '② 제1항에 따른 이의제기서는 해당 사법경찰관이 소속된 경찰관서에 제출할 수 있다. 이 경우 이의제기서를 제출받은 경찰관서의 장은 이를 지체 없이 소속상급경찰관서장에게 송부해야 한다.', 2349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4036, '③ 소속상급경찰관서장은 제1항 또는 제2항에 따라 이의제기서를 제출받거나 송부받은 날부터 30일 이내에 다음 각 호의 구분에 따른 결정을 하고 해당 사법경찰관의 소속수사부서장에게 이를 통보해야 한다.', 2349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4037, '④ 제3항제1호에 따른 결정을 통보받은 소속수사부서장은 지체 없이 이를 이행하고 소속상급경찰관서장에게 이행 결과를 보고해야 한다.', 2349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4038, '⑤ 소속상급경찰관서장은 제3항의 결정을 한 날부터 7일 이내에 별지 제111호서식의 수사중지사건 이의처리결과 통지서에 처리 결과와 그 이유를 적어 이의를 제기한 사람에게 통지해야 한다.', 2349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4039, '⑥ 사법경찰관은 제1항부터 제4항까지의 규정에 따른 절차의 진행 중에 수사준칙 제51조제4항 후단에 따라 검사의 시정조치요구를 받은 경우에는 지체 없이 소속상급경찰관서장에게 보고해야 한다.', 2349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4040, '① 사법경찰관은 수사중지된 사건의 피의자를 발견하는 등 수사중지 사유가 해소된 때에는 별지 제112호서식의 수사중지사건 수사재개서를 작성하여 사건기록에 편철하고 즉시 수사를 진행해야 한다.', 2350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4041, '② 사법경찰관은 수사준칙 제51조제5항 전단에 따라 피의자 등의 소재 발견 및 수사 재개 사실을 검사에게 통보하는 경우에는 별지 제113호서식의 피의자 등 소재발견 통보서에 따른다.', 2350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4042, '① 수사준칙 제58조제1항에 따른 송치 결정서는 별지 제114호서식에 따르고, 압수물 총목록은 별지 제115호서식에 따르며, 기록목록은 별지 제116호서식에 따른다.', 2351);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4043, '② 송치 서류는 다음 순서에 따라 편철한다.', 2351);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4044, '③ 수사준칙 제58조에 따라 사건을 송치하는 경우에는 소속경찰관서장 또는 소속수사부서장의 명의로 한다.', 2351);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4045, '④ 제1항의 송치 결정서는 사법경찰관이 작성해야 한다.', 2351);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4046, '① 사법경찰관은 법 제197조의2제2항에 따라 보완수사 이행 결과를 통보하는 경우에는 별지 제119호서식의 보완수사 결과 통보서에 따른다. 다만, 수사준칙 제59조에 따른 보완수사요구의 대상이 아니거나 그 범위를 벗어난 경우 등 정당한 이유가 있어 보완수사를 이행하지 않은 경우에는 그 내용과 사유를 보완수사 결과 통보서에 적어 검사에게 통보해야 한다.', 2353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4047, '② 사법경찰관은 법 제197조의2제1항제1호에 따른 보완수사요구 결과를 통보하면서 새로운 증거물, 서류 및 그 밖의 자료를 검사에게 송부하는 경우에는 수사준칙 제58조제3항에 따른다.', 2353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4048, '③ 사법경찰관은 법 제197조의2제1항제2호에 따른 보완수사요구를 이행한 경우에는 다음 각 호의 구분에 따라 처리한다.', 2353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4049, '④ 사법경찰관은 수사준칙 제60조제5항에 따라 사건을 불송치하거나 수사중지하는 경우에는 기존 송치 결정을 취소해야 한다. <개정 2024.5.24>', 2353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4050, '① 소속경찰관서장은 수사준칙 제61조제2항에 따라 직무배제를 하는 경우 지체 없이 사건 담당 사법경찰관리를 교체해야 한다.', 2354);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4051, '② 소속경찰관서장은 수사준칙 제61조제3항에 따라 직무배제 또는 징계 요구의 처리 결과와 그 이유를 통보하는 경우에는 별지 제120호서식의 직무배제요구 처리결과 통보서 또는 별지 제88호서식의 징계요구 처리결과 통보서에 따른다.', 2354);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4052, '① 경찰서장은 「소년법」 제4조제2항에 따라 소년 보호사건을 법원에 송치하는 경우에는 별지 제121호서식의 소년 보호사건 송치서를 작성하여 사건기록에 편철하고 관계 서류와 증거물을 관할 가정법원 소년부 또는 지방법원 소년부에 송부해야 한다.', 2355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4053, '② 제1항의 송치 서류에 관하여는 제103조를 준용한다.', 2355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4054, '① 불송치 결정의 주문(主文)은 다음과 같이 한다. <개정 2024.5.24>', 2356);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4055, '② 사법경찰관은 압수물의 환부 또는 가환부를 받을 사람이 없는 등 특별한 사유가 있는 경우를 제외하고는 제1항에 따른 결정을 하기 전에 압수물 처분을 완료하도록 노력해야 한다. 수사준칙 제64조제1항제2호에 따라 재수사 결과를 처리하는 경우에도 또한 같다.', 2356);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4056, '① 수사준칙 제62조제1항에 따른 불송치 결정서는 별지 제122호서식에 따르고, 압수물 총목록은 별지 제115호서식에 따르며, 기록목록은 별지 제116호서식에 따른다.', 2357);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4057, '② 불송치 서류는 다음 순서에 따라 편철한다.', 2357);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4058, '③ 불송치 사건기록 송부서 명의인 및 불송치 결정서 작성인에 관하여는 제103조제3항 및 제4항을 준용한다.', 2357);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4059, '① 하나의 사건에 수사준칙 제51조제1항제2호부터 제4호까지의 규정에 따른 검찰송치, 불송치 및 수사중지 결정이 병존하는 병존사건의 경우 사법경찰관은 기록을 분리하여 송치 및 송부하도록 노력해야 한다.', 2358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4060, '② 제1항에도 불구하고 기록을 분리할 수 없는 경우에 사법경찰관은 관계 서류와 증거물을 원본과 다름이 없음을 인증하여 등사 보관하고 송치 결정서, 불송치 결정서 및 수사중지 결정서를 작성하여 그 결정서별로 압수물 총목록과 기록목록 등을 첨부한 후 각 별책으로 편철하여 관계 서류와 증거물 원본과 함께 검사에게 송치 및 송부한다.', 2358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4061, '③ 검사가 제2항에 따라 송치 및 송부된 사건을 공소제기(수사준칙 제52조제1항제7호에 따른 이송 중 타 기관 이송 및 같은 항 제8호부터 제11호까지의 규정에 따른 사건송치 결정을 포함한다)한 이후, 사법경찰관이 고소인등의 이의신청에 따라 사건을 송치하거나 수사중지 사건을 재개수사하여 송치 또는 송부할 때에는 추가된 새로운 증거물, 관계 서류와 함께 제2항의 관계 서류와 증거물 등본 중 관련 부분을 검사에게 송부해야 한다. 다만, 고소인등의 이의신청이나 수사중지 사건의 재개에 따라 불송치하거나 수사중지 결정한 부분을 모두 송치 또는 송부하는 경우에는 등본 전체를 검사에게 송부해야 한다.', 2358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4062, '① 사법경찰관은 수사준칙 제64조제1항제1호에 따라 사건을 송치하는 경우에는 기존 불송치 결정을 취소해야 한다.', 2360);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4063, '② 사법경찰관은 수사준칙 제64조제2항 단서에 따라 사건을 송치하는 경우에는 기존 불송치 결정을 변경해야 한다.', 2360);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4064, '③ 수사준칙 제64조제1항제2호에 따른 재수사 결과서는 별지 제124호서식에 따른다.', 2360);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4065, '① 법 제245조의7제1항에 따른 이의신청은 별지 제125호서식의 불송치 결정 이의신청서에 따른다.', 2361);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4066, '② 사법경찰관은 제1항의 이의신청이 있는 경우 지체 없이 수사준칙 제58조제1항에 따라 사건을 송치한다. 이 경우 관계 서류와 증거물을 검사가 보관하는 경우(제110조제3항을 적용받는 경우는 제외한다)에는 관계 서류 및 증거물을 송부하지 않고 사건송치서 및 송치 결정서만으로 사건을 송치한다.', 2361);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4067, '③ 사법경찰관은 법 제245조의7제2항에 따라 신청인에게 통지하는 경우에는 서면, 전화, 팩스, 전자우편, 문자메시지 등 신청인이 요청한 방법으로 통지할 수 있으며, 별도로 요청한 방법이 없는 경우에는 서면 또는 문자메시지로 한다. 이 경우 서면으로 하는 통지는 별지 제126호서식의 이의신청에 따른 사건송치 통지서에 따른다.', 2361);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4068, '④ 사법경찰관은 법 제245조의7제2항에 따라 사건을 송치하는 경우에는 기존 불송치 결정을 변경해야 한다.', 2361);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4069, '① 군사법경찰관리가 수사를 할 때에는 합리적 이유 없이 피의자와 그 밖의 피해자ㆍ참고인 등(이하 "사건관계인"이라 한다)을 그 성별, 종교, 나이, 장애, 사회적 신분, 출신지역, 인종, 국적, 외모 등 신체조건, 병력(病歷), 혼인 여부, 정치적 의견 및 성적(性的) 지향 등을 이유로 차별해서는 안 된다.', 2363);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4070, '② 군사법경찰관리는 「군사법원법」(이하 "법"이라 한다) 및 「군검사와 군사법경찰관의 수사준칙에 관한 규정」(이하 "수사준칙"이라 한다) 등 관계 법령을 준수하고 적법한 절차와 방식에 따라 수사해야 한다.', 2363);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4071, '① 군사법경찰관은 다음 각 호의 어느 하나에 해당하는 날부터 7일 이내에 고소인ㆍ고발인ㆍ피해자 또는 그 법정대리인(피해자가 사망한 경우에는 그 배우자ㆍ직계친족ㆍ형제자매를 포함한다. 이하 "고소인등"이라 한다)에게 수사 진행상황을 통지해야 한다. 다만, 고소인등의 연락처를 모르거나 소재가 확인되지 않으면 연락처나 소재를 알게 된 날부터 7일 이내에 수사 진행 상황을 통지해야 한다.', 2366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4072, '② 제1항에 따른 통지는 서면, 전화, 팩스, 전자우편, 문자메시지 등 고소인등이 요청한 방법으로 할 수 있으며, 고소인등이 별도로 요청한 방법이 없는 경우에는 서면 또는 문자메시지로 통지한다. 이 경우 서면으로 통지할 때에는 별지 제2호서식의 수사 진행상황 통지서에 따른다.', 2366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4073, '③ 군사법경찰관은 제2항에 따라 수사 진행상황을 서면으로 통지한 경우에는 그 사본을, 그 밖의 방법으로 통지한 경우에는 그 취지를 적은 서면을 사건기록에 편철해야 한다.', 2366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4074, '④ 군사법경찰관은 제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 수사 진행상황을 통지하지 않을 수 있다. 이 경우 그 사실을 수사보고서로 작성하여 사건기록에 편철해야 한다.', 2366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4075, '① 군사법경찰관은 법 제235조의2제1항에 따라 피의자 또는 그 변호인ㆍ법정대리인ㆍ배우자ㆍ직계친족ㆍ형제자매가 신청한 경우 변호인이 참여하면 신문(訊問)에 방해되거나  수사기밀이 누설되는 등 정당한 사유가 있는 경우를 제외하고는 피의자에 대한 신문에 변호인을 참여하게 해야 한다.', 2367);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4076, '② 제1항에 따라 변호인의 피의자신문 참여 신청을 받은 군사법경찰관은 변호인의 피의자신문 참여 전에 신청인으로부터 다음 각 호의 서면을 제출받아야 한다.', 2367);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4077, '① 군사법경찰관은 변호인이 참여하면 증거를 인멸ㆍ은닉ㆍ조작할 위험이 구체적으로 드러나거나, 신문 방해, 수사기밀 누설 등 수사에 현저한 지장을 초래하는 경우에는 피의자신문 중이라도 변호인의 참여를 제한할 수 있다. 이 경우 변호인의 참여를 제한하는 처분에 대해 법 제466조에 따른 준항고를 제기할 수 있다는 사실을 피의자와 변호인에게 고지해야 한다.', 2368);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4078, '② 제1항에 따라 변호인 참여를 제한하는 경우 군사법경찰관은 피의자 또는 변호인에게 그 사유를 설명하고 의견을 진술할 기회와 다른 변호인을 참여시킬 기회를 주어야 한다.', 2368);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4079, '③ 제1항에 따라 변호인의 참여를 제한한 후 그 사유가 해소되었을 때에는 변호인을 신문에 참여하게 해야 한다.', 2368);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4080, '① 군사법경찰관리는 피해자의 심정을 이해하고 그 인격을 존중하며, 피해자가 범죄피해 상황에서 조속히 회복하여 인간의 존엄성을 보장받을 수 있도록 노력해야 한다.', 2370);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4081, '② 군사법경찰관리는 피해자의 명예와 사생활의 평온을 보호하고 해당 사건과 관련하여 각종 법적 절차에 참여할 권리를 보장해야 한다.', 2370);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4082, '① 군사법경찰관은 법 제228조제1항에 따라 구체적인 사실에 근거를 둔 범죄의 혐의를 인식한 때에는 수사를 개시한다.', 2373);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4083, '② 군사법경찰관은 제1항에 따라 수사를 개시할 때에는 지체 없이 별지 제4호서식의 범죄인지서를 작성하여 사건기록에 편철해야 한다.', 2373);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4084, '① 군사법경찰관은 수사준칙 제11조제3항에 따른 입건 전에 범죄를 의심할 만한 정황이 있어 수사 개시 여부를 결정하기 위한 사실관계의 확인 등 필요한 조사(이하 "입건전조사"라 한다)에 착수하려는 경우에는 소속 부대 또는 기관의 장의 지휘를 받아야 한다.', 2374);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4085, '② 군사법경찰관은 입건전조사한 사건을 다음 각 호의 구분에 따라 처리해야 한다.', 2374);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4086, '① 군사법경찰관은 수사준칙 제11조제4항에 따라 피혐의자(제13조제2항제2호에 따라 입건전조사 종결을 한 경우만 해당한다)와 진정인ㆍ탄원인ㆍ피해자 또는 그 법정대리인(피해자가 사망한 경우에는 그 배우자ㆍ직계친족ㆍ형제자매를 포함한다. 이하 "진정인등"이라 한다)에게 입건하지 않는 결정을 통지할 때에는 그 결정을 한 날부터 7일 이내에 통지해야 한다. 다만, 피혐의자나 진정인등의 연락처를 모르거나 소재가 확인되지 않으면 연락처나 소재를 알게 된 날부터 7일 이내에 통지해야 한다.', 2375);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4087, '② 제1항에 따른 통지는 서면, 전화, 팩스, 전자우편, 문자메시지 등 피혐의자 또는 진정인등이 요청한 방법으로 할 수 있으며, 별도로 요청한 방법이 없는 경우에는 서면 또는 문자메시지로 한다. 이 경우 서면으로 하는 통지는 별지 제5호서식 또는 별지 제6호서식의 불입건 결정 통지서에 따른다.', 2375);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4088, '③ 군사법경찰관은 제2항에 따라 서면으로 통지한 경우에는 그 사본을, 그 밖의 방법으로 통지한 경우에는 그 취지를 적은 서면을 사건기록에 편철해야 한다.', 2375);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4089, '④ 군사법경찰관은 제1항에도 불구하고 통지로 인해 보복범죄 또는 2차 피해 등이 우려되는 다음 각 호의 경우에는 불입건 결정을 통지하지 않을 수 있다. 이 경우 그 사실을 입건전조사 보고서로 작성하여 사건기록에 편철해야 한다.', 2375);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4090, '① 군사법경찰관은 진정인ㆍ탄원인 등 민원인이 제출하는 서류가 고소ㆍ고발의 요건을 갖추었다고 판단하는 경우 이를 고소ㆍ고발로 수리한다.', 2376);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4091, '② 군사법경찰관은 고소장 또는 고발장이라는 명칭으로 제출된 서류가 다음 각 호의 어느 하나에 해당하는 경우에는 이를 진정(陳情)으로 처리할 수 있다.', 2376);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4092, '① 군사법경찰관은 구술로 제출된 고소ㆍ고발을 수리한 경우에는 진술조서를 작성해야 한다.', 2377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4093, '② 군사법경찰관은 서면으로 제출된 고소ㆍ고발을 수리했으나 추가 진술이 필요하다고 판단하는 경우 고소인ㆍ고발인으로부터 보충 서면을 제출받거나 추가로 진술을 들어야 한다.', 2377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4094, '③ 피고소인 또는 피고발인이 자수하는 경우 진술조서의 작성 및 추가 진술에 관하여는 제1항 및 제2항을 준용한다.', 2377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4095, '① 군사법경찰관은 법 제278조에 따라 대리인으로부터 고소를 수리할 때에는 고소인 본인의 위임장을 제출받아야 한다.', 2378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4096, '② 군사법경찰관은 법 제267조부터 제270조까지의 규정에 따른 고소권자로부터 고소를 수리할 때에는 그 자격을 증명하는 서면을 제출받아야 한다.', 2378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4097, '③ 군사법경찰관은 제2항에 따른 고소권자의 대리인으로부터 고소를 수리할 때에는 제1항 및 제2항에 따른 위임장 및 자격을 증명하는 서면을 함께 제출받아야 한다.', 2378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4098, '④ 고소의 취소에 관하여는 제1항부터 제3항까지의 규정을 준용한다.', 2378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4099, '① 군사법경찰관은 고소ㆍ고발을 수리한 날부터 3개월 이내에 수사를 마쳐야 한다.', 2379);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4100, '② 군사법경찰관은 제1항의 기간 내에 수사를 완료하지 못한 경우에는 그 이유를 소속 부대 또는 기관의 장에게 보고하고 수사기간 연장을 승인받아야 한다.', 2379);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4101, '① 군사법경찰관은 고소ㆍ고발의 취소가 있을 때에는 그 취지를 명확하게 확인해야 한다.', 2380);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4102, '② 피해자의 명시적인 의사에 반하여 공소를 제기할 수 없는 범죄에  대하여 처벌을 희망하는 의사표시를 피해자가 철회한 경우에도 제1항과 같다.', 2380);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4103, '① 군사법경찰관은 법 제264조제1항ㆍ제2항 및 제4항에 따라 검시를 한 경우에는 별지 제8호서식에 따른 검시조서를, 검증영장이나 같은 조 제3항ㆍ제4항에 따라 검증을 한 경우에는 별지 제9호서식에 따른 검증조서를 각각 작성하여 군검사에게 송부해야 한다.', 2383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4104, '② 군사법경찰관은 군검사에게 제1항의 검시조서 또는 검증조서를 송부할 때에는 군의관 또는 의사의 검안서, 감정서 및 촬영한 사진 등 관련 자료를 첨부해야 한다.', 2383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4105, null, 2384);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4106, '① 군사법경찰관은 변사자에 대한 검시 또는 검증이 종료된 때에는 군검사의 지휘를 받아 사체를 소지품 등과 함께 신속히 유족 등에게 인도한다.', 2386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4107, '② 제1항에서 "검시 또는 검증이 종료된 때"란 다음 각 호의 구분에 따른 때를 말한다.', 2386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4108, '③ 군사법경찰관은 제1항에 따라 사체를 인도한 경우에는 인수자로부터 별지 제10호서식의 사체 및 소지품 인수서를 받아야 한다.', 2386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4109, '① 군사법경찰관은 수사준칙 제12조에 따라 군검사에게 수사와 관련하여 의견의 제시ㆍ교환을 요청할 때에는 별지 제12호서식의 의견 요청서에 따른다.', 2388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4110, '② 군사법경찰관은 수사준칙 제12조에 따라 군검사로부터 수사와 관련하여 의견의 제시ㆍ교환 요청을 받아 의견을 제시ㆍ교환할 때에는 별지 제13호서식의 의견서에 따른다.', 2388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4111, '① 수사준칙 제18조제2항에 따른 동석신청서는 별지 제18호서식 또는 별지 제19호서식에 따른다.', 2392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4112, '② 군사법경찰관은 피의자, 피해자 또는 그 법정대리인이 제1항의 동석신청서를 작성할 시간적 여유가 없는 등 긴급한 경우에는 이를 제출받지 않고 조서 또는 수사보고서에 그 취지를 기재하는 것으로 동석신청서 작성을 갈음할 수 있다. 이 경우 조사의 긴급성 또는 동석의 필요성 등이 현저한 경우에는 예외적으로 동석 조사 이후에 신뢰관계인과 피의자와의 관계를 소명할 자료를 제출받아 기록에 편철할 수 있다.', 2392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4113, '③ 군사법경찰관은 동석 신청이 없더라도 동석이 필요하다고 인정되면 피의자 또는 피해자와의 신뢰관계 유무를 확인한 후 직권으로 신뢰관계에 있는 사람을 동석하게 할 수 있다. 이 경우 그 관계 및 취지를 조서 또는 수사보고서에 적어야 한다.', 2392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4114, '④ 군사법경찰관은 신뢰관계인이 동석하면 신문(訊問)에 방해되거나  수사기밀이 누설되는 등 정당한 사유가 있는 경우에는 동석을 거부할 수 있으며, 신뢰관계인이 피의자신문 또는 피해자 조사를 방해하거나 그 진술의 내용에 부당한 영향을 미칠 수 있는 행위를 하는 등 수사에 현저한 지장을 초래하는 경우에는 피의자신문 또는 피해자 조사 중에도 동석을 제한할 수 있다.', 2392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4115, '⑤ 피해자 외의 사건관계인 조사에 관하여는 제1항부터 제4항까지의 규정을 준용한다.', 2392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4116, '① 군사법경찰관리가 법 제236조제1항에 따라 피의자의 진술을 조서에 적을 때에는 별지 제20호서식 또는 별지 제21호서식의 피의자신문조서에 따른다.', 2393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4117, '② 군사법경찰관리가 피의자가 아닌 사람의 진술을 조서에 적을 때에는 별지 제22호서식 또는 별지 제23호서식의 진술조서에 따른다.', 2393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4118, '③ 군사법경찰관리는 피의자 또는 피의자가 아닌 사람의 진술을 듣는 경우 진술 내용이 복잡하거나 진술인이 서면진술을 원하면 진술서를 작성하여 제출하게 할 수 있다.', 2393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4119, '④ 피의자신문조서와 진술조서에는 진술자로 하여금 간인(間印)한 후 기명날인 또는 서명하게 한다.', 2393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4120, '① 군사법경찰관리는 범죄의 현장 또는 그 밖의 장소에서 피의사실을 확인하거나 증거물의 증명력을 확보하기 위해 필요한 경우 실황조사를 할 수 있다.', 2395);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4121, '② 군사법경찰관리는 제1항에 따라 실황조사를 할 때에는 거주자, 관리자, 그 밖의 관계자 등을 참여하게 할 수 있다.', 2395);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4122, '③ 군사법경찰관리는 제1항에 따라 실황조사를 하였을 때에는 별지 제26호서식의 실황조사서에 조사 내용을 상세하게 적고, 현장도면이나 사진이 있으면 이를 실황조사서에 첨부해야 한다.', 2395);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4123, '① 군사법경찰관리는 법 제236조의2제1항 또는 제260조제1항에 따라 피의자 또는 피의자가 아닌 사람을 영상녹화할 때에는 그 조사의 시작부터 조서에 기명날인 또는 서명을 마치는 시점까지의 모든 과정을 영상녹화해야 한다. 다만, 조사 도중 영상녹화를 할 필요가 발생한 때에는 그 즉시 진행 중인 조사를 중단하고, 중단한 조사를 다시 시작하는 때부터 조서에 기명날인 또는 서명을 마치는 시점까지의 모든 과정을 영상녹화해야 한다.', 2397);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4124, '② 군사법경찰관리는 제1항에도 불구하고 조사를 마친 후 조서 정리에 오랜 시간이 필요한 경우에는 조서 정리과정을 영상녹화하지 않고, 조서 열람 시부터 영상녹화를 다시 시작할 수 있다.', 2397);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4125, '③ 제1항 및 제2항에 따른 영상녹화는 조사실 전체를 확인할 수 있고 조사받는 사람의 얼굴과 음성을 식별할 수 있도록 해야 한다.', 2397);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4126, '④ 군사법경찰관리는 피의자에 대한 조사 과정을 영상녹화할 때에는 다음 각 호의 사항을 고지해야 한다.', 2397);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4127, '⑤ 군사법경찰관리는 피의자가 아닌 사람의 조사 과정을 영상녹화할 때에는 별지 제28호서식의 영상녹화 동의서에 따라 영상녹화에 대한  동의 여부를 확인하고, 제4항제1호ㆍ제2호 및 제4호의 사항을 고지해야 한다. 다만, 피혐의자에게는 제4항제1호부터 제4호까지의 규정에 따른 사항을 고지해야 한다.', 2397);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4128, '① 군사법경찰관리는 조사 시 영상녹화를 한 경우에는 영상녹화용 컴퓨터에 저장된 영상녹화 파일을 이용하여 영상녹화물(CD, DVD 등을 말한다. 이하 같다)을 제작한 후, 피조사자 또는 변호인 앞에서 지체 없이 제작된 영상녹화물을 봉인하고 피조사자로 하여금 기명날인 또는 서명하게 해야 한다.', 2398);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4129, '② 군사법경찰관리는 제1항에 따라 영상녹화물을 제작한 후 영상녹화용 컴퓨터에 저장된 영상녹화 파일을 데이터베이스 서버에 전송하여 보관할 수 있다.', 2398);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4130, '③ 군사법경찰관리는 손상 또는 분실 등으로 제1항의 영상녹화물을 사용할 수 없는 경우에는 데이터베이스 서버에 보관된 영상녹화 파일을 이용하여 다시 영상녹화물을 제작할 수 있다.', 2398);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4131, '① 법 제232조의3제3항에 따른 긴급체포서는 별지 제30호서식에 따른다.', 2400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4132, '② 수사준칙 제21조제2항 본문에 따른 긴급체포 승인요청서는 별지 제31호서식에 따른다.', 2400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4133, '③ 군사법경찰관은 수사준칙 제21조제4항 후단에 따라 긴급체포된 피의자의 석방 일시와 사유 등을 군검사에게 보고할 때에는 별지 제32호서식의 석방 보고서에 따른다.', 2400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4134, '① 군사법경찰관리는 법 제248조에 따라 현행범인을 체포할 때에는 현행범인에게 도망 또는 증거인멸의 우려가 있는 등 당장에 체포하지 않으면 안 될 정도의 급박한 사정이 있는지 또는 체포 외에는 현행범인의 위법행위를 제지할 다른 방법이 없는지 등을 고려해야 한다.', 2401);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4135, '② 군사법경찰관리는 법 제248조에 따라 현행범인을 체포하였을 때에는 별지 제33호서식의 현행범인 체포서를 작성하고, 법 제249조에 따라 현행범인을 인도받은 때에는 별지 제34호서식의 현행범인 인수서를 작성해야 한다.', 2401);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4136, '③ 군사법경찰관리는 제2항의 현행범인 체포서 또는 현행범인 인수서를 작성할 때에는 현행범인에 대해서는 범죄와의 시간적 접착성과 범죄의 명백성이 인정되는 상황을, 준현행범인(법 제247조제2항에 따른 현행범을 말한다)에 대해서는 범죄와의 관련성이 인정되는 상황을 구체적으로 적어야 한다.', 2401);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4137, '① 수사준칙 제22조제3항에 따른 피의자 석방서는 별지 제35호서식에 따른다.', 2402);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4138, '② 군사법경찰관은 수사준칙 제22조제3항에 따라 군검사에게 현행범인의 석방사실을 보고할 때에는 별지 제36호서식의 석방 보고서에 따른다.', 2402);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4139, '① 군사법경찰관리는 체포영장 또는 구속영장을 집행할 때에는 신속하고 정확하게 해야 한다.', 2404);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4140, '② 체포영장 또는 구속영장의 집행은 군검사가 서명 또는 날인하여 교부한 영장이나 군검사가 영장의 집행에 관한 사항을 적어 교부한 서면에 따른다.', 2404);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4141, '③ 수사준칙 제26조제3항에 따른 권리 고지 확인서는 별지 제41호서식에 따른다. 다만, 피의자가 권리 고지 확인서에 기명날인 또는 서명하기를 거부하는 경우에는 피의자를 체포ㆍ구속하는 군사법경찰관리가 확인서 끝부분에 그 사유를 적고 기명날인 또는 서명해야 한다.', 2404);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4142, '① 군사법경찰관리는 체포ㆍ구속한 피의자를 호송할 때에는 피의자의 도망ㆍ자살ㆍ신변안전ㆍ증거인멸 등에 주의해야 한다.', 2405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4143, '② 군사법경찰관리는 체포ㆍ구속한 피의자를 호송할 때 필요한 경우에는 가장 근접한 군사경찰부대, 수사부대나 국가경찰관서에 피의자를 임시로 유치할 수 있다.', 2405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4144, '① 군사법경찰관은 법 제232조의6ㆍ제246조에서 준용하는 법 제131조 또는 「군에서의 형의 집행 및 군수용자의 처우에 관한 법률」 제42조에 따라 체포 또는 구속된 피의자와 법 제63조에서 규정한 사람이 아닌 사람과의 접견 등을 금지하는 결정을 하려는 경우에는 별지 제44호서식의 피의자 접견 등 금지 결정서에 따른다.', 2408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4145, '② 군사법경찰관은 제1항의 결정을 취소하는 것이 타당하다고 인정되어 피의자 접견 등의 금지를 취소하는 결정을 할 때에는 별지 제45호서식의 피의자 접견 등 금지 취소 결정서에 따른다.', 2408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4146, '③ 제1항의 피의자 접견 등 금지 결정은 군사법경찰관의 사건 송치와 동시에 그 효력을 상실한다.', 2408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4147, '① 수사준칙 제30조제1항에 따른 피의자 석방서는 별지 제46호서식 또는 별지 제47호서식에 따른다.', 2409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4148, '② 군사법경찰관은 군검사에게 수사준칙 제30조제2항제1호에 따라 석방사실을 통보할 때에는 별지 제48호서식의 석방 통보서에 따르고, 같은 항 제2호에 따라 석방사실을 보고할 때에는 별지 제49호서식의 석방 보고서에 따른다.', 2409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4149, '① 군사법경찰관은 법 제246조에서 준용하는 법 제133조에 따라 구속을 취소하여 피의자를 석방하는 결정을 할 때에는  군검사의 동의를 받아야 한다. 이 경우 별지 제50호서식에 따른 구속취소 동의 요청서를 군검사에게 송부해야 한다.', 2410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4150, '② 제1항에 따라 구속취소 결정을 할 때에는 문서로 해야 한다. 이 경우 별지 제51호서식의 구속취소 결정서에 따른다.', 2410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4151, '③ 제1항 및 제2항에 따라 구속취소 결정을 한 군사법경찰관은 피의자를 석방한 후 지체 없이 별지 제52호서식의 석방 통보서를 작성하여 군검사에게 석방사실을 통보하고, 그 통보서 사본을 사건기록에 편철해야 한다.', 2410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4152, '① 군사법경찰관은 법 제246조에서 준용하는 법 제141조제1항에 따라 구속의 집행을 정지하는 결정을 할 때에는 군검사의 의견을 들어야 한다.', 2411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4153, '② 제1항에 따라 구속의 집행정지 결정을 할 때에는 문서로 해야 한다. 이 경우 별지 제53호서식의 구속집행정지 결정서에 따른다.', 2411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4154, '③ 제1항 및 제2항에 따라 구속의 집행을 정지한 군사법경찰관은 지체 없이 별지 제54호서식의 구속집행정지 통보서를 작성하여 군검사에게 그 사실을 통보하고, 그 통보서 사본을 사건기록에 편철해야 한다.', 2411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4155, '④ 군사법경찰관은 법 제246조에서 준용하는 법 제142조제2항에 따라 구속집행정지 결정을 취소할 때에는 별지 제55호서식의 구속집행정지 취소 결정서에 따른다.', 2411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4156, '① 군사법경찰관은 수사준칙 제31조에 따라 압수ㆍ수색 또는 검증영장을 신청할 때에는 별지 제56호서식부터 별지 제58호서식까지의 압수ㆍ수색ㆍ검증영장 신청서에 따른다. 이 경우 압수ㆍ수색 또는 검증의 필요성 및 해당 사건과의 관련성을 인정할 수 있는 자료를 신청서에 첨부해야 한다.', 2412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4157, '② 압수ㆍ수색 또는 검증영장의 집행 및 반환에 관하여는 제43조제1항ㆍ제2항 및 제46조를 준용한다.', 2412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4158, '① 수사준칙 제34조 본문에 따른 압수조서는 별지 제59호서식에 따르고, 압수목록은 별지 제60호서식에 따른다.', 2413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4159, '② 군사법경찰관은 법 제258조에서 준용하는 법 제170조에 따라 압수목록을 교부할 때에는 별지 제61호서식의 압수목록 교부서에 따른다. 이 경우 수사준칙 제35조제1항에 따른 전자정보에 대한 압수목록 교부서는 전자파일의 형태로 복사해 주거나 전자우편으로 전송하는 등의 방식으로 교부할 수 있다.', 2413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4160, '③ 수사준칙 제36조제2항 후단에 따른 삭제ㆍ폐기 또는 반환확인서는 별지 제62호서식에 따른다.', 2413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4161, '① 군사법경찰관은 법 제254조에 따라 수색을 한 경우에는 수색의 상황과 결과를 명백히 한 별지 제63호서식의 수색조서를 작성해야 한다.', 2414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4162, '② 군사법경찰관은 법 제258조에서 준용하는 법 제169조에 따라 증거물 또는 몰수할 물건이 없다는 취지의 증명서를 교부할 때에는 별지 제64호서식의 수색증명서에 따른다.', 2414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4163, '① 군사법경찰관은 법 제257조의2제1항 및 제4항에 따라 압수물에 대해 그 소유자, 소지자, 보관자 또는 제출인(이하 이 조에서 "소유자등"이라 한다)으로부터 환부 또는 가환부의 청구를 받거나 법 제258조에서 준용하는 법 제175조에 따라 압수장물을 피해자에게 환부하려는 경우에는 군검사의 동의를 받아야 한다. 이 경우 별지 제65호서식의 압수물 환부ㆍ가환부 동의 요청서를 군검사에게 송부해야 한다.', 2415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4164, '② 군사법경찰관은 제1항에 따른 압수물의 환부 또는 가환부의 청구를 받았을 때에는 소유자등으로부터 별지 제66호서식의 압수물 환부ㆍ가환부 청구서를 제출받아야 한다.', 2415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4165, '③ 군사법경찰관은 압수물을 환부 또는 가환부한 경우에는 피해자 및 소유자등으로부터 별지 제67호서식의 압수물 환부ㆍ가환부 영수증을 받아야 한다.', 2415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4166, '① 군사법경찰관은 압수물에 다음 각 호의 사항이 적힌 표찰을 붙여야 한다.', 2416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4167, '② 군사법경찰관은 법 제258조에서 준용하는 법 제171조제1항에 따라 압수물을 다른 사람에게 보관하게 하려는 경우에는 군검사의 동의를 받아야 한다. 이 경우 별지 제68호서식의 압수물 위탁보관 동의 요청서를 군검사에게 송부해야 한다.', 2416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4168, '③ 군사법경찰관은 제2항에 따라 압수물을 다른 사람에게 보관하게 하는 경우에는 적절한 보관인을 선정하여 성실하게 보관하게 하고, 보관인으로부터 별지 제69호서식의 압수물 보관 서약서를 제출받아야 한다.', 2416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4169, '① 군사법경찰관은 법 제258조에서 준용하는 법 제171조제2항 및 제3항에 따라 압수물을 폐기하려는 경우에는 군검사의 동의를 받아야 한다. 이 경우 별지 제70호서식의 압수물 폐기 동의 요청서를 군검사에게 송부해야 한다.', 2417);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4170, '② 군사법경찰관은 제1항에 따라 압수물을 폐기할 때에는 별지 제71호서식의 압수물 폐기 조서를 작성하고 사진을 촬영하여 사건기록에 편철해야 한다.', 2417);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4171, '③ 군사법경찰관은 법 제258조에서 준용하는 법 제171조제3항에 따라 압수물을 폐기할 때에는 소유자 등 권한이 있는 사람으로부터 별지 제72호서식의 압수물 폐기 동의서를 제출받거나 진술조서 등에 그 취지를 적어야 한다.', 2417);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4172, '① 군사법경찰관은 법 제258조에서 준용하는 법 제173조에 따라 압수물을 매각하여 대가를 보관하려는 경우에는 군검사의 동의를 받아야 한다. 이 경우 별지 제73호서식의 압수물 대가보관 동의 요청서를 군검사에게 송부해야 한다.', 2418);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4173, '② 군사법경찰관은 제1항에 따라 대가보관의 처분을 했을 때에는 별지 제74호서식의 압수물 대가보관 조서를 작성해야 한다.', 2418);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4174, '① 군사법경찰관은 법 제260조제2항의 감정을 위하여 법 제213조제3항에 따른 유치가 필요한 경우에는 군검사에게 감정유치장 발부의 청구를 신청할 수 있다. 이 경우 감정유치장의 발부 청구 신청서는 별지 제77호서식에 따른다.', 2422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4175, '② 군사법경찰관은 법 제263조제1항에 따라 법 제215조제1항에 따른 처분을 위한 허가가 필요한 경우에는 군검사에게 감정처분허가장 발급의 청구를 신청할 수 있다. 이 경우 감정처분허가장의 발급 청구 신청서는 별지 제78호서식에 따른다.', 2422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4176, '① 수사준칙 제41조에 따른 수사서류 등의 열람ㆍ복사 신청은 해당 수사서류 등을 보유ㆍ관리하는 수사부대 또는 기관의 장에게 한다.', 2423);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4177, '② 제1항의 신청을 받은 수사부대 또는 기관의 장은 신청을 받은 날부터 10일 이내에 다음 각 호의 어느 하나에 해당하는 결정을 해야 한다.', 2423);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4178, '③ 수사부대 또는 기관의 장은 제2항에도 불구하고 피의자 및 사건관계인, 그 변호인이 조사 당일 본인의 진술이 기재된 조서에 대해 열람ㆍ복사를 신청할 때에는 공개 여부에 대해 지체 없이 검토한 후 제공 여부를 결정해야 한다.', 2423);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4179, '④ 수사부대 또는 기관의 장은 해당 관서에서 보유ㆍ관리하지 않는 수사서류 등에 대해 열람ㆍ복사 신청을 접수한 경우에는 그 신청을 해당 수사서류 등을 보유ㆍ관리하는 기관으로 이송하거나 신청인에게 부존재 통지를 해야 한다.', 2423);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4180, '⑤ 수사부대 또는 기관의 장은 제2항제1호 또는 제2호에 따라 수사서류 등을 제공할 때에는 사건관계인의 개인정보가 공개되지 않도록 비실명처리 등 보호조치를 해야 한다.', 2423);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4181, '⑥ 제1항부터 제5항까지에서 규정한 사항 외에 수사서류 등의 열람ㆍ복사에 필요한 세부 사항은 국방부장관이 따로 정한다.', 2423);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4182, '① 군사법경찰관은 법령에서 다른 수사기관으로 사건을 이송하도록 의무를 부여한 경우에는 해당 사건을 다른 수사기관에 이송해야 한다.', 2424);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4183, '② 군사법경찰관은 사건이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 사건을 다른 수사부대 또는 기관에 이송할 수 있다.', 2424);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4184, '③ 군사법경찰관은 제1항 또는 제2항에 따라 사건을 이송할 때에는 별지 제79호서식의 사건이송서를 사건기록에 편철하고 관계 서류와 증거물을 다른 수사부대 또는 기관에 송부해야 한다.', 2424);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4185, '① 군사법경찰관은 수사를 종결하였을 때에는 사건을 군검사에게 다음 각 호의 구분에 따라 송치해야 한다.', 2425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4186, '② 즉결심판 대상사건은 군사경찰부대의 장이 관할 군사법원에 청구한다.', 2425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4187, '③ 「군용물 등 범죄에 관한 특별조치법」 위반 사건 중 「군형법」의 적용대상자가 아닌 자의 경우에는 관할 지방검찰청 검사에게 송치해야 한다.', 2425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4188, '① 수사준칙 제38조제1항에 따른 송치 의견서는 별지 제80호서식 또는 별지 제81호서식에 따르고, 압수물 총목록은 별지 제82호서식에 따르며, 기록목록은 별지 제83호서식에 따른다.', 2426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4189, '② 송치 서류는 다음 각 호의 순서에 따라 편철한다.', 2426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4190, '③ 수사준칙 제38조제3항에 따라 증거물 등을 추가로 송부할 때에는 별지 제85호서식에 따른다.', 2426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4191, '④ 수사준칙 제38조에 따라 사건을 송치하는 경우에는 소속 부대 또는 기관의 장 명의로 한다.', 2426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4192, '⑤ 제1항의 송치 의견서는 군사법경찰관이 작성해야 한다.', 2426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4193, '① 군사법경찰관은 법 제283조제3항에 따라 보완수사 이행 결과를 통보할 때에는 별지 제86호서식의 보완수사 결과 통보서에 따른다. 다만, 수사준칙 제39조에 따른 보완수사요구의 대상이 아니거나 그 범위를 벗어난 경우 등 정당한 이유가 있어 보완수사를 이행하지 않은 경우에는 그 내용과 사유를 보완수사 결과 통보서에 적어 군검사에게 통보해야 한다.', 2427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4194, '② 군사법경찰관은 법 제283조제2항제1호에 따른 보완수사요구에 대한 이행 결과를 통보하면서 새로운 증거물, 서류 및 그 밖의 자료를 군검사에게 송부할 때에는 수사준칙 제38조제3항에 따른다.', 2427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4195, '③ 군사법경찰관은 법 제283조제2항제2호에 따른 보완수사요구를 이행한 경우에는 다음 각 호의 구분에 따라 처리한다.', 2427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4196, '① 「사법경찰관리의 직무를 행할 자와 그 직무범위에 관한 법률」(이하 "사법경찰직무법"이라 한다)에 따라 사법경찰관의 직무를 행하는 자(이하 "특별사법경찰관"이라 한다)는 사법경찰직무법에 따른 직무의 범위에서 범인과 범죄사실을 수사하고 그에 관한 증거를 수집하는 것을 그 직무로 한다.', 2429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4197, '② 법에 따라 사법경찰리의 직무를 행하는 자(이하 "특별사법경찰리"라 한다)는 특별사법경찰관의 수사를 보조하는 것을 그 직무로 한다.', 2429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4198, '③ 특별사법경찰관 및 특별사법경찰리(이하 "특별사법경찰관리"라 한다)는 범죄를 수사하거나 그 수사를 보조하는 경우에는 검사의 지휘를 받아야 한다.', 2429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4199, '① 특별사법경찰관리는 모든 수사과정에서 헌법과 법률에 따라 보장되는 피의자와 그 밖의 피해자ㆍ참고인 등(이하 "사건관계인"이라 한다)의 권리를 보호하고, 적법한 절차에 따라야 한다.', 2430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4200, '② 특별사법경찰관리는 예단(豫斷)이나 편견 없이 신속하게 수사해야 하고, 주어진 권한을 자의적으로 행사하거나 남용해서는 안 된다.', 2430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4201, '③ 특별사법경찰관리는 다른 사건의 수사를 통해 확보된 증거 또는 자료를 내세워 관련이 없는 사건에 대한 자백이나 진술을 강요해서는 안 된다.', 2430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4202, '① 특별사법경찰관리는 범죄를 수사할 때에는 기밀을 엄수해야 하며, 수사의 모든 과정에서 피의자와 사건관계인의 사생활의 비밀을 보호하고 그들의 명예나 신용이 훼손되지 않도록 노력해야 한다.', 2432);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4203, '② 특별사법경찰관리는 수사 관련 사항, 피의자와 사건관계인의 개인정보, 그 밖에 직무상 알게 된 사실을 누설(구체적 사건의 수사와 관련하여 수사권한이나 수사지휘 권한이 없는 상급자에게 누설하는 것을 포함한다)해서는 안 된다.', 2432);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4204, '① 특별사법경찰관리는 법령에 따라 정해진 관할구역에서 직무를 수행한다. 다만, 관할구역의 사건과 관련성이 있는 사실을 발견하기 위해 필요한 때에는 관할구역 밖에서도 그 직무를 수행할 수 있다.', 2433);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4205, '② 특별사법경찰관리는 관할구역 밖에서 수사하려는 경우에는 관할 지방검찰청 검사장 또는 지청장에게 미리 보고해야 한다. 다만, 「형사소송법」(이하 "법"이라 한다) 제200조의3, 제212조, 제214조, 제216조 및 제217조에 따른 수사를 하는 경우로서 긴급을 요구하여 미리 보고할 시간적 여유가 없을 때에는 사후에 보고할 수 있다.', 2433);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4206, '① 특별사법경찰관리는 수사를 할 때 수사 대상자의 자유로운 의사에 따른 임의수사를 원칙으로 해야 하고, 강제수사는 법률에서 정한 바에 따라 필요한 경우에만 최소한의 범위에서 하되, 수사 대상자의 권익 침해의 정도가 더 적은 절차와 방법을 선택해야 한다.', 2434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4207, '② 특별사법경찰관리는 피의자를 체포ㆍ구속하는 과정에서 피의자 및 현장에 있는 가족 등 지인들의 인격과 명예를 침해하지 않도록 유의해야 한다.', 2434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4208, '③ 특별사법경찰관리는 압수ㆍ수색 과정에서 사생활의 비밀, 주거의 평온을 최대한 보장하고, 피의자 및 현장에 있는 가족 등 지인들의 인격과 명예를 침해하지 않도록 유의해야 한다.', 2434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4209, '① 특별사법경찰관은 법 제243조의2제1항에 따라 피의자 또는 그 변호인ㆍ법정대리인ㆍ배우자ㆍ직계친족ㆍ형제자매의 신청이 있는 경우에는 변호인의 참여로 인하여 신문이 방해되거나, 수사기밀이 누설되는 등 정당한 사유가 있는 경우를 제외하고는 피의자에 대한 신문에 변호인을 참여하게 해야 한다.', 2437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4210, '② 피의자 또는 그 변호인ㆍ법정대리인ㆍ배우자ㆍ직계친족ㆍ형제자매가 법 제243조의2제1항에 따른 피의자에 대한 신문의 변호인 참여를 신청하는 경우에는 별지 제1호서식의 변호인ㆍ변호사 참여신청서 또는 구술로 할 수 있다.', 2437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4211, '③ 특별사법경찰관은 변호인의 참여로 증거를 인멸ㆍ은닉ㆍ조작할 위험이 구체적으로 드러나거나, 신문 방해, 수사기밀 누설 등 수사에 현저한 지장을 초래하는 경우에는 피의자신문 중이라도 변호인의 참여를 제한할 수 있다. 이 경우 특별사법경찰관은 피의자와 변호인에게 변호인 참여를 제한하는 처분에 대해 법 제417조에 따른 준항고를 제기할 수 있다는 사실을 고지하고, 피의자에게 다른 변호인을 참여시킬 기회를 주어야 한다.', 2437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4212, '④ 특별사법경찰관은 피의자신문에 참여한 변호인이 피의자의 옆자리 등 실질적인 조력을 할 수 있는 위치에 앉도록 해야 하고, 정당한 사유가 없으면 피의자에 대한 법적인 조언ㆍ상담을 보장해야 하며, 법적인 조언ㆍ상담을 위한 변호인의 메모를 허용해야 한다.', 2437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4213, '⑤ 특별사법경찰관은 피의자에 대한 신문이 아닌 단순 면담 등이라는 이유로 변호인의 참여ㆍ조력을 제한해서는 안 된다.', 2437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4214, '⑥ 제1항부터 제5항까지의 규정은 특별사법경찰관의 사건관계인에 대한 조사ㆍ면담 등의 경우에도 적용한다.', 2437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4215, '⑦ 특별사법경찰관은 변호인이 여럿 있을 때에는 법 제32조의2에 따른 대표변호인의 지정, 지정의 철회 또는 변경을 별지 제2호서식의 대표변호인 지정 등 건의서로 검사에게 건의할 수 있다.', 2437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4216, '① 피의자신문에 참여한 변호인은 신문 후 조서를 열람하고 의견을 진술할 수 있다. 이 경우 변호인은 별도의 서면으로 의견을 제출할 수 있으며, 특별사법경찰관은 해당 서면을 사건기록에 편철한다.', 2438);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4217, '② 피의자신문에 참여한 변호인은 신문 중이라도 특별사법경찰관의 승인을 받아 의견을 진술할 수 있다. 이 경우 특별사법경찰관은 정당한 사유가 있는 경우를 제외하고는 변호인의 의견진술 요청을 승인해야 한다.', 2438);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4218, '③ 피의자신문에 참여한 변호인은 제2항에도 불구하고 부당한 신문방법에 대해서는 특별사법경찰관의 승인 없이 이의를 제기할 수 있다.', 2438);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4219, '④ 특별사법경찰관은 제1항부터 제3항까지의 규정에 따른 의견진술 또는 이의제기가 있는 경우 해당 내용을 조서에 적어야 한다.', 2438);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4220, '① 특별사법경찰관리는 피해자의 명예와 사생활의 평온을 보호하기 위해 「범죄피해자 보호법」 등 피해자 보호 관련 법령의 규정을 준수해야 한다.', 2439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4221, '② 특별사법경찰관리는 피의자의 범죄수법, 범행 동기, 피해자와의 관계, 언동 및 그 밖의 상황으로 보아 피해자가 피의자 또는 그 밖의 사람으로부터 생명ㆍ신체에 위해를 입거나 입을 염려가 있다고 인정되는 경우에는 직권 또는 피해자의 신청에 따라 신변보호에 필요한 조치를 강구해야 한다.', 2439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4222, null, 2441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4223, '① 지방검찰청 검사장이나 지청장은 범죄의 태양(態樣), 범죄가 미치는 사회적 영향 등을 고려하여 특정 범죄(사법경찰직무법 제8조 및 제9조에 따른 사법경찰관리의 직무범위에 속하는 범죄는 제외한다)를 중점적으로 단속할 필요가 있거나 특정사범에 대한 일반사법경찰관리와 특별사법경찰관리의 중복단속을 피하기 위해 필요한 때에는 관계 행정기관의 장과 협의하여 합동단속반을 설치ㆍ운영할 수 있다.', 2443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4224, '② 지방검찰청 검사장 또는 지청장은 합동단속이나 실태조사 또는 특별사법경찰관리의 전문지식과 인권의식 함양 등을 위해 필요한 때에는 특별사법경찰관리가 소속된 행정기관의 장에게 특별사법경찰관리의 파견, 특별사법경찰관리의 직무를 소관으로 하는 부서에서의 일정기간 근무, 수사실무나 수사 관계 법률 또는 인권에 관한 교육의 수강 등 필요한 사항의 협조를 요청할 수 있다.', 2443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4225, '① 특별사법경찰관은 직무범위에 속하는 범죄에 관한 신문ㆍ방송이나 그 밖의 보도매체의 기사, 익명의 신고 또는 풍문이 있는 경우에는 특히 출처에 주의하여 진상을 내사하고, 내사 결과 범죄의 혐의가 있다고 인정할 때에는 즉시 수사를 개시해야 한다.', 2444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4226, '② 특별사법경찰관은 내사 결과 범죄의 혐의가 없다고 인정될 때에는 즉시 내사를 종결해야 한다.', 2444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4227, '③ 특별사법경찰관은 익명이나 가공인물의 이름으로 이루어진 진정ㆍ탄원 및 투서의 내용을 정확히 판단하여 수사 단서로서 가치가 없다고 인정할 때에는 내사하지 않을 수 있다.', 2444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4228, '④ 특별사법경찰관은 진정ㆍ탄원 및 투서의 내용이 소관으로 하는 형벌법규에 저촉되지 않는 것이 명백하다고 인정할 때에는 진정인ㆍ탄원인 및 투서인에게 그 뜻을 통지하고 내사하지 않을 수 있다.', 2444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4229, '① 특별사법경찰관이 수사를 개시한 경우에는 별지 제3호서식의 범죄인지서를 작성해야 한다.', 2445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4230, '② 제1항에 따른 범죄인지서에는 피의자의 성명ㆍ주민등록번호ㆍ직업ㆍ주거ㆍ범죄경력, 수사경력, 죄명, 범죄사실 및 적용될 법조문을 적어야 하며, 범죄사실에는 범죄의 일시ㆍ장소ㆍ방법 등을 명시하고 특히 수사의 단서와 범죄사실을 인지하게 된 경위를 구체적으로 적어야 한다.', 2445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4231, '① 특별사법경찰관이 다음 각 호의 어느 하나에 해당하는 행위에 착수한 때에는 수사를 개시한 것으로 본다. 이 경우 특별사법경찰관은 해당 사건을 즉시 입건해야 한다.', 2446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4232, '② 특별사법경찰관은 수사 중인 사건의 범죄 혐의를 밝히기 위한 목적으로 관련 없는 사건의 수사를 개시하거나 수사기간을 부당하게 연장해서는 안 된다.', 2446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4233, '③ 특별사법경찰관은 입건 전에 범죄를 의심할 만한 정황이 있어 수사 개시 여부를 결정하기 위한 사실관계의 확인 등 필요한 조사를 할 때에는 적법절차를 준수하고 사건관계인의 인권을 존중하며, 조사가 부당하게 장기화되지 않도록 신속하게 진행해야 한다.', 2446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4234, '④ 특별사법경찰관은 제3항에 따른 조사 결과 입건하지 않는 결정을 한 때에는 피해자에 대한 보복범죄나 2차 피해가 우려되는 경우 등을 제외하고는 피혐의자 및 사건관계인에게 통지해야 한다.', 2446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4235, '① 특별사법경찰관리는 다음 각 호의 어느 하나에 해당하는 행위를 한 후 제18조에 따른 범죄인지서를 작성하지 않은 사건에 대해서는 매 분기마다 해당 사건의 목록과 요지를 검사에게 제출해야 한다.', 2447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4236, '② 검사는 제1항 각 호의 행위가 다음 각 호의 어느 하나에 해당하는 경우에는 구체적 사건을 특정하여 특별사법경찰관리에게 관계 서류와 증거물을 제출할 것을 서면으로 지시할 수 있다. 이 경우 특별사법경찰관리는 그 지시에 따라야 한다.', 2447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4237, '① 특별사법경찰관은 변사자 또는 변사한 것으로 의심되는 시체가 있으면 변사사건 발생사실을 즉시 관할 지방검찰청 또는 지청의 검사에게 보고하고 지휘를 받아야 한다.', 2448);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4238, '② 특별사법경찰관이 검사의 명령으로 법 제222조제1항 및 제3항에 따라 검시를 했을 때에는 별지 제4호서식의 검시조서를 작성해야 한다.', 2448);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4239, '① 특별사법경찰관리는 검시에 착수하기 전에 변사자의 위치ㆍ상태 등이 변하지 않도록 현장을 보존해야 한다.', 2449);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4240, '② 특별사법경찰관리는 변사자의 소지품이나 그 밖에 변사자가 남겨 놓은 물건이 수사에 필요하다고 인정될 때에는 이를 주의하여 보존해야 한다.', 2449);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4241, '③ 특별사법경찰관리는 검시를 할 때에는 잠재지문과 변사자의 지문을 주의하여 채취하고, 의사로 하여금 사체검안서를 작성하게 해야 한다.', 2449);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4242, null, 2452);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4243, null, 2453);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4244, '① 특별사법경찰관은 사건마다 범죄통계원표(발생사건표, 검거사건표 및 피의자표를 말한다)를 작성하여 검찰총장이나 관할 지방검찰청 검사장 또는 지청장에게 제출해야 한다.', 2454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4245, '② 특별사법경찰관은 사건을 인지할 때에는 피의자의 지문을 채취하여 별지 제6호서식의 수사자료표 송부서에 따라 지문대조조회를 해야 한다.', 2454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4246, '③ 특별사법경찰관이 고소ㆍ고발을 받은 사건을 직접 수사할 때에는 피의자의 지문을 채취하여 별지 제6호서식의 수사자료표 송부서에 따라 지문대조조회를 해야 한다. 다만, 고소ㆍ고발을 받은 사건이 다음 각 호의 어느 하나에 해당하는 경우로서 피의자가 「지문을 채취할 형사피의자의 범위에 관한 규칙」 제2조제2항제1호ㆍ제2호 또는 제4호의 어느 하나에 해당하지 않는 경우에는 피의자에 대한 지문채취 및 지문대조조회를 하지 않을 수 있다.', 2454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4247, '① 검찰총장, 지방검찰청 검사장 또는 지청장은 국민의 인권을 보호하고 수사절차의 투명성과 수사의 효율성을 보장하기 위해 특별사법경찰관리에게 필요한 일반적 수사준칙 또는 지침을 마련하여 시행할 수 있다.', 2456);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4248, '② 지방검찰청 검사장 또는 지청장이 제1항에 따라 일반적 수사지휘를 하거나 세부 지침 등을 마련하여 시행하는 경우에는 법무부장관과 검찰총장에게 일반적 수사지휘 또는 세부 지침 등의 내용을 보고해야 한다.', 2456);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4249, '① 특별사법경찰관은 사건을 수사할 때 검사의 지휘가 필요하면 검사에게 별지 제7호서식의 수사지휘 건의서로 건의하여 구체적 지휘를 받아 수사할 수 있다. 다만, 범법자 출입국 규제 요청과 관련하여 지휘건의를 하는 경우에는 별지 제8호서식의 범법자 출입국 규제 요청 지휘 건의서에 따른다.', 2457);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4250, '② 특별사법경찰관은 사건 수사와 관련하여 일반사법경찰관리 또는 다른 기관의 특별사법경찰관리와 업무권한의 충돌이나 분쟁이 생겨 기관 간의 업무 조정이 필요한 경우에도 별지 제7호서식의 수사지휘 건의서로 건의하여 구체적 지휘를 받아 수사할 수 있다.', 2457);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4251, '① 검사는 특별사법경찰관리에게 사건에 대한 구체적 지휘를 할 때에는 서면 또는 「형사사법절차 전자화 촉진법」에 따른 형사사법정보시스템(이하 "형사사법정보시스템"이라 한다)을 이용하여 지휘해야 한다. 다만, 천재지변, 긴급한 상황, 이미 수사지휘한 내용을 보완하거나 지휘 내용이 명확한 경우, 수사 현장에서 지휘하는 경우 등 서면 또는 형사사법정보시스템에 의한 지휘가 불가능하거나 필요 없다고 인정되는 경우에는 구두나 전화 등 간편한 방식으로 지휘할 수 있다.', 2458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4252, '② 특별사법경찰관은 검사가 제1항 단서에 따라 간편한 방식으로 지휘하였을 때에는 서면 또는 형사사법정보시스템을 이용하여 지휘해 줄 것을 요청할 수 있다.', 2458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4253, '③ 검사는 수사지휘를 위해 필요할 때에는 특별사법경찰관리에게 모든 관계 서류와 증거물을 송부할 것을 지시할 수 있다.', 2458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4254, '④ 검사는 사건이 복잡하여 설명이 필요한 경우 특별사법경찰관에게 대면하여 설명할 것을 요구할 수 있고, 특별사법경찰관은 수사 중인 사건에 관하여 필요할 때에는 검사에게 대면하여 보고할 수 있다.', 2458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4255, '① 특별사법경찰관은 다음 각 호의 어느 하나에 해당하는 경우에는 해당 검사에게 의견을 밝히고 재지휘를 건의할 수 있다.', 2459);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4256, '② 검사는 제1항에 따른 재지휘 건의를 받은 때에는 재지휘 여부를 결정하고, 필요한 조치를 해야 한다.', 2459);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4257, '① 특별사법경찰관은 검사가 기한을 지정하였을 때에는 그 기한 내에 지휘 사항을 이행해야 한다.', 2461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4258, '② 특별사법경찰관이 검사가 지휘한 기한 내에 지휘 사항을 이행하지 못하였을 때에는 그 사유를 소명하여 검사에게 별지 제9호서식의 수사기일 연장지휘 건의서로 수사기일 연장지휘를 건의해야 한다.', 2461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4259, '① 특별사법경찰관은 다음 각 호의 어느 하나에 해당하는 범죄에 대하여 수사를 개시했을 때에는 검사에게 지휘를 건의하고 입건 여부에 대한 검사의 의견에 따라야 한다.', 2462);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4260, '② 특별사법경찰관은 제1항 각 호 외의 범죄에 대해서도 사안의 중대성 등을 고려하여 필요한 경우 검사에게 입건 여부에 대한 지휘를 받을 수 있다.', 2462);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4261, '③ 특별사법경찰관은 제20조제2항에 따라 관계 서류와 증거물을 제출한 사건을 입건하거나 사건을 종결하려면 미리 검사의 지휘를 받아야 한다.', 2462);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4262, '① 특별사법경찰관은 피의자에게 출석요구를 할 때에는 다음 각 호의 사항을 유의해야 한다.', 2463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4263, '② 특별사법경찰관은 피의자에게 출석요구를 하려는 경우 피의자와 조사의 일시ㆍ장소에 관하여 협의해야 한다. 이 경우 변호인이 있는 경우에는 변호인과도 협의해야 한다.', 2463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4264, '③ 특별사법경찰관은 피의자에게 출석요구를 하려는 경우 피의사실의 요지 등 출석요구의 취지를 구체적으로 적은 별지 제10호서식의 출석요구서를 발송해야 한다. 다만, 신속한 출석요구가 필요한 경우 등 부득이한 사정이 있는 경우에는 전화, 문자메시지, 그 밖의 상당한 방법으로 출석요구를 할 수 있다.', 2463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4265, '④ 특별사법경찰관은 제3항 본문에 따른 방법으로 출석요구를 했을 때에는 출석요구서의 사본을, 같은 항 단서에 따른 방법으로 출석요구를 했을 때에는 그 취지를 적은 수사보고서를 각각 사건기록에 편철한다.', 2463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4266, '⑤ 특별사법경찰관은 피의자가 치료 등 수사관서에 출석하여 조사를 받는 것이 현저히 곤란한 사정이 있는 경우에는 수사관서 외의 장소에서 조사할 수 있다.', 2463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4267, '⑥ 제1항부터 제5항까지의 규정은 피의자가 아닌 사람에 대한 출석요구의 경우에도 적용한다. 이 경우 피의자가 아닌 사람에 대한 출석요구는 별지 제11호서식의 참고인 출석요구서에 따른다.', 2463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4268, '⑦ 특별사법경찰관은 제3항 또는 제6항에 따라 피의자 또는 피의자가 아닌 사람에게 출석요구를 한 경우에는 별지 제12호서식의 출석요구통지부에 해당 사항을 적어야 한다.', 2463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4269, '① 특별사법경찰관은 조사, 신문, 면담 등 그 명칭을 불문하고 피의자나 사건관계인에 대해 오후 9시부터 오전 6시까지 사이에 조사(이하 "심야조사"라 한다)를 해서는 안 된다. 다만, 이미 작성된 조서의 열람을 위한 절차는 자정 이전까지 진행할 수 있다.', 2465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4270, '② 제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 심야조사를 할 수 있다. 이 경우 심야조사의 사유를 조서에 명확하게 적어야 한다.', 2465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4271, '① 특별사법경찰관은 조사, 신문, 면담 등 그 명칭을 불문하고 피의자나 사건관계인을 조사하는 경우에는 대기시간, 휴식시간, 식사시간 등 모든 시간을 합산한 조사시간(이하 "총조사시간"이라 한다)이 12시간을 초과하지 않도록 해야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 예외로 한다.', 2466);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4272, '② 특별사법경찰관은 특별한 사정이 없으면 총조사시간 중 식사시간, 휴식시간 및 조서의 열람시간 등을 제외한 실제 조사시간이 8시간을 초과하지 않도록 해야 한다.', 2466);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4273, '③ 특별사법경찰관은 피의자나 사건관계인에 대한 조사를 마친 때부터 8시간이 지나기 전에는 다시 조사할 수 없다. 다만, 제1항제2호에 해당하는 경우에는 예외로 한다.', 2466);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4274, '① 특별사법경찰관은 조사에 상당한 시간이 소요되는 경우에는 특별한 사정이 없으면 피의자 또는 사건관계인에게 조사 도중에 최소한 2시간마다 10분 이상의 휴식시간을 주어야 한다.', 2467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4275, '② 특별사법경찰관은 조사 도중 피의자, 사건관계인 또는 그 변호인으로부터 휴식시간의 부여를 요청받았을 때에는 그때까지 조사에 소요된 시간, 피의자 또는 사건관계인의 건강상태 등을 고려해 적정하다고 판단될 경우 휴식시간을 주어야 한다.', 2467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4276, '③ 특별사법경찰관은 조사 중인 피의자 또는 사건관계인의 건강상태에 이상 징후가 발견되면 의사의 진료를 받게 하거나 휴식하게 하는 등 필요한 조치를 해야 한다.', 2467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4277, '① 법 제244조의5에 따라 피의자와 동석할 수 있는 신뢰관계에 있는 사람과 법 제221조제3항에서 준용하는 법 제163조의2에 따라 피의자 또는 피해자와 동석할 수 있는 신뢰관계에 있는 사람은 피의자 또는 피해자의 직계친족, 형제자매, 배우자, 가족, 동거인, 보호ㆍ교육시설의 보호ㆍ교육담당자 등 피의자 또는 피해자의 심리적 안정과 원활한 의사소통에 도움을 줄 수 있는 사람으로 한다.', 2468);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4278, '② 피의자, 피해자 또는 그 법정대리인이 제1항에 따른 신뢰관계에 있는 사람(이하 "신뢰관계인"이라 한다)의 동석을 신청한 경우 특별사법경찰관은 그 관계를 포함하는 별지 제13호서식 또는 별지 제14호서식의 동석신청서를 제출받거나 조서 또는 수사보고서에 그 관계를 적어야 한다.', 2468);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4279, '③ 제2항의 경우 특별사법경찰관은 신뢰관계인으로 동석할 사람과 피의자 또는 피해자와의 관계를 소명할 수 있는 자료를 제출받아 기록에 편철한다. 다만, 조사의 긴급성 또는 동석의 필요성 등이 현저한 경우에는 예외적으로 동석 조사 이후에 해당 자료를 제출받아 기록에 편철할 수 있다.', 2468);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4280, '④ 특별사법경찰관은 신뢰관계인의 동석으로 인하여 신문이 방해되거나, 수사기밀이 누설되는 등 정당한 사유가 있는 경우에는 동석을 거부할 수 있으며, 신뢰관계인이 피의자신문 또는 피해자 조사를 방해하거나 그 진술의 내용에 부당한 영향을 미칠 수 있는 행위를 하는 등 수사에 현저한 지장을 초래하는 경우에는 피의자신문 또는 피해자 조사 중에도 동석을 제한할 수 있다.', 2468);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4281, '① 특별사법경찰관은 피의자 또는 사건관계인을 조사하기에 앞서 조사 대상자에게 조사의 경위 및 이유를 설명해야 하고, 유리한 자료를 제출할 기회를 주거나, 조사 대상자로부터 피의사실에 대한 의견 및 조사 요구 사항 등을 들을 수 있다.', 2469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4282, '② 특별사법경찰관은 조사과정에서 피의자, 사건관계인 또는 그 변호인이 사실관계 등의 확인을 위해 자료를 제출하는 경우 그 자료를 수사기록에 편철한다.', 2469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4283, '③ 특별사법경찰관은 조사를 종결하기 전에 피의자, 사건관계인 또는 그 변호인에게 자료 또는 의견을 제출할 의사가 있는지를 확인하고, 자료 또는 의견을 제출받은 경우에는 해당 자료 및 의견을 수사기록에 편철한다.', 2469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4284, '① 특별사법경찰관은 법 제244조의4에 따라 조사(신문, 면담 등 명칭을 불문한다. 이하 이 조에서 같다) 과정의 진행경과를 다음 각 호의 구분에 따른 방법으로 기록해야 한다.', 2470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4285, '② 제1항에 따라 조사과정의 진행경과를 기록할 때에는 다음 각 호의 구분에 따른 사항을 구체적으로 적어야 한다.', 2470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4286, null, 2471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4287, '① 특별사법경찰관이 피의자를 신문하고 조서를 작성하는 경우에는 별지 제17호서식 및 별지 제18호서식(피의자를 추가로 신문하는 경우로 한정한다)의 피의자신문조서에 따른다.', 2472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4288, '② 특별사법경찰관이 피의자가 아닌 사람의 진술을 듣고 조서를 작성하는 경우에는 별지 제19호서식 및 별지 제20호서식(피의자가 아닌 사람의 진술을 추가로 듣는 경우로 한정한다)의 진술조서에 따른다.', 2472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4289, '③ 제1항의 피의자신문조서 및 제2항의 진술조서는 진술을 한 피의자 또는 피의자가 아닌 사람(이하 "진술인"이라 한다)에게 열람하게 하거나 읽어 들려주어야 하며, 진술한 대로 기재되지 않았거나 사실과 다른 부분이 있는지를 물어 진술인이 기재 내용의 증감 또는 변경을 청구하는 등 이의를 제기하거나 의견을 진술했을 때에는 이를 조서에 추가로 적어야 한다. 이 경우 진술인이 이의를 제기하였던 부분은 읽을 수 있도록 남겨두어야 한다.', 2472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4290, '④ 진술인이 조서에 대하여 이의나 의견이 없음을 진술한 때에는 진술인으로 하여금 그 취지를 별지 제21호서식 또는 제22호서식(진술인이 외국인인 경우로 한정한다)에 따라 자필로 기재하게 한 후 조서에 편철하고, 간인(間印)을 한 후 기명날인 또는 서명하게 해야 한다.', 2472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4291, '⑤ 법 제243조의2제4항에 따라 변호인의 의견을 기재한 피의자신문조서는 변호인에게 열람하게 한 후 변호인이 그 조서에 기명날인 또는 서명하게 해야 한다.', 2472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4292, '⑥ 특별사법경찰관은 변호인의 신문참여 및 그 제한에 관한 사항을 피의자신문조서에 적어야 한다.', 2472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4293, '⑦ 특별사법경찰관은 피의자 또는 피의자가 아닌 사람의 진술을 들어야 하는 경우에 다음 각 호의 어느 하나에 해당할 때에는 피의자 또는 피의자가 아닌 사람에게 별지 제23호서식에 따라 진술서를 작성하도록 할 수 있다.', 2472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4294, '⑧ 특별사법경찰관은 제7항의 경우 피의자 또는 피의자가 아닌 사람이 자필로 진술서를 작성하도록 해야 하고, 특별사법경찰관리가 대신 진술서를 작성해서는 안 된다.', 2472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4295, '① 특별사법경찰관은 사건관계인이 출석한 경우 지체 없이 조사하고, 부득이한 사유로 조사의 시작이 늦어지거나 조사를 하지 못할 경우에는 그 사유를 설명해야 한다.', 2474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4296, '② 특별사법경찰관은 조사 과정을 녹음 또는 녹화하거나 같은 날 여러 명에 대해 출석요구하는 경우에는 시차를 두고 출석을 요구하는 등 불필요한 출석 요구나 장시간 대기를 방지해야 한다.', 2474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4297, '③ 특별사법경찰관은 피의자와 사건관계인의 대질조사는 불가피한 사정이 있고 사건관계인이 동의한 경우에만 할 수 있다.', 2474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4298, '④ 특별사법경찰관은 사건관계인을 조사할 때에는 폭언 또는 강압적이거나 모멸감을 주거나 공정성을 의심받을 수 있는 언행을 해서는 안 되고, 사생활에 대한 조사는 수사상 반드시 필요한 경우만 할 수 있다.', 2474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4299, '① 특별사법경찰관은 피의자 또는 참고인에 대한 조서를 작성할 때에는 필요한 경우 그 조사과정을 영상녹화할 수 있다.', 2476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4300, '② 특별사법경찰관은 조사과정을 영상녹화하는 경우 해당 조사의 시작부터 피조사자가 조서에 기명날인 또는 서명을 마치는 시점까지의 전 과정을 영상녹화해야 하며, 조사를 시작한 후에 영상녹화를 할 필요가 있게 된 경우에는 그 시점에서 진행 중인 조사를 종료하고, 그 다음 조사의 시작부터 조서에 피조사자가 서명날인 또는 서명을 마치는 시점까지의 전 과정을 영상녹화해야 한다.', 2476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4301, '③ 제2항에도 불구하고 특별사법경찰관은 조사를 마친 후 조서 정리에 장시간을 요하는 경우에는 조서정리과정을 영상녹화하지 않고, 조서 열람 시부터 영상녹화를 재개할 수 있다.', 2476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4302, '④ 특별사법경찰관은 피의자에 대한 조사과정을 영상녹화하는 경우 피의자에게 다음 각 호의 사항을 고지해야 한다.', 2476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4303, '⑤ 특별사법경찰관은 참고인에 대한 조사과정을 영상녹화하는 경우 별지 제25호서식의 영상녹화 동의서에 따라 영상녹화에 대한 동의 여부를 확인하고, 제4항제1호, 제2호 및 제4호의 사항을 고지해야 한다.', 2476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4304, '⑥ 특별사법경찰관은 영상녹화를 할 때에는 조사실 전체를 확인할 수 있도록 하고, 피조사자의 얼굴과 음성을 식별할 수 있도록 해야 한다.', 2476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4305, '⑦ 특별사법경찰관은 피의자에 대한 조사과정을 영상녹화하는 경우 법 제243조에 따라 참여자를 참여하게 해야 한다. 이 경우, 참여자는 반드시 조사실에 동석해야 한다.', 2476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4306, '① 특별사법경찰관은 영상녹화를 실시한 경우 영상녹화용 컴퓨터에 저장된 영상녹화파일을 이용하여 영상녹화물(CD, DVD 등) 1개를 제작하고, 피조사자의 기명날인 또는 서명을 받아 피조사자 또는 변호인의 면전에서 봉인하여 수사기록에 편철한다.', 2477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4307, '② 특별사법경찰관은 영상녹화물을 제작한 후 영상녹화용 컴퓨터에 저장되어 있는 영상녹화파일을 데이터베이스 서버에 전송하여 보관할 수 있다.', 2477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4308, '③ 특별사법경찰관은 제1항의 영상녹화물이 손상 또는 분실 등으로 인하여 사용될 수 없게 된 경우에는 데이터베이스 서버에 저장되어 있는 영상녹화파일을 이용하여 다시 영상녹화물을 제작할 수 있다.', 2477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4309, '① 특별사법경찰관은 수사상 필요하다고 인정되는 경우에는 범죄현장이나 그 밖의 장소에 가서 실황을 조사해야 한다.', 2479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4310, '② 특별사법경찰관은 제1항의 조사를 하였을 때에는 별지 제26호서식에 따라 실황조사서를 작성해야 한다.', 2479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4311, '① 특별사법경찰관리는 영장, 감정유치장, 허가장, 허가서 및 요청서 등(이하 "영장등"이라 한다)을 신속하고 정확하게 집행해야 한다.', 2481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4312, '② 특별사법경찰관리가 영장등을 집행할 때에는 피의자나 사건관계인의 신체와 명예를 보전(保全)하는데 유의해야 한다.', 2481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4313, '③ 영장은 검사의 서명ㆍ날인 또는 집행지휘서에 따라 집행한다.', 2481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4314, '④ 특별사법경찰관리는 법 제81조제1항 단서에 따라 재판장ㆍ수명법관 또는 수탁판사가 구속영장의 집행을 지휘할 때에는 즉시 구속영장을 집행해야 한다.', 2481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4315, '⑤ 특별사법경찰관은 피의자를 체포하거나 구속할 때에는 법 제200조의5(법 제209조에서 준용하는 경우를 포함한다)에 따라 피의자에게 피의사실의 요지, 체포ㆍ구속의 이유와 변호인을 선임할 수 있음을 말하고, 변명할 기회를 주어야 하며, 진술거부권을 알려주어야 한다.', 2481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4316, '⑥ 제5항에 따라 피의자에게 알려주어야 하는 진술거부권의 내용은 법 제244조의3제1항제1호부터 제3호까지의 사항으로 한다.', 2481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4317, '⑦ 특별사법경찰관은 제5항에 따라 피의자에게 진술거부권 등의 권리를 알려준 경우에는 피의자로부터 별지 제28호서식의 권리 고지 확인서를 받아 사건기록에 편철해야 한다. 다만, 피의자가 확인서에 기명날인 또는 서명하기를 거부할 때에는 별지 제28호서식의 권리 고지 확인서의 끝부분에 그 사유를 기재하고 기명날인 또는 서명해야 한다.', 2481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4318, '⑧ 특별사법경찰관리는 영장을 집행할 때에는 법 제89조 및 제90조를 준수해야 한다.', 2481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4319, '⑨ 특별사법경찰관은 제1항에 따라 체포ㆍ구속영장을 집행한 때에는 별지 제29호서식의 체포ㆍ구속영장 집행원부에 해당 사항을 기재해야 한다.', 2481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4320, '① 특별사법경찰관은 법 제200조의2에 따라 검사에게 체포영장을 신청하려는 경우에는 별지 제30호서식의 체포영장신청서로 신청해야 한다.', 2482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4321, '② 특별사법경찰관은 제1항에 따라 체포영창을 신청하는 경우에는 해당 사항을 별지 제31호서식의 체포영장신청부에 기재해야 한다.', 2482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4322, null, 2483);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4323, '① 특별사법경찰관이 법 제200조의3제1항에 따라 긴급체포를 하는 경우에는 피의자의 연령ㆍ경력ㆍ범죄성향, 범죄의 경중ㆍ양상, 그 밖의 여러 사정을 고려하여 인권의 침해가 없도록 신중을 기해야 한다.', 2484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4324, '② 특별사법경찰관이 피의자를 긴급체포한 때에는 즉시 별지 제32호서식의 긴급체포서를 작성하고 별지 제33호서식의 긴급체포원부에 그 내용을 적어야 한다.', 2484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4325, '③ 특별사법경찰관은 긴급체포 후 12시간 이내에 관할 지방검찰청 또는 지청의 검사에게 긴급체포를 승인하여 줄 것을 건의해야 한다. 다만, 기소중지된 피의자를 해당 기관 또는 관서가 위치하는 특별시ㆍ광역시ㆍ특별자치시ㆍ도 또는 특별자치도 외의 지역이나 「연안관리법」 제2조제2호나목의 바다에서 긴급체포한 때에는 긴급체포 후 24시간 내에 긴급체포에 대한 승인건의를 할 수 있다.', 2484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4326, '④ 특별사법경찰관이 제3항에 따라 긴급체포에 대한 승인을 건의할 때에는 범죄사실의 요지, 긴급체포의 일시ㆍ장소, 긴급체포의 사유, 체포를 계속해야 하는 사유 등을 포함하는 별지 제34호서식의 긴급체포승인건의서에 따른다. 다만, 긴급한 경우에는 형사사법정보시스템 또는 팩스를 이용하여 긴급체포에 대한 승인건의를 할 수 있다.', 2484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4327, '⑤ 특별사법경찰관은 긴급체포한 피의자를 석방했을 때에는 별지 제33호서식의 긴급체포원부에 석방일시와 석방사유를 적어야 한다.', 2484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4328, '⑥ 특별사법경찰관이 피의자를 긴급체포하는 경우의 진술거부권 등 권리 고지에 관하여는 제54조제5항부터 제8항까지의 규정을 준용한다.', 2484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4329, '① 특별사법경찰관리가 현행범인을 체포한 때에는 체포의 경위를 상세히 적은 별지 제35호서식의 현행범인체포서를 작성해야 한다.', 2485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4330, '② 특별사법경찰관리가 현행범인을 인도받은 경우에는 현행범인을 체포한 사람으로부터 그의 성명ㆍ주민등록번호ㆍ직업ㆍ주거, 체포의 일시ㆍ장소ㆍ사유를 듣고 별지 제36호서식의 현행범인인수서를 작성해야 한다.', 2485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4331, '③ 특별사법경찰관리가 현행범인을 체포하거나 현행범인을 인도받는 경우에는 특히 인권의 침해가 없도록 신중을 기해야 한다.', 2485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4332, '④ 특별사법경찰관이 현행범인을 체포하거나 인수하는 경우의 진술거부권 등 권리 고지에 관하여는 제54조제5항부터 제8항까지의 규정을 준용한다.', 2485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4333, '① 특별사법경찰관리는 현행범인을 체포하거나 체포된 현행범인을 인수한 경우에는 조사가 현저히 곤란하다고 인정되는 경우가 아니면 지체 없이 조사하고, 계속 체포하거나 구금할 필요가 없다고 인정될 때에는 즉시 석방해야 한다.', 2486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4334, '② 특별사법경찰관은 제1항에 따라 현행범인을 석방했을 때에는 지체 없이 검사에게 보고하고, 석방일시와 석방사유를 기재한 별지 제37호서식의 피의자 석방보고서를 작성하여 수사기록에 편철해야 한다.', 2486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4335, '③ 체포한 현행범인을 석방할 때에는 별지 제38호서식의 현행범인체포원부에 석방일시와 석방사유를 적어야 한다.', 2486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4336, '① 특별사법경찰관이 검사에게 구속영장을 신청하는 경우에는 다음 각 호의 구분에 따른 신청서와 서류를 제출해야 한다.', 2487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4337, '② 특별사법경찰관은 피의자에 대하여 구속영장을 신청할 때 법 제209조에서 준용하는 법 제70조제2항의 필요적 고려사항이 있는 경우에는 제1항 각 호의 구속영장신청서에 이를 기재한다.', 2487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4338, '③ 특별사법경찰관은 검사로부터 법 제201조의2제3항 전단에 따른 심문기일과 장소를 통지받은 때에는 검사의 지휘를 받아 지정된 기일과 장소에 체포된 피의자를 출석시켜야 한다.', 2487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4339, '④ 특별사법경찰관은 제1항에 따라 구속영장을 신청한 경우에는 별지 제43호서식의 구속영장신청부에 해당 사항을 기재해야 한다.', 2487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4340, '① 특별사법경찰관은 법 제200조의6 또는 제209조에서 준용하는 법 제87조에 따라 체포ㆍ구속의 통지를 하는 경우에는 별지 제44호서식의 체포ㆍ구속 통지서에 따른다.', 2488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4341, '② 특별사법경찰관은 제1항에 따른 통지를 하는 경우에는 각 호의 구분에 따른 사람에게 체포ㆍ구속한 때부터 늦어도 24시간 내에 서면으로 사건명, 체포ㆍ구속의 일시ㆍ장소, 범죄사실의 요지, 체포ㆍ구속의 이유와 변호인을 선임할 수 있음을 통지해야 한다.', 2488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4342, '③ 특별사법경찰관은 제2항제2호의 경우에 법 제30조제2항에서 규정한 사람이 없어 체포ㆍ구속의 통지를 할 수 없는 경우에는 그 취지를 수사보고서에 적어 수사기록에 편철해야 한다.', 2488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4343, '④ 특별사법경찰관은 긴급을 요할 때에는 전화ㆍ모사전송 또는 이에 상응하는 방법으로 체포ㆍ구속의 통지를 할 수 있다. 이 경우 체포ㆍ구속한 때부터 늦어도 24시간 내에 다시 서면으로 체포ㆍ구속의 통지를 해야 한다.', 2488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4344, '⑤ 제1항에 따른 체포ㆍ구속의 통지서 사본은 수사기록에 편철해야 한다.', 2488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4345, '⑥ 법 제214조의2제2항에 따라 법 제214조의2제1항에서 규정한 사람 중에서 피의자가 지정한 사람에게 적부심사를 청구할 수 있음을 통지하는 경우에도 제1항부터 제3항까지의 규정을 준용한다.', 2488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4346, '① 특별사법경찰관은 법 제214조의2제1항에서 규정한 사람이 체포ㆍ구속영장의 등본을 교부하여 줄 것을 청구하는 경우에는 그 등본을 교부해야 한다.', 2489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4347, '② 특별사법경찰관은 제1항에 따라 체포ㆍ구속영장 등본을 교부했을 때에는 별지 제45호서식의 체포ㆍ구속영장등본교부대장을 작성해야 한다.', 2489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4348, '① 특별사법경찰관리는 변호인 또는 변호인이 되려는 사람이 체포ㆍ구속된 피의자와의 접견, 서류ㆍ물건의 수수(授受) 또는 의사에 의한 피의자의 진료를 요청할 때에는 친절하게 응해야 한다.', 2490);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4349, '② 특별사법경찰관리는 변호인 또는 변호인이 되려는 사람이 아닌 사람이 체포ㆍ구속된 피의자와의 접견, 서류ㆍ물건의 수수 또는 의사에 의한 피의자의 진료를 요청하는 경우 법 제200조의6에서 준용하는 법 제91조에 따라 피의자 접견 등을 금지하는 결정이 없는 때에는 제1항에 준하여 처리해야 한다.', 2490);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4350, '③ 제1항에 따른 접견 등은 접촉차단시설이 없는 장소에서 하도록 해야 하며, 제2항에 따른 접견 등은 접견 장소 부족, 접견시설의 질서 유지, 접견 사무의 장애 등 특별한 사유가 없으면 유치장 외의 방실에서 하도록 해야 한다.', 2490);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4351, '④ 특별사법경찰관리는 제1항 및 제2항에 따른 접견 등의 신청을 받아 접견 등을 하도록 했을 때에는 다음 각 호의 구분에 따른 서류를 작성해야 한다.', 2490);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4352, '① 특별사법경찰관은 피의자를 유치할 때에 위험물 또는 휴대금품을 보관하는 경우에는 유치인에게 별지 제49호서식의 임치증명서를 교부해야 한다.', 2491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4353, '② 특별사법경찰관은 피의자를 유치한 경우에는 별지 제50호서식의 임치 및 급식상황표에 임치금품의 처리현황, 급식상황 등을 기재해야 한다.', 2491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4354, '③ 특별사법경찰관은 유치인에게 자기 용도를 위한 차입물품을 사용하는 것을 허가하는 경우에는 별지 제51호서식의 물품차입부에 해당 사항을 기재해야 한다.', 2491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4355, '① 특별사법경찰관은 법 제200조의2 또는 제212조에 따라 체포한 피의자나 법 제200조의3에 따라 긴급체포한 피의자 또는 구속한 피의자를 석방할 때에는 미리 검사의 지휘를 받아야 한다.', 2494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4356, '② 특별사법경찰관은 제1항에 따른 검사의 석방지휘가 있을 때에는 즉시 체포 또는 긴급체포한 피의자나 구속한 피의자를 석방해야 한다.', 2494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4357, '③ 특별사법경찰관은 피의자를 석방했을 때에는 그 사실을 다음 각 호의 구분에 따른 서식에 따라 검사에게 지체 없이 보고해야 하며, 석방일시와 석방사유를 기재한 서면을 작성하여 수사기록에 편철해야 한다.', 2494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4358, '④ 특별사법경찰관은 제1항에 따라 석방을 건의하는 경우에는 별지 제53호서식의 피의자 석방 건의서로 한다. 다만, 긴급을 요하는 경우에는 전화, 팩스, 전자우편, 그 밖의 상당한 방법으로 석방을 건의할 수 있다.', 2494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4359, '① 특별사법경찰관은 법 제198조의2에 따른 검사의 체포ㆍ구속장소 감찰과 관련하여 별지 제54호서식의 체포ㆍ구속인명부를 작성하여 관리해야 한다.', 2495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4360, '② 특별사법경찰관은 검사가 법 제198조의2에 따라 체포ㆍ구속장소를 감찰한 후 체포 또는 구속된 피의자의 석방을 명하거나 사건을 송치할 것을 명한 때에는 즉시 피의자를 석방하거나 사건을 송치하고, 피의자석방명령서 또는 사건송치명령서를 수사기록에 편철해야 한다.', 2495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4361, '① 특별사법경찰관은 압수ㆍ수색 또는 검증영장을 신청하는 경우 압수ㆍ수색 또는 검증의 범위를 범죄 혐의의 소명에 필요한 최소한으로 정해야 하고, 수색 또는 검증할 장소ㆍ신체ㆍ물건 및 압수할 물건 등을 구체적으로 특정해야 한다.', 2497);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4362, '② 특별사법경찰관은 검사에게 압수ㆍ수색 또는 검증영장을 신청할 때에는 다음 각 호의 구분에 따른 신청서를 검사에게 제출해야 한다.', 2497);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4363, '③ 특별사법경찰관은 제2항에 따라 압수ㆍ수색 또는 검증영장을 신청했을 때에는 별지 제58호서식의 압수ㆍ수색ㆍ검증영장 신청부를 작성해야 한다.', 2497);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4364, '① 특별사법경찰관은 법 제219조에서 준용하는 법 제118조에 따라 영장을 제시할 때에는 피압수자에게 법관이 발부한 영장에 따른 압수ㆍ수색 또는 검증이라는 사실과 영장에 기재된 범죄사실 및 수색 또는 검증할 장소ㆍ신체ㆍ물건, 압수할 물건 등을 명확히 알리고, 피압수자가 해당 영장을 열람할 수 있도록 해야 한다.', 2498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4365, '② 압수ㆍ수색 또는 검증의 처분을 받는 자가 여럿인 경우에는 모두에게 개별적으로 영장을 제시해야 한다.', 2498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4366, '① 특별사법경찰관은 법 제219조에서 준용하는 법 제106조제3항에 따라 컴퓨터용 디스크 및 그 밖에 이와 비슷한 정보저장매체(이하 이 항에서 "정보저장매체등"이라 한다)에 기억된 정보(이하 "전자정보"라 한다)를 압수하는 경우에는 해당 정보저장매체등의 소재지에서 수색 또는 검증한 후 범죄사실과 관련된 전자정보의 범위를 정하여 출력하거나 복제하는 방법으로 한다.', 2499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4367, '② 제1항에도 불구하고 제1항에 따른 압수 방법의 실행이 불가능하거나 그 방법으로는 압수의 목적을 달성하는 것이 현저히 곤란한 경우에는 압수ㆍ수색 또는 검증 현장에서 정보저장매체등에 들어 있는 전자정보 전부를 복제하여 그 복제본을 정보저장매체등의 소재지 외의 장소로 반출할 수 있다.', 2499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4368, '③ 제1항 및 제2항에도 불구하고 제1항 및 제2항에 따른 압수 방법의 실행이 불가능하거나 그 방법으로는 압수의 목적을 달성하는 것이 현저히 곤란한 경우에는 피압수자 또는 법 제123조에 따라 압수ㆍ수색영장을 집행할 때 참여하게 해야 하는 사람(이하 "피압수자등"이라 한다)이 참여한 상태에서 정보저장매체등의 원본을 봉인(封印)하여 정보저장매체등의 소재지 외의 장소로 반출할 수 있다.', 2499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4369, '① 특별사법경찰관은 전자정보의 탐색ㆍ복제ㆍ출력을 완료한 경우에는 지체 없이 피압수자등에게 압수한 전자정보의 목록을 교부해야 한다.', 2500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4370, '② 특별사법경찰관은 제1항의 목록에 포함되지 않은 전자정보가 있는 경우에는 해당 전자정보를 지체 없이 삭제 또는 폐기하거나 반환해야 한다. 이 경우 별지 제59호서식의 전자정보 삭제ㆍ폐기 또는 반환확인서를 작성하여 피압수자등에게 교부해야 한다.', 2500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4371, '③ 특별사법경찰관은 전자정보의 복제본을 취득하거나 전자정보를 복제할 때에는 해시값(파일의 고유값으로서 일종의 전자지문을 말한다)을 확인하거나 압수ㆍ수색 또는 검증의 과정을 촬영하는 등 전자적 증거의 동일성과 무결성(無缺性)을 보장할 수 있는 적절한 방법과 조치를 취해야 한다.', 2500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4372, '④ 특별사법경찰관은 압수ㆍ수색 또는 검증의 전 과정에 걸쳐 피압수자등이나 변호인의 참여권을 보장해야 하며, 피압수자등과 변호인이 참여를 거부하는 경우에는 신뢰성과 전문성을 담보할 수 있는 상당한 방법으로 압수ㆍ수색 또는 검증을 해야 한다.', 2500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4373, '⑤ 특별사법경찰관은 제4항에 따라 참여한 피압수자등이나 변호인이 압수 대상 전자정보와 사건의 관련성에 관하여 의견을 제시한 때에는 이를 조서에 적어야 한다.', 2500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4374, '⑥ 제72조제2항 또는 제3항에 따라 전자정보 전부를 복제하여 그 복제본을 반출하거나 정보저장매체등 원본을 반출하는 경우에는 피압수자등에게 전자정보의 탐색ㆍ복제ㆍ출력 절차에 참여할 수 있음을 고지한 후 다음 각 호의 구분에 따른 확인서를 작성하여 피압수자등의 서명을 받아야 한다. 다만, 서명을 받기 어려운 사정이 있는 경우에는 그 사유를 해당 확인서에 기재하고 기록에 편철한다.', 2500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4375, '① 특별사법경찰관은 증거물이나 몰수할 물건을 압수한 경우에는 별지 제62호서식의 압수조서와 별지 제63호서식의 압수목록을 작성해야 한다.', 2501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4376, '② 압수조서에는 압수의 일시ㆍ장소, 압수의 경위 등을, 압수목록에는 압수물건의 품종ㆍ수량 등을 각각 구체적으로 적어야 한다.', 2501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4377, '③ 제1항에도 불구하고 피의자신문조서ㆍ진술조서ㆍ검증조서 또는 실황조사서에 압수의 취지를 기재하여 압수조서의 작성을 갈음할 수 있다.', 2501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4378, '④ 특별사법경찰관이 법 제218조에 따라 유류(遺留)한 물건 또는 임의로 제출하는 물건을 압수하여 압수조서와 압수목록을 작성하는 경우에는 제1항 및 제2항을 준용한다.', 2501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4379, '① 특별사법경찰관리는 멸실할 우려가 있는 증거물은 특히 보전에 유의해야 하며, 검증조서 또는 다른 조서에 그 성질과 형상을 상세히 기재하거나 촬영해야 한다.', 2502);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4380, '② 특별사법경찰관은 증거물이 훼손되거나 형상이 변경될 우려가 있는 검증이나 감정을 위촉할 때에는 검증조서 또는 다른 조서에 그 성질과 형상을 상세히 기재하거나 촬영하는 등 변경 전의 형상을 알 수 있도록 특히 유의해야 한다.', 2502);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4381, '① 특별사법경찰관리가 수색을 한 경우에는 수색의 일시ㆍ장소, 참여인 등을 포함하여 별지 제64호서식의 수색조서를 작성해야 한다.', 2503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4382, '② 특별사법경찰관리는 수색을 한 결과 증거물 또는 몰수할 물건이 없을 때에는 그 처분을 받는 자에게 그 취지를 기재한 별지 제65호서식의 수색결과 증명서를 교부해야 한다.', 2503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4383, '① 특별사법경찰관은 법 제218조의2제4항에서 준용하는 같은 조 제1항부터 제3항까지에 따른 압수물의 환부 또는 가환부 처분을 하거나 법 제219조에서 준용하는 법 제130조, 제132조 및 제134조에 따라 압수물의 보관, 폐기, 대가보관 또는 피해자환부의 처분을 하려는 경우에는 그 처분유형과 처분사유를 기재한 다음 각 호의 구분에 따른 지휘건의서를 검사에게 제출하여 압수물의 처분에 대한 검사의 지휘를 받아야 한다.', 2505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4384, '② 특별사법경찰관이 법 제130조제1항에 따라 압수물을 다른 사람에게 보관하게 하는 경우에는 압수물에 사건명, 피의자의 성명, 압수목록에 기재한 순위ㆍ번호를 표시하고, 보관자로부터 별지 제70호서식의 압수물 보관 서약서를 받아 사건기록에 첨부해야 한다.', 2505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4385, '③ 특별사법경찰관은 압수물이 유가증권인 경우에는 지체 없이 별지 제71호서식의 유가증권 원형보존 등 지휘건의서를 검사에게 제출하여 원형보존 또는 환전보관 여부에 관한 검사의 지휘를 받아야 한다.', 2505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4386, '④ 특별사법경찰관은 법 제130조제2항 또는 제3항에 따라 압수물을 폐기하는 경우에는 별지 제72호서식의 폐기조서를 작성하고 압수물 사진 및 압수물 폐기에 관한 증빙자료를 수사기록에 첨부해야 한다.', 2505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4387, '⑤ 특별사법경찰관이 법 제133조에 따라 압수물을 환부ㆍ가환부하거나 법 제134조에 따라 압수장물을 피해자환부하는 경우에는 피해자, 피의자 또는 변호인에게 지체 없이 통지를 한 후 신속히 환부해야 한다.', 2505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4388, '① 특별사법경찰관이 「통신비밀보호법」 제6조제2항에 따라 검사에게 통신제한조치에 대한 허가를 신청하는 경우에는 별지 제73호서식의 통신제한조치허가 신청서에 따르고, 같은 조 제7항 단서에 따라 통신제한조치기간의 연장허가 청구를 신청하는 경우에는 별지 제74호서식의 통신제한조치기간 연장허가 신청서에 따른다.', 2506);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4389, '② 특별사법경찰관은 제1항에 따라 검사가 통신제한조치에 대한 허가를 신청하거나 통신제한조치의 연장 청구를 신청하는 경우에는 별지 제75호서식의 통신제한조치허가 신청부에 해당 사항을 기재한다.', 2506);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4390, '③ 특별사법경찰관은 「통신비밀보호법」 제8조제3항 본문에 따라 긴급통신제한조치에 대하여 검사에게 지휘를 건의하는 경우에는 별지 제76호서식의 긴급통신제한조치 지휘건의서에 따르고, 같은 항 단서에 따라 검사에게 승인을 건의하는 경우에는 별지 제77호서식의 긴급통신제한조치 승인건의서에 따른다.', 2506);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4391, '④ 특별사법경찰관은 「통신비밀보호법」 제8조제1항에 따라 긴급통신제한조치를 하는 경우에는 별지 제78호서식의 긴급검열(감청)서에 따른다. 이 경우 특별사법경찰관은 별지 제79호서식의 긴급통신제한조치대장을 작성하여 소속기관에 비치해야 한다.', 2506);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4392, '⑤ 특별사법경찰관이 「통신비밀보호법」 제8조제2항에 따라 긴급통신제한조치를 한 후에 검사에게 허가청구를 신청하는 경우에는 별지 제80호서식의 통신제한조치허가 신청서(사후)에 따른다.', 2506);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4393, '⑥ 특별사법경찰관이 「통신비밀보호법」 제8조제5항에 따라 긴급통신제한조치를 한 후에 법원의 허가를 받을 필요가 없어 긴급통신제한조치 사실을 법원에 통보하는 경우에는 별지 제81호서식의 긴급통신제한조치통보서에 따른다. 이 경우 특별사법경찰관은 별지 제82호서식의 긴급통신제한조치 통보서 발송부를 작성하여 소속기관에 비치해야 한다.', 2506);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4394, '① 특별사법경찰관이 「통신비밀보호법」 제9조제1항 후단에 따라 통신제한조치 집행을 위탁하는 경우에는 별지 제83호서식의 통신제한조치 집행위탁 의뢰서에 따른다.', 2507);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4395, '② 특별사법경찰관이 집행위탁한 통신제한조치의 허가기간이 연장된 경우에는 별지 제84호서식의 통신제한조치 기간연장 통지서로 수탁기관에 통지한다.', 2507);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4396, '③ 특별사법경찰관은 제1항 및 제2항에 따라 통신제한조치 집행을 위탁하거나 통신제한조치의 허가기간 연장을 통지한 경우에는 별지 제85호서식의 통신제한조치 집행위탁허가 신청부에 해당 사항을 기재해야 한다.', 2507);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4397, '④ 통신제한조치를 집행한 특별사법경찰관은 별지 제86호서식의 통신제한조치 집행조서를 작성해야 한다.', 2507);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4398, '⑤ 특별사법경찰관은 통신제한조치를 집행한 후 수사 또는 내사한 사건을 종결하는 경우 그 결과를 별지 제87호서식의 통신제한조치 집행결과 보고서에 따라 검사에게 보고해야 한다.', 2507);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4399, '⑥ 다른 관서에서 통신제한조치를 집행한 사건을 이송받아 내사한 후 내사를 종결하는 경우 내사를 종결한 관서는 허가서를 청구한 검찰청에 집행결과를 검사에게 보고한 후 허가서를 신청한 관서에 사건처리결과를 통보해야 한다.', 2507);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4400, '⑦ 특별사법경찰관은 통신제한조치의 집행이 필요 없게 되어 통신제한조치를 중단하려는 경우에는 별지 제88호서식의 통신제한조치 집행중지통지서에 따라 이를 수탁기관에 통지한다.', 2507);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4401, '① 특별사법경찰관은 「통신비밀보호법」에 따른 통신제한조치 집행으로 취득한 자료를 같은 법 제6조 및 제8조에 따른 통신제한조치허가서, 별지 제86호서식의 통신제한조치 집행조서 및 같은 법 제12조의2제4항에 따라 법원이 발부한 승인서와 함께 봉인한 후 통신제한조치 허가번호 및 보존기간을 표기하여 별도로 보관하고, 수사담당자 외의 사람이 열람할 수 없도록 해야 한다.', 2508);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4402, '② 특별사법경찰관은 통신제한조치를 집행하고 제18조에 따른 범죄인지서를 작성하지 않았을 때에는 그 집행으로 취득한 자료 등은 보존기간이 지난 후 검사의 지휘를 받아 즉시 폐기해야 한다.', 2508);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4403, '① 특별사법경찰관이 「통신비밀보호법」 제9조의2제2항에 따라 통신제한조치를 집행한 사실 등을 통지하는 경우에는 별지 제89호서식의 통신제한조치 집행사실 통지서에 따른다. 이 경우 특별사법경찰관은 별지 제90호서식의 통신제한조치 집행사실 통지부에 해당 사항을 기재해야 한다.', 2509);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4404, '② 특별사법경찰관은 「통신비밀보호법」 제9조의2제5항에 따라 통지유예에 대한 관할 지방검찰청 검사장의 승인을 신청하는 경우에는 별지 제91호서식의 통신제한조치 집행사실 통지유예 승인신청서에 따른다. 이 경우 특별사법경찰관은 별지 제92호서식의 통신제한조치 집행사실통지 유예승인신청부에 해당 사항을 기재해야 한다.', 2509);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4405, '③ 특별사법경찰관은 「통신비밀보호법」 제9조의2제6항에 따라 통지유예의 사유가 해소된 날부터 30일 이내에 유예했던 통지를 한 경우에는 그 사실을 별지 제93호서식의 통신제한조치 집행사실 통지보고서에 따라 관할 지방검찰청 검사장에게 보고해야 한다.', 2509);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4406, '① 특별사법경찰관이 「통신비밀보호법」 제13조제1항에 따라 통신사실 확인자료제공을 요청하는 경우에는 별지 제98호서식의 통신사실 확인자료제공 요청서에 따르고, 별지 제99호서식의 통신사실 확인자료제공 요청 집행대장에 해당 사항을 기재해야 한다.', 2512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4407, '② 제1항에 따라 통신사실 확인자료제공을 요청한 특별사법경찰관은 별지 제100호서식의 통신사실 확인자료제공 요청 집행조서를 작성해야 한다.', 2512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4408, '③ 특별사법경찰관은 제1항에 따라 전기통신사업자로부터 통신사실 확인자료를 제공받은 경우에는 이를 별지 제101호서식의 통신사실 확인자료 회신대장에 기재해야 한다.', 2512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4409, '④ 특별사법경찰관은 통신사실 확인자료제공 요청이 필요없게 된 경우에는 별지 제102호서식의 통신사실 확인자료제공 요청중지통지서로 해당 전기통신사업자에게 이를 통지해야 한다.', 2512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4410, '⑤ 특별사법경찰관은 통신사실 확인자료제공을 요청한 후 수사 또는 내사한 사건을 종결하는 경우 그 결과를 별지 제103호서식의 통신사실 확인자료제공 요청 집행결과보고서에 따라 검사에게 보고해야 한다.', 2512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4411, '⑥ 다른 관서에서 통신사실 확인자료제공을 요청한 사건을 이송받아 내사한 후 내사를 종결하는 경우 내사를 종결한 관서는 허가서를 청구한 검찰청에 집행결과를 검사에게 보고한 후 허가서를 신청한 관서에 사건처리결과를 통보해야 한다.', 2512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4412, '① 특별사법경찰관이 「통신비밀보호법」 제13조제3항 본문에 따른 통신사실 확인자료제공 요청허가를 검사에게 신청하는 경우에는 별지 제104호서식의 통신사실 확인자료제공 요청허가 신청서에 따른다.', 2513);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4413, '② 특별사법경찰관은 제1항 및 제87조제2항에 따라 통신사실 확인자료제공 요청허가를 신청하는 경우에는 별지 제105호서식의 통신사실 확인자료제공 요청허가 신청부에 해당 사항을 기재해야 한다.', 2513);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4414, '① 특별사법경찰관이 「통신비밀보호법」 제13조제3항 단서에 따라 긴급 통신사실 확인자료제공을 요청하는 경우에는 별지 제106호서식의 긴급 통신사실 확인자료제공 요청서에 따른다. 이 경우 특별사법경찰관은 별지 제107호서식의 긴급 통신사실 확인자료제공 요청대장에 해당 사항을 기재해야 한다.', 2514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4415, '② 특별사법경찰관이 「통신비밀보호법」 제13조제3항 단서에 따라 통신사실 확인자료제공 요청허가를 검사에게 신청하는 경우에는 별지 제108호서식의 통신사실 확인자료제공 요청허가 신청서(사후)에 따른다.', 2514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4416, '① 특별사법경찰관이 「통신비밀보호법」 제13조의3제1항에 따라 통신사실 확인자료제공의 대상이 된 당사자에게 통지를 하는 경우에는 별지 제109호서식의 통신사실 확인자료제공 요청 집행사실 통지서에 따른다. 이 경우 특별사법경찰관은 별지 제110호서식의 통신사실 확인자료제공 요청 집행사실 통지부에 해당 사항을 기재해야 한다.', 2515);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4417, '② 특별사법경찰관은 「통신비밀보호법」 제13조의3제3항에 따라 통지유예에 대하여 관할 지방검찰청 검사장의 승인을 신청하는 경우에는 별지 제111호서식의 통신사실 확인자료제공 요청 집행사실 통지유예 승인신청서에 따른다. 이 경우 특별사법경찰관은 별지 제112호서식의 통신사실 확인자료제공 요청 집행사실 통지유예 승인신청부에 해당 사항을 기재해야 한다.', 2515);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4418, '③ 특별사법경찰관은 「통신비밀보호법」 제13조의3제4항에 따라 통지유예의 사유가 해소된 날부터 30일 이내에 유예했던 통지를 한 경우에는 그 사실을 별지 제113호서식의 통신제한조치 집행사실 통지 보고서에 따라 관할 지방검찰청 검사장에게 보고해야 한다.', 2515);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4419, '① 특별사법경찰관리가 검사에게 법 제221조의3제1항에 따른 감정유치의 청구를 신청하는 경우에는 별지 제114호서식의 감정유치장 신청서에 따른다.', 2516);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4420, '② 특별사법경찰관리가 검사에게 법 제221조의4제1항 및 제2항에 따른 감정처분허가의 청구를 신청하는 경우에는 별지 제115호서식의 감정처분허가장 신청서에 따른다.', 2516);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4421, '③ 특별사법경찰관리가 법 제221조제2항에 따라 감정을 위촉하는 경우에는 별지 제116호서식의 감정위촉서에 따른다.', 2516);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4422, '④ 특별사법경찰관리가 법 제221조의4제3항에 따라 발부된 감정처분허가장에 따라 감정을 위촉하는 경우에는 별지 제117호서식의 감정위촉서에 따른다.', 2516);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4423, '① 특별사법경찰관은 체포ㆍ구속영장의 유효기간 내에 영장의 집행에 착수하지 못했거나, 그 밖의 사유로 영장의 집행이 불가능하거나 불필요하게 되었을 때에는 즉시 해당 영장을 법원에 반환해야 한다. 이 경우 체포ㆍ구속영장이 여러 통 발부된 경우에는 모두 반환해야 한다.', 2517);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4424, '② 특별사법경찰관은 제1항에 따라 체포ㆍ구속영장을 반환하는 경우에는 별지 제118호서식의 영장반환 보고서에 발행통수와 집행불능 등 영장반환 사유를 적어 검사에게 제출하고, 그 사본을 사건기록에 편철한다.', 2517);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4425, '① 특별사법경찰관이 고소나 고발에 의하여 범죄를 수사하는 경우에는 고소나 고발이 있은 날부터 2개월 이내에 수사를 완료해야 한다.', 2522);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4426, '② 제1항에 따른 기간에 수사를 완료하지 못한 경우에는 관할 지방검찰청 또는 지청의 검사의 지휘를 받아야 한다.', 2522);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4427, null, 2523);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4428, '① 소년사건을 수사할 때에는 범죄의 원인 및 동기와 그 소년의 성격, 경력, 교육 정도, 가정상황, 교우관계, 그 밖의 환경 등을 상세히 조사하여 별지 제121호서식의 소년환경 조사서를 작성해야 한다.', 2526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4429, '② 소년의 심신에 이상이 있다고 인정되는 때에는 지체 없이 의사의 진단을 받도록 해야 한다.', 2526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4430, '① 특별사법경찰관은 청각 및 언어장애인이나 그 밖에 의사소통이 어려운 장애인을 조사하는 경우에는 수화ㆍ문자통역을 제공하거나 의사소통을 도울 수 있는 사람을 참여시켜야 한다.', 2529);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4431, '② 특별사법경찰관은 장애인인 피의자에게 대한법률구조공단의 법률구조 신청에 대하여 안내해야 한다.', 2529);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4432, '① 특별사법경찰관은 외국인을 체포ㆍ구속하는 경우에는 우리나라 주재 본국 영사관원과 자유롭게 접견ㆍ통신할 수 있고, 체포ㆍ구속된 사실을 영사기관에 통지하여 줄 것을 요청할 수 있다는 사실을 알려야 한다.', 2531);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4433, '② 특별사법경찰관은 체포ㆍ구속된 외국인이 제1항에 따른 통지를 요청할 경우에는 지체 없이 해당 영사기관에 체포ㆍ구속된 사실을 통지해야 한다.', 2531);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4434, null, 2532);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4435, '① 특별사법경찰관이 「마약류 불법거래 방지에 관한 특례법」(이하 "마약거래방지법"이라 한다) 제34조제1항 및 제53조제1항(「범죄수익은닉의 규제 및 처벌 등에 관한 법률」 제12조에서 준용하는 경우를 포함한다)에 따라 검사에게 몰수ㆍ부대보전 또는 추징보전을 신청할 때에는 별지 제122호서식의 몰수ㆍ부대보전 신청서 또는 별지 제123호서식의 추징보전 신청서를 제출해야 한다.', 2534);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4436, '② 특별사법경찰관이 제1항에 따라 몰수ㆍ부대보전 또는 추징보전을 신청했을 때에는 별지 제124호서식의 몰수ㆍ부대보전 신청부 또는 별지 제125호서식의 추징보전 신청부를 작성하고, 필요한 사항을 적어야 한다.', 2534);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4437, '③ 특별사법경찰관은 마약거래방지법 제53조제3항(「범죄수익은닉의 규제 및 처벌 등에 관한 법률」 제12조에서 준용하는 경우를 포함한다. 이하 이 조에서 같다)에 따라 검사가 추징보전과 관련한 신청, 보완ㆍ수정, 취소 등의 요구를 한 경우에는 검사의 요구에 따른 조치를 취한 다음 지체 없이 그 결과를 검사에게 보고해야 한다.', 2534);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4438, '④ 특별사법경찰관은 마약거래방지법 제53조제3항에 따른 검사의 요구에 따라 추징보전명령 취소신청을 하려는 경우에는 별지 제126호서식에 따라 추징보전명령 취소신청서를 제출해야 한다.', 2534);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4439, '⑤ 특별사법경찰관은 제4항에 따라 취소신청을 하였을 때에는 별지 제127호서식의 추징보전 취소신청부를 작성하고, 필요한 사항을 적어야 한다.', 2534);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4440, '① 특별사법경찰관은 마약거래방지법 제3조제5항에 따른 입국ㆍ상륙 허가의 요청 또는 체류 부적당 통보를 검사에게 신청할 때에는 별지 제128호서식의 입국ㆍ상륙허가요청 신청서 또는 별지 제129호서식의 체류부적당통보 신청서를 제출해야 한다.', 2535);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4441, '② 특별사법경찰관은 마약거래방지법 제4조제3항에 따라 세관 절차 특례에 대한 요청을 검사에게 신청하는 경우에는 별지 제130호서식의 세관절차 특례요청 신청서를 제출해야 한다.', 2535);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4442, '③ 특별사법경찰관은 제1항 및 제2항에 따라 신청을 하였을 때에는 별지 제131호서식의 특례조치 등 신청부를 작성해야 한다.', 2535);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4443, '① 특별사법경찰관이 수사를 종결한 때에는 관할 지방검찰청 검사장 또는 지청장에게 사건을 송치해야 한다.', 2536);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4444, '② 특별사법경찰관은 제1항에 따라 사건을 송치하는 경우에는 다음 각 호의 구분에 따른 명의로 해야 한다.', 2536);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4445, '① 특별사법경찰관은 다음 각 호의 어느 하나에 해당하는 사건에 대해서는 사건을 송치하기 전에 검사의 구체적 지휘를 받아야 한다.', 2537);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4446, '② 특별사법경찰관은 「출입국관리법」 위반범죄, 「관세법」 위반범죄 및 「조세범 처벌법」 위반범죄 등 관계 행정기관의 장의 고발을 공소제기 요건으로 하는 범죄를 수사하는 경우에는 송치 등 사건을 종결하는 처분을 하기 전에 해당 사건의 증거 판단, 소추요건, 법령의 해석ㆍ적용 등에 관하여 검사의 지휘를 받아야 한다. 다만, 관계 행정기관의 장이 법무부장관이나 검찰총장, 관할 지방검찰청 검사장 또는 지청장과 미리 협의하여 정한 처리기준에 따라 처리할 때에는 검사의 지휘를 받지 않고 사건을 종결하는 처분을 할 수 있다.', 2537);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4447, '③ 검사는 제1항 및 제2항 본문에 따른 지휘 건의가 있을 때에는 7일 이내에 의견을 제시해야 한다. 다만, 사안이 복잡하거나 장시간의 검토를 필요로 하는 등의 특별한 사정이 있을 때에는 14일 이내에 의견을 제시할 수 있다.', 2537);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4448, '④ 제1항 및 제2항 본문에 따른 검사의 지휘를 받은 특별사법경찰관은 사건송치서 등 수사기록 표지의 비고란에 지휘검사의 성명 및 지휘일자를 기재하고, 수사기록에 수사지휘서 또는 수사지휘내용을 기재한 수사보고서를 편철해야 한다.', 2537);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4449, '① 특별사법경찰관은 사건을 송치할 때에는 수사기록에 제4항 각 호의 서류를 첨부해야 한다. 다만, 「형의 실효 등에 관한 법률」 제5조제1항제2호에 해당하는 경우로서 「지문을 채취할 형사피의자의 범위에 관한 규칙」 제2조제2항제1호ㆍ제2호 또는 제4호에 해당하지 않는 피의자에 대하여 다음 각 호의 어느 하나에 해당하는 의견으로 송치할 때에는 범죄경력ㆍ수사경력 조회 결과를 첨부하지 않을 수 있다.', 2538);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4450, '② 사건을 송치하기 전에 범죄경력ㆍ수사경력 조회 결과를 받지 못한 경우에는 사건송치서에 그 사유를 기재하고, 송치 후에 범죄경력 또는 수사경력을 발견한 때에는 즉시 주임검사에게 보고해야 한다.', 2538);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4451, '③ 특별사법경찰관은 사건을 기소중지 의견으로 송치하는 경우에는 소재불명 피의자의 지명수배ㆍ통보 내용, 사진, 별지 제132호서식의 인상서 등 관련 자료를 첨부해야 한다.', 2538);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4452, '④ 송치서류는 다음 각 호의 순서에 따라 편철한다.', 2538);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4453, '⑤ 사건을 송치하는 특별사법경찰관은 제4항제2호부터 제4호까지의 규정에 따른 서류에 직접 간인을 해야 한다.', 2538);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4454, '⑥ 제4항제4호의 서류에는 각 장마다 면수를 기입하되, 1장으로 이루어진 경우에는 1로 표시하고, 2장 이상으로 이루어진 경우에는 1-1, 1-2, 1-3 등으로 표시해야 한다.', 2538);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4455, '⑦ 제4항제5호의 서류는 접수하거나 작성한 순서에 따라 편철한다. 이 경우 순서대로 각 장마다 2부터 시작하여 2, 3, 4 등으로 면수를 표시해야 한다. <개정 2021.2.3>', 2538);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4456, '⑧ 특별사법경찰관은 「검찰압수물사무규칙」 제2조에 따른 특수압수물을 송부하는 경우에는 수사기록에 감정서 원본을 편철하여 사본 2부와 함께 제출해야 한다. 다만, 통화ㆍ외국환 및 유가증권과 이에 준하는 증서를 송부하는 경우에는 감정서를 첨부하지 않을 수 있다.', 2538);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4457, '⑨ 수사담당 특별사법경찰관은 통신제한조치를 집행한 사건을 송치하는 경우에는 수사기록 표지의 증거품 관련 난에 "통신제한조치"라고 표기하고, 통신제한조치집행으로 취득한 물건을 직접 「검찰압수물사무규칙」에 따른 압수물 송부의 방법으로 송부해야 한다.', 2538);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4458, '⑩ 제4항ㆍ제5항 및 제7항은 사건송치 전에 영장등을 신청하거나 신병지휘건의 등을 하는 경우에 영장등의 신청서류 및 신병지휘건의서류 등의 편철, 간인 및 면수 표시 방법에 관하여도 적용한다.', 2538);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4459, '① 특별사법경찰관은 영상녹화를 실시한 경우 사건 송치 시 봉인된 영상녹화물을 기록과 함께 송부해야 한다.', 2539);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4460, '② 특별사법경찰관은 영상녹화물을 송부하는 경우에는 송치서 표지의 비고란에 영상녹화물의 종류와 개수를 표시해야 한다.', 2539);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4461, '① 특별사법경찰관이 참고인중지의견으로 사건을 송치할 때에는 별지 제137호서식의 참고인 등 소재수사 지휘부를 작성하여 별도로 편철하여 관리하고, 그 사본 1부를 수사기록에 편철해야 한다.', 2541);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4462, '② 특별사법경찰관리는 분기마다 1회 이상 참고인 등에 대한 소재수사를 행해야 한다. 다만, 검사가 특별사법경찰관의 송치의견과 다른 결정을 한 경우에는 참고인 등 소재수사 지휘부에 그 취지를 기재하고 소재수사를 하지 않을 수 있다.', 2541);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4463, '① 특별사법경찰관리는 사건을 송치한 후에 해당 사건을 계속 수사하려는 경우에는 미리 주임검사의 지휘를 받아야 한다.', 2543);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4464, '② 특별사법경찰관리는 사건을 송치한 후에 해당 사건의 피의자가 저지른 다른 범죄의 혐의를 발견한 경우에는 즉시 주임검사에게 보고하고 지휘를 받아야 한다.', 2543);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4465, '① 특별사법경찰관은 다음 각 호의 어느 하나에 해당하는 경우에는 즉시 수사에 착수하고 관할 지방검찰청 또는 지청의 검사에게 그 사실을 보고해야 한다.', 2544);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4466, '② 사법경찰관은 제1항에 따른 보고를 하는 경우에는 다음 각 호의 서식에 따른다.', 2544);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4467, '③ 특별사법경찰관은 기소중지된 피의자가 다른 기관에서 검거된 경우에는 즉시 그 피의자에 대한 체포영장의 집행ㆍ호송 등 필요한 조치를 취해야 한다.', 2544);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4468, '④ 특별사법경찰관은 참고인중지의 경우 그 참고인이 교도소, 구치소 등에 구금되어 있는 것을 확인했을 때에는 즉시 검사의 지휘를 받아 출장조사, 공조수사 촉탁 등 필요한 조치를 해야 한다.', 2544);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4469, '⑤ 특별사법경찰관은 제1항에 따라 수사에 착수한 경우에는 별지 제141호서식의 피의자 등 소재발견처리부에 이를 적어야 한다.', 2544);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4470, '① 특별사법경찰관이 수사촉탁을 하는 경우에는 촉탁사항을 구체적으로 기재한 별지 제142호서식의 촉탁서에 수사진행 상황을 알 수 있는 수사기록 원본 또는 사본의 전부나 일부를 첨부하여 발송한다.', 2545);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4471, '② 수탁관서는 촉탁사항에 대한 수사를 완료한 후 별지 제143호서식의 회답서를 작성하여 관계 서류 전부와 함께 신속히 송부해야 한다.', 2545);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4472, '① 특별사법경찰관은 범죄사건을 접수하거나 입건ㆍ수사 또는 송치하는 경우에는 별지 제144호서식의 범죄사건부에 접수일시, 접수구분, 수사담당자, 피의자, 죄명, 범죄일시, 장소, 피해정도, 피해자 등을 기재해야 한다.', 2547);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4473, '② 특별사법경찰관은 압수물건이 있는 경우에는 별지 제145호서식의 압수부에 압수연월일, 압수 물건의 품종, 수량 등을 기재해야 한다.', 2547);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4474, '① 특별사법경찰사무를 처리하는 행정기관은 다음 각 호의 장부와 서류를 비치해야 한다. 다만, 제22호부터 제35호까지의 규정에 따른 장부와 서류를 비치해야 하는 기관은 「통신비밀보호법」 제5조에 따른 범죄의 수사를 직무로 하는 기관으로 한정한다.', 2549);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4475, '② 특별사법경찰관은 미리 제1항제20호의 체포ㆍ구속인명부 및 같은 항 제41호의 범죄사건부의 매 장마다 관할 지방검찰청 검사장 또는 지청장의 간인을 받아야 한다.', 2549);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4476, '① 특별사법경찰사무를 처리하는 행정기관이 형사사법정보시스템 또는 형사사법정보시스템에 준하는 시스템(「형사사법절차 전자화 촉진법」에 따른 형사사법정보시스템에 준하여 같은 법 제2조에 따른 형사사법정보를 작성, 취득, 저장, 저장 및 관리하는 데 이용할 수 있도록 구현된 것으로서 시스템의 각 기능 및 운영 상황 등에 대해 검찰총장이나 관할 지방검찰청 검사장 또는 지청장의 점검을 받은 시스템을 말한다)을 갖춘 경우에는 제122조제1항제41호의 범죄사건부를 전자적으로 관리할 수 있다. 이 경우 전자적으로 관리하는 범죄사건부에 대해서는 같은 조 제2항을 적용하지 않는다.', 2550);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4477, '② 제1항 전단에 따라 전자적으로 관리하는 범죄사건부는 별지 제144호서식의 개별 항목을 포함해야 한다.', 2550);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4478, '① 서류철에는 색인목록을 붙여야 한다.', 2558);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4479, '② 서류를 철한 후 일부를 빼낼 때에는 그 색인목록의 비고란에 그 연월일과 사유를 기재하고 담당 특별사법경찰관이 날인해야 한다.', 2558);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4480, '① 특별사법경찰사무에 관한 장부와 서류철은 해마다 갱신해야 한다.', 2560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4481, '② 제1항에도 불구하고 계속 사용할 필요가 있는 경우에는 해마다 갱신하지 않고 사용할 수 있다. 이 경우 연도 구분을 명백히 표시해야 한다.', 2560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4482, null, 2561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4483, '① 제134조에 따른 보존기간은 사건처리를 완결하거나 최종절차를 마친 다음 해 1월 1일부터 기산한다.', 2562);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4484, '② 보존기간이 경과한 장부와 서류철은 폐기목록을 작성한 후 폐기해야 한다.', 2562);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4485, '③ 제3항에 따라 장부와 서류철을 폐기하는 경우에는 「공공기록물 관리에 관한 법률 시행령」 제43조에 따라 해당 기관 기록물관리 전문요원의 심사 및 기록물평가심의회의 심의 절차를 거쳐야 한다.', 2562);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4486, '① 사법경찰관리는 수사를 할 때에는 합리적 이유 없이 피의자와 그 밖의 피해자ㆍ참고인 등(이하 "사건관계인"이라 한다)의 성별, 종교, 나이, 장애, 사회적 신분, 출신지역, 인종, 국적, 외모 등 신체조건, 병력(病歷), 혼인 여부, 정치적 의견 및 성적(性的) 지향 등을 이유로 차별해서는 안 된다.', 2564);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4487, '② 사법경찰관리는 「형사소송법」(이하 "법"이라 한다) 및 「검사와 사법경찰관의 상호협력과 일반적 수사준칙에 관한 규정」(이하 "수사준칙"이라 한다) 등 관계 법령을 준수하고 적법한 절차와 방식에 따라 수사해야 한다.', 2564);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4488, '① 사법경찰관리는 수사준칙 제6조에 따라 검사가 수사, 공소제기 및 공소유지와 관련하여 협력의 요청ㆍ요구ㆍ신청 등(이하 "협력요청등"이라 한다)을 하는 경우에는 상호 존중을 바탕으로 적극 협조해야 한다.', 2565);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4489, '② 사법경찰관리는 검사에게 협력요청등을 하는 경우에는 「형사사법절차 전자화 촉진법」 제2조제4호에 따른 형사사법정보시스템(이하 "형사사법정보시스템"이라 한다) 또는 서면으로 해야 한다.', 2565);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4490, '③ 천재지변 또는 긴급한 상황이 발생하거나 수사 현장에서 협력요청등을 하는 경우 등 제2항의 방식으로 협력요청등을 하는 것이 불가능하거나 현저히 곤란한 경우에는 구두(口頭)나 전화 등 간편한 방식으로 협력요청등을 할 수 있다.', 2565);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4491, '④ 사법경찰관리는 신속한 수사가 필요한 경우에는 적정한 기간을 정하여 검사에게 협력요청등을 할 수 있다.', 2565);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4492, '⑤ 사법경찰관리는 검사로부터 기간이 정해진 협력요청등을 받은 경우에는 그 기간 내에 이행하도록 노력해야 한다. 다만, 그 기간 내에 이행하기 곤란하거나 이행하지 못하는 경우에는 추가로 필요한 기간을 검사와 협의할 수 있다.', 2565);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4493, '① 사법경찰관리는 수사준칙 제7조에 따라 검사에게 중요사건에 대한 의견의 제시ㆍ교환을 요청하는 경우에는 별지 제1호서식의 의견요청서에 따른다.', 2566);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4494, '② 사법경찰관리는 수사준칙 제7조에 따라 검사로부터 중요사건에 대한 의견의 제시ㆍ교환 요청을 받아 의견을 제시ㆍ교환하는 경우에는 별지 제2호서식의 의견서에 따른다.', 2566);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4495, '① 사법경찰관리는 수사준칙 제55조제1항에 따라 소재불명(所在不明)인 피의자나 참고인을 발견하여 통보하는 경우에는 별지 제3호서식 또는 별지 제4호서식의 소재불명자 발견 통보서에 따른다.', 2567);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4496, '② 사법경찰관리는 수사준칙 제55조제2항에 따른 검사의 소재수사 요청에 협력하여 소재 확인을 한 경우에는 별지 제5호서식의 소재수사 결과 통보서를 작성하여 검사에게 통보해야 한다.', 2567);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4497, '① 사법경찰관리는 사법경찰관리가 수사 중인 사건에 대하여 검사로부터 「검찰사건사무규칙」에 따른 시찰조회를 요청받은 경우에는 협력해야 한다.', 2568);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4498, '② 사법경찰관리는 사법경찰관리가 수사 중인 사건이 아닌 사건에 대하여 검사로부터 시찰조회를 요청받은 경우에는 사건의 내용, 시찰조회 요청 사유 및 직무 수행 지장 여부 등을 종합적으로 검토하여 협력 여부를 결정할 수 있다.', 2568);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4499, '① 사법경찰관리는 수사준칙 제8조제1항에 따라 검사와의 협의를 요청하려는 경우에는 별지 제6호서식의 협의요청서에 요청 사항과 그 사유를 적어 검사에게 통보해야 한다.', 2569);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4500, '② 사법경찰관리는 수사준칙 제8조제2항 각 호의 어느 하나에 해당하는 경우 제1항에 따른 해당 검사와의 협의에도 불구하고 이견이 해소되지 않으면 이를 즉시 소속된 해양경찰관서의 장(이하 "소속해양경찰관서장"이라 한다)에게 보고해야 한다. <개정 2024.6.19>', 2569);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4501, '③ 제2항의 보고를 받은 소속해양경찰관서장은 수사준칙 제8조제2항에 따른 협의가 필요하다고 판단하면 별지 제7호서식의 협의요청서에 요청 사항과 그 사유를 적어 제2항에 따른 해당 검사가 소속된 검찰청의 장에게 통보해야 한다.', 2569);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4502, '④ 사법경찰관리 또는 소속해양경찰관서장은 제1항 또는 제3항에 따라 검사 또는 검찰청의 장과 협의한 사항이 있으면 그 협의사항을 성실하게 이행하도록 노력해야 한다.', 2569);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4503, '① 사법경찰관리는 수사에 필요한 경우에는 다른 사법경찰관리에게 피의자의 체포ㆍ출석요구ㆍ조사ㆍ호송, 압수ㆍ수색ㆍ검증, 참고인의 출석요구ㆍ조사 등 그 밖의 필요한 조치에 대한 협력을 요청할 수 있다. 이 경우 요청을 받은 사법경찰관리는 정당한 이유가 없으면 이에 적극 협조해야 한다.', 2570);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4504, '② 사법경찰관리는 수사에 필요한 경우에는 법 제245조의10에 따른 특별사법경찰관리와 긴밀히 협력해야 한다. 이 경우 협력의 구체적인 내용ㆍ범위 및 방법 등은 상호 협의하여 정한다.', 2570);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4505, '① 사건기록담당직원은 법 및 관련 법령에 따라 검사로부터 요구ㆍ요청 등을 받거나 사건 기록과 증거물을 반환받은 때에는 관계 서류 등이 법령에 따라 작성ㆍ편철됐는지 및 검사가 법령에 따라 필요한 행위를 했는지를 점검해야 한다.', 2571);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4506, '② 사건기록담당직원은 제1항에 따른 점검 결과 관계 서류 등이 법 및 관련 법령에 따라 작성ㆍ편철되지 않거나, 검사가 법 및 관련 법령에 따라 필요한 행위를 하지 않은 경우에는 검사에게 그 보완을 요구하는 등 필요한 조치를 할 수 있다.', 2571);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4507, '③ 사건기록담당직원은 제1항에 따라 요구ㆍ요청 등을 받거나 사건 기록과 증거물을 반환받아 이를 접수한 경우에는 접수대장에 접수일시, 검사 또는 검찰청 직원의 성명 등을 기재하고, 검사 또는 검찰청 직원이 제시하는 접수기록부 등에 접수일시와 접수자의 직급 및 서명을 기재한다.', 2571);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4508, '① 사법경찰관은 다음 각 호의 어느 하나에 해당하는 날부터 7일 이내에 고소인ㆍ고발인ㆍ피해자 또는 그 법정대리인(피해자가 사망한 경우에는 그 배우자ㆍ직계친족ㆍ형제자매를 포함한다. 이하 "고소인등"이라 한다)에게 수사 진행상황을 통지해야 한다. 다만, 고소인등의 연락처를 모르거나 소재가 확인되지 않으면 연락처나 소재를 알게 된 날부터 7일 이내에 수사 진행상황을 통지해야 한다. <개정 2024.6.19>', 2573);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4509, '② 제1항제2호에 따른 수사 진행상황 통지 후에 고소인등의 요청이 있거나 그 밖에 사법경찰관이 필요하다고 인정하는 경우에도 수사 진행상황을 통지할 수 있다. <신설 2024.6.19>', 2573);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4510, '③ 제1항 및 제2항에 따른 통지는 서면, 전화, 팩스, 전자우편, 문자메시지 등 고소인등이 요청한 방법으로 할 수 있으며, 고소인등이 별도로 요청한 방법이 없는 경우에는 서면 또는 문자메시지로 통지한다. 이 경우 서면으로 하는 통지는 별지 제9호서식의 수사 진행상황 통지서에 따른다. <개정 2024.6.19>', 2573);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4511, '④ 사법경찰관은 수사 진행상황을 서면으로 통지한 경우에는 그 사본을, 그 밖의 방법으로 통지한 경우에는 그 취지를 적은 서면을 사건기록에 편철해야 한다. <개정 2024.6.19>', 2573);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4512, '⑤ 사법경찰관은 제1항 및 제2항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 수사 진행상황을 통지하지 않을 수 있다. 이 경우 그 사실을 수사보고서로 작성하여 사건기록에 편철해야 한다. <개정 2024.6.19>', 2573);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4513, '① 사법경찰관리는 법 제243조의2제1항에 따라 피의자 또는 그 변호인ㆍ법정대리인ㆍ배우자ㆍ직계친족ㆍ형제자매의 신청이 있는 경우 변호인의 참여로 인하여 신문이 방해되거나, 수사기밀이 누설되는 등 정당한 사유가 있는 경우를 제외하고는 피의자에 대한 신문에 변호인을 참여하게 해야 한다.', 2574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4514, '② 제1항의 변호인의 피의자신문 참여 신청을 받은 사법경찰관리는 신청인으로부터 변호인의 피의자신문 참여 전에 다음 각 호의 서면을 제출받아야 한다.', 2574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4515, '① 사법경찰관리는 변호인의 참여로 증거를 인멸ㆍ은닉ㆍ조작할 위험이 구체적으로 드러나거나, 신문 방해, 수사기밀 누설 등 수사에 현저한 지장을 초래하는 경우에는 피의자신문 중이라도 변호인의 참여를 제한할 수 있다. 이 경우 피의자와 변호인에게 변호인의 참여를 제한하는 처분에 대해 법 제417조에 따른 준항고를 제기할 수 있다는 사실을 고지해야 한다.', 2575);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4516, '② 제1항에 따라 변호인 참여를 제한하는 경우 사법경찰관리는 피의자 또는 변호인에게 그 사유를 설명하고 의견을 진술할 기회와 다른 변호인을 참여시킬 기회를 주어야 한다.', 2575);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4517, '③ 제1항에 따라 변호인의 참여를 제한한 후 그 사유가 해소된 때에는 변호인을 신문에 참여하게 해야 한다.', 2575);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4518, null, 2577);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4519, '① 해양경찰청장은 수사의 책임성과 완결성 확보를 위해 해양경찰관서에 해양경찰청장이 정하는 자격을 갖춘 심사관을 둘 수 있다.', 2579);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4520, '② 제1항에 따른 심사관은 강제수사의 적법성ㆍ타당성 심사, 불송치 사건 및 수사 전반에 대한 점검 등의 업무를 수행한다.', 2579);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4521, '① 사법경찰관은 법 제197조제1항에 따라 구체적인 사실에 근거를 둔 범죄의 혐의를 인식한 때에는 수사를 개시한다.', 2580);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4522, '② 사법경찰관은 제1항에 따라 수사를 개시할 때에는 지체 없이 별지 제11호서식의 범죄인지서를 작성하여 사건기록에 편철해야 한다.', 2580);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4523, '① 사법경찰관은 수사준칙 제16조제3항에 따른 입건 전에 범죄를 의심할 만한 정황이 있어 수사 개시 여부를 결정하기 위한 사실관계의 확인 등 필요한 조사(이하 "입건전조사"라고 한다)에 착수하기 위해서는 그 사건을 수리하고, 해당 사법경찰관이 소속된 해양경찰관서의 수사 부서의 장(이하 "소속수사부서장"이라 한다)의 지휘를 받아야 한다. <개정 2022.11.15, 2024.6.19>', 2581);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4524, '② 사법경찰관은 입건전조사한 사건을 다음 각 호의 구분에 따라 처리해야 한다. <개정 2022.11.15, 2024.6.19>', 2581);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4525, '③ 제1항 및 제2항에서 규정한 사항 외에 입건전조사 사건의 분류, 수리 및 조사의 진행과 기록관리 등에 필요한 세부사항은 해양경찰청장이 정한다. <신설 2024.6.19>', 2581);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4526, '① 사법경찰관은 수사준칙 제16조제4항에 따라 피혐의자(제19조제2항제2호에 따라 입건전조사 종결한 경우만 해당한다)와 진정인ㆍ탄원인ㆍ피해자 또는 그 법정대리인(피해자가 사망한 경우에는 그 배우자ㆍ직계친족ㆍ형제자매를 포함한다. 이하 "진정인등"이라 한다)에게 입건하지 않는 결정을 통지하는 경우에는 그 결정을 한 날부터 7일 이내에 통지해야 한다. 다만, 피혐의자나 진정인등의 연락처를 모르거나 소재가 확인되지 않으면 연락처나 소재를 알게 된 날부터 7일 이내에 통지해야 한다. <개정 2022.11.15>', 2582);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4527, '② 제1항에 따른 통지는 서면, 전화, 팩스, 전자우편, 문자메시지 등 피혐의자 또는 진정인등이 요청한 방법으로 할 수 있으며, 별도로 요청한 방법이 없는 경우에는 서면 또는 문자메시지로 한다. 이 경우 서면으로 하는 통지는 별지 제12호서식 또는 별지 제13호서식의 불입건 결정 통지서에 따른다.', 2582);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4528, '③ 사법경찰관은 서면으로 통지한 경우에는 그 사본을, 그 밖의 방법으로 통지한 경우에는 그 취지를 적은 서면을 사건기록에 편철해야 한다.', 2582);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4529, '④ 사법경찰관은 제1항에도 불구하고 통지로 인해 보복범죄 또는 2차 피해 등이 우려되는 다음 각 호의 경우에는 불입건 결정을 통지하지 않을 수 있다. 이 경우 그 사실을 입건전조사 보고서로 작성하여 사건기록에 편철해야 한다. <개정 2022.11.15>', 2582);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4530, '① 사법경찰관리는 진정인ㆍ탄원인 등 민원인이 제출하는 서류가 고소ㆍ고발의 요건을 갖추었다고 판단하는 경우 이를 고소ㆍ고발로 수리한다.', 2583);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4531, '② 사법경찰관리는 고소장 또는 고발장의 명칭으로 제출된 서류가 다음 각 호의 어느 하나에 해당하는 경우에는 이를 진정(陳情)으로 처리할 수 있다. <개정 2024.6.19>', 2583);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4532, '① 사법경찰관리는 구술로 제출된 고소ㆍ고발을 수리한 경우에는 진술조서를 작성해야 한다.', 2584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4533, '② 사법경찰관리는 서면으로 제출된 고소ㆍ고발을 수리했으나 추가 진술이 필요하다고 판단하는 경우 고소인ㆍ고발인으로부터 보충 서면을 제출받거나 추가로 진술을 들어야 한다.', 2584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4534, '③ 자수하는 경우 진술조서의 작성 및 추가 진술에 관하여는 제1항 및 제2항을 준용한다.', 2584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4535, '① 사법경찰관리는 법 제236조에 따라 대리인으로부터 고소를 수리하는 경우에는 고소인 본인의 위임장을 제출받아야 한다.', 2585);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4536, '② 사법경찰관리는 법 제225조부터 제228조까지의 규정에 따른 고소권자로부터 고소를 수리하는 경우에는 그 자격을 증명하는 서면을 제출받아야 한다.', 2585);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4537, '③ 사법경찰관리는 제2항에 따른 고소권자의 대리인으로부터 고소를 수리하는 경우에는 제1항 및 제2항에 따른 위임장 및 자격을 증명하는 서면을 함께 제출받아야 한다.', 2585);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4538, '④ 고소의 취소에 관하여는 제1항부터 제3항까지의 규정을 준용한다.', 2585);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4539, '① 사법경찰관리는 고소ㆍ고발을 수리한 날부터 3개월 이내에 수사를 마쳐야 한다.', 2586);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4540, '② 사법경찰관리는 제1항의 기간 내에 수사를 완료하지 못한 경우에는 그 이유를 소속수사부서장에게 보고하고 수사기간 연장을 승인받아야 한다.', 2586);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4541, '① 사법경찰관리는 고소ㆍ고발의 취소가 있을 때에는 그 취지를 명확하게 확인해야 한다.', 2587);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4542, '② 피해자의 명시한 의사에 반하여 공소를 제기할 수 없는 범죄에 대해 처벌을 희망하는 의사표시의 철회가 있을 때에도 제1항과 같다.', 2587);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4543, '① 사법경찰관은 수사준칙 제17조제1항에 따라 변사사건 발생사실을 검사에게 통보하는 경우에는 별지 제14호서식의 변사사건 발생 통보서에 따른다.', 2588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4544, '② 사법경찰관은 긴급한 상황 등 제1항의 방식으로 통보하는 것이 불가능하거나 현저히 곤란한 경우에는 구두ㆍ전화ㆍ팩스ㆍ전자우편 등 간편한 방식으로 통보할 수 있다. 이 경우 사후에 지체 없이 서면으로 변사사건 발생사실을 통보해야 한다.', 2588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4545, '① 사법경찰관은 법 제222조제1항 및 제3항에 따라 검시를 하는 경우에는 의사를 참여시켜야 하며, 그 의사로 하여금 검안서를 작성하게 해야 한다. 이 경우 사법경찰관은 검시 조사관을 참여시킬 수 있다.', 2589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4546, '② 사법경찰관은 법 제222조에 따른 검시 또는 검증 결과 사망의 원인이 범죄로 인한 것으로 판단하는 경우에는 신속하게 수사를 개시해야 한다.', 2589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4547, '① 수사준칙 제17조제3항에 따른 검시조서는 별지 제15호서식에 따르고, 검증조서는 별지 제16호서식에 따른다.', 2590);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4548, '② 사법경찰관은 수사준칙 제17조제3항에 따라 검사에게 제1항의 검시조서 또는 검증조서를 송부하는 경우에는 의사의 검안서, 감정서 및 촬영한 사진 등 관련 자료를 첨부해야 한다.', 2590);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4549, '③ 사법경찰관은 수사준칙 제17조제4항에 따라 검시를 한 사건에 대해 검사와 의견을 제시ㆍ교환하는 경우에는 별지 제17호서식의 변사사건 처리 등에 관한 의견서에 따른다.', 2590);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4550, null, 2591);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4551, '① 사법경찰관은 변사자에 대한 검시 또는 검증이 종료된 때에는 사체를 소지품 등과 함께 신속히 유족 등에게 인도한다. 다만, 사체를 인수할 사람이 없거나 변사자의 신원이 판명되지 않은 경우에는 사체가 현존하는 지역의 특별자치시장ㆍ특별자치도지사ㆍ시장ㆍ군수 또는 자치구의 구청장에게 인도해야 한다.', 2593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4552, '② 제1항 본문에서 검시 또는 검증이 종료된 때는 다음 각 호의 구분에 따른 때를 말한다.', 2593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4553, '③ 사법경찰관은 제1항에 따라 사체를 인도한 경우에는 인수자로부터 별지 제18호서식의 사체 및 소지품 인수서를 받아야 한다.', 2593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4554, '① 사법경찰관은 수사준칙 제21조제2항제4호에 따라 심야조사를 하려는 경우에는 심야조사의 내용 및 심야조사가 필요한 사유를 소속 해양경찰관서에서 인권보호 업무를 담당하는 부서의 장에게 보고하고 허가를 받아야 한다.', 2598);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4555, '② 사법경찰관은 제1항에 따라 허가를 받은 경우 수사보고서를 작성하여 사건기록에 편철해야 한다.', 2598);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4556, '① 수사준칙 제24조제2항에 따른 동석신청서는 별지 제24호서식 또는 별지 제25호서식에 따른다.', 2600);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4557, '② 사법경찰관은 피의자, 피해자 또는 그 법정대리인이 제1항의 동석신청서를 작성할 시간적 여유가 없는 경우 등에는 이를 제출받지 않고 조서 또는 수사보고서에 그 취지를 기재하는 것으로 동석신청서 작성을 갈음할 수 있으며, 조사의 긴급성 또는 동석의 필요성 등이 현저한 경우에는 예외적으로 동석 조사 이후에 신뢰관계인과 피의자와의 관계를 소명할 자료를 제출받아 기록에 편철할 수 있다.', 2600);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4558, '③ 사법경찰관은 동석 신청이 없더라도 동석이 필요하다고 인정되면 피의자 또는 피해자와의 신뢰관계 유무를 확인한 후 직권으로 신뢰관계에 있는 사람을 동석하게 할 수 있다. 이 경우 그 관계 및 취지를 조서나 수사보고서에 적어야 한다.', 2600);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4559, '④ 사법경찰관은 신뢰관계인의 동석으로 인하여 신문이 방해되거나, 수사기밀이 누설되는 등 정당한 사유가 있는 경우에는 동석을 거부할 수 있으며, 신뢰관계인이 피의자신문 또는 피해자 조사를 방해하거나 그 진술의 내용에 부당한 영향을 미칠 수 있는 행위를 하는 등 수사에 현저한 지장을 초래하는 경우에는 피의자신문 또는 피해자 조사 중에도 동석을 제한할 수 있다.', 2600);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4560, '⑤ 피해자 이외의 사건관계인 조사에 관하여는 제1항부터 제4항까지의 규정을 준용한다.', 2600);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4561, '① 사법경찰관리가 법 제244조제1항에 따라 피의자의 진술을 조서에 적는 경우에는 별지 제26호서식 또는 별지 제27호서식의 피의자신문조서에 따른다.', 2601);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4562, '② 사법경찰관리가 피의자가 아닌 사람의 진술을 조서에 적는 경우에는 별지 제28호서식 또는 별지 제29호서식의 진술조서에 따른다.', 2601);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4563, '③ 사법경찰관리는 피의자 또는 피의자가 아닌 사람의 진술을 듣는 경우 진술 사항이 복잡하거나 진술인이 서면진술을 원하면 진술서를 작성하여 제출하게 할 수 있다.', 2601);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4564, '④ 피의자신문조서와 진술조서에는 진술자로 하여금 간인(間印)한 후 기명날인 또는 서명하게 한다.', 2601);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4565, '① 사법경찰관리는 범죄의 현장 또는 그 밖의 장소에서 피의사실을 확인하거나 증거물의 증명력을 확보하기 위해 필요한 경우 실황조사를 할 수 있다.', 2603);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4566, '② 사법경찰관리는 실황조사를 하는 경우에는 거주자, 관리자 그 밖의 관계자 등을 참여하게 할 수 있다.', 2603);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4567, '③ 사법경찰관리는 실황조사를 한 경우에는 별지 제32호서식의 실황조사서에 조사 내용을 상세하게 적고, 현장도면이나 사진이 있으면 이를 실황조사서에 첨부해야 한다.', 2603);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4568, '① 사법경찰관리는 법 제221조제1항 또는 제244조의2제1항에 따라 피의자 또는 피의자가 아닌 사람을 영상녹화하는 경우 그 조사의 시작부터 조서에 기명날인 또는 서명을 마치는 시점까지의 모든 과정을 영상녹화해야 한다. 다만, 조사 도중 영상녹화의 필요성이 발생한 때에는 그 시점에서 진행 중인 조사를 중단하고, 중단한 조사를 다시 시작하는 때부터 조서에 기명날인 또는 서명을 마치는 시점까지의 모든 과정을 영상녹화해야 한다.', 2605);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4569, '② 사법경찰관리는 제1항에도 불구하고 조사를 마친 후 조서 정리에 오랜 시간이 필요한 경우에는 조서 정리과정을 영상녹화하지 않고, 조서 열람 시부터 영상녹화를 다시 시작할 수 있다.', 2605);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4570, '③ 제1항 및 제2항에 따른 영상녹화는 조사실 전체를 확인할 수 있고 조사받는 사람의 얼굴과 음성을 식별할 수 있도록 해야 한다.', 2605);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4571, '④ 사법경찰관리는 피의자에 대한 조사 과정을 영상녹화하는 경우 다음 각 호의 사항을 고지해야 한다.', 2605);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4572, '⑤ 사법경찰관리는 피의자가 아닌 사람의 조사 과정을 영상녹화하는 경우에는 별지 제34호서식의 영상녹화 동의서로 영상녹화 동의 여부를 확인하고, 제4항제1호, 제2호 및 제4호의 사항을 고지해야 한다. 다만, 피혐의자에 대해서는 제4항제1호부터 제4호까지의 규정에 따른 사항을 고지해야 한다.', 2605);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4573, '① 사법경찰관리는 조사 시 영상녹화를 한 경우에는 영상녹화용 컴퓨터에 저장된 영상녹화 파일을 이용하여 영상녹화물(CD, DVD 등을 말한다. 이하 같다) 2개를 제작하여 그 중 하나를 피조사자의 기명날인 또는 서명을 받아 피조사자 또는 변호인 앞에서 봉인한 후, 봉인하지 않은 나머지 하나와 함께 수사기록에 편철한다. <개정 2024.6.19>', 2606);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4574, '② 사법경찰관리는 제1항에 따라 영상녹화물을 제작한 후 영상녹화용 컴퓨터에 저장되어 있는 영상녹화 파일을 데이터베이스 서버에 전송하여 보관할 수 있다.', 2606);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4575, '③ 사법경찰관리는 손상 또는 분실 등으로 제1항의 영상녹화물을 사용할 수 없는 경우에는 데이터베이스 서버에 보관되어 있는 영상녹화 파일을 이용하여 다시 영상녹화물을 제작할 수 있다.', 2606);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4576, '① 사법경찰관리는 다음 각 호의 어느 하나에 해당하는 사람의 소재를 알 수 없을 때에는 지명수배를 할 수 있다.', 2607);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4577, '② 제1항에도 불구하고 법 제200조의3제1항에 따른 긴급체포를 하지 않으면 수사에 현저한 지장을 초래하는 경우에는 영장을 발부받지 않고 지명수배할 수 있다. 이 경우 지명수배 후 신속히 체포영장을 발부받아야 하며, 체포영장을 발부받지 못한 때에는 즉시 지명수배를 해제해야 한다.', 2607);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4578, '① 사법경찰관리는 제45조제1항에 따라 지명수배된 사람(이하 "지명수배자"라 한다)을 발견한 때에는 체포영장 또는 구속영장을 제시하고, 수사준칙 제32조제1항에 따라 권리 등을 고지한 후 체포 또는 구속하며 별지 제35호서식의 권리 고지 확인서를 받아야 한다. 다만, 체포영장 또는 구속영장을 소지하지 않은 경우 긴급하게 필요하면 지명수배자에게 영장이 발부되었음을 고지한 후 체포 또는 구속할 수 있으며 사후에 지체 없이 그 영장을 제시해야 한다.', 2608);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4579, '② 사법경찰관은 제45조제2항에 따라 영장을 발부받지 않고 지명수배한 경우에는 지명수배자에게 긴급체포한다는 사실과 수사준칙 제32조제1항에 따른 권리 등을 고지한 후 긴급체포해야 한다. 이 경우 지명수배자로부터 별지 제35호서식의 권리 고지 확인서를 받고 제51조제1항에 따른 긴급체포서를 작성해야 한다.', 2608);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4580, null, 2609);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4581, null, 2611);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4582, '① 법 제200조의3제3항에 따른 긴급체포서는 별지 제37호서식에 따른다.', 2613);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4583, '② 수사준칙 제27조제2항 본문에 따른 긴급체포 승인요청서는 별지 제38호서식에 따른다.', 2613);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4584, '③ 사법경찰관은 수사준칙 제27조제4항 후단에 따라 긴급체포된 피의자의 석방 일시와 사유 등을 검사에게 통보하는 경우에는 별지 제39호서식의 석방 통보서에 따른다.', 2613);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4585, '① 사법경찰관리는 법 제212조에 따라 현행범인을 체포할 때에는 현행범인에게 도망 또는 증거인멸의 우려가 있는 등 당장에 체포하지 않으면 안 될 정도의 급박한 사정이 있는지 또는 체포 외에는 현행범인의 위법행위를 제지할 다른 방법이 없는지 등을 고려해야 한다.', 2614);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4586, '② 사법경찰관리는 법 제212조에 따라 현행범인을 체포한 때에는 별지 제40호서식의 현행범인체포서를 작성하고, 법 제213조에 따라 현행범인을 인도받은 때에는 별지 제41호서식의 현행범인인수서를 작성해야 한다.', 2614);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4587, '③ 사법경찰관리는 제2항의 현행범인체포서 또는 현행범인인수서를 작성하는 경우 현행범인에 대해서는 범죄와의 시간적 접착성과 범죄의 명백성이 인정되는 상황을, 준현행범인에 대해서는 범죄와의 관련성이 인정되는 상황을 구체적으로 적어야 한다.', 2614);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4588, '① 수사준칙 제28조제2항 전단에 따른 피의자 석방서는 별지 제42호서식에 따른다.', 2615);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4589, '② 사법경찰관은 수사준칙 제28조제2항 후단에 따라 검사에게 현행범인의 석방사실을 통보하는 경우에는 별지 제43호서식의 석방 통보서에 따른다.', 2615);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4590, '① 사법경찰관리는 체포영장 또는 구속영장을 집행할 때에는 신속하고 정확하게 해야 한다.', 2617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4591, '② 체포영장 또는 구속영장의 집행은 검사가 서명 또는 날인하여 교부한 영장이나 검사가 영장의 집행에 관한 사항을 적어 교부한 서면에 따른다.', 2617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4592, '③ 수사준칙 제32조제3항에 따른 권리 고지 확인서는 별지 제35호서식에 따른다. 다만, 피의자가 권리 고지 확인서에 기명날인 또는 서명하기를 거부하는 경우에는 피의자를 체포ㆍ구속하는 사법경찰관리가 확인서 끝부분에 그 사유를 적고 기명날인 또는 서명해야 한다.', 2617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4593, '④ 수사준칙 제32조의2제3항에 따른 영장 사본 교부 확인서는 별지 제47호의2서식에 따른다. 다만, 피의자가 영장 사본의 수령을 거부하거나 영장 사본 교부 확인서에 기명날인 또는 서명하는 것을 거부하는 경우에는 체포영장 또는 구속영장을 집행하는 사법경찰관리가 영장 사본 교부 확인서 끝 부분에 그 사유를 적고 기명날인 또는 서명해야 한다. <신설 2024.6.19>', 2617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4594, '① 사법경찰관리는 체포ㆍ구속한 피의자를 호송할 때에는 피의자의 도망ㆍ자살ㆍ신변안전ㆍ증거인멸 등에 주의해야 한다.', 2618);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4595, '② 사법경찰관리는 체포ㆍ구속한 피의자를 호송할 때 필요한 경우에는 가장 근접한 경찰관서에 피의자를 임시로 유치할 수 있다.', 2618);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4596, '① 사법경찰관은 법 제200조의6 및 제209조에서 준용하는 법 제91조 또는 「형의 집행 및 수용자의 처우에 관한 법률」 제87조에서 준용하는 같은 법 제41조에 따라 체포 또는 구속된 피의자와 법 제34조에서 규정한 사람이 아닌 사람과의 접견 등을 금지하려는 경우에는 별지 제50호서식의 피의자 접견 등 금지 결정서에 따른다.', 2621);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4597, '② 사법경찰관은 제1항의 결정을 취소하는 것이 타당하다고 인정되어 피의자 접견 등의 금지를 취소하는 경우에는 별지 제51호서식의 피의자 접견 등 금지 취소 결정서에 따른다.', 2621);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4598, '③ 제1항의 피의자 접견 등 금지 결정은 사법경찰관의 사건 송치와 동시에 그 효력을 상실한다.', 2621);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4599, '① 수사준칙 제36조제1항에 따른 피의자 석방서는 별지 제52호서식 또는 별지 제53호서식에 따른다.', 2622);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4600, '② 사법경찰관은 검사에게 수사준칙 제36조제2항제1호에 따라 석방사실을 통보하는 경우에는 별지 제54호서식의 석방 통보서에 따르고, 같은 항 제2호에 따라 석방사실을 보고하는 경우에는 별지 제55호서식의 석방 보고서에 따른다.', 2622);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4601, '① 사법경찰관은 법 제209조에서 준용하는 법 제93조에 따라 구속을 취소하여 피의자를 석방하는 경우에는 별지 제56호서식의 구속취소 결정서에 따른다. 다만, 법 제245조의5제1호에 따라 검사에게 송치해야 하는 사건인 경우에는 사전에 별지 제57호서식의 구속취소 동의 요청서에 따라 검사의 동의를 받아야 한다.', 2623);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4602, '② 제1항에 따라 구속을 취소한 사법경찰관은 지체 없이 별지 제58호서식의 석방 통보서를 작성하여 검사에게 석방사실을 통보하고, 그 통보서 사본을 사건기록에 편철해야 한다.', 2623);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4603, '① 사법경찰관은 법 제209조에서 준용하는 법 제101조제1항에 따라 구속의 집행을 정지하는 경우에는 별지 제59호서식의 구속집행정지 결정서에 따른다.', 2624);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4604, '② 제1항에 따라 구속의 집행을 정지한 사법경찰관은 지체 없이 별지 제60호서식의 구속집행정지 통보서를 작성하여 검사에게 그 사실을 통보하고, 그 통보서 사본을 사건기록에 편철해야 한다.', 2624);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4605, '③ 사법경찰관은 법 제209조에서 준용하는 법 제102조제2항에 따라 구속집행정지 결정을 취소하는 경우에는 별지 제61호서식의 구속집행정지 취소 결정서에 따른다.', 2624);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4606, '① 사법경찰관은 수사준칙 제37조에 따라 압수ㆍ수색 또는 검증영장을 신청하는 경우에는 별지 제62호서식부터 별지 제64호서식까지의 압수ㆍ수색ㆍ검증영장 신청서에 따른다. 이 경우 압수ㆍ수색 또는 검증의 필요성 및 해당 사건과의 관련성을 인정할 수 있는 자료를 신청서에 첨부해야 한다.', 2625);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4607, '② 압수ㆍ수색 또는 검증영장의 집행 및 반환에 관하여는 제55조제1항ㆍ제2항 및 제58조를 준용한다.', 2625);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4608, '③ 수사준칙 제38조제4항에 따른 영장 사본 교부 확인서는 별지 제47호의2서식에 따른다. 다만, 피의자가 영장 사본의 수령을 거부하거나 영장 사본 교부 확인서에 기명날인 또는 서명하는 것을 거부하는 경우에는 압수ㆍ수색 또는 검증영장을 집행하는 사법경찰관리가 영장 사본 교부 확인서 끝 부분에 그 사유를 적고 기명날인 또는 서명해야 한다. <신설 2024.6.19>', 2625);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4609, '① 수사준칙 제40조 본문에 따른 압수조서는 별지 제65호서식에 따르고, 압수목록은 별지 제66호서식에 따른다.', 2626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4610, '② 법 제219조에서 준용하는 법 제129조에 따라 압수목록을 교부하는 경우에는 별지 제67호서식의 압수목록 교부서에 따른다. 이 경우 수사준칙 제41조제1항에 따른 전자정보에 대한 압수목록 교부서는 전자파일의 형태로 복사해 주거나 전자우편으로 전송하는 등의 방식으로 교부할 수 있다.', 2626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4611, '③ 수사준칙 제42조제2항 후단에 따른 삭제ㆍ폐기ㆍ반환 확인서는 별지 제68호서식에 따른다. 다만, 제2항에 따른 압수목록 교부서에 삭제ㆍ폐기 또는 반환했다는 내용을 포함시켜 교부하는 경우에는 삭제ㆍ폐기ㆍ반환 확인서를 교부하지 않을 수 있다.', 2626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4612, '① 사법경찰관은 법 제215조에 따라 수색을 한 경우에는 수색의 상황과 결과를 명백히 한 별지 제69호서식의 수색조서를 작성해야 한다.', 2627);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4613, '② 법 제219조에서 준용하는 법 제128조에 따라 증거물 또는 몰수할 물건이 없다는 취지의 증명서를 교부하는 경우에는 별지 제70호서식의 수색증명서에 따른다.', 2627);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4614, '① 사법경찰관은 법 제218조의2제1항 및 제4항에 따라 압수물에 대해 그 소유자, 소지자, 보관자 또는 제출인(이하 이 조에서 "소유자등"이라 한다)으로부터 환부 또는 가환부의 청구를 받거나 법 제219조에서 준용하는 법 제134조에 따라 압수장물을 피해자에게 환부하려는 경우에는 별지 제71호서식의 압수물 처분 지휘 요청서를 작성하여 검사에게 제출해야 한다.', 2628);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4615, '② 사법경찰관은 제1항에 따른 압수물의 환부 또는 가환부의 청구를 받은 경우 소유자등으로부터 별지 제72호서식의 압수물 환부ㆍ가환부 청구서를 제출받아 별지 제71호서식의 압수물 처분 지휘 요청서에 첨부한다.', 2628);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4616, '③ 사법경찰관은 압수물을 환부 또는 가환부한 경우에는 피해자 및 소유자등으로부터 별지 제73호서식의 압수물 환부ㆍ가환부 영수증을 받아야 한다.', 2628);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4617, '① 사법경찰관은 압수물에 사건명, 피의자의 성명, 제64조제1항의 압수목록에 적힌 순위ㆍ번호를 기입한 표찰을 붙여야 한다.', 2629);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4618, '② 사법경찰관은 법 제219조에서 준용하는 법 제130조제1항에 따라 압수물을 다른 사람에게 보관하게 하려는 경우에는 별지 제74호서식의 압수물 처분 지휘요청서를 작성하여 검사에게 제출해야 한다.', 2629);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4619, '③ 사법경찰관은 제2항에 따라 압수물을 다른 사람에게 보관하게 하는 경우 적절한 보관인을 선정하여 성실하게 보관하게 하고, 보관인으로부터 별지 제75호서식의 압수물 보관 서약서를 받아야 한다.', 2629);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4620, '① 사법경찰관은 법 제219조에서 준용하는 법 제130조제2항 및 제3항에 따라 압수물을 폐기하려는 경우에는 별지 제76호서식의 압수물 처분 지휘요청서를 작성하여 검사에게 제출해야 한다.', 2630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4621, '② 사법경찰관은 제1항에 따라 압수물을 폐기하는 경우에는 별지 제77호서식의 압수물 폐기 조서를 작성하고 사진을 촬영하여 사건기록에 편철해야 한다.', 2630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4622, '③ 사법경찰관은 법 제219조에서 준용하는 법 제130조제3항에 따라 압수물을 폐기하는 경우에는 소유자 등 권한 있는 사람으로부터 별지 제78호서식의 압수물 폐기 동의서를 제출받거나 진술조서 등에 그 취지를 적어야 한다.', 2630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4623, '① 사법경찰관은 법 제219조에서 준용하는 법 제132조에 따라 압수물을 매각하여 대가를 보관하려는 경우에는 별지 제79호서식의 압수물 처분 지휘요청서를 작성하여 검사에게 제출해야 한다.', 2631);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4624, '② 사법경찰관은 제1항에 따라 대가보관의 처분을 했을 때에는 별지 제80호서식의 압수물 대가보관 조서를 작성한다.', 2631);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4625, '① 사법경찰관은 법 제221조제2항의 감정을 위해 법 제172조제3항에 따른 유치가 필요한 경우에는 별지 제83호서식의 감정유치장 신청서를 작성하여 검사에게 제출해야 한다.', 2635);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4626, '② 사법경찰관은 법 제221조의4제1항에 따라 법 제173조제1항에 따른 처분을 위한 허가가 필요한 경우에는 별지 제84호서식의 감정처분허가장 신청서를 작성하여 검사에게 제출해야 한다.', 2635);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4627, '① 사법경찰관은 수사준칙 제45조제2항에 따라 사건기록 등본을 검사에게 송부하는 경우에는 별지 제85호서식의 사건기록 등본 송부서를 작성하여 사건기록 등본에 편철해야 한다.', 2637);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4628, '② 사법경찰관은 제1항에 따라 사건기록 등본을 송부하는 경우에는 해당 사건기록 전체의 등본을 송부한다. 다만, 등본송부 요구의 사유가 사건기록의 일부와 관련된 경우에는 사전에 검사와 합의하고 해당 부분에 대해서만 등본을 송부할 수 있다.', 2637);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4629, '③ 사법경찰관은 필요하다고 인정하는 경우 제1항에 따라 사건기록 등본을 송부하면서 의견을 함께 제출할 수 있다.', 2637);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4630, '④ 사법경찰관은 수사준칙 제45조제4항에 따라 검사에게 시정조치 이행 결과를 통보하는 경우 별지 제86호서식의 시정조치 결과 통보서에 따른다. 다만, 법률상ㆍ사실상 시정이 불가능한 경우 등 정당한 이유가 있어 시정조치요구를 이행하지 않은 경우에는 그 내용과 사유를 시정조치 결과 통보서에 구체적으로 적어 통보해야 한다.', 2637);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4631, '① 사법경찰관은 수사준칙 제48조제1항에 따라 검사에게 사건기록의 열람을 요청하는 경우에는 별지 제89호서식의 사건기록 열람요청서에 따른다.', 2640);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4632, '② 사법경찰관은 검사로부터 수사준칙 제48조제1항에 따른 사건기록의 열람을 요청하는 서면을 받은 경우에는 그 요청 서면을 검토하여 열람 허용 여부 및 범위를 신속하게 결정한다.', 2640);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4633, '③ 사법경찰관이 검사에게 열람을 허용할 수 있는 사건기록의 범위는 다음 각 호와 같다. 다만, 예외적으로 그 외 사건기록의 열람을 허용할 필요가 있는 경우에는 달리 정할 수 있다.', 2640);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4634, '④ 사법경찰관은 별지 제90호서식의 열람허가서에 열람을 허용하는 사건기록의 범위를 기재하여 제2항의 사건기록 중 열람을 허용한 사건기록 등본과 함께 사건기록담당직원에게 인계한다.', 2640);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4635, '⑤ 사건기록담당직원은 검사에게 기록을 열람하게 하고, 관리대장에 열람 일시, 열람 검사의 성명 등을 기재한다.', 2640);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4636, '① 사법경찰관리는 피해자[타인의 범죄행위로 피해를 당한 사람과 그 배우자(사실상의 혼인관계에 있는 자를 포함한다), 직계친족 및 형제자매를 말한다. 이하 이 장에서 같다]의 심정을 이해하고 그 인격을 존중하며 피해자가 범죄피해 상황에서 조속히 회복하여 인간의 존엄성을 보장받을 수 있도록 노력해야 한다.', 2641);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4637, '② 사법경찰관리는 피해자의 명예와 사생활의 평온을 보호하고 해당 사건과 관련하여 각종 법적 절차에 참여할 권리를 보장해야 한다.', 2641);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4638, '① 수사준칙 제15조제2항에 따른 신변보호에 필요한 조치의 유형은 다음 각 호와 같다.', 2642);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4639, '② 범죄신고자 등 참고인으로서 범죄수사와 관련하여 보복을 당할 우려가 있는 경우에 관하여는 제1항을 준용한다.', 2642);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4640, null, 2643);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4641, '① 사법경찰관리는 피해자가 입은 피해의 실질적인 회복 등을 위해 필요하다고 인정하면 피해자 또는 가해자의 신청과 그 상대방의 동의에 따라 서로 대화할 수 있는 기회를 제공할 수 있다.', 2644);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4642, '② 제1항에 따라 대화 기회를 제공하는 경우 사법경찰관리는 피해자와 가해자 간 대화가 원활하게 진행될 수 있도록 전문가에게 회복적 대화 진행을 의뢰할 수 있다.', 2644);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4643, '① 사법경찰관은 수사에 필요한 장부와 서류철을 갖추어 두고 보존기간을 정하여 관리해야 한다.', 2647);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4644, '② 제1항의 장부와 서류철은 형사사법정보시스템을 통해 전자적으로 작성ㆍ저장ㆍ관리ㆍ보존할 수 있다. 이 경우 전자 장부와 서류철은 종이 장부와 서류철의 개별 항목을 포함해야 한다.', 2647);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4645, '① 수사준칙 제69조(같은 영 제16조제6항에서 준용하는 경우를 포함한다)에 따른 수사서류 열람ㆍ복사 신청은 해당 수사서류를 보유ㆍ관리하는 해양경찰관서의 장에게 해야 한다.', 2649);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4646, '② 제1항의 신청을 받은 해양경찰관서의 장은 신청을 받은 날부터 10일 이내에 다음 각 호의 어느 하나에 해당하는 결정을 해야 한다.', 2649);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4647, '③ 해양경찰관서의 장은 제2항에도 불구하고 피의자 및 사건관계인, 그 변호인이 조사 당일 본인의 진술이 기재된 조서에 대해 열람ㆍ복사를 신청하는 경우에는 공개 여부에 대해 지체 없이 검토한 후 제공 여부를 결정해야 한다.', 2649);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4648, '④ 해양경찰관서의 장은 해당 관서에서 보유ㆍ관리하지 않는 수사서류에 대해 열람ㆍ복사 신청을 접수한 경우에는 그 신청을 해당 수사서류를 보유ㆍ관리하는 기관으로 이송하거나 신청인에게 부존재 통지를 해야 한다.', 2649);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4649, '⑤ 해양경찰관서의 장은 제2항제1호 또는 제2호에 따라 수사서류를 제공하는 경우에는 사건관계인의 개인정보가 공개되지 않도록 비실명처리 등 보호조치를 해야 한다.', 2649);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4650, '⑥ 제1항부터 제5항까지에서 규정한 사항 외에 수사서류 열람ㆍ복사에 필요한 세부 사항은 해양경찰청장이 따로 정한다.', 2649);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4651, '① 사법경찰관리는 혼획ㆍ좌초 또는 표류된 고래류 신고를 접수하였을 때에는 현장조사를 하여 불법포획 등 위법행위 여부를 조사해야 한다.', 2650);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4652, '② 사법경찰관은 제1항에 따른 조사 결과, 위법행위가 확인되지 않은 경우에는 신고인이 희망하는 위판장을 지정하여 신고인에게 해양수산부장관이 정하여 고시하는 고래류 처리확인서를 발급해야 한다.', 2650);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4653, '① 사법경찰관리는 소년을 조사하는 경우에는 행위의 동기, 그 소년의 성품과 행실, 경력, 가정 상황, 교우관계, 그 밖의 환경 등을 상세히 조사하여 그 결과를 서면으로 적어야 한다.', 2652);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4654, '② 사법경찰관리는 소년에 대한 출석요구나 조사를 하는 경우에는 지체 없이 그 소년의 보호자 또는 보호자를 대신하여 소년을 보호할 수 있는 사람에게 연락해야 한다. 다만, 연락하는 것이 그 소년의 복리상 부적당하다고 인정되는 경우에는 그렇지 않다.', 2652);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4655, '③ 사법경찰관리는 소년인 피의자에 대해서는 가급적 구속을 피하고, 부득이하게 체포ㆍ구속 또는 임의동행하는 경우에는 그 시기와 방법에 특히 주의해야 한다.', 2652);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4656, '④ 사법경찰관리는 소년인 피의자가 체포ㆍ구속된 경우에는 다른 사건보다 우선하여 그 사건을 조사하는 등 신속한 수사를 위해 노력해야 한다.', 2652);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4657, '① 사법경찰관리는 외국인을 조사하는 경우에는 조사를 받는 외국인이 이해할 수 있는 언어로 통역해 주어야 한다.', 2654);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4658, '② 사법경찰관리는 외국인을 체포ㆍ구속하는 경우 국내 법령을 위반하지 않는 범위에서 영사관원과 자유롭게 접견ㆍ교통할 수 있고, 체포ㆍ구속된 사실을 영사기관에 통보해 줄 것을 요청할 수 있다는 사실을 알려야 한다.', 2654);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4659, '③ 사법경찰관리는 체포ㆍ구속된 외국인이 제2항에 따른 통보를 요청하는 경우에는 별지 제91호서식의 영사기관 체포ㆍ구속 통보서를 작성하여 지체 없이 해당 영사기관에 체포ㆍ구속 사실을 통보해야 한다.', 2654);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4660, '④ 사법경찰관리는 외국인 변사사건이 발생한 경우에는 별지 제92호서식의 영사기관 사망 통보서를 작성하여 지체 없이 해당 영사기관에 통보해야 한다.', 2654);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4661, '① 사법경찰관은 주한 미합중국 군대의 구성원ㆍ외국인군무원 및 그 가족이나 초청계약자의 범죄 관련 사건을 인지하거나 고소ㆍ고발 등을 수리한 때에는 7일 이내에 별지 제93호서식의 한미행정협정사건 통보서를 검사에게 통보해야 한다.', 2656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4662, '② 사법경찰관은 주한 미합중국 군당국으로부터 공무증명서를 제출받은 경우 지체 없이 공무증명서의 사본을 검사에게 송부해야 한다.', 2656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4663, '③ 사법경찰관은 검사로부터 주한 미합중국 군당국의 재판권포기 요청 사실을 통보받은 날부터 14일 이내에 검사에게 사건을 송치 또는 송부해야 한다. 다만, 검사의 동의를 받아 그 기간을 연장할 수 있다.', 2656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4664, '① 사법경찰관은 관계 법령에 따라 검사에게 추징보전을 신청하는 경우에는 별지 제95호서식의 추징보전 신청서에 따른다.', 2658);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4665, '② 사법경찰관은 검사에게 추징보전명령의 취소를 신청하는 경우에는 별지 제96호서식의 추징보전명령 취소 신청서에 따른다.', 2658);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4666, '① 사법경찰관리는 범죄 인지 후 1년이 지난 사건에 대해서는 수사준칙 제51조제1항에 따른 결정을 해야 한다. 다만, 다수의 사건관계인 조사, 관련 자료 추가확보ㆍ분석, 외부 전문기관 감정의 장기화, 범인 미검거 등으로 계속하여 수사가 필요한 경우에는 해당 사법경찰관리가 소속된 바로 위 상급해양경찰관서 수사 부서의 장의 승인을 받아 연장할 수 있다.', 2659);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4667, '② 사법경찰관리는 제1항 단서에 따른 승인을 받으려면 수사기간 연장의 필요성을 소명해야 한다.', 2659);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4668, '① 사법경찰관은 사건이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 사건을 다른 해양경찰관서 또는 기관에 이송해야 한다.', 2660);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4669, '② 사법경찰관은 사건이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 사건을 다른 해양경찰관서 또는 기관(해당 기관과 협의된 경우로 한정한다)에 이송할 수 있다.', 2660);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4670, '③ 사법경찰관은 제1항 또는 제2항에 따라 사건을 이송하는 경우에는 별지 제97호서식의 사건이송서를 사건기록에 편철하고 관계 서류와 증거물을 다른 해양경찰관서 또는 기관에 송부해야 한다.', 2660);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4671, '① 사법경찰관은 수사준칙 제53조에 따라 피의자와 고소인등에게 수사 결과를 통지하는 경우에는 사건을 송치하거나 사건기록을 송부한 날부터 7일 이내에 해야 한다. 다만, 피의자나 고소인등의 연락처를 모르거나 소재가 확인되지 않는 경우에는 연락처나 소재를 안 날부터 7일 이내에 통지를 해야 한다.', 2661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4672, '② 제1항의 통지(법 제245조의6에 따른 고소인등에 대한 불송치 통지는 제외한다)는 서면, 전화, 팩스, 전자우편, 문자메시지 등 피의자나 고소인등이 요청한 방법으로 할 수 있으며, 별도로 요청한 방법이 없는 경우에는 서면으로 한다. 이 경우 서면으로 하는 통지는 별지 제98호서식부터 별지 제100호서식까지의 수사결과 통지서에 따른다.', 2661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4673, '③ 법 제245조의6에 따른 고소인등에 대한 불송치 통지는 별지 제101호서식의 수사결과 통지서에 따른다.', 2661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4674, '④ 제2항 후단 및 제3항에도 불구하고 하나의 사건에 수사준칙 제51조제1항 각 호에 따른 법원송치, 검찰송치, 불송치, 수사중지 및 이송 결정이 병존하는 사건의 수사 결과를 통지하는 경우에는 별지 제101호의2서식 또는 별지 제101호의3서식의 수사결과 통지서에 따를 수 있다. <신설 2024.6.19>', 2661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4675, '⑤ 사법경찰관은 서면으로 통지한 경우에는 그 사본을, 그 외의 방법으로 통지한 경우에는 그 취지를 적은 서면을 사건기록에 편철해야 한다. <개정 2024.6.19>', 2661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4676, '⑥ 수사준칙 제53조제2항에 따른 고소인등의 통지 요구는 별지 제102호서식의 불송치 통지요구서에 따른다. <개정 2024.6.19>', 2661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4677, '⑦ 사법경찰관은 고소인, 고발인 또는 피의자가 불송치 결정에 관한 사실증명을 청구한 경우에는 지체 없이 별지 제103호서식 또는 별지 제104호서식의 불송치 결정 증명서를 발급해야 한다. <개정 2024.6.19>', 2661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4678, '⑧ 사법경찰관은 고소인등에게 수사중지 결정의 통지를 하는 경우에는 수사준칙 제54조제3항에 따라 검사에게 신고할 수 있다는 내용을 통지서에 기재해야 한다. <개정 2024.6.19>', 2661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4679, '① 사법경찰관은 다음 각 호의 구분에 해당하는 경우에는 그 사유가 해소될 때까지 수사준칙 제51조제1항제4호에 따른 수사중지 결정을 할 수 있다.', 2662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4680, '② 사법경찰관은 제1항에 따라 수사중지의 결정을 하는 경우에는 별지 제105호서식의 수사중지 결정서를 작성하여 사건기록에 편철해야 한다.', 2662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4681, '③ 사법경찰관은 수사준칙 제51조제4항에 따라 검사에게 사건기록을 송부하는 경우에는 별지 제106호서식의 수사중지 사건기록 송부서를 사건기록에 편철해야 한다.', 2662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4682, '④ 사법경찰관리는 제1항제1호나목 또는 다목의 사유로 수사중지 결정을 한 경우에는 매월 1회 이상 해당 수사중지 사유가 해소되었는지를 확인해야 한다.', 2662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4683, '① 사법경찰관은 소재불명의 사유로 수사중지를 하려는 경우에는 별지 제107호서식의 소재수사 보고서를 작성하여 사건기록에 편철해야 한다.', 2663);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4684, '② 사법경찰관리는 소재불명의 사유로 수사중지된 사건의 경우 매 분기 1회 이상 소재수사를 하는 등 수사중지 사유 해소를 위해 노력해야 한다.', 2663);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4685, '① 수사준칙 제54조제1항에 따라 이의제기를 하려는 사람은 수사중지 결정을 통지받은 날부터 30일 이내에 해당 사법경찰관이 소속된 바로 위 상급해양경찰관서의 장(이하 "소속상급해양경찰관서장"이라 한다)에게 별지 제108호서식의 수사중지 결정 이의제기서를 제출해야 한다.', 2665);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4686, '② 제1항에 따른 이의제기서는 해당 사법경찰관이 소속된 해양경찰관서에 제출할 수 있다. 이 경우 이의제기서를 제출받은 해양경찰관서의 장은 이를 지체 없이 소속상급해양경찰관서장에게 송부해야 한다.', 2665);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4687, '③ 소속상급해양경찰관서장은 제1항 또는 제2항에 따라 이의제기서를 제출받거나 송부받은 날부터 30일 이내에 다음 각 호의 구분에 따른 결정을 하고 해당 사법경찰관의 소속수사부서장에게 이를 통보해야 한다.', 2665);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4688, '④ 제3항제1호에 따른 결정을 통보받은 소속수사부서장은 지체 없이 이를 이행하고 소속상급해양경찰관서장에게 이행 결과를 보고해야 한다.', 2665);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4689, '⑤ 소속상급해양경찰관서장은 제3항의 결정을 한 날부터 7일 이내에 별지 제109호서식의 수사중지사건 이의처리결과 통지서에 처리 결과와 그 이유를 적어 이의를 제기한 사람에게 통지해야 한다.', 2665);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4690, '⑥ 사법경찰관은 제1항부터 제4항까지의 규정에 따른 절차의 진행 중에 수사준칙 제51조제4항 후단에 따라 검사의 시정조치요구를 받은 경우에는 지체 없이 소속상급해양경찰관서장에게 보고해야 한다.', 2665);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4691, '① 사법경찰관은 수사중지된 사건의 피의자를 발견하는 등 수사중지 사유가 해소된 때에는 별지 제110호서식의 수사중지사건 수사재개서를 작성하여 사건기록에 편철하고 즉시 수사를 진행해야 한다.', 2666);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4692, '② 사법경찰관은 수사준칙 제51조제5항 전단에 따라 피의자 등의 소재 발견 및 수사 재개 사실을 검사에게 통보하는 경우에는 별지 제111호서식의 피의자 등 소재발견 통보서에 따른다.', 2666);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4693, '① 수사준칙 제58조제1항에 따른 송치 결정서는 별지 제112호서식에 따르고, 압수물 총목록은 별지 제113호서식에 따르며, 기록목록은 별지 제114호서식에 따른다.', 2667);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4694, '② 송치 서류는 다음 순서에 따라 편철한다.', 2667);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4695, '③ 수사준칙 제58조에 따라 사건을 송치하는 경우에는 소속해양경찰관서장 또는 소속수사부서장의 명의로 한다.', 2667);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4696, '④ 제1항의 송치 결정서는 사법경찰관이 작성해야 한다.', 2667);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4697, '① 사법경찰관은 법 제197조의2제2항에 따라 보완수사 이행 결과를 통보하는 경우에는 별지 제117호서식의 보완수사 결과 통보서에 따른다. 다만, 수사준칙 제59조에 따른 보완수사요구의 대상이 아니거나 그 범위를 벗어난 경우 등 정당한 이유가 있어 보완수사를 이행하지 않은 경우에는 그 내용과 사유를 보완수사 결과 통보서에 적어 검사에게 통보해야 한다.', 2669);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4698, '② 사법경찰관은 법 제197조의2제1항제1호에 따른 보완수사요구 결과를 통보하면서 새로운 증거물, 서류 및 그 밖의 자료를 검사에게 송부하는 경우에는 수사준칙 제58조제3항에 따른다.', 2669);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4699, '③ 사법경찰관은 법 제197조의2제1항제2호에 따른 보완수사요구를 이행한 경우에는 다음 각 호의 구분에 따라 처리한다.', 2669);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4700, '④ 사법경찰관은 수사준칙 제60조제5항에 따라 사건을 불송치하거나 수사중지하는 경우에는 기존 송치 결정을 취소해야 한다. <개정 2024.6.19>', 2669);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4701, '① 소속해양경찰관서장은 수사준칙 제61조제2항에 따라 직무배제를 하는 경우 지체 없이 사건 담당 사법경찰관리를 교체해야 한다.', 2670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4702, '② 소속해양경찰관서장은 수사준칙 제61조제3항에 따라 직무배제 또는 징계 요구의 처리 결과와 그 이유를 통보하는 경우에는 별지 제118호서식의 직무배제요구 처리결과 통보서 또는 별지 제87호서식의 징계요구 처리결과 통보서에 따른다.', 2670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4703, '① 해양경찰서장은 「소년법」 제4조제2항에 따라 소년 보호사건을 법원에 송치하는 경우에는 별지 제119호서식의 소년 보호사건 송치서를 작성하여 사건기록에 편철하고 관계 서류와 증거물을 관할 가정법원 소년부 또는 지방법원 소년부에 송부해야 한다.', 2671);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4704, '② 제1항의 송치 서류에 관하여는 제105조를 준용한다.', 2671);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4705, '① 불송치 결정의 주문(主文)은 다음과 같이 한다. <개정 2024.6.19>', 2672);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4706, '② 사법경찰관은 압수물의 환부 또는 가환부를 받을 사람이 없는 등 특별한 사유가 있는 경우를 제외하고는 제1항에 따른 결정을 하기 전에 압수물 처분을 완료하도록 노력해야 한다. 수사준칙 제64조제1항제2호에 따라 재수사 결과를 처리하는 경우에도 또한 같다.', 2672);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4707, '① 수사준칙 제62조제1항에 따른 불송치 결정서는 별지 제120호서식에 따르고, 압수물 총목록은 별지 제113호서식에 따르며, 기록목록은 별지 제114호서식에 따른다.', 2673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4708, '② 불송치 서류는 다음 순서에 따라 편철한다.', 2673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4709, '③ 불송치 사건기록 송부서 명의인 및 불송치 결정서 작성인에 관하여는 제105조제3항 및 제4항을 준용한다.', 2673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4710, '① 하나의 사건에 수사준칙 제51조제1항제2호부터 제4호까지의 규정에 따른 검찰송치, 불송치 및 수사중지 결정이 병존하는 병존사건의 경우 사법경찰관은 기록을 분리하여 송치 및 송부하도록 노력해야 한다.', 2674);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4711, '② 제1항에도 불구하고 기록을 분리할 수 없는 경우에 사법경찰관은 관계 서류와 증거물을 원본과 다름이 없음을 인증하여 등사 보관하고 송치 결정서, 불송치 결정서 및 수사중지 결정서를 작성하여 그 결정서별로 압수물 총목록과 기록목록 등을 첨부한 후 각 별책으로 편철하여 관계 서류와 증거물 원본과 함께 검사에게 송치 및 송부한다.', 2674);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4712, '③ 검사가 제2항에 따라 송치 및 송부된 사건을 공소제기(수사준칙 제52조제1항제7호에 따른 이송 중 타 기관 이송 및 같은 항 제8호부터 제11호까지의 규정에 따른 사건송치 결정을 포함한다)한 이후, 사법경찰관이 고소인등의 이의신청에 따라 사건을 송치하거나 수사중지 사건을 재개수사하여 송치 또는 송부할 때에는 추가된 새로운 증거물, 관계 서류와 함께 제2항의 관계 서류와 증거물 등본 중 관련 부분을 검사에게 송부해야 한다. 다만, 고소인등의 이의신청이나 수사중지 사건의 재개에 따라 불송치하거나 수사중지 결정한 부분을 모두 송치 또는 송부하는 경우에는 등본 전체를 검사에게 송부해야 한다.', 2674);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4713, '① 사법경찰관은 수사준칙 제64조제1항제1호에 따라 사건을 송치하는 경우에는 기존 불송치 결정을 취소해야 한다.', 2676);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4714, '② 사법경찰관은 수사준칙 제64조제2항 단서에 따라 사건을 송치하는 경우에는 기존 불송치 결정을 변경해야 한다.', 2676);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4715, '③ 수사준칙 제64조제1항제2호에 따른 재수사 결과서는 별지 제122호서식에 따른다.', 2676);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4716, '① 법 제245조의7제1항에 따른 이의신청은 별지 제123호서식의 불송치 결정 이의신청서에 따른다.', 2677);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4717, '② 사법경찰관은 제1항의 이의신청이 있는 경우 지체 없이 수사준칙 제58조제1항에 따라 사건을 송치한다. 이 경우 관계 서류와 증거물을 검사가 보관하는 경우(제112조제3항을 적용받는 경우는 제외한다)에는 관계 서류 및 증거물을 송부하지 않고 사건송치서 및 송치 결정서만으로 사건을 송치한다.', 2677);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4718, '③ 사법경찰관은 법 제245조의7제2항에 따라 신청인에게 통지하는 경우에는 서면, 전화, 팩스, 전자우편, 문자메시지 등 신청인이 요청한 방법으로 통지할 수 있으며, 별도로 요청한 방법이 없는 경우에는 서면 또는 문자메시지로 한다. 이 경우 서면으로 하는 통지는 별지 제124호서식의 이의신청에 따른 사건송치 통지서에 따른다.', 2677);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4719, '④ 사법경찰관은 법 제245조의7제2항에 따라 사건을 송치하는 경우에는 기존 불송치 결정을 변경해야 한다.', 2677);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4720, null, 2679);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4721, '① 소년원장 또는 소년분류심사원장(이하 "원장"이라 한다)은 보호소년등을 처우할 때에 인권보호를 우선적으로 고려하여야 하며, 그들의 심신 발달 과정에 알맞은 환경을 조성하고 안정되고 규율있는 생활 속에서 보호소년등의 성장 가능성을 최대한으로 신장시킴으로써 사회적응력을 길러 건전한 청소년으로서 사회에 복귀할 수 있도록 하여야 한다. <개정 2013.7.30, 2020.10.20>', 2680);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4722, '② 보호소년에게는 품행의 개선과 진보의 정도에 따라 점차 향상된 처우를 하여야 한다.', 2680);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4723, '① 소년원은 보호소년을 수용하여 교정교육을 하는 것을 임무로 한다. <개정 2013.7.30, 2020.10.20>', 2681);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4724, '② 소년분류심사원은 다음 각 호의 임무를 수행한다. <개정 2013.7.30, 2020.10.20>', 2681);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4725, '①소년원과 소년분류심사원은 법무부장관이 관장한다.', 2682);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4726, '② 소년원과 소년분류심사원의 명칭, 위치, 직제(職制), 그 밖에 필요한 사항은 대통령령으로 정한다.', 2682);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4727, '①법무부장관은 보호소년의 처우상 필요하다고 인정하면 대통령령으로 정하는 바에 따라 소년원을 초ㆍ중등교육, 직업능력개발훈련, 의료재활 등 기능별로 분류하여 운영하게 할 수 있다. <개정 2013.7.30>', 2683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4728, '② 법무부장관은 제1항에 따라 의료재활 기능을 전문적으로 수행하는 소년원을 의료재활소년원으로 운영한다. <개정 2020.10.20>', 2683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4729, '① 신설하는 소년원 및 소년분류심사원은 수용정원이 150명 이내의 규모가 되도록 하여야 한다. 다만, 소년원 및 소년분류심사원의 기능ㆍ위치나 그 밖의 사정을 고려하여 그 규모를 증대할 수 있다.', 2684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4730, '② 보호소년등의 개별적 특성에 맞는 처우를 위하여 소년원 및 소년분류심사원에 두는 생활실은 대통령령으로 정하는 바에 따라 소규모로 구성하여야 한다.', 2684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4731, '③ 소년원 및 소년분류심사원의 생활실이나 그 밖의 수용생활을 위한 설비는 그 목적과 기능에 맞도록 설치되어야 한다.', 2684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4732, '④ 소년원 및 소년분류심사원의 생활실은 보호소년등의 건강한 생활과 성장을 위하여 적정한 수준의 공간과 채광ㆍ통풍ㆍ난방을 위한 시설이 갖추어져야 한다.', 2684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4733, '① 보호소년등을 소년원이나 소년분류심사원에 수용할 때에는 법원소년부의 결정서, 법무부장관의 이송허가서 또는 지방법원 판사의 유치허가장에 의하여야 한다. <개정 2016.3.29>', 2685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4734, '② 원장은 새로 수용된 보호소년등에 대하여 지체 없이 건강진단과 위생에 필요한 조치를 하여야 한다.', 2685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4735, '③ 원장은 새로 수용된 보호소년등의 보호자나 보호소년등이 지정하는 자(이하 "보호자등"이라 한다)에게 지체 없이 수용 사실을 알려야 한다.', 2685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4736, '① 원장은 보호소년등의 정신적ㆍ신체적 상황 등 개별적 특성을 고려하여 생활실을 구분하는 등 적합한 처우를 하여야 한다. <개정 2016.3.29>', 2686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4737, '② 보호소년등은 다음 각 호의 기준에 따라 분리 수용한다. <개정 2016.3.29, 2018.9.18>', 2686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4738, '③ 「소년법」 제32조제1항제7호의 처분을 받은 보호소년은 의료재활소년원에 해당하는 소년원에 수용하여야 한다. <신설 2013.7.30, 2020.10.20>', 2686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4739, '④ 원장은 보호소년등이 희망하거나 특별히 보호소년등의 개별적 특성에 맞는 처우가 필요한 경우 보호소년등을 혼자 생활하게 할 수 있다. <신설 2020.10.20>', 2686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4740, '① 소년원장은 보호소년이 다음 각 호의 어느 하나에 해당하는 경우에는 소년원 소재지를 관할하는 법원소년부에 「소년법」 제37조에 따른 보호처분의 변경을 신청할 수 있다.', 2688);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4741, '② 소년분류심사원장은 위탁소년이 제1항 각 호의 어느 하나에 해당하는 경우에는 위탁 결정을 한 법원소년부에 「소년법」 제18조에 따른 임시조치의 취소, 변경 또는 연장에 관한 의견을 제시할 수 있다.', 2688);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4742, '③ 소년분류심사원장은 유치소년이 제1항제1호 또는 제2호에 해당하는 경우에는 유치 허가를 한 지방법원 판사 또는 소년분류심사원 소재지를 관할하는 법원소년부에 유치 허가의 취소에 관한 의견을 제시할 수 있다.', 2688);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4743, '④ 제3항에 따른 의견 제시 후 지방법원 판사 또는 법원소년부 판사의 유치 허가 취소 결정이 있으면 소년분류심사원장은 그 유치소년을 관할하는 보호관찰소장에게 이를 즉시 통보하여야 한다.', 2688);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4744, '⑤ 제1항에 따른 보호처분의 변경을 할 경우 보호소년이 19세 이상인 경우에도 「소년법」 제2조 및 제38조제1항에도 불구하고 같은 법 제2장의 보호사건 규정을 적용한다.', 2688);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4745, '①소년원장은 분류수용, 교정교육상의 필요, 그 밖의 이유로 보호소년을 다른 소년원으로 이송하는 것이 적당하다고 인정하면 법무부장관의 허가를 받아 이송할 수 있다. <개정 2013.7.30>', 2691);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4746, '② 「소년법」 제32조제1항제7호의 처분을 받은 보호소년은 의료재활소년원에 해당하지 아니하는 소년원으로 이송할 수 없다. <신설 2013.7.30, 2020.10.20>', 2691);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4747, '① 원장은 천재지변이나 그 밖의 재난 또는 비상사태에 대비하여 계획을 수립하고 보호소년등에게 대피훈련 등 필요한 훈련을 실시하여야 한다.', 2692);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4748, '② 원장은 천재지변이나 그 밖의 재난 또는 비상사태가 발생한 경우에 그 시설 내에서는 안전한 대피방법이 없다고 인정될 때에는 보호소년등을 일시적으로 적당한 장소로 긴급 이송할 수 있다.', 2692);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4749, '① 원장은 보호소년등이 이탈, 난동, 폭행, 자해(自害), 그 밖의 사고를 일으킬 우려가 있을 때에는 이를 방지하는 데에 필요한 조치를 하여야 한다.', 2693);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4750, '② 보호소년등이 소년원이나 소년분류심사원을 이탈하였을 때에는 그 소속 공무원이 재수용할 수 있다.', 2693);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4751, '① 보호장비의 종류는 다음 각 호와 같다. <개정 2013.7.30, 2016.3.29, 2020.10.20>', 2694);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4752, '② 원장은 다음 각 호의 어느 하나에 해당하는 경우에는 소속 공무원으로 하여금 보호소년등에 대하여 수갑, 포승 또는 보호대를 사용하게 할 수 있다. <개정 2013.7.30, 2020.10.20>', 2694);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4753, '③ 원장은 다음 각 호의 어느 하나에 해당하는 경우에는 소속 공무원으로 하여금 보호소년등에 대하여 수갑, 포승 또는 보호대 외에 가스총이나 전자충격기를 사용하게 할 수 있다. <신설 2013.7.30, 2016.3.29, 2020.10.20>', 2694);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4754, '④ 제3항에 따라 가스총이나 전자충격기를 사용하려면 사전에 상대방에게 이를 경고하여야 한다. 다만, 상황이 급박하여 경고할 시간적인 여유가 없는 때에는 그러하지 아니하다. <신설 2013.7.30>', 2694);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4755, '⑤ 원장은 보호소년등이 자해할 우려가 큰 경우에는 소속 공무원으로 하여금 보호소년등에게 머리보호장비를 사용하게 할 수 있다. <신설 2016.3.29>', 2694);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4756, '⑥ 보호장비는 필요한 최소한의 범위에서 사용하여야 하며, 보호장비를 사용할 필요가 없게 되었을 때에는 지체 없이 사용을 중지하여야 한다. <개정 2013.7.30, 2016.3.29>', 2694);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4757, '⑦ 보호장비는 징벌의 수단으로 사용되어서는 아니 된다. <신설 2013.7.30, 2016.3.29>', 2694);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4758, '⑧ 보호장비의 사용방법 및 관리에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2013.7.30, 2016.3.29>', 2694);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4759, '① 소년원 및 소년분류심사원에는 보호소년등의 이탈ㆍ난동ㆍ폭행ㆍ자해ㆍ자살, 그 밖에 보호소년등의 생명ㆍ신체를 해치거나 시설의 안전 또는 질서를 해치는 행위(이하 이 조에서 "자해등"이라 한다)를 방지하기 위하여 필요한 최소한의 범위에서 전자장비를 설치하여 운영할 수 있다. <개정 2016.3.29>', 2695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4760, '② 보호소년등이 사용하는 목욕탕, 세면실 및 화장실에 전자영상장비를 설치하여 운영하는 것은 자해등의 우려가 큰 때에만 할 수 있다. 이 경우 전자영상장비로 보호소년등을 감호할 때에는 여성인 보호소년등에 대해서는 여성인 소속 공무원만, 남성인 보호소년등에 대해서는 남성인 소속 공무원만이 참여하여야 한다. <개정 2016.3.29>', 2695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4761, '③ 제1항 및 제2항에 따라 전자장비를 설치ㆍ운영할 때에는 보호소년등의 인권이 침해되지 아니하도록 하여야 한다. <개정 2016.3.29>', 2695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4762, '④ 전자장비의 종류ㆍ설치장소ㆍ사용방법 및 녹화기록물의 관리 등에 필요한 사항은 법무부령으로 정한다. <개정 2016.3.29>', 2695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4763, null, 2696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4764, '① 원장은 보호소년등이 제14조의4 각 호의 어느 하나에 해당하는 행위를 하면 제15조의2제1항에 따른 보호소년등처우ㆍ징계위원회의 의결에 따라 다음 각 호의 어느 하나에 해당하는 징계를 할 수 있다. <개정 2016.3.29, 2020.10.20>', 2697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4765, '② 제1항제3호부터 제6호까지의 처분은 함께 부과할 수 있다. <신설 2016.3.29>', 2697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4766, '③ 제1항제7호의 처분은 14세 미만의 보호소년등에게는 부과하지 못한다. <신설 2016.3.29>', 2697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4767, '④ 원장은 제1항제7호의 처분을 받은 보호소년등에게 개별적인 체육활동 시간을 보장하여야 한다. 이 경우 매주 1회 이상 실외운동을 할 수 있도록 하여야 한다. <신설 2020.10.20>', 2697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4768, '⑤ 제1항제7호의 처분을 받은 보호소년등에게는 그 기간 중 같은 항 제4호부터 제6호까지의 처우 제한이 함께 부과된다. 다만, 원장은 보호소년등의 교화 또는 건전한 사회복귀를 위하여 특히 필요하다고 인정하면 텔레비전 시청, 단체 체육활동 또는 공동행사 참가를 허가할 수 있다. <신설 2016.3.29, 2020.10.20>', 2697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4769, '⑥ 소년원장은 보호소년이 제1항 각 호의 어느 하나에 해당하는 징계를 받은 경우에는 법무부령으로 정하는 기준에 따라 교정성적 점수를 빼야 한다. <개정 2016.3.29, 2020.10.20>', 2697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4770, '⑦ 징계는 당사자의 심신상황을 고려하여 교육적으로 하여야 한다. <개정 2016.3.29, 2020.10.20>', 2697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4771, '⑧ 원장은 보호소년등에게 제1항에 따라 징계를 한 경우에는 지체 없이 그 사실을 보호자에게 통지하여야 한다. <신설 2016.3.29, 2020.10.20>', 2697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4772, '⑨ 원장은 징계를 받은 보호소년등의 보호자와 상담을 할 수 있다. <신설 2016.3.29, 2020.10.20>', 2697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4773, '① 보호소년등의 처우에 관하여 원장의 자문에 응하게 하거나 징계대상자에 대한 징계를 심의ㆍ의결하기 위하여 소년원 및 소년분류심사원에 보호소년등처우ㆍ징계위원회를 둔다.', 2698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4774, '② 제1항에 따른 보호소년등처우ㆍ징계위원회(이하 "위원회"라 한다)는 위원장을 포함한 5명 이상 11명 이하의 위원으로 구성하고, 민간위원은 1명 이상으로 한다.', 2698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4775, '③ 위원회가 징계대상자에 대한 징계를 심의ㆍ의결하는 경우에는 1명 이상의 민간위원이 해당 심의ㆍ의결에 참여하여야 한다.', 2698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4776, '④ 위원회는 소년보호에 관한 학식과 경험이 풍부한 외부인사로부터 의견을 들을 수 있다.', 2698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4777, '⑤ 제1항부터 제4항까지에서 규정한 사항 외에 위원회의 구성과 운영 등에 필요한 사항은 대통령령으로 정한다.', 2698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4778, '⑥ 위원회의 위원 중 공무원이 아닌 사람은 「형법」 제127조 및 제129조부터 제132조까지의 규정을 적용할 때에는 공무원으로 본다.', 2698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4779, '① 원장은 교정성적이 우수하거나 품행이 타인의 모범이 되는 보호소년등에게 포상을 할 수 있다.', 2699);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4780, '② 원장은 제1항에 따라 포상을 받은 보호소년등에게는 특별한 처우를 할 수 있다.', 2699);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4781, '① 보호소년등에게는 의류, 침구, 학용품, 그 밖에 처우에 필요한 물품을 주거나 대여한다.', 2700);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4782, '② 보호소년등에게는 주식, 부식, 음료, 그 밖의 영양물을 제공하되, 그 양은 보호소년등이 건강을 유지하고 심신의 발육을 증진하는 데에 필요한 정도이어야 한다.', 2700);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4783, '③ 제1항 및 제2항에 따른 급여품과 대여품의 종류와 수량의 기준은 법무부령으로 정한다.', 2700);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4784, '① 원장은 비행집단과 교제하고 있다고 의심할 만한 상당한 이유가 있는 경우 등 보호소년등의 보호 및 교정교육에 지장이 있다고 인정되는 경우 외에는 보호소년등의 면회를 허가하여야 한다. 다만, 제15조제1항제7호의 징계를 받은 보호소년등에 대한 면회는 그 상대방이 변호인이나 보조인(이하 "변호인등"이라 한다) 또는 보호자인 경우에 한정하여 허가할 수 있다. <개정 2016.3.29>', 2701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4785, '② 보호소년등이 면회를 할 때에는 소속 공무원이 참석하여 보호소년등의 보호 및 교정교육에 지장이 없도록 지도할 수 있다. 이 경우 소속 공무원은 보호소년등의 보호 및 교정교육에 지장이 있다고 인정되는 경우에는 면회를 중지할 수 있다. <개정 2016.3.29>', 2701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4786, '③ 제2항 전단에도 불구하고 보호소년등이 변호인등과 면회를 할 때에는 소속 공무원이 참석하지 아니한다. 다만, 보이는 거리에서 보호소년등을 지켜볼 수 있다. <개정 2016.3.29>', 2701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4787, '④ 원장은 공동으로 비행을 저지른 관계에 있는 사람의 편지인 경우 등 보호소년등의 보호 및 교정교육에 지장이 있다고 인정되는 경우에는 보호소년등의 편지 왕래를 제한할 수 있으며, 편지의 내용을 검사할 수 있다. <개정 2016.3.29>', 2701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4788, '⑤ 제4항에도 불구하고 보호소년등이 변호인등과 주고받는 편지는 제한하거나 검사할 수 없다. 다만, 상대방이 변호인등임을 확인할 수 없는 때에는 예외로 한다. <개정 2016.3.29>', 2701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4789, '⑥ 원장은 공범 등 교정교육에 해가 된다고 인정되는 사람과의 전화통화를 제한하는 등 보호소년등의 보호 및 교정교육에 지장을 주지 아니하는 범위에서 가족 등과 전화통화를 허가할 수 있다. <신설 2013.7.30, 2016.3.29>', 2701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4790, '⑦ 제1항과 제2항에 따른 면회 허가의 제한과 면회 중지, 제4항에 따른 편지 왕래의 제한 및 제6항에 따른 전화통화의 제한 사유에 관한 구체적인 범위는 대통령령으로 정한다. <신설 2016.3.29>', 2701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4791, '⑧ 제6항에 따른 전화통화를 위하여 소년원 및 소년분류심사원에 설치하는 전화기의 운영에 필요한 사항은 법무부장관이 정한다. <신설 2016.3.29>', 2701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4792, null, 2702);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4793, '① 원장은 보호소년등이 질병에 걸리면 지체 없이 적정한 치료를 받도록 하여야 한다.', 2703);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4794, '② 원장은 소년원이나 소년분류심사원에서 제1항에 따른 치료를 하는 것이 곤란하다고 인정되면 외부 의료기관에서 치료를 받게 할 수 있다.', 2703);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4795, '③ 원장은 보호소년등이나 그 보호자등이 자비(自費)로 치료받기를 원할 때에는 이를 허가할 수 있다.', 2703);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4796, '④ 소년원 및 소년분류심사원에 근무하는 간호사는 「의료법」 제27조에도 불구하고 야간 또는 공휴일 등 의사가 진료할 수 없는 경우 대통령령으로 정하는 경미한 의료행위를 할 수 있다. <신설 2020.10.20>', 2703);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4797, '① 소년원 및 소년분류심사원에 근무하는 의사와 간호사는 보호소년등에 대한 진료기록부, 간호기록부, 그 밖의 진료에 관한 기록(이하 "진료기록부등"이라 한다)을 소년원과 소년분류심사원의 정보를 통합적으로 관리하기 위하여 법무부장관이 운영하는 정보시스템에 입력하여야 한다.', 2704);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4798, '② 법무부장관은 진료기록부등을 법무부령으로 정하는 바에 따라 보존하여야 한다.', 2704);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4799, '① 의료재활소년원장은 의료재활소년원 출원생(出院生)이 외래진료를 신청하는 경우 의료재활소년원에서 검사, 투약 등 적절한 진료 및 치료를 받도록 할 수 있다.', 2705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4800, '② 법무부장관은 의료재활소년원 출원생이 신청하는 경우 「치료감호 등에 관한 법률」 제16조의2제1항제2호에 따른 법무부장관이 지정하는 기관에서 외래진료를 받도록 할 수 있다. 이 경우 법무부장관은 예산의 범위에서 진료비용을 지원할 수 있다.', 2705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4801, '③ 제1항 및 제2항에 따른 외래진료의 기간과 방법 및 진료비용 지원 등에 필요한 사항은 법무부령으로 정한다.', 2705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4802, '① 원장은 소년원이나 소년분류심사원에서 감염병이 발생하거나 발생할 우려가 있을 때에는 이에 대한 상당한 조치를 하여야 한다. <개정 2009.12.29>', 2706);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4803, '② 원장은 보호소년등이 감염병에 걸렸을 때에는 지체 없이 격리 수용하고 필요한 응급조치를 하여야 한다. <개정 2009.12.29>', 2706);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4804, '① 원장은 보호소년등이 갖고 있던 금전, 의류, 그 밖의 물품을 보관하는 경우에는 이를 안전하게 관리하고 보호소년등에게 수령증을 내주어야 한다.', 2707);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4805, '② 원장은 보호소년등의 퇴원, 임시퇴원, 사망, 이탈 등의 사유로 금품을 계속 보관할 필요가 없게 되었을 때에는 본인이나 보호자등에게 반환하여야 한다. <개정 2013.7.30>', 2707);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4806, '③ 제2항에 따라 반환되지 아니한 금품은 퇴원, 임시퇴원, 사망, 이탈 등의 사유가 발생한 날부터 1년 이내에 본인이나 보호자등이 반환 요청을 하지 아니하면 국고에 귀속하거나 폐기한다. <개정 2013.7.30>', 2707);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4807, '① 분류심사는 제3조제2항에 해당하는 소년의 신체, 성격, 소질, 환경, 학력 및 경력 등에 대한 조사를 통하여 비행 또는 범죄의 원인을 규명하여 심사대상인 소년의 처우에 관하여 최선의 지침을 제시함을 목적으로 한다. <개정 2020.10.20>', 2709);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4808, '② 분류심사를 할 때에는 심리학ㆍ교육학ㆍ사회학ㆍ사회복지학ㆍ범죄학ㆍ의학 등의 전문적인 지식과 기술에 근거하여 보호소년등의 신체적ㆍ심리적ㆍ환경적 측면 등을 조사ㆍ판정하여야 한다.', 2709);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4809, '① 제3조제2항에 따른 임무를 수행하기 위하여 소년분류심사원에 분류심사관을 둔다. <개정 2020.10.20>', 2710);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4810, '② 분류심사관은 제24조제2항에 따른 학문적 소양과 전문지식을 갖추어야 한다.', 2710);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4811, '① 소년분류심사원장은 제3조제2항제1호부터 제4호까지의 규정에 따른 분류심사 또는 조사 결과와 의견 등을 각각 법원소년부 또는 검사에게 통지하여야 한다. <개정 2013.7.30, 2020.10.20>', 2712);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4812, '② 소년분류심사원장은 제3조제2항제1호부터 제3호까지에 규정된 소년이 보호처분의 결정을 받으면 그 소년의 분류심사 결과 및 의견 또는 상담조사 결과 및 의견을 지체 없이 그 처분을 집행하는 소년원이나 보호관찰소에서 정보시스템으로 열람할 수 있도록 통지하여야 한다. <개정 2013.7.30, 2020.10.20>', 2712);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4813, '③ 소년분류심사원장은 제3조제2항제5호에 따른 분류심사 또는 제26조에 따른 청소년심리검사 등을 하였을 때에는 그 결과를 각각 분류심사 또는 심리검사 등을 의뢰한 자에게 통지하고 필요한 의견을 제시할 수 있다. <개정 2013.7.30, 2020.10.20>', 2712);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4814, '① 소년원학교에 대하여는 「초ㆍ중등교육법」 제4조, 제10조, 제11조, 제18조, 제18조의2, 제30조의2, 제30조의3, 제31조, 제31조의2, 제32조부터 제34조까지, 제34조의2 및 제63조부터 제65조까지의 규정을 적용하지 아니한다. <개정 2013.7.30, 2016.3.29>', 2715);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4815, '② 소년원학교에 대하여 「초ㆍ중등교육법」 제6조부터 제9조까지의 규정을 적용할 때에는 "교육부장관"을 "법무부장관"으로 본다. <개정 2011.4.5, 2013.3.23>', 2715);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4816, '③ 교육부장관은 「교육기본법」 및 「초ㆍ중등교육법」에 관한 사항(제1항에 따라 적용이 배제되는 사항은 제외한다)에 대하여 법무부장관에게 필요한 권고를 할 수 있으며, 법무부장관은 정당한 사유를 제시하지 아니하는 한 이에 따라야 한다. <개정 2011.4.5, 2013.3.23>', 2715);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4817, '① 소년원학교에는 「초ㆍ중등교육법」 제21조제2항에 따른 자격을 갖춘 교원을 두되, 교원은 일반직공무원으로 임용할 수 있다.', 2717);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4818, '② 제1항에 따라 일반직공무원으로 임용된 교원의 경력ㆍ연수 및 직무 수행 등에 관하여 필요한 사항은 대통령령으로 정한다. 이 경우 「교육기본법」 및 「교육공무원법」에 따라 임용된 교원과 동등한 처우를 받도록 하여야 한다.', 2717);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4819, '③ 제1항과 제2항에도 불구하고 소년원학교의 교장(이하 "소년원학교장"이라 한다)은 소년원학교가 설치된 소년원의 장이, 교감은 그 소년원의 교육과정을 총괄하는 부서의 장으로서 대통령령으로 정하는 자가 겸직할 수 있다.', 2717);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4820, '④ 소년원학교장은 소년원학교의 교육과정을 원활하게 운영하기 위하여 필요하면 관할 교육청의 장에게 소년원학교 교사와 다른 중ㆍ고등학교 교사간 교환수업 등 상호 교류협력을 요청할 수 있다.', 2717);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4821, '① 보호소년이 소년원학교에 입교하면 「초ㆍ중등교육법」에 따라 입학ㆍ전학 또는 편입학한 것으로 본다.', 2718);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4822, '② 「초ㆍ중등교육법」 제2조의 학교에서 재학하던 중 소년분류심사원에 위탁되거나 유치된 소년 및 「소년법」 제32조제1항제8호의 처분을 받은 소년의 수용기간은 그 학교의 수업일수로 계산한다. <개정 2013.7.30>', 2718);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4823, '③ 소년원학교장은 보호소년이 입교하면 그 사실을 보호소년이 최종적으로 재학했던 학교[이하 "전적학교(前籍學校)"라 한다]의 장에게 통지하고 그 보호소년의 학적에 관한 자료를 보내줄 것을 요청할 수 있다.', 2718);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4824, '④ 제3항에 따른 요청을 받은 전적학교의 장은 교육의 계속성을 유지하는 데에 필요한 학적사항을 지체 없이 소년원학교장에게 보내야 한다.', 2718);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4825, '① 소년원학교에서 교육과정을 마친 보호소년이 전적학교의 졸업장 취득을 희망하는 경우 소년원학교장은 전적학교의 장에게 학적사항을 통지하고 졸업장의 발급을 요청할 수 있다.', 2721);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4826, '② 제1항에 따른 요청을 받은 전적학교의 장은 정당한 사유를 제시하지 아니하는 한 졸업장을 발급하여야 한다. 이 경우 그 보호소년에 관한 소년원학교의 학적사항은 전적학교의 학적사항으로 본다.', 2721);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4827, '① 소년원의 직업능력개발훈련은 「국민 평생 직업능력 개발법」으로 정하는 바에 따른다. <개정 2021.8.17>', 2722);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4828, '② 소년원장은 법무부장관의 허가를 받아 산업체의 기술지원이나 지원금으로 직업능력개발훈련을 실시하거나 소년원 외의 시설에서 직업능력개발훈련을 실시할 수 있다.', 2722);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4829, '③ 고용노동부장관은 보호소년의 직업능력개발훈련에 관하여 법무부장관에게 필요한 권고를 할 수 있다. <개정 2010.6.4>', 2722);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4830, '① 소년원장은 보호소년이 직업능력개발훈련과정을 마쳤을 때에는 산업체에 통근취업하게 할 수 있다.', 2724);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4831, '② 소년원장은 보호소년이 제1항에 따라 취업을 하였을 때에는 해당 산업체로 하여금 「근로기준법」을 지키게 하고, 보호소년에게 지급되는 보수는 전부 본인에게 지급하여야 한다.', 2724);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4832, '① 소년원장은 직업능력개발훈련을 실시할 때 보호소년에게 해롭거나 위험한 일을 하게 하여서는 아니 된다.', 2725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4833, '② 소년원장은 직업능력개발훈련을 실시할 때 기계, 기구, 재료, 그 밖의 시설 등에 의하여 보호소년에게 위해가 발생할 우려가 있으면 이를 방지하는 데에 필요한 조치를 하여야 한다.', 2725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4834, '① 소년원장은 보호소년의 연령, 학력, 적성, 진로, 교정의 난이도 등을 고려하여 처우과정을 정하고 교정목표를 조기에 달성할 수 있도록 교육계획을 수립ㆍ시행하여야 한다.', 2728);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4835, '② 소년원장은 제1항의 교육계획에 따른 교육과정을 운영하고 법무부장관이 정하는 바에 따라 그 결과를 평가하여 출원(出院), 포상 등 보호소년의 처우에 반영할 수 있다.', 2728);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4836, '① 소년원 및 소년분류심사원은 청소년 등에게 비행예방 및 재범방지 또는 사회적응을 위한 체험과 인성 위주의 교육을 실시하기 위하여 다음 각 호의 교육과정(이하 "대안교육과정"이라 한다)을 운영한다.', 2730);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4837, '② 원장은 행정기관, 지방자치단체, 학교, 그 밖의 단체 등과 협력하여 지역사회의 청소년 비행을 예방하기 위하여 적극 노력하여야 한다.', 2730);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4838, '③ 대안교육과정의 운영에 필요한 사항은 법무부령으로 정한다.', 2730);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4839, '① 소년원과 소년분류심사원은 「소년법」 제32조의2제3항에 따라 교육명령을 받은 보호자 또는 보호소년등의 보호자를 대상으로 역할개선 중심의 보호자교육과정을 운영한다.', 2731);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4840, '② 제1항에 따른 보호자교육의 절차 및 방법 등에 관하여 필요한 사항은 대통령령으로 정한다.', 2731);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4841, '① 소년원장은 보호소년이 22세가 되면 퇴원시켜야 한다.', 2732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4842, '② 소년원장은 「소년법」 제32조제1항제8호 또는 같은 법 제33조제1항ㆍ제5항ㆍ제6항에 따라 수용상한기간에 도달한 보호소년은 즉시 퇴원시켜야 한다. <개정 2013.7.30>', 2732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4843, '③ 소년원장은 교정성적이 양호하며 교정의 목적을 이루었다고 인정되는 보호소년(「소년법」 제32조제1항제8호에 따라 송치된 보호소년은 제외한다)에 대하여는 「보호관찰 등에 관한 법률」에 따른 보호관찰심사위원회에 퇴원을 신청하여야 한다. <개정 2016.3.29>', 2732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4844, '④ 위탁소년 또는 유치소년의 소년분류심사원 퇴원은 법원소년부의 결정서에 의하여야 한다. <개정 2013.7.30>', 2732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4845, '① 소년원장은 보호소년의 퇴원 또는 임시퇴원이 허가되면 지체 없이 보호자등에게 보호소년의 인도에 관하여 알려야 한다.', 2735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4846, '② 소년원장은 퇴원 또는 임시퇴원이 허가된 보호소년을 보호자등에게 직접 인도하여야 한다. 다만, 보호소년의 보호자등이 없거나 제44조의2 본문에 따른 출원예정일부터 10일 이내에 보호자등이 인수하지 아니하면 사회복지단체, 독지가, 그 밖의 적당한 자에게 인도할 수 있다. <개정 2016.3.29>', 2735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4847, '③ 제2항 단서에 따라 사회복지단체 등에 인도되기 전까지의 보호소년에 대해서는 제46조제1항에 따른 계속 수용에 준하여 처우한다. <신설 2016.3.29>', 2735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4848, '① 원장은 출원하는 보호소년등의 성공적인 사회정착을 위하여 장학ㆍ원호ㆍ취업알선 등 필요한 지원을 할 수 있다. <개정 2016.3.29>', 2736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4849, '② 제1항에 따른 사회정착지원(이하 이 조에서 "사회정착지원"이라 한다)의 기간은 6개월 이내로 하되, 6개월 이내의 범위에서 한 번에 한하여 그 기간을 연장할 수 있다. <개정 2016.3.29>', 2736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4850, '③ 원장은 제51조에 따른 소년보호협회 및 제51조의2에 따른 소년보호위원에게 사회정착지원에 관한 협조를 요청할 수 있다. <개정 2016.3.29>', 2736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4851, '④ 사회정착지원의 절차와 방법 등에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2016.3.29>', 2736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4852, '① 퇴원 또는 임시퇴원이 허가된 보호소년이 질병에 걸리거나 본인의 편익을 위하여 필요하면 본인의 신청에 의하여 계속 수용할 수 있다.', 2737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4853, '② 소년원장은 제1항에 따른 계속 수용의 사유가 소멸되면 지체 없이 보호소년을 보호자등에게 인도하여야 한다.', 2737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4854, '③ 소년원장은 제1항에 따라 임시퇴원이 허가된 보호소년을 계속 수용할 때에는 그 사실을 보호관찰소장에게 통지하여야 한다.', 2737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4855, '① 소년원장은 「보호관찰 등에 관한 법률」 제48조에 따라 임시퇴원이 취소된 자는 지체 없이 재수용하여야 한다.', 2739);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4856, '② 제1항에 따라 재수용된 자의 수용기간은 수용상한기간 중 남은 기간으로 한다.', 2739);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4857, '③ 제1항에 따라 재수용된 자는 새로 수용된 보호소년에 준하여 처우를 한다.', 2739);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4858, '① 보호소년등에 대한 지도, 학술연구, 그 밖의 사유로 소년원이나 소년분류심사원을 방문하려는 자는 그 대상 및 사유를 구체적으로 밝혀 원장의 허가를 받아야 한다.', 2740);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4859, '② 소년원이나 소년분류심사원을 방문하지 아니하고 설문조사를 하려는 자는 미리 그 내용을 원장과 협의하여야 한다.', 2740);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4860, '① 원장은 제3조에 따른 교정교육, 분류심사 또는 조사에 특히 필요하다고 인정하면 행정기관, 학교, 병원, 그 밖의 단체에 대하여 필요한 협조를 요청할 수 있다. <개정 2013.7.30, 2020.10.20>', 2741);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4861, '② 제1항의 요청을 거절할 때에는 정당한 이유를 제시하여야 한다.', 2741);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4862, '① 소년분류심사원장은 제26조에 따른 업무를 처리하기 위하여 청소년심리상담실을 설치ㆍ운영할 수 있다.', 2742);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4863, '② 제1항에 따른 청소년심리상담실의 설치와 운영에 필요한 사항은 법무부령으로 정한다.', 2742);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4864, '① 보호소년등을 선도하기 위하여 법무부장관 감독하에 소년 선도에 관하여 학식과 경험이 풍부한 인사로 구성되는 소년보호협회를 둘 수 있다.', 2743);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4865, '② 소년보호협회의 설치, 조직, 그 밖의 운영에 필요한 사항은 대통령령으로 정한다.', 2743);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4866, '③ 국가는 소년보호협회에 보조금을 지급할 수 있다.', 2743);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4867, '④ 국가는 보호소년등의 교정교육과 사회복귀 지원 및 청소년 비행예방을 위하여 필요하다고 인정하는 경우에는 「국유재산법」에도 불구하고 소년보호협회에 소년원, 소년분류심사원 및 「보호관찰 등에 관한 법률」 제14조에 따른 보호관찰소의 시설, 그 밖에 대통령령으로 정하는 국유재산을 무상으로 대부하거나 사용허가할 수 있다. <신설 2010.5.4, 2016.3.29>', 2743);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4868, '⑤ 제4항에 따라 국유재산을 무상으로 대부하거나 사용허가하는 경우 그 기간은 「국유재산법」 제35조제1항 또는 같은 법 제46조제1항에서 정하는 바에 따른다. <신설 2016.3.29>', 2743);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4869, '⑥ 제5항의 대부기간 또는 사용허가기간이 끝난 국유재산에 대해서는 그 대부기간 또는 사용허가기간을 초과하지 아니하는 범위에서 종전의 대부계약 또는 사용허가를 갱신할 수 있다. <신설 2016.3.29>', 2743);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4870, '⑦ 국가나 지방자치단체는 소년보호협회에 대하여 「조세특례제한법」 및 「지방세특례제한법」에서 정하는 바에 따라 국세 또는 지방세를 감면할 수 있다. <신설 2016.3.29>', 2743);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4871, '① 보호소년등의 교육 및 사후지도를 지원하기 위하여 소년보호위원을 둘 수 있다.', 2744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4872, '② 소년보호위원은 명예직으로 하며, 법무부장관이 위촉한다.', 2744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4873, '③ 소년보호위원에게는 예산의 범위에서 직무수행에 필요한 비용의 전부 또는 일부를 지급할 수 있다. <신설 2013.7.30>', 2744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4874, '④ 소년보호위원의 위촉ㆍ해촉 및 자치조직 등에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2013.7.30>', 2744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4875, '① 원장은 기관ㆍ단체 또는 개인이 보호소년등에 대한 적절한 처우, 학업 지원 및 보호소년등의 사회 정착 등을 위하여 소년원이나 소년분류심사원에 자발적으로 기탁하는 금품을 접수할 수 있다.', 2746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4876, '② 기부자에 대한 영수증 발급, 기부금품의 용도 지정, 장부의 열람, 그 밖에 필요한 사항은 대통령령으로 정한다.', 2746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4877, '① 법무부장관은 제43조제1항 및 제2항에 따라 소년원에서 퇴원한 보호소년의 재범 여부를 조사하고 소년원 교정교육의 효과를 평가하기 위하여 보호소년이 같은 조 제1항 및 제2항에 따라 퇴원한 때부터 3년 동안 관계 기관에 그 소년에 관한 범죄경력자료와 수사경력자료에 대한 조회를 요청할 수 있다.', 2747);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4878, '② 제1항의 요청을 받은 관계 기관의 장은 정당한 사유 없이 이를 거부해서는 아니 된다.', 2747);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4879, null, 2749);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4880, '① 법 제5조에 따라 소년원을 다음 각 호와 같이 분류한다. <개정 2021.4.20, 2022.2.17>', 2750);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4881, '② 제1항에 따른 소년원의 세부분류ㆍ운영기준은 법무부장관이 정한다.', 2750);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4882, '①소년원장 또는 소년분류심사원장(이하 "원장"이라 한다)은 법 제7조 또는 법 제12조에 따라 보호소년등을 새로 수용할 때에는 법원소년부의 결정서, 법무부장관의 이송허가서 또는 지방법원 판사의 유치허가장을 통하여 본인임을 확인한 후 인수하고, 인도기관에 인수서를 내주어야 한다. <개정 2014.1.28, 2021.4.20>', 2754);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4883, '② 보호관찰소의 장은 유치소년을 원장에게 인도할 때에는 원본과 대조ㆍ확인한 유치허가장 사본을 제출하여야 한다. <신설 2014.1.28>', 2754);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4884, '① 원장은 법 제8조제1항에 따라 분류처우를 할 때에는 분류심사 결과와 법원소년부로부터 송부된 자료를 고려하여야 한다. <개정 2016.9.5>', 2757);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4885, '② 원장은 법 제8조제2항에 따라 보호소년등을 분리수용하는 경우 비행, 공범관계, 처우과정 등을 고려하여 법무부령으로 정하는 바에 따라 생활실을 구분할 수 있다. <개정 2016.9.5>', 2757);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4886, '① 소년원장은 제9조에 따른 분류처우 대상 보호소년에 대하여 법 제15조의2에 따른 보호소년등처우ㆍ징계위원회(이하 "처우ㆍ징계위원회"라 한다)의 심사를 거쳐 개별처우계획을 수립해야 한다. <개정 2021.4.20>', 2758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4887, '② 제1항에 따른 개별처우계획에는 초ㆍ중등교육, 직업능력개발훈련, 의료재활, 인성교육 등 개별 교육ㆍ처우의 방향이 제시돼야 한다. 이 경우 보호소년과 보호자등의 의견을 고려해야 한다. <개정 2021.4.20>', 2758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4888, '③ 제1항 및 제2항에 따라 수립된 개별처우계획은 교정교육에 지장이 없는 범위에서 그 내용을 본인 및 보호자등에게 알려 보호소년이 스스로 교육에 참여하고, 자기 개선을 위하여 노력하도록 하여야 한다.', 2758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4889, '① 원장은 법 제11조에 따른 청원서를 접수하면 지체 없이 이를 법무부장관에게 보내야 한다.', 2761);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4890, '② 원장은 법 제11조에 따른 청원을 할 수 있다는 안내문을 보기 쉬운 곳에 게시하는 등 청원의 편의를 제공하여야 한다.', 2761);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4891, '③ 원장은 보호소년등이 청원을 못하게 하거나 청원을 하였다는 이유로 불이익한 처우를 하여서는 아니 된다.', 2761);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4892, '① 소년원장은 이송할 보호소년에 대하여 건강진단을 하고 건강상태가 이송해 갈 소년원의 교육활동에 적합하지 아니하다고 판명되면 이송을 중지하여야 한다.', 2764);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4893, '② 소년원장은 다음 각 호의 어느 하나에 해당하는 보호소년을 다른 소년원으로 이송해서는 안 된다. <개정 2021.1.5, 2021.4.20>', 2764);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4894, '③ 소년원장은 제2항에도 불구하고 처우상 특히 필요하다고 인정되는 사유가 있으면 처우ㆍ징계위원회의 심의를 거쳐 법무부장관의 허가를 받아 보호소년을 다른 소년원으로 이송할 수 있다. <개정 2021.4.20>', 2764);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4895, null, 2766);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4896, '① 원장은 시설의 안전과 질서 유지를 위하여 필요하다고 인정하는 경우에는 보호소년등의 신체ㆍ의류ㆍ휴대품ㆍ생활실 등을 검사할 수 있다.', 2767);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4897, '② 원장은 보호소년등의 신체를 검사하는 경우에는 해당 보호소년등이 불필요한 고통이나 수치심을 느끼지 않도록 유의해야 하며, 특히 신체를 면밀히 검사할 필요가 있으면 다른 보호소년등이 볼 수 없는 차단된 장소에서 해야 한다. <개정 2021.4.20>', 2767);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4898, '③ 원장은 여성인 보호소년등의 신체ㆍ의류 및 휴대품을 검사하는 경우에는 소속 여성 공무원이 하게 하여야 한다.', 2767);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4899, '④ 원장은 제1항에 따라 검사한 결과 제17조의2에 따른 소지금지물품(이하 "금지물품"이라 한다)이 발견되면 이를 보호소년등에게 알린 후 폐기한다.', 2767);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4900, '⑤ 제4항에도 불구하고 폐기하는 것이 적당하지 아니한 물품은 소년원등에 보관하거나 보호자등에게 전달할 수 있다. 이 경우 보관 물품의 처리는 법 제22조에 따른다. <개정 2021.4.20>', 2767);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4901, '①원장은 소년원등에 출입하는 외부인의 출입 목적과 신원을 확인하고, 시설의 안전과 질서 유지를 위하여 필요하다고 인정하면 출입자의 의류와 휴대품을 검사할 수 있다. <개정 2014.1.28>', 2768);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4902, '② 원장은 제1항에 따른 검사 결과 출입자가 금지물품을 소지하고 있으면 소년원등에 맡기게 하여야 하며, 이에 따르지 아니하면 출입을 금지할 수 있다. <신설 2014.1.28>', 2768);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4903, '③ 원장은 여성 출입자의 의류 및 휴대품을 검사하는 경우에는 소속 여성 공무원이 하게 하여야 한다. <신설 2014.1.28>', 2768);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4904, '① 원장은 보호소년등이 다음 각 호의 어느 하나에 해당할 때에는 의사의 의견을 고려하여 심신안정실(자살 및 자해 방지 등의 설비를 갖춘 생활실을 말한다. 이하 같다)에 수용할 수 있다. <개정 2016.9.5>', 2769);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4905, '② 제1항제1호 및 제2호에 따른 심신안정실의 수용기간은 15일 이내로 한다. 다만, 원장은 특별히 계속하여 수용할 필요가 있으면 의사의 의견을 고려하여 7일을 초과하지 아니하는 범위에서 한 차례만 그 기간을 연장할 수 있다.', 2769);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4906, '③ 제1항제3호 및 제4호에 따른 심신안정실 수용기간은 24시간 이내로 한다. 다만, 원장은 특별히 계속하여 수용할 필요가 있으면 의사의 의견을 고려하여 12시간을 초과하지 아니하는 범위에서 한 차례만 그 기간을 연장할 수 있다.', 2769);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4907, '④ 원장은 보호소년등을 심신안정실에 수용하거나 그 수용기간을 연장하는 경우에는 그 사유를 본인에게 알려주어야 한다.', 2769);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4908, '⑤ 원장은 의사 및 간호사로 하여금 심신안정실에 수용된 보호소년등의 건강상태를 수시로 확인하게 하여야 한다.', 2769);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4909, '⑥ 원장은 심신안정실에 수용할 사유가 소멸하면 심신안정실 수용을 즉시 중단하여야 한다.', 2769);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4910, '① 원장은 보호소년등의 사망, 이탈, 난동, 그 밖의 중대한 사고가 발생하면 지체 없이 법무부장관에게 보고하여야 한다.', 2770);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4911, '② 원장은 조사ㆍ심리(審理)를 받고 있는 위탁소년 또는 항고 중의 보호소년이 사망하거나 이탈한 경우 또는 이탈한 보호소년등을 재수용한 경우에는 지체 없이 그 사실을 사건이 계류되어 있는 법원에 통지하여야 한다.', 2770);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4912, '① 원장은 법 제15조에 따라 보호소년등을 징계할 때에는 다음 각 호의 사항을 고려하여야 한다. <개정 2014.1.28>', 2775);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4913, '② 원장은 제1항에 따라 보호소년등을 징계할 때에는 증거에 의하여 징계 정도를 공정하게 정하고 교육적 효과를 고려하여야 한다.', 2775);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4914, '① 보호소년등의 징계대상행위에 대한 조사기간(조사를 시작한 날부터 조사를 완료하여 처우ㆍ징계위원회 개최 통보를 한 날까지를 말한다. 이하 같다)은 7일 이내로 한다. 다만, 원장은 특별히 필요하다고 인정하는 경우에는 3일을 초과하지 아니하는 범위에서 한 차례만 그 기간을 연장할 수 있다. <개정 2021.4.20>', 2776);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4915, '② 원장은 규율을 위반하여 징계가 필요하다고 의심할 만한 상당한 이유가 있는 보호소년등이 다음 각 호의 어느 하나에 해당하면 조사기간 중 분리하여 수용할 수 있다.', 2776);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4916, '③ 제2항에 따른 분리수용기간은 징계기간에 포함한다.', 2776);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4917, '④ 원장은 조사대상자의 질병이나 그 밖의 특별한 사정으로 조사를 계속하기 어려운 경우에는 그 사유가 없어질 때까지 조사를 일시적으로 정지할 수 있다. 이 경우 조사가 정지된 다음 날부터 정지사유가 소멸한 전날까지의 기간은 조사기간에 포함하지 아니한다.', 2776);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4918, '⑤ 제1항부터 제4항까지에서 규정한 사항 외에 징계대상행위 조사에 관한 세부 사항은 법무부령으로 정한다.', 2776);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4919, '① 원장은 보호소년등을 징계할 때에는 지도계획을 수립하여 시행하여야 한다.', 2779);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4920, '② 원장은 징계 중인 보호소년등을 매주 1회 이상 면접하고 개별지도를 하여야 한다.', 2779);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4921, '③ 원장은 징계 중인 보호소년등의 처우를 제한하는 경우에는 그 사실을 그 보호소년등의 가족이나 친지에게 알려야 한다.', 2779);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4922, '④ 원장은 징계 중인 보호소년등에 대하여는 의사 및 간호사에게 수시로 건강진단을 하도록 하여야 한다.', 2779);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4923, null, 2783);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4924, '① 처우ㆍ징계위원회의 위원장(이하 "위원장"이라 한다)은 원장이 된다.', 2784);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4925, '② 처우ㆍ징계위원회의 위원(이하 "위원"이라 한다)은 다음 각 호에 해당하는 사람 중에서 위원장이 성별을 고려하여 임명하거나 위촉한다. 이 경우 의료재활소년원에 두는 처우ㆍ징계위원회의 위원에는 의무직공무원 및 간호직공무원이 포함돼야 한다.', 2784);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4926, '③ 「국가공무원법」 제33조 각 호에 해당하는 사람은 위원이 될 수 없다.', 2784);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4927, '④ 제2항에 따라 위촉된 위원의 임기는 2년으로 한다.', 2784);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4928, '① 위원이 다음 각 호의 어느 하나에 해당하는 경우에는 처우ㆍ징계위원회의 심의ㆍ의결에서 제척(除斥)된다.', 2785);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4929, '② 해당 안건의 당사자는 위원에게 공정한 심의ㆍ의결을 기대하기 어려운 사정이 있는 경우에는 처우ㆍ징계위원회에 기피 신청을 할 수 있고, 처우ㆍ징계위원회는 의결로 기피 여부를 결정한다. 이 경우 기피 신청의 대상인 위원은 그 의결에 참여할 수 없다.', 2785);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4930, '③ 위원이 제1항 각 호에 따른 제척사유나 제2항 전단에 따른 기피사유에 해당하는 경우에는 스스로 해당 안건의 심의ㆍ의결에서 회피해야 한다.', 2785);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4931, '① 위원장은 처우ㆍ징계위원회를 대표하고, 처우ㆍ징계위원회의 업무를 총괄한다.', 2786);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4932, '② 위원장이 부득이한 사유로 직무를 수행할 수 없을 경우에는 위원장이 미리 지정한 위원이 그 직무를 대행한다.', 2786);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4933, '① 위원장은 다음 각 호의 어느 하나에 해당하는 경우에 처우ㆍ징계위원회의 회의를 소집한다.', 2787);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4934, '② 처우ㆍ징계위원회의 회의는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.', 2787);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4935, '③ 처우ㆍ징계위원회의 회의에 출석한 위원과 관계 전문가 등에게는 예산의 범위에서 수당과 여비, 그 밖에 필요한 경비를 지급할 수 있다. 다만, 공무원이 그 소관 업무와 직접 관련하여 출석하는 경우에는 지급하지 않는다.', 2787);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4936, null, 2788);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4937, '① 처우ㆍ징계위원회의 사무를 처리하기 위해 처우ㆍ징계위원회에 2명 이내의 간사를 둔다.', 2789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4938, '② 간사는 위원장이 해당 소년원등에 소속된 공무원 중에서 임명한다.', 2789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4939, '① 간사는 처우ㆍ징계위원회의 회의록을 작성ㆍ보관해야 한다.', 2790);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4940, '② 제1항에 따른 회의록에는 위원장 및 출석위원이 서명 또는 날인해야 한다.', 2790);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4941, '① 원장은 법 제16조제1항에 따라 선정된 보호소년등에게는 상장ㆍ상품 등을 주거나 그 밖의 포상을 할 수 있다.', 2792);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4942, '② 원장은 제1항에 따라 포상을 받은 보호소년등에 대하여 제2조 각 호의 특별처우를 할 수 있다. <개정 2021.4.20>', 2792);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4943, '① 원장은 교정교육이나 위생에 해가 없다고 인정되는 경우에만 보호자나 그 밖의 관계인으로부터 음식물ㆍ의류ㆍ학용품 등을 반입하도록 허가할 수 있다.', 2794);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4944, '② 원장은 제1항에 따른 반입품이 유해한지를 검사하여야 한다.', 2794);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4945, '① 보호소년등의 면회는 평일[원장이 필요하다고 인정하는 경우에는 토요일(공휴일은 제외한다)을 포함한다]에 교육 등 일과 진행에 지장이 없는 범위에서 1일 1회 40분 이내로 한다. 다만, 특별한 사유가 있을 때에는 그렇지 않다. <개정 2014.1.28, 2021.4.20>', 2797);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4946, '② 제1항에 따른 면회의 장소ㆍ절차 등에 관하여 필요한 사항은 법무부령으로 정한다.', 2797);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4947, null, 2799);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4948, '① 원장은 법 제18조제4항에 따라 편지를 검사한 결과 다음 각 호의 어느 하나에 해당하는 경우에는 편지의 왕래를 제한할 수 있다. <개정 2016.9.5>', 2800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4949, '② 제1항에 따른 편지 왕래의 제한은 다음 각 호의 어느 하나에 해당하는 방법으로 한다.', 2800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4950, '③ 정보통신매체를 통한 편지의 제한에 관하여는 제1항 및 제2항을 준용한다.', 2800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4951, '① 원장은 전화통화 허가를 신청한 보호소년등에게 다음 각 호의 어느 하나에 해당하는 사유가 있는 경우에는 전화통화를 허가하지 않을 수 있다. <개정 2021.4.20>', 2801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4952, '② 원장은 다음 각 호의 어느 하나에 해당하는 경우에는 보호소년등의 전화통화를 중지시킬 수 있다.', 2801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4953, '③ 제2항에 따라 보호소년등의 전화통화를 중지시키려면 미리 보호소년등에게 경고하여야 하며, 전화통화를 중지시킬 경우 통화상대방에게도 그 사유를 알려야 한다.', 2801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4954, '① 소년원장은 외출허가를 받은 보호소년에게 지켜야 할 사항을 부과하여야 한다.', 2803);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4955, '② 소년원장은 보호소년이 준수사항을 위반하면 지체 없이 외출허가를 취소하고 복귀에 필요한 조치를 하여야 한다.', 2803);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4956, '① 원장은 제42조에 따른 건강진단이나 정기ㆍ수시검진 결과 중한 질병이 있다는 사실을 알았거나, 외부 의료기관에서 입원ㆍ수술 등의 처치를 받아야 할 사유가 발생하면 지체 없이 그 사실을 법무부장관에게 보고하고 보호자등에게 알려야 한다. <개정 2021.4.20>', 2805);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4957, '② 원장은 법 제20조제2항에 따라 보호소년등을 외부 의료기관에 입원시킨 경우에는 지체 없이 법무부장관에게 보고하여야 한다.', 2805);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4958, null, 2807);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4959, '① 원장은 보호소년등에 대한 예방접종과 방역소독 등 감염병 예방에 필요한 조치를 하여야 한다. <개정 2010.12.29>', 2808);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4960, '② 원장은 감염병이 유행하고 있을 때에는 감염병 유행지역 거주자의 면회, 음식물ㆍ피복이나 그 밖의 물품의 반입을 금지할 수 있다. <개정 2010.12.29>', 2808);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4961, '③ 원장은 보호소년등이 감염병에 감염되었다고 의심되는 경우에는 감염병의 증상 또는 전염력이 없어질 때까지 격리수용하고, 소지품에 대한 소독 등 필요한 조치를 하여야 한다. <개정 2010.12.29>', 2808);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4962, '① 원장은 법 제22조제1항에 따라 보호소년등의 금품을 보관할 때에는 본인이 참여한 가운데 점검하고, 법무부령으로 정하는 보관금품 보관증(이하 "보관증"으로 한다)에 품명ㆍ수량ㆍ규격과 그 밖에 필요한 사항을 기재한 후 본인이 확인ㆍ서명하게 하여야 한다. 이 경우 보관증은 원장과 보호소년등이 각각 한 부씩 보관한다. <개정 2016.9.5>', 2810);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4963, '② 제1항의 경우 보호소년등이 소지한 물품이 보관하기에 부적당하다고 인정되면 보호자등에게 반환하거나 본인의 승낙을 받아 매각하고 그 대금을 보관할 수 있다. 다만, 물품 중 가치가 없다고 인정되는 것은 본인이 폐기하게 할 수 있다.', 2810);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4964, '③ 원장은 필요하다고 인정하면 보관한 물품을 보호소년등이 사용하게 할 수 있다.', 2810);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4965, '① 법 제22조제2항에 따라 보관금품을 반환하는 때에는 보관증에 그 사유를 기재하고 수령인에게 확인ㆍ서명하도록 하여야 한다. <개정 2016.9.5>', 2811);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4966, '② 원장은 법 제22조제2항에도 불구하고 출원하는 보호소년등이 보관금품을 반환받기를 원하지 아니하면 반환하지 않을 수 있다.', 2811);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4967, '③ 제2항에 따라 보관금품을 반환하지 않을 때에는 보관증에 그 사유를 기재하고 해당 보호소년등에게 확인ㆍ서명하도록 하여야 한다. <개정 2016.9.5>', 2811);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4968, '① 원장은 소년원등에서 사용할 물품을 기증하려는 자가 있을 경우에는 보호와 교정교육에 필요한 물품만 기증받을 수 있다. <개정 2021.4.20>', 2812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4969, '② 원장은 기증자가 제1항의 물품 기증을 목적으로 현금을 기탁하는 경우에는 이를 접수하여 해당 물품을 대신 구입할 수 있다. 이 경우 관련 증빙서류를 첨부하여 기증자에게 알려야 한다.', 2812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4970, '① 법 제3조제2항제1호 및 제2호에 따른 분류심사를 할 때는 다음 각 호의 사항을 종합ㆍ분석해야 한다. <개정 2014.1.28, 2021.4.20>', 2814);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4971, '② 제1항에 따른 분류심사를 할 때에는 각종 기록 및 상담 결과, 관계인과의 면접, 그 밖의 객관적인 자료를 토대로 하여야 한다.', 2814);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4972, '① 법 제3조제2항제3호부터 제5호까지의 규정에 따른 상담조사, 검사의 결정 전 조사, 분류심사 업무를 할 때에는 의뢰기관이 요청한 영역에 대하여 실시한다. <개정 2014.1.28, 2021.4.20>', 2815);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4973, '② 법 제3조제2항제3호의 경우 소년의 진로지도 및 품행 개선을 위한 교육을 실시할 수 있다. 이 경우 상담조사 기간의 출석일수 인정 등에 관하여는 제85조를 준용한다. <개정 2014.1.28, 2021.4.20>', 2815);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4974, '① 분류심사관은 제51조에 따른 분류심사자료를 종합하여 분류심사서를 작성하여야 한다.', 2816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4975, '② 소년분류심사원장은 분류심사관의 원활한 직무수행을 위하여 필요한 소양과 전문지식을 갖춘 분류심사 전문요원을 두고 제51조제1항 각 호의 자료수집과 심리검사 등을 하게 할 수 있다.', 2816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4976, '① 법 제26조에 따라 심리검사 등을 요청하려는 사람은 소년분류심사원장에게 법무부장관이 정한 방법과 절차에 따라 심리검사를 의뢰하여야 한다.', 2817);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4977, '② 소년분류심사원장은 제1항에 따른 청소년 심리검사 등을 의뢰받았을 때에는 심리검사 등의 일시와 장소, 그 밖에 필요한 사항 등 협조사항을 미리 알려야 한다.', 2817);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4978, '① 소년원장은 보호소년이 정해진 교육기간에 교정목적을 달성할 수 있도록 법 제41조에 따른 교육계획을 수립하여 시행하여야 한다.', 2818);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4979, '② 제1항에 따른 교육계획에는 교육과정, 특별활동 및 생활지도 등에 관한 구체적 내용이 포함되어야 한다.', 2818);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4980, '① 교정교육은 보호소년이 소년원에 입원할 때부터 출원할 때까지의 전 과정을 신입자교육, 기본교육, 사회복귀교육의 3단계로 구분하여 순차적으로 실시해야 한다. <개정 2021.4.20>', 2819);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4981, '② 제1항에 따른 단계별 교육에 관한 세부사항은 법무부령으로 정한다.', 2819);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4982, '① 보호소년의 교정성적은 교육성과 및 생활성적을 종합하여 평가한다.', 2820);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4983, '② 그 밖에 보호소년의 교정성적 평가에 필요한 사항은 법무부장관이 정한다.', 2820);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4984, '① 원장은 보호소년등의 처우와 교정성적 관리를 적절하게 하기 위하여 개인별로 소년관리기록부를 갖추고 출원 시까지의 모든 상황을 정해진 양식에 따라 계속 기록ㆍ유지하여야 한다.', 2821);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4985, '② 소년분류심사원장은 위탁소년, 유치소년 또는 법 제3조제2항제3호에 따른 상담조사 대상 소년이 법원소년부의 심리 결과 소년원 송치처분을 받게 된 때에는 지체 없이 그 소년의 소년관리기록부 원본을 해당 소년원에 송부해야 한다. <개정 2014.1.28, 2021.4.20>', 2821);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4986, '① 법 제29조에 따른 소년원학교(이하 "소년원학교"라 한다)를 설치하는 경우에는 「초ㆍ중등교육법」에서 정하는 기준에 따라야 한다.', 2822);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4987, '② 소년원학교의 원활한 운영과 소년보호 교육기관의 특성을 고려하여 "소년원"과 "소년원의 각급학교 명칭"을 함께 사용할 수 있다.', 2822);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4988, '① 법 제30조제1항에 따라 임용된 소년원학교의 교원은 학생의 수업, 생활지도, 그 밖에 필요한 직무를 수행하여야 한다.', 2824);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4989, '② 소년원학교장은 소년원학교 교육을 원활하게 하기 위하여 필요하다고 판단되면 법무부장관의 승인을 받아 관련 학과 학사학위 이상 소지자, 청소년상담사, 청소년지도사, 정보통신ㆍ어학 관련 국가공인 자격 소지자 등 정해진 자격요건을 갖춘 소속 공무원에게 제1항에 따른 직무를 담당하도록 할 수 있다.', 2824);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4990, '① 법무부장관은 「교육공무원법」 및 「교원 등의 연수에 관한 규정」에서 정하는 바에 따라 소년원학교 교원을 각급학교의 교육연수원에서 연수하게 하거나 법무연수원에서 연수하게 해야 한다. <개정 2021.4.20>', 2825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4991, '② 소년원학교장은 제1항에 따른 연수대상자를 선발하려면 관할 교육감 또는 법무연수원장과 협의해야 한다. <개정 2021.4.20>', 2825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4992, '① 소년원학교장은 학년 초부터 60일 이내에 입교한 보호소년이 각급학교를 졸업하였거나 같은 수준 이상의 학력이 있다고 인정되는 경우에는 상급학교 교육과정에 입학시킬 수 있다.', 2826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4993, '② 소년원학교장은 보호소년이 학적을 가졌던 학년의 입교 당시 학기에 전학ㆍ편입학시킬 수 있다. 다만, 입교 당시 학기에 전학ㆍ편입학 시킬 수 없을 경우에는 같은 학년 이하의 학기에 전학ㆍ편입학시킬 수 있다.', 2826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4994, '③ 「소년법」 제32조제1항제8호에 따라 소년원에 송치된 소년에 대하여는 제1항 및 제2항을 적용하지 아니한다.', 2826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4995, '① 소년원학교장은 법 제31조제1항에 따라 보호소년이 편입학한 경우에는 편입학사항을 보호소년이 최종적으로 재학하였던 학교[이하 "전적학교(前籍學校)"라 한다]의 장에게 통지하여야 한다.', 2829);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4996, '② 소년원학교장은 보호소년의 학적기록사항을 매 학기 또는 매 학년이 종료되기 이전까지 전적학교의 장에게 보내야 한다.', 2829);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4997, '③ 소년원학교장은 보호소년이 출원하면 그 출원일부터 10일 이내에 학적기록 전부를 전적학교의 장에게 보내야 한다.', 2829);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4998, '④ 전적학교의 장은 제1항부터 제3항까지의 규정에 따라 학적사항을 접수하면 이를 재학생에 준하여 관리하여야 한다.', 2829);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (4999, '① 소년원장은 보호소년이 수용으로 인하여 학교 입학ㆍ복학 또는 편입학에 지장을 줄 염려가 있는 경우에는 보호소년에게 준수사항을 부과하여 통학하도록 할 수 있다.', 2831);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5000, '② 소년원장은 제1항에 따라 통학을 허가받은 보호소년이 통학기간 중 준수사항을 현저하게 위반하거나 통학을 계속해서는 아니 된다고 판단되는 사유가 있으면 통학허가를 취소할 수 있다.', 2831);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5001, '① 소년원학교의 학년별 과정 이수 및 졸업 여부는 처우ㆍ징계위원회에서 다음 각 호의 사항을 심의하여 결정한다. <개정 2021.4.20>', 2832);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5002, '② 제1항제2호에 따른 총 수업시간 수 또는 수업일수는 각 소년원학교별 수업시간수를 더하여 산정하되, 그 기간이 「초ㆍ중등교육법 시행령」 제50조제2항에 따른 기간을 넘으면 졸업요건을 충족한 것으로 본다.', 2832);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5003, null, 2834);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5004, '① 소년원의 직업능력개발훈련은 보호소년이 근로의 소중함을 깨닫고 직업에 대한 올바른 태도와 능력을 길러 건전한 직업생활을 할 수 있도록 하여야 한다.', 2836);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5005, '② 소년원의 직업능력개발훈련은 학교교육 및 산업사회와 밀접한 관련을 갖도록 실시하여야 한다.', 2836);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5006, '① 보호소년의 통근취업 대상 산업체는 소년원 출원 후 직업 선택이 쉽고 건전한 직업의식과 가치관을 기를 수 있는 업체로 선정해야 한다. <개정 2021.4.20>', 2841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5007, '② 소년원장은 법 제37조제1항에 따라 보호소년을 통근취업시키려면 통근취업 대상 산업체와 보수, 취업기간, 취업조건, 그 밖에 필요한 사항을 포함하는 취업약정서를 작성하여야 한다.', 2841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5008, '③ 소년원장은 통근취업을 하는 보호소년에게 준수사항을 부과하여 이를 지키도록 지도하여야 한다.', 2841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5009, '④ 소년원장은 산업체가 제2항의 취업약정사항을 위반하였을 때 또는 보호소년이 준수사항을 현저하게 위반하거나 통근취업을 계속하여서는 아니 된다고 판단되는 사유가 있을 때에는 통근취업을 금지할 수 있다.', 2841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5010, '① 원장은 보호소년등이 지닌 모든 문제와 그들의 욕구를 효과적으로 해소하여 교정목표를 조기에 달성할 수 있도록 체계적인 상담과 심리치료 등 인성교육을 하여야 한다.', 2844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5011, '② 원장은 보호자등이 보호소년등의 처우 또는 개인 사정에 관하여 상담을 신청하면 이에 응하여야 한다.', 2844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5012, '③ 원장은 제1항의 직무를 수행하기 위하여 해당 분야에 전문성과 소양을 갖춘 전담직원을 배치하거나 지정하여야 한다.', 2844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5013, '① 원장은 법 제40조에 따라 보호소년등의 정서를 순화하고 특기를 살리기 위하여 적당한 특별활동에 참여하게 하여야 한다.', 2845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5014, '② 제1항에 따른 특별활동은 체육, 독서, 음악, 연극지도 등 교내 특별활동과 전시관 및 산업시설 견학, 문화유적지 답사, 문화예술 공연 관람, 야영, 소풍 등 다양한 체험학습을 하는 교외 특별활동으로 한다.', 2845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5015, '① 원장은 교육과정 운영에 지장을 주지 않는 범위에서 종교를 가진 보호소년등에게 지정된 장소에서 자유롭게 종교의식에 참여하도록 하여야 한다.', 2847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5016, '② 원장은 신부, 목사, 승려, 그 밖의 종교인에게 보호소년등에 대하여 종교에 관한 지도를 하도록 할 수 있다.', 2847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5017, '① 원장은 교정교육에 필요한 도서실ㆍ상담실ㆍ방송실ㆍ심리검사실ㆍ교육자료실 및 종교실 등을 설치ㆍ운영할 수 있다.', 2848);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5018, '② 원장은 보호소년등이 제1항의 시설을 이용할 수 있도록 필요한 지원을 하여야 한다.', 2848);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5019, '① 법 제42조의2제1항에 따라 판사 또는 검사가 의뢰한 대안교육 대상 소년이 소년원등에서 정해진 교육과정을 이수했을 때에는 그 기간을 재적학교의 출석일수로 인정해야 한다. <개정 2021.4.20>', 2850);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5020, '② 원장은 법 제31조제2항에 따른 위탁소년이나 그 보호자 또는 제1항에 따른 대안교육 대상 소년이나 그 보호자가 원하는 경우에는 소년원등의 교육과정 이수사실이나 대안교육 이수사실을 소년의 재적학교의 장에게 통지할 수 있다. <개정 2021.4.20>', 2850);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5021, '① 원장은 법 제42조의3에 따라 보호자교육이 필요하다고 인정되면 교육목적과 대상, 시간 및 장소, 프로그램 등의 내용이 포함되는 교육계획을 수립ㆍ시행하여야 한다.', 2851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5022, '② 제1항에 따른 교육 프로그램에는 다음 각 호의 내용을 포함하여야 한다.', 2851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5023, null, 2853);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5024, '① 「보호관찰 등에 관한 법률」 제48조에 따라 임시퇴원이 취소된 소년의 경우 임시퇴원 당시의 소년원장은 보호관찰관으로부터 그 소년을 인수하여 지체 없이 재수용하여야 한다.', 2854);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5025, '② 제1항에도 불구하고 임시퇴원 당시의 소년원과 임시퇴원 취소자(여성인 임시퇴원 취소자는 제외한다. 이하 이 항에서 같다)의 현재지(現在地)의 시ㆍ도가 달라 재수용이 지체될 우려가 있으면 임시퇴원 취소자의 현재지와 인접한 소년원에서 소년을 인수할 수 있다. <개정 2021.4.20>', 2854);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5026, '③ 제주지역을 현재지로 하여 임시퇴원이 취소된 사람은 제주소년원에 재수용한다. 다만, 임시퇴원 취소자의 주된 거주지와 제주소년원의 시ㆍ도가 다르면 청원이나 그 밖에 처우상 필요에 따라 임시퇴원 당시의 소년원에서 인수할 수 있다.', 2854);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5027, '① 원장은 법 제50조에 따라 보호소년등의 교정교육과 분류심사를 위하여 필요한 경우에는 다음 각 호의 자료를 해당 기관에 요청할 수 있다.', 2856);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5028, '② 직무상 제1항의 자료조회를 요청하는 사람 또는 이를 취급하는 사람은 그 내용을 직무와 직접 관련되지 아니하는 사람에게 누설하여서는 아니 된다.', 2856);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5029, '① 원장은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2016.9.5, 2021.4.20>', 2857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5030, '② 원장은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법 시행령」 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2014.6.30, 2020.3.3>', 2857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5031, '① 협회의 정관에는 다음 각 호의 사항이 포함되어야 한다.', 2859);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5032, '② 협회는 정관을 변경할 때에는 이사회의 의결을 거쳐 법무부장관의 허가를 받아야 한다.', 2859);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5033, '① 협회에는 다음 각 호의 임원을 둔다.', 2860);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5034, '② 이사장은 법무부장관이 임명하고, 이사장 및 상임이사를 제외한 이사 중 1명은 법무부 소속 공무원 중에서 법무부장관이 지명하며, 이사장과 법무부장관이 지명한 이사(이하 "당연직이사"라 한다)를 제외한 임원은 이사회에서 선임하되, 법무부장관의 승인을 받아 취임한다.', 2860);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5035, '③ 이사장 및 감사의 임기는 2년으로 하고, 당연직이사를 제외한 이사의 임기는 3년으로 한다.', 2860);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5036, '④ 당연직이사를 제외한 임원은 법무부장관의 승인을 받아 연임할 수 있다. 다만, 임원의 재임(在任)기간은 이사장의 경우 6년을 초과할 수 없고, 이사의 경우 이사장 임기를 포함하여 10년을 초과할 수 없다.', 2860);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5037, '① 이사장은 협회를 대표하고 협회의 업무를 총괄한다.', 2861);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5038, '② 이사장은 이사회를 소집하며, 이사회의 의장이 된다.', 2861);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5039, '③ 이사장이 부득이한 사유로 직무를 수행할 수 없을 때에는 상임이사가 이사장의 직무를 대행한다.', 2861);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5040, '④ 이사는 이사회에 출석하여 협회의 중요 사항을 심의ㆍ의결하며, 이사회 또는 이사장으로부터 위임받은 업무를 처리한다.', 2861);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5041, '⑤ 감사는 협회의 업무 및 회계를 감사한다.', 2861);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5042, '① 협회의 업무에 관한 주요 사항을 심의ㆍ의결하기 위하여 협회에 이사장과 이사로 구성된 이사회를 둔다.', 2862);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5043, '② 감사는 이사회에 출석하여 의견을 진술할 수 있다.', 2862);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5044, null, 2864);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5045, '① 협회는 그 설립목적을 달성하기 위하여 다음 각 호의 목적사업을 한다. <개정 2016.9.5>', 2865);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5046, '② 협회는 그 설립목적을 달성하기 위하여 수익사업을 할 수 있다.', 2865);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5047, '③ 협회는 제2항의 수익사업을 하려는 경우에는 사업마다 미리 법무부장관의 승인을 받아야 한다. 이를 변경하려는 경우에도 또한 같다.', 2865);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5048, '① 협회의 회계연도는 정부의 회계연도에 따른다.', 2866);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5049, '② 협회는 매 회계연도 개시 전까지 해당 회계연도에 수행할 사업계획 및 예산안을 작성하여 이사회의 의결을 거친 후 법무부장관에게 제출하여 승인을 받아야 한다. 이를 변경할 때에도 또한 같다.', 2866);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5050, '③ 협회는 매 회계연도의 사업실적과 결산서를 작성하여 이사회의 의결을 거친 후 다음 회계연도 2월 말일까지 법무부장관에게 제출하여야 한다.', 2866);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5051, '④ 협회는 국고보조금의 집행결과를 분기마다 법무부장관에게 보고하여야 한다.', 2866);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5052, '① 법무부장관은 협회를 지휘ㆍ감독한다.', 2867);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5053, '② 법무부장관은 협회에 대하여 감독상 필요한 경우에는 그 업무에 관한 사항을 보고하게 하거나 자료의 제출, 그 밖에 필요한 명령을 할 수 있으며, 소속 공무원에게 협회 운영 실태를 조사하게 할 수 있다.', 2867);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5054, '③ 법무부장관은 협회의 국고보조금 집행에 관하여 감사를 할 수 있다.', 2867);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5055, '① 원장은 법 제53조제1항에 따라 기부금품을 접수하는 경우 기부자에게 영수증을 발급하여야 한다. 다만, 익명으로 기부하거나 기부자를 알 수 없는 경우에는 영수증을 발급하지 아니할 수 있다.', 2869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5056, '② 원장은 제1항에 따른 기부자가 다음 각 호의 어느 하나의 경우에 해당하는 사실을 알게 된 경우에는 기부금품을 접수해서는 아니 된다.', 2869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5057, '③ 원장은 제1항에 따른 기부자가 기부금품의 용도를 지정한 경우에는 그 용도로만 사용하여야 한다. 다만, 기부자가 지정한 용도로 사용하기 어려운 경우에는 특별한 사정이 없는 한 기부자의 동의를 받아 다른 용도로 사용할 수 있다.', 2869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5058, '④ 원장은 모든 기부금의 수입 및 지출을 기부금 전용계좌를 통하여 처리하여야 한다.', 2869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5059, '⑤ 원장은 기부금품의 접수현황 및 사용실적 등에 관한 장부를 갖추어 두고 기부자가 열람할 수 있도록 하여야 한다.', 2869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5060, '⑥ 원장은 매 반기별로 기부금품의 접수현황 및 사용실적 등에 관한 사항을 법무부장관에게 보고하여야 한다.', 2869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5061, '① 법무부장관이 법 제54조에 따라 범죄경력자료와 수사경력자료의 조회를 요청하는 경우 「형의 실효 등에 관한 법률」 제6조제1항에 따라 소년원에서 퇴원한 보호소년의 재범 여부를 조사하고 소년원 교정교육의 효과를 평가하기 위해 필요한 최소한의 범위에서 요청해야 한다.', 2870);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5062, '② 범죄경력자료 또는 수사경력자료를 관리하는 사람이나 직무상 범죄경력자료 또는 수사경력자료를 조회하거나 열람한 사람은 그 내용을 누설해서는 안 된다.', 2870);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5063, '③ 제1항 및 제2항에서 규정한 사항 외에 범죄경력자료와 수사경력자료의 조회 요청 방법, 자료 관리 등에 필요한 세부사항은 법무부장관이 정한다.', 2870);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5064, '① 「보호소년 등의 처우에 관한 법률 시행령」(이하 "영"이라 한다) 제6조에 따른 인수서는 별지 제1호서식에 따른다. <개정 2021.4.20>', 2879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5065, '② 소년원장 또는 소년분류심사원장(이하 "원장"이라 한다)은 보호소년등이 영 제6조에 따라 새로 수용된 때에는 지체 없이 다음 각 호에 따른 검사ㆍ조사 또는 조치 등을 하고, 이상이 발견되었을 경우에는 필요한 조치를 마련하여야 한다. <개정 2016.9.29, 2021.4.20>', 2879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5066, '③ 여성인 보호소년등에 대한 제2항제1호ㆍ제3호 및 제4호의 검사 또는 조치는 여성인 직원이 실시해야 한다. 다만, 제2항제3호에 따른 검사는 여성인 직원이 참석한 가운데 의사나 간호사가 실시할 수 있다. <개정 2021.4.20>', 2879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5067, null, 2882);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5068, '① 소년원장은 법 제9조제1항에 따라 「소년법」 제32조제1항제7호부터 제10호까지의 보호처분을 받아 수용된 보호소년이 소년원을 이탈한 후 재수용되었을 때에는 법원소년부에 같은 항 제7호부터 제10호까지의 보호처분으로 변경을 신청할 수 있다. <개정 2021.4.20>', 2887);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5069, '② 소년원장은 「소년법」 제32조제1항제5호 처분과 제8호 처분이 병합되어 소년원에 수용된 보호소년이 소년원을 이탈하였을 때에는 그 보호소년을 관할하는 보호관찰소에 즉시 통보하여야 한다.', 2887);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5070, '③ 소년원장은 보호소년이 소년원을 이탈하거나 소년원을 이탈한 후 범법행위로 인하여 징역 또는 금고 이상의 유죄판결이 확정된 경우 또는 보호처분에 따라 소년원에 다시 송치된 경우에는 해당 보호소년에 대한 종전의 보호처분을 취소할 것을 법원소년부에 신청하여야 한다.', 2887);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5071, '① 원장은 영 제13조에 따른 청원의 편의를 위하여 보호소년등이 이용하기 편리한 곳에 청원함을 설치하고, 매일 청원사항을 확인하여야 한다.', 2888);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5072, '② 청원에 대한 결정은 문서로 하여야 하며, 그 결정서는 지체 없이 청원인에게 전달하여야 한다.', 2888);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5073, '③ 원장은 별지 제3호서식의 청원처리부를 갖추고, 청원의 처리경위 등을 기록ㆍ유지하여야 한다.', 2888);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5074, '① 신입보호소년의 이송은 보호처분에 대한 항고제기기간이 지난 후 지체 없이 실시하여야 한다. 다만, 보호소년 및 보호소년의 보호자가 항고제기의사가 없음을 밝히고, 별지 제4호서식의 항고권포기 서약서를 작성하여 제출한 경우에는 항고제기기간이 지나기 전이라도 이송할 수 있다.', 2890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5075, '② 소년원장은 법 제12조에 따라 보호소년을 다른 소년원으로 이송하려면 이송할 보호소년의 인적사항, 이송사유, 그 밖에 필요한 사항을 구체적으로 제시하여 법무부장관에게 이송허가를 신청해야 한다. <개정 2021.4.20>', 2890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5076, '③ 소년원장은 제1항에 따라 이송허가를 받아 보호소년을 다른 소년원에 이송할 때에는 그 보호소년의 소년관리기록부ㆍ보관금품 및 별지 제12호서식에 따른 보관금품 보관증(기관 보관용을 말한다) 그 밖의 참고자료를 인수소년원에 인계하여야 한다. <개정 2016.9.29>', 2890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5077, '① 소년원장은 보호소년이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 보호소년을 의료재활소년원으로 이송하도록 허가해 줄 것을 법무부장관에게 신청할 수 있다. <개정 2021.4.20>', 2892);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5078, '② 제1항에 따른 이송허가의 구체적인 기준은 법무부장관이 정한다.', 2892);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5079, '① 소년원장은 의료재활소년원으로의 이송을 신청할 때에는 별지 제5호서식에 따른 소속 의무과장의 진료소견서를 첨부해야 한다. <개정 2016.9.29, 2021.4.20>', 2893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5080, '② 보호소년을 의료재활소년원으로 이송하는 경우 인계기관은 해당 보호소년의 의무ㆍ진료와 관련된 모든 자료의 원본 또는 출력물을 인수기관으로 보내고 그 사본을 보관해야 한다. <개정 2021.4.20>', 2893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5081, '③ 의료재활소년원장은 보호소년이 개별처우계획에 따른 의료재활과정을 마쳤을 때에는 해당 보호소년을 처우하기에 적합한 소년원을 정하여 법무부장관에게 이송을 신청해야 한다. 이 경우 처우ㆍ징계위원회의 심사를 거쳐야 한다. <개정 2021.4.20>', 2893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5082, '④ 제1항부터 제3항까지에서 규정한 사항 외에 의료재활소년원으로의 이송절차 등에 관한 구체적인 사항은 법무부장관이 정한다. <신설 2016.9.29, 2021.4.20>', 2893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5083, '① 원장은 보호소년등의 특성ㆍ인원ㆍ감호환경 그 밖에 사고방지를 위한 모든 여건을 고려하여 감호직원을 배치하여야 한다.', 2895);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5084, '② 제1항에 따라 감호의 임무를 부여받은 사람은 보호소년등을 방치하거나 감호 중에 무단이석ㆍ음주ㆍ독서ㆍ잡무처리 등 감호 외의 용무를 보아서는 아니된다.', 2895);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5085, '① 수갑의 사용방법은 다음 각 호와 같다. 이 경우 수갑은 손목에만 채워야 하며, 주요 동맥이나 정맥을 압박하여 피가 통하지 않도록 해서는 안 된다.', 2896);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5086, '② 포승의 사용방법은 다음 각 호와 같이 하되, 주요 동맥이나 정맥을 압박하여 피가 통하지 않도록 해서는 안 된다. 다만, 제1호부터 제4호까지의 규정에도 불구하고 원장은 영 제2조제2호에 따른 향상된 처우를 하는 경우로서 보호소년등이 이탈할 위험성이 크지 않다고 판단되는 경우에는 포승을 사용하지 않을 수 있다.', 2896);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5087, '③ 가스총의 사용방법은 다음 각 호와 같다.', 2896);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5088, '④ 전자충격기의 사용방법은 다음 각 호와 같다.', 2896);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5089, '⑤ 머리보호장비는 별표 1의10의 방법으로 사용한다. 이 경우 보호소년등이 머리보호장비를 임의로 해제하지 못하도록 수갑이나 포승을 함께 사용할 수 있다.', 2896);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5090, '⑥ 보호대는 보호대에 부착된 고리에 수갑을 연결하여 별표 1의11의 방법으로 사용한다.', 2896);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5091, '⑦ 법 제14조의2제1항에 따른 보호장비를 사용하려면 미리 원장의 허가를 받아야 한다. 다만, 긴급한 경우에는 사용 후 즉시 원장에게 보고해야 한다.', 2896);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5092, '⑧ 제1항부터 제7항까지의 규정에서 정한 사항 외에 그 밖에 보호장비의 사용방법 등에 관한 세부 사항은 법무부장관이 정한다.', 2896);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5093, '① 원장은 보호장비의 관리책임을 지며, 월 1회 이상 소속기관의 보호장비 사용실태를 확인ㆍ점검하여야 한다. <개정 2014.1.29>', 2897);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5094, '② 보호장비는 항상 사용가능한 상태를 유지하여야 하며, 보관은 별도의 캐비넷에 하여야 한다. <개정 2014.1.29>', 2897);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5095, '③ 보호장비를 사용할 때에는 별지 제34호서식의 보호장비 사용 기록부에 기록ㆍ관리한다. <개정 2014.1.29>', 2897);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5096, '④ 유효기간이 지난 가스총의 탄환 및 분사약재 등은 폐기해야 한다. <신설 2021.4.20>', 2897);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5097, '⑤ 제1항부터 제4항까지의 규정에서 정한 사항 외에 보호장비의 관리 등에 관한 세부 사항은 법무부장관이 정한다. <신설 2016.9.29, 2021.4.20>', 2897);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5098, null, 2898);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5099, '① 원장은 전자장비의 효율적인 운용을 위하여 각종 전자장비를 통합적으로 관리할 수 있는 시스템이 설치된 통제실을 설치하여 운영한다.', 2899);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5100, '② 원장은 통제실에 대한 외부인의 출입을 제한하여야 한다. 다만, 시찰ㆍ참관이나 그 밖에 원장이 특별히 필요하다고 인정하는 경우에는 외부인의 출입을 허가할 수 있다.', 2899);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5101, '① 영상정보처리기기 중 카메라는 소년원등의 청사 정문ㆍ운동장, 외곽 담장, 생활관 내 복도, 각 생활실, 생활지도실, 그 밖에 보호소년등의 감호에 필요한 장소로서 법무부장관이 정하는 장소에 설치한다. <개정 2021.4.20>', 2900);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5102, '② 영상정보처리기기 중 모니터는 상황실ㆍ생활지도실, 그 밖에 소년원등의 소속 공무원(이하 제24조의10까지에서 "소속공무원"이라 한다)이 보호소년등을 감호하기에 적정한 장소로서 법무부장관이 정하는 장소에 설치한다. <개정 2021.4.20>', 2900);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5103, '③ 제1항 및 제2항에서 규정한 사항 외에 영상정보처리기기의 운영ㆍ관리 등에 관한 세부 사항은 법무부장관이 정한다.', 2900);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5104, '① 고정식 물품검색기는 정문, 생활관 입구, 교육관 입구, 그 밖에 보호소년등이나 소년원등에 출입하는 외부인에 대한 신체ㆍ의류ㆍ휴대품의 검사가 필요한 장소에 설치한다. <개정 2021.4.20>', 2903);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5105, '② 소속공무원이 영 제17조의3제1항에 따라 보호소년등의 신체ㆍ의류ㆍ휴대품을 검사하는 경우에는 특별한 사정이 없으면 고정식 물품검색기를 통과하게 한 후 휴대식 금속탐지기나 손으로 이를 확인한다.', 2903);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5106, '③ 소속공무원이 영 제18조제1항에 따라 소년원등을 출입하는 외부인의 의류와 휴대품을 검사하는 경우에는 고정식 물품검색기를 통과하게 하거나 휴대식 금속탐지기로 이를 확인한다. <개정 2021.4.20>', 2903);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5107, '① 원장은 보호소년등의 인원ㆍ소지품ㆍ이용시설 그 밖에 필요한 사항을 수시로 점검하고 보호소년등이 허가없이 외부인과 접촉하는 것을 금지하여야 한다.', 2906);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5108, '② 원장은 보호소년등이 외출하거나 생활관을 출입할 때에는 반드시 소지품검사를 하여 부정물품반입을 예방하여야 한다.', 2906);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5109, '③ 원장은 수시로 생활실 등 각종 시설의 이상유무, 부정물품의 은닉여부 그 밖에 필요한 사항을 점검하여야 한다.', 2906);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5110, null, 2909);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5111, '① 원장은 규율을 위반한 보호소년등을 징계할 때에는 별표 2의 보호소년등의 징계기준에 따라야 한다. <개정 2021.4.20>', 2910);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5112, '② 삭제 <2014.1.29>', 2910);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5113, '③ 소년원장은 제1항에 따른 징계를 받은 보호소년에 대하여 각각 다음 각 호에 따른 점수를 해당 보호소년의 교정성적에서 뺀다. <개정 2014.1.29, 2016.9.29>', 2910);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5114, '④ 보호소년에 대하여 법 제15조제2항에 따라 여러 처분을 함께 부과하는 경우에는 제3항 각 호에 따른 점수가 가장 높은 처분의 점수만을 해당 보호소년의 교정성적에서 뺀다. <신설 2016.9.29>', 2910);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5115, '⑤ 소년분류심사원장은 징계를 받은 위탁소년 및 유치소년에 대하여는 분류심사관에게 통보하여 분류심사에 반영하여야 한다. <개정 2014.1.29, 2016.9.29>', 2910);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5116, null, 2911);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5117, '① 원장은 별표 3의 분기별 반입품 허가기준에 따라 자체실정에 맞는 반입기준을 정하여 물품의 반입을 허가할 수 있다. 다만, 다음 각 호의 어느 하나에 해당한다고 인정되는 물품에 대하여는 반입을 허가하지 아니한다.', 2915);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5118, '② 반입품은 별지 제8호서식의 개인별 반입품관리부에 기록ㆍ관리하여야 한다.', 2915);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5119, '① 법 제18조제1항에 따른 보호소년등의 면회는 면회실에서 하여야 한다.', 2916);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5120, '② 면회실에는 상담직원을 배치하고 다음 각 호의 사항을 구비하여 면회인의 편의를 도모하며 수시로 의견을 청취하여 민원개선에 노력하여야 한다.', 2916);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5121, '③ 원장은 제1항에도 불구하고 특별한 사유가 있으면 면회인과 보호소년등이 보다 안정된 분위기 속에서 면회를 할 수 있도록 별도의 장소를 활용할 수 있다.', 2916);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5122, '① 원장은 면회를 신청하는 사람의 성명ㆍ주소 및 보호소년등과의 관계 등을 확인하고 면회허가여부를 결정하여야 한다.', 2917);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5123, '② 원장은 면회를 신청하는 사람이 해당 사건의 변호인 또는 수사관련 공무원인 경우에는 신분 및 면회신청사유 등을 확인한 후 면회를 허가하여야 한다.', 2917);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5124, null, 2919);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5125, '① 원장은 법 제18조제6항에 따른 전화통화를 할 수 있는 별도의 장소를 지정하여야 한다.', 2920);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5126, '② 전화통화는 평일 근무시간에 한정한다. 다만, 원장은 특별히 필요하다고 인정하는 경우에는 야간 및 휴일에도 전화통화를 허가할 수 있다.', 2920);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5127, '③ 제1항 및 제2항에서 규정한 사항 외에 전화통화의 신청 및 기록 등에 관한 세부 사항은 법무부장관이 정한다.', 2920);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5128, '① 보호소년이 법 제19조에 따른 외출을 허가받으려면 별지 제10호서식의 외출신청서를 작성하여 해당 소년원장에게 제출하여야 한다.', 2921);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5129, '② 보호소년 또는 그 보호자가 영 제40조 단서에 따라 외출을 연장하려면 외출기간이 종료되기 전에 별지 제10호서식에 따른 외출기간연장신청서를 제출하고 소년원장의 허가를 받아야 한다. <개정 2012.8.2>', 2921);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5130, '① 영 제41조제1항에 따른 준수사항에는 다음 각 호의 내용이 포함되어야 한다.', 2923);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5131, '② 소년원장은 보호소년의 자유를 부당하게 제한하지 아니하는 범위에서 제1항에 따른 준수사항 외에 별도의 특별한 준수사항을 부과할 수 있다.', 2923);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5132, '③ 영 제66조 및 영 제76조에 따른 통학 또는 통근취업 대상자에 대하여는 제1항 및 제2항의 규정을 준용한다.', 2923);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5133, '① 원장은 보호소년등의 보건ㆍ위생관리를 위한 종합대책과 세부생활지도계획을 분기별로 수립ㆍ시행하여야 한다.', 2924);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5134, '② 원장은 제9조제2항제3호에 따른 신체검사 등을 통하여 문신이 있는지 확인하고 해당 보호소년등이 문신제거 시술을 원하는 경우에는 신청에 의하여 문신제거 시술을 할 수 있다.', 2924);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5135, '① 원장은 보호소년등의 보건위생을 위하여 보호소년등의 신체ㆍ의류ㆍ거실ㆍ침구ㆍ식기ㆍ취사장ㆍ화장실 그 밖의 생활환경을 청결히 하도록 하여야 한다.', 2925);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5136, '② 원장은 제1항에 따른 생활환경의 청결유지상태를 월 1회 이상 점검하여야 한다.', 2925);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5137, '① 영 제42조에 따른 정기검진은 분기별로 1회 이상 실시하되, 「학교건강검사규칙」 제4조 및 제5조에 따른 신체검사 및 건강검진이 연 1회 이상 포함되어야 한다.', 2927);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5138, '② 영 제3조제1항제1호에 따른 초ㆍ중등교육소년원(이하 "소년원학교"라 한다)의 원장(이하 "소년원학교장"이라 한다)은 보호소년을 대상으로 연 1회 이상 체력검사를 실시하고 그 결과를 기록ㆍ유지해야 한다. <개정 2021.4.20>', 2927);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5139, '③ 제2항에 따른 체력검사의 대상ㆍ종목ㆍ시기ㆍ방법ㆍ급수판정 및 관리 등에 관하여는 「학교건강검사규칙」 제7조부터 제9조까지의 규정을 준용한다.', 2927);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5140, '① 소년원등의 소속 의료인은 보호소년등의 치료를 위하여 보호소년등을 진료한 의료인 또는 의료기관의 장에게 「의료법」 제22조 또는 제23조에 따른 진료기록의 내용 확인이나 진료기록의 사본 및 환자의 진료경과에 대한 소견 등을 송부하거나 전송할 것을 요청하는 경우에는 같은 법 제21조의2제1항에 따라 해당 보호소년이나 그 보호자의 동의를 받아야 한다.', 2930);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5141, '② 소년원등의 소속 의료인은 의료재활소년원 출원생이 외래진료를 받은 법 제20조의3제2항 전단에 따라 법무부장관이 지정하는 기관(이하 "지정법무병원"이라 한다)의 의료인 또는 의료기관의 장으로부터 「의료법」 제21조의2에 따라 요청받은 같은 법 제22조 또는 제23조에 따른 진료기록의 내용 확인이나 진료기록의 사본 및 환자의 진료경과에 대한 소견 등을 송부 또는 전송하려는 경우에는 해당 출원생이나 그 보호자의 동의를 받아야 한다.', 2930);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5142, '① 법 제20조의3제1항 및 제2항에 따른 외래진료기간은 의료재활소년원 출원일부터 10년의 범위로 한다.', 2931);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5143, '② 법 제20조의3제1항 및 제2항에 따른 외래진료의 방법은 영 제3조제1항제3호의 약물 오ㆍ남용 및 정신장애에 대한 의료재활을 위하여 필요한 정신건강의학과 의사의 진료, 검사시설에 의한 검사, 처방 및 투약 등으로 한다.', 2931);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5144, '① 법무부장관은 법 제20조의3제2항 전단에 따라 의료재활소년원 출원생이 지정법무병원에서 외래진료를 받도록 한 경우에는 같은 항 후단에 따라 예산의 범위에서 지정법무병원에 외래진료 진료비용(「국민건강보험법」, 「의료급여법」, 그 밖의 다른 법령에 따라 의료재활소년원 출원생 또는 보호자등이 부담하지 않는 비용은 제외한다)을 지급한다.', 2932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5145, '② 제1항에 따라 외래진료 진료비용을 지급받으려는 지정법무병원의 장은 별지 제11호서식의 외래진료 진료비용 지급 청구서에 의료재활소년원 출원생별 진료비 계산서를 첨부하여 「치료감호 등에 관한 법률 시행령」 제4조의5제2항에 따른 제출기간에 법무부장관에게 제출해야 한다.', 2932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5146, '① 법 제3조제2항 각 호에 따른 분류심사, 상담조사 및 검사의 결정 전 조사(이하 "분류심사등"이라 한다)는 면접조사, 심리검사, 정신의학적 진단, 행동관찰, 자기기록 검토, 자료조회, 현지조사 등의 방법에 따른다. <개정 2021.4.20>', 2936);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5147, '② 분류심사는 다음 각 호와 같이 구분한다.', 2936);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5148, '③ 분류심사의 실시기준은 별표 4와 같다.', 2936);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5149, '① 면접조사는 다음 각 호의 구분에 따른 방법으로 하여야 한다. <개정 2010.12.13, 2021.4.20>', 2937);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5150, '② 분류심사관은 면접대상자가 심리적 안정감을 가질 수 있도록 친절하게 대하고 용모ㆍ태도ㆍ언어 등에 유의하여야 한다.', 2937);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5151, '① 소년에 대한 행동관찰은 객관적이고 신뢰성있게 하고 그 결과가 분류심사등에 유용하도록 제공되어야 한다.', 2938);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5152, '② 소년분류심사원장은 행동관찰 업무를 적정하게 하기 위하여 담당직원의 교육, 부서간의 협조 독려 그 밖에 필요한 조치를 하여야 한다.', 2938);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5153, '① 소년분류심사원장은 법 제25조제2항에 따라 다음 각 호의 어느 하나에 해당하는 사람 중에서 분류심사관을 임명하여야 한다. <개정 2011.4.5, 2022.12.19>', 2939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5154, '② 소년분류심사원장은 각종 전문교육, 관련 학회 등에 분류심사관의 참여를 적극 권장하는 등 분류심사관의 자질향상을 위하여 노력하여야 한다. <개정 2010.12.13>', 2939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5155, '③ 소년분류심사원장은 분류심사에 필요한 각종 검사기구의 구비, 전문성 증진을 위한 연구개발지원 등 분류심사의 과학화를 위하여 노력하여야 한다. <개정 2010.12.13>', 2939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5156, '① 소년원장은 신입보호소년에 대하여 생활규범지도, 기초교육, 적응훈련 그 밖에 필요한 지도를 함으로써 신입보호소년이 소년원에 신속히 적응하고 심신의 안정을 도모할 수 있도록 하여야 한다.', 2941);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5157, '② 제1항에 따른 신입자교육기간은 10일 이내로 한다.', 2941);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5158, '① 소년원장은 보호소년이 제54조에 따른 기본교육과정을 마치고 퇴원 또는 임시퇴원의 요건을 갖춘 때에는 사회적응에 필요한 진로상담, 장래의 생활설계에 대한 지도, 퇴원 또는 임시퇴원 후의 준수사항에 대한 교육 그 밖에 사회복귀에 필요한 교육을 실시한다.', 2943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5159, '② 소년원장은 제1항에 따른 보호소년에게 퇴원이나 임시퇴원 후에도 자립생활관 이용, 취업알선 및 창업보육 등의 사회정착지원을 받을 수 있음을 알려 주어야 한다. <개정 2016.9.29, 2021.4.20>', 2943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5160, '③ 제1항에 따른 사회복귀교육기간은 10일 이내로 한다.', 2943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5161, '① 영 제58조제1항에 따른 소년관리기록부에는 다음 각 호의 자료가 포함되어야 한다. <개정 2014.1.29, 2021.4.20>', 2947);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5162, '② 원장은 보호소년등을 다른 기관으로 이송할 때에는 영 제64조에 따른 학교생활기록부와 함께 소년관리기록부를 송부하여야 한다.', 2947);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5163, '① 소년원학교장은 학칙을 제정하거나 개정할 때에는 법무부장관의 승인을 받아야 한다.', 2948);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5164, '② 제1항에 따른 학칙에는 다음 각 호의 사항이 포함되어야 한다.', 2948);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5165, null, 2949);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5166, '① 영 제67조에 따라 졸업대상자로 결정된 보호소년에 대하여는 별지 제18호서식의 졸업대장에 기록하고, 별지 제19호서식의 졸업증서를 발급한다.', 2953);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5167, '② 법 제34조제1항에 따라 전적학교(前籍學校)의 졸업장 취득을 위해 학적사항을 통지하는 방법 및 절차 등에 관하여는 제64조를 준용한다. <개정 2021.4.20>', 2953);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5168, '③ 제1항에 따른 졸업장 및 법 제34조에 따른 전적학교의 졸업장은 가능하면 보호소년이 모두 모인 장소에서 소년원학교장이 본인에게 직접 수여해야 한다. <개정 2021.4.20>', 2953);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5169, '① 소년원장은 필요하다고 판단되는 경우 「근로자직업능력 개발법」에서 고용노동부장관이 정한 직업능력개발훈련기준에 따라 직업능력개발훈련 직종을 신설 또는 폐지할 수 있다. 이 경우 지방고용노동관서의 장과 협의를 거쳐 법무부장관의 승인을 받아야 한다. <개정 2014.1.29>', 2955);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5170, '② 소년원장은 제1항에 따라 직업능력개발훈련 직종을 신설하거나 폐지하는 경우에는 산업계의 인력수요를 조사ㆍ파악하여 이를 적절히 반영하여야 한다.', 2955);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5171, '③ 제1항에 따라 신설되는 직종의 수업일수, 교과편성 그 밖에 필요한 사항은 법무부장관의 승인을 받아 소년원장이 정한다.', 2955);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5172, '① 직업능력개발훈련을 받을 수 있는 보호소년은 15세 이상으로 한다.', 2956);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5173, '② 소년원장은 훈련직종 또는 훈련과정에 따라 보호소년의 연령 또는 학력의 기준을 따로 정할 수 있다.', 2956);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5174, '① 소년원장은 법 제37조제1항에 따라 통근취업을 하는 보호소년의 원만한 적응과 교통편의 등을 위하여 예산의 범위에서 통근취업 기간 중의 교통비 전액 또는 일부를 지원할 수 있다.', 2957);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5175, '② 소년원장은 보호소년의 통근취업으로 발생한 보수 등에 관하여는 영 제47조의 규정을 준용하여 관리하여야 한다.', 2957);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5176, '③ 영 제76조제2항에 따른 통근취업약정서는 별지 제24호서식에 따른다.', 2957);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5177, '① 원장은 보호소년등의 심신이 조화롭게 성장ㆍ발달할 수 있도록 일과를 진행하여야 한다.', 2958);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5178, '② 원장은 보호소년등이 8시간 이상 취침할 수 있도록 하여야 한다. 다만, 수업시간 수 확보 등 교육과정의 운영상 불가피한 경우에는 그러하지 아니하다.', 2958);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5179, '③ 원장은 교정교육상 특히 필요한 경우를 제외하고는 보호소년등의 정서함양을 위하여 공휴일에는 직원의 지도로 보호소년등이 다양한 여가선용프로그램에 참여하거나 휴식할 수 있도록 하여야 한다.', 2958);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5180, '④ 국경일 및 스승의 날, 성년의 날 등 교육적으로 필요하다고 인정되는 기념일에는 경축ㆍ기념의식 또는 관련 교육행사를 가질 수 있다. <개정 2014.1.29>', 2958);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5181, '① 소년원장은 보호소년이 자발적으로 교육목표를 달성할 수 있도록 자치회를 조직하여 운영하게 할 수 있다.', 2960);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5182, '② 제1항에 따른 자치회는 소년원의 관리ㆍ규율ㆍ설비ㆍ급양(給養)ㆍ의료 및 위생에 관한 업무에 관여할 수 없다. 다만, 소년원장 또는 직원이 함께 참석하여 자치회를 개최하는 경우에는 관련 의견을 제시할 수 있다. <개정 2022.2.7>', 2960);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5183, '③ 제1항에 따른 자치회의 대표자와 임원의 임면, 자치회의 조직 및 운영에 관하여 필요한 사항은 소년원장이 정한다.', 2960);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5184, '① 원장은 법 제42조의2에 따른 대안교육과정의 운영을 위한 계획을 수립하여 시행하여야 한다.', 2961);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5185, '② 제1항에 따른 대안교육과정운영계획에는 다음 각 호의 내용이 포함되어야 한다. 다만, 교육기간 및 대상에 따라 이를 달리 수립ㆍ시행할 수 있다. <개정 2014.1.29>', 2961);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5186, '③ 원장은 대안교육대상자와 보호소년등을 분리하여 관리하여야 한다.', 2961);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5187, '① 원장은 교정교육의 효과를 높이기 위하여 필요하다고 인정되는 경우에는 관계직원으로 하여금 보호자상담을 실시하게 할 수 있다.', 2962);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5188, '② 관계직원이 제1항에 따른 보호자상담을 실시하려는 때에는 지정된 장소에서 실시하고 별지 제25호서식의 보호자상담부에 상담내용을 기록ㆍ유지하여야 한다.', 2962);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5189, '③ 영 제86조제1항에 따른 보호자교육의 대상자를 선정하는 때에는 제1항에 따른 보호자상담 결과를 고려하여야 한다.', 2962);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5190, '① 소년원장이 법 제43조제3항 및 제44조에 따라 관할 보호관찰심사위원회에 보호소년의 출원심사를 신청하는 경우에는 처우ㆍ징계위원회의 심사를 거쳐 퇴원, 임시퇴원 여부를 구분하여 신청해야 한다. <개정 2021.4.20>', 2963);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5191, '②제1항에 따른 보호소년의 출원에 관한 처우ㆍ징계위원회의 심사를 할 때에는 보호소년의 생활태도, 교정성적, 사회적응 정도 및 보호자의 보호력 등을 종합적으로 고려해야 한다. <개정 2021.4.20>', 2963);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5192, '③그 밖에 보호소년의 출원에 관한 처우ㆍ징계위원회의 심사 및 보호관찰심사위원회로의 심사 신청에 관한 사항은 법무부장관이 따로 정한다. <개정 2021.4.20>', 2963);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5193, null, 2964);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5194, null, 2965);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5195, '① 소년원장은 보호소년이 임시퇴원하는 경우에는 보호관찰의 실효성을 높이기 위하여 지체 없이 임시퇴원자에 관한 분류심사서 사본 및 별지 제26호서식의 교육ㆍ생활지도부 등을 해당 보호관찰소에 송부하여야 한다. <개정 2014.1.29>', 2966);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5196, '② 소년원장은 법 제46조제1항에 따른 계속수용의 사유가 소멸하여 보호소년을 보호자등에게 인도할 때에는 보호소년과 보호자등에게 지체 없이 관할보호관찰소에 출석ㆍ신고할 것을 고지하고 보호관찰소장에게 출원사실을 통보하여야 한다.', 2966);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5197, '① 소년원장은 퇴원 또는 임시퇴원이 허가된 보호소년에 대하여 수료식을 실시하고 별지 제27호서식에 따른 퇴원증 또는 별지 제28호서식에 따른 임시퇴원증을 내주어야 한다.', 2967);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5198, '② 소년원장은 임시퇴원자에 대하여 보호관찰기간 중의 준수사항을 이행하도록 교육하고 신고기일 이내에 관할보호관찰소에 출석하여 신고할 것을 알려주어야 한다.', 2967);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5199, '① 법 제45조제1항에 따른 보호소년의 인도에 관한 통지는 별지 제29호서식에 따른다.', 2968);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5200, '② 소년원장은 법 제45조제2항에 따라 보호소년을 보호자, 사회복지단체 또는 독지가 등에게 인도할 때에는 별지 제30호서식의 보호자인도부에 그 사실을 기록ㆍ유지하여야 한다.', 2968);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5201, '① 원장은 법 제45조의2에 따른 사회정착지원에 관한 계획을 수립ㆍ시행하여야 한다. <개정 2016.9.29>', 2969);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5202, '② 제1항에 따른 계획은 취업ㆍ진학 등 보호소년등의 진로를 고려하여 수립하되, 이 계획에는 방문ㆍ출석ㆍ통신지도 등 사회정착지원 방법과 기간ㆍ횟수 등의 구체적인 내용이 포함되어야 한다. <개정 2016.9.29>', 2969);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5203, '③ 원장은 제1항에 따른 계획을 수립하기 전에 보호소년등으로부터 사회정착지원을 희망하는 구체적인 분야 등을 청취한 후 이를 계획에 반영하여야 한다. <개정 2016.9.29>', 2969);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5204, '④ 원장은 법 제45조의2제2항에 따라 사회정착지원 기간을 연장하려는 경우에는 보호소년등의 재범 여부, 취업ㆍ진학 여부, 주거 안정 여부, 그 밖에 사회정착지원의 필요성 등을 고려하여 판단하여야 한다. <개정 2016.9.29>', 2969);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5205, '⑤ 원장은 보호소년등이 무의탁소년인 경우에는 법 제51조에 따른 소년보호협회가 영 제98조에 따라 운영하는 자립지원시설의 이용지원, 취업알선, 그 밖에 필요한 사회정착지원을 하여야 한다. <개정 2016.9.29>', 2969);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5206, '① 법 제46조제1항에 따른 보호소년의 계속수용은 다음 각 호의 어느 하나에 해당하는 사유로 해당 보호소년과 보호자등이 희망하는 경우에 한정한다.', 2972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5207, '② 보호소년과 보호자등이 제1항에 따른 사유로 계속수용을 희망할 때에는 퇴원일 또는 임시퇴원일을 기준으로 7일 전까지 별지 제32호서식의 계속수용신청서를 소년원장에게 제출해야 한다. <개정 2021.4.20>', 2972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5208, '③ 소년원장은 제2항에 따른 계속수용신청서를 접수받은 경우에는 처우ㆍ징계위원회의 심의를 거쳐 계속수용을 허용할 수 있다. 이 경우 해당 보호소년에게 계속수용 중의 준수사항을 지시할 수 있다. <개정 2021.4.20>', 2972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5209, '④ 계속수용기간은 다음 각 호와 같다. 이 경우 보호소년의 의사를 존중하여야 한다.', 2972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5210, '⑤ 계속수용의 교육과정은 특별한 프로그램이 마련된 경우를 제외하고는 퇴원 또는 임시퇴원허가 이전의 기본교육과정으로 분류하여야 한다.', 2972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5211, '⑥ 법 제46조제3항에 따른 보호소년의 계속수용사실의 통지는 별지 제33호서식에 따른다.', 2972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5212, '① 영 제88조제2항에 따라 임시퇴원취소자의 신병을 인수한 소년원장은 지체 없이 임시퇴원 당시의 해당 소년원장에게 신병인수 사실을 알리고, 가정ㆍ학교ㆍ사회환경 및 임시퇴원 기간 중의 생활상태를 종합심사하기 위한 처우ㆍ징계위원회의 심사를 거쳐 자체수용 또는 이송여부를 결정해야 한다. <개정 2021.4.20>', 2973);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5213, '② 제1항에 따라 임시퇴원취소자를 자체수용하기로 결정한 때에는 지체 없이 임시퇴원 당시의 해당 소년원장에게 그 사실을 알리고, 개별처우계획의 수립에 필요한 자료의 제출을 요구할 수 있다.', 2973);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5214, '③ 제1항에 따라 이송을 결정한 때에는 지체 없이 임시퇴원취소자의 신병을 임시퇴원 당시의 소년원에 이송하여야 한다.', 2973);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5215, '① 소년원장은 임시퇴원된 보호소년이 영 제88조에 따라 임시퇴원이 취소되어 재수용된 때에는 제53조에 따른 신입자교육을 실시하고, 처우ㆍ징계위원회의 심사를 거쳐 개별처우계획을 새로 수립해야 한다. 다만, 재수용된 보호소년의 잔여 수용기간이 40일 미만인 경우에는 처우ㆍ징계위원회의 심사를 생략하고 임시퇴원 당시의 과정에 편성할 수 있다. <개정 2014.1.29, 2021.4.20>', 2974);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5216, '② 소년원장은 임시퇴원자가 보호관찰기간 중에 범법행위를 하여 임시퇴원이 취소되고 징역 또는 금고 이상의 유죄판결이 확정되거나 보호처분에 의하여 소년원에 송치된 때에는 이전의 보호처분취소를 법원소년부에 신청하여야 한다.', 2974);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5217, '① 청소년심리상담실 이용에 따른 실비는 그 수혜자가 부담함을 원칙으로 한다. 다만, 다음 각 호의 어느 하나에 해당하는 사람에게는 실비의 징수를 면제할 수 있다.', 2976);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5218, '② 실비의 산정기준은 소속 공무원의 인건비를 제외한 프로그램 운영비 및 검사용지 매입가를 기준으로 하되, 100원 미만은 버린다.', 2976);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5219, '① 법무부장관은 보호소년등의 선도ㆍ보호에 관한 학식과 경험이 풍부한 자를 소년보호위원으로 위촉하여 교정교육에 참여시킬 수 있다. 다만, 다음 각 호의 어느 하나에 해당하는 자는 소년보호위원으로 위촉할 수 없다.', 2977);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5220, '② 원장은 소년보호위원으로 위촉된 자가 제1항 각 호의 어느 하나에 해당되는 사유가 발생한 때에는 지체 없이 사유서 등을 첨부하여 법무부장관에게 해촉을 신청하여야 한다.', 2977);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5221, '① 법 제51조에 따라 설치된 소년보호협회(이하 "협회"라 한다)는 영 제98조제2항에 따른 수익사업의 경영으로 목적사업에 지장을 초래하여서는 아니되며, 그 수익은 목적사업을 위하여 사용하여야 한다.', 2979);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5222, '② 협회는 영 제98조제3항에 따라 수익사업의 승인 또는 변경승인을 신청하는 경우에는 승인신청서에 다음 각 호의 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 2979);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5223, '③ 영 제99조제3항에 따라 협회가 법무부장관에게 제출하는 사업실적 및 결산서에는 해당 회계연도의 대차대조표ㆍ손익계산서ㆍ재산목록ㆍ잉여금처분계산서ㆍ감사의견서 및 관련 서류가 포함되어야 한다.', 2979);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5224, '① 영 제102조제1항에 따른 기부금품의 접수 영수증은 「법인세법 시행규칙」 제82조제7항제3호의3의 별지 제63호의3서식에 따른다.', 2980);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5225, '② 영 제102조제5항에 따른 기부금품의 접수현황 및 사용실적 등에 관한 장부는 별지 제35호서식에 따른다.', 2980);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5226, null, 2982);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5227, '① 불법재산은 몰수한다.', 2983);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5228, '② 제1항에 따라 몰수하여야 할 재산에 대하여 재산의 성질, 사용 상황, 그 재산에 관한 범인 외의 자의 권리 유무, 그 밖의 사정을 고려한 결과 그 재산을 몰수하는 것이 타당하지 아니하다고 인정될 경우에는 제1항에도 불구하고 몰수하지 아니할 수 있다.', 2983);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5229, '③ 제1항의 경우 「형사소송법」 제333조제1항 및 제2항은 적용하지 아니한다.', 2983);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5230, '① 제3조에 따른 몰수는 불법재산 또는 혼합재산이 범인 외의 자에게 귀속되지 아니하는 경우에만 한다. 다만, 제2조제1호나목의 죄와 같은 호 다목의 죄 중 「특정범죄가중처벌 등에 관한 법률」 제5조의 죄의 경우로서 불법재산 또는 혼합재산이 국가 또는 지방자치단체의 소유인 경우 및 범인 외의 자가 범죄 후 그 정황을 알면서도 그 불법재산 또는 혼합재산을 취득한 경우(법령상의 의무 이행으로서 제공된 것을 취득한 경우나 채권자에게 상당한 재산상의 이익을 제공하는 계약을 할 당시에 그 계약에 관련된 채무 이행이 불법재산 또는 혼합재산에 의한다는 사실을 알지 못하고 그 계약에 관련된 채무의 이행으로 제공된 것을 취득한 경우는 제외한다)에는 그 불법재산 또는 혼합재산이 범인 외의 자에게 귀속되었더라도 몰수할 수 있다.', 2985);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5231, '② 지상권ㆍ저당권 또는 그 밖의 권리가 그 위에 존재하는 재산을 제3조에 따라 몰수하는 경우, 범인 외의 자가 범죄 전에 그 권리를 취득한 경우 또는 범인 외의 자가 범죄 후 그 정황을 알지 못하고 그 권리를 취득한 경우에는 해당 권리를 존속시킨다.', 2985);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5232, '① 몰수된 재산은 검사가 처분하여야 한다.', 2989);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5233, '② 검사는 채권의 몰수재판이 확정된 때에는 그 채권의 채무자에게 몰수재판의 초본을 송부하여 그 요지를 알려야 한다.', 2989);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5234, '① 검사는 이 법에 따른 몰수ㆍ추징의 집행을 위하여 필요하다고 인정되면 그 목적에 필요한 최소한의 범위에서 다음 각 호의 처분을 할 수 있다. 다만, 범인 외의 자에 대한 제4호 및 제5호의 처분은 제3항에 따른 영장이 있어야 한다. <개정 2020.3.24>', 2991);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5235, '② 제1항의 자료제공 요청에 대하여 해당 기관은 다른 법률을 근거로 이를 거부할 수 없다.', 2991);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5236, '③ 검사는 이 법에 따른 몰수ㆍ추징의 집행을 위하여 필요한 경우 지방법원판사에게 청구하여 발부받은 영장에 의하여 압수ㆍ수색 또는 검증을 할 수 있다.', 2991);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5237, null, 2993);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5238, '① 제2조제1호나목의 범죄행위 또는 같은 호 다목 중 「특정범죄가중처벌 등에 관한 법률」 제5조의 범죄행위와 관련하여 몰수판결 또는 추징판결이 확정된 경우, 피해를 입은 국가의 특별회계 관리주체와 지방자치단체는 국가에 대하여 피해액에 상당하는 금액의 지급을 요구할 수 있다.', 2995);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5239, '② 국가는 제1항의 요구가 정당하다고 인정하는 경우에는 해당 범죄행위와 관련한 몰수 또는 추징으로 국고에 귀속된 금액의 범위에서 피해액에 상당하는 금액을 지급하여야 한다.', 2995);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5240, '① 검사는 공소를 제기할 때 이 법에 따라 피고인 외의 자(국가 또는 지방자치단체는 제외한다)의 재산이나 지상권ㆍ저당권 또는 그 밖의 권리가 그 위에 존재하는 재산을 몰수할 필요가 있다고 인정하는 경우에는 즉시 해당 재산을 가진 자나 그 재산상에  지상권ㆍ저당권 또는 그 밖의 권리를 가진 자로서 피고인 외의 자(이하 "제3자"라 한다)에게 서면으로 다음 각 호의 사항을 고지하여야 한다.', 2996);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5241, '② 검사는 제3자의 소재(所在)를 알 수 없거나 그 밖의 사유로 제1항의 고지를 할 수 없을 때에는 제1항 각 호의 사항을 관보나 일간신문에 싣고 검찰청 게시판에 14일간 게시하여 공고하여야 한다.', 2996);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5242, '③ 검사가 제1항 또는 제2항에 따른 고지 또는 공고를 하였을 때에는 그 사실을 증명하는 서면을 법원에 제출하여야 한다.', 2996);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5243, '① 몰수될 염려가 있는 재산을 가진 제3자는 제1심 재판이 있기까지(약식절차에 의한 재판이 있는 경우에는 정식재판 청구가 가능한 기간이 지나기까지를 말하며, 이 경우 정식재판 청구가 있을 때에는 통상의 공판절차에 의한 제1심 재판이 있기까지를 말한다. 이하 같다) 피고인에 대한 형사사건이 계속 중인 법원에 서면으로 그 형사사건 절차에 대한 참가신청을 할 수 있다. 다만, 제13조제1항 또는 제2항에 따른 고지 또는 공고가 있은 때에는 고지 또는 공고가 있었던 날부터 14일 이내에만 참가신청을 할 수 있다.', 2997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5244, '② 검사가 제13조제1항 또는 제2항에 따라 고지 또는 공고한 법원이 피고인에 대한 형사사건을 이송한 경우에 그 법원에 제3자가 참가신청을 하였을 때에는, 신청을 받은 법원은 피고인에 대한 형사사건을 이송받은 법원에 그 신청 서면을 송부하여야 한다. 이 경우 그 서면이 송부되면 피고인에 대한 형사사건에의 참가신청은 처음부터 이송받은 법원에 한 것으로 본다.', 2997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5245, '③ 법원은 제3자의 참가신청이 다음 각 호의 어느 하나에 해당하는 경우에는 기각(棄却)하여야 한다. 다만, 제1항 단서에 규정된 기간에 참가신청을 하지 아니한 것이 신청인의 책임으로 돌릴 수 없는 사유에 의한 것이라고 인정할 때에는 제1심 재판이 있기까지 참가를 허가할 수 있다.', 2997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5246, '④ 법원은 제3항 각 호의 경우를 제외하고는 참가신청을 허가하여야 한다. 다만, 몰수가 불가능하거나 불필요하다는 검사 의견이 타당하다고 인정할 때에는 참가신청을 기각할 수 있다.', 2997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5247, '⑤ 법원이 참가를 허가한 경우 몰수하여야 할 재산 또는 몰수하여야 할 재산상에 존재하는 지상권ㆍ저당권 또는 그 밖의 권리가 참가가 허가된 자(이하 "참가인"이라 한다)에게 귀속하지 아니함이 명백하게 되었을 때에는 참가를 허가한 재판을 취소하여야 하며, 몰수가 불가능하거나 불필요하다는 검사 의견이 타당하다고 인정할 때에는 참가를 허가한 재판을 취소할 수 있다.', 2997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5248, '⑥ 참가에 관한 재판은 검사, 참가신청인 또는 참가인, 피고인 또는 변호인의 의견을 듣고 결정하여야 한다.', 2997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5249, '⑦ 검사, 참가신청인 또는 참가인은 참가신청을 기각한 결정 또는 참가를 허가한 재판을 취소한 결정에 대하여 즉시항고(卽時抗告)할 수 있다.', 2997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5250, '⑧ 참가신청의 취하(取下)는 서면으로 하여야 한다. 다만, 공판기일에는 말로써 할 수 있다.', 2997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5251, '① 참가인은 이 법에 특별한 규정이 있는 경우를 제외하고는 몰수에 관하여 피고인과 동일한 소송상의 권리를 가진다.', 2998);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5252, '② 제1항은 참가인을 증인으로서 조사하는 것을 방해하지 아니한다.', 2998);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5253, '① 참가인은 공판기일에 출석하지 아니하여도 된다.', 2999);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5254, '② 법원은 참가인의 소재를 알 수 없을 때에는 공판기일의 통지나 그 밖의 서류의 송달을 하지 아니하여도 된다.', 2999);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5255, '③ 법원은 공판기일에 출석한 참가인에게 몰수의 이유가 되는 사실의 요지, 참가 전의 공판기일에 있어서의 심리(審理)에 관한 중요한 사항, 그 밖에 참가인의 권리를 보호하기 위하여 필요하다고 인정하는 사항을 고지하고, 몰수에 관하여 진술할 기회를 주어야 한다.', 2999);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5256, '① 참가인의 참가는 「형사소송법」 제310조의2, 제311조부터 제318조까지, 제318조의2 및 제318조의3을 적용하는 데에 영향을 미치지 아니한다.', 3000);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5257, '② 법원은 「형사소송법」 제318조 및 제318조의3 본문에 따라 증거로 하는 것이 가능한 서면 또는 진술을 조사한 경우에 참가인이 그 서면 또는 진술의 내용이 된 진술을 한 사람을 증인으로 조사할 것을 청구하였을 때에는 그 권리의 보호에 필요하다고 인정하면 조사를 하여야 한다. 참가인이 참가하기 전에 조사한 증인에 대하여 참가인이 다시 그 조사를 청구한 경우에도 같다.', 3000);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5258, null, 3001);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5259, '① 원심(原審)의 참가인은 상소심(上訴審)에서도 참가인으로서의 지위를 잃지 아니한다.', 3002);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5260, '② 참가인이 상소를 하면 검사 또는 피고인이 상소를 하지 아니하거나 상소의 포기 또는 취하를 한 경우에도 원심 재판 중 몰수에 관한 부분은 확정되지 아니한다.', 3002);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5261, '③ 제2항의 경우 피고인은 상소심 및 그 후의 심급(審級)과 관련하여 공판기일에 출석하지 아니하여도 된다. 이 경우 「형사소송법」 제33조ㆍ제282조 및 제283조는 적용하지 아니한다.', 3002);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5262, '④ 약식절차에 의한 재판에 대하여 참가인이 정식재판을 청구한 경우에는 제2항과 제3항을 준용한다.', 3002);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5263, '① 이 법에 따라 피고인에 대한 형사사건 절차에 관여하는 제3자는 변호사 중에서 대리인을 선임하여 소송행위를 대리하게 할 수 있다. 이 경우 「형사소송법」 제32조제1항 및 제35조를 준용한다.', 3003);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5264, '② 대리인은 참가인이 서면으로 동의하지 아니하면 참가의 취하, 정식재판 청구의 취하, 상소의 포기 또는 취하를 할 수 없다.', 3003);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5265, '① 제3자의 소송능력에 관하여는 「형사소송법」 제26조부터 제28조까지의 규정을 준용하고, 제3자의 소송비용 부담에 관하여는 같은 법 제186조 및 제191조를 준용한다.', 3004);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5266, '② 제13조제1항에 규정된 재산을 몰수하는 절차에 관하여는 이 법에 특별한 규정이 있는 경우를 제외하고는 「형사소송법」을 준용한다.', 3004);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5267, '① 법원은 특정공무원범죄에 관련된 피고인에 대한 형사사건에서 이 법에 따라 몰수할 수 있는 재산(이하 "몰수대상재산"이라 한다)에 해당한다고 판단할 만한 상당한 이유가 있고, 그 재산을 몰수하기 위하여 필요하다고 인정할 때에는 검사의 청구에 의하여 또는 법원의 직권으로 몰수보전명령을 하여 그 재산에 관한 처분을 금지할 수 있다.', 3006);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5268, '② 법원은 지상권ㆍ저당권 또는 그 밖의 권리가 그 위에 존재하는 재산에 대하여 몰수보전명령을 한 경우 또는 하려는 경우, 그 권리가 몰수에 의하여 소멸된다고 볼 만한 상당한 이유가 있고 그 재산을 몰수하기 위하여 필요하다고 인정할 때 또는 그 권리가 가장(假裝)된 것이라고 볼 만한 상당한 이유가 있다고 인정할 때에는 검사의 청구에 의하여 또는 법원의 직권으로 따로 부대보전명령을 하여 그 권리의 처분을 금지할 수 있다.', 3006);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5269, '③ 몰수보전명령서 또는 부대보전명령서에는 피고인의 성명, 죄명, 공소 사실의 요지, 몰수의 근거가 되는 법령의 조항, 처분을 금지하는 재산 또는 권리의 표시, 그 재산 또는 권리를 가진 사람(명의인이 다른 경우 명의인을 포함한다)의 성명, 발급연월일, 그 밖에 대법원규칙으로 정하는 사항을 적고 재판한 법관이 서명날인하여야 한다.', 3006);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5270, '④ 재판장은 긴급한 조치가 필요한 경우에는 직접 제1항 또는 제2항에 따른 처분을 하거나 합의부(合議部)의 구성원에게 그 처분을 하게 할 수 있다.', 3006);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5271, '⑤ 부동산 또는 동산에 대한 몰수보전은 「형사소송법」에 따른 압수를 방해하지 아니한다.', 3006);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5272, '① 검사는 제23조제1항 또는 제2항의 이유와 필요가 있다고 인정하는 경우에는 공소가 제기되기 전이라도 지방법원 판사에게 청구하여 같은 조 제1항 또는 제2항에 따른 처분을 받을 수 있으며, 사법경찰관은 검사에게 신청하여 검사의 청구로 해당 처분을 받을 수 있다.', 3007);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5273, '② 사법경찰관은 몰수보전명령 또는 부대보전명령이 내려진 경우에는 지체 없이 관계 서류를 검사에게 송부하여야 한다.', 3007);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5274, '③ 제1항에 따른 청구는 청구하는 검사가 소속된 지방검찰청 또는 그 지청(支廳) 소재지를 관할하는 지방법원 또는 그 지원(支院)의 판사에게 하여야 한다.', 3007);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5275, '④ 제1항에 따라 청구를 받은 판사는 몰수보전에 관하여 법원 또는 재판장과 동일한 권한을 가진다.', 3007);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5276, '⑤ 검사는 제1항에 따른 몰수보전 후 공소를 제기한 경우에는 그 요지를 몰수보전명령을 받은 사람(피고인은 제외한다)에게 알려야 한다. 다만, 그 사람의 소재가 분명하지 아니하거나 그 밖의 이유로 인하여 알릴 수 없을 때에는 통지를 갈음하여 그 요지를 관할 지방검찰청 또는 그 지청의 게시판에 7일간 게시하여 공고하여야 한다.', 3007);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5277, '① 몰수보전에 관한 재판은 검사의 지휘에 따라 집행한다.', 3008);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5278, '② 몰수보전명령의 집행은 그 명령에 따라 처분이 금지되는 재산을 가진 자에게 몰수보전명령의 등본이 송달되기 전에도 할 수 있다.', 3008);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5279, '① 부동산의 몰수보전은 그 처분을 금지하는 내용의 몰수보전명령에 따라 한다.', 3010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5280, '② 제1항의 몰수보전명령의 등본은 부동산의 소유자(명의인이 다른 경우 명의인을 포함한다)에게 송달하여야 한다.', 3010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5281, '③ 부동산에 대한 몰수보전명령의 집행은 몰수보전등기를 하는 방법으로 한다.', 3010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5282, '④ 제3항의 등기는 검사가 촉탁한다.', 3010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5283, '⑤ 부동산에 대한 몰수보전의 효력은 몰수보전등기가 된 때에 발생한다.', 3010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5284, '⑥ 부동산에 대하여 등기청구권을 보전하기 위한 처분 금지 가처분의 등기가 된 후 몰수보전등기가 된 경우에 그 가처분 채권자가 보전하려는 등기청구권에 따른 등기를 할 때에는 몰수보전등기에 의한 처분의 제한은 그 가처분등기에 의한 권리의 취득 또는 소멸에 영향을 미치지 아니한다.', 3010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5285, '⑦ 부동산의 몰수보전에 관하여는 「민사집행법」 제83조제2항, 제94조제2항 및 제95조를 준용한다. 이 경우 「민사집행법」제83조제2항 중 "채무자"는 "몰수보전재산을 가진 자"로 보고, 같은 법 제94조제2항 중 "제1항" 및 같은 법 제95조 중 "제94조"는 "「공무원범죄에 관한 몰수 특례법」 제27조제4항"으로 보며, 「민사집행법」 제95조 중 "법원"은 "검사"로 본다.', 3010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5286, '① 동산(제28조에 규정된 것 외의 것을 말한다. 이하 이 조에서 같다)의 몰수보전은 그 처분을 금지하는 내용의 몰수보전명령에 따라 한다.', 3012);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5287, '② 제1항에 따른 몰수보전명령의 등본은 동산의 소유자(명의인이 다른 경우 명의인을 포함한다. 이하 이 조에서 같다)에게 송달하여야 한다.', 3012);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5288, '③ 「형사소송법」에 따라 압수되지 아니한 동산이나 같은 법 제130조제1항에 따라 간수자(看守者)를 두거나 소유자 또는 적당한 자에게 보관하게 할 수 있는 동산에 관하여 몰수보전명령이 있는 때에는 검사는 공시서(公示書)를 첨부시키거나 그 밖의 적절한 방법으로 그 내용을 공시하는 조치를 하여야 한다.', 3012);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5289, '④ 동산의 몰수보전의 효력은 몰수보전명령의 등본이 소유자에게 송달된 때에 발생한다.', 3012);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5290, '① 채권의 몰수보전은 채권자(명의인이 다른 경우 명의인을 포함한다. 이하 이 조에서 같다)에게는 채권의 처분과 영수(領收)를 금지하고, 채무자에게는 채권자에 대한 지급을 금지하는 내용의 몰수보전명령에 따라 한다.', 3013);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5291, '② 제1항의 몰수보전명령의 등본은 채권자 및 채무자에게 송달하여야 한다.', 3013);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5292, '③ 채권의 몰수보전의 효력은 몰수보전명령의 등본이 채무자에게 송달된 때에 발생한다.', 3013);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5293, '④ 채권의 몰수보전에 관하여는 「민사집행법」 제228조, 제248조제1항 및 제4항 본문을 준용한다. 이 경우 「민사집행법」 제228조제1항 중 "압류"는 "몰수보전"으로, "채권자"는 "검사"로 보고, 같은 조 제1항 및 제2항 중 "압류명령" 및 같은 법 제248조제1항 중 "압류"는 "몰수보전명령"으로 보며, 같은 법 제248조제1항 및 제4항 본문 중 "제3채무자"는 "채무자"로 보고, 같은 조 제4항 본문 중 "법원"은 "몰수보전명령을 한 법원"으로 본다.', 3013);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5294, '① 제27조부터 제30조까지에 규정된 재산 외의 재산권(이하 이 조에서 "그 밖의 재산권"이라 한다)의 몰수보전에 관하여는 이 조에 특별히 정한 사항을 제외하고는 채권의 몰수보전의 예에 따른다.', 3014);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5295, '② 그 밖의 재산권 중 채무자 또는 이에 준하는 자가 없는 경우(제3항의 경우는 제외한다) 몰수보전의 효력은 몰수보전명령이 그 권리자에게 송달된 때에 발생한다.', 3014);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5296, '③ 그 밖의 재산권 중 권리 이전을 할 때 등기등이 필요한 재산권에 대하여는 제27조제3항부터 제6항까지의 규정과 「민사집행법」 제94조제2항 및 제95조를 준용한다. 이 경우 「민사집행법」 제94조제2항 중 "제1항" 및 같은 법 제95조 중 "제94조"는 "「공무원범죄에 관한 몰수 특례법」 제31조제3항에서 준용한 제27조제4항"으로 보고, 「민사집행법」 제95조 중 "법원"은 "검사"로 본다.', 3014);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5297, '① 법원은 몰수보전의 이유 또는 필요가 없어지거나 몰수보전의 기간이 부당하게 길어진 때에는 검사나 몰수보전재산을 가진 자(그 사람이 피고인 또는 피의자인 경우에는 그 변호인을 포함한다)의 청구 또는 법원의 직권에 의한 결정으로 몰수보전명령을 취소하여야 한다.', 3015);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5298, '② 법원은 검사의 청구에 의한 경우를 제외하고는 제1항의 결정을 할 때 검사의 의견을 들어야 한다.', 3015);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5299, '① 몰수보전명령은 몰수선고가 없는 재판(「형사소송법」 제327조제2호에 따른 경우는 제외한다)이 확정된 때에는 그 효력을 잃는다.', 3016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5300, '② 「형사소송법」 제327조제2호에 따른 공소기각(公訴棄却)의 판결이 있은 경우 공소기각의 판결이 확정된 날부터 30일 이내에 해당 사건에 대하여 공소가 제기되지 아니한 때에는 몰수보전명령은 그 효력을 잃는다.', 3016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5301, '① 몰수보전이 된 후에 그 몰수보전의 대상이 된 부동산 또는 제28조에 규정된 선박ㆍ항공기ㆍ자동차 또는 건설기계에 대하여 강제경매 개시가 결정된 경우 또는 그 몰수보전의 대상이 된 유체동산(有體動産)이 강제집행에 의하여 압류된 경우에는 강제집행에 의한 환가(換價) 절차는 몰수보전이 실효된 후가 아니면 진행할 수 없다.', 3018);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5302, '② 몰수보전된 채권에 대하여 강제집행에 의한 압류명령이 내려진 경우 그 압류채권자는 압류된 채권 중 몰수보전된 부분에 대하여 몰수보전이 실효되지 아니하면 채권을 영수할 수 없다.', 3018);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5303, '③ 몰수보전이 된 후에 강제집행에 의하여 압류된 채권이 조건부 또는 기한부(期限附)이거나 반대의무의 이행과 관련되어 있거나 그 밖의 사유로 추심(推尋)하기 곤란한 경우에는 제1항을 준용한다.', 3018);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5304, '④ 몰수보전된 그 밖의 재산권(「민사집행법」 제251조제1항에 규정된 그 밖의 재산권을 말한다)에 대한 강제집행에 관하여는 몰수보전된 채권에 대한 강제집행의 예에 따른다.', 3018);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5305, '① 금전 지급을 목적으로 하는 채권(이하 "금전채권"이라 한다)의 채무자(이하 "제3채무자"라 한다)는 해당 채권이 몰수보전된 후에 그 몰수보전의 대상이 된 채권에 대하여 강제집행에 의한 압류명령을 송달받은 때에는 그 채권의 전액을 채무 이행지(履行地)의 관할 지방법원 또는 지원에 공탁(供託)할 수 있다.', 3019);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5306, '② 제3채무자가 제1항에 따른 공탁을 하였을 때에는 그 사유를 몰수보전명령을 한 법원 및 압류명령을 한 법원에 신고하여야 한다.', 3019);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5307, '③ 제1항에 따라 공탁된 경우 집행법원은 공탁된 금액 중에서 몰수보전된 금전채권의 금액에 상당하는 부분에 관하여는 몰수보전이 실효된 때에, 그 나머지 부분에 관하여는 공탁된 때에 배당 절차를 시작하거나 변제금의 지급을 실시한다.', 3019);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5308, '④ 강제집행에 의하여 압류된 금전채권에 관하여 몰수보전이 된 경우에 제3채무자의 공탁에 관하여는 제1항과 제2항을 준용한다.', 3019);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5309, '⑤ 제1항(제4항에서 준용하는 경우를 포함한다)에 따라 공탁된 경우에 「민사집행법」 제247조를 적용할 때에는 같은 조 제1항제1호의 "제248조제4항"은 "「공무원범죄에 관한 몰수 특례법」 제36조제2항(같은 조 제4항에서 준용하는 경우를 포함한다)"으로 본다.', 3019);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5310, '① 몰수보전되기 전에 강제경매 개시의 결정 또는 강제집행에 의하여 압류된 재산에 대하여는 몰수재판을 할 수 없다. 다만, 다음 각 호의 어느 하나에 해당하면 몰수재판을 할 수 있다.', 3020);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5311, '② 몰수대상재산상에 존재하는 지상권 또는 그 밖의 권리로서 부대보전명령에 따라 처분이 금지된 것에 대하여 그 처분 금지 전에 강제경매 개시의 결정 또는 강제집행에 의하여 압류된 재산을 몰수할 때에는, 그 권리는 존속시키고 몰수한다는 취지를 선고하여야 한다. 다만, 다음 각 호의 어느 하나에 해당하면 그러하지 아니하다.', 3020);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5312, '① 법원은 강제경매 개시의 결정 또는 강제집행에 의하여 압류된 재산에 관하여 몰수보전명령을 한 경우 또는 하려는 경우 제37조제1항 단서에 규정된 사유가 있다고 판단할 만한 상당한 이유가 있다고 인정할 때에는 검사의 청구 또는 법원의 직권에 의한 결정으로 강제집행의 정지를 명할 수 있다.', 3021);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5313, '② 검사가 제1항의 결정 등본을 집행법원에 제출하였을 때에는 집행법원은 강제집행을 정지하여야 한다. 이 경우 「민사집행법」을 적용할 때에는 같은 법 제49조제2호의 서류가 제출된 것으로 본다.', 3021);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5314, '③ 법원은 몰수보전이 실효된 때, 제1항의 이유가 없어진 때 또는 강제집행정지기간이 부당하게 길어진 때에는 검사나 압류채권자의 청구에 의하여 또는 법원의 직권으로 제1항의 결정을 취소하여야 한다. 이 경우 제32조제2항을 준용한다.', 3021);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5315, '① 몰수보전재산상에 존재하는 담보권이 몰수보전된 후에 성립되거나 부대보전명령에 따라 처분이 금지된 경우 그 담보권의 실행(압류는 제외한다)은 몰수보전명령 또는 부대보전명령에 따른 처분 금지가 실효되지 아니하면 할 수 없다.', 3022);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5316, '② 담보권의 실행을 위한 경매 절차가 시작된 후 그 담보권에 관하여 부대보전명령이 내려진 경우 검사가 그 명령의 등본을 제출하였을 때에는 집행법원은 그 절차를 정지하여야 한다. 이 경우 「민사집행법」을 적용할 때에는 같은 법 제266조제1항제5호(같은 법 제269조 및 제272조에서 준용하는 경우를 포함한다)의 문서가 제출된 것으로 본다.', 3022);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5317, '① 다음 각 호의 어느 하나에 해당하는 경우 그 절차의 제한에 관하여는 제35조를 준용한다. <개정 2010.3.31, 2016.12.27>', 3023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5318, '② 다음 각 호의 어느 하나에 해당하는 경우 제3채무자의 공탁에 관하여는 제36조를 준용한다.', 3023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5319, '③ 다음 각 호의 어느 하나에 해당하는 경우 제3채무자의 공탁에 관하여는 제36조제1항 및 제2항을 준용한다.', 3023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5320, '④ 다음 각 호의 어느 하나에 해당하는 경우에 이러한 재산의 몰수 제한에 관하여는 제37조를 준용한다.', 3023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5321, '⑤ 다음 각 호의 어느 하나에 해당하는 경우에 이러한 재산의 몰수 제한에 관하여는 제37조제1항 본문을 준용한다.', 3023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5322, '⑥ 다음 각 호의 어느 하나에 해당하는 경우에 이러한 재산의 몰수 제한에 관하여는 제37조제2항 본문을 준용한다.', 3023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5323, '⑦ 가압류된 재산에 대하여 몰수보전명령을 한 경우 또는 하려는 경우에 강제집행정지에 관하여는 제38조를 준용한다.', 3023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5324, '① 부대보전명령은 그 명령에 관계된 몰수보전의 효력이 존속하는 동안 그 효력이 있다.', 3024);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5325, '② 부대보전명령에 따른 처분 금지에 관하여는 이 법에 특별한 규정이 있는 경우를 제외하고는 몰수보전에 관한 규정을 준용한다.', 3024);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5326, '① 법원은 특정공무원범죄에 관련된 피고인에 대한 형사사건에 관하여 제6조에 따라 추징을 하여야 할 경우에 해당한다고 판단할 만한 상당한 이유가 있는 경우에 추징재판을 집행할 수 없게 될 염려가 있거나 집행이 현저히 곤란할 염려가 있다고 인정할 때에는 검사의 청구에 의하여 또는 법원의 직권으로 추징보전명령을 하여 피고인에 대하여 재산의 처분을 금지할 수 있다.', 3025);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5327, '② 추징보전명령을 할 때에는 추징재판의 집행을 위하여 보전하는 것이 타당하다고 인정되는 금액(이하 "추징보전액"이라 한다)을 정한 후 특정 재산에 대하여 하여야 한다. 다만, 유체동산에 관하여는 그 목적물을 특별히 정하지 아니할 수 있다.', 3025);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5328, '③ 추징보전명령을 할 때에는 추징보전명령의 집행정지나 집행처분의 취소를 위하여 피고인이 공탁하여야 할 금액(이하 "추징보전해방금"이라 한다)을 정하여야 한다.', 3025);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5329, '④ 추징보전명령서에는 피고인의 성명, 죄명, 공소 사실의 요지, 추징의 근거가 되는 법령의 조항, 추징보전액, 처분을 금지하는 재산의 표시, 추징보전해방금, 발급연월일, 그 밖에 대법원규칙으로 정하는 사항을 적고 재판한 법관이 서명날인하여야 한다.', 3025);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5330, '⑤ 추징보전에 관하여는 제23조제4항을 준용한다.', 3025);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5331, '① 검사는 제42조제1항에 따른 추징보전의 이유와 필요가 있다고 인정하는 경우에는 공소가 제기되기 전이라도 지방법원 판사에게 청구하여 같은 항에 규정된 처분을 받을 수 있다.', 3026);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5332, '② 제1항에 따른 추징보전에 관하여는 제24조제3항 및 제4항을 준용한다.', 3026);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5333, '① 추징보전명령은 검사의 명령에 따라 집행한다. 이 경우 검사의 명령은 「민사집행법」에 따른 가압류명령과 동일한 효력을 가진다.', 3027);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5334, '② 추징보전명령의 집행은 추징보전명령의 등본이 피고인 또는 피의자에게 송달되기 전에도 할 수 있다.', 3027);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5335, '③ 추징보전명령의 집행에 관하여는 이 법에 특별한 규정이 있는 경우를 제외하고는 「민사집행법」이나 그 밖에 가압류 집행의 절차에 관한 법령의 규정을 준용한다. 이 경우 법령에 따라 가압류명령을 한 법원이 가압류 집행법원으로서 관할하도록 되어 있는 가압류의 집행에 관하여는 제1항에 따른 명령을 한 검사가 소속하는 검찰청에 대응하는 법원이 관할한다.', 3027);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5336, '① 추징보전해방금이 공탁된 후에 추징재판이 확정된 때 또는 가납재판(假納裁判)이 선고된 때에는 공탁된 금액의 범위에서 추징 또는 가납재판의 집행이 있은 것으로 본다.', 3029);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5337, '② 추징선고된 경우 공탁된 추징보전해방금이 추징금액을 초과할 때에는 법원은 그 초과액을 피고인에게 돌려주어야 한다.', 3029);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5338, '① 추징보전명령은 추징선고가 없는 재판(「형사소송법」 제327조제2호에 따른 경우는 제외한다)이 확정된 때에는 그 효력을 잃는다.', 3031);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5339, '② 「형사소송법」 제327조제2호에 따른 공소기각의 판결이 있은 경우 추징보전명령의 효력에 관하여는 제33조제2항을 준용한다.', 3031);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5340, '① 몰수보전 또는 추징보전에 관한 법원의 결정에 대하여는 항고할 수 있다.', 3035);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5341, '② 몰수보전 또는 추징보전에 관한 법관의 재판에 불복하는 경우에는 그 법관이 소속한 법원에 그 재판의 취소 또는 변경을 청구할 수 있다.', 3035);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5342, '③ 제2항에 따른 불복신청의 절차에 관하여는 「형사소송법」 제416조제1항에 따른 재판의 취소 또는 변경의 청구에 관련된 절차 규정을 준용한다.', 3035);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5343, '①몰수보전 청구서에는 다음 각호의 사항을 기재하고 청구하는 검사가 서명날인을 하여야 한다. <개정 2005.12.29>', 3038);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5344, '②몰수보전 청구서에는 공소사실 또는 피의사실의 요지를 따로 기재한 서면 1통을 첨부하여야 한다. <개정 2005.12.29>', 3038);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5345, '③몰수보전의 청구를 하는 때에는 법 제23조제1항이 규정하는 사유를 인정할 수 있는 자료를 제출하여야 한다.', 3038);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5346, '①부대보전 청구서에는 제3조제1항 각호의 사항을 기재하는 외에, 몰수보전의 청구와 함께 하는 경우에는 다음 제2호 및 제3호의 사항을, 몰수보전의 청구와 별도로 하는 경우에는 다음 각호의 사항을 각 기재하고 청구하는 검사가 서명날인을 하여야 한다. <개정 2005.12.29>', 3040);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5347, '②부대보전의 청구를 하는 때에는 법 제23조제2항이 규정하는 사유를 인정할 수 있는 자료를 제출하여야 한다.', 3040);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5348, '③제3조제2항은 부대보전의 청구에 이를 준용한다.', 3040);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5349, '①몰수보전명령의 취소청구는 다음 각호의 사항을 기재한 서면으로 하여야 한다.', 3047);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5350, '②몰수보전명령의 취소청구를 하는 때에는 법 제32조제1항이 규정하는 사유를 인정할 수 있는 자료를 제출하여야 한다.', 3047);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5351, '③검사 또는 수사처검사 아닌 자가 제1항의 취소청구를 할 때에는 그 청구서의 부본을 첨부하여야 한다. <개정 2021.1.29>', 3047);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5352, '④법원이 몰수보전명령의 취소에 관하여 검사 또는 수사처검사의 의견을 물을 때에는 제3항의 청구서 부본을 첨부하여야 한다. <개정 2021.1.29>', 3047);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5353, '①몰수보전된 재산에 대하여 강제경매개시결정 또는 강제집행에 의하여 압류가 된 때에는, 집행법원의 법원서기관, 법원사무관, 법원주사 또는 법원주사보(이하 "법원사무관등"이라고 한다. 동산의 경우에는 집행관)는 검사 또는 수사처검사에게 그 사실을 통지하여야 한다. <개정 2002.6.28, 2021.1.29>', 3049);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5354, '②제1항의 경우 강제집행신청이 취하된 때 또는 강제집행절차를 취소하는 결정이 확정된 때에는 집행법원의 법원사무관등(동산의 경우에는 집행관)은 검사 또는 수사처검사에게 그 사실을 통지하여야 한다. <개정 2002.6.28, 2021.1.29>', 3049);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5355, '③제1항의 경우 몰수의 재판이 확정되거나 몰수보전이 효력을 상실한 때에는 검사 또는 수사처검사는 집행법원(동산의 경우에는 집행관)에 그 사실을 통지하여야 한다. <개정 2002.6.28, 2021.1.29>', 3049);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5356, '①법 제36조제2항의 규정에 의한 신고는 다음 각호의 사항을 기재한 서면으로 하여야 한다. <개정 2005.12.29>', 3050);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5357, '②제1항의 경우 몰수보전명령을 발한 법원에 대한 공탁사유신고서에는 공탁서를 첨부하여야 한다. <개정 2005.12.29>', 3050);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5358, '③제1항의 신고가 있은 경우 몰수보전명령을 발한 법원의 법원사무관등은 검사 또는 수사처검사에게 그 사실을 통지하여야 한다. <개정 2021.1.29>', 3050);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5359, '①법 제40조제2항에 의하여 준용되는 법 제36조제2항의 규정에 의한 신고는 몰수보전명령을 발한 법원, 체납처분을 한 「국세기본법」 제2조제17호 및 「지방세법」 제1조제1항제3호의 세무공무원과 그 밖에 체납처분을 집행하는 권한이 있는 자 또는 한국자산관리공사가 세무서장을 대행하여 공매, 배분 및 권리이전등기의 촉탁을 대행하는 경우에는 한국자산관리공사 및 그 직원(이하 "세무공무원등"이라고 한다)에게 하여야 한다.', 3051);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5360, '②제1항의 신고는 다음 각 호의 사항을 기재한 서면으로 하여야 한다.', 3051);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5361, '③제1항의 경우 제14조제2항ㆍ제3항의 규정을 준용한다.', 3051);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5362, '①제14조제1항은 법 제36조제4항에 의하여 준용되는 동조제2항의 규정에 의한 공탁사유신고에 준용한다.', 3052);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5363, '②제1항의 경우 압류명령을 발한 법원에 대한 공탁사유신고서에는 공탁서를 첨부하여야 한다. <개정 2005.12.29>', 3052);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5364, '③제1항의 신고가 있은 경우 압류명령을 발한 법원의 법원사무관등은 검사 또는 수사처검사에게 그 사실을 통지하여야 한다. <개정 2021.1.29>', 3052);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5365, '①제14조의2제1항ㆍ제2항은 법 제40조제2항 및 제36조제4항에 의하여 준용되는 법 제36조제2항의 규정에 의한 공탁사유신고에 준용한다.', 3053);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5366, '②제1항의 경우 세무공무원등에 대한 공탁사유신고서에는 공탁서를 첨부하여야 한다.', 3053);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5367, '①강제경매개시결정 또는 강제집행에 의하여 압류가 된 재산에 대하여 몰수보전명령이 발하여진 때에는 검사 또는 수사처검사는 집행법원(동산의 경우에는 집행관)에 그 사실을 통지하여야 한다. <개정 2002.6.28, 2021.1.29>', 3054);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5368, '②제1항의 경우 몰수의 재판이 확정된 때 또는 몰수보전이 효력을 상실한 때에는 검사 또는 수사처검사는 집행법원(동산의 경우에는 집행관)에 그 사실을 통지하여야 한다. <개정 2002.6.28, 2021.1.29>', 3054);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5369, '③제1항의 경우 강제집행신청의 취하에 의하여 압류의 효력이 소멸하거나 강제집행절차를 취소하는 결정이 확정된 때 또는 강제집행절차에 의하여 재산이 매각된 때에는 집행법원의 법원사무관등(동산의 경우 집행관)은 검사 또는 수사처검사에게 그 사실을 통지하여야 한다. 「민사집행법」 제223조가 규정하는 채권(같은 법 제251조제1항에 의하여 같은 법 제2편제2장제4절제3관의 규정이 준용되는 재산권을 포함한다)에 대하여 같은 법 제236조제1항의 신고가 있는 때, 같은 법 제256조의 규정에 의하여 배당이 실시된 때, 같은 법 제229조제3항의 전부명령 또는 같은 법 제241조의 양도명령이 확정된 때에도 그 사실을 통지하여야 한다. <개정 2002.6.28, 2005.12.29, 2021.1.29>', 3054);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5370, '①법 제38조제1항의 강제집행의 정지의 청구는 다음 각호의 사항을 기재한 서면으로 하여야 한다.', 3055);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5371, '②제1항의 청구를 하는 경우에는 제1항제2호의 이유가 있다고 인정할 수 있는 자료를 제출하여야 한다.', 3055);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5372, '③제11조의 규정은 법 제38조제3항의 강제집행정지결정의 취소청구에 관하여 준용한다. 이 경우 제11조제1항의 "몰수보전사건의 표시"는 "강제집행정지사건의 표시"로, 동조제1항 및 제2항의 각 "법 제32조제1항"은 각 "법 제38조제3항"으로 본다.', 3055);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5373, '①제13조의 규정은 몰수보전이 된 재산에 대하여 가압류의 집행이 있는 경우에 준용한다.', 3057);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5374, '②제14조의 규정은 몰수보전이 된 금전채권에 대하여 가압류의 집행이 있는 경우 당해금전채권의 채무자의 공탁에 관하여, 제15조의 규정은 가압류된 금전채권에 대하여 몰수보전이 된 경우 당해금전채권의 채무자의 공탁에 관하여 각 준용한다.', 3057);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5375, '③제16조의 규정은 가압류된 재산에 대하여 몰수보전명령이 발하여진 경우에 준용한다.', 3057);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5376, '④제17조의 규정은 가압류된 재산에 대하여 몰수보전명령을 발한 경우 또는 발하려고 하는 경우에 있어서 강제집행의 정지의 청구 및 그 정지결정의 취소청구에 관하여 준용한다.', 3057);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5377, '①추징보전 청구서에는 다음 각호의 사항을 기재하고 검사 또는 수사처검사가 서명날인하여야 한다. <개정 2005.12.29, 2021.1.29>', 3060);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5378, '②추징보전 청구서에는 공소사실 또는 피의사실의 요지를 따로 기재한 서면 1통을 첨부하여야 한다. <개정 2005.12.29>', 3060);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5379, '③추징보전의 청구를 하는 때에는 법 제42조제1항이 규정하는 사유를 인정할 수 있는 자료를 제출하여야 한다.', 3060);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5380, '① 「질서위반행위규제법」(이하 "법"이라 한다) 제2조제1호가목에서 "대통령령으로 정하는 사법(私法)상ㆍ소송법상 의무를 위반하여 과태료를 부과하는 행위"란 「민법」, 「상법」 등 사인(私人) 간의 법률관계를 규율하는 법 또는 「민사소송법」, 「가사소송법」, 「민사집행법」, 「형사소송법」, 「민사조정법」 등 분쟁 해결에 관한 절차를 규율하는 법률상의 의무를 위반하여 과태료를 부과하는 행위를 말한다.', 3066);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5381, '② 법 제2조제1호나목에서 "대통령령으로 정하는 법률에 따른 징계사유에 해당하여 과태료를 부과하는 행위"란 「공증인법」ㆍ「법무사법」ㆍ「변리사법」ㆍ「변호사법」 등 기관ㆍ단체 등이 질서 유지를 목적으로 구성원의 의무 위반에 대하여 제재를 할 수 있도록 규정하는 법률에 따른 징계사유에 해당하여 과태료를 부과하는 행위를 말한다.', 3066);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5382, '① 행정청은 법 제16조에 따른 사전통지 및 의견 제출 결과 당사자가 다음 각 호의 어느 하나에 해당하는 경우에는 해당 과태료 금액의 100분의 50의 범위에서 과태료를 감경할 수 있다. 다만, 과태료를 체납하고 있는 당사자에 대해서는 그러하지 아니하다. <개정 2013.5.10, 2018.12.31>', 3067);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5383, '② 법령상 감경할 사유가 여러 개 있는 경우라도 제1항에 따라 감경을 하는 경우에는 법 제18조에 따른 감경을 제외하고는 거듭 감경할 수 없다.', 3067);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5384, '① 법 제16조제1항에 따라 행정청이 과태료 부과에 관하여 미리 통지하는 경우에는 다음 각 호의 사항을 모두 적은 서면(당사자가 동의하는 경우에는 전자문서를 포함한다)으로 하여야 한다. <개정 2009.12.15, 2013.5.10, 2021.1.26>', 3068);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5385, '② 당사자는 제1항제4호의 의견제출 기한 이내에 서면(전자문서를 포함한다)으로 의견을 제출하거나 말로 의견을 진술할 수 있고, 그 주장을 증명하기 위하여 증거자료 등을 제출할 수 있다. <개정 2013.5.10>', 3068);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5386, '③ 행정청은 당사자가 제2항에 따라 말로 의견을 진술한 경우에는 진술자와 그 의견의 요지를 기록해 두어야 한다. <개정 2013.5.10>', 3068);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5387, null, 3069);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5388, '① 법 제17조의2제1항에서 "대통령령으로 정하는 과태료 납부대행기관"이란 정보통신망을 이용하여 신용카드, 직불카드 등(이하 "신용카드등"이라 한다)에 의한 결제를 수행하는 기관으로서 다음 각 호의 어느 하나에 해당하는 기관을 말한다.', 3070);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5389, '② 납부대행기관은 법 제17조의2제3항에 따라 해당 과태료(법 제24조에 따른 가산금, 중가산금 및 체납처분비를 포함한다. 이하 이 조, 제7조의2부터 제7조의4까지 및 제14조의2에서 같다)금액의 1천분의 15를 초과하지 아니하는 범위에서 행정청이 승인한 납부대행 수수료를 받을 수 있다. 이 경우 행정청은 납부대행기관의 운영경비 등을 종합적으로 고려하여 납부대행 수수료를 승인하여야 한다.', 3070);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5390, '③ 행정청은 신용카드등에 의한 과태료의 납부에 필요한 사항을 정할 수 있다.', 3070);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5391, '① 행정청은 법 제22조제1항 각 호의 조치를 하려면 당사자 또는 참고인에게 다음 각 호의 내용을 모두 적은 서면으로 알려야 한다. <개정 2013.5.10>', 3072);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5392, '② 행정청은 제1항에도 불구하고 신속한 조사를 위하여 필요하면 전화, 팩스, 그 밖의 적절한 방법으로 법 제22조제1항 각 호의 조치를 할 수 있다.', 3072);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5393, '③ 행정청이 법 제22조제3항에 따라 검사를 위하여 사전통지를 하는 경우에는 다음 각 호의 사항을 적은 서면으로 한다. <개정 2013.5.10>', 3072);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5394, '① 행정청은 법 제24조의3제1항에 따라 과태료의 분할납부나 납부기일의 연기(이하 "징수유예등"이라 한다)를 결정하는 경우 그 기간을 그 징수유예등을 결정한 날의 다음 날부터 9개월 이내로 하여야 한다. 다만, 그 기간이 만료될 때까지 법 제24조의3제1항에 따른 징수유예등의 사유가 해소되지 아니하는 경우에는 1회에 한정하여 3개월의 범위에서 그 기간을 연장할 수 있다.', 3074);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5395, '② 법 제24조의3제1항제9호에서 "대통령령으로 정하는 부득이한 사유가 있는 경우"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다.', 3074);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5396, '③ 행정청은 제1항에 따라 징수유예등을 결정하는 경우 법 제24조의3제1항에 따른 징수유예등의 사유를 고려하여 납부기한의 연기, 분할납부의 횟수 및 금액을 정한다.', 3074);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5397, '① 법 제24조의3제2항에 따라 징수유예등을 신청하거나 제7조의2제1항 단서에 따라 기간의 연장을 받으려는 당사자는 별지 제1호서식의 분할납부ㆍ납부기일의 연기ㆍ징수유예등 기간연장 신청서(전자문서를 포함한다)에 그 사유를 증명하는 서류를 첨부하여 행정청에 신청하여야 한다.', 3075);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5398, '② 제1항에 따라 징수유예등 또는 징수유예등 기간 연장의 신청을 받은 행정청은 특별한 사정이 없는 한 그 신청을 받은 날부터 20일 이내에 결정하여 당사자에게 통지하여야 한다.', 3075);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5399, '③ 행정청은 징수유예등의 사유가 있을 때에는 직권으로 징수유예등을 결정할 수 있다.', 3075);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5400, '④ 징수유예등의 결정의 효력은 다음 각 호의 구분에 따른 날에 발생한다.', 3075);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5401, '① 법 제24조의3제5항제4호에서 "대통령령으로 정하는 사유"란 다음 각 호의 어느 하나에 해당하는 사유를 말한다.', 3076);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5402, '② 법 제24조의3제5항에 따른 징수유예등 취소의 통지는 별지 제2호서식의 분할납부ㆍ납부기일의 연기 취소 통지서(당사자가 동의하는 경우에는 전자문서를 포함한다)로 한다.', 3076);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5403, '③ 행정청은 법 제24조의3제5항에 따라 징수유예등을 취소한 경우에는 그 과태료 징수금에 대하여 다시 징수유예등을 할 수 없다. 다만 법 제24조의3제5항제3호의 사유로 징수유예등을 취소한 경우는 그러하지 아니하다.', 3076);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5404, '① 법 제24조의4제1항제2호에서 "대통령령으로 정하는 경우"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다.', 3077);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5405, '② 행정청은 제1항에 따라 결손처분을 하려는 경우에는 체납자와 관계가 있다고 인정되는 행정기관에 체납자에 대한 실종선고 사실 또는 재산의 유무를 확인(「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통해 조회하여 확인하는 것을 포함한다)해야 한다.', 3077);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5406, '③ 행정청은 법 제24조의4제2항에 따라 결손처분을 취소했을 때에는 지체 없이 체납자에게 그 취소사실을 통지해야 한다.', 3077);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5407, '① 과태료의 징수 절차는 법 또는 이 영에 반하지 아니하는 범위에서 국고금관리법령 또는 지방재정ㆍ회계법령을 준용한다. <개정 2016.11.29>', 3078);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5408, '② 제1항에도 불구하고 과태료의 징수 절차를 국고금관리법령 또는 지방재정ㆍ회계법령과 달리 정할 필요가 있는 경우에는 따로 총리령 또는 부령으로 정한다. <개정 2016.11.29>', 3078);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5409, '① 법 제52조제1항제1호의 "횟수"와 "금액"은 각각 "3회"와 "500만원"으로 한다.', 3081);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5410, '② 제1항의 과태료 체납 횟수는 과태료 부과고지서 1통을 1회로 보아 계산한다.', 3081);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5411, '③ 법 제52조제1항제2호에서 "대통령령으로 정하는 특별한 사유"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다.', 3081);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5412, '④ 행정청이 법 제52조제2항에 따라 관허사업의 제한을 요구할 때에는 다음 각 호의 사항을 적은 문서(전자문서를 포함한다)로 하여야 한다. <개정 2013.5.10>', 3081);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5413, '⑤ 제4항의 요구를 받은 주무관청은 그 조치 결과를 지체 없이 해당 행정청에 알려야 한다.', 3081);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5414, '① 법 제54조제1항제1호의 "횟수"와 "금액"은 각각 "3회"와 "1천만원"으로 한다.', 3083);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5415, '② 제1항의 과태료 체납 횟수 계산에 관하여는 제11조제2항을 준용한다.', 3083);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5416, '① 법 제55조제1항에서 "대통령령으로 정하는 질서위반행위로 부과받은 과태료"란 다음 각 호의 어느 하나에 해당하는 과태료를 말한다. <개정 2013.5.10, 2021.1.26>', 3084);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5417, '② 법 제55조 및 이 조 제1항에 따라 행정청이 자동차 등록번호판을 영치할 수 있는 경우는 다음 각 호의 요건을 모두 충족하는 경우로 한정한다.', 3084);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5418, '③ 행정청은 제2항에 따라 자동차 등록번호판을 영치할 때에는 미리 당사자에게 10일 이내에 자동차 관련 과태료를 납부하지 아니하면 즉시 등록번호판을 영치할 것이라는 뜻을 통지하여야 한다.', 3084);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5419, '④ 제3항에 따른 통지는 다음 각 호의 사항을 모두 적은 서면(당사자가 동의하는 경우에는 전자문서를 포함한다)으로 하여야 한다. <개정 2013.5.10>', 3084);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5420, '⑤ 행정청은 자동차 등록번호판을 영치하였을 때에는 당사자에게 다음 각 호의 사항을 모두 적은 영치증을 교부하여야 한다. 다만, 당사자가 영치증을 수령할 수 없거나 거부하는 경우에는 그러하지 아니하다. <개정 2013.5.10>', 3084);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5421, '⑥ 법 제55조제2항에 따라 자동차 등록업무를 담당하는 주무관청이 아닌 행정청이 등록번호판을 영치한 사실을 주무관청에 통지할 때에는 제4항 각 호의 사항을 모두 적은 서면(전자문서를 포함한다)으로 하여야 한다. <개정 2013.5.10>', 3084);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5422, '⑦ 행정청이 법 제55조제3항에 따라 등록번호판을 내줄 때에는 영치 원인이 된 자동차 관련 과태료(법 제24조에 따른 가산금 및 중가산금을 포함한다)의 납부증명서를 제출받아 그 납부 여부를 확인하여야 한다. 다만, 「전자정부법」 제36조제1항에 따른 행정정보 공동이용을 통하여 납부사실을 확인할 수 있는 경우에는 그러하지 아니하다.', 3084);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5423, '⑧ 자동차 등록업무를 담당하는 주무관청이 아닌 행정청이 법 제55조제3항에 따라 자동차 등록번호판을 내주고 영치를 해제하였을 때에는 지체 없이 주무관청에 그 사실을 통지하여야 한다. <신설 2013.5.10>', 3084);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5424, '① 행정청은 법 제55조제4항에 따라 자동차 등록번호판 영치를 일시 해제할 경우 그 기간을  9개월 이내로 하여야 한다. 다만, 그 기간이 만료될 때까지 법 제55조제4항 본문에 따른 일시 해제의 사유가 해소되지 아니하는 경우에는 1회에 한정하여 3개월의 범위에서 그 기간을 연장할 수 있다.', 3085);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5425, '② 법 제55조제4항에 따라 자동차 등록번호판 영치의 일시 해제를 신청하거나 제1항 단서에 따라 자동차 등록번호판 영치의 일시 해제 기간을 연장받으려는 당사자는 별지 제6호서식의 자동차 등록번호판 영치의 일시 해제ㆍ자동차 등록번호판 영치의 일시 해제 기간연장 신청서(전자문서를 포함한다)에 다음 각 호의 서류를 첨부하여 행정청에 제출하여야 한다.', 3085);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5426, '③ 제2항에 따라 자동차 등록번호판 영치의 일시해제 또는 자동차 등록번호판 영치의 일시 해제 기간연장의 신청을 받은 행정청은 특별한 사정이 없는 한 그 신청을 받은 날부터 20일 이내에 결정하여 당사자에게 통지하여야 한다.', 3085);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5427, '④ 행정청은 제3항에 따라 자동차 등록번호판 영치의 일시 해제를 결정하는 경우 필요한 때에는 체납된 자동차 관련 과태료를 분할납부할 것을 조건으로 붙일 수 있다. 이 경우 분할납부의 기간은 제1항에 따른 자동차 등록번호판 영치의 일시해제 기간으로 하고, 분할납부의 횟수 및 금액은 당사자의 자동차 사용목적과 생계유지의 관련성 등을 고려하여 행정청이 정한다.', 3085);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5428, '⑤ 행정청은 다음 각 호의 어느 하나에 해당하는 경우에는 자동차 등록번호판 영치의 일시 해제를 취소하고, 자동차 등록번호판을 다시 영치할 수 있다.', 3085);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5429, '⑥ 자동차 등록업무를 담당하는 주무관청이 아닌 행정청이 법 제55조제4항에 따라 자동차 등록번호판의 영치를 일시 해제하거나 제5항에 따라 등록번호판을 다시 영치하는 경우에는 지체없이 주무관청에 그 사실을 통지하여야 한다.', 3085);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5430, null, 3088);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5431, null, 3094);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5432, '① 인도범죄가 정치적 성격을 지닌 범죄이거나 그와 관련된 범죄인 경우에는 범죄인을 인도하여서는 아니 된다. 다만, 인도범죄가 다음 각 호의 어느 하나에 해당하는 경우에는 그러하지 아니하다.', 3095);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5433, '② 인도청구가 범죄인이 범한 정치적 성격을 지닌 다른 범죄에 대하여 재판을 하거나 그러한 범죄에 대하여 이미 확정된 형을 집행할 목적으로 행하여진 것이라고 인정되는 경우에는 범죄인을 인도하여서는 아니 된다.', 3095);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5434, null, 3096);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5435, null, 3097);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5436, '① 법무부장관은 외교부장관으로부터 제11조에 따른 인도청구서 등을 받았을 때에는 이를 서울고등검찰청 검사장(檢事長)에게 송부하고 그 소속 검사로 하여금 서울고등법원(이하 "법원"이라 한다)에 범죄인의 인도허가 여부에 관한 심사(이하 "인도심사"라 한다)를 청구하도록 명하여야 한다. 다만, 인도조약 또는 이 법에 따라 범죄인을 인도할 수 없거나 인도하지 아니하는 것이 타당하다고 인정되는 경우에는 그러하지 아니하다. <개정 2013.3.23>', 3100);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5437, '② 법무부장관은 제1항 단서에 따라 인도심사청구명령을 하지 아니하는 경우에는 그 사실을 외교부장관에게 통지하여야 한다. <개정 2013.3.23>', 3100);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5438, '① 검사는 제12조제1항에 따른 법무부장관의 인도심사청구명령이 있을 때에는 지체 없이 법원에 인도심사를 청구하여야 한다. 다만, 범죄인의 소재(所在)를 알 수 없는 경우에는 그러하지 아니하다.', 3101);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5439, '② 범죄인이 제20조에 따른 인도구속영장에 의하여 구속되었을 때에는 구속된 날부터 3일 이내에 인도심사를 청구하여야 한다.', 3101);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5440, '③ 인도심사의 청구는 관계 자료를 첨부하여 서면으로 하여야 한다.', 3101);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5441, '④ 검사는 인도심사를 청구하였을 때에는 그 청구서의 부본(副本)을 범죄인에게 송부하여야 한다.', 3101);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5442, '① 법원은 제13조에 따른 인도심사의 청구를 받았을 때에는 지체 없이 인도심사를 시작하여야 한다.', 3102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5443, '② 법원은 범죄인이 인도구속영장에 의하여 구속 중인 경우에는 구속된 날부터 2개월 이내에 인도심사에 관한 결정(決定)을 하여야 한다.', 3102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5444, '③ 범죄인은 인도심사에 관하여 변호인의 도움을 받을 수 있다.', 3102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5445, '④ 제3항의 경우에는 「형사소송법」 제33조를 준용한다.', 3102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5446, '⑤ 법원은 인도심사에 관한 결정을 하기 전에 범죄인과 그의 변호인에게 의견을 진술할 기회를 주어야 한다. 다만, 인도심사청구 각하결정(却下決定) 또는 인도거절 결정을 하는 경우에는 그러하지 아니하다.', 3102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5447, '⑥ 법원은 인도심사를 하면서 필요하다고 인정할 때에는 증인을 신문(訊問)할 수 있고, 감정(鑑定)ㆍ통역 또는 번역을 명할 수 있다.', 3102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5448, '⑦ 제6항의 경우에는 심사청구의 성질에 반하지 아니하는 범위에서 「형사소송법」 제1편제12장부터 제14장까지 및 제16장을 준용한다.', 3102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5449, '① 법원은 인도심사의 청구에 대하여 다음 각 호의 구분에 따라 결정을 하여야 한다.', 3103);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5450, '② 제1항에 따른 결정에는 그 이유를 구체적으로 밝혀야 한다.', 3103);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5451, '③ 제1항에 따른 결정은 그 주문(主文)을 검사에게 통지함으로써 효력이 발생한다.', 3103);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5452, '④ 법원은 제1항에 따른 결정을 하였을 때에는 지체 없이 검사와 범죄인에게 결정서의 등본을 송달하고, 검사에게 관계 서류를 반환하여야 한다.', 3103);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5453, '① 범죄인이 청구국으로 인도되는 것에 동의하는 경우 법원은 신속하게 제15조에 따른 결정을 하여야 한다. 이 경우 제9조에 해당한다는 이유로 인도거절 결정을 할 수 없다.', 3104);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5454, '② 제1항에 따른 동의는 서면으로 법원에 제출되어야 하며, 법원은 범죄인의 진의(眞意) 여부를 직접 확인하여야 한다.', 3104);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5455, '③ 제1항에 따른 결정이 있는 경우 법무부장관은 제34조제1항에 따른 명령 여부를 신속하게 결정하여야 한다.', 3104);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5456, '① 법무부장관은 둘 이상의 국가로부터 동일 또는 상이한 범죄에 관하여 동일한 범죄인에 대한 인도청구를 받은 경우에는 범죄인을 인도할 국가를 결정하여야 하며, 필요한 경우 외교부장관과 협의할 수 있다. <개정 2013.3.23>', 3105);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5457, '② 제1항에 따른 결정을 할 때에는 인도범죄의 발생일시, 발생장소, 중요성, 인도청구 날짜, 범죄인의 국적 및 거주지 등을 고려하여야 한다.', 3105);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5458, '① 법원은 인도범죄로 인하여 생겼거나 인도범죄로 인하여 취득한 물건 또는 인도범죄에 관한 증거로 사용될 수 있는 물건 중 대한민국 영역에서 발견된 것은 검사의 청구에 의하여 청구국에 양도할 것을 허가할 수 있다. 범죄인의 사망 또는 도망으로 인하여 범죄인 인도가 불가능한 경우에도 또한 같다.', 3106);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5459, '② 제1항에 따라 청구국에 양도할 물건에 대한 압수ㆍ수색은 검사의 청구로 서울고등법원 판사(이하 "판사"라 한다)가 발부하는 압수ㆍ수색영장에 의하여 한다.', 3106);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5460, '③ 제2항의 경우에는 그 성질에 반하지 아니하는 범위에서 「형사소송법」 제1편제10장을 준용한다.', 3106);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5461, '① 외교부장관은 제11조에 따른 서류를 송부한 후에 청구국으로부터 범죄인의 인도청구를 철회한다는 통지를 받았을 때에는 그 사실을 법무부장관에게 통지하여야 한다. <개정 2013.3.23>', 3107);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5462, '② 법무부장관은 제12조제1항 본문에 따른 인도심사청구명령을 한 후에 외교부장관으로부터 제1항에 따른 통지를 받거나 제12조제1항 단서에 해당하게 되었을 때에는 인도심사청구명령을 취소하여야 한다. <개정 2013.3.23>', 3107);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5463, '③ 검사는 제13조제1항에 따른 인도심사청구를 한 후에 인도심사청구명령이 취소되었을 때에는 지체 없이 인도심사청구를 취소하고 범죄인에게 그 내용을 통지하여야 한다.', 3107);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5464, '④ 제3항에 따른 인도심사청구의 취소는 서면으로 하여야 한다.', 3107);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5465, '① 검사는 제12조제1항에 따른 법무부장관의 인도심사청구명령이 있을 때에는 인도구속영장에 의하여 범죄인을 구속하여야 한다. 다만, 범죄인이 주거가 일정하고 도망할 염려가 없다고 인정되는 경우에는 그러하지 아니하다.', 3108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5466, '② 인도구속영장은 검사의 청구에 의하여 판사가 발부한다.', 3108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5467, '③ 인도구속영장에는 다음 각 호의 사항을 적고 판사가 서명날인하여야 한다.', 3108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5468, '① 인도구속영장은 검사의 지휘에 따라 사법경찰관리가 집행한다.', 3109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5469, '② 검사는 범죄인이 군복무 중인 경우에는 군검사에게 인도구속영장의 집행을 촉탁(囑託)할 수 있다. 이 경우 인도구속영장은 군검사의 지휘에 따라 군사법경찰관리가 집행한다. <개정 2016.1.6>', 3109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5470, '③ 인도구속영장을 집행할 때에는 반드시 범죄인에게 이를 제시하여야 한다.', 3109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5471, '④ 사법경찰관리 등이 범죄인을 구속할 때에는 구속의 이유와 변호인을 선임(選任)할 수 있음을 알려주고, 신속히 범죄인 소재지를 관할하는 지방검찰청 또는 그 지청(支廳)의 소속 검사에게 범죄인을 인치하여야 한다.', 3109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5472, '⑤ 인도구속영장에 의한 구속에 관하여는 「형사소송법」 제83조, 제85조제3항ㆍ제4항, 제86조, 제87조, 제89조, 제90조, 제137조 및 제138조를 준용한다.', 3109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5473, '① 인도구속영장에 의하여 구속된 범죄인 또는 그 변호인, 법정대리인, 배우자, 직계친족, 형제자매, 가족이나 동거인 또는 고용주는 법원에 구속의 적부심사(適否審査)를 청구할 수 있다.', 3111);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5474, '② 인도구속의 적부심사에 관하여는 그 성질에 반하지 아니하는 범위에서 「형사소송법」 제214조의2제2항부터 제14항까지, 제214조의3 및 제214조의4를 준용한다.', 3111);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5475, '① 검사는 타당한 이유가 있을 때에는 인도구속영장에 의하여 구속된 범죄인을 친족, 보호단체 또는 그 밖의 적당한 자에게 맡기거나 범죄인의 주거를 제한하여 구속의 집행을 정지할 수 있다.', 3112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5476, '② 검사는 범죄인이 다음 각 호의 어느 하나에 해당할 때에는 구속의 집행정지를 취소할 수 있다.', 3112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5477, '③ 검사는 법무부장관으로부터 범죄인에 대하여 제36조에 따른 인도장(引渡狀)이 발부되었을 때에는 지체 없이 구속의 집행정지를 취소하여야 한다.', 3112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5478, '④ 검사는 제2항이나 제3항에 따라 구속의 집행정지를 취소하였을 때에는 사법경찰관리로 하여금 범죄인을 구속하게 하여야 한다.', 3112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5479, '⑤ 검사는 제3항에 따른 구속의 집행정지 취소로 인하여 범죄인을 구속하였을 때에는 법무부장관에게 그 내용을 보고하여야 한다.', 3112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5480, '⑥ 다음 각 호의 어느 하나에 해당하는 경우에는 인도구속영장은 효력을 잃는다.', 3112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5481, null, 3114);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5482, '① 검사는 제25조에 따른 법무부장관의 긴급인도구속명령이 있을 때에는 긴급인도구속영장에 의하여 범죄인을 구속하여야 한다.', 3115);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5483, '② 긴급인도구속영장의 발부 및 그 영장에 의한 구속에 대하여는 제19조제2항ㆍ제3항, 제20조부터 제22조까지 및 제23조제1항부터 제4항까지의 규정을 준용한다.', 3115);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5484, '① 법무부장관은 긴급인도구속영장에 의하여 구속된 범죄인에 대하여 제12조제1항 단서에 따라 인도심사청구명령을 하지 아니하는 경우에는 서울고등검찰청 검사장에게 그 소속 검사로 하여금 범죄인을 석방하도록 명함과 동시에 외교부장관에게 그 사실을 통지하여야 한다. <개정 2013.3.23>', 3116);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5485, '② 검사는 제1항에 따른 법무부장관의 석방명령이 있을 때에는 지체 없이 범죄인에게 그 내용을 통지하고 그를 석방하여야 한다.', 3116);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5486, '① 검사는 긴급인도구속영장에 의하여 구속된 범죄인에 대하여 제12조제1항에 따른 법무부장관의 인도심사청구명령을 받았을 때에는 지체 없이 범죄인에게 그 사실을 서면으로 통지하여야 한다.', 3117);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5487, '② 긴급인도구속영장에 의하여 구속된 범죄인에 대하여 제1항에 따른 통지가 있은 때에는 그 구속은 인도구속영장에 의한 구속으로 보고, 제13조제2항과 제14조제2항을 적용할 때에는 그 통지가 있은 때에 인도구속영장에 의하여 범죄인이 구속된 것으로 본다.', 3117);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5488, '① 외교부장관은 제24조에 따른 서류를 송부한 후에 청구국으로부터 범죄인의 인도청구를 하지 아니한다는 통지를 받았을 때에는 지체 없이 법무부장관에게 그 사실을 통지하여야 한다. <개정 2013.3.23>', 3118);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5489, '② 법무부장관은 제1항에 따른 통지를 받았을 때에는 서울고등검찰청 검사장에게 그 소속 검사로 하여금 범죄인을 석방하도록 명하여야 한다.', 3118);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5490, '③ 검사는 제2항에 따른 법무부장관의 석방명령이 있을 때에는 지체 없이 범죄인에게 그 내용을 통지하고 그를 석방하여야 한다.', 3118);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5491, '① 긴급인도구속영장에 의하여 구속된 후 그 구속의 집행이 정지된 범죄인에 대하여 제28조제1항에 따른 통지가 있는 경우에 긴급인도구속영장에 의한 구속의 집행정지는 제23조제1항에 따른 구속의 집행정지로 본다.', 3120);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5492, '② 다음 각 호의 어느 하나에 해당하는 경우에는 긴급인도구속영장은 효력을 잃는다.', 3120);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5493, '① 검사는 다음 각 호의 어느 하나에 해당하는 경우에는 지체 없이 구속 중인 범죄인을 석방하고, 법무부장관에게 그 내용을 보고하여야 한다.', 3121);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5494, '② 법무부장관은 제1항에 따라 범죄인이 석방되었을 때에는 외교부장관에게 그 사실을 통지하여야 한다. <개정 2013.3.23>', 3121);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5495, '① 법무부장관은 제15조제1항제3호에 따른 인도허가 결정이 있는 경우에는 서울고등검찰청 검사장에게 그 소속 검사로 하여금 범죄인을 인도하도록 명하여야 한다. 다만, 청구국이 인도청구를 철회하였거나 대한민국의 이익 보호를 위하여 범죄인의 인도가 특히 부적당하다고 인정되는 경우에는 그러하지 아니하다.', 3123);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5496, '② 법무부장관은 제1항 단서에 따라 범죄인을 인도하지 아니하는 경우에는 서울고등검찰청 검사장에게 그 소속 검사로 하여금 구속 중인 범죄인을 석방하도록 명함과 동시에 외교부장관에게 그 사실을 통지하여야 한다. <개정 2013.3.23>', 3123);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5497, '③ 검사는 제2항에 따른 법무부장관의 석방명령이 있을 때에는 지체 없이 범죄인에게 그 내용을 통지하고 그를 석방하여야 한다.', 3123);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5498, '④ 법무부장관은 제3항에 따른 통지가 있은 후에는 해당 인도청구에 대한 범죄인의 인도를 명할 수 없다. 다만, 제9조제3호의 경우에 관하여 인도조약에 특별한 규정이 있는 경우에 대한민국에서 인도범죄 외의 사건에 관한 재판 또는 형의 집행이 끝나지 아니하였음을 이유로 범죄인 불인도 통지를 한 후 그에 해당하지 아니하게 되었을 때에는 그러하지 아니하다.', 3123);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5499, '① 법무부장관의 인도명령에 따른 범죄인의 인도는 범죄인이 구속되어 있는 교도소, 구치소 또는 그 밖에 법무부장관이 지정하는 장소에서 한다.', 3124);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5500, '② 인도기한은 인도명령을 한 날부터 30일로 한다.', 3124);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5501, '③ 제2항에도 불구하고 인도명령을 할 당시 범죄인이 구속되어 있지 아니한 경우의 인도기한은 범죄인이 인도집행장(引渡執行狀)에 의하여 구속되었거나 구속의 집행정지 취소에 의하여 다시 구속된 날부터 30일로 한다.', 3124);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5502, '① 법무부장관은 제34조제1항에 따른 인도명령을 할 때에는 인도장을 발부하여 서울고등검찰청 검사장에게 송부하고, 인수허가장(引受許可狀)을 발부하여 외교부장관에게 송부하여야 한다. <개정 2013.3.23>', 3125);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5503, '② 인도장과 인수허가장에는 다음 각 호의 사항을 적고, 법무부장관이 서명날인하여야 한다.', 3125);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5504, '① 검사는 법무부장관으로부터 제36조에 따른 인도장을 받았을 때에는 범죄인이 구속되어 있거나 구속의 집행이 정지될 때까지 구속되어 있던 교도소ㆍ구치소 또는 그 밖에 인도구속영장에 기재된 구금장소의 장에게 인도장을 교부하고 범죄인을 인도할 것을 지휘하여야 한다.', 3126);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5505, '② 제1항의 경우 범죄인이 구속되어 있지 아니하면 검사는 인도집행장을 발부하여 범죄인을 구속하여야 한다.', 3126);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5506, '③ 인도집행장에는 다음 각 호의 사항을 적고, 검사가 서명날인하여야 한다.', 3126);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5507, '④ 인도집행장에 의한 범죄인의 구속에 관하여는 제20조와 제21조를 준용한다.', 3126);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5508, '⑤ 검사는 범죄인이 인도집행장에 의하여 교도소, 구치소 또는 그 밖에 인도집행장에 기재된 구금장소에 구속되었을 때에는 지체 없이 그 교도소 등의 장에게 인도장을 교부하여 범죄인을 인도할 것을 지휘하고 법무부장관에게 그 내용을 보고하여야 한다.', 3126);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5509, '① 외교부장관은 법무부장관으로부터 제36조에 따른 인수허가장을 송부받았을 때에는 지체 없이 청구국에 이를 송부하여야 한다. <개정 2013.3.23>', 3128);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5510, '② 외교부장관은 법무부장관으로부터 제38조에 따른 통지를 받았을 때에는 지체 없이 그 내용을 청구국에 통지하여야 한다. <개정 2013.3.23>', 3128);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5511, '① 제37조제1항 또는 제5항에 따라 범죄인의 인도 지휘를 받은 교도소ㆍ구치소 등 인도구속영장 또는 인도집행장에 기재된 구금장소의 장은 청구국의 공무원이 인수허가장을 제시하면서 범죄인 인도를 요청하는 경우에는 범죄인을 인도하여야 한다.', 3129);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5512, '② 검사는 범죄인의 인도기한까지 제1항에 따른 인도 요청이 없는 경우에는 범죄인을 석방하고, 법무부장관에게 그 내용을 보고하여야 한다.', 3129);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5513, '① 법무부장관은 대한민국 법률을 위반한 범죄인이 외국에 있는 경우 그 외국에 대하여 범죄인 인도 또는 긴급인도구속을 청구할 수 있다.', 3131);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5514, '② 법무부장관은 외국에 대한 범죄인 인도청구 또는 긴급인도구속청구 등과 관련하여 필요하다고 판단할 때에는 적절하다고 인정되는 검사장ㆍ지청장 또는 고위공직자범죄수사처장 등에게 필요한 조치를 명하거나 요구할 수 있다. <개정 2021.1.5>', 3131);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5515, '① 제42조제2항에 따른 명령 또는 요구를 받은 검사장ㆍ지청장 또는 고위공직자범죄수사처장 등은 소속 검사에게 관련 자료의 검토ㆍ작성ㆍ보완 등 필요한 조치를 하도록 명하여야 한다. <개정 2021.1.5>', 3132);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5516, '② 제1항에 따른 명령을 받은 검사는 그 명령을 신속히 이행하고 관련 자료를 첨부하여 그 결과를 법무부장관에게 보고하여야 한다.', 3132);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5517, '① 검사 또는 고위공직자범죄수사처장은 외국에 대한 범죄인 인도청구 또는 긴급인도구속청구가 타당하다고 판단할 때에는 법무부장관에게 외국에 대한 범죄인 인도청구 또는 긴급인도구속청구를 건의 또는 요청할 수 있다. <개정 2021.1.5>', 3133);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5518, '② 제1항의 경우 검사는 인도조약 및 법무부장관이 지정한 사항을 적은 서면과 관련 자료를 첨부하여야 한다.', 3133);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5519, '① 법무부장관은 외국으로부터 인도받은 범죄인을 인도가 허용된 범죄 외의 범죄로도 처벌할 필요가 있다고 판단하는 경우에는 그 외국에 대하여 처벌에 대한 동의를 요청할 수 있다.', 3134);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5520, '② 검사 또는 고위공직자범죄수사처장은 제1항에 따른 동의 요청이 필요하다고 판단하는 경우에는 법무부장관에게 동의 요청을 건의 또는 요청할 수 있다. 이 경우 제42조의3제2항을 준용한다. <개정 2021.1.5>', 3134);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5521, '① 법무부장관은 외국으로부터 외교기관을 거쳐 그 외국의 공무원이 다른 외국에서 인도받은 사람을 대한민국 영역을 통과하여 호송하기 위한 승인을 요청하는 경우에 그 요청에 타당한 이유가 있다고 인정되는 경우에는 이를 승인할 수 있다. 다만, 다음 각 호의 어느 하나에 해당되는 경우에는 그 요청을 승인하여서는 아니 된다.', 3137);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5522, '② 법무부장관은 제1항에 따른 승인을 할 것인지에 관하여 미리 외교부장관과 협의하여야 한다. <개정 2013.3.23>', 3137);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5523, '① 법무부장관은 외국으로부터 국내로 범죄인을 호송할 때 제3국의 영토를 통과하여야 할 필요가 있는 경우에는 그 제3국에 대하여 통과호송에 관한 승인을 요청할 수 있다.', 3138);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5524, '② 제1항의 승인 요청에 관하여는 제43조와 제44조를 준용한다.', 3138);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5525, '① 법무부장관은 범죄인이 유효한 여권을 소지하지 아니하거나 제시하지 아니하는 등의 경우에 범죄인 인도의 목적을 달성하기 위하여 특히 필요하다고 판단될 때에는 「출입국관리법」 제3조ㆍ제6조제1항ㆍ제7조ㆍ제12조ㆍ제13조 및 제28조에도 불구하고 이 법 제36조에 따른 인도장ㆍ인수허가장 또는 외국정부가 발행한 범죄인 인도명령장 등 범죄인 인도 관련 서류로 출입국심사를 하고 입국 또는 출국하게 할 수 있다.', 3144);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5526, '② 법무부장관은 외국으로 인도할 범죄인이 대한민국 국민으로서 「병역법」 제70조에 따른 국외여행 허가대상 병역의무자인 경우에는 제1항의 출국조치를 하기 전에 국방부장관과 협의하여야 한다.', 3144);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5527, '①이 규칙에서 사용하는 "인도조약" "청구국" "인도범죄" 또는 "범죄인"의 용어의 정의는 법 제2조의 규정한 바와 같다.', 3146);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5528, '②이 규칙에서 "법원"이라 함은 서울고등법원을, "판사"라 함은 서울고등법원판사를, "검사"라 함은 서울고등검찰청검사를 말한다.', 3146);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5529, '①법 제13조제3항의 규정에 의한 인도심사 청구서에는 다음의 사항을 기재하고 검사가 서명날인하여야 한다.', 3149);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5530, '②범죄인의 성명을 알 수 없는 때에는 그 인상, 체격등 범죄인을 특정하는데 필요한 사항을 기재하여야 한다.', 3149);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5531, '③범죄인의 연령, 성별, 국적, 직업 또는 주거가 분명하지 아니한 때에는 그 취지를 기재하여야 한다.', 3149);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5532, '①인도구속영장 또는 긴급인도구속영장이 발부된 범죄인에 대하여 인도심사청구를 하는 경우에는 인도심사청구서에 제5조제1항에 열거된 사항외에 다음 각호의 사항을 기재하여야 한다.', 3150);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5533, '②제1항의 경우 검사는 인도심사청구서에 인도구속영장, 긴급인도구속영장, 기타 범죄인의 구속과 석방에 관련된 서류를 첨부하여야 한다.', 3150);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5534, null, 3152);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5535, '①범죄인 또는 범죄인의 법정대리인, 배우자, 직계친족, 형제자매, 호주, 가족이나 동거인 또는 고용주는 언제든지 범죄인을 위하여 변호인을 선임할 수 있다.', 3153);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5536, '②제1항에 규정된 자가 변호인을 선임하는 때에는, 인도심사청구가 있기 전에는 검사에게, 인도심사청구가 있은 이후에는 법원에, 그 선임의 취지를 기재하고 변호인과 연명날인한 서면을 제출하여야 한다.', 3153);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5537, '③검사가 제2항의 서면을 받은 때에는 인도심사청구서에 그 서면을 첨부하는등의 방법으로 이를 법원에 제출하여야 한다.', 3153);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5538, '①법원은 다음 각호의 경우에는 심문기일을 열어 범죄인 또는 출석한 관계인을 신문하거나 그 의견을 진술하게 하여야 한다.', 3156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5539, '②심문기일은 재판장이 이를 정한다.', 3156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5540, '③법원은 제1항의 경우에 검사, 범죄인 및 그 변호인에게 심문기일을 통지하여야 한다.', 3156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5541, '①검사가 법 제17조제1항의 규정에 의한 물건의 양도허가청구를 함에는 범죄인의 성명, 인도범죄사실의 요지, 양도할 국명, 물건의 종류, 특징 및 수량등 양도할 물건을 특정할 수 있는 사항을 기재한 서면으로 이를 하여야 한다.', 3165);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5542, '②물건의 양도허가청구는 인도심사청구서에 제1항의 사항을 기재하여 할 수 있다.', 3165);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5543, '③법원이 양도허가청구된 물건의 전부 또는 일부에 대하여 양도를 허가하는 때에는 결정서에 그 취지 및 양도될 물건의 목록, 양도할 국가명을 기재하고 이를 검사에게 송부한다.', 3165);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5544, '④법원은 제3항의 규정에 불구하고 제1항의 청구서의 여백에 양도허가 또는 불허가의 취지를 기재하고 관여법관이 서명날인하여 청구서를 검사에게 반환함으로써 전항의 결정서의 작성 및 송부에 갈음할 수 있다.', 3165);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5545, '⑤법원이 법 제15조제1항의 규정에 의한 결정과 동시에 물건양도의 허부를 결정하는 경우에는, 그 결정서의 주문에 제3항에 기재된 사항을 기재함으로써 물건양도허부의 결정서에 갈음할 수 있다.', 3165);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5546, '①검사의 인도구속영장의 청구는 다음 각호의 사항을 기재한 서면에 의하여 이를 하여야 한다.', 3167);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5547, '②제5조제2항 및 제3항의 규정은 제1항의 경우에 이를 준용한다.', 3167);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5548, '①검사는 인도구속영장을 청구함에 있어서 인도구속영장발부의 요건이 존재함을 소명하는 자료를 제출하여야 한다.', 3168);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5549, '②인도구속영장이 청구된 범죄인 및 그 범죄인과 법 제22조제1항이 규정한 관계에 있는 자는 판사에게 범죄인을 위하여 유리한 자료를 제출할 수 있다.', 3168);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5550, '①판사는 다음 각호의 경우에는 인도구속영장의 청구를 기각하여야 한다.', 3169);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5551, '②제1항의 경우에 판사는 인도구속영장청구서의 여백에 기각의 취지와 이유의 요지를 기재하고 서명날인하여야 한다.', 3169);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5552, '①인도구속영장에는 법 제19조제3항이 규정한 사항외에 다음 각호의 사항을 기재하여야 한다.', 3170);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5553, '②제5조제2항 및 제3항은 제1항의 경우에 이를 준용한다.', 3170);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5554, '①판사는 검사의 청구에 의하여 필요하다고 인정하는 경우에 수통의 인도구속영장을 발부할 수 있다.', 3171);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5555, '②제1항의 경우에는 그 사유를 인도구속영장에 기재하여야 한다.', 3171);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5556, null, 3173);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5557, null, 3180);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5558, '① 국가는 범죄신고자등을 보호하고, 이들에 대한 보복범죄를 예방하기 위한 법적ㆍ제도적 장치를 마련하고, 필요한 재원을 조달하여야 한다.', 3182);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5559, '② 수사기관 등은 이 법을 적용할 때 피의자ㆍ피고인의 방어권 및 변호인의 변론권을 부당하게 침해하지 아니하도록 주의하여야 한다.', 3182);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5560, '① 사법경찰관, 검사 또는 법원은 범죄신고자등이나 그 친족등이 보복을 당할 우려가 있는 경우에는 직권으로 또는 범죄신고자등, 그 법정대리인이나 친족등의 신청에 의하여 범죄신고자등보좌인(이하 "보좌인"이라 한다)을 지정할 수 있다.', 3184);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5561, '② 보좌인은 범죄신고자등의 법정대리인, 친족 또는 대통령령으로 정하는 자 중에서 지정한다. 다만, 수사기관 종사자는 보좌인이 될 수 없다.', 3184);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5562, '③ 보좌인은 범죄신고자등을 위하여 해당 형사사건의 수사ㆍ공판 과정에 동행하거나 조언하는 등 필요한 조력(助力)을 할 수 있다.', 3184);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5563, '④ 보좌인은 거짓 진술을 유도하는 등 범죄신고자등의 진술이나 증언 등에 부당한 영향을 주어서는 아니 된다.', 3184);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5564, '⑤ 보좌인이 다음 각 호의 어느 하나에 해당하는 경우에는 그 지정을 취소할 수 있다.', 3184);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5565, '⑥ 제5항에 따른 지정의 취소는 해당 사건의 진행 경과에 따라 사법경찰관, 검사 또는 법원이 결정한다.', 3184);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5566, '⑦ 사법경찰관이 보좌인을 지정하거나 취소하려면 지체 없이 검사에게 보고하여 허가를 받아야 한다.', 3184);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5567, '⑧ 제6항에 따른 취소 결정에 대하여는 이의를 제기할 수 없다.', 3184);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5568, '⑨ 보좌인의 지정은 제5항에 따라 취소되지 아니하는 한 해당 사건이 종결될 때까지 효력을 가진다.', 3184);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5569, '⑩ 보좌인에게는 대통령령으로 정하는 바에 따라 여비나 그 밖의 실비(實費)를 지급할 수 있다.', 3184);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5570, '① 검사 또는 사법경찰관은 범죄신고등과 관련하여 조서나 그 밖의 서류(이하 "조서등"이라 한다)를 작성할 때 범죄신고자등이나 그 친족등이 보복을 당할 우려가 있는 경우에는 그 취지를 조서등에 기재하고 범죄신고자등의 성명ㆍ연령ㆍ주소ㆍ직업 등 신원을 알 수 있는 사항(이하 "인적 사항"이라 한다)은 기재하지 아니한다. <개정 2014.12.30>', 3185);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5571, '② 사법경찰관이 조서등에 범죄신고자등의 인적 사항의 전부 또는 일부를 기재하지 아니한 경우에는 즉시 검사에게 보고하여야 한다.', 3185);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5572, '③ 제1항의 경우 검사 또는 사법경찰관은 조서등에 기재하지 아니한 인적 사항을 범죄신고자등 신원관리카드(이하 "신원관리카드"라 한다)에 등재하여야 한다.', 3185);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5573, '④ 제1항에 따라 조서등에 성명을 기재하지 아니하는 경우에는 범죄신고자등으로 하여금 조서등에 서명은 가명(假名)으로, 간인(間印) 및 날인(捺印)은 무인(拇印)으로 하게 하여야 한다. 이 경우 가명으로 된 서명은 본명(本名)의 서명과 동일한 효력이 있다.', 3185);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5574, '⑤ 범죄신고자등은 진술서 등을 작성할 때 검사 또는 사법경찰관의 승인을 받아 인적 사항의 전부 또는 일부를 기재하지 아니할 수 있다. 이 경우 제2항부터 제4항까지의 규정을 준용한다.', 3185);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5575, '⑥ 범죄신고자등이나 그 법정대리인은 검사 또는 사법경찰관에게 제1항에 따른 조치를 하도록 신청할 수 있다. 이 경우 검사 또는 사법경찰관은 특별한 사유가 없으면 그 조치를 하여야 한다.', 3185);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5576, '⑦ 신원관리카드는 검사가 관리한다.', 3185);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5577, '⑧ 신원관리카드의 작성 및 관리 등에 필요한 사항은 대통령령으로 정한다.', 3185);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5578, '① 법원은 다른 사건의 재판에 필요한 경우에는 검사에게 신원관리카드의 열람을 요청할 수 있다. 이 경우 요청을 받은 검사는 범죄신고자등이나 그 친족등이 보복을 당할 우려가 있는 경우 외에는 그 열람을 허용하여야 한다.', 3187);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5579, '② 다음 각 호의 어느 하나에 해당하는 경우에는 그 사유를 소명(疏明)하고 검사의 허가를 받아 신원관리카드를 열람할 수 있다. 다만, 범죄신고자등이나 그 친족등이 보복을 당할 우려가 있는 경우에는 열람을 허가하여서는 아니 된다.', 3187);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5580, '③ 피의자 또는 피고인이나 그 변호인 또는 법정대리인, 배우자, 직계친족과 형제자매는 피해자와의 합의를 위하여 필요한 경우에 검사에게 범죄신고자등과의 면담을 신청할 수 있다.', 3187);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5581, '④ 제3항의 면담 신청을 받은 검사는 즉시 그 사실을 범죄신고자등에게 통지하고, 범죄신고자등이 이를 승낙한 경우에는 검사실 등 적당한 장소에서 범죄신고자등이나 그 대리인과 면담을 할 수 있도록 조치할 수 있다.', 3187);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5582, '⑤ 제2항제2호에 따라 신원관리카드의 열람을 신청한 변호인과 제3항에 따라 면담 신청을 한 자는 검사의 거부처분에 대하여 이의신청을 할 수 있다.', 3187);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5583, '⑥ 제5항의 이의신청은 그 검사가 소속된 지방검찰청검사장(지청의 경우에는 지청장)에게 서면으로 제출하여야 한다. 이의신청을 받은 검사장 또는 지청장은 이의신청이 이유가 있다고 인정하는 경우에는 신원관리카드의 열람을 허가하거나 범죄신고자등이나 그 대리인과 면담할 수 있도록 조치하여야 한다.', 3187);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5584, '① 범죄신고자등에 대하여 「형사소송법」 제184조(증거보전의 청구와 그 절차) 또는 제221조의2(증인신문의 청구)에 따른 증인신문을 하는 경우 판사는 직권으로 또는 검사의 신청에 의하여 그 과정을 비디오테이프 등 영상물로 촬영할 것을 명할 수 있다.', 3188);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5585, '② 제1항에 따른 영상물의 촬영비용 및 복사에 관하여는 「형사소송법」 제56조의2(공판정에서의 속기ㆍ녹음 및 영상녹화)제2항 및 제3항을 준용한다.', 3188);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5586, '③ 제1항에 따라 촬영한 영상물에 수록된 범죄신고자등의 진술은 이를 증거로 할 수 있다.', 3188);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5587, '① 제7조에 따라 조서등에 인적 사항을 기재하지 아니한 범죄신고자등을 증인으로 소환할 때에는 검사에게 소환장을 송달한다.', 3189);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5588, '② 재판장 또는 판사는 소환된 증인 또는 그 친족등이 보복을 당할 우려가 있는 경우에는 참여한 법원서기관 또는 서기로 하여금 공판조서에 그 취지를 기재하고 해당 증인의 인적 사항의 전부 또는 일부를 기재하지 아니하게 할 수 있다. 이 경우 재판장 또는 판사는 검사에게 신원관리카드가 작성되지 아니한 증인에 대한 신원관리카드의 작성 및 관리를 요청할 수 있다.', 3189);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5589, '③ 제2항의 경우 재판장 또는 판사는 증인의 인적 사항이 신원확인, 증인선서, 증언 등 증인신문의 모든 과정에서 공개되지 아니하도록 하여야 한다. 이 경우 제1항에 따라 소환된 증인의 신원확인은 검사가 제시하는 신원관리카드로 한다.', 3189);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5590, '④ 제2항에 따라 공판조서에 인적 사항을 기재하지 아니하는 경우 재판장 또는 판사는 범죄신고자등으로 하여금 선서서(宣誓書)에 가명으로 서명ㆍ무인하게 하여야 한다. 이 경우 제7조제4항 후단을 준용한다.', 3189);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5591, '⑤ 증인으로 소환된 범죄신고자등이나 그 친족등이 보복을 당할 우려가 있는 경우에는 검사, 범죄신고자등 또는 그 법정대리인은 법원에 피고인이나 방청인을 퇴정(退廷)시키거나 공개법정 외의 장소에서 증인신문을 할 것을 신청할 수 있다.', 3189);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5592, '⑥ 재판장 또는 판사는 직권으로 또는 제5항에 따른 신청이 상당한 이유가 있다고 인정할 때에는 피고인이나 방청인을 퇴정시키거나 공개법정 외의 장소에서 증인신문 등을 할 수 있다. 이 경우 변호인이 없을 때에는 국선변호인을 선임하여야 한다.', 3189);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5593, '⑦ 제6항의 경우에는 「법원조직법」 제57조(재판의 공개)제2항ㆍ제3항 및 「형사소송법」 제297조(피고인등의 퇴정)제2항을 준용한다.', 3189);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5594, '① 법원은 범죄신고자등이나 그 친족등이 보복을 당할 우려가 있는 경우에는 검사 및 변호인과 해당 피고인에 대한 공판기일의 지정이나 그 밖의 소송 진행에 필요한 사항을 협의할 수 있다.', 3190);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5595, '② 제1항에 따른 협의는 소송진행에 필요한 최소한에 그쳐야 하며, 판결에 영향을 주어서는 아니 된다.', 3190);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5596, '③ 제1항의 경우에는 「특정강력범죄의 처벌에 관한 특례법」 제10조(집중심리) 및 제13조(판결선고)를 준용한다.', 3190);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5597, '① 검사 또는 경찰서장은 범죄신고자등이나 그 친족등이 보복을 당할 우려가 있는 경우에는 일정 기간 동안 해당 검찰청 또는 경찰서 소속 공무원으로 하여금 신변안전을 위하여 필요한 조치(이하 "신변안전조치"라 한다)를 하게 하거나 대상자의 주거지 또는 현재지(現在地)를 관할하는 경찰서장에게 신변안전조치를 하도록 요청할 수 있다. 이 경우 요청을 받은 경찰서장은 특별한 사유가 없으면 즉시 신변안전조치를 하여야 한다.', 3191);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5598, '② 재판장 또는 판사는 공판준비 또는 공판진행 과정에서 검사에게 제1항에 따른 조치를 하도록 요청할 수 있다.', 3191);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5599, '③ 범죄신고자등, 그 법정대리인 또는 친족등은 재판장ㆍ검사 또는 주거지나 현재지를 관할하는 경찰서장에게 제1항에 따른 조치를 하여 줄 것을 신청할 수 있다.', 3191);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5600, '④ 경찰서장이 신변안전조치를 한 경우에는 대통령령으로 정하는 바에 따라 그 사실을 검사에게 통보하여야 한다.', 3191);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5601, '⑤ 제1항에 따른 신변안전조치의 절차 등에 관하여 필요한 사항은 대통령령으로 정한다. <개정 2014.12.30>', 3191);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5602, null, 3192);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5603, '① 국가는 범죄신고자등이나 그 친족등이 보복을 당할 우려가 있는 경우로서 그로 인하여 중대한 경제적 손실 또는 정신적 고통을 받았거나 이사ㆍ전직(轉職) 등으로 비용을 지출하였거나 지출할 필요가 있을 때에는 범죄신고자등, 그 법정대리인 또는 친족등의 신청에 의하여 범죄신고자등 구조금(이하 "구조금"이라 한다)을 지급할 수 있다.', 3193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5604, '② 구조금의 금액은 보복의 위험성, 지급대상자의 직업ㆍ신분ㆍ생활수준, 경제적 손실과 정신적 고통의 정도, 지출비용, 그 밖의 필요한 사항을 고려하여 대통령령으로 정하는 한도에서 결정한다.', 3193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5605, '③ 구조금 지급에 관한 사항을 심의ㆍ결정하기 위하여 지방검찰청에 범죄신고자등 구조심의회(이하 "심의회"라 한다)를 둔다.', 3193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5606, '④ 심의회는 법무부장관의 지휘ㆍ감독을 받는다.', 3193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5607, '⑤ 심의회는 구조금 지급에 관한 사항을 심의ㆍ결정하기 위하여 필요할 때에는 신청인이나 그 밖의 관계인을 조사하거나 행정기관 또는 공ㆍ사단체(公ㆍ私團體)에 필요한 사항을 알아볼 수 있다. 이 경우 행정기관 및 공ㆍ사단체는 특별한 사유가 없으면 이에 따라야 한다.', 3193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5608, '⑥ 심의회의 구성ㆍ운영 및 구조금 지급에 필요한 사항은 대통령령으로 정한다.', 3193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5609, '① 제8조를 위반한 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.', 3196);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5610, '② 제5조를 위반하여 범죄신고자등에게 「공익신고자 보호법」 제2조제6호에 해당하는 불이익조치를 한 자는 2년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.', 3196);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5611, null, 3198);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5612, '①법 제6조제10항의 규정에 의하여 범죄신고자등보좌인(이하 "보좌인"이라 한다)에게 지급할 수 있는 비용은 범죄신고자등과의 동행일수에 따른 일당ㆍ여비 및 숙박료(이하 이 조에서 "실비"라 한다)로 한다.', 3199);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5613, '②제1항의 규정에 의한 실비는 당해 사건의 진행경과에 따라 참고인 또는 증인에 준하여 지급하되, 수사단계에서는 수사기관이, 재판단계에서는 법원이 각각 이를 지급한다.', 3199);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5614, '①법 제7조제3항의 규정에 의한 범죄신고자등신원관리카드(이하 "신원관리카드"라 한다)에는 범죄신고자등의 성명ㆍ주민등록번호ㆍ주소 및 직업 등 신원을 알 수 있는 사항과 보좌인, 변호인, 법제13조의 규정에 의한 신변안전조치 및 법 제14조의 규정에 의한 구조금의 지급에 관한 사항 등을 기재한다.', 3200);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5615, '②법 제7조제4항의 규정에 의하여 범죄신고자등이 조서등에 가명으로 서명한 때에는 검사 또는 사법경찰관은 조서에 기재한 가명을 신원관리카드에 기재하고 범죄신고자등으로 하여금 본명과 가명의 서명을 신원관리카드에 기재하고 무인하게 하여야 한다.', 3200);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5616, '①사법경찰관이 사건을 송치하는 때에는 수사서류와 별도로 신원관리카드를 봉인하여 사건기록과 함께 관할 검찰청에 이를 제출하여야한다.', 3201);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5617, '②각급 검찰청의 장(지방검찰청 지청의 장을 포함한다)은 신원관리카드를 관리하는 검사를 지정하여야 한다.', 3201);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5618, '③신원관리카드는 공소제기후에도 제2항의 규정에 의한 검사가 이를 관리한다.', 3201);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5619, '④법 제11조제3항 후단의 규정에 의하여 증인의 신원확인을 하는 때에는 검사가공판정에서 재판장 또는 판사에게 직접 신원관리카드를 제시하고, 재판장 또는판사는 지체없이 담당 법원사무관 등으로 하여금 신원관리카드에 의하여 신원을 확인하게 하여야 한다.', 3201);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5620, '①법 제13조제1항 내지 제3항의 규정에 의한 신변안전조치의 요청 또는 신청은 이를 서면(전자문서를 포함한다. 이하 같다)으로 하여야 한다. 다만, 긴급을 요하는 경우에는 구두 또는 유선으로 하되, 사후에 지체없이 관련 서면을 제출하여야 한다. <개정 2004.3.17>', 3202);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5621, '②재판장 또는 판사는 제1항의 규정에 불구하고 공판정에 출석한 검사에게 신변안전조치를 취하도록 구두로 요청할 수 있다. 이 경우 그 취지를 공판조서에 기재하여야 한다.', 3202);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5622, '③제1항의 규정에 의한 신변안전조치를 요청 또는 신청하고자 하는 때에는 필요한 신변안전조치의 종류와 기간을 구체적으로 기재하여야 한다.', 3202);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5623, '④경찰청장(해양경찰청장을 포함한다. 이하 같다) 또는 시ㆍ도경찰청장(지방해양경찰청장을 포함한다. 이하 같다)은 당해관서에서 수사중인 사건의 범죄신고자등이나 그 친족 등에 대하여 신변안전조치를 취할 필요가 있는 때에는 대상자의 주거지 또는 현재지를 관할하는 경찰서장(해양경찰서장을 포함한다. 이하 같다)에게 신변안전조치를 취하도록 지시할 수 있다. <개정 2014.11.19, 2017.7.26, 2020.12.31>', 3202);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5624, null, 3203);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5625, '①경찰서장이 법 제13조제1항의 규정에 의한 신변안전조치를 취한 때에는 다음 각호의 구분에 따라 지체없이 그 사실을 해당검사에게 통보하여야 한다. <개정 2020.12.31>', 3204);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5626, '②제1항의 규정에 의한 통보서류 및 신변안전조치와 관련된 서류는 이를 공개하여서는 아니된다.', 3204);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5627, '①법 제14조의 규정에 의한 구조금은 지출하였거나 지출할 필요가 있는 치료비, 생활비, 이사 및 전직비용, 방범시설 설치비, 수사기간중 범죄신고자등 또는 그 친족등의 보호나 경호에 필요한 비용과 위자료 등을 포함하여 이를 산정한다.', 3205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5628, '②제1항의 규정에 의한 구조금중 치료비, 이사비용, 방범시설 설치비와 범죄신고자등 또는 그 친족 등의 보호나 경호에 필요한 비용은 이를 실비로 지급한다.', 3205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5629, '③제1항의 규정에 의한 구조금중 생활비ㆍ전직비용 및 위자료는 이를 합산하여 월정액으로 지급할 수 있으며, 이 경우에는 구조금지급 대상자의 근무직종에 따라 구조결정시 최저임금법에서 정한 일급최저임금의 5배 이하를 기준으로 하여 산정하여야 한다.', 3205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5630, '①심의회는 제10조의 규정에 의한 구조금의 신청이 있는 때에는 특별한 사유가 없는 한 신청일부터 1월 이내에 구조금의 지급여부에 대한결정(지급한다는 결정을 하는 경우에는 그 금액을 포함한다. 이하 같다)을 하여야한다.', 3207);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5631, '②검사는 제10조 또는 제1항의 규정에 의한 절차를 거칠 수 없는 긴급한 사유가 있는 때에는 범죄신고자등 또는 그 친족등의 보호나 경호 등에 필요한 비용 등을 가지급할 것을 심의회에 요청할 수 있다. 이 경우 심의회는 제1항의 규정에 불구하고 가지급결정을 할 수 있다.', 3207);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5632, '①심의회의 위원장은 심의회의 업무를 통할하고, 심의회를 대표한다.', 3210);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5633, '②위원장이 부득이한 사유로 직무를 수행할 수 없는 때에는 위원장이 미리 지명한 위원이 그 직무를 대행하고, 지명이 없는 경우에는 심의회가 설치된 기관의 소속공무원인 위원중에서 선임자가 그 직무를 대행한다.', 3210);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5634, '①위원장은 심의회의 회의(이하 "회의"라 한다)를 소집하고 그 의장이 된다.', 3211);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5635, '②회의는 위원장을 포함한 재적위원 과반수의 출석으로 개의하고, 출석위원 3분의 2이상의 찬성으로 의결한다.', 3211);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5636, '③구조금의 액수에 관한 의견이 3 이상으로 나뉘어져 각각 의결정족수 3분의 2에 달하지 못한 때에는 의결정족수 3분의 2에 달하기까지 최소액의 의견수에 순차로 다액의 의견수를 더하여 그중 최다액의 의견에 의한다.', 3211);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5637, '①심의회에 그 사무를 처리하게 하기 위하여 간사 1인과 서기 약간인을 둔다.', 3212);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5638, '②간사와 서기는 심의회가 설치된 지방검찰청 소속 공무원중에서 위원장의 추천으로 당해 지방검찰청 검사장이 임명한다.', 3212);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5639, '③간사는 위원장의 명에 의하여 심의회의 사무를 처리한다.', 3212);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5640, '④간사는 회의에 출석하여 발언할 수 있다.', 3212);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5641, '⑤서기는 간사를 보조하고 심의회의 관련서류를 관리한다.', 3212);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5642, '①법무부장관은 각 심의회를 지휘ㆍ감독하기 위하여 필요한 명령이나 조치를 할 수 있다.', 3213);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5643, '②법무부장관은 제1항의 직무를 행하기 위하여 필요하다고 인정하는 때에는 소속직원 또는 각급 검찰청의 검사로 하여금 각 심의회의 업무처리사항에 관하여 감사를 하게 할 수 있다.', 3213);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5644, '①심의회가 구조결정을 한 때에는 구조결정서를 작성하고 회의에 출석한 위원 전원이 서명 또는 날인하여야 한다.', 3214);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5645, '②제1항의 규정에 의한 구조결정서에는 다음 각호의 사항을 기재하여야 한다.', 3214);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5646, '③심의회가 구조결정을 한 때에는 신청인에게 구조결정통지서를 송부하여야 한다.', 3214);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5647, '①구조금의 지급을 청구하고자 하는 자는 구조결정을 한심의회가 설치된 지방검찰청에 구조금지급청구서를 제출하여야 한다.', 3215);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5648, '②제1항의 규정에 의한 청구서에는 다음 각호의 사항을 기재하여야 한다.', 3215);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5649, '①신원관리카드와 함께 사건기록을 배당받은 검사는 사건 종국결정시 신원관리카드에 해당사항을 기재한 후 즉시 신원관리카드를 관리하는 검사에게 이를 인계하고, 신원관리카드를 관리하는 검사는 별지 제7호서식에 의한 범죄신고자등 신원관리카드대장을 작성하여야 한다.', 3224);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5650, '②법원이 법 제6조의 규정에 의하여 보좌인을 지정ㆍ취소 또는 교체한 때에는 별지 제8호서식에 의하여 당해 사건을 기소한 검찰청의 신원관리카드를 관리하는 검사에게 그 내용을 통보하여야 한다.', 3224);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5651, '①법 제9조제2항의 규정에 의한 신원관리카드의 열람허가신청은 별지 제9호서식에 의한다.', 3226);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5652, '②검사는 제1항의 규정에 의한 신원관리카드의 열람허가신청을 받은 때에는 그 허가여부에 대한 결정을 한 후 지체없이 그 결과를 신청인에게 서면으로 통지하여야 한다.', 3226);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5653, '①법 제9조제4항의 규정에 의한 면담신청사실의 통지는 별지 제11호서식에 의한다.', 3228);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5654, '②검사는 제1항의 규정에 불구하고 서면외에 전화ㆍ팩스 등을 이용하여 면담신청사실을 통지할 수 있다. 이 경우 관련 증빙서류를 수사기록에 첨부하여야 한다.', 3228);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5655, '①법 제9조제5항의 규정에 의한 이의신청은 별지 제12호서식에 의한다.', 3229);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5656, '②지방검찰청검사장(지청의 경우에는 지청장)은 제1항의 규정에 의한 이의신청을 받은 때에는 그에 대한 수용여부를 결정한 후 지체없이 그 결과를 이의신청인에게 서면으로 통지하여야 한다.', 3229);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5657, '①영 제11조제2항 후단의 규정에 의하여 가지급결정을 한 때에는 별지 제19호서식에 의한 가구조결정서를 작성하여야 한다.', 3236);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5658, '②영 제18조제1항의 규정에 의한 구조결정서의 작성은 별지 제20호서식에 의하고, 동조제3항의 규정에 의한 구조결정통지는 별지 제21호서식에 의한다.', 3236);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5659, null, 3238);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5660, '①별지 제1호서식 내지 별지 제4호서식 및 별지 제8호서식 내지 별지 제11호서식에 의하여 작성한 서류는 사건기록에 이를 편철한다. 다만, 법 제7조의 규정에 의하여 인적사항의 전부 또는 일부를 기재하지 아니한 범죄신고자등에 대한 신원을 알 수 있는 내용이 기재되어 있는 경우에는 사건기록에 이를 편철하여서는 아니된다.', 3241);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5661, '②제1항의 규정에 의하여 사건기록에 편철한 서류를 제외한 나머지 서류는 그 작성기관의 장이 범죄신고자등 또는 그 친족등에 대한 비밀보호를 위하여 적절한 보존조치를 취한 후 별도로 관리하여야 한다.', 3241);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5662, null, 3243);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5663, '① 법무부장관은 「형의 집행 및 수용자의 처우에 관한 법률」 제68조에 따라 수형자가 외부기업체 등에 통근 작업하거나 교정시설의 안에 설치된 외부기업체의 작업장에서 작업할 수 있도록 민간기업을 참여하게 하여 교도작업을 운영할 수 있다.', 3247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5664, '② 교정시설의 장은 제1항에 따라 민간기업이 참여할 교도작업(이하 이 조에서 "민간참여작업"이라 한다)의 내용을 해당 기업체와의 계약으로 정하고 이에 대하여 법무부장관의 승인(재계약의 경우에는 지방교정청장의 승인)을 받아야 한다. 다만, 법무부장관이 정하는 단기의 계약에 대하여는 그러하지 아니하다.', 3247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5665, '③ 제1항 및 제2항에 따른 민간기업의 참여 절차, 민간참여작업의 종류, 그 밖에 민간참여작업의 운영에 필요한 사항은 「형의 집행 및 수용자의 처우에 관한 법률」 제68조제1항의 사항을 고려하여 법무부장관이 정한다.', 3247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5666, '① 교도작업의 효율적인 운영을 위하여 교도작업특별회계(이하 "특별회계"라 한다)를 설치한다.', 3249);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5667, '② 특별회계는 법무부장관이 운용ㆍ관리한다.', 3249);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5668, '① 특별회계의 세입(歲入)은 다음 각 호와 같다.', 3250);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5669, '② 특별회계의 세출(歲出)은 다음 각 호와 같다.', 3250);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5670, '① 특별회계는 지출할 자금이 부족할 경우에는 특별회계의 부담으로 국회의 의결을 받은 금액의 범위에서 일시적으로 차입하거나 세출예산의 범위에서 수입금 출납공무원 등이 수납한 현금을 우선 사용할 수 있다.', 3252);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5671, '② 제1항에 따라 일시적으로 차입하거나 우선 사용한 자금은 해당 회계연도 내에 상환하거나 지출금으로 대체납입하여야 한다.', 3252);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5672, '① 법무부장관은 수요기관에 대하여 법 제4조에 따른 공고에 필요한 자료의 제출을 요청할 수 있다.', 3258);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5673, '② 제1항에 따른 요청을 받은 수요기관은 지정된 기간 내에 필요한 자료를 성실하게 작성하여 제출하여야 한다.', 3258);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5674, '① 법무부장관은 제3조에 따라 제출된 생산공급계획과 제4조에 따라 제출된 자료를 검토하고 다음 각 호의 사항을 고려하여 법 제4조에서 정한 기한까지 다음 연도에 생산할 교도작업제품의 종류와 수량을 결정하여 공고하여야 한다.', 3259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5675, '② 법무부장관은 교도작업제품을 공급할 수 없을 때에는 해당 지역 또는 해당 수요기관을 미리 공고하여야 한다.', 3259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5676, '① 소장은 다음 각 호의 사항을 고려하여 법무부장관의 승인을 받아 교도작업의 시행방법에 따른 교도작업의 종류를 교도작업제품별로 정한다. 교도작업의 종류를 변경하는 경우에도 또한 같다.', 3260);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5677, '② 제1항에 따른 교도작업의 종류 및 그 승인 절차는 법무부령으로 정한다.', 3260);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5678, '① 특별회계의 회계처리는 「국가회계법」 제11조에 따른 국가회계기준에 따른다.', 3262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5679, '② 법무부장관은 특별회계 재무구조의 건전화와 효율적인 경영성과의 분석을 위하여 필요하다고 인정하면 별도의 회계기준을 마련하여 특별회계 운영의 분석에 활용할 수 있다.', 3262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5680, null, 3263);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5681, null, 3264);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5682, null, 3267);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5683, '① 법 제6조제1항에 따라 교도작업에 참여하려는 민간기업은 별지 서식의 참여신청서를 법무부장관에게 제출하여야 한다.', 3268);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5684, '② 교도작업에 참여하려는 민간기업은 경영상태가 양호하고, 취업지원을 하는 등 수형자의 사회복귀에 도움이 될 수 있어야 한다.', 3268);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5685, '① 법 제6조제2항 단서에서 "법무부장관이 정하는 단기의 계약"이란 계약기간이 2개월 이하인 계약을 말한다.', 3269);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5686, '② 소장은 제1항에 따른 계약을 체결한 경우에는 지체 없이 법무부장관에게 보고하여야 한다.', 3269);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5687, '① 영 제6조에 따른 교도작업의 종류는 다음  각 호와 같다', 3270);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5688, '② 소장은 제1항에 따른 작업을 중지하려면 지방교정청장의 승인을 받아야 한다.', 3270);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5689, null, 3271);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5690, '① 계약담당자는 계약을 수의계약으로 하려면 「교도관직무규칙」 제21조에 따른 교도관회의의 심의를 거쳐야 한다.', 3273);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5691, '② 계약담당자가 계약을 수의계약으로 한 경우에는 법무부장관에게 보고하여야 한다.', 3273);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5692, '① 법 제6조제1항의 전자화대상문서가 법원에 제출된 경우에는 법원서기관, 법원사무관, 법원주사 또는 법원주사보(이하 "법원사무관등"이라 한다)는 전자화대상 문서를 전자화문서로 작성하고, 법원의 형사사법정보시스템에 등재한다.', 3276);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5693, '② 법 제6조제1항의 전자화대상문서를 기술적 문제, 그 밖의 다른 사유로 전자화할 수 없는 경우에는 이를 별도의 기록으로 관리ㆍ보관한다. 법원사무관등은 법원의 형사사법정보시스템에 그 취지를 입력하여야 한다.', 3276);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5694, '① 법원은 법 제7조의 규정에 따라 검사가 제출한 전자문서 및 전자화문서를 법원의 형사사법정보시스템을 이용하여 접수한다.', 3277);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5695, '② 피고인은 법 제2조제4호의 형사사법포털을 이용하여 전자문서 및 전자화문서를 법원에 제출할 수 있다.', 3277);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5696, '③ 제1항 및 제2항에 따른 전자문서 및 전자화문서는 법원의 형사사법정보시스템에 접수된 때 법원에 제출된 것으로 본다.', 3277);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5697, '① 법원사무관등은 법 제8조제1항에 따라 다음 각 호의 사유를 피고인이 제출한 동의서에 적힌 전자우편 또는 휴대전화 문자서비스로 통지한다.', 3278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5698, '② 제1항제2호의 통지를 받은 피고인은 형사사법포털에 접속하여 약식명령등본을 열람ㆍ출력할 수 있다.', 3278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5699, '③ 제1항제2호의 사실을 전자우편 또는 휴대전화 문자서비스로 전송한 때를 법 제8조제4항에 따른 ‘약식명령을 올린 사실을 알린 날’로 본다.', 3278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5700, '④ 제1항제2호의 사실의 통지가 제1항의 전자우편 또는 휴대전화 문자서비스로 도달하지 아니하였음이 객관적으로 증명되는 때에는 법 제8조제4항의 ‘송달을 받을 사람이 책임질 수 없는 사유’로 본다.', 3278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5701, '① 법 제8조제1항의 검사에 대한 약식명령이나 그 밖의 소송에 관한 서류의 송달 또는 통지는 그 전자문서나 정보를 검찰의 형사사법정보시스템으로 전송하는 방식에 의한다.', 3279);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5702, '② 약식명령이 검찰의 형사사법정보시스템에 접수된 때에 검사에 대한 약식명령이 송달된 것으로 본다.', 3279);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5703, null, 3282);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5704, '① 법에 따른 약식명령에 대한 경정신청은 종이문서로 법원에 제출하여야 한다.', 3284);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5705, '② 법원사무관등은 경정결정 등본을 전자적으로 검사 및 피고인에게 송달한다.', 3284);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5706, '① 법원의 형사사법정보시스템에 등재된 약식사건기록의 전자문서 및 전자화문서는 종이문서로 출력한 뒤 그 출력물을 보는 방법으로 열람할 수 있다.', 3285);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5707, '② 법원의 형사사법정보시스템에 등재된 약식사건의 열람, 출력을 신청할 경우 신청인이 납부하여야 할 수수료의 금액은 다음 각 호와 같다. 단, 약식명령이나 판결이 확정되기 전에 열람하는 경우에는 아래 1호에 규정된 기록의 열람ㆍ출력에 관한 수수료를 납부하지 아니한다. <개정 2012.5.29>', 3285);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5708, '③ 사건기록의 열람, 출력에 관하여 이 규칙에 특별한 규정이 없으면 「재판기록 열람ㆍ복사 규칙」을 준용한다. <개정 2012.12.27>', 3285);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5709, null, 3287);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5710, '① 오염물질을 불법배출함으로써 사람의 생명이나 신체에 위해를 끼치거나 상수원을 오염시킴으로써 먹는 물의 사용에 위험을 끼친 자는 3년 이상 15년 이하의 유기징역에 처한다. <개정 2015.2.3>', 3288);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5711, '② 제1항의 죄를 범하여 사람을 죽거나 다치게 한 자는 무기 또는 5년 이상의 유기징역에 처한다.', 3288);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5712, '③ 오염물질을 불법배출한 자로서 다음 각 호의 어느 하나에 해당하거나 「물환경보전법」 제15조제1항제4호를 위반한 자로서 제3호에 해당하는 자는 1년 이상 7년 이하의 징역에 처한다. <개정 2017.1.17>', 3288);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5713, '① 환경보호지역에서 제3조제1항부터 제3항까지의 죄를 범한 자에 대하여는 해당 형(刑)의 2분의 1까지 가중할 수 있다.', 3289);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5714, '② 환경보호지역에서 「자연환경보전법」 제15조제1항제2호(「자연환경보전법」 제22조제2항에서 준용하는 경우를 포함한다), 「독도 등 도서지역의 생태계보전에 관한 특별법」 제8조제1항제3호, 「자연공원법」 제23조제1항제3호(공원구역 중 공원자연보존지구와 공원자연환경지구의 경우만 해당한다), 「습지보전법」 제13조제1항제1호 또는 「수도법」 제7조제4항제3호를 위반하여 토지를 300제곱미터 이상 형질변경한 자는 2년 이상 15년 이하의 유기징역에 처한다. <개정 2015.2.3>', 3289);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5715, '③ 오염물질을 불법배출하거나 제2항의 죄를 범하여 환경보호지역을 그 설정 또는 지정의 목적을 상실하게 할 정도에 이르게 한 자는 5년 이상의 유기징역에 처한다.', 3289);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5716, '① 업무상 과실 또는 중대한 과실로 제3조제1항의 죄를 범한 자는 7년 이하의 징역 또는 1억원 이하의 벌금에 처한다. <개정 2015.2.3>', 3290);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5717, '② 업무상 과실 또는 중대한 과실로 제3조제2항 또는 제4조제3항의 죄를 범한 자는 10년 이하의 징역 또는 1억5천만원 이하의 벌금에 처한다. <개정 2015.2.3>', 3290);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5718, '③ 업무상 과실 또는 중대한 과실로 제3조제3항의 죄를 범한 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다. <개정 2015.2.3>', 3290);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5719, '① 제13조제1항에 따른 명령(철거명령은 제외한다)을 위반한 자는 5년 이하의 징역에 처한다.', 3294);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5720, '② 제13조제1항에 따른 철거명령을 위반한 자 또는 제13조제4항에 따라 설치된 표지판을 제거ㆍ훼손한 자는 2년 이하의 징역 또는 2천만원 이하의 벌금에 처한다. <개정 2015.2.3>', 3294);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5721, '① 환경부장관은 다음 각 호의 어느 하나에 해당하는 자에게 매출액에 100분의 5를 곱한 금액을 초과하지 아니하는 금액(이하 이 조에서 "위반부과금액"이라 한다)과 오염물질의 제거 및 원상회복에 드는 비용(이하 "정화비용"이라 한다)을 더한 금액을 과징금으로 부과할 수 있다. 다만, 매출액이 없거나 매출액의 산정이 곤란한 경우로서 대통령령으로 정하는 경우에는 위반부과금액을 10억원 이내로 한다. <개정 2019.11.26, 2024.2.6, 2025.3.25>', 3297);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5722, '② 제1항에 따른 매출액을 계산할 때에는 해당 사업장의 최근 3년간 매출액의 평균을 기준으로 한다. <개정 2019.11.26>', 3297);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5723, '③ 환경부장관은 제1항에 따른 과징금을 부과하기 위하여 필요한 경우에는 다음 각 호의 사항을 적은 문서로 관할 세무서의 장에게 과세정보 제공을 요청할 수 있다. <개정 2019.11.26>', 3297);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5724, '④ 제1항에 따른 과징금을 부과함에 있어 위반행위의 횟수, 해당 사업장의 매출액 범주 등에 따른 부과기준은 대통령령으로 정한다. <개정 2019.11.26>', 3297);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5725, '⑤ 환경부장관은 제1항에 따른 과징금을 산출함에 있어 행위자가 동일한 위반행위로 제15조의2제1항 각 호에 따른 벌금, 과징금, 과태료 또는 배출부과금을 부과 받은 경우 그 액수에 상당하는 금액을 과징금에서 뺀다. <개정 2019.11.26>', 3297);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5726, '⑥ 환경부장관은 제1항의 위반 사실을 알게 된 즉시 이를 환경부장관에게 신고하고 시정한 자에 대하여 대통령령으로 정하는 바에 따라 과징금의 전부 또는 일부를 감면할 수 있다. <신설 2019.11.26>', 3297);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5727, '⑦ 환경부장관은 제1항에 따라 과징금의 부과처분을 받은 자가 과징금을 기한까지 내지 아니하면 국세 체납처분의 예에 따라 징수한다. <개정 2019.11.26>', 3297);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5728, '⑧ 제1항에 따른 과징금은 「환경정책기본법」에 따른 환경개선특별회계의 세입으로 한다. <개정 2011.7.21, 2019.11.26>', 3297);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5729, '① 환경부장관은 불법배출시설의 소유자 또는 점유자에게 해당 시설의 사용중지, 철거 또는 폐쇄를 명할 수 있다.', 3298);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5730, '② 불법배출시설이 제2조제4호바목부터 아목까지의 영업을 하는 시설에 해당하는 경우에는 그 불법배출시설이 다음 각 호의 어느 하나에 해당하는 지역에 있는 경우에만 제1항을 적용한다. <개정 2013.7.30, 2014.6.3, 2017.1.17, 2020.2.18>', 3298);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5731, '③ 환경부장관은 제1항에 따른 불법배출시설의 소유자 또는 점유자가 철거명령을 받고도 이를 이행하지 아니하면 「행정대집행법」에서 정하는 바에 따라 대집행(代執行)하고 그 비용을 소유자 또는 점유자로부터 징수할 수 있다.', 3298);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5732, '④ 환경부장관은 제1항에 따라 불법배출시설에 대하여 철거명령을 하는 경우에는 해당 불법배출시설 또는 그 사업장에 대통령령으로 정하는 표지판을 설치하여야 한다.', 3298);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5733, '① 사업자가 불법배출시설을 양도하거나 사망한 경우 또는 법인인 사업자가 합병한 경우에는 종전의 사업자(이하 "양도인등"이라 한다)에 대하여 제13조에 따라 한 행정처분의 효과는 그 처분기간이 끝난 날부터 1년간 양수인, 상속인 또는 합병 후 존속하는 법인이나 합병으로 새로 설립되는 법인(이하 "양수인등"이라 한다)에 승계되며, 행정처분의 절차가 진행 중인 때에는 양수인등에게 행정처분의 절차를 계속 진행할 수 있다. 다만, 양수인 또는 합병 후 존속하는 법인이나 합병으로 새로 설립되는 법인이 그 처분이나 위반의 사실을 양수 또는 합병한 때에 알지 못하였음을 증명하는 경우에는 그러하지 아니한다.', 3299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5734, '② 양수인등이 양수ㆍ상속 또는 합병할 때에는 제13조에 따른 행정처분의 절차가 진행 중인지 및 행정처분을 받은 이력이 있는지 여부를 양도인등에게 확인하여야 하며, 환경부장관은 양수인등이 그 확인을 요청하는 경우 대통령령으로 정하는 바에 따라 행정처분의 종류, 사유, 진행 중인 행정처분의 절차 등에 관한 서류를 발급할 수 있다.', 3299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5735, '① 이 법과 다음 각 호의 법률에서 규정하는 위반행위에 대한 단속 및 예방을 위하여 환경부 및 그 소속 기관에 환경감시관을 둔다. <개정 2019.11.26, 2021.6.15, 2022.12.31, 2024.3.19, 2025.3.25>', 3301);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5736, '② 환경감시관은 제1항에 따른 위반행위의 단속 및 예방을 위하여 필요한 경우 지방자치단체의 장에게 자료를 요청할 수 있다. 이 경우 자료의 제출을 요청받은 지방자치단체의 장은 특별한 사유가 없으면 요청받은 자료를 제출하여야 한다. <개정 2019.11.26>', 3301);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5737, '③ 제1항에 따른 환경감시관은 환경부 및 그 소속 기관에서 환경감시업무에 종사하는 공무원 중에서 임명하되, 그 자격, 임면(任免), 직무 범위 등에 관한 사항은 대통령령으로 정한다.', 3301);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5738, '④ 환경감시관은 제1항에 따른 위반행위의 단속 및 예방을 위하여 필요한 경우에는 시설 또는 사업장 등에 출입하여 조사할 수 있다. 이 경우 출입ㆍ조사를 하는 공무원은 그 권한을 표시하는 증표를 지니고 이를 관계 기관에 보여주어야 한다. <신설 2013.5.22, 2019.11.26>', 3301);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5739, '① 환경부장관은 제12조에 따른 과징금의 부과 또는 제13조에 따른 행정처분을 하기 위하여 관계 공무원에게 불법배출시설 또는 사업장 등에 출입하여 오염물질을 채취하거나 관계 서류ㆍ시설ㆍ장비 등을 검사하게 할 수 있다.', 3303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5740, '② 환경부장관은 제1항에 따라 오염물질을 채취하였을 때에는 대통령령으로 정하는 검사기관에 그 오염도의 검사를 의뢰할 수 있다.', 3303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5741, '③ 제1항에 따라 출입ㆍ검사를 하는 공무원은 그 권한을 표시하는 증표를 지니고 이를 관계인에게 보여주어야 한다.', 3303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5742, '① 「환경범죄 등의 단속 및 가중처벌에 관한 법률」(이하 "법"이라 한다) 제12조제1항 각 호 외의 부분 단서에서 "대통령령으로 정하는 경우"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다.', 3309);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5743, '② 법 제12조제4항에 따른 과징금의 부과기준은 별표 1과 같다.', 3309);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5744, '③ 법 제12조제6항에 따라 환경부장관은 같은 조 제1항 각 호의 위반 사실을 알게 된 즉시 이를 신고하고 시정한 자에 대해서는 다음 각 호의 구분에 따라 과징금을 감면한다.', 3309);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5745, '④ 제3항 각 호의 구분에 따른 과징금 감면금액의 세부 기준은 환경부장관이 정하여 고시한다.', 3309);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5746, '① 환경부장관은 법 제12조에 따라 과징금을 부과하려면 위반행위의 종류와 해당 과징금의 금액을 분명하게 밝혀 이를 납부할 것을 서면으로 통지해야 한다.', 3312);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5747, '② 제1항에 따라 통지를 받은 자는 통지를 받은 날부터 60일 이내에 과징금을 환경부장관이 정하는 수납기관에 내야 한다. <개정 2023.12.12>', 3312);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5748, '③ 제2항에 따라 과징금을 받은 수납기관은 그 납부자에게 영수증을 발급해야 한다.', 3312);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5749, '④ 과징금 수납기관이 제2항에 따라 과징금을 수납한 때에는 지체 없이 그 사실을 환경부장관에게 통보해야 한다.', 3312);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5750, '⑤ 제1항부터 제4항까지에서 규정한 사항 외에 과징금의 부과 및 납부에 필요한 세부 사항은 환경부장관이 정하여 고시한다.', 3312);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5751, '① 양수인, 상속인 또는 합병 후 존속하는 법인이나 합병으로 새로 설립되는 법인이 법 제14조제2항에 따라 종전 사업자의 행정처분 절차 진행 여부 및 행정처분 이력 유무(이하 "종전사업자의 행정처분이력등"이라 한다)에 대한 확인을 환경부장관에게 요청하려면 별지 제1호서식의 행정처분 이력 등 확인 요청서를 제출해야 한다.', 3316);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5752, '② 제1항에 따라 요청서를 받은 환경부장관은 요청일부터 5일 이내에 종전사업자의 행정처분이력등을 확인하여 별지 제2호서식의 행정처분 이력 등 확인서를 요청인에게 발급해야 한다.', 3316);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5753, '① 삭제 <2013.10.22>', 3317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5754, '② 법 제15조에 따라 범죄의 신고를 받은 수사기관, 환경부장관 및 지방환경관서의 장은 그 사건의 개요를 관할 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장(자치구의 구청장을 말한다)에게 통지하여야 한다.', 3317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5755, '③ 법 제15조에 따라 범죄의 신고를 받거나 제2항에 따라 통지를 받은 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장(자치구의 구청장을 말한다)은 그 신고내용이 환경법위반행위에 해당된다고 인정하는 경우에는 예산의 범위에서 포상금을 지급할 수 있다. <개정 2013.10.22>', 3317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5756, '④ 제3항에 따른 포상금은 300만원의 범위에서 지급하며, 포상금의 금액ㆍ지급시기 및 지급절차 등에 관하여 필요한 사항은 환경부장관이 정하여 고시한다.', 3317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5757, '① 다음 각 호의 어느 하나에 해당하는 일반직공무원은 그 직위에 임용된 날부터 법 제15조의2제1항 각 호 외의 부분에 따른 환경감시관(이하 "환경감시관"이라 한다)에 임명된 것으로 본다. <개정 2020.11.10>', 3318);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5758, '② 제1항의 경우 환경부 또는 지방환경관서에서 근무한 경력이 1년 미만인 공무원은 그 근무경력이 1년이 되는 날부터 환경감시관에 임명된 것으로 본다.', 3318);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5759, '③ 환경부장관 또는 지방환경관서의 장은 법과 법 제15조의2제1항 각 호의 법률에서 규정하는 위반행위(이하 "환경관계법령위반행위"라 한다)의 단속 및 예방을 위하여 한시적으로 전담반을 구성할 특별한 필요가 있을 때에는 그 환경관계법령위반행위와 관련된 업무를 담당하고 있는 공무원을 환경감시관으로 임명할 수 있다. <개정 2020.11.10>', 3318);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5760, '① 제11조에 따라 환경감시관으로 임명된 사람이 다음 각 호의 어느 하나에 해당하는 경우 환경감시관 임명이 해제된 것으로 본다.', 3319);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5761, '② 환경부장관 또는 지방환경관서의 장은 제11조에 따라 환경감시관으로 임명된 사람이 환경관계법령위반행위의 단속 및 예방 업무와 관련하여 징계처분을 받거나 「국가공무원법」 제61조ㆍ제65조 또는 제66조를 위반하여 징계처분을 받은 경우에는 그 환경감시관의 임명을 지체 없이 해제해야 한다. <개정 2020.11.10>', 3319);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5762, '③ 환경부장관 또는 지방환경관서의 장은 환경관계법령위반행위의 단속 및 예방 업무와 관련하여 징계처분을 받거나 「국가공무원법」 제61조ㆍ제65조 또는 제66조를 위반하여 징계처분을 받은 사람에 대해서는 그 처분을 받은 날부터 다음 각 호의 구분에 따른 기간 동안 환경감시관으로 임명해서는 안 된다. <개정 2020.11.10>', 3319);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5763, null, 3320);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5764, '① 환경부장관 또는 지방환경관서의 장은 환경감시관의 신분을 표시하는 증표를 발급하여야 한다.', 3322);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5765, '② 제1항에 따른 증표의 발급에 필요한 사항은 환경부장관이 정한다.', 3322);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5766, null, 3323);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5767, '① 환경부장관은 법 제19조에 따라 다음 각 호의 권한을 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ도지사ㆍ특별자치도지사(이하 "시ㆍ도지사"라 한다)에게 위임한다. 다만, 제2항에 해당하는 권한 및 법 제2조제3호사목에 따른 배출시설에 대한 다음 각 호의 권한은 제외한다. <개정 2020.11.10, 2025.9.23>', 3324);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5768, '② 환경부장관은 다음 각 호의 어느 하나에 해당하는 자에 대한 제1항 각 호의 권한(법 제2조제3호사목에 따른 배출시설에 대한 권한은 제외한다)을 지방환경관서의 장에게 위임한다. <개정 2020.11.10, 2025.8.5, 2025.9.23>', 3324);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5769, null, 3327);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5770, '① 제2조제4호가목부터 다목까지의 아동학대범죄를 범한 사람이 아동을 살해한 때에는 사형, 무기 또는 7년 이상의 징역에 처한다.', 3329);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5771, '② 제2조제4호가목부터 다목까지의 아동학대범죄를 범한 사람이 아동을 사망에 이르게 한 때에는 무기 또는 5년 이상의 징역에 처한다.', 3329);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5772, '① 법원은 아동학대행위자에 대하여 유죄판결(선고유예는 제외한다)을 선고하면서 200시간의 범위에서 재범예방에 필요한 수강명령(「보호관찰 등에 관한 법률」에 따른 수강명령을 말한다. 이하 같다) 또는 아동학대 치료프로그램의 이수명령(이하 "이수명령"이라 한다)을 병과할 수 있다.', 3333);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5773, '② 아동학대행위자에 대하여 제1항의 수강명령은 형의 집행을 유예할 경우에 그 집행유예기간 내에서 병과하고, 이수명령은 벌금형 또는 징역형의 실형(實刑)을 선고할 경우에 병과한다.', 3333);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5774, '③ 법원이 아동학대행위자에 대하여 형의 집행을 유예하는 경우에는 제1항에 따른 수강명령 외에 그 집행유예기간 내에서 보호관찰 또는 사회봉사 중 하나 이상의 처분을 병과할 수 있다.', 3333);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5775, '④ 제1항에 따른 수강명령 또는 이수명령은 형의 집행을 유예할 경우에는 그 집행유예기간 내에, 벌금형을 선고할 경우에는 형 확정일로부터 6개월 이내에, 징역형의 실형을 선고할 경우에는 형기 내에 각각 집행한다.', 3333);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5776, '⑤ 제1항에 따른 수강명령 또는 이수명령이 벌금형 또는 형의 집행유예와 병과된 경우에는 보호관찰소의 장이 집행하고, 징역형의 실형과 병과된 경우에는 교정시설의 장이 집행한다. 다만, 징역형의 실형과 병과된 이수명령을 모두 이행하기 전에 석방 또는 가석방되거나 미결구금일수 산입 등의 사유로 형을 집행할 수 없게 된 경우에는 보호관찰소의 장이 남은 이수명령을 집행한다.', 3333);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5777, '⑥ 제1항에 따른 수강명령 또는 이수명령은 다음 각 호의 내용으로 한다.', 3333);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5778, '⑦ 형벌과 병과하는 보호관찰, 사회봉사, 수강명령 및 이수명령에 관하여 이 법에서 규정한 사항 외에는 「보호관찰 등에 관한 법률」을 준용한다.', 3333);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5779, '① 아동학대행위자가 제5조 또는 제6조의 범죄를 저지른 때에는 검사는 그 사건의 아동학대행위자가 피해아동의 친권자나 후견인인 경우에 법원에 「민법」 제924조의 친권상실의 선고 또는 같은 법 제940조의 후견인의 변경 심판을 청구하여야 한다. 다만, 친권상실의 선고 또는 후견인의 변경 심판을 하여서는 아니 될 특별한 사정이 있는 경우에는 그러하지 아니하다.', 3334);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5780, '② 검사가 제1항에 따른 청구를 하지 아니한 때에는 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ도지사ㆍ특별자치도지사(이하 "시ㆍ도지사"라 한다) 또는 시장ㆍ군수ㆍ구청장(자치구의 구청장을 말한다. 이하 같다)은 검사에게 제1항의 청구를 하도록 요청할 수 있다. 이 경우 청구를 요청받은 검사는 요청받은 날부터 30일 내에 그 처리 결과를 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 통보하여야 한다. <개정 2020.3.24>', 3334);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5781, '③ 제2항 후단에 따라 처리 결과를 통보받은 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 그 처리 결과에 대하여 이의가 있을 경우 통보받은 날부터 30일 내에 직접 법원에 제1항의 청구를 할 수 있다. <개정 2020.3.24>', 3334);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5782, '① 누구든지 아동학대범죄를 알게 된 경우나 그 의심이 있는 경우에는 특별시ㆍ광역시ㆍ특별자치시ㆍ도ㆍ특별자치도(이하 "시ㆍ도"라 한다), 시ㆍ군ㆍ구(자치구를 말한다. 이하 같다) 또는 수사기관에 신고할 수 있다. <개정 2020.3.24>', 3335);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5783, '② 다음 각 호의 어느 하나에 해당하는 사람이 직무를 수행하면서 아동학대범죄를 알게 된 경우나 그 의심이 있는 경우에는 시ㆍ도, 시ㆍ군ㆍ구 또는 수사기관에 즉시 신고하여야 한다. <개정 2016.5.29, 2019.1.15, 2020.3.24, 2022.12.27, 2023.7.18>', 3335);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5784, '③ 누구든지 제1항 및 제2항에 따른 신고인의 인적 사항 또는 신고인임을 미루어 알 수 있는 사실을 다른 사람에게 알려주거나 공개 또는 보도하여서는 아니 된다.', 3335);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5785, '④ 제2항에 따른 신고가 있는 경우 시ㆍ도, 시ㆍ군ㆍ구 또는 수사기관은 정당한 사유가 없으면 즉시 조사 또는 수사에 착수하여야 한다. <신설 2021.1.26>', 3335);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5786, '① 피해아동 또는 그 법정대리인은 아동학대행위자를 고소할 수 있다. 피해아동의 법정대리인이 아동학대행위자인 경우 또는 아동학대행위자와 공동으로 아동학대범죄를 범한 경우에는 피해아동의 친족이 고소할 수 있다.', 3338);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5787, '② 피해아동은 「형사소송법」 제224조에도 불구하고 아동학대행위자가 자기 또는 배우자의 직계존속인 경우에도 고소할 수 있다. 법정대리인이 고소하는 경우에도 또한 같다.', 3338);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5788, '③ 피해아동에게 고소할 법정대리인이나 친족이 없는 경우에 이해관계인이 신청하면 검사는 10일 이내에 고소할 수 있는 사람을 지정하여야 한다.', 3338);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5789, '① 아동학대범죄 신고를 접수한 사법경찰관리나 「아동복지법」 제22조제4항에 따른 아동학대전담공무원(이하 "아동학대전담공무원"이라 한다)은 지체 없이 아동학대범죄의 현장에 출동하여야 한다. 이 경우 수사기관의 장이나 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 서로 동행하여 줄 것을 요청할 수 있으며, 그 요청을 받은 수사기관의 장이나 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 정당한 사유가 없으면 사법경찰관리나 아동학대전담공무원이 아동학대범죄 현장에 동행하도록 조치하여야 한다. <개정 2020.3.24>', 3339);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5790, '② 아동학대범죄 신고를 접수한 사법경찰관리나 아동학대전담공무원은 아동학대범죄가 행하여지고 있는 것으로 신고된 현장 또는 피해아동을 보호하기 위하여 필요한 장소에 출입하여 아동 또는 아동학대행위자 등 관계인에 대하여 조사를 하거나 질문을 할 수 있다. 다만, 아동학대전담공무원은 다음 각 호를 위한 범위에서만 아동학대행위자 등 관계인에 대하여 조사 또는 질문을 할 수 있다. <개정 2020.3.24, 2021.1.26>', 3339);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5791, '③ 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 제1항에 따른 현장출동 시 아동보호 및 사례관리를 위하여 필요한 경우 아동보호전문기관의 장에게 아동보호전문기관의 직원이 동행할 것을 요청할 수 있다. 이 경우 아동보호전문기관의 직원은 피해아동의 보호 및 사례관리를 위한 범위에서 아동학대전담공무원의 조사에 참여할 수 있다. <신설 2020.3.24>', 3339);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5792, '④ 제2항 및 제3항에 따라 출입이나 조사를 하는 사법경찰관리, 아동학대전담공무원 또는 아동보호전문기관의 직원은 그 권한을 표시하는 증표를 지니고 이를 관계인에게 내보여야 한다. <개정 2020.3.24>', 3339);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5793, '⑤ 제2항에 따라 조사 또는 질문을 하는 사법경찰관리 또는 아동학대전담공무원은 피해아동, 아동학대범죄신고자등, 목격자 등이 자유롭게 진술할 수 있도록 아동학대행위자로부터 분리된 곳에서 조사하는 등 필요한 조치를 하여야 한다. <신설 2021.1.26>', 3339);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5794, '⑥ 누구든지 제1항부터 제3항까지의 규정에 따라 현장에 출동한 사법경찰관리, 아동학대전담공무원 또는 아동보호전문기관의 직원이 제2항 및 제3항에 따른 업무를 수행할 때에 폭행ㆍ협박이나 현장조사를 거부하는 등 그 업무 수행을 방해하는 행위를 하여서는 아니 된다. <개정 2020.3.24, 2021.1.26>', 3339);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5795, '⑦ 제1항에 따른 현장출동이 동행하여 이루어지지 아니한 경우 수사기관의 장이나 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 현장출동에 따른 조사 등의 결과를 서로에게 통지하여야 한다. <신설 2021.1.26>', 3339);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5796, '① 아동학대전담공무원은 피해아동의 보호 및 사례관리를 위한 조사를 할 수 있다. 이 경우 아동학대전담공무원은 아동학대행위자 및 관계인에 대하여 출석ㆍ진술 및 자료제출을 요구할 수 있으며, 아동학대행위자 및 관계인은 정당한 사유가 없으면 이에 따라야 한다. <개정 2021.1.26>', 3340);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5797, '② 제1항에 관하여는 「행정조사기본법」 제4조, 제5조, 제9조, 제10조, 제17조, 제21조를 준용한다. 이 경우 "행정조사"는 "제1항에 따른 아동학대전담공무원의 조사"로, "행정기관"은 "시ㆍ도 또는 시ㆍ군ㆍ구"로, "조사대상자"는 "아동학대행위자 및 관계인"으로 본다.', 3340);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5798, '① 제11조제1항에 따라 현장에 출동하거나 아동학대범죄 현장을 발견한 경우 또는 학대현장 이외의 장소에서 학대피해가 확인되고 재학대의 위험이 급박ㆍ현저한 경우, 사법경찰관리 또는 아동학대전담공무원은 피해아동, 피해아동의 형제자매인 아동 및 피해아동과 동거하는 아동(이하 "피해아동등"이라 한다)의 보호를 위하여 즉시 다음 각 호의 조치(이하 "응급조치"라 한다)를 하여야 한다. 이 경우 제3호의 조치를 하는 때에는 피해아동등의 이익을 최우선으로 고려하여야 하며, 피해아동등을 보호하여야 할 필요가 있는 등 특별한 사정이 있는 경우를 제외하고는 피해아동등의 의사를 존중하여야 한다. <개정 2016.5.29, 2020.3.24>', 3341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5799, '② 사법경찰관리나 아동학대전담공무원은 제1항제3호 및 제4호 규정에 따라 피해아동등을 분리ㆍ인도하여 보호하는 경우 지체 없이 피해아동등을 인도받은 보호시설ㆍ의료시설을 관할하는 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 그 사실을 통보하여야 한다. <개정 2016.5.29, 2020.3.24>', 3341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5800, '③ 제1항제2호부터 제4호까지의 규정에 따른 응급조치는 72시간을 넘을 수 없다. 다만, 본문의 기간에 공휴일이나 토요일이 포함되는 경우로서 피해아동등의 보호를 위하여 필요하다고 인정되는 경우에는 48시간의 범위에서 그 기간을 연장할 수 있다. <개정 2021.1.26>', 3341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5801, '④ 제3항에도 불구하고 검사가 제15조제2항에 따라 임시조치를 법원에 청구한 경우에는 법원의 임시조치 결정 시까지 응급조치 기간이 연장된다. <신설 2021.1.26>', 3341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5802, '⑤ 사법경찰관리 또는 아동학대전담공무원이 제1항에 따라 응급조치를 한 경우에는 즉시 응급조치결과보고서를 작성하여야 한다. 이 경우 사법경찰관리가 응급조치를 한 경우에는 관할 경찰관서의 장이 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게, 아동학대전담공무원이 응급조치를 한 경우에는 소속 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장이 관할 경찰관서의 장에게 작성된 응급조치결과보고서를 지체 없이 송부하여야 한다. <개정 2020.3.24, 2021.1.26>', 3341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5803, '⑥ 제5항에 따른 응급조치결과보고서에는 피해사실의 요지, 응급조치가 필요한 사유, 응급조치의 내용 등을 기재하여야 한다. <개정 2021.1.26>', 3341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5804, '⑦ 누구든지 아동학대전담공무원이나 사법경찰관리가 제1항에 따른 업무를 수행할 때에 폭행ㆍ협박이나 응급조치를 저지하는 등 그 업무 수행을 방해하는 행위를 하여서는 아니 된다. <개정 2020.3.24, 2021.1.26>', 3341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5805, '⑧ 사법경찰관리는 제1항제1호 또는 제2호의 조치를 위하여 다른 사람의 토지ㆍ건물ㆍ배 또는 차에 출입할 수 있다. <신설 2021.1.26>', 3341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5806, '① 사법경찰관은 제12조제1항에 따른 응급조치에도 불구하고 아동학대범죄가 재발될 우려가 있고, 긴급을 요하여 제19조제1항에 따른 법원의 임시조치 결정을 받을 수 없을 때에는 직권이나 피해아동등, 그 법정대리인(아동학대행위자를 제외한다. 이하 같다), 변호사(제16조에 따른 변호사를 말한다. 제48조 및 제49조를 제외하고는 이하 같다), 시ㆍ도지사, 시장ㆍ군수ㆍ구청장 또는 아동보호전문기관의 장의 신청에 따라 제19조제1항제1호부터 제3호까지의 어느 하나에 해당하는 조치를 할 수 있다. <개정 2020.3.24>', 3342);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5807, '② 사법경찰관은 제1항에 따른 조치(이하 "긴급임시조치"라 한다)를 한 경우에는 즉시 긴급임시조치결정서를 작성하여야 하고, 그 내용을 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 지체 없이 통지하여야 한다. <개정 2020.3.24>', 3342);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5808, '③ 제2항에 따른 긴급임시조치결정서에는 범죄사실의 요지, 긴급임시조치가 필요한 사유, 긴급임시조치의 내용 등을 기재하여야 한다.', 3342);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5809, '① 검사는 아동학대범죄가 재발될 우려가 있다고 인정하는 경우에는 직권으로 또는 사법경찰관이나 보호관찰관의 신청에 따라 법원에 제19조제1항 각 호의 임시조치를 청구할 수 있다.', 3343);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5810, '② 피해아동등, 그 법정대리인, 변호사, 시ㆍ도지사, 시장ㆍ군수ㆍ구청장 또는 아동보호전문기관의 장은 검사 또는 사법경찰관에게 제1항에 따른 임시조치의 청구 또는 그 신청을 요청하거나 이에 관하여 의견을 진술할 수 있다. <개정 2020.3.24>', 3343);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5811, '③ 제2항에 따른 요청을 받은 사법경찰관은 제1항에 따른 임시조치를 신청하지 아니하는 경우에는 검사 및 임시조치를 요청한 자에게 그 사유를 통지하여야 한다. <개정 2020.3.24>', 3343);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5812, '① 사법경찰관이 제12조제1항제2호부터 제4호까지의 규정에 따른 응급조치 또는 제13조제1항에 따른 긴급임시조치를 하였거나 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장으로부터 제12조제1항제2호부터 제4호까지의 규정에 따른 응급조치가 행하여졌다는 통지를 받은 때에는 지체 없이 검사에게 제19조에 따른 임시조치의 청구를 신청하여야 한다. <개정 2020.3.24>', 3344);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5813, '② 제1항의 신청을 받은 검사는 임시조치를 청구하는 때에는 응급조치가 있었던 때부터 72시간(제12조제3항 단서에 따라 응급조치 기간이 연장된 경우에는 그 기간을 말한다) 이내에, 긴급임시조치가 있었던 때부터 48시간 이내에 하여야 한다. 이 경우 제12조제5항에 따라 작성된 응급조치결과보고서 및 제13조제2항에 따라 작성된 긴급임시조치결정서를 첨부하여야 한다. <개정 2021.1.26>', 3344);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5814, '③ 사법경찰관은 검사가 제2항에 따라 임시조치를 청구하지 아니하거나 법원이 임시조치의 결정을 하지 아니한 때에는 즉시 그 긴급임시조치를 취소하여야 한다.', 3344);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5815, '① 아동학대범죄의 피해아동 및 그 법정대리인은 형사 및 아동보호 절차상 입을 수 있는 피해를 방지하고 법률적 조력을 보장하기 위하여 변호사를 선임할 수 있다.', 3345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5816, '② 제1항에 따른 변호사는 검사 또는 사법경찰관의 피해아동 및 그 법정대리인에 대한 조사에 참여하여 의견을 진술할 수 있다. 다만, 조사 도중에는 검사 또는 사법경찰관의 승인을 받아 의견을 진술할 수 있다.', 3345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5817, '③ 제1항에 따른 변호사는 피의자에 대한 구속 전 피의자심문, 증거보전절차, 공판준비기일 및 공판절차에 출석하여 의견을 진술할 수 있다. 이 경우 필요한 절차에 관한 구체적 사항은 대법원규칙으로 정한다.', 3345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5818, '④ 제1항에 따른 변호사는 증거보전 후 관계 서류나 증거물, 소송계속 중의 관계 서류나 증거물을 열람하거나 등사할 수 있다.', 3345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5819, '⑤ 제1항에 따른 변호사는 형사 및 아동보호 절차에서 피해아동 및 그 법정대리인의 대리가 허용될 수 있는 모든 소송행위에 대한 포괄적인 대리권을 가진다.', 3345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5820, '⑥ 검사는 피해아동에게 변호사가 없는 경우 형사 및 아동보호 절차에서 피해아동의 권익을 보호하기 위하여 국선변호사를 선정하여야 한다.', 3345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5821, '① 아동학대범죄의 조사ㆍ심리에 관하여는 「성폭력범죄의 처벌 등에 관한 특례법」 제29조부터 제32조까지, 제34조부터 제41조까지 및 「아동ㆍ청소년의 성보호에 관한 법률」 제29조를 각각 준용한다. 이 경우 "성폭력" 또는 "아동ㆍ청소년대상 성범죄"는 "아동학대범죄"로, "피해자"는 "피해아동"으로 본다. <개정 2020.3.24>', 3346);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5822, '② 아동학대범죄사건의 형사 및 아동보호 절차에서 참고인이나 증인이 13세 미만의 아동이거나 신체적인 또는 정신적인 장애로 의사소통이나 의사표현에 어려움이 있는 경우 「성폭력범죄의 처벌 등에 관한 특례법」 제36조부터 제39조까지를 준용한다. 이 경우 "성폭력범죄"는 "아동학대범죄"로, "피해자"는 "참고인이나 증인"으로 본다. <신설 2020.3.24>', 3346);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5823, '① 검사는 아동학대범죄사건의 증인이 피고인 또는 그 밖의 사람으로부터 생명ㆍ신체에 해를 입거나 입을 염려가 있다고 인정될 때에는 관할 경찰서장에게 증인의 신변안전을 위하여 필요한 조치를 할 것을 요청하여야 한다.', 3347);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5824, '② 증인은 검사에게 제1항의 조치를 하도록 청구할 수 있다.', 3347);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5825, '③ 재판장은 검사에게 제1항의 조치를 하도록 요청할 수 있다.', 3347);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5826, '④ 제1항의 요청을 받은 관할 경찰서장은 즉시 증인의 신변안전을 위하여 필요한 조치를 하고 그 사실을 검사에게 통보하여야 한다.', 3347);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5827, '① 아동보호사건의 관할은 아동학대행위자의 행위지, 거주지 또는 현재지를 관할하는 가정법원으로 한다. 다만, 가정법원이 설치되지 아니한 지역에서는 해당 지역의 지방법원(지원을 포함한다. 이하 같다)으로 한다.', 3348);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5828, '② 아동보호사건의 심리와 결정은 단독판사(이하 "판사"라 한다)가 한다.', 3348);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5829, '① 판사는 아동학대범죄의 원활한 조사ㆍ심리 또는 피해아동등의 보호를 위하여 필요하다고 인정하는 경우에는 결정으로 아동학대행위자에게 다음 각 호의 어느 하나에 해당하는 조치(이하 "임시조치"라 한다)를 할 수 있다. <개정 2020.3.24>', 3349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5830, '② 제1항 각 호의 처분은 병과할 수 있다.', 3349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5831, '③ 판사는 피해아동등에 대하여 제12조제1항제2호부터 제4호까지의 규정에 따른 응급조치가 행하여진 경우에는 임시조치가 청구된 때로부터 24시간 이내에 임시조치 여부를 결정하여야 한다. <개정 2020.3.24>', 3349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5832, '④ 제1항 각 호의 규정에 따른 임시조치기간은 2개월을 초과할 수 없다. 다만, 피해아동등의 보호를 위하여 그 기간을 연장할 필요가 있다고 인정하는 경우에는 결정으로 제1항제1호부터 제3호까지의 규정에 따른 임시조치는 두 차례만, 같은 항 제4호부터 제7호까지의 규정에 따른 임시조치는 한 차례만 각 기간의 범위에서 연장할 수 있다. <개정 2020.3.24>', 3349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5833, '⑤ 제1항제6호에 따라 위탁을 하는 경우에는 의료기관 등의 장에게 아동학대행위자를 보호하는 데에 필요한 사항을 부과할 수 있다.', 3349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5834, '⑥ 제1항제6호에 따라 민간이 운영하는 의료기관 등에 아동학대행위자를 위탁하려는 경우에는 제5항에 따라 부과할 사항을 그 의료기관 등의 장에게 미리 고지하고 동의를 받아야 한다.', 3349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5835, '⑦ 법원은 제1항에 따른 임시조치를 결정한 경우에는 검사, 피해아동등, 그 법정대리인, 변호사, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장 및 피해아동등을 보호하고 있는 기관의 장에게 통지하여야 한다. <개정 2020.3.24>', 3349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5836, '⑧ 제1항제5호에 따른 상담 및 교육을 행한 아동보호전문기관의 장 등은 그 결과보고서를 판사와 검사에게 제출하여야 한다.', 3349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5837, '⑨ 제1항 각 호의 위탁 대상이 되는 상담소, 의료기관, 요양시설 등의 기준과 위탁의 절차 및 제7항에 따른 통지의 절차 등 그 밖에 필요한 사항은 대법원규칙으로 정한다.', 3349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5838, '① 판사는 제19조제1항 각 호에 규정된 임시조치의 결정을 한 경우에는 가정보호사건조사관, 법원공무원, 사법경찰관리 또는 구치소 소속 교정직공무원으로 하여금 집행하게 할 수 있다.', 3351);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5839, '② 제1항에 따른 집행담당자는 아동학대행위자의 임시조치 이행상황에 대하여 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 통보하여야 한다. <신설 2020.3.24>', 3351);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5840, '③ 피해아동등 또는 가정구성원은 제19조제1항제1호 및 제2호의 임시조치 후 주거, 학교 또는 보호시설 등을 옮긴 경우에는 관할 법원에 임시조치 결정의 변경을 신청할 수 있다. <개정 2020.3.24>', 3351);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5841, '④ 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 아동학대행위자의 임시조치 이행을 관리하고, 아동학대행위자가 임시조치 결정을 이행하지 않거나 그 집행에 따르지 아니하는 경우 적절한 조치를 하여야 한다. <신설 2020.3.24>', 3351);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5842, '① 아동학대행위자, 그 법정대리인이나 보조인은 제19조제1항 각 호에 따른 임시조치 결정의 취소 또는 그 종류의 변경을 관할 법원에 신청할 수 있다.', 3352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5843, '② 판사는 정당한 이유가 있다고 인정하는 경우에는 직권 또는 제1항의 신청에 따라 결정으로 해당 임시조치를 취소하거나 그 종류를 변경할 수 있다.', 3352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5844, '③ 판사는 임시조치를 받은 아동학대행위자가 제19조제1항제5호 및 제6호의 임시조치 결정을 이행하지 아니하거나 그 집행에 따르지 아니하면 직권 또는 검사, 시ㆍ도지사, 시장ㆍ군수ㆍ구청장, 피해아동등, 그 법정대리인이나 변호사 또는 제19조제1항 각 호의 위탁 대상이 되는 기관의 장의 청구에 따라 결정으로 그 임시조치를 변경할 수 있다. <개정 2016.5.29, 2020.3.24>', 3352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5845, '① 판사는 제19조제1항제4호의 임시조치로 인하여 피해아동등에게 친권을 행사하거나 후견인의 임무를 수행할 사람이 없는 경우 그 임시조치의 기간 동안 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장, 아동권리보장원의 장, 아동보호전문기관의 장 및 가정위탁지원센터의 장으로 하여금 임시로 후견인의 임무를 수행하게 하거나 그 임무를 수행할 사람을 선임하여야 한다. <개정 2016.5.29, 2019.1.15, 2020.3.24>', 3353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5846, '② 제1항의 경우 판사는 피해아동등의 이익을 최우선으로 고려하고 그 의견을 존중하여야 하며, 피해아동등, 변호사, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장, 아동권리보장원의 장, 아동보호전문기관의 장 및 가정위탁지원센터의 장 등 피해아동등을 보호하고 있는 사람은 그 선임에 관하여 의견을 제시할 수 있다. <개정 2016.5.29, 2019.1.15, 2020.3.24>', 3353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5847, '③ 법원이 제1항에 따른 조치를 한 경우에는 그 사실을 피해아동등, 변호사, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장, 아동권리보장원의 장, 아동보호전문기관의 장 및 가정위탁지원센터의 장 등 피해아동등을 보호하고 있는 사람에게 고지하여야 한다. <개정 2016.5.29, 2019.1.15, 2020.3.24>', 3353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5848, '④ 제1항에 따라 임시로 후견인의 임무를 수행하는 사람은 피해아동등이 소유한 재산의 보존 및 피해아동등의 보호를 위한 범위에서만 후견인의 임무를 수행할 수 있다. <개정 2020.3.24>', 3353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5849, '⑤ 임시로 후견인의 임무를 수행하는 사람에 대해서는 「민법」 제949조를 준용한다.', 3353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5850, '⑥ 임시로 후견인의 임무를 수행하는 사람에 대한 선임, 사임 및 변경의 절차 등에 필요한 사항은 대법원규칙으로 정한다.', 3353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5851, '① 검사는 아동학대범죄에 대하여 아동보호사건 송치, 공소제기 또는 기소유예 등의 처분을 결정하기 위하여 필요하다고 인정하면 아동학대행위자의 주거지 또는 검찰청 소재지를 관할하는 보호관찰소의 장에게 아동학대행위자의 경력, 생활환경, 양육능력이나 그 밖에 필요한 사항에 관한 조사를 요구할 수 있다.', 3355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5852, '② 제1항의 요구를 받은 보호관찰소의 장은 지체 없이 이를 조사하여 서면으로 해당 검사에게 통보하여야 하며, 조사를 위하여 필요한 경우에는 소속 보호관찰관에게 아동학대행위자 또는 관계인을 출석하게 하여 진술요구를 하는 등의 방법으로 필요한 사항을 조사하게 할 수 있다.', 3355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5853, '③ 제2항에 따른 조사를 할 때에는 미리 아동학대행위자 또는 관계인에게 조사의 취지를 설명하여야 하고, 그 인권을 존중하며, 직무상 비밀을 엄수하여야 한다.', 3355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5854, '④ 검사는 아동학대범죄에 관하여 필요한 경우 시ㆍ도지사, 시장ㆍ군수ㆍ구청장 또는 아동보호전문기관의 장에 대하여 제1항의 결정에 필요한 자료의 제출을 요구할 수 있다. <개정 2020.3.24>', 3355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5855, '⑤ 검사는 제1항의 결정을 할 때에는 보호관찰소의 장으로부터 통보받은 조사 결과 및 시ㆍ도지사, 시장ㆍ군수ㆍ구청장 또는 아동보호전문기관의 장으로부터 제출 받은 자료 등을 참고하여 피해아동 보호와 아동학대행위자의 교화ㆍ개선에 가장 적합한 결정을 하여야 한다. <개정 2020.3.24>', 3355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5856, null, 3356);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5857, '①검사는 아동학대범죄로서 제26조 각 호의 사유를 고려하여 제36조에 따른 보호처분을 하는 것이 적절하다고 인정하는 경우에는 아동보호사건으로 처리할 수 있다. <개정 2016.5.29>', 3357);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5858, '② 다음 각 호의 경우에는 제1항을 적용할 수 있다. <신설 2016.5.29>', 3357);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5859, '① 검사는 제27조에 따라 아동보호사건으로 처리하는 경우에는 그 사건을 제18조제1항에 따른 관할 법원(이하 "관할 법원"이라 한다)에 송치하여야 한다.', 3358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5860, '② 검사는 아동학대범죄와 그 외의 범죄가 경합(競合)하는 경우에는 아동학대범죄에 대한 사건만을 분리하여 관할 법원에 송치할 수 있다.', 3358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5861, '① 제28조 또는 제29조에 따른 송치결정이 있는 경우 아동학대행위자를 구금하고 있는 시설의 장은 검사의 이송지휘를 받은 때부터 관할 법원이 있는 시(특별시, 광역시, 특별자치시 및 「제주특별자치도 설치 및 국제자유도시 조성을 위한 특별법」 제10조제2항에 따른 행정시를 포함한다. 이하 같다)ㆍ군에서는 24시간 이내에, 그 밖의 시ㆍ군에서는 48시간 이내에 아동학대행위자를 관할 법원에 인도하여야 한다. 이 경우 법원은 아동학대행위자에 대하여 제19조에 따른 임시조치 여부를 결정하여야 한다. <개정 2015.7.24>', 3360);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5862, '② 제1항에 따른 인도와 결정은 「형사소송법」 제92조, 제203조 또는 제205조의 구속기간 내에 이루어져야 한다.', 3360);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5863, '③ 아동학대행위자에 대한 구속영장의 효력은 제1항 후단에 따라 임시조치 여부를 결정한 때에 상실된 것으로 본다.', 3360);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5864, '① 제28조 또는 제29조에 따라 사건을 아동보호사건으로 송치하는 경우에는 송치서를 보내야 한다.', 3361);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5865, '② 제1항의 송치서에는 아동학대행위자의 성명, 주소, 생년월일, 직업, 피해아동과의 관계 및 행위의 개요와 가정 상황을 적고 그 밖의 참고자료를 첨부하여야 한다.', 3361);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5866, '① 아동보호사건을 송치 받은 법원은 사건이 그 관할에 속하지 아니하거나 적정한 조사ㆍ심리를 위하여 필요하다고 인정하는 경우에는 결정으로 그 사건을 즉시 다른 관할 법원에 이송하여야 한다.', 3362);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5867, '② 법원은 제1항에 따른 이송결정을 한 경우에는 지체 없이 그 사유를 첨부하여 아동학대행위자와 피해아동, 그 법정대리인, 변호사 및 검사에게 통지하여야 한다.', 3362);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5868, '① 아동학대범죄의 공소시효는 「형사소송법」 제252조에도 불구하고 해당 아동학대범죄의 피해아동이 성년에 달한 날부터 진행한다.', 3364);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5869, '② 아동학대범죄에 대한 공소시효는 해당 아동보호사건이 법원에 송치된 때부터 시효 진행이 정지된다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그 때부터 진행된다.', 3364);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5870, '③ 공범 중 1명에 대한 제2항의 시효정지는 다른 공범자에게도 효력을 미친다.', 3364);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5871, '① 아동학대범죄의 수사 또는 아동보호사건의 조사ㆍ심리 및 그 집행을 담당하거나 이에 관여하는 공무원, 보조인, 진술조력인, 아동보호전문기관 직원과 그 기관장, 상담소 등에 근무하는 상담원과 그 기관장 및 제10조제2항 각 호에 규정된 사람(그 직에 있었던 사람을 포함한다)은 그 직무상 알게 된 비밀을 누설하여서는 아니 된다.', 3365);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5872, '② 신문의 편집인ㆍ발행인 또는 그 종사자, 방송사의 편집책임자, 그 기관장 또는 종사자, 그 밖의 출판물의 저작자와 발행인은 아동보호사건에 관련된 아동학대행위자, 피해아동, 고소인, 고발인 또는 신고인의 주소, 성명, 나이, 직업, 용모, 그 밖에 이들을 특정하여 파악할 수 있는 인적 사항이나 사진 등을 신문 등 출판물에 싣거나 방송매체를 통하여 방송할 수 없다.', 3365);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5873, '③ 피해아동의 교육 또는 보육을 담당하는 학교의 교직원 또는 보육교직원은 정당한 사유가 없으면 해당 아동의 취학, 진학, 전학 또는 입소(그 변경을 포함한다)의 사실을 아동학대행위자인 친권자를 포함하여 누구에게든지 누설하여서는 아니 된다.', 3365);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5874, '① 판사는 심리의 결과 보호처분이 필요하다고 인정하는 경우에는 결정으로 다음 각 호의 어느 하나에 해당하는 보호처분을 할 수 있다.', 3366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5875, '② 제1항 각 호의 처분은 병과할 수 있다.', 3366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5876, '③ 제1항제3호의 처분을 하는 경우에는 피해아동을 아동학대행위자가 아닌 다른 친권자나 친족 또는 아동복지시설 등으로 인도할 수 있다.', 3366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5877, '④ 판사가 제1항제3호의 보호처분을 하는 경우 보호처분의 기간 동안 임시로 후견인의 임무를 수행할 사람의 선임 등에 대하여는 제23조를 준용한다.', 3366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5878, '⑤ 법원은 제1항에 따라 보호처분의 결정을 한 경우에는 지체 없이 그 사실을 검사, 아동학대행위자, 피해아동, 법정대리인, 변호사, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장, 보호관찰관 및 보호처분을 위탁받아 하는 보호시설, 의료기관, 아동보호전문기관 또는 상담소 등(이하 "수탁기관"이라 한다)의 장에게 통지하여야 한다. 다만, 수탁기관이 국가나 지방자치단체가 운영하는 기관이 아닌 경우에는 그 기관의 장으로부터 수탁에 대한 동의를 받아야 한다. <개정 2020.3.24>', 3366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5879, '⑥ 제1항제4호부터 제8호까지의 규정에 따라 처분을 한 경우에는 법원은 아동학대행위자의 교정에 필요한 참고자료를 보호관찰관 또는 수탁기관의 장에게 보내야 한다.', 3366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5880, '⑦ 제1항제6호의 감호위탁기관은 아동학대행위자에 대하여 그 성행을 교정하기 위한 교육을 하여야 한다.', 3366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5881, '① 법원은 가정보호사건조사관, 법원공무원, 사법경찰관리, 보호관찰관 또는 수탁기관 소속 직원으로 하여금 보호처분의 결정을 집행하게 할 수 있다.', 3368);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5882, '② 제1항에 따른 집행담당자는 아동학대행위자의 보호처분 이행상황에 관하여 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 통보하여야 한다. <신설 2020.3.24>', 3368);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5883, '③ 보호처분의 집행에 관하여 이 법에서 정하지 아니한 사항에 대하여는 아동보호사건의 성질에 위배되지 아니하는 범위에서 「형사소송법」, 「보호관찰 등에 관한 법률」 및 「정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률」을 준용한다. <개정 2016.5.29, 2020.3.24>', 3368);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5884, '④ 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 아동학대행위자의 보호처분 이행을 관리하고, 아동학대행위자가 보호처분 결정을 이행하지 않거나 그 집행에 따르지 아니하는 경우 적절한 조치를 하여야 한다. <신설 2020.3.24>', 3368);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5885, '① 법원은 제36조제1항제4호부터 제8호까지의 규정에 따른 보호처분을 결정한 경우에는 보호관찰관 또는 수탁기관의 장에게 아동학대행위자에 관한 보고서 또는 의견서 제출을 요구할 수 있고, 그 집행에 대하여 필요한 지시를 할 수 있다.', 3369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5886, '② 보호관찰관 또는 수탁기관의 장은 제1항의 경우 외에도 아동학대행위자가 제36조제1항제4호부터 제8호까지의 규정에 따른 보호처분을 이행하지 아니하거나 그 집행에 따르지 아니하는 경우에는 보호처분의 이행 실태에 대한 보고서 또는 의견서를 법원에 제출하여야 한다.', 3369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5887, '① 법원은 보호처분이 진행되는 동안 필요하다고 인정하는 경우에는 직권 또는 검사, 시ㆍ도지사, 시장ㆍ군수ㆍ구청장, 보호관찰관 또는 수탁기관의 장의 청구에 의하여 결정으로 보호처분의 종류와 기간을 변경할 수 있다. <개정 2020.3.24>', 3370);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5888, '② 법원은 필요한 경우 제38조제1항에 따른 집행담당자로 하여금 집행상황을 보고하도록 할 수 있으며, 가정보호사건조사관으로 하여금 보호처분에 관한 집행상황에 대하여 조사하도록 할 수 있다. <신설 2020.3.24>', 3370);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5889, '③ 제1항에 따라 보호처분의 종류와 기간을 변경하는 경우 종전의 처분기간을 합산하여 제36조제1항제1호부터 제3호까지 및 제5호부터 제8호까지의 규정에 따른 보호처분의 기간은 2년을, 같은 항 제4호의 규정에 따른 사회봉사ㆍ수강명령의 시간은 400시간을 각각 초과할 수 없다. <개정 2020.3.24>', 3370);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5890, '④ 법원은 제1항에 따라 처분변경 결정을 한 경우에는 지체 없이 그 사실을 검사, 아동학대행위자, 피해아동, 법정대리인, 변호사, 보조인, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장, 보호관찰관 및 수탁기관의 장에게 통지하여야 한다. <개정 2020.3.24>', 3370);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5891, null, 3371);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5892, '① 제19조제1항제6호에 따른 임시조치 또는 제36조제1항제7호 및 제8호에 따른 보호처분을 받은 아동학대행위자는 위탁 또는 보호처분에 필요한 비용을 부담한다. 다만, 아동학대행위자가 지급할 능력이 없는 경우에는 국가가 부담할 수 있다.', 3373);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5893, '② 판사는 아동학대행위자에게 제1항 본문에 따른 비용의 예납(豫納)을 명할 수 있다.', 3373);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5894, '③ 제1항에 따라 아동학대행위자가 부담할 비용의 계산, 청구 및 지급 절차, 그 밖에 필요한 사항은 대법원규칙으로 정한다.', 3373);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5895, '① 제19조의 임시조치(연장 또는 변경의 결정을 포함한다. 이하 같다), 제36조의 보호처분, 제40조의 보호처분의 변경 및 제41조의 보호처분의 취소에 있어서 그 결정에 영향을 미칠 법령 위반이 있거나 중대한 사실 오인이 있는 경우 또는 그 결정이 현저히 부당한 경우에는 검사, 아동학대행위자, 법정대리인 또는 보조인은 가정법원본원합의부에 항고할 수 있다. 다만, 가정법원이 설치되지 아니한 지역에서는 지방법원본원합의부에 하여야 한다.', 3375);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5896, '② 법원이 제44조가 준용하는 「가정폭력범죄의 처벌 등에 관한 특례법」 제37조에 따라 처분을 하지 아니한다는 결정을 한 경우 그 결정이 현저히 부당할 때에는 검사, 피해아동, 그 법정대리인 또는 변호사는 항고할 수 있다. 이 경우 항고법원에 관하여는 제1항을 준용한다.', 3375);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5897, '③ 항고는 그 결정을 고지받은 날부터 7일 이내에 하여야 한다.', 3375);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5898, '④ 임시조치ㆍ보호처분의 항고ㆍ재항고에 관하여는 「가정폭력범죄의 처벌 등에 관한 특례법」 제50조부터 제54조까지의 규정을 준용한다. 이 경우 "가정보호사건"은 "아동보호사건"으로 본다.', 3375);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5899, '① 피해아동보호명령사건의 관할은 아동학대행위자의 행위지ㆍ거주지 또는 현재지 및 피해아동의 거주지 또는 현재지를 관할하는 가정법원으로 한다. 다만, 가정법원이 설치되지 아니하는 지역에 있어서는 해당 지역의 지방법원으로 한다.', 3376);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5900, '② 피해아동보호명령사건의 심리와 결정은 판사가 한다.', 3376);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5901, '① 판사는 직권 또는 피해아동, 그 법정대리인, 변호사, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장의 청구에 따라 결정으로 피해아동의 보호를 위하여 다음 각 호의 피해아동보호명령을 할 수 있다. <개정 2017.12.19, 2020.3.24>', 3377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5902, '② 아동보호전문기관의 장은 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 제1항에 따른 피해아동보호명령의 청구를 요청할 수 있다. 이 경우 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 요청을 신속히 처리해야 하며, 요청받은 날부터 15일 이내에 그 처리 결과를 아동보호전문기관의 장에게 통보하여야 한다. <신설 2020.3.24>', 3377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5903, '③ 제1항 각 호의 처분은 병과할 수 있다. <개정 2020.3.24>', 3377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5904, '④ 판사가 제1항 각 호의 피해아동보호명령을 하는 경우 피해아동, 그 법정대리인, 변호사, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장 및 아동보호전문기관의 장은 관할 법원에 대하여 필요한 의견을 진술할 수 있다. <개정 2020.3.24>', 3377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5905, '⑤ 판사가 제1항제7호 및 제8호의 피해아동보호명령을 하는 경우 피해아동보호명령의 기간 동안 임시로 후견인의 임무를 수행할 자의 선임 등에 대하여는 제23조를 준용한다. <개정 2020.3.24>', 3377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5906, '⑥ 제1항제4호ㆍ제5호ㆍ제5호의2ㆍ제6호의 규정에 따른 위탁 대상이 되는 아동복지시설, 의료기관, 아동보호전문기관ㆍ상담소 등, 연고자 등의 기준과 위탁의 절차 및 집행 등에 필요한 사항은 대법원규칙으로 정한다. <개정 2017.12.19, 2020.3.24>', 3377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5907, '⑦ 판사는 제1항제5호의2에 따른 피해아동보호명령을 하는 경우 필요하다고 인정하는 때에는 피해아동의 보호자를 그 과정에 참여시킬 수 있다. <신설 2017.12.19, 2020.3.24>', 3377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5908, '① 피해아동 및 아동학대행위자는 피해아동보호명령사건에 대하여 각자 보조인을 선임할 수 있다.', 3378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5909, '② 피해아동 및 아동학대행위자의 법정대리인ㆍ배우자ㆍ직계친족ㆍ형제자매, 아동학대전담공무원, 아동보호전문기관의 상담원과 그 기관장 및 제16조에 따른 변호사는 보조인이 될 수 있다. <개정 2020.3.24>', 3378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5910, '③ 변호사(「변호사법」에 따른 변호사를 말한다. 이하 제49조에서 같다)가 아닌 사람을 보조인으로 선임하거나 제2항에 따른 보조인이 되려면 법원의 허가를 받아야 한다.', 3378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5911, '④ 판사는 언제든지 제3항의 허가를 취소할 수 있다.', 3378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5912, '⑤ 제1항에 따른 보조인의 선임은 심급마다 보조인과 연명날인한 서면으로 제출하여야 한다.', 3378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5913, '⑥ 제2항에 따른 보조인이 되고자 하는 자는 심급별로 그 취지를 신고하여야 한다. 이 경우 보조인이 되고자 하는 자와 피해아동ㆍ아동학대행위자 사이의 신분관계 또는 보조인이 되고자 하는 자의 직위를 소명하는 서면을 첨부하여야 한다.', 3378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5914, '⑦ 제1항에 따른 보조인은 독립하여 절차행위를 할 수 있고, 제2항에 따른 보조인은 독립하여 피해아동 또는 아동학대행위자의 명시한 의사에 반하지 아니하는 절차행위를 할 수 있다. 다만, 법률에 다른 규정이 있는 때에는 예외로 한다.', 3378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5915, '① 다음 각 호의 어느 하나에 해당하는 경우 법원은 직권에 의하거나 피해아동 또는 피해아동의 법정대리인ㆍ직계친족ㆍ형제자매, 아동학대전담공무원, 아동보호전문기관의 상담원과 그 기관장의 신청에 따라 변호사를 피해아동의 보조인으로 선정하여야 한다. <개정 2020.3.24, 2021.3.16>', 3379);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5916, '② 법원은 아동학대행위자가 「형사소송법」 제33조제1항 각 호의 어느 하나에 해당하는 경우에는 직권으로 변호사를 아동학대행위자의 보조인으로 선정할 수 있다.', 3379);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5917, '③ 제1항과 제2항에 따라 선정된 보조인에게 지급하는 비용에 대하여는 「형사소송비용 등에 관한 법률」을 준용한다.', 3379);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5918, '① 관할 법원의 판사는 제47조제1항제1호부터 제5호까지, 제5호의2 및 제6호의 규정에 따른 피해아동보호명령을 하는 경우, 가정보호사건조사관, 법원공무원, 사법경찰관리 또는 구치소 소속 교정직공무원으로 하여금 이를 집행하게 하거나, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 그 집행을 위임할 수 있다. <개정 2017.12.19, 2020.3.24>', 3380);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5919, '② 판사는 제1항에 따른 집행담당자에게 피해아동보호명령의 집행상황보고서 또는 의견서를 요구할 수 있고, 그 집행에 필요한 지시를 할 수 있으며, 필요한 경우 가정보호사건조사관으로 하여금 피해아동보호명령의 집행과 관련한 사항에 대하여 조사하도록 할 수 있다. <신설 2020.3.24>', 3380);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5920, '③ 피해아동, 그 법정대리인, 변호사, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 제47조제1항에 따른 보호명령의 취소 또는 그 종류의 변경을 신청할 수 있으며, 아동보호전문기관의 장은 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 보호명령의 취소 또는 그 종류의 변경 신청을 요청할 수 있다. <개정 2020.3.24>', 3380);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5921, '④ 판사는 상당한 이유가 있다고 인정하는 때에는 직권 또는 제3항의 신청에 따라 결정으로 해당 피해아동보호명령을 취소하거나 그 종류를 변경할 수 있다. <개정 2020.3.24>', 3380);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5922, '⑤ 법원은 제51조제1항에 따른 피해아동보호명령의 기간이 종료된 경우 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 그 사실을 통지하여야 한다. <신설 2021.1.26>', 3380);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5923, '① 제47조제1항제1호부터 제5호까지, 제5호의2 및 제6호부터 제8호까지의 피해아동보호명령의 기간은 1년을 초과할 수 없다. 다만, 관할 법원의 판사는 피해아동의 보호를 위하여 그 기간의 연장이 필요하다고 인정하는 경우 직권 또는 피해아동, 그 법정대리인, 변호사, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장의 청구에 따른 결정으로 6개월 단위로 그 기간을 연장할 수 있다. <개정 2017.12.19, 2020.3.24>', 3381);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5924, '② 보호관찰소의 장 및 아동보호전문기관의 장은 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 제1항 단서에 따른 피해아동보호명령의 연장 청구를 요청할 수 있으며, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 요청받은 날부터 15일 이내에 그 처리 결과를 요청자에게 통보하여야 한다. <신설 2020.3.24>', 3381);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5925, '③ 제1항에 따라 연장된 기간은 피해아동이 성년에 도달하는 때를 초과할 수 없다. <개정 2020.3.24>', 3381);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5926, '① 관할 법원의 판사는 제47조에 따른 피해아동보호명령의 청구가 있는 경우에 피해아동 보호를 위하여 필요하다고 인정하는 때에는 결정으로 임시로 제47조제1항 각 호의 어느 하나에 해당하는 조치(이하 "임시보호명령"이라 한다)를 할 수 있다.', 3382);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5927, '② 임시보호명령의 기간은 피해아동보호명령의 결정 시까지로 한다. 다만, 판사는 필요하다고 인정하는 경우에는 그 기간을 제한할 수 있다.', 3382);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5928, '③ 판사가 제47조제1항제7호 및 제8호에 따라 임시보호명령을 한 경우 그 임시보호명령의 기간 동안 임시로 후견인의 임무를 수행할 자의 선임 등에 대하여는 제23조를 준용한다.', 3382);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5929, '④ 임시보호명령의 집행 및 취소와 변경에 대하여는 제50조를 준용한다. 이 경우 "피해아동보호명령"은 "임시보호명령"으로 본다.', 3382);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5930, '① 관할 법원은 가정보호사건조사관, 법원공무원, 사법경찰관리 또는 보호관찰관 등으로 하여금 임시보호명령 및 피해아동보호명령의 이행실태에 대하여 수시로 조사하게 하고, 지체 없이 그 결과를 보고하도록 할 수 있다.', 3383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5931, '② 관할 법원은 임시보호명령 및 피해아동보호명령을 받은 아동학대행위자가 그 결정을 이행하지 아니하거나 집행에 따르지 아니하는 때에는 그 사실을 관할 법원에 대응하는 검찰청 검사에게 통보할 수 있다.', 3383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5932, '① 법무부장관은 아동학대 및 아동보호의 실태를 파악하고 제도를 개선하기 위하여 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장, 아동권리보장원의 장 및 아동보호전문기관의 장에게 관련 통계 등 자료를 요청할 수 있다.', 3386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5933, '② 법무부장관은 중대한 아동학대 사건이 발생하여 필요하다고 인정하면 해당 사건의 실태파악 및 제도개선을 위하여 관련 공무원, 아동보호전문기관 또는 관계인을 면담하거나 질문할 수 있다.', 3386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5934, null, 3387);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5935, '① 제47조에 따른 피해아동보호명령(제51조에 따른 연장의 결정을 포함한다) 및 제50조에 따른 그 취소 또는 종류의 변경, 제52조에 따른 임시보호명령 및 그 취소 또는 종류의 변경에 있어서 그 결정에 영향을 미칠 법령 위반이 있거나 중대한 사실오인이 있는 때 또는 그 결정이 현저히 부당한 때에는 피해아동, 아동학대행위자, 법정대리인, 변호사, 시ㆍ도지사, 시장ㆍ군수ㆍ구청장 또는 보조인은 가정법원본원합의부에 항고할 수 있다. 다만, 가정법원이 설치되지 아니한 지역에서는 지방법원본원합의부에 하여야 한다. <개정 2020.3.24>', 3388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5936, '② 판사가 피해아동보호명령의 청구를 기각한 경우 피해아동, 그 법정대리인, 변호사, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 항고할 수 있다. 이 경우 항고법원에 관하여는 제1항을 준용한다. <개정 2020.3.24>', 3388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5937, '③ 아동보호전문기관의 장은 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 제1항 및 제2항에 따른 항고를 요청할 수 있다. <신설 2020.3.24>', 3388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5938, '④ 제1항 및 제2항에 따른 피해아동보호명령 등의 항고 및 재항고에 관하여는 「가정폭력범죄의 처벌 등에 관한 특례법」 제49조제3항 및 제50조부터 제53조까지의 규정을 준용한다. <개정 2020.3.24>', 3388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5939, '① 다음 각 호의 어느 하나에 해당하는 아동학대행위자는 2년 이하의 징역 또는 2천만원 이하의 벌금 또는 구류에 처한다.', 3390);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5940, '② 상습적으로 제1항의 죄를 범한 아동학대행위자는 5년 이하의 징역이나 5천만원 이하의 벌금에 처한다. <개정 2017.12.19>', 3390);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5941, '③ 제8조제1항에 따라 이수명령을 부과받은 사람이 보호관찰소의 장 또는 교정시설의 장의 이수명령 이행에 관한 지시에 불응하여 「보호관찰 등에 관한 법률」 또는 「형의 집행 및 수용자의 처우에 관한 법률」에 따른 경고를 받은 후 재차 정당한 사유 없이 이수명령 이행에 관한 지시에 불응한 경우 다음 각 호에 따른다. <개정 2017.12.19>', 3390);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5942, '① 제11조제2항ㆍ제3항, 제12조제1항, 제19조제1항 각 호, 제36조제1항 각 호 또는 제47조제1항 각 호에 따른 업무를 수행 중인 사법경찰관리, 아동학대전담공무원이나 아동보호전문기관의 직원에 대하여 폭행 또는 협박하거나 위계 또는 위력으로써 그 업무수행을 방해한 사람은 5년 이하의 징역 또는 5천만원 이하의 벌금에 처한다. <개정 2020.3.24, 2021.1.26>', 3392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5943, '② 단체 또는 다중의 위력을 보이거나 위험한 물건을 휴대하여 제1항의 죄를 범한 때에는 그 정한 형의 2분의 1까지 가중한다.', 3392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5944, '③ 제1항의 죄를 범하여 사법경찰관리, 아동학대전담공무원이나 아동보호전문기관의 직원을 상해에 이르게 한 때에는 3년 이상의 유기징역에 처한다. 사망에 이르게 한 때에는 무기 또는 5년 이상의 징역에 처한다. <개정 2020.3.24>', 3392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5945, '① 제35조제1항에 따른 비밀엄수 의무를 위반한 보조인, 진술조력인, 아동보호전문기관 직원과 그 기관장, 상담소 등에 근무하는 상담원과 그 기관장 및 제10조제2항 각 호에 규정된 사람(그 직에 있었던 사람을 포함한다)은 3년 이하의 징역이나 5년 이하의 자격정지 또는 3천만원 이하의 벌금에 처한다. 다만, 보조인인 변호사에 대하여는 「형법」 제317조제1항을 적용한다. <개정 2016.5.29>', 3393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5946, '② 제10조제3항을 위반하여 신고인의 인적사항 또는 신고인임을 미루어 알 수 있는 사실을 다른 사람에게 알려주거나 공개 또는 보도한 자는 3년 이하의 징역이나 3천만원 이하의 벌금에 처한다. <개정 2016.5.29>', 3393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5947, '③ 제35조제2항의 보도 금지 의무를 위반한 신문의 편집인ㆍ발행인 또는 그 종사자, 방송사의 편집책임자, 그 기관장 또는 종사자, 그 밖의 출판물의 저작자와 발행인은 500만원 이하의 벌금에 처한다.', 3393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5948, '① 제10조의2를 위반하여 아동학대범죄신고자등에게 파면, 해임, 해고, 그 밖에 신분상실에 해당하는 신분상의 불이익조치를 한 자는 2년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.', 3394);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5949, '② 제10조의2를 위반하여 아동학대범죄신고자등에게 다음 각 호의 어느 하나에 해당하는 불이익조치를 한 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 3394);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5950, '① 다음 각 호의 어느 하나에 해당하는 사람에게는 1천만원 이하의 과태료를 부과한다. <개정 2020.3.24, 2021.1.26>', 3395);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5951, '② 제1항에 따른 과태료는 대통령령으로 정하는 바에 따라 관계 행정기관의 장이 부과ㆍ징수한다.', 3395);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5952, '① 검사는 다음 각 호의 조치를 하기 위해 아동학대전담공무원, 아동보호전문기관의 장, 법 제36조제5항 본문에 따른 수탁기관(이하 "수탁기관"이라 한다)의 장, 사법경찰관, 보호관찰관, 의사, 변호사 및 「아동복지법」 제13조에 따른 아동복지전담공무원 등을 구성원으로 하는 사건관리회의(이하 이 조에서 "회의"라 한다)를 열어 의견 청취 등을 할 수 있다. <개정 2025.6.20>', 3400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5953, '② 회의의 구성원은 회의에 필요한 조사 결과, 자료 등을 제출하거나 보고할 수 있다. <개정 2025.6.20>', 3400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5954, '③ 검사는 회의의 운영을 위하여 필요한 경우에는 회의의 구성원에게 조사 결과, 자료 등의 제출 또는 보고를 요구할 수 있다. <개정 2025.6.20>', 3400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5955, '① 아동학대전담공무원이나 사법경찰관리는 피해아동등이 법 제12조에 따른 응급조치 또는 법 제47조에 따른 피해아동보호명령 등에 따라 보호시설, 의료기관, 아동복지시설 등의 시설이나 기관에 인도되거나 위탁된 경우 또는 법 제12조제1항제5호에 따른 연고자 등에게 인도된 경우에는 주기적으로 피해아동등을 방문하여 보호자와의 의사소통을 중개하거나 피해아동등의 상황 등에 관한 의견을 청취할 수 있다. 다만, 보호자와의 의사소통 중개는 피해아동등이 원하는 경우에만 할 수 있다. <개정 2020.9.29, 2025.6.20>', 3401);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5956, '② 아동학대전담공무원이나 사법경찰관리는 제1항에 따라 의사소통을 중개하거나 의견을 청취할 때 피해아동등이 편안한 상태에서 말할 수 있는 환경을 조성하도록 노력해야 한다. <개정 2020.9.29>', 3401);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5957, '③ 시ㆍ도지사, 시장ㆍ군수ㆍ구청장, 가정보호사건조사관, 법원공무원, 사법경찰관리, 보호관찰관, 아동보호전문기관의 장이나 수탁기관의 장은 법 제25조제4항에 따른 자료 제출, 법 제39조에 따른 보고서ㆍ의견서 제출 또는 법 제53조제1항에 따른 이행실태 조사를 위하여 필요한 경우에는 보호시설, 의료기관 및 아동복지시설 등의 장에게 피해아동등 또는 아동학대행위자에 관한 자료의 제출을 요청할 수 있다. <개정 2020.9.29>', 3401);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5958, '① 사법경찰관리 또는 아동학대전담공무원은 법 제12조제1항제5호에 따라 피해아동등을 제5조의2에 따른 연고자 등(이하 "연고자등"이라 한다)에게 인도하려는 경우에는 연고자등에게 인도하는 것이 적합한지를 판단하기 위해 해당 연고자등에게 다음 각 호의 사항에 대해 질문할 수 있다.', 3403);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5959, '② 사법경찰관리 또는 아동학대전담공무원은 피해아동등을 연고자등에게 인도하는 경우에는 다음 각 호의 사항을 미리 해당 연고자등에게 알려주어야 한다.', 3403);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5960, '③ 사법경찰관리 또는 아동학대전담공무원은 법 제12조제1항제5호에 따라 피해아동등을 연고자등에게 인도하기 전에 해당 연고자등으로부터 법무부령으로 정하는 범죄경력 조회 동의서를 제출받아 다음 각 호의 구분에 따라 해당 연고자등에게 별표 1에 규정된 범죄경력이 있는지를 확인해야 한다. 이 경우 제2호에 따른 범죄경력 조회 요청을 받은 경찰관서의 장은 특별한 사유가 없으면 이에 따라야 한다.', 3403);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5961, '④ 사법경찰관리 또는 아동학대전담공무원은 제3항에 따른 범죄경력 조회 결과 연고자등에게 별표 1에 규정된 범죄경력이 확인된 경우에는 해당 연고자등에게 피해아동동을 인도해서는 안 된다.', 3403);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5962, '⑤ 법 제12조제1항제5호에 따라 피해아동등을 인도받은 연고자등은 응급조치 기간 동안 제5조에 따른 사법경찰관리 또는 아동학대전담공무원의 방문, 피해아동등의 상황 등에 관한 의견청취 등 피해아동등을 보호하기 위한 절차에 성실히 응해야 한다.', 3403);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5963, null, 3404);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5964, '① 법무부장관 등 관계 행정기관의 장, 검사, 보호관찰소의 장, 교정시설의 장, 사법경찰관리, 보호관찰관, 시ㆍ도지사, 시장ㆍ군수ㆍ구청장, 아동학대전담공무원, 아동보호전문기관, 가정위탁지원센터, 아동복지시설의 장과 그 종사자, 수탁기관의 장과 그 직원은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호 및 제2호에 따른 유전정보와 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2020.9.29, 2021.5.18, 2025.6.20>', 3405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5965, '② 수사기관, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장, 아동학대전담공무원, 아동보호전문기관의 장과 그 종사자, 신고의무자는 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보 및 같은 법 시행령 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2020.9.29>', 3405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5966, '③ 법무부장관, 검사 또는 사법경찰관리는 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2021.5.18, 2025.6.20>', 3405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5967, '④ 다음 각 호의 자는 해당 업무와 그에 부수되는 업무를 수행하기 위하여 불가피한 경우 제3항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <개정 2021.5.18>', 3405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5968, '① 「아동학대범죄의 처벌 등에 관한 특례법」(이하 "법"이라 한다) 제9조제2항 전단에 따른 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ도지사ㆍ특별자치도지사(이하 "시ㆍ도지사"라 한다) 또는 시장ㆍ군수ㆍ구청장(자치구의 구청장을 말한다. 이하 같다)의 친권상실의 선고 청구 요청 또는 후견인의 변경 심판 청구 요청은 별지 제1호서식에 따른다. <개정 2020.9.28>', 3408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5969, '② 검사는 제1항에 따른 친권상실의 선고 청구 요청 또는 후견인의 변경 심판 청구 요청에 대하여 별지 제2호서식에 따라 그 처리 결과를 통보하여야 한다.', 3408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5970, '① 법 제11조제1항 후단 및 같은 조 제3항 전단에 따른 동행 요청은 별지 제3호서식에 따른다. 다만, 긴급한 경우에는 구두로 요청할 수 있다. <개정 2020.9.28>', 3409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5971, '② 제1항 단서에 따라 구두로 요청한 경우에는 지체 없이 별지 제3호서식의 동행요청서를 송부해야 한다. <신설 2020.9.28>', 3409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5972, '③ 법 제11조제4항에 따른 아동보호전문기관의 직원의 증표는 별지 제4호서식에 따른다. <개정 2020.9.28>', 3409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5973, '① 법 제11조의2제1항에 따른 출석ㆍ진술 및 자료제출의 요구는 별지 제4호의2서식에 따른다.', 3410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5974, '② 아동학대행위자 또는 관계인이 법 제11조의2제2항에 따라 준용되는 「행정조사기본법」 제9조제2항에 따라 「아동복지법」 제22조제4항에 따른 아동학대전담공무원(이하 "아동학대전담공무원"이라 한다)에게 출석일시를 변경하여 줄 것을 신청하는 경우에는 별지 제4호의3서식의 출석일시 변경신청서를 제출해야 한다.', 3410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5975, '③ 아동학대전담공무원은 제2항에 따라 출석일시 변경신청을 받은 경우에는 신청을 받은 날부터 7일 이내에 변경여부를 별지 제4호의4서식의 출석일시 변경신청 결과통지서에 따라 아동학대행위자 또는 관계인에게 통지해야 한다.', 3410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5976, '④ 아동학대전담공무원은 제1항에 따라 출석ㆍ진술 또는 자료제출의 요구를 한 경우와 제3항에 따라 출석일시 변경신청 결과를 통지한 경우에는 별지 제4호의5서식의 발송확인대장에 해당 사항을 기록해야 한다.', 3410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5977, '⑤ 아동학대행위자 또는 관계인은 법 제11조의2제2항에 따라 준용되는 「행정조사기본법」 제21조제1항에 따라 의견을 제출하려는 경우에는 별지 제4호의6서식의 의견제출서를 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 제출해야 한다.', 3410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5978, '① 사법경찰관리 또는 아동학대전담공무원은 법 제12조제2항에 따라 피해아동, 피해아동의 형제자매인 아동 및 피해아동과 동거하는 아동(이하 "피해아동등"이라 한다)을 보호하고 있는 사실을 다음 각 호의 구분에 따라 관할 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 통보해야 한다.', 3411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5979, '② 「아동학대범죄의 처벌 등에 관한 특례법 시행령」 제5조의3제3항에 따른 범죄경력 조회 동의서는 별지 제5호의3서식에 따른다.', 3411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5980, '③ 사법경찰관리 또는 아동학대전담공무원이 법 제12조제5항에 따라 응급조치결과보고서를 작성하는 경우에는 별지 제6호서식에 따른다.', 3411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5981, '① 피해아동등, 그 법정대리인(아동학대행위자를 제외한다. 이하 같다), 변호사(법 제16조에 따른 변호사를 말한다. 이하 같다), 시ㆍ도지사, 시장ㆍ군수ㆍ구청장 또는 아동보호전문기관의 장이 법 제13조제1항에 따른 조치(이하 "긴급임시조치"라 한다)를 신청할 때에는 별지 제7호서식에 따른다. <개정 2020.9.28, 2025.6.20>', 3412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5982, '② 사법경찰관이 법 제13조제1항에 따라 긴급임시조치를 한 때에는 별지 제8호서식의 긴급임시조치결정서를 작성한 후 사건기록에 편철하여야 한다.', 3412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5983, '③ 사법경찰관이 법 제15조제3항에 따라 긴급임시조치를 취소한 때에는 별지 제9호서식의 긴급임시조치 취소결정서를 작성한 후 사건기록에 편철하여야 한다.', 3412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5984, '④ 사법경찰관이 법 제13조제1항에 따라 긴급임시조치를 하거나 법 제15조제3항에 따라 긴급임시조치를 취소한 때에는 긴급임시조치를 신청한 사람에게 그 처리 결과를 알려주어야 한다. 이 경우 처리 결과의 통보는 서면, 전화, 전자우편, 팩스, 휴대전화 문자전송, 그 밖에 적당한 방법으로 할 수 있다. <개정 2020.9.28>', 3412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5985, '① 검사가 법 제14조제1항에 따라 직권으로 임시조치를 청구할 때에는 별지 제10호서식에 따르고, 사법경찰관이나 보호관찰관의 신청에 따라 임시조치를 청구할 때에는 별지 제11호서식에 따른다. 이 경우 사법경찰관이나 보호관찰관이 법 제14조제1항에 따라 검사에게 임시조치를 신청할 때에는 별지 제12호서식에 따른다.', 3413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5986, '② 사법경찰관이 법 제15조제1항에 따라 검사에게 임시조치를 신청할 때에는 별지 제13호서식에 따른다. 이 신청을 받은 검사가 법 제15조제2항에 따라 임시조치를 청구할 때에는 별지 제14호서식에 따른다.', 3413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5987, '③ 제1항 후단 또는 제2항 전단에 따라 사법경찰관이나 보호관찰관이 임시조치를 신청하였을 때에는 별지 제15호서식의 임시조치신청부를 작성하여야 하고, 제1항 전단 또는 제2항 후단에 따라 검사가 임시조치를 청구하였을 때에는 별지 제16호서식의 임시조치청구부를 작성하여야 한다.', 3413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5988, '④ 검사는 법 제14조제1항에 따른 사법경찰관이나 보호관찰관의 임시조치 신청 또는 법 제15조제1항에 따른 사법경찰관의 임시조치 신청을 검토하여 임시조치를 할 만한 상당한 이유가 없다고 인정할 때에는 별지 제17호서식에 그 이유를 구체적으로 기재하여 임시조치 신청을 기각한다. <개정 2025.6.20>', 3413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5989, '⑤ 피해아동등, 그 법정대리인, 변호사, 시ㆍ도지사, 시장ㆍ군수ㆍ구청장 또는 아동보호전문기관의 장이 법 제14조제2항에 따라 임시조치의 청구 또는 그 신청을 요청할 때에는 별지 제18호서식에 따른다. <개정 2020.9.28>', 3413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5990, '⑥ 제5항의 경우에 검사는 임시조치의 청구를 요청한 사람에게 별지 제19호서식에 따라 그 처리 결과를 알려주어야 하고, 사법경찰관은 임시조치의 신청을 요청한 사람에게 별지 제20호서식에 따라 그 처리 결과를 알려주어야 한다. 이 경우 임시조치의 신청 요청을 받은 사법경찰관이 임시조치를 신청하지 않는 경우에는 별지 제21호서식에 따라 검사 및 임시조치의 신청을 요청한 사람에게 그 사유를 통지해야 한다. <개정 2020.9.28>', 3413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5991, '⑦ 사법경찰관리가 법 제21조제1항에 따라 임시조치의 결정을 집행하였을 때에는 집행일시 및 집행방법을 적은 서면을 사건기록에 편철하여야 한다.', 3413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5992, '⑧ 사법경찰관은 임시조치의 결정에 대하여 항고가 제기되어 법원으로부터 수사기록 등본의 제출을 요구받았을 경우에 항고심 재판에 필요한 범위에서 수사기록 등본을 관할 검찰청으로 보내야 한다.', 3413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5993, '⑨ 법 제21조제2항에 따라 임시조치 집행담당자가 아동학대행위자의 임시조치 이행상황에 대해 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 통보할 때에는 별지 제21호의2서식에 따른다. <신설 2020.9.28>', 3413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5994, '⑩ 제1항부터 제9항까지에서 규정한 사항 외에 임시조치의 청구 및 집행 절차 등에 관하여는 「검찰사건사무규칙」 제21조제5항ㆍ제6항 및 제56조의2제6항을 준용한다. <개정 2020.9.28>', 3413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5995, '① 다음 각 호에 해당하는 경우에는 별지 제22호서식에 따른다.', 3414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5996, '② 법 제22조제2항에 따라 검사가 법원에 임시조치 기간의 연장, 그 종류의 변경 또는 취소 청구를 하는 경우에는 별지 제23호서식에 따르고, 사법경찰관이 검사에게 임시조치 기간의 연장, 그 종류의 변경 또는 취소 신청을 하는 경우에는 별지 제23호의2서식에 따른다.', 3414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5997, '③ 검사는 법 제22조제2항에 따른 사법경찰관의 임시조치 기간의 연장, 그 종류의 변경 또는 취소 신청을 검토한 결과 해당 청구를 할 상당한 이유가 없다고 인정하는 경우에는 별지 제23호의3서식에 그 이유를 구체적으로 기재하여 신청을 기각한다.', 3414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5998, '④ 법 제22조제2항에 따라 사법경찰관이 검사에게 임시조치 기간의 연장, 그 종류의 변경 또는 취소 신청을 한 경우에는 별지 제23호의4서식의 임시조치 기간연장ㆍ종류변경ㆍ취소 신청부를 작성해야 하고, 검사가 법원에 임시조치 기간의 연장, 그 종류의 변경 또는 취소 청구를 한 경우에는 별지 제23호의5서식의 임시조치 기간연장ㆍ종류변경ㆍ취소 청구부를 작성해야 한다.', 3414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (5999, '⑤ 법 제19조제1항 각 호의 위탁 대상이 되는 기관의 장이 법 제22조제4항에 따라 임시조치 변경을 청구하는 경우에는 별지 제24호서식에 따른다.', 3414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6000, '① 법 제31조에 따른 송치서(검사가 법 제28조에 따라 사건을 관할 법원에 송치하는 경우로 한정한다)는 별지 제27호서식에 따른다.', 3416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6001, '② 검사가 구속되어 있는 아동학대행위자에게 제1항에 따른 아동보호사건 송치 결정(이하 "송치 결정"이라 한다)을 할 때에는 별지 제28호서식에 따라 아동학대행위자를 구금하고 있는 시설의 장에게 아동학대행위자를 관할 법원에 인도할 것을 지휘하여야 한다.', 3416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6002, '③ 법원이 법 제29조에 따라 구속되어 있는 아동학대행위자에 대한 피고사건을 관할 법원에 송치하는 결정을 하는 경우의 사무처리에 관하여는 제2항을 준용한다.', 3416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6003, '④ 제1항부터 제3항까지에서 규정한 사항 외에 검사가 구속되어 있는 아동학대행위자를 관할 법원에 송치하는 결정을 하는 경우의 사무처리에 관하여는 「검찰사건사무규칙」 제49조제4항, 제103조제6항ㆍ제7항, 제128조제3항 및 제141조를 준용한다. 이 경우 "가정보호사건"은 "아동보호사건"으로 본다. <개정 2021.1.1>', 3416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6004, '① 검사가 법 제40조제1항에 따른 보호처분의 변경 청구, 법 제41조에 따른 보호처분의 취소 청구 또는 법 제42조에 따른 보호처분의 종료 청구를 할 때에는 별지 제29호서식에 따르고, 시ㆍ도지사, 시장ㆍ군수ㆍ구청장, 보호관찰관 또는 수탁기관의 장이 같은 청구를 할 때에는 별지 제30호서식에 따른다. <개정 2020.9.28>', 3418);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6005, '② 피해아동, 그 법정대리인 또는 변호사가 법 제41조에 따른 보호처분의 취소 청구 또는 법 제42조에 따른 보호처분의 종료 청구를 할 때에는 별지 제31호서식에 따른다.', 3418);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6006, '① 검사가 법 제47조제1항에 따라 법원에 피해아동보호명령의 청구를 하는 경우에는 별지 제31호의2서식에 따르고, 피해아동보호명령 청구를 한 경우에는 별지 제31호의3서식의 피해아동보호명령 청구부를 작성해야 한다.', 3419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6007, '② 아동보호전문기관의 장이 법 제47조제2항에 따라 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 피해아동보호명령의 청구를 요청하는 경우에는 별지 제31호의4서식에 따른다.', 3419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6008, '③ 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 제2항에 따른 청구를 요청받은 경우에는 피해아동보호명령의 청구를 요청한 아동보호전문기관의 장에게 별지 제31호의5서식에 따라 그 처리 결과를 통보해야 한다.', 3419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6009, '① 검사가 법 제50조제3항에 따라 법원에 피해아동보호명령의 취소 또는 그 종류의 변경을 신청하거나 법 제51조제1항에 따라 피해아동보호명령 기간의 연장을 청구하는 경우에는 별지 제31호의6서식에 따르고, 피해아동보호명령의 취소 또는 그 종류의 변경 신청이나 피해아동보호명령 기간의 연장 청구를 한 경우에는 별지 제31호의7서식의 피해아동보호명령 취소ㆍ종류변경 신청부 및 기간연장 청구부를 작성해야 한다.', 3420);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6010, '② 아동보호전문기관의 장이 법 제50조제3항에 따라 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 피해아동보호명령의 취소 또는 그 종류의 변경 신청을 요청하는 경우에는 별지 제31호의8서식에 따른다.', 3420);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6011, '③ 보호관찰소의 장 또는 아동보호전문기관의 장이 법 제51조제2항에 따라 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 피해아동보호명령의 연장 청구를 요청하는 경우에는 별지 제31호의9서식에 따른다.', 3420);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6012, '④ 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 제3항에 따른 청구를 요청받은 경우에는 피해아동보호명령의 연장 청구를 요청한 보호관찰소의 장 또는 아동보호전문기관의 장에게 별지 제31호의10서식에 따라 그 처리 결과를 통보해야 한다.', 3420);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6013, '⑤ 아동보호전문기관의 장이 법 제57조제3항에 따라 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 법 제57조제1항 및 제2항에 따른 항고를 요청하는 경우에는 별지 제31호의11서식에 따른다.', 3420);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6014, null, 3423);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6015, '① 법무부장관은 법 제3조의2제2항에 따라 협약을 맺은 기관 또는 단체(이하 "연구개발기관"이라 한다)에 같은 조 제3항에 따라 출연금을 지급하는 경우 연구개발사업의 규모, 착수시기 및 정부의 재정 사정 등을 고려해 한꺼번에 지급하거나 나누어 지급할 수 있다.', 3425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6016, '② 제1항에 따라 출연금을 지급받은 연구개발기관은 그 출연금을 별도의 계정(計定)을 설정하여 관리해야 한다.', 3425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6017, '③ 제1항에 따라 출연금을 지급받은 연구개발기관은 그 출연금을 「국가연구개발혁신법 시행령」 별표 2에 따른 연구개발비 사용용도로만 사용해야 한다.', 3425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6018, '④ 법무부장관은 연구개발기관이 정당한 사유 없이 제3항에 따른 용도 외의 용도로 제1항에 따라 지급받은 출연금을 사용한 경우에는 해당 금액을 회수해야 한다.', 3425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6019, '⑤ 법 제3조의2제4항에 따른 보조금의 지급ㆍ사용 및 관리에 관하여는 「보조금 관리에 관한 법률」에서 정하는 바에 따른다.', 3425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6020, '① 검사는 법 제6조제1항에 따라 보호관찰소(지소를 포함한다. 이하 같다)의 장에게 조사를 요청할 때에는 법 제5조제1항부터 제5항까지의 규정에 따른 전자장치를 부착하도록 하는 명령(이하 "부착명령"이라 한다)을 청구하는 피의자의 인적사항 및 범죄사실의 요지를 통보해야 한다. 이 경우 법무부령으로 정하는 참고자료를 보낼 수 있다. <개정 2009.7.30, 2010.7.12, 2013.5.31, 2024.1.9>', 3426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6021, '② 보호관찰소의 장은 법 제6조제1항의 조사를 위해 교도소ㆍ소년교도소ㆍ구치소ㆍ군교도소의 장, 경찰서장, 국립법무병원장(이하 "수용기관의 장"이라 한다)에게 협조를 요청할 수 있다. 이 경우 수용기관의 장은 특별한 사유가 없으면 협조해야 한다. <개정 2024.1.9>', 3426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6022, '① 법 제8조제1항제1호에서 "그 밖에 피부착명령청구자를 특정할 수 있는 사항"이란 피부착명령청구자의 주민등록번호, 직업, 주거, 등록기준지를 말하고, 같은 항 제4호에서 "대통령령으로 정하는 사항"이란 피부착명령청구자의 죄명을 말한다. <개정 2010.7.12>', 3427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6023, '② 검사가 공소 제기와 동시에 부착명령을 청구할 경우에는 공소장에 부착명령 청구의 원인이 되는 사실과 적용 법조문을 추가하여 적는 것으로 부착명령 청구서를 대신할 수 있다.', 3427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6024, '① 보호관찰관은 피부착명령자에 대한 판결문 등본, 법 제12조제2항의 부착명령 집행을 지휘한 서면, 그 밖의 관련 서류를 확인한 후 부착명령을 집행하여야 한다.', 3429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6025, '② 보호관찰관은 법 제13조제1항에 따라 부착명령을 집행하기에 앞서 피부착명령자에게 법 제14조와 이 영에 따른 피부착자의 의무사항 및 법 제38조 및 제39조에 따른 벌칙에 관한 사항을 알려야 한다.', 3429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6026, '③ 부착명령은 다음 각 호의 방법으로 집행한다. <개정 2018.2.13>', 3429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6027, '④ 보호관찰소의 장은 소속 보호관찰관이 부착명령을 집행하기 위하여 필요하면 수용기관의 장에게 협조를 요청할 수 있다. 이 경우 수용기관의 장은 특별한 사유가 없으면 협조하여야 한다.', 3429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6028, '⑤ 수용기관의 장은 피부착자가 부착명령의 집행 중 「형법」 제70조에 따른 노역장유치의 집행을 받게 된 경우 피부착자의 주거지를 관할하는 보호관찰소의 장에게 통보하여 담당 보호관찰관이 전자장치를 분리하여 회수하도록 하여야 하며, 피부착자가 노역장유치의 집행을 마치고 석방되기 전에 피부착자의 주거지를 관할하는 보호관찰소의 장에게 석방예정 사실을 통보하여 석방 전에 담당 보호관찰관이 피부착자에게 전자장치를 부착할 수 있도록 하여야 한다. <신설 2013.5.31>', 3429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6029, '① 보호관찰관은 법 제13조제6항에 따라 부착명령의 집행이 정지되면 지체 없이 전자장치를 분리하여 회수하여야 한다. 이 경우 부착명령의 집행기간은 신체에서 부착장치를 분리한 때부터 정지된다. <개정 2010.7.12, 2018.6.12>', 3430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6030, '② 수용기관의 장은 법 제13조제6항 각 호의 사유로 피부착자가 구금된 경우에는 즉시 그의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다. <개정 2010.7.12, 2018.6.12>', 3430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6031, '③ 보호관찰관은 법 제13조제8항에 따른 부착명령의 잔여기간 집행사유가 발생한 경우 다시 전자장치를 부착하여야 한다. 이 경우 부착명령의 집행기간은 신체에 부착장치를 부착한 때부터 진행한다. <개정 2010.7.12, 2018.6.12>', 3430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6032, '④ 수용기관의 장은 법 제13조제8항제1호에 따른 부착명령의 잔여기간 집행사유가 발생한 경우 구금을 해제하기 전에 피부착명령자의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다. <개정 2010.7.12, 2018.6.12>', 3430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6033, '⑤ 수용기관의 장은 법 제13조제8항제2호 및 제3호에 따른 부착명령의 잔여기간 집행사유가 발생한 경우 부착명령의 집행이 정지된 사람이 석방되기 5일 전까지 그의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다. <신설 2010.7.12, 2018.6.12>', 3430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6034, '① 보호관찰관은 피부착자의 치료, 전자장치의 교체, 그 밖에 전자장치를 일시 분리할 필요가 있는 경우 보호관찰소의 장의 승인을 받아 전자장치의 전부 또는 일부를 피부착자의 신체 또는 주거에서 일시적으로 분리할 수 있다. 다만, 승인을 받을 시간적 여유가 없을 경우에는 분리한 후 지체 없이 보고하여야 한다.', 3432);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6035, '② 보호관찰관은 제1항의 일시 분리 사실을 대장에 적고 그 대장을 비치하여야 한다.', 3432);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6036, null, 3433);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6037, '① 법 제14조제2항에서 "대통령령으로 정하는 신상정보 등"이란 제15조의2제1항제1호부터 제8호까지의 사항 및 그 밖에 피부착자에 대한 지도ㆍ감독에 필요한 사항을 말한다. <개정 2018.6.12>', 3434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6038, '② 피부착자는 법 제14조제3항에 따른 주거이전 등의 허가를 받으려고 할 때에는 본인의 성명, 주거, 주거이전 예정지나 국내여행 예정지 또는 출국 예정지, 주거이전 이유나 국내여행 목적 또는 출국 목적, 주거이전 일자나 국내여행 기간 또는 출국 기간 등을 적은 허가신청서와 소명자료를 보호관찰소에 출석하여 제출하여야 한다.', 3434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6039, '③ 제2항에 따른 허가 신청을 받은 보호관찰관은 신청일부터 7일 이내에 주거이전 예정지나 국내여행 예정지 또는 출국 예정지, 주거이전 이유나 국내여행 목적, 출국의 목적 또는 법 제9조의2 및 「보호관찰 등에 관한 법률」 제32조에 따른 준수사항 이행 정도 등을 종합적으로 고려하여 허가 여부를 결정하여야 한다. <개정 2013.5.31>', 3434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6040, '④ 보호관찰관은 제3항에 따라 피부착자의 출국 허가를 결정할 경우 피부착자가 다음 각 호의 어느 하나에 해당하는 경우에는 출국을 허가하지 아니할 수 있다. 다만, 제1호의 경우에는 출국을 허가하지 아니하여야 한다. <신설 2013.5.31>', 3434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6041, '⑤ 보호관찰관은 제3항에 따라 피부착자의 출국 허가를 결정할 경우 그 허가기간을 출국일부터 3개월 이내의 범위에서 정하되, 불가피한 경우에만 이를 초과하여 정할 수 있다. <신설 2013.5.31>', 3434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6042, '⑥ 피부착자는 주거이전 허가를 받아 다른 보호관찰소의 관할 구역으로 주거를 이전한 경우 3일 이내에 새로운 주거지를 관할하는 보호관찰소에 출석하여 제1항의 신고를 하여야 한다. <개정 2013.5.31>', 3434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6043, '⑦ 보호관찰소의 장은 소속 보호관찰관이 제3항에 따라 피부착자에게 출국을 허가한 경우 법무부장관에게 피부착자의 출입국 사실을 통보하여 줄 것을 요청하여야 한다. <개정 2013.5.31>', 3434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6044, '⑧ 법무부장관은 제7항에 따른 요청을 받은 경우에는 피부착자의 출입국 시 지체 없이 그 사실을 보호관찰소의 장에게 통보하여야 한다. <개정 2013.5.31>', 3434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6045, '⑨ 제3항에 따른 출국 허가를 받아 출국했던 피부착자는 입국한 후 지체 없이 관할 보호관찰소에 출석하여 전자장치가 정상적으로 작동하는지를 확인받아야 한다. <개정 2013.5.31>', 3434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6046, '① 보호관찰소의 장은 법 제14조의2에 따라 부착기간의 연장을 신청하거나 같은 조 또는 법 제14조의3에 따라 준수사항의 부과ㆍ추가ㆍ변경ㆍ삭제를 신청하는 경우에는 다음 각 호의 사항을 적은 서면으로 신청해야 한다. <개정 2021.9.14>', 3435);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6047, '② 보호관찰소의 장은 제1항의 신청을 할 때 신청사유를 소명할 수 있는 자료를 제출하여야 한다.', 3435);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6048, '③ 법원은 법 제14조의2 또는 제14조의3에 따른 청구의 심리를 위하여 필요한 경우에는 담당 보호관찰관을 출석시켜 의견을 들을 수 있고, 피부착자 또는 피부착명령자를 소환하여 심문하거나 필요한 사항을 확인할 수 있다. <개정 2021.9.14>', 3435);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6049, '① 법무부장관은 다음 각 호의 시설 또는 단체를 지정하여 법 제15조제2항의 치료 및 상담치료 등을 실시하게 할 수 있다. <개정 2009.7.30, 2010.12.29, 2017.5.29>', 3436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6050, '② 법무부장관은 제1항의 치료 및 상담치료 등에 대하여 예산의 범위에서 비용의 전부 또는 일부를 지급할 수 있다.', 3436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6051, '③ 법무부장관은 제1항의 치료 및 상담치료에 필요한 프로그램의 개발과 전문인력의 양성을 위하여 노력하여야 한다.', 3436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6052, '④ 법무부장관은 제1항에 따른 지정을 받은 시설 또는 단체가 치료 및 상담치료 등을 실시하기에 부적당한 경우 그 지정을 취소할 수 있다. <신설 2010.7.12>', 3436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6053, '① 검사는 법 제16조제4항 본문에 따라 수신자료를 열람 또는 조회하려는 경우에는 관할 법원에 피부착자에 대한 수신자료의 열람 또는 조회를 허가하여 줄 것을 청구할 수 있다.', 3438);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6054, '② 사법경찰관은 법 제16조제4항 본문에 따라 수신자료를 열람 또는 조회하려는 경우 검사에게 피부착자에 대한 수신자료의 열람 또는 조회에 대한 허가를 신청하고, 검사는 관할 법원에 그 허가를 청구할 수 있다.', 3438);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6055, '③ 제1항 및 제2항에 따른 수신자료 열람 또는 조회의 허가 청구 또는 신청은 피부착자의 인적사항, 수신자료 제공기관, 청구ㆍ신청 사유 및 필요한 자료의 범위를 적은 서면으로 하여야 한다.', 3438);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6056, '④ 검사 또는 사법경찰관은 법 제16조제4항 본문에 따라 수신자료를 열람 또는 조회하는 경우에는 보호관찰소의 장(위치추적 관제센터의 장을 포함한다. 이하 제14조의3부터 제14조의6까지에서 같다)에게 관할 법원의 허가서 사본을 내주어야 한다. <개정 2021.9.14, 2024.1.9>', 3438);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6057, '① 검사 또는 사법경찰관은 법 제16조제4항 단서에 따라 수신자료의 열람 또는 조회를 요청하는 경우에는 보호관찰소의 장에게 다음 각 호의 서류를 팩스 등의 방법으로 제시하여야 한다.', 3439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6058, '② 검사는 제1항에 따른 긴급 수신자료 열람 또는 조회를 요청한 경우에는 지체 없이 관할 법원에 그 허가를 청구하여야 한다.', 3439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6059, '③ 사법경찰관은 제1항에 따른 긴급 수신자료 열람 또는 조회를 요청한 경우에는 지체 없이 검사에게 긴급 수신자료 열람 또는 조회에 대한 허가를 신청하고, 검사는 관할 법원에 그 허가를 청구할 수 있다.', 3439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6060, '④ 검사 또는 사법경찰관이 법 제16조제4항 단서에 따라 보호관찰소의 장에게 송부하여야 할 자료는 관할 법원의 허가서 사본으로 한다.', 3439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6061, '① 검사 또는 사법경찰관은 법 제16조제4항과 제5항에 따른 수신자료의 열람 또는 조회 허가 신청 및 청구 현황, 수신자료 열람 또는 조회 사실을 적은 대장을 3년간 소속 기관에 갖추어 두어야 한다.', 3440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6062, '② 보호관찰소의 장은 검사 또는 사법경찰관에게 수신자료를 열람 또는 조회하게 하였을 때에는 해당 수신자료 열람 또는 조회 사실을 적은 대장과 수신자료 열람ㆍ조회 요청서 등 관련 자료를 3년간 갖추어 두어야 한다.', 3440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6063, '③ 검사가 제14조의3제3항에 따른 사법경찰관의 허가 신청을 기각하면 사법경찰관은 지체 없이 열람 또는 조회한 수신자료를 폐기하여야 한다.', 3440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6064, '④ 검사 또는 사법경찰관은 법 제16조제5항 또는 이 조 제3항에 따라 열람 또는 조회한 수신자료를 폐기하였을 때에는 지체 없이 그 사실을 서면으로 보호관찰소의 장에게 통지하여야 한다.', 3440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6065, '① 검사 또는 사법경찰관은 수신자료를 열람 또는 조회하여 수사한 사건에 관하여 공소를 제기하거나 공소의 제기 또는 입건을 하지 아니하는 처분(기소중지결정은 제외한다)을 하였을 때에는 그 처분의 결과를 수신자료를 제공한 보호관찰소의 장에게 서면으로 통지하여야 한다.', 3441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6066, '② 사법경찰관은 수신자료를 열람 또는 조회하여 수사한 사건을 종결하는 경우에는 그 결과를 검사에게 보고하여야 한다. 다만, 그 사건을 검찰에 송치하는 경우에는 그러하지 아니하다.', 3441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6067, '① 전자장치 부착기간이 끝난 사람이 부착을 마친 날부터 5년 내에 자격정지 이상의 형을 받은 경우에는 그 형의 집행이 끝난 날부터 5년이 지난 때에 수신자료를 폐기한다.', 3443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6068, '② 수신자료의 폐기는 전산자료에서 삭제하는 방법으로 한다.', 3443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6069, '① 법 제16조의2제1항에 따라 보호관찰소의 장이 피부착자의 주거지를 관할하는 경찰관서의 장 등 수사기관에 제공할 수 있는 피부착자의 신상정보는 다음 각 호와 같다. <개정 2015.1.20>', 3444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6070, '② 법 제16조의2제3항에 따라 보호관찰소의 장이 수사기관에 통보하는 사항은 다음 각 호와 같다.', 3444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6071, '③ 법 제16조의2제4항에 따라 수사기관이 보호관찰소의 장에게 통보하는 사항은 다음 각 호와 같다.', 3444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6072, '④ 제1항에 따른 피부착자 신상정보의 제공은 보호관찰소의 장이 관리하는 제1항 각 호의 피부착자 신상정보에 관한 전자기록을 「형사사법절차 전자화 촉진법」 제2조제4호에 따른 형사사법정보시스템에 등록하고, 수사기관은 이를 조회하는 방식 등으로 할 수 있다.', 3444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6073, '⑤ 수사기관의 장은 제4항에 따라 조회한 피부착자의 신상정보를 문서로 출력한 경우 제1항제7호에 따른 전자장치 부착기간이 끝나면 그 문서를 폐기하여야 한다.', 3444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6074, '① 법 제17조제1항에 따른 부착명령의 임시해제 신청은 「보호관찰 등에 관한 법률」 제5조에 따른 보호관찰심사위원회(이하 "심사위원회"라 한다)에 서면으로 해야 한다. <개정 2020.8.5>', 3445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6075, '② 심사위원회는 피부착자 또는 그 법정대리인이 부착명령의 임시해제를 신청한 경우 지체 없이 그 사실을 보호관찰소의 장에게 통보해야 한다. <개정 2020.8.5>', 3445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6076, '① 심사위원회는 법 제18조제1항에 따라 부착명령의 임시해제를 심사할 때에는 보호관찰관, 정신건강의학과 의사, 정신보건임상심리사, 그 밖의 전문가의 의견을 고려해야 한다. <개정 2011.11.23, 2013.5.31, 2020.8.5>', 3446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6077, '② 심사위원회는 법 제18조제4항 및 제5항의 결정을 하면 지체 없이 그 결정서 등본을 관할 보호관찰소의 장과 신청인에게 송달하여야 한다.', 3446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6078, '③ 보호관찰관은 법 제18조제4항의 부착명령 임시해제 결정이 있으면 결정서에 기재된 임시해제일에 전자장치를 회수해야 한다. <개정 2020.8.5>', 3446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6079, '④ 심사위원회가 제1항에 따라 전문가 의견을 고려한 경우 의견을 진술하거나 자료를 제출한 전문가에게는 예산의 범위에서 필요한 비용의 전부 또는 일부를 지급할 수 있다. <신설 2010.7.12>', 3446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6080, '① 법 제19조제1항에 따른 임시해제의 취소신청은 심사위원회에 서면으로 해야 한다. <신설 2013.5.31, 2020.8.5>', 3447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6081, '② 심사위원회는 법 제19조제1항에 따라 부착명령의 임시해제 취소 결정을 했을 때에는 지체 없이 그 사실을 관할 보호관찰소의 장에게 통보해야 한다. <개정 2013.5.31, 2020.8.5>', 3447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6082, '③ 보호관찰관은 부착명령의 임시해제 취소결정이 있으면 피부착명령자에게 결정서를 제시한 후 전자장치를 부착해야 한다. <개정 2013.5.31, 2020.8.5>', 3447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6083, '④ 임시해제가 취소된 경우 부착명령 집행기간은 부착장치를 피부착명령자의 신체에 부착한 때부터 진행한다. <개정 2013.5.31, 2020.8.5>', 3447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6084, '① 보호관찰소의 장은 법 제21조의7에 따라 보호관찰 기간의 연장 또는 준수사항의 추가ㆍ변경ㆍ삭제를 신청하는 경우에는 다음 각 호의 사항을 적은 서면으로 하여야 한다.', 3448);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6085, '② 보호관찰소의 장은 제1항의 신청을 할 때 신청사유를 소명할 수 있는 자료를 제출하여야 한다.', 3448);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6086, '③ 법원은 법 제21조의7에 따른 청구의 심리를 위하여 필요한 경우에는 담당 보호관찰관을 출석시켜 의견을 들을 수 있으며, 보호관찰대상자를 소환하여 심문(審問)하거나 필요한 사항을 확인할 수 있다.', 3448);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6087, '① 교도소ㆍ소년교도소ㆍ구치소의 장은 가석방 예정자에 대한 심사위원회의 법 제22조제3항에 따른 전자장치 부착의 필요성과 적합성 여부 등의 조사(이하 "전자장치 부착 적합성조사"라 한다)를 위해 「형의 집행 및 수용자의 처우에 관한 법률」 및 관계 법령에 따라 가석방 적격심사 신청 대상자가 선정되면 지체 없이 해당 대상자에 대한 다음 각 호의 사항이 포함된 자료를 해당 교도소ㆍ소년교도소ㆍ구치소의 소재지를 관할하는 심사위원회에 보내야 한다.', 3450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6088, '② 심사위원회는 제1항에 따라 교도소ㆍ소년교도소ㆍ구치소의 장으로부터 자료를 받은 경우에는 가석방 예정자에 대한 전자장치 부착 적합성조사를 하거나, 교도소ㆍ소년교도소ㆍ구치소의 소재지 또는 해당 가석방 예정자의 거주예정지를 관할하는 보호관찰소의 장과 협의하여 보호관찰소의 장에게 전자장치 부착 적합성조사를 위하여 필요한 사항의 조사를 의뢰할 수 있다.', 3450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6089, '③ 보호관찰소의 장은 제2항에 따른 의뢰를 받은 경우에는 필요한 조사를 하고 그 결과를 심사위원회에 통보해야 한다.', 3450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6090, '④ 교도소ㆍ소년교도소ㆍ구치소의 장은 심사위원회 또는 보호관찰소의 장으로부터 제2항 또는 제3항에 따른 전자장치 부착 적합성조사 등을 위한 가석방 예정자 면담 등 필요한 협조를 요청받은 경우 특별한 사정이 없으면 이에 협조해야 한다.', 3450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6091, '⑤ 심사위원회 또는 보호관찰소의 장은 전자장치 부착 적합성조사를 위해 필요하다고 인정하면 국가기관, 지방자치단체 또는 공공기관의 장에게 사실을 알아보거나 관련 자료의 열람 등 협조를 요청할 수 있다. 이 경우 해당 기관의 장은 특별한 사정이 없는 한 이에 협조해야 한다.', 3450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6092, '⑥ 전자장치 부착 적합성조사의 내용에는 가석방 예정자의 범죄경력, 범죄내용 및 직업, 경제력, 생활환경 등 개별적 특성에 관한 사항이 포함되어야 한다.', 3450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6093, '① 심사위원회는 「보호관찰 등에 관한 법률」 제24조제1항에 따른 보호관찰 결정서 등본을 수용기관의 장에게 송달하면서 법 제22조제1항 및 제2항에 따른 전자장치 부착에 관한 사항을 함께 통보해야 한다. <개정 2020.8.5>', 3451);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6094, '② 「치료감호 등에 관한 법률」 제37조에 따른 치료감호심의위원회는 법 제23조제1항에 따라 피치료감호자 또는 피보호감호자에게 전자장치를 부착하는 결정을 한 경우 그 결정서를 피치료감호자 또는 피보호감호자에게, 결정서 등본을 수용기관의 장(보호감호시설의 장을 포함한다. 이하 이 장에서 같다)에게 각각 송달하여야 한다. <개정 2010.7.12, 2016.11.29>', 3451);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6095, '③ 제1항 또는 제2항에 따라 결정서 등본을 송달받은 수용기관의 장은 전자장치를 부착하게 될 가석방예정자, 피치료감호자 또는 피보호감호자에게 전자장치 부착에 관한 내용을 알려주어야 한다. <개정 2010.7.12>', 3451);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6096, '① 치료감호시설의 장 및 보호감호시설의 장은 법 제23조제1항에 따라 전자장치 부착결정을 받은 사람(이하 "피부착결정자"라 한다)을 다른 수용기관으로 이송할 경우 그 수용기관의 장에게 이송되는 사람이 전자장치 부착결정을 받았음을 통보하여야 한다. <개정 2010.7.12>', 3452);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6097, '② 제1항에 따라 피부착결정자를 인수한 수용기관의 장은 그가 출소하기 5일 전까지 그 주거지를 관할하는 보호관찰소의 장에게 피부착결정자의 석방 예정 사실을 통보하여야 한다.', 3452);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6098, '① 법원은 법 제31조의2제2항에 따라 보호관찰소의 장에게 조사를 의뢰하는 경우에는 피고인의 인적사항 및 범죄사실의 요지를 통보해야 한다. 이 경우 필요하면 참고자료를 보낼 수 있다.', 3456);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6099, '② 보호관찰소의 장은 법 제31조의2제3항에 따른 조사를 위해 수용기관의 장에게 협조를 요청할 수 있다. 이 경우 수용기관의 장은 특별한 사유가 없으면 이에 협조해야 한다.', 3456);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6100, '① 보호관찰관은 법 제31조의3제2항에 따라 부착명령을 집행하는 경우 같은 조 제1항에 따라 송부된 전자장치 보석피고인에 대한 결정문 등본(제23조의3에 따른 사본을 포함한다)을 확인한 후 전자장치를 부착해야 한다.', 3459);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6101, '② 보호관찰관은 제1항에 따라 전자장치를 부착하기 전에 전자장치 보석피고인에게 다음 각 호의 내용을 알려주어야 한다.', 3459);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6102, '③ 전자장치의 부착은 다음 각 호의 방법으로 한다.', 3459);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6103, '④ 보호관찰소의 장은 법 제31조의3제3항에 따라 피고인의 보석조건 이행 여부를 확인하기 위하여 국가기관, 지방자치단체 또는 공공기관의 장에게 사실을 알아보거나 관련 자료의 열람 등 협조를 요청할 수 있다. 이 경우 해당 기관의 장은 특별한 사정이 없는 한 이에 협조해야 한다. <신설 2021.9.14>', 3459);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6104, '① 보호관찰소의 장은 법 제31조의4제1항에 따라 피고인의 보석조건 이행상황을 매월 말일을 기준으로 작성하여 그 다음달 10일까지 보석결정을 한 법원에 송부해야 한다.', 3460);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6105, '② 제1항에도 불구하고 법원은 피고인의 재판을 위해 피고인의 보석조건 이행상황을 신속하게 파악할 필요가 있는 경우에는 보호관찰소의 장에게 피고인의 보석조건 이행상황에 관한 자료를 요청할 수 있다.', 3460);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6106, '① 보호관찰소의 장은 전자장치 보석피고인이 다음 각 호의 어느 하나에 해당하는 경우 법 제31조의4제2항에 따라 보석결정을 한 법원과 그 법원에 대응하는 검찰청 검사에게 지체 없이 통지해야 한다.', 3461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6107, '② 제1항에 따른 통지는 인편 또는 등기우편의 방법으로 한다. 다만, 긴급한 경우에는 전화ㆍ팩스ㆍ전자우편 등의 방법으로 먼저 통지하고 사후에 인편 또는 등기우편의 방법으로 할 수 있다.', 3461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6108, null, 3464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6109, '① 법 제31조의6제2항에서 "대통령령으로 정하는 신상정보 등"이란 다음 각 호의 사항을 말한다.', 3465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6110, '② 전자장치 스토킹행위자는 전자장치 부착의 집행 중 제1항제1호, 제2호 및 제4호부터 제6호까지의 사항이 변경된 경우에는 주거지를 관할하는 보호관찰소의 장에게 전화 등의 방법으로 지체 없이 그 사실을 신고해야 한다.', 3465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6111, '③ 전자장치 스토킹행위자는 전자장치 부착의 집행 중 제1항제3호의 사항이 변경된 경우에는 지체 없이 주거지를 관할하는 보호관찰소에 출석하여 그 사실을 신고해야 한다.', 3465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6112, '④ 제3항에도 불구하고 전자장치 스토킹행위자는 전자장치 부착의 집행 중 다른 보호관찰소의 관할 구역으로 주거지를 이전한 경우에는 3일 이내에 새로운 주거지를 관할하는 보호관찰소에 출석하여 제1항 각 호의 사항을 서면으로 신고해야 한다.', 3465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6113, '⑤ 전자장치 스토킹행위자의 주거지를 관할하는 보호관찰소(이하 이 장에서 "보호관찰소"라 한다)의 장은 제2항부터 제4항까지의 규정에 따른 신고를 받은 경우에는 관할경찰관서의 장에게 지체 없이 그 사실을 통지해야 한다.', 3465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6114, '① 보호관찰관은 법 제31조의6제2항에 따라 전자장치를 부착하는 경우 같은 조 제1항에 따라 송부된 전자장치 스토킹행위자에 대한 결정문 등본(제23조의10에 따른 사본을 포함한다)을 확인한 후 전자장치를 부착해야 한다.', 3466);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6115, '② 보호관찰관은 제1항에 따라 전자장치를 부착하기 전에 전자장치 스토킹행위자에게 전자장치 효용 유지를 위해 필요한 다음 각 호의 의무 사항을 알려주어야 한다.', 3466);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6116, '③ 보호관찰관은 제1항에 따라 전자장치를 부착하면 지체 없이 전자장치 스토킹행위자와 피해자가 서로 근접하는지 여부를 확인할 수 있는 장치 또는 시스템(이하 이 항에서 "피해자장치등"이라 한다)을 피해자에게 제공해야 한다. 다만, 피해자와 연락이 되지 않거나 피해자가 피해자장치등의 수령을 거부하는 등의 사유로 피해자장치등을 제공할 수 없는 경우에는 피해자 보호 업무를 담당하는 사법경찰관리에게 휴대전화 문자전송, 전자우편, 팩스 또는 전화 등의 방법으로 지체 없이 그 사실을 통지해야 한다.', 3466);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6117, '① 보호관찰소의 장은 법 제31조의6제3항 각 호 외의 부분에 따라 관할경찰관서의 장에게 전자장치 스토킹행위자가 전자장치를 부착한 사실을 통지할 때에는 제23조의11제1항 각 호의 사항과 그 밖에 피해자 보호를 위해 필요한 사항을 함께 통지해야 한다.', 3467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6118, '② 법 제31조의6제3항제6호에서 "대통령령으로 정하는 피해자의 보호를 위하여 필요한 사항"이란 다음 각 호의 사항을 말한다.', 3467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6119, '③ 관할경찰관서의 장은 전자장치 부착의 집행 중 법 제31조의6제3항 각 호의 사항이 변경된 것을 안 때에는 보호관찰소의 장에게 즉시 그 사실을 통지해야 한다.', 3467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6120, '① 법 제31조의6제4항제4호에서 "대통령령으로 정하는 사유가 있는 경우"란 다음 각 호의 경우를 말한다.', 3468);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6121, '② 보호관찰소의 장 또는 위치추적 관제센터의 장은 전자장치 스토킹행위자가 법 제31조의6제4항 각 호의 어느 하나에 해당하는 경우에는 관할경찰관서의 장 또는 시ㆍ도경찰청 112치안종합상황실장에게 휴대전화 문자전송, 전자우편, 팩스 또는 전화 등의 방법으로 즉시 그 사실을 통지해야 한다.', 3468);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6122, '③ 제1항 및 제2항에서 규정한 사항 외에 피해자의 보호 방법 및 절차 등에 관한 세부 사항은 경찰청장이 법무부장관과 협의하여 정한다.', 3468);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6123, null, 3472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6124, '① 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제1호 및 제3항제1호에 따라 성폭력범죄를 저질러 2008년 9월 1일 이전에 제1심판결을 선고받아 2010년 7월 16일 기준으로 징역형 이상의 형, 치료감호 또는 보호감호(이하 "징역형등"이라 한다)의 집행 종료일까지 6개월 이상이 남은 사람(이하 "출소예정자"라 한다), 징역형등의 집행 종료일까지 6개월 미만이 남은 사람(이하 "출소임박자"라 한다) 및 징역형등의 집행이 종료, 가종료ㆍ가출소ㆍ가석방 또는 면제된 후 3년이 경과되지 아니한 사람(이하 "출소자"라 한다)에 대하여 교도소ㆍ구치소ㆍ치료감호시설ㆍ보호감호시설(이하 "수용시설"이라 한다)의 장이 수용시설의 소재지를 관할하는 지방검찰청의 검사에게 통보하여야 할 사항은 다음 각 호와 같다.', 3474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6125, '② 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제1호 및 제3항제1호에 따라 성폭력범죄를 저질러 2008년 9월 1일 이전에 제1심판결을 선고받아 2010년 7월 16일 기준으로 출소예정자, 출소임박자, 출소자(이하 "출소자등"이라 한다)인 사람에 대하여 수용시설의 장이 수용시설의 소재지를 관할하는 보호관찰소의 장에게 통보하여야 할 사항은 출소자등의 성명, 주민등록번호, 주소, 출소예정일 및 죄명으로 한다.', 3474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6126, '① 법원은 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제5호 및 제3항제8호에 따라 출소자등에 대하여 부착명령을 결정한 경우에는 부착명령을 받은 사람에게 그 결정을 고지하여야 한다.', 3477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6127, '② 법원은 제1항에 따라 결정이 고지된 날부터 3일 이내에 부착명령을 고지받은 사람의 주거지를 관할하는 보호관찰소의 장에게 결정문 등본을 송부하여야 한다.', 3477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6128, '③ 수용시설의 장은 부착명령을 고지받은 사람이 석방되기 5일 전까지 그의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다.', 3477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6129, '① 출소자등에 대한 부착명령은 부착명령이 고지된 후 지체 없이 검사의 지휘를 받아 보호관찰관이 집행한다.', 3478);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6130, '② 제1항에 따른 지휘는 결정문 등본을 첨부한 서면으로 한다.', 3478);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6131, '① 법무부장관은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 3479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6132, '② 검사는 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호 또는 제2호에 따른 유전정보 또는 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. 다만, 제9호의2의 사무의 경우에는 「개인정보 보호법」 제23조에 따른 성생활에 관한 정보 및 같은 법 시행령 제18조제1호에 따른 유전정보에 해당하는 정보는 제외한다. <개정 2021.9.14, 2024.1.9>', 3479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6133, '③ 보호관찰소의 장 또는 보호관찰관은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호 또는 제2호에 따른 유전정보 또는 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. 다만, 제16호의2 및 제16호의3의 사무의 경우에는 「개인정보 보호법」 제23조에 따른 성생활에 관한 정보 및 같은 법 시행령 제18조제1호에 따른 유전정보에 해당하는 정보는 제외한다. <개정 2021.9.14, 2024.1.9>', 3479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6134, '④ 심사위원회는 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호 또는 제2호에 따른 유전정보 또는 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 3479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6135, '⑤ 치료감호심의위원회는 법 제23조 및 제24조에 따른 전자장치 부착에 관한 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호 또는 제2호에 따른 유전정보 또는 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 3479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6136, '⑥ 수용기관의 장 또는 수용시설의 장은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 3479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6137, '⑦ 경찰관서의 장 등 수사기관은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2024.1.9>', 3479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6138, '⑧ 사법경찰관은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2024.1.9>', 3479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6139, '① 검사와 사법경찰관은 모든 수사과정에서 헌법과 법률에 따라 보장되는 피의자와 그 밖의 피해자ㆍ참고인 등(이하 "사건관계인"이라 한다)의 권리를 보호하고, 적법한 절차에 따라야 한다.', 3482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6140, '② 검사와 사법경찰관은 예단(豫斷)이나 편견 없이 신속하게 수사해야 하고, 주어진 권한을 자의적으로 행사하거나 남용해서는 안 된다.', 3482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6141, '③ 검사와 사법경찰관은 수사를 할 때 다음 각 호의 사항에 유의하여 실체적 진실을 발견해야 한다.', 3482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6142, '④ 검사와 사법경찰관은 다른 사건의 수사를 통해 확보된 증거 또는 자료를 내세워 관련이 없는 사건에 대한 자백이나 진술을 강요해서는 안 된다.', 3482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6143, '① 검사와 사법경찰관은 공소제기 전의 형사사건에 관한 내용을 공개해서는 안 된다.', 3484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6144, '② 검사와 사법경찰관은 수사의 전(全) 과정에서 피의자와 사건관계인의 사생활의 비밀을 보호하고 그들의 명예나 신용이 훼손되지 않도록 노력해야 한다.', 3484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6145, '③ 제1항에도 불구하고 법무부장관, 경찰청장 또는 해양경찰청장은 무죄추정의 원칙과 국민의 알권리 등을 종합적으로 고려하여 형사사건 공개에 관한 준칙을 정할 수 있다.', 3484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6146, '① 검사와 사법경찰관은 상호 존중해야 하며, 수사, 공소제기 및 공소유지와 관련하여 협력해야 한다.', 3485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6147, '② 검사와 사법경찰관은 수사와 공소제기 및 공소유지를 위해 필요한 경우 수사ㆍ기소ㆍ재판 관련 자료를 서로 요청할 수 있다.', 3485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6148, '③ 검사와 사법경찰관의 협의는 신속히 이루어져야 하며, 협의의 지연 등으로 수사 또는 관련 절차가 지연되어서는 안 된다.', 3485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6149, '① 검사와 사법경찰관은 다음 각 호의 어느 하나에 해당하는 사건(이하 "중요사건"이라 한다)의 경우에는 송치 전에 수사할 사항, 증거 수집의 대상, 법령의 적용, 범죄수익 환수를 위한 조치 등에 관하여 상호 의견을 제시ㆍ교환할 것을 요청할 수 있다. 이 경우 검사와 사법경찰관은 특별한 사정이 없으면 상대방의 요청에 응해야 한다.', 3486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6150, '② 제1항에도 불구하고 검사와 사법경찰관은 다음 각 호의 어느 하나에 따른 공소시효가 적용되는 사건에 대해서는 공소시효 만료일 3개월 전까지 제1항 각 호 외의 부분 전단에 규정된 사항 등에 관하여 상호 의견을 제시ㆍ교환해야 한다. 다만, 공소시효 만료일 전 3개월 이내에 수사를 개시한 때에는 지체 없이 상호 의견을 제시ㆍ교환해야 한다.', 3486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6151, '① 검사와 사법경찰관은 수사와 사건의 송치, 송부 등에 관한 이견의 조정이나 협력 등이 필요한 경우 서로 협의를 요청할 수 있다. 이 경우 특별한 사정이 없으면 상대방의 협의 요청에 응해야 한다. <개정 2023.10.17>', 3487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6152, '② 제1항에 따른 협의에도 불구하고 이견이 해소되지 않는 경우로서 다음 각 호의 어느 하나에 해당하는 경우에는 해당 검사가 소속된 검찰청의 장과 해당 사법경찰관이 소속된 경찰관서(지방해양경찰관서를 포함한다. 이하 같다)의 장의 협의에 따른다. <개정 2023.10.17>', 3487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6153, '① 대검찰청, 경찰청 및 해양경찰청 간에 수사에 관한 제도 개선 방안 등을 논의하고, 수사기관 간 협조가 필요한 사항에 대해 서로 의견을 협의ㆍ조정하기 위해 수사기관협의회를 둔다.', 3488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6154, '② 수사기관협의회는 다음 각 호의 사항에 대해 협의ㆍ조정한다.', 3488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6155, '③ 수사기관협의회는 반기마다 정기적으로 개최하되, 제1항의 어느 한 기관이 요청하면 수시로 개최할 수 있다.', 3488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6156, '④ 제1항의 각 기관은 수사기관협의회에서 협의ㆍ조정된 사항의 세부 추진계획을 수립ㆍ시행해야 한다.', 3488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6157, '⑤ 제1항부터 제4항까지의 규정에서 정한 사항 외에 수사기관협의회의 운영 등에 필요한 사항은 수사기관협의회에서 정한다.', 3488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6158, '① 검사와 사법경찰관은 수사를 할 때 수사 대상자의 자유로운 의사에 따른 임의수사를 원칙으로 해야 하고, 강제수사는 법률에서 정한 바에 따라 필요한 경우에만 최소한의 범위에서 하되, 수사 대상자의 권익 침해의 정도가 더 적은 절차와 방법을 선택해야 한다.', 3489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6159, '② 검사와 사법경찰관은 피의자를 체포ㆍ구속하는 과정에서 피의자 및 현장에 있는 가족 등 지인들의 인격과 명예를 침해하지 않도록 유의해야 한다.', 3489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6160, '③ 검사와 사법경찰관은 압수ㆍ수색 과정에서 사생활의 비밀, 주거의 평온을 최대한 보장하고, 피의자 및 현장에 있는 가족 등 지인들의 인격과 명예를 침해하지 않도록 유의해야 한다.', 3489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6161, '① 검사 또는 사법경찰관은 수사에 대한 진행상황을 사건관계인에게 적절히 통지하도록 노력해야 한다.', 3491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6162, '② 제1항에 따른 통지의 구체적인 방법ㆍ절차 등은 법무부장관, 경찰청장 또는 해양경찰청장이 정한다.', 3491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6163, '① 검사 또는 사법경찰관은 피의자신문에 참여한 변호인이 피의자의 옆자리 등 실질적인 조력을 할 수 있는 위치에 앉도록 해야 하고, 정당한 사유가 없으면 피의자에 대한 법적인 조언ㆍ상담을 보장해야 하며, 법적인 조언ㆍ상담을 위한 변호인의 메모를 허용해야 한다.', 3492);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6164, '② 검사 또는 사법경찰관은 피의자에 대한 신문이 아닌 단순 면담 등이라는 이유로 변호인의 참여ㆍ조력을 제한해서는 안 된다.', 3492);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6165, '③ 제1항 및 제2항은 검사 또는 사법경찰관의 사건관계인에 대한 조사ㆍ면담 등의 경우에도 적용한다.', 3492);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6166, '① 피의자신문에 참여한 변호인은 검사 또는 사법경찰관의 신문 후 조서를 열람하고 의견을 진술할 수 있다. 이 경우 변호인은 별도의 서면으로 의견을 제출할 수 있으며, 검사 또는 사법경찰관은 해당 서면을 사건기록에 편철한다.', 3493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6167, '② 피의자신문에 참여한 변호인은 신문 중이라도 검사 또는 사법경찰관의 승인을 받아 의견을 진술할 수 있다. 이 경우 검사 또는 사법경찰관은 정당한 사유가 있는 경우를 제외하고는 변호인의 의견진술 요청을 승인해야 한다.', 3493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6168, '③ 피의자신문에 참여한 변호인은 제2항에도 불구하고 부당한 신문방법에 대해서는 검사 또는 사법경찰관의 승인 없이 이의를 제기할 수 있다.', 3493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6169, '④ 검사 또는 사법경찰관은 제1항부터 제3항까지의 규정에 따른 의견진술 또는 이의제기가 있는 경우 해당 내용을 조서에 적어야 한다.', 3493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6170, '① 검사 또는 사법경찰관은 피해자의 명예와 사생활의 평온을 보호하기 위해 「범죄피해자 보호법」 등 피해자 보호 관련 법령의 규정을 준수해야 한다.', 3494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6171, '② 검사 또는 사법경찰관은 피의자의 범죄수법, 범행 동기, 피해자와의 관계, 언동 및 그 밖의 상황으로 보아 피해자가 피의자 또는 그 밖의 사람으로부터 생명ㆍ신체에 위해를 입거나 입을 염려가 있다고 인정되는 경우에는 직권 또는 피해자의 신청에 따라 신변보호에 필요한 조치를 강구해야 한다.', 3494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6172, '① 검사 또는 사법경찰관이 다음 각 호의 어느 하나에 해당하는 행위에 착수한 때에는 수사를 개시한 것으로 본다. 이 경우 검사 또는 사법경찰관은 해당 사건을 즉시 입건해야 한다.', 3495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6173, '② 검사 또는 사법경찰관은 수사 중인 사건의 범죄 혐의를 밝히기 위한 목적으로 관련 없는 사건의 수사를 개시하거나 수사기간을 부당하게 연장해서는 안 된다.', 3495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6174, '③ 검사 또는 사법경찰관은 입건 전에 범죄를 의심할 만한 정황이 있어 수사 개시 여부를 결정하기 위한 사실관계의 확인 등 필요한 조사를 할 때에는 적법절차를 준수하고 사건관계인의 인권을 존중하며, 조사가 부당하게 장기화되지 않도록 신속하게 진행해야 한다.', 3495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6175, '④ 검사 또는 사법경찰관은 제3항에 따른 조사 결과 입건하지 않는 결정을 한 때에는 피해자에 대한 보복범죄나 2차 피해가 우려되는 경우 등을 제외하고는 피혐의자 및 사건관계인에게 통지해야 한다.', 3495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6176, '⑤ 제4항에 따른 통지의 구체적인 방법 및 절차 등은 법무부장관, 경찰청장 또는 해양경찰청장이 정한다.', 3495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6177, '⑥ 제3항에 따른 조사와 관련한 서류 등의 열람 및 복사에 관하여는 제69조제1항, 제3항, 제5항(같은 조 제1항 및 제3항을 준용하는 부분으로 한정한다. 이하 이 항에서 같다) 및 제6항(같은 조 제1항, 제3항 및 제5항에 따른 신청을 받은 경우로 한정한다)을 준용한다.', 3495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6178, '① 검사 또는 사법경찰관은 고소 또는 고발을 받은 경우에는 이를 수리해야 한다.', 3496);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6179, '② 검사 또는 사법경찰관은 고소 또는 고발에 따라 범죄를 수사하는 경우에는 고소 또는 고발을 수리한 날부터 3개월 이내에 수사를 마쳐야 한다.', 3496);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6180, '① 사법경찰관은 변사자 또는 변사한 것으로 의심되는 사체가 있으면 변사사건 발생사실을 검사에게 통보해야 한다.', 3497);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6181, '② 검사는 법 제222조제1항에 따라 검시를 했을 경우에는 검시조서를, 검증영장이나 같은 조 제2항에 따라 검증을 했을 경우에는 검증조서를 각각 작성하여 사법경찰관에게 송부해야 한다.', 3497);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6182, '③ 사법경찰관은 법 제222조제1항 및 제3항에 따라 검시를 했을 경우에는 검시조서를, 검증영장이나 같은 조 제2항 및 제3항에 따라 검증을 했을 경우에는 검증조서를 각각 작성하여 검사에게 송부해야 한다.', 3497);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6183, '④ 검사와 사법경찰관은 법 제222조에 따라 변사자의 검시를 한 사건에 대해 사건 종결 전에 수사할 사항 등에 관하여 상호 의견을 제시ㆍ교환해야 한다.', 3497);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6184, '① 검사는 「검찰청법」 제4조제1항제1호 각 목에 해당되지 않는 범죄에 대한 고소ㆍ고발ㆍ진정 등이 접수된 때에는 사건을 검찰청 외의 수사기관에 이송해야 한다. <개정 2023.10.17>', 3498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6185, '② 검사는 다음 각 호의 어느 하나에 해당하는 때에는 사건을 검찰청 외의 수사기관에 이송할 수 있다.', 3498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6186, '③ 검사는 제1항 또는 제2항에 따라 사건을 이송하는 경우에는 관계 서류와 증거물을 해당 수사기관에 함께 송부해야 한다.', 3498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6187, '④ 검사는 제2항제2호에 따른 이송을 하는 경우에는 특별한 사정이 없으면 사건을 수리한 날부터 1개월 이내에 이송해야 한다. <신설 2023.10.17>', 3498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6188, '① 검사 또는 사법경찰관은 피의자에게 출석요구를 할 때에는 다음 각 호의 사항을 유의해야 한다.', 3499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6189, '② 검사 또는 사법경찰관은 피의자에게 출석요구를 하려는 경우 피의자와 조사의 일시ㆍ장소에 관하여 협의해야 한다. 이 경우 변호인이 있는 경우에는 변호인과도 협의해야 한다.', 3499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6190, '③ 검사 또는 사법경찰관은 피의자에게 출석요구를 하려는 경우 피의사실의 요지 등 출석요구의 취지를 구체적으로 적은 출석요구서를 발송해야 한다. 다만, 신속한 출석요구가 필요한 경우 등 부득이한 사정이 있는 경우에는 전화, 문자메시지, 그 밖의 상당한 방법으로 출석요구를 할 수 있다.', 3499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6191, '④ 검사 또는 사법경찰관은 제3항 본문에 따른 방법으로 출석요구를 했을 때에는 출석요구서의 사본을, 같은 항 단서에 따른 방법으로 출석요구를 했을 때에는 그 취지를 적은 수사보고서를 각각 사건기록에 편철한다.', 3499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6192, '⑤ 검사 또는 사법경찰관은 피의자가 치료 등 수사관서에 출석하여 조사를 받는 것이 현저히 곤란한 사정이 있는 경우에는 수사관서 외의 장소에서 조사할 수 있다.', 3499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6193, '⑥ 제1항부터 제5항까지의 규정은 피의자 외의 사람에 대한 출석요구의 경우에도 적용한다.', 3499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6194, '① 검사 또는 사법경찰관은 조사, 신문, 면담 등 그 명칭을 불문하고 피의자나 사건관계인에 대해 오후 9시부터 오전 6시까지 사이에 조사(이하 "심야조사"라 한다)를 해서는 안 된다. 다만, 이미 작성된 조서의 열람을 위한 절차는 자정 이전까지 진행할 수 있다.', 3501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6195, '② 제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 심야조사를 할 수 있다. 이 경우 심야조사의 사유를 조서에 명확하게 적어야 한다.', 3501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6196, '① 검사 또는 사법경찰관은 조사, 신문, 면담 등 그 명칭을 불문하고 피의자나 사건관계인을 조사하는 경우에는 대기시간, 휴식시간, 식사시간 등 모든 시간을 합산한 조사시간(이하 "총조사시간"이라 한다)이 12시간을 초과하지 않도록 해야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 예외로 한다.', 3502);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6197, '② 검사 또는 사법경찰관은 특별한 사정이 없으면 총조사시간 중 식사시간, 휴식시간 및 조서의 열람시간 등을 제외한 실제 조사시간이 8시간을 초과하지 않도록 해야 한다.', 3502);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6198, '③ 검사 또는 사법경찰관은 피의자나 사건관계인에 대한 조사를 마친 때부터 8시간이 지나기 전에는 다시 조사할 수 없다. 다만, 제1항제2호에 해당하는 경우에는 예외로 한다.', 3502);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6199, '① 검사 또는 사법경찰관은 조사에 상당한 시간이 소요되는 경우에는 특별한 사정이 없으면 피의자 또는 사건관계인에게 조사 도중에 최소한 2시간마다 10분 이상의 휴식시간을 주어야 한다.', 3503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6200, '② 검사 또는 사법경찰관은 조사 도중 피의자, 사건관계인 또는 그 변호인으로부터 휴식시간의 부여를 요청받았을 때에는 그때까지 조사에 소요된 시간, 피의자 또는 사건관계인의 건강상태 등을 고려해 적정하다고 판단될 경우 휴식시간을 주어야 한다.', 3503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6201, '③ 검사 또는 사법경찰관은 조사 중인 피의자 또는 사건관계인의 건강상태에 이상 징후가 발견되면 의사의 진료를 받게 하거나 휴식하게 하는 등 필요한 조치를 해야 한다.', 3503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6202, '① 법 제244조의5에 따라 피의자와 동석할 수 있는 신뢰관계에 있는 사람과 법 제221조제3항에서 준용하는 법 제163조의2에 따라 피해자와 동석할 수 있는 신뢰관계에 있는 사람은 피의자 또는 피해자의 직계친족, 형제자매, 배우자, 가족, 동거인, 보호ㆍ교육시설의 보호ㆍ교육담당자 등 피의자 또는 피해자의 심리적 안정과 원활한 의사소통에 도움을 줄 수 있는 사람으로 한다.', 3504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6203, '② 피의자, 피해자 또는 그 법정대리인이 제1항에 따른 신뢰관계에 있는 사람의 동석을 신청한 경우 검사 또는 사법경찰관은 그 관계를 적은 동석신청서를 제출받거나 조서 또는 수사보고서에 그 관계를 적어야 한다.', 3504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6204, '① 검사 또는 사법경찰관은 조사과정에서 피의자, 사건관계인 또는 그 변호인이 사실관계 등의 확인을 위해 자료를 제출하는 경우 그 자료를 수사기록에 편철한다.', 3505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6205, '② 검사 또는 사법경찰관은 조사를 종결하기 전에 피의자, 사건관계인 또는 그 변호인에게 자료 또는 의견을 제출할 의사가 있는지를 확인하고, 자료 또는 의견을 제출받은 경우에는 해당 자료 및 의견을 수사기록에 편철한다.', 3505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6206, '① 검사 또는 사법경찰관은 법 제244조의4에 따라 조사(신문, 면담 등 명칭을 불문한다. 이하 이 조에서 같다) 과정의 진행경과를 다음 각 호의 구분에 따른 방법으로 기록해야 한다.', 3506);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6207, '② 제1항에 따라 조사과정의 진행경과를 기록할 때에는 다음 각 호의 구분에 따른 사항을 구체적으로 적어야 한다.', 3506);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6208, '① 사법경찰관은 법 제200조의3제2항에 따라 긴급체포 후 12시간 내에 검사에게 긴급체포의 승인을 요청해야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 긴급체포 후 24시간 이내에 긴급체포의 승인을 요청해야 한다. <개정 2023.10.17>', 3507);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6209, '② 제1항에 따라 긴급체포의 승인을 요청할 때에는 범죄사실의 요지, 긴급체포의 일시ㆍ장소, 긴급체포의 사유, 체포를 계속해야 하는 사유 등을 적은 긴급체포 승인요청서로 요청해야 한다. 다만, 긴급한 경우에는 「형사사법절차 전자화 촉진법」 제2조제4호에 따른 형사사법정보시스템(이하 "형사사법정보시스템"이라 한다) 또는 팩스를 이용하여 긴급체포의 승인을 요청할 수 있다.', 3507);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6210, '③ 검사는 사법경찰관의 긴급체포 승인 요청이 이유 있다고 인정하는 경우에는 지체 없이 긴급체포 승인서를 사법경찰관에게 송부해야 한다.', 3507);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6211, '④ 검사는 사법경찰관의 긴급체포 승인 요청이 이유 없다고 인정하는 경우에는 지체 없이 사법경찰관에게 불승인 통보를 해야 한다. 이 경우 사법경찰관은 긴급체포된 피의자를 즉시 석방하고 그 석방 일시와 사유 등을 검사에게 통보해야 한다.', 3507);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6212, '① 검사 또는 사법경찰관은 법 제212조 또는 제213조에 따라 현행범인을 체포하거나 체포된 현행범인을 인수했을 때에는 조사가 현저히 곤란하다고 인정되는 경우가 아니면 지체 없이 조사해야 하며, 조사 결과 계속 구금할 필요가 없다고 인정할 때에는 현행범인을 즉시 석방해야 한다.', 3508);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6213, '② 검사 또는 사법경찰관은 제1항에 따라 현행범인을 석방했을 때에는 석방 일시와 사유 등을 적은 피의자 석방서를 작성해 사건기록에 편철한다. 이 경우 사법경찰관은 석방 후 지체 없이 검사에게 석방 사실을 통보해야 한다.', 3508);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6214, '① 검사 또는 사법경찰관은 구속영장을 청구하거나 신청하는 경우 법 제209조에서 준용하는 법 제70조제2항의 필요적 고려사항이 있을 때에는 구속영장 청구서 또는 신청서에 그 내용을 적어야 한다.', 3509);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6215, '② 검사 또는 사법경찰관은 체포한 피의자에 대해 구속영장을 청구하거나 신청할 때에는 구속영장 청구서 또는 신청서에 체포영장, 긴급체포서, 현행범인 체포서 또는 현행범인 인수서를 첨부해야 한다.', 3509);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6216, '① 검사 또는 사법경찰관은 피의자를 체포하거나 구속할 때에는 법 제200조의5(법 제209조에서 준용하는 경우를 포함한다)에 따라 피의자에게 피의사실의 요지, 체포ㆍ구속의 이유와 변호인을 선임할 수 있음을 말하고, 변명할 기회를 주어야 하며, 진술거부권을 알려주어야 한다.', 3512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6217, '② 제1항에 따라 피의자에게 알려주어야 하는 진술거부권의 내용은 법 제244조의3제1항제1호부터 제3호까지의 사항으로 한다.', 3512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6218, '③ 검사와 사법경찰관이 제1항에 따라 피의자에게 그 권리를 알려준 경우에는 피의자로부터 권리 고지 확인서를 받아 사건기록에 편철한다.', 3512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6219, '① 검사 또는 사법경찰관은 영장에 따라 피의자를 체포하거나 구속하는 경우에는 법 제200조의6 또는 제209조에서 준용하는 법 제85조제1항 또는 제4항에 따라 피의자에게 반드시 영장을 제시하고 그 사본을 교부해야 한다.', 3513);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6220, '② 검사 또는 사법경찰관은 제1항에 따라 피의자에게 영장을 제시하거나 영장의 사본을 교부할 때에는 사건관계인의 개인정보가 피의자의 방어권 보장을 위해 필요한 정도를 넘어 불필요하게 노출되지 않도록 유의해야 한다.', 3513);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6221, '③ 검사 또는 사법경찰관은 제1항에 따라 피의자에게 영장의 사본을 교부한 경우에는 피의자로부터 영장 사본 교부 확인서를 받아 사건기록에 편철한다.', 3513);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6222, '④ 피의자가 영장의 사본을 수령하기를 거부하거나 영장 사본 교부 확인서에 기명날인 또는 서명하는 것을 거부하는 경우에는 검사 또는 사법경찰관이 영장 사본 교부 확인서 끝 부분에 그 사유를 적고 기명날인 또는 서명해야 한다.', 3513);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6223, '① 검사 또는 사법경찰관은 피의자를 체포하거나 구속하였을 때에는 법 제200조의6 또는 제209조에서 준용하는 법 제87조에 따라 변호인이 있으면 변호인에게, 변호인이 없으면 법 제30조제2항에 따른 사람 중 피의자가 지정한 사람에게 24시간 이내에 서면으로 사건명, 체포ㆍ구속의 일시ㆍ장소, 범죄사실의 요지, 체포ㆍ구속의 이유와 변호인을 선임할 수 있음을 통지해야 한다.', 3514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6224, '② 검사 또는 사법경찰관은 제1항에 따른 통지를 하였을 때에는 그 통지서 사본을 사건기록에 편철한다. 다만, 변호인 및 법 제30조제2항에 따른 사람이 없어서 체포ㆍ구속의 통지를 할 수 없을 때에는 그 취지를 수사보고서에 적어 사건기록에 편철한다.', 3514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6225, '③ 제1항 및 제2항은 법 제214조의2제2항에 따라 검사 또는 사법경찰관이 같은 조 제1항에 따른 자 중에서 피의자가 지정한 자에게 체포 또는 구속의 적부심사를 청구할 수 있음을 통지하는 경우에도 준용한다.', 3514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6226, '① 검사 또는 사법경찰관은 체포ㆍ구속영장의 유효기간 내에 영장의 집행에 착수하지 못했거나, 그 밖의 사유로 영장의 집행이 불가능하거나 불필요하게 되었을 때에는 즉시 해당 영장을 법원에 반환해야 한다. 이 경우 체포ㆍ구속영장이 여러 통 발부된 경우에는 모두 반환해야 한다.', 3516);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6227, '② 검사 또는 사법경찰관은 제1항에 따라 체포ㆍ구속영장을 반환하는 경우에는 반환사유 등을 적은 영장반환서에 해당 영장을 첨부하여 반환하고, 그 사본을 사건기록에 편철한다.', 3516);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6228, '③ 제1항에 따라 사법경찰관이 체포ㆍ구속영장을 반환하는 경우에는 그 영장을 청구한 검사에게 반환하고, 검사는 사법경찰관이 반환한 영장을 법원에 반환한다.', 3516);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6229, '① 검사 또는 사법경찰관은 법 제200조의2제5항 또는 제200조의4제2항에 따라 구속영장을 청구하거나 신청하지 않고(사법경찰관이 구속영장의 청구를 신청하였으나 검사가 그 신청을 기각한 경우를 포함한다) 체포 또는 긴급체포한 피의자를 석방하려는 때에는 다음 각 호의 구분에 따른 사항을 적은 피의자 석방서를 작성해야 한다. <개정 2023.10.17>', 3517);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6230, '② 사법경찰관은 제1항에 따라 피의자를 석방한 경우 다음 각 호의 구분에 따라 처리한다. <개정 2023.10.17>', 3517);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6231, '① 검사 또는 사법경찰관은 법 제219조에서 준용하는 법 제118조에 따라 영장을 제시할 때에는 처분을 받는 자에게 법관이 발부한 영장에 따른 압수ㆍ수색 또는 검증이라는 사실과 영장에 기재된 범죄사실 및 수색 또는 검증할 장소ㆍ신체ㆍ물건, 압수할 물건 등을 명확히 알리고, 처분을 받는 자가 해당 영장을 열람할 수 있도록 해야 한다. 이 경우 처분을 받는 자가 피의자인 경우에는 해당 영장의 사본을 교부해야 한다. <개정 2023.10.17>', 3519);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6232, '② 압수ㆍ수색 또는 검증의 처분을 받는 자가 여럿인 경우에는 모두에게 개별적으로 영장을 제시해야 한다. 이 경우 피의자에게는 개별적으로 해당 영장의 사본을 교부해야 한다. <개정 2023.10.17>', 3519);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6233, '③ 검사 또는 사법경찰관은 제1항 및 제2항에 따라 피의자에게 영장을 제시하거나 영장의 사본을 교부할 때에는 사건관계인의 개인정보가 피의자의 방어권 보장을 위해 필요한 정도를 넘어 불필요하게 노출되지 않도록 유의해야 한다. <신설 2023.10.17>', 3519);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6234, '④ 검사 또는 사법경찰관은 제1항 후단 및 제2항 후단에 따라 피의자에게 영장의 사본을 교부한 경우에는 피의자로부터 영장 사본 교부 확인서를 받아 사건기록에 편철한다. <신설 2023.10.17>', 3519);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6235, '⑤ 피의자가 영장의 사본을 수령하기를 거부하거나 영장 사본 교부 확인서에 기명날인 또는 서명하는 것을 거부하는 경우에는 검사 또는 사법경찰관이 영장 사본 교부 확인서 끝 부분에 그 사유를 적고 기명날인 또는 서명해야 한다. <신설 2023.10.17>', 3519);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6236, '① 검사 또는 사법경찰관은 법 제219조에서 준용하는 법 제106조제3항에 따라 컴퓨터용디스크 및 그 밖에 이와 비슷한 정보저장매체(이하 이 항에서 "정보저장매체등"이라 한다)에 기억된 정보(이하 "전자정보"라 한다)를 압수하는 경우에는 해당 정보저장매체등의 소재지에서 수색 또는 검증한 후 범죄사실과 관련된 전자정보의 범위를 정하여 출력하거나 복제하는 방법으로 한다.', 3522);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6237, '② 제1항에도 불구하고 제1항에 따른 압수 방법의 실행이 불가능하거나 그 방법으로는 압수의 목적을 달성하는 것이 현저히 곤란한 경우에는 압수ㆍ수색 또는 검증 현장에서 정보저장매체등에 들어 있는 전자정보 전부를 복제하여 그 복제본을 정보저장매체등의 소재지 외의 장소로 반출할 수 있다.', 3522);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6238, '③ 제1항 및 제2항에도 불구하고 제1항 및 제2항에 따른 압수 방법의 실행이 불가능하거나 그 방법으로는 압수의 목적을 달성하는 것이 현저히 곤란한 경우에는 피압수자 또는 법 제123조에 따라 압수ㆍ수색영장을 집행할 때 참여하게 해야 하는 사람(이하 "피압수자등"이라 한다)이 참여한 상태에서 정보저장매체등의 원본을 봉인(封印)하여 정보저장매체등의 소재지 외의 장소로 반출할 수 있다.', 3522);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6239, '① 검사 또는 사법경찰관은 전자정보의 탐색ㆍ복제ㆍ출력을 완료한 경우에는 지체 없이 피압수자등에게 압수한 전자정보의 목록을 교부해야 한다.', 3523);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6240, '② 검사 또는 사법경찰관은 제1항의 목록에 포함되지 않은 전자정보가 있는 경우에는 해당 전자정보를 지체 없이 삭제 또는 폐기하거나 반환해야 한다. 이 경우 삭제ㆍ폐기 또는 반환확인서를 작성하여 피압수자등에게 교부해야 한다.', 3523);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6241, '③ 검사 또는 사법경찰관은 전자정보의 복제본을 취득하거나 전자정보를 복제할 때에는 해시값(파일의 고유값으로서 일종의 전자지문을 말한다)을 확인하거나 압수ㆍ수색 또는 검증의 과정을 촬영하는 등 전자적 증거의 동일성과 무결성(無缺性)을 보장할 수 있는 적절한 방법과 조치를 취해야 한다.', 3523);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6242, '④ 검사 또는 사법경찰관은 압수ㆍ수색 또는 검증의 전 과정에 걸쳐 피압수자등이나 변호인의 참여권을 보장해야 하며, 피압수자등과 변호인이 참여를 거부하는 경우에는 신뢰성과 전문성을 담보할 수 있는 상당한 방법으로 압수ㆍ수색 또는 검증을 해야 한다.', 3523);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6243, '⑤ 검사 또는 사법경찰관은 제4항에 따라 참여한 피압수자등이나 변호인이 압수 대상 전자정보와 사건의 관련성에 관하여 의견을 제시한 때에는 이를 조서에 적어야 한다.', 3523);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6244, '① 검사는 법 제197조의3제1항에 따라 사법경찰관에게 사건기록 등본의 송부를 요구할 때에는 그 내용과 이유를 구체적으로 적은 서면으로 해야 한다.', 3526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6245, '② 사법경찰관은 제1항에 따른 요구를 받은 날부터 7일 이내에 사건기록 등본을 검사에게 송부해야 한다.', 3526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6246, '③ 검사는 제2항에 따라 사건기록 등본을 송부받은 날부터 30일(사안의 경중 등을 고려하여 10일의 범위에서 한 차례 연장할 수 있다) 이내에 법 제197조의3제3항에 따른 시정조치 요구 여부를 결정하여 사법경찰관에게 통보해야 한다. 이 경우 시정조치 요구의 통보는 그 내용과 이유를 구체적으로 적은 서면으로 해야 한다.', 3526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6247, '④ 사법경찰관은 제3항에 따라 시정조치 요구를 통보받은 경우 정당한 이유가 있는 경우를 제외하고는 지체 없이 시정조치를 이행하고, 그 이행 결과를 서면에 구체적으로 적어 검사에게 통보해야 한다.', 3526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6248, '⑤ 검사는 법 제197조의3제5항에 따라 사법경찰관에게 사건송치를 요구하는 경우에는 그 내용과 이유를 구체적으로 적은 서면으로 해야 한다.', 3526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6249, '⑥ 사법경찰관은 제5항에 따라 서면으로 사건송치를 요구받은 날부터 7일 이내에 사건을 검사에게 송치해야 한다. 이 경우 관계 서류와 증거물을 함께 송부해야 한다.', 3526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6250, '⑦ 제5항 및 제6항에도 불구하고 검사는 공소시효 만료일의 임박 등 특별한 사유가 있을 때에는 제5항에 따른 서면에 그 사유를 명시하고 별도의 송치기한을 정하여 사법경찰관에게 통지할 수 있다. 이 경우 사법경찰관은 정당한 이유가 있는 경우를 제외하고는 통지받은 송치기한까지 사건을 검사에게 송치해야 한다.', 3526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6251, '① 검찰총장 또는 각급 검찰청 검사장은 법 제197조의3제7항에 따라 사법경찰관리의 징계를 요구할 때에는 서면에 그 사유를 구체적으로 적고 이를 증명할 수 있는 관계 자료를 첨부하여 해당 사법경찰관리가 소속된 경찰관서의 장(이하 "경찰관서장"이라 한다)에게 통보해야 한다.', 3527);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6252, '② 경찰관서장은 제1항에 따른 징계요구에 대한 처리 결과와 그 이유를 징계를 요구한 검찰총장 또는 각급 검찰청 검사장에게 통보해야 한다.', 3527);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6253, '① 검사와 사법경찰관은 법 제197조의4에 따른 수사의 경합과 관련하여 동일한 범죄사실 여부나 영장(「통신비밀보호법」 제6조 및 제8조에 따른 통신제한조치허가서 및 같은 법 제13조에 따른 통신사실 확인자료제공 요청 허가서를 포함한다. 이하 이 조에서 같다) 청구ㆍ신청의 시간적 선후관계 등을 판단하기 위해 필요한 경우에는 그 필요한 범위에서 사건기록의 상호 열람을 요청할 수 있다.', 3529);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6254, '② 제1항에 따른 영장 청구ㆍ신청의 시간적 선후관계는 검사의 영장청구서와 사법경찰관의 영장신청서가 각각 법원과 검찰청에 접수된 시점을 기준으로 판단한다.', 3529);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6255, '③ 검사는 제2항에 따른 사법경찰관의 영장신청서의 접수를 거부하거나 지연해서는 안 된다.', 3529);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6256, '① 검사는 법 제197조의4제1항에 따라 사법경찰관에게 사건송치를 요구할 때에는 그 내용과 이유를 구체적으로 적은 서면으로 해야 한다.', 3530);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6257, '② 사법경찰관은 제1항에 따른 요구를 받은 날부터 7일 이내에 사건을 검사에게 송치해야 한다. 이 경우 관계 서류와 증거물을 함께 송부해야 한다.', 3530);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6258, '① 사법경찰관은 사건을 수사한 경우에는 다음 각 호의 구분에 따라 결정해야 한다.', 3532);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6259, '② 사법경찰관은 하나의 사건 중 피의자가 여러 사람이거나 피의사실이 여러 개인 경우로서 분리하여 결정할 필요가 있는 경우 그중 일부에 대해 제1항 각 호의 결정을 할 수 있다.', 3532);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6260, '③ 사법경찰관은 제1항제3호나목 또는 다목에 해당하는 사건이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 사건을 검사에게 이송한다. <개정 2023.10.17>', 3532);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6261, '④ 사법경찰관은 제1항제4호에 따른 수사중지 결정을 한 경우 7일 이내에 사건기록을 검사에게 송부해야 한다. 이 경우 검사는 사건기록을 송부받은 날부터 30일 이내에 반환해야 하며, 그 기간 내에 법 제197조의3에 따라 시정조치요구를 할 수 있다.', 3532);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6262, '⑤ 사법경찰관은 제4항 전단에 따라 검사에게 사건기록을 송부한 후 피의자 등의 소재를 발견한 경우에는 소재 발견 및 수사 재개 사실을 검사에게 통보해야 한다. 이 경우 통보를 받은 검사는 지체 없이 사법경찰관에게 사건기록을 반환해야 한다.', 3532);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6263, '① 검사는 사법경찰관으로부터 사건을 송치받거나 직접 수사한 경우에는 다음 각 호의 구분에 따라 결정해야 한다.', 3533);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6264, '② 검사는 하나의 사건 중 피의자가 여러 사람이거나 피의사실이 여러 개인 경우로서 분리하여 결정할 필요가 있는 경우 그중 일부에 대해 제1항 각 호의 결정을 할 수 있다.', 3533);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6265, '① 검사 또는 사법경찰관은 제51조 또는 제52조에 따른 결정을 한 경우에는 그 내용을 고소인ㆍ고발인ㆍ피해자 또는 그 법정대리인(피해자가 사망한 경우에는 그 배우자ㆍ직계친족ㆍ형제자매를 포함한다. 이하 "고소인등"이라 한다)과 피의자에게 통지해야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 고소인등에게만 통지한다. <개정 2023.10.17>', 3534);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6266, '② 고소인등은 법 제245조의6에 따른 통지를 받지 못한 경우 사법경찰관에게 불송치 통지서로 통지해 줄 것을 요구할 수 있다.', 3534);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6267, '③ 제1항에 따른 통지의 구체적인 방법ㆍ절차 등은 법무부장관, 경찰청장 또는 해양경찰청장이 정한다.', 3534);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6268, '① 제53조에 따라 사법경찰관으로부터 제51조제1항제4호에 따른 수사중지 결정의 통지를 받은 사람은 해당 사법경찰관이 소속된 바로 위 상급경찰관서의 장에게 이의를 제기할 수 있다.', 3535);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6269, '② 제1항에 따른 이의제기의 절차ㆍ방법 및 처리 등에 관하여 필요한 사항은 경찰청장 또는 해양경찰청장이 정한다.', 3535);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6270, '③ 제1항에 따른 통지를 받은 사람은 해당 수사중지 결정이 법령위반, 인권침해 또는 현저한 수사권 남용이라고 의심되는 경우 검사에게 법 제197조의3제1항에 따른 신고를 할 수 있다.', 3535);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6271, '④ 사법경찰관은 제53조에 따라 고소인등에게 제51조제1항제4호에 따른 수사중지 결정의 통지를 할 때에는 제3항에 따라 신고할 수 있다는 사실을 함께 고지해야 한다.', 3535);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6272, '① 검사와 사법경찰관은 소재불명(所在不明)인 피의자나 참고인을 발견한 때에는 해당 사실을 통보하는 등 서로 협력해야 한다.', 3536);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6273, '② 검사는 법 제245조의5제1호 또는 법 제245조의7제2항에 따라 송치된 사건의 피의자나 참고인의 소재 확인이 필요하다고 판단하는 경우 피의자나 참고인의 주소지 또는 거소지 등을 관할하는 경찰관서의 사법경찰관에게 소재수사를 요청할 수 있다. 이 경우 요청을 받은 사법경찰관은 이에 협력해야 한다.', 3536);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6274, '③ 검사 또는 사법경찰관은 제51조제1항제4호 또는 제52조제1항제3호ㆍ제4호에 따라 수사중지 또는 기소중지ㆍ참고인중지된 사건의 피의자 또는 참고인을 발견하는 등 수사중지 결정 또는 기소중지ㆍ참고인중지 결정의 사유가 해소된 경우에는 즉시 수사를 진행해야 한다.', 3536);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6275, '① 검사 또는 사법경찰관은 사건 관계 서류와 증거물을 분리하여 송부하거나 반환할 필요가 있으나 해당 서류와 증거물의 분리가 불가능하거나 현저히 곤란한 경우에는 그 서류와 증거물을 등사하여 송부하거나 반환할 수 있다.', 3537);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6276, '② 검사 또는 사법경찰관은 제45조제1항, 이 조 제1항 등에 따라 사건기록 등본을 송부받은 경우 이를 다른 목적으로 사용할 수 없으며, 다른 법령에 특별한 규정이 있는 경우를 제외하고는 그 사용 목적을 위한 기간이 경과한 때에 즉시 이를 반환하거나 폐기해야 한다.', 3537);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6277, '① 사법경찰관은 관계 법령에 따라 검사에게 사건을 송치할 때에는 송치의 이유와 범위를 적은 송치 결정서와 압수물 총목록, 기록목록, 범죄경력 조회 회보서, 수사경력 조회 회보서 등 관계 서류와 증거물을 함께 송부해야 한다.', 3539);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6278, '② 사법경찰관은 피의자 또는 참고인에 대한 조사과정을 영상녹화한 경우에는 해당 영상녹화물을 봉인한 후 검사에게 사건을 송치할 때 봉인된 영상녹화물의 종류와 개수를 표시하여 사건기록과 함께 송부해야 한다.', 3539);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6279, '③ 사법경찰관은 사건을 송치한 후에 새로운 증거물, 서류 및 그 밖의 자료를 추가로 송부할 때에는 이전에 송치한 사건명, 송치 연월일, 피의자의 성명과 추가로 송부하는 서류 및 증거물 등을 적은 추가송부서를 첨부해야 한다.', 3539);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6280, '① 검사는 사법경찰관으로부터 송치받은 사건에 대해 보완수사가 필요하다고 인정하는 경우에는 직접 보완수사를 하거나 법 제197조의2제1항제1호에 따라 사법경찰관에게 보완수사를 요구할 수 있다. 다만, 송치사건의 공소제기 여부 결정에 필요한 경우로서 다음 각 호의 어느 하나에 해당하는 경우에는 특별히 사법경찰관에게 보완수사를 요구할 필요가 있다고 인정되는 경우를 제외하고는 검사가 직접 보완수사를 하는 것을 원칙으로 한다. <개정 2023.10.17>', 3540);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6281, '② 검사는 법 제197조의2제1항에 따른 보완수사요구 여부를 판단하는 경우 필요한 보완수사의 정도, 수사 진행 기간, 구체적 사건의 성격에 따른 수사 주체의 적합성 및 검사와 사법경찰관의 상호 존중과 협력의 취지 등을 종합적으로 고려한다. <신설 2023.10.17>', 3540);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6282, '③ 검사는 법 제197조의2제1항제1호에 따라 사법경찰관에게 송치사건 및 관련사건(법 제11조에 따른 관련사건 및 법 제208조제2항에 따라 간주되는 동일한 범죄사실에 관한 사건을 말한다. 다만, 법 제11조제1호의 경우에는 수사기록에 명백히 현출(現出)되어 있는 사건으로 한정한다)에 대해 다음 각 호의 사항에 관한 보완수사를 요구할 수 있다. <개정 2023.10.17>', 3540);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6283, '④ 검사는 사법경찰관이 신청한 영장(「통신비밀보호법」 제6조 및 제8조에 따른 통신제한조치허가서 및 같은 법 제13조에 따른 통신사실 확인자료 제공 요청 허가서를 포함한다. 이하 이 항에서 같다)의 청구 여부를 결정하기 위해 필요한 경우 법 제197조의2제1항제2호에 따라 사법경찰관에게 보완수사를 요구할 수 있다. 이 경우 보완수사를 요구할 수 있는 범위는 다음 각 호와 같다. <개정 2023.10.17>', 3540);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6284, '① 검사는 법 제197조의2제1항에 따라 보완수사를 요구할 때에는 그 이유와 내용 등을 구체적으로 적은 서면과 관계 서류 및 증거물을 사법경찰관에게 함께 송부해야 한다. 다만, 보완수사 대상의 성질, 사안의 긴급성 등을 고려하여 관계 서류와 증거물을 송부할 필요가 없거나 송부하는 것이 적절하지 않다고 판단하는 경우에는 해당 관계 서류와 증거물을 송부하지 않을 수 있다.', 3541);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6285, '② 보완수사를 요구받은 사법경찰관은 제1항 단서에 따라 송부받지 못한 관계 서류와 증거물이 보완수사를 위해 필요하다고 판단하면 해당 서류와 증거물을 대출하거나 그 전부 또는 일부를 등사할 수 있다.', 3541);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6286, '③ 사법경찰관은 법 제197조의2제1항에 따른 보완수사요구가 접수된 날부터 3개월 이내에 보완수사를 마쳐야 한다. <신설 2023.10.17>', 3541);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6287, '④ 사법경찰관은 법 제197조의2제2항에 따라 보완수사를 이행한 경우에는 그 이행 결과를 검사에게 서면으로 통보해야 하며, 제1항 본문에 따라 관계 서류와 증거물을 송부받은 경우에는 그 서류와 증거물을 함께 반환해야 한다. 다만, 관계 서류와 증거물을 반환할 필요가 없는 경우에는 보완수사의 이행 결과만을 검사에게 통보할 수 있다. <개정 2023.10.17>', 3541);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6288, '⑤ 사법경찰관은 법 제197조의2제1항제1호에 따라 보완수사를 이행한 결과 법 제245조의5제1호에 해당하지 않는다고 판단한 경우에는 제51조제1항제3호에 따라 사건을 불송치하거나 같은 항 제4호에 따라 수사중지할 수 있다. <개정 2023.10.17>', 3541);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6289, '① 검찰총장 또는 각급 검찰청 검사장은 법 제197조의2제3항에 따라 사법경찰관의 직무배제 또는 징계를 요구할 때에는 그 이유를 구체적으로 적은 서면에 이를 증명할 수 있는 관계 자료를 첨부하여 해당 사법경찰관이 소속된 경찰관서장에게 통보해야 한다.', 3542);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6290, '② 제1항의 직무배제 요구를 통보받은 경찰관서장은 정당한 이유가 있는 경우를 제외하고는 그 요구를 받은 날부터 20일 이내에 해당 사법경찰관을 직무에서 배제해야 한다.', 3542);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6291, '③ 경찰관서장은 제1항에 따른 요구의 처리 결과와 그 이유를 직무배제 또는 징계를 요구한 검찰총장 또는 각급 검찰청 검사장에게 통보해야 한다.', 3542);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6292, '① 사법경찰관은 법 제245조의5제2호 및 이 영 제51조제1항제3호에 따라 불송치 결정을 하는 경우 불송치의 이유를 적은 불송치 결정서와 함께 압수물 총목록, 기록목록 등 관계 서류와 증거물을 검사에게 송부해야 한다.', 3543);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6293, '② 제1항의 경우 영상녹화물의 송부 및 새로운 증거물 등의 추가 송부에 관하여는 제58조제2항 및 제3항을 준용한다.', 3543);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6294, '① 검사는 법 제245조의8에 따라 사법경찰관에게 재수사를 요청하려는 경우에는 법 제245조의5제2호에 따라 관계 서류와 증거물을 송부받은 날부터 90일 이내에 해야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 관계 서류와 증거물을 송부받은 날부터 90일이 지난 후에도 재수사를 요청할 수 있다.', 3544);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6295, '② 검사는 제1항에 따라 재수사를 요청할 때에는 그 내용과 이유를 구체적으로 적은 서면으로 해야 한다. 이 경우 법 제245조의5제2호에 따라 송부받은 관계 서류와 증거물을 사법경찰관에게 반환해야 한다.', 3544);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6296, '③ 검사는 법 제245조의8에 따라 재수사를 요청한 경우 그 사실을 고소인등에게 통지해야 한다.', 3544);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6297, '④ 사법경찰관은 법 제245조의8제1항에 따른 재수사의 요청이 접수된 날부터 3개월 이내에 재수사를 마쳐야 한다. <신설 2023.10.17>', 3544);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6298, '① 사법경찰관은 법 제245조의8제2항에 따라 재수사를 한 경우 다음 각 호의 구분에 따라 처리한다.', 3545);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6299, '② 검사는 사법경찰관이 제1항제2호에 따라 재수사 결과를 통보한 사건에 대해서 다시 재수사를 요청하거나 송치 요구를 할 수 없다. 다만, 검사는 사법경찰관이 사건을 송치하지 않은 위법 또는 부당이 시정되지 않아 사건을 송치받아 수사할 필요가 있는 다음 각 호의 경우에는 법 제197조의3에 따라 사건송치를 요구할 수 있다. <개정 2023.10.17>', 3545);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6300, '③ 검사는 제2항 각 호 외의 부분 단서에 따른 사건송치 요구 여부를 판단하기 위해 필요한 경우에는 사법경찰관에게 관계 서류와 증거물의 송부를 요청할 수 있다. 이 경우 요청을 받은 사법경찰관은 이에 협력해야 한다. <신설 2023.10.17>', 3545);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6301, '④ 검사는 재수사 결과를 통보받은 날(제3항에 따라 관계 서류와 증거물의 송부를 요청한 경우에는 관계 서류와 증거물을 송부받은 날을 말한다)부터 30일 이내에 제2항 각 호 외의 부분 단서에 따른 사건송치 요구를 해야 하고, 그 기간 내에 사건송치 요구를 하지 않을 경우에는 송부받은 관계 서류와 증거물을 사법경찰관에게 반환해야 한다. <신설 2023.10.17>', 3545);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6302, '① 사법경찰관이 수사 중인 사건이 법 제260조제2항제3호에 해당하여 같은 조 제3항에 따라 지방검찰청 검사장 또는 지청장에게 재정신청서가 제출된 경우 해당 지방검찰청 또는 지청 소속 검사는 즉시 사법경찰관에게 그 사실을 통보해야 한다.', 3547);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6303, '② 사법경찰관은 제1항의 통보를 받으면 즉시 검사에게 해당 사건을 송치하고 관계 서류와 증거물을 송부해야 한다.', 3547);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6304, '③ 검사는 제1항에 따른 재정신청에 대해 법원이 법 제262조제2항제1호에 따라 기각하는 결정을 한 경우에는 해당 결정서를 사법경찰관에게 송부해야 한다. 이 경우 제2항에 따라 송치받은 사건을 사법경찰관에게 이송해야 한다.', 3547);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6305, null, 3548);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6306, '① 피의자, 사건관계인 또는 그 변호인은 검사 또는 사법경찰관이 수사 중인 사건에 관한 본인의 진술이 기재된 부분 및 본인이 제출한 서류의 전부 또는 일부에 대해 열람ㆍ복사를 신청할 수 있다.', 3550);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6307, '② 피의자, 사건관계인 또는 그 변호인은 검사가 불기소 결정을 하거나 사법경찰관이 불송치 결정을 한 사건에 관한 기록의 전부 또는 일부에 대해 열람ㆍ복사를 신청할 수 있다.', 3550);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6308, '③ 피의자 또는 그 변호인은 필요한 사유를 소명하고 고소장, 고발장, 이의신청서, 항고장, 재항고장(이하 "고소장등"이라 한다)의 열람ㆍ복사를 신청할 수 있다. 이 경우 열람ㆍ복사의 범위는 피의자에 대한 혐의사실 부분으로 한정하고, 그 밖에 사건관계인에 관한 사실이나 개인정보, 증거방법 또는 고소장등에 첨부된 서류 등은 제외한다.', 3550);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6309, '④ 체포ㆍ구속된 피의자 또는 그 변호인은 현행범인체포서, 긴급체포서, 체포영장, 구속영장의 열람ㆍ복사를 신청할 수 있다.', 3550);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6310, '⑤ 피의자 또는 사건관계인의 법정대리인, 배우자, 직계친족, 형제자매로서 피의자 또는 사건관계인의 위임장 및 신분관계를 증명하는 문서를 제출한 사람도 제1항부터 제4항까지의 규정에 따라 열람ㆍ복사를 신청할 수 있다.', 3550);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6311, '⑥ 검사 또는 사법경찰관은 제1항부터 제5항까지의 규정에 따른 신청을 받은 경우에는 해당 서류의 공개로 사건관계인의 개인정보나 영업비밀이 침해될 우려가 있거나 범인의 증거인멸ㆍ도주를 용이하게 할 우려가 있는 경우 등 정당한 사유가 있는 경우를 제외하고는 열람ㆍ복사를 허용해야 한다.', 3550);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6312, '① 이 영을 해석하거나 개정하는 경우에는 법무부장관은 행정안전부장관과 협의하여 결정해야 한다.', 3551);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6313, '② 제1항에 따른 해석 및 개정에 관한 법무부장관의 자문에 응하기 위해 법무부에 외부전문가로 구성된 자문위원회를 둔다.', 3551);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6314, '①법 제5조의 규정에 의한 보호관찰심사위원회(이하 "심사위원회"라 한다)의 위원장은 심사위원회의 회무를 통할하고, 심사위원회를 대표하며, 심사위원회의 회의를 소집하고 그 의장이 된다.', 3554);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6315, '②위원장이 부득이한 사유로 직무를 수행할 수 없는 때에는 위원장이 미리 지정한 위원이 그 직무를 대행한다.', 3554);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6316, '①심사위원회의 고위공무원단에 속하는 임기제공무원인 상임위원은 다음 각 호의 어느 하나에 해당하는 사람으로서 보호관찰에 관한 지식과 경험이 풍부한 사람 중에서 임명한다. <개정 2006.6.12, 2009.3.18, 2009.11.23, 2014.6.30, 2017.2.7, 2022.12.27>', 3555);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6317, '②심사위원회의 4급 임기제공무원인 상임위원은 다음 각 호의 어느 하나에 해당하는 사람으로서 보호관찰에 관한 지식과 경험이 풍부한 사람 중에서 임명한다. <개정 2009.3.18, 2009.11.23, 2014.6.30, 2017.2.7>', 3555);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6318, '③심사위원회의 상임위원이 아닌 위원은 위원장의 제청으로 법무부장관이 임명 또는 위촉한다.', 3555);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6319, '①심사위원회에 간사와 서기를 두되, 심사위원회 소속 공무원 또는 심사위원회의 소재지를 관할하는 보호관찰소소속 공무원중에서 위원장이 임명한다. <개정 2006.3.23>', 3556);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6320, '②간사는 위원장 및 상임위원의 명을 받아 심사위원회의 사무를 처리하고, 서기는 간사를 보조한다.', 3556);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6321, '③간사는 회의에 참석하여 발언할 수 있다.', 3556);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6322, '①심사위원회는 법 제6조에 규정된 사항을 심사함에 있어 필요한 경우에는 교도소ㆍ구치소ㆍ소년교도소 및 소년원(이하 "수용기관"이라 한다)의 장, 보호관찰관 기타 관계인을 출석시켜 의견을 듣거나 관계자료의 제출을 요청할 수 있다.', 3557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6323, '②국ㆍ공립기관 기타 단체는 법 제11조제3항의 규정에 의한 심사위원회의 요청이 있는 경우에는 특별한 사정이 없는 한 이에 협조하여야 한다.', 3557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6324, '③상임위원은 심사관계자료를 검토한 후 그 결과를 심사위원회에 보고하여야 한다.', 3557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6325, '① 심사위원회는 법 제6조에 규정된 사항을 심사하여 의결하고, 위원장과 심사위원이 서명 또는 기명날인한 결정서를 작성하여야 한다.', 3558);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6326, '② 법 제12조제2항에서 "대통령령으로 정하는 경우"란 다음 각 호의 경우를 말한다. <개정 2022.1.11>', 3558);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6327, '① 법무부장관은 법 제15조의 사무를 담당하는 보호관찰소 소속 공무원이 충분한 전문적 지식을 갖출 수 있도록 교육훈련과정을 운영하여야 한다.', 3559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6328, '② 법 제15조의 사무를 담당하는 보호관찰소 소속 공무원은 법무부령으로 정하는 바에 따라 제1항의 교육훈련과정을 이수하여야 한다.', 3559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6329, '③ 교육훈련과정에 관하여 필요한 사항은 법무부령으로 정한다.', 3559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6330, '①수용기관의 장은 법 제21조제1항 및 제2항의 규정에 의하여 징역 또는 금고의 형의 선고를 받은 소년(이하 "소년수형자"라 한다) 및 보호소년에 대한 기간경과의 통보를 하는 때에는 기간경과통보서를 작성하여 관할심사위원회에 통보하여야 한다.', 3561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6331, '②수용기관의 장은 제1항의 규정에 의하여 통보한 사항 기타 신상에 관한 사항에 변동이 생긴 때에는 지체없이 관할심사위원회에 그 사실을 통보하여야 한다.', 3561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6332, '①심사위원회는 법 제23조에 따라 가석방, 퇴원 또는 임시퇴원의 적부를 심사하여 결정하는 경우에는 소년수형자 또는 보호소년의 건전한 사회복귀를 위하여 가장 적당하다고 인정되는 시기와 다음 각호의 요건을 충족하였는지의 여부를 종합적으로 판단하여야 한다. <개정 2008.6.20, 2009.3.18>', 3564);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6333, '②심사위원회는 법 제23조제3항의 규정에 의하여 보호관찰의 필요성 여부를 심사하여 결정하는 때에는 법 제26조의 규정에 의한 환경조사 또는 법 제27조의 규정에 의한 환경개선활동의 결과를 고려하여야 한다.', 3564);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6334, '①수용기관의 장은 법 제26조제1항의 규정에 의하여 환경조사를 의뢰한 후 소년수형자 및 「소년법」 제32조제1항제8호부터 제10호까지의 어느 하나에 해당하는 보호처분을 받은 자(이하 "수용자"라 한다)의 신상에 변동이 있는 때에는 지체없이 거주예정지를 관할하는 보호관찰소의 장에게 그 사실을 통지하여야 한다. <개정 2006.3.23, 2009.3.18>', 3565);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6335, '②법 제26조의 규정에 의한 환경조사는 다음 각호의 사항에 대하여 실시하여야 한다.', 3565);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6336, null, 3569);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6337, '①보호관찰대상자는 법 제32조제2항제4호의 규정에 의한 신고를 할 때에는 법무부령이 정하는 바에 의하여 본인의 성명, 주거, 주거이전예정지 또는 여행지, 주거이전이유 또는 여행목적, 주거이전일자 또는 여행기간 등을 신고하여야 한다.', 3571);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6338, '②보호관찰대상자가 다른 보호관찰소의 관할구역안으로 주거를 이전한 때에는 10일이내에 신주거지를 관할하는 보호관찰소에 출석하여 서면으로 주거이전의 사실을 신고하여야 한다.', 3571);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6339, null, 3572);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6340, '① 보호관찰소의 장은 법 제32조제4항에 따라 준수사항의 추가, 변경 또는 삭제를 신청하는 경우에는 다음 각 호의 사항을 적은 서면으로 하여야 한다. <개정 2019.11.5>', 3573);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6341, '② 보호관찰소의 장은 제1항의 신청을 할 때 신청사유를 소명할 수 있는 자료를 제출하여야 한다.', 3573);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6342, '③ 법원 또는 심사위원회는 제1항에 따른 신청의 심리를 위하여 필요한 경우에는 담당보호관찰관을 출석시켜 의견을 들을 수 있고, 보호관찰 대상자를 소환하여 심문하거나 필요한 사항을 조사할 수 있다.', 3573);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6343, '① 보호관찰소의 장은 법 제33조의2에 따른 분류처우(이하 이 조에서 "분류처우"라 한다)를 하기 위하여 보호관찰 대상자의 개별적 특성에 알맞은 분류처우계획을 수립하여 시행하여야 한다.', 3574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6344, '② 보호관찰소의 장은 분류처우를 하기 위하여 보호관찰 대상자의 재범가능성, 사회생활 적응가능성 등 필요한 사항을 조사하여야 한다.', 3574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6345, '③ 보호관찰소의 장은 분류처우를 하기 위하여 보호관찰 대상자에 대한 심리검사 등 필요한 검사를 할 수 있고, 필요한 경우 외부전문가로부터 의견을 듣거나 검사를 의뢰할 수 있다.', 3574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6346, '①법 제35조의 규정에 의한 응급구호는 다음 각호의 1에 해당하는 경우에 실시할 수 있다.', 3575);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6347, '②보호관찰소의 장은 법 제35조의 규정에 의하여 응급구호를 하고자 하는 경우에는 예산의 범위안에서 이를 실시할 수 있다.', 3575);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6348, '① 보호관찰소의 장은 법 제36조의2제2항에 따라 정신질환 보호관찰 대상자의 보호관찰 종료사실 통보를 위한 심사위원회의 심사를 받으려는 경우에는 다음 각 호의 사항을 적은 신청서에 진단서 또는 진료확인서 등을 첨부하여 제출하여야 한다.', 3576);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6349, '② 보호관찰소의 장이 법 제36조의2제2항에 따라 통보하는 정보의 구체적인 범위는 다음 각 호와 같다.', 3576);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6350, '③ 보호관찰소의 장은 경찰관서의 장에게 법 제36조의2제2항에 따른 종료사실 통보를 하는 경우에는 제2항 각 호의 사항에 관한 전자기록을 「형사사법절차 전자화 촉진법」에 따른 형사사법정보시스템에 등록하여 경찰관서의 장이 그 전자기록을 조회하게 하는 방식으로 할 수 있다.', 3576);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6351, '①보호관찰소의 장은 법 제37조제1항의 규정에 의하여 보호관찰대상자 기타 관계인을 소환하고자 하는 경우에는 출석요구서를 발부하여야 한다. 다만, 긴급을 요하는 등 출석요구서를 발부하기에 적당하지 아니한 경우에는 다른 방법에 의할 수 있다.', 3577);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6352, '②보호관찰관은 보호관찰대상자 기타 관계인을 소환하여 조사한 때에는 그 조사내용을 서면으로 작성하여야 한다.', 3577);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6353, null, 3579);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6354, '①법 제40조제2항에 따른 긴급구인승인신청은 보호관찰대상자를 구인한 때부터 12시간 이내에 하여야 한다. <개정 2017.2.7>', 3582);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6355, '②법 제40조제2항에 따른 긴급구인서에는 다음 각 호의 사항을 기재하여야 한다. <개정 2009.11.23, 2017.2.7>', 3582);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6356, '①보호관찰관은 구인된 보호관찰대상자를 보호관찰소등에 인치한 때에는 지체없이 조사하여야 한다.', 3583);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6357, '②제1항의 경우 보호관찰관은 보호관찰대상자에게 심문에 대하여 진술을 거부할 수 있으며 본인에게 유리한 사실에 대하여 진술을 할 수 있다는 취지를 고지하여야 한다.', 3583);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6358, '③보호관찰소의 장은 제1항의 규정에 의한 조사결과 보호관찰대상자를 법 제42조의 규정에 의하여 유치할 필요가 없다고 판단되는 때에는 즉시 석방하여야 한다.', 3583);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6359, null, 3584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6360, '①보호관찰소의 장은 법 제47조제1항의 규정에 의한 신청을 하는 때에는 다음 각호의 사항을 기재한 서면에 의하여야 한다. <개정 2009.11.23>', 3588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6361, '②검사는 법 제47조제1항의 규정에 의한 청구를 하는 때에는 보호관찰소의 장이 제1항의 규정에 의하여 제출한 서면을 첨부하고, 그 사유를 소명하여야 한다.', 3588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6362, '③법원은 법 제47조제1항의 규정에 의한 청구의 심리를 위하여 필요하다고 인정하는 때에는 담당보호관찰관을 출석시켜 의견을 들을 수 있다.', 3588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6363, '①수용기관의 장은 법 제48조의 규정에 의하여 가석방 또는 임시퇴원이 취소된 보호관찰대상자를 지체없이 수용기관에 재수용하여야 한다. <개정 2008.6.20>', 3590);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6364, '②제1항의 경우 재수용을 위하여 필요한 때에는 수용기관 소재지를 관할하는 지방검찰청 또는 지청의 검사에게 구인을 의뢰할 수 있다.', 3590);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6365, '①보호관찰소의 장은 법 제49조제1항의 규정에 의하여 보호처분의 변경을 신청하는 때에는 다음 각호의 사항을 기재한 서면에 의하여야 한다. <개정 2009.11.23>', 3591);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6366, '②제1항제3호 및 제4호의 사유는 이를 소명하여야 한다.', 3591);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6367, '③법원은 제1항의 규정에 의한 신청의 심리를 위하여 필요하다고 인정하는 때에는 담당보호관찰관을 출석시켜 의견을 들을 수 있으며, 보호관찰대상자를 심문하거나 필요한 사항을 조사ㆍ심리할 수 있다.', 3591);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6368, '① 보호관찰소의 장은 법 제55조의2제1항에 따라 기부금품을 접수하는 경우 기부자에게 영수증을 발급하여야 한다. 다만, 익명으로 기부하거나 기부자를 알 수 없는 경우에는 영수증을 발급하지 아니할 수 있다.', 3593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6369, '② 보호관찰소의 장은 제1항에 따른 기부자가 다음 각 호의 어느 하나의 경우에 해당하는 사실을 알게 된 경우에는 기부금품을 접수해서는 아니 된다.', 3593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6370, '③ 보호관찰소의 장은 제1항에 따른 기부자가 기부금품의 용도를 지정한 경우에는 그 용도로만 사용하여야 한다. 다만, 기부자가 지정한 용도로 사용하기 어려운 경우에는 특별한 사정이 없는 한 기부자의 동의를 받아 다른 용도로 사용할 수 있다.', 3593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6371, '④ 보호관찰소의 장은 모든 기부금의 수입 및 지출을 기부금 전용계좌를 통하여 처리하여야 한다.', 3593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6372, '⑤ 보호관찰소의 장은 기부금품의 접수현황 및 사용실적 등에 관한 장부를 갖추어 두고 기부자가 열람할 수 있도록 하여야 한다.', 3593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6373, '⑥ 보호관찰소의 장은 매 반기별로 기부금품의 접수현황 및 사용실적 등에 관한 사항을 법무부장관에게 보고하여야 한다', 3593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6374, '①제16조(보호관찰대상자의 신고의무)ㆍ제17조(준수사항의 부과 및 훈계)ㆍ제18조(주거이전등의 신고)ㆍ제19조(특별준수사항) 및 제20조(응급구호의 범위)의 규정은 법 제3조제2항의 규정에 의한 사회봉사ㆍ수강명령대상자(이하 이 조에서 "사회봉사ㆍ수강명령대상자"라 한다)에 대하여 이를 준용한다.', 3597);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6375, '② 사회봉사ㆍ수강명령 대상자의 준수사항이나 명령 위반에 따른 경고, 구인, 유치, 집행유예 취소 및 보호처분 변경 등에 관하여는 제21조부터 제33조까지 및 제35조를 준용한다. <개정 2009.3.18>', 3597);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6376, '①법 제65조제1항에 따른 갱생보호는 갱생보호를 받을 사람(이하 "갱생보호 대상자"라 한다)이 친족 또는 연고자 등으로부터 도움을 받을 수 없거나 이들의 도움만으로는 충분하지 아니한 경우에 한하여 행한다. <개정 2014.11.19>', 3598);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6377, '②갱생보호를 하는 경우에는 미리 갱생보호 대상자로 하여금 자립계획을 수립하게 할 수 있다. <개정 2014.11.19>', 3598);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6378, '①법 제65조제1항제1호에 따른 숙식 제공은 생활관 등 갱생보호시설에서 갱생보호 대상자에게 숙소ㆍ음식물 및 의복 등을 제공하고 정신교육을 하는 것으로 한다. <개정 2014.11.19>', 3599);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6379, '②제1항의 규정에 의한 숙식제공은 6월을 초과할 수 없다. 다만, 필요하다고 인정하는 때에는 매회 6월의 범위내에서 3회에 한하여 그 기간을 연장할 수 있다. <개정 2006.12.21>', 3599);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6380, '③제1항의 규정에 의하여 숙식을 제공한 경우에는 법무부장관이 정하는 바에 의하여 소요된 최소한의 비용을 징수할 수 있다.', 3599);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6381, '①법 제65조제1항제4호에 따른 직업훈련은 갱생보호 대상자에게 취업에 필요한 기능훈련을 시키고 자격 취득을 위한 교육을 하는 것으로 한다. <개정 2014.11.19>', 3604);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6382, '②제1항의 규정에 의한 직업훈련은 다른 직업훈련기관에 위탁하여 행할 수 있다.', 3604);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6383, '① 법 제65조제1항제5호에 따른 출소예정자 사전상담은 출소예정자에게 출소 전에 갱생보호의 방법을 안내하고 자립계획 등에 대하여 상담을 실시하는 것으로 한다.', 3606);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6384, '② 갱생보호사업의 허가를 받은 자 또는 법 제71조에 따른 한국법무보호복지공단(이하 "공단"이라 한다)은 제1항의 상담을 위하여 수용기관의 장에게 출소예정자의 수용자 번호를 통보하여 줄 것을 요청할 수 있다. 이 경우 수용기관의 장은 특별한 사유가 없으면 이에 협조하여야 한다.', 3606);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6385, '① 갱생보호사업의 허가를 받은 자 또는 공단은 갱생보호 대상자의 적절한 보호를 위하여 필요한 경우 갱생보호 대상자의 동의를 받아 수용기관의 장에게 다음 각 호의 사항을 통보하여 줄 것을 요청할 수 있다.', 3611);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6386, '② 제1항의 요청을 받은 수용기관의 장은 특별한 사유가 없으면 이에 협조하여야 한다.', 3611);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6387, '①공단은 매년 다음 회계연도의 기금의 운용ㆍ관리계획을 법 제84조제2항의 규정에 의한 사업계획 및 예산에 포함시켜 법무부장관에게 제출하여야 한다.', 3614);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6388, '②제1항의 규정에 의한 운용ㆍ관리계획에는 다음 각호의 사항이 포함되어야 한다.', 3614);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6389, '①공단은 매 회계연도의 기금운용에 관한 결산결과를 법 제84조제3항의 규정에 의한 전년도의 사업실적과 결산에 포함시켜 법무부장관에게 보고하여야 한다.', 3615);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6390, '②제1항의 규정에 의한 결산결과보고에는 다음 각호의 서류를 첨부하여야 한다.', 3615);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6391, '① 심사위원회는 법 제11조에 따른 심사 및 법 제21조에 따른 통보의 접수에 관한 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보, 같은 영 제19조제1호 또는 제4호에 따른 주민등록번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 3616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6392, '② 보호관찰소의 장은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <개정 2014.6.30, 2014.11.19, 2015.6.22, 2019.11.5, 2022.1.11>', 3616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6393, '③ 법무부장관은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <신설 2014.8.6>', 3616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6394, '④ 검사는 법 제32조제4항에 따른 보호관찰대상자의 준수사항 추가, 변경 또는 삭제 청구에 관한 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <개정 2014.6.30, 2014.8.6, 2019.11.5>', 3616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6395, '⑤ 보호관찰소의 장, 갱생보호사업의 허가를 받은 자 또는 공단은 법 제66조에 따른 갱생보호의 신청 및 조치에 관한 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <신설 2014.6.30, 2014.8.6>', 3616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6396, '⑥ 공단은 법 제85조에 따른 기부금품의 접수에 관한 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법 시행령」 제19조제1호 또는 제4호에 따른 주민등록번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <신설 2015.6.22>', 3616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6397, null, 3619);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6398, '① 법무부장관은 법 제3조의2제2항에 따라 협약을 맺은 기관 또는 단체(이하 "연구개발기관"이라 한다)에 같은 조 제3항에 따라 출연금을 지급하는 경우 연구개발사업의 규모, 착수시기 및 정부의 재정 사정 등을 고려해 한꺼번에 지급하거나 나누어 지급할 수 있다.', 3621);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6399, '② 제1항에 따라 출연금을 지급받은 연구개발기관은 그 출연금을 별도의 계정(計定)을 설정하여 관리해야 한다.', 3621);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6400, '③ 제1항에 따라 출연금을 지급받은 연구개발기관은 그 출연금을 「국가연구개발혁신법 시행령」 별표 2에 따른 연구개발비 사용용도로만 사용해야 한다.', 3621);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6401, '④ 법무부장관은 연구개발기관이 정당한 사유 없이 제3항에 따른 용도 외의 용도로 제1항에 따라 지급받은 출연금을 사용한 경우에는 해당 금액을 회수해야 한다.', 3621);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6402, '⑤ 법 제3조의2제4항에 따른 보조금의 지급ㆍ사용 및 관리에 관하여는 「보조금 관리에 관한 법률」에서 정하는 바에 따른다.', 3621);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6403, '① 검사는 법 제6조제1항에 따라 보호관찰소(지소를 포함한다. 이하 같다)의 장에게 조사를 요청할 때에는 법 제5조제1항부터 제5항까지의 규정에 따른 전자장치를 부착하도록 하는 명령(이하 "부착명령"이라 한다)을 청구하는 피의자의 인적사항 및 범죄사실의 요지를 통보해야 한다. 이 경우 법무부령으로 정하는 참고자료를 보낼 수 있다. <개정 2009.7.30, 2010.7.12, 2013.5.31, 2024.1.9>', 3622);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6404, '② 보호관찰소의 장은 법 제6조제1항의 조사를 위해 교도소ㆍ소년교도소ㆍ구치소ㆍ군교도소의 장, 경찰서장, 국립법무병원장(이하 "수용기관의 장"이라 한다)에게 협조를 요청할 수 있다. 이 경우 수용기관의 장은 특별한 사유가 없으면 협조해야 한다. <개정 2024.1.9>', 3622);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6405, '① 법 제8조제1항제1호에서 "그 밖에 피부착명령청구자를 특정할 수 있는 사항"이란 피부착명령청구자의 주민등록번호, 직업, 주거, 등록기준지를 말하고, 같은 항 제4호에서 "대통령령으로 정하는 사항"이란 피부착명령청구자의 죄명을 말한다. <개정 2010.7.12>', 3623);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6406, '② 검사가 공소 제기와 동시에 부착명령을 청구할 경우에는 공소장에 부착명령 청구의 원인이 되는 사실과 적용 법조문을 추가하여 적는 것으로 부착명령 청구서를 대신할 수 있다.', 3623);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6407, '① 보호관찰관은 피부착명령자에 대한 판결문 등본, 법 제12조제2항의 부착명령 집행을 지휘한 서면, 그 밖의 관련 서류를 확인한 후 부착명령을 집행하여야 한다.', 3625);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6408, '② 보호관찰관은 법 제13조제1항에 따라 부착명령을 집행하기에 앞서 피부착명령자에게 법 제14조와 이 영에 따른 피부착자의 의무사항 및 법 제38조 및 제39조에 따른 벌칙에 관한 사항을 알려야 한다.', 3625);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6409, '③ 부착명령은 다음 각 호의 방법으로 집행한다. <개정 2018.2.13>', 3625);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6410, '④ 보호관찰소의 장은 소속 보호관찰관이 부착명령을 집행하기 위하여 필요하면 수용기관의 장에게 협조를 요청할 수 있다. 이 경우 수용기관의 장은 특별한 사유가 없으면 협조하여야 한다.', 3625);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6411, '⑤ 수용기관의 장은 피부착자가 부착명령의 집행 중 「형법」 제70조에 따른 노역장유치의 집행을 받게 된 경우 피부착자의 주거지를 관할하는 보호관찰소의 장에게 통보하여 담당 보호관찰관이 전자장치를 분리하여 회수하도록 하여야 하며, 피부착자가 노역장유치의 집행을 마치고 석방되기 전에 피부착자의 주거지를 관할하는 보호관찰소의 장에게 석방예정 사실을 통보하여 석방 전에 담당 보호관찰관이 피부착자에게 전자장치를 부착할 수 있도록 하여야 한다. <신설 2013.5.31>', 3625);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6412, '① 보호관찰관은 법 제13조제6항에 따라 부착명령의 집행이 정지되면 지체 없이 전자장치를 분리하여 회수하여야 한다. 이 경우 부착명령의 집행기간은 신체에서 부착장치를 분리한 때부터 정지된다. <개정 2010.7.12, 2018.6.12>', 3626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6413, '② 수용기관의 장은 법 제13조제6항 각 호의 사유로 피부착자가 구금된 경우에는 즉시 그의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다. <개정 2010.7.12, 2018.6.12>', 3626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6414, '③ 보호관찰관은 법 제13조제8항에 따른 부착명령의 잔여기간 집행사유가 발생한 경우 다시 전자장치를 부착하여야 한다. 이 경우 부착명령의 집행기간은 신체에 부착장치를 부착한 때부터 진행한다. <개정 2010.7.12, 2018.6.12>', 3626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6415, '④ 수용기관의 장은 법 제13조제8항제1호에 따른 부착명령의 잔여기간 집행사유가 발생한 경우 구금을 해제하기 전에 피부착명령자의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다. <개정 2010.7.12, 2018.6.12>', 3626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6416, '⑤ 수용기관의 장은 법 제13조제8항제2호 및 제3호에 따른 부착명령의 잔여기간 집행사유가 발생한 경우 부착명령의 집행이 정지된 사람이 석방되기 5일 전까지 그의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다. <신설 2010.7.12, 2018.6.12>', 3626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6417, '① 보호관찰관은 피부착자의 치료, 전자장치의 교체, 그 밖에 전자장치를 일시 분리할 필요가 있는 경우 보호관찰소의 장의 승인을 받아 전자장치의 전부 또는 일부를 피부착자의 신체 또는 주거에서 일시적으로 분리할 수 있다. 다만, 승인을 받을 시간적 여유가 없을 경우에는 분리한 후 지체 없이 보고하여야 한다.', 3628);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6418, '② 보호관찰관은 제1항의 일시 분리 사실을 대장에 적고 그 대장을 비치하여야 한다.', 3628);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6419, null, 3629);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6420, '① 법 제14조제2항에서 "대통령령으로 정하는 신상정보 등"이란 제15조의2제1항제1호부터 제8호까지의 사항 및 그 밖에 피부착자에 대한 지도ㆍ감독에 필요한 사항을 말한다. <개정 2018.6.12>', 3630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6421, '② 피부착자는 법 제14조제3항에 따른 주거이전 등의 허가를 받으려고 할 때에는 본인의 성명, 주거, 주거이전 예정지나 국내여행 예정지 또는 출국 예정지, 주거이전 이유나 국내여행 목적 또는 출국 목적, 주거이전 일자나 국내여행 기간 또는 출국 기간 등을 적은 허가신청서와 소명자료를 보호관찰소에 출석하여 제출하여야 한다.', 3630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6422, '③ 제2항에 따른 허가 신청을 받은 보호관찰관은 신청일부터 7일 이내에 주거이전 예정지나 국내여행 예정지 또는 출국 예정지, 주거이전 이유나 국내여행 목적, 출국의 목적 또는 법 제9조의2 및 「보호관찰 등에 관한 법률」 제32조에 따른 준수사항 이행 정도 등을 종합적으로 고려하여 허가 여부를 결정하여야 한다. <개정 2013.5.31>', 3630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6423, '④ 보호관찰관은 제3항에 따라 피부착자의 출국 허가를 결정할 경우 피부착자가 다음 각 호의 어느 하나에 해당하는 경우에는 출국을 허가하지 아니할 수 있다. 다만, 제1호의 경우에는 출국을 허가하지 아니하여야 한다. <신설 2013.5.31>', 3630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6424, '⑤ 보호관찰관은 제3항에 따라 피부착자의 출국 허가를 결정할 경우 그 허가기간을 출국일부터 3개월 이내의 범위에서 정하되, 불가피한 경우에만 이를 초과하여 정할 수 있다. <신설 2013.5.31>', 3630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6425, '⑥ 피부착자는 주거이전 허가를 받아 다른 보호관찰소의 관할 구역으로 주거를 이전한 경우 3일 이내에 새로운 주거지를 관할하는 보호관찰소에 출석하여 제1항의 신고를 하여야 한다. <개정 2013.5.31>', 3630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6426, '⑦ 보호관찰소의 장은 소속 보호관찰관이 제3항에 따라 피부착자에게 출국을 허가한 경우 법무부장관에게 피부착자의 출입국 사실을 통보하여 줄 것을 요청하여야 한다. <개정 2013.5.31>', 3630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6427, '⑧ 법무부장관은 제7항에 따른 요청을 받은 경우에는 피부착자의 출입국 시 지체 없이 그 사실을 보호관찰소의 장에게 통보하여야 한다. <개정 2013.5.31>', 3630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6428, '⑨ 제3항에 따른 출국 허가를 받아 출국했던 피부착자는 입국한 후 지체 없이 관할 보호관찰소에 출석하여 전자장치가 정상적으로 작동하는지를 확인받아야 한다. <개정 2013.5.31>', 3630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6429, '① 보호관찰소의 장은 법 제14조의2에 따라 부착기간의 연장을 신청하거나 같은 조 또는 법 제14조의3에 따라 준수사항의 부과ㆍ추가ㆍ변경ㆍ삭제를 신청하는 경우에는 다음 각 호의 사항을 적은 서면으로 신청해야 한다. <개정 2021.9.14>', 3631);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6430, '② 보호관찰소의 장은 제1항의 신청을 할 때 신청사유를 소명할 수 있는 자료를 제출하여야 한다.', 3631);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6431, '③ 법원은 법 제14조의2 또는 제14조의3에 따른 청구의 심리를 위하여 필요한 경우에는 담당 보호관찰관을 출석시켜 의견을 들을 수 있고, 피부착자 또는 피부착명령자를 소환하여 심문하거나 필요한 사항을 확인할 수 있다. <개정 2021.9.14>', 3631);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6432, '① 법무부장관은 다음 각 호의 시설 또는 단체를 지정하여 법 제15조제2항의 치료 및 상담치료 등을 실시하게 할 수 있다. <개정 2009.7.30, 2010.12.29, 2017.5.29>', 3632);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6433, '② 법무부장관은 제1항의 치료 및 상담치료 등에 대하여 예산의 범위에서 비용의 전부 또는 일부를 지급할 수 있다.', 3632);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6434, '③ 법무부장관은 제1항의 치료 및 상담치료에 필요한 프로그램의 개발과 전문인력의 양성을 위하여 노력하여야 한다.', 3632);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6435, '④ 법무부장관은 제1항에 따른 지정을 받은 시설 또는 단체가 치료 및 상담치료 등을 실시하기에 부적당한 경우 그 지정을 취소할 수 있다. <신설 2010.7.12>', 3632);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6436, '① 검사는 법 제16조제4항 본문에 따라 수신자료를 열람 또는 조회하려는 경우에는 관할 법원에 피부착자에 대한 수신자료의 열람 또는 조회를 허가하여 줄 것을 청구할 수 있다.', 3634);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6437, '② 사법경찰관은 법 제16조제4항 본문에 따라 수신자료를 열람 또는 조회하려는 경우 검사에게 피부착자에 대한 수신자료의 열람 또는 조회에 대한 허가를 신청하고, 검사는 관할 법원에 그 허가를 청구할 수 있다.', 3634);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6438, '③ 제1항 및 제2항에 따른 수신자료 열람 또는 조회의 허가 청구 또는 신청은 피부착자의 인적사항, 수신자료 제공기관, 청구ㆍ신청 사유 및 필요한 자료의 범위를 적은 서면으로 하여야 한다.', 3634);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6439, '④ 검사 또는 사법경찰관은 법 제16조제4항 본문에 따라 수신자료를 열람 또는 조회하는 경우에는 보호관찰소의 장(위치추적 관제센터의 장을 포함한다. 이하 제14조의3부터 제14조의6까지에서 같다)에게 관할 법원의 허가서 사본을 내주어야 한다. <개정 2021.9.14, 2024.1.9>', 3634);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6440, '① 검사 또는 사법경찰관은 법 제16조제4항 단서에 따라 수신자료의 열람 또는 조회를 요청하는 경우에는 보호관찰소의 장에게 다음 각 호의 서류를 팩스 등의 방법으로 제시하여야 한다.', 3635);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6441, '② 검사는 제1항에 따른 긴급 수신자료 열람 또는 조회를 요청한 경우에는 지체 없이 관할 법원에 그 허가를 청구하여야 한다.', 3635);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6442, '③ 사법경찰관은 제1항에 따른 긴급 수신자료 열람 또는 조회를 요청한 경우에는 지체 없이 검사에게 긴급 수신자료 열람 또는 조회에 대한 허가를 신청하고, 검사는 관할 법원에 그 허가를 청구할 수 있다.', 3635);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6443, '④ 검사 또는 사법경찰관이 법 제16조제4항 단서에 따라 보호관찰소의 장에게 송부하여야 할 자료는 관할 법원의 허가서 사본으로 한다.', 3635);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6444, '① 검사 또는 사법경찰관은 법 제16조제4항과 제5항에 따른 수신자료의 열람 또는 조회 허가 신청 및 청구 현황, 수신자료 열람 또는 조회 사실을 적은 대장을 3년간 소속 기관에 갖추어 두어야 한다.', 3636);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6445, '② 보호관찰소의 장은 검사 또는 사법경찰관에게 수신자료를 열람 또는 조회하게 하였을 때에는 해당 수신자료 열람 또는 조회 사실을 적은 대장과 수신자료 열람ㆍ조회 요청서 등 관련 자료를 3년간 갖추어 두어야 한다.', 3636);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6446, '③ 검사가 제14조의3제3항에 따른 사법경찰관의 허가 신청을 기각하면 사법경찰관은 지체 없이 열람 또는 조회한 수신자료를 폐기하여야 한다.', 3636);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6447, '④ 검사 또는 사법경찰관은 법 제16조제5항 또는 이 조 제3항에 따라 열람 또는 조회한 수신자료를 폐기하였을 때에는 지체 없이 그 사실을 서면으로 보호관찰소의 장에게 통지하여야 한다.', 3636);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6448, '① 검사 또는 사법경찰관은 수신자료를 열람 또는 조회하여 수사한 사건에 관하여 공소를 제기하거나 공소의 제기 또는 입건을 하지 아니하는 처분(기소중지결정은 제외한다)을 하였을 때에는 그 처분의 결과를 수신자료를 제공한 보호관찰소의 장에게 서면으로 통지하여야 한다.', 3637);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6449, '② 사법경찰관은 수신자료를 열람 또는 조회하여 수사한 사건을 종결하는 경우에는 그 결과를 검사에게 보고하여야 한다. 다만, 그 사건을 검찰에 송치하는 경우에는 그러하지 아니하다.', 3637);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6450, '① 전자장치 부착기간이 끝난 사람이 부착을 마친 날부터 5년 내에 자격정지 이상의 형을 받은 경우에는 그 형의 집행이 끝난 날부터 5년이 지난 때에 수신자료를 폐기한다.', 3639);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6451, '② 수신자료의 폐기는 전산자료에서 삭제하는 방법으로 한다.', 3639);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6452, '① 법 제16조의2제1항에 따라 보호관찰소의 장이 피부착자의 주거지를 관할하는 경찰관서의 장 등 수사기관에 제공할 수 있는 피부착자의 신상정보는 다음 각 호와 같다. <개정 2015.1.20>', 3640);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6453, '② 법 제16조의2제3항에 따라 보호관찰소의 장이 수사기관에 통보하는 사항은 다음 각 호와 같다.', 3640);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6454, '③ 법 제16조의2제4항에 따라 수사기관이 보호관찰소의 장에게 통보하는 사항은 다음 각 호와 같다.', 3640);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6455, '④ 제1항에 따른 피부착자 신상정보의 제공은 보호관찰소의 장이 관리하는 제1항 각 호의 피부착자 신상정보에 관한 전자기록을 「형사사법절차 전자화 촉진법」 제2조제4호에 따른 형사사법정보시스템에 등록하고, 수사기관은 이를 조회하는 방식 등으로 할 수 있다.', 3640);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6456, '⑤ 수사기관의 장은 제4항에 따라 조회한 피부착자의 신상정보를 문서로 출력한 경우 제1항제7호에 따른 전자장치 부착기간이 끝나면 그 문서를 폐기하여야 한다.', 3640);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6457, '① 법 제17조제1항에 따른 부착명령의 임시해제 신청은 「보호관찰 등에 관한 법률」 제5조에 따른 보호관찰심사위원회(이하 "심사위원회"라 한다)에 서면으로 해야 한다. <개정 2020.8.5>', 3641);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6458, '② 심사위원회는 피부착자 또는 그 법정대리인이 부착명령의 임시해제를 신청한 경우 지체 없이 그 사실을 보호관찰소의 장에게 통보해야 한다. <개정 2020.8.5>', 3641);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6459, '① 심사위원회는 법 제18조제1항에 따라 부착명령의 임시해제를 심사할 때에는 보호관찰관, 정신건강의학과 의사, 정신보건임상심리사, 그 밖의 전문가의 의견을 고려해야 한다. <개정 2011.11.23, 2013.5.31, 2020.8.5>', 3642);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6460, '② 심사위원회는 법 제18조제4항 및 제5항의 결정을 하면 지체 없이 그 결정서 등본을 관할 보호관찰소의 장과 신청인에게 송달하여야 한다.', 3642);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6461, '③ 보호관찰관은 법 제18조제4항의 부착명령 임시해제 결정이 있으면 결정서에 기재된 임시해제일에 전자장치를 회수해야 한다. <개정 2020.8.5>', 3642);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6462, '④ 심사위원회가 제1항에 따라 전문가 의견을 고려한 경우 의견을 진술하거나 자료를 제출한 전문가에게는 예산의 범위에서 필요한 비용의 전부 또는 일부를 지급할 수 있다. <신설 2010.7.12>', 3642);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6463, '① 법 제19조제1항에 따른 임시해제의 취소신청은 심사위원회에 서면으로 해야 한다. <신설 2013.5.31, 2020.8.5>', 3643);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6464, '② 심사위원회는 법 제19조제1항에 따라 부착명령의 임시해제 취소 결정을 했을 때에는 지체 없이 그 사실을 관할 보호관찰소의 장에게 통보해야 한다. <개정 2013.5.31, 2020.8.5>', 3643);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6465, '③ 보호관찰관은 부착명령의 임시해제 취소결정이 있으면 피부착명령자에게 결정서를 제시한 후 전자장치를 부착해야 한다. <개정 2013.5.31, 2020.8.5>', 3643);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6466, '④ 임시해제가 취소된 경우 부착명령 집행기간은 부착장치를 피부착명령자의 신체에 부착한 때부터 진행한다. <개정 2013.5.31, 2020.8.5>', 3643);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6467, '① 보호관찰소의 장은 법 제21조의7에 따라 보호관찰 기간의 연장 또는 준수사항의 추가ㆍ변경ㆍ삭제를 신청하는 경우에는 다음 각 호의 사항을 적은 서면으로 하여야 한다.', 3644);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6468, '② 보호관찰소의 장은 제1항의 신청을 할 때 신청사유를 소명할 수 있는 자료를 제출하여야 한다.', 3644);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6469, '③ 법원은 법 제21조의7에 따른 청구의 심리를 위하여 필요한 경우에는 담당 보호관찰관을 출석시켜 의견을 들을 수 있으며, 보호관찰대상자를 소환하여 심문(審問)하거나 필요한 사항을 확인할 수 있다.', 3644);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6470, '① 교도소ㆍ소년교도소ㆍ구치소의 장은 가석방 예정자에 대한 심사위원회의 법 제22조제3항에 따른 전자장치 부착의 필요성과 적합성 여부 등의 조사(이하 "전자장치 부착 적합성조사"라 한다)를 위해 「형의 집행 및 수용자의 처우에 관한 법률」 및 관계 법령에 따라 가석방 적격심사 신청 대상자가 선정되면 지체 없이 해당 대상자에 대한 다음 각 호의 사항이 포함된 자료를 해당 교도소ㆍ소년교도소ㆍ구치소의 소재지를 관할하는 심사위원회에 보내야 한다.', 3646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6471, '② 심사위원회는 제1항에 따라 교도소ㆍ소년교도소ㆍ구치소의 장으로부터 자료를 받은 경우에는 가석방 예정자에 대한 전자장치 부착 적합성조사를 하거나, 교도소ㆍ소년교도소ㆍ구치소의 소재지 또는 해당 가석방 예정자의 거주예정지를 관할하는 보호관찰소의 장과 협의하여 보호관찰소의 장에게 전자장치 부착 적합성조사를 위하여 필요한 사항의 조사를 의뢰할 수 있다.', 3646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6472, '③ 보호관찰소의 장은 제2항에 따른 의뢰를 받은 경우에는 필요한 조사를 하고 그 결과를 심사위원회에 통보해야 한다.', 3646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6473, '④ 교도소ㆍ소년교도소ㆍ구치소의 장은 심사위원회 또는 보호관찰소의 장으로부터 제2항 또는 제3항에 따른 전자장치 부착 적합성조사 등을 위한 가석방 예정자 면담 등 필요한 협조를 요청받은 경우 특별한 사정이 없으면 이에 협조해야 한다.', 3646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6474, '⑤ 심사위원회 또는 보호관찰소의 장은 전자장치 부착 적합성조사를 위해 필요하다고 인정하면 국가기관, 지방자치단체 또는 공공기관의 장에게 사실을 알아보거나 관련 자료의 열람 등 협조를 요청할 수 있다. 이 경우 해당 기관의 장은 특별한 사정이 없는 한 이에 협조해야 한다.', 3646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6475, '⑥ 전자장치 부착 적합성조사의 내용에는 가석방 예정자의 범죄경력, 범죄내용 및 직업, 경제력, 생활환경 등 개별적 특성에 관한 사항이 포함되어야 한다.', 3646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6476, '① 심사위원회는 「보호관찰 등에 관한 법률」 제24조제1항에 따른 보호관찰 결정서 등본을 수용기관의 장에게 송달하면서 법 제22조제1항 및 제2항에 따른 전자장치 부착에 관한 사항을 함께 통보해야 한다. <개정 2020.8.5>', 3647);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6477, '② 「치료감호 등에 관한 법률」 제37조에 따른 치료감호심의위원회는 법 제23조제1항에 따라 피치료감호자 또는 피보호감호자에게 전자장치를 부착하는 결정을 한 경우 그 결정서를 피치료감호자 또는 피보호감호자에게, 결정서 등본을 수용기관의 장(보호감호시설의 장을 포함한다. 이하 이 장에서 같다)에게 각각 송달하여야 한다. <개정 2010.7.12, 2016.11.29>', 3647);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6478, '③ 제1항 또는 제2항에 따라 결정서 등본을 송달받은 수용기관의 장은 전자장치를 부착하게 될 가석방예정자, 피치료감호자 또는 피보호감호자에게 전자장치 부착에 관한 내용을 알려주어야 한다. <개정 2010.7.12>', 3647);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6479, '① 치료감호시설의 장 및 보호감호시설의 장은 법 제23조제1항에 따라 전자장치 부착결정을 받은 사람(이하 "피부착결정자"라 한다)을 다른 수용기관으로 이송할 경우 그 수용기관의 장에게 이송되는 사람이 전자장치 부착결정을 받았음을 통보하여야 한다. <개정 2010.7.12>', 3648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6480, '② 제1항에 따라 피부착결정자를 인수한 수용기관의 장은 그가 출소하기 5일 전까지 그 주거지를 관할하는 보호관찰소의 장에게 피부착결정자의 석방 예정 사실을 통보하여야 한다.', 3648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6481, '① 법원은 법 제31조의2제2항에 따라 보호관찰소의 장에게 조사를 의뢰하는 경우에는 피고인의 인적사항 및 범죄사실의 요지를 통보해야 한다. 이 경우 필요하면 참고자료를 보낼 수 있다.', 3652);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6482, '② 보호관찰소의 장은 법 제31조의2제3항에 따른 조사를 위해 수용기관의 장에게 협조를 요청할 수 있다. 이 경우 수용기관의 장은 특별한 사유가 없으면 이에 협조해야 한다.', 3652);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6483, '① 보호관찰관은 법 제31조의3제2항에 따라 부착명령을 집행하는 경우 같은 조 제1항에 따라 송부된 전자장치 보석피고인에 대한 결정문 등본(제23조의3에 따른 사본을 포함한다)을 확인한 후 전자장치를 부착해야 한다.', 3655);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6484, '② 보호관찰관은 제1항에 따라 전자장치를 부착하기 전에 전자장치 보석피고인에게 다음 각 호의 내용을 알려주어야 한다.', 3655);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6485, '③ 전자장치의 부착은 다음 각 호의 방법으로 한다.', 3655);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6486, '④ 보호관찰소의 장은 법 제31조의3제3항에 따라 피고인의 보석조건 이행 여부를 확인하기 위하여 국가기관, 지방자치단체 또는 공공기관의 장에게 사실을 알아보거나 관련 자료의 열람 등 협조를 요청할 수 있다. 이 경우 해당 기관의 장은 특별한 사정이 없는 한 이에 협조해야 한다. <신설 2021.9.14>', 3655);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6487, '① 보호관찰소의 장은 법 제31조의4제1항에 따라 피고인의 보석조건 이행상황을 매월 말일을 기준으로 작성하여 그 다음달 10일까지 보석결정을 한 법원에 송부해야 한다.', 3656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6488, '② 제1항에도 불구하고 법원은 피고인의 재판을 위해 피고인의 보석조건 이행상황을 신속하게 파악할 필요가 있는 경우에는 보호관찰소의 장에게 피고인의 보석조건 이행상황에 관한 자료를 요청할 수 있다.', 3656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6489, '① 보호관찰소의 장은 전자장치 보석피고인이 다음 각 호의 어느 하나에 해당하는 경우 법 제31조의4제2항에 따라 보석결정을 한 법원과 그 법원에 대응하는 검찰청 검사에게 지체 없이 통지해야 한다.', 3657);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6490, '② 제1항에 따른 통지는 인편 또는 등기우편의 방법으로 한다. 다만, 긴급한 경우에는 전화ㆍ팩스ㆍ전자우편 등의 방법으로 먼저 통지하고 사후에 인편 또는 등기우편의 방법으로 할 수 있다.', 3657);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6491, null, 3660);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6492, '① 법 제31조의6제2항에서 "대통령령으로 정하는 신상정보 등"이란 다음 각 호의 사항을 말한다.', 3661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6493, '② 전자장치 스토킹행위자는 전자장치 부착의 집행 중 제1항제1호, 제2호 및 제4호부터 제6호까지의 사항이 변경된 경우에는 주거지를 관할하는 보호관찰소의 장에게 전화 등의 방법으로 지체 없이 그 사실을 신고해야 한다.', 3661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6494, '③ 전자장치 스토킹행위자는 전자장치 부착의 집행 중 제1항제3호의 사항이 변경된 경우에는 지체 없이 주거지를 관할하는 보호관찰소에 출석하여 그 사실을 신고해야 한다.', 3661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6495, '④ 제3항에도 불구하고 전자장치 스토킹행위자는 전자장치 부착의 집행 중 다른 보호관찰소의 관할 구역으로 주거지를 이전한 경우에는 3일 이내에 새로운 주거지를 관할하는 보호관찰소에 출석하여 제1항 각 호의 사항을 서면으로 신고해야 한다.', 3661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6496, '⑤ 전자장치 스토킹행위자의 주거지를 관할하는 보호관찰소(이하 이 장에서 "보호관찰소"라 한다)의 장은 제2항부터 제4항까지의 규정에 따른 신고를 받은 경우에는 관할경찰관서의 장에게 지체 없이 그 사실을 통지해야 한다.', 3661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6497, '① 보호관찰관은 법 제31조의6제2항에 따라 전자장치를 부착하는 경우 같은 조 제1항에 따라 송부된 전자장치 스토킹행위자에 대한 결정문 등본(제23조의10에 따른 사본을 포함한다)을 확인한 후 전자장치를 부착해야 한다.', 3662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6498, '② 보호관찰관은 제1항에 따라 전자장치를 부착하기 전에 전자장치 스토킹행위자에게 전자장치 효용 유지를 위해 필요한 다음 각 호의 의무 사항을 알려주어야 한다.', 3662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6499, '③ 보호관찰관은 제1항에 따라 전자장치를 부착하면 지체 없이 전자장치 스토킹행위자와 피해자가 서로 근접하는지 여부를 확인할 수 있는 장치 또는 시스템(이하 이 항에서 "피해자장치등"이라 한다)을 피해자에게 제공해야 한다. 다만, 피해자와 연락이 되지 않거나 피해자가 피해자장치등의 수령을 거부하는 등의 사유로 피해자장치등을 제공할 수 없는 경우에는 피해자 보호 업무를 담당하는 사법경찰관리에게 휴대전화 문자전송, 전자우편, 팩스 또는 전화 등의 방법으로 지체 없이 그 사실을 통지해야 한다.', 3662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6500, '① 보호관찰소의 장은 법 제31조의6제3항 각 호 외의 부분에 따라 관할경찰관서의 장에게 전자장치 스토킹행위자가 전자장치를 부착한 사실을 통지할 때에는 제23조의11제1항 각 호의 사항과 그 밖에 피해자 보호를 위해 필요한 사항을 함께 통지해야 한다.', 3663);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6501, '② 법 제31조의6제3항제6호에서 "대통령령으로 정하는 피해자의 보호를 위하여 필요한 사항"이란 다음 각 호의 사항을 말한다.', 3663);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6502, '③ 관할경찰관서의 장은 전자장치 부착의 집행 중 법 제31조의6제3항 각 호의 사항이 변경된 것을 안 때에는 보호관찰소의 장에게 즉시 그 사실을 통지해야 한다.', 3663);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6503, '① 법 제31조의6제4항제4호에서 "대통령령으로 정하는 사유가 있는 경우"란 다음 각 호의 경우를 말한다.', 3664);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6504, '② 보호관찰소의 장 또는 위치추적 관제센터의 장은 전자장치 스토킹행위자가 법 제31조의6제4항 각 호의 어느 하나에 해당하는 경우에는 관할경찰관서의 장 또는 시ㆍ도경찰청 112치안종합상황실장에게 휴대전화 문자전송, 전자우편, 팩스 또는 전화 등의 방법으로 즉시 그 사실을 통지해야 한다.', 3664);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6505, '③ 제1항 및 제2항에서 규정한 사항 외에 피해자의 보호 방법 및 절차 등에 관한 세부 사항은 경찰청장이 법무부장관과 협의하여 정한다.', 3664);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6506, null, 3668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6507, '① 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제1호 및 제3항제1호에 따라 성폭력범죄를 저질러 2008년 9월 1일 이전에 제1심판결을 선고받아 2010년 7월 16일 기준으로 징역형 이상의 형, 치료감호 또는 보호감호(이하 "징역형등"이라 한다)의 집행 종료일까지 6개월 이상이 남은 사람(이하 "출소예정자"라 한다), 징역형등의 집행 종료일까지 6개월 미만이 남은 사람(이하 "출소임박자"라 한다) 및 징역형등의 집행이 종료, 가종료ㆍ가출소ㆍ가석방 또는 면제된 후 3년이 경과되지 아니한 사람(이하 "출소자"라 한다)에 대하여 교도소ㆍ구치소ㆍ치료감호시설ㆍ보호감호시설(이하 "수용시설"이라 한다)의 장이 수용시설의 소재지를 관할하는 지방검찰청의 검사에게 통보하여야 할 사항은 다음 각 호와 같다.', 3670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6508, '② 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제1호 및 제3항제1호에 따라 성폭력범죄를 저질러 2008년 9월 1일 이전에 제1심판결을 선고받아 2010년 7월 16일 기준으로 출소예정자, 출소임박자, 출소자(이하 "출소자등"이라 한다)인 사람에 대하여 수용시설의 장이 수용시설의 소재지를 관할하는 보호관찰소의 장에게 통보하여야 할 사항은 출소자등의 성명, 주민등록번호, 주소, 출소예정일 및 죄명으로 한다.', 3670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6509, '① 법원은 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제5호 및 제3항제8호에 따라 출소자등에 대하여 부착명령을 결정한 경우에는 부착명령을 받은 사람에게 그 결정을 고지하여야 한다.', 3673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6510, '② 법원은 제1항에 따라 결정이 고지된 날부터 3일 이내에 부착명령을 고지받은 사람의 주거지를 관할하는 보호관찰소의 장에게 결정문 등본을 송부하여야 한다.', 3673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6511, '③ 수용시설의 장은 부착명령을 고지받은 사람이 석방되기 5일 전까지 그의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다.', 3673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6512, '① 출소자등에 대한 부착명령은 부착명령이 고지된 후 지체 없이 검사의 지휘를 받아 보호관찰관이 집행한다.', 3674);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6513, '② 제1항에 따른 지휘는 결정문 등본을 첨부한 서면으로 한다.', 3674);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6514, '① 법무부장관은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 3675);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6515, '② 검사는 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호 또는 제2호에 따른 유전정보 또는 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. 다만, 제9호의2의 사무의 경우에는 「개인정보 보호법」 제23조에 따른 성생활에 관한 정보 및 같은 법 시행령 제18조제1호에 따른 유전정보에 해당하는 정보는 제외한다. <개정 2021.9.14, 2024.1.9>', 3675);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6516, '③ 보호관찰소의 장 또는 보호관찰관은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호 또는 제2호에 따른 유전정보 또는 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. 다만, 제16호의2 및 제16호의3의 사무의 경우에는 「개인정보 보호법」 제23조에 따른 성생활에 관한 정보 및 같은 법 시행령 제18조제1호에 따른 유전정보에 해당하는 정보는 제외한다. <개정 2021.9.14, 2024.1.9>', 3675);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6517, '④ 심사위원회는 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호 또는 제2호에 따른 유전정보 또는 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 3675);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6518, '⑤ 치료감호심의위원회는 법 제23조 및 제24조에 따른 전자장치 부착에 관한 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호 또는 제2호에 따른 유전정보 또는 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 3675);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6519, '⑥ 수용기관의 장 또는 수용시설의 장은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 3675);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6520, '⑦ 경찰관서의 장 등 수사기관은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2024.1.9>', 3675);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6521, '⑧ 사법경찰관은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2024.1.9>', 3675);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6522, '① 「보호소년 등의 처우에 관한 법률 시행령」(이하 "영"이라 한다) 제6조에 따른 인수서는 별지 제1호서식에 따른다. <개정 2021.4.20>', 3684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6523, '② 소년원장 또는 소년분류심사원장(이하 "원장"이라 한다)은 보호소년등이 영 제6조에 따라 새로 수용된 때에는 지체 없이 다음 각 호에 따른 검사ㆍ조사 또는 조치 등을 하고, 이상이 발견되었을 경우에는 필요한 조치를 마련하여야 한다. <개정 2016.9.29, 2021.4.20>', 3684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6524, '③ 여성인 보호소년등에 대한 제2항제1호ㆍ제3호 및 제4호의 검사 또는 조치는 여성인 직원이 실시해야 한다. 다만, 제2항제3호에 따른 검사는 여성인 직원이 참석한 가운데 의사나 간호사가 실시할 수 있다. <개정 2021.4.20>', 3684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6525, null, 3687);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6526, '① 소년원장은 법 제9조제1항에 따라 「소년법」 제32조제1항제7호부터 제10호까지의 보호처분을 받아 수용된 보호소년이 소년원을 이탈한 후 재수용되었을 때에는 법원소년부에 같은 항 제7호부터 제10호까지의 보호처분으로 변경을 신청할 수 있다. <개정 2021.4.20>', 3692);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6527, '② 소년원장은 「소년법」 제32조제1항제5호 처분과 제8호 처분이 병합되어 소년원에 수용된 보호소년이 소년원을 이탈하였을 때에는 그 보호소년을 관할하는 보호관찰소에 즉시 통보하여야 한다.', 3692);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6528, '③ 소년원장은 보호소년이 소년원을 이탈하거나 소년원을 이탈한 후 범법행위로 인하여 징역 또는 금고 이상의 유죄판결이 확정된 경우 또는 보호처분에 따라 소년원에 다시 송치된 경우에는 해당 보호소년에 대한 종전의 보호처분을 취소할 것을 법원소년부에 신청하여야 한다.', 3692);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6529, '① 원장은 영 제13조에 따른 청원의 편의를 위하여 보호소년등이 이용하기 편리한 곳에 청원함을 설치하고, 매일 청원사항을 확인하여야 한다.', 3693);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6530, '② 청원에 대한 결정은 문서로 하여야 하며, 그 결정서는 지체 없이 청원인에게 전달하여야 한다.', 3693);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6531, '③ 원장은 별지 제3호서식의 청원처리부를 갖추고, 청원의 처리경위 등을 기록ㆍ유지하여야 한다.', 3693);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6532, '① 신입보호소년의 이송은 보호처분에 대한 항고제기기간이 지난 후 지체 없이 실시하여야 한다. 다만, 보호소년 및 보호소년의 보호자가 항고제기의사가 없음을 밝히고, 별지 제4호서식의 항고권포기 서약서를 작성하여 제출한 경우에는 항고제기기간이 지나기 전이라도 이송할 수 있다.', 3695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6533, '② 소년원장은 법 제12조에 따라 보호소년을 다른 소년원으로 이송하려면 이송할 보호소년의 인적사항, 이송사유, 그 밖에 필요한 사항을 구체적으로 제시하여 법무부장관에게 이송허가를 신청해야 한다. <개정 2021.4.20>', 3695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6534, '③ 소년원장은 제1항에 따라 이송허가를 받아 보호소년을 다른 소년원에 이송할 때에는 그 보호소년의 소년관리기록부ㆍ보관금품 및 별지 제12호서식에 따른 보관금품 보관증(기관 보관용을 말한다) 그 밖의 참고자료를 인수소년원에 인계하여야 한다. <개정 2016.9.29>', 3695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6535, '① 소년원장은 보호소년이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 보호소년을 의료재활소년원으로 이송하도록 허가해 줄 것을 법무부장관에게 신청할 수 있다. <개정 2021.4.20>', 3697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6536, '② 제1항에 따른 이송허가의 구체적인 기준은 법무부장관이 정한다.', 3697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6537, '① 소년원장은 의료재활소년원으로의 이송을 신청할 때에는 별지 제5호서식에 따른 소속 의무과장의 진료소견서를 첨부해야 한다. <개정 2016.9.29, 2021.4.20>', 3698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6538, '② 보호소년을 의료재활소년원으로 이송하는 경우 인계기관은 해당 보호소년의 의무ㆍ진료와 관련된 모든 자료의 원본 또는 출력물을 인수기관으로 보내고 그 사본을 보관해야 한다. <개정 2021.4.20>', 3698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6539, '③ 의료재활소년원장은 보호소년이 개별처우계획에 따른 의료재활과정을 마쳤을 때에는 해당 보호소년을 처우하기에 적합한 소년원을 정하여 법무부장관에게 이송을 신청해야 한다. 이 경우 처우ㆍ징계위원회의 심사를 거쳐야 한다. <개정 2021.4.20>', 3698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6540, '④ 제1항부터 제3항까지에서 규정한 사항 외에 의료재활소년원으로의 이송절차 등에 관한 구체적인 사항은 법무부장관이 정한다. <신설 2016.9.29, 2021.4.20>', 3698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6541, '① 원장은 보호소년등의 특성ㆍ인원ㆍ감호환경 그 밖에 사고방지를 위한 모든 여건을 고려하여 감호직원을 배치하여야 한다.', 3700);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6542, '② 제1항에 따라 감호의 임무를 부여받은 사람은 보호소년등을 방치하거나 감호 중에 무단이석ㆍ음주ㆍ독서ㆍ잡무처리 등 감호 외의 용무를 보아서는 아니된다.', 3700);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6543, '① 수갑의 사용방법은 다음 각 호와 같다. 이 경우 수갑은 손목에만 채워야 하며, 주요 동맥이나 정맥을 압박하여 피가 통하지 않도록 해서는 안 된다.', 3701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6544, '② 포승의 사용방법은 다음 각 호와 같이 하되, 주요 동맥이나 정맥을 압박하여 피가 통하지 않도록 해서는 안 된다. 다만, 제1호부터 제4호까지의 규정에도 불구하고 원장은 영 제2조제2호에 따른 향상된 처우를 하는 경우로서 보호소년등이 이탈할 위험성이 크지 않다고 판단되는 경우에는 포승을 사용하지 않을 수 있다.', 3701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6545, '③ 가스총의 사용방법은 다음 각 호와 같다.', 3701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6546, '④ 전자충격기의 사용방법은 다음 각 호와 같다.', 3701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6547, '⑤ 머리보호장비는 별표 1의10의 방법으로 사용한다. 이 경우 보호소년등이 머리보호장비를 임의로 해제하지 못하도록 수갑이나 포승을 함께 사용할 수 있다.', 3701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6548, '⑥ 보호대는 보호대에 부착된 고리에 수갑을 연결하여 별표 1의11의 방법으로 사용한다.', 3701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6549, '⑦ 법 제14조의2제1항에 따른 보호장비를 사용하려면 미리 원장의 허가를 받아야 한다. 다만, 긴급한 경우에는 사용 후 즉시 원장에게 보고해야 한다.', 3701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6550, '⑧ 제1항부터 제7항까지의 규정에서 정한 사항 외에 그 밖에 보호장비의 사용방법 등에 관한 세부 사항은 법무부장관이 정한다.', 3701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6551, '① 원장은 보호장비의 관리책임을 지며, 월 1회 이상 소속기관의 보호장비 사용실태를 확인ㆍ점검하여야 한다. <개정 2014.1.29>', 3702);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6552, '② 보호장비는 항상 사용가능한 상태를 유지하여야 하며, 보관은 별도의 캐비넷에 하여야 한다. <개정 2014.1.29>', 3702);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6553, '③ 보호장비를 사용할 때에는 별지 제34호서식의 보호장비 사용 기록부에 기록ㆍ관리한다. <개정 2014.1.29>', 3702);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6554, '④ 유효기간이 지난 가스총의 탄환 및 분사약재 등은 폐기해야 한다. <신설 2021.4.20>', 3702);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6555, '⑤ 제1항부터 제4항까지의 규정에서 정한 사항 외에 보호장비의 관리 등에 관한 세부 사항은 법무부장관이 정한다. <신설 2016.9.29, 2021.4.20>', 3702);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6556, null, 3703);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6557, '① 원장은 전자장비의 효율적인 운용을 위하여 각종 전자장비를 통합적으로 관리할 수 있는 시스템이 설치된 통제실을 설치하여 운영한다.', 3704);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6558, '② 원장은 통제실에 대한 외부인의 출입을 제한하여야 한다. 다만, 시찰ㆍ참관이나 그 밖에 원장이 특별히 필요하다고 인정하는 경우에는 외부인의 출입을 허가할 수 있다.', 3704);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6559, '① 영상정보처리기기 중 카메라는 소년원등의 청사 정문ㆍ운동장, 외곽 담장, 생활관 내 복도, 각 생활실, 생활지도실, 그 밖에 보호소년등의 감호에 필요한 장소로서 법무부장관이 정하는 장소에 설치한다. <개정 2021.4.20>', 3705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6560, '② 영상정보처리기기 중 모니터는 상황실ㆍ생활지도실, 그 밖에 소년원등의 소속 공무원(이하 제24조의10까지에서 "소속공무원"이라 한다)이 보호소년등을 감호하기에 적정한 장소로서 법무부장관이 정하는 장소에 설치한다. <개정 2021.4.20>', 3705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6561, '③ 제1항 및 제2항에서 규정한 사항 외에 영상정보처리기기의 운영ㆍ관리 등에 관한 세부 사항은 법무부장관이 정한다.', 3705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6562, '① 고정식 물품검색기는 정문, 생활관 입구, 교육관 입구, 그 밖에 보호소년등이나 소년원등에 출입하는 외부인에 대한 신체ㆍ의류ㆍ휴대품의 검사가 필요한 장소에 설치한다. <개정 2021.4.20>', 3708);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6563, '② 소속공무원이 영 제17조의3제1항에 따라 보호소년등의 신체ㆍ의류ㆍ휴대품을 검사하는 경우에는 특별한 사정이 없으면 고정식 물품검색기를 통과하게 한 후 휴대식 금속탐지기나 손으로 이를 확인한다.', 3708);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6564, '③ 소속공무원이 영 제18조제1항에 따라 소년원등을 출입하는 외부인의 의류와 휴대품을 검사하는 경우에는 고정식 물품검색기를 통과하게 하거나 휴대식 금속탐지기로 이를 확인한다. <개정 2021.4.20>', 3708);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6565, '① 원장은 보호소년등의 인원ㆍ소지품ㆍ이용시설 그 밖에 필요한 사항을 수시로 점검하고 보호소년등이 허가없이 외부인과 접촉하는 것을 금지하여야 한다.', 3711);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6566, '② 원장은 보호소년등이 외출하거나 생활관을 출입할 때에는 반드시 소지품검사를 하여 부정물품반입을 예방하여야 한다.', 3711);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6567, '③ 원장은 수시로 생활실 등 각종 시설의 이상유무, 부정물품의 은닉여부 그 밖에 필요한 사항을 점검하여야 한다.', 3711);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6568, null, 3714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6569, '① 원장은 규율을 위반한 보호소년등을 징계할 때에는 별표 2의 보호소년등의 징계기준에 따라야 한다. <개정 2021.4.20>', 3715);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6570, '② 삭제 <2014.1.29>', 3715);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6571, '③ 소년원장은 제1항에 따른 징계를 받은 보호소년에 대하여 각각 다음 각 호에 따른 점수를 해당 보호소년의 교정성적에서 뺀다. <개정 2014.1.29, 2016.9.29>', 3715);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6572, '④ 보호소년에 대하여 법 제15조제2항에 따라 여러 처분을 함께 부과하는 경우에는 제3항 각 호에 따른 점수가 가장 높은 처분의 점수만을 해당 보호소년의 교정성적에서 뺀다. <신설 2016.9.29>', 3715);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6573, '⑤ 소년분류심사원장은 징계를 받은 위탁소년 및 유치소년에 대하여는 분류심사관에게 통보하여 분류심사에 반영하여야 한다. <개정 2014.1.29, 2016.9.29>', 3715);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6574, null, 3716);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6575, '① 원장은 별표 3의 분기별 반입품 허가기준에 따라 자체실정에 맞는 반입기준을 정하여 물품의 반입을 허가할 수 있다. 다만, 다음 각 호의 어느 하나에 해당한다고 인정되는 물품에 대하여는 반입을 허가하지 아니한다.', 3720);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6576, '② 반입품은 별지 제8호서식의 개인별 반입품관리부에 기록ㆍ관리하여야 한다.', 3720);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6577, '① 법 제18조제1항에 따른 보호소년등의 면회는 면회실에서 하여야 한다.', 3721);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6578, '② 면회실에는 상담직원을 배치하고 다음 각 호의 사항을 구비하여 면회인의 편의를 도모하며 수시로 의견을 청취하여 민원개선에 노력하여야 한다.', 3721);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6579, '③ 원장은 제1항에도 불구하고 특별한 사유가 있으면 면회인과 보호소년등이 보다 안정된 분위기 속에서 면회를 할 수 있도록 별도의 장소를 활용할 수 있다.', 3721);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6580, '① 원장은 면회를 신청하는 사람의 성명ㆍ주소 및 보호소년등과의 관계 등을 확인하고 면회허가여부를 결정하여야 한다.', 3722);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6581, '② 원장은 면회를 신청하는 사람이 해당 사건의 변호인 또는 수사관련 공무원인 경우에는 신분 및 면회신청사유 등을 확인한 후 면회를 허가하여야 한다.', 3722);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6582, null, 3724);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6583, '① 원장은 법 제18조제6항에 따른 전화통화를 할 수 있는 별도의 장소를 지정하여야 한다.', 3725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6584, '② 전화통화는 평일 근무시간에 한정한다. 다만, 원장은 특별히 필요하다고 인정하는 경우에는 야간 및 휴일에도 전화통화를 허가할 수 있다.', 3725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6585, '③ 제1항 및 제2항에서 규정한 사항 외에 전화통화의 신청 및 기록 등에 관한 세부 사항은 법무부장관이 정한다.', 3725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6586, '① 보호소년이 법 제19조에 따른 외출을 허가받으려면 별지 제10호서식의 외출신청서를 작성하여 해당 소년원장에게 제출하여야 한다.', 3726);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6587, '② 보호소년 또는 그 보호자가 영 제40조 단서에 따라 외출을 연장하려면 외출기간이 종료되기 전에 별지 제10호서식에 따른 외출기간연장신청서를 제출하고 소년원장의 허가를 받아야 한다. <개정 2012.8.2>', 3726);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6588, '① 영 제41조제1항에 따른 준수사항에는 다음 각 호의 내용이 포함되어야 한다.', 3728);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6589, '② 소년원장은 보호소년의 자유를 부당하게 제한하지 아니하는 범위에서 제1항에 따른 준수사항 외에 별도의 특별한 준수사항을 부과할 수 있다.', 3728);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6590, '③ 영 제66조 및 영 제76조에 따른 통학 또는 통근취업 대상자에 대하여는 제1항 및 제2항의 규정을 준용한다.', 3728);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6591, '① 원장은 보호소년등의 보건ㆍ위생관리를 위한 종합대책과 세부생활지도계획을 분기별로 수립ㆍ시행하여야 한다.', 3729);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6592, '② 원장은 제9조제2항제3호에 따른 신체검사 등을 통하여 문신이 있는지 확인하고 해당 보호소년등이 문신제거 시술을 원하는 경우에는 신청에 의하여 문신제거 시술을 할 수 있다.', 3729);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6593, '① 원장은 보호소년등의 보건위생을 위하여 보호소년등의 신체ㆍ의류ㆍ거실ㆍ침구ㆍ식기ㆍ취사장ㆍ화장실 그 밖의 생활환경을 청결히 하도록 하여야 한다.', 3730);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6594, '② 원장은 제1항에 따른 생활환경의 청결유지상태를 월 1회 이상 점검하여야 한다.', 3730);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6595, '① 영 제42조에 따른 정기검진은 분기별로 1회 이상 실시하되, 「학교건강검사규칙」 제4조 및 제5조에 따른 신체검사 및 건강검진이 연 1회 이상 포함되어야 한다.', 3732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6596, '② 영 제3조제1항제1호에 따른 초ㆍ중등교육소년원(이하 "소년원학교"라 한다)의 원장(이하 "소년원학교장"이라 한다)은 보호소년을 대상으로 연 1회 이상 체력검사를 실시하고 그 결과를 기록ㆍ유지해야 한다. <개정 2021.4.20>', 3732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6597, '③ 제2항에 따른 체력검사의 대상ㆍ종목ㆍ시기ㆍ방법ㆍ급수판정 및 관리 등에 관하여는 「학교건강검사규칙」 제7조부터 제9조까지의 규정을 준용한다.', 3732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6598, '① 소년원등의 소속 의료인은 보호소년등의 치료를 위하여 보호소년등을 진료한 의료인 또는 의료기관의 장에게 「의료법」 제22조 또는 제23조에 따른 진료기록의 내용 확인이나 진료기록의 사본 및 환자의 진료경과에 대한 소견 등을 송부하거나 전송할 것을 요청하는 경우에는 같은 법 제21조의2제1항에 따라 해당 보호소년이나 그 보호자의 동의를 받아야 한다.', 3735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6599, '② 소년원등의 소속 의료인은 의료재활소년원 출원생이 외래진료를 받은 법 제20조의3제2항 전단에 따라 법무부장관이 지정하는 기관(이하 "지정법무병원"이라 한다)의 의료인 또는 의료기관의 장으로부터 「의료법」 제21조의2에 따라 요청받은 같은 법 제22조 또는 제23조에 따른 진료기록의 내용 확인이나 진료기록의 사본 및 환자의 진료경과에 대한 소견 등을 송부 또는 전송하려는 경우에는 해당 출원생이나 그 보호자의 동의를 받아야 한다.', 3735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6600, '① 법 제20조의3제1항 및 제2항에 따른 외래진료기간은 의료재활소년원 출원일부터 10년의 범위로 한다.', 3736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6601, '② 법 제20조의3제1항 및 제2항에 따른 외래진료의 방법은 영 제3조제1항제3호의 약물 오ㆍ남용 및 정신장애에 대한 의료재활을 위하여 필요한 정신건강의학과 의사의 진료, 검사시설에 의한 검사, 처방 및 투약 등으로 한다.', 3736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6602, '① 법무부장관은 법 제20조의3제2항 전단에 따라 의료재활소년원 출원생이 지정법무병원에서 외래진료를 받도록 한 경우에는 같은 항 후단에 따라 예산의 범위에서 지정법무병원에 외래진료 진료비용(「국민건강보험법」, 「의료급여법」, 그 밖의 다른 법령에 따라 의료재활소년원 출원생 또는 보호자등이 부담하지 않는 비용은 제외한다)을 지급한다.', 3737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6603, '② 제1항에 따라 외래진료 진료비용을 지급받으려는 지정법무병원의 장은 별지 제11호서식의 외래진료 진료비용 지급 청구서에 의료재활소년원 출원생별 진료비 계산서를 첨부하여 「치료감호 등에 관한 법률 시행령」 제4조의5제2항에 따른 제출기간에 법무부장관에게 제출해야 한다.', 3737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6604, '① 법 제3조제2항 각 호에 따른 분류심사, 상담조사 및 검사의 결정 전 조사(이하 "분류심사등"이라 한다)는 면접조사, 심리검사, 정신의학적 진단, 행동관찰, 자기기록 검토, 자료조회, 현지조사 등의 방법에 따른다. <개정 2021.4.20>', 3741);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6605, '② 분류심사는 다음 각 호와 같이 구분한다.', 3741);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6606, '③ 분류심사의 실시기준은 별표 4와 같다.', 3741);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6607, '① 면접조사는 다음 각 호의 구분에 따른 방법으로 하여야 한다. <개정 2010.12.13, 2021.4.20>', 3742);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6608, '② 분류심사관은 면접대상자가 심리적 안정감을 가질 수 있도록 친절하게 대하고 용모ㆍ태도ㆍ언어 등에 유의하여야 한다.', 3742);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6609, '① 소년에 대한 행동관찰은 객관적이고 신뢰성있게 하고 그 결과가 분류심사등에 유용하도록 제공되어야 한다.', 3743);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6610, '② 소년분류심사원장은 행동관찰 업무를 적정하게 하기 위하여 담당직원의 교육, 부서간의 협조 독려 그 밖에 필요한 조치를 하여야 한다.', 3743);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6611, '① 소년분류심사원장은 법 제25조제2항에 따라 다음 각 호의 어느 하나에 해당하는 사람 중에서 분류심사관을 임명하여야 한다. <개정 2011.4.5, 2022.12.19>', 3744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6612, '② 소년분류심사원장은 각종 전문교육, 관련 학회 등에 분류심사관의 참여를 적극 권장하는 등 분류심사관의 자질향상을 위하여 노력하여야 한다. <개정 2010.12.13>', 3744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6613, '③ 소년분류심사원장은 분류심사에 필요한 각종 검사기구의 구비, 전문성 증진을 위한 연구개발지원 등 분류심사의 과학화를 위하여 노력하여야 한다. <개정 2010.12.13>', 3744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6614, '① 소년원장은 신입보호소년에 대하여 생활규범지도, 기초교육, 적응훈련 그 밖에 필요한 지도를 함으로써 신입보호소년이 소년원에 신속히 적응하고 심신의 안정을 도모할 수 있도록 하여야 한다.', 3746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6615, '② 제1항에 따른 신입자교육기간은 10일 이내로 한다.', 3746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6616, '① 소년원장은 보호소년이 제54조에 따른 기본교육과정을 마치고 퇴원 또는 임시퇴원의 요건을 갖춘 때에는 사회적응에 필요한 진로상담, 장래의 생활설계에 대한 지도, 퇴원 또는 임시퇴원 후의 준수사항에 대한 교육 그 밖에 사회복귀에 필요한 교육을 실시한다.', 3748);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6617, '② 소년원장은 제1항에 따른 보호소년에게 퇴원이나 임시퇴원 후에도 자립생활관 이용, 취업알선 및 창업보육 등의 사회정착지원을 받을 수 있음을 알려 주어야 한다. <개정 2016.9.29, 2021.4.20>', 3748);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6618, '③ 제1항에 따른 사회복귀교육기간은 10일 이내로 한다.', 3748);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6619, '① 영 제58조제1항에 따른 소년관리기록부에는 다음 각 호의 자료가 포함되어야 한다. <개정 2014.1.29, 2021.4.20>', 3752);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6620, '② 원장은 보호소년등을 다른 기관으로 이송할 때에는 영 제64조에 따른 학교생활기록부와 함께 소년관리기록부를 송부하여야 한다.', 3752);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6621, '① 소년원학교장은 학칙을 제정하거나 개정할 때에는 법무부장관의 승인을 받아야 한다.', 3753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6622, '② 제1항에 따른 학칙에는 다음 각 호의 사항이 포함되어야 한다.', 3753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6623, null, 3754);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6624, '① 영 제67조에 따라 졸업대상자로 결정된 보호소년에 대하여는 별지 제18호서식의 졸업대장에 기록하고, 별지 제19호서식의 졸업증서를 발급한다.', 3758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6625, '② 법 제34조제1항에 따라 전적학교(前籍學校)의 졸업장 취득을 위해 학적사항을 통지하는 방법 및 절차 등에 관하여는 제64조를 준용한다. <개정 2021.4.20>', 3758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6626, '③ 제1항에 따른 졸업장 및 법 제34조에 따른 전적학교의 졸업장은 가능하면 보호소년이 모두 모인 장소에서 소년원학교장이 본인에게 직접 수여해야 한다. <개정 2021.4.20>', 3758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6627, '① 소년원장은 필요하다고 판단되는 경우 「근로자직업능력 개발법」에서 고용노동부장관이 정한 직업능력개발훈련기준에 따라 직업능력개발훈련 직종을 신설 또는 폐지할 수 있다. 이 경우 지방고용노동관서의 장과 협의를 거쳐 법무부장관의 승인을 받아야 한다. <개정 2014.1.29>', 3760);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6628, '② 소년원장은 제1항에 따라 직업능력개발훈련 직종을 신설하거나 폐지하는 경우에는 산업계의 인력수요를 조사ㆍ파악하여 이를 적절히 반영하여야 한다.', 3760);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6629, '③ 제1항에 따라 신설되는 직종의 수업일수, 교과편성 그 밖에 필요한 사항은 법무부장관의 승인을 받아 소년원장이 정한다.', 3760);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6630, '① 직업능력개발훈련을 받을 수 있는 보호소년은 15세 이상으로 한다.', 3761);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6631, '② 소년원장은 훈련직종 또는 훈련과정에 따라 보호소년의 연령 또는 학력의 기준을 따로 정할 수 있다.', 3761);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6632, '① 소년원장은 법 제37조제1항에 따라 통근취업을 하는 보호소년의 원만한 적응과 교통편의 등을 위하여 예산의 범위에서 통근취업 기간 중의 교통비 전액 또는 일부를 지원할 수 있다.', 3762);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6633, '② 소년원장은 보호소년의 통근취업으로 발생한 보수 등에 관하여는 영 제47조의 규정을 준용하여 관리하여야 한다.', 3762);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6634, '③ 영 제76조제2항에 따른 통근취업약정서는 별지 제24호서식에 따른다.', 3762);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6635, '① 원장은 보호소년등의 심신이 조화롭게 성장ㆍ발달할 수 있도록 일과를 진행하여야 한다.', 3763);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6636, '② 원장은 보호소년등이 8시간 이상 취침할 수 있도록 하여야 한다. 다만, 수업시간 수 확보 등 교육과정의 운영상 불가피한 경우에는 그러하지 아니하다.', 3763);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6637, '③ 원장은 교정교육상 특히 필요한 경우를 제외하고는 보호소년등의 정서함양을 위하여 공휴일에는 직원의 지도로 보호소년등이 다양한 여가선용프로그램에 참여하거나 휴식할 수 있도록 하여야 한다.', 3763);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6638, '④ 국경일 및 스승의 날, 성년의 날 등 교육적으로 필요하다고 인정되는 기념일에는 경축ㆍ기념의식 또는 관련 교육행사를 가질 수 있다. <개정 2014.1.29>', 3763);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6639, '① 소년원장은 보호소년이 자발적으로 교육목표를 달성할 수 있도록 자치회를 조직하여 운영하게 할 수 있다.', 3765);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6640, '② 제1항에 따른 자치회는 소년원의 관리ㆍ규율ㆍ설비ㆍ급양(給養)ㆍ의료 및 위생에 관한 업무에 관여할 수 없다. 다만, 소년원장 또는 직원이 함께 참석하여 자치회를 개최하는 경우에는 관련 의견을 제시할 수 있다. <개정 2022.2.7>', 3765);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6641, '③ 제1항에 따른 자치회의 대표자와 임원의 임면, 자치회의 조직 및 운영에 관하여 필요한 사항은 소년원장이 정한다.', 3765);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6642, '① 원장은 법 제42조의2에 따른 대안교육과정의 운영을 위한 계획을 수립하여 시행하여야 한다.', 3766);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6643, '② 제1항에 따른 대안교육과정운영계획에는 다음 각 호의 내용이 포함되어야 한다. 다만, 교육기간 및 대상에 따라 이를 달리 수립ㆍ시행할 수 있다. <개정 2014.1.29>', 3766);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6644, '③ 원장은 대안교육대상자와 보호소년등을 분리하여 관리하여야 한다.', 3766);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6645, '① 원장은 교정교육의 효과를 높이기 위하여 필요하다고 인정되는 경우에는 관계직원으로 하여금 보호자상담을 실시하게 할 수 있다.', 3767);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6646, '② 관계직원이 제1항에 따른 보호자상담을 실시하려는 때에는 지정된 장소에서 실시하고 별지 제25호서식의 보호자상담부에 상담내용을 기록ㆍ유지하여야 한다.', 3767);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6647, '③ 영 제86조제1항에 따른 보호자교육의 대상자를 선정하는 때에는 제1항에 따른 보호자상담 결과를 고려하여야 한다.', 3767);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6648, '① 소년원장이 법 제43조제3항 및 제44조에 따라 관할 보호관찰심사위원회에 보호소년의 출원심사를 신청하는 경우에는 처우ㆍ징계위원회의 심사를 거쳐 퇴원, 임시퇴원 여부를 구분하여 신청해야 한다. <개정 2021.4.20>', 3768);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6649, '②제1항에 따른 보호소년의 출원에 관한 처우ㆍ징계위원회의 심사를 할 때에는 보호소년의 생활태도, 교정성적, 사회적응 정도 및 보호자의 보호력 등을 종합적으로 고려해야 한다. <개정 2021.4.20>', 3768);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6650, '③그 밖에 보호소년의 출원에 관한 처우ㆍ징계위원회의 심사 및 보호관찰심사위원회로의 심사 신청에 관한 사항은 법무부장관이 따로 정한다. <개정 2021.4.20>', 3768);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6651, null, 3769);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6652, null, 3770);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6653, '① 소년원장은 보호소년이 임시퇴원하는 경우에는 보호관찰의 실효성을 높이기 위하여 지체 없이 임시퇴원자에 관한 분류심사서 사본 및 별지 제26호서식의 교육ㆍ생활지도부 등을 해당 보호관찰소에 송부하여야 한다. <개정 2014.1.29>', 3771);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6654, '② 소년원장은 법 제46조제1항에 따른 계속수용의 사유가 소멸하여 보호소년을 보호자등에게 인도할 때에는 보호소년과 보호자등에게 지체 없이 관할보호관찰소에 출석ㆍ신고할 것을 고지하고 보호관찰소장에게 출원사실을 통보하여야 한다.', 3771);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6655, '① 소년원장은 퇴원 또는 임시퇴원이 허가된 보호소년에 대하여 수료식을 실시하고 별지 제27호서식에 따른 퇴원증 또는 별지 제28호서식에 따른 임시퇴원증을 내주어야 한다.', 3772);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6656, '② 소년원장은 임시퇴원자에 대하여 보호관찰기간 중의 준수사항을 이행하도록 교육하고 신고기일 이내에 관할보호관찰소에 출석하여 신고할 것을 알려주어야 한다.', 3772);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6657, '① 법 제45조제1항에 따른 보호소년의 인도에 관한 통지는 별지 제29호서식에 따른다.', 3773);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6658, '② 소년원장은 법 제45조제2항에 따라 보호소년을 보호자, 사회복지단체 또는 독지가 등에게 인도할 때에는 별지 제30호서식의 보호자인도부에 그 사실을 기록ㆍ유지하여야 한다.', 3773);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6659, '① 원장은 법 제45조의2에 따른 사회정착지원에 관한 계획을 수립ㆍ시행하여야 한다. <개정 2016.9.29>', 3774);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6660, '② 제1항에 따른 계획은 취업ㆍ진학 등 보호소년등의 진로를 고려하여 수립하되, 이 계획에는 방문ㆍ출석ㆍ통신지도 등 사회정착지원 방법과 기간ㆍ횟수 등의 구체적인 내용이 포함되어야 한다. <개정 2016.9.29>', 3774);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6661, '③ 원장은 제1항에 따른 계획을 수립하기 전에 보호소년등으로부터 사회정착지원을 희망하는 구체적인 분야 등을 청취한 후 이를 계획에 반영하여야 한다. <개정 2016.9.29>', 3774);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6662, '④ 원장은 법 제45조의2제2항에 따라 사회정착지원 기간을 연장하려는 경우에는 보호소년등의 재범 여부, 취업ㆍ진학 여부, 주거 안정 여부, 그 밖에 사회정착지원의 필요성 등을 고려하여 판단하여야 한다. <개정 2016.9.29>', 3774);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6663, '⑤ 원장은 보호소년등이 무의탁소년인 경우에는 법 제51조에 따른 소년보호협회가 영 제98조에 따라 운영하는 자립지원시설의 이용지원, 취업알선, 그 밖에 필요한 사회정착지원을 하여야 한다. <개정 2016.9.29>', 3774);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6664, '① 법 제46조제1항에 따른 보호소년의 계속수용은 다음 각 호의 어느 하나에 해당하는 사유로 해당 보호소년과 보호자등이 희망하는 경우에 한정한다.', 3777);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6665, '② 보호소년과 보호자등이 제1항에 따른 사유로 계속수용을 희망할 때에는 퇴원일 또는 임시퇴원일을 기준으로 7일 전까지 별지 제32호서식의 계속수용신청서를 소년원장에게 제출해야 한다. <개정 2021.4.20>', 3777);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6666, '③ 소년원장은 제2항에 따른 계속수용신청서를 접수받은 경우에는 처우ㆍ징계위원회의 심의를 거쳐 계속수용을 허용할 수 있다. 이 경우 해당 보호소년에게 계속수용 중의 준수사항을 지시할 수 있다. <개정 2021.4.20>', 3777);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6667, '④ 계속수용기간은 다음 각 호와 같다. 이 경우 보호소년의 의사를 존중하여야 한다.', 3777);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6668, '⑤ 계속수용의 교육과정은 특별한 프로그램이 마련된 경우를 제외하고는 퇴원 또는 임시퇴원허가 이전의 기본교육과정으로 분류하여야 한다.', 3777);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6669, '⑥ 법 제46조제3항에 따른 보호소년의 계속수용사실의 통지는 별지 제33호서식에 따른다.', 3777);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6670, '① 영 제88조제2항에 따라 임시퇴원취소자의 신병을 인수한 소년원장은 지체 없이 임시퇴원 당시의 해당 소년원장에게 신병인수 사실을 알리고, 가정ㆍ학교ㆍ사회환경 및 임시퇴원 기간 중의 생활상태를 종합심사하기 위한 처우ㆍ징계위원회의 심사를 거쳐 자체수용 또는 이송여부를 결정해야 한다. <개정 2021.4.20>', 3778);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6671, '② 제1항에 따라 임시퇴원취소자를 자체수용하기로 결정한 때에는 지체 없이 임시퇴원 당시의 해당 소년원장에게 그 사실을 알리고, 개별처우계획의 수립에 필요한 자료의 제출을 요구할 수 있다.', 3778);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6672, '③ 제1항에 따라 이송을 결정한 때에는 지체 없이 임시퇴원취소자의 신병을 임시퇴원 당시의 소년원에 이송하여야 한다.', 3778);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6673, '① 소년원장은 임시퇴원된 보호소년이 영 제88조에 따라 임시퇴원이 취소되어 재수용된 때에는 제53조에 따른 신입자교육을 실시하고, 처우ㆍ징계위원회의 심사를 거쳐 개별처우계획을 새로 수립해야 한다. 다만, 재수용된 보호소년의 잔여 수용기간이 40일 미만인 경우에는 처우ㆍ징계위원회의 심사를 생략하고 임시퇴원 당시의 과정에 편성할 수 있다. <개정 2014.1.29, 2021.4.20>', 3779);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6674, '② 소년원장은 임시퇴원자가 보호관찰기간 중에 범법행위를 하여 임시퇴원이 취소되고 징역 또는 금고 이상의 유죄판결이 확정되거나 보호처분에 의하여 소년원에 송치된 때에는 이전의 보호처분취소를 법원소년부에 신청하여야 한다.', 3779);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6675, '① 청소년심리상담실 이용에 따른 실비는 그 수혜자가 부담함을 원칙으로 한다. 다만, 다음 각 호의 어느 하나에 해당하는 사람에게는 실비의 징수를 면제할 수 있다.', 3781);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6676, '② 실비의 산정기준은 소속 공무원의 인건비를 제외한 프로그램 운영비 및 검사용지 매입가를 기준으로 하되, 100원 미만은 버린다.', 3781);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6677, '① 법무부장관은 보호소년등의 선도ㆍ보호에 관한 학식과 경험이 풍부한 자를 소년보호위원으로 위촉하여 교정교육에 참여시킬 수 있다. 다만, 다음 각 호의 어느 하나에 해당하는 자는 소년보호위원으로 위촉할 수 없다.', 3782);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6678, '② 원장은 소년보호위원으로 위촉된 자가 제1항 각 호의 어느 하나에 해당되는 사유가 발생한 때에는 지체 없이 사유서 등을 첨부하여 법무부장관에게 해촉을 신청하여야 한다.', 3782);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6679, '① 법 제51조에 따라 설치된 소년보호협회(이하 "협회"라 한다)는 영 제98조제2항에 따른 수익사업의 경영으로 목적사업에 지장을 초래하여서는 아니되며, 그 수익은 목적사업을 위하여 사용하여야 한다.', 3784);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6680, '② 협회는 영 제98조제3항에 따라 수익사업의 승인 또는 변경승인을 신청하는 경우에는 승인신청서에 다음 각 호의 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 3784);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6681, '③ 영 제99조제3항에 따라 협회가 법무부장관에게 제출하는 사업실적 및 결산서에는 해당 회계연도의 대차대조표ㆍ손익계산서ㆍ재산목록ㆍ잉여금처분계산서ㆍ감사의견서 및 관련 서류가 포함되어야 한다.', 3784);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6682, '① 영 제102조제1항에 따른 기부금품의 접수 영수증은 「법인세법 시행규칙」 제82조제7항제3호의3의 별지 제63호의3서식에 따른다.', 3785);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6683, '② 영 제102조제5항에 따른 기부금품의 접수현황 및 사용실적 등에 관한 장부는 별지 제35호서식에 따른다.', 3785);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6684, '① 이 법에서 "치료감호대상자"란 다음 각 호의 어느 하나에 해당하는 자로서 치료감호시설에서 치료를 받을 필요가 있고 재범의 위험성이 있는 자를 말한다. <개정 2014.12.30, 2020.10.20>', 3787);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6685, '② 제1항제2호의 남용되거나 해독을 끼칠 우려가 있는 물질에 관한 자세한 사항은 대통령령으로 정한다.', 3787);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6686, null, 3788);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6687, null, 3789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6688, '① 치료감호사건의 토지관할은 치료감호사건과 동시에 심리하거나 심리할 수 있었던 사건의 관할에 따른다.', 3790);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6689, '② 치료감호사건의 제1심 재판관할은 지방법원합의부 및 지방법원지원 합의부로 한다. 이 경우 치료감호가 청구된 치료감호대상자(이하 "피치료감호청구인"이라 한다)에 대한 치료감호사건과 피고사건의 관할이 다른 때에는 치료감호사건의 관할에 따른다.', 3790);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6690, '① 검사는 치료감호대상자가 치료감호를 받을 필요가 있는 경우 관할 법원에 치료감호를 청구할 수 있다.', 3791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6691, '② 치료감호대상자에 대한 치료감호를 청구할 때에는 정신건강의학과 등의 전문의의 진단이나 감정(鑑定)을 참고하여야 한다. 다만, 제2조제1항제3호에 따른 치료감호대상자에 대하여는 정신건강의학과 등의 전문의의 진단이나 감정을 받은 후 치료감호를 청구하여야 한다. <개정 2011.8.4>', 3791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6692, '③ 치료감호를 청구할 때에는 검사가 치료감호청구서를 관할 법원에 제출하여야 한다. 치료감호청구서에는 피치료감호청구인 수만큼의 부본(副本)을 첨부하여야 한다.', 3791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6693, '④ 치료감호청구서에는 다음 각 호의 사항을 적어야 한다.', 3791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6694, '⑤ 검사는 공소제기한 사건의 항소심 변론종결 시까지 치료감호를 청구할 수 있다.', 3791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6695, '⑥ 법원은 치료감호 청구를 받으면 지체 없이 치료감호청구서의 부본을 피치료감호청구인이나 그 변호인에게 송달하여야 한다. 다만, 공소제기와 동시에 치료감호 청구를 받았을 때에는 제1회 공판기일 전 5일까지, 피고사건 심리 중에 치료감호 청구를 받았을 때에는 다음 공판기일 전 5일까지 송달하여야 한다.', 3791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6696, '⑦ 법원은 공소제기된 사건의 심리결과 치료감호를 할 필요가 있다고 인정할 때에는 검사에게 치료감호 청구를 요구할 수 있다.', 3791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6697, '① 검사는 범죄를 수사할 때 범죄경력이나 심신장애 등을 고려하여 치료감호를 청구함이 상당하다고 인정되는 자에 대하여는 치료감호 청구에 필요한 자료를 조사하여야 한다.', 3792);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6698, '② 사법경찰관리(특별사법경찰관리를 포함한다. 이하 같다)는 검사의 지휘를 받아 제1항에 따른 조사를 하여야 한다.', 3792);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6699, '① 치료감호대상자에 대하여 치료감호를 할 필요가 있다고 인정되고 다음 각 호의 어느 하나에 해당하는 사유가 있을 때에는 검사는 관할 지방법원 판사에게 청구하여 치료감호영장을 발부받아 치료감호대상자를 보호구속[보호구금(保護拘禁)과 보호구인(保護拘引)을 포함한다. 이하 같다]할 수 있다.', 3793);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6700, '② 사법경찰관은 제1항의 요건에 해당하는 치료감호대상자에 대하여 검사에게 신청하여 검사의 청구로 관할 지방법원 판사의 치료감호영장을 발부받아 보호구속할 수 있다.', 3793);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6701, '③ 제1항과 제2항에 따른 보호구속에 관하여는 「형사소송법」 제201조제2항부터 제4항까지, 제201조의2부터 제205조까지, 제208조, 제209조 및 제214조의2부터 제214조의4까지의 규정을 준용한다.', 3793);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6702, null, 3794);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6703, '① 제7조제1호에 따른 치료감호청구사건의 공판을 시작한 후 피치료감호청구인이 「형법」 제10조제1항에 따른 심신장애에 해당되지 아니한다는 명백한 증거가 발견되고 검사의 청구가 있을 때에는 법원은「형사소송법」에 따른 공판절차로 이행(移行)하여야 한다.', 3797);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6704, '② 제1항에 따라 공판절차로 이행한 경우에는 치료감호를 청구하였던 때에 공소를 제기한 것으로 본다. 이 경우 치료감호청구서는 공소장과 같은 효력을 가지며, 공판절차로 이행하기 전의 심리는 공판절차에 따른 심리로 본다. 공소장에 적어야 할 사항은 「형사소송법」 제298조의 절차에 따라 변경할 수 있다.', 3797);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6705, '③ 약식명령(略式命令)이 청구된 후 치료감호가 청구되었을 때에는 약식명령청구는 그 치료감호가 청구되었을 때부터 공판절차에 따라 심판하여야 한다.', 3797);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6706, '① 법원은 치료감호사건을 심리하여 그 청구가 이유 있다고 인정할 때에는 판결로써 치료감호를 선고하여야 하고, 이유 없다고 인정할 때 또는 피고사건에 대하여 심신상실 외의 사유로 무죄를 선고하거나 사형을 선고할 때에는 판결로써 청구기각을 선고하여야 한다.', 3799);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6707, '② 치료감호사건의 판결은 피고사건의 판결과 동시에 선고하여야 한다. 다만, 제7조에 따라 공소를 제기하지 아니하고 치료감호만을 청구한 경우에는 그러하지 아니하다.', 3799);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6708, '③ 치료감호선고의 판결이유에는 요건으로 되는 사실, 증거의 요지와 적용 법 조문을 구체적으로 밝혀야 한다.', 3799);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6709, '④ 법원은 피고사건에 대하여 「형사소송법」 제326조 각 호, 제327조제1호부터 제4호까지 및 제328조제1항 각 호(제2호 중 피고인인 법인이 존속하지 아니하게 되었을 때는 제외한다)의 사유가 있을 때에는 치료감호청구사건에 대하여도 청구기각의 판결 또는 결정을 하여야 한다. 치료감호청구사건에 대하여 위와 같은 사유가 있을 때에도 또한 같다.', 3799);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6710, '① 검사 또는 피치료감호청구인과 「형사소송법」 제339조부터 제341조까지에 규정된 자는 「형사소송법」의 절차에 따라 상소할 수 있다.', 3801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6711, '② 피고사건의 판결에 대하여 상소 및 상소의 포기ㆍ취하가 있을 때에는 치료감호청구사건의 판결에 대하여도 상소 및 상소의 포기ㆍ취하가 있는 것으로 본다. 상소권회복 또는 재심(再審)의 청구나 비상상고가 있을 때에도 또한 같다.', 3801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6712, '① 법원에서 피치료감호청구인을 보호구속하는 경우의 치료감호영장에 관하여는 제6조제1항을 준용한다.', 3802);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6713, '② 제2조제1항 각 호의 어느 하나에 해당하는 치료감호대상자에 대한 치료감호청구사건에 관하여는 「형사소송법」 제282조 및 제283조를 준용한다.', 3802);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6714, '① 치료감호를 선고받은 자(이하 "피치료감호자"라 한다)에 대하여는 치료감호시설에 수용하여 치료를 위한 조치를 한다.', 3803);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6715, '② 피치료감호자를 치료감호시설에 수용하는 기간은 다음 각 호의 구분에 따른 기간을 초과할 수 없다.', 3803);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6716, '③ 「전자장치 부착 등에 관한 법률」 제2조제3호의2에 따른 살인범죄(이하 "살인범죄"라 한다)를 저질러 치료감호를 선고받은 피치료감호자가 살인범죄를 다시 범할 위험성이 있고 계속 치료가 필요하다고 인정되는 경우에는 법원은 치료감호시설의 장의 신청에 따른 검사의 청구로 3회까지 매회 2년의 범위에서 제2항 각 호의 기간을 연장하는 결정을 할 수 있다. <신설 2013.7.30, 2020.2.4>', 3803);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6717, '④ 치료감호시설의 장은 정신건강의학과 등 전문의의 진단이나 감정을 받은 후 제3항의 신청을 하여야 한다. <신설 2013.7.30>', 3803);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6718, '⑤ 제3항에 따른 검사의 청구는 제2항 각 호의 기간 또는 제3항에 따라 연장된 기간이 종료하기 6개월 전까지 하여야 한다. <신설 2013.7.30>', 3803);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6719, '⑥ 제3항에 따른 법원의 결정은 제2항 각 호의 기간 또는 제3항에 따라 연장된 기간이 종료하기 3개월 전까지 하여야 한다. <신설 2013.7.30>', 3803);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6720, '⑦ 제3항의 결정에 대한 검사, 피치료감호자, 그 법정대리인의 항고와 재항고에 관하여는 「성폭력범죄자의 성충동 약물치료에 관한 법률」 제22조제5항부터 제11항까지의 규정을 준용하되, "성폭력 수형자"는 "피치료감호자"로 본다. <신설 2013.7.30>', 3803);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6721, '⑧ 제1항에 따른 치료감호시설에서의 치료와 그 밖에 필요한 사항은 대통령령으로 정한다. <개정 2013.7.30>', 3803);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6722, '① 제16조제1항에서 "치료감호시설"이란 다음 각 호의 시설을 말한다. <개정 2022.1.4>', 3804);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6723, '② 지정법무병원은 피치료감호자를 다른 환자와 구분하여 수용한다.', 3804);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6724, '③ 국가는 지정법무병원에 대하여 예산의 범위에서 시설의 설치 및 운영에 필요한 경비를 보조하여야 한다.', 3804);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6725, '④ 지정법무병원의 지정절차, 운영, 치료, 경비보조, 그 밖에 필요한 사항은 대통령령으로 정한다.', 3804);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6726, '① 치료감호의 집행은 검사가 지휘한다.', 3805);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6727, '② 제1항에 따른 지휘는 판결서등본을 첨부한 서면으로 한다.', 3805);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6728, '① 검사는 보호구금되어 있지 아니한 피치료감호자에 대한 치료감호를 집행하기 위하여 피치료감호자를 소환할 수 있다.', 3809);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6729, '② 피치료감호자가 제1항에 따른 소환에 응하지 아니하면 검사는 치료감호집행장을 발부하여 보호구인할 수 있다.', 3809);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6730, '③ 피치료감호자가 도망하거나 도망할 염려가 있을 때 또는 피치료감호자의 현재지(現在地)를 알 수 없을 때에는 제2항에도 불구하고 소환 절차를 생략하고 치료감호집행장을 발부하여 보호구인할 수 있다.', 3809);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6731, '④ 치료감호집행장은 치료감호영장과 같은 효력이 있다.', 3809);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6732, '① 제37조에 따른 치료감호심의위원회는 피치료감호자에 대하여 치료감호 집행을 시작한 후 6개월마다 국립법무병원에서 지정법무병원으로 이송할 것인지를 심사ㆍ결정한다. <개정 2022.1.4>', 3810);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6733, '② 지정법무병원으로 이송된 피치료감호자가 수용질서를 해치거나 증상이 악화되는 등의 사유로 지정법무병원에서 계속 치료하기 곤란할 경우 제37조에 따른 치료감호심의위원회는 지정법무병원의 피치료감호자를 국립법무병원으로 재이송하는 결정을 할 수 있다. <개정 2022.1.4>', 3810);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6734, '③ 제37조에 따른 치료감호심의위원회는 제1항 및 제2항의 결정을 위하여 치료감호시설의 장 또는 소속 정신건강의학과 의사의 의견을 청취할 수 있다.', 3810);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6735, '① 제37조에 따른 치료감호심의위원회는 치료감호만을 선고받은 피치료감호자에 대한 집행이 시작된 후 1년이 지났을 때에는 상당한 기간을 정하여 그의 법정대리인, 배우자, 직계친족, 형제자매(이하 "법정대리인등"이라 한다)에게 치료감호시설 외에서의 치료를 위탁할 수 있다.', 3812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6736, '② 제37조에 따른 치료감호심의위원회는 치료감호와 형이 병과되어 형기(刑期)에 상당하는 치료감호를 집행받은 자에 대하여는 상당한 기간을 정하여 그 법정대리인등에게 치료감호시설 외에서의 치료를 위탁할 수 있다.', 3812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6737, '③ 제1항이나 제2항에 따라 치료위탁을 결정하는 경우 치료감호심의위원회는 법정대리인등으로부터 치료감호시설 외에서의 입원ㆍ치료를 보증하는 내용의 서약서를 받아야 한다.', 3812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6738, '① 치료감호시설의 장은 피치료감호자의 건강한 생활이 보장될 수 있도록 쾌적하고 위생적인 시설을 갖추고 의류, 침구, 그 밖에 처우에 필요한 물품을 제공하여야 한다.', 3814);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6739, '② 피치료감호자에 대한 의료적 처우는 정신병원에 준하여 의사의 조치에 따르도록 한다.', 3814);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6740, '③ 치료감호시설의 장은 피치료감호자의 사회복귀에 도움이 될 수 있도록 치료와 개선 정도에 따라 점진적으로 개방적이고 완화된 처우를 하여야 한다.', 3814);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6741, '① 피치료감호청구인은 피치료감호자와 구분하여 수용한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 피치료감호청구인을 피치료감호자와 같은 치료감호시설에 수용할 수 있다.', 3815);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6742, '② 제1항 단서에 따라 같은 치료감호시설에 수용된 피치료감호자와 피치료감호청구인은 분리하여 수용한다.', 3815);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6743, '③ 치료감호시설의 장은 피치료감호청구인이 치료감호시설에 수용된 경우에는 그 특성을 고려하여 적합한 처우를 하여야 한다.', 3815);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6744, '④ 제3항에 따른 피치료감호청구인에 대한 처우의 구체적 기준 및 절차는 대통령령으로 정한다.', 3815);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6745, '① 치료감호시설의 장은 피치료감호자 및 피치료감호청구인(이하 "피치료감호자등"이라 한다)이 다음 각 호의 어느 하나에 해당하는 경우가 아니면 피치료감호자등에 대하여 격리 또는 묶는 등의 신체적 제한을 할 수 없다. 다만, 피치료감호자등의 신체를 묶는 등으로 직접적으로 제한하는 것은 제1호의 경우에 한정한다.', 3816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6746, '② 치료감호시설의 장은 제1항에 따라 피치료감호자등에 대하여 격리 또는 묶는 등의 신체적 제한을 하려는 경우 정신건강의학과 전문의의 지시에 따라야 한다. 다만, 제1항제2호 또는 제3호에 해당하는 경우에는 담당 의사의 지시에 따를 수 있다. <개정 2020.10.20>', 3816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6747, '③ 제1항 및 제2항에 따라 피치료감호자등을 격리하는 경우에는 해당 치료감호시설 안에서 하여야 한다.', 3816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6748, '④ 제1항 및 제2항에 따라 피치료감호자등을 신체적으로 제한한 경우에는 그 사유, 제한의 기간 및 해제 시기를 포함한 내용을 대통령령으로 정하는 바에 따라 작성ㆍ보존하여야 한다.', 3816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6749, '① 치료감호시설의 장은 피치료감호자등이 치료감호시설에서 치료하기 곤란한 질병에 걸렸을 때에는 외부의료기관에서 치료를 받게 할 수 있다. <개정 2017.12.12>', 3819);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6750, '② 치료감호시설의 장은 제1항의 경우 본인이나 보호자 등이 직접 비용을 부담하여 치료 받기를 원하면 이를 허가할 수 있다.', 3819);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6751, '① 피치료감호자등이나 법정대리인등은 법무부장관에게 피치료감호자등의 처우개선에 관한 청원(請願)을 할 수 있다. <개정 2017.12.12>', 3821);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6752, '② 제1항에 따른 청원의 제기, 청원의 심사, 그 밖에 필요한 사항에 관하여는 대통령령으로 정한다.', 3821);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6753, '① 피치료감호자가 다음 각 호의 어느 하나에 해당하게 되면 「보호관찰 등에 관한 법률」에 따른 보호관찰(이하 "보호관찰"이라 한다)이 시작된다. <개정 2017.12.12>', 3824);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6754, '② 보호관찰의 기간은 3년으로 한다.', 3824);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6755, '③ 보호관찰을 받기 시작한 자(이하 "피보호관찰자"라 한다)가 다음 각 호의 어느 하나에 해당하게 되면 보호관찰이 종료된다. <개정 2017.12.12>', 3824);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6756, '④ 피보호관찰자가 보호관찰기간 중 새로운 범죄로 금고 이상의 형의 집행을 받게 된 때에는 보호관찰은 종료되지 아니하며, 해당 형의 집행기간 동안 피보호관찰자에 대한 보호관찰기간은 계속 진행된다. <신설 2017.12.12>', 3824);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6757, '⑤ 피보호관찰자에 대하여 제4항에 따른 금고 이상의 형의 집행이 종료ㆍ면제되는 때 또는 피보호관찰자가 가석방되는 때에 보호관찰기간이 아직 남아있으면 그 잔여기간 동안 보호관찰을 집행한다. <신설 2017.12.12>', 3824);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6758, '① 피보호관찰자는 「보호관찰 등에 관한 법률」 제32조제2항에 따른 준수사항을 성실히 이행하여야 한다.', 3825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6759, '② 제37조에 따른 치료감호심의위원회는 피보호관찰자의 치료경과 및 특성 등에 비추어 필요하다고 판단되면 제1항에 따른 준수사항 외에 다음 각 호의 사항 중 전부 또는 일부를 따로 보호관찰기간 동안 특별히 지켜야 할 준수사항으로 부과할 수 있다. <개정 2017.12.12>', 3825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6760, '③ 제37조에 따른 치료감호심의위원회는 피보호관찰자가 제1항 또는 제2항의 준수사항을 위반하거나 상당한 사정변경이 있는 경우에는 직권 또는 보호관찰소의 장의 신청에 따라 준수사항 전부 또는 일부의 추가ㆍ변경 또는 삭제에 관하여 심사하고 결정할 수 있다. <신설 2017.12.12>', 3825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6761, '④ 제1항부터 제3항까지의 규정에 따른 준수사항은 서면으로 고지하여야 한다. <신설 2017.12.12>', 3825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6762, '⑤ 보호관찰소의 장은 피보호관찰자가 제1항부터 제3항까지의 준수사항을 위반하거나 위반할 위험성이 있다고 인정할 상당한 이유가 있는 경우에는 준수사항의 이행을 촉구하고 제22조에 따른 가종료 또는 제23조에 따른 치료의 위탁(이하 "가종료등"이라 한다)의 취소 등 불리한 처분을 받을 수 있음을 경고할 수 있다. <신설 2017.12.12>', 3825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6763, '① 보호관찰소의 장은 제33조에 따른 준수사항을 위반한 피보호관찰자를 구인(拘引)할 수 있다. 이 경우 피보호관찰자의 구인에 대해서는 「보호관찰 등에 관한 법률」 제39조 및 제40조를 준용한다.', 3826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6764, '② 보호관찰소의 장은 다음 각 호의 어느 하나에 해당하는 신청을 검사에게 요청할 필요가 있다고 인정하는 경우에는 구인한 피보호관찰자를 교도소, 구치소 또는 치료감호시설에 유치할 수 있다.', 3826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6765, '③ 보호관찰소의 장은 제2항에 따라 피보호관찰자를 유치하려는 경우에는 검사에게 신청하여 검사의 청구로 관할 지방법원 판사의 허가를 받아야 한다. 이 경우 검사는 피보호관찰자가 구인된 때부터 48시간 이내에 유치허가를 청구하여야 한다.', 3826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6766, '④ 보호관찰소의 장은 유치허가를 받은 때부터 24시간 이내에 검사에게 가종료등의 취소 신청을 요청하여야 한다.', 3826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6767, '⑤ 검사는 보호관찰소의 장으로부터 제4항에 따른 신청을 받았을 경우에 그 이유가 타당하다고 인정되면 48시간 이내에 제37조에 따른 치료감호심의위원회에 가종료등의 취소를 신청하여야 한다.', 3826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6768, '⑥ 보호관찰소의 장이 제2항에 따라 피보호관찰자를 유치할 수 있는 기간은 구인한 날부터 30일로 한다. 다만, 보호관찰소의 장은 제5항에 따른 검사의 신청이 있는 경우에 제37조에 따른 치료감호심의위원회의 심사에 필요하면 검사에게 신청하여 검사의 청구로 관할 지방법원 판사의 허가를 받아 20일의 범위에서 한 차례만 유치기간을 연장할 수 있다.', 3826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6769, '⑦ 보호관찰소의 장은 다음 각 호의 어느 하나에 해당하는 경우에는 유치를 해제하고 피보호관찰자를 즉시 석방하여야 한다.', 3826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6770, '⑧ 제2항에 따라 유치된 피보호관찰자에 대하여 가종료등이 취소된 경우에는 그 유치기간을 치료감호기간에 산입한다.', 3826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6771, '① 피보호관찰자나 법정대리인등은 대통령령으로 정하는 바에 따라 출소 후의 거주 예정지나 그 밖에 필요한 사항을 미리 치료감호시설의 장에게 신고하여야 한다.', 3827);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6772, '② 피보호관찰자나 법정대리인등은 출소 후 10일 이내에 주거, 직업, 치료를 받는 병원, 피보호관찰자가 등록한 「정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률」 제3조제3호에 따른 정신건강복지센터(이하 "정신건강복지센터"라 한다), 그 밖에 필요한 사항을 보호관찰관에게 서면으로 신고하여야 한다. <개정 2013.7.30, 2016.5.29>', 3827);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6773, '① 제32조제1항제1호 또는 제2호에 해당하는 경우에는 보호관찰기간이 끝나면 피보호관찰자에 대한 치료감호가 끝난다. <개정 2017.12.12>', 3828);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6774, '② 제37조에 따른 치료감호심의위원회는 피보호관찰자의 관찰성적 및 치료경과가 양호하면 보호관찰기간이 끝나기 전에 보호관찰의 종료를 결정할 수 있다.', 3828);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6775, null, 3829);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6776, '① 치료감호시설 출소자가 치료감호시설에서의 외래진료를 신청한 경우에 치료감호시설의 장은 검사, 투약 등 적절한 진료 및 치료를 실시할 수 있다. <개정 2017.12.12>', 3831);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6777, '② 제1항에 따른 외래진료의 절차 등에 관하여 필요한 사항은 법무부령으로 정한다.', 3831);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6778, '① 보호관찰소의 장과 정신건강복지센터의 장은 피보호관찰자의 치료 및 재범방지, 사회복귀를 위하여 상호 협조하여야 한다. <개정 2016.5.29>', 3832);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6779, '② 보호관찰소의 장은 피보호관찰자에 대한 등록, 상담, 진료, 사회복귀훈련 및 이에 관한 사례 관리 등 정신보건 관련 정보를 정신건강복지센터의 장에게 요청할 수 있다. <개정 2016.5.29>', 3832);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6780, '③ 정신건강복지센터의 장은 피보호관찰자의 공동 면담 등 피보호관찰자의 치료 및 재범방지, 사회복귀를 위하여 필요한 경우 보호관찰소의 장에게 협조를 요청할 수 있다. <개정 2016.5.29>', 3832);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6781, '① 치료감호 및 보호관찰의 관리와 집행에 관한 사항을 심사ㆍ결정하기 위하여 법무부에 치료감호심의위원회(이하 "위원회"라 한다)를 둔다.', 3833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6782, '② 위원회는 판사, 검사, 법무부의 고위공무원단에 속하는 일반직공무원 또는 변호사의 자격이 있는 6명 이내의 위원과 정신건강의학과 등 전문의의 자격이 있는 3명 이내의 위원으로 구성하고, 위원장은 법무부차관으로 한다. <개정 2011.8.4, 2018.12.18>', 3833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6783, '③ 위원회는 다음 각 호의 사항을 심사ㆍ결정한다. <개정 2013.7.30, 2017.12.12>', 3833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6784, '④ 위원회에는 전문적 학식과 덕망이 있는 자 중에서 위원장의 제청으로 법무부장관이 위촉하는 자문위원을 둘 수 있다.', 3833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6785, '⑤ 위원회의 위원 중 공무원이 아닌 위원은 「형법」과 그 밖의 법률에 따른 벌칙을 적용할 때에는 공무원으로 본다. <신설 2015.12.1>', 3833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6786, '⑥ 위원회의 구성ㆍ운영ㆍ서무 및 자문위원의 위촉과 그 밖에 필요한 사항은 대통령령으로 정한다. <개정 2015.12.1>', 3833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6787, null, 3834);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6788, null, 3835);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6789, '① 위원회는 심의자료에 따라 제37조제3항에 규정된 사항을 심사한다.', 3836);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6790, '② 위원회는 제1항에 따른 심사를 위하여 필요하면 법무부 소속 공무원으로 하여금 결정에 필요한 사항을 조사하게 하거나 피치료감호자 및 피보호관찰자(이하 "피보호자"라 한다)나 그 밖의 관계자를 직접 소환ㆍ심문하거나 조사할 수 있다.', 3836);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6791, '③ 제2항에 따라 조사 명령을 받은 공무원은 다음 각 호의 권한을 가진다.', 3836);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6792, '④ 피보호자나 그 밖의 관계자는 제2항과 제3항의 소환ㆍ심문 및 조사에 응하여야 하며, 국공립기관이나 그 밖의 공공단체ㆍ민간단체는 제3항에 따라 조회나 자료 제출을 요구받았을 때에는 국가기밀 또는 공공의 안녕질서에 해를 끼치는 것이 아니면 이를 거부할 수 없다.', 3836);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6793, '① 위원회는 위원장을 포함한 재적위원 과반수의 출석으로 개의(開議)하고, 출석위원 과반수의 찬성으로 의결한다. 다만, 찬성과 반대의 수가 같을 때에는 위원장이 결정한다.', 3837);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6794, '② 결정은 이유를 붙이고 출석한 위원들이 기명날인한 문서로 한다.', 3837);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6795, '③ 위원회는 제1항에 따른 의결을 할 때 필요하면 치료감호시설의 장이나 보호관찰관에게 의견서를 제출하도록 할 수 있다.', 3837);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6796, '④ 치료감호시설의 장은 제3항에 따른 의견서를 제출할 때에는 피보호자의 상태 및 예후, 치료감호 종료의 타당성 등에 관한 피보호자 담당 의사의 의견을 참조하여야 한다.', 3837);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6797, '① 피보호자와 그 법정대리인등은 위원회의 위원에게 공정한 심사ㆍ의결을 기대하기 어려운 사정이 있으면 위원장에게 기피신청을 할 수 있다.', 3838);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6798, '② 위원장은 제1항에 따른 기피신청에 대하여 위원회의 의결을 거치지 아니하고 신청이 타당한지를 결정한다. 다만, 위원장이 결정하기에 적절하지 아니한 경우에는 위원회의 의결로 결정할 수 있다.', 3838);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6799, '③ 제1항에 따라 기피신청을 받은 위원은 제2항 단서의 의결에 참여하지 못한다.', 3838);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6800, '① 피보호자의 주거지(시설에 수용된 경우에는 그 시설을 주거지로 본다)를 관할하는 지방검찰청 또는 지청의 검사는 제37조제3항에 규정된 사항에 관하여 위원회에 그 심사ㆍ결정을 신청할 수 있다.', 3839);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6801, '② 제1항에 따른 신청을 할 때에는 심사신청서와 신청사항의 결정에 필요한 자료를 제출하여야 한다. 이 경우 치료감호시설의 장이나 보호관찰소의 장의 의견을 들어야 한다. <개정 2017.12.12>', 3839);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6802, '③ 치료감호시설의 장이나 보호관찰소의 장은 검사에게 제1항에 따른 신청을 요청할 수 있다. <개정 2017.12.12>', 3839);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6803, '① 피치료감호자와 그 법정대리인등은 피치료감호자가 치료감호를 받을 필요가 없을 정도로 치유되었음을 이유로 치료감호의 종료 여부를 심사ㆍ결정하여 줄 것을 위원회에 신청할 수 있다.', 3840);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6804, '② 제1항에 따른 신청을 할 때에는 심사신청서와 심사신청이유에 대한 자료를 제출하여야 한다.', 3840);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6805, '③ 제1항에 따른 신청은 치료감호의 집행이 시작된 날부터 6개월이 지난 후에 하여야 한다. 신청이 기각된 경우에는 6개월이 지난 후에 다시 신청할 수 있다.', 3840);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6806, '④ 위원회는 제1항에 따른 신청에 대한 심사를 마친 때에는 지체 없이 심사 기준과 그 결정 이유를 피치료감호자와 법정대리인등에게 통보하여야 한다. <개정 2017.12.12>', 3840);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6807, '① 법원은 치료명령대상자에 대하여 형의 선고 또는 집행을 유예하는 경우에는 치료기간을 정하여 치료를 받을 것을 명할 수 있다.', 3841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6808, '② 제1항의 치료를 명하는 경우 보호관찰을 병과하여야 한다. <개정 2017.12.12>', 3841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6809, '③ 제2항에 따른 보호관찰기간은 선고유예의 경우에는 1년, 집행유예의 경우에는 그 유예기간으로 한다. 다만, 법원은 집행유예 기간의 범위에서 보호관찰기간을 정할 수 있다.', 3841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6810, '④ 제1항의 치료기간은 제3항에 따른 보호관찰기간을 초과할 수 없다.', 3841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6811, '① 법원은 제44조의2에 따른 치료를 명하기 위하여 필요하다고 인정하면 피고인의 주거지 또는 그 법원의 소재지를 관할하는 보호관찰소의 장에게 범죄의 동기, 피고인의 신체적ㆍ심리적 특성 및 상태, 가정환경, 직업, 생활환경, 병력(病歷), 치료비용 부담능력, 재범위험성 등 피고인에 관한 사항의 조사를 요구할 수 있다.', 3842);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6812, '② 제1항의 요구를 받은 보호관찰소의 장은 지체 없이 이를 조사하여 서면으로 해당 법원에 알려야 한다. 이 경우 필요하다고 인정하면 피고인이나 그 밖의 관계인을 소환하여 심문하거나 소속 보호관찰관에게 필요한 사항을 조사하게 할 수 있다.', 3842);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6813, '③ 보호관찰소의 장은 제2항의 조사를 위하여 필요하다고 인정하면 국공립 기관이나 그 밖의 단체에 사실을 알아보거나 관련 자료의 열람 등 협조를 요청할 수 있다.', 3842);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6814, null, 3844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6815, '① 치료명령은 검사의 지휘를 받아 보호관찰관이 집행한다.', 3845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6816, '② 치료명령은 정신건강의학과 전문의의 진단과 약물 투여, 상담 등 치료 및 「정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률」에 따른 정신건강전문요원 등 전문가에 의한 인지행동 치료 등 심리치료 프로그램의 실시 등의 방법으로 집행한다. <개정 2016.5.29, 2017.12.12>', 3845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6817, '③ 보호관찰관은 치료명령을 받은 사람에게 치료명령을 집행하기 전에 치료기관, 치료의 방법ㆍ내용 등에 관하여 충분히 설명하여야 한다.', 3845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6818, '④ 그 밖에 치료명령의 집행에 관하여 필요한 사항은 대통령령으로 정한다.', 3845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6819, '① 법무부장관은 치료명령을 받은 사람의 치료를 위하여 치료기관을 지정할 수 있다.', 3846);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6820, '② 제1항에 따른 치료기관의 지정기준 등 필요한 사항은 법무부령으로 정한다.', 3846);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6821, '① 법원은 제44조의2에 따라 치료를 명한 선고유예를 받은 사람이 정당한 사유 없이 치료기간 중에 제44조의5의 준수사항을 위반하고 그 정도가 무거운 때에는 유예한 형을 선고할 수 있다.', 3847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6822, '② 법원은 제44조의2에 따라 치료를 명한 집행유예를 받은 사람이 정당한 사유 없이 치료기간 중에 제44조의5의 준수사항을 위반하고 그 정도가 무거운 때에는 집행유예의 선고를 취소할 수 있다.', 3847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6823, '③ 치료명령대상자에 대한 경고ㆍ구인ㆍ긴급구인ㆍ유치ㆍ선고유예의 실효 및 집행유예의 취소 등에 대하여는 「보호관찰 등에 관한 법률」 제38조부터 제45조까지, 제45조의2, 제46조 및 제47조를 준용한다.', 3847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6824, '① 제44조의2에 따른 치료명령을 받은 사람은 치료기간 동안 치료비용을 부담하여야 한다. 다만, 치료비용을 부담할 경제력이 없는 사람의 경우에는 국가가 비용을 부담할 수 있다.', 3848);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6825, '② 비용부담에 관하여 필요한 사항은 대통령령으로 정한다.', 3848);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6826, '① 치료감호 청구의 시효는 치료감호가 청구된 사건과 동시에 심리하거나 심리할 수 있었던 죄에 대한 공소시효기간이 지나면 완성된다.', 3849);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6827, '② 치료감호가 청구된 사건은 판결의 확정 없이 치료감호가 청구되었을 때부터 15년이 지나면 청구의 시효가 완성된 것으로 본다.', 3849);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6828, '① 피치료감호자는 그 판결이 확정된 후 집행을 받지 아니하고 다음 각 호의 구분에 따른 기간이 지나면 시효가 완성되어 집행이 면제된다.', 3850);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6829, '② 시효는 치료감호의 집행정지 기간 또는 가종료 기간이나 그 밖에 집행할 수 없는 기간에는 진행되지 아니한다.', 3850);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6830, '③ 시효는 피치료감호자를 체포함으로써 중단된다.', 3850);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6831, null, 3851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6832, '① 치료감호의 집행을 종료하거나 집행이 면제된 자가 피해자의 피해를 보상하고 자격정지 이상의 형이나 치료감호를 선고받지 아니하고 7년이 지났을 때에는 본인이나 검사의 신청에 의하여 그 재판의 실효(失效)를 선고할 수 있다. 이 경우 「형사소송법」 제337조를 준용한다.', 3852);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6833, '② 치료감호의 집행을 종료하거나 집행이 면제된 자가 자격정지 이상의 형이나 치료감호를 선고받지 아니하고 10년이 지났을 때에는 그 재판이 실효된 것으로 본다.', 3852);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6834, '① 치료감호의 기간은 치료감호를 집행한 날부터 기산(起算)한다. 이 경우 치료감호 집행을 시작한 첫날은 시간으로 계산하지 아니하고 1일로 산정한다.', 3853);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6835, '② 치료감호의 집행을 위반한 기간은 그 치료감호의 집행기간에 포함하지 아니한다.', 3853);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6836, '① 「군사법원법」 제2조제1항 각 호의 어느 하나에 해당하는 자에 대한 치료감호사건에 관하여는 군사법원, 군검찰부 군검사 및 군사법경찰관리가 이 법에 따른 직무를 수행한다. 이 경우 "군사법원"은 "법원", "군검찰부 군검사"는 "검사", "군사법경찰관리"는 "사법경찰관리"로 본다. <개정 2016.1.6>', 3854);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6837, '② 「군사법원법」 제2조제1항 각 호의 어느 하나에 해당하는 자에 대한 치료감호의 관리와 그 집행사항을 심사ㆍ결정하기 위하여 국방부에 군치료감호심의위원회를 둔다.', 3854);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6838, '③ 군치료감호심의위원회의 구성과 운영에 관하여는 위원회에 관한 규정을 준용한다.', 3854);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6839, '④ 군사법원, 군검찰부 군검사 또는 군치료감호심의위원회는 치료감호대상자가 「군사법원법」 제2조제1항 각 호의 어느 하나에 해당하는 자가 아님이  명백할 때에는 그 치료감호사건을 대응하는 법원ㆍ검사 또는 위원회로 이송한다. 이 경우 이송 전에 한 조사ㆍ청구ㆍ재판ㆍ신청ㆍ심사 및 결정은 이송 후에도 그 효력을 잃지 아니한다. <개정 2016.1.6>', 3854);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6840, '⑤ 법원ㆍ검사 또는 위원회는 치료감호대상자가 「군사법원법」 제2조제1항 각 호의 어느 하나에 해당하는 자임이 명백할 때에는 치료감호사건을 대응하는 군사법원ㆍ군검찰부 군검사 또는 군치료감호심의위원회로 이송한다. 이 경우 이송 전에 한 조사ㆍ청구ㆍ재판ㆍ신청ㆍ심사 및 결정은 이송 후에도 그 효력을 잃지 아니한다. <개정 2016.1.6>', 3854);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6841, '⑥ 제44조의2에 따른 치료명령을 받은 사람에 대하여는 「보호관찰 등에 관한 법률」 제56조를 준용한다. <신설 2015.12.1>', 3854);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6842, '① 치료감호시설의 장은 기관ㆍ단체 또는 개인이 피치료감호자에 대한 적절한 보호와 치료 등을 위하여 치료감호시설에 자발적으로 기탁하는 금품을 접수할 수 있다.', 3855);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6843, '② 기부자에 대한 영수증 발급, 기부금품의 용도 지정, 장부의 열람, 그 밖에 필요한 사항은 대통령령으로 정한다.', 3855);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6844, '① 피치료감호자가 치료감호 집행자의 치료감호를 위한 명령에 정당한 사유 없이 복종하지 아니하거나 도주한 경우에는 1년 이하의 징역에 처한다.', 3857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6845, '② 피치료감호자 2명 이상이 공동으로 제1항의 죄를 지은 경우에는 3년 이하의 징역에 처한다.', 3857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6846, '③ 치료감호를 집행하는 자가 피치료감호자를 도주하게 하거나 도주를 용이하게 한 경우에는 1년 이상의 유기징역에 처한다.', 3857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6847, '④ 치료감호를 집행하는 자가 뇌물을 수수ㆍ요구 또는 약속하고 제3항의 죄를 지은 경우에는 2년 이상의 유기징역에 처한다.', 3857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6848, '⑤ 타인으로 하여금 치료감호처분을 받게 할 목적으로 공공기관이나 공무원에게 거짓의 사실을 신고한 자는 10년 이하의 징역 또는 1천500만원 이하의 벌금에 처한다.', 3857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6849, '⑥ 치료감호청구사건에 관하여 피치료감호청구인을 모함하여 해칠 목적으로 「형법」 제152조제1항의 위증죄를 지은 자는 10년 이하의 징역에 처한다.', 3857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6850, '⑦ 치료감호청구사건에 관하여 「형법」 제154조의 죄를 지은 자는 10년 이하의 징역에 처한다.', 3857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6851, '⑧ 치료감호청구사건에 관하여 「형법」 제233조 또는 제234조(허위작성진단서의 행사로 한정한다)의 죄를 지은 자는 5년 이하의 징역, 10년 이하의 자격정지 또는 5천만원 이하의 벌금에 처한다. <개정 2014.1.7>', 3857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6852, '⑨ 제23조제3항에 따라 치료의 위탁을 받은 법정대리인등이 그 서약을 위반하여 피치료감호자를 도주하게 하거나 도주를 용이하게 한 경우에는 3년 이하의 징역 또는 500만원 이하의 벌금에 처한다.', 3857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6853, '⑩ 다음 각 호의 어느 하나에 해당하는 사람은 6개월 이하의 징역 또는 500만원 이하의 벌금에 처한다. <신설 2017.12.12>', 3857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6854, '⑪ 제10항의 미수범은 처벌한다. <신설 2017.12.12>', 3857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6855, '⑫ 금지물품은 몰수한다. <신설 2017.12.12>', 3857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6856, '⑬ 치료감호기간의 만료로 피보호관찰자가 된 사람이 정당한 사유 없이 제33조제1항부터 제3항까지의 준수사항을 위반하여 같은 조 제5항에 따른 경고를 받은 후 다시 정당한 사유 없이 제33조제1항부터 제3항까지의 준수사항을 위반한 경우 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <신설 2017.12.12>', 3857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6857, null, 3859);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6858, '① 검사가 공소를 제기하면서 동시에 치료감호 청구를 하는 경우 치료감호청구서에 적어야 할 법 제4조제4항제1호의 사항은 공소장에 적힌 피고인의 성명, 연령, 등록기준지, 주거, 직업 등으로 갈음하고, 청구의 원인이 되는 사실 및 적용법조는 공소장의 공소사실 및 적용법조에 추가하여 적는다.', 3861);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6859, '② 검사가 공소를 제기하지 아니하고 치료감호 청구만을 하거나 공소를 제기한 후에 치료감호 청구를 하는 경우에는 치료감호청구서에 치료감호가 청구된 치료감호대상자(이하 "피치료감호청구인"이라 한다)의 성명, 연령, 등록기준지, 주거, 직업, 죄명과 청구의 원인이 되는 사실 및 적용법조를 적는다. <개정 2018.6.12>', 3861);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6860, '③ 제1항 및 제2항의 경우에는 구속영장 또는 치료감호영장이나 그 등본, 변호인 선임서, 피의자 또는 치료감호대상자 수용증명, 구속 또는 보호구속기간 연장결정서나 그 등본 등을 첨부한다.', 3861);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6861, '① 치료감호를 선고받은 자(이하 "피치료감호자"라 한다)에 대하여는 법 제16조제1항에 따른 치료감호시설(이하 "치료감호시설"이라 한다)에 수용ㆍ감호하고 치료와 재활교육을 한다. <개정 2014.1.28>', 3862);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6862, '② 피치료감호자에 대하여는 심신장애의 정도 또는 제2조에 규정된 물질이나 알코올을 식음(食飮)하는 등의 습벽(習癖) 및 중독된 정도, 정신성적(精神性的) 장애의 정도에 따라 분리수용한다.', 3862);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6863, '① 치료감호시설의 장은 법 제16조제3항에 따라 피치료감호자의 치료감호 기간 연장을 검사에게 신청하려면 다음 각 호의 사항을 적은 서면에 그 신청사유를 소명(疎明)할 수 있는 자료를 첨부하여 제출하여야 한다.', 3863);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6864, '② 제1항에 따른 치료감호 기간 연장 신청은 법 제16조제2항 각 호의 기간 또는 같은 조 제3항에 따라 연장된 기간이 종료하기 7개월 전까지 하여야 한다.', 3863);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6865, '① 법무부장관은 법 제16조의2제1항제2호에 따른 지정법무병원(이하 "지정법무병원"이라 한다)을 지정하기 위하여 필요한 경우 보건복지부장관의 의견을 들을 수 있다.', 3864);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6866, '② 법무부장관은 지정법무병원을 지정한 경우에는 보건복지부장관 및 지정법무병원의 장에게 그 사실을 통보하여야 한다.', 3864);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6867, '① 지정법무병원의 장은 피치료감호자가 입원하면 지정법무병원의 정신건강의학과 의사 중 피치료감호자의 치료를 담당할 의사를 지정하여야 한다.', 3865);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6868, '② 지정법무병원의 피치료감호자 수용정원은 50명 이내로 한다. 다만, 법무부장관은 치료감호시설 전체 수용인원 및 치료의 적절성을 고려하여 수용정원을 조정할 수 있다.', 3865);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6869, '③ 제1항 및 제2항에서 규정한 사항 외에 피치료감호자의 수용 및 치료에 필요한 세부 사항은 법무부장관이 정한다.', 3865);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6870, '① 법 제16조의2제3항에 따라 국가는 예산의 범위에서 다음 각 호의 경비를 지정법무병원에 보조하여야 한다.', 3866);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6871, '② 지정법무병원의 장은 제1항에 따른 경비보조를 받으려면 경비보조 청구서에 다음 각 호의 서류를 첨부하여 매달 10일까지 법무부장관에게 제출하여야 한다.', 3866);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6872, '① 치료감호시설의 장은 피치료감호자에 대하여 치료감호 집행을 시작한 후 6개월마다 피치료감호자의 동태ㆍ치료정도와 그 밖에 필요한 사항을 법 제37조에 따른 치료감호심의위원회(이하 "위원회"라 한다)에 보고하여야 한다. <개정 2014.1.28>', 3867);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6873, '② 지정법무병원의 장은 피치료감호자가 다음 각 호의 어느 하나에 해당하면 지체 없이 위원회에 보고하여야 한다. <신설 2014.1.28>', 3867);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6874, '③ 치료감호시설의 장은 치료감호를 종료 또는 가종료(假終了)하거나 치료를 위탁하는 것이 타당하다고 인정하는 경우에는 검사에게 제1항의 사항을 통보하여 위원회에 심사를 신청하도록 요청할 수 있다. <개정 2014.1.28>', 3867);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6875, '① 판사와 검사는 치료감호시설을 수시로 시찰할 수 있다. <개정 2014.1.28>', 3868);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6876, '② 판사나 검사가 아닌 사람이 법 제20조에 따라 치료감호시설을 참관하려면 치료감호시설의 장의 허가를 받아야 한다. <개정 2014.1.28>', 3868);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6877, '③ 치료감호시설의 장은 치료감호시설을 참관하려는 사람에 대하여 그 성명ㆍ직업ㆍ주소 및 참관의 목적을 명백히 한 후 정당한 이유가 있을 때에는 참관을 허가하여야 한다. <개정 2014.1.28>', 3868);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6878, '④ 치료감호시설의 장은 외국인이 치료감호시설을 참관하려는 경우에는 법무부장관의 승인을 받아 참관을 허가하여야 한다. <개정 2014.1.28>', 3868);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6879, '⑤ 치료감호시설의 장은 참관을 허가받은 사람에게 참관할 때의 주의사항을 고지하여야 한다. <개정 2014.1.28>', 3868);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6880, '① 지정법무병원의 장은 법 제21조의2제2항의 사유가 있는 경우에는 위원회에 피치료감호자의 재이송을 신청할 수 있다.', 3869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6881, '② 지정법무병원의 장은 제1항에 따른 재이송 신청을 할 때에는 증상 악화에 대한 담당 의사의 의견서 등 지정법무병원에서 계속 치료하기 곤란한 사유를 확인할 수 있는 관련 자료를 첨부하여야 한다.', 3869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6882, '③ 위원회는 제1항에 따른 재이송 신청을 받으면 피치료감호자에 대한 재이송이 적절한지를 심사하여 결정하여야 한다.', 3869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6883, '① 치료감호시설의 장은 법 제25조의2제3항에 따라 다음 각 호의 사항을 고려하여 피치료감호청구인의 생활실을 구분하는 등 피치료감호청구인에게 적합한 처우를 하여야 한다.', 3871);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6884, '② 치료감호시설의 장은 피치료감호청구인의 처우를 위하여 필요한 경우 피치료감호청구인을 대상으로 상담 등을 통한 신상에 관한 개별사안의 조사, 심리ㆍ지능ㆍ적성 검사, 그 밖에 필요한 검사를 할 수 있다.', 3871);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6885, '① 치료감호시설의 장은 법 제25조의3제1항에 따라 피치료감호자 및 피치료감호청구인(이하 "피치료감호자등"이라 한다)에게 격리 또는 묶는 등의 신체적 제한(이하 "보호조치"라 한다)을 하려면 다음 각 호의 어느 하나에 해당하는 방법으로 하여야 한다. 이 경우 제2호의 보호조치는 법 제25조의3제1항제1호의 경우에만 할 수 있다.', 3872);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6886, '② 제1항제1호에 따른 보호조치의 기간은 15일 이내로 한다. 다만, 치료감호시설의 장은 다음 각 호의 구분에 따른 의사의 지시에 따라 특히 계속하여 보호조치를 할 필요가 있으면 이를 연장할 수 있다. <개정 2021.4.6>', 3872);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6887, '③ 제2항 단서에 따른 보호조치 기간 연장은 1회에 7일 이내로 하되, 보호조치 기간은 계속하여 30일을 초과할 수 없다.', 3872);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6888, '④ 제1항제2호에 따른 보호조치의 기간은 24시간 이내로 한다. 다만, 치료감호시설의 장은 정신건강의학과 전문의의 지시에 따라 특히 계속하여 보호조치를 할 필요가 있으면 이를 24시간 이내에서 한 차례만 연장할 수 있다. <개정 2021.4.6>', 3872);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6889, '⑤ 치료감호시설의 장은 피치료감호자등에게 보호조치를 하는 경우 법 제25조의3제4항에 따라 피치료감호자등 보호원부에 다음 각 호의 사항을 작성ㆍ보존해야 한다. <개정 2021.4.6>', 3872);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6890, '⑥ 피치료감호자등 보호원부의 서식에 관한 사항은 법무부령으로 정한다.', 3872);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6891, '① 피치료감호자등이나 법정대리인등이 법 제30조제1항에 따라 피치료감호자등의 처우개선에 관하여 청원할 경우에는 법무부장관에게 문서로 하여야 한다. <개정 2018.6.12>', 3873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6892, '② 제1항에 따라 청원하려는 사람은 청원서를 작성하여 봉한 후 치료감호시설의 장에게 제출하여야 한다. <개정 2014.1.28>', 3873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6893, '③ 치료감호시설의 장은 청원서를 개봉하여서는 아니 되며, 지체 없이  법무부장관에게 송부하여야 한다. <개정 2014.1.28>', 3873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6894, '④ 치료감호시설의 장은 피치료감호자등 또는 법정대리인등이 청원을 하지 못하게 하거나 청원을 하였다는 이유로 피치료감호자등에게 불이익을 주어서는 아니 된다. <개정 2014.1.28, 2018.6.12>', 3873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6895, '⑤ 법무부장관은 청원의 처리 결과를 치료감호시설의 장에게 문서로 통보하고, 치료감호시설의 장은 지체 없이 청원인에게 전달하여야 한다. <개정 2014.1.28>', 3873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6896, '① 「보호관찰 등에 관한 법률」에 따른 보호관찰(이하 "보호관찰"이라 한다)을 받기 시작한 자(이하 "피보호관찰자"라 한다)에 대한 법 제33조제2항에 따른 준수사항의 부과는 위원회가 하되, 피보호관찰자마다 개인의 성향 등을 고려하여 서면으로 지시한다. <개정 2018.6.12>', 3874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6897, '② 보호관찰관은 위원회가 피보호관찰자에게 부과한 준수사항의 이행을 독려(督勵)하기 위하여 필요한 범위에서 구체적인 지시를 할 수 있다.', 3874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6898, '③ 보호관찰관은 피보호관찰자를 지도ㆍ감독하기 위하여 특별히 필요한 경우에는 피보호관찰자를 출석하게 하여 사실을 확인하거나 관계자에게 필요한 협조를 요청할 수 있다.', 3874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6899, '① 위원회는 법 제33조제3항에 따라 피보호관찰자의 준수사항 전부 또는 일부의 추가ㆍ변경 또는 삭제에 관한 심사와 결정을 한 경우 그 내용을 피보호관찰자에게 문서로 알려야 한다.', 3875);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6900, '② 보호관찰소의 장이 법 제33조제3항에 따라 피보호관찰자의 준수사항 전부 또는 일부의 추가ㆍ변경 또는 삭제를 위원회에 신청하려면 다음 각 호의 사항을 적은 문서로 하여야 한다.', 3875);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6901, '③ 위원회는 제1항에 따른 심사를 위하여 필요하다고 인정하는 경우에는 해당 피보호관찰자를 담당하는 보호관찰관을 출석시켜 의견을 들을 수 있으며, 피보호관찰자를 심문하거나 필요한 사항을 조사ㆍ심리할 수 있다.', 3875);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6902, '① 피보호관찰자는 2개월마다 다음 각 호의 사항을 보호관찰관에게 서면으로 신고해야 한다. <개정 2021.1.5>', 3877);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6903, '② 피보호관찰자는 주거를 이전하거나 30일 이상 여행하려는 경우에는 미리 그 내용을 보호관찰관에게 서면으로 신고하여야 한다.', 3877);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6904, '③ 피보호관찰자가 제1항 및 제2항에 따른 신고를 스스로 할 수 없는 경우에는 그 보호자(보호시설의 경우는 그 시설의 장을 말한다. 이하 같다) 또는 치료를 위탁받은 법정대리인등이 신고하여야 한다.', 3877);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6905, '① 보호관찰관은 피보호관찰자의 동태를 관찰하고 건전한 사회인으로 복귀할 수 있도록 지도ㆍ감독하여야 한다.', 3878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6906, '② 보호관찰관은 보호관찰부를 작성하여 갖춰 두고, 매월 1회 이상 피보호관찰자의 주요 동태 및 제9조에 따른 준수사항의 이행 여부를 확인하여야 한다.', 3878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6907, '③ 보호관찰관은 6개월마다 제2항에 규정한 사항을 검사를 거쳐 위원회에 보고하여야 한다.', 3878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6908, '④ 보호관찰관은 피보호관찰자에게 다음 각 호의 어느 하나에 해당하는 사유가 있는 경우에는 지체 없이 검사를 거쳐 위원회에 보고하여야 한다.', 3878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6909, '⑤ 제4항제7호의 경우 보호관찰관은 검사에게 법 제43조에 따라 치료감호의 종료에 관한 심사신청을 할 것을 요청할 수 있다.', 3878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6910, '⑥ 보호관찰관은 제10조제2항에 따른 신고를 받은 경우에는 지체 없이 그 내용을 새 주거지 또는 여행지의 보호관찰관에게 통보하여야 한다. 이 경우 피보호관찰자가 주거를 이전한 때에는 지체 없이 피보호관찰자에 대한 보호관찰부와 그 밖의 관계 서류를 새 주거지 관할 보호관찰관에게 송부하여야 한다. <개정 2016.11.29>', 3878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6911, '⑦ 제6항 후단에 따라 관계 서류를 받은 새 주거지의 보호관찰관은 그 주거 이전의 사실을 확인한 후 지체 없이 검사를 거쳐 위원회에 보고하여야 한다.', 3878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6912, '① 보호관찰소의 장은 법 제33조의2제3항에 따라 피보호관찰자의 유치허가 신청을 하는 경우에는 다음 각 호의 사항을 적은 문서로 하여야 한다.', 3879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6913, '② 법 제33조의2제3항에 따라 판사가 발부하는 유치허가장에는 청구한 검사의 관직ㆍ성명ㆍ발부일시 및 제1항 각 호의 사항을 적어야 한다.', 3879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6914, '① 보호관찰소의 장은 법 제33조의2제4항에 따라 법 제22조에 따른 가종료 또는 법 제23조에 따른 치료의 위탁(이하 "가종료등"이라 한다)의 취소 신청을 요청하는 경우에는 다음 각 호의 사항을 적은 문서로 하여야 한다. 이 경우 법 제33조의2제4항에 따른 가종료등의 취소신청기간은 보호관찰소의 장이 유치허가장을 받은 때부터 기산한다.', 3881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6915, '② 검사는 법 제33조의2제4항에 따른 보호관찰소장의 가종료등의 취소 신청 요청을 기각한 경우에는 지체 없이 보호관찰소의 장에게 그 사실을 알려야 한다.', 3881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6916, '③ 검사는 법 제33조의2제5항에 따라 위원회에 가종료등의 취소 신청을 하는 경우에는 보호관찰소의 장이 제1항에 따라 제출한 문서를 첨부하고, 그 사유를 소명하여야 한다.', 3881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6917, '④ 위원회는 법 제33조의2제5항에 따른 가종료등의 취소 신청을 심리하기 위하여 필요하다고 인정하는 경우에는 치료감호시설의 장이나 보호관찰소의 장을 출석시켜 의견을 들을 수 있다.', 3881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6918, '① 피보호관찰자가 법 제34조제1항에 따른 출소 전 신고를 할 때에는 다음 각 호의 사항을 적은 신고서를 치료감호시설의 장에게 제출하여야 한다. <개정 2014.1.28>', 3884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6919, '② 제1항에 따른 신고서를 받은 치료감호시설의 장은 제1항 각 호의 사항과 다음 각 호의 사항을 적은 출소통보서를 작성하여 1부는 위원회에, 1부는 출소 후 거주 예정지 관할 보호관찰관에게 송부하고, 1부는 치료감호시설에 갖춰 두어야 한다. <개정 2014.1.28>', 3884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6920, '③ 법 제34조제2항에 따른 출소 후 신고를 할 때에는 다음 각 호의 사항을 적은 신고서를 보호관찰관에게 제출하여야 한다. <개정 2014.1.28, 2017.5.29>', 3884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6921, '④ 피보호관찰자는 제3항에 따른 신고사항이 변동된 경우에는 지체 없이 보호관찰관에게 신고하여야 한다.', 3884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6922, '⑤ 피보호관찰자가 제1항ㆍ제3항 및 제4항에 따른 신고를 스스로 할 수 없는 경우에는 그 보호자 또는 치료의 위탁을 받은 법정대리인등이 신고하여야 한다.', 3884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6923, '⑥ 제2항에 따른 통보를 받은 관할 보호관찰관은 피보호관찰자가 법 제34조제2항에 따른 출소 후 신고를 하지 아니한 경우에는 지체 없이 그 사실을 검사를 거쳐 위원회에 보고하여야 한다.', 3884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6924, '① 법 제36조의4제2항에 따라 보호관찰소의 장이 정신건강복지센터의 장에게 요청할 수 있는 정신보건 관련 정보는 다음 각 호와 같다. <개정 2017.5.29>', 3885);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6925, '② 법 제36조의4제3항에 따라 정신건강복지센터의 장이 보호관찰소의 장에게 협조를 요청할 수 있는 사항은 다음 각 호와 같다. <개정 2017.5.29>', 3885);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6926, '① 위원회의 위원은 위원장의 제청으로 법무부장관이 임명하거나 위촉한다.', 3886);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6927, '② 공무원이 아닌 위원의 임기는 3년으로 한다.', 3886);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6928, '③ 위원장은 위원회를 대표하고 위원회의 업무를 총괄하며, 위원회의 회의를 소집하고 그 의장이 된다.', 3886);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6929, '④ 위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 위원장이 미리 지명한 위원이 그 직무를 대행한다.', 3886);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6930, '⑤ 법 제37조제4항에 따른 자문위원은 10명 이내로 하며, 자문위원은 위원회의 심사ㆍ결정에 필요한 자문에 응한다.', 3886);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6931, '① 위원회에 간사 2명과 서기 약간명을 둔다.', 3887);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6932, '② 간사와 서기는 법무부 소속 공무원 중에서 위원장이 임명한다.', 3887);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6933, '③ 간사는 위원장의 명을 받아 위원회의 사무를 처리하고 회의에 참석하여 발언할 수 있으며, 서기는 간사를 보조한다.', 3887);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6934, '① 검사가 법 제43조에 따라 위원회에 피치료감호자의 심사를 신청할 때에는 신청서에 피치료감호자의 성명ㆍ연령ㆍ주거ㆍ직업 등을 적고, 다음 각 호의 자료를 첨부하여야 한다. <개정 2014.1.28>', 3889);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6935, '② 제1항의 경우 검사는 치료감호사안과 관련된 사건기록을 보존하고 있는 검찰청으로부터 송부받아 이를 심사신청서와 함께 위원회에 송부할 수 있다.', 3889);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6936, '① 피치료감호자와 그 법정대리인등은 법 제44조에 따라 위원회에 치료감호의 종료 여부에 대한 심사를 신청할 때에는 정신건강의학과 등의 전문의의 진단서 또는 감정서를 첨부하여야 한다. <개정 2011.11.23, 2018.6.12>', 3890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6937, '② 치료감호시설의 장은 피치료감호자와 그 법정대리인등의 심사신청에 대하여 위원회에 의견을 제출할 수 있다. <개정 2014.1.28, 2018.6.12>', 3890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6938, null, 3891);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6939, '① 위원회는 치료감호사안에 관하여 결정을 한 때에는 결정서 등본을 피치료감호자를 감호 또는 보호관찰하는 치료감호시설의 장이나 보호관찰관에게 송달한다. 다만, 검사의 신청을 받아 결정을 한 경우에는 결정서 등본을 심사를 신청한 검사에게 송달하여야 하며, 그 송달을 받은 검사는 이를 치료감호시설의 장이나 보호관찰관에게 통보한다. <개정 2014.1.28>', 3893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6940, '② 제1항에 따라 송달 또는 통보를 받은 치료감호시설의 장이나 보호관찰관은 그 내용을 피치료감호자에게 고지하여야 한다. <개정 2014.1.28>', 3893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6941, '③ 위원회는 법 제44조에 따른 피치료감호자와 그 법정대리인등의 신청에 대하여 결정을 한 때에는 그 결정서 등본을 피치료감호자와 그 법정대리인등에게 송달하여야 한다. <개정 2018.6.12>', 3893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6942, '① 위원회는 회의록을 작성ㆍ비치하여야 한다.', 3894);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6943, '② 회의록에는 회의와 관련된 모든 사항을 적고 위원장이 기명ㆍ날인하여야 한다.', 3894);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6944, '① 위원회의 위원장ㆍ위원ㆍ자문위원 및 직원에 대하여는 예산의 범위에서 출석수당과 여비를 지급할 수 있다. 다만, 공무원인 위원이 그 소관 업무와 직접적으로 관련되어 위원회에 출석하는 경우에는 그러하지 아니하다.', 3895);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6945, '② 제1항의 수당 및 여비의 금액과 지급방법 및 그 밖에 필요한 사항은 법무부령으로 정한다.', 3895);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6946, '① 보호관찰관은 법 제44조의6제1항에 따라 치료명령을 집행하기 전에 제26조에 따른 지휘 서면 및 판결문 등본을 모두 확인하여야 한다.', 3900);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6947, '② 보호관찰관은 법 제44조의6제1항에 따라 치료명령을 집행하기 전에 피치료명령자에게 다음 각 호의 사항을 알려 주어야 한다.', 3900);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6948, null, 3901);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6949, '① 법 제44조의6제2항에 따른 인지행동 치료 등 심리치료 프로그램에는 다음 각 호의 내용이 포함되어야 한다.', 3902);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6950, '② 법무부장관은 제1항에 따른 심리치료 프로그램의 개발에 노력하여야 한다.', 3902);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6951, '① 법 제44조의6제1항에 따라 치료명령을 집행하는 보호관찰관은 피치료명령자와의 면담이나 법 제44조의7에 따른 치료기관 방문 등을 통하여 피치료명령자에 대한 치료명령 집행 상황을 확인하여야 한다.', 3903);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6952, '② 법무부장관은 치료명령 집행업무를 전문적으로 수행할 수 있는 인력의 양성을 위하여 노력하여야 한다.', 3903);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6953, null, 3904);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6954, '① 국가는 법 제44조의9제1항 단서에 따라 피치료명령자가 다음 각 호의 어느 하나에 해당하는 경우에는 치료비용을 부담할 수 있다.', 3905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6955, '② 피치료명령자는 제1항에 따른 치료비용의 국가부담을 신청하려는 경우에는 법무부령으로 정하는 신청서에 다음 각 호의 서류를 첨부하여 보호관찰소의 장에게 제출하여야 한다. 다만, 「국민기초생활 보장법」 제2조제2호에 따른 수급자인 피치료명령자는 신청서만 제출한다.', 3905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6956, '③ 보호관찰소의 장은 제2항에 따라 신청서를 제출받았을 때에는 신청인의 동의를 받아 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 다음 각 호의 행정정보를 확인하여야 한다. 다만, 신청인이 확인에 동의하지 아니하는 경우에는 그 서류를 첨부하게 하여야 한다. <개정 2018.6.12>', 3905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6957, '④ 보호관찰소의 장은 필요한 경우에는 신청인을 출석하게 하거나 신청인에게 필요한 자료를 제출하도록 요청할 수 있다.', 3905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6958, '⑤ 보호관찰소의 장은 국가, 지방자치단체 및 「공공기관의 운영에 관한 법률」 제4조에 따른 공공기관에 신청인의 치료비용 부담 능력을 확인하는 데 필요한 자료의 제출을 요청할 수 있다. 이 경우 법무부령으로 정하는 신청인의 동의서를 첨부하여야 한다.', 3905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6959, '⑥ 보호관찰소의 장은 제2항부터 제5항까지의 자료를 심사하여 신청인에 대한 치료비용의 국가부담을 결정한다.', 3905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6960, '⑦ 보호관찰소의 장은 제6항에 따라 치료비용을 국가가 부담하도록 결정한 경우에는 치료행위마다 예산의 범위에서 치료비용 전부를 지급해야 한다. 다만, 「국민건강보험법」, 「의료급여법」이나 그 밖의 다른 법령에서 신청인 또는 그 보호의무자(「정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률」 제39조에 따른 보호의무자를 말한다)가 부담하지 않도록 규정한 치료비용은 국가가 지급하는 비용에서 제외한다. <개정 2021.4.6>', 3905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6961, '⑧ 제1항부터 제7항까지에서 규정한 사항 외에 국가가 부담하는 치료비용의 구체적인 지급절차는 법무부장관이 정한다.', 3905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6962, '① 치료감호시설의 장은 법 제50조의2제1항에 따라 기부금품을 접수하는 경우 기부자에게 영수증을 발급하여야 한다. 다만, 익명으로 기부하거나 기부자를 알 수 없는 경우에는 영수증을 발급하지 아니할 수 있다.', 3907);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6963, '② 치료감호시설의 장은 제1항에 따른 기부자가 다음 각 호의 어느 하나의 경우에 해당하는 사실을 알게 된 경우에는 기부금품을 접수해서는 아니 된다.', 3907);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6964, '③ 치료감호시설의 장은 제1항에 따른 기부자가 기부금품의 용도를 지정한 경우에는 그 용도로만 사용하여야 한다. 다만, 기부자가 지정한 용도로 사용하기 어려운 경우에는 특별한 사정이 없는 한 기부자의 동의를 받아 다른 용도로 사용할 수 있다.', 3907);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6965, '④ 치료감호시설의 장은 모든 기부금의 수입 및 지출을 기부금 전용계좌를 통하여 처리하여야 한다.', 3907);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6966, '⑤ 치료감호시설의 장은 기부금품의 접수현황 및 사용실적 등에 관한 장부를 갖추어 두고 기부자가 열람할 수 있도록 하여야 한다.', 3907);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6967, '⑥ 치료감호시설의 장은 매 반기별로 기부금품의 접수현황 및 사용실적 등에 관한 사항을 법무부장관에게 보고하여야 한다.', 3907);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6968, '① 검사는 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법 시행령」 제18조제2호에 따른 범죄경력자료에 해당하는 정보, 같은 영 제19조제1호 또는 제4호에 따른 주민등록번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2014.1.28, 2016.11.29>', 3908);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6969, '② 위원회는 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다.', 3908);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6970, '③ 치료감호시설의 장은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보, 같은 영 제19조제1호 또는 제4호에 따른 주민등록번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2014.1.28, 2014.6.30, 2018.6.12>', 3908);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6971, '④ 보호관찰소의 장은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제3항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <신설 2014.1.28, 2016.11.29, 2017.5.29>', 3908);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6972, '⑤ 보호관찰관은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제3항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <개정 2014.1.28, 2016.11.29>', 3908);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6973, '⑥ 치료감호시설의 장 또는 보호관찰관은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <개정 2014.1.28>', 3908);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6974, '⑦ 정신건강복지센터의 장은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제3항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <신설 2014.1.28, 2016.11.29, 2017.5.29, 2018.6.12>', 3908);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6975, '⑧ 법무부장관은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <신설 2014.8.6, 2016.11.29>', 3908);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6976, '① 「치료감호 등에 관한 법률」(이하 "법"이라 한다) 제4조에 따른 치료감호청구서는 별지 제1호서식과 같다. 다만, 공소를 제기하면서 동시에 치료감호를 청구할 때에는 별지 제2호서식의 공소장 및 치료감호청구서로 하여야 한다. <개정 2014.1.29, 2016.12.2>', 3911);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6977, '② 공소를 제기한 후에 치료감호청구를 할 때에는 치료감호사건과 병합심리할 피고사건이나 약식명령 청구사건이 계속(繫屬)되어 있는 법원명, 사건번호, 피고인 성명, 죄명 등을 분명하게 적어 병합심리를 신청하여야 한다.', 3911);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6978, '③ 공소를 제기하지 아니하고 치료감호청구만을 할 때에는 치료감호사건과 동시에 심리할 수 있었던 피의사건의 사건번호를 적는다.', 3911);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6979, '④ 제1항 본문에 따른 치료감호청구서와 같은 항 단서에 따른 공소장 및 치료감호청구서에는 다음 각 호의 서류를 첨부하여야 한다. <개정 2024.5.21>', 3911);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6980, '① 검사와 사법경찰관리는 법 제5조에 따라 치료감호대상자를 조사할 때 다음 각 호의 사항에 유의하여야 한다. <개정 2016.12.2>', 3912);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6981, '② 제1항제1호의 전과 및 치료감호경력을 조사할 때에는 형 및 치료감호의 판결법원, 판결 연월일, 죄명, 형명(刑名), 형기(刑期)와 치료감호기간, 형 집행사항과 치료감호의 집행사항을 명백히 조사하여야 한다.', 3912);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6982, '① 사법경찰관이 치료감호에 처(處)함이 상당하다고 인정되는 사건(이하 "치료감호대상사건"이라 한다)을 검찰청에 송치할 때에는 의견서에 적용법조와 치료감호를 청구함이 상당하다고 인정되는 이유 및 의견을 덧붙여 적어야 한다. 이 경우 법 제2조제1항제3호에 따른 치료감호대상자에 대하여는 검찰청에 송치하기 전에 정신과 등의 전문의의 진단이나 감정을 받아야 한다.', 3914);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6983, '② 제1항의 경우 사건송치서의 의견란에 괄호를 하고, 붉은색으로 "치료감호"라고 적어야 한다.', 3914);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6984, '③ 제1항의 송치서류에는 범죄경력 자료 등 치료감호의 요건이 되는 사실을 증명하는 서류를 첨부하여야 한다.', 3914);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6985, '④ 치료감호대상사건을 송치할 때에 제3항에 따른 서류를 첨부하지 못한 경우에는 사건송치서의 비고란에 그 사유를 적고, 사건을 송치한 후에 새로운 치료감호의 요건이 되는 사실이 발견된 경우에는 즉시 그 사실을 검사에게 보고하여야 한다.', 3914);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6986, '① 지방검찰청 검사장 또는 지청장은 치료감호대상자에 대하여 치료감호청구를 한 때에는 지체 없이 법무부장관과 상급 검찰청의 장에게 그 사실을 보고하여야 한다.', 3916);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6987, '② 제1항의 치료감호청구사건에 대하여 재판이 확정된 때에는 그 법원에 대응하는 검찰청의 장은 지체 없이 법무부장관과 상급 검찰청의 장에게 그 사실을 보고하여야 한다.', 3916);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6988, '① 법 제16조제3항에 따른 치료감호 기간의 연장 신청은 별지 제5호의2서식에 따른다.', 3918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6989, '② 법 제16조제3항에 따른 치료감호 기간의 연장 청구는 별지 제5호의3서식에 따른다.', 3918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6990, '③ 법원이 법 제16조제3항에 따라 치료감호 기간의 연장을 결정한 경우 검사의 집행 지휘는 별지 제5호의4서식에 따른다. 다만, 법원이 검사의 청구를 기각한 경우에는 검사는 그 결정문 사본을 치료감호시설의 장에게 송부하여야 한다.', 3918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6991, '① 법 제17조에 따른 치료감호의 집행 지휘는 별지 제6호서식의 치료감호집행지휘서로 하여야 한다.', 3920);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6992, '② 법 제21조제2항에 따른 치료감호집행장은 별지 제7호서식과 같다.', 3920);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6993, '① 치료감호와 형이 병과(倂科)된 경우에는 먼저 치료감호의 집행을 지휘하고, 그 치료감호 집행지휘서의 비고란에 병과된 형의 내용을 붉은색으로 적어야 한다.', 3921);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6994, '② 치료감호시설의 장은 형이 병과된 치료감호를 선고받은 자(이하 "피치료감호자"라 한다)에 대하여 치료감호의 종료가 결정되었으나 남은 형기가 있을 때에는 즉시 치료감호의 집행을 지휘한 지방검찰청 또는 지청의 검사에게 치료감호의 종료와 남은 형기 등 형의 집행 지휘에 필요한 사항을 통보하여야 한다. <개정 2014.1.29>', 3921);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6995, '③ 법 제37조에 따른 치료감호심의위원회가 치료감호의 가종료에 관련된 사항으로서 피치료감호자에 대한 치료감호의 집행을 정지하고 치료감호와 병과된 형 외의 자유형 또는 노역장유치(이하 이 조에서 "자유형등"이라 한다)를 먼저 집행할 필요가 있다고 심사ㆍ결정한 경우 치료감호시설의 장은 치료감호시설 소재지를 관할하는 지방검찰청 또는 지청의 검사에게 해당 피치료감호자에 대한 치료감호의 집행을 정지하고 먼저 자유형등의 집행을 지휘해줄 것을 요청할 수 있다. <신설 2023.5.4>', 3921);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6996, '④ 제3항에 따른 요청을 받은 검사는 소속 검찰청의 장의 허가를 받아 해당 피치료감호자에 대한 치료감호의 집행을 정지하고 먼저 자유형등의 집행을 지휘할 수 있다. <신설 2023.5.4>', 3921);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6997, '⑤ 제3항에 따른 요청은 별지 제6호의2서식에 따르고, 제4항에 따른 지휘는 별지 제6호의3서식에 따른다. <신설 2023.5.4>', 3921);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6998, '① 영 제5조제1항에 따른 치료감호시설의 장의 보고는 별지 제8호서식에 따른다.', 3922);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (6999, '② 영 제5조제2항에 따른 지정법무병원의 장의 보고는 별지 제8호의2서식에 따른다.', 3922);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7000, '① 법 제23조제3항에 따라 치료를 위탁받은 피치료감호자의 법정대리인, 배우자, 직계존속, 형제자매(이하 "법정대리인등"이라 한다)가 제출할 서약서에는 치료받을 병원의 장이 확인한 입원보증서, 법정대리인등과 피치료감호자와의 관계 및 입원치료의 능력을 소명하는 자료를 첨부하여야 한다.', 3924);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7001, '② 제1항의 서약서는 별지 제9호서식과 같다.', 3924);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7002, '① 보호관찰관이 영 제9조제2항에 따라 보호관찰을 받기 시작한 자(이하 "피보호관찰자"라 한다)에게 구체적인 지시를 할 때에는 별지 제11호서식의 지시서로 하여야 한다.', 3927);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7003, '② 보호관찰관이 제1항에 따른 지시를 한 때에는 그 내용을 지체 없이 검사를 거쳐 법 제37조에 따른 치료감호심의위원회(이하 "위원회"라 한다)에 보고하여야 한다.', 3927);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7004, '① 보호관찰관은 영 제9조제3항에 따라 피보호관찰자를 출석하게 하여 법 제33조에 따른 준수사항이나 그 밖에 지도ㆍ감독상 필요한 사실을 확인하는 경우 필요하다고 인정될 때에는 별지 제12호서식의 진술서를 작성하거나 피보호관찰자로 하여금 자필로 이를 작성ㆍ제출하게 할 수 있다.', 3928);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7005, '② 제1항에 따른 진술서에는 피보호관찰자가 서명하고 도장 또는 지장을 찍어야 한다. 피보호관찰자가 서명할 수 없을 때에는 보호관찰관이 대신하여 이름을 적되, 그 사유를 적고 피보호관찰자의 도장 또는 지장을 받아야 한다.', 3928);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7006, '③ 영 제9조제3항에 따라 보호관찰관이 피보호관찰자를 지도ㆍ감독하기 위하여 관계자로부터 필요한 사실을 확인하는 경우 그 진술서 작성에 관하여는 제1항과 제2항을 준용한다. 이 경우 관계자가 진술 등을 거부할 때에는 그 사유를 적어야 한다.', 3928);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7007, '① 보호관찰관은 별지 제14호서식의 신고접수부를 갖추어 영 제10조, 법 제34조제1항ㆍ제2항 또는 영 제13조제4항ㆍ제5항에 따른 신고를 접수한 때에는 그 사실을 신고접수부에 적고, 신고인에게 별지 제15호서식의 신고확인증을 발급하여야 한다. <개정 2024.5.21>', 3932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7008, '② 영 제10조제1항제4호 또는 같은 조 제2항에 따른 신고는 별지 제16호서식의 피보호관찰자 주거이전ㆍ여행 신고서로 하여야 하며, 주거이전의 신고를 할 때에는 퇴거신고접수증 사본을 첨부하여야 한다.', 3932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7009, '① 영 제11조의2제1항에 따른 피보호관찰자의 유치허가 신청은 별지 제16호의2서식에 따른다.', 3933);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7010, '② 영 제11조의2제2항에 따른 유치허가장은 별지 제16호의3서식에 따른다.', 3933);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7011, '① 영 제11조의4제1항에 따른 가종료 또는 치료 위탁의 취소 신청 요청과 같은 조 제3항에 따른 가종료 또는 치료 위탁의 취소 신청은 별지 제16호의4서식에 따른다. <개정 2021.4.6>', 3934);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7012, '② 위원회는 제1항의 신청에 따라 또는 직권으로 가종료 또는 치료의 위탁을 취소하는 결정을 한 때에는 해당 피보호관찰자가 수용된 교도소ㆍ구치소 또는 치료감호시설의 장과 관할 보호관찰소의 장에게 별지 제16호의5서식에 따라 통보한다. <신설 2021.4.6>', 3934);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7013, '① 보호관찰관은 영 제13조제2항에 따른 출소통보서를 접수한 때에는 지체 없이 피보호관찰자마다 별지 제17호서식의 보호관찰부를 작성하여 갖춰 두어야 한다.', 3935);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7014, '② 제1항에 따른 보호관찰부에는 피보호관찰자의 주요 동태 및 준수사항의 이행 여부와 피보호관찰자가 신고한 사항을 적는다.', 3935);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7015, '① 영 제11조제6항에 따라 주거이전 또는 여행 사실을 새 주거지 또는 여행지의 보호관찰관에게 통보할 때에는 별지 제19호서식의 피보호관찰자 주거이전ㆍ여행 통보서에 관계 서류를 첨부하여야 한다. <개정 2016.12.2>', 3937);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7016, '② 영 제11조제6항에 따라 여행 사실을 통보받은 여행지 보호관찰관은 피보호관찰자가 관할구역에 머무르는 동안 그를 보호관찰하여야 하며, 1개월마다 정기적으로 별지 제19호서식의 피보호관찰자 주거이전ㆍ여행 통보서를 작성하여 주거지 관할 보호관찰관에게 송부하여야 하고, 피보호관찰자가 죄를 범하는 등 그의 신상에 중대한 변동이 발생한 경우에는 지체 없이 그 통보서를 작성하여 주거지 관할 보호관찰관에게 송부하여야 한다. <개정 2016.12.2>', 3937);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7017, '① 영 제13조제1항에 따른 신고서는 별지 제20호서식과 같다.', 3939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7018, '② 영 제13조제2항에 따른 출소통보서는 별지 제21호서식과 같다.', 3939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7019, '③ 영 제13조제3항에 따른 출소 후 신고서는 별지 제22호서식과 같다.', 3939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7020, '① 보호관찰관이 위원회로부터 가종료나 치료위탁의 취소결정서를 송달받은 때에는 지체 없이 그 내용을 치료감호시설의 장에게 통보하여야 한다. 이 경우 보호관찰관 및 치료감호시설의 장은 피보호관찰자에 대한 남은 기간의 치료감호를 집행하기 위하여 보호관찰관의 관할구역이나 치료감호시설 소재지를 관할하는 검사에게 보호구인(保護拘引)을 의뢰할 수 있다. <개정 2022.7.4>', 3940);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7021, '② 보호관찰관이 검사로부터 가종료나 치료위탁의 취소결정서를 통보받은 때에도 제1항과 같이 처리한다.', 3940);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7022, '① 법 제36조의3에 따른 외래진료(이하 "외래진료"라 한다)는 치료감호시설 출소자의 정신질환 치료를 위하여 출소일부터 10년의 범위에서 실시할 수 있다. 다만, 증상의 악화 등 외래진료가 계속 필요하다고 인정되는 경우에는 10년의 범위에서 한 차례만 그 기간을 연장할 수 있다. <개정 2022.7.4>', 3943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7023, '② 외래진료는 치료감호시설에서 정신건강의학과의사의 진료, 검사시설에 의한 검사, 처방 및 투약 등의 방법으로 실시한다. 다만, 치료의 편의를 위하여 필요한 경우에는 원격화상장비를 이용하여 진료할 수 있다.', 3943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7024, '③ 외래진료의 경우 치료감호시설 출소자의 증상이 악화되더라도 치료감호시설에 입소시켜 치료할 수 없다. <개정 2022.7.4>', 3943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7025, '④ 외래진료를 실시한 치료감호시설의 장은 별지 제22호의2서식의 치료감호시설 출소자 외래진료 접수대장을 작성하여 10년간 보존하여야 한다. <개정 2022.7.4>', 3943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7026, '① 외래진료에 필요한 비용은 법무부장관이 부담한다. 다만, 「국민건강보험법」, 「의료급여법」, 그 밖의 다른 법령에 따라 치료감호시설 출소자 또는 그 보호의무자가 부담하지 아니하는 비용은 제외한다. <개정 2022.7.4>', 3944);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7027, '② 법무부장관은 예산의 범위에서 외래진료를 실시한 지정법무병원에 제1항에 따른 외래진료비용을 지급하여야 한다.', 3944);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7028, '③ 제2항에 따라 외래진료비용을 지급받으려는 지정법무병원의 장은 별지 제22호의3서식의 외래진료비용 지급 청구서에 출소자별 진료비 계산서를 첨부하여 매달 10일까지 법무부장관에게 제출하여야 한다. <개정 2022.7.4>', 3944);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7029, '① 법 제36조의4제2항에 따른 보호관찰소의 장의 정신보건센터의 장에 대한 정보 요청은 별지 제22호의4서식에 따른다.', 3945);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7030, '② 법 제36조의4제3항에 따른 정신보건센터의 장의 보호관찰소의 장에 대한 협조 요청은 별지 제22호의5서식에 따른다.', 3945);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7031, '① 법 제43조제1항 및 영 제17조제1항에 따라 검사가 심사ㆍ결정을 신청할 때에는 별지 제23호서식으로 하여야 한다.', 3950);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7032, '② 법 제43조제2항에 따라 치료감호시설의 장이나 보호관찰관이 의견을 제출할 때에는 별지 제24호서식으로 하여야 한다.', 3950);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7033, '③ 법 제43조제3항에 따라 치료감호시설의 장이나 보호관찰소의 장이 검사에게 위원회에 심사ㆍ결정을 신청해 줄 것을 요청할 때에는 별지 제25호서식으로 하여야 한다. 다만, 보호관찰소의 장이 검사에게 가종료 또는 치료 위탁의 취소 신청을 요청할 때에는 별지 제16호의4서식에 따른다. <개정 2024.5.21>', 3950);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7034, '④ 법 제44조제2항에 따라 피치료감호자와 그 법정대리인등이 위원회에 치료감호의 종료 여부에 대한 심사를 신청할 때에는 별지 제26호서식으로 하여야 한다.', 3950);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7035, '⑤ 영 제18조제2항에 따라 치료감호시설의 장이 의견을 제출할 때에는 별지 제27호서식으로 하여야 한다. <개정 2014.1.29>', 3950);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7036, '① 위원회가 한 사람에게 2건 이상의 결정서를 동시에 송달할 때에는 1부의 송달서류만으로 할 수 있다. 검사가 치료감호시설의 장이나 보호관찰관에게 통보할 때에도 또한 같다. <개정 2014.1.29>', 3952);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7037, '② 위원회가 가종료 또는 치료위탁으로 출소하는 피보호관찰자에게 부과하는 준수사항은 치료감호시설의 장을 통하여 보호관찰관에게 송달할 수 있다. <개정 2014.1.29>', 3952);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7038, null, 3954);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7039, null, 3955);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7040, '① 검사가 위원회에 심사신청한 치료감호사안에 관한 조사기록은 그 소속 지방검찰청 또는 지청에서 보존하고, 그 외의 치료감호사안에 관한 조사기록은 위원회에서 보존한다.', 3957);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7041, '② 제1항에 따라 검찰청에 보존 중인 치료감호사안 조사기록은 피치료감호자가 이감된 경우에는 이감된 감호소의 소재지를 관할하는 지방검찰청 또는 지청에 송부하여야 한다.', 3957);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7042, '① 법무부장관은 다음 각 호의 시설ㆍ기관 또는 단체 중에서 법 제44조의7제1항에 따른 치료기관(이하 "치료기관"이라 한다)을 지정할 수 있다. 다만, 제2호 및 제3호의 기관을 치료기관으로 지정하려는 경우에는 해당 기관의 장과 협의를 하여야 한다. <개정 2021.4.6>', 3960);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7043, '② 법무부장관은 치료기관의 시설이나 치료 프로그램이 치료명령을 선고받은 사람의 치료와 상태 개선에 부적당하다고 판단하는 경우에는 치료기관의 지정을 취소할 수 있다. 다만, 치료기관이 다음 각 호의 어느 하나에 해당하는 경우에는 지정을 취소하여야 한다.', 3960);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7044, '③ 제1항 및 제2항에서 규정한 사항 외에 치료기관의 지정 및 지정 취소 등에 대한 세부 사항은 법무부장관이 정한다.', 3960);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7045, '① 보호관찰소의 장은 영 제32조제5항 전단에 따라 자료의 제출을 요청할 때에는 별지 제32호서식의 자료제출 요청서를 국가, 지방자치단체 및 「공공기관의 운영에 관한 법률」 제4조에 따른 공공기관에 보내야 한다.', 3962);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7046, '② 영 제32조제5항 후단에 따른 신청인의 동의서는 별지 제33호서식에 따른다.', 3962);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7047, '① 영 제34조제1항에 따른 기부금품의 접수 영수증은 「법인세법 시행규칙」 제82조제7항제3호의3의 별지 제63호의3서식에 따른다. <개정 2016.12.2>', 3963);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7048, '② 영 제34조제5항에 따른 기부금품의 접수현황 및 사용실적 등에 관한 장부는 별지 제34호서식에 따른다. <개정 2016.12.2>', 3963);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7049, null, 3966);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7050, '① 제2조의 죄에 대하여 고소 또는 고발을 한 자가 검사나 군검사로부터 공소를 제기하지 아니한다는 통지를 받은 경우에는 그 검사 소속의 고등검찰청이나 그 군검사 소속의 고등검찰부에 대응하는 고등법원에 그 당부(當否)에 관한 재정(裁定)을 신청할 수 있다. <개정 2016.1.6, 2021.9.24>', 3967);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7051, '② 제1항의 재정신청에 관하여는 「형사소송법」 또는 「군사법원법」의 해당 규정을 적용한다.', 3967);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7052, '① 모든 국민은 제1조의 목적을 달성하기 위하여 그 지위와 능력에 따라 협력하여야 한다.', 3969);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7053, '② 국가와 지방자치단체는 죄를 지은 사람의 건전한 사회 복귀를 위하여 보호선도 사업을 육성할 책임을 진다.', 3969);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7054, '③ 국가는 이 법의 집행과정에서 보호관찰을 받을 사람 등의 인권이 부당하게 침해되지 않도록 주의하여야 한다. <신설 2021.7.20>', 3969);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7055, '① 보호관찰을 받을 사람(이하 "보호관찰 대상자"라 한다)은 다음 각 호와 같다.', 3970);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7056, '② 사회봉사 또는 수강을 하여야 할 사람(이하 "사회봉사ㆍ수강명령 대상자"라 한다)은 다음 각 호와 같다.', 3970);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7057, '③ 갱생보호를 받을 사람(이하 "갱생보호 대상자"라 한다)은 형사처분 또는 보호처분을 받은 사람으로서 자립갱생을 위한 숙식 제공, 주거 지원, 창업 지원, 직업훈련 및 취업 지원 등 보호의 필요성이 인정되는 사람으로 한다. <개정 2014.5.20>', 3970);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7058, '① 보호관찰에 관한 사항을 심사ㆍ결정하기 위하여 법무부장관 소속으로 보호관찰 심사위원회(이하 "심사위원회"라 한다)를 둔다.', 3972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7059, '② 심사위원회는 고등검찰청 소재지 등 대통령령으로 정하는 지역에 설치한다.', 3972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7060, null, 3973);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7061, '① 심사위원회는 위원장을 포함하여 5명 이상 9명 이하의 위원으로 구성한다.', 3974);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7062, '② 심사위원회의 위원장은 고등검찰청 검사장 또는 고등검찰청 소속 검사 중에서 법무부장관이 임명한다.', 3974);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7063, '③ 심사위원회의 위원은 판사, 검사, 변호사, 보호관찰소장, 지방교정청장, 교도소장, 소년원장 및 보호관찰에 관한 지식과 경험이 풍부한 사람 중에서 법무부장관이 임명하거나 위촉한다.', 3974);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7064, '④ 심사위원회의 위원 중 3명 이내의 상임위원을 둔다.', 3974);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7065, null, 3976);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7066, '① 상임위원은 고위공무원단에 속하는 일반직공무원 또는 4급 공무원으로서 「국가공무원법」 제26조의5에 따른 임기제공무원으로 한다. <개정 2014.1.7>', 3977);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7067, '② 상임위원이 아닌 위원은 명예직으로 한다. 다만, 예산의 범위에서 법무부령으로 정하는 바에 따라 여비나 그 밖의 수당을 지급할 수 있다.', 3977);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7068, '① 심사위원회는 심사자료에 의하여 제6조 각 호의 사항을 심사한다.', 3978);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7069, '② 심사위원회는 심사에 필요하다고 인정하면 보호관찰 대상자와 그 밖의 관계인을 소환하여 심문하거나 상임위원 또는 보호관찰관에게 필요한 사항을 조사하게 할 수 있다.', 3978);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7070, '③ 심사위원회는 심사에 필요하다고 인정하면 국공립기관이나 그 밖의 단체에 사실을 알아보거나 관계 자료의 제출을 요청할 수 있다.', 3978);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7071, '① 심사위원회의 회의는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.', 3979);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7072, '② 제1항에도 불구하고 회의를 개최할 시간적 여유가 없는 등 부득이한 경우로서 대통령령으로 정하는 경우에는 서면으로 의결할 수 있다. 이 경우 재적위원 과반수의 찬성으로 의결한다. <개정 2021.7.20>', 3979);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7073, '③ 심사위원회의 회의는 비공개로 한다.', 3979);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7074, '④ 결정은 이유를 붙이고 심사한 위원이 서명 또는 기명날인한 문서로 한다.', 3979);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7075, '① 보호관찰, 사회봉사, 수강 및 갱생보호에 관한 사무를 관장하기 위하여 법무부장관 소속으로 보호관찰소를 둔다.', 3982);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7076, '② 보호관찰소의 사무 일부를 처리하게 하기 위하여 그 관할 구역에 보호관찰지소를 둘 수 있다.', 3982);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7077, null, 3983);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7078, '① 보호관찰소에는 제15조 각 호의 사무를 처리하기 위하여 보호관찰관을 둔다.', 3984);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7079, '② 보호관찰관은 형사정책학, 행형학, 범죄학, 사회사업학, 교육학, 심리학, 그 밖에 보호관찰에 필요한 전문적 지식을 갖춘 사람이어야 한다.', 3984);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7080, '① 범죄예방활동을 하고, 보호관찰활동과 갱생보호사업을 지원하기 위하여 범죄예방 자원봉사위원(이하 "범죄예방위원"이라 한다)을 둘 수 있다.', 3986);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7081, '② 법무부장관은 법무부령으로 정하는 바에 따라 범죄예방위원을 위촉한다.', 3986);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7082, '③ 범죄예방위원의 명예와 이 법에 따른 활동은 존중되어야 한다.', 3986);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7083, '④ 범죄예방위원은 명예직으로 하되, 예산의 범위에서 직무수행에 필요한 비용의 전부 또는 일부를 지급할 수 있다.', 3986);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7084, '⑤ 범죄예방위원의 위촉 및 해촉, 정원, 직무의 구체적 내용, 조직, 비용의 지급, 그 밖에 필요한 사항은 법무부령으로 정한다.', 3986);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7085, '① 법원은 피고인에 대하여 「형법」 제59조의2 및 제62조의2에 따른 보호관찰, 사회봉사 또는 수강을 명하기 위하여 필요하다고 인정하면 그 법원의 소재지(所在地) 또는 피고인의 주거지를 관할하는 보호관찰소의 장에게 범행 동기, 직업, 생활환경, 교우관계, 가족상황, 피해회복 여부 등 피고인에 관한 사항의 조사를 요구할 수 있다.', 3987);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7086, '② 제1항의 요구를 받은 보호관찰소의 장은 지체 없이 이를 조사하여 서면으로 해당 법원에 알려야 한다. 이 경우 필요하다고 인정하면 피고인이나 그 밖의 관계인을 소환하여 심문하거나 소속 보호관찰관에게 필요한 사항을 조사하게 할 수 있다.', 3987);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7087, '③ 법원은 제1항의 요구를 받은 보호관찰소의 장에게 조사진행상황에 관한 보고를 요구할 수 있다.', 3987);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7088, '① 법원은 「소년법」 제12조에 따라 소년 보호사건에 대한 조사 또는 심리를 위하여 필요하다고 인정하면 그 법원의 소재지 또는 소년의 주거지를 관할하는 보호관찰소의 장에게 소년의 품행, 경력, 가정상황, 그 밖의 환경 등 필요한 사항에 관한 조사를 의뢰할 수 있다.', 3988);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7089, '② 제1항의 의뢰를 받은 보호관찰소의 장은 지체 없이 조사하여 서면으로 법원에 통보하여야 하며, 조사를 위하여 필요한 경우에는 소년 또는 관계인을 소환하여 심문하거나 소속 보호관찰관으로 하여금 필요한 사항을 조사하게 할 수 있다.', 3988);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7090, '① 법원은 「형법」 제59조의2 또는 제62조의2에 따라 보호관찰을 명하는 판결이 확정된 때부터 3일 이내에 판결문 등본 및 준수사항을 적은 서면을 피고인의 주거지를 관할하는 보호관찰소의 장에게 보내야 한다.', 3989);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7091, '② 제1항의 경우 법원은 그 의견이나 그 밖에 보호관찰에 참고가 될 수 있는 자료를 첨부할 수 있다.', 3989);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7092, '③ 법원은 제1항의 통지를 받은 보호관찰소의 장에게 보호관찰 상황에 관한 보고를 요구할 수 있다.', 3989);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7093, '① 교도소ㆍ구치소ㆍ소년교도소의 장은 징역 또는 금고의 형을 선고받은 소년(이하 "소년수형자"라 한다)이 「소년법」 제65조 각 호의 기간을 지나면 그 교도소ㆍ구치소ㆍ소년교도소의 소재지를 관할하는 심사위원회에 그 사실을 통보하여야 한다.', 3990);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7094, '② 소년원장은 보호소년이 수용된 후 6개월이 지나면 그 소년원의 소재지를 관할하는 심사위원회에 그 사실을 통보하여야 한다.', 3990);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7095, '① 교도소ㆍ구치소ㆍ소년교도소 및 소년원(이하 "수용기관"이라 한다)의 장은 「소년법」 제65조 각 호의 기간이 지난 소년수형자 또는 수용 중인 보호소년에 대하여 법무부령으로 정하는 바에 따라 관할 심사위원회에 가석방, 퇴원 또는 임시퇴원 심사를 신청할 수 있다.', 3991);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7096, '② 제1항의 신청을 할 때에는 제26조 또는 제27조에 따라 통지받은 환경조사 및 환경개선활동 결과를 고려하여야 한다.', 3991);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7097, '① 심사위원회는 제22조제1항에 따른 신청을 받으면 소년수형자에 대한 가석방 또는 보호소년에 대한 퇴원ㆍ임시퇴원이 적절한지를 심사하여 결정한다.', 3992);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7098, '② 심사위원회는 제21조에 따른 통보를 받은 사람에 대하여는 제22조제1항에 따른 신청이 없는 경우에도 직권으로 가석방ㆍ퇴원 및 임시퇴원이 적절한지를 심사하여 결정할 수 있다.', 3992);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7099, '③ 심사위원회는 제1항 또는 제2항에 따라 소년수형자의 가석방이 적절한지를 심사할 때에는 보호관찰의 필요성을 심사하여 결정한다.', 3992);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7100, '④ 심사위원회는 제1항부터 제3항까지의 규정에 따라 심사ㆍ결정을 할 때에는 본인의 인격, 교정성적, 직업, 생활태도, 가족관계 및 재범 위험성 등 모든 사정을 고려하여야 한다.', 3992);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7101, '① 심사위원회는 「형의 집행 및 수용자의 처우에 관한 법률」 제122조에 따라 가석방되는 사람에 대하여 보호관찰의 필요성을 심사하여 결정한다.', 3993);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7102, '② 심사위원회는 제1항에 따른 보호관찰심사를 할 때에는 제28조에 따른 보호관찰 사안조사 결과를 고려하여야 한다.', 3993);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7103, '① 수용기관ㆍ병원ㆍ요양소ㆍ「보호소년 등의 처우에 관한 법률」에 따른 의료재활소년원의 장은 소년수형자 및 「소년법」 제32조제1항제7호ㆍ제9호ㆍ제10호의 보호처분 중 어느 하나에 해당하는 처분을 받은 사람(이하 "수용자"라 한다)을 수용한 경우에는 지체 없이 거주예정지를 관할하는 보호관찰소의 장에게 신상조사서를 보내 환경조사를 의뢰하여야 한다. <개정 2014.12.30, 2020.10.20>', 3995);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7104, '② 제1항에 따라 환경조사를 의뢰받은 보호관찰소의 장은 수용자의 범죄 또는 비행의 동기, 수용 전의 직업, 생활환경, 교우관계, 가족상황, 피해회복 여부, 생계대책 등을 조사하여 수용기관의 장에게 알려야 한다. 이 경우 필요하다고 인정하면 수용자를 면담하거나 관계인을 소환하여 심문(審問)하거나 소속 보호관찰관에게 필요한 사항을 조사하게 할 수 있다.', 3995);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7105, '① 보호관찰소의 장은 제26조에 따른 환경조사 결과에 따라 수용자의 건전한 사회 복귀를 촉진하기 위하여 필요하다고 인정하면 본인의 동의를 얻거나 가족ㆍ관계인의 협력을 받아 본인의 환경개선을 위한 활동을 할 수 있다.', 3996);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7106, '② 보호관찰소의 장은 제1항에 따른 환경개선활동을 위하여 필요하다고 인정하면 수용기관의 장에게 수용자의 면담 등 필요한 협조를 요청할 수 있다.', 3996);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7107, '③ 보호관찰소의 장은 제1항에 따른 환경개선활동의 결과를 수용기관의 장과 수용기관의 소재지를 관할하는 심사위원회에 알려야 한다.', 3996);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7108, '① 교도소ㆍ구치소ㆍ소년교도소의 장은 징역 또는 금고 이상의 형을 선고받은 성인(이하 "성인수형자"라 한다)에 대하여 「형의 집행 및 수용자의 처우에 관한 법률」 제121조에 따라 가석방심사위원회에 가석방 적격심사신청을 할 때에는 신청과 동시에 가석방 적격심사신청 대상자의 명단과 신상조사서를 해당 교도소ㆍ구치소ㆍ소년교도소의 소재지를 관할하는 심사위원회에 보내야 한다.', 3997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7109, '② 심사위원회는 교도소ㆍ구치소ㆍ소년교도소의 장으로부터 가석방 적격심사신청 대상자의 명단과 신상조사서를 받으면 해당 성인수형자를 면담하여 직접 제26조제2항 전단에 규정된 사항, 석방 후의 재범 위험성 및 사회생활에 대한 적응 가능성 등에 관한 조사(이하 "보호관찰 사안조사"라 한다)를 하거나 교도소ㆍ구치소ㆍ소년교도소의 소재지 또는 해당 성인수형자의 거주예정지를 관할하는 보호관찰소의 장에게 그 자료를 보내 보호관찰 사안조사를 의뢰할 수 있다.', 3997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7110, '③ 제2항에 따라 보호관찰 사안조사를 의뢰받은 보호관찰소의 장은 지체 없이 보호관찰 사안조사를 하고 그 결과를 심사위원회에 통보하여야 한다.', 3997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7111, '④ 교도소ㆍ구치소ㆍ소년교도소의 장은 심사위원회 또는 보호관찰소의 장으로부터 보호관찰 사안조사를 위하여 성인수형자의 면담 등 필요한 협조 요청을 받으면 이에 협조하여야 한다.', 3997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7112, '① 보호관찰은 법원의 판결이나 결정이 확정된 때 또는 가석방ㆍ임시퇴원된 때부터 시작된다.', 3998);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7113, '② 보호관찰 대상자는 대통령령으로 정하는 바에 따라 주거, 직업, 생활계획, 그 밖에 필요한 사항을 관할 보호관찰소의 장에게 신고하여야 한다.', 3998);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7114, null, 3999);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7115, '① 보호관찰 대상자는 보호관찰관의 지도ㆍ감독을 받으며 준수사항을 지키고 스스로 건전한 사회인이 되도록 노력하여야 한다.', 4001);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7116, '② 보호관찰 대상자는 다음 각 호의 사항을 지켜야 한다.', 4001);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7117, '③ 법원 및 심사위원회는 판결의 선고 또는 결정의 고지를 할 때에는 제2항의 준수사항 외에 범죄의 내용과 종류 및 본인의 특성 등을 고려하여 필요하면 보호관찰 기간의 범위에서 기간을 정하여 다음 각 호의 사항을 특별히 지켜야 할 사항으로 따로 과(科)할 수 있다.', 4001);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7118, '④ 보호관찰 대상자가 제2항 또는 제3항의 준수사항을 위반하거나 사정변경의 상당한 이유가 있는 경우에는 법원은 보호관찰소의 장의 신청 또는 검사의 청구에 따라, 심사위원회는 보호관찰소의 장의 신청에 따라 각각 준수사항의 전부 또는 일부를 추가, 변경하거나 삭제할 수 있다. <개정 2019.4.16>', 4001);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7119, '⑤ 제2항부터 제4항까지의 준수사항은 서면으로 고지하여야 한다.', 4001);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7120, '① 보호관찰관은 보호관찰 대상자의 재범을 방지하고 건전한 사회 복귀를 촉진하기 위하여 필요한 지도ㆍ감독을 한다.', 4002);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7121, '② 제1항의 지도ㆍ감독 방법은 다음 각 호와 같다.', 4002);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7122, '① 보호관찰소의 장은 범행 내용, 재범위험성 등 보호관찰 대상자의 개별적 특성을 고려하여 그에 알맞은 지도ㆍ감독의 방법과 수준에 따라 분류처우를 하여야 한다.', 4003);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7123, '② 제1항에 따른 분류처우에 관하여 필요한 사항은 대통령령으로 정한다.', 4003);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7124, '① 보호관찰관은 보호관찰 대상자가 자조(自助)의 노력을 할 때에는 그의 개선과 자립을 위하여 필요하다고 인정되는 적절한 원호(援護)를 한다.', 4004);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7125, '② 제1항의 원호의 방법은 다음 각 호와 같다.', 4004);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7126, '① 보호관찰 대상자로서 정신건강의학과전문의가 「정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률」 제3조제1호에 따른 정신질환자로 진단하거나 감정한 사람(이하 "정신질환 보호관찰 대상자"라 한다)은 같은 조 제3호의 정신건강복지센터에 등록하여 상담, 진료, 재활 지원 등의 서비스를 받을 수 있다.', 4007);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7127, '② 보호관찰소의 장은 제1항의 정신질환 보호관찰 대상자의 보호관찰이 종료되는 때에는 심사위원회의 심사를 거쳐 그 종료사실을 정신질환 보호관찰 대상자의 주소지를 관할하는 경찰관서의 장 및 지방자치단체의 장에게 통보할 수 있다.', 4007);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7128, '③ 심사위원회는 제2항에 따라 정신질환 보호관찰 대상자의 보호관찰 종료사실통보가 적절한지 심사할 때에는 정신질환 보호관찰 대상자의 재범 방지 및 치료의 필요성 여부를 심사하여 결정한다.', 4007);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7129, '④ 제2항에 따라 통보하는 정보의 구체적인 범위, 통보 방법 및 통보 절차 등에 필요한 사항은 대통령령으로 정한다.', 4007);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7130, '① 보호관찰소의 장은 보호관찰을 위하여 필요하다고 인정하면 보호관찰 대상자나 그 밖의 관계인을 소환하여 심문하거나 소속 보호관찰관에게 필요한 사항을 조사하게 할 수 있다.', 4008);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7131, '② 보호관찰소의 장은 보호관찰을 위하여 필요하다고 인정하면 국공립기관이나 그 밖의 단체에 사실을 알아보거나 관련 자료의 열람 등 협조를 요청할 수 있다.', 4008);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7132, '③ 제1항과 제2항의 직무를 담당하는 사람은 직무상 비밀을 엄수하고, 보호관찰 대상자 및 관계인의 인권을 존중하며, 보호관찰 대상자의 건전한 사회 복귀에 방해되는 일이 없도록 주의하여야 한다.', 4008);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7133, '① 보호관찰소의 장은 보호관찰 대상자가 제32조의 준수사항을 위반하였거나 위반하였다고 의심할 상당한 이유가 있고, 다음 각 호의 어느 하나에 해당하는 사유가 있는 경우에는 관할 지방검찰청의 검사에게 신청하여 검사의 청구로 관할 지방법원 판사의 구인장을 발부받아 보호관찰 대상자를 구인(拘引)할 수 있다.', 4010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7134, '② 제1항의 구인장은 검사의 지휘에 따라 보호관찰관이 집행한다. 다만, 보호관찰관이 집행하기 곤란한 경우에는 사법경찰관리에게 집행하게 할 수 있다.', 4010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7135, '① 보호관찰소의 장은 제32조의 준수사항을 위반한 보호관찰 대상자가 제39조제1항 각 호의 어느 하나에 해당하는 사유가 있는 경우로서 긴급하여 제39조에 따른 구인장을 발부받을 수 없는 경우에는 그 사유를 알리고 구인장 없이 그 보호관찰 대상자를 구인할 수 있다. 이 경우 긴급하다 함은 해당 보호관찰 대상자를 우연히 발견한 경우 등과 같이 구인장을 발부받을 시간적 여유가 없는 경우를 말한다.', 4011);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7136, '② 보호관찰소의 장은 제1항에 따라 보호관찰 대상자를 구인한 경우에는 긴급구인서를 작성하여 즉시 관할 지방검찰청 검사의 승인을 받아야 한다.', 4011);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7137, '③ 보호관찰소의 장은 제2항에 따른 승인을 받지 못하면 즉시 보호관찰 대상자를 석방하여야 한다.', 4011);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7138, '① 보호관찰소의 장은 다음 각 호의 신청이 필요하다고 인정되면 제39조 또는 제40조에 따라 구인한 보호관찰 대상자를 수용기관 또는 소년분류심사원에 유치할 수 있다. <개정 2019.4.16>', 4013);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7139, '② 제1항에 따른 유치를 하려는 경우에는 보호관찰소의 장이 검사에게 신청하여 검사의 청구로 관할 지방법원 판사의 허가를 받아야 한다. 이 경우 검사는 보호관찰 대상자가 구인된 때부터 48시간 이내에 유치 허가를 청구하여야 한다. <개정 2014.12.30>', 4013);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7140, '③ 보호관찰소의 장은 유치 허가를 받은 때부터 24시간 이내에 제1항 각 호의 신청을 하여야 한다.', 4013);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7141, '④ 검사는 보호관찰소의 장으로부터 제1항제1호의 신청을 받고 그 이유가 타당하다고 인정되면 48시간 이내에 관할 지방법원에 보호관찰을 조건으로 한 형의 선고유예의 실효 또는 집행유예의 취소를 청구하여야 한다.', 4013);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7142, '① 제42조에 따른 유치의 기간은 제39조제1항 또는 제40조제1항에 따라 구인한 날부터 20일로 한다. <개정 2014.12.30>', 4014);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7143, '② 법원은 제42조제1항제1호 또는 제3호에 따른 신청이 있는 경우에 심리(審理)를 위하여 필요하다고 인정되면 심급마다 20일의 범위에서 한 차례만 유치기간을 연장할 수 있다.', 4014);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7144, '③ 보호관찰소의 장은 제42조제1항제2호에 따른 신청이 있는 경우에 심사위원회의 심사에 필요하면 검사에게 신청하여 검사의 청구로 지방법원 판사의 허가를 받아 10일의 범위에서 한 차례만 유치기간을 연장할 수 있다.', 4014);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7145, null, 4015);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7146, '① 보호관찰소 소속 공무원은 보호관찰 대상자가 다음 각 호의 어느 하나에 해당하고, 정당한 직무집행 과정에서 필요하다고 인정되는 상당한 이유가 있으면 제46조의3제1항에 따른 보호장구를 사용할 수 있다.', 4019);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7147, '② 보호장구를 사용하는 경우에는 보호관찰 대상자의 나이, 신체적ㆍ정신적 건강상태 및 보호관찰 집행 상황 등을 고려하여야 한다.', 4019);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7148, '③ 그 밖에 보호장구의 사용절차 및 방법 등에 관하여 필요한 사항은 법무부령으로 정한다.', 4019);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7149, '① 보호장구의 종류는 다음 각 호와 같다.', 4020);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7150, '② 보호장구의 종류별 사용요건은 다음 각 호와 같다.', 4020);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7151, '① 제46조의3제1항제1호부터 제3호까지의 보호장구를 사용할 경우에는 보호관찰 대상자에게 그 사유를 알려주어야 한다. 다만, 상황이 급박하여 시간적인 여유가 없을 때에는 보호장구 사용 직후 지체 없이 알려주어야 한다.', 4021);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7152, '② 제46조의3제1항제4호 및 제5호의 보호장구를 사용할 경우에는 사전에 상대방에게 이를 경고하여야 한다. 다만, 상황이 급박하여 경고할 시간적인 여유가 없는 때에는 그러하지 아니하다.', 4021);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7153, '① 「형법」 제61조제2항에 따른 선고유예의 실효 및 같은 법 제64조제2항에 따른 집행유예의 취소는 검사가 보호관찰소의 장의 신청을 받아 법원에 청구한다.', 4023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7154, '② 제1항의 실효 및 취소절차에 관하여는 「형사소송법」 제335조를 준용한다.', 4023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7155, '① 심사위원회는 가석방 또는 임시퇴원된 사람이 보호관찰기간 중 제32조의 준수사항을 위반하고 위반 정도가 무거워 보호관찰을 계속하기가 적절하지 아니하다고 판단되는 경우에는 보호관찰소의 장의 신청을 받거나 직권으로 가석방 및 임시퇴원의 취소를 심사하여 결정할 수 있다.', 4024);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7156, '② 심사위원회는 제1항에 따른 심사 결과 가석방 또는 임시퇴원을 취소하는 것이 적절하다고 결정한 경우에는 결정서에 관계 서류를 첨부하여 법무부장관에게 이에 대한 허가를 신청하여야 하며, 법무부장관은 심사위원회의 결정이 정당하다고 인정되면 이를 허가할 수 있다.', 4024);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7157, '① 보호관찰소의 장은 「소년법」 제32조제1항제4호 또는 제5호의 보호처분에 따라 보호관찰을 받고 있는 사람이 보호관찰 기간 중 제32조의 준수사항을 위반하고 그 정도가 무거워 보호관찰을 계속하기 적절하지 아니하다고 판단되면 보호관찰소 소재지를 관할하는 법원에 보호처분의 변경을 신청할 수 있다.', 4025);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7158, '② 제1항에 따른 보호처분의 변경을 할 경우 신청대상자가 19세 이상인 경우에도 「소년법」 제2조 및 제38조제1항에도 불구하고 같은 법 제2장의 보호사건 규정을 적용한다.', 4025);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7159, '① 「소년법」 제60조제1항에 따라 형을 선고받은 후 가석방된 사람이 그 형의 단기(短期)가 지나고 보호관찰의 목적을 달성하였다고 인정되면 같은 법 제66조에서 정한 기간 전이라도 심사위원회는 보호관찰소의 장의 신청을 받거나 직권으로 형의 집행을 종료한 것으로 결정할 수 있다.', 4026);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7160, '② 임시퇴원자가 임시퇴원이 취소되지 아니하고 보호관찰 기간을 지난 경우에는 퇴원된 것으로 본다.', 4026);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7161, '① 보호관찰은 보호관찰 대상자가 다음 각 호의 어느 하나에 해당하는 때에 종료한다. <개정 2014.12.30, 2019.4.16>', 4027);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7162, '② 보호관찰 대상자가 보호관찰 기간 중 금고 이상의 형의 집행을 받게 된 때에는 해당 형의 집행기간 동안 보호관찰 대상자에 대한 보호관찰 기간은 계속 진행되고, 해당 형의 집행이 종료ㆍ면제되거나 보호관찰 대상자가 가석방된 경우 보호관찰 기간이 남아있는 때에는 그 잔여기간 동안 보호관찰을 집행한다. <신설 2019.4.16>', 4027);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7163, '① 심사위원회는 보호관찰 대상자의 성적이 양호할 때에는 보호관찰소의 장의 신청을 받거나 직권으로 보호관찰을 임시해제할 수 있다.', 4028);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7164, '② 임시해제 중에는 보호관찰을 하지 아니한다. 다만, 보호관찰 대상자는 준수사항을 계속하여 지켜야 한다.', 4028);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7165, '③ 심사위원회는 임시해제 결정을 받은 사람에 대하여 다시 보호관찰을 하는 것이 적절하다고 인정되면 보호관찰소의 장의 신청을 받거나 직권으로 임시해제 결정을 취소할 수 있다.', 4028);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7166, '④ 제3항에 따라 임시해제 결정이 취소된 경우에는 그 임시해제 기간을 보호관찰 기간에 포함한다.', 4028);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7167, '① 심사위원회는 가석방 또는 임시퇴원된 사람이 있는 곳을 알 수 없어 보호관찰을 계속할 수 없을 때에는 보호관찰소의 장의 신청을 받거나 직권으로 보호관찰을 정지하는 결정(이하 "정지결정"이라 한다)을 할 수 있다.', 4029);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7168, '② 심사위원회는 제1항에 따라 보호관찰을 정지한 사람이 있는 곳을 알게 되면 즉시 그 정지를 해제하는 결정(이하 "정지해제결정"이라 한다)을 하여야 한다.', 4029);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7169, '③ 보호관찰 정지 중인 사람이 제39조 또는 제40조에 따라 구인된 경우에는 구인된 날에 정지해제결정을 한 것으로 본다.', 4029);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7170, '④ 형기 또는 보호관찰 기간은 정지결정을 한 날부터 그 진행이 정지되고, 정지해제결정을 한 날부터 다시 진행된다.', 4029);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7171, '⑤ 심사위원회는 제1항에 따라 정지결정을 한 후 소재 불명이 천재지변이나 그 밖의 부득이한 사정 등 보호관찰 대상자에게 책임이 있는 사유로 인한 것이 아닌 것으로 밝혀진 경우에는 그 정지결정을 취소하여야 한다. 이 경우 정지결정은 없었던 것으로 본다.', 4029);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7172, '① 보호관찰소의 장은 기관ㆍ단체 또는 개인이 보호관찰 대상자에 대한 원호 등을 위하여 보호관찰소에 자발적으로 기탁하는 금품을 접수할 수 있다.', 4032);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7173, '② 기부자에 대한 영수증 발급, 기부금품의 용도 지정, 장부의 열람, 그 밖에 필요한 사항은 대통령령으로 정한다.', 4032);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7174, '① 보호관찰소의 장은 다음 각 호의 어느 하나에 해당하는 범죄를 저지른 가석방자의 보호관찰이 종료된 때에 재범 방지 등을 위하여 필요하다고 인정하면 가석방자의 보호관찰 종료사실 등을 그의 주거지를 관할하는 경찰관서의 장에게 통보할 수 있다. <개정 2016.12.27, 2020.2.4>', 4033);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7175, '② 제1항에 따라 보호관찰소의 장이 통보할 사항은 다음 각 호와 같다.', 4033);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7176, '③ 제1항에 따른 통보의 절차 등에 관하여 필요한 사항은 대통령령으로 정한다.', 4033);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7177, '① 법무부장관은 이 법에 따른 보호관찰의 집행이 종료된 사람의 재범 여부를 조사하고 보호관찰명령의 효과를 평가하기 위하여 필요한 경우에는 그 집행이 종료된 때부터 3년 동안 관계 기관에 그 사람에 관한 범죄경력자료와 수사경력자료에 대한 조회를 요청할 수 있다.', 4034);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7178, '② 제1항의 요청을 받은 관계 기관의 장은 정당한 사유 없이 이를 거부해서는 아니 된다.', 4034);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7179, '① 법원은 「형법」 제62조의2에 따른 사회봉사를 명할 때에는 500시간, 수강을 명할 때에는 200시간의 범위에서 그 기간을 정하여야 한다. 다만, 다른 법률에 특별한 규정이 있는 경우에는 그 법률에서 정하는 바에 따른다.', 4038);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7180, '② 법원은 제1항의 경우에 사회봉사ㆍ수강명령 대상자가 사회봉사를 하거나 수강할 분야와 장소 등을 지정할 수 있다.', 4038);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7181, '① 법원은 「형법」 제62조의2에 따른 사회봉사 또는 수강을 명하는 판결이 확정된 때부터 3일 이내에 판결문 등본 및 준수사항을 적은 서면을 피고인의 주거지를 관할하는 보호관찰소의 장에게 보내야 한다.', 4039);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7182, '② 제1항의 경우에 법원은 그 의견이나 그 밖에 사회봉사명령 또는 수강명령의 집행에 참고가 될 만한 자료를 첨부할 수 있다.', 4039);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7183, '③ 법원 또는 법원의 장은 제1항의 통지를 받은 보호관찰소의 장에게 사회봉사명령 또는 수강명령의 집행상황에 관한 보고를 요구할 수 있다.', 4039);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7184, '① 사회봉사명령 또는 수강명령은 보호관찰관이 집행한다. 다만, 보호관찰관은 국공립기관이나 그 밖의 단체에 그 집행의 전부 또는 일부를 위탁할 수 있다.', 4040);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7185, '② 보호관찰관은 사회봉사명령 또는 수강명령의 집행을 국공립기관이나 그 밖의 단체에 위탁한 때에는 이를 법원 또는 법원의 장에게 통보하여야 한다.', 4040);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7186, '③ 법원은 법원 소속 공무원으로 하여금 사회봉사 또는 수강할 시설 또는 강의가 사회봉사ㆍ수강명령 대상자의 교화ㆍ개선에 적당한지 여부와 그 운영 실태를 조사ㆍ보고하도록 하고, 부적당하다고 인정하면 그 집행의 위탁을 취소할 수 있다.', 4040);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7187, '④ 보호관찰관은 사회봉사명령 또는 수강명령의 집행을 위하여 필요하다고 인정하면 국공립기관이나 그 밖의 단체에 협조를 요청할 수 있다.', 4040);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7188, '① 사회봉사ㆍ수강명령 대상자는 대통령령으로 정하는 바에 따라 주거, 직업, 그 밖에 필요한 사항을 관할 보호관찰소의 장에게 신고하여야 한다.', 4041);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7189, '② 사회봉사ㆍ수강명령 대상자는 다음 각 호의 사항을 준수하여야 한다.', 4041);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7190, '③ 법원은 판결의 선고를 할 때 제2항의 준수사항 외에 대통령령으로 정하는 범위에서 본인의 특성 등을 고려하여 특별히 지켜야 할 사항을 따로 과(科)할 수 있다.', 4041);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7191, '④ 제2항과 제3항의 준수사항은 서면으로 고지하여야 한다.', 4041);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7192, '① 사회봉사ㆍ수강은 사회봉사ㆍ수강명령 대상자가 다음 각 호의 어느 하나에 해당하는 때에 종료한다. <개정 2014.12.30, 2019.4.16>', 4042);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7193, '② 사회봉사ㆍ수강명령 대상자가 사회봉사ㆍ수강명령 집행 중 금고 이상의 형의 집행을 받게 된 때에는 해당 형의 집행이 종료ㆍ면제되거나 사회봉사ㆍ수강명령 대상자가 가석방된 경우 잔여 사회봉사ㆍ수강명령을 집행한다. <신설 2019.4.16>', 4042);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7194, '① 사회봉사ㆍ수강명령 대상자에 대하여는 제34조부터 제36조까지, 제54조, 제55조, 제55조의4, 제56조 및 제57조를 준용한다. <개정 2014.12.30, 2019.4.16>', 4043);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7195, '② 사회봉사ㆍ수강명령 대상자의 준수사항이나 명령 위반에 따른 경고, 구인, 유치, 집행유예 취소 및 보호처분 변경 등에 관하여는 제37조부터 제45조까지, 제46조, 제46조의2부터 제46조의5까지, 제47조 및 제49조를 준용한다. <개정 2019.4.16>', 4043);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7196, '① 갱생보호는 다음 각 호의 방법으로 한다. <개정 2014.5.20>', 4044);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7197, '② 제1항 각 호의 구체적인 내용은 대통령령으로 정한다.', 4044);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7198, '③ 제71조에 따른 한국법무보호복지공단 또는 제67조에 따라 갱생보호사업의 허가를 받은 자는 제1항 각 호의 갱생보호활동을 위하여 갱생보호시설을 설치ㆍ운영할 수 있다.', 4044);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7199, '④ 제3항의 갱생보호시설의 기준은 법무부령으로 정한다.', 4044);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7200, '① 갱생보호 대상자와 관계 기관은 보호관찰소의 장, 제67조제1항에 따라 갱생보호사업 허가를 받은 자 또는 제71조에 따른 한국법무보호복지공단에 갱생보호 신청을 할 수 있다.', 4045);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7201, '② 제1항의 신청을 받은 자는 지체 없이 보호가 필요한지 결정하고 보호하기로 한 경우에는 그 방법을 결정하여야 한다.', 4045);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7202, '③ 제1항의 신청을 받은 자가 제2항에 따라 보호결정을 한 경우에는 지체 없이 갱생보호에 필요한 조치를 하여야 한다.', 4045);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7203, '① 갱생보호사업을 하려는 자는 법무부령으로 정하는 바에 따라 법무부장관의 허가를 받아야 한다. 허가받은 사항을 변경하려는 경우에도 또한 같다.', 4046);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7204, '② 법무부장관은 갱생보호사업의 허가를 할 때에는 사업의 범위와 허가의 기간을 정하거나 그 밖에 필요한 조건을 붙일 수 있다.', 4046);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7205, null, 4047);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7206, null, 4049);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7207, '① 공단의 주된 사무소의 소재지는 정관으로 정한다.', 4053);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7208, '② 공단은 정관으로 정하는 바에 따라 필요한 곳에 지부와 지소를 둘 수 있다.', 4053);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7209, '① 공단의 정관에는 다음 각 호의 사항이 포함되어야 한다.', 4054);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7210, '② 공단은 정관을 변경하려면 법무부장관의 인가를 받아야 한다.', 4054);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7211, '① 공단에 이사장 1명을 포함한 15명 이내의 이사와 감사 2명을 둔다. <개정 2014.5.20>', 4056);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7212, '② 이사장은 법무부장관이 임명하고, 그 임기는 3년으로 하되 연임할 수 있다. 다만, 임기가 만료된 이사장은 그 후임자가 임명될 때까지 그 직무를 행한다. <개정 2014.5.20>', 4056);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7213, '③ 이사는 갱생보호사업에 열성이 있고, 학식과 덕망이 있는 사람 중에서 이사장의 제청에 의하여 법무부장관이 임명하거나 위촉하며, 임기는 3년으로 하되 연임할 수 있다. 다만, 공무원인 이사의 임기는 그 직위에 있는 동안으로 한다.', 4056);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7214, '④ 감사는 이사장의 제청에 의하여 법무부장관이 임명하며, 임기는 2년으로 하되 연임할 수 있다.', 4056);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7215, '① 이사장은 공단을 대표하고 공단의 업무를 총괄한다.', 4057);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7216, '② 감사는 공단의 업무 및 회계를 감사한다.', 4057);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7217, '③ 이사장 아닌 이사와 감사는 비상근으로 할 수 있다.', 4057);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7218, null, 4058);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7219, '① 임원이 제78조 각 호의 어느 하나에 해당하게 되면 당연히 퇴직한다.', 4059);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7220, '② 법무부장관은 임원이 다음 각 호의 어느 하나에 해당할 때에는 그 임원을 해임하거나 해촉할 수 있다.', 4059);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7221, '① 공단의 업무에 관한 주요 사항을 심의ㆍ의결하기 위하여 공단에 이사회를 둔다.', 4060);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7222, '② 이사회는 이사장과 이사로 구성한다.', 4060);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7223, '③ 이사장은 이사회를 소집하고 그 의장이 된다.', 4060);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7224, '④ 감사는 이사회에 출석하여 의견을 진술할 수 있다.', 4060);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7225, null, 4062);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7226, null, 4063);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7227, '① 공단의 회계연도는 정부의 회계연도에 따른다.', 4064);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7228, '② 공단은 법무부령으로 정하는 바에 따라 매 회계연도가 시작되기 전에 다음 회계연도에 실시할 공단의 사업계획 및 예산을 법무부장관에게 제출하여 그 승인을 받아야 한다. 이를 변경할 때에도 또한 같다.', 4064);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7229, '③ 공단은 법무부령으로 정하는 바에 따라 매 회계연도의 종료 후 전년도의 사업 실적과 결산을 법무부장관에게 제출하여야 한다.', 4064);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7230, '① 공단은 기관ㆍ단체 또는 개인이 갱생보호사업을 위하여 공단에 자발적으로 기탁하는 금품을 접수할 수 있다.', 4065);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7231, '② 제1항에 따라 기부금품을 접수한 경우 공단은 그 접수 상황 및 처리 상황을 법무부장관에게 보고하여야 한다.', 4065);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7232, '③ 기부자에 대한 영수증 발급, 기부금품의 용도 지정, 장부의 열람, 그 밖에 필요한 사항은 대통령령으로 정한다.', 4065);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7233, null, 4067);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7234, '① 기금은 공단이 운용ㆍ관리한다.', 4068);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7235, '② 기금의 운용ㆍ관리에 필요한 사항은 대통령령으로 정한다.', 4068);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7236, '① 사업자 또는 공단은 갱생보호사업을 위하여 수익사업을 하려면 사업마다 법무부장관의 승인을 받아야 한다. 이를 변경할 때에도 또한 같다.', 4076);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7237, '② 법무부장관은 수익사업을 하는 사업자 또는 공단이 수익을 갱생보호사업 외의 사업에 사용한 경우에는 수익사업의 시정이나 정지를 명할 수 있다.', 4076);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7238, '① 법무부장관은 사업자와 공단을 지휘ㆍ감독한다.', 4077);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7239, '② 법무부장관은 사업자와 공단에 대하여 감독상 필요한 경우에는 그 업무에 관한 사항을 보고하게 하거나 자료의 제출이나 그 밖에 필요한 명령을 할 수 있으며, 소속 공무원에게 사업자 및 공단의 운영 실태를 조사하게 할 수 있다.', 4077);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7240, '③ 제2항에 따라 조사를 하는 공무원은 그 권한을 나타내는 증표를 지니고 이를 관계인에게 내보여야 한다.', 4077);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7241, '① 이 법에 따른 공단이 아닌 자는 한국법무보호복지공단 또는 이와 유사한 명칭을 사용하지 못한다.', 4078);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7242, '② 이 법에 따른 사업자가 아닌 자는 갱생보호회 또는 이와 유사한 명칭을 사용하지 못한다.', 4078);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7243, null, 4079);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7244, '① 제98조를 위반한 자에게는 200만원 이하의 과태료를 부과한다.', 4081);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7245, '② 제1항에 따른 과태료는 대통령령으로 정하는 바에 따라 법무부장관이 부과ㆍ징수한다.', 4081);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7246, '①법 제5조의 규정에 의한 보호관찰심사위원회(이하 "심사위원회"라 한다)의 위원장은 심사위원회의 회무를 통할하고, 심사위원회를 대표하며, 심사위원회의 회의를 소집하고 그 의장이 된다.', 4083);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7247, '②위원장이 부득이한 사유로 직무를 수행할 수 없는 때에는 위원장이 미리 지정한 위원이 그 직무를 대행한다.', 4083);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7248, '①심사위원회의 고위공무원단에 속하는 임기제공무원인 상임위원은 다음 각 호의 어느 하나에 해당하는 사람으로서 보호관찰에 관한 지식과 경험이 풍부한 사람 중에서 임명한다. <개정 2006.6.12, 2009.3.18, 2009.11.23, 2014.6.30, 2017.2.7, 2022.12.27>', 4084);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7249, '②심사위원회의 4급 임기제공무원인 상임위원은 다음 각 호의 어느 하나에 해당하는 사람으로서 보호관찰에 관한 지식과 경험이 풍부한 사람 중에서 임명한다. <개정 2009.3.18, 2009.11.23, 2014.6.30, 2017.2.7>', 4084);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7250, '③심사위원회의 상임위원이 아닌 위원은 위원장의 제청으로 법무부장관이 임명 또는 위촉한다.', 4084);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7251, '①심사위원회에 간사와 서기를 두되, 심사위원회 소속 공무원 또는 심사위원회의 소재지를 관할하는 보호관찰소소속 공무원중에서 위원장이 임명한다. <개정 2006.3.23>', 4085);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7252, '②간사는 위원장 및 상임위원의 명을 받아 심사위원회의 사무를 처리하고, 서기는 간사를 보조한다.', 4085);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7253, '③간사는 회의에 참석하여 발언할 수 있다.', 4085);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7254, '①심사위원회는 법 제6조에 규정된 사항을 심사함에 있어 필요한 경우에는 교도소ㆍ구치소ㆍ소년교도소 및 소년원(이하 "수용기관"이라 한다)의 장, 보호관찰관 기타 관계인을 출석시켜 의견을 듣거나 관계자료의 제출을 요청할 수 있다.', 4086);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7255, '②국ㆍ공립기관 기타 단체는 법 제11조제3항의 규정에 의한 심사위원회의 요청이 있는 경우에는 특별한 사정이 없는 한 이에 협조하여야 한다.', 4086);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7256, '③상임위원은 심사관계자료를 검토한 후 그 결과를 심사위원회에 보고하여야 한다.', 4086);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7257, '① 심사위원회는 법 제6조에 규정된 사항을 심사하여 의결하고, 위원장과 심사위원이 서명 또는 기명날인한 결정서를 작성하여야 한다.', 4087);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7258, '② 법 제12조제2항에서 "대통령령으로 정하는 경우"란 다음 각 호의 경우를 말한다. <개정 2022.1.11>', 4087);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7259, '① 법무부장관은 법 제15조의 사무를 담당하는 보호관찰소 소속 공무원이 충분한 전문적 지식을 갖출 수 있도록 교육훈련과정을 운영하여야 한다.', 4088);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7260, '② 법 제15조의 사무를 담당하는 보호관찰소 소속 공무원은 법무부령으로 정하는 바에 따라 제1항의 교육훈련과정을 이수하여야 한다.', 4088);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7261, '③ 교육훈련과정에 관하여 필요한 사항은 법무부령으로 정한다.', 4088);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7262, '①수용기관의 장은 법 제21조제1항 및 제2항의 규정에 의하여 징역 또는 금고의 형의 선고를 받은 소년(이하 "소년수형자"라 한다) 및 보호소년에 대한 기간경과의 통보를 하는 때에는 기간경과통보서를 작성하여 관할심사위원회에 통보하여야 한다.', 4090);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7263, '②수용기관의 장은 제1항의 규정에 의하여 통보한 사항 기타 신상에 관한 사항에 변동이 생긴 때에는 지체없이 관할심사위원회에 그 사실을 통보하여야 한다.', 4090);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7264, '①심사위원회는 법 제23조에 따라 가석방, 퇴원 또는 임시퇴원의 적부를 심사하여 결정하는 경우에는 소년수형자 또는 보호소년의 건전한 사회복귀를 위하여 가장 적당하다고 인정되는 시기와 다음 각호의 요건을 충족하였는지의 여부를 종합적으로 판단하여야 한다. <개정 2008.6.20, 2009.3.18>', 4093);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7265, '②심사위원회는 법 제23조제3항의 규정에 의하여 보호관찰의 필요성 여부를 심사하여 결정하는 때에는 법 제26조의 규정에 의한 환경조사 또는 법 제27조의 규정에 의한 환경개선활동의 결과를 고려하여야 한다.', 4093);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7266, '①수용기관의 장은 법 제26조제1항의 규정에 의하여 환경조사를 의뢰한 후 소년수형자 및 「소년법」 제32조제1항제8호부터 제10호까지의 어느 하나에 해당하는 보호처분을 받은 자(이하 "수용자"라 한다)의 신상에 변동이 있는 때에는 지체없이 거주예정지를 관할하는 보호관찰소의 장에게 그 사실을 통지하여야 한다. <개정 2006.3.23, 2009.3.18>', 4094);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7267, '②법 제26조의 규정에 의한 환경조사는 다음 각호의 사항에 대하여 실시하여야 한다.', 4094);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7268, null, 4098);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7269, '①보호관찰대상자는 법 제32조제2항제4호의 규정에 의한 신고를 할 때에는 법무부령이 정하는 바에 의하여 본인의 성명, 주거, 주거이전예정지 또는 여행지, 주거이전이유 또는 여행목적, 주거이전일자 또는 여행기간 등을 신고하여야 한다.', 4100);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7270, '②보호관찰대상자가 다른 보호관찰소의 관할구역안으로 주거를 이전한 때에는 10일이내에 신주거지를 관할하는 보호관찰소에 출석하여 서면으로 주거이전의 사실을 신고하여야 한다.', 4100);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7271, null, 4101);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7272, '① 보호관찰소의 장은 법 제32조제4항에 따라 준수사항의 추가, 변경 또는 삭제를 신청하는 경우에는 다음 각 호의 사항을 적은 서면으로 하여야 한다. <개정 2019.11.5>', 4102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7273, '② 보호관찰소의 장은 제1항의 신청을 할 때 신청사유를 소명할 수 있는 자료를 제출하여야 한다.', 4102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7274, '③ 법원 또는 심사위원회는 제1항에 따른 신청의 심리를 위하여 필요한 경우에는 담당보호관찰관을 출석시켜 의견을 들을 수 있고, 보호관찰 대상자를 소환하여 심문하거나 필요한 사항을 조사할 수 있다.', 4102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7275, '① 보호관찰소의 장은 법 제33조의2에 따른 분류처우(이하 이 조에서 "분류처우"라 한다)를 하기 위하여 보호관찰 대상자의 개별적 특성에 알맞은 분류처우계획을 수립하여 시행하여야 한다.', 4103);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7276, '② 보호관찰소의 장은 분류처우를 하기 위하여 보호관찰 대상자의 재범가능성, 사회생활 적응가능성 등 필요한 사항을 조사하여야 한다.', 4103);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7277, '③ 보호관찰소의 장은 분류처우를 하기 위하여 보호관찰 대상자에 대한 심리검사 등 필요한 검사를 할 수 있고, 필요한 경우 외부전문가로부터 의견을 듣거나 검사를 의뢰할 수 있다.', 4103);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7278, '①법 제35조의 규정에 의한 응급구호는 다음 각호의 1에 해당하는 경우에 실시할 수 있다.', 4104);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7279, '②보호관찰소의 장은 법 제35조의 규정에 의하여 응급구호를 하고자 하는 경우에는 예산의 범위안에서 이를 실시할 수 있다.', 4104);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7280, '① 보호관찰소의 장은 법 제36조의2제2항에 따라 정신질환 보호관찰 대상자의 보호관찰 종료사실 통보를 위한 심사위원회의 심사를 받으려는 경우에는 다음 각 호의 사항을 적은 신청서에 진단서 또는 진료확인서 등을 첨부하여 제출하여야 한다.', 4105);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7281, '② 보호관찰소의 장이 법 제36조의2제2항에 따라 통보하는 정보의 구체적인 범위는 다음 각 호와 같다.', 4105);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7282, '③ 보호관찰소의 장은 경찰관서의 장에게 법 제36조의2제2항에 따른 종료사실 통보를 하는 경우에는 제2항 각 호의 사항에 관한 전자기록을 「형사사법절차 전자화 촉진법」에 따른 형사사법정보시스템에 등록하여 경찰관서의 장이 그 전자기록을 조회하게 하는 방식으로 할 수 있다.', 4105);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7283, '①보호관찰소의 장은 법 제37조제1항의 규정에 의하여 보호관찰대상자 기타 관계인을 소환하고자 하는 경우에는 출석요구서를 발부하여야 한다. 다만, 긴급을 요하는 등 출석요구서를 발부하기에 적당하지 아니한 경우에는 다른 방법에 의할 수 있다.', 4106);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7284, '②보호관찰관은 보호관찰대상자 기타 관계인을 소환하여 조사한 때에는 그 조사내용을 서면으로 작성하여야 한다.', 4106);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7285, null, 4108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7286, '①법 제40조제2항에 따른 긴급구인승인신청은 보호관찰대상자를 구인한 때부터 12시간 이내에 하여야 한다. <개정 2017.2.7>', 4111);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7287, '②법 제40조제2항에 따른 긴급구인서에는 다음 각 호의 사항을 기재하여야 한다. <개정 2009.11.23, 2017.2.7>', 4111);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7288, '①보호관찰관은 구인된 보호관찰대상자를 보호관찰소등에 인치한 때에는 지체없이 조사하여야 한다.', 4112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7289, '②제1항의 경우 보호관찰관은 보호관찰대상자에게 심문에 대하여 진술을 거부할 수 있으며 본인에게 유리한 사실에 대하여 진술을 할 수 있다는 취지를 고지하여야 한다.', 4112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7290, '③보호관찰소의 장은 제1항의 규정에 의한 조사결과 보호관찰대상자를 법 제42조의 규정에 의하여 유치할 필요가 없다고 판단되는 때에는 즉시 석방하여야 한다.', 4112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7291, null, 4113);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7292, '①보호관찰소의 장은 법 제47조제1항의 규정에 의한 신청을 하는 때에는 다음 각호의 사항을 기재한 서면에 의하여야 한다. <개정 2009.11.23>', 4117);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7293, '②검사는 법 제47조제1항의 규정에 의한 청구를 하는 때에는 보호관찰소의 장이 제1항의 규정에 의하여 제출한 서면을 첨부하고, 그 사유를 소명하여야 한다.', 4117);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7294, '③법원은 법 제47조제1항의 규정에 의한 청구의 심리를 위하여 필요하다고 인정하는 때에는 담당보호관찰관을 출석시켜 의견을 들을 수 있다.', 4117);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7295, '①수용기관의 장은 법 제48조의 규정에 의하여 가석방 또는 임시퇴원이 취소된 보호관찰대상자를 지체없이 수용기관에 재수용하여야 한다. <개정 2008.6.20>', 4119);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7296, '②제1항의 경우 재수용을 위하여 필요한 때에는 수용기관 소재지를 관할하는 지방검찰청 또는 지청의 검사에게 구인을 의뢰할 수 있다.', 4119);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7297, '①보호관찰소의 장은 법 제49조제1항의 규정에 의하여 보호처분의 변경을 신청하는 때에는 다음 각호의 사항을 기재한 서면에 의하여야 한다. <개정 2009.11.23>', 4120);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7298, '②제1항제3호 및 제4호의 사유는 이를 소명하여야 한다.', 4120);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7299, '③법원은 제1항의 규정에 의한 신청의 심리를 위하여 필요하다고 인정하는 때에는 담당보호관찰관을 출석시켜 의견을 들을 수 있으며, 보호관찰대상자를 심문하거나 필요한 사항을 조사ㆍ심리할 수 있다.', 4120);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7300, '① 보호관찰소의 장은 법 제55조의2제1항에 따라 기부금품을 접수하는 경우 기부자에게 영수증을 발급하여야 한다. 다만, 익명으로 기부하거나 기부자를 알 수 없는 경우에는 영수증을 발급하지 아니할 수 있다.', 4122);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7301, '② 보호관찰소의 장은 제1항에 따른 기부자가 다음 각 호의 어느 하나의 경우에 해당하는 사실을 알게 된 경우에는 기부금품을 접수해서는 아니 된다.', 4122);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7302, '③ 보호관찰소의 장은 제1항에 따른 기부자가 기부금품의 용도를 지정한 경우에는 그 용도로만 사용하여야 한다. 다만, 기부자가 지정한 용도로 사용하기 어려운 경우에는 특별한 사정이 없는 한 기부자의 동의를 받아 다른 용도로 사용할 수 있다.', 4122);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7303, '④ 보호관찰소의 장은 모든 기부금의 수입 및 지출을 기부금 전용계좌를 통하여 처리하여야 한다.', 4122);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7304, '⑤ 보호관찰소의 장은 기부금품의 접수현황 및 사용실적 등에 관한 장부를 갖추어 두고 기부자가 열람할 수 있도록 하여야 한다.', 4122);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7305, '⑥ 보호관찰소의 장은 매 반기별로 기부금품의 접수현황 및 사용실적 등에 관한 사항을 법무부장관에게 보고하여야 한다', 4122);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7306, '①제16조(보호관찰대상자의 신고의무)ㆍ제17조(준수사항의 부과 및 훈계)ㆍ제18조(주거이전등의 신고)ㆍ제19조(특별준수사항) 및 제20조(응급구호의 범위)의 규정은 법 제3조제2항의 규정에 의한 사회봉사ㆍ수강명령대상자(이하 이 조에서 "사회봉사ㆍ수강명령대상자"라 한다)에 대하여 이를 준용한다.', 4126);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7307, '② 사회봉사ㆍ수강명령 대상자의 준수사항이나 명령 위반에 따른 경고, 구인, 유치, 집행유예 취소 및 보호처분 변경 등에 관하여는 제21조부터 제33조까지 및 제35조를 준용한다. <개정 2009.3.18>', 4126);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7308, '①법 제65조제1항에 따른 갱생보호는 갱생보호를 받을 사람(이하 "갱생보호 대상자"라 한다)이 친족 또는 연고자 등으로부터 도움을 받을 수 없거나 이들의 도움만으로는 충분하지 아니한 경우에 한하여 행한다. <개정 2014.11.19>', 4127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7309, '②갱생보호를 하는 경우에는 미리 갱생보호 대상자로 하여금 자립계획을 수립하게 할 수 있다. <개정 2014.11.19>', 4127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7310, '①법 제65조제1항제1호에 따른 숙식 제공은 생활관 등 갱생보호시설에서 갱생보호 대상자에게 숙소ㆍ음식물 및 의복 등을 제공하고 정신교육을 하는 것으로 한다. <개정 2014.11.19>', 4128);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7311, '②제1항의 규정에 의한 숙식제공은 6월을 초과할 수 없다. 다만, 필요하다고 인정하는 때에는 매회 6월의 범위내에서 3회에 한하여 그 기간을 연장할 수 있다. <개정 2006.12.21>', 4128);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7312, '③제1항의 규정에 의하여 숙식을 제공한 경우에는 법무부장관이 정하는 바에 의하여 소요된 최소한의 비용을 징수할 수 있다.', 4128);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7313, '①법 제65조제1항제4호에 따른 직업훈련은 갱생보호 대상자에게 취업에 필요한 기능훈련을 시키고 자격 취득을 위한 교육을 하는 것으로 한다. <개정 2014.11.19>', 4133);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7314, '②제1항의 규정에 의한 직업훈련은 다른 직업훈련기관에 위탁하여 행할 수 있다.', 4133);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7315, '① 법 제65조제1항제5호에 따른 출소예정자 사전상담은 출소예정자에게 출소 전에 갱생보호의 방법을 안내하고 자립계획 등에 대하여 상담을 실시하는 것으로 한다.', 4135);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7316, '② 갱생보호사업의 허가를 받은 자 또는 법 제71조에 따른 한국법무보호복지공단(이하 "공단"이라 한다)은 제1항의 상담을 위하여 수용기관의 장에게 출소예정자의 수용자 번호를 통보하여 줄 것을 요청할 수 있다. 이 경우 수용기관의 장은 특별한 사유가 없으면 이에 협조하여야 한다.', 4135);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7317, '① 갱생보호사업의 허가를 받은 자 또는 공단은 갱생보호 대상자의 적절한 보호를 위하여 필요한 경우 갱생보호 대상자의 동의를 받아 수용기관의 장에게 다음 각 호의 사항을 통보하여 줄 것을 요청할 수 있다.', 4140);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7318, '② 제1항의 요청을 받은 수용기관의 장은 특별한 사유가 없으면 이에 협조하여야 한다.', 4140);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7319, '①공단은 매년 다음 회계연도의 기금의 운용ㆍ관리계획을 법 제84조제2항의 규정에 의한 사업계획 및 예산에 포함시켜 법무부장관에게 제출하여야 한다.', 4143);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7320, '②제1항의 규정에 의한 운용ㆍ관리계획에는 다음 각호의 사항이 포함되어야 한다.', 4143);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7321, '①공단은 매 회계연도의 기금운용에 관한 결산결과를 법 제84조제3항의 규정에 의한 전년도의 사업실적과 결산에 포함시켜 법무부장관에게 보고하여야 한다.', 4144);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7322, '②제1항의 규정에 의한 결산결과보고에는 다음 각호의 서류를 첨부하여야 한다.', 4144);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7323, '① 심사위원회는 법 제11조에 따른 심사 및 법 제21조에 따른 통보의 접수에 관한 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보, 같은 영 제19조제1호 또는 제4호에 따른 주민등록번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 4145);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7324, '② 보호관찰소의 장은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <개정 2014.6.30, 2014.11.19, 2015.6.22, 2019.11.5, 2022.1.11>', 4145);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7325, '③ 법무부장관은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <신설 2014.8.6>', 4145);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7326, '④ 검사는 법 제32조제4항에 따른 보호관찰대상자의 준수사항 추가, 변경 또는 삭제 청구에 관한 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <개정 2014.6.30, 2014.8.6, 2019.11.5>', 4145);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7327, '⑤ 보호관찰소의 장, 갱생보호사업의 허가를 받은 자 또는 공단은 법 제66조에 따른 갱생보호의 신청 및 조치에 관한 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <신설 2014.6.30, 2014.8.6>', 4145);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7328, '⑥ 공단은 법 제85조에 따른 기부금품의 접수에 관한 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법 시행령」 제19조제1호 또는 제4호에 따른 주민등록번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <신설 2015.6.22>', 4145);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7329, '① 「보호관찰 등에 관한 법률 시행령」(이하 "영"이라 한다) 제6조제1항에 따른 심사위원회의 결정서는 별지 제3호 서식에 의한다.', 4151);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7330, '② 법 제12조제2항에 따른 서면의결은 별지 제3호의2 서식에 의한다.', 4151);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7331, '①심사위원회는 회의록을 작성ㆍ비치하여야 한다.', 4152);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7332, '②제1항의 규정에 의한 회의록에는 회의의 내용을 기재하고 위원장 및 서기가 서명 또는 기명날인하여야 한다. <개정 2009.3.19>', 4152);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7333, '① 영 제6조의2에 따른 교육훈련과정의 분야ㆍ교과목 및 교육 강사의 자격은 별표 1과 같다', 4154);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7334, '② 보호관찰소 소속 공무원은 법 제15조의 사무를 담당하는 날부터 2년 이내에 별표 1의 공통분야의 교과목을 모두 이수하여야 한다. 다만, 법 제15조의 사무를 담당하기 전에 임용전 교육 등을 통해 별표 1의 공통분야의 교과목을 이수한 경우에는 해당 교과목을 이수한 것으로 본다.', 4154);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7335, '③ 법무부장관은 별표 1의 전문분야의 분야별 교과목을 정하여야 하며, 법 제15조의 사무를 담당하는 보호관찰소 소속 공무원은 매년 2개 이상의 전문분야의 분야별 교과목을 이수하여야 한다.', 4154);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7336, '④ 별표 1에 따른 교육훈련과정은 법무연수원 등 국가공무원 교육기관의 교육과정 외 보호관찰소 직무교육과정, 「고등교육법」 제2조에 따른 학교의 학위과정, 「학점인정 등에 관한 법률」 제3조에 따라 평가인정을 받은 학습과정에서도 이수할 수 있다.', 4154);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7337, '⑤ 법무부장관은 보호관찰소 소속 공무원의 전문적 지식을 향상시키기 위하여 별표 1에 따른 교육훈련과정에 대하여 필기시험 또는 구술시험을 실시할 수 있다.', 4154);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7338, '⑥ 보호관찰소의 장은 소속 공무원에 대하여 별표 1에 따른 교육훈련과정에 대한 연간 교육계획을 수립하여야 한다.', 4154);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7339, '① 법무부장관은 판결 전 조사 등 조사업무의 원활한 수행 및 전문성 확보를 위하여 조사관을 양성하여야 한다.', 4155);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7340, '② 조사관은 다음 각 호의 요건을 모두 갖추어야 한다.', 4155);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7341, '③ 필기시험 및 조사서 작성능력 평가 등 조사관 양성에 관하여 필요한 세부 사항은 법무부장관이 정한다.', 4155);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7342, '①법 제18조의 규정에 의한 범죄예방자원봉사위원(이하 "범죄예방위원"이라 한다)은 다음 각호의 요건을 갖춘 자중에서 법무부장관이 위촉한다.', 4156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7343, '②법무부장관은 범죄예방위원이 다음 각호의 1에 해당하는 때에는 해촉할 수 있다.', 4156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7344, '③ 삭제 <2009.11.27>', 4156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7345, '④ 삭제 <2009.11.27>', 4156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7346, null, 4158);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7347, '① 보호관찰소의 장은 보호관찰 대상자 지도, 사회봉사명령 집행감독 등 보호관찰활동을 지원할 사람이 필요한 경우 특별범죄예방자원봉사위원(이하 "특별범죄예방위원"이라 한다)을 위촉할 수 있다.', 4160);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7348, '② 특별범죄예방위원의 위촉기간은 2년으로 한다. 다만, 보호관찰 대상자와 특별한 관계에 있는 사람을 특별범죄예방위원으로 위촉하는 경우 그 위촉기간은 대상자의 보호관찰기간으로 할 수 있다. <개정 2017.2.7>', 4160);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7349, '③ 특별범죄예방위원의 위촉 및 해촉에 관하여 제8조제1항 및 제2항을 준용한다.', 4160);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7350, '①교도소ㆍ구치소ㆍ소년교도소 및 소년원(이하 "수용기관"이라 한다)의 장은 관할심사위원회에 기간경과통보서를 송부한 후에 징역 또는 금고의 형의 선고를 받은 소년(이하 "소년수형자"라 한다) 또는 보호소년을 다른 수용기관에 이송한 경우에는 별지 제6호서식의 이송통지서를 작성하여 관할심사위원회에 송부하여야 한다.', 4164);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7351, '②제1항의 이송통지서를 송부받은 심사위원회는 소년수형자 또는 보호소년이 다른 심사위원회의 관할구역에 있는 수용기관에 이송된 때에는 지체없이 기간경과통보서등 관계서류를 당해심사위원회에 송부하여야 한다.', 4164);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7352, '① 법 제22조에 따른 가석방 심사의 신청은 별지 제7호 서식에 의한다.', 4165);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7353, '② 법 제22조의 규정에 따른 퇴원 또는 임시퇴원 심사의 신청은 별지 제7호의2 서식에 의한다.', 4165);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7354, '①보호관찰소의 장은 법원으로부터 법 제20조제1항에 따른 판결이나 「소년법」 제32조제5항에 따른 결정의 통보를 받거나 심사위원회로부터 제17조에 따른 명단 등의 송부를 받은 때 또는 영 제16조 또는 제18조제2항에 따른 보호관찰대상자의 신고를 접수한 때에는 별지 제11호서식의 보호관찰사건부에 정해진 사항을 기재하고, 개인별로 별지 제12호서식의 보호관찰카드를 작성해야 한다. <개정 2009.3.19, 2009.11.27, 2022.2.7>', 4170);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7355, '② 제1항에 따라 보호관찰카드를 작성하는 경우 보호관찰 대상자의 동일성 식별을 위하여 사진을 촬영할 수 있다. <신설 2009.11.27>', 4170);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7356, '①보호관찰소의 장은 보호관찰대상자별로 담당보호관찰관을 지명하여 보호관찰을 담당하게 한다.', 4172);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7357, '②보호관찰관은 보호관찰대상자로부터 별지 제13호서식의 서약서를 제출받고 보호관찰기간중 준수사항을 이행하도록 지시한다.', 4172);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7358, '③보호관찰관은 보호관찰대상자의 자립과 건전한 사회복귀를 위하여 적절한 지도와 감독 및 원호를 하여야 한다.', 4172);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7359, '④보호관찰관은 그 직무수행에 필요한 경우에는 범죄예방위원 또는 특별범죄예방위원에게 지원을 요청할 수 있다.', 4172);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7360, '⑤보호관찰관은 보호관찰대상자에 대한 지도ㆍ감독ㆍ원호ㆍ조치상황ㆍ주요동태 및 준수사항의 이행여부등 보호관찰경과에 관한 중요한 사항을 보호관찰카드에 기재한다.', 4172);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7361, '⑥보호관찰관은 제4항의 규정에 의하여 지원을 요청한 범죄예방위원 또는 특별범죄예방위원에 대하여 별지 제14호서식의 보호관찰경과통보서를 작성하여 매월 1회 통보하도록 요구할 수 있다.', 4172);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7362, '⑦보호관찰관은 법 제32조제2항제4호의 규정에 의한 주거이전신고를 받은 때에는 지체없이 보호관찰대상자에 대한 보호관찰카드 기타 관계서류를 첨부하여 신주거지를 관할하는 보호관찰소의 장에게 통보하여야 한다.', 4172);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7363, '① 보호관찰소의 장은 법 제34조의 원호활동을 종합적이고 체계적으로 전개하기 위하여 원호협의회를 설치할 수 있다.', 4176);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7364, '② 원호협의회는 5명 이상의 위원으로 구성하되, 보호관찰소의 장은 당연직 위원으로서 위원장이 되고, 위원은 다음 각 호에 해당하는 사람 중에서 위원장이 위촉한다.', 4176);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7365, '③ 위원의 임기는 2년으로 한다.', 4176);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7366, '④ 위원장은 위원의 활동이 부진하거나 품위손상 등 사유로 직무수행이 곤란하다고 인정되는 경우에는 그 위원을 해촉할 수 있다.', 4176);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7367, '⑤ 위원장은 보호관찰 대상자와 그의 가족에 대한 생계, 의료ㆍ교육ㆍ법률 문제 해결, 직업훈련, 취업알선, 기초생활수급자 지정 등 종합적인 지원이 필요한 경우 협의회를 소집하여 원호의 내용, 분야, 규모 등을 협의할 수 있다.', 4176);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7368, '⑥ 위원장은 보호관찰 대상자와 그의 가족에 대한 특정 분야의 원호활동을 각 위원에게 개별적으로 의뢰할 수 있다.', 4176);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7369, '① 법 제36조의2제2항 및 영 제20조의2제1항에 따른 보호관찰 종료사실 통보를 위한 심사 신청서는 별지 제16호의2서식과 같다.', 4177);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7370, '② 심사위원회가 법 제36조의2제2항 및 제3항에 따라 하는 보호관찰 종료사실 통보를 위한 심사 결정은 별지 제3호서식에 따른다.', 4177);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7371, '③ 보호관찰소의 장이 법 제36조의2제2항 및 영 제20조의2제2항에 따라 경찰관서의 장 및 지방자치단체의 장에게 하는 보호관찰 종료사실 통보는 별지 제16호의3서식에 따른다.', 4177);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7372, '①영 제23조 및 제39조제2항에 따른 구인신청은 별지 제20호서식에 의한다. <개정 2009.11.27>', 4181);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7373, '②보호관찰소의 장은 영 제23조에 따라 구인신청을 하는 때에는 별지 제21호서식의 구인장신청부에 정해진 사항을 기재해야 한다. <개정 2022.2.7>', 4181);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7374, '① 영 제36조의2제1항(영 제47조에서 준용하는 경우를 포함한다)에 따른 기부금품의 접수 영수증은 「법인세법 시행규칙」 제82조제7항제3호의3의 별지 제63호의3서식에 따른다. <개정 2015.6.22>', 4201);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7375, '② 영 제36조의2제5항(영 제47조에서 준용하는 경우를 포함한다)에 따른 기부금품의 접수현황 및 사용실적 등에 관한 장부는 별지 제34호서식에 따른다. <개정 2015.6.22>', 4201);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7376, '①영 제41조제1항의 규정에 의하여 갱생보호대상자에 대하여 숙식을 제공하는 시설(이하 "생활관"이라 한다)에는 제49조의 규정에 의한 사무실 및 상담실외에 갱생보호대상자의 숙박에 제공되는 거실ㆍ집회실ㆍ조리장ㆍ식당ㆍ세면장 및 화장실을 설치하여야 한다. 다만, 10인이내의 갱생보호대상자에게 숙식을 제공하는 생활관에서 거실을 식당으로 겸용하는 경우에는 따로 식당을 설치하지 아니할 수 있다.', 4205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7377, '②남녀를 함께 수용하는 생활관의 거실은 남자용과 여자용을 분리하여 설치하여야 한다.', 4205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7378, '③거실ㆍ조리장 및 식당은 보건위생에 적합하여야 하며, 난방ㆍ채광 및 환기가 잘 되도록 설치하여야 한다.', 4205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7379, '①갱생보호대상자로서 갱생보호를 받고자 하는 자는 보호관찰소의 장, 법 제67조에 따라 갱생보호사업의 허가를 받은 자(이하 "사업자"라 한다) 또는 법 제71조에 따른 한국법무보호복지공단(이하 "공단"이라 한다)에 서면으로 신청하여야 한다. <개정 2014.11.19>', 4206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7380, '②관계기관이 보호관찰소의 장, 사업자 또는 공단에 갱생보호대상자에 대한 갱생보호의 신청을 하는 경우에는 갱생보호대상자의 전과 및 처분의 내용, 신상관계, 갱생보호대상자가 희망하는 갱생보호방법등을 기재한 서면으로 하여야 한다.', 4206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7381, '③제1항 및 제2항에 따라 갱생보호의 신청을 받은 보호관찰소의 장, 사업자 또는 공단이 법 제66조제2항에 따라 갱생보호의 필요 여부와 그 방법을 결정함에 있어서는 신청서 및 갱생보호대상자와의 상담 등에 의하여 갱생보호대상자의 전과의 죄질ㆍ연령ㆍ학력ㆍ가정사정ㆍ교우관계 및 자립계획 등을 조사하여야 한다. <개정 2014.11.19>', 4206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7382, '④보호관찰소의 장, 사업자 또는 공단은 갱생보호를 행하지 아니하기로 결정한 때에는 서면으로 그 이유를 신청인에게 통지하여야 한다.', 4206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7383, '①사업자 또는 공단은 생활관에 수용보호한 갱생보호대상자에 대하여 지체없이 갱생자립계획을 수립하게 하여야 한다.', 4208);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7384, '②사업자 또는 공단은 갱생보호대상자에 대하여 교양을 높이고 자율ㆍ자조 및 협동정신과 준법정신을 생활화하여야 하고, 근로의 정신과 습성을 체득하도록 생활지도를 하여야 한다.', 4208);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7385, '①사업자 또는 공단은 갱생보호대상자가 소유하는 금품을 낭비하지 아니하고 갱생자립에 적절하게 사용하도록 지도하여야 한다.', 4210);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7386, '②사업자 또는 공단은 갱생보호대상자로부터 금품의 보관을 의뢰받은 경우에는 금품의 종류 및 수량을 명백히 하여 장부에 기재하고 본인에게 보관증을 교부하여야 한다. 이 경우 현금에 대하여는 갱생보호대상자의 명의로 은행에 예금한 후 예금통장은 본인에게 교부하고 인감은 담당직원이 이를 보관하여야 한다.', 4210);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7387, '③보관된 금품은 갱생보호대상자가 사용용도를 명확히 하여 신청하는 경우에는 본인에게 환급한다.', 4210);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7388, '①생활관에서는 구급약품을 비치하고 시설을 위생적으로 관리하는 등 갱생보호대상자의 건강관리에 유의하여야 한다.', 4211);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7389, '②갱생보호대상자에 대하여는 보건소등 의료시설에서 건강진단을 받도록 하여야 한다.', 4211);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7390, '①갱생보호대상자에게는 독서ㆍ훈화ㆍ교양집회의 개최 기타의 방법으로 그 교양을 높이도록 하여야 한다.', 4214);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7391, '②갱생보호대상자에게는 운동과 여가활동으로 심신의 건강을 유지할 수 있도록 하여야 한다.', 4214);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7392, '①영 제44조제1항의 규정에 의한 직업훈련은 갱생보호대상자의 희망ㆍ적성ㆍ경력등을 고려하여 직업훈련후 취업이 쉬운 분야를 선정하여 훈련을 실시하여야 한다.', 4220);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7393, '②직업훈련을 받은 갱생보호대상자에 대하여는 기술자격을 취득할 수 있도록 최대한 지원하고 취업을 알선하는데 노력하여야 한다.', 4220);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7394, '①갱생보호대상자에 대하여는 기업을 경영하는 범죄예방위원 기타 독지가등과 긴밀하게 연락하여 그 취업을 알선하는데 노력하여야 한다.', 4221);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7395, '②사업자 또는 공단은 그 경영하는 부설작업장에 특별한 사유가 없는 한 갱생보호대상자를 취업시켜야 한다.', 4221);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7396, null, 4223);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7397, '①사업자의 회계연도는 정부의 회계연도에 의한다.', 4226);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7398, '②사업자는 법 제69조의 규정에 의하여 매 회계연도 개시 1월전에 다음 연도의 사업계획 및 예산을, 매 회계연도 종료후 2월이내에 전년도의 사업실적 및 결산서를 법무부장관에게 보고하여야 한다.', 4226);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7399, '③제2항의 규정에 의하여 제출하는 사업계획 및 예산에는 다음 서류를 첨부하여야 한다.', 4226);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7400, '④제2항의 규정에 의하여 제출하는 사업실적 및 결산에는 다음 서류를 첨부하여야 한다.', 4226);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7401, '①공단은 법 제84조제2항의 규정에 의하여 매 회계연도 개시 1월전에 다음 연도의 사업계획 및 예산을 법무부 장관에게 제출하여 승인을 얻어야 하며, 매 회계연도 종료후 2월이내에 전년도의 사업실적 및 결산서를 법무부장관에게 제출하여야 한다.', 4227);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7402, '②공단은 제1항의 규정에 의하여 사업계획 및 예산의 승인을 얻은 후 사업계획을 변경하거나 예산의 관ㆍ항간의 유용 또는 예산외 지출을 하고자 할 때에는 법무부장관의 승인을 얻어야 한다.', 4227);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7403, '③제1항의 사업계획ㆍ예산ㆍ사업실적 및 결산은 지부별로 내용이 명시되어야 한다.', 4227);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7404, null, 4228);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7405, null, 4230);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7406, '①법무부장관은 법 제97조제2항의 규정에 의하여 사업자 또는 공단에 대한 갱생보호사업의 운영실태를 조사한 결과 허가기준에 위반되거나 기타 위법ㆍ부당한 사항이 있는 경우에는 개선을 명할 수 있다.', 4231);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7407, '②제1항의 개선명령을 받은 자는 지체없이 개선조치를 한 후 그 조치내용을 법무부장관에게 서면으로 보고하여야 한다.', 4231);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7408, '①사업자 및 공단은 갱생보호사업의 성과와 재정상태를 정확히 파악하기 위하여 모든 회계거래를 그 발생의 사실에 따라 처리하여야 한다.', 4232);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7409, '②사업자 및 공단이 수익사업을 경영하는 경우에는 갱생보호사업의 회계와 수익사업의 회계를 구분하여 처리하여야 한다. <개정 2014.11.19>', 4232);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7410, null, 4233);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7411, null, 4235);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7412, '① 법무부장관은 제1조의 목적을 달성하기 위하여 필요한 연구ㆍ실험ㆍ조사ㆍ기술개발(이하 "연구개발사업"이라 한다) 및 전문인력 양성 등 소관 분야의 과학기술진흥을 위한 시책을 마련하여 시행할 수 있다.', 4237);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7413, '② 제1항에 따른 연구개발사업은 단계별ㆍ분야별 연구개발과제를 선정하여 「국가연구개발혁신법」 제2조제3호의 기관 또는 단체와 협약을 맺어 실시하게 할 수 있다.', 4237);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7414, '③ 법무부장관은 제2항에 따라 협약을 맺은 기관 또는 단체에 연구개발사업을 실시하는 데 필요한 자금의 전부 또는 일부를 출연하거나 보조할 수 있다.', 4237);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7415, '④ 제3항에 따른 출연금 및 보조금의 지급ㆍ사용 및 관리 등에 필요한 사항은 대통령령으로 정한다.', 4237);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7416, '①검사는 다음 각 호의 어느 하나에 해당하고, 성폭력범죄를 다시 범할 위험성이 있다고 인정되는 사람에 대하여 전자장치를 부착하도록 하는 명령(이하 "부착명령"이라 한다)을 법원에 청구할 수 있다. <개정 2008.6.13, 2010.4.15, 2012.12.18>', 4239);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7417, '② 검사는 미성년자 대상 유괴범죄를 저지른 사람으로서 미성년자 대상 유괴범죄를 다시 범할 위험성이 있다고 인정되는 사람에 대하여 부착명령을 법원에 청구할 수 있다. 다만, 유괴범죄로 징역형의 실형 이상의 형을 선고받아 그 집행이 종료 또는 면제된 후 다시 유괴범죄를 저지른 경우에는 부착명령을 청구하여야 한다. <신설 2009.5.8, 2010.4.15>', 4239);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7418, '③ 검사는 살인범죄를 저지른 사람으로서 살인범죄를 다시 범할 위험성이 있다고 인정되는 사람에 대하여 부착명령을 법원에 청구할 수 있다. 다만, 살인범죄로 징역형의 실형 이상의 형을 선고받아 그 집행이 종료 또는 면제된 후 다시 살인범죄를 저지른 경우에는 부착명령을 청구하여야 한다. <신설 2010.4.15>', 4239);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7419, '④ 검사는 다음 각 호의 어느 하나에 해당하고 강도범죄를 다시 범할 위험성이 있다고 인정되는 사람에 대하여 부착명령을 법원에 청구할 수 있다. <신설 2012.12.18>', 4239);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7420, '⑤ 검사는 다음 각 호의 어느 하나에 해당하고 스토킹범죄를 다시 범할 위험성이 있다고 인정되는 사람에 대하여 부착명령을 법원에 청구할 수 있다. <신설 2023.7.11>', 4239);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7421, '⑥제1항부터 제5항까지의 규정에 따른 부착명령의 청구는 공소가 제기된 특정범죄사건의 항소심 변론종결 시까지 하여야 한다. <개정 2009.5.8, 2010.4.15, 2012.12.18, 2023.7.11>', 4239);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7422, '⑦법원은 공소가 제기된 특정범죄사건을 심리한 결과 부착명령을 선고할 필요가 있다고 인정하는 때에는 검사에게 부착명령의 청구를 요구할 수 있다. <개정 2009.5.8, 2010.4.15, 2012.12.18, 2023.7.11>', 4239);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7423, '⑧제1항부터 제5항까지의 규정에 따른 특정범죄사건에 대하여 판결의 확정 없이 공소가 제기된 때부터 15년이 경과한 경우에는 부착명령을 청구할 수 없다. <개정 2009.5.8, 2010.4.15, 2012.12.18, 2023.7.11>', 4239);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7424, '①검사는 부착명령을 청구하기 위하여 필요하다고 인정하는 때에는 피의자의 주거지 또는 소속 검찰청(지청을 포함한다. 이하 같다) 소재지를 관할하는 보호관찰소(지소를 포함한다. 이하 같다)의 장에게 범죄의 동기, 피해자와의 관계, 심리상태, 재범의 위험성 등 피의자에 관하여 필요한 사항의 조사를 요청할 수 있다.', 4240);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7425, '②제1항의 요청을 받은 보호관찰소의 장은 조사할 보호관찰관을 지명하여야 한다.', 4240);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7426, '③제2항에 따라 지명된 보호관찰관은 지체 없이 필요한 사항을 조사한 후 검사에게 조사보고서를 제출하여야 한다. <개정 2012.12.18>', 4240);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7427, '④ 검사는 제1항의 요청을 받은 보호관찰소의 장에게 조사진행상황의 보고를 요구할 수 있다. <신설 2012.12.18>', 4240);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7428, '⑤검사는 부착명령을 청구함에 있어서 필요한 경우에는 피의자에 대한 정신감정이나 그 밖에 전문가의 진단 등의 결과를 참고하여야 한다. <개정 2012.12.18>', 4240);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7429, '①부착명령 청구사건의 관할은 부착명령 청구사건과 동시에 심리하는 특정범죄사건의 관할에 따른다. <개정 2009.5.8>', 4241);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7430, '②부착명령 청구사건의 제1심 재판은 지방법원 합의부(지방법원지원 합의부를 포함한다. 이하 같다)의 관할로 한다.', 4241);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7431, '①부착명령 청구서에는 다음 각 호의 사항을 기재하여야 한다.', 4242);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7432, '②법원은 부착명령 청구가 있는 때에는 지체 없이 부착명령 청구서의 부본을 피부착명령청구자 또는 그의 변호인에게 송부하여야 한다. 이 경우 특정범죄사건에 대한 공소제기와 동시에 부착명령 청구가 있는 때에는 제1회 공판기일 5일 전까지, 특정범죄사건의 심리 중에 부착명령 청구가 있는 때에는 다음 공판기일 5일 전까지 송부하여야 한다. <개정 2009.5.8>', 4242);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7433, '①법원은 부착명령 청구가 이유 있다고 인정하는 때에는 다음 각 호에 따른 기간의 범위 내에서 부착기간을 정하여 판결로 부착명령을 선고하여야 한다. 다만, 19세 미만의 사람에 대하여 특정범죄를 저지른 경우에는 부착기간 하한을 다음 각 호에 따른 부착기간 하한의 2배로 한다. <개정 2008.6.13, 2010.4.15, 2012.12.18>', 4243);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7434, '② 여러 개의 특정범죄에 대하여 동시에 부착명령을 선고할 때에는 법정형이 가장 중한 죄의 부착기간 상한의 2분의 1까지 가중하되, 각 죄의 부착기간의 상한을 합산한 기간을 초과할 수 없다. 다만, 하나의 행위가 여러 특정범죄에 해당하는 경우에는 가장 중한 죄의 부착기간을 부착기간으로 한다. <신설 2010.4.15>', 4243);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7435, '③ 부착명령을 선고받은 사람은 부착기간 동안 「보호관찰 등에 관한 법률」에 따른 보호관찰을 받는다. <신설 2010.4.15>', 4243);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7436, '④법원은 다음 각 호의 어느 하나에 해당하는 때에는 판결로 부착명령 청구를 기각하여야 한다. <개정 2008.6.13, 2009.5.8, 2010.4.15>', 4243);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7437, '⑤부착명령 청구사건의 판결은 특정범죄사건의 판결과 동시에 선고하여야 한다. <개정 2009.5.8, 2010.4.15>', 4243);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7438, '⑥부착명령 선고의 판결이유에는 요건으로 되는 사실, 증거의 요지 및 적용 법조를 명시하여야 한다. <개정 2010.4.15>', 4243);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7439, '⑦부착명령의 선고는 특정범죄사건의 양형에 유리하게 참작되어서는 아니 된다. <개정 2009.5.8, 2010.4.15>', 4243);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7440, '⑧특정범죄사건의 판결에 대하여 상소 및 상소의 포기ㆍ취하가 있는 때에는 부착명령 청구사건의 판결에 대하여도 상소 및 상소의 포기ㆍ취하가 있는 것으로 본다. 상소권회복 또는 재심의 청구나 비상상고가 있는 때에도 또한 같다. <개정 2009.5.8, 2010.4.15>', 4243);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7441, '⑨제8항에도 불구하고 검사 또는 피부착명령청구자 및 「형사소송법」 제340조ㆍ제341조에 규정된 자는 부착명령에 대하여 독립하여 상소 및 상소의 포기ㆍ취하를 할 수 있다. 상소권회복 또는 재심의 청구나 비상상고의 경우에도 또한 같다. <개정 2010.4.15>', 4243);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7442, '① 법원은 제9조제1항에 따라 부착명령을 선고하는 경우 부착기간의 범위에서 준수기간을 정하여 다음 각 호의 준수사항 중 하나 이상을 부과할 수 있다. 다만, 제4호의 준수사항은 500시간의 범위에서 그 기간을 정하여야 한다. <개정 2010.4.15, 2020.12.15>', 4244);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7443, '② 삭제 <2010.4.15>', 4244);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7444, '③ 제1항에도 불구하고 법원은 성폭력범죄를 저지른 사람(19세 미만의 사람을 대상으로 성폭력범죄를 저지른 사람으로 한정한다) 또는 스토킹범죄를 저지른 사람에 대해서 제9조제1항에 따라 부착명령을 선고하는 경우에는 다음 각 호의 구분에 따라 제1항의 준수사항을 부과하여야 한다. <개정 2023.7.11>', 4244);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7445, '①법원은 제9조에 따라 부착명령을 선고한 때에는 그 판결이 확정된 날부터 3일 이내에 부착명령을 선고받은 자(이하 "피부착명령자"라 한다)의 주거지를 관할하는 보호관찰소의 장에게 판결문의 등본을 송부하여야 한다.', 4245);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7446, '②교도소, 소년교도소, 구치소, 국립법무병원 및 군교도소의 장(이하 "교도소장등"이라 한다)은 피부착명령자가 석방되기 5일 전까지 피부착명령자의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다. <개정 2008.6.13, 2022.1.4>', 4245);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7447, '①부착명령은 검사의 지휘를 받아 보호관찰관이 집행한다.', 4247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7448, '②제1항에 따른 지휘는 판결문 등본을 첨부한 서면으로 한다.', 4247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7449, '①부착명령은 특정범죄사건에 대한 형의 집행이 종료되거나 면제ㆍ가석방되는 날 또는 치료감호의 집행이 종료ㆍ가종료되는 날 석방 직전에 피부착명령자의 신체에 전자장치를 부착함으로써 집행한다. 다만, 다음의 경우에는 각 호의 구분에 따라 집행한다. <개정 2008.6.13, 2009.5.8, 2012.12.18, 2017.10.31>', 4248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7450, '② 제1항제2호에 따라 부착명령을 집행하는 경우 보호관찰소의 장은 피부착명령자를 소환할 수 있으며, 피부착명령자가 소환에 따르지 아니하는 때에는 관할 지방검찰청의 검사에게 신청하여 부착명령 집행장을 발부받아 구인할 수 있다. <신설 2017.10.31>', 4248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7451, '③ 보호관찰소의 장은 제2항에 따라 피부착명령자를 구인한 경우에는 부착명령의 집행을 마친 즉시 석방하여야 한다. <신설 2017.10.31>', 4248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7452, '④부착명령의 집행은 신체의 완전성을 해하지 아니하는 범위 내에서 이루어져야 한다. <개정 2017.10.31>', 4248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7453, '⑤ 부착명령이 여러 개인 경우 확정된 순서에 따라 집행한다. <신설 2010.4.15, 2017.10.31>', 4248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7454, '⑥다음 각 호의 어느 하나에 해당하는 때에는 부착명령의 집행이 정지된다. <개정 2008.6.13, 2010.4.15, 2017.10.31>', 4248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7455, '⑦ 제6항제1호에도 불구하고 구속영장의 집행을 받아 구금된 후에 다음 각 호의 어느 하나에 해당하는 사유로 구금이 종료되는 경우 그 구금기간 동안에는 부착명령이 집행된 것으로 본다. 다만, 제1호 및 제2호의 경우 법원의 판결에 따라 유죄로 확정된 경우는 제외한다. <신설 2017.12.12, 2021.3.16>', 4248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7456, '⑧제6항에 따라 집행이 정지된 부착명령의 잔여기간에 대하여는 다음 각 호의 구분에 따라 집행한다. <개정 2008.6.13, 2010.4.15, 2017.10.31, 2017.12.12>', 4248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7457, '⑨제1항부터 제8항까지 규정된 사항 외에 부착명령의 집행 및 정지에 관하여 필요한 사항은 대통령령으로 정한다. <개정 2010.4.15, 2017.10.31, 2017.12.12>', 4248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7458, '①전자장치가 부착된 자(이하 "피부착자"라 한다)는 전자장치의 부착기간 중 전자장치를 신체에서 임의로 분리ㆍ손상, 전파 방해 또는 수신자료의 변조, 그 밖의 방법으로 그 효용을 해하여서는 아니 된다.', 4249);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7459, '② 피부착자는 특정범죄사건에 대한 형의 집행이 종료되거나 면제ㆍ가석방되는 날부터 10일 이내에 주거지를 관할하는 보호관찰소에 출석하여 대통령령으로 정하는 신상정보 등을 서면으로 신고하여야 한다. <신설 2010.4.15, 2017.12.12>', 4249);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7460, '③피부착자는 주거를 이전하거나 7일 이상의 국내여행을 하거나 출국할 때에는 미리 보호관찰관의 허가를 받아야 한다. <개정 2010.4.15>', 4249);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7461, '① 피부착자가 다음 각 호의 어느 하나에 해당하는 경우에는 법원은 보호관찰소의 장의 신청에 따른 검사의 청구로 1년의 범위에서 부착기간을 연장하거나 제9조의2제1항의 준수사항을 추가 또는 변경하는 결정을 할 수 있다. <개정 2018.3.20>', 4250);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7462, '② 제1항 각 호에 규정된 사항 외의 사정변경이 있는 경우에도 법원은 상당한 이유가 있다고 인정되면 보호관찰소의 장의 신청에 따른 검사의 청구로 제9조의2제1항의 준수사항을 부과, 추가, 변경 또는 삭제하는 결정을 할 수 있다. <개정 2020.12.15>', 4250);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7463, '①보호관찰관은 피부착자의 재범방지와 건전한 사회복귀를 위하여 필요한 지도와 원호를 한다.', 4252);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7464, '②보호관찰관은 전자장치 부착기간 중 피부착자의 소재지 인근 의료기관에서의 치료, 상담시설에서의 상담치료 등 피부착자의 재범방지 및 수치심으로 인한 과도한 고통의 방지를 위하여 필요한 조치를 할 수 있다. <개정 2012.12.18>', 4252);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7465, '③ 보호관찰관은 필요한 경우 부착명령의 집행을 개시하기 전에 교도소장등에게 요청하여 「형의 집행 및 수용자의 처우에 관한 법률」 제63조의 교육, 제64조의 교화프로그램 및 제107조의 징벌에 관한 자료 등 피부착자의 형 또는 치료감호 집행 중의 생활실태를 확인할 수 있는 자료를 확보하고, 형 또는 치료감호의 집행을 받고 있는 피부착자를 면접할 수 있다. 이 경우 교도소장등은 보호관찰관에게 협조하여야 한다. <신설 2012.12.18>', 4252);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7466, '①보호관찰소의 장은 피부착자의 전자장치로부터 발신되는 전자파를 수신하여 그 자료(이하 "수신자료"라 한다)를 보존하여야 한다.', 4253);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7467, '②수신자료는 다음 각 호의 경우 외에는 열람ㆍ조회ㆍ제공 또는 공개할 수 없다. <개정 2009.5.8, 2017.12.12, 2020.2.4>', 4253);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7468, '③ 삭제 <2012.12.18>', 4253);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7469, '④검사 또는 사법경찰관은 제2항제1호에 해당하는 사유로 수신자료를 열람 또는 조회하는 경우 관할 지방법원(군사법원을 포함한다) 또는 지원의 허가를 받아야 한다. 다만, 관할 지방법원 또는 지원의 허가를 받을 수 없는 긴급한 사유가 있는 때에는 수신자료 열람 또는 조회를 요청한 후 지체 없이 그 허가를 받아 보호관찰소의 장에게 송부하여야 한다. <개정 2012.12.18, 2017.12.12, 2021.9.24>', 4253);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7470, '⑤ 검사 또는 사법경찰관은 제4항 단서에 따라 긴급한 사유로 수신자료를 열람 또는 조회하였으나 지방법원 또는 지원의 허가를 받지 못한 경우에는 지체 없이 열람 또는 조회한 수신자료를 폐기하고, 그 사실을 보호관찰소의 장에게 통지하여야 한다. <신설 2012.12.18>', 4253);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7471, '⑥보호관찰소의 장은 다음 각 호의 어느 하나에 해당하는 때에는 수신자료를 폐기하여야 한다. <개정 2010.4.15, 2012.12.18>', 4253);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7472, '⑦제1항부터 제6항까지에서 규정한 사항 외에 수신자료의 보존ㆍ사용ㆍ열람ㆍ조회ㆍ제공ㆍ폐기 등에 관하여 필요한 사항은 대통령령으로 정한다. <개정 2012.12.18, 2017.12.12>', 4253);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7473, '① 보호관찰소의 장은 범죄예방 및 수사에 필요하다고 판단하는 경우 피부착자가 제14조제2항에 따라 신고한 신상정보 및 피부착자에 대한 지도ㆍ감독 중 알게 된 사실 등의 자료를 피부착자의 주거지를 관할하는 경찰관서의 장 등 수사기관에 제공할 수 있다. <개정 2017.12.12>', 4254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7474, '② 수사기관은 범죄예방 및 수사활동 중 인지한 사실이 피부착자 지도ㆍ감독에 활용할 만한 자료라고 판단할 경우 이를 보호관찰소의 장에게 제공할 수 있다. <개정 2017.12.12>', 4254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7475, '③ 보호관찰소의 장은 피부착자가 범죄를 저질렀거나 저질렀다고 의심할만한 상당한 이유가 있을 때에는 이를 수사기관에 통보하여야 한다.', 4254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7476, '④ 수사기관은 체포 또는 구속한 사람이 피부착자임을 알게 된 경우에는 피부착자의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다.', 4254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7477, '⑤ 제1항부터 제4항에 따른 제공 및 통보의 절차와 관리 등에 필요한 사항은 대통령령으로 정한다.', 4254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7478, '① 법무부장관은 보호관찰소의 장 및 보호관찰관이 피부착자의 위치를 확인하고 이동경로를 탐지하며, 전자장치로부터 발신되는 전자파를 수신한 자료를 보존ㆍ사용ㆍ폐기하는 업무를 지원하기 위하여 위치추적 관제센터를 설치하여 운영할 수 있다. <개정 2022.1.4>', 4255);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7479, '② 위치추적 관제센터의 장은 피부착자가 제9조의2제1항 각 호(제4호 및 제6호는 제외한다)에 따른 준수사항 또는 제14조제1항에 따른 효용 유지 의무를 위반하거나, 위반하였다고 의심할만한 상당한 이유가 있고 피부착자에 대한 신속한 지도ㆍ감독을 위하여 긴급히 필요한 경우 지방자치단체의 장에게 「개인정보 보호법」 제2조제7호에 따른 고정형 영상정보처리기기를 통하여 수집된 영상정보의 제공 등 협조를 요청할 수 있다. <신설 2022.1.4, 2023.3.14>', 4255);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7480, '③ 제2항에 따라 피부착자에 관한 영상정보를 제공받은 위치추적 관제센터의 장은 영상정보의 열람이 종료된 후 그 사실을 해당 피부착자에게 통지하여야 한다. <신설 2022.1.4>', 4255);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7481, '④ 제3항에 따른 통지의 시기 및 방법 등 영상정보 열람사실의 통지에 필요한 사항은 법무부령으로 정한다. <신설 2022.1.4>', 4255);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7482, '①보호관찰소의 장 또는 피부착자 및 그 법정대리인은 해당 보호관찰소를 관할하는 심사위원회에 부착명령의 임시해제를 신청할 수 있다. <개정 2020.2.4>', 4256);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7483, '②제1항의 신청은 부착명령의 집행이 개시된 날부터 3개월이 경과한 후에 하여야 한다. 신청이 기각된 경우에는 기각된 날부터 3개월이 경과한 후에 다시 신청할 수 있다.', 4256);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7484, '③제2항에 따라 임시해제의 신청을 할 때에는 신청서에 임시해제의 심사에 참고가 될 자료를 첨부하여 제출하여야 한다. <개정 2020.2.4>', 4256);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7485, '①심사위원회는 임시해제를 심사할 때에는 피부착자의 인격, 생활태도, 부착명령 이행상황 및 재범의 위험성에 대하여 보호관찰관 등 전문가의 의견을 고려하여야 한다. <개정 2012.12.18, 2020.2.4>', 4257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7486, '②심사위원회는 임시해제의 심사를 위하여 필요한 때에는 보호관찰소의 장으로 하여금 필요한 사항을 조사하게 하거나 피부착자나 그 밖의 관계인을 직접 소환ㆍ심문 또는 조사할 수 있다. <개정 2020.2.4>', 4257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7487, '③제2항의 요구를 받은 보호관찰소의 장은 필요한 사항을 조사하여 심사위원회에 통보하여야 한다.', 4257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7488, '④심사위원회는 피부착자가 부착명령이 계속 집행될 필요가 없을 정도로 개선되어 재범의 위험성이 없다고 인정하는 때에는 부착명령의 임시해제를 결정할 수 있다. 이 경우 피부착자로 하여금 주거이전 상황 등을 보호관찰소의 장에게 정기적으로 보고하도록 할 수 있다. <개정 2020.2.4>', 4257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7489, '⑤심사위원회는 부착명령의 임시해제를 하지 아니하기로 결정한 때에는 결정서에 그 이유를 명시하여야 한다. <개정 2020.2.4>', 4257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7490, '⑥ 제4항에 따라 부착명령이 임시해제된 경우에는 제9조제3항에 따른 보호관찰과 제9조의2에 따른 준수사항 및 「아동ㆍ청소년의 성보호에 관한 법률」 제61조제3항에 따른 보호관찰이 임시해제된 것으로 본다. 다만, 심사위원회에서 보호관찰 또는 준수사항 부과가 필요하다고 결정한 경우에는 그러하지 아니하다. <신설 2008.6.13, 2010.4.15, 2012.12.18, 2016.12.20, 2020.2.4>', 4257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7491, '①보호관찰소의 장은 부착명령이 임시해제된 자가 특정범죄를 저지르거나 주거이전 상황 등의 보고에 불응하는 등 재범의 위험성이 있다고 판단되는 때에는 심사위원회에 임시해제의 취소를 신청할 수 있다. 이 경우 심사위원회는 임시해제된 자의 재범의 위험성이 현저하다고 인정될 때에는 임시해제를 취소하여야 한다. <개정 2009.5.8, 2020.2.4>', 4258);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7492, '②제1항에 따라 임시해제가 취소된 자는 잔여 부착명령기간 동안 전자장치를 부착하여야 하고, 부착명령할 때 개시된 보호관찰을 받아야 하며, 부과된 준수사항(준수기간이 종료되지 않은 경우에 한정한다)을 준수하여야 한다. 이 경우 임시해제기간은 부착명령기간에 산입하지 아니한다. <개정 2016.12.20, 2020.2.4>', 4258);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7493, null, 4259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7494, '①피부착명령자는 그 판결이 확정된 후 집행을 받지 아니하고 함께 선고된 특정범죄사건의 형의 시효가 완성되면 그 집행이 면제된다. <개정 2009.5.8>', 4260);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7495, '②부착명령의 시효는 피부착명령자를 체포함으로써 중단된다.', 4260);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7496, null, 4261);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7497, '① 법원은 제21조의2 각 호의 어느 하나에 해당하는 사람이 금고 이상의 선고형에 해당하고 보호관찰명령의 청구가 이유 있다고 인정하는 때에는 2년 이상 5년 이하의 범위에서 기간을 정하여 보호관찰명령을 선고하여야 한다. <개정 2017.12.12>', 4262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7498, '② 법원은 제1항에도 불구하고 제9조제4항제1호에 따라 부착명령 청구를 기각하는 경우로서 제21조의2 각 호의 어느 하나에 해당하여 보호관찰명령을 선고할 필요가 있다고 인정하는 때에는 직권으로 제1항에 따른 기간을 정하여 보호관찰명령을 선고할 수 있다. <신설 2017.12.12>', 4262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7499, '① 법원은 제21조의3에 따라 보호관찰명령을 선고하는 경우 제9조의2제1항 각 호의 준수사항 중 하나 이상을 부과할 수 있다. 다만, 제9조의2제1항제4호의 준수사항은 300시간의 범위에서 그 기간을 정하여야 한다. <개정 2019.4.16>', 4263);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7500, '② 제1항 본문에도 불구하고 법원은 성폭력범죄를 저지른 사람(19세 미만의 사람을 대상으로 성폭력범죄를 저지른 사람으로 한정한다) 또는 스토킹범죄를 저지른 사람에 대해서는 제21조의3에 따라 보호관찰명령을 선고하는 경우 제9조의2제1항제3호를 포함하여 준수사항을 부과하여야 한다. <신설 2019.4.16, 2023.7.11>', 4263);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7501, '① 보호관찰대상자는 특정범죄사건에 대한 형의 집행이 종료되거나 면제ㆍ가석방되는 날부터 10일 이내에 주거지를 관할하는 보호관찰소에 출석하여 서면으로 신고하여야 한다.', 4265);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7502, '② 보호관찰대상자는 주거를 이전하거나 7일 이상의 국내여행을 하거나 출국할 때에는 미리 보호관찰관의 허가를 받아야 한다.', 4265);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7503, '① 보호관찰대상자가 정당한 사유 없이 제21조의4 또는 「보호관찰 등에 관한 법률」 제32조에 따른 준수사항을 위반하거나 제21조의6에 따른 의무를 위반한 때에는 법원은 보호관찰소의 장의 신청에 따른 검사의 청구로 다음 각 호의 결정을 할 수 있다. <개정 2023.7.11>', 4266);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7504, '② 제1항 각 호의 처분은 병과할 수 있다.', 4266);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7505, '③ 제1항에 규정된 사항 외의 사정변경이 있는 경우에도 법원은 상당한 이유가 있다고 인정하면 보호관찰소의 장의 신청에 따른 검사의 청구로 제21조의4에 따른 준수사항을 추가, 변경 또는 삭제하는 결정을 할 수 있다.', 4266);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7506, '①제9조에 따른 부착명령 판결을 선고받지 아니한 특정 범죄자로서 형의 집행 중 가석방되어 보호관찰을 받게 되는 자는 준수사항 이행 여부 확인 등을 위하여 가석방기간 동안 전자장치를 부착하여야 한다. 다만, 심사위원회가 전자장치 부착이 필요하지 아니하다고 결정한 경우에는 그러하지 아니하다. <개정 2009.5.8, 2012.12.18>', 4268);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7507, '② 심사위원회는 특정범죄 이외의 범죄로 형의 집행 중 가석방되어 보호관찰을 받는 사람의 준수사항 이행 여부 확인 등을 위하여 가석방 예정자의 범죄내용, 개별적 특성 등을 고려하여 가석방 기간의 전부 또는 일부의 기간을 정하여 전자장치를 부착하게 할 수 있다. <신설 2020.2.4>', 4268);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7508, '③ 심사위원회는 제1항 및 제2항의 결정을 위하여 가석방 예정자에 대한 전자장치 부착의 필요성과 적합성 여부 등을 조사하여야 한다. <신설 2020.2.4>', 4268);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7509, '④심사위원회는 제1항 및 제2항에 따라 전자장치를 부착하게 되는 자의 주거지를 관할하는 보호관찰소의 장에게 가석방자의 인적사항 등 전자장치 부착에 필요한 사항을 즉시 통보하여야 한다. <개정 2020.2.4>', 4268);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7510, '⑤교도소장등은 제1항 및 제2항에 따른 가석방 예정자가 석방되기 5일 전까지 그의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다. <개정 2020.2.4>', 4268);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7511, '①「치료감호 등에 관한 법률」 제37조에 따른 치료감호심의위원회(이하 "치료감호심의위원회"라 한다)는 제9조에 따른 부착명령 판결을 선고받지 아니한 특정 범죄자로서 치료감호의 집행 중 가종료 또는 치료위탁되는 피치료감호자나 보호감호의 집행 중 가출소되는 피보호감호자(이하 "가종료자등"이라 한다)에 대하여 「치료감호 등에 관한 법률」 또는 「사회보호법」(법률 제7656호로 폐지되기 전의 법률을 말한다)에 따른 준수사항 이행 여부 확인 등을 위하여 보호관찰 기간의 범위에서 기간을 정하여 전자장치를 부착하게 할 수 있다. <개정 2008.6.13, 2009.5.8, 2010.4.15, 2023.7.11>', 4269);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7512, '②치료감호심의위원회는 제1항에 따라 전자장치 부착을 결정한 경우에는 즉시 피부착결정자의 주거지를 관할하는 보호관찰소의 장에게 통보하여야 한다.', 4269);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7513, '③치료감호시설의 장ㆍ보호감호시설의 장 또는 교도소의 장은 가종료자등이 가종료 또는 치료위탁되거나 가출소되기 5일 전까지 가종료자등의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다. <개정 2010.4.15>', 4269);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7514, '①전자장치 부착은 보호관찰관이 집행한다.', 4270);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7515, '②전자장치는 다음 각 호의 어느 하나에 해당하는 때 석방 직전에 부착한다. <개정 2010.4.15, 2017.12.12>', 4270);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7516, '③전자장치 부착집행 중 보호관찰 준수사항 위반으로 유치허가장의 집행을 받아 유치된 때에는 부착집행이 정지된다. 이 경우 심사위원회가 보호관찰소의 장의 가석방 취소신청을 기각한 날 또는 법무부장관이 심사위원회의 허가신청을 불허한 날부터 그 잔여기간을 집행한다.', 4270);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7517, null, 4271);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7518, '①법원은 특정범죄를 범한 자에 대하여 형의 집행을 유예하면서 보호관찰을 받을 것을 명할 때에는 보호관찰 기간의 범위 내에서 기간을 정하여 준수사항의 이행여부 확인 등을 위하여 전자장치를 부착할 것을 명할 수 있다. <개정 2009.5.8, 2023.7.11>', 4274);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7519, '②법원은 제1항에 따른 부착명령기간 중 소재지 인근 의료기관에서의 치료, 지정 상담시설에서의 상담치료 등 대상자의 재범방지를 위하여 필요한 조치들을 과할 수 있다.', 4274);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7520, '③법원은 제1항에 따른 전자장치 부착을 명하기 위하여 필요하다고 인정하는 때에는 피고인의 주거지 또는 그 법원의 소재지를 관할하는 보호관찰소의 장에게 범죄의 동기, 피해자와의 관계, 심리상태, 재범의 위험성 등 피고인에 관하여 필요한 사항의 조사를 요청할 수 있다.', 4274);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7521, '①부착명령은 전자장치 부착을 명하는 법원의 판결이 확정된 때부터 집행한다.', 4275);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7522, '②부착명령의 집행 중 보호관찰 준수사항 위반으로 유치허가장의 집행을 받아 유치된 때에는 부착명령 집행이 정지된다. 이 경우 검사가 보호관찰소의 장의 집행유예 취소신청을 기각한 날 또는 법원이 검사의 집행유예취소청구를 기각한 날부터 그 잔여기간을 집행한다.', 4275);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7523, null, 4276);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7524, '① 법원은 「형사소송법」 제98조제9호에 따른 보석조건으로 피고인에게 전자장치 부착을 명할 수 있다.', 4278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7525, '② 법원은 제1항에 따른 전자장치 부착을 명하기 위하여 필요하다고 인정하면 그 법원의 소재지 또는 피고인의 주거지를 관할하는 보호관찰소의 장에게 피고인의 직업, 경제력, 가족상황, 주거상태, 생활환경 및 피해회복 여부 등 피고인에 관한 사항의 조사를 의뢰할 수 있다.', 4278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7526, '③ 제2항의 의뢰를 받은 보호관찰소의 장은 지체 없이 조사하여 서면으로 법원에 통보하여야 하며, 조사를 위하여 필요한 경우에는 피고인이나 그 밖의 관계인을 소환하여 심문하거나 소속 보호관찰관에게 필요한 사항을 조사하게 할 수 있다.', 4278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7527, '④ 보호관찰소의 장은 제3항의 조사를 위하여 필요하다고 인정하면 국공립 기관이나 그 밖의 단체에 사실을 알아보거나 관련 자료의 열람 등 협조를 요청할 수 있다.', 4278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7528, '① 법원은 제31조의2제1항에 따라 전자장치 부착을 명한 경우 지체 없이 그 결정문의 등본을 피고인의 주거지를 관할하는 보호관찰소의 장에게 송부하여야 한다.', 4279);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7529, '② 제31조의2제1항에 따라 전자장치 부착명령을 받고 석방된 피고인은 법원이 지정한 일시까지 주거지를 관할하는 보호관찰소에 출석하여 신고한 후 보호관찰관의 지시에 따라 전자장치를 부착하여야 한다.', 4279);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7530, '③ 보호관찰소의 장은 제31조의2제1항에 따른 피고인의 보석조건 이행 여부 확인을 위하여 적절한 조치를 하여야 한다.', 4279);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7531, '④ 전자장치 부착 집행의 절차 및 방법 등에 관한 사항은 대통령령으로 정한다.', 4279);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7532, '① 보호관찰소의 장은 제31조의2제1항에 따른 피고인의 보석조건 이행 상황을 법원에 정기적으로 통지하여야 한다.', 4280);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7533, '② 보호관찰소의 장은 피고인이 제31조의2제1항에 따른 전자장치 부착명령을 위반한 경우 및 전자장치 부착을 통하여 피고인에게 부과된 주거의 제한 등 「형사소송법」에 따른 다른 보석조건을 위반하였음을 확인한 경우 지체 없이 법원과 검사에게 이를 통지하여야 한다.', 4280);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7534, '③ 제2항에 따른 통지를 받은 법원은 「형사소송법」 제102조에 따라 피고인의 보석조건을 변경하거나 보석을 취소하는 경우 이를 지체 없이 보호관찰소의 장에게 통지하여야 한다.', 4280);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7535, '④ 제1항부터 제3항까지의 규정에 따른 통지의 절차 및 방법 등에 관한 사항은 대통령령으로 정한다.', 4280);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7536, null, 4281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7537, '① 법원은 「스토킹범죄의 처벌 등에 관한 법률」 제9조제1항제3호의2에 따른 잠정조치(이하 이 장에서 "잠정조치"라 한다)로 전자장치의 부착을 결정한 경우 그 결정문의 등본을 스토킹행위자의 사건 수사를 관할하는 경찰관서(이하 이 장에서 "관할경찰관서"라 한다)의 장과 스토킹행위자의 주거지를 관할하는 보호관찰소(이하 이 장에서 "보호관찰소"라 한다)의 장에게 지체 없이 송부하여야 한다.', 4282);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7538, '② 잠정조치 결정을 받은 스토킹행위자는 법원이 지정한 일시까지 보호관찰소에 출석하여 대통령령으로 정하는 신상정보 등을 서면으로 신고한 후 보호관찰관의 지시에 따라 전자장치를 부착하여야 한다.', 4282);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7539, '③ 보호관찰소의 장은 스토킹행위자가 제2항에 따라 전자장치를 부착하면 관할경찰관서의 장에게 이를 즉시 통지하여야 하고, 관할경찰관서의 장은 「스토킹범죄의 처벌 등에 관한 법률」 제9조제1항제2호 및 제3호의2에 따른 스토킹행위자의 잠정조치 이행 여부를 확인하기 위하여 피해자에 대한 다음 각 호의 사항을 보호관찰소의 장에게 즉시 통지하여야 한다.', 4282);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7540, '④ 보호관찰소의 장은 스토킹행위자가 다음 각 호의 어느 하나에 해당하는 경우 그 사실을 관할경찰관서의 장에게 즉시 통지하여야 한다.', 4282);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7541, '⑤ 관할경찰관서의 장은 제4항에 따른 통지가 있는 경우 즉시 스토킹행위자가 소재한 현장에 출동하는 등의 방법으로 그 사유를 확인하고, 「스토킹범죄의 처벌 등에 관한 법률」 제9조제1항제4호에 따른 유치 신청 등 피해자 보호에 필요한 적절한 조치를 하여야 한다.', 4282);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7542, '⑥ 관할경찰관서의 장은 「스토킹범죄의 처벌 등에 관한 법률」 제11조제5항에 따라 잠정조치 결정이 효력을 상실하는 때에는 보호관찰소의 장에게 이를 지체 없이 통지하여야 한다.', 4282);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7543, '⑦ 법원은 잠정조치의 연장ㆍ변경ㆍ취소 결정을 하는 경우 관할경찰관서의 장과 보호관찰소의 장에게 이를 지체 없이 통지하여야 한다.', 4282);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7544, '⑧ 제1항부터 제7항까지에 따른 전자장치 부착의 집행 등에 필요한 사항은 대통령령으로 정한다.', 4282);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7545, null, 4283);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7546, '① 보호관찰소의 장은 제31조의6제2항에 따라 전자장치를 부착한 스토킹행위자의 전자장치로부터 발신되는 전자파를 수신하여 그 자료(이하 "스토킹행위자 수신자료"라 한다)를 보존하여야 한다.', 4284);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7547, '② 스토킹행위자 수신자료는 다음 각 호의 경우 외에는 열람ㆍ조회ㆍ제공 또는 공개할 수 없다.', 4284);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7548, '③ 검사 또는 사법경찰관이 제2항제1호에 해당하는 사유로 스토킹행위자 수신자료를 열람 또는 조회하는 경우 그 절차에 관하여는 제16조제4항 및 제5항을 준용한다.', 4284);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7549, '④ 보호관찰소의 장은 다음 각 호의 어느 하나에 해당하는 때에는 스토킹행위자 수신자료를 폐기하여야 한다.', 4284);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7550, '①전자장치 부착기간은 이를 집행한 날부터 기산하되, 초일은 시간을 계산함이 없이 1일로 산정한다.', 4285);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7551, '② 다음 각 호의 어느 하나에 해당하는 기간은 전자장치 부착기간에 산입하지 아니한다. 다만, 보호관찰이 부과된 사람의 전자장치 부착기간은 보호관찰 기간을 초과할 수 없다. <개정 2018.3.20, 2023.7.11>', 4285);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7552, null, 4286);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7553, '① 법무부장관은 이 법에 따른 부착명령 또는 보호관찰명령의 집행이 종료된 사람의 재범 여부를 조사하고 부착명령 또는 보호관찰명령의 효과를 평가하기 위하여 필요한 경우에는 그 집행이 종료된 때부터 5년 동안 관계 기관에 그 사람에 관한 범죄경력자료와 수사경력자료에 대한 조회를 요청할 수 있다.', 4288);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7554, '② 제1항의 요청을 받은 관계 기관의 장은 정당한 사유 없이 이를 거부하여서는 아니 된다.', 4288);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7555, '①전자장치 부착 업무를 담당하는 자가 정당한 사유 없이 피부착자의 전자장치를 해제하거나 손상한 때에는 1년 이상의 유기징역에 처한다.', 4291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7556, '②전자장치 부착 업무를 담당하는 자가 금품을 수수ㆍ요구 또는 약속하고 제1항의 죄를 범한 때에는 2년 이상의 유기징역에 처한다.', 4291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7557, '③수신자료(스토킹행위자 수신자료를 포함한다)를 관리하는 자가 제16조제2항 또는 제31조의8제2항을 위반한 때에는 1년 이상의 유기징역에 처한다. <개정 2023.7.11>', 4291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7558, '① 타인으로 하여금 부착명령 또는 보호관찰명령을 받게 할 목적으로 공무소 또는 공무원에 대하여 허위의 사실을 신고하거나 「형법」 제152조제1항의 죄를 범한 때에는 10년 이하의 징역에 처한다. <개정 2012.12.18>', 4292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7559, '②제2장의 부착명령 또는 보호관찰명령 청구사건에 관하여 피부착명령청구자 또는 피보호관찰명령청구자를 모해할 목적으로 「형법」 제154조ㆍ제233조 또는 제234조(허위작성진단서의 행사에 한한다)의 죄를 범한 때에는 10년 이하의 징역에 처한다. 이 경우 10년 이하의 자격정지를 병과한다. <개정 2012.12.18, 2014.1.7>', 4292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7560, '① 피부착자가 제14조제1항(제27조 및 제31조에 따라 준용되는 경우를 포함한다)을 위반하여 전자장치의 부착기간 중 전자장치를 신체에서 임의로 분리ㆍ손상, 전파 방해 또는 수신자료의 변조, 그 밖의 방법으로 그 효용을 해한 때에는 7년 이하의 징역 또는 2천만원 이하의 벌금에 처한다. <개정 2017.12.12>', 4293);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7561, '② 제1항의 미수범은 처벌한다. <신설 2017.12.12>', 4293);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7562, '① 피부착자 또는 보호관찰대상자가 제9조의2제1항제3호 또는 제4호의 준수사항을 정당한 사유 없이 위반한 때에는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다. <개정 2012.12.18, 2020.12.15>', 4294);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7563, '② 피부착자 또는 보호관찰대상자가 정당한 사유 없이 「보호관찰 등에 관한 법률」 제32조제2항 또는 제3항에 따른 준수사항을 위반하여 같은 법 제38조에 따른 경고를 받은 후 다시 정당한 사유 없이 같은 법 제32조제2항 또는 제3항에 따른 준수사항을 위반한 경우 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <신설 2012.12.18, 2020.12.15>', 4294);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7564, '③ 피부착자 또는 보호관찰대상자가 제9조의2제1항제1호ㆍ제2호ㆍ제2호의2ㆍ제5호 또는 제6호의 준수사항을 정당한 사유 없이 위반한 때에는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 2010.4.15, 2012.12.18, 2020.12.15>', 4294);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7565, null, 4296);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7566, '① 법무부장관은 법 제3조의2제2항에 따라 협약을 맺은 기관 또는 단체(이하 "연구개발기관"이라 한다)에 같은 조 제3항에 따라 출연금을 지급하는 경우 연구개발사업의 규모, 착수시기 및 정부의 재정 사정 등을 고려해 한꺼번에 지급하거나 나누어 지급할 수 있다.', 4298);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7567, '② 제1항에 따라 출연금을 지급받은 연구개발기관은 그 출연금을 별도의 계정(計定)을 설정하여 관리해야 한다.', 4298);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7568, '③ 제1항에 따라 출연금을 지급받은 연구개발기관은 그 출연금을 「국가연구개발혁신법 시행령」 별표 2에 따른 연구개발비 사용용도로만 사용해야 한다.', 4298);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7569, '④ 법무부장관은 연구개발기관이 정당한 사유 없이 제3항에 따른 용도 외의 용도로 제1항에 따라 지급받은 출연금을 사용한 경우에는 해당 금액을 회수해야 한다.', 4298);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7570, '⑤ 법 제3조의2제4항에 따른 보조금의 지급ㆍ사용 및 관리에 관하여는 「보조금 관리에 관한 법률」에서 정하는 바에 따른다.', 4298);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7571, '① 검사는 법 제6조제1항에 따라 보호관찰소(지소를 포함한다. 이하 같다)의 장에게 조사를 요청할 때에는 법 제5조제1항부터 제5항까지의 규정에 따른 전자장치를 부착하도록 하는 명령(이하 "부착명령"이라 한다)을 청구하는 피의자의 인적사항 및 범죄사실의 요지를 통보해야 한다. 이 경우 법무부령으로 정하는 참고자료를 보낼 수 있다. <개정 2009.7.30, 2010.7.12, 2013.5.31, 2024.1.9>', 4299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7572, '② 보호관찰소의 장은 법 제6조제1항의 조사를 위해 교도소ㆍ소년교도소ㆍ구치소ㆍ군교도소의 장, 경찰서장, 국립법무병원장(이하 "수용기관의 장"이라 한다)에게 협조를 요청할 수 있다. 이 경우 수용기관의 장은 특별한 사유가 없으면 협조해야 한다. <개정 2024.1.9>', 4299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7573, '① 법 제8조제1항제1호에서 "그 밖에 피부착명령청구자를 특정할 수 있는 사항"이란 피부착명령청구자의 주민등록번호, 직업, 주거, 등록기준지를 말하고, 같은 항 제4호에서 "대통령령으로 정하는 사항"이란 피부착명령청구자의 죄명을 말한다. <개정 2010.7.12>', 4300);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7574, '② 검사가 공소 제기와 동시에 부착명령을 청구할 경우에는 공소장에 부착명령 청구의 원인이 되는 사실과 적용 법조문을 추가하여 적는 것으로 부착명령 청구서를 대신할 수 있다.', 4300);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7575, '① 보호관찰관은 피부착명령자에 대한 판결문 등본, 법 제12조제2항의 부착명령 집행을 지휘한 서면, 그 밖의 관련 서류를 확인한 후 부착명령을 집행하여야 한다.', 4302);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7576, '② 보호관찰관은 법 제13조제1항에 따라 부착명령을 집행하기에 앞서 피부착명령자에게 법 제14조와 이 영에 따른 피부착자의 의무사항 및 법 제38조 및 제39조에 따른 벌칙에 관한 사항을 알려야 한다.', 4302);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7577, '③ 부착명령은 다음 각 호의 방법으로 집행한다. <개정 2018.2.13>', 4302);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7578, '④ 보호관찰소의 장은 소속 보호관찰관이 부착명령을 집행하기 위하여 필요하면 수용기관의 장에게 협조를 요청할 수 있다. 이 경우 수용기관의 장은 특별한 사유가 없으면 협조하여야 한다.', 4302);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7579, '⑤ 수용기관의 장은 피부착자가 부착명령의 집행 중 「형법」 제70조에 따른 노역장유치의 집행을 받게 된 경우 피부착자의 주거지를 관할하는 보호관찰소의 장에게 통보하여 담당 보호관찰관이 전자장치를 분리하여 회수하도록 하여야 하며, 피부착자가 노역장유치의 집행을 마치고 석방되기 전에 피부착자의 주거지를 관할하는 보호관찰소의 장에게 석방예정 사실을 통보하여 석방 전에 담당 보호관찰관이 피부착자에게 전자장치를 부착할 수 있도록 하여야 한다. <신설 2013.5.31>', 4302);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7580, '① 보호관찰관은 법 제13조제6항에 따라 부착명령의 집행이 정지되면 지체 없이 전자장치를 분리하여 회수하여야 한다. 이 경우 부착명령의 집행기간은 신체에서 부착장치를 분리한 때부터 정지된다. <개정 2010.7.12, 2018.6.12>', 4303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7581, '② 수용기관의 장은 법 제13조제6항 각 호의 사유로 피부착자가 구금된 경우에는 즉시 그의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다. <개정 2010.7.12, 2018.6.12>', 4303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7582, '③ 보호관찰관은 법 제13조제8항에 따른 부착명령의 잔여기간 집행사유가 발생한 경우 다시 전자장치를 부착하여야 한다. 이 경우 부착명령의 집행기간은 신체에 부착장치를 부착한 때부터 진행한다. <개정 2010.7.12, 2018.6.12>', 4303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7583, '④ 수용기관의 장은 법 제13조제8항제1호에 따른 부착명령의 잔여기간 집행사유가 발생한 경우 구금을 해제하기 전에 피부착명령자의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다. <개정 2010.7.12, 2018.6.12>', 4303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7584, '⑤ 수용기관의 장은 법 제13조제8항제2호 및 제3호에 따른 부착명령의 잔여기간 집행사유가 발생한 경우 부착명령의 집행이 정지된 사람이 석방되기 5일 전까지 그의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다. <신설 2010.7.12, 2018.6.12>', 4303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7585, '① 보호관찰관은 피부착자의 치료, 전자장치의 교체, 그 밖에 전자장치를 일시 분리할 필요가 있는 경우 보호관찰소의 장의 승인을 받아 전자장치의 전부 또는 일부를 피부착자의 신체 또는 주거에서 일시적으로 분리할 수 있다. 다만, 승인을 받을 시간적 여유가 없을 경우에는 분리한 후 지체 없이 보고하여야 한다.', 4305);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7586, '② 보호관찰관은 제1항의 일시 분리 사실을 대장에 적고 그 대장을 비치하여야 한다.', 4305);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7587, null, 4306);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7588, '① 법 제14조제2항에서 "대통령령으로 정하는 신상정보 등"이란 제15조의2제1항제1호부터 제8호까지의 사항 및 그 밖에 피부착자에 대한 지도ㆍ감독에 필요한 사항을 말한다. <개정 2018.6.12>', 4307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7589, '② 피부착자는 법 제14조제3항에 따른 주거이전 등의 허가를 받으려고 할 때에는 본인의 성명, 주거, 주거이전 예정지나 국내여행 예정지 또는 출국 예정지, 주거이전 이유나 국내여행 목적 또는 출국 목적, 주거이전 일자나 국내여행 기간 또는 출국 기간 등을 적은 허가신청서와 소명자료를 보호관찰소에 출석하여 제출하여야 한다.', 4307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7590, '③ 제2항에 따른 허가 신청을 받은 보호관찰관은 신청일부터 7일 이내에 주거이전 예정지나 국내여행 예정지 또는 출국 예정지, 주거이전 이유나 국내여행 목적, 출국의 목적 또는 법 제9조의2 및 「보호관찰 등에 관한 법률」 제32조에 따른 준수사항 이행 정도 등을 종합적으로 고려하여 허가 여부를 결정하여야 한다. <개정 2013.5.31>', 4307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7591, '④ 보호관찰관은 제3항에 따라 피부착자의 출국 허가를 결정할 경우 피부착자가 다음 각 호의 어느 하나에 해당하는 경우에는 출국을 허가하지 아니할 수 있다. 다만, 제1호의 경우에는 출국을 허가하지 아니하여야 한다. <신설 2013.5.31>', 4307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7592, '⑤ 보호관찰관은 제3항에 따라 피부착자의 출국 허가를 결정할 경우 그 허가기간을 출국일부터 3개월 이내의 범위에서 정하되, 불가피한 경우에만 이를 초과하여 정할 수 있다. <신설 2013.5.31>', 4307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7593, '⑥ 피부착자는 주거이전 허가를 받아 다른 보호관찰소의 관할 구역으로 주거를 이전한 경우 3일 이내에 새로운 주거지를 관할하는 보호관찰소에 출석하여 제1항의 신고를 하여야 한다. <개정 2013.5.31>', 4307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7594, '⑦ 보호관찰소의 장은 소속 보호관찰관이 제3항에 따라 피부착자에게 출국을 허가한 경우 법무부장관에게 피부착자의 출입국 사실을 통보하여 줄 것을 요청하여야 한다. <개정 2013.5.31>', 4307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7595, '⑧ 법무부장관은 제7항에 따른 요청을 받은 경우에는 피부착자의 출입국 시 지체 없이 그 사실을 보호관찰소의 장에게 통보하여야 한다. <개정 2013.5.31>', 4307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7596, '⑨ 제3항에 따른 출국 허가를 받아 출국했던 피부착자는 입국한 후 지체 없이 관할 보호관찰소에 출석하여 전자장치가 정상적으로 작동하는지를 확인받아야 한다. <개정 2013.5.31>', 4307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7597, '① 보호관찰소의 장은 법 제14조의2에 따라 부착기간의 연장을 신청하거나 같은 조 또는 법 제14조의3에 따라 준수사항의 부과ㆍ추가ㆍ변경ㆍ삭제를 신청하는 경우에는 다음 각 호의 사항을 적은 서면으로 신청해야 한다. <개정 2021.9.14>', 4308);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7598, '② 보호관찰소의 장은 제1항의 신청을 할 때 신청사유를 소명할 수 있는 자료를 제출하여야 한다.', 4308);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7599, '③ 법원은 법 제14조의2 또는 제14조의3에 따른 청구의 심리를 위하여 필요한 경우에는 담당 보호관찰관을 출석시켜 의견을 들을 수 있고, 피부착자 또는 피부착명령자를 소환하여 심문하거나 필요한 사항을 확인할 수 있다. <개정 2021.9.14>', 4308);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7600, '① 법무부장관은 다음 각 호의 시설 또는 단체를 지정하여 법 제15조제2항의 치료 및 상담치료 등을 실시하게 할 수 있다. <개정 2009.7.30, 2010.12.29, 2017.5.29>', 4309);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7601, '② 법무부장관은 제1항의 치료 및 상담치료 등에 대하여 예산의 범위에서 비용의 전부 또는 일부를 지급할 수 있다.', 4309);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7602, '③ 법무부장관은 제1항의 치료 및 상담치료에 필요한 프로그램의 개발과 전문인력의 양성을 위하여 노력하여야 한다.', 4309);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7603, '④ 법무부장관은 제1항에 따른 지정을 받은 시설 또는 단체가 치료 및 상담치료 등을 실시하기에 부적당한 경우 그 지정을 취소할 수 있다. <신설 2010.7.12>', 4309);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7604, '① 검사는 법 제16조제4항 본문에 따라 수신자료를 열람 또는 조회하려는 경우에는 관할 법원에 피부착자에 대한 수신자료의 열람 또는 조회를 허가하여 줄 것을 청구할 수 있다.', 4311);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7605, '② 사법경찰관은 법 제16조제4항 본문에 따라 수신자료를 열람 또는 조회하려는 경우 검사에게 피부착자에 대한 수신자료의 열람 또는 조회에 대한 허가를 신청하고, 검사는 관할 법원에 그 허가를 청구할 수 있다.', 4311);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7606, '③ 제1항 및 제2항에 따른 수신자료 열람 또는 조회의 허가 청구 또는 신청은 피부착자의 인적사항, 수신자료 제공기관, 청구ㆍ신청 사유 및 필요한 자료의 범위를 적은 서면으로 하여야 한다.', 4311);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7607, '④ 검사 또는 사법경찰관은 법 제16조제4항 본문에 따라 수신자료를 열람 또는 조회하는 경우에는 보호관찰소의 장(위치추적 관제센터의 장을 포함한다. 이하 제14조의3부터 제14조의6까지에서 같다)에게 관할 법원의 허가서 사본을 내주어야 한다. <개정 2021.9.14, 2024.1.9>', 4311);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7608, '① 검사 또는 사법경찰관은 법 제16조제4항 단서에 따라 수신자료의 열람 또는 조회를 요청하는 경우에는 보호관찰소의 장에게 다음 각 호의 서류를 팩스 등의 방법으로 제시하여야 한다.', 4312);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7609, '② 검사는 제1항에 따른 긴급 수신자료 열람 또는 조회를 요청한 경우에는 지체 없이 관할 법원에 그 허가를 청구하여야 한다.', 4312);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7610, '③ 사법경찰관은 제1항에 따른 긴급 수신자료 열람 또는 조회를 요청한 경우에는 지체 없이 검사에게 긴급 수신자료 열람 또는 조회에 대한 허가를 신청하고, 검사는 관할 법원에 그 허가를 청구할 수 있다.', 4312);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7611, '④ 검사 또는 사법경찰관이 법 제16조제4항 단서에 따라 보호관찰소의 장에게 송부하여야 할 자료는 관할 법원의 허가서 사본으로 한다.', 4312);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7612, '① 검사 또는 사법경찰관은 법 제16조제4항과 제5항에 따른 수신자료의 열람 또는 조회 허가 신청 및 청구 현황, 수신자료 열람 또는 조회 사실을 적은 대장을 3년간 소속 기관에 갖추어 두어야 한다.', 4313);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7613, '② 보호관찰소의 장은 검사 또는 사법경찰관에게 수신자료를 열람 또는 조회하게 하였을 때에는 해당 수신자료 열람 또는 조회 사실을 적은 대장과 수신자료 열람ㆍ조회 요청서 등 관련 자료를 3년간 갖추어 두어야 한다.', 4313);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7614, '③ 검사가 제14조의3제3항에 따른 사법경찰관의 허가 신청을 기각하면 사법경찰관은 지체 없이 열람 또는 조회한 수신자료를 폐기하여야 한다.', 4313);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7615, '④ 검사 또는 사법경찰관은 법 제16조제5항 또는 이 조 제3항에 따라 열람 또는 조회한 수신자료를 폐기하였을 때에는 지체 없이 그 사실을 서면으로 보호관찰소의 장에게 통지하여야 한다.', 4313);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7616, '① 검사 또는 사법경찰관은 수신자료를 열람 또는 조회하여 수사한 사건에 관하여 공소를 제기하거나 공소의 제기 또는 입건을 하지 아니하는 처분(기소중지결정은 제외한다)을 하였을 때에는 그 처분의 결과를 수신자료를 제공한 보호관찰소의 장에게 서면으로 통지하여야 한다.', 4314);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7617, '② 사법경찰관은 수신자료를 열람 또는 조회하여 수사한 사건을 종결하는 경우에는 그 결과를 검사에게 보고하여야 한다. 다만, 그 사건을 검찰에 송치하는 경우에는 그러하지 아니하다.', 4314);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7618, '① 전자장치 부착기간이 끝난 사람이 부착을 마친 날부터 5년 내에 자격정지 이상의 형을 받은 경우에는 그 형의 집행이 끝난 날부터 5년이 지난 때에 수신자료를 폐기한다.', 4316);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7619, '② 수신자료의 폐기는 전산자료에서 삭제하는 방법으로 한다.', 4316);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7620, '① 법 제16조의2제1항에 따라 보호관찰소의 장이 피부착자의 주거지를 관할하는 경찰관서의 장 등 수사기관에 제공할 수 있는 피부착자의 신상정보는 다음 각 호와 같다. <개정 2015.1.20>', 4317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7621, '② 법 제16조의2제3항에 따라 보호관찰소의 장이 수사기관에 통보하는 사항은 다음 각 호와 같다.', 4317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7622, '③ 법 제16조의2제4항에 따라 수사기관이 보호관찰소의 장에게 통보하는 사항은 다음 각 호와 같다.', 4317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7623, '④ 제1항에 따른 피부착자 신상정보의 제공은 보호관찰소의 장이 관리하는 제1항 각 호의 피부착자 신상정보에 관한 전자기록을 「형사사법절차 전자화 촉진법」 제2조제4호에 따른 형사사법정보시스템에 등록하고, 수사기관은 이를 조회하는 방식 등으로 할 수 있다.', 4317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7624, '⑤ 수사기관의 장은 제4항에 따라 조회한 피부착자의 신상정보를 문서로 출력한 경우 제1항제7호에 따른 전자장치 부착기간이 끝나면 그 문서를 폐기하여야 한다.', 4317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7625, '① 법 제17조제1항에 따른 부착명령의 임시해제 신청은 「보호관찰 등에 관한 법률」 제5조에 따른 보호관찰심사위원회(이하 "심사위원회"라 한다)에 서면으로 해야 한다. <개정 2020.8.5>', 4318);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7626, '② 심사위원회는 피부착자 또는 그 법정대리인이 부착명령의 임시해제를 신청한 경우 지체 없이 그 사실을 보호관찰소의 장에게 통보해야 한다. <개정 2020.8.5>', 4318);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7627, '① 심사위원회는 법 제18조제1항에 따라 부착명령의 임시해제를 심사할 때에는 보호관찰관, 정신건강의학과 의사, 정신보건임상심리사, 그 밖의 전문가의 의견을 고려해야 한다. <개정 2011.11.23, 2013.5.31, 2020.8.5>', 4319);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7628, '② 심사위원회는 법 제18조제4항 및 제5항의 결정을 하면 지체 없이 그 결정서 등본을 관할 보호관찰소의 장과 신청인에게 송달하여야 한다.', 4319);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7629, '③ 보호관찰관은 법 제18조제4항의 부착명령 임시해제 결정이 있으면 결정서에 기재된 임시해제일에 전자장치를 회수해야 한다. <개정 2020.8.5>', 4319);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7630, '④ 심사위원회가 제1항에 따라 전문가 의견을 고려한 경우 의견을 진술하거나 자료를 제출한 전문가에게는 예산의 범위에서 필요한 비용의 전부 또는 일부를 지급할 수 있다. <신설 2010.7.12>', 4319);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7631, '① 법 제19조제1항에 따른 임시해제의 취소신청은 심사위원회에 서면으로 해야 한다. <신설 2013.5.31, 2020.8.5>', 4320);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7632, '② 심사위원회는 법 제19조제1항에 따라 부착명령의 임시해제 취소 결정을 했을 때에는 지체 없이 그 사실을 관할 보호관찰소의 장에게 통보해야 한다. <개정 2013.5.31, 2020.8.5>', 4320);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7633, '③ 보호관찰관은 부착명령의 임시해제 취소결정이 있으면 피부착명령자에게 결정서를 제시한 후 전자장치를 부착해야 한다. <개정 2013.5.31, 2020.8.5>', 4320);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7634, '④ 임시해제가 취소된 경우 부착명령 집행기간은 부착장치를 피부착명령자의 신체에 부착한 때부터 진행한다. <개정 2013.5.31, 2020.8.5>', 4320);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7635, '① 보호관찰소의 장은 법 제21조의7에 따라 보호관찰 기간의 연장 또는 준수사항의 추가ㆍ변경ㆍ삭제를 신청하는 경우에는 다음 각 호의 사항을 적은 서면으로 하여야 한다.', 4321);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7636, '② 보호관찰소의 장은 제1항의 신청을 할 때 신청사유를 소명할 수 있는 자료를 제출하여야 한다.', 4321);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7637, '③ 법원은 법 제21조의7에 따른 청구의 심리를 위하여 필요한 경우에는 담당 보호관찰관을 출석시켜 의견을 들을 수 있으며, 보호관찰대상자를 소환하여 심문(審問)하거나 필요한 사항을 확인할 수 있다.', 4321);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7638, '① 교도소ㆍ소년교도소ㆍ구치소의 장은 가석방 예정자에 대한 심사위원회의 법 제22조제3항에 따른 전자장치 부착의 필요성과 적합성 여부 등의 조사(이하 "전자장치 부착 적합성조사"라 한다)를 위해 「형의 집행 및 수용자의 처우에 관한 법률」 및 관계 법령에 따라 가석방 적격심사 신청 대상자가 선정되면 지체 없이 해당 대상자에 대한 다음 각 호의 사항이 포함된 자료를 해당 교도소ㆍ소년교도소ㆍ구치소의 소재지를 관할하는 심사위원회에 보내야 한다.', 4323);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7639, '② 심사위원회는 제1항에 따라 교도소ㆍ소년교도소ㆍ구치소의 장으로부터 자료를 받은 경우에는 가석방 예정자에 대한 전자장치 부착 적합성조사를 하거나, 교도소ㆍ소년교도소ㆍ구치소의 소재지 또는 해당 가석방 예정자의 거주예정지를 관할하는 보호관찰소의 장과 협의하여 보호관찰소의 장에게 전자장치 부착 적합성조사를 위하여 필요한 사항의 조사를 의뢰할 수 있다.', 4323);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7640, '③ 보호관찰소의 장은 제2항에 따른 의뢰를 받은 경우에는 필요한 조사를 하고 그 결과를 심사위원회에 통보해야 한다.', 4323);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7641, '④ 교도소ㆍ소년교도소ㆍ구치소의 장은 심사위원회 또는 보호관찰소의 장으로부터 제2항 또는 제3항에 따른 전자장치 부착 적합성조사 등을 위한 가석방 예정자 면담 등 필요한 협조를 요청받은 경우 특별한 사정이 없으면 이에 협조해야 한다.', 4323);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7642, '⑤ 심사위원회 또는 보호관찰소의 장은 전자장치 부착 적합성조사를 위해 필요하다고 인정하면 국가기관, 지방자치단체 또는 공공기관의 장에게 사실을 알아보거나 관련 자료의 열람 등 협조를 요청할 수 있다. 이 경우 해당 기관의 장은 특별한 사정이 없는 한 이에 협조해야 한다.', 4323);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7643, '⑥ 전자장치 부착 적합성조사의 내용에는 가석방 예정자의 범죄경력, 범죄내용 및 직업, 경제력, 생활환경 등 개별적 특성에 관한 사항이 포함되어야 한다.', 4323);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7644, '① 심사위원회는 「보호관찰 등에 관한 법률」 제24조제1항에 따른 보호관찰 결정서 등본을 수용기관의 장에게 송달하면서 법 제22조제1항 및 제2항에 따른 전자장치 부착에 관한 사항을 함께 통보해야 한다. <개정 2020.8.5>', 4324);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7645, '② 「치료감호 등에 관한 법률」 제37조에 따른 치료감호심의위원회는 법 제23조제1항에 따라 피치료감호자 또는 피보호감호자에게 전자장치를 부착하는 결정을 한 경우 그 결정서를 피치료감호자 또는 피보호감호자에게, 결정서 등본을 수용기관의 장(보호감호시설의 장을 포함한다. 이하 이 장에서 같다)에게 각각 송달하여야 한다. <개정 2010.7.12, 2016.11.29>', 4324);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7646, '③ 제1항 또는 제2항에 따라 결정서 등본을 송달받은 수용기관의 장은 전자장치를 부착하게 될 가석방예정자, 피치료감호자 또는 피보호감호자에게 전자장치 부착에 관한 내용을 알려주어야 한다. <개정 2010.7.12>', 4324);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7647, '① 치료감호시설의 장 및 보호감호시설의 장은 법 제23조제1항에 따라 전자장치 부착결정을 받은 사람(이하 "피부착결정자"라 한다)을 다른 수용기관으로 이송할 경우 그 수용기관의 장에게 이송되는 사람이 전자장치 부착결정을 받았음을 통보하여야 한다. <개정 2010.7.12>', 4325);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7648, '② 제1항에 따라 피부착결정자를 인수한 수용기관의 장은 그가 출소하기 5일 전까지 그 주거지를 관할하는 보호관찰소의 장에게 피부착결정자의 석방 예정 사실을 통보하여야 한다.', 4325);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7649, '① 법원은 법 제31조의2제2항에 따라 보호관찰소의 장에게 조사를 의뢰하는 경우에는 피고인의 인적사항 및 범죄사실의 요지를 통보해야 한다. 이 경우 필요하면 참고자료를 보낼 수 있다.', 4329);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7650, '② 보호관찰소의 장은 법 제31조의2제3항에 따른 조사를 위해 수용기관의 장에게 협조를 요청할 수 있다. 이 경우 수용기관의 장은 특별한 사유가 없으면 이에 협조해야 한다.', 4329);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7651, '① 보호관찰관은 법 제31조의3제2항에 따라 부착명령을 집행하는 경우 같은 조 제1항에 따라 송부된 전자장치 보석피고인에 대한 결정문 등본(제23조의3에 따른 사본을 포함한다)을 확인한 후 전자장치를 부착해야 한다.', 4332);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7652, '② 보호관찰관은 제1항에 따라 전자장치를 부착하기 전에 전자장치 보석피고인에게 다음 각 호의 내용을 알려주어야 한다.', 4332);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7653, '③ 전자장치의 부착은 다음 각 호의 방법으로 한다.', 4332);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7654, '④ 보호관찰소의 장은 법 제31조의3제3항에 따라 피고인의 보석조건 이행 여부를 확인하기 위하여 국가기관, 지방자치단체 또는 공공기관의 장에게 사실을 알아보거나 관련 자료의 열람 등 협조를 요청할 수 있다. 이 경우 해당 기관의 장은 특별한 사정이 없는 한 이에 협조해야 한다. <신설 2021.9.14>', 4332);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7655, '① 보호관찰소의 장은 법 제31조의4제1항에 따라 피고인의 보석조건 이행상황을 매월 말일을 기준으로 작성하여 그 다음달 10일까지 보석결정을 한 법원에 송부해야 한다.', 4333);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7656, '② 제1항에도 불구하고 법원은 피고인의 재판을 위해 피고인의 보석조건 이행상황을 신속하게 파악할 필요가 있는 경우에는 보호관찰소의 장에게 피고인의 보석조건 이행상황에 관한 자료를 요청할 수 있다.', 4333);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7657, '① 보호관찰소의 장은 전자장치 보석피고인이 다음 각 호의 어느 하나에 해당하는 경우 법 제31조의4제2항에 따라 보석결정을 한 법원과 그 법원에 대응하는 검찰청 검사에게 지체 없이 통지해야 한다.', 4334);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7658, '② 제1항에 따른 통지는 인편 또는 등기우편의 방법으로 한다. 다만, 긴급한 경우에는 전화ㆍ팩스ㆍ전자우편 등의 방법으로 먼저 통지하고 사후에 인편 또는 등기우편의 방법으로 할 수 있다.', 4334);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7659, null, 4337);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7660, '① 법 제31조의6제2항에서 "대통령령으로 정하는 신상정보 등"이란 다음 각 호의 사항을 말한다.', 4338);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7661, '② 전자장치 스토킹행위자는 전자장치 부착의 집행 중 제1항제1호, 제2호 및 제4호부터 제6호까지의 사항이 변경된 경우에는 주거지를 관할하는 보호관찰소의 장에게 전화 등의 방법으로 지체 없이 그 사실을 신고해야 한다.', 4338);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7662, '③ 전자장치 스토킹행위자는 전자장치 부착의 집행 중 제1항제3호의 사항이 변경된 경우에는 지체 없이 주거지를 관할하는 보호관찰소에 출석하여 그 사실을 신고해야 한다.', 4338);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7663, '④ 제3항에도 불구하고 전자장치 스토킹행위자는 전자장치 부착의 집행 중 다른 보호관찰소의 관할 구역으로 주거지를 이전한 경우에는 3일 이내에 새로운 주거지를 관할하는 보호관찰소에 출석하여 제1항 각 호의 사항을 서면으로 신고해야 한다.', 4338);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7664, '⑤ 전자장치 스토킹행위자의 주거지를 관할하는 보호관찰소(이하 이 장에서 "보호관찰소"라 한다)의 장은 제2항부터 제4항까지의 규정에 따른 신고를 받은 경우에는 관할경찰관서의 장에게 지체 없이 그 사실을 통지해야 한다.', 4338);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7665, '① 보호관찰관은 법 제31조의6제2항에 따라 전자장치를 부착하는 경우 같은 조 제1항에 따라 송부된 전자장치 스토킹행위자에 대한 결정문 등본(제23조의10에 따른 사본을 포함한다)을 확인한 후 전자장치를 부착해야 한다.', 4339);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7666, '② 보호관찰관은 제1항에 따라 전자장치를 부착하기 전에 전자장치 스토킹행위자에게 전자장치 효용 유지를 위해 필요한 다음 각 호의 의무 사항을 알려주어야 한다.', 4339);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7667, '③ 보호관찰관은 제1항에 따라 전자장치를 부착하면 지체 없이 전자장치 스토킹행위자와 피해자가 서로 근접하는지 여부를 확인할 수 있는 장치 또는 시스템(이하 이 항에서 "피해자장치등"이라 한다)을 피해자에게 제공해야 한다. 다만, 피해자와 연락이 되지 않거나 피해자가 피해자장치등의 수령을 거부하는 등의 사유로 피해자장치등을 제공할 수 없는 경우에는 피해자 보호 업무를 담당하는 사법경찰관리에게 휴대전화 문자전송, 전자우편, 팩스 또는 전화 등의 방법으로 지체 없이 그 사실을 통지해야 한다.', 4339);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7668, '① 보호관찰소의 장은 법 제31조의6제3항 각 호 외의 부분에 따라 관할경찰관서의 장에게 전자장치 스토킹행위자가 전자장치를 부착한 사실을 통지할 때에는 제23조의11제1항 각 호의 사항과 그 밖에 피해자 보호를 위해 필요한 사항을 함께 통지해야 한다.', 4340);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7669, '② 법 제31조의6제3항제6호에서 "대통령령으로 정하는 피해자의 보호를 위하여 필요한 사항"이란 다음 각 호의 사항을 말한다.', 4340);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7670, '③ 관할경찰관서의 장은 전자장치 부착의 집행 중 법 제31조의6제3항 각 호의 사항이 변경된 것을 안 때에는 보호관찰소의 장에게 즉시 그 사실을 통지해야 한다.', 4340);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7671, '① 법 제31조의6제4항제4호에서 "대통령령으로 정하는 사유가 있는 경우"란 다음 각 호의 경우를 말한다.', 4341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7672, '② 보호관찰소의 장 또는 위치추적 관제센터의 장은 전자장치 스토킹행위자가 법 제31조의6제4항 각 호의 어느 하나에 해당하는 경우에는 관할경찰관서의 장 또는 시ㆍ도경찰청 112치안종합상황실장에게 휴대전화 문자전송, 전자우편, 팩스 또는 전화 등의 방법으로 즉시 그 사실을 통지해야 한다.', 4341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7673, '③ 제1항 및 제2항에서 규정한 사항 외에 피해자의 보호 방법 및 절차 등에 관한 세부 사항은 경찰청장이 법무부장관과 협의하여 정한다.', 4341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7674, null, 4345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7675, '① 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제1호 및 제3항제1호에 따라 성폭력범죄를 저질러 2008년 9월 1일 이전에 제1심판결을 선고받아 2010년 7월 16일 기준으로 징역형 이상의 형, 치료감호 또는 보호감호(이하 "징역형등"이라 한다)의 집행 종료일까지 6개월 이상이 남은 사람(이하 "출소예정자"라 한다), 징역형등의 집행 종료일까지 6개월 미만이 남은 사람(이하 "출소임박자"라 한다) 및 징역형등의 집행이 종료, 가종료ㆍ가출소ㆍ가석방 또는 면제된 후 3년이 경과되지 아니한 사람(이하 "출소자"라 한다)에 대하여 교도소ㆍ구치소ㆍ치료감호시설ㆍ보호감호시설(이하 "수용시설"이라 한다)의 장이 수용시설의 소재지를 관할하는 지방검찰청의 검사에게 통보하여야 할 사항은 다음 각 호와 같다.', 4347);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7676, '② 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제1호 및 제3항제1호에 따라 성폭력범죄를 저질러 2008년 9월 1일 이전에 제1심판결을 선고받아 2010년 7월 16일 기준으로 출소예정자, 출소임박자, 출소자(이하 "출소자등"이라 한다)인 사람에 대하여 수용시설의 장이 수용시설의 소재지를 관할하는 보호관찰소의 장에게 통보하여야 할 사항은 출소자등의 성명, 주민등록번호, 주소, 출소예정일 및 죄명으로 한다.', 4347);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7677, '① 법원은 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제5호 및 제3항제8호에 따라 출소자등에 대하여 부착명령을 결정한 경우에는 부착명령을 받은 사람에게 그 결정을 고지하여야 한다.', 4350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7678, '② 법원은 제1항에 따라 결정이 고지된 날부터 3일 이내에 부착명령을 고지받은 사람의 주거지를 관할하는 보호관찰소의 장에게 결정문 등본을 송부하여야 한다.', 4350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7679, '③ 수용시설의 장은 부착명령을 고지받은 사람이 석방되기 5일 전까지 그의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다.', 4350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7680, '① 출소자등에 대한 부착명령은 부착명령이 고지된 후 지체 없이 검사의 지휘를 받아 보호관찰관이 집행한다.', 4351);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7681, '② 제1항에 따른 지휘는 결정문 등본을 첨부한 서면으로 한다.', 4351);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7682, '① 법무부장관은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 4352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7683, '② 검사는 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호 또는 제2호에 따른 유전정보 또는 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. 다만, 제9호의2의 사무의 경우에는 「개인정보 보호법」 제23조에 따른 성생활에 관한 정보 및 같은 법 시행령 제18조제1호에 따른 유전정보에 해당하는 정보는 제외한다. <개정 2021.9.14, 2024.1.9>', 4352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7684, '③ 보호관찰소의 장 또는 보호관찰관은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호 또는 제2호에 따른 유전정보 또는 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. 다만, 제16호의2 및 제16호의3의 사무의 경우에는 「개인정보 보호법」 제23조에 따른 성생활에 관한 정보 및 같은 법 시행령 제18조제1호에 따른 유전정보에 해당하는 정보는 제외한다. <개정 2021.9.14, 2024.1.9>', 4352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7685, '④ 심사위원회는 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호 또는 제2호에 따른 유전정보 또는 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 4352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7686, '⑤ 치료감호심의위원회는 법 제23조 및 제24조에 따른 전자장치 부착에 관한 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호 또는 제2호에 따른 유전정보 또는 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 4352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7687, '⑥ 수용기관의 장 또는 수용시설의 장은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 4352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7688, '⑦ 경찰관서의 장 등 수사기관은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2024.1.9>', 4352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7689, '⑧ 사법경찰관은 다음 각 호의 사무를 수행하기 위해 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2024.1.9>', 4352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7690, '① 「전자장치 부착 등에 관한 법률」(이하 "법"이라 한다) 제6조제1항, 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제2호 및 제3항제2호에 따른 조사요청은 별지 제1호서식의 부착명령 청구 전 조사 요청서에 따른다. <개정 2009.7.30, 2010.7.15, 2013.5.31, 2020.8.5>', 4355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7691, '② 「전자장치 부착 등에 관한 법률 시행령」(이하 "영"이라 한다) 제4조제1항 후단에 따른 참고자료란 피의자 신문조서, 피해자 진술조서, 범죄경력자료 및 수사경력자료 등을 말한다. <개정 2010.7.15, 2013.5.31, 2020.8.5>', 4355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7692, '① 법 제8조의 부착명령청구서는 별지 제2호서식과 같다. 다만, 공소제기와 동시에 부착명령을 청구하는 경우에는 영 제5조제2항에 따라 별지 제3호서식의 공소장 및 부착명령청구서로 할 수 있다.', 4356);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7693, '② 공소를 제기한 후에 부착명령을 청구하는 경우에는 부착명령 청구사건과 병합심리할 피고사건의 법원명, 사건번호, 피고인명, 죄명 등을 명시하여 부착명령 청구사건의 관할법원에 병합심리를 신청하여야 한다.', 4356);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7694, '① 법 제12조(법 제31조에 따라 준용되는 경우를 포함한다) 및 영 제28조제1항의 집행지휘는 별지 제5호서식의 부착명령 집행지휘서에 따른다. <개정 2010.7.15>', 4358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7695, '② 검사는 부착명령과 병과된 형의 집행지휘서의 비고란에 "부착명령"이라고 붉은 색으로 적어야 한다.', 4358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7696, '① 영 제12조제1항(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 신고는 별지 제9호서식의 신고서에 따른다. <개정 2013.5.31>', 4362);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7697, '② 영 제12조제2항 및 제3항(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 허가 신청 및 허가는 각각 별지 제10호서식의 주거이전, 국내여행 또는 출국 허가신청서와 별지 제11호서식의 주거이전, 국내여행 또는 출국 허가서에 따른다. <개정 2013.5.31>', 4362);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7698, '③ 영 제12조제7항(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 통보요청은 별지 제12호서식의 출입국사실 통보 요청서에 따른다. <개정 2013.5.31>', 4362);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7699, '① 법 제14조의2, 제14조의3 및 영 제12조의2에 따른 부착기간의 연장 또는 준수사항의 부과ㆍ추가ㆍ변경ㆍ삭제의 신청은 별지 제13호서식에 따른다.', 4363);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7700, '② 법 제14조의2 또는 제14조의3에 따른 부착기간의 연장 또는 준수사항의 부과ㆍ추가ㆍ변경ㆍ삭제의 청구는 별지 제14호서식에 따른다.', 4363);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7701, '① 영 제13조제1항에 따라 치료 및 상담치료 등을 실시할 수 있는 시설 또는 단체로 지정을 받으려는 자(이하 "신청인"이라 한다)는 별지 제15호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정 신청서에 다음 각 호의 서류를 첨부하여 주소지를 관할하는 보호관찰소(지소를 포함한다. 이하 같다)의 장에게 제출해야 한다. <개정 2013.5.31, 2022.2.7, 2022.12.19>', 4364);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7702, '② 제1항에 따른 신청서를 받은 담당 공무원은 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 다음 각 호의 서류의 내용을 확인하여야 한다.', 4364);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7703, '③ 제1항에 따른 신청을 받은 경우 보호관찰소의 장은 신청일부터 14일 이내에 별지 제16호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정신청에 대한 의견서와 함께 신청인이 제출한 특정 범죄자 치료기관 또는 상담치료기관 지정 신청서와 첨부서류를 법무부장관에게 보내야 한다. <개정 2013.5.31>', 4364);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7704, '④ 법무부장관은 영 제13조제1항에 따라 신청인을 치료 및 상담치료 등을 실시할 수 있는 시설 또는 단체로 지정할 때에는 신청인에게 별지 제17호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정서를 발급하여야 한다. <개정 2013.5.31>', 4364);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7705, '⑤ 영 제13조제1항에 따른 지정을 받은 시설 또는 단체는 다음 각 호의 어느 하나에 해당하는 사항을 변경하려면 별지 제18호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정사항 변경신청서에 변경된 사항을 증명하는 서류 등을 첨부하여 주소지를 관할하는 보호관찰소의 장에게 제출하여야 한다. <개정 2013.5.31>', 4364);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7706, '⑥ 제5항에 따른 변경신청을 받은 경우 보호관찰소의 장은 변경신청일부터 14일 이내에 별지 제19호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정사항 변경신청에 대한 의견서와 변경신청을 한 시설 또는 단체가 제출한 특정 범죄자 치료기관 또는 상담치료기관 지정사항 변경신청서 및 첨부서류를 법무부장관에게 보내야 한다. <개정 2013.5.31>', 4364);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7707, '⑦ 법무부장관은 제5항에 따른 지정사항 변경신청이 적정하다고 판단되는 경우 변경내용이 기재된 제17호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정서를 신청인에게 다시 발급하여야 한다. <개정 2013.5.31>', 4364);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7708, '⑧ 보호관찰소의 장은 법무부장관에게 영 제13조제1항에 따른 지정을 받은 시설 또는 단체의 시설이나 특정 범죄자 치료 및 교정 프로그램이 특정 범죄자의 치료ㆍ개선에 적당한지 여부와 그 운영실태를 정기적으로 보고하여야 한다.', 4364);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7709, '⑨ 법무부장관은 제8항에 따른 보고 결과 영 제13조제1항에 따른 지정을 받은 시설 또는 단체의 시설이나 특정 범죄자 치료 및 교정 프로그램이 특정 범죄자의 치료ㆍ개선에 부적당하다고 인정하면 지정을 취소할 수 있다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 지정을 취소하여야 한다. <개정 2013.5.31>', 4364);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7710, '① 보호관찰관은 법 제15조제3항에 따라 피부착자의 형 또는 치료감호 집행 중의 생활실태를 확인할 수 있는 자료를 요청하거나 피부착자를 면접하려는 경우에는 보호관찰소의 장을 통하여 교도소, 소년교도소, 구치소, 국립법무병원 및 군교도소의 장(이하 "교도소장등"이라 한다)에게 다음 사항을 적은 서면(전자문서를 포함한다)을 제출하여야 한다. <개정 2022.7.4>', 4365);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7711, '② 교도소장등은 제1항의 요청에 대하여 보호관찰소의 장에게 서면(전자문서를 포함한다)으로 회신하여야 한다. 다만, 생활실태 확인을 위한 자료는 「형사사법절차 전자화 촉진법」에 따른 형사사법정보시스템을 통하여 보호관찰소의 장에게 제공하는 방법으로 회신할 수 있다.', 4365);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7712, '③ 제1항에 따른 보호관찰관의 자료 또는 면접 요청은 별지 제20호서식에 따른다.', 4365);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7713, '④ 제2항 본문에 따른 교도소장등의 회신은 별지 제21호서식에 따른다.', 4365);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7714, '① 검사가 영 제14조의2제1항에 따라 수신자료의 열람ㆍ조회 허가청구를 하는 경우에는 별지 제23호서식에 따른다.', 4367);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7715, '② 사법경찰관이 영 제14조의2제2항에 따른 수신자료 열람ㆍ조회 허가신청을 하는 경우에는 별지 제24호서식에 따른다.', 4367);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7716, '③ 검사가 영 제14조의2제2항에 따라 사법경찰관으로부터 수신자료의 열람ㆍ조회 허가신청을 받아 수신자료 열람ㆍ조회 허가청구를 하는 경우에는 별지 제25호서식에 따른다.', 4367);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7717, '① 검사 또는 사법경찰관이 영 제14조의3제1항에 따라 보호관찰소의 장에게 긴급 수신자료 열람ㆍ조회를 요청하는 경우에는 별지 제26호서식에 따른다.', 4368);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7718, '② 영 제14조의3제2항에 따른 긴급 수신자료 열람 또는 조회의 허가청구는 별지 제27호서식에 따른다.', 4368);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7719, '③ 영 제14조의3제3항에 따른 긴급 수신자료 열람 또는 조회의 허가신청 및 허가청구는 각각 별지 제28호서식 및 별지 제29호서식에 따른다.', 4368);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7720, '① 검사 또는 사법경찰관은 법 제16조제4항 본문에 따라 수신자료를 열람 또는 조회한 때에는 별지 제30호서식의 수신자료 열람ㆍ조회 대장에 해당 사항을 적어야 하고, 법 제16조제4항 단서에 따라 수신자료를 열람 또는 조회한 때에는 별지 제31호서식의 긴급 수신자료 열람ㆍ조회 대장에 해당 사항을 적어야 한다.', 4369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7721, '② 보호관찰소의 장은 법 제16조제4항에 따라 수신자료를 열람 또는 조회하게 한 때에는 별지 제32호서식의 수신자료 열람ㆍ조회 접수 대장에 해당 사항을 적어야 한다.', 4369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7722, '③ 영 제14조의4제4항에 따른 검사 또는 사법경찰관의 수신자료 폐기사실의 통지는 별지 제33호서식에 따른다.', 4369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7723, '① 법 제16조의3제2항에 따라 피부착자에 관한 영상정보를 제공받은 위치추적 관제센터의 장은 같은 조 제3항에 따라 해당 영상정보의 열람이 종료된 날부터 30일 이내에 열람 사실을 해당 피부착자에게 통지해야 한다.', 4372);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7724, '② 제1항에 따른 통지는 휴대전화 문자전송, 전자우편, 팩스, 전화 또는 우편 등의 방법으로 한다.', 4372);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7725, '① 법 제21조의2에 따른 보호관찰명령의 청구는 별지 제38호서식에 따른다. 다만, 공소제기와 동시에 보호관찰명령을 청구하는 경우에는 별지 제39호서식의 공소장 및 보호관찰명령 청구서로 할 수 있다.', 4376);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7726, '② 검사가 공소를 제기한 후에 보호관찰명령을 청구하는 경우에는 보호관찰명령 청구사건과 병합심리할 피고사건의 법원명, 사건번호, 피고인명 및 죄명 등을 명시하여 보호관찰명령 청구사건의 관할 법원에 병합심리를 신청하여야 한다.', 4376);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7727, '① 법 제21조의3에 따라 선고된 보호관찰명령의 집행지휘는 별지 제40호서식의 보호관찰명령 집행지휘서에 따른다.', 4377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7728, '② 검사는 보호관찰명령과 병과된 형의 집행지휘서의 비고란에 "보호관찰명령"이라고 붉은 색으로 적어야 한다.', 4377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7729, '① 법 제22조제4항 및 제23조제2항에 따른 전자장치 부착대상자 통보는 별지 제43호서식의 전자장치 부착대상자 통보서에 따른다. <개정 2013.5.31, 2020.8.5>', 4380);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7730, '② 영 제19조의2제2항의 결정서는 별지 제44호서식에 따른다. <개정 2013.5.31, 2020.8.5>', 4380);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7731, '① 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제6호에 따른 구인영장의 청구와 신청은 각각 별지 제47호서식과 별지 제48호서식에 따른다. <개정 2013.5.31>', 4392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7732, '② 보호관찰소의 장은 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제6호에 따라 검사에게 구인영장을 신청할 때에는 별지 제49호서식의 구인영장 신청부에 정해진 사항을 적어야 한다. <개정 2013.5.31, 2022.2.7>', 4392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7733, '① 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제6호에 따른 구인영장은 별지 제50호서식에 따른다. <개정 2013.5.31>', 4393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7734, '② 검사는 구인영장 위쪽에 집행을 지휘한다는 내용을 기재하고 서명 또는 기명날인의 방법으로 구인영장의 집행을 지휘할 수 있다.', 4393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7735, '① 법 제13조제2항 및 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제10호에 따른 부착명령 집행장의 신청은 별지 제51호서식에 따른다. <개정 2013.5.31, 2018.2.2>', 4394);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7736, '② 법 제13조제2항 및 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제10호에 따른 부착명령 집행장은 별지 제52호서식에 따른다. <개정 2013.5.31, 2018.2.2>', 4394);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7737, '①몰수보전 청구서에는 다음 각호의 사항을 기재하고 청구하는 검사가 서명날인을 하여야 한다. <개정 2005.12.29>', 4397);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7738, '②몰수보전 청구서에는 공소사실 또는 피의사실의 요지를 따로 기재한 서면 1통을 첨부하여야 한다. <개정 2005.12.29>', 4397);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7739, '③몰수보전의 청구를 하는 때에는 법 제23조제1항이 규정하는 사유를 인정할 수 있는 자료를 제출하여야 한다.', 4397);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7740, '①부대보전 청구서에는 제3조제1항 각호의 사항을 기재하는 외에, 몰수보전의 청구와 함께 하는 경우에는 다음 제2호 및 제3호의 사항을, 몰수보전의 청구와 별도로 하는 경우에는 다음 각호의 사항을 각 기재하고 청구하는 검사가 서명날인을 하여야 한다. <개정 2005.12.29>', 4399);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7741, '②부대보전의 청구를 하는 때에는 법 제23조제2항이 규정하는 사유를 인정할 수 있는 자료를 제출하여야 한다.', 4399);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7742, '③제3조제2항은 부대보전의 청구에 이를 준용한다.', 4399);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7743, '①몰수보전명령의 취소청구는 다음 각호의 사항을 기재한 서면으로 하여야 한다.', 4406);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7744, '②몰수보전명령의 취소청구를 하는 때에는 법 제32조제1항이 규정하는 사유를 인정할 수 있는 자료를 제출하여야 한다.', 4406);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7745, '③검사 또는 수사처검사 아닌 자가 제1항의 취소청구를 할 때에는 그 청구서의 부본을 첨부하여야 한다. <개정 2021.1.29>', 4406);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7746, '④법원이 몰수보전명령의 취소에 관하여 검사 또는 수사처검사의 의견을 물을 때에는 제3항의 청구서 부본을 첨부하여야 한다. <개정 2021.1.29>', 4406);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7747, '①몰수보전된 재산에 대하여 강제경매개시결정 또는 강제집행에 의하여 압류가 된 때에는, 집행법원의 법원서기관, 법원사무관, 법원주사 또는 법원주사보(이하 "법원사무관등"이라고 한다. 동산의 경우에는 집행관)는 검사 또는 수사처검사에게 그 사실을 통지하여야 한다. <개정 2002.6.28, 2021.1.29>', 4408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7748, '②제1항의 경우 강제집행신청이 취하된 때 또는 강제집행절차를 취소하는 결정이 확정된 때에는 집행법원의 법원사무관등(동산의 경우에는 집행관)은 검사 또는 수사처검사에게 그 사실을 통지하여야 한다. <개정 2002.6.28, 2021.1.29>', 4408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7749, '③제1항의 경우 몰수의 재판이 확정되거나 몰수보전이 효력을 상실한 때에는 검사 또는 수사처검사는 집행법원(동산의 경우에는 집행관)에 그 사실을 통지하여야 한다. <개정 2002.6.28, 2021.1.29>', 4408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7750, '①법 제36조제2항의 규정에 의한 신고는 다음 각호의 사항을 기재한 서면으로 하여야 한다. <개정 2005.12.29>', 4409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7751, '②제1항의 경우 몰수보전명령을 발한 법원에 대한 공탁사유신고서에는 공탁서를 첨부하여야 한다. <개정 2005.12.29>', 4409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7752, '③제1항의 신고가 있은 경우 몰수보전명령을 발한 법원의 법원사무관등은 검사 또는 수사처검사에게 그 사실을 통지하여야 한다. <개정 2021.1.29>', 4409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7753, '①법 제40조제2항에 의하여 준용되는 법 제36조제2항의 규정에 의한 신고는 몰수보전명령을 발한 법원, 체납처분을 한 「국세기본법」 제2조제17호 및 「지방세법」 제1조제1항제3호의 세무공무원과 그 밖에 체납처분을 집행하는 권한이 있는 자 또는 한국자산관리공사가 세무서장을 대행하여 공매, 배분 및 권리이전등기의 촉탁을 대행하는 경우에는 한국자산관리공사 및 그 직원(이하 "세무공무원등"이라고 한다)에게 하여야 한다.', 4410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7754, '②제1항의 신고는 다음 각 호의 사항을 기재한 서면으로 하여야 한다.', 4410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7755, '③제1항의 경우 제14조제2항ㆍ제3항의 규정을 준용한다.', 4410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7756, '①제14조제1항은 법 제36조제4항에 의하여 준용되는 동조제2항의 규정에 의한 공탁사유신고에 준용한다.', 4411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7757, '②제1항의 경우 압류명령을 발한 법원에 대한 공탁사유신고서에는 공탁서를 첨부하여야 한다. <개정 2005.12.29>', 4411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7758, '③제1항의 신고가 있은 경우 압류명령을 발한 법원의 법원사무관등은 검사 또는 수사처검사에게 그 사실을 통지하여야 한다. <개정 2021.1.29>', 4411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7759, '①제14조의2제1항ㆍ제2항은 법 제40조제2항 및 제36조제4항에 의하여 준용되는 법 제36조제2항의 규정에 의한 공탁사유신고에 준용한다.', 4412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7760, '②제1항의 경우 세무공무원등에 대한 공탁사유신고서에는 공탁서를 첨부하여야 한다.', 4412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7761, '①강제경매개시결정 또는 강제집행에 의하여 압류가 된 재산에 대하여 몰수보전명령이 발하여진 때에는 검사 또는 수사처검사는 집행법원(동산의 경우에는 집행관)에 그 사실을 통지하여야 한다. <개정 2002.6.28, 2021.1.29>', 4413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7762, '②제1항의 경우 몰수의 재판이 확정된 때 또는 몰수보전이 효력을 상실한 때에는 검사 또는 수사처검사는 집행법원(동산의 경우에는 집행관)에 그 사실을 통지하여야 한다. <개정 2002.6.28, 2021.1.29>', 4413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7763, '③제1항의 경우 강제집행신청의 취하에 의하여 압류의 효력이 소멸하거나 강제집행절차를 취소하는 결정이 확정된 때 또는 강제집행절차에 의하여 재산이 매각된 때에는 집행법원의 법원사무관등(동산의 경우 집행관)은 검사 또는 수사처검사에게 그 사실을 통지하여야 한다. 「민사집행법」 제223조가 규정하는 채권(같은 법 제251조제1항에 의하여 같은 법 제2편제2장제4절제3관의 규정이 준용되는 재산권을 포함한다)에 대하여 같은 법 제236조제1항의 신고가 있는 때, 같은 법 제256조의 규정에 의하여 배당이 실시된 때, 같은 법 제229조제3항의 전부명령 또는 같은 법 제241조의 양도명령이 확정된 때에도 그 사실을 통지하여야 한다. <개정 2002.6.28, 2005.12.29, 2021.1.29>', 4413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7764, '①법 제38조제1항의 강제집행의 정지의 청구는 다음 각호의 사항을 기재한 서면으로 하여야 한다.', 4414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7765, '②제1항의 청구를 하는 경우에는 제1항제2호의 이유가 있다고 인정할 수 있는 자료를 제출하여야 한다.', 4414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7766, '③제11조의 규정은 법 제38조제3항의 강제집행정지결정의 취소청구에 관하여 준용한다. 이 경우 제11조제1항의 "몰수보전사건의 표시"는 "강제집행정지사건의 표시"로, 동조제1항 및 제2항의 각 "법 제32조제1항"은 각 "법 제38조제3항"으로 본다.', 4414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7767, '①제13조의 규정은 몰수보전이 된 재산에 대하여 가압류의 집행이 있는 경우에 준용한다.', 4416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7768, '②제14조의 규정은 몰수보전이 된 금전채권에 대하여 가압류의 집행이 있는 경우 당해금전채권의 채무자의 공탁에 관하여, 제15조의 규정은 가압류된 금전채권에 대하여 몰수보전이 된 경우 당해금전채권의 채무자의 공탁에 관하여 각 준용한다.', 4416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7769, '③제16조의 규정은 가압류된 재산에 대하여 몰수보전명령이 발하여진 경우에 준용한다.', 4416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7770, '④제17조의 규정은 가압류된 재산에 대하여 몰수보전명령을 발한 경우 또는 발하려고 하는 경우에 있어서 강제집행의 정지의 청구 및 그 정지결정의 취소청구에 관하여 준용한다.', 4416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7771, '①추징보전 청구서에는 다음 각호의 사항을 기재하고 검사 또는 수사처검사가 서명날인하여야 한다. <개정 2005.12.29, 2021.1.29>', 4419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7772, '②추징보전 청구서에는 공소사실 또는 피의사실의 요지를 따로 기재한 서면 1통을 첨부하여야 한다. <개정 2005.12.29>', 4419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7773, '③추징보전의 청구를 하는 때에는 법 제42조제1항이 규정하는 사유를 인정할 수 있는 자료를 제출하여야 한다.', 4419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7774, null, 4425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7775, '① 질서위반행위의 성립과 과태료 처분은 행위 시의 법률에 따른다.', 4426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7776, '② 질서위반행위 후 법률이 변경되어 그 행위가 질서위반행위에 해당하지 아니하게 되거나 과태료가 변경되기 전의 법률보다 가볍게 된 때에는 법률에 특별한 규정이 없는 한 변경된 법률을 적용한다.', 4426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7777, '③ 행정청의 과태료 처분이나 법원의 과태료 재판이 확정된 후 법률이 변경되어 그 행위가 질서위반행위에 해당하지 아니하게 된 때에는 변경된 법률에 특별한 규정이 없는 한 과태료의 징수 또는 집행을 면제한다.', 4426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7778, '① 이 법은 대한민국 영역 안에서 질서위반행위를 한 자에게 적용한다.', 4427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7779, '② 이 법은 대한민국 영역 밖에서 질서위반행위를 한 대한민국의 국민에게 적용한다.', 4427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7780, '③ 이 법은 대한민국 영역 밖에 있는 대한민국의 선박 또는 항공기 안에서 질서위반행위를 한 외국인에게 적용한다.', 4427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7781, '① 심신(心神)장애로 인하여 행위의 옳고 그름을 판단할 능력이 없거나 그 판단에 따른 행위를 할 능력이 없는 자의 질서위반행위는 과태료를 부과하지 아니한다.', 4433);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7782, '② 심신장애로 인하여 제1항에 따른 능력이 미약한 자의 질서위반행위는 과태료를 감경한다.', 4433);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7783, '③ 스스로 심신장애 상태를 일으켜 질서위반행위를 한 자에 대하여는 제1항 및 제2항을 적용하지 아니한다.', 4433);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7784, '① 법인의 대표자, 법인 또는 개인의 대리인ㆍ사용인 및 그 밖의 종업원이 업무에 관하여 법인 또는 그 개인에게 부과된 법률상의 의무를 위반한 때에는 법인 또는 그 개인에게 과태료를 부과한다.', 4434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7785, '② 제7조부터 제10조까지의 규정은 「도로교통법」 제56조제1항에 따른 고용주등을 같은 법 제160조제3항에 따라 과태료를 부과하는 경우에는 적용하지 아니한다.', 4434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7786, '① 2인 이상이 질서위반행위에 가담한 때에는 각자가 질서위반행위를 한 것으로 본다.', 4435);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7787, '② 신분에 의하여 성립하는 질서위반행위에 신분이 없는 자가 가담한 때에는 신분이 없는 자에 대하여도 질서위반행위가 성립한다.', 4435);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7788, '③ 신분에 의하여 과태료를 감경 또는 가중하거나 과태료를 부과하지 아니하는 때에는 그 신분의 효과는 신분이 없는 자에게는 미치지 아니한다.', 4435);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7789, '① 하나의 행위가 2 이상의 질서위반행위에 해당하는 경우에는 각 질서위반행위에 대하여 정한 과태료 중 가장 중한 과태료를 부과한다.', 4436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7790, '② 제1항의 경우를 제외하고 2 이상의 질서위반행위가 경합하는 경우에는 각 질서위반행위에 대하여 정한 과태료를 각각 부과한다. 다만, 다른 법령(지방자치단체의 조례를 포함한다. 이하 같다)에 특별한 규정이 있는 경우에는 그 법령으로 정하는 바에 따른다.', 4436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7791, null, 4437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7792, '① 과태료는 행정청의 과태료 부과처분이나 법원의 과태료 재판이 확정된 후 5년간 징수하지 아니하거나 집행하지 아니하면 시효로 인하여 소멸한다.', 4438);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7793, '② 제1항에 따른 소멸시효의 중단ㆍ정지 등에 관하여는 「국세기본법」 제28조를 준용한다.', 4438);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7794, '① 행정청이 질서위반행위에 대하여 과태료를 부과하고자 하는 때에는 미리 당사자(제11조제2항에 따른 고용주등을 포함한다. 이하 같다)에게 대통령령으로 정하는 사항을 통지하고, 10일 이상의 기간을 정하여 의견을 제출할 기회를 주어야 한다. 이 경우 지정된 기일까지 의견 제출이 없는 경우에는 의견이 없는 것으로 본다.', 4439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7795, '② 당사자는 의견 제출 기한 이내에 대통령령으로 정하는 방법에 따라 행정청에 의견을 진술하거나 필요한 자료를 제출할 수 있다.', 4439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7796, '③ 행정청은 제2항에 따라 당사자가 제출한 의견에 상당한 이유가 있는 경우에는 과태료를 부과하지 아니하거나 통지한 내용을 변경할 수 있다.', 4439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7797, '① 행정청은 제16조의 의견 제출 절차를 마친 후에 서면(당사자가 동의하는 경우에는 전자문서를 포함한다. 이하 이 조에서 같다)으로 과태료를 부과하여야 한다. <개정 2011.4.5>', 4440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7798, '② 제1항에 따른 서면에는 질서위반행위, 과태료 금액, 그 밖에 대통령령으로 정하는 사항을 명시하여야 한다.', 4440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7799, '③ 삭제 <2016.12.2>', 4440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7800, '① 당사자는 과태료, 제24조에 따른 가산금, 중가산금 및 체납처분비를 대통령령으로 정하는 과태료 납부대행기관을 통하여 신용카드, 직불카드 등(이하 "신용카드등"이라 한다)으로 낼 수 있다.', 4441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7801, '② 제1항에 따라 신용카드등으로 내는 경우에는 과태료 납부대행기관의 승인일을 납부일로 본다.', 4441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7802, '③ 과태료 납부대행기관은 납부자로부터 신용카드등에 의한 과태료 납부대행 용역의 대가로 납부대행 수수료를 받을 수 있다.', 4441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7803, '④ 과태료 납부대행기관의 지정 및 운영, 납부대행 수수료에 관한 사항은 대통령령으로 정한다.', 4441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7804, '① 행정청은 당사자가 제16조에 따른 의견 제출 기한 이내에 과태료를 자진하여 납부하고자 하는 경우에는 대통령령으로 정하는 바에 따라 과태료를 감경할 수 있다.', 4442);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7805, '② 당사자가 제1항에 따라 감경된 과태료를 납부한 경우에는 해당 질서위반행위에 대한 과태료 부과 및 징수절차는 종료한다.', 4442);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7806, '① 행정청은 질서위반행위가 종료된 날(다수인이 질서위반행위에 가담한 경우에는 최종행위가 종료된 날을 말한다)부터 5년이 경과한 경우에는 해당 질서위반행위에 대하여 과태료를 부과할 수 없다.', 4443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7807, '② 제1항에도 불구하고 행정청은 제36조 또는 제44조에 따른 법원의 결정이 있는 경우에는 그 결정이 확정된 날부터 1년이 경과하기 전까지는 과태료를 정정부과 하는 등 해당 결정에 따라 필요한 처분을 할 수 있다.', 4443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7808, '① 행정청의 과태료 부과에 불복하는 당사자는 제17조제1항에 따른 과태료 부과 통지를 받은 날부터 60일 이내에 해당 행정청에 서면으로 이의제기를 할 수 있다.', 4444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7809, '② 제1항에 따른 이의제기가 있는 경우에는 행정청의 과태료 부과처분은 그 효력을 상실한다.', 4444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7810, '③ 당사자는 행정청으로부터 제21조제3항에 따른 통지를 받기 전까지는 행정청에 대하여 서면으로 이의제기를 철회할 수 있다.', 4444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7811, '① 제20조제1항에 따른 이의제기를 받은 행정청은 이의제기를 받은 날부터 14일 이내에 이에 대한 의견 및 증빙서류를 첨부하여 관할 법원에 통보하여야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그러하지 아니하다.', 4445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7812, '② 행정청은 사실상 또는 법률상 같은 원인으로 말미암아 다수인에게 과태료를 부과할 필요가 있는 경우에는 다수인 가운데 1인에 대한 관할권이 있는 법원에 제1항에 따른 이의제기 사실을 통보할 수 있다.', 4445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7813, '③ 행정청이 제1항 및 제2항에 따라 관할 법원에 통보를 하거나 통보하지 아니하는 경우에는 그 사실을 즉시 당사자에게 통지하여야 한다.', 4445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7814, '① 행정청은 질서위반행위가 발생하였다는 합리적 의심이 있어 그에 대한 조사가 필요하다고 인정할 때에는 대통령령으로 정하는 바에 따라 다음 각 호의 조치를 할 수 있다.', 4446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7815, '② 행정청은 질서위반행위가 발생하였다는 합리적 의심이 있어 그에 대한 조사가 필요하다고 인정할 때에는 그 소속 직원으로 하여금 당사자의 사무소 또는 영업소에 출입하여 장부ㆍ서류 또는 그 밖의 물건을 검사하게 할 수 있다.', 4446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7816, '③ 제2항에 따른 검사를 하고자 하는 행정청 소속 직원은 당사자에게 검사 개시 7일 전까지 검사 대상 및 검사 이유, 그 밖에 대통령령으로 정하는 사항을 통지하여야 한다. 다만, 긴급을 요하거나 사전통지의 경우 증거인멸 등으로 검사목적을 달성할 수 없다고 인정되는 때에는 그러하지 아니하다.', 4446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7817, '④ 제2항에 따라 검사를 하는 직원은 그 권한을 표시하는 증표를 지니고 이를 관계인에게 내보여야 한다.', 4446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7818, '⑤ 제1항 및 제2항에 따른 조치 또는 검사는 그 목적 달성에 필요한 최소한에 그쳐야 한다.', 4446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7819, '① 행정청은 당사자가 납부기한까지 과태료를 납부하지 아니한 때에는 납부기한을 경과한 날부터 체납된 과태료에 대하여 100분의 3에 상당하는 가산금을 징수한다. <개정 2016.12.2>', 4448);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7820, '② 체납된 과태료를 납부하지 아니한 때에는 납부기한이 경과한 날부터 매 1개월이 경과할 때마다 체납된 과태료의 1천분의 12에 상당하는 가산금(이하 이 조에서 "중가산금"이라 한다)을 제1항에 따른 가산금에 가산하여 징수한다. 이 경우 중가산금을 가산하여 징수하는 기간은 60개월을 초과하지 못한다.', 4448);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7821, '③ 행정청은 당사자가 제20조제1항에 따른 기한 이내에 이의를 제기하지 아니하고 제1항에 따른 가산금을 납부하지 아니한 때에는 국세 또는 지방세 체납처분의 예에 따라 징수한다.', 4448);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7822, '④ 삭제 <2018.12.18>', 4448);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7823, '① 과태료는 당사자가 과태료 부과처분에 대하여 이의를 제기하지 아니한 채 제20조제1항에 따른 기한이 종료한 후 사망한 경우에는 그 상속재산에 대하여 집행할 수 있다.', 4449);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7824, '② 법인에 대한 과태료는 법인이 과태료 부과처분에 대하여 이의를 제기하지 아니한 채 제20조제1항에 따른 기한이 종료한 후 합병에 의하여 소멸한 경우에는 합병 후 존속한 법인 또는 합병에 의하여 설립된 법인에 대하여 집행할 수 있다.', 4449);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7825, '① 행정청은 당사자가 다음 각 호의 어느 하나에 해당하여 과태료(체납된 과태료와 가산금, 중가산금 및 체납처분비를 포함한다. 이하 이 조에서 같다)를 납부하기가 곤란하다고 인정되면 1년의 범위에서 대통령령으로 정하는 바에 따라 과태료의 분할납부나 납부기일의 연기(이하 "징수유예등"이라 한다)를 결정할 수 있다.', 4450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7826, '② 제1항에 따라 징수유예등을 받으려는 당사자는 대통령령으로 정하는 바에 따라 이를 행정청에 신청할 수 있다.', 4450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7827, '③ 행정청은 제1항에 따라 징수유예등을 하는 경우 그 유예하는 금액에 상당하는 담보의 제공이나 제공된 담보의 변경을 요구할 수 있고, 그 밖에 담보보전에 필요한 명령을 할 수 있다.', 4450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7828, '④ 행정청은 제1항에 따른 징수유예등의 기간 중에는 그 유예한 과태료 징수금에 대하여 가산금, 중가산금의 징수 또는 체납처분(교부청구는 제외한다)을 할 수 없다.', 4450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7829, '⑤ 행정청은 다음 각 호의 어느 하나에 해당하는 경우 그 징수유예등을 취소하고, 유예된 과태료 징수금을 한꺼번에 징수할 수 있다. 이 경우 그 사실을 당사자에게 통지하여야 한다.', 4450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7830, '⑥ 과태료 징수유예등의 방식과 절차, 그 밖에 징수유예등에 관하여 필요한 사항은 대통령령으로 정한다.', 4450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7831, '① 행정청은 당사자에게 다음 각 호의 어느 하나에 해당하는 사유가 있을 경우에는 결손처분을 할 수 있다.', 4451);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7832, '② 행정청은 제1항제2호에 따라 결손처분을 한 후 압류할 수 있는 다른 재산을 발견하였을 때에는 지체 없이 그 처분을 취소하고 체납처분을 하여야 한다.', 4451);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7833, '① 법원은 과태료 사건의 전부 또는 일부에 대하여 관할권이 없다고 인정하는 경우에는 결정으로 이를 관할 법원으로 이송한다.', 4454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7834, '② 당사자 또는 검사는 이송결정에 대하여 즉시항고를 할 수 있다.', 4454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7835, '① 법원은 심문기일을 열어 당사자의 진술을 들어야 한다.', 4458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7836, '② 법원은 검사의 의견을 구하여야 하고, 검사는 심문에 참여하여 의견을 진술하거나 서면으로 의견을 제출하여야 한다.', 4458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7837, '③ 법원은 당사자 및 검사에게 제1항에 따른 심문기일을 통지하여야 한다.', 4458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7838, '① 법원은 행정청의 참여가 필요하다고 인정하는 때에는 행정청으로 하여금 심문기일에 출석하여 의견을 진술하게 할 수 있다.', 4459);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7839, '② 행정청은 법원의 허가를 받아 소속 공무원으로 하여금 심문기일에 출석하여 의견을 진술하게 할 수 있다.', 4459);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7840, '① 법원은 직권으로 사실의 탐지와 필요하다고 인정하는 증거의 조사를 하여야 한다.', 4460);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7841, '② 제1항의 증거조사에 관하여는 「민사소송법」에 따른다.', 4460);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7842, '① 과태료 재판은 이유를 붙인 결정으로써 한다.', 4463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7843, '② 결정서의 원본에는 판사가 서명날인하여야 한다. 다만, 제20조제1항에 따른 이의제기서 또는 조서에 재판에 관한 사항을 기재하고 판사가 이에 서명날인함으로써 원본에 갈음할 수 있다.', 4463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7844, '③ 결정서의 정본과 등본에는 법원사무관등이 기명날인하고, 정본에는 법원인을 찍어야 한다.', 4463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7845, '④ 제2항의 서명날인은 기명날인으로 갈음할 수 있다.', 4463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7846, '① 결정은 당사자와 검사에게 고지함으로써 효력이 생긴다.', 4464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7847, '② 결정의 고지는 법원이 적당하다고 인정하는 방법으로 한다. 다만, 공시송달을 하는 경우에는 「민사소송법」에 따라야 한다.', 4464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7848, '③ 법원사무관등은 고지의 방법ㆍ장소와 연월일을 결정서의 원본에 부기하고 이에 날인하여야 한다.', 4464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7849, '① 당사자와 검사는 과태료 재판에 대하여 즉시항고를 할 수 있다. 이 경우 항고는 집행정지의 효력이 있다', 4465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7850, '② 검사는 필요한 경우에는 제1항에 따른 즉시항고 여부에 대한 행정청의 의견을 청취할 수 있다.', 4465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7851, '① 과태료 재판절차의 비용은 과태료에 처하는 선고가 있는 경우에는 그 선고를 받은 자의 부담으로 하고, 그 외의 경우에는 국고의 부담으로 한다.', 4468);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7852, '② 항고법원이 당사자의 신청을 인정하는 과태료 재판을 한 때에는 항고절차의 비용과 전심에서 당사자의 부담이 된 비용은 국고의 부담으로 한다.', 4468);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7853, '① 과태료 재판은 검사의 명령으로써 집행한다. 이 경우 그 명령은 집행력 있는 집행권원과 동일한 효력이 있다.', 4469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7854, '② 과태료 재판의 집행절차는 「민사집행법」에 따르거나 국세 또는 지방세 체납처분의 예에 따른다. 다만, 「민사집행법」에 따를 경우에는 집행을 하기 전에 과태료 재판의 송달은 하지 아니한다.', 4469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7855, '③ 과태료 재판의 집행에 대하여는 제24조 및 제24조의2를 준용한다. 이 경우 제24조의2제1항 및 제2항 중 "과태료 부과처분에 대하여 이의를 제기하지 아니한 채 제20조제1항에 따른 기한이 종료한 후"는 "과태료 재판이 확정된 후"로 본다. <개정 2011.4.5>', 4469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7856, '④ 검사는 제1항부터 제3항까지의 규정에 따른 과태료 재판을 집행한 경우 그 결과를 해당 행정청에 통보하여야 한다. <신설 2011.4.5>', 4469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7857, '① 검사는 과태료를 최초 부과한 행정청에 대하여 과태료 재판의 집행을 위탁할 수 있고, 위탁을 받은 행정청은 국세 또는 지방세 체납처분의 예에 따라 집행한다.', 4470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7858, '② 지방자치단체의 장이 제1항에 따라 집행을 위탁받은 경우에는 그 집행한 금원(金員)은 당해 지방자치단체의 수입으로 한다.', 4470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7859, '① 당사자와 검사는 제44조에 따른 약식재판의 고지를 받은 날부터 7일 이내에 이의신청을 할 수 있다.', 4472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7860, '② 검사는 필요한 경우에는 제1항에 따른 이의신청 여부에 대하여 행정청의 의견을 청취할 수 있다.', 4472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7861, '③ 제1항의 기간은 불변기간으로 한다.', 4472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7862, '④ 당사자와 검사가 책임질 수 없는 사유로 제1항의 기간을 지킬 수 없었던 경우에는 그 사유가 없어진 날부터 14일 이내에 이의신청을 할 수 있다. 다만, 그 사유가 없어질 당시 외국에 있던 당사자에 대하여는 그 기간을 30일로 한다.', 4472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7863, '① 이의신청은 대통령령으로 정하는 이의신청서를 제44조에 따른 약식재판을 한 법원에 제출함으로써 한다.', 4473);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7864, '② 법원은 제1항에 따른 이의신청이 있은 때에는 이의신청의 상대방에게 이의신청서 부본을 송달하여야 한다.', 4473);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7865, '① 이의신청을 한 당사자 또는 검사는 정식재판 절차에 따른 결정을 고지받기 전까지 이의신청을 취하할 수 있다.', 4474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7866, '② 이의신청의 취하는 대통령령으로 정하는 이의신청취하서를 제46조제1항에 따른 법원에 제출함으로써 한다. 다만, 심문기일에는 말로 할 수 있다.', 4474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7867, '③ 법원은 제46조제2항에 따라 이의신청서 부본을 송달한 뒤에 제1항에 따른 이의신청의 취하가 있은 때에는 그 상대방에게 이의신청취하서 부본을 송달하여야 한다.', 4474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7868, '① 법원은 이의신청이 법령상 방식에 어긋나거나 이의신청권이 소멸된 뒤의 것임이 명백한 경우에는 결정으로 이를 각하하여야 한다. 다만, 그 흠을 보정할 수 있는 경우에는 그러하지 아니하다.', 4475);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7869, '② 제1항의 결정에 대하여는 즉시항고를 할 수 있다.', 4475);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7870, null, 4476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7871, '① 법원이 이의신청이 적법하다고 인정하는 때에는 약식재판은 그 효력을 잃는다.', 4477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7872, '② 제1항의 경우 법원은 제31조제1항에 따른 심문을 거쳐 다시 재판하여야 한다.', 4477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7873, '① 행정청은 허가ㆍ인가ㆍ면허ㆍ등록 및 갱신(이하 "허가등"이라 한다)을 요하는 사업을 경영하는 자로서 다음 각 호의 사유에 모두 해당하는 체납자에 대하여는 사업의 정지 또는 허가등의 취소를 할 수 있다.', 4479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7874, '② 허가등을 요하는 사업의 주무관청이 따로 있는 경우에는 행정청은 당해 주무관청에 대하여 사업의 정지 또는 허가등의 취소를 요구할 수 있다.', 4479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7875, '③ 행정청은 제1항 또는 제2항에 따라 사업의 정지 또는 허가등을 취소하거나 주무관청에 대하여 그 요구를 한 후 당해 과태료를 징수한 때에는 지체 없이 사업의 정지 또는 허가등의 취소나 그 요구를 철회하여야 한다.', 4479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7876, '④ 제2항에 따른 행정청의 요구가 있는 때에는 당해 주무관청은 정당한 사유가 없는 한 이에 응하여야 한다.', 4479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7877, '① 행정청은 과태료 징수 또는 공익목적을 위하여 필요한 경우 「국세징수법」 제110조를 준용하여 「신용정보의 이용 및 보호에 관한 법률」 제25조제2항제1호에 따른 종합신용정보집중기관의 요청에 따라 체납 또는 결손처분자료를 제공할 수 있다. 이 경우 「국세징수법」 제110조를 준용할 때 "체납자"는 "체납자 또는 결손처분자"로, "체납자료"는 "체납 또는 결손처분 자료"로 본다. <개정 2009.4.1, 2018.12.18, 2020.2.4, 2020.12.29>', 4480);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7878, '② 행정청은 당사자에게 과태료를 납부하지 아니할 경우에는 체납 또는 결손처분자료를 제1항의 신용정보집중기관에게 제공할 수 있음을 미리 알려야 한다. <개정 2009.4.1, 2020.2.4>', 4480);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7879, '③ 행정청은 제1항에 따라 체납 또는 결손처분자료를 제공한 경우에는 대통령령으로 정하는 바에 따라 해당 체납자에게 그 제공사실을 통보하여야 한다.', 4480);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7880, '① 법원은 검사의 청구에 따라 결정으로 30일의 범위 이내에서 과태료의 납부가 있을 때까지 다음 각 호의 사유에 모두 해당하는 경우 체납자(법인인 경우에는 대표자를 말한다. 이하 이 조에서 같다)를 감치(監置)에 처할 수 있다.', 4481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7881, '② 행정청은 과태료 체납자가 제1항 각 호의 사유에 모두 해당하는 경우에는 관할 지방검찰청 또는 지청의 검사에게 체납자의 감치를 신청할 수 있다.', 4481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7882, '③ 제1항의 결정에 대하여는 즉시항고를 할 수 있다.', 4481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7883, '④ 제1항에 따라 감치에 처하여진 과태료 체납자는 동일한 체납사실로 인하여 재차 감치되지 아니한다.', 4481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7884, '⑤ 제1항에 따른 감치에 처하는 재판 절차 및 그 집행, 그 밖에 필요한 사항은 대법원규칙으로 정한다.', 4481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7885, '① 행정청은 「자동차관리법」 제2조제1호에 따른 자동차의 운행ㆍ관리 등에 관한 질서위반행위 중 대통령령으로 정하는 질서위반행위로 부과받은 과태료(이하 "자동차 관련 과태료"라 한다)를 납부하지 아니한 자에 대하여 체납된 자동차 관련 과태료와 관계된 그 소유의 자동차의 등록번호판을 영치할 수 있다.', 4482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7886, '② 자동차 등록업무를 담당하는 주무관청이 아닌 행정청이 제1항에 따라 등록번호판을 영치한  경우에는 지체 없이 주무관청에 등록번호판을 영치한 사실을 통지하여야 한다.', 4482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7887, '③ 자동차 관련 과태료를 납부하지 아니한 자가 체납된 자동차 관련 과태료를 납부한 경우 행정청은 영치한 자동차 등록번호판을 즉시 내주어야 한다.', 4482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7888, '④ 행정청은 제1항에 따라 자동차의 등록번호판이 영치된 당사자가 해당 자동차를 직접적인 생계유지 목적으로 사용하고 있어 자동차 등록번호판을 영치할 경우 생계유지가 곤란하다고 인정되는 경우 자동차 등록번호판을 내주고 영치를 일시 해제할 수 있다. 다만, 그 밖의 다른 과태료를 체납하고 있는 당사자에 대하여는 그러하지 아니하다. <신설 2016.12.2>', 4482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7889, '⑤ 제1항부터 제4항까지에서 규정한 사항 외에 자동차 등록번호판 영치의 요건ㆍ방법ㆍ절차, 영치 해제의 요건ㆍ방법ㆍ절차 및 영치 일시 해제의 기간ㆍ요건ㆍ방법ㆍ절차에 관하여 필요한 사항은 대통령령으로 정한다. <개정 2016.12.2>', 4482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7890, '① 제22조제2항에 따른 검사를 거부ㆍ방해 또는 기피한 자에게는 500만원 이하의 과태료를 부과한다.', 4484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7891, '② 제1항에 따른 과태료는 제22조에 따른 행정청이 부과ㆍ징수한다.', 4484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7892, '① 「질서위반행위규제법」(이하 "법"이라 한다) 제2조제1호가목에서 "대통령령으로 정하는 사법(私法)상ㆍ소송법상 의무를 위반하여 과태료를 부과하는 행위"란 「민법」, 「상법」 등 사인(私人) 간의 법률관계를 규율하는 법 또는 「민사소송법」, 「가사소송법」, 「민사집행법」, 「형사소송법」, 「민사조정법」 등 분쟁 해결에 관한 절차를 규율하는 법률상의 의무를 위반하여 과태료를 부과하는 행위를 말한다.', 4486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7893, '② 법 제2조제1호나목에서 "대통령령으로 정하는 법률에 따른 징계사유에 해당하여 과태료를 부과하는 행위"란 「공증인법」ㆍ「법무사법」ㆍ「변리사법」ㆍ「변호사법」 등 기관ㆍ단체 등이 질서 유지를 목적으로 구성원의 의무 위반에 대하여 제재를 할 수 있도록 규정하는 법률에 따른 징계사유에 해당하여 과태료를 부과하는 행위를 말한다.', 4486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7894, '① 행정청은 법 제16조에 따른 사전통지 및 의견 제출 결과 당사자가 다음 각 호의 어느 하나에 해당하는 경우에는 해당 과태료 금액의 100분의 50의 범위에서 과태료를 감경할 수 있다. 다만, 과태료를 체납하고 있는 당사자에 대해서는 그러하지 아니하다. <개정 2013.5.10, 2018.12.31>', 4487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7895, '② 법령상 감경할 사유가 여러 개 있는 경우라도 제1항에 따라 감경을 하는 경우에는 법 제18조에 따른 감경을 제외하고는 거듭 감경할 수 없다.', 4487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7896, '① 법 제16조제1항에 따라 행정청이 과태료 부과에 관하여 미리 통지하는 경우에는 다음 각 호의 사항을 모두 적은 서면(당사자가 동의하는 경우에는 전자문서를 포함한다)으로 하여야 한다. <개정 2009.12.15, 2013.5.10, 2021.1.26>', 4488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7897, '② 당사자는 제1항제4호의 의견제출 기한 이내에 서면(전자문서를 포함한다)으로 의견을 제출하거나 말로 의견을 진술할 수 있고, 그 주장을 증명하기 위하여 증거자료 등을 제출할 수 있다. <개정 2013.5.10>', 4488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7898, '③ 행정청은 당사자가 제2항에 따라 말로 의견을 진술한 경우에는 진술자와 그 의견의 요지를 기록해 두어야 한다. <개정 2013.5.10>', 4488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7899, null, 4489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7900, '① 법 제17조의2제1항에서 "대통령령으로 정하는 과태료 납부대행기관"이란 정보통신망을 이용하여 신용카드, 직불카드 등(이하 "신용카드등"이라 한다)에 의한 결제를 수행하는 기관으로서 다음 각 호의 어느 하나에 해당하는 기관을 말한다.', 4490);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7901, '② 납부대행기관은 법 제17조의2제3항에 따라 해당 과태료(법 제24조에 따른 가산금, 중가산금 및 체납처분비를 포함한다. 이하 이 조, 제7조의2부터 제7조의4까지 및 제14조의2에서 같다)금액의 1천분의 15를 초과하지 아니하는 범위에서 행정청이 승인한 납부대행 수수료를 받을 수 있다. 이 경우 행정청은 납부대행기관의 운영경비 등을 종합적으로 고려하여 납부대행 수수료를 승인하여야 한다.', 4490);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7902, '③ 행정청은 신용카드등에 의한 과태료의 납부에 필요한 사항을 정할 수 있다.', 4490);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7903, '① 행정청은 법 제22조제1항 각 호의 조치를 하려면 당사자 또는 참고인에게 다음 각 호의 내용을 모두 적은 서면으로 알려야 한다. <개정 2013.5.10>', 4492);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7904, '② 행정청은 제1항에도 불구하고 신속한 조사를 위하여 필요하면 전화, 팩스, 그 밖의 적절한 방법으로 법 제22조제1항 각 호의 조치를 할 수 있다.', 4492);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7905, '③ 행정청이 법 제22조제3항에 따라 검사를 위하여 사전통지를 하는 경우에는 다음 각 호의 사항을 적은 서면으로 한다. <개정 2013.5.10>', 4492);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7906, '① 행정청은 법 제24조의3제1항에 따라 과태료의 분할납부나 납부기일의 연기(이하 "징수유예등"이라 한다)를 결정하는 경우 그 기간을 그 징수유예등을 결정한 날의 다음 날부터 9개월 이내로 하여야 한다. 다만, 그 기간이 만료될 때까지 법 제24조의3제1항에 따른 징수유예등의 사유가 해소되지 아니하는 경우에는 1회에 한정하여 3개월의 범위에서 그 기간을 연장할 수 있다.', 4494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7907, '② 법 제24조의3제1항제9호에서 "대통령령으로 정하는 부득이한 사유가 있는 경우"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다.', 4494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7908, '③ 행정청은 제1항에 따라 징수유예등을 결정하는 경우 법 제24조의3제1항에 따른 징수유예등의 사유를 고려하여 납부기한의 연기, 분할납부의 횟수 및 금액을 정한다.', 4494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7909, '① 법 제24조의3제2항에 따라 징수유예등을 신청하거나 제7조의2제1항 단서에 따라 기간의 연장을 받으려는 당사자는 별지 제1호서식의 분할납부ㆍ납부기일의 연기ㆍ징수유예등 기간연장 신청서(전자문서를 포함한다)에 그 사유를 증명하는 서류를 첨부하여 행정청에 신청하여야 한다.', 4495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7910, '② 제1항에 따라 징수유예등 또는 징수유예등 기간 연장의 신청을 받은 행정청은 특별한 사정이 없는 한 그 신청을 받은 날부터 20일 이내에 결정하여 당사자에게 통지하여야 한다.', 4495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7911, '③ 행정청은 징수유예등의 사유가 있을 때에는 직권으로 징수유예등을 결정할 수 있다.', 4495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7912, '④ 징수유예등의 결정의 효력은 다음 각 호의 구분에 따른 날에 발생한다.', 4495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7913, '① 법 제24조의3제5항제4호에서 "대통령령으로 정하는 사유"란 다음 각 호의 어느 하나에 해당하는 사유를 말한다.', 4496);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7914, '② 법 제24조의3제5항에 따른 징수유예등 취소의 통지는 별지 제2호서식의 분할납부ㆍ납부기일의 연기 취소 통지서(당사자가 동의하는 경우에는 전자문서를 포함한다)로 한다.', 4496);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7915, '③ 행정청은 법 제24조의3제5항에 따라 징수유예등을 취소한 경우에는 그 과태료 징수금에 대하여 다시 징수유예등을 할 수 없다. 다만 법 제24조의3제5항제3호의 사유로 징수유예등을 취소한 경우는 그러하지 아니하다.', 4496);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7916, '① 법 제24조의4제1항제2호에서 "대통령령으로 정하는 경우"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다.', 4497);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7917, '② 행정청은 제1항에 따라 결손처분을 하려는 경우에는 체납자와 관계가 있다고 인정되는 행정기관에 체납자에 대한 실종선고 사실 또는 재산의 유무를 확인(「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통해 조회하여 확인하는 것을 포함한다)해야 한다.', 4497);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7918, '③ 행정청은 법 제24조의4제2항에 따라 결손처분을 취소했을 때에는 지체 없이 체납자에게 그 취소사실을 통지해야 한다.', 4497);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7919, '① 과태료의 징수 절차는 법 또는 이 영에 반하지 아니하는 범위에서 국고금관리법령 또는 지방재정ㆍ회계법령을 준용한다. <개정 2016.11.29>', 4498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7920, '② 제1항에도 불구하고 과태료의 징수 절차를 국고금관리법령 또는 지방재정ㆍ회계법령과 달리 정할 필요가 있는 경우에는 따로 총리령 또는 부령으로 정한다. <개정 2016.11.29>', 4498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7921, '① 법 제52조제1항제1호의 "횟수"와 "금액"은 각각 "3회"와 "500만원"으로 한다.', 4501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7922, '② 제1항의 과태료 체납 횟수는 과태료 부과고지서 1통을 1회로 보아 계산한다.', 4501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7923, '③ 법 제52조제1항제2호에서 "대통령령으로 정하는 특별한 사유"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다.', 4501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7924, '④ 행정청이 법 제52조제2항에 따라 관허사업의 제한을 요구할 때에는 다음 각 호의 사항을 적은 문서(전자문서를 포함한다)로 하여야 한다. <개정 2013.5.10>', 4501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7925, '⑤ 제4항의 요구를 받은 주무관청은 그 조치 결과를 지체 없이 해당 행정청에 알려야 한다.', 4501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7926, '① 법 제54조제1항제1호의 "횟수"와 "금액"은 각각 "3회"와 "1천만원"으로 한다.', 4503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7927, '② 제1항의 과태료 체납 횟수 계산에 관하여는 제11조제2항을 준용한다.', 4503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7928, '① 법 제55조제1항에서 "대통령령으로 정하는 질서위반행위로 부과받은 과태료"란 다음 각 호의 어느 하나에 해당하는 과태료를 말한다. <개정 2013.5.10, 2021.1.26>', 4504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7929, '② 법 제55조 및 이 조 제1항에 따라 행정청이 자동차 등록번호판을 영치할 수 있는 경우는 다음 각 호의 요건을 모두 충족하는 경우로 한정한다.', 4504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7930, '③ 행정청은 제2항에 따라 자동차 등록번호판을 영치할 때에는 미리 당사자에게 10일 이내에 자동차 관련 과태료를 납부하지 아니하면 즉시 등록번호판을 영치할 것이라는 뜻을 통지하여야 한다.', 4504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7931, '④ 제3항에 따른 통지는 다음 각 호의 사항을 모두 적은 서면(당사자가 동의하는 경우에는 전자문서를 포함한다)으로 하여야 한다. <개정 2013.5.10>', 4504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7932, '⑤ 행정청은 자동차 등록번호판을 영치하였을 때에는 당사자에게 다음 각 호의 사항을 모두 적은 영치증을 교부하여야 한다. 다만, 당사자가 영치증을 수령할 수 없거나 거부하는 경우에는 그러하지 아니하다. <개정 2013.5.10>', 4504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7933, '⑥ 법 제55조제2항에 따라 자동차 등록업무를 담당하는 주무관청이 아닌 행정청이 등록번호판을 영치한 사실을 주무관청에 통지할 때에는 제4항 각 호의 사항을 모두 적은 서면(전자문서를 포함한다)으로 하여야 한다. <개정 2013.5.10>', 4504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7934, '⑦ 행정청이 법 제55조제3항에 따라 등록번호판을 내줄 때에는 영치 원인이 된 자동차 관련 과태료(법 제24조에 따른 가산금 및 중가산금을 포함한다)의 납부증명서를 제출받아 그 납부 여부를 확인하여야 한다. 다만, 「전자정부법」 제36조제1항에 따른 행정정보 공동이용을 통하여 납부사실을 확인할 수 있는 경우에는 그러하지 아니하다.', 4504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7935, '⑧ 자동차 등록업무를 담당하는 주무관청이 아닌 행정청이 법 제55조제3항에 따라 자동차 등록번호판을 내주고 영치를 해제하였을 때에는 지체 없이 주무관청에 그 사실을 통지하여야 한다. <신설 2013.5.10>', 4504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7936, '① 행정청은 법 제55조제4항에 따라 자동차 등록번호판 영치를 일시 해제할 경우 그 기간을  9개월 이내로 하여야 한다. 다만, 그 기간이 만료될 때까지 법 제55조제4항 본문에 따른 일시 해제의 사유가 해소되지 아니하는 경우에는 1회에 한정하여 3개월의 범위에서 그 기간을 연장할 수 있다.', 4505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7937, '② 법 제55조제4항에 따라 자동차 등록번호판 영치의 일시 해제를 신청하거나 제1항 단서에 따라 자동차 등록번호판 영치의 일시 해제 기간을 연장받으려는 당사자는 별지 제6호서식의 자동차 등록번호판 영치의 일시 해제ㆍ자동차 등록번호판 영치의 일시 해제 기간연장 신청서(전자문서를 포함한다)에 다음 각 호의 서류를 첨부하여 행정청에 제출하여야 한다.', 4505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7938, '③ 제2항에 따라 자동차 등록번호판 영치의 일시해제 또는 자동차 등록번호판 영치의 일시 해제 기간연장의 신청을 받은 행정청은 특별한 사정이 없는 한 그 신청을 받은 날부터 20일 이내에 결정하여 당사자에게 통지하여야 한다.', 4505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7939, '④ 행정청은 제3항에 따라 자동차 등록번호판 영치의 일시 해제를 결정하는 경우 필요한 때에는 체납된 자동차 관련 과태료를 분할납부할 것을 조건으로 붙일 수 있다. 이 경우 분할납부의 기간은 제1항에 따른 자동차 등록번호판 영치의 일시해제 기간으로 하고, 분할납부의 횟수 및 금액은 당사자의 자동차 사용목적과 생계유지의 관련성 등을 고려하여 행정청이 정한다.', 4505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7940, '⑤ 행정청은 다음 각 호의 어느 하나에 해당하는 경우에는 자동차 등록번호판 영치의 일시 해제를 취소하고, 자동차 등록번호판을 다시 영치할 수 있다.', 4505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7941, '⑥ 자동차 등록업무를 담당하는 주무관청이 아닌 행정청이 법 제55조제4항에 따라 자동차 등록번호판의 영치를 일시 해제하거나 제5항에 따라 등록번호판을 다시 영치하는 경우에는 지체없이 주무관청에 그 사실을 통지하여야 한다.', 4505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7942, null, 4508);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7943, '①제3조에 해당하는 자중 보안관찰해당범죄를 다시 범할 위험성이 있다고 인정할 충분한 이유가 있어 재범의 방지를 위한 관찰이 필요한 자에 대하여는 보안관찰처분을 한다.', 4510);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7944, '②보안관찰처분을 받은 자는 이 법이 정하는 바에 따라 소정의 사항을 주거지 관할경찰서장(이하 "管轄警察署長"이라 한다)에게 신고하고, 재범방지에 필요한 범위안에서 그 지시에 따라 보안관찰을 받아야 한다.', 4510);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7945, '①보안관찰처분의 기간은 2년으로 한다.', 4511);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7946, '②법무부장관은 검사의 청구가 있는 때에는 보안관찰처분심의위원회의 의결을 거쳐 그 기간을 갱신할 수 있다.', 4511);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7947, '①보안관찰처분대상자는 대통령령이 정하는 바에 따라 그 형의 집행을 받고 있는 교도소, 소년교도소, 구치소, 유치장 또는 군교도소(이하 "矯導所등"이라 한다) 에서 출소전에 거주예정지 기타 대통령령으로 정하는 사항을 교도소등의 장을 경유하여 거주예정지 관할경찰서장에게 신고하고, 출소후 7일이내에 그 거주예정지 관할경찰서장에게 출소사실을 신고하여야 한다. 제20조제3항에 해당하는 경우에는 법무부장관이 제공하는 거주할 장소(이하 "居所"라 한다)를 거주예정지로 신고하여야 한다. <개정 2020.2.4>', 4512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7948, '②보안관찰처분대상자는 교도소등에서 출소한 후 제1항의 신고사항에 변동이 있을 때에는 변동이 있는 날부터 7일이내에 그 변동된 사항을 관할경찰서장에게 신고하여야 한다. 다만, 제20조제3항에 의하여 거소제공을 받은 자가 주거지를 이전하고자 할 때에는 미리 관할경찰서장에게 제18조제4항 단서에 의한 신고를 하여야 한다.', 4512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7949, '③교도소등의 장은 제3조에 해당하는 자가 생길 때에는 지체없이 보안관찰처분심의위원회와 거주예정지를 관할하는 검사 및 경찰서장에게 통고하여야 한다.', 4512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7950, '①제7조의 규정에 의한 보안관찰처분청구는 검사가 보안관찰처분청구서(이하 "處分請求書"라 한다)를 법무부장관에게 제출함으로써 행한다.', 4514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7951, '②처분청구서에는 다음 사항을 기재하여야 한다.', 4514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7952, '③검사가 처분청구서를 제출할 때에는 청구의 원인이 되는 사실을 증명할 수 있는 자료와 의견서를 첨부하여야 한다.', 4514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7953, '④검사는 보안관찰처분청구를 한 때에는 지체없이 처분청구서등본을 피청구자에게 송달하여야 한다. 이 경우 송달에 관하여는 민사소송법중 송달에 관한 규정을 준용한다.', 4514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7954, '①검사는 제7조의 규정에 의한 보안관찰처분청구를 위하여 필요한 때에는 보안관찰처분대상자, 청구의 원인이 되는 사실과 보안관찰처분을 필요로 하는 자료를 조사할 수 있다.', 4515);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7955, '②사법경찰관리와 특별사법경찰관리(이하 "司法警察官吏"라 한다)는 검사의 지휘를 받아 제1항의 규정에 의한 조사를 할 수 있다.', 4515);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7956, '①법무부장관은 처분청구서와 자료에 의하여 청구된 사안을 심사한다.', 4516);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7957, '②법무부장관은 제1항의 규정에 의한 심사를 위하여 필요한 때에는 법무부소속공무원으로 하여금 조사하게 할 수 있다.', 4516);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7958, '③제2항의 규정에 의하여 조사의 명을 받은 공무원은 다음 각호의 권한을 가진다.', 4516);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7959, '①법무부장관은 보안관찰처분대상자중 다음 각호의 요건을 갖춘 자에 대하여는 보안관찰처분을 하지 아니하는 결정(이하 "免除決定"이라 한다)을 할 수 있다.', 4517);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7960, '②법무부장관은 제1항의 요건을 갖춘 보안관찰처분대상자의 신청이 있을 때에는 부득이한 사유가 있는 경우를 제외하고는 3월내에 보안관찰처분면제여부를 결정하여야 한다.', 4517);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7961, '③검사는 제1항제1호 및 제2호의 요건을 갖춘 보안관찰처분대상자의 정상을 참작하여 위험성이 없다고 인정되는 때에는 법무부장관에게 면제결정을 청구할 수 있다.', 4517);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7962, '④면제결정을 받은 자가 그 면제결정요건에 해당하지 아니하게 된 때에는 검사의 청구에 의하여 법무부장관은 면제결정을 취소할 수 있다.', 4517);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7963, '⑤면제결정과 면제결정청구, 면제결정취소청구 및 그 결정에 대하여는 보안관찰처분청구 및 심사결정에 관한 규정을 준용한다.', 4517);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7964, '⑥보안관찰처분의 면제결정을 받은 자는 그때부터 이 법에 의한 보안관찰처분대상자 또는 피보안관찰자로서의 의무를 면한다.', 4517);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7965, '①보안관찰처분에 관한 사안을 심의ㆍ의결하기 위하여 법무부에 보안관찰처분심의위원회(이하 "委員會"라 한다)를 둔다.', 4518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7966, '②위원회는 위원장 1인과 6인의 위원으로 구성한다.', 4518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7967, '③위원장은 법무부차관이 되고, 위원은 학식과 덕망이 있는 자로 하되, 그 과반수는 변호사의 자격이 있는 자이어야 한다.', 4518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7968, '④위원은 법무부장관의 제청으로 대통령이 임명 또는 위촉한다.', 4518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7969, '⑤위촉된 위원의 임기는 2년으로 한다. 다만, 공무원인 위원은 그 직을 면한 때에는 위원의 자격을 상실한다.', 4518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7970, '⑥위원중 공무원이 아닌 위원도 이 법 기타 다른 법률의 규정에 의한 벌칙의 적용에 있어서는 공무원으로 본다.', 4518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7971, '⑦위원장은 위원회의 회무를 총괄하고 위원회를 대표하며, 위원회의 회의를 소집하고 그 의장이 된다. <개정 2016.1.19>', 4518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7972, '⑧위원장이 사고가 있을 때에는 미리 그가 지정한 위원이 그 직무를 대행한다.', 4518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7973, '⑨위원회는 다음 각호의 사안을 심의ㆍ의결한다.', 4518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7974, '⑩위원회의 회의는 위원장을 포함한 재적위원 과반수의 출석으로 개의하고 출석위원 과반수의 찬성으로 의결한다.', 4518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7975, '⑪위원회의 운영ㆍ서무 기타 필요한 사항은 대통령령으로 정한다.', 4518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7976, '①피청구자는 처분청구서등본을 송달받은 날부터 7일 이내에 법무부장관 또는 위원회에 서면으로 자기에게 이익된 사실을 진술하고 자료를 제출할 수 있다.', 4519);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7977, '②위원회는 필요하다고 인정하는 경우에는 피청구자 및 기타 관계자를 출석시켜 심문ㆍ조사하거나 공무소 기타 공ㆍ사단체에 대하여 조회할 수 있으며, 관계자료의 제출을 요구할 수 있다.', 4519);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7978, '①보안관찰처분에 관한 결정은 위원회의 의결을 거쳐 법무부장관이 행한다.', 4520);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7979, '②법무부장관은 위원회의 의결과 다른 결정을 할 수 없다. 다만, 보안관찰처분대상자에 대하여 위원회의 의결보다 유리한 결정을 하는 때에는 그러하지 아니하다.', 4520);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7980, '①위원회의 의결은 이유를 붙이고 위원장과 출석위원이 기명날인하는 문서로써 행한다.', 4521);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7981, '②법무부장관의 결정은 이유를 붙이고 법무부장관이 기명ㆍ날인하는 문서로써 행한다.', 4521);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7982, '①검사는 법무부장관에게 보안관찰처분의 취소 또는 기간의 갱신을 청구할 수 있다.', 4522);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7983, '②법무부장관은 제1항의 규정에 의한 청구를 받은 때에는 위원회의 의결을 거쳐 이를 심사ㆍ결정하여야 한다.', 4522);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7984, '③제1항 및 제2항의 규정에 의한 청구와 그 청구의 심사ㆍ결정에 대하여는 보안관찰처분청구 및 심사결정에 관한 규정을 준용한다.', 4522);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7985, '①보안관찰처분의 집행은 검사가 지휘한다.', 4523);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7986, '②제1항의 지휘는 결정서등본을 첨부한 서면으로 하여야 한다.', 4523);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7987, '③검사는 피보안관찰자가 도주하거나 1월 이상 그 소재가 불명한 때에는 보안관찰처분의 집행중지결정을 할 수 있다. 그 사유가 소멸된 때에는 지체없이 그 결정을 취소하여야 한다.', 4523);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7988, '①보안관찰처분을 받은 자(이하 "被保安觀察者"라 한다)는 보안관찰처분결정고지를 받은 날부터 7일 이내에 다음 각호의 사항을 주거지를 관할하는 지구대 또는 파출소의 장(이하 "지구대ㆍ파출소장"이라 한다)을 거쳐 관할경찰서장에게 신고하여야 한다. 제20조제3항에 해당하는 경우에는 법무부장관이 제공하는 거소를 주거지로 신고하여야 한다. <개정 2004.12.23, 2007.5.17>', 4524);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7989, '②피보안관찰자는 보안관찰처분결정고지를 받은 날이 속한 달부터 매3월이 되는 달의 말일까지 다음 각호의 사항을 지구대ㆍ파출소장을 거쳐 관할경찰서장에게 신고하여야 한다. <개정 2004.12.23>', 4524);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7990, '③피보안관찰자는 제1항의 신고사항에 변동이 있을 때에는 7일 이내에 지구대ㆍ파출소장을 거쳐 관할경찰서장에게 신고하여야 한다. 피보안관찰자가 제1항의 신고를 한 후 제20조제3항에 의하여 거소제공을 받거나 제20조제5항에 의하여 거소가 변경된 때에는 제공 또는 변경된 거소로 이전한 후 7일 이내에 지구대ㆍ파출소장을 거쳐 관할경찰서장에게 신고하여야 한다. <개정 2004.12.23>', 4524);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7991, '④피보안관찰자가 주거지를 이전하거나 국외여행 또는 10일 이상 주거를 이탈하여 여행하고자 할 때에는 미리 거주예정지, 여행예정지 기타 대통령령이 정하는 사항을 지구대ㆍ파출소장을 거쳐 관할경찰서장에게 신고하여야 한다. 다만, 제20조제3항에 의하여 거소제공을 받은 자가 주거지를 이전하고자 할 때에는 제20조제5항에 의하여 거소변경을 신청하여 변경결정된 거소를 거주예정지로 신고하여야 한다. <개정 2004.12.23>', 4524);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7992, '⑤관할경찰서장은 제1항 내지 제4항의 규정에 의한 신고를 받은 때에는 신고필증을 교부하여야 한다.', 4524);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7993, '①검사 및 사법경찰관리는 피보안관찰자의 재범을 방지하고 건전한 사회복귀를 촉진하기 위하여 다음 각호의 지도를 할 수 있다.', 4525);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7994, '②검사 및 사법경찰관은 피보안관찰자의 재범방지를 위하여 특히 필요한 경우에는 다음 각호의 조치를 할 수 있다.', 4525);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7995, '①검사 및 사법경찰관리는 피보안관찰자가 자조의 노력을 함에 있어, 그의 개선과 자위를 위하여 필요하다고 인정되는 적절한 보호를 할 수 있다.', 4526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7996, '②제1항의 보호의 방법은 다음과 같다.', 4526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7997, '③법무부장관은 보안관찰처분대상자 또는 피보안관찰자중 국내에 가족이 없거나 가족이 있어도 인수를 거절하는 자에 대하여는 대통령령이 정하는 바에 의하여 거소를 제공할 수 있다.', 4526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7998, '④사회복지사업법에 의한 사회복지시설로서 대통령령이 정하는 시설의 장은 법무부장관으로부터 보안관찰처분대상자 또는 피보안관찰자에 대한 거소제공의 요청을 받은 때에는 정당한 이유없이 이를 거부하여서는 아니된다.', 4526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (7999, '⑤법무부장관은 제3항에 의하여 거소제공을 받은 자에게 국내에 인수를 희망하는 가족이 생기거나 기타 거소변경의 필요가 있는 때에는 본인의 신청 또는 검사의 청구에 의하여 이미 제공한 거소를 변경할 수 있다. 이 경우 법무부장관은 3월 이내에 거소의 변경여부를 결정하여야 한다.', 4526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8000, '①보안관찰처분의 기간은 보안관찰처분 결정을 집행하는 날부터 계산한다. 이 경우 초일은 산입한다.', 4531);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8001, '②제18조제1항 내지 제4항의 규정에 의한 신고를 하지 아니한 기간은 보안관찰처분 기간에 산입하지 아니한다.', 4531);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8002, '③보안관찰처분의 집행중지결정이 있거나 징역ㆍ금고ㆍ구류ㆍ노역장유치 중에 있는 때, 「사회보호법」에 의한 감호의 집행 중에 있는 때 또는 「치료감호법」에 의한 치료감호의 집행 중에 있는 때에는 보안관찰처분의 기간은 그 진행이 정지된다. <개정 2005.8.4>', 4531);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8003, '①군사법원법 제2조제1항 각호의 1에 게기된 자에 대한 보안관찰처분에 관하여는 국방부장관은 법무부장관의, 군검찰부 군검사는 검사의, 군사법경찰관리는 사법경찰관리의 이 법에 의한 직무를 행한다. <개정 2016.1.6>', 4532);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8004, '②군사법원법 제2조제1항 각호의 1에 게기된 자에 대한 보안관찰처분을 심의ㆍ의결하기 위하여 국방부에 군보안관찰처분심의위원회를 둔다.', 4532);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8005, '③군보안관찰처분심의위원회의 구성과 운영에 관하여는 제12조의 규정을 준용한다.', 4532);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8006, '④국방부장관 또는 군검찰부 군검사는 보안관찰처분대상자가 군사법원법 제2조제1항 각호의 1에 게기된 자가 아님이 명백한 때에는 당해 사안을 법무부장관 또는 검사에게 이송한다. 이 경우 이송전에 한 심사 또는 조사는 이송후에도 그 효력에 영향이 없다. <개정 2016.1.6>', 4532);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8007, '⑤법무부장관 또는 검사는 보안관찰처분대상자가 군사법원법 제2조제1항 각호의 1에 게기된 자임이 명백한 때에는 당해 사안을 국방부장관 또는 군검찰부 군검사에게 이송한다. 이 경우 이송전에 한 심사 또는 조사는 이송후에도 그 효력에 영향이 없다. <개정 2016.1.6>', 4532);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8008, '①보안관찰처분대상자 또는 피보안관찰자가 보안관찰처분 또는 보안관찰을 면탈할 목적으로 은신 또는 도주한 때에는 3년 이하의 징역에 처한다.', 4533);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8009, '②정당한 이유없이 제6조제1항ㆍ제2항 및 제18조제1항 내지 제4항의 규정에 의한 신고를 하지 아니하거나 허위의 신고를 한 자 또는 그 신고를 함에 있어서 거주예정지나 주거지를 명시하지 아니한 자는 2년 이하의 징역 또는 100만원 이하의 벌금에 처한다.', 4533);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8010, '③정당한 이유없이 제19조제2항의 조치에 위반한 자는 1년 이하의 징역 또는 50만원 이하의 벌금에 처한다.', 4533);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8011, '④제20조제4항에 위반한 자는 6월 이하의 징역 또는 50만원 이하의 벌금에 처한다.', 4533);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8012, '⑤보안관찰처분에 관한 업무에 종사하는 공무원이 정당한 이유없이 그 직무수행을 거부 또는 그 직무를 유기하거나 허위의 보고를 한 때에는 2년 이하의 징역 또는 5년 이하의 자격정지에 처한다.', 4533);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8013, '⑥보안관찰처분대상자 또는 피보안관찰자를 은닉하거나 도주하게 한 자는 2년 이하의 징역에 처한다. 다만, 친족이 본인을 위하여 본문의 죄를 범한 때에는 벌하지 아니한다. <개정 2005.3.31>', 4533);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8014, '⑦보안관찰처분의 업무에 종사하는 공무원 또는 제11조의 신원보증을 한 자가 정당한 사유없이 보안관찰처분대상자에 관하여 이 법에 의하여 지득한 사실을 공표하거나 누설한 때에는 2년 이하의 징역 또는 5년 이하의 자격정지에 처한다.', 4533);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8015, null, 4535);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8016, '①피보안관찰자의 주거지를 관할하는 경찰서장(이하 "관할경찰서장"이라 한다)은 피보안관찰자의 동태를 관찰하고 사회에 복귀하도록 선도하여 보안관찰해당범죄를 다시 범하지 아니하도록 예방하여야 한다.', 4537);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8017, '②관할경찰서장은 보안관찰부를 작성ㆍ비치하고 매월 1회이상 피보안관찰자의 동태를 관찰하여 그 결과를 보안관찰부에 기재하여야 한다.', 4537);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8018, '①관할경찰서장은 매 3월마다 법 제18조제2항의 규정에 의하여 신고된 사항을 포함한 피보안관찰자의 주요동태를 주거지 관할검사에게 보고하여야 한다.', 4538);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8019, '②관할경찰서장은 피보안관찰자에게 다음 각호의 1에 해당하는 사유가 발생한 때에는 지체없이 이를 주거지 관할검사에게 보고하여야 한다.', 4538);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8020, '①보안관찰처분대상자가 법 제6조제1항의 규정에 의하여 출소전에 신고할 때에는 다음 각호의 사항을 기재한 신고서 5부를 작성하여 교도소, 소년교도소, 구치소, 유치장 또는 군교도소(이하 "교도소등"이라 한다)의 장에게 제출하여야 한다. <개정 2020.7.28>', 4539);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8021, '②교도소등의 장은 제1항의 규정에 의하여 접수한 신고서 1부씩을 법 제12조의 규정에 의한 보안관찰처분심의위원회(이하 "위원회"라 한다)와 거주예정지관할 검사 및 경찰서장에게 각각 송부하여야 한다.', 4539);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8022, '③교도소등의 장은 제2항의 규정에 의하여 신고서를 송부할 때에는 보안관찰해당범죄에 대한 판결문사본ㆍ행형성적 기타 필요한 서류를 각각 첨부하여야 한다.', 4539);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8023, '①교도소등의 장은 법 제6조제1항의 규정에 의하여 보안관찰처분대상자 신고를 한 자가 출소한 때에는 지체없이 다음 각호의 사항을 거주예정지 관할경찰서장에게 통보하여야 한다.', 4541);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8024, '②거주예정지 관할경찰서장은 출소한 보안관찰처분대상자가 법 제6조제1항의 규정에 의한 신고기간내에 신고를 하지 아니한 때에는 지체없이 이를 거주예정지 관할검사에게 보고하여야 한다.', 4541);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8025, '① 출소한 보안관찰처분대상자는 법 제6조제1항에 따라 출소사실을 신고할 때에는 출소일ㆍ출소교도소ㆍ출소사유와 그 밖에 필요한 사항을 기재한 신고서를 작성ㆍ제출해야 하며, 신고서에는 2명 이상의 신원보증인이 서명ㆍ날인해야 한다. 이 경우 신원보증인이 없는 경우에는 그 사유를 명확히 기재해야 한다. <개정 2021.1.5>', 4542);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8026, '②보안관찰처분대상자는 교도소등에서 출소한 후 제6조제1항의 신고사항중에 변동이 있는 때에는 그 변동사항을 기재한 신고서를 작성하여 관할경찰서장에게 제출하여야 한다.', 4542);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8027, '③제1항 및 제2항의 신고서를 접수한 거주예정지 관할경찰서장 또는 관할경찰서장은 신고인에게 신고필증을 교부하여야 하며, 지체없이 이를 그 거주예정지 또는 주거지 관할검사에게 보고하여야 한다.', 4542);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8028, '④거주예정지 관할경찰서장 또는 관할경찰서장은 보안관찰처분대상자가 신고한 거주예정지를 변경하거나 주거지를 이전한 때에는 그 사실여부를 확인한 후 보안관찰처분대상자신고서ㆍ출소사실신고서 기타 관계서류를 변경된 거주예정지 또는 신주거지 관할경찰서장에게 송부하여야 한다.', 4542);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8029, '⑤제4항의 규정에 의하여 관계서류를 송부받은 변경된 거주예정지 또는 신주거지 관할경찰서장은 지체없이 이를 주거지 관할검사에게 보고하여야 한다.', 4542);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8030, '①교도소등의 장은 법 제6조제3항의 규정에 의한 통고를 할 때에는 다음 각호의 사항을 기재한 통고서를 작성하여 위원회와 거주예정지 관할검사 및 경찰서장에게 송부하여야 한다.', 4543);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8031, '②교도소등의 장은 수용되어 있는 보안관찰처분대상자에 대하여 다음 각호의 1에 해당하는 사유가 발생한 때에는 지체없이 이를 위원회와 거주예정지 관할검사 및 경찰서장에게 통보하여야 한다.', 4543);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8032, null, 4544);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8033, '①법 제8조제1항의 규정에 의한 보안관찰처분청구서에는 피청구자의 성명 기타 피청구자를 특정할 수 있는 사항ㆍ청구의 원인이 되는 사실ㆍ청구연월일을 기재하고 검사가 서명ㆍ날인하여야 한다. 이 경우 법 제20조제3항의 규정에 의하여 거소를 제공한 때에는 거소제공 결정연월일 및 제공된 사회복지시설등의 명칭과 그 소재지를 함께 기재하여야 한다.', 4545);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8034, '②법 제8조제3항의 의견서에는 청구취지와 적용법조에 관한 의견을 기재하여야 한다.', 4545);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8035, null, 4546);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8036, '①법 제11조제2항에 따른 보안관찰처분면제결정 신청을 하려는 보안관찰처분대상자는 관할경찰서장에게 다음 각 호의 서류를 첨부한 보안관찰처분면제결정신청서(전자문서로 된 신청서를 포함한다)를 제출해야 한다. 이 경우 관할경찰서장은 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 보안관찰처분대상자의 주민등록표 등본을 확인해야 하며, 보안관찰처분대상자가 확인에 동의하지 않는 경우에는 이를 첨부하도록 해야 한다. <개정 2004.3.17, 2007.7.18, 2010.5.4, 2010.11.2, 2019.10.8>', 4547);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8037, '②관할경찰서장은 제1항의 규정에 의한 신청서를 접수한 때에는 20일이내에 전과관계를 증명할 수 있는 서류와 의견서를 첨부하여 검사에게 송부하여야 한다.', 4547);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8038, '③검사는 제2항의 규정에 의하여 신청서와 관계서류를 송부받은 때에는 20일이내에 의견서를 첨부하여 법무부장관에게 송부하여야 한다.', 4547);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8039, '④제1항제4호의 규정에 의한 신원보증인이 될 수 있는 자는 보안관찰처분대상자가 아닌 자로서 다음 각호의 1에 해당하는 자이어야 한다.', 4547);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8040, '⑤검사는 법 제11조제3항의 규정에 의한 보안관찰처분면제결정 청구를 함에 있어서는 보안관찰처분면제결정청구서에 보안관찰처분대상자가 법 제11조제1항제1호 및 제2호에 해당한다는 의견서와 기타 필요한 서류를 첨부하여 법무장관에게 제출하여야 한다.', 4547);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8041, '①법무부장관은 법 제12조제9항 각호의 1에 해당하는 결정의 신청을 받은 때에는 이를 심사한 후 지체없이 위원회에 그 사안을 회부하여야 한다.', 4548);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8042, '②위원회는 제1항의 규정에 의하여 사안을 회부받은 때에는 이를 심의ㆍ의결하고 그 결과를 위원장과 출석위원 전원이 서명ㆍ날인한 문서로써 법무부장관에게 통보하여야 한다.', 4548);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8043, '①위원회에 간사 2인과 서기 약간인을 둔다.', 4549);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8044, '②간사 및 서기는 법무부소속 직원중에서 법무부장관이 임명한다.', 4549);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8045, '③간사는 위원장의 명을 받아 위원회의 서무를 처리하고 회의에 참석하여 발언할 수 있으며, 서기는 간사를 보조한다.', 4549);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8046, '①서기는 위원장의 명을 받아 위원회의 회의록을 작성ㆍ비치하여야 한다.', 4550);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8047, '②회의록에는 회의의 전말을 기재하고 위원장이 서명ㆍ날인하여야 한다.', 4550);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8048, '①관할경찰서장은 법 제17조제3항의 규정에 의한 사유가 발생한 때에는 주거지 관할검사에게 주거지 리ㆍ통ㆍ반의 장의 확인서 기타 피보안관찰자가 도주 또는 소재불명임을 인정할 수 있는 자료를 첨부하여 보안관찰처분집행중지결정을 신청하여야 한다. 이 경우 주거지 관할검사는 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 피보안관찰자의 주민등록표 등본을 확인하여야 한다. <개정 2004.3.17, 2007.7.18, 2010.5.4, 2010.11.2>', 4556);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8049, '②검사는 법 제17조제3항 전단의 규정에 의하여 보안관찰처분의 집행중지결정을 할 때에는 피보안관찰자의 성명 기타 피보안관찰자를 특정할 수 있는 사항, 보안관찰처분 결정일 및 그 기간갱신일, 집행중지사유, 집행중지결정일 기타 필요한 사항을 기재한 보안관찰처분 집행중지결정서를 작성하여야 한다.', 4556);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8050, '③검사는 보안관찰처분의 집행중지결정을 한 때에는 관할경찰서장에게 보안관찰처분 집행중지결정의 집행지휘를 하고 지체없이 이를 법무부장관에게 보고하여야 한다.', 4556);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8051, '④검사는 법 제17조제3항 후단의 규정에 의하여 보안관찰처분의 집행중지결정을 취소할 때에는 피보안관찰자의 성명 기타 피보안관찰자를 특정할 수 있는 사항, 집행중지결정일, 집행중지결정취소사유, 취소결정일 기타 필요한 사항을 기재한 보안관찰처분집행중지 취소결정서를 작성하여야 한다.', 4556);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8052, '⑤피보안관찰자는 검사의 보안관찰처분 집행중지결정에 이의가 있거나 그 집행중지결정의 사유가 소멸된 때에는 관할경찰서장을 거쳐 검사에게 보안관찰처분 집행중지결정의 취소신청을 할 수 있다.', 4556);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8053, '⑥검사는 제5항의 취소신청이 이유있다고 인정하는 때에는 보안관찰처분의 집행중지결정을 취소하고 지체없이 이를 신청인에게 고지하여야 한다. 신청이 이유없다고 인정하여 기각하는 때에는 그 취지를 고지하여야 한다.', 4556);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8054, '⑦검사는 제4항 및 제6항의 규정에 의한 취소를 한 때에는 관할경찰서장에게 보안관찰처분 집행중지결정의 취소지휘 또는 보안관찰처분의 잔기간집행지휘를 하고 지체없이 이를 법무부장관에게 보고하여야 한다.', 4556);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8055, '①법 제18조제1항제8호의 규정에 의하여 피보안관찰자가 신고하여야 할 사항은 다음과 같다.', 4557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8056, '②피보안관찰자는 법 제18조제4항의 규정에 의한 신고를 할 때에는 다음 각호의 구분에 따라 관련사항을 기재한 신고서를 작성ㆍ제출하여야 한다.', 4557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8057, '③관할경찰서장은 제2항제1호 및 제3호의 규정에 의한 신고서를 접수한 때에는 지체없이 그 사실을 이전예정지 또는 여행목적지 관할경찰서장에게 통보하여야 한다.', 4557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8058, '④관할경찰서장은 피보안관찰자가 주거지를 이전한 때에는 지체없이 신주거지 관할경찰서장에게 보안관찰부 기타 관계서류를 송부하여야 한다.', 4557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8059, '⑤제4항의 규정에 의하여 관계서류를 송부받은 신거주지 관할경찰서장은 지체없이 그 주거지 이전의 사실을 신주거지 관할검사에게 보고하여야 한다.', 4557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8060, '①검사 및 사법경찰관리는 피보안관찰자의 재범을 방지하고 건전한 사회복귀를 촉진하기 위하여 피보안관찰자와의 면접과 통신, 가족 및 그 관계인과의 협의, 거소제공된 사회복지시설등의 장 및 관계기관과의 협조에 의하여 계속적으로 관찰ㆍ지도하여야 하며, 피보안관찰자 및 그 관계인의 신뢰와 협력을 얻도록 노력하여야 한다.', 4558);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8061, '②검사 및 사법경찰관은 법 제19조제2항의 규정에 의하여 피보안관찰자의 재범방지를 위한 조치를 할 때에는 피보안관찰자에게 조치의 취지를 설명하고 조치사항을 기재한 서면을 교부하여야 한다.', 4558);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8062, '③사법경찰관은 제2항의 조치를 할 때에는 긴급을 요하는 경우를 제외하고는 미리 주거지 관할검사에게 보고하여야 한다.', 4558);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8063, '④제2항의 조치는 피보안관찰자의 재범방지를 위하여 특히 필요하다고 인정되는 구체적 사항으로서 피보안관찰자의 자유를 부당하게 제한하지 아니하도록 하여야 한다.', 4558);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8064, '①법 제20조제3항의 규정에 의한 거소제공은 검사의 청구에 의하여 법무부장관이 결정한다.', 4559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8065, '②교도소등의 장은 수용중인 보안관찰처분대상자 또는 피보안관찰자중 거소제공이 필요한 자(이하 "거소제공대상자"라 한다)가 생긴 때에는 특별한 사유가 있는 경우를 제외하고는 출소예정일 2월전까지 교도소등의 소재지 관할검사에게 거소제공의 청구를 신청하여야 한다.', 4559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8066, '③관할경찰서장은 그 관할구역내에 거소제공대상자가 생긴때에는 지체없이 주거지 관할검사에게 거소제공의 청구를 신청하여야 한다.', 4559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8067, '④교도소등의 장 및 관할경찰서장은 제2항 또는 제3항의 규정에 의한 신청을 하는 때에는 거소제공대상자의 성명 기타 거소제공대상자임을 특정할 수 있는 사항, 거소제공의 필요사유, 행형성적 또는 최근의 동태를 기재한 신청서와 거소제공에 필요한 자료를 제출하여야 한다.', 4559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8068, '⑤검사는 법무부장관에게 거소제공을 청구하는 때에는 청구서와 거소제공에 필요한 자료를 제출하여야 한다.', 4559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8069, '⑥법무부장관은 거소제공대상자에 대하여 거소제공이 필요하다고 인정하는 때에는 사회복지사업법에 의한 사회복지시설 기타 본인의 건전한 사회복귀를 위하여 도움이 되는 적절한 시설을 지정하여야 한다.', 4559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8070, '⑦검사는 법무부장관이 제6항의 규정에 의하여 거소제공의 결정을 한 때에는 지체없이 교도소등의 장 또는 관할 경찰서장, 사회복지시설등의 장에게 결정내용 및 결정일을 통보하여야 한다.', 4559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8071, '⑧거소제공대상자에 대한 거소제공결정의 고지는 검사가 거소제공결정서등본을 송달하는 방법으로 한다.', 4559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8072, '⑨교도소등의 장은 거소제공대상자가 출소하는 때에 지체없이, 관할경찰서장은 거소제공결정의 통보를 받은 때에 지체없이 거소제공결정을 받은 보안관찰처분대상자 또는 피보안관찰자를 지정된 사회복지시설등의 장에게 인계하고 즉시 이를 검사에게 보고하여야 한다.', 4559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8073, '①거소제공을 받은 자는 법 제20조제5항의 규정에 의하여 거소변경을 신청하는 때에는 관할경찰서장에게 거소변경 신청서와 거소변경이 필요함을 인정할 수 있는 서류를 제출하여야 한다.', 4560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8074, '②관할경찰서장은 제1항의 규정에 의하여 신청서와 관계서류를 접수한 때에는 20일이내에 의견서와 거소변경에 필요한 자료를 첨부하여 주거지 관할 검사에게 송부하여야 한다.', 4560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8075, '③검사는 제2항의 규정에 의하여 신청서와 관계서류를 송부받은 때에는 20일이내에 의견서와 거소변경에 필요한 자료를 첨부하여 법무부장관에게 송부하여야 한다.', 4560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8076, '④검사는 법 제20조제5항의 규정에 의하여 거소변경의 청구를 하는 때에는 법무부장관에게 거소변경 청구서와 의견서 및 거소변경에 필요한 자료를 제출하여야 한다.', 4560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8077, '⑤제26조제6항 내지 제9항의 규정은 법무부장관이 거소변경결정을 하는 경우에 이를 준용한다.', 4560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8078, '①검사는 긴급을 요하여 법무부장관의 거소제공결정 또는 거소변경결정을 기다릴 여유가 없는 때에는 사회복지시설등의 장과 협의하여 거소제공대상자에게 임시거소를 제공할 수 있다.', 4561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8079, '②검사는 제1항의 규정에 의한 임시거소의 제공을 한 때에는 지체없이 이를 법무부장관에게 보고하여야 한다.', 4561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8080, '①법 제20조제4항의 사회복지시설은 사회복지사업법에 의한 사회복지시설중 기거와 침식을 제공할 수 있는 시설로 한다.', 4562);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8081, '②법무부장관은 제1항의 시설을 거소로 지정하는 때에는 보건복지부장관의 의견을 들어야 한다. <개정 1994.12.23, 2008.2.29, 2010.3.15>', 4562);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8082, '③사회복지시설등의 장은 보호하고 있는 보안관찰처분대상자 또는 피보안관찰자에 대하여 다음 각호의 1에 해당하는 사유가 발생한 때에는 지체없이 이를 관할경찰서장에게 통보하여야 한다.', 4562);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8083, '①법 제21조의 규정에 의한 응급구호는 다음 각호의 1에 해당하는 경우에 실시할 수 있다.', 4563);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8084, '②사법경찰관리는 제1항의 규정에 의한 응급구호를 행한 때에는 지체없이 이를 검사에게 보고하여야 한다.', 4563);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8085, null, 4569);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8086, '①영 제6조제1항의 규정에 의한 보안관찰처분대상자 신고서는 별지 제3호서식에 의한다.', 4572);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8087, '②영 제6조제1항의 교도소등의 장(이하 "교도소등의 장"이라 한다)은 동조동항의 규정에 의하여 제출받은 신고서 중 1부를 국가안전기획부장에게 송부하고 1부는 보존하며, 별지 제4호서식의 신고서 송부부를 작성ㆍ비치하여야 한다.', 4572);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8088, '③교도소등의 장은 제2항 및 영 제6조제2항의 규정에 의하여 신고서를 송부하는 때에는 특별한 사유가 있는 경우를 제외하고는 보안관찰처분대상자의 출소예정일  2월전까지 이를 송부하여야 한다.', 4572);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8089, '④영 제6조제2항의 규정에 의하여 신고서를 송부받은 거주예정지 관할경찰서장은 보안관찰처분대상자가 출소 후 거주예정지에 거주하지 아니할 것이 명백한 때에는 지체없이 그 사유를 교도소등의 장에게 통보하여야 한다.', 4572);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8090, '⑤제4항의 규정에 의한 통보를 받은 교도소등의 장은 지체없이 이를 교도소등의 소재지 관할검사에게 보고하여야 한다.', 4572);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8091, '⑥영 제6조제2항의 규정에 의하여 신고서를 송부받은 거주예정지 관할경찰서장은  별지 제5호서식의 신고서 접수부와 별지 제6호서식의 보안관찰처분대상자 관리부를 작성ㆍ비치하여야 한다.', 4572);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8092, '⑦영 제6조제2항의 규정에 의한 보안관찰처분대상자신고서의 송부는 별지 제7호서식에 의한다.', 4572);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8093, '①거주예정지 관할경찰서장은 영 제8조제1항의 규정에 의한 출소통보를 받거나 영 제8조제2항의 규정에 의한 보고를 한 때에는 보안관찰처분대상자 관리부에 그 내용을 기재하여야 한다.', 4573);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8094, '②영 제8조제1항의 규정에 의한 출소통보는 별지 제8호서식, 영 제8조제2항의 규정에 의한 보고는 별지 제9호서식에 의한다.', 4573);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8095, '①거주예정지 관할경찰서장 또는 관할경찰서장은 영 제9조제1항의 규정에 의한 신고사항과 영 제9조제2항의 규정에 의한 신고사항을 보안관찰처분대상자 관리부에 기재하여야 한다.', 4574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8096, '②영 제9조제1항의 규정에 의한 신고서는 별지 제10호서식, 영 제9조제2항의 규정에 의한 신고서는 별지 제11호서식, 영 제9조제3항의 규정에 의한 신고필증은 별지 제12호서식, 영 제9조제3항 및 제5항의 규정에 의한 보고는 별지 제9호서식에 의한다.', 4574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8097, '①교도소등의 장은 보안관찰처분대상자가 입소한 때에는 별지 제13호서식의 보안관찰처분대상자 관리부를 작성ㆍ비치하여야 한다.', 4575);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8098, '②교도소등의 장은 보안관찰처분대상자 관리부에 영 제10조제1항의 규정에 의한 통고서송부사실과 영 제10조제2항의 규정에 의한 통보사유를 기재하여야 한다.', 4575);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8099, '③교도소등의 장은 보안관찰처분대상자에 대하여 영 제10조제2항제4호의 사유가 발생한 때에는 보안관찰처분대상자 관리부와 관계서류를 이송된 교도소등의 장에게 송부하여야 한다.', 4575);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8100, '④영 제10조 제1항의 규정에 의한 통고서는 별지 제14호서식, 영 제10조제2항의 규정에 의한 통보는 별지 제15호서식에 의한다.', 4575);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8101, '①관할경찰서장은 그 관할구역내에 거주하는 보안관찰처분대상자에게 영 제11조 각호의1에 해당하는 사유가 발생한 때에는 보안관찰처분대상자관리부에 그 내용을 기재하여야 한다.', 4576);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8102, '②영 제11조의 규정에 의한 보고는 별지 제9호서식에 의한다.', 4576);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8103, '①검사는 직무를 수행함에 있어 상호 협조하여야 한다.', 4579);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8104, '②사법경찰관리는 직무를 수행함에 있어 상호 협조하여야 한다.', 4579);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8105, '①조사서류를 작성할 때에는 내용의 정확과 진술의 임의성을 확보하기 위하여 특히 다음 각호의 사항에 유의하여야 한다.', 4582);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8106, '②조사서류의 작성에 관하여는 이 규칙에서 규정한 사항외에 형사소송법 제47조ㆍ제48조ㆍ제50조와 제57조 내지 제59조의 규정을 준용한다.', 4582);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8107, '①검사는 보안관찰처분대상자가 보안관찰해당범죄를 다시 범할 위험성이 있다고 의심하여 조사에 착수하는 때에는 사안인지서를 작성하여야 한다.', 4584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8108, '②사법경찰관이 제1항의 조사에 착수하고자 하는 때에는 사안인지승인신청서를 작성하여 검사의 승인을 얻어야 한다.', 4584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8109, '③제1항의 규정에 의한 사안인지서와 제2항의 규정에 의한 사안인지승인신청서에는 용의자의 주거ㆍ성명ㆍ연령ㆍ직업ㆍ주민등록번호, 보안관찰해당범죄사실, 전향여부, 보안관찰해당범죄를 다시 범할 위험성이 있다고 의심되는 사실 기타 필요한 사항을 기재하고 특히 조사의 단서 및 인지하게 된 경위를 상세히 기재하여야 한다.', 4584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8110, '①검사 또는 사법경찰관리는 용의자 또는 참고인에 대하여 출석을 요구하는 때에는 출석요구서를 발부하여야 한다. 다만, 긴급을 요하는 때에는 전화 또는 구두로 출석을 요구할 수 있다.', 4585);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8111, '②제1항의 출석요구서에는 출석일시ㆍ장소 및 출석요구의 취지를 명백히 기재하여야 한다.', 4585);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8112, '③용의자 또는 참고인이 출석한 때에는 지체없이 진술을 들어야 하며 장시간 대기시키는 일이 없도록 하여야 한다.', 4585);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8113, '④외국인을 조사할 때에는 국제법과 국제조약에 위배되는 일이 없도록 유의하여야 한다.', 4585);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8114, null, 4586);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8115, '①검사 또는 사법경찰관리는 참고인의 진술을 들을 때에는 형사소송법 제317조의 규정에 유의하여 진술을 강요하여서는 아니된다.', 4587);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8116, '②참고인의 진술은 조서에 기재하여야 한다.', 4587);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8117, '③진술내용이 복잡하거나 참고인이 서면진술을 원하는 때에는 참고인으로 하여금 진술서를 작성ㆍ제출하게 할 수 있다.', 4587);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8118, '④제3항의 규정에 의하여 진술서를 작성하는 때에는 부득이한 경우를 제외하고는 참고인이 자필로 작성하도록 하여야 한다.', 4587);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8119, '①용의자 또는 관계인으로부터 자료를 제출받아 이를 보관하여야 할 필요가 있는 때에는 보관조서 및 보관물목록을 작성하여야 한다. 다만, 조사 중에 자료를 제출 받은 때에는 조서에 보관의 취지를 기재하여 보관조서에 갈음할 수 있다.', 4589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8120, '②보관조서에는 사안번호ㆍ제출자ㆍ소유자 및 보관경위를, 보관물목록에는 보관물의 순위ㆍ품명ㆍ수량ㆍ특징을 구체적으로 기재하여야 한다.', 4589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8121, '①보관물을 다른 사람에게 보관시킬 때에는 보관증을 받아야 하며, 보관자의 선정에 유의하여 그로 하여금 보관물을 성실하게 보관하도록 하여야 한다.', 4590);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8122, '②보관물에 대하여는 사안번호ㆍ용의자의 성명ㆍ보관물목록의 순위ㆍ번호를 기재한 표찰을 붙여야 한다.', 4590);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8123, '③보관물을 보관할 필요가 없는 때에는 지체없이 이를 제출자에게 반환하여야 한다.', 4590);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8124, '④보관물을 폐기하는 때에는 폐기조서와 폐기물목록을 작성하고 사진을 촬영하여 이에 첨부하여야 한다.', 4590);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8125, '①소년인 용의자를 조사하는 때에는 소년의 심리적 특성을 충분히 고려하여 조용한 장소에서 온정과 이해를 가지고 부드러운 어조로 조사에 임하여야 한다.', 4591);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8126, '②소년용의자에 대한 사안은 신속히 처리하고, 소년의 주거ㆍ성명ㆍ직업ㆍ용모등에 의하여  당해본인임을 알 수 있는 정도의 사실이나 사진이 보도되지 아니하도록 유의하여야 한다.', 4591);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8127, '①소년인 용의자를 조사하는 때에는 환경조사서를 작성하여야 한다.', 4592);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8128, '②제1항의 규정에 의한 환경조사서에는 소년의 성격ㆍ행장ㆍ경력ㆍ교육정도ㆍ가정상황ㆍ교우관계 기타 환경등을 상세히 기재하여야 한다.', 4592);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8129, '③소년인 용의자의 심신에 이상이 있다고 인정되는 때에는 지체없이 의사로 하여금 진단하게 하고 그 진단결과를 기재한 서류를 첨부하여야 한다.', 4592);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8130, '①사법경찰관리는 조사를 종결한 때에는 지체없이 사안을 관할검사장에게 송치하여야 한다.', 4594);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8131, '②사법경찰관리는 사안을 송치하는 때에는 소속관서의 장의 명의로 하여야 한다.', 4594);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8132, '①제27조제1항의 규정에 의하여 사안을 송치하는 때에는 사안송치서ㆍ보관물 총목록ㆍ기록목록ㆍ의견서ㆍ용의자 환경조사서ㆍ용의자의 본적조회 회답서 및 전과관계를 증명할 수 있는 서류 기타 필요한 서류를 첨부하여야 한다.', 4595);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8133, '②송치서류는 다음의 순서에 따라 편철하여야 한다.', 4595);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8134, '③제2항제4호의 의견서는 사법경찰관이 작성하여야 한다.', 4595);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8135, '④제2항제5호의 기타 서류는 접수 또는 작성한 순서에 따라 편철하고, 제4호ㆍ제5호의 서류에는 매면에 면수를 기입하며, 제2호 내지 제4호의 서류에는 송치인이 직접 간인하여야 한다.', 4595);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8136, '⑤사법경찰관리는 사안송치 후 용의자에 대하여 다른 보안관찰해당범죄경력을 발견한 때에는 즉시 그 사안을 담당하는 검사(이하 "주임검사"라 한다)에게 보고하여야 한다.', 4595);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8137, '①사법경찰관리는 사안송치 후 조사를 계속하고자 하는 때에는 미리 주임검사의 지휘를 받아야 한다.', 4597);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8138, '②사법경찰관리는 사안송치 후 당해사안에 속하는 용의자의 다른 재범의 위험성을 발견한 때에는 즉시 주임검사에게 보고하고 그 지휘를 받아야 한다.', 4597);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8139, '①검사는 사안의 조사를 종결한 때에는 법무부장관에게 보안관찰처분 청구를 하여야 한다. 다만, 보안관찰처분 청구의 필요가 없다고 인정하는 경우에는 그 청구를 하지 아니하는 조치를 할 수 있다.', 4598);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8140, '②제1항의 규정에 의한 청구를 하는 때에는 검찰총장을 경유하여야 한다. 다만, 검찰총장이 경유하지 아니하도록 한 사안은 그러하지 아니하다.', 4598);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8141, '③제1항 단서의 조치를 하는 경우에는 조사의 결과 및 보안관찰처분 청구를 하지 아니하는 이유를 기재하여야 한다.', 4598);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8142, null, 4599);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8143, '①검사는 보안관찰처분 기간갱신사안(이하 "기간생갱신사안"이라 한다)을 처리하는 때에는 관할경찰서장으로 하여금 피보안관찰자에 대하여 직업ㆍ월수입ㆍ가정환경ㆍ사회활동상황 기타 기간갱신여부를 판단할 수 있는 사항을 기재한 피보안관찰자 동태조사서와 보안관찰부등본을 제출하게하여야 한다.', 4600);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8144, '②검사는 제1항의 규정에 의한 기간갱신사안을 처리함에 있어서는 관할경찰서장으로 하여금 1개월이내의 기간을 정하여 조사하게 할 수 있다.', 4600);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8145, '③검사는 기간갱신사안의 조사를 종결한 때에는 보안관찰처분의 기간만료 2월 전까지 법무부장관에게 보안관찰처분 기간갱신을 청구하여야 한다. 다만, 기간갱신 청구의 필요가 없다고 인정하는 경우에는 그 청구를 하지 아니하는 조치를 할 수 있다.', 4600);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8146, '①검사가 조사에 관하여 사용하는 문서와 장부는 별지 제18호서식 내지 별지 제22호서식에 의한다.', 4602);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8147, '②사법경찰관리가 조사에 관하여 사용하는 문서와 장부는 별지 제23호서식 내지 별지 제29호서식에 의한다.', 4602);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8148, '③검사와 사법경찰관리가 조사에 관하여 공통으로 사용하는 문서와 장부는 별지 제30호서식 내지 별지 제40호서식에 의한다.', 4602);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8149, '①관할경찰서장은 영 제14조제1항의 규정에 의하여 보안관찰처분면제결정 신청서를 접수한 때에는 신청인의 진술을 듣고 재범의 위험성 유무와 신청인이 제출한 서류의 사실여부 및 신청인의 전과관계등을 조사하여야 한다.', 4603);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8150, '②검사는 영 제14조제2항의 규정에 의하여 보안관찰처분면제결정 신청서와 관계서류를 송부받은 때에는 필요하다고 인정하는 경우 제1항의 조사를 할 수 있다.', 4603);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8151, '③검사는 법 제11조 제3항의 규정에 의하여 보안관찰처분면제결정 청구를 하는 때에는 법 제11조제1항제1호 및 제2호에 해당하는 지의 여부와 기타 필요한 자료를 조사하여야 한다.', 4603);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8152, '④영 제14조제1항의 규정에 의한 보안관찰처분면제결정 신청서는 별지 제41호서식, 영 제14조제2항의 규정에 의한 보안관찰처분면제결정 신청서의 송부 및 의견서는 별지 제42호서식 및 별지 제43호서식, 영 제14조제3항의 규정에 의한 보안관찰처분면제결정 신청서의 송부 및 의견서는 별지 제44호서식 및 별지 제43호서식, 영 제14조제5항의 규정에 의한 보안관찰처분면제결정 청구서 및 의견서는 별지 제16호서식 및 별지 제17호서식에 의한다. <개정 2019.10.8>', 4603);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8153, '①법무부장관이 영 제15조제1항의 규정에 의하여 사안을 위원회에 회부하는 때에는 법 제10조제2항의 규정에 의하여 조사의 명을 받은 공무원의 의견을 첨부할 수 있다.', 4604);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8154, '②법무부장관이 위원회에 2건이상의 사안을 동시에 회부하는 때에는 1부의 회부서에 의할 수 있다.', 4604);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8155, '③위원회가 동시에 2건이상의 의결결과를 통보하는 때에는 1부의 통보서에 의할 수 있다.', 4604);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8156, '①검사는 법무부장관으로부터 보안관찰처분결정서를 송달받은 때에는 지체없이 그 결정내용 및 일자를 관할경찰서장에게  통보하여야 한다.', 4605);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8157, '②영 제21조의 규정에 의한 보안관찰처분에 관한 결정서등본의 송달은 피청구자 또는 신청인으로부터 수령서를 받고 검사가 직접 교부하거나 사법경찰관리로 하여금 교부하게 할 수 있다.', 4605);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8158, '③제2항의 수령서는 사안기록에 편철하여야 한다.', 4605);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8159, '④제1항의 규정에 의한 통보는 별지 제20호서식, 제2항의 규정에 의한 수령서는 별지 제45호서식에 의한다.', 4605);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8160, '①법 제17조제1항의 규정에 의한 보안관찰처분의 집행지휘는 별지 제46호서식에 의한다.', 4606);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8161, '②검사가 제1항의 집행지휘를 하는 때에는 별지 제47호서식의 집행원부를 작성ㆍ비치하여야 한다.', 4606);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8162, '①검사는 법 제17조제3항 전단의 규정에 의하여 보안관찰처분 집행중지결정을 하는 때에는 피보안관찰자의 가족 및 신원보증인 기타 관계인의 진술을 듣거나 필요한 조사를 하여야 한다.', 4607);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8163, '②검사는 법 제17조제3항 후단의 규정에 의하여 보안관찰처분 집행중지결정을 취소하는 때에는 집행중지결정을 받은 피보안관찰자ㆍ가족ㆍ신원보증인 기타  관계인의 진술을 듣거나 필요한 조사를 하여야 한다.', 4607);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8164, '③영 제23조제6항 전단의 규정에 의한 고지는 검사가 신청인에게 보안관찰처분집행중지취소결정서등본을 직접 교부하거나 사법경찰관리로 하여금 교부하게 할 수 있다.', 4607);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8165, '④영 제23조제1항의 규정에 의한 보안관찰처분집행중지결정 신청은 별지 제48호서식, 영 제23조제2항의 규정에 의한 보안관찰처분집행중지 결정서는 별지 제49호서식, 영 제23조제3항의 규정에 의한 보안관찰처분집행중지 결정의 집행지휘는 별지 제50호서식, 영 제23조제4항의 규정에 의한 보안관찰처분집행중지 취소결정서는 별지 제51호서식, 영 제23조제5항의 규정에 의한 보안관찰처분집행중지결정취소신청은 별지 제52호서식, 영 제23조제7항의 규정에 의한 보안관찰처분집행중지 취소지휘 및 잔기간 집행지휘는 별지 제53호서식에 의한다.', 4607);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8166, '①피보안관찰자가 법 제18조제1항 내지 제4항의 규정에 의한 신고를 하는 때에는 신고서 1부를 작성하여 주거지를 관할하는 지서 또는 파출소의 장(이하 "지ㆍ파출소장"이라 한다)에게 제출하여야 한다.', 4608);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8167, '②제1항의 규정에 의한 신고서를 접수한 지ㆍ파출소장은 신고서 1부를 사본하여 원본은 관할경찰서장에게 송부하고 사본은 보존한다.', 4608);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8168, '③제1항 및 제2항의 규정에 의하여 신고서를 접수한 지ㆍ파출소장 및 관할경찰서장은 별지 제5호서식의 신고서 접수부를 작성ㆍ비치하여야 한다.', 4608);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8169, '④관할경찰서장은 법 제18조제2항 내지 제4항의 신고사실을 보안관찰부에 기재하여야 한다.', 4608);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8170, '⑤법 제18조제1항의 규정에 의한 신고는 별지 제54호서식, 법 제18조제2항의 규정에 의한 신고는 별지 제55호서식, 법 제18조제3항의 규정에 의한 신고는 별지 제56호서식, 법 제18조제4항 및 영 제24조제2항의 규정에 의한 신고서는 별지 제57호서식, 법 제18조제5항의 규정에 의한 신고필증은 별지 제12호서식, 영 제24조제5항의 규정에 의한 보고는 별지 제2호서식에 의한다.', 4608);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8171, '①영 제24조제3항의 규정에 의하여 여행사실의 통보를 받은 여행목적지 관할경찰서장은 피보안관찰자의 도착여부를 확인한 후 지체없이 이를 관할경찰서장에게 통보하여야 한다.', 4609);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8172, '②여행목적지 관할경찰서장은 피보안관찰자가 그 관할지역이 속하는 특별시ㆍ직할시ㆍ시 또는 군에 체재하는 동안 그 동태를 관찰하고 피보안관찰자에게 다음 각호의 1에 해당하는 사유가 발생한 때에는 지체없이 이를 관할경찰서장에게 통보하여야 한다.', 4609);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8173, '①영 제25조제2항의 규정에 의하여 피보안관찰자에게 교부하는 서면은 별지 제58호서식에 의한다.', 4610);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8174, '②영 제25조제3항의 규정에 의한 보고는 별지 제59호서식에 의하되, 조치를 필요로 하는 사유와 조치할 사항을 구체적으로 기재하여야 한다. 긴급을 요하여 미리 조치를 한 후 보고하는 때에도 또한 같다.', 4610);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8175, '①검사는 영 제26조제2항의 규정에 의한 거소제공대상자에게 거소제공의 필요가 있다고 인정하는 때에는 출소예정일 1월전까지 법무부장관에게 거소제공의 청구를 하여야 한다.', 4611);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8176, '②검사는 영 제26조제3항의 규정에 의한 거소제공대상자에게 거소제공의 필요가 있다고 인정하는 때에는 거소제공청구의 신청을 받은 날부터 20일이내에 법무부장관에게 거소제공의 청구를 하여야 한다.', 4611);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8177, '③검사가 거소제공의 청구를 하는 때에는 별지 제60호서식의 거소제공대상자 관리부를 작성ㆍ비치하여야 한다.', 4611);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8178, '④검사가 영 제26조제8항의 규정에 의하여 거소제공결정서등본을 송달하는 때에는 거소제공대상자에게 직접 교부하거나 교도소등의 장 또는 사법경찰관리로 하여금 교부하게 할 수 있다.', 4611);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8179, '⑤영 제26조제4항의 규정에 의한 신청서는 별지 제61호서식, 영 제26조제5항의 규정에 의한 청구서는 별지 제62호서식, 영 제26조제7항의 규정에 의한 통보는 별지 제20호서식에 의한다.', 4611);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8180, '①검사는 영 제27조제3항의 규정에 의하여 거소변경신청서를 송부하거나 영 제27조제4항의 규정에 의하여 거소변경청구를 하는 때에는 거소제공대상자 관리부에 그 사실을 기재하여야 한다.', 4612);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8181, '②영 제27조제1항의 규정에 의한 신청서는 별지 제63호서식, 영 제27조제2항의 규정에 의한 송부 및 의견서는 별지 제64호서식 및 별지 제43호서식, 영 제27조제3항의 규정에 의한 송부 및 의견서는 별지 제65호서식 및 별지 제43호서식, 영 제27조제4항의 규정에 의한 거소변경청구서는 별지 제66호서식에 의한다.', 4612);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8182, '①조사 사무를 처리하는 관서의 장은 다음의 장부 및 서류를 비치하여야 한다.', 4616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8183, '②제1항제1호의 보안관찰처분사안 접수ㆍ처리부는 미리 매면마다 관할검사장의 간인을 받아야 한다.', 4616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8184, '③제1항제8호의 조사관계 예규철에는 검찰청 기타 감독관청이 발한 훈련ㆍ통첩ㆍ지시등 관계서류를 편철하여야 한다.', 4616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8185, '④제1항제9호의 조사종결사안(송치사안)철에는 검사에게 송치한 사한송치서, 기록목록 및 의견서의 사본을 편철하여야 한다.', 4616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8186, '⑤제1항제10호의 조사미제사안기록철에는 장차 소재를 파악할 가망이 없는 보안관찰처분대상자에 대한 사안등의 기록을 편철하여야 한다.', 4616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8187, '⑥제1항제11호의 통계철에는 조사업무와 관련한 각종 통계서류를 편철하여야 한다.', 4616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8188, '⑦제1항제12호의 처분결과통보서철에는 검사의 보안관찰처분에 관한 청구여부 및 그에 대한 법무부장관의 결정에 관한 통보서를 편철하여야 한다.', 4616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8189, '⑧제1항제13호의 잡서류철에는 제1항제8호 내지 제12호에 해당하지 아니하는 모든 서류를 편철하여야 한다.', 4616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8190, '⑨제1항의 규정에 의한 관서의 장은 필요하다고 인정하는 때에는 제1항 각호의 장부 및 서류외에 필요한 장부 또는 서류철을 비치할 수 있다.', 4616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8191, '①서류철에는 색인목록을 붙여야 한다.', 4617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8192, '②서류를 편철한 후 그 일부를 빼낸 때에는 색인목록 비고란에 그 연월일 및 사유를 기재하고 담당검사 또는 사법경찰관이 날인하여야 한다.', 4617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8193, '①조사사무에 관한 장부 및 서류철은 매년 이를 갱신하여야 한다. 다만, 필요에 따라 계속 사용할 수 있다.', 4618);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8194, '②제1항 단서의 경우에는 분개지등을 삽입하여 그 연도를 분명히 구분하여야 한다.', 4618);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8195, null, 4619);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8196, '①보존기간은 사안처리를 완결하거나 사안처리의 최종절차를 마친 다음해 1월 1일부터 기산한다.', 4620);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8197, '②보존기간이 경과한 장부 및 서류철은 폐기목록을 작성한 후 폐기하여야 한다.', 4620);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8198, '①사안기록과 결정서는 보안관찰처분대상자의 주거지를 관할하는 검찰청에서 보관ㆍ보존한다.', 4621);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8199, '②보안관찰처분대상자가 제1항의 규정에 의한 검찰청의 관할구역외로 주거지를 이전한 때에는 보안관찰처분대상자신고서와 사안기록 및 결정서 기타 관계서류를 신주거지를 관할하는 검찰청에 이송하여야 한다.', 4621);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8200, '③제2항의 규정에 의한 이송은 별지 제69호서식에 의하며, 이 경우 별지 제70호서식의 이송결정서를 작성하여야 한다.', 4621);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8201, '④제2항의 규정에 의하여 보안관찰처분대상자신고서등을 접수한 검찰청은 이송한 검찰청에 별지 제71호서식에 의한 접수통지를 하여야 한다.', 4621);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8202, null, 4623);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8203, '① 영 제6조제1항에 따른 보안관찰처분대상자 신고서는 별지 제3호서식과 같다. <개정 2023.12.13>', 4626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8204, '② 군교도소의 장은 영 제6조제1항에 따라 제출받은 신고서 중 1부를 해당 군교도소를 관할하는 군검찰부의 군검사에게 송부하고, 1부는 보존하며, 별지 제4호서식의 신고서 발송부를 작성하여 갖춰 두어야 한다. <개정 2023.12.13>', 4626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8205, '③ 군교도소의 장은 제2항 및 영 제6조제2항에 따라 신고서를 보낼 때에는 특별한 사유가 있는 경우를 제외하고는 보안관찰처분대상자의 출소 예정일 2개월 전까지 보내야 한다.', 4626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8206, '④ 영 제6조제2항에 따른 신고서를 받은 보안관찰처분대상자의 거주 예정지를 관할하는 경찰서장(이하 "거주예정지 관할경찰서장"이라 한다)은 그 신고서 사본 1부를 관할방첩부대장에게 송부하여야 하며, 신고서 사본을 받은 관할방첩부대장은 보안관찰처분대상자가 출소 후 거주 예정지에 거주하지 아니할 것이 명백한 경우에는 지체 없이 그 사유를 군교도소의 장에게 통보하여야 한다. <개정 2023.12.13>', 4626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8207, '⑤ 제4항에 따른 통보를 받은 군교도소의 장은 지체 없이 해당 군교도소 소재지를 관할하는 군검찰부의 군검사에게 이를 보고하여야 한다. <개정 2023.12.13>', 4626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8208, '⑥ 제4항에 따라 신고서를 받은 관할방첩부대장은 별지 제5호서식의 신고서 접수부와 별지 제6호서식의 보안관찰처분대상자 관리부를 작성ㆍ비치하여야 한다. <개정 2023.12.13>', 4626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8209, '⑦ 제2항에 따른 송부는 별지 제7호서식에 따른다.', 4626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8210, '① 군교도소의 장은 보안관찰처분대상자가 입소하였을 때에는 별지 제8호서식의 보안관찰처분대상자 관리부를 작성하여 갖춰 두어야 한다.', 4629);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8211, '② 군교도소의 장은 보안관찰처분대상자 관리부에 영 제10조제1항에 따른 통고서 송부사실과 영 제10조제2항에 따른 통보사유를 적어야 한다.', 4629);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8212, '③ 삭제 <2020.7.28>', 4629);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8213, '④ 거주예정지 관할경찰서장은 영 제10조제1항에 따른 통고서를 받거나 같은 조 제2항에 따른 통보를 받은 경우에는 관할방첩부대장에게 통고서 사본을 송부하거나 통보 사실을 알려야 한다. <개정 2023.12.13>', 4629);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8214, '① 관할방첩부대장은 그 관할 부대에 소속된 보안관찰처분대상자에게 영 제11조 각 호의 어느 하나에 해당하는 사유가 발생하였을 때에는 지체 없이 그 사실을 보안관찰처분대상자의 소속 부대를 관할하는 군검사에게 보고하고 보안관찰처분대상자 관리부에 그 내용을 기록하여야 한다. <개정 2023.12.13>', 4630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8215, '② 제1항에 따른 보고는 별지 제9호서식에 따른다.', 4630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8216, '① 군검사는 직무를 수행할 때 상호 협조하여야 한다. <개정 2023.12.13>', 4633);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8217, '② 군사법경찰관리는 직무를 수행할 때 상호 협조하여야 한다.', 4633);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8218, '① 조사서류를 작성할 때에는 내용의 정확성과 진술의 임의성을 확보하기 위하여 특히 다음 각 호의 사항에 유의하여야 한다.', 4636);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8219, '② 이 규칙에서 규정한 사항 외에 조사서류의 작성에 관하여는 「군사법원법」 제81조, 제82조, 제84조 및 제91조부터 제93조까지의 규정을 준용한다. <개정 2023.12.13>', 4636);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8220, '① 군검사는 보안관찰처분대상자가 보안관찰해당범죄를 다시 범할 위험성이 있다고 의심하여 조사를 시작하는 경우에는 별지 제12호서식에 따른 보안관찰처분 사안 인지서를 작성하여야 한다. <개정 2023.12.13>', 4638);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8221, '② 군사법경찰관이 제1항의 조사를 시작하려는 경우에는 별지 제13호서식에 따른 보안관찰처분 사안 인지 승인신청서를 작성하여 군검사의 승인을 받아야 한다. <개정 2023.12.13>', 4638);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8222, '③ 제1항에 따른 보안관찰처분 사안 인지서와 제2항에 따른 보안관찰처분 사안 인지 승인신청서에는 용의자의 주거ㆍ성명ㆍ나이ㆍ직업ㆍ생년월일, 보안관찰해당범죄사실, 전향 여부, 보안관찰해당범죄를 다시 범할 위험성이 있다고 의심되는 사실, 그 밖에 필요한 사항을 적되, 특히 조사의 단서와 인지하게 된 경위를 상세히 적어야 한다. <개정 2023.12.13>', 4638);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8223, '① 군검사 또는 군사법경찰관리는 용의자나 참고인에 대하여 출석을 요구할 때에는 출석요구서를 발급하여야 한다. 다만, 긴급히 조치하여야 할 때에는 전화 또는 구두로 출석을 요구할 수 있다. <개정 2023.12.13>', 4639);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8224, '② 제1항의 출석요구서에는 출석 일시ㆍ장소 및 출석요구의 취지를 분명하게 적어야 한다.', 4639);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8225, '③ 용의자 또는 참고인이 출석하였을 때에는 지체 없이 진술을 들어야 하며 장시간 기다리게 하는 일이 없도록 하여야 한다.', 4639);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8226, '④ 외국인을 조사할 때에는 국제법과 국제조약에 위배되는 일이 없도록 유의하여야 한다.', 4639);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8227, null, 4640);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8228, '① 군검사 또는 군사법경찰관리는 참고인의 진술을 들을 때에는 「군사법원법」 제370조에 유의하여 진술을 강요해서는 아니 된다. <개정 2023.12.13>', 4641);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8229, '② 참고인의 진술은 조서에 적어야 한다.', 4641);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8230, '③ 진술 내용이 복잡하거나 참고인이 서면진술을 원할 때에는 참고인으로 하여금 진술서를 작성하여 제출하게 할 수 있다.', 4641);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8231, '④ 제3항에 따라 진술서를 작성할 때에는 부득이한 경우를 제외하고는 참고인이 자필로 작성하도록 하여야 한다.', 4641);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8232, '① 용의자나 관계인으로부터 자료를 제출받아 보관하여야 할 필요가 있는 경우에는 보관조서와 보관물 목록을 작성하여야 한다. 다만, 조사 중에 자료를 제출받았을 때에는 조서에 보관의 취지를 적어 보관조서를 갈음할 수 있다.', 4643);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8233, '② 보관조서에는 사안번호ㆍ제출자ㆍ소유자 및 보관 경위를 적고, 보관물 목록에는 보관물의 순위ㆍ품명ㆍ수량ㆍ특징을 구체적으로 적어야 한다.', 4643);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8234, '① 보관물을 다른 사람에게 보관시킬 때에는 보관증을 받아야 하며, 보관자의 선정에 유의하여 그로 하여금 보관물을 성실하게 보관하도록 하여야 한다.', 4644);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8235, '② 보관물에는 사안번호, 용의자의 성명, 보관물 목록의 순위, 번호를 적은 표찰을 붙여야 한다.', 4644);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8236, '③ 보관물을 보관할 필요가 없을 때에는 지체 없이 제출자에게 반환하여야 한다.', 4644);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8237, '④ 보관물을 폐기할 때에는 폐기조서와 폐기물 목록을 작성하고 사진을 촬영하여 폐기조서에 첨부하여야 한다. <개정 2023.12.13>', 4644);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8238, '① 「소년법」 제2조에 따른 소년(이하 "소년"이라 한다)인 용의자를 조사할 때에는 소년의 심리적 특성을 충분히 고려하여 조용한 장소에서 온정과 이해를 가지고 부드러운 어조로 조사를 진행하여야 한다.', 4645);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8239, '② 소년인 용의자에 대한 사안은 신속히 처리하고, 소년의 주거ㆍ성명ㆍ직업ㆍ용모 등에 의하여 본인임을 알 수 있는 정도의 사실이나 사진이 보도되지 아니하도록 유의하여야 한다.', 4645);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8240, '① 소년인 용의자를 조사할 때에는 환경조사서를 작성하여야 한다.', 4646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8241, '② 제1항에 따른 환경조사서에는 소년의 성격, 품행, 경력, 교육 정도, 가정 상황, 교우 관계, 그 밖의 환경 등을 상세히 적어야 한다.', 4646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8242, '③ 소년인 용의자의 심신에 이상이 있다고 인정될 때에는 지체 없이 군의관으로 하여금 진단하게 하고 그 진단 결과를 적은 서류를 첨부하여야 한다.', 4646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8243, '① 군사법경찰관리는 조사를 마쳤을 때에는 지체 없이 그 사안을 담당하는 군검사(이하 "담당군검사"라 한다)에게 사안을 송치하여야 한다. <개정 2023.12.13>', 4647);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8244, '② 군사법경찰관리는 사안을 송치할 때에는 소속 기관의 장의 명의로 하여야 한다.', 4647);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8245, '① 제26조제1항에 따라 사안을 송치할 때에는 사안 송치서, 보관물 총목록, 기록 목록, 의견서, 용의자 환경조사서 및 전과 관계를 증명할 수 있는 서류 등 그 밖에 필요한 서류를 첨부하여야 한다.', 4648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8246, '② 송치서류는 다음 각 호의 순서에 따라 편철하여야 한다.', 4648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8247, '③ 제2항제4호의 의견서는 군사법경찰관이 작성하여야 한다.', 4648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8248, '④ 제2항제6호의 그 밖의 서류는 접수하거나 작성한 순서에 따라 편철하고, 제4호ㆍ제6호의 서류에는 면마다 면수를 써 놓고, 제2호부터 제5호까지의 서류에는 송치인이 직접 간인하여야 한다.', 4648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8249, '⑤ 군사법경찰관리는 사안 송치 후 용의자에 대하여 다른 보안관찰해당범죄경력을 발견한 때에는 즉시 담당군검사에게 보고하여야 한다. <개정 2023.12.13>', 4648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8250, '① 군사법경찰관리는 사안 송치 후 조사를 계속하려는 경우에는 미리 담당군검사의 지휘를 받아야 한다. <개정 2023.12.13>', 4650);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8251, '② 군사법경찰관리는 사안 송치 후 해당 사안에 속하는 용의자의 다른 재범의 위험성을 발견한 때에는 즉시 담당군검사에게 보고하고 그 지휘를 받아야 한다. <개정 2023.12.13>', 4650);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8252, '① 군검사는 사안의 조사를 마쳤을 때에는 국방부장관에게 보안관찰처분 청구를 하여야 한다. 다만, 보안관찰처분 청구를 할 필요가 없다고 인정하는 경우에는 그 청구를 하지 아니하는 조치를 할 수 있다. <개정 2023.12.13>', 4651);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8253, '② 제1항에 따른 청구를 할 때에는 소속 기관의 장을 거쳐야 한다. 다만, 소속 기관의 장이 거치지 아니하도록 한 사안은 그러하지 아니하다.', 4651);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8254, '③ 제1항 단서의 조치를 하는 경우에는 조사의 결과와 보안관찰처분 청구를 하지 아니하는 이유를 적어야 한다.', 4651);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8255, null, 4652);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8256, '① 군검사는 보안관찰처분 기간갱신사안(이하 "기간갱신사안"이라 한다)을 처리할 때에는 관할방첩부대장으로 하여금 피보안관찰자에 대하여 직업, 월수입, 가정환경, 사회활동 상황, 그 밖에 기간갱신 여부를 판단할 수 있는 사항을 적은 피보안관찰자 동태조사서와 보안관찰부 등본을 제출하게 하여야 한다. <개정 2023.12.13>', 4653);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8257, '② 군검사는 제1항에 따른 기간갱신사안을 처리하는 경우 관할방첩부대장으로 하여금 1개월 이내의 기간을 정하여 조사하게 할 수 있다. <개정 2023.12.13>', 4653);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8258, '③ 군검사는 기간갱신사안의 조사를 마쳤을 때에는 보안관찰처분의 기간이 만료되기 2개월 전까지 국방부장관에게 보안관찰처분 기간갱신을 청구하여야 한다. 다만, 기간갱신 청구를 할 필요가 없다고 인정하는 경우에는 그 청구를 하지 아니하는 조치를 할 수 있다. <개정 2023.12.13>', 4653);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8259, '① 군검사가 사안에 관하여 사용하는 문서와 장부는 별지 제14호서식부터 별지 제17호서식까지와 같다. <개정 2023.12.13>', 4655);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8260, '② 군사법경찰관리가 조사에 관하여 사용하는 문서와 장부는 별지 제18호서식부터 별지 제22호서식까지와 같다.', 4655);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8261, '③ 군검사와 군사법경찰관리가 조사에 관하여 공통으로 사용하는 문서와 장부는 별지 제23호서식부터 별지 제33호서식까지와 같다. <개정 2023.12.13>', 4655);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8262, '① 피보안관찰자의 거주지를 관할하는 관할경찰서장은 영 제14조제1항에 따라 보안관찰처분 면제결정 신청서를 접수한 경우에는 해당 신청서 및 영 제14조제1항 각 호의 서류(이하 "신청서등"이라 한다)를 관할방첩부대장에게 송부하여야 한다. <개정 2023.12.13>', 4656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8263, '② 관할방첩부대장은 제1항에 따라 신청서등을 받은 경우에는 20일 이내에 신청인의 진술을 듣고 재범의 위험성 유무와 신청인이 제출한 서류의 사실 여부 및 신청인의 전과 관계 등을 조사한 후 신청서등에 별지 제34호서식에 따른 의견서 등을 첨부하여 군검사에게 송부하여야 한다. 이 경우 관할방첩부대장은 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 보안관찰처분대상자의 주민등록표 등본을 확인하여야 하며, 보안관찰처분대상자가 확인에 동의하지 아니하는 경우에는 그 등본을 첨부하도록 하여야 한다. <개정 2023.12.13>', 4656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8264, '③ 군검사는 영 제14조제2항에 따라 보안관찰처분 면제결정 신청서와 관계 서류를 받았을 때에는 필요하다고 인정하는 경우 제1항의 조사를 할 수 있다. <개정 2023.12.13>', 4656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8265, '④ 군검사는 법 제11조제3항에 따라 보안관찰처분 면제결정 청구를 할 때에는 법 제11조제1항제1호 및 제2호에 해당하는 지의 여부와 그 밖에 필요한 자료를 조사하여야 한다. <개정 2023.12.13>', 4656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8266, '⑤ 제2항에 따른 보안관찰처분 면제결정 신청서의 송부는 별지 제35호서식, 영 제14조제3항에 따른 보안관찰처분 면제결정 신청서의 송부 및 의견서는 별지 제36호서식 및 별지 제34호서식, 영 제14조제5항에 따른 보안관찰처분 면제결정 청구서 및 의견서는 별지 제10호서식 및 별지 제11호서식에 따른다.', 4656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8267, '① 국방부장관이 영 제15조제1항에 따라 사안을 군보안관찰처분심의위원회(이하 "위원회"라 한다)의 회의에 부칠 때에는 법 제10조제2항에 따라 조사의 명을 받은 국방부 소속 공무원의 의견을 첨부할 수 있다.', 4657);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8268, '② 국방부장관이 2건 이상의 사안을 동시에 위원회의 회의에 부칠 때에는 1부의 회부서에 의할 수 있다.', 4657);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8269, '③ 위원회가 동시에 2건 이상의 의결 결과를 통보할 때에는 1부의 통보서에 의할 수 있다.', 4657);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8270, '① 군검사는 국방부장관으로부터 보안관찰처분 결정서를 송달받았을 때에는 지체 없이 그 결정 내용 및 날짜를 관할방첩부대장에게 별지 제15호서식에 따라 통보하여야 한다. <개정 2023.12.13>', 4658);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8271, '② 영 제21조에 따른 보안관찰처분에 관한 결정서 등본의 송달은 피청구자 또는 신청인으로부터 별지 제37호서식에 따른 수령서를 받고 군검사가 직접 교부하거나 군사법경찰관리로 하여금 교부하게 할 수 있다. <개정 2023.12.13>', 4658);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8272, '③ 제2항의 수령서는 사안기록에 편철하여야 한다.', 4658);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8273, '① 법 제17조제1항에 따른 보안관찰처분의 집행지휘는 별지 제38호서식에 따른다.', 4659);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8274, '② 군검사는 제1항의 집행지휘를 하는 때에는 별지 제39호서식의 집행원부를 작성하여 갖춰 두어야 한다. <개정 2023.12.13>', 4659);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8275, '① 군검사는 법 제17조제3항 전단에 따라 보안관찰처분 집행중지결정을 할 때에는 피보안관찰자의 가족 및 신원보증인, 그 밖의 관계인의 진술을 듣거나 필요한 조사를 하여야 한다. <개정 2023.12.13>', 4660);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8276, '② 군검사는 법 제17조제3항 후단에 따라 보안관찰처분 집행중지결정을 취소할 때에는 집행중지결정을 받은 피보안관찰자, 그 가족, 신원보증인, 그 밖의 관계인의 진술을 듣거나 필요한 조사를 하여야 한다. <개정 2023.12.13>', 4660);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8277, '③ 영 제23조제6항 전단에 따른 고지는 군검사가 신청인에게 보안관찰처분 집행중지 취소결정서 등본을 직접 교부하거나 군사법경찰관리로 하여금 교부하게 할 수 있다. <개정 2023.12.13>', 4660);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8278, '④ 영 제23조제2항에 따른 보안관찰처분 집행중지결정서는 별지 제40호서식과 같고, 영 제23조제4항에 따른 보안관찰처분 집행중지 취소결정서는 별지 제41호서식과 같고, 영 제23조제5항에 따른 보안관찰처분 집행중지결정 취소신청은 별지 제42호서식에 따른다.', 4660);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8279, '① 피보안관찰자가 법 제18조제1항부터 제4항까지에 따른 신고를 할 때에는 해당 사안에 관한 신고서 1부를 작성하여 관할방첩부대장에게 제출하여야 한다. <개정 2023.12.13>', 4661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8280, '② 제1항에 따른 신고서를 접수한 관할방첩부대장은 신고서 1부를 복사하여 원본은 군검사에게 보내고 사본은 보존한다. <개정 2023.12.13>', 4661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8281, '③ 제1항과 제2항에 따라 신고서를 접수한 군검사는 별지 제5호서식의 신고서 접수부를 작성하여 갖춰 두어야 한다. <개정 2023.12.13>', 4661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8282, '④ 군검사는 법 제18조제2항부터 제4항까지에 따른 신고사실을 보안관찰부에 적어야 한다. <개정 2023.12.13>', 4661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8283, '⑤ 제1항에 따른 신고서는 별지 제43호서식부터 별지 제46호서식까지와 같다.', 4661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8284, '① 피보안관찰자가 휴가 또는 출장의 명을 받은 경우 관할방첩부대장은 피보안관찰자의 휴가 또는 출장 목적지를 관할하는 방첩부대장에게 그 사실을 통보하여야 한다. <개정 2023.12.13>', 4662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8285, '② 제1항에 따라 휴가 또는 출장 사실을 통보받은 방첩부대장은 피보안관찰자의 도착 여부를 확인한 후 지체 없이 그 사실을 피보안관찰자의 휴가 또는 출장 목적지를 관할하는 군검찰부의 군검사에게 통보하여야 한다. <개정 2023.12.13>', 4662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8286, '③ 피보안관찰자의 휴가 또는 출장 목적지를 관할하는 방첩부대장은 피보안관찰자가 그 관할지역이 속하는 특별시, 광역시, 도, 특별자치도, 시 또는 군에 체류하는 동안 그 동태를 관찰하고 피보안관찰자에게 다음 각 호의 어느 하나에 해당하는 사유가 발생한 때에는 지체 없이 이를 피보안관찰자의 휴가 또는 출장 목적지를 관할하는 군검찰부의 군검사에게 통보하여야 한다. <개정 2023.12.13>', 4662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8287, '① 영 제25조제2항에 따라 피보안관찰자에게 교부하는 서면은 별지 제47호서식과 같다.', 4663);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8288, '② 영 제25조제3항에 따른 보고는 별지 제48호서식에 따르되, 조치를 필요로 하는 사유와 조치할 사항을 구체적으로 적어야 한다. 긴급하여 미리 조치를 한 후 보고할 때에도 또한 같다.', 4663);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8289, '① 군검사는 영 제26조제2항에 따른 거소제공대상자에게 거소를 제공할 필요가 있다고 인정할 때에는 출소 예정일 1개월 전까지 국방부장관에게 거소제공의 청구를 하여야 한다. <개정 2023.12.13>', 4664);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8290, '② 군검사는 영 제26조제3항에 따른 거소제공대상자에게 거소를 제공할 필요가 있다고 인정할 때에는 거소제공 청구의 신청을 받은 날부터 20일 이내에 국방부장관에게 거소제공의 청구를 하여야 한다. <개정 2023.12.13>', 4664);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8291, '③ 군검사가 거소제공의 청구를 할 때에는 별지 제49호서식의 거소제공대상자 관리부를 작성하여 갖춰 두어야 한다. <개정 2023.12.13>', 4664);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8292, '④ 군검사가 영 제26조제8항에 따라 거소제공결정서 등본을 송달할 때에는 거소제공대상자에게 직접 교부하거나 군교도소의 장 또는 군사법경찰관리로 하여금 교부하게 할 수 있다. <개정 2023.12.13>', 4664);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8293, '⑤ 영 제26조제4항에 따른 신청서는 별지 제50호서식, 영 제26조제5항에 따른 청구서는 별지 제51호서식과 같고, 영 제26조제7항에 따른 통보는 별지 제15호서식에 따른다.', 4664);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8294, '① 군검사는 영 제27조제3항에 따라 거소변경 신청서를 보내거나 영 제27조제4항에 따라 거소변경 청구를 할 때에는 별지 제49호서식의 거소제공대상자 관리부에 그 사실을 적어야 한다. <개정 2023.12.13>', 4665);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8295, '② 영 제27조제3항에 따른 송부 및 의견서는 별지 제52호서식 및 별지 제34호서식, 영 제27조제4항에 따른 거소변경 청구서는 별지 제53호서식과 같다.', 4665);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8296, '① 조사사무를 처리하는 기관의 장은 다음 각 호의 장부와 서류를 갖춰 두어야 한다.', 4668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8297, '② 제1항제1호의 보안관찰처분사안 접수ㆍ처리부는 미리 면마다 관할 군검사의 간인을 받아야 한다. <개정 2023.12.13>', 4668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8298, '③ 제1항제8호의 조사관계 예규철에는 관할 군검사의 소속 기관 또는 그 밖의 감독관청에서 내린 훈련ㆍ통첩ㆍ지시 등 관계 서류를 편철하여야 한다. <개정 2023.12.13>', 4668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8299, '④ 제1항제9호의 조사 종결사안(송치사안)철에는 군검사에게 송치한 사안 송치서, 기록 목록 및 의견서의 사본을 편철하여야 한다. <개정 2023.12.13>', 4668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8300, '⑤ 제1항제10호의 조사 미제사안 기록철에는 앞으로 소재를 파악할 가망이 없는 보안관찰처분대상자에 대한 사안 등의 기록을 편철하여야 한다.', 4668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8301, '⑥ 제1항제11호의 통계철에는 조사업무와 관련한 각종 통계서류를 편철하여야 한다.', 4668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8302, '⑦ 제1항제12호의 처분 결과 통보서철에는 군검사의 보안관찰처분에 관한 청구 여부와 그에 대한 국방부장관의 결정에 관한 통보서를 편철하여야 한다. <개정 2023.12.13>', 4668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8303, '⑧ 제1항제13호의 기타서류철에는 제1항제8호부터 제12호까지에 해당하지 아니하는 모든 서류를 편철하여야 한다.', 4668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8304, '⑨ 제1항에 따른 기관의 장은 필요하다고 인정할 때에는 제1항 각 호의 장부와 서류 외에 필요한 장부 또는 서류철을 갖추어 둘 수 있다.', 4668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8305, '① 서류철에는 찾아보기 목록을 붙여야 한다.', 4669);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8306, '② 서류를 편철한 후 그 일부를 빼낸 경우에는 찾아보기 목록 비고란에 그 연월일과 사유를 적고 담당군검사 또는 군사법경찰관이 도장을 찍어야 한다. <개정 2023.12.13>', 4669);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8307, '① 조사사무에 관한 장부와 서류철은 해마다 갱신하여야 한다. 다만, 필요하면 계속 사용할 수 있다.', 4670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8308, '② 제1항 단서의 경우에는 분개지(分介紙) 등을 삽입하여 그 연도를 분명히 구분하여야 한다.', 4670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8309, null, 4671);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8310, '① 보존기간은 사안처리를 완결하거나 사안처리의 최종 절차를 마친 다음 해 1월 1일부터 기산(起算)한다.', 4672);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8311, '② 보존기간이 지난 장부와 서류철은 폐기 목록을 작성한 후 폐기하여야 한다.', 4672);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8312, '① 사안기록과 결정서는 보안관찰처분대상자의 소속 부대를 관할하는 군검찰부가 설치된 기관(이하 이 조에서 "기관"이라 한다)에서 보관ㆍ보존한다.', 4673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8313, '② 기관은 보안관찰처분대상자가 관할구역 외로 근무지를 이전한 경우에는 보안관찰처분대상자 신고서와 사안기록 및 결정서, 그 밖의 관계 서류를 새로운 근무지를 관할하는 기관에 이송하여야 한다.', 4673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8314, '③ 제2항에 따른 이송은 별지 제55호서식에 따르며, 이 경우 별지 제56호서식의 이송결정서를 작성하여야 한다.', 4673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8315, '④ 제2항에 따라 보안관찰처분대상자 신고서 등을 접수한 기관은 이송한 기관에 별지 제57호서식에 따른 접수통지를 하여야 한다.', 4673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8316, '①검사는 법 제23조제1항의 규정에 의하여 위반선박 또는 그 선박의 선장이나 기타 위반자(이하 "위반자"라 한다)에 대하여 정선ㆍ승선ㆍ검색ㆍ나포 등 필요한 조치를 취한 때에는 별지 제1호서식의 위반선박및위반자조치서를 작성하여 사건기록에 편철하여야 한다.', 4675);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8317, '②사법경찰관이 법 제23조제2항의 규정에 의하여 검사의 지휘를 받고자 하는 경우에는 별지 제2호서식의 위반선박및위반자조치지휘건의서에 의한다. 다만, 급속을 요하여 미리 검사의 지휘를 받지 못한 경우에는 별지 제3호서식에 의한 위반선박및위반조치결과보고서에 그 사유를 기재하여 검사의 승인을 얻어야 한다.', 4675);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8318, '③사법경찰관이 법 제23조제2항의 규정에 의한 보고를 하고자 하는 경우에는 별지 제3호서식의 위반선박및위반자조치결과보고서에 의한다.', 4675);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8319, '①제2조제1항의 규정에 의한 조치를 한 검사는 별지 제4호서식의 담보금결정서를 2부 작성하여 1부는 사건기록에 편철하고, 1부는 사건사무담당직원에게 송부하여 위반자에게 교부하게 하여야 한다.', 4676);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8320, '②사법경찰관으로부터 제2조제3항의 규정에 의한 보고를 받은 검사는 별지 제4호서식의 담보금결정서를 2부 작성하여 사건사무담당직원에게 송부하고, 사건사무담당직원은 이를 해당사법경찰관에게 송부하여 그중 1부는 사건기록에 편철하게 하고, 다른 1부는 위반자에게 교부하게 하여야 한다.', 4676);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8321, '③제1항 또는 제2항의 규정에 의한 담보금결정서를 송부받은 사건사무담당직원은 별지 제5호서식의 배타적경제수역위반자기록표 및 별지 제6호서식의 배타적경제수역위반자명부에 소정의 사항을 기재하고, 각란의 소정사유가 발생할 때마다 이를 기재하여야 한다.', 4676);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8322, '④담보금이 납입되거나 담보금보증보험증권이 첨부된 담보금보증서가 제출된 때에는 사건사무담당직원은 세입세출외현금출납공무원으로부터 별지 제7호서식의 담보금(담보금보증서)영수필보고서 및 별지 제8호서식의 보관표를 인계받아 검사의 확인인을 받은 후 이를 보관하여야 한다.', 4676);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8323, '①제3조제4항의 규정에 의하여 위반자에 대한 담보금이 납입되거나 담보금보증서가 제출된 때에는 검사는 위반자를 즉시 석방하고, 위반선박 및 압수를 계속할 필요가 없다고 판단되는 압수물을 환부하여야 한다.', 4677);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8324, '②제1항의 경우 사건사무담당직원은 별지 제9호서식의 위반자석방및위반선박등환부지휘서를 작성하여 검사의 서명ㆍ날인을 받아 해당법경찰관에게 송부하여야 한다.', 4677);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8325, '③검찰청에 수리되어 있는 압수물의 환부절차에 관하여는 검찰압수물사무규칙 제4장제5절 및 제5장의 규정을 준용한다.', 4677);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8326, '①검사는 법 제24조제2항 또는 제3항의 규정에 의한 국고귀속의 사유가 발생한 때에는 별지 제10호서식의 담보금국고귀속서를 작성하여 사건사무담당직원에게 송부하여야 한다.', 4678);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8327, '②제1항의 규정에 의한 담보금국고귀속서를 송부받은 사건사무담당직원은 별지 제5호서식의 배타적경제수역위반자기록표 및 별지 제6호서식의 배타적경제수역위반자명부에 소정의 사항을 기재하고, 별지 제10호서식의 담보금국고귀속서 및 별지 제8호서식의 보관표를 세입세출외현금출납공무원에게 인계하여야 한다.', 4678);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8328, '③제2항의 경우 담보금보증서가 제출되어 있는 때에는 즉시 별지 제11호서식의 담보금보증보험금지급청구서를 작성하여 검사의 서명ㆍ날인을 받아 보증보험회사에 송부하여야 한다.', 4678);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8329, '④제2항의 규정은 사건사무담당직원이 보증보험회사로부터 담보금보증보험금을 송부받은 경우에 이를 준용한다.', 4678);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8330, '①검사는 법 제24조제2항 및 제3항의 규정에 의한 국고귀속사유에 의하여 담보금이 국고에 귀속되기 전에 다음 각호의 1에 해당하는 사유가 발생한 때에는 위반자 또는 담보금을 납입한 자의 청구에 의하여 담보금을 환부하여야 한다.', 4679);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8331, '②사건사무담당직원은 제1항의 규정에 의한 담보금환부청구가 있는 때에는 환부사유를 확인하여 별지 제8호서식의 보관표의 명령란에 사유를 기재하여 검사의 환부명령과 날인을 받고, 별지 제5호서식에 의한 배타적경제수역위반자기록표 및 별지 제6호서식의 배타적경제수역위반자명부에 소정의 사항을 기재한 후 별지 제8호서식의 보관표를 세입세출외현금출납공무원에게 인계하여야 한다.', 4679);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8332, '③사건사무담당직원은 담보금보증보험증권의 환부사유가 발생하였음에도 30일이내에 환부청구가 없는 때에는 별지 제8호서식의 보관표의 명령란에 검사의 폐기명령과 날인을 받아 별지 제5호서식의 배타적경제수역위반자기록표 및 별지 제6호서식의 배타적경제수역위반자명부에 소정의 사항을 기재한 후 별지 제8호서식의 보관표를 유가증권취급공무원에게 인계하여야 한다.', 4679);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8333, '① 「가정폭력범죄의 처벌 등에 관한 특례법」(이하 "법"이라 한다) 제55조의2제5항에 따른 신변안전조치의 청구 및 요청은 각각 별지 제1호서식의 신변안전조치 청구서 및 별지 제2호서식의 신변안전조치 요청서로 하여야 한다. 다만, 긴급한 경우에는 구두(口頭)로 또는 전화 등으로 할 수 있으며, 사후에 지체 없이 관련 서면을 제출하거나 송부하여야 한다.', 4681);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8334, '② 제1항에 따른 신변안전조치를 청구하거나 요청할 때에는 신변안전조치가 필요한 사유, 신변안전조치의 종류 및 기간을 구체적으로 기재하여야 하며, 그 내용을 입증할 수 있는 자료 등을 첨부할 수 있다.', 4681);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8335, null, 4682);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8336, '① 피해자 또는 그 법정대리인은 신변안전조치 종류의 변경이 필요하거나 또는 추가적인 신변안전조치가 필요한 경우 별지 제3호서식으로 법원에 신변안전조치의 종류 변경 또는 신변안전조치의 추가를 청구할 수 있다. 이 경우 제2조제1항 단서 및 제2항을 준용한다.', 4683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8337, '② 피해자 또는 그 법정대리인은 신변안전조치의 기간 중에 신변안전조치의 연장이 필요한 사유 및 그 기간을 구체적으로 기재하여 별지 제3호서식으로 법원에 신변안전조치의 연장을 청구할 수 있다. 이 경우 제2조제1항 단서 및 제2항을 준용한다.', 4683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8338, '③ 법원은 피해자 보호를 위하여 신변안전조치의 종류 변경, 신변안전조치의 추가 또는 기간 연장이 필요하다고 인정하는 경우에는 직권으로 또는 제1항ㆍ제2항에 따른 청구에 의하여 별지 제2호서식으로 검사에게 신변안전조치의 종류 변경, 신변안전조치의 추가 또는 기간 연장을 요청할 수 있다. 이 경우 제2조제1항 단서 및 제2항을 준용한다.', 4683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8339, '① 검사는 법원으로부터 법 제55조의2제5항 전단 또는 이 영 제4조제3항에 따른 요청을 받은 경우에는 별지 제2호서식으로 피해자의 주거지 또는 현재지를 관할하는 경찰서장에게 해당 조치를 하도록 요청할 수 있다. 이 경우 제2조제1항 단서 및 제2항을 준용한다.', 4684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8340, '② 제1항에 따라 신변안전조치를 요청받은 경찰서장은 신변안전조치의 필요성이 소멸하는 등 특별한 사유가 없으면 제1항에 따라 검사가 요청한 조치를 하여야 한다.', 4684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8341, '① 경찰서장이 법 제55조의2제5항에 따른 신변안전조치 및 제5조에 따른 조치를 하였을 때에는 지체 없이 그 조치를 요청한 검사에게 별지 제4호서식의 신변안전조치 이행 통보서로 통보하여야 한다.', 4685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8342, '② 검사는 제1항에 따른 통보를 받았을 때에는 제5조제1항에 따른 요청을 한 법원에 그 사실을 별지 제4호서식의 신변안전조치 이행 통보서로 통보하여야 한다.', 4685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8343, '③ 제1항과 제2항에 따른 통보 서류 및 신변안전조치와 관련된 서류는 공개해서는 아니 된다.', 4685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8344, null, 4689);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8345, null, 4692);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8346, '① 법원은 법 제54조제1항에 따른 검사의 청구가 부적법하다고 인정한 때에는 그 청구를 각하하는 결정을 하여야 한다. 다만, 그 흠을 보정할 수 있는 경우에는 그러하지 아니하다.', 4693);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8347, '② 제1항의 결정은 검사에게 송달하여야 한다.', 4693);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8348, '③ 검사는 제1항의 결정에 대하여 즉시항고를 할 수 있다.', 4693);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8349, '① 감치에 처하는 재판에는 체납된 과태료의 내용, 감치의 기간 및 감치의 기간이 만료되기 이전이라도 체납된 과태료가 납부된 때에는 감치의 집행이 종료된다는 뜻을 명확히 하여야 한다.', 4695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8350, '② 법원은 다음 각 호의 어느 하나에 해당하는 경우에는 감치의 청구를 기각하는 결정을 하여야 한다.', 4695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8351, '③ 감치에 관한 재판서 또는 그 재판의 내용을 기재한 조서의 등본은 검사에게 송달하여야 한다.', 4695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8352, '④ 체납자가 재판기일에 출석하지 아니한 때에는 제1항과 제2항의 감치에 관한 재판서 또는 그 재판의 내용을 기재한 조서의 등본을 체납자에게 송달하여야 한다.', 4695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8353, '⑤ 검사는 제2항의 결정에 대하여 즉시항고를 할 수 있다.', 4695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8354, '① 법 제54조제3항에 따른 즉시항고는 재판의 선고일부터 1주 이내에 하여야 한다. 다만, 체납자가 출석하지 아니한 상태에서 감치의 재판을 선고한 때에는 재판서 또는 재판의 내용이 기재된 조서의 등본이 체납자에게 송달된 날부터 체납자의 즉시항고기간을 기산한다.', 4696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8355, '② 제1항의 경우 이외에 이 규칙에 따른 즉시항고는 검사가 감치에 관한 재판서 또는 그 재판의 내용을 기재한 조서의 등본을 송달받은 날부터 1주 이내에 하여야 한다.', 4696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8356, '③ 제1항과 제2항의 기간은 불변기간으로 한다.', 4696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8357, '④ 체납자가 책임질 수 없는 사유로 말미암아 불변기간을 지킬 수 없었던 경우에는 그 사유가 없어진 날부터 2주 이내에 즉시항고를 제기할 수 있다. 다만, 그 사유가 없어질 당시 외국에 있던 체납자에 대하여는 이 기간을 30일로 한다.', 4696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8358, '⑤ 즉시항고는 이유를 기재한 항고장을 재판법원에 제출함으로써 한다.', 4696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8359, '⑥ 제6조제3항, 제4항은 즉시항고 및 재항고에 대한 재판서에 이를 준용한다.', 4696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8360, '① 감치에 처하는 재판의 집행은 검사가 지휘한다.', 4698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8361, '② 법원은 감치에 처하는 재판에 대하여 체납자의 즉시항고가 있는 경우 그 사실을 즉시 검사에게 통지하여야 한다.', 4698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8362, '③ 감치에 처하는 재판은 그 재판의 확정일부터 1년이 경과된 후에는 이를 집행할 수 없다.', 4698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8363, '① 법 제54조제1항에 따라 감치에 처하는 재판을 받은 자가 그 감치의 집행 중에 체납된 과태료가 납부된 사실을 증명하는 서면을 제출한 때에는 검사는 곧바로 체납자가 유치되어 있는 감치시설의 장에게 체납자의 석방을 지휘하여야 한다.', 4701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8364, '② 제1항의 석방지휘는 서면으로 하여야 한다. 다만, 긴급한 필요가 있는 경우에는 그러하지 아니하다.', 4701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8365, '① 이 규칙에 따른 송달에 관하여는 「형사소송법」과 「형사소송규칙」 중 송달에 관한 규정을 준용한다.', 4702);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8366, '② 법 제54조제1항에 따른 감치에 처하는 재판절차 및 그 밖의 사항에 관하여는「법정등의질서유지를위한재판에관한규칙」제6조, 제7조, 제8조, 제10조제1항, 제11조, 제15조, 제16조 내지 제18조, 제25조제1항ㆍ제2항ㆍ제5항의 규정을 준용한다.', 4702);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8367, '③ 체납자가 항고한 사건에 대하여는 「법정등의질서유지를위한재판에관한규칙」제15조의2의 규정을 준용한다.', 4702);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8368, '④ 법 제54조제1항에 따른 감치에 처하는 재판의 집행절차에 관하여는 법 및 이 규칙에 특별한 규정이 있는 경우를 제외하고는 성질에 반하지 아니하는 한 「형사소송법」과 「형사소송규칙」 중 형의 집행에 관한 규정을 준용한다.', 4702);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8369, null, 4704);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8370, '① 「형법」 제347조(사기), 제347조의2(컴퓨터등 사용사기), 제350조(공갈), 제350조의2(특수공갈), 제351조(제347조, 제347조의2, 제350조 및 제350조의2의 상습범만 해당한다), 제355조(횡령ㆍ배임) 또는 제356조(업무상의 횡령과 배임)의 죄를 범한 사람은 그 범죄행위로 인하여 취득하거나 제3자로 하여금 취득하게 한 재물 또는 재산상 이익의 가액(이하 이 조에서 "이득액"이라 한다)이 5억원 이상일 때에는 다음 각 호의 구분에 따라 가중처벌한다. <개정 2016.1.6, 2017.12.19>', 4705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8371, '② 제1항의 경우 이득액 이하에 상당하는 벌금을 병과(倂科)할 수 있다.', 4705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8372, '① 법령을 위반하여 대한민국 또는 대한민국국민의 재산을 국외로 이동하거나 국내로 반입하여야 할 재산을 국외에서 은닉 또는 처분하여 도피시켰을 때에는 1년 이상의 유기징역 또는 해당 범죄행위의 목적물 가액(이하 이 조에서 "도피액"이라 한다)의 2배 이상 10배 이하에 상당하는 벌금에 처한다.', 4706);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8373, '② 제1항의 경우 도피액이 5억원 이상일 때에는 다음 각 호의 구분에 따라 가중처벌한다.', 4706);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8374, '③ 제1항 또는 제2항의 미수범은 각 죄에 해당하는 형으로 처벌한다.', 4706);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8375, '④ 법인의 대표자나 법인 또는 개인의 대리인, 사용인, 그 밖의 종업원이 그 법인 또는 개인의 업무에 관하여 제1항부터 제3항까지의 어느 하나에 해당하는 위반행위를 하면 그 행위자를 벌하는 외에 그 법인 또는 개인에게도 제1항의 벌금형을 과(科)한다. 다만, 법인 또는 개인이 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다.', 4706);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8376, '① 금융회사등의 임직원이 그 직무에 관하여 금품이나 그 밖의 이익을 수수(收受), 요구 또는 약속하였을 때에는 5년 이하의 징역 또는 10년 이하의 자격정지에 처한다.', 4707);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8377, '② 금융회사등의 임직원이 그 직무에 관하여 부정한 청탁을 받고 제3자에게 금품이나 그 밖의 이익을 공여(供與)하게 하거나 공여하게 할 것을 요구 또는 약속하였을 때에는 제1항과 같은 형에 처한다.', 4707);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8378, '③ 금융회사등의 임직원이 그 지위를 이용하여 소속 금융회사등 또는 다른 금융회사등의 임직원의 직무에 속하는 사항의 알선에 관하여 금품이나 그 밖의 이익을 수수, 요구 또는 약속하였을 때에는 제1항과 같은 형에 처한다.', 4707);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8379, '④ 제1항부터 제3항까지의 경우에 수수, 요구 또는 약속한 금품이나 그 밖의 이익의 가액(이하 이 조에서 "수수액"이라 한다)이 3천만원 이상일 때에는 다음 각 호의 구분에 따라 가중처벌한다.', 4707);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8380, '⑤ 제1항부터 제4항까지의 경우에 수수액의 2배 이상 5배 이하의 벌금을 병과한다.', 4707);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8381, '① 제5조에 따른 금품이나 그 밖의 이익을 약속, 공여 또는 공여의 의사를 표시한 사람은 5년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.', 4708);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8382, '② 제1항의 행위에 제공할 목적으로 제3자에게 금품을 교부하거나 그 정황을 알면서 교부받은 사람은 제1항과 같은 형에 처한다.', 4708);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8383, '① 저축을 하는 사람 또는 저축을 중개하는 사람이 금융회사등의 임직원으로부터 그 저축에 관하여 법령 또는 약관이나 그 밖에 이에 준하는 금융회사등의 규정에 따라 정하여진 이자, 복금(福金), 보험금, 배당금, 보수 외에 어떤 명목으로든 금품이나 그 밖의 이익을 수수하거나 제3자에게 공여하게 하였을 때에는 5년 이하의 징역 또는 5천만원 이하의 벌금에 처한다.', 4711);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8384, '② 저축을 하는 사람이 그 저축과 관련하여 그 저축을 중개하는 자 또는 그 저축과 관계없는 제3자에게 금융회사등으로부터 대출등을 받게 하였을 때 또는 저축을 중개하는 사람이 그 저축과 관련하여 금융회사등으로부터 대출등을 받거나 그 저축과 관계없는 제3자에게 대출등을 받게 하였을 때에는 제1항과 같은 형에 처한다.', 4711);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8385, '③ 금융회사등의 임직원이 제1항 또는 제2항에 규정된 금품이나 그 밖의 이익을 공여하거나 대출등을 하였을 때에는 제1항 또는 제2항과 같은 형에 처한다.', 4711);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8386, '④ 제1항부터 제3항까지의 경우 징역과 벌금을 병과할 수 있다.', 4711);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8387, '⑤ 금융회사등의 임직원이 소속 금융회사등의 업무에 관하여 제3항의 위반행위를 하면 그 행위자를 벌하는 외에 그 소속 금융회사등에도 같은 항의 벌금형을 과(科)한다. 다만, 소속 금융회사등이 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다.', 4711);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8388, '① 제4조제1항부터 제3항까지의 경우 범인이 도피시키거나 도피시키려고 한 재산은 몰수한다.', 4712);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8389, '② 제5조부터 제7조까지 및 제9조제1항ㆍ제3항의 경우 범인 또는 정황을 아는 제3자가 받은 금품이나 그 밖의 이익은 몰수한다.', 4712);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8390, '③ 제1항 또는 제2항의 경우 몰수할 수 없을 때에는 그 가액을 추징한다.', 4712);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8391, '① 「자본시장과 금융투자업에 관한 법률」 제444조제22호(단기금융업무만 해당한다)의 죄를 범한 사람은 그 영업으로 인하여 취득한 이자, 할인 및 수입료 또는 그 밖의 수수료의 금액(이하 이 조에서 "수수료액"이라 한다)이 연 1억원 이상일 때에는 다음 각 호의 구분에 따라 가중처벌한다.', 4713);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8392, '② 제1항의 경우에 취득한 수수료액의 100분의 10 이상 수수료액 이하에 상당하는 벌금을 병과한다.', 4713);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8393, '① 금융회사등의 임직원은 그의 감독을 받는 사람이 그 직무에 관하여 이 법에 규정된 죄를 범한 정황을 알았을 때에는 지체 없이 소속 금융회사등의 장이나 감사 또는 검사(檢査)의 직무를 담당하는 부서의 장에게 보고하여야 한다.', 4714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8394, '② 금융회사등의 장이나 감사 또는 검사의 직무에 종사하는 임직원 또는 감독기관의 감독업무에 종사하는 사람은 그 직무를 수행할 때 금융회사등의 임직원이 그 직무에 관하여 이 법에 규정된 죄를 범한 정황을 알았을 때에는 지체 없이 수사기관에 알려야 한다.', 4714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8395, '③ 정당한 사유 없이 제1항을 위반한 사람은 100만원 이하의 벌금에 처한다.', 4714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8396, '④ 정당한 사유 없이 제2항을 위반한 사람은 200만원 이하의 벌금에 처한다.', 4714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8397, '⑤ 제3항 또는 제4항의 죄를 범한 사람이 본범과 친족일 때에는 그 형을 감경하거나 면제할 수 있다.', 4714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8398, '⑥ 제2항에 따른 감독기관 및 감독업무에 종사하는 사람의 범위는 대통령령으로 정한다.', 4714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8399, '① 제3조, 제4조제2항(미수범을 포함한다), 제5조제4항 또는 제8조에 따라 유죄판결을 받은 사람은 다음 각 호의 기간 동안 금융회사등, 국가ㆍ지방자치단체가 자본금의 전부 또는 일부를 출자한 기관 및 그 출연(出捐)이나 보조를 받는 기관과 유죄판결된 범죄행위와 밀접한 관련이 있는 기업체에 취업할 수 없다. 다만, 대통령령으로 정하는 바에 따라 법무부장관의 승인을 받은 경우에는 그러하지 아니하다.', 4716);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8400, '② 제1항에 규정된 사람 또는 그를 대표자나 임원으로 하는 기업체는 제1항 각 호의 기간 동안 대통령령으로 정하는 관허업(官許業)의 허가ㆍ인가ㆍ면허ㆍ등록ㆍ지정 등(이하 이 조에서 "허가등"이라 한다)을 받을 수 없다. 다만, 대통령령으로 정하는 바에 따라 법무부장관의 승인을 받은 경우에는 그러하지 아니하다.', 4716);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8401, '③ 제1항의 경우 국가ㆍ지방자치단체가 자본금의 전부 또는 일부를 출자한 기관 및 그 출연이나 보조를 받는 기관과 유죄판결된 범죄행위와 밀접한 관련이 있는 기업체의 범위는 대통령령으로 정한다.', 4716);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8402, '④ 법무부장관은 제1항 또는 제2항을 위반한 사람이 있을 때에는 그 사람이 취업하고 있는 기관이나 기업체의 장 또는 허가등을 한 행정기관의 장에게 그의 해임(解任)이나 허가등의 취소를 요구하여야 한다.', 4716);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8403, '⑤ 제4항에 따라 해임 요구를 받은 기관이나 기업체의 장은 지체 없이 그 요구에 따라야 한다.', 4716);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8404, '⑥ 제1항, 제2항 또는 제5항을 위반한 자는 1년 이하의 징역 또는 500만원 이하의 벌금에 처한다.', 4716);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8405, null, 4718);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8406, null, 4719);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8407, '①지방검찰청 또는 지방검찰청지청의 장은 법 제3조ㆍ법 제4조제2항 (미수범을 포함한다)ㆍ법 제5조제4항 또는 법 제8조의 죄를 범한 사람에 대하여 공소가 제기된 경우에는 지체 없이 그 사실을 법무부장관에게 보고하여야 한다. <개정 2009.7.7, 2019.5.7>', 4725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8408, '② 고위공직자범죄수사처장은 제1항에서 규정한 죄를 범한 사람에 대하여 공소가 제기된 경우에는 지체 없이 그 사실을 법무부장관에게 통보해야 한다. <신설 2020.7.14>', 4725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8409, '③법무부장관은 경제사범의 관리를 위하여 필요할 경우 관계기관 또는 관계기업체의 장에게 자료의 제출을 요청할 수 있다. <개정 2009.7.7, 2020.7.14>', 4725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8410, '① 법 제14조제1항 본문에 따른 국가ㆍ지방자치단체가 자본금의 전부 또는 일부를 출자한 기관 및 그 출연(出捐)이나 보조를 받는 기관은 별표 1부터 별표 3까지에 해당하는 기관으로 한다. <개정 2019.5.7>', 4726);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8411, '②법 제14조제1항 본문에 따른 유죄판결된 범죄행위와 밀접한 관련이 있는 기업체는 다음 각 호의 어느 하나에 해당하는 기업체로 한다. <개정 2019.5.7>', 4726);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8412, '①법 제14조제1항 단서에 따라 법무부장관의 취업승인을 받으려는 사람은 취업하려는 날의 1개월 전까지 법무부장관에게 취업승인신청서를 제출하여야 한다. <개정 2009.7.7, 2019.5.7>', 4729);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8413, '② 법무부장관은 법 제14조제1항 단서에 따른 취업의 승인 여부를 결정한 때에는 지체 없이 그 결정내용을 신청인에게 통지하여야 한다. <개정 2009.7.7>', 4729);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8414, '①제11조에 따른 관허업을 영위하기 위하여 법 제14조제2항 단서에 따른 법무부장관의 승인을 받으려는 사람은 승인신청서를 해당 관허업의 허가등에 관한 소관 행정기관의 장에게 제출하여야 한다. <개정 2009.7.7, 2019.5.7>', 4730);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8415, '②제1항에 따른 승인신청서에는 관허업의 허가등에 관한 신청서류의 사본 1부를 첨부하여야 한다. <개정 2019.5.7>', 4730);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8416, '③ 소관 행정기관의 장은 제1항에 따른 승인신청서를 받은 때에는 관허업의 허가등에 관한 신청서류의 사본이 원본과 다름없음을 확인한 후 지체 없이 이를 법무부장관에게 송부하여야 한다. <개정 2009.7.7, 2019.5.7>', 4730);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8417, '④법무부장관이 제3항에 따른 승인신청서를 송부받아 그 승인여부를 결정한 때에는 지체 없이 그 내용을 그 승인신청을 한 사람과 소관 행정기관의 장에게 통지하여야 한다. <개정 2009.7.7, 2019.5.7>', 4730);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8418, '① 법무부장관은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 민감정보, 같은 법 시행령 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호, 외국인등록번호나 그 밖의 개인정보가 포함된 자료를 처리할 수 있다.', 4731);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8419, '② 허가등에 관한 소관 행정기관의 장은 법 제14조제2항 및 이 영 제14조에 따른 허가등의 승인 신청에 관한 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다.', 4731);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8420, '① 「형법」 제129조ㆍ제130조 또는 제132조에 규정된 죄를 범한 사람은 그 수수(收受)ㆍ요구 또는 약속한 뇌물의 가액(價額)(이하 이 조에서 "수뢰액"이라 한다)에 따라 다음 각 호와 같이 가중처벌한다.', 4733);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8421, '② 「형법」 제129조ㆍ제130조 또는 제132조에 규정된 죄를 범한 사람은 그 죄에 대하여 정한 형(제1항의 경우를 포함한다)에 수뢰액의 2배 이상 5배 이하의 벌금을 병과(倂科)한다.', 4733);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8422, '① 다음 각 호의 어느 하나에 해당하는 기관 또는 단체로서 대통령령으로 정하는 기관 또는 단체의 간부직원은 「형법」 제129조부터 제132조까지의 규정을 적용할 때에는 공무원으로 본다.', 4735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8423, '② 제1항의 간부직원의 범위는 제1항의 기관 또는 단체의 설립목적, 자산, 직원의 규모 및 해당 직원의 구체적인 업무 등을 고려하여 대통령령으로 정한다.', 4735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8424, '① 「형법」 제124조ㆍ제125조에 규정된 죄를 범하여 사람을 상해(傷害)에 이르게 한 경우에는 1년 이상의 유기징역에 처한다.', 4736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8425, '② 「형법」 제124조ㆍ제125조에 규정된 죄를 범하여 사람을 사망에 이르게 한 경우에는 무기 또는 3년 이상의 징역에 처한다.', 4736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8426, null, 4738);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8427, '① 13세 미만의 미성년자에 대하여 「형법」 제287조의 죄를 범한 사람은 그 약취(略取) 또는 유인(誘引)의 목적에 따라 다음 각 호와 같이 가중처벌한다. <개정 2016.1.6>', 4739);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8428, '② 13세 미만의 미성년자에 대하여 「형법」 제287조의 죄를 범한 사람이 다음 각 호의 어느 하나에 해당하는 행위를 한 경우에는 다음 각 호와 같이 가중처벌한다. <개정 2016.1.6>', 4739);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8429, '③ 제1항 또는 제2항의 죄를 범한 사람을 방조(幇助)하여 약취 또는 유인된 미성년자를 은닉하거나 그 밖의 방법으로 귀가하지 못하게 한 사람은 5년 이상의 유기징역에 처한다.', 4739);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8430, '④ 삭제 <2013.4.5>', 4739);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8431, '⑤ 삭제 <2013.4.5>', 4739);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8432, '⑥ 제1항 및 제2항(제2항제4호는 제외한다)에 규정된 죄의 미수범은 처벌한다. <개정 2013.4.5>', 4739);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8433, '⑦ 제1항부터 제3항까지 및 제6항의 죄를 범한 사람을 은닉하거나 도피하게 한 사람은 3년 이상 25년 이하의 징역에 처한다. <개정 2013.4.5, 2016.1.6>', 4739);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8434, '⑧ 제1항 또는 제2항제1호ㆍ제2호의 죄를 범할 목적으로 예비하거나 음모한 사람은 1년 이상 10년 이하의 징역에 처한다. <개정 2013.4.5, 2016.1.6>', 4739);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8435, '① 「도로교통법」 제2조의 자동차, 원동기장치자전거 또는 「건설기계관리법」 제26조제1항 단서에 따른 건설기계 외의 건설기계(이하 "자동차등"이라 한다)의 교통으로 인하여 「형법」 제268조의 죄를 범한 해당 자동차등의 운전자(이하 "사고운전자"라 한다)가 피해자를 구호(救護)하는 등 「도로교통법」 제54조제1항에 따른 조치를 하지 아니하고 도주한 경우에는 다음 각 호의 구분에 따라 가중처벌한다. <개정 2022.12.27>', 4740);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8436, '② 사고운전자가 피해자를 사고 장소로부터 옮겨 유기하고 도주한 경우에는 다음 각 호의 구분에 따라 가중처벌한다.', 4740);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8437, '① 삭제 <2016.1.6>', 4741);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8438, '② 5명 이상이 공동하여 상습적으로 「형법」 제329조부터 제331조까지의 죄 또는 그 미수죄를 범한 사람은 2년 이상 20년 이하의 징역에 처한다. <개정 2016.1.6>', 4741);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8439, '③ 삭제 <2016.1.6>', 4741);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8440, '④ 삭제 <2016.1.6>', 4741);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8441, '⑤ 「형법」 제329조부터 제331조까지, 제333조부터 제336조까지 및 제340조ㆍ제362조의 죄 또는 그 미수죄로 세 번 이상 징역형을 받은 사람이 다시 이들 죄를 범하여 누범(累犯)으로 처벌하는 경우에는 다음 각 호의 구분에 따라 가중처벌한다. <개정 2016.1.6>', 4741);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8442, '⑥ 상습적으로 「형법」 제329조부터 제331조까지의 죄나 그 미수죄 또는 제2항의 죄로 두 번 이상 실형을 선고받고 그 집행이 끝나거나 면제된 후 3년 이내에 다시 상습적으로 「형법」 제329조부터 제331조까지의 죄나 그 미수죄 또는 제2항의 죄를 범한 경우에는 3년 이상 25년 이하의 징역에 처한다. <개정 2016.1.6>', 4741);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8443, '① 자기 또는 타인의 형사사건의 수사 또는 재판과 관련하여 고소ㆍ고발 등 수사단서의 제공, 진술, 증언 또는 자료제출에 대한 보복의 목적으로 「형법」 제250조제1항의 죄를 범한 사람은 사형, 무기 또는 10년 이상의 징역에 처한다. 고소ㆍ고발 등 수사단서의 제공, 진술, 증언 또는 자료제출을 하지 못하게 하거나 고소ㆍ고발을 취소하게 하거나 거짓으로 진술ㆍ증언ㆍ자료제출을 하게 할 목적인 경우에도 또한 같다.', 4746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8444, '② 제1항과 같은 목적으로 「형법」 제257조제1항ㆍ제260조제1항ㆍ제276조제1항 또는 제283조제1항의 죄를 범한 사람은 1년 이상의 유기징역에 처한다.', 4746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8445, '③ 제2항의 죄 중 「형법」 제257조제1항ㆍ제260조제1항 또는 제276조제1항의 죄를 범하여 사람을 사망에 이르게 한 경우에는 무기 또는 3년 이상의 징역에 처한다.', 4746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8446, '④ 자기 또는 타인의 형사사건의 수사 또는 재판과 관련하여 필요한 사실을 알고 있는 사람 또는 그 친족에게 정당한 사유 없이 면담을 강요하거나 위력(威力)을 행사한 사람은 3년 이하의 징역 또는 300만원 이하의 벌금에 처한다.', 4746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8447, '① 운행 중(「여객자동차 운수사업법」 제2조제3호에 따른 여객자동차운송사업을 위하여 사용되는 자동차를 운행하는 중 운전자가 여객의 승차ㆍ하차 등을 위하여 일시 정차한 경우를 포함한다)인 자동차의 운전자를 폭행하거나 협박한 사람은 5년 이하의 징역 또는 2천만원 이하의 벌금에 처한다. <개정 2015.6.22>', 4747);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8448, '② 제1항의 죄를 범하여 사람을 상해에 이르게 한 경우에는 3년 이상의 유기징역에 처하고, 사망에 이르게 한 경우에는 무기 또는 5년 이상의 징역에 처한다.', 4747);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8449, '① 음주 또는 약물의 영향으로 정상적인 운전이 곤란한 상태에서 자동차등을 운전하여 사람을 상해에 이르게 한 사람은 1년 이상 15년 이하의 징역 또는 1천만원 이상 3천만원 이하의 벌금에 처하고, 사망에 이르게 한 사람은 무기 또는 3년 이상의 징역에 처한다. <개정 2018.12.18, 2020.2.4, 2022.12.27>', 4748);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8450, '② 음주 또는 약물의 영향으로 정상적인 운항이 곤란한 상태에서 운항의 목적으로 「해상교통안전법」 제39조제1항에 따른 선박의 조타기를 조작, 조작 지시 또는 도선하여 사람을 상해에 이르게 한 사람은 1년 이상 15년 이하의 징역 또는 1천만원 이상 3천만원 이하의 벌금에 처하고, 사망에 이르게 한 사람은 무기 또는 3년 이상의 징역에 처한다. <신설 2020.2.4, 2023.7.25>', 4748);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8451, null, 4749);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8452, null, 4750);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8453, '① 「관세법」 제269조제1항에 규정된 죄를 범한 사람은 다음 각 호의 구분에 따라 가중처벌한다.', 4751);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8454, '② 「관세법」 제269조제2항에 규정된 죄를 범한 사람은 다음 각 호의 구분에 따라 가중처벌한다.', 4751);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8455, '③ 「관세법」 제269조제3항에 규정된 죄를 범한 사람이 수출하거나 반송한 물품의 원가가 5억원 이상인 경우에는 1년 이상의 유기징역에 처한다.', 4751);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8456, '④ 「관세법」 제270조제1항제1호 또는 같은 조 제4항ㆍ제5항에 규정된 죄를 범한 사람은 다음 각 호의 구분에 따라 가중처벌한다.', 4751);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8457, '⑤ 「관세법」 제270조제1항제2호 또는 같은 조 제2항에 규정된 죄를 범한 사람은 다음 각 호의 구분에 따라 가중처벌한다.', 4751);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8458, '⑥ 제1항부터 제5항까지의 경우에는 다음 각 호의 구분에 따른 벌금을 병과한다.', 4751);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8459, '⑦ 「관세법」 제271조에 규정된 죄를 범한 사람은 제1항부터 제6항까지의 예에 따른 그 정범(正犯) 또는 본죄(本罪)에 준하여 처벌한다.', 4751);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8460, '⑧ 단체 또는 집단을 구성하거나 상습적으로 「관세법」 제269조부터 제271조까지 또는 제274조에 규정된 죄를 범한 사람은 무기 또는 10년 이상의 징역에 처한다.', 4751);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8461, '① 「조세범 처벌법」 제3조제1항, 제4조 및 제5조, 「지방세기본법」 제102조제1항에 규정된 죄를 범한 사람은 다음 각 호의 구분에 따라 가중처벌한다. <개정 2011.12.31, 2016.12.27>', 4753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8462, '② 제1항의 경우에는 그 포탈세액등의 2배 이상 5배 이하에 상당하는 벌금을 병과한다.', 4753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8463, '① 영리를 목적으로 「조세범 처벌법」 제10조제3항 및 제4항 전단의 죄를 범한 사람은 다음 각 호의 구분에 따라 가중처벌한다.', 4754);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8464, '② 제1항의 경우에는 공급가액등의 합계액에 부가가치세의 세율을 적용하여 계산한 세액의 2배 이상 5배 이하의 벌금을 병과한다.', 4754);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8465, '① 「산림자원의 조성 및 관리에 관한 법률」 제73조 및 제74조에 규정된 죄를 범한 사람은 다음 각 호의 구분에 따라 가중처벌한다. <개정 2016.1.6>', 4755);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8466, '② 삭제 <2016.1.6>', 4755);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8467, '① 「마약류관리에 관한 법률」 제58조제1항제1호부터 제4호까지 및 제6호ㆍ제7호에 규정된 죄(매매, 수수 및 제공에 관한 죄와 매매목적, 매매 유인ㆍ권유ㆍ알선 목적 또는 수수목적의 소지ㆍ소유에 관한 죄는 제외한다) 또는 그 미수죄를 범한 사람은 다음 각 호의 구분에 따라 가중처벌한다. <개정 2016.1.6, 2025.4.1>', 4757);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8468, '② 「마약류관리에 관한 법률」 제59조제1항부터 제3항까지 및 제60조에 규정된 죄(마약 및 향정신성의약품에 관한 죄만 해당한다)를 범한 사람은 다음 각 호의 구분에 따라 가중처벌한다. <개정 2016.1.6>', 4757);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8469, null, 4758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8470, null, 4764);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8471, null, 4765);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8472, '① 이 법에 규정된 군사경찰의 직권은 그 직무수행에 필요한 최소한도에서 행사되어야 하며 남용되어서는 아니 된다.', 4767);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8473, '② 군사경찰은 이 법에서 정하는 정당한 직무범위를 벗어나 정보를 수집하거나 활용하여서는 아니 된다.', 4767);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8474, null, 4768);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8475, '① 이 법에 따른 군사경찰의 직무는 원칙적으로 「군인사법」 및 「군무원인사법」의 적용을 받는 군인, 군무원에 대하여 적용한다.', 4769);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8476, '② 제1항에도 불구하고 제7조 및 제8조는 군사지역에 거주하거나 일시적으로 방문하는 민간인(외국인을 포함한다)에게도 적용한다.', 4769);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8477, '③ 제1항에도 불구하고 제11조부터 제14조까지는 「군형법」 제1조제4항에 해당하는 죄를 범한 내국인ㆍ외국인에게도 적용한다.', 4769);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8478, '① 군사경찰은 군사경찰부대가 설치되어 있는 부대의 장의 지휘ㆍ감독 하에 다음 각 호의 직무를 수행한다. <개정 2022.12.13>', 4770);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8479, '② 국방부장관은 군사경찰 직무의 최고 지휘자ㆍ감독자로서 군사경찰에 관한 정책을 총괄하기 위하여 국방부 소속으로 조사본부를 둔다.', 4770);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8480, '③ 각 군 참모총장은 각 군 군사경찰 직무의 지휘자ㆍ감독자로서 각 군 소속 부대의 군사경찰 직무를 총괄하기 위하여 군사경찰실이나 군사경찰단을 둔다.', 4770);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8481, '④ 군사경찰부대가 설치되어 있는 부대의 장은 소관 군사경찰 직무를 관장하고 소속 군사경찰을 지휘ㆍ감독한다.', 4770);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8482, '⑤ 군사경찰인 병은 소속 군사경찰부대 간부(제3조제1호에 규정된 장교ㆍ준사관ㆍ부사관 및 군무원을 말한다)의 지시를 받아 군사에 관한 경찰의 직무를 보조한다.', 4770);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8483, '⑥ 그 밖에 군사경찰의 직무범위와 지휘ㆍ감독에 관한 구체적 사항은 대통령령으로 정한다.', 4770);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8484, '① 군사경찰은 군사지역에서 다음 각 호의 어느 하나에 해당하는 사람을 정지시켜 질문(이하 이 조에서 "직무질문"이라 한다)할 수 있으며, 이 경우 신분증명서의 제시 등 신원확인에 필요한 조치를 취할 수 있다.', 4772);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8485, '② 군사경찰은 제1항에 따라 같은 항 각 호의 사람을 정지시킨 장소에서 직무질문을 하는 것이 그 사람에게 불리하거나 교통에 방해가 된다고 인정될 때에는 질문을 하기 위하여 가까운 군사경찰부대, 검문소 등(이하 이 조에서 "군사경찰부대등"이라 한다)에 동행할 것을 요구할 수 있다. 이 경우 동행을 요구받은 사람은 군사경찰의 그 요구를 거절할 수 있다. 다만, 제4조제1항에 규정되지 아니한 사람은 「군형법」 제1조제4항에 해당되는 범죄를 저질렀다고 명백히 인정되지 아니하면 가까운 경찰서ㆍ지구대ㆍ파출소 또는 출장소(지방해양경찰관서를 포함한다. 이하 이 조에서 "경찰관서"라 한다)로 동행할 것을 요구할 수 있다.', 4772);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8486, '③ 군사경찰은 직무질문을 하는 때에 무기 또는 흉기를 가지고 있는 지를 조사할 수 있다.', 4772);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8487, '④ 군사경찰은 직무질문을 하거나 동행을 요구하는 때에는 자신의 신분을 표시하는 증표를 제시하면서 소속과 성명을 밝히고 질문이나 동행의 목적과 이유를 설명하여야 하며, 동행을 요구하는 경우에는 동행 장소를 밝혀야 한다.', 4772);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8488, '⑤ 군사경찰은 제2항에 따라 동행한 사람의 소속 부대장과 가족 또는 친지, 그 밖의 연고자에게 동행한 군사경찰의 신분, 동행 장소 및 동행 목적과 이유를 직접 알리거나 본인으로 하여금 가족이나 친지 등 연고자에게 즉시 연락할 수 있는 기회를 주어야 하며, 변호인의 도움을 받을 권리가 있음을 알려야 한다.', 4772);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8489, '⑥ 군사경찰은 동행한 사람을 6시간을 초과하여 군사경찰부대등 또는 경찰관서에 머물게 할 수 없으며, 당사자의 요청이 있을 경우에는 즉시 동행을 해제하여야 한다.', 4772);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8490, '⑦ 제1항부터 제3항까지의 규정에 따라 질문을 받거나 동행을 요구받은 사람은 군사법원의 소송절차에 관한 법률에 따르지 아니하고는 신체를 구속당하지 아니하며, 그 의사에 반하여 답변을 강요당하지 아니한다.', 4772);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8491, '① 군사경찰은 군사지역에서 위험한 사태가 발생하여 사람의 생명ㆍ신체 또는 재산에 대한 위해가 임박한 때에 그 위해를 방지하거나 피해자를 구조하기 위하여 부득이하다고 인정하면 합리적으로 판단하여 필요한 한도에서 다른 사람의 토지ㆍ건물ㆍ배 또는 차에 출입할 수 있다.', 4774);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8492, '② 군사경찰이 제1항에 따라 출입할 때에는 그 신분을 표시하는 증표를 제시하여야 하며, 함부로 관계인의 정당한 업무를 방해하여서는 아니 된다.', 4774);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8493, '① 군사경찰은 군사지역에서 안전하고 원활한 교통ㆍ운항ㆍ항행 질서를 유지하기 위하여 교통ㆍ운항ㆍ항행 상의 위험과 장해를 방지 및 제거하여야 하며, 「도로교통법」 제44조 및 제45조, 「해상교통안전법」 제39조 및 제40조, 「항공안전법」 제57조에 따라 금지된 행위를 단속할 수 있다. <개정 2023.7.25>', 4775);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8494, '② 군사경찰은 제1항에 따른 단속행위를 할 때 술에 취하였는지를 호흡조사로 측정할 수 있다. 이 경우 단속을 받는 사람은 군사경찰의 측정 요구에 따라야 한다.', 4775);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8495, '③ 제2항에 따른 측정 결과에 불복하는 사람에 대해서는 본인의 동의를 받아 혈액 채취 등의 방법으로 다시 측정할 수 있다.', 4775);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8496, '④ 제1항부터 제3항까지의 직무수행에 관한 구체적 사항은 대통령령으로 정한다.', 4775);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8497, '① 군사경찰은 직무수행 중 군사경찰장비를 사용할 수 있다. 다만, 위해성 군사경찰장비를 사용할 때에는 필요한 안전교육과 안전검사를 받은 후 사용하여야 한다.', 4776);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8498, '② 군사경찰은 군사경찰장비를 함부로 개조하거나 군사경찰장비에 임의의 장비를 부착하여 일반적인 사용법과 달리 사용함으로써 다른 사람의 생명ㆍ신체에 위해를 끼쳐서는 아니 된다.', 4776);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8499, '③ 위해성 군사경찰장비는 필요한 최소한도에서 사용하여야 한다.', 4776);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8500, '④ 국방부장관은 위해성 군사경찰장비를 새로 도입하려는 경우에는 대통령령으로 정하는 바에 따라 안전성 검사를 실시하여 그 안전성 검사의 결과보고서를 국회 소관 상임위원회에 제출하여야 한다. 이 경우 안전성 검사에는 외부 전문가를 참여시켜야 한다.', 4776);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8501, '⑤ 위해성 군사경찰장비의 종류ㆍ사용기준 및 안전교육ㆍ안전검사의 기준 등은 대통령령으로 정한다.', 4776);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8502, null, 4777);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8503, null, 4778);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8504, '① 군사경찰은 범인의 체포, 도주 방지, 자신이나 다른 사람의 생명ㆍ신체에 대한 방어 및 보호, 공무집행에 대한 항거의 제지를 위하여 필요하다고 인정되는 상당한 이유가 있을 때에는 그 사태를 합리적으로 판단하여 최소한의 범위에서 무기를 사용할 수 있다. 다만, 다음 각 호의 어느 하나에 해당하는 때를 제외하고는 사람에게 위해를 끼쳐서는 아니 된다.', 4779);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8505, '② 군사경찰은 무기를 사용할 때 무기 사용을 야기한 자와 관계없는 자에게 피해가 발생하지 아니하도록 하여야 하며, 주위의 정황상 무기의 사용이 필요하지 아니하게 된 때에는 즉시 그 사용을 중지하여야 한다.', 4779);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8506, '③ 군사경찰은 제1항에 따라 무기를 사용한 때에는 그 사유 및 상황을 지체 없이 소속 군사경찰부대의 지휘관에게 보고하고, 소속 군사경찰부대의 지휘관은 그 상급부대의 지휘관에게 지체 없이 보고하여야 한다.', 4779);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8507, '① 군사경찰부대의 지휘관은 군사경찰장비의 사용방법ㆍ관리 및 안전 등에 관하여 교육을 실시하여야 한다.', 4780);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8508, '② 군사경찰부대의 지휘관은 위해성 군사경찰장비에 대하여 정기적인 안전검사를 실시하여야 한다.', 4780);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8509, '③ 군사경찰부대의 지휘관은 제1항에 따른 안전교육을 받지 아니한 자에게 군사경찰의 직무를 수행하도록 하거나 제2항에 따른 안전검사를 받지 아니한 위해성 군사경찰장비를 사용하게 하여서는 아니 된다.', 4780);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8510, '④ 제1항에 따른 군사경찰장비의 사용방법ㆍ관리 및 안전 등에 관한 교육의 방법과 제2항에 따른 안전검사의 기준 등 구체적인 사항에 관하여는 대통령령으로 정한다.', 4780);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8511, null, 4784);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8512, '① 이 법에 규정된 군사경찰의 의무를 위반하거나 직권을 남용하여 다른 사람에게 피해를 끼친 군사경찰에 대해서는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 4786);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8513, '② 술에 취한 상태에 있다고 인정할 만한 상당한 이유가 있는 사람으로서 제10조제2항에 따른 군사경찰의 측정 요구에 따르지 아니한 사람은 1년 이상 5년 이하의 징역이나 500만원 이상 2천만원 이하의 벌금에 처한다.', 4786);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8514, '③ 제10조제2항을 위반하여 군사경찰의 측정 요구에 따르지 아니한 「선박직원법」 제2조제1호에 따른 선박(같은 호 각 목의 어느 하나에 해당하는 외국선박을 포함한다)의 조타기를 조작하거나 그 조작을 지시한 운항자 또는 도선을 한 자와 「항공안전법」 제2조제1호에 따른 항공기를 조작한 항공종사자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.', 4786);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8515, null, 4788);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8516, null, 4790);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8517, null, 4791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8518, '① 군사경찰은 법 제10조제1항에 따른 단속을 하기 전에 제3조에 따른 신분을 표시하는 증표를 단속 대상자에게 보여줘야 한다.', 4794);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8519, '② 군사경찰은 법 제10조제2항에 따른 단속행위를 한 경우 별지 제1호서식의 음주 단속 보고서를 작성해야 한다.', 4794);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8520, '③ 제1항 및 제2항에서 규정한 사항 외에 단속행위의 세부 절차와 방법, 단속 결과의 처리 등 필요한 사항은 국방부장관이 정한다.', 4794);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8521, null, 4795);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8522, null, 4798);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8523, '① 국방부장관은 위해성 군사경찰장비를 새로 도입하려는 경우 법 제11조제4항에 따라 안전성 검사를 실시하여 새로 도입하려는 위해성 군사경찰장비(이하 이 조에서 "신규도입장비"라 한다)가 사람의 생명이나 신체에 미치는 영향을 평가해야 한다.', 4799);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8524, '② 제1항에 따른 안전성 검사는 신규도입장비와 관련된 분야의 외부 전문가가 신규도입장비의 주요 특성이나 작동원리에 기초하여 제시하는 검사방법 및 기준에 따라 실시한다. 이 경우 신규도입장비에 대하여 일반적으로 인정되는 합리적인 검사방법이나 기준이 있을 때에는 그 검사방법이나 기준에 따라 안전성 검사를 실시할 수 있다.', 4799);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8525, '③ 법 제11조제4항 후단에 따라 안전성 검사에 참여한 외부 전문가는 안전성 검사가 끝난 날부터 30일 이내에 신규도입장비의 안전성 여부에 대한 의견을 국방부장관에게 제출해야 한다.', 4799);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8526, '④ 국방부장관은 법 제11조제4항 전단에 따라 신규도입장비에 대한 안전성 검사를 실시한 날부터 3개월 이내에 다음 각 호의 내용이 포함된 안전성 검사 결과보고서를 국회 소관 상임위원회에 제출해야 한다.', 4799);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8527, '① 법 제17조제1항에 따라 손실보상을 할 때 생명ㆍ신체상의 손실의 경우에는 별표 3의 기준에 따라 보상한다.', 4800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8528, '② 법 제17조제1항에 따라 손실보상을 할 때 재산상 손실 중 물건의 멸실ㆍ훼손으로 인한 손실의 경우에는 다음 각 호의 기준에 따라 보상한다.', 4800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8529, '③ 법 제17조제1항에 따라 손실보상을 할 때 물건의 멸실ㆍ훼손으로 인한 손실 외의 재산상 손실에 대해서는 직무집행과 상당한 인과관계가 있는 범위에서 보상한다.', 4800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8530, '④ 법 제17조제1항에 따라 보상금을 지급받을 사람이 동일한 원인으로 다른 법령에 따라 보상금 등을 지급받은 경우에는 그 보상금 등에 해당하는 금액을 제외하고 보상금을 지급한다.', 4800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8531, '① 법 제17조제1항에 따라 손실을 보상받으려는 사람은 별지 제2호서식의 보상금 지급 청구서에 손실내용과 손실금액을 증명할 수 있는 서류를 첨부하여 손실보상청구 사건 발생지를 작전지역으로 하는 부대의 장에게 제출해야 한다.', 4801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8532, '② 제1항에 따라 보상금 지급 청구서를 받은 부대의 장은 해당 청구서를 국방부장관에게 보내야 한다.', 4801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8533, '③ 제2항에 따라 보상금 지급 청구서를 받은 국방부장관은 법 제17조제3항에 따른 손실보상심의위원회의 심의ㆍ의결을 거쳐 보상 여부 및 보상금액을 결정하되, 다음 각 호의 어느 하나에 해당하는 경우에는 그 청구를 각하하는 결정을 해야 한다.', 4801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8534, '④ 국방부장관은 제3항에 따른 결정일부터 10일 이내에 다음 각 호의 구분에 따른 통지서에 결정 내용을 적어서 청구인에게 통지해야 한다.', 4801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8535, '⑤ 보상금은 다른 법률에 특별한 규정이 있는 경우를 제외하고는 현금으로 지급해야 한다.', 4801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8536, '⑥ 보상금은 일시금으로 지급하되, 예산 부족 등의 사유로 일시금으로 지급할 수 없는 특별한 사정이 있는 경우에는 청구인의 동의를 받아 분할하여 지급할 수 있다.', 4801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8537, '⑦ 보상금을 지급받은 사람은 보상금을 지급받은 원인과 동일한 원인으로 인한 부상이 악화되거나 새로 발견되어 다음 각 호의 어느 하나에 해당하는 경우에는 보상금의 추가 지급을 청구할 수 있다. 이 경우 보상금 지급 청구, 보상금액 결정, 보상금 지급 결정에 대한 통지, 보상금 지급방법 등에 관하여는 제1항부터 제6항까지의 규정을 준용한다.', 4801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8538, '⑧ 제1항부터 제7항까지에서 규정한 사항 외에 손실보상의 청구 및 지급에 필요한 사항은 국방부장관이 정한다.', 4801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8539, '① 법 제17조제3항에 따른 손실보상심의위원회(이하 "위원회"라 한다)는 위원장 1명을 포함하여 5명 이상 7명 이하의 위원으로 구성한다.', 4802);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8540, '② 위원회의 위원은 국방부 소속 군사경찰 중 영관급 및 장성급 장교와 다음 각 호의 어느 하나에 해당하는 사람 중에서 국방부장관이 위촉하거나 임명한다. 이 경우 위원의 과반수는 군사경찰이 아닌 사람으로 해야 한다.', 4802);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8541, '③ 위촉위원의 임기는 2년으로 한다.', 4802);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8542, '④ 위원회의 사무를 처리하기 위하여 위원회에 간사 1명을 두며, 간사는 소속 공무원 중에서 국방부장관이 임명한다.', 4802);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8543, '① 위원장은 위원 중에서 호선(互選)한다.', 4803);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8544, '② 위원장은 위원회를 대표하며, 위원회의 업무를 총괄한다.', 4803);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8545, '③ 위원장이 부득이한 사유로 직무를 수행할 수 없는 때에는 위원장이 미리 지명한 위원이 그 직무를 대행한다.', 4803);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8546, '① 위원장은 위원회의 회의를 소집하고, 그 의장이 된다.', 4804);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8547, '② 위원회의 회의는 재적위원 과반수의 출석으로 개의(開議)하고, 출석위원 과반수의 찬성으로 의결한다.', 4804);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8548, '③ 위원회는 심의를 위하여 필요한 경우에는 관계 공무원이나 관계 기관에 사실조사나 자료의 제출 등을 요구할 수 있으며, 관계 전문가에게 필요한 정보의 제공이나 의견의 진술 등을 요청할 수 있다.', 4804);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8549, '① 위원회의 위원이 다음 각 호의 어느 하나에 해당하는 경우에는 위원회의 심의ㆍ의결에서 제척(除斥)된다.', 4805);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8550, '② 청구인은 위원에게 공정한 심의ㆍ의결을 기대하기 어려운 사정이 있는 경우에는 위원회에 기피 신청을 할 수 있고, 위원회는 의결로 기피 여부를 결정한다. 이 경우 기피 신청의 대상인 위원은 그 의결에 참여할 수 없다.', 4805);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8551, '③ 위원이 제1항 각 호에 따른 제척 사유에 해당하는 경우에는 스스로 해당 안건의 심의ㆍ의결에서 회피(回避)해야 한다.', 4805);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8552, null, 4806);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8553, null, 4809);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8554, '① 「스토킹방지 및 피해자보호 등에 관한 법률」(이하 "법"이라 한다) 제4조제1항에 따른 스토킹에 대한 실태조사(이하 이 조에서 "실태조사"라 한다)에는 다음 각 호의 사항이 포함되어야 한다.', 4811);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8555, '② 여성가족부장관은 실태조사를 스토킹에 관한 전문성과 인력ㆍ장비를 갖춘 연구기관ㆍ법인 또는 단체에 의뢰하여 실시할 수 있다.', 4811);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8556, '① 법 제5조제1항 본문에서 "대통령령으로 정하는 공공단체"란 다음 각 호의 기관 또는 단체를 말한다.', 4812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8557, '② 법 제5조제3항에서 "대통령령으로 정하는 공공단체"란 다음 각 호의 기관 또는 단체를 말한다.', 4812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8558, '③ 국가기관, 지방자치단체의 장 및 제2항 각 호에 따른 공공단체의 장은 법 제5조제3항에 따라 스토킹 방지를 위한 자체 예방지침을 마련하는 경우 「성폭력방지 및 피해자보호 등에 관한 법률」 제5조제1항에 따른 자체 예방지침 및 「양성평등기본법」 제31조제1항에 따른 자체 예방지침과 통합하여 마련할 수 있다.', 4812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8559, '④ 법 제5조제3항에 따른 재발방지대책에는 다음 각 호의 사항이 포함되어야 한다.', 4812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8560, '⑤ 국가기관, 지방자치단체의 장 및 제2항 각 호에 따른 공공단체의 장은 법 제5조제3항에 따른 재발방지대책을 수립ㆍ시행하는 경우 스토킹이 「성폭력방지 및 피해자보호 등에 관한 법률」에 따른 성폭력 또는 「양성평등기본법」에 따른 성희롱과 결합된 사건인 경우에는 「성폭력방지 및 피해자보호 등에 관한 법률」 제5조제1항에 따른 재발방지대책 및 「양성평등기본법」 제31조제1항에 따른 재발방지대책과 통합하여 수립ㆍ시행할 수 있다.', 4812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8561, '① 법 제7조제1항에 따라 피해자나 그 가족구성원(이하 "피해자등"이라 한다)을 주소지 외의 지역에 취학(입학ㆍ재입학ㆍ전학 및 편입학을 포함한다. 이하 이 조에서 같다)시키려는 경우 다음 각 호의 절차에 따라야 한다.', 4813);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8562, '② 「초ㆍ중등교육법」 제2조에 따른 각급 학교의 장, 교육장 또는 교육감은 피해자등을 보호하기 위하여 제1항 각 호에 따라 조치한 사실이 취학 업무 관계자가 아닌 사람에게 공개되지 않도록 관리ㆍ감독해야 한다.', 4813);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8563, '③ 제1항에 따른 절차에 따라 취학에 걸린 기간은 피해자등의 출석일수에 산입한다.', 4813);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8564, null, 4815);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8565, '① 법 제11조제1항에 따른 교육은 지원시설의 장 및 상담원에 대하여 연간 8시간 이상 20시간 이하로 실시해야 한다. 이 경우 집합교육 또는 인터넷 강의 등의 방법으로 실시할 수 있다.', 4818);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8566, '② 제1항에 따른 교육에는 다음 각 호의 내용을 포함해야 한다.', 4818);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8567, '③ 법 제11조제2항에서 "대통령령으로 정하는 전문기관"이란 「양성평등기본법」 제46조의2에 따른 한국여성인권진흥원을 말한다.', 4818);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8568, '① 국가기관, 지방자치단체의 장(해당 권한이 위임ㆍ위탁된 경우에는 그 권한을 위임ㆍ위탁받은 자를 포함한다) 또는 지원시설의 장은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법 시행령」 제19조제1호 또는 제4호에 따른 주민등록번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 4819);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8569, '② 지원시설의 장은 법 제9조제5호에 따른 의료 지원 업무에 관한 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보가 포함된 자료를 처리할 수 있다.', 4819);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8570, null, 4820);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8571, '① 「보호관찰 등에 관한 법률 시행령」(이하 "영"이라 한다) 제6조제1항에 따른 심사위원회의 결정서는 별지 제3호 서식에 의한다.', 4826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8572, '② 법 제12조제2항에 따른 서면의결은 별지 제3호의2 서식에 의한다.', 4826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8573, '①심사위원회는 회의록을 작성ㆍ비치하여야 한다.', 4827);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8574, '②제1항의 규정에 의한 회의록에는 회의의 내용을 기재하고 위원장 및 서기가 서명 또는 기명날인하여야 한다. <개정 2009.3.19>', 4827);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8575, '① 영 제6조의2에 따른 교육훈련과정의 분야ㆍ교과목 및 교육 강사의 자격은 별표 1과 같다', 4829);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8576, '② 보호관찰소 소속 공무원은 법 제15조의 사무를 담당하는 날부터 2년 이내에 별표 1의 공통분야의 교과목을 모두 이수하여야 한다. 다만, 법 제15조의 사무를 담당하기 전에 임용전 교육 등을 통해 별표 1의 공통분야의 교과목을 이수한 경우에는 해당 교과목을 이수한 것으로 본다.', 4829);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8577, '③ 법무부장관은 별표 1의 전문분야의 분야별 교과목을 정하여야 하며, 법 제15조의 사무를 담당하는 보호관찰소 소속 공무원은 매년 2개 이상의 전문분야의 분야별 교과목을 이수하여야 한다.', 4829);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8578, '④ 별표 1에 따른 교육훈련과정은 법무연수원 등 국가공무원 교육기관의 교육과정 외 보호관찰소 직무교육과정, 「고등교육법」 제2조에 따른 학교의 학위과정, 「학점인정 등에 관한 법률」 제3조에 따라 평가인정을 받은 학습과정에서도 이수할 수 있다.', 4829);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8579, '⑤ 법무부장관은 보호관찰소 소속 공무원의 전문적 지식을 향상시키기 위하여 별표 1에 따른 교육훈련과정에 대하여 필기시험 또는 구술시험을 실시할 수 있다.', 4829);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8580, '⑥ 보호관찰소의 장은 소속 공무원에 대하여 별표 1에 따른 교육훈련과정에 대한 연간 교육계획을 수립하여야 한다.', 4829);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8581, '① 법무부장관은 판결 전 조사 등 조사업무의 원활한 수행 및 전문성 확보를 위하여 조사관을 양성하여야 한다.', 4830);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8582, '② 조사관은 다음 각 호의 요건을 모두 갖추어야 한다.', 4830);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8583, '③ 필기시험 및 조사서 작성능력 평가 등 조사관 양성에 관하여 필요한 세부 사항은 법무부장관이 정한다.', 4830);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8584, '①법 제18조의 규정에 의한 범죄예방자원봉사위원(이하 "범죄예방위원"이라 한다)은 다음 각호의 요건을 갖춘 자중에서 법무부장관이 위촉한다.', 4831);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8585, '②법무부장관은 범죄예방위원이 다음 각호의 1에 해당하는 때에는 해촉할 수 있다.', 4831);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8586, '③ 삭제 <2009.11.27>', 4831);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8587, '④ 삭제 <2009.11.27>', 4831);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8588, null, 4833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8589, '① 보호관찰소의 장은 보호관찰 대상자 지도, 사회봉사명령 집행감독 등 보호관찰활동을 지원할 사람이 필요한 경우 특별범죄예방자원봉사위원(이하 "특별범죄예방위원"이라 한다)을 위촉할 수 있다.', 4835);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8590, '② 특별범죄예방위원의 위촉기간은 2년으로 한다. 다만, 보호관찰 대상자와 특별한 관계에 있는 사람을 특별범죄예방위원으로 위촉하는 경우 그 위촉기간은 대상자의 보호관찰기간으로 할 수 있다. <개정 2017.2.7>', 4835);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8591, '③ 특별범죄예방위원의 위촉 및 해촉에 관하여 제8조제1항 및 제2항을 준용한다.', 4835);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8592, '①교도소ㆍ구치소ㆍ소년교도소 및 소년원(이하 "수용기관"이라 한다)의 장은 관할심사위원회에 기간경과통보서를 송부한 후에 징역 또는 금고의 형의 선고를 받은 소년(이하 "소년수형자"라 한다) 또는 보호소년을 다른 수용기관에 이송한 경우에는 별지 제6호서식의 이송통지서를 작성하여 관할심사위원회에 송부하여야 한다.', 4839);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8593, '②제1항의 이송통지서를 송부받은 심사위원회는 소년수형자 또는 보호소년이 다른 심사위원회의 관할구역에 있는 수용기관에 이송된 때에는 지체없이 기간경과통보서등 관계서류를 당해심사위원회에 송부하여야 한다.', 4839);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8594, '① 법 제22조에 따른 가석방 심사의 신청은 별지 제7호 서식에 의한다.', 4840);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8595, '② 법 제22조의 규정에 따른 퇴원 또는 임시퇴원 심사의 신청은 별지 제7호의2 서식에 의한다.', 4840);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8596, '①보호관찰소의 장은 법원으로부터 법 제20조제1항에 따른 판결이나 「소년법」 제32조제5항에 따른 결정의 통보를 받거나 심사위원회로부터 제17조에 따른 명단 등의 송부를 받은 때 또는 영 제16조 또는 제18조제2항에 따른 보호관찰대상자의 신고를 접수한 때에는 별지 제11호서식의 보호관찰사건부에 정해진 사항을 기재하고, 개인별로 별지 제12호서식의 보호관찰카드를 작성해야 한다. <개정 2009.3.19, 2009.11.27, 2022.2.7>', 4845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8597, '② 제1항에 따라 보호관찰카드를 작성하는 경우 보호관찰 대상자의 동일성 식별을 위하여 사진을 촬영할 수 있다. <신설 2009.11.27>', 4845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8598, '①보호관찰소의 장은 보호관찰대상자별로 담당보호관찰관을 지명하여 보호관찰을 담당하게 한다.', 4847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8599, '②보호관찰관은 보호관찰대상자로부터 별지 제13호서식의 서약서를 제출받고 보호관찰기간중 준수사항을 이행하도록 지시한다.', 4847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8600, '③보호관찰관은 보호관찰대상자의 자립과 건전한 사회복귀를 위하여 적절한 지도와 감독 및 원호를 하여야 한다.', 4847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8601, '④보호관찰관은 그 직무수행에 필요한 경우에는 범죄예방위원 또는 특별범죄예방위원에게 지원을 요청할 수 있다.', 4847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8602, '⑤보호관찰관은 보호관찰대상자에 대한 지도ㆍ감독ㆍ원호ㆍ조치상황ㆍ주요동태 및 준수사항의 이행여부등 보호관찰경과에 관한 중요한 사항을 보호관찰카드에 기재한다.', 4847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8603, '⑥보호관찰관은 제4항의 규정에 의하여 지원을 요청한 범죄예방위원 또는 특별범죄예방위원에 대하여 별지 제14호서식의 보호관찰경과통보서를 작성하여 매월 1회 통보하도록 요구할 수 있다.', 4847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8604, '⑦보호관찰관은 법 제32조제2항제4호의 규정에 의한 주거이전신고를 받은 때에는 지체없이 보호관찰대상자에 대한 보호관찰카드 기타 관계서류를 첨부하여 신주거지를 관할하는 보호관찰소의 장에게 통보하여야 한다.', 4847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8605, '① 보호관찰소의 장은 법 제34조의 원호활동을 종합적이고 체계적으로 전개하기 위하여 원호협의회를 설치할 수 있다.', 4851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8606, '② 원호협의회는 5명 이상의 위원으로 구성하되, 보호관찰소의 장은 당연직 위원으로서 위원장이 되고, 위원은 다음 각 호에 해당하는 사람 중에서 위원장이 위촉한다.', 4851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8607, '③ 위원의 임기는 2년으로 한다.', 4851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8608, '④ 위원장은 위원의 활동이 부진하거나 품위손상 등 사유로 직무수행이 곤란하다고 인정되는 경우에는 그 위원을 해촉할 수 있다.', 4851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8609, '⑤ 위원장은 보호관찰 대상자와 그의 가족에 대한 생계, 의료ㆍ교육ㆍ법률 문제 해결, 직업훈련, 취업알선, 기초생활수급자 지정 등 종합적인 지원이 필요한 경우 협의회를 소집하여 원호의 내용, 분야, 규모 등을 협의할 수 있다.', 4851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8610, '⑥ 위원장은 보호관찰 대상자와 그의 가족에 대한 특정 분야의 원호활동을 각 위원에게 개별적으로 의뢰할 수 있다.', 4851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8611, '① 법 제36조의2제2항 및 영 제20조의2제1항에 따른 보호관찰 종료사실 통보를 위한 심사 신청서는 별지 제16호의2서식과 같다.', 4852);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8612, '② 심사위원회가 법 제36조의2제2항 및 제3항에 따라 하는 보호관찰 종료사실 통보를 위한 심사 결정은 별지 제3호서식에 따른다.', 4852);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8613, '③ 보호관찰소의 장이 법 제36조의2제2항 및 영 제20조의2제2항에 따라 경찰관서의 장 및 지방자치단체의 장에게 하는 보호관찰 종료사실 통보는 별지 제16호의3서식에 따른다.', 4852);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8614, '①영 제23조 및 제39조제2항에 따른 구인신청은 별지 제20호서식에 의한다. <개정 2009.11.27>', 4856);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8615, '②보호관찰소의 장은 영 제23조에 따라 구인신청을 하는 때에는 별지 제21호서식의 구인장신청부에 정해진 사항을 기재해야 한다. <개정 2022.2.7>', 4856);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8616, '① 영 제36조의2제1항(영 제47조에서 준용하는 경우를 포함한다)에 따른 기부금품의 접수 영수증은 「법인세법 시행규칙」 제82조제7항제3호의3의 별지 제63호의3서식에 따른다. <개정 2015.6.22>', 4876);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8617, '② 영 제36조의2제5항(영 제47조에서 준용하는 경우를 포함한다)에 따른 기부금품의 접수현황 및 사용실적 등에 관한 장부는 별지 제34호서식에 따른다. <개정 2015.6.22>', 4876);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8618, '①영 제41조제1항의 규정에 의하여 갱생보호대상자에 대하여 숙식을 제공하는 시설(이하 "생활관"이라 한다)에는 제49조의 규정에 의한 사무실 및 상담실외에 갱생보호대상자의 숙박에 제공되는 거실ㆍ집회실ㆍ조리장ㆍ식당ㆍ세면장 및 화장실을 설치하여야 한다. 다만, 10인이내의 갱생보호대상자에게 숙식을 제공하는 생활관에서 거실을 식당으로 겸용하는 경우에는 따로 식당을 설치하지 아니할 수 있다.', 4880);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8619, '②남녀를 함께 수용하는 생활관의 거실은 남자용과 여자용을 분리하여 설치하여야 한다.', 4880);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8620, '③거실ㆍ조리장 및 식당은 보건위생에 적합하여야 하며, 난방ㆍ채광 및 환기가 잘 되도록 설치하여야 한다.', 4880);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8621, '①갱생보호대상자로서 갱생보호를 받고자 하는 자는 보호관찰소의 장, 법 제67조에 따라 갱생보호사업의 허가를 받은 자(이하 "사업자"라 한다) 또는 법 제71조에 따른 한국법무보호복지공단(이하 "공단"이라 한다)에 서면으로 신청하여야 한다. <개정 2014.11.19>', 4881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8622, '②관계기관이 보호관찰소의 장, 사업자 또는 공단에 갱생보호대상자에 대한 갱생보호의 신청을 하는 경우에는 갱생보호대상자의 전과 및 처분의 내용, 신상관계, 갱생보호대상자가 희망하는 갱생보호방법등을 기재한 서면으로 하여야 한다.', 4881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8623, '③제1항 및 제2항에 따라 갱생보호의 신청을 받은 보호관찰소의 장, 사업자 또는 공단이 법 제66조제2항에 따라 갱생보호의 필요 여부와 그 방법을 결정함에 있어서는 신청서 및 갱생보호대상자와의 상담 등에 의하여 갱생보호대상자의 전과의 죄질ㆍ연령ㆍ학력ㆍ가정사정ㆍ교우관계 및 자립계획 등을 조사하여야 한다. <개정 2014.11.19>', 4881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8624, '④보호관찰소의 장, 사업자 또는 공단은 갱생보호를 행하지 아니하기로 결정한 때에는 서면으로 그 이유를 신청인에게 통지하여야 한다.', 4881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8625, '①사업자 또는 공단은 생활관에 수용보호한 갱생보호대상자에 대하여 지체없이 갱생자립계획을 수립하게 하여야 한다.', 4883);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8626, '②사업자 또는 공단은 갱생보호대상자에 대하여 교양을 높이고 자율ㆍ자조 및 협동정신과 준법정신을 생활화하여야 하고, 근로의 정신과 습성을 체득하도록 생활지도를 하여야 한다.', 4883);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8627, '①사업자 또는 공단은 갱생보호대상자가 소유하는 금품을 낭비하지 아니하고 갱생자립에 적절하게 사용하도록 지도하여야 한다.', 4885);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8628, '②사업자 또는 공단은 갱생보호대상자로부터 금품의 보관을 의뢰받은 경우에는 금품의 종류 및 수량을 명백히 하여 장부에 기재하고 본인에게 보관증을 교부하여야 한다. 이 경우 현금에 대하여는 갱생보호대상자의 명의로 은행에 예금한 후 예금통장은 본인에게 교부하고 인감은 담당직원이 이를 보관하여야 한다.', 4885);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8629, '③보관된 금품은 갱생보호대상자가 사용용도를 명확히 하여 신청하는 경우에는 본인에게 환급한다.', 4885);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8630, '①생활관에서는 구급약품을 비치하고 시설을 위생적으로 관리하는 등 갱생보호대상자의 건강관리에 유의하여야 한다.', 4886);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8631, '②갱생보호대상자에 대하여는 보건소등 의료시설에서 건강진단을 받도록 하여야 한다.', 4886);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8632, '①갱생보호대상자에게는 독서ㆍ훈화ㆍ교양집회의 개최 기타의 방법으로 그 교양을 높이도록 하여야 한다.', 4889);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8633, '②갱생보호대상자에게는 운동과 여가활동으로 심신의 건강을 유지할 수 있도록 하여야 한다.', 4889);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8634, '①영 제44조제1항의 규정에 의한 직업훈련은 갱생보호대상자의 희망ㆍ적성ㆍ경력등을 고려하여 직업훈련후 취업이 쉬운 분야를 선정하여 훈련을 실시하여야 한다.', 4895);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8635, '②직업훈련을 받은 갱생보호대상자에 대하여는 기술자격을 취득할 수 있도록 최대한 지원하고 취업을 알선하는데 노력하여야 한다.', 4895);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8636, '①갱생보호대상자에 대하여는 기업을 경영하는 범죄예방위원 기타 독지가등과 긴밀하게 연락하여 그 취업을 알선하는데 노력하여야 한다.', 4896);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8637, '②사업자 또는 공단은 그 경영하는 부설작업장에 특별한 사유가 없는 한 갱생보호대상자를 취업시켜야 한다.', 4896);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8638, null, 4898);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8639, '①사업자의 회계연도는 정부의 회계연도에 의한다.', 4901);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8640, '②사업자는 법 제69조의 규정에 의하여 매 회계연도 개시 1월전에 다음 연도의 사업계획 및 예산을, 매 회계연도 종료후 2월이내에 전년도의 사업실적 및 결산서를 법무부장관에게 보고하여야 한다.', 4901);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8641, '③제2항의 규정에 의하여 제출하는 사업계획 및 예산에는 다음 서류를 첨부하여야 한다.', 4901);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8642, '④제2항의 규정에 의하여 제출하는 사업실적 및 결산에는 다음 서류를 첨부하여야 한다.', 4901);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8643, '①공단은 법 제84조제2항의 규정에 의하여 매 회계연도 개시 1월전에 다음 연도의 사업계획 및 예산을 법무부 장관에게 제출하여 승인을 얻어야 하며, 매 회계연도 종료후 2월이내에 전년도의 사업실적 및 결산서를 법무부장관에게 제출하여야 한다.', 4902);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8644, '②공단은 제1항의 규정에 의하여 사업계획 및 예산의 승인을 얻은 후 사업계획을 변경하거나 예산의 관ㆍ항간의 유용 또는 예산외 지출을 하고자 할 때에는 법무부장관의 승인을 얻어야 한다.', 4902);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8645, '③제1항의 사업계획ㆍ예산ㆍ사업실적 및 결산은 지부별로 내용이 명시되어야 한다.', 4902);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8646, null, 4903);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8647, null, 4905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8648, '①법무부장관은 법 제97조제2항의 규정에 의하여 사업자 또는 공단에 대한 갱생보호사업의 운영실태를 조사한 결과 허가기준에 위반되거나 기타 위법ㆍ부당한 사항이 있는 경우에는 개선을 명할 수 있다.', 4906);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8649, '②제1항의 개선명령을 받은 자는 지체없이 개선조치를 한 후 그 조치내용을 법무부장관에게 서면으로 보고하여야 한다.', 4906);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8650, '①사업자 및 공단은 갱생보호사업의 성과와 재정상태를 정확히 파악하기 위하여 모든 회계거래를 그 발생의 사실에 따라 처리하여야 한다.', 4907);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8651, '②사업자 및 공단이 수익사업을 경영하는 경우에는 갱생보호사업의 회계와 수익사업의 회계를 구분하여 처리하여야 한다. <개정 2014.11.19>', 4907);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8652, null, 4908);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8653, '① 「전자장치 부착 등에 관한 법률」(이하 "법"이라 한다) 제6조제1항, 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제2호 및 제3항제2호에 따른 조사요청은 별지 제1호서식의 부착명령 청구 전 조사 요청서에 따른다. <개정 2009.7.30, 2010.7.15, 2013.5.31, 2020.8.5>', 4911);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8654, '② 「전자장치 부착 등에 관한 법률 시행령」(이하 "영"이라 한다) 제4조제1항 후단에 따른 참고자료란 피의자 신문조서, 피해자 진술조서, 범죄경력자료 및 수사경력자료 등을 말한다. <개정 2010.7.15, 2013.5.31, 2020.8.5>', 4911);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8655, '① 법 제8조의 부착명령청구서는 별지 제2호서식과 같다. 다만, 공소제기와 동시에 부착명령을 청구하는 경우에는 영 제5조제2항에 따라 별지 제3호서식의 공소장 및 부착명령청구서로 할 수 있다.', 4912);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8656, '② 공소를 제기한 후에 부착명령을 청구하는 경우에는 부착명령 청구사건과 병합심리할 피고사건의 법원명, 사건번호, 피고인명, 죄명 등을 명시하여 부착명령 청구사건의 관할법원에 병합심리를 신청하여야 한다.', 4912);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8657, '① 법 제12조(법 제31조에 따라 준용되는 경우를 포함한다) 및 영 제28조제1항의 집행지휘는 별지 제5호서식의 부착명령 집행지휘서에 따른다. <개정 2010.7.15>', 4914);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8658, '② 검사는 부착명령과 병과된 형의 집행지휘서의 비고란에 "부착명령"이라고 붉은 색으로 적어야 한다.', 4914);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8659, '① 영 제12조제1항(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 신고는 별지 제9호서식의 신고서에 따른다. <개정 2013.5.31>', 4918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8660, '② 영 제12조제2항 및 제3항(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 허가 신청 및 허가는 각각 별지 제10호서식의 주거이전, 국내여행 또는 출국 허가신청서와 별지 제11호서식의 주거이전, 국내여행 또는 출국 허가서에 따른다. <개정 2013.5.31>', 4918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8661, '③ 영 제12조제7항(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 통보요청은 별지 제12호서식의 출입국사실 통보 요청서에 따른다. <개정 2013.5.31>', 4918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8662, '① 법 제14조의2, 제14조의3 및 영 제12조의2에 따른 부착기간의 연장 또는 준수사항의 부과ㆍ추가ㆍ변경ㆍ삭제의 신청은 별지 제13호서식에 따른다.', 4919);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8663, '② 법 제14조의2 또는 제14조의3에 따른 부착기간의 연장 또는 준수사항의 부과ㆍ추가ㆍ변경ㆍ삭제의 청구는 별지 제14호서식에 따른다.', 4919);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8664, '① 영 제13조제1항에 따라 치료 및 상담치료 등을 실시할 수 있는 시설 또는 단체로 지정을 받으려는 자(이하 "신청인"이라 한다)는 별지 제15호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정 신청서에 다음 각 호의 서류를 첨부하여 주소지를 관할하는 보호관찰소(지소를 포함한다. 이하 같다)의 장에게 제출해야 한다. <개정 2013.5.31, 2022.2.7, 2022.12.19>', 4920);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8665, '② 제1항에 따른 신청서를 받은 담당 공무원은 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 다음 각 호의 서류의 내용을 확인하여야 한다.', 4920);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8666, '③ 제1항에 따른 신청을 받은 경우 보호관찰소의 장은 신청일부터 14일 이내에 별지 제16호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정신청에 대한 의견서와 함께 신청인이 제출한 특정 범죄자 치료기관 또는 상담치료기관 지정 신청서와 첨부서류를 법무부장관에게 보내야 한다. <개정 2013.5.31>', 4920);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8667, '④ 법무부장관은 영 제13조제1항에 따라 신청인을 치료 및 상담치료 등을 실시할 수 있는 시설 또는 단체로 지정할 때에는 신청인에게 별지 제17호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정서를 발급하여야 한다. <개정 2013.5.31>', 4920);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8668, '⑤ 영 제13조제1항에 따른 지정을 받은 시설 또는 단체는 다음 각 호의 어느 하나에 해당하는 사항을 변경하려면 별지 제18호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정사항 변경신청서에 변경된 사항을 증명하는 서류 등을 첨부하여 주소지를 관할하는 보호관찰소의 장에게 제출하여야 한다. <개정 2013.5.31>', 4920);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8669, '⑥ 제5항에 따른 변경신청을 받은 경우 보호관찰소의 장은 변경신청일부터 14일 이내에 별지 제19호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정사항 변경신청에 대한 의견서와 변경신청을 한 시설 또는 단체가 제출한 특정 범죄자 치료기관 또는 상담치료기관 지정사항 변경신청서 및 첨부서류를 법무부장관에게 보내야 한다. <개정 2013.5.31>', 4920);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8670, '⑦ 법무부장관은 제5항에 따른 지정사항 변경신청이 적정하다고 판단되는 경우 변경내용이 기재된 제17호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정서를 신청인에게 다시 발급하여야 한다. <개정 2013.5.31>', 4920);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8671, '⑧ 보호관찰소의 장은 법무부장관에게 영 제13조제1항에 따른 지정을 받은 시설 또는 단체의 시설이나 특정 범죄자 치료 및 교정 프로그램이 특정 범죄자의 치료ㆍ개선에 적당한지 여부와 그 운영실태를 정기적으로 보고하여야 한다.', 4920);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8672, '⑨ 법무부장관은 제8항에 따른 보고 결과 영 제13조제1항에 따른 지정을 받은 시설 또는 단체의 시설이나 특정 범죄자 치료 및 교정 프로그램이 특정 범죄자의 치료ㆍ개선에 부적당하다고 인정하면 지정을 취소할 수 있다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 지정을 취소하여야 한다. <개정 2013.5.31>', 4920);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8673, '① 보호관찰관은 법 제15조제3항에 따라 피부착자의 형 또는 치료감호 집행 중의 생활실태를 확인할 수 있는 자료를 요청하거나 피부착자를 면접하려는 경우에는 보호관찰소의 장을 통하여 교도소, 소년교도소, 구치소, 국립법무병원 및 군교도소의 장(이하 "교도소장등"이라 한다)에게 다음 사항을 적은 서면(전자문서를 포함한다)을 제출하여야 한다. <개정 2022.7.4>', 4921);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8674, '② 교도소장등은 제1항의 요청에 대하여 보호관찰소의 장에게 서면(전자문서를 포함한다)으로 회신하여야 한다. 다만, 생활실태 확인을 위한 자료는 「형사사법절차 전자화 촉진법」에 따른 형사사법정보시스템을 통하여 보호관찰소의 장에게 제공하는 방법으로 회신할 수 있다.', 4921);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8675, '③ 제1항에 따른 보호관찰관의 자료 또는 면접 요청은 별지 제20호서식에 따른다.', 4921);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8676, '④ 제2항 본문에 따른 교도소장등의 회신은 별지 제21호서식에 따른다.', 4921);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8677, '① 검사가 영 제14조의2제1항에 따라 수신자료의 열람ㆍ조회 허가청구를 하는 경우에는 별지 제23호서식에 따른다.', 4923);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8678, '② 사법경찰관이 영 제14조의2제2항에 따른 수신자료 열람ㆍ조회 허가신청을 하는 경우에는 별지 제24호서식에 따른다.', 4923);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8679, '③ 검사가 영 제14조의2제2항에 따라 사법경찰관으로부터 수신자료의 열람ㆍ조회 허가신청을 받아 수신자료 열람ㆍ조회 허가청구를 하는 경우에는 별지 제25호서식에 따른다.', 4923);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8680, '① 검사 또는 사법경찰관이 영 제14조의3제1항에 따라 보호관찰소의 장에게 긴급 수신자료 열람ㆍ조회를 요청하는 경우에는 별지 제26호서식에 따른다.', 4924);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8681, '② 영 제14조의3제2항에 따른 긴급 수신자료 열람 또는 조회의 허가청구는 별지 제27호서식에 따른다.', 4924);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8682, '③ 영 제14조의3제3항에 따른 긴급 수신자료 열람 또는 조회의 허가신청 및 허가청구는 각각 별지 제28호서식 및 별지 제29호서식에 따른다.', 4924);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8683, '① 검사 또는 사법경찰관은 법 제16조제4항 본문에 따라 수신자료를 열람 또는 조회한 때에는 별지 제30호서식의 수신자료 열람ㆍ조회 대장에 해당 사항을 적어야 하고, 법 제16조제4항 단서에 따라 수신자료를 열람 또는 조회한 때에는 별지 제31호서식의 긴급 수신자료 열람ㆍ조회 대장에 해당 사항을 적어야 한다.', 4925);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8684, '② 보호관찰소의 장은 법 제16조제4항에 따라 수신자료를 열람 또는 조회하게 한 때에는 별지 제32호서식의 수신자료 열람ㆍ조회 접수 대장에 해당 사항을 적어야 한다.', 4925);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8685, '③ 영 제14조의4제4항에 따른 검사 또는 사법경찰관의 수신자료 폐기사실의 통지는 별지 제33호서식에 따른다.', 4925);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8686, '① 법 제16조의3제2항에 따라 피부착자에 관한 영상정보를 제공받은 위치추적 관제센터의 장은 같은 조 제3항에 따라 해당 영상정보의 열람이 종료된 날부터 30일 이내에 열람 사실을 해당 피부착자에게 통지해야 한다.', 4928);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8687, '② 제1항에 따른 통지는 휴대전화 문자전송, 전자우편, 팩스, 전화 또는 우편 등의 방법으로 한다.', 4928);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8688, '① 법 제21조의2에 따른 보호관찰명령의 청구는 별지 제38호서식에 따른다. 다만, 공소제기와 동시에 보호관찰명령을 청구하는 경우에는 별지 제39호서식의 공소장 및 보호관찰명령 청구서로 할 수 있다.', 4932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8689, '② 검사가 공소를 제기한 후에 보호관찰명령을 청구하는 경우에는 보호관찰명령 청구사건과 병합심리할 피고사건의 법원명, 사건번호, 피고인명 및 죄명 등을 명시하여 보호관찰명령 청구사건의 관할 법원에 병합심리를 신청하여야 한다.', 4932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8690, '① 법 제21조의3에 따라 선고된 보호관찰명령의 집행지휘는 별지 제40호서식의 보호관찰명령 집행지휘서에 따른다.', 4933);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8691, '② 검사는 보호관찰명령과 병과된 형의 집행지휘서의 비고란에 "보호관찰명령"이라고 붉은 색으로 적어야 한다.', 4933);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8692, '① 법 제22조제4항 및 제23조제2항에 따른 전자장치 부착대상자 통보는 별지 제43호서식의 전자장치 부착대상자 통보서에 따른다. <개정 2013.5.31, 2020.8.5>', 4936);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8693, '② 영 제19조의2제2항의 결정서는 별지 제44호서식에 따른다. <개정 2013.5.31, 2020.8.5>', 4936);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8694, '① 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제6호에 따른 구인영장의 청구와 신청은 각각 별지 제47호서식과 별지 제48호서식에 따른다. <개정 2013.5.31>', 4948);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8695, '② 보호관찰소의 장은 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제6호에 따라 검사에게 구인영장을 신청할 때에는 별지 제49호서식의 구인영장 신청부에 정해진 사항을 적어야 한다. <개정 2013.5.31, 2022.2.7>', 4948);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8696, '① 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제6호에 따른 구인영장은 별지 제50호서식에 따른다. <개정 2013.5.31>', 4949);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8697, '② 검사는 구인영장 위쪽에 집행을 지휘한다는 내용을 기재하고 서명 또는 기명날인의 방법으로 구인영장의 집행을 지휘할 수 있다.', 4949);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8698, '① 법 제13조제2항 및 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제10호에 따른 부착명령 집행장의 신청은 별지 제51호서식에 따른다. <개정 2013.5.31, 2018.2.2>', 4950);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8699, '② 법 제13조제2항 및 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제10호에 따른 부착명령 집행장은 별지 제52호서식에 따른다. <개정 2013.5.31, 2018.2.2>', 4950);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8700, null, 4952);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8701, '① 법 제5조제1항 및 제22조제2항제3호에 따른 조사 요청은 별지 제2호서식에 따른다.', 4953);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8702, '② 「성폭력범죄자의 성충동 약물치료에 관한 법률 시행령」(이하 "영"이라 한다) 제3조제1항 후단에서 "법무부령으로 정하는 참고자료"란 다음 각 호의 자료를 말한다.', 4953);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8703, '① 법 제7조제1항 및 제22조제2항제5호 후단에 따른 치료명령 청구서는 별지 제3호서식에 따른다. 다만, 공소제기와 동시에 치료명령을 청구하는 경우에는 별지 제4호서식에 따른 청구서로 할 수 있다.', 4954);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8704, '② 공소를 제기한 후에 치료명령을 청구하는 경우에는 다음 각 호의 사항을 구체적으로 밝혀 치료명령 청구사건의 관할법원에 병합심리(倂合審理)를 신청하여야 한다.', 4954);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8705, '① 지방검찰청 검사장 또는 지청장은 법 제4조 및 제22조에 따라 치료명령을 청구하였을 때에는 지체 없이 법무부장관과 상급 검찰청의 장에게 그 사실을 보고하여야 한다.', 4955);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8706, '② 제1항에 따른 치료명령 청구사건의 재판이 확정되었을 때에는 그 법원에 대응하는 검찰청의 장은 지체 없이 법무부장관과 상급 검찰청의 장에게 그 사실을 보고하여야 한다.', 4955);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8707, '① 법 제13조 및 영 제6조에 따른 집행지휘는 별지 제6호서식에 따른다.', 4958);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8708, '② 검사는 치료명령과 병과(倂科)된 형(刑)에 대한 집행지휘서의 비고란에 "치료명령"이라고 붉은색으로 적어야 한다.', 4958);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8709, '① 보호관찰소의 장은 치료명령을 받은 사람별로 보호관찰을 담당하는 보호관찰관을 지명하여야 한다.', 4961);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8710, '② 제1항에 따른 담당 보호관찰관은 치료명령을 받은 사람으로부터 별지 제9호서식의 서약서를 받아 치료기간 동안 준수사항을 이행할 것을 지시하여야 한다.', 4961);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8711, '① 법 제15조제2항에 따른 치료명령을 받은 사람의 신고 및 영 제14조제2항에 따른 주거 이전 신고는 별지 제19호서식에 따른다.', 4971);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8712, '② 법 제15조제3항 및 영 제14조제1항에 따른 주거 이전 등의 허가 신청 및 허가는 각각 별지 제20호서식과 별지 제21호서식에 따른다.', 4971);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8713, '③ 영 제14조제3항에 따른 출입국 사실 통보 요청은 별지 제22호서식에 따른다.', 4971);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8714, '① 법 제16조 및 영 제15조에 따른 치료기간의 연장 또는 준수사항의 추가ㆍ변경 등의 신청 및 청구는 각각 별지 제23호서식과 별지 제24호서식에 따른다.', 4972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8715, '② 법원이 법 제16조에 따라 치료기간의 연장 또는 준수사항의 추가ㆍ변경 등을 결정한 경우에 검사의 집행지휘는 별지 제25호서식에 따른다. 다만, 법원이 검사의 청구를 기각한 경우에는 검사는 그 결정문 사본을 보호관찰소의 장에게 송부하여야 한다.', 4972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8716, '① 영 제26조제5항에 따른 치료명령을 받은 사람의 자료 제출 동의는 별지 제32호서식에 따른다.', 4980);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8717, '② 영 제26조제5항에 따른 공공기관 등에 대한 자료 제출 요구는 별지 제33호서식에 따른다. 다만, 다른 법령에서 금융거래정보ㆍ신용정보 등의 자료 제출 요구에 관한 서식을 정하고 있는 경우에는 그에 따를 수 있다.', 4980);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8718, '① 법 제25조제1항 및 영 제28조제1항에 따른 치료명령 결정은 별지 제35호서식에 따른다.', 4982);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8719, '② 법 제25조제3항에 따른 치료명령 결정 통보는 별지 제36호서식에 따른다.', 4982);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8720, '① 주식은 1일 3회 급여하고, 1명당 한 끼 급여량은 124그램(여성은 92그램) 이상으로 한다. <개정 2016.10.31, 2019.3.27>', 4986);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8721, '② 소년원장 또는 소년분류심사원장(이하 "원장"이라 한다)은 다음 각 호의 어느 하나에 해당하는 경우에는 대용식(代用食)을 급여할 수 있다. <개정 2016.10.31>', 4986);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8722, '① 부식은 보호소년등의 신체발육과 건강유지를 위하여 영양이 풍부한 식품을 선별하여 급여하되, 보호소년등의 기호에 맞도록 수시로 그 종류를 변경하여야 한다.', 4987);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8723, '② 원장은 제3조제2항에 따라 대용식을 급여할 때에는 제2조에 따른 기준열량에 모자람이 없도록 부족한 영양을 부식으로 보충하여야 한다. <개정 2016.10.31>', 4987);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8724, '① 원장은 환자, 허약자(虛弱者), 그 밖에 요양이 필요하다고 인정되는 보호소년등에게는 의무관의 의견을 들어 쌀밥, 죽, 그 밖의 적당한 대용식과 특별히 마련된 부식을 급여할 수 있다.', 4988);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8725, '② 원장은 체험학습이나 수험준비 중인 보호소년등에 대하여는 예산의 범위에서 특별간식을 급여할 수 있다. <개정 2019.3.27>', 4988);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8726, '① 보호소년등에게 급여 또는 대여할 피복, 침구 및 신발 등(이하 "피복등"이라 한다)의 종류는 다음 각 호와 같이 구분하며, 그 급여 또는 대여의 기준은 별표 1과 같다. 다만, 원장은 날씨, 보호소년등의 건강상태 및 피복등의 재고량 등 그 밖의 사정을 고려하여 급여 또는 대여의 기준량을 조정할 수 있다. <개정 2016.10.31, 2019.3.27>', 4990);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8727, '② 원장은 보호소년등에게 피복등을 급여하거나 대여하는 경우에는 별표 1에 따른 내용연수(耐用年數) 기준을 준수해야 한다. 다만, 피복등이 더 이상 사용할 수 없는 상태에 있거나 내용연수가 지나도록 피복등을 급여 또는 대여하지 않고 보관 중이었던 경우 등 특별한 사유가 있으면 내용연수 기준을 따르지 않을 수 있다. <신설 2016.10.31, 2022.2.7>', 4990);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8728, '③ 삭제 <2019.3.27>', 4990);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8729, '④ 제1항에 따른 피복등의 제작 양식은 예산의 범위에서 원장이 자율적으로 선정하여 급여하거나 대여한다. <개정 2016.10.31, 2019.3.27, 2022.2.7>', 4990);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8730, '① 피복등은 다음 각 호의 구분에 따라 겨울옷 또는 여름옷을 착용하거나 사용한다. 다만, 계절의 구별이 없는 피복등은 그러하지 아니하다.', 4991);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8731, '② 원장은 기후조건 등에 따라 제1항에 따른 피복등의 착용 또는 사용기간을 조정할 수 있다. <개정 2019.3.27>', 4991);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8732, '① 보호소년등에게는 학과교육ㆍ직업훈련 등 교정교육에 필요한 교과서 및 학용품을 급여하거나 대여한다.', 4992);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8733, '② 제1항에 따른 교과서 및 학용품의 급여 또는 대여 기준은 별표 3과 같다.', 4992);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8734, '① 보호소년등에게 일상생활에 필요한 생활용품을 급여하거나 대여하되, 그 기준은 별표 4와 같다.', 4993);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8735, '② 원장은 보호소년등의 처우와 관련하여 필요하다고 인정하는 경우 법무부장관의 허가를 받아 이 규칙에서 정하지 아니한 일상용품을 보호소년등에게 급여하거나 대여할 수 있다.', 4993);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8736, null, 4996);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8737, '① 사업주 또는 경영책임자등은 사업주나 법인 또는 기관이 실질적으로 지배ㆍ운영ㆍ관리하는 사업 또는 사업장에서 종사자의 안전ㆍ보건상 유해 또는 위험을 방지하기 위하여 그 사업 또는 사업장의 특성 및 규모 등을 고려하여 다음 각 호에 따른 조치를 하여야 한다.', 4998);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8738, '② 제1항제1호ㆍ제4호의 조치에 관한 구체적인 사항은 대통령령으로 정한다.', 4998);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8739, '① 제4조 또는 제5조를 위반하여 제2조제2호가목의 중대산업재해에 이르게 한 사업주 또는 경영책임자등은 1년 이상의 징역 또는 10억원 이하의 벌금에 처한다. 이 경우 징역과 벌금을 병과할 수 있다.', 5000);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8740, '② 제4조 또는 제5조를 위반하여 제2조제2호나목 또는 다목의 중대산업재해에 이르게 한 사업주 또는 경영책임자등은 7년 이하의 징역 또는 1억원 이하의 벌금에 처한다.', 5000);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8741, '③ 제1항 또는 제2항의 죄로 형을 선고받고 그 형이 확정된 후 5년 이내에 다시 제1항 또는 제2항의 죄를 저지른 자는 각 항에서 정한 형의 2분의 1까지 가중한다.', 5000);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8742, null, 5001);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8743, '① 중대산업재해가 발생한 법인 또는 기관의 경영책임자등은 대통령령으로 정하는 바에 따라 안전보건교육을 이수하여야 한다.', 5002);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8744, '② 제1항의 안전보건교육을 정당한 사유 없이 이행하지 아니한 경우에는 5천만원 이하의 과태료를 부과한다.', 5002);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8745, '③ 제2항에 따른 과태료는 대통령령으로 정하는 바에 따라 고용노동부장관이 부과ㆍ징수한다.', 5002);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8746, '① 사업주 또는 경영책임자등은 사업주나 법인 또는 기관이 실질적으로 지배ㆍ운영ㆍ관리하는 사업 또는 사업장에서 생산ㆍ제조ㆍ판매ㆍ유통 중인 원료나 제조물의 설계, 제조, 관리상의 결함으로 인한 그 이용자 또는 그 밖의 사람의 생명, 신체의 안전을 위하여 다음 각 호에 따른 조치를 하여야 한다.', 5003);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8747, '② 사업주 또는 경영책임자등은 사업주나 법인 또는 기관이 실질적으로 지배ㆍ운영ㆍ관리하는 공중이용시설 또는 공중교통수단의 설계, 설치, 관리상의 결함으로 인한 그 이용자 또는 그 밖의 사람의 생명, 신체의 안전을 위하여 다음 각 호에 따른 조치를 하여야 한다.', 5003);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8748, '③ 사업주 또는 경영책임자등은 사업주나 법인 또는 기관이 공중이용시설 또는 공중교통수단과 관련하여 제3자에게 도급, 용역, 위탁 등을 행한 경우에는 그 이용자 또는 그 밖의 사람의 생명, 신체의 안전을 위하여 제2항의 조치를 하여야 한다. 다만, 사업주나 법인 또는 기관이 그 시설, 장비, 장소 등에 대하여 실질적으로 지배ㆍ운영ㆍ관리하는 책임이 있는 경우에 한정한다.', 5003);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8749, '④ 제1항제1호ㆍ제4호 및 제2항제1호ㆍ제4호의 조치에 관한 구체적인 사항은 대통령령으로 정한다.', 5003);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8750, '① 제9조를 위반하여 제2조제3호가목의 중대시민재해에 이르게 한 사업주 또는 경영책임자등은 1년 이상의 징역 또는 10억원 이하의 벌금에 처한다. 이 경우 징역과 벌금을 병과할 수 있다.', 5004);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8751, '② 제9조를 위반하여 제2조제3호나목 또는 다목의 중대시민재해에 이르게 한 사업주 또는 경영책임자등은 7년 이하의 징역 또는 1억원 이하의 벌금에 처한다.', 5004);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8752, null, 5005);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8753, '① 고용노동부장관은 제4조에 따른 의무를 위반하여 발생한 중대산업재해에 대하여 사업장의 명칭, 발생 일시와 장소, 재해의 내용 및 원인 등 그 발생사실을 공표할 수 있다.', 5007);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8754, '② 제1항에 따른 공표의 방법, 기준 및 절차 등은 대통령령으로 정한다.', 5007);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8755, '① 이 법 위반 여부에 관한 형사재판에서 법원은 직권으로 「형사소송법」 제294조의2에 따라 피해자 또는 그 법정대리인(피해자가 사망하거나 진술할 수 없는 경우에는 그 배우자ㆍ직계친족ㆍ형제자매를 포함한다)을 증인으로 신문할 수 있다.', 5008);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8756, '② 이 법 위반 여부에 관한 형사재판에서 법원은 검사, 피고인 또는 변호인의 신청이 있는 경우 특별한 사정이 없으면 해당 분야의 전문가를 전문심리위원으로 지정하여 소송절차에 참여하게 하여야 한다.', 5008);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8757, '① 사업주 또는 경영책임자등이 고의 또는 중대한 과실로 이 법에서 정한 의무를 위반하여 중대재해를 발생하게 한 경우 해당 사업주, 법인 또는 기관이 중대재해로 손해를 입은 사람에 대하여 그 손해액의 5배를 넘지 아니하는 범위에서 배상책임을 진다. 다만, 법인 또는 기관이 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다.', 5009);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8758, '② 법원은 제1항의 배상액을 정할 때에는 다음 각 호의 사항을 고려하여야 한다.', 5009);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8759, '① 정부는 중대재해를 예방하여 시민과 종사자의 안전과 건강을 확보하기 위하여 다음 각 호의 사항을 이행하여야 한다.', 5010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8760, '② 정부는 사업주, 법인 및 기관에 대하여 유해ㆍ위험 시설의 개선과 보호 장비의 구매, 종사자 건강진단 및 관리 등 중대재해 예방사업에 소요되는 비용의 전부 또는 일부를 예산의 범위에서 지원할 수 있다.', 5010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8761, '③ 정부는 제1항 및 제2항에 따른 중대재해 예방을 위한 조치 이행 등 상황 및 중대재해 예방사업 지원 현황을 반기별로 국회 소관 상임위원회에 보고하여야 한다.', 5010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8762, null, 5013);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8763, null, 5014);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8764, '① 법 제4조제1항제4호에서 "안전ㆍ보건 관계 법령"이란 해당 사업 또는 사업장에 적용되는 것으로서 종사자의 안전ㆍ보건을 확보하는 데 관련되는 법령을 말한다.', 5015);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8765, '② 법 제4조제1항제4호에 따른 조치에 관한 구체적인 사항은 다음 각 호와 같다.', 5015);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8766, '① 법 제8조제1항에 따른 안전보건교육(이하 "안전보건교육"이라 한다)은 총 20시간의 범위에서 고용노동부장관이 정하는 바에 따라 이수해야 한다.', 5016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8767, '② 안전보건교육에는 다음 각 호의 사항이 포함되어야 한다.', 5016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8768, '③ 고용노동부장관은 「한국산업안전보건공단법」에 따른 한국산업안전보건공단이나 「산업안전보건법」 제33조에 따라 등록된 안전보건교육기관(이하 "안전보건교육기관등"이라 한다)에 안전보건교육을 의뢰하여 실시할 수 있다.', 5016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8769, '④ 고용노동부장관은 분기별로 중대산업재해가 발생한 법인 또는 기관을 대상으로 안전보건교육을 이수해야 할 교육대상자를 확정하고 안전보건교육 실시일 30일 전까지 다음 각 호의 사항을 해당 교육대상자에게 통보해야 한다.', 5016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8770, '⑤ 제4항에 따른 통보를 받은 교육대상자는 해당 교육일정에 참여할 수 없는 정당한 사유가 있는 경우에는 안전보건교육 실시일 7일 전까지 고용노동부장관에게 안전보건교육의 연기를 한 번만 요청할 수 있다.', 5016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8771, '⑥ 고용노동부장관은 제5항에 따른 연기 요청을 받은 날부터 3일 이내에 연기 가능 여부를 교육대상자에게 통보해야 한다.', 5016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8772, '⑦ 안전보건교육을 연기하는 경우 교육일정 등의 통보에 관하여는 제4항을 준용한다.', 5016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8773, '⑧ 안전보건교육에 드는 비용은 안전보건교육기관등에서 수강하는 교육대상자가 부담한다.', 5016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8774, '⑨ 안전보건교육기관등은 안전보건교육을 실시한 경우에는 지체 없이 안전보건교육 이수자 명단을 고용노동부장관에게 통보해야 한다.', 5016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8775, '⑩ 안전보건교육을 이수한 교육대상자는 필요한 경우 안전보건교육이수확인서를 발급해 줄 것을 고용노동부장관에게 요청할 수 있다.', 5016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8776, '⑪ 제10항에 따른 요청을 받은 고용노동부장관은 고용노동부장관이 정하는 바에 따라 안전보건교육이수확인서를 지체 없이 내주어야 한다.', 5016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8777, null, 5018);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8778, '① 법 제9조제1항제4호에서 "안전ㆍ보건 관계 법령"이란 해당 사업 또는 사업장에서 생산ㆍ제조ㆍ판매ㆍ유통 중인 원료나 제조물에 적용되는 것으로서 그 원료나 제조물이 사람의 생명ㆍ신체에 미칠 수 있는 유해ㆍ위험 요인을 예방하고 안전하게 관리하는 데 관련되는 법령을 말한다.', 5019);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8779, '② 법 제9조제1항제4호에 따른 조치의 구체적인 사항은 다음 각 호와 같다.', 5019);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8780, null, 5020);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8781, '① 법 제9조제2항제4호에서 "안전ㆍ보건 관계 법령"이란 해당 공중이용시설ㆍ공중교통수단에 적용되는 것으로서 이용자나 그 밖의 사람의 안전ㆍ보건을 확보하는 데 관련되는 법령을 말한다.', 5021);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8782, '② 법 제9조제2항제4호에 따른 조치의 구체적인 사항은 다음 각 호와 같다.', 5021);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8783, '① 법 제13조제1항에 따른 공표(이하 이 조에서 "공표"라 한다)는 법 제4조에 따른 의무를 위반하여 발생한 중대산업재해로 법 제12조에 따라 범죄의 형이 확정되어 통보된 사업장을 대상으로 한다.', 5022);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8784, '② 공표 내용은 다음 각 호의 사항으로 한다.', 5022);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8785, '③ 고용노동부장관은 공표하기 전에 해당 사업장의 사업주 또는 경영책임자등에게 공표하려는 내용을 통지하고 30일 이상의 기간을 정하여 그에 대해 소명자료를 제출하게 하거나 의견을 진술할 수 있는 기회를 주어야 한다.', 5022);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8786, '④ 공표는 관보, 고용노동부나 「한국산업안전보건공단법」에 따른 한국산업안전보건공단의 홈페이지에 게시하는 방법으로 한다.', 5022);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8787, '⑤ 제4항에 따라 홈페이지에 게시하는 방법으로 공표하는 경우 공표기간은 1년으로 한다.', 5022);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8788, null, 5025);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8789, null, 5026);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8790, '①지방검찰청 또는 지방검찰청지청의 장은 법 제3조ㆍ법 제4조제2항 (미수범을 포함한다)ㆍ법 제5조제4항 또는 법 제8조의 죄를 범한 사람에 대하여 공소가 제기된 경우에는 지체 없이 그 사실을 법무부장관에게 보고하여야 한다. <개정 2009.7.7, 2019.5.7>', 5032);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8791, '② 고위공직자범죄수사처장은 제1항에서 규정한 죄를 범한 사람에 대하여 공소가 제기된 경우에는 지체 없이 그 사실을 법무부장관에게 통보해야 한다. <신설 2020.7.14>', 5032);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8792, '③법무부장관은 경제사범의 관리를 위하여 필요할 경우 관계기관 또는 관계기업체의 장에게 자료의 제출을 요청할 수 있다. <개정 2009.7.7, 2020.7.14>', 5032);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8793, '① 법 제14조제1항 본문에 따른 국가ㆍ지방자치단체가 자본금의 전부 또는 일부를 출자한 기관 및 그 출연(出捐)이나 보조를 받는 기관은 별표 1부터 별표 3까지에 해당하는 기관으로 한다. <개정 2019.5.7>', 5033);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8794, '②법 제14조제1항 본문에 따른 유죄판결된 범죄행위와 밀접한 관련이 있는 기업체는 다음 각 호의 어느 하나에 해당하는 기업체로 한다. <개정 2019.5.7>', 5033);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8795, '①법 제14조제1항 단서에 따라 법무부장관의 취업승인을 받으려는 사람은 취업하려는 날의 1개월 전까지 법무부장관에게 취업승인신청서를 제출하여야 한다. <개정 2009.7.7, 2019.5.7>', 5036);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8796, '② 법무부장관은 법 제14조제1항 단서에 따른 취업의 승인 여부를 결정한 때에는 지체 없이 그 결정내용을 신청인에게 통지하여야 한다. <개정 2009.7.7>', 5036);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8797, '①제11조에 따른 관허업을 영위하기 위하여 법 제14조제2항 단서에 따른 법무부장관의 승인을 받으려는 사람은 승인신청서를 해당 관허업의 허가등에 관한 소관 행정기관의 장에게 제출하여야 한다. <개정 2009.7.7, 2019.5.7>', 5037);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8798, '②제1항에 따른 승인신청서에는 관허업의 허가등에 관한 신청서류의 사본 1부를 첨부하여야 한다. <개정 2019.5.7>', 5037);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8799, '③ 소관 행정기관의 장은 제1항에 따른 승인신청서를 받은 때에는 관허업의 허가등에 관한 신청서류의 사본이 원본과 다름없음을 확인한 후 지체 없이 이를 법무부장관에게 송부하여야 한다. <개정 2009.7.7, 2019.5.7>', 5037);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8800, '④법무부장관이 제3항에 따른 승인신청서를 송부받아 그 승인여부를 결정한 때에는 지체 없이 그 내용을 그 승인신청을 한 사람과 소관 행정기관의 장에게 통지하여야 한다. <개정 2009.7.7, 2019.5.7>', 5037);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8801, '① 법무부장관은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 민감정보, 같은 법 시행령 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호, 외국인등록번호나 그 밖의 개인정보가 포함된 자료를 처리할 수 있다.', 5038);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8802, '② 허가등에 관한 소관 행정기관의 장은 법 제14조제2항 및 이 영 제14조에 따른 허가등의 승인 신청에 관한 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다.', 5038);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8803, null, 5040);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8804, null, 5041);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8805, null, 5043);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8806, '①법 제6조제10항의 규정에 의하여 범죄신고자등보좌인(이하 "보좌인"이라 한다)에게 지급할 수 있는 비용은 범죄신고자등과의 동행일수에 따른 일당ㆍ여비 및 숙박료(이하 이 조에서 "실비"라 한다)로 한다.', 5044);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8807, '②제1항의 규정에 의한 실비는 당해 사건의 진행경과에 따라 참고인 또는 증인에 준하여 지급하되, 수사단계에서는 수사기관이, 재판단계에서는 법원이 각각 이를 지급한다.', 5044);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8808, '①법 제7조제3항의 규정에 의한 범죄신고자등신원관리카드(이하 "신원관리카드"라 한다)에는 범죄신고자등의 성명ㆍ주민등록번호ㆍ주소 및 직업 등 신원을 알 수 있는 사항과 보좌인, 변호인, 법제13조의 규정에 의한 신변안전조치 및 법 제14조의 규정에 의한 구조금의 지급에 관한 사항 등을 기재한다.', 5045);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8809, '②법 제7조제4항의 규정에 의하여 범죄신고자등이 조서등에 가명으로 서명한 때에는 검사 또는 사법경찰관은 조서에 기재한 가명을 신원관리카드에 기재하고 범죄신고자등으로 하여금 본명과 가명의 서명을 신원관리카드에 기재하고 무인하게 하여야 한다.', 5045);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8810, '①사법경찰관이 사건을 송치하는 때에는 수사서류와 별도로 신원관리카드를 봉인하여 사건기록과 함께 관할 검찰청에 이를 제출하여야한다.', 5046);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8811, '②각급 검찰청의 장(지방검찰청 지청의 장을 포함한다)은 신원관리카드를 관리하는 검사를 지정하여야 한다.', 5046);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8812, '③신원관리카드는 공소제기후에도 제2항의 규정에 의한 검사가 이를 관리한다.', 5046);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8813, '④법 제11조제3항 후단의 규정에 의하여 증인의 신원확인을 하는 때에는 검사가공판정에서 재판장 또는 판사에게 직접 신원관리카드를 제시하고, 재판장 또는판사는 지체없이 담당 법원사무관 등으로 하여금 신원관리카드에 의하여 신원을 확인하게 하여야 한다.', 5046);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8814, '①법 제13조제1항 내지 제3항의 규정에 의한 신변안전조치의 요청 또는 신청은 이를 서면(전자문서를 포함한다. 이하 같다)으로 하여야 한다. 다만, 긴급을 요하는 경우에는 구두 또는 유선으로 하되, 사후에 지체없이 관련 서면을 제출하여야 한다. <개정 2004.3.17>', 5047);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8815, '②재판장 또는 판사는 제1항의 규정에 불구하고 공판정에 출석한 검사에게 신변안전조치를 취하도록 구두로 요청할 수 있다. 이 경우 그 취지를 공판조서에 기재하여야 한다.', 5047);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8816, '③제1항의 규정에 의한 신변안전조치를 요청 또는 신청하고자 하는 때에는 필요한 신변안전조치의 종류와 기간을 구체적으로 기재하여야 한다.', 5047);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8817, '④경찰청장(해양경찰청장을 포함한다. 이하 같다) 또는 시ㆍ도경찰청장(지방해양경찰청장을 포함한다. 이하 같다)은 당해관서에서 수사중인 사건의 범죄신고자등이나 그 친족 등에 대하여 신변안전조치를 취할 필요가 있는 때에는 대상자의 주거지 또는 현재지를 관할하는 경찰서장(해양경찰서장을 포함한다. 이하 같다)에게 신변안전조치를 취하도록 지시할 수 있다. <개정 2014.11.19, 2017.7.26, 2020.12.31>', 5047);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8818, null, 5048);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8819, '①경찰서장이 법 제13조제1항의 규정에 의한 신변안전조치를 취한 때에는 다음 각호의 구분에 따라 지체없이 그 사실을 해당검사에게 통보하여야 한다. <개정 2020.12.31>', 5049);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8820, '②제1항의 규정에 의한 통보서류 및 신변안전조치와 관련된 서류는 이를 공개하여서는 아니된다.', 5049);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8821, '①법 제14조의 규정에 의한 구조금은 지출하였거나 지출할 필요가 있는 치료비, 생활비, 이사 및 전직비용, 방범시설 설치비, 수사기간중 범죄신고자등 또는 그 친족등의 보호나 경호에 필요한 비용과 위자료 등을 포함하여 이를 산정한다.', 5050);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8822, '②제1항의 규정에 의한 구조금중 치료비, 이사비용, 방범시설 설치비와 범죄신고자등 또는 그 친족 등의 보호나 경호에 필요한 비용은 이를 실비로 지급한다.', 5050);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8823, '③제1항의 규정에 의한 구조금중 생활비ㆍ전직비용 및 위자료는 이를 합산하여 월정액으로 지급할 수 있으며, 이 경우에는 구조금지급 대상자의 근무직종에 따라 구조결정시 최저임금법에서 정한 일급최저임금의 5배 이하를 기준으로 하여 산정하여야 한다.', 5050);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8824, '①심의회는 제10조의 규정에 의한 구조금의 신청이 있는 때에는 특별한 사유가 없는 한 신청일부터 1월 이내에 구조금의 지급여부에 대한결정(지급한다는 결정을 하는 경우에는 그 금액을 포함한다. 이하 같다)을 하여야한다.', 5052);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8825, '②검사는 제10조 또는 제1항의 규정에 의한 절차를 거칠 수 없는 긴급한 사유가 있는 때에는 범죄신고자등 또는 그 친족등의 보호나 경호 등에 필요한 비용 등을 가지급할 것을 심의회에 요청할 수 있다. 이 경우 심의회는 제1항의 규정에 불구하고 가지급결정을 할 수 있다.', 5052);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8826, '①심의회의 위원장은 심의회의 업무를 통할하고, 심의회를 대표한다.', 5055);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8827, '②위원장이 부득이한 사유로 직무를 수행할 수 없는 때에는 위원장이 미리 지명한 위원이 그 직무를 대행하고, 지명이 없는 경우에는 심의회가 설치된 기관의 소속공무원인 위원중에서 선임자가 그 직무를 대행한다.', 5055);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8828, '①위원장은 심의회의 회의(이하 "회의"라 한다)를 소집하고 그 의장이 된다.', 5056);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8829, '②회의는 위원장을 포함한 재적위원 과반수의 출석으로 개의하고, 출석위원 3분의 2이상의 찬성으로 의결한다.', 5056);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8830, '③구조금의 액수에 관한 의견이 3 이상으로 나뉘어져 각각 의결정족수 3분의 2에 달하지 못한 때에는 의결정족수 3분의 2에 달하기까지 최소액의 의견수에 순차로 다액의 의견수를 더하여 그중 최다액의 의견에 의한다.', 5056);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8831, '①심의회에 그 사무를 처리하게 하기 위하여 간사 1인과 서기 약간인을 둔다.', 5057);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8832, '②간사와 서기는 심의회가 설치된 지방검찰청 소속 공무원중에서 위원장의 추천으로 당해 지방검찰청 검사장이 임명한다.', 5057);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8833, '③간사는 위원장의 명에 의하여 심의회의 사무를 처리한다.', 5057);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8834, '④간사는 회의에 출석하여 발언할 수 있다.', 5057);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8835, '⑤서기는 간사를 보조하고 심의회의 관련서류를 관리한다.', 5057);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8836, '①법무부장관은 각 심의회를 지휘ㆍ감독하기 위하여 필요한 명령이나 조치를 할 수 있다.', 5058);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8837, '②법무부장관은 제1항의 직무를 행하기 위하여 필요하다고 인정하는 때에는 소속직원 또는 각급 검찰청의 검사로 하여금 각 심의회의 업무처리사항에 관하여 감사를 하게 할 수 있다.', 5058);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8838, '①심의회가 구조결정을 한 때에는 구조결정서를 작성하고 회의에 출석한 위원 전원이 서명 또는 날인하여야 한다.', 5059);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8839, '②제1항의 규정에 의한 구조결정서에는 다음 각호의 사항을 기재하여야 한다.', 5059);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8840, '③심의회가 구조결정을 한 때에는 신청인에게 구조결정통지서를 송부하여야 한다.', 5059);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8841, '①구조금의 지급을 청구하고자 하는 자는 구조결정을 한심의회가 설치된 지방검찰청에 구조금지급청구서를 제출하여야 한다.', 5060);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8842, '②제1항의 규정에 의한 청구서에는 다음 각호의 사항을 기재하여야 한다.', 5060);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8843, null, 5063);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8844, '① 영 및 이 규칙에 따른 통지를 할 때에는 「우편법 시행규칙」 제25조제1항제6호에 따른 특별송달로써 해야 한다.', 5064);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8845, '② 영 제5조제1항에 따른 범죄피해재산 환부절차 개시에 관한 통지는 별지 제1호서식에 따른다.', 5064);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8846, '① 청구인은 영 제6조제1항에 따라 회복대상재산의 환부를 청구하려는 경우에는 별지 제2호서식의 청구서에 다음 각 호의 서류를 첨부하여 청구해야 한다.', 5065);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8847, '② 영 제6조제1항제4호에서 "범죄피해재산의 환부청구를 위해 필요한 사항으로서 법무부령으로 정하는 사항"이란 다음 각 호의 사항을 말한다.', 5065);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8848, '③ 검사는 제1항에 따른 청구서를 제출받은 경우에는 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통해 다음 각 호의 서류를 확인해야 한다. 다만, 청구인이 제1호의 서류 확인에 동의하지 않은 경우에는 그 서류를 첨부하게 해야 한다.', 5065);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8849, '① 청구인은 영 제6조제2항에 따라 청구사항을 변경하려는 경우에는 별지 제3호서식의 변경신고서에 그 변경사항을 소명하는 자료를 첨부하여 범죄피해재산 환부절차를 담당하는 검사에게 제출해야 한다.', 5066);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8850, '② 검사는 제1항에 따른 변경신고서를 제출받은 경우에는 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통해 다음 각 호의 서류를 확인해야 한다. 다만, 청구인이 제1호의 서류 확인에 동의하지 않은 경우에는 그 서류를 첨부하게 해야 한다.', 5066);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8851, '① 영 제7조제1항에 따른 결정은 별지 제4호서식의 회복대상재산 환부결정서에 따른다.', 5067);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8852, '② 검사가 영 제7조제3항에 따라 회복대상재산 환부 여부의 결정 취지와 이유를 청구인에게 통지할 때에는 별지 제5호서식에 따른다.', 5067);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8853, '① 청구인은 영 제10조제1항에 따라 이의신청을 하려는 경우에는 별지 제7호서식의 이의신청서에 다음 각 호의 서류를 첨부하여 신청해야 한다.', 5069);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8854, '② 검사는 제1항에 따른 이의신청서를 제출받은 경우에는 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통해 다음 각 호의 서류를 확인해야 한다. 다만, 이의신청을 한 청구인이 제1호의 서류 확인에 동의하지 않은 경우에는 그 서류를 첨부하게 해야 한다.', 5069);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8855, '① 영 제10조제2항에 따른 이의신청에 대한 결정은 별지 제8호서식의 결정서에 따른다.', 5070);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8856, '② 검찰청의 장은 영 제10조제3항에 따라 이의신청을 한 청구인에게 이의신청에 대한 결정의 취지와 이유를 통지할 때에는 별지 제9호서식에 따른다.', 5070);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8857, '① 영 제11조에 따른 범죄피해재산환부심의회(이하 "심의회"라 한다)의 위원장(이하 "위원장"이라 한다)은 심의회를 대표하고 심의회의 업무를 총괄한다.', 5071);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8858, '② 위원장은 심의회를 소집하고 그 의장이 된다.', 5071);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8859, '③ 심의회는 심의회의 위원(이하 "위원"이라 한다) 과반수의 출석으로 개의(開議)하고, 출석위원 과반수의 찬성으로 의결한다.', 5071);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8860, '④ 심의회에 참석한 위원에게는 예산의 범위에서 수당을 지급할 수 있다.', 5071);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8861, '⑤ 제1항부터 제4항까지에서 규정한 사항 외에 심의회의 구성 및 운영에 필요한 사항은 각 검찰청의 장이 정한다.', 5071);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8862, '① 위원이 다음 각 호의 어느 하나에 해당하는 경우에는 심의회의 심의ㆍ의결에서 제척(除斥)된다.', 5072);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8863, '② 해당 안건의 당사자는 위원에게 공정한 심의ㆍ의결을 기대하기 어려운 사정이 있는 경우에는 심의회에 기피 신청을 할 수 있고, 심의회는 의결로 기피 여부를 결정한다. 이 경우 기피 신청의 대상인 위원은 그 의결에 참여할 수 없다.', 5072);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8864, '③ 위원이 제1항 각 호에 따른 제척사유에 해당하는 경우에는 스스로 해당 안건의 심의ㆍ의결에서 회피해야 한다.', 5072);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8865, null, 5073);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8866, null, 5075);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8867, '① 누구든지 이 법으로 정하는 바에 따라 국민참여재판을 받을 권리를 가진다.', 5076);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8868, '② 대한민국 국민은 이 법으로 정하는 바에 따라 국민참여재판에 참여할 권리와 의무를 가진다.', 5076);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8869, '① 다음 각 호에 정하는 사건을 국민참여재판의 대상사건(이하 "대상사건"이라 한다)으로 한다. <개정 2012.1.17>', 5078);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8870, '② 피고인이 국민참여재판을 원하지 아니하거나 제9조제1항에 따른 배제결정이 있는 경우는 국민참여재판을 하지 아니한다.', 5078);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8871, '① 법원은 공소사실의 일부 철회 또는 변경으로 인하여 대상사건에 해당하지 아니하게 된 경우에도 이 법에 따른 재판을 계속 진행한다. 다만, 법원은 심리의 상황이나 그 밖의 사정을 고려하여 국민참여재판으로 진행하는 것이 적당하지 아니하다고 인정하는 때에는 결정으로 당해 사건을 지방법원 본원 합의부가 국민참여재판에 의하지 아니하고 심판하게 할 수 있다.', 5079);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8872, '② 제1항 단서의 결정에 대하여는 불복할 수 없다.', 5079);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8873, '③ 제1항 단서의 결정이 있는 경우에는 당해 재판에 참여한 배심원과 예비배심원은 해임된 것으로 본다.', 5079);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8874, '④ 제1항 단서의 결정 전에 행한 소송행위는 그 결정 이후에도 그 효력에 영향이 없다.', 5079);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8875, '① 법원은 대상사건의 피고인에 대하여 국민참여재판을 원하는지 여부에 관한 의사를 서면 등의 방법으로 반드시 확인하여야 한다. 이 경우 피고인 의사의 구체적인 확인 방법은 대법원규칙으로 정하되, 피고인의 국민참여재판을 받을 권리가 최대한 보장되도록 하여야 한다.', 5081);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8876, '② 피고인은 공소장 부본을 송달받은 날부터 7일 이내에 국민참여재판을 원하는지 여부에 관한 의사가 기재된 서면을 제출하여야 한다. 이 경우 피고인이 서면을 우편으로 발송한 때, 교도소 또는 구치소에 있는 피고인이 서면을 교도소장ㆍ구치소장 또는 그 직무를 대리하는 자에게 제출한 때에 법원에 제출한 것으로 본다.', 5081);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8877, '③ 피고인이 제2항의 서면을 제출하지 아니한 때에는 국민참여재판을 원하지 아니하는 것으로 본다.', 5081);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8878, '④ 피고인은 제9조제1항의 배제결정 또는 제10조제1항의 회부결정이 있거나 공판준비기일이 종결되거나 제1회 공판기일이 열린 이후에는 종전의 의사를 바꿀 수 없다.', 5081);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8879, '① 법원은 공소제기 후부터 공판준비기일이 종결된 다음날까지 다음 각 호의 어느 하나에 해당하는 경우 국민참여재판을 하지 아니하기로 하는 결정을 할 수 있다. <개정 2012.1.17>', 5082);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8880, '② 법원은 제1항의 결정을 하기 전에 검사ㆍ피고인 또는 변호인의 의견을 들어야 한다.', 5082);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8881, '③ 제1항의 결정에 대하여는 즉시항고를 할 수 있다.', 5082);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8882, '① 제8조에 따라 피고인이 국민참여재판을 원하는 의사를 표시한 경우 지방법원 지원 합의부가 제9조제1항의 배제결정을 하지 아니하는 경우에는 국민참여재판절차 회부결정을 하여 사건을 지방법원 본원 합의부로 이송하여야 한다.', 5083);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8883, '② 지방법원 지원 합의부가 심판권을 가지는 사건 중 지방법원 지원 합의부가 제1항의 회부결정을 한 사건에 대하여는 지방법원 본원 합의부가 관할권을 가진다.', 5083);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8884, '① 법원은 피고인의 질병 등으로 공판절차가 장기간 정지되거나 피고인에 대한 구속기간의 만료, 성폭력범죄 피해자의 보호, 그 밖에 심리의 제반 사정에 비추어 국민참여재판을 계속 진행하는 것이 부적절하다고 인정하는 경우에는 직권 또는 검사ㆍ피고인ㆍ변호인이나 성폭력범죄 피해자 또는 법정대리인의 신청에 따라 결정으로 사건을 지방법원 본원 합의부가 국민참여재판에 의하지 아니하고 심판하게 할 수 있다. <개정 2012.1.17>', 5084);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8885, '② 법원은 제1항의 결정을 하기 전에 검사ㆍ피고인 또는 변호인의 의견을 들어야 한다.', 5084);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8886, '③ 제1항의 결정에 대하여는 불복할 수 없다.', 5084);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8887, '④ 제1항의 결정이 있는 경우에는 제6조제3항 및 제4항을 준용한다.', 5084);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8888, '① 배심원은 국민참여재판을 하는 사건에 관하여 사실의 인정, 법령의 적용 및 형의 양정에 관한 의견을 제시할 권한이 있다.', 5085);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8889, '② 배심원은 법령을 준수하고 독립하여 성실히 직무를 수행하여야 한다.', 5085);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8890, '③ 배심원은 직무상 알게 된 비밀을 누설하거나 재판의 공정을 해하는 행위를 하여서는 아니 된다.', 5085);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8891, '① 법정형이 사형ㆍ무기징역 또는 무기금고에 해당하는 대상사건에 대한 국민참여재판에는 9인의 배심원이 참여하고, 그 외의 대상사건에 대한 국민참여재판에는 7인의 배심원이 참여한다. 다만, 법원은 피고인 또는 변호인이 공판준비절차에서 공소사실의 주요내용을 인정한 때에는 5인의 배심원이 참여하게 할 수 있다.', 5086);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8892, '② 법원은 사건의 내용에 비추어 특별한 사정이 있다고 인정되고 검사ㆍ피고인 또는 변호인의 동의가 있는 경우에 한하여 결정으로 배심원의 수를 7인과 9인 중에서 제1항과 달리 정할 수 있다.', 5086);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8893, '① 법원은 배심원의 결원 등에 대비하여 5인 이내의 예비배심원을 둘 수 있다.', 5087);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8894, '② 이 법에서 정하는 배심원에 대한 사항은 그 성질에 반하지 아니하는 한 예비배심원에 대하여 준용한다.', 5087);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8895, null, 5090);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8896, null, 5091);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8897, null, 5092);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8898, null, 5093);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8899, '① 지방법원장은 배심원후보예정자명부를 작성하기 위하여 행정안전부장관에게 매년 그 관할 구역 내에 거주하는 만 20세 이상 국민의 주민등록정보에서 일정한 수의 배심원후보예정자의 성명ㆍ생년월일ㆍ주소 및 성별에 관한 주민등록정보를 추출하여 전자파일의 형태로 송부하여 줄 것을 요청할 수 있다. <개정 2012.1.17, 2013.3.23, 2014.11.19, 2017.7.26>', 5095);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8900, '② 제1항의 요청을 받은 행정안전부장관은 30일 이내에 주민등록자료를 지방법원장에게 송부하여야 한다. <개정 2012.1.17, 2013.3.23, 2014.11.19, 2017.7.26>', 5095);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8901, '③ 지방법원장은 매년 주민등록자료를 활용하여 배심원후보예정자명부를 작성한다.', 5095);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8902, '① 법원은 배심원후보예정자명부 중에서 필요한 수의 배심원후보자를 무작위 추출 방식으로 정하여 배심원과 예비배심원의 선정기일을 통지하여야 한다.', 5096);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8903, '② 제1항의 통지를 받은 배심원후보자는 선정기일에 출석하여야 한다.', 5096);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8904, '③ 법원은 제1항의 통지 이후 배심원의 직무 종사 예정기간을 마칠 때까지 제17조부터 제20조까지에 해당하는 사유가 있다고 인정되는 배심원후보자에 대하여는 즉시 그 출석통지를 취소하고 신속하게 당해 배심원후보자에게 그 내용을 통지하여야 한다.', 5096);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8905, '① 법원은 합의부원으로 하여금 선정기일의 절차를 진행하게 할 수 있다. 이 경우 수명법관은 선정기일에 관하여 법원 또는 재판장과 동일한 권한이 있다.', 5097);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8906, '② 선정기일은 공개하지 아니한다.', 5097);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8907, '③ 선정기일에서는 배심원후보자의 명예가 손상되지 아니하고 사생활이 침해되지 아니하도록 배려하여야 한다.', 5097);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8908, '④ 법원은 선정기일의 속행을 위하여 새로운 기일을 정할 수 있다. 이 경우 선정기일에 출석한 배심원후보자에 대하여 새로운 기일을 통지한 때에는 출석통지서의 송달이 있었던 경우와 동일한 효력이 있다.', 5097);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8909, '① 법원은 배심원후보자가 제28조제1항에서 정하는 사유에 해당하는지의 여부를 판단하기 위하여 질문표를 사용할 수 있다.', 5098);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8910, '② 배심원후보자는 정당한 사유가 없는 한 질문표에 기재된 질문에 답하여 이를 법원에 제출하여야 한다.', 5098);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8911, '① 법원은 선정기일의 2일 전까지 검사와 변호인에게 배심원후보자의 성명ㆍ성별ㆍ출생연도가 기재된 명부를 송부하여야 한다.', 5099);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8912, '② 법원은 선정절차에 질문표를 사용하는 때에는 선정기일을 진행하기 전에 배심원후보자가 제출한 질문표 사본을 검사와 변호인에게 교부하여야 한다.', 5099);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8913, '① 법원은 검사ㆍ피고인 또는 변호인에게 선정기일을 통지하여야 한다.', 5100);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8914, '② 검사와 변호인은 선정기일에 출석하여야 하며, 피고인은 법원의 허가를 받아 출석할 수 있다.', 5100);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8915, '③ 법원은 변호인이 선정기일에 출석하지 아니한 경우 국선변호인을 선정하여야 한다.', 5100);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8916, '① 법원은 배심원후보자가 제17조부터 제20조까지의 사유에 해당하는지 여부 또는 불공평한 판단을 할 우려가 있는지 여부 등을 판단하기 위하여 배심원후보자에게 질문을 할 수 있다. 검사ㆍ피고인 또는 변호인은 법원으로 하여금 필요한 질문을 하도록 요청할 수 있고, 법원은 검사 또는 변호인으로 하여금 직접 질문하게 할 수 있다.', 5101);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8917, '② 배심원후보자는 제1항의 질문에 대하여 정당한 사유 없이 진술을 거부하거나 거짓 진술을 하여서는 아니 된다.', 5101);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8918, '③ 법원은 배심원후보자가 제17조부터 제20조까지의 사유에 해당하거나 불공평한 판단을 할 우려가 있다고 인정되는 때에는 직권 또는 검사ㆍ피고인ㆍ변호인의 기피신청에 따라 당해 배심원후보자에 대하여 불선정결정을 하여야 한다. 검사ㆍ피고인 또는 변호인의 기피신청을 기각하는 경우에는 이유를 고지하여야 한다.', 5101);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8919, '① 제28조제3항의 기피신청을 기각하는 결정에 대하여는 즉시 이의신청을 할 수 있다.', 5102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8920, '② 제1항의 이의신청에 대한 결정은 기피신청 기각결정을 한 법원이 한다.', 5102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8921, '③ 이의신청에 대한 결정에 대하여는 불복할 수 없다.', 5102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8922, '① 검사와 변호인은 각자 다음 각 호의 범위 내에서 배심원후보자에 대하여 이유를 제시하지 아니하는 기피신청(이하 "무이유부기피신청"이라 한다)을 할 수 있다.', 5103);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8923, '② 무이유부기피신청이 있는 때에는 법원은 당해 배심원후보자를 배심원으로 선정할 수 없다.', 5103);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8924, '③ 법원은 검사ㆍ피고인 또는 변호인에게 순서를 바꿔가며 무이유부기피신청을 할 수 있는 기회를 주어야 한다.', 5103);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8925, '① 법원은 출석한 배심원후보자 중에서 당해 재판에서 필요한 배심원과 예비배심원의 수에 해당하는 배심원후보자를 무작위로 뽑고 이들을 대상으로 직권, 기피신청 또는 무이유부기피신청에 따른 불선정결정을 한다.', 5104);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8926, '② 제1항의 불선정결정이 있는 경우에는 그 수만큼 제1항의 절차를 반복한다.', 5104);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8927, '③ 제1항 및 제2항의 절차를 거쳐 필요한 수의 배심원과 예비배심원 후보자가 확정되면 법원은 무작위의 방법으로 배심원과 예비배심원을 선정한다. 예비배심원이 2인 이상인 경우에는 그 순번을 정하여야 한다.', 5104);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8928, '④ 법원은 배심원과 예비배심원에게 누가 배심원으로 선정되었는지 여부를 알리지 아니할 수 있다.', 5104);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8929, '① 법원은 배심원 또는 예비배심원이 다음 각 호의 어느 하나에 해당하는 때에는 직권 또는 검사ㆍ피고인ㆍ변호인의 신청에 따라 배심원 또는 예비배심원을 해임하는 결정을 할 수 있다.', 5105);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8930, '② 제1항의 결정을 함에 있어서는 검사ㆍ피고인 또는 변호인의 의견을 묻고 출석한 당해 배심원 또는 예비배심원에게 진술기회를 부여하여야 한다.', 5105);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8931, '③ 제1항의 결정에 대하여는 불복할 수 없다.', 5105);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8932, '① 배심원과 예비배심원은 직무를 계속 수행하기 어려운 사정이 있는 때에는 법원에 사임을 신청할 수 있다.', 5106);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8933, '② 법원은 제1항의 신청에 이유가 있다고 인정하는 때에는 당해 배심원 또는 예비배심원을 해임하는 결정을 할 수 있다.', 5106);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8934, '③ 제2항의 결정을 함에 있어서는 검사ㆍ피고인 또는 변호인의 의견을 들어야 한다.', 5106);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8935, '④ 제2항의 결정에 대하여는 불복할 수 없다.', 5106);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8936, '① 제32조 및 제33조에 따라 배심원이 부족하게 된 경우 예비배심원은 미리 정한 순서에 따라 배심원이 된다. 이 때 배심원이 될 예비배심원이 없는 경우 배심원을 추가로 선정한다.', 5107);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8937, '② 국민참여재판 도중 심리의 진행 정도에 비추어 배심원을 추가선정하여 재판에 관여하게 하는 것이 부적절하다고 판단되는 경우 법원은 다음 각 호의 구분에 따라 남은 배심원만으로 계속하여 국민참여재판을 진행하는 결정을 할 수 있다. 다만, 배심원이 5인 미만이 되는 경우에는 그러하지 아니하다.', 5107);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8938, null, 5108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8939, '① 재판장은 제8조에 따라 피고인이 국민참여재판을 원하는 의사를 표시한 경우에 사건을 공판준비절차에 부쳐야 한다. 다만, 공판준비절차에 부치기 전에 제9조제1항의 배제결정이 있는 때에는 그러하지 아니하다.', 5109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8940, '② 공판준비절차에 부친 이후 피고인이 국민참여재판을 원하지 아니하는 의사를 표시하거나 제9조제1항의 배제결정이 있는 때에는 공판준비절차를 종결할 수 있다.', 5109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8941, '③ 지방법원 본원 합의부가 지방법원 지원 합의부로부터 제10조제1항에 따라 이송받은 사건에 대하여는 이미 공판준비절차를 거친 경우에도 필요한 때에는 공판준비절차에 부칠 수 있다.', 5109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8942, '④ 검사ㆍ피고인 또는 변호인은 증거를 미리 수집ㆍ정리하는 등 공판준비절차가 원활하게 진행되도록 협력하여야 한다.', 5109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8943, '① 법원은 주장과 증거를 정리하고 심리계획을 수립하기 위하여 공판준비기일을 지정하여야 한다.', 5110);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8944, '② 법원은 합의부원으로 하여금 공판준비기일을 진행하게 할 수 있다. 이 경우 수명법관은 공판준비기일에 관하여 법원 또는 재판장과 동일한 권한이 있다.', 5110);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8945, '③ 공판준비기일은 공개한다. 다만, 법원은 공개함으로써 절차의 진행이 방해될 우려가 있는 때에는 공판준비기일을 공개하지 아니할 수 있다.', 5110);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8946, '④ 공판준비기일에는 배심원이 참여하지 아니한다.', 5110);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8947, '① 공판정은 판사ㆍ배심원ㆍ예비배심원ㆍ검사ㆍ변호인이 출석하여 개정한다.', 5112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8948, '② 검사와 피고인 및 변호인은 대등하게 마주 보고 위치한다. 다만, 피고인신문을 하는 때에는 피고인은 증인석에 위치한다.', 5112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8949, '③ 배심원과 예비배심원은 재판장과 검사ㆍ피고인 및 변호인의 사이 왼쪽에 위치한다.', 5112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8950, '④ 증인석은 재판장과 검사ㆍ피고인 및 변호인의 사이 오른쪽에 배심원과 예비배심원을 마주 보고 위치한다.', 5112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8951, '① 법원은 특별한 사정이 없는 한 공판정에서의 심리를 속기사로 하여금 속기하게 하거나 녹음장치 또는 영상녹화장치를 사용하여 녹음 또는 영상녹화하여야 한다.', 5113);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8952, '② 제1항에 따른 속기록ㆍ녹음테이프 또는 비디오테이프는 공판조서와는 별도로 보관되어야 하며, 검사ㆍ피고인 또는 변호인은 비용을 부담하고 속기록ㆍ녹음테이프 또는 비디오테이프의 사본을 청구할 수 있다.', 5113);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8953, '① 배심원과 예비배심원은 다음 각 호의 행위를 할 수 있다.', 5114);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8954, '② 배심원과 예비배심원은 다음 각 호의 행위를 하여서는 아니 된다.', 5114);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8955, '① 배심원과 예비배심원은 법률에 따라 공정하게 그 직무를 수행할 것을 다짐하는 취지의 선서를 하여야 한다.', 5115);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8956, '② 재판장은 배심원과 예비배심원에 대하여 배심원과 예비배심원의 권한ㆍ의무ㆍ재판절차, 그 밖에 직무수행을 원활히 하는 데 필요한 사항을 설명하여야 한다.', 5115);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8957, '① 공판절차가 개시된 후 새로 재판에 참여하는 배심원 또는 예비배심원이 있는 때에는 공판절차를 갱신하여야 한다.', 5118);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8958, '② 제1항의 갱신절차는 새로 참여한 배심원 또는 예비배심원이 쟁점 및 조사한 증거를 이해할 수 있도록 하되, 그 부담이 과중하지 아니하도록 하여야 한다.', 5118);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8959, '① 재판장은 변론이 종결된 후 법정에서 배심원에게 공소사실의 요지와 적용법조, 피고인과 변호인 주장의 요지, 증거능력, 그 밖에 유의할 사항에 관하여 설명하여야 한다. 이 경우 필요한 때에는 증거의 요지에 관하여 설명할 수 있다.', 5119);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8960, '② 심리에 관여한 배심원은 제1항의 설명을 들은 후 유ㆍ무죄에 관하여 평의하고, 전원의 의견이 일치하면 그에 따라 평결한다. 다만, 배심원 과반수의 요청이 있으면 심리에 관여한 판사의 의견을 들을 수 있다.', 5119);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8961, '③ 배심원은 유ㆍ무죄에 관하여 전원의 의견이 일치하지 아니하는 때에는 평결을 하기 전에 심리에 관여한 판사의 의견을 들어야 한다. 이 경우 유ㆍ무죄의 평결은 다수결의 방법으로 한다. 심리에 관여한 판사는 평의에 참석하여 의견을 진술한 경우에도 평결에는 참여할 수 없다.', 5119);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8962, '④ 제2항 및 제3항의 평결이 유죄인 경우 배심원은 심리에 관여한 판사와 함께 양형에 관하여 토의하고 그에 관한 의견을 개진한다. 재판장은 양형에 관한 토의 전에 처벌의 범위와 양형의 조건 등을 설명하여야 한다.', 5119);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8963, '⑤ 제2항부터 제4항까지의 평결과 의견은 법원을 기속하지 아니한다.', 5119);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8964, '⑥ 제2항 및 제3항의 평결결과와 제4항의 의견을 집계한 서면은 소송기록에 편철한다.', 5119);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8965, '① 판결의 선고는 변론을 종결한 기일에 하여야 한다. 다만, 특별한 사정이 있는 때에는 따로 선고기일을 지정할 수 있다.', 5121);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8966, '② 변론을 종결한 기일에 판결을 선고하는 경우에는 판결서를 선고 후에 작성할 수 있다.', 5121);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8967, '③ 제1항 단서의 선고기일은 변론종결 후 14일 이내로 정하여야 한다.', 5121);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8968, '④ 재판장은 판결선고 시 피고인에게 배심원의 평결결과를 고지하여야 하며, 배심원의 평결결과와 다른 판결을 선고하는 때에는 피고인에게 그 이유를 설명하여야 한다.', 5121);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8969, '① 판결서에는 배심원이 재판에 참여하였다는 취지를 기재하여야 하고, 배심원의 의견을 기재할 수 있다.', 5122);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8970, '② 배심원의 평결결과와 다른 판결을 선고하는 때에는 판결서에 그 이유를 기재하여야 한다.', 5122);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8971, '① 누구든지 당해 재판에 영향을 미치거나 배심원 또는 예비배심원이 직무상 취득한 비밀을 알아낼 목적으로 배심원 또는 예비배심원과 접촉하여서는 아니 된다.', 5124);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8972, '② 누구든지 배심원 또는 예비배심원이 직무상 취득한 비밀을 알아낼 목적으로 배심원 또는 예비배심원의 직무에 종사하였던 사람과 접촉하여서는 아니 된다. 다만, 연구에 필요한 경우는 그러하지 아니하다.', 5124);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8973, '① 법령으로 정하는 경우를 제외하고는 누구든지 배심원ㆍ예비배심원 또는 배심원후보자의 성명ㆍ주소와 그 밖의 개인정보를 공개하여서는 아니 된다.', 5125);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8974, '② 배심원ㆍ예비배심원 또는 배심원후보자의 직무를 수행하였던 사람들의 개인정보에 대하여는 본인이 동의하는 경우에 한하여 공개할 수 있다.', 5125);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8975, '① 재판장은 배심원 또는 예비배심원이 피고인이나 그 밖의 사람으로부터 위해를 받거나 받을 염려가 있다고 인정하는 때 또는 공정한 심리나 평의에 지장을 초래하거나 초래할 염려가 있다고 인정하는 때에는 배심원 또는 예비배심원의 신변안전을 위하여 보호, 격리, 숙박, 그 밖에 필요한 조치를 취할 수 있다.', 5126);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8976, '② 검사, 피고인, 변호인, 배심원 또는 예비배심원은 재판장에게 제1항의 조치를 취하도록 요청할 수 있다.', 5126);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8977, '① 국민참여재판에 관한 조사ㆍ연구 등을 수행하기 위하여 대법원에 사법참여기획단을 둔다.', 5127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8978, '② 사법참여기획단은 다음 각 호의 사항에 관한 임무를 수행한다.', 5127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8979, '③ 사법참여기획단의 조직과 활동, 그 밖에 필요한 사항은 대법원규칙으로 정한다.', 5127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8980, '① 국민참여재판의 시행경과에 대한 분석 등을 통하여 국민참여재판 제도의 최종적인 형태를 결정하기 위하여 대법원에 국민사법참여위원회를 둔다.', 5128);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8981, '② 국민사법참여위원회의 조직과 활동, 그 밖에 필요한 사항은 대법원규칙으로 정한다.', 5128);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8982, '① 배심원 또는 예비배심원에게 그 직무에 관하여 청탁을 한 자는 2년 이하의 징역 또는 500만원 이하의 벌금에 처한다.', 5129);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8983, '② 배심원후보자에게 그 직무에 관하여 청탁을 한 자도 제1항과 같다.', 5129);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8984, '① 피고사건에 관하여 당해 피고사건의 배심원ㆍ예비배심원 또는 그러한 직에 있었던 자나 그 친족에 대하여 전화ㆍ편지ㆍ면회, 그 밖의 다른 방법으로 겁을 주거나 불안감을 조성하는 등의 위협행위를 한 자는 2년 이하의 징역 또는 500만원 이하의 벌금에 처한다.', 5130);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8985, '② 피고사건에 관하여 당해 피고사건의 배심원후보자 또는 그 친족에 대하여 제1항의 방법으로 위협행위를 한 자도 제1항과 같다.', 5130);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8986, '① 배심원 또는 예비배심원이 직무상 알게 된 비밀을 누설한 때에는 6개월 이하의 징역 또는 300만원 이하의 벌금에 처한다.', 5131);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8987, '② 배심원 또는 예비배심원이었던 자가 직무상 알게 된 비밀을 누설한 때에도 제1항과 같다. 다만, 연구에 필요한 협조를 한 경우는 그러하지 아니하다.', 5131);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8988, '① 배심원ㆍ예비배심원 또는 배심원후보자가 직무와 관련하여 재물 또는 재산상 이익을 수수ㆍ요구ㆍ약속한 때에는 3년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 5132);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8989, '② 배심원ㆍ예비배심원 또는 배심원후보자에게 제1항의 재물 또는 재산상 이익을 약속ㆍ공여 또는 공여의 의사를 표시한 자도 제1항과 같다.', 5132);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8990, '① 다음 각 호의 어느 하나에 해당하는 때에 법원은 결정으로 200만원 이하의 과태료를 부과한다.', 5133);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8991, '② 제1항의 결정에 대하여는 즉시항고할 수 있다.', 5133);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8992, null, 5136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8993, '① 법 제6조제1항에 따라 교도작업에 참여하려는 민간기업은 별지 서식의 참여신청서를 법무부장관에게 제출하여야 한다.', 5137);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8994, '② 교도작업에 참여하려는 민간기업은 경영상태가 양호하고, 취업지원을 하는 등 수형자의 사회복귀에 도움이 될 수 있어야 한다.', 5137);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8995, '① 법 제6조제2항 단서에서 "법무부장관이 정하는 단기의 계약"이란 계약기간이 2개월 이하인 계약을 말한다.', 5138);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8996, '② 소장은 제1항에 따른 계약을 체결한 경우에는 지체 없이 법무부장관에게 보고하여야 한다.', 5138);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8997, '① 영 제6조에 따른 교도작업의 종류는 다음  각 호와 같다', 5139);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8998, '② 소장은 제1항에 따른 작업을 중지하려면 지방교정청장의 승인을 받아야 한다.', 5139);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (8999, null, 5140);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9000, '① 계약담당자는 계약을 수의계약으로 하려면 「교도관직무규칙」 제21조에 따른 교도관회의의 심의를 거쳐야 한다.', 5142);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9001, '② 계약담당자가 계약을 수의계약으로 한 경우에는 법무부장관에게 보고하여야 한다.', 5142);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9002, null, 5145);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9003, '①법 제8조의2제2항의 규정에 의하여 불출석심판을 청구하고자 하는 자는 즉결심판을 청구할 관할 경찰서장(해양경찰서장을 포함한다. 이하 같다)에게 제2조제1호ㆍ제2호의 경우에는 경범죄 처벌법 시행령 제2조 또는 도로교통법 시행령 제93조 각 항에 규정된 범칙금액에 그 100분의 50을 더한 금액을, 제3호의 경우에는 별표 기재 벌금등예납기준액을 예납하고, 별지 1 또는 별지 2 서식에 의한 불출석심판청구서를 제출하여야 한다. <개정 2003.5.29, 2014.4.3>', 5146);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9004, '②제1항의 규정에 의하여 예납하여야 할 금액에 1,000미만의 단수(端數)가 있는 때에는 그 단수는 이를 계산하지 아니한다. 제1항의 규정에 의하여 예납하여야 할 금액이 200,000원을 초과하는 때에는 이를 200,000원으로 본다. <개정 2000.6.3>', 5146);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9005, '③불출석심판청구인이 제1항 및 제2항의 규정에 의한 예납액을 예납한 때에는 이를 수령한 경찰공무원이 별지1 서식의 불출석심판청구서의 해당란에 그 취지를 기재하고 기명날인하여야 한다. 다만, 별지2 서식을 이용하는 경우에는 그러하지 아니하다. <개정 2000.6.3>', 5146);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9006, '④경찰서장이 즉결심판을 청구함에는 제1항의 규정에 의하여 제출받은 불출석심판청구서를 사건기록과 함께 법원에 제출하여야 한다.', 5146);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9007, '①제3조의 규정에 의한 불출석심판청구가 있는 때에는 법원은 특별한 사정이 없는 한 그 불출석심판청구를 허가하여야 한다. 다만, 제2조 제3호에 해당하는 사건으로서 그 죄질이 중하거나 범행이 상습적으로 이루어진 경우에는 불출석심판을 허가하지 아니한다. <개정 2000.6.3>', 5147);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9008, '②불출석심판청구에 대한 허부의 결정은 법정에서 선고할 수 있다. 이 경우에는 불출석심판청구서의 오른쪽 윗부분의 여백에 그 취지를 기재하고 법관이 날인하여야 한다.', 5147);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9009, '①불출석심판청구를 허가하여 피고인의 출석없이 즉결심판을 한 때에는 법원서기관, 법원사무관, 법원주사 또는 법원주사보는 즉결심판서의 오른쪽 위의 여백과 즉결심판사건부의 비고란에 각각 "불출석심판"이라고 주인하여 놓아야 한다.', 5148);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9010, '②불출석심판청구를 허가하지 아니한 때에는 다시 즉결심판기일을 정하여 피고인을 소환하여야 한다.', 5148);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9011, '① 「부정수표 단속법」(이하 "법"이라 한다)에 따른 금융기관은 「수표법」과 그 밖의 법령에 따라 수표의 지급 사무를 처리하는 은행 및 은행과 같이 취급되는 사람 또는 시설로 한다.', 5150);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9012, '② 법 제2조제1항제1호에 따른 가공인물의 명의는 수표발행인의 명의가 개인인 경우에는 주민등록표상의 성명과 일치하지 아니하는 것으로 하고, 법인인 경우에는 법인 등기사항증명서상의 상호ㆍ명칭과 일치하지 아니하는 것으로 한다.', 5150);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9013, '③ 법 제2조제2항에 따른 제시기일은 「수표법」 제28조제2항에 따라 수표를 제시한 날 및 같은 법 제29조에 따라 지급제시기간에 금융기관에 지급을 받기 위하여 수표를 제시한 날로 한다.', 5150);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9014, '④ 법 제2조제2항에 따른 제시기일에 지급되지 아니하게 한 경우는 「수표법」 제39조의 지급거절을 증명하였을 때로 한다.', 5150);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9015, '①이 규칙에서 사용하는 "인도조약" "청구국" "인도범죄" 또는 "범죄인"의 용어의 정의는 법 제2조의 규정한 바와 같다.', 5152);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9016, '②이 규칙에서 "법원"이라 함은 서울고등법원을, "판사"라 함은 서울고등법원판사를, "검사"라 함은 서울고등검찰청검사를 말한다.', 5152);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9017, '①법 제13조제3항의 규정에 의한 인도심사 청구서에는 다음의 사항을 기재하고 검사가 서명날인하여야 한다.', 5155);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9018, '②범죄인의 성명을 알 수 없는 때에는 그 인상, 체격등 범죄인을 특정하는데 필요한 사항을 기재하여야 한다.', 5155);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9019, '③범죄인의 연령, 성별, 국적, 직업 또는 주거가 분명하지 아니한 때에는 그 취지를 기재하여야 한다.', 5155);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9020, '①인도구속영장 또는 긴급인도구속영장이 발부된 범죄인에 대하여 인도심사청구를 하는 경우에는 인도심사청구서에 제5조제1항에 열거된 사항외에 다음 각호의 사항을 기재하여야 한다.', 5156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9021, '②제1항의 경우 검사는 인도심사청구서에 인도구속영장, 긴급인도구속영장, 기타 범죄인의 구속과 석방에 관련된 서류를 첨부하여야 한다.', 5156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9022, null, 5158);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9023, '①범죄인 또는 범죄인의 법정대리인, 배우자, 직계친족, 형제자매, 호주, 가족이나 동거인 또는 고용주는 언제든지 범죄인을 위하여 변호인을 선임할 수 있다.', 5159);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9024, '②제1항에 규정된 자가 변호인을 선임하는 때에는, 인도심사청구가 있기 전에는 검사에게, 인도심사청구가 있은 이후에는 법원에, 그 선임의 취지를 기재하고 변호인과 연명날인한 서면을 제출하여야 한다.', 5159);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9025, '③검사가 제2항의 서면을 받은 때에는 인도심사청구서에 그 서면을 첨부하는등의 방법으로 이를 법원에 제출하여야 한다.', 5159);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9026, '①법원은 다음 각호의 경우에는 심문기일을 열어 범죄인 또는 출석한 관계인을 신문하거나 그 의견을 진술하게 하여야 한다.', 5162);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9027, '②심문기일은 재판장이 이를 정한다.', 5162);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9028, '③법원은 제1항의 경우에 검사, 범죄인 및 그 변호인에게 심문기일을 통지하여야 한다.', 5162);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9029, '①검사가 법 제17조제1항의 규정에 의한 물건의 양도허가청구를 함에는 범죄인의 성명, 인도범죄사실의 요지, 양도할 국명, 물건의 종류, 특징 및 수량등 양도할 물건을 특정할 수 있는 사항을 기재한 서면으로 이를 하여야 한다.', 5171);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9030, '②물건의 양도허가청구는 인도심사청구서에 제1항의 사항을 기재하여 할 수 있다.', 5171);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9031, '③법원이 양도허가청구된 물건의 전부 또는 일부에 대하여 양도를 허가하는 때에는 결정서에 그 취지 및 양도될 물건의 목록, 양도할 국가명을 기재하고 이를 검사에게 송부한다.', 5171);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9032, '④법원은 제3항의 규정에 불구하고 제1항의 청구서의 여백에 양도허가 또는 불허가의 취지를 기재하고 관여법관이 서명날인하여 청구서를 검사에게 반환함으로써 전항의 결정서의 작성 및 송부에 갈음할 수 있다.', 5171);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9033, '⑤법원이 법 제15조제1항의 규정에 의한 결정과 동시에 물건양도의 허부를 결정하는 경우에는, 그 결정서의 주문에 제3항에 기재된 사항을 기재함으로써 물건양도허부의 결정서에 갈음할 수 있다.', 5171);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9034, '①검사의 인도구속영장의 청구는 다음 각호의 사항을 기재한 서면에 의하여 이를 하여야 한다.', 5173);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9035, '②제5조제2항 및 제3항의 규정은 제1항의 경우에 이를 준용한다.', 5173);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9036, '①검사는 인도구속영장을 청구함에 있어서 인도구속영장발부의 요건이 존재함을 소명하는 자료를 제출하여야 한다.', 5174);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9037, '②인도구속영장이 청구된 범죄인 및 그 범죄인과 법 제22조제1항이 규정한 관계에 있는 자는 판사에게 범죄인을 위하여 유리한 자료를 제출할 수 있다.', 5174);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9038, '①판사는 다음 각호의 경우에는 인도구속영장의 청구를 기각하여야 한다.', 5175);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9039, '②제1항의 경우에 판사는 인도구속영장청구서의 여백에 기각의 취지와 이유의 요지를 기재하고 서명날인하여야 한다.', 5175);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9040, '①인도구속영장에는 법 제19조제3항이 규정한 사항외에 다음 각호의 사항을 기재하여야 한다.', 5176);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9041, '②제5조제2항 및 제3항은 제1항의 경우에 이를 준용한다.', 5176);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9042, '①판사는 검사의 청구에 의하여 필요하다고 인정하는 경우에 수통의 인도구속영장을 발부할 수 있다.', 5177);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9043, '②제1항의 경우에는 그 사유를 인도구속영장에 기재하여야 한다.', 5177);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9044, null, 5179);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9045, '① 법원이 법 제9조제3항에 따라 법 제9조제1항제3호의2, 제4호의 잠정조치 결정, 다른 종류의 잠정조치를 위 각 호의 잠정조치로 변경하는 결정 또는 법 제9조제1항제3호의2의 잠정조치에 대한 기간연장 결정을 하기 전 필요하다고 인정하여 검사, 스토킹행위자, 피해자, 기타 참고인(이하 "관계인"이라 한다)의 의견을 듣고자 하는 경우에는 심문기일을 지정하여 관계인의 의견을 듣는 방법으로 한다. 다만, 피해자에 대한 위해 우려 등 특별한 사정이 있는 경우에는 관계인에게 의견을 기재한 서면을 제출하게 하는 방법으로 할 수 있다.', 5186);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9046, '② 법원은 제1항 본문의 방법으로 관계인의 의견을 듣기로 결정하는 경우 해당 관계인 및 검사에게 심문기일을 서면 이외에 구술ㆍ전화ㆍ모사전송ㆍ전자우편ㆍ휴대전화 문자전송 그 밖에 적당한 방법으로 신속하게 통지하여야 한다. 이 경우 통지의 증명은 그 취지를 심문조서에 기재함으로써 할 수 있다.', 5186);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9047, '③ 검사는 제1항 본문의 심문기일에 출석하여 의견을 진술할 수 있다.', 5186);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9048, '④ 제1항 본문에 따라 의견을 들은 경우 심문기일에 참여한 법원사무관 등은 심문조서를 작성한다. 심문조서에는 관계인의 진술 요지를 기재한다.', 5186);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9049, '⑤ 법원은 필요하다고 인정하는 때에는 비디오 등 중계장치에 의한 중계시설을 통하거나 인터넷 화상장치를 이용하여 제1항 본문의 심문기일을 열 수 있다. 위 심문기일의 절차와 방법 등에 관하여는 그 성질에 반하지 아니하는 한 「형사소송규칙」제123조의13을 준용한다.', 5186);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9050, '① 이 법에서 "5ㆍ18민주화운동"이란 1979년 12월 12일과 1980년 5월 18일을 전후하여 발생한 헌정질서 파괴범죄와 반인도적 범죄에 대항하여 시민들이 전개한 민주화운동을 말한다.', 5190);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9051, '② 이 법에서 "반인도적 범죄"란 제1항에 따른 기간 동안 국가 또는 단체ㆍ기관(이에 속한 사람을 포함한다)의 민간인에 대한 살해, 상해, 감금, 고문, 강간, 강제추행, 폭행을 말한다.', 5190);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9052, '① 제2조의 죄에 대하여 고소 또는 고발을 한 자가 검사 또는 군검사로부터 공소를 제기하지 아니한다는 통지를 받은 경우에는 그 검사 소속의 고등검찰청이나 그 군검사 소속의 고등검찰부에 대응하는 고등법원에 그 당부(當否)에 관한 재정(裁定)을 신청할 수 있다. 법률 제5029호 5ㆍ18민주화운동등에관한특별법 시행 전에 제2조의 죄에 대하여 공소를 제기하지 아니하기로 결정된 사건의 경우에도 또한 같다. <개정 2016.1.6, 2021.9.24>', 5192);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9053, '② 제1항의 재정신청에 관하여는 「형사소송법」 또는 「군사법원법」의 해당 규정을 적용한다.', 5192);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9054, '① 5ㆍ18민주화운동과 관련된 행위 또는 제2조의 범행을 저지하거나 반대한 행위로 유죄의 확정판결을 선고받은 자는 「형사소송법」 제420조 및 「군사법원법」 제469조에도 불구하고 재심(再審)을 청구할 수 있다.', 5193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9055, '② 재심의 청구는 원판결의 법원이 관할한다. 다만, 「군형법」을 적용받지 아니한 자에 대한 원판결의 법원이 군법회의 또는 군사법원인 경우에는 그 심급(審級)에 따른 주소지의 법원이 관할한다.', 5193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9056, '③ 재심의 관할법원은 제2조의 죄를 범한 자가 그 죄로 유죄를 선고받고 그 형(刑)이 확정된 사실에 대하여 직권으로 조사하여야 한다.', 5193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9057, '④ 제1항의 재심 청구인이 사면을 받았거나 형이 실효(失效)된 경우 재심 관할법원은 「형사소송법」 제326조부터 제328조까지 및 「군사법원법」 제381조부터 제383조까지의 규정에도 불구하고 종국적(終局的) 실체판결(實體判決)을 하여야 한다.', 5193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9058, '⑤ 제1항의 재심에 관한 절차는 그 재심의 성격에 저촉되지 아니하는 범위에서 「형사소송법」과 「군사법원법」의 해당 조항을 적용한다.', 5193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9059, '① 다음 각 호의 어느 하나에 해당하는 방법으로 5ㆍ18민주화운동에 대한 허위의 사실을 유포한 자는 5년 이하의 징역 또는 5천만원 이하의 벌금에 처한다.', 5197);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9060, '② 제1항의 행위가 예술ㆍ학문, 연구ㆍ학설, 시사사건이나 역사의 진행과정에 관한 보도를 위한 것이거나 그 밖에 이와 유사한 목적을 위한 경우에는 처벌하지 아니한다.', 5197);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9061, null, 5199);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9062, '①영 제6조제1항의 규정에 의한 보안관찰처분대상자 신고서는 별지 제3호서식에 의한다.', 5202);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9063, '②영 제6조제1항의 교도소등의 장(이하 "교도소등의 장"이라 한다)은 동조동항의 규정에 의하여 제출받은 신고서 중 1부를 국가안전기획부장에게 송부하고 1부는 보존하며, 별지 제4호서식의 신고서 송부부를 작성ㆍ비치하여야 한다.', 5202);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9064, '③교도소등의 장은 제2항 및 영 제6조제2항의 규정에 의하여 신고서를 송부하는 때에는 특별한 사유가 있는 경우를 제외하고는 보안관찰처분대상자의 출소예정일  2월전까지 이를 송부하여야 한다.', 5202);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9065, '④영 제6조제2항의 규정에 의하여 신고서를 송부받은 거주예정지 관할경찰서장은 보안관찰처분대상자가 출소 후 거주예정지에 거주하지 아니할 것이 명백한 때에는 지체없이 그 사유를 교도소등의 장에게 통보하여야 한다.', 5202);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9066, '⑤제4항의 규정에 의한 통보를 받은 교도소등의 장은 지체없이 이를 교도소등의 소재지 관할검사에게 보고하여야 한다.', 5202);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9067, '⑥영 제6조제2항의 규정에 의하여 신고서를 송부받은 거주예정지 관할경찰서장은  별지 제5호서식의 신고서 접수부와 별지 제6호서식의 보안관찰처분대상자 관리부를 작성ㆍ비치하여야 한다.', 5202);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9068, '⑦영 제6조제2항의 규정에 의한 보안관찰처분대상자신고서의 송부는 별지 제7호서식에 의한다.', 5202);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9069, '①거주예정지 관할경찰서장은 영 제8조제1항의 규정에 의한 출소통보를 받거나 영 제8조제2항의 규정에 의한 보고를 한 때에는 보안관찰처분대상자 관리부에 그 내용을 기재하여야 한다.', 5203);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9070, '②영 제8조제1항의 규정에 의한 출소통보는 별지 제8호서식, 영 제8조제2항의 규정에 의한 보고는 별지 제9호서식에 의한다.', 5203);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9071, '①거주예정지 관할경찰서장 또는 관할경찰서장은 영 제9조제1항의 규정에 의한 신고사항과 영 제9조제2항의 규정에 의한 신고사항을 보안관찰처분대상자 관리부에 기재하여야 한다.', 5204);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9072, '②영 제9조제1항의 규정에 의한 신고서는 별지 제10호서식, 영 제9조제2항의 규정에 의한 신고서는 별지 제11호서식, 영 제9조제3항의 규정에 의한 신고필증은 별지 제12호서식, 영 제9조제3항 및 제5항의 규정에 의한 보고는 별지 제9호서식에 의한다.', 5204);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9073, '①교도소등의 장은 보안관찰처분대상자가 입소한 때에는 별지 제13호서식의 보안관찰처분대상자 관리부를 작성ㆍ비치하여야 한다.', 5205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9074, '②교도소등의 장은 보안관찰처분대상자 관리부에 영 제10조제1항의 규정에 의한 통고서송부사실과 영 제10조제2항의 규정에 의한 통보사유를 기재하여야 한다.', 5205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9075, '③교도소등의 장은 보안관찰처분대상자에 대하여 영 제10조제2항제4호의 사유가 발생한 때에는 보안관찰처분대상자 관리부와 관계서류를 이송된 교도소등의 장에게 송부하여야 한다.', 5205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9076, '④영 제10조 제1항의 규정에 의한 통고서는 별지 제14호서식, 영 제10조제2항의 규정에 의한 통보는 별지 제15호서식에 의한다.', 5205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9077, '①관할경찰서장은 그 관할구역내에 거주하는 보안관찰처분대상자에게 영 제11조 각호의1에 해당하는 사유가 발생한 때에는 보안관찰처분대상자관리부에 그 내용을 기재하여야 한다.', 5206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9078, '②영 제11조의 규정에 의한 보고는 별지 제9호서식에 의한다.', 5206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9079, '①검사는 직무를 수행함에 있어 상호 협조하여야 한다.', 5209);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9080, '②사법경찰관리는 직무를 수행함에 있어 상호 협조하여야 한다.', 5209);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9081, '①조사서류를 작성할 때에는 내용의 정확과 진술의 임의성을 확보하기 위하여 특히 다음 각호의 사항에 유의하여야 한다.', 5212);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9082, '②조사서류의 작성에 관하여는 이 규칙에서 규정한 사항외에 형사소송법 제47조ㆍ제48조ㆍ제50조와 제57조 내지 제59조의 규정을 준용한다.', 5212);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9083, '①검사는 보안관찰처분대상자가 보안관찰해당범죄를 다시 범할 위험성이 있다고 의심하여 조사에 착수하는 때에는 사안인지서를 작성하여야 한다.', 5214);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9084, '②사법경찰관이 제1항의 조사에 착수하고자 하는 때에는 사안인지승인신청서를 작성하여 검사의 승인을 얻어야 한다.', 5214);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9085, '③제1항의 규정에 의한 사안인지서와 제2항의 규정에 의한 사안인지승인신청서에는 용의자의 주거ㆍ성명ㆍ연령ㆍ직업ㆍ주민등록번호, 보안관찰해당범죄사실, 전향여부, 보안관찰해당범죄를 다시 범할 위험성이 있다고 의심되는 사실 기타 필요한 사항을 기재하고 특히 조사의 단서 및 인지하게 된 경위를 상세히 기재하여야 한다.', 5214);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9086, '①검사 또는 사법경찰관리는 용의자 또는 참고인에 대하여 출석을 요구하는 때에는 출석요구서를 발부하여야 한다. 다만, 긴급을 요하는 때에는 전화 또는 구두로 출석을 요구할 수 있다.', 5215);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9087, '②제1항의 출석요구서에는 출석일시ㆍ장소 및 출석요구의 취지를 명백히 기재하여야 한다.', 5215);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9088, '③용의자 또는 참고인이 출석한 때에는 지체없이 진술을 들어야 하며 장시간 대기시키는 일이 없도록 하여야 한다.', 5215);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9089, '④외국인을 조사할 때에는 국제법과 국제조약에 위배되는 일이 없도록 유의하여야 한다.', 5215);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9090, null, 5216);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9091, '①검사 또는 사법경찰관리는 참고인의 진술을 들을 때에는 형사소송법 제317조의 규정에 유의하여 진술을 강요하여서는 아니된다.', 5217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9092, '②참고인의 진술은 조서에 기재하여야 한다.', 5217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9093, '③진술내용이 복잡하거나 참고인이 서면진술을 원하는 때에는 참고인으로 하여금 진술서를 작성ㆍ제출하게 할 수 있다.', 5217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9094, '④제3항의 규정에 의하여 진술서를 작성하는 때에는 부득이한 경우를 제외하고는 참고인이 자필로 작성하도록 하여야 한다.', 5217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9095, '①용의자 또는 관계인으로부터 자료를 제출받아 이를 보관하여야 할 필요가 있는 때에는 보관조서 및 보관물목록을 작성하여야 한다. 다만, 조사 중에 자료를 제출 받은 때에는 조서에 보관의 취지를 기재하여 보관조서에 갈음할 수 있다.', 5219);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9096, '②보관조서에는 사안번호ㆍ제출자ㆍ소유자 및 보관경위를, 보관물목록에는 보관물의 순위ㆍ품명ㆍ수량ㆍ특징을 구체적으로 기재하여야 한다.', 5219);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9097, '①보관물을 다른 사람에게 보관시킬 때에는 보관증을 받아야 하며, 보관자의 선정에 유의하여 그로 하여금 보관물을 성실하게 보관하도록 하여야 한다.', 5220);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9098, '②보관물에 대하여는 사안번호ㆍ용의자의 성명ㆍ보관물목록의 순위ㆍ번호를 기재한 표찰을 붙여야 한다.', 5220);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9099, '③보관물을 보관할 필요가 없는 때에는 지체없이 이를 제출자에게 반환하여야 한다.', 5220);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9100, '④보관물을 폐기하는 때에는 폐기조서와 폐기물목록을 작성하고 사진을 촬영하여 이에 첨부하여야 한다.', 5220);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9101, '①소년인 용의자를 조사하는 때에는 소년의 심리적 특성을 충분히 고려하여 조용한 장소에서 온정과 이해를 가지고 부드러운 어조로 조사에 임하여야 한다.', 5221);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9102, '②소년용의자에 대한 사안은 신속히 처리하고, 소년의 주거ㆍ성명ㆍ직업ㆍ용모등에 의하여  당해본인임을 알 수 있는 정도의 사실이나 사진이 보도되지 아니하도록 유의하여야 한다.', 5221);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9103, '①소년인 용의자를 조사하는 때에는 환경조사서를 작성하여야 한다.', 5222);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9104, '②제1항의 규정에 의한 환경조사서에는 소년의 성격ㆍ행장ㆍ경력ㆍ교육정도ㆍ가정상황ㆍ교우관계 기타 환경등을 상세히 기재하여야 한다.', 5222);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9105, '③소년인 용의자의 심신에 이상이 있다고 인정되는 때에는 지체없이 의사로 하여금 진단하게 하고 그 진단결과를 기재한 서류를 첨부하여야 한다.', 5222);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9106, '①사법경찰관리는 조사를 종결한 때에는 지체없이 사안을 관할검사장에게 송치하여야 한다.', 5224);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9107, '②사법경찰관리는 사안을 송치하는 때에는 소속관서의 장의 명의로 하여야 한다.', 5224);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9108, '①제27조제1항의 규정에 의하여 사안을 송치하는 때에는 사안송치서ㆍ보관물 총목록ㆍ기록목록ㆍ의견서ㆍ용의자 환경조사서ㆍ용의자의 본적조회 회답서 및 전과관계를 증명할 수 있는 서류 기타 필요한 서류를 첨부하여야 한다.', 5225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9109, '②송치서류는 다음의 순서에 따라 편철하여야 한다.', 5225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9110, '③제2항제4호의 의견서는 사법경찰관이 작성하여야 한다.', 5225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9111, '④제2항제5호의 기타 서류는 접수 또는 작성한 순서에 따라 편철하고, 제4호ㆍ제5호의 서류에는 매면에 면수를 기입하며, 제2호 내지 제4호의 서류에는 송치인이 직접 간인하여야 한다.', 5225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9112, '⑤사법경찰관리는 사안송치 후 용의자에 대하여 다른 보안관찰해당범죄경력을 발견한 때에는 즉시 그 사안을 담당하는 검사(이하 "주임검사"라 한다)에게 보고하여야 한다.', 5225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9113, '①사법경찰관리는 사안송치 후 조사를 계속하고자 하는 때에는 미리 주임검사의 지휘를 받아야 한다.', 5227);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9114, '②사법경찰관리는 사안송치 후 당해사안에 속하는 용의자의 다른 재범의 위험성을 발견한 때에는 즉시 주임검사에게 보고하고 그 지휘를 받아야 한다.', 5227);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9115, '①검사는 사안의 조사를 종결한 때에는 법무부장관에게 보안관찰처분 청구를 하여야 한다. 다만, 보안관찰처분 청구의 필요가 없다고 인정하는 경우에는 그 청구를 하지 아니하는 조치를 할 수 있다.', 5228);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9116, '②제1항의 규정에 의한 청구를 하는 때에는 검찰총장을 경유하여야 한다. 다만, 검찰총장이 경유하지 아니하도록 한 사안은 그러하지 아니하다.', 5228);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9117, '③제1항 단서의 조치를 하는 경우에는 조사의 결과 및 보안관찰처분 청구를 하지 아니하는 이유를 기재하여야 한다.', 5228);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9118, null, 5229);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9119, '①검사는 보안관찰처분 기간갱신사안(이하 "기간생갱신사안"이라 한다)을 처리하는 때에는 관할경찰서장으로 하여금 피보안관찰자에 대하여 직업ㆍ월수입ㆍ가정환경ㆍ사회활동상황 기타 기간갱신여부를 판단할 수 있는 사항을 기재한 피보안관찰자 동태조사서와 보안관찰부등본을 제출하게하여야 한다.', 5230);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9120, '②검사는 제1항의 규정에 의한 기간갱신사안을 처리함에 있어서는 관할경찰서장으로 하여금 1개월이내의 기간을 정하여 조사하게 할 수 있다.', 5230);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9121, '③검사는 기간갱신사안의 조사를 종결한 때에는 보안관찰처분의 기간만료 2월 전까지 법무부장관에게 보안관찰처분 기간갱신을 청구하여야 한다. 다만, 기간갱신 청구의 필요가 없다고 인정하는 경우에는 그 청구를 하지 아니하는 조치를 할 수 있다.', 5230);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9122, '①검사가 조사에 관하여 사용하는 문서와 장부는 별지 제18호서식 내지 별지 제22호서식에 의한다.', 5232);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9123, '②사법경찰관리가 조사에 관하여 사용하는 문서와 장부는 별지 제23호서식 내지 별지 제29호서식에 의한다.', 5232);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9124, '③검사와 사법경찰관리가 조사에 관하여 공통으로 사용하는 문서와 장부는 별지 제30호서식 내지 별지 제40호서식에 의한다.', 5232);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9125, '①관할경찰서장은 영 제14조제1항의 규정에 의하여 보안관찰처분면제결정 신청서를 접수한 때에는 신청인의 진술을 듣고 재범의 위험성 유무와 신청인이 제출한 서류의 사실여부 및 신청인의 전과관계등을 조사하여야 한다.', 5233);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9126, '②검사는 영 제14조제2항의 규정에 의하여 보안관찰처분면제결정 신청서와 관계서류를 송부받은 때에는 필요하다고 인정하는 경우 제1항의 조사를 할 수 있다.', 5233);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9127, '③검사는 법 제11조 제3항의 규정에 의하여 보안관찰처분면제결정 청구를 하는 때에는 법 제11조제1항제1호 및 제2호에 해당하는 지의 여부와 기타 필요한 자료를 조사하여야 한다.', 5233);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9128, '④영 제14조제1항의 규정에 의한 보안관찰처분면제결정 신청서는 별지 제41호서식, 영 제14조제2항의 규정에 의한 보안관찰처분면제결정 신청서의 송부 및 의견서는 별지 제42호서식 및 별지 제43호서식, 영 제14조제3항의 규정에 의한 보안관찰처분면제결정 신청서의 송부 및 의견서는 별지 제44호서식 및 별지 제43호서식, 영 제14조제5항의 규정에 의한 보안관찰처분면제결정 청구서 및 의견서는 별지 제16호서식 및 별지 제17호서식에 의한다. <개정 2019.10.8>', 5233);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9129, '①법무부장관이 영 제15조제1항의 규정에 의하여 사안을 위원회에 회부하는 때에는 법 제10조제2항의 규정에 의하여 조사의 명을 받은 공무원의 의견을 첨부할 수 있다.', 5234);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9130, '②법무부장관이 위원회에 2건이상의 사안을 동시에 회부하는 때에는 1부의 회부서에 의할 수 있다.', 5234);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9131, '③위원회가 동시에 2건이상의 의결결과를 통보하는 때에는 1부의 통보서에 의할 수 있다.', 5234);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9132, '①검사는 법무부장관으로부터 보안관찰처분결정서를 송달받은 때에는 지체없이 그 결정내용 및 일자를 관할경찰서장에게  통보하여야 한다.', 5235);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9133, '②영 제21조의 규정에 의한 보안관찰처분에 관한 결정서등본의 송달은 피청구자 또는 신청인으로부터 수령서를 받고 검사가 직접 교부하거나 사법경찰관리로 하여금 교부하게 할 수 있다.', 5235);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9134, '③제2항의 수령서는 사안기록에 편철하여야 한다.', 5235);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9135, '④제1항의 규정에 의한 통보는 별지 제20호서식, 제2항의 규정에 의한 수령서는 별지 제45호서식에 의한다.', 5235);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9136, '①법 제17조제1항의 규정에 의한 보안관찰처분의 집행지휘는 별지 제46호서식에 의한다.', 5236);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9137, '②검사가 제1항의 집행지휘를 하는 때에는 별지 제47호서식의 집행원부를 작성ㆍ비치하여야 한다.', 5236);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9138, '①검사는 법 제17조제3항 전단의 규정에 의하여 보안관찰처분 집행중지결정을 하는 때에는 피보안관찰자의 가족 및 신원보증인 기타 관계인의 진술을 듣거나 필요한 조사를 하여야 한다.', 5237);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9139, '②검사는 법 제17조제3항 후단의 규정에 의하여 보안관찰처분 집행중지결정을 취소하는 때에는 집행중지결정을 받은 피보안관찰자ㆍ가족ㆍ신원보증인 기타  관계인의 진술을 듣거나 필요한 조사를 하여야 한다.', 5237);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9140, '③영 제23조제6항 전단의 규정에 의한 고지는 검사가 신청인에게 보안관찰처분집행중지취소결정서등본을 직접 교부하거나 사법경찰관리로 하여금 교부하게 할 수 있다.', 5237);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9141, '④영 제23조제1항의 규정에 의한 보안관찰처분집행중지결정 신청은 별지 제48호서식, 영 제23조제2항의 규정에 의한 보안관찰처분집행중지 결정서는 별지 제49호서식, 영 제23조제3항의 규정에 의한 보안관찰처분집행중지 결정의 집행지휘는 별지 제50호서식, 영 제23조제4항의 규정에 의한 보안관찰처분집행중지 취소결정서는 별지 제51호서식, 영 제23조제5항의 규정에 의한 보안관찰처분집행중지결정취소신청은 별지 제52호서식, 영 제23조제7항의 규정에 의한 보안관찰처분집행중지 취소지휘 및 잔기간 집행지휘는 별지 제53호서식에 의한다.', 5237);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9142, '①피보안관찰자가 법 제18조제1항 내지 제4항의 규정에 의한 신고를 하는 때에는 신고서 1부를 작성하여 주거지를 관할하는 지서 또는 파출소의 장(이하 "지ㆍ파출소장"이라 한다)에게 제출하여야 한다.', 5238);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9143, '②제1항의 규정에 의한 신고서를 접수한 지ㆍ파출소장은 신고서 1부를 사본하여 원본은 관할경찰서장에게 송부하고 사본은 보존한다.', 5238);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9144, '③제1항 및 제2항의 규정에 의하여 신고서를 접수한 지ㆍ파출소장 및 관할경찰서장은 별지 제5호서식의 신고서 접수부를 작성ㆍ비치하여야 한다.', 5238);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9145, '④관할경찰서장은 법 제18조제2항 내지 제4항의 신고사실을 보안관찰부에 기재하여야 한다.', 5238);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9146, '⑤법 제18조제1항의 규정에 의한 신고는 별지 제54호서식, 법 제18조제2항의 규정에 의한 신고는 별지 제55호서식, 법 제18조제3항의 규정에 의한 신고는 별지 제56호서식, 법 제18조제4항 및 영 제24조제2항의 규정에 의한 신고서는 별지 제57호서식, 법 제18조제5항의 규정에 의한 신고필증은 별지 제12호서식, 영 제24조제5항의 규정에 의한 보고는 별지 제2호서식에 의한다.', 5238);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9147, '①영 제24조제3항의 규정에 의하여 여행사실의 통보를 받은 여행목적지 관할경찰서장은 피보안관찰자의 도착여부를 확인한 후 지체없이 이를 관할경찰서장에게 통보하여야 한다.', 5239);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9148, '②여행목적지 관할경찰서장은 피보안관찰자가 그 관할지역이 속하는 특별시ㆍ직할시ㆍ시 또는 군에 체재하는 동안 그 동태를 관찰하고 피보안관찰자에게 다음 각호의 1에 해당하는 사유가 발생한 때에는 지체없이 이를 관할경찰서장에게 통보하여야 한다.', 5239);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9149, '①영 제25조제2항의 규정에 의하여 피보안관찰자에게 교부하는 서면은 별지 제58호서식에 의한다.', 5240);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9150, '②영 제25조제3항의 규정에 의한 보고는 별지 제59호서식에 의하되, 조치를 필요로 하는 사유와 조치할 사항을 구체적으로 기재하여야 한다. 긴급을 요하여 미리 조치를 한 후 보고하는 때에도 또한 같다.', 5240);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9151, '①검사는 영 제26조제2항의 규정에 의한 거소제공대상자에게 거소제공의 필요가 있다고 인정하는 때에는 출소예정일 1월전까지 법무부장관에게 거소제공의 청구를 하여야 한다.', 5241);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9152, '②검사는 영 제26조제3항의 규정에 의한 거소제공대상자에게 거소제공의 필요가 있다고 인정하는 때에는 거소제공청구의 신청을 받은 날부터 20일이내에 법무부장관에게 거소제공의 청구를 하여야 한다.', 5241);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9153, '③검사가 거소제공의 청구를 하는 때에는 별지 제60호서식의 거소제공대상자 관리부를 작성ㆍ비치하여야 한다.', 5241);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9154, '④검사가 영 제26조제8항의 규정에 의하여 거소제공결정서등본을 송달하는 때에는 거소제공대상자에게 직접 교부하거나 교도소등의 장 또는 사법경찰관리로 하여금 교부하게 할 수 있다.', 5241);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9155, '⑤영 제26조제4항의 규정에 의한 신청서는 별지 제61호서식, 영 제26조제5항의 규정에 의한 청구서는 별지 제62호서식, 영 제26조제7항의 규정에 의한 통보는 별지 제20호서식에 의한다.', 5241);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9156, '①검사는 영 제27조제3항의 규정에 의하여 거소변경신청서를 송부하거나 영 제27조제4항의 규정에 의하여 거소변경청구를 하는 때에는 거소제공대상자 관리부에 그 사실을 기재하여야 한다.', 5242);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9157, '②영 제27조제1항의 규정에 의한 신청서는 별지 제63호서식, 영 제27조제2항의 규정에 의한 송부 및 의견서는 별지 제64호서식 및 별지 제43호서식, 영 제27조제3항의 규정에 의한 송부 및 의견서는 별지 제65호서식 및 별지 제43호서식, 영 제27조제4항의 규정에 의한 거소변경청구서는 별지 제66호서식에 의한다.', 5242);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9158, '①조사 사무를 처리하는 관서의 장은 다음의 장부 및 서류를 비치하여야 한다.', 5246);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9159, '②제1항제1호의 보안관찰처분사안 접수ㆍ처리부는 미리 매면마다 관할검사장의 간인을 받아야 한다.', 5246);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9160, '③제1항제8호의 조사관계 예규철에는 검찰청 기타 감독관청이 발한 훈련ㆍ통첩ㆍ지시등 관계서류를 편철하여야 한다.', 5246);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9161, '④제1항제9호의 조사종결사안(송치사안)철에는 검사에게 송치한 사한송치서, 기록목록 및 의견서의 사본을 편철하여야 한다.', 5246);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9162, '⑤제1항제10호의 조사미제사안기록철에는 장차 소재를 파악할 가망이 없는 보안관찰처분대상자에 대한 사안등의 기록을 편철하여야 한다.', 5246);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9163, '⑥제1항제11호의 통계철에는 조사업무와 관련한 각종 통계서류를 편철하여야 한다.', 5246);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9164, '⑦제1항제12호의 처분결과통보서철에는 검사의 보안관찰처분에 관한 청구여부 및 그에 대한 법무부장관의 결정에 관한 통보서를 편철하여야 한다.', 5246);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9165, '⑧제1항제13호의 잡서류철에는 제1항제8호 내지 제12호에 해당하지 아니하는 모든 서류를 편철하여야 한다.', 5246);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9166, '⑨제1항의 규정에 의한 관서의 장은 필요하다고 인정하는 때에는 제1항 각호의 장부 및 서류외에 필요한 장부 또는 서류철을 비치할 수 있다.', 5246);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9167, '①서류철에는 색인목록을 붙여야 한다.', 5247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9168, '②서류를 편철한 후 그 일부를 빼낸 때에는 색인목록 비고란에 그 연월일 및 사유를 기재하고 담당검사 또는 사법경찰관이 날인하여야 한다.', 5247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9169, '①조사사무에 관한 장부 및 서류철은 매년 이를 갱신하여야 한다. 다만, 필요에 따라 계속 사용할 수 있다.', 5248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9170, '②제1항 단서의 경우에는 분개지등을 삽입하여 그 연도를 분명히 구분하여야 한다.', 5248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9171, null, 5249);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9172, '①보존기간은 사안처리를 완결하거나 사안처리의 최종절차를 마친 다음해 1월 1일부터 기산한다.', 5250);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9173, '②보존기간이 경과한 장부 및 서류철은 폐기목록을 작성한 후 폐기하여야 한다.', 5250);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9174, '①사안기록과 결정서는 보안관찰처분대상자의 주거지를 관할하는 검찰청에서 보관ㆍ보존한다.', 5251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9175, '②보안관찰처분대상자가 제1항의 규정에 의한 검찰청의 관할구역외로 주거지를 이전한 때에는 보안관찰처분대상자신고서와 사안기록 및 결정서 기타 관계서류를 신주거지를 관할하는 검찰청에 이송하여야 한다.', 5251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9176, '③제2항의 규정에 의한 이송은 별지 제69호서식에 의하며, 이 경우 별지 제70호서식의 이송결정서를 작성하여야 한다.', 5251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9177, '④제2항의 규정에 의하여 보안관찰처분대상자신고서등을 접수한 검찰청은 이송한 검찰청에 별지 제71호서식에 의한 접수통지를 하여야 한다.', 5251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9178, null, 5253);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9179, '① 형사사법업무 처리기관은 형사사법절차의 전자화에 필요한 제도 개선과 이를 반영할 수 있는 시스템 개발을 위하여 노력하여야 한다.', 5254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9180, '② 형사사법업무 처리기관은 형사사법절차의 전자화를 위하여 시스템의 유통표준을 준수하고 시스템이 안정적으로 운영될 수 있도록 협력하여야 한다.', 5254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9181, null, 5255);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9182, '① 형사사법업무 처리기관은 판결문, 공소장, 영장, 조서 등 형사사법업무와 관련된 문서를 시스템을 이용하여 저장ㆍ보관하여야 한다. 다만, 업무의 성격상 시스템을 이용하는 것이 곤란한 경우에는 법무부, 검찰청, 경찰청, 해양경찰청 및 고위공직자범죄수사처의 업무에 관하여는 대통령령으로, 법원의 업무에 관하여는 대법원규칙으로 예외를 정할 수 있다. <개정 2014.3.18, 2014.11.19, 2017.7.26, 2021.12.28>', 5256);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9183, '② 형사사법업무 처리기관은 제1항의 문서를 작성하거나 활용할 때 시스템에서 정하는 형사사법정보의 유통표준에 따라야 한다.', 5256);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9184, '③ 형사사법업무 처리기관은 형사사법정보를 생성하거나 유통할 때에는 그 형사사법정보의 정확성을 유지하여야 한다.', 5256);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9185, '① 형사사법업무 처리기관은 형사사법정보가 시스템을 통하여 공동 활용되고 신속히 유통되도록 노력하여야 한다.', 5257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9186, '② 형사사법업무 처리기관은 형사사법업무를 신속하고 정확하게 처리하기 위하여 필요하면 제9조에 따른 형사사법정보체계 협의회가 정한 형사사법정보를 시스템을 통하여 다른 형사사법업무 처리기관에 제공할 수 있다.', 5257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9187, '③ 형사사법업무 처리기관은 형사사법업무 처리 외의 목적으로 형사사법정보를 수집ㆍ저장 또는 이용할 수 없다.', 5257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9188, '① 시스템의 운영ㆍ관리는 이를 사용하는 각 형사사법업무 처리기관이 한다. 다만, 형사사법포털 및 각 형사사법업무 처리기관이 운영ㆍ관리하는 시스템을 연계ㆍ지원하는 공통시스템은 법무부에 운영기구를 두어 운영ㆍ관리한다.', 5259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9189, '② 제1항의 운영기구의 조직과 운영 등에 필요한 사항은 대통령령으로 정한다.', 5259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9190, '③ 각 형사사법업무 처리기관은 시스템의 안정적인 운영과 관리를 위하여 필요하다고 인정하면 시스템의 유지ㆍ보수 등 지원업무의 일부를 다른 국가기관 또는 정보화를 지원하는 법인에 위탁할 수 있다.', 5259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9191, '① 협의회는 법무부차관, 법원행정처 차장, 대검찰청 차장검사, 경찰청 차장, 해양경찰청 차장 및 고위공직자범죄수사처 차장으로 구성한다. <개정 2014.3.18, 2014.11.19, 2017.7.26, 2021.12.28>', 5261);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9192, '② 협의회의 위원장은 위원 중에서 호선(互選)한다.', 5261);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9193, '① 협의회의 정기회의는 반기(半期)에 1회 개최한다.', 5262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9194, '② 협의회에서 협의할 사항이 있으면 각 위원은 위원장에게 임시협의회 개최를 요구할 수 있다.', 5262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9195, '③ 협의회의 협의와 조정은 위원 전원의 합의에 의하여 한다.', 5262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9196, '④ 협의회는 제12조제1항 각 호의 사항 중 대한변호사협회의 소관 사무와 관련되는 내용이 있는 때에는 대한변호사협회의 의견을 들어야 한다.', 5262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9197, '⑤ 제1항부터 제4항까지에서 규정한 사항 외에 협의회의 운영 등에 필요한 사항은 대통령령으로 정한다.', 5262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9198, '① 협의회는 다음 각 호의 사항에 대하여 협의ㆍ조정한다.', 5263);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9199, '② 협의회의 운영에는 각 형사사법업무 처리기관의 시스템 운영상의 독립성이 존중되어야 한다.', 5263);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9200, '① 협의회의 업무를 효율적으로 지원하기 위하여 협의회에 형사사법정보체계 실무협의회(이하 "실무협의회"라 한다)를 둔다.', 5264);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9201, '② 실무협의회는 협의회의 회의에 부칠 의안(議案)을 미리 검토ㆍ조정하며, 협의회로부터 위임받은 사항을 처리한다.', 5264);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9202, '③ 실무협의회는 협의회의 각 위원이 지명하는 사람으로 구성한다.', 5264);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9203, '④ 제1항부터 제3항까지에서 규정한 사항 외에 실무협의회의 운영 등에 필요한 사항은 대통령령으로 정한다.', 5264);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9204, '① 형사사법업무 처리기관은 형사사법업무를 처리할 때 형사사법정보가 분실, 도난, 유출, 변조 또는 훼손되지 아니하도록 안전성 확보에 필요한 조치를 하여야 한다.', 5265);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9205, '② 형사사법업무에 종사하는 사람 또는 제8조제3항에 따라 시스템의 지원업무를 위탁받아 그 업무에 종사하는 사람은 권한 없이 다른 기관 또는 다른 사람이 관리하는 형사사법정보를 열람, 복사 또는 전송하여서는 아니 된다.', 5265);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9206, '③ 형사사법업무에 종사하거나 종사하였던 사람 또는 제8조제3항에 따라 시스템의 지원업무를 위탁받아 그 업무에 종사하거나 종사하였던 사람은 직무상 알게 된 형사사법정보를 누설하거나 권한 없이 처리하거나 타인이 이용하도록 제공하는 등 부당한 목적으로 사용하여서는 아니 된다.', 5265);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9207, '① 형사사법업무 처리기관의 업무를 방해할 목적으로 형사사법정보를 위작(僞作) 또는 변작(變作)하거나 말소한 사람은 10년 이하의 징역에 처한다.', 5266);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9208, '② 제14조제3항을 위반하여 형사사법정보를 누설하거나 권한 없이 처리하거나 타인이 이용하도록 제공하는 등 부당한 목적으로 사용한 사람은 5년 이하의 징역 또는 5천만원 이하의 벌금에 처한다.', 5266);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9209, '③ 제14조제2항을 위반하여 권한 없이 다른 기관 또는 다른 사람이 관리하는 형사사법정보를 열람, 복사 또는 전송한 사람은 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.', 5266);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9210, null, 5271);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9211, '① 형사사법업무 처리기관은 법 제5조제2항에 따른 형사사법정보의 유통표준을 정할 때 다음 각 호의 사항을 준수하여야 한다.', 5272);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9212, '② 전자문서 출력물의 간인(間印)은 면수 및 총면수를 표시하는 방법으로 한다.', 5272);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9213, null, 5273);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9214, '① 법 제8조제1항 단서에 따라 형사사법정보공통시스템(이하 "공통시스템"이라 한다)을 운영ㆍ관리하기 위하여 법무부에 형사사법공통시스템 운영단(이하 "운영단"이라 한다)을 둔다.', 5275);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9215, '② 운영단은 법무부 소속 공무원과 형사사법업무 처리기관이나 관계 행정기관에서 파견된 공무원으로 구성한다.', 5275);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9216, '③ 법무부장관은 운영단을 운영하기 위하여 필요한 경우에는 다른 형사사법업무 처리기관이나 관계 행정기관에 소속 공무원의 파견을 요청할 수 있다.', 5275);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9217, '④ 운영단의 조직 및 정원에 관한 세부사항은 법무부령으로 정한다.', 5275);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9218, null, 5276);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9219, '① 운영단은 형사사법업무 처리기관이 형사사법업무를 처리하는 데에 지장이 없도록 공통시스템을 안정적으로 관리하여야 한다.', 5277);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9220, '② 운영단은 형사사법업무 처리기관의 시스템이 변경되어 공통시스템의 변경이 필요한 경우 적극 협조하여야 한다.', 5277);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9221, '① 운영단에 파견된 공무원의 보수는 원소속 기관에서 지급한다.', 5279);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9222, '② 운영단에 파견된 공무원에게는 예산의 범위에서 수당 및 여비, 그 밖에 필요한 경비를 지급할 수 있다.', 5279);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9223, '① 협의회 위원장(이하 "위원장"이라 한다)의 임기는 2년으로 한다.', 5280);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9224, '② 위원장은 동일한 형사사법업무 처리기관 소속 위원이 연임할 수 없다.', 5280);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9225, '③ 협의회에 간사 1명을 두며, 간사는 위원장이 속한 기관의 법 제13조에 따른 형사사법정보체계 실무협의회의 위원(이하 "실무협의회 주관위원"이라 한다)이 된다.', 5280);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9226, '① 법 제11조제1항에 따른 협의회의 정기회의는 특별한 사정이 없으면 매년 3월, 9월에 개최한다.', 5281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9227, '② 협의회의 각 위원은 서면으로 법 제11조제2항에 따른 임시협의회의 개최를 요구할 수 있다.', 5281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9228, '③ 제2항에 따른 요구가 있는 경우 위원장은 특별한 사유가 없으면 요구가 있은 날부터 14일 이내에 임시협의회를 개최하여야 한다.', 5281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9229, '④ 위원장이 정기회의 또는 임시협의회를 소집할 때에는 회의 개최 7일 전까지 회의 안건, 일시 및 장소를 각 위원에게 서면으로 알려야 한다.', 5281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9230, '⑤ 법 제11조제4항에 따라 대한변호사협회의 의견을 들어야 하는 경우 위원장은 회의 개최 7일 전까지 회의 안건, 일시 및 장소를 대한변호사협회에 통보하여 의견을 제출하도록 하여야 한다.', 5281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9231, '① 협의회는 업무를 수행하기 위하여 필요한 경우에는 전문적인 지식과 경험이 있는 관계 공무원 또는 전문가 등을 회의에 참석하게 하여 의견을 들을 수 있다.', 5282);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9232, '② 위원장은 필요하다고 인정하는 경우에는 협의회 위원 전원의 합의를 거쳐 회의를 비공개로 진행할 수 있다.', 5282);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9233, '③ 협의회 위원 전원이 합의한 내용은 회의록 외의 별도 서면으로 작성할 수 있다.', 5282);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9234, '① 협의회는 회의록을 작성하여 갖추어 두어야 한다.', 5283);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9235, '② 회의록은 협의회의 각 위원이 열람한 후 서명함으로써 확정된다.', 5283);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9236, '③ 위원장은 협의회의 각 위원에게 확정된 회의록 사본 1부씩을 내주어야 한다.', 5283);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9237, '④ 회의록은 위원장이 관리하며, 10년간 보존한다.', 5283);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9238, '① 실무협의회의 회의는 정기회의와 임시회의로 구분한다.', 5285);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9239, '② 실무협의회 정기회의는 특별한 사정이 없으면 매년 3월, 9월에 개최한다.', 5285);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9240, '③ 법 제11조제2항에 따른 임시협의회의 안건을 미리 검토ㆍ조정할 필요가 있는 경우 또는 실무협의회의 각 위원이 실무협의회 임시회의의 개최를 요구하는 경우에는 실무협의회 임시회의를 개최할 수 있다.', 5285);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9241, '④ 실무협의회의 회의는 실무협의회 주관위원이 주관한다.', 5285);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9242, '⑤ 실무협의회의 각 위원은 실무협의회 주관위원에게 서면으로 제3항에 따른 임시회의의 개최를 요구할 수 있다.', 5285);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9243, '⑥ 제5항에 따른 요구가 있는 경우 실무협의회 주관위원은 요구가 있은 날부터 14일 이내에 회의를 개최하여야 한다.', 5285);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9244, '⑦ 실무협의회 주관위원은 회의 개최 7일 전까지 회의 안건, 일시 및 장소를 실무협의회의 각 위원에게 서면으로 알려야 한다.', 5285);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9245, '① 실무협의회는 회의록을 작성하여 갖추어 두어야 한다.', 5286);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9246, '② 회의록은 실무협의회의 각 위원이 열람한 후 서명함으로써 확정된다.', 5286);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9247, '③ 실무협의회 주관위원은 실무협의회의 각 위원에게 확정된 회의록 사본 1부씩을 내주어야 한다.', 5286);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9248, '④ 회의록은 실무협의회 주관위원이 관리하며, 10년간 보존한다.', 5286);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9249, null, 5287);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9250, '①법 제28조의 규정에 의하여 신고(고소ㆍ고발을 포함한다. 이하 같다)에 대한 보상금(이하 "보상금"이라 한다)을 지급받고자 하는 사람은 법무부령이 정하는 바에 의하여 보상금지급신청서를 관할 지방검찰청검사장(지방검찰청 지청장을 포함한다. 이하 같다)에게 제출하여야 한다.', 5292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9251, '②제1항의 규정에 의한 신청은 「민원 처리에 관한 법률 시행령」 제2조제1항제3호에도 불구하고 익명 또는 가명으로 할 수 있다. 이 경우 그 사유에 관하여 신고를 접수한 기관의 장의 확인이 있어야 한다. <개정 2016.2.12>', 5292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9252, '③제1항의 규정에 의한 신청은 제6조제1항의 규정에 의한 보상금지급사유가 발생하였음을 안 날부터 1년 이내에 하여야 한다.', 5292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9253, '④지방검찰청검사장은 제1항의 규정에 의한 신청서를 접수한 때에는 법무부령이 정하는 서류를 첨부하여 검찰총장을 경유하여 법무부장관에게 제출하여야 한다.', 5292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9254, '①보상금은 신고가 접수된 범죄에 대하여 공소가 제기되거나 기소유예처분이 된 경우에 지급할 수 있다. 다만, 피의자를 검거하지 못하는 등으로 공소가 제기되지 아니한 경우에도 신고로 인하여 범죄의 주요 증거가 확보되거나 피해자 구조에 현저히 기여한 때에는 보상금을 지급할 수 있다.', 5293);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9255, '②보상금은 최고 2천만원 이내로 하여 그 지급결정이 있은 당해연도 예산의 범위안에서 지급하되, 그 구체적인 지급기준은 법무부령으로 정한다.', 5293);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9256, '③법무부장관은 보상금 지급사무의 일부를 검찰총장 또는 지방검찰청 검사장에게 위임할 수 있다.', 5293);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9257, null, 5295);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9258, null, 5299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9259, '① 대통령령으로 정한 금액 범위 내의 벌금형이 확정된 벌금 미납자는 검사의 납부명령일부터 30일 이내에 주거지를 관할하는 지방검찰청(지방검찰청지청을 포함한다. 이하 같다)의 검사에게 사회봉사를 신청할 수 있다. 다만, 검사로부터 벌금의 일부납부 또는 납부연기를 허가받은 자는 그 허가기한 내에 사회봉사를 신청할 수 있다.', 5301);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9260, '② 제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 사람은 사회봉사를 신청할 수 없다.', 5301);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9261, '③ 제1항의 사회봉사를 신청할 때에 필요한 서류 및 제출방법에 관한 사항은 대통령령으로 정하되, 신청서식 및 서식에 적을 내용 등은 법무부령으로 정한다.', 5301);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9262, '① 제4조제1항의 신청을 받은 검사는 사회봉사 신청인(이하 "신청인"이라 한다)이 제6조제2항 각 호의 요건에 해당하지 아니하는 때에는 법원에 사회봉사의 허가를 청구하여야 한다.', 5302);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9263, '② 검사는 사회봉사의 청구 여부를 결정하기 위하여 필요한 경우 신청인에게 출석 또는 자료의 제출을 요구하거나, 신청인의 동의를 받아 공공기관, 민간단체 등에 벌금 납입 능력 확인에 필요한 자료의 제출을 요구할 수 있다.', 5302);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9264, '③ 신청인이 정당한 이유 없이 검사의 출석 요구나 자료제출 요구를 거부한 경우 검사는 신청을 기각할 수 있다.', 5302);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9265, '④ 검사는 신청일부터 7일 이내에 사회봉사의 청구 여부를 결정하여야 한다. 다만, 제2항에 따른 출석 요구, 자료제출 요구에 걸리는 기간은 위 기간에 포함하지 아니한다.', 5302);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9266, '⑤ 검사는 사회봉사의 신청을 기각한 때에는 이를 지체 없이 신청인에게 서면으로 알려야 한다.', 5302);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9267, '⑥ 사회봉사의 신청을 기각하는 검사의 처분에 대한 이의신청에 관하여는 「형사소송법」 제489조를 준용한다.', 5302);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9268, '① 법원은 검사로부터 사회봉사 허가 청구를 받은 날부터 14일 이내에 벌금 미납자의 경제적 능력, 사회봉사 이행에 필요한 신체적 능력, 주거의 안정성 등을 고려하여 사회봉사 허가 여부를 결정한다. 다만, 제3항에 따른 출석 요구, 자료제출 요구에 걸리는 기간은 위 기간에 포함하지 아니한다.', 5303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9269, '② 다음 각 호의 어느 하나에 해당하는 경우에는 사회봉사를 허가하지 아니한다.', 5303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9270, '③ 법원은 사회봉사 허가 여부를 결정하기 위하여 필요한 경우 신청인에게 출석 또는 자료의 제출을 요구하거나 신청인의 동의를 받아 공공기관, 민간단체 등에 벌금 납입 능력 확인에 필요한 자료의 제출을 요구할 수 있다.', 5303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9271, '④ 법원은 사회봉사를 허가하는 경우 벌금 미납액에 의하여 계산된 노역장 유치 기간에 상응하는 사회봉사시간을 산정하여야 한다. 다만, 산정된 사회봉사시간 중 1시간 미만은 집행하지 아니한다.', 5303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9272, '⑤ 사회봉사를 허가받지 못한 벌금 미납자는 그 결정을 고지받은 날부터 15일 이내에 벌금을 내야 하며, 위의 기간 내에 벌금을 내지 아니할 경우 노역장에 유치한다. 다만, 사회봉사 불허가에 관한 통지를 받은 날부터 15일이 지나도록 벌금을 내지 아니한 사람 중 「형법」 제69조제1항에 따른 벌금 납입기간이 지나지 아니한 사람의 경우에는 그 납입기간이 지난 후 노역장에 유치한다.', 5303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9273, '① 법원은 제6조제1항의 결정을 검사와 신청인에게 서면으로 알려야 한다.', 5304);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9274, '② 법원은 사회봉사를 허가하는 경우 그 확정일부터 3일 이내에 사회봉사 대상자의 주거지를 관할하는 보호관찰소(보호관찰지소를 포함한다. 이하 같다)의 장에게 사회봉사 허가서, 판결문 등본, 약식명령 등본 등 사회봉사 집행에 필요한 서류를 송부하여야 한다.', 5304);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9275, '① 사회봉사 대상자는 법원으로부터 사회봉사 허가의 고지를 받은 날부터 10일 이내에 사회봉사 대상자의 주거지를 관할하는 보호관찰소의 장에게 주거, 직업, 그 밖에 대통령령으로 정하는 사항을 신고하여야 한다.', 5305);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9276, '② 사회봉사 대상자로부터 제1항의 신고를 받은 보호관찰소의 장은 사회봉사 대상자에게 사회봉사의 내용, 준수사항, 사회봉사 종료 및 취소 사유 등에 대하여 고지하여야 한다.', 5305);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9277, '① 사회봉사는 보호관찰관이 집행한다. 다만, 보호관찰관은 그 집행의 전부 또는 일부를 국공립기관이나 그 밖의 단체 또는 시설의 협력을 받아 집행할 수 있다.', 5306);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9278, '② 검사는 보호관찰관에게 사회봉사 집행실태에 대한 관련 자료의 제출을 요구할 수 있고, 집행방법 및 내용이 부적당하다고 인정하는 경우에는 이에 대한 변경을 요구할 수 있다.', 5306);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9279, '③ 보호관찰관은 검사로부터 제2항의 변경 요구를 받으면 그에 따라 사회봉사의 집행방법 및 내용을 변경하여 집행하여야 한다.', 5306);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9280, '① 보호관찰관은 사회봉사 대상자의 성격, 사회경력, 범죄의 원인 및 개인적 특성 등을 고려하여 사회봉사의 집행분야를 정하여야 한다.', 5307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9281, '② 사회봉사는 1일 9시간을 넘겨 집행할 수 없다. 다만, 사회봉사의 내용상 연속집행의 필요성이 있어 보호관찰관이 승낙하고 사회봉사 대상자가 분명히 동의한 경우에만 연장하여 집행할 수 있다.', 5307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9282, '③ 사회봉사의 집행시간은 사회봉사 기간 동안의 집행시간을 합산하여 시간 단위로 인정한다. 다만, 집행시간을 합산한 결과 1시간 미만이면 1시간으로 인정한다.', 5307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9283, '④ 집행 개시 시기와 그 밖의 사회봉사 집행기준에 관한 사항은 대통령령으로 정하되, 구체적인 절차 및 서식에 적을 내용 등은 법무부령으로 정한다.', 5307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9284, '① 사회봉사 대상자는 사회봉사의 이행을 마치기 전에 벌금의 전부 또는 일부를 낼 수 있다.', 5309);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9285, '② 사회봉사 집행 중에 벌금을 내려는 사회봉사 대상자는 보호관찰소의 장으로부터 사회봉사집행확인서를 발급받아 주거지를 관할하는 지방검찰청의 검사에게 제출하여야 한다.', 5309);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9286, '③ 제2항의 사회봉사집행확인서를 제출받은 검사는 미납한 벌금에서 이미 집행한 사회봉사시간에 상응하는 금액을 공제하는 방법으로 남은 벌금을 산정하여 사회봉사 대상자에게 고지한다.', 5309);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9287, '④ 검사는 사회봉사 대상자가 벌금을 전부 또는 일부 낸 경우 그 사실을 지체 없이 사회봉사를 집행 중인 보호관찰소의 장에게 통보하여야 한다.', 5309);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9288, '⑤ 사회봉사 대상자가 미납벌금의 일부를 낸 경우 검사는 법원이 결정한 사회봉사시간에서 이미 납입한 벌금에 상응하는 사회봉사시간을 공제하는 방법으로 남은 사회봉사시간을 다시 산정하여 사회봉사 대상자와 사회봉사를 집행 중인 보호관찰소의 장에게 통보하여야 한다.', 5309);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9289, '① 사회봉사 대상자가 다음 각 호의 어느 하나에 해당하는 경우 보호관찰소 관할 지방검찰청의 검사는 보호관찰소의 장의 신청에 의하여 사회봉사 허가의 취소를 법원에 청구한다.', 5311);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9290, '② 제1항의 취소신청이 있는 경우 보호관찰관은 사회봉사의 집행을 중지하여야 한다. 다만, 제1항의 취소신청에 따라 사회봉사의 집행이 중지된 기간은 제11조의 기간에 포함하지 아니한다.', 5311);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9291, '③ 제1항의 청구를 받은 법원은 사회봉사 대상자의 의견을 듣거나 필요한 자료의 제출을 요구할 수 있다.', 5311);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9292, '④ 법원은 제1항의 청구가 있는 날부터 14일 이내에 사회봉사 취소 여부를 결정한다. 다만, 사회봉사 대상자의 의견을 듣거나 필요한 자료의 제출 요구 등에 걸리는 기간은 위 기간에 포함하지 아니한다.', 5311);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9293, '⑤ 법원은 제4항의 결정을 검사와 사회봉사 대상자에게 서면으로 알려야 한다.', 5311);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9294, '⑥ 제5항의 고지를 받은 검사는 보호관찰소의 장에게 지체 없이 서면으로 알려야 한다.', 5311);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9295, '⑦ 사회봉사 허가가 취소된 사회봉사 대상자는 취소통지를 받은 날부터 7일 이내에 남은 사회봉사시간에 해당하는 미납벌금을 내야 하며, 그 기간 내에 미납벌금을 내지 아니하면 노역장에 유치한다.', 5311);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9296, '⑧ 사회봉사의 취소를 구하는 보호관찰소의 장의 신청 또는 검사의 취소청구가 받아들여지지 아니하는 경우 보호관찰관은 지체 없이 사회봉사를 집행하여야 한다.', 5311);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9297, '① 사회봉사는 다음 각 호의 어느 하나에 해당하는 경우에 종료한다.', 5312);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9298, '② 보호관찰소의 장은 사회봉사 대상자가 제1호 또는 제4호에 해당되면 사회봉사 대상자의 주거지를 관할하는 지방검찰청의 검사에게 지체 없이 통보하여야 한다.', 5312);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9299, '① 사회봉사 대상자에 대하여는 「보호관찰 등에 관한 법률」 제34조부터 제38조까지, 제54조, 제55조, 제59조 및 제62조제2항을 준용한다.', 5314);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9300, '② 이 법에 따른 결정에 대하여는 이 법에 특별한 규정이 있는 경우를 제외하고는 「형사소송법」을 준용한다.', 5314);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9301, null, 5317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9302, null, 5319);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9303, null, 5320);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9304, '① 사회봉사는 평일 주간에 집행하는 것을 원칙으로 한다. 다만, 사회봉사 대상자의 동의 또는 신청을 받아 사회봉사 대상자의 생업, 학업, 질병 등을 고려하여 야간 또는 공휴일에 집행할 수 있다.', 5322);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9305, '② 법 제10조제2항 단서에 따라 1일 9시간을 넘겨 사회봉사를 집행하는 경우에도 1일 총 13시간을 초과할 수 없다.', 5322);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9306, '① 보호관찰관은 법 제11조 단서에 따라 사회봉사의 집행기간을 연장하려는 경우에는 그 집행기간이 끝나기 10일 전까지 관할 지방검찰청의 검사에게 서면으로 사회봉사 집행기간의 연장허가를 신청하여야 한다.', 5324);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9307, '② 검사는 제1항의 신청을 받은 날부터 7일 이내에 사회봉사 집행기간의 연장 여부를 결정하여야 한다.', 5324);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9308, '① 검사가 법 제12조제3항에 따라 사회봉사시간에 상응하는 벌금액을 산정하는 경우 및 같은 조 제5항에 따라 납부한 벌금액에 상응하는 사회봉사시간을 산정하는 경우에는 법원이 해당 사회봉사를 허가할 때에 적용한 벌금액과 사회봉사시간의 비율에 따른다.', 5325);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9309, '② 법 제12조제3항에 따라 산정된 남은 벌금액 중 1천원 미만 및 같은 조 제5항에 따라 산정된 남은 사회봉사시간 중 1시간 미만은 집행하지 아니한다.', 5325);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9310, '① 검사는 사회봉사 대상자가 벌금의 전부를 낸 경우 그 사실을 지체 없이 서면으로 사회봉사를 집행 중인 보호관찰소의 장에게 통보하여야 한다.', 5326);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9311, '② 사회봉사 대상자가 미납벌금의 일부를 낸 경우 법 제12조제5항에 따른 검사의 통보는 사회봉사 허가 사건번호, 허가받은 사회봉사시간, 이행한 사회봉사시간, 납부한 벌금액, 납부한 벌금액에 상응하는 사회봉사시간 및 남은 사회봉사시간 등을 적은 서면으로 하여야 한다.', 5326);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9312, '① 검사는 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보, 같은 영 제19조제1호 또는 제4호에 따른 주민등록번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 5327);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9313, '② 보호관찰관 또는 보호관찰소의 장은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다.', 5327);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9314, '① 법 제12조제4항 및 영 제12조제1항에 따른 벌금의 전부 납입 사실의 통보는 별지 제10호 서식에 따른다.', 5338);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9315, '② 법 제12조제5항 및 영 제12조제2항에 따른 벌금의 일부 납입 사실 및 남은 사회봉사시간의 통보는 별지 제11호 서식에 따른다.', 5338);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9316, null, 5342);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9317, '① 사법경찰관리는 법 제22조의2제1항에 따른 신분비공개수사(이하 "신분비공개수사"라 한다) 또는 같은 조 제2항에 따른 신분위장수사(이하 "신분위장수사"라 한다)를 하는 경우에는 피해자에게 추가 피해가 발생하지 않도록 주의해야 한다.', 5344);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9318, '② 사법경찰관리는 법 제22조의2제2항제3호에 따라 촬영물 또는 복제물 등을 소지 또는 광고하는 경우에는 피해자에 관한 자료가 유포되지 않도록 해야 한다.', 5344);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9319, '① 법 제22조의2제1항에 따른 신분 비공개는 사법경찰관리임을 밝히지 않거나 부인(법 제22조의2제2항제1호에 이르지 않는 행위로서 사법경찰관리 외의 신분을 고지하는 방식을 포함한다)하는 방법으로 한다.', 5345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9320, '② 법 제22조의2제1항에 따른 접근은 다음 각 호의 방법으로 한다.', 5345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9321, '① 사법경찰관리는 법 제22조의2제2항제3호 단서에 따라 피해자의 동의를 받으려면 법 제22조의3제3항에 따른 신분위장수사에 대한 허가 신청 전(법 제22조의5제1항에 따른 긴급 신분위장수사의 경우에는 촬영물 또는 복제물 등의 제공 또는 판매 전을 말한다)에 피해자에게 신분위장수사의 필요성ㆍ종류ㆍ목적ㆍ대상ㆍ범위ㆍ기간ㆍ장소 및 방법 등을 직접 설명한 후 피해자로부터 경찰청장 또는 해양경찰청장이 정하는 서면으로 동의를 받아야 한다.', 5346);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9322, '② 사법경찰관리는 법 제22조의3제8항에 따라 신분위장수사의 수사기간을 연장하려는 경우로서 제1항에 따라 피해자의 동의를 받아야 하는 경우에는 그 연장 신청 전에 제1항에 따라 다시 피해자에게 설명하고 서면 동의를 받아야 한다.', 5346);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9323, '③ 사법경찰관리는 피해자가 신체적인 또는 정신적인 장애가 있어 사물을 변별하거나 의사를 결정할 능력이 미약한 경우에는 법 제22조의2제2항제3호 단서에 따른 동의를 받아서는 안 된다.', 5346);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9324, '④ 사법경찰관리는 제1항에 따라 피해자의 동의를 받은 후 신분위장수사를 종료하거나 실시하지 않기로 결정한 경우에는 지체 없이 피해자에게 다음 각 호의 사항을 통보해야 한다.', 5346);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9325, '⑤ 법 제22조의2제2항제3호에 따른 광고에 촬영물 또는 복제물 등의 영상ㆍ사진ㆍ음성의 전부 또는 일부가 포함되어 있는 경우의 피해자 동의 절차 등에 관하여는 제1항부터 제4항까지의 규정에 따른다. 이 경우 제1항 중 "제공 또는 판매 전"은 "광고 전"으로 한다.', 5346);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9326, '① 신분비공개수사를 하려는 사법경찰관리는 법 제22조의3에 따라 신분비공개수사 전(법 제22조의4에 따른 긴급 신분비공개수사의 경우에는 신분비공개수사 개시 후 48시간이 되기 전을 말한다)에 경찰청장 또는 해양경찰청장이 정하는 서면으로 바로 위 상급 경찰관서 수사부서의 장의 승인을 받아야 한다.', 5347);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9327, '② 사법경찰관리는 제1항에 따른 승인을 받으려면 신분비공개수사의 필요성ㆍ대상ㆍ범위ㆍ기간ㆍ장소 및 방법 등을 바로 위 상급 경찰관서 수사부서의 장에게 소명해야 한다.', 5347);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9328, '③ 사법경찰관리는 신분비공개수사를 종료한 때에는 종료 일시 및 종료 사유 등을 바로 위 상급 경찰관서 수사부서의 장에게 보고해야 한다.', 5347);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9329, '① 법 제22조의7제1항에 따른 국가경찰위원회에 대한 보고사항은 신분비공개수사의 승인요청 경찰관서, 승인기간, 종료일시, 종료사유, 수사대상, 수사방법, 사건요지 및 필요성으로 한다.', 5348);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9330, '② 법 제22조의7제2항에 따른 국회 소관 상임위원회에 대한 보고사항은 신분비공개수사의 승인요청 경찰관서, 승인기간, 승인건수, 종료일시 및 종료사유로 한다.', 5348);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9331, '③ 제1항 및 제2항에 따른 보고는 「정보통신망 이용촉진 및 정보보호 등에 관한 법률」 제2조제1항제1호에 따른 정보통신망(이하 "정보통신망"이라 한다)을 이용하거나, 그 내용을 기록ㆍ보관ㆍ출력할 수 있는 전자적 정보저장매체에 저장하여 제출하는 방법으로 할 수 있다.', 5348);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9332, null, 5349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9333, '① 법 제42조제1항에 따른 신상정보 등록대상자(이하 "등록대상자"라 한다)가 법 제43조제1항에 따라 제출하여야 하는 신상정보(이하 "기본신상정보"라 한다)의 세부 내용은 다음 각 호와 같다. <개정 2015.1.20, 2015.6.22, 2017.6.20>', 5350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9334, '② 기본신상정보 및 법 제43조제3항에 따른 변경정보(이하 "변경정보"라 한다)는 등록대상자가 자신의 주소지 또는 거주지를 관할하는 경찰관서의 장(이하 "관할경찰관서의 장"이라 한다)에게 직접 방문하여 제출하여야 한다. 다만, 등록대상자가 교정시설 또는 치료감호시설(이하 "교정시설등"이라 한다)에 수용된 경우에는 그 교정시설의 장 또는 치료감호시설의 장(이하 "교정시설등의 장"이라 한다)에게 제출하여야 한다. <개정 2017.6.20>', 5350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9335, '③ 관할경찰관서의 장 또는 교정시설등의 장은 기본신상정보와 변경정보를 받으면 다음 각 호의 관련 서류를 확인하는 방법으로 그 진위를 확인하여야 한다. <개정 2015.1.20, 2017.6.20, 2024.12.3>', 5350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9336, '④ 관할경찰관서의 장 또는 교정시설등의 장은 제2항에 따라 기본신상정보와 변경정보를 받으면 기재사항 중 빠진 것이 없는지를 확인한 후 제출 일시를 적은 확인서를 지체 없이 등록대상자에게 발급하여야 한다. 이 경우 다음 각 호의 사항이 기재된 안내문을 함께 교부하여야 한다. <개정 2017.6.20>', 5350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9337, '⑤ 관할경찰관서의 장 또는 교정시설등의 장은 법 제43조제2항 또는 제4항에 따라 등록대상자의 사진을 촬영할 때에는 선명한 화질을 얻도록 충분히 조명을 밝힌 상태에서 600만 화소 이상의 해상도를 가진 카메라로 촬영하고, 등록대상자의 정면ㆍ좌측ㆍ우측 상반신 및 전신 컬러사진을 각각 구분하여 전자기록으로 저장ㆍ보관하여야 한다. 이 경우 전자기록의 파일명을 등록대상자의 성명과 생년월일로 하여야 한다.', 5350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9338, '⑥ 교정시설등의 장은 법 제43조제4항 단서에 따라 촬영한 등록대상자 사진의 전자기록과 다음 각 호의 사항을 기재한 서면을 등록대상자가 출소되기 2개월 전까지 법무부장관에게 송달하여야 한다. 다만, 등록대상자가 가석방, 가종료 또는 가출소되는 경우에는 출소 5일 전까지 법무부장관에게 송달하여야 한다.', 5350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9339, '⑦ 기본신상정보와 변경정보에 관한 제출 서식 및 신상정보 제출 확인서 등에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2017.6.20>', 5350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9340, '① 법 제43조의2제1항에 따라 등록대상자는 6개월 이상 국외에 체류하기 위하여 출국하는 경우 출국하기 전까지 관할경찰관서의 장에게 법무부령으로 정하는 출국신고서를 제출하여야 한다.', 5352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9341, '② 제1항에 따라 출국신고서를 제출한 등록대상자는 사정변경 등으로 출국을 하지 아니하거나 출국 후 입국 예정일까지 입국을 할 수 없게 된 경우에는 지체없이 관할경찰관서의 장에게 알려야 한다.', 5352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9342, '③ 등록대상자는 법 제43조의2제2항에 따라 입국한 날부터 14일 이내에 관할경찰관서의 장에게 법무부령으로 정하는 입국신고서를 제출하여야 한다. 다만, 그 기간 내에 입국신고서를 제출할 수 없는 특별한 사정이 있는 경우에는 그 사유가 소멸한 날부터 7일 이내에 소명자료를 첨부하여 입국신고서를 제출하여야 한다.', 5352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9343, '④ 법 제43조의2제3항에 따라 관할경찰관서의 장은 제1항에 따른 출국신고서 및 제3항에 따른 입국신고서 등 등록대상자의 출입국에 관한 정보를 등기우편으로 법무부장관에게 송달하여야 한다.', 5352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9344, '① 법무부장관은 법 제43조제5항ㆍ제6항 및 법 제43조의2제3항에 따라 관할경찰관서의 장 또는 교정시설등의 장으로부터 송달받은 정보와 법 제44조제4항 전단에 따라 관계 행정기관의 장으로부터 조회된 내용을 확인한 후 성범죄자 등록정보 원부(이하 "등록정보원부"라 한다)에 등록하여야 한다. <개정 2017.6.20>', 5353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9345, '② 법 제44조제1항 각 호의 등록대상자 정보의 세부 내용은 다음 각 호와 같다. <개정 2020.8.5>', 5353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9346, '③ 등록정보원부의 서식과 작성 방식 등에 관한 구체적인 사항은 법무부령으로 정한다.', 5353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9347, '① 법 제44조제1항 또는 제4항 전단에 따라 등록한 정보(이하 "등록정보"라 한다)의 열람은 등록대상자가 「형사사법절차 전자화 촉진법」 제2조제6호에 따른 형사사법포털(이하 이 조에서 "형사사법포털"이라 한다)에 접속하여 열람하는 방법으로 한다.', 5354);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9348, '② 제1항에 따른 등록정보의 열람은 등록대상자 본인 외에는 할 수 없다.', 5354);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9349, '③ 형사사법포털의 접속절차ㆍ방법 등 그 밖에 등록정보의 열람에 필요한 사항은 법무부장관이 정한다.', 5354);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9350, '① 등록대상자는 법 제44조제2항 단서에 따라 등록정보의 통지를 신청하거나 그 신청을 철회하려는 경우에는 법무부령으로 정하는 신청서를 직접 방문하거나 등기우편으로 법무부장관에게 제출하여야 한다.', 5355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9351, '② 법무부장관은 법 제44조제2항 단서 또는 같은 조 제4항 후단에 따라 등록정보를 통지하여야 하는 경우에는 등기우편으로 그 내용을 통지하여야 한다.', 5355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9352, '① 법무부장관은 법 제45조제7항 및 제8항에 따라 등록정보의 진위와 변경 여부를 확인하기 위하여 필요하면 성범죄자 등록정보를 관할경찰관서의 장에게 제공할 수 있다. <개정 2017.6.20>', 5356);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9353, '② 법 제45조제7항에 따른 직접 대면 등의 방법은 등록대상자를 경찰관서에 출석시키는 방법을 포함한다. <개정 2017.6.20>', 5356);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9354, '③ 법 제45조제7항 및 제8항에 따라 관할경찰관서의 장으로부터 등록정보의 진위와 변경 여부 확인 결과를 송부받은 법무부장관은 그 내용을 확인한 후 변경된 정보를 등록정보원부에 등록하여야 한다. <개정 2017.6.20>', 5356);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9355, '① 법 제45조의2제2항에 따른 신상정보 등록의 면제를 신청하려는 등록대상자(이하 "면제 신청인"이라 한다)는 법무부령으로 정하는 신청서를 직접 방문하거나 등기우편으로 법무부장관에게 제출하여야 한다.', 5357);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9356, '② 제1항에 따른 면제 신청인으로부터 신상정보 등록의 면제 신청을 받은 법무부장관은 법 제45조의2제2항 각 호의 기간 경과 여부와 법 제45조의2제3항 각 호에 따른 면제 요건 충족 여부를 확인한 후 등록의 면제신청을 받은 날부터 20일 이내에 신상정보 등록의 면제 여부를 결정하여야 한다. 이 경우 법 제45조의2제2항 각 호의 기간 경과 여부는 등록면제 신청일을 기준으로 하고, 법 제45조의2제3항 각 호에 따른 면제 요건 충족 여부는 등록면제 결정일을 기준으로 한다.', 5357);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9357, '③ 법무부장관은 면제 신청인이 등록의 면제 여부의 결과를 정보통신망을 이용하여 열람할 수 있도록 하여야 한다. 다만, 면제 신청인이 요청하는 경우에는 등기우편으로 통지하여야 한다.', 5357);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9358, '④ 제3항에 따른 등록면제 신청 결과의 열람 방법 등에 관하여는 제5조의2를 준용한다.', 5357);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9359, '① 법 제45조의3제3항 본문에 따른 등록정보 폐기 사실의 열람 방법 등에 관하여는 제5조의2를 준용한다.', 5358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9360, '② 법 제45조의3제3항 본문에 따라 등록정보 폐기 사실을 열람할 수 있는 기간은 법 제45조의3제1항에 따라 등록이 종료된 때부터 1년으로 한다.', 5358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9361, '① 등록대상자는 법 제45조의3제3항 단서에 따라 등록정보 폐기사실의 통지를 신청하거나 그 신청을 철회하려는 경우 법무부령으로 정하는 신청서를 직접 방문하거나 등기우편으로 법무부장관에게 제출하여야 한다.', 5359);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9362, '② 법무부장관은 제1항에 따라 등록정보 폐기 사실의 통지 신청을 받은 경우 등기우편으로 그 내용을 통지하여야 한다.', 5359);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9363, '③ 법무부장관은 법 제44조제4항 전단에 따라 등록된 신상정보가 법 제45조의3제2항에 따라 폐기된 경우에는 등기우편으로 해당 등록대상자에게 그 사실을 통지하여야 한다.', 5359);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9364, '① 법무부장관은 법 제46조제1항에 따른 등록정보의 배포를 갈음하여 검사나 각급 경찰관서의 장에게 법무부장관이 운영하는 정보통신망에 접속하여 등록정보를 조회하거나 출력하게 할 수 있다.', 5360);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9365, '② 제1항에 따라 출력된 등록정보는 그 활용 목적을 다하거나 법 제45조의3제1항에 따라 신상정보의 등록이 종료되면 즉시 폐기하여야 한다. <개정 2017.6.20>', 5360);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9366, '① 법무부장관은 법 제47조제3항과 제49조제3항에 따라 등록정보의 공개와 고지에 필요한 정보(제6조제3항에 따라 등록정보원부에 등록한 변경된 정보를 포함한다)를 등록정보원부에 등록한 후 지체 없이 여성가족부장관에게 송부하여야 한다.', 5361);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9367, '② 제1항에 따른 정보의 송부는 행정기관의 정보통신망 등을 이용하여 한다.', 5361);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9368, '① 법무부장관, 검사 또는 사법경찰관은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 5362);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9369, '② 법무부장관, 여성가족부장관, 검사, 관할경찰관서의 장, 각급 경찰관서의 장, 교정시설등의 장, 관계 행정기관의 장 또는 사법경찰관은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호 및 제2호에 따른 유전정보 및 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2017.6.20>', 5362);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9370, '③ 법 제27조제6항에 따른 국선변호사 또는 법 제35조에 따른 진술조력인은 다음 각 호의 업무를 수행하기 위하여 불가피한 경우 제2항에 따른 개인정보가 포함된 자료를 처리할 수 있다.', 5362);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9371, '① 이 법에서 "성폭력범죄"란 다음 각 호의 어느 하나에 해당하는 죄를 말한다. <개정 2013.4.5, 2016.12.20>', 5365);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9372, '② 제1항 각 호의 범죄로서 다른 법률에 따라 가중처벌되는 죄는 성폭력범죄로 본다.', 5365);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9373, '① 「형법」 제319조제1항(주거침입), 제330조(야간주거침입절도), 제331조(특수절도) 또는 제342조(미수범. 다만, 제330조 및 제331조의 미수범으로 한정한다)의 죄를 범한 사람이 같은 법 제297조(강간), 제297조의2(유사강간), 제298조(강제추행) 및 제299조(준강간, 준강제추행)의 죄를 범한 경우에는 무기징역 또는 7년 이상의 징역에 처한다. <개정 2020.5.19>', 5366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9374, '② 「형법」 제334조(특수강도) 또는 제342조(미수범. 다만, 제334조의 미수범으로 한정한다)의 죄를 범한 사람이 같은 법 제297조(강간), 제297조의2(유사강간), 제298조(강제추행) 및 제299조(준강간, 준강제추행)의 죄를 범한 경우에는 사형, 무기징역 또는 10년 이상의 징역에 처한다.', 5366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9375, '① 흉기나 그 밖의 위험한 물건을 지닌 채 또는 2명 이상이 합동하여 「형법」 제297조(강간)의 죄를 범한 사람은 무기징역 또는 7년 이상의 징역에 처한다. <개정 2020.5.19>', 5367);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9376, '② 제1항의 방법으로 「형법」 제298조(강제추행)의 죄를 범한 사람은 5년 이상의 유기징역에 처한다. <개정 2020.5.19>', 5367);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9377, '③ 제1항의 방법으로 「형법」 제299조(준강간, 준강제추행)의 죄를 범한 사람은 제1항 또는 제2항의 예에 따라 처벌한다.', 5367);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9378, '① 친족관계인 사람이 폭행 또는 협박으로 사람을 강간한 경우에는 7년 이상의 유기징역에 처한다.', 5368);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9379, '② 친족관계인 사람이 폭행 또는 협박으로 사람을 강제추행한 경우에는 5년 이상의 유기징역에 처한다.', 5368);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9380, '③ 친족관계인 사람이 사람에 대하여 「형법」 제299조(준강간, 준강제추행)의 죄를 범한 경우에는 제1항 또는 제2항의 예에 따라 처벌한다.', 5368);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9381, '④ 제1항부터 제3항까지의 친족의 범위는 4촌 이내의 혈족ㆍ인척과 동거하는 친족으로 한다.', 5368);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9382, '⑤ 제1항부터 제3항까지의 친족은 사실상의 관계에 의한 친족을 포함한다.', 5368);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9383, '① 신체적인 또는 정신적인 장애가 있는 사람에 대하여 「형법」 제297조(강간)의 죄를 범한 사람은 무기징역 또는 7년 이상의 징역에 처한다.', 5369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9384, '② 신체적인 또는 정신적인 장애가 있는 사람에 대하여 폭행이나 협박으로 다음 각 호의 어느 하나에 해당하는 행위를 한 사람은 5년 이상의 유기징역에 처한다.', 5369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9385, '③ 신체적인 또는 정신적인 장애가 있는 사람에 대하여 「형법」 제298조(강제추행)의 죄를 범한 사람은 3년 이상의 유기징역 또는 3천만원 이상 5천만원 이하의 벌금에 처한다. <개정 2020.5.19>', 5369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9386, '④ 신체적인 또는 정신적인 장애로 항거불능 또는 항거곤란 상태에 있음을 이용하여 사람을 간음하거나 추행한 사람은 제1항부터 제3항까지의 예에 따라 처벌한다.', 5369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9387, '⑤ 위계(僞計) 또는 위력(威力)으로써 신체적인 또는 정신적인 장애가 있는 사람을 간음한 사람은 5년 이상의 유기징역에 처한다.', 5369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9388, '⑥ 위계 또는 위력으로써 신체적인 또는 정신적인 장애가 있는 사람을 추행한 사람은 1년 이상의 유기징역 또는 1천만원 이상 3천만원 이하의 벌금에 처한다.', 5369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9389, '⑦ 장애인의 보호, 교육 등을 목적으로 하는 시설의 장 또는 종사자가 보호, 감독의 대상인 장애인에 대하여 제1항부터 제6항까지의 죄를 범한 경우에는 그 죄에 정한 형의 2분의 1까지 가중한다.', 5369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9390, '① 13세 미만의 사람에 대하여 「형법」 제297조(강간)의 죄를 범한 사람은 무기징역 또는 10년 이상의 징역에 처한다.', 5370);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9391, '② 13세 미만의 사람에 대하여 폭행이나 협박으로 다음 각 호의 어느 하나에 해당하는 행위를 한 사람은 7년 이상의 유기징역에 처한다.', 5370);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9392, '③ 13세 미만의 사람에 대하여 「형법」 제298조(강제추행)의 죄를 범한 사람은 5년 이상의 유기징역에 처한다. <개정 2020.5.19>', 5370);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9393, '④ 13세 미만의 사람에 대하여 「형법」 제299조(준강간, 준강제추행)의 죄를 범한 사람은 제1항부터 제3항까지의 예에 따라 처벌한다.', 5370);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9394, '⑤ 위계 또는 위력으로써 13세 미만의 사람을 간음하거나 추행한 사람은 제1항부터 제3항까지의 예에 따라 처벌한다.', 5370);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9395, '① 제3조제1항, 제4조, 제6조, 제7조 또는 제15조(제3조제1항, 제4조, 제6조 또는 제7조의 미수범으로 한정한다)의 죄를 범한 사람이 다른 사람을 상해하거나 상해에 이르게 한 때에는 무기징역 또는 10년 이상의 징역에 처한다.', 5371);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9396, '② 제5조 또는 제15조(제5조의 미수범으로 한정한다)의 죄를 범한 사람이 다른 사람을 상해하거나 상해에 이르게 한 때에는 무기징역 또는 7년 이상의 징역에 처한다.', 5371);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9397, '① 제3조부터 제7조까지, 제15조(제3조부터 제7조까지의 미수범으로 한정한다)의 죄 또는 「형법」 제297조(강간), 제297조의2(유사강간) 및 제298조(강제추행)부터 제300조(미수범)까지의 죄를 범한 사람이 다른 사람을 살해한 때에는 사형 또는 무기징역에 처한다.', 5372);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9398, '② 제4조, 제5조 또는 제15조(제4조 또는 제5조의 미수범으로 한정한다)의 죄를 범한 사람이 다른 사람을 사망에 이르게 한 때에는 무기징역 또는 10년 이상의 징역에 처한다.', 5372);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9399, '③ 제6조, 제7조 또는 제15조(제6조 또는 제7조의 미수범으로 한정한다)의 죄를 범한 사람이 다른 사람을 사망에 이르게 한 때에는 사형, 무기징역 또는 10년 이상의 징역에 처한다.', 5372);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9400, '① 업무, 고용이나 그 밖의 관계로 인하여 자기의 보호, 감독을 받는 사람에 대하여 위계 또는 위력으로 추행한 사람은 3년 이하의 징역 또는 1천500만원 이하의 벌금에 처한다. <개정 2018.10.16>', 5373);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9401, '② 법률에 따라 구금된 사람을 감호하는 사람이 그 사람을 추행한 때에는 5년 이하의 징역 또는 2천만원 이하의 벌금에 처한다. <개정 2018.10.16>', 5373);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9402, '① 카메라나 그 밖에 이와 유사한 기능을 갖춘 기계장치를 이용하여 성적 욕망 또는 수치심을 유발할 수 있는 사람의 신체를 촬영대상자의 의사에 반하여 촬영한 자는 7년 이하의 징역 또는 5천만원 이하의 벌금에 처한다. <개정 2018.12.18, 2020.5.19>', 5377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9403, '② 제1항에 따른 촬영물 또는 복제물(복제물의 복제물을 포함한다. 이하 이 조에서 같다)을 반포ㆍ판매ㆍ임대ㆍ제공 또는 공공연하게 전시ㆍ상영(이하 "반포등"이라 한다)한 자 또는 제1항의 촬영이 촬영 당시에는 촬영대상자의 의사에 반하지 아니한 경우(자신의 신체를 직접 촬영한 경우를 포함한다)에도 사후에 그 촬영물 또는 복제물을 촬영대상자의 의사에 반하여 반포등을 한 자는 7년 이하의 징역 또는 5천만원 이하의 벌금에 처한다. <개정 2018.12.18, 2020.5.19>', 5377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9404, '③ 영리를 목적으로 촬영대상자의 의사에 반하여 「정보통신망 이용촉진 및 정보보호 등에 관한 법률」 제2조제1항제1호의 정보통신망(이하 "정보통신망"이라 한다)을 이용하여 제2항의 죄를 범한 자는 3년 이상의 유기징역에 처한다. <개정 2018.12.18, 2020.5.19>', 5377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9405, '④ 제1항 또는 제2항의 촬영물 또는 복제물을 소지ㆍ구입ㆍ저장 또는 시청한 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다. <신설 2020.5.19>', 5377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9406, '⑤ 상습으로 제1항부터 제3항까지의 죄를 범한 때에는 그 죄에 정한 형의 2분의 1까지 가중한다. <신설 2020.5.19>', 5377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9407, '① 사람의  얼굴ㆍ신체 또는 음성을 대상으로 한 촬영물ㆍ영상물 또는 음성물(이하 이 조에서 "영상물등"이라 한다)을 영상물등의 대상자의 의사에 반하여 성적 욕망 또는 수치심을 유발할 수 있는 형태로 편집ㆍ합성 또는 가공(이하 이 조에서 "편집등"이라 한다)한 자는 7년 이하의 징역 또는 5천만원 이하의 벌금에 처한다. <개정 2024.10.16>', 5378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9408, '② 제1항에 따른 편집물ㆍ합성물ㆍ가공물(이하 이 조에서 "편집물등"이라 한다) 또는 복제물(복제물의 복제물을 포함한다. 이하 이 조에서 같다)을 반포등을 한 자 또는 제1항의 편집등을 할 당시에는 영상물등의 대상자의 의사에 반하지 아니한 경우에도 사후에 그 편집물등 또는 복제물을 영상물등의 대상자의 의사에 반하여 반포등을 한 자는 7년 이하의 징역 또는 5천만원 이하의 벌금에 처한다. <개정 2024.10.16>', 5378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9409, '③ 영리를 목적으로 영상물등의 대상자의 의사에 반하여 정보통신망을 이용하여 제2항의 죄를 범한 자는 3년 이상의 유기징역에 처한다. <개정 2024.10.16>', 5378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9410, '④ 제1항 또는 제2항의 편집물등 또는 복제물을 소지ㆍ구입ㆍ저장 또는 시청한 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다. <신설 2024.10.16>', 5378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9411, '⑤ 상습으로 제1항부터 제3항까지의 죄를 범한 때에는 그 죄에 정한 형의 2분의 1까지 가중한다. <신설 2020.5.19, 2024.10.16>', 5378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9412, '① 성적 욕망 또는 수치심을 유발할 수 있는 촬영물 또는 복제물(복제물의 복제물을 포함한다), 제14조의2제2항에 따른 편집물등 또는 복제물(복제물의 복제물을 포함한다)을 이용하여 사람을 협박한 자는 1년 이상의 유기징역에 처한다. <개정 2024.10.16>', 5379);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9413, '② 제1항에 따른 협박으로 사람의 권리행사를 방해하거나 의무 없는 일을 하게 한 자는 3년 이상의 유기징역에 처한다.', 5379);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9414, '③ 상습으로 제1항 및 제2항의 죄를 범한 경우에는 그 죄에 정한 형의 2분의 1까지 가중한다.', 5379);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9415, '① 제14조부터 제14조의3까지의 죄에 해당하는 범죄행위에 의하여 생긴 재산 또는 그 범죄행위의 보수(報酬)로 얻은 재산(이하 이 항에서 "범죄수익"이라 한다)과 범죄수익에서 유래한 재산은 몰수하고, 이를 몰수할 수 없는 경우에는 그 가액(價額)을 추징한다.', 5382);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9416, '② 제1항에 따른 몰수 및 추징에 관하여는 「범죄수익은닉의 규제 및 처벌 등에 관한 법률」 제8조부터 제10조까지, 제10조의3, 제10조의4, 제11조, 제12조를 준용한다.', 5382);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9417, '① 법원이 성폭력범죄를 범한 사람에 대하여 형의 선고를 유예하는 경우에는 1년 동안 보호관찰을 받을 것을 명할 수 있다. 다만, 성폭력범죄를 범한 「소년법」 제2조에 따른 소년에 대하여 형의 선고를 유예하는 경우에는 반드시 보호관찰을 명하여야 한다.', 5383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9418, '② 법원이 성폭력범죄를 범한 사람에 대하여 유죄판결(선고유예는 제외한다)을 선고하거나 약식명령을 고지하는 경우에는 500시간의 범위에서 재범예방에 필요한 수강명령 또는 성폭력 치료프로그램의 이수명령(이하 "이수명령"이라 한다)을 병과하여야 한다. 다만, 수강명령 또는 이수명령을 부과할 수 없는 특별한 사정이 있는 경우에는 그러하지 아니하다. <개정 2016.12.20>', 5383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9419, '③ 성폭력범죄를 범한 자에 대하여 제2항의 수강명령은 형의 집행을 유예할 경우에 그 집행유예기간 내에서 병과하고, 이수명령은 벌금 이상의 형을 선고하거나 약식명령을 고지할 경우에 병과한다. 다만, 이수명령은 성폭력범죄자가 「전자장치 부착 등에 관한 법률」 제9조의2제1항제4호에 따른 이수명령을 부과받은 경우에는 병과하지 아니한다. <개정 2016.12.20, 2020.2.4>', 5383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9420, '④ 법원이 성폭력범죄를 범한 사람에 대하여 형의 집행을 유예하는 경우에는 제2항에 따른 수강명령 외에 그 집행유예기간 내에서 보호관찰 또는 사회봉사 중 하나 이상의 처분을 병과할 수 있다.', 5383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9421, '⑤ 제2항에 따른 수강명령 또는 이수명령은 형의 집행을 유예할 경우에는 그 집행유예기간 내에, 벌금형을 선고하거나 약식명령을 고지할 경우에는 형 확정일부터 6개월 이내에, 징역형 이상의 실형(實刑)을 선고할 경우에는 형기 내에 각각 집행한다. 다만, 수강명령 또는 이수명령은 성폭력범죄를 범한 사람이 「아동ㆍ청소년의 성보호에 관한 법률」 제21조에 따른 수강명령 또는 이수명령을 부과받은 경우에는 병과하지 아니한다. <개정 2016.12.20>', 5383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9422, '⑥ 제2항에 따른 수강명령 또는 이수명령이 벌금형 또는 형의 집행유예와 병과된 경우에는 보호관찰소의 장이 집행하고, 징역형 이상의 실형(치료감호와 징역형 이상의 실형이 병과된 경우를 포함한다. 이하 이 항에서 같다)과 병과된 경우에는 교정시설의 장 또는 치료감호시설의 장(이하 "교정시설등의 장"이라 한다)이 집행한다. 다만, 징역형 이상의 실형과 병과된 이수명령을 모두 이행하기 전에 석방 또는 가석방되거나 미결구금일수 산입 등의 사유로 형을 집행할 수 없게 된 경우에는 보호관찰소의 장이 남은 이수명령을 집행한다. <개정 2024.1.16>', 5383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9423, '⑦ 제2항에 따른 수강명령 또는 이수명령은 다음 각 호의 내용으로 한다.', 5383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9424, '⑧ 성폭력범죄를 범한 사람으로서 형의 집행 중에 가석방된 사람은 가석방기간 동안 보호관찰을 받는다. 다만, 가석방을 허가한 행정관청이 보호관찰을 할 필요가 없다고 인정한 경우에는 그러하지 아니하다.', 5383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9425, '⑨ 보호관찰, 사회봉사, 수강명령 및 이수명령에 관하여 이 법에서 규정한 사항 외의 사항에 대하여는 「보호관찰 등에 관한 법률」을 준용한다.', 5383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9426, '① 법원은 성폭력범죄를 범한 피고인에 대하여 제16조에 따른 보호관찰, 사회봉사, 수강명령 또는 이수명령을 부과하기 위하여 필요하다고 인정하면 그 법원의 소재지 또는 피고인의 주거지를 관할하는 보호관찰소의 장에게 피고인의 신체적ㆍ심리적 특성 및 상태, 정신성적 발달과정, 성장배경, 가정환경, 직업, 생활환경, 교우관계, 범행동기, 병력(病歷), 피해자와의 관계, 재범위험성 등 피고인에 관한 사항의 조사를 요구할 수 있다.', 5384);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9427, '② 제1항의 요구를 받은 보호관찰소의 장은 지체 없이 이를 조사하여 서면으로 해당 법원에 알려야 한다. 이 경우 필요하다고 인정하면 피고인이나 그 밖의 관계인을 소환하여 심문하거나 소속 보호관찰관에게 필요한 사항을 조사하게 할 수 있다.', 5384);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9428, '③ 법원은 제1항의 요구를 받은 보호관찰소의 장에게 조사진행상황에 관한 보고를 요구할 수 있다', 5384);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9429, '① 미성년자에 대한 성폭력범죄의 공소시효는 「형사소송법」 제252조제1항 및 「군사법원법」 제294조제1항에도 불구하고 해당 성폭력범죄로 피해를 당한 미성년자가 성년에 달한 날부터 진행한다. <개정 2013.4.5>', 5388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9430, '② 제2조제3호 및 제4호의 죄와 제3조부터 제9조까지의 죄는 디엔에이(DNA)증거 등 그 죄를 증명할 수 있는 과학적인 증거가 있는 때에는 공소시효가 10년 연장된다.', 5388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9431, '③ 13세 미만의 사람 및 신체적인 또는 정신적인 장애가 있는 사람에 대하여 다음 각 호의 죄를 범한 경우에는 제1항과 제2항에도 불구하고 「형사소송법」 제249조부터 제253조까지 및 「군사법원법」 제291조부터 제295조까지에 규정된 공소시효를 적용하지 아니한다. <개정 2019.8.20, 2020.5.19>', 5388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9432, '④ 다음 각 호의 죄를 범한 경우에는 제1항과 제2항에도 불구하고 「형사소송법」 제249조부터 제253조까지 및 「군사법원법」 제291조부터 제295조까지에 규정된 공소시효를 적용하지 아니한다. <개정 2013.4.5>', 5388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9433, '① 사법경찰관리는 제14조부터 제14조의3까지의 죄(이하 "디지털 성범죄"라 한다)에 대하여 신분을 비공개하고 범죄현장(정보통신망을 포함한다) 또는 범인으로 추정되는 자들에게 접근하여 범죄행위의 증거 및 자료 등을 수집(이하 "신분비공개수사"라 한다)할 수 있다.', 5390);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9434, '② 사법경찰관리는 디지털 성범죄를 계획 또는 실행하고 있거나 실행하였다고 의심할 만한 충분한 이유가 있고, 다른 방법으로는 그 범죄의 실행을 저지하거나 범인의 체포 또는 증거의 수집이 어려운 경우에 한정하여 수사 목적을 달성하기 위하여 부득이한 때에는 다음 각 호의 행위(이하 "신분위장수사"라 한다)를 할 수 있다.', 5390);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9435, '③ 제1항에 따른 수사의 방법 등에 필요한 사항은 대통령령으로 정한다.', 5390);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9436, '① 사법경찰관리가 신분비공개수사를 진행하고자 할 때에는 사전에 상급 경찰관서 수사부서의 장의 승인을 받아야 한다. 이 경우 그 수사기간은 3개월을 초과할 수 없다.', 5391);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9437, '② 제1항에 따른 승인의 절차 및 방법 등에 필요한 사항은 대통령령으로 정한다.', 5391);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9438, '③ 사법경찰관리는 신분위장수사를 하려는 경우에는 검사에게 신분위장수사에 대한 허가를 신청하고, 검사는 법원에 그 허가를 청구한다.', 5391);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9439, '④ 제3항의 신청은 필요한 신분위장수사의 종류ㆍ목적ㆍ대상ㆍ범위ㆍ기간ㆍ장소ㆍ방법 및 해당 신분위장수사가 제22조의2제2항의 요건을 충족하는 사유 등의 신청사유를 기재한 서면으로 하여야 하며, 신청사유에 대한 소명자료를 첨부하여야 한다.', 5391);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9440, '⑤ 법원은 제3항의 신청이 이유 있다고 인정하는 경우에는 신분위장수사를 허가하고, 이를 증명하는 서류(이하 "허가서"라 한다)를 신청인에게 발부한다.', 5391);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9441, '⑥ 허가서에는 신분위장수사의 종류ㆍ목적ㆍ대상ㆍ범위ㆍ기간ㆍ장소ㆍ방법 등을 특정하여 기재하여야 한다.', 5391);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9442, '⑦ 신분위장수사의 기간은 3개월을 초과할 수 없으며, 그 수사기간 중 수사의 목적이 달성되었을 경우에는 즉시 종료하여야 한다.', 5391);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9443, '⑧ 제7항에도 불구하고 제22조의2제2항의 요건이 존속하여 그 수사기간을 연장할 필요가 있는 경우에는 사법경찰관리는 소명자료를 첨부하여 3개월의 범위에서 수사기간의 연장을 검사에게 신청하고, 검사는 법원에 그 연장을 청구한다. 이 경우 신분위장수사의 총 기간은 1년을 초과할 수 없다.', 5391);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9444, '① 사법경찰관리는 디지털 성범죄에 대하여 제22조의3제1항 및 제2항에 따른 절차를 거칠 수 없는 긴급을 요하는 때에는 상급 경찰관서 수사부서의 장의 승인 없이 신분비공개수사를 할 수 있다.', 5392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9445, '② 사법경찰관리는 제1항에 따른 신분비공개수사 개시 후 지체 없이 상급 경찰관서 수사부서의 장에게 보고하여야 하고, 사법경찰관리는 48시간 이내에 상급 경찰관서 수사부서의 장의 승인을 받지 못한 때에는 즉시 신분비공개수사를 중지하여야 한다.', 5392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9446, '③ 제1항 및 제2항에 따른 신분비공개수사 기간에 대해서는 제22조의3제1항 후단을 준용한다.', 5392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9447, '① 사법경찰관리는 제22조의2제2항의 요건을 구비하고, 제22조의3제3항부터 제8항까지에 따른 절차를 거칠 수 없는 긴급을 요하는 때에는 법원의 허가 없이 신분위장수사를 할 수 있다.', 5393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9448, '② 사법경찰관리는 제1항에 따른 신분위장수사 개시 후 지체 없이 검사에게 허가를 신청하여야 하고, 사법경찰관리는 48시간 이내에 법원의 허가를 받지 못한 때에는 즉시 신분위장수사를 중지하여야 한다.', 5393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9449, '③ 제1항 및 제2항에 따른 신분위장수사 기간에 대해서는 제22조의3제7항 및 제8항을 준용한다.', 5393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9450, null, 5394);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9451, '① 「국가경찰과 자치경찰의 조직 및 운영에 관한 법률」 제16조제1항에 따른 국가수사본부장(이하 "국가수사본부장"이라 한다)은 신분비공개수사가 종료된 즉시 대통령령으로 정하는 바에 따라 같은 법 제7조제1항에 따른 국가경찰위원회에 수사 관련 자료를 보고하여야 한다.', 5395);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9452, '② 국가수사본부장은 대통령령으로 정하는 바에 따라 국회 소관 상임위원회에 신분비공개수사 관련 자료를 반기별로 보고하여야 한다.', 5395);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9453, '① 제22조의2부터 제22조의5까지에 따른 신분비공개수사 또는 신분위장수사에 대한 승인ㆍ집행ㆍ보고 및 각종 서류작성 등에 관여한 공무원 또는 그 직에 있었던 자는 직무상 알게 된 신분비공개수사 또는 신분위장수사에 관한 사항을 외부에 공개하거나 누설하여서는 아니 된다.', 5396);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9454, '② 제1항의 비밀유지에 필요한 사항은 대통령령으로 정한다.', 5396);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9455, '① 사법경찰관리가 신분비공개수사 또는 신분위장수사 중 부득이한 사유로 위법행위를 한 경우 그 행위에 고의나 중대한 과실이 없는 경우에는 벌하지 아니한다.', 5398);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9456, '② 제1항에 따른 위법행위가 「국가공무원법」 제78조제1항에 따른 징계 사유에 해당하더라도 그 행위에 고의나 중대한 과실이 없는 경우에는 징계 요구 또는 문책 요구 등 책임을 묻지 아니한다.', 5398);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9457, '③ 신분비공개수사 또는 신분위장수사 행위로 타인에게 손해가 발생한 경우라도 사법경찰관리는 그 행위에 고의나 중대한 과실이 없는 경우에는 그 손해에 대한 책임을 지지 아니한다.', 5398);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9458, '① 사법경찰관리는 디지털 성범죄에 대한 신고를 받고 다음 각 호의 어느 하나에 해당하는 촬영물 또는 복제물 등(이하 이 항에서 "촬영물등"이라 한다)이 정보통신망을 통하여 게시ㆍ상영 또는 유통되고 있다는 사실을 확인한 경우에는 지체 없이 「방송통신위원회의 설치 및 운영에 관한 법률」 제18조에 따른 방송통신심의위원회와 「정보통신망 이용촉진 및 정보보호 등에 관한 법률」 제2조제1항제3호의 정보통신서비스 제공자 또는 같은 항 제9호의 게시판의 관리ㆍ운영자에게 해당 촬영물등에 대한 삭제 또는 접속차단 등의 조치를 하여줄 것을 요청하여야 한다. 이 경우 사법경찰관리는 촬영물등의 삭제 또는 접속차단 등의 처리절차에 관하여 특별한 사정이 없으면 해당 피해자에게 안내하여야 한다.', 5401);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9459, '② 사법경찰관리는 디지털 성범죄의 피해자가 재차 피해를 입을 위험이 현저하여 신변을 보호할 필요가 있다고 인정되는 경우 해당 피해자를 대통령령으로 정하는 보호시설 또는 상담시설로 인도할 수 있다. 이 경우 그 피해자의 동의를 얻어야 한다.', 5401);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9460, '① 성폭력범죄의 수사 또는 재판을 담당하거나 이에 관여하는 공무원 또는 그 직에 있었던 사람은 피해자의 주소, 성명, 나이, 직업, 학교, 용모, 그 밖에 피해자를 특정하여 파악할 수 있게 하는 인적사항과 사진 등 또는 그 피해자의 사생활에 관한 비밀을 공개하거나 다른 사람에게 누설하여서는 아니 된다.', 5402);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9461, '② 누구든지 제1항에 따른 피해자의 주소, 성명, 나이, 직업, 학교, 용모, 그 밖에 피해자를 특정하여 파악할 수 있는 인적사항이나 사진 등을 피해자의 동의를 받지 아니하고 신문 등 인쇄물에 싣거나 「방송법」 제2조제1호에 따른 방송 또는 정보통신망을 통하여 공개하여서는 아니 된다.', 5402);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9462, '① 검찰총장은 각 지방검찰청 검사장으로 하여금 성폭력범죄 전담 검사를 지정하도록 하여 특별한 사정이 없으면 이들로 하여금 피해자를 조사하게 하여야 한다.', 5404);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9463, '② 경찰청장은 각 경찰서장으로 하여금 성폭력범죄 전담 사법경찰관을 지정하도록 하여 특별한 사정이 없으면 이들로 하여금 피해자를 조사하게 하여야 한다.', 5404);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9464, '③ 국가는 제1항의 검사 및 제2항의 사법경찰관에게 성폭력범죄의 수사에 필요한 전문지식과 피해자보호를 위한 수사방법 및 수사절차, 아동 심리 및 아동ㆍ장애인 조사 면담기법 등에 관한 교육을 실시하여야 한다. <개정 2023.7.11>', 5404);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9465, '④ 성폭력범죄를 전담하여 조사하는 제1항의 검사 및 제2항의 사법경찰관은 19세 미만인 피해자나 신체적인 또는 정신적인 장애로 사물을 변별하거나 의사를 결정할 능력이 미약한 피해자(이하 "19세미만피해자등"이라 한다)를 조사할 때에는 피해자의 나이, 인지적 발달 단계, 심리 상태, 장애 정도 등을 종합적으로 고려하여야 한다. <신설 2023.7.11>', 5404);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9466, '① 성폭력범죄의 피해자 및 그 법정대리인(이하 "피해자등"이라 한다)은 형사절차상 입을 수 있는 피해를 방어하고 법률적 조력을 보장하기 위하여 변호사를 선임할 수 있다.', 5405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9467, '② 제1항에 따른 변호사는 검사 또는 사법경찰관의 피해자등에 대한 조사에 참여하여 의견을 진술할 수 있다. 다만, 조사 도중에는 검사 또는 사법경찰관의 승인을 받아 의견을 진술할 수 있다.', 5405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9468, '③ 제1항에 따른 변호사는 피의자에 대한 구속 전 피의자심문, 증거보전절차, 공판준비기일 및 공판절차에 출석하여 의견을 진술할 수 있다. 이 경우 필요한 절차에 관한 구체적 사항은 대법원규칙으로 정한다.', 5405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9469, '④ 제1항에 따른 변호사는 증거보전 후 관계 서류나 증거물, 소송계속 중의 관계 서류나 증거물을 열람하거나 등사할 수 있다.', 5405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9470, '⑤ 제1항에 따른 변호사는 형사절차에서 피해자등의 대리가 허용될 수 있는 모든 소송행위에 대한 포괄적인 대리권을 가진다.', 5405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9471, '⑥ 검사는 피해자에게 변호사가 없는 경우 국선변호사를 선정하여 형사절차에서 피해자의 권익을 보호할 수 있다. 다만, 19세미만피해자등에게 변호사가 없는 경우에는 국선변호사를 선정하여야 한다. <개정 2023.7.11>', 5405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9472, '① 수사기관과 법원 및 소송관계인은 성폭력범죄를 당한 피해자의 나이, 심리 상태 또는 후유장애의 유무 등을 신중하게 고려하여 조사 및 심리ㆍ재판 과정에서 피해자의 인격이나 명예가 손상되거나 사적인 비밀이 침해되지 아니하도록 주의하여야 한다.', 5407);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9473, '② 수사기관과 법원은 성폭력범죄의 피해자를 조사하거나 심리ㆍ재판할 때 피해자가 편안한 상태에서 진술할 수 있는 환경을 조성하여야 하며, 조사 및 심리ㆍ재판 횟수는 필요한 범위에서 최소한으로 하여야 한다.', 5407);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9474, '③ 수사기관과 법원은 조사 및 심리ㆍ재판 과정에서 19세미만피해자등의 최상의 이익을 고려하여 다음 각 호에 따른 보호조치를 하도록 노력하여야 한다. <신설 2023.7.11>', 5407);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9475, '① 검사 또는 사법경찰관은 19세미만피해자등의 진술 내용과 조사 과정을 영상녹화장치로 녹화(녹음이 포함된 것을 말하며, 이하 "영상녹화"라 한다)하고, 그 영상녹화물을 보존하여야 한다.', 5408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9476, '② 검사 또는 사법경찰관은 19세미만피해자등을 조사하기 전에 다음 각 호의 사실을 피해자의 나이, 인지적 발달 단계, 심리 상태, 장애 정도 등을 고려한 적절한 방식으로 피해자에게 설명하여야 한다.', 5408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9477, '③ 제1항에도 불구하고 19세미만피해자등 또는 그 법정대리인(법정대리인이 가해자이거나 가해자의 배우자인 경우는 제외한다)이 이를 원하지 아니하는 의사를 표시하는 경우에는 영상녹화를 하여서는 아니 된다.', 5408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9478, '④ 검사 또는 사법경찰관은 제1항에 따른 영상녹화를 마쳤을 때에는 지체 없이 피해자 또는 변호사 앞에서 봉인하고 피해자로 하여금 기명날인 또는 서명하게 하여야 한다.', 5408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9479, '⑤ 검사 또는 사법경찰관은 제1항에 따른 영상녹화 과정의 진행 경과를 조서(별도의 서면을 포함한다. 이하 같다)에 기록한 후 수사기록에 편철하여야 한다.', 5408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9480, '⑥ 제5항에 따라 영상녹화 과정의 진행 경과를 기록할 때에는 다음 각 호의 사항을 구체적으로 적어야 한다.', 5408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9481, '⑦ 검사 또는 사법경찰관은 19세미만피해자등이나 그 법정대리인이 신청하는 경우에는 영상녹화 과정에서 작성한 조서의 사본 또는 영상녹화물에 녹음된 내용을 옮겨 적은 녹취서의 사본을 신청인에게 발급하거나 영상녹화물을 재생하여 시청하게 하여야 한다.', 5408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9482, '⑧ 누구든지 제1항에 따라 영상녹화한 영상녹화물을 수사 및 재판의 용도 외에 다른 목적으로 사용하여서는 아니 된다.', 5408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9483, '⑨ 제1항에 따른 영상녹화의 방법에 관하여는 「형사소송법」 제244조의2제1항 후단을 준용한다.', 5408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9484, '① 제30조제1항에 따라 19세미만피해자등의 진술이 영상녹화된 영상녹화물은 같은 조 제4항부터 제6항까지에서 정한 절차와 방식에 따라 영상녹화된 것으로서 다음 각 호의 어느 하나의 경우에 증거로 할 수 있다.', 5409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9485, '② 법원은 제1항제2호에 따라 증거능력이 있는 영상녹화물을 유죄의 증거로 할지를 결정할 때에는 피고인과의 관계, 범행의 내용, 피해자의 나이, 심신의 상태, 피해자가 증언으로 인하여 겪을 수 있는 심리적 외상, 영상녹화물에 수록된 19세미만피해자등의 진술 내용 및 진술 태도 등을 고려하여야 한다. 이 경우 법원은 전문심리위원 또는 제33조에 따른 전문가의 의견을 들어야 한다.', 5409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9486, '① 성폭력범죄에 대한 심리는 그 피해자의 사생활을 보호하기 위하여 결정으로써 공개하지 아니할 수 있다.', 5410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9487, '② 증인으로 소환받은 성폭력범죄의 피해자와 그 가족은 사생활보호 등의 사유로 증인신문의 비공개를 신청할 수 있다.', 5410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9488, '③ 재판장은 제2항에 따른 신청을 받으면 그 허가 및 공개 여부, 법정 외의 장소에서의 신문 등 증인의 신문 방식 및 장소에 관하여 결정할 수 있다.', 5410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9489, '④ 제1항 및 제3항의 경우에는 「법원조직법」 제57조(재판의 공개)제2항ㆍ제3항 및 「군사법원법」 제67조제2항ㆍ제3항을 준용한다. <개정 2013.4.5>', 5410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9490, '① 각급 법원은 증인으로 법원에 출석하는 피해자등이 재판 전후에 피고인이나 그 가족과 마주치지 아니하도록 하고, 보호와 지원을 받을 수 있는 적절한 시설을 설치한다.', 5411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9491, '② 각급 법원은 제1항의 시설을 관리ㆍ운영하고 피해자등의 보호와 지원을 담당하는 직원(이하 "증인지원관"이라 한다)을 둔다.', 5411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9492, '③ 법원은 증인지원관에 대하여 인권 감수성 향상에 필요한 교육을 정기적으로 실시한다.', 5411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9493, '④ 증인지원관의 업무ㆍ자격 및 교육 등에 필요한 사항은 대법원규칙으로 정한다.', 5411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9494, '① 법원은 정신건강의학과의사, 심리학자, 사회복지학자, 그 밖의 관련 전문가로부터 행위자 또는 피해자의 정신ㆍ심리 상태에 대한 진단 소견 및 피해자의 진술 내용에 관한 의견을 조회할 수 있다.', 5412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9495, '② 법원은 성폭력범죄를 조사ㆍ심리할 때에는 제1항에 따른 의견 조회의 결과를 고려하여야 한다.', 5412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9496, '③ 법원은 법원행정처장이 정하는 관련 전문가 후보자 중에서 제1항에 따른 전문가를 지정하여야 한다.', 5412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9497, '④ 제1항부터 제3항까지의 규정은 수사기관이 성폭력범죄를 수사하는 경우에 준용한다. 다만, 피해자가 13세 미만이거나 신체적인 또는 정신적인 장애로 사물을 변별하거나 의사를 결정할 능력이 미약한 경우에는 관련 전문가에게 피해자의 정신ㆍ심리 상태에 대한 진단 소견 및 진술 내용에 관한 의견을 조회하여야 한다.', 5412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9498, '⑤ 제4항에 따라 준용할 경우 "법원행정처장"은 "검찰총장 또는 경찰청장"으로 본다.', 5412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9499, '① 법원은 다음 각 호의 어느 하나에 해당하는 피해자를 증인으로 신문하는 경우에 검사, 피해자 또는 그 법정대리인이 신청할 때에는 재판에 지장을 줄 우려가 있는 등 부득이한 경우가 아니면 피해자와 신뢰관계에 있는 사람을 동석하게 하여야 한다. <개정 2023.7.11>', 5413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9500, '② 제1항은 수사기관이 같은 항 각 호의 피해자를 조사하는 경우에 관하여 준용한다. <개정 2023.7.11>', 5413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9501, '③ 제1항 및 제2항의 경우 법원과 수사기관은 피해자와 신뢰관계에 있는 사람이 피해자에게 불리하거나 피해자가 원하지 아니하는 경우에는 동석하게 하여서는 아니 된다.', 5413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9502, '① 법무부장관은 의사소통 및 의사표현에 어려움이 있는 성폭력범죄의 피해자에 대한 형사사법절차에서의 조력을 위하여 진술조력인을 양성하여야 한다.', 5414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9503, '② 진술조력인은 정신건강의학, 심리학, 사회복지학, 교육학 등 아동ㆍ장애인의 심리나 의사소통 관련 전문지식이 있거나 관련 분야에서 상당 기간 종사한 사람으로 법무부장관이 정하는 교육을 이수하여야 한다. 진술조력인의 자격, 양성 및 배치 등에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2020.10.20>', 5414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9504, '③ 법무부장관은 제1항에 따라 양성한 진술조력인 명부를 작성하여야 한다.', 5414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9505, null, 5415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9506, '① 법무부장관은 진술조력인 자격을 가진 사람이 다음 각 호의 어느 하나에 해당하는 경우에는 그 자격을 취소할 수 있다. 다만, 제1호 또는 제2호에 해당하는 경우에는 그 자격을 취소하여야 한다.', 5416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9507, '② 법무부장관은 제1항에 따라 진술조력인 자격을 취소하려는 경우에는 해당 진술조력인에게 자격 취소 예정인 사실과 그 사유를 통보하여야 한다. 이 경우 통보를 받은 진술조력인은 법무부에 출석하여 소명(疏明)하거나 소명에 관한 의견서를 제출할 수 있다.', 5416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9508, '③ 법무부장관은 제2항 후단에 따라 진술조력인이 소명하거나 소명에 관한 의견서를 제출한 경우 진술조력인 자격 취소 여부를 결정하기 위하여 외부 전문가의 의견을 들을 수 있다.', 5416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9509, '④ 법무부장관은 제1항에 따라 진술조력인 자격을 취소한 경우에는 즉시 그 사람에게 진술조력인 자격 취소의 사실 및 그 사유를 서면으로 알려주어야 한다.', 5416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9510, '⑤ 제1항에 따라 진술조력인 자격이 취소된 사람의 자격증 반납에 관해서는 법무부령으로 정한다.', 5416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9511, '① 검사 또는 사법경찰관은 성폭력범죄의 피해자가 19세미만피해자등인 경우 형사사법절차에서의 조력과 원활한 조사를 위하여 직권이나 피해자, 그 법정대리인 또는 변호사의 신청에 따라 진술조력인으로 하여금 조사과정에 참여하여 의사소통을 중개하거나 보조하게 할 수 있다. 다만, 피해자 또는 그 법정대리인이 이를 원하지 아니하는 의사를 표시한 경우에는 그러하지 아니하다. <개정 2023.7.11>', 5417);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9512, '② 검사 또는 사법경찰관은 제1항의 피해자를 조사하기 전에 피해자, 법정대리인 또는 변호사에게 진술조력인에 의한 의사소통 중개나 보조를 신청할 수 있음을 고지하여야 한다.', 5417);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9513, '③ 진술조력인은 조사 전에 피해자를 면담하여 진술조력인 조력 필요성에 관하여 평가한 의견을 수사기관에 제출할 수 있다.', 5417);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9514, '④ 제1항에 따라 조사과정에 참여한 진술조력인은 피해자의 의사소통이나 표현 능력, 특성 등에 관한 의견을 수사기관이나 법원에 제출할 수 있다.', 5417);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9515, '⑤ 제1항부터 제4항까지의 규정은 검증에 관하여 준용한다.', 5417);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9516, '⑥ 그 밖에 진술조력인의 수사절차 참여에 관한 절차와 방법 등 필요한 사항은 법무부령으로 정한다.', 5417);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9517, '① 법원은 성폭력범죄의 피해자가 19세미만피해자등인 경우 재판과정에서의 조력과 원활한 증인 신문을 위하여 직권 또는 검사, 피해자, 그 법정대리인 및 변호사의 신청에 의한 결정으로 진술조력인으로 하여금 증인 신문에 참여하여 중개하거나 보조하게 할 수 있다. <개정 2023.7.11>', 5418);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9518, '② 법원은 증인이 제1항에 해당하는 경우에는 신문 전에 피해자, 법정대리인 및 변호사에게 진술조력인에 의한 의사소통 중개나 보조를 신청할 수 있음을 고지하여야 한다.', 5418);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9519, '③ 진술조력인의 소송절차 참여에 관한 구체적 절차와 방법은 대법원규칙으로 정한다.', 5418);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9520, '① 진술조력인은 수사 및 재판 과정에 참여함에 있어 중립적인 지위에서 상호간의 진술이 왜곡 없이 전달될 수 있도록 노력하여야 한다.', 5419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9521, '② 진술조력인은 그 직무상 알게 된 피해자의 주소, 성명, 나이, 직업, 학교, 용모, 그 밖에 피해자를 특정하여 파악할 수 있게 하는 인적사항과 사진 및 사생활에 관한 비밀을 공개하거나 다른 사람에게 누설하여서는 아니 된다.', 5419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9522, '① 법원은 제2조제1항제3호부터 제5호까지의 범죄의 피해자를 증인으로 신문하는 경우 검사와 피고인 또는 변호인의 의견을 들어 비디오 등 중계장치에 의한 중계를 통하여 신문할 수 있다.', 5421);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9523, '② 제1항에 따른 증인신문의 절차ㆍ방법 등에 관하여 필요한 사항은 대법원규칙으로 정한다.', 5421);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9524, '① 법원은 19세미만피해자등을 증인으로 신문하려는 경우에는 19세미만피해자등의 보호와 원활한 심리를 위하여 필요한 경우 검사, 피고인 또는 변호인의 의견을 들어 사건을 공판준비절차에 부칠 수 있다.', 5422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9525, '② 법원은 제1항에 따라 공판준비절차에 부치는 경우 증인신문을 위한 심리계획을 수립하기 위하여 공판준비기일을 지정하여야 한다.', 5422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9526, '③ 법원은 제2항에 따라 지정한 공판준비기일에 증인신문을 중개하거나 보조할 진술조력인을 출석하게 할 수 있다.', 5422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9527, '④ 19세미만피해자등의 변호사는 제2항에 따라 지정된 공판준비기일에 출석할 수 있다.', 5422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9528, '⑤ 법원은 제1항에 따른 공판준비절차에서 검사, 피고인 또는 변호인에게 신문할 사항을 기재한 서면을 법원에 미리 제출하게 할 수 있다. 다만, 제출한 신문사항은 증인신문을 하기 전까지는 열람ㆍ복사 등을 통하여 상대방에게 공개하지 아니한다.', 5422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9529, '⑥ 법원은 제2항에 따라 지정된 공판준비기일에서 검사, 피고인, 변호인, 19세미만피해자등의 변호사 및 진술조력인에게 신문사항과 신문방법 등에 관한 의견을 구할 수 있다.', 5422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9530, '① 법원은 19세미만피해자등을 증인으로 신문하는 경우 사전에 피해자에게 「형사소송법」 제165조의2제1항에 따라 비디오 등 중계장치에 의한 중계시설을 통하여 신문할 수 있음을 고지하여야 한다.', 5423);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9531, '② 19세미만피해자등은 제1항의 중계시설을 통하여 증인신문을 진행할지 여부 및 증인으로 출석할 장소에 관하여 법원에 의견을 진술할 수 있다.', 5423);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9532, '③ 제1항에 따른 중계시설을 통하여 19세미만피해자등을 증인으로 신문하는 경우 그 중계시설은 특별한 사정이 없으면 제30조제1항에 따른 영상녹화가 이루어진 장소로 한다. 다만, 피해자가 다른 장소를 원하는 의사를 표시하거나, 제30조제1항에 따른 영상녹화가 이루어진 장소가 경찰서 등 수사기관의 시설인 경우에는 법원이 중계시설을 지정할 수 있다.', 5423);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9533, '① 피해자나 그 법정대리인 또는 사법경찰관은 피해자가 공판기일에 출석하여 증언하는 것에 현저히 곤란한 사정이 있을 때에는 그 사유를 소명하여 제30조에 따라 영상녹화된 영상녹화물 또는 그 밖의 다른 증거에 대하여 해당 성폭력범죄를 수사하는 검사에게 「형사소송법」 제184조(증거보전의 청구와 그 절차)제1항에 따른 증거보전의 청구를 할 것을 요청할 수 있다. 이 경우 피해자가 19세미만피해자등인 경우에는 공판기일에 출석하여 증언하는 것에 현저히 곤란한 사정이 있는 것으로 본다. <개정 2020.10.20, 2023.7.11>', 5424);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9534, '② 제1항의 요청을 받은 검사는 그 요청이 타당하다고 인정할 때에는 증거보전의 청구를 할 수 있다. 다만, 19세미만피해자등이나 그 법정대리인이 제1항의 요청을 하는 경우에는 특별한 사정이 없는 한 「형사소송법」 제184조제1항에 따라 관할 지방법원판사에게 증거보전을 청구하여야 한다. <개정 2023.7.11>', 5424);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9535, '① 제2조제1항제3호ㆍ제4호, 같은 조 제2항(제1항제3호ㆍ제4호에 한정한다), 제3조부터 제15조까지의 범죄 및 「아동ㆍ청소년의 성보호에 관한 법률」 제2조제2호가목ㆍ라목의 범죄(이하 "등록대상 성범죄"라 한다)로 유죄판결이나 약식명령이 확정된 자 또는 같은 법 제49조제1항제4호에 따라 공개명령이 확정된 자는 신상정보 등록대상자(이하 "등록대상자"라 한다)가 된다. 다만, 제12조ㆍ제13조의 범죄 및 「아동ㆍ청소년의 성보호에 관한 법률」 제11조제3항 및 제5항의 범죄로 벌금형을 선고받은 자는 제외한다. <개정 2016.12.20>', 5425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9536, '② 법원은 등록대상 성범죄로 유죄판결을 선고하거나 약식명령을 고지하는 경우에는 등록대상자라는 사실과 제43조에 따른 신상정보 제출 의무가 있음을 등록대상자에게 알려 주어야 한다. <개정 2016.12.20>', 5425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9537, '③ 제2항에 따른 통지는 판결을 선고하는 때에는 구두 또는 서면으로 하고, 약식명령을 고지하는 때에는 통지사항이 기재된 서면을 송달하는 방법으로 한다. <신설 2016.12.20>', 5425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9538, '④ 법원은 제1항의 판결이나 약식명령이 확정된 날부터 14일 이내에 판결문(제45조제4항에 따라 법원이 등록기간을 달리 정한 경우에는 그 사실을 포함한다) 또는 약식명령 등본을 법무부장관에게 송달하여야 한다. <개정 2016.12.20>', 5425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9539, '① 등록대상자는 제42조제1항의 판결이 확정된 날부터 30일 이내에 다음 각 호의 신상정보(이하 "기본신상정보"라 한다)를 자신의 주소지를 관할하는 경찰관서의 장(이하 "관할경찰관서의 장"이라 한다)에게 제출하여야 한다. 다만, 등록대상자가 교정시설 또는 치료감호시설에 수용된 경우에는 그 교정시설등의 장에게 기본신상정보를 제출함으로써 이를 갈음할 수 있다. <개정 2014.12.30, 2016.12.20, 2024.1.16>', 5426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9540, '② 관할경찰관서의 장 또는 교정시설등의 장은 제1항에 따라 등록대상자가 기본신상정보를 제출할 때에 등록대상자의 정면ㆍ좌측ㆍ우측 상반신 및 전신 컬러사진을 촬영하여 전자기록으로 저장ㆍ보관하여야 한다. <개정 2016.12.20>', 5426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9541, '③ 등록대상자는 제1항에 따라 제출한 기본신상정보가 변경된 경우에는 그 사유와 변경내용(이하 "변경정보"라 한다)을 변경사유가 발생한 날부터 20일 이내에 제1항에 따라 제출하여야 한다. <개정 2016.12.20>', 5426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9542, '④ 등록대상자는 제1항에 따라 기본신상정보를 제출한 경우에는 그 다음 해부터 매년 12월 31일까지 주소지를 관할하는 경찰관서에 출석하여 경찰관서의 장으로 하여금 자신의 정면ㆍ좌측ㆍ우측 상반신 및 전신 컬러사진을 촬영하여 전자기록으로 저장ㆍ보관하도록 하여야 한다. 다만, 교정시설등의 장은 등록대상자가 교정시설 등에 수용된 경우에는 석방 또는 치료감호 종료 전에 등록대상자의 정면ㆍ좌측ㆍ우측 상반신 및 전신 컬러사진을 새로 촬영하여 전자기록으로 저장ㆍ보관하여야 한다. <개정 2016.12.20>', 5426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9543, '⑤ 관할경찰관서의 장 또는 교정시설등의 장은 등록대상자로부터 제출받은 기본신상정보 및 변경정보와 제2항 및 제4항에 따라 저장ㆍ보관하는 전자기록을 지체 없이 법무부장관에게 송달하여야 한다. <개정 2016.12.20>', 5426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9544, '⑥ 제5항에 따라 등록대상자에 대한 기본신상정보를 송달할 때에 관할경찰관서의 장은 등록대상자에 대한 「형의 실효 등에 관한 법률」 제2조제5호에 따른 범죄경력자료를 함께 송달하여야 한다. <개정 2016.12.20>', 5426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9545, '⑦ 기본신상정보 및 변경정보의 송달, 등록에 관한 절차와 방법 등 필요한 사항은 대통령령으로 정한다. <개정 2016.12.20>', 5426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9546, '① 등록대상자가 6개월 이상 국외에 체류하기 위하여 출국하는 경우에는 미리 관할경찰관서의 장에게 체류국가 및 체류기간 등을 신고하여야 한다.', 5427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9547, '② 제1항에 따라 신고한 등록대상자가 입국하였을 때에는 특별한 사정이 없으면 14일 이내에 관할경찰관서의 장에게 입국 사실을 신고하여야 한다. 제1항에 따른 신고를 하지 아니하고 출국하여 6개월 이상 국외에 체류한 등록대상자가 입국하였을 때에도 또한 같다.', 5427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9548, '③ 관할경찰관서의 장은 제1항 및 제2항에 따른 신고를 받았을 때에는 지체 없이 법무부장관에게 해당 정보를 송달하여야 한다.', 5427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9549, '④ 제1항 및 제2항에 따른 신고와 제3항에 따른 송달의 절차 및 방법 등에 관하여 필요한 사항은 대통령령으로 정한다.', 5427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9550, '① 법무부장관은 제43조제5항, 제6항 및 제43조의2제3항에 따라 송달받은 정보와 다음 각 호의 등록대상자 정보를 등록하여야 한다. <개정 2016.12.20, 2020.2.4>', 5428);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9551, '② 법무부장관은 등록대상자가 제1항에 따라 등록한 정보를 정보통신망을 이용하여 열람할 수 있도록 하여야 한다. 다만, 등록대상자가 신청하는 경우에는 등록한 정보를 등록대상자에게 통지하여야 한다. <개정 2016.12.20>', 5428);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9552, '③ 법무부장관은 제1항에 따른 등록에 필요한 정보의 조회(「형의 실효 등에 관한 법률」 제2조제8호에 따른 범죄경력조회를 포함한다)를 관계 행정기관의 장에게 요청할 수 있다.', 5428);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9553, '④ 법무부장관은 등록대상자가 기본신상정보 또는 변경정보를 정당한 사유 없이 제출하지 아니한 경우에는 신상정보의 등록에 필요한 사항을 관계 행정기관의 장에게 조회를 요청하여 등록할 수 있다. 이 경우 법무부장관은 등록일자를 밝혀 등록대상자에게 신상정보를 등록한 사실 및 등록한 신상정보의 내용을 통지하여야 한다. <개정 2016.12.20>', 5428);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9554, '⑤ 제3항 및 제4항의 요청을 받은 관계 행정기관의 장은 지체 없이 조회 결과를 법무부장관에게 송부하여야 한다.', 5428);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9555, '⑥ 제4항 전단에 따라 법무부장관이 기본신상정보를 등록한 경우에 등록대상자의 변경정보 제출과 사진 촬영에 대해서는 제43조제3항 및 제4항을 준용한다. <신설 2016.12.20>', 5428);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9556, '⑦ 제1항 또는 제4항 전단에 따라 등록한 정보(이하 "등록정보"라 한다)의 열람, 통지 신청 및 통지의 방법과 절차 등에 필요한 사항은 대통령령으로 정한다. <신설 2016.12.20>', 5428);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9557, '① 법무부장관은 제44조제1항 또는 제4항에 따라 기본신상정보를 최초로 등록한 날(이하 "최초등록일"이라 한다)부터 다음 각 호의 구분에 따른 기간(이하 "등록기간"이라 한다) 동안 등록정보를 보존ㆍ관리하여야 한다. 다만, 법원이 제4항에 따라 등록기간을 정한 경우에는 그 기간 동안 등록정보를 보존ㆍ관리하여야 한다.', 5429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9558, '② 신상정보 등록의 원인이 된 성범죄와 다른 범죄가 「형법」 제37조(판결이 확정되지 아니한 수개의 죄를 경합범으로 하는 경우로 한정한다)에 따라 경합되어 「형법」 제38조에 따라 형이 선고된 경우에는 그 선고형 전부를 신상정보 등록의 원인이 된 성범죄로 인한 선고형으로 본다.', 5429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9559, '③ 제1항에 따른 등록기간을 산정하기 위한 선고형은 다음 각 호에 따라 계산한다. 제2항이 적용되는 경우도 이와 같다.', 5429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9560, '④ 법원은 제2항이 적용(제3항이 동시에 적용되는 경우를 포함한다)되어 제1항 각 호에 따라 등록기간이 결정되는 것이 부당하다고 인정하는 경우에는 판결로 제1항 각 호의 기간 중 더 단기의 기간을 등록기간으로 정할 수 있다.', 5429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9561, '⑤ 다음 각 호의 기간은 제1항에 따른 등록기간에 넣어 계산하지 아니한다.', 5429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9562, '⑥ 법무부장관은 제44조제1항에 따른 등록 당시 등록대상자가 교정시설 또는 치료감호시설에 수용 중인 경우에는 등록대상자가 석방된 후 지체 없이 등록정보를 등록대상자의 관할경찰관서의 장에게 송부하여야 한다.', 5429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9563, '⑦ 관할경찰관서의 장은 등록기간 중 다음 각 호의 구분에 따른 기간마다 등록대상자와의 직접 대면 등의 방법으로 등록정보의 진위와 변경 여부를 확인하여 그 결과를 법무부장관에게 송부하여야 한다.', 5429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9564, '⑧ 제7항제2호 및 제3호에도 불구하고 관할경찰관서의 장은 다음 각 호의 구분에 따른 기간 동안에는 3개월마다 제7항의 결과를 법무부장관에게 송부하여야 한다.', 5429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9565, '① 신상정보 등록의 원인이 된 성범죄로 형의 선고를 유예받은 사람이 선고유예를 받은 날부터 2년이 경과하여 「형법」 제60조에 따라 면소된 것으로 간주되면 신상정보 등록을 면제한다.', 5430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9566, '② 등록대상자는 다음 각 호의 구분에 따른 기간(교정시설 또는 치료감호시설에 수용된 기간은 제외한다)이 경과한 경우에는 법무부령으로 정하는 신청서를 법무부장관에게 제출하여 신상정보 등록의 면제를 신청할 수 있다. <개정 2020.2.4>', 5430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9567, '③ 법무부장관은 제2항에 따라 등록의 면제를 신청한 등록대상자가 다음 각 호의 요건을 모두 갖춘 경우에는 신상정보 등록을 면제한다. <개정 2020.2.4>', 5430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9568, '④ 법무부장관은 제3항 각 호에 따른 요건의 충족 여부를 확인하기 위하여 관계 행정기관의 장에게 협조(「형의 실효 등에 관한 법률」 제2조제8호에 따른 범죄경력조회를 포함한다)를 요청하거나 등록대상자에게 필요한 자료의 제출을 요청할 수 있다. 이 경우 협조를 요청받은 관계 행정기관의 장은 지체 없이 이에 따라야 한다. <개정 2020.2.4>', 5430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9569, '① 신상정보의 등록은 다음 각 호의 어느 하나에 해당하는 때에 종료된다.', 5431);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9570, '② 법무부장관은 제1항에 따라 등록이 종료된 신상정보를 즉시 폐기하여야 한다.', 5431);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9571, '③ 법무부장관은 제2항에 따라 등록정보를 폐기하는 경우에는 등록대상자가 정보통신망을 이용하여 폐기된 사실을 열람할 수 있도록 하여야 한다. 다만, 등록대상자가 신청하는 경우에는 폐기된 사실을 통지하여야 한다.', 5431);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9572, '④ 제3항에 따른 등록정보 폐기 사실의 열람, 통지 신청과 통지의 방법 및 절차 등에 필요한 사항은 대통령령으로 정한다.', 5431);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9573, '① 법무부장관은 등록정보를 등록대상 성범죄와 관련한 범죄 예방 및 수사에 활용하게 하기 위하여 검사 또는 각급 경찰관서의 장에게 배포할 수 있다.', 5432);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9574, '② 제1항에 따른 등록정보의 배포절차 및 관리 등에 관한 사항은 대통령령으로 정한다.', 5432);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9575, '① 등록정보의 공개에 관하여는 「아동ㆍ청소년의 성보호에 관한 법률」 제49조, 제50조, 제52조, 제54조, 제55조 및 제65조를 적용한다.', 5433);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9576, '② 등록정보의 공개는 여성가족부장관이 집행한다.', 5433);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9577, '③ 법무부장관은 등록정보의 공개에 필요한 정보를 여성가족부장관에게 송부하여야 한다.', 5433);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9578, '④ 제3항에 따른 정보 송부에 관하여 필요한 사항은 대통령령으로 정한다.', 5433);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9579, '① 등록정보의 고지에 관하여는 「아동ㆍ청소년의 성보호에 관한 법률」 제50조 및 제51조를 적용한다.', 5435);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9580, '② 등록정보의 고지는 여성가족부장관이 집행한다.', 5435);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9581, '③ 법무부장관은 등록정보의 고지에 필요한 정보를 여성가족부장관에게 송부하여야 한다.', 5435);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9582, '④ 제3항에 따른 정보 송부에 관한 세부사항은 대통령령으로 정한다.', 5435);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9583, '① 「군사법원법」 제2조제1항 각 호의 어느 하나에 해당하는 사람(이하 이 조에서 "군인등"이라 한다)에 대하여 군사법원이 재판권을 가지는 경우 제27조제2항ㆍ제6항, 제29조, 제30조, 제33조제1항부터 제4항까지, 제34조, 제40조제1항, 제41조, 제42조제2항ㆍ제4항을 적용함에 있어 "법원"은 "군사법원(고등법원을 포함한다)"으로, "수사기관"은 "군수사기관"으로, "검사"는 "군검사"로, "사법경찰관"은 "군사법경찰관"으로, "국선변호사"는 "변호사 자격이 있는 장교"로 간주한다. <개정 2016.12.20, 2021.9.24, 2023.7.11, 2023.10.24>', 5436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9584, '② 군인등에 대하여 제41조제1항을 적용함에 있어 "사법경찰관"은 "군사법경찰관"으로 간주한다. <개정 2023.7.11>', 5436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9585, '③ 군인등에 대하여 제33조제3항을 적용함(같은 조 제4항에 따라 준용되는 경우에도 같다)에 있어 "법원행정처장"은 "국방부장관"으로 간주한다.', 5436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9586, '① 다음 각 호의 어느 하나에 해당하는 자는 5년 이하의 징역 또는 5천만원 이하의 벌금에 처한다. <개정 2024.12.3>', 5437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9587, '② 다음 각 호의 어느 하나에 해당하는 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다. <개정 2020.10.20>', 5437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9588, '③ 다음 각 호의 어느 하나에 해당하는 자는 1년 이하의 징역 또는 500만원 이하의 벌금에 처한다. <개정 2016.12.20>', 5437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9589, '④ 제2항제2호의 죄는 피해자의 명시한 의사에 반하여 공소를 제기할 수 없다.', 5437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9590, '⑤ 제16조제2항에 따라 이수명령을 부과받은 사람이 보호관찰소의 장 또는 교정시설등의 장의 이수명령 이행에 관한 지시에 불응하여 「보호관찰 등에 관한 법률」 또는 「형의 집행 및 수용자의 처우에 관한 법률」에 따른 경고를 받은 후 재차 정당한 사유 없이 이수명령 이행에 관한 지시에 불응한 경우에는 다음 각 호에 따른다. <개정 2016.12.20, 2024.1.16>', 5437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9591, '① 정당한 사유 없이 제43조의2제1항 또는 제2항을 위반하여 신고하지 아니하거나 거짓으로 신고한 경우에는 300만원 이하의 과태료를 부과한다.', 5439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9592, '② 제1항에 따른 과태료는 대통령령으로 정하는 바에 따라 관할경찰관서의 장이 부과ㆍ징수한다.', 5439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9593, null, 5441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9594, '① 사법경찰관리는 법 제22조의2제1항에 따른 신분비공개수사(이하 "신분비공개수사"라 한다) 또는 같은 조 제2항에 따른 신분위장수사(이하 "신분위장수사"라 한다)를 하는 경우에는 피해자에게 추가 피해가 발생하지 않도록 주의해야 한다.', 5443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9595, '② 사법경찰관리는 법 제22조의2제2항제3호에 따라 촬영물 또는 복제물 등을 소지 또는 광고하는 경우에는 피해자에 관한 자료가 유포되지 않도록 해야 한다.', 5443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9596, '① 법 제22조의2제1항에 따른 신분 비공개는 사법경찰관리임을 밝히지 않거나 부인(법 제22조의2제2항제1호에 이르지 않는 행위로서 사법경찰관리 외의 신분을 고지하는 방식을 포함한다)하는 방법으로 한다.', 5444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9597, '② 법 제22조의2제1항에 따른 접근은 다음 각 호의 방법으로 한다.', 5444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9598, '① 사법경찰관리는 법 제22조의2제2항제3호 단서에 따라 피해자의 동의를 받으려면 법 제22조의3제3항에 따른 신분위장수사에 대한 허가 신청 전(법 제22조의5제1항에 따른 긴급 신분위장수사의 경우에는 촬영물 또는 복제물 등의 제공 또는 판매 전을 말한다)에 피해자에게 신분위장수사의 필요성ㆍ종류ㆍ목적ㆍ대상ㆍ범위ㆍ기간ㆍ장소 및 방법 등을 직접 설명한 후 피해자로부터 경찰청장 또는 해양경찰청장이 정하는 서면으로 동의를 받아야 한다.', 5445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9599, '② 사법경찰관리는 법 제22조의3제8항에 따라 신분위장수사의 수사기간을 연장하려는 경우로서 제1항에 따라 피해자의 동의를 받아야 하는 경우에는 그 연장 신청 전에 제1항에 따라 다시 피해자에게 설명하고 서면 동의를 받아야 한다.', 5445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9600, '③ 사법경찰관리는 피해자가 신체적인 또는 정신적인 장애가 있어 사물을 변별하거나 의사를 결정할 능력이 미약한 경우에는 법 제22조의2제2항제3호 단서에 따른 동의를 받아서는 안 된다.', 5445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9601, '④ 사법경찰관리는 제1항에 따라 피해자의 동의를 받은 후 신분위장수사를 종료하거나 실시하지 않기로 결정한 경우에는 지체 없이 피해자에게 다음 각 호의 사항을 통보해야 한다.', 5445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9602, '⑤ 법 제22조의2제2항제3호에 따른 광고에 촬영물 또는 복제물 등의 영상ㆍ사진ㆍ음성의 전부 또는 일부가 포함되어 있는 경우의 피해자 동의 절차 등에 관하여는 제1항부터 제4항까지의 규정에 따른다. 이 경우 제1항 중 "제공 또는 판매 전"은 "광고 전"으로 한다.', 5445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9603, '① 신분비공개수사를 하려는 사법경찰관리는 법 제22조의3에 따라 신분비공개수사 전(법 제22조의4에 따른 긴급 신분비공개수사의 경우에는 신분비공개수사 개시 후 48시간이 되기 전을 말한다)에 경찰청장 또는 해양경찰청장이 정하는 서면으로 바로 위 상급 경찰관서 수사부서의 장의 승인을 받아야 한다.', 5446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9604, '② 사법경찰관리는 제1항에 따른 승인을 받으려면 신분비공개수사의 필요성ㆍ대상ㆍ범위ㆍ기간ㆍ장소 및 방법 등을 바로 위 상급 경찰관서 수사부서의 장에게 소명해야 한다.', 5446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9605, '③ 사법경찰관리는 신분비공개수사를 종료한 때에는 종료 일시 및 종료 사유 등을 바로 위 상급 경찰관서 수사부서의 장에게 보고해야 한다.', 5446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9606, '① 법 제22조의7제1항에 따른 국가경찰위원회에 대한 보고사항은 신분비공개수사의 승인요청 경찰관서, 승인기간, 종료일시, 종료사유, 수사대상, 수사방법, 사건요지 및 필요성으로 한다.', 5447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9607, '② 법 제22조의7제2항에 따른 국회 소관 상임위원회에 대한 보고사항은 신분비공개수사의 승인요청 경찰관서, 승인기간, 승인건수, 종료일시 및 종료사유로 한다.', 5447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9608, '③ 제1항 및 제2항에 따른 보고는 「정보통신망 이용촉진 및 정보보호 등에 관한 법률」 제2조제1항제1호에 따른 정보통신망(이하 "정보통신망"이라 한다)을 이용하거나, 그 내용을 기록ㆍ보관ㆍ출력할 수 있는 전자적 정보저장매체에 저장하여 제출하는 방법으로 할 수 있다.', 5447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9609, null, 5448);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9610, '① 법 제42조제1항에 따른 신상정보 등록대상자(이하 "등록대상자"라 한다)가 법 제43조제1항에 따라 제출하여야 하는 신상정보(이하 "기본신상정보"라 한다)의 세부 내용은 다음 각 호와 같다. <개정 2015.1.20, 2015.6.22, 2017.6.20>', 5449);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9611, '② 기본신상정보 및 법 제43조제3항에 따른 변경정보(이하 "변경정보"라 한다)는 등록대상자가 자신의 주소지 또는 거주지를 관할하는 경찰관서의 장(이하 "관할경찰관서의 장"이라 한다)에게 직접 방문하여 제출하여야 한다. 다만, 등록대상자가 교정시설 또는 치료감호시설(이하 "교정시설등"이라 한다)에 수용된 경우에는 그 교정시설의 장 또는 치료감호시설의 장(이하 "교정시설등의 장"이라 한다)에게 제출하여야 한다. <개정 2017.6.20>', 5449);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9612, '③ 관할경찰관서의 장 또는 교정시설등의 장은 기본신상정보와 변경정보를 받으면 다음 각 호의 관련 서류를 확인하는 방법으로 그 진위를 확인하여야 한다. <개정 2015.1.20, 2017.6.20, 2024.12.3>', 5449);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9613, '④ 관할경찰관서의 장 또는 교정시설등의 장은 제2항에 따라 기본신상정보와 변경정보를 받으면 기재사항 중 빠진 것이 없는지를 확인한 후 제출 일시를 적은 확인서를 지체 없이 등록대상자에게 발급하여야 한다. 이 경우 다음 각 호의 사항이 기재된 안내문을 함께 교부하여야 한다. <개정 2017.6.20>', 5449);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9614, '⑤ 관할경찰관서의 장 또는 교정시설등의 장은 법 제43조제2항 또는 제4항에 따라 등록대상자의 사진을 촬영할 때에는 선명한 화질을 얻도록 충분히 조명을 밝힌 상태에서 600만 화소 이상의 해상도를 가진 카메라로 촬영하고, 등록대상자의 정면ㆍ좌측ㆍ우측 상반신 및 전신 컬러사진을 각각 구분하여 전자기록으로 저장ㆍ보관하여야 한다. 이 경우 전자기록의 파일명을 등록대상자의 성명과 생년월일로 하여야 한다.', 5449);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9615, '⑥ 교정시설등의 장은 법 제43조제4항 단서에 따라 촬영한 등록대상자 사진의 전자기록과 다음 각 호의 사항을 기재한 서면을 등록대상자가 출소되기 2개월 전까지 법무부장관에게 송달하여야 한다. 다만, 등록대상자가 가석방, 가종료 또는 가출소되는 경우에는 출소 5일 전까지 법무부장관에게 송달하여야 한다.', 5449);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9616, '⑦ 기본신상정보와 변경정보에 관한 제출 서식 및 신상정보 제출 확인서 등에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2017.6.20>', 5449);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9617, '① 법 제43조의2제1항에 따라 등록대상자는 6개월 이상 국외에 체류하기 위하여 출국하는 경우 출국하기 전까지 관할경찰관서의 장에게 법무부령으로 정하는 출국신고서를 제출하여야 한다.', 5451);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9618, '② 제1항에 따라 출국신고서를 제출한 등록대상자는 사정변경 등으로 출국을 하지 아니하거나 출국 후 입국 예정일까지 입국을 할 수 없게 된 경우에는 지체없이 관할경찰관서의 장에게 알려야 한다.', 5451);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9619, '③ 등록대상자는 법 제43조의2제2항에 따라 입국한 날부터 14일 이내에 관할경찰관서의 장에게 법무부령으로 정하는 입국신고서를 제출하여야 한다. 다만, 그 기간 내에 입국신고서를 제출할 수 없는 특별한 사정이 있는 경우에는 그 사유가 소멸한 날부터 7일 이내에 소명자료를 첨부하여 입국신고서를 제출하여야 한다.', 5451);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9620, '④ 법 제43조의2제3항에 따라 관할경찰관서의 장은 제1항에 따른 출국신고서 및 제3항에 따른 입국신고서 등 등록대상자의 출입국에 관한 정보를 등기우편으로 법무부장관에게 송달하여야 한다.', 5451);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9621, '① 법무부장관은 법 제43조제5항ㆍ제6항 및 법 제43조의2제3항에 따라 관할경찰관서의 장 또는 교정시설등의 장으로부터 송달받은 정보와 법 제44조제4항 전단에 따라 관계 행정기관의 장으로부터 조회된 내용을 확인한 후 성범죄자 등록정보 원부(이하 "등록정보원부"라 한다)에 등록하여야 한다. <개정 2017.6.20>', 5452);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9622, '② 법 제44조제1항 각 호의 등록대상자 정보의 세부 내용은 다음 각 호와 같다. <개정 2020.8.5>', 5452);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9623, '③ 등록정보원부의 서식과 작성 방식 등에 관한 구체적인 사항은 법무부령으로 정한다.', 5452);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9624, '① 법 제44조제1항 또는 제4항 전단에 따라 등록한 정보(이하 "등록정보"라 한다)의 열람은 등록대상자가 「형사사법절차 전자화 촉진법」 제2조제6호에 따른 형사사법포털(이하 이 조에서 "형사사법포털"이라 한다)에 접속하여 열람하는 방법으로 한다.', 5453);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9625, '② 제1항에 따른 등록정보의 열람은 등록대상자 본인 외에는 할 수 없다.', 5453);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9626, '③ 형사사법포털의 접속절차ㆍ방법 등 그 밖에 등록정보의 열람에 필요한 사항은 법무부장관이 정한다.', 5453);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9627, '① 등록대상자는 법 제44조제2항 단서에 따라 등록정보의 통지를 신청하거나 그 신청을 철회하려는 경우에는 법무부령으로 정하는 신청서를 직접 방문하거나 등기우편으로 법무부장관에게 제출하여야 한다.', 5454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9628, '② 법무부장관은 법 제44조제2항 단서 또는 같은 조 제4항 후단에 따라 등록정보를 통지하여야 하는 경우에는 등기우편으로 그 내용을 통지하여야 한다.', 5454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9629, '① 법무부장관은 법 제45조제7항 및 제8항에 따라 등록정보의 진위와 변경 여부를 확인하기 위하여 필요하면 성범죄자 등록정보를 관할경찰관서의 장에게 제공할 수 있다. <개정 2017.6.20>', 5455);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9630, '② 법 제45조제7항에 따른 직접 대면 등의 방법은 등록대상자를 경찰관서에 출석시키는 방법을 포함한다. <개정 2017.6.20>', 5455);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9631, '③ 법 제45조제7항 및 제8항에 따라 관할경찰관서의 장으로부터 등록정보의 진위와 변경 여부 확인 결과를 송부받은 법무부장관은 그 내용을 확인한 후 변경된 정보를 등록정보원부에 등록하여야 한다. <개정 2017.6.20>', 5455);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9632, '① 법 제45조의2제2항에 따른 신상정보 등록의 면제를 신청하려는 등록대상자(이하 "면제 신청인"이라 한다)는 법무부령으로 정하는 신청서를 직접 방문하거나 등기우편으로 법무부장관에게 제출하여야 한다.', 5456);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9633, '② 제1항에 따른 면제 신청인으로부터 신상정보 등록의 면제 신청을 받은 법무부장관은 법 제45조의2제2항 각 호의 기간 경과 여부와 법 제45조의2제3항 각 호에 따른 면제 요건 충족 여부를 확인한 후 등록의 면제신청을 받은 날부터 20일 이내에 신상정보 등록의 면제 여부를 결정하여야 한다. 이 경우 법 제45조의2제2항 각 호의 기간 경과 여부는 등록면제 신청일을 기준으로 하고, 법 제45조의2제3항 각 호에 따른 면제 요건 충족 여부는 등록면제 결정일을 기준으로 한다.', 5456);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9634, '③ 법무부장관은 면제 신청인이 등록의 면제 여부의 결과를 정보통신망을 이용하여 열람할 수 있도록 하여야 한다. 다만, 면제 신청인이 요청하는 경우에는 등기우편으로 통지하여야 한다.', 5456);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9635, '④ 제3항에 따른 등록면제 신청 결과의 열람 방법 등에 관하여는 제5조의2를 준용한다.', 5456);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9636, '① 법 제45조의3제3항 본문에 따른 등록정보 폐기 사실의 열람 방법 등에 관하여는 제5조의2를 준용한다.', 5457);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9637, '② 법 제45조의3제3항 본문에 따라 등록정보 폐기 사실을 열람할 수 있는 기간은 법 제45조의3제1항에 따라 등록이 종료된 때부터 1년으로 한다.', 5457);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9638, '① 등록대상자는 법 제45조의3제3항 단서에 따라 등록정보 폐기사실의 통지를 신청하거나 그 신청을 철회하려는 경우 법무부령으로 정하는 신청서를 직접 방문하거나 등기우편으로 법무부장관에게 제출하여야 한다.', 5458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9639, '② 법무부장관은 제1항에 따라 등록정보 폐기 사실의 통지 신청을 받은 경우 등기우편으로 그 내용을 통지하여야 한다.', 5458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9640, '③ 법무부장관은 법 제44조제4항 전단에 따라 등록된 신상정보가 법 제45조의3제2항에 따라 폐기된 경우에는 등기우편으로 해당 등록대상자에게 그 사실을 통지하여야 한다.', 5458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9641, '① 법무부장관은 법 제46조제1항에 따른 등록정보의 배포를 갈음하여 검사나 각급 경찰관서의 장에게 법무부장관이 운영하는 정보통신망에 접속하여 등록정보를 조회하거나 출력하게 할 수 있다.', 5459);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9642, '② 제1항에 따라 출력된 등록정보는 그 활용 목적을 다하거나 법 제45조의3제1항에 따라 신상정보의 등록이 종료되면 즉시 폐기하여야 한다. <개정 2017.6.20>', 5459);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9643, '① 법무부장관은 법 제47조제3항과 제49조제3항에 따라 등록정보의 공개와 고지에 필요한 정보(제6조제3항에 따라 등록정보원부에 등록한 변경된 정보를 포함한다)를 등록정보원부에 등록한 후 지체 없이 여성가족부장관에게 송부하여야 한다.', 5460);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9644, '② 제1항에 따른 정보의 송부는 행정기관의 정보통신망 등을 이용하여 한다.', 5460);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9645, '① 법무부장관, 검사 또는 사법경찰관은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 5461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9646, '② 법무부장관, 여성가족부장관, 검사, 관할경찰관서의 장, 각급 경찰관서의 장, 교정시설등의 장, 관계 행정기관의 장 또는 사법경찰관은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강 및 성생활에 관한 정보, 같은 법 시행령 제18조제1호 및 제2호에 따른 유전정보 및 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2017.6.20>', 5461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9647, '③ 법 제27조제6항에 따른 국선변호사 또는 법 제35조에 따른 진술조력인은 다음 각 호의 업무를 수행하기 위하여 불가피한 경우 제2항에 따른 개인정보가 포함된 자료를 처리할 수 있다.', 5461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9648, '① 「성폭력범죄의 처벌 등에 관한 특례법 시행령」(이하 "영"이라 한다) 제3조제4항 전단에 따른 신상정보의 제출 확인서는 별지 제2호서식과 같다.', 5465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9649, '② 영 제3조제4항 후단에 따른 안내문은 별지 제3호서식과 같다.', 5465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9650, '① 영 제4조의2제1항에 따른 출국신고서는 별지 제5호서식과 같다.', 5467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9651, '② 영 제4조의2제3항에 따른 입국신고서는 별지 제6호서식과 같다.', 5467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9652, '① 영 제5조의3제1항에 따른 통지의 신청 또는 그 철회의 신청은 별지 제8호서식에 따른다.', 5469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9653, '② 영 제5조의3제2항에 따른 등록정보의 통지는 별지 제9호서식에 따른다.', 5469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9654, '① 법 제45조의2제2항 및 영 제6조의2제1항에 따른 신상정보 등록 면제 신청서는 별지 제11호서식과 같다.', 5471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9655, '② 영 제6조의2제3항 단서에 따른 신상정보 등록 면제 신청 결과의 통지는 별지 제12호서식에 따른다.', 5471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9656, '① 영 제6조의4제1항에 따른 등록정보 폐기 사실의 통지 신청 또는 그 철회 신청은 별지 제13호서식에 따른다.', 5472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9657, '② 영 제6조의4제2항 및 제3항에 따른 등록정보 폐기 사실의 통지는 별지 제14호서식에 따른다.', 5472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9658, null, 5475);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9659, '① 차의 운전자가 교통사고로 인하여 「형법」 제268조의 죄를 범한 경우에는 5년 이하의 금고 또는 2천만원 이하의 벌금에 처한다.', 5476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9660, '② 차의 교통으로 제1항의 죄 중 업무상과실치상죄(業務上過失致傷罪) 또는 중과실치상죄(重過失致傷罪)와 「도로교통법」 제151조의 죄를 범한 운전자에 대하여는 피해자의 명시적인 의사에 반하여 공소(公訴)를 제기할 수 없다. 다만, 차의 운전자가 제1항의 죄 중 업무상과실치상죄 또는 중과실치상죄를 범하고도 피해자를 구호(救護)하는 등 「도로교통법」 제54조제1항에 따른 조치를 하지 아니하고 도주하거나 피해자를 사고 장소로부터 옮겨 유기(遺棄)하고 도주한 경우, 같은 죄를 범하고 「도로교통법」 제44조제2항을 위반하여 음주측정 요구에 따르지 아니하거나(운전자가 채혈 측정을 요청하거나 동의한 경우는 제외한다), 「도로교통법」 제44조제5항을 위반하여 음주측정방해행위를 한 경우와 다음 각 호의 어느 하나에 해당하는 행위로 인하여 같은 죄를 범한 경우에는 그러하지 아니하다. <개정 2016.1.27, 2016.12.2, 2025.1.7>', 5476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9661, '① 교통사고를 일으킨 차가 「보험업법」 제4조, 제126조, 제127조 및 제128조, 「여객자동차 운수사업법」 제60조, 제61조 또는 「화물자동차 운수사업법」 제51조에 따른 보험 또는 공제에 가입된 경우에는 제3조제2항 본문에 규정된 죄를 범한 차의 운전자에 대하여 공소를 제기할 수 없다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그러하지 아니하다.', 5477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9662, '② 제1항에서 "보험 또는 공제"란 교통사고의 경우 「보험업법」에 따른 보험회사나 「여객자동차 운수사업법」 또는 「화물자동차 운수사업법」에 따른 공제조합 또는 공제사업자가 인가된 보험약관 또는 승인된 공제약관에 따라 피보험자와 피해자 간 또는 공제조합원과 피해자 간의 손해배상에 관한 합의 여부와 상관없이 피보험자나 공제조합원을 갈음하여 피해자의 치료비에 관하여는 통상비용의 전액을, 그 밖의 손해에 관하여는 보험약관이나 공제약관으로 정한 지급기준금액을 대통령령으로 정하는 바에 따라 우선 지급하되, 종국적으로는 확정판결이나 그 밖에 이에 준하는 집행권원(執行權原)상 피보험자 또는 공제조합원의 교통사고로 인한 손해배상금 전액을 보상하는 보험 또는 공제를 말한다.', 5477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9663, '③ 제1항의 보험 또는 공제에 가입된 사실은 보험회사, 공제조합 또는 공제사업자가 제2항의 취지를 적은 서면에 의하여 증명되어야 한다.', 5477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9664, '① 보험회사, 공제조합 또는 공제사업자의 사무를 처리하는 사람이 제4조제3항의 서면을 거짓으로 작성한 경우에는 3년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 5478);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9665, '② 제1항의 거짓으로 작성된 문서를 그 정황을 알고 행사한 사람도 제1항의 형과 같은 형에 처한다.', 5478);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9666, '③ 보험회사, 공제조합 또는 공제사업자가 정당한 사유 없이 제4조제3항의 서면을 발급하지 아니한 경우에는 1년 이하의 징역 또는 300만원 이하의 벌금에 처한다.', 5478);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9667, '①법 제4조제2항에 따라 우선 지급해야 할 치료비에 관한 통상비용의 범위는 다음 각 호와 같다. <개정 2021.1.5>', 5481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9668, '②치료비에 관한 통상비용의 계산에 있어서 피해자가 외국에서 치료를 받은 경우의 제1항 각호의 비용은 국내의료기관에서 동일한 치료를 하는 경우 그에 상당한 비용으로 한다. 다만, 국내의료기관에서 치료가 불가능하여 외국에서 치료를 받은 경우에는 그에 소요되는 비용으로 한다.', 5481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9669, '①법 제4조제2항의 규정에 의하여 우선지급하여야 할 치료비외의 손해배상금의 범위는 다음 각호와 같다.', 5482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9670, '②제1항제1호 및 제2호의 규정에 의한 위자료가 중복되는 경우에는 보험약관 또는 공제약관이 정하는 바에 의하여 지급한다.', 5482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9671, '①피해자가 제2조 및 제3조의 규정에 의한 손해배상금의 우선지급을 받고자 하는 때에는 금융위원회 또는 국토교통부장관이 정하는 바에 의하여 보험사업자 또는 공제사업자에게 손해배상금우선지급의 청구를 하여야 한다. <개정 1994ㆍ12ㆍ23, 1999.5.24, 2008.2.29, 2008.12.31, 2013.3.23>', 5483);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9672, '②제1항의 규정에 의하여 손해배상금우선지급의 청구를 받은 보험사업자 또는 공제사업자는 그 청구를 받은 날로부터 7일이내에 이를 지급하여야 한다.', 5483);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9673, '③피해자가 「자동차손해배상 보장법」 제10조 및 제11조에 따라 손해배상액 또는 가불금을 지급받은 때에는 보험사업자 또는 공제사업자는 손해배상금의 우선지급액에서 이를 공제할 수 있다. <개정 2008.9.25>', 5483);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9674, null, 5487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9675, '① 검찰총장 및 경찰청장은 다음 각 호의 업무에 이용하기 위하여 하드웨어, 소프트웨어, 데이터베이스, 네트워크, 보안요소 등이 결합되어 구축된 디엔에이인적관리시스템(이하 "인적관리시스템"이라 한다)을 서로 연계하여 운영하는 등 필요한 조치를 하여야 한다.', 5488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9676, '② 인적관리시스템은 「형사사법절차 전자화 촉진법」에 따른 형사사법정보시스템을 이용할 수 있다.', 5488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9677, '① 검찰총장 및 경찰청장은 식별코드의 생성ㆍ부착 및 제3조제1항 각 호의 업무를 담당할 디엔에이인적관리자를 소속 공무원 중에서 지정할 수 있다.', 5489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9678, '② 디엔에이인적관리자는 인적관리시스템에 정보를 입력하거나 수정ㆍ삭제하기 위하여 그가 소속된 기관의 공무원 중에서 인적관리시스템에 접속할 권한을 부여받을 사람을 지정할 수 있다.', 5489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9679, '③ 디엔에이인적관리자는 검사 또는 사법경찰관이 디엔에이감식시료의 중복 채취 확인, 관련 사건의 수사 등을 위하여 인적관리시스템을 열람할 수 있도록 조치할 수 있다.', 5489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9680, '④ 디엔에이인적관리자는 인적관리시스템을 검색한 결과 법 제5조 및 제6조에 따른 디엔에이감식시료 채취대상자에 대한 디엔에이감식시료 채취가 누락된 사실을 발견한 경우 지체 없이 검사(군검사를 포함한다. 이하 같다) 또는 사법경찰관(군사법경찰관을 포함한다. 이하 같다)에게 그 사실을 통보하여야 한다. <개정 2022.6.30>', 5489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9681, '① 검사는 법 제5조제2항에 따라 디엔에이감식시료의 채취를 위탁하기 위하여 교도소ㆍ구치소 및 그 지소, 소년원, 치료감호시설 등(이하 "수용기관"이라 한다)의 장에게 디엔에이감식시료 채취대상자의 확인 및 디엔에이감식시료 채취의 위탁에 필요한 자료를 요청할 수 있다.', 5491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9682, '② 법 제5조제2항에 따라 검사로부터 디엔에이감식시료의 채취를 위탁받은 수용기관의 장은 지체 없이 법 제5조에 따른 디엔에이감식시료 채취대상자로부터 디엔에이감식시료를 채취하고, 채취한 디엔에이감식시료와 다음 각 호의 서류를 즉시 검사에게 보내야 한다.', 5491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9683, '① 검찰총장 및 경찰청장은 법 제8조에 따라 디엔에이감식시료를 채취하기 위한 영장(이하 "디엔에이감식시료채취영장"이라 한다)이 발부되고 검사의 지명수배ㆍ통보 결정이 있는 경우 검사 또는 사법경찰관리가 지명수배ㆍ통보관리와 관련된 전산자료를 통하여 그 사실을 조회할 수 있도록 하여야 한다.', 5492);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9684, '② 법 제5조 또는 제6조에 따른 디엔에이감식시료 채취대상자에 대하여 법 제8조제6항에 따라 디엔에이감식시료채취영장의 집행지휘를 받은 사법경찰관리 또는 수용기관 소속 공무원은 지체 없이 디엔에이감식시료 채취대상자로부터 디엔에이감식시료를 채취하여야 한다.', 5492);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9685, '③ 제2항에 따라 디엔에이감식시료를 채취한 사법경찰관 또는 수용기관 소속 공무원은 채취한 디엔에이감식시료와 다음 각 호의 서류를 즉시 검사에게 보내야 한다. 다만, 법 제8조제6항에 따라 디엔에이감식시료채취영장의 집행지휘를 받은 사법경찰관(수용기관 소속의 사법경찰관은 제외한다)이 법 제6조에 따른 디엔에이감식시료 채취대상자로부터 디엔에이감식시료를 채취한 경우는 제외한다.', 5492);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9686, '① 법 제5조 또는 제6조에 따른 디엔에이감식시료 채취대상자로부터 디엔에이감식시료를 채취할 때에는 다음 각 호의 어느 하나에 해당하는 방법으로 하여야 한다.', 5493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9687, '② 검찰총장 및 경찰청장은 법 제5조부터 제8조까지의 규정에 따라 디엔에이감식시료를 채취하는 경우 디엔에이감식시료가 부패 또는 오염되거나 다른 디엔에이감식시료와 바뀌지 않도록 디엔에이감식시료의 채취, 운반 및 보관에 필요한 조치를 하여야 한다.', 5493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9688, '① 검사 또는 사법경찰관은 법 제5조 또는 제6조에 따른 디엔에이감식시료 채취대상자로부터 채취한 디엔에이감식시료와 다음 각 호의 서류를 제4조제1항에 따라 검찰총장이 지정한 디엔에이인적관리자(이하 "검찰 디엔에이인적관리자"라 한다) 또는 제4조제1항에 따라 경찰청장이 지정한 디엔에이인적관리자(이하 "경찰 디엔에이인적관리자"라 한다)에게 보내야 한다.', 5495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9689, '② 제1항에 따라 디엔에이감식시료를 건네받은 디엔에이인적관리자는 식별코드를 생성하여 디엔에이감식시료를 담은 봉투, 용기 등에 부착하고 인적관리시스템에 인적사항등과 식별코드를 입력한 후 지체 없이 그 디엔에이감식시료를 법 제10조 및 이 영 제12조제1항에 따라 법 제10조제1항 각 호의 업무를 위임받은 대검찰청 과학수사기획관(이하 "검찰 디엔에이신원확인정보담당자"라 한다) 또는 법 제10조 및 이 영 제12조제2항제1호에 따라 법 제10조제1항 각 호의 업무를 위탁받은 국립과학수사연구원(이하 "경찰 디엔에이신원확인정보담당자"라 한다)에 보내야 한다. <개정 2010.8.13>', 5495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9690, '③ 검찰 디엔에이신원확인정보담당자는 검사가 법 제6조에 따른 디엔에이감식시료 채취대상자로부터 채취한 디엔에이감식시료에서 취득한 디에이신원확인정보를 지체 없이 경찰 디엔에이신원확인정보담당자에게 보내야 한다.', 5495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9691, '① 검사 또는 사법경찰관은 법 제7조에 따라 채취한 디엔에이감식시료를 지체 없이 다음 각 호의 구분에 따른 사람 또는 기관에게 보내야 한다.', 5496);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9692, '② 검찰 디엔에이신원확인정보담당자 또는 군 디엔에이감식기관은 제1항에 따라 건네받은 디엔에이감식시료에서 취득한 디엔에이신원확인정보 중 신원이 밝혀지지 아니한 것을 지체 없이 경찰 디엔에이신원확인정보담당자에게 보내야 한다.', 5496);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9693, '① 검찰총장은 법 제10조제1항에 따라 같은 항 각 호의 업무를 대검찰청 과학수사기획관에게 위임한다.', 5497);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9694, '② 법 제10조제1항에 따른 경찰청장 업무의 위탁은 다음 각 호의 구분에 따른다. <개정 2010.8.13>', 5497);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9695, '① 검찰 디엔에이신원확인정보담당자ㆍ경찰 디엔에이신원확인정보담당자(이하 "디엔에이신원확인정보담당자"라 한다) 및 군 디엔에이감식기관은 디엔에이감식에 필요한 시설과 장비, 신뢰성 높은 디엔에이감식기법의 사용 등과 관련하여 국제공인시험기관으로 인정받은 기관에서 디엔에이감식을 하고, 감정서를 작성하여야 한다.', 5498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9696, '② 디엔에이신원확인정보담당자 및 군 디엔에이감식기관은 디엔에이감식과 관련하여 디엔에이감식시료가 부패 또는 오염되거나 다른 시료와 바뀌지 않도록 디엔에이감식시료의 취급에 필요한 조치를 하여야 한다.', 5498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9697, '③ 디엔에이신원확인정보담당자 및 군 디엔에이감식기관은 디엔에이감식시료 부족 등의 사유로 디엔에이신원확인정보를 확인하기 어려운 경우 검사 또는 사법경찰관에게 그 사유를 적어 디엔에이감식시료를 다시 채취해 줄 것을 요청할 수 있다.', 5498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9698, '① 디엔에이신원확인정보담당자는 데이터베이스에 수록된 정보가 유출되거나 임의로 변경, 삭제 또는 멸실되는 것을 방지하기 위하여 데이터베이스에 보안장치 등 필요한 조치를 취하여야 한다.', 5499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9699, '② 디엔에이신원확인정보담당자는 데이터베이스에 정보를 입력하거나 수정ㆍ삭제하거나 검색하기 위하여 그가 소속된 기관의 공무원 중에서 데이터베이스에 접속할 권한을 부여받을 사람을 지정할 수 있다.', 5499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9700, '① 법 제11조제1항에 따라 디엔에이신원확인정보의 검색결과를 회보할 디엔에이신원확인정보담당자는 다음 각 호의 구분에 따른다.', 5500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9701, '② 법 제11조제1항에 따른 디엔에이신원확인정보 검색결과를 회보받을 사람은 다음 각 호의 구분에 따른다.', 5500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9702, '③ 제2항에 따라 디엔에이신원확인정보의 검색결과를 회보받은 사람은 검찰 디엔에이인적관리자 또는 경찰 디엔에이인적관리자에게 디엔에이신원확인정보 검색결과의 회보와 관련된 인적사항등을 확인해 줄 것을 요청할 수 있다.', 5500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9703, '④ 법 제11조제1항에 따라 디엔에이신원확인정보를 검색한 결과 다른 디엔에이신원확인정보담당자가 관리하는 데이터베이스에 수록된 디엔에이신원확인정보와 대조하려는 디엔에이신원확인정보가 일치하거나 중복한다는 사실을 발견한 디엔에이신원확인정보담당자는 지체 없이 그 데이터베이스를 관리하는 디엔에이신원확인정보담당자, 그 데이터베이스에 수록된 디엔에이신원확인정보와 관련된 인적사항등을 관리하는 디엔에이인적관리자 및 검색을 요청하거나 사건을 담당하는 검사 또는 사법경찰관에게 그 사실을 감정서 등의 서면, 유선 또는 팩스 등의 방법으로 통보해야 한다. <개정 2021.1.5>', 5500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9704, '⑤ 제4항에 따른 통보를 받은 디엔에이인적관리자는 디엔에이신원확인정보의 검색을 요청하거나 사건을 담당하는 검사 또는 사법경찰관에게 인적사항등을 확인해 줄 수 있다.', 5500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9705, '⑥ 제1항제1호 및 제2호에 따른 디엔에이신원확인정보담당자로부터 디엔에이신원확인정보의 검색결과를 회보받은 검사 또는 사법경찰관은 해당 디엔에이감식시료 채취대상자로부터 시료를 다시 채취하여 검색결과를 회보한 디엔에이신원확인정보담당자에게 다시 감식해 줄 것을 요청할 수 있다.', 5500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9706, '① 디엔에이신원확인정보담당자는 법 제12조제1항에 따라 지정된 장소에서 소각하거나 화학적 처리 등을 통하여 디엔에이감식시료의 재분석을 불가능하게 하는 방법으로 디엔에이감식시료와 그로부터 추출한 디엔에이 및 감식과정에서 발생한 부산물을 폐기하여야 한다.', 5501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9707, '② 디엔에이신원확인정보담당자는 제1항에 따라 디엔에이감식시료와 그로부터 추출한 디엔에이 및 감식과정에서 발생한 부산물을 폐기한 경우 폐기 일시와 장소, 폐기한 디엔에이감식시료의 종류, 폐기 방법 등을 적은 자료를 보존하여야 한다. 이 경우 그 자료를 전자적 문서 또는 데이터베이스를 통하여 관리할 수 있다.', 5501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9708, '① 법 제13조에 따른 디엔에이신원확인정보의 삭제 사유가 발생한 경우 검사, 사법경찰관 또는 수용기관의 장은 다음 각 호의 구분에 따라 디엔에이인적관리자에게 그 사실을 통보하여야 한다.', 5502);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9709, '② 제1항에 따라 통보를 받은 디엔에이인적관리자는 법 제5조 또는 제6조에 따른 디엔에이감식시료 채취대상자의 디엔에이신원확인정보를 법 제13조제1항부터 제3항까지의 규정에 따라 삭제하여야 하는지를 확인하기 위하여 인적관리시스템을 검색할 수 있다.', 5502);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9710, '③ 제2항에 따른 검색 결과 디엔에이신원확인정보를 삭제하여야 하는 경우 디엔에이인적관리자는 인적관리시스템에서 인적사항등 및 식별코드를 삭제한 후 검찰 디엔에이신원확인정보담당자 또는 경찰 디엔에이신원확인정보담당자에게 삭제한 식별코드를 통보하여야 한다.', 5502);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9711, '④ 디엔에이신원확인정보를 삭제한 디엔에이신원확인정보담당자는 법 제13조제5항에 따라 디엔에이신원확인정보 삭제 사실을 서면, 전자우편, 문자전송 또는 팩스의 방법으로 통지해야 한다. <개정 2021.1.5>', 5502);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9712, null, 5503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9713, '① 법 제14조에 따른 디엔에이신원확인정보데이터베이스관리위원회(이하 "위원회"라 한다)의 위원장은 위원회를 대표하고 위원회의 업무를 총괄한다.', 5504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9714, '② 위원회의 위원장은 위원회의 회의를 소집하고 그 의장이 된다.', 5504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9715, '③ 위원장이 부득이한 사유로 그 직무를 수행할 수 없는 때에는 위원장이 미리 지명한 위원이 그 직무를 대행한다.', 5504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9716, '④ 위원회의 회의는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.', 5504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9717, '⑤ 위원회의 사무를 처리하기 위하여 위원회에 간사 2명을 두며, 간사는 디엔에이신원확인정보의 이용 및 보호에 관련한 업무에 종사하거나 관련 지식이 풍부한 대검찰청 및 경찰청 소속 공무원 중에서 검찰총장 및 경찰청장이 각 1명씩을 임명한다.', 5504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9718, '⑥ 위원회에서 심의할 안건을 검토하고 위원회의 운영을 지원하기 위하여 위원회에 실무위원회를 둔다.', 5504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9719, '⑦ 제1항부터 제6항까지에서 규정한 사항 외에 위원회 및 실무위원회의 운영에 필요한 사항은 위원회의 의결을 거쳐 위원장이 정한다.', 5504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9720, null, 5505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9721, '① 법원, 검사, 피고인 또는 변호인 그 밖의 소송관계인은 심리ㆍ재판 과정에서 피해자의 주소ㆍ성명ㆍ나이ㆍ직업ㆍ학교ㆍ용모 그 밖에 피해자를 특정하여 파악할 수 있는 인적사항 등이 공개되거나 타인에게 누설되지 않도록 노력하여야 한다.', 5508);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9722, '② 법원, 검사, 피고인 또는 변호인 그 밖의 소송관계인은 심리ㆍ재판 과정에서 피해자의 인권과 특성을 배려하고, 당해 사건과 무관한 피해자의 사생활에 관한 신문 또는 진술이 이루어지거나 피해자가 성적 수치심 또는 공포감을 느낄 수 있는 상황이 발생하지 않도록 노력하여야 한다.', 5508);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9723, '① 법원은 성폭력범죄, 아동ㆍ청소년대상 성범죄 또는 아동학대범죄의 피해자 및 그 법정대리인이 변호사를 선임하거나 검사가 피해자를 위하여 국선변호사를 선정한 경우, 그 변호사(이하 "피해자 변호사"라 한다)의 선임 등을 증명할 수 있는 서류가 제출된 때에는 피해자 변호사에게 공판기일을 통지한다. <개정 2014.9.1>', 5510);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9724, '② 제1항의 통지는 서면, 전화, 전자우편, 모사전송, 휴대전화 문자전송 그 밖에 적당한 방법으로 할 수 있다.', 5510);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9725, '① 법원은 공판절차에서 피해자 변호사로부터 피해의 정도 및 결과, 피고인의 처벌에 관한 의견, 그 밖에 당해 사건에 관한 의견 진술의 신청이 있는 때에는 공판기일에서 그 의견을 진술하게 한다.', 5512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9726, '② 제1항에 따른 의견진술의 신청은 제4조제1항에서 정한 서류가 법원에 제출된 이후 또는 제출과 함께 할 수 있다.', 5512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9727, '③ 재판장은 재판의 진행상황 등을 고려하여 상당한 범위 내에서 피해자 변호사의 의견진술의 순서와 시간을 정할 수 있다.', 5512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9728, '④ 재판장은 피해자 변호사의 의견진술에 대하여 그 취지를 명확하게 하기 위하여 피해자 변호사에게 질문할 수 있고, 설명을 촉구할 수 있다.', 5512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9729, '⑤ 합의부원은 재판장에게 알리고 제4항의 행위를 할 수 있다.', 5512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9730, '⑥ 검사, 피고인 또는 변호인은 피해자 변호사가 의견을 진술한 후 그 취지를 명확하게 하기 위하여 재판장의 허가를 받아 피해자 변호사에게 질문할 수 있다.', 5512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9731, '⑦ 재판장은 다음 각 호의 어느 하나에 해당하는 경우에는 피해자 변호사의 의견진술이나 검사, 피고인 또는 변호인의 피해자 변호사에 대한 질문을 제한할 수 있다.', 5512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9732, '① 제6조제1항의 신청을 받은 법원은 의견진술을 신청한 피해자 변호사에게 의견진술을 할 기일을 통지하여야 한다.', 5513);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9733, '② 제1항의 통지를 한 때에는 검사 및 피고인 또는 변호인에게도 해당 기일에 피해자 변호사의 의견진술이 있을 예정이라는 취지를 통지하여야 한다.', 5513);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9734, '③ 제6조제1항에 따른 의견진술 신청인이 의견진술을 할 기일을 통지받고도 정당한 이유 없이 출석하지 아니한 때에는 그 신청을 철회한 것으로 본다.', 5513);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9735, '④ 제4조제2항의 규정은 제1항 및 제2항의 통지에 준용한다.', 5513);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9736, '① 재판장은 제6조제7항의 사유가 있거나 재판의 진행상황 기타의 사정을 고려하여 의견의 진술이 상당하지 아니하다고 인정하는 때에는 피해자 변호사에게 의견의 진술에 갈음하여 의견을 기재한 서면을 제출하도록 할 수 있다.', 5514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9737, '② 피해자 변호사의 의견진술에 갈음하는 서면이 법원에 제출된 때에는 검사 및 피고인 또는 변호인에게 그 취지를 통지하여야 한다.', 5514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9738, '③ 제1항에 따라 서면이 제출된 경우 재판장은 공판기일에서 의견진술에 갈음하는 서면의 취지를 명확하게 하여야 한다. 이 경우 재판장은 상당하다고 인정하는 때에는 그 서면을 낭독하거나 요지를 고지할 수 있다.', 5514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9739, '④ 제4조제2항의 규정은 제2항의 통지에 준용한다.', 5514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9740, '① 「성폭력범죄의 처벌 등에 관한 특례법」 제27조제4항(다른 법률에서 위 규정을 준용하는 경우를 포함한다)에 따른 피해자 변호사의 관계 서류나 증거물에 대한 열람ㆍ등사의 신청은 서면으로 하여야 한다. <개정 2014.9.1>', 5518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9741, '② 제1항의 신청을 할 때에는 열람ㆍ등사할 서류나 증거물을 특정하고, 그 서류나 증거물의 열람ㆍ등사가 피해자 등의 피해 방어와 피해자 등에 대한 법률적 조력을 위하여 필요한 사유를 소명하여야 한다.', 5518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9742, '① 고등법원, 지방법원 및 그 지원에 증인지원관을 둔다.', 5519);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9743, '② 증인지원관은 증인의 보호와 지원에 필요한 경력ㆍ인품ㆍ적성을 고려하여 특별한 사정이 없는 한 법원사무관, 법원주사 또는 법원주사보 중에서 배치한다.', 5519);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9744, '③ 고등법원장은 증인지원관의 업무 수행에 지장이 없는 범위 내에서 지방법원 소속 증인지원관으로 하여금 고등법원 증인지원관을 겸임하게 할 수 있다.', 5519);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9745, '① 각급 법원은 증인지원관에 대하여 증인의 보호ㆍ지원 업무에 필요한 이론과 실무능력 및 인권 감수성을 향상하기 위하여 증인지원관의 직무에 관한 기본교육을 실시한다.', 5520);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9746, '② 제1항의 교육은 법원공무원교육원이 관장한다.', 5520);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9747, '③ 증인지원관은 특별한 사정이 없는 한 보임된 날로부터 1년 이내에 제1항에서 정한 기본교육을 받아야 한다.', 5520);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9748, '④ 법원행정처는 각급 법원의 증인지원관 교육을 위하여 필요한 지원을 하고, 각급 법원 증인지원관의 소양과 전문성을 높이기 위한 교육을 실시할 수 있다.', 5520);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9749, '① 증인지원관은 다음 각 호의 업무를 수행한다.', 5521);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9750, '② 증인지원관은 증인이 「특정범죄신고자 등 보호법」 제13조제1항(다른 법률에서 위 규정을 준용하는 경우를 포함한다)에 따른 신변안전조치를 받는 경우 관할 경찰서 소속 공무원의 법원 내에서의 신변안전조치에 협력한다. <개정 2014.9.1>', 5521);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9751, '③ 증인지원관은 증인지원 사건의 업무현황에 관하여 법원행정처장에게 정기적으로 서면 보고하여야 한다.', 5521);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9752, '① 각급 법원은 다음 각 호의 사항을 심의하기 위하여 증인지원위원회(이하 "위원회"라 한다)를 둔다.', 5522);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9753, '② 각급 법원장(지원의 경우에는 지원장)은 위원회의 심의 결과를 존중하여야 한다.', 5522);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9754, '③ 위원회의 구성 및 운영에 관한 사항은 각급 법원의 내규로 정한다.', 5522);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9755, '①「성폭력범죄의 처벌 등에 관한 특례법」 제37조제1항(다른 법률에서 위 규정을 준용하는 경우를 포함한다, 이하 같다), 「장애인복지법」제59조의16제1항에 따른 진술조력인 재판과정 참여의 신청은 기일에서 하는 경우를 제외하고는 서면으로 하여야 한다. <개정 2014.9.1, 2022.1.28>', 5523);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9756, '② 제1항의 신청을 할 때에는 신청 이유를 밝혀야 한다.', 5523);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9757, '① 법원은 증인이 「성폭력범죄의 처벌 등에 관한 특례법」제37조제1항,「장애인복지법」제59조의16제1항에 해당하는 경우 증인신문 전에 구두 또는 서면에 의하여 피해자, 법정대리인, 변호사(제4조제1항에서 정한 서류가 법원에 제출된 경우에 한한다) 및 보조인(「장애인복지법」제59조의16제1항의 경우에 한한다. 이하 이 조에서 같다)에게 「성폭력범죄의 처벌 등에 관한 특례법」제37조제1항, 「장애인복지법」제59조의16제1항의 신청권이 있음을 고지하여야 한다. <개정 2022.1.28>', 5524);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9758, '② 「성폭력범죄의 처벌 등에 관한 특례법」제37조제2항(다른 법률에서 위 규정을 준용하는 경우를 포함한다), 「장애인복지법」제59조의16제2항에 따른 고지를 한 때에는 법원사무관등을 참여시켜 조서를 작성하게 하거나 피해자, 법정대리인, 변호사 및 보조인으로 하여금 확인서 기타 서면을 작성하게 하여야 한다. <개정 2022.1.28>', 5524);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9759, '① 법원이 「성폭력범죄의 처벌 등에 관한 특례법」 제37조제1항, 「장애인복지법」제59조의16제1항에 따라 진술조력인으로 하여금 증인신문에 참여하여 중개하거나 보조하게 하는 경우에는 그 증인신문 전에 진술조력인을 선정하여야 한다. <개정 2022.1.28>', 5525);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9760, '② 제1항의 경우 법원은 「진술조력인의 선정 등에 관한 규칙」에 따라 자격이 인정된 진술조력인을 선정한다. 다만, 당해 피해자에 대한 조사과정에 참여한 진술조력인이 있는 경우 특별한 사정이 없는 한 그 진술조력인을 선정한다. <개정 2014.9.1>', 5525);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9761, '③ 제1항 및 제2항에 따라 진술조력인을 선정하는 경우 다음 각 호의 어느 하나에 해당하는 사람은 당해 사건의 진술조력인으로 선정하여서는 아니 된다.', 5525);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9762, '④ 진술조력인 선정은 선정이 취소되지 않는 한 재판이 확정될 때까지 효력이 있다.', 5525);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9763, '① 법원은 다음 각 호의 어느 하나에 해당하는 경우 당해 사건의 진술조력인 선정을 취소할 수 있다. 다만, 제1호 및 제2호의 경우에는 그 선정을 취소하여야 한다. <개정 2014.9.1, 2021.1.29>', 5526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9764, '② 법원은 진술조력인의 선정을 취소한 경우 지체 없이 진술조력인에게 통지하여야 한다.', 5526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9765, '③ 법원은 제1항에 따라 진술조력인 선정을 취소한 경우 제19조에 따라 진술조력인을 다시 선정할 수 있다.', 5526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9766, '④ 제4조제2항의 규정은 제2항의 통지에 준용한다.', 5526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9767, '① 법원은 제19조에 따라 진술조력인이 선정된 경우 진술조력인에게 참여하여 중개ㆍ보조할 기일을 통지하여야 한다.', 5527);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9768, '② 제1항의 통지를 한 때에는 검사 및 피고인 또는 변호인에게도 해당 기일에 진술조력인이 참여하여 중개ㆍ보조할 예정이라는 취지를 통지하여야 한다.', 5527);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9769, '③ 제4조제2항의 규정은 제1항 및 제2항의 통지에 준용한다.', 5527);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9770, '① 진술조력인은 증인의 좌석에 가까운 곳에 위치한다.', 5528);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9771, '② 제1항의 규정에도 불구하고, 재판장은 법정의 구조 등을 고려하여 진술조력인의 좌석의 위치 및 방향을 달리 정할 수 있다.', 5528);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9772, '① 법원은 필요한 경우 공판준비기일 또는 공판기일에서 검사, 변호인 및 진술조력인과 다음 각 호의 사항에 관하여 협의할 수 있다.', 5529);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9773, '② 진술조력인은 증인이 의사소통에 어려움이 있어 신문의 취지를 이해하지 못하는 사정이 있는 경우 재판장의 허가를 받아 증인에게 질문의 요지를 설명할 수 있다.', 5529);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9774, '③ 제2항의 경우 진술조력인은 재판장의 허가를 받아 검사, 피고인 또는 변호인에게 신문의 취지를 질문하거나 신문사항의 수정을 요청할 수 있다.', 5529);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9775, '④ 진술조력인은 증인이 의사표현에 어려움이 있는 경우 재판장의 허가를 받아 증인의 진술을 소송관계인이 이해할 수 있는 방식으로 진술할 수 있다.', 5529);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9776, '⑤ 진술조력인이 제2항부터 제4항까지의 규정에 따라 증인의 의사소통이나 의사표현을 중개ㆍ보조하는 경우 법원, 검사, 피고인 또는 변호인의 신문이나 증인의 진술의 취지를 변경하여서는 아니 된다.', 5529);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9777, '⑥ 재판장은 진술조력인의 중개ㆍ보조의 정확성과 공정성을 확인하기 위하여 진술조력인에게 질문할 수 있다.', 5529);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9778, '⑦ 합의부원은 재판장에게 알리고 제6항의 행위를 할 수 있다.', 5529);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9779, '⑧ 검사, 피고인 또는 변호인은 진술조력인의 중개ㆍ보조의 정확성과 공정성을 확인하기 위하여 재판장의 허가를 받아 진술조력인에게 질문할 수 있다.', 5529);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9780, '① 진술조력인에게는 수당을 지급하고, 필요한 경우에는 그 밖의 여비, 일당 및 숙박료를 지급할 수 있다.', 5531);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9781, '② 제1항의 일당 및 수당은 매년 예산의 범위 안에서 대법관회의에서 이를 정한다.', 5531);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9782, '③ 제1항 및 제2항의 수당은 사안의 난이, 진술조력인이 수행한 직무의 내용, 소송절차 참여에 소요된 시간 등을 참작하여 예산의 범위 안에서 재판장이 이를 증액할 수 있다.', 5531);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9783, '④ 진술조력인의 국내 여비와 숙박료는 「법원공무원 여비 규칙」 제10조제1항, 제11조제1항, 제12조제1항, 제13조제1항, 제16조제1항의 별표 2 국내 여비 지급표에 정한 제2호 소정액 이내로 한다.', 5531);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9784, '⑤ 진술조력인이 국외여행하는 경우의 여비와 숙박료는 「법원공무원 여비 규칙」 제10조제2항, 제11조제2항 및 제13조제2항에 정한 액수 이내, 제12조제2항의 별표 3 국외 항공운임 정액표에 정한 그 밖의 사람 소정액 이내, 제16조제1항의 별표 4 국외 여비 지급표에 정한 별표 1의 제2호가목에 해당하는 사람 소정액 이내로 한다.', 5531);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9785, '⑥ 진술조력인의 수당, 일당, 여비 및 숙박료는 국고에서 지급한다.', 5531);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9786, '① 피해자 등을 증인으로 신문함에 있어 비디오 등 중계장치에 의한 신문여부의 결정 및 그 증인신문의 절차와 방법 등은 「형사소송규칙」 제84조의4부터 제84조의8까지의 규정을 준용한다.', 5532);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9787, '② 법원은 비디오 등 중계장치에 의한 중계시설을 통하여 증인신문을 하는 경우, 「성폭력범죄의 처벌 등에 관한 특례법」 제37조제1항, 「장애인복지법」제59조의16제1항에 따라 진술조력인으로 하여금 증인신문에 참여하여 중개하거나 보조하게 할 때에는 진술조력인을 비디오 등 중계장치에 의한 중계시설에 동석하게 한다. <개정 2022.1.28>', 5532);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9788, null, 5534);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9789, '① 법무부장관은 필요하다고 인정하면 이 법에서 정하는 바에 따라 교정업무를 공공단체 외의 법인ㆍ단체 또는 그 기관이나 개인에게 위탁할 수 있다. 다만, 교정업무를 포괄적으로 위탁하여 한 개 또는 여러 개의 교도소등을 설치ㆍ운영하도록 하는 경우에는 법인에만 위탁할 수 있다.', 5535);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9790, '② 법무부장관은 교정업무의 수탁자를 선정하는 경우에는 수탁자의 인력ㆍ조직ㆍ시설ㆍ재정능력ㆍ공신력 등을 종합적으로 검토한 후 적절한 자를 선정하여야 한다.', 5535);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9791, '③ 제2항에 따른 선정방법, 선정절차, 그 밖에 수탁자의 선정에 관하여 필요한 사항은 법무부장관이 정한다.', 5535);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9792, '① 법무부장관은 교정업무를 위탁하려면 수탁자와 대통령령으로 정하는 방법으로 계약(이하 "위탁계약"이라 한다)을 체결하여야 한다.', 5536);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9793, '② 법무부장관은 필요하다고 인정하면 민영교도소등의 직원이 담당할 업무와 민영교도소등에 파견된 소속 공무원이 담당할 업무를 구분하여 위탁계약을 체결할 수 있다.', 5536);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9794, '③ 법무부장관은 위탁계약을 체결하기 전에 계약 내용을 기획재정부장관과 미리 협의하여야 한다.', 5536);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9795, '④ 위탁계약의 기간은 다음 각 호와 같이 하되, 그 기간은 갱신할 수 있다.', 5536);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9796, '① 위탁계약에는 다음 각 호의 사항이 포함되어야 한다.', 5537);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9797, '② 법무부장관은 제1항제6호에 따른 위탁수용 대상자의 범위를 정할 때에는 수탁자의 관리능력, 교도소등의 안전과 질서, 위탁수용이 수용자의 사회 복귀에 유용한지 등을 고려하여야 한다.', 5537);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9798, '① 법무부장관은 수탁자가 이 법 또는 이 법에 따른 명령이나 처분을 위반하면 6개월 이내의 기간을 정하여 위탁업무의 전부 또는 일부의 정지를 명할 수 있다.', 5538);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9799, '② 법무부장관은 제1항에 따른 정지명령을 한 경우에는 소속 공무원에게 정지된 위탁업무를 처리하도록 하여야 한다.', 5538);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9800, '③ 법무부장관은 제1항에 따른 정지명령을 할 때 제2항을 적용하기 어려운 사정이 있으면 그 사정이 해결되어 없어질 때까지 정지명령의 집행을 유예할 수 있다.', 5538);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9801, '① 법무부장관은 수탁자가 다음 각 호의 어느 하나에 해당하면 위탁계약을 해지할 수 있다.', 5539);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9802, '② 법무부장관과 수탁자는 위탁계약으로 정하는 바에 따라 계약을 해지할 수 있다.', 5539);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9803, '① 제3조제1항 단서에 따라 교정업무를 위탁받은 법인은 위탁계약을 이행하기 전에 법인의 목적사업에 민영교도소등의 설치ㆍ운영이 포함되도록 정관(定款)을 변경하여야 한다.', 5542);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9804, '② 제1항에 따른 정관 변경과 교정법인의 정관 변경은 법무부장관의 인가를 받아야 한다. 다만, 대통령령으로 정하는 경미한 사항의 변경은 법무부장관에게 신고하여야 한다.', 5542);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9805, '① 교정법인은 이사 중에서 위탁업무를 전담하는 자를 선임(選任)하여야 한다.', 5543);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9806, '② 교정법인의 대표자 및 감사와 제1항에 따라 위탁업무를 전담하는 이사(이하 "임원"이라 한다)는 법무부장관의 승인을 받아 취임한다.', 5543);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9807, '③ 교정법인 이사의 과반수는 대한민국 국민이어야 하며, 이사의 5분의 1 이상은 교정업무에 종사한 경력이 5년 이상이어야 한다.', 5543);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9808, '④ 다음 각 호의 어느 하나에 해당하는 자는 교정법인의 임원이 될 수 없으며, 임원이 된 후 이에 해당하게 되면 임원의 직을 상실한다.', 5543);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9809, '⑤ 교정법인 임원의 임기, 직무, 결원 보충 및 임시이사 선임에 필요한 사항은 대통령령으로 정한다.', 5543);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9810, null, 5544);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9811, '① 교정법인의 대표자는 그 교정법인이 운영하는 민영교도소등의 장을 겸할 수 없다.', 5545);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9812, '② 이사는 감사나 해당 교정법인이 운영하는 민영교도소등의 직원(민영교도소등의 장은 제외한다)을 겸할 수 없다.', 5545);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9813, '③ 감사는 교정법인의 대표자ㆍ이사 또는 직원(그 교정법인이 운영하는 민영교도소등의 직원을 포함한다)을 겸할 수 없다.', 5545);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9814, '① 교정법인은 대통령령으로 정하는 기준에 따라 민영교도소등의 운영에 필요한 기본재산을 갖추어야 한다.', 5546);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9815, '② 교정법인은 기본재산에 대하여 다음 각 호의 행위를 하려면 법무부장관의 허가를 받아야 한다. 다만, 대통령령으로 정하는 경미한 사항은 법무부장관에게 신고하여야 한다.', 5546);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9816, '③ 교정법인의 재산 중 교도소등 수용시설로 직접 사용되고 있는 것으로서 대통령령으로 정하는 것은 국가 또는 다른 교정법인 외의 자에게 매도ㆍ증여 또는 교환하거나 담보로 제공할 수 없다.', 5546);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9817, '① 교정법인의 회계는 그가 운영하는 민영교도소등의 설치ㆍ운영에 관한 회계와 법인의 일반업무에 관한 회계로 구분한다.', 5547);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9818, '② 제1항에 따른 민영교도소등의 설치ㆍ운영에 관한 회계는 교도작업회계와 일반회계로 구분하며, 각 회계의 세입ㆍ세출에 관한 사항은 대통령령으로 정한다.', 5547);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9819, '③ 제1항에 따른 법인의 일반업무에 관한 회계는 일반업무회계와 수익사업회계로 구분할 수 있다.', 5547);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9820, '④ 제2항에 따른 민영교도소등의 설치ㆍ운영에 관한 회계의 예산은 민영교도소등의 장이 편성하여 교정법인의 이사회가 심의ㆍ의결하고 민영교도소등의 장이 집행한다.', 5547);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9821, '① 교정법인의 회계연도는 정부의 회계연도에 따른다.', 5548);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9822, '② 교정법인은 대통령령으로 정하는 바에 따라 법무부장관에게 매 회계연도가 시작되기 전에 다음 회계연도에 실시할 사업계획과 예산을 제출하고, 매 회계연도가 끝난 후에 사업 실적과 결산을 보고하여야 한다.', 5548);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9823, '③ 법무부장관은 교정법인이 제2항에 따라 결산서를 제출하는 경우 교정법인으로부터 독립된 공인회계사나 회계법인의 감사증명서를 첨부하게 할 수 있다.', 5548);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9824, '④ 교정법인의 회계규칙이나 그 밖에 예산 또는 회계에 관하여 필요한 사항은 법무부장관이 정한다.', 5548);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9825, '① 교정법인이 다음 각 호의 어느 하나에 해당하는 행위를 하려면 법무부장관의 인가를 받아야 한다.', 5549);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9826, '② 법무부장관은 제1항에 따른 인가에 조건을 붙일 수 있다.', 5549);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9827, '① 해산한 교정법인의 잔여재산 귀속은 합병하거나 파산한 경우가 아니면 정관으로 정하는 바에 따른다.', 5550);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9828, '② 제1항에 따라 처분되지 아니한 교정법인의 재산은 국고에 귀속한다.', 5550);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9829, '③ 국가는 제2항에 따라 국고에 귀속된 재산을 다른 민영교도소등의 사업에 사용할 수 있다.', 5550);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9830, '④ 제2항에 따라 국고에 귀속된 재산은 법무부장관이 관리한다.', 5550);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9831, '① 민영교도소등은 「형의 집행 및 수용자의 처우에 관한 법률」 제2조제4호에 규정된 교도소등에 준하는 조직을 갖추어야 한다.', 5553);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9832, '② 교정법인은 민영교도소등을 운영할 때 시설 안의 수용자를 수용ㆍ관리하고 교정서비스를 제공하기에 적합한 직원을 확보하여야 한다.', 5553);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9833, '① 교정법인은 민영교도소등의 시설이 이 법과 이 법에 따른 명령 및 위탁계약의 내용에 적합한지에 관하여 법무부장관의 검사를 받아야 한다.', 5554);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9834, '② 법무부장관은 제1항에 따른 검사를 한 결과 해당 시설이 이 법에 따른 수용시설로서 적당하지 아니하다고 인정되면 교정법인에 대하여 보정(補正)을 명할 수 있다.', 5554);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9835, '③ 제1항과 제2항에 따른 시설의 검사 방법ㆍ절차 등에 관하여 필요한 사항은 법무부장관이 정한다.', 5554);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9836, '① 법무부장관은 사전에 기획재정부장관과 협의하여 민영교도소등을 운영하는 교정법인에 대하여 매년 그 교도소등의 운영에 필요한 경비를 지급한다.', 5555);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9837, '② 제1항에 따른 연간 지급 경비의 기준은 다음 각 호의 사항 등을 고려하여 예산의 범위에서 법무부장관이 정한다.', 5555);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9838, '① 교정법인은 위탁업무를 수행할 때 같은 유형의 수용자를 수용ㆍ관리하는 국가운영의 교도소등과 동등한 수준 이상의 교정서비스를 제공하여야 한다.', 5557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9839, '② 교정법인은 민영교도소등에 수용되는 자에게 특별한 사유가 있다는 이유로 수용을 거절할 수 없다. 다만, 수용ㆍ작업ㆍ교화, 그 밖의 처우를 위하여 특별히 필요하다고 인정되는 경우에는 법무부장관에게 수용자의 이송(移送)을 신청할 수 있다.', 5557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9840, '③ 교정법인의 임직원과 민영교도소등의 장 및 직원은 수용자에게 특정 종교나 사상을 강요하여서는 아니 된다.', 5557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9841, '① 민영교도소등의 장은 제40조에 따라 준용되는 「형의 집행 및 수용자의 처우에 관한 법률」 제37조제1항ㆍ제2항, 제63조제3항, 제68조제1항, 제77조제1항, 제97조, 제100조부터 제102조까지 및 제107조부터 제109조까지의 규정에 따른 처분 등을 하려면 제33조제2항에 따라 법무부장관이 민영교도소등의 지도ㆍ감독을 위하여 파견한 소속 공무원(이하 이 조에서 "감독관"이라 한다)의 승인을 받아야 한다. 다만, 긴급한 상황으로 승인을 받을 만한 시간적 여유가 없을 때에는 그 처분 등을 한 후 즉시 감독관에게 알려서 승인을 받아야 한다.', 5559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9842, '② 민영교도소등의 장은 제40조에 따라 준용되는 「형의 집행 및 수용자의 처우에 관한 법률」 제121조제1항에 따른 가석방 적격심사를 신청하려면 감독관의 의견서를 첨부하여야 한다.', 5559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9843, '③ 민영교도소등의 장은 제40조에 따라 준용되는 「형의 집행 및 수용자의 처우에 관한 법률」 제123조에 따른 석방을 하려면 관계 서류를 조사한 후 감독관의 확인을 받아 석방하여야 한다.', 5559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9844, null, 5560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9845, '① 교정법인의 대표자는 민영교도소등의 직원을 임면(任免)한다. 다만, 민영교도소등의 장 및 대통령령으로 정하는 직원을 임면할 때에는 미리 법무부장관의 승인을 받아야 한다.', 5561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9846, '② 교정법인의 대표자는 민영교도소등의 장 외의 직원을 임면할 권한을 민영교도소등의 장에게 위임할 수 있다.', 5561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9847, '③ 민영교도소등의 직원의 임용 자격, 임용 방법, 교육 및 징계에 관하여는 대통령령으로 정한다.', 5561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9848, '① 민영교도소등의 직원은 대통령령으로 정하는 바에 따라 「형의 집행 및 수용자의 처우에 관한 법률」에 따른 교도관의 직무를 수행한다.', 5562);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9849, '② 민영교도소등의 직원의 복무에 관하여는 「국가공무원법」 제56조부터 제61조까지, 제63조, 제64조제1항, 제65조제1항부터 제3항까지 및 제66조제1항 본문을 준용한다.', 5562);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9850, '① 민영교도소등의 직원은 근무 중 법무부장관이 정하는 제복을 입어야 한다.', 5563);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9851, '② 민영교도소등의 운영에 필요한 무기는 해당 교정법인의 부담으로 법무부장관이 구입하여 배정한다.', 5563);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9852, '③ 민영교도소등의 무기 구입ㆍ배정에 필요한 사항은 법무부장관이 정한다.', 5563);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9853, '① 법무부장관은 민영교도소등의 업무 및 그와 관련된 교정법인의 업무를 지도ㆍ감독하며, 필요한 경우 지시나 명령을 할 수 있다. 다만, 수용자에 대한 교육과 교화프로그램에 관하여는 그 교정법인의 의견을 최대한 존중하여야 한다.', 5565);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9854, '② 법무부장관은 제1항에 따른 지도ㆍ감독상 필요하다고 인정하면 민영교도소등에 소속 공무원을 파견하여 그 민영교도소등의 업무를 지도ㆍ감독하게 하여야 한다.', 5565);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9855, '③ 교정법인 및 민영교도소등의 장은 항상 소속 직원의 근무 상황을 감독하고 필요한 교육을 하여야 한다.', 5565);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9856, '① 민영교도소등의 장은 대통령령으로 정하는 바에 따라 매월 또는 분기마다 다음 각 호의 사항을 법무부장관에게 보고하여야 한다.', 5566);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9857, '② 법무부장관은 필요하다고 인정하면 수시로 교정법인이나 민영교도소등에 대하여 그 업무ㆍ회계 및 재산에 관한 사항을 보고하게 하거나, 소속 공무원에게 장부ㆍ서류ㆍ시설, 그 밖의 물건을 검사하게 할 수 있다. 이 경우 위법 또는 부당한 사실이 발견되면 이에 따른 필요한 조치를 명할 수 있다.', 5566);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9858, '① 법무부장관은 위탁업무의 처리 결과에 대하여 매년 1회 이상 감사를 하여야 한다.', 5567);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9859, '② 법무부장관은 제1항에 따른 감사 결과 위탁업무의 처리가 위법 또는 부당하다고 인정되면 해당 교정법인이나 민영교도소등에 대하여 적절한 시정조치를 명할 수 있으며, 관계 임직원에 대한 인사 조치를 요구할 수 있다.', 5567);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9860, '① 법무부장관은 민영교도소등의 직원이 위탁업무에 관하여 이 법 또는 이 법에 따른 명령이나 처분을 위반하면 그 직원의 임면권자에게 해임이나 정직ㆍ감봉 등 징계처분을 하도록 명할 수 있다.', 5568);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9861, '② 교정법인 또는 민영교도소등의 장은 제1항에 따른 징계처분명령을 받으면 즉시 징계처분을 하고 법무부장관에게 보고하여야 한다.', 5568);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9862, '① 민영교도소등의 직원은 법령에 따라 공무(公務)에 종사하는 것으로 본다.', 5569);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9863, '② 교정법인의 임직원 중 교정업무를 수행하는 자와 민영교도소등의 직원은 「형법」이나 그 밖의 법률에 따른 벌칙을 적용할 때에는 공무원으로 본다.', 5569);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9864, '③ 민영교도소등의 장 및 직원은 「형사소송법」이나 「사법경찰관리의 직무를 수행할 자와 그 직무범위에 관한 법률」을 적용할 때에는 교도소장ㆍ구치소장 또는 교도관리로 본다.', 5569);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9865, '① 교정법인의 임직원과 민영교도소등의 직원이 위탁업무를 수행할 때 고의 또는 과실로 법령을 위반하여 국가에 손해를 입힌 경우 그 교정법인은 손해를 배상하여야 한다.', 5570);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9866, '② 교정법인은 제1항에 따른 손해배상을 위하여 대통령령으로 정하는 기준에 따라 현금ㆍ유가증권 또는 물건을 공탁하거나 이행보증보험에 가입하여야 한다.', 5570);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9867, '① 다음 각 호의 어느 하나에 해당하는 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.', 5574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9868, '② 다음 각 호의 어느 하나에 해당하는 자는 2년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.', 5574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9869, '① 다음 각 호의 어느 하나에 해당하는 자에게는 1천만원 이하의 과태료를 부과한다.', 5576);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9870, '② 다음 각 호의 어느 하나에 해당하는 자에게는 500만원 이하의 과태료를 부과한다.', 5576);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9871, '③ 다음 각 호의 어느 하나에 해당하는 자에게는 300만원 이하의 과태료를 부과한다.', 5576);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9872, '④ 제1항부터 제3항까지의 규정에 따른 과태료는 대통령령으로 정하는 기준에 따라 법무부장관이 부과ㆍ징수한다.', 5576);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9873, '①「민영교도소 등의 설치ㆍ운영에 관한 법률」(이하 "법"이라 한다) 제4조제1항에 따른 위탁계약은 법무부장관과 법 제3조제2항에 따라 선정된 수탁자가 법 제5조제1항 각 호의 사항에 관하여 약정하고 해당 계약서에 각각 서명날인함으로써 성립한다.', 5580);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9874, '② 법무부장관은 위탁계약을 체결할 때 계약사항의 누락을 방지하고, 계약내용의 일관성을 유지하며, 계약체결의 효율성과 공정성을 높이기 위하여 교정업무의 민간위탁에 관한 표준계약서를 정할 수 있다.', 5580);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9875, null, 5581);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9876, '① 교정법인의 임원의 임기는 해당 법인의 정관에서 정하는 바에 따르고, 정관에서 특별히 정하지 않은 경우에는 3년으로 하며, 연임할 수 있다.', 5582);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9877, '② 교정법인은 해당 법인의 이사(위탁업무를 전담하는 이사만 해당한다. 이하 이 조에서 같다) 또는 감사 중에 결원이 생겼을 때에는 그 사유가 발생한 날부터 2개월 이내에 보충하여야 한다.', 5582);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9878, '③ 법무부장관은 교정법인이 제2항에 따라 이사의 결원을 보충하지 않아 해당 교정법인의 목적을 달성할 수 없거나 손해가 생길 우려가 있다고 인정되면 이해관계인의 청구나 직권에 의하여 임시이사를 선임(選任)할 수 있다.', 5582);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9879, '① 교정법인의 대표자(이하 "대표자"라 한다)는 교정법인을 대표하며, 법인의 업무를 총괄한다.', 5583);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9880, '② 대표자가 공석이 되거나 부득이한 사유로 직무를 수행할 수 없을 때에는 정관에서 미리 정한 사람이 그 직무를 대행하되, 정관에서 특별히 정하지 않은 경우에는 이사 중에서 호선(互選)한 사람이 그 직무를 대행한다.', 5583);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9881, '③ 이사는 이사회에 출석하여 교정법인의 업무에 관한 사항을 심의ㆍ의결하며, 이사회나 대표자로부터 위임받은 사항을 처리한다.', 5583);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9882, '④ 감사는 다음 각 호의 직무를 수행한다.', 5583);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9883, '① 대표자는 이사회를 소집하고, 그 의장이 된다.', 5584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9884, '② 이사회는 다음 각 호의 사항을 심의ㆍ의결한다.', 5584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9885, '① 교정법인의 재산 중 다음 각 호의 어느 하나에 해당하는 재산은 법 제14조제1항에 따른 기본재산으로 한다.', 5585);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9886, '② 교정법인의 재산 중 제1항 각 호 외의 재산은 보통재산으로 한다.', 5585);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9887, '③ 제1항에 따른 기본재산은 교도소ㆍ소년교도소 또는 구치소 및 그 지소(이하 "교도소등"이라 한다)의 부지매입, 설계 및 건축에 필요한 재원(교정법인이 교도소등의 설치비용을 부담하는 경우만 해당한다)과 직원교육, 손해배상 등 교도소등의 운영에 드는 경비를 충당할 수 있어야 한다.', 5585);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9888, null, 5586);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9889, null, 5587);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9890, '① 법 제15조제2항에 따른 민영교도소등의 설치ㆍ운영에 관한 회계 중 일반회계의 세입은 다음 각 호의 수입으로 한다.', 5588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9891, '② 일반회계의 세출은 다음 각 호의 경비로 한다.', 5588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9892, '③ 법 제15조제2항에 따른 민영교도소등의 설치ㆍ운영에 관한 회계 중 교도작업회계의 세입은 다음 각 호의 수입으로 한다.', 5588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9893, '④ 교도작업회계의 세출은 교도작업을 위하여 필요한 모든 경비로 한다.', 5588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9894, '① 교정법인은 법 제16조제2항에 따라 법무부장관에게 법 제15조제2항에 따른 민영교도소등의 설치ㆍ운영에 관한 회계의 사업계획과 예산을 매 회계연도가 시작되기 8개월 이전에 제출하고, 사업실적과 결산을 매 회계연도가 끝난 후 2개월 이내에 제출하여야 한다.', 5589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9895, '② 교정법인은 연도 중에 해당 예산을 추가하거나 경정(更正)할 때에는 추가하거나 경정한 날부터 15일 이내에 해당 예산을 법무부장관에게 제출하여야 한다.', 5589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9896, '③ 법 제16조제3항에 따른 공인회계사 등의 감사증명서를 제출하여야 할 교정법인의 범위는 다음 각 호와 같다.', 5589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9897, '① 교정법인이 설치ㆍ운영하는 교도소등은 위탁수용 대상자의 특성을 고려하여 위탁계약에서 달리 정한 경우를 제외하고는 다음 각 호의 시설을 갖추어야 한다. <개정 2021.1.5>', 5590);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9898, '② 교정법인은 「형의 집행 및 수용자의 처우에 관한 법률」 제45조에 따른 종교행사를 치르기 위하여 마련된 장소를 제외하고는 그 법인이 운영하는 교도소등의 시설에서 수용자가 항상 출입하거나 접근할 수 있는 장소에 특정종교의 상징물을 설치해서는 아니 된다. 다만, 법무부장관이 국가의 종교적 중립성과 종파간의 형평성을 해치지 아니하는 범위에서 특별히 허가한 경우에는 그러하지 아니하다.', 5590);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9899, '① 민영교도소등의 장과 직원은 수용자에게 특정 종교의 교리ㆍ교의에 따른 교육ㆍ교화ㆍ의식과 그 밖에 행사의 참가를 강요해서는 아니 된다.', 5591);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9900, '② 민영교도소등의 장과 직원은 수용자가 특정 종교를 신봉하지 아니한다는 이유로 불리한 처우를 해서는 아니 된다.', 5591);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9901, '① 법 제29조제3항에 따라 민영교도소등의 직원으로 임용되려면 18세 이상이어야 한다. <개정 2025.5.27>', 5593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9902, '② 교정법인은 민영교도소등의 직원을 임용하였을 때에는 10일 이내에 그 임용사항을 법무부장관에게 보고하여야 한다. 민영교도소등의 직원이 퇴직하였을 때에도 또한 같다.', 5593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9903, '① 교정법인은 민영교도소등의 직원으로 임용된 사람에 대하여 민영교도소등에 배치하기 전에 자체 교육기관이나 교정공무원 교육기관에서 직무수행에 필요한 교육을 받게 하여야 한다. 다만, 자체 교육기관이나 교정공무원 교육기관의 교육계획상 부득이 하다고 인정되는 경우에는 임용 후 1년 이내에 교육을 받게 할 수 있다.', 5594);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9904, '② 교정공무원이나 민영교도소등의 직원으로 근무하다가 퇴직한 사람이 퇴직한 날부터 2년 이내에 민영교도소등의 직원으로 임용된 경우에는 제1항에 따른 교육을 면제할 수 있다. <개정 2016.11.29>', 5594);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9905, '③ 제1항의 교육기간, 교육과목, 수업시간과 그 밖에 교육 실시에 필요한 사항은 법무부장관이 정한다.', 5594);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9906, '① 교정법인은 민영교도소등의 직원이 신체적ㆍ정신적 이상으로 직무를 감당하지 못하거나 인원의 감축으로 정원(定員)이 초과되었을 때 또는 위탁업무의 정지명령을 받았거나 위탁계약이 해지되었을 때에는 직권으로 면직시킬 수 있다.', 5596);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9907, '② 교정법인이 제1항에 따라 민영교도소등의 직원을 직권으로 면직시켰을 때에는 5일 이내에 그 사실을 법무부장관에게 보고하여야 한다.', 5596);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9908, '① 교정법인은 민영교도소등의 직원이 다음 각 호의 어느 하나에 해당하는 경우에는 그에 대하여 징계처분을 하여야 한다.', 5597);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9909, '② 민영교도소등의 직원에 대한 징계의 종류는 해임ㆍ정직ㆍ감봉ㆍ견책으로 하되, 정직은 1개월 이상 3개월 이하의 기간 동안 직무에 종사하지 못하게 하고 보수의 전액을 감하며, 감봉은 1개월 이상 3개월 이하의 기간 동안 보수의 3분의 1을 줄인다. <개정 2025.5.27>', 5597);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9910, '① 민영교도소등의 장은 매월 법 제34조제1항제1호ㆍ제2호ㆍ제4호 및 제6호부터 제8호까지의 사항을 법무부장관에게 보고하여야 한다.', 5598);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9911, '② 민영교도소등의 장은 매 분기 법 제34조제1항제3호ㆍ제5호 및 제9호의 사항을 법무부장관에게 보고하여야 한다.', 5598);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9912, null, 5603);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9913, '① 교정법인이 법 제11조제2항에 따라 임원의 취임 승인을 신청하는 경우에는 임원 취임 승인신청서에 다음 각 호의 서류를 첨부하여 법무부장관에게 제출하여야 한다. 다만, 연임되는 임원에 대한 취임 승인을 신청하는 경우에는 제2호의 서류는 제출하지 아니한다. <개정 2010.8.3>', 5604);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9914, '② 삭제 <2010.8.3>', 5604);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9915, '① 교정법인이 법 제14조제2항에 따라 기본재산의 매도ㆍ증여 또는 교환에 관한 허가를 받거나 신고를 하려는 경우에는 그 허가신청서 또는 신고서에 다음 각 호의 서류를 첨부하여 법무부장관에게 제출하여야 한다. <개정 2017.4.21, 2025.5.27>', 5605);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9916, '② 교정법인이 법 제14조제2항에 따라 기본재산의 담보 제공에 관한 허가를 받거나 신고를 하려는 경우에는 그 허가신청서 또는 신고서에 다음 각 호의 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 5605);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9917, '③ 교정법인이 법 제14조제2항에 따라 기본재산에 대하여 용도 변경, 의무의 부담 또는 권리의 포기에 관한 허가를 받거나 신고를 하려는 경우에는 그 허가신청서 또는 신고서에 그 사유를 분명히 기록하여야 한다.', 5605);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9918, '① 교정법인이 법 제16조제2항 및 같은 법 시행령(이하 "영"이라 한다) 제13조에 따라 사업계획과 예산을 제출할 때에는 다음 각 호의 서류를 첨부하여야 한다.', 5606);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9919, '② 교정법인이 법 제16조제2항 및 영 제13조에 따라 사업실적과 결산을 보고할 경우에는 다음 각 호의 서류를 첨부하여야 한다.', 5606);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9920, '① 교정법인의 예산은 법 제15조에 따른 회계별로 구분하여 추정 대차대조표 및 그 부속명세서와 추정 손익계산서 및 그 부속명세서로 편성한다.', 5607);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9921, '② 제1항의 추정 대차대조표는 해당 연도 말 현재에 추정되는 재정상태를 표시하되, 전년도 말 현재와의 비교증감을 표시하여야 한다.', 5607);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9922, '③ 제1항의 추정 손익계산서에는 해당 연도에 발생할 것으로 추정되는 모든 수익과 비용을 계상(計上)하되, 전년도의 수익과 비용을 비교ㆍ표시하여야 한다.', 5607);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9923, '④ 제1항의 추정 대차대조표 및 추정 손익계산서의 부속명세서에는 각각 그 추정의 근거를 명백히 하여야 한다.', 5607);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9924, '① 교정법인이 법 제17조제1항제1호 및 제2호에 따른 합병 또는 분할합병의 인가를 신청하는 경우에는 합병(분할합병을 포함한다. 이하 같다)인가 신청서에 다음 각 호의 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 5609);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9925, '② 제1항제5호의 재산목록은 기본재산과 보통재산으로 구분하여 작성하여야 한다.', 5609);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9926, '③ 교정법인이 분할에 의하여 1개 또는 여러 개의 교정법인을 설립함과 동시에 분할합병하려는 경우에는 그 합병인가 신청서에 제1항 각 호의 서류 외에 제10조제1호부터 제4호까지의 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 5609);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9927, null, 5610);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9928, null, 5611);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9929, '① 법무부장관이 교정법인의 합병 또는 분할의 인가를 하는 경우 다음 각 호의 조건을 붙일 수 있다.', 5612);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9930, '② 법무부장관이 교정법인의 해산인가를 하는 경우 다음 각 호의 조건을 붙일 수 있다.', 5612);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9931, '① 교정법인이 법 제22조제1항에 따른 시설검사를 받으려는 경우 검사를 받으려는 날의 30일 전까지 시설검사 신청서에 공사일정에 관한 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 5613);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9932, '② 법무부장관은 법 제22조제1항에 따라 시설검사를 하기 위하여 필요하다고 인정되는 경우에는 소속 공무원에게 이를 검사하게 하거나, 외부의 건축ㆍ토목전문가 등에게 검사를 대행하게 할 수 있다.', 5613);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9933, '③ 제2항에 따라 검사를 하려는 경우에는 그 권한을 표시하는 증표를 지니고, 이를 관계인에게 보여주어야 한다.', 5613);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9934, '④ 법무부장관이 법 제22조제1항 또는 법 제34조제2항에 따른 검사를 하려는 경우에는 미리 검사의 목적ㆍ대상 및 기간을 정하여 해당 교정법인 또는 민영교도소등의 장에게 통지하여야 한다.', 5613);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9935, null, 5614);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9936, '① 법 제23조에 따라 교정법인에 지급할 경비는 「국가재정법」에 따른 일반회계에 속하는 해당 연도 교정행정 예산의 총액과 그 예산에 계상된 수용인원을 기준으로 1인당 수용경비를 산정하고, 위탁수용 대상자의 인원과 특성 등을 고려하여 위탁계약으로 정한다. 다만, 교도작업에 필요한 경비의 지급은 위탁계약에서 정하는 바에 따른다.', 5615);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9937, '② 제1항에 따라 지급하는 운영 경비는 국가가 운영하는 교도소ㆍ소년교도소 또는 구치소 및 그 지소(이하 "교도소등"이라 한다)에 대한 예산ㆍ자금배정 시기 및 방법에 준하여 지급한다. <개정 2022.2.7>', 5615);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9938, '① 교정법인이 교도소등의 설치비용을 부담한 경우에는 제15조에 따른 경비 외에 위탁계약에서 정하는 바에 따라 해당 교도소등의 설치비용과 그에 대한 이자를 계약기간 중 매년 나누어 지급할 수 있다.', 5616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9939, '② 교정법인이 제1항에 따라 교도소등의 설치비용을 지급받는 경우에는 그 지급이 완료됨과 동시에 교도소등의 부지 및 건축물과 그 부대시설ㆍ장비 등의 소유를 국유로 이전하는 데 필요한 조치를 하여야 한다.', 5616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9940, '① 교정법인은 법 제29조제1항 단서에 따라 민영교도소등의 장 및 직원의 임명승인을 받으려는 경우에는 그 승인신청서에 다음 각 호의 서류를 첨부하여야 한다. <개정 2010.8.3>', 5617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9941, '② 삭제 <2010.8.3>', 5617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9942, '③ 교정법인은 법 제29조제1항 단서에 따라 민영교도소등의 장 및 직원의 면직승인을 받으려는 경우에는 그 승인신청서에 다음 각 호의 서류를 첨부하여야 한다.', 5617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9943, '① 법무부장관은 법 제33조제2항에 따라 파견한 소속공무원에게 민영교도소등의 직원에 대하여 매주 1시간의 범위에서 직무수행에 필요한 교육을 실시하게 할 수 있다.', 5619);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9944, '② 민영교도소등의 장은 소속 직원에 대하여 법 제33조제3항에 따른 직무수행에 필요한 교육을 매주 1시간 이상 실시하여야 한다.', 5619);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9945, '③ 법무부장관은 직원연수ㆍ업무협조 등을 위하여 민영교도소등의 장이 요청하는 경우에는 민영교도소등의 직원을 국가가 운영하는 교도소등에 일정기간 근무하게 할 수 있다.', 5619);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9946, '① 민영교도소등의 직원이 착용할 제복의 종류 및 제작 양식과 그 착용 방법은 교정공무원 복제(服制)에 관한 규정을 준용하여 해당 민영교도소등의 장이 정하되, 법무부장관의 승인을 받아야 한다. <개정 2018.7.13, 2022.2.7>', 5620);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9947, '② 민영교도소등의 장은 제1항에 따른 복제를 정하는 경우 계급 및 소속 기관의 표시 등을 교정직공무원의 것과 구별되도록 하여야 한다.', 5620);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9948, '③ 민영교도소등의 장은 교화ㆍ분류심사ㆍ교육훈련 등 직무상 필요한 경우와 근무지역의 여건상 필요하다고 인정되는 경우에는 소속 직원에게 근무 중 사복을 착용하게 할 수 있다.', 5620);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9949, '① 민영교도소등의 직원의 신분증명서는 민영교도소등의 장이 발행하되, 그 제작 양식은 법무부장관의 승인을 받아야 한다. <개정 2022.2.7>', 5621);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9950, '② 민영교도소등의 직원은 근무 중 신분증명서를 지녀야 한다.', 5621);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9951, '① 민영교도소등의 장이 법 제31조제2항에 따라 무기 및 탄약을 배정받으려는 경우에는 무기 및 탄약의 종류ㆍ수량 등을 명시하여 매년 2월 말까지 법무부장관에게 신청하여야 한다.', 5622);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9952, '② 법무부장관은 제1항에 따른 신청을 검토하여 민영교도소등의 운영에 필요하다고 인정되는 범위에서 무기 및 탄약을 구입하여 배정한다.', 5622);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9953, '③ 제2항에 따라 무기 및 탄약을 배정받은 민영교도소등의 장은 위탁계약에서 달리 정한 경우를 제외하고는 국가가 운영하는 교도소 등에서의 보안장비의 관리 및 사용에 관하여 법무부장관이 정한 지침에 따라 이를 관리하여야 한다.', 5622);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9954, '① 민영교도소등의 장은 소속 직원에 관한 다음 각 호의 장부와 서류를 갖춰 두어야 한다.', 5623);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9955, '② 민영교도소등의 장은 수용자관리에 관한 다음 각 호의 장부와 서류를 갖춰 두어야 한다.', 5623);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9956, '① 화염병을 사용하여 사람의 생명ㆍ신체 또는 재산을 위험에 빠트린 사람은 5년 이하의 징역 또는 5천만원 이하의 벌금에 처한다. <개정 2019.12.3>', 5626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9957, '② 제1항의 미수범은 처벌한다.', 5626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9958, '① 화염병을 제조하거나 보관ㆍ운반ㆍ소지한 사람은 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다. <개정 2019.12.3>', 5627);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9959, '② 화염병의 제조에 쓸 목적으로 유리병이나 그 밖의 용기에 휘발유나 등유, 그 밖에 불붙기 쉬운 물질을 넣은 물건으로서 이에 발화장치나 점화장치를 하면 화염병이 되는 것을 보관ㆍ운반ㆍ소지한 사람도 제1항과 같이 처벌한다.', 5627);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9960, '③ 화염병의 제조에 쓸 목적으로 화염병을 사용할 위험이 있는 장소에서 그 제조에 사용되는 물건 또는 물질을 보관ㆍ운반ㆍ소지한 사람은 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 2019.12.3>', 5627);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9961, null, 5629);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9962, '① 판결서 등의 열람 및 복사는 판결이 확정된 후 해당 판결을 선고한 법원에 신청하거나 법원 인터넷홈페이지를 통하여 열람 및 출력하는 방법으로 할 수 있다. 다만, 피고인이 수인인 경우에는 모든 피고인에 대한 판결이 확정된 후 열람 및 복사를 할 수 있다. <개정 2018.12.4>', 5632);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9963, '② 제1항의 열람 및 복사를 신청하거나 법원 인터넷 홈페이지를 통하여 열람 및 출력하는 때에는 재판기록 열람ㆍ복사 규칙에서 정하는 수수료를 내야 한다. <개정 2018.12.4>', 5632);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9964, '① 법원사무관 등은 법 제59조의3제1항 각 호 가운데 어느 하나에 해당하는 경우에는 소속 법원의 판결과 그 상ㆍ하급심 및 재심대상 판결 등에 관하여 판결서 등의 열람 및 복사를 제한할 수 있다.', 5633);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9965, '② 소송관계인은 소송기록을 보관하고 있는 법원(판결이 확정된 후에는 해당 판결을 선고한 법원을 말한다)의 법원사무관 등에게 법제 59조의3제1항제5호 단서에 따라 제1항의 판결서 등에 대한 열람 및 복사의 제한을 신청할 수 있다. 이 경우 그 신청에 관한 처분이 확정될 때까지 제3자는 해당 판결서 등의 열람 및 복사를 신청할 수 없다.', 5633);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9966, '③ 제1항 또는 제2항 단서에 따라 열람 및 복사가 제한된 경우 소송관계인이나 이해관계 있는 제3자는 판결이 확정된 후정당한 사유를 소명하여 해당 판결을 선고한 법원의 법원사무관 등에게 판결서 등의 열람 및 복사를 신청할 수 있다.', 5633);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9967, '④ 제2항의 신청을 거부한 법원사무관 등의 처분 또는 제3항의 신청에 관한 법원사무관 등의 처분에 불복하는 경우에는 법원사무관 등의 소속 법원(대법원인 경우에는 제2심판결을 한 법원을 말한 다)에 처분의 취소 또는 변경을 신청할 수 있다. 다만, 제2항의 신청을 거부한 법원사무관 등의 처분에 대하여는 처분을 통지받은 날부터 3일 이내에 취소 또는 변경을 신청하여야 하고, 이 경우 법 제417조 및 제418조를 준용한다.', 5633);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9968, '① 다음 각 호의 어느 하나에 해당하는 사람은 10만원 이하의 벌금, 구류 또는 과료(科料)의 형으로 처벌한다. <개정 2014.11.19, 2017.7.26, 2017.10.24>', 5637);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9969, '② 다음 각 호의 어느 하나에 해당하는 사람은 20만원 이하의 벌금, 구류 또는 과료의 형으로 처벌한다.', 5637);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9970, '③ 다음 각 호의 어느 하나에 해당하는 사람은 60만원 이하의 벌금, 구류 또는 과료의 형으로 처벌한다. <개정 2013.5.22>', 5637);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9971, '① 이 장에서 "범칙행위"란 제3조제1항 각 호 및 제2항 각 호의 어느 하나에 해당하는 위반행위를 말하며, 그 구체적인 범위는 대통령령으로 정한다.', 5640);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9972, '② 이 장에서 "범칙자"란 범칙행위를 한 사람으로서 다음 각 호의 어느 하나에 해당하지 아니하는 사람을 말한다.', 5640);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9973, '③ 이 장에서 "범칙금"이란 범칙자가 제7조에 따른 통고처분에 따라 국고 또는 제주특별자치도의 금고에 납부하여야 할 금전을 말한다.', 5640);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9974, '① 경찰서장, 해양경찰서장, 제주특별자치도지사 또는 철도특별사법경찰대장은 범칙자로 인정되는 사람에 대하여 그 이유를 명백히 나타낸 서면으로 범칙금을 부과하고 이를 납부할 것을 통고할 수 있다. 다만, 다음 각 호의 어느 하나에 해당하는 사람에게는 통고하지 아니한다. <개정 2014.11.19, 2017.7.26>', 5641);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9975, '② 제1항에 따라 통고할 범칙금의 액수는 범칙행위의 종류에 따라 대통령령으로 정한다.', 5641);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9976, '③ 제주특별자치도지사, 철도특별사법경찰대장은 제1항에 따라 통고처분을 한 경우에는 관할 경찰서장에게 그 사실을 통보하여야 한다.', 5641);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9977, '① 제7조에 따라 통고처분서를 받은 사람은 통고처분서를 받은 날부터 10일 이내에 경찰청장ㆍ해양경찰청장 또는 철도특별사법경찰대장이 지정한 은행, 그 지점이나 대리점, 우체국 또는 제주특별자치도지사가 지정하는 금융기관이나 그 지점에 범칙금을 납부하여야 한다. 다만, 천재지변이나 그 밖의 부득이한 사유로 말미암아 그 기간 내에 범칙금을 납부할 수 없을 때에는 그 부득이한 사유가 없어지게 된 날부터 5일 이내에 납부하여야 한다. <개정 2014.11.19, 2017.7.26>', 5642);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9978, '② 제1항에 따른 납부기간에 범칙금을 납부하지 아니한 사람은 납부기간의 마지막 날의 다음 날부터 20일 이내에 통고받은 범칙금에 그 금액의 100분의 20을 더한 금액을 납부하여야 한다.', 5642);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9979, '③ 제1항 또는 제2항에 따라 범칙금을 납부한 사람은 그 범칙행위에 대하여 다시 처벌받지 아니한다.', 5642);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9980, '① 범칙금은 제8조에 따른 납부 방법 외에 대통령령으로 정하는 범칙금 납부대행기관을 통하여 신용카드, 직불카드 등(이하 "신용카드등"이라 한다)으로 낼 수 있다. 이 경우 "범칙금 납부대행기관"이란 정보통신망을 이용하여 신용카드등에 의한 결제를 수행하는 기관으로서 대통령령으로 정하는 바에 따라 범칙금 납부대행기관으로 지정받은 자를 말한다.', 5643);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9981, '② 제1항에 따라 신용카드등으로 내는 경우에는 범칙금 납부대행기관의 승인일을 납부일로 본다.', 5643);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9982, '③ 범칙금 납부대행기관은 납부자로부터 신용카드등에 의한 과태료 납부대행 용역의 대가로 대통령령으로 정하는 바에 따라 납부대행 수수료를 받을 수 있다.', 5643);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9983, '④ 범칙금 납부대행기관의 지정 및 운영, 납부대행 수수료 등에 관하여 필요한 사항은 대통령령으로 정한다.', 5643);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9984, '① 경찰서장, 해양경찰서장 및 제주특별자치도지사는 다음 각 호의 어느 하나에 해당하는 사람에 대하여는 지체 없이 즉결심판을 청구하여야 한다. 다만, 즉결심판이 청구되기 전까지 통고받은 범칙금에 그 금액의 100분의 50을 더한 금액을 납부한 사람에 대하여는 그러하지 아니하다. <개정 2014.11.19, 2016.1.22, 2017.7.26>', 5644);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9985, '② 제1항제2호에 따라 즉결심판이 청구된 피고인이 통고받은 범칙금에 그 금액의 100분의 50을 더한 금액을 납부하고 그 증명서류를 즉결심판 선고 전까지 제출하였을 때에는 경찰서장, 해양경찰서장 및 제주특별자치도지사는 그 피고인에 대한 즉결심판 청구를 취소하여야 한다. <개정 2014.11.19, 2016.1.22, 2017.7.26>', 5644);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9986, '③ 제1항 단서 또는 제2항에 따라 범칙금을 납부한 사람은 그 범칙행위에 대하여 다시 처벌받지 아니한다.', 5644);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9987, '④ 철도특별사법경찰대장은 제1항 각 호의 어느 하나에 해당하는 사람이 있는 경우에는 즉시 관할 경찰서장 또는 해양경찰서장에게 그 사실을 통보하고 관련 서류를 넘겨야 한다. 이 경우 통보를 받은 경찰서장 또는 해양경찰서장은 제1항부터 제3항까지의 규정에 따라 이를 처리하여야 한다. <개정 2014.11.19, 2016.1.22, 2017.7.26>', 5644);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9988, '① 경찰서장, 해양경찰서장, 제주특별자치도지사 또는 철도특별사법경찰대장(이하 "경찰서장등"이라 한다)은 법 제7조에 따라 범칙자로 인정되는 사람에게 범칙금 납부를 통고할 때에는 다음 각 호의 사항을 적은 범칙금 납부통고서를 범칙금 영수증 및 범칙금 납부고지서와 함께 발부하고, 범칙금 납부고지서 발행원부와 범칙자 적발보고서를 작성하여야 한다. <개정 2014.11.19, 2017.7.26>', 5647);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9989, '② 경찰서장등은 제1항에 따른 통고처분을 하였을 때에는 통고처분사항을 통고처분처리부에 기록하거나 전자매체를 통하여 전산으로 저장ㆍ관리하여야 한다.', 5647);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9990, '③ 경찰서장 또는 해양경찰서장은 해당 경찰서의 관할구역 밖에 거주하는 범칙자로 인정되는 사람에게 범칙금 납부통고서를 발부한 경우에 범칙금 납부통고서를 받은 사람이 범칙금을 납부한 사실이 법 제8조제2항에 따라 범칙금을 납부할 수 있는 기간의 마지막 날(이하 "납부기간만료일"이라 한다)부터 5일이 지난 날까지 확인되지 아니할 때에는 그 날부터 3일 이내에 범칙자의 주소지를 관할하는 경찰서장 또는 해양경찰서장에게 제1항에 따른 범칙자 적발보고서 사본을 발송하여야 한다. <개정 2014.11.19, 2017.7.26>', 5647);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9991, '① 제3조제1항에 따른 납부통고를 받은 사람은 같은 항에 따라 발부받은 범칙금 영수증 및 범칙금 납부고지서를 법 제8조제1항에 따라 경찰청장, 해양경찰청장 또는 철도특별사법경찰대장이 지정한 은행, 그 지점이나 대리점, 우체국 또는 제주특별자치도지사가 지정하는 금융기관이나 그 지점(이하 "수납기관"이라 한다)에 제시하고 범칙금을 납부하여야 한다. <개정 2014.11.19, 2017.7.26>', 5648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9992, '② 범칙금은 분할하여 납부할 수 없다.', 5648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9993, '③ 제1항에 따라 범칙금을 받은 수납기관은 같은 항에 따라 제시된 범칙금 영수증에 범칙금 납부 사실을 확인하여 범칙금을 납부한 사람에게 내주어야 한다.', 5648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9994, '④ 수납기관이 범칙금을 받았을 때에는 지체 없이 범칙금 수납 사실을 범칙금 납부 통고를 한 경찰서장등에게 전자매체 등을 이용하여 통보하여야 한다.', 5648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9995, '① 법 제8조의2제1항 전단에서 "대통령령으로 정하는 범칙금 납부대행기관"이란 다음 각 호의 어느 하나에 해당하는 기관을 말한다.', 5649);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9996, '② 법 제8조의2제3항에 따른 납부대행수수료는 경찰청장이 범칙금 납부대행기관의 운영경비 등을 종합적으로 고려하여 승인하며, 해당 범칙금액(법 제8조제2항에 따라 부가되는 금액을 포함한다)의 1천분의 15를 초과할 수 없다.', 5649);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9997, '① 경찰서장등(철도특별사법경찰대장은 제외한다. 이하 이 조에서 같다)은 법 제9조제1항제1호에 해당하는 사람에게 지체 없이 다음 각 호의 사항을 적은 즉결심판 출석통지서를 발부하여야 한다. <개정 2014.11.19, 2016.7.19>', 5651);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9998, '② 경찰서장등은 법 제9조제1항제2호에 해당하는 사람(이하 "통고처분 불이행자"라 한다)에게 납부기간만료일부터 30일 이내에 제1항 각 호의 사항 및 법 제9조제1항 각 호 외의 부분 단서에 따라 범칙금에 그 금액의 100분의 50을 더한 금액(이하 "범칙금등"이라 한다)을 납부할 경우 즉결심판을 받지 않아도 된다는 사실을 적은 즉결심판 출석통지서를 범칙금등 영수증 및 범칙금등 납부고지서와 함께 발부하여야 한다. <개정 2014.11.19, 2016.7.19>', 5651);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (9999, '③ 경찰서장등은 제1항 및 제2항에 따라 즉결심판 출석통지서를 받은 사람이 즉결심판 기일에 출석하지 아니하여 즉결심판 절차가 진행되지 못한 경우에는 즉결심판을 위한 출석의 일시 및 장소를 다시 정하여 지체 없이 그 즉결심판 대상자에게 제1항 또는 제2항의 사항을 적은 즉결심판 출석최고서를 발부하되, 통고처분 불이행자에게 즉결심판 출석최고서를 발부할 때에는 범칙금등 영수증과 범칙금등 납부고지서를 함께 발부하여야 한다. <개정 2014.11.19, 2016.7.19>', 5651);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10000, '④ 통고처분 불이행자의 경우 제2항에 따른 즉결심판을 위한 출석일은 납부기간만료일부터 40일을 초과해서는 아니 되며, 제3항에 따른 즉결심판을 위한 출석일은 법원의 사정으로 즉결심판을 할 수 없는 경우 등의 특별한 사정이 없으면 납부기간만료일부터 60일을 초과해서는 아니 된다.', 5651);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10001, '⑤ 경찰서장등은 법 제9조제1항에 따라 즉결심판을 청구하려는 경우에는 즉결심판사범 적발보고서를 작성한 후 관할법원에 즉결심판청구서를 제출하여야 한다. <개정 2014.11.19, 2016.7.19>', 5651);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10002, '① 철도특별사법경찰대장은 법 제7조제1항 각 호의 어느 하나에 해당하는 사람에게는 즉결심판 출석 통지를 받게 될 것임을 알리는 즉결심판 통지예고서를 즉시 발부하고, 즉결심판 대상자 적발통보서를 작성하여 관할 경찰서장 또는 해양경찰서장에게 통보하여야 한다. <개정 2014.11.19, 2016.7.19, 2017.7.26>', 5652);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10003, '② 철도특별사법경찰대장은 범칙금 납부통고서를 받은 사람이 범칙금을 납부한 사실이 납부기간만료일부터 5일이 지난 날까지 확인되지 아니할 때에는 즉시 범칙자의 주소지를 관할하는 경찰서장 또는 해양경찰서장에게 제3조제1항에 따른 범칙자 적발보고서 사본을 발송하여야 한다. <개정 2014.11.19, 2016.7.19, 2017.7.26>', 5652);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10004, '① 제3조제3항 및 제7조제2항에 따라 범칙자 적발보고서 사본을 받은 경찰서장 또는 해양경찰서장은 범칙자 적발보고서 사본을 보낸 경찰서장등에게 범칙금 납부통고서를 받은 사람의 즉결심판 청구에 필요한 자료를 요청할 수 있다. <개정 2014.11.19, 2017.7.26>', 5653);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10005, '② 제3조제3항 및 제7조제2항에 따라 범칙자 적발보고서 사본을 받은 경찰서장 또는 해양경찰서장은 그 내용을 통고처분 접수처리부에 기록하거나 전자매체를 통하여 전산으로 저장ㆍ관리하여야 한다. <개정 2014.11.19, 2017.7.26>', 5653);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10006, '① 「경범죄 처벌법」(이하 "법"이라 한다) 제7조 및 「경범죄 처벌법 시행령」(이하 "영"이라 한다) 제3조제1항에 따른 범칙금 납부통고서 및 범칙금 영수증은 별지 제1호서식에 따르고, 범칙금 납부고지서는 별지 제2호서식에 따른다.', 5656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10007, '② 제1항에도 불구하고 휴대용 컴퓨터 등을 이용하여 범칙금의 납부를 통고하는 경우 범칙금 납부통고서, 범칙금 영수증 및 범칙금 납부고지서는 별지 제3호서식에 따르되, 「도로교통법 시행규칙」 별지 제159호의2서식을 사용할 수 있다.', 5656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10008, '③ 영 제3조제1항에 따른 범칙금 납부고지서 발행원부 및 범칙자 적발보고서는 별지 제4호서식에 따른다.', 5656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10009, '④ 영 제3조제2항에 따른 통고처분처리부는 별지 제5호서식에 따른다.', 5656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10010, '① 법 제9조제1항제1호에 해당하는 사람에게 영 제6조제1항에 따라 발부하는 즉결심판 출석통지서는 별지 제7호서식에 따르고,  영 제6조제3항에 따라 발부하는 즉결심판 출석최고서는 별지 제7호의2서식에 따른다. <개정 2016.7.19>', 5658);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10011, '② 제1항에도 불구하고 경찰서장, 해양경찰서장 및 제주특별자치도지사는 휴대용 컴퓨터 등을 이용하여 별지 제8호서식에 따른 현장 즉결심판 출석통지서로 즉결심판 출석통지를 할 수 있다. <신설 2015.7.2, 2016.7.19, 2017.7.26>', 5658);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10012, '③ 법 제9조제1항제2호에 해당하는 사람에게 영 제6조제2항 및 제3항에 따라 발부하는 즉결심판 출석통지서(최고서), 범칙금등 영수증 및 범칙금등 납부고지서는 별지 제9호서식에 따른다. <개정 2015.7.2>', 5658);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10013, '④ 영 제6조제5항에 따른 즉결심판사범 적발보고서는 별지 제10호서식에 따르고, 즉결심판청구서는 별지 제11호서식에 따른다. <개정 2015.7.2>', 5658);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10014, '① 삭제 <2016.1.6>', 5662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10015, '② 2명 이상이 공동하여 다음 각 호의 죄를 범한 사람은 「형법」 각 해당 조항에서 정한 형의 2분의 1까지 가중한다. <개정 2016.1.6>', 5662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10016, '③ 이 법(「형법」 각 해당 조항 및 각 해당 조항의 상습범, 특수범, 상습특수범, 각 해당 조항의 상습범의 미수범, 특수범의 미수범, 상습특수범의 미수범을 포함한다)을 위반하여 2회 이상 징역형을 받은 사람이 다시 제2항 각 호에 규정된 죄를 범하여 누범(累犯)으로 처벌할 경우에는 다음 각 호의 구분에 따라 가중처벌한다. <개정 2016.1.6>', 5662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10017, '④ 제2항과 제3항의 경우에는 「형법」 제260조제3항 및 제283조제3항을 적용하지 아니한다.', 5662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10018, '① 삭제 <2016.1.6>', 5663);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10019, '② 삭제 <2006.3.24>', 5663);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10020, '③ 삭제 <2016.1.6>', 5663);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10021, '④ 이 법(「형법」 각 해당 조항 및 각 해당 조항의 상습범, 특수범, 상습특수범, 각 해당 조항의 상습범의 미수범, 특수범의 미수범, 상습특수범의 미수범을 포함한다)을 위반하여 2회 이상 징역형을 받은 사람이 다시 다음 각 호의 죄를 범하여 누범으로 처벌할 경우에는 다음 각 호의 구분에 따라 가중처벌한다. <개정 2014.12.30, 2016.1.6>', 5663);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10022, '① 이 법에 규정된 범죄를 목적으로 하는 단체 또는 집단을 구성하거나 그러한 단체 또는 집단에 가입하거나 그 구성원으로 활동한 사람은 다음 각 호의 구분에 따라 처벌한다.', 5664);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10023, '② 제1항의 단체 또는 집단을 구성하거나 그러한 단체 또는 집단에 가입한 사람이 단체 또는 집단의 위력을 과시하거나 단체 또는 집단의 존속ㆍ유지를 위하여 다음 각 호의 어느 하나에 해당하는 죄를 범하였을 때에는 그 죄에 대한 형의 장기(長期) 및 단기(短期)의 2분의 1까지 가중한다. <개정 2016.1.6>', 5664);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10024, '③ 타인에게 제1항의 단체 또는 집단에 가입할 것을 강요하거나 권유한 사람은 2년 이상의 유기징역에 처한다.', 5664);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10025, '④ 제1항의 단체 또는 집단을 구성하거나 그러한 단체 또는 집단에 가입하여 그 단체 또는 집단의 존속ㆍ유지를 위하여 금품을 모집한 사람은 3년 이상의 유기징역에 처한다.', 5664);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10026, '① 제4조제1항의 단체 또는 집단을 이용하여 이 법이나 그 밖의 형벌 법규에 규정된 죄를 범하게 한 사람은 그 죄에 대한 형의 장기 및 단기의 2분의 1까지 가중한다.', 5665);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10027, '② 제4조제1항의 단체 또는 집단을 구성하거나 그러한 단체 또는 집단에 가입하지 아니한 사람이 그러한 단체 또는 집단의 구성ㆍ유지를 위하여 자금을 제공하였을 때에는 3년 이상의 유기징역에 처한다.', 5665);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10028, '① 이 법에 규정된 죄를 범한 사람이 흉기나 그 밖의 위험한 물건 등으로 사람에게 위해(危害)를 가하거나 가하려 할 때 이를 예방하거나 방위(防衛)하기 위하여 한 행위는 벌하지 아니한다.', 5668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10029, '② 제1항의 경우에 방위 행위가 그 정도를 초과한 때에는 그 형을 감경한다.', 5668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10030, '③ 제2항의 경우에 그 행위가 야간이나 그 밖의 불안한 상태에서 공포ㆍ경악ㆍ흥분 또는 당황으로 인한 행위인 때에는 벌하지 아니한다.', 5668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10031, '① 사법경찰관리(司法警察官吏)로서 이 법에 규정된 죄를 범한 사람을 수사하지 아니하거나 범인을 알면서 체포하지 아니하거나 수사상 정보를 누설하여 범인의 도주를 용이하게 한 사람은 1년 이상의 유기징역에 처한다.', 5669);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10032, '② 뇌물을 수수(收受), 요구 또는 약속하고 제1항의 죄를 범한 사람은 2년 이상의 유기징역에 처한다.', 5669);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10033, '① 관할 지방검찰청 검사장은 제2조부터 제6조까지의 범죄가 발생하였는데도 그 사실을 자신에게 보고하지 아니하거나 수사를 게을리하거나 수사능력 부족 또는 그 밖의 이유로 사법경찰관리로서 부적당하다고 인정하는 사람에 대해서는 그 임명권자에게 징계, 해임 또는 교체임용을 요구할 수 있다.', 5670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10034, '② 제1항의 요구를 받은 임명권자는 2주일 이내에 해당 사법경찰관리에 대하여 행정처분을 한 후 그 사실을 관할 지방검찰청 검사장에게 통보하여야 한다.', 5670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10035, null, 5672);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10036, '①국제수형자이송의 요청 및 승인 등과 관련된 외국과의 문서 또는 통지의 접수 및 송부는 외교부장관이 행한다. 다만, 긴급을 요하거나 특별한 사정이 있는 때에는 법무부장관이 외교부장관의 동의를 얻어 이를 행할 수 있다. <개정 2013.3.23>', 5674);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10037, '②외교부장관은 제1항의 규정에 의하여 외국으로부터 접수한 국제수형자이송과 관련되는 문서 또는 통지를 법무부장관에게 송부하여야 한다. <개정 2013.3.23>', 5674);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10038, '①국내이송은 다음 각호의 요건이 갖추어진 때에 한하여 실시할 수 있다.', 5681);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10039, '②국내이송에 관한 국내이송대상수형자의 동의는 다음 각호의 1에 해당하는 자가 서면으로 확인하여야 한다. 이 경우 국내이송대상수형자에게 제3항의 규정에 의하여 동의의 철회가 인정되지 아니함을 고지하여야 한다.', 5681);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10040, '③국내이송에 관한 국내이송대상수형자의 동의는 제2항의 규정에 의하여 확인된 후에는 그 철회가 인정되지 아니한다.', 5681);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10041, '① 법무부장관은 제11조에 따른 국내이송의 요건이 갖추어져 있고, 대한민국의 안전과 질서 유지, 공공의 이익, 국내이송대상수형자의 선도ㆍ교화 및 사회복귀의 용이성 등을 종합적으로 고려하여 필요하다고 인정하는 경우에만 외국에 대하여 국내이송을 요청하거나 외국의 국내이송 요청을 수락하여야 한다. <개정 2009.3.25>', 5682);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10042, '② 법무부장관은 제1항에 따른 요청 또는 수락을 위하여 필요하면 관계 지방검찰청 또는 지청의 장(이하 "검사장등"이라 한다)에게 관련 자료의 수집 및 송부를 명할 수 있다. <개정 2009.3.25>', 5682);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10043, '③제2항의 규정에 의한 명령을 받은 검사장등은 소속 검사에게 필요한 조치를 취할 것을 명하여야 한다.', 5682);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10044, '④제3항의 규정에 의하여 검사장등으로부터 명령을 받은 검사는 필요한 때에는 사법경찰관리를 지휘하여 자료를 수집하도록 할 수 있다.', 5682);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10045, '① 법무부장관은 국내이송대상수형자를 국내이송하려면 서면으로 관계 검사장등에게 국내이송을 명하여야 한다. 이 경우 관련 자료를 첨부하여야 한다.', 5683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10046, '② 제1항에 따른 명령서에는 다음 각 호의 사항을 적고 법무부장관이 서명ㆍ날인하여야 한다.', 5683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10047, '③ 법무부장관은 다음 각 호의 어느 하나에 해당하는 경우에는 해당 국내이송대상수형자에게 서면으로 통지하여야 한다.', 5683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10048, '①검사장등은 제13조제1항에 따른 국내이송명령을 받은 때에는 지체없이 소속 검사로 하여금 국내이송에 필요한 조치를 취하도록 명하여야 한다. <개정 2009.3.25>', 5684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10049, '②검사는 제1항의 규정에 의하여 국내이송에 필요한 조치를 명령받은 때에는 지체없이 국내이송집행장을 발부하여 외국으로부터 국내이송대상수형자를 인도받고 그 자유형의 집행을 지휘하여야 한다.', 5684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10050, '③제2항의 규정에 의한 국내이송집행장에는 다음 각호의 사항을 기재하고 검사가 서명ㆍ날인하여야 한다.', 5684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10051, '④제2항의 규정에 의한 국내이송집행장에는 외국의 재판서 등본 또는 초본이나 그 밖에 판결이 선고되었음을 증명할 수 있는 서류를 첨부하여야 한다.', 5684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10052, '⑤제2항의 규정에 의하여 발부된 국내이송집행장은 형집행장과 동일한 효력이 있다.', 5684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10053, '⑥형사소송법 제1편제9장중 피고인의 구속에 관한 규정은 국내이송집행장의 집행에 관하여 이를 준용한다.', 5684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10054, '①제14조제2항의 규정에 의하여 국내에 인도된 국내이송대상수형자(이하 "국내이송수형자"라 한다)에 대하여 집행할 자유형의 형기는 외국에서 선고하여 확정된 형기로 한다. 다만, 자유형이 유기인 때에는 50년을 초과하여 집행하지 못하며, 외국에서 선고하여 확정된 자유형이 종신형인 때에는 형기가 무기인 것으로 본다. <개정 2011.4.5>', 5686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10055, '②제1항의 규정에 의하여 자유형을 집행하는 때에는 외국에서 구금되거나 형이 집행된 기간(형의 집행을 감경받은 기간을 포함한다)과 국내이송에 소요된 기간을 형기에 산입한다. <개정 2010.7.23>', 5686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10056, '③외국에서 선고되어 확정된 자유형이 징역에 상당하는 형인 때에는 형법 제67조의 규정에 의하여 집행하며, 금고에 상당하는 형인 때에는 형법 제68조의 규정에 의하여 집행한다.', 5686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10057, '①법무부장관은 외국으로부터 국내이송수형자에 대한 외국법원의 확정판결이 취소되거나 선고된 자유형을 집행하지 아니하기로 확정되었다는 취지의 통지가 있는 때(외국법원의 확정판결이 수 개인 경우에는 그 전부가 취소되거나 집행할 수 없게 된 때에 한한다)에는 지체없이 서면으로 제13조제1항에 따른 국내이송명령을 철회하고, 국내이송수형자가 수용되어 있는 교도소ㆍ소년교도소ㆍ구치소 또는 그 지소(이하 "교도소등"이라 한다)의 소재지를 관할하는 검사장등에게 그 국내이송수형자의 석방을 명하여야 한다. <개정 2009.3.25>', 5689);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10058, '②검사장등은 제1항의 규정에 의하여 법무부장관으로부터 석방명령을 받은 때에는 즉시 소속 검사에게 국내이송수형자의 석방을 명하여야 한다.', 5689);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10059, '③검사는 제2항의 규정에 의한 석방명령을 받은 때에는 즉시 국내이송수형자가 수용되어 있는 교도소등의 장에 대하여 그 국내이송수형자의 석방을 지휘하여야 한다.', 5689);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10060, '①법무부장관은 외국으로부터 감형 또는 그 밖의 사유에 의하여 국내이송수형자에게 선고된 자유형의 종류 또는 형기를 변경한다는 취지의 통지가 있는 때에는 지체없이 서면으로 제13조제1항에 따른 국내이송명령을 변경하고, 국내이송수형자가 수용되어 있는 교도소등의 소재지를 관할하는 검사장등에게 변경된 자유형의 종류 및 기간에 의하여 형을 집행하도록 명하여야 한다. <개정 2009.3.25>', 5690);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10061, '②제13조 및 제14조의 규정은 제1항의 규정에 의한 국내이송명령의 변경 및 그 집행에 관하여 준용한다.', 5690);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10062, null, 5691);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10063, '①국외이송은 다음 각호의 요건이 갖추어진 때에 한하여 실시할 수 있다.', 5693);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10064, '②제1항제3호의 규정에 의한 동의는 법무부장관으로부터 확인을 명령받은 검사장등이 지정한 검사가 서면으로 확인하여야 한다. 이 경우 국외이송대상수형자에게 제3항의 규정에 의하여 동의의 철회가 인정되지 아니함을 고지하여야 한다.', 5693);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10065, '③국외이송에 관한 국외이송대상수형자의 동의는 제2항의 규정에 의하여 확인된 후에는 그 철회가 인정되지 아니한다.', 5693);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10066, null, 5694);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10067, '① 법무부장관은 제23조에 따른 국외이송의 요건이 갖추어져 있고, 대한민국의 안전과 질서 유지, 공공의 이익, 국외이송대상수형자의 선도ㆍ교화와 사회복귀의 용이성 및 국내 재입국 가능성, 국내에서의 다른 사건에 대한 수사 또는 재판상의 필요성 등을 종합적으로 고려하여 필요하다고 인정하는 경우에만 외국에 국외이송을 요청하거나 외국의 국외이송 요청을 수락하여야 한다.', 5695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10068, '② 제1항의 국외이송 요청 대상인 국외이송대상수형자가 군사법원에서 자유형을 선고받은 사람인 경우에는 법무부장관은 미리 국방부장관의 동의를 받아야 하며, 그 결정을 위하여 필요하면 국방부장관에게 이에 관한 협조를 요청할 수 있다.', 5695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10069, '③ 제1항에 따른 법무부장관의 요청 또는 수락에 관하여는 제12조제2항부터 제4항까지의 규정을 준용한다.', 5695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10070, '① 법무부장관은 국외이송대상수형자를 국외이송하려면 서면으로 관계 검사장등에게 국외이송을 명하여야 한다. 이 경우 관련 자료를 첨부하여야 한다.', 5696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10071, '② 제1항에 따른 국외이송 명령서에는 다음 각 호의 사항을 적고, 법무부장관이 서명ㆍ날인하여야 한다.', 5696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10072, '③ 법무부장관은 제1항에 따라 국외이송 명령을 할 때에는 인수허가장을 발부하여 외교부장관에게 송부하고 이를 외국에 송부할 것을 요청하여야 한다. <개정 2013.3.23>', 5696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10073, '④ 법무부장관은 다음 각 호의 어느 하나에 해당하는 경우에는 해당 국외이송대상수형자에게 서면으로 통지하여야 한다.', 5696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10074, '①검사장등은 제26조제1항에 따른 국외이송명령을 받은 때에는 지체없이 소속 검사로 하여금 국외이송에 필요한 조치를 취하도록 명하여야 한다. <개정 2009.3.25>', 5697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10075, '②검사는 제1항의 규정에 의하여 검사장으로부터 국외이송에 필요한 조치를 명령받은 때에는 지체없이 그 국외이송대상수형자가 수용되어 있는 교도소등의 장에게 국외이송지휘서를 발부하고 국외이송을 지휘하여야 한다.', 5697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10076, '③제2항의 규정에 의한 국외이송지휘서에는 다음 각호의 사항을 기재하고 검사가 서명ㆍ날인하여야 한다.', 5697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10077, null, 5700);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10078, '①법무부장관은 군교도소에 수용중인 국외이송대상수형자에 대하여는 국외이송명령을 하기에 앞서 국방부장관에게 그 취지를 통보하여야 한다.', 5701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10079, '②제1항의 규정에 의한 통보를 받은 국방부장관은 해당 군 참모총장에게 국외이송대상수형자를 교도소등에 수용하도록 지시하여야 하며, 이 경우 「군에서의 형의 집행 및 군수용자의 처우에 관한 법률」 제20조제1항에 따른 법무부장관의 동의가 있은 것으로 본다. <개정 2009.11.2>', 5701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10080, '①법무부장관은 대한민국 공무원이 국내이송대상수형자 또는 국외이송대상수형자를 외국의 영역을 통과하여 호송할 필요가 있는 때에는 그 외국에 대하여 통과호송의 승인을 요청할 수 있다.', 5702);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10081, '②법무부장관은 외국으로부터 그 외국의 공무원이 다른 외국의 확정판결에 의하여 그 외국의 교도소등에 수용되어 있는 자를 이송하기 위하여 대한민국의 영역을 통과하여 호송하기 위한 승인을 요청하는 경우 그 요청에 상당한 이유가 있다고 인정되는 때에는 이를 승인할 수 있다. 다만, 그 확정판결에 의하여 인정된 범죄에 관련된 행위가 대한민국의 법률에 의하여 범죄를 구성하지 아니하는 때에는 이를 승인하여서는 아니된다.', 5702);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10082, '③제4조의 규정은 제1항 및 제2항의 통과호송의 요청과 승인 및 이와 관련된 외국과의 문서 또는 통지의 접수 및 송부에 관하여 이를 준용한다.', 5702);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10083, null, 5707);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10084, null, 5710);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10085, null, 5711);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10086, '① 다음 각 호의 어느 하나에 해당하는 부정수표를 발행하거나 작성한 자는 5년 이하의 징역 또는 수표금액의 10배 이하의 벌금에 처한다.', 5716);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10087, '② 수표를 발행하거나 작성한 자가 수표를 발행한 후에 예금부족, 거래정지처분이나 수표계약의 해제 또는 해지로 인하여 제시기일에 지급되지 아니하게 한 경우에도 제1항과 같다.', 5716);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10088, '③ 과실로 제1항과 제2항의 죄를 범한 자는 3년 이하의 금고 또는 수표금액의 5배 이하의 벌금에 처한다.', 5716);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10089, '④ 제2항과 제3항의 죄는 수표를 발행하거나 작성한 자가 그 수표를 회수한 경우 또는 회수하지 못하였더라도 수표 소지인의 명시적 의사에 반하는 경우 공소를 제기할 수 없다.', 5716);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10090, '① 제2조의 경우에 발행인이 법인이나 그 밖의 단체일 때에는 그 수표에 적혀 있는 대표자 또는 작성자를 처벌하며, 그 법인 또는 그 밖의 단체에도 해당 조문의 벌금형을 과(科)한다. 다만, 법인 또는 그 밖의 단체가 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다.', 5717);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10091, '② 대리인이 수표를 발행한 경우에는 본인을 처벌하는 외에 그 대리인도 처벌한다.', 5717);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10092, '① 금융기관에 종사하는 사람이 직무상 제2조제1항(발행인이 법인이나 그 밖의 단체인 경우를 포함한다) 또는 제5조에 규정된 수표를 발견한 때에는 48시간 이내에 수사기관에 고발하여야 하며, 제2조제2항(발행인이 법인이나 그 밖의 단체인 경우를 포함한다)에 규정된 수표를 발견한 때에는 30일 이내에 수사기관에 고발하여야 한다.', 5721);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10093, '② 제1항의 고발을 하지 아니하면 100만원 이하의 벌금에 처한다.', 5721);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10094, '① 「부정수표 단속법」(이하 "법"이라 한다)에 따른 금융기관은 「수표법」과 그 밖의 법령에 따라 수표의 지급 사무를 처리하는 은행 및 은행과 같이 취급되는 사람 또는 시설로 한다.', 5723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10095, '② 법 제2조제1항제1호에 따른 가공인물의 명의는 수표발행인의 명의가 개인인 경우에는 주민등록표상의 성명과 일치하지 아니하는 것으로 하고, 법인인 경우에는 법인 등기사항증명서상의 상호ㆍ명칭과 일치하지 아니하는 것으로 한다.', 5723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10096, '③ 법 제2조제2항에 따른 제시기일은 「수표법」 제28조제2항에 따라 수표를 제시한 날 및 같은 법 제29조에 따라 지급제시기간에 금융기관에 지급을 받기 위하여 수표를 제시한 날로 한다.', 5723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10097, '④ 법 제2조제2항에 따른 제시기일에 지급되지 아니하게 한 경우는 「수표법」 제39조의 지급거절을 증명하였을 때로 한다.', 5723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10098, '①영 제2조제2항의 규정에 의하여 수사자료표를 작성함에 있어서 지문을 채취할 피의자의 범위는 다음 각호와 같다.', 5725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10099, '②피의자가 제1항 각호의 1에 해당하지 아니하는 경우에도 피의자가 다음 각호의 1에 해당하는 때에는 당해피의자의 지문을 채취한다.', 5725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10100, '③제1항의 규정에 불구하고 고소 또는 고발사건중 다음 각호의 1의 불기소처분사유에 해당하는 피의자에 대하여는 수사자료표작성과 지문채취를 하지 아니한다. 다만, 피의자가 제2항제1호, 제2호 또는 제4호의 1에 해당하는 때에는 그러하지 아니하다. <신설 1993.12.31, 1995.6.24, 1999.3.30>', 5725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10101, '①법원에 제출되어 있는 증거물등에 대한 법 제17조제3항의 규정에 의한 인도허가청구서에는 다음 각호의 사항을 기재하고 청구한 검사가 서명날인하여야 한다.', 5727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10102, '②제1항제3호의 인도할 증거물을 기재함에 있어서는 그 증거물이 법원에 제출될 당시의 관련사건 및 제출자를 명시하여야 한다.', 5727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10103, '①검사가 법 제17조제3항의 규정에 의한 청구를 할때에는 피의자에게 범죄의 혐의가 있고 법원에 제출되어 있는 증거물을 인도하여야 할 필요가 있음을 인정할 수 있는 자료를 제출하여야 한다.', 5728);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10104, '②제1항의 경우에 증거물의 인도에 관하여 이해관계있는 자가 있는 때에는 그의 동의서를 첨부하여야 한다.', 5728);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10105, '① 「아동학대범죄의 처벌 등에 관한 특례법」(이하 "법"이라 한다) 제9조제2항 전단에 따른 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ도지사ㆍ특별자치도지사(이하 "시ㆍ도지사"라 한다) 또는 시장ㆍ군수ㆍ구청장(자치구의 구청장을 말한다. 이하 같다)의 친권상실의 선고 청구 요청 또는 후견인의 변경 심판 청구 요청은 별지 제1호서식에 따른다. <개정 2020.9.28>', 5732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10106, '② 검사는 제1항에 따른 친권상실의 선고 청구 요청 또는 후견인의 변경 심판 청구 요청에 대하여 별지 제2호서식에 따라 그 처리 결과를 통보하여야 한다.', 5732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10107, '① 법 제11조제1항 후단 및 같은 조 제3항 전단에 따른 동행 요청은 별지 제3호서식에 따른다. 다만, 긴급한 경우에는 구두로 요청할 수 있다. <개정 2020.9.28>', 5733);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10108, '② 제1항 단서에 따라 구두로 요청한 경우에는 지체 없이 별지 제3호서식의 동행요청서를 송부해야 한다. <신설 2020.9.28>', 5733);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10109, '③ 법 제11조제4항에 따른 아동보호전문기관의 직원의 증표는 별지 제4호서식에 따른다. <개정 2020.9.28>', 5733);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10110, '① 법 제11조의2제1항에 따른 출석ㆍ진술 및 자료제출의 요구는 별지 제4호의2서식에 따른다.', 5734);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10111, '② 아동학대행위자 또는 관계인이 법 제11조의2제2항에 따라 준용되는 「행정조사기본법」 제9조제2항에 따라 「아동복지법」 제22조제4항에 따른 아동학대전담공무원(이하 "아동학대전담공무원"이라 한다)에게 출석일시를 변경하여 줄 것을 신청하는 경우에는 별지 제4호의3서식의 출석일시 변경신청서를 제출해야 한다.', 5734);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10112, '③ 아동학대전담공무원은 제2항에 따라 출석일시 변경신청을 받은 경우에는 신청을 받은 날부터 7일 이내에 변경여부를 별지 제4호의4서식의 출석일시 변경신청 결과통지서에 따라 아동학대행위자 또는 관계인에게 통지해야 한다.', 5734);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10113, '④ 아동학대전담공무원은 제1항에 따라 출석ㆍ진술 또는 자료제출의 요구를 한 경우와 제3항에 따라 출석일시 변경신청 결과를 통지한 경우에는 별지 제4호의5서식의 발송확인대장에 해당 사항을 기록해야 한다.', 5734);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10114, '⑤ 아동학대행위자 또는 관계인은 법 제11조의2제2항에 따라 준용되는 「행정조사기본법」 제21조제1항에 따라 의견을 제출하려는 경우에는 별지 제4호의6서식의 의견제출서를 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 제출해야 한다.', 5734);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10115, '① 사법경찰관리 또는 아동학대전담공무원은 법 제12조제2항에 따라 피해아동, 피해아동의 형제자매인 아동 및 피해아동과 동거하는 아동(이하 "피해아동등"이라 한다)을 보호하고 있는 사실을 다음 각 호의 구분에 따라 관할 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 통보해야 한다.', 5735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10116, '② 「아동학대범죄의 처벌 등에 관한 특례법 시행령」 제5조의3제3항에 따른 범죄경력 조회 동의서는 별지 제5호의3서식에 따른다.', 5735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10117, '③ 사법경찰관리 또는 아동학대전담공무원이 법 제12조제5항에 따라 응급조치결과보고서를 작성하는 경우에는 별지 제6호서식에 따른다.', 5735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10118, '① 피해아동등, 그 법정대리인(아동학대행위자를 제외한다. 이하 같다), 변호사(법 제16조에 따른 변호사를 말한다. 이하 같다), 시ㆍ도지사, 시장ㆍ군수ㆍ구청장 또는 아동보호전문기관의 장이 법 제13조제1항에 따른 조치(이하 "긴급임시조치"라 한다)를 신청할 때에는 별지 제7호서식에 따른다. <개정 2020.9.28, 2025.6.20>', 5736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10119, '② 사법경찰관이 법 제13조제1항에 따라 긴급임시조치를 한 때에는 별지 제8호서식의 긴급임시조치결정서를 작성한 후 사건기록에 편철하여야 한다.', 5736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10120, '③ 사법경찰관이 법 제15조제3항에 따라 긴급임시조치를 취소한 때에는 별지 제9호서식의 긴급임시조치 취소결정서를 작성한 후 사건기록에 편철하여야 한다.', 5736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10121, '④ 사법경찰관이 법 제13조제1항에 따라 긴급임시조치를 하거나 법 제15조제3항에 따라 긴급임시조치를 취소한 때에는 긴급임시조치를 신청한 사람에게 그 처리 결과를 알려주어야 한다. 이 경우 처리 결과의 통보는 서면, 전화, 전자우편, 팩스, 휴대전화 문자전송, 그 밖에 적당한 방법으로 할 수 있다. <개정 2020.9.28>', 5736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10122, '① 검사가 법 제14조제1항에 따라 직권으로 임시조치를 청구할 때에는 별지 제10호서식에 따르고, 사법경찰관이나 보호관찰관의 신청에 따라 임시조치를 청구할 때에는 별지 제11호서식에 따른다. 이 경우 사법경찰관이나 보호관찰관이 법 제14조제1항에 따라 검사에게 임시조치를 신청할 때에는 별지 제12호서식에 따른다.', 5737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10123, '② 사법경찰관이 법 제15조제1항에 따라 검사에게 임시조치를 신청할 때에는 별지 제13호서식에 따른다. 이 신청을 받은 검사가 법 제15조제2항에 따라 임시조치를 청구할 때에는 별지 제14호서식에 따른다.', 5737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10124, '③ 제1항 후단 또는 제2항 전단에 따라 사법경찰관이나 보호관찰관이 임시조치를 신청하였을 때에는 별지 제15호서식의 임시조치신청부를 작성하여야 하고, 제1항 전단 또는 제2항 후단에 따라 검사가 임시조치를 청구하였을 때에는 별지 제16호서식의 임시조치청구부를 작성하여야 한다.', 5737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10125, '④ 검사는 법 제14조제1항에 따른 사법경찰관이나 보호관찰관의 임시조치 신청 또는 법 제15조제1항에 따른 사법경찰관의 임시조치 신청을 검토하여 임시조치를 할 만한 상당한 이유가 없다고 인정할 때에는 별지 제17호서식에 그 이유를 구체적으로 기재하여 임시조치 신청을 기각한다. <개정 2025.6.20>', 5737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10126, '⑤ 피해아동등, 그 법정대리인, 변호사, 시ㆍ도지사, 시장ㆍ군수ㆍ구청장 또는 아동보호전문기관의 장이 법 제14조제2항에 따라 임시조치의 청구 또는 그 신청을 요청할 때에는 별지 제18호서식에 따른다. <개정 2020.9.28>', 5737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10127, '⑥ 제5항의 경우에 검사는 임시조치의 청구를 요청한 사람에게 별지 제19호서식에 따라 그 처리 결과를 알려주어야 하고, 사법경찰관은 임시조치의 신청을 요청한 사람에게 별지 제20호서식에 따라 그 처리 결과를 알려주어야 한다. 이 경우 임시조치의 신청 요청을 받은 사법경찰관이 임시조치를 신청하지 않는 경우에는 별지 제21호서식에 따라 검사 및 임시조치의 신청을 요청한 사람에게 그 사유를 통지해야 한다. <개정 2020.9.28>', 5737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10128, '⑦ 사법경찰관리가 법 제21조제1항에 따라 임시조치의 결정을 집행하였을 때에는 집행일시 및 집행방법을 적은 서면을 사건기록에 편철하여야 한다.', 5737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10129, '⑧ 사법경찰관은 임시조치의 결정에 대하여 항고가 제기되어 법원으로부터 수사기록 등본의 제출을 요구받았을 경우에 항고심 재판에 필요한 범위에서 수사기록 등본을 관할 검찰청으로 보내야 한다.', 5737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10130, '⑨ 법 제21조제2항에 따라 임시조치 집행담당자가 아동학대행위자의 임시조치 이행상황에 대해 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 통보할 때에는 별지 제21호의2서식에 따른다. <신설 2020.9.28>', 5737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10131, '⑩ 제1항부터 제9항까지에서 규정한 사항 외에 임시조치의 청구 및 집행 절차 등에 관하여는 「검찰사건사무규칙」 제21조제5항ㆍ제6항 및 제56조의2제6항을 준용한다. <개정 2020.9.28>', 5737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10132, '① 다음 각 호에 해당하는 경우에는 별지 제22호서식에 따른다.', 5738);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10133, '② 법 제22조제2항에 따라 검사가 법원에 임시조치 기간의 연장, 그 종류의 변경 또는 취소 청구를 하는 경우에는 별지 제23호서식에 따르고, 사법경찰관이 검사에게 임시조치 기간의 연장, 그 종류의 변경 또는 취소 신청을 하는 경우에는 별지 제23호의2서식에 따른다.', 5738);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10134, '③ 검사는 법 제22조제2항에 따른 사법경찰관의 임시조치 기간의 연장, 그 종류의 변경 또는 취소 신청을 검토한 결과 해당 청구를 할 상당한 이유가 없다고 인정하는 경우에는 별지 제23호의3서식에 그 이유를 구체적으로 기재하여 신청을 기각한다.', 5738);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10135, '④ 법 제22조제2항에 따라 사법경찰관이 검사에게 임시조치 기간의 연장, 그 종류의 변경 또는 취소 신청을 한 경우에는 별지 제23호의4서식의 임시조치 기간연장ㆍ종류변경ㆍ취소 신청부를 작성해야 하고, 검사가 법원에 임시조치 기간의 연장, 그 종류의 변경 또는 취소 청구를 한 경우에는 별지 제23호의5서식의 임시조치 기간연장ㆍ종류변경ㆍ취소 청구부를 작성해야 한다.', 5738);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10136, '⑤ 법 제19조제1항 각 호의 위탁 대상이 되는 기관의 장이 법 제22조제4항에 따라 임시조치 변경을 청구하는 경우에는 별지 제24호서식에 따른다.', 5738);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10137, '① 법 제31조에 따른 송치서(검사가 법 제28조에 따라 사건을 관할 법원에 송치하는 경우로 한정한다)는 별지 제27호서식에 따른다.', 5740);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10138, '② 검사가 구속되어 있는 아동학대행위자에게 제1항에 따른 아동보호사건 송치 결정(이하 "송치 결정"이라 한다)을 할 때에는 별지 제28호서식에 따라 아동학대행위자를 구금하고 있는 시설의 장에게 아동학대행위자를 관할 법원에 인도할 것을 지휘하여야 한다.', 5740);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10139, '③ 법원이 법 제29조에 따라 구속되어 있는 아동학대행위자에 대한 피고사건을 관할 법원에 송치하는 결정을 하는 경우의 사무처리에 관하여는 제2항을 준용한다.', 5740);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10140, '④ 제1항부터 제3항까지에서 규정한 사항 외에 검사가 구속되어 있는 아동학대행위자를 관할 법원에 송치하는 결정을 하는 경우의 사무처리에 관하여는 「검찰사건사무규칙」 제49조제4항, 제103조제6항ㆍ제7항, 제128조제3항 및 제141조를 준용한다. 이 경우 "가정보호사건"은 "아동보호사건"으로 본다. <개정 2021.1.1>', 5740);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10141, '① 검사가 법 제40조제1항에 따른 보호처분의 변경 청구, 법 제41조에 따른 보호처분의 취소 청구 또는 법 제42조에 따른 보호처분의 종료 청구를 할 때에는 별지 제29호서식에 따르고, 시ㆍ도지사, 시장ㆍ군수ㆍ구청장, 보호관찰관 또는 수탁기관의 장이 같은 청구를 할 때에는 별지 제30호서식에 따른다. <개정 2020.9.28>', 5742);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10142, '② 피해아동, 그 법정대리인 또는 변호사가 법 제41조에 따른 보호처분의 취소 청구 또는 법 제42조에 따른 보호처분의 종료 청구를 할 때에는 별지 제31호서식에 따른다.', 5742);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10143, '① 검사가 법 제47조제1항에 따라 법원에 피해아동보호명령의 청구를 하는 경우에는 별지 제31호의2서식에 따르고, 피해아동보호명령 청구를 한 경우에는 별지 제31호의3서식의 피해아동보호명령 청구부를 작성해야 한다.', 5743);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10144, '② 아동보호전문기관의 장이 법 제47조제2항에 따라 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 피해아동보호명령의 청구를 요청하는 경우에는 별지 제31호의4서식에 따른다.', 5743);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10145, '③ 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 제2항에 따른 청구를 요청받은 경우에는 피해아동보호명령의 청구를 요청한 아동보호전문기관의 장에게 별지 제31호의5서식에 따라 그 처리 결과를 통보해야 한다.', 5743);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10146, '① 검사가 법 제50조제3항에 따라 법원에 피해아동보호명령의 취소 또는 그 종류의 변경을 신청하거나 법 제51조제1항에 따라 피해아동보호명령 기간의 연장을 청구하는 경우에는 별지 제31호의6서식에 따르고, 피해아동보호명령의 취소 또는 그 종류의 변경 신청이나 피해아동보호명령 기간의 연장 청구를 한 경우에는 별지 제31호의7서식의 피해아동보호명령 취소ㆍ종류변경 신청부 및 기간연장 청구부를 작성해야 한다.', 5744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10147, '② 아동보호전문기관의 장이 법 제50조제3항에 따라 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 피해아동보호명령의 취소 또는 그 종류의 변경 신청을 요청하는 경우에는 별지 제31호의8서식에 따른다.', 5744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10148, '③ 보호관찰소의 장 또는 아동보호전문기관의 장이 법 제51조제2항에 따라 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 피해아동보호명령의 연장 청구를 요청하는 경우에는 별지 제31호의9서식에 따른다.', 5744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10149, '④ 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 제3항에 따른 청구를 요청받은 경우에는 피해아동보호명령의 연장 청구를 요청한 보호관찰소의 장 또는 아동보호전문기관의 장에게 별지 제31호의10서식에 따라 그 처리 결과를 통보해야 한다.', 5744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10150, '⑤ 아동보호전문기관의 장이 법 제57조제3항에 따라 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 법 제57조제1항 및 제2항에 따른 항고를 요청하는 경우에는 별지 제31호의11서식에 따른다.', 5744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10151, '① 교도소ㆍ소년교도소ㆍ구치소 또는 그 지소(支所)의 장은 해당 교도소ㆍ소년교도소ㆍ구치소 또는 그 지소 안에서 발생하는 범죄에 관하여 「형사소송법」 제197조제1항에 따른 사법경찰관(이하 "사법경찰관"이라 한다)의 직무를 수행한다. <개정 2021.3.16>', 5748);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10152, '② 소년원 또는 그 분원(分院)의 장이나 소년분류심사원 또는 그 지원(支院)의 장은 각각 해당 소년원 또는 그 분원이나 소년분류심사원 또는 그 지원 안에서 발생하는 범죄에 관하여 사법경찰관의 직무를 수행한다.', 5748);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10153, '③ 보호감호소ㆍ치료감호시설 또는 그 지소의 장은 해당 감호소ㆍ치료감호시설 또는 그 지소 안에서 발생하는 범죄에 관하여 사법경찰관의 직무를 수행한다.', 5748);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10154, '④ 「형의 집행 및 수용자의 처우에 관한 법률」 제8조에 따른 교정시설 순회점검 업무에 종사하는 4급부터 7급까지의 국가공무원은 교정시설 안에서 발생하는 범죄에 관하여 사법경찰관의 직무를, 8급ㆍ9급의 국가공무원은 그 범죄에 관하여 「형사소송법」 제197조제2항에 따른 사법경찰리(이하 "사법경찰리"라 한다)의 직무를 수행한다. <개정 2015.8.11, 2021.3.16>', 5748);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10155, '⑤ 출입국관리 업무에 종사하는 4급부터 7급까지의 국가공무원은 출입국관리에 관한 범죄와 다음 각 호에 해당하는 범죄에 관하여 사법경찰관의 직무를, 8급ㆍ9급의 국가공무원은 그 범죄에 관하여 사법경찰리의 직무를 수행한다. <개정 2015.8.11>', 5748);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10156, '⑥ 보호관찰소 또는 그 지소의 장은 「전자장치 부착 등에 관한 법률」 제38조 또는 제39조에 규정된 피부착자의 범죄에 관하여 사법경찰관의 직무를 수행한다. <신설 2020.12.8>', 5748);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10157, null, 5750);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10158, null, 5751);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10159, '① 「근로기준법」에 따른 근로감독관은 그의 관할 구역에서 발생하는 다음 각 호의 법률에 규정된 범죄에 관하여 사법경찰관의 직무를 수행한다. <개정 2010.5.4, 2010.6.8, 2019.4.30, 2021.6.15, 2022.1.4>', 5752);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10160, '② 지방고용노동청, 지방고용노동청 지청 및 그 출장소에 근무하며 근로감독, 노사협력, 산업안전, 근로여성 보호 등의 업무에 종사하는 8급ㆍ9급의 국가공무원 중 그 소속 관서의 장의 추천에 의하여 그 근무지를 관할하는 지방검찰청검사장이 지명한 자는 제1항의 범죄에 관하여 사법경찰리의 직무를 수행한다. <개정 2010.6.4>', 5752);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10161, '③ 「선원법」에 따른 선원근로감독관은 그의 관할 구역에서 발생하는 선박소유자와 선원의 「선원법」 또는 「근로기준법」에서 규정한 범죄에 관하여 사법경찰관의 직무를 수행한다.', 5752);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10162, '① 해선(海船)[연해항로(沿海航路) 이상의 항로를 항행구역으로 하는 총톤수 20톤 이상 또는 적석수(積石數) 2백 석 이상의 것] 안에서 발생하는 범죄에 관하여는 선장은 사법경찰관의 직무를, 사무장 또는 갑판부, 기관부, 사무부의 해원(海員) 중 선장의 지명을 받은 자는 사법경찰리의 직무를 수행한다.', 5753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10163, '② 항공기 안에서 발생하는 범죄에 관하여는 기장과 승무원이 제1항에 준하여 사법경찰관 및 사법경찰리의 직무를 수행한다.', 5753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10164, '① 금융감독원 또는 그 지원이나 출장소에 근무하는 직원으로서 금융위원회 위원장의 추천에 의하여 그 근무지를 관할하는 지방검찰청 검사장이 지명한 사람 중 다음 각 호의 직원은 관할 구역에서 발생하는 「자본시장과 금융투자업에 관한 법률」에 규정된 범죄에 관하여 사법경찰관의 직무를 수행하고, 그 밖의 직원은 그 범죄에 관하여 사법경찰리의 직무를 수행한다.', 5755);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10165, '② 금융위원회 위원장은 제1항에 따른 추천을 할 때에는 금융감독원 원장의 의견을 들어야 한다.', 5755);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10166, '① 「군사법원법」 제43조제1호 및 제46조제1호에 따른 군사법경찰관리로서 지방검찰청검사장의 지명을 받은 자는 「군용물 등 범죄에 관한 특별조치법」에 규정된 범죄에 관하여 사법경찰관리의 직무를 수행한다.', 5757);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10167, '② 「군사법원법」 제43조제2호와 제46조제2호에 규정된 군사법경찰관리로서 지방검찰청검사장의 지명을 받은 자는 「군사기밀보호법」에 규정된 범죄에 관하여 사법경찰관리의 직무를 수행한다.', 5757);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10168, '①신원관리카드와 함께 사건기록을 배당받은 검사는 사건 종국결정시 신원관리카드에 해당사항을 기재한 후 즉시 신원관리카드를 관리하는 검사에게 이를 인계하고, 신원관리카드를 관리하는 검사는 별지 제7호서식에 의한 범죄신고자등 신원관리카드대장을 작성하여야 한다.', 5768);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10169, '②법원이 법 제6조의 규정에 의하여 보좌인을 지정ㆍ취소 또는 교체한 때에는 별지 제8호서식에 의하여 당해 사건을 기소한 검찰청의 신원관리카드를 관리하는 검사에게 그 내용을 통보하여야 한다.', 5768);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10170, '①법 제9조제2항의 규정에 의한 신원관리카드의 열람허가신청은 별지 제9호서식에 의한다.', 5770);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10171, '②검사는 제1항의 규정에 의한 신원관리카드의 열람허가신청을 받은 때에는 그 허가여부에 대한 결정을 한 후 지체없이 그 결과를 신청인에게 서면으로 통지하여야 한다.', 5770);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10172, '①법 제9조제4항의 규정에 의한 면담신청사실의 통지는 별지 제11호서식에 의한다.', 5772);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10173, '②검사는 제1항의 규정에 불구하고 서면외에 전화ㆍ팩스 등을 이용하여 면담신청사실을 통지할 수 있다. 이 경우 관련 증빙서류를 수사기록에 첨부하여야 한다.', 5772);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10174, '①법 제9조제5항의 규정에 의한 이의신청은 별지 제12호서식에 의한다.', 5773);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10175, '②지방검찰청검사장(지청의 경우에는 지청장)은 제1항의 규정에 의한 이의신청을 받은 때에는 그에 대한 수용여부를 결정한 후 지체없이 그 결과를 이의신청인에게 서면으로 통지하여야 한다.', 5773);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10176, '①영 제11조제2항 후단의 규정에 의하여 가지급결정을 한 때에는 별지 제19호서식에 의한 가구조결정서를 작성하여야 한다.', 5780);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10177, '②영 제18조제1항의 규정에 의한 구조결정서의 작성은 별지 제20호서식에 의하고, 동조제3항의 규정에 의한 구조결정통지는 별지 제21호서식에 의한다.', 5780);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10178, null, 5782);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10179, '①별지 제1호서식 내지 별지 제4호서식 및 별지 제8호서식 내지 별지 제11호서식에 의하여 작성한 서류는 사건기록에 이를 편철한다. 다만, 법 제7조의 규정에 의하여 인적사항의 전부 또는 일부를 기재하지 아니한 범죄신고자등에 대한 신원을 알 수 있는 내용이 기재되어 있는 경우에는 사건기록에 이를 편철하여서는 아니된다.', 5785);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10180, '②제1항의 규정에 의하여 사건기록에 편철한 서류를 제외한 나머지 서류는 그 작성기관의 장이 범죄신고자등 또는 그 친족등에 대한 비밀보호를 위하여 적절한 보존조치를 취한 후 별도로 관리하여야 한다.', 5785);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10181, null, 5787);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10182, '① 군교도관은 직무를 신속ㆍ정확ㆍ공정하게 처리하고, 그 결과를 지체 없이 상관에게 문서 또는 구두로 보고하여야 한다. 다만, 상관으로부터 특별히 명령받은 직무로서 그 직무처리에 많은 시일이 걸리는 경우에는 그 중간 처리상황을 보고하여야 한다.', 5788);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10183, '② 군교도관은 직무수행 중 다음 각 호의 사유가 발생하면 즉시 소장에게 보고하고 그 지시에 따라 필요한 조치를 하여야 한다.', 5788);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10184, '① 군교도소의 교정업무에 관한 중요사항을 심의하기 위하여 군교도소에 군교도관회의를 둔다.', 5791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10185, '② 제1항에 따른 군교도관회의는 소장, 부소장, 과장급 직원 및 군교도관 중에서 소장이 임명하는 4명 이상 10명 이하의 군교도관으로 구성한다.', 5791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10186, '③ 소장은 군교도관회의를 소집하고, 그 의장이 된다.', 5791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10187, '④ 군교도관회의는 구성원 과반수의 출석으로 개의(開議)하고, 출석위원 과반수의 찬성으로 의결한다.', 5791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10188, '① 법 제22조에 따라 군수용자에게 지급하는 의류의 품목은 수용복, 전투복, 체육복, 고무신 및 활동화로 한다.', 5792);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10189, '② 제1항에 따른 의류의 지급수량, 지급횟수 등에 대한 기준은 「군복 및 군일용품 지급규정」에 따른 현역 군인의 의류지급기준에 따른다.', 5792);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10190, '① 법 제22조에 따라 군수용자에게 지급하는 침구의 품목은 이불, 매트리스, 담요 및 베개로 한다.', 5793);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10191, '② 제1항에 따른 침구는 1명당 1매로 한다.', 5793);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10192, '③ 법 제22조에 따라 군수용자에게 지급하는 생활용품의 품목, 지급수량, 지급횟수 등에 대한 기준은 「군복 및 군일용품 지급규정」에 따른 현역 군인의 생활용품의 지급기준에 따른다.', 5793);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10193, '① 자비구매물품은 군교정시설이나 부대 내에서 판매하는 것으로 하며, 종류는 다음 각 호와 같다.', 5796);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10194, '② 국방부장관은 자비구매물품 공급의 군교정시설 간 균형 및 군교정시설의 안전과 질서유지를 위하여 필요한 경우에 공급물품의 품목 및 규격 등에 대한 통일된 기준을 정할 수 있다.', 5796);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10195, '③ 제1항 각 호에 해당하는 자비구매물품의 품목, 유형 및 규격 등에 관한 세부사항은 제2항 및 영 제31조의 기준에 어긋나지 아니하는 범위에서 수용생활에 필요한 정도, 가격과 품질, 다른 군교정시설과의 균형, 공급의 용이성 및 군수용자의 선호도 등을 고려하여 소장이 정한다.', 5796);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10196, '① 소장은 군수용자가 자비구매물품의 구매를 신청하는 경우에는 군교정시설의 보관범위 및 군수용자의 소지범위에서 다음 각 호의 구분에 따라 허가할 수 있다.', 5797);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10197, '② 소장은 감염병(「감염병의 예방 및 관리에 관한 법률」에 따른 감염병을 말한다)의 유행 또는 군수용자의 징벌 집행 등으로 자비구매물품의 사용이 중지된 경우에는 구매신청을 제한할 수 있다. <개정 2014.11.3>', 5797);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10198, '① 소장은 물품공급업무 담당자를 검수관(檢收官)으로 지정하여 자비구매물품 공급자로부터 납품받은 제품의 수량, 상태 및 유통기한 등을 검사하게 하여야 한다.', 5799);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10199, '② 검수관은 공급제품이 부패, 파손, 규격 미달, 그 밖의 사유로 군수용자에게 공급하기에 적당하지 아니하다고 인정하는 경우에는 소장에게 보고하고 필요한 조치를 하여야 한다.', 5799);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10200, '① 소장은 군수용자에게 자비구매물품의 품목ㆍ가격, 그 밖의 구매에 관한 주요사항을 미리 알려주어야 한다.', 5800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10201, '② 소장은 제품의 변질ㆍ파손, 그 밖의 정당한 사유로 군수용자가 교환 또는 반품을 원하는 경우에는 신속히 적절한 조치를 하여야 한다.', 5800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10202, '① 소장은 법 제27조에 따라 군수용자 외의 사람이 군수용자에게 금품을 교부하려고 신청하는 경우에는 현금ㆍ수표 및 우편환의 범위에서 허가한다. <개정 2020.2.3>', 5801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10203, '② 소장은 법 제27조에 따라 군수용자 외의 사람이 군수용자에게 음식물을 교부하려고 신청하는 경우에는 군교정시설에서 판매하는 음식물 중에서 허가한다.', 5801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10204, '③ 소장은 법 제27조에 따라 군수용자 외의 사람이 군수용자에게 음식물 외의 물품을 교부하려고 신청하는 경우 그 물품이 다음 각 호의 어느 하나에 해당하지 아니하면 군교정시설의 보관범위 및 군수용자의 소지범위에서 허가한다.', 5801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10205, '① 군교정시설에는「의료법」 제3조에 따른 의료기관 중 의원(醫院)이 갖추어야 하는 시설 이상의 의료시설(진료실 등의 의료용 건축물을 말한다. 이하 같다)을 갖추어야 한다. 다만, 즉시 접근이 가능한 군부대 내에 의료시설을 갖춘 경우는 그러하지 아니하다.', 5802);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10206, '② 군교정시설에 갖춰 둬야 하는 의료장비(혈압측정기 등의 의료기기를 말한다)의 기준은 별표 1과 같다.', 5802);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10207, '③ 의료시설의 세부종류 및 설치기준은 국방부장관이 정한다.', 5802);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10208, '① 소장은 수용정원과 시설여건 등을 고려하여 적정한 양의 비상의료용품을 갖추어야 한다.', 5803);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10209, '② 제1항에 따라 군교정시설에 갖춰 둬야 하는 비상의료용품의 기준은 별표 2와 같다.', 5803);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10210, null, 5804);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10211, '① 소장은 군교정시설의 안전과 질서를 해치지 아니하는 범위에서 종교단체 또는 종교인이 주관하는 종교행사를 실시한다.', 5805);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10212, '② 소장은 종교행사를 위하여 종교별 성상ㆍ성물ㆍ성화ㆍ성구가 구비된 종교관(종교행사를 할 수 있는 종교상담실ㆍ교리교육실 등을 말한다. 이하 같다)을 설치할 수 있으며, 특정 종교행사를 위하여 임시행사장을 설치하는 경우에는 성상 등을 임시로 둘 수 있다.', 5805);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10213, null, 5806);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10214, '① 소장은 군수용자가 종교상담을 신청하거나 군수용자에게 종교상담이 필요한 경우에는 해당 종교를 신봉하는 군교도관 또는 교정참여인사로 하여금 상담하게 할 수 있다.', 5807);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10215, '② 소장은 제1항에 따른 종교상담의 중요 내용을 기록하여 군수용자 처우에 활용할 수 있다. 이 경우 군수용자의 개인정보가 유출되지 아니하도록 하여야 한다.', 5807);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10216, null, 5808);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10217, null, 5810);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10218, '① 군수용자를 대상으로 하는 방송은 무상으로 한다.', 5812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10219, '② 국방부장관은 방송의 전문성을 강화하기 위하여 외부전문가의 협력을 구할 수 있고, 모든 군교정시설의 군수용자를 대상으로 하는 통합방송을 할 수 있다.', 5812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10220, '③ 소장은 방송에 대한 의견 수렴을 위하여 설문조사 등의 방법으로 군수용자의 반응도 및 만족도를 측정할 수 있다.', 5812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10221, '① 소장은 방송을 위하여 텔레비전, 비디오카세트레코더(VCR), 앰프, 스피커 등의 장비와 방송선로 등의 시설을 갖추어야 한다.', 5813);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10222, '② 소장은 물품관리법령에 따라 제1항의 장비와 시설을 정상적으로 유지ㆍ관리하여야 한다.', 5813);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10223, '① 소장은 「방송법」 제2조의 텔레비전방송 또는 라디오방송을 생방송하거나 이를 녹음ㆍ녹화한 것을 방송할 수 있으며, 비디오테이프에 의한 영상물 또는 자체 제작한 영상물을 방송할 수 있다.', 5815);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10224, '② 방송프로그램은 그 내용에 따라 다음 각 호와 같이 구분한다.', 5815);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10225, '③ 소장은 방송프로그램을 자체 편성하는 경우 다음 각 호의 어느 하나에 해당하는 내용이 포함되지 아니하도록 특히 유의하여야 한다.', 5815);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10226, '① 군수용자는 소장이 지정한 장소에서 텔레비전을 시청하거나 라디오방송을 청취를 하여야 한다.', 5816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10227, '② 군수용자는 방송설비 또는 채널을 마음대로 조작ㆍ변경하거나 개인적으로 방송 수신 장비를 소지해서는 아니 된다.', 5816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10228, '③ 군수용자가 군교정시설에 설치된 방송시설과 장비를 손상하거나 그 밖의 방법으로 그 효용을 해친 경우에는 이를 배상하여야 한다.', 5816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10229, null, 5817);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10230, null, 5819);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10231, '① 정기심사는 영 제76조에 따라 군수형자의 처우가 개시된 날부터 다음 각 호의 구분에 따른 기간마다 실시한다.', 5820);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10232, '② 정기심사는 제1항 각 호에 해당하는 날이 해당 월 15일 이전에 속한 경우에는 그 달 25일까지, 해당 월 15일 이후에 속한 경우에는 그 다음달 10일까지 하여야 한다.', 5820);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10233, '③ 정기심사일과 제35조에 따른 형기의 3분의 1 심사일이 같을 때에는 형기의 3분의 1 심사를 정기심사에 갈음한다.', 5820);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10234, '④ 정기심사 기간에 제35조에 따른 형기의 3분의 1 심사 또는 제36조에 따른 특별심사를 하였을 때에는 그 심사일부터 제1항에 따른 정기심사의 기간을 계산한다.', 5820);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10235, null, 5821);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10236, '① 특별심사는 다음 각 호의 어느 하나에 해당하는 경우에 실시한다.', 5822);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10237, '② 특별심사 대상자는 군교도관회의에서 결정한다.', 5822);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10238, null, 5823);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10239, '① 군교도소에 처음으로 입소한 군수형자의 처우등급은 4급으로 하고, 차례로 상위등급으로 승급시킨다.', 5825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10240, '② 법 제93조에 따른 징벌을 받은 군수형자에 대해서는 그 정상(情狀)에 따라 처우등급을 1등급 이상 강등시킬 수 있다.', 5825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10241, '③ 제2항에 따라 강등된 군수형자에 대해서는 징벌기간이 만료된 날부터 제34조에 따른 정기심사 기간을 계산한다.', 5825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10242, '① 소장은 군수형자에 대하여 처우등급 심사를 하였을 때에는 별지 제2호서식의 처우등급심사표를 작성ㆍ관리하여야 한다.', 5827);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10243, '② 소장은 군수형자를 다른 교도소로 이송할 때에는 제1항에 따른 처우등급심사표를 그 군수형자가 이송되는 교도소의 소장에게 송부하여야 한다.', 5827);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10244, '① 소장은 형의 집행정지 중에 있는 사람이 기간만료 그 밖의 정지사유 소멸로 재수용된 경우에는 석방 당시와 동일한 처우등급을 부여한다.', 5829);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10245, '② 소장은 가석방 취소로 재수용되어 남은 형이 집행되는 경우에는 석방 당시보다 한 단계 낮은 처우등급을 부여한다. 다만, 특히 고려할 만한 사유가 있는 때에는 석방 당시와 동일한 처우등급을 부여할 수 있다. <개정 2020.2.3>', 5829);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10246, '① 소장은 처우등급 2급 이상의 군수형자 중 교정성적, 나이, 인성 등을 고려하여 다른 군수형자의 모범이 된다고 인정되는 사람을 봉사원으로 선정하여 담당 군교도관의 사무처리 그 밖의 업무를 보조하게 할 수 있다.', 5832);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10247, '② 봉사원의 활동기간은 6개월로 하되, 필요한 경우에는 그 기간을 1회 연장할 수 있다.', 5832);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10248, '③ 소장은 봉사원의 활동과 역할수행이 적당하지 아니하다고 인정하는 경우에는 선정을 취소할 수 있다.', 5832);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10249, '④ 봉사원의 선정, 기간연장 및 선정취소에 관한 사항은 군교도관회의 의결로 정한다.', 5832);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10250, '① 소장은 군수용자의 처우를 위하여 필요하다고 인정되면 처우등급 2급 이상의 군수형자에게 자치생활을 하게 할 수 있다. 다만, 처우상 특히 필요한 경우에는 처우등급 3급 이하의 군수형자를 포함할 수 있다.', 5833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10251, '② 제1항에 따른 자치생활의 범위는 인원 점검, 취미활동, 일정한 구역에서의 생활 등으로 한다.', 5833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10252, '③ 소장은 제1항에 따라 자치생활을 하는 군수형자들이 교육실ㆍ강당 등 적당한 장소에서 월 1회 이상 토론회를 할 수 있도록 하여야 한다.', 5833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10253, '④ 소장은 군수형자가 국방부장관 또는 소장이 정하는 자치생활에 관한 준수사항을 위반한 경우에는 자치생활의 허가를 취소할 수 있다.', 5833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10254, null, 5834);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10255, '① 소장은 군수형자의 교정ㆍ교화와 사회생활 적응 능력을 기르도록 처우하기 위하여 군교정시설에 수용시설과 별도로 군수형자와 그 가족이 숙식을 함께할 일반주택 형태의 건축물(이하 "가족 만남의 집"이라 한다)을 설치할 수 있고, 군수형자와 그 가족이 군교정시설 내의 일정한 장소에서 다과와 음식을 함께 나누면서 대화의 시간을 갖는 행사(이하 "가족 만남의 날 행사"라 한다)를 할 수 있다.', 5836);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10256, '② 소장은 처우등급 2급 이상의 군수형자에 대하여 가족 만남의 집을 이용하게 하거나 가족 만남의 날 행사에 참여하게 할 수 있다. 이 경우 제48조에 따른 접견 허용횟수에는 포함하지 아니한다.', 5836);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10257, '③ 소장은 가족이 없는 군수형자에 대해서는 자매결연자 또는 후원자 등에게 가족을 대신하여 가족 만남의 날 행사에 참여하게 할 수 있다.', 5836);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10258, '④ 소장은 제2항 전단에도 불구하고 교화를 위하여 특히 필요한 경우에는 처우등급 3급 이하의 군수형자에게도 가족 만남의 집 이용이나 가족 만남의 날 행사에 참여하도록 할 수 있다.', 5836);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10259, '① 군수형자의 처우등급별 전화통화의 허용횟수는 다음 각 호와 같다.', 5837);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10260, '② 소장은 제1항에도 불구하고 처우상 특히 필요한 경우에는 처우등급 2급 이상 군수형자의 전화통화 허용횟수를 늘릴 수 있으며, 처우등급 3급 이하 군수형자에게도 전화통화를 허가할 수 있다.', 5837);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10261, '① 소장은 처우등급 2급 이상인 군수형자 중에서 작업기술이 탁월하고 작업성적이 우수한 군수형자에게 자신을 위한 개인작업을 하게 할 수 있다. 이 경우 개인작업 시간은 교도작업에 지장을 주지 아니하는 범위에서 1일 2시간 이내로 한다.', 5839);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10262, '② 소장은 제1항에 따라 개인작업을 하는 군수형자에게 개인작업 용구를 사용하게 할 수 있다. 이 경우 작업용구는 특정한 용기에 보관하도록 하여야 한다.', 5839);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10263, '③ 개인작업에 필요한 작업재료 등의 구입비용은 군수형자가 부담한다. 다만, 처우상 필요한 경우에는 예산의 범위에서 그 비용을 지원할 수 있다.', 5839);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10264, '① 소장은 처우등급 2급 이상인 군수형자 중에서 직업능력 향상을 위하여 특히 필요하다고 인정하는 경우에는 군교정시설 외의 공공기관 또는 기업체 등에서 운영하는 직업훈련을 받게 할 수 있다.', 5840);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10265, '② 제1항에 따른 직업훈련의 비용은 군수형자가 부담한다. 다만, 처우상 특히 필요한 경우에는 예산의 범위에서 그 비용을 지원할 수 있다.', 5840);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10266, '① 소장은 법 제53조제1항 및 제2항에 따른 교육대상자를 각 교육과정의 교육계획, 교육시설의 규모, 교육대상인원과 군수형자의 나이, 학력, 교정성적, 자체 평가시험 성적, 정신자세, 성실성 등을 고려하여 선발하여야 한다.', 5841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10267, '② 소장은 군수형자가 정당한 이유 없이 법 제53조에 따른 교육을 기피하였거나 교육기관에서 자퇴(제적을 포함한다)한 사실이 있을 때에는 교육대상자로 선발하지 아니할 수 있다.', 5841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10268, '① 소장은 교육대상자가 다음 각 호의 어느 하나에 해당하는 경우에는 교육대상자 선발을 취소할 수 있다.', 5842);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10269, '② 소장은 교육대상자가 질병에 걸리거나 부상을 당한 경우, 그 밖의 부득이한 사정이 있는 경우에는 교육과정을 일시 중지할 수 있다.', 5842);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10270, null, 5843);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10271, '① 소장은 다음 각 호의 시험을 준비하는 군수형자 중 제59조제2항 각 호의 요건을 갖춘 사람을 대상으로 검정고시반을 설치ㆍ운영할 수 있다.', 5844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10272, '② 소장은 교육기간에 검정고시에 합격한 군수형자에 대하여 해당 교육과정을 조기 수료시키거나 상위 교육과정에 임시 배치시킬 수 있다.', 5844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10273, '① 소장은 고등학교과정의 교육기회를 부여하기 위하여 「초ㆍ중등교육법」 제51조에 따른 방송통신고등학교 교육과정을 설치ㆍ운영할 수 있다.', 5845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10274, '② 소장은 다음 각 호의 요건을 갖춘 군수형자가 방송통신고등학교 교육과정에 지원하여 합격한 경우에는 교육생으로 선발할 수 있다.', 5845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10275, '③ 제1항의 교육에 필요한 비용은 자비부담을 원칙으로 한다. 다만, 소장은 제1항의 방송통신고등학교 교육과정의 입학금, 수업료, 교과용 도서구입비 등 교육에 필요한 비용을 예산 범위에서 지원할 수 있다.', 5845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10276, '① 군사교육훈련은 정신교육, 제식훈련 등 기본군사훈련을 위주로 실시한다.', 5847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10277, '② 소장은 군사교육훈련이 군수형자에 대한 징벌수단, 보복조치로 악용되지 않도록 주의하여야 한다.', 5847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10278, '① 소장은 교육ㆍ훈련기간 중 각 교육과목에 대한 성적평가를 위하여 시험 또는 교육사열(敎育査閱)을 실시하여야 한다.', 5851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10279, '② 소장은 시험 또는 교육사열 결과 성적이 불량하여 교육ㆍ훈련의 효과를 거두지 못하였다고 인정되는 군수형자에 대해서는 다시 교육ㆍ훈련을 실시할 수 있다.', 5851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10280, '③ 소장은 군사교육훈련과정 외 교육과정에서 성적이 현저히 불량한 군수형자에 대하여 해당 교육과정을 중단시킬 수 있다.', 5851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10281, null, 5855);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10282, '① 소장은 군수형자와 그 가족의 관계를 유지ㆍ회복하기 위하여 군수형자의 가족이 참여하는 각종 프로그램을 실시할 수 있다. 다만, 가족이 없는 군수형자의 경우 교화를 위하여 필요하면 결연을 맺은 사람이나 그 밖에 가족에 준하는 사람의 참여를 허가할 수 있다.', 5858);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10283, '② 제1항에 따른 가족관계 회복프로그램의 대상이 되는 군수형자는 제50조에 따라 가족 만남의 집을 이용하거나 가족 만남의 날 행사에 참여할 수 있는 사람을 대상자로 하여 군교정시설 안에서 실시하며, 참여인원은 5명 이내의 가족으로 한다. 다만, 특히 필요하다고 인정하는 경우에는 참여인원을 늘릴 수 있다.', 5858);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10284, '① 소장은 군수형자의 건전한 가치관 형성, 정서안정, 고충 해소 등을 위하여 교화상담을 실시할 수 있다.', 5859);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10285, '② 소장은 제1항에 따른 교화상담을 위하여 군교도관이나 교정참여인사를 교화상담자로 지정할 수 있고, 군수형자의 안정을 위하여 결연을 주선할 수 있다.', 5859);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10286, '① 소장은 교화프로그램을 운영하는 경우에 성폭력, 약물중독, 정신질환 등 군수형자의 개별 특성을 고려하여야 하며, 프로그램의 성격 및 시설의 규모와 인원을 고려하여 이송 등의 적절한 조치를 할 수 있다.', 5860);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10287, '② 소장은 교화프로그램의 운영을 위하여 군수형자의 정서적인 안정이 보장될 수 있는 장소를 따로 정하거나 방송설비 및 방송기기를 이용할 수 있다.', 5860);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10288, '③ 소장은 교화프로그램의 주요 진행내용을 기록하여 군수형자 처우에 활용하여야 하며, 상담내용 등 개인정보가 유출되지 아니하도록 하여야 한다.', 5860);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10289, '① 영 제81조제3항에 따른 작업의 종류는 군납물품 생산 및 관용작업으로 한다.', 5861);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10290, '② 영 제81조제3항에 따른 작업시간은 1일 8시간 이하로 한다.', 5861);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10291, '③ 제1항에 따른 작업의 구체적인 내용은 국방부조사본부장의 승인을 받아 소장이 정한다. <개정 2014.11.3>', 5861);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10292, '① 소장은 작업실적ㆍ작업시간을 참작하여 작업에 종사한 군수형자에게 작업등급을 부여하여야 한다.', 5863);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10293, '② 제1항에 따른 작업등급은 다음 각 호의 구분에 따른다.', 5863);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10294, '③ 소장은 작업성적 및 품행이 특히 우수하다고 인정되는 군수형자에 대해서는 제2항 각 호에 규정된 작업기간의 2분의 1 이상을 종사하였을 때에 바로 상위의 작업등급을 부여할 수 있다.', 5863);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10295, '① 법 제58조제2항에 따른 외부통근자의 선정기준은 다음 각 호와 같다.', 5864);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10296, '② 소장은 제1항에도 불구하고 작업의 성격이나 교화를 위하여 특히 필요하다고 인정하는 경우에는 제1항의 군수형자 외의 군수형자도 외부통근자로 선정할 수 있다.', 5864);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10297, '① 법 제59조에 따른 기술 습득 및 향상을 위한 직업능력개발훈련(이하 "직업훈련"이라 한다)의 직종 선정 및 훈련과정별 인원은 국방부조사본부장의 승인을 받아 소장이 정한다. <개정 2014.11.3>', 5869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10298, '② 직업훈련 대상자는 소속 기관의 군수형자 중에서 소장이 선정한다.', 5869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10299, null, 5870);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10300, null, 5871);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10301, '① 국방부장관은 직업훈련을 위하여 필요한 경우에는 군수형자를 다른 군교정시설로 이송할 수 있다.', 5872);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10302, '② 소장은 제1항에 따라 이송된 군수형자나 직업훈련 중인 군수형자를 다른 군교정시설로 이송해서는 아니 된다. 다만, 훈련 취소 등 특별한 사유가 있는 경우에는 그러하지 아니하다.', 5872);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10303, '① 소장은 직업훈련 대상자가 다음 각 호의 어느 하나에 해당하는 경우에는 직업훈련을 보류할 수 있다.', 5873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10304, '② 소장은 제1항에 따라 직업훈련이 보류된 군수형자의 보류 사유가 소멸된 경우에는 본래의 과정에 복귀시켜 훈련할 수 있게 하여야 한다. 다만, 본래 과정으로 복귀시키는 것이 적당하지 아니하다고 인정되는 경우에는 해당 훈련을 취소할 수 있다.', 5873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10305, '① 법 제66조제1항제4호에서 "교화나 건전한 사회복귀를 위하여 국방부령으로 정하는 사유"란 다음 각 호의 어느 하나에 해당하는 사유를 말한다.', 5874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10306, '② 소장은 처우등급 2급 이상인 군수형자에 한정하여 법 제66조에 따라 귀휴를 허가할 수 있다. 다만, 교정ㆍ교화 또는 사회복귀 준비 등을 위하여 특히 필요한 경우에는 처우등급 3급의 군수형자에게도 귀휴를 허가할 수 있다.', 5874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10307, '① 소장은 법 제66조에 따라 귀휴를 허가할 때에는 제90조의 귀휴심사위원회의 심사를 거쳐야 한다.', 5875);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10308, '② 제1항에도 불구하고 소장은 토요일, 공휴일 그 밖의 사유로 귀휴심사위원회의 소집이 곤란할 때에는 귀휴심사위원회 심사를 거치지 아니하고 귀휴를 허가할 수 있다. 다만, 이 경우 다음 각 호에 해당하는 부서의 장의 의견을 들어야 한다.', 5875);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10309, '③ 제2항 각 호에 해당하는 부서의 장은 제97조의 서류를 검토하여 그 의견을 지체 없이 소장에게 보고하여야 한다.', 5875);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10310, null, 5877);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10311, '① 위원회는 위원장 1명을 포함한 5명 이상 7명 이하의 위원으로 구성한다.', 5878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10312, '② 위원회의 위원장은 소장이 되고, 위원회의 위원은 소장이 소속 군교도관과 교정에 관한 학식과 경험이 풍부한 사람 중에서 임명하거나 위촉한다. 이 경우 위촉위원은 2명 이상으로 한다.', 5878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10313, '① 위촉위원의 임기는 2년으로 한다.', 5879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10314, '② 위원장은 위촉위원이 다음 각 호의 어느 하나에 해당하는 경우에는 위촉을 해제할 수 있다.', 5879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10315, '③ 위촉위원에 대해서는 예산의 범위에서 수당과 여비를 지급할 수 있다.', 5879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10316, '① 위원장은 위원회를 대표하고, 위원회의 업무를 총괄한다.', 5880);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10317, '② 위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 위원장이 미리 지명한 위원이 그 직무를 대행한다.', 5880);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10318, '① 위원장은 위원회의 회의를 소집하고, 그 의장이 된다.', 5881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10319, '② 위원회의 회의는 재적위원 과반수의 출석으로 개의(開議)하고, 출석위원 과반수의 찬성으로 의결한다.', 5881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10320, '① 위원회에 위원회의 사무를 처리할 간사 1명을 둔다.', 5882);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10321, '② 간사는 소속 군교도관 중에서 소장이 임명한다.', 5882);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10322, '③ 간사는 별지 제6호서식의 귀휴심사위원회 회의록을 작성하여 보관하여야 한다.', 5882);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10323, '① 귀휴심사에 필요한 서류는 다음 각 호와 같다.', 5883);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10324, '② 소장은 심사대상자에게 별지 제9호서식의 지도보증서를 위원회에 제출하게 하여야 한다. 이 경우 법 제66조제1항제1호부터 제3호까지의 사유에 해당하는 군수형자에 대해서는 별지 제10호서식의 사실확인서를 같이 제출하도록 하여야 한다.', 5883);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10325, '① 소장은 심사대상자의 심사에 필요한 경우에는 군수용자의 가족 등을 면담하거나 군사법원, 군검찰부, 헌병부대 그 밖의 관계 기관이나 단체에 대하여 필요한 사실조회를 할 수 있다.', 5884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10326, '② 소장은 심사대상자의 보호관계 등을 알아보는 데 필요하다고 인정하는 경우에는 그의 가족 또는 보호관계에 있는 사람에게 위원회의 참석을 요청할 수 있다.', 5884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10327, null, 5887);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10328, '① 소장은 법 제66조제3항에 따라 군수형자에게 귀휴를 허가하는 경우 필요하다고 인정하면 군교도관 또는 헌병을 동행시킬 수 있다.', 5888);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10329, '② 소장은 귀휴자를 출발시키기 전에 귀휴자의 가족 또는 보호관계에 있는 사람으로부터 별지 제13호서식의 지도보증서를 제출받아야 한다.', 5888);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10330, '③ 영 제86조제1항에 따라 헌병대 또는 국가경찰관서의 장에게 귀휴사실을 통보하는 경우에는 별지 제14호서식에 따른다.', 5888);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10331, '① 귀휴자의 여비와 귀휴 중 착용할 의류 등은 본인이 부담한다.', 5889);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10332, '② 소장은 귀휴자의 신청이 있는 경우에 작업장려금의 전부 또는 일부를 귀휴비용으로 사용하게 할 수 있다.', 5889);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10333, '① 소장은 귀휴자가 정당한 사유없이 귀휴 기간 만료 시까지 군교도소에 복귀하지 아니한 경우에는 지체없이 귀휴지 및 그 부근 또는 연고지 등 숨을 가능성이 많은 지역의 군부대 및 경찰관서의 장에게 사진 또는 인상 설명서를 첨부하여 그 사실을 통보하여야 한다. <개정 2020.2.3>', 5890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10334, '② 소장은 제1항의 경우 그 사실을 국방부조사본부장에게 보고하여야 한다. 해당 귀휴자를 체포한 경우에도 또한 같다. <개정 2014.11.3>', 5890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10335, '③ 소장은 귀휴자가 제101조에 따른 귀휴지의 제한이나 그 밖에 소장이 지시한 사항을 위반한 사실을 알게 되었을 때에는 지체 없이 귀휴허가를 취소하거나 군교도관으로 하여금 필요한 조치를 하게 하여야 한다.', 5890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10336, '① 소장은 사형확정자의 심리적 안정 및 원만한 수용생활을 위하여 소속 군교도관에게 지속적으로 상담하게 하여야 한다.', 5892);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10337, '② 제1항의 상담책임자는 상담 관련 전문교육을 이수한 군교도관을 우선하여 지정하여야 한다.', 5892);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10338, '③ 제2항에 따라 지정된 상담책임자는 상담대상자에 대하여 월 1회 이상 개별상담을 함으로써 신속한 고충 처리와 원만한 수용생활 지도를 위하여 노력하여야 한다.', 5892);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10339, '④ 제3항에 따라 상담책임자가 상담하였을 때에는 그 요지와 처리결과 등을 별지 제15호서식의 사형확정자 상담결과 보고서에 기록하여 소장에게 보고하여야 한다.', 5892);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10340, '① 소장은 법 제77조제2항에 따라 사형확정자를 혼거수용할 때에는 거실 및 작업장 등의 봉사원, 반장, 조장, 분임장, 그 밖에 군수용자를 대표하는 직책을 부여해서는 아니 된다.', 5893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10341, '② 소장은 법 제77조제3항에 따라 사형확정자가 작업을 신청하는 경우에는 군교도관회의를 거쳐 군교정시설 안에서 하는 작업을 부과할 수 있다. 이 경우 부과하는 작업은 심리적 안정과 원만한 수용생활을 도모하는 데 적합한 것이어야 한다.', 5893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10342, '③ 소장은 제2항에 따라 작업을 부과한 사형확정자에 대하여 군교도관회의를 거쳐 제105조를 적용하지 아니할 수 있다.', 5893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10343, '④ 소장은 제2항에 따라 작업이 부과된 사형확정자가 작업의 취소를 요청하는 경우에는 사형확정자의 의사, 건강, 담당 군교도관의 의견 등을 고려하여 작업을 취소할 수 있다.', 5893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10344, '⑤ 제2항에 따른 사형확정자에 대한 작업부과에 관하여는 법 제61조부터 제65조까지의 규정을 준용한다.', 5893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10345, null, 5896);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10346, '① 소장은 교정장비의 보관 및 관리를 위하여 관리책임자와 보조자를 지정한다.', 5897);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10347, '② 제1항에 따라 지정된 관리책임자와 보조자는 교정장비가 적정상태로 보관ㆍ관리될 수 있도록 수시로 점검하는 등 필요한 조치를 하여야 한다.', 5897);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10348, '③ 특정장소에 고정식으로 설치되는 장비 이외의 교정장비는 별도의 장소에 보관ㆍ관리하여야 한다.', 5897);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10349, null, 5899);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10350, '① 소장은 전자장비의 효율적인 운용을 위하여 각종 전자장비를 통합 관리할 수 있는 시스템이 설치된 중앙통제실을 설치하여 운영하여야 한다.', 5900);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10351, '② 소장은 제1항의 중앙통제실에는 외부인의 출입을 제한하여야 한다. 다만, 시찰ㆍ참관 그 밖에 소장이 특별히 허가한 경우에는 그러하지 아니하다.', 5900);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10352, '③ 전자장비의 통합관리시스템, 중앙통제실의 운영ㆍ관리 등에 관하여 필요한 사항은 국방부장관이 정한다.', 5900);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10353, '① 영상정보처리기기 카메라는 군교정시설의 벽둘레ㆍ감시대ㆍ울타리ㆍ운동장ㆍ거실ㆍ작업장ㆍ접견실ㆍ전화실ㆍ조사실ㆍ진료실ㆍ복도ㆍ통용문 그 밖에 법 제81조제1항에 따라 전자장비를 이용하여 계호하여야 할 필요가 있는 장소에 설치한다. <개정 2020.2.3>', 5901);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10354, '② 영상정보처리기기 모니터는 중앙통제실ㆍ관구실 그 밖에 군교도관이 계호하기에 적정한 장소(이하 "중앙통제실등"이라 한다)에 설치한다.', 5901);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10355, '③ 거실에 영상정보처리기기 카메라를 설치하는 경우에는 용변을 보는 하반신의 모습이 촬영되지 아니하도록 카메라의 각도를 한정하거나 화장실 가림막시설을 설치하여야 한다.', 5901);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10356, '① 군교도관 및 교도병(이하 "군교도관등"이라 한다)이 법 제81조제1항에 따라 거실에 있는 군수용자를 계호하는 경우에는 별지 제16호서식의 거실군수용자 영상계호부에 군교도관과 교도병의 직급ㆍ성명, 계호시간 및 계호대상 등을 기록하여야 한다.', 5902);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10357, '② 군교도관이 법 제81조제1항에 따라 계호하는 과정에서 군수용자의 처우 및 관리에 특히 참고할 사항을 알게 된 경우에는 그 요지를 수용기록부에 기록하여 소장에게 지체 없이 보고하여야 한다.', 5902);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10358, '① 고정식 물품검색기는 정문ㆍ수용동입구ㆍ작업장입구, 그 밖에 군수용자 또는 군교정시설을 출입하는 군수용자 외의 사람(이하 "외부인"이라 한다)의 신체ㆍ의류ㆍ휴대품의 검사가 필요한 장소에 설치한다.', 5905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10359, '② 군교도관등이 법 제80조제1항에 따라 군수용자의 신체ㆍ의류ㆍ휴대품을 검사하는 경우에는 특별한 사정이 없으면 고정식 물품검색기를 통과하게 한 후 휴대식 금속탐지기 또는 손으로 이를 확인한다.', 5905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10360, '③ 군교도관등이 법 제80조제3항에 따라 외부인의 의류와 휴대품을 검사하는 경우에는 고정식 물품검색기를 통과하게 하거나 휴대식 금속탐지기로 이를 확인한다.', 5905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10361, null, 5908);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10362, '① 보호장비의 규격은 별표 3과 같다.', 5909);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10363, '② 군교도관은 제1항에 따른 규격에 맞지 아니한 보호장비를 군수용자에게 사용해서는 아니 된다.', 5909);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10364, '① 수갑의 사용방법은 다음 각 호와 같다.', 5911);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10365, '② 제1항제1호에 따라 수갑을 사용하는 경우에는 수갑보호기를 함께 사용할 수 있다.', 5911);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10366, '③ 제1항제2호에 따라 별표 5의 방법으로 수갑을 사용하여 그 목적을 달성한 후에는 즉시 별표 4의 방법으로 전환하거나 사용을 중지하여야 한다.', 5911);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10367, '④ 수갑은 구체적 상황에 적합한 종류를 선택하여 사용할 수 있다. 다만, 일회용 수갑은 일시적으로 사용하여야 하며, 사용목적을 달성한 후에는 즉시 사용을 중지하거나 다른 보호장비로 교체하여야 한다.', 5911);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10368, null, 5913);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10369, null, 5914);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10370, '① 보호의자의 사용은 별표 12의 방법으로 하며, 다른 보호장비로는 법 제84조제1항제2호부터 제4호까지의 어느 하나에 해당하는 행위를 방지하기 어려운 특별한 사정이 있는 경우에만 사용하여야 한다.', 5915);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10371, '② 보호의자의 사용은 제137조제2항에 따라 그 사용을 일시 해제하거나 완화하는 경우를 포함하여 8시간을 초과할 수 없으며, 해제 후 4시간이 지나지 아니하면 다시 사용할 수 없다.', 5915);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10372, '① 보호침대의 사용은 별표 13의 방법으로 하며, 다른 보호장비로는 자살ㆍ자해를 방지하기 어려운 특별한 사정이 있는 경우에만 사용하여야 한다.', 5916);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10373, '② 보호침대의 사용에 관하여는 제129조제2항을 준용한다.', 5916);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10374, '① 보호복의 사용은 별표 14의 방법으로 한다.', 5917);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10375, '② 보호복의 사용에 관하여는 제129제2항을 준용한다.', 5917);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10376, '① 포승의 사용방법은 다음 각 호와 같다.', 5918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10377, '② 제1항제2호에 따라 포승을 사용하여 2명 이상의 군수용자를 호송하는 경우에는 군수용자 간에 포승을 연결하여 사용할 수 있다.', 5918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10378, '③ 개인포승은 일시적으로 사용하여야 하며, 계속하여 사용할 필요가 있는 경우에는 일반포승으로 교체하여야 한다.', 5918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10379, '① 소장은 보호장비를 착용 중인 군수용자에 대하여 보호장비사용 심사부 및 보호장비착용자 관찰부 등의 기록과 관계직원의 의견 등을 토대로 보호장비의 계속 사용 여부를 매일 심사하여야 한다.', 5922);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10380, '② 소장은 영 제106조에 따라 군의관 또는 의료관계 직원이 보호장비 사용의 중지를 건의하였음에도 불구하고 해당 군수용자에 대하여 보호장비를 계속하여 사용할 필요성이 있다고 판단하는 경우에는 군의관 또는 의료관계 직원에게 건강유지에 필요한 조치를 취할 것을 명하고 보호장비를 계속하여 사용할 수 있다. 이 경우 소장은 보호장비사용 심사부에 보호장비를 계속 사용할 필요가 있다고 판단하는 근거를 기록하여야 한다.', 5922);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10381, '① 군교도관은 법 제84조제1항 각 호에서 정한 보호장비 사용 사유가 소멸한 경우에는 소장의 허가를 받아 지체 없이 사용중인 보호장비를 해제하여야 한다. 다만, 군교도관이 소장의 허가를 받을 시간적 여유가 없을 때에는 보호장비를 해제한 후 지체 없이 소장의 승인을 받아야 한다.', 5923);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10382, '② 군교도관은 보호장비 착용 군수용자의 목욕ㆍ식사ㆍ용변ㆍ치료 등을 위하여 필요한 경우에는 보호장비 사용을 일시 해제하거나 완화할 수 있다.', 5923);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10383, null, 5925);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10384, '① 군교도관등이 군수용자에 대하여 사용할 수 있는 보안장비의 종류별 사용요건은 다음 각 호와 같다.', 5926);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10385, '② 군교도관등이 군수용자 외의 사람에 대하여 사용할 수 있는 보안장비의 종류별 사용요건은 다음 각 호와 같다.', 5926);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10386, '③ 제139조제7호에 해당하는 보안장비의 사용은 국방부장관이 정하는 바에 따른다.', 5926);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10387, null, 5927);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10388, null, 5928);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10389, '① 군교도관등이 군수용자에 대하여 사용할 수 있는 무기의 종류별 사용요건은 다음 각 호와 같다.', 5929);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10390, '② 군교도관등이 군수용자 외의 사람에 대하여 사용할 수 있는 무기의 종류별 사용요건은 다음 각 호와 같다.', 5929);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10391, '③ 제142조제4호에 해당하는 무기의 사용은 국방부장관이 정하는 바에 따른다.', 5929);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10392, '① 소장은 소속 군교도관(현역 군인만 해당한다)에 대하여 연 1회 이상 총기의 조작ㆍ정비ㆍ사용에 관한 교육을 실시한다.', 5932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10393, '② 총기 및 탄약의 정비ㆍ취급 및 사격요령은 각군의 참모총장 또는 국방부조사본부장이 정한다. <개정 2014.11.3>', 5932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10394, '③ 총기 조작훈련을 받지 아니하였거나 그 조작이 미숙한 사람, 그 밖에 총기휴대가 부적당하다고 인정되는 사람에 대해서는 총기의 휴대를 금지하고 별지 제19호서식의 총기휴대 금지자 명부에 그 명단을 기록한 후 총기를 지급할 때마다 대조ㆍ확인하여야 한다.', 5932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10395, '④ 제3항의 총기휴대 금지자에 대하여 금지사유가 소멸한 경우에는 그 사유를 총기휴대금지자명부에 기록하고 총기휴대금지를 해제하여야 한다.', 5932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10396, '① 소장은 법 제92조에 따라 군수용자를 포상할 때에는 제6조에 따른 군교도관회의의 의결을 거쳐야 한다.', 5933);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10397, '② 소장은 군수형자가 법 제92조 각 호의 어느 하나에 해당하면 포상과 함께 제36조에 따른 특별심사를 할 수 있다.', 5933);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10398, null, 5934);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10399, null, 5936);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10400, null, 5937);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10401, null, 5938);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10402, '① 소장은 군수용자의 징벌대상행위에 대한 조사를 시작한 날부터 10일 이내에 다음 각 호의 어느 하나에 해당하는 조치를 하여야 한다. 다만, 특히 필요하다고 인정하는 경우에는 7일을 초과하지 아니하는 범위에서 한 차례만 조사기간을 연장할 수 있다.', 5939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10403, '② 제1항에 따른 조사기간 중 법 제96조제3항에 따라 징벌대상자에 대하여 처우를 제한하는 경우에는 징벌위원회의 의결을 거쳐 그 기간의 전부 또는 일부를 징벌기간에 산입할 수 있다.', 5939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10404, '③ 소장은 징벌대상행위가 징벌대상자의 정신병적인 원인에 따른 것으로 의심할만한 충분한 사유가 있는 경우에는 징벌절차에 우선하여 의사의 진료, 전문가 상담 등 필요한 조치를 하여야 한다.', 5939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10405, '④ 소장은 군의관의 소견과 제3항에 따른 의사의 진료, 전문가 상담 등에서 징벌대상자의 징벌대상행위가 정신병적인 원인에 따른 것이라고 판정된 경우에는 징벌위원회에 징벌을 요구할 수 없다.', 5939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10406, '① 소장은 징벌대상자의 질병이나 그 밖의 특별한 사정으로 조사를 계속하기 어려운 경우에는 조사를 일시적으로 정지할 수 있다.', 5941);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10407, '② 제1항에 따라 정지된 조사기간은 그 사유가 해소된 때부터 다시 진행된다. 이 경우 조사가 정지된 다음 날부터 정지사유가 소멸한 전날까지의 기간은 조사기간에 산입되지 아니 한다.', 5941);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10408, '① 소장은 징벌대상자에 대한 조사가 끝났을 때에는 별지 제20호서식의 징벌의결 요구서를 작성하여 징벌위원회에 징벌 의결을 요구하여야 한다.', 5942);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10409, '② 제1항에 따른 징벌의결 요구서에는 징벌대상행위의 입증에 필요한 관계서류를 첨부할 수 있다.', 5942);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10410, '① 징벌위원회가 제156조에 따른 징벌의결요구서를 접수한 경우에는 지체 없이 징벌대상자에게 별지 제21호서식의 징벌위원회 출석통지서를 전달하여야 한다.', 5943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10411, '② 제1항에 따른 출석통지서에는 다음 각 호의 내용이 포함되어야 한다.', 5943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10412, '③ 제1항에 따라 출석통지서를 전달받은 징벌대상자가 징벌위원회에 출석하는 것을 원하지 아니하는 경우에는 별지 제22호서식의 출석포기서를 징벌위원회에 제출하여야 한다.', 5943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10413, '① 징벌위원회는 출석한 징벌대상자를 심문하고, 필요하다고 인정하는 경우에는 군교도관이나 다른 군수용자 등을 참고인으로 출석시켜 심문할 수 있다.', 5944);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10414, '② 징벌위원회는 징벌대상자에게 제157조제1항에 따른 출석통지서를 전달하였음에도 불구하고 징벌대상자가 출석포기서를 제출하거나 정당한 사유 없이 출석하지 아니한 경우에는 그 사실을 별지 제23호서식의 징벌위원회 회의록에 기록하고 서면심리만으로 징벌을 의결할 수 있다.', 5944);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10415, '③ 징벌의 의결은 별지 제24호서식의 징벌의결서에 따른다.', 5944);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10416, '④ 징벌위원회가 작업장려금의 삭감을 의결하려면 미리 군수용자의 작업장려금을 확인하여야 한다.', 5944);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10417, '⑤ 징벌위원회의 회의에 참여한 사람은 직무상 알게 된 비밀을 누설해서는 아니 된다.', 5944);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10418, '① 금치와 다른 징벌을 함께 집행할 때에는 작업장려금의 삭감과 경고를 제외하고는 금치를 우선하여 집행한다.', 5946);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10419, '② 같은 종류의 징벌은 그 기간이 긴 것부터 집행한다.', 5946);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10420, '③ 금치를 제외한 다른 종류의 징벌은 함께 집행할 수 있다.', 5946);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10421, '① 작업장려금의 삭감은 징벌위원회가 해당 징벌을 의결한 날이 속하는 달의 작업장려금부터 이미 지급된 작업장려금에 대하여 역순(逆順)으로 집행한다.', 5947);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10422, '② 소장은 금치를 집행하는 경우에는 징벌집행을 위하여 따로 지정한 거실(이하 "징벌거실"이라 한다)에 해당 군수용자를 수용하여야 한다.', 5947);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10423, '③ 소장은 금치 외의 징벌을 집행하는 경우에 그 징벌의 목적을 달성하기 위하여 필요하다고 인정하면 해당 군수용자를 징벌거실에 수용할 수 있다.', 5947);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10424, '④ 소장은 징벌 집행을 받고 있거나 집행을 앞둔 군수용자가 같은 행위로 형사법률에 따른 처벌이 확정되어 징벌을 집행할 필요가 없다고 인정하면 징벌 집행을 감경하거나 면제할 수 있다.', 5947);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10425, '① 위원회의 위원은 다음 각 호의 사람 중에서 위원장이 법 제105조제2항에 따라 위촉한 위원으로 구성한다. 이 경우 제1호의 군법무관 3명과 헌병병과 장교 2명이 포함되도록 하되, 특정 군 또는 부대 소속으로만 구성하지 않도록 한다.', 5952);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10426, '② 위원장이 제1항에 따라 위원을 위촉하였을 때에는 그 명단을 국방부조사본부장을 거쳐 국방부장관에게 보고하여야 한다. <개정 2014.11.3>', 5952);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10427, '③ 제2항에 따른 위원 명단은 심사의 공정성과 위원의 신변보호를 위하여 외부에 공개해서는 아니 된다.', 5952);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10428, '① 위원장은 위원회를 대표하고, 위원회의 업무를 총괄한다.', 5954);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10429, '② 위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 위원장이 미리 지정한 위원이 그 직무를 대행한다.', 5954);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10430, '① 위원장은 회의를 소집하고, 그 의장이 된다.', 5955);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10431, '② 위원회의 회의는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.', 5955);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10432, '① 위원회에 위원회의 사무를 처리하기 위하여 간사 1명과 서기 1명을 둔다.', 5956);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10433, '② 간사와 서기는 소속 군교도관 중에서 소장이 임명한다.', 5956);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10434, '③ 간사는 회의에 참석하여 발언할 수 있고, 위원회 결정에 따른 결정서를 작성하여야 한다.', 5956);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10435, '④ 서기는 간사의 업무를 보조한다.', 5956);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10436, '① 간사는 별지 제26호서식의 가석방심사위원회 회의록을 작성ㆍ관리하여야 한다.', 5957);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10437, '② 제1항에 따른 회의록에는 회의의 내용을 기록하고, 위원장 및 간사가 서명ㆍ날인하여야 한다.', 5957);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10438, '① 소장은 「형법」 제72조에 따른 가석방의 요건을 갖춘 군수형자 중 교정성적이 우수하고 뉘우치는 빛이 뚜렷하여 재범의 위험성이 없다고 인정되는 사람을 군교도관회의의 의결을 거쳐 가석방 적격심사 대상자로 선정한다.', 5961);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10439, '② 소장은 형의 집행정지를 받게 될 군수형자가 제1항에 해당할 경우에는 우선적으로 위원회에 가석방의 적격심사를 회부하여야 한다.', 5961);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10440, '③ 소장은 가석방 적격심사에 필요하다고 인정하는 경우에는 군교도관회의에 담당군교도관을 출석시켜 군수형자의 가석방 적격심사에 관한 의견을 들을 수 있다.', 5961);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10441, null, 5962);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10442, '① 신원관계의 조사는 영 제76조제1항에 따라 군수형자로 처우하는 날부터 1개월 이내에 하고, 그 후에는 변경을 요하는 사항을 발견하거나 가석방 적격심사를 위해 필요한 경우에 한다.', 5964);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10443, '② 범죄관계 및 보호관계의 조사는 영 제76조제1항에 따라 군수형자로 처우하는 날부터 2개월 이내에 하여야 한다.', 5964);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10444, '③ 범죄관계의 조사에 필요하다고 인정하는 경우에는 소송기록을 열람할 수 있다.', 5964);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10445, '① 소장은 제175조에 따라 가석방 심사대상자를 선정하였을 때에는 선정한 날부터 5일 이내에 위원회에 가석방 적격심사를 회부하여야 한다.', 5965);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10446, '② 소장은 제1항에 따라 위원회에 가석방 적격심사를 회부할 때에는 별지 제27호서식의 가석방 적격심사 신청서에 별지 제28호서식의 가석방 심사 및 신상조사표를 첨부하여야 한다.', 5965);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10447, '③ 소장은 위원회에 가석방 적격심사를 회부한 사실을 군수형자의 동의를 얻어 보호자 등에게 통지할 수 있다.', 5965);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10448, '① 위원회가 범죄의 동기에 관하여 심사할 때에는 사회 통념상 및 공익상 등 정상을 참작할 만한 사유가 있는지를 심사하여야 한다.', 5967);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10449, '② 범죄의 동기가 군중의 암시 또는 도발, 감독관계에 의한 위협, 그 밖에 이와 유사한 사유에 의한 경우에는 특히 군수형자의 성격 또는 환경의 변화에 유의하고 가석방 후의 환경이 가석방처분을 받은 사람(「보호관찰 등에 관한 법률」에 따른 보호관찰대상자는 제외한다. 이하 "가석방자"라 한다)에게 미칠 영향을 심사하여야 한다.', 5967);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10450, null, 5968);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10451, null, 5969);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10452, '① 재산에 관한 죄를 범한 군수형자에 대해서는 특히 그 범행으로 인하여 발생한 손해의 배상 여부 또는 손해를 줄이기 위한 노력 여부를 심사하여야 한다.', 5970);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10453, '② 군수형자 외의 사람이 피해자의 손해를 배상한 경우에는 그 배상이 군수형자 본인의 희망에 따른 것인지를 심사하여야 한다.', 5970);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10454, '① 위원회는 가석방 적격심사에 필요하다고 인정하는 경우에는 군수형자의 주소지 또는 연고지 등을 관할하는 시ㆍ군ㆍ구ㆍ경찰서, 전(前) 소속부대, 그 밖에 학교ㆍ직업알선기관ㆍ보호단체ㆍ종교단체 등 관계기관에 사실조회를 하거나 관계자의 의견을 들을 수 있다.', 5971);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10455, '② 위원회는 가석방 적격심사를 위하여 필요하다고 인정하는 경우에는 위원이 아닌 군법무관 또는 판사ㆍ검사ㆍ변호사에게 의견을 구하거나 위원회에 참여하게 할 수 있다.', 5971);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10456, '① 위원회는 가석방 적격심사에 필요하다고 인정하는 경우에는 심리학ㆍ정신의학ㆍ사회학 또는 교육학을 전공한 전문가에게 군수형자의 정신상태 등 특정 사항에 대한 감정(鑑定)을 촉탁(囑託)할 수 있다.', 5972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10457, '② 제1항에 따른 촉탁을 받은 사람은 소장의 허가를 받아 군수형자와 접견할 수 있다.', 5972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10458, '① 위원회가 법 제106조제2항에 따라 가석방 적격결정을 하였을 때에는 별지 제29호서식의 가석방 결정서를 작성하여야 한다.', 5974);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10459, '② 법 제107조에 따른 가석방허가의 신청은 별지 제30호서식에 따른다.', 5974);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10460, '① 소장은 가석방자가 제192조에 따른 가석방 취소의 사유가 있음을 알았거나 소속 부대장 또는 관할 경찰서장으로부터 통보를 받았을 때에는 지체 없이 가석방 취소의 심사를 위원회에 회부하여야 한다.', 5979);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10461, '② 제1항에도 불구하고 소장은 위원회를 소집할 수 없거나 긴급한 사유가 있는 때에는 위원회의 심사를 거치지 아니하고 국방부장관에게 가석방 취소를 신청할 수 있다.', 5979);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10462, '③ 위원장은 위원회에서 가석방 취소를 결정하였을 때에는 지체 없이 국방부장관에게 가석방 취소를 신청하여야 한다.', 5979);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10463, '① 위원회가 가석방 취소 여부를 심사하는 경우에는 제192조에 따른 가석방 취소의 사유에 해당하게 된 경위와 그 위반행위가 군과 사회에 미치는 영향, 가석방 기간 동안의 행실의 양호 여부, 직업의 유무 및 종류, 생활상황과 친족관계, 그 밖의 사정을 고려하여야 한다.', 5980);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10464, '② 위원회는 제1항의 심사를 위하여 필요한 경우에는 해당 가석방자를 위원회에 출석시켜 그 진술을 들을 수 있다.', 5980);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10465, '① 소장은 가석방자의 가석방이 취소되었을 때에는 지체 없이 남은 형의 집행에 필요한 조치를 하고, 그 결과를 국방부장관에게 보고하여야 한다.', 5981);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10466, '② 소장은 가석방이 취소된 사람이 군교도소 밖에 있을 때에는 관할 헌병대장 또는 관할 경찰서장에게 가석방이 취소된 사람을 구인(拘引)하도록 의뢰하여야 한다.', 5981);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10467, '③ 제2항에 따라 구인의 의뢰를 받은 헌병대장 또는 경찰서장은 즉시 가석방이 취소된 사람을 구인하여 소장에게 인계하여야 한다.', 5981);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10468, null, 5985);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10469, '① 수용자의 범죄횟수는 징역 또는 금고 이상의 형을 선고받아 확정된 횟수로 한다. 다만, 집행유예의 선고를 받은 사람이 유예기간 중 고의로 범한 죄로 금고 이상의 실형이 확정되지 아니하고 그 기간이 지난 경우에는 집행이 유예된 형은 범죄횟수에 포함하지 아니한다. <개정 2014.11.17>', 5986);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10470, '② 형의 집행을 종료하거나 그 집행이 면제된 날부터 다음 각 호의 기간이 지난 경우에는 범죄횟수에 포함하지 아니한다. 다만, 그 기간 중 자격정지 이상의 형을 선고받아 확정된 경우는 제외한다. <개정 2013.4.16, 2014.11.17>', 5986);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10471, '③ 수용기록부 등 수용자의 범죄횟수를 기록하는 문서에는 필요한 경우 수용횟수(징역 또는 금고 이상의 형을 선고받고 그 집행을 위하여 교정시설에 수용된 횟수를 말한다)를 함께 기록하여 해당 수용자의 처우에 참고할 수 있도록 한다.', 5986);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10472, '① 수용자 의류의 품목은 평상복ㆍ특수복ㆍ보조복ㆍ의복부속물ㆍ모자 및 신발로 한다.', 5987);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10473, '② 제1항에 따른 품목별 구분은 다음 각 호와 같다. <개정 2013.4.16, 2014.11.17>', 5987);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10474, null, 5988);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10475, null, 5990);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10476, '① 수용자에게 지급하는 의류 및 침구는 1명당 1매로 하되, 작업 여부 또는 난방 여건을 고려하여 2매를 지급할 수 있다. <개정 2013.4.16>', 5991);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10477, '② 의류ㆍ침구 외에 수용자에게 지급하는 생활용품의 품목, 지급수량, 사용기간, 지급횟수 등에 대한 기준은 별표 1과 같다.', 5991);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10478, '③ 생활용품 지급일 이후에 수용된 수용자에 대하여는 다음 지급일까지 쓸 적절한 양을 지급하여야 한다.', 5991);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10479, '④ 신입수용자에게는 수용되는 날에 칫솔, 치약 및 수건 등 수용생활에 필요한 최소한의 생활용품을 지급하여야 한다.', 5991);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10480, '① 수용자에게 지급하는 주식은 1명당 1일 390 그램을 기준으로 한다. <개정 2013.4.16, 2014.11.17>', 5994);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10481, '② 소장은 수용자의 나이, 건강, 작업 여부 및 작업의 종류 등을 고려하여 필요한 경우에는 제1항의 지급 기준량을 변경할 수 있다.', 5994);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10482, '③ 소장은 수용자의 기호 등을 고려하여 주식으로 빵이나 국수 등을 지급할 수 있다. <개정 2014.11.17>', 5994);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10483, '① 부식은 주식과 함께 지급하며, 1명당 1일의 영양섭취기준량은 별표 2와 같다.', 5996);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10484, '② 소장은 작업의 장려나 적절한 처우를 위하여 필요하다고 인정하는 경우 특별한 부식을 지급할 수 있다.', 5996);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10485, '① 주ㆍ부식의 지급횟수는 1일 3회로 한다.', 5997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10486, '② 수용자에게 지급하는 음식물의 총열량은 1명당 1일 2천500 킬로칼로리를 기준으로 한다.', 5997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10487, '① 영 제29조에 따른 특식은 예산의 범위에서 지급한다. <개정 2014.11.17>', 5998);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10488, '② 소장은 작업시간을 3시간 이상 연장하는 경우에는 수용자에게 주ㆍ부식 또는 대용식 1회분을 간식으로 지급할 수 있다.', 5998);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10489, '① 자비구매물품의 종류는 다음 각 호와 같다.', 5999);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10490, '② 제1항 각 호에 해당하는 자비구매물품의 품목ㆍ유형 및 규격 등은 영 제31조에 어긋나지 아니하는 범위에서 소장이 정하되, 수용생활에 필요한 정도, 가격과 품질, 다른 교정시설과의 균형, 공급하기 쉬운 정도 및 수용자의 선호도 등을 고려하여야 한다.', 5999);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10491, '③ 법무부장관은 자비구매물품 공급의 교정시설 간 균형 및 교정시설의 안전과 질서유지를 위하여 공급물품의 품목 및 규격 등에 대한 통일된 기준을 제시할 수 있다.', 5999);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10492, '① 소장은 수용자가 자비구매물품의 구매를 신청하는 경우에는 법무부장관이 교정성적 또는 제74조에 따른 경비처우급을 고려하여 정하는 보관금의 사용한도, 교정시설의 보관범위 및 수용자가 지닐 수 있는 범위에서 허가한다. <개정 2013.4.16, 2020.8.5>', 6000);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10493, '② 소장은 감염병(「감염병의 예방 및 관리에 관한 법률」에 따른 감염병을 말한다)의 유행 또는 수용자의 징벌집행 등으로 자비구매물품의 사용이 중지된 경우에는 구매신청을 제한할 수 있다. <개정 2014.11.17>', 6000);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10494, '① 소장은 물품공급업무 담당공무원을 검수관(檢收官)으로 지정하여 제21조에 따라 지정받은 자비구매물품 공급자로부터 납품받은 제품의 수량ㆍ상태 및 소비기한 등을 검사하도록 해야 한다. <개정 2024.2.8>', 6002);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10495, '② 검수관은 공급제품이 부패, 파손, 규격미달, 그 밖의 사유로 수용자에게 공급하기에 부적당하다고 인정하는 경우에는 소장에게 이를 보고하고 필요한 조치를 하여야 한다.', 6002);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10496, '① 소장은 수용자에게 자비구매물품의 품목ㆍ가격, 그 밖에 구매에 관한 주요사항을 미리 알려주어야 한다.', 6003);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10497, '② 소장은 제품의 변질, 파손, 그 밖의 정당한 사유로 수용자가 교환, 반품 또는 수선을 원하는 경우에는 신속히 적절한 조치를 하여야 한다. <개정 2013.4.16>', 6003);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10498, '① 법무부장관은 자비구매물품의 품목ㆍ규격ㆍ가격 등의 교정시설 간 균형을 유지하고 공급과정의 효율성ㆍ공정성을 높이기 위하여 그 공급업무를 담당하는 법인 또는 개인을 지정할 수 있다.', 6004);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10499, '② 제1항에 따라 지정받은 법인 또는 개인은 그 업무를 처리하는 경우 교정시설의 안전과 질서유지를 위하여 선량한 관리자로서의 의무를 다하여야 한다.', 6004);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10500, '③ 자비구매물품 공급업무의 담당자 지정 등에 관한 세부사항은 법무부장관이 정한다.', 6004);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10501, '① 소장은 수용자 외의 사람이 수용자에게 금원(金員)을 건네줄 것을 신청하는 경우에는 현금ㆍ수표 및 우편환의 범위에서 허가한다. 다만, 수용자 외의 사람이 온라인으로 수용자의 예금계좌에 입금한 경우에는 금원을 건네줄 것을 허가한 것으로 본다. <개정 2020.8.5>', 6005);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10502, '② 소장은 수용자 외의 사람이 수용자에게 음식물을 건네줄 것을 신청하는 경우에는 법무부장관이 정하는 바에 따라 교정시설 안에서 판매되는 음식물 중에서 허가한다. 다만, 제30조 각 호에 해당하는 종교행사 및 제114조 각 호에 해당하는 교화프로그램의 시행을 위하여 특히 필요하다고 인정하는 경우에는 교정시설 안에서 판매되는 음식물이 아니더라도 건네줄 것을 허가할 수 있다. <개정 2020.8.5>', 6005);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10503, '③ 소장은 수용자 외의 사람이 수용자에게 음식물 외의 물품을 건네줄 것을 신청하는 경우에는 다음 각 호의 어느 하나에 해당하지 아니하면 법무부장관이 정하는 교정시설의 보관범위 및 수용자가 지닐 수 있는 범위에서 허가한다. <개정 2020.8.5>', 6005);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10504, '① 교정시설에는「의료법」 제3조에 따른 의료기관 중 의원(醫院)이 갖추어야 하는 시설 수준 이상의 의료시설(진료실 등의 의료용 건축물을 말한다. 이하 같다)을 갖추어야 한다.', 6006);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10505, '② 교정시설에 갖추어야 하는 의료장비(혈압측정기 등의 의료기기를 말한다)의 기준은 별표 3과 같다.', 6006);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10506, '③ 의료시설의 세부종류 및 설치기준은 법무부장관이 정한다.', 6006);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10507, '① 소장은 수용정원과 시설여건 등을 고려하여 적정한 양의 비상의료용품을 갖추어 둔다.', 6007);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10508, '② 교정시설에 갖추어야 하는 비상의료용품의 기준은 별표 4와 같다.', 6007);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10509, '① 소장은 전화통화(발신하는 것만을 말한다. 이하 같다)를 신청한 수용자에 대하여 다음 각 호의 어느 하나에 해당하는 사유가 없으면 전화통화를 허가할 수 있다. 다만, 미결수용자에게 전화통화를 허가할 경우 그 허용횟수는 월 2회 이내로 한다. <개정 2020.8.5, 2024.2.8>', 6008);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10510, '② 소장은 제1항에 따른 허가를 하기 전에 전화번호와 수신자(수용자와 통화할 상대방을 말한다. 이하 같다)를 확인하여야 한다. 이 경우 수신자에게 제1항 각 호에 해당하는 사유가 있으면 제1항의 허가를 아니할 수 있다.', 6008);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10511, '③ 전화통화의 통화시간은 특별한 사정이 없으면 5분 이내로 한다. <개정 2024.2.8>', 6008);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10512, '① 수용자의 전화통화는 매일(공휴일 및 법무부장관이 정한 날은 제외한다) 「국가공무원 복무규정」 제9조에 따른 근무시간 내에서 실시한다.', 6009);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10513, '② 소장은 제1항에도 불구하고 평일에 전화를 이용하기 곤란한 특별한 사유가 있는 수용자에 대해서는 전화이용시간을 따로 정할 수 있다.', 6009);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10514, null, 6010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10515, '① 소장은 제25조제1항 각 호의 어느 하나에 해당하지 아니한다고 명백히 인정되는 경우가 아니면 통화내용을 청취하거나 녹음한다.', 6011);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10516, '② 제1항의 녹음기록물은 「공공기록물 관리에 관한 법률」에 따라 관리하고, 특히 녹음기록물이 손상되지 아니하도록 유의해서 보존하여야 한다.', 6011);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10517, '③ 소장은 제1항의 녹음기록물에 대한 보호ㆍ관리를 위해 전화통화정보 취급자를 지정해야 하고, 전화통화정보 취급자는 직무상 알게 된 전화통화정보를 누설 또는 권한 없이 처리하거나 다른 사람이 이용하도록 제공하는 등 부당한 목적으로 사용해서는 안 된다. <개정 2024.2.8>', 6011);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10518, '④ 제1항의 녹음기록물을 관계기관에 제공하는 경우에는 영 제62조제4항 및 제5항을 준용한다. <개정 2024.2.8>', 6011);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10519, '① 수용자의 전화통화 요금은 수용자가 부담한다.', 6012);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10520, '② 소장은 교정성적이 양호한 수형자 또는 보관금이 없는 수용자 등에 대하여는 제1항에도 불구하고 예산의 범위에서 요금을 부담할 수 있다. <개정 2013.4.16, 2020.8.5>', 6012);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10521, '① 영 제59조의2제1항 각 호의 변호사가 수용자를 접견하고자 하는 경우에는 별지 제32호서식의 신청서를 소장에게 제출해야 한다. 다만, 영 제59조의2제1항제1호의 변호사는 소송위임장 사본 등 소송사건의 대리인임을 소명할 수 있는 자료를 첨부해야 한다. <개정 2024.2.8>', 6014);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10522, '② 영 제59조의2제1항 각 호의 변호사가 같은 조 제3항에 따라 접견 시간을 연장하거나 접견 횟수를 추가하고자 하는 경우에는 별지 제33호서식의 신청서에 해당 사유를 소명할 수 있는 자료를 첨부하여 소장에게 제출해야 한다. <개정 2024.2.8>', 6014);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10523, null, 6015);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10524, '① 소장은 교정시설의 안전과 질서를 해치지 아니하는 범위에서 종교단체 또는 종교인이 주재하는 종교행사를 실시한다.', 6016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10525, '② 소장은 종교행사를 위하여 각 종교별 성상ㆍ성물ㆍ성화ㆍ성구가 구비된 종교상담실ㆍ교리교육실 등을 설치할 수 있으며, 특정 종교행사를 위하여 임시행사장을 설치하는 경우에는 성상 등을 임시로 둘 수 있다.', 6016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10526, null, 6017);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10527, '① 소장은 수용자의 신앙생활에 필요하다고 인정하는 경우에는 외부에서 제작된 휴대용 종교도서 및 성물을 수용자가 지니게 할 수 있다. <개정 2020.8.5>', 6019);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10528, '② 소장이 수용자에게 제1항의 종교도서 및 성물을 지니는 것을 허가하는 경우에는 그 재질ㆍ수량ㆍ규격ㆍ형태 등을 고려해야 하며, 다른 수용자의 수용생활을 방해하지 않도록 해야 한다. <개정 2020.8.5>', 6019);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10529, '① 소장은 신문등을 구독하는 수용자가 다음 각 호의 어느 하나에 해당하는 사유가 있으면 구독의 허가를 취소할 수 있다. <개정 2020.8.5>', 6021);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10530, '② 소장은 소유자가 분명하지 아니한 도서를 회수하여 비치도서로 전환하거나 폐기할 수 있다.', 6021);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10531, '① 수용자를 대상으로 하는 방송은 무상으로 한다.', 6022);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10532, '② 법무부장관은 방송의 전문성을 강화하기 위하여 외부전문가의 협력을 구할 수 있고, 모든 교정시설의 수용자를 대상으로 통합방송을 할 수 있다.', 6022);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10533, '③ 소장은 방송에 대한 의견수렴을 위하여 설문조사 등의 방법으로 수용자의 반응도 및 만족도를 측정할 수 있다.', 6022);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10534, '① 소장은 방송을 위하여 텔레비전, 라디오, 스피커 등의 장비와 방송선로 등의 시설을 갖추어야 한다. <개정 2019.10.22>', 6023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10535, '② 소장은 물품관리법령에 따라 제1항의 장비와 시설을 정상적으로 유지ㆍ관리하여야 한다.', 6023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10536, '① 소장은 「방송법」 제2조의 텔레비전방송 또는 라디오방송을 녹음ㆍ녹화하여 방송하거나 생방송할 수 있으며, 비디오테이프에 의한 영상물 또는 자체 제작한 영상물을 방송할 수 있다.', 6025);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10537, '② 방송프로그램은 그 내용에 따라 다음 각 호와 같이 구분한다.', 6025);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10538, '③ 소장은 방송프로그램을 자체 편성하는 경우에는 다음 각 호의 어느 하나에 해당하는 내용이 포함되지 아니하도록 특히 유의하여야 한다.', 6025);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10539, '① 수용자는 소장이 지정한 장소에서 지정된 채널을 통하여 텔레비전을 시청하거나 라디오를 청취하여야 한다. 다만, 제86조에 따른 자치생활 수형자는 법무부장관이 정하는 방법에 따라 텔레비전을 시청할 수 있다. <개정 2013.4.16>', 6026);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10540, '② 수용자는 방송설비 또는 채널을 임의 조작ㆍ변경하거나 임의수신 장비를 지녀서는 안 된다. <개정 2020.8.5>', 6026);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10541, '③ 수용자가 방송시설과 장비를 손상하거나 그 밖의 방법으로 그 효용을 해친 경우에는 배상을 하여야 한다.', 6026);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10542, '① 법 제57조제6항에 따라 법무부장관이 노인수형자의 처우를 전담하도록 정하는 시설(이하 "노인수형자 전담교정시설"이라 한다)에는 「장애인ㆍ노인ㆍ임산부 등의 편의증진보장에 관한 법률 시행령」 별표 2의 교도소ㆍ구치소 편의시설의 종류 및 설치기준에 따른 편의시설을 갖추어야 한다. <개정 2015.12.10>', 6028);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10543, '② 노인수형자 전담교정시설에는 별도의 공동휴게실을 마련하고 노인이 선호하는 오락용품 등을 갖춰두어야 한다.', 6028);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10544, '① 노인수형자 전담교정시설이 아닌 교정시설에서는 노인수용자를 수용하기 위하여 별도의 거실을 지정하여 운용할 수 있다.', 6029);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10545, '② 노인수용자의 거실은 시설부족 또는 그 밖의 부득이한 사정이 없으면 건물의 1층에 설치하고, 특히 겨울철 난방을 위하여 필요한 시설을 갖추어야 한다.', 6029);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10546, '① 소장은 노인수용자의 나이ㆍ건강상태 등을 고려하여 필요하다고 인정하면 영 제49조에 따른 운동시간을 연장하거나 영 제50조에 따른 목욕횟수를 늘릴 수 있다.', 6031);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10547, '② 소장은 노인수용자가 거동이 불편하여 혼자서 목욕하기 어려운 경우에는 교도관, 자원봉사자 또는 다른 수용자로 하여금 목욕을 보조하게 할 수 있다.', 6031);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10548, '① 노인수형자 전담교정시설의 장은 노인성 질환에 관한 전문적인 지식을 가진 의료진과 장비를 갖추고, 외부의료시설과 협력체계를 강화하여 노인수형자가 신속하고 적절한 치료를 받을 수 있도록 노력하여야 한다.', 6032);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10549, '② 소장은 노인수용자에 대하여 6개월에 1회 이상 건강검진을 하여야 한다.', 6032);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10550, '① 노인수형자 전담교정시설의 장은 노인문제에 관한 지식과 경험이 풍부한 외부전문가를 초빙하여 교육하게 하는 등 노인수형자의 교육 받을 기회를 확대하고, 노인전문오락, 그 밖에 노인의 특성에 알맞은 교화프로그램을 개발ㆍ시행하여야 한다.', 6033);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10551, '② 소장은 노인수용자가 작업을 원하는 경우에는 나이ㆍ건강상태 등을 고려하여 해당 수용자가 감당할 수 있는 정도의 작업을 부과한다. 이 경우 의무관의 의견을 들어야 한다.', 6033);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10552, '① 법 제57조제6항에 따라 법무부장관이 장애인수형자의 처우를 전담하도록 정하는 시설(이하 "장애인수형자 전담교정시설"이라 한다)의 장은 장애종류별 특성에 알맞은 재활치료프로그램을 개발하여 시행하여야 한다. <개정 2015.12.10>', 6035);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10553, '② 장애인수형자 전담교정시설 편의시설의 종류 및 설치기준에 관하여는 제43조제1항을 준용한다.', 6035);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10554, '① 장애인수형자 전담교정시설이 아닌 교정시설에서는 장애인수용자를 수용하기 위하여 별도의 거실을 지정하여 운용할 수 있다.', 6036);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10555, '② 장애인수용자의 거실은 시설부족 또는 그 밖의 부득이한 사정이 없으면 건물의 1층에 설치하고, 특히 장애인이 이용할 수 있는 변기 등의 시설을 갖추도록 하여야 한다.', 6036);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10556, '① 외국인수용자를 수용하는 소장은 외국어에 능통한 소속 교도관을 전담요원으로 지정하여 일상적인 개별면담, 고충해소, 통역ㆍ번역 및 외교공관 또는 영사관 등 관계기관과의 연락 등의 업무를 수행하게 하여야 한다.', 6041);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10557, '② 제1항의 전담요원은 외국인 미결수용자에게 소송 진행에 필요한 법률지식을 제공하는 등의 조력을 하여야 한다.', 6041);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10558, '① 소장은 외국인수용자의 수용거실을 지정하는 경우에는 종교 또는 생활관습이 다르거나 민족감정 등으로 인하여 분쟁의 소지가 있는 외국인수용자는 거실을 분리하여 수용하여야 한다. <개정 2013.4.16>', 6042);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10559, '② 소장은 외국인수용자에 대하여는 그 생활양식을 고려하여 필요한 수용설비를 제공하도록 노력하여야 한다.', 6042);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10560, '① 외국인수용자에게 지급하는 음식물의 총열량은 제14조제2항에도 불구하고 소속 국가의 음식문화, 체격 등을 고려하여 조정할 수 있다.', 6043);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10561, '② 외국인수용자에 대하여는 쌀, 빵 또는 그 밖의 식품을 주식으로 지급하되, 소속 국가의 음식문화를 고려하여야 한다. <개정 2014.11.17>', 6043);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10562, '③ 외국인수용자에게 지급하는 부식의 지급기준은 법무부장관이 정한다.', 6043);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10563, '① 법 제57조제6항에 따라 법무부장관이 19세 미만의 수형자(이하 "소년수형자"라 한다)의 처우를 전담하도록 정하는 시설(이하 "소년수형자 전담교정시설"이라 한다)의 장은 소년의 나이ㆍ적성 등 특성에 알맞은 교육ㆍ교화프로그램을 개발하여 시행하여야 한다.', 6045);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10564, '② 소년수형자 전담교정시설에는 별도의 공동학습공간을 마련하고 학용품 및 소년의 정서 함양에 필요한 도서, 잡지 등을 갖춰 두어야 한다.', 6045);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10565, '① 소년수형자 전담교정시설이 아닌 교정시설에서는 소년수용자(영 제81조제4항에 따른 소년수용자를 말한다. 이하 같다)를 수용하기 위하여 별도의 거실을 지정하여 운용할 수 있다.', 6046);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10566, '② 소년수형자 전담교정시설이 아닌 교정시설에서 소년수용자를 수용한 경우 교육ㆍ교화프로그램에 관하여는 제59조의2제1항을 준용한다.', 6046);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10567, '① 소장은 해당 교정시설의 특성 등을 고려하여 필요한 경우에는 다른 교정시설로부터 이송되어 온 수형자의 개별처우계획(법 제56조제1항에 따른 개별처우계획을 말한다. 이하 같다)을 변경할 수 있다.', 6051);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10568, '② 소장은 형집행정지 중에 있는 사람이 기간만료 또는 그 밖의 정지사유가 없어져 재수용된 경우에는 석방 당시와 동일한 처우등급을 부여할 수 있다. <개정 2010.5.31, 2020.8.5>', 6051);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10569, '③ 소장은 형집행정지 중에 있는 사람이 「자유형등에 관한 검찰집행사무규칙」 제33조제2항에 따른 형집행정지의 취소로 재수용된 경우에는 석방 당시보다 한 단계 낮은 처우등급(제74조의 경비처우급에만 해당한다)을 부여할 수 있다. <신설 2024.2.8>', 6051);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10570, '④ 소장은 가석방의 취소로 재수용되어 남은 형기가 집행되는 경우에는 석방 당시보다 한 단계 낮은 처우등급(제74조의 경비처우급에만 해당한다)을 부여한다. 다만, 「가석방자관리규정」 제5조 단서를 위반하여 가석방이 취소되는 등 가석방 취소사유에 특히 고려할 만한 사정이 있는 때에는 석방 당시와 동일한 처우등급을 부여할 수 있다. <개정 2010.5.31, 2022.2.7, 2024.2.8>', 6051);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10571, '⑤ 소장은 형집행정지 중이거나 가석방기간 중에 있는 사람이 형사사건으로 재수용되어 형이 확정된 경우에는 개별처우계획을 새로 수립하여야 한다. <개정 2024.2.8>', 6051);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10572, '① 소장은 「국제수형자이송법」에 따라 외국으로부터 이송되어 온 수형자에 대하여는 개별처우계획을 새로 수립하여 시행한다. 이 경우 해당 국가의 교정기관으로부터 접수된 그 수형자의 수형생활 또는 처우 등에 관한 내용을 고려할 수 있다.', 6052);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10573, '② 소장은 군사법원에서 징역형 또는 금고형이 확정되거나 그 형의 집행 중에 있는 사람이 이송되어 온 경우에는 개별처우계획을 새로 수립하여 시행한다. 이 경우 해당 군교도소로부터 접수된 그 수형자의 수형생활 또는 처우 등에 관한 내용을 고려할 수 있다.', 6052);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10574, '① 다음 각 호의 사람에 대해서는 분류심사를 하지 아니한다. <개정 2013.4.16>', 6053);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10575, '② 소장은 수형자가 다음 각 호의 어느 하나에 해당하는 사유가 있으면 분류심사를 유예한다.', 6053);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10576, '③ 소장은 제2항 각 호에 해당하는 사유가 소멸한 경우에는 지체 없이 분류심사를 하여야 한다. 다만, 집행할 형기가 사유 소멸일부터 3개월 미만인 경우에는 분류심사를 하지 아니한다. <개정 2013.4.16>', 6053);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10577, null, 6054);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10578, null, 6056);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10579, '① 정기재심사는 다음 각 호의 어느 하나에 해당하는 경우에 한다. 다만, 형집행지휘서가 접수된 날부터 6개월이 지나지 아니한 경우에는 그러하지 아니하다.', 6057);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10580, '② 부정기형의 재심사 시기는 단기형을 기준으로 한다.', 6057);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10581, '③ 무기형과 20년을 초과하는 징역형ㆍ금고형의 재심사 시기를 산정하는 경우에는 그 형기를 20년으로 본다.', 6057);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10582, '④ 2개 이상의 징역형 또는 금고형을 집행하는 수형자의 재심사 시기를 산정하는 경우에는 그 형기를 합산한다. 다만, 합산한 형기가 20년을 초과하는 경우에는 그 형기를 20년으로 본다.', 6057);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10583, null, 6058);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10584, '① 소장은 재심사를 할 때에는 그 사유가 발생한 달의 다음 달까지 완료하여야 한다.', 6059);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10585, '② 재심사에 따라 제74조의 경비처우급을 조정할 필요가 있는 경우에는 한 단계의 범위에서 조정한다. 다만, 수용 및 처우를 위하여 특히 필요한 경우에는 두 단계의 범위에서 조정할 수 있다. <개정 2010.5.31>', 6059);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10586, '① 신입심사를 할 때에는 다음 각 호의 사항을 조사한다. <개정 2014.11.17>', 6060);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10587, '② 재심사를 할 때에는 제1항 각 호의 사항 중 변동된 사항과 다음 각 호의 사항을 조사한다. <개정 2014.11.17>', 6060);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10588, null, 6061);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10589, '① 소장은 분류심사를 위하여 수형자의 인성, 지능, 적성 등의 특성을 측정ㆍ진단하기 위한 검사를 할 수 있다.', 6062);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10590, '② 인성검사는 신입심사 대상자 및 그 밖에 처우상 필요한 수형자를 대상으로 한다. 다만, 수형자가 다음 각 호의 어느 하나에 해당하면 인성검사를 하지 아니할 수 있다.', 6062);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10591, '③ 이해력의 현저한 부족 등으로 인하여 인성검사를 하지 아니한 경우에는 상담 내용과 관련 서류를 토대로 인성을 판정하여 경비처우급 분류지표를 결정할 수 있다. <개정 2010.5.31>', 6062);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10592, '④ 지능 및 적성 검사는 제2항 각 호의 어느 하나에 해당하지 아니하는 신입심사 대상자로서 집행할 형기가 형집행지휘서 접수일부터 1년 이상이고 나이가 35세 이하인 경우에 한다. 다만, 직업훈련 또는 그 밖의 처우를 위하여 특히 필요한 경우에는 예외로 할 수 있다.', 6062);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10593, null, 6063);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10594, null, 6064);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10595, '① 경비처우급은 다음 각 호와 같이 구분한다.', 6065);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10596, '② 경비처우급에 따른 작업기준은 다음 각 호와 같다. <개정 2013.4.16>', 6065);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10597, null, 6067);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10598, null, 6068);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10599, '① 소장은 수형자(제62조에 따라 분류심사에서 제외되거나 유예되는 사람은 제외한다)의 소득점수를 별지 제1호서식의 소득점수 평가 및 통지서에 따라 매월 평가하여야 한다. 이 경우 대상기간은 매월 초일부터 말일까지로 한다. <개정 2013.4.16>', 6069);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10600, '② 수형자의 소득점수 평가 방법은 다음 각 호로 구분한다.', 6069);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10601, '③ 제2항에 따라 수형자의 작업 또는 교육 성적을 평가하는 경우에는 작업 숙련도, 기술력, 작업기간, 교육태도, 시험성적 등을 고려할 수 있다.', 6069);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10602, '④ 보안ㆍ작업 담당교도관 및 수용관리팀(교정시설의 효율적인 운영과 수용자의 적정한 관리 및 처우를 위하여 수용동별 또는 작업장별로 나누어진 교정시설 안의 일정한 구역을 관리하는 단위조직을 말한다. 이하 같다)의 팀장은 서로 협의하여 소득점수 평가 및 통지서에 해당 수형자에 대한 매월 초일부터 말일까지의 소득점수를 채점한다. <개정 2013.4.16, 2024.2.8>', 6069);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10603, '① 수형생활 태도 점수와 작업 또는 교육성적 점수는 제78조제2항의 방법에 따라 채점하되, 수는 소속 작업장 또는 교육장 전체 인원의 10퍼센트를 초과할 수 없고, 우는 30퍼센트를 초과할 수 없다. 다만, 작업장 또는 교육장 전체인원이 4명 이하인 경우에는 수ㆍ우를 각각 1명으로 채점할 수 있다.', 6070);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10604, '② 소장이 작업장 중 작업의 특성이나 난이도 등을 고려하여 필수 작업장으로 지정하는 경우 소득점수의 수는 5퍼센트 이내, 우는 10퍼센트 이내의 범위에서 각각 확대할 수 있다.', 6070);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10605, '③ 소장은 수형자가 부상이나 질병, 그 밖의 부득이한 사유로 작업 또는 교육을 받지 못한 경우에는 3점 이내의 범위에서 작업 또는 교육 성적을 부여할 수 있다.', 6070);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10606, '① 소장은 제66조 및 제67조에 따라 재심사를 하는 경우에는 그 때마다 제78조에 따라 평가한 수형자의 소득점수를 평정하여 경비처우급을 조정할 것인지를 고려하여야 한다. 다만, 부정기재심사의 소득점수 평정대상기간은 사유가 발생한 달까지로 한다. <개정 2010.5.31>', 6071);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10607, '② 제1항에 따라 소득점수를 평정하는 경우에는 평정 대상기간 동안 매월 평가된 소득점수를 합산하여 평정 대상기간의 개월 수로 나누어 얻은 점수(이하 "평정소득점수"라 한다)로 한다.', 6071);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10608, null, 6072);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10609, '① 조정된 처우등급에 따른 처우는 그 조정이 확정된 다음 날부터 한다. 이 경우 조정된 처우등급은 그 달 초일부터 적용된 것으로 본다. <개정 2010.5.31>', 6073);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10610, '② 소장은 수형자의 경비처우급을 조정한 경우에는 지체 없이 해당 수형자에게 그 사항을 알려야 한다. <개정 2010.5.31>', 6073);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10611, '① 소장은 수형자를 기본수용급별ㆍ경비처우급별로 구분하여 수용하여야 한다. 다만 처우상 특히 필요하거나 시설의 여건상 부득이한 경우에는 기본수용급ㆍ경비처우급이 다른 수형자를 함께 수용하여 처우할 수 있다. <개정 2010.5.31>', 6074);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10612, '② 소장은 제1항에 따라 수형자를 수용하는 경우 개별처우의 효과를 증진하기 위하여 경비처우급ㆍ개별처우급이 같은 수형자 집단으로 수용하여 처우할 수 있다. <개정 2010.5.31>', 6074);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10613, '① 소장은 수형자의 경비처우급에 따라 물품에 차이를 두어 지급할 수 있다. 다만, 주ㆍ부식, 음료, 그 밖에 건강유지에 필요한 물품은 그러하지 아니하다. <개정 2010.5.31>', 6075);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10614, '② 제1항에 따라 의류를 지급하는 경우 수형자가 개방처우급인 경우에는 색상, 디자인 등을 다르게 할 수 있다. <개정 2010.5.31>', 6075);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10615, '① 소장은 개방처우급ㆍ완화경비처우급ㆍ일반경비처우급 수형자로서 교정성적, 나이, 인성 등을 고려하여 다른 수형자의 모범이 된다고 인정되는 경우에는 봉사원으로 선정하여 담당교도관의 사무처리와 그 밖의 업무를 보조하게 할 수 있다. <개정 2010.5.31>', 6076);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10616, '② 소장은 봉사원의 활동기간을 1년 이하로 정하되, 필요한 경우에는 그 기간을 연장할 수 있다. <개정 2010.5.31, 2014.11.17>', 6076);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10617, '③ 소장은 봉사원의 활동과 역할 수행이 부적당하다고 인정하는 경우에는 그 선정을 취소할 수 있다.', 6076);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10618, '④ 제1항부터 제3항까지에서 규정한 사항 외에 봉사원 선정, 기간연장 및 선정취소 등에 필요한 사항은 법무부장관이 정한다. <개정 2024.2.8>', 6076);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10619, '① 소장은 개방처우급ㆍ완화경비처우급 수형자에게 자치생활을 허가할 수 있다. <개정 2010.5.31>', 6077);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10620, '② 수형자 자치생활의 범위는 인원점검, 취미활동, 일정한 구역 안에서의 생활 등으로 한다.', 6077);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10621, '③ 소장은 자치생활 수형자들이 교육실, 강당 등 적당한 장소에서 월 1회 이상 토론회를 할 수 있도록 하여야 한다.', 6077);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10622, '④ 소장은 자치생활 수형자가 법무부장관 또는 소장이 정하는 자치생활 중 지켜야 할 사항을 위반한 경우에는 자치생활 허가를 취소할 수 있다. <개정 2020.8.5>', 6077);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10623, '①수형자의 경비처우급별 접견의 허용횟수는 다음 각 호와 같다. <개정 2010.5.31, 2013.4.16>', 6078);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10624, '② 제1항제2호부터 제4호까지의 경우 접견은 1일 1회만 허용한다. 다만, 처우상 특히 필요한 경우에는 그러하지 아니하다. <신설 2013.4.16>', 6078);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10625, '③ 소장은 교화 및 처우상 특히 필요한 경우에는 수용자가 다른 교정시설의 수용자와 통신망을 이용하여 화상으로 접견하는 것(이하 "화상접견"이라 한다)을 허가할 수 있다. 이 경우 화상접견은 제1항의 접견 허용횟수에 포함한다. <신설 2013.4.16>', 6078);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10626, '① 소장은 개방처우급ㆍ완화경비처우급 수형자에 대하여 가족 만남의 날 행사에 참여하게 하거나 가족 만남의 집을 이용하게 할 수 있다. 이 경우 제87조의 접견 허용횟수에는 포함되지 아니한다. <개정 2010.5.31>', 6080);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10627, '② 제1항의 경우 소장은 가족이 없는 수형자에 대하여는 결연을 맺었거나 그 밖에 가족에 준하는 사람으로 하여금 그 가족을 대신하게 할 수 있다.', 6080);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10628, '③ 소장은 제1항에도 불구하고 교화를 위하여 특히 필요한 경우에는 일반경비처우급 수형자에 대하여도 가족 만남의 날 행사 참여 또는 가족 만남의 집 이용을 허가할 수 있다. <개정 2010.5.31>', 6080);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10629, '④ 제1항 및 제3항에서 "가족 만남의 날 행사"란 수형자와 그 가족이 교정시설의 일정한 장소에서 다과와 음식을 함께 나누면서 대화의 시간을 갖는 행사를 말하며, "가족 만남의 집"이란 수형자와 그 가족이 숙식을 함께 할 수 있도록 교정시설에 수용동과 별도로 설치된 일반주택 형태의 건축물을 말한다. <개정 2013.4.16>', 6080);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10630, '① 수형자의 경비처우급별 전화통화의 허용횟수는 다음 각 호와 같다. <개정 2010.5.31, 2014.11.17, 2024.2.8>', 6081);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10631, '② 소장은 제1항에도 불구하고 처우상 특히 필요한 경우에는 개방처우급ㆍ완화경비처우급ㆍ일반경비처우급 수형자의 전화통화 허용횟수를 늘릴 수 있다. <개정 2010.5.31, 2024.2.8>', 6081);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10632, '③ 제1항 각 호의 경우 전화통화는 1일 1회만 허용한다. 다만, 처우상 특히 필요한 경우에는 그러하지 아니하다. <신설 2013.4.16>', 6081);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10633, '① 소장은 개방처우급ㆍ완화경비처우급 또는 자치생활 수형자에 대하여 월 2회 이내에서 경기 또는 오락회를 개최하게 할 수 있다. 다만, 소년수형자에 대하여는 그 횟수를 늘릴 수 있다. <개정 2010.5.31>', 6082);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10634, '② 제1항에 따라 경기 또는 오락회가 개최되는 경우 소장은 해당 시설의 사정을 고려하여 참석인원, 방법 등을 정할 수 있다.', 6082);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10635, '③ 제1항에 따라 경기 또는 오락회가 개최되는 경우 소장은 관련 분야의 전문지식과 자격을 가지고 있는 외부강사를 초빙할 수 있다.', 6082);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10636, '① 소장은 개방처우급ㆍ완화경비처우급 수형자에 대하여 교정시설 밖에서 이루어지는 다음 각 호에 해당하는 활동을 허가할 수 있다. 다만, 처우상 특히 필요한 경우에는 일반경비처우급 수형자에게도 이를 허가할 수 있다. <개정 2010.5.31>', 6083);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10637, '② 제1항 각 호의 활동을 허가하는 경우 소장은 별도의 수형자 의류를 지정하여 입게 한다. 다만, 처우상 필요한 경우에는 자비구매의류를 입게 할 수 있다.', 6083);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10638, '③ 제1항제4호의 활동에 필요한 비용은 수형자가 부담한다. 다만, 처우상 필요한 경우에는 예산의 범위에서 그 비용을 지원할 수 있다.', 6083);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10639, '① 소장은 개방처우급 혹은 완화경비처우급 수형자가 다음 각 호의 사유에 모두 해당하는 경우에는 교정시설에 설치된 개방시설에 수용하여 사회 적응에 필요한 교육, 취업지원 등 적정한 처우를 할 수 있다. <개정 2024.2.8>', 6084);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10640, '② 소장은 제1항에 따른 처우의 대상자 중 다음 각 호의 사유에 모두 해당하는 수형자에 대해서는 지역사회에 설치된 개방시설에 수용하여 제1항에 따른 처우를 할 수 있다. <개정 2024.2.8>', 6084);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10641, '③ 제1항 및 제2항에 따른 중간처우 대상자의 선발절차, 교정시설 또는 지역사회에 설치하는 개방시설의 종류 및 기준, 그 밖에 필요한 사항은 법무부장관이 정한다. <개정 2024.2.8>', 6084);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10642, '① 소장은 수형자가 개방처우급 또는 완화경비처우급으로서 작업기술이 탁월하고 작업성적이 우수한 경우에는 수형자 자신을 위한 개인작업을 하게 할 수 있다. 이 경우 개인작업 시간은 교도작업에 지장을 주지 아니하는 범위에서 1일 2시간 이내로 한다. <개정 2010.5.31>', 6086);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10643, '② 소장은 제1항에 따라 개인작업을 하는 수형자에게 개인작업 용구를 사용하게 할 수 있다. 이 경우 작업용구는 특정한 용기에 보관하도록 하여야 한다.', 6086);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10644, '③ 제1항의 개인작업에 필요한 작업재료 등의 구입비용은 수형자가 부담한다. 다만, 처우상 필요한 경우에는 예산의 범위에서 그 비용을 지원할 수 있다.', 6086);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10645, '① 소장은 수형자가 개방처우급 또는 완화경비처우급으로서 직업능력 향상을 위하여 특히 필요한 경우에는 교정시설 외부의 공공기관 또는 기업체 등에서 운영하는 직업훈련을 받게 할 수 있다. <개정 2010.5.31>', 6087);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10646, '② 제1항에 따른 직업훈련의 비용은 수형자가 부담한다. 다만, 처우상 특히 필요한 경우에는 예산의 범위에서 그 비용을 지원할 수 있다.', 6087);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10647, '① 법 제61조 및 영 제86조에 따른 분류심사를 전담하는 교정시설(이하 이 절에서 "분류전담시설"이라 한다)의 장은 범죄의 피해가 중대하고 재범의 위험성이 높은 수형자(이하 이 절에서 "고위험군 수형자"라 한다)의 개별처우계획을 수립ㆍ조정하기 위해 고위험군 수형자의 개별적 특성과 재범의 위험성 등을 면밀히 분석ㆍ평가하기 위한 분류심사(이하 이 절에서 "정밀분류심사"라 한다)를 실시할 수 있다.', 6088);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10648, '② 분류전담시설의 장은 정밀분류심사를 실시한 고위험군 수형자의 개별처우계획 이행 여부를 지속적으로 평가해야 한다.', 6088);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10649, null, 6089);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10650, '① 위원장은 위원회를 소집하고 위원회의 사무를 총괄한다.', 6090);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10651, '② 위원장이 부득이한 사유로 그 직무를 수행할 수 없을 때에는 위원장이 미리 지정한 위원이 그 직무를 대행할 수 있다.', 6090);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10652, '① 위원회의 회의는 매월 10일에 개최한다. 다만, 위원회의 회의를 개최하는 날이 토요일, 공휴일, 그 밖에 법무부장관이 정한 휴무일일 때에는 그 다음 날에 개최한다.', 6091);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10653, '② 위원장은 수형자의 처우와 관련하여 필요한 경우에는 임시회의를 개최할 수 있다. <개정 2019.8.29>', 6091);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10654, '③ 위원회의 회의는 재적위원 3분의 2이상의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.', 6091);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10655, '① 위원회의 사무를 처리하기 위하여 분류심사 업무를 담당하는 교도관 중에서 간사 1명을 둔다.', 6092);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10656, '② 간사는 위원회의 회의록을 작성하여 유지하여야 한다.', 6092);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10657, '① 소장은 교육대상자를 소속기관(소장이 관할하고 있는 교정시설을 말한다. 이하 같다)에서 선발하여 교육한다. 다만, 소속기관에서 교육대상자를 선발하기 어려운 경우에는 다른 기관에서 추천한 사람을 모집하여 교육할 수 있다.', 6094);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10658, '② 소장은 교육대상자의 성적불량, 학업태만 등으로 인하여 교육의 목적을 달성하기 어려운 경우에는 그 선발을 취소할 수 있다.', 6094);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10659, '③ 소장은 교육대상자 및 시험응시 희망자의 학습능력을 평가하기 위하여 자체 평가시험을 실시할 수 있다.', 6094);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10660, '④ 소장은 교육의 효과를 거두지 못하였다고 인정하는 교육대상자에 대하여 다시 교육을 할 수 있다.', 6094);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10661, '⑤ 소장은 기관의 교육전문인력, 교육시설, 교육대상인원 등의 사정을 고려하여 단계별 교육과 자격취득 목표를 설정할 수 있으며, 자격취득ㆍ대회입상 등을 하면 처우에 반영할 수 있다.', 6094);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10662, '① 교육대상자는 교육의 시행에 관한 관계법령, 학칙 및 교육관리지침을 성실히 지켜야 한다. <개정 2020.8.5>', 6095);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10663, '② 제110조부터 제113조까지의 규정에 따른 교육을 실시하는 경우 소요되는 비용은 특별한 사정이 없으면 교육대상자의 부담으로 한다.', 6095);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10664, '', 6095);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10665, '① 소장은 각 교육과정의 선정 요건과 수형자의 나이, 학력, 교정성적, 자체 평가시험 성적, 정신자세, 성실성, 교육계획과 시설의 규모, 교육대상인원 등을 고려하여 교육대상자를 선발하거나 추천하여야 한다.', 6096);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10666, '② 소장은 정당한 이유 없이 교육을 기피한 사실이 있거나 자퇴(제적을 포함한다)한 사실이 있는 수형자는 교육대상자로 선발하거나 추천하지 아니할 수 있다.', 6096);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10667, '① 학과교육대상자의 과정수료 단위는 학년으로 하되, 학기의 구분은 국공립학교의 학기에 준한다. 다만, 독학에 의한 교육은 수업 일수의 제한을 받지 아니한다.', 6097);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10668, '② 소장은 교육을 위하여 필요한 경우에는 외부강사를 초빙할 수 있으며, 카세트 또는 재생전용기기의 사용을 허용할 수 있다.', 6097);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10669, '③ 소장은 교육의 실효성을 확보하기 위하여 교육실을 설치ㆍ관리하여야 하며, 교육목적을 위하여 필요한 경우 신체장애를 보완하는 교육용 물품의 사용을 허가하거나 예산의 범위에서 학용품과 응시료를 지원할 수 있다.', 6097);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10670, '① 소장은 교육대상자가 다음 각 호의 어느 하나에 해당하는 경우에는 교육대상자 선발을 취소할 수 있다. <개정 2017.8.22>', 6098);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10671, '② 교육과정의 변경은 교육대상자의 선발로 보아 제103조를 준용한다.', 6098);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10672, '③ 소장은 교육대상자에게 질병, 부상, 그 밖의 부득이한 사정이 있는 경우에는 교육과정을 일시 중지할 수 있다.', 6098);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10673, '① 소장은 특별한 사유가 없으면 교육기간 동안에 교육대상자를 다른 기관으로 이송할 수 없다.', 6099);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10674, '② 교육대상자의 선발이 취소되거나 교육대상자가 교육을 수료하였을 때에는 선발 당시 소속기관으로 이송한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 소속기관으로 이송하지 아니하거나 다른 기관으로 이송할 수 있다.', 6099);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10675, '① 교육대상자에게는 작업ㆍ직업훈련 등을 면제한다.', 6100);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10676, '② 작업ㆍ직업훈련 수형자 등도 독학으로 검정고시ㆍ학사고시 등에 응시하게 할 수 있다. 이 경우 자체 평가시험 성적 등을 고려해야 한다. <개정 2019.10.22>', 6100);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10677, '① 소장은 매년 초 다음 각 호의 시험을 준비하는 수형자를 대상으로 검정고시반을 설치ㆍ운영할 수 있다. <개정 2016.6.28>', 6101);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10678, '② 소장은 교육기간 중에 검정고시에 합격한 교육대상자에 대하여는 해당 교육과정을 조기 수료시키거나 상위 교육과정에 임시 편성시킬 수 있다.', 6101);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10679, '③ 소장은 고등학교 졸업 또는 이와 동등한 수준 이상의 학력이 인정되는 수형자를 대상으로 대학입학시험 준비반을 편성ㆍ운영할 수 있다.', 6101);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10680, '① 소장은 수형자에게 고등학교 과정의 교육기회를 부여하기 위하여 「초ㆍ중등교육법」 제51조에 따른 방송통신고등학교 교육과정을 설치ㆍ운영할 수 있다.', 6102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10681, '② 소장은 중학교 졸업 또는 이와 동등한 수준 이상의 학력이 인정되는 수형자가 제1항의 방송통신고등학교 교육과정을 지원하여 합격한 경우에는 교육대상자로 선발할 수 있다.', 6102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10682, '③ 소장은 제1항의 방송통신고등학교 교육과정의 입학금, 수업료, 교과용 도서 구입비 등 교육에 필요한 비용을 예산의 범위에서 지원할 수 있다.', 6102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10683, '① 소장은 수형자에게 학위취득 기회를 부여하기 위하여 독학에 의한 학사학위 취득과정(이하 "학사고시반 교육"이라 한다)을 설치ㆍ운영할 수 있다.', 6103);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10684, '② 소장은 다음 각 호의 요건을 갖춘 수형자가 제1항의 학사고시반 교육을 신청하는 경우에는 교육대상자로 선발할 수 있다. <개정 2013.4.16>', 6103);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10685, '① 소장은 대학 과정의 교육기회를 부여하기 위하여 「고등교육법」 제2조에 따른 방송통신대학 교육과정을 설치ㆍ운영할 수 있다.', 6104);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10686, '② 소장은 제110조제2항 각 호의 요건을 갖춘 개방처우급ㆍ완화경비처우급ㆍ일반경비처우급 수형자가 제1항의 방송통신대학 교육과정에 지원하여 합격한 경우에는 교육대상자로 선발할 수 있다. <개정 2010.5.31>', 6104);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10687, '① 소장은 전문대학과정의 교육기회를 부여하기 위하여 「고등교육법」 제2조에 따른 전문대학 위탁교육과정을 설치ㆍ운영할 수 있다.', 6105);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10688, '② 소장은 제110조제2항 각 호의 요건을 갖춘 개방처우급ㆍ완화경비처우급ㆍ일반경비처우급 수형자가 제1항의 전문대학 위탁교육과정에 지원하여 합격한 경우에는 교육대상자로 선발할 수 있다. <개정 2010.5.31>', 6105);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10689, '③ 제1항의 전문대학 위탁교육과정의 교과과정, 시험응시 및 학위취득에 관한 세부사항은 위탁자와 수탁자 간의 협약에 따른다.', 6105);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10690, '④ 소장은 제1항부터 제3항까지의 규정에 따른 교육을 위하여 필요한 경우 수형자를 중간처우를 위한 전담교정시설에 수용할 수 있다. <신설 2015.12.10>', 6105);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10691, '① 소장은 수형자에게 지식정보사회에 적응할 수 있는 교육기회를 부여하기 위하여 정보화 교육과정을 설치ㆍ운영할 수 있다.', 6106);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10692, '② 소장은 개방처우급ㆍ완화경비처우급ㆍ일반경비처우급 수형자에게 다문화 시대에 대처할 수 있는 교육기회를 부여하기 위하여 외국어 교육과정을 설치ㆍ운영할 수 있다. <개정 2010.5.31>', 6106);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10693, '③ 소장은 외국어 교육대상자가 교육실 외에서의 어학학습장비를 이용한 외국어학습을 원하는 경우에는 계호 수준, 독거 여부, 교육 정도 등에 대한 교도관회의(「교도관 직무규칙」 제21조에 따른 교도관회의를 말한다. 이하 같다)의 심의를 거쳐 허가할 수 있다.', 6106);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10694, '④ 소장은 이 규칙에서 정한 교육과정 외에도 법무부장관이 수형자로 하여금 건전한 사회복귀에 필요한 지식과 소양을 습득하게 하기 위하여 정하는 교육과정을 설치ㆍ운영할 수 있다.', 6106);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10695, null, 6107);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10696, '① 소장은 수형자와 그 가족의 관계를 유지ㆍ회복하기 위하여 수형자의 가족이 참여하는 각종 프로그램을 운영할 수 있다. 다만, 가족이 없는 수형자의 경우 교화를 위하여 필요하면 결연을 맺었거나 그 밖에 가족에 준하는 사람의 참여를 허가할 수 있다.', 6110);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10697, '② 제1항의 경우 대상 수형자는 교도관회의의 심의를 거쳐 선발하고, 참여인원은 5명 이내의 가족으로 한다. 다만, 특히 필요하다고 인정하는 경우에는 참여인원을 늘릴 수 있다. <개정 2017.8.22>', 6110);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10698, '① 소장은 수형자의 건전한 가치관 형성, 정서안정, 고충해소 등을 위하여 교화상담을 실시할 수 있다.', 6111);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10699, '② 소장은 제1항의 교화상담을 위하여 교도관이나 제33조의 교정참여인사를 교화상담자로 지정할 수 있으며, 수형자의 안정을 위하여 결연을 주선할 수 있다.', 6111);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10700, '① 소장은 교화프로그램을 운영하는 경우 약물중독ㆍ정신질환ㆍ신체장애ㆍ건강ㆍ성별ㆍ나이 등 수형자의 개별 특성을 고려하여야 하며, 프로그램의 성격 및 시설 규모와 인원을 고려하여 이송 등의 적절한 조치를 할 수 있다.', 6112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10701, '② 소장은 교화프로그램을 운영하기 위하여 수형자의 정서적인 안정이 보장될 수 있는 장소를 따로 정하거나 방송설비 및 방송기기를 이용할 수 있다.', 6112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10702, '③ 소장은 교정정보시스템(교정시설에서 통합적으로 정보를 관리하는 시스템을 말한다)에 교화프로그램의 주요 진행내용을 기록하여 수형자 처우에 활용하여야 하며, 상담내용 등 개인정보가 유출되지 아니하도록 하여야 한다.', 6112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10703, '④ 교화프로그램 운영에 관하여는 제101조부터 제107조까지의 규정을 준용한다.', 6112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10704, '① 법무부장관은 교화프로그램의 효과를 높이기 위해 소속 공무원 중에서 법 제64조제2항에 따른 전문인력을 선발 및 양성할 수 있다.', 6113);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10705, '② 제1항에 따른 전문인력 선발 및 양성의 요건, 방법, 그 밖에 필요한 사항은 법무부장관이 정한다.', 6113);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10706, '① 외부기업체에 통근하며 작업하는 수형자는 다음 각 호의 요건을 갖춘 수형자 중에서 선정한다. <개정 2010.5.31, 2013.4.16, 2014.11.17, 2020.8.5>', 6114);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10707, '② 교정시설 안에 설치된 외부기업체의 작업장에 통근하며 작업하는 수형자는 제1항제1호부터 제4호까지의 요건(같은 항 제3호의 요건의 경우에는 일반경비처우급에 해당하는 수형자도 포함한다)을 갖춘 수형자로서 집행할 형기가 10년 미만이거나 형기기산일부터 10년 이상이 지난 수형자 중에서 선정한다. <신설 2013.4.16, 2014.11.17>', 6114);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10708, '③ 소장은 제1항 및 제2항에도 불구하고 작업 부과 또는 교화를 위하여 특히 필요하다고 인정하는 경우에는 제1항 및 제2항의 수형자 외의 수형자에 대하여도 외부통근자로 선정할 수 있다. <개정 2013.4.16>', 6114);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10709, '① 직업훈련 직종 선정 및 훈련과정별 인원은 법무부장관의 승인을 받아 소장이 정한다.', 6118);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10710, '② 직업훈련 대상자는 소속기관의 수형자 중에서 소장이 선정한다. 다만, 집체직업훈련(직업훈련 전담 교정시설이나 그 밖에 직업훈련을 실시하기에 적합한 교정시설에 수용하여 실시하는 훈련을 말한다) 대상자는 집체직업훈련을 실시하는 교정시설의 관할 지방교정청장이 선정한다. <개정 2010.5.31, 2013.4.16>', 6118);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10711, '①소장은 수형자가 다음 각 호의 요건을 갖춘 경우에는 수형자의 의사, 적성, 나이, 학력 등을 고려하여 직업훈련 대상자로 선정할 수 있다. <개정 2013.4.16>', 6119);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10712, '② 소장은 소년수형자의 선도(善導)를 위하여 필요한 경우에는 제1항의 요건을 갖추지 못한 경우에도 직업훈련 대상자로 선정하여 교육할 수 있다. <신설 2013.4.16>', 6119);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10713, null, 6120);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10714, '① 법무부장관은 직업훈련을 위하여 필요한 경우에는 수형자를 다른 교정시설로 이송할 수 있다.', 6121);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10715, '② 소장은 제1항에 따라 이송된 수형자나 직업훈련 중인 수형자를 다른 교정시설로 이송해서는 아니 된다. 다만, 훈련취소 등 특별한 사유가 있는 경우에는 그러하지 아니하다.', 6121);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10716, '① 소장은 직업훈련 대상자가 다음 각 호의 어느 하나에 해당하는 경우에는 직업훈련을 보류할 수 있다.', 6122);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10717, '② 소장은 제1항에 따라 직업훈련이 보류된 수형자가 그 사유가 소멸되면 본래의 과정에 복귀시켜 훈련하여야 한다. 다만, 본래 과정으로 복귀하는 것이 부적당하다고 인정하는 경우에는 해당 훈련을 취소할 수 있다.', 6122);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10718, '① 소장은 법 제77조에 따른 귀휴를 허가하는 경우에는 제131조의 귀휴심사위원회의 심사를 거쳐야 한다.', 6123);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10719, '② 소장은 개방처우급ㆍ완화경비처우급 수형자에게 법 제77조제1항에 따른 귀휴를 허가할 수 있다. 다만, 교화 또는 사회복귀 준비 등을 위하여 특히 필요한 경우에는 일반경비처우급 수형자에게도 이를 허가할 수 있다. <개정 2010.5.31>', 6123);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10720, '③ 법 제77조제1항제4호에 해당하는 귀휴사유는 다음 각 호와 같다. <개정 2013.4.16, 2014.11.17>', 6123);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10721, '① 법 제77조제1항의 형기를 계산할 때 부정기형은 단기를 기준으로 하고, 2개 이상의 징역 또는 금고의 형을 선고받은 수형자의 경우에는 그 형기를 합산한다. <개정 2014.11.17>', 6124);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10722, '② 법 제77조제1항의 "1년 중 20일 이내의 귀휴" 중 "1년"이란 매년 1월 1일부터 12월 31일까지를 말한다.', 6124);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10723, '① 법 제77조에 따른 수형자의 귀휴허가에 관한 심사를 하기 위하여 교정시설에 귀휴심사위원회(이하 이 절에서 "위원회"라 한다)를 둔다.', 6125);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10724, '② 위원회는 위원장을 포함한 6명 이상 8명 이하의 위원으로 구성한다.', 6125);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10725, '③ 위원장은 소장이 되며, 위원은 소장이 소속기관의 부소장ㆍ과장(지소의 경우에는 7급 이상의 교도관) 및 교정에 관한 학식과 경험이 풍부한 외부인사 중에서 임명 또는 위촉한다. 이 경우 외부위원은 2명 이상으로 한다.', 6125);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10726, '① 위원장은 위원회를 소집하고 위원회의 업무를 총괄한다.', 6126);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10727, '② 위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 부소장인 위원이 그 직무를 대행하고, 부소장이 없거나 부소장인 위원이 사고가 있는 경우에는 위원장이 미리 지정한 위원이 그 직무를 대행한다.', 6126);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10728, '① 위원회의 회의는 위원장이 수형자에게 법 제77조제1항 및 제2항에 따른 귀휴사유가 발생하여 귀휴심사가 필요하다고 인정하는 때에 개최한다.', 6127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10729, '② 위원회의 회의는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.', 6127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10730, '① 소장은 토요일, 공휴일, 그 밖에 위원회의 소집이 매우 곤란한 때에 법 제77조제2항제1호의 사유가 발생한 경우에는 제129조제1항에도 불구하고 위원회의 심사를 거치지 아니하고 귀휴를 허가할 수 있다. 다만, 이 경우 다음 각 호에 해당하는 부서의 장의 의견을 들어야 한다.', 6128);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10731, '② 제1항 각 호에 해당하는 부서의 장은 제137조제3항의 서류를 검토하여 그 의견을 지체 없이 소장에게 보고하여야 한다.', 6128);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10732, null, 6129);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10733, '① 외부위원의 임기는 2년으로 하며, 연임할 수 있다.', 6130);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10734, '② 소장은 외부위원이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 위원을 해촉할 수 있다. <개정 2016.6.28>', 6130);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10735, '③ 외부위원에게는 예산의 범위에서 수당과 여비를 지급할 수 있다.', 6130);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10736, '① 위원회의 사무를 처리하기 위하여 귀휴업무를 담당하는 교도관 중에서 간사 1명을 둔다.', 6131);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10737, '② 간사는 위원장의 명을 받아 위원회의 사무를 처리한다.', 6131);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10738, '③ 간사는 다음 각 호의 서류를 위원회에 제출하여야 한다.', 6131);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10739, '④ 간사는 별지 제3호서식에 따른 위원회 회의록을 작성하여 유지하여야 한다.', 6131);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10740, '① 소장은 수형자의 귀휴심사에 필요한 경우에는 법 제60조제1항에 따라 사실조회를 할 수 있다.', 6132);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10741, '② 소장은 심사대상자의 보호관계 등을 알아보기 위하여 필요하다고 인정하는 경우에는 그의 가족 또는 보호관계에 있는 사람에게 위원회 회의의 참석을 요청할 수 있다.', 6132);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10742, null, 6134);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10743, '① 소장은 수형자에게 귀휴를 허가한 경우 필요하다고 인정하면 교도관을 동행시킬 수 있다.', 6135);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10744, '② 소장은 귀휴자의 가족 또는 보호관계에 있는 사람으로부터 별지 제6호서식의 보호서약서를 제출받아야 한다. <개정 2013.4.16>', 6135);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10745, '③ 영 제97조제1항에 따라 경찰관서의 장에게 귀휴사실을 통보하는 경우에는 별지 제7호서식에 따른다.', 6135);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10746, '① 귀휴자의 여비와 귀휴 중 착용할 복장은 본인이 부담한다.', 6136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10747, '② 소장은 귀휴자가 신청할 경우 작업장려금의 전부 또는 일부를 귀휴비용으로 사용하게 할 수 있다.', 6136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10748, null, 6138);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10749, '① 협의회는 회장 1명을 포함하여 3명 이상 5명 이하의 내부위원과 10명 이상의 외부위원으로 구성한다. <개정 2010.5.31>', 6139);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10750, '② 협의회의 회장은 소장이 되고, 부회장은 2명을 두되 1명은 소장이 내부위원 중에서 지명하고 1명은 외부위원 중에서 호선(互選)한다.', 6139);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10751, '③ 내부위원은 소장이 지명하는 소속기관의 부소장ㆍ과장(지소의 경우에는 7급 이상의 교도관)으로 구성한다.', 6139);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10752, '④ 회장ㆍ부회장 외에 협의회 운영을 위하여 기관실정에 적합한 수의 임원을 둘 수 있다.', 6139);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10753, '① 법무부장관은 협의회의 외부위원을 다음 각 호의 사람 중에서 소장의 추천을 받아 위촉한다. <개정 2010.5.31, 2013.4.16, 2014.11.17, 2024.2.8>', 6140);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10754, '② 외부위원의 임기는 3년으로 하며, 연임할 수 있다.', 6140);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10755, '③ 법무부장관은 외부위원이 다음 각 호의 어느 하나에 해당하는 경우에는 소장의 건의를 받아 해당 위원을 해촉할 수 있다. <개정 2016.6.28>', 6140);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10756, '① 회장은 협의회를 소집하고 협의회 업무를 총괄한다.', 6141);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10757, '② 회장이 부득이한 사유로 직무를 수행할 수 없을 때에는 소장이 지정한 부회장이 그 직무를 대행한다.', 6141);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10758, '① 협의회의 회의는 반기마다 개최한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 임시회의를 개최할 수 있다. <개정 2010.5.31, 2013.4.16>', 6142);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10759, '② 협의회의 회의는 회장이 소집하고 그 의장이 된다.', 6142);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10760, '③ 협의회의 회의는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.', 6142);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10761, '① 협의회의 사무를 처리하기 위하여 수형자 취업알선 및 창업지원 업무를 전담하는 직원 중에서 간사 1명을 둔다.', 6143);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10762, '② 간사는 별지 제8호서식에 따른 협의회의 회의록을 작성하여 유지하여야 한다.', 6143);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10763, '① 사형확정자는 사형집행시설이 설치되어 있는 교정시설에 수용하되, 다음 각 호와 같이 구분하여 수용한다. 다만, 수용관리 또는 처우상 필요한 경우에는 사형집행시설이 설치되지 않은 교정시설에 수용할 수 있다. <개정 2024.2.8>', 6144);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10764, '② 사형확정자의 심리적 안정 도모 또는 교정시설의 안전과 질서유지를 위하여 특히 필요하다고 인정하는 경우에는 제1항 각 호에도 불구하고 교도소에 수용할 사형확정자를 구치소에 수용할 수 있고, 구치소에 수용할 사형확정자를 교도소에 수용할 수 있다.', 6144);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10765, '③ 사형확정자와 소년수용자를 같은 교정시설에 수용하는 경우에는 서로 분리하여 수용한다. <신설 2024.2.8>', 6144);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10766, '④ 소장은 사형확정자의 자살ㆍ도주 등의 사고를 방지하기 위하여 필요한 경우에는 사형확정자와 미결수용자를 혼거수용할 수 있고, 사형확정자의 교육ㆍ교화프로그램, 작업 등의 적절한 처우를 위하여 필요한 경우에는 사형확정자와 수형자를 혼거수용할 수 있다. <개정 2024.2.8>', 6144);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10767, '⑤ 사형확정자의 번호표 및 거실표의 색상은 붉은색으로 한다. <개정 2024.2.8>', 6144);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10768, '① 소장은 사형확정자의 심리적 안정 및 원만한 수용생활을 위하여 소속 교도관으로 하여금 지속적인 상담을 하게 하여야 한다.', 6146);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10769, '② 제1항의 사형확정자에 대한 상담시기, 상담책임자 지정, 상담결과 처리절차 등에 관하여는 제196조를 준용한다.', 6146);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10770, '① 소장은 사형확정자가 작업을 신청하면 교도관회의의 심의를 거쳐 교정시설 안에서 실시하는 작업을 부과할 수 있다. 이 경우 부과하는 작업은 심리적 안정과 원만한 수용생활을 도모하는 데 적합한 것이어야 한다.', 6147);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10771, '② 소장은 작업이 부과된 사형확정자에 대하여 교도관회의의 심의를 거쳐 제150조제5항을 적용하지 아니할 수 있다. <개정 2024.2.8>', 6147);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10772, '③ 소장은 작업이 부과된 사형확정자가 작업의 취소를 요청하면 사형확정자의 의사(意思)ㆍ건강, 담당교도관의 의견 등을 고려하여 작업을 취소할 수 있다.', 6147);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10773, '④ 사형확정자에게 작업을 부과하는 경우에는 법 제71조부터 제76조까지의 규정 및 이 규칙 제200조를 준용한다.', 6147);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10774, null, 6151);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10775, '① 소장은 교정장비의 보관 및 관리를 위하여 관리책임자와 보조자를 지정한다.', 6152);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10776, '② 제1항의 관리책임자와 보조자는 교정장비가 적정한 상태로 보관ㆍ관리될 수 있도록 수시로 점검하는 등 필요한 조치를 하여야 한다.', 6152);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10777, '③ 특정 장소에 고정식으로 설치되는 장비 외의 교정장비는 별도의 장소에 보관ㆍ관리하여야 한다.', 6152);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10778, null, 6154);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10779, '① 소장은 전자장비의 효율적인 운용을 위하여 각종 전자장비를 통합적으로 관리할 수 있는 시스템이 설치된 중앙통제실을 설치하여 운영한다.', 6155);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10780, '② 소장은 중앙통제실에 대한 외부인의 출입을 제한하여야 한다. 다만, 시찰, 참관, 그 밖에 소장이 특별히 허가한 경우에는 그러하지 아니하다.', 6155);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10781, '③ 전자장비의 통합관리시스템, 중앙통제실의 운영ㆍ관리 등에 관하여 필요한 사항은 법무부장관이 정한다.', 6155);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10782, '① 영상정보처리기기 카메라는 교정시설의 주벽(周壁)ㆍ감시대ㆍ울타리ㆍ운동장ㆍ거실ㆍ작업장ㆍ접견실ㆍ전화실ㆍ조사실ㆍ진료실ㆍ복도ㆍ중문, 그 밖에 법 제94조제1항에 따라 전자장비를 이용하여 계호하여야 할 필요가 있는 장소에 설치한다. <개정 2013.4.16>', 6156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10783, '② 영상정보처리기기 모니터는 중앙통제실, 수용관리팀의 사무실, 그 밖에 교도관이 계호하기에 적정한 장소에 설치한다. <개정 2024.2.8>', 6156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10784, '③ 거실에 영상정보처리기기 카메라를 설치하는 경우에는 용변을 보는 하반신의 모습이 촬영되지 아니하도록 카메라의 각도를 한정하거나 화장실 차폐시설을 설치하여야 한다.', 6156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10785, '① 교도관이 법 제94조제1항에 따라 거실에 있는 수용자를 계호하는 경우에는 별지 제9호서식의 거실수용자 영상계호부에 피계호자의 인적사항 및 주요 계호내용을 개별적으로 기록하여야 한다. 다만, 중경비시설의 거실에 있는 수용자를 전자장비를 이용하여 계호하는 경우에는 중앙통제실 등에 비치된 현황표에 피계호인원 등 전체 현황만을 기록할 수 있다. <개정 2010.5.31>', 6157);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10786, '② 교도관이 법 제94조제1항에 따라 계호하는 과정에서 수용자의 처우 및 관리에 특히 참고할만한 사항을 알게 된 경우에는 그 요지를 수용기록부에 기록하여 소장에게 지체 없이 보고하여야 한다.', 6157);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10787, '① 고정식 물품검색기는 정문, 수용동 입구, 작업장 입구, 그 밖에 수용자 또는 교정시설을 출입하는 수용자 외의 사람에 대한 신체ㆍ의류ㆍ휴대품의 검사가 필요한 장소에 설치한다. <개정 2013.4.16>', 6160);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10788, '② 교도관이 법 제93조제1항에 따라 수용자의 신체ㆍ의류ㆍ휴대품을 검사하는 경우에는 특별한 사정이 없으면 고정식 물품검색기를 통과하게 한 후 휴대식 금속탐지기 또는 손으로 이를 확인한다.', 6160);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10789, '③ 교도관이 법 제93조제3항에 따라 교정시설을 출입하는 수용자 외의 사람의 의류와 휴대품을 검사하는 경우에는 고정식 물품검색기를 통과하게 하거나 휴대식 금속탐지기로 이를 확인한다.', 6160);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10790, null, 6163);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10791, '① 보호장비의 규격은 별표 5와 같다.', 6164);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10792, '② 교도관은 제1항에 따른 보호장비 규격에 맞지 아니한 보호장비를 수용자에게 사용해서는 아니 된다.', 6164);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10793, '① 수갑의 사용방법은 다음 각 호와 같다.', 6166);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10794, '② 제1항제1호에 따라 수갑을 사용하는 경우에는 수갑보호기를 함께 사용할 수 있다.', 6166);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10795, '③ 제1항제2호에 따라 별표 7의 방법으로 수갑을 사용하여 그 목적을 달성한 후에는 즉시 별표 6의 방법으로 전환하거나 사용을 중지하여야 한다.', 6166);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10796, '④ 수갑은 구체적 상황에 적합한 종류를 선택하여 사용할 수 있다. 다만, 일회용수갑은 일시적으로 사용하여야 하며, 사용목적을 달성한 후에는 즉시 사용을 중단하거나 다른 보호장비로 교체하여야 한다. <개정 2013.4.16>', 6166);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10797, null, 6168);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10798, null, 6169);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10799, '① 보호의자는 별표 14의 방법으로 사용하며, 다른 보호장비로는 법 제97조제1항제2호부터 제4호까지의 규정의 어느 하나에 해당하는 행위를 방지하기 어려운 특별한 사정이 있는 경우에만 사용하여야 한다.', 6170);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10800, '② 보호의자는 제184조제2항에 따라 그 사용을 일시 중지하거나 완화하는 경우를 포함하여 8시간을 초과하여 사용할 수 없으며, 사용 중지 후 4시간이 경과하지 아니하면 다시 사용할 수 없다. <개정 2013.4.16>', 6170);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10801, '① 보호침대는 별표 15의 방법으로 사용하며, 다른 보호장비로는 자살ㆍ자해를 방지하기 어려운 특별한 사정이 있는 경우에만 사용하여야 한다.', 6171);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10802, '② 보호침대의 사용에 관하여는 제176조제2항을 준용한다.', 6171);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10803, '① 보호복은 별표 16의 방법으로 사용한다.', 6172);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10804, '② 보호복의 사용에 관하여는 제176조제2항을 준용한다.', 6172);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10805, '① 포승의 사용방법은 다음 각 호와 같다. <개정 2018.5.2, 2020.8.5>', 6173);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10806, '② 제1항제2호에 따라 포승을 사용하여 2명 이상의 수용자를 호송하는 경우에는 수용자 간에 포승을 다음 각 호의 구분에 따른 방법으로 연결하여 사용할 수 있다. <개정 2019.10.22, 2020.8.5, 2024.2.8>', 6173);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10807, '③ 삭제 <2018.5.2>', 6173);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10808, null, 6174);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10809, '① 소장은 보호장비를 착용 중인 수용자에 대하여 별지 제10호 서식의 보호장비 사용 심사부 및 별지 제11호 서식의 보호장비 착용자 관찰부 등의 기록과 관계직원의 의견 등을 토대로 보호장비의 계속사용 여부를 매일 심사하여야 한다.', 6177);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10810, '② 소장은 영 제121조에 따라 의무관 또는 의료관계 직원으로부터 보호장비의 사용 중지 의견을 보고받았음에도 불구하고 해당 수용자에 대하여 보호장비를 계속하여 사용할 필요가 있는 경우에는 의무관 또는 의료관계 직원에게 건강유지에 필요한 조치를 취할 것을 명하고 보호장비를 사용할 수 있다. 이 경우 소장은 별지 제10호서식의 보호장비 사용 심사부에 보호장비를 계속 사용할 필요가 있다고 판단하는 근거를 기록하여야 한다.', 6177);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10811, '① 교도관은 법 제97조제1항 각 호에 따른 보호장비 사용 사유가 소멸한 경우에는 소장의 허가를 받아 지체 없이 보호장비 사용을 중단하여야 한다. 다만, 소장의 허가를 받을 시간적 여유가 없을 때에는 보호장비 사용을 중단한 후 지체 없이 소장의 승인을 받아야 한다. <개정 2013.4.16>', 6178);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10812, '② 교도관은 보호장비 착용 수용자의 목욕, 식사, 용변, 치료 등을 위하여 필요한 경우에는 보호장비 사용을 일시 중지하거나 완화할 수 있다. <개정 2013.4.16>', 6178);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10813, null, 6180);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10814, '① 교도관이 수용자에 대하여 사용할 수 있는 보안장비의 종류별 사용요건은 다음 각 호와 같다. <개정 2014.11.17>', 6181);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10815, '② 교도관이 수용자 외의 사람에 대하여 사용할 수 있는 보안장비의 종류별 사용요건은 다음 각 호와 같다. <개정 2014.11.17>', 6181);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10816, '③ 제186조제7호에 해당하는 보안장비의 사용은 법무부장관이 정하는 바에 따른다.', 6181);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10817, null, 6182);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10818, null, 6183);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10819, '① 교도관이 수용자에 대하여 사용할 수 있는 무기의 종류별 사용요건은 다음 각 호와 같다. <개정 2014.11.17>', 6184);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10820, '② 교도관이 수용자 외의 사람에 대하여 사용할 수 있는 무기의 종류별 사용요건은 다음 각 호와 같다. <개정 2014.11.17>', 6184);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10821, '③ 제189조제4호에 해당하는 무기의 사용은 법무부장관이 정하는 바에 따른다.', 6184);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10822, '① 소장은 소속 교도관에 대하여 연 1회 이상 총기의 조작ㆍ정비ㆍ사용에 관한 교육을 한다.', 6187);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10823, '② 제1항의 교육을 받지 아니하였거나 총기 조작이 미숙한 사람, 그 밖에 총기휴대가 부적당하다고 인정되는 사람에 대하여는 총기휴대를 금지하고 별지 제12호서식의 총기휴대 금지자 명부에 그 명단을 기록한 후 총기를 지급할 때마다 대조ㆍ확인하여야 한다.', 6187);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10824, '③ 제2항의 총기휴대 금지자에 대하여 금지사유가 소멸한 경우에는 그 사유를 제2항에 따른 총기휴대 금지자 명부에 기록하고 총기휴대금지를 해제하여야 한다.', 6187);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10825, null, 6188);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10826, '① 엄중관리대상자의 번호표 및 거실표의 색상은 다음 각 호와 같이 구분한다.', 6189);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10827, '② 제194조의 엄중관리대상자 구분이 중복되는 수용자의 경우 그 번호표 및 거실표의 색상은 제1항 각 호의 순서에 따른다.', 6189);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10828, '① 소장은 엄중관리대상자 중 지속적인 상담이 필요하다고 인정되는 사람에 대하여는 상담책임자를 지정한다.', 6190);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10829, '② 제1항의 상담책임자는 감독교도관 또는 상담 관련 전문교육을 이수한 교도관을 우선하여 지정하여야 하며, 상담대상자는 상담책임자 1명당 10명 이내로 하여야 한다. <개정 2013.4.16>', 6190);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10830, '③ 상담책임자는 해당 엄중관리대상자에 대하여 수시로 개별상담을 함으로써 신속한 고충처리와 원만한 수용생활 지도를 위하여 노력하여야 한다. <개정 2013.4.16>', 6190);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10831, '④ 제3항에 따라 상담책임자가 상담을 하였을 때에는 그 요지와 처리결과 등을 제119조제3항에 따른 교정정보시스템에 입력하여야 한다. 이 경우 엄중관리대상자의 처우를 위하여 필요하면 별지 제13호서식의 엄중관리대상자 상담결과 보고서를 작성하여 소장에게 보고하여야 한다. <개정 2013.4.16>', 6190);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10832, null, 6192);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10833, '① 소장은 제198조 각 호의 어느 하나에 해당하는 수용자에 대하여는 조직폭력수용자로 지정한다. 현재의 수용생활 중 집행되었거나 집행할 형이 제198조제1호 또는 제2호에 해당하는 경우에도 또한 같다. <개정 2014.11.17>', 6193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10834, '② 소장은 제1항에 따라 조직폭력수용자로 지정된 사람에 대하여는 석방할 때까지 지정을 해제할 수 없다. 다만, 공소장 변경 또는 재판 확정에 따라 지정사유가 해소되었다고 인정되는 경우에는 교도관회의의 심의 또는 분류처우위원회의 의결을 거쳐 지정을 해제한다. <개정 2014.11.17>', 6193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10835, null, 6198);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10836, '① 소장은 제204조 각 호의 어느 하나에 해당하는 수용자에 대하여는 마약류수용자로 지정하여야 한다. 현재의 수용생활 중 집행되었거나 집행할 형이 제204조제1호에 해당하는 경우에도 또한 같다.', 6199);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10837, '② 소장은 제1항에 따라 마약류수용자로 지정된 사람에 대하여는 석방할 때까지 지정을 해제할 수 없다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 교도관회의의 심의 또는 분류처우위원회의 의결을 거쳐 지정을 해제할 수 있다. <개정 2014.11.17>', 6199);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10838, '① 마약류수용자에 대하여 다량 또는 장기간 복용할 경우 환각증세를 일으킬 수 있는 의약품을 투약할 때에는 특히 유의하여야 한다.', 6200);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10839, '② 소장은 교정시설에 마약류를 반입하는 것을 방지하기 위하여 필요하면 강제에 의하지 아니하는 범위에서 수용자의 소변을 채취하여 마약반응검사를 할 수 있다.', 6200);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10840, '③ 소장은 제2항의 검사 결과 양성반응이 나타난 수용자에 대하여는 관계기관에 혈청검사, 모발검사, 그 밖의 정밀검사를 의뢰하고 그 결과에 따라 적절한 조치를 하여야 한다.', 6200);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10841, null, 6201);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10842, '① 소장은 마약류수용자가 마약류 근절(根絶) 의지를 갖고 이를 실천할 수 있도록 해당 교정시설의 여건에 적합한 마약류수용자 재활교육계획을 수립하여 시행하여야 한다.', 6203);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10843, '② 소장은 마약류수용자의 마약류 근절 의지를 북돋울 수 있도록 마약 퇴치 전문강사, 성직자 등과 자매결연을 주선할 수 있다.', 6203);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10844, null, 6204);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10845, '① 소장은 제210조 각 호의 어느 하나에 해당하는 수용자에 대하여는 분류처우위원회의 의결을 거쳐 관심대상수용자로 지정한다. 다만, 미결수용자 등 분류처우위원회의 의결 대상자가 아닌 경우에도 관심대상수용자로 지정할 필요가 있다고 인정되는 수용자에 대하여는 교도관회의의 심의를 거쳐 관심대상수용자로 지정할 수 있다. <개정 2013.4.16, 2014.11.17>', 6205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10846, '② 소장은 관심대상수용자의 수용생활태도 등이 양호하고 지정사유가 해소되었다고 인정하는 경우에는 제1항의 절차에 따라 그 지정을 해제한다. <개정 2013.4.16, 2016.6.28>', 6205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10847, '③ 제1항 및 제2항에 따라 관심대상수용자로 지정하거나 지정을 해제하는 경우에는 담당교도관 또는 감독교도관의 의견을 고려하여야 한다.', 6205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10848, null, 6208);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10849, null, 6209);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10850, null, 6210);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10851, null, 6211);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10852, null, 6212);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10853, '① 다른 수용자를 교사(敎唆)하여 징벌대상행위를 하게 한 수용자에게는 그 징벌대상행위를 한 수용자에게 부과되는 징벌과 같은 징벌을 부과한다.', 6213);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10854, '② 다른 수용자의 징벌대상행위를 방조(幇助)한 수용자에게는 그 징벌대상행위를 한 수용자에게 부과되는 징벌과 같은 징벌을 부과하되, 그 정황을 고려하여 2분의 1까지 감경할 수 있다.', 6213);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10855, '① 둘 이상의 징벌대상행위가 경합하는 경우에는 각각의 행위에 해당하는 징벌 중 가장 중한 징벌의 2분의 1까지 가중할 수 있다.', 6214);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10856, '② 제1항의 경우 징벌의 경중(輕重)은 제215조 각 호의 순서에 따른다. 이 경우 같은 조 제2호부터 제5호까지의 경우에는 각 목의 순서에 따른다.', 6214);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10857, null, 6215);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10858, '① 수용자의 징벌대상행위에 대한 조사기간(조사를 시작한 날부터 법 제111조제1항의 징벌위원회의 의결이 있는 날까지를 말한다. 이하 같다)은 10일 이내로 한다. 다만, 특히 필요하다고 인정하는 경우에는 1회에 한하여 7일을 초과하지 아니하는 범위에서 그 기간을 연장할 수 있다.', 6217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10859, '② 소장은 제1항의 조사기간 중 조사결과에 따라 다음 각 호의 어느 하나에 해당하는 조치를 할 수 있다. <개정 2013.4.16>', 6217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10860, '③ 제1항의 조사기간 중 법 제110조제2항에 따라 징벌대상자에 대하여 처우를 제한하는 경우에는 징벌위원회의 의결을 거쳐 처우를 제한한 기간의 전부 또는 일부를 징벌기간에 포함할 수 있다.', 6217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10861, '④ 소장은 징벌대상행위가 징벌대상자의 정신병적인 원인에 따른 것으로 의심할 만한 충분한 사유가 있는 경우에는 징벌절차를 진행하기 전에 의사의 진료, 전문가 상담 등 필요한 조치를 하여야 한다.', 6217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10862, '⑤ 소장은 징벌대상행위에 대한 조사 결과 그 행위가 징벌대상자의 정신병적인 원인에 따른 것이라고 인정하는 경우에는 그 행위를 이유로 징벌위원회에 징벌을 요구할 수 없다.', 6217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10863, '⑥ 제1항의 조사기간 중 징벌대상자의 생활용품 등의 보관에 대해서는 제232조를 준용한다. <신설 2010.5.31>', 6217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10864, '① 소장은 징벌대상자의 질병이나 그 밖의 특별한 사정으로 인하여 조사를 계속하기 어려운 경우에는 조사를 일시 정지할 수 있다.', 6218);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10865, '② 제1항에 따라 정지된 조사기간은 그 사유가 해소된 때부터 다시 진행한다. 이 경우 조사가 정지된 다음 날부터 정지사유가 소멸한 전날까지의 기간은 조사기간에 포함되지 아니한다.', 6218);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10866, '① 소장은 법 제111조제2항에 따른 징벌위원회의 외부위원을 다음 각 호의 사람 중에서 위촉한다. <개정 2014.11.17, 2019.10.22>', 6220);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10867, '② 제1항에 따라 위촉된 위원의 임기는 2년으로 하며, 연임할 수 있다.', 6220);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10868, '③ 소장은 외부위원이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 위원을 해촉할 수 있다. <개정 2016.6.28>', 6220);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10869, '④ 제1항에 따라 위촉된 위원이 징벌위원회에 참석한 경우에는 예산의 범위에서 수당, 여비, 그 밖에 필요한 경비를 지급할 수 있다.', 6220);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10870, null, 6222);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10871, '① 소장이 징벌대상자에 대하여 징벌의결을 요구하는 경우에는 별지 제14호서식의 징벌의결 요구서를 작성하여 징벌위원회에 제출하여야 한다.', 6223);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10872, '② 제1항에 따른 징벌의결 요구서에는 징벌대상행위의 입증에 필요한 관계서류를 첨부할 수 있다.', 6223);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10873, '① 징벌위원회가 제226조에 따른 징벌의결 요구서를 접수한 경우에는 지체 없이 징벌대상자에게 별지 제15호서식의 출석통지서를 전달하여야 한다.', 6224);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10874, '② 제1항에 따른 출석통지서에는 다음 각 호의 내용이 포함되어야 한다.', 6224);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10875, '③ 제1항에 따라 출석통지서를 전달받은 징벌대상자가 징벌위원회에 출석하기를 원하지 아니하는 경우에는 별지 제16호서식의 출석포기서를 징벌위원회에 제출하여야 한다.', 6224);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10876, '① 징벌위원회는 출석한 징벌대상자를 심문하고, 필요하다고 인정하는 경우에는 교도관이나 다른 수용자 등을 참고인으로 출석하게 하여 심문할 수 있다.', 6225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10877, '② 징벌위원회는 필요하다고 인정하는 경우 제219조의2에 따라 심리상담을 한 교도관으로 하여금 그 심리상담 결과를 제출하게 하거나 해당 교도관을 징벌위원회에 출석하게 하여 심리상담 결과를 진술하게 할 수 있다. <신설 2018.12.28>', 6225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10878, '③ 징벌위원회는 징벌대상자에게 제227조제1항에 따른 출석통지서를 전달하였음에도 불구하고 징벌대상자가 같은 조 제3항에 따른 출석포기서를 제출하거나 정당한 사유 없이 출석하지 아니한 경우에는 그 사실을 별지 제17호서식의 징벌위원회 회의록에 기록하고 서면심리만으로 징벌을 의결할 수 있다. <개정 2018.12.28>', 6225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10879, '④ 징벌위원회는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다. 이 경우 외부위원 1명 이상이 출석한 경우에만 개의할 수 있다. <개정 2014.11.17, 2018.12.28>', 6225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10880, '⑤ 징벌의 의결은 별지 제18호서식의 징벌의결서에 따른다. <개정 2018.12.28>', 6225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10881, '⑥ 징벌위원회가 작업장려금 삭감을 의결하려면 사전에 수용자의 작업장려금을 확인하여야 한다. <개정 2018.12.28>', 6225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10882, '⑦ 징벌위원회의 회의에 참여한 사람은 직무상 알게 된 비밀을 누설하여서는 아니 된다. <개정 2018.12.28>', 6225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10883, '① 징벌위원회는 영 제132조에 따라 소장에게 징벌의결 내용을 통고하는 경우에는 징벌의결서 정본(正本)을 첨부하여야 한다.', 6226);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10884, '② 소장은 징벌을 집행하려면 징벌의결의 내용과 징벌처분에 대한 불복방법 등을 기록한 별지 제19호서식의 징벌집행통지서에 징벌의결서 부본(副本)을 첨부하여 해당 수용자에게 전달하여야 한다.', 6226);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10885, '③ 영 제137조에 따른 징벌집행부는 별지 제19호의2 서식에 따른다. <신설 2019.10.22>', 6226);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10886, '④ 소장은 영 제137조에 따라 수용자의 징벌에 관한 사항을 징벌집행부에 기록한 때에는 그 내용을 제119조제3항에 따른 교정정보시스템에 입력해야 한다. <신설 2019.10.22>', 6226);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10887, '① 금치와 그 밖의 징벌을 집행할 경우에는 금치를 우선하여 집행한다. 다만, 작업장려금의 삭감과 경고는 금치와 동시에 집행할 수 있다.', 6227);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10888, '② 같은 종류의 징벌은 그 기간이 긴 것부터 집행한다.', 6227);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10889, '③ 금치를 제외한 두 가지 이상의 징벌을 집행할 경우에는 함께 집행할 수 있다.', 6227);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10890, '④ 두 가지 이상의 금치는 연속하여 집행할 수 없다. 다만, 두 가지 이상의 금치 기간의 합이 45일 이하인 경우에는 그렇지 않다. <신설 2024.2.8>', 6227);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10891, '① 작업장려금의 삭감은 징벌위원회가 해당 징벌을 의결한 날이 속하는 달의 작업장려금부터 이미 지급된 작업장려금에 대하여 역순으로 집행한다.', 6228);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10892, '② 소장은 금치를 집행하는 경우에는 징벌집행을 위하여 별도로 지정한 거실(이하 "징벌거실"이라 한다)에 해당 수용자를 수용하여야 한다.', 6228);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10893, '③ 소장은 금치 외의 징벌을 집행하는 경우 그 징벌의 목적을 달성하기 위하여 필요하다고 인정하면 해당 수용자를 징벌거실에 수용할 수 있다.', 6228);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10894, '④ 소장은 징벌집행을 받고 있거나 집행을 앞둔 수용자가 같은 행위로 형사 법률에 따른 처벌이 확정되어 징벌을 집행할 필요가 없다고 인정하면 징벌집행을 감경하거나 면제할 수 있다.', 6228);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10895, '① 소장은 징벌집행 중인 수용자의 심리적 안정과 징벌대상행위의 재발방지를 위해서 교도관으로 하여금 징벌집행 중인 수용자에 대한 심리상담을 하게 해야 한다.', 6230);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10896, '② 소장은 징벌대상행위의 재발방지에 도움이 된다고 인정하는 경우에는 징벌집행 중인 수용자가 교정위원, 자원봉사자 등 전문가의 상담을 받게 할 수 있다.', 6230);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10897, '① 법 제115조제1항에서 "법무부령으로 정하는 기간"이란 다음 각 호와 같다. <개정 2013.4.16>', 6231);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10898, '② 소장은 법 제115조제1항ㆍ제2항에 따라 징벌을 실효시킬 필요가 있으면 징벌실효기간이 지나거나 분류처우위원회의 의결을 거친 후에 지체 없이 법무부장관에게 그 승인을 신청하여야 한다.', 6231);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10899, '③ 소장은 법 제115조에 따라 실효된 징벌을 이유로 그 수용자에게 처우상 불이익을 주어서는 아니 된다.', 6231);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10900, '① 가석방심사는 객관적 자료와 기준에 따라 공정하게 하여야 하며, 심사 과정에서 알게 된 비밀은 누설해서는 아니 된다.', 6234);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10901, '② 삭제 <2013.4.16>', 6234);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10902, '① 위원장은 위원회를 소집하고 위원회의 업무를 총괄한다.', 6235);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10903, '② 위원장이 부득이한 사정으로 직무를 수행할 수 없을 때에는 위원장이 미리 지정한 위원이 그 직무를 대행한다.', 6235);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10904, null, 6236);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10905, null, 6237);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10906, '① 위원장은 위원회의 사무를 처리하기 위하여 소속 공무원 중에서 간사 1명과 서기 약간 명을 임명한다.', 6239);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10907, '② 간사는 위원장의 명을 받아 위원회의 사무를 처리하고 회의에 참석하여 발언할 수 있다.', 6239);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10908, '③ 서기는 간사를 보조한다.', 6239);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10909, '① 위원회의 회의는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.', 6240);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10910, '② 간사는 위원회의 결정에 대하여 결정서를 작성하여야 한다.', 6240);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10911, '① 간사는 별지 제20호서식의 가석방심사위원회 회의록을 작성하여 유지하여야 한다.', 6241);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10912, '② 회의록에는 회의의 내용을 기록하고 위원장 및 간사가 기명날인 또는 서명하여야 한다. <개정 2013.4.16>', 6241);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10913, '① 소장은 「형법」 제72조제1항의 기간을 경과한 수형자로서 교정성적이 우수하고 뉘우치는 빛이 뚜렷하여 재범의 위험성이 없다고 인정하는 경우에는 분류처우위원회의 의결을 거쳐 가석방 적격심사신청 대상자를 선정한다. <개정 2010.5.31>', 6243);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10914, '② 소장은 가석방 적격심사신청에 필요하다고 인정하면 분류처우위원회에 수형자를 출석하게 하여 진술하도록 하거나 담당교도관을 출석하게 하여 의견을 들을 수 있다. <개정 2010.5.31, 2024.2.8>', 6243);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10915, null, 6244);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10916, '① 소장은 제246조에 따라 조사한 사항을 매월 분류처우위원회의 회의 개최일 전날까지 분류처우심사표에 기록하여야 한다.', 6246);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10917, '② 제1항의 분류처우심사표는 법무부장관이 정한다.', 6246);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10918, '① 제246조제1호의 사항에 대한 조사는 수형자를 수용한 날부터 1개월 이내에 하고, 그 후 변경할 필요가 있는 사항이 발견되거나 가석방 적격심사신청을 위하여 필요한 경우에 한다. <개정 2010.5.31>', 6247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10919, '② 제246조제2호의 사항에 대한 조사는 수형자를 수용한 날부터 2개월 이내에 하고, 조사에 필요하다고 인정하는 경우에는 소송기록을 열람할 수 있다.', 6247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10920, '③ 제246조제3호의 사항에 대한 조사는 형기의 3분의 1이 지나기 전에 하여야 하고, 그 후 변경된 사항이 있는 경우에는 지체 없이 그 내용을 변경하여야 한다.', 6247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10921, '① 소장은 법 제121조제1항에 따라 가석방 적격심사를 신청할 때에는 별지 제21호서식의 가석방 적격심사신청서에 별지 제22호서식의 가석방 적격심사 및 신상조사표를 첨부하여야 한다. <개정 2010.5.31>', 6248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10922, '② 소장은 가석방 적격심사신청 대상자를 선정한 경우 선정된 날부터 5일 이내에 위원회에 가석방 적격심사신청을 하여야 한다. <개정 2010.5.31>', 6248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10923, '③ 소장은 위원회에 적격심사신청한 사실을 수형자의 동의를 받아 보호자 등에게 알릴 수 있다. <개정 2010.5.31>', 6248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10924, '① 위원회가 범죄의 동기에 관하여 심사할 때에는 사회의 통념 및 공익 등에 비추어 정상을 참작할 만한 사유가 있는지를 심사하여야 한다.', 6251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10925, '② 범죄의 동기가 군중의 암시 또는 도발, 감독관계에 의한 위협, 그 밖에 이와 유사한 사유로 인한 것일 때에는 특히 수형자의 성격 또는 환경의 변화에 유의하고 가석방 후의 환경이 가석방처분을 받은 사람(「보호관찰 등에 관한 법률」에 따른 보호관찰대상자는 제외한다. 이하 "가석방자"라 한다)에게 미칠 영향을 심사하여야 한다.', 6251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10926, null, 6252);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10927, '① 재산에 관한 죄를 지은 수형자에 대하여는 특히 그 범행으로 인하여 발생한 손해의 배상 여부 또는 손해를 경감하기 위한 노력 여부를 심사하여야 한다.', 6253);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10928, '② 수형자 외의 사람이 피해자의 손해를 배상한 경우에는 그 배상이 수형자 본인의 희망에 따른 것인지를 심사하여야 한다.', 6253);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10929, '① 위원회는 가석방 적격심사에 특히 필요하다고 인정하면 심층면접(수형자 면담ㆍ심리검사, 수형자의 가족 또는 보호관계에 있는 사람 등에 대한 방문조사 등을 통해 재범의 위험성, 사회복귀 준비 상태 등을 파악하는 것을 말한다. 이하 이 조에서 같다)을 실시할 수 있다.', 6254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10930, '② 심층면접의 방법, 절차, 그 밖에 필요한 사항은 법무부장관이 정한다.', 6254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10931, '① 위원회는 가석방 적격심사에 필요하다고 인정하면 수형자의 주소지 또는 연고지 등을 관할하는 시ㆍ군ㆍ구ㆍ경찰서, 그 밖에 학교ㆍ직업알선기관ㆍ보호단체ㆍ종교단체 등 관계기관에 사실조회를 할 수 있다. <개정 2010.5.31>', 6255);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10932, '② 위원회는 가석방 적격심사를 위하여 필요하다고 인정하면 위원이 아닌 판사ㆍ검사 또는 군법무관에게 의견을 묻거나 위원회에 참여시킬 수 있다. <개정 2010.5.31>', 6255);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10933, '① 위원회는 가석방 적격심사를 위하여 필요하다고 인정하면 심리학ㆍ정신의학ㆍ사회학 또는 교육학을 전공한 전문가에게 수형자의 정신상태 등 특정 사항에 대한 감정을 촉탁할 수 있다. <개정 2010.5.31>', 6256);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10934, '② 제1항에 따른 촉탁을 받은 사람은 소장의 허가를 받아 수형자와 접견할 수 있다.', 6256);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10935, '① 수형자를 가석방한 소장 또는 가석방자를 수용하고 있는 소장은 가석방자가 제260조의 가석방 취소사유에 해당하는 사실이 있음을 알게 되거나 관할 경찰서장으로부터 그 사실을 통보받은 경우에는 지체 없이 별지 제25호서식의 가석방 취소심사신청서에 별지 제26호서식의 가석방 취소심사 및 조사표를 첨부하여 위원회에 가석방 취소심사를 신청하여야 한다.', 6260);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10936, '② 위원회가 제1항의 신청을 받아 심사를 한 결과 가석방을 취소하는 것이 타당하다고 결정한 경우에는 별지 제23호서식의 결정서에 별지 제26호서식의 가석방 취소심사 및 조사표를 첨부하여 지체 없이 법무부장관에게 가석방의 취소를 신청하여야 한다.', 6260);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10937, '③ 소장은 가석방을 취소하는 것이 타당하다고 인정하는 경우 긴급한 사유가 있을 때에는 위원회의 심사를 거치지 아니하고 전화, 전산망 또는 그 밖의 통신수단으로 법무부장관에게 가석방의 취소를 신청할 수 있다. 이 경우 소장은 지체 없이 별지 제26호서식의 가석방 취소심사 및 조사표를 송부하여야 한다.', 6260);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10938, '① 위원회가 가석방 취소를 심사하는 경우에는 가석방자가 「가석방자관리규정」등의 법령을 위반하게 된 경위와 그 위반이 사회에 미치는 영향, 가석방 기간 동안의 생활 태도, 직업의 유무와 종류, 생활환경 및 친족과의 관계, 그 밖의 사정을 고려하여야 한다.', 6261);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10939, '② 위원회는 제1항의 심사를 위하여 필요하다고 인정하면 가석방자를 위원회에 출석하게 하여 진술을 들을 수 있다.', 6261);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10940, '① 소장은 가석방이 취소된 경우에는 지체 없이 남은 형기 집행에 필요한 조치를 취하고 법무부장관에게 별지 제27호서식의 가석방취소자 남은 형기 집행보고서를 송부해야 한다. <개정 2022.2.7>', 6262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10941, '② 소장은 가석방자가 「형법」 제74조에 따라 가석방이 실효된 것을 알게 된 경우에는 지체 없이 남은 형기 집행에 필요한 조치를 취하고 법무부장관에게 별지 제28호서식의 가석방실효자 남은 형기 집행보고서를 송부해야 한다. <개정 2022.2.7>', 6262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10942, '③ 소장은 가석방이 취소된 사람(이하 "가석방취소자"라 한다) 또는 가석방이 실효된 사람(이하 "가석방실효자"라 한다)이 교정시설에 수용되지 아니한 사실을 알게 된 때에는 관할 지방검찰청 검사 또는 관할 경찰서장에게 구인하도록 의뢰하여야 한다.', 6262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10943, '④ 제3항에 따라 구인 의뢰를 받은 검사 또는 경찰서장은 즉시 가석방취소자 또는 가석방실효자를 구인하여 소장에게 인계하여야 한다.', 6262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10944, '⑤ 가석방취소자 및 가석방실효자의 남은 형기 기간은 가석방을 실시한 다음 날부터 원래 형기의 종료일까지로 하고, 남은 형기 집행 기산일은 가석방의 취소 또는 실효로 인하여 교정시설에 수용된 날부터 한다. <개정 2022.2.7>', 6262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10945, '⑥ 가석방 기간 중 형사사건으로 구속되어 교정시설에 미결수용 중인 자의 가석방 취소 결정으로 남은 형기를 집행하게 된 경우에는 가석방된 형의 집행을 지휘하였던 검찰청 검사에게 남은 형기 집행지휘를 받아 우선 집행해야 한다. <개정 2022.2.7>', 6262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10946, null, 6265);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10947, '① 위원회에 부위원장을 두며, 위원 중에서 호선한다.', 6266);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10948, '② 위원 중 4명 이상은 여성으로 한다. <개정 2019.10.22>', 6266);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10949, '③ 지방교정청장이 위원을 추천하는 경우에는 별지 제29호서식의 교정자문위원회 위원 추천서를 법무부장관에게 제출하여야 한다. 다만, 재위촉의 경우에는 지방교정청장의 의견서로 추천서를 갈음한다. <개정 2019.10.22>', 6266);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10950, '① 위원의 임기는 2년으로 하며, 연임할 수 있다.', 6267);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10951, '② 지방교정청장은 위원의 결원이 생긴 경우에는 결원이 생긴 날부터 30일 이내에 후임자를 법무부장관에게 추천해야 한다. <개정 2019.10.22>', 6267);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10952, '③ 결원이 된 위원의 후임으로 위촉된 위원의 임기는 전임자 임기의 남은 기간으로 한다.', 6267);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10953, '① 위원장은 위원회를 소집하고 위원회의 업무를 총괄한다.', 6268);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10954, '② 위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 부위원장이 그 직무를 대행하고, 부위원장도 부득이한 사유로 직무를 수행할 수 없을 때에는 위원장이 미리 지명한 위원이 그 직무를 대행한다.', 6268);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10955, '① 위원회의 회의는 위원 과반수의 요청이 있거나 지방교정청장이 필요하다고 인정하는 경우에 개최한다. <개정 2013.4.16, 2019.10.22>', 6269);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10956, '② 위원회는 재적위원 과반수의 출석으로 개의하고 출석위원 과반수의 찬성으로 의결한다.', 6269);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10957, '③ 위원회의 회의는 공개하지 아니한다. 다만, 위원회의 의결을 거친 경우에는 공개할 수 있다.', 6269);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10958, '① 위원은 다음 사항을 지켜야 한다. <개정 2020.8.5>', 6270);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10959, '② 위원은 별지 제30호서식의 서약서에 규정된 바에 따라 제1항의 내용을 지키겠다는 서약을 해야 한다. <개정 2020.8.5>', 6270);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10960, null, 6271);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10961, '① 위원회의 사무를 처리하기 위하여 위원회에 간사 1명을 둔다. 간사는 해당 지방교정청의 총무과장 또는 6급 이상의 교도관으로 한다. <개정 2019.10.22>', 6272);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10962, '② 간사는 회의에 참석하여 위원회의 심의사항에 대한 설명을 하거나 필요한 발언을 할 수 있으며, 별지 제31호서식의 교정자문위원회 회의록을 작성하여 유지하여야 한다.', 6272);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10963, '① 검사와 사법경찰관은 피의자에게 법 제4조제6항 본문에 따라 신상정보 공개를 결정하기 전에 의견을 진술할 기회가 있다는 사실을 고지하고 별지 제1호서식의 의견진술 기회 등 고지 확인서를 제출받아야 한다.', 6276);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10964, '② 검사와 사법경찰관은 법 제8조에 따른 신상정보공개심의위원회를 개최하는 경우에는 피의자에게 해당 위원회의 개최일과 위원회에 의견을 진술할 기회가 있다는 사실을 고지하고 별지 제2호서식의 신상정보공개심의위원회 개최 통지 확인서를 제출받아야 한다.', 6276);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10965, '③ 검사와 사법경찰관은 제1항 또는 제2항의 고지를 받은 피의자가 의견 진술을 희망하는 의사를 표시한 경우에는 피의자에게 별지 제3호서식의 의견서 양식을 교부해야 한다. 다만, 피의자가 의견서 수령을 거부하는 의사를 밝힌 경우에는 교부하지 않을 수 있다.', 6276);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10966, '① 검사와 사법경찰관은 법 제4조제1항에 따라 피의자의 신상정보를 공개하기로 결정한 경우에는 지체 없이 별지 제4호서식의 피의자 신상정보 공개 결정 통지서로 피의자에게 통지해야 한다. 이 경우 피의자에게 변호인이 있는 경우에는 변호인에게도 피의자의 신상정보 공개 사실을 알려야 한다.', 6277);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10967, '② 검사와 사법경찰관은 제1항에 따른 통지를 받은 피의자가 신상정보 공개 결정에 대해 이의가 없다는 의사를 표시해 법 제4조제7항 단서에 따라 유예기간을 두지 않는 경우에는 별지 제5호서식의 신상정보 공개 결정 확인서를 제출받아야 한다.', 6277);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10968, '③ 사법경찰관은 신상정보를 공개하기로 결정된 특정중대범죄사건을 검사에게 송치하는 경우에는 별지 제4호서식의 피의자 신상정보 공개 결정 통지서를 수사기록에 편철하는 방식으로 신상정보 공개 결정 사실을 통보해야 한다.', 6277);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10969, '④ 제3항에 따라 사법경찰관이 검사에게 사건을 송치한 경우에도 해당 사건 피의자의 신상정보 공개는 사법경찰관이 집행한다.', 6277);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10970, '① 검사와 사법경찰관은 법 제4조에 따라 피의자의 신상정보를 검찰총장 또는 경찰청장이 지정하는 인터넷 홈페이지에 신상정보 공개일부터 30일간 게시하는 방법으로 공개한다. 이 경우 유죄의 판결이 확정될 때까지는 피의자가 무죄로 추정된다는 내용을 명시해야 한다.', 6278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10971, '② 검사와 사법경찰관은 법 제4조제8항에 따른 신상정보 공개기간이 지나거나 신상정보가 공개된 피의자가 불기소처분 또는 불송치결정을 받은 경우 등 피의자의 신상정보 공개를 종료해야 할 사유가 생겼을 때에는 지체 없이 공개한 신상정보를 삭제해야 한다.', 6278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10972, '① 검사는 신상정보를 공개하기로 결정된 특정중대범죄사건 중 제4조제3항에 따라 사법경찰관으로부터 송치받은 특정중대범죄사건에 대해 전부 또는 일부 불기소처분을 한 경우에는 그 사실을 별지 제6호서식의 신상정보 공개 결정 사건 불기소처분 통보서로 사법경찰관에게 통보한다.', 6279);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10973, '② 사법경찰관은 신상정보를 공개하기로 결정된 특정중대범죄사건 전부 또는 일부에 대해 불기소처분이 된 경우에는 신상정보를 공개해서는 안 되며, 이미 신상정보를 공개한 경우에는 그 신상정보를 지체 없이 삭제해야 한다. 다만, 일부 불기소처분의 경우 불기소처분이 된 부분을 제외하더라도 신상정보 공개 결정을 유지할 필요가 인정되는 경우에는 삭제하지 않을 수 있다.', 6279);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10974, '① 검사는 법 제5조제1항에 따라 법원에 피고인의 신상정보 공개를 청구하는 경우에는 법 제4조제1항 각 호의 요건을 갖추었음을 인정할 수 있는 자료를 제출해야 한다.', 6280);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10975, '② 검사는 법 제5조제5항에 따라 피고인에 대한 신상정보 공개 결정이 있는 경우 지체 없이 별지 제7호서식의 피고인 신상정보 공개 결정 통지서로 피고인에게 통지해야 한다.', 6280);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10976, '③ 피고인에 대한 신상정보 공개 방법 및 공개의 종료 등에 관하여는 제5조를 준용한다. 이 경우 "피의자"는 "피고인"으로, "불기소처분 또는 불송치결정을 받은 경우"는 "무죄재판을 받아 확정된 경우"로 본다.', 6280);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10977, '① 법 제8조에 따른 신상정보공개심의위원회(이하 "위원회"라 한다)는 각급 검찰청(지청을 포함한다) 및 경찰관서에 둘 수 있다.', 6281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10978, '② 위원회는 위원장 1명을 포함하여 7명 이상 10명 이하의 위원으로 구성한다. 이 경우 공무원이 아닌 위원이 과반수가 되도록 하여야 한다.', 6281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10979, '③ 위원회의 위원(이하 "위원"이라 한다)은 법조계나 학계 등에서 사회적 신망이 높고 경험이 풍부한 사람 중 검찰총장 또는 경찰청장이 성별을 고려하여 임명하거나 위촉한다.', 6281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10980, '④ 위원회의 위원장(이하 "위원장"이라 한다)은 공무원이 아닌 위원 중에서 검찰총장 또는 경찰청장이 위촉한다.', 6281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10981, '⑤ 검찰총장 또는 경찰청장은 위원 및 위원장의 임명 또는 위촉 권한을 각각 각급 검찰청의 장(지청장을 포함한다) 또는 각급 경찰관서의 장에게 위임할 수 있다.', 6281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10982, '⑥ 위원은 다음 각 호의 어느 하나에 해당하는 경우에는 위원회의 심의ㆍ의결에서 제척(除斥)된다.', 6281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10983, '⑦ 위원이 제6항 각 호의 어느 하나에 해당하는 경우에는 위원회에 그 사실을 알리고 스스로 해당 안건의 심의ㆍ의결에서 회피(回避)하여야 한다.', 6281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10984, '⑧ 위원회의 심의는 공개하지 않으며, 재적위원 과반수의 찬성으로 의결한다.', 6281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10985, '⑨ 위원의 명부와 심의내용에 관한 위원의 의견서 등 위원회의 문서는 공개하지 않는다.', 6281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10986, '⑩ 제1항부터 제9항까지에서 규정한 사항 외에 위원회의 구성 및 운영 에 필요한 사항은 검찰총장 및 경찰청장이 정한다.', 6281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10987, null, 6282);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10988, '① 「전자장치 부착 등에 관한 법률」(이하 "법"이라 한다) 제6조제1항, 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제2항제2호 및 제3항제2호에 따른 조사요청은 별지 제1호서식의 부착명령 청구 전 조사 요청서에 따른다. <개정 2009.7.30, 2010.7.15, 2013.5.31, 2020.8.5>', 6285);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10989, '② 「전자장치 부착 등에 관한 법률 시행령」(이하 "영"이라 한다) 제4조제1항 후단에 따른 참고자료란 피의자 신문조서, 피해자 진술조서, 범죄경력자료 및 수사경력자료 등을 말한다. <개정 2010.7.15, 2013.5.31, 2020.8.5>', 6285);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10990, '① 법 제8조의 부착명령청구서는 별지 제2호서식과 같다. 다만, 공소제기와 동시에 부착명령을 청구하는 경우에는 영 제5조제2항에 따라 별지 제3호서식의 공소장 및 부착명령청구서로 할 수 있다.', 6286);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10991, '② 공소를 제기한 후에 부착명령을 청구하는 경우에는 부착명령 청구사건과 병합심리할 피고사건의 법원명, 사건번호, 피고인명, 죄명 등을 명시하여 부착명령 청구사건의 관할법원에 병합심리를 신청하여야 한다.', 6286);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10992, '① 법 제12조(법 제31조에 따라 준용되는 경우를 포함한다) 및 영 제28조제1항의 집행지휘는 별지 제5호서식의 부착명령 집행지휘서에 따른다. <개정 2010.7.15>', 6288);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10993, '② 검사는 부착명령과 병과된 형의 집행지휘서의 비고란에 "부착명령"이라고 붉은 색으로 적어야 한다.', 6288);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10994, '① 영 제12조제1항(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 신고는 별지 제9호서식의 신고서에 따른다. <개정 2013.5.31>', 6292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10995, '② 영 제12조제2항 및 제3항(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 허가 신청 및 허가는 각각 별지 제10호서식의 주거이전, 국내여행 또는 출국 허가신청서와 별지 제11호서식의 주거이전, 국내여행 또는 출국 허가서에 따른다. <개정 2013.5.31>', 6292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10996, '③ 영 제12조제7항(영 제18조의3, 제21조 및 제23조에 따라 준용되는 경우를 포함한다)의 통보요청은 별지 제12호서식의 출입국사실 통보 요청서에 따른다. <개정 2013.5.31>', 6292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10997, '① 법 제14조의2, 제14조의3 및 영 제12조의2에 따른 부착기간의 연장 또는 준수사항의 부과ㆍ추가ㆍ변경ㆍ삭제의 신청은 별지 제13호서식에 따른다.', 6293);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10998, '② 법 제14조의2 또는 제14조의3에 따른 부착기간의 연장 또는 준수사항의 부과ㆍ추가ㆍ변경ㆍ삭제의 청구는 별지 제14호서식에 따른다.', 6293);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (10999, '① 영 제13조제1항에 따라 치료 및 상담치료 등을 실시할 수 있는 시설 또는 단체로 지정을 받으려는 자(이하 "신청인"이라 한다)는 별지 제15호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정 신청서에 다음 각 호의 서류를 첨부하여 주소지를 관할하는 보호관찰소(지소를 포함한다. 이하 같다)의 장에게 제출해야 한다. <개정 2013.5.31, 2022.2.7, 2022.12.19>', 6294);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11000, '② 제1항에 따른 신청서를 받은 담당 공무원은 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 다음 각 호의 서류의 내용을 확인하여야 한다.', 6294);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11001, '③ 제1항에 따른 신청을 받은 경우 보호관찰소의 장은 신청일부터 14일 이내에 별지 제16호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정신청에 대한 의견서와 함께 신청인이 제출한 특정 범죄자 치료기관 또는 상담치료기관 지정 신청서와 첨부서류를 법무부장관에게 보내야 한다. <개정 2013.5.31>', 6294);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11002, '④ 법무부장관은 영 제13조제1항에 따라 신청인을 치료 및 상담치료 등을 실시할 수 있는 시설 또는 단체로 지정할 때에는 신청인에게 별지 제17호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정서를 발급하여야 한다. <개정 2013.5.31>', 6294);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11003, '⑤ 영 제13조제1항에 따른 지정을 받은 시설 또는 단체는 다음 각 호의 어느 하나에 해당하는 사항을 변경하려면 별지 제18호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정사항 변경신청서에 변경된 사항을 증명하는 서류 등을 첨부하여 주소지를 관할하는 보호관찰소의 장에게 제출하여야 한다. <개정 2013.5.31>', 6294);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11004, '⑥ 제5항에 따른 변경신청을 받은 경우 보호관찰소의 장은 변경신청일부터 14일 이내에 별지 제19호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정사항 변경신청에 대한 의견서와 변경신청을 한 시설 또는 단체가 제출한 특정 범죄자 치료기관 또는 상담치료기관 지정사항 변경신청서 및 첨부서류를 법무부장관에게 보내야 한다. <개정 2013.5.31>', 6294);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11005, '⑦ 법무부장관은 제5항에 따른 지정사항 변경신청이 적정하다고 판단되는 경우 변경내용이 기재된 제17호서식의 특정 범죄자 치료기관 또는 상담치료기관 지정서를 신청인에게 다시 발급하여야 한다. <개정 2013.5.31>', 6294);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11006, '⑧ 보호관찰소의 장은 법무부장관에게 영 제13조제1항에 따른 지정을 받은 시설 또는 단체의 시설이나 특정 범죄자 치료 및 교정 프로그램이 특정 범죄자의 치료ㆍ개선에 적당한지 여부와 그 운영실태를 정기적으로 보고하여야 한다.', 6294);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11007, '⑨ 법무부장관은 제8항에 따른 보고 결과 영 제13조제1항에 따른 지정을 받은 시설 또는 단체의 시설이나 특정 범죄자 치료 및 교정 프로그램이 특정 범죄자의 치료ㆍ개선에 부적당하다고 인정하면 지정을 취소할 수 있다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 지정을 취소하여야 한다. <개정 2013.5.31>', 6294);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11008, '① 보호관찰관은 법 제15조제3항에 따라 피부착자의 형 또는 치료감호 집행 중의 생활실태를 확인할 수 있는 자료를 요청하거나 피부착자를 면접하려는 경우에는 보호관찰소의 장을 통하여 교도소, 소년교도소, 구치소, 국립법무병원 및 군교도소의 장(이하 "교도소장등"이라 한다)에게 다음 사항을 적은 서면(전자문서를 포함한다)을 제출하여야 한다. <개정 2022.7.4>', 6295);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11009, '② 교도소장등은 제1항의 요청에 대하여 보호관찰소의 장에게 서면(전자문서를 포함한다)으로 회신하여야 한다. 다만, 생활실태 확인을 위한 자료는 「형사사법절차 전자화 촉진법」에 따른 형사사법정보시스템을 통하여 보호관찰소의 장에게 제공하는 방법으로 회신할 수 있다.', 6295);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11010, '③ 제1항에 따른 보호관찰관의 자료 또는 면접 요청은 별지 제20호서식에 따른다.', 6295);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11011, '④ 제2항 본문에 따른 교도소장등의 회신은 별지 제21호서식에 따른다.', 6295);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11012, '① 검사가 영 제14조의2제1항에 따라 수신자료의 열람ㆍ조회 허가청구를 하는 경우에는 별지 제23호서식에 따른다.', 6297);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11013, '② 사법경찰관이 영 제14조의2제2항에 따른 수신자료 열람ㆍ조회 허가신청을 하는 경우에는 별지 제24호서식에 따른다.', 6297);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11014, '③ 검사가 영 제14조의2제2항에 따라 사법경찰관으로부터 수신자료의 열람ㆍ조회 허가신청을 받아 수신자료 열람ㆍ조회 허가청구를 하는 경우에는 별지 제25호서식에 따른다.', 6297);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11015, '① 검사 또는 사법경찰관이 영 제14조의3제1항에 따라 보호관찰소의 장에게 긴급 수신자료 열람ㆍ조회를 요청하는 경우에는 별지 제26호서식에 따른다.', 6298);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11016, '② 영 제14조의3제2항에 따른 긴급 수신자료 열람 또는 조회의 허가청구는 별지 제27호서식에 따른다.', 6298);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11017, '③ 영 제14조의3제3항에 따른 긴급 수신자료 열람 또는 조회의 허가신청 및 허가청구는 각각 별지 제28호서식 및 별지 제29호서식에 따른다.', 6298);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11018, '① 검사 또는 사법경찰관은 법 제16조제4항 본문에 따라 수신자료를 열람 또는 조회한 때에는 별지 제30호서식의 수신자료 열람ㆍ조회 대장에 해당 사항을 적어야 하고, 법 제16조제4항 단서에 따라 수신자료를 열람 또는 조회한 때에는 별지 제31호서식의 긴급 수신자료 열람ㆍ조회 대장에 해당 사항을 적어야 한다.', 6299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11019, '② 보호관찰소의 장은 법 제16조제4항에 따라 수신자료를 열람 또는 조회하게 한 때에는 별지 제32호서식의 수신자료 열람ㆍ조회 접수 대장에 해당 사항을 적어야 한다.', 6299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11020, '③ 영 제14조의4제4항에 따른 검사 또는 사법경찰관의 수신자료 폐기사실의 통지는 별지 제33호서식에 따른다.', 6299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11021, '① 법 제16조의3제2항에 따라 피부착자에 관한 영상정보를 제공받은 위치추적 관제센터의 장은 같은 조 제3항에 따라 해당 영상정보의 열람이 종료된 날부터 30일 이내에 열람 사실을 해당 피부착자에게 통지해야 한다.', 6302);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11022, '② 제1항에 따른 통지는 휴대전화 문자전송, 전자우편, 팩스, 전화 또는 우편 등의 방법으로 한다.', 6302);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11023, '① 법 제21조의2에 따른 보호관찰명령의 청구는 별지 제38호서식에 따른다. 다만, 공소제기와 동시에 보호관찰명령을 청구하는 경우에는 별지 제39호서식의 공소장 및 보호관찰명령 청구서로 할 수 있다.', 6306);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11024, '② 검사가 공소를 제기한 후에 보호관찰명령을 청구하는 경우에는 보호관찰명령 청구사건과 병합심리할 피고사건의 법원명, 사건번호, 피고인명 및 죄명 등을 명시하여 보호관찰명령 청구사건의 관할 법원에 병합심리를 신청하여야 한다.', 6306);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11025, '① 법 제21조의3에 따라 선고된 보호관찰명령의 집행지휘는 별지 제40호서식의 보호관찰명령 집행지휘서에 따른다.', 6307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11026, '② 검사는 보호관찰명령과 병과된 형의 집행지휘서의 비고란에 "보호관찰명령"이라고 붉은 색으로 적어야 한다.', 6307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11027, '① 법 제22조제4항 및 제23조제2항에 따른 전자장치 부착대상자 통보는 별지 제43호서식의 전자장치 부착대상자 통보서에 따른다. <개정 2013.5.31, 2020.8.5>', 6310);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11028, '② 영 제19조의2제2항의 결정서는 별지 제44호서식에 따른다. <개정 2013.5.31, 2020.8.5>', 6310);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11029, '① 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제6호에 따른 구인영장의 청구와 신청은 각각 별지 제47호서식과 별지 제48호서식에 따른다. <개정 2013.5.31>', 6322);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11030, '② 보호관찰소의 장은 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제6호에 따라 검사에게 구인영장을 신청할 때에는 별지 제49호서식의 구인영장 신청부에 정해진 사항을 적어야 한다. <개정 2013.5.31, 2022.2.7>', 6322);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11031, '① 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제6호에 따른 구인영장은 별지 제50호서식에 따른다. <개정 2013.5.31>', 6323);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11032, '② 검사는 구인영장 위쪽에 집행을 지휘한다는 내용을 기재하고 서명 또는 기명날인의 방법으로 구인영장의 집행을 지휘할 수 있다.', 6323);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11033, '① 법 제13조제2항 및 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제10호에 따른 부착명령 집행장의 신청은 별지 제51호서식에 따른다. <개정 2013.5.31, 2018.2.2>', 6324);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11034, '② 법 제13조제2항 및 법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조제3항제10호에 따른 부착명령 집행장은 별지 제52호서식에 따른다. <개정 2013.5.31, 2018.2.2>', 6324);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11035, '① 이 법에서 사용하는 용어의 뜻은 다음과 같다. <개정 2011.9.15, 2023.12.29>', 6326);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11036, '② 다음 각 호의 어느 하나에 해당하는 경우에는 대상자를 제1항제3호가목에 따른 지배ㆍ관리하에 둔 것으로 본다.', 6326);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11037, '① 국가 및 지방자치단체는 성매매, 성매매알선 등 행위 및 성매매 목적의 인신매매를 예방하고 근절하기 위한 교육 및 홍보 등에 관하여 법적ㆍ제도적 대책을 마련하고, 필요한 재원(財源)을 조달하여야 한다.', 6327);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11038, '② 국가는 성매매 목적의 인신매매를 방지하기 위하여 국제협력의 증진과 형사사법의 공조(共助) 강화에 노력하여야 한다.', 6327);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11039, null, 6328);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11040, '① 성매매피해자의 성매매는 처벌하지 아니한다.', 6330);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11041, '② 검사 또는 사법경찰관은 수사과정에서 피의자 또는 참고인이 성매매피해자에 해당한다고 볼 만한 상당한 이유가 있을 때에는 지체 없이 법정대리인, 친족 또는 변호인에게 통지하고, 신변보호, 수사의 비공개, 친족 또는 지원시설ㆍ성매매피해상담소에의 인계 등 그 보호에 필요한 조치를 하여야 한다. 다만, 피의자 또는 참고인의 사생활 보호 등 부득이한 사유가 있는 경우에는 통지하지 아니할 수 있다.', 6330);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11042, '③ 법원 또는 수사기관이 이 법에 규정된 범죄를 신고(고소ㆍ고발을 포함한다. 이하 같다)한 사람 또는 성매매피해자(이하 "신고자등"이라 한다. 이하 같다)를 조사하거나 증인으로 신문(訊問)하는 경우에는 「특정범죄 신고자 등 보호법」 제7조부터 제13조까지의 규정을 준용한다. 이 경우 「특정범죄 신고자 등 보호법」 제9조와 제13조를 제외하고는 보복을 당할 우려가 있어야 한다는 요건이 필요하지 아니하다.', 6330);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11043, '① 「성매매방지 및 피해자보호 등에 관한 법률」 제5조제1항에 따른 지원시설 및 같은 법 제10조에 따른 성매매피해상담소의 장이나 종사자가 업무와 관련하여 성매매 피해사실을 알게 되었을 때에는 지체 없이 수사기관에 신고하여야 한다.', 6331);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11044, '② 누구든지 이 법에 규정된 범죄를 신고한 사람에게 그 신고를 이유로 불이익을 주어서는 아니 된다.', 6331);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11045, '③ 다른 법률에 규정이 있는 경우를 제외하고는 신고자등의 인적사항이나 사진 등 그 신원을 알 수 있는 정보나 자료를 인터넷 또는 출판물에 게재하거나 방송매체를 통하여 방송하여서는 아니 된다.', 6331);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11046, '① 법원은 신고자등을 증인으로 신문할 때에는 직권으로 또는 본인ㆍ법정대리인이나 검사의 신청에 의하여 신뢰관계에 있는 사람을 동석하게 할 수 있다.', 6332);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11047, '② 수사기관은 신고자등을 조사할 때에는 직권으로 또는 본인ㆍ법정대리인의 신청에 의하여 신뢰관계에 있는 사람을 동석하게 할 수 있다.', 6332);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11048, '③ 법원 또는 수사기관은 미성년자, 사물을 변별하거나 의사를 결정할 능력이 없거나 미약한 사람 또는 대통령령으로 정하는 중대한 장애가 있는 사람에 대하여 제1항 및 제2항에 따른 신청을 받은 경우에는 재판이나 수사에 지장을 줄 우려가 있는 등 특별한 사유가 없으면 신뢰관계에 있는 사람을 동석하게 하여야 한다. <개정 2023.12.29>', 6332);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11049, '④ 제1항부터 제3항까지의 규정에 따라 신문이나 조사에 동석하는 사람은 진술을 대리하거나 유도하는 등의 행위로 수사나 재판에 부당한 영향을 끼쳐서는 아니 된다.', 6332);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11050, '① 법원은 신고자등의 사생활이나 신변을 보호하기 위하여 필요하면 결정으로 심리를 공개하지 아니할 수 있다.', 6333);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11051, '② 증인으로 소환받은 신고자등과 그 가족은 사생활이나 신변을 보호하기 위하여 증인신문의 비공개를 신청할 수 있다.', 6333);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11052, '③ 재판장은 제2항에 따른 신청을 받으면 그 허가 여부, 법정 외의 장소에서의 신문 등 신문의 방식 및 장소에 관하여 결정할 수 있다.', 6333);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11053, '④ 제1항 및 제3항에 따른 심리의 비공개에 관하여는 「법원조직법」 제57조제2항 및 제3항을 준용한다.', 6333);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11054, '① 다음 각 호의 어느 하나에 해당하는 사람이 그 행위와 관련하여 성을 파는 행위를 하였거나 할 사람에게 가지는 채권은 그 계약의 형식이나 명목에 관계없이 무효로 한다. 그 채권을 양도하거나 그 채무를 인수한 경우에도 또한 같다.', 6334);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11055, '② 검사 또는 사법경찰관은 제1항의 불법원인과 관련된 것으로 의심되는 채무의 불이행을 이유로 고소ㆍ고발된 사건을 수사할 때에는 금품이나 그 밖의 재산상의 이익 제공이 성매매의 유인ㆍ강요 수단이나 성매매 업소로부터의 이탈방지 수단으로 이용되었는지를 확인하여 수사에 참작하여야 한다.', 6334);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11056, '③ 검사 또는 사법경찰관은 성을 파는 행위를 한 사람이나 성매매피해자를 조사할 때에는 제1항의 채권이 무효라는 사실과 지원시설 등을 이용할 수 있음을 본인 또는 법정대리인 등에게 고지하여야 한다.', 6334);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11057, '① 외국인여성이 이 법에 규정된 범죄를 신고한 경우나 외국인여성을 성매매피해자로 수사하는 경우에는 다음 각 호의 어느 하나에 해당하는 때까지 「출입국관리법」 제46조에 따른 강제퇴거명령 또는 같은 법 제51조에 따른 보호의 집행을 하여서는 아니 된다. 이 경우 수사기관은 지방출입국ㆍ외국인관서에 해당 외국인여성의 인적사항과 주거를 통보하는 등 출입국 관리에 필요한 조치를 하여야 한다. <개정 2014.3.18, 2021.3.16>', 6335);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11058, '② 검사는 제1항의 사건에 대하여 공소를 제기한 후에는 성매매피해 실태, 증언 또는 배상의 필요성, 그 밖의 정황을 고려하여 지방출입국ㆍ외국인관서의 장 등 관계 기관의 장에게 일정한 기간을 정하여 제1항에 따른 강제퇴거명령의 집행을 유예하거나 보호를 일시해제할 것을 요청할 수 있다. <개정 2014.3.18>', 6335);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11059, '③ 제1항 및 제2항에 따라 강제퇴거명령의 집행을 유예하거나 보호의 일시해제를 하는 기간에는 해당 외국인여성에게 지원시설 등을 이용하게 할 수 있다.', 6335);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11060, '④ 수사기관은 외국인여성을 성매매피해자로 조사할 때에는 「소송촉진 등에 관한 특례법」에 따른 배상신청을 할 수 있음을 고지하여야 한다.', 6335);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11061, '⑤ 성매매피해자인 외국인여성이 「소송촉진 등에 관한 특례법」에 따른 배상신청을 한 경우에는 그 배상명령이 확정될 때까지 제1항을 준용한다.', 6335);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11062, '① 검사는 성매매를 한 사람에 대하여 사건의 성격ㆍ동기, 행위자의 성행(性行) 등을 고려하여 이 법에 따른 보호처분을 하는 것이 적절하다고 인정할 때에는 특별한 사정이 없으면 보호사건으로 관할법원에 송치하여야 한다.', 6336);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11063, '② 법원은 성매매 사건의 심리 결과 이 법에 따른 보호처분을 하는 것이 적절하다고 인정할 때에는 결정으로 사건을 보호사건의 관할법원에 송치할 수 있다.', 6336);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11064, '① 이 법에서 정한 보호사건(이하 "보호사건"이라 한다)의 관할은 성매매를 한 장소나 성매매를 한 사람의 거주지 또는 현재지를 관할하는 가정법원으로 한다. 다만, 가정법원이 설치되어 있지 아니한 지역의 경우에는 해당 지역의 지방법원(지원을 포함한다. 이하 같다)으로 한다.', 6337);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11065, '② 보호사건의 심리와 결정은 단독판사가 한다.', 6337);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11066, '① 판사는 심리 결과 보호처분이 필요하다고 인정할 때에는 결정으로 다음 각 호의 어느 하나에 해당하는 처분을 할 수 있다.', 6338);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11067, '② 제1항 각 호의 처분은 병과(倂科)할 수 있다.', 6338);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11068, '③ 법원은 보호처분의 결정을 한 경우에는 지체 없이 검사, 보호처분을 받은 사람, 보호관찰관 또는 보호처분을 위탁받아 행하는 지원시설ㆍ성매매피해상담소 또는 의료기관(이하 "수탁기관"이라 한다)의 장에게 통지하여야 한다. 다만, 국가가 운영하지 아니하는 수탁기관에 보호처분을 위탁할 때에는 그 기관의 장으로부터 수탁에 대한 동의를 받아야 한다.', 6338);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11069, '④ 법원은 제1항제2호부터 제5호까지의 처분을 한 경우에는 교육, 상담, 치료 또는 보호관찰에 필요한 자료를 보호관찰관 또는 수탁기관의 장에게 송부하여야 한다.', 6338);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11070, '⑤ 보호관찰, 사회봉사ㆍ수강명령에 관하여 이 법에서 정한 사항 외의 사항에 관하여는 「보호관찰 등에 관한 법률」을 준용한다.', 6338);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11071, '① 법원은 검사, 보호관찰관 또는 수탁기관의 장이 청구하면 결정으로 한 번만 보호처분의 종류와 기간을 변경할 수 있다.', 6340);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11072, '② 제1항에 따라 보호처분의 종류와 기간을 변경할 때에는 종전의 처분기간을 합산하여 제14조제1항제1호ㆍ제2호ㆍ제4호ㆍ제5호에 따른 보호처분 기간은 1년을, 같은 항 제3호에 따른 사회봉사ㆍ수강명령은 200시간을 각각 초과할 수 없다.', 6340);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11073, '① 성매매 사건의 보호처분에 관하여 이 법에서 정하지 아니한 사항에 대하여는 「가정폭력범죄의 처벌 등에 관한 특례법」 제13조부터 제17조까지, 제19조부터 제28조까지, 제30조, 제31조, 제32조제1항, 제34조부터 제38조까지, 제43조, 제44조 및 제46조부터 제54조까지의 규정을 준용하되, "가정폭력범죄"는 "성매매"로, "가정보호사건"은 "보호사건"으로 본다. 다만, 임시조치, 피해자 또는 법정대리인의 권리에 관한 조항 등 성질상 성매매 사건에 적용할 수 없는 규정은 준용하지 아니한다.', 6341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11074, '② 이 법에서 규정한 사항 외에 보호사건의 조사와 심리에 필요한 사항은 대법원규칙으로 정한다.', 6341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11075, '① 다음 각 호의 어느 하나에 해당하는 사람은 10년 이하의 징역 또는 1억원 이하의 벌금에 처한다.', 6342);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11076, '② 다음 각 호의 어느 하나에 해당하는 사람은 1년 이상의 유기징역에 처한다. <개정 2023.12.29>', 6342);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11077, '③ 다음 각 호의 어느 하나에 해당하는 사람은 3년 이상의 유기징역에 처한다.', 6342);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11078, '④ 다음 각 호의 어느 하나에 해당하는 사람은 5년 이상의 유기징역에 처한다.', 6342);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11079, '① 다음 각 호의 어느 하나에 해당하는 사람은 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.', 6343);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11080, '② 다음 각 호의 어느 하나에 해당하는 사람은 7년 이하의 징역 또는 7천만원 이하의 벌금에 처한다.', 6343);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11081, '① 다음 각 호의 어느 하나에 해당하는 사람은 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.', 6344);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11082, '② 영업으로 제1항에 따른 광고물을 제작ㆍ공급하거나 광고를 게재한 사람은 2년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 6344);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11083, '③ 영업으로 제1항에 따른 광고물이나 광고가 게재된 출판물을 배포한 사람은 1년 이하의 징역 또는 500만원 이하의 벌금에 처한다.', 6344);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11084, '① 성매매를 한 사람은 1년 이하의 징역이나 300만원 이하의 벌금ㆍ구류 또는 과료(科料)에 처한다.', 6345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11085, '② 제7조제3항을 위반한 사람은 500만원 이하의 벌금에 처한다.', 6345);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11086, '① 제18조제2항제3호, 같은 조 제3항제4호, 같은 조 제4항, 제22조의 범죄 및 성매매 목적의 인신매매의 범죄를 수사기관에 신고한 사람에게는 보상금을 지급할 수 있다. <개정 2013.4.5>', 6352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11087, '② 제1항에 따른 보상금의 지급 기준 및 범위에 관하여 필요한 사항은 대통령령으로 정한다.', 6352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11088, '①법 제28조의 규정에 의하여 신고(고소ㆍ고발을 포함한다. 이하 같다)에 대한 보상금(이하 "보상금"이라 한다)을 지급받고자 하는 사람은 법무부령이 정하는 바에 의하여 보상금지급신청서를 관할 지방검찰청검사장(지방검찰청 지청장을 포함한다. 이하 같다)에게 제출하여야 한다.', 6357);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11089, '②제1항의 규정에 의한 신청은 「민원 처리에 관한 법률 시행령」 제2조제1항제3호에도 불구하고 익명 또는 가명으로 할 수 있다. 이 경우 그 사유에 관하여 신고를 접수한 기관의 장의 확인이 있어야 한다. <개정 2016.2.12>', 6357);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11090, '③제1항의 규정에 의한 신청은 제6조제1항의 규정에 의한 보상금지급사유가 발생하였음을 안 날부터 1년 이내에 하여야 한다.', 6357);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11091, '④지방검찰청검사장은 제1항의 규정에 의한 신청서를 접수한 때에는 법무부령이 정하는 서류를 첨부하여 검찰총장을 경유하여 법무부장관에게 제출하여야 한다.', 6357);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11092, '①보상금은 신고가 접수된 범죄에 대하여 공소가 제기되거나 기소유예처분이 된 경우에 지급할 수 있다. 다만, 피의자를 검거하지 못하는 등으로 공소가 제기되지 아니한 경우에도 신고로 인하여 범죄의 주요 증거가 확보되거나 피해자 구조에 현저히 기여한 때에는 보상금을 지급할 수 있다.', 6358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11093, '②보상금은 최고 2천만원 이내로 하여 그 지급결정이 있은 당해연도 예산의 범위안에서 지급하되, 그 구체적인 지급기준은 법무부령으로 정한다.', 6358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11094, '③법무부장관은 보상금 지급사무의 일부를 검찰총장 또는 지방검찰청 검사장에게 위임할 수 있다.', 6358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11095, null, 6360);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11096, '①「성매매알선 등 행위의 처벌에 관한 법률」(이하 "법"이라 한다) 제28조에 따른 신고(고소ㆍ고발을 포함한다. 이하 같다)에 대한 보상금(이하 "보상금"이라 한다)은 그 지급대상자가 해당 사건의 해결에 기여한 공로, 신고로 인한 경제적 손실, 신고대상이 된 범죄에의 관여 여부 등 여러 정황을 참작하여 공정하게 지급하여야 한다. <개정 2011.1.25>', 6364);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11097, '②보상금은 동일한 공로에 대하여 중복하여 지급할 수 없다.', 6364);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11098, '①성매매알선등행위의처벌에관한법률시행령(이하 "영"이라 한다) 제5조제1항의 규정에 의하여 보상금의 지급신청을 하고자 하는 자는 별지 제1호서식에 의한 보상금지급신청서를 관할 지방검찰청 검사장(지청장을 포함한다. 이하 같다)에게 제출하여야 한다.', 6366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11099, '②지방검찰청 검사장은 제1항의 규정에 의한 보상금지급신청서를 접수한 때에는 다음 각호의 서류를 첨부하여 매년 2월과 8월에 일괄하여 검찰총장을 거쳐 법무부장관에게 송부하여야 한다.', 6366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11100, '③지방검찰청 검사장 또는 검찰총장은 접수된 보상금지급신청서를 심사한 결과 흠이 있거나 증빙이 부족하다고 판단되는 때에는 그에 대한 보완을 요구할 수 있고, 보상금 지급액의 산정에 관한 의견을 첨부할 수 있다.', 6366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11101, '①영 제5조제2항 전단의 규정에 의하여 익명 또는 가명으로 보상금의 지급을 신청하는 경우에는 당해 사건의 담당검사의 승인을 얻어야 한다.', 6367);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11102, '②제1항의 규정에 의하여 익명으로 보상금의 지급을 신청하는 경우에는 신청인을 당해 사건의 담당검사로 기재하되, 익명임을 표시하여야 한다.', 6367);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11103, '③제1항의 규정에 의한 담당검사의 승인 및 영 제5조제2항 후단의 규정에 의한 신고를 접수한 기관의 장의 확인은 별지 제1호서식 하단에 의한다.', 6367);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11104, null, 6371);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11105, '① 보상금은 법 제28조제1항에 따라 보상금 지급대상이 되는 범죄(이하 "대상범죄"라 한다)에 대하여 신고를 한 경우에 다음 각 호에서 정한 보상금 상한액의 범위에서 지급한다. <개정 2011.1.25>', 6375);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11106, '②제1항의 규정에 의하여 보상금 액수를 결정함에 있어서 다음 각호의 사항을 참작하여야 한다.', 6375);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11107, '③당해 사건의 해결이 국내외적으로 중요하거나 대형범죄, 조직범죄의 근절 등 범죄진압에 현저히 기여한 경우에는 2천만원을 초과하지 아니하는 범위안에서 제1항의 규정에 의한 지급기준보다 보상금을 증액하여 지급할 수 있다.', 6375);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11108, '④ 삭제 <2011.1.25>', 6375);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11109, '① 삭제 <2011.1.25>', 6377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11110, '②법무부장관은 보상금 지급결정을 한 경우 별지 제4호서식의 보상금지급결정서를 작성하여야 한다. <개정 2011.1.25>', 6377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11111, '①제15조제2항의 규정에 의한 보상금지급결정서는 검찰총장을 거쳐 관할 지방검찰청 검사장에게 송부하고, 지방검찰청 검사장은 신청인에게 지체없이 지급결정 사실을 통보하여야 한다.', 6378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11112, '②보상금은 관할 지방검찰청 검사장이 신청인에게 지급하되, 익명으로 보상금지급신청서가 제출되어 지급결정된 경우에는 신청한 검사가 수령하여 대상자에게 지급한다.', 6378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11113, '①법무부장관은 지방검찰청 검사장으로부터 신고를 한 자에 대한 보상이 시급하다는 이유로 보상금의 가지급 요청이 있는 때에는 검찰총장의 의견을 참작하여 당해 사건의 종국처분 이전이라도 전년도 지급기준에 의한 예상 보상금 액수의 10분의 8의 범위안에서 보상금을 가지급할 수 있다. 이 경우 별지 각 서식에 준하여 가지급 관련 서류를 작성하되, 가지급금인 사실과 예상보상금 액수, 가지급을 필요로 하는 사유를 기재하여야 한다.', 6379);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11114, '②법무부장관은 보상금 지급사무의 적정을 기하기 위하여 필요하다고 인정하는 때에는 지방검찰청 검사장 및 검찰총장의 의견을 참작하여 판결이 확정될 때까지 그 지급여부 및 보상금 지급액의 결정을 유예할 수 있다. <개정 2011.1.25>', 6379);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11115, '①법무부장관은 지방검찰청 검사장으로 하여금 영 제10조의 규정에 의한 보상금지급조서 및 보상금지급대장을 각각 별지 제5호서식 및 별지 제6호서식에 의하여 작성ㆍ비치하도록 할 수 있다.', 6380);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11116, '②보상금지급조서 및 보상금지급대장에는 수령인이 작성한 영수증이나 보상금을 송금한 예금통장 사본 등 지급 근거 서류를 첨부하여 보존하여야 한다.', 6380);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11117, '①제5조제1항의 규정에 의하여 익명 또는 가명으로 보상금이 신청된 경우에는 그 공로조서, 보상금지급심의서, 보상금지급결정서에는 익명 또는 가명을 기재하고, 주민등록번호 및 주소 등 인적사항을 확인할 수 있는 내용을 기재하여서는 아니된다.', 6381);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11118, '②보상금지급조서 및 보상금지급대장에는 신청인의 실명을 기재하되, 보상금지급신청서에 기재된 익명 또는 가명을 부기하여야 한다.', 6381);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11119, null, 6383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11120, '① 국방부장관은 군수형자에 대한 형의 집행에 관한 사무를 관장하기 위하여 군교도소(이하 "교도소"라 한다)를 설치ㆍ운영하고, 필요하다고 인정하는 경우 교도소에 지소를 설치ㆍ운영할 수 있다. <개정 2014.5.20>', 6385);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11121, '② 국방부장관은 군미결수용자를 수용하기 위하여 교도소와 대통령령으로 정하는 부대에 군미결수용실(이하 "미결수용실"이라 한다)을 설치ㆍ운영할 수 있다. <개정 2014.5.20>', 6385);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11122, '③ 삭제 <2014.5.20>', 6385);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11123, '④ 삭제 <2014.5.20>', 6385);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11124, '① 군판사와 군검사는 직무상 필요하면 군교정시설을 시찰할 수 있다. <개정 2016.1.6>', 6389);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11125, '② 군판사와 군검사 외의 사람은 군교정시설을 참관하려면 학술연구 등 정당한 사유를 구체적으로 밝혀 소장의 허가를 받아야 한다. <개정 2016.1.6>', 6389);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11126, '③ 제1항 및 제2항에 따른 시찰 및 참관에 관하여 필요한 사항은 대통령령으로 정한다.', 6389);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11127, null, 6391);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11128, '① 다음 각 호의 어느 하나에 해당하면 교도소에 군미결수용자를 수용할 수 있다.', 6392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11129, '② 미결수용실이 설치된 부대의 장은 특별한 사정이 있을 때에는 교도소로 이송(移送)하여야 할 군수형자를 3개월을 초과하지 아니하는 범위에서 계속하여 수용할 수 있다.', 6392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11130, '① 남성과 여성은 분리하여 수용한다.', 6393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11131, '② 군수형자와 군미결수용자를 같은 군교정시설에 수용할 때에는 서로 분리하여 수용한다.', 6393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11132, '① 군수용자는 독거수용한다. 다만, 다음 각 호의 어느 하나에 해당하면 혼거(混居)수용할 수 있다.', 6394);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11133, '② 제1항에서 규정한 사항 외에 독거수용의 구분 등 독거수용에 관하여 필요한 사항은 대통령령으로 정한다.', 6394);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11134, '① 혼거수용하는 경우에는 다음 각 호의 구분에 따라 거실(居室)을 구분하여 수용한다. 다만, 군수용자의 죄질ㆍ성격ㆍ범죄전력ㆍ나이ㆍ경력 및 수용생활 태도, 그 밖에 군수용자의 개인적 특성을 고려하여 거실을 별도로 구분하여 수용할 수 있다. <개정 2017.3.21>', 6395);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11135, '② 제1항에서 규정한 사항 외에 혼거수용 인원의 기준, 혼거수용의 제한 등에 관하여 필요한 사항은 대통령령으로 정한다.', 6395);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11136, '① 소장은 군수용자로서 군교정시설에 처음으로 수용되는 사람(이하 "신입자"라 한다)에 대하여는 집행지휘서, 재판서, 그 밖에 수용에 필요한 서류를 조사한 후 수용한다.', 6396);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11137, '② 소장은 대통령령으로 정하는 바에 따라 신입자에게 군의관이 실시하는 건강진단을 받게 하여야 한다.', 6396);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11138, '① 소장은 다른 사람의 건강에 위해(危害)를 끼칠 우려가 있는 감염병(「감염병의 예방 및 관리에 관한 법률」 제2조제1호에 따른 감염병을 말한다. 이하 같다)에 걸린 사람이 있으면, 지체 없이 수용지휘기관과 관할 보건소장에게 통보하고 국방부장관에게 보고한 후 국방부장관의 조치에 따라 수용을 중단할 수 있다. <개정 2009.12.29>', 6397);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11139, '② 제1항에 따라 보고를 받은 국방부장관은 지체 없이 「감염병의 예방 및 관리에 관한 법률」에서 정하는 바에 따라 필요한 조치를 하여야 한다. 이 경우 군교정시설이 아닌 곳에 수용된 사람에 대하여는 제38조제2항 및 제3항을 준용한다. <개정 2009.12.29>', 6397);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11140, null, 6398);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11141, '① 소장은 신입자와 다른 군교정시설에서 이송되어 온 사람을 식별하기 위하여 필요한 한도에서 사진촬영, 지문채취, 군수용자 번호지정, 그 밖에 대통령령으로 정하는 조치를 하여야 한다.', 6399);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11142, '② 소장은 수용목적상 필요하면 수용 중인 사람에 대하여도 제1항의 조치를 할 수 있다.', 6399);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11143, '① 국방부장관은 필요하면 법무부장관의 동의를 받아 군수용자를 일반교도소나 구치소에 수용할 수 있다. 다만, 여성 군수용자는 특별한 사유가 없으면 일반교도소나 구치소에 수용하여야 한다.', 6401);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11144, '② 제1항에 따라 일반교도소나 구치소에 수용된 군수용자에게는 「형의 집행 및 수용자의 처우에 관한 법률」을 적용한다.', 6401);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11145, '① 소장은 군수용자의 건강, 계절 등을 고려하여 군수용자에게 건강 유지에 적합한 의류ㆍ침구, 그 밖의 생활용품을 지급한다.', 6403);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11146, '② 제1항에 따른 의류ㆍ침구, 그 밖의 생활용품의 지급기준 등에 관하여 필요한 사항은 국방부령으로 정한다.', 6403);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11147, '① 소장은 군수용자에게 건강상태, 나이, 부과된 작업의 종류, 그 밖의 개인적 특성을 고려하여 건강 및 체력을 유지하는 데에 필요한 음식물을 지급한다.', 6404);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11148, '② 제1항에 따라 지급하는 음식물의 구분 및 지급 방법 등에 관하여 필요한 사항은 대통령령으로 정하고, 구체적인 음식물의 지급기준 등에 관하여 필요한 사항은 국방부령으로 정한다.', 6404);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11149, '① 군수용자는 소장의 허가를 받아 자신의 비용으로 음식물ㆍ의류ㆍ침구, 그 밖에 수용생활에 필요한 물품을 구매할 수 있다.', 6405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11150, '② 제1항에 따른 물품의 자비구매 허가의 기준에 관한 사항은 대통령령으로 정하고, 자비구매 물품의 종류, 공급 및 검수 등에 관한 사항은 국방부령으로 정한다.', 6405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11151, '① 소장은 군수용자의 휴대금품(군수용자가 군교정시설에 수용될 때 지니고 있는 현금ㆍ자기앞수표, 그 밖의 휴대품을 말한다. 이하 같다)을 군교정시설에 영치(領置)한다. 다만, 휴대품이 다음 각 호의 어느 하나에 해당하는 것이면 군수용자로 하여금 자신이 지정하는 사람에게 보내게 하거나 그 밖의 적당한 방법으로 처분하게 할 수 있다.', 6406);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11152, '② 소장은 군수용자가 제1항 단서에 따라 처분하여야 할 휴대품을 상당한 기간 내에 처분하지 아니하면 폐기할 수 있다.', 6406);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11153, '③ 군수용자 휴대금품의 영치ㆍ사용, 영치의 예외 등에 관하여 필요한 사항은 대통령령으로 정한다.', 6406);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11154, '① 군수용자는 서신ㆍ도서, 그 밖에 수용생활에 필요한 물품을 국방부장관이 정하는 범위에서 소지할 수 있다.', 6407);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11155, '② 소장은 제1항에 따른 소지범위를 벗어난 물품으로서 특별히 군교정시설에 영치할 필요가 있다고 인정하지 아니하는 물품은 군수용자로 하여금 자신이 지정하는 사람에게 보내게 하거나 그 밖의 적당한 방법으로 처분하게 할 수 있다.', 6407);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11156, '③ 소장은 군수용자가 제2항에 따라 처분하여야 할 물품을 상당한 기간 내에 처분하지 아니하면 폐기할 수 있다.', 6407);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11157, '① 군수용자 외의 사람이 군수용자에게 금품을 교부하려고 신청하면 소장은 다음 각 호의 어느 하나에 해당할 때를 제외하고는 이를 허가하여야 한다.', 6408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11158, '② 소장은 제1항에 따라 교부를 허가한 금품을 대통령령으로 정하는 바에 따라 검사한 후 군수용자에게 사용하게 하여야 한다.', 6408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11159, '③ 소장은 군수용자에게 보내온 금품을 본인이 받기를 거부하거나 제1항 각 호의 어느 하나에 해당하면 보낸 사람에게 돌려보내야 한다.', 6408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11160, '④ 소장은 제3항의 경우에 금품을 보낸 사람을 알 수 없거나 보낸 사람의 주소가 분명하지 아니할 때에는 그 사실을 공고하여야 하고, 공고한 날부터 6개월이 지나도 금품 교부를 청구하는 사람이 없으면 그 금품은 국고에 귀속된다.', 6408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11161, '⑤ 소장은 제3항이나 제4항에 따른 조치를 하였으면 그 사실을 군수용자에게 알려주어야 한다.', 6408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11162, '⑥ 제1항부터 제5항까지에서 규정한 사항 외에 군수용자에 대한 금품 교부의 허가에 관하여 필요한 사항은 국방부령으로 정한다.', 6408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11163, '① 소장은 사망자나 도주자가 남겨둔 금품이 있으면 사망자의 상속인이나 도주자의 가족에게 그 내용 및 교부 청구절차 등을 알려주어야 한다. 다만, 부패하거나 없어질 우려가 있는 것은 폐기할 수 있다.', 6409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11164, '② 소장은 상속인이나 가족이 제1항의 금품을 청구하면 지체 없이 교부하여야 한다. 다만, 제1항에 따른 고지를 받은 날(알려줄 수가 없는 경우에는 청구사유가 발생한 날을 말한다)부터 1년이 지나도 청구하지 아니하면 그 금품은 국고에 귀속된다.', 6409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11165, '③ 소장은 제2항 본문에도 불구하고 제1항의 금품을 그대로 교부하기 어려운 특별한 사정이 있으면 그 금품을 팔아 대가를 상속인이나 가족에게 교부할 수 있다.', 6409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11166, '① 군수용자는 자신의 신체와 의류를 청결히 하여야 하고, 자신이 사용하는 거실ㆍ작업장, 그 밖의 수용시설의 청결 유지에 협력하여야 한다.', 6414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11167, '② 군수용자는 위생을 위하여 머리나 수염을 단정하게 하여야 한다.', 6414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11168, '① 소장은 군수용자가 건강 유지에 필요한 운동과 목욕을 정기적으로 할 수 있도록 하여야 한다.', 6415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11169, '② 제1항에 따른 운동시간, 목욕횟수 등에 관하여 필요한 사항은 대통령령으로 정한다.', 6415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11170, '① 소장은 군수용자에 대하여 건강검진을 정기적으로 실시하여야 한다.', 6416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11171, '② 제1항에 따른 건강검진의 횟수 등에 관하여 필요한 사항은 대통령령으로 정한다.', 6416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11172, '① 소장은 감염병이나 그 밖에 전염 또는 감염의 우려가 있는 질병의 발생과 확산을 방지하기 위하여 필요하다고 인정하면 군수용자에 대하여 예방접종, 격리수용, 이송, 그 밖에 필요한 조치를 하여야 한다. <개정 2009.12.29>', 6417);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11173, '② 제1항에 따른 소장의 조치에 관하여 필요한 사항은 대통령령으로 정한다.', 6417);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11174, '① 소장은 군수용자에 대한 적절한 치료를 위하여 필요하다고 인정하면 군수용자를 군병원이나 군병원이 아닌 의료시설(이하 "외부의료시설"이라 한다)에서 진료를 받게 할 수 있다.', 6419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11175, '② 제1항에 따라 군병원이나 외부의료시설에서 진료를 받게 된 사람은 군수용자에 준하여 처우한다.', 6419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11176, '③ 소장은 제1항에 따라 군수용자가 군병원이나 외부의료시설에서 진료를 받게 되면 그 사실을 그 가족(가족이 없을 때에는 군수용자가 지정하는 사람을 말한다)에게 지체 없이 통지하여야 한다. 다만, 군수용자가 통지를 원하지 아니하면 그러하지 아니하다.', 6419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11177, '④ 소장은 군수용자가 자신의 고의 또는 중대한 과실로 부상 등을 입어 외부의료시설에서 진료를 받았을 때에는 그 진료비의 전부 또는 일부를 그 군수용자에게 부담시킬 수 있다.', 6419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11178, '① 군교정시설에는 군수용자의 진료를 위하여 필요한 의료 인력과 설비를 갖추어야 한다.', 6421);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11179, '② 소장은 정신질환이 있다고 의심되는 군수용자가 있으면 정신건강의학과 군의관의 진료를 받게 하여야 한다. <개정 2011.8.4>', 6421);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11180, '③ 외부의사는 군수용자를 진료할 때에는 국방부장관이 정하는 사항을 준수하여야 한다.', 6421);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11181, '① 소장은 군수용자가 진료나 음식물의 섭취를 거부하면 군의관으로 하여금 관찰ㆍ조언 또는 설득을 하게 하여야 한다.', 6422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11182, '② 소장은 제1항의 조치에도 불구하고 군수용자가 진료나 음식물의 섭취를 계속 거부하여 그 생명에 위험을 가져올 급박한 우려가 있으면 군의관으로 하여금 적당한 진료나 영양보급 등의 조치를 하게 할 수 있다.', 6422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11183, '① 군수용자는 군교정시설의 외부에 있는 사람과 접견할 수 있다. 다만, 다음 각 호의 어느 하나에 해당하면 그러하지 아니하다.', 6423);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11184, '② 소장은 다음 각 호의 어느 하나에 해당하면 교도관으로 하여금 군수용자의 접견내용을 청취ㆍ기록ㆍ녹음 또는 녹화하게 할 수 있다. 이 경우 접견을 하는 군수용자와 군수용자가 아닌 사람은 국어로 의사소통을 하기 어려운 사정이 있는 경우 외에는 외국어를 사용하여서는 아니 된다.', 6423);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11185, '③ 제2항에 따라 녹음ㆍ녹화하는 경우에는 미리 군수용자와 그 상대방에게 그 사실을 알려주어야 한다.', 6423);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11186, '④ 군수용자의 구분에 따른 접견의 횟수ㆍ시간ㆍ장소ㆍ방법 및 제2항에 따른 접견내용의 청취ㆍ기록ㆍ녹음ㆍ녹화, 접견기록물 등의 관리 등에 관하여 필요한 사항은 대통령령으로 정한다.', 6423);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11187, null, 6424);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11188, '① 군수용자는 다른 사람에게 서신을 보내거나 다른 사람으로부터 서신을 받을 수 있다. 다만, 다음 각 호의 어느 하나에 해당하면 그러하지 아니하다.', 6425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11189, '② 제1항 본문에도 불구하고 같은 군교정시설에 수용되어 있는 군수용자 사이에 서신을 주고받으려면 소장의 허가를 받아야 한다.', 6425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11190, '③ 소장은 군수용자가 주고받는 서신에 법령에서 금지한 물품이 들어 있는지 확인할 수 있다.', 6425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11191, '④ 군수용자가 주고받는 서신의 내용은 검열받지 아니한다. 다만, 다음 각 호의 어느 하나에 해당하면 그러하지 아니하다.', 6425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11192, '⑤ 소장은 제3항 또는 제4항 단서에 따라 확인하거나 검열한 결과 군수용자의 서신에 법령에서 금지한 물품이 들어 있거나 서신의 내용이 다음 각 호의 어느 하나에 해당하면 그 서신을 보내거나 받는 것을 금지할 수 있다.', 6425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11193, '⑥ 소장은 제3항에 따라 확인을 하거나 제4항 단서에 따라 검열을 한 뒤 그 서신이 제1항 각 호 또는 제5항 각 호의 어느 하나에 해당하지 아니하는 경우에는 지체 없이 군수용자의 서신을 발송하거나 교부하여야 한다.', 6425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11194, '⑦ 소장은 제1항 단서 또는 제5항에 따라 보내거나 받는 것이 금지된 서신은 군수용자에게 그 사유를 알린 후 군교정시설에 영치한다. 다만, 군수용자가 동의하면 폐기할 수 있다.', 6425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11195, '⑧ 제1항부터 제5항까지의 규정에 따른 서신 발송의 횟수, 서신 내용물의 확인방법 및 서신 내용의 검열절차 등에 관하여 필요한 사항은 대통령령으로 정한다.', 6425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11196, '① 군수용자는 소장의 허가를 받아 군교정시설의 외부에 있는 사람과 전화통화를 할 수 있다.', 6426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11197, '② 제1항에 따른 허가에는 통화내용의 청취 또는 녹음을 조건으로 붙일 수 있다.', 6426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11198, '③ 군수용자의 전화통화에 관하여는 제42조제2항 후단 및 제43조를 준용한다.', 6426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11199, '④ 제2항에 따라 통화내용을 청취하거나 녹음하려면 미리 군수용자 와 상대방에게 그 사실을 알려주어야 한다.', 6426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11200, '⑤ 제1항과 제2항에 따른 전화통화의 허가범위, 통화내용의 청취ㆍ녹음 등에 관하여 필요한 사항은 대통령령으로 정한다.', 6426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11201, '① 군수용자는 군교정시설에서 실시되는 종교의식이나 행사에 참석할 수 있으며, 개별적인 종교상담을 받을 수 있다.', 6427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11202, '② 군수용자는 자신의 신앙생활에 필요한 서적이나 물품을 소지할 수 있다.', 6427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11203, '③ 소장은 다음 각 호의 어느 하나에 해당하면 제1항과 제2항에서 규정하고 있는 사항을 제한할 수 있다.', 6427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11204, '④ 제1항부터 제3항까지의 규정에 따라 군수용시설에서 실시하는 종교행사의 종류와 참석 대상ㆍ방법, 종교상담의 대상ㆍ방법 및 종교 서적ㆍ물품의 소지범위 등에 관하여 필요한 사항은 국방부령으로 정한다.', 6427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11205, '① 군수용자는 자신의 비용으로 신문ㆍ잡지 또는 도서(이하 "신문등"이라 한다)의 구독을 신청할 수 있다.', 6429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11206, '② 소장은 제1항에 따라 구독을 신청한 신문등이 「출판문화산업 진흥법」에 따른 유해간행물인 경우를 제외하고는 구독을 허가하여야 한다.', 6429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11207, '③ 제1항에 따라 구독을 신청할 수 있는 신문등의 범위와 수량, 구독허가의 취소 등에 관하여 필요한 사항은 국방부령으로 정한다.', 6429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11208, '① 군수용자는 정서 안정과 교양 습득을 위하여 대통령령으로 정하는 바에 따라 라디오 청취와 텔레비전 시청을 할 수 있다.', 6430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11209, '② 소장은 다음 각 호의 어느 하나에 해당하면 군수용자에 대하여 라디오 청취 및 텔레비전 시청을 일시 중단시키거나 개별 군수용자에 대하여 라디오 청취 또는 텔레비전 시청을 금지할 수 있다.', 6430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11210, '③ 제1항 및 제2항에 따른 방송설비, 방송프로그램, 방송시간 등에 관하여 필요한 사항은 국방부령으로 정한다.', 6430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11211, '① 군수용자는 문서나 도화를 작성하거나 문예ㆍ학술, 그 밖의 사항에 관하여 집필할 수 있다. 다만, 소장이 시설의 안전이나 질서를 해칠 명백한 위험이 있다고 인정하는 경우에는 그러하지 아니하다.', 6431);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11212, '② 제1항에 따라 작성 또는 집필한 문서나 도화의 소지와 처분에 관하여는 제26조를 준용한다.', 6431);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11213, '③ 제1항에 따라 작성 또는 집필한 문서나 도화가 제44조제5항 각 호의 어느 하나에 해당하는 경우에는 같은 조 제7항을 준용한다.', 6431);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11214, '④ 제1항부터 제3항까지의 규정에 따른 집필용구의 관리, 집필의 시간ㆍ장소, 집필한 문서 또는 도화의 외부반출 등에 관하여 필요한 사항은 대통령령으로 정한다.', 6431);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11215, '① 군수형자에 대하여는 교육, 교화프로그램, 작업, 직업훈련 등을 통하여 교정ㆍ교화를 도모하고 사회생활에 적응하는 능력을 기르도록 처우하여야 한다.', 6432);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11216, '② 소장은 국방부령으로 정하는 바에 따라 군수형자의 인성, 행동 특성 및 자질, 뉘우침의 정도, 상벌 실적, 작업 실적 및 교육ㆍ훈련 실적 등을 측정ㆍ평가하고, 그 결과를 군수형자의 처우에 반영할 수 있다.', 6432);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11217, '① 소장은 군수형자가 건전한 사회복귀에 필요한 지식과 소양을 습득하도록 교육할 수 있다.', 6434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11218, '② 소장은 제1항에 따른 교육을 위하여 필요하면 군수형자를 외부의 교육기관에 통학하게 하거나 위탁하여 교육받게 할 수 있다.', 6434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11219, '③ 교육대상자인 군수형자는 교육과 관련된 관계 법령, 학칙 및 소장이 정하는 교육관리지침 등을 성실하게 준수하여야 한다.', 6434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11220, '④ 제1항 및 제2항에 따른 교육대상자의 선발 및 선발 취소, 교육과정, 외부통학, 위탁교육 등에 관하여 필요한 사항은 국방부령으로 정한다.', 6434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11221, '① 소장은 군수형자의 교정ㆍ교화를 위하여 상담ㆍ심리치료, 그 밖의 교화프로그램을 실시하여야 한다.', 6435);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11222, '② 제1항에 따른 교화프로그램의 종류ㆍ내용 등에 관하여 필요한 사항은 국방부령으로 정한다.', 6435);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11223, '① 군수형자에게 부과하는 작업은 건전한 사회복귀를 위하여 기술을 습득하고, 근로의욕을 고취하는 데에 적합하여야 한다.', 6436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11224, '② 소장은 군수형자에게 작업을 부과하려면 나이ㆍ형기ㆍ건강상태ㆍ기술ㆍ성격ㆍ취미ㆍ경력ㆍ장래생계, 그 밖의 군수형자의 사정을 고려하여야 한다.', 6436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11225, '① 소장은 군수형자의 건전한 사회복귀와 기술 습득을 촉진하기 위하여 필요하면 군수형자를 외부기업체 등에 통근하며 작업하게 할 수 있다.', 6439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11226, '② 제1항에 따른 외부 통근 작업 대상자 및 외부기업체 등의 선정기준, 선정 취소 등에 관하여 필요한 사항은 국방부령으로 정하고, 그 밖에 외부 통근 작업의 운영에 관하여 필요한 사항은 국방부장관이 정한다.', 6439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11227, '① 소장은 군수형자의 건전한 사회복귀를 위하여 기술 습득 및 향상을 위한 직업능력개발훈련(이하 "직업훈련"이라 한다)을 실시할 수 있다.', 6440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11228, '② 소장은 군수형자의 직업훈련을 위하여 필요하면 외부의 기관이나 단체에서 훈련을 받게 할 수 있다.', 6440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11229, '③ 제1항 및 제2항에 따른 직업훈련 대상자의 선정기준 등에 관하여 필요한 사항은 국방부령으로 정한다.', 6440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11230, '① 소장은 군수형자의 신청에 따라 제58조의 작업, 제59조제2항의 훈련, 그 밖에 집중적인 근로가 필요한 작업을 부과하는 경우에는 접견, 전화통화, 교육 및 공동행사 참가 등의 처우를 제한할 수 있다. 다만, 접견이나 전화통화를 제한할 때에는 공휴일, 토요일과 그 밖에 대통령령으로 정하는 휴일과 그 군수형자의 작업이 없는 날에 접견이나 전화통화를 할 수 있게 하여야 한다.', 6441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11231, '② 소장은 제1항에 따라 작업을 부과하거나 훈련을 받게 하기 전에 해당 군수형자에게 제한되는 처우의 내용을 충분히 설명하여야 한다.', 6441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11232, '① 소장은 군수형자의 가족이나 배우자의 직계존속이 사망하면 2일간, 부모나 배우자의 기일(忌日)을 맞이하면 1일간 해당 군수형자의 작업을 면제한다. 다만, 군수형자가 작업을 계속하기를 원하는 경우에는 그러하지 아니하다.', 6443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11233, '② 소장은 군수형자에게 부상, 질병, 그 밖에 작업을 계속하기 어려운 특별한 사정이 있으면 그 사유가 없어질 때까지 작업을 면제할 수 있다.', 6443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11234, '① 작업수입은 국고수입으로 한다.', 6444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11235, '② 소장은 군수형자의 근로의욕을 고취하고 건전한 사회복귀를 지원하기 위하여 국방부장관이 정하는 바에 따라 작업의 종류, 작업성적, 교정성적, 그 밖의 사정을 고려하여 군수형자에게 작업장려금을 지급할 수 있다.', 6444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11236, '③ 제2항의 작업장려금은 석방할 때 본인에게 지급한다. 다만, 본인의 가족생활 부조, 교화 또는 건전한 사회복귀를 위하여 특별히 필요하면 석방 전이라도 그 전부 또는 일부를 지급할 수 있다.', 6444);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11237, '① 소장은 군수형자가 다음 각 호의 어느 하나에 해당하면 국방부장관이 정하는 바에 따라 위로금이나 조위금을 지급할 수 있다.', 6445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11238, '② 위로금은 석방할 때 본인에게 지급하고, 조위금은 그 상속인에게 지급한다.', 6445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11239, '① 소장은 6개월 이상 복역한 군수형자로서 그 형기의 3분의 1(21년 이상의 유기형 또는 무기형의 경우에는 7년을 말한다)이 지나고 교정성적이 우수한 사람이 다음 각 호의 어느 하나에 해당하면 1년 중 20일 이내의 귀휴(기간과 행선지를 정하여 외출ㆍ외박할 수 있도록 하는 것을 말한다. 이하 같다)를 허가할 수 있다.', 6447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11240, '② 소장은 다음 각 호의 어느 하나에 해당하는 사유가 있는 군수형자에 대하여는 제1항에도 불구하고 5일 이내의 특별귀휴를 허가할 수 있다.', 6447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11241, '③ 소장은 귀휴를 허가하는 경우에 국방부령으로 정하는 바에 따라 거소의 제한이나 그 밖에 필요한 조건을 붙일 수 있다.', 6447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11242, '④ 제1항 및 제2항의 귀휴기간은 형 집행기간에 포함한다.', 6447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11243, null, 6448);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11244, '① 군인인 군미결수용자는 수사ㆍ재판 또는 법률로 정하는 조사에 참석할 때에는 군복을 착용하여야 한다.', 6452);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11245, '② 군무원과 민간인인 군미결수용자는 수사ㆍ재판 또는 법률에서 정하는 조사에 참석할 때에는 사복을 착용할 수 있다.', 6452);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11246, '① 제42조제2항에도 불구하고 군미결수용자와 변호인(변호인이 되려고 하는 사람을 포함한다. 이하 같다)의 접견에는 교도관이 참여하지 못하며 그 내용을 청취 또는 녹취하지 못한다. 다만, 보이는 거리에서 군미결수용자를 관찰할 수 있다.', 6454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11247, '② 군미결수용자와 변호인의 접견은 시간과 횟수를 제한하지 아니한다.', 6454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11248, '③ 제44조제4항 단서에도 불구하고 군미결수용자와 변호인 사이의 서신은 군교정시설에서 상대방이 변호인임을 확인할 수 없는 경우를 제외하고는 검열할 수 없다.', 6454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11249, '① 소장은 군미결수용자에 대하여는 신청에 따라 교육 또는 교화프로그램을 실시하거나 작업을 부과할 수 있다.', 6456);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11250, '② 제1항에 따라 군미결수용자에게 교육 또는 교화프로그램을 실시하거나 작업을 부과하는 경우에는 제53조부터 제55조까지 및 제60조부터 제65조까지의 규정을 준용한다.', 6456);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11251, '① 사형확정자는 미결수용실에 수용한다.', 6458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11252, '② 사형확정자는 독거수용한다. 다만, 자살방지 또는 교화, 작업 등을 위하여 필요한 경우에는 국방부령으로 정하는 바에 따라 혼거수용할 수 있다.', 6458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11253, '③ 소장은 사형확정자의 심리적 안정 및 원만한 수용생활을 위하여 본인의 신청에 따라 심리상담 또는 종교상담을 받게 하거나 작업을 부과할 수 있다.', 6458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11254, null, 6460);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11255, '① 교도관은 시설의 안전과 질서유지를 위하여 필요하면 대통령령으로 정하는 바에 따라 군수용자의 신체ㆍ의류ㆍ휴대품ㆍ거실 및 작업장 등을 검사할 수 있다.', 6461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11256, '② 제1항에 따라 교도관이 군수용자의 신체를 검사할 때에는 불필요한 고통이나 수치심을 느끼지 아니하도록 유의하여야 하고, 특히 신체를 면밀하게 검사할 필요가 있으면 다른 군수용자가 볼 수 없는 차단된 장소에서 하여야 한다.', 6461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11257, '③ 교도관은 시설의 안전과 질서유지를 위하여 필요하면 군교정시설을 출입하는 군수용자 외의 사람에 대하여 의류와 휴대품을 검사할 수 있다. 이 경우 출입자가 제79조의 금지물품을 소지하고 있으면 군교정시설에 맡기도록 하여야 하고, 이에 따르지 아니하면 출입을 금지할 수 있다.', 6461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11258, '④ 여성의 의류와 휴대품에 대한 검사는 여성 교도관이 하여야 한다.', 6461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11259, '⑤ 소장은 제1항에 따라 검사한 결과 제79조의 금지물품이 발견되면 형사 법령에서 정하는 절차에 따라 처리할 물품을 제외하고는 군수용자에게 알린 후 폐기한다. 다만, 폐기하는 것이 적당하지 아니한 물품은 군교정시설에 영치하거나 군수용자로 하여금 자신이 지정하는 사람에게 보내게 할 수 있다.', 6461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11260, '① 교도관은 자살ㆍ자해ㆍ도주ㆍ폭행ㆍ손괴, 그 밖에 군수용자의 생명ㆍ신체를 해치거나 시설의 안전이나 질서를 해치는 행위(이하 "자살등"이라 한다)를 방지하기 위하여 필요한 범위에서 전자장비를 이용하여 군수용자나 시설을 계호할 수 있다. 다만, 전자영상장비로 거실에 있는 군수용자를 계호하는 것은 자살등의 우려가 클 때에만 할 수 있다.', 6462);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11261, '② 제1항 단서에 따라 거실에 있는 군수용자를 전자영상장비로 계호할 때에는 계호직원ㆍ계호시간 및 계호대상 등을 기록하여야 한다.', 6462);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11262, '③ 제1항과 제2항에 따라 계호하는 경우에는 계호를 받는 군수용자의 인권이 침해되지 아니하도록 유의하여야 한다.', 6462);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11263, '④ 제1항과 제2항에 따른 전자장비의 종류ㆍ설치장소ㆍ사용방법 및 녹화기록물의 관리 등에 관하여 필요한 사항은 국방부령으로 정한다.', 6462);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11264, '① 소장은 군수용자가 다음 각 호의 어느 하나에 해당하면 군의관의 의견을 참고하여 보호실(자살 및 자해 방지 등의 설비를 갖춘 거실을 말한다. 이하 같다)에 수용할 수 있다.', 6463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11265, '② 군수용자를 보호실에 수용하는 기간은 15일 이내로 한다. 다만, 소장은 특별히 계속하여 군수용자를 보호실에 수용할 필요가 있으면 군의관의 의견을 참고하여 그 기간을 연장할 수 있다.', 6463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11266, '③ 제2항 단서에 따른 기간 연장은 7일 이내로 하되, 계속하여 3개월을 초과할 수 없다.', 6463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11267, '④ 소장은 군수용자를 보호실에 수용하거나 수용기간을 연장할 때에는 그 사유를 본인에게 알려주어야 한다.', 6463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11268, '⑤ 군의관은 보호실에 수용된 군수용자의 건강상태를 수시로 확인하여야 한다.', 6463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11269, '⑥ 소장은 군수용자를 보호실에 수용할 사유가 소멸하면 보호실 수용을 즉시 중단하여야 한다.', 6463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11270, '① 소장은 군수용자가 다음 각 호의 어느 하나에 해당하는 때에 강제력을 행사하거나 제85조의 보호장비를 사용하여도 그 목적을 달성할 수 없는 경우에만 진정실(일반 거실과 격리되어 있고, 방음설비 등을 갖춘 거실을 말한다. 이하 같다)에 수용할 수 있다.', 6464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11271, '② 군수용자의 진정실 수용기간은 24시간 이내로 한다. 다만, 소장은 특별히 계속하여 군수용자를 진정실에 수용할 필요가 있으면 군의관의 의견을 참고하여 그 시간을 연장할 수 있다.', 6464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11272, '③ 제2항 단서에 따른 시간 연장은 12시간 이내로 하되, 계속하여 3일을 초과할 수 없다.', 6464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11273, '④ 진정실에 수용된 군수용자에 대하여는 제82조제4항부터 제6항까지의 규정을 준용한다.', 6464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11274, '① 교도관은 군수용자가 다음 각 호의 어느 하나에 해당하면 보호장비를 사용할 수 있다.', 6465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11275, '② 군수용자에 대하여 보호장비를 사용할 때에는 군수용자의 나이, 건강상태 및 수용생활 태도 등을 고려하여야 한다.', 6465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11276, '③ 교도관이 군교정시설에서 군수용자에 대하여 보호장비를 사용한 경우에는 군의관은 그 군수용자의 건강상태를 수시로 확인하여야 한다.', 6465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11277, '① 보호장비의 종류는 다음 각 호와 같다.', 6466);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11278, '② 보호장비의 종류별 사용요건은 다음 각 호와 같다.', 6466);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11279, '③ 제1항 및 제2항에 따른 보호장비의 사용절차 등에 관하여 필요한 사항은 대통령령으로 정하고, 보호장비의 규격 및 종류별 사용 방법은 국방부령으로 정한다.', 6466);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11280, '① 교도관은 필요한 최소한의 범위에서 보호장비를 사용하여야 하고, 그 사유가 없어지면 지체 없이 사용을 중단하여야 한다.', 6467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11281, '② 보호장비는 징벌의 수단으로 사용되어서는 아니 된다.', 6467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11282, '① 교도관등은 군수용자가 다음 각 호의 어느 하나에 해당하면 강제력을 행사할 수 있다.', 6468);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11283, '② 교도관등은 군수용자가 아닌 사람이 다음 각 호의 어느 하나에 해당하면 강제력을 행사할 수 있다.', 6468);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11284, '③ 제1항과 제2항에 따라 강제력을 행사할 때에는 보안장비를 사용할 수 있다.', 6468);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11285, '④ 제3항에서 "보안장비"란 교도봉, 가스분사기, 가스총, 최루탄 등 사람의 생명과 신체 보호, 군수용자의 도주 방지 및 시설의 안전과 질서유지를 위하여 교도관등이 사용하는 장비와 기구를 말한다.', 6468);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11286, '⑤ 제1항과 제2항에 따라 강제력을 행사하려면 미리 상대방에게 경고하여야 한다. 다만, 상황이 급박하여 경고할 시간적인 여유가 없을 때에는 그러하지 아니하다.', 6468);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11287, '⑥ 강제력의 행사는 필요한 최소한도에 그쳐야 한다.', 6468);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11288, '⑦ 제3항에 따른 보안장비의 종류, 종류별 사용요건 및 사용절차 등에 관하여 필요한 사항은 국방부령으로 정한다.', 6468);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11289, '① 교도관등은 다음 각 호의 어느 하나에 해당하면 군수용자에 대하여 무기를 사용할 수 있다.', 6469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11290, '② 교도관등은 군교정시설(교도관이 군교정시설 밖에서 군수용자를 계호하고 있는 경우 그 장소를 포함한다)에서 자신이나 다른 사람의 생명ㆍ신체를 보호하거나 군수용자의 탈취를 저지하거나 건물 또는 그 밖의 시설과 무기에 대한 위험을 방지하기 위하여 급박하다고 인정되는 충분한 이유가 있으면 군수용자가 아닌 사람에 대하여도 무기를 사용할 수 있다.', 6469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11291, '③ 교도관등은 소장이나 그 직무를 대행하는 사람의 명령을 받아 무기를 사용한다. 다만, 그 명령을 받을 시간적인 여유가 없으면 그러하지 아니하다.', 6469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11292, '④ 제1항과 제2항에 따라 무기를 사용하려면 공포탄을 발사하거나 그 밖의 적당한 방법으로 미리 상대방에게 무기 사용을 경고하여야 한다.', 6469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11293, '⑤ 무기의 사용은 필요한 최소한도에 그쳐야 하며, 최후의 수단이어야 한다.', 6469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11294, '⑥ 제1항 및 제2항에 따라 사용할 수 있는 무기의 종류, 무기의 종류별 사용요건 및 사용절차 등에 관하여 필요한 사항은 국방부령으로 정한다.', 6469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11295, '① 천재지변이나 그 밖의 재해가 발생하여 시설의 안전과 질서유지를 위하여 긴급한 조치가 필요하면 소장은 군수용자로 하여금 피해의 복구나 그 밖의 응급용무를 보조하게 할 수 있다.', 6470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11296, '② 소장은 군교정시설에서 천재지변이나 그 밖의 사변에 대한 피난 방법이 없을 때에는 군수용자를 다른 장소로 이송할 수 있다.', 6470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11297, '③ 소장은 제2항에 따른 이송을 할 수 없으면 수용자를 일시적으로 석방할 수 있다.', 6470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11298, '④ 제3항에 따라 석방된 사람은 석방 후 24시간 이내에 군교정시설 또는 「군인사법」 제5조제2항에 따른 기본병과 중 수사 및 교정업무 등을 주로 담당하는 병과(이하 "군사경찰과"라 한다)에 속하는 군인으로 편성된 부대(이하 "군사경찰부대"라 한다)나 경찰관서에 출석하여야 한다. <개정 2020.2.4>', 6470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11299, '① 교도관은 군수용자가 도주하거나 제117조 각 호의 어느 하나에 해당하는 행위(이하 "도주등"이라 한다)를 하였을 때에는 도주 후 또는 출석기한이 지난 후 72시간 이내에만 그를 체포할 수 있다.', 6471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11300, '② 교도관은 제1항에 따른 체포를 위하여 긴급히 필요하면 도주등을 하였다고 의심할 만한 충분한 이유가 있는 사람이나 도주등을 한 사람의 이동경로나 소재를 안다고 인정되는 사람을 정지시켜 질문할 수 있다.', 6471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11301, '③ 교도관은 제2항에 따라 질문을 할 때에는 그 신분을 표시하는 증표를 보여주고 질문의 목적과 이유를 설명하여야 한다.', 6471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11302, '④ 교도관은 제1항에 따른 체포를 위하여 영업시간 내에 흥행장ㆍ여관ㆍ음식점ㆍ역, 그 밖에 많은 사람이 출입하는 장소의 관리자나 관계인에게 그 장소의 출입이나 그 밖에 특별히 필요한 사항에 관하여 협조를 요구할 수 있다.', 6471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11303, '⑤ 교도관은 제4항에 따라 필요한 장소에 출입하는 경우 그 신분을 표시하는 증표를 보여주어야 하고, 그 장소의 관리자나 관계인의 정당한 업무를 방해하여서는 아니 된다.', 6471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11304, '① 군수용자는 군교정시설의 안전과 질서유지를 위하여 국방부장관이 정하는 규율을 준수하여야 한다.', 6472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11305, '② 군수용자는 소장이 정하는 일과시간표를 준수하여야 한다.', 6472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11306, '③ 군수용자는 교도관의 직무상 지시에 복종하여야 한다.', 6472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11307, null, 6473);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11308, null, 6474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11309, null, 6475);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11310, '① 제94조제4호부터 제13호까지의 징벌은 함께 부과할 수 있다.', 6476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11311, '② 군수용자에게 징벌을 부과하는 경우에는 다음 각 호의 구분에 따라 징벌을 가중할 수 있다.', 6476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11312, '③ 다른 군수용자를 교사(敎唆)하여 징벌대상 행위를 하게 한 군수용자나 다른 군수용자의 징벌대상 행위를 방조(幇助)한 군수용자에게는 그 징벌대상 행위를 한 군수용자와 같은 징벌을 부과하되, 징벌대상 행위를 방조한 군수용자에게는 정황을 고려하여 징벌을 2분의 1까지 감경할 수 있다.', 6476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11313, '④ 징벌은 같은 행위에 대하여 거듭하여 부과할 수 없으며, 행위의 동기 및 경중, 행위 후의 정황, 그 밖의 사정을 고려하여 수용목적 달성에 필요한 최소한도에 그쳐야 한다.', 6476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11314, '⑤ 징벌사유가 발생한 날부터 2년이 지나면 그 사유로 징벌을 부과하지 못한다.', 6476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11315, '⑥ 제1항부터 제5항까지에서 규정한 사항 외에 징벌의 부과기준, 징벌 부과 시의 고려사항 등 징벌의 부과에 관하여 필요한 사항은 국방부령으로 정한다.', 6476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11316, '① 소장은 징벌사유에 해당하는 행위를 하였다고 의심할 만한 충분한 이유가 있는 군수용자(이하 "징벌대상자"라 한다) 또는 참고인을 국방부령으로 정하는 바에 따라 조사할 수 있다.', 6477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11317, '② 징벌대상자가 다음 각 호의 어느 하나에 해당하면 조사기간 중 분리하여 수용할 수 있다.', 6477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11318, '③ 소장은 징벌대상자가 제2항 각 호의 어느 하나에 해당하면 접견, 서신수수, 전화통화, 실외운동, 작업, 교육훈련, 공동행사 참가 등 다른 사람과 접촉할 수 있는 처우의 전부 또는 일부를 제한할 수 있다.', 6477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11319, '① 징벌대상자의 징벌을 결정하기 위하여 군교정시설에 징벌위원회(이하 이 조에서 "위원회"라 한다)를 둔다.', 6478);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11320, '② 위원회는 위원장을 포함한 5명 이상 7명 이하의 위원으로 구성하되, 위원장은 소장이 되고, 위원은 소장이 소속 부대의 장교, 군법무관 및 교정에 관한 학식과 경험이 풍부한 외부인사 중에서 임명하거나 위촉한다. 이 경우 외부인사인 위원과 군법무관은 각각 1명 이상으로 한다.', 6478);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11321, '③ 위원회는 소장의 징벌 요구에 따라 개회하며, 징벌은 그 의결로 정한다.', 6478);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11322, '④ 징벌위원회는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.', 6478);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11323, '⑤ 위원회의 위원이 징벌대상자의 친족이거나 그 밖에 공정한 심의ㆍ의결을 기대할 수 없는 특별한 사유가 있을 때에는 위원회에 참석할 수 없다.', 6478);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11324, '⑥ 징벌대상자는 위원회의 위원에 대하여 기피(忌避) 신청을 할 수 있다. 이 경우 위원회는 의결로 기피 여부를 결정하여야 한다.', 6478);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11325, '⑦ 위원회는 징벌대상자가 위원회에 출석하여 충분한 진술을 할 수 있는 기회를 주어야 하며, 징벌대상자는 서면이나 말로써 자기에게 유리한 사실을 진술하거나 증거를 제출할 수 있다.', 6478);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11326, '⑧ 제1항부터 제7항까지에서 규정한 사항 외에 위원회의 구성 및 운영에 관하여 필요한 사항은 대통령령으로 정한다.', 6478);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11327, '① 징벌은 소장이 집행한다.', 6479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11328, '② 소장은 징벌 집행을 위하여 필요하다고 인정하면 군수용자를 분리하여 수용할 수 있다.', 6479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11329, '③ 제94조제14호의 징벌을 받은 사람에게는 그 기간 중 같은 조 제4호부터 제13호까지의 징벌이 함께 부과된다. 다만, 소장은 군수용자의 권리구제, 군수형자의 교화나 건전한 사회복귀를 위하여 특별히 필요하다고 인정하면 집필, 서신수수, 접견 또는 실외운동을 허가할 수 있다.', 6479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11330, '④ 소장은 제94조제13호 또는 제14호의 징벌을 집행할 때에는 군의관으로 하여금 미리 군수용자의 건강을 확인하도록 하여야 하고, 징벌이 집행 중일 때에도 징벌을 받고 있는 군수용자의 건강상태를 수시로 확인하여야 한다.', 6479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11331, '⑤ 제1항부터 제4항까지에서 규정한 사항 외에 징벌기간의 계산 등 징벌의 집행에 관하여 필요한 사항은 대통령령으로 정한다.', 6479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11332, '① 소장은 질병이나 그 밖의 사유로 징벌 집행이 곤란하면 그 사유가 없어질 때까지 그 집행을 일시적으로 정지할 수 있다.', 6480);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11333, '② 소장은 징벌 집행 중인 군수용자가 뉘우치는 빛이 뚜렷한 경우에는 그 징벌을 감경하거나 남은 기간의 징벌 집행을 면제할 수 있다.', 6480);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11334, '① 징벌위원회가 징벌을 의결하는 때에는 징벌의 원인이 된 행위의 동기 및 정황, 교정성적, 뉘우치는 정도 등 그 사정을 고려할 만한 사유가 있는 군수용자에 대하여 2개월 이상 6개월 이하의 기간 동안 징벌의 집행을 유예할 것을 의결할 수 있다.', 6481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11335, '② 소장은 징벌 집행의 유예기간 중에 있는 군수용자가 다시 제93조의 징벌대상 행위를 하여 징벌이 결정되면 그 유예한 징벌을 함께 집행한다.', 6481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11336, '③ 군수용자가 징벌 집행을 유예받은 후 징벌을 받지 아니하고 유예기간이 지나면 그 징벌의 집행은 끝난 것으로 본다.', 6481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11337, '④ 이 법에서 규정한 사항 외에 징벌의 결정 및 집행에 관하여 필요한 사항은 국방부령으로 정한다.', 6481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11338, '① 군수용자는 그 처우에 관하여 소장에게 면담을 신청할 수 있다.', 6482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11339, '② 소장은 군수용자의 면담신청을 받으면 다음 각 호의 어느 하나에 해당하는 때를 제외하고는 면담에 응하여야 한다.', 6482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11340, '③ 소장은 특별한 사정이 있으면 소속 교도관으로 하여금 그 면담을 대리하게 할 수 있다. 이 경우 면담을 대리한 사람은 그 결과를 소장에게 지체 없이 보고하여야 한다.', 6482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11341, '④ 소장은 면담한 결과 처리가 필요한 사항이 있으면 그 처리결과를 군수용자에게 통지하여야 한다.', 6482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11342, '① 군수용자는 그 처우에 관하여 불복할 경우 국방부장관 또는 제7조에 따른 순회점검 공무원에게 청원할 수 있다. <개정 2014.5.20>', 6483);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11343, '② 제1항에 따라 청원하려는 군수용자는 청원서를 작성하여 봉한 후 소장에게 제출하여야 한다. 다만, 순회점검 공무원에 대한 청원은 말로도 할 수 있다.', 6483);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11344, '③ 소장은 청원서를 개봉하여서는 아니 되며, 이를 지체 없이 국방부장관 또는 순회점검 공무원에게 전달하여야 한다. <개정 2014.5.20>', 6483);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11345, '④ 제2항 단서에 따라 순회점검 공무원이 군수용자의 청원을 청취하는 경우에는 해당 군교정시설의 교도관등이 참여하여서는 아니 된다.', 6483);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11346, '⑤ 청원을 받은 국방부장관은 청원에 대하여 지체 없이 문서로써 결정하여야 한다. <개정 2014.5.20>', 6483);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11347, '⑥ 소장은 청원에 관한 결정서를 접수하면 청원인에게 지체 없이 전달하여야 한다.', 6483);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11348, '① 위원회는 위원장을 포함한 5명 이상 9명 이하의 위원으로 구성한다.', 6486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11349, '② 위원장은 교도소의 장이 되고, 위원은 위원장이 군법무관, 군사경찰과 장교, 교정에 관한 학식과 경험이 풍부한 사람 중에서 위촉한다. <개정 2020.2.4>', 6486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11350, '③ 이 법에서 규정한 사항 외에 위원회의 구성 및 운영에 관하여 필요한 사항은 국방부령으로 정한다.', 6486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11351, '① 위원회는 군수형자의 나이, 범죄동기, 죄명, 형기, 교정성적, 건강상태, 가석방 후의 생계능력, 생활환경, 재범의 위험성, 그 밖에 필요한 사정을 고려하여 가석방의 적격 여부를 결정한다.', 6487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11352, '② 위원회는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.', 6487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11353, '③ 가석방 적격 여부의 심사절차 및 조사, 그 밖에 가석방 적격심사에 관하여 필요한 사항은 국방부령으로 정한다.', 6487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11354, '① 위원회는 가석방 적격결정을 하였으면 5일 이내에 국방부장관에게 가석방 허가를 신청하여야 한다.', 6488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11355, '② 국방부장관은 제1항에 따른 위원회의 가석방 허가신청이 적정하다고 인정하면 가석방을 허가할 수 있다.', 6488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11356, '① 사면, 가석방, 형의 집행면제, 감형에 따른 석방은 그 서류가 도달한 후 12시간 이내에 하여야 한다. 다만, 그 서류에서 석방일시를 지정하고 있으면 그 일시에 한다.', 6490);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11357, '② 형기종료에 따른 석방은 형기종료일에 하여야 한다.', 6490);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11358, '③ 권한 있는 사람의 명령에 따른 석방은 서류가 도달한 후 5시간 이내에 하여야 한다.', 6490);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11359, '① 소장은 사망한 군수용자의 친족이나 군수용자와 특별한 연고가 있는 사람이 그 시신이나 유골의 인도를 청구하면 인도하여야 한다. 다만, 제3항에 따라 합장(合葬)을 한 뒤에는 그러하지 아니하다.', 6494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11360, '② 소장은 제112조에 따라 사망 통지를 받은 사람이 통지를 받은 날부터 3일 이내에 그 시신을 인수하지 아니하거나 시신을 인수할 사람이 없으면 임시로 매장하여야 한다. 다만, 감염병 예방 등을 위하여 필요하면 즉시 화장(火葬)을 하는 등 필요한 조치를 할 수 있다. <개정 2009.12.29>', 6494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11361, '③ 소장은 제2항에 따라 시신을 임시로 매장한 후 2년이 지나도 시신의 인도를 청구하는 사람이 없으면 합장하거나 화장할 수 있다.', 6494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11362, '④ 소장은 병원이나 그 밖의 연구기관이 학술연구상 필요하여 군수용자의 시신 인도를 신청하면 본인의 유언이나 상속인의 승낙이 있는 경우에만 병원이나 그 밖의 연구기관에 시신을 인도할 수 있다.', 6494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11363, '① 군수용자의 교육ㆍ교화, 의료 지원, 그 밖에 군수용자의 처우를 후원하기 위하여 군교정시설에 교정위원을 둘 수 있다.', 6495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11364, '② 교정위원은 명예직으로 하며 소장의 추천을 받아 국방부장관이 위촉한다. <개정 2014.5.20>', 6495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11365, '③ 교정위원은 교정위원으로 활동 중에 알게 된 군수용자의 신상에 관한 사항이나 군교정시설의 안전과 관련된 사실을 누설하거나 공개하여서는 아니 된다.', 6495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11366, '① 소장은 기관ㆍ단체 또는 개인이 군수용자의 교화 등을 위하여 군교정시설에 자발적으로 기탁하는 금품을 받을 수 있다.', 6496);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11367, '② 제1항에 따른 기부금품의 접수방법, 처리절차, 기부금품의 공개 등에 관하여 필요한 사항은 대통령령으로 정한다.', 6496);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11368, '① 다음 각 호의 어느 하나에 해당하는 행위를 한 사람은 6개월 이하의 징역 또는 200만원 이하의 벌금에 처한다.', 6499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11369, '② 제1항의 미수범은 처벌한다.', 6499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11370, '③ 제1항의 금지물품은 몰수한다.', 6499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11371, null, 6500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11372, '① 군판사와 군검사가 법 제8조제1항에 따라 군교도소, 군교도소 지소(支所) 및 군미결수용실(이하 "군교정시설"이라 한다)을 시찰하려면 신분을 나타내는 증표를 소장에게 보여주고 시찰부에 서명 또는 날인하여야 한다. <개정 2022.6.30>', 6503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11373, '② 소장은 군교도관에게 군판사나 군검사를 시찰하려는 장소로 안내하게 하고, 시찰한 시간을 시찰부에 기록하여야 한다. <개정 2022.6.30>', 6503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11374, '① 군판사와 군검사 외의 사람이 법 제8조제2항에 따라  군교정시설을 참관하려면 다음 각 호의 사항을 적은 신청서를 소장에게 제출하여야 한다. <개정 2022.6.30>', 6504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11375, '② 제1항에 따라 신청서를 받은 소장은 참관하려는 사람의 신분과 참관 목적 등을 확인한 후 허가 여부를 결정하여야 한다.', 6504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11376, '③ 소장은 외국인에게 참관을 허가하려면 국방부장관의 승인을 받아야 한다. <개정 2014.10.28>', 6504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11377, '④ 소장은 참관을 허가한 사람에게 미리 참관할 때의 주의사항을 알려주어야 한다.', 6504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11378, null, 6506);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11379, '① 군교도관은 제6조제2호의 계호상 독거수용을 한 군수용자(이하 "계호독거자"라 한다)를 수시로 시찰하여 건강과 교화에 이상이 없는지 살펴야 한다.', 6507);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11380, '② 군교도관은 계호독거자가 건강에 이상이 있다고 보일 때에는 즉시 해당 군교정시설을 담당하는 군의관에게 그 사실을 알려야 하고, 교화에 문제가 있다고 인정되면 즉시 소장에게 보고하여야 한다.', 6507);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11381, '③ 제2항에 따라 통보받은 군의관은 즉시 계호독거자를 상담ㆍ진찰하는 등 적절한 의료조치를 하여야 하고, 독거수용을 계속하게 되면 건강을 해치게 된다고 판단될 때에는 그 사실을 즉시 소장에게 보고하여야 한다.', 6507);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11382, '④ 소장은 계호독거자를 계속 독거수용하는 것이 건강이나 교화에 해롭다고 인정되면 즉시 독거수용을 중단하여야 한다.', 6507);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11383, '① 소장은 거실에 면적, 정원 및 현재인원을 적은 현황표를 붙여야 한다.', 6513);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11384, '② 소장은 거실 앞에 군수용자의 이름표를 붙여야 한다. 이 경우 이름표 윗부분에는 군수용자의 성명, 출생연도, 죄명, 형명(刑名) 및 형기(刑期)를 적고, 아랫부분에는 군수용자 번호와 입소한 날짜를 적되, 윗부분의 내용은 보이지 않도록 하여야 한다. <개정 2014.10.28>', 6513);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11385, '③ 소장은 군수용자가 법령에 따라 지켜야 할 사항과 군수용자의 권리구제 절차에 관한 사항을 거실 안 군수용자가 보기 쉬운 곳에 붙이는 등의 방법으로 비치하여야 한다. <개정 2014.10.28>', 6513);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11386, '① 소장은 군사법원, 군검찰부, 군사경찰부대 등에서 처음으로 군교정시설에 수용되는 사람(이하 "신입자"라 한다)이나 다른 군교정시설로부터 이송(移送)되어 온 사람(이하 "이입자"라 한다)을 인수하였을 때에는 호송인(護送人)에게 인수서를 써 주어야 한다. 이 경우 신입자나 이입자에게 부상이나 질병, 그 밖에 건강에 이상이 있을 때에는 호송인으로부터 그 사실에 대한 확인서를 받아야 한다. <개정 2020.2.4>', 6514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11387, '② 신입자나 이입자를 인수한 군교도관은 제1항 전단의 인수서에 성명, 나이 및 인수 일시를 적고 서명 또는 날인하여야 한다.', 6514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11388, '③ 소장은 제1항 후단에 따라 확인서를 받았을 때에는 호송인에게 신입자나 이입자의 성명, 나이, 인계 일시 및 부상의 정도나 질병의 상태 등에 관한 사실을 적고 서명 또는 날인하도록 하여야 한다.', 6514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11389, '④ 소장은 신입자나 이입자가 감염병(「감염병의 예방 및 관리에 관한 법률」 제2조제2호에 따른 감염병을 말한다. 이하 같다)에 걸린 때에는 인수를 거부할 수 있다. 이 경우 수용을 지휘한 군검사와 소속 부대장 또는 이송 보낸 소장에게 즉시 그 사유를 통보하고 국방부장관에게 보고하여야 한다. <개정 2010.12.29, 2022.6.30>', 6514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11390, '⑤ 소장은 제4항에도 불구하고 감염병에 걸린 신입자나 이입자가 위독하여 다른 곳으로 이송할 만한 시간적 여유가 없을 때에는 그를 격리수용하고 즉시 필요한 조치를 하여야 한다. <개정 2010.12.29>', 6514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11391, '① 소장은 신입자의 키, 용모, 문신, 흉터 등 신체의 특징과 가족이나 보호자 등의 연락처를 제19조에 따른 수용기록부에 기록하여야 한다.', 6518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11392, '② 소장은 업무상 필요한 경우가 아니면 군교도관이 제1항의 수용기록부를 열람하지 못하도록 하여야 한다.', 6518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11393, '③ 소장은 신입자와 이입자에게 군수용자 번호를 지정하고, 상의 왼쪽 가슴 부위에 번호표를 붙이게 하여야 한다. 다만, 군수용자의 교화 또는 건전한 사회복귀를 위하여 특히 필요하다고 인정하면 번호표를 붙이지 아니할 수 있다.', 6518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11394, '① 소장은 신입자 또는 이입자가 환자이거나 그 밖에 부득이한 사정이 있는 경우가 아니면 수용된 날부터 7일 동안 신입자만을 수용하는 거실(이하 "신입자거실"이라 한다)에 수용하여야 한다.', 6520);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11395, '② 소장은 신입자거실에 수용된 사람에게는 작업을 부과해서는 아니 된다.', 6520);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11396, '③ 소장은 신입자나 이입자의 처우를 위하여 특히 필요하다고 인정하면 제1항의 기간을 30일까지 연장할 수 있다.', 6520);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11397, '① 소장은 거실, 작업장, 그 밖에 군수용자가 생활하는 장소(이하 "거실등"이라 한다)에 수용생활에 필요한 기구를 갖춰 두어야 한다.', 6526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11398, '② 거실등에는 제1항에 따라 갖춰 둔 기구의 품목과 수량을 기록한 품목표를 붙여 두어야 한다.', 6526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11399, '① 소장은 군수용자가 사용하는 의류등을 적당한 시기에 세탁, 수선 또는 교체하여야 한다.', 6533);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11400, '② 자신의 비용으로 구매한 의류등의 세탁이나 수선에 필요한 비용은 군수용자가 부담한다.', 6533);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11401, '① 법 제25조제1항 각 호의 어느 하나에 해당하지 아니하는 휴대품은 영치한 후 사용하게 할 수 있다.', 6534);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11402, '② 소장은 법 제25조제1항 단서에 따라 군수용자의 휴대품을 팔 경우에는 그 비용을 제외한 나머지 대금을 영치할 수 있다.', 6534);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11403, '③ 소장은 법 제25조제1항 각 호의 어느 하나에 해당하는 휴대품을 국방부장관이 정한 기간 내에 처분하지 아니하면 폐기한다는 사실을 군수용자에게 알리고, 군수용자가 그 기간이 지날 때까지 처분하지 아니하면 이를 폐기하여야 한다.', 6534);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11404, '① 소장은 법 제27조제1항에 따라 교부를 허가한 금품의 내용이나 용도가 분명하여 검사할 필요가 없다고 인정되는 경우 외에는 군교도관에게 위해성(危害性)이나 안전성 등에 대하여 검사하게 하여야 한다. 이 경우 물품이 의약품인 경우에는 군의관에게 검사하게 하여야 한다.', 6541);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11405, '② 소장은 제1항에 따라 검사를 마친 금품을 영치한 후 사용하게 할 수 있다.', 6541);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11406, '① 소장은 법 제29조에 따라 군수용자가 영치금 사용을 신청한 경우에는 영치금이 정당한 용도에 사용되는지를 확인하고 허가할 수 있다.', 6543);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11407, '② 제1항에 따라 영치금을 사용하는 경우 발생하는 비용은 군수용자가 부담한다.', 6543);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11408, '③ 영치금의 출납, 예탁(預託), 영치금품의 보관 등에 필요한 사항은 국방부장관이 정한다.', 6543);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11409, '① 소장은 거실등과 목욕탕, 취사장, 주식ㆍ부식 저장고, 그 밖에 음식물 공급과 관련된 시설을 수시로 청소ㆍ소독하여야 한다.', 6545);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11410, '② 소장은 저수조(貯水槽) 등 급수시설을 6개월에 1회 이상 청소ㆍ소독하여야 한다.', 6545);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11411, null, 6547);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11412, '① 소장은 법 제35조에 따라 군수용자에 대하여 1년에 1회 이상 건강검진을 하여야 한다. 다만, 계호독거자에 대해서는 6개월에 1회 이상 하여야 한다.', 6549);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11413, '② 제1항의 건강검진은 「건강검진기본법」 제14조에 따라 지정된 건강검진기관에 의뢰하여 할 수 있다.', 6549);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11414, '① 소장은 법 제36조에 따라 군수용자가 감염병에 걸렸다고 의심되는 경우에는 1주 이상 격리수용하고, 그의 휴대품을 소독하여야 한다. <개정 2010.12.29>', 6550);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11415, '② 소장은 감염병이 유행하고 있을 때에는 군수용자가 자신의 비용으로 구매한 음식물의 공급을 중지할 수 있다. <개정 2010.12.29>', 6550);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11416, '③ 소장은 군수용자가 감염병에 걸렸을 때에는 즉시 격리수용하고, 그가 사용하였던 물품과 설비를 철저히 소독하여야 한다. <개정 2010.12.29>', 6550);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11417, '④ 제3항의 경우 소장은 군수용자가 감염병에 걸린 사실을 지체 없이 국방부장관에게 보고하고, 관할 보건기관의 장에게 알려야 한다. <개정 2010.12.29>', 6550);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11418, '① 소장은 법 제37조에 따라 군수용자가 부상을 당하거나 질병에 걸렸을 때에는 의료용 거실에 수용하거나 다른 군수용자에게 그를 간병(看病)하게 할 수 있다.', 6551);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11419, '② 소장은 특히 필요하다고 인정하면 군병원이 아닌 의료시설(이하 "외부의료시설"이라 한다)에서 근무하는 의사에게 군수용자를 치료하게 할 수 있다.', 6551);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11420, '③ 소장은 군수용자가 위독한 경우에는 그 사실을 가족에게 지체 없이 알려야 한다.', 6551);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11421, '① 소장은 법 제38조제1항에 따라 군수용자를 외부의료시설에서 진료를 받도록 결정하기 전에 미리 군의관의 의견을 들어야 한다.', 6552);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11422, '② 소장은 법 제38조제1항에 따라 군수용자를 외부의료시설에 입원시키거나 입원 중인 군수용자를 군교정시설로 데려왔을 때에는 그 사실을 국방부장관에게 지체 없이 보고하여야 한다.', 6552);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11423, '① 법 제42조제1항에 따른 군수용자의 접견은 매일(공휴일 및 국방부장관이 정한 날은 제외한다) 군 표준일과표에 따른 근무시간에 한다.', 6553);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11424, '② 군수용자의 접견시간은 1회당 30분 이내로 한다. 다만, 군미결수용자가 변호인과 접견하는 경우에는 접견시간을 제한하지 아니한다.', 6553);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11425, '③ 군수형자의 접견 횟수는 매월 4회 이상으로 하되, 제77조제2항에 따라 부여한 처우등급별 접견 횟수는 국방부령으로 정한다.', 6553);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11426, '④ 군수용자의 접견은 접촉 차단시설이 설치된 장소(이하 "접견실"이라 한다)에서 하게 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그러하지 아니하다. <개정 2014.10.28>', 6553);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11427, '⑤ 법 및 이 영에서 규정한 사항 외에 군수형자, 사형확정자 및 군미결수용자 외의 군수용자에 대한 접견 횟수ㆍ시간ㆍ장소 등에 관하여 필요한 사항은 국방부장관이 정한다.', 6553);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11428, '① 소장은 제53조제1항 및 제2항에도 불구하고 군수형자의 교화 또는 건전한 사회복귀를 위하여 특히 필요하다고 인정하면 군 표준일과표에 따른 근무시간 외의 시간에도 접견하게 할 수 있고, 접견시간을 연장할 수 있다.', 6554);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11429, '② 소장은 제53조제3항에도 불구하고 군수형자가 다음 각 호의 어느 하나에 해당하는 경우에는 접견 횟수를 늘릴 수 있다.', 6554);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11430, '③ 소장은 제53조제4항 본문에도 불구하고 군수형자가 제2항 각 호에 해당하는 경우에는 접견실 외의 장소에서 접견하게 할 수 있다.', 6554);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11431, '① 소장은 법 제42조제2항에 따라 접견내용을 청취ㆍ기록하기 위하여 군교도관이나 교도병(군교정시설에서 군교도관의 업무를 보조하는 병을 말한다. 이하 같다)을 접견에 참여하게 할 수 있다. 다만, 군미결수용자가 변호인과 접견하는 경우는 제외한다.', 6556);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11432, '② 소장은 법 제42조제2항 후단에 따라 군수용자와 군수용자가 아닌 사람에게 외국어를 사용하게 할 때에는 군교도관이나 통역인으로 하여금 통역하게 할 수 있다.', 6556);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11433, '③ 소장은 법 제42조제3항에 따라 군수용자와 그 상대방에게 접견실에 들어가기 전에 미리 접견내용을 청취ㆍ녹음 또는 녹화한다는 사실을 말이나 서면 등 적절한 방법으로 알려주어야 한다.', 6556);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11434, '① 소장은 접견내용을 청취ㆍ기록ㆍ녹음 및 녹화한 경우의 접견기록물에 대한 보호ㆍ관리를 위하여 접견정보 취급자를 지정하여야 한다.', 6557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11435, '② 제1항에 따라 지정된 접견정보 취급자는 직무상 알게 된 접견정보를 누설하거나, 권한 없이 처리하거나, 다른 사람이 이용하도록 제공하는 등 부당한 목적을 위하여 사용해서는 아니 된다.', 6557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11436, '③ 소장은 다음 각 호의 어느 하나에 해당하는 경우에는 접견기록물을 관계 기관에 제공할 수 있다.', 6557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11437, '④ 소장은 제3항에 따라 접견기록물을 제공할 때에는 제1항에 따라 지정된 접견정보 취급자에게 접견기록물을 요청한 기관의 명칭, 받으려는 목적, 제공 근거, 제공을 요청한 범위, 그 밖에 필요한 사항을 접견기록물 관리부에 기록하게 하고, 따로 이동식 저장매체에 옮겨 담아 제공하여야 한다.', 6557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11438, '① 군수용자는 서신을 보내려는 경우 해당 서신을 봉함하여 군교정시설에 제출한다. 다만, 소장은 다음 각 호의 어느 하나에 해당하는 경우로서 법 제44조제3항에 따른 금지물품의 확인을 위하여 필요한 경우에는 서신을 봉함하지 아니한 상태로 제출하게 할 수 있다. <개정 2013.9.26>', 6560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11439, '② 소장은 군수용자에게 온 서신에 법령에서 금지한 물품이 들어 있는지를 개봉하여 확인할 수 있다.', 6560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11440, '① 법 제44조제4항제4호에서 "대통령령으로 정하는 군수용자 사이의 서신"이란 다음 각 호의 어느 하나에 해당하는 군수용자가 다른 군수용자와 주고받는 서신을 말한다.', 6561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11441, '② 군수용자 사이에 오가는 서신에 대한 검열은 서신을 보내는 군교정시설에서 한다. 다만, 특히 필요하다고 인정되는 경우에는 서신을 받는 군교정시설에서도 할 수 있다.', 6561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11442, '③ 소장은 군수용자가 주고받는 서신이 법 제44조제4항 각 호의 어느 하나에 해당하면 이를 개봉한 후 검열할 수 있다. <신설 2013.9.26>', 6561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11443, '④ 소장은 제3항에 따라 서신을 검열한 결과 그 내용이 법 제44조제5항의 발신 또는 수신 금지사유에 해당하지 아니하면 발신서신은 봉함한 후 발송하고, 수신서신은 군수용자에게 교부한다. <신설 2013.9.26>', 6561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11444, '⑤ 소장은 서신의 내용을 검열하였을 때에는 그 사실을 해당 군수용자에게 지체 없이 알려 주어야 한다. <신설 2013.9.26>', 6561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11445, '① 군수용자는 법 제45조에 따라 전화통화를 허가받으려면 미리 전화번호와 수신자를 지정하여 신청하여야 한다.', 6565);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11446, '② 전화통화는 발신(發信)으로 한정하고, 통화시간은 특별한 사정이 없으면 3분 이내로 한다.', 6565);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11447, '① 법 제45조에 따른 전화통화는 매일(공휴일 및 국방부장관이 정한 날은 제외한다) 군 표준일과표에 따른 근무시간에 할 수 있다.', 6566);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11448, '② 소장은 제1항에도 불구하고 평일에 전화통화가 곤란한 특별한 사유가 있는 군수용자에 대해서는 전화통화 시간을 따로 정할 수 있다.', 6566);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11449, '① 소장은 법 제45조제2항에 따라 전화통화를 허가할 때에는 법 제42조제2항 각 호의 어느 하나에 해당하지 아니한다고 명백히 인정되는 경우 외에는 군수용자의 통화내용을 청취 또는 녹음하는 것을 조건으로 붙여야 한다.', 6567);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11450, '② 소장은 제45조제4항에 따라 군수용자에게 전화통화를 하기 전에 미리 통화내용을 청취하거나 녹음한다는 사실을 말이나 서면 등 적절한 방법으로 알려주어야 한다.', 6567);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11451, '③ 제1항에 따라 녹음한 기록물은 「공공기록물 관리에 관한 법률」에 따라 관리하고, 특히 녹음한 기록물이 손상되지 않도록 그 보존에 주의하여야 한다.', 6567);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11452, '④ 군교도관은 군수용자 전화통화의 청취ㆍ녹음을 통하여 알게 된 내용을 누설하거나, 권한 없이 처리하거나, 타인의 이용에 제공하는 등 부당한 목적으로 사용해서는 아니 된다.', 6567);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11453, '⑤ 제1항에 따라 녹음한 기록물을 관계 기관에 제공하는 것에 관하여는 제57조제3항 및 제4항을 준용한다.', 6567);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11454, '① 군수용자의 전화통화 요금은 군수용자의 부담으로 한다.', 6568);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11455, '② 소장은 군수용자가 교정성적이 양호하거나 영치금이 없는 등 특히 필요하다고 인정하는 경우에는 예산의 범위에서 요금을 부담할 수 있다.', 6568);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11456, '① 소장은 법 제47조에 따라 군수용자가 쉽게 이용할 수 있도록 도서를 갖춰 두고 그 목록을 정기적으로 공개하여야 한다.', 6571);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11457, '② 제1항에 따라 갖춰 둔 도서의 열람방법, 열람기간 등에 관하여 필요한 사항은 국방부장관이 정한다.', 6571);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11458, '① 법 제50조에 따른 집필에 필요한 집필용구는 거실의 집필용구 보관함에 보관하여 관리한다.', 6573);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11459, '② 거실에는 집필용구의 품목과 수량을 기록한 집필용구 품목표를 붙여 두어야 한다.', 6573);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11460, '③ 집필용구의 구입비용은 군수용자가 부담한다. 다만, 소장은 군수용자가 그 비용을 부담할 수 없는 경우에는 필요한 집필용구를 지급할 수 있다.', 6573);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11461, '① 군수용자는 휴업일과 휴게시간에 시간의 제한 없이 집필할 수 있다. 다만, 부득이한 사정이 있는 경우에는 그러하지 아니하다.', 6574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11462, '② 군수용자는 거실, 작업장, 그 밖에 지정된 장소에서 집필할 수 있다.', 6574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11463, '① 소장은 군수용자가 자신이 작성하거나 집필한 문서 또는 도화를 외부로 보내거나 내가려고 하는 경우에는 그 내용을 확인하여 법 제44조제5항 각 호의 어느 하나에 해당하지 아니하면 허가하여야 한다.', 6575);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11464, '② 제1항에 따라 문서 또는 도화를 외부로 보내거나 내가는 데에 드는 비용은 군수용자가 부담한다.', 6575);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11465, '③ 법 및 이 영에서 규정한 사항 외에 군수용자의 집필에 필요한 사항은 국방부장관이 정한다.', 6575);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11466, '① 소장은 자유형(自由刑)이 확정된 군미결수용자에 대해서는 군검사의 집행 지휘서가 도달된 때부터 군수형자로 처우하여야 한다. <개정 2022.6.30>', 6576);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11467, '② 군검사는 집행 지휘를 한 날부터 10일 이내에 재판서(裁判書)나 그 밖에 적법한 서류를 소장에게 보내야 한다. <개정 2022.6.30>', 6576);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11468, '① 소장은 법 제51조에 따른 군수형자의 처우를 위하여 개별처우계획을 수립하여야 한다.', 6577);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11469, '② 소장은 제1항에 따른 개별처우계획의 시행에 적합하게 정하거나 조정하기 위하여 교정성적에 따라 처우등급을 부여할 수 있다.', 6577);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11470, '③ 군수형자에게 부여하는 처우등급에 관하여 필요한 사항은 국방부령으로 정한다.', 6577);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11471, '① 소장은 법 제53조에 따른 교육을 효과적으로 시행하기 위하여 교육실을 설치하는 등 교육에 적합한 환경을 조성하여야 한다.', 6579);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11472, '② 소장은 교육 대상자, 시설 여건 등을 고려하여 교육계획을 수립하여 시행하여야 한다.', 6579);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11473, '① 소장은 법 제55조에 따라 군수형자에게 작업을 부과하는 경우에는 작업의 종류와 작업과정을 정하여 알려야 한다.', 6581);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11474, '② 제1항의 작업과정은 작업성적, 작업시간, 작업의 난이도 및 숙련도를 고려하여 정한다. 이 경우 작업과정을 정하기 어려우면 작업시간을 작업과정으로 본다.', 6581);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11475, '③ 군수형자에게 부과하는 작업의 종류, 작업과정 및 작업시간 등의 세부 사항은 국방부령으로 정한다.', 6581);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11476, '① 소장은 법 제66조에 따라 2일 이상의 귀휴(歸休)를 허가하였을 때에는 귀휴를 허가받은 군수형자의 귀휴지(법 제66조제1항에 따라 정한 행선지를 말한다)를 관할하는 군사경찰부대나 국가경찰관서의 장에게 그 사실을 통보하여야 한다. <개정 2020.2.4>', 6586);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11477, '② 귀휴 중인 군수형자는 천재지변이나 그 밖의 사유로 자신의 신상에 중대한 사고가 발생하였을 때에는 가까운 군교정시설, 군사경찰부대 또는 국가경찰관서에 신고하여야 하고, 필요한 보호를 요청할 수 있다. <개정 2020.2.4>', 6586);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11478, '③ 제2항에 따른 보호 요청을 받은 군교정시설, 군사경찰부대 또는 국가경찰관서의 장은 귀휴를 허가한 소장에게 그 사실을 지체 없이 통보하고 적절한 보호조치를 하여야 한다. <개정 2020.2.4>', 6586);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11479, '① 법 제75조제1항에 따른 군미결수용자에 대한 교육ㆍ교화 프로그램이나 작업은 군교정시설 밖에서 실시하거나 부과하지 아니한다.', 6591);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11480, '② 소장은 법 제75조제1항에 따라 작업이 부과된 군미결수용자가 작업의 취소를 요청하는 경우에는 그 군미결수용자의 의사, 건강 및 군교도관의 의견 등을 고려하여 작업을 취소할 수 있다.', 6591);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11481, '① 소장은 사형을 집행하였을 때에는 군의관에게 시신을 검사하게 하여 사망하였음을 확인한 후가 아니면 시신의 이전 등 다른 조치를 하지 못한다. <개정 2014.10.28>', 6597);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11482, '② 사형 집행 시 군검사는 사형확정자의 유언을 기록하고 날인한 후 친족 또는 친지에게 전달하여야 한다. <개정 2022.6.30>', 6597);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11483, '① 군교정시설의 바깥문, 출입구, 거실, 작업장, 그 밖에 군수용자를 수용하고 있는 장소는 외부와 차단하여야 한다. 다만, 필요에 따라 일시 개방하는 경우에는 그 장소를 경비하여야 한다.', 6602);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11484, '② 군교도관은 접견, 상담, 진료, 그 밖에 군수용자의 처우를 위하여 필요한 경우가 아니면 군수용자와 외부인이 접촉하게 해서는 아니 된다.', 6602);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11485, '① 법 제82조제5항 및 제83조제4항에 따라 군의관이 보호실이나 진정실에 수용된 군수용자의 건강을 확인한 결과 보호실이나 진정실에 계속 수용하는 것이 부적당하다고 인정하는 경우에는 소장에게 즉시 보고하여야 한다. 이 경우 소장은 특별한 사유가 없으면 보호실이나 진정실에 수용하는 것을 즉시 중지하여야 한다.', 6605);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11486, '② 소장은 군의관이 출장, 휴가, 그 밖의 부득이한 사유로 법 제82조제5항 또는 제83조제4항의 직무를 수행할 수 없을 때에는 군교정시설에 근무하는 의료 관계자에게 그 직무를 대행하게 할 수 있다.', 6605);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11487, '① 군교도관은 소장의 명령 없이 군수용자에게 법 제85조제1항에 따른 보호장비를 사용해서는 아니 된다. 다만, 소장의 명령을 받을 시간적 여유가 없는 경우에는 보호장비를 사용한 후 소장에게 즉시 보고하여야 한다.', 6606);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11488, '② 군교도관이 보호장비를 사용할 때에는 군수용자에게 그 사유를 알려주어야 한다.', 6606);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11489, '③ 군의관은 군수용자에게 보호장비를 계속 사용하는 것이 건강상 부적당하다고 인정하는 경우에는 소장에게 즉시 보고하여야 한다. 이 경우 소장은 특별한 사유가 없으면 보호장비 사용을 즉시 중지하여야 한다.', 6606);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11490, '④ 군의관이 출장, 휴가, 그 밖의 부득이한 사유로 법 제84조제3항의 직무를 수행할 수 없을 때에는 군교정시설에 근무하는 의료관계자에게 그 직무를 대행하게 할 수 있다.', 6606);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11491, '① 소장은 제106조제1항에 따라 보호장비의 사용을 명령한 경우에는 수시로 그 사용 실태를 확인ㆍ점검하여야 한다.', 6608);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11492, '② 국방부장관은 군교정시설의 보호장비 사용 실태를 정기적으로 점검하여야 한다. <개정 2014.10.28>', 6608);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11493, '① 소장은 교정성적이 우수한 군수형자를 선정하여 법 제89조제1항에 따른 응급용무의 보조에 필요한 훈련을 시킬 수 있다.', 6611);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11494, '② 소장은 법 제89조제3항에 따라 군수용자를 일시 석방할 때에는 출석하여야 할 시한과 출석할 장소를 미리 알려주어야 한다.', 6611);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11495, '① 소장은 군수용자가 도주하거나 법 제117조 각 호의 어느 하나에 해당하는 행위(이하 이 조에서 "도주등"이라 한다)를 하였을 때에는 군교정시설의 소재지와 그 인접 지역 또는 도주등을 한 사람(이하 이 조에서 "도주자등"이라 한다)이 숨을 만한 지역의 군사경찰부대나 국가경찰관서에 도주자등의 사진이나 인상착의를 기록한 서면을 첨부하여 그 사실을 지체 없이 통보하여야 한다. <개정 2020.2.4>', 6612);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11496, '② 소장은 군수용자가 도주등을 하거나 도주자등을 체포한 경우에는 국방부장관에게 지체 없이 보고하여야 한다.', 6612);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11497, null, 6613);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11498, '① 위원회의 외부인사인 위원은 다음 각 호의 어느 하나에 해당하는 사람 중에서 소장이 위촉한다. <개정 2012.2.29>', 6614);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11499, '② 제1항에 따라 위촉된 위원의 임기는 2년으로 한다.', 6614);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11500, '③ 소장은 제1항에 따라 위촉된 위원이 직무를 게을리하거나, 품위를 손상하였거나, 특정한 종파나 특정한 사상에 치우쳐 징벌의 공정성을 해칠 우려가 있다고 인정되면 그 위원을 해촉할 수 있다.', 6614);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11501, '① 위원장은 위원회를 대표하고, 위원회의 업무를 총괄한다.', 6615);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11502, '② 위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 위원장이 미리 지명한 위원이 그 직무를 대행한다.', 6615);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11503, '① 위원회에 위원회의 사무를 처리할 간사 1명을 둔다.', 6616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11504, '② 간사는 군교도관 중에서 소장이 임명한다.', 6616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11505, '① 소장은 법 제98조에 따라 위원회가 의결한 징벌을 지체 없이 집행하여야 한다.', 6619);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11506, '② 소장은 군수용자에 대하여 법 제94조제9호의 전화통화 제한, 같은 조 제11호의 서신수수 제한 또는 같은 조 제12호의 접견 제한 징벌을 부과하였을 때에는 군수용자의 가족에게 그 사실을 알려야 한다. 다만, 군수용자가 통지를 원하지 아니하면 그러하지 아니하다.', 6619);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11507, '③ 소장은 법 제94조제14호의 금치(禁置) 징벌을 집행할 때에도 군수용자의 기본적인 건강유지를 위하여 필요하다고 인정하면 실외운동을 허가할 수 있다.', 6619);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11508, '④ 소장은 법 제98조제13호의 실외운동 정지나 같은 조 제14호의 금치 징벌의 집행을 마쳤을 때에는 군의관에게 해당 군수용자의 건강 상태를 지체 없이 확인하게 하여야 한다.', 6619);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11509, '⑤ 군의관이 출장, 휴가, 그 밖의 부득이한 사유로 법 제98조제4항이나 이 조 제4항의 직무를 수행할 수 없을 때에는 군교정시설에 근무하는 의료 관계자에게 그 직무를 대행하게 할 수 있다.', 6619);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11510, '① 소장은 법 제101조제1항에 따라 군수용자가 면담을 신청하였을 때에는 군수용자의 인적사항을 면담부에 적고, 특별한 사정이 없으면 신청한 순서에 따라 면담하여야 한다.', 6624);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11511, '② 소장은 제1항에 따라 군수용자를 면담하였을 때에는 그 요지를 면담부에 적어야 한다.', 6624);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11512, '③ 소장은 법 제101조제2항 각 호의 어느 하나에 해당하여 군수용자의 면담 신청을 받아들이지 아니하였을 때에는 그 사유를 해당 군수용자에게 알려주어야 한다.', 6624);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11513, '① 소장은 군수용자가 법 제102조제1항에 따라 순회점검공무원(법 제7조에 따라 국방부장관으로부터 순회점검의 명을 받은 공무원을 말한다. 이하 같다)에게 청원하는 경우에는 그 인적사항을 청원부에 기록하여야 한다. <개정 2014.10.28>', 6625);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11514, '② 순회점검공무원은 법 제102조제2항 단서에 따라 군수용자가 말로 청원하는 경우에는 그 요지를 청원부에 기록하여야 한다. <개정 2014.10.28>', 6625);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11515, '③ 순회점검공무원은 법 제102조에 따른 군수용자의 청원에 대하여 결정하였을 때에는 그 요지를 청원부에 기록하여야 한다. <개정 2014.10.28>', 6625);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11516, '④ 순회점검공무원은 법 제102조에 따른 군수용자의 청원에 대하여 스스로 결정하는 것이 부적당하다고 인정하는 경우에는 그 내용을 국방부장관에게 보고하여야 한다. <개정 2014.10.28>', 6625);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11517, '⑤ 군수용자의 청원 처리의 기준ㆍ절차 등에 관하여 필요한 사항은 국방부장관이 정한다.', 6625);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11518, null, 6626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11519, '① 군의관은 군수용자가 질병으로 사망한 경우에는 사망기록부에 병명, 병력(病歷), 사인 및 사망 일시를 기록하고 서명하여야 한다.', 6634);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11520, '② 소장은 군수용자가 자살하거나 변사(變事)한 경우에는 그 사실을 즉시 군검사(기소된 군수용자인 경우에는 군사법원을 포함한다)에게 통보하고, 그 시신을 검사한 후 사망기록부에 검시자와 참여자의 성명, 신분 및 검시 결과를 기록하여야 한다. <개정 2014.10.28, 2022.6.30>', 6634);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11521, '③ 소장은 법 제78조에 따라 사형을 집행하였을 때에는 사망기록부에 집행일시, 집행장소, 검시자와 참여자의 성명 및 유언이 있었는지를 기록하여야 한다.', 6634);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11522, '④ 소장은 법 제113조에 따라 시신을 인도(引渡)하거나, 화장(火葬), 임시 매장 또는 합장(合葬)한 경우에는 그 사실을 사망기록부에 기록하여야 한다.', 6634);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11523, '① 소장은 법 제113조제2항 단서에 따라 시신을 화장하였을 때에는 유골을 인수할 사람이 없으면 임시 매장하고, 임시 매장 후 2년이 지나도 인도를 청구하는 사람이 없으면 합장할 수 있다.', 6635);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11524, '② 소장은 법 제113조제3항에 따라 시신을 화장한 경우에는 그 유골을 합장할 수 있다.', 6635);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11525, '① 소장은 법 제113조제2항에 따라 시신을 임시 매장한 경우에는 그 장소에 사망자의 가족관계등록기준지, 성명, 사망 일시를 적은 표지를 세워야 한다.', 6636);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11526, '② 소장은 법 제113조제3항에 따라 시신 또는 유골을 합장한 경우에는 합장된 사람의 가족관계등록기준지, 성명, 사망 일시를 합장기록부에 기록하고 그 장소에 묘비를 세워야 한다.', 6636);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11527, '① 소장은 군수용자의 안정된 수용생활과 교화를 위하여 법 제114조에 따른 교정위원에게 군수용자를 교화상담하게 할 수 있다.', 6637);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11528, '② 교정위원은 군수용자의 고충 처리나 교정ㆍ교화를 위하여 필요한 의견을 소장에게 건의할 수 있다.', 6637);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11529, '① 소장은 법 제115조에 따라 기부금품을 접수하였을 때에는 기부금품 접수대장에 등록하고, 기부한 기관, 단체 또는 개인(이하 이 조에서 "기부자"라 한다)에게 영수증을 발급하여야 한다. 다만, 익명으로 기부하거나 기부자를 알 수 없는 경우에는 영수증을 발급하지 아니한다.', 6638);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11530, '② 소장은 기부자가 용도를 지정하여 금품을 기부한 경우에는 기부금품을 그 용도에 사용하여야 한다. 다만, 지정한 용도로 사용하기 어려운 특별한 사유가 있는 경우에는 기부자의 동의를 받아 다른 용도로 사용할 수 있다.', 6638);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11531, '③ 소장은 기부금품 접수대장과 기부금품의 사용결과를 기록한 장부를 갖춰 두고, 기부자가 열람할 수 있도록 하여야 한다.', 6638);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11532, '④ 제1항부터 제3항까지에서 규정한 사항 외에 군교정시설의 기부금품 접수ㆍ사용 등에 필요한 사항은 국방부장관이 정한다.', 6638);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11533, '① 국방부장관은 법 제115조의2에 따라 다음 각 호의 업무에 관한 권한을 각 군의 참모총장에게 위임한다.', 6639);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11534, '② 국방부장관은 법 제115조의2에 따라 다음 각 호의 업무에 관한 권한을 국방부조사본부장에게 위임한다.', 6639);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11535, null, 6641);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11536, '① 군교도관은 직무를 신속ㆍ정확ㆍ공정하게 처리하고, 그 결과를 지체 없이 상관에게 문서 또는 구두로 보고하여야 한다. 다만, 상관으로부터 특별히 명령받은 직무로서 그 직무처리에 많은 시일이 걸리는 경우에는 그 중간 처리상황을 보고하여야 한다.', 6642);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11537, '② 군교도관은 직무수행 중 다음 각 호의 사유가 발생하면 즉시 소장에게 보고하고 그 지시에 따라 필요한 조치를 하여야 한다.', 6642);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11538, '① 군교도소의 교정업무에 관한 중요사항을 심의하기 위하여 군교도소에 군교도관회의를 둔다.', 6645);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11539, '② 제1항에 따른 군교도관회의는 소장, 부소장, 과장급 직원 및 군교도관 중에서 소장이 임명하는 4명 이상 10명 이하의 군교도관으로 구성한다.', 6645);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11540, '③ 소장은 군교도관회의를 소집하고, 그 의장이 된다.', 6645);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11541, '④ 군교도관회의는 구성원 과반수의 출석으로 개의(開議)하고, 출석위원 과반수의 찬성으로 의결한다.', 6645);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11542, '① 법 제22조에 따라 군수용자에게 지급하는 의류의 품목은 수용복, 전투복, 체육복, 고무신 및 활동화로 한다.', 6646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11543, '② 제1항에 따른 의류의 지급수량, 지급횟수 등에 대한 기준은 「군복 및 군일용품 지급규정」에 따른 현역 군인의 의류지급기준에 따른다.', 6646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11544, '① 법 제22조에 따라 군수용자에게 지급하는 침구의 품목은 이불, 매트리스, 담요 및 베개로 한다.', 6647);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11545, '② 제1항에 따른 침구는 1명당 1매로 한다.', 6647);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11546, '③ 법 제22조에 따라 군수용자에게 지급하는 생활용품의 품목, 지급수량, 지급횟수 등에 대한 기준은 「군복 및 군일용품 지급규정」에 따른 현역 군인의 생활용품의 지급기준에 따른다.', 6647);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11547, '① 자비구매물품은 군교정시설이나 부대 내에서 판매하는 것으로 하며, 종류는 다음 각 호와 같다.', 6650);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11548, '② 국방부장관은 자비구매물품 공급의 군교정시설 간 균형 및 군교정시설의 안전과 질서유지를 위하여 필요한 경우에 공급물품의 품목 및 규격 등에 대한 통일된 기준을 정할 수 있다.', 6650);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11549, '③ 제1항 각 호에 해당하는 자비구매물품의 품목, 유형 및 규격 등에 관한 세부사항은 제2항 및 영 제31조의 기준에 어긋나지 아니하는 범위에서 수용생활에 필요한 정도, 가격과 품질, 다른 군교정시설과의 균형, 공급의 용이성 및 군수용자의 선호도 등을 고려하여 소장이 정한다.', 6650);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11550, '① 소장은 군수용자가 자비구매물품의 구매를 신청하는 경우에는 군교정시설의 보관범위 및 군수용자의 소지범위에서 다음 각 호의 구분에 따라 허가할 수 있다.', 6651);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11551, '② 소장은 감염병(「감염병의 예방 및 관리에 관한 법률」에 따른 감염병을 말한다)의 유행 또는 군수용자의 징벌 집행 등으로 자비구매물품의 사용이 중지된 경우에는 구매신청을 제한할 수 있다. <개정 2014.11.3>', 6651);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11552, '① 소장은 물품공급업무 담당자를 검수관(檢收官)으로 지정하여 자비구매물품 공급자로부터 납품받은 제품의 수량, 상태 및 유통기한 등을 검사하게 하여야 한다.', 6653);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11553, '② 검수관은 공급제품이 부패, 파손, 규격 미달, 그 밖의 사유로 군수용자에게 공급하기에 적당하지 아니하다고 인정하는 경우에는 소장에게 보고하고 필요한 조치를 하여야 한다.', 6653);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11554, '① 소장은 군수용자에게 자비구매물품의 품목ㆍ가격, 그 밖의 구매에 관한 주요사항을 미리 알려주어야 한다.', 6654);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11555, '② 소장은 제품의 변질ㆍ파손, 그 밖의 정당한 사유로 군수용자가 교환 또는 반품을 원하는 경우에는 신속히 적절한 조치를 하여야 한다.', 6654);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11556, '① 소장은 법 제27조에 따라 군수용자 외의 사람이 군수용자에게 금품을 교부하려고 신청하는 경우에는 현금ㆍ수표 및 우편환의 범위에서 허가한다. <개정 2020.2.3>', 6655);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11557, '② 소장은 법 제27조에 따라 군수용자 외의 사람이 군수용자에게 음식물을 교부하려고 신청하는 경우에는 군교정시설에서 판매하는 음식물 중에서 허가한다.', 6655);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11558, '③ 소장은 법 제27조에 따라 군수용자 외의 사람이 군수용자에게 음식물 외의 물품을 교부하려고 신청하는 경우 그 물품이 다음 각 호의 어느 하나에 해당하지 아니하면 군교정시설의 보관범위 및 군수용자의 소지범위에서 허가한다.', 6655);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11559, '① 군교정시설에는「의료법」 제3조에 따른 의료기관 중 의원(醫院)이 갖추어야 하는 시설 이상의 의료시설(진료실 등의 의료용 건축물을 말한다. 이하 같다)을 갖추어야 한다. 다만, 즉시 접근이 가능한 군부대 내에 의료시설을 갖춘 경우는 그러하지 아니하다.', 6656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11560, '② 군교정시설에 갖춰 둬야 하는 의료장비(혈압측정기 등의 의료기기를 말한다)의 기준은 별표 1과 같다.', 6656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11561, '③ 의료시설의 세부종류 및 설치기준은 국방부장관이 정한다.', 6656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11562, '① 소장은 수용정원과 시설여건 등을 고려하여 적정한 양의 비상의료용품을 갖추어야 한다.', 6657);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11563, '② 제1항에 따라 군교정시설에 갖춰 둬야 하는 비상의료용품의 기준은 별표 2와 같다.', 6657);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11564, null, 6658);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11565, '① 소장은 군교정시설의 안전과 질서를 해치지 아니하는 범위에서 종교단체 또는 종교인이 주관하는 종교행사를 실시한다.', 6659);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11566, '② 소장은 종교행사를 위하여 종교별 성상ㆍ성물ㆍ성화ㆍ성구가 구비된 종교관(종교행사를 할 수 있는 종교상담실ㆍ교리교육실 등을 말한다. 이하 같다)을 설치할 수 있으며, 특정 종교행사를 위하여 임시행사장을 설치하는 경우에는 성상 등을 임시로 둘 수 있다.', 6659);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11567, null, 6660);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11568, '① 소장은 군수용자가 종교상담을 신청하거나 군수용자에게 종교상담이 필요한 경우에는 해당 종교를 신봉하는 군교도관 또는 교정참여인사로 하여금 상담하게 할 수 있다.', 6661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11569, '② 소장은 제1항에 따른 종교상담의 중요 내용을 기록하여 군수용자 처우에 활용할 수 있다. 이 경우 군수용자의 개인정보가 유출되지 아니하도록 하여야 한다.', 6661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11570, null, 6662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11571, null, 6664);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11572, '① 군수용자를 대상으로 하는 방송은 무상으로 한다.', 6666);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11573, '② 국방부장관은 방송의 전문성을 강화하기 위하여 외부전문가의 협력을 구할 수 있고, 모든 군교정시설의 군수용자를 대상으로 하는 통합방송을 할 수 있다.', 6666);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11574, '③ 소장은 방송에 대한 의견 수렴을 위하여 설문조사 등의 방법으로 군수용자의 반응도 및 만족도를 측정할 수 있다.', 6666);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11575, '① 소장은 방송을 위하여 텔레비전, 비디오카세트레코더(VCR), 앰프, 스피커 등의 장비와 방송선로 등의 시설을 갖추어야 한다.', 6667);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11576, '② 소장은 물품관리법령에 따라 제1항의 장비와 시설을 정상적으로 유지ㆍ관리하여야 한다.', 6667);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11577, '① 소장은 「방송법」 제2조의 텔레비전방송 또는 라디오방송을 생방송하거나 이를 녹음ㆍ녹화한 것을 방송할 수 있으며, 비디오테이프에 의한 영상물 또는 자체 제작한 영상물을 방송할 수 있다.', 6669);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11578, '② 방송프로그램은 그 내용에 따라 다음 각 호와 같이 구분한다.', 6669);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11579, '③ 소장은 방송프로그램을 자체 편성하는 경우 다음 각 호의 어느 하나에 해당하는 내용이 포함되지 아니하도록 특히 유의하여야 한다.', 6669);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11580, '① 군수용자는 소장이 지정한 장소에서 텔레비전을 시청하거나 라디오방송을 청취를 하여야 한다.', 6670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11581, '② 군수용자는 방송설비 또는 채널을 마음대로 조작ㆍ변경하거나 개인적으로 방송 수신 장비를 소지해서는 아니 된다.', 6670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11582, '③ 군수용자가 군교정시설에 설치된 방송시설과 장비를 손상하거나 그 밖의 방법으로 그 효용을 해친 경우에는 이를 배상하여야 한다.', 6670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11583, null, 6671);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11584, null, 6673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11585, '① 정기심사는 영 제76조에 따라 군수형자의 처우가 개시된 날부터 다음 각 호의 구분에 따른 기간마다 실시한다.', 6674);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11586, '② 정기심사는 제1항 각 호에 해당하는 날이 해당 월 15일 이전에 속한 경우에는 그 달 25일까지, 해당 월 15일 이후에 속한 경우에는 그 다음달 10일까지 하여야 한다.', 6674);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11587, '③ 정기심사일과 제35조에 따른 형기의 3분의 1 심사일이 같을 때에는 형기의 3분의 1 심사를 정기심사에 갈음한다.', 6674);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11588, '④ 정기심사 기간에 제35조에 따른 형기의 3분의 1 심사 또는 제36조에 따른 특별심사를 하였을 때에는 그 심사일부터 제1항에 따른 정기심사의 기간을 계산한다.', 6674);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11589, null, 6675);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11590, '① 특별심사는 다음 각 호의 어느 하나에 해당하는 경우에 실시한다.', 6676);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11591, '② 특별심사 대상자는 군교도관회의에서 결정한다.', 6676);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11592, null, 6677);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11593, '① 군교도소에 처음으로 입소한 군수형자의 처우등급은 4급으로 하고, 차례로 상위등급으로 승급시킨다.', 6679);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11594, '② 법 제93조에 따른 징벌을 받은 군수형자에 대해서는 그 정상(情狀)에 따라 처우등급을 1등급 이상 강등시킬 수 있다.', 6679);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11595, '③ 제2항에 따라 강등된 군수형자에 대해서는 징벌기간이 만료된 날부터 제34조에 따른 정기심사 기간을 계산한다.', 6679);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11596, '① 소장은 군수형자에 대하여 처우등급 심사를 하였을 때에는 별지 제2호서식의 처우등급심사표를 작성ㆍ관리하여야 한다.', 6681);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11597, '② 소장은 군수형자를 다른 교도소로 이송할 때에는 제1항에 따른 처우등급심사표를 그 군수형자가 이송되는 교도소의 소장에게 송부하여야 한다.', 6681);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11598, '① 소장은 형의 집행정지 중에 있는 사람이 기간만료 그 밖의 정지사유 소멸로 재수용된 경우에는 석방 당시와 동일한 처우등급을 부여한다.', 6683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11599, '② 소장은 가석방 취소로 재수용되어 남은 형이 집행되는 경우에는 석방 당시보다 한 단계 낮은 처우등급을 부여한다. 다만, 특히 고려할 만한 사유가 있는 때에는 석방 당시와 동일한 처우등급을 부여할 수 있다. <개정 2020.2.3>', 6683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11600, '① 소장은 처우등급 2급 이상의 군수형자 중 교정성적, 나이, 인성 등을 고려하여 다른 군수형자의 모범이 된다고 인정되는 사람을 봉사원으로 선정하여 담당 군교도관의 사무처리 그 밖의 업무를 보조하게 할 수 있다.', 6686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11601, '② 봉사원의 활동기간은 6개월로 하되, 필요한 경우에는 그 기간을 1회 연장할 수 있다.', 6686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11602, '③ 소장은 봉사원의 활동과 역할수행이 적당하지 아니하다고 인정하는 경우에는 선정을 취소할 수 있다.', 6686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11603, '④ 봉사원의 선정, 기간연장 및 선정취소에 관한 사항은 군교도관회의 의결로 정한다.', 6686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11604, '① 소장은 군수용자의 처우를 위하여 필요하다고 인정되면 처우등급 2급 이상의 군수형자에게 자치생활을 하게 할 수 있다. 다만, 처우상 특히 필요한 경우에는 처우등급 3급 이하의 군수형자를 포함할 수 있다.', 6687);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11605, '② 제1항에 따른 자치생활의 범위는 인원 점검, 취미활동, 일정한 구역에서의 생활 등으로 한다.', 6687);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11606, '③ 소장은 제1항에 따라 자치생활을 하는 군수형자들이 교육실ㆍ강당 등 적당한 장소에서 월 1회 이상 토론회를 할 수 있도록 하여야 한다.', 6687);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11607, '④ 소장은 군수형자가 국방부장관 또는 소장이 정하는 자치생활에 관한 준수사항을 위반한 경우에는 자치생활의 허가를 취소할 수 있다.', 6687);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11608, null, 6688);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11609, '① 소장은 군수형자의 교정ㆍ교화와 사회생활 적응 능력을 기르도록 처우하기 위하여 군교정시설에 수용시설과 별도로 군수형자와 그 가족이 숙식을 함께할 일반주택 형태의 건축물(이하 "가족 만남의 집"이라 한다)을 설치할 수 있고, 군수형자와 그 가족이 군교정시설 내의 일정한 장소에서 다과와 음식을 함께 나누면서 대화의 시간을 갖는 행사(이하 "가족 만남의 날 행사"라 한다)를 할 수 있다.', 6690);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11610, '② 소장은 처우등급 2급 이상의 군수형자에 대하여 가족 만남의 집을 이용하게 하거나 가족 만남의 날 행사에 참여하게 할 수 있다. 이 경우 제48조에 따른 접견 허용횟수에는 포함하지 아니한다.', 6690);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11611, '③ 소장은 가족이 없는 군수형자에 대해서는 자매결연자 또는 후원자 등에게 가족을 대신하여 가족 만남의 날 행사에 참여하게 할 수 있다.', 6690);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11612, '④ 소장은 제2항 전단에도 불구하고 교화를 위하여 특히 필요한 경우에는 처우등급 3급 이하의 군수형자에게도 가족 만남의 집 이용이나 가족 만남의 날 행사에 참여하도록 할 수 있다.', 6690);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11613, '① 군수형자의 처우등급별 전화통화의 허용횟수는 다음 각 호와 같다.', 6691);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11614, '② 소장은 제1항에도 불구하고 처우상 특히 필요한 경우에는 처우등급 2급 이상 군수형자의 전화통화 허용횟수를 늘릴 수 있으며, 처우등급 3급 이하 군수형자에게도 전화통화를 허가할 수 있다.', 6691);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11615, '① 소장은 처우등급 2급 이상인 군수형자 중에서 작업기술이 탁월하고 작업성적이 우수한 군수형자에게 자신을 위한 개인작업을 하게 할 수 있다. 이 경우 개인작업 시간은 교도작업에 지장을 주지 아니하는 범위에서 1일 2시간 이내로 한다.', 6693);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11616, '② 소장은 제1항에 따라 개인작업을 하는 군수형자에게 개인작업 용구를 사용하게 할 수 있다. 이 경우 작업용구는 특정한 용기에 보관하도록 하여야 한다.', 6693);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11617, '③ 개인작업에 필요한 작업재료 등의 구입비용은 군수형자가 부담한다. 다만, 처우상 필요한 경우에는 예산의 범위에서 그 비용을 지원할 수 있다.', 6693);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11618, '① 소장은 처우등급 2급 이상인 군수형자 중에서 직업능력 향상을 위하여 특히 필요하다고 인정하는 경우에는 군교정시설 외의 공공기관 또는 기업체 등에서 운영하는 직업훈련을 받게 할 수 있다.', 6694);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11619, '② 제1항에 따른 직업훈련의 비용은 군수형자가 부담한다. 다만, 처우상 특히 필요한 경우에는 예산의 범위에서 그 비용을 지원할 수 있다.', 6694);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11620, '① 소장은 법 제53조제1항 및 제2항에 따른 교육대상자를 각 교육과정의 교육계획, 교육시설의 규모, 교육대상인원과 군수형자의 나이, 학력, 교정성적, 자체 평가시험 성적, 정신자세, 성실성 등을 고려하여 선발하여야 한다.', 6695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11621, '② 소장은 군수형자가 정당한 이유 없이 법 제53조에 따른 교육을 기피하였거나 교육기관에서 자퇴(제적을 포함한다)한 사실이 있을 때에는 교육대상자로 선발하지 아니할 수 있다.', 6695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11622, '① 소장은 교육대상자가 다음 각 호의 어느 하나에 해당하는 경우에는 교육대상자 선발을 취소할 수 있다.', 6696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11623, '② 소장은 교육대상자가 질병에 걸리거나 부상을 당한 경우, 그 밖의 부득이한 사정이 있는 경우에는 교육과정을 일시 중지할 수 있다.', 6696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11624, null, 6697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11625, '① 소장은 다음 각 호의 시험을 준비하는 군수형자 중 제59조제2항 각 호의 요건을 갖춘 사람을 대상으로 검정고시반을 설치ㆍ운영할 수 있다.', 6698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11626, '② 소장은 교육기간에 검정고시에 합격한 군수형자에 대하여 해당 교육과정을 조기 수료시키거나 상위 교육과정에 임시 배치시킬 수 있다.', 6698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11627, '① 소장은 고등학교과정의 교육기회를 부여하기 위하여 「초ㆍ중등교육법」 제51조에 따른 방송통신고등학교 교육과정을 설치ㆍ운영할 수 있다.', 6699);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11628, '② 소장은 다음 각 호의 요건을 갖춘 군수형자가 방송통신고등학교 교육과정에 지원하여 합격한 경우에는 교육생으로 선발할 수 있다.', 6699);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11629, '③ 제1항의 교육에 필요한 비용은 자비부담을 원칙으로 한다. 다만, 소장은 제1항의 방송통신고등학교 교육과정의 입학금, 수업료, 교과용 도서구입비 등 교육에 필요한 비용을 예산 범위에서 지원할 수 있다.', 6699);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11630, '① 군사교육훈련은 정신교육, 제식훈련 등 기본군사훈련을 위주로 실시한다.', 6701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11631, '② 소장은 군사교육훈련이 군수형자에 대한 징벌수단, 보복조치로 악용되지 않도록 주의하여야 한다.', 6701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11632, '① 소장은 교육ㆍ훈련기간 중 각 교육과목에 대한 성적평가를 위하여 시험 또는 교육사열(敎育査閱)을 실시하여야 한다.', 6705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11633, '② 소장은 시험 또는 교육사열 결과 성적이 불량하여 교육ㆍ훈련의 효과를 거두지 못하였다고 인정되는 군수형자에 대해서는 다시 교육ㆍ훈련을 실시할 수 있다.', 6705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11634, '③ 소장은 군사교육훈련과정 외 교육과정에서 성적이 현저히 불량한 군수형자에 대하여 해당 교육과정을 중단시킬 수 있다.', 6705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11635, null, 6709);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11636, '① 소장은 군수형자와 그 가족의 관계를 유지ㆍ회복하기 위하여 군수형자의 가족이 참여하는 각종 프로그램을 실시할 수 있다. 다만, 가족이 없는 군수형자의 경우 교화를 위하여 필요하면 결연을 맺은 사람이나 그 밖에 가족에 준하는 사람의 참여를 허가할 수 있다.', 6712);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11637, '② 제1항에 따른 가족관계 회복프로그램의 대상이 되는 군수형자는 제50조에 따라 가족 만남의 집을 이용하거나 가족 만남의 날 행사에 참여할 수 있는 사람을 대상자로 하여 군교정시설 안에서 실시하며, 참여인원은 5명 이내의 가족으로 한다. 다만, 특히 필요하다고 인정하는 경우에는 참여인원을 늘릴 수 있다.', 6712);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11638, '① 소장은 군수형자의 건전한 가치관 형성, 정서안정, 고충 해소 등을 위하여 교화상담을 실시할 수 있다.', 6713);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11639, '② 소장은 제1항에 따른 교화상담을 위하여 군교도관이나 교정참여인사를 교화상담자로 지정할 수 있고, 군수형자의 안정을 위하여 결연을 주선할 수 있다.', 6713);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11640, '① 소장은 교화프로그램을 운영하는 경우에 성폭력, 약물중독, 정신질환 등 군수형자의 개별 특성을 고려하여야 하며, 프로그램의 성격 및 시설의 규모와 인원을 고려하여 이송 등의 적절한 조치를 할 수 있다.', 6714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11641, '② 소장은 교화프로그램의 운영을 위하여 군수형자의 정서적인 안정이 보장될 수 있는 장소를 따로 정하거나 방송설비 및 방송기기를 이용할 수 있다.', 6714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11642, '③ 소장은 교화프로그램의 주요 진행내용을 기록하여 군수형자 처우에 활용하여야 하며, 상담내용 등 개인정보가 유출되지 아니하도록 하여야 한다.', 6714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11643, '① 영 제81조제3항에 따른 작업의 종류는 군납물품 생산 및 관용작업으로 한다.', 6715);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11644, '② 영 제81조제3항에 따른 작업시간은 1일 8시간 이하로 한다.', 6715);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11645, '③ 제1항에 따른 작업의 구체적인 내용은 국방부조사본부장의 승인을 받아 소장이 정한다. <개정 2014.11.3>', 6715);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11646, '① 소장은 작업실적ㆍ작업시간을 참작하여 작업에 종사한 군수형자에게 작업등급을 부여하여야 한다.', 6717);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11647, '② 제1항에 따른 작업등급은 다음 각 호의 구분에 따른다.', 6717);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11648, '③ 소장은 작업성적 및 품행이 특히 우수하다고 인정되는 군수형자에 대해서는 제2항 각 호에 규정된 작업기간의 2분의 1 이상을 종사하였을 때에 바로 상위의 작업등급을 부여할 수 있다.', 6717);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11649, '① 법 제58조제2항에 따른 외부통근자의 선정기준은 다음 각 호와 같다.', 6718);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11650, '② 소장은 제1항에도 불구하고 작업의 성격이나 교화를 위하여 특히 필요하다고 인정하는 경우에는 제1항의 군수형자 외의 군수형자도 외부통근자로 선정할 수 있다.', 6718);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11651, '① 법 제59조에 따른 기술 습득 및 향상을 위한 직업능력개발훈련(이하 "직업훈련"이라 한다)의 직종 선정 및 훈련과정별 인원은 국방부조사본부장의 승인을 받아 소장이 정한다. <개정 2014.11.3>', 6723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11652, '② 직업훈련 대상자는 소속 기관의 군수형자 중에서 소장이 선정한다.', 6723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11653, null, 6724);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11654, null, 6725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11655, '① 국방부장관은 직업훈련을 위하여 필요한 경우에는 군수형자를 다른 군교정시설로 이송할 수 있다.', 6726);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11656, '② 소장은 제1항에 따라 이송된 군수형자나 직업훈련 중인 군수형자를 다른 군교정시설로 이송해서는 아니 된다. 다만, 훈련 취소 등 특별한 사유가 있는 경우에는 그러하지 아니하다.', 6726);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11657, '① 소장은 직업훈련 대상자가 다음 각 호의 어느 하나에 해당하는 경우에는 직업훈련을 보류할 수 있다.', 6727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11658, '② 소장은 제1항에 따라 직업훈련이 보류된 군수형자의 보류 사유가 소멸된 경우에는 본래의 과정에 복귀시켜 훈련할 수 있게 하여야 한다. 다만, 본래 과정으로 복귀시키는 것이 적당하지 아니하다고 인정되는 경우에는 해당 훈련을 취소할 수 있다.', 6727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11659, '① 법 제66조제1항제4호에서 "교화나 건전한 사회복귀를 위하여 국방부령으로 정하는 사유"란 다음 각 호의 어느 하나에 해당하는 사유를 말한다.', 6728);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11660, '② 소장은 처우등급 2급 이상인 군수형자에 한정하여 법 제66조에 따라 귀휴를 허가할 수 있다. 다만, 교정ㆍ교화 또는 사회복귀 준비 등을 위하여 특히 필요한 경우에는 처우등급 3급의 군수형자에게도 귀휴를 허가할 수 있다.', 6728);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11661, '① 소장은 법 제66조에 따라 귀휴를 허가할 때에는 제90조의 귀휴심사위원회의 심사를 거쳐야 한다.', 6729);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11662, '② 제1항에도 불구하고 소장은 토요일, 공휴일 그 밖의 사유로 귀휴심사위원회의 소집이 곤란할 때에는 귀휴심사위원회 심사를 거치지 아니하고 귀휴를 허가할 수 있다. 다만, 이 경우 다음 각 호에 해당하는 부서의 장의 의견을 들어야 한다.', 6729);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11663, '③ 제2항 각 호에 해당하는 부서의 장은 제97조의 서류를 검토하여 그 의견을 지체 없이 소장에게 보고하여야 한다.', 6729);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11664, null, 6731);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11665, '① 위원회는 위원장 1명을 포함한 5명 이상 7명 이하의 위원으로 구성한다.', 6732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11666, '② 위원회의 위원장은 소장이 되고, 위원회의 위원은 소장이 소속 군교도관과 교정에 관한 학식과 경험이 풍부한 사람 중에서 임명하거나 위촉한다. 이 경우 위촉위원은 2명 이상으로 한다.', 6732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11667, '① 위촉위원의 임기는 2년으로 한다.', 6733);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11668, '② 위원장은 위촉위원이 다음 각 호의 어느 하나에 해당하는 경우에는 위촉을 해제할 수 있다.', 6733);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11669, '③ 위촉위원에 대해서는 예산의 범위에서 수당과 여비를 지급할 수 있다.', 6733);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11670, '① 위원장은 위원회를 대표하고, 위원회의 업무를 총괄한다.', 6734);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11671, '② 위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 위원장이 미리 지명한 위원이 그 직무를 대행한다.', 6734);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11672, '① 위원장은 위원회의 회의를 소집하고, 그 의장이 된다.', 6735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11673, '② 위원회의 회의는 재적위원 과반수의 출석으로 개의(開議)하고, 출석위원 과반수의 찬성으로 의결한다.', 6735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11674, '① 위원회에 위원회의 사무를 처리할 간사 1명을 둔다.', 6736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11675, '② 간사는 소속 군교도관 중에서 소장이 임명한다.', 6736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11676, '③ 간사는 별지 제6호서식의 귀휴심사위원회 회의록을 작성하여 보관하여야 한다.', 6736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11677, '① 귀휴심사에 필요한 서류는 다음 각 호와 같다.', 6737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11678, '② 소장은 심사대상자에게 별지 제9호서식의 지도보증서를 위원회에 제출하게 하여야 한다. 이 경우 법 제66조제1항제1호부터 제3호까지의 사유에 해당하는 군수형자에 대해서는 별지 제10호서식의 사실확인서를 같이 제출하도록 하여야 한다.', 6737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11679, '① 소장은 심사대상자의 심사에 필요한 경우에는 군수용자의 가족 등을 면담하거나 군사법원, 군검찰부, 헌병부대 그 밖의 관계 기관이나 단체에 대하여 필요한 사실조회를 할 수 있다.', 6738);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11680, '② 소장은 심사대상자의 보호관계 등을 알아보는 데 필요하다고 인정하는 경우에는 그의 가족 또는 보호관계에 있는 사람에게 위원회의 참석을 요청할 수 있다.', 6738);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11681, null, 6741);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11682, '① 소장은 법 제66조제3항에 따라 군수형자에게 귀휴를 허가하는 경우 필요하다고 인정하면 군교도관 또는 헌병을 동행시킬 수 있다.', 6742);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11683, '② 소장은 귀휴자를 출발시키기 전에 귀휴자의 가족 또는 보호관계에 있는 사람으로부터 별지 제13호서식의 지도보증서를 제출받아야 한다.', 6742);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11684, '③ 영 제86조제1항에 따라 헌병대 또는 국가경찰관서의 장에게 귀휴사실을 통보하는 경우에는 별지 제14호서식에 따른다.', 6742);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11685, '① 귀휴자의 여비와 귀휴 중 착용할 의류 등은 본인이 부담한다.', 6743);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11686, '② 소장은 귀휴자의 신청이 있는 경우에 작업장려금의 전부 또는 일부를 귀휴비용으로 사용하게 할 수 있다.', 6743);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11687, '① 소장은 귀휴자가 정당한 사유없이 귀휴 기간 만료 시까지 군교도소에 복귀하지 아니한 경우에는 지체없이 귀휴지 및 그 부근 또는 연고지 등 숨을 가능성이 많은 지역의 군부대 및 경찰관서의 장에게 사진 또는 인상 설명서를 첨부하여 그 사실을 통보하여야 한다. <개정 2020.2.3>', 6744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11688, '② 소장은 제1항의 경우 그 사실을 국방부조사본부장에게 보고하여야 한다. 해당 귀휴자를 체포한 경우에도 또한 같다. <개정 2014.11.3>', 6744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11689, '③ 소장은 귀휴자가 제101조에 따른 귀휴지의 제한이나 그 밖에 소장이 지시한 사항을 위반한 사실을 알게 되었을 때에는 지체 없이 귀휴허가를 취소하거나 군교도관으로 하여금 필요한 조치를 하게 하여야 한다.', 6744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11690, '① 소장은 사형확정자의 심리적 안정 및 원만한 수용생활을 위하여 소속 군교도관에게 지속적으로 상담하게 하여야 한다.', 6746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11691, '② 제1항의 상담책임자는 상담 관련 전문교육을 이수한 군교도관을 우선하여 지정하여야 한다.', 6746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11692, '③ 제2항에 따라 지정된 상담책임자는 상담대상자에 대하여 월 1회 이상 개별상담을 함으로써 신속한 고충 처리와 원만한 수용생활 지도를 위하여 노력하여야 한다.', 6746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11693, '④ 제3항에 따라 상담책임자가 상담하였을 때에는 그 요지와 처리결과 등을 별지 제15호서식의 사형확정자 상담결과 보고서에 기록하여 소장에게 보고하여야 한다.', 6746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11694, '① 소장은 법 제77조제2항에 따라 사형확정자를 혼거수용할 때에는 거실 및 작업장 등의 봉사원, 반장, 조장, 분임장, 그 밖에 군수용자를 대표하는 직책을 부여해서는 아니 된다.', 6747);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11695, '② 소장은 법 제77조제3항에 따라 사형확정자가 작업을 신청하는 경우에는 군교도관회의를 거쳐 군교정시설 안에서 하는 작업을 부과할 수 있다. 이 경우 부과하는 작업은 심리적 안정과 원만한 수용생활을 도모하는 데 적합한 것이어야 한다.', 6747);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11696, '③ 소장은 제2항에 따라 작업을 부과한 사형확정자에 대하여 군교도관회의를 거쳐 제105조를 적용하지 아니할 수 있다.', 6747);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11697, '④ 소장은 제2항에 따라 작업이 부과된 사형확정자가 작업의 취소를 요청하는 경우에는 사형확정자의 의사, 건강, 담당 군교도관의 의견 등을 고려하여 작업을 취소할 수 있다.', 6747);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11698, '⑤ 제2항에 따른 사형확정자에 대한 작업부과에 관하여는 법 제61조부터 제65조까지의 규정을 준용한다.', 6747);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11699, null, 6750);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11700, '① 소장은 교정장비의 보관 및 관리를 위하여 관리책임자와 보조자를 지정한다.', 6751);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11701, '② 제1항에 따라 지정된 관리책임자와 보조자는 교정장비가 적정상태로 보관ㆍ관리될 수 있도록 수시로 점검하는 등 필요한 조치를 하여야 한다.', 6751);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11702, '③ 특정장소에 고정식으로 설치되는 장비 이외의 교정장비는 별도의 장소에 보관ㆍ관리하여야 한다.', 6751);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11703, null, 6753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11704, '① 소장은 전자장비의 효율적인 운용을 위하여 각종 전자장비를 통합 관리할 수 있는 시스템이 설치된 중앙통제실을 설치하여 운영하여야 한다.', 6754);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11705, '② 소장은 제1항의 중앙통제실에는 외부인의 출입을 제한하여야 한다. 다만, 시찰ㆍ참관 그 밖에 소장이 특별히 허가한 경우에는 그러하지 아니하다.', 6754);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11706, '③ 전자장비의 통합관리시스템, 중앙통제실의 운영ㆍ관리 등에 관하여 필요한 사항은 국방부장관이 정한다.', 6754);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11707, '① 영상정보처리기기 카메라는 군교정시설의 벽둘레ㆍ감시대ㆍ울타리ㆍ운동장ㆍ거실ㆍ작업장ㆍ접견실ㆍ전화실ㆍ조사실ㆍ진료실ㆍ복도ㆍ통용문 그 밖에 법 제81조제1항에 따라 전자장비를 이용하여 계호하여야 할 필요가 있는 장소에 설치한다. <개정 2020.2.3>', 6755);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11708, '② 영상정보처리기기 모니터는 중앙통제실ㆍ관구실 그 밖에 군교도관이 계호하기에 적정한 장소(이하 "중앙통제실등"이라 한다)에 설치한다.', 6755);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11709, '③ 거실에 영상정보처리기기 카메라를 설치하는 경우에는 용변을 보는 하반신의 모습이 촬영되지 아니하도록 카메라의 각도를 한정하거나 화장실 가림막시설을 설치하여야 한다.', 6755);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11710, '① 군교도관 및 교도병(이하 "군교도관등"이라 한다)이 법 제81조제1항에 따라 거실에 있는 군수용자를 계호하는 경우에는 별지 제16호서식의 거실군수용자 영상계호부에 군교도관과 교도병의 직급ㆍ성명, 계호시간 및 계호대상 등을 기록하여야 한다.', 6756);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11711, '② 군교도관이 법 제81조제1항에 따라 계호하는 과정에서 군수용자의 처우 및 관리에 특히 참고할 사항을 알게 된 경우에는 그 요지를 수용기록부에 기록하여 소장에게 지체 없이 보고하여야 한다.', 6756);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11712, '① 고정식 물품검색기는 정문ㆍ수용동입구ㆍ작업장입구, 그 밖에 군수용자 또는 군교정시설을 출입하는 군수용자 외의 사람(이하 "외부인"이라 한다)의 신체ㆍ의류ㆍ휴대품의 검사가 필요한 장소에 설치한다.', 6759);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11713, '② 군교도관등이 법 제80조제1항에 따라 군수용자의 신체ㆍ의류ㆍ휴대품을 검사하는 경우에는 특별한 사정이 없으면 고정식 물품검색기를 통과하게 한 후 휴대식 금속탐지기 또는 손으로 이를 확인한다.', 6759);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11714, '③ 군교도관등이 법 제80조제3항에 따라 외부인의 의류와 휴대품을 검사하는 경우에는 고정식 물품검색기를 통과하게 하거나 휴대식 금속탐지기로 이를 확인한다.', 6759);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11715, null, 6762);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11716, '① 보호장비의 규격은 별표 3과 같다.', 6763);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11717, '② 군교도관은 제1항에 따른 규격에 맞지 아니한 보호장비를 군수용자에게 사용해서는 아니 된다.', 6763);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11718, '① 수갑의 사용방법은 다음 각 호와 같다.', 6765);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11719, '② 제1항제1호에 따라 수갑을 사용하는 경우에는 수갑보호기를 함께 사용할 수 있다.', 6765);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11720, '③ 제1항제2호에 따라 별표 5의 방법으로 수갑을 사용하여 그 목적을 달성한 후에는 즉시 별표 4의 방법으로 전환하거나 사용을 중지하여야 한다.', 6765);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11721, '④ 수갑은 구체적 상황에 적합한 종류를 선택하여 사용할 수 있다. 다만, 일회용 수갑은 일시적으로 사용하여야 하며, 사용목적을 달성한 후에는 즉시 사용을 중지하거나 다른 보호장비로 교체하여야 한다.', 6765);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11722, null, 6767);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11723, null, 6768);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11724, '① 보호의자의 사용은 별표 12의 방법으로 하며, 다른 보호장비로는 법 제84조제1항제2호부터 제4호까지의 어느 하나에 해당하는 행위를 방지하기 어려운 특별한 사정이 있는 경우에만 사용하여야 한다.', 6769);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11725, '② 보호의자의 사용은 제137조제2항에 따라 그 사용을 일시 해제하거나 완화하는 경우를 포함하여 8시간을 초과할 수 없으며, 해제 후 4시간이 지나지 아니하면 다시 사용할 수 없다.', 6769);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11726, '① 보호침대의 사용은 별표 13의 방법으로 하며, 다른 보호장비로는 자살ㆍ자해를 방지하기 어려운 특별한 사정이 있는 경우에만 사용하여야 한다.', 6770);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11727, '② 보호침대의 사용에 관하여는 제129조제2항을 준용한다.', 6770);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11728, '① 보호복의 사용은 별표 14의 방법으로 한다.', 6771);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11729, '② 보호복의 사용에 관하여는 제129제2항을 준용한다.', 6771);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11730, '① 포승의 사용방법은 다음 각 호와 같다.', 6772);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11731, '② 제1항제2호에 따라 포승을 사용하여 2명 이상의 군수용자를 호송하는 경우에는 군수용자 간에 포승을 연결하여 사용할 수 있다.', 6772);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11732, '③ 개인포승은 일시적으로 사용하여야 하며, 계속하여 사용할 필요가 있는 경우에는 일반포승으로 교체하여야 한다.', 6772);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11733, '① 소장은 보호장비를 착용 중인 군수용자에 대하여 보호장비사용 심사부 및 보호장비착용자 관찰부 등의 기록과 관계직원의 의견 등을 토대로 보호장비의 계속 사용 여부를 매일 심사하여야 한다.', 6776);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11734, '② 소장은 영 제106조에 따라 군의관 또는 의료관계 직원이 보호장비 사용의 중지를 건의하였음에도 불구하고 해당 군수용자에 대하여 보호장비를 계속하여 사용할 필요성이 있다고 판단하는 경우에는 군의관 또는 의료관계 직원에게 건강유지에 필요한 조치를 취할 것을 명하고 보호장비를 계속하여 사용할 수 있다. 이 경우 소장은 보호장비사용 심사부에 보호장비를 계속 사용할 필요가 있다고 판단하는 근거를 기록하여야 한다.', 6776);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11735, '① 군교도관은 법 제84조제1항 각 호에서 정한 보호장비 사용 사유가 소멸한 경우에는 소장의 허가를 받아 지체 없이 사용중인 보호장비를 해제하여야 한다. 다만, 군교도관이 소장의 허가를 받을 시간적 여유가 없을 때에는 보호장비를 해제한 후 지체 없이 소장의 승인을 받아야 한다.', 6777);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11736, '② 군교도관은 보호장비 착용 군수용자의 목욕ㆍ식사ㆍ용변ㆍ치료 등을 위하여 필요한 경우에는 보호장비 사용을 일시 해제하거나 완화할 수 있다.', 6777);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11737, null, 6779);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11738, '① 군교도관등이 군수용자에 대하여 사용할 수 있는 보안장비의 종류별 사용요건은 다음 각 호와 같다.', 6780);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11739, '② 군교도관등이 군수용자 외의 사람에 대하여 사용할 수 있는 보안장비의 종류별 사용요건은 다음 각 호와 같다.', 6780);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11740, '③ 제139조제7호에 해당하는 보안장비의 사용은 국방부장관이 정하는 바에 따른다.', 6780);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11741, null, 6781);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11742, null, 6782);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11743, '① 군교도관등이 군수용자에 대하여 사용할 수 있는 무기의 종류별 사용요건은 다음 각 호와 같다.', 6783);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11744, '② 군교도관등이 군수용자 외의 사람에 대하여 사용할 수 있는 무기의 종류별 사용요건은 다음 각 호와 같다.', 6783);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11745, '③ 제142조제4호에 해당하는 무기의 사용은 국방부장관이 정하는 바에 따른다.', 6783);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11746, '① 소장은 소속 군교도관(현역 군인만 해당한다)에 대하여 연 1회 이상 총기의 조작ㆍ정비ㆍ사용에 관한 교육을 실시한다.', 6786);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11747, '② 총기 및 탄약의 정비ㆍ취급 및 사격요령은 각군의 참모총장 또는 국방부조사본부장이 정한다. <개정 2014.11.3>', 6786);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11748, '③ 총기 조작훈련을 받지 아니하였거나 그 조작이 미숙한 사람, 그 밖에 총기휴대가 부적당하다고 인정되는 사람에 대해서는 총기의 휴대를 금지하고 별지 제19호서식의 총기휴대 금지자 명부에 그 명단을 기록한 후 총기를 지급할 때마다 대조ㆍ확인하여야 한다.', 6786);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11749, '④ 제3항의 총기휴대 금지자에 대하여 금지사유가 소멸한 경우에는 그 사유를 총기휴대금지자명부에 기록하고 총기휴대금지를 해제하여야 한다.', 6786);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11750, '① 소장은 법 제92조에 따라 군수용자를 포상할 때에는 제6조에 따른 군교도관회의의 의결을 거쳐야 한다.', 6787);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11751, '② 소장은 군수형자가 법 제92조 각 호의 어느 하나에 해당하면 포상과 함께 제36조에 따른 특별심사를 할 수 있다.', 6787);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11752, null, 6788);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11753, null, 6790);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11754, null, 6791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11755, null, 6792);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11756, '① 소장은 군수용자의 징벌대상행위에 대한 조사를 시작한 날부터 10일 이내에 다음 각 호의 어느 하나에 해당하는 조치를 하여야 한다. 다만, 특히 필요하다고 인정하는 경우에는 7일을 초과하지 아니하는 범위에서 한 차례만 조사기간을 연장할 수 있다.', 6793);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11757, '② 제1항에 따른 조사기간 중 법 제96조제3항에 따라 징벌대상자에 대하여 처우를 제한하는 경우에는 징벌위원회의 의결을 거쳐 그 기간의 전부 또는 일부를 징벌기간에 산입할 수 있다.', 6793);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11758, '③ 소장은 징벌대상행위가 징벌대상자의 정신병적인 원인에 따른 것으로 의심할만한 충분한 사유가 있는 경우에는 징벌절차에 우선하여 의사의 진료, 전문가 상담 등 필요한 조치를 하여야 한다.', 6793);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11759, '④ 소장은 군의관의 소견과 제3항에 따른 의사의 진료, 전문가 상담 등에서 징벌대상자의 징벌대상행위가 정신병적인 원인에 따른 것이라고 판정된 경우에는 징벌위원회에 징벌을 요구할 수 없다.', 6793);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11760, '① 소장은 징벌대상자의 질병이나 그 밖의 특별한 사정으로 조사를 계속하기 어려운 경우에는 조사를 일시적으로 정지할 수 있다.', 6795);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11761, '② 제1항에 따라 정지된 조사기간은 그 사유가 해소된 때부터 다시 진행된다. 이 경우 조사가 정지된 다음 날부터 정지사유가 소멸한 전날까지의 기간은 조사기간에 산입되지 아니 한다.', 6795);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11762, '① 소장은 징벌대상자에 대한 조사가 끝났을 때에는 별지 제20호서식의 징벌의결 요구서를 작성하여 징벌위원회에 징벌 의결을 요구하여야 한다.', 6796);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11763, '② 제1항에 따른 징벌의결 요구서에는 징벌대상행위의 입증에 필요한 관계서류를 첨부할 수 있다.', 6796);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11764, '① 징벌위원회가 제156조에 따른 징벌의결요구서를 접수한 경우에는 지체 없이 징벌대상자에게 별지 제21호서식의 징벌위원회 출석통지서를 전달하여야 한다.', 6797);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11765, '② 제1항에 따른 출석통지서에는 다음 각 호의 내용이 포함되어야 한다.', 6797);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11766, '③ 제1항에 따라 출석통지서를 전달받은 징벌대상자가 징벌위원회에 출석하는 것을 원하지 아니하는 경우에는 별지 제22호서식의 출석포기서를 징벌위원회에 제출하여야 한다.', 6797);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11767, '① 징벌위원회는 출석한 징벌대상자를 심문하고, 필요하다고 인정하는 경우에는 군교도관이나 다른 군수용자 등을 참고인으로 출석시켜 심문할 수 있다.', 6798);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11768, '② 징벌위원회는 징벌대상자에게 제157조제1항에 따른 출석통지서를 전달하였음에도 불구하고 징벌대상자가 출석포기서를 제출하거나 정당한 사유 없이 출석하지 아니한 경우에는 그 사실을 별지 제23호서식의 징벌위원회 회의록에 기록하고 서면심리만으로 징벌을 의결할 수 있다.', 6798);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11769, '③ 징벌의 의결은 별지 제24호서식의 징벌의결서에 따른다.', 6798);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11770, '④ 징벌위원회가 작업장려금의 삭감을 의결하려면 미리 군수용자의 작업장려금을 확인하여야 한다.', 6798);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11771, '⑤ 징벌위원회의 회의에 참여한 사람은 직무상 알게 된 비밀을 누설해서는 아니 된다.', 6798);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11772, '① 금치와 다른 징벌을 함께 집행할 때에는 작업장려금의 삭감과 경고를 제외하고는 금치를 우선하여 집행한다.', 6800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11773, '② 같은 종류의 징벌은 그 기간이 긴 것부터 집행한다.', 6800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11774, '③ 금치를 제외한 다른 종류의 징벌은 함께 집행할 수 있다.', 6800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11775, '① 작업장려금의 삭감은 징벌위원회가 해당 징벌을 의결한 날이 속하는 달의 작업장려금부터 이미 지급된 작업장려금에 대하여 역순(逆順)으로 집행한다.', 6801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11776, '② 소장은 금치를 집행하는 경우에는 징벌집행을 위하여 따로 지정한 거실(이하 "징벌거실"이라 한다)에 해당 군수용자를 수용하여야 한다.', 6801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11777, '③ 소장은 금치 외의 징벌을 집행하는 경우에 그 징벌의 목적을 달성하기 위하여 필요하다고 인정하면 해당 군수용자를 징벌거실에 수용할 수 있다.', 6801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11778, '④ 소장은 징벌 집행을 받고 있거나 집행을 앞둔 군수용자가 같은 행위로 형사법률에 따른 처벌이 확정되어 징벌을 집행할 필요가 없다고 인정하면 징벌 집행을 감경하거나 면제할 수 있다.', 6801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11779, '① 위원회의 위원은 다음 각 호의 사람 중에서 위원장이 법 제105조제2항에 따라 위촉한 위원으로 구성한다. 이 경우 제1호의 군법무관 3명과 헌병병과 장교 2명이 포함되도록 하되, 특정 군 또는 부대 소속으로만 구성하지 않도록 한다.', 6806);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11780, '② 위원장이 제1항에 따라 위원을 위촉하였을 때에는 그 명단을 국방부조사본부장을 거쳐 국방부장관에게 보고하여야 한다. <개정 2014.11.3>', 6806);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11781, '③ 제2항에 따른 위원 명단은 심사의 공정성과 위원의 신변보호를 위하여 외부에 공개해서는 아니 된다.', 6806);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11782, '① 위원장은 위원회를 대표하고, 위원회의 업무를 총괄한다.', 6808);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11783, '② 위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 위원장이 미리 지정한 위원이 그 직무를 대행한다.', 6808);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11784, '① 위원장은 회의를 소집하고, 그 의장이 된다.', 6809);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11785, '② 위원회의 회의는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.', 6809);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11786, '① 위원회에 위원회의 사무를 처리하기 위하여 간사 1명과 서기 1명을 둔다.', 6810);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11787, '② 간사와 서기는 소속 군교도관 중에서 소장이 임명한다.', 6810);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11788, '③ 간사는 회의에 참석하여 발언할 수 있고, 위원회 결정에 따른 결정서를 작성하여야 한다.', 6810);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11789, '④ 서기는 간사의 업무를 보조한다.', 6810);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11790, '① 간사는 별지 제26호서식의 가석방심사위원회 회의록을 작성ㆍ관리하여야 한다.', 6811);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11791, '② 제1항에 따른 회의록에는 회의의 내용을 기록하고, 위원장 및 간사가 서명ㆍ날인하여야 한다.', 6811);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11792, '① 소장은 「형법」 제72조에 따른 가석방의 요건을 갖춘 군수형자 중 교정성적이 우수하고 뉘우치는 빛이 뚜렷하여 재범의 위험성이 없다고 인정되는 사람을 군교도관회의의 의결을 거쳐 가석방 적격심사 대상자로 선정한다.', 6815);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11793, '② 소장은 형의 집행정지를 받게 될 군수형자가 제1항에 해당할 경우에는 우선적으로 위원회에 가석방의 적격심사를 회부하여야 한다.', 6815);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11794, '③ 소장은 가석방 적격심사에 필요하다고 인정하는 경우에는 군교도관회의에 담당군교도관을 출석시켜 군수형자의 가석방 적격심사에 관한 의견을 들을 수 있다.', 6815);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11795, null, 6816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11796, '① 신원관계의 조사는 영 제76조제1항에 따라 군수형자로 처우하는 날부터 1개월 이내에 하고, 그 후에는 변경을 요하는 사항을 발견하거나 가석방 적격심사를 위해 필요한 경우에 한다.', 6818);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11797, '② 범죄관계 및 보호관계의 조사는 영 제76조제1항에 따라 군수형자로 처우하는 날부터 2개월 이내에 하여야 한다.', 6818);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11798, '③ 범죄관계의 조사에 필요하다고 인정하는 경우에는 소송기록을 열람할 수 있다.', 6818);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11799, '① 소장은 제175조에 따라 가석방 심사대상자를 선정하였을 때에는 선정한 날부터 5일 이내에 위원회에 가석방 적격심사를 회부하여야 한다.', 6819);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11800, '② 소장은 제1항에 따라 위원회에 가석방 적격심사를 회부할 때에는 별지 제27호서식의 가석방 적격심사 신청서에 별지 제28호서식의 가석방 심사 및 신상조사표를 첨부하여야 한다.', 6819);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11801, '③ 소장은 위원회에 가석방 적격심사를 회부한 사실을 군수형자의 동의를 얻어 보호자 등에게 통지할 수 있다.', 6819);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11802, '① 위원회가 범죄의 동기에 관하여 심사할 때에는 사회 통념상 및 공익상 등 정상을 참작할 만한 사유가 있는지를 심사하여야 한다.', 6821);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11803, '② 범죄의 동기가 군중의 암시 또는 도발, 감독관계에 의한 위협, 그 밖에 이와 유사한 사유에 의한 경우에는 특히 군수형자의 성격 또는 환경의 변화에 유의하고 가석방 후의 환경이 가석방처분을 받은 사람(「보호관찰 등에 관한 법률」에 따른 보호관찰대상자는 제외한다. 이하 "가석방자"라 한다)에게 미칠 영향을 심사하여야 한다.', 6821);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11804, null, 6822);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11805, null, 6823);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11806, '① 재산에 관한 죄를 범한 군수형자에 대해서는 특히 그 범행으로 인하여 발생한 손해의 배상 여부 또는 손해를 줄이기 위한 노력 여부를 심사하여야 한다.', 6824);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11807, '② 군수형자 외의 사람이 피해자의 손해를 배상한 경우에는 그 배상이 군수형자 본인의 희망에 따른 것인지를 심사하여야 한다.', 6824);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11808, '① 위원회는 가석방 적격심사에 필요하다고 인정하는 경우에는 군수형자의 주소지 또는 연고지 등을 관할하는 시ㆍ군ㆍ구ㆍ경찰서, 전(前) 소속부대, 그 밖에 학교ㆍ직업알선기관ㆍ보호단체ㆍ종교단체 등 관계기관에 사실조회를 하거나 관계자의 의견을 들을 수 있다.', 6825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11809, '② 위원회는 가석방 적격심사를 위하여 필요하다고 인정하는 경우에는 위원이 아닌 군법무관 또는 판사ㆍ검사ㆍ변호사에게 의견을 구하거나 위원회에 참여하게 할 수 있다.', 6825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11810, '① 위원회는 가석방 적격심사에 필요하다고 인정하는 경우에는 심리학ㆍ정신의학ㆍ사회학 또는 교육학을 전공한 전문가에게 군수형자의 정신상태 등 특정 사항에 대한 감정(鑑定)을 촉탁(囑託)할 수 있다.', 6826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11811, '② 제1항에 따른 촉탁을 받은 사람은 소장의 허가를 받아 군수형자와 접견할 수 있다.', 6826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11812, '① 위원회가 법 제106조제2항에 따라 가석방 적격결정을 하였을 때에는 별지 제29호서식의 가석방 결정서를 작성하여야 한다.', 6828);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11813, '② 법 제107조에 따른 가석방허가의 신청은 별지 제30호서식에 따른다.', 6828);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11814, '① 소장은 가석방자가 제192조에 따른 가석방 취소의 사유가 있음을 알았거나 소속 부대장 또는 관할 경찰서장으로부터 통보를 받았을 때에는 지체 없이 가석방 취소의 심사를 위원회에 회부하여야 한다.', 6833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11815, '② 제1항에도 불구하고 소장은 위원회를 소집할 수 없거나 긴급한 사유가 있는 때에는 위원회의 심사를 거치지 아니하고 국방부장관에게 가석방 취소를 신청할 수 있다.', 6833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11816, '③ 위원장은 위원회에서 가석방 취소를 결정하였을 때에는 지체 없이 국방부장관에게 가석방 취소를 신청하여야 한다.', 6833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11817, '① 위원회가 가석방 취소 여부를 심사하는 경우에는 제192조에 따른 가석방 취소의 사유에 해당하게 된 경위와 그 위반행위가 군과 사회에 미치는 영향, 가석방 기간 동안의 행실의 양호 여부, 직업의 유무 및 종류, 생활상황과 친족관계, 그 밖의 사정을 고려하여야 한다.', 6834);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11818, '② 위원회는 제1항의 심사를 위하여 필요한 경우에는 해당 가석방자를 위원회에 출석시켜 그 진술을 들을 수 있다.', 6834);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11819, '① 소장은 가석방자의 가석방이 취소되었을 때에는 지체 없이 남은 형의 집행에 필요한 조치를 하고, 그 결과를 국방부장관에게 보고하여야 한다.', 6835);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11820, '② 소장은 가석방이 취소된 사람이 군교도소 밖에 있을 때에는 관할 헌병대장 또는 관할 경찰서장에게 가석방이 취소된 사람을 구인(拘引)하도록 의뢰하여야 한다.', 6835);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11821, '③ 제2항에 따라 구인의 의뢰를 받은 헌병대장 또는 경찰서장은 즉시 가석방이 취소된 사람을 구인하여 소장에게 인계하여야 한다.', 6835);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11822, null, 6839);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11823, '① 법무부장관은 이 법의 목적을 효율적으로 달성하기 위하여 5년마다 형의 집행 및 수용자 처우에 관한 기본계획(이하 "기본계획"이라 한다)을 수립하고 추진하여야 한다.', 6843);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11824, '② 기본계획에는 다음 각 호의 사항이 포함되어야 한다.', 6843);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11825, '③ 법무부장관은 기본계획을 수립 또는 변경하려는 때에는 법원, 검찰 및 경찰 등 관계 기관과 협의하여야 한다.', 6843);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11826, '④ 법무부장관은 기본계획을 수립하기 위하여 실태조사와 수요예측 조사를 실시할 수 있다.', 6843);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11827, '⑤ 법무부장관은 기본계획을 수립하기 위하여 필요하다고 인정하는 경우에는 관계 기관의 장에게 필요한 자료를 요청할 수 있다. 이 경우 자료를 요청받은 관계 기관의 장은 특별한 사정이 없으면 요청에 따라야 한다.', 6843);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11828, '① 법무부장관은 형의 집행 및 수용자 처우에 관한 사항을 협의하기 위하여 법원, 검찰 및 경찰 등 관계 기관과 협의체를 설치하여 운영할 수 있다.', 6844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11829, '② 제1항에 따른 협의체의 설치 및 운영 등에 필요한 사항은 대통령령으로 정한다.', 6844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11830, '① 신설하는 교정시설은 수용인원이 500명 이내의 규모가 되도록 하여야 한다. 다만, 교정시설의 기능ㆍ위치나 그 밖의 사정을 고려하여 그 규모를 늘릴 수 있다. <개정 2020.2.4>', 6845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11831, '② 교정시설의 거실ㆍ작업장ㆍ접견실이나 그 밖의 수용생활을 위한 설비는 그 목적과 기능에 맞도록 설치되어야 한다. 특히, 거실은 수용자가 건강하게 생활할 수 있도록 적정한 수준의 공간과 채광ㆍ통풍ㆍ난방을 위한 시설이 갖추어져야 한다.', 6845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11832, '③ 법무부장관은 수용자에 대한 처우 및 교정시설의 유지ㆍ관리를 위한 적정한 인력을 확보하여야 한다. <신설 2019.4.23>', 6845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11833, '① 법무부장관은 교정시설의 설치 및 운영에 관한 업무의 일부를 법인 또는 개인에게 위탁할 수 있다.', 6846);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11834, '② 제1항에 따라 위탁을 받을 수 있는 법인 또는 개인의 자격요건, 교정시설의 시설기준, 수용대상자의 선정기준, 수용자 처우의 기준, 위탁절차, 국가의 감독, 그 밖에 필요한 사항은 따로 법률로 정한다.', 6846);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11835, '① 판사와 검사는 직무상 필요하면 교정시설을 시찰할 수 있다.', 6848);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11836, '② 제1항의 판사와 검사 외의 사람은 교정시설을 참관하려면 학술연구 등 정당한 이유를 명시하여 교정시설의 장(이하 "소장"이라 한다)의 허가를 받아야 한다.', 6848);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11837, '① 수용자는 다음 각 호에 따라 구분하여 수용한다. <개정 2008.12.11>', 6850);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11838, '② 교도소 및 구치소의 각 지소에는 교도소 또는 구치소에 준하여 수용자를 수용한다.', 6850);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11839, '① 다음 각 호의 어느 하나에 해당하는 사유가 있으면 교도소에 미결수용자를 수용할 수 있다.', 6851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11840, '② 취사 등의 작업을 위하여 필요하거나 그 밖에 특별한 사정이 있으면 구치소에 수형자를 수용할 수 있다.', 6851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11841, '③ 수형자가 소년교도소에 수용 중에 19세가 된 경우에도 교육ㆍ교화프로그램, 작업, 직업훈련 등을 실시하기 위하여 특히 필요하다고 인정되면 23세가 되기 전까지는 계속하여 수용할 수 있다. <개정 2008.12.11>', 6851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11842, '④ 소장은 특별한 사정이 있으면 제11조의 구분수용 기준에 따라 다른 교정시설로 이송하여야 할 수형자를 6개월을 초과하지 아니하는 기간 동안 계속하여 수용할 수 있다.', 6851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11843, '① 남성과 여성은 분리하여 수용한다.', 6852);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11844, '② 제12조에 따라 수형자와 미결수용자, 19세 이상의 수형자와 19세 미만의 수형자를 같은 교정시설에 수용하는 경우에는 서로 분리하여 수용한다. <개정 2008.12.11>', 6852);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11845, null, 6853);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11846, '① 소장은 법원ㆍ검찰청ㆍ경찰관서 등으로부터 처음으로 교정시설에 수용되는 사람(이하 "신입자"라 한다)에 대하여는 집행지휘서, 재판서, 그 밖에 수용에 필요한 서류를 조사한 후 수용한다.', 6855);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11847, '② 소장은 신입자에 대하여는 지체 없이 신체ㆍ의류 및 휴대품을 검사하고 건강진단을 하여야 한다. <개정 2017.12.19>', 6855);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11848, '③ 신입자는 제2항에 따라 소장이 실시하는 검사 및 건강진단을 받아야 한다. <신설 2015.3.27, 2017.12.19>', 6855);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11849, null, 6856);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11850, null, 6857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11851, '① 소장은 다른 사람의 건강에 위해를 끼칠 우려가 있는 감염병에 걸린 사람의 수용을 거절할 수 있다. <개정 2009.12.29>', 6858);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11852, '② 소장은 제1항에 따라 수용을 거절하였으면 그 사유를 지체 없이 수용지휘기관과 관할 보건소장에게 통보하고 법무부장관에게 보고하여야 한다.', 6858);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11853, '① 소장은 신입자 및 다른 교정시설로부터 이송되어 온 사람에 대하여 다른 사람과의 식별을 위하여 필요한 한도에서 사진촬영, 지문채취, 수용자 번호지정, 그 밖에 대통령령으로 정하는 조치를 하여야 한다.', 6859);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11854, '② 소장은 수용목적상 필요하면 수용 중인 사람에 대하여도 제1항의 조치를 할 수 있다.', 6859);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11855, '① 소장은 수용자의 수용ㆍ작업ㆍ교화ㆍ의료, 그 밖의 처우를 위하여 필요하거나 시설의 안전과 질서유지를 위하여 필요하다고 인정하면 법무부장관의 승인을 받아 수용자를 다른 교정시설로 이송할 수 있다.', 6860);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11856, '② 법무부장관은 제1항의 이송승인에 관한 권한을 대통령령으로 정하는 바에 따라 지방교정청장에게 위임할 수 있다.', 6860);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11857, '① 소장은 수용자에게 건강유지에 적합한 의류ㆍ침구, 그 밖의 생활용품을 지급한다.', 6862);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11858, '② 의류ㆍ침구, 그 밖의 생활용품의 지급기준 등에 관하여 필요한 사항은 법무부령으로 정한다.', 6862);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11859, '① 소장은 수용자에게 건강상태, 나이, 부과된 작업의 종류, 그 밖의 개인적 특성을 고려하여 건강 및 체력을 유지하는 데에 필요한 음식물을 지급한다.', 6863);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11860, '② 음식물의 지급기준 등에 관하여 필요한 사항은 법무부령으로 정한다.', 6863);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11861, '① 수용자는 소장의 허가를 받아 자신의 비용으로 음식물ㆍ의류ㆍ침구, 그 밖에 수용생활에 필요한 물품을 구매할 수 있다.', 6864);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11862, '② 물품의 자비구매 허가범위 등에 관하여 필요한 사항은 법무부령으로 정한다.', 6864);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11863, '① 소장은 수용자의 휴대금품을 교정시설에 보관한다. 다만, 휴대품이 다음 각 호의 어느 하나에 해당하는 것이면 수용자로 하여금 자신이 지정하는 사람에게 보내게 하거나 그 밖에 적당한 방법으로 처분하게 할 수 있다. <개정 2020.2.4>', 6865);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11864, '② 소장은 수용자가 제1항 단서에 따라 처분하여야 할 휴대품을 상당한 기간 내에 처분하지 아니하면 폐기할 수 있다.', 6865);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11865, '① 수용자는 편지ㆍ도서, 그 밖에 수용생활에 필요한 물품을 법무부장관이 정하는 범위에서 지닐 수 있다. <개정 2020.2.4>', 6866);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11866, '② 소장은 제1항에 따라 법무부장관이 정하는 범위를 벗어난 물품으로서 교정시설에 특히 보관할 필요가 있다고 인정하지 아니하는 물품은 수용자로 하여금 자신이 지정하는 사람에게 보내게 하거나 그 밖에 적당한 방법으로 처분하게 할 수 있다. <개정 2020.2.4>', 6866);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11867, '③ 소장은 수용자가 제2항에 따라 처분하여야 할 물품을 상당한 기간 내에 처분하지 아니하면 폐기할 수 있다.', 6866);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11868, '① 수용자 외의 사람이 수용자에게 금품을 건네줄 것을 신청하는 때에는 소장은 다음 각 호의 어느 하나에 해당하지 아니하면 허가하여야 한다. <개정 2020.2.4>', 6867);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11869, '② 소장은 수용자 외의 사람이 수용자에게 주려는 금품이 제1항 각 호의 어느 하나에 해당하거나 수용자가 금품을 받지 아니하려는 경우에는 해당 금품을 보낸 사람에게 되돌려 보내야 한다. <개정 2020.2.4>', 6867);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11870, '③ 소장은 제2항의 경우에 금품을 보낸 사람을 알 수 없거나 보낸 사람의 주소가 불분명한 경우에는 금품을 다시 가지고 갈 것을 공고하여야 하며, 공고한 후 6개월이 지나도 금품을 돌려달라고 청구하는 사람이 없으면 그 금품은 국고에 귀속된다. <개정 2020.2.4>', 6867);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11871, '④ 소장은 제2항 또는 제3항에 따른 조치를 하였으면 그 사실을 수용자에게 알려 주어야 한다.', 6867);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11872, '① 소장은 사망자 또는 도주자가 남겨두고 간 금품이 있으면 사망자의 경우에는 그 상속인에게, 도주자의 경우에는 그 가족에게 그 내용 및 청구절차 등을 알려 주어야 한다. 다만, 썩거나 없어질 우려가 있는 것은 폐기할 수 있다. <개정 2020.2.4>', 6868);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11873, '② 소장은 상속인 또는 가족이 제1항의 금품을 내어달라고 청구하면 지체 없이 내어주어야 한다. 다만, 제1항에 따른 알림을 받은 날(알려줄 수가 없는 경우에는 청구사유가 발생한 날)부터 1년이 지나도 청구하지 아니하면 그 금품은 국고에 귀속된다. <개정 2020.2.4>', 6868);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11874, '① 소장은 수용자가 석방될 때 제25조에 따라 보관하고 있던 수용자의 휴대금품을 본인에게 돌려주어야 한다. 다만, 보관품을 한꺼번에 가져가기 어려운 경우 등 특별한 사정이 있어 수용자가 석방 시 소장에게 일정 기간 동안(1개월 이내의 범위로 한정한다) 보관품을 보관하여 줄 것을 신청하는 경우에는 그러하지 아니하다. <개정 2020.2.4>', 6869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11875, '② 제1항 단서에 따른 보관 기간이 지난 보관품에 관하여는 제28조를 준용한다. 이 경우 "사망자" 및 "도주자"는 "피석방자"로, "금품"은 "보관품"으로, "상속인" 및 "가족"은 "피석방자 본인 또는 가족"으로 본다. <개정 2020.2.4>', 6869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11876, '① 수용자는 자신의 신체 및 의류를 청결히 하여야 하며, 자신이 사용하는 거실ㆍ작업장, 그 밖의 수용시설의 청결유지에 협력하여야 한다.', 6872);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11877, '② 수용자는 위생을 위하여 머리카락과 수염을 단정하게 유지하여야 한다. <개정 2020.2.4>', 6872);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11878, '① 소장은 수용자가 건강유지에 필요한 운동 및 목욕을 정기적으로 할 수 있도록 하여야 한다.', 6873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11879, '② 운동시간ㆍ목욕횟수 등에 관하여 필요한 사항은 대통령령으로 정한다.', 6873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11880, '① 소장은 수용자에 대하여 건강검진을 정기적으로 하여야 한다.', 6874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11881, '② 건강검진의 횟수 등에 관하여 필요한 사항은 대통령령으로 정한다.', 6874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11882, '①소장은 수용자가 부상을 당하거나 질병에 걸리면 적절한 치료를 받도록 하여야 한다. <개정 2010.5.4>', 6876);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11883, '② 제1항의 치료를 위하여 교정시설에 근무하는 간호사는 야간 또는 공휴일 등에 「의료법」 제27조에도 불구하고 대통령령으로 정하는 경미한 의료행위를 할 수 있다. <신설 2010.5.4>', 6876);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11884, '① 소장은 수용자에 대한 적절한 치료를 위하여 필요하다고 인정하면 교정시설 밖에 있는 의료시설(이하 "외부의료시설"이라 한다)에서 진료를 받게 할 수 있다.', 6877);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11885, '② 소장은 수용자의 정신질환 치료를 위하여 필요하다고 인정하면 법무부장관의 승인을 받아 치료감호시설로 이송할 수 있다.', 6877);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11886, '③ 제2항에 따라 이송된 사람은 수용자에 준하여 처우한다.', 6877);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11887, '④ 소장은 제1항 또는 제2항에 따라 수용자가 외부의료시설에서 진료받거나 치료감호시설로 이송되면 그 사실을 그 가족(가족이 없는 경우에는 수용자가 지정하는 사람)에게 지체 없이 알려야 한다. 다만, 수용자가 알리는 것을 원하지 아니하면 그러하지 아니하다. <개정 2020.2.4>', 6877);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11888, '⑤ 소장은 수용자가 자신의 고의 또는 중대한 과실로 부상 등이 발생하여 외부의료시설에서 진료를 받은 경우에는 그 진료비의 전부 또는 일부를 그 수용자에게 부담하게 할 수 있다.', 6877);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11889, '① 교정시설에는 수용자의 진료를 위하여 필요한 의료 인력과 설비를 갖추어야 한다.', 6879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11890, '② 소장은 정신질환이 있다고 의심되는 수용자가 있으면 정신건강의학과 의사의 진료를 받을 수 있도록 하여야 한다. <개정 2011.8.4>', 6879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11891, '③ 외부의사는 수용자를 진료하는 경우에는 법무부장관이 정하는 사항을 준수하여야 한다.', 6879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11892, '④ 교정시설에 갖추어야 할 의료설비의 기준에 관하여 필요한 사항은 법무부령으로 정한다.', 6879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11893, '① 소장은 수용자가 진료 또는 음식물의 섭취를 거부하면 의무관으로 하여금 관찰ㆍ조언 또는 설득을 하도록 하여야 한다.', 6880);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11894, '② 소장은 제1항의 조치에도 불구하고 수용자가 진료 또는 음식물의 섭취를 계속 거부하여 그 생명에 위험을 가져올 급박한 우려가 있으면 의무관으로 하여금 적당한 진료 또는 영양보급 등의 조치를 하게 할 수 있다.', 6880);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11895, '① 수용자는 교정시설의 외부에 있는 사람과 접견할 수 있다. 다만, 다음 각 호의 어느 하나에 해당하는 사유가 있으면 그러하지 아니하다.', 6881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11896, '② 수용자의 접견은 접촉차단시설이 설치된 장소에서 하게 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 접촉차단시설이 설치되지 아니한 장소에서 접견하게 한다. <신설 2019.4.23, 2022.12.27>', 6881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11897, '③ 제2항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 접촉차단시설이 설치되지 아니한 장소에서 접견하게 할 수 있다. <신설 2019.4.23>', 6881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11898, '④ 소장은 다음 각 호의 어느 하나에 해당하는 사유가 있으면 교도관으로 하여금 수용자의 접견내용을 청취ㆍ기록ㆍ녹음 또는 녹화하게 할 수 있다. <개정 2019.4.23>', 6881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11899, '⑤ 제4항에 따라 녹음ㆍ녹화하는 경우에는 사전에 수용자 및 그 상대방에게 그 사실을 알려 주어야 한다. <개정 2019.4.23>', 6881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11900, '⑥ 접견의 횟수ㆍ시간ㆍ장소ㆍ방법 및 접견내용의 청취ㆍ기록ㆍ녹음ㆍ녹화 등에 관하여 필요한 사항은 대통령령으로 정한다. <개정 2019.4.23>', 6881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11901, null, 6882);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11902, '① 수용자는 다른 사람과 편지를 주고받을 수 있다. 다만, 다음 각 호의 어느 하나에 해당하는 사유가 있으면 그러하지 아니하다. <개정 2020.2.4>', 6883);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11903, '② 제1항 각 호 외의 부분 본문에도 불구하고 같은 교정시설의 수용자 간에 편지를 주고받으려면 소장의 허가를 받아야 한다. <개정 2020.2.4>', 6883);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11904, '③ 소장은 수용자가 주고받는 편지에 법령에 따라 금지된 물품이 들어 있는지 확인할 수 있다. <개정 2020.2.4>', 6883);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11905, '④ 수용자가 주고받는 편지의 내용은 검열받지 아니한다. 다만, 다음 각 호의 어느 하나에 해당하는 사유가 있으면 그러하지 아니하다. <개정 2020.2.4>', 6883);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11906, '⑤ 소장은 제3항 또는 제4항 단서에 따라 확인 또는 검열한 결과 수용자의 편지에 법령으로 금지된 물품이 들어 있거나 편지의 내용이 다음 각 호의 어느 하나에 해당하면 발신 또는 수신을 금지할 수 있다. <개정 2020.2.4>', 6883);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11907, '⑥ 소장이 편지를 발송하거나 내어주는 경우에는 신속히 하여야 한다. <개정 2020.2.4>', 6883);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11908, '⑦ 소장은 제1항 단서 또는 제5항에 따라 발신 또는 수신이 금지된 편지는 그 구체적인 사유를 서면으로 작성해 관리하고, 수용자에게 그 사유를 알린 후 교정시설에 보관한다. 다만, 수용자가 동의하면 폐기할 수 있다. <개정 2019.4.23, 2020.2.4>', 6883);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11909, '⑧ 편지발송의 횟수, 편지 내용물의 확인방법 및 편지 내용의 검열절차 등에 관하여 필요한 사항은 대통령령으로 정한다. <개정 2020.2.4>', 6883);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11910, '① 수용자는 소장의 허가를 받아 교정시설의 외부에 있는 사람과 전화통화를 할 수 있다.', 6884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11911, '② 제1항에 따른 허가에는 통화내용의 청취 또는 녹음을 조건으로 붙일 수 있다.', 6884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11912, '③ 제42조는 수용자의 전화통화에 관하여 준용한다.', 6884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11913, '④ 제2항에 따라 통화내용을 청취 또는 녹음하려면 사전에 수용자 및 상대방에게 그 사실을 알려 주어야 한다.', 6884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11914, '⑤ 전화통화의 허가범위, 통화내용의 청취ㆍ녹음 등에 관하여 필요한 사항은 법무부령으로 정한다.', 6884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11915, '① 수용자는 교정시설의 안에서 실시하는 종교의식 또는 행사에 참석할 수 있으며, 개별적인 종교상담을 받을 수 있다.', 6885);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11916, '② 수용자는 자신의 신앙생활에 필요한 책이나 물품을 지닐 수 있다. <개정 2020.2.4>', 6885);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11917, '③ 소장은 다음 각 호의 어느 하나에 해당하는 사유가 있으면 제1항 및 제2항에서 규정하고 있는 사항을 제한할 수 있다.', 6885);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11918, '④ 종교행사의 종류ㆍ참석대상ㆍ방법, 종교상담의 대상ㆍ방법 및 종교도서ㆍ물품을 지닐 수 있는 범위 등에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2020.2.4>', 6885);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11919, '① 수용자는 자신의 비용으로 신문ㆍ잡지 또는 도서(이하 "신문등" 이라 한다)의 구독을 신청할 수 있다.', 6887);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11920, '② 소장은 제1항에 따라 구독을 신청한 신문등이 「출판문화산업 진흥법」에 따른 유해간행물인 경우를 제외하고는 구독을 허가하여야 한다.', 6887);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11921, '③ 제1항에 따라 구독을 신청할 수 있는 신문등의 범위 및 수량은 법무부령으로 정한다.', 6887);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11922, '① 수용자는 정서안정 및 교양습득을 위하여 라디오 청취와 텔레비전 시청을 할 수 있다.', 6888);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11923, '② 소장은 다음 각 호의 어느 하나에 해당하는 사유가 있으면 수용자에 대한 라디오 및 텔레비전의 방송을 일시 중단하거나 개별 수용자에 대하여 라디오 및 텔레비전의 청취 또는 시청을 금지할 수 있다.', 6888);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11924, '③ 방송설비ㆍ방송프로그램ㆍ방송시간 등에 관하여 필요한 사항은 법무부령으로 정한다.', 6888);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11925, '① 수용자는 문서 또는 도화(<img src="http://www.law.go.kr/flDownload.do?flSeq=56450713"  alt="img56450713" >圖</img>)를 작성하거나 문예ㆍ학술, 그 밖의 사항에 관하여 집필할 수 있다. 다만, 소장이 시설의 안전 또는 질서를 해칠 명백한 위험이 있다고 인정하는 경우는 예외로 한다. <개정 2020.2.4>', 6889);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11926, '② 제1항에 따라 작성 또는 집필한 문서나 도화를 지니거나 처리하는 것에 관하여는 제26조를 준용한다. <개정 2020.2.4>', 6889);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11927, '③ 제1항에 따라 작성 또는 집필한 문서나 도화가 제43조제5항 각 호의 어느 하나에 해당하면 제43조제7항을 준용한다.', 6889);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11928, '④ 집필용구의 관리, 집필의 시간ㆍ장소, 집필한 문서 또는 도화의 외부반출 등에 관하여 필요한 사항은 대통령령으로 정한다.', 6889);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11929, '① 소장은 여성수용자에 대하여 여성의 신체적ㆍ심리적 특성을 고려하여 처우하여야 한다.', 6890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11930, '② 소장은 여성수용자에 대하여 건강검진을 실시하는 경우에는 나이ㆍ건강 등을 고려하여 부인과질환에 관한 검사를 포함시켜야 한다. <개정 2014.12.30>', 6890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11931, '③ 소장은 생리 중인 여성수용자에 대하여는 위생에 필요한 물품을 지급하여야 한다. <개정 2014.12.30>', 6890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11932, '④ 삭제 <2019.4.23>', 6890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11933, '① 소장은 여성수용자에 대하여 상담ㆍ교육ㆍ작업 등(이하 이 조에서 "상담등"이라 한다)을 실시하는 때에는 여성교도관이 담당하도록 하여야 한다. 다만, 여성교도관이 부족하거나 그 밖의 부득이한 사정이 있으면 그러하지 아니하다.', 6891);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11934, '② 제1항 단서에 따라 남성교도관이 1인의 여성수용자에 대하여 실내에서 상담등을 하려면 투명한 창문이 설치된 장소에서 다른 여성을 입회시킨 후 실시하여야 한다.', 6891);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11935, '① 소장은 수용자가 임신 중이거나 출산(유산ㆍ사산을 포함한다)한 경우에는 모성보호 및 건강유지를 위하여 정기적인 검진 등 적절한 조치를 하여야 한다. <개정 2019.4.23>', 6892);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11936, '② 소장은 수용자가 출산하려고 하는 경우에는 외부의료시설에서 진료를 받게 하는 등 적절한 조치를 하여야 한다.', 6892);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11937, '① 여성수용자는 자신이 출산한 유아를 교정시설에서 양육할 것을 신청할 수 있다. 이 경우 소장은 다음 각 호의 어느 하나에 해당하는 사유가 없으면, 생후 18개월에 이르기까지 허가하여야 한다. <개정 2009.12.29>', 6893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11938, '② 소장은 제1항에 따라 유아의 양육을 허가한 경우에는 필요한 설비와 물품의 제공, 그 밖에 양육을 위하여 필요한 조치를 하여야 한다.', 6893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11939, '① 소장은 신입자에게 「아동복지법」 제15조에 따른 보호조치를 의뢰할 수 있음을 알려주어야 한다.', 6894);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11940, '② 소장은 수용자가 「아동복지법」 제15조에 따른 보호조치를 의뢰하려는 경우 보호조치 의뢰가 원활하게 이루어질 수 있도록 지원하여야 한다.', 6894);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11941, '③ 제1항에 따른 안내 및 제2항에 따른 보호조치 의뢰 지원의 방법ㆍ절차, 그 밖에 필요한 사항은 법무부장관이 정한다.', 6894);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11942, '① 소장은 노인수용자에 대하여 나이ㆍ건강상태 등을 고려하여 그 처우에 있어 적정한 배려를 하여야 한다.', 6895);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11943, '② 소장은 장애인수용자에 대하여 장애의 정도를 고려하여 그 처우에 있어 적정한 배려를 하여야 한다.', 6895);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11944, '③ 소장은 외국인수용자에 대하여 언어ㆍ생활문화 등을 고려하여 적정한 처우를 하여야 한다.', 6895);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11945, '④ 소장은 소년수용자에 대하여 나이ㆍ적성 등을 고려하여 적정한 처우를 하여야 한다. <신설 2015.3.27>', 6895);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11946, '⑤ 노인수용자ㆍ장애인수용자ㆍ외국인수용자 및 소년수용자에 대한 적정한 배려 또는 처우에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2015.3.27>', 6895);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11947, '① 소장은 제62조의 분류처우위원회의 의결에 따라 수형자의 개별적 특성에 알맞은 교육ㆍ교화프로그램, 작업, 직업훈련 등의 처우에 관한 계획(이하 "개별처우계획"이라 한다)을 수립하여 시행한다.', 6897);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11948, '② 소장은 수형자가 스스로 개선하여 사회에 복귀하려는 의욕이 고취되도록 개별처우계획을 정기적으로 또는 수시로 점검하여야 한다.', 6897);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11949, '① 수형자는 제59조의 분류심사의 결과에 따라 그에 적합한 교정시설에 수용되며, 개별처우계획에 따라 그 특성에 알맞은 처우를 받는다.', 6898);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11950, '② 교정시설은 도주방지 등을 위한 수용설비 및 계호의 정도(이하 "경비등급"이라 한다)에 따라 다음 각 호로 구분한다. 다만, 동일한 교정시설이라도 구획을 정하여 경비등급을 달리할 수 있다.', 6898);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11951, '③ 수형자에 대한 처우는 교화 또는 건전한 사회복귀를 위하여 교정성적에 따라 상향 조정될 수 있으며, 특히 그 성적이 우수한 수형자는 개방시설에 수용되어 사회생활에 필요한 적정한 처우를 받을 수 있다.', 6898);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11952, '④ 소장은 가석방 또는 형기 종료를 앞둔 수형자 중에서 법무부령으로 정하는 일정한 요건을 갖춘 사람에 대해서는 가석방 또는 형기 종료 전 일정 기간 동안 지역사회 또는 교정시설에 설치된 개방시설에 수용하여 사회적응에 필요한 교육, 취업지원 등의 적정한 처우를 할 수 있다. <신설 2015.3.27>', 6898);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11953, '⑤ 수형자는 교화 또는 건전한 사회복귀를 위하여 교정시설 밖의 적당한 장소에서 봉사활동ㆍ견학, 그 밖에 사회적응에 필요한 처우를 받을 수 있다. <개정 2015.3.27>', 6898);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11954, '⑥ 학과교육생ㆍ직업훈련생ㆍ외국인ㆍ여성ㆍ장애인ㆍ노인ㆍ환자ㆍ소년(19세 미만인 자를 말한다), 제4항에 따른 처우(이하 "중간처우"라 한다)의 대상자, 그 밖에 별도의 처우가 필요한 수형자는 법무부장관이 특히 그 처우를 전담하도록 정하는 시설(이하 "전담교정시설"이라 한다)에 수용되며, 그 특성에 알맞은 처우를 받는다. 다만, 전담교정시설의 부족이나 그 밖의 부득이한 사정이 있는 경우에는 예외로 할 수 있다. <개정 2015.3.27>', 6898);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11955, '⑦ 제2항 각 호의 시설의 설비 및 계호의 정도에 관하여 필요한 사항은 대통령령으로 정한다. <개정 2015.3.27>', 6898);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11956, '① 소장은 수형자에 대한 개별처우계획을 합리적으로 수립하고 조정하기 위하여 수형자의 인성, 행동특성 및 자질 등을 과학적으로 조사ㆍ측정ㆍ평가(이하 "분류심사"라 한다)하여야 한다. 다만, 집행할 형기가 짧거나 그 밖의 특별한 사정이 있는 경우에는 예외로 할 수 있다.', 6900);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11957, '② 수형자의 분류심사는 형이 확정된 경우에 개별처우계획을 수립하기 위하여 하는 심사와 일정한 형기가 지나거나 상벌 또는 그 밖의 사유가 발생한 경우에 개별처우계획을 조정하기 위하여 하는 심사로 구분한다.', 6900);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11958, '③ 소장은 분류심사를 위하여 수형자를 대상으로 상담 등을 통한 신상에 관한 개별사안의 조사, 심리ㆍ지능ㆍ적성 검사, 그 밖에 필요한 검사를 할 수 있다.', 6900);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11959, '④ 소장은 분류심사를 위하여 외부전문가로부터 필요한 의견을 듣거나 외부전문가에게 조사를 의뢰할 수 있다.', 6900);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11960, '⑤ 이 법에 규정된 사항 외에 분류심사에 관하여 필요한 사항은 법무부령으로 정한다.', 6900);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11961, '① 소장은 분류심사와 그 밖에 수용목적의 달성을 위하여 필요하면 수용자의 가족 등을 면담하거나 법원ㆍ경찰관서, 그 밖의 관계 기관 또는 단체(이하 "관계기관등"이라 한다)에 대하여 필요한 사실을 조회할 수 있다.', 6901);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11962, '② 제1항의 조회를 요청받은 관계기관등의 장은 특별한 사정이 없으면 지체 없이 그에 관하여 답하여야 한다. <개정 2020.2.4>', 6901);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11963, '① 수형자의 개별처우계획, 가석방심사신청 대상자 선정, 그 밖에 수형자의 분류처우에 관한 중요 사항을 심의ㆍ의결하기 위하여 교정시설에 분류처우위원회(이하 이 조에서 "위원회"라 한다)를 둔다.', 6903);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11964, '② 위원회는 위원장을 포함한 5명 이상 7명 이하의 위원으로 구성하고, 위원장은 소장이 되며, 위원은 위원장이 소속 기관의 부소장 및 과장(지소의 경우에는 7급 이상의 교도관) 중에서 임명한다. <개정 2020.2.4>', 6903);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11965, '③ 위원회는 그 심의ㆍ의결을 위하여 외부전문가로부터 의견을 들을 수 있다.', 6903);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11966, '④ 이 법에 규정된 사항 외에 위원회에 관하여 필요한 사항은 법무부령으로 정한다.', 6903);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11967, '① 소장은 수형자가 건전한 사회복귀에 필요한 지식과 소양을 습득하도록 교육할 수 있다.', 6904);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11968, '② 소장은 「교육기본법」 제8조의 의무교육을 받지 못한 수형자에 대하여는 본인의 의사ㆍ나이ㆍ지식정도, 그 밖의 사정을 고려하여 그에 알맞게 교육하여야 한다.', 6904);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11969, '③ 소장은 제1항 및 제2항에 따른 교육을 위하여 필요하면 수형자를 중간처우를 위한 전담교정시설에 수용하여 다음 각 호의 조치를 할 수 있다. <개정 2015.3.27>', 6904);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11970, '④ 교육과정ㆍ외부통학ㆍ위탁교육 등에 관하여 필요한 사항은 법무부령으로 정한다.', 6904);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11971, '① 소장은 수형자의 교정교화를 위하여 상담ㆍ심리치료, 그 밖의 교화프로그램을 실시하여야 한다.', 6905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11972, '② 소장은 제1항에 따른 교화프로그램의 효과를 높이기 위하여 범죄원인별로 적절한 교화프로그램의 내용, 교육장소 및 전문인력의 확보 등 적합한 환경을 갖추도록 노력하여야 한다. <신설 2019.4.23>', 6905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11973, '③ 교화프로그램의 종류ㆍ내용 등에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2019.4.23>', 6905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11974, '① 수형자에게 부과하는 작업은 건전한 사회복귀를 위하여 기술을 습득하고 근로의욕을 고취하는 데에 적합한 것이어야 한다.', 6906);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11975, '② 소장은 수형자에게 작업을 부과하려면 나이ㆍ형기ㆍ건강상태ㆍ기술ㆍ성격ㆍ취미ㆍ경력ㆍ장래생계, 그 밖의 수형자의 사정을 고려하여야 한다.', 6906);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11976, '① 소장은 수형자의 건전한 사회복귀와 기술습득을 촉진하기 위하여 필요하면 외부기업체 등에 통근 작업하게 하거나 교정시설의 안에 설치된 외부기업체의 작업장에서 작업하게 할 수 있다.', 6909);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11977, '② 외부 통근 작업 대상자의 선정기준 등에 관하여 필요한 사항은 법무부령으로 정한다.', 6909);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11978, '① 소장은 수형자의 건전한 사회복귀를 위하여 기술 습득 및 향상을 위한 직업능력개발훈련(이하 "직업훈련"이라 한다)을 실시할 수 있다.', 6910);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11979, '② 소장은 수형자의 직업훈련을 위하여 필요하면 외부의 기관 또는 단체에서 훈련을 받게 할 수 있다.', 6910);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11980, '③ 직업훈련 대상자의 선정기준 등에 관하여 필요한 사항은 법무부령으로 정한다.', 6910);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11981, '① 소장은 수형자의 신청에 따라 제68조의 작업, 제69조제2항의 훈련, 그 밖에 집중적인 근로가 필요한 작업을 부과하는 경우에는 접견ㆍ전화통화ㆍ교육ㆍ공동행사 참가 등의 처우를 제한할 수 있다. 다만, 접견 또는 전화통화를 제한한 때에는 휴일이나 그 밖에 해당 수용자의 작업이 없는 날에 접견 또는 전화통화를 할 수 있게 하여야 한다.', 6911);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11982, '② 소장은 제1항에 따라 작업을 부과하거나 훈련을 받게 하기 전에 수형자에게 제한되는 처우의 내용을 충분히 설명하여야 한다.', 6911);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11983, '① 1일의 작업시간(휴식ㆍ운동ㆍ식사ㆍ접견 등 실제 작업을 실시하지 않는 시간을 제외한다. 이하 같다)은 8시간을 초과할 수 없다.', 6912);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11984, '② 제1항에도 불구하고 취사ㆍ청소ㆍ간병 등 교정시설의 운영과 관리에 필요한 작업의 1일 작업시간은 12시간 이내로 한다.', 6912);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11985, '③ 1주의 작업시간은 52시간을 초과할 수 없다. 다만, 수형자가 신청하는 경우에는 1주의 작업시간을 8시간 이내의 범위에서 연장할 수 있다.', 6912);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11986, '④ 제2항 및 제3항에도 불구하고 19세 미만 수형자의 작업시간은 1일에 8시간을, 1주에 40시간을 초과할 수 없다.', 6912);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11987, '⑤ 공휴일ㆍ토요일과 대통령령으로 정하는 휴일에는 작업을 부과하지 아니한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 작업을 부과할 수 있다.', 6912);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11988, '① 소장은 수형자의 가족 또는 배우자의 직계존속이 사망하면 2일간, 부모 또는 배우자의 제삿날에는 1일간 해당 수형자의 작업을 면제한다. 다만, 수형자가 작업을 계속하기를 원하는 경우는 예외로 한다. <개정 2020.2.4>', 6913);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11989, '② 소장은 수형자에게 부상ㆍ질병, 그 밖에 작업을 계속하기 어려운 특별한 사정이 있으면 그 사유가 해소될 때까지 작업을 면제할 수 있다.', 6913);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11990, '① 작업수입은 국고수입으로 한다.', 6914);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11991, '② 소장은 수형자의 근로의욕을 고취하고 건전한 사회복귀를 지원하기 위하여 법무부장관이 정하는 바에 따라 작업의 종류, 작업성적, 교정성적, 그 밖의 사정을 고려하여 수형자에게 작업장려금을 지급할 수 있다.', 6914);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11992, '③ 제2항의 작업장려금은 석방할 때에 본인에게 지급한다. 다만, 본인의 가족생활 부조, 교화 또는 건전한 사회복귀를 위하여 특히 필요하면 석방 전이라도 그 전부 또는 일부를 지급할 수 있다.', 6914);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11993, '① 소장은 수형자가 다음 각 호의 어느 하나에 해당하면 법무부장관이 정하는 바에 따라 위로금 또는 조위금을 지급한다.', 6915);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11994, '② 위로금은 본인에게 지급하고, 조위금은 그 상속인에게 지급한다. <개정 2022.12.27>', 6915);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11995, '① 제74조의 위로금 또는 조위금을 지급받을 권리는 다른 사람 또는 법인에게 양도하거나 담보로 제공할 수 없으며, 다른 사람 또는 법인은 이를 압류할 수 없다.', 6917);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11996, '② 제74조에 따라 지급받은 금전을 표준으로 하여 조세와 그 밖의 공과금(公課金)을 부과하여서는 아니 된다.', 6917);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11997, '① 소장은 6개월 이상 형을 집행받은 수형자로서 그 형기의 3분의 1(21년 이상의 유기형 또는 무기형의 경우에는 7년)이 지나고 교정성적이 우수한 사람이 다음 각 호의 어느 하나에 해당하면 1년 중 20일 이내의 귀휴를 허가할 수 있다. <개정 2020.2.4>', 6918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11998, '② 소장은 다음 각 호의 어느 하나에 해당하는 사유가 있는 수형자에 대하여는 제1항에도 불구하고 5일 이내의 특별귀휴를 허가할 수 있다.', 6918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (11999, '③ 소장은 귀휴를 허가하는 경우에 법무부령으로 정하는 바에 따라 거소의 제한이나 그 밖에 필요한 조건을 붙일 수 있다.', 6918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12000, '④ 제1항 및 제2항의 귀휴기간은 형 집행기간에 포함한다.', 6918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12001, null, 6919);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12002, '① 제41조제4항에도 불구하고 미결수용자와 변호인과의 접견에는 교도관이 참여하지 못하며 그 내용을 청취 또는 녹취하지 못한다. 다만, 보이는 거리에서 미결수용자를 관찰할 수 있다. <개정 2019.4.23, 2022.12.27>', 6925);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12003, '② 미결수용자와 변호인 간의 접견은 시간과 횟수를 제한하지 아니한다.', 6925);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12004, '③ 제43조제4항 단서에도 불구하고 미결수용자와 변호인 간의 편지는 교정시설에서 상대방이 변호인임을 확인할 수 없는 경우를 제외하고는 검열할 수 없다. <개정 2020.2.4>', 6925);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12005, '① 소장은 미결수용자에 대하여는 신청에 따라 교육 또는 교화프로그램을 실시하거나 작업을 부과할 수 있다.', 6927);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12006, '② 제1항에 따라 미결수용자에게 교육 또는 교화프로그램을 실시하거나 작업을 부과하는 경우에는 제63조부터 제65조까지 및 제70조부터 제76조까지의 규정을 준용한다.', 6927);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12007, '① 사형확정자는 독거수용한다. 다만, 자살방지, 교육ㆍ교화프로그램, 작업, 그 밖의 적절한 처우를 위하여 필요한 경우에는 법무부령으로 정하는 바에 따라 혼거수용할 수 있다.', 6930);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12008, '② 사형확정자가 수용된 거실은 참관할 수 없다.', 6930);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12009, '① 소장은 사형확정자의 심리적 안정 및 원만한 수용생활을 위하여 교육 또는 교화프로그램을 실시하거나 신청에 따라 작업을 부과할 수 있다. <개정 2008.12.11>', 6931);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12010, '② 사형확정자에 대한 교육ㆍ교화프로그램, 작업, 그 밖의 처우에 필요한 사항은 법무부령으로 정한다. <개정 2008.12.11>', 6931);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12011, '① 사형은 교정시설의 사형장에서 집행한다.', 6932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12012, '② 공휴일과 토요일에는 사형을 집행하지 아니한다.', 6932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12013, '① 수용자는 다음 각 호의 물품을 지녀서는 아니 된다. <개정 2019.4.23, 2020.2.4>', 6933);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12014, '② 제1항에도 불구하고 소장이 수용자의 처우를 위하여 허가하는 경우에는 제1항제2호의 물품을 지닐 수 있다. <신설 2019.4.23, 2020.2.4>', 6933);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12015, '① 교도관은 시설의 안전과 질서유지를 위하여 필요하면 수용자의 신체ㆍ의류ㆍ휴대품ㆍ거실 및 작업장 등을 검사할 수 있다.', 6934);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12016, '② 수용자의 신체를 검사하는 경우에는 불필요한 고통이나 수치심을 느끼지 아니하도록 유의하여야 하며, 특히 신체를 면밀하게 검사할 필요가 있으면 다른 수용자가 볼 수 없는 차단된 장소에서 하여야 한다.', 6934);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12017, '③ 교도관은 시설의 안전과 질서유지를 위하여 필요하면 교정시설을 출입하는 수용자 외의 사람에 대하여 의류와 휴대품을 검사할 수 있다. 이 경우 출입자가 제92조의 금지물품을 지니고 있으면 교정시설에 맡기도록 하여야 하며, 이에 따르지 아니하면 출입을 금지할 수 있다. <개정 2020.2.4>', 6934);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12018, '④ 여성의 신체ㆍ의류 및 휴대품에 대한 검사는 여성교도관이 하여야 한다.', 6934);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12019, '⑤ 소장은 제1항에 따라 검사한 결과 제92조의 금지물품이 발견되면 형사 법령으로 정하는 절차에 따라 처리할 물품을 제외하고는 수용자에게 알린 후 폐기한다. 다만, 폐기하는 것이 부적당한 물품은 교정시설에 보관하거나 수용자로 하여금 자신이 지정하는 사람에게 보내게 할 수 있다. <개정 2020.2.4>', 6934);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12020, '① 교도관은 자살ㆍ자해ㆍ도주ㆍ폭행ㆍ손괴, 그 밖에 수용자의 생명ㆍ신체를 해하거나 시설의 안전 또는 질서를 해하는 행위(이하 "자살등"이라 한다)를 방지하기 위하여 필요한 범위에서 전자장비를 이용하여 수용자 또는 시설을 계호할 수 있다. 다만, 전자영상장비로 거실에 있는 수용자를 계호하는 것은 자살등의 우려가 큰 때에만 할 수 있다.', 6935);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12021, '② 제1항 단서에 따라 거실에 있는 수용자를 전자영상장비로 계호하는 경우에는 계호직원ㆍ계호시간 및 계호대상 등을 기록하여야 한다. 이 경우 수용자가 여성이면 여성교도관이 계호하여야 한다.', 6935);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12022, '③ 제1항 및 제2항에 따라 계호하는 경우에는 피계호자의 인권이 침해되지 아니하도록 유의하여야 한다.', 6935);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12023, '④ 전자장비의 종류ㆍ설치장소ㆍ사용방법 및 녹화기록물의 관리 등에 관하여 필요한 사항은 법무부령으로 정한다.', 6935);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12024, '① 소장은 수용자가 다음 각 호의 어느 하나에 해당하면 의무관의 의견을 고려하여 보호실(자살 및 자해 방지 등의 설비를 갖춘 거실을 말한다. 이하 같다)에 수용할 수 있다.', 6936);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12025, '② 수용자의 보호실 수용기간은 15일 이내로 한다. 다만, 소장은 특히 계속하여 수용할 필요가 있으면 의무관의 의견을 고려하여 1회당 7일의 범위에서 기간을 연장할 수 있다. <개정 2019.4.23>', 6936);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12026, '③ 제2항에 따라 수용자를 보호실에 수용할 수 있는 기간은 계속하여 3개월을 초과할 수 없다. <개정 2019.4.23>', 6936);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12027, '④ 소장은 수용자를 보호실에 수용하거나 수용기간을 연장하는 경우에는 그 사유를 본인에게 알려 주어야 한다.', 6936);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12028, '⑤ 의무관은 보호실 수용자의 건강상태를 수시로 확인하여야 한다.', 6936);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12029, '⑥ 소장은 보호실 수용사유가 소멸한 경우에는 보호실 수용을 즉시 중단하여야 한다.', 6936);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12030, '① 소장은 수용자가 다음 각 호의 어느 하나에 해당하는 경우로서 강제력을 행사하거나 제98조의 보호장비를 사용하여도 그 목적을 달성할 수 없는 경우에만 진정실(일반 수용거실로부터 격리되어 있고 방음설비 등을 갖춘 거실을 말한다. 이하 같다)에 수용할 수 있다. <개정 2016.5.29>', 6937);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12031, '② 수용자의 진정실 수용기간은 24시간 이내로 한다. 다만, 소장은 특히 계속하여 수용할 필요가 있으면 의무관의 의견을 고려하여 1회당 12시간의 범위에서 기간을 연장할 수 있다. <개정 2019.4.23>', 6937);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12032, '③ 제2항에 따라 수용자를 진정실에 수용할 수 있는 기간은 계속하여 3일을 초과할 수 없다. <개정 2019.4.23>', 6937);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12033, '④ 진정실 수용자에 대하여는 제95조제4항부터 제6항까지의 규정을 준용한다.', 6937);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12034, '① 교도관은 수용자가 다음 각 호의 어느 하나에 해당하면 보호장비를 사용할 수 있다. <개정 2016.5.29>', 6938);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12035, '② 보호장비를 사용하는 경우에는 수용자의 나이, 건강상태 및 수용생활 태도 등을 고려하여야 한다.', 6938);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12036, '③ 교도관이 교정시설의 안에서 수용자에 대하여 보호장비를 사용한 경우 의무관은 그 수용자의 건강상태를 수시로 확인하여야 한다.', 6938);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12037, '① 보호장비의 종류는 다음 각 호와 같다.', 6939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12038, '② 보호장비의 종류별 사용요건은 다음 각 호와 같다.', 6939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12039, '③ 보호장비의 사용절차 등에 관하여 필요한 사항은 대통령령으로 정한다.', 6939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12040, '① 교도관은 필요한 최소한의 범위에서 보호장비를 사용하여야 하며, 그 사유가 없어지면 사용을 지체 없이 중단하여야 한다. <개정 2020.2.4>', 6940);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12041, '② 보호장비는 징벌의 수단으로 사용되어서는 아니 된다.', 6940);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12042, '① 교도관은 수용자가 다음 각 호의 어느 하나에 해당하면 강제력을 행사할 수 있다. <개정 2016.5.29>', 6941);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12043, '② 교도관은 수용자 외의 사람이 다음 각 호의 어느 하나에 해당하면 강제력을 행사할 수 있다. <개정 2016.5.29, 2020.2.4>', 6941);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12044, '③ 제1항 및 제2항에 따라 강제력을 행사하는 경우에는 보안장비를 사용할 수 있다.', 6941);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12045, '④ 제3항에서 "보안장비"란 교도봉ㆍ가스분사기ㆍ가스총ㆍ최루탄 등 사람의 생명과 신체의 보호, 도주의 방지 및 시설의 안전과 질서유지를 위하여 교도관이 사용하는 장비와 기구를 말한다. <개정 2016.5.29>', 6941);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12046, '⑤ 제1항 및 제2항에 따라 강제력을 행사하려면 사전에 상대방에게 이를 경고하여야 한다. 다만, 상황이 급박하여 경고할 시간적인 여유가 없는 때에는 그러하지 아니하다.', 6941);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12047, '⑥ 강제력의 행사는 필요한 최소한도에 그쳐야 한다.', 6941);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12048, '⑦ 보안장비의 종류, 종류별 사용요건 및 사용절차 등에 관하여 필요한 사항은 법무부령으로 정한다.', 6941);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12049, '① 교도관은 다음 각 호의 어느 하나에 해당하는 사유가 있으면 수용자에 대하여 무기를 사용할 수 있다. <개정 2016.5.29, 2020.2.4>', 6942);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12050, '② 교도관은 교정시설의 안(교도관이 교정시설의 밖에서 수용자를 계호하고 있는 경우 그 장소를 포함한다)에서 자기 또는 타인의 생명ㆍ신체를 보호하거나 수용자의 탈취를 저지하거나 건물 또는 그 밖의 시설과 무기에 대한 위험을 방지하기 위하여 급박하다고 인정되는 상당한 이유가 있으면 수용자 외의 사람에 대하여도 무기를 사용할 수 있다. <개정 2016.5.29>', 6942);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12051, '③ 교도관은 소장 또는 그 직무를 대행하는 사람의 명령을 받아 무기를 사용한다. 다만, 그 명령을 받을 시간적 여유가 없으면 그러하지 아니하다. <개정 2016.5.29>', 6942);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12052, '④ 제1항 및 제2항에 따라 무기를 사용하려면 공포탄을 발사하거나 그 밖에 적당한 방법으로 사전에 상대방에 대하여 이를 경고하여야 한다.', 6942);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12053, '⑤ 무기의 사용은 필요한 최소한도에 그쳐야 하며, 최후의 수단이어야 한다.', 6942);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12054, '⑥ 사용할 수 있는 무기의 종류, 무기의 종류별 사용요건 및 사용절차 등에 관하여 필요한 사항은 법무부령으로 정한다.', 6942);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12055, '① 천재지변이나 그 밖의 재해가 발생하여 시설의 안전과 질서유지를 위하여 긴급한 조치가 필요하면 소장은 수용자로 하여금 피해의 복구나 그 밖의 응급용무를 보조하게 할 수 있다.', 6943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12056, '② 소장은 교정시설의 안에서 천재지변이나 그 밖의 사변에 대한 피난의 방법이 없는 경우에는 수용자를 다른 장소로 이송할 수 있다.', 6943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12057, '③ 소장은 제2항에 따른 이송이 불가능하면 수용자를 일시 석방할 수 있다.', 6943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12058, '④ 제3항에 따라 석방된 사람은 석방 후 24시간 이내에 교정시설 또는 경찰관서에 출석하여야 한다. <개정 2020.2.4>', 6943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12059, '① 교도관은 수용자가 도주 또는 제134조 각 호의 어느 하나에 해당하는 행위(이하 "도주등"이라 한다)를 한 경우에는 도주 후 또는 출석기한이 지난 후 72시간 이내에만 그를 체포할 수 있다. <개정 2019.4.23>', 6944);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12060, '② 교도관은 제1항에 따른 체포를 위하여 긴급히 필요하면 도주등을 하였다고 의심할 만한 상당한 이유가 있는 사람 또는 도주등을 한 사람의 이동경로나 소재를 안다고 인정되는 사람을 정지시켜 질문할 수 있다.', 6944);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12061, '③ 교도관은 제2항에 따라 질문을 할 때에는 그 신분을 표시하는 증표를 제시하고 질문의 목적과 이유를 설명하여야 한다.', 6944);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12062, '④ 교도관은 제1항에 따른 체포를 위하여 영업시간 내에 공연장ㆍ여관ㆍ음식점ㆍ역, 그 밖에 다수인이 출입하는 장소의 관리자 또는 관계인에게 그 장소의 출입이나 그 밖에 특히 필요한 사항에 관하여 협조를 요구할 수 있다. <개정 2020.2.4>', 6944);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12063, '⑤ 교도관은 제4항에 따라 필요한 장소에 출입하는 경우에는 그 신분을 표시하는 증표를 제시하여야 하며, 그 장소의 관리자 또는 관계인의 정당한 업무를 방해하여서는 아니 된다.', 6944);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12064, '① 소장은 마약류사범ㆍ조직폭력사범 등 법무부령으로 정하는 수용자에 대하여는 시설의 안전과 질서유지를 위하여 필요한 범위에서 다른 수용자와의 접촉을 차단하거나 계호를 엄중히 하는 등 법무부령으로 정하는 바에 따라 다른 수용자와 달리 관리할 수 있다.', 6945);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12065, '② 소장은 제1항에 따라 관리하는 경우에도 기본적인 처우를 제한하여서는 아니 된다.', 6945);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12066, '① 수용자는 교정시설의 안전과 질서유지를 위하여 법무부장관이 정하는 규율을 지켜야 한다. <개정 2020.2.4>', 6946);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12067, '② 수용자는 소장이 정하는 일과시간표를 지켜야 한다. <개정 2020.2.4>', 6946);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12068, '③ 수용자는 교도관의 직무상 지시에 따라야 한다. <개정 2020.2.4>', 6946);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12069, null, 6947);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12070, null, 6948);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12071, null, 6949);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12072, '① 제108조제4호부터 제13호까지의 처분은 함께 부과할 수 있다.', 6950);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12073, '② 수용자가 다음 각 호의 어느 하나에 해당하면 제108조제2호부터 제14호까지의 규정에서 정한 징벌의 장기의 2분의 1까지 가중할 수 있다.', 6950);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12074, '③ 징벌은 동일한 행위에 관하여 거듭하여 부과할 수 없으며, 행위의 동기 및 경중, 행위 후의 정황, 그 밖의 사정을 고려하여 수용목적을 달성하는 데에 필요한 최소한도에 그쳐야 한다.', 6950);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12075, '④ 징벌사유가 발생한 날부터 2년이 지나면 이를 이유로 징벌을 부과하지 못한다.', 6950);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12076, '① 소장은 징벌사유에 해당하는 행위를 하였다고 의심할 만한 상당한 이유가 있는 수용자(이하 "징벌대상자"라 한다)가 다음 각 호의 어느 하나에 해당하면 조사기간 중 분리하여 수용할 수 있다.', 6951);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12077, '② 소장은 징벌대상자가 제1항 각 호의 어느 하나에 해당하면 접견ㆍ편지수수ㆍ전화통화ㆍ실외운동ㆍ작업ㆍ교육훈련, 공동행사 참가, 중간처우 등 다른 사람과의 접촉이 가능한 처우의 전부 또는 일부를 제한할 수 있다. <개정 2015.3.27, 2020.2.4>', 6951);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12078, '① 징벌대상자의 징벌을 결정하기 위하여 교정시설에 징벌위원회(이하 이 조에서 "위원회"라 한다)를 둔다.', 6952);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12079, '② 위원회는 위원장을 포함한 5명 이상 7명 이하의 위원으로 구성하고, 위원장은 소장의 바로 다음 순위자가 되며, 위원은 소장이 소속 기관의 과장(지소의 경우에는 7급 이상의 교도관) 및 교정에 관한 학식과 경험이 풍부한 외부인사 중에서 임명 또는 위촉한다. 이 경우 외부위원은 3명 이상으로 한다. <개정 2020.2.4>', 6952);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12080, '③ 위원회는 소장의 징벌요구에 따라 개회하며, 징벌은 그 의결로써 정한다.', 6952);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12081, '④ 위원이 징벌대상자의 친족이거나 그 밖에 공정한 심의ㆍ의결을 기대할 수 없는 특별한 사유가 있는 경우에는 위원회에 참석할 수 없다.', 6952);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12082, '⑤ 징벌대상자는 위원에 대하여 기피신청을 할 수 있다. 이 경우 위원회의 의결로 기피 여부를 결정하여야 한다.', 6952);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12083, '⑥ 위원회는 징벌대상자가 위원회에 출석하여 충분한 진술을 할 수 있는 기회를 부여하여야 하며, 징벌대상자는 서면 또는 말로써 자기에게 유리한 사실을 진술하거나 증거를 제출할 수 있다.', 6952);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12084, '⑦ 위원회의 위원 중 공무원이 아닌 사람은 「형법」 제127조 및 제129조부터 제132조까지의 규정을 적용할 때에는 공무원으로 본다. <신설 2016.1.6>', 6952);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12085, '① 징벌은 소장이 집행한다.', 6954);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12086, '② 소장은 징벌집행을 위하여 필요하다고 인정하면 수용자를 분리하여 수용할 수 있다.', 6954);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12087, '③ 제108조제14호의 처분을 받은 사람에게는 그 기간 중 같은 조 제4호부터 제12호까지의 처우제한이 함께 부과된다. 다만, 소장은 수용자의 권리구제, 수형자의 교화 또는 건전한 사회복귀를 위하여 특히 필요하다고 인정하면 집필ㆍ편지수수 또는 접견을 허가할 수 있다. <개정 2016.12.2, 2020.2.4>', 6954);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12088, '④ 소장은 제108조제14호의 처분을 받은 사람에게 다음 각 호의 어느 하나에 해당하는 사유가 있어 필요하다고 인정하는 경우에는 건강유지에 지장을 초래하지 아니하는 범위에서 실외운동을 제한할 수 있다. <신설 2016.12.2, 2020.2.4>', 6954);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12089, '⑤ 소장은 제108조제13호에 따른 실외운동 정지를 부과하는 경우 또는 제4항에 따라 실외운동을 제한하는 경우라도 수용자가 매주 1회 이상 실외운동을 할 수 있도록 하여야 한다. <신설 2020.2.4>', 6954);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12090, '⑥ 소장은 제108조제13호 또는 제14호의 처분을 집행하는 경우에는 의무관으로 하여금 사전에 수용자의 건강을 확인하도록 하여야 하며, 집행 중인 경우에도 수시로 건강상태를 확인하여야 한다. <개정 2016.12.2, 2020.2.4>', 6954);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12091, '① 소장은 질병이나 그 밖의 사유로 징벌집행이 곤란하면 그 사유가 해소될 때까지 그 집행을 일시 정지할 수 있다.', 6955);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12092, '② 소장은 징벌집행 중인 사람이 뉘우치는 빛이 뚜렷한 경우에는 그 징벌을 감경하거나 남은 기간의 징벌집행을 면제할 수 있다.', 6955);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12093, '① 징벌위원회는 징벌을 의결하는 때에 행위의 동기 및 정황, 교정성적, 뉘우치는 정도 등 그 사정을 고려할 만한 사유가 있는 수용자에 대하여 2개월 이상 6개월 이하의 기간 내에서 징벌의 집행을 유예할 것을 의결할 수 있다.', 6956);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12094, '② 소장은 징벌집행의 유예기간 중에 있는 수용자가 다시 제107조의 징벌대상행위를 하여 징벌이 결정되면 그 유예한 징벌을 집행한다.', 6956);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12095, '③ 수용자가 징벌집행을 유예받은 후 징벌을 받음이 없이 유예기간이 지나면 그 징벌의 집행은 종료된 것으로 본다.', 6956);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12096, '① 소장은 징벌의 집행이 종료되거나 집행이 면제된 수용자가 교정성적이 양호하고 법무부령으로 정하는 기간 동안 징벌을 받지 아니하면 법무부장관의 승인을 받아 징벌을 실효시킬 수 있다.', 6957);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12097, '② 제1항에도 불구하고 소장은 수용자가 교정사고 방지에 뚜렷한 공로가 있다고 인정되면 분류처우위원회의 의결을 거친 후 법무부장관의 승인을 받아 징벌을 실효시킬 수 있다.', 6957);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12098, '③ 이 법에 규정된 사항 외에 징벌에 관하여 필요한 사항은 법무부령으로 정한다.', 6957);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12099, '① 수용자는 그 처우에 관하여 소장에게 면담을 신청할 수 있다.', 6958);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12100, '② 소장은 수용자의 면담신청이 있으면 다음 각 호의 어느 하나에 해당하는 사유가 있는 경우를 제외하고는 면담을 하여야 한다. <개정 2020.2.4>', 6958);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12101, '③ 소장은 특별한 사정이 있으면 소속 교도관으로 하여금 그 면담을 대리하게 할 수 있다. 이 경우 면담을 대리한 사람은 그 결과를 소장에게 지체 없이 보고하여야 한다.', 6958);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12102, '④ 소장은 면담한 결과 처리가 필요한 사항이 있으면 그 처리결과를 수용자에게 알려야 한다. <개정 2020.2.4>', 6958);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12103, '① 수용자는 그 처우에 관하여 불복하는 경우 법무부장관ㆍ순회점검공무원 또는 관할 지방교정청장에게 청원할 수 있다.', 6959);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12104, '② 제1항에 따라 청원하려는 수용자는 청원서를 작성하여 봉한 후 소장에게 제출하여야 한다. 다만, 순회점검공무원에 대한 청원은 말로도 할 수 있다.', 6959);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12105, '③ 소장은 청원서를 개봉하여서는 아니 되며, 이를 지체 없이 법무부장관ㆍ순회점검공무원 또는 관할 지방교정청장에게 보내거나 순회점검공무원에게 전달하여야 한다.', 6959);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12106, '④ 제2항 단서에 따라 순회점검공무원이 청원을 청취하는 경우에는 해당 교정시설의 교도관이 참여하여서는 아니 된다. <개정 2016.5.29>', 6959);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12107, '⑤ 청원에 관한 결정은 문서로 하여야 한다. <개정 2020.2.4>', 6959);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12108, '⑥ 소장은 청원에 관한 결정서를 접수하면 청원인에게 지체 없이 전달하여야 한다.', 6959);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12109, '① 수용자는 「공공기관의 정보공개에 관한 법률」에 따라 법무부장관, 지방교정청장 또는 소장에게 정보의 공개를 청구할 수 있다.', 6960);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12110, '② 현재의 수용기간 동안 법무부장관, 지방교정청장 또는 소장에게 제1항에 따른 정보공개청구를 한 후 정당한 사유 없이 그 청구를 취하하거나 「공공기관의 정보공개에 관한 법률」 제17조에 따른 비용을 납부하지 아니한 사실이 2회 이상 있는 수용자가 제1항에 따른 정보공개청구를 한 경우에 법무부장관, 지방교정청장 또는 소장은 그 수용자에게 정보의 공개 및 우송 등에 들 것으로 예상되는 비용을 미리 납부하게 할 수 있다.', 6960);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12111, '③ 제2항에 따라 정보의 공개 및 우송 등에 들 것으로 예상되는 비용을 미리 납부하여야 하는 수용자가 비용을 납부하지 아니한 경우 법무부장관, 지방교정청장 또는 소장은 그 비용을 납부할 때까지 「공공기관의 정보공개에 관한 법률」 제11조에 따른 정보공개 여부의 결정을 유예할 수 있다.', 6960);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12112, '④ 제2항에 따른 예상비용의 산정방법, 납부방법, 납부기간, 그 밖에 비용납부에 관하여 필요한 사항은 대통령령으로 정한다.', 6960);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12113, '① 위원회는 위원장을 포함한 5명 이상 9명 이하의 위원으로 구성한다. <개정 2020.2.4>', 6963);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12114, '② 위원장은 법무부차관이 되고, 위원은 판사, 검사, 변호사, 법무부 소속 공무원, 교정에 관한 학식과 경험이 풍부한 사람 중에서 법무부장관이 임명 또는 위촉한다.', 6963);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12115, '③ 위원회의 심사과정 및 심사내용의 공개범위와 공개시기는 다음 각 호와 같다. 다만, 제2호 및 제3호의 내용 중 개인의 신상을 특정할 수 있는 부분은 삭제하고 공개하되, 국민의 알권리를 충족할 필요가 있는 등의 사유가 있는 경우에는 위원회가 달리 의결할 수 있다. <개정 2011.7.18, 2020.2.4>', 6963);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12116, '④ 위원회의 위원 중 공무원이 아닌 사람은 「형법」 제127조 및 제129조부터 제132조까지의 규정을 적용할 때에는 공무원으로 본다. <신설 2016.1.6>', 6963);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12117, '⑤ 그 밖에 위원회에 관하여 필요한 사항은 법무부령으로 정한다. <신설 2011.7.18, 2016.1.6>', 6963);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12118, '① 소장은 「형법」 제72조제1항의 기간이 지난 수형자에 대하여는 법무부령으로 정하는 바에 따라 위원회에 가석방 적격심사를 신청하여야 한다.', 6964);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12119, '② 위원회는 수형자의 나이, 범죄동기, 죄명, 형기, 교정성적, 건강상태, 가석방 후의 생계능력, 생활환경, 재범의 위험성, 그 밖에 필요한 사정을 고려하여 가석방의 적격 여부를 결정한다.', 6964);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12120, '① 위원회는 가석방 적격결정을 하였으면 5일 이내에 법무부장관에게 가석방 허가를 신청하여야 한다.', 6965);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12121, '② 법무부장관은 제1항에 따른 위원회의 가석방 허가신청이 적정하다고 인정하면 허가할 수 있다.', 6965);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12122, '① 사면, 가석방, 형의 집행면제, 감형에 따른 석방은 그 서류가 교정시설에 도달한 후 12시간 이내에 하여야 한다. 다만, 그 서류에서 석방일시를 지정하고 있으면 그 일시에 한다. <개정 2020.2.4>', 6967);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12123, '② 형기종료에 따른 석방은 형기종료일에 하여야 한다. <개정 2020.2.4>', 6967);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12124, '③ 권한이 있는 사람의 명령에 따른 석방은 서류가 도달한 후 5시간 이내에 하여야 한다. <개정 2020.2.4>', 6967);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12125, '① 소장은 석방될 수형자의 재범방지, 자립지원 및 피해자 보호를 위하여 필요하다고 인정하면 해당 수형자의 수용이력 또는 사회복귀에 관한 의견을 그의 거주지를 관할하는 경찰관서나 자립을 지원할 법인 또는 개인에게 통보할 수 있다. 다만, 법인 또는 개인에게 통보하는 경우에는 해당 수형자의 동의를 받아야 한다.', 6970);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12126, '② 제1항에 따라 통보하는 수용이력 또는 사회복귀에 관한 의견의 구체적인 사항은 대통령령으로 정한다.', 6970);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12127, '① 소장은 사망한 수용자의 친족 또는 특별한 연고가 있는 사람이 그 시신 또는 유골의 인도를 청구하는 경우에는 인도하여야 한다. 다만, 제3항에 따라 자연장(自然葬)을 하거나 집단으로 매장을 한 후에는 그러하지 아니하다. <개정 2015.3.27>', 6972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12128, '② 소장은 제127조에 따라 수용자가 사망한 사실을 알게 된 사람이 다음 각 호의 어느 하나에 해당하는 기간 이내에 그 시신을 인수하지 아니하거나 시신을 인수할 사람이 없으면 임시로 매장하거나 화장(火葬) 후 봉안하여야 한다. 다만, 감염병 예방 등을 위하여 필요하면 즉시 화장하여야 하며, 그 밖에 필요한 조치를 할 수 있다. <개정 2015.3.27, 2020.2.4>', 6972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12129, '③ 소장은 제2항에 따라 시신을 임시로 매장하거나 화장하여 봉안한 후 2년이 지나도록 시신의 인도를 청구하는 사람이 없을 때에는 다음 각 호의 구분에 따른 방법으로 처리할 수 있다. <개정 2015.3.27>', 6972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12130, '④ 소장은 병원이나 그 밖의 연구기관이 학술연구상의 필요에 따라 수용자의 시신인도를 신청하면 본인의 유언 또는 상속인의 승낙이 있는 경우에 한하여 인도할 수 있다.', 6972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12131, '⑤ 소장은 수용자가 사망하면 법무부장관이 정하는 범위에서 화장ㆍ시신인도 등에 필요한 비용을 인수자에게 지급할 수 있다.', 6972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12132, '① 수용자의 관리ㆍ교정교화 등 사무에 관한 지방교정청장의 자문에 응하기 위하여 지방교정청에 교정자문위원회(이하 이 조에서 "위원회"라 한다)를 둔다. <개정 2019.4.23>', 6973);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12133, '② 위원회는 10명 이상 15명 이하의 위원으로 성별을 고려하여 구성하고, 위원장은 위원 중에서 호선하며, 위원은 교정에 관한 학식과 경험이 풍부한 외부인사 중에서 지방교정청장의 추천을 받아 법무부장관이 위촉한다. <개정 2019.4.23>', 6973);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12134, '③ 이 법에 규정된 사항 외에 위원회에 관하여 필요한 사항은 법무부령으로 정한다.', 6973);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12135, '① 수용자의 교육ㆍ교화ㆍ의료, 그 밖에 수용자의 처우를 후원하기 위하여 교정시설에 교정위원을 둘 수 있다.', 6974);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12136, '② 교정위원은 명예직으로 하며 소장의 추천을 받아 법무부장관이 위촉한다.', 6974);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12137, '① 수용자가 제92조제2항을 위반하여 소장의 허가 없이 무인비행장치, 전자ㆍ통신기기를 지닌 경우 2년 이하의 징역 또는 2천만원 이하의 벌금에 처한다. <개정 2020.2.4>', 6976);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12138, '② 수용자가 제92조제1항제3호를 위반하여 주류ㆍ담배ㆍ화기ㆍ현금ㆍ수표를 지닌 경우 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 2020.2.4>', 6976);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12139, '① 소장의 허가 없이 무인비행장치, 전자ㆍ통신기기를 교정시설에 반입한 사람은 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.', 6977);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12140, '② 주류ㆍ담배ㆍ화기ㆍ현금ㆍ수표ㆍ음란물ㆍ사행행위에 사용되는 물품을 수용자에게 전달할 목적으로 교정시설에 반입한 사람은 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 6977);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12141, '③ 상습적으로 제2항의 죄를 범한 사람은 2년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.', 6977);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12142, null, 6978);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12143, '① 「형의 집행 및 수용자의 처우에 관한 법률」(이하 "법"이라 한다) 제5조의3에 따른 협의체(이하 "협의체"라 한다)는 위원장을 포함하여 12명의 위원으로 구성한다.', 6983);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12144, '② 협의체의 위원장은 법무부차관이 되고, 협의체의 위원은 다음 각 호의 사람이 된다.', 6983);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12145, '③ 협의체의 위원장은 협의체 회의를 소집하며, 회의 개최 7일 전까지 회의의 일시ㆍ장소 및 안건 등을 각 위원에게 알려야 한다.', 6983);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12146, '④ 협의체의 위원장은 협의체의 회의 결과를 위원이 소속된 기관의 장에게 통보해야 한다.', 6983);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12147, '① 판사 또는 검사가 법 제9조제1항에 따라 교도소ㆍ구치소 및 그 지소(이하 "교정시설"이라 한다)를 시찰할 경우에는 미리 그 신분을 나타내는 증표를 교정시설의 장(이하 "소장"이라 한다)에게 제시해야 한다. <개정 2018.12.24, 2019.10.22>', 6984);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12148, '② 소장은 제1항의 경우에 교도관에게 시찰을 요구받은 장소를 안내하게 해야 한다. <개정 2018.12.24>', 6984);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12149, '① 소장은 법 제9조제2항에 따라 판사와 검사 외의 사람이 교정시설의 참관을 신청하는 경우에는 그 성명ㆍ직업ㆍ주소ㆍ나이ㆍ성별 및 참관 목적을 확인한 후 허가 여부를 결정하여야 한다.', 6985);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12150, '② 소장은 외국인에게 참관을 허가할 경우에는 미리 관할 지방교정청장의 승인을 받아야 한다.', 6985);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12151, '③ 소장은 제1항 및 제2항에 따라 허가를 받은 사람에게 참관할 때의 주의사항을 알려주어야 한다.', 6985);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12152, null, 6987);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12153, '① 교도관은 제5조제2호에 따라 독거수용된 사람(이하 "계호상 독거수용자"라 한다)을 수시로 시찰하여 건강상 또는 교화상 이상이 없는지 살펴야 한다.', 6988);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12154, '② 교도관은 제1항의 시찰 결과, 계호상 독거수용자가 건강상 이상이 있는 것으로 보이는 경우에는 교정시설에 근무하는 의사(공중보건의사를 포함한다. 이하 "의무관"이라 한다)에게 즉시 알려야 하고, 교화상 문제가 있다고 인정하는 경우에는 소장에게 지체 없이 보고하여야 한다.', 6988);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12155, '③ 의무관은 제2항의 통보를 받은 즉시 해당 수용자를 상담ㆍ진찰하는 등 적절한 의료조치를 하여야 하며, 계호상 독거수용자를 계속하여 독거수용하는 것이 건강상 해롭다고 인정하는 경우에는 그 의견을 소장에게 즉시 보고하여야 한다.', 6988);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12156, '④ 소장은 계호상 독거수용자를 계속하여 독거수용하는 것이 건강상 또는 교화상 해롭다고 인정하는 경우에는 이를 즉시 중단하여야 한다.', 6988);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12157, '① 소장은 수용자거실에 면적, 정원 및 현재인원을 적은 현황표를 붙여야 한다.', 6994);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12158, '② 소장은 수용자거실 앞에 이름표를 붙이되, 이름표 윗부분에는 수용자의 성명ㆍ출생연도ㆍ죄명ㆍ형명(刑名) 및 형기(刑期)를 적고, 그 아랫부분에는 수용자번호 및 입소일을 적되, 윗부분의 내용이 보이지 않도록 해야 한다. <개정 2014.6.25, 2020.8.5>', 6994);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12159, '③ 소장은 수용자가 법령에 따라 지켜야 할 사항과 수용자의 권리구제 절차에 관한 사항을 수용자거실의 보기 쉬운 장소에 붙이는 등의 방법으로 비치하여야 한다. <개정 2014.6.25>', 6994);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12160, '① 소장은 법원ㆍ검찰청ㆍ경찰관서 등으로부터 처음으로 교정시설에 수용되는 사람(이하 "신입자"라 한다)을 인수한 경우에는 호송인(護送人)에게 인수서를 써 주어야 한다. 이 경우 신입자에게 부상ㆍ질병, 그 밖에 건강에 이상(이하 이 조에서 "부상등"이라 한다)이 있을 때에는 호송인으로부터 그 사실에 대한 확인서를 받아야 한다.', 6995);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12161, '② 신입자를 인수한 교도관은 제1항의 인수서에 신입자의 성명, 나이 및 인수일시를 적고 서명 또는 날인하여야 한다.', 6995);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12162, '③ 소장은 제1항 후단에 따라 확인서를 받는 경우에는 호송인에게 신입자의 성명, 나이, 인계일시 및 부상등의 사실을 적고 서명 또는 날인하도록 하여야 한다.', 6995);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12163, '① 소장은 신입자의 키ㆍ용모ㆍ문신ㆍ흉터 등 신체 특징과 가족 등 보호자의 연락처를 수용기록부에 기록하여야 하며, 교도관이 업무상 필요한 경우가 아니면 이를 열람하지 못하도록 하여야 한다.', 6999);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12164, '② 소장은 신입자 및 다른 교정시설로부터 이송(移送)되어 온 사람(이하 "이입자"라 한다)에 대하여 수용자번호를 지정하고 수용 중 번호표를 상의의 왼쪽 가슴에 붙이게 하여야 한다. 다만, 수용자의 교화 또는 건전한 사회복귀를 위하여 특히 필요하다고 인정하면 번호표를 붙이지 아니할 수 있다.', 6999);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12165, '① 소장은 신입자가 환자이거나 부득이한 사정이 있는 경우가 아니면 수용된 날부터 3일 동안 신입자거실에 수용하여야 한다.', 7000);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12166, '② 소장은 제1항에 따라 신입자거실에 수용된 사람에게는 작업을 부과해서는 아니 된다.', 7000);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12167, '③ 소장은 19세 미만의 신입자 그 밖에 특히 필요하다고 인정하는 수용자에 대하여는 제1항의 기간을 30일까지 연장할 수 있다.', 7000);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12168, '①소장은 신입자의 신원에 관한 사항을 조사하여 수용기록부에 기록하여야 한다. <개정 2012.1.6>', 7002);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12169, '② 소장은 신입자의 본인 확인 및 수용자의 처우 등을 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보, 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <신설 2012.1.6>', 7002);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12170, '① 지방교정청장은 법 제20조제2항에 따라 다음 각 호의 어느 하나에 해당하는 경우에는 수용자의 이송을 승인할 수 있다.', 7004);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12171, '② 제1항에 따른 지방교정청장의 이송승인은 관할 내 이송으로 한정한다.', 7004);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12172, '① 소장은 법 제22조제1항에 따라 의류ㆍ침구, 그 밖의 생활용품(이하 "의류등"이라 한다)을 지급하는 경우에는 수용자의 건강, 계절 등을 고려하여야 한다.', 7007);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12173, '② 소장은 수용자에게 특히 청결하게 관리할 수 있는 재질의 식기를 지급하여야 하며, 다른 사람이 사용한 의류등을 지급하는 경우에는 세탁하거나 소독하여 지급하여야 한다.', 7007);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12174, '① 소장은 거실ㆍ작업장, 그 밖에 수용자가 생활하는 장소(이하 이 조에서 "거실등"이라 한다)에 수용생활에 필요한 기구를 갖춰 둬야 한다.', 7008);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12175, '② 거실등에는 갖춰 둔 기구의 품목ㆍ수량을 기록한 품목표를 붙여야 한다.', 7008);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12176, '① 수용자에게 지급하는 주식은 쌀로 한다. <개정 2014.6.25>', 7010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12177, '② 소장은 쌀 수급이 곤란하거나 그 밖에 필요하다고 인정하면 주식을 쌀과 보리 등 잡곡의 혼합곡으로 하거나 대용식을 지급할 수 있다. <개정 2014.6.25>', 7010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12178, '① 소장은 수용자가 사용하는 의류등을 적당한 시기에 세탁ㆍ수선 또는 교체(이하 이 조에서 "세탁등"이라 한다)하도록 하여야 한다.', 7015);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12179, '② 자비로 구매한 의류등을 세탁등을 하는 경우 드는 비용은 수용자가 부담한다.', 7015);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12180, '① 법 제25조에서 "휴대금품"이란 신입자가 교정시설에 수용될 때에 지니고 있는 현금(자기앞수표를 포함한다. 이하 같다)과 휴대품을 말한다.', 7016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12181, '② 법 제25조제1항 각 호의 어느 하나에 해당하지 아니한 신입자의 휴대품은 보관한 후 사용하게 할 수 있다. <개정 2020.8.5>', 7016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12182, '③ 법 제25조제1항 단서에 따라 신입자의 휴대품을 팔 경우에는 그 비용을 제외한 나머지 대금을 보관할 수 있다. <개정 2020.8.5>', 7016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12183, '④ 소장은 신입자가 법 제25조제1항 각 호의 어느 하나에 해당하는 휴대품을 법무부장관이 정한 기간에 처분하지 않은 경우에는 본인에게 그 사실을 고지한 후 폐기한다.', 7016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12184, '① 소장은 수용자가 그의 가족(배우자, 직계존비속 또는 형제자매를 말한다. 이하 같다) 또는 배우자의 직계존속에게 도움을 주거나 그 밖에 정당한 용도로 사용하기 위하여 보관금의 사용을 신청한 경우에는 그 사정을 고려하여 허가할 수 있다. <개정 2020.8.5>', 7020);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12185, '② 제1항에 따라 보관금을 사용하는 경우 발생하는 비용은 수용자가 부담한다. <개정 2020.8.5>', 7020);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12186, '③ 보관금의 출납ㆍ예탁(預託), 보관금품의 보관 등에 관하여 필요한 사항은 법무부장관이 정한다. <개정 2020.8.5>', 7020);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12187, '① 소장은 법 제27조제1항에 따라 수용자에 대한 금품의 전달을 허가한 경우에는 그 금품을 보관한 후 해당 수용자가 사용하게 할 수 있다. <개정 2020.8.5>', 7024);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12188, '② 법 제27조제1항에 따라 수용자에게 건네주려고 하는 금품의 허가범위 등에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2020.8.5>', 7024);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12189, '① 소장은 사망자의 유류품을 건네받을 사람이 원거리에 있는 등 특별한 사정이 있는 경우에는 유류품을 받을 사람의 청구에 따라 유류품을 팔아 그 대금을 보낼 수 있다. <개정 2020.8.5>', 7027);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12190, '② 법 제28조에 따라 사망자의 유류금품을 보내거나 제1항에 따라 유류품을 팔아 대금을 보내는 경우에 드는 비용은 유류금품의 청구인이 부담한다.', 7027);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12191, '① 소장은 거실ㆍ작업장ㆍ목욕탕, 그 밖에 수용자가 공동으로 사용하는 시설과 취사장, 주식ㆍ부식 저장고, 그 밖에 음식물 공급과 관련된 시설을 수시로 청소ㆍ소독하여야 한다.', 7029);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12192, '② 소장은 저수조 등 급수시설을 6개월에 1회 이상 청소ㆍ소독하여야 한다.', 7029);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12193, null, 7031);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12194, '① 소장은 수용자에 대하여 1년에 1회 이상 건강검진을 하여야 한다. 다만, 19세 미만의 수용자와 계호상 독거수용자에 대하여는 6개월에 1회 이상 하여야 한다.', 7033);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12195, '② 제1항의 건강검진은 「건강검진기본법」 제14조에 따라 지정된 건강검진기관에 의뢰하여 할 수 있다. <개정 2009.3.18>', 7033);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12196, '① 소장은 수용자가 감염병에 걸렸다고 의심되는 경우에는 1주 이상 격리수용하고 그 수용자의 휴대품을 소독하여야 한다. <개정 2010.12.29>', 7035);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12197, '② 소장은 감염병이 유행하는 경우에는 수용자가 자비로 구매하는 음식물의 공급을 중지할 수 있다. <개정 2010.12.29>', 7035);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12198, '③ 소장은 수용자가 감염병에 걸린 경우에는 즉시 격리수용하고 그 수용자가 사용한 물품과 설비를 철저히 소독하여야 한다. <개정 2010.12.29>', 7035);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12199, '④ 소장은 제3항의 사실을 지체 없이 법무부장관에게 보고하고 관할 보건기관의 장에게 알려야 한다.', 7035);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12200, null, 7037);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12201, '① 수용자의 접견은 매일(공휴일 및 법무부장관이 정한 날은 제외한다) 「국가공무원 복무규정」 제9조에 따른 근무시간 내에서 한다.', 7041);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12202, '② 변호인(변호인이 되려고 하는 사람을 포함한다. 이하 같다)과 접견하는 미결수용자를 제외한 수용자의 접견시간은 회당 30분 이내로 한다. <개정 2014.6.25>', 7041);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12203, '③ 수형자의 접견 횟수는 매월 4회로 한다.', 7041);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12204, '④ 삭제 <2019.10.22>', 7041);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12205, '⑤ 법 및 이 영에 규정된 사항 외에 수형자, 사형확정자 및 미결수용자를 제외한 수용자의 접견 횟수ㆍ시간ㆍ장소 등에 관하여 필요한 사항은 법무부장관이 정한다.', 7041);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12206, '⑥ 소장은 교정시설의 외부에 있는 사람의 수용자 접견에 관한 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 시행령 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <신설 2012.1.6>', 7041);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12207, '① 소장은 제58조제1항 및 제2항에도 불구하고 수형자의 교화 또는 건전한 사회복귀를 위하여 특히 필요하다고 인정하면 접견 시간대 외에도 접견을 하게 할 수 있고 접견시간을 연장할 수 있다.', 7042);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12208, '② 소장은 제58조제3항에도 불구하고 수형자가 다음 각 호의 어느 하나에 해당하면 접견 횟수를 늘릴 수 있다.', 7042);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12209, '③ 법 제41조제3항제2호에서 "대통령령으로 정하는 경우"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다. <개정 2019.10.22>', 7042);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12210, '① 제58조제2항에도 불구하고 수용자가 다음 각 호의 어느 하나에 해당하는 변호사와 접견하는 시간은 회당 60분으로 한다. <개정 2019.10.22>', 7043);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12211, '② 수용자가 제1항 각 호의 변호사와 접견하는 횟수는 다음 각 호의 구분에 따르되, 이를 제58조제3항, 제101조 및 제109조의 접견 횟수에 포함시키지 아니한다. <개정 2019.10.22>', 7043);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12212, '③ 소장은 제58조제1항과 이 조 제1항 및 제2항에도 불구하고 소송사건의 수 또는 소송내용의 복잡성 등을 고려하여 소송의 준비를 위하여 특히 필요하다고 인정하면 접견 시간대 외에도 접견을 하게 할 수 있고, 접견 시간 및 횟수를 늘릴 수 있다.', 7043);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12213, '④ 소장은 제1항 및 제2항에도 불구하고 접견 수요 또는 접견실 사정 등을 고려하여 원활한 접견 사무 진행에 현저한 장애가 발생한다고 판단하면 접견 시간 및 횟수를 줄일 수 있다. 이 경우 줄어든 시간과 횟수는 다음 접견 시에 추가하도록 노력하여야 한다.', 7043);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12214, '⑤ 수용자가 「형사소송법」에 따른 상소권회복 또는 재심 청구사건의 대리인이 되려는 변호사와 접견하는 경우에는 교정시설의 안전 또는 질서를 해칠 우려가 없는 한 접촉차단시설이 설치되지 않은 장소에서 접견하게 한다. <신설 2019.10.22>', 7043);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12215, '⑥ 제1항부터 제5항까지에서 규정한 사항 외에 수용자와 제1항 각 호의 변호사의 접견에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2019.10.22>', 7043);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12216, '① 수용자와 교정시설 외부의 사람이 접견하는 경우에 법 제41조제4항에 따라 접견내용이 청취ㆍ녹음 또는 녹화될 때에는 외국어를 사용해서는 아니 된다. 다만, 국어로 의사소통하기 곤란한 사정이 있는 경우에는 외국어를 사용할 수 있다. <개정 2019.10.22>', 7044);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12217, '② 소장은 제1항 단서의 경우에 필요하다고 인정하면 교도관 또는 통역인으로 하여금 통역하게 할 수 있다.', 7044);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12218, '① 소장은 법 제41조제4항의 청취ㆍ기록을 위하여 다음 각 호의 사람을 제외한 수용자의 접견에 교도관을 참여하게 할 수 있다. <개정 2016.6.28, 2019.10.22>', 7046);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12219, '② 소장은 특별한 사정이 없으면 교도관으로 하여금 법 제41조제5항에 따라 수용자와 그 상대방에게 접견내용의 녹음ㆍ녹화 사실을 수용자와 그 상대방이 접견실에 들어가기 전에 미리 말이나 서면 등 적절한 방법으로 알려 주게 하여야 한다. <개정 2019.10.22>', 7046);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12220, '③ 소장은 법 제41조제4항에 따라 청취ㆍ녹음ㆍ녹화한 경우의 접견기록물에 대한 보호ㆍ관리를 위하여 접견정보 취급자를 지정하여야 하고, 접견정보 취급자는 직무상 알게 된 접견정보를 누설하거나 권한 없이 처리하거나 다른 사람이 이용하도록 제공하는 등 부당한 목적을 위하여 사용해서는 아니 된다. <개정 2019.10.22>', 7046);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12221, '④ 소장은 관계기관으로부터 다음 각 호의 어느 하나에 해당하는 사유로 제3항의 접견기록물의 제출을 요청받은 경우에는 기록물을 제공할 수 있다.', 7046);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12222, '⑤ 소장은 제4항에 따라 녹음ㆍ녹화 기록물을 제공할 경우에는 제3항의 접견정보 취급자로 하여금 녹음ㆍ녹화기록물을 요청한 기관의 명칭, 제공받는 목적, 제공 근거, 제공을 요청한 범위, 그 밖에 필요한 사항을 녹음ㆍ녹화기록물 관리프로그램에 입력하게 하고, 따로 이동식 저장매체에 옮겨 담아 제공한다.', 7046);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12223, '① 수용자는 편지를 보내려는 경우 해당 편지를 봉함하여 교정시설에 제출한다. 다만, 소장은 다음 각 호의 어느 하나에 해당하는 경우로서 법 제43조제3항에 따른 금지물품의 확인을 위하여 필요한 경우에는 편지를 봉함하지 않은 상태로 제출하게 할 수 있다. <개정 2013.2.5, 2017.9.19, 2020.8.5>', 7049);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12224, '② 소장은 수용자에게 온 편지에 금지물품이 들어 있는지를 개봉하여 확인할 수 있다. <개정 2020.8.5>', 7049);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12225, '① 소장은 법 제43조제4항제4호에 따라 다음 각 호의 어느 하나에 해당하는 수용자가 다른 수용자와 편지를 주고받는 때에는 그 내용을 검열할 수 있다. <개정 2020.8.5>', 7050);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12226, '② 수용자 간에 오가는 편지에 대한 제1항의 검열은 편지를 보내는 교정시설에서 한다. 다만, 특히 필요하다고 인정되는 경우에는 편지를 받는 교정시설에서도 할 수 있다. <개정 2020.8.5>', 7050);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12227, '③ 소장은 수용자가 주고받는 편지가 법 제43조제4항 각 호의 어느 하나에 해당하면 이를 개봉한 후 검열할 수 있다. <신설 2013.2.5, 2020.8.5>', 7050);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12228, '④ 소장은 제3항에 따라 검열한 결과 편지의 내용이 법 제43조제5항의 발신 또는 수신 금지사유에 해당하지 아니하면 발신편지는 봉함한 후 발송하고, 수신편지는 수용자에게 건네준다. <신설 2013.2.5, 2020.8.5>', 7050);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12229, '⑤ 소장은 편지의 내용을 검열했을 때에는 그 사실을 해당 수용자에게 지체 없이 알려주어야 한다. <신설 2013.2.5, 2020.8.5>', 7050);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12230, '① 소장은 수용자가 쉽게 이용할 수 있도록 비치도서의 목록을 정기적으로 공개하여야 한다.', 7056);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12231, '② 비치도서의 열람방법, 열람기간 등에 관하여 필요한 사항은 법무부장관이 정한다.', 7056);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12232, '① 수용자는 휴업일 및 휴게시간 내에 시간의 제한 없이 집필할 수 있다. 다만, 부득이한 사정이 있는 경우에는 그러하지 아니하다.', 7059);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12233, '② 수용자는 거실ㆍ작업장, 그 밖에 지정된 장소에서 집필할 수 있다.', 7059);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12234, '① 소장은 수용자 본인이 작성 또는 집필한 문서나 도화(<img src="http://www.law.go.kr/flDownload.do?flSeq=72505057"  alt="img72505057" >圖</img>)를 외부에 보내거나 내가려고 할 때에는 그 내용을 확인하여 법 제43조제5항 각 호의 어느 하나에 해당하지 않으면 허가해야 한다. <개정 2020.8.5>', 7060);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12235, '② 제1항에 따라 문서나 도화를 외부로 보내거나 내갈 때 드는 비용은 수용자가 부담한다.', 7060);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12236, '③ 법 및 이 영에 규정된 사항 외에 수용자의 집필에 필요한 사항은 법무부장관이 정한다.', 7060);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12237, '① 소장은 제50조에 따라 여성수용자의 목욕횟수를 정하는 경우에는 그 신체적 특성을 특히 고려하여야 한다.', 7061);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12238, '② 소장은 여성수용자가 목욕을 하는 경우에 계호가 필요하다고 인정하면 여성교도관이 하도록 하여야 한다.', 7061);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12239, '① 소장은 유아의 양육을 허가하지 아니하는 경우에는 수용자의 의사를 고려하여 유아보호에 적당하다고 인정하는 법인 또는 개인에게 그 유아를 보낼 수 있다. 다만, 적당한 법인 또는 개인이 없는 경우에는 그 유아를 해당 교정시설의 소재지를 관할하는 시장ㆍ군수 또는 구청장에게 보내서 보호하게 하여야 한다.', 7064);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12240, '② 법 제53조제1항에 따라 양육이 허가된 유아가 출생 후 18개월이 지나거나, 유아양육의 허가를 받은 수용자가 허가의 취소를 요청하는 때 또는 법 제53조제1항 각 호의 어느 하나에 해당되는 때에도 제1항과 같다.', 7064);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12241, '① 법 제54조제1항에서 "노인수용자"란 65세 이상인 수용자를 말한다.', 7065);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12242, '② 법 제54조제2항에서 "장애인수용자"란 시각ㆍ청각ㆍ언어ㆍ지체(肢體) 등의 장애로 통상적인 수용생활이 특히 곤란하다고 인정되는 사람으로서 법무부령으로 정하는 수용자를 말한다.', 7065);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12243, '③ 법 제54조제3항에서 "외국인수용자"란 대한민국의 국적을 가지지 아니한 수용자를 말한다. <신설 2015.12.10>', 7065);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12244, '④ 법 제54조제4항에서 "소년수용자"란 다음 각 호의 사람을 말한다. <신설 2015.12.10>', 7065);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12245, '① 소장은 미결수용자로서 자유형이 확정된 사람에 대하여는 검사의 집행 지휘서가 도달된 때부터 수형자로 처우할 수 있다.', 7066);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12246, '② 제1항의 경우 검사는 집행 지휘를 한 날부터 10일 이내에 재판서나 그 밖에 적법한 서류를 소장에게 보내야 한다.', 7066);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12247, null, 7067);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12248, '① 법 제57조제3항에서 "교정성적"이란 수형자의 수용생활 태도, 상벌 유무, 교육 및 작업의 성과 등을 종합적으로 평가한 결과를 말한다.', 7068);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12249, '② 소장은 수형자의 처우수준을 개별처우계획의 시행에 적합하게 정하거나 조정하기 위하여 교정성적에 따라 처우등급을 부여할 수 있다.', 7068);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12250, '③ 수형자에게 부여하는 처우등급에 관하여 필요한 사항은 법무부령으로 정한다.', 7068);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12251, '① 수형자의 건전한 사회복귀를 지원하기 위하여 교정시설에 취업알선 및 창업지원에 관한 협의기구를 둘 수 있다.', 7069);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12252, '② 제1항의 협의기구의 조직ㆍ운영, 그 밖에 활동에 필요한 사항은 법무부령으로 정한다.', 7069);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12253, '① 소장은 법 제63조에 따른 교육을 효과적으로 시행하기 위하여 교육실을 설치하는 등 교육에 적합한 환경을 조성하여야 한다.', 7071);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12254, '② 소장은 교육 대상자, 시설 여건 등을 고려하여 교육계획을 수립하여 시행하여야 한다.', 7071);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12255, '① 소장은 수형자에게 작업을 부과하는 경우에는 작업의 종류 및 작업과정을 정하여 고지하여야 한다.', 7075);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12256, '② 제1항의 작업과정은 작업성적, 작업시간, 작업의 난이도 및 숙련도를 고려하여 정한다. 작업과정을 정하기 어려운 경우에는 작업시간을 작업과정으로 본다.', 7075);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12257, '① 소장은 법 제77조에 따라 2일 이상의 귀휴를 허가한 경우에는 귀휴를 허가받은 사람(이하 "귀휴자"라 한다)의 귀휴지를 관할하는 경찰관서의 장에게 그 사실을 통보하여야 한다.', 7081);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12258, '② 귀휴자는 귀휴 중 천재지변이나 그 밖의 사유로 자신의 신상에 중대한 사고가 발생한 경우에는 가까운 교정시설이나 경찰관서에 신고하여야 하고 필요한 보호를 요청할 수 있다.', 7081);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12259, '③ 제2항의 보호 요청을 받은 교정시설이나 경찰관서의 장은 귀휴를 허가한 소장에게 그 사실을 지체 없이 통보하고 적절한 보호조치를 하여야 한다.', 7081);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12260, '① 법 제86조제1항의 미결수용자에 대한 교육ㆍ교화프로그램 또는 작업은 교정시설 밖에서 행하는 것은 포함하지 아니한다.', 7087);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12261, '② 소장은 법 제86조제1항에 따라 작업이 부과된 미결수용자가 작업의 취소를 요청하는 경우에는 그 미결수용자의 의사, 건강 및 교도관의 의견 등을 고려하여 작업을 취소할 수 있다.', 7087);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12262, '①교도관 외의 사람은 「국가공무원 복무규정」 제9조에 따른 근무시간 외에는 소장의 허가 없이 교정시설에 출입하지 못한다. <개정 2014.8.6>', 7099);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12263, '② 소장은 외부인의 교정시설 출입에 관한 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법 시행령」 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <신설 2014.8.6>', 7099);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12264, '① 교정시설의 바깥문, 출입구, 거실, 작업장, 그 밖에 수용자를 수용하고 있는 장소는 외부와 차단하여야 한다. 다만, 필요에 따라 일시 개방하는 경우에는 그 장소를 경비하여야 한다.', 7100);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12265, '② 교도관은 접견ㆍ상담ㆍ진료, 그 밖에 수용자의 처우를 위하여 필요한 경우가 아니면 수용자와 외부인이 접촉하게 해서는 아니 된다.', 7100);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12266, '① 법 제95조제5항 및 법 제96조제4항에 따라 의무관이 보호실이나 진정실 수용자의 건강을 확인한 결과 보호실 또는 진정실에 계속 수용하는 것이 부적당하다고 인정하는 경우에는 소장에게 즉시 보고하여야 한다. 이 경우 소장은 특별한 사유가 없으면 보호실 또는 진정실 수용을 즉시 중지하여야 한다.', 7103);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12267, '② 소장은 의무관이 출장ㆍ휴가, 그 밖의 부득이한 사유로 법 제95조제5항 및 법 제96조제4항의 직무를 수행할 수 없을 때에는 그 교정시설에 근무하는 의료관계 직원에게 대행하게 할 수 있다.', 7103);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12268, '① 교도관은 소장의 명령 없이 수용자에게 보호장비를 사용하여서는 아니 된다. 다만, 소장의 명령을 받을 시간적 여유가 없는 경우에는 사용 후 소장에게 즉시 보고하여야 한다.', 7104);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12269, '② 법 및 이 영에 규정된 사항 외에 보호장비의 규격과 사용방법 등에 관하여 필요한 사항은 법무부령으로 정한다.', 7104);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12270, '① 의무관은 수용자에게 보호장비를 계속 사용하는 것이 건강상 부적당하다고 인정하는 경우에는 소장에게 즉시 보고하여야 한다. 이 경우 소장은 특별한 사유가 없으면 보호장비 사용을 즉시 중지하여야 한다.', 7105);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12271, '② 의무관이 출장ㆍ휴가, 그 밖의 부득이한 사유로 법 제97조제3항의 직무를 수행할 수 없을 때에는 제119조제2항을 준용한다.', 7105);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12272, '① 소장은 보호장비의 사용을 명령한 경우에는 수시로 그 사용 실태를 확인ㆍ점검하여야 한다.', 7108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12273, '② 지방교정청장은 소속 교정시설의 보호장비 사용 실태를 정기적으로 점검하여야 한다.', 7108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12274, '① 소장은 법 제102조제1항에 따른 응급용무의 보조를 위하여 교정성적이 우수한 수형자를 선정하여 필요한 훈련을 시킬 수 있다.', 7111);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12275, '② 소장은 법 제102조제3항에 따라 수용자를 일시석방하는 경우에는 같은 조 제4항의 출석 시한과 장소를 알려주어야 한다.', 7111);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12276, '① 소장은 수용자가 도주하거나 법 제134조 각 호의 어느 하나에 해당하는 행위(이하 이 조에서 "도주등"이라 한다)를 한 경우에는 교정시설의 소재지 및 인접지역 또는 도주등을 한 사람(이하 이 조에서 "도주자"라 한다)이 숨을 만한 지역의 경찰관서에 도주자의 사진이나 인상착의를 기록한 서면을 첨부하여 그 사실을 지체 없이 통보하여야 한다. <개정 2019.10.22>', 7112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12277, '② 소장은 수용자가 도주등을 하거나 도주자를 체포한 경우에는 법무부장관에게 지체 없이 보고하여야 한다.', 7112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12278, '① 법무부장관은 「형법」 제145조ㆍ제146조 또는 법 제134조 각 호에 규정된 죄를 지은 수용자를 체포하거나 행정기관 또는 수사기관에 정보를 제공하여 체포하게 한 사람에게 예산의 범위에서 포상금을 지급할 수 있다. <개정 2019.10.22>', 7113);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12279, '② 포상금의 지급기준ㆍ지급방법, 그 밖에 필요한 사항은 법무부장관이 정한다.', 7113);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12280, '① 포상금을 받으려는 사람은 법무부장관이 정하는 바에 따라 포상금 지급 신청서를 지방교정청장에게 제출해야 한다. <개정 2020.8.5>', 7114);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12281, '② 제1항에 따른 신청서를 접수한 지방교정청장은 그 신청서에 법무부장관이 정하는 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 7114);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12282, null, 7115);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12283, '① 소장은 제132조의 통고를 받은 경우에는 징벌을 지체 없이 집행하여야 한다.', 7120);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12284, '② 소장은 수용자가 징벌처분을 받아 접견, 편지수수 또는 전화통화가 제한된 경우에는 그의 가족에게 그 사실을 알려야 한다. 다만, 수용자가 알리는 것을 원하지 않으면 알리지 않는다. <개정 2014.6.25, 2020.8.5>', 7120);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12285, '③ 삭제 <2017.9.19>', 7120);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12286, '④ 소장은 법 제108조제13호 및 제14호의 징벌집행을 마친 경우에는 의무관에게 해당 수용자의 건강을 지체 없이 확인하게 하여야 한다.', 7120);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12287, '⑤ 의무관이 출장, 휴가, 그 밖의 부득이한 사유로 법 제112조제5항 및 이 조 제4항의 직무를 수행할 수 없는 경우에는 제119조제2항을 준용한다. <개정 2019.10.22>', 7120);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12288, '① 소장은 법 제116조제1항에 따라 수용자가 면담을 신청한 경우에는 그 인적사항을 면담부에 기록하고 특별한 사정이 없으면 신청한 순서에 따라 면담하여야 한다.', 7125);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12289, '② 소장은 제1항에 따라 수용자를 면담한 경우에는 그 요지를 면담부에 기록하여야 한다.', 7125);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12290, '③ 소장은 법 제116조제2항 각 호의 어느 하나에 해당하여 수용자의 면담 신청을 받아들이지 아니하는 경우에는 그 사유를 해당 수용자에게 알려주어야 한다.', 7125);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12291, '① 소장은 법 제117조제1항에 따라 수용자가 순회점검공무원(법 제8조에 따라 법무부장관으로부터 순회점검의 명을 받은 법무부 또는 그 소속기관에 근무하는 공무원을 말한다. 이하 같다)에게 청원하는 경우에는 그 인적사항을 청원부에 기록하여야 한다.', 7126);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12292, '② 순회점검공무원은 법 제117조제2항 단서에 따라 수용자가 말로 청원하는 경우에는 그 요지를 청원부에 기록하여야 한다.', 7126);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12293, '③ 순회점검공무원은 법 제117조제1항의 청원에 관하여 결정을 한 경우에는 그 요지를 청원부에 기록하여야 한다.', 7126);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12294, '④ 순회점검공무원은 법 제117조제1항의 청원을 스스로 결정하는 것이 부적당하다고 인정하는 경우에는 그 내용을 법무부장관에게 보고하여야 한다.', 7126);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12295, '⑤ 수용자의 청원처리의 기준ㆍ절차 등에 관하여 필요한 사항은 법무부장관이 정한다.', 7126);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12296, '① 법 제117조의2제2항에 따른 예상비용은 「공공기관의 정보공개에 관한 법률 시행령」 제17조에 따른 수수료와 우편요금(공개되는 정보의 사본ㆍ출력물ㆍ복제물 또는 인화물을 우편으로 송부하는 경우로 한정한다)을 기준으로 공개를 청구한 정보가 모두 공개되었을 경우에 예상되는 비용으로 한다.', 7127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12297, '② 법무부장관, 지방교정청장 또는 소장은 법 제117조의2제2항에 해당하는 수용자가 정보공개의 청구를 한 경우에는 청구를 한 날부터 7일 이내에 제1항에 따른 비용을 산정하여 해당 수용자에게 미리 납부할 것을 통지할 수 있다.', 7127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12298, '③ 제2항에 따라 비용납부의 통지를 받은 수용자는 그 통지를 받은 날부터 7일 이내에 현금 또는 수입인지로 법무부장관, 지방교정청장 또는 소장에게 납부하여야 한다.', 7127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12299, '④ 법무부장관, 지방교정청장 또는 소장은 수용자가 제1항에 따른 비용을 제3항에 따른 납부기한까지 납부하지 아니한 경우에는 해당 수용자에게 정보공개 여부 결정의 유예를 통지할 수 있다.', 7127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12300, '⑤ 법무부장관, 지방교정청장 또는 소장은 제1항에 따른 비용이 납부되면 신속하게 정보공개 여부의 결정을 하여야 한다.', 7127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12301, '⑥ 법무부장관, 지방교정청장 또는 소장은 비공개 결정을 한 경우에는 제3항에 따라 납부된 비용의 전부를 반환하고 부분공개 결정을 한 경우에는 공개 결정한 부분에 대하여 드는 비용을 제외한 금액을 반환하여야 한다.', 7127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12302, '⑦ 제2항부터 제5항까지의 규정에도 불구하고 법무부장관, 지방교정청장 또는 소장은 제1항에 따른 비용이 납부되기 전에 정보공개 여부의 결정을 할 수 있다.', 7127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12303, '⑧ 제1항에 따른 비용의 세부적인 납부방법 및 반환방법 등에 관하여 필요한 사항은 법무부장관이 정한다.', 7127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12304, '① 법 제126조의2제1항 본문에 따라 통보하는 수용이력에는 다음 각 호의 사항이 포함되어야 한다.', 7131);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12305, '② 법 제126조의2제1항 본문에 따라 통보하는 사회복귀에 관한 의견에는 다음 각 호의 사항이 포함되어야 한다.', 7131);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12306, '③ 법 제126조의2제1항 본문에 따른 통보를 위한 수용이력 통보서와 사회복귀에 관한 의견 통보서의 서식은 법무부령으로 정한다.', 7131);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12307, '④ 법 제126조의2제1항 본문에 따라 석방될 수형자의 수용이력 또는 사회복귀에 관한 의견을 그의 거주지를 관할하는 경찰관서에 통보하는 경우에는 「형사사법절차 전자화 촉진법」 제2조제4호에 따른 형사사법정보시스템을 통해 통보할 수 있다.', 7131);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12308, null, 7134);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12309, '① 의무관은 수용자가 질병으로 사망한 경우에는 사망장에 그 병명ㆍ병력(病歷)ㆍ사인 및 사망일시를 기록하고 서명하여야 한다.', 7138);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12310, '② 소장은 수용자가 자살이나 그 밖에 변사한 경우에는 그 사실을 검사에게 통보하고, 기소된 상태인 경우에는 법원에도 통보하여야 하며 검시가 끝난 후에는 검시자ㆍ참여자의 신분ㆍ성명과 검시 결과를 사망장에 기록하여야 한다.', 7138);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12311, '③ 소장은 법 제128조에 따라 시신을 인도, 화장(火葬), 임시 매장, 집단 매장 또는 자연장(自然葬)을 한 경우에는 그 사실을 사망장에 기록하여야 한다. <개정 2015.12.10>', 7138);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12312, '① 소장은 시신을 임시 매장하거나 봉안한 경우에는 그 장소에 사망자의 성명을 적은 표지를 비치하고, 별도의 장부에 가족관계 등록기준지, 성명, 사망일시를 기록하여 관리하여야 한다. <개정 2015.12.10>', 7140);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12313, '② 소장은 시신 또는 유골을 집단 매장한 경우에는 집단 매장된 사람의 가족관계 등록기준지, 성명, 사망일시를 집단 매장부에 기록하고 그 장소에 묘비를 세워야 한다. <개정 2015.12.10>', 7140);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12314, '① 소장은 법 제130조에 따라 교정위원을 두는 경우 수용자의 개선을 촉구하고 안정된 수용생활을 하게 하기 위하여 교정위원에게 수용자를 교화상담하게 할 수 있다.', 7141);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12315, '② 교정위원은 수용자의 고충 해소 및 교정ㆍ교화를 위하여 필요한 의견을 소장에게 건의할 수 있다.', 7141);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12316, '③ 교정위원의 임기, 위촉 및 해촉, 지켜야 할 사항 등에 관하여 필요한 사항은 법무부장관이 정한다. <개정 2020.8.5>', 7141);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12317, '① 소장은 법 제131조의 기부금품을 접수하는 경우에는 기부한 기관ㆍ단체 또는 개인(이하 이 장에서 "기부자"라 한다)에게 영수증을 발급하여야 한다. 다만, 익명으로 기부하거나 기부자를 알 수 없는 경우에는 그러하지 아니하다.', 7143);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12318, '② 소장은 기부자가 용도를 지정하여 금품을 기부한 경우에는 기부금품을 그 용도에 사용하여야 한다. 다만, 지정한 용도로 사용하기 어려운 특별한 사유가 있는 경우에는 기부자의 동의를 받아 다른 용도로 사용할 수 있다.', 7143);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12319, '③ 교정시설의 기부금품 접수ㆍ사용 등에 관하여 필요한 사항은 법무부장관이 정한다.', 7143);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12320, null, 7145);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12321, '① 수용자의 범죄횟수는 징역 또는 금고 이상의 형을 선고받아 확정된 횟수로 한다. 다만, 집행유예의 선고를 받은 사람이 유예기간 중 고의로 범한 죄로 금고 이상의 실형이 확정되지 아니하고 그 기간이 지난 경우에는 집행이 유예된 형은 범죄횟수에 포함하지 아니한다. <개정 2014.11.17>', 7146);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12322, '② 형의 집행을 종료하거나 그 집행이 면제된 날부터 다음 각 호의 기간이 지난 경우에는 범죄횟수에 포함하지 아니한다. 다만, 그 기간 중 자격정지 이상의 형을 선고받아 확정된 경우는 제외한다. <개정 2013.4.16, 2014.11.17>', 7146);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12323, '③ 수용기록부 등 수용자의 범죄횟수를 기록하는 문서에는 필요한 경우 수용횟수(징역 또는 금고 이상의 형을 선고받고 그 집행을 위하여 교정시설에 수용된 횟수를 말한다)를 함께 기록하여 해당 수용자의 처우에 참고할 수 있도록 한다.', 7146);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12324, '① 수용자 의류의 품목은 평상복ㆍ특수복ㆍ보조복ㆍ의복부속물ㆍ모자 및 신발로 한다.', 7147);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12325, '② 제1항에 따른 품목별 구분은 다음 각 호와 같다. <개정 2013.4.16, 2014.11.17>', 7147);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12326, null, 7148);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12327, null, 7150);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12328, '① 수용자에게 지급하는 의류 및 침구는 1명당 1매로 하되, 작업 여부 또는 난방 여건을 고려하여 2매를 지급할 수 있다. <개정 2013.4.16>', 7151);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12329, '② 의류ㆍ침구 외에 수용자에게 지급하는 생활용품의 품목, 지급수량, 사용기간, 지급횟수 등에 대한 기준은 별표 1과 같다.', 7151);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12330, '③ 생활용품 지급일 이후에 수용된 수용자에 대하여는 다음 지급일까지 쓸 적절한 양을 지급하여야 한다.', 7151);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12331, '④ 신입수용자에게는 수용되는 날에 칫솔, 치약 및 수건 등 수용생활에 필요한 최소한의 생활용품을 지급하여야 한다.', 7151);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12332, '① 수용자에게 지급하는 주식은 1명당 1일 390 그램을 기준으로 한다. <개정 2013.4.16, 2014.11.17>', 7154);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12333, '② 소장은 수용자의 나이, 건강, 작업 여부 및 작업의 종류 등을 고려하여 필요한 경우에는 제1항의 지급 기준량을 변경할 수 있다.', 7154);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12334, '③ 소장은 수용자의 기호 등을 고려하여 주식으로 빵이나 국수 등을 지급할 수 있다. <개정 2014.11.17>', 7154);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12335, '① 부식은 주식과 함께 지급하며, 1명당 1일의 영양섭취기준량은 별표 2와 같다.', 7156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12336, '② 소장은 작업의 장려나 적절한 처우를 위하여 필요하다고 인정하는 경우 특별한 부식을 지급할 수 있다.', 7156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12337, '① 주ㆍ부식의 지급횟수는 1일 3회로 한다.', 7157);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12338, '② 수용자에게 지급하는 음식물의 총열량은 1명당 1일 2천500 킬로칼로리를 기준으로 한다.', 7157);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12339, '① 영 제29조에 따른 특식은 예산의 범위에서 지급한다. <개정 2014.11.17>', 7158);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12340, '② 소장은 작업시간을 3시간 이상 연장하는 경우에는 수용자에게 주ㆍ부식 또는 대용식 1회분을 간식으로 지급할 수 있다.', 7158);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12341, '① 자비구매물품의 종류는 다음 각 호와 같다.', 7159);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12342, '② 제1항 각 호에 해당하는 자비구매물품의 품목ㆍ유형 및 규격 등은 영 제31조에 어긋나지 아니하는 범위에서 소장이 정하되, 수용생활에 필요한 정도, 가격과 품질, 다른 교정시설과의 균형, 공급하기 쉬운 정도 및 수용자의 선호도 등을 고려하여야 한다.', 7159);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12343, '③ 법무부장관은 자비구매물품 공급의 교정시설 간 균형 및 교정시설의 안전과 질서유지를 위하여 공급물품의 품목 및 규격 등에 대한 통일된 기준을 제시할 수 있다.', 7159);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12344, '① 소장은 수용자가 자비구매물품의 구매를 신청하는 경우에는 법무부장관이 교정성적 또는 제74조에 따른 경비처우급을 고려하여 정하는 보관금의 사용한도, 교정시설의 보관범위 및 수용자가 지닐 수 있는 범위에서 허가한다. <개정 2013.4.16, 2020.8.5>', 7160);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12345, '② 소장은 감염병(「감염병의 예방 및 관리에 관한 법률」에 따른 감염병을 말한다)의 유행 또는 수용자의 징벌집행 등으로 자비구매물품의 사용이 중지된 경우에는 구매신청을 제한할 수 있다. <개정 2014.11.17>', 7160);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12346, '① 소장은 물품공급업무 담당공무원을 검수관(檢收官)으로 지정하여 제21조에 따라 지정받은 자비구매물품 공급자로부터 납품받은 제품의 수량ㆍ상태 및 소비기한 등을 검사하도록 해야 한다. <개정 2024.2.8>', 7162);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12347, '② 검수관은 공급제품이 부패, 파손, 규격미달, 그 밖의 사유로 수용자에게 공급하기에 부적당하다고 인정하는 경우에는 소장에게 이를 보고하고 필요한 조치를 하여야 한다.', 7162);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12348, '① 소장은 수용자에게 자비구매물품의 품목ㆍ가격, 그 밖에 구매에 관한 주요사항을 미리 알려주어야 한다.', 7163);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12349, '② 소장은 제품의 변질, 파손, 그 밖의 정당한 사유로 수용자가 교환, 반품 또는 수선을 원하는 경우에는 신속히 적절한 조치를 하여야 한다. <개정 2013.4.16>', 7163);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12350, '① 법무부장관은 자비구매물품의 품목ㆍ규격ㆍ가격 등의 교정시설 간 균형을 유지하고 공급과정의 효율성ㆍ공정성을 높이기 위하여 그 공급업무를 담당하는 법인 또는 개인을 지정할 수 있다.', 7164);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12351, '② 제1항에 따라 지정받은 법인 또는 개인은 그 업무를 처리하는 경우 교정시설의 안전과 질서유지를 위하여 선량한 관리자로서의 의무를 다하여야 한다.', 7164);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12352, '③ 자비구매물품 공급업무의 담당자 지정 등에 관한 세부사항은 법무부장관이 정한다.', 7164);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12353, '① 소장은 수용자 외의 사람이 수용자에게 금원(金員)을 건네줄 것을 신청하는 경우에는 현금ㆍ수표 및 우편환의 범위에서 허가한다. 다만, 수용자 외의 사람이 온라인으로 수용자의 예금계좌에 입금한 경우에는 금원을 건네줄 것을 허가한 것으로 본다. <개정 2020.8.5>', 7165);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12354, '② 소장은 수용자 외의 사람이 수용자에게 음식물을 건네줄 것을 신청하는 경우에는 법무부장관이 정하는 바에 따라 교정시설 안에서 판매되는 음식물 중에서 허가한다. 다만, 제30조 각 호에 해당하는 종교행사 및 제114조 각 호에 해당하는 교화프로그램의 시행을 위하여 특히 필요하다고 인정하는 경우에는 교정시설 안에서 판매되는 음식물이 아니더라도 건네줄 것을 허가할 수 있다. <개정 2020.8.5>', 7165);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12355, '③ 소장은 수용자 외의 사람이 수용자에게 음식물 외의 물품을 건네줄 것을 신청하는 경우에는 다음 각 호의 어느 하나에 해당하지 아니하면 법무부장관이 정하는 교정시설의 보관범위 및 수용자가 지닐 수 있는 범위에서 허가한다. <개정 2020.8.5>', 7165);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12356, '① 교정시설에는「의료법」 제3조에 따른 의료기관 중 의원(醫院)이 갖추어야 하는 시설 수준 이상의 의료시설(진료실 등의 의료용 건축물을 말한다. 이하 같다)을 갖추어야 한다.', 7166);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12357, '② 교정시설에 갖추어야 하는 의료장비(혈압측정기 등의 의료기기를 말한다)의 기준은 별표 3과 같다.', 7166);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12358, '③ 의료시설의 세부종류 및 설치기준은 법무부장관이 정한다.', 7166);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12359, '① 소장은 수용정원과 시설여건 등을 고려하여 적정한 양의 비상의료용품을 갖추어 둔다.', 7167);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12360, '② 교정시설에 갖추어야 하는 비상의료용품의 기준은 별표 4와 같다.', 7167);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12361, '① 소장은 전화통화(발신하는 것만을 말한다. 이하 같다)를 신청한 수용자에 대하여 다음 각 호의 어느 하나에 해당하는 사유가 없으면 전화통화를 허가할 수 있다. 다만, 미결수용자에게 전화통화를 허가할 경우 그 허용횟수는 월 2회 이내로 한다. <개정 2020.8.5, 2024.2.8>', 7168);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12362, '② 소장은 제1항에 따른 허가를 하기 전에 전화번호와 수신자(수용자와 통화할 상대방을 말한다. 이하 같다)를 확인하여야 한다. 이 경우 수신자에게 제1항 각 호에 해당하는 사유가 있으면 제1항의 허가를 아니할 수 있다.', 7168);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12363, '③ 전화통화의 통화시간은 특별한 사정이 없으면 5분 이내로 한다. <개정 2024.2.8>', 7168);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12364, '① 수용자의 전화통화는 매일(공휴일 및 법무부장관이 정한 날은 제외한다) 「국가공무원 복무규정」 제9조에 따른 근무시간 내에서 실시한다.', 7169);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12365, '② 소장은 제1항에도 불구하고 평일에 전화를 이용하기 곤란한 특별한 사유가 있는 수용자에 대해서는 전화이용시간을 따로 정할 수 있다.', 7169);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12366, null, 7170);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12367, '① 소장은 제25조제1항 각 호의 어느 하나에 해당하지 아니한다고 명백히 인정되는 경우가 아니면 통화내용을 청취하거나 녹음한다.', 7171);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12368, '② 제1항의 녹음기록물은 「공공기록물 관리에 관한 법률」에 따라 관리하고, 특히 녹음기록물이 손상되지 아니하도록 유의해서 보존하여야 한다.', 7171);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12369, '③ 소장은 제1항의 녹음기록물에 대한 보호ㆍ관리를 위해 전화통화정보 취급자를 지정해야 하고, 전화통화정보 취급자는 직무상 알게 된 전화통화정보를 누설 또는 권한 없이 처리하거나 다른 사람이 이용하도록 제공하는 등 부당한 목적으로 사용해서는 안 된다. <개정 2024.2.8>', 7171);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12370, '④ 제1항의 녹음기록물을 관계기관에 제공하는 경우에는 영 제62조제4항 및 제5항을 준용한다. <개정 2024.2.8>', 7171);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12371, '① 수용자의 전화통화 요금은 수용자가 부담한다.', 7172);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12372, '② 소장은 교정성적이 양호한 수형자 또는 보관금이 없는 수용자 등에 대하여는 제1항에도 불구하고 예산의 범위에서 요금을 부담할 수 있다. <개정 2013.4.16, 2020.8.5>', 7172);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12373, '① 영 제59조의2제1항 각 호의 변호사가 수용자를 접견하고자 하는 경우에는 별지 제32호서식의 신청서를 소장에게 제출해야 한다. 다만, 영 제59조의2제1항제1호의 변호사는 소송위임장 사본 등 소송사건의 대리인임을 소명할 수 있는 자료를 첨부해야 한다. <개정 2024.2.8>', 7174);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12374, '② 영 제59조의2제1항 각 호의 변호사가 같은 조 제3항에 따라 접견 시간을 연장하거나 접견 횟수를 추가하고자 하는 경우에는 별지 제33호서식의 신청서에 해당 사유를 소명할 수 있는 자료를 첨부하여 소장에게 제출해야 한다. <개정 2024.2.8>', 7174);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12375, null, 7175);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12376, '① 소장은 교정시설의 안전과 질서를 해치지 아니하는 범위에서 종교단체 또는 종교인이 주재하는 종교행사를 실시한다.', 7176);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12377, '② 소장은 종교행사를 위하여 각 종교별 성상ㆍ성물ㆍ성화ㆍ성구가 구비된 종교상담실ㆍ교리교육실 등을 설치할 수 있으며, 특정 종교행사를 위하여 임시행사장을 설치하는 경우에는 성상 등을 임시로 둘 수 있다.', 7176);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12378, null, 7177);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12379, '① 소장은 수용자의 신앙생활에 필요하다고 인정하는 경우에는 외부에서 제작된 휴대용 종교도서 및 성물을 수용자가 지니게 할 수 있다. <개정 2020.8.5>', 7179);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12380, '② 소장이 수용자에게 제1항의 종교도서 및 성물을 지니는 것을 허가하는 경우에는 그 재질ㆍ수량ㆍ규격ㆍ형태 등을 고려해야 하며, 다른 수용자의 수용생활을 방해하지 않도록 해야 한다. <개정 2020.8.5>', 7179);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12381, '① 소장은 신문등을 구독하는 수용자가 다음 각 호의 어느 하나에 해당하는 사유가 있으면 구독의 허가를 취소할 수 있다. <개정 2020.8.5>', 7181);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12382, '② 소장은 소유자가 분명하지 아니한 도서를 회수하여 비치도서로 전환하거나 폐기할 수 있다.', 7181);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12383, '① 수용자를 대상으로 하는 방송은 무상으로 한다.', 7182);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12384, '② 법무부장관은 방송의 전문성을 강화하기 위하여 외부전문가의 협력을 구할 수 있고, 모든 교정시설의 수용자를 대상으로 통합방송을 할 수 있다.', 7182);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12385, '③ 소장은 방송에 대한 의견수렴을 위하여 설문조사 등의 방법으로 수용자의 반응도 및 만족도를 측정할 수 있다.', 7182);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12386, '① 소장은 방송을 위하여 텔레비전, 라디오, 스피커 등의 장비와 방송선로 등의 시설을 갖추어야 한다. <개정 2019.10.22>', 7183);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12387, '② 소장은 물품관리법령에 따라 제1항의 장비와 시설을 정상적으로 유지ㆍ관리하여야 한다.', 7183);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12388, '① 소장은 「방송법」 제2조의 텔레비전방송 또는 라디오방송을 녹음ㆍ녹화하여 방송하거나 생방송할 수 있으며, 비디오테이프에 의한 영상물 또는 자체 제작한 영상물을 방송할 수 있다.', 7185);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12389, '② 방송프로그램은 그 내용에 따라 다음 각 호와 같이 구분한다.', 7185);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12390, '③ 소장은 방송프로그램을 자체 편성하는 경우에는 다음 각 호의 어느 하나에 해당하는 내용이 포함되지 아니하도록 특히 유의하여야 한다.', 7185);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12391, '① 수용자는 소장이 지정한 장소에서 지정된 채널을 통하여 텔레비전을 시청하거나 라디오를 청취하여야 한다. 다만, 제86조에 따른 자치생활 수형자는 법무부장관이 정하는 방법에 따라 텔레비전을 시청할 수 있다. <개정 2013.4.16>', 7186);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12392, '② 수용자는 방송설비 또는 채널을 임의 조작ㆍ변경하거나 임의수신 장비를 지녀서는 안 된다. <개정 2020.8.5>', 7186);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12393, '③ 수용자가 방송시설과 장비를 손상하거나 그 밖의 방법으로 그 효용을 해친 경우에는 배상을 하여야 한다.', 7186);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12394, '① 법 제57조제6항에 따라 법무부장관이 노인수형자의 처우를 전담하도록 정하는 시설(이하 "노인수형자 전담교정시설"이라 한다)에는 「장애인ㆍ노인ㆍ임산부 등의 편의증진보장에 관한 법률 시행령」 별표 2의 교도소ㆍ구치소 편의시설의 종류 및 설치기준에 따른 편의시설을 갖추어야 한다. <개정 2015.12.10>', 7188);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12395, '② 노인수형자 전담교정시설에는 별도의 공동휴게실을 마련하고 노인이 선호하는 오락용품 등을 갖춰두어야 한다.', 7188);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12396, '① 노인수형자 전담교정시설이 아닌 교정시설에서는 노인수용자를 수용하기 위하여 별도의 거실을 지정하여 운용할 수 있다.', 7189);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12397, '② 노인수용자의 거실은 시설부족 또는 그 밖의 부득이한 사정이 없으면 건물의 1층에 설치하고, 특히 겨울철 난방을 위하여 필요한 시설을 갖추어야 한다.', 7189);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12398, '① 소장은 노인수용자의 나이ㆍ건강상태 등을 고려하여 필요하다고 인정하면 영 제49조에 따른 운동시간을 연장하거나 영 제50조에 따른 목욕횟수를 늘릴 수 있다.', 7191);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12399, '② 소장은 노인수용자가 거동이 불편하여 혼자서 목욕하기 어려운 경우에는 교도관, 자원봉사자 또는 다른 수용자로 하여금 목욕을 보조하게 할 수 있다.', 7191);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12400, '① 노인수형자 전담교정시설의 장은 노인성 질환에 관한 전문적인 지식을 가진 의료진과 장비를 갖추고, 외부의료시설과 협력체계를 강화하여 노인수형자가 신속하고 적절한 치료를 받을 수 있도록 노력하여야 한다.', 7192);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12401, '② 소장은 노인수용자에 대하여 6개월에 1회 이상 건강검진을 하여야 한다.', 7192);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12402, '① 노인수형자 전담교정시설의 장은 노인문제에 관한 지식과 경험이 풍부한 외부전문가를 초빙하여 교육하게 하는 등 노인수형자의 교육 받을 기회를 확대하고, 노인전문오락, 그 밖에 노인의 특성에 알맞은 교화프로그램을 개발ㆍ시행하여야 한다.', 7193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12403, '② 소장은 노인수용자가 작업을 원하는 경우에는 나이ㆍ건강상태 등을 고려하여 해당 수용자가 감당할 수 있는 정도의 작업을 부과한다. 이 경우 의무관의 의견을 들어야 한다.', 7193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12404, '① 법 제57조제6항에 따라 법무부장관이 장애인수형자의 처우를 전담하도록 정하는 시설(이하 "장애인수형자 전담교정시설"이라 한다)의 장은 장애종류별 특성에 알맞은 재활치료프로그램을 개발하여 시행하여야 한다. <개정 2015.12.10>', 7195);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12405, '② 장애인수형자 전담교정시설 편의시설의 종류 및 설치기준에 관하여는 제43조제1항을 준용한다.', 7195);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12406, '① 장애인수형자 전담교정시설이 아닌 교정시설에서는 장애인수용자를 수용하기 위하여 별도의 거실을 지정하여 운용할 수 있다.', 7196);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12407, '② 장애인수용자의 거실은 시설부족 또는 그 밖의 부득이한 사정이 없으면 건물의 1층에 설치하고, 특히 장애인이 이용할 수 있는 변기 등의 시설을 갖추도록 하여야 한다.', 7196);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12408, '① 외국인수용자를 수용하는 소장은 외국어에 능통한 소속 교도관을 전담요원으로 지정하여 일상적인 개별면담, 고충해소, 통역ㆍ번역 및 외교공관 또는 영사관 등 관계기관과의 연락 등의 업무를 수행하게 하여야 한다.', 7201);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12409, '② 제1항의 전담요원은 외국인 미결수용자에게 소송 진행에 필요한 법률지식을 제공하는 등의 조력을 하여야 한다.', 7201);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12410, '① 소장은 외국인수용자의 수용거실을 지정하는 경우에는 종교 또는 생활관습이 다르거나 민족감정 등으로 인하여 분쟁의 소지가 있는 외국인수용자는 거실을 분리하여 수용하여야 한다. <개정 2013.4.16>', 7202);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12411, '② 소장은 외국인수용자에 대하여는 그 생활양식을 고려하여 필요한 수용설비를 제공하도록 노력하여야 한다.', 7202);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12412, '① 외국인수용자에게 지급하는 음식물의 총열량은 제14조제2항에도 불구하고 소속 국가의 음식문화, 체격 등을 고려하여 조정할 수 있다.', 7203);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12413, '② 외국인수용자에 대하여는 쌀, 빵 또는 그 밖의 식품을 주식으로 지급하되, 소속 국가의 음식문화를 고려하여야 한다. <개정 2014.11.17>', 7203);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12414, '③ 외국인수용자에게 지급하는 부식의 지급기준은 법무부장관이 정한다.', 7203);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12415, '① 법 제57조제6항에 따라 법무부장관이 19세 미만의 수형자(이하 "소년수형자"라 한다)의 처우를 전담하도록 정하는 시설(이하 "소년수형자 전담교정시설"이라 한다)의 장은 소년의 나이ㆍ적성 등 특성에 알맞은 교육ㆍ교화프로그램을 개발하여 시행하여야 한다.', 7205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12416, '② 소년수형자 전담교정시설에는 별도의 공동학습공간을 마련하고 학용품 및 소년의 정서 함양에 필요한 도서, 잡지 등을 갖춰 두어야 한다.', 7205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12417, '① 소년수형자 전담교정시설이 아닌 교정시설에서는 소년수용자(영 제81조제4항에 따른 소년수용자를 말한다. 이하 같다)를 수용하기 위하여 별도의 거실을 지정하여 운용할 수 있다.', 7206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12418, '② 소년수형자 전담교정시설이 아닌 교정시설에서 소년수용자를 수용한 경우 교육ㆍ교화프로그램에 관하여는 제59조의2제1항을 준용한다.', 7206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12419, '① 소장은 해당 교정시설의 특성 등을 고려하여 필요한 경우에는 다른 교정시설로부터 이송되어 온 수형자의 개별처우계획(법 제56조제1항에 따른 개별처우계획을 말한다. 이하 같다)을 변경할 수 있다.', 7211);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12420, '② 소장은 형집행정지 중에 있는 사람이 기간만료 또는 그 밖의 정지사유가 없어져 재수용된 경우에는 석방 당시와 동일한 처우등급을 부여할 수 있다. <개정 2010.5.31, 2020.8.5>', 7211);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12421, '③ 소장은 형집행정지 중에 있는 사람이 「자유형등에 관한 검찰집행사무규칙」 제33조제2항에 따른 형집행정지의 취소로 재수용된 경우에는 석방 당시보다 한 단계 낮은 처우등급(제74조의 경비처우급에만 해당한다)을 부여할 수 있다. <신설 2024.2.8>', 7211);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12422, '④ 소장은 가석방의 취소로 재수용되어 남은 형기가 집행되는 경우에는 석방 당시보다 한 단계 낮은 처우등급(제74조의 경비처우급에만 해당한다)을 부여한다. 다만, 「가석방자관리규정」 제5조 단서를 위반하여 가석방이 취소되는 등 가석방 취소사유에 특히 고려할 만한 사정이 있는 때에는 석방 당시와 동일한 처우등급을 부여할 수 있다. <개정 2010.5.31, 2022.2.7, 2024.2.8>', 7211);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12423, '⑤ 소장은 형집행정지 중이거나 가석방기간 중에 있는 사람이 형사사건으로 재수용되어 형이 확정된 경우에는 개별처우계획을 새로 수립하여야 한다. <개정 2024.2.8>', 7211);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12424, '① 소장은 「국제수형자이송법」에 따라 외국으로부터 이송되어 온 수형자에 대하여는 개별처우계획을 새로 수립하여 시행한다. 이 경우 해당 국가의 교정기관으로부터 접수된 그 수형자의 수형생활 또는 처우 등에 관한 내용을 고려할 수 있다.', 7212);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12425, '② 소장은 군사법원에서 징역형 또는 금고형이 확정되거나 그 형의 집행 중에 있는 사람이 이송되어 온 경우에는 개별처우계획을 새로 수립하여 시행한다. 이 경우 해당 군교도소로부터 접수된 그 수형자의 수형생활 또는 처우 등에 관한 내용을 고려할 수 있다.', 7212);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12426, '① 다음 각 호의 사람에 대해서는 분류심사를 하지 아니한다. <개정 2013.4.16>', 7213);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12427, '② 소장은 수형자가 다음 각 호의 어느 하나에 해당하는 사유가 있으면 분류심사를 유예한다.', 7213);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12428, '③ 소장은 제2항 각 호에 해당하는 사유가 소멸한 경우에는 지체 없이 분류심사를 하여야 한다. 다만, 집행할 형기가 사유 소멸일부터 3개월 미만인 경우에는 분류심사를 하지 아니한다. <개정 2013.4.16>', 7213);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12429, null, 7214);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12430, null, 7216);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12431, '① 정기재심사는 다음 각 호의 어느 하나에 해당하는 경우에 한다. 다만, 형집행지휘서가 접수된 날부터 6개월이 지나지 아니한 경우에는 그러하지 아니하다.', 7217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12432, '② 부정기형의 재심사 시기는 단기형을 기준으로 한다.', 7217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12433, '③ 무기형과 20년을 초과하는 징역형ㆍ금고형의 재심사 시기를 산정하는 경우에는 그 형기를 20년으로 본다.', 7217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12434, '④ 2개 이상의 징역형 또는 금고형을 집행하는 수형자의 재심사 시기를 산정하는 경우에는 그 형기를 합산한다. 다만, 합산한 형기가 20년을 초과하는 경우에는 그 형기를 20년으로 본다.', 7217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12435, null, 7218);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12436, '① 소장은 재심사를 할 때에는 그 사유가 발생한 달의 다음 달까지 완료하여야 한다.', 7219);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12437, '② 재심사에 따라 제74조의 경비처우급을 조정할 필요가 있는 경우에는 한 단계의 범위에서 조정한다. 다만, 수용 및 처우를 위하여 특히 필요한 경우에는 두 단계의 범위에서 조정할 수 있다. <개정 2010.5.31>', 7219);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12438, '① 신입심사를 할 때에는 다음 각 호의 사항을 조사한다. <개정 2014.11.17>', 7220);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12439, '② 재심사를 할 때에는 제1항 각 호의 사항 중 변동된 사항과 다음 각 호의 사항을 조사한다. <개정 2014.11.17>', 7220);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12440, null, 7221);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12441, '① 소장은 분류심사를 위하여 수형자의 인성, 지능, 적성 등의 특성을 측정ㆍ진단하기 위한 검사를 할 수 있다.', 7222);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12442, '② 인성검사는 신입심사 대상자 및 그 밖에 처우상 필요한 수형자를 대상으로 한다. 다만, 수형자가 다음 각 호의 어느 하나에 해당하면 인성검사를 하지 아니할 수 있다.', 7222);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12443, '③ 이해력의 현저한 부족 등으로 인하여 인성검사를 하지 아니한 경우에는 상담 내용과 관련 서류를 토대로 인성을 판정하여 경비처우급 분류지표를 결정할 수 있다. <개정 2010.5.31>', 7222);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12444, '④ 지능 및 적성 검사는 제2항 각 호의 어느 하나에 해당하지 아니하는 신입심사 대상자로서 집행할 형기가 형집행지휘서 접수일부터 1년 이상이고 나이가 35세 이하인 경우에 한다. 다만, 직업훈련 또는 그 밖의 처우를 위하여 특히 필요한 경우에는 예외로 할 수 있다.', 7222);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12445, null, 7223);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12446, null, 7224);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12447, '① 경비처우급은 다음 각 호와 같이 구분한다.', 7225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12448, '② 경비처우급에 따른 작업기준은 다음 각 호와 같다. <개정 2013.4.16>', 7225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12449, null, 7227);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12450, null, 7228);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12451, '① 소장은 수형자(제62조에 따라 분류심사에서 제외되거나 유예되는 사람은 제외한다)의 소득점수를 별지 제1호서식의 소득점수 평가 및 통지서에 따라 매월 평가하여야 한다. 이 경우 대상기간은 매월 초일부터 말일까지로 한다. <개정 2013.4.16>', 7229);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12452, '② 수형자의 소득점수 평가 방법은 다음 각 호로 구분한다.', 7229);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12453, '③ 제2항에 따라 수형자의 작업 또는 교육 성적을 평가하는 경우에는 작업 숙련도, 기술력, 작업기간, 교육태도, 시험성적 등을 고려할 수 있다.', 7229);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12454, '④ 보안ㆍ작업 담당교도관 및 수용관리팀(교정시설의 효율적인 운영과 수용자의 적정한 관리 및 처우를 위하여 수용동별 또는 작업장별로 나누어진 교정시설 안의 일정한 구역을 관리하는 단위조직을 말한다. 이하 같다)의 팀장은 서로 협의하여 소득점수 평가 및 통지서에 해당 수형자에 대한 매월 초일부터 말일까지의 소득점수를 채점한다. <개정 2013.4.16, 2024.2.8>', 7229);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12455, '① 수형생활 태도 점수와 작업 또는 교육성적 점수는 제78조제2항의 방법에 따라 채점하되, 수는 소속 작업장 또는 교육장 전체 인원의 10퍼센트를 초과할 수 없고, 우는 30퍼센트를 초과할 수 없다. 다만, 작업장 또는 교육장 전체인원이 4명 이하인 경우에는 수ㆍ우를 각각 1명으로 채점할 수 있다.', 7230);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12456, '② 소장이 작업장 중 작업의 특성이나 난이도 등을 고려하여 필수 작업장으로 지정하는 경우 소득점수의 수는 5퍼센트 이내, 우는 10퍼센트 이내의 범위에서 각각 확대할 수 있다.', 7230);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12457, '③ 소장은 수형자가 부상이나 질병, 그 밖의 부득이한 사유로 작업 또는 교육을 받지 못한 경우에는 3점 이내의 범위에서 작업 또는 교육 성적을 부여할 수 있다.', 7230);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12458, '① 소장은 제66조 및 제67조에 따라 재심사를 하는 경우에는 그 때마다 제78조에 따라 평가한 수형자의 소득점수를 평정하여 경비처우급을 조정할 것인지를 고려하여야 한다. 다만, 부정기재심사의 소득점수 평정대상기간은 사유가 발생한 달까지로 한다. <개정 2010.5.31>', 7231);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12459, '② 제1항에 따라 소득점수를 평정하는 경우에는 평정 대상기간 동안 매월 평가된 소득점수를 합산하여 평정 대상기간의 개월 수로 나누어 얻은 점수(이하 "평정소득점수"라 한다)로 한다.', 7231);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12460, null, 7232);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12461, '① 조정된 처우등급에 따른 처우는 그 조정이 확정된 다음 날부터 한다. 이 경우 조정된 처우등급은 그 달 초일부터 적용된 것으로 본다. <개정 2010.5.31>', 7233);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12462, '② 소장은 수형자의 경비처우급을 조정한 경우에는 지체 없이 해당 수형자에게 그 사항을 알려야 한다. <개정 2010.5.31>', 7233);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12463, '① 소장은 수형자를 기본수용급별ㆍ경비처우급별로 구분하여 수용하여야 한다. 다만 처우상 특히 필요하거나 시설의 여건상 부득이한 경우에는 기본수용급ㆍ경비처우급이 다른 수형자를 함께 수용하여 처우할 수 있다. <개정 2010.5.31>', 7234);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12464, '② 소장은 제1항에 따라 수형자를 수용하는 경우 개별처우의 효과를 증진하기 위하여 경비처우급ㆍ개별처우급이 같은 수형자 집단으로 수용하여 처우할 수 있다. <개정 2010.5.31>', 7234);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12465, '① 소장은 수형자의 경비처우급에 따라 물품에 차이를 두어 지급할 수 있다. 다만, 주ㆍ부식, 음료, 그 밖에 건강유지에 필요한 물품은 그러하지 아니하다. <개정 2010.5.31>', 7235);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12466, '② 제1항에 따라 의류를 지급하는 경우 수형자가 개방처우급인 경우에는 색상, 디자인 등을 다르게 할 수 있다. <개정 2010.5.31>', 7235);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12467, '① 소장은 개방처우급ㆍ완화경비처우급ㆍ일반경비처우급 수형자로서 교정성적, 나이, 인성 등을 고려하여 다른 수형자의 모범이 된다고 인정되는 경우에는 봉사원으로 선정하여 담당교도관의 사무처리와 그 밖의 업무를 보조하게 할 수 있다. <개정 2010.5.31>', 7236);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12468, '② 소장은 봉사원의 활동기간을 1년 이하로 정하되, 필요한 경우에는 그 기간을 연장할 수 있다. <개정 2010.5.31, 2014.11.17>', 7236);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12469, '③ 소장은 봉사원의 활동과 역할 수행이 부적당하다고 인정하는 경우에는 그 선정을 취소할 수 있다.', 7236);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12470, '④ 제1항부터 제3항까지에서 규정한 사항 외에 봉사원 선정, 기간연장 및 선정취소 등에 필요한 사항은 법무부장관이 정한다. <개정 2024.2.8>', 7236);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12471, '① 소장은 개방처우급ㆍ완화경비처우급 수형자에게 자치생활을 허가할 수 있다. <개정 2010.5.31>', 7237);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12472, '② 수형자 자치생활의 범위는 인원점검, 취미활동, 일정한 구역 안에서의 생활 등으로 한다.', 7237);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12473, '③ 소장은 자치생활 수형자들이 교육실, 강당 등 적당한 장소에서 월 1회 이상 토론회를 할 수 있도록 하여야 한다.', 7237);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12474, '④ 소장은 자치생활 수형자가 법무부장관 또는 소장이 정하는 자치생활 중 지켜야 할 사항을 위반한 경우에는 자치생활 허가를 취소할 수 있다. <개정 2020.8.5>', 7237);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12475, '①수형자의 경비처우급별 접견의 허용횟수는 다음 각 호와 같다. <개정 2010.5.31, 2013.4.16>', 7238);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12476, '② 제1항제2호부터 제4호까지의 경우 접견은 1일 1회만 허용한다. 다만, 처우상 특히 필요한 경우에는 그러하지 아니하다. <신설 2013.4.16>', 7238);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12477, '③ 소장은 교화 및 처우상 특히 필요한 경우에는 수용자가 다른 교정시설의 수용자와 통신망을 이용하여 화상으로 접견하는 것(이하 "화상접견"이라 한다)을 허가할 수 있다. 이 경우 화상접견은 제1항의 접견 허용횟수에 포함한다. <신설 2013.4.16>', 7238);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12478, '① 소장은 개방처우급ㆍ완화경비처우급 수형자에 대하여 가족 만남의 날 행사에 참여하게 하거나 가족 만남의 집을 이용하게 할 수 있다. 이 경우 제87조의 접견 허용횟수에는 포함되지 아니한다. <개정 2010.5.31>', 7240);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12479, '② 제1항의 경우 소장은 가족이 없는 수형자에 대하여는 결연을 맺었거나 그 밖에 가족에 준하는 사람으로 하여금 그 가족을 대신하게 할 수 있다.', 7240);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12480, '③ 소장은 제1항에도 불구하고 교화를 위하여 특히 필요한 경우에는 일반경비처우급 수형자에 대하여도 가족 만남의 날 행사 참여 또는 가족 만남의 집 이용을 허가할 수 있다. <개정 2010.5.31>', 7240);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12481, '④ 제1항 및 제3항에서 "가족 만남의 날 행사"란 수형자와 그 가족이 교정시설의 일정한 장소에서 다과와 음식을 함께 나누면서 대화의 시간을 갖는 행사를 말하며, "가족 만남의 집"이란 수형자와 그 가족이 숙식을 함께 할 수 있도록 교정시설에 수용동과 별도로 설치된 일반주택 형태의 건축물을 말한다. <개정 2013.4.16>', 7240);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12482, '① 수형자의 경비처우급별 전화통화의 허용횟수는 다음 각 호와 같다. <개정 2010.5.31, 2014.11.17, 2024.2.8>', 7241);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12483, '② 소장은 제1항에도 불구하고 처우상 특히 필요한 경우에는 개방처우급ㆍ완화경비처우급ㆍ일반경비처우급 수형자의 전화통화 허용횟수를 늘릴 수 있다. <개정 2010.5.31, 2024.2.8>', 7241);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12484, '③ 제1항 각 호의 경우 전화통화는 1일 1회만 허용한다. 다만, 처우상 특히 필요한 경우에는 그러하지 아니하다. <신설 2013.4.16>', 7241);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12485, '① 소장은 개방처우급ㆍ완화경비처우급 또는 자치생활 수형자에 대하여 월 2회 이내에서 경기 또는 오락회를 개최하게 할 수 있다. 다만, 소년수형자에 대하여는 그 횟수를 늘릴 수 있다. <개정 2010.5.31>', 7242);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12486, '② 제1항에 따라 경기 또는 오락회가 개최되는 경우 소장은 해당 시설의 사정을 고려하여 참석인원, 방법 등을 정할 수 있다.', 7242);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12487, '③ 제1항에 따라 경기 또는 오락회가 개최되는 경우 소장은 관련 분야의 전문지식과 자격을 가지고 있는 외부강사를 초빙할 수 있다.', 7242);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12488, '① 소장은 개방처우급ㆍ완화경비처우급 수형자에 대하여 교정시설 밖에서 이루어지는 다음 각 호에 해당하는 활동을 허가할 수 있다. 다만, 처우상 특히 필요한 경우에는 일반경비처우급 수형자에게도 이를 허가할 수 있다. <개정 2010.5.31>', 7243);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12489, '② 제1항 각 호의 활동을 허가하는 경우 소장은 별도의 수형자 의류를 지정하여 입게 한다. 다만, 처우상 필요한 경우에는 자비구매의류를 입게 할 수 있다.', 7243);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12490, '③ 제1항제4호의 활동에 필요한 비용은 수형자가 부담한다. 다만, 처우상 필요한 경우에는 예산의 범위에서 그 비용을 지원할 수 있다.', 7243);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12491, '① 소장은 개방처우급 혹은 완화경비처우급 수형자가 다음 각 호의 사유에 모두 해당하는 경우에는 교정시설에 설치된 개방시설에 수용하여 사회 적응에 필요한 교육, 취업지원 등 적정한 처우를 할 수 있다. <개정 2024.2.8>', 7244);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12492, '② 소장은 제1항에 따른 처우의 대상자 중 다음 각 호의 사유에 모두 해당하는 수형자에 대해서는 지역사회에 설치된 개방시설에 수용하여 제1항에 따른 처우를 할 수 있다. <개정 2024.2.8>', 7244);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12493, '③ 제1항 및 제2항에 따른 중간처우 대상자의 선발절차, 교정시설 또는 지역사회에 설치하는 개방시설의 종류 및 기준, 그 밖에 필요한 사항은 법무부장관이 정한다. <개정 2024.2.8>', 7244);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12494, '① 소장은 수형자가 개방처우급 또는 완화경비처우급으로서 작업기술이 탁월하고 작업성적이 우수한 경우에는 수형자 자신을 위한 개인작업을 하게 할 수 있다. 이 경우 개인작업 시간은 교도작업에 지장을 주지 아니하는 범위에서 1일 2시간 이내로 한다. <개정 2010.5.31>', 7246);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12495, '② 소장은 제1항에 따라 개인작업을 하는 수형자에게 개인작업 용구를 사용하게 할 수 있다. 이 경우 작업용구는 특정한 용기에 보관하도록 하여야 한다.', 7246);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12496, '③ 제1항의 개인작업에 필요한 작업재료 등의 구입비용은 수형자가 부담한다. 다만, 처우상 필요한 경우에는 예산의 범위에서 그 비용을 지원할 수 있다.', 7246);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12497, '① 소장은 수형자가 개방처우급 또는 완화경비처우급으로서 직업능력 향상을 위하여 특히 필요한 경우에는 교정시설 외부의 공공기관 또는 기업체 등에서 운영하는 직업훈련을 받게 할 수 있다. <개정 2010.5.31>', 7247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12498, '② 제1항에 따른 직업훈련의 비용은 수형자가 부담한다. 다만, 처우상 특히 필요한 경우에는 예산의 범위에서 그 비용을 지원할 수 있다.', 7247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12499, '① 법 제61조 및 영 제86조에 따른 분류심사를 전담하는 교정시설(이하 이 절에서 "분류전담시설"이라 한다)의 장은 범죄의 피해가 중대하고 재범의 위험성이 높은 수형자(이하 이 절에서 "고위험군 수형자"라 한다)의 개별처우계획을 수립ㆍ조정하기 위해 고위험군 수형자의 개별적 특성과 재범의 위험성 등을 면밀히 분석ㆍ평가하기 위한 분류심사(이하 이 절에서 "정밀분류심사"라 한다)를 실시할 수 있다.', 7248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12500, '② 분류전담시설의 장은 정밀분류심사를 실시한 고위험군 수형자의 개별처우계획 이행 여부를 지속적으로 평가해야 한다.', 7248);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12501, null, 7249);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12502, '① 위원장은 위원회를 소집하고 위원회의 사무를 총괄한다.', 7250);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12503, '② 위원장이 부득이한 사유로 그 직무를 수행할 수 없을 때에는 위원장이 미리 지정한 위원이 그 직무를 대행할 수 있다.', 7250);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12504, '① 위원회의 회의는 매월 10일에 개최한다. 다만, 위원회의 회의를 개최하는 날이 토요일, 공휴일, 그 밖에 법무부장관이 정한 휴무일일 때에는 그 다음 날에 개최한다.', 7251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12505, '② 위원장은 수형자의 처우와 관련하여 필요한 경우에는 임시회의를 개최할 수 있다. <개정 2019.8.29>', 7251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12506, '③ 위원회의 회의는 재적위원 3분의 2이상의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.', 7251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12507, '① 위원회의 사무를 처리하기 위하여 분류심사 업무를 담당하는 교도관 중에서 간사 1명을 둔다.', 7252);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12508, '② 간사는 위원회의 회의록을 작성하여 유지하여야 한다.', 7252);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12509, '① 소장은 교육대상자를 소속기관(소장이 관할하고 있는 교정시설을 말한다. 이하 같다)에서 선발하여 교육한다. 다만, 소속기관에서 교육대상자를 선발하기 어려운 경우에는 다른 기관에서 추천한 사람을 모집하여 교육할 수 있다.', 7254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12510, '② 소장은 교육대상자의 성적불량, 학업태만 등으로 인하여 교육의 목적을 달성하기 어려운 경우에는 그 선발을 취소할 수 있다.', 7254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12511, '③ 소장은 교육대상자 및 시험응시 희망자의 학습능력을 평가하기 위하여 자체 평가시험을 실시할 수 있다.', 7254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12512, '④ 소장은 교육의 효과를 거두지 못하였다고 인정하는 교육대상자에 대하여 다시 교육을 할 수 있다.', 7254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12513, '⑤ 소장은 기관의 교육전문인력, 교육시설, 교육대상인원 등의 사정을 고려하여 단계별 교육과 자격취득 목표를 설정할 수 있으며, 자격취득ㆍ대회입상 등을 하면 처우에 반영할 수 있다.', 7254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12514, '① 교육대상자는 교육의 시행에 관한 관계법령, 학칙 및 교육관리지침을 성실히 지켜야 한다. <개정 2020.8.5>', 7255);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12515, '② 제110조부터 제113조까지의 규정에 따른 교육을 실시하는 경우 소요되는 비용은 특별한 사정이 없으면 교육대상자의 부담으로 한다.', 7255);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12516, '', 7255);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12517, '① 소장은 각 교육과정의 선정 요건과 수형자의 나이, 학력, 교정성적, 자체 평가시험 성적, 정신자세, 성실성, 교육계획과 시설의 규모, 교육대상인원 등을 고려하여 교육대상자를 선발하거나 추천하여야 한다.', 7256);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12518, '② 소장은 정당한 이유 없이 교육을 기피한 사실이 있거나 자퇴(제적을 포함한다)한 사실이 있는 수형자는 교육대상자로 선발하거나 추천하지 아니할 수 있다.', 7256);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12519, '① 학과교육대상자의 과정수료 단위는 학년으로 하되, 학기의 구분은 국공립학교의 학기에 준한다. 다만, 독학에 의한 교육은 수업 일수의 제한을 받지 아니한다.', 7257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12520, '② 소장은 교육을 위하여 필요한 경우에는 외부강사를 초빙할 수 있으며, 카세트 또는 재생전용기기의 사용을 허용할 수 있다.', 7257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12521, '③ 소장은 교육의 실효성을 확보하기 위하여 교육실을 설치ㆍ관리하여야 하며, 교육목적을 위하여 필요한 경우 신체장애를 보완하는 교육용 물품의 사용을 허가하거나 예산의 범위에서 학용품과 응시료를 지원할 수 있다.', 7257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12522, '① 소장은 교육대상자가 다음 각 호의 어느 하나에 해당하는 경우에는 교육대상자 선발을 취소할 수 있다. <개정 2017.8.22>', 7258);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12523, '② 교육과정의 변경은 교육대상자의 선발로 보아 제103조를 준용한다.', 7258);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12524, '③ 소장은 교육대상자에게 질병, 부상, 그 밖의 부득이한 사정이 있는 경우에는 교육과정을 일시 중지할 수 있다.', 7258);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12525, '① 소장은 특별한 사유가 없으면 교육기간 동안에 교육대상자를 다른 기관으로 이송할 수 없다.', 7259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12526, '② 교육대상자의 선발이 취소되거나 교육대상자가 교육을 수료하였을 때에는 선발 당시 소속기관으로 이송한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 소속기관으로 이송하지 아니하거나 다른 기관으로 이송할 수 있다.', 7259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12527, '① 교육대상자에게는 작업ㆍ직업훈련 등을 면제한다.', 7260);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12528, '② 작업ㆍ직업훈련 수형자 등도 독학으로 검정고시ㆍ학사고시 등에 응시하게 할 수 있다. 이 경우 자체 평가시험 성적 등을 고려해야 한다. <개정 2019.10.22>', 7260);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12529, '① 소장은 매년 초 다음 각 호의 시험을 준비하는 수형자를 대상으로 검정고시반을 설치ㆍ운영할 수 있다. <개정 2016.6.28>', 7261);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12530, '② 소장은 교육기간 중에 검정고시에 합격한 교육대상자에 대하여는 해당 교육과정을 조기 수료시키거나 상위 교육과정에 임시 편성시킬 수 있다.', 7261);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12531, '③ 소장은 고등학교 졸업 또는 이와 동등한 수준 이상의 학력이 인정되는 수형자를 대상으로 대학입학시험 준비반을 편성ㆍ운영할 수 있다.', 7261);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12532, '① 소장은 수형자에게 고등학교 과정의 교육기회를 부여하기 위하여 「초ㆍ중등교육법」 제51조에 따른 방송통신고등학교 교육과정을 설치ㆍ운영할 수 있다.', 7262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12533, '② 소장은 중학교 졸업 또는 이와 동등한 수준 이상의 학력이 인정되는 수형자가 제1항의 방송통신고등학교 교육과정을 지원하여 합격한 경우에는 교육대상자로 선발할 수 있다.', 7262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12534, '③ 소장은 제1항의 방송통신고등학교 교육과정의 입학금, 수업료, 교과용 도서 구입비 등 교육에 필요한 비용을 예산의 범위에서 지원할 수 있다.', 7262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12535, '① 소장은 수형자에게 학위취득 기회를 부여하기 위하여 독학에 의한 학사학위 취득과정(이하 "학사고시반 교육"이라 한다)을 설치ㆍ운영할 수 있다.', 7263);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12536, '② 소장은 다음 각 호의 요건을 갖춘 수형자가 제1항의 학사고시반 교육을 신청하는 경우에는 교육대상자로 선발할 수 있다. <개정 2013.4.16>', 7263);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12537, '① 소장은 대학 과정의 교육기회를 부여하기 위하여 「고등교육법」 제2조에 따른 방송통신대학 교육과정을 설치ㆍ운영할 수 있다.', 7264);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12538, '② 소장은 제110조제2항 각 호의 요건을 갖춘 개방처우급ㆍ완화경비처우급ㆍ일반경비처우급 수형자가 제1항의 방송통신대학 교육과정에 지원하여 합격한 경우에는 교육대상자로 선발할 수 있다. <개정 2010.5.31>', 7264);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12539, '① 소장은 전문대학과정의 교육기회를 부여하기 위하여 「고등교육법」 제2조에 따른 전문대학 위탁교육과정을 설치ㆍ운영할 수 있다.', 7265);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12540, '② 소장은 제110조제2항 각 호의 요건을 갖춘 개방처우급ㆍ완화경비처우급ㆍ일반경비처우급 수형자가 제1항의 전문대학 위탁교육과정에 지원하여 합격한 경우에는 교육대상자로 선발할 수 있다. <개정 2010.5.31>', 7265);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12541, '③ 제1항의 전문대학 위탁교육과정의 교과과정, 시험응시 및 학위취득에 관한 세부사항은 위탁자와 수탁자 간의 협약에 따른다.', 7265);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12542, '④ 소장은 제1항부터 제3항까지의 규정에 따른 교육을 위하여 필요한 경우 수형자를 중간처우를 위한 전담교정시설에 수용할 수 있다. <신설 2015.12.10>', 7265);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12543, '① 소장은 수형자에게 지식정보사회에 적응할 수 있는 교육기회를 부여하기 위하여 정보화 교육과정을 설치ㆍ운영할 수 있다.', 7266);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12544, '② 소장은 개방처우급ㆍ완화경비처우급ㆍ일반경비처우급 수형자에게 다문화 시대에 대처할 수 있는 교육기회를 부여하기 위하여 외국어 교육과정을 설치ㆍ운영할 수 있다. <개정 2010.5.31>', 7266);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12545, '③ 소장은 외국어 교육대상자가 교육실 외에서의 어학학습장비를 이용한 외국어학습을 원하는 경우에는 계호 수준, 독거 여부, 교육 정도 등에 대한 교도관회의(「교도관 직무규칙」 제21조에 따른 교도관회의를 말한다. 이하 같다)의 심의를 거쳐 허가할 수 있다.', 7266);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12546, '④ 소장은 이 규칙에서 정한 교육과정 외에도 법무부장관이 수형자로 하여금 건전한 사회복귀에 필요한 지식과 소양을 습득하게 하기 위하여 정하는 교육과정을 설치ㆍ운영할 수 있다.', 7266);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12547, null, 7267);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12548, '① 소장은 수형자와 그 가족의 관계를 유지ㆍ회복하기 위하여 수형자의 가족이 참여하는 각종 프로그램을 운영할 수 있다. 다만, 가족이 없는 수형자의 경우 교화를 위하여 필요하면 결연을 맺었거나 그 밖에 가족에 준하는 사람의 참여를 허가할 수 있다.', 7270);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12549, '② 제1항의 경우 대상 수형자는 교도관회의의 심의를 거쳐 선발하고, 참여인원은 5명 이내의 가족으로 한다. 다만, 특히 필요하다고 인정하는 경우에는 참여인원을 늘릴 수 있다. <개정 2017.8.22>', 7270);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12550, '① 소장은 수형자의 건전한 가치관 형성, 정서안정, 고충해소 등을 위하여 교화상담을 실시할 수 있다.', 7271);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12551, '② 소장은 제1항의 교화상담을 위하여 교도관이나 제33조의 교정참여인사를 교화상담자로 지정할 수 있으며, 수형자의 안정을 위하여 결연을 주선할 수 있다.', 7271);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12552, '① 소장은 교화프로그램을 운영하는 경우 약물중독ㆍ정신질환ㆍ신체장애ㆍ건강ㆍ성별ㆍ나이 등 수형자의 개별 특성을 고려하여야 하며, 프로그램의 성격 및 시설 규모와 인원을 고려하여 이송 등의 적절한 조치를 할 수 있다.', 7272);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12553, '② 소장은 교화프로그램을 운영하기 위하여 수형자의 정서적인 안정이 보장될 수 있는 장소를 따로 정하거나 방송설비 및 방송기기를 이용할 수 있다.', 7272);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12554, '③ 소장은 교정정보시스템(교정시설에서 통합적으로 정보를 관리하는 시스템을 말한다)에 교화프로그램의 주요 진행내용을 기록하여 수형자 처우에 활용하여야 하며, 상담내용 등 개인정보가 유출되지 아니하도록 하여야 한다.', 7272);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12555, '④ 교화프로그램 운영에 관하여는 제101조부터 제107조까지의 규정을 준용한다.', 7272);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12556, '① 법무부장관은 교화프로그램의 효과를 높이기 위해 소속 공무원 중에서 법 제64조제2항에 따른 전문인력을 선발 및 양성할 수 있다.', 7273);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12557, '② 제1항에 따른 전문인력 선발 및 양성의 요건, 방법, 그 밖에 필요한 사항은 법무부장관이 정한다.', 7273);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12558, '① 외부기업체에 통근하며 작업하는 수형자는 다음 각 호의 요건을 갖춘 수형자 중에서 선정한다. <개정 2010.5.31, 2013.4.16, 2014.11.17, 2020.8.5>', 7274);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12559, '② 교정시설 안에 설치된 외부기업체의 작업장에 통근하며 작업하는 수형자는 제1항제1호부터 제4호까지의 요건(같은 항 제3호의 요건의 경우에는 일반경비처우급에 해당하는 수형자도 포함한다)을 갖춘 수형자로서 집행할 형기가 10년 미만이거나 형기기산일부터 10년 이상이 지난 수형자 중에서 선정한다. <신설 2013.4.16, 2014.11.17>', 7274);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12560, '③ 소장은 제1항 및 제2항에도 불구하고 작업 부과 또는 교화를 위하여 특히 필요하다고 인정하는 경우에는 제1항 및 제2항의 수형자 외의 수형자에 대하여도 외부통근자로 선정할 수 있다. <개정 2013.4.16>', 7274);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12561, '① 직업훈련 직종 선정 및 훈련과정별 인원은 법무부장관의 승인을 받아 소장이 정한다.', 7278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12562, '② 직업훈련 대상자는 소속기관의 수형자 중에서 소장이 선정한다. 다만, 집체직업훈련(직업훈련 전담 교정시설이나 그 밖에 직업훈련을 실시하기에 적합한 교정시설에 수용하여 실시하는 훈련을 말한다) 대상자는 집체직업훈련을 실시하는 교정시설의 관할 지방교정청장이 선정한다. <개정 2010.5.31, 2013.4.16>', 7278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12563, '①소장은 수형자가 다음 각 호의 요건을 갖춘 경우에는 수형자의 의사, 적성, 나이, 학력 등을 고려하여 직업훈련 대상자로 선정할 수 있다. <개정 2013.4.16>', 7279);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12564, '② 소장은 소년수형자의 선도(善導)를 위하여 필요한 경우에는 제1항의 요건을 갖추지 못한 경우에도 직업훈련 대상자로 선정하여 교육할 수 있다. <신설 2013.4.16>', 7279);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12565, null, 7280);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12566, '① 법무부장관은 직업훈련을 위하여 필요한 경우에는 수형자를 다른 교정시설로 이송할 수 있다.', 7281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12567, '② 소장은 제1항에 따라 이송된 수형자나 직업훈련 중인 수형자를 다른 교정시설로 이송해서는 아니 된다. 다만, 훈련취소 등 특별한 사유가 있는 경우에는 그러하지 아니하다.', 7281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12568, '① 소장은 직업훈련 대상자가 다음 각 호의 어느 하나에 해당하는 경우에는 직업훈련을 보류할 수 있다.', 7282);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12569, '② 소장은 제1항에 따라 직업훈련이 보류된 수형자가 그 사유가 소멸되면 본래의 과정에 복귀시켜 훈련하여야 한다. 다만, 본래 과정으로 복귀하는 것이 부적당하다고 인정하는 경우에는 해당 훈련을 취소할 수 있다.', 7282);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12570, '① 소장은 법 제77조에 따른 귀휴를 허가하는 경우에는 제131조의 귀휴심사위원회의 심사를 거쳐야 한다.', 7283);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12571, '② 소장은 개방처우급ㆍ완화경비처우급 수형자에게 법 제77조제1항에 따른 귀휴를 허가할 수 있다. 다만, 교화 또는 사회복귀 준비 등을 위하여 특히 필요한 경우에는 일반경비처우급 수형자에게도 이를 허가할 수 있다. <개정 2010.5.31>', 7283);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12572, '③ 법 제77조제1항제4호에 해당하는 귀휴사유는 다음 각 호와 같다. <개정 2013.4.16, 2014.11.17>', 7283);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12573, '① 법 제77조제1항의 형기를 계산할 때 부정기형은 단기를 기준으로 하고, 2개 이상의 징역 또는 금고의 형을 선고받은 수형자의 경우에는 그 형기를 합산한다. <개정 2014.11.17>', 7284);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12574, '② 법 제77조제1항의 "1년 중 20일 이내의 귀휴" 중 "1년"이란 매년 1월 1일부터 12월 31일까지를 말한다.', 7284);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12575, '① 법 제77조에 따른 수형자의 귀휴허가에 관한 심사를 하기 위하여 교정시설에 귀휴심사위원회(이하 이 절에서 "위원회"라 한다)를 둔다.', 7285);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12576, '② 위원회는 위원장을 포함한 6명 이상 8명 이하의 위원으로 구성한다.', 7285);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12577, '③ 위원장은 소장이 되며, 위원은 소장이 소속기관의 부소장ㆍ과장(지소의 경우에는 7급 이상의 교도관) 및 교정에 관한 학식과 경험이 풍부한 외부인사 중에서 임명 또는 위촉한다. 이 경우 외부위원은 2명 이상으로 한다.', 7285);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12578, '① 위원장은 위원회를 소집하고 위원회의 업무를 총괄한다.', 7286);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12579, '② 위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 부소장인 위원이 그 직무를 대행하고, 부소장이 없거나 부소장인 위원이 사고가 있는 경우에는 위원장이 미리 지정한 위원이 그 직무를 대행한다.', 7286);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12580, '① 위원회의 회의는 위원장이 수형자에게 법 제77조제1항 및 제2항에 따른 귀휴사유가 발생하여 귀휴심사가 필요하다고 인정하는 때에 개최한다.', 7287);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12581, '② 위원회의 회의는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.', 7287);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12582, '① 소장은 토요일, 공휴일, 그 밖에 위원회의 소집이 매우 곤란한 때에 법 제77조제2항제1호의 사유가 발생한 경우에는 제129조제1항에도 불구하고 위원회의 심사를 거치지 아니하고 귀휴를 허가할 수 있다. 다만, 이 경우 다음 각 호에 해당하는 부서의 장의 의견을 들어야 한다.', 7288);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12583, '② 제1항 각 호에 해당하는 부서의 장은 제137조제3항의 서류를 검토하여 그 의견을 지체 없이 소장에게 보고하여야 한다.', 7288);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12584, null, 7289);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12585, '① 외부위원의 임기는 2년으로 하며, 연임할 수 있다.', 7290);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12586, '② 소장은 외부위원이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 위원을 해촉할 수 있다. <개정 2016.6.28>', 7290);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12587, '③ 외부위원에게는 예산의 범위에서 수당과 여비를 지급할 수 있다.', 7290);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12588, '① 위원회의 사무를 처리하기 위하여 귀휴업무를 담당하는 교도관 중에서 간사 1명을 둔다.', 7291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12589, '② 간사는 위원장의 명을 받아 위원회의 사무를 처리한다.', 7291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12590, '③ 간사는 다음 각 호의 서류를 위원회에 제출하여야 한다.', 7291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12591, '④ 간사는 별지 제3호서식에 따른 위원회 회의록을 작성하여 유지하여야 한다.', 7291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12592, '① 소장은 수형자의 귀휴심사에 필요한 경우에는 법 제60조제1항에 따라 사실조회를 할 수 있다.', 7292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12593, '② 소장은 심사대상자의 보호관계 등을 알아보기 위하여 필요하다고 인정하는 경우에는 그의 가족 또는 보호관계에 있는 사람에게 위원회 회의의 참석을 요청할 수 있다.', 7292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12594, null, 7294);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12595, '① 소장은 수형자에게 귀휴를 허가한 경우 필요하다고 인정하면 교도관을 동행시킬 수 있다.', 7295);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12596, '② 소장은 귀휴자의 가족 또는 보호관계에 있는 사람으로부터 별지 제6호서식의 보호서약서를 제출받아야 한다. <개정 2013.4.16>', 7295);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12597, '③ 영 제97조제1항에 따라 경찰관서의 장에게 귀휴사실을 통보하는 경우에는 별지 제7호서식에 따른다.', 7295);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12598, '① 귀휴자의 여비와 귀휴 중 착용할 복장은 본인이 부담한다.', 7296);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12599, '② 소장은 귀휴자가 신청할 경우 작업장려금의 전부 또는 일부를 귀휴비용으로 사용하게 할 수 있다.', 7296);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12600, null, 7298);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12601, '① 협의회는 회장 1명을 포함하여 3명 이상 5명 이하의 내부위원과 10명 이상의 외부위원으로 구성한다. <개정 2010.5.31>', 7299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12602, '② 협의회의 회장은 소장이 되고, 부회장은 2명을 두되 1명은 소장이 내부위원 중에서 지명하고 1명은 외부위원 중에서 호선(互選)한다.', 7299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12603, '③ 내부위원은 소장이 지명하는 소속기관의 부소장ㆍ과장(지소의 경우에는 7급 이상의 교도관)으로 구성한다.', 7299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12604, '④ 회장ㆍ부회장 외에 협의회 운영을 위하여 기관실정에 적합한 수의 임원을 둘 수 있다.', 7299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12605, '① 법무부장관은 협의회의 외부위원을 다음 각 호의 사람 중에서 소장의 추천을 받아 위촉한다. <개정 2010.5.31, 2013.4.16, 2014.11.17, 2024.2.8>', 7300);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12606, '② 외부위원의 임기는 3년으로 하며, 연임할 수 있다.', 7300);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12607, '③ 법무부장관은 외부위원이 다음 각 호의 어느 하나에 해당하는 경우에는 소장의 건의를 받아 해당 위원을 해촉할 수 있다. <개정 2016.6.28>', 7300);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12608, '① 회장은 협의회를 소집하고 협의회 업무를 총괄한다.', 7301);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12609, '② 회장이 부득이한 사유로 직무를 수행할 수 없을 때에는 소장이 지정한 부회장이 그 직무를 대행한다.', 7301);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12610, '① 협의회의 회의는 반기마다 개최한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 임시회의를 개최할 수 있다. <개정 2010.5.31, 2013.4.16>', 7302);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12611, '② 협의회의 회의는 회장이 소집하고 그 의장이 된다.', 7302);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12612, '③ 협의회의 회의는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.', 7302);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12613, '① 협의회의 사무를 처리하기 위하여 수형자 취업알선 및 창업지원 업무를 전담하는 직원 중에서 간사 1명을 둔다.', 7303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12614, '② 간사는 별지 제8호서식에 따른 협의회의 회의록을 작성하여 유지하여야 한다.', 7303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12615, '① 사형확정자는 사형집행시설이 설치되어 있는 교정시설에 수용하되, 다음 각 호와 같이 구분하여 수용한다. 다만, 수용관리 또는 처우상 필요한 경우에는 사형집행시설이 설치되지 않은 교정시설에 수용할 수 있다. <개정 2024.2.8>', 7304);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12616, '② 사형확정자의 심리적 안정 도모 또는 교정시설의 안전과 질서유지를 위하여 특히 필요하다고 인정하는 경우에는 제1항 각 호에도 불구하고 교도소에 수용할 사형확정자를 구치소에 수용할 수 있고, 구치소에 수용할 사형확정자를 교도소에 수용할 수 있다.', 7304);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12617, '③ 사형확정자와 소년수용자를 같은 교정시설에 수용하는 경우에는 서로 분리하여 수용한다. <신설 2024.2.8>', 7304);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12618, '④ 소장은 사형확정자의 자살ㆍ도주 등의 사고를 방지하기 위하여 필요한 경우에는 사형확정자와 미결수용자를 혼거수용할 수 있고, 사형확정자의 교육ㆍ교화프로그램, 작업 등의 적절한 처우를 위하여 필요한 경우에는 사형확정자와 수형자를 혼거수용할 수 있다. <개정 2024.2.8>', 7304);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12619, '⑤ 사형확정자의 번호표 및 거실표의 색상은 붉은색으로 한다. <개정 2024.2.8>', 7304);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12620, '① 소장은 사형확정자의 심리적 안정 및 원만한 수용생활을 위하여 소속 교도관으로 하여금 지속적인 상담을 하게 하여야 한다.', 7306);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12621, '② 제1항의 사형확정자에 대한 상담시기, 상담책임자 지정, 상담결과 처리절차 등에 관하여는 제196조를 준용한다.', 7306);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12622, '① 소장은 사형확정자가 작업을 신청하면 교도관회의의 심의를 거쳐 교정시설 안에서 실시하는 작업을 부과할 수 있다. 이 경우 부과하는 작업은 심리적 안정과 원만한 수용생활을 도모하는 데 적합한 것이어야 한다.', 7307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12623, '② 소장은 작업이 부과된 사형확정자에 대하여 교도관회의의 심의를 거쳐 제150조제5항을 적용하지 아니할 수 있다. <개정 2024.2.8>', 7307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12624, '③ 소장은 작업이 부과된 사형확정자가 작업의 취소를 요청하면 사형확정자의 의사(意思)ㆍ건강, 담당교도관의 의견 등을 고려하여 작업을 취소할 수 있다.', 7307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12625, '④ 사형확정자에게 작업을 부과하는 경우에는 법 제71조부터 제76조까지의 규정 및 이 규칙 제200조를 준용한다.', 7307);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12626, null, 7311);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12627, '① 소장은 교정장비의 보관 및 관리를 위하여 관리책임자와 보조자를 지정한다.', 7312);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12628, '② 제1항의 관리책임자와 보조자는 교정장비가 적정한 상태로 보관ㆍ관리될 수 있도록 수시로 점검하는 등 필요한 조치를 하여야 한다.', 7312);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12629, '③ 특정 장소에 고정식으로 설치되는 장비 외의 교정장비는 별도의 장소에 보관ㆍ관리하여야 한다.', 7312);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12630, null, 7314);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12631, '① 소장은 전자장비의 효율적인 운용을 위하여 각종 전자장비를 통합적으로 관리할 수 있는 시스템이 설치된 중앙통제실을 설치하여 운영한다.', 7315);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12632, '② 소장은 중앙통제실에 대한 외부인의 출입을 제한하여야 한다. 다만, 시찰, 참관, 그 밖에 소장이 특별히 허가한 경우에는 그러하지 아니하다.', 7315);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12633, '③ 전자장비의 통합관리시스템, 중앙통제실의 운영ㆍ관리 등에 관하여 필요한 사항은 법무부장관이 정한다.', 7315);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12634, '① 영상정보처리기기 카메라는 교정시설의 주벽(周壁)ㆍ감시대ㆍ울타리ㆍ운동장ㆍ거실ㆍ작업장ㆍ접견실ㆍ전화실ㆍ조사실ㆍ진료실ㆍ복도ㆍ중문, 그 밖에 법 제94조제1항에 따라 전자장비를 이용하여 계호하여야 할 필요가 있는 장소에 설치한다. <개정 2013.4.16>', 7316);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12635, '② 영상정보처리기기 모니터는 중앙통제실, 수용관리팀의 사무실, 그 밖에 교도관이 계호하기에 적정한 장소에 설치한다. <개정 2024.2.8>', 7316);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12636, '③ 거실에 영상정보처리기기 카메라를 설치하는 경우에는 용변을 보는 하반신의 모습이 촬영되지 아니하도록 카메라의 각도를 한정하거나 화장실 차폐시설을 설치하여야 한다.', 7316);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12637, '① 교도관이 법 제94조제1항에 따라 거실에 있는 수용자를 계호하는 경우에는 별지 제9호서식의 거실수용자 영상계호부에 피계호자의 인적사항 및 주요 계호내용을 개별적으로 기록하여야 한다. 다만, 중경비시설의 거실에 있는 수용자를 전자장비를 이용하여 계호하는 경우에는 중앙통제실 등에 비치된 현황표에 피계호인원 등 전체 현황만을 기록할 수 있다. <개정 2010.5.31>', 7317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12638, '② 교도관이 법 제94조제1항에 따라 계호하는 과정에서 수용자의 처우 및 관리에 특히 참고할만한 사항을 알게 된 경우에는 그 요지를 수용기록부에 기록하여 소장에게 지체 없이 보고하여야 한다.', 7317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12639, '① 고정식 물품검색기는 정문, 수용동 입구, 작업장 입구, 그 밖에 수용자 또는 교정시설을 출입하는 수용자 외의 사람에 대한 신체ㆍ의류ㆍ휴대품의 검사가 필요한 장소에 설치한다. <개정 2013.4.16>', 7320);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12640, '② 교도관이 법 제93조제1항에 따라 수용자의 신체ㆍ의류ㆍ휴대품을 검사하는 경우에는 특별한 사정이 없으면 고정식 물품검색기를 통과하게 한 후 휴대식 금속탐지기 또는 손으로 이를 확인한다.', 7320);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12641, '③ 교도관이 법 제93조제3항에 따라 교정시설을 출입하는 수용자 외의 사람의 의류와 휴대품을 검사하는 경우에는 고정식 물품검색기를 통과하게 하거나 휴대식 금속탐지기로 이를 확인한다.', 7320);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12642, null, 7323);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12643, '① 보호장비의 규격은 별표 5와 같다.', 7324);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12644, '② 교도관은 제1항에 따른 보호장비 규격에 맞지 아니한 보호장비를 수용자에게 사용해서는 아니 된다.', 7324);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12645, '① 수갑의 사용방법은 다음 각 호와 같다.', 7326);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12646, '② 제1항제1호에 따라 수갑을 사용하는 경우에는 수갑보호기를 함께 사용할 수 있다.', 7326);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12647, '③ 제1항제2호에 따라 별표 7의 방법으로 수갑을 사용하여 그 목적을 달성한 후에는 즉시 별표 6의 방법으로 전환하거나 사용을 중지하여야 한다.', 7326);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12648, '④ 수갑은 구체적 상황에 적합한 종류를 선택하여 사용할 수 있다. 다만, 일회용수갑은 일시적으로 사용하여야 하며, 사용목적을 달성한 후에는 즉시 사용을 중단하거나 다른 보호장비로 교체하여야 한다. <개정 2013.4.16>', 7326);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12649, null, 7328);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12650, null, 7329);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12651, '① 보호의자는 별표 14의 방법으로 사용하며, 다른 보호장비로는 법 제97조제1항제2호부터 제4호까지의 규정의 어느 하나에 해당하는 행위를 방지하기 어려운 특별한 사정이 있는 경우에만 사용하여야 한다.', 7330);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12652, '② 보호의자는 제184조제2항에 따라 그 사용을 일시 중지하거나 완화하는 경우를 포함하여 8시간을 초과하여 사용할 수 없으며, 사용 중지 후 4시간이 경과하지 아니하면 다시 사용할 수 없다. <개정 2013.4.16>', 7330);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12653, '① 보호침대는 별표 15의 방법으로 사용하며, 다른 보호장비로는 자살ㆍ자해를 방지하기 어려운 특별한 사정이 있는 경우에만 사용하여야 한다.', 7331);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12654, '② 보호침대의 사용에 관하여는 제176조제2항을 준용한다.', 7331);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12655, '① 보호복은 별표 16의 방법으로 사용한다.', 7332);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12656, '② 보호복의 사용에 관하여는 제176조제2항을 준용한다.', 7332);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12657, '① 포승의 사용방법은 다음 각 호와 같다. <개정 2018.5.2, 2020.8.5>', 7333);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12658, '② 제1항제2호에 따라 포승을 사용하여 2명 이상의 수용자를 호송하는 경우에는 수용자 간에 포승을 다음 각 호의 구분에 따른 방법으로 연결하여 사용할 수 있다. <개정 2019.10.22, 2020.8.5, 2024.2.8>', 7333);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12659, '③ 삭제 <2018.5.2>', 7333);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12660, null, 7334);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12661, '① 소장은 보호장비를 착용 중인 수용자에 대하여 별지 제10호 서식의 보호장비 사용 심사부 및 별지 제11호 서식의 보호장비 착용자 관찰부 등의 기록과 관계직원의 의견 등을 토대로 보호장비의 계속사용 여부를 매일 심사하여야 한다.', 7337);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12662, '② 소장은 영 제121조에 따라 의무관 또는 의료관계 직원으로부터 보호장비의 사용 중지 의견을 보고받았음에도 불구하고 해당 수용자에 대하여 보호장비를 계속하여 사용할 필요가 있는 경우에는 의무관 또는 의료관계 직원에게 건강유지에 필요한 조치를 취할 것을 명하고 보호장비를 사용할 수 있다. 이 경우 소장은 별지 제10호서식의 보호장비 사용 심사부에 보호장비를 계속 사용할 필요가 있다고 판단하는 근거를 기록하여야 한다.', 7337);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12663, '① 교도관은 법 제97조제1항 각 호에 따른 보호장비 사용 사유가 소멸한 경우에는 소장의 허가를 받아 지체 없이 보호장비 사용을 중단하여야 한다. 다만, 소장의 허가를 받을 시간적 여유가 없을 때에는 보호장비 사용을 중단한 후 지체 없이 소장의 승인을 받아야 한다. <개정 2013.4.16>', 7338);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12664, '② 교도관은 보호장비 착용 수용자의 목욕, 식사, 용변, 치료 등을 위하여 필요한 경우에는 보호장비 사용을 일시 중지하거나 완화할 수 있다. <개정 2013.4.16>', 7338);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12665, null, 7340);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12666, '① 교도관이 수용자에 대하여 사용할 수 있는 보안장비의 종류별 사용요건은 다음 각 호와 같다. <개정 2014.11.17>', 7341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12667, '② 교도관이 수용자 외의 사람에 대하여 사용할 수 있는 보안장비의 종류별 사용요건은 다음 각 호와 같다. <개정 2014.11.17>', 7341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12668, '③ 제186조제7호에 해당하는 보안장비의 사용은 법무부장관이 정하는 바에 따른다.', 7341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12669, null, 7342);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12670, null, 7343);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12671, '① 교도관이 수용자에 대하여 사용할 수 있는 무기의 종류별 사용요건은 다음 각 호와 같다. <개정 2014.11.17>', 7344);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12672, '② 교도관이 수용자 외의 사람에 대하여 사용할 수 있는 무기의 종류별 사용요건은 다음 각 호와 같다. <개정 2014.11.17>', 7344);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12673, '③ 제189조제4호에 해당하는 무기의 사용은 법무부장관이 정하는 바에 따른다.', 7344);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12674, '① 소장은 소속 교도관에 대하여 연 1회 이상 총기의 조작ㆍ정비ㆍ사용에 관한 교육을 한다.', 7347);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12675, '② 제1항의 교육을 받지 아니하였거나 총기 조작이 미숙한 사람, 그 밖에 총기휴대가 부적당하다고 인정되는 사람에 대하여는 총기휴대를 금지하고 별지 제12호서식의 총기휴대 금지자 명부에 그 명단을 기록한 후 총기를 지급할 때마다 대조ㆍ확인하여야 한다.', 7347);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12676, '③ 제2항의 총기휴대 금지자에 대하여 금지사유가 소멸한 경우에는 그 사유를 제2항에 따른 총기휴대 금지자 명부에 기록하고 총기휴대금지를 해제하여야 한다.', 7347);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12677, null, 7348);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12678, '① 엄중관리대상자의 번호표 및 거실표의 색상은 다음 각 호와 같이 구분한다.', 7349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12679, '② 제194조의 엄중관리대상자 구분이 중복되는 수용자의 경우 그 번호표 및 거실표의 색상은 제1항 각 호의 순서에 따른다.', 7349);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12680, '① 소장은 엄중관리대상자 중 지속적인 상담이 필요하다고 인정되는 사람에 대하여는 상담책임자를 지정한다.', 7350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12681, '② 제1항의 상담책임자는 감독교도관 또는 상담 관련 전문교육을 이수한 교도관을 우선하여 지정하여야 하며, 상담대상자는 상담책임자 1명당 10명 이내로 하여야 한다. <개정 2013.4.16>', 7350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12682, '③ 상담책임자는 해당 엄중관리대상자에 대하여 수시로 개별상담을 함으로써 신속한 고충처리와 원만한 수용생활 지도를 위하여 노력하여야 한다. <개정 2013.4.16>', 7350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12683, '④ 제3항에 따라 상담책임자가 상담을 하였을 때에는 그 요지와 처리결과 등을 제119조제3항에 따른 교정정보시스템에 입력하여야 한다. 이 경우 엄중관리대상자의 처우를 위하여 필요하면 별지 제13호서식의 엄중관리대상자 상담결과 보고서를 작성하여 소장에게 보고하여야 한다. <개정 2013.4.16>', 7350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12684, null, 7352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12685, '① 소장은 제198조 각 호의 어느 하나에 해당하는 수용자에 대하여는 조직폭력수용자로 지정한다. 현재의 수용생활 중 집행되었거나 집행할 형이 제198조제1호 또는 제2호에 해당하는 경우에도 또한 같다. <개정 2014.11.17>', 7353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12686, '② 소장은 제1항에 따라 조직폭력수용자로 지정된 사람에 대하여는 석방할 때까지 지정을 해제할 수 없다. 다만, 공소장 변경 또는 재판 확정에 따라 지정사유가 해소되었다고 인정되는 경우에는 교도관회의의 심의 또는 분류처우위원회의 의결을 거쳐 지정을 해제한다. <개정 2014.11.17>', 7353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12687, null, 7358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12688, '① 소장은 제204조 각 호의 어느 하나에 해당하는 수용자에 대하여는 마약류수용자로 지정하여야 한다. 현재의 수용생활 중 집행되었거나 집행할 형이 제204조제1호에 해당하는 경우에도 또한 같다.', 7359);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12689, '② 소장은 제1항에 따라 마약류수용자로 지정된 사람에 대하여는 석방할 때까지 지정을 해제할 수 없다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 교도관회의의 심의 또는 분류처우위원회의 의결을 거쳐 지정을 해제할 수 있다. <개정 2014.11.17>', 7359);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12690, '① 마약류수용자에 대하여 다량 또는 장기간 복용할 경우 환각증세를 일으킬 수 있는 의약품을 투약할 때에는 특히 유의하여야 한다.', 7360);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12691, '② 소장은 교정시설에 마약류를 반입하는 것을 방지하기 위하여 필요하면 강제에 의하지 아니하는 범위에서 수용자의 소변을 채취하여 마약반응검사를 할 수 있다.', 7360);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12692, '③ 소장은 제2항의 검사 결과 양성반응이 나타난 수용자에 대하여는 관계기관에 혈청검사, 모발검사, 그 밖의 정밀검사를 의뢰하고 그 결과에 따라 적절한 조치를 하여야 한다.', 7360);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12693, null, 7361);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12694, '① 소장은 마약류수용자가 마약류 근절(根絶) 의지를 갖고 이를 실천할 수 있도록 해당 교정시설의 여건에 적합한 마약류수용자 재활교육계획을 수립하여 시행하여야 한다.', 7363);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12695, '② 소장은 마약류수용자의 마약류 근절 의지를 북돋울 수 있도록 마약 퇴치 전문강사, 성직자 등과 자매결연을 주선할 수 있다.', 7363);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12696, null, 7364);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12697, '① 소장은 제210조 각 호의 어느 하나에 해당하는 수용자에 대하여는 분류처우위원회의 의결을 거쳐 관심대상수용자로 지정한다. 다만, 미결수용자 등 분류처우위원회의 의결 대상자가 아닌 경우에도 관심대상수용자로 지정할 필요가 있다고 인정되는 수용자에 대하여는 교도관회의의 심의를 거쳐 관심대상수용자로 지정할 수 있다. <개정 2013.4.16, 2014.11.17>', 7365);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12698, '② 소장은 관심대상수용자의 수용생활태도 등이 양호하고 지정사유가 해소되었다고 인정하는 경우에는 제1항의 절차에 따라 그 지정을 해제한다. <개정 2013.4.16, 2016.6.28>', 7365);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12699, '③ 제1항 및 제2항에 따라 관심대상수용자로 지정하거나 지정을 해제하는 경우에는 담당교도관 또는 감독교도관의 의견을 고려하여야 한다.', 7365);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12700, null, 7368);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12701, null, 7369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12702, null, 7370);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12703, null, 7371);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12704, null, 7372);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12705, '① 다른 수용자를 교사(敎唆)하여 징벌대상행위를 하게 한 수용자에게는 그 징벌대상행위를 한 수용자에게 부과되는 징벌과 같은 징벌을 부과한다.', 7373);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12706, '② 다른 수용자의 징벌대상행위를 방조(幇助)한 수용자에게는 그 징벌대상행위를 한 수용자에게 부과되는 징벌과 같은 징벌을 부과하되, 그 정황을 고려하여 2분의 1까지 감경할 수 있다.', 7373);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12707, '① 둘 이상의 징벌대상행위가 경합하는 경우에는 각각의 행위에 해당하는 징벌 중 가장 중한 징벌의 2분의 1까지 가중할 수 있다.', 7374);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12708, '② 제1항의 경우 징벌의 경중(輕重)은 제215조 각 호의 순서에 따른다. 이 경우 같은 조 제2호부터 제5호까지의 경우에는 각 목의 순서에 따른다.', 7374);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12709, null, 7375);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12710, '① 수용자의 징벌대상행위에 대한 조사기간(조사를 시작한 날부터 법 제111조제1항의 징벌위원회의 의결이 있는 날까지를 말한다. 이하 같다)은 10일 이내로 한다. 다만, 특히 필요하다고 인정하는 경우에는 1회에 한하여 7일을 초과하지 아니하는 범위에서 그 기간을 연장할 수 있다.', 7377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12711, '② 소장은 제1항의 조사기간 중 조사결과에 따라 다음 각 호의 어느 하나에 해당하는 조치를 할 수 있다. <개정 2013.4.16>', 7377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12712, '③ 제1항의 조사기간 중 법 제110조제2항에 따라 징벌대상자에 대하여 처우를 제한하는 경우에는 징벌위원회의 의결을 거쳐 처우를 제한한 기간의 전부 또는 일부를 징벌기간에 포함할 수 있다.', 7377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12713, '④ 소장은 징벌대상행위가 징벌대상자의 정신병적인 원인에 따른 것으로 의심할 만한 충분한 사유가 있는 경우에는 징벌절차를 진행하기 전에 의사의 진료, 전문가 상담 등 필요한 조치를 하여야 한다.', 7377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12714, '⑤ 소장은 징벌대상행위에 대한 조사 결과 그 행위가 징벌대상자의 정신병적인 원인에 따른 것이라고 인정하는 경우에는 그 행위를 이유로 징벌위원회에 징벌을 요구할 수 없다.', 7377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12715, '⑥ 제1항의 조사기간 중 징벌대상자의 생활용품 등의 보관에 대해서는 제232조를 준용한다. <신설 2010.5.31>', 7377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12716, '① 소장은 징벌대상자의 질병이나 그 밖의 특별한 사정으로 인하여 조사를 계속하기 어려운 경우에는 조사를 일시 정지할 수 있다.', 7378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12717, '② 제1항에 따라 정지된 조사기간은 그 사유가 해소된 때부터 다시 진행한다. 이 경우 조사가 정지된 다음 날부터 정지사유가 소멸한 전날까지의 기간은 조사기간에 포함되지 아니한다.', 7378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12718, '① 소장은 법 제111조제2항에 따른 징벌위원회의 외부위원을 다음 각 호의 사람 중에서 위촉한다. <개정 2014.11.17, 2019.10.22>', 7380);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12719, '② 제1항에 따라 위촉된 위원의 임기는 2년으로 하며, 연임할 수 있다.', 7380);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12720, '③ 소장은 외부위원이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 위원을 해촉할 수 있다. <개정 2016.6.28>', 7380);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12721, '④ 제1항에 따라 위촉된 위원이 징벌위원회에 참석한 경우에는 예산의 범위에서 수당, 여비, 그 밖에 필요한 경비를 지급할 수 있다.', 7380);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12722, null, 7382);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12723, '① 소장이 징벌대상자에 대하여 징벌의결을 요구하는 경우에는 별지 제14호서식의 징벌의결 요구서를 작성하여 징벌위원회에 제출하여야 한다.', 7383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12724, '② 제1항에 따른 징벌의결 요구서에는 징벌대상행위의 입증에 필요한 관계서류를 첨부할 수 있다.', 7383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12725, '① 징벌위원회가 제226조에 따른 징벌의결 요구서를 접수한 경우에는 지체 없이 징벌대상자에게 별지 제15호서식의 출석통지서를 전달하여야 한다.', 7384);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12726, '② 제1항에 따른 출석통지서에는 다음 각 호의 내용이 포함되어야 한다.', 7384);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12727, '③ 제1항에 따라 출석통지서를 전달받은 징벌대상자가 징벌위원회에 출석하기를 원하지 아니하는 경우에는 별지 제16호서식의 출석포기서를 징벌위원회에 제출하여야 한다.', 7384);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12728, '① 징벌위원회는 출석한 징벌대상자를 심문하고, 필요하다고 인정하는 경우에는 교도관이나 다른 수용자 등을 참고인으로 출석하게 하여 심문할 수 있다.', 7385);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12729, '② 징벌위원회는 필요하다고 인정하는 경우 제219조의2에 따라 심리상담을 한 교도관으로 하여금 그 심리상담 결과를 제출하게 하거나 해당 교도관을 징벌위원회에 출석하게 하여 심리상담 결과를 진술하게 할 수 있다. <신설 2018.12.28>', 7385);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12730, '③ 징벌위원회는 징벌대상자에게 제227조제1항에 따른 출석통지서를 전달하였음에도 불구하고 징벌대상자가 같은 조 제3항에 따른 출석포기서를 제출하거나 정당한 사유 없이 출석하지 아니한 경우에는 그 사실을 별지 제17호서식의 징벌위원회 회의록에 기록하고 서면심리만으로 징벌을 의결할 수 있다. <개정 2018.12.28>', 7385);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12731, '④ 징벌위원회는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다. 이 경우 외부위원 1명 이상이 출석한 경우에만 개의할 수 있다. <개정 2014.11.17, 2018.12.28>', 7385);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12732, '⑤ 징벌의 의결은 별지 제18호서식의 징벌의결서에 따른다. <개정 2018.12.28>', 7385);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12733, '⑥ 징벌위원회가 작업장려금 삭감을 의결하려면 사전에 수용자의 작업장려금을 확인하여야 한다. <개정 2018.12.28>', 7385);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12734, '⑦ 징벌위원회의 회의에 참여한 사람은 직무상 알게 된 비밀을 누설하여서는 아니 된다. <개정 2018.12.28>', 7385);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12735, '① 징벌위원회는 영 제132조에 따라 소장에게 징벌의결 내용을 통고하는 경우에는 징벌의결서 정본(正本)을 첨부하여야 한다.', 7386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12736, '② 소장은 징벌을 집행하려면 징벌의결의 내용과 징벌처분에 대한 불복방법 등을 기록한 별지 제19호서식의 징벌집행통지서에 징벌의결서 부본(副本)을 첨부하여 해당 수용자에게 전달하여야 한다.', 7386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12737, '③ 영 제137조에 따른 징벌집행부는 별지 제19호의2 서식에 따른다. <신설 2019.10.22>', 7386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12738, '④ 소장은 영 제137조에 따라 수용자의 징벌에 관한 사항을 징벌집행부에 기록한 때에는 그 내용을 제119조제3항에 따른 교정정보시스템에 입력해야 한다. <신설 2019.10.22>', 7386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12739, '① 금치와 그 밖의 징벌을 집행할 경우에는 금치를 우선하여 집행한다. 다만, 작업장려금의 삭감과 경고는 금치와 동시에 집행할 수 있다.', 7387);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12740, '② 같은 종류의 징벌은 그 기간이 긴 것부터 집행한다.', 7387);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12741, '③ 금치를 제외한 두 가지 이상의 징벌을 집행할 경우에는 함께 집행할 수 있다.', 7387);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12742, '④ 두 가지 이상의 금치는 연속하여 집행할 수 없다. 다만, 두 가지 이상의 금치 기간의 합이 45일 이하인 경우에는 그렇지 않다. <신설 2024.2.8>', 7387);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12743, '① 작업장려금의 삭감은 징벌위원회가 해당 징벌을 의결한 날이 속하는 달의 작업장려금부터 이미 지급된 작업장려금에 대하여 역순으로 집행한다.', 7388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12744, '② 소장은 금치를 집행하는 경우에는 징벌집행을 위하여 별도로 지정한 거실(이하 "징벌거실"이라 한다)에 해당 수용자를 수용하여야 한다.', 7388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12745, '③ 소장은 금치 외의 징벌을 집행하는 경우 그 징벌의 목적을 달성하기 위하여 필요하다고 인정하면 해당 수용자를 징벌거실에 수용할 수 있다.', 7388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12746, '④ 소장은 징벌집행을 받고 있거나 집행을 앞둔 수용자가 같은 행위로 형사 법률에 따른 처벌이 확정되어 징벌을 집행할 필요가 없다고 인정하면 징벌집행을 감경하거나 면제할 수 있다.', 7388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12747, '① 소장은 징벌집행 중인 수용자의 심리적 안정과 징벌대상행위의 재발방지를 위해서 교도관으로 하여금 징벌집행 중인 수용자에 대한 심리상담을 하게 해야 한다.', 7390);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12748, '② 소장은 징벌대상행위의 재발방지에 도움이 된다고 인정하는 경우에는 징벌집행 중인 수용자가 교정위원, 자원봉사자 등 전문가의 상담을 받게 할 수 있다.', 7390);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12749, '① 법 제115조제1항에서 "법무부령으로 정하는 기간"이란 다음 각 호와 같다. <개정 2013.4.16>', 7391);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12750, '② 소장은 법 제115조제1항ㆍ제2항에 따라 징벌을 실효시킬 필요가 있으면 징벌실효기간이 지나거나 분류처우위원회의 의결을 거친 후에 지체 없이 법무부장관에게 그 승인을 신청하여야 한다.', 7391);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12751, '③ 소장은 법 제115조에 따라 실효된 징벌을 이유로 그 수용자에게 처우상 불이익을 주어서는 아니 된다.', 7391);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12752, '① 가석방심사는 객관적 자료와 기준에 따라 공정하게 하여야 하며, 심사 과정에서 알게 된 비밀은 누설해서는 아니 된다.', 7394);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12753, '② 삭제 <2013.4.16>', 7394);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12754, '① 위원장은 위원회를 소집하고 위원회의 업무를 총괄한다.', 7395);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12755, '② 위원장이 부득이한 사정으로 직무를 수행할 수 없을 때에는 위원장이 미리 지정한 위원이 그 직무를 대행한다.', 7395);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12756, null, 7396);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12757, null, 7397);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12758, '① 위원장은 위원회의 사무를 처리하기 위하여 소속 공무원 중에서 간사 1명과 서기 약간 명을 임명한다.', 7399);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12759, '② 간사는 위원장의 명을 받아 위원회의 사무를 처리하고 회의에 참석하여 발언할 수 있다.', 7399);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12760, '③ 서기는 간사를 보조한다.', 7399);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12761, '① 위원회의 회의는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.', 7400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12762, '② 간사는 위원회의 결정에 대하여 결정서를 작성하여야 한다.', 7400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12763, '① 간사는 별지 제20호서식의 가석방심사위원회 회의록을 작성하여 유지하여야 한다.', 7401);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12764, '② 회의록에는 회의의 내용을 기록하고 위원장 및 간사가 기명날인 또는 서명하여야 한다. <개정 2013.4.16>', 7401);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12765, '① 소장은 「형법」 제72조제1항의 기간을 경과한 수형자로서 교정성적이 우수하고 뉘우치는 빛이 뚜렷하여 재범의 위험성이 없다고 인정하는 경우에는 분류처우위원회의 의결을 거쳐 가석방 적격심사신청 대상자를 선정한다. <개정 2010.5.31>', 7403);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12766, '② 소장은 가석방 적격심사신청에 필요하다고 인정하면 분류처우위원회에 수형자를 출석하게 하여 진술하도록 하거나 담당교도관을 출석하게 하여 의견을 들을 수 있다. <개정 2010.5.31, 2024.2.8>', 7403);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12767, null, 7404);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12768, '① 소장은 제246조에 따라 조사한 사항을 매월 분류처우위원회의 회의 개최일 전날까지 분류처우심사표에 기록하여야 한다.', 7406);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12769, '② 제1항의 분류처우심사표는 법무부장관이 정한다.', 7406);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12770, '① 제246조제1호의 사항에 대한 조사는 수형자를 수용한 날부터 1개월 이내에 하고, 그 후 변경할 필요가 있는 사항이 발견되거나 가석방 적격심사신청을 위하여 필요한 경우에 한다. <개정 2010.5.31>', 7407);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12771, '② 제246조제2호의 사항에 대한 조사는 수형자를 수용한 날부터 2개월 이내에 하고, 조사에 필요하다고 인정하는 경우에는 소송기록을 열람할 수 있다.', 7407);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12772, '③ 제246조제3호의 사항에 대한 조사는 형기의 3분의 1이 지나기 전에 하여야 하고, 그 후 변경된 사항이 있는 경우에는 지체 없이 그 내용을 변경하여야 한다.', 7407);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12773, '① 소장은 법 제121조제1항에 따라 가석방 적격심사를 신청할 때에는 별지 제21호서식의 가석방 적격심사신청서에 별지 제22호서식의 가석방 적격심사 및 신상조사표를 첨부하여야 한다. <개정 2010.5.31>', 7408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12774, '② 소장은 가석방 적격심사신청 대상자를 선정한 경우 선정된 날부터 5일 이내에 위원회에 가석방 적격심사신청을 하여야 한다. <개정 2010.5.31>', 7408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12775, '③ 소장은 위원회에 적격심사신청한 사실을 수형자의 동의를 받아 보호자 등에게 알릴 수 있다. <개정 2010.5.31>', 7408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12776, '① 위원회가 범죄의 동기에 관하여 심사할 때에는 사회의 통념 및 공익 등에 비추어 정상을 참작할 만한 사유가 있는지를 심사하여야 한다.', 7411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12777, '② 범죄의 동기가 군중의 암시 또는 도발, 감독관계에 의한 위협, 그 밖에 이와 유사한 사유로 인한 것일 때에는 특히 수형자의 성격 또는 환경의 변화에 유의하고 가석방 후의 환경이 가석방처분을 받은 사람(「보호관찰 등에 관한 법률」에 따른 보호관찰대상자는 제외한다. 이하 "가석방자"라 한다)에게 미칠 영향을 심사하여야 한다.', 7411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12778, null, 7412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12779, '① 재산에 관한 죄를 지은 수형자에 대하여는 특히 그 범행으로 인하여 발생한 손해의 배상 여부 또는 손해를 경감하기 위한 노력 여부를 심사하여야 한다.', 7413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12780, '② 수형자 외의 사람이 피해자의 손해를 배상한 경우에는 그 배상이 수형자 본인의 희망에 따른 것인지를 심사하여야 한다.', 7413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12781, '① 위원회는 가석방 적격심사에 특히 필요하다고 인정하면 심층면접(수형자 면담ㆍ심리검사, 수형자의 가족 또는 보호관계에 있는 사람 등에 대한 방문조사 등을 통해 재범의 위험성, 사회복귀 준비 상태 등을 파악하는 것을 말한다. 이하 이 조에서 같다)을 실시할 수 있다.', 7414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12782, '② 심층면접의 방법, 절차, 그 밖에 필요한 사항은 법무부장관이 정한다.', 7414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12783, '① 위원회는 가석방 적격심사에 필요하다고 인정하면 수형자의 주소지 또는 연고지 등을 관할하는 시ㆍ군ㆍ구ㆍ경찰서, 그 밖에 학교ㆍ직업알선기관ㆍ보호단체ㆍ종교단체 등 관계기관에 사실조회를 할 수 있다. <개정 2010.5.31>', 7415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12784, '② 위원회는 가석방 적격심사를 위하여 필요하다고 인정하면 위원이 아닌 판사ㆍ검사 또는 군법무관에게 의견을 묻거나 위원회에 참여시킬 수 있다. <개정 2010.5.31>', 7415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12785, '① 위원회는 가석방 적격심사를 위하여 필요하다고 인정하면 심리학ㆍ정신의학ㆍ사회학 또는 교육학을 전공한 전문가에게 수형자의 정신상태 등 특정 사항에 대한 감정을 촉탁할 수 있다. <개정 2010.5.31>', 7416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12786, '② 제1항에 따른 촉탁을 받은 사람은 소장의 허가를 받아 수형자와 접견할 수 있다.', 7416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12787, '① 수형자를 가석방한 소장 또는 가석방자를 수용하고 있는 소장은 가석방자가 제260조의 가석방 취소사유에 해당하는 사실이 있음을 알게 되거나 관할 경찰서장으로부터 그 사실을 통보받은 경우에는 지체 없이 별지 제25호서식의 가석방 취소심사신청서에 별지 제26호서식의 가석방 취소심사 및 조사표를 첨부하여 위원회에 가석방 취소심사를 신청하여야 한다.', 7420);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12788, '② 위원회가 제1항의 신청을 받아 심사를 한 결과 가석방을 취소하는 것이 타당하다고 결정한 경우에는 별지 제23호서식의 결정서에 별지 제26호서식의 가석방 취소심사 및 조사표를 첨부하여 지체 없이 법무부장관에게 가석방의 취소를 신청하여야 한다.', 7420);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12789, '③ 소장은 가석방을 취소하는 것이 타당하다고 인정하는 경우 긴급한 사유가 있을 때에는 위원회의 심사를 거치지 아니하고 전화, 전산망 또는 그 밖의 통신수단으로 법무부장관에게 가석방의 취소를 신청할 수 있다. 이 경우 소장은 지체 없이 별지 제26호서식의 가석방 취소심사 및 조사표를 송부하여야 한다.', 7420);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12790, '① 위원회가 가석방 취소를 심사하는 경우에는 가석방자가 「가석방자관리규정」등의 법령을 위반하게 된 경위와 그 위반이 사회에 미치는 영향, 가석방 기간 동안의 생활 태도, 직업의 유무와 종류, 생활환경 및 친족과의 관계, 그 밖의 사정을 고려하여야 한다.', 7421);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12791, '② 위원회는 제1항의 심사를 위하여 필요하다고 인정하면 가석방자를 위원회에 출석하게 하여 진술을 들을 수 있다.', 7421);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12792, '① 소장은 가석방이 취소된 경우에는 지체 없이 남은 형기 집행에 필요한 조치를 취하고 법무부장관에게 별지 제27호서식의 가석방취소자 남은 형기 집행보고서를 송부해야 한다. <개정 2022.2.7>', 7422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12793, '② 소장은 가석방자가 「형법」 제74조에 따라 가석방이 실효된 것을 알게 된 경우에는 지체 없이 남은 형기 집행에 필요한 조치를 취하고 법무부장관에게 별지 제28호서식의 가석방실효자 남은 형기 집행보고서를 송부해야 한다. <개정 2022.2.7>', 7422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12794, '③ 소장은 가석방이 취소된 사람(이하 "가석방취소자"라 한다) 또는 가석방이 실효된 사람(이하 "가석방실효자"라 한다)이 교정시설에 수용되지 아니한 사실을 알게 된 때에는 관할 지방검찰청 검사 또는 관할 경찰서장에게 구인하도록 의뢰하여야 한다.', 7422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12795, '④ 제3항에 따라 구인 의뢰를 받은 검사 또는 경찰서장은 즉시 가석방취소자 또는 가석방실효자를 구인하여 소장에게 인계하여야 한다.', 7422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12796, '⑤ 가석방취소자 및 가석방실효자의 남은 형기 기간은 가석방을 실시한 다음 날부터 원래 형기의 종료일까지로 하고, 남은 형기 집행 기산일은 가석방의 취소 또는 실효로 인하여 교정시설에 수용된 날부터 한다. <개정 2022.2.7>', 7422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12797, '⑥ 가석방 기간 중 형사사건으로 구속되어 교정시설에 미결수용 중인 자의 가석방 취소 결정으로 남은 형기를 집행하게 된 경우에는 가석방된 형의 집행을 지휘하였던 검찰청 검사에게 남은 형기 집행지휘를 받아 우선 집행해야 한다. <개정 2022.2.7>', 7422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12798, null, 7425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12799, '① 위원회에 부위원장을 두며, 위원 중에서 호선한다.', 7426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12800, '② 위원 중 4명 이상은 여성으로 한다. <개정 2019.10.22>', 7426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12801, '③ 지방교정청장이 위원을 추천하는 경우에는 별지 제29호서식의 교정자문위원회 위원 추천서를 법무부장관에게 제출하여야 한다. 다만, 재위촉의 경우에는 지방교정청장의 의견서로 추천서를 갈음한다. <개정 2019.10.22>', 7426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12802, '① 위원의 임기는 2년으로 하며, 연임할 수 있다.', 7427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12803, '② 지방교정청장은 위원의 결원이 생긴 경우에는 결원이 생긴 날부터 30일 이내에 후임자를 법무부장관에게 추천해야 한다. <개정 2019.10.22>', 7427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12804, '③ 결원이 된 위원의 후임으로 위촉된 위원의 임기는 전임자 임기의 남은 기간으로 한다.', 7427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12805, '① 위원장은 위원회를 소집하고 위원회의 업무를 총괄한다.', 7428);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12806, '② 위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 부위원장이 그 직무를 대행하고, 부위원장도 부득이한 사유로 직무를 수행할 수 없을 때에는 위원장이 미리 지명한 위원이 그 직무를 대행한다.', 7428);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12807, '① 위원회의 회의는 위원 과반수의 요청이 있거나 지방교정청장이 필요하다고 인정하는 경우에 개최한다. <개정 2013.4.16, 2019.10.22>', 7429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12808, '② 위원회는 재적위원 과반수의 출석으로 개의하고 출석위원 과반수의 찬성으로 의결한다.', 7429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12809, '③ 위원회의 회의는 공개하지 아니한다. 다만, 위원회의 의결을 거친 경우에는 공개할 수 있다.', 7429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12810, '① 위원은 다음 사항을 지켜야 한다. <개정 2020.8.5>', 7430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12811, '② 위원은 별지 제30호서식의 서약서에 규정된 바에 따라 제1항의 내용을 지키겠다는 서약을 해야 한다. <개정 2020.8.5>', 7430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12812, null, 7431);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12813, '① 위원회의 사무를 처리하기 위하여 위원회에 간사 1명을 둔다. 간사는 해당 지방교정청의 총무과장 또는 6급 이상의 교도관으로 한다. <개정 2019.10.22>', 7432);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12814, '② 간사는 회의에 참석하여 위원회의 심의사항에 대한 설명을 하거나 필요한 발언을 할 수 있으며, 별지 제31호서식의 교정자문위원회 회의록을 작성하여 유지하여야 한다.', 7432);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12815, '① 경찰서장, 해양경찰서장, 제주특별자치도지사 또는 철도특별사법경찰대장(이하 "경찰서장등"이라 한다)은 법 제7조에 따라 범칙자로 인정되는 사람에게 범칙금 납부를 통고할 때에는 다음 각 호의 사항을 적은 범칙금 납부통고서를 범칙금 영수증 및 범칙금 납부고지서와 함께 발부하고, 범칙금 납부고지서 발행원부와 범칙자 적발보고서를 작성하여야 한다. <개정 2014.11.19, 2017.7.26>', 7436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12816, '② 경찰서장등은 제1항에 따른 통고처분을 하였을 때에는 통고처분사항을 통고처분처리부에 기록하거나 전자매체를 통하여 전산으로 저장ㆍ관리하여야 한다.', 7436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12817, '③ 경찰서장 또는 해양경찰서장은 해당 경찰서의 관할구역 밖에 거주하는 범칙자로 인정되는 사람에게 범칙금 납부통고서를 발부한 경우에 범칙금 납부통고서를 받은 사람이 범칙금을 납부한 사실이 법 제8조제2항에 따라 범칙금을 납부할 수 있는 기간의 마지막 날(이하 "납부기간만료일"이라 한다)부터 5일이 지난 날까지 확인되지 아니할 때에는 그 날부터 3일 이내에 범칙자의 주소지를 관할하는 경찰서장 또는 해양경찰서장에게 제1항에 따른 범칙자 적발보고서 사본을 발송하여야 한다. <개정 2014.11.19, 2017.7.26>', 7436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12818, '① 제3조제1항에 따른 납부통고를 받은 사람은 같은 항에 따라 발부받은 범칙금 영수증 및 범칙금 납부고지서를 법 제8조제1항에 따라 경찰청장, 해양경찰청장 또는 철도특별사법경찰대장이 지정한 은행, 그 지점이나 대리점, 우체국 또는 제주특별자치도지사가 지정하는 금융기관이나 그 지점(이하 "수납기관"이라 한다)에 제시하고 범칙금을 납부하여야 한다. <개정 2014.11.19, 2017.7.26>', 7437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12819, '② 범칙금은 분할하여 납부할 수 없다.', 7437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12820, '③ 제1항에 따라 범칙금을 받은 수납기관은 같은 항에 따라 제시된 범칙금 영수증에 범칙금 납부 사실을 확인하여 범칙금을 납부한 사람에게 내주어야 한다.', 7437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12821, '④ 수납기관이 범칙금을 받았을 때에는 지체 없이 범칙금 수납 사실을 범칙금 납부 통고를 한 경찰서장등에게 전자매체 등을 이용하여 통보하여야 한다.', 7437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12822, '① 법 제8조의2제1항 전단에서 "대통령령으로 정하는 범칙금 납부대행기관"이란 다음 각 호의 어느 하나에 해당하는 기관을 말한다.', 7438);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12823, '② 법 제8조의2제3항에 따른 납부대행수수료는 경찰청장이 범칙금 납부대행기관의 운영경비 등을 종합적으로 고려하여 승인하며, 해당 범칙금액(법 제8조제2항에 따라 부가되는 금액을 포함한다)의 1천분의 15를 초과할 수 없다.', 7438);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12824, '① 경찰서장등(철도특별사법경찰대장은 제외한다. 이하 이 조에서 같다)은 법 제9조제1항제1호에 해당하는 사람에게 지체 없이 다음 각 호의 사항을 적은 즉결심판 출석통지서를 발부하여야 한다. <개정 2014.11.19, 2016.7.19>', 7440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12825, '② 경찰서장등은 법 제9조제1항제2호에 해당하는 사람(이하 "통고처분 불이행자"라 한다)에게 납부기간만료일부터 30일 이내에 제1항 각 호의 사항 및 법 제9조제1항 각 호 외의 부분 단서에 따라 범칙금에 그 금액의 100분의 50을 더한 금액(이하 "범칙금등"이라 한다)을 납부할 경우 즉결심판을 받지 않아도 된다는 사실을 적은 즉결심판 출석통지서를 범칙금등 영수증 및 범칙금등 납부고지서와 함께 발부하여야 한다. <개정 2014.11.19, 2016.7.19>', 7440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12826, '③ 경찰서장등은 제1항 및 제2항에 따라 즉결심판 출석통지서를 받은 사람이 즉결심판 기일에 출석하지 아니하여 즉결심판 절차가 진행되지 못한 경우에는 즉결심판을 위한 출석의 일시 및 장소를 다시 정하여 지체 없이 그 즉결심판 대상자에게 제1항 또는 제2항의 사항을 적은 즉결심판 출석최고서를 발부하되, 통고처분 불이행자에게 즉결심판 출석최고서를 발부할 때에는 범칙금등 영수증과 범칙금등 납부고지서를 함께 발부하여야 한다. <개정 2014.11.19, 2016.7.19>', 7440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12827, '④ 통고처분 불이행자의 경우 제2항에 따른 즉결심판을 위한 출석일은 납부기간만료일부터 40일을 초과해서는 아니 되며, 제3항에 따른 즉결심판을 위한 출석일은 법원의 사정으로 즉결심판을 할 수 없는 경우 등의 특별한 사정이 없으면 납부기간만료일부터 60일을 초과해서는 아니 된다.', 7440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12828, '⑤ 경찰서장등은 법 제9조제1항에 따라 즉결심판을 청구하려는 경우에는 즉결심판사범 적발보고서를 작성한 후 관할법원에 즉결심판청구서를 제출하여야 한다. <개정 2014.11.19, 2016.7.19>', 7440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12829, '① 철도특별사법경찰대장은 법 제7조제1항 각 호의 어느 하나에 해당하는 사람에게는 즉결심판 출석 통지를 받게 될 것임을 알리는 즉결심판 통지예고서를 즉시 발부하고, 즉결심판 대상자 적발통보서를 작성하여 관할 경찰서장 또는 해양경찰서장에게 통보하여야 한다. <개정 2014.11.19, 2016.7.19, 2017.7.26>', 7441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12830, '② 철도특별사법경찰대장은 범칙금 납부통고서를 받은 사람이 범칙금을 납부한 사실이 납부기간만료일부터 5일이 지난 날까지 확인되지 아니할 때에는 즉시 범칙자의 주소지를 관할하는 경찰서장 또는 해양경찰서장에게 제3조제1항에 따른 범칙자 적발보고서 사본을 발송하여야 한다. <개정 2014.11.19, 2016.7.19, 2017.7.26>', 7441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12831, '① 제3조제3항 및 제7조제2항에 따라 범칙자 적발보고서 사본을 받은 경찰서장 또는 해양경찰서장은 범칙자 적발보고서 사본을 보낸 경찰서장등에게 범칙금 납부통고서를 받은 사람의 즉결심판 청구에 필요한 자료를 요청할 수 있다. <개정 2014.11.19, 2017.7.26>', 7442);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12832, '② 제3조제3항 및 제7조제2항에 따라 범칙자 적발보고서 사본을 받은 경찰서장 또는 해양경찰서장은 그 내용을 통고처분 접수처리부에 기록하거나 전자매체를 통하여 전산으로 저장ㆍ관리하여야 한다. <개정 2014.11.19, 2017.7.26>', 7442);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12833, null, 7445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12834, '① 검사가 공소를 제기하면서 동시에 치료감호 청구를 하는 경우 치료감호청구서에 적어야 할 법 제4조제4항제1호의 사항은 공소장에 적힌 피고인의 성명, 연령, 등록기준지, 주거, 직업 등으로 갈음하고, 청구의 원인이 되는 사실 및 적용법조는 공소장의 공소사실 및 적용법조에 추가하여 적는다.', 7447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12835, '② 검사가 공소를 제기하지 아니하고 치료감호 청구만을 하거나 공소를 제기한 후에 치료감호 청구를 하는 경우에는 치료감호청구서에 치료감호가 청구된 치료감호대상자(이하 "피치료감호청구인"이라 한다)의 성명, 연령, 등록기준지, 주거, 직업, 죄명과 청구의 원인이 되는 사실 및 적용법조를 적는다. <개정 2018.6.12>', 7447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12836, '③ 제1항 및 제2항의 경우에는 구속영장 또는 치료감호영장이나 그 등본, 변호인 선임서, 피의자 또는 치료감호대상자 수용증명, 구속 또는 보호구속기간 연장결정서나 그 등본 등을 첨부한다.', 7447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12837, '① 치료감호를 선고받은 자(이하 "피치료감호자"라 한다)에 대하여는 법 제16조제1항에 따른 치료감호시설(이하 "치료감호시설"이라 한다)에 수용ㆍ감호하고 치료와 재활교육을 한다. <개정 2014.1.28>', 7448);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12838, '② 피치료감호자에 대하여는 심신장애의 정도 또는 제2조에 규정된 물질이나 알코올을 식음(食飮)하는 등의 습벽(習癖) 및 중독된 정도, 정신성적(精神性的) 장애의 정도에 따라 분리수용한다.', 7448);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12839, '① 치료감호시설의 장은 법 제16조제3항에 따라 피치료감호자의 치료감호 기간 연장을 검사에게 신청하려면 다음 각 호의 사항을 적은 서면에 그 신청사유를 소명(疎明)할 수 있는 자료를 첨부하여 제출하여야 한다.', 7449);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12840, '② 제1항에 따른 치료감호 기간 연장 신청은 법 제16조제2항 각 호의 기간 또는 같은 조 제3항에 따라 연장된 기간이 종료하기 7개월 전까지 하여야 한다.', 7449);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12841, '① 법무부장관은 법 제16조의2제1항제2호에 따른 지정법무병원(이하 "지정법무병원"이라 한다)을 지정하기 위하여 필요한 경우 보건복지부장관의 의견을 들을 수 있다.', 7450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12842, '② 법무부장관은 지정법무병원을 지정한 경우에는 보건복지부장관 및 지정법무병원의 장에게 그 사실을 통보하여야 한다.', 7450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12843, '① 지정법무병원의 장은 피치료감호자가 입원하면 지정법무병원의 정신건강의학과 의사 중 피치료감호자의 치료를 담당할 의사를 지정하여야 한다.', 7451);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12844, '② 지정법무병원의 피치료감호자 수용정원은 50명 이내로 한다. 다만, 법무부장관은 치료감호시설 전체 수용인원 및 치료의 적절성을 고려하여 수용정원을 조정할 수 있다.', 7451);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12845, '③ 제1항 및 제2항에서 규정한 사항 외에 피치료감호자의 수용 및 치료에 필요한 세부 사항은 법무부장관이 정한다.', 7451);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12846, '① 법 제16조의2제3항에 따라 국가는 예산의 범위에서 다음 각 호의 경비를 지정법무병원에 보조하여야 한다.', 7452);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12847, '② 지정법무병원의 장은 제1항에 따른 경비보조를 받으려면 경비보조 청구서에 다음 각 호의 서류를 첨부하여 매달 10일까지 법무부장관에게 제출하여야 한다.', 7452);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12848, '① 치료감호시설의 장은 피치료감호자에 대하여 치료감호 집행을 시작한 후 6개월마다 피치료감호자의 동태ㆍ치료정도와 그 밖에 필요한 사항을 법 제37조에 따른 치료감호심의위원회(이하 "위원회"라 한다)에 보고하여야 한다. <개정 2014.1.28>', 7453);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12849, '② 지정법무병원의 장은 피치료감호자가 다음 각 호의 어느 하나에 해당하면 지체 없이 위원회에 보고하여야 한다. <신설 2014.1.28>', 7453);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12850, '③ 치료감호시설의 장은 치료감호를 종료 또는 가종료(假終了)하거나 치료를 위탁하는 것이 타당하다고 인정하는 경우에는 검사에게 제1항의 사항을 통보하여 위원회에 심사를 신청하도록 요청할 수 있다. <개정 2014.1.28>', 7453);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12851, '① 판사와 검사는 치료감호시설을 수시로 시찰할 수 있다. <개정 2014.1.28>', 7454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12852, '② 판사나 검사가 아닌 사람이 법 제20조에 따라 치료감호시설을 참관하려면 치료감호시설의 장의 허가를 받아야 한다. <개정 2014.1.28>', 7454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12853, '③ 치료감호시설의 장은 치료감호시설을 참관하려는 사람에 대하여 그 성명ㆍ직업ㆍ주소 및 참관의 목적을 명백히 한 후 정당한 이유가 있을 때에는 참관을 허가하여야 한다. <개정 2014.1.28>', 7454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12854, '④ 치료감호시설의 장은 외국인이 치료감호시설을 참관하려는 경우에는 법무부장관의 승인을 받아 참관을 허가하여야 한다. <개정 2014.1.28>', 7454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12855, '⑤ 치료감호시설의 장은 참관을 허가받은 사람에게 참관할 때의 주의사항을 고지하여야 한다. <개정 2014.1.28>', 7454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12856, '① 지정법무병원의 장은 법 제21조의2제2항의 사유가 있는 경우에는 위원회에 피치료감호자의 재이송을 신청할 수 있다.', 7455);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12857, '② 지정법무병원의 장은 제1항에 따른 재이송 신청을 할 때에는 증상 악화에 대한 담당 의사의 의견서 등 지정법무병원에서 계속 치료하기 곤란한 사유를 확인할 수 있는 관련 자료를 첨부하여야 한다.', 7455);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12858, '③ 위원회는 제1항에 따른 재이송 신청을 받으면 피치료감호자에 대한 재이송이 적절한지를 심사하여 결정하여야 한다.', 7455);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12859, '① 치료감호시설의 장은 법 제25조의2제3항에 따라 다음 각 호의 사항을 고려하여 피치료감호청구인의 생활실을 구분하는 등 피치료감호청구인에게 적합한 처우를 하여야 한다.', 7457);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12860, '② 치료감호시설의 장은 피치료감호청구인의 처우를 위하여 필요한 경우 피치료감호청구인을 대상으로 상담 등을 통한 신상에 관한 개별사안의 조사, 심리ㆍ지능ㆍ적성 검사, 그 밖에 필요한 검사를 할 수 있다.', 7457);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12861, '① 치료감호시설의 장은 법 제25조의3제1항에 따라 피치료감호자 및 피치료감호청구인(이하 "피치료감호자등"이라 한다)에게 격리 또는 묶는 등의 신체적 제한(이하 "보호조치"라 한다)을 하려면 다음 각 호의 어느 하나에 해당하는 방법으로 하여야 한다. 이 경우 제2호의 보호조치는 법 제25조의3제1항제1호의 경우에만 할 수 있다.', 7458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12862, '② 제1항제1호에 따른 보호조치의 기간은 15일 이내로 한다. 다만, 치료감호시설의 장은 다음 각 호의 구분에 따른 의사의 지시에 따라 특히 계속하여 보호조치를 할 필요가 있으면 이를 연장할 수 있다. <개정 2021.4.6>', 7458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12863, '③ 제2항 단서에 따른 보호조치 기간 연장은 1회에 7일 이내로 하되, 보호조치 기간은 계속하여 30일을 초과할 수 없다.', 7458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12864, '④ 제1항제2호에 따른 보호조치의 기간은 24시간 이내로 한다. 다만, 치료감호시설의 장은 정신건강의학과 전문의의 지시에 따라 특히 계속하여 보호조치를 할 필요가 있으면 이를 24시간 이내에서 한 차례만 연장할 수 있다. <개정 2021.4.6>', 7458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12865, '⑤ 치료감호시설의 장은 피치료감호자등에게 보호조치를 하는 경우 법 제25조의3제4항에 따라 피치료감호자등 보호원부에 다음 각 호의 사항을 작성ㆍ보존해야 한다. <개정 2021.4.6>', 7458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12866, '⑥ 피치료감호자등 보호원부의 서식에 관한 사항은 법무부령으로 정한다.', 7458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12867, '① 피치료감호자등이나 법정대리인등이 법 제30조제1항에 따라 피치료감호자등의 처우개선에 관하여 청원할 경우에는 법무부장관에게 문서로 하여야 한다. <개정 2018.6.12>', 7459);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12868, '② 제1항에 따라 청원하려는 사람은 청원서를 작성하여 봉한 후 치료감호시설의 장에게 제출하여야 한다. <개정 2014.1.28>', 7459);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12869, '③ 치료감호시설의 장은 청원서를 개봉하여서는 아니 되며, 지체 없이  법무부장관에게 송부하여야 한다. <개정 2014.1.28>', 7459);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12870, '④ 치료감호시설의 장은 피치료감호자등 또는 법정대리인등이 청원을 하지 못하게 하거나 청원을 하였다는 이유로 피치료감호자등에게 불이익을 주어서는 아니 된다. <개정 2014.1.28, 2018.6.12>', 7459);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12871, '⑤ 법무부장관은 청원의 처리 결과를 치료감호시설의 장에게 문서로 통보하고, 치료감호시설의 장은 지체 없이 청원인에게 전달하여야 한다. <개정 2014.1.28>', 7459);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12872, '① 「보호관찰 등에 관한 법률」에 따른 보호관찰(이하 "보호관찰"이라 한다)을 받기 시작한 자(이하 "피보호관찰자"라 한다)에 대한 법 제33조제2항에 따른 준수사항의 부과는 위원회가 하되, 피보호관찰자마다 개인의 성향 등을 고려하여 서면으로 지시한다. <개정 2018.6.12>', 7460);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12873, '② 보호관찰관은 위원회가 피보호관찰자에게 부과한 준수사항의 이행을 독려(督勵)하기 위하여 필요한 범위에서 구체적인 지시를 할 수 있다.', 7460);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12874, '③ 보호관찰관은 피보호관찰자를 지도ㆍ감독하기 위하여 특별히 필요한 경우에는 피보호관찰자를 출석하게 하여 사실을 확인하거나 관계자에게 필요한 협조를 요청할 수 있다.', 7460);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12875, '① 위원회는 법 제33조제3항에 따라 피보호관찰자의 준수사항 전부 또는 일부의 추가ㆍ변경 또는 삭제에 관한 심사와 결정을 한 경우 그 내용을 피보호관찰자에게 문서로 알려야 한다.', 7461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12876, '② 보호관찰소의 장이 법 제33조제3항에 따라 피보호관찰자의 준수사항 전부 또는 일부의 추가ㆍ변경 또는 삭제를 위원회에 신청하려면 다음 각 호의 사항을 적은 문서로 하여야 한다.', 7461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12877, '③ 위원회는 제1항에 따른 심사를 위하여 필요하다고 인정하는 경우에는 해당 피보호관찰자를 담당하는 보호관찰관을 출석시켜 의견을 들을 수 있으며, 피보호관찰자를 심문하거나 필요한 사항을 조사ㆍ심리할 수 있다.', 7461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12878, '① 피보호관찰자는 2개월마다 다음 각 호의 사항을 보호관찰관에게 서면으로 신고해야 한다. <개정 2021.1.5>', 7463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12879, '② 피보호관찰자는 주거를 이전하거나 30일 이상 여행하려는 경우에는 미리 그 내용을 보호관찰관에게 서면으로 신고하여야 한다.', 7463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12880, '③ 피보호관찰자가 제1항 및 제2항에 따른 신고를 스스로 할 수 없는 경우에는 그 보호자(보호시설의 경우는 그 시설의 장을 말한다. 이하 같다) 또는 치료를 위탁받은 법정대리인등이 신고하여야 한다.', 7463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12881, '① 보호관찰관은 피보호관찰자의 동태를 관찰하고 건전한 사회인으로 복귀할 수 있도록 지도ㆍ감독하여야 한다.', 7464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12882, '② 보호관찰관은 보호관찰부를 작성하여 갖춰 두고, 매월 1회 이상 피보호관찰자의 주요 동태 및 제9조에 따른 준수사항의 이행 여부를 확인하여야 한다.', 7464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12883, '③ 보호관찰관은 6개월마다 제2항에 규정한 사항을 검사를 거쳐 위원회에 보고하여야 한다.', 7464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12884, '④ 보호관찰관은 피보호관찰자에게 다음 각 호의 어느 하나에 해당하는 사유가 있는 경우에는 지체 없이 검사를 거쳐 위원회에 보고하여야 한다.', 7464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12885, '⑤ 제4항제7호의 경우 보호관찰관은 검사에게 법 제43조에 따라 치료감호의 종료에 관한 심사신청을 할 것을 요청할 수 있다.', 7464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12886, '⑥ 보호관찰관은 제10조제2항에 따른 신고를 받은 경우에는 지체 없이 그 내용을 새 주거지 또는 여행지의 보호관찰관에게 통보하여야 한다. 이 경우 피보호관찰자가 주거를 이전한 때에는 지체 없이 피보호관찰자에 대한 보호관찰부와 그 밖의 관계 서류를 새 주거지 관할 보호관찰관에게 송부하여야 한다. <개정 2016.11.29>', 7464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12887, '⑦ 제6항 후단에 따라 관계 서류를 받은 새 주거지의 보호관찰관은 그 주거 이전의 사실을 확인한 후 지체 없이 검사를 거쳐 위원회에 보고하여야 한다.', 7464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12888, '① 보호관찰소의 장은 법 제33조의2제3항에 따라 피보호관찰자의 유치허가 신청을 하는 경우에는 다음 각 호의 사항을 적은 문서로 하여야 한다.', 7465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12889, '② 법 제33조의2제3항에 따라 판사가 발부하는 유치허가장에는 청구한 검사의 관직ㆍ성명ㆍ발부일시 및 제1항 각 호의 사항을 적어야 한다.', 7465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12890, '① 보호관찰소의 장은 법 제33조의2제4항에 따라 법 제22조에 따른 가종료 또는 법 제23조에 따른 치료의 위탁(이하 "가종료등"이라 한다)의 취소 신청을 요청하는 경우에는 다음 각 호의 사항을 적은 문서로 하여야 한다. 이 경우 법 제33조의2제4항에 따른 가종료등의 취소신청기간은 보호관찰소의 장이 유치허가장을 받은 때부터 기산한다.', 7467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12891, '② 검사는 법 제33조의2제4항에 따른 보호관찰소장의 가종료등의 취소 신청 요청을 기각한 경우에는 지체 없이 보호관찰소의 장에게 그 사실을 알려야 한다.', 7467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12892, '③ 검사는 법 제33조의2제5항에 따라 위원회에 가종료등의 취소 신청을 하는 경우에는 보호관찰소의 장이 제1항에 따라 제출한 문서를 첨부하고, 그 사유를 소명하여야 한다.', 7467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12893, '④ 위원회는 법 제33조의2제5항에 따른 가종료등의 취소 신청을 심리하기 위하여 필요하다고 인정하는 경우에는 치료감호시설의 장이나 보호관찰소의 장을 출석시켜 의견을 들을 수 있다.', 7467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12894, '① 피보호관찰자가 법 제34조제1항에 따른 출소 전 신고를 할 때에는 다음 각 호의 사항을 적은 신고서를 치료감호시설의 장에게 제출하여야 한다. <개정 2014.1.28>', 7470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12895, '② 제1항에 따른 신고서를 받은 치료감호시설의 장은 제1항 각 호의 사항과 다음 각 호의 사항을 적은 출소통보서를 작성하여 1부는 위원회에, 1부는 출소 후 거주 예정지 관할 보호관찰관에게 송부하고, 1부는 치료감호시설에 갖춰 두어야 한다. <개정 2014.1.28>', 7470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12896, '③ 법 제34조제2항에 따른 출소 후 신고를 할 때에는 다음 각 호의 사항을 적은 신고서를 보호관찰관에게 제출하여야 한다. <개정 2014.1.28, 2017.5.29>', 7470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12897, '④ 피보호관찰자는 제3항에 따른 신고사항이 변동된 경우에는 지체 없이 보호관찰관에게 신고하여야 한다.', 7470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12898, '⑤ 피보호관찰자가 제1항ㆍ제3항 및 제4항에 따른 신고를 스스로 할 수 없는 경우에는 그 보호자 또는 치료의 위탁을 받은 법정대리인등이 신고하여야 한다.', 7470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12899, '⑥ 제2항에 따른 통보를 받은 관할 보호관찰관은 피보호관찰자가 법 제34조제2항에 따른 출소 후 신고를 하지 아니한 경우에는 지체 없이 그 사실을 검사를 거쳐 위원회에 보고하여야 한다.', 7470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12900, '① 법 제36조의4제2항에 따라 보호관찰소의 장이 정신건강복지센터의 장에게 요청할 수 있는 정신보건 관련 정보는 다음 각 호와 같다. <개정 2017.5.29>', 7471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12901, '② 법 제36조의4제3항에 따라 정신건강복지센터의 장이 보호관찰소의 장에게 협조를 요청할 수 있는 사항은 다음 각 호와 같다. <개정 2017.5.29>', 7471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12902, '① 위원회의 위원은 위원장의 제청으로 법무부장관이 임명하거나 위촉한다.', 7472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12903, '② 공무원이 아닌 위원의 임기는 3년으로 한다.', 7472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12904, '③ 위원장은 위원회를 대표하고 위원회의 업무를 총괄하며, 위원회의 회의를 소집하고 그 의장이 된다.', 7472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12905, '④ 위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 위원장이 미리 지명한 위원이 그 직무를 대행한다.', 7472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12906, '⑤ 법 제37조제4항에 따른 자문위원은 10명 이내로 하며, 자문위원은 위원회의 심사ㆍ결정에 필요한 자문에 응한다.', 7472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12907, '① 위원회에 간사 2명과 서기 약간명을 둔다.', 7473);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12908, '② 간사와 서기는 법무부 소속 공무원 중에서 위원장이 임명한다.', 7473);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12909, '③ 간사는 위원장의 명을 받아 위원회의 사무를 처리하고 회의에 참석하여 발언할 수 있으며, 서기는 간사를 보조한다.', 7473);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12910, '① 검사가 법 제43조에 따라 위원회에 피치료감호자의 심사를 신청할 때에는 신청서에 피치료감호자의 성명ㆍ연령ㆍ주거ㆍ직업 등을 적고, 다음 각 호의 자료를 첨부하여야 한다. <개정 2014.1.28>', 7475);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12911, '② 제1항의 경우 검사는 치료감호사안과 관련된 사건기록을 보존하고 있는 검찰청으로부터 송부받아 이를 심사신청서와 함께 위원회에 송부할 수 있다.', 7475);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12912, '① 피치료감호자와 그 법정대리인등은 법 제44조에 따라 위원회에 치료감호의 종료 여부에 대한 심사를 신청할 때에는 정신건강의학과 등의 전문의의 진단서 또는 감정서를 첨부하여야 한다. <개정 2011.11.23, 2018.6.12>', 7476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12913, '② 치료감호시설의 장은 피치료감호자와 그 법정대리인등의 심사신청에 대하여 위원회에 의견을 제출할 수 있다. <개정 2014.1.28, 2018.6.12>', 7476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12914, null, 7477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12915, '① 위원회는 치료감호사안에 관하여 결정을 한 때에는 결정서 등본을 피치료감호자를 감호 또는 보호관찰하는 치료감호시설의 장이나 보호관찰관에게 송달한다. 다만, 검사의 신청을 받아 결정을 한 경우에는 결정서 등본을 심사를 신청한 검사에게 송달하여야 하며, 그 송달을 받은 검사는 이를 치료감호시설의 장이나 보호관찰관에게 통보한다. <개정 2014.1.28>', 7479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12916, '② 제1항에 따라 송달 또는 통보를 받은 치료감호시설의 장이나 보호관찰관은 그 내용을 피치료감호자에게 고지하여야 한다. <개정 2014.1.28>', 7479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12917, '③ 위원회는 법 제44조에 따른 피치료감호자와 그 법정대리인등의 신청에 대하여 결정을 한 때에는 그 결정서 등본을 피치료감호자와 그 법정대리인등에게 송달하여야 한다. <개정 2018.6.12>', 7479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12918, '① 위원회는 회의록을 작성ㆍ비치하여야 한다.', 7480);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12919, '② 회의록에는 회의와 관련된 모든 사항을 적고 위원장이 기명ㆍ날인하여야 한다.', 7480);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12920, '① 위원회의 위원장ㆍ위원ㆍ자문위원 및 직원에 대하여는 예산의 범위에서 출석수당과 여비를 지급할 수 있다. 다만, 공무원인 위원이 그 소관 업무와 직접적으로 관련되어 위원회에 출석하는 경우에는 그러하지 아니하다.', 7481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12921, '② 제1항의 수당 및 여비의 금액과 지급방법 및 그 밖에 필요한 사항은 법무부령으로 정한다.', 7481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12922, '① 보호관찰관은 법 제44조의6제1항에 따라 치료명령을 집행하기 전에 제26조에 따른 지휘 서면 및 판결문 등본을 모두 확인하여야 한다.', 7486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12923, '② 보호관찰관은 법 제44조의6제1항에 따라 치료명령을 집행하기 전에 피치료명령자에게 다음 각 호의 사항을 알려 주어야 한다.', 7486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12924, null, 7487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12925, '① 법 제44조의6제2항에 따른 인지행동 치료 등 심리치료 프로그램에는 다음 각 호의 내용이 포함되어야 한다.', 7488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12926, '② 법무부장관은 제1항에 따른 심리치료 프로그램의 개발에 노력하여야 한다.', 7488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12927, '① 법 제44조의6제1항에 따라 치료명령을 집행하는 보호관찰관은 피치료명령자와의 면담이나 법 제44조의7에 따른 치료기관 방문 등을 통하여 피치료명령자에 대한 치료명령 집행 상황을 확인하여야 한다.', 7489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12928, '② 법무부장관은 치료명령 집행업무를 전문적으로 수행할 수 있는 인력의 양성을 위하여 노력하여야 한다.', 7489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12929, null, 7490);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12930, '① 국가는 법 제44조의9제1항 단서에 따라 피치료명령자가 다음 각 호의 어느 하나에 해당하는 경우에는 치료비용을 부담할 수 있다.', 7491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12931, '② 피치료명령자는 제1항에 따른 치료비용의 국가부담을 신청하려는 경우에는 법무부령으로 정하는 신청서에 다음 각 호의 서류를 첨부하여 보호관찰소의 장에게 제출하여야 한다. 다만, 「국민기초생활 보장법」 제2조제2호에 따른 수급자인 피치료명령자는 신청서만 제출한다.', 7491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12932, '③ 보호관찰소의 장은 제2항에 따라 신청서를 제출받았을 때에는 신청인의 동의를 받아 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 다음 각 호의 행정정보를 확인하여야 한다. 다만, 신청인이 확인에 동의하지 아니하는 경우에는 그 서류를 첨부하게 하여야 한다. <개정 2018.6.12>', 7491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12933, '④ 보호관찰소의 장은 필요한 경우에는 신청인을 출석하게 하거나 신청인에게 필요한 자료를 제출하도록 요청할 수 있다.', 7491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12934, '⑤ 보호관찰소의 장은 국가, 지방자치단체 및 「공공기관의 운영에 관한 법률」 제4조에 따른 공공기관에 신청인의 치료비용 부담 능력을 확인하는 데 필요한 자료의 제출을 요청할 수 있다. 이 경우 법무부령으로 정하는 신청인의 동의서를 첨부하여야 한다.', 7491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12935, '⑥ 보호관찰소의 장은 제2항부터 제5항까지의 자료를 심사하여 신청인에 대한 치료비용의 국가부담을 결정한다.', 7491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12936, '⑦ 보호관찰소의 장은 제6항에 따라 치료비용을 국가가 부담하도록 결정한 경우에는 치료행위마다 예산의 범위에서 치료비용 전부를 지급해야 한다. 다만, 「국민건강보험법」, 「의료급여법」이나 그 밖의 다른 법령에서 신청인 또는 그 보호의무자(「정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률」 제39조에 따른 보호의무자를 말한다)가 부담하지 않도록 규정한 치료비용은 국가가 지급하는 비용에서 제외한다. <개정 2021.4.6>', 7491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12937, '⑧ 제1항부터 제7항까지에서 규정한 사항 외에 국가가 부담하는 치료비용의 구체적인 지급절차는 법무부장관이 정한다.', 7491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12938, '① 치료감호시설의 장은 법 제50조의2제1항에 따라 기부금품을 접수하는 경우 기부자에게 영수증을 발급하여야 한다. 다만, 익명으로 기부하거나 기부자를 알 수 없는 경우에는 영수증을 발급하지 아니할 수 있다.', 7493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12939, '② 치료감호시설의 장은 제1항에 따른 기부자가 다음 각 호의 어느 하나의 경우에 해당하는 사실을 알게 된 경우에는 기부금품을 접수해서는 아니 된다.', 7493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12940, '③ 치료감호시설의 장은 제1항에 따른 기부자가 기부금품의 용도를 지정한 경우에는 그 용도로만 사용하여야 한다. 다만, 기부자가 지정한 용도로 사용하기 어려운 경우에는 특별한 사정이 없는 한 기부자의 동의를 받아 다른 용도로 사용할 수 있다.', 7493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12941, '④ 치료감호시설의 장은 모든 기부금의 수입 및 지출을 기부금 전용계좌를 통하여 처리하여야 한다.', 7493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12942, '⑤ 치료감호시설의 장은 기부금품의 접수현황 및 사용실적 등에 관한 장부를 갖추어 두고 기부자가 열람할 수 있도록 하여야 한다.', 7493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12943, '⑥ 치료감호시설의 장은 매 반기별로 기부금품의 접수현황 및 사용실적 등에 관한 사항을 법무부장관에게 보고하여야 한다.', 7493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12944, '① 검사는 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법 시행령」 제18조제2호에 따른 범죄경력자료에 해당하는 정보, 같은 영 제19조제1호 또는 제4호에 따른 주민등록번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2014.1.28, 2016.11.29>', 7494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12945, '② 위원회는 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다.', 7494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12946, '③ 치료감호시설의 장은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보, 같은 영 제19조제1호 또는 제4호에 따른 주민등록번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2014.1.28, 2014.6.30, 2018.6.12>', 7494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12947, '④ 보호관찰소의 장은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제3항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <신설 2014.1.28, 2016.11.29, 2017.5.29>', 7494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12948, '⑤ 보호관찰관은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제3항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <개정 2014.1.28, 2016.11.29>', 7494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12949, '⑥ 치료감호시설의 장 또는 보호관찰관은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <개정 2014.1.28>', 7494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12950, '⑦ 정신건강복지센터의 장은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제3항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <신설 2014.1.28, 2016.11.29, 2017.5.29, 2018.6.12>', 7494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12951, '⑧ 법무부장관은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <신설 2014.8.6, 2016.11.29>', 7494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12952, null, 7496);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12953, '① 소년원장 또는 소년분류심사원장(이하 "원장"이라 한다)은 보호소년등을 처우할 때에 인권보호를 우선적으로 고려하여야 하며, 그들의 심신 발달 과정에 알맞은 환경을 조성하고 안정되고 규율있는 생활 속에서 보호소년등의 성장 가능성을 최대한으로 신장시킴으로써 사회적응력을 길러 건전한 청소년으로서 사회에 복귀할 수 있도록 하여야 한다. <개정 2013.7.30, 2020.10.20>', 7497);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12954, '② 보호소년에게는 품행의 개선과 진보의 정도에 따라 점차 향상된 처우를 하여야 한다.', 7497);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12955, '① 소년원은 보호소년을 수용하여 교정교육을 하는 것을 임무로 한다. <개정 2013.7.30, 2020.10.20>', 7498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12956, '② 소년분류심사원은 다음 각 호의 임무를 수행한다. <개정 2013.7.30, 2020.10.20>', 7498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12957, '①소년원과 소년분류심사원은 법무부장관이 관장한다.', 7499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12958, '② 소년원과 소년분류심사원의 명칭, 위치, 직제(職制), 그 밖에 필요한 사항은 대통령령으로 정한다.', 7499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12959, '①법무부장관은 보호소년의 처우상 필요하다고 인정하면 대통령령으로 정하는 바에 따라 소년원을 초ㆍ중등교육, 직업능력개발훈련, 의료재활 등 기능별로 분류하여 운영하게 할 수 있다. <개정 2013.7.30>', 7500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12960, '② 법무부장관은 제1항에 따라 의료재활 기능을 전문적으로 수행하는 소년원을 의료재활소년원으로 운영한다. <개정 2020.10.20>', 7500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12961, '① 신설하는 소년원 및 소년분류심사원은 수용정원이 150명 이내의 규모가 되도록 하여야 한다. 다만, 소년원 및 소년분류심사원의 기능ㆍ위치나 그 밖의 사정을 고려하여 그 규모를 증대할 수 있다.', 7501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12962, '② 보호소년등의 개별적 특성에 맞는 처우를 위하여 소년원 및 소년분류심사원에 두는 생활실은 대통령령으로 정하는 바에 따라 소규모로 구성하여야 한다.', 7501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12963, '③ 소년원 및 소년분류심사원의 생활실이나 그 밖의 수용생활을 위한 설비는 그 목적과 기능에 맞도록 설치되어야 한다.', 7501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12964, '④ 소년원 및 소년분류심사원의 생활실은 보호소년등의 건강한 생활과 성장을 위하여 적정한 수준의 공간과 채광ㆍ통풍ㆍ난방을 위한 시설이 갖추어져야 한다.', 7501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12965, '① 보호소년등을 소년원이나 소년분류심사원에 수용할 때에는 법원소년부의 결정서, 법무부장관의 이송허가서 또는 지방법원 판사의 유치허가장에 의하여야 한다. <개정 2016.3.29>', 7502);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12966, '② 원장은 새로 수용된 보호소년등에 대하여 지체 없이 건강진단과 위생에 필요한 조치를 하여야 한다.', 7502);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12967, '③ 원장은 새로 수용된 보호소년등의 보호자나 보호소년등이 지정하는 자(이하 "보호자등"이라 한다)에게 지체 없이 수용 사실을 알려야 한다.', 7502);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12968, '① 원장은 보호소년등의 정신적ㆍ신체적 상황 등 개별적 특성을 고려하여 생활실을 구분하는 등 적합한 처우를 하여야 한다. <개정 2016.3.29>', 7503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12969, '② 보호소년등은 다음 각 호의 기준에 따라 분리 수용한다. <개정 2016.3.29, 2018.9.18>', 7503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12970, '③ 「소년법」 제32조제1항제7호의 처분을 받은 보호소년은 의료재활소년원에 해당하는 소년원에 수용하여야 한다. <신설 2013.7.30, 2020.10.20>', 7503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12971, '④ 원장은 보호소년등이 희망하거나 특별히 보호소년등의 개별적 특성에 맞는 처우가 필요한 경우 보호소년등을 혼자 생활하게 할 수 있다. <신설 2020.10.20>', 7503);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12972, '① 소년원장은 보호소년이 다음 각 호의 어느 하나에 해당하는 경우에는 소년원 소재지를 관할하는 법원소년부에 「소년법」 제37조에 따른 보호처분의 변경을 신청할 수 있다.', 7505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12973, '② 소년분류심사원장은 위탁소년이 제1항 각 호의 어느 하나에 해당하는 경우에는 위탁 결정을 한 법원소년부에 「소년법」 제18조에 따른 임시조치의 취소, 변경 또는 연장에 관한 의견을 제시할 수 있다.', 7505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12974, '③ 소년분류심사원장은 유치소년이 제1항제1호 또는 제2호에 해당하는 경우에는 유치 허가를 한 지방법원 판사 또는 소년분류심사원 소재지를 관할하는 법원소년부에 유치 허가의 취소에 관한 의견을 제시할 수 있다.', 7505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12975, '④ 제3항에 따른 의견 제시 후 지방법원 판사 또는 법원소년부 판사의 유치 허가 취소 결정이 있으면 소년분류심사원장은 그 유치소년을 관할하는 보호관찰소장에게 이를 즉시 통보하여야 한다.', 7505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12976, '⑤ 제1항에 따른 보호처분의 변경을 할 경우 보호소년이 19세 이상인 경우에도 「소년법」 제2조 및 제38조제1항에도 불구하고 같은 법 제2장의 보호사건 규정을 적용한다.', 7505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12977, '①소년원장은 분류수용, 교정교육상의 필요, 그 밖의 이유로 보호소년을 다른 소년원으로 이송하는 것이 적당하다고 인정하면 법무부장관의 허가를 받아 이송할 수 있다. <개정 2013.7.30>', 7508);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12978, '② 「소년법」 제32조제1항제7호의 처분을 받은 보호소년은 의료재활소년원에 해당하지 아니하는 소년원으로 이송할 수 없다. <신설 2013.7.30, 2020.10.20>', 7508);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12979, '① 원장은 천재지변이나 그 밖의 재난 또는 비상사태에 대비하여 계획을 수립하고 보호소년등에게 대피훈련 등 필요한 훈련을 실시하여야 한다.', 7509);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12980, '② 원장은 천재지변이나 그 밖의 재난 또는 비상사태가 발생한 경우에 그 시설 내에서는 안전한 대피방법이 없다고 인정될 때에는 보호소년등을 일시적으로 적당한 장소로 긴급 이송할 수 있다.', 7509);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12981, '① 원장은 보호소년등이 이탈, 난동, 폭행, 자해(自害), 그 밖의 사고를 일으킬 우려가 있을 때에는 이를 방지하는 데에 필요한 조치를 하여야 한다.', 7510);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12982, '② 보호소년등이 소년원이나 소년분류심사원을 이탈하였을 때에는 그 소속 공무원이 재수용할 수 있다.', 7510);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12983, '① 보호장비의 종류는 다음 각 호와 같다. <개정 2013.7.30, 2016.3.29, 2020.10.20>', 7511);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12984, '② 원장은 다음 각 호의 어느 하나에 해당하는 경우에는 소속 공무원으로 하여금 보호소년등에 대하여 수갑, 포승 또는 보호대를 사용하게 할 수 있다. <개정 2013.7.30, 2020.10.20>', 7511);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12985, '③ 원장은 다음 각 호의 어느 하나에 해당하는 경우에는 소속 공무원으로 하여금 보호소년등에 대하여 수갑, 포승 또는 보호대 외에 가스총이나 전자충격기를 사용하게 할 수 있다. <신설 2013.7.30, 2016.3.29, 2020.10.20>', 7511);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12986, '④ 제3항에 따라 가스총이나 전자충격기를 사용하려면 사전에 상대방에게 이를 경고하여야 한다. 다만, 상황이 급박하여 경고할 시간적인 여유가 없는 때에는 그러하지 아니하다. <신설 2013.7.30>', 7511);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12987, '⑤ 원장은 보호소년등이 자해할 우려가 큰 경우에는 소속 공무원으로 하여금 보호소년등에게 머리보호장비를 사용하게 할 수 있다. <신설 2016.3.29>', 7511);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12988, '⑥ 보호장비는 필요한 최소한의 범위에서 사용하여야 하며, 보호장비를 사용할 필요가 없게 되었을 때에는 지체 없이 사용을 중지하여야 한다. <개정 2013.7.30, 2016.3.29>', 7511);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12989, '⑦ 보호장비는 징벌의 수단으로 사용되어서는 아니 된다. <신설 2013.7.30, 2016.3.29>', 7511);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12990, '⑧ 보호장비의 사용방법 및 관리에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2013.7.30, 2016.3.29>', 7511);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12991, '① 소년원 및 소년분류심사원에는 보호소년등의 이탈ㆍ난동ㆍ폭행ㆍ자해ㆍ자살, 그 밖에 보호소년등의 생명ㆍ신체를 해치거나 시설의 안전 또는 질서를 해치는 행위(이하 이 조에서 "자해등"이라 한다)를 방지하기 위하여 필요한 최소한의 범위에서 전자장비를 설치하여 운영할 수 있다. <개정 2016.3.29>', 7512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12992, '② 보호소년등이 사용하는 목욕탕, 세면실 및 화장실에 전자영상장비를 설치하여 운영하는 것은 자해등의 우려가 큰 때에만 할 수 있다. 이 경우 전자영상장비로 보호소년등을 감호할 때에는 여성인 보호소년등에 대해서는 여성인 소속 공무원만, 남성인 보호소년등에 대해서는 남성인 소속 공무원만이 참여하여야 한다. <개정 2016.3.29>', 7512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12993, '③ 제1항 및 제2항에 따라 전자장비를 설치ㆍ운영할 때에는 보호소년등의 인권이 침해되지 아니하도록 하여야 한다. <개정 2016.3.29>', 7512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12994, '④ 전자장비의 종류ㆍ설치장소ㆍ사용방법 및 녹화기록물의 관리 등에 필요한 사항은 법무부령으로 정한다. <개정 2016.3.29>', 7512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12995, null, 7513);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12996, '① 원장은 보호소년등이 제14조의4 각 호의 어느 하나에 해당하는 행위를 하면 제15조의2제1항에 따른 보호소년등처우ㆍ징계위원회의 의결에 따라 다음 각 호의 어느 하나에 해당하는 징계를 할 수 있다. <개정 2016.3.29, 2020.10.20>', 7514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12997, '② 제1항제3호부터 제6호까지의 처분은 함께 부과할 수 있다. <신설 2016.3.29>', 7514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12998, '③ 제1항제7호의 처분은 14세 미만의 보호소년등에게는 부과하지 못한다. <신설 2016.3.29>', 7514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (12999, '④ 원장은 제1항제7호의 처분을 받은 보호소년등에게 개별적인 체육활동 시간을 보장하여야 한다. 이 경우 매주 1회 이상 실외운동을 할 수 있도록 하여야 한다. <신설 2020.10.20>', 7514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13000, '⑤ 제1항제7호의 처분을 받은 보호소년등에게는 그 기간 중 같은 항 제4호부터 제6호까지의 처우 제한이 함께 부과된다. 다만, 원장은 보호소년등의 교화 또는 건전한 사회복귀를 위하여 특히 필요하다고 인정하면 텔레비전 시청, 단체 체육활동 또는 공동행사 참가를 허가할 수 있다. <신설 2016.3.29, 2020.10.20>', 7514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13001, '⑥ 소년원장은 보호소년이 제1항 각 호의 어느 하나에 해당하는 징계를 받은 경우에는 법무부령으로 정하는 기준에 따라 교정성적 점수를 빼야 한다. <개정 2016.3.29, 2020.10.20>', 7514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13002, '⑦ 징계는 당사자의 심신상황을 고려하여 교육적으로 하여야 한다. <개정 2016.3.29, 2020.10.20>', 7514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13003, '⑧ 원장은 보호소년등에게 제1항에 따라 징계를 한 경우에는 지체 없이 그 사실을 보호자에게 통지하여야 한다. <신설 2016.3.29, 2020.10.20>', 7514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13004, '⑨ 원장은 징계를 받은 보호소년등의 보호자와 상담을 할 수 있다. <신설 2016.3.29, 2020.10.20>', 7514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13005, '① 보호소년등의 처우에 관하여 원장의 자문에 응하게 하거나 징계대상자에 대한 징계를 심의ㆍ의결하기 위하여 소년원 및 소년분류심사원에 보호소년등처우ㆍ징계위원회를 둔다.', 7515);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13006, '② 제1항에 따른 보호소년등처우ㆍ징계위원회(이하 "위원회"라 한다)는 위원장을 포함한 5명 이상 11명 이하의 위원으로 구성하고, 민간위원은 1명 이상으로 한다.', 7515);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13007, '③ 위원회가 징계대상자에 대한 징계를 심의ㆍ의결하는 경우에는 1명 이상의 민간위원이 해당 심의ㆍ의결에 참여하여야 한다.', 7515);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13008, '④ 위원회는 소년보호에 관한 학식과 경험이 풍부한 외부인사로부터 의견을 들을 수 있다.', 7515);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13009, '⑤ 제1항부터 제4항까지에서 규정한 사항 외에 위원회의 구성과 운영 등에 필요한 사항은 대통령령으로 정한다.', 7515);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13010, '⑥ 위원회의 위원 중 공무원이 아닌 사람은 「형법」 제127조 및 제129조부터 제132조까지의 규정을 적용할 때에는 공무원으로 본다.', 7515);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13011, '① 원장은 교정성적이 우수하거나 품행이 타인의 모범이 되는 보호소년등에게 포상을 할 수 있다.', 7516);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13012, '② 원장은 제1항에 따라 포상을 받은 보호소년등에게는 특별한 처우를 할 수 있다.', 7516);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13013, '① 보호소년등에게는 의류, 침구, 학용품, 그 밖에 처우에 필요한 물품을 주거나 대여한다.', 7517);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13014, '② 보호소년등에게는 주식, 부식, 음료, 그 밖의 영양물을 제공하되, 그 양은 보호소년등이 건강을 유지하고 심신의 발육을 증진하는 데에 필요한 정도이어야 한다.', 7517);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13015, '③ 제1항 및 제2항에 따른 급여품과 대여품의 종류와 수량의 기준은 법무부령으로 정한다.', 7517);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13016, '① 원장은 비행집단과 교제하고 있다고 의심할 만한 상당한 이유가 있는 경우 등 보호소년등의 보호 및 교정교육에 지장이 있다고 인정되는 경우 외에는 보호소년등의 면회를 허가하여야 한다. 다만, 제15조제1항제7호의 징계를 받은 보호소년등에 대한 면회는 그 상대방이 변호인이나 보조인(이하 "변호인등"이라 한다) 또는 보호자인 경우에 한정하여 허가할 수 있다. <개정 2016.3.29>', 7518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13017, '② 보호소년등이 면회를 할 때에는 소속 공무원이 참석하여 보호소년등의 보호 및 교정교육에 지장이 없도록 지도할 수 있다. 이 경우 소속 공무원은 보호소년등의 보호 및 교정교육에 지장이 있다고 인정되는 경우에는 면회를 중지할 수 있다. <개정 2016.3.29>', 7518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13018, '③ 제2항 전단에도 불구하고 보호소년등이 변호인등과 면회를 할 때에는 소속 공무원이 참석하지 아니한다. 다만, 보이는 거리에서 보호소년등을 지켜볼 수 있다. <개정 2016.3.29>', 7518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13019, '④ 원장은 공동으로 비행을 저지른 관계에 있는 사람의 편지인 경우 등 보호소년등의 보호 및 교정교육에 지장이 있다고 인정되는 경우에는 보호소년등의 편지 왕래를 제한할 수 있으며, 편지의 내용을 검사할 수 있다. <개정 2016.3.29>', 7518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13020, '⑤ 제4항에도 불구하고 보호소년등이 변호인등과 주고받는 편지는 제한하거나 검사할 수 없다. 다만, 상대방이 변호인등임을 확인할 수 없는 때에는 예외로 한다. <개정 2016.3.29>', 7518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13021, '⑥ 원장은 공범 등 교정교육에 해가 된다고 인정되는 사람과의 전화통화를 제한하는 등 보호소년등의 보호 및 교정교육에 지장을 주지 아니하는 범위에서 가족 등과 전화통화를 허가할 수 있다. <신설 2013.7.30, 2016.3.29>', 7518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13022, '⑦ 제1항과 제2항에 따른 면회 허가의 제한과 면회 중지, 제4항에 따른 편지 왕래의 제한 및 제6항에 따른 전화통화의 제한 사유에 관한 구체적인 범위는 대통령령으로 정한다. <신설 2016.3.29>', 7518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13023, '⑧ 제6항에 따른 전화통화를 위하여 소년원 및 소년분류심사원에 설치하는 전화기의 운영에 필요한 사항은 법무부장관이 정한다. <신설 2016.3.29>', 7518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13024, null, 7519);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13025, '① 원장은 보호소년등이 질병에 걸리면 지체 없이 적정한 치료를 받도록 하여야 한다.', 7520);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13026, '② 원장은 소년원이나 소년분류심사원에서 제1항에 따른 치료를 하는 것이 곤란하다고 인정되면 외부 의료기관에서 치료를 받게 할 수 있다.', 7520);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13027, '③ 원장은 보호소년등이나 그 보호자등이 자비(自費)로 치료받기를 원할 때에는 이를 허가할 수 있다.', 7520);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13028, '④ 소년원 및 소년분류심사원에 근무하는 간호사는 「의료법」 제27조에도 불구하고 야간 또는 공휴일 등 의사가 진료할 수 없는 경우 대통령령으로 정하는 경미한 의료행위를 할 수 있다. <신설 2020.10.20>', 7520);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13029, '① 소년원 및 소년분류심사원에 근무하는 의사와 간호사는 보호소년등에 대한 진료기록부, 간호기록부, 그 밖의 진료에 관한 기록(이하 "진료기록부등"이라 한다)을 소년원과 소년분류심사원의 정보를 통합적으로 관리하기 위하여 법무부장관이 운영하는 정보시스템에 입력하여야 한다.', 7521);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13030, '② 법무부장관은 진료기록부등을 법무부령으로 정하는 바에 따라 보존하여야 한다.', 7521);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13031, '① 의료재활소년원장은 의료재활소년원 출원생(出院生)이 외래진료를 신청하는 경우 의료재활소년원에서 검사, 투약 등 적절한 진료 및 치료를 받도록 할 수 있다.', 7522);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13032, '② 법무부장관은 의료재활소년원 출원생이 신청하는 경우 「치료감호 등에 관한 법률」 제16조의2제1항제2호에 따른 법무부장관이 지정하는 기관에서 외래진료를 받도록 할 수 있다. 이 경우 법무부장관은 예산의 범위에서 진료비용을 지원할 수 있다.', 7522);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13033, '③ 제1항 및 제2항에 따른 외래진료의 기간과 방법 및 진료비용 지원 등에 필요한 사항은 법무부령으로 정한다.', 7522);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13034, '① 원장은 소년원이나 소년분류심사원에서 감염병이 발생하거나 발생할 우려가 있을 때에는 이에 대한 상당한 조치를 하여야 한다. <개정 2009.12.29>', 7523);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13035, '② 원장은 보호소년등이 감염병에 걸렸을 때에는 지체 없이 격리 수용하고 필요한 응급조치를 하여야 한다. <개정 2009.12.29>', 7523);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13036, '① 원장은 보호소년등이 갖고 있던 금전, 의류, 그 밖의 물품을 보관하는 경우에는 이를 안전하게 관리하고 보호소년등에게 수령증을 내주어야 한다.', 7524);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13037, '② 원장은 보호소년등의 퇴원, 임시퇴원, 사망, 이탈 등의 사유로 금품을 계속 보관할 필요가 없게 되었을 때에는 본인이나 보호자등에게 반환하여야 한다. <개정 2013.7.30>', 7524);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13038, '③ 제2항에 따라 반환되지 아니한 금품은 퇴원, 임시퇴원, 사망, 이탈 등의 사유가 발생한 날부터 1년 이내에 본인이나 보호자등이 반환 요청을 하지 아니하면 국고에 귀속하거나 폐기한다. <개정 2013.7.30>', 7524);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13039, '① 분류심사는 제3조제2항에 해당하는 소년의 신체, 성격, 소질, 환경, 학력 및 경력 등에 대한 조사를 통하여 비행 또는 범죄의 원인을 규명하여 심사대상인 소년의 처우에 관하여 최선의 지침을 제시함을 목적으로 한다. <개정 2020.10.20>', 7526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13040, '② 분류심사를 할 때에는 심리학ㆍ교육학ㆍ사회학ㆍ사회복지학ㆍ범죄학ㆍ의학 등의 전문적인 지식과 기술에 근거하여 보호소년등의 신체적ㆍ심리적ㆍ환경적 측면 등을 조사ㆍ판정하여야 한다.', 7526);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13041, '① 제3조제2항에 따른 임무를 수행하기 위하여 소년분류심사원에 분류심사관을 둔다. <개정 2020.10.20>', 7527);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13042, '② 분류심사관은 제24조제2항에 따른 학문적 소양과 전문지식을 갖추어야 한다.', 7527);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13043, '① 소년분류심사원장은 제3조제2항제1호부터 제4호까지의 규정에 따른 분류심사 또는 조사 결과와 의견 등을 각각 법원소년부 또는 검사에게 통지하여야 한다. <개정 2013.7.30, 2020.10.20>', 7529);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13044, '② 소년분류심사원장은 제3조제2항제1호부터 제3호까지에 규정된 소년이 보호처분의 결정을 받으면 그 소년의 분류심사 결과 및 의견 또는 상담조사 결과 및 의견을 지체 없이 그 처분을 집행하는 소년원이나 보호관찰소에서 정보시스템으로 열람할 수 있도록 통지하여야 한다. <개정 2013.7.30, 2020.10.20>', 7529);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13045, '③ 소년분류심사원장은 제3조제2항제5호에 따른 분류심사 또는 제26조에 따른 청소년심리검사 등을 하였을 때에는 그 결과를 각각 분류심사 또는 심리검사 등을 의뢰한 자에게 통지하고 필요한 의견을 제시할 수 있다. <개정 2013.7.30, 2020.10.20>', 7529);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13046, '① 소년원학교에 대하여는 「초ㆍ중등교육법」 제4조, 제10조, 제11조, 제18조, 제18조의2, 제30조의2, 제30조의3, 제31조, 제31조의2, 제32조부터 제34조까지, 제34조의2 및 제63조부터 제65조까지의 규정을 적용하지 아니한다. <개정 2013.7.30, 2016.3.29>', 7532);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13047, '② 소년원학교에 대하여 「초ㆍ중등교육법」 제6조부터 제9조까지의 규정을 적용할 때에는 "교육부장관"을 "법무부장관"으로 본다. <개정 2011.4.5, 2013.3.23>', 7532);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13048, '③ 교육부장관은 「교육기본법」 및 「초ㆍ중등교육법」에 관한 사항(제1항에 따라 적용이 배제되는 사항은 제외한다)에 대하여 법무부장관에게 필요한 권고를 할 수 있으며, 법무부장관은 정당한 사유를 제시하지 아니하는 한 이에 따라야 한다. <개정 2011.4.5, 2013.3.23>', 7532);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13049, '① 소년원학교에는 「초ㆍ중등교육법」 제21조제2항에 따른 자격을 갖춘 교원을 두되, 교원은 일반직공무원으로 임용할 수 있다.', 7534);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13050, '② 제1항에 따라 일반직공무원으로 임용된 교원의 경력ㆍ연수 및 직무 수행 등에 관하여 필요한 사항은 대통령령으로 정한다. 이 경우 「교육기본법」 및 「교육공무원법」에 따라 임용된 교원과 동등한 처우를 받도록 하여야 한다.', 7534);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13051, '③ 제1항과 제2항에도 불구하고 소년원학교의 교장(이하 "소년원학교장"이라 한다)은 소년원학교가 설치된 소년원의 장이, 교감은 그 소년원의 교육과정을 총괄하는 부서의 장으로서 대통령령으로 정하는 자가 겸직할 수 있다.', 7534);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13052, '④ 소년원학교장은 소년원학교의 교육과정을 원활하게 운영하기 위하여 필요하면 관할 교육청의 장에게 소년원학교 교사와 다른 중ㆍ고등학교 교사간 교환수업 등 상호 교류협력을 요청할 수 있다.', 7534);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13053, '① 보호소년이 소년원학교에 입교하면 「초ㆍ중등교육법」에 따라 입학ㆍ전학 또는 편입학한 것으로 본다.', 7535);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13054, '② 「초ㆍ중등교육법」 제2조의 학교에서 재학하던 중 소년분류심사원에 위탁되거나 유치된 소년 및 「소년법」 제32조제1항제8호의 처분을 받은 소년의 수용기간은 그 학교의 수업일수로 계산한다. <개정 2013.7.30>', 7535);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13055, '③ 소년원학교장은 보호소년이 입교하면 그 사실을 보호소년이 최종적으로 재학했던 학교[이하 "전적학교(前籍學校)"라 한다]의 장에게 통지하고 그 보호소년의 학적에 관한 자료를 보내줄 것을 요청할 수 있다.', 7535);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13056, '④ 제3항에 따른 요청을 받은 전적학교의 장은 교육의 계속성을 유지하는 데에 필요한 학적사항을 지체 없이 소년원학교장에게 보내야 한다.', 7535);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13057, '① 소년원학교에서 교육과정을 마친 보호소년이 전적학교의 졸업장 취득을 희망하는 경우 소년원학교장은 전적학교의 장에게 학적사항을 통지하고 졸업장의 발급을 요청할 수 있다.', 7538);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13058, '② 제1항에 따른 요청을 받은 전적학교의 장은 정당한 사유를 제시하지 아니하는 한 졸업장을 발급하여야 한다. 이 경우 그 보호소년에 관한 소년원학교의 학적사항은 전적학교의 학적사항으로 본다.', 7538);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13059, '① 소년원의 직업능력개발훈련은 「국민 평생 직업능력 개발법」으로 정하는 바에 따른다. <개정 2021.8.17>', 7539);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13060, '② 소년원장은 법무부장관의 허가를 받아 산업체의 기술지원이나 지원금으로 직업능력개발훈련을 실시하거나 소년원 외의 시설에서 직업능력개발훈련을 실시할 수 있다.', 7539);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13061, '③ 고용노동부장관은 보호소년의 직업능력개발훈련에 관하여 법무부장관에게 필요한 권고를 할 수 있다. <개정 2010.6.4>', 7539);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13062, '① 소년원장은 보호소년이 직업능력개발훈련과정을 마쳤을 때에는 산업체에 통근취업하게 할 수 있다.', 7541);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13063, '② 소년원장은 보호소년이 제1항에 따라 취업을 하였을 때에는 해당 산업체로 하여금 「근로기준법」을 지키게 하고, 보호소년에게 지급되는 보수는 전부 본인에게 지급하여야 한다.', 7541);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13064, '① 소년원장은 직업능력개발훈련을 실시할 때 보호소년에게 해롭거나 위험한 일을 하게 하여서는 아니 된다.', 7542);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13065, '② 소년원장은 직업능력개발훈련을 실시할 때 기계, 기구, 재료, 그 밖의 시설 등에 의하여 보호소년에게 위해가 발생할 우려가 있으면 이를 방지하는 데에 필요한 조치를 하여야 한다.', 7542);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13066, '① 소년원장은 보호소년의 연령, 학력, 적성, 진로, 교정의 난이도 등을 고려하여 처우과정을 정하고 교정목표를 조기에 달성할 수 있도록 교육계획을 수립ㆍ시행하여야 한다.', 7545);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13067, '② 소년원장은 제1항의 교육계획에 따른 교육과정을 운영하고 법무부장관이 정하는 바에 따라 그 결과를 평가하여 출원(出院), 포상 등 보호소년의 처우에 반영할 수 있다.', 7545);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13068, '① 소년원 및 소년분류심사원은 청소년 등에게 비행예방 및 재범방지 또는 사회적응을 위한 체험과 인성 위주의 교육을 실시하기 위하여 다음 각 호의 교육과정(이하 "대안교육과정"이라 한다)을 운영한다.', 7547);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13069, '② 원장은 행정기관, 지방자치단체, 학교, 그 밖의 단체 등과 협력하여 지역사회의 청소년 비행을 예방하기 위하여 적극 노력하여야 한다.', 7547);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13070, '③ 대안교육과정의 운영에 필요한 사항은 법무부령으로 정한다.', 7547);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13071, '① 소년원과 소년분류심사원은 「소년법」 제32조의2제3항에 따라 교육명령을 받은 보호자 또는 보호소년등의 보호자를 대상으로 역할개선 중심의 보호자교육과정을 운영한다.', 7548);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13072, '② 제1항에 따른 보호자교육의 절차 및 방법 등에 관하여 필요한 사항은 대통령령으로 정한다.', 7548);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13073, '① 소년원장은 보호소년이 22세가 되면 퇴원시켜야 한다.', 7549);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13074, '② 소년원장은 「소년법」 제32조제1항제8호 또는 같은 법 제33조제1항ㆍ제5항ㆍ제6항에 따라 수용상한기간에 도달한 보호소년은 즉시 퇴원시켜야 한다. <개정 2013.7.30>', 7549);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13075, '③ 소년원장은 교정성적이 양호하며 교정의 목적을 이루었다고 인정되는 보호소년(「소년법」 제32조제1항제8호에 따라 송치된 보호소년은 제외한다)에 대하여는 「보호관찰 등에 관한 법률」에 따른 보호관찰심사위원회에 퇴원을 신청하여야 한다. <개정 2016.3.29>', 7549);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13076, '④ 위탁소년 또는 유치소년의 소년분류심사원 퇴원은 법원소년부의 결정서에 의하여야 한다. <개정 2013.7.30>', 7549);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13077, '① 소년원장은 보호소년의 퇴원 또는 임시퇴원이 허가되면 지체 없이 보호자등에게 보호소년의 인도에 관하여 알려야 한다.', 7552);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13078, '② 소년원장은 퇴원 또는 임시퇴원이 허가된 보호소년을 보호자등에게 직접 인도하여야 한다. 다만, 보호소년의 보호자등이 없거나 제44조의2 본문에 따른 출원예정일부터 10일 이내에 보호자등이 인수하지 아니하면 사회복지단체, 독지가, 그 밖의 적당한 자에게 인도할 수 있다. <개정 2016.3.29>', 7552);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13079, '③ 제2항 단서에 따라 사회복지단체 등에 인도되기 전까지의 보호소년에 대해서는 제46조제1항에 따른 계속 수용에 준하여 처우한다. <신설 2016.3.29>', 7552);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13080, '① 원장은 출원하는 보호소년등의 성공적인 사회정착을 위하여 장학ㆍ원호ㆍ취업알선 등 필요한 지원을 할 수 있다. <개정 2016.3.29>', 7553);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13081, '② 제1항에 따른 사회정착지원(이하 이 조에서 "사회정착지원"이라 한다)의 기간은 6개월 이내로 하되, 6개월 이내의 범위에서 한 번에 한하여 그 기간을 연장할 수 있다. <개정 2016.3.29>', 7553);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13082, '③ 원장은 제51조에 따른 소년보호협회 및 제51조의2에 따른 소년보호위원에게 사회정착지원에 관한 협조를 요청할 수 있다. <개정 2016.3.29>', 7553);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13083, '④ 사회정착지원의 절차와 방법 등에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2016.3.29>', 7553);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13084, '① 퇴원 또는 임시퇴원이 허가된 보호소년이 질병에 걸리거나 본인의 편익을 위하여 필요하면 본인의 신청에 의하여 계속 수용할 수 있다.', 7554);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13085, '② 소년원장은 제1항에 따른 계속 수용의 사유가 소멸되면 지체 없이 보호소년을 보호자등에게 인도하여야 한다.', 7554);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13086, '③ 소년원장은 제1항에 따라 임시퇴원이 허가된 보호소년을 계속 수용할 때에는 그 사실을 보호관찰소장에게 통지하여야 한다.', 7554);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13087, '① 소년원장은 「보호관찰 등에 관한 법률」 제48조에 따라 임시퇴원이 취소된 자는 지체 없이 재수용하여야 한다.', 7556);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13088, '② 제1항에 따라 재수용된 자의 수용기간은 수용상한기간 중 남은 기간으로 한다.', 7556);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13089, '③ 제1항에 따라 재수용된 자는 새로 수용된 보호소년에 준하여 처우를 한다.', 7556);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13090, '① 보호소년등에 대한 지도, 학술연구, 그 밖의 사유로 소년원이나 소년분류심사원을 방문하려는 자는 그 대상 및 사유를 구체적으로 밝혀 원장의 허가를 받아야 한다.', 7557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13091, '② 소년원이나 소년분류심사원을 방문하지 아니하고 설문조사를 하려는 자는 미리 그 내용을 원장과 협의하여야 한다.', 7557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13092, '① 원장은 제3조에 따른 교정교육, 분류심사 또는 조사에 특히 필요하다고 인정하면 행정기관, 학교, 병원, 그 밖의 단체에 대하여 필요한 협조를 요청할 수 있다. <개정 2013.7.30, 2020.10.20>', 7558);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13093, '② 제1항의 요청을 거절할 때에는 정당한 이유를 제시하여야 한다.', 7558);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13094, '① 소년분류심사원장은 제26조에 따른 업무를 처리하기 위하여 청소년심리상담실을 설치ㆍ운영할 수 있다.', 7559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13095, '② 제1항에 따른 청소년심리상담실의 설치와 운영에 필요한 사항은 법무부령으로 정한다.', 7559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13096, '① 보호소년등을 선도하기 위하여 법무부장관 감독하에 소년 선도에 관하여 학식과 경험이 풍부한 인사로 구성되는 소년보호협회를 둘 수 있다.', 7560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13097, '② 소년보호협회의 설치, 조직, 그 밖의 운영에 필요한 사항은 대통령령으로 정한다.', 7560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13098, '③ 국가는 소년보호협회에 보조금을 지급할 수 있다.', 7560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13099, '④ 국가는 보호소년등의 교정교육과 사회복귀 지원 및 청소년 비행예방을 위하여 필요하다고 인정하는 경우에는 「국유재산법」에도 불구하고 소년보호협회에 소년원, 소년분류심사원 및 「보호관찰 등에 관한 법률」 제14조에 따른 보호관찰소의 시설, 그 밖에 대통령령으로 정하는 국유재산을 무상으로 대부하거나 사용허가할 수 있다. <신설 2010.5.4, 2016.3.29>', 7560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13100, '⑤ 제4항에 따라 국유재산을 무상으로 대부하거나 사용허가하는 경우 그 기간은 「국유재산법」 제35조제1항 또는 같은 법 제46조제1항에서 정하는 바에 따른다. <신설 2016.3.29>', 7560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13101, '⑥ 제5항의 대부기간 또는 사용허가기간이 끝난 국유재산에 대해서는 그 대부기간 또는 사용허가기간을 초과하지 아니하는 범위에서 종전의 대부계약 또는 사용허가를 갱신할 수 있다. <신설 2016.3.29>', 7560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13102, '⑦ 국가나 지방자치단체는 소년보호협회에 대하여 「조세특례제한법」 및 「지방세특례제한법」에서 정하는 바에 따라 국세 또는 지방세를 감면할 수 있다. <신설 2016.3.29>', 7560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13103, '① 보호소년등의 교육 및 사후지도를 지원하기 위하여 소년보호위원을 둘 수 있다.', 7561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13104, '② 소년보호위원은 명예직으로 하며, 법무부장관이 위촉한다.', 7561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13105, '③ 소년보호위원에게는 예산의 범위에서 직무수행에 필요한 비용의 전부 또는 일부를 지급할 수 있다. <신설 2013.7.30>', 7561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13106, '④ 소년보호위원의 위촉ㆍ해촉 및 자치조직 등에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2013.7.30>', 7561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13107, '① 원장은 기관ㆍ단체 또는 개인이 보호소년등에 대한 적절한 처우, 학업 지원 및 보호소년등의 사회 정착 등을 위하여 소년원이나 소년분류심사원에 자발적으로 기탁하는 금품을 접수할 수 있다.', 7563);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13108, '② 기부자에 대한 영수증 발급, 기부금품의 용도 지정, 장부의 열람, 그 밖에 필요한 사항은 대통령령으로 정한다.', 7563);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13109, '① 법무부장관은 제43조제1항 및 제2항에 따라 소년원에서 퇴원한 보호소년의 재범 여부를 조사하고 소년원 교정교육의 효과를 평가하기 위하여 보호소년이 같은 조 제1항 및 제2항에 따라 퇴원한 때부터 3년 동안 관계 기관에 그 소년에 관한 범죄경력자료와 수사경력자료에 대한 조회를 요청할 수 있다.', 7564);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13110, '② 제1항의 요청을 받은 관계 기관의 장은 정당한 사유 없이 이를 거부해서는 아니 된다.', 7564);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13111, null, 7566);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13112, '① 법 제5조에 따라 소년원을 다음 각 호와 같이 분류한다. <개정 2021.4.20, 2022.2.17>', 7567);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13113, '② 제1항에 따른 소년원의 세부분류ㆍ운영기준은 법무부장관이 정한다.', 7567);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13114, '①소년원장 또는 소년분류심사원장(이하 "원장"이라 한다)은 법 제7조 또는 법 제12조에 따라 보호소년등을 새로 수용할 때에는 법원소년부의 결정서, 법무부장관의 이송허가서 또는 지방법원 판사의 유치허가장을 통하여 본인임을 확인한 후 인수하고, 인도기관에 인수서를 내주어야 한다. <개정 2014.1.28, 2021.4.20>', 7571);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13115, '② 보호관찰소의 장은 유치소년을 원장에게 인도할 때에는 원본과 대조ㆍ확인한 유치허가장 사본을 제출하여야 한다. <신설 2014.1.28>', 7571);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13116, '① 원장은 법 제8조제1항에 따라 분류처우를 할 때에는 분류심사 결과와 법원소년부로부터 송부된 자료를 고려하여야 한다. <개정 2016.9.5>', 7574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13117, '② 원장은 법 제8조제2항에 따라 보호소년등을 분리수용하는 경우 비행, 공범관계, 처우과정 등을 고려하여 법무부령으로 정하는 바에 따라 생활실을 구분할 수 있다. <개정 2016.9.5>', 7574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13118, '① 소년원장은 제9조에 따른 분류처우 대상 보호소년에 대하여 법 제15조의2에 따른 보호소년등처우ㆍ징계위원회(이하 "처우ㆍ징계위원회"라 한다)의 심사를 거쳐 개별처우계획을 수립해야 한다. <개정 2021.4.20>', 7575);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13119, '② 제1항에 따른 개별처우계획에는 초ㆍ중등교육, 직업능력개발훈련, 의료재활, 인성교육 등 개별 교육ㆍ처우의 방향이 제시돼야 한다. 이 경우 보호소년과 보호자등의 의견을 고려해야 한다. <개정 2021.4.20>', 7575);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13120, '③ 제1항 및 제2항에 따라 수립된 개별처우계획은 교정교육에 지장이 없는 범위에서 그 내용을 본인 및 보호자등에게 알려 보호소년이 스스로 교육에 참여하고, 자기 개선을 위하여 노력하도록 하여야 한다.', 7575);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13121, '① 원장은 법 제11조에 따른 청원서를 접수하면 지체 없이 이를 법무부장관에게 보내야 한다.', 7578);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13122, '② 원장은 법 제11조에 따른 청원을 할 수 있다는 안내문을 보기 쉬운 곳에 게시하는 등 청원의 편의를 제공하여야 한다.', 7578);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13123, '③ 원장은 보호소년등이 청원을 못하게 하거나 청원을 하였다는 이유로 불이익한 처우를 하여서는 아니 된다.', 7578);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13124, '① 소년원장은 이송할 보호소년에 대하여 건강진단을 하고 건강상태가 이송해 갈 소년원의 교육활동에 적합하지 아니하다고 판명되면 이송을 중지하여야 한다.', 7581);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13125, '② 소년원장은 다음 각 호의 어느 하나에 해당하는 보호소년을 다른 소년원으로 이송해서는 안 된다. <개정 2021.1.5, 2021.4.20>', 7581);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13126, '③ 소년원장은 제2항에도 불구하고 처우상 특히 필요하다고 인정되는 사유가 있으면 처우ㆍ징계위원회의 심의를 거쳐 법무부장관의 허가를 받아 보호소년을 다른 소년원으로 이송할 수 있다. <개정 2021.4.20>', 7581);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13127, null, 7583);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13128, '① 원장은 시설의 안전과 질서 유지를 위하여 필요하다고 인정하는 경우에는 보호소년등의 신체ㆍ의류ㆍ휴대품ㆍ생활실 등을 검사할 수 있다.', 7584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13129, '② 원장은 보호소년등의 신체를 검사하는 경우에는 해당 보호소년등이 불필요한 고통이나 수치심을 느끼지 않도록 유의해야 하며, 특히 신체를 면밀히 검사할 필요가 있으면 다른 보호소년등이 볼 수 없는 차단된 장소에서 해야 한다. <개정 2021.4.20>', 7584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13130, '③ 원장은 여성인 보호소년등의 신체ㆍ의류 및 휴대품을 검사하는 경우에는 소속 여성 공무원이 하게 하여야 한다.', 7584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13131, '④ 원장은 제1항에 따라 검사한 결과 제17조의2에 따른 소지금지물품(이하 "금지물품"이라 한다)이 발견되면 이를 보호소년등에게 알린 후 폐기한다.', 7584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13132, '⑤ 제4항에도 불구하고 폐기하는 것이 적당하지 아니한 물품은 소년원등에 보관하거나 보호자등에게 전달할 수 있다. 이 경우 보관 물품의 처리는 법 제22조에 따른다. <개정 2021.4.20>', 7584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13133, '①원장은 소년원등에 출입하는 외부인의 출입 목적과 신원을 확인하고, 시설의 안전과 질서 유지를 위하여 필요하다고 인정하면 출입자의 의류와 휴대품을 검사할 수 있다. <개정 2014.1.28>', 7585);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13134, '② 원장은 제1항에 따른 검사 결과 출입자가 금지물품을 소지하고 있으면 소년원등에 맡기게 하여야 하며, 이에 따르지 아니하면 출입을 금지할 수 있다. <신설 2014.1.28>', 7585);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13135, '③ 원장은 여성 출입자의 의류 및 휴대품을 검사하는 경우에는 소속 여성 공무원이 하게 하여야 한다. <신설 2014.1.28>', 7585);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13136, '① 원장은 보호소년등이 다음 각 호의 어느 하나에 해당할 때에는 의사의 의견을 고려하여 심신안정실(자살 및 자해 방지 등의 설비를 갖춘 생활실을 말한다. 이하 같다)에 수용할 수 있다. <개정 2016.9.5>', 7586);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13137, '② 제1항제1호 및 제2호에 따른 심신안정실의 수용기간은 15일 이내로 한다. 다만, 원장은 특별히 계속하여 수용할 필요가 있으면 의사의 의견을 고려하여 7일을 초과하지 아니하는 범위에서 한 차례만 그 기간을 연장할 수 있다.', 7586);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13138, '③ 제1항제3호 및 제4호에 따른 심신안정실 수용기간은 24시간 이내로 한다. 다만, 원장은 특별히 계속하여 수용할 필요가 있으면 의사의 의견을 고려하여 12시간을 초과하지 아니하는 범위에서 한 차례만 그 기간을 연장할 수 있다.', 7586);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13139, '④ 원장은 보호소년등을 심신안정실에 수용하거나 그 수용기간을 연장하는 경우에는 그 사유를 본인에게 알려주어야 한다.', 7586);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13140, '⑤ 원장은 의사 및 간호사로 하여금 심신안정실에 수용된 보호소년등의 건강상태를 수시로 확인하게 하여야 한다.', 7586);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13141, '⑥ 원장은 심신안정실에 수용할 사유가 소멸하면 심신안정실 수용을 즉시 중단하여야 한다.', 7586);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13142, '① 원장은 보호소년등의 사망, 이탈, 난동, 그 밖의 중대한 사고가 발생하면 지체 없이 법무부장관에게 보고하여야 한다.', 7587);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13143, '② 원장은 조사ㆍ심리(審理)를 받고 있는 위탁소년 또는 항고 중의 보호소년이 사망하거나 이탈한 경우 또는 이탈한 보호소년등을 재수용한 경우에는 지체 없이 그 사실을 사건이 계류되어 있는 법원에 통지하여야 한다.', 7587);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13144, '① 원장은 법 제15조에 따라 보호소년등을 징계할 때에는 다음 각 호의 사항을 고려하여야 한다. <개정 2014.1.28>', 7592);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13145, '② 원장은 제1항에 따라 보호소년등을 징계할 때에는 증거에 의하여 징계 정도를 공정하게 정하고 교육적 효과를 고려하여야 한다.', 7592);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13146, '① 보호소년등의 징계대상행위에 대한 조사기간(조사를 시작한 날부터 조사를 완료하여 처우ㆍ징계위원회 개최 통보를 한 날까지를 말한다. 이하 같다)은 7일 이내로 한다. 다만, 원장은 특별히 필요하다고 인정하는 경우에는 3일을 초과하지 아니하는 범위에서 한 차례만 그 기간을 연장할 수 있다. <개정 2021.4.20>', 7593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13147, '② 원장은 규율을 위반하여 징계가 필요하다고 의심할 만한 상당한 이유가 있는 보호소년등이 다음 각 호의 어느 하나에 해당하면 조사기간 중 분리하여 수용할 수 있다.', 7593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13148, '③ 제2항에 따른 분리수용기간은 징계기간에 포함한다.', 7593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13149, '④ 원장은 조사대상자의 질병이나 그 밖의 특별한 사정으로 조사를 계속하기 어려운 경우에는 그 사유가 없어질 때까지 조사를 일시적으로 정지할 수 있다. 이 경우 조사가 정지된 다음 날부터 정지사유가 소멸한 전날까지의 기간은 조사기간에 포함하지 아니한다.', 7593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13150, '⑤ 제1항부터 제4항까지에서 규정한 사항 외에 징계대상행위 조사에 관한 세부 사항은 법무부령으로 정한다.', 7593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13151, '① 원장은 보호소년등을 징계할 때에는 지도계획을 수립하여 시행하여야 한다.', 7596);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13152, '② 원장은 징계 중인 보호소년등을 매주 1회 이상 면접하고 개별지도를 하여야 한다.', 7596);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13153, '③ 원장은 징계 중인 보호소년등의 처우를 제한하는 경우에는 그 사실을 그 보호소년등의 가족이나 친지에게 알려야 한다.', 7596);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13154, '④ 원장은 징계 중인 보호소년등에 대하여는 의사 및 간호사에게 수시로 건강진단을 하도록 하여야 한다.', 7596);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13155, null, 7600);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13156, '① 처우ㆍ징계위원회의 위원장(이하 "위원장"이라 한다)은 원장이 된다.', 7601);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13157, '② 처우ㆍ징계위원회의 위원(이하 "위원"이라 한다)은 다음 각 호에 해당하는 사람 중에서 위원장이 성별을 고려하여 임명하거나 위촉한다. 이 경우 의료재활소년원에 두는 처우ㆍ징계위원회의 위원에는 의무직공무원 및 간호직공무원이 포함돼야 한다.', 7601);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13158, '③ 「국가공무원법」 제33조 각 호에 해당하는 사람은 위원이 될 수 없다.', 7601);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13159, '④ 제2항에 따라 위촉된 위원의 임기는 2년으로 한다.', 7601);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13160, '① 위원이 다음 각 호의 어느 하나에 해당하는 경우에는 처우ㆍ징계위원회의 심의ㆍ의결에서 제척(除斥)된다.', 7602);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13161, '② 해당 안건의 당사자는 위원에게 공정한 심의ㆍ의결을 기대하기 어려운 사정이 있는 경우에는 처우ㆍ징계위원회에 기피 신청을 할 수 있고, 처우ㆍ징계위원회는 의결로 기피 여부를 결정한다. 이 경우 기피 신청의 대상인 위원은 그 의결에 참여할 수 없다.', 7602);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13162, '③ 위원이 제1항 각 호에 따른 제척사유나 제2항 전단에 따른 기피사유에 해당하는 경우에는 스스로 해당 안건의 심의ㆍ의결에서 회피해야 한다.', 7602);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13163, '① 위원장은 처우ㆍ징계위원회를 대표하고, 처우ㆍ징계위원회의 업무를 총괄한다.', 7603);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13164, '② 위원장이 부득이한 사유로 직무를 수행할 수 없을 경우에는 위원장이 미리 지정한 위원이 그 직무를 대행한다.', 7603);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13165, '① 위원장은 다음 각 호의 어느 하나에 해당하는 경우에 처우ㆍ징계위원회의 회의를 소집한다.', 7604);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13166, '② 처우ㆍ징계위원회의 회의는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.', 7604);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13167, '③ 처우ㆍ징계위원회의 회의에 출석한 위원과 관계 전문가 등에게는 예산의 범위에서 수당과 여비, 그 밖에 필요한 경비를 지급할 수 있다. 다만, 공무원이 그 소관 업무와 직접 관련하여 출석하는 경우에는 지급하지 않는다.', 7604);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13168, null, 7605);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13169, '① 처우ㆍ징계위원회의 사무를 처리하기 위해 처우ㆍ징계위원회에 2명 이내의 간사를 둔다.', 7606);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13170, '② 간사는 위원장이 해당 소년원등에 소속된 공무원 중에서 임명한다.', 7606);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13171, '① 간사는 처우ㆍ징계위원회의 회의록을 작성ㆍ보관해야 한다.', 7607);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13172, '② 제1항에 따른 회의록에는 위원장 및 출석위원이 서명 또는 날인해야 한다.', 7607);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13173, '① 원장은 법 제16조제1항에 따라 선정된 보호소년등에게는 상장ㆍ상품 등을 주거나 그 밖의 포상을 할 수 있다.', 7609);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13174, '② 원장은 제1항에 따라 포상을 받은 보호소년등에 대하여 제2조 각 호의 특별처우를 할 수 있다. <개정 2021.4.20>', 7609);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13175, '① 원장은 교정교육이나 위생에 해가 없다고 인정되는 경우에만 보호자나 그 밖의 관계인으로부터 음식물ㆍ의류ㆍ학용품 등을 반입하도록 허가할 수 있다.', 7611);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13176, '② 원장은 제1항에 따른 반입품이 유해한지를 검사하여야 한다.', 7611);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13177, '① 보호소년등의 면회는 평일[원장이 필요하다고 인정하는 경우에는 토요일(공휴일은 제외한다)을 포함한다]에 교육 등 일과 진행에 지장이 없는 범위에서 1일 1회 40분 이내로 한다. 다만, 특별한 사유가 있을 때에는 그렇지 않다. <개정 2014.1.28, 2021.4.20>', 7614);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13178, '② 제1항에 따른 면회의 장소ㆍ절차 등에 관하여 필요한 사항은 법무부령으로 정한다.', 7614);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13179, null, 7616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13180, '① 원장은 법 제18조제4항에 따라 편지를 검사한 결과 다음 각 호의 어느 하나에 해당하는 경우에는 편지의 왕래를 제한할 수 있다. <개정 2016.9.5>', 7617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13181, '② 제1항에 따른 편지 왕래의 제한은 다음 각 호의 어느 하나에 해당하는 방법으로 한다.', 7617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13182, '③ 정보통신매체를 통한 편지의 제한에 관하여는 제1항 및 제2항을 준용한다.', 7617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13183, '① 원장은 전화통화 허가를 신청한 보호소년등에게 다음 각 호의 어느 하나에 해당하는 사유가 있는 경우에는 전화통화를 허가하지 않을 수 있다. <개정 2021.4.20>', 7618);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13184, '② 원장은 다음 각 호의 어느 하나에 해당하는 경우에는 보호소년등의 전화통화를 중지시킬 수 있다.', 7618);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13185, '③ 제2항에 따라 보호소년등의 전화통화를 중지시키려면 미리 보호소년등에게 경고하여야 하며, 전화통화를 중지시킬 경우 통화상대방에게도 그 사유를 알려야 한다.', 7618);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13186, '① 소년원장은 외출허가를 받은 보호소년에게 지켜야 할 사항을 부과하여야 한다.', 7620);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13187, '② 소년원장은 보호소년이 준수사항을 위반하면 지체 없이 외출허가를 취소하고 복귀에 필요한 조치를 하여야 한다.', 7620);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13188, '① 원장은 제42조에 따른 건강진단이나 정기ㆍ수시검진 결과 중한 질병이 있다는 사실을 알았거나, 외부 의료기관에서 입원ㆍ수술 등의 처치를 받아야 할 사유가 발생하면 지체 없이 그 사실을 법무부장관에게 보고하고 보호자등에게 알려야 한다. <개정 2021.4.20>', 7622);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13189, '② 원장은 법 제20조제2항에 따라 보호소년등을 외부 의료기관에 입원시킨 경우에는 지체 없이 법무부장관에게 보고하여야 한다.', 7622);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13190, null, 7624);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13191, '① 원장은 보호소년등에 대한 예방접종과 방역소독 등 감염병 예방에 필요한 조치를 하여야 한다. <개정 2010.12.29>', 7625);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13192, '② 원장은 감염병이 유행하고 있을 때에는 감염병 유행지역 거주자의 면회, 음식물ㆍ피복이나 그 밖의 물품의 반입을 금지할 수 있다. <개정 2010.12.29>', 7625);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13193, '③ 원장은 보호소년등이 감염병에 감염되었다고 의심되는 경우에는 감염병의 증상 또는 전염력이 없어질 때까지 격리수용하고, 소지품에 대한 소독 등 필요한 조치를 하여야 한다. <개정 2010.12.29>', 7625);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13194, '① 원장은 법 제22조제1항에 따라 보호소년등의 금품을 보관할 때에는 본인이 참여한 가운데 점검하고, 법무부령으로 정하는 보관금품 보관증(이하 "보관증"으로 한다)에 품명ㆍ수량ㆍ규격과 그 밖에 필요한 사항을 기재한 후 본인이 확인ㆍ서명하게 하여야 한다. 이 경우 보관증은 원장과 보호소년등이 각각 한 부씩 보관한다. <개정 2016.9.5>', 7627);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13195, '② 제1항의 경우 보호소년등이 소지한 물품이 보관하기에 부적당하다고 인정되면 보호자등에게 반환하거나 본인의 승낙을 받아 매각하고 그 대금을 보관할 수 있다. 다만, 물품 중 가치가 없다고 인정되는 것은 본인이 폐기하게 할 수 있다.', 7627);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13196, '③ 원장은 필요하다고 인정하면 보관한 물품을 보호소년등이 사용하게 할 수 있다.', 7627);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13197, '① 법 제22조제2항에 따라 보관금품을 반환하는 때에는 보관증에 그 사유를 기재하고 수령인에게 확인ㆍ서명하도록 하여야 한다. <개정 2016.9.5>', 7628);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13198, '② 원장은 법 제22조제2항에도 불구하고 출원하는 보호소년등이 보관금품을 반환받기를 원하지 아니하면 반환하지 않을 수 있다.', 7628);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13199, '③ 제2항에 따라 보관금품을 반환하지 않을 때에는 보관증에 그 사유를 기재하고 해당 보호소년등에게 확인ㆍ서명하도록 하여야 한다. <개정 2016.9.5>', 7628);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13200, '① 원장은 소년원등에서 사용할 물품을 기증하려는 자가 있을 경우에는 보호와 교정교육에 필요한 물품만 기증받을 수 있다. <개정 2021.4.20>', 7629);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13201, '② 원장은 기증자가 제1항의 물품 기증을 목적으로 현금을 기탁하는 경우에는 이를 접수하여 해당 물품을 대신 구입할 수 있다. 이 경우 관련 증빙서류를 첨부하여 기증자에게 알려야 한다.', 7629);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13202, '① 법 제3조제2항제1호 및 제2호에 따른 분류심사를 할 때는 다음 각 호의 사항을 종합ㆍ분석해야 한다. <개정 2014.1.28, 2021.4.20>', 7631);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13203, '② 제1항에 따른 분류심사를 할 때에는 각종 기록 및 상담 결과, 관계인과의 면접, 그 밖의 객관적인 자료를 토대로 하여야 한다.', 7631);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13204, '① 법 제3조제2항제3호부터 제5호까지의 규정에 따른 상담조사, 검사의 결정 전 조사, 분류심사 업무를 할 때에는 의뢰기관이 요청한 영역에 대하여 실시한다. <개정 2014.1.28, 2021.4.20>', 7632);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13205, '② 법 제3조제2항제3호의 경우 소년의 진로지도 및 품행 개선을 위한 교육을 실시할 수 있다. 이 경우 상담조사 기간의 출석일수 인정 등에 관하여는 제85조를 준용한다. <개정 2014.1.28, 2021.4.20>', 7632);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13206, '① 분류심사관은 제51조에 따른 분류심사자료를 종합하여 분류심사서를 작성하여야 한다.', 7633);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13207, '② 소년분류심사원장은 분류심사관의 원활한 직무수행을 위하여 필요한 소양과 전문지식을 갖춘 분류심사 전문요원을 두고 제51조제1항 각 호의 자료수집과 심리검사 등을 하게 할 수 있다.', 7633);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13208, '① 법 제26조에 따라 심리검사 등을 요청하려는 사람은 소년분류심사원장에게 법무부장관이 정한 방법과 절차에 따라 심리검사를 의뢰하여야 한다.', 7634);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13209, '② 소년분류심사원장은 제1항에 따른 청소년 심리검사 등을 의뢰받았을 때에는 심리검사 등의 일시와 장소, 그 밖에 필요한 사항 등 협조사항을 미리 알려야 한다.', 7634);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13210, '① 소년원장은 보호소년이 정해진 교육기간에 교정목적을 달성할 수 있도록 법 제41조에 따른 교육계획을 수립하여 시행하여야 한다.', 7635);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13211, '② 제1항에 따른 교육계획에는 교육과정, 특별활동 및 생활지도 등에 관한 구체적 내용이 포함되어야 한다.', 7635);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13212, '① 교정교육은 보호소년이 소년원에 입원할 때부터 출원할 때까지의 전 과정을 신입자교육, 기본교육, 사회복귀교육의 3단계로 구분하여 순차적으로 실시해야 한다. <개정 2021.4.20>', 7636);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13213, '② 제1항에 따른 단계별 교육에 관한 세부사항은 법무부령으로 정한다.', 7636);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13214, '① 보호소년의 교정성적은 교육성과 및 생활성적을 종합하여 평가한다.', 7637);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13215, '② 그 밖에 보호소년의 교정성적 평가에 필요한 사항은 법무부장관이 정한다.', 7637);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13216, '① 원장은 보호소년등의 처우와 교정성적 관리를 적절하게 하기 위하여 개인별로 소년관리기록부를 갖추고 출원 시까지의 모든 상황을 정해진 양식에 따라 계속 기록ㆍ유지하여야 한다.', 7638);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13217, '② 소년분류심사원장은 위탁소년, 유치소년 또는 법 제3조제2항제3호에 따른 상담조사 대상 소년이 법원소년부의 심리 결과 소년원 송치처분을 받게 된 때에는 지체 없이 그 소년의 소년관리기록부 원본을 해당 소년원에 송부해야 한다. <개정 2014.1.28, 2021.4.20>', 7638);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13218, '① 법 제29조에 따른 소년원학교(이하 "소년원학교"라 한다)를 설치하는 경우에는 「초ㆍ중등교육법」에서 정하는 기준에 따라야 한다.', 7639);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13219, '② 소년원학교의 원활한 운영과 소년보호 교육기관의 특성을 고려하여 "소년원"과 "소년원의 각급학교 명칭"을 함께 사용할 수 있다.', 7639);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13220, '① 법 제30조제1항에 따라 임용된 소년원학교의 교원은 학생의 수업, 생활지도, 그 밖에 필요한 직무를 수행하여야 한다.', 7641);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13221, '② 소년원학교장은 소년원학교 교육을 원활하게 하기 위하여 필요하다고 판단되면 법무부장관의 승인을 받아 관련 학과 학사학위 이상 소지자, 청소년상담사, 청소년지도사, 정보통신ㆍ어학 관련 국가공인 자격 소지자 등 정해진 자격요건을 갖춘 소속 공무원에게 제1항에 따른 직무를 담당하도록 할 수 있다.', 7641);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13222, '① 법무부장관은 「교육공무원법」 및 「교원 등의 연수에 관한 규정」에서 정하는 바에 따라 소년원학교 교원을 각급학교의 교육연수원에서 연수하게 하거나 법무연수원에서 연수하게 해야 한다. <개정 2021.4.20>', 7642);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13223, '② 소년원학교장은 제1항에 따른 연수대상자를 선발하려면 관할 교육감 또는 법무연수원장과 협의해야 한다. <개정 2021.4.20>', 7642);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13224, '① 소년원학교장은 학년 초부터 60일 이내에 입교한 보호소년이 각급학교를 졸업하였거나 같은 수준 이상의 학력이 있다고 인정되는 경우에는 상급학교 교육과정에 입학시킬 수 있다.', 7643);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13225, '② 소년원학교장은 보호소년이 학적을 가졌던 학년의 입교 당시 학기에 전학ㆍ편입학시킬 수 있다. 다만, 입교 당시 학기에 전학ㆍ편입학 시킬 수 없을 경우에는 같은 학년 이하의 학기에 전학ㆍ편입학시킬 수 있다.', 7643);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13226, '③ 「소년법」 제32조제1항제8호에 따라 소년원에 송치된 소년에 대하여는 제1항 및 제2항을 적용하지 아니한다.', 7643);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13227, '① 소년원학교장은 법 제31조제1항에 따라 보호소년이 편입학한 경우에는 편입학사항을 보호소년이 최종적으로 재학하였던 학교[이하 "전적학교(前籍學校)"라 한다]의 장에게 통지하여야 한다.', 7646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13228, '② 소년원학교장은 보호소년의 학적기록사항을 매 학기 또는 매 학년이 종료되기 이전까지 전적학교의 장에게 보내야 한다.', 7646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13229, '③ 소년원학교장은 보호소년이 출원하면 그 출원일부터 10일 이내에 학적기록 전부를 전적학교의 장에게 보내야 한다.', 7646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13230, '④ 전적학교의 장은 제1항부터 제3항까지의 규정에 따라 학적사항을 접수하면 이를 재학생에 준하여 관리하여야 한다.', 7646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13231, '① 소년원장은 보호소년이 수용으로 인하여 학교 입학ㆍ복학 또는 편입학에 지장을 줄 염려가 있는 경우에는 보호소년에게 준수사항을 부과하여 통학하도록 할 수 있다.', 7648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13232, '② 소년원장은 제1항에 따라 통학을 허가받은 보호소년이 통학기간 중 준수사항을 현저하게 위반하거나 통학을 계속해서는 아니 된다고 판단되는 사유가 있으면 통학허가를 취소할 수 있다.', 7648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13233, '① 소년원학교의 학년별 과정 이수 및 졸업 여부는 처우ㆍ징계위원회에서 다음 각 호의 사항을 심의하여 결정한다. <개정 2021.4.20>', 7649);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13234, '② 제1항제2호에 따른 총 수업시간 수 또는 수업일수는 각 소년원학교별 수업시간수를 더하여 산정하되, 그 기간이 「초ㆍ중등교육법 시행령」 제50조제2항에 따른 기간을 넘으면 졸업요건을 충족한 것으로 본다.', 7649);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13235, null, 7651);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13236, '① 소년원의 직업능력개발훈련은 보호소년이 근로의 소중함을 깨닫고 직업에 대한 올바른 태도와 능력을 길러 건전한 직업생활을 할 수 있도록 하여야 한다.', 7653);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13237, '② 소년원의 직업능력개발훈련은 학교교육 및 산업사회와 밀접한 관련을 갖도록 실시하여야 한다.', 7653);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13238, '① 보호소년의 통근취업 대상 산업체는 소년원 출원 후 직업 선택이 쉽고 건전한 직업의식과 가치관을 기를 수 있는 업체로 선정해야 한다. <개정 2021.4.20>', 7658);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13239, '② 소년원장은 법 제37조제1항에 따라 보호소년을 통근취업시키려면 통근취업 대상 산업체와 보수, 취업기간, 취업조건, 그 밖에 필요한 사항을 포함하는 취업약정서를 작성하여야 한다.', 7658);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13240, '③ 소년원장은 통근취업을 하는 보호소년에게 준수사항을 부과하여 이를 지키도록 지도하여야 한다.', 7658);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13241, '④ 소년원장은 산업체가 제2항의 취업약정사항을 위반하였을 때 또는 보호소년이 준수사항을 현저하게 위반하거나 통근취업을 계속하여서는 아니 된다고 판단되는 사유가 있을 때에는 통근취업을 금지할 수 있다.', 7658);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13242, '① 원장은 보호소년등이 지닌 모든 문제와 그들의 욕구를 효과적으로 해소하여 교정목표를 조기에 달성할 수 있도록 체계적인 상담과 심리치료 등 인성교육을 하여야 한다.', 7661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13243, '② 원장은 보호자등이 보호소년등의 처우 또는 개인 사정에 관하여 상담을 신청하면 이에 응하여야 한다.', 7661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13244, '③ 원장은 제1항의 직무를 수행하기 위하여 해당 분야에 전문성과 소양을 갖춘 전담직원을 배치하거나 지정하여야 한다.', 7661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13245, '① 원장은 법 제40조에 따라 보호소년등의 정서를 순화하고 특기를 살리기 위하여 적당한 특별활동에 참여하게 하여야 한다.', 7662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13246, '② 제1항에 따른 특별활동은 체육, 독서, 음악, 연극지도 등 교내 특별활동과 전시관 및 산업시설 견학, 문화유적지 답사, 문화예술 공연 관람, 야영, 소풍 등 다양한 체험학습을 하는 교외 특별활동으로 한다.', 7662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13247, '① 원장은 교육과정 운영에 지장을 주지 않는 범위에서 종교를 가진 보호소년등에게 지정된 장소에서 자유롭게 종교의식에 참여하도록 하여야 한다.', 7664);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13248, '② 원장은 신부, 목사, 승려, 그 밖의 종교인에게 보호소년등에 대하여 종교에 관한 지도를 하도록 할 수 있다.', 7664);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13249, '① 원장은 교정교육에 필요한 도서실ㆍ상담실ㆍ방송실ㆍ심리검사실ㆍ교육자료실 및 종교실 등을 설치ㆍ운영할 수 있다.', 7665);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13250, '② 원장은 보호소년등이 제1항의 시설을 이용할 수 있도록 필요한 지원을 하여야 한다.', 7665);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13251, '① 법 제42조의2제1항에 따라 판사 또는 검사가 의뢰한 대안교육 대상 소년이 소년원등에서 정해진 교육과정을 이수했을 때에는 그 기간을 재적학교의 출석일수로 인정해야 한다. <개정 2021.4.20>', 7667);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13252, '② 원장은 법 제31조제2항에 따른 위탁소년이나 그 보호자 또는 제1항에 따른 대안교육 대상 소년이나 그 보호자가 원하는 경우에는 소년원등의 교육과정 이수사실이나 대안교육 이수사실을 소년의 재적학교의 장에게 통지할 수 있다. <개정 2021.4.20>', 7667);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13253, '① 원장은 법 제42조의3에 따라 보호자교육이 필요하다고 인정되면 교육목적과 대상, 시간 및 장소, 프로그램 등의 내용이 포함되는 교육계획을 수립ㆍ시행하여야 한다.', 7668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13254, '② 제1항에 따른 교육 프로그램에는 다음 각 호의 내용을 포함하여야 한다.', 7668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13255, null, 7670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13256, '① 「보호관찰 등에 관한 법률」 제48조에 따라 임시퇴원이 취소된 소년의 경우 임시퇴원 당시의 소년원장은 보호관찰관으로부터 그 소년을 인수하여 지체 없이 재수용하여야 한다.', 7671);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13257, '② 제1항에도 불구하고 임시퇴원 당시의 소년원과 임시퇴원 취소자(여성인 임시퇴원 취소자는 제외한다. 이하 이 항에서 같다)의 현재지(現在地)의 시ㆍ도가 달라 재수용이 지체될 우려가 있으면 임시퇴원 취소자의 현재지와 인접한 소년원에서 소년을 인수할 수 있다. <개정 2021.4.20>', 7671);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13258, '③ 제주지역을 현재지로 하여 임시퇴원이 취소된 사람은 제주소년원에 재수용한다. 다만, 임시퇴원 취소자의 주된 거주지와 제주소년원의 시ㆍ도가 다르면 청원이나 그 밖에 처우상 필요에 따라 임시퇴원 당시의 소년원에서 인수할 수 있다.', 7671);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13259, '① 원장은 법 제50조에 따라 보호소년등의 교정교육과 분류심사를 위하여 필요한 경우에는 다음 각 호의 자료를 해당 기관에 요청할 수 있다.', 7673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13260, '② 직무상 제1항의 자료조회를 요청하는 사람 또는 이를 취급하는 사람은 그 내용을 직무와 직접 관련되지 아니하는 사람에게 누설하여서는 아니 된다.', 7673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13261, '① 원장은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보 및 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2016.9.5, 2021.4.20>', 7674);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13262, '② 원장은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법 시행령」 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <개정 2014.6.30, 2020.3.3>', 7674);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13263, '① 협회의 정관에는 다음 각 호의 사항이 포함되어야 한다.', 7676);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13264, '② 협회는 정관을 변경할 때에는 이사회의 의결을 거쳐 법무부장관의 허가를 받아야 한다.', 7676);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13265, '① 협회에는 다음 각 호의 임원을 둔다.', 7677);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13266, '② 이사장은 법무부장관이 임명하고, 이사장 및 상임이사를 제외한 이사 중 1명은 법무부 소속 공무원 중에서 법무부장관이 지명하며, 이사장과 법무부장관이 지명한 이사(이하 "당연직이사"라 한다)를 제외한 임원은 이사회에서 선임하되, 법무부장관의 승인을 받아 취임한다.', 7677);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13267, '③ 이사장 및 감사의 임기는 2년으로 하고, 당연직이사를 제외한 이사의 임기는 3년으로 한다.', 7677);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13268, '④ 당연직이사를 제외한 임원은 법무부장관의 승인을 받아 연임할 수 있다. 다만, 임원의 재임(在任)기간은 이사장의 경우 6년을 초과할 수 없고, 이사의 경우 이사장 임기를 포함하여 10년을 초과할 수 없다.', 7677);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13269, '① 이사장은 협회를 대표하고 협회의 업무를 총괄한다.', 7678);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13270, '② 이사장은 이사회를 소집하며, 이사회의 의장이 된다.', 7678);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13271, '③ 이사장이 부득이한 사유로 직무를 수행할 수 없을 때에는 상임이사가 이사장의 직무를 대행한다.', 7678);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13272, '④ 이사는 이사회에 출석하여 협회의 중요 사항을 심의ㆍ의결하며, 이사회 또는 이사장으로부터 위임받은 업무를 처리한다.', 7678);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13273, '⑤ 감사는 협회의 업무 및 회계를 감사한다.', 7678);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13274, '① 협회의 업무에 관한 주요 사항을 심의ㆍ의결하기 위하여 협회에 이사장과 이사로 구성된 이사회를 둔다.', 7679);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13275, '② 감사는 이사회에 출석하여 의견을 진술할 수 있다.', 7679);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13276, null, 7681);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13277, '① 협회는 그 설립목적을 달성하기 위하여 다음 각 호의 목적사업을 한다. <개정 2016.9.5>', 7682);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13278, '② 협회는 그 설립목적을 달성하기 위하여 수익사업을 할 수 있다.', 7682);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13279, '③ 협회는 제2항의 수익사업을 하려는 경우에는 사업마다 미리 법무부장관의 승인을 받아야 한다. 이를 변경하려는 경우에도 또한 같다.', 7682);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13280, '① 협회의 회계연도는 정부의 회계연도에 따른다.', 7683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13281, '② 협회는 매 회계연도 개시 전까지 해당 회계연도에 수행할 사업계획 및 예산안을 작성하여 이사회의 의결을 거친 후 법무부장관에게 제출하여 승인을 받아야 한다. 이를 변경할 때에도 또한 같다.', 7683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13282, '③ 협회는 매 회계연도의 사업실적과 결산서를 작성하여 이사회의 의결을 거친 후 다음 회계연도 2월 말일까지 법무부장관에게 제출하여야 한다.', 7683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13283, '④ 협회는 국고보조금의 집행결과를 분기마다 법무부장관에게 보고하여야 한다.', 7683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13284, '① 법무부장관은 협회를 지휘ㆍ감독한다.', 7684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13285, '② 법무부장관은 협회에 대하여 감독상 필요한 경우에는 그 업무에 관한 사항을 보고하게 하거나 자료의 제출, 그 밖에 필요한 명령을 할 수 있으며, 소속 공무원에게 협회 운영 실태를 조사하게 할 수 있다.', 7684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13286, '③ 법무부장관은 협회의 국고보조금 집행에 관하여 감사를 할 수 있다.', 7684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13287, '① 원장은 법 제53조제1항에 따라 기부금품을 접수하는 경우 기부자에게 영수증을 발급하여야 한다. 다만, 익명으로 기부하거나 기부자를 알 수 없는 경우에는 영수증을 발급하지 아니할 수 있다.', 7686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13288, '② 원장은 제1항에 따른 기부자가 다음 각 호의 어느 하나의 경우에 해당하는 사실을 알게 된 경우에는 기부금품을 접수해서는 아니 된다.', 7686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13289, '③ 원장은 제1항에 따른 기부자가 기부금품의 용도를 지정한 경우에는 그 용도로만 사용하여야 한다. 다만, 기부자가 지정한 용도로 사용하기 어려운 경우에는 특별한 사정이 없는 한 기부자의 동의를 받아 다른 용도로 사용할 수 있다.', 7686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13290, '④ 원장은 모든 기부금의 수입 및 지출을 기부금 전용계좌를 통하여 처리하여야 한다.', 7686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13291, '⑤ 원장은 기부금품의 접수현황 및 사용실적 등에 관한 장부를 갖추어 두고 기부자가 열람할 수 있도록 하여야 한다.', 7686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13292, '⑥ 원장은 매 반기별로 기부금품의 접수현황 및 사용실적 등에 관한 사항을 법무부장관에게 보고하여야 한다.', 7686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13293, '① 법무부장관이 법 제54조에 따라 범죄경력자료와 수사경력자료의 조회를 요청하는 경우 「형의 실효 등에 관한 법률」 제6조제1항에 따라 소년원에서 퇴원한 보호소년의 재범 여부를 조사하고 소년원 교정교육의 효과를 평가하기 위해 필요한 최소한의 범위에서 요청해야 한다.', 7687);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13294, '② 범죄경력자료 또는 수사경력자료를 관리하는 사람이나 직무상 범죄경력자료 또는 수사경력자료를 조회하거나 열람한 사람은 그 내용을 누설해서는 안 된다.', 7687);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13295, '③ 제1항 및 제2항에서 규정한 사항 외에 범죄경력자료와 수사경력자료의 조회 요청 방법, 자료 관리 등에 필요한 세부사항은 법무부장관이 정한다.', 7687);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13296, '① 「보호소년 등의 처우에 관한 법률 시행령」(이하 "영"이라 한다) 제6조에 따른 인수서는 별지 제1호서식에 따른다. <개정 2021.4.20>', 7696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13297, '② 소년원장 또는 소년분류심사원장(이하 "원장"이라 한다)은 보호소년등이 영 제6조에 따라 새로 수용된 때에는 지체 없이 다음 각 호에 따른 검사ㆍ조사 또는 조치 등을 하고, 이상이 발견되었을 경우에는 필요한 조치를 마련하여야 한다. <개정 2016.9.29, 2021.4.20>', 7696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13298, '③ 여성인 보호소년등에 대한 제2항제1호ㆍ제3호 및 제4호의 검사 또는 조치는 여성인 직원이 실시해야 한다. 다만, 제2항제3호에 따른 검사는 여성인 직원이 참석한 가운데 의사나 간호사가 실시할 수 있다. <개정 2021.4.20>', 7696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13299, null, 7699);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13300, '① 소년원장은 법 제9조제1항에 따라 「소년법」 제32조제1항제7호부터 제10호까지의 보호처분을 받아 수용된 보호소년이 소년원을 이탈한 후 재수용되었을 때에는 법원소년부에 같은 항 제7호부터 제10호까지의 보호처분으로 변경을 신청할 수 있다. <개정 2021.4.20>', 7704);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13301, '② 소년원장은 「소년법」 제32조제1항제5호 처분과 제8호 처분이 병합되어 소년원에 수용된 보호소년이 소년원을 이탈하였을 때에는 그 보호소년을 관할하는 보호관찰소에 즉시 통보하여야 한다.', 7704);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13302, '③ 소년원장은 보호소년이 소년원을 이탈하거나 소년원을 이탈한 후 범법행위로 인하여 징역 또는 금고 이상의 유죄판결이 확정된 경우 또는 보호처분에 따라 소년원에 다시 송치된 경우에는 해당 보호소년에 대한 종전의 보호처분을 취소할 것을 법원소년부에 신청하여야 한다.', 7704);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13303, '① 원장은 영 제13조에 따른 청원의 편의를 위하여 보호소년등이 이용하기 편리한 곳에 청원함을 설치하고, 매일 청원사항을 확인하여야 한다.', 7705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13304, '② 청원에 대한 결정은 문서로 하여야 하며, 그 결정서는 지체 없이 청원인에게 전달하여야 한다.', 7705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13305, '③ 원장은 별지 제3호서식의 청원처리부를 갖추고, 청원의 처리경위 등을 기록ㆍ유지하여야 한다.', 7705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13306, '① 신입보호소년의 이송은 보호처분에 대한 항고제기기간이 지난 후 지체 없이 실시하여야 한다. 다만, 보호소년 및 보호소년의 보호자가 항고제기의사가 없음을 밝히고, 별지 제4호서식의 항고권포기 서약서를 작성하여 제출한 경우에는 항고제기기간이 지나기 전이라도 이송할 수 있다.', 7707);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13307, '② 소년원장은 법 제12조에 따라 보호소년을 다른 소년원으로 이송하려면 이송할 보호소년의 인적사항, 이송사유, 그 밖에 필요한 사항을 구체적으로 제시하여 법무부장관에게 이송허가를 신청해야 한다. <개정 2021.4.20>', 7707);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13308, '③ 소년원장은 제1항에 따라 이송허가를 받아 보호소년을 다른 소년원에 이송할 때에는 그 보호소년의 소년관리기록부ㆍ보관금품 및 별지 제12호서식에 따른 보관금품 보관증(기관 보관용을 말한다) 그 밖의 참고자료를 인수소년원에 인계하여야 한다. <개정 2016.9.29>', 7707);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13309, '① 소년원장은 보호소년이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 보호소년을 의료재활소년원으로 이송하도록 허가해 줄 것을 법무부장관에게 신청할 수 있다. <개정 2021.4.20>', 7709);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13310, '② 제1항에 따른 이송허가의 구체적인 기준은 법무부장관이 정한다.', 7709);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13311, '① 소년원장은 의료재활소년원으로의 이송을 신청할 때에는 별지 제5호서식에 따른 소속 의무과장의 진료소견서를 첨부해야 한다. <개정 2016.9.29, 2021.4.20>', 7710);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13312, '② 보호소년을 의료재활소년원으로 이송하는 경우 인계기관은 해당 보호소년의 의무ㆍ진료와 관련된 모든 자료의 원본 또는 출력물을 인수기관으로 보내고 그 사본을 보관해야 한다. <개정 2021.4.20>', 7710);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13313, '③ 의료재활소년원장은 보호소년이 개별처우계획에 따른 의료재활과정을 마쳤을 때에는 해당 보호소년을 처우하기에 적합한 소년원을 정하여 법무부장관에게 이송을 신청해야 한다. 이 경우 처우ㆍ징계위원회의 심사를 거쳐야 한다. <개정 2021.4.20>', 7710);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13314, '④ 제1항부터 제3항까지에서 규정한 사항 외에 의료재활소년원으로의 이송절차 등에 관한 구체적인 사항은 법무부장관이 정한다. <신설 2016.9.29, 2021.4.20>', 7710);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13315, '① 원장은 보호소년등의 특성ㆍ인원ㆍ감호환경 그 밖에 사고방지를 위한 모든 여건을 고려하여 감호직원을 배치하여야 한다.', 7712);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13316, '② 제1항에 따라 감호의 임무를 부여받은 사람은 보호소년등을 방치하거나 감호 중에 무단이석ㆍ음주ㆍ독서ㆍ잡무처리 등 감호 외의 용무를 보아서는 아니된다.', 7712);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13317, '① 수갑의 사용방법은 다음 각 호와 같다. 이 경우 수갑은 손목에만 채워야 하며, 주요 동맥이나 정맥을 압박하여 피가 통하지 않도록 해서는 안 된다.', 7713);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13318, '② 포승의 사용방법은 다음 각 호와 같이 하되, 주요 동맥이나 정맥을 압박하여 피가 통하지 않도록 해서는 안 된다. 다만, 제1호부터 제4호까지의 규정에도 불구하고 원장은 영 제2조제2호에 따른 향상된 처우를 하는 경우로서 보호소년등이 이탈할 위험성이 크지 않다고 판단되는 경우에는 포승을 사용하지 않을 수 있다.', 7713);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13319, '③ 가스총의 사용방법은 다음 각 호와 같다.', 7713);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13320, '④ 전자충격기의 사용방법은 다음 각 호와 같다.', 7713);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13321, '⑤ 머리보호장비는 별표 1의10의 방법으로 사용한다. 이 경우 보호소년등이 머리보호장비를 임의로 해제하지 못하도록 수갑이나 포승을 함께 사용할 수 있다.', 7713);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13322, '⑥ 보호대는 보호대에 부착된 고리에 수갑을 연결하여 별표 1의11의 방법으로 사용한다.', 7713);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13323, '⑦ 법 제14조의2제1항에 따른 보호장비를 사용하려면 미리 원장의 허가를 받아야 한다. 다만, 긴급한 경우에는 사용 후 즉시 원장에게 보고해야 한다.', 7713);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13324, '⑧ 제1항부터 제7항까지의 규정에서 정한 사항 외에 그 밖에 보호장비의 사용방법 등에 관한 세부 사항은 법무부장관이 정한다.', 7713);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13325, '① 원장은 보호장비의 관리책임을 지며, 월 1회 이상 소속기관의 보호장비 사용실태를 확인ㆍ점검하여야 한다. <개정 2014.1.29>', 7714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13326, '② 보호장비는 항상 사용가능한 상태를 유지하여야 하며, 보관은 별도의 캐비넷에 하여야 한다. <개정 2014.1.29>', 7714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13327, '③ 보호장비를 사용할 때에는 별지 제34호서식의 보호장비 사용 기록부에 기록ㆍ관리한다. <개정 2014.1.29>', 7714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13328, '④ 유효기간이 지난 가스총의 탄환 및 분사약재 등은 폐기해야 한다. <신설 2021.4.20>', 7714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13329, '⑤ 제1항부터 제4항까지의 규정에서 정한 사항 외에 보호장비의 관리 등에 관한 세부 사항은 법무부장관이 정한다. <신설 2016.9.29, 2021.4.20>', 7714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13330, null, 7715);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13331, '① 원장은 전자장비의 효율적인 운용을 위하여 각종 전자장비를 통합적으로 관리할 수 있는 시스템이 설치된 통제실을 설치하여 운영한다.', 7716);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13332, '② 원장은 통제실에 대한 외부인의 출입을 제한하여야 한다. 다만, 시찰ㆍ참관이나 그 밖에 원장이 특별히 필요하다고 인정하는 경우에는 외부인의 출입을 허가할 수 있다.', 7716);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13333, '① 영상정보처리기기 중 카메라는 소년원등의 청사 정문ㆍ운동장, 외곽 담장, 생활관 내 복도, 각 생활실, 생활지도실, 그 밖에 보호소년등의 감호에 필요한 장소로서 법무부장관이 정하는 장소에 설치한다. <개정 2021.4.20>', 7717);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13334, '② 영상정보처리기기 중 모니터는 상황실ㆍ생활지도실, 그 밖에 소년원등의 소속 공무원(이하 제24조의10까지에서 "소속공무원"이라 한다)이 보호소년등을 감호하기에 적정한 장소로서 법무부장관이 정하는 장소에 설치한다. <개정 2021.4.20>', 7717);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13335, '③ 제1항 및 제2항에서 규정한 사항 외에 영상정보처리기기의 운영ㆍ관리 등에 관한 세부 사항은 법무부장관이 정한다.', 7717);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13336, '① 고정식 물품검색기는 정문, 생활관 입구, 교육관 입구, 그 밖에 보호소년등이나 소년원등에 출입하는 외부인에 대한 신체ㆍ의류ㆍ휴대품의 검사가 필요한 장소에 설치한다. <개정 2021.4.20>', 7720);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13337, '② 소속공무원이 영 제17조의3제1항에 따라 보호소년등의 신체ㆍ의류ㆍ휴대품을 검사하는 경우에는 특별한 사정이 없으면 고정식 물품검색기를 통과하게 한 후 휴대식 금속탐지기나 손으로 이를 확인한다.', 7720);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13338, '③ 소속공무원이 영 제18조제1항에 따라 소년원등을 출입하는 외부인의 의류와 휴대품을 검사하는 경우에는 고정식 물품검색기를 통과하게 하거나 휴대식 금속탐지기로 이를 확인한다. <개정 2021.4.20>', 7720);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13339, '① 원장은 보호소년등의 인원ㆍ소지품ㆍ이용시설 그 밖에 필요한 사항을 수시로 점검하고 보호소년등이 허가없이 외부인과 접촉하는 것을 금지하여야 한다.', 7723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13340, '② 원장은 보호소년등이 외출하거나 생활관을 출입할 때에는 반드시 소지품검사를 하여 부정물품반입을 예방하여야 한다.', 7723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13341, '③ 원장은 수시로 생활실 등 각종 시설의 이상유무, 부정물품의 은닉여부 그 밖에 필요한 사항을 점검하여야 한다.', 7723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13342, null, 7726);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13343, '① 원장은 규율을 위반한 보호소년등을 징계할 때에는 별표 2의 보호소년등의 징계기준에 따라야 한다. <개정 2021.4.20>', 7727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13344, '② 삭제 <2014.1.29>', 7727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13345, '③ 소년원장은 제1항에 따른 징계를 받은 보호소년에 대하여 각각 다음 각 호에 따른 점수를 해당 보호소년의 교정성적에서 뺀다. <개정 2014.1.29, 2016.9.29>', 7727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13346, '④ 보호소년에 대하여 법 제15조제2항에 따라 여러 처분을 함께 부과하는 경우에는 제3항 각 호에 따른 점수가 가장 높은 처분의 점수만을 해당 보호소년의 교정성적에서 뺀다. <신설 2016.9.29>', 7727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13347, '⑤ 소년분류심사원장은 징계를 받은 위탁소년 및 유치소년에 대하여는 분류심사관에게 통보하여 분류심사에 반영하여야 한다. <개정 2014.1.29, 2016.9.29>', 7727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13348, null, 7728);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13349, '① 원장은 별표 3의 분기별 반입품 허가기준에 따라 자체실정에 맞는 반입기준을 정하여 물품의 반입을 허가할 수 있다. 다만, 다음 각 호의 어느 하나에 해당한다고 인정되는 물품에 대하여는 반입을 허가하지 아니한다.', 7732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13350, '② 반입품은 별지 제8호서식의 개인별 반입품관리부에 기록ㆍ관리하여야 한다.', 7732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13351, '① 법 제18조제1항에 따른 보호소년등의 면회는 면회실에서 하여야 한다.', 7733);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13352, '② 면회실에는 상담직원을 배치하고 다음 각 호의 사항을 구비하여 면회인의 편의를 도모하며 수시로 의견을 청취하여 민원개선에 노력하여야 한다.', 7733);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13353, '③ 원장은 제1항에도 불구하고 특별한 사유가 있으면 면회인과 보호소년등이 보다 안정된 분위기 속에서 면회를 할 수 있도록 별도의 장소를 활용할 수 있다.', 7733);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13354, '① 원장은 면회를 신청하는 사람의 성명ㆍ주소 및 보호소년등과의 관계 등을 확인하고 면회허가여부를 결정하여야 한다.', 7734);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13355, '② 원장은 면회를 신청하는 사람이 해당 사건의 변호인 또는 수사관련 공무원인 경우에는 신분 및 면회신청사유 등을 확인한 후 면회를 허가하여야 한다.', 7734);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13356, null, 7736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13357, '① 원장은 법 제18조제6항에 따른 전화통화를 할 수 있는 별도의 장소를 지정하여야 한다.', 7737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13358, '② 전화통화는 평일 근무시간에 한정한다. 다만, 원장은 특별히 필요하다고 인정하는 경우에는 야간 및 휴일에도 전화통화를 허가할 수 있다.', 7737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13359, '③ 제1항 및 제2항에서 규정한 사항 외에 전화통화의 신청 및 기록 등에 관한 세부 사항은 법무부장관이 정한다.', 7737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13360, '① 보호소년이 법 제19조에 따른 외출을 허가받으려면 별지 제10호서식의 외출신청서를 작성하여 해당 소년원장에게 제출하여야 한다.', 7738);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13361, '② 보호소년 또는 그 보호자가 영 제40조 단서에 따라 외출을 연장하려면 외출기간이 종료되기 전에 별지 제10호서식에 따른 외출기간연장신청서를 제출하고 소년원장의 허가를 받아야 한다. <개정 2012.8.2>', 7738);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13362, '① 영 제41조제1항에 따른 준수사항에는 다음 각 호의 내용이 포함되어야 한다.', 7740);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13363, '② 소년원장은 보호소년의 자유를 부당하게 제한하지 아니하는 범위에서 제1항에 따른 준수사항 외에 별도의 특별한 준수사항을 부과할 수 있다.', 7740);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13364, '③ 영 제66조 및 영 제76조에 따른 통학 또는 통근취업 대상자에 대하여는 제1항 및 제2항의 규정을 준용한다.', 7740);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13365, '① 원장은 보호소년등의 보건ㆍ위생관리를 위한 종합대책과 세부생활지도계획을 분기별로 수립ㆍ시행하여야 한다.', 7741);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13366, '② 원장은 제9조제2항제3호에 따른 신체검사 등을 통하여 문신이 있는지 확인하고 해당 보호소년등이 문신제거 시술을 원하는 경우에는 신청에 의하여 문신제거 시술을 할 수 있다.', 7741);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13367, '① 원장은 보호소년등의 보건위생을 위하여 보호소년등의 신체ㆍ의류ㆍ거실ㆍ침구ㆍ식기ㆍ취사장ㆍ화장실 그 밖의 생활환경을 청결히 하도록 하여야 한다.', 7742);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13368, '② 원장은 제1항에 따른 생활환경의 청결유지상태를 월 1회 이상 점검하여야 한다.', 7742);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13369, '① 영 제42조에 따른 정기검진은 분기별로 1회 이상 실시하되, 「학교건강검사규칙」 제4조 및 제5조에 따른 신체검사 및 건강검진이 연 1회 이상 포함되어야 한다.', 7744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13370, '② 영 제3조제1항제1호에 따른 초ㆍ중등교육소년원(이하 "소년원학교"라 한다)의 원장(이하 "소년원학교장"이라 한다)은 보호소년을 대상으로 연 1회 이상 체력검사를 실시하고 그 결과를 기록ㆍ유지해야 한다. <개정 2021.4.20>', 7744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13371, '③ 제2항에 따른 체력검사의 대상ㆍ종목ㆍ시기ㆍ방법ㆍ급수판정 및 관리 등에 관하여는 「학교건강검사규칙」 제7조부터 제9조까지의 규정을 준용한다.', 7744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13372, '① 소년원등의 소속 의료인은 보호소년등의 치료를 위하여 보호소년등을 진료한 의료인 또는 의료기관의 장에게 「의료법」 제22조 또는 제23조에 따른 진료기록의 내용 확인이나 진료기록의 사본 및 환자의 진료경과에 대한 소견 등을 송부하거나 전송할 것을 요청하는 경우에는 같은 법 제21조의2제1항에 따라 해당 보호소년이나 그 보호자의 동의를 받아야 한다.', 7747);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13373, '② 소년원등의 소속 의료인은 의료재활소년원 출원생이 외래진료를 받은 법 제20조의3제2항 전단에 따라 법무부장관이 지정하는 기관(이하 "지정법무병원"이라 한다)의 의료인 또는 의료기관의 장으로부터 「의료법」 제21조의2에 따라 요청받은 같은 법 제22조 또는 제23조에 따른 진료기록의 내용 확인이나 진료기록의 사본 및 환자의 진료경과에 대한 소견 등을 송부 또는 전송하려는 경우에는 해당 출원생이나 그 보호자의 동의를 받아야 한다.', 7747);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13374, '① 법 제20조의3제1항 및 제2항에 따른 외래진료기간은 의료재활소년원 출원일부터 10년의 범위로 한다.', 7748);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13375, '② 법 제20조의3제1항 및 제2항에 따른 외래진료의 방법은 영 제3조제1항제3호의 약물 오ㆍ남용 및 정신장애에 대한 의료재활을 위하여 필요한 정신건강의학과 의사의 진료, 검사시설에 의한 검사, 처방 및 투약 등으로 한다.', 7748);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13376, '① 법무부장관은 법 제20조의3제2항 전단에 따라 의료재활소년원 출원생이 지정법무병원에서 외래진료를 받도록 한 경우에는 같은 항 후단에 따라 예산의 범위에서 지정법무병원에 외래진료 진료비용(「국민건강보험법」, 「의료급여법」, 그 밖의 다른 법령에 따라 의료재활소년원 출원생 또는 보호자등이 부담하지 않는 비용은 제외한다)을 지급한다.', 7749);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13377, '② 제1항에 따라 외래진료 진료비용을 지급받으려는 지정법무병원의 장은 별지 제11호서식의 외래진료 진료비용 지급 청구서에 의료재활소년원 출원생별 진료비 계산서를 첨부하여 「치료감호 등에 관한 법률 시행령」 제4조의5제2항에 따른 제출기간에 법무부장관에게 제출해야 한다.', 7749);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13378, '① 법 제3조제2항 각 호에 따른 분류심사, 상담조사 및 검사의 결정 전 조사(이하 "분류심사등"이라 한다)는 면접조사, 심리검사, 정신의학적 진단, 행동관찰, 자기기록 검토, 자료조회, 현지조사 등의 방법에 따른다. <개정 2021.4.20>', 7753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13379, '② 분류심사는 다음 각 호와 같이 구분한다.', 7753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13380, '③ 분류심사의 실시기준은 별표 4와 같다.', 7753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13381, '① 면접조사는 다음 각 호의 구분에 따른 방법으로 하여야 한다. <개정 2010.12.13, 2021.4.20>', 7754);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13382, '② 분류심사관은 면접대상자가 심리적 안정감을 가질 수 있도록 친절하게 대하고 용모ㆍ태도ㆍ언어 등에 유의하여야 한다.', 7754);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13383, '① 소년에 대한 행동관찰은 객관적이고 신뢰성있게 하고 그 결과가 분류심사등에 유용하도록 제공되어야 한다.', 7755);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13384, '② 소년분류심사원장은 행동관찰 업무를 적정하게 하기 위하여 담당직원의 교육, 부서간의 협조 독려 그 밖에 필요한 조치를 하여야 한다.', 7755);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13385, '① 소년분류심사원장은 법 제25조제2항에 따라 다음 각 호의 어느 하나에 해당하는 사람 중에서 분류심사관을 임명하여야 한다. <개정 2011.4.5, 2022.12.19>', 7756);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13386, '② 소년분류심사원장은 각종 전문교육, 관련 학회 등에 분류심사관의 참여를 적극 권장하는 등 분류심사관의 자질향상을 위하여 노력하여야 한다. <개정 2010.12.13>', 7756);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13387, '③ 소년분류심사원장은 분류심사에 필요한 각종 검사기구의 구비, 전문성 증진을 위한 연구개발지원 등 분류심사의 과학화를 위하여 노력하여야 한다. <개정 2010.12.13>', 7756);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13388, '① 소년원장은 신입보호소년에 대하여 생활규범지도, 기초교육, 적응훈련 그 밖에 필요한 지도를 함으로써 신입보호소년이 소년원에 신속히 적응하고 심신의 안정을 도모할 수 있도록 하여야 한다.', 7758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13389, '② 제1항에 따른 신입자교육기간은 10일 이내로 한다.', 7758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13390, '① 소년원장은 보호소년이 제54조에 따른 기본교육과정을 마치고 퇴원 또는 임시퇴원의 요건을 갖춘 때에는 사회적응에 필요한 진로상담, 장래의 생활설계에 대한 지도, 퇴원 또는 임시퇴원 후의 준수사항에 대한 교육 그 밖에 사회복귀에 필요한 교육을 실시한다.', 7760);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13391, '② 소년원장은 제1항에 따른 보호소년에게 퇴원이나 임시퇴원 후에도 자립생활관 이용, 취업알선 및 창업보육 등의 사회정착지원을 받을 수 있음을 알려 주어야 한다. <개정 2016.9.29, 2021.4.20>', 7760);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13392, '③ 제1항에 따른 사회복귀교육기간은 10일 이내로 한다.', 7760);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13393, '① 영 제58조제1항에 따른 소년관리기록부에는 다음 각 호의 자료가 포함되어야 한다. <개정 2014.1.29, 2021.4.20>', 7764);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13394, '② 원장은 보호소년등을 다른 기관으로 이송할 때에는 영 제64조에 따른 학교생활기록부와 함께 소년관리기록부를 송부하여야 한다.', 7764);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13395, '① 소년원학교장은 학칙을 제정하거나 개정할 때에는 법무부장관의 승인을 받아야 한다.', 7765);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13396, '② 제1항에 따른 학칙에는 다음 각 호의 사항이 포함되어야 한다.', 7765);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13397, null, 7766);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13398, '① 영 제67조에 따라 졸업대상자로 결정된 보호소년에 대하여는 별지 제18호서식의 졸업대장에 기록하고, 별지 제19호서식의 졸업증서를 발급한다.', 7770);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13399, '② 법 제34조제1항에 따라 전적학교(前籍學校)의 졸업장 취득을 위해 학적사항을 통지하는 방법 및 절차 등에 관하여는 제64조를 준용한다. <개정 2021.4.20>', 7770);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13400, '③ 제1항에 따른 졸업장 및 법 제34조에 따른 전적학교의 졸업장은 가능하면 보호소년이 모두 모인 장소에서 소년원학교장이 본인에게 직접 수여해야 한다. <개정 2021.4.20>', 7770);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13401, '① 소년원장은 필요하다고 판단되는 경우 「근로자직업능력 개발법」에서 고용노동부장관이 정한 직업능력개발훈련기준에 따라 직업능력개발훈련 직종을 신설 또는 폐지할 수 있다. 이 경우 지방고용노동관서의 장과 협의를 거쳐 법무부장관의 승인을 받아야 한다. <개정 2014.1.29>', 7772);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13402, '② 소년원장은 제1항에 따라 직업능력개발훈련 직종을 신설하거나 폐지하는 경우에는 산업계의 인력수요를 조사ㆍ파악하여 이를 적절히 반영하여야 한다.', 7772);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13403, '③ 제1항에 따라 신설되는 직종의 수업일수, 교과편성 그 밖에 필요한 사항은 법무부장관의 승인을 받아 소년원장이 정한다.', 7772);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13404, '① 직업능력개발훈련을 받을 수 있는 보호소년은 15세 이상으로 한다.', 7773);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13405, '② 소년원장은 훈련직종 또는 훈련과정에 따라 보호소년의 연령 또는 학력의 기준을 따로 정할 수 있다.', 7773);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13406, '① 소년원장은 법 제37조제1항에 따라 통근취업을 하는 보호소년의 원만한 적응과 교통편의 등을 위하여 예산의 범위에서 통근취업 기간 중의 교통비 전액 또는 일부를 지원할 수 있다.', 7774);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13407, '② 소년원장은 보호소년의 통근취업으로 발생한 보수 등에 관하여는 영 제47조의 규정을 준용하여 관리하여야 한다.', 7774);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13408, '③ 영 제76조제2항에 따른 통근취업약정서는 별지 제24호서식에 따른다.', 7774);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13409, '① 원장은 보호소년등의 심신이 조화롭게 성장ㆍ발달할 수 있도록 일과를 진행하여야 한다.', 7775);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13410, '② 원장은 보호소년등이 8시간 이상 취침할 수 있도록 하여야 한다. 다만, 수업시간 수 확보 등 교육과정의 운영상 불가피한 경우에는 그러하지 아니하다.', 7775);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13411, '③ 원장은 교정교육상 특히 필요한 경우를 제외하고는 보호소년등의 정서함양을 위하여 공휴일에는 직원의 지도로 보호소년등이 다양한 여가선용프로그램에 참여하거나 휴식할 수 있도록 하여야 한다.', 7775);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13412, '④ 국경일 및 스승의 날, 성년의 날 등 교육적으로 필요하다고 인정되는 기념일에는 경축ㆍ기념의식 또는 관련 교육행사를 가질 수 있다. <개정 2014.1.29>', 7775);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13413, '① 소년원장은 보호소년이 자발적으로 교육목표를 달성할 수 있도록 자치회를 조직하여 운영하게 할 수 있다.', 7777);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13414, '② 제1항에 따른 자치회는 소년원의 관리ㆍ규율ㆍ설비ㆍ급양(給養)ㆍ의료 및 위생에 관한 업무에 관여할 수 없다. 다만, 소년원장 또는 직원이 함께 참석하여 자치회를 개최하는 경우에는 관련 의견을 제시할 수 있다. <개정 2022.2.7>', 7777);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13415, '③ 제1항에 따른 자치회의 대표자와 임원의 임면, 자치회의 조직 및 운영에 관하여 필요한 사항은 소년원장이 정한다.', 7777);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13416, '① 원장은 법 제42조의2에 따른 대안교육과정의 운영을 위한 계획을 수립하여 시행하여야 한다.', 7778);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13417, '② 제1항에 따른 대안교육과정운영계획에는 다음 각 호의 내용이 포함되어야 한다. 다만, 교육기간 및 대상에 따라 이를 달리 수립ㆍ시행할 수 있다. <개정 2014.1.29>', 7778);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13418, '③ 원장은 대안교육대상자와 보호소년등을 분리하여 관리하여야 한다.', 7778);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13419, '① 원장은 교정교육의 효과를 높이기 위하여 필요하다고 인정되는 경우에는 관계직원으로 하여금 보호자상담을 실시하게 할 수 있다.', 7779);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13420, '② 관계직원이 제1항에 따른 보호자상담을 실시하려는 때에는 지정된 장소에서 실시하고 별지 제25호서식의 보호자상담부에 상담내용을 기록ㆍ유지하여야 한다.', 7779);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13421, '③ 영 제86조제1항에 따른 보호자교육의 대상자를 선정하는 때에는 제1항에 따른 보호자상담 결과를 고려하여야 한다.', 7779);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13422, '① 소년원장이 법 제43조제3항 및 제44조에 따라 관할 보호관찰심사위원회에 보호소년의 출원심사를 신청하는 경우에는 처우ㆍ징계위원회의 심사를 거쳐 퇴원, 임시퇴원 여부를 구분하여 신청해야 한다. <개정 2021.4.20>', 7780);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13423, '②제1항에 따른 보호소년의 출원에 관한 처우ㆍ징계위원회의 심사를 할 때에는 보호소년의 생활태도, 교정성적, 사회적응 정도 및 보호자의 보호력 등을 종합적으로 고려해야 한다. <개정 2021.4.20>', 7780);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13424, '③그 밖에 보호소년의 출원에 관한 처우ㆍ징계위원회의 심사 및 보호관찰심사위원회로의 심사 신청에 관한 사항은 법무부장관이 따로 정한다. <개정 2021.4.20>', 7780);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13425, null, 7781);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13426, null, 7782);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13427, '① 소년원장은 보호소년이 임시퇴원하는 경우에는 보호관찰의 실효성을 높이기 위하여 지체 없이 임시퇴원자에 관한 분류심사서 사본 및 별지 제26호서식의 교육ㆍ생활지도부 등을 해당 보호관찰소에 송부하여야 한다. <개정 2014.1.29>', 7783);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13428, '② 소년원장은 법 제46조제1항에 따른 계속수용의 사유가 소멸하여 보호소년을 보호자등에게 인도할 때에는 보호소년과 보호자등에게 지체 없이 관할보호관찰소에 출석ㆍ신고할 것을 고지하고 보호관찰소장에게 출원사실을 통보하여야 한다.', 7783);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13429, '① 소년원장은 퇴원 또는 임시퇴원이 허가된 보호소년에 대하여 수료식을 실시하고 별지 제27호서식에 따른 퇴원증 또는 별지 제28호서식에 따른 임시퇴원증을 내주어야 한다.', 7784);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13430, '② 소년원장은 임시퇴원자에 대하여 보호관찰기간 중의 준수사항을 이행하도록 교육하고 신고기일 이내에 관할보호관찰소에 출석하여 신고할 것을 알려주어야 한다.', 7784);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13431, '① 법 제45조제1항에 따른 보호소년의 인도에 관한 통지는 별지 제29호서식에 따른다.', 7785);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13432, '② 소년원장은 법 제45조제2항에 따라 보호소년을 보호자, 사회복지단체 또는 독지가 등에게 인도할 때에는 별지 제30호서식의 보호자인도부에 그 사실을 기록ㆍ유지하여야 한다.', 7785);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13433, '① 원장은 법 제45조의2에 따른 사회정착지원에 관한 계획을 수립ㆍ시행하여야 한다. <개정 2016.9.29>', 7786);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13434, '② 제1항에 따른 계획은 취업ㆍ진학 등 보호소년등의 진로를 고려하여 수립하되, 이 계획에는 방문ㆍ출석ㆍ통신지도 등 사회정착지원 방법과 기간ㆍ횟수 등의 구체적인 내용이 포함되어야 한다. <개정 2016.9.29>', 7786);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13435, '③ 원장은 제1항에 따른 계획을 수립하기 전에 보호소년등으로부터 사회정착지원을 희망하는 구체적인 분야 등을 청취한 후 이를 계획에 반영하여야 한다. <개정 2016.9.29>', 7786);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13436, '④ 원장은 법 제45조의2제2항에 따라 사회정착지원 기간을 연장하려는 경우에는 보호소년등의 재범 여부, 취업ㆍ진학 여부, 주거 안정 여부, 그 밖에 사회정착지원의 필요성 등을 고려하여 판단하여야 한다. <개정 2016.9.29>', 7786);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13437, '⑤ 원장은 보호소년등이 무의탁소년인 경우에는 법 제51조에 따른 소년보호협회가 영 제98조에 따라 운영하는 자립지원시설의 이용지원, 취업알선, 그 밖에 필요한 사회정착지원을 하여야 한다. <개정 2016.9.29>', 7786);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13438, '① 법 제46조제1항에 따른 보호소년의 계속수용은 다음 각 호의 어느 하나에 해당하는 사유로 해당 보호소년과 보호자등이 희망하는 경우에 한정한다.', 7789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13439, '② 보호소년과 보호자등이 제1항에 따른 사유로 계속수용을 희망할 때에는 퇴원일 또는 임시퇴원일을 기준으로 7일 전까지 별지 제32호서식의 계속수용신청서를 소년원장에게 제출해야 한다. <개정 2021.4.20>', 7789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13440, '③ 소년원장은 제2항에 따른 계속수용신청서를 접수받은 경우에는 처우ㆍ징계위원회의 심의를 거쳐 계속수용을 허용할 수 있다. 이 경우 해당 보호소년에게 계속수용 중의 준수사항을 지시할 수 있다. <개정 2021.4.20>', 7789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13441, '④ 계속수용기간은 다음 각 호와 같다. 이 경우 보호소년의 의사를 존중하여야 한다.', 7789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13442, '⑤ 계속수용의 교육과정은 특별한 프로그램이 마련된 경우를 제외하고는 퇴원 또는 임시퇴원허가 이전의 기본교육과정으로 분류하여야 한다.', 7789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13443, '⑥ 법 제46조제3항에 따른 보호소년의 계속수용사실의 통지는 별지 제33호서식에 따른다.', 7789);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13444, '① 영 제88조제2항에 따라 임시퇴원취소자의 신병을 인수한 소년원장은 지체 없이 임시퇴원 당시의 해당 소년원장에게 신병인수 사실을 알리고, 가정ㆍ학교ㆍ사회환경 및 임시퇴원 기간 중의 생활상태를 종합심사하기 위한 처우ㆍ징계위원회의 심사를 거쳐 자체수용 또는 이송여부를 결정해야 한다. <개정 2021.4.20>', 7790);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13445, '② 제1항에 따라 임시퇴원취소자를 자체수용하기로 결정한 때에는 지체 없이 임시퇴원 당시의 해당 소년원장에게 그 사실을 알리고, 개별처우계획의 수립에 필요한 자료의 제출을 요구할 수 있다.', 7790);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13446, '③ 제1항에 따라 이송을 결정한 때에는 지체 없이 임시퇴원취소자의 신병을 임시퇴원 당시의 소년원에 이송하여야 한다.', 7790);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13447, '① 소년원장은 임시퇴원된 보호소년이 영 제88조에 따라 임시퇴원이 취소되어 재수용된 때에는 제53조에 따른 신입자교육을 실시하고, 처우ㆍ징계위원회의 심사를 거쳐 개별처우계획을 새로 수립해야 한다. 다만, 재수용된 보호소년의 잔여 수용기간이 40일 미만인 경우에는 처우ㆍ징계위원회의 심사를 생략하고 임시퇴원 당시의 과정에 편성할 수 있다. <개정 2014.1.29, 2021.4.20>', 7791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13448, '② 소년원장은 임시퇴원자가 보호관찰기간 중에 범법행위를 하여 임시퇴원이 취소되고 징역 또는 금고 이상의 유죄판결이 확정되거나 보호처분에 의하여 소년원에 송치된 때에는 이전의 보호처분취소를 법원소년부에 신청하여야 한다.', 7791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13449, '① 청소년심리상담실 이용에 따른 실비는 그 수혜자가 부담함을 원칙으로 한다. 다만, 다음 각 호의 어느 하나에 해당하는 사람에게는 실비의 징수를 면제할 수 있다.', 7793);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13450, '② 실비의 산정기준은 소속 공무원의 인건비를 제외한 프로그램 운영비 및 검사용지 매입가를 기준으로 하되, 100원 미만은 버린다.', 7793);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13451, '① 법무부장관은 보호소년등의 선도ㆍ보호에 관한 학식과 경험이 풍부한 자를 소년보호위원으로 위촉하여 교정교육에 참여시킬 수 있다. 다만, 다음 각 호의 어느 하나에 해당하는 자는 소년보호위원으로 위촉할 수 없다.', 7794);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13452, '② 원장은 소년보호위원으로 위촉된 자가 제1항 각 호의 어느 하나에 해당되는 사유가 발생한 때에는 지체 없이 사유서 등을 첨부하여 법무부장관에게 해촉을 신청하여야 한다.', 7794);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13453, '① 법 제51조에 따라 설치된 소년보호협회(이하 "협회"라 한다)는 영 제98조제2항에 따른 수익사업의 경영으로 목적사업에 지장을 초래하여서는 아니되며, 그 수익은 목적사업을 위하여 사용하여야 한다.', 7796);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13454, '② 협회는 영 제98조제3항에 따라 수익사업의 승인 또는 변경승인을 신청하는 경우에는 승인신청서에 다음 각 호의 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 7796);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13455, '③ 영 제99조제3항에 따라 협회가 법무부장관에게 제출하는 사업실적 및 결산서에는 해당 회계연도의 대차대조표ㆍ손익계산서ㆍ재산목록ㆍ잉여금처분계산서ㆍ감사의견서 및 관련 서류가 포함되어야 한다.', 7796);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13456, '① 영 제102조제1항에 따른 기부금품의 접수 영수증은 「법인세법 시행규칙」 제82조제7항제3호의3의 별지 제63호의3서식에 따른다.', 7797);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13457, '② 영 제102조제5항에 따른 기부금품의 접수현황 및 사용실적 등에 관한 장부는 별지 제35호서식에 따른다.', 7797);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13458, '① 소년 보호사건의 관할은 소년의 행위지, 거주지 또는 현재지로 한다.', 7800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13459, '② 소년 보호사건은 가정법원소년부 또는 지방법원소년부[이하 "소년부(少年部)"라 한다]에 속한다.', 7800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13460, '③ 소년 보호사건의 심리(審理)와 처분 결정은 소년부 단독판사가 한다.', 7800);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13461, '① 다음 각 호의 어느 하나에 해당하는 소년은 소년부의 보호사건으로 심리한다.', 7801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13462, '② 제1항제2호 및 제3호에 해당하는 소년이 있을 때에는 경찰서장은 직접 관할 소년부에 송치(送致)하여야 한다.', 7801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13463, '③ 제1항 각 호의 어느 하나에 해당하는 소년을 발견한 보호자 또는 학교ㆍ사회복리시설ㆍ보호관찰소(보호관찰지소를 포함한다. 이하 같다)의 장은 이를 관할 소년부에 통고할 수 있다.', 7801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13464, '① 보호사건을 송치받은 소년부는 보호의 적정을 기하기 위하여 필요하다고 인정하면 결정(決定)으로써 사건을 다른 관할 소년부에 이송할 수 있다.', 7803);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13465, '② 소년부는 사건이 그 관할에 속하지 아니한다고 인정하면 결정으로써 그 사건을 관할 소년부에 이송하여야 한다.', 7803);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13466, '① 소년부는 조사 또는 심리한 결과 금고 이상의 형에 해당하는 범죄 사실이 발견된 경우 그 동기와 죄질이 형사처분을 할 필요가 있다고 인정하면 결정으로써 사건을 관할 지방법원에 대응한 검찰청 검사에게 송치하여야 한다.', 7804);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13467, '② 소년부는 조사 또는 심리한 결과 사건의 본인이 19세 이상인 것으로 밝혀진 경우에는 결정으로써 사건을 관할 지방법원에 대응하는 검찰청 검사에게 송치하여야 한다. 다만, 제51조에 따라 법원에 이송하여야 할 경우에는 그러하지 아니하다.', 7804);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13468, '① 소년부 판사는 조사관에게 사건 본인, 보호자 또는 참고인의 심문이나 그 밖에 필요한 사항을 조사하도록 명할 수 있다.', 7808);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13469, '② 소년부는 제4조제3항에 따라 통고된 소년을 심리할 필요가 있다고 인정하면 그 사건을 조사하여야 한다.', 7808);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13470, '① 소년부 판사는 사건의 조사 또는 심리에 필요하다고 인정하면 기일을 지정하여 사건 본인이나 보호자 또는 참고인을 소환할 수 있다.', 7810);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13471, '② 사건 본인이나 보호자가 정당한 이유 없이 소환에 응하지 아니하면 소년부 판사는 동행영장을 발부할 수 있다.', 7810);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13472, null, 7812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13473, '① 동행영장은 조사관이 집행한다.', 7813);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13474, '② 소년부 판사는 소년부 법원서기관ㆍ법원사무관ㆍ법원주사ㆍ법원주사보나 보호관찰관 또는 사법경찰관리에게 동행영장을 집행하게 할 수 있다.', 7813);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13475, '③ 동행영장을 집행하면 지체 없이 보호자나 보조인에게 알려야 한다.', 7813);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13476, '① 사건 본인이나 보호자는 소년부 판사의 허가를 받아 보조인을 선임할 수 있다.', 7814);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13477, '② 보호자나 변호사를 보조인으로 선임하는 경우에는 제1항의 허가를 받지 아니하여도 된다.', 7814);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13478, '③ 보조인을 선임함에 있어서는 보조인과 연명날인한 서면을 제출하여야 한다. 이 경우 변호사가 아닌 사람을 보조인으로 선임할 경우에는 위 서면에 소년과 보조인과의 관계를 기재하여야 한다.', 7814);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13479, '④ 소년부 판사는 보조인이 심리절차를 고의로 지연시키는 등 심리진행을 방해하거나 소년의 이익에 반하는 행위를 할 우려가 있다고 판단하는 경우에는 보조인 선임의 허가를 취소할 수 있다.', 7814);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13480, '⑤ 보조인의 선임은 심급마다 하여야 한다.', 7814);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13481, '⑥ 「형사소송법」 중 변호인의 권리의무에 관한 규정은 소년 보호사건의 성질에 위배되지 아니하는 한 보조인에 대하여 준용한다.', 7814);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13482, '① 소년이 소년분류심사원에 위탁된 경우 보조인이 없을 때에는 법원은 변호사 등 적정한 자를 보조인으로 선정하여야 한다.', 7815);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13483, '② 소년이 소년분류심사원에 위탁되지 아니하였을 때에도 다음의 경우 법원은 직권에 의하거나 소년 또는 보호자의 신청에 따라 보조인을 선정할 수 있다.', 7815);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13484, '③ 제1항과 제2항에 따라 선정된 보조인에게 지급하는 비용에 대하여는 「형사소송비용 등에 관한 법률」을 준용한다.', 7815);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13485, '① 소년부 판사는 사건을 조사 또는 심리하는 데에 필요하다고 인정하면 소년의 감호에 관하여 결정으로써 다음 각 호의 어느 하나에 해당하는 조치를 할 수 있다.', 7816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13486, '② 동행된 소년 또는 제52조제1항에 따라 인도된 소년에 대하여는 도착한 때로부터 24시간 이내에 제1항의 조치를 하여야 한다.', 7816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13487, '③ 제1항제1호 및 제2호의 위탁기간은 3개월을, 제1항제3호의 위탁기간은 1개월을 초과하지 못한다. 다만, 특별히 계속 조치할 필요가 있을 때에는 한 번에 한하여 결정으로써 연장할 수 있다.', 7816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13488, '④ 제1항제1호 및 제2호의 조치를 할 때에는 보호자 또는 위탁받은 자에게 소년의 감호에 관한 필요 사항을 지시할 수 있다.', 7816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13489, '⑤ 소년부 판사는 제1항의 결정을 하였을 때에는 소년부 법원서기관ㆍ법원사무관ㆍ법원주사ㆍ법원주사보, 소년분류심사원 소속 공무원, 교도소 또는 구치소 소속 공무원, 보호관찰관 또는 사법경찰관리에게 그 결정을 집행하게 할 수 있다.', 7816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13490, '⑥ 제1항의 조치는 언제든지 결정으로써 취소하거나 변경할 수 있다.', 7816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13491, '① 소년부 판사는 송치서와 조사관의 조사보고에 따라 사건의 심리를 개시(開始)할 수 없거나 개시할 필요가 없다고 인정하면 심리를 개시하지 아니한다는 결정을 하여야 한다. 이 결정은 사건 본인과 보호자에게 알려야 한다.', 7817);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13492, '② 사안이 가볍다는 이유로 심리를 개시하지 아니한다는 결정을 할 때에는 소년에게 훈계하거나 보호자에게 소년을 엄격히 관리하거나 교육하도록 고지할 수 있다.', 7817);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13493, '③ 제1항의 결정이 있을 때에는 제18조의 임시조치는 취소된 것으로 본다.', 7817);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13494, '④ 소년부 판사는 소재가 분명하지 아니하다는 이유로 심리를 개시하지 아니한다는 결정을 받은 소년의 소재가 밝혀진 경우에는 그 결정을 취소하여야 한다.', 7817);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13495, '① 소년부 판사는 송치서와 조사관의 조사보고에 따라 사건을 심리할 필요가 있다고 인정하면 심리 개시 결정을 하여야 한다.', 7818);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13496, '② 제1항의 결정은 사건 본인과 보호자에게 알려야 한다. 이 경우 심리 개시 사유의 요지와 보조인을 선임할 수 있다는 취지를 아울러 알려야 한다.', 7818);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13497, '① 소년부 판사는 심리 기일을 지정하고 본인과 보호자를 소환하여야 한다. 다만, 필요가 없다고 인정한 경우에는 보호자는 소환하지 아니할 수 있다.', 7819);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13498, '② 보조인이 선정된 경우에는 보조인에게 심리 기일을 알려야 한다.', 7819);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13499, '① 심리 기일에는 소년부 판사와 서기가 참석하여야 한다.', 7821);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13500, '② 조사관, 보호자 및 보조인은 심리 기일에 출석할 수 있다.', 7821);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13501, '① 심리는 친절하고 온화하게 하여야 한다.', 7822);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13502, '② 심리는 공개하지 아니한다. 다만, 소년부 판사는 적당하다고 인정하는 자에게 참석을 허가할 수 있다.', 7822);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13503, '① 조사관, 보호자 및 보조인은 심리에 관하여 의견을 진술할 수 있다.', 7823);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13504, '② 제1항의 경우에 소년부 판사는 필요하다고 인정하면 사건 본인의 퇴장을 명할 수 있다.', 7823);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13505, null, 7824);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13506, '① 소년부 판사는 소년의 품행을 교정하고 피해자를 보호하기 위하여 필요하다고 인정하면 소년에게 피해 변상 등 피해자와의 화해를 권고할 수 있다.', 7825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13507, '② 소년부 판사는 제1항의 화해를 위하여 필요하다고 인정하면 기일을 지정하여 소년, 보호자 또는 참고인을 소환할 수 있다.', 7825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13508, '③ 소년부 판사는 소년이 제1항의 권고에 따라 피해자와 화해하였을 경우에는 보호처분을 결정할 때 이를 고려할 수 있다.', 7825);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13509, '① 소년부 판사는 증인을 신문(訊問)하고 감정(鑑定)이나 통역 및 번역을 명할 수 있다.', 7826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13510, '② 제1항의 경우에는 「형사소송법」 중 법원의 증인신문, 감정이나 통역 및 번역에 관한 규정을 보호사건의 성질에 위반되지 아니하는 한도에서 준용한다.', 7826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13511, '① 소년부 판사는 검증, 압수 또는 수색을 할 수 있다.', 7827);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13512, '② 제1항의 경우에는 「형사소송법」 중 법원의 검증, 압수 및 수색에 관한 규정은 보호사건의 성질에 위반되지 아니하는 한도에서 준용한다.', 7827);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13513, '① 소년부 판사는 그 직무에 관하여 모든 행정기관, 학교, 병원, 그 밖의 공사단체(公私團體)에 필요한 원조와 협력을 요구할 수 있다.', 7828);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13514, '② 제1항의 요구를 거절할 때에는 정당한 이유를 제시하여야 한다.', 7828);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13515, '① 소년부 판사는 심리 결과 보호처분을 할 수 없거나 할 필요가 없다고 인정하면 그 취지의 결정을 하고, 이를 사건 본인과 보호자에게 알려야 한다.', 7829);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13516, '② 제1항의 결정에 관하여는 제19조제2항과 제3항을 준용한다.', 7829);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13517, '① 소년부 법원서기관ㆍ법원사무관ㆍ법원주사 또는 법원주사보는 보호사건의 조사 및 심리에 대한 기록을 작성하여 조사 및 심리의 내용과 모든 결정을 명확히 하고 그 밖에 필요한 사항을 적어야 한다.', 7830);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13518, '② 조사 기록에는 조사관 및 소년부 법원서기관ㆍ법원사무관ㆍ법원주사 또는 법원주사보가, 심리기록에는 소년부 판사 및 법원서기관ㆍ법원사무관ㆍ법원주사 또는 법원주사보가 서명날인하여야 한다.', 7830);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13519, '① 소년부 판사는 심리 결과 보호처분을 할 필요가 있다고 인정하면 결정으로써 다음 각 호의 어느 하나에 해당하는 처분을 하여야 한다. <개정 2020.10.20>', 7833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13520, '② 다음 각 호 안의 처분 상호 간에는 그 전부 또는 일부를 병합할 수 있다.', 7833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13521, '③ 제1항제3호의 처분은 14세 이상의 소년에게만 할 수 있다.', 7833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13522, '④ 제1항제2호 및 제10호의 처분은 12세 이상의 소년에게만 할 수 있다.', 7833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13523, '⑤ 제1항 각 호의 어느 하나에 해당하는 처분을 한 경우 소년부는 소년을 인도하면서 소년의 교정에 필요한 참고자료를 위탁받는 자나 처분을 집행하는 자에게 넘겨야 한다.', 7833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13524, '⑥ 소년의 보호처분은 그 소년의 장래 신상에 어떠한 영향도 미치지 아니한다.', 7833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13525, '① 제32조제1항제4호 또는 제5호의 처분을 할 때에 3개월 이내의 기간을 정하여 「보호소년 등의 처우에 관한 법률」에 따른 대안교육 또는 소년의 상담ㆍ선도ㆍ교화와 관련된 단체나 시설에서의 상담ㆍ교육을 받을 것을 동시에 명할 수 있다.', 7834);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13526, '② 제32조제1항제4호 또는 제5호의 처분을 할 때에 1년 이내의 기간을 정하여 야간 등 특정 시간대의 외출을 제한하는 명령을 보호관찰대상자의 준수 사항으로 부과할 수 있다.', 7834);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13527, '③ 소년부 판사는 가정상황 등을 고려하여 필요하다고 판단되면 보호자에게 소년원ㆍ소년분류심사원 또는 보호관찰소 등에서 실시하는 소년의 보호를 위한 특별교육을 받을 것을 명할 수 있다.', 7834);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13528, '① 제32조제1항제1호ㆍ제6호ㆍ제7호의 위탁기간은 6개월로 하되, 소년부 판사는 결정으로써 6개월의 범위에서 한 번에 한하여 그 기간을 연장할 수 있다. 다만, 소년부 판사는 필요한 경우에는 언제든지 결정으로써 그 위탁을 종료시킬 수 있다.', 7835);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13529, '② 제32조제1항제4호의 단기 보호관찰기간은 1년으로 한다.', 7835);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13530, '③ 제32조제1항제5호의 장기 보호관찰기간은 2년으로 한다. 다만, 소년부 판사는 보호관찰관의 신청에 따라 결정으로써 1년의 범위에서 한 번에 한하여 그 기간을 연장할 수 있다.', 7835);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13531, '④ 제32조제1항제2호의 수강명령은 100시간을, 제32조제1항제3호의 사회봉사명령은 200시간을 초과할 수 없으며, 보호관찰관이 그 명령을 집행할 때에는 사건 본인의 정상적인 생활을 방해하지 아니하도록 하여야 한다.', 7835);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13532, '⑤ 제32조제1항제9호에 따라 단기로 소년원에 송치된 소년의 보호기간은 6개월을 초과하지 못한다.', 7835);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13533, '⑥ 제32조제1항제10호에 따라 장기로 소년원에 송치된 소년의 보호기간은 2년을 초과하지 못한다.', 7835);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13534, '⑦ 제32조제1항제6호부터 제10호까지의 어느 하나에 해당하는 처분을 받은 소년이 시설위탁이나 수용 이후 그 시설을 이탈하였을 때에는 위 처분기간은 진행이 정지되고, 재위탁 또는 재수용된 때로부터 다시 진행한다.', 7835);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13535, '① 소년부 판사는 제4조제1항제1호ㆍ제2호에 해당하는 소년에 대하여 제32조의 처분을 하는 경우에는 결정으로써 다음의 물건을 몰수할 수 있다.', 7836);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13536, '② 제1항의 몰수는 그 물건이 사건 본인 이외의 자의 소유에 속하지 아니하는 경우에만 할 수 있다. 다만, 사건 본인의 행위가 있은 후 그 정을 알고도 취득한 자가 소유한 경우에는 그러하지 아니하다.', 7836);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13537, '① 소년부 판사는 제32조제1항제1호ㆍ제6호ㆍ제7호의 처분을 한 경우에는 위탁받은 자에게 소년에 관한 보고서나 의견서를 제출하도록 요구할 수 있다.', 7838);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13538, '② 소년부 판사는 조사관에게 제32조제1항제1호ㆍ제6호ㆍ제7호의 처분에 관한 집행상황을 보고하게 할 수 있고, 필요하다고 인정되면 위탁받은 자에게 그 집행과 관련된 사항을 지시할 수 있다.', 7838);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13539, '① 소년부 판사는 위탁받은 자나 보호처분을 집행하는 자의 신청에 따라 결정으로써 제32조의 보호처분과 제32조의2의 부가처분을 변경할 수 있다. 다만, 제32조제1항제1호ㆍ제6호ㆍ제7호의 보호처분과 제32조의2제1항의 부가처분은 직권으로 변경할 수 있다.', 7839);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13540, '② 제1항에 따른 결정을 집행할 때에는 제35조를 준용한다.', 7839);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13541, '③ 제1항의 결정은 지체 없이 사건 본인과 보호자에게 알리고 그 취지를 위탁받은 자나 보호처분을 집행하는 자에게 알려야 한다.', 7839);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13542, '① 보호처분이 계속 중일 때에 사건 본인이 처분 당시 19세 이상인 것으로 밝혀진 경우에는 소년부 판사는 결정으로써 그 보호처분을 취소하고 다음의 구분에 따라 처리하여야 한다.', 7840);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13543, '② 제4조제1항제1호ㆍ제2호의 소년에 대한 보호처분이 계속 중일 때에 사건 본인이 행위 당시 10세 미만으로 밝혀진 경우 또는 제4조제1항제3호의 소년에 대한 보호처분이 계속 중일 때에 사건 본인이 처분 당시 10세 미만으로 밝혀진 경우에는 소년부 판사는 결정으로써 그 보호처분을 취소하여야 한다.', 7840);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13544, '① 증인ㆍ감정인ㆍ통역인ㆍ번역인에게 지급하는 비용, 숙박료, 그 밖의 비용에 대하여는 「형사소송법」 중 비용에 관한 규정을 준용한다.', 7844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13545, '② 참고인에게 지급하는 비용에 관하여는 제1항을 준용한다.', 7844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13546, '① 제32조에 따른 보호처분의 결정 및 제32조의2에 따른 부가처분 등의 결정 또는 제37조의 보호처분ㆍ부가처분 변경 결정이 다음 각 호의 어느 하나에 해당하면 사건 본인ㆍ보호자ㆍ보조인 또는 그 법정대리인은 관할 가정법원 또는 지방법원 본원 합의부에 항고할 수 있다.', 7845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13547, '② 항고를 제기할 수 있는 기간은 7일로 한다.', 7845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13548, '① 항고를 할 때에는 항고장을 원심(原審) 소년부에 제출하여야 한다.', 7846);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13549, '② 항고장을 받은 소년부는 3일 이내에 의견서를 첨부하여 항고법원에 송부하여야 한다.', 7846);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13550, '① 항고법원은 항고 절차가 법률에 위반되거나 항고가 이유 없다고 인정한 경우에는 결정으로써 항고를 기각하여야 한다.', 7847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13551, '② 항고법원은 항고가 이유가 있다고 인정한 경우에는 원결정(原決定)을 취소하고 사건을 원소년부에 환송(還送)하거나 다른 소년부에 이송하여야 한다. 다만, 환송 또는 이송할 여유가 없이 급하거나 그 밖에 필요하다고 인정한 경우에는 원결정을 파기하고 불처분 또는 보호처분의 결정을 할 수 있다.', 7847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13552, '③ 제2항에 따라 항고가 이유가 있다고 인정되어 보호처분의 결정을 다시 하는 경우에는 원결정에 따른 보호처분의 집행 기간은 그 전부를 항고에 따른 보호처분의 집행 기간에 산입(제32조제1항제8호ㆍ제9호ㆍ제10호 처분 상호 간에만 해당한다)한다. <신설 2015.12.1>', 7847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13553, '① 항고를 기각하는 결정에 대하여는 그 결정이 법령에 위반되는 경우에만 대법원에 재항고를 할 수 있다.', 7849);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13554, '② 제1항의 재항고에 관하여는 제43조제2항 및 제45조제3항을 준용한다. <개정 2015.12.1>', 7849);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13555, '① 검사는 소년에 대한 피의사건을 수사한 결과 보호처분에 해당하는 사유가 있다고 인정한 경우에는 사건을 관할 소년부에 송치하여야 한다.', 7851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13556, '② 소년부는 제1항에 따라 송치된 사건을 조사 또는 심리한 결과 그 동기와 죄질이 금고 이상의 형사처분을 할 필요가 있다고 인정할 때에는 결정으로써 해당 검찰청 검사에게 송치할 수 있다.', 7851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13557, '③ 제2항에 따라 송치한 사건은 다시 소년부에 송치할 수 없다.', 7851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13558, '① 검사는 소년 피의사건에 대하여 소년부 송치, 공소제기, 기소유예 등의 처분을 결정하기 위하여 필요하다고 인정하면 피의자의 주거지 또는 검찰청 소재지를 관할하는 보호관찰소의 장, 소년분류심사원장 또는 소년원장(이하 "보호관찰소장등"이라 한다)에게 피의자의 품행, 경력, 생활환경이나 그 밖에 필요한 사항에 관한 조사를 요구할 수 있다.', 7852);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13559, '② 제1항의 요구를 받은 보호관찰소장등은 지체 없이 이를 조사하여 서면으로 해당 검사에게 통보하여야 하며, 조사를 위하여 필요한 경우에는 소속 보호관찰관ㆍ분류심사관 등에게 피의자 또는 관계인을 출석하게 하여 진술요구를 하는 등의 방법으로 필요한 사항을 조사하게 할 수 있다.', 7852);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13560, '③ 제2항에 따른 조사를 할 때에는 미리 피의자 또는 관계인에게 조사의 취지를 설명하여야 하고, 피의자 또는 관계인의 인권을 존중하며, 직무상 비밀을 엄수하여야 한다.', 7852);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13561, '④ 검사는 보호관찰소장등으로부터 통보받은 조사 결과를 참고하여 소년피의자를 교화ㆍ개선하는 데에 가장 적합한 처분을 결정하여야 한다.', 7852);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13562, null, 7853);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13563, '① 제49조제1항이나 제50조에 따른 소년부 송치결정이 있는 경우에는 소년을 구금하고 있는 시설의 장은 검사의 이송 지휘를 받은 때로부터 법원 소년부가 있는 시ㆍ군에서는 24시간 이내에, 그 밖의 시ㆍ군에서는 48시간 이내에 소년을 소년부에 인도하여야 한다. 이 경우 구속영장의 효력은 소년부 판사가 제18조제1항에 따른 소년의 감호에 관한 결정을 한 때에 상실한다.', 7856);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13564, '② 제1항에 따른 인도와 결정은 구속영장의 효력기간 내에 이루어져야 한다.', 7856);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13565, '① 소년에 대한 구속영장은 부득이한 경우가 아니면 발부하지 못한다.', 7859);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13566, '② 소년을 구속하는 경우에는 특별한 사정이 없으면 다른 피의자나 피고인과 분리하여 수용하여야 한다.', 7859);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13567, '① 소년에 대한 형사사건의 심리는 친절하고 온화하게 하여야 한다.', 7862);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13568, '② 제1항의 심리에는 소년의 심신상태, 품행, 경력, 가정상황, 그 밖의 환경 등에 대하여 정확한 사실을 밝힐 수 있도록 특별히 유의하여야 한다.', 7862);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13569, '① 소년이 법정형으로 장기 2년 이상의 유기형(有期刑)에 해당하는 죄를 범한 경우에는 그 형의 범위에서 장기와 단기를 정하여 선고한다. 다만, 장기는 10년, 단기는 5년을 초과하지 못한다.', 7864);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13570, '② 소년의 특성에 비추어 상당하다고 인정되는 때에는 그 형을 감경할 수 있다.', 7864);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13571, '③ 형의 집행유예나 선고유예를 선고할 때에는 제1항을 적용하지 아니한다.', 7864);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13572, '④ 소년에 대한 부정기형을 집행하는 기관의 장은 형의 단기가 지난 소년범의 행형(行刑) 성적이 양호하고 교정의 목적을 달성하였다고 인정되는 경우에는 관할 검찰청 검사의 지휘에 따라 그 형의 집행을 종료시킬 수 있다. <개정 2018.9.18>', 7864);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13573, null, 7869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13574, '① 소년이었을 때 범한 죄에 의하여 형의 선고 등을 받은 자에 대하여 다음 각 호의 경우 자격에 관한 법령을 적용할 때 장래에 향하여 형의 선고를 받지 아니한 것으로 본다. <개정 2018.9.18>', 7871);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13575, '② 제1항에도 불구하고 형의 선고유예가 실효되거나 집행유예가 실효ㆍ취소된 때에는 그 때에 형을 선고받은 것으로 본다. <신설 2018.9.18>', 7871);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13576, null, 7872);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13577, '① 이 법에 따라 조사 또는 심리 중에 있는 보호사건이나 형사사건에 대하여는 성명ㆍ연령ㆍ직업ㆍ용모 등으로 비추어 볼 때 그 자가 당해 사건의 당사자라고 미루어 짐작할 수 있는 정도의 사실이나 사진을 신문이나 그 밖의 출판물에 싣거나 방송할 수 없다.', 7873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13578, '② 제1항을 위반한 다음 각 호의 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 2014.1.7>', 7873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13579, '① 소년 보호사건과 관계있는 기관은 그 사건 내용에 관하여 재판, 수사 또는 군사상 필요한 경우 외의 어떠한 조회에도 응하여서는 아니 된다.', 7875);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13580, '② 제1항을 위반한 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 7875);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13581, null, 7876);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13582, null, 7878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13583, '① 국가와 지방자치단체는 학교 밖 청소년에 대한 사회적 차별 및 편견을 예방하고 학교 밖 청소년을 존중하고 이해할 수 있도록 조사ㆍ연구ㆍ교육 및 홍보 등 필요한 조치를 하여야 한다.', 7879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13584, '② 국가와 지방자치단체는 학교 밖 청소년을 조기에 발견하고, 지원에 필요한 법적ㆍ제도적 장치를 마련하여 시행하여야 한다. <개정 2021.3.23>', 7879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13585, '③ 국가와 지방자치단체는 학교 밖 청소년의 교육복지 실현을 위하여 노력하여야 한다. <신설 2021.3.23>', 7879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13586, '④ 국가와 지방자치단체는 제1항부터 제3항까지의 규정에 따른 책무를 다하기 위하여 학교 밖 청소년 지원에 필요한 행정적ㆍ재정적 지원방안을 마련하여야 한다. <개정 2021.3.23>', 7879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13587, '① 국가와 지방자치단체는 「청소년 기본법」 제14조에 따라 연도별 시행계획을 수립하는 경우 다음 각 호의 사항을 포함하여야 한다.', 7881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13588, '② 학교 밖 청소년 지원계획의 수립ㆍ시행 등에 필요한 사항은 대통령령으로 정한다.', 7881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13589, '① 여성가족부장관은 학교 밖 청소년의 현황 및 실태 파악과 학교 밖 청소년 지원 정책수립을 위한 기초자료로 활용하기 위하여 2년마다 학교 밖 청소년에 대한 실태조사를 실시하고, 그 결과를 공표하여야 한다. <개정 2021.3.23>', 7882);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13590, '② 여성가족부장관은 제1항에 따른 실태조사 중 학업중단 현황에 관한 조사는 교육부장관과 협의하여 실시한다.', 7882);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13591, '③ 여성가족부장관은 제1항에 따른 실태조사에 필요한 경우 관계 중앙행정기관의 장, 지방자치단체의 장 또는 「공공기관의 운영에 관한 법률」에 따른 공공기관의 장, 그 밖의 관련 법인ㆍ단체에 대하여 필요한 자료 제출 또는 의견 진술을 요청할 수 있다. 이 경우 요청을 받은 자는 정당한 사유가 없으면 이에 협조하여야 한다.', 7882);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13592, '④ 제1항에 따른 실태조사의 내용과 방법 등에 필요한 사항은 여성가족부령으로 정한다.', 7882);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13593, '① 학교 밖 청소년 지원에 관한 다음 각 호의 사항을 심의하기 위하여 여성가족부장관 소속으로 학교 밖 청소년 지원 위원회(이하 "지원위원회"라 한다)를 둔다.', 7883);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13594, '② 지원위원회는 위원장 1명과 부위원장 1명을 포함한 15명 이내의 위원으로 구성하고, 위원은 당연직 위원과 위촉직 위원으로 구성한다.', 7883);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13595, '③ 지원위원회의 조직ㆍ구성 및 운영 등에 필요한 사항은 대통령령으로 정한다.', 7883);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13596, '① 국가와 지방자치단체는 학교 밖 청소년에 대하여 효율적이고 적합한 지원을 할 수 있도록 심리상담, 진로상담, 가족상담 등 상담을 제공할 수 있다.', 7884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13597, '② 제1항에 따른 상담의 방법과 내용 등에 필요한 사항은 여성가족부령으로 정한다.', 7884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13598, '① 국가와 지방자치단체(교육감을 포함한다)는 학교 밖 청소년이 학업에 복귀할 수 있도록 다음 각 호의 사항을 지원할 수 있다. <개정 2024.3.26>', 7885);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13599, '② 제1항에 따른 교육지원의 방법 및 절차 등에 필요한 사항은 여성가족부령으로 정한다.', 7885);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13600, '① 국가와 지방자치단체는 학교 밖 청소년이 자신의 적성과 능력에 맞는 직업의 체험과 훈련을 할 수 있도록 다음 각 호의 사항을 지원할 수 있다.', 7886);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13601, '② 국가와 지방자치단체는 학교 밖 청소년을 대상으로 취업 및 직무수행에 필요한 지식ㆍ기술 및 태도를 습득ㆍ향상시키기 위하여 직업교육 훈련을 실시할 수 있다.', 7886);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13602, '③ 제1항에 따른 지원과 제2항의 직업교육 훈련 내용 및 방법에 필요한 사항은 여성가족부령으로 정한다.', 7886);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13603, '① 국가와 지방자치단체는 대통령령으로 정하는 바에 따라 학교 밖 청소년의 자립에 필요한 생활지원, 문화공간지원, 의료지원(제11조의2에 따라 건강진단을 받은 후 확진을 위한 검사에 사용된 의료비의 지원을 포함한다), 정서지원 등을 제공할 수 있다. <개정 2018.1.16, 2024.3.26>', 7887);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13604, '② 국가와 지방자치단체는 경제교육, 법률교육, 문화교육 등 학교 밖 청소년의 자립에 필요한 교육을 지원할 수 있다.', 7887);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13605, '③ 국가와 지방자치단체는 제1항에 따른 지원이 필요한 학교 밖 청소년에게 「청소년복지 지원법」 제14조에 따른 위기청소년 특별지원을 우선적으로 제공할 수 있다.', 7887);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13606, '④ 제2항에 따른 지원의 방법과 내용 등에 필요한 사항은 여성가족부령으로 정한다. <신설 2024.3.26>', 7887);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13607, '① 국가와 지방자치단체는 학교 밖 청소년의 건강증진 및 질환 예방을 위한 건강진단을 실시할 수 있다.', 7888);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13608, '② 국가와 지방자치단체는 제1항에 따른 건강진단의 실시를 「국민건강보험법」에 따른 국민건강보험공단에 위탁할 수 있다.', 7888);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13609, '③ 제1항에 따른 건강진단의 실시에 필요한 사항은 여성가족부령으로 정한다.', 7888);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13610, '① 국가와 지방자치단체는 학교 밖 청소년 지원을 위하여 필요한 경우 학교 밖 청소년 지원센터(이하 "지원센터"라 한다)를 설치하거나 다음 각 호에 해당하는 기관이나 단체를 지원센터로 지정할 수 있다.', 7889);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13611, '② 지원센터는 다음 각 호의 업무를 수행한다.', 7889);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13612, '③ 지원센터에는 학교 밖 청소년 지원 업무를 수행하기 위하여 관련 분야에 대한 학식과 경험을 가진 전문인력을 두어야 한다.', 7889);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13613, '④ 국가 및 지방자치단체의 장은 제2항 각 호의 업무 수행에 필요한 비용을 지원할 수 있다.', 7889);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13614, '⑤ 제1항의 지원센터의 설치기준 및 지정기준, 지정기간, 지정절차, 제3항의 전문인력의 기준 등에 필요한 사항은 대통령령으로 정한다.', 7889);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13615, '① 여성가족부장관은 3년마다 지원센터의 운영실적을 평가하고, 그 결과를 지원센터의 감독, 지원 등에 반영할 수 있다.', 7890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13616, '② 제1항에 따른 평가의 기준과 방법 등에 관하여 필요한 사항은 여성가족부령으로 정한다.', 7890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13617, '① 국가와 지방자치단체의 장은 지원센터가 다음 각 호의 어느 하나에 해당하는 경우에는 6개월의 범위에서 업무의 전부 또는 일부를 정지하거나 그 지정을 취소할 수 있다. 다만, 제1호에 해당하는 경우에는 지정을 취소하여야 한다.', 7891);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13618, '② 국가 및 지방자치단체의 장은 제1항에 따라 지원센터의 지정을 취소하려면 청문을 거쳐야 한다.', 7891);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13619, '③ 제1항에 따른 지정 취소, 업무정지의 기준 및 절차 등에 필요한 사항은 대통령령으로 정한다.', 7891);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13620, '① 「초ㆍ중등교육법」 제2조 각 호의 각급 학교의 장(이하 이 조에서 "학교장"이라 한다)은 소속 학교의 학생이 학교 밖 청소년이 되는 경우에는 해당 청소년에게 학교 밖 청소년 지원 프로그램을 안내하고 지원센터를 연계하여야 한다.', 7893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13621, '② 「청소년복지 지원법」 제9조에 따른 지역사회 청소년통합지원체계에 포함된 기관 또는 단체의 장(이하 이 조에서 "단체장"이라 한다)은 지원이 필요한 학교 밖 청소년을 발견한 경우에는 지체 없이 해당 청소년에게 학교 밖 청소년 지원 프로그램을 안내하고 지원센터를 연계하여야 한다.', 7893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13622, '③ 제1항 및 제2항에 따라 학교 밖 청소년을 지원센터에 연계하는 경우 학교장 및 단체장은 해당 청소년(제6호의 경우 해당 청소년의 법정대리인)에게 다음 각 호의 개인정보(이하 "개인정보"라 한다)의 수집ㆍ이용 목적, 수집 항목, 보유ㆍ이용 기간 및 파기 방법(이하 "개인정보동의고지사항"이라 한다)을 고지하고 개인정보를 수집하여 지원센터에 제공할 수 있다. 다만, 질병 또는 출국을 사유로 학교 밖 청소년이 되는 경우는 제외한다. <개정 2017.3.21, 2021.3.23, 2024.3.26>', 7893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13623, '④ 삭제 <2024.3.26>', 7893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13624, '⑤ 지원센터의 장은 제3항에 따라 개인정보를 제공받은 날부터 6개월 이내에 해당 청소년 또는 청소년의 법정대리인에게 개인정보동의고지사항 및 「개인정보 보호법」 제37조제1항에 따른 개인정보의 처리정지 요구 권한을 고지하고 동의를 받아야 한다. 이 경우 해당 청소년 또는 청소년의 법정대리인이 개인정보의 처리정지를 요구하거나 개인정보를 제공받은 날부터 6개월 이내에 동의를 받지 못한 경우에는 즉시 개인정보를 파기하여야 한다. <신설 2021.3.23, 2024.3.26>', 7893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13625, '⑥ 제1항 및 제2항에 따른 학교 밖 청소년 지원 프로그램의 안내 및 지원센터의 연계에 필요한 사항은 여성가족부령으로 정한다. <개정 2021.3.23>', 7893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13626, '① 이 법에 따른 여성가족부장관의 권한은 그 일부를 대통령령으로 정하는 바에 따라 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ도지사ㆍ특별자치도지사 또는 시장ㆍ군수ㆍ구청장(자치구의 구청장을 말한다)에게 위임할 수 있다.', 7896);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13627, '② 여성가족부장관은 이 법에 따른 업무의 일부를 대통령령으로 정하는 바에 따른 법인 또는 단체 등에 위탁할 수 있다.', 7896);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13628, '① 제19조를 위반하여 지원센터 또는 이와 유사한 명칭을 사용한 자에게는 300만원 이하의 과태료를 부과한다.', 7899);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13629, '② 제1항에 따른 과태료는 대통령령으로 정하는 바에 따라 여성가족부장관 또는 지방자치단체의 장이 부과ㆍ징수한다.', 7899);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13630, '① 법 제7조제1항에 따른 학교 밖 청소년 지원 위원회(이하 "지원위원회"라 한다)의 위원장은 여성가족부차관이 되고, 부위원장은 위원 중에서 호선(互選)한다.', 7902);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13631, '② 지원위원회의 위원은 다음 각 호의 사람이 된다.', 7902);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13632, '③ 제2항제2호에 따라 위촉된 위원의 임기는 2년으로 한다. 이 경우 보궐위원의 임기는 전임자 임기의 남은 기간으로 한다.', 7902);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13633, '④ 지원위원회의 위원장은 지원위원회를 대표하고 지원위원회의 업무를 총괄하며, 지원위원회의 위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 부위원장이 그 직무를 대행한다.', 7902);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13634, '⑤ 지원위원회의 사무를 처리하기 위하여 지원위원회에 간사 1명을 두며, 간사는 여성가족부 소속 공무원 중에서 여성가족부장관이 지명한다.', 7902);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13635, '① 지원위원회의 회의는 재적위원 3분의 1 이상의 요구가 있거나 위원장이 필요하다고 인정할 때에 소집한다.', 7903);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13636, '② 지원위원회의 회의는 재적위원 과반수의 출석으로 개의(開議)하고 출석위원 과반수의 찬성으로 의결한다.', 7903);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13637, '① 법 제12조제1항에 따른 학교 밖 청소년 지원센터(이하 "지원센터"라 한다)의 설치ㆍ지정 기준 및 지원센터에 두어야 하는 전문인력 기준은 별표 1과 같다.', 7905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13638, '② 법 제12조제1항에 따라 지원센터로 지정받으려는 자는 여성가족부령으로 정하는 지정 신청서(전자문서로 된 신청서를 포함한다)에 다음 각 호의 서류를 첨부하여 여성가족부장관 또는 지원센터의 소재지를 관할하는 지방자치단체의 장에게 제출하여야 한다.', 7905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13639, '③ 여성가족부장관 및 지방자치단체의 장은 법 제12조제1항에 따라 지원센터를 지정하려는 경우에는 관계 전문가 등의 의견을 들을 수 있다.', 7905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13640, '④ 지원센터의 지정기간은 3년으로 한다.', 7905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13641, '⑤ 여성가족부장관 및 지방자치단체의 장은 지정센터를 지정한 경우 그 사실을 여성가족부 또는 해당 지방자치단체의 인터넷 홈페이지에 게시하여야 한다.', 7905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13642, '① 법 제13조제1항에 따른 지원센터 지정 취소 및 업무정지의 기준은 별표 2와 같다.', 7906);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13643, '② 여성가족부장관 및 지방자치단체의 장은 지원센터의 지정을 취소하거나 업무를 정지한 경우에는 그 사실을 여성가족부 또는 해당 지방자치단체의 인터넷 홈페이지에 게시하여야 한다.', 7906);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13644, null, 7907);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13645, null, 7909);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13646, null, 7910);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13647, '① 「학교 밖 청소년 지원에 관한 법률」(이하 "법"이라 한다) 제6조제1항에 따른 학교 밖 청소년에 대한 실태조사에는 다음 각 호의 사항이 포함되어야 한다.', 7913);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13648, '② 제1항에 따른 실태조사는 표본조사의 방식으로 실시하되, 서면조사, 면접조사, 전화조사 또는 온라인 조사 등의 방법을 사용할 수 있다. <개정 2024.9.27>', 7913);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13649, '③ 여성가족부장관은 실태조사를 효율적으로 추진하기 위하여 필요한 경우에는 「고등교육법」 제2조에 따른 학교 또는 청소년 정책 관련 연구기관ㆍ법인ㆍ단체에 의뢰하여 실시할 수 있다. <신설 2024.9.27>', 7913);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13650, '④ 여성가족부장관은 법 제6조제1항에 따라 실태조사의 결과를 여성가족부의 인터넷 홈페이지에 게시하는 방법으로 공표해야 한다. <신설 2024.9.27>', 7913);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13651, '⑤ 제1항부터 제4항까지에서 규정한 사항 외에 실태조사 실시에 필요한 세부 사항은 여성가족부장관이 정한다. <신설 2024.9.27>', 7913);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13652, '① 국가 및 지방자치단체는 법 제8조제1항에 따른 상담을 학교 밖 청소년과 그 가족 또는 보호자에게 법 제12조에 따른 학교 밖 청소년 지원센터(이하 "지원센터"라 한다)를 통하여 실시한다.', 7914);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13653, '② 제1항에 따른 상담은 대면상담, 전화상담 및 온라인상담 등의 방법으로 한다.', 7914);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13654, '③ 제1항에 따른 상담은 청소년의 심리, 학교 밖 청소년의 가족관계와 친구관계 및 학교 밖 청소년의 진로 등에 관하여 실시한다.', 7914);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13655, '① 국가 및 지방자치단체(교육감을 포함한다)는 법 제9조에 따른 교육지원을 다음 각 호의 정보를 제공하는 방법으로 실시한다. <개정 2024.9.27>', 7915);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13656, '② 국가 및 지방자치단체는 학교 밖 청소년이 법 제9조제1항제1호 또는 제2호에 따른 재취학, 재입학 또는 진학을 한 경우 학교생활의 원활한 적응을 위하여 해당 청소년에 대한 상담 등 필요한 지원을 하도록 해당 학교의 장에게 요청할 수 있다.', 7915);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13657, '① 법 제10조제1항에 따른 학교 밖 청소년의 직업체험 및 훈련의 지원은 직업체험ㆍ취업지원 관련 프로그램의 종류와 그 참여 절차 등에 관한 정보를 제공하는 방법으로 한다.', 7916);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13658, '② 법 제10조제2항에 따른 직업교육 훈련의 과정은 훈련대상자의 특성, 취업ㆍ직무수행의 용이성 및 훈련 수요 등을 고려하여 여성가족부장관 및 지방자치단체의 장이 정할 수 있다.', 7916);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13659, '③ 국가와 지방자치단체는 법 제10조제2항에 따른 직업교육 훈련을 실시하는 경우 직업교육 훈련을 받는 학교 밖 청소년에게 훈련수당을 지급할 수 있다. 이 경우 여성가족부장관 및 지방자치단체의 장이 정하는 기준에 따라 소득수준, 가족상황 등 훈련을 받는 학교 밖 청소년의 여건 및 훈련 수강 횟수 등을 고려하여 훈련수당을 지급할 수 있다.', 7916);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13660, '① 법 제11조제2항에 따른 학교 밖 청소년의 자립에 필요한 교육의 지원은 강의, 시청각교육, 인터넷 홈페이지를 이용한 교육 등을 실시하는 방법으로 한다.', 7917);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13661, '② 제1항에 따라 실시하는 교육의 내용은 경제, 법률, 문화 등과 관련된 기초적인 소양(素養)을 습득하는 데 필요한 것으로 한다.', 7917);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13662, '① 법 제11조의2제1항에 따른 건강진단은 학교 밖 청소년 중 9세 이상 18세 이하의 청소년에 대하여 우선적으로 실시한다.', 7918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13663, '② 여성가족부장관, 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ도지사ㆍ특별자치도지사(이하 "시ㆍ도지사"라 한다) 또는 시장ㆍ군수ㆍ구청장(자치구의 구청장을 말한다. 이하 같다)은 제1항에 따른 건강진단을 실시하는 경우에는 그 실시기간 및 실시장소 등 구체적인 실시계획을 수립하여 해당 기관의 홈페이지에 공고해야 한다.', 7918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13664, '③ 건강진단을 신청하려는 학교 밖 청소년, 해당 청소년의 보호자(친권자, 법정대리인 또는 사실상 학교 밖 청소년을 양육하는 사람을 말한다. 이하 이 조에서 같다) 또는 「청소년기본법」 제3조제7항에 따른 청소년지도자(이하 "청소년지도자"라 한다)는 별지 제1호서식의 학교 밖 청소년 건강진단 신청서에 학교 밖 청소년임을 증명하는 서류를 첨부하여 여성가족부장관, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장에게 제출해야 한다. 이 경우 해당 청소년의 보호자 또는 청소년지도자가 신청하는 때에는 해당 청소년의 동의를 받아야 한다.', 7918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13665, '④ 여성가족부장관, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 제3항에 따른 신청서를 받은 때에는 「전자정부법」 제36조제1항에 따른 행정정보 공동이용을 통하여 해당 청소년의 주민등록표 등본을 확인해야 한다. 다만, 해당 청소년 또는 그 보호자가 확인에 동의하지 않는 경우에는 이를 첨부하도록 해야 한다.', 7918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13666, '⑤ 여성가족부장관, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 제3항에 따른 신청서를 받은 때에는 신청일부터 30일 이내에 건강진단의 실시 여부를 결정하고, 그 결과를 신청인에게 통보해야 한다.', 7918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13667, '⑥ 여성가족부장관, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 건강진단을 실시한 후 30일 이내에 그 결과를 해당 청소년에게 통보해야 한다.', 7918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13668, '⑦ 여성가족부장관, 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 건강진단을 실시한 결과 질병의 치료 등이 필요한 해당 청소년에 대하여는 적절한 조치를 하여야 한다.', 7918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13669, '⑧ 제1항부터 제7항까지에서 규정한 사항 외에 건강진단의 검사항목, 방법, 그 결과의 통보 절차 등 건강진단 실시에 필요한 사항은 여성가족부장관이 정하여 고시한다.', 7918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13670, '① 「학교 밖 청소년 지원에 관한 법률 시행령」(이하 "영"이라 한다) 제6조제2항에 따른 지원센터 지정 신청서는 별지 제2호서식에 따른다. <개정 2024.9.27>', 7919);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13671, '② 영 제6조제2항에 따른 신청을 받은 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 다음 각 호의 구분에 따른 서류를 확인하여야 한다. 다만, 신청인이 주민등록표 초본의 확인에 동의하지 아니하는 경우에는 그 사본을 첨부하도록 하여야 한다. <개정 2017.10.27, 2024.9.27>', 7919);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13672, '③ 시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 법 제12조제1항에 따라 지원센터를 지정하는 경우에는 별지 제3호서식의 학교 밖 청소년 지원센터 지정서를 발급하여야 한다. <개정 2024.9.27>', 7919);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13673, '① 법 제12조의2에 따른 지원센터에 대한 평가기준은 다음 각 호와 같다.', 7920);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13674, '② 여성가족부장관은 법 제12조의2에 따른 평가를 「청소년복지 지원법」 제22조에 따른 한국청소년상담복지개발원에 의뢰하여 실시할 수 있다.', 7920);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13675, '① 지원센터는 법 제15조제1항 및 제2항에 따른 학교 밖 청소년 지원 프로그램의 안내 및 지원센터의 연계를 위하여 「초ㆍ중등교육법」 제2조 각 호의 각급 학교의 장(이하 이 조에서 "학교장"이라 한다)과 「청소년복지 지원법」 제9조에 따른 지역사회 청소년통합지원체계에 포함된 기관 또는 단체의 장(이하 이 조에서 "단체장"이라 한다)에게 관련 정보를 제공하여야 한다.', 7921);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13676, '② 삭제 <2024.9.27>', 7921);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13677, null, 7923);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13678, '① 각 고등검찰청 검사장은 심의위원회를 구성하기 전에 심의위원회 직무 수행의 공정성을 높이기 위하여 각 고등검찰청에 20명 이상 50명 이하의 심의위원회 위원 후보(이하 "위원후보"라 한다)로 심의위원회 위원 후보단(이하 "후보단"이라 한다)을 구성한다.', 7924);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13679, '② 위원후보는 사법제도 등에 관한 학식과 경험이 풍부하고 덕망이 있는 사람 중에서 각 고등검찰청 검사장이 위촉한다.', 7924);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13680, '③ 각 고등검찰청 검사장은 법조계ㆍ학계ㆍ언론계 등 사회 각 분야에서 위원후보를 추천받을 수 있으며, 후보단이 특정 직업이나 분야에 편중되어 구성되지 않도록 노력해야 한다.', 7924);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13681, '① 각 고등검찰청 검사장은 위원후보를 위촉하기 전에 위원후보가 될 사람으로 하여금 별지 제1호서식의 직무윤리 사전진단서를 작성ㆍ제출하도록 하여 직무 적합성 여부를 확인한 후 위원후보로 위촉해야 한다.', 7925);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13682, '② 각 고등검찰청 검사장은 위원후보를 위촉한 경우 해당 위원후보로 하여금 별지 제2호서식의 직무윤리 서약서를 작성하여 제출하도록 해야 한다.', 7925);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13683, '① 심의위원회는 법 제221조의5제3항에 따라 위원장 1명을 포함하여 10명의 위원으로 구성한다.', 7926);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13684, '② 심의위원회 위원장(이하 "위원장"이라 한다)은 위원후보 중에서 후보단의 추천을 받아 각 고등검찰청 검사장이 위촉한다.', 7926);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13685, '③ 위원장을 제외한 심의위원회 위원(이하 "심의위원"이라 한다)은 심의신청이 있을 때마다 각 고등검찰청 검사장이 위원후보 중에서 추첨 등 무작위 추출방식으로 선정하여 위촉한다.', 7926);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13686, '④ 각 고등검찰청 검사장은 심의위원회의 회의가 개최되기 전에 제2항 및 제3항에 따라 위촉한 심의위원회 위원(이하 "위원"이라 한다)으로 하여금 별지 제3호서식의 서약서를 작성ㆍ제출하도록 하여 제8조제1항 각 호에 따른 결격사유 또는 제9조제1항 각 호에 따른 제척사유나 같은 조 제3항에 따른 회피사유가 없는지를 확인해야 한다.', 7926);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13687, '① 위원장의 임기는 1년으로 하며, 연임할 수 없다.', 7927);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13688, '② 위원후보의 임기는 1년으로 하며, 한 차례만 연임할 수 있다.', 7927);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13689, null, 7928);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13690, '① 다음 각 호의 어느 하나에 해당하는 사람은 위원 또는 위원후보가 될 수 없다.', 7929);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13691, '② 각 고등검찰청 검사장은 위원 또는 위원후보가 제1항 각 호의 어느 하나에 해당하는 사람이거나 위촉 당시 그에 해당하는 사람이었음이 밝혀진 경우 해당 위원 또는 위원후보를 해촉해야 한다.', 7929);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13692, '③ 제2항에 따라 해촉된 위원 또는 위원후보가 심의위원회의 직무와 관련하여 해촉 전에 한 행위는 그 효력을 잃지 않는다.', 7929);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13693, '① 위원이 다음 각 호의 어느 하나에 해당하는 경우에는 해당 안건의 심의에서 제척(除斥)된다.', 7930);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13694, '② 심의신청을 한 사법경찰관이나 심의대상 영장을 담당한 검사(이하 "담당검사"라 한다)는 위원에게 공정한 심의를 기대하기 어려운 사정이 있는 경우에는 심의위원회에 기피신청을 할 수 있고, 심의위원회는 의결로 기피 여부를 결정한다. 이 경우 기피신청의 대상인 위원은 그 의결에 참여할 수 없다.', 7930);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13695, '③ 위원은 제1항 각 호에 따른 제척사유에 해당하거나 제1항제1호의 사람 또는 해당 안건의 수사나 영장의 신청ㆍ청구 여부의 결정에 관여한 사람과 친분관계ㆍ대립관계 또는 이해관계가 있어 심의의 공정성에 대한 의심을 받을 수 있다고 판단하는 경우에는 심의위원회에 그 사실을 알리고 스스로 해당 안건의 심의에서 회피해야 한다.', 7930);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13696, '① 위원장은 심의위원회를 대표하고, 심의위원회의 업무를 총괄하며 심의위원회의 회의를 주재한다. 다만, 심의위원회의 의결에는 참여하지 못한다.', 7931);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13697, '② 위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 위원 중 연장자 순으로 그 직무를 대행한다.', 7931);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13698, '① 심의위원회에 심의위원회의 구성과 활동 등을 지원할 간사 1명을 둔다.', 7932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13699, '② 심의위원회 간사(이하 "간사"라 한다)는 각 고등검찰청 검사장이 해당 고등검찰청 소속 검사 중에서 지명한다.', 7932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13700, '③ 간사는 위원장의 명에 따라 심의위원회의 사무를 처리한다.', 7932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13701, '④ 간사는 객관적이고 중립적인 입장에서 심의위원회의 업무를 수행해야 하고, 위원장의 요청이 없는 한 위원회의 심의에 영향을 미칠 수 있는 의견 등을 표명해서는 안 된다.', 7932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13702, '⑤ 각 고등검찰청 검사장은 해당 고등검찰청 소속 검찰사무관으로 하여금 간사를 보조하게 할 수 있다.', 7932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13703, '① 사법경찰관은 다음 각 호의 구분에 따른 날부터 7일(토요일과 공휴일은 제외한다) 이내에 심의신청을 해야 한다.', 7934);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13704, '② 사법경찰관은 심의신청을 할 때 별지 제4호서식의 심의신청서 원본 및 부본 각 1부와 사건기록 등본 2부를 담당검사가 소속된 지방검찰청 소재지를 관할하는 고등검찰청(이하 "관할 고등검찰청"이라 한다)에 제출해야 한다. 다만, 담당검사와 합의한 경우 사건기록 등본은 그 일부만을 제출할 수 있다.', 7934);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13705, '③ 사법경찰관이 심의신청을 하려고 할 때 담당검사가 사건기록을 보관하고 있는 경우에는 그 담당검사는 사법경찰관에게 사건기록을 신속히 반환해야 한다.', 7934);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13706, '① 사법경찰관은 심의위원회의 회의 개최일 전날(그날이 토요일 또는 공휴일인 경우에는 그 전날을 말한다)까지 관할 고등검찰청에 별지 제5호서식의 심의신청 철회서를 제출하여 심의신청을 철회할 수 있다.', 7935);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13707, '② 사법경찰관이 심의신청 후 심의위원회의 회의가 개최되기 전에 심의대상 영장과 동일한 내용의 영장(범죄사실 또는 영장에 의한 강제처분의 범위가 추가된 경우를 포함한다)을 담당검사에게 다시 신청한 경우에는 심의신청을 철회한 것으로 본다. 이 경우 사법경찰관은 영장을 다시 신청할 때 그 신청사실을 관할 고등검찰청에 통보해야 한다.', 7935);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13708, '③ 제14조제1항 또는 제2항에 따라 심의신청이 철회된 경우에는 위원회의 회의를 개최하지 않는다.', 7935);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13709, '① 간사는 심의신청이 접수되면 지체 없이 그 사실을 담당검사가 소속된 검찰청의 장과 위원장에게 각각 통보하고 제13조제2항에 따른 심의신청서 부본 1부, 사건기록 등본 1부 및 제17조제1항에 따른 의견서 부본 1부를 해당 검찰청에 송부해야 한다.', 7937);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13710, '② 간사는 접수된 심의신청의 대상이 구속영장인 경우에는 지체 없이 심의신청 접수사실을 별지 제6호서식에 따라 해당 안건의 피의자 또는 변호인에게 통보해야 한다.', 7937);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13711, '③ 간사는 제13조제2항에 따른 심의신청서, 사건기록 등본 및 제17조제1항에 따른 의견서 등을 참고하여 별지 제7호서식의 심의안건 요지서 등 심의위원회의 회의에 필요한 자료를 작성해야 한다.', 7937);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13712, '① 심의신청을 한 사법경찰관은 심의위원회에 의견서를 제출할 수 있다. 이 경우 심의신청을 할 때 의견서 원본 및 부본 각 1부를 심의위원회에 제출해야 한다.', 7938);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13713, '② 심의신청을 한 사법경찰관은 법 제221조의5제4항에 따라 심의위원회에 출석하여 의견을 개진하려는 경우 심의위원회의 회의가 개최되기 2일(토요일과 공휴일은 제외한다) 전까지 그 출석의사를 심의위원회에 서면으로 통지해야 한다.', 7938);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13714, '③ 심의신청을 한 사법경찰관 외에 영장 신청의 검토 또는 결재에 관여한 사실이 수사기록에 명백히 드러나는 사법경찰관은 심의위원회에 출석하여 의견을 개진할 수 있다. 이 경우 그 출석의사는 심의신청을 한 사법경찰관이 심의위원회의 회의가 개최되기 2일(토요일과 공휴일은 제외한다) 전까지 심의위원회에 서면으로 통지해야 한다.', 7938);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13715, '① 담당검사는 심의위원회에 의견서를 제출할 수 있다. 이 경우 담당검사는 제16조제1항에 따른 통보가 있은 날부터 5일(토요일과 공휴일은 제외한다) 이내에 의견서 원본 및 부본 각 1부를 심의위원회에 제출해야 한다.', 7939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13716, '② 담당검사는 심의위원회에 출석하여 의견을 개진할 수 있다. 이 경우 담당검사는 심의위원회의 회의가 개최되기 2일(토요일과 공휴일은 제외한다) 전까지 그 출석의사를 심의위원회에 서면으로 통지해야 한다.', 7939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13717, '① 위원장은 심의신청이 접수된 날부터 10일(토요일과 공휴일은 제외한다) 이내에 심의위원회의 회의를 소집해야 한다.', 7941);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13718, '② 간사는 심의위원회의 회의 개최일이 정해지면 지체 없이 담당검사와 심의신청을 한 사법경찰관에게 통보해야 한다.', 7941);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13719, '③ 심의위원회의 회의는 심의위원 과반수의 출석으로 개의(開議)한다.', 7941);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13720, '④ 심의위원회의 회의는 비공개로 진행한다.', 7941);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13721, '① 위원은 심의위원회에 출석한 담당검사와 사법경찰관에게 질의할 수 있다.', 7942);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13722, '② 위원장은 담당검사와 사법경찰관이 함께 출석한 경우에는 의견 개진 및 질의를 분리하여 진행해야 한다.', 7942);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13723, '③ 제2항의 경우 의견 개진 및 질의는 사법경찰관, 담당검사의 순으로 진행한다. 다만, 위원장은 심의위원회의 회의 진행을 위해 필요한 경우 그 순서를 달리 정할 수 있다.', 7942);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13724, '④ 위원장은 사법경찰관 또는 담당검사가 제17조제1항 또는 제18조제1항에 따라 의견서를 제출한 경우에는 심의위원이 그 내용 및 취지를 충분히 알 수 있도록 필요한 조치를 해야 한다.', 7942);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13725, '① 심의위원회가 영장 청구 여부에 대하여 심의하는 기준시점은 다음 각 호의 구분에 따른다.', 7943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13726, '② 위원장은 심의위원회의 심의가 신속하고 공정하게 이루어질 수 있도록 최대한 노력해야 한다.', 7943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13727, '③ 영장 청구 여부에 대한 심의위원회의 의결은 무기명 비밀투표로 하며, 영장 청구가 적정하다는 의견을 출석심의위원 과반수의 찬성으로 의결한다.', 7943);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13728, '① 심의위원회는 심의가 종료되면 별지 제8호서식의 심의의견서(이하 "심의의견서"라 한다)를 작성해야 한다.', 7944);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13729, '② 심의위원회의 심의에 참여한 위원은 제1항에 따라 작성한 심의의견서에 서명 또는 날인한다.', 7944);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13730, '③ 심의위원회의 의결 결과와 다른 의견을 가진 심의위원은 본인의 의견과 그 이유를 적은 서면을 심의의견서 뒤에 첨부할 수 있다.', 7944);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13731, null, 7945);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13732, '① 각 고등검찰청 검사장은 담당검사가 소속된 검찰청의 장과 심의신청을 한 사법경찰관 소속 경찰관서의 장에게 별지 제9호서식에 따라 심의위원회의 심의 결과 및 심의의견별 심의위원 수를 통보해야 한다.', 7946);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13733, '② 담당검사와 사법경찰관은 심의위원회의 심의 결과를 존중해야 한다.', 7946);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13734, '③ 사법경찰관은 제1항에 따라 심의 결과를 통보받은 경우 이를 수사기록에 편철해야 한다.', 7946);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13735, '① 누구든지 심의위원회의 심의 여부 및 내용, 심의대상 영장과 관련된 사건에 관한 사항, 심의의견서 등 심의 관련 서류 및 심의위원회의 심의에 참여한 위원 명단을 외부에 공개해서는 안 된다.', 7948);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13736, '② 제1항에도 불구하고 다음 각 호의 사유가 있는 경우에는 심의위원회의 의결을 거쳐 심의 관련 사항을 공개할 수 있다. 다만, 이 경우에도 심의위원회의 심의에 참여한 위원 명단은 공개할 수 없다.', 7948);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13737, '③ 제2항의 경우 심의위원회는 출석심의위원 3분의 2 이상의 찬성으로 공개 여부를 의결한다.', 7948);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13738, null, 7953);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13739, '①국가정보원장은 몰수금품 중 첩보공작상 또는 공익상 필요하다고 인정되는 금품의 일부 또는 전부를 국무회의의 심의를 거쳐 대통령의 승인을 얻어 이를 직접사용 또는 처분할 수 있다. <개정 1963.12.16, 1997.12.13, 1999.1.21, 2018.12.18>', 7954);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13740, '②국가정보원장은 제1항에 따라 직접사용한 몰수금품 중 대한민국화폐에 대하여는 그와 같은 금액을 국가정보원 세출금 중에서 공제하여 이를 국고에 납부하여야 한다. <개정 1997.12.13, 1999.1.21, 2018.12.18>', 7954);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13741, '①국가정보원장은 전조의 규정에 의하여 통보받은 몰수금품중 법 제3조제1항의 규정에 의하여 직접 사용 또는 처분이 필요하다고 인정되는 금품이 있을 때에는 통보를 받은 날로부터 30일이내에 그 송부를 별지 제2호서식에 의하여 관계 각급 검사장에게 요청하여야 한다. <개정 1999.3.31>', 7958);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13742, '②국가정보원장은 통보받은 몰수금품중에 직접 사용 또는 처분할 금품이 없다고 인정되는 때에도 전항의 기간내에 그 뜻을 관계 각급 검사장에게 통보하여야 한다. <개정 1999.3.31>', 7958);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13743, '①국가정보원장이 법 제3조제1항의 규정에 의한 대통령의 승인을 얻고자 할 때에는 다음 각호의 사항을 기재한 문서로써 하여야 한다. <개정 1999.3.31>', 7960);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13744, '②전항의 규정에 의하여 대통령의 승인을 얻은 후 그 몰수금품의 사용 또는 처분의 목적을 변경하고자 할 때의 승인절차도 전항에 준한다.', 7960);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13745, '① 각급 검찰청의 장(지청의 장은 제외한다. 이하 같다)은 전문적인 지식과 경험을 가진 사람 중에서 전문수사자문위원 후보자를 선정하여 그 명단을 관리한다.', 7964);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13746, '② 각급 검찰청의 장은 전문수사자문위원 후보자를 선정하기 위하여 다른 국가기관, 공공단체, 교육기관, 연구기관 등에 후보자의 추천을 의뢰할 수 있다.', 7964);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13747, '① 검사는 수사 진행, 구속영장 청구, 사건(항고사건을 포함한다)의 기소 등 수사절차의 모든 단계에서 공소제기 여부와 관련된 사실관계를 분명하게 하기 위하여 필요한 경우 직권이나 피의자 또는 변호인의 신청에 의하여 구두 또는 별지 제1호서식의 지정결정서로 전문수사자문위원을 지정하여 수사절차에 참여하게 하고 설명이나 의견을 들을 수 있다.', 7965);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13748, '② 전문수사자문위원은 관련 서류를 검토하거나, 피의자ㆍ피해자 또는 그 밖의 참고인의 진술을 듣는 자리에 동석하는 등 수사절차에 참여하여 설명하거나 의견을 진술할 수 있다.', 7965);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13749, '③ 검사는 제1항에 따른 전문수사자문위원 지정 사실을 피의자 또는 변호인에게 구두 또는 별지 제2호서식의 통지서로 알려야 한다.', 7965);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13750, null, 7966);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13751, '① 검사는 전문수사자문위원이 제4조 각 호의 어느 하나에 해당하거나 직무상 알게 된 비밀을 누설한 경우에는 전문수사자문위원 지정을 취소하여야 한다.', 7967);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13752, '② 검사는 전문수사자문위원이 다음 각 호의 어느 하나에 해당할 때에는 지정을 취소할 수 있다.', 7967);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13753, '③ 전문수사자문위원의 지정 취소는 구두 또는 별지 제3호서식의 지정취소결정서로 한다. 검사는 전문수사자문위원 지정 취소 사실을 피의자 또는 변호인에게 구두 또는 별지 제2호서식의 통지서로 알려야 한다.', 7967);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13754, '① 「형사소송법」 제245조의3제3항에 따라 전문수사자문위원의 지정에 관하여 이의를 제기하려는 피의자 또는 변호인은 별지 제4호서식의 이의신청서에 이의 사유를 소명하는 자료를 첨부하여 수사를 담당하는 검사에게 제출하여야 한다.', 7968);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13755, '② 검사는 제1항의 이의신청서를 접수한 경우 이에 대한 의견을 기재하여 관할 고등검찰청 검사장에게 송부하여야 한다. 다만, 검사가 이의신청이 이유 있다고 인정하여 전문수사자문위원의 지정을 취소하는 경우에는 그러하지 아니하다.', 7968);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13756, '③ 고등검찰청 검사장은 제2항의 이의신청서를 송부 받은 경우 신속하게 심사하여 다음 각 호의 구분에 따라 결정하여 별지 제5호서식의 결정서를 수사 검사에게 송부하고, 피의자 또는 변호인에게 별지 제6호서식의 이의신청 결정통지서로 그 결과를 알려야 한다.', 7968);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13757, '① 전문수사자문위원의 일당 및 수당은 예산의 범위에서 법무부장관이 정한다.', 7970);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13758, '② 전문수사자문위원의 국내 여비와 숙박료는 「공무원여비규정」 제10조부터 제13조까지 및 제16조제1항의 별표 2 국내여비지급표의 제2호 해당자 소정액 이내로 한다.', 7970);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13759, '③ 전문수사자문위원이 국외여행하는 경우의 여비와 숙박료는 「공무원여비규정」 제10조제2항, 제11조제2항, 제13조제2항의 액수 이내, 제12조제2항의 별표 3 국외항공운임정액표의 "기타의 자" 해당자 소정액 이내, 제16조제1항의 별표 4 국외여비정액표의 "7. 별표 1의 제2호 가목 해당자" 소정액 이내로 한다.', 7970);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13760, null, 7974);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13761, '① 위원장은 심의회를 소집하고, 그 회의의 의장이 된다.', 7976);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13762, '② 심의회의 회의는 위원장을 포함한 재적위원 과반수의 출석과 출석위원 3분의 2 이상의 찬성으로 의결한다.', 7976);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13763, '③ 보상금을 결정할 때 액수에 관한 의견이 세 가지 이상으로 나누어져 각각 3분의 2에 이르지 못하는 경우에는 3분의 2에 이르기까지 최저금액의 의견 수에 차례로 많은 금액의 의견 수를 더하여 그 중 가장 많은 금액의 의견에 따른다.', 7976);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13764, '① 법무부장관은 각 심의회를 지휘ㆍ감독하기 위하여 필요한 명령이나 조치를 할 수 있다.', 7978);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13765, '② 법무부장관은 제1항에 따른 직무를 수행하기 위하여 필요하다고 인정할 때에는 소속 직원 또는 각급 검찰청의 검사로 하여금 각 심의회의 업무처리를 감사(監査)하게 할 수 있다.', 7978);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13766, '① 법 제28조제2항에 따른 피의자 보상청구서(이하 "청구서"라 한다)에는 다음 각 호의 사항을 적고 청구인이 기명날인하거나 전자서명을 하여야 한다.', 7979);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13767, '② 청구서에는 청구이유를 소명할 수 있는 증거자료를 첨부하여야 한다. 이 경우 심의회는 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 청구인의 주민등록표 등본을 확인하여야 하며, 청구인이 확인에 동의하지 아니하는 경우에는 이를 첨부하게 하여야 한다.', 7979);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13768, '① 위원장이나 위원장의 명을 받은 사람은 보상결정에 필요한 조사를 할 수 있고, 관계 공무원이나 관계 기관에 사실을 조회하거나 필요한 자료의 제출을 요청할 수 있다.', 7980);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13769, '② 제1항의 요청을 받은 공무원이나 관계 기관의 장은 정당한 사유 없이 요청에 따르지 아니하거나 회신을 지체해서는 아니 된다.', 7980);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13770, '① 보상결정은 믿을 수 있는 증거자료에 의하여 이루어져야 한다.', 7981);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13771, '② 보상결정서에는 다음 각 호의 사항을 적고 회의에 출석한 위원이 기명날인하여야 한다.', 7981);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13772, '③ 심의회가 보상결정을 하였을 때에는 보상결정서 원본을 보관하고 청구인에게 보상결정통지서와 보상결정서 정본(正本) 1부를 보내야 한다.', 7981);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13773, null, 7982);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13774, '① 법 제30조에 따른 무죄재판사건을 기소한 검찰청(지방검찰청 지청을 포함한다)의 장은 무죄재판서 게재 업무를 담당할 전담직원을 지정할 수 있다.', 7984);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13775, '② 제1항의 전담직원은 무죄재판서 게재에 관한 장부를 작성하고, 매년 1회 이상 그 업무처리 상황을 법무부장관에게 보고하여야 한다.', 7984);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13776, null, 7987);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13777, '① 교정법인이 법 제11조제2항에 따라 임원의 취임 승인을 신청하는 경우에는 임원 취임 승인신청서에 다음 각 호의 서류를 첨부하여 법무부장관에게 제출하여야 한다. 다만, 연임되는 임원에 대한 취임 승인을 신청하는 경우에는 제2호의 서류는 제출하지 아니한다. <개정 2010.8.3>', 7988);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13778, '② 삭제 <2010.8.3>', 7988);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13779, '① 교정법인이 법 제14조제2항에 따라 기본재산의 매도ㆍ증여 또는 교환에 관한 허가를 받거나 신고를 하려는 경우에는 그 허가신청서 또는 신고서에 다음 각 호의 서류를 첨부하여 법무부장관에게 제출하여야 한다. <개정 2017.4.21, 2025.5.27>', 7989);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13780, '② 교정법인이 법 제14조제2항에 따라 기본재산의 담보 제공에 관한 허가를 받거나 신고를 하려는 경우에는 그 허가신청서 또는 신고서에 다음 각 호의 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 7989);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13781, '③ 교정법인이 법 제14조제2항에 따라 기본재산에 대하여 용도 변경, 의무의 부담 또는 권리의 포기에 관한 허가를 받거나 신고를 하려는 경우에는 그 허가신청서 또는 신고서에 그 사유를 분명히 기록하여야 한다.', 7989);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13782, '① 교정법인이 법 제16조제2항 및 같은 법 시행령(이하 "영"이라 한다) 제13조에 따라 사업계획과 예산을 제출할 때에는 다음 각 호의 서류를 첨부하여야 한다.', 7990);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13783, '② 교정법인이 법 제16조제2항 및 영 제13조에 따라 사업실적과 결산을 보고할 경우에는 다음 각 호의 서류를 첨부하여야 한다.', 7990);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13784, '① 교정법인의 예산은 법 제15조에 따른 회계별로 구분하여 추정 대차대조표 및 그 부속명세서와 추정 손익계산서 및 그 부속명세서로 편성한다.', 7991);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13785, '② 제1항의 추정 대차대조표는 해당 연도 말 현재에 추정되는 재정상태를 표시하되, 전년도 말 현재와의 비교증감을 표시하여야 한다.', 7991);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13786, '③ 제1항의 추정 손익계산서에는 해당 연도에 발생할 것으로 추정되는 모든 수익과 비용을 계상(計上)하되, 전년도의 수익과 비용을 비교ㆍ표시하여야 한다.', 7991);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13787, '④ 제1항의 추정 대차대조표 및 추정 손익계산서의 부속명세서에는 각각 그 추정의 근거를 명백히 하여야 한다.', 7991);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13788, '① 교정법인이 법 제17조제1항제1호 및 제2호에 따른 합병 또는 분할합병의 인가를 신청하는 경우에는 합병(분할합병을 포함한다. 이하 같다)인가 신청서에 다음 각 호의 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 7993);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13789, '② 제1항제5호의 재산목록은 기본재산과 보통재산으로 구분하여 작성하여야 한다.', 7993);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13790, '③ 교정법인이 분할에 의하여 1개 또는 여러 개의 교정법인을 설립함과 동시에 분할합병하려는 경우에는 그 합병인가 신청서에 제1항 각 호의 서류 외에 제10조제1호부터 제4호까지의 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 7993);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13791, null, 7994);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13792, null, 7995);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13793, '① 법무부장관이 교정법인의 합병 또는 분할의 인가를 하는 경우 다음 각 호의 조건을 붙일 수 있다.', 7996);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13794, '② 법무부장관이 교정법인의 해산인가를 하는 경우 다음 각 호의 조건을 붙일 수 있다.', 7996);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13795, '① 교정법인이 법 제22조제1항에 따른 시설검사를 받으려는 경우 검사를 받으려는 날의 30일 전까지 시설검사 신청서에 공사일정에 관한 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 7997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13796, '② 법무부장관은 법 제22조제1항에 따라 시설검사를 하기 위하여 필요하다고 인정되는 경우에는 소속 공무원에게 이를 검사하게 하거나, 외부의 건축ㆍ토목전문가 등에게 검사를 대행하게 할 수 있다.', 7997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13797, '③ 제2항에 따라 검사를 하려는 경우에는 그 권한을 표시하는 증표를 지니고, 이를 관계인에게 보여주어야 한다.', 7997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13798, '④ 법무부장관이 법 제22조제1항 또는 법 제34조제2항에 따른 검사를 하려는 경우에는 미리 검사의 목적ㆍ대상 및 기간을 정하여 해당 교정법인 또는 민영교도소등의 장에게 통지하여야 한다.', 7997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13799, null, 7998);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13800, '① 법 제23조에 따라 교정법인에 지급할 경비는 「국가재정법」에 따른 일반회계에 속하는 해당 연도 교정행정 예산의 총액과 그 예산에 계상된 수용인원을 기준으로 1인당 수용경비를 산정하고, 위탁수용 대상자의 인원과 특성 등을 고려하여 위탁계약으로 정한다. 다만, 교도작업에 필요한 경비의 지급은 위탁계약에서 정하는 바에 따른다.', 7999);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13801, '② 제1항에 따라 지급하는 운영 경비는 국가가 운영하는 교도소ㆍ소년교도소 또는 구치소 및 그 지소(이하 "교도소등"이라 한다)에 대한 예산ㆍ자금배정 시기 및 방법에 준하여 지급한다. <개정 2022.2.7>', 7999);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13802, '① 교정법인이 교도소등의 설치비용을 부담한 경우에는 제15조에 따른 경비 외에 위탁계약에서 정하는 바에 따라 해당 교도소등의 설치비용과 그에 대한 이자를 계약기간 중 매년 나누어 지급할 수 있다.', 8000);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13803, '② 교정법인이 제1항에 따라 교도소등의 설치비용을 지급받는 경우에는 그 지급이 완료됨과 동시에 교도소등의 부지 및 건축물과 그 부대시설ㆍ장비 등의 소유를 국유로 이전하는 데 필요한 조치를 하여야 한다.', 8000);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13804, '① 교정법인은 법 제29조제1항 단서에 따라 민영교도소등의 장 및 직원의 임명승인을 받으려는 경우에는 그 승인신청서에 다음 각 호의 서류를 첨부하여야 한다. <개정 2010.8.3>', 8001);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13805, '② 삭제 <2010.8.3>', 8001);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13806, '③ 교정법인은 법 제29조제1항 단서에 따라 민영교도소등의 장 및 직원의 면직승인을 받으려는 경우에는 그 승인신청서에 다음 각 호의 서류를 첨부하여야 한다.', 8001);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13807, '① 법무부장관은 법 제33조제2항에 따라 파견한 소속공무원에게 민영교도소등의 직원에 대하여 매주 1시간의 범위에서 직무수행에 필요한 교육을 실시하게 할 수 있다.', 8003);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13808, '② 민영교도소등의 장은 소속 직원에 대하여 법 제33조제3항에 따른 직무수행에 필요한 교육을 매주 1시간 이상 실시하여야 한다.', 8003);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13809, '③ 법무부장관은 직원연수ㆍ업무협조 등을 위하여 민영교도소등의 장이 요청하는 경우에는 민영교도소등의 직원을 국가가 운영하는 교도소등에 일정기간 근무하게 할 수 있다.', 8003);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13810, '① 민영교도소등의 직원이 착용할 제복의 종류 및 제작 양식과 그 착용 방법은 교정공무원 복제(服制)에 관한 규정을 준용하여 해당 민영교도소등의 장이 정하되, 법무부장관의 승인을 받아야 한다. <개정 2018.7.13, 2022.2.7>', 8004);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13811, '② 민영교도소등의 장은 제1항에 따른 복제를 정하는 경우 계급 및 소속 기관의 표시 등을 교정직공무원의 것과 구별되도록 하여야 한다.', 8004);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13812, '③ 민영교도소등의 장은 교화ㆍ분류심사ㆍ교육훈련 등 직무상 필요한 경우와 근무지역의 여건상 필요하다고 인정되는 경우에는 소속 직원에게 근무 중 사복을 착용하게 할 수 있다.', 8004);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13813, '① 민영교도소등의 직원의 신분증명서는 민영교도소등의 장이 발행하되, 그 제작 양식은 법무부장관의 승인을 받아야 한다. <개정 2022.2.7>', 8005);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13814, '② 민영교도소등의 직원은 근무 중 신분증명서를 지녀야 한다.', 8005);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13815, '① 민영교도소등의 장이 법 제31조제2항에 따라 무기 및 탄약을 배정받으려는 경우에는 무기 및 탄약의 종류ㆍ수량 등을 명시하여 매년 2월 말까지 법무부장관에게 신청하여야 한다.', 8006);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13816, '② 법무부장관은 제1항에 따른 신청을 검토하여 민영교도소등의 운영에 필요하다고 인정되는 범위에서 무기 및 탄약을 구입하여 배정한다.', 8006);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13817, '③ 제2항에 따라 무기 및 탄약을 배정받은 민영교도소등의 장은 위탁계약에서 달리 정한 경우를 제외하고는 국가가 운영하는 교도소 등에서의 보안장비의 관리 및 사용에 관하여 법무부장관이 정한 지침에 따라 이를 관리하여야 한다.', 8006);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13818, '① 민영교도소등의 장은 소속 직원에 관한 다음 각 호의 장부와 서류를 갖춰 두어야 한다.', 8007);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13819, '② 민영교도소등의 장은 수용자관리에 관한 다음 각 호의 장부와 서류를 갖춰 두어야 한다.', 8007);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13820, '① 「치료감호 등에 관한 법률」(이하 "법"이라 한다) 제4조에 따른 치료감호청구서는 별지 제1호서식과 같다. 다만, 공소를 제기하면서 동시에 치료감호를 청구할 때에는 별지 제2호서식의 공소장 및 치료감호청구서로 하여야 한다. <개정 2014.1.29, 2016.12.2>', 8010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13821, '② 공소를 제기한 후에 치료감호청구를 할 때에는 치료감호사건과 병합심리할 피고사건이나 약식명령 청구사건이 계속(繫屬)되어 있는 법원명, 사건번호, 피고인 성명, 죄명 등을 분명하게 적어 병합심리를 신청하여야 한다.', 8010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13822, '③ 공소를 제기하지 아니하고 치료감호청구만을 할 때에는 치료감호사건과 동시에 심리할 수 있었던 피의사건의 사건번호를 적는다.', 8010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13823, '④ 제1항 본문에 따른 치료감호청구서와 같은 항 단서에 따른 공소장 및 치료감호청구서에는 다음 각 호의 서류를 첨부하여야 한다. <개정 2024.5.21>', 8010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13824, '① 검사와 사법경찰관리는 법 제5조에 따라 치료감호대상자를 조사할 때 다음 각 호의 사항에 유의하여야 한다. <개정 2016.12.2>', 8011);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13825, '② 제1항제1호의 전과 및 치료감호경력을 조사할 때에는 형 및 치료감호의 판결법원, 판결 연월일, 죄명, 형명(刑名), 형기(刑期)와 치료감호기간, 형 집행사항과 치료감호의 집행사항을 명백히 조사하여야 한다.', 8011);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13826, '① 사법경찰관이 치료감호에 처(處)함이 상당하다고 인정되는 사건(이하 "치료감호대상사건"이라 한다)을 검찰청에 송치할 때에는 의견서에 적용법조와 치료감호를 청구함이 상당하다고 인정되는 이유 및 의견을 덧붙여 적어야 한다. 이 경우 법 제2조제1항제3호에 따른 치료감호대상자에 대하여는 검찰청에 송치하기 전에 정신과 등의 전문의의 진단이나 감정을 받아야 한다.', 8013);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13827, '② 제1항의 경우 사건송치서의 의견란에 괄호를 하고, 붉은색으로 "치료감호"라고 적어야 한다.', 8013);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13828, '③ 제1항의 송치서류에는 범죄경력 자료 등 치료감호의 요건이 되는 사실을 증명하는 서류를 첨부하여야 한다.', 8013);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13829, '④ 치료감호대상사건을 송치할 때에 제3항에 따른 서류를 첨부하지 못한 경우에는 사건송치서의 비고란에 그 사유를 적고, 사건을 송치한 후에 새로운 치료감호의 요건이 되는 사실이 발견된 경우에는 즉시 그 사실을 검사에게 보고하여야 한다.', 8013);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13830, '① 지방검찰청 검사장 또는 지청장은 치료감호대상자에 대하여 치료감호청구를 한 때에는 지체 없이 법무부장관과 상급 검찰청의 장에게 그 사실을 보고하여야 한다.', 8015);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13831, '② 제1항의 치료감호청구사건에 대하여 재판이 확정된 때에는 그 법원에 대응하는 검찰청의 장은 지체 없이 법무부장관과 상급 검찰청의 장에게 그 사실을 보고하여야 한다.', 8015);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13832, '① 법 제16조제3항에 따른 치료감호 기간의 연장 신청은 별지 제5호의2서식에 따른다.', 8017);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13833, '② 법 제16조제3항에 따른 치료감호 기간의 연장 청구는 별지 제5호의3서식에 따른다.', 8017);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13834, '③ 법원이 법 제16조제3항에 따라 치료감호 기간의 연장을 결정한 경우 검사의 집행 지휘는 별지 제5호의4서식에 따른다. 다만, 법원이 검사의 청구를 기각한 경우에는 검사는 그 결정문 사본을 치료감호시설의 장에게 송부하여야 한다.', 8017);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13835, '① 법 제17조에 따른 치료감호의 집행 지휘는 별지 제6호서식의 치료감호집행지휘서로 하여야 한다.', 8019);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13836, '② 법 제21조제2항에 따른 치료감호집행장은 별지 제7호서식과 같다.', 8019);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13837, '① 치료감호와 형이 병과(倂科)된 경우에는 먼저 치료감호의 집행을 지휘하고, 그 치료감호 집행지휘서의 비고란에 병과된 형의 내용을 붉은색으로 적어야 한다.', 8020);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13838, '② 치료감호시설의 장은 형이 병과된 치료감호를 선고받은 자(이하 "피치료감호자"라 한다)에 대하여 치료감호의 종료가 결정되었으나 남은 형기가 있을 때에는 즉시 치료감호의 집행을 지휘한 지방검찰청 또는 지청의 검사에게 치료감호의 종료와 남은 형기 등 형의 집행 지휘에 필요한 사항을 통보하여야 한다. <개정 2014.1.29>', 8020);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13839, '③ 법 제37조에 따른 치료감호심의위원회가 치료감호의 가종료에 관련된 사항으로서 피치료감호자에 대한 치료감호의 집행을 정지하고 치료감호와 병과된 형 외의 자유형 또는 노역장유치(이하 이 조에서 "자유형등"이라 한다)를 먼저 집행할 필요가 있다고 심사ㆍ결정한 경우 치료감호시설의 장은 치료감호시설 소재지를 관할하는 지방검찰청 또는 지청의 검사에게 해당 피치료감호자에 대한 치료감호의 집행을 정지하고 먼저 자유형등의 집행을 지휘해줄 것을 요청할 수 있다. <신설 2023.5.4>', 8020);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13840, '④ 제3항에 따른 요청을 받은 검사는 소속 검찰청의 장의 허가를 받아 해당 피치료감호자에 대한 치료감호의 집행을 정지하고 먼저 자유형등의 집행을 지휘할 수 있다. <신설 2023.5.4>', 8020);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13841, '⑤ 제3항에 따른 요청은 별지 제6호의2서식에 따르고, 제4항에 따른 지휘는 별지 제6호의3서식에 따른다. <신설 2023.5.4>', 8020);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13842, '① 영 제5조제1항에 따른 치료감호시설의 장의 보고는 별지 제8호서식에 따른다.', 8021);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13843, '② 영 제5조제2항에 따른 지정법무병원의 장의 보고는 별지 제8호의2서식에 따른다.', 8021);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13844, '① 법 제23조제3항에 따라 치료를 위탁받은 피치료감호자의 법정대리인, 배우자, 직계존속, 형제자매(이하 "법정대리인등"이라 한다)가 제출할 서약서에는 치료받을 병원의 장이 확인한 입원보증서, 법정대리인등과 피치료감호자와의 관계 및 입원치료의 능력을 소명하는 자료를 첨부하여야 한다.', 8023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13845, '② 제1항의 서약서는 별지 제9호서식과 같다.', 8023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13846, '① 보호관찰관이 영 제9조제2항에 따라 보호관찰을 받기 시작한 자(이하 "피보호관찰자"라 한다)에게 구체적인 지시를 할 때에는 별지 제11호서식의 지시서로 하여야 한다.', 8026);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13847, '② 보호관찰관이 제1항에 따른 지시를 한 때에는 그 내용을 지체 없이 검사를 거쳐 법 제37조에 따른 치료감호심의위원회(이하 "위원회"라 한다)에 보고하여야 한다.', 8026);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13848, '① 보호관찰관은 영 제9조제3항에 따라 피보호관찰자를 출석하게 하여 법 제33조에 따른 준수사항이나 그 밖에 지도ㆍ감독상 필요한 사실을 확인하는 경우 필요하다고 인정될 때에는 별지 제12호서식의 진술서를 작성하거나 피보호관찰자로 하여금 자필로 이를 작성ㆍ제출하게 할 수 있다.', 8027);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13849, '② 제1항에 따른 진술서에는 피보호관찰자가 서명하고 도장 또는 지장을 찍어야 한다. 피보호관찰자가 서명할 수 없을 때에는 보호관찰관이 대신하여 이름을 적되, 그 사유를 적고 피보호관찰자의 도장 또는 지장을 받아야 한다.', 8027);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13850, '③ 영 제9조제3항에 따라 보호관찰관이 피보호관찰자를 지도ㆍ감독하기 위하여 관계자로부터 필요한 사실을 확인하는 경우 그 진술서 작성에 관하여는 제1항과 제2항을 준용한다. 이 경우 관계자가 진술 등을 거부할 때에는 그 사유를 적어야 한다.', 8027);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13851, '① 보호관찰관은 별지 제14호서식의 신고접수부를 갖추어 영 제10조, 법 제34조제1항ㆍ제2항 또는 영 제13조제4항ㆍ제5항에 따른 신고를 접수한 때에는 그 사실을 신고접수부에 적고, 신고인에게 별지 제15호서식의 신고확인증을 발급하여야 한다. <개정 2024.5.21>', 8031);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13852, '② 영 제10조제1항제4호 또는 같은 조 제2항에 따른 신고는 별지 제16호서식의 피보호관찰자 주거이전ㆍ여행 신고서로 하여야 하며, 주거이전의 신고를 할 때에는 퇴거신고접수증 사본을 첨부하여야 한다.', 8031);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13853, '① 영 제11조의2제1항에 따른 피보호관찰자의 유치허가 신청은 별지 제16호의2서식에 따른다.', 8032);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13854, '② 영 제11조의2제2항에 따른 유치허가장은 별지 제16호의3서식에 따른다.', 8032);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13855, '① 영 제11조의4제1항에 따른 가종료 또는 치료 위탁의 취소 신청 요청과 같은 조 제3항에 따른 가종료 또는 치료 위탁의 취소 신청은 별지 제16호의4서식에 따른다. <개정 2021.4.6>', 8033);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13856, '② 위원회는 제1항의 신청에 따라 또는 직권으로 가종료 또는 치료의 위탁을 취소하는 결정을 한 때에는 해당 피보호관찰자가 수용된 교도소ㆍ구치소 또는 치료감호시설의 장과 관할 보호관찰소의 장에게 별지 제16호의5서식에 따라 통보한다. <신설 2021.4.6>', 8033);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13857, '① 보호관찰관은 영 제13조제2항에 따른 출소통보서를 접수한 때에는 지체 없이 피보호관찰자마다 별지 제17호서식의 보호관찰부를 작성하여 갖춰 두어야 한다.', 8034);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13858, '② 제1항에 따른 보호관찰부에는 피보호관찰자의 주요 동태 및 준수사항의 이행 여부와 피보호관찰자가 신고한 사항을 적는다.', 8034);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13859, '① 영 제11조제6항에 따라 주거이전 또는 여행 사실을 새 주거지 또는 여행지의 보호관찰관에게 통보할 때에는 별지 제19호서식의 피보호관찰자 주거이전ㆍ여행 통보서에 관계 서류를 첨부하여야 한다. <개정 2016.12.2>', 8036);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13860, '② 영 제11조제6항에 따라 여행 사실을 통보받은 여행지 보호관찰관은 피보호관찰자가 관할구역에 머무르는 동안 그를 보호관찰하여야 하며, 1개월마다 정기적으로 별지 제19호서식의 피보호관찰자 주거이전ㆍ여행 통보서를 작성하여 주거지 관할 보호관찰관에게 송부하여야 하고, 피보호관찰자가 죄를 범하는 등 그의 신상에 중대한 변동이 발생한 경우에는 지체 없이 그 통보서를 작성하여 주거지 관할 보호관찰관에게 송부하여야 한다. <개정 2016.12.2>', 8036);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13861, '① 영 제13조제1항에 따른 신고서는 별지 제20호서식과 같다.', 8038);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13862, '② 영 제13조제2항에 따른 출소통보서는 별지 제21호서식과 같다.', 8038);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13863, '③ 영 제13조제3항에 따른 출소 후 신고서는 별지 제22호서식과 같다.', 8038);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13864, '① 보호관찰관이 위원회로부터 가종료나 치료위탁의 취소결정서를 송달받은 때에는 지체 없이 그 내용을 치료감호시설의 장에게 통보하여야 한다. 이 경우 보호관찰관 및 치료감호시설의 장은 피보호관찰자에 대한 남은 기간의 치료감호를 집행하기 위하여 보호관찰관의 관할구역이나 치료감호시설 소재지를 관할하는 검사에게 보호구인(保護拘引)을 의뢰할 수 있다. <개정 2022.7.4>', 8039);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13865, '② 보호관찰관이 검사로부터 가종료나 치료위탁의 취소결정서를 통보받은 때에도 제1항과 같이 처리한다.', 8039);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13866, '① 법 제36조의3에 따른 외래진료(이하 "외래진료"라 한다)는 치료감호시설 출소자의 정신질환 치료를 위하여 출소일부터 10년의 범위에서 실시할 수 있다. 다만, 증상의 악화 등 외래진료가 계속 필요하다고 인정되는 경우에는 10년의 범위에서 한 차례만 그 기간을 연장할 수 있다. <개정 2022.7.4>', 8042);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13867, '② 외래진료는 치료감호시설에서 정신건강의학과의사의 진료, 검사시설에 의한 검사, 처방 및 투약 등의 방법으로 실시한다. 다만, 치료의 편의를 위하여 필요한 경우에는 원격화상장비를 이용하여 진료할 수 있다.', 8042);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13868, '③ 외래진료의 경우 치료감호시설 출소자의 증상이 악화되더라도 치료감호시설에 입소시켜 치료할 수 없다. <개정 2022.7.4>', 8042);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13869, '④ 외래진료를 실시한 치료감호시설의 장은 별지 제22호의2서식의 치료감호시설 출소자 외래진료 접수대장을 작성하여 10년간 보존하여야 한다. <개정 2022.7.4>', 8042);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13870, '① 외래진료에 필요한 비용은 법무부장관이 부담한다. 다만, 「국민건강보험법」, 「의료급여법」, 그 밖의 다른 법령에 따라 치료감호시설 출소자 또는 그 보호의무자가 부담하지 아니하는 비용은 제외한다. <개정 2022.7.4>', 8043);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13871, '② 법무부장관은 예산의 범위에서 외래진료를 실시한 지정법무병원에 제1항에 따른 외래진료비용을 지급하여야 한다.', 8043);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13872, '③ 제2항에 따라 외래진료비용을 지급받으려는 지정법무병원의 장은 별지 제22호의3서식의 외래진료비용 지급 청구서에 출소자별 진료비 계산서를 첨부하여 매달 10일까지 법무부장관에게 제출하여야 한다. <개정 2022.7.4>', 8043);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13873, '① 법 제36조의4제2항에 따른 보호관찰소의 장의 정신보건센터의 장에 대한 정보 요청은 별지 제22호의4서식에 따른다.', 8044);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13874, '② 법 제36조의4제3항에 따른 정신보건센터의 장의 보호관찰소의 장에 대한 협조 요청은 별지 제22호의5서식에 따른다.', 8044);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13875, '① 법 제43조제1항 및 영 제17조제1항에 따라 검사가 심사ㆍ결정을 신청할 때에는 별지 제23호서식으로 하여야 한다.', 8049);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13876, '② 법 제43조제2항에 따라 치료감호시설의 장이나 보호관찰관이 의견을 제출할 때에는 별지 제24호서식으로 하여야 한다.', 8049);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13877, '③ 법 제43조제3항에 따라 치료감호시설의 장이나 보호관찰소의 장이 검사에게 위원회에 심사ㆍ결정을 신청해 줄 것을 요청할 때에는 별지 제25호서식으로 하여야 한다. 다만, 보호관찰소의 장이 검사에게 가종료 또는 치료 위탁의 취소 신청을 요청할 때에는 별지 제16호의4서식에 따른다. <개정 2024.5.21>', 8049);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13878, '④ 법 제44조제2항에 따라 피치료감호자와 그 법정대리인등이 위원회에 치료감호의 종료 여부에 대한 심사를 신청할 때에는 별지 제26호서식으로 하여야 한다.', 8049);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13879, '⑤ 영 제18조제2항에 따라 치료감호시설의 장이 의견을 제출할 때에는 별지 제27호서식으로 하여야 한다. <개정 2014.1.29>', 8049);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13880, '① 위원회가 한 사람에게 2건 이상의 결정서를 동시에 송달할 때에는 1부의 송달서류만으로 할 수 있다. 검사가 치료감호시설의 장이나 보호관찰관에게 통보할 때에도 또한 같다. <개정 2014.1.29>', 8051);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13881, '② 위원회가 가종료 또는 치료위탁으로 출소하는 피보호관찰자에게 부과하는 준수사항은 치료감호시설의 장을 통하여 보호관찰관에게 송달할 수 있다. <개정 2014.1.29>', 8051);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13882, null, 8053);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13883, null, 8054);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13884, '① 검사가 위원회에 심사신청한 치료감호사안에 관한 조사기록은 그 소속 지방검찰청 또는 지청에서 보존하고, 그 외의 치료감호사안에 관한 조사기록은 위원회에서 보존한다.', 8056);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13885, '② 제1항에 따라 검찰청에 보존 중인 치료감호사안 조사기록은 피치료감호자가 이감된 경우에는 이감된 감호소의 소재지를 관할하는 지방검찰청 또는 지청에 송부하여야 한다.', 8056);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13886, '① 법무부장관은 다음 각 호의 시설ㆍ기관 또는 단체 중에서 법 제44조의7제1항에 따른 치료기관(이하 "치료기관"이라 한다)을 지정할 수 있다. 다만, 제2호 및 제3호의 기관을 치료기관으로 지정하려는 경우에는 해당 기관의 장과 협의를 하여야 한다. <개정 2021.4.6>', 8059);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13887, '② 법무부장관은 치료기관의 시설이나 치료 프로그램이 치료명령을 선고받은 사람의 치료와 상태 개선에 부적당하다고 판단하는 경우에는 치료기관의 지정을 취소할 수 있다. 다만, 치료기관이 다음 각 호의 어느 하나에 해당하는 경우에는 지정을 취소하여야 한다.', 8059);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13888, '③ 제1항 및 제2항에서 규정한 사항 외에 치료기관의 지정 및 지정 취소 등에 대한 세부 사항은 법무부장관이 정한다.', 8059);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13889, '① 보호관찰소의 장은 영 제32조제5항 전단에 따라 자료의 제출을 요청할 때에는 별지 제32호서식의 자료제출 요청서를 국가, 지방자치단체 및 「공공기관의 운영에 관한 법률」 제4조에 따른 공공기관에 보내야 한다.', 8061);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13890, '② 영 제32조제5항 후단에 따른 신청인의 동의서는 별지 제33호서식에 따른다.', 8061);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13891, '① 영 제34조제1항에 따른 기부금품의 접수 영수증은 「법인세법 시행규칙」 제82조제7항제3호의3의 별지 제63호의3서식에 따른다. <개정 2016.12.2>', 8062);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13892, '② 영 제34조제5항에 따른 기부금품의 접수현황 및 사용실적 등에 관한 장부는 별지 제34호서식에 따른다. <개정 2016.12.2>', 8062);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13893, null, 8064);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13894, '① 검사와 사법경찰관은 다음 각 호의 요건을 모두 갖춘 특정중대범죄사건의 피의자의 얼굴, 성명 및 나이(이하 "신상정보"라 한다)를 공개할 수 있다. 다만, 피의자가 미성년자인 경우에는 공개하지 아니한다.', 8066);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13895, '② 검사와 사법경찰관은 제1항에 따라 신상정보 공개를 결정할 때에는 범죄의 중대성, 범행 후 정황, 피해자 보호 필요성, 피해자(피해자가 사망한 경우 피해자의 유족을 포함한다)의 의사 등을 종합적으로 고려하여야 한다.', 8066);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13896, '③ 검사와 사법경찰관은 제1항에 따라 신상정보를 공개할 때에는 피의자의 인권을 고려하여 신중하게 결정하고 이를 남용하여서는 아니 된다.', 8066);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13897, '④ 제1항에 따라 공개하는 피의자의 얼굴은 특별한 사정이 없으면 공개 결정일 전후 30일 이내의 모습으로 한다. 이 경우 검사와 사법경찰관은 다른 법령에 따라 적법하게 수집ㆍ보관하고 있는 사진, 영상물 등이 있는 때에는 이를 활용하여 공개할 수 있다.', 8066);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13898, '⑤ 검사와 사법경찰관은 제1항에 따라 피의자의 얼굴을 공개하기 위하여 필요한 경우 피의자를 식별할 수 있도록 피의자의 얼굴을 촬영할 수 있다. 이 경우 피의자는 이에 따라야 한다.', 8066);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13899, '⑥ 검사와 사법경찰관은 제1항에 따라 피의자의 신상정보 공개를 결정하기 전에 피의자에게 의견을 진술할 기회를 주어야 한다. 다만, 신상정보공개심의위원회에서 피의자의 의견을 청취한 경우에는 이를 생략할 수 있다.', 8066);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13900, '⑦ 검사와 사법경찰관은 피의자에게 신상정보 공개를 통지한 날부터 5일 이상의 유예기간을 두고 신상정보를 공개하여야 한다. 다만, 피의자가 신상정보 공개 결정에 대하여 서면으로 이의 없음을 표시한 때에는 유예기간을 두지 아니할 수 있다.', 8066);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13901, '⑧ 검사와 사법경찰관은 정보통신망을 이용하여 그 신상정보를 30일간 공개한다.', 8066);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13902, '⑨ 신상정보의 공개 등에 관한 절차와 방법 등 그 밖에 필요한 사항은 대통령령으로 정한다.', 8066);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13903, '① 검사는 공소제기 시까지 특정중대범죄사건이 아니었으나 재판 과정에서 특정중대범죄사건으로 공소사실이 변경된 사건의 피고인으로서 제4조제1항 각 호의 요건을 모두 갖춘 피고인에 대하여 피고인의 현재지 또는 최후 거주지를 관할하는 법원에 신상정보의 공개를 청구할 수 있다. 다만, 피고인이 미성년자인 경우는 제외한다.', 8067);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13904, '② 제1항에 따른 청구는 해당 특정중대범죄 피고사건의 항소심 변론종결 시까지 하여야 한다.', 8067);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13905, '③ 제1항에 따른 청구에 관하여는 해당 특정중대범죄 피고사건을 심리하는 재판부가 아닌 별도의 재판부에서 결정한다.', 8067);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13906, '④ 법원은 피고인의 신상정보 공개 여부를 결정하기 위하여 필요하다고 인정하는 때에는 검사, 피고인, 그 밖의 참고인으로부터 의견을 들을 수 있다.', 8067);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13907, '⑤ 제1항에 따른 청구를 받은 법원은 청구의 허부에 관한 결정을 하여야 한다.', 8067);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13908, '⑥ 제5항의 결정에 대하여는 즉시항고를 할 수 있다.', 8067);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13909, '⑦ 법원의 신상정보 공개 결정은 검사가 집행하고, 이에 대하여는 제4조제4항ㆍ제5항ㆍ제8항ㆍ제9항을 준용한다.', 8067);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13910, '① 피의자로서 이 법에 따라 신상정보가 공개된 자 중 검사로부터 불기소처분을 받거나 사법경찰관으로부터 불송치결정을 받은 자는 「형사보상 및 명예회복에 관한 법률」에 따른 형사보상과 별도로 국가에 대하여 신상정보의 공개에 따른 보상을 청구할 수 있다. 다만, 신상정보가 공개된 이후 불기소처분 또는 불송치결정의 사유가 있는 경우와 해당 불기소처분 또는 불송치결정이 종국적인 것이 아니거나 「형사소송법」 제247조에 따른 것일 경우에는 그러하지 아니하다.', 8068);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13911, '② 다음 각 호의 어느 하나에 해당하는 경우에는 제1항에 따른 보상의 전부 또는 일부를 지급하지 아니할 수 있다.', 8068);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13912, '③ 제1항에 따른 보상을 할 때에는 1천만원 이내에서 모든 사정을 고려하여 타당하다고 인정하는 금액을 보상한다. 이 경우 신상공개로 인하여 발생한 재산상의 손실액이 증명되었을 때에는 그 손실액도 보상한다.', 8068);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13913, '④ 제1항에 따른 보상에 관하여는 이 법에 특별한 규정이 있는 경우를 제외하고는 그 성질에 반하지 아니하는 범위에서 「형사보상 및 명예회복에 관한 법률」을 준용한다.', 8068);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13914, '① 이 법에 따라 신상정보가 공개된 피고인이 해당 특정중대범죄에 대하여 무죄재판을 받아 확정되었을 때에는 「형사보상 및 명예회복에 관한 법률」에 따른 형사보상과 별도로 국가에 대하여 신상정보의 공개에 따른 보상을 청구할 수 있다.', 8069);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13915, '② 다음 각 호의 어느 하나에 해당하는 경우에는 법원은 재량으로 보상청구의 전부 또는 일부를 기각할 수 있다.', 8069);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13916, '③ 제1항에 따른 보상을 할 때에는 1천만원 이내에서 모든 사정을 고려하여 법원이 타당하다고 인정하는 금액을 보상한다. 이 경우 신상공개로 인하여 발생한 재산상의 손실액이 증명되었을 때에는 그 손실액도 보상한다.', 8069);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13917, '④ 제1항에 따른 보상에 관하여는 특별한 규정이 있는 경우를 제외하고는 그 성질에 반하지 아니하는 범위에서 「형사보상 및 명예회복에 관한 법률」을 준용한다.', 8069);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13918, '① 검찰총장 및 경찰청장은 제4조에 따른 신상정보 공개 여부에 관한 사항을 심의하기 위하여 신상정보공개심의위원회를 둘 수 있다.', 8070);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13919, '② 신상정보공개심의위원회는 위원장을 포함하여 10인 이내의 위원으로 구성한다.', 8070);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13920, '③ 신상정보공개심의위원회는 신상정보 공개 여부에 관한 사항을 심의할 때 피의자에게 의견을 진술할 기회를 주어야 한다.', 8070);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13921, '④ 신상정보공개심의위원회 위원 또는 위원이었던 사람은 심의 과정에서 알게 된 비밀을 외부에 공개하거나 누설하여서는 아니 된다.', 8070);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13922, '⑤ 신상정보공개심의위원회의 구성 및 운영 등에 관한 구체적인 사항은 검찰총장 및 경찰청장이 정한다.', 8070);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13923, '① 검사와 사법경찰관은 피의자에게 법 제4조제6항 본문에 따라 신상정보 공개를 결정하기 전에 의견을 진술할 기회가 있다는 사실을 고지하고 별지 제1호서식의 의견진술 기회 등 고지 확인서를 제출받아야 한다.', 8074);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13924, '② 검사와 사법경찰관은 법 제8조에 따른 신상정보공개심의위원회를 개최하는 경우에는 피의자에게 해당 위원회의 개최일과 위원회에 의견을 진술할 기회가 있다는 사실을 고지하고 별지 제2호서식의 신상정보공개심의위원회 개최 통지 확인서를 제출받아야 한다.', 8074);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13925, '③ 검사와 사법경찰관은 제1항 또는 제2항의 고지를 받은 피의자가 의견 진술을 희망하는 의사를 표시한 경우에는 피의자에게 별지 제3호서식의 의견서 양식을 교부해야 한다. 다만, 피의자가 의견서 수령을 거부하는 의사를 밝힌 경우에는 교부하지 않을 수 있다.', 8074);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13926, '① 검사와 사법경찰관은 법 제4조제1항에 따라 피의자의 신상정보를 공개하기로 결정한 경우에는 지체 없이 별지 제4호서식의 피의자 신상정보 공개 결정 통지서로 피의자에게 통지해야 한다. 이 경우 피의자에게 변호인이 있는 경우에는 변호인에게도 피의자의 신상정보 공개 사실을 알려야 한다.', 8075);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13927, '② 검사와 사법경찰관은 제1항에 따른 통지를 받은 피의자가 신상정보 공개 결정에 대해 이의가 없다는 의사를 표시해 법 제4조제7항 단서에 따라 유예기간을 두지 않는 경우에는 별지 제5호서식의 신상정보 공개 결정 확인서를 제출받아야 한다.', 8075);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13928, '③ 사법경찰관은 신상정보를 공개하기로 결정된 특정중대범죄사건을 검사에게 송치하는 경우에는 별지 제4호서식의 피의자 신상정보 공개 결정 통지서를 수사기록에 편철하는 방식으로 신상정보 공개 결정 사실을 통보해야 한다.', 8075);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13929, '④ 제3항에 따라 사법경찰관이 검사에게 사건을 송치한 경우에도 해당 사건 피의자의 신상정보 공개는 사법경찰관이 집행한다.', 8075);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13930, '① 검사와 사법경찰관은 법 제4조에 따라 피의자의 신상정보를 검찰총장 또는 경찰청장이 지정하는 인터넷 홈페이지에 신상정보 공개일부터 30일간 게시하는 방법으로 공개한다. 이 경우 유죄의 판결이 확정될 때까지는 피의자가 무죄로 추정된다는 내용을 명시해야 한다.', 8076);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13931, '② 검사와 사법경찰관은 법 제4조제8항에 따른 신상정보 공개기간이 지나거나 신상정보가 공개된 피의자가 불기소처분 또는 불송치결정을 받은 경우 등 피의자의 신상정보 공개를 종료해야 할 사유가 생겼을 때에는 지체 없이 공개한 신상정보를 삭제해야 한다.', 8076);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13932, '① 검사는 신상정보를 공개하기로 결정된 특정중대범죄사건 중 제4조제3항에 따라 사법경찰관으로부터 송치받은 특정중대범죄사건에 대해 전부 또는 일부 불기소처분을 한 경우에는 그 사실을 별지 제6호서식의 신상정보 공개 결정 사건 불기소처분 통보서로 사법경찰관에게 통보한다.', 8077);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13933, '② 사법경찰관은 신상정보를 공개하기로 결정된 특정중대범죄사건 전부 또는 일부에 대해 불기소처분이 된 경우에는 신상정보를 공개해서는 안 되며, 이미 신상정보를 공개한 경우에는 그 신상정보를 지체 없이 삭제해야 한다. 다만, 일부 불기소처분의 경우 불기소처분이 된 부분을 제외하더라도 신상정보 공개 결정을 유지할 필요가 인정되는 경우에는 삭제하지 않을 수 있다.', 8077);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13934, '① 검사는 법 제5조제1항에 따라 법원에 피고인의 신상정보 공개를 청구하는 경우에는 법 제4조제1항 각 호의 요건을 갖추었음을 인정할 수 있는 자료를 제출해야 한다.', 8078);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13935, '② 검사는 법 제5조제5항에 따라 피고인에 대한 신상정보 공개 결정이 있는 경우 지체 없이 별지 제7호서식의 피고인 신상정보 공개 결정 통지서로 피고인에게 통지해야 한다.', 8078);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13936, '③ 피고인에 대한 신상정보 공개 방법 및 공개의 종료 등에 관하여는 제5조를 준용한다. 이 경우 "피의자"는 "피고인"으로, "불기소처분 또는 불송치결정을 받은 경우"는 "무죄재판을 받아 확정된 경우"로 본다.', 8078);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13937, '① 법 제8조에 따른 신상정보공개심의위원회(이하 "위원회"라 한다)는 각급 검찰청(지청을 포함한다) 및 경찰관서에 둘 수 있다.', 8079);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13938, '② 위원회는 위원장 1명을 포함하여 7명 이상 10명 이하의 위원으로 구성한다. 이 경우 공무원이 아닌 위원이 과반수가 되도록 하여야 한다.', 8079);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13939, '③ 위원회의 위원(이하 "위원"이라 한다)은 법조계나 학계 등에서 사회적 신망이 높고 경험이 풍부한 사람 중 검찰총장 또는 경찰청장이 성별을 고려하여 임명하거나 위촉한다.', 8079);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13940, '④ 위원회의 위원장(이하 "위원장"이라 한다)은 공무원이 아닌 위원 중에서 검찰총장 또는 경찰청장이 위촉한다.', 8079);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13941, '⑤ 검찰총장 또는 경찰청장은 위원 및 위원장의 임명 또는 위촉 권한을 각각 각급 검찰청의 장(지청장을 포함한다) 또는 각급 경찰관서의 장에게 위임할 수 있다.', 8079);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13942, '⑥ 위원은 다음 각 호의 어느 하나에 해당하는 경우에는 위원회의 심의ㆍ의결에서 제척(除斥)된다.', 8079);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13943, '⑦ 위원이 제6항 각 호의 어느 하나에 해당하는 경우에는 위원회에 그 사실을 알리고 스스로 해당 안건의 심의ㆍ의결에서 회피(回避)하여야 한다.', 8079);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13944, '⑧ 위원회의 심의는 공개하지 않으며, 재적위원 과반수의 찬성으로 의결한다.', 8079);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13945, '⑨ 위원의 명부와 심의내용에 관한 위원의 의견서 등 위원회의 문서는 공개하지 않는다.', 8079);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13946, '⑩ 제1항부터 제9항까지에서 규정한 사항 외에 위원회의 구성 및 운영 에 필요한 사항은 검찰총장 및 경찰청장이 정한다.', 8079);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13947, null, 8080);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13948, '① 「형사소송법」에 따른 일반 절차 또는 재심(再審)이나 비상상고(非常上告) 절차에서 무죄재판을 받아 확정된 사건의 피고인이 미결구금(未決拘禁)을 당하였을 때에는 이 법에 따라 국가에 대하여 그 구금에 대한 보상을 청구할 수 있다.', 8082);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13949, '② 상소권회복에 의한 상소, 재심 또는 비상상고의 절차에서 무죄재판을 받아 확정된 사건의 피고인이 원판결(原判決)에 의하여 구금되거나 형 집행을 받았을 때에는 구금 또는 형의 집행에 대한 보상을 청구할 수 있다.', 8082);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13950, '③ 「형사소송법」 제470조제3항에 따른 구치(拘置)와 같은 법 제473조부터 제475조까지의 규정에 따른 구속은 제2항을 적용할 때에는 구금 또는 형의 집행으로 본다.', 8082);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13951, '① 제2조에 따라 보상을 청구할 수 있는 자가 그 청구를 하지 아니하고 사망하였을 때에는 그 상속인이 이를 청구할 수 있다.', 8083);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13952, '② 사망한 자에 대하여 재심 또는 비상상고의 절차에서 무죄재판이 있었을 때에는 보상의 청구에 관하여는 사망한 때에 무죄재판이 있었던 것으로 본다.', 8083);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13953, null, 8084);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13954, '① 구금에 대한 보상을 할 때에는 그 구금일수(拘禁日數)에 따라 1일당 보상청구의 원인이 발생한 연도의 「최저임금법」에 따른 일급(日給) 최저임금액 이상 대통령령으로 정하는 금액 이하의 비율에 의한 보상금을 지급한다.', 8085);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13955, '② 법원은 제1항의 보상금액을 산정할 때 다음 각 호의 사항을 고려하여야 한다. <개정 2018.3.20>', 8085);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13956, '③ 사형 집행에 대한 보상을 할 때에는 집행 전 구금에 대한 보상금 외에 3천만원 이내에서 모든 사정을 고려하여 법원이 타당하다고 인정하는 금액을 더하여 보상한다. 이 경우 본인의 사망으로 인하여 발생한 재산상의 손실액이 증명되었을 때에는 그 손실액도 보상한다.', 8085);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13957, '④ 벌금 또는 과료(科料)의 집행에 대한 보상을 할 때에는 이미 징수한 벌금 또는 과료의 금액에 징수일의 다음 날부터 보상 결정일까지의 일수에 대하여 「민법」 제379조의 법정이율을 적용하여 계산한 금액을 더한 금액을 보상한다.', 8085);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13958, '⑤ 노역장유치(勞役場留置)의 집행을 한 경우 그에 대한 보상에 관하여는 제1항을 준용한다.', 8085);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13959, '⑥ 몰수(沒收) 집행에 대한 보상을 할 때에는 그 몰수물을 반환하고, 그것이 이미 처분되었을 때에는 보상결정 시의 시가(時價)를 보상한다.', 8085);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13960, '⑦ 추징금(追徵金)에 대한 보상을 할 때에는 그 액수에 징수일의 다음 날부터 보상 결정일까지의 일수에 대하여 「민법」 제379조의 법정이율을 적용하여 계산한 금액을 더한 금액을 보상한다.', 8085);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13961, '① 이 법은 보상을 받을 자가 다른 법률에 따라 손해배상을 청구하는 것을 금지하지 아니한다.', 8086);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13962, '② 이 법에 따른 보상을 받을 자가 같은 원인에 대하여 다른 법률에 따라 손해배상을 받은 경우에 그 손해배상의 액수가 이 법에 따라 받을 보상금의 액수와 같거나 그보다 많을 때에는 보상하지 아니한다. 그 손해배상의 액수가 이 법에 따라 받을 보상금의 액수보다 적을 때에는 그 손해배상 금액을 빼고 보상금의 액수를 정하여야 한다.', 8086);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13963, '③ 다른 법률에 따라 손해배상을 받을 자가 같은 원인에 대하여 이 법에 따른 보상을 받았을 때에는 그 보상금의 액수를 빼고 손해배상의 액수를 정하여야 한다.', 8086);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13964, '① 보상청구를 할 때에는 보상청구서에 재판서의 등본과 그 재판의 확정증명서를 첨부하여 법원에 제출하여야 한다.', 8089);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13965, '② 보상청구서에는 다음 각 호의 사항을 적어야 한다.', 8089);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13966, '① 보상청구를 할 수 있는 같은 순위의 상속인이 여러 명인 경우에 그 중 1명이 보상청구를 하였을 때에는 보상을 청구할 수 있는 모두를 위하여 그 전부에 대하여 보상청구를 한 것으로 본다.', 8091);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13967, '② 제1항의 경우에 청구를 한 상속인 외의 상속인은 공동청구인으로서 절차에 참가할 수 있다.', 8091);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13968, '③ 법원은 제1항의 경우에 보상을 청구할 수 있는 같은 순위의 다른 상속인이 있다는 사실을 알았을 때에는 지체 없이 그 상속인에게 보상청구가 있었음을 통지하여야 한다.', 8091);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13969, '① 같은 순위의 상속인이 여러 명인 경우에 보상을 청구한 자는 나머지 모두의 동의 없이 청구를 취소할 수 없다.', 8092);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13970, '② 보상청구를 취소한 경우에 보상청구권자는 다시 보상을 청구할 수 없다.', 8092);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13971, '① 보상청구는 법원 합의부에서 재판한다.', 8094);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13972, '② 보상청구에 대하여는 법원은 검사와 청구인의 의견을 들은 후 결정을 하여야 한다.', 8094);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13973, '③ 보상청구를 받은 법원은 6개월 이내에 보상결정을 하여야 한다. <신설 2018.3.20>', 8094);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13974, '④ 제2항에 따른 결정의 정본(正本)은 검사와 청구인에게 송달하여야 한다. <개정 2018.3.20>', 8094);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13975, null, 8096);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13976, '① 보상의 청구가 이유 있을 때에는 보상결정을 하여야 한다.', 8097);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13977, '② 보상의 청구가 이유 없을 때에는 청구기각의 결정을 하여야 한다.', 8097);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13978, '① 보상을 청구한 자가 청구절차 중 사망하거나 상속인 자격을 상실한 경우에 다른 청구인이 없을 때에는 청구의 절차는 중단된다.', 8099);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13979, '② 제1항의 경우에 보상을 청구한 자의 상속인 또는 보상을 청구한 상속인과 같은 순위의 상속인은 2개월 이내에 청구의 절차를 승계할 수 있다.', 8099);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13980, '③ 법원은 제2항에 따라 절차를 승계할 수 있는 자로서 법원에 알려진 자에게는 지체 없이 제2항의 기간 내에 청구의 절차를 승계할 것을 통지하여야 한다.', 8099);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13981, '④ 제2항의 기간 내에 절차를 승계하는 신청이 없을 때에는 법원은 청구를 각하하는 결정을 하여야 한다.', 8099);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13982, '① 제17조제1항에 따른 보상결정에 대하여는 1주일 이내에 즉시항고(卽時抗告)를 할 수 있다.', 8100);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13983, '② 제17조제2항에 따른 청구기각 결정에 대하여는 즉시항고를 할 수 있다.', 8100);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13984, '① 보상금 지급을 청구하려는 자는 보상을 결정한 법원에 대응하는 검찰청에 보상금 지급청구서를 제출하여야 한다.', 8101);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13985, '② 제1항의 청구서에는 법원의 보상결정서를 첨부하여야 한다.', 8101);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13986, '③ 보상결정이 송달된 후 2년 이내에 보상금 지급청구를 하지 아니할 때에는 권리를 상실한다.', 8101);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13987, '④ 보상금을 받을 수 있는 자가 여러 명인 경우에는 그 중 1명이 한 보상금 지급청구는 보상결정을 받은 모두를 위하여 그 전부에 대하여 보상금 지급청구를 한 것으로 본다.', 8101);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13988, '① 보상금 지급청구서를 제출받은 검찰청은 3개월 이내에 보상금을 지급하여야 한다.', 8102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13989, '② 제1항에 따른 기한까지 보상금을 지급하지 아니한 경우에는 그 다음 날부터 지급하는 날까지의 지연 일수에 대하여 「민법」 제379조의 법정이율에 따른 지연이자를 지급하여야 한다.', 8102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13990, '① 법원은 보상결정이 확정되었을 때에는 2주일 내에 보상결정의 요지를 관보에 게재하여 공시하여야 한다. 이 경우 보상결정을 받은 자의 신청이 있을 때에는 그 결정의 요지를 신청인이 선택하는 두 종류 이상의 일간신문에 각각 한 번씩 공시하여야 하며 그 공시는 신청일부터 30일 이내에 하여야 한다.', 8106);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13991, '② 제6조제2항 전단에 규정된 이유로 보상청구를 기각하는 결정이 확정되었을 때에는 제1항을 준용한다.', 8106);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13992, '① 다음 각 호의 어느 하나에 해당하는 경우에도 국가에 대하여 구금에 대한 보상을 청구할 수 있다. 다만, 제3호의 경우 재심 절차에서 선고된 형을 초과하여 집행된 구금일수를 제5조제1항에 따른 구금일수로 본다. <개정 2023.12.29>', 8107);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13993, '② 제1항에 따른 보상에 대하여는 무죄재판을 받아 확정된 사건의 피고인에 대한 보상에 관한 규정을 준용한다. 보상결정의 공시에 대하여도 또한 같다.', 8107);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13994, '③ 제1항제3호에 따른 보상청구의 경우에 법원은 재량으로 보상청구의 전부 또는 일부를 기각할 수 있다. <신설 2023.12.29>', 8107);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13995, '① 피의자로서 구금되었던 자 중 검사로부터 불기소처분을 받거나 사법경찰관으로부터 불송치결정을 받은 자는 국가에 대하여 그 구금에 대한 보상(이하 "피의자보상"이라 한다)을 청구할 수 있다. 다만, 구금된 이후 불기소처분 또는 불송치결정의 사유가 있는 경우와 해당 불기소처분 또는 불송치결정이 종국적(終局的)인 것이 아니거나 「형사소송법」 제247조에 따른 것일 경우에는 그러하지 아니하다. <개정 2021.3.16>', 8108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13996, '② 다음 각 호의 어느 하나에 해당하는 경우에는 피의자보상의 전부 또는 일부를 지급하지 아니할 수 있다.', 8108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13997, '③ 피의자보상에 관한 사항을 심의ㆍ결정하기 위하여 지방검찰청에 피의자보상심의회(이하 "심의회"라 한다)를 둔다.', 8108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13998, '④ 심의회는 법무부장관의 지휘ㆍ감독을 받는다.', 8108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (13999, '⑤ 심의회의 관할ㆍ구성ㆍ운영, 그 밖에 필요한 사항은 대통령령으로 정한다.', 8108);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14000, '① 피의자보상을 청구하려는 자는 불기소처분을 한 검사가 소속된 지방검찰청(지방검찰청 지청의 검사가 불기소처분을 한 경우에는 그 지청이 소속하는 지방검찰청을 말한다) 또는 불송치결정을 한 사법경찰관이 소속된 경찰관서에 대응하는 지방검찰청의 심의회에 보상을 청구하여야 한다. <개정 2021.3.16>', 8109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14001, '② 제1항에 따라 피의자보상을 청구하는 자는 보상청구서에 불기소처분 또는 불송치결정을 받은 사실을 증명하는 서류를 첨부하여 제출하여야 한다. <개정 2021.3.16>', 8109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14002, '③ 피의자보상의 청구는 불기소처분 또는 불송치결정의 고지(告知) 또는 통지를 받은 날부터 3년 이내에 하여야 한다. <개정 2021.3.16>', 8109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14003, '④ 피의자보상의 청구에 대한 심의회의 결정에 대하여는 「행정심판법」에 따른 행정심판을 청구하거나 「행정소송법」에 따른 행정소송을 제기할 수 있다.', 8109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14004, '⑤ 심의회의 보상결정이 송달(제4항의 심판을 청구하거나 소송을 제기한 경우에는 그 재결 또는 판결에 따른 심의회의 보상결정이 송달된 때를 말한다)된 후 2년 이내에 보상금 지급청구를 하지 아니할 때에는 그 권리를 상실한다.', 8109);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14005, '① 피의자보상에 대하여 이 장에 특별한 규정이 있는 경우를 제외하고는 그 성질에 반하지 아니하는 범위에서 무죄재판을 받아 확정된 사건의 피고인에 대한 보상에 관한 이 장의 규정을 준용한다.', 8110);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14006, '② 다음 각 호의 어느 하나에 해당하는 자에 대한 형사보상에 대하여는 이 장의 규정을 준용한다. 이 경우 "법원"은 "군사법원"으로, "검찰청"은 "군검찰부"로, "심의회"는 "「국가배상법」 제10조제2항에 따른 특별심의회 소속 지구심의회(地區審議會)"로, "법무부장관"은 "국방부장관"으로 본다. <개정 2016.1.6>', 8110);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14007, '① 제30조에 따른 청구를 할 때에는 무죄재판서 게재 청구서에 재판서의 등본과 그 재판의 확정증명서를 첨부하여 제출하여야 한다.', 8112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14008, '② 상속인에 의한 청구 및 그 소명에 대하여는 제3조 및 제10조를 준용한다. 이 경우 "보상"은 "게재"로 보며, 같은 순위의 상속인이 여러 명일 때에는 상속인 모두가 무죄재판서 게재 청구에 동의하였음을 소명할 자료를 제출하여야 한다.', 8112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14009, '③ 대리인에 의한 청구에 대하여는 제13조를 준용한다. 이 경우 "보상"은 "게재"로 본다.', 8112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14010, '④ 청구의 취소에 대하여는 제12조를 준용한다. 이 경우 "보상"은 "게재"로 본다.', 8112);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14011, '① 제30조에 따른 청구가 있을 때에는 그 청구를 받은 날부터 1개월 이내에 무죄재판서를 법무부 인터넷 홈페이지에 게재하여야 한다. 다만, 청구를 받은 때에 무죄재판사건의 확정재판기록이 해당 지방검찰청에 송부되지 아니한 경우에는 무죄재판사건의 확정재판기록이 해당 지방검찰청에 송부된 날부터 1개월 이내에 게재하여야 한다.', 8113);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14012, '② 다음 각 호의 어느 하나에 해당할 때에는 무죄재판서의 일부를 삭제하여 게재할 수 있다.', 8113);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14013, '③ 제2항제1호의 경우에는 청구인의 의사를 서면으로 확인하여야 한다. 다만, 소재불명 등으로 청구인의 의사를 확인할 수 없을 때에는 「민법」 제779조에 따른 가족 중 1명의 의사를 서면으로 확인하는 것으로 대신할 수 있다.', 8113);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14014, '④ 제1항에 따른 무죄재판서의 게재기간은 1년으로 한다.', 8113);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14015, '① 제32조제1항에 따라 무죄재판서를 법무부 인터넷 홈페이지에 게재한 경우에는 지체 없이 그 사실을 청구인에게 서면으로 통지하여야 한다.', 8114);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14016, '② 제30조의 청구에 따른 집행절차 등에 관한 세부사항은 대통령령으로 정한다.', 8114);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14017, '① 제26조제1항 각 호의 경우에 해당하는 자는 확정된 사건의 재판서를 게재하도록 청구할 수 있다.', 8115);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14018, '② 제1항에 따른 청구에 대하여는 무죄재판사건 피고인의 무죄재판서 게재 청구에 관한 규정을 준용한다.', 8115);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14019, null, 8116);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14020, null, 8119);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14021, '① 위원장은 심의회를 소집하고, 그 회의의 의장이 된다.', 8121);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14022, '② 심의회의 회의는 위원장을 포함한 재적위원 과반수의 출석과 출석위원 3분의 2 이상의 찬성으로 의결한다.', 8121);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14023, '③ 보상금을 결정할 때 액수에 관한 의견이 세 가지 이상으로 나누어져 각각 3분의 2에 이르지 못하는 경우에는 3분의 2에 이르기까지 최저금액의 의견 수에 차례로 많은 금액의 의견 수를 더하여 그 중 가장 많은 금액의 의견에 따른다.', 8121);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14024, '① 법무부장관은 각 심의회를 지휘ㆍ감독하기 위하여 필요한 명령이나 조치를 할 수 있다.', 8123);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14025, '② 법무부장관은 제1항에 따른 직무를 수행하기 위하여 필요하다고 인정할 때에는 소속 직원 또는 각급 검찰청의 검사로 하여금 각 심의회의 업무처리를 감사(監査)하게 할 수 있다.', 8123);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14026, '① 법 제28조제2항에 따른 피의자 보상청구서(이하 "청구서"라 한다)에는 다음 각 호의 사항을 적고 청구인이 기명날인하거나 전자서명을 하여야 한다.', 8124);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14027, '② 청구서에는 청구이유를 소명할 수 있는 증거자료를 첨부하여야 한다. 이 경우 심의회는 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 청구인의 주민등록표 등본을 확인하여야 하며, 청구인이 확인에 동의하지 아니하는 경우에는 이를 첨부하게 하여야 한다.', 8124);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14028, '① 위원장이나 위원장의 명을 받은 사람은 보상결정에 필요한 조사를 할 수 있고, 관계 공무원이나 관계 기관에 사실을 조회하거나 필요한 자료의 제출을 요청할 수 있다.', 8125);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14029, '② 제1항의 요청을 받은 공무원이나 관계 기관의 장은 정당한 사유 없이 요청에 따르지 아니하거나 회신을 지체해서는 아니 된다.', 8125);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14030, '① 보상결정은 믿을 수 있는 증거자료에 의하여 이루어져야 한다.', 8126);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14031, '② 보상결정서에는 다음 각 호의 사항을 적고 회의에 출석한 위원이 기명날인하여야 한다.', 8126);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14032, '③ 심의회가 보상결정을 하였을 때에는 보상결정서 원본을 보관하고 청구인에게 보상결정통지서와 보상결정서 정본(正本) 1부를 보내야 한다.', 8126);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14033, null, 8127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14034, '① 법 제30조에 따른 무죄재판사건을 기소한 검찰청(지방검찰청 지청을 포함한다)의 장은 무죄재판서 게재 업무를 담당할 전담직원을 지정할 수 있다.', 8129);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14035, '② 제1항의 전담직원은 무죄재판서 게재에 관한 장부를 작성하고, 매년 1회 이상 그 업무처리 상황을 법무부장관에게 보고하여야 한다.', 8129);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14036, null, 8131);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14037, '① 다음 각 호의 어느 하나에 해당하는 자는 5년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.', 8132);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14038, '② 제1항의 미수범은 처벌한다.', 8132);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14039, '③ 제1항의 죄를 범할 목적으로 예비하거나 음모한 자는 2년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 8132);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14040, '① 「특정 금융거래정보의 보고 및 이용 등에 관한 법률」 제2조제1호에 따른 금융회사등(이하 "금융회사등"이라 한다)에 종사하는 사람은 같은 법 제2조제2호에 따른 금융거래등과 관련하여 수수한 재산이 범죄수익등이라는 사실을 알게 되었을 때 또는 금융거래등의 상대방이 제3조의 죄에 해당하는 행위를 하고 있다는 사실을 알게 되었을 때에는 다른 법률의 규정에도 불구하고 지체 없이 관할 수사기관에 신고하여야 한다. <개정 2011.5.19, 2020.3.24>', 8134);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14041, '② 금융회사등에 종사하는 사람은 제1항에 따라 신고를 하려는 경우 또는 신고를 한 경우에 그 사실을 그 신고와 관련된 금융거래등의 상대방 및 그의 관계자에게 누설하여서는 아니 된다. <개정 2011.5.19, 2020.3.24>', 8134);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14042, '③ 제1항이나 제2항을 위반한 사람은 2년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 8134);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14043, '① 다음 각 호의 재산은 몰수할 수 있다.', 8138);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14044, '② 제1항에 따라 몰수할 수 있는 재산(이하 "몰수대상재산"이라 한다)이 몰수대상재산 외의 재산과 합쳐진 경우 그 몰수대상재산을 몰수하여야 할 때에는 합쳐짐으로써 생긴 재산[이하 "혼화재산"(混和財産)이라 한다] 중 몰수대상재산(합쳐지는 데에 관련된 부분만 해당한다)의 금액 또는 수량에 상당하는 부분을 몰수할 수 있다.', 8138);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14045, '③ 제1항에도 불구하고 같은 항 각 호의 재산이 범죄피해재산(재산에 관한 죄, 「특정범죄 가중처벌 등에 관한 법률」 제5조의2제1항제1호ㆍ제2항제1호의 죄 또는 「채무자 회생 및 파산에 관한 법률」 제650조ㆍ제652조 및 제654조의 죄에 해당하는 범죄행위에 의하여 그 피해자로부터 취득한 재산 또는 그 재산의 보유ㆍ처분에 의하여 얻은 재산을 말한다. 이하 같다)인 경우에는 몰수할 수 없다. 제1항 각 호의 재산 중 일부가 범죄피해재산인 경우에는 그 부분에 대하여도 또한 같다.', 8138);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14046, '① 제8조제1항에 따른 몰수는 몰수대상재산 또는 혼화재산이 범인 외의 자에게 귀속(歸屬)되지 아니하는 경우에만 할 수 있다. 다만, 범인 외의 자가 범죄 후 그 정황을 알면서 그 몰수대상재산 또는 혼화재산을 취득한 경우(그 몰수대상재산 또는 혼화재산의 취득이 제4조 단서에 해당하는 경우는 제외한다)에는 그 몰수대상재산 또는 혼화재산이 범인 외의 자에게 귀속된 경우에도 몰수할 수 있다.', 8139);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14047, '② 지상권ㆍ저당권 또는 그 밖의 권리가 설정된 재산을 제8조제1항에 따라 몰수하는 경우 범인 외의 자가 범죄 전에 그 권리를 취득하였을 때 또는 범죄 후 그 정황을 알지 못하고 그 권리를 취득하였을 때에는 그 권리를 존속시킨다.', 8139);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14048, '① 제8조제1항에 따라 몰수할 재산을 몰수할 수 없거나 그 재산의 성질, 사용 상황, 그 재산에 관한 범인 외의 자의 권리 유무, 그 밖의 사정으로 인하여 그 재산을 몰수하는 것이 적절하지 아니하다고 인정될 때에는 그 가액(價額)을 범인으로부터 추징할 수 있다.', 8140);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14049, '② 제1항에도 불구하고 제8조제1항의 재산이 범죄피해재산인 경우에는 그 가액을 추징할 수 없다.', 8140);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14050, '① 검사는 이 법에  따른 몰수ㆍ추징의 집행을 위하여 필요하다고 인정되면 그 목적에 필요한 최소한의 범위에서 다음 각 호의 처분을 할 수 있다. 다만, 범인 외의 자에 대한 제4호 및 제5호의 처분은 제3항에 따른 영장이 있어야 한다. <개정 2020.3.24>', 8142);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14051, '② 제1항의 자료제공 요청에 대하여 해당 기관은 군사, 외교, 대북관계 등 국가안위에 중대한 영향을 미치는 경우를 제외하고는 다른 법률을 근거로 이를 거부할 수 없다.', 8142);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14052, '③ 검사는 제1항의 몰수ㆍ추징의 집행을 위하여 필요한 경우 지방법원 판사에게 청구하여 발부받은 영장에 의하여 압수ㆍ수색 또는 검증을 할 수 있다.', 8142);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14053, null, 8143);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14054, null, 8144);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14055, '① 법무부장관은 몰수대상재산이 몰수ㆍ추징되어 국고에 귀속된 경우에는 수사기관에 신고한 자 또는 몰수ㆍ추징에 공로가 있는 자에게 포상금을 지급할 수 있다. 다만, 공무원이 그 직무와 관련하여 신고하거나 금융회사등에 종사하는 사람이 제5조제1항에 따라 신고한 경우에는 포상금을 감액하거나 지급하지 아니할 수 있다.', 8146);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14056, '② 제1항에 따른 포상금 지급 대상이 되는 신고 또는 공로의 범위, 포상금 지급의 기준ㆍ방법 및 절차 등에 관하여 필요한 사항은 대통령령으로 정한다.', 8146);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14057, '① 「범죄수익은닉의 규제 및 처벌 등에 관한 법률」(이하 "법"이라 한다) 제13조제1항에 따른 포상금(이하 "포상금"이라 한다) 지급 대상이 되는 신고 또는 공로의 범위는 다음 각 호와 같다.', 8148);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14058, '② 제1항제3호에서 "은닉재산"이란 몰수ㆍ추징의 판결이 확정된 자가 은닉한 현금, 예금, 주식, 그 밖에 재산적 가치가 있는 유형ㆍ무형의 재산을 말한다. 다만, 다음 각 호의 어느 하나에 해당하는 재산은 제외한다. <개정 2021.2.17>', 8148);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14059, '', 8149);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14060, '② 법무부장관은 제1항에 따라 포상금을 결정하는 경우 다음 각 호의 사항을 고려하여야 한다.', 8149);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14061, '③ 포상금의 세부적인 지급 방법과 절차 등에 관하여 필요한 사항은 법무부장관이 정한다.', 8149);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14062, '① 포상금을 받으려는 자는 법무부장관이 정하는 바에 따라 포상금 지급 신청서를 관할 지방검찰청 검사장(지방검찰청 지청장을 포함한다. 이하 같다)에게 제출하여야 한다.', 8150);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14063, '② 제1항에 따른 신청은 「민원 처리에 관한 법률 시행령」 제2조제1항제3호에도 불구하고 익명 또는 가명으로 할 수 있다. 이 경우 그 사유에 관하여 신청을 접수한 관할 지방검찰청 검사장의 확인이 있어야 한다. <개정 2016.2.12>', 8150);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14064, '③ 제1항에 따른 신청서를 접수한 관할 지방검찰청 검사장은 그 신청서에 법무부장관이 정하는 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 8150);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14065, null, 8151);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14066, null, 8154);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14067, null, 8155);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14068, '① 대한민국 선박의 선장은 운항 중에 제5조부터 제13조까지의 죄를 범한 것으로 의심할 만한 상당한 이유가 있다고 인정하는 사람(이하 "범죄인"이라 한다)을 「항해의 안전에 대한 불법행위의 억제를 위한 협약」(이하 "항해안전협약"이라 한다)의 당사국인 외국의 정부기관에 인도(引渡)할 수 있다. 이 경우 선장은 긴급히 처리하여야 할 부득이한 사유가 있는 경우를 제외하고는 인도하기 전에 인도 대상자, 인도 사유, 인도 예정 일시 및 인도 대상국 등에 관한 사항을 미리 법무부장관에게 보고하고 승인을 받아야 한다.', 8156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14069, '② 대한민국 선박의 선장은 제1항에 따라 범죄인을 인도하려는 경우에는 특별한 사정이 있는 경우를 제외하고는 외국의 영해에 진입하기 전에 인도 대상자, 인도 의사(意思) 및 인도 사유를 그 정부기관에 통보하여야 하고, 인도하는 경우에는 관련 증거를 함께 제공하여야 한다.', 8156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14070, '③ 제1항에 따라 범죄인을 인도한 선장은 즉시 법무부장관에게 인도 대상자, 인도 일시, 인도 장소 및 인수기관 등에 관한 사항을 보고하여야 한다.', 8156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14071, '④ 항해안전협약의 당사국인 외국선박의 선장이 범죄인을 대한민국에 인도하려는 경우에는 검사 또는 「형사소송법」 제197조제1항에 따른 사법경찰관(「사법경찰관리의 직무를 수행할 자와 그 직무범위에 관한 법률」 제5조제18호에 따른 어업감독 공무원 중 7급 이상 공무원을 포함한다. 이하 같다)은 특별한 사정이 있는 경우를 제외하고는 그 범죄인을 인수하여야 한다. 이 경우 사법경찰관이 인수할 때에는 긴급히 처리하여야 할 부득이한 사유가 있는 경우를 제외하고는 검사의 지휘를 받아야 한다. <개정 2021.3.16>', 8156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14072, '⑤ 사법경찰관은 제4항에 따라 범죄인을 인수한 경우에는 그 결과를 즉시 검사에게 보고하여야 한다.', 8156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14073, '⑥ 검사 또는 사법경찰관이 제4항에 따라 범죄인을 인수할 때에는 범행을 조사하는 데에 필요한 증거물의 제시ㆍ제출, 선박 안에 있는 사람의 출석 등을 선장에게 요구할 수 있다. 이 경우 그 조사를 위하여 해당 선박의 운항을 부당하게 지연시켜서는 아니 된다.', 8156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14074, '⑦ 법무부장관은 제4항에 따라 인수한 범죄인을 그가 승선하고 있던 외국선박이 등록된 국가에 인수하도록 요청할 수 있다. 이 경우 인수요청 절차에 관하여는 「국제형사사법 공조법」 제29조부터 제32조까지의 규정을 준용하되, "공조요청"은 "인수요청"으로, "공조요청서"는 "인수요청서"로 본다.', 8156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14075, '⑧ 제7항의 인수요청 대상 국가로부터 인수 수락의 통보를 받은 경우 검사는 범죄인이 구속되어 있는 교도소ㆍ구치소 또는 그 밖의 구금장소의 장에게 그 범죄인을 인도할 것을 지휘하여야 한다. 이 경우 그 절차에 관하여는 「범죄인 인도법」 제36조, 제37조제1항, 제39조제1항, 제40조제1항 및 제41조를 준용한다.', 8156);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14076, '① 운항 중인 선박 또는 해상구조물의 안전을 위험하게 할 목적으로 그 선박 또는 해상구조물에 있는 사람을 살해한 사람은 사형, 무기 또는 7년 이상의 징역에 처한다.', 8157);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14077, '② 운항 중인 선박 또는 해상구조물의 안전을 위험하게 할 목적으로 그 선박 또는 해상구조물에 있는 사람의 신체를 상해(傷害) 또는 폭행하거나 사람을 협박한 사람은 3년 이상의 유기징역에 처한다.', 8157);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14078, '③ 제1항의 죄를 범할 목적으로 예비하거나 음모한 사람은 10년 이하의 징역에 처한다. 다만, 그 목적한 죄의 실행에 착수(着手)하기 전에 자수한 사람은 그 형을 감경하거나 면제한다.', 8157);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14079, '① 폭행이나 협박 또는 그 밖의 방법으로 운항 중인 선박 또는 해상구조물을 강탈하거나 선박을 강제로 운항하게 한 사람은 무기 또는 5년 이상의 징역에 처한다.', 8158);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14080, '② 제1항의 죄를 범할 목적으로 예비하거나 음모한 사람은 5년 이하의 징역에 처한다. 다만, 그 목적한 죄의 실행에 착수하기 전에 자수한 사람은 그 형을 감경하거나 면제한다.', 8158);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14081, '① 제6조제1항의 죄 또는 그 미수죄를 범하여 사람을 살해하거나 사망에 이르게 한 사람은 사형, 무기 또는 10년 이상의 징역에 처하고, 사람의 신체를 상해하거나 상해에 이르게 한 사람은 무기 또는 7년 이상의 징역에 처한다.', 8164);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14082, '② 제5조제1항ㆍ제2항, 제7조의 죄 또는 그 미수죄(제5조제2항의 경우 폭행은 제외한다)를 범하여 사람을 살해하거나 사망에 이르게 한 사람은 사형, 무기 또는 7년 이상의 징역에 처하고, 사람의 신체를 상해하거나 상해에 이르게 한 사람은 무기 또는 5년 이상의 징역에 처한다.', 8164);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14083, '③ 제8조부터 제10조까지의 죄 또는 그 미수죄를 범하여 사람을 살해하거나 사망에 이르게 한 사람은 사형, 무기 또는 5년 이상의 징역에 처하고, 사람의 신체를 상해하거나 상해에 이르게 한 사람은 무기 또는 3년 이상의 징역에 처한다.', 8164);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14084, '④ 제1항부터 제3항까지에 규정된 죄의 미수범은 처벌한다.', 8164);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14085, null, 8167);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14086, '① 밀항 또는 이선ㆍ이기한 사람은 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다. <개정 2020.2.18>', 8168);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14087, '② 제1항의 경우 미수범도 처벌한다.', 8168);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14088, '③ 제1항의 죄를 범할 목적으로 예비(豫備)하거나 음모한 사람은 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 8168);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14089, '① 제3조제1항의 행위를 알선한 사람은 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다. <개정 2020.2.18>', 8169);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14090, '② 영리를 목적으로 제1항의 행위를 한 사람은 5년 이하의 징역 또는 5천만원 이하의 벌금에 처한다. <개정 2020.2.18>', 8169);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14091, '① 제3조 또는 제4조의 경우에 그 범죄에 제공되었거나 제공하려던 선박 등 도구로서 범인 이외의 자의 소유가 아닌 것은 몰수할 수 있다.', 8170);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14092, '② 제4조제2항의 경우에 받았거나 받기로 약속한 보수는 몰수한다. 이 경우 해당 보수를 몰수할 수 없을 때에는 그 가액을 추징한다.', 8170);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14093, '① 밀항 또는 이선ㆍ이기한 사람으로서 재외공관에 자수 또는 귀환하였거나 밀항 또는 이선ㆍ이기에 착수하였다가 관계 수사기관이나 해당 선장 또는 기장, 그 밖의 책임자에게 자수한 사람은 형을 경감하거나 면제할 수 있다.', 8172);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14094, '② 직계혈족ㆍ배우자ㆍ동거친족 또는 그 배우자를 위하여 제3조제1항의 행위를 교사하거나 방조한 때에는 벌하지 아니한다.', 8172);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14095, '① 사법경찰관리가 이 법을 위반한 사건을 수사하였을 때에는 지체 없이 그 사실을 관할 지방출입국ㆍ외국인관서의 장에게 통보하여야 한다. <개정 2014.3.18>', 8173);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14096, '② 제1항의 경우에 그 수사기관의 장은 지방출입국ㆍ외국인관서의 장으로부터 출입국관리사무 처리에 필요한 자료의 제출요구를 받으면 그에 따라야 한다. <개정 2014.3.18>', 8173);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14097, null, 8177);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14098, '① 국가는 디엔에이감식시료를 채취하고 디엔에이 신원확인정보를 관리하며 이를 이용함에 있어 인간의 존엄성 및 개인의 사생활이 침해되지 아니하도록 필요한 시책을 마련하여야 한다.', 8178);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14099, '② 데이터베이스에 수록되는 디엔에이신원확인정보에는 개인 식별을 위하여 필요한 사항 외의 정보 또는 인적사항이 포함되어서는 아니 된다.', 8178);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14100, '① 검찰총장은 제5조에 따라 채취한 디엔에이감식시료로부터 취득한 디엔에이신원확인정보에 관한 사무를 총괄한다.', 8179);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14101, '② 경찰청장은 제6조 및 제7조에 따라 채취한 디엔에이감식시료로부터 취득한 디엔에이신원확인정보에 관한 사무를 총괄한다.', 8179);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14102, '③ 검찰총장 및 경찰청장은 데이터베이스를 서로 연계하여 운영할 수 있다.', 8179);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14103, '① 검사(군검사를 포함한다. 이하 같다)는 다음 각 호의 어느 하나에 해당하는 죄 또는 이와 경합된 죄에 대하여 형의 선고, 「형법」 제59조의2에 따른 보호관찰명령, 「치료감호법」에 따른 치료감호선고, 「소년법」 제32조제1항제9호 또는 제10호에 해당하는 보호처분결정을 받아 확정된 사람(이하 "수형인등"이라 한다)으로부터 디엔에이감식시료를 채취할 수 있다. 다만, 제6조에 따라 디엔에이감식시료를 채취하여 디엔에이신원확인정보가 이미 수록되어 있는 경우는 제외한다. <개정 2010.4.15, 2012.12.18, 2013.4.5, 2014.10.15, 2016.1.6>', 8180);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14104, '② 검사는 필요한 경우 교도소ㆍ구치소 및 그 지소, 소년원, 치료감호시설 등(이하 "수용기관"이라 한다)의 장에게 디엔에이감식시료의 채취를 위탁할 수 있다.', 8180);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14105, '① 검사 또는 사법경찰관은 다음 각 호의 어느 하나에 해당하는 것(이하 "범죄현장등"이라 한다)에서 디엔에이감식시료를 채취할 수 있다.', 8182);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14106, '② 제1항에 따라 채취한 디엔에이감식시료에서 얻은 디엔에이신원확인정보는 그 신원이 밝혀지지 아니한 것에 한정하여 데이터베이스에 수록할 수 있다.', 8182);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14107, '① 검사는 관할 지방법원 판사(군판사를 포함한다. 이하 같다)에게 청구하여 발부받은 영장에 의하여 제5조 또는 제6조에 따른 디엔에이감식시료의 채취대상자로부터 디엔에이감식시료를 채취할 수 있다.', 8183);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14108, '② 사법경찰관은 검사에게 신청하여 검사의 청구로 관할 지방법원판사가 발부한 영장에 의하여 제6조에 따른 디엔에이감식시료의 채취대상자로부터 디엔에이감식시료를 채취할 수 있다.', 8183);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14109, '③ 제1항과 제2항의 채취대상자가 동의하는 경우에는 영장 없이 디엔에이감식시료를 채취할 수 있다. 이 경우 미리 채취대상자에게 채취를 거부할 수 있음을 고지하고 서면으로 동의를 받아야 한다.', 8183);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14110, '④ 제1항 및 제2항에 따라 디엔에이감식시료를 채취하기 위한 영장(이하 "디엔에이감식시료채취영장"이라 한다)을 청구할 때에는 채취대상자의 성명, 주소, 청구이유, 채취할 시료의 종류 및 방법, 채취할 장소 등을 기재한 청구서 및 채취에 관한 채취대상자의 의견이 담긴 서면을 제출하여야 하며, 청구이유에 대한 소명자료를 첨부하여야 한다. 이 경우 채취대상자의 의견이 담긴 서면을 제출하기 곤란한 사정이 있는 때에는 그에 대한 소명자료를 함께 제출하여야 한다.', 8183);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14111, '⑤ 관할 지방법원 판사는 디엔에이감식시료채취영장 발부여부를 심사하는 때에 채취대상자에게 서면에 의한 의견진술의 기회를 주어야 한다. 다만, 제4항에 따라 채취대상자의 의견이 담긴 서면이 제출된 때에는 의견진술의 기회를 부여한 것으로 본다.', 8183);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14112, '⑥ 디엔에이감식시료채취영장에는 대상자의 성명, 주소, 채취할 시료의 종류 및 방법, 채취할 장소, 유효기간과 그 기간을 경과하면 집행에 착수하지 못하며 영장을 반환하여야 한다는 취지를 적고 지방법원판사가 서명날인하여야 한다.', 8183);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14113, '⑦ 디엔에이감식시료채취영장은 검사의 지휘에 의하여 사법경찰관리가 집행한다. 다만, 수용기관에 수용되어 있는 사람에 대한 디엔에이감식시료채취영장은 검사의 지휘에 의하여 수용기관 소속 공무원이 행할 수 있다.', 8183);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14114, '⑧ 검사는 필요에 따라 관할구역 밖에서 디엔에이감식시료채취영장의 집행을 직접 지휘하거나 해당 관할구역의 검사에게 집행지휘를 촉탁할 수 있다.', 8183);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14115, '⑨ 디엔에이감식시료를 채취할 때에는 채취대상자에게 미리 디엔에이감식시료의 채취 이유, 채취할 시료의 종류 및 방법을 고지하여야 한다.', 8183);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14116, '⑩ 디엔에이감식시료채취영장에 의한 디엔에이감식시료의 채취에 관하여는 「형사소송법」 제116조, 제118조, 제124조부터 제126조까지 및 제131조를 준용한다.', 8183);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14117, '① 제8조제1항 또는 제2항에 따른 디엔에이감식시료채취영장에 의하여 디엔에이감식시료가 채취된 대상자는 채취에 관한 처분에 대하여 불복이 있으면 채취가 이루어진 날부터 7일 이내에 그 직무집행지의 관할법원 또는 검사의 소속검찰청에 대응한 법원에 그 처분의 취소를 청구할 수 있다.', 8184);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14118, '② 제1항의 청구는 서면으로 관할 법원에 제출하여야 한다.', 8184);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14119, '③ 제1항의 청구가 있는 경우에는 「형사소송법」 제409조, 제413조, 제414조 및 제415조의 규정을 준용한다.', 8184);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14120, '① 제5조 및 제6조에 따라 디엔에이감식시료를 채취할 때에는 구강점막에서의 채취 등 채취대상자의 신체나 명예에 대한 침해를 최소화하는 방법을 사용하여야 한다.', 8185);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14121, '② 디엔에이감식시료의 채취 방법 및 관리에 관하여 필요한 사항은 대통령령으로 정한다.', 8185);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14122, '① 검찰총장 및 경찰청장은 다음 각 호의 업무를 대통령령으로 정하는 사람이나 기관(이하 "디엔에이신원확인정보담당자"라 한다)에 위임 또는 위탁할 수 있다. <개정 2020.1.21>', 8186);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14123, '② 디엔에이신원확인정보담당자에 대한 위임 또는 위탁, 디엔에이감식업무, 디엔에이신원확인정보의 수록 및 관리 등에 관하여 필요한 사항은 대통령령으로 정한다.', 8186);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14124, '① 디엔에이신원확인정보담당자는 다음 각 호의 어느 하나에 해당하는 경우에 디엔에이신원확인정보를 검색하거나 그 결과를 회보할 수 있다.', 8187);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14125, '② 디엔에이신원확인정보담당자는 제1항에 따라 디엔에이신원확인정보의 검색결과를 회보하는 때에는 그 용도, 작성자, 조회자의 성명 및 작성 일시를 명시하여야 한다.', 8187);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14126, '③ 디엔에이신원확인정보의 검색 및 검색결과의 회보 절차에 관하여 필요한 사항은 대통령령으로 정한다.', 8187);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14127, '① 디엔에이신원확인정보담당자가 디엔에이신원확인정보를 데이터베이스에 수록한 때에는 제5조 및 제6조에 따라 채취된 디엔에이감식시료와 그로부터 추출한 디엔에이를 지체 없이 폐기하여야 한다.', 8188);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14128, '② 디엔에이감식시료와 그로부터 추출한 디엔에이의 폐기 방법 및 절차에 관하여 필요한 사항은 대통령령으로 정한다.', 8188);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14129, '① 디엔에이신원확인정보담당자는 수형인등이 재심에서 무죄, 면소, 공소기각 판결 또는 공소기각 결정이 확정된 경우에는 직권 또는 본인의 신청에 의하여 제5조에 따라 채취되어 데이터베이스에 수록된 디엔에이신원확인정보를 삭제하여야 한다.', 8189);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14130, '② 디엔에이신원확인정보담당자는 구속피의자등이 다음 각 호의 어느 하나에 해당하는 경우에는 직권 또는 본인의 신청에 의하여 제6조에 따라 채취되어 데이터베이스에 수록된 디엔에이신원확인정보를 삭제하여야 한다.', 8189);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14131, '③ 디엔에이신원확인정보담당자는 제8조의2에 따른 수형인등 또는 구속피의자등의 불복절차에서 검사 또는 사법경찰관의 디엔에이감식시료의 채취에 관한 처분 취소결정이 확정된 경우에는 직권 또는 본인의 신청에 의하여 제5조 또는 제6조에 따라 채취되어 데이터베이스에 수록된 디엔에이신원확인정보를 삭제하여야 한다. <신설 2020.1.21>', 8189);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14132, '④ 디엔에이신원확인정보담당자는 수형인등 또는 구속피의자등이 사망한 경우에는 제5조 또는 제6조에 따라 채취되어 데이터베이스에 수록된 디엔에이신원확인정보를 직권 또는 친족의 신청에 의하여 삭제하여야 한다. <개정 2020.1.21>', 8189);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14133, '⑤ 디엔에이신원확인정보담당자는 제7조에 따라 채취되어 데이터베이스에 수록된 디엔에이신원확인정보에 관하여 그 신원이 밝혀지는 등의 사유로 더 이상 보존ㆍ관리가 필요하지 아니한 경우에는 직권 또는 본인의 신청에 의하여 그 디엔에이신원확인정보를 삭제하여야 한다. <개정 2020.1.21>', 8189);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14134, '⑥ 디엔에이신원확인정보담당자는 제1항부터 제5항까지의 규정에 따라 디엔에이신원확인정보를 삭제한 경우에는 30일 이내에 본인 또는 신청인에게 그 사실을 통지하여야 한다. <개정 2020.1.21>', 8189);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14135, '⑦ 디엔에이신원확인정보의 삭제 방법, 절차 및 통지에 관하여 필요한 사항은 대통령령으로 정한다. <개정 2020.1.21>', 8189);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14136, '① 데이터베이스의 관리ㆍ운영에 관한 다음 각 호의 사항을 심의하기 위하여 국무총리 소속으로 디엔에이신원확인정보데이터베이스관리위원회(이하 "위원회"라 한다)를 둔다.', 8190);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14137, '② 위원회는 위원장 1명을 포함한 7명 이상 9명 이하의 위원으로 구성한다.', 8190);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14138, '③ 위원은 다음 각 호의 어느 하나에 해당하는 사람 중에서 국무총리가 위촉하며, 위원장은 국무총리가 위원 중에서 지명한다.', 8190);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14139, '④ 위원의 임기는 3년으로 한다.', 8190);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14140, '⑤ 위원회는 제1항 각 호 사항의 심의에 필요하다고 인정하는 때에는 검찰총장 및 경찰청장에게 관련 자료의 제출을 요청할 수 있고, 디엔에이신원확인정보담당자 등을 위원회의 회의에 참석하게 하여 의견을 들을 수 있다.', 8190);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14141, '⑥ 위원회는 제1항 각 호의 사항을 심의하여 검찰총장 또는 경찰청장에게 의견을 제시할 수 있다.', 8190);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14142, '⑦ 제1항부터 제6항까지에서 규정한 사항 외에 위원회의 구성과 운영 등에 필요한 사항은 대통령령으로 정한다.', 8190);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14143, '① 디엔에이신원확인정보를 거짓으로 작성하거나 변개(變改)한 사람은 7년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.', 8193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14144, '② 이 법에 따라 채취한 디엔에이감식시료를 인멸, 은닉 또는 손상하거나 그 밖의 방법으로 그 효용을 해친 사람은 5년 이하의 징역 또는 700만원 이하의 벌금에 처한다.', 8193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14145, '③ 제15조를 위반하여 디엔에이감식시료 또는 디엔에이신원확인정보를 업무목적 외에 사용하거나 타인에게 제공 또는 누설한 사람은 3년 이하의 징역 또는 5년 이하의 자격정지에 처한다.', 8193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14146, '④ 다음 각 호의 어느 하나에 해당하는 사람은 2년 이하의 징역 또는 500만원 이하의 벌금에 처한다.', 8193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14147, '⑤ 디엔에이신원확인정보담당자가 정당한 사유 없이 제12조 또는 제13조를 위반하여 디엔에이감식시료와 추출한 디엔에이를 폐기하지 아니하거나 디엔에이신원확인정보를 삭제하지 아니한 때에는 1년 이하의 징역 또는 3년 이하의 자격정지에 처한다. <개정 2014.1.7>', 8193);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14148, null, 8195);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14149, '① 검찰총장 및 경찰청장은 다음 각 호의 업무에 이용하기 위하여 하드웨어, 소프트웨어, 데이터베이스, 네트워크, 보안요소 등이 결합되어 구축된 디엔에이인적관리시스템(이하 "인적관리시스템"이라 한다)을 서로 연계하여 운영하는 등 필요한 조치를 하여야 한다.', 8196);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14150, '② 인적관리시스템은 「형사사법절차 전자화 촉진법」에 따른 형사사법정보시스템을 이용할 수 있다.', 8196);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14151, '① 검찰총장 및 경찰청장은 식별코드의 생성ㆍ부착 및 제3조제1항 각 호의 업무를 담당할 디엔에이인적관리자를 소속 공무원 중에서 지정할 수 있다.', 8197);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14152, '② 디엔에이인적관리자는 인적관리시스템에 정보를 입력하거나 수정ㆍ삭제하기 위하여 그가 소속된 기관의 공무원 중에서 인적관리시스템에 접속할 권한을 부여받을 사람을 지정할 수 있다.', 8197);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14153, '③ 디엔에이인적관리자는 검사 또는 사법경찰관이 디엔에이감식시료의 중복 채취 확인, 관련 사건의 수사 등을 위하여 인적관리시스템을 열람할 수 있도록 조치할 수 있다.', 8197);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14154, '④ 디엔에이인적관리자는 인적관리시스템을 검색한 결과 법 제5조 및 제6조에 따른 디엔에이감식시료 채취대상자에 대한 디엔에이감식시료 채취가 누락된 사실을 발견한 경우 지체 없이 검사(군검사를 포함한다. 이하 같다) 또는 사법경찰관(군사법경찰관을 포함한다. 이하 같다)에게 그 사실을 통보하여야 한다. <개정 2022.6.30>', 8197);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14155, '① 검사는 법 제5조제2항에 따라 디엔에이감식시료의 채취를 위탁하기 위하여 교도소ㆍ구치소 및 그 지소, 소년원, 치료감호시설 등(이하 "수용기관"이라 한다)의 장에게 디엔에이감식시료 채취대상자의 확인 및 디엔에이감식시료 채취의 위탁에 필요한 자료를 요청할 수 있다.', 8199);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14156, '② 법 제5조제2항에 따라 검사로부터 디엔에이감식시료의 채취를 위탁받은 수용기관의 장은 지체 없이 법 제5조에 따른 디엔에이감식시료 채취대상자로부터 디엔에이감식시료를 채취하고, 채취한 디엔에이감식시료와 다음 각 호의 서류를 즉시 검사에게 보내야 한다.', 8199);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14157, '① 검찰총장 및 경찰청장은 법 제8조에 따라 디엔에이감식시료를 채취하기 위한 영장(이하 "디엔에이감식시료채취영장"이라 한다)이 발부되고 검사의 지명수배ㆍ통보 결정이 있는 경우 검사 또는 사법경찰관리가 지명수배ㆍ통보관리와 관련된 전산자료를 통하여 그 사실을 조회할 수 있도록 하여야 한다.', 8200);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14158, '② 법 제5조 또는 제6조에 따른 디엔에이감식시료 채취대상자에 대하여 법 제8조제6항에 따라 디엔에이감식시료채취영장의 집행지휘를 받은 사법경찰관리 또는 수용기관 소속 공무원은 지체 없이 디엔에이감식시료 채취대상자로부터 디엔에이감식시료를 채취하여야 한다.', 8200);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14159, '③ 제2항에 따라 디엔에이감식시료를 채취한 사법경찰관 또는 수용기관 소속 공무원은 채취한 디엔에이감식시료와 다음 각 호의 서류를 즉시 검사에게 보내야 한다. 다만, 법 제8조제6항에 따라 디엔에이감식시료채취영장의 집행지휘를 받은 사법경찰관(수용기관 소속의 사법경찰관은 제외한다)이 법 제6조에 따른 디엔에이감식시료 채취대상자로부터 디엔에이감식시료를 채취한 경우는 제외한다.', 8200);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14160, '① 법 제5조 또는 제6조에 따른 디엔에이감식시료 채취대상자로부터 디엔에이감식시료를 채취할 때에는 다음 각 호의 어느 하나에 해당하는 방법으로 하여야 한다.', 8201);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14161, '② 검찰총장 및 경찰청장은 법 제5조부터 제8조까지의 규정에 따라 디엔에이감식시료를 채취하는 경우 디엔에이감식시료가 부패 또는 오염되거나 다른 디엔에이감식시료와 바뀌지 않도록 디엔에이감식시료의 채취, 운반 및 보관에 필요한 조치를 하여야 한다.', 8201);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14162, '① 검사 또는 사법경찰관은 법 제5조 또는 제6조에 따른 디엔에이감식시료 채취대상자로부터 채취한 디엔에이감식시료와 다음 각 호의 서류를 제4조제1항에 따라 검찰총장이 지정한 디엔에이인적관리자(이하 "검찰 디엔에이인적관리자"라 한다) 또는 제4조제1항에 따라 경찰청장이 지정한 디엔에이인적관리자(이하 "경찰 디엔에이인적관리자"라 한다)에게 보내야 한다.', 8203);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14163, '② 제1항에 따라 디엔에이감식시료를 건네받은 디엔에이인적관리자는 식별코드를 생성하여 디엔에이감식시료를 담은 봉투, 용기 등에 부착하고 인적관리시스템에 인적사항등과 식별코드를 입력한 후 지체 없이 그 디엔에이감식시료를 법 제10조 및 이 영 제12조제1항에 따라 법 제10조제1항 각 호의 업무를 위임받은 대검찰청 과학수사기획관(이하 "검찰 디엔에이신원확인정보담당자"라 한다) 또는 법 제10조 및 이 영 제12조제2항제1호에 따라 법 제10조제1항 각 호의 업무를 위탁받은 국립과학수사연구원(이하 "경찰 디엔에이신원확인정보담당자"라 한다)에 보내야 한다. <개정 2010.8.13>', 8203);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14164, '③ 검찰 디엔에이신원확인정보담당자는 검사가 법 제6조에 따른 디엔에이감식시료 채취대상자로부터 채취한 디엔에이감식시료에서 취득한 디에이신원확인정보를 지체 없이 경찰 디엔에이신원확인정보담당자에게 보내야 한다.', 8203);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14165, '① 검사 또는 사법경찰관은 법 제7조에 따라 채취한 디엔에이감식시료를 지체 없이 다음 각 호의 구분에 따른 사람 또는 기관에게 보내야 한다.', 8204);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14166, '② 검찰 디엔에이신원확인정보담당자 또는 군 디엔에이감식기관은 제1항에 따라 건네받은 디엔에이감식시료에서 취득한 디엔에이신원확인정보 중 신원이 밝혀지지 아니한 것을 지체 없이 경찰 디엔에이신원확인정보담당자에게 보내야 한다.', 8204);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14167, '① 검찰총장은 법 제10조제1항에 따라 같은 항 각 호의 업무를 대검찰청 과학수사기획관에게 위임한다.', 8205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14168, '② 법 제10조제1항에 따른 경찰청장 업무의 위탁은 다음 각 호의 구분에 따른다. <개정 2010.8.13>', 8205);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14169, '① 검찰 디엔에이신원확인정보담당자ㆍ경찰 디엔에이신원확인정보담당자(이하 "디엔에이신원확인정보담당자"라 한다) 및 군 디엔에이감식기관은 디엔에이감식에 필요한 시설과 장비, 신뢰성 높은 디엔에이감식기법의 사용 등과 관련하여 국제공인시험기관으로 인정받은 기관에서 디엔에이감식을 하고, 감정서를 작성하여야 한다.', 8206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14170, '② 디엔에이신원확인정보담당자 및 군 디엔에이감식기관은 디엔에이감식과 관련하여 디엔에이감식시료가 부패 또는 오염되거나 다른 시료와 바뀌지 않도록 디엔에이감식시료의 취급에 필요한 조치를 하여야 한다.', 8206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14171, '③ 디엔에이신원확인정보담당자 및 군 디엔에이감식기관은 디엔에이감식시료 부족 등의 사유로 디엔에이신원확인정보를 확인하기 어려운 경우 검사 또는 사법경찰관에게 그 사유를 적어 디엔에이감식시료를 다시 채취해 줄 것을 요청할 수 있다.', 8206);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14172, '① 디엔에이신원확인정보담당자는 데이터베이스에 수록된 정보가 유출되거나 임의로 변경, 삭제 또는 멸실되는 것을 방지하기 위하여 데이터베이스에 보안장치 등 필요한 조치를 취하여야 한다.', 8207);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14173, '② 디엔에이신원확인정보담당자는 데이터베이스에 정보를 입력하거나 수정ㆍ삭제하거나 검색하기 위하여 그가 소속된 기관의 공무원 중에서 데이터베이스에 접속할 권한을 부여받을 사람을 지정할 수 있다.', 8207);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14174, '① 법 제11조제1항에 따라 디엔에이신원확인정보의 검색결과를 회보할 디엔에이신원확인정보담당자는 다음 각 호의 구분에 따른다.', 8208);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14175, '② 법 제11조제1항에 따른 디엔에이신원확인정보 검색결과를 회보받을 사람은 다음 각 호의 구분에 따른다.', 8208);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14176, '③ 제2항에 따라 디엔에이신원확인정보의 검색결과를 회보받은 사람은 검찰 디엔에이인적관리자 또는 경찰 디엔에이인적관리자에게 디엔에이신원확인정보 검색결과의 회보와 관련된 인적사항등을 확인해 줄 것을 요청할 수 있다.', 8208);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14177, '④ 법 제11조제1항에 따라 디엔에이신원확인정보를 검색한 결과 다른 디엔에이신원확인정보담당자가 관리하는 데이터베이스에 수록된 디엔에이신원확인정보와 대조하려는 디엔에이신원확인정보가 일치하거나 중복한다는 사실을 발견한 디엔에이신원확인정보담당자는 지체 없이 그 데이터베이스를 관리하는 디엔에이신원확인정보담당자, 그 데이터베이스에 수록된 디엔에이신원확인정보와 관련된 인적사항등을 관리하는 디엔에이인적관리자 및 검색을 요청하거나 사건을 담당하는 검사 또는 사법경찰관에게 그 사실을 감정서 등의 서면, 유선 또는 팩스 등의 방법으로 통보해야 한다. <개정 2021.1.5>', 8208);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14178, '⑤ 제4항에 따른 통보를 받은 디엔에이인적관리자는 디엔에이신원확인정보의 검색을 요청하거나 사건을 담당하는 검사 또는 사법경찰관에게 인적사항등을 확인해 줄 수 있다.', 8208);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14179, '⑥ 제1항제1호 및 제2호에 따른 디엔에이신원확인정보담당자로부터 디엔에이신원확인정보의 검색결과를 회보받은 검사 또는 사법경찰관은 해당 디엔에이감식시료 채취대상자로부터 시료를 다시 채취하여 검색결과를 회보한 디엔에이신원확인정보담당자에게 다시 감식해 줄 것을 요청할 수 있다.', 8208);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14180, '① 디엔에이신원확인정보담당자는 법 제12조제1항에 따라 지정된 장소에서 소각하거나 화학적 처리 등을 통하여 디엔에이감식시료의 재분석을 불가능하게 하는 방법으로 디엔에이감식시료와 그로부터 추출한 디엔에이 및 감식과정에서 발생한 부산물을 폐기하여야 한다.', 8209);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14181, '② 디엔에이신원확인정보담당자는 제1항에 따라 디엔에이감식시료와 그로부터 추출한 디엔에이 및 감식과정에서 발생한 부산물을 폐기한 경우 폐기 일시와 장소, 폐기한 디엔에이감식시료의 종류, 폐기 방법 등을 적은 자료를 보존하여야 한다. 이 경우 그 자료를 전자적 문서 또는 데이터베이스를 통하여 관리할 수 있다.', 8209);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14182, '① 법 제13조에 따른 디엔에이신원확인정보의 삭제 사유가 발생한 경우 검사, 사법경찰관 또는 수용기관의 장은 다음 각 호의 구분에 따라 디엔에이인적관리자에게 그 사실을 통보하여야 한다.', 8210);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14183, '② 제1항에 따라 통보를 받은 디엔에이인적관리자는 법 제5조 또는 제6조에 따른 디엔에이감식시료 채취대상자의 디엔에이신원확인정보를 법 제13조제1항부터 제3항까지의 규정에 따라 삭제하여야 하는지를 확인하기 위하여 인적관리시스템을 검색할 수 있다.', 8210);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14184, '③ 제2항에 따른 검색 결과 디엔에이신원확인정보를 삭제하여야 하는 경우 디엔에이인적관리자는 인적관리시스템에서 인적사항등 및 식별코드를 삭제한 후 검찰 디엔에이신원확인정보담당자 또는 경찰 디엔에이신원확인정보담당자에게 삭제한 식별코드를 통보하여야 한다.', 8210);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14185, '④ 디엔에이신원확인정보를 삭제한 디엔에이신원확인정보담당자는 법 제13조제5항에 따라 디엔에이신원확인정보 삭제 사실을 서면, 전자우편, 문자전송 또는 팩스의 방법으로 통지해야 한다. <개정 2021.1.5>', 8210);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14186, null, 8211);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14187, '① 법 제14조에 따른 디엔에이신원확인정보데이터베이스관리위원회(이하 "위원회"라 한다)의 위원장은 위원회를 대표하고 위원회의 업무를 총괄한다.', 8212);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14188, '② 위원회의 위원장은 위원회의 회의를 소집하고 그 의장이 된다.', 8212);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14189, '③ 위원장이 부득이한 사유로 그 직무를 수행할 수 없는 때에는 위원장이 미리 지명한 위원이 그 직무를 대행한다.', 8212);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14190, '④ 위원회의 회의는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.', 8212);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14191, '⑤ 위원회의 사무를 처리하기 위하여 위원회에 간사 2명을 두며, 간사는 디엔에이신원확인정보의 이용 및 보호에 관련한 업무에 종사하거나 관련 지식이 풍부한 대검찰청 및 경찰청 소속 공무원 중에서 검찰총장 및 경찰청장이 각 1명씩을 임명한다.', 8212);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14192, '⑥ 위원회에서 심의할 안건을 검토하고 위원회의 운영을 지원하기 위하여 위원회에 실무위원회를 둔다.', 8212);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14193, '⑦ 제1항부터 제6항까지에서 규정한 사항 외에 위원회 및 실무위원회의 운영에 필요한 사항은 위원회의 의결을 거쳐 위원장이 정한다.', 8212);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14194, null, 8213);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14195, null, 8217);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14196, null, 8219);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14197, null, 8220);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14198, '① 사회봉사는 평일 주간에 집행하는 것을 원칙으로 한다. 다만, 사회봉사 대상자의 동의 또는 신청을 받아 사회봉사 대상자의 생업, 학업, 질병 등을 고려하여 야간 또는 공휴일에 집행할 수 있다.', 8222);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14199, '② 법 제10조제2항 단서에 따라 1일 9시간을 넘겨 사회봉사를 집행하는 경우에도 1일 총 13시간을 초과할 수 없다.', 8222);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14200, '① 보호관찰관은 법 제11조 단서에 따라 사회봉사의 집행기간을 연장하려는 경우에는 그 집행기간이 끝나기 10일 전까지 관할 지방검찰청의 검사에게 서면으로 사회봉사 집행기간의 연장허가를 신청하여야 한다.', 8224);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14201, '② 검사는 제1항의 신청을 받은 날부터 7일 이내에 사회봉사 집행기간의 연장 여부를 결정하여야 한다.', 8224);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14202, '① 검사가 법 제12조제3항에 따라 사회봉사시간에 상응하는 벌금액을 산정하는 경우 및 같은 조 제5항에 따라 납부한 벌금액에 상응하는 사회봉사시간을 산정하는 경우에는 법원이 해당 사회봉사를 허가할 때에 적용한 벌금액과 사회봉사시간의 비율에 따른다.', 8225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14203, '② 법 제12조제3항에 따라 산정된 남은 벌금액 중 1천원 미만 및 같은 조 제5항에 따라 산정된 남은 사회봉사시간 중 1시간 미만은 집행하지 아니한다.', 8225);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14204, '① 검사는 사회봉사 대상자가 벌금의 전부를 낸 경우 그 사실을 지체 없이 서면으로 사회봉사를 집행 중인 보호관찰소의 장에게 통보하여야 한다.', 8226);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14205, '② 사회봉사 대상자가 미납벌금의 일부를 낸 경우 법 제12조제5항에 따른 검사의 통보는 사회봉사 허가 사건번호, 허가받은 사회봉사시간, 이행한 사회봉사시간, 납부한 벌금액, 납부한 벌금액에 상응하는 사회봉사시간 및 남은 사회봉사시간 등을 적은 서면으로 하여야 한다.', 8226);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14206, '① 검사는 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보, 같은 영 제19조제1호 또는 제4호에 따른 주민등록번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 8227);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14207, '② 보호관찰관 또는 보호관찰소의 장은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다.', 8227);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14208, '①즉결심판은 관할경찰서장 또는 관할해양경찰서장(이하 "경찰서장"이라 한다)이 관할법원에 이를 청구한다. <개정 1991.11.22, 2014.11.19, 2017.7.26>', 8230);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14209, '②즉결심판을 청구함에는 즉결심판청구서를 제출하여야 하며, 즉결심판청구서에는 피고인의 성명 기타 피고인을 특정할 수 있는 사항, 죄명, 범죄사실과 적용법조를 기재하여야 한다.', 8230);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14210, '③ 즉결심판을 청구할 때에는 사전에 피고인에게 즉결심판의 절차를 이해하는 데 필요한 사항을 서면 또는 구두로 알려주어야 한다. <신설 2009.12.29>', 8230);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14211, '①판사는 사건이 즉결심판을 할 수 없거나 즉결심판절차에 의하여 심판함이 적당하지 아니하다고 인정할 때에는 결정으로 즉결심판의 청구를 기각하여야 한다.', 8233);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14212, '②제1항의 결정이 있는 때에는 경찰서장은 지체없이 사건을 관할지방검찰청 또는 지청의 장에게 송치하여야 한다.', 8233);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14213, '①즉결심판절차에 의한 심리와 재판의 선고는 공개된 법정에서 행하되, 그 법정은 경찰관서(해양경찰관서를 포함한다)외의 장소에 설치되어야 한다. <개정 1996ㆍ8ㆍ8, 2014.11.19, 2017.7.26>', 8235);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14214, '②법정은 판사와 법원서기관, 법원사무관, 법원주사 또는 법원주사보(이하 "法院事務官등"이라 한다)가 열석하여 개정한다. <개정 1991ㆍ11ㆍ22>', 8235);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14215, '③제1항 및 제2항의 규정에 불구하고 판사는 상당한 이유가 있는 경우에는 개정없이 피고인의 진술서와 제4조의 서류 또는 증거물에 의하여 심판할 수 있다. 다만, 구류에 처하는 경우에는 그러하지 아니하다.', 8235);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14216, '①벌금 또는 과료를 선고하는 경우에는 피고인이 출석하지 아니하더라도 심판할 수 있다.', 8237);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14217, '②피고인 또는 즉결심판출석통지서를 받은 자(이하 "被告人등"이라 한다)는 법원에 불출석심판을 청구할 수 있고, 법원이 이를 허가한 때에는 피고인이 출석하지 아니하더라도 심판할 수 있다.', 8237);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14218, '③제2항의 규정에 의한 불출석심판의 청구와 그 허가절차에 관하여 필요한 사항은 대법원규칙으로 정한다.', 8237);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14219, '①판사는 피고인에게 피고사건의 내용과 「형사소송법」 제283조의2에 규정된 진술거부권이 있음을 알리고 변명할 기회를 주어야 한다. <개정 2007.12.21>', 8238);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14220, '②판사는 필요하다고 인정할 때에는 적당한 방법에 의하여 재정하는 증거에 한하여 조사할 수 있다.', 8238);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14221, '③변호인은 기일에 출석하여 제2항의 증거조사에 참여할 수 있으며 의견을 진술할 수 있다.', 8238);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14222, '①즉결심판으로 유죄를 선고할 때에는 형, 범죄사실과 적용법조를 명시하고 피고인은 7일 이내에 정식재판을 청구할 수 있다는 것을 고지하여야 한다. <개정 1991ㆍ11ㆍ22>', 8240);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14223, '②참여한 법원사무관등은 제1항의 선고의 내용을 기록하여야 한다. <개정 1991ㆍ11ㆍ22>', 8240);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14224, '③피고인이 판사에게 정식재판청구의 의사를 표시하였을 때에는 이를 제2항의 기록에 명시하여야 한다.', 8240);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14225, '④제7조제3항 또는 제8조의2의 경우에는 법원사무관등은 7일 이내에 정식재판을 청구할 수 있음을 부기한 즉결심판서의 등본을 피고인에게 송달하여 고지한다. 다만, 제8조의2제2항의 경우에 피고인등이 미리 즉결심판서의 등본송달을 요하지 아니한다는 뜻을 표시한 때에는 그러하지 아니하다. <개정 1991ㆍ11ㆍ22>', 8240);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14226, '⑤판사는 사건이 무죄ㆍ면소 또는 공소기각을 함이 명백하다고 인정할 때에는 이를 선고ㆍ고지할 수 있다.', 8240);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14227, '①유죄의 즉결심판서에는 피고인의 성명 기타 피고인을 특정할 수 있는 사항, 주문, 범죄사실과 적용법조를 명시하고 판사가 서명ㆍ날인하여야 한다.', 8241);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14228, '②피고인이 범죄사실을 자백하고 정식재판의 청구를 포기한 경우에는 제11조의 기록작성을 생략하고 즉결심판서에 선고한 주문과 적용법조를 명시하고 판사가 기명ㆍ날인한다.', 8241);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14229, '①정식재판을 청구하고자 하는 피고인은 즉결심판의 선고ㆍ고지를 받은 날부터 7일 이내에 정식재판청구서를 경찰서장에게 제출하여야 한다. 정식재판청구서를 받은 경찰서장은 지체없이 판사에게 이를 송부하여야 한다. <개정 1991ㆍ11ㆍ22>', 8243);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14230, '②경찰서장은 제11조제5항의 경우에 그 선고ㆍ고지를 한 날부터 7일 이내에 정식재판을 청구할 수 있다. 이 경우 경찰서장은 관할지방검찰청 또는 지청의 검사(이하 "檢事"라 한다)의 승인을 얻어 정식재판청구서를 판사에게 제출하여야 한다. <개정 1991ㆍ11ㆍ22>', 8243);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14231, '③판사는 정식재판청구서를 받은 날부터 7일 이내에 경찰서장에게 정식재판청구서를 첨부한 사건기록과 증거물을 송부하고, 경찰서장은 지체없이 관할지방검찰청 또는 지청의 장에게 이를 송부하여야 하며, 그 검찰청 또는 지청의 장은 지체없이 관할법원에 이를 송부하여야 한다. <개정 1991ㆍ11ㆍ22>', 8243);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14232, '④형사소송법 제340조 내지 제342조, 제344조 내지 제352조, 제354조, 제454조, 제455조의 규정은 정식재판의 청구 또는 그 포기ㆍ취하에 이를 준용한다.', 8243);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14233, '①판사는 구류의 선고를 받은 피고인이 일정한 주소가 없거나 또는 도망할 염려가 있을 때에는 5일을 초과하지 아니하는 기간 경찰서유치장(지방해양경찰관서의 유치장을 포함한다. 이하 같다)에 유치할 것을 명령할 수 있다. 다만, 이 기간은 선고기간을 초과할 수 없다. <개정 1996ㆍ8ㆍ8, 2014.11.19, 2017.7.26>', 8246);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14234, '②집행된 유치기간은 본형의 집행에 산입한다.', 8246);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14235, '③형사소송법 제334조의 규정은 판사가 벌금 또는 과료를 선고하였을 때에 이를 준용한다.', 8246);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14236, '①형의 집행은 경찰서장이 하고 그 집행결과를 지체없이 검사에게 보고하여야 한다.', 8247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14237, '②구류는 경찰서유치장ㆍ구치소 또는 교도소에서 집행하며 구치소 또는 교도소에서 집행할 때에는 검사가 이를 지휘한다.', 8247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14238, '③벌금, 과료, 몰수는 그 집행을 종료하면 지체없이 검사에게 이를 인계하여야 한다. 다만, 즉결심판 확정후 상당기간내에 집행할 수 없을 때에는 검사에게 통지하여야 한다. 통지를 받은 검사는 형사소송법 제477조에 의하여 집행할 수 있다.', 8247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14239, '④형의 집행정지는 사전에 검사의 허가를 얻어야 한다.', 8247);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14240, '① 소년부 판사가 결정을 할 때에는 결정서를 작성하고 서명날인하여야 한다. 다만 상당하다고 인정할 때에는 결정의 내용을 조서에 기재하게 하여 결정서의 작성에 갈음할 수 있고, 다음 각 호의 결정 이외에는 서명날인을 기명날인으로 갈음할 수 있다.', 8250);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14241, '② 결정서에는 소년의 성명, 주민등록번호(기록상 주민등록번호를 알 수 없을 때에는 생년월일, 이하 ‘주민등록번호 등’이라 한다.), 직업, 주거, 등록기준지 및 주문과 이유를 기재하여야 한다. 다만, 다음 각 호의 결정을 제외한 결정의 결정서에는 소년의 성명, 주민등록번호 등, 주거 및 주문 이외의 기재를 생략할 수 있다.', 8250);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14242, '① 법 제32조제1항에 따른 결정은 심리 기일에 결정서에 의하여 고지하여야 한다. <개정 2008.6.5>', 8251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14243, '②제1항의 결정 이외의 결정은 법 및 이 규칙에 특별한 정함이 없는 경우에도 소년과 보호자에게 통지하여야 한다.', 8251);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14244, '①법 제18조제1항의 결정에 따라 위탁된 소년에 관하여 제22조 및 법 제6조, 법 제7조, 법 제19조, 법 제29조, 법 제32조제1항, 법 제49조제2항, 법 제51조에 따른 결정을 한 경우에는 위탁받은 자에게 그 결정을 통지하여야 한다.', 8252);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14245, '② 보호처분이 계속 중인 소년에 관하여 법 제33조제1항, 제3항, 법 제37조부터 제40조까지 및 법 제45조에 따른 결정을 한 경우에는 위탁받은 자 또는 보호처분을 집행하는 자에게 그 결정을 통지하여야 한다.', 8252);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14246, '① 법 제4조제3항에 따른 통고는 서면 또는 구술로 할 수 있다. <개정 2008.6.5>', 8254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14247, '②제1항의 통고에는 소년과 보호자의 성명, 생년월일, 직업, 주거, 등록기준지, 통고자의 성명, 통고하게 된 사유 및 소년의 처우에 관한 의견을 명시하여야 한다. <개정 2007.12.31>', 8254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14248, '③구술의 통고가 있는 때에는 소년부 법원서기관, 법원사무관, 법원주사 또는 법원주사보(이하 "법원사무관등"이라 한다)는 이를 조서에 기재하고 서명날인하여야 한다.', 8254);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14249, '① 검사가 법 제4조제1항제1호에 해당하는 소년 보호사건을 송치하는 경우에는 법 제5조에 따른 송치서에 범죄사실과 적용법조를 명시하여야 한다.', 8255);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14250, '② 법 제5조의 참고자료는 관계되는 서류와 증거물 전부를 말한다.', 8255);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14251, '③ 공범이 있거나 그 밖의 사유로 법 제5조에 따른 송치서에 제2항의 참고자료를 첨부할 수 없는 경우에는 그 중 소년 보호사건과 관련되는 부분의 등본을 첨부하여야 한다.', 8255);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14252, '① 법 제7조제1항에 따라 검사에게 송치하는 결정을 할 때에는 범죄사실과 적용법조를 명시하여야 한다.', 8256);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14253, '② 법 제7조에 따라 사건을 검사에게 송치할 때에는 관계되는 서류와 증거물 전부를 검사에게 넘겨야 한다. 다만, 공범이 있거나 그 밖의 사유로 이를 넘길 수 없는 때에는 송치하는 사건과 관련되는 부분의 등본을 넘겨야 한다.', 8256);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14254, null, 8257);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14255, '① 조사는 다음 각 호의 사항에 관하여 한다.', 8259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14256, '② 조사관은 필요한 경우에 공무소나 공사단체에 조회하여 필요한 사항의 조사, 보고 또는 필요한 사건기록이나 서류를 넘겨줄 것을 요구할 수 있다.', 8259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14257, '③ 조사관은 제1항 각 호의 사항을 조사하기 위하여 소년, 보호자, 참고인 그 밖에 필요한 사람의 출석을 요구하거나 방문하여 면접, 관찰 또는 심리검사 등을 할 수 있다. 이 경우의 출석요구는 출석요구서의 송달 그 밖에 적당한 방법으로 할 수 있다.', 8259);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14258, '①조사관은 조사의 결과를 의견을 붙인 서면으로 보고하여야 한다.', 8260);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14259, '②조사관은 제1항의 보고의 전후를 통하여 소년부 판사에게 소년의 처우에 관한 의견을 진술할 수 있다. <개정 2008.6.5>', 8260);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14260, '① 법 제13조제1항에 따른 소년, 보호자 또는 참고인의 소환은 소환장을 송달함으로써 한다.', 8262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14261, '② 제1항의 소환장에는 소년의 성명, 생년월일과 소환되는 사람의 성명, 소년 보호사건에 관하여 소환하는 뜻, 출석할 일시와 장소, 소년이나 보호자가 정당한 이유없이 소환해 응하지 아니할 때에는 동행영장을 발부할 수 있다는 뜻을 기재하고 소년부 판사가 기명날인하여야 한다.', 8262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14262, '③ 제1항의 송달에 관하여는 「민사소송법」 중 송달에 관한 규정 및 「형사소송법」 제76조제2항부터 제5항까지를 준용한다. 다만, 「민사소송법」 중 제187조 및 공시송달에 관한 규정은 그러하지 아니하다.', 8262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14263, '④ 제3항은 법 및 이 규칙에 정한 다른 송달에도 이를 준용한다.', 8262);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14264, '① 법 제18조제1항의 결정에 따라 위탁된 소 년이 제11조제3항에 따른 출석요구 또는 법 제13조제1항에 따른 소환을 받은 때에는 위탁받은 자는 지정된 기일에 그 소년을 출석시켜야 한다.', 8263);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14265, '② 제1항의 경우에 위탁받은 자가 소년분류심사원 또는 소년분류심사원의 업무를 행하는 소년원(이하 "소년분류심사원"이라 한다)인 때에는 소년분류심사원 소속 공무원은 소년을 호송하고 당일의 조사 또는 심리가 종료될 때까지 소년부 청사 안에서 소년을 감호하여야 한다.', 8263);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14266, '① 법 제14조에 따른 동행영장에는 법 제15조가 정한 기재사항 외에 소년을 보호하기 위하여 긴급조치가 필요한 이유를 구체적으로 기재하여야 한다. <개정 2008.6.5>', 8264);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14267, '② 삭제 <1995.5.20>', 8264);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14268, '①동행영장은 소년부 판사의 지휘에 의하여 집행한다. <개정 2008.6.5>', 8265);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14269, '②제1항의 집행지휘는 동행영장을 법 제16조에 정한 집행담당자에게 교부함으로써 한다.', 8265);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14270, '①동행영장을 집행함에는 피동행자에게 이를 제시하고 신속히 지정된 장소에 동행하여야 한다.', 8266);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14271, '② 동행영장을 소지하지 않은 경우 급속을 요할 때에는 제1항의 규정에 불구하고 피동행자에게 비행사실 및 동행영장이 발부되었음을 고지하고 집행할 수 있다. 이 경우에는 집행완료 후 신속히 동행영장을 제시하여야 한다. <개정 2008.6.5>', 8266);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14272, '③ 동행영장을 집행한 때에는 동행영장에 집행한 일시, 장소를, 집행할 수 없었을 때에는 그 사유를 각 기재하고 기명날인하여 이를 소년부 판사에게 제출하여야 한다. <개정 2008.6.5>', 8266);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14273, '④ 제3항에 따라 동행영장을 제출받은 소년부 판사는 피동행자가 동행된 경우 법원사무관등에게 그 동행일시를 동행영장에 기재하게 하여야 한다. <개정 2008.6.5>', 8266);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14274, '① 국선보조인은 다음 각 호의 사람 중에서 선정 한다.', 8268);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14275, '②소년부 판사는 제9조제3호의 고지를 받은 소년 및 보호자가 보조인을 선임하지 아니한 때 및 법 제17조의2제2항에 따라 국선보조인 선정이 필요하다고 인정하는 경우에는 지체 없이 국선보조인을 선정하고, 소년, 보호자 및 보조인에게 그 뜻을 고지하여야 한다.', 8268);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14276, '③ 국선보조인의 선정ㆍ보수 등 이 규칙에서 따로 정하지 아니한 사항에 대하여는 소년 보호사건의 성질에 어긋나지 아니하는 범위 내에서 「형사소송규칙」, 「형사소송비용 등에 관한 규칙」 중국선변호인에 관한 규정을 준용한다.', 8268);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14277, '① 소년이 심리 기일에 출석하지 아 니한 때에는 심리를 할 수 없다.', 8273);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14278, '② 법 제17조의2제1항에 해당하는 사건 및 같은 조 제2항에 따라 보조인이 선정된 사건에 관하여 보조인이 심리 기일에 출석하지 아니한 때에는 심리를 할 수 없다.', 8273);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14279, '① 소년부 판사가 심리를 할 때에 는 비행사실의 내용을 고지하고 그 이익되는 사실을 진술할 기회를 주어야 한다.', 8274);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14280, '② 동일 소년에 대한 2개 이상의 보호사건 및 관련 보호사건은 될 수 있는 한 병합하여 심리하여야 한다.', 8274);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14281, '①소년부 판사는 심리의 공평을 해할 만한 상당한 사유가 있다고 인정할 때에는 그 직무의 집행을 회피하여야 한다. <개정 2008.6.5>', 8275);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14282, '②제1항은 법원사무관등 및 조사관에게도 이를 준용한다.', 8275);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14283, '① 소년부 판사는 보호처분을 하기 전까지 법 제25조의3제1항에 따른 화해를 권고할 수 있다. 이 경우 화해를 권고하기 위한 기일(이하 "화해권고기일"이라 한다)까지 소년, 보호자 및 피해자(피해자가 미성년자인 경우 그 보호자도 포함한다. 이하 같다)의 서면에 의한 동의를 받아야 한다.', 8276);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14284, '② 소년, 보호자 및 피해자는 화해권고절차가 종료할 때까지 제1항에 따른 동의를 서면에 의하여 철회할 수 있다.', 8276);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14285, '① 가정법원장 또는 소년부가 설치되어 있는 지방법원장(이하 "법원장"이라 한다)은 법 제25조의3제1항에 따른 피해자와의 화해를 권고하기 위하여 갈등해결에 전문적인 소양과 능력이 있거나, 법학, 심리학, 교육학, 정신의학, 보건간호학, 사회복지학, 가족치료학, 상담학, 가족관계학 그 밖에 소년보호사건과 연관된 분야에서 전문적인 지식과 경험이 있는 사람 중에서 화해권고위원을 위촉할 수 있다.', 8278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14286, '② 화해권고위원의 위촉 및 해촉에 관하여는 「조정위원규칙」 제3조 및 제4조제1항, 제2항을 준용한다. 이 경우 "조정위원"은 "화해권고위원"으로, "조정기일"은 "화해권고기일"로 본다.', 8278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14287, '③ 소년부 판사는 제26조의3에 따라 화해권고위원으로 하여금 화해를 권고하게 하는 경우 소년, 보호자 및 피해자의 의견을 들어 각 사건마다 2인 이상의 화해권고위원을 지정하여야 한다.', 8278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14288, '④ 화해권고위원에게는 대법원 예규로 정하는 바에 따라 수당을 지급한다.', 8278);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14289, '① 소년부 판사는 화해권고위원으로 하여금 화해권고기일 전에 분쟁해결에 관하여 소년, 보호자 및 피해자의 의견을 청취하게 할 수 있다.', 8280);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14290, '② 화해권고기일에 소환을 받은 소년, 보호자 또는 피해자는 본인이 출석하여야 한다. 다만, 특별한 사정이 있을 때에는 소년부 판사의 허가를 받아 대리인을 출석하게 할 수 있고, 보조인을 동반할 수 있다.', 8280);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14291, '③ 화해권고위원 등 화해권고기일에 참여한 사람은 화해권고와 관련하여 알게 된 사항을 누설하여서는 아니 된다.', 8280);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14292, '④ 화해권고기일의 소환에 관하여는 제14조를 준용한다. 이 경우 "소년 보호사건"은 "화해권고"로 본다.', 8280);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14293, '① 법원사무관등은 화해권고기일마다 화해권고절차에 관한 조서(이하 "화해권고기일조서"라 한다)를 작성하여야 한다.', 8281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14294, '② 화해권고기일조서에 관하여는 제28조를 준용한다. 이 경우 "심리"는 "화해권고"로 본다.', 8281);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14295, '① 소년부 판사는 화해가 성립한 경우 조사관, 법원사무관등으로 하여금 그 이행실태에 대하여 조사하게 하고, 지체 없이 그 결과를 보고하도록 할 수 있다. 이 경우 소년부 판사는 이행의 확인을 위한 심리 기일을 열 수 있다.', 8282);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14296, '② 소년부 판사가 법 제25조의3제3항에 따라 화해권고의 결과를 고려할 경우 화해가 성립되지 아니하였다는 사정을 소년에게 불리하게 고려하여서는 아니 된다.', 8282);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14297, '① 심리 기일의 심리절차에 관하여는 참여한 법원사 무관등이 심리조서를 작성하여야 한다.', 8285);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14298, '② 심리조서에는 다음 사항을 기재하여야 한다.', 8285);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14299, '③ 심리에 참여한 법원사무관등은 소년부 판사의 허가가 있을 때에는 제2항의 기재사항 중 일부를 생략할 수 있다.', 8285);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14300, '④ 심리조서에 관하여 이 규칙에 규정되지 않은 사항은 보호사건의 성질에 어긋나지 아니하는 한「형사소송법」 제48조부터 제59조까지 및 「형사소송규칙」 제29조부터 제41조까지를 준용한다.', 8285);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14301, '①소년, 보호자 및 보조인은 결정서 또는 결정을 기재한 조서의 등본, 초본 또는 심판에 관한 사항의 증명서의 교부를 법원사무관등에게 청구할 수 있다.', 8287);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14302, '②법원사무관등은 제1항의 등본, 초본 또는 증명서를 작성할 때에는 등본, 초본 또는 심판에 관한 사항의 증명서라는 취지를 기재한 후 기명날인하여야 한다.', 8287);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14303, '① 보호처분의 결정을 고지할 때 에는 소년 및 출석한 보호자에 대하여 보호처분의 취지를 이해할 수 있도록 친절히 설명하여야 한다.', 8288);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14304, '② 소년부 판사가 법 제32조제1항제2호ㆍ제3호에 따라 수강명령 또는 사회봉사명령의 처분을 하는 경우에는 소년이 이행하여야 할 총 수강시간 또는 총 사회봉사시간과 집행기한을 정하여야 한다. 이 경우 필요하다고 인정하는 때에는 수강할 강의의 종류나 방법 및 그 시설, 사회봉사의 종류나 방법 및 그 대상이 될 시설 등을 지정할 수 있다.', 8288);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14305, '③ 소년부 판사가 법 제32조제1항제8호에 따라 1개월 이내의 소년원 송치를 명하는 경우에, 법 제32조제1항제5호 처분과 병합하는 경우 등 필요하다고 인정하는 때에는 소년이 입원하여야 할 소년원과 입원 연월일을 지정할 수 있다.', 8288);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14306, '④ 소년부 판사가 법 제32조의2제1항에 따라 「보호소년 등의 처우에 관한 법률」에 따른 대안교육 또는 소년의 상담ㆍ선도ㆍ교화와 관련된 단체나 시설에서의 상담ㆍ교육을 받을 것을 동시에 명하는 경우에는 소년이 대안교육 또는 상담ㆍ교육을 받을 대안교육기관, 단체 또는 시설, 대안교육 또는 상담ㆍ교육을 받을 기간 및 총 시간을 지정하여야 한다.', 8288);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14307, '⑤ 소년부 판사가 법 제32조의2제3항에 따라 보호자에게 소년원ㆍ소년분류심사원 또는 보호관찰소 등에서 실시하는 소년의 보호를 위한 특별교육을 받을 것을 명하는 경우에는 특별교육을 받을 보호자, 특별교육을 받을 기관, 특별교육을 받을 기간 및 총 시간을 지정하여야 한다.', 8288);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14308, '⑥ 제1항의 경우에는 소년부 판사는 항고기간과 항고법원을 알려주어야 한다.', 8288);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14309, '① 법원장은 법 제18조제1항제1호, 법 제32조제1항제1호에 따라 보호자를 대신하여 소년의 감호를 위탁받을 사람(이하 "위탁보호위원"이라 한다)을 정신과 의사, 심리학자, 사회사업가,「청소년복지 지원법」제31조제4호에 정한 청소년회복지원시설의 종사자 중 시설장의 자격기준을 충족하는 사람 또는 학식과 덕망이 있는 사람 중에서 위촉한다. <개정 2012.2.24, 2016.11.1>', 8290);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14310, '② 법원장은 제1항의 위탁보호위원이 소년의 보호에 적당하지 아니하거나 그 밖의 사유로 그 직무를 적절히 수행하기 어렵다고 인정하는 때에는 그 위촉을 해제할 수 있다. <개정 2012.2.24>', 8290);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14311, '③ 법원장은 제2항에 따라 해촉하는 위탁보호위원이「청소년복지 지원법」제31조제4호에 정한 청소년회복지원시설의 종사자 중 시설장인 경우에는 해당 청소년회복지원시설이 있는 지역을 관할하는 특별자치도지사 또는 시장ㆍ군수ㆍ구청장에게 그 사실을 통지하여야 한다. <신설 2016.11.1>', 8290);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14312, '① 법원장은 법 제18조제1항제1 호, 제2호, 법 제32조제1항제6호, 7호에 규정된 아동복지시설 그 밖의 소년보호시설, 병원, 요양소, 「보호소년 등의 처우에 관한 법률」상의 소년의료보호시설 등의 위탁받는 기관을 지정하여야 한다.', 8291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14313, '② 법원장은 법 제32조제1항제2호ㆍ제3호에 따라 소년이 수강 또는 사회봉사할 장소 또는 시설을 지정할 수 있다.', 8291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14314, '③ 제2항의 지정을 할 때에는 보호관찰소의 장으로 하여금 필요한 보고를 하게 하거나 그 의견을 들을 수 있다.', 8291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14315, '④ 법원장은 법 제32조의2제1항ㆍ제3항에 따라 소년이 대안교육 또는 상담ㆍ교육을 받을 대안교육기관, 단체 또는 시설이나 보호자가 특별교육을 받을 기관을 지정할 수 있다.', 8291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14316, '⑤ 제1항, 제2항 및 제4항에 따른 위탁받는 기관 등은 소년에 대한 환경의 조정과 품행의 교정이나 보호자에 대한 특별교육에 적당한 곳이어야 하고, 이를 지정할 때에는 미리 그 시설의 운영자와 협의하여야 한다.', 8291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14317, '⑥ 법원장은 언제든지 법원소속 공무원으로 하여금 제1항, 제2항 및 제4항에 따라 지정된 위탁받는 기관 등이 소년의 보호나 보호자 특별교육에 충분한 시설을 가지고 있는가의 여부와 그 운영실태를 조사, 보고하도록 하고 이에 부적당하다고 인정되는 경우에는 그 지정을 취소할 수 있다.', 8291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14318, '⑦ 소년부는 제2항 및 제4항에 따른 위탁받는 기관 등(소년원, 소년분류심사원, 보호관찰소, 「보호소년 등의 처우에 관한 법률」상의 대안교육기관 및 사회봉사할 장소 또는 시설은 제외한다)에게 그 집행에 관한 비용의 전부 또는 일부를 지급할 수 있다. <신설 2009.3.31>', 8291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14319, '① 법 제33조제3항에 따른 장 기 보호관찰기간의 연장 신청은 서면으로 하여야 한다.', 8292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14320, '② 제1항의 서면에는 보호관찰을 계속할 상당한 이유를 기재하고, 이를 소명하여야 한다.', 8292);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14321, '① 법 제36조제2항에 따라 보고의 명을 받은 조사관은 지시사항의 이행여부, 위탁받은 자의 감호상황 또는 소년부 판사가 특히 필요하다고 인정하는 사항을 조사하여 의견을 붙인 서면으로 보고하여야 한다.', 8295);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14322, '② 조사관이 제1항의 조사를 할 때에는 다음 각 호의 행위를 할 수 있다.', 8295);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14323, '① 법 제37조제1항 본문에 따른 보호처분 또는 부가처분의 변경 신청은 서면으로 하여야 한다.', 8296);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14324, '② 제1항의 서면에는 보호처분 또는 부가처분을 변경할 상당한 이유를 기재하고, 이를 소명하여야 한다.', 8296);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14325, '③ 소년부 판사는 보호처분 또는 부가처분을 변경함에 있어 필요하다고 인정하는 때에는 소년, 보호자 또는 참고인을 소환하고, 법 제18조의 임시조치를 할 수 있으며, 필요한 사항을 조사, 심리할 수 있다.', 8296);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14326, '① 소년부 판사는 심리 중에 소년 이 10세 미만인 것이 밝혀진 경우에는 그 심리 개시 결정을 취소하고 심리 불개시 결정을 하여야 한다.', 8299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14327, '② 법 제4조제1항제1호ㆍ제2호의 소년에 대한 보호처분이 계속 중일 때에 그 소년이 행위 당시 10세 미만으로 밝혀진 경우 또는 법 제4조제1항제3호의 소년에 대한 보호처분이 계속 중일 때에 그 소년이 처분 당시 10세 미만으로 밝혀진 경우에는 법 제38조제2항에 따라 그 보호처분을 취소하고 제1항의 예에 따른다.', 8299);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14328, '①보호자 또는 법정대리인이 있는 소년이 항고를 취하함에는 보호자 또는 법정대리인의 동의를 얻어야 한다.', 8302);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14329, '②보호자, 보조인 또는 법정대리인은 소년의 동의를 얻어 항고를 취하할 수 있다.', 8302);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14330, '① 소년분류심사원 또는 소년원에 있는 소년이 항고 제기기간 내에 항고장을 그 기관의 장 또는 그 직무를 대리하는 사람에게 제출한 때에는 항고제기기간 내에 항고한 것으로 본다.', 8303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14331, '②제1항에 따라 항고장을 제출받은 기관의 장 또는 그 대리자는 항고장에 접수연월일을 기재하여 즉시 보호처분 결정을 한 소년부에 보내야 한다.', 8303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14332, '①항고법원은 항고이유에 기재된 사항에 관하여 조사하여야 한다.', 8304);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14333, '②항고법원은 법 제43조제1항 각 호의 사유에 관하여는 직권으로 조사할 수 있다. <개정 2008.6.5>', 8304);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14334, '①항고법원은 필요한 경우에 사실조사를 할 수 있다.', 8305);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14335, '②제1항의 조사는 이를 합의부원에게 명하거나, 가정법원 또는 지방법원판사에게 촉탁하여 할 수 있다.', 8305);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14336, '① 항고법원이 원결정을 취소하는 결정을 한 경우에 소년이 법 제32조제1항제6호 및 제7호에 따른 위탁받는 기관 또는 제8호부터 제10호까지에 따른 소년원(이하 이 조에서는 "시설"이라 한다)에 있는 때에는 지체 없이 이를 시설의 장에게 통지하여야 한다. <개정 2008.6.5>', 8306);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14337, '②항고법원이 제1항의 통지를 하는 때에는 즉시 취소결정의 등본을 환송 또는 이송을 받을 소년부로 보내야 한다. <개정 2008.6.5>', 8306);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14338, '③시설의 장이 제1항의 통지를 받은 때에는 즉시 소년을 환송 또는 이송을 받을 소년부로 송치하여야 한다.', 8306);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14339, '① 항고법원으로부터 사건을 환송 또는 이송받은 소년부 판사는 환송 또는 이송받은 사건에 관하여 다시 심리하여야 한다.', 8308);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14340, '② 제1항의 경우에 원결정을 한 소년부 판사는 심리에 관여할 수 없다.', 8308);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14341, '① 대법원은 법 제47조에 따른 재항고의 절 차가 법 및 이 규칙의 규정에 위반되거나, 재항고이유가 없다고 인정될 때에는 재항고를 기각하여야 한다.', 8309);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14342, '② 재항고가 이유 있다고 인정할 때에는 원결정 및 보호처분 결정을 취소하고 사건을 소년부에 환송하거나 다른 소년부에 이송하여야 한다.', 8309);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14343, null, 8313);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14344, '① 이 법은 국군 및 국군과 공동작전에 종사하고 있는 외국군의 군용물 등에 대한 범죄에 적용한다.', 8315);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14345, '② 이 법이 적용되는 군용물의 범위는 군용(軍用)으로 사용되는 물건으로서 다음 각 호의 어느 하나에 해당하는 것으로 한다.', 8315);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14346, '① 군용물에 관하여 다음 각 호의 죄를 범한 사람은 무기 또는 1년 이상의 징역에 처한다. <개정 2016.1.6>', 8316);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14347, '② 제1항에도 불구하고 군용물 중 별표에 따른 군용 식량, 군복류 및 군용 유류(油類)에 관하여 제1항 각 호의 죄를 범한 사람은 다음 각 호의 어느 하나에 해당하는 경우에만 제1항에 따른 형을 적용한다.', 8316);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14348, '③ 제1항 및 제2항의 죄에 대하여는 10년 이하의 자격정지(유기징역을 선고하는 경우만 해당한다) 또는 3천만원 이하의 벌금을 병과(倂科)할 수 있다.', 8316);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14349, '① 군의 요새(要塞)ㆍ진영(陣營) 또는 군용에 공하는 함선, 항공기, 공장, 건조물, 설비와 군용 표지가 있는 장소에 침입한 사람은 5년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 8317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14350, '② 제1항의 장소에서 퇴거 요구를 받고 이에 따르지 아니한 사람도 제1항에 따른 형을 적용한다.', 8317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14351, '③ 제1항 및 제2항에 따른 죄의 미수범은 처벌한다.', 8317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14352, '① 「사법경찰관리의 직무를 수행할 자와 그 직무범위에 관한 법률」 제9조제1항에 따라 사법경찰관리의 직무를 하는 사람은 「군형법」의 적용대상자가 아닌 이 법 위반 피의자(이하 "피의자"라 한다)에 대한 범죄수사를 할 때에는 미리 검사의 지휘를 받아야 하며 검사의 직무상 명령에 복종하여야 한다. 다만, 현행범인 경우와 긴급한 조치가 필요하여 미리 지휘를 받을 수 없는 경우에는 사후(事後)에 지체 없이 검사의 지휘를 받아야 한다.', 8319);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14353, '② 지방검찰청 검사장 또는 지청장은 피의자에 대한 불법 구속의 여부를 조사하기 위하여 필요하다고 인정하면 소속 검사로 하여금 관하(管下) 군 수사기관의 피의자 구속장소를 감찰하게 하며, 감찰하는 검사는 피의자를 심문(審問)하고 구속에 관한 서류를 조사할 수 있다.', 8319);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14354, '③ 검사는 피의자가 불법으로 구속된 것이라고 의심할 만한 충분한 이유가 있는 경우에는 즉시 피의자에 관한 사건을 검찰에 송치할 것을 명할 수 있다.', 8319);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14355, '①「도로교통법」 제165조제2항, 경범죄 처벌법 제9조제2항의 규정에 의한 즉결심판청구의 취소는 별지 제1호서식의 즉결심판청구 취소장으로 하여야 한다. 다만, 법정에서는 구술로써 할 수 있다. <개정 2009.1.9, 2014.4.3>', 8321);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14356, '②제1항 단서의 경우에는 법원서기관, 법원사무관, 법원주사 또는 법원주사보는 이를 기록하여야 한다.', 8321);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14357, '① 「식품위생법」 제37조제1항, 제4항 및 제5항의 허가를 받지 아니하거나 신고 또는 등록을 하지 아니하고 제조ㆍ가공한 사람, 「건강기능식품에 관한 법률」 제5조에 따른 허가를 받지 아니하고 건강기능식품을 제조ㆍ가공한 사람, 이미 허가받거나 신고된 식품, 식품첨가물 또는 건강기능식품과 유사하게 위조하거나 변조한 사람, 그 사실을 알고 판매하거나 판매할 목적으로 취득한 사람 및 판매를 알선한 사람, 「식품위생법」 제6조, 제7조제4항 또는 「건강기능식품에 관한 법률」 제24조제1항을 위반하여 제조ㆍ가공한 사람, 그 정황을 알고 판매하거나 판매할 목적으로 취득한 사람 및 판매를 알선한 사람은 다음 각 호의 구분에 따라 처벌한다. <개정 2017.12.19>', 8326);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14358, '② 제1항의 경우에는 제조, 가공, 위조, 변조, 취득, 판매하거나 판매를 알선한 제품의 소매가격의 2배 이상 5배 이하에 상당하는 벌금을 병과(倂科)한다.', 8326);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14359, '① 「약사법」 제31조제1항의 허가를 받지 아니하고 의약품을 제조한 사람, 그 정황을 알고 판매하거나 판매할 목적으로 취득한 사람 및 판매를 알선한 사람 또는 진료 목적으로 구입한 사람, 「약사법」 제62조제2호를 위반하여 주된 성분의 효능을 전혀 다른 성분의 효능으로 대체하거나 허가된 함량보다 현저히 부족하게 제조한 사람, 그 정황을 알고 판매하거나 판매할 목적으로 취득한 사람 및 판매를 알선한 사람 또는 진료 목적으로 구입한 사람, 이미 허가된 의약품과 유사하게 위조하거나 변조한 사람, 그 정황을 알고 판매하거나 판매할 목적으로 취득한 사람 및 판매를 알선한 사람 또는 진료 목적으로 구입한 사람은 다음 각 호의 구분에 따라 처벌한다. <개정 2011.6.7>', 8327);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14360, '② 제1항의 경우에는 제조, 위조, 변조, 취득, 판매, 판매를 알선하거나 구입한 제품의 소매가격의 2배 이상 5배 이하에 상당하는 벌금을 병과한다.', 8327);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14361, '① 「화학물질관리법」 제28조에 따른 영업허가를 받지 아니하거나 신고를 하지 아니하고 유해화학물질을 제조한 사람, 이미 허가되거나 신고한 유해화학물질과 유사하게 위조하거나 변조한 사람은 다음 각 호의 구분에 따라 처벌한다. <개정 2024.2.6>', 8329);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14362, '② 제1항의 경우에는 제조, 사용, 위조 또는 변조한 제품의 소매가격의 2배 이상 5배 이하에 상당하는 벌금을 병과한다.', 8329);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14363, null, 8330);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14364, '① 이 법에 따라 처벌을 받았거나, 그 제품이 규격기준을 위반하여 인체에 유해하거나, 효능 또는 함량이 현저히 부족하다고 식품의약품안전처에서 검정된 영업에 대하여는 해당 허가, 면허 또는 등록을 관할하는 기관의 장은 보건복지부장관, 식품의약품안전처장 또는 환경부장관의 요구에 따라 그 허가, 면허 또는 등록을 취소하여야 한다. <개정 2013.3.23>', 8332);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14365, '② 제1항의 경우 이 법에 따라 영업이 취소된 자는 취소된 날부터(처벌을 받은 자는 그 형의 집행이 종료되거나 집행을 받지 아니하기로 확정된 후) 5년간 해당 업무에 종사하지 못한다.', 8332);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14366, '① 이 법에서 규정하는 범죄를 범죄가 발각되기 전에 수사기관 또는 감독청에 통보한 자 또는 검거한 자에게는 대통령령으로 정하는 바에 따라 상금을 지급한다.', 8334);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14367, '② 타인으로 하여금 이 법에 따른 처벌 또는 행정처분을 받게 할 목적으로 거짓 정보를 제공한 사람은 1년 이상의 유기징역에 처한다.', 8334);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14368, null, 8338);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14369, null, 8339);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14370, '①법 제3조제1항제1호의 규정에 의한 "인체에 현저한 유해"의 기준은 대한약전 또는 보건복지부장관이 지정하는 공정서에 극량이 표시된 의약품으로서 그 함량이 극량을 초과한 경우를 말한다. <개정 1994.12.23, 2008.2.29, 2010.3.15>', 8340);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14371, '②법 제3조제1항 및 제7조제1항의 규정에 의한 "효능 또는 함량의 현저한 부족"의 기준은 의약품 또는 화장품의 주된 성분의 총함량이 제조당시를 기준으로 하여 최소유효량에 미달하는 경우를 말한다.', 8340);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14372, '①법 제9조제1항의 규정에 의한 상금의 지급액은 당해 사건으로 부과된 벌금액의 100분의 20상당액으로 하되, 상금의 총액은 50만원을 초과할 수 없다.', 8341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14373, '②당해 사건이 검사의 기소유예처분을 받은 경우에는 전항의 규정에 불구하고 3만원이하의 범위안에서 그 공로, 범죄의 경중 기타의 사정을 참작하여 보건복지부장관이 정하는 금액으로 한다. <개정 1994.12.23, 2008.2.29, 2010.3.15>', 8341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14374, null, 8344);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14375, '①수사기관원 또는 감독청의 관계직원은 법 제9조의 규정에 의한 통보를 받은 때에는 지체없이 그 소속기관의 장에게 보고하여야 한다.', 8347);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14376, '②소속기관의 장은 전항의 보고를 받은 때에는 지체없이 그 통보인에게 통보증명서를 교부하여야 한다.', 8347);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14377, null, 8348);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14378, '① 이 규칙에서 사용하는 용어의 뜻은 다음과 같다. <개정 2025.5.30>', 8352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14379, '② 이 규칙에서 사용하는 용어는 보호사건에서는 아래 각 호의 구분에 따른다.', 8352);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14380, null, 8353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14381, '① 피고인, 피의자 또는 변호인, 그 밖의 소송관계인은 전자적 송달 또는 통지 등 전자소송시스템을 이용한 형사사법절차의 진행에 대한 동의(다음부터 "전자소송 동의"라고 한다)를 할 수 있다. 전자소송 동의는 전자소송시스템에 사용자등록을 하고, 동의서를 전자문서로 작성ㆍ제출하는 방식으로 하여야 한다.', 8354);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14382, '② 전자소송 동의는 당해 사건이 확정될 때까지 효력이 있다. 다만 변호인의 전자소송 동의는 당해 심급에만 효력이 있으나, 원심과 상소심의 변호인이 동일인일 때에는 상소심에도 효력이 있다.', 8354);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14383, '③ 전자소송 동의를 한 등록사용자는 재판장의 허가를 받아 전자소송 동의를 철회할 수 있다.', 8354);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14384, '④ 본안사건에 대한 전자소송 동의의 효력은 그에 부수하는 신청사건에도 미친다.', 8354);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14385, '① 전자소송시스템을 이용하려는 자는 전자소송시스템에 접속하여 다음 각 호의 회원 유형별로 전자소송포털에서 요구하는 정보를 해당란에 입력한 후 전자서명을 위한 인증서를 사용하여 사용자등록을 신청하여야 한다. 등록한 사용자 정보는 인증서의 내용과 일치하여야 한다. <개정 2025.5.30>', 8355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14386, '② 제1항제2호부터 제5호까지의 회원으로 사용자등록을 한 자는 이용권한의 범위를 정하여 소속사용자를 지정할 수 있고, 그에 따라 지정된 자는 전자소송시스템에 소속사용자로 등록할 수 있다.', 8355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14387, '③ 재판장, 수명법관, 수탁판사(다음부터 "재판장등"이라 한다)는 피고인 등의 권리 행사에 지장을 초래하지 아니하는 한, 사용자등록 또는 전자소송 동의를 하지 않은 피의자, 피고인, 피해자, 고소인, 고발인, 변호인 및 제3조제1호부터 제5호까지의 자에 대하여 사용자등록과 전자소송 동의를 할 것을 권고할 수 있다. 변호인의 선임ㆍ변경ㆍ해임ㆍ사임 또는 그 밖의 사유로 소송을 수행할 자가 변경된 때에도 같다.', 8355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14388, '① 제5조제1항에 따라 사용자등록을 한 자(다음부터 "등록사용자"라 한다)는 전자소송시스템에 접속하여 사용자등록 철회의 취지를 입력함으로써 사용자등록을 철회할 수 있다.', 8356);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14389, '② 계속 중인 사건이 있으면 그 전부에 관하여 제4조제3항에 따른 절차를 마친 때에만 제1항의 철회를 할 수 있다.', 8356);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14390, '① 다음 각 호의 어느 하나에 해당하면 법 제7조제3항제5호에 따라 등록사용자(제5조제2항이 정하는 소속사용자를 포함한다. 이하 같다)의 사용을 정지하거나 사용자등록을 말소할 수 있다.', 8357);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14391, '② 법원행정처장은 법 제7조제3항 각 호의 어느 하나에 해당하는지를 결정하기 위하여 필요하다고 인정하는 때에는 피의자, 피고인, 검사 또는 이해관계인의 신청에 따라 또는 직권으로 해당 등록사용자의 사용을 일시적으로 정지할 수 있다. 이때 법원행정처장은 등록사용자에게 적당한 방법으로 그 사실을 통지하여야 한다.', 8357);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14392, '③ 법원행정처장은 법 제7조제3항에 따라 사용자등록을 말소하기 전에 해당 등록사용자에게 미리 그 사유를 통지하고 소명할 기회를 부여하여야 한다.', 8357);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14393, '④ 등록사용자가 전자소송시스템을 마지막으로 이용한 날부터 5년이 지나면 사용자등록은 효력을 상실한다.', 8357);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14394, '① 법원에 전자문서를 제출하는 자는 이 규칙에서 달리 정하는 경우를 제외하고는 전자문서에 「전자정부법」 제2조제9호에 따른 행정전자서명 또는 「전자서명법」 제2조제2호에 따른 전자서명(서명자의 실지명의를 확인할 수 있는 것으로서 법원행정처장이 지정ㆍ공고하는 인증서를 말한다)을 하여야 한다.', 8358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14395, '② 법관 또는 법원서기관ㆍ법원사무관ㆍ법원주사ㆍ법원주사보(다음부터 "법원사무관등"이라 한다)가 재판서나 조서 등을 작성하는 때에는 「법원 행정전자서명 인증업무에 관한 규칙」 제2조제2항에 따라 설치된 ‘법원 행정전자서명 인증관리센터’에서 발급받은 행정전자서명 인증서에 의한 사법전자서명을 하여야 한다.', 8358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14396, '③ 전자소송시스템을 이용하여 전자문서를 제출할 필요성이 있다고 인정되고 그 신원이 확인되어 재판장등의 허가를 받은 자는 제1항이 규정한 인증서에 의하지 아니한 전자서명을 하거나 전자서명을 하지 아니하고 사용자등록 또는 전자문서 제출을 할 수 있다.', 8358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14397, '④ 제1항과 제3항에 따라 전자문서를 제출하는 경우에는 법 제3조 각 호의 법률에 따른 절차에서 인감의 날인 또는 인감증명서 첨부를 하지 아니할 수 있다.', 8358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14398, '⑤ 이 규칙에서 달리 정한 경우 이외에는 재판장등의 허가가 있으면 형사사법절차에 적용되거나 준용되는 법령에서 정한 서명, 서명날인 또는 기명날인은 제1항이 규정한 인증서에 의하지 아니한 전자서명으로 대신할 수 있다.', 8358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14399, '⑥ 제1항의 공고는 전자소송포털에 하여야 한다. <개정 2025.5.30>', 8358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14400, '① 법 제10조제1항 단서에 따라 다음 각 호의 어느 하나에 해당하는 서류는 전자문서로 작성하지 아니할 수 있다.', 8359);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14401, '② 제1항에 따라 작성된 재판서, 조서 등은 이후 전자소송시스템에 등재되기 전에는 이를 원본으로 본다.', 8359);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14402, '① 형사사법업무 처리기관 또는 그 소속 공무원은 법원에 제출할 서류를 전자소송시스템을 통하여 전자문서(전자화문서를 포함한다)로 제출하여야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그러하지 아니하다.', 8360);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14403, '② 제1항제4호에 해당하는 서류가 전자문서로 작성되어 있을 때에는 이를 제출한 형사사법업무 처리기관 또는 그 소속 공무원은 그 원본을 해당 형사사법절차가 확정될 때까지 보관하여야 한다.', 8360);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14404, '③ 형사사법업무 처리기관이 법 제11조에 따라 변환ㆍ등재한 전자화문서를 법원에 제출한 경우에는 그 전자화대상문서를 해당 형사사법절차가 확정될 때까지 보관하여야 한다.', 8360);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14405, '① 제4조제1항에 따른 전자소송 동의를 한 등록사용자는 법원에 제출할 서류를 전자소송시스템을 통하여 전자문서로 제출할 수 있다. 이 경우 등록사용자는 전자소송포털에서 요구하는 사항을 빈칸 채우기 방식으로 입력한 후, 나머지 사항을 해당란에 직접 입력하거나 미리 작성ㆍ변환한 전자문서를 등재하는 방식으로 전자문서를 제출할 수 있다. <개정 2025.5.30>', 8361);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14406, '② 공동의 이해관계를 가진 여러 등록사용자는 다음 각 호의 어느 하나의 방법에 따라 공동 명의로 하나의 전자문서를 제출할 수 있다.', 8361);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14407, '③ 제5조제1항제4호의 법무사회원은 다음 각 호 가운데 어느 하나의 방법에 따라 전자문서를 작성ㆍ제출할 수 있다.', 8361);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14408, '④ 「형사소송규칙」 제126조의 규정에 따른 대리권을 수여한 사실의 증명은 전자문서로 할 수 있다.', 8361);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14409, '⑤ 「공증인법」 제5장의2(전자문서등에 대한 인증)의 각 규정에 따라 인증된 전자문서를 제출할 때에는 그 취지와 인증의 증명에 관한 사항을 밝혀야 한다.', 8361);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14410, '⑥ 제5조제1항제2호의 법인회원으로부터 제5조제2항에 따라 전자문서 제출권한을 지정받은 소속사용자는 다음 각 호 가운데 어느 하나의 방법으로 전자문서를 제출할 수 있다.', 8361);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14411, '① 법원행정처장은 전자소송시스템을 이용하여 제출할 수 있는 전자문서의 파일 형식, 구성 방식 그 밖의 사항을 지정하여 전자소송포털에 공고하여야 한다. <개정 2025.5.30>', 8362);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14412, '② 제1항에 따라 지정된 파일 형식을 사용하지 아니한 전자문서는 부득이한 사정을 소명하지 아니하는 한 전자소송시스템을 이용하여 제출할 수 없다.', 8362);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14413, '③ 전자소송시스템을 이용하여 전자문서를 제출하는 경우 다음 각 호의 사항을 준수하여야 한다.', 8362);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14414, '④ 법원에 제출하고자 하는 전자문서에 다음 각 호의 어느 하나에 해당하는 내용이 포함되어 있는 경우, 「형사소송법」 제35조제3항에 따른 개인정보 보호조치 또는 같은 법 제59조의3제1항에 따른 열람이나 복사 제한의 필요성 및 그 범위에 관한 의견을 제출할 수 있다. 이 경우 법원행정처장이 정하여 공고하는 방법에 따라 그 전자문서 중 다음 각 호의 사유가 있는 부분을 특정하여야 한다.', 8362);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14415, '⑤ 재판장은 제4항 각 호의 어느 하나에 해당하는 사유가 있는 경우, 전자문서를 제출하였거나 제출하려고 하는 자에게 그 전자문서 중 제4항 각 호의 어느 하나에 해당하는 사유가 있는 부분을 특정할 것을 명할 수 있다.', 8362);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14416, '⑥ 제4항 후문, 제5항에 따라 특정된 정보는 당해 전자문서와 별도로 관리할 수 있다.', 8362);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14417, '① 음성ㆍ영상 등 멀티미디어 방식의 자료(다음부터 "멀티미디어 자료"라 한다)를 전자소송시스템을 이용하여 제출하는 경우, 전자소송포털에서 요구하는 방식에 따라 제출하되, 해당 자료의 주요 내용, 제출 취지 및 용량을 밝혀야 한다. <개정 2025.5.30>', 8363);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14418, '② 법원은 멀티미디어 자료를 송부 또는 송달하기 위하여 필요한 경우, 이를 제출한 자에게 해당 자료를 컴퓨터용디스크, 그 밖에 이와 비슷한 정보저장매체(다음부터 "정보저장매체등"이라 한다)에 담아 제출하거나 그 출력물을 제출하게 할 수 있다.', 8363);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14419, '① 전자소송시스템 또는 정보통신망에 장애가 있는 경우, 법원에 제출할 서류를 정보저장매체등에 전자문서의 형태로 담아 제출하거나 전자문서가 아닌 형태로 제출할 수 있다.', 8364);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14420, '② 제1항에 따라 전자문서를 정보저장매체등에 담아 제출할 때에는 다음 각 호의 사항을 밝혀야 한다.', 8364);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14421, '③ 전자서명 방식으로 작성되지 아니한 전자문서를 제1항에 따라 제출하는 경우에는 작성자의 의사에 따라 작성한 것이라는 취지를 추가로 밝혀야 한다.', 8364);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14422, '④ 재판장등은 제1항에 따라 서류를 제출한 자에게 전자소송시스템 또는 정보통신망의 장애가 해소된 뒤에 해당 서류를 전자적 방법으로 제출할 것을 명할 수 있다. 이 명령에 따른 경우에는 최초로 제출한 때에 제출한 것으로 본다.', 8364);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14423, '① 법원사무관등은 전자화대상문서를 전자적인 형태로 변환하고 사법전자서명을 하여 전자소송시스템에 등재하여야 한다. 전자소송시스템에 장애가 있는 경우에는 그 사유가 해소된 후 상당한 기간 내에 같은 방법에 따라 전자소송시스템에 등재하여야 한다.', 8365);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14424, '② 제1항에 따라 전자적인 형태로 변환ㆍ등재한 전자화대상문서는 제출한 자가 반환을 요청하지 아니하는 한 해당 형사사법절차가 확정될 때까지 보관하고, 해당 형사사법절차 확정 후 제출한 자의 의사에 따라 반환 또는 폐기한다.', 8365);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14425, '③ 법 제11조제1항 단서의 "전자화대상문서를 전자적인 형태로 변환하는 것이 현저히 곤란하거나 적합하지 아니한 경우"란 전자화대상문서가 다음 각 호의 어느 하나에 해당하는 경우를 말한다. 이 경우 법원사무관등은 전자문서로 변환하지 아니한 서류 또는 도면ㆍ사진ㆍ음성ㆍ영상자료 등(다음부터 "서류등"이라 한다)을 별도의 기록으로 관리ㆍ보존하고 전자소송시스템에 그 사실을 입력하여야 한다.', 8365);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14426, '④ 법원사무관등은 전자문서를 출력한 서면을 제출한 자 또는 제출하려는 자에게 해당 전자문서를 정보저장매체등에 담아 제출하게 하거나 지정된 전자우편주소로 전송 또는 법원이 관리ㆍ운영하는 전산정보처리시스템을 통하여 전송하게 한 후 그 전자문서에 사법전자서명을 하고 전자소송시스템에 등재할 수 있다. 이러한 방식으로 제출한 전자문서는 이를 출력하여 제출한 서면을 갈음하는 것으로 본다.', 8365);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14427, '⑤ 제14조제2항, 제3항의 규정은 제4항에 따라 전자문서를 정보저장매체등에 담아 제출하는 경우에 준용한다.', 8365);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14428, '⑥ 제4항에 따라 제출된 출력서면은 그 제출자에게 반환하거나 폐기한다.', 8365);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14429, '⑦ 제1항에 따라 전자화대상문서를 전자적인 형태로 변환하는 경우에 다음 각 호의 속성정보를 생성하여 전자소송시스템에서 관리하여야 한다.', 8365);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14430, '① 법원사무관등은 전자문서가 접수된 때에는 즉시 전자우편 및 문자전송서비스(휴대전화 문자메시지와 법원행정처장이 정하는 인터넷 사회관계망 서비스를 포함한다. 이하 같다)를 이용하여, 제출자에게 접수사실을 전자적으로 통지하여야 한다.', 8366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14431, '② 전자화문서는 그 전자화대상문서가 제출되었을 때 접수된 것으로 본다.', 8366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14432, '③ 증거로 제출하고자 하는 취지를 법원행정처장이 정하는 방법에 따라 명시하여 제출한 전자문서는 그렇지 않은 전자문서와 별도로 관리하여야 한다.', 8366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14433, '④ 전자문서가 접수되거나 전자화문서가 등재된 때에는 다음 각 호의 사항이 포함된 접수정보를 생성하여 전자소송시스템에서 관리한다.', 8366);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14434, '① 전자문서를 제출한 등록사용자는 제28조에 따라 전자소송포털에서 전자기록을 열람하는 방법으로 제출한 전자문서와 접수된 전자문서의 동일성을 확인할 수 있다. <개정 2025.5.30>', 8367);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14435, '② 제1항에 따라 직접 전자문서의 동일성을 확인할 수 없는 등록사용자의 요구가 있는 경우, 법원사무관등은 컴퓨터 등 정보처리능력을 갖춘 장치의 화면을 이용하여 전자문서를 열람하게 하는 방법으로 동일성을 확인할 수 있도록 하여야 한다. 법 12조제3항에 따라 전자화대상문서를 제출한 자에게 전자화대상문서를 반환하기 위하여 전자화문서와 전자화대상문서의 동일성을 확인하는 경우에도 같다.', 8367);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14436, '③ 전자문서를 제출한 등록사용자가 전자문서 제출일부터 1주일이 경과하거나 제출 후 최초로 진행되는 기일이 끝날 때까지 제1항의 동일성 확인을 요구하지 아니한 경우에는 제출하고자 한 문서와 전자소송시스템에 등재된 전자문서 사이의 동일성에 관하여 이의를 제기할 권리를 잃는다.', 8367);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14437, '④ 제출한 전자문서와 전자소송시스템에 등재된 전자문서의 동일성을 확인한 등록사용자는 그 결과에 따라 해당 전자문서의 수정ㆍ삭제를 요구할 수 있다.', 8367);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14438, '⑤ 전자소송시스템에 등재된 전자화문서와 전자화대상문서의 동일성에 이의가 있는 자는 해당 전자화문서를 삭제하고 전자화대상문서를 다시 제15조에 따라 전자적인 형태로 변환하여 전자소송시스템에 등재하여 줄 것을 요구할 수 있다.', 8367);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14439, '① 재판장등은 제출된 전자문서의 판독이 곤란하거나 그 밖에 원본을 확인할 필요가 있을 때에는 이를 제출한 자에게 상당한 기간을 정하여 판독이 가능한 전자문서를 다시 제출하거나 원본을 제출할 것을 명할 수 있다.', 8368);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14440, '② 제1항의 명령에 따른 경우 최초에 제출한 때에 제출한 것으로 본다.', 8368);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14441, '③ 등록사용자가 전자소송시스템을 이용하여 전자문서를 제출한 후에는 전자소송시스템에서 이를 삭제하거나 수정된 내용으로 다시 등재할 수 없다. 이때 등록사용자는 법원사무관등에게 해당 전자문서의 삭제나 등재사항의 수정을 요청할 수 있다.', 8368);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14442, '① 법원사무관등은 전자문서로 작성한 조서에 잘못이 있는 때에는 전자소송시스템을 이용하여 다음 각 호의 예에 따라 바로잡을 수 있다.', 8369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14443, '② 제1항의 폐기 또는 정정의 절차와 방법은 법원행정처장이 정한다.', 8369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14444, '③ 전자문서로 작성한 재판서는 제1항에 따라 폐기할 수 있다.', 8369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14445, '④ 법원은 제1항, 제3항의 폐기 또는 정정에 대하여 당사자의 이의가 있는 때에는 폐기 또는 정정 전의 조서 또는 재판서를 확인할 수 있도록 하여야 한다.', 8369);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14446, '① 법원은 제출자의 의견을 들어 불필요한 전자문서를 돌려주거나 폐기할 수 있다.', 8370);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14447, '② 증거의 성격을 가지는 전자문서가 제12조제3항제2호에서 정한 방식에 따르지 않고 제출된 경우, 법원은 해당 증거를 돌려주거나 폐기할 수 있다.', 8370);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14448, '① 법원사무관등은 전자문서의 형태, 제출방식, 전자소송시스템 이용 방식 등에 관하여 필요한 사항을 지적하고 보정을 권고할 수 있다.', 8371);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14449, '② 법원사무관등은 전자적으로 제출된 소송서류가 전자소송포털에서 요구하는 방식과 달리 등재되거나 소송서류에 관한 정보 입력이 잘못된 때에는 재판장등의 허가를 얻어 이를 정정ㆍ변경할 수 있다. <개정 2025.5.30>', 8371);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14450, '① 법 제13조제2항 단서에 따라 전자문서를 전자적 방법으로 송부받을 수 있는 기관은 법원행정처장이 지정하여 전자소송포털에 공고하는 기관으로 한다. <개정 2025.5.30>', 8372);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14451, '② 법 제13조제2항 본문에 따라 전자문서를 출력할 때에는 전자기록에 이송 또는 송치에 관한 결정문 등을 등재하고, 이를 포함하여 송부할 서면을 출력한다. 이 경우 이 규칙 제27조제3항을 준용한다.', 8372);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14452, '③ 심급 사이 또는 이송결정에 따른 전자기록 송부는 전자적인 방법으로 한다. 다만, 군사법원으로 이송하는 경우 전자소송시스템을 통하여 출력한 기록을 송부하는 방법으로 할 수 있다. 이 때 제15조제3항에 따라 별도로 보관하는 기록 또는 문서는 그 자체를 송부하는 방법으로 한다.', 8372);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14453, '① 법 제14조제1항제3호에 따라 전자적 송달 또는 통지를 받을 자는 다음 각 호와 같다.', 8373);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14454, '② 제1항에도 불구하고 전자적 송달 또는 통지를 받을 등록사용자가 교도소ㆍ구치소 또는 국가경찰관서의 유치장에 체포ㆍ구속 또는 유치(留置)된 사람인 경우, 그에 대한 송달 또는 통지는 「형사소송법」 제65조, 「민사소송법」 제182조, 법 제14조제1항제1호 및 제2호에 따라 그 교도소ㆍ구치소 또는 국가경찰관서의 장에게 전산정보처리시스템을 통하여 전자적으로 하여야 한다.', 8373);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14455, '③ 법원사무관등은 전자문서로 작성된 재판서 또는 조서의 송달을 신청한 등록사용자에게 전자소송시스템을 이용하여 전자적인 방법으로 송달할 수 있다.', 8373);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14456, '④ 제1항제2호의 신고가 있는 경우에 법 제14조제1항의 송달 또는 통지는 그 송달영수인에게 하여야 한다.', 8373);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14457, '① 법 제14조제1항 및 제2항에 따른 전자문서의 전산등재 및 그 사실의 통지는 다음 각 호의 방식에 따른다.', 8374);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14458, '② 법 제14조제1항에 따른 송달 또는 통지는 제1항 각 호의 방식으로 송달 또는 통지를 받을 자가 등재된 전자문서를 확인한 때에 효력이 있다. 법 제14조제1항제1호 및 제2호에 따른 송달 또는 통지의 경우, 형사사법업무 처리기관의 전산정보처리시스템에 송달ㆍ통지의 대상인 전자문서가 전자적으로 기록되고 그 기록 정보가 시스템과 연계된 전자소송시스템을 통하여 전자적으로 수신된 때 이를 확인한 것으로 본다.', 8374);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14459, '③ 등록사용자가 책임질 수 없는 사유로 전자소송시스템에 등재된 전자문서를 법 제14조제4항의 기간 안에 확인하지 못한 경우로서 다음 각 호의 어느 하나에 해당하는 경우에는 법 제14조제2항에 따라 피고인에게 전자문서의 등재사실을 전자적으로 통지한 날부터 14일이 지나더라도 송달 또는 통지된 것으로 보지 아니한다.', 8374);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14460, '④ 전자소송시스템을 이용하여 송달한 전자문서 정본에 의하여 출력한 서면은 정본의 효력이 있다. 이 경우 전자소송시스템 장애 등 책임질 수 없는 사유로 등재된 전자문서 정본의 출력이 정상적으로 끝나지 아니하였으면, 그 사유를 소명하여 재발급을 신청할 수 있다.', 8374);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14461, '① 송달받을 자가 전자소송시스템 또는 정보통신망의 장애로 인하여 전자문서를 확인할 수 없는 기간이 1일당 1시간을 초과하는 경우에는 해당 일을 법 제14조제4항 본문의 기간에 산입하지 아니한다. 그 기간의 마지막 날 오전 9시 이후에 전자소송시스템 장애로 인하여 전자문서를 확인할 수 없게 된 때에도 1일을 그 기간에 산입하지 아니한다.', 8376);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14462, '② 전자소송시스템의 유지ㆍ보수를 위하여 그 사용을 일시 중단한 경우로서 법원행정처장이 사전에 공지한 경우에는 제1항을 적용하지 아니한다.', 8376);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14463, '① 법 제15조제1항제3호의 사유는 다음 각 호 가운데 어느 하나를 말한다.', 8377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14464, '② 법원사무관등은 법 제15조제1항에 따라 출력서면을 송달하는 경우 다음 각 호의 어느 하나에 해당하면 그 제출자로 하여금 전자문서의 출력서면을 제출하게 할 수 있다.', 8377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14465, '③ 법 제15조제1항에 따라 전자문서를 출력할 경우에는 다음 각 호의 사항이 포함된 출력정보를 생성하여 전자소송시스템에서 관리한다. 출력문서에는 출력하는 전자문서의 고유번호 등이 표시되도록 하고, 「법원사무관리규칙」 제12조제3항의 규정에 따른 발급번호기재방식으로 간인에 갈음한다.', 8377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14466, '④ 법원사무관등은 법 제15조제1항에 따라 전자문서를 출력한 서면을 송달하는 경우 「우편법」 제15조제3항, 「우편법 시행규칙」 제25조제1항제12호에서 정한 전자우편을 이용하여 할 수 있다.', 8377);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14467, '① 등록사용자로서 전자소송 동의를 한 자가 법 제16조제1항 및 그에 열거된 「형사소송법」 각 해당 규정에 따라 전자기록을 열람ㆍ등사 또는 복사하는 경우에는, 전자소송시스템에 접속한 후 전자소송포털에서 그 내용을 확인하고 이를 서면으로 출력하거나 해당 사항을 자신의 정보저장매체등에 내려받는 방식으로 한다. <개정 2025.5.30>', 8378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14468, '② 법 제16조제1항 및 그에 열거된 「형사소송법」 각 해당 규정에 따라 전자기록을 열람하고자 하는 자가 법원에 출석하여 당해 사건의 전자기록을 열람ㆍ등사 또는 복사를 신청한 때에는, 법원사무관등은 법원에 비치된 컴퓨터 단말기를 이용하여 해당 내용을 확인 또는 서면으로 출력하게 하거나 해당 사항을 정보저장매체등에 내려받게 할 수 있다.', 8378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14469, '③ 제1항 및 제2항에 따라 전자기록을 내려받거나 출력하는 경우에는, 다음 각 호의 사항이 포함된 정보를 생성하여 전자소송시스템에서 관리하고, 해당 전자문서에 다음 각 호의 사항이 표시되도록 한다.', 8378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14470, '④ 법원은 「형사소송법」 제35조제3항에 따른 개인정보 보호조치 필요성, 이 규칙 제12조제4항에 따라 전자문서를 제출한 자의 의견 등을 고려하여 열람권자별로 열람ㆍ등사ㆍ복사의 범위를 달리 정할 수 있고, 그에 따라 열람ㆍ등사ㆍ복사 대상 기록을 별도로 관리할 수 있다.', 8378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14471, '① 전자기록의 열람, 출력 또는 복제를 신청할 경우 납부하여야 할 수수료의 금액은 별표 2와 같다.', 8379);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14472, '② 형사사법절차가 법원에 계속되는 동안에 제28조에 따라 전자기록을 열람, 출력 또는 복제하는 경우 다음 각 호의 어느 하나에 해당하면 제1항의 수수료를 납부하지 아니한다.', 8379);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14473, '③ 전자기록의 열람ㆍ출력 또는 복제에 관하여 이 규칙에 특별한 규정이 없으면 「재판기록 열람ㆍ복사 규칙」을 준용한다.', 8379);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14474, '① 공소장, 공판준비를 위한 서면, 항소이유서와 답변서, 그 밖에 이에 준하는 서류가 전자문서로 등재되어 있는 경우 그에 따른 진술 또는 변론은 컴퓨터 등 정보처리능력을 갖춘 장치에 의하여 전자문서를 현출한 화면에서 필요한 사항을 지적하면서 할 수 있다.', 8380);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14475, '② 제13조에 따라 제출된 멀티미디어 방식의 자료에 따른 변론은 제1항의 방식과 함께 컴퓨터 등 정보처리능력을 갖춘 장치에 의하여 재생되는 음성이나 영상 중 필요한 부분을 청취 또는 시청하는 방법으로 한다.', 8380);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14476, '③ 제1항 및 제2항은 공판준비기일에서 검사, 피고인 또는 변호인이 쟁점 및 증거의 정리를 위하여 하는 행위에 준용한다.', 8380);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14477, '① 전자문서에 대한 증거신청은 다음 각 호의 어느 하나에 해당하는 방법에 의하여 하되, 증거임을 명시하여 하여야 한다.', 8381);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14478, '② 다음 각 호의 어느 하나에 해당하면 증거신청을 하는 전자문서를 정보저장매체등에 담아 제출할 수 있다. 이 경우 제14조제3항을 준용한다.', 8381);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14479, '③ 전자문서에 대한 증거신청을 하는 때에는 전자문서의 내용에 따라 다음 각 호의 사항을 밝혀야 한다. 다만, 전자문서의 내용에 비추어 명백한 경우에는 그러하지 아니하다.', 8381);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14480, '④ 재판장등은 필요한 경우 전자문서를 증거로 신청한 자에게 다음 각 호의 자료를 제출할 것을 명할 수 있다. 이 명령을 이행하지 아니하는 때에는 해당 전자문서를 증거로 채택하지 아니할 수 있다.', 8381);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14481, '⑤ 재판장등은 공판절차의 원활한 진행을 위하여 필요하다고 인정하는 경우 공판기일ㆍ공판준비기일 전에 검사, 피고인 또는 변호인에게 증거로 신청할 서류등의 목록을 전자소송시스템에 등재할 것을 명하고, 상대방에게는 그 증거신청에 대한 의견을 전자소송시스템에 입력할 것을 명할 수 있다.', 8381);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14482, '① 문자등 정보에 해당하는 전자문서에 대한 증거조사는 법 제18조제1항제1호의 방법 이외에 필요한 경우 직권 또는 당사자의 신청에 따라 검증 또는 감정의 방법으로 할 수 있다.', 8382);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14483, '② 전자문서로 변환하여 제출된 증거에 대하여 원본의 존재나 내용에 대하여 이의가 있는 때에는 원본을 열람하는 방법에 의한다.', 8382);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14484, '③ 컴퓨터 등 정보처리능력을 갖춘 장치를 이용하여 증거조사를 하기 곤란한 사유가 있을 때에는 그 출력문서로 증거조사를 할 수 있다. 이때에는 작성자, 작성일, 출력한 자와 출력한 일시를 밝혀야 한다.', 8382);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14485, '① 음성ㆍ영상등 정보에 해당하는 전자문서에 대한 증거조사는 법 제18조제1항제2호의 방법 이외에 필요한 경우 직권 또는 당사자의 신청에 따라 다른 방법으로 검증하거나 감정의 방법으로 할 수 있다.', 8383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14486, '② 제1항의 전자문서에 대한 증거조사를 신청한 당사자는 법원이 명하거나 상대방이 요구한 경우에는 녹취서, 그 밖에 그 내용을 설명하는 문서를 전자문서로 제출하여야 한다.', 8383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14487, '③ 법원사무관등이 증거조사 결과에 따라 조서를 작성하는 때에는 재판장등의 허가를 받아 제2항에 따라 제출된 전자문서 가운데 필요한 부분을 그 조서에 인용할 수 있다.', 8383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14488, '① 검사, 변호인 또는 피고인은 재판장등의 허가를 받아 멀티미디어 자료 등 전자문서를 이용하여 증인, 감정인, 번역인, 통역인 등을 신문할 수 있다. 검사, 변호인이 피고인을 신문하는 경우에도 같다.', 8384);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14489, '② 제1항의 규정은 「형사소송법」 제171조제4항 및 같은 법 제179조의2제2항에 따른 설명에 준용한다.', 8384);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14490, '③ 제1항 및 제2항의 경우 이 규칙 제33조제3항, 「형사소송규칙」 제82조제2항을 준용한다.', 8384);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14491, '① 제3조제8호부터 제11호까지에 해당하는 기관 등이 그 촉탁사항이나 송부대상인 문서를 전자데이터 또는 전자문서로 가지고 있는 경우에는 전자소송시스템을 이용하여 이를 전송하여야 한다.', 8385);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14492, '② 법원은 제1항의 촉탁사항이나 송부대상인 문서가 전자데이터 또는 전자문서가 아닌 경우 이를 전자문서로 변환하여 전송하여 줄 것을 요청할 수 있다.', 8385);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14493, '③ 법원은 제1항의 각종 촉탁 등을 전자적 송달 또는 통지의 방법으로 할 수 있다.', 8385);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14494, '① 전자문서로 발부된 다음 각 호의 영장, 감정유치장, 허가장, 허가서 및 요청서(다음부터 "영장등"이라 한다)는 컴퓨터, 이동통신 단말장치, 그 밖에 이에 준하는 정보처리능력을 갖춘 장치에 의하여 당해 전자문서를 현출한 화면을 이용하여 제시하는 방법으로 집행한다.', 8386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14495, '② 전자문서로 발부된 제1항제8호부터 제13호까지에 해당하는 영장등이 전자적 형태로 송신 또는 수신될 수 있는 정보를 대상으로 하는 경우에는 다음 각 호의 어느 하나에 해당하는 자에게 영장등을 전송하여 집행할 수 있다. 이때 전송은 그 집행을 받을 자에게 지정된 인터넷주소를 전자우편이나 문자전송서비스를 이용하여 보내고, 그 인터넷주소에 접속하여 전산정보처리시스템에 등재된 영장등을 시스템 내에서 확인하도록 하는 방법으로 한다.', 8386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14496, '③ 제2항 후문에도 불구하고 다음 각 호의 영장등은 형사사법업무처리기관이 암호화 조치를 하여 전산정보처리시스템을 이용하여 전송하고 이를 전용 프로그램 내에서 제16조제4항제3호의 정보가 동일한 원본을 열람하게 하는 방법으로 집행할 수 있다. 전용 프로그램에는 원본 형태의 출력을 방지하고 집행 완료 이후의 열람을 제한하는 등 영장등이 법관이 발부한 취지와 달리 전용되지 아니하도록 하는 기능이 포함되어야 한다.', 8386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14497, '④ 영장등을 전자문서로 여러 통 발부하는 경우, 발부한 영장등의 수와 그 사유에 관한 정보를 각 전자문서에 포함하여야 한다.', 8386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14498, '⑤ 전자문서로 발부된 영장등은 이를 집행하는 때에 당해 영장등이 법관에 의하여 진정하게 발부되어 유효하게 집행할 수 있는 상태에 있는 것이라는 점을 전자소송시스템에서 생성한 바코드 등 컴퓨터가 인식할 수 있도록 표시한 기호의 형태로 확인ㆍ검증할 수 있어야 한다. 제3항의 방법으로 영장등을 집행하는 경우, 그 상대방에게 당해 영장등의 유효성을 전자적으로 확인ㆍ검증할 수 있음을 고지하고 이를 확인ㆍ검증할 수 있는 기회를 주어야 한다.', 8386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14499, '⑥ 형사사법업무 처리기관은 영장등을 집행할 때마다 전자문서의 제시 또는 전송 등 전자적 집행에 관한 정보, 법 제17조제2항에 따른 출력에 관한 정보를 전산정보처리시스템에 입력하여 법관이 발부한 취지와 다르게 영장등이 동시에 여러 장소에서 집행되지 않도록 하여야 한다.', 8386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14500, '⑦ 다음 각 호의 정보는 전자문서로 발부되는 영장등과 별도의 전자문서로 작성할 수 있다.', 8386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14501, '① 법 제17조제2항에 따라 전자문서로 발부된 영장등을 출력한 서면으로 집행하여야 하는 경우, 그 출력은 전자소송시스템과 연계하여 1회에 한하여 할 수 있다. 다만 법관이 당해 영장등을 전자문서로 여러 통 발부한 경우에는 출력횟수도 그에 따른다.', 8387);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14502, '② 제1항에 따라 전자문서로 발부된 영장등을 출력한 이후에는 제36조제1항, 제2항 및 제3항에 따른 전자문서의 제시나 전송의 방법으로 영장등을 집행할 수 없다.', 8387);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14503, '③ 제1항에 따라 전자문서로 발부된 영장등을 출력한 서면은 해당 형사사법절차가 확정될 때까지 보관하되, 영장등을 법원에 제출하거나 반환하여야 하는 경우에는 출력한 서면을 전자화하여 원래의 전자문서와 함께 제출하거나 반환한다.', 8387);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14504, '④ 제1항에 따른 영장등의 출력에 관하여는 제27조제3항, 제36조제4항, 제36조제6항을 준용한다.', 8387);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14505, '⑤ 전자소송시스템 또는 정보통신망의 장애 등 책임질 수 없는 사유로 영장등이 정상적으로 출력되지 아니한 경우에는 그 사유를 소명하여 재발급을 신청할 수 있다.', 8387);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14506, '① 전자문서로 발부된 영장등을 집행하는 경우의 「형사소송법」 제85조제1항 및 제4항(같은 법 제200조의6, 제209조에 의하여 준용되는 경우를 포함한다), 같은 법 제118조(같은 법 제219조에 의하여 준용되는 경우를 포함한다)에 따른 영장등의 사본 교부는 전자문서의 사본을 전송하거나 전자문서의 사본을 출력한 서면을 교부하는 방식으로 할 수 있다.', 8388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14507, '② 제1항의 전송은 제36조제2항에 의한 방법 외에 당해 영장등의 사본임을 표시한 교부용 전자파일을 전자우편 및 문자전송서비스를 이용하여 보내는 방법으로도 할 수 있다.', 8388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14508, '③ 「형사소송법」 제128조, 제129조(같은 법 제219조에 의하여 준용되는 경우를 포함한다)에 따른 압수목록, 증명서의 교부에 관하여는 제1항, 제2항을 준용한다.', 8388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14509, '① 소년보호사건, 가정보호사건, 아동보호사건, 성매매관련보호사건에서 판사는 재판서 또는 재판을 기재한 조서가 전자문서로 작성된 경우에는 「소년심판규칙」 제21조, 제37조, 「아동보호심판규칙」 제32조, 제52조,  「가정보호심판규칙」 제31조, 제51조의 규정에도 불구하고 전자문서로 재판의 집행을 지휘한다.', 8389);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14510, '② 제1항에도 불구하고 전자문서로 재판의 집행을 지휘하기 곤란한 경우에는 전자문서로 작성된 재판서 또는 재판을 기재한 조서를 전산정보처리시스템을 통하여 출력한 서면으로 재판의 집행을 지휘한다.', 8389);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14511, '③ 제2항에 따라 전자문서를 출력하는 절차와 방법은 제37조에 따른다.', 8389);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14512, '① 전자소송시스템에 기록된 전자문서는 전자파일로 보존하되, 위조ㆍ변조ㆍ훼손ㆍ유출 등을 방지하기 위한 보안조치를 하여야 한다.', 8390);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14513, '② 사건기록이 전자기록으로 관리되는 사건(다음부터 "전자기록사건"이라 한다)의 경우 법원행정처장은 「법원재판사무 처리규칙」 제4장 각 조의 사항에 관하여 전자기록의 특성을 고려하여 달리 정할 수 있다.', 8390);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14514, '③ 전자기록사건의 경우 법관 또는 법원사무관등은 현장검증이나 서증조사 등 법원 밖에서의 증거조사 또는 재택근무 그 밖에 업무상 필요하다고 인정되는 때에는 법원청사 이외의 곳에서 전자기록을 이용할 수 있다. 이때 전자기록이 정당한 이유 없이 공개되지 않도록 조치하여야 한다.', 8390);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14515, '① 법원행정처장은 전자소송시스템의 점검을 위하여 필요한 시간 동안 전자소송시스템의 이용시간을 일시 제한할 수 있다.', 8391);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14516, '② 법원행정처장은 전자소송시스템에 장애가 발생하거나 그 밖에 부득이한 사정이 있을 때에는 장애발생사실 및 그 복구사실을 법원 홈페이지 및 전자소송포털에 게시하여야 한다. <개정 2025.5.30>', 8391);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14517, '③ 법원행정처장은 전자기록사건에 관하여 담당 재판장등이 전자소송시스템의 장애 또는 그 밖의 사유로 기술적 지원을 요청한 경우 필요한 범위 내에서 사건 정보 또는 기록 등을 열람하거나 그 밖의 조치를 취할 수 있다.', 8391);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14518, '① 법원행정처장은 다음 각 호의 어느 하나에 해당하는 사유가 있는 경우 법 제20조제2항에 따라 전자기록을 영구 보관하거나 폐기 시기를 늦출 수 있다.', 8392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14519, '② 법과 이 규칙에서 정한 것 이외에 전자기록의 보존, 폐기에 관하여는 「법원재판사무 처리규칙」 제29조에 의한다.', 8392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14520, null, 8394);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14521, '① 국방부장관은 군수형자에 대한 형의 집행에 관한 사무를 관장하기 위하여 군교도소(이하 "교도소"라 한다)를 설치ㆍ운영하고, 필요하다고 인정하는 경우 교도소에 지소를 설치ㆍ운영할 수 있다. <개정 2014.5.20>', 8396);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14522, '② 국방부장관은 군미결수용자를 수용하기 위하여 교도소와 대통령령으로 정하는 부대에 군미결수용실(이하 "미결수용실"이라 한다)을 설치ㆍ운영할 수 있다. <개정 2014.5.20>', 8396);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14523, '③ 삭제 <2014.5.20>', 8396);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14524, '④ 삭제 <2014.5.20>', 8396);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14525, '① 군판사와 군검사는 직무상 필요하면 군교정시설을 시찰할 수 있다. <개정 2016.1.6>', 8400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14526, '② 군판사와 군검사 외의 사람은 군교정시설을 참관하려면 학술연구 등 정당한 사유를 구체적으로 밝혀 소장의 허가를 받아야 한다. <개정 2016.1.6>', 8400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14527, '③ 제1항 및 제2항에 따른 시찰 및 참관에 관하여 필요한 사항은 대통령령으로 정한다.', 8400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14528, null, 8402);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14529, '① 다음 각 호의 어느 하나에 해당하면 교도소에 군미결수용자를 수용할 수 있다.', 8403);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14530, '② 미결수용실이 설치된 부대의 장은 특별한 사정이 있을 때에는 교도소로 이송(移送)하여야 할 군수형자를 3개월을 초과하지 아니하는 범위에서 계속하여 수용할 수 있다.', 8403);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14531, '① 남성과 여성은 분리하여 수용한다.', 8404);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14532, '② 군수형자와 군미결수용자를 같은 군교정시설에 수용할 때에는 서로 분리하여 수용한다.', 8404);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14533, '① 군수용자는 독거수용한다. 다만, 다음 각 호의 어느 하나에 해당하면 혼거(混居)수용할 수 있다.', 8405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14534, '② 제1항에서 규정한 사항 외에 독거수용의 구분 등 독거수용에 관하여 필요한 사항은 대통령령으로 정한다.', 8405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14535, '① 혼거수용하는 경우에는 다음 각 호의 구분에 따라 거실(居室)을 구분하여 수용한다. 다만, 군수용자의 죄질ㆍ성격ㆍ범죄전력ㆍ나이ㆍ경력 및 수용생활 태도, 그 밖에 군수용자의 개인적 특성을 고려하여 거실을 별도로 구분하여 수용할 수 있다. <개정 2017.3.21>', 8406);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14536, '② 제1항에서 규정한 사항 외에 혼거수용 인원의 기준, 혼거수용의 제한 등에 관하여 필요한 사항은 대통령령으로 정한다.', 8406);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14537, '① 소장은 군수용자로서 군교정시설에 처음으로 수용되는 사람(이하 "신입자"라 한다)에 대하여는 집행지휘서, 재판서, 그 밖에 수용에 필요한 서류를 조사한 후 수용한다.', 8407);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14538, '② 소장은 대통령령으로 정하는 바에 따라 신입자에게 군의관이 실시하는 건강진단을 받게 하여야 한다.', 8407);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14539, '① 소장은 다른 사람의 건강에 위해(危害)를 끼칠 우려가 있는 감염병(「감염병의 예방 및 관리에 관한 법률」 제2조제1호에 따른 감염병을 말한다. 이하 같다)에 걸린 사람이 있으면, 지체 없이 수용지휘기관과 관할 보건소장에게 통보하고 국방부장관에게 보고한 후 국방부장관의 조치에 따라 수용을 중단할 수 있다. <개정 2009.12.29>', 8408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14540, '② 제1항에 따라 보고를 받은 국방부장관은 지체 없이 「감염병의 예방 및 관리에 관한 법률」에서 정하는 바에 따라 필요한 조치를 하여야 한다. 이 경우 군교정시설이 아닌 곳에 수용된 사람에 대하여는 제38조제2항 및 제3항을 준용한다. <개정 2009.12.29>', 8408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14541, null, 8409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14542, '① 소장은 신입자와 다른 군교정시설에서 이송되어 온 사람을 식별하기 위하여 필요한 한도에서 사진촬영, 지문채취, 군수용자 번호지정, 그 밖에 대통령령으로 정하는 조치를 하여야 한다.', 8410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14543, '② 소장은 수용목적상 필요하면 수용 중인 사람에 대하여도 제1항의 조치를 할 수 있다.', 8410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14544, '① 국방부장관은 필요하면 법무부장관의 동의를 받아 군수용자를 일반교도소나 구치소에 수용할 수 있다. 다만, 여성 군수용자는 특별한 사유가 없으면 일반교도소나 구치소에 수용하여야 한다.', 8412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14545, '② 제1항에 따라 일반교도소나 구치소에 수용된 군수용자에게는 「형의 집행 및 수용자의 처우에 관한 법률」을 적용한다.', 8412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14546, '① 소장은 군수용자의 건강, 계절 등을 고려하여 군수용자에게 건강 유지에 적합한 의류ㆍ침구, 그 밖의 생활용품을 지급한다.', 8414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14547, '② 제1항에 따른 의류ㆍ침구, 그 밖의 생활용품의 지급기준 등에 관하여 필요한 사항은 국방부령으로 정한다.', 8414);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14548, '① 소장은 군수용자에게 건강상태, 나이, 부과된 작업의 종류, 그 밖의 개인적 특성을 고려하여 건강 및 체력을 유지하는 데에 필요한 음식물을 지급한다.', 8415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14549, '② 제1항에 따라 지급하는 음식물의 구분 및 지급 방법 등에 관하여 필요한 사항은 대통령령으로 정하고, 구체적인 음식물의 지급기준 등에 관하여 필요한 사항은 국방부령으로 정한다.', 8415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14550, '① 군수용자는 소장의 허가를 받아 자신의 비용으로 음식물ㆍ의류ㆍ침구, 그 밖에 수용생활에 필요한 물품을 구매할 수 있다.', 8416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14551, '② 제1항에 따른 물품의 자비구매 허가의 기준에 관한 사항은 대통령령으로 정하고, 자비구매 물품의 종류, 공급 및 검수 등에 관한 사항은 국방부령으로 정한다.', 8416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14552, '① 소장은 군수용자의 휴대금품(군수용자가 군교정시설에 수용될 때 지니고 있는 현금ㆍ자기앞수표, 그 밖의 휴대품을 말한다. 이하 같다)을 군교정시설에 영치(領置)한다. 다만, 휴대품이 다음 각 호의 어느 하나에 해당하는 것이면 군수용자로 하여금 자신이 지정하는 사람에게 보내게 하거나 그 밖의 적당한 방법으로 처분하게 할 수 있다.', 8417);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14553, '② 소장은 군수용자가 제1항 단서에 따라 처분하여야 할 휴대품을 상당한 기간 내에 처분하지 아니하면 폐기할 수 있다.', 8417);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14554, '③ 군수용자 휴대금품의 영치ㆍ사용, 영치의 예외 등에 관하여 필요한 사항은 대통령령으로 정한다.', 8417);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14555, '① 군수용자는 서신ㆍ도서, 그 밖에 수용생활에 필요한 물품을 국방부장관이 정하는 범위에서 소지할 수 있다.', 8418);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14556, '② 소장은 제1항에 따른 소지범위를 벗어난 물품으로서 특별히 군교정시설에 영치할 필요가 있다고 인정하지 아니하는 물품은 군수용자로 하여금 자신이 지정하는 사람에게 보내게 하거나 그 밖의 적당한 방법으로 처분하게 할 수 있다.', 8418);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14557, '③ 소장은 군수용자가 제2항에 따라 처분하여야 할 물품을 상당한 기간 내에 처분하지 아니하면 폐기할 수 있다.', 8418);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14558, '① 군수용자 외의 사람이 군수용자에게 금품을 교부하려고 신청하면 소장은 다음 각 호의 어느 하나에 해당할 때를 제외하고는 이를 허가하여야 한다.', 8419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14559, '② 소장은 제1항에 따라 교부를 허가한 금품을 대통령령으로 정하는 바에 따라 검사한 후 군수용자에게 사용하게 하여야 한다.', 8419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14560, '③ 소장은 군수용자에게 보내온 금품을 본인이 받기를 거부하거나 제1항 각 호의 어느 하나에 해당하면 보낸 사람에게 돌려보내야 한다.', 8419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14561, '④ 소장은 제3항의 경우에 금품을 보낸 사람을 알 수 없거나 보낸 사람의 주소가 분명하지 아니할 때에는 그 사실을 공고하여야 하고, 공고한 날부터 6개월이 지나도 금품 교부를 청구하는 사람이 없으면 그 금품은 국고에 귀속된다.', 8419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14562, '⑤ 소장은 제3항이나 제4항에 따른 조치를 하였으면 그 사실을 군수용자에게 알려주어야 한다.', 8419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14563, '⑥ 제1항부터 제5항까지에서 규정한 사항 외에 군수용자에 대한 금품 교부의 허가에 관하여 필요한 사항은 국방부령으로 정한다.', 8419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14564, '① 소장은 사망자나 도주자가 남겨둔 금품이 있으면 사망자의 상속인이나 도주자의 가족에게 그 내용 및 교부 청구절차 등을 알려주어야 한다. 다만, 부패하거나 없어질 우려가 있는 것은 폐기할 수 있다.', 8420);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14565, '② 소장은 상속인이나 가족이 제1항의 금품을 청구하면 지체 없이 교부하여야 한다. 다만, 제1항에 따른 고지를 받은 날(알려줄 수가 없는 경우에는 청구사유가 발생한 날을 말한다)부터 1년이 지나도 청구하지 아니하면 그 금품은 국고에 귀속된다.', 8420);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14566, '③ 소장은 제2항 본문에도 불구하고 제1항의 금품을 그대로 교부하기 어려운 특별한 사정이 있으면 그 금품을 팔아 대가를 상속인이나 가족에게 교부할 수 있다.', 8420);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14567, '① 군수용자는 자신의 신체와 의류를 청결히 하여야 하고, 자신이 사용하는 거실ㆍ작업장, 그 밖의 수용시설의 청결 유지에 협력하여야 한다.', 8425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14568, '② 군수용자는 위생을 위하여 머리나 수염을 단정하게 하여야 한다.', 8425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14569, '① 소장은 군수용자가 건강 유지에 필요한 운동과 목욕을 정기적으로 할 수 있도록 하여야 한다.', 8426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14570, '② 제1항에 따른 운동시간, 목욕횟수 등에 관하여 필요한 사항은 대통령령으로 정한다.', 8426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14571, '① 소장은 군수용자에 대하여 건강검진을 정기적으로 실시하여야 한다.', 8427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14572, '② 제1항에 따른 건강검진의 횟수 등에 관하여 필요한 사항은 대통령령으로 정한다.', 8427);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14573, '① 소장은 감염병이나 그 밖에 전염 또는 감염의 우려가 있는 질병의 발생과 확산을 방지하기 위하여 필요하다고 인정하면 군수용자에 대하여 예방접종, 격리수용, 이송, 그 밖에 필요한 조치를 하여야 한다. <개정 2009.12.29>', 8428);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14574, '② 제1항에 따른 소장의 조치에 관하여 필요한 사항은 대통령령으로 정한다.', 8428);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14575, '① 소장은 군수용자에 대한 적절한 치료를 위하여 필요하다고 인정하면 군수용자를 군병원이나 군병원이 아닌 의료시설(이하 "외부의료시설"이라 한다)에서 진료를 받게 할 수 있다.', 8430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14576, '② 제1항에 따라 군병원이나 외부의료시설에서 진료를 받게 된 사람은 군수용자에 준하여 처우한다.', 8430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14577, '③ 소장은 제1항에 따라 군수용자가 군병원이나 외부의료시설에서 진료를 받게 되면 그 사실을 그 가족(가족이 없을 때에는 군수용자가 지정하는 사람을 말한다)에게 지체 없이 통지하여야 한다. 다만, 군수용자가 통지를 원하지 아니하면 그러하지 아니하다.', 8430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14578, '④ 소장은 군수용자가 자신의 고의 또는 중대한 과실로 부상 등을 입어 외부의료시설에서 진료를 받았을 때에는 그 진료비의 전부 또는 일부를 그 군수용자에게 부담시킬 수 있다.', 8430);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14579, '① 군교정시설에는 군수용자의 진료를 위하여 필요한 의료 인력과 설비를 갖추어야 한다.', 8432);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14580, '② 소장은 정신질환이 있다고 의심되는 군수용자가 있으면 정신건강의학과 군의관의 진료를 받게 하여야 한다. <개정 2011.8.4>', 8432);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14581, '③ 외부의사는 군수용자를 진료할 때에는 국방부장관이 정하는 사항을 준수하여야 한다.', 8432);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14582, '① 소장은 군수용자가 진료나 음식물의 섭취를 거부하면 군의관으로 하여금 관찰ㆍ조언 또는 설득을 하게 하여야 한다.', 8433);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14583, '② 소장은 제1항의 조치에도 불구하고 군수용자가 진료나 음식물의 섭취를 계속 거부하여 그 생명에 위험을 가져올 급박한 우려가 있으면 군의관으로 하여금 적당한 진료나 영양보급 등의 조치를 하게 할 수 있다.', 8433);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14584, '① 군수용자는 군교정시설의 외부에 있는 사람과 접견할 수 있다. 다만, 다음 각 호의 어느 하나에 해당하면 그러하지 아니하다.', 8434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14585, '② 소장은 다음 각 호의 어느 하나에 해당하면 교도관으로 하여금 군수용자의 접견내용을 청취ㆍ기록ㆍ녹음 또는 녹화하게 할 수 있다. 이 경우 접견을 하는 군수용자와 군수용자가 아닌 사람은 국어로 의사소통을 하기 어려운 사정이 있는 경우 외에는 외국어를 사용하여서는 아니 된다.', 8434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14586, '③ 제2항에 따라 녹음ㆍ녹화하는 경우에는 미리 군수용자와 그 상대방에게 그 사실을 알려주어야 한다.', 8434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14587, '④ 군수용자의 구분에 따른 접견의 횟수ㆍ시간ㆍ장소ㆍ방법 및 제2항에 따른 접견내용의 청취ㆍ기록ㆍ녹음ㆍ녹화, 접견기록물 등의 관리 등에 관하여 필요한 사항은 대통령령으로 정한다.', 8434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14588, null, 8435);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14589, '① 군수용자는 다른 사람에게 서신을 보내거나 다른 사람으로부터 서신을 받을 수 있다. 다만, 다음 각 호의 어느 하나에 해당하면 그러하지 아니하다.', 8436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14590, '② 제1항 본문에도 불구하고 같은 군교정시설에 수용되어 있는 군수용자 사이에 서신을 주고받으려면 소장의 허가를 받아야 한다.', 8436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14591, '③ 소장은 군수용자가 주고받는 서신에 법령에서 금지한 물품이 들어 있는지 확인할 수 있다.', 8436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14592, '④ 군수용자가 주고받는 서신의 내용은 검열받지 아니한다. 다만, 다음 각 호의 어느 하나에 해당하면 그러하지 아니하다.', 8436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14593, '⑤ 소장은 제3항 또는 제4항 단서에 따라 확인하거나 검열한 결과 군수용자의 서신에 법령에서 금지한 물품이 들어 있거나 서신의 내용이 다음 각 호의 어느 하나에 해당하면 그 서신을 보내거나 받는 것을 금지할 수 있다.', 8436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14594, '⑥ 소장은 제3항에 따라 확인을 하거나 제4항 단서에 따라 검열을 한 뒤 그 서신이 제1항 각 호 또는 제5항 각 호의 어느 하나에 해당하지 아니하는 경우에는 지체 없이 군수용자의 서신을 발송하거나 교부하여야 한다.', 8436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14595, '⑦ 소장은 제1항 단서 또는 제5항에 따라 보내거나 받는 것이 금지된 서신은 군수용자에게 그 사유를 알린 후 군교정시설에 영치한다. 다만, 군수용자가 동의하면 폐기할 수 있다.', 8436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14596, '⑧ 제1항부터 제5항까지의 규정에 따른 서신 발송의 횟수, 서신 내용물의 확인방법 및 서신 내용의 검열절차 등에 관하여 필요한 사항은 대통령령으로 정한다.', 8436);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14597, '① 군수용자는 소장의 허가를 받아 군교정시설의 외부에 있는 사람과 전화통화를 할 수 있다.', 8437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14598, '② 제1항에 따른 허가에는 통화내용의 청취 또는 녹음을 조건으로 붙일 수 있다.', 8437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14599, '③ 군수용자의 전화통화에 관하여는 제42조제2항 후단 및 제43조를 준용한다.', 8437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14600, '④ 제2항에 따라 통화내용을 청취하거나 녹음하려면 미리 군수용자 와 상대방에게 그 사실을 알려주어야 한다.', 8437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14601, '⑤ 제1항과 제2항에 따른 전화통화의 허가범위, 통화내용의 청취ㆍ녹음 등에 관하여 필요한 사항은 대통령령으로 정한다.', 8437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14602, '① 군수용자는 군교정시설에서 실시되는 종교의식이나 행사에 참석할 수 있으며, 개별적인 종교상담을 받을 수 있다.', 8438);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14603, '② 군수용자는 자신의 신앙생활에 필요한 서적이나 물품을 소지할 수 있다.', 8438);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14604, '③ 소장은 다음 각 호의 어느 하나에 해당하면 제1항과 제2항에서 규정하고 있는 사항을 제한할 수 있다.', 8438);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14605, '④ 제1항부터 제3항까지의 규정에 따라 군수용시설에서 실시하는 종교행사의 종류와 참석 대상ㆍ방법, 종교상담의 대상ㆍ방법 및 종교 서적ㆍ물품의 소지범위 등에 관하여 필요한 사항은 국방부령으로 정한다.', 8438);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14606, '① 군수용자는 자신의 비용으로 신문ㆍ잡지 또는 도서(이하 "신문등"이라 한다)의 구독을 신청할 수 있다.', 8440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14607, '② 소장은 제1항에 따라 구독을 신청한 신문등이 「출판문화산업 진흥법」에 따른 유해간행물인 경우를 제외하고는 구독을 허가하여야 한다.', 8440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14608, '③ 제1항에 따라 구독을 신청할 수 있는 신문등의 범위와 수량, 구독허가의 취소 등에 관하여 필요한 사항은 국방부령으로 정한다.', 8440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14609, '① 군수용자는 정서 안정과 교양 습득을 위하여 대통령령으로 정하는 바에 따라 라디오 청취와 텔레비전 시청을 할 수 있다.', 8441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14610, '② 소장은 다음 각 호의 어느 하나에 해당하면 군수용자에 대하여 라디오 청취 및 텔레비전 시청을 일시 중단시키거나 개별 군수용자에 대하여 라디오 청취 또는 텔레비전 시청을 금지할 수 있다.', 8441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14611, '③ 제1항 및 제2항에 따른 방송설비, 방송프로그램, 방송시간 등에 관하여 필요한 사항은 국방부령으로 정한다.', 8441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14612, '① 군수용자는 문서나 도화를 작성하거나 문예ㆍ학술, 그 밖의 사항에 관하여 집필할 수 있다. 다만, 소장이 시설의 안전이나 질서를 해칠 명백한 위험이 있다고 인정하는 경우에는 그러하지 아니하다.', 8442);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14613, '② 제1항에 따라 작성 또는 집필한 문서나 도화의 소지와 처분에 관하여는 제26조를 준용한다.', 8442);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14614, '③ 제1항에 따라 작성 또는 집필한 문서나 도화가 제44조제5항 각 호의 어느 하나에 해당하는 경우에는 같은 조 제7항을 준용한다.', 8442);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14615, '④ 제1항부터 제3항까지의 규정에 따른 집필용구의 관리, 집필의 시간ㆍ장소, 집필한 문서 또는 도화의 외부반출 등에 관하여 필요한 사항은 대통령령으로 정한다.', 8442);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14616, '① 군수형자에 대하여는 교육, 교화프로그램, 작업, 직업훈련 등을 통하여 교정ㆍ교화를 도모하고 사회생활에 적응하는 능력을 기르도록 처우하여야 한다.', 8443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14617, '② 소장은 국방부령으로 정하는 바에 따라 군수형자의 인성, 행동 특성 및 자질, 뉘우침의 정도, 상벌 실적, 작업 실적 및 교육ㆍ훈련 실적 등을 측정ㆍ평가하고, 그 결과를 군수형자의 처우에 반영할 수 있다.', 8443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14618, '① 소장은 군수형자가 건전한 사회복귀에 필요한 지식과 소양을 습득하도록 교육할 수 있다.', 8445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14619, '② 소장은 제1항에 따른 교육을 위하여 필요하면 군수형자를 외부의 교육기관에 통학하게 하거나 위탁하여 교육받게 할 수 있다.', 8445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14620, '③ 교육대상자인 군수형자는 교육과 관련된 관계 법령, 학칙 및 소장이 정하는 교육관리지침 등을 성실하게 준수하여야 한다.', 8445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14621, '④ 제1항 및 제2항에 따른 교육대상자의 선발 및 선발 취소, 교육과정, 외부통학, 위탁교육 등에 관하여 필요한 사항은 국방부령으로 정한다.', 8445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14622, '① 소장은 군수형자의 교정ㆍ교화를 위하여 상담ㆍ심리치료, 그 밖의 교화프로그램을 실시하여야 한다.', 8446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14623, '② 제1항에 따른 교화프로그램의 종류ㆍ내용 등에 관하여 필요한 사항은 국방부령으로 정한다.', 8446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14624, '① 군수형자에게 부과하는 작업은 건전한 사회복귀를 위하여 기술을 습득하고, 근로의욕을 고취하는 데에 적합하여야 한다.', 8447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14625, '② 소장은 군수형자에게 작업을 부과하려면 나이ㆍ형기ㆍ건강상태ㆍ기술ㆍ성격ㆍ취미ㆍ경력ㆍ장래생계, 그 밖의 군수형자의 사정을 고려하여야 한다.', 8447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14626, '① 소장은 군수형자의 건전한 사회복귀와 기술 습득을 촉진하기 위하여 필요하면 군수형자를 외부기업체 등에 통근하며 작업하게 할 수 있다.', 8450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14627, '② 제1항에 따른 외부 통근 작업 대상자 및 외부기업체 등의 선정기준, 선정 취소 등에 관하여 필요한 사항은 국방부령으로 정하고, 그 밖에 외부 통근 작업의 운영에 관하여 필요한 사항은 국방부장관이 정한다.', 8450);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14628, '① 소장은 군수형자의 건전한 사회복귀를 위하여 기술 습득 및 향상을 위한 직업능력개발훈련(이하 "직업훈련"이라 한다)을 실시할 수 있다.', 8451);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14629, '② 소장은 군수형자의 직업훈련을 위하여 필요하면 외부의 기관이나 단체에서 훈련을 받게 할 수 있다.', 8451);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14630, '③ 제1항 및 제2항에 따른 직업훈련 대상자의 선정기준 등에 관하여 필요한 사항은 국방부령으로 정한다.', 8451);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14631, '① 소장은 군수형자의 신청에 따라 제58조의 작업, 제59조제2항의 훈련, 그 밖에 집중적인 근로가 필요한 작업을 부과하는 경우에는 접견, 전화통화, 교육 및 공동행사 참가 등의 처우를 제한할 수 있다. 다만, 접견이나 전화통화를 제한할 때에는 공휴일, 토요일과 그 밖에 대통령령으로 정하는 휴일과 그 군수형자의 작업이 없는 날에 접견이나 전화통화를 할 수 있게 하여야 한다.', 8452);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14632, '② 소장은 제1항에 따라 작업을 부과하거나 훈련을 받게 하기 전에 해당 군수형자에게 제한되는 처우의 내용을 충분히 설명하여야 한다.', 8452);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14633, '① 소장은 군수형자의 가족이나 배우자의 직계존속이 사망하면 2일간, 부모나 배우자의 기일(忌日)을 맞이하면 1일간 해당 군수형자의 작업을 면제한다. 다만, 군수형자가 작업을 계속하기를 원하는 경우에는 그러하지 아니하다.', 8454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14634, '② 소장은 군수형자에게 부상, 질병, 그 밖에 작업을 계속하기 어려운 특별한 사정이 있으면 그 사유가 없어질 때까지 작업을 면제할 수 있다.', 8454);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14635, '① 작업수입은 국고수입으로 한다.', 8455);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14636, '② 소장은 군수형자의 근로의욕을 고취하고 건전한 사회복귀를 지원하기 위하여 국방부장관이 정하는 바에 따라 작업의 종류, 작업성적, 교정성적, 그 밖의 사정을 고려하여 군수형자에게 작업장려금을 지급할 수 있다.', 8455);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14637, '③ 제2항의 작업장려금은 석방할 때 본인에게 지급한다. 다만, 본인의 가족생활 부조, 교화 또는 건전한 사회복귀를 위하여 특별히 필요하면 석방 전이라도 그 전부 또는 일부를 지급할 수 있다.', 8455);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14638, '① 소장은 군수형자가 다음 각 호의 어느 하나에 해당하면 국방부장관이 정하는 바에 따라 위로금이나 조위금을 지급할 수 있다.', 8456);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14639, '② 위로금은 석방할 때 본인에게 지급하고, 조위금은 그 상속인에게 지급한다.', 8456);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14640, '① 소장은 6개월 이상 복역한 군수형자로서 그 형기의 3분의 1(21년 이상의 유기형 또는 무기형의 경우에는 7년을 말한다)이 지나고 교정성적이 우수한 사람이 다음 각 호의 어느 하나에 해당하면 1년 중 20일 이내의 귀휴(기간과 행선지를 정하여 외출ㆍ외박할 수 있도록 하는 것을 말한다. 이하 같다)를 허가할 수 있다.', 8458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14641, '② 소장은 다음 각 호의 어느 하나에 해당하는 사유가 있는 군수형자에 대하여는 제1항에도 불구하고 5일 이내의 특별귀휴를 허가할 수 있다.', 8458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14642, '③ 소장은 귀휴를 허가하는 경우에 국방부령으로 정하는 바에 따라 거소의 제한이나 그 밖에 필요한 조건을 붙일 수 있다.', 8458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14643, '④ 제1항 및 제2항의 귀휴기간은 형 집행기간에 포함한다.', 8458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14644, null, 8459);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14645, '① 군인인 군미결수용자는 수사ㆍ재판 또는 법률로 정하는 조사에 참석할 때에는 군복을 착용하여야 한다.', 8463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14646, '② 군무원과 민간인인 군미결수용자는 수사ㆍ재판 또는 법률에서 정하는 조사에 참석할 때에는 사복을 착용할 수 있다.', 8463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14647, '① 제42조제2항에도 불구하고 군미결수용자와 변호인(변호인이 되려고 하는 사람을 포함한다. 이하 같다)의 접견에는 교도관이 참여하지 못하며 그 내용을 청취 또는 녹취하지 못한다. 다만, 보이는 거리에서 군미결수용자를 관찰할 수 있다.', 8465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14648, '② 군미결수용자와 변호인의 접견은 시간과 횟수를 제한하지 아니한다.', 8465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14649, '③ 제44조제4항 단서에도 불구하고 군미결수용자와 변호인 사이의 서신은 군교정시설에서 상대방이 변호인임을 확인할 수 없는 경우를 제외하고는 검열할 수 없다.', 8465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14650, '① 소장은 군미결수용자에 대하여는 신청에 따라 교육 또는 교화프로그램을 실시하거나 작업을 부과할 수 있다.', 8467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14651, '② 제1항에 따라 군미결수용자에게 교육 또는 교화프로그램을 실시하거나 작업을 부과하는 경우에는 제53조부터 제55조까지 및 제60조부터 제65조까지의 규정을 준용한다.', 8467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14652, '① 사형확정자는 미결수용실에 수용한다.', 8469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14653, '② 사형확정자는 독거수용한다. 다만, 자살방지 또는 교화, 작업 등을 위하여 필요한 경우에는 국방부령으로 정하는 바에 따라 혼거수용할 수 있다.', 8469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14654, '③ 소장은 사형확정자의 심리적 안정 및 원만한 수용생활을 위하여 본인의 신청에 따라 심리상담 또는 종교상담을 받게 하거나 작업을 부과할 수 있다.', 8469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14655, null, 8471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14656, '① 교도관은 시설의 안전과 질서유지를 위하여 필요하면 대통령령으로 정하는 바에 따라 군수용자의 신체ㆍ의류ㆍ휴대품ㆍ거실 및 작업장 등을 검사할 수 있다.', 8472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14657, '② 제1항에 따라 교도관이 군수용자의 신체를 검사할 때에는 불필요한 고통이나 수치심을 느끼지 아니하도록 유의하여야 하고, 특히 신체를 면밀하게 검사할 필요가 있으면 다른 군수용자가 볼 수 없는 차단된 장소에서 하여야 한다.', 8472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14658, '③ 교도관은 시설의 안전과 질서유지를 위하여 필요하면 군교정시설을 출입하는 군수용자 외의 사람에 대하여 의류와 휴대품을 검사할 수 있다. 이 경우 출입자가 제79조의 금지물품을 소지하고 있으면 군교정시설에 맡기도록 하여야 하고, 이에 따르지 아니하면 출입을 금지할 수 있다.', 8472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14659, '④ 여성의 의류와 휴대품에 대한 검사는 여성 교도관이 하여야 한다.', 8472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14660, '⑤ 소장은 제1항에 따라 검사한 결과 제79조의 금지물품이 발견되면 형사 법령에서 정하는 절차에 따라 처리할 물품을 제외하고는 군수용자에게 알린 후 폐기한다. 다만, 폐기하는 것이 적당하지 아니한 물품은 군교정시설에 영치하거나 군수용자로 하여금 자신이 지정하는 사람에게 보내게 할 수 있다.', 8472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14661, '① 교도관은 자살ㆍ자해ㆍ도주ㆍ폭행ㆍ손괴, 그 밖에 군수용자의 생명ㆍ신체를 해치거나 시설의 안전이나 질서를 해치는 행위(이하 "자살등"이라 한다)를 방지하기 위하여 필요한 범위에서 전자장비를 이용하여 군수용자나 시설을 계호할 수 있다. 다만, 전자영상장비로 거실에 있는 군수용자를 계호하는 것은 자살등의 우려가 클 때에만 할 수 있다.', 8473);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14662, '② 제1항 단서에 따라 거실에 있는 군수용자를 전자영상장비로 계호할 때에는 계호직원ㆍ계호시간 및 계호대상 등을 기록하여야 한다.', 8473);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14663, '③ 제1항과 제2항에 따라 계호하는 경우에는 계호를 받는 군수용자의 인권이 침해되지 아니하도록 유의하여야 한다.', 8473);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14664, '④ 제1항과 제2항에 따른 전자장비의 종류ㆍ설치장소ㆍ사용방법 및 녹화기록물의 관리 등에 관하여 필요한 사항은 국방부령으로 정한다.', 8473);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14665, '① 소장은 군수용자가 다음 각 호의 어느 하나에 해당하면 군의관의 의견을 참고하여 보호실(자살 및 자해 방지 등의 설비를 갖춘 거실을 말한다. 이하 같다)에 수용할 수 있다.', 8474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14666, '② 군수용자를 보호실에 수용하는 기간은 15일 이내로 한다. 다만, 소장은 특별히 계속하여 군수용자를 보호실에 수용할 필요가 있으면 군의관의 의견을 참고하여 그 기간을 연장할 수 있다.', 8474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14667, '③ 제2항 단서에 따른 기간 연장은 7일 이내로 하되, 계속하여 3개월을 초과할 수 없다.', 8474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14668, '④ 소장은 군수용자를 보호실에 수용하거나 수용기간을 연장할 때에는 그 사유를 본인에게 알려주어야 한다.', 8474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14669, '⑤ 군의관은 보호실에 수용된 군수용자의 건강상태를 수시로 확인하여야 한다.', 8474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14670, '⑥ 소장은 군수용자를 보호실에 수용할 사유가 소멸하면 보호실 수용을 즉시 중단하여야 한다.', 8474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14671, '① 소장은 군수용자가 다음 각 호의 어느 하나에 해당하는 때에 강제력을 행사하거나 제85조의 보호장비를 사용하여도 그 목적을 달성할 수 없는 경우에만 진정실(일반 거실과 격리되어 있고, 방음설비 등을 갖춘 거실을 말한다. 이하 같다)에 수용할 수 있다.', 8475);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14672, '② 군수용자의 진정실 수용기간은 24시간 이내로 한다. 다만, 소장은 특별히 계속하여 군수용자를 진정실에 수용할 필요가 있으면 군의관의 의견을 참고하여 그 시간을 연장할 수 있다.', 8475);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14673, '③ 제2항 단서에 따른 시간 연장은 12시간 이내로 하되, 계속하여 3일을 초과할 수 없다.', 8475);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14674, '④ 진정실에 수용된 군수용자에 대하여는 제82조제4항부터 제6항까지의 규정을 준용한다.', 8475);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14675, '① 교도관은 군수용자가 다음 각 호의 어느 하나에 해당하면 보호장비를 사용할 수 있다.', 8476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14676, '② 군수용자에 대하여 보호장비를 사용할 때에는 군수용자의 나이, 건강상태 및 수용생활 태도 등을 고려하여야 한다.', 8476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14677, '③ 교도관이 군교정시설에서 군수용자에 대하여 보호장비를 사용한 경우에는 군의관은 그 군수용자의 건강상태를 수시로 확인하여야 한다.', 8476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14678, '① 보호장비의 종류는 다음 각 호와 같다.', 8477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14679, '② 보호장비의 종류별 사용요건은 다음 각 호와 같다.', 8477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14680, '③ 제1항 및 제2항에 따른 보호장비의 사용절차 등에 관하여 필요한 사항은 대통령령으로 정하고, 보호장비의 규격 및 종류별 사용 방법은 국방부령으로 정한다.', 8477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14681, '① 교도관은 필요한 최소한의 범위에서 보호장비를 사용하여야 하고, 그 사유가 없어지면 지체 없이 사용을 중단하여야 한다.', 8478);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14682, '② 보호장비는 징벌의 수단으로 사용되어서는 아니 된다.', 8478);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14683, '① 교도관등은 군수용자가 다음 각 호의 어느 하나에 해당하면 강제력을 행사할 수 있다.', 8479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14684, '② 교도관등은 군수용자가 아닌 사람이 다음 각 호의 어느 하나에 해당하면 강제력을 행사할 수 있다.', 8479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14685, '③ 제1항과 제2항에 따라 강제력을 행사할 때에는 보안장비를 사용할 수 있다.', 8479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14686, '④ 제3항에서 "보안장비"란 교도봉, 가스분사기, 가스총, 최루탄 등 사람의 생명과 신체 보호, 군수용자의 도주 방지 및 시설의 안전과 질서유지를 위하여 교도관등이 사용하는 장비와 기구를 말한다.', 8479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14687, '⑤ 제1항과 제2항에 따라 강제력을 행사하려면 미리 상대방에게 경고하여야 한다. 다만, 상황이 급박하여 경고할 시간적인 여유가 없을 때에는 그러하지 아니하다.', 8479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14688, '⑥ 강제력의 행사는 필요한 최소한도에 그쳐야 한다.', 8479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14689, '⑦ 제3항에 따른 보안장비의 종류, 종류별 사용요건 및 사용절차 등에 관하여 필요한 사항은 국방부령으로 정한다.', 8479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14690, '① 교도관등은 다음 각 호의 어느 하나에 해당하면 군수용자에 대하여 무기를 사용할 수 있다.', 8480);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14691, '② 교도관등은 군교정시설(교도관이 군교정시설 밖에서 군수용자를 계호하고 있는 경우 그 장소를 포함한다)에서 자신이나 다른 사람의 생명ㆍ신체를 보호하거나 군수용자의 탈취를 저지하거나 건물 또는 그 밖의 시설과 무기에 대한 위험을 방지하기 위하여 급박하다고 인정되는 충분한 이유가 있으면 군수용자가 아닌 사람에 대하여도 무기를 사용할 수 있다.', 8480);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14692, '③ 교도관등은 소장이나 그 직무를 대행하는 사람의 명령을 받아 무기를 사용한다. 다만, 그 명령을 받을 시간적인 여유가 없으면 그러하지 아니하다.', 8480);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14693, '④ 제1항과 제2항에 따라 무기를 사용하려면 공포탄을 발사하거나 그 밖의 적당한 방법으로 미리 상대방에게 무기 사용을 경고하여야 한다.', 8480);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14694, '⑤ 무기의 사용은 필요한 최소한도에 그쳐야 하며, 최후의 수단이어야 한다.', 8480);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14695, '⑥ 제1항 및 제2항에 따라 사용할 수 있는 무기의 종류, 무기의 종류별 사용요건 및 사용절차 등에 관하여 필요한 사항은 국방부령으로 정한다.', 8480);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14696, '① 천재지변이나 그 밖의 재해가 발생하여 시설의 안전과 질서유지를 위하여 긴급한 조치가 필요하면 소장은 군수용자로 하여금 피해의 복구나 그 밖의 응급용무를 보조하게 할 수 있다.', 8481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14697, '② 소장은 군교정시설에서 천재지변이나 그 밖의 사변에 대한 피난 방법이 없을 때에는 군수용자를 다른 장소로 이송할 수 있다.', 8481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14698, '③ 소장은 제2항에 따른 이송을 할 수 없으면 수용자를 일시적으로 석방할 수 있다.', 8481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14699, '④ 제3항에 따라 석방된 사람은 석방 후 24시간 이내에 군교정시설 또는 「군인사법」 제5조제2항에 따른 기본병과 중 수사 및 교정업무 등을 주로 담당하는 병과(이하 "군사경찰과"라 한다)에 속하는 군인으로 편성된 부대(이하 "군사경찰부대"라 한다)나 경찰관서에 출석하여야 한다. <개정 2020.2.4>', 8481);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14700, '① 교도관은 군수용자가 도주하거나 제117조 각 호의 어느 하나에 해당하는 행위(이하 "도주등"이라 한다)를 하였을 때에는 도주 후 또는 출석기한이 지난 후 72시간 이내에만 그를 체포할 수 있다.', 8482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14701, '② 교도관은 제1항에 따른 체포를 위하여 긴급히 필요하면 도주등을 하였다고 의심할 만한 충분한 이유가 있는 사람이나 도주등을 한 사람의 이동경로나 소재를 안다고 인정되는 사람을 정지시켜 질문할 수 있다.', 8482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14702, '③ 교도관은 제2항에 따라 질문을 할 때에는 그 신분을 표시하는 증표를 보여주고 질문의 목적과 이유를 설명하여야 한다.', 8482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14703, '④ 교도관은 제1항에 따른 체포를 위하여 영업시간 내에 흥행장ㆍ여관ㆍ음식점ㆍ역, 그 밖에 많은 사람이 출입하는 장소의 관리자나 관계인에게 그 장소의 출입이나 그 밖에 특별히 필요한 사항에 관하여 협조를 요구할 수 있다.', 8482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14704, '⑤ 교도관은 제4항에 따라 필요한 장소에 출입하는 경우 그 신분을 표시하는 증표를 보여주어야 하고, 그 장소의 관리자나 관계인의 정당한 업무를 방해하여서는 아니 된다.', 8482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14705, '① 군수용자는 군교정시설의 안전과 질서유지를 위하여 국방부장관이 정하는 규율을 준수하여야 한다.', 8483);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14706, '② 군수용자는 소장이 정하는 일과시간표를 준수하여야 한다.', 8483);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14707, '③ 군수용자는 교도관의 직무상 지시에 복종하여야 한다.', 8483);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14708, null, 8484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14709, null, 8485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14710, null, 8486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14711, '① 제94조제4호부터 제13호까지의 징벌은 함께 부과할 수 있다.', 8487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14712, '② 군수용자에게 징벌을 부과하는 경우에는 다음 각 호의 구분에 따라 징벌을 가중할 수 있다.', 8487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14713, '③ 다른 군수용자를 교사(敎唆)하여 징벌대상 행위를 하게 한 군수용자나 다른 군수용자의 징벌대상 행위를 방조(幇助)한 군수용자에게는 그 징벌대상 행위를 한 군수용자와 같은 징벌을 부과하되, 징벌대상 행위를 방조한 군수용자에게는 정황을 고려하여 징벌을 2분의 1까지 감경할 수 있다.', 8487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14714, '④ 징벌은 같은 행위에 대하여 거듭하여 부과할 수 없으며, 행위의 동기 및 경중, 행위 후의 정황, 그 밖의 사정을 고려하여 수용목적 달성에 필요한 최소한도에 그쳐야 한다.', 8487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14715, '⑤ 징벌사유가 발생한 날부터 2년이 지나면 그 사유로 징벌을 부과하지 못한다.', 8487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14716, '⑥ 제1항부터 제5항까지에서 규정한 사항 외에 징벌의 부과기준, 징벌 부과 시의 고려사항 등 징벌의 부과에 관하여 필요한 사항은 국방부령으로 정한다.', 8487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14717, '① 소장은 징벌사유에 해당하는 행위를 하였다고 의심할 만한 충분한 이유가 있는 군수용자(이하 "징벌대상자"라 한다) 또는 참고인을 국방부령으로 정하는 바에 따라 조사할 수 있다.', 8488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14718, '② 징벌대상자가 다음 각 호의 어느 하나에 해당하면 조사기간 중 분리하여 수용할 수 있다.', 8488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14719, '③ 소장은 징벌대상자가 제2항 각 호의 어느 하나에 해당하면 접견, 서신수수, 전화통화, 실외운동, 작업, 교육훈련, 공동행사 참가 등 다른 사람과 접촉할 수 있는 처우의 전부 또는 일부를 제한할 수 있다.', 8488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14720, '① 징벌대상자의 징벌을 결정하기 위하여 군교정시설에 징벌위원회(이하 이 조에서 "위원회"라 한다)를 둔다.', 8489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14721, '② 위원회는 위원장을 포함한 5명 이상 7명 이하의 위원으로 구성하되, 위원장은 소장이 되고, 위원은 소장이 소속 부대의 장교, 군법무관 및 교정에 관한 학식과 경험이 풍부한 외부인사 중에서 임명하거나 위촉한다. 이 경우 외부인사인 위원과 군법무관은 각각 1명 이상으로 한다.', 8489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14722, '③ 위원회는 소장의 징벌 요구에 따라 개회하며, 징벌은 그 의결로 정한다.', 8489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14723, '④ 징벌위원회는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.', 8489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14724, '⑤ 위원회의 위원이 징벌대상자의 친족이거나 그 밖에 공정한 심의ㆍ의결을 기대할 수 없는 특별한 사유가 있을 때에는 위원회에 참석할 수 없다.', 8489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14725, '⑥ 징벌대상자는 위원회의 위원에 대하여 기피(忌避) 신청을 할 수 있다. 이 경우 위원회는 의결로 기피 여부를 결정하여야 한다.', 8489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14726, '⑦ 위원회는 징벌대상자가 위원회에 출석하여 충분한 진술을 할 수 있는 기회를 주어야 하며, 징벌대상자는 서면이나 말로써 자기에게 유리한 사실을 진술하거나 증거를 제출할 수 있다.', 8489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14727, '⑧ 제1항부터 제7항까지에서 규정한 사항 외에 위원회의 구성 및 운영에 관하여 필요한 사항은 대통령령으로 정한다.', 8489);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14728, '① 징벌은 소장이 집행한다.', 8490);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14729, '② 소장은 징벌 집행을 위하여 필요하다고 인정하면 군수용자를 분리하여 수용할 수 있다.', 8490);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14730, '③ 제94조제14호의 징벌을 받은 사람에게는 그 기간 중 같은 조 제4호부터 제13호까지의 징벌이 함께 부과된다. 다만, 소장은 군수용자의 권리구제, 군수형자의 교화나 건전한 사회복귀를 위하여 특별히 필요하다고 인정하면 집필, 서신수수, 접견 또는 실외운동을 허가할 수 있다.', 8490);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14731, '④ 소장은 제94조제13호 또는 제14호의 징벌을 집행할 때에는 군의관으로 하여금 미리 군수용자의 건강을 확인하도록 하여야 하고, 징벌이 집행 중일 때에도 징벌을 받고 있는 군수용자의 건강상태를 수시로 확인하여야 한다.', 8490);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14732, '⑤ 제1항부터 제4항까지에서 규정한 사항 외에 징벌기간의 계산 등 징벌의 집행에 관하여 필요한 사항은 대통령령으로 정한다.', 8490);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14733, '① 소장은 질병이나 그 밖의 사유로 징벌 집행이 곤란하면 그 사유가 없어질 때까지 그 집행을 일시적으로 정지할 수 있다.', 8491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14734, '② 소장은 징벌 집행 중인 군수용자가 뉘우치는 빛이 뚜렷한 경우에는 그 징벌을 감경하거나 남은 기간의 징벌 집행을 면제할 수 있다.', 8491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14735, '① 징벌위원회가 징벌을 의결하는 때에는 징벌의 원인이 된 행위의 동기 및 정황, 교정성적, 뉘우치는 정도 등 그 사정을 고려할 만한 사유가 있는 군수용자에 대하여 2개월 이상 6개월 이하의 기간 동안 징벌의 집행을 유예할 것을 의결할 수 있다.', 8492);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14736, '② 소장은 징벌 집행의 유예기간 중에 있는 군수용자가 다시 제93조의 징벌대상 행위를 하여 징벌이 결정되면 그 유예한 징벌을 함께 집행한다.', 8492);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14737, '③ 군수용자가 징벌 집행을 유예받은 후 징벌을 받지 아니하고 유예기간이 지나면 그 징벌의 집행은 끝난 것으로 본다.', 8492);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14738, '④ 이 법에서 규정한 사항 외에 징벌의 결정 및 집행에 관하여 필요한 사항은 국방부령으로 정한다.', 8492);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14739, '① 군수용자는 그 처우에 관하여 소장에게 면담을 신청할 수 있다.', 8493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14740, '② 소장은 군수용자의 면담신청을 받으면 다음 각 호의 어느 하나에 해당하는 때를 제외하고는 면담에 응하여야 한다.', 8493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14741, '③ 소장은 특별한 사정이 있으면 소속 교도관으로 하여금 그 면담을 대리하게 할 수 있다. 이 경우 면담을 대리한 사람은 그 결과를 소장에게 지체 없이 보고하여야 한다.', 8493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14742, '④ 소장은 면담한 결과 처리가 필요한 사항이 있으면 그 처리결과를 군수용자에게 통지하여야 한다.', 8493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14743, '① 군수용자는 그 처우에 관하여 불복할 경우 국방부장관 또는 제7조에 따른 순회점검 공무원에게 청원할 수 있다. <개정 2014.5.20>', 8494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14744, '② 제1항에 따라 청원하려는 군수용자는 청원서를 작성하여 봉한 후 소장에게 제출하여야 한다. 다만, 순회점검 공무원에 대한 청원은 말로도 할 수 있다.', 8494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14745, '③ 소장은 청원서를 개봉하여서는 아니 되며, 이를 지체 없이 국방부장관 또는 순회점검 공무원에게 전달하여야 한다. <개정 2014.5.20>', 8494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14746, '④ 제2항 단서에 따라 순회점검 공무원이 군수용자의 청원을 청취하는 경우에는 해당 군교정시설의 교도관등이 참여하여서는 아니 된다.', 8494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14747, '⑤ 청원을 받은 국방부장관은 청원에 대하여 지체 없이 문서로써 결정하여야 한다. <개정 2014.5.20>', 8494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14748, '⑥ 소장은 청원에 관한 결정서를 접수하면 청원인에게 지체 없이 전달하여야 한다.', 8494);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14749, '① 위원회는 위원장을 포함한 5명 이상 9명 이하의 위원으로 구성한다.', 8497);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14750, '② 위원장은 교도소의 장이 되고, 위원은 위원장이 군법무관, 군사경찰과 장교, 교정에 관한 학식과 경험이 풍부한 사람 중에서 위촉한다. <개정 2020.2.4>', 8497);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14751, '③ 이 법에서 규정한 사항 외에 위원회의 구성 및 운영에 관하여 필요한 사항은 국방부령으로 정한다.', 8497);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14752, '① 위원회는 군수형자의 나이, 범죄동기, 죄명, 형기, 교정성적, 건강상태, 가석방 후의 생계능력, 생활환경, 재범의 위험성, 그 밖에 필요한 사정을 고려하여 가석방의 적격 여부를 결정한다.', 8498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14753, '② 위원회는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.', 8498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14754, '③ 가석방 적격 여부의 심사절차 및 조사, 그 밖에 가석방 적격심사에 관하여 필요한 사항은 국방부령으로 정한다.', 8498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14755, '① 위원회는 가석방 적격결정을 하였으면 5일 이내에 국방부장관에게 가석방 허가를 신청하여야 한다.', 8499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14756, '② 국방부장관은 제1항에 따른 위원회의 가석방 허가신청이 적정하다고 인정하면 가석방을 허가할 수 있다.', 8499);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14757, '① 사면, 가석방, 형의 집행면제, 감형에 따른 석방은 그 서류가 도달한 후 12시간 이내에 하여야 한다. 다만, 그 서류에서 석방일시를 지정하고 있으면 그 일시에 한다.', 8501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14758, '② 형기종료에 따른 석방은 형기종료일에 하여야 한다.', 8501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14759, '③ 권한 있는 사람의 명령에 따른 석방은 서류가 도달한 후 5시간 이내에 하여야 한다.', 8501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14760, '① 소장은 사망한 군수용자의 친족이나 군수용자와 특별한 연고가 있는 사람이 그 시신이나 유골의 인도를 청구하면 인도하여야 한다. 다만, 제3항에 따라 합장(合葬)을 한 뒤에는 그러하지 아니하다.', 8505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14761, '② 소장은 제112조에 따라 사망 통지를 받은 사람이 통지를 받은 날부터 3일 이내에 그 시신을 인수하지 아니하거나 시신을 인수할 사람이 없으면 임시로 매장하여야 한다. 다만, 감염병 예방 등을 위하여 필요하면 즉시 화장(火葬)을 하는 등 필요한 조치를 할 수 있다. <개정 2009.12.29>', 8505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14762, '③ 소장은 제2항에 따라 시신을 임시로 매장한 후 2년이 지나도 시신의 인도를 청구하는 사람이 없으면 합장하거나 화장할 수 있다.', 8505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14763, '④ 소장은 병원이나 그 밖의 연구기관이 학술연구상 필요하여 군수용자의 시신 인도를 신청하면 본인의 유언이나 상속인의 승낙이 있는 경우에만 병원이나 그 밖의 연구기관에 시신을 인도할 수 있다.', 8505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14764, '① 군수용자의 교육ㆍ교화, 의료 지원, 그 밖에 군수용자의 처우를 후원하기 위하여 군교정시설에 교정위원을 둘 수 있다.', 8506);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14765, '② 교정위원은 명예직으로 하며 소장의 추천을 받아 국방부장관이 위촉한다. <개정 2014.5.20>', 8506);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14766, '③ 교정위원은 교정위원으로 활동 중에 알게 된 군수용자의 신상에 관한 사항이나 군교정시설의 안전과 관련된 사실을 누설하거나 공개하여서는 아니 된다.', 8506);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14767, '① 소장은 기관ㆍ단체 또는 개인이 군수용자의 교화 등을 위하여 군교정시설에 자발적으로 기탁하는 금품을 받을 수 있다.', 8507);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14768, '② 제1항에 따른 기부금품의 접수방법, 처리절차, 기부금품의 공개 등에 관하여 필요한 사항은 대통령령으로 정한다.', 8507);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14769, '① 다음 각 호의 어느 하나에 해당하는 행위를 한 사람은 6개월 이하의 징역 또는 200만원 이하의 벌금에 처한다.', 8510);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14770, '② 제1항의 미수범은 처벌한다.', 8510);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14771, '③ 제1항의 금지물품은 몰수한다.', 8510);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14772, null, 8511);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14773, '① 군판사와 군검사가 법 제8조제1항에 따라 군교도소, 군교도소 지소(支所) 및 군미결수용실(이하 "군교정시설"이라 한다)을 시찰하려면 신분을 나타내는 증표를 소장에게 보여주고 시찰부에 서명 또는 날인하여야 한다. <개정 2022.6.30>', 8514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14774, '② 소장은 군교도관에게 군판사나 군검사를 시찰하려는 장소로 안내하게 하고, 시찰한 시간을 시찰부에 기록하여야 한다. <개정 2022.6.30>', 8514);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14775, '① 군판사와 군검사 외의 사람이 법 제8조제2항에 따라  군교정시설을 참관하려면 다음 각 호의 사항을 적은 신청서를 소장에게 제출하여야 한다. <개정 2022.6.30>', 8515);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14776, '② 제1항에 따라 신청서를 받은 소장은 참관하려는 사람의 신분과 참관 목적 등을 확인한 후 허가 여부를 결정하여야 한다.', 8515);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14777, '③ 소장은 외국인에게 참관을 허가하려면 국방부장관의 승인을 받아야 한다. <개정 2014.10.28>', 8515);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14778, '④ 소장은 참관을 허가한 사람에게 미리 참관할 때의 주의사항을 알려주어야 한다.', 8515);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14779, null, 8517);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14780, '① 군교도관은 제6조제2호의 계호상 독거수용을 한 군수용자(이하 "계호독거자"라 한다)를 수시로 시찰하여 건강과 교화에 이상이 없는지 살펴야 한다.', 8518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14781, '② 군교도관은 계호독거자가 건강에 이상이 있다고 보일 때에는 즉시 해당 군교정시설을 담당하는 군의관에게 그 사실을 알려야 하고, 교화에 문제가 있다고 인정되면 즉시 소장에게 보고하여야 한다.', 8518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14782, '③ 제2항에 따라 통보받은 군의관은 즉시 계호독거자를 상담ㆍ진찰하는 등 적절한 의료조치를 하여야 하고, 독거수용을 계속하게 되면 건강을 해치게 된다고 판단될 때에는 그 사실을 즉시 소장에게 보고하여야 한다.', 8518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14783, '④ 소장은 계호독거자를 계속 독거수용하는 것이 건강이나 교화에 해롭다고 인정되면 즉시 독거수용을 중단하여야 한다.', 8518);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14784, '① 소장은 거실에 면적, 정원 및 현재인원을 적은 현황표를 붙여야 한다.', 8524);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14785, '② 소장은 거실 앞에 군수용자의 이름표를 붙여야 한다. 이 경우 이름표 윗부분에는 군수용자의 성명, 출생연도, 죄명, 형명(刑名) 및 형기(刑期)를 적고, 아랫부분에는 군수용자 번호와 입소한 날짜를 적되, 윗부분의 내용은 보이지 않도록 하여야 한다. <개정 2014.10.28>', 8524);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14786, '③ 소장은 군수용자가 법령에 따라 지켜야 할 사항과 군수용자의 권리구제 절차에 관한 사항을 거실 안 군수용자가 보기 쉬운 곳에 붙이는 등의 방법으로 비치하여야 한다. <개정 2014.10.28>', 8524);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14787, '① 소장은 군사법원, 군검찰부, 군사경찰부대 등에서 처음으로 군교정시설에 수용되는 사람(이하 "신입자"라 한다)이나 다른 군교정시설로부터 이송(移送)되어 온 사람(이하 "이입자"라 한다)을 인수하였을 때에는 호송인(護送人)에게 인수서를 써 주어야 한다. 이 경우 신입자나 이입자에게 부상이나 질병, 그 밖에 건강에 이상이 있을 때에는 호송인으로부터 그 사실에 대한 확인서를 받아야 한다. <개정 2020.2.4>', 8525);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14788, '② 신입자나 이입자를 인수한 군교도관은 제1항 전단의 인수서에 성명, 나이 및 인수 일시를 적고 서명 또는 날인하여야 한다.', 8525);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14789, '③ 소장은 제1항 후단에 따라 확인서를 받았을 때에는 호송인에게 신입자나 이입자의 성명, 나이, 인계 일시 및 부상의 정도나 질병의 상태 등에 관한 사실을 적고 서명 또는 날인하도록 하여야 한다.', 8525);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14790, '④ 소장은 신입자나 이입자가 감염병(「감염병의 예방 및 관리에 관한 법률」 제2조제2호에 따른 감염병을 말한다. 이하 같다)에 걸린 때에는 인수를 거부할 수 있다. 이 경우 수용을 지휘한 군검사와 소속 부대장 또는 이송 보낸 소장에게 즉시 그 사유를 통보하고 국방부장관에게 보고하여야 한다. <개정 2010.12.29, 2022.6.30>', 8525);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14791, '⑤ 소장은 제4항에도 불구하고 감염병에 걸린 신입자나 이입자가 위독하여 다른 곳으로 이송할 만한 시간적 여유가 없을 때에는 그를 격리수용하고 즉시 필요한 조치를 하여야 한다. <개정 2010.12.29>', 8525);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14792, '① 소장은 신입자의 키, 용모, 문신, 흉터 등 신체의 특징과 가족이나 보호자 등의 연락처를 제19조에 따른 수용기록부에 기록하여야 한다.', 8529);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14793, '② 소장은 업무상 필요한 경우가 아니면 군교도관이 제1항의 수용기록부를 열람하지 못하도록 하여야 한다.', 8529);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14794, '③ 소장은 신입자와 이입자에게 군수용자 번호를 지정하고, 상의 왼쪽 가슴 부위에 번호표를 붙이게 하여야 한다. 다만, 군수용자의 교화 또는 건전한 사회복귀를 위하여 특히 필요하다고 인정하면 번호표를 붙이지 아니할 수 있다.', 8529);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14795, '① 소장은 신입자 또는 이입자가 환자이거나 그 밖에 부득이한 사정이 있는 경우가 아니면 수용된 날부터 7일 동안 신입자만을 수용하는 거실(이하 "신입자거실"이라 한다)에 수용하여야 한다.', 8531);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14796, '② 소장은 신입자거실에 수용된 사람에게는 작업을 부과해서는 아니 된다.', 8531);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14797, '③ 소장은 신입자나 이입자의 처우를 위하여 특히 필요하다고 인정하면 제1항의 기간을 30일까지 연장할 수 있다.', 8531);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14798, '① 소장은 거실, 작업장, 그 밖에 군수용자가 생활하는 장소(이하 "거실등"이라 한다)에 수용생활에 필요한 기구를 갖춰 두어야 한다.', 8537);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14799, '② 거실등에는 제1항에 따라 갖춰 둔 기구의 품목과 수량을 기록한 품목표를 붙여 두어야 한다.', 8537);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14800, '① 소장은 군수용자가 사용하는 의류등을 적당한 시기에 세탁, 수선 또는 교체하여야 한다.', 8544);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14801, '② 자신의 비용으로 구매한 의류등의 세탁이나 수선에 필요한 비용은 군수용자가 부담한다.', 8544);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14802, '① 법 제25조제1항 각 호의 어느 하나에 해당하지 아니하는 휴대품은 영치한 후 사용하게 할 수 있다.', 8545);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14803, '② 소장은 법 제25조제1항 단서에 따라 군수용자의 휴대품을 팔 경우에는 그 비용을 제외한 나머지 대금을 영치할 수 있다.', 8545);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14804, '③ 소장은 법 제25조제1항 각 호의 어느 하나에 해당하는 휴대품을 국방부장관이 정한 기간 내에 처분하지 아니하면 폐기한다는 사실을 군수용자에게 알리고, 군수용자가 그 기간이 지날 때까지 처분하지 아니하면 이를 폐기하여야 한다.', 8545);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14805, '① 소장은 법 제27조제1항에 따라 교부를 허가한 금품의 내용이나 용도가 분명하여 검사할 필요가 없다고 인정되는 경우 외에는 군교도관에게 위해성(危害性)이나 안전성 등에 대하여 검사하게 하여야 한다. 이 경우 물품이 의약품인 경우에는 군의관에게 검사하게 하여야 한다.', 8552);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14806, '② 소장은 제1항에 따라 검사를 마친 금품을 영치한 후 사용하게 할 수 있다.', 8552);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14807, '① 소장은 법 제29조에 따라 군수용자가 영치금 사용을 신청한 경우에는 영치금이 정당한 용도에 사용되는지를 확인하고 허가할 수 있다.', 8554);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14808, '② 제1항에 따라 영치금을 사용하는 경우 발생하는 비용은 군수용자가 부담한다.', 8554);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14809, '③ 영치금의 출납, 예탁(預託), 영치금품의 보관 등에 필요한 사항은 국방부장관이 정한다.', 8554);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14810, '① 소장은 거실등과 목욕탕, 취사장, 주식ㆍ부식 저장고, 그 밖에 음식물 공급과 관련된 시설을 수시로 청소ㆍ소독하여야 한다.', 8556);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14811, '② 소장은 저수조(貯水槽) 등 급수시설을 6개월에 1회 이상 청소ㆍ소독하여야 한다.', 8556);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14812, null, 8558);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14813, '① 소장은 법 제35조에 따라 군수용자에 대하여 1년에 1회 이상 건강검진을 하여야 한다. 다만, 계호독거자에 대해서는 6개월에 1회 이상 하여야 한다.', 8560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14814, '② 제1항의 건강검진은 「건강검진기본법」 제14조에 따라 지정된 건강검진기관에 의뢰하여 할 수 있다.', 8560);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14815, '① 소장은 법 제36조에 따라 군수용자가 감염병에 걸렸다고 의심되는 경우에는 1주 이상 격리수용하고, 그의 휴대품을 소독하여야 한다. <개정 2010.12.29>', 8561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14816, '② 소장은 감염병이 유행하고 있을 때에는 군수용자가 자신의 비용으로 구매한 음식물의 공급을 중지할 수 있다. <개정 2010.12.29>', 8561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14817, '③ 소장은 군수용자가 감염병에 걸렸을 때에는 즉시 격리수용하고, 그가 사용하였던 물품과 설비를 철저히 소독하여야 한다. <개정 2010.12.29>', 8561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14818, '④ 제3항의 경우 소장은 군수용자가 감염병에 걸린 사실을 지체 없이 국방부장관에게 보고하고, 관할 보건기관의 장에게 알려야 한다. <개정 2010.12.29>', 8561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14819, '① 소장은 법 제37조에 따라 군수용자가 부상을 당하거나 질병에 걸렸을 때에는 의료용 거실에 수용하거나 다른 군수용자에게 그를 간병(看病)하게 할 수 있다.', 8562);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14820, '② 소장은 특히 필요하다고 인정하면 군병원이 아닌 의료시설(이하 "외부의료시설"이라 한다)에서 근무하는 의사에게 군수용자를 치료하게 할 수 있다.', 8562);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14821, '③ 소장은 군수용자가 위독한 경우에는 그 사실을 가족에게 지체 없이 알려야 한다.', 8562);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14822, '① 소장은 법 제38조제1항에 따라 군수용자를 외부의료시설에서 진료를 받도록 결정하기 전에 미리 군의관의 의견을 들어야 한다.', 8563);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14823, '② 소장은 법 제38조제1항에 따라 군수용자를 외부의료시설에 입원시키거나 입원 중인 군수용자를 군교정시설로 데려왔을 때에는 그 사실을 국방부장관에게 지체 없이 보고하여야 한다.', 8563);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14824, '① 법 제42조제1항에 따른 군수용자의 접견은 매일(공휴일 및 국방부장관이 정한 날은 제외한다) 군 표준일과표에 따른 근무시간에 한다.', 8564);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14825, '② 군수용자의 접견시간은 1회당 30분 이내로 한다. 다만, 군미결수용자가 변호인과 접견하는 경우에는 접견시간을 제한하지 아니한다.', 8564);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14826, '③ 군수형자의 접견 횟수는 매월 4회 이상으로 하되, 제77조제2항에 따라 부여한 처우등급별 접견 횟수는 국방부령으로 정한다.', 8564);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14827, '④ 군수용자의 접견은 접촉 차단시설이 설치된 장소(이하 "접견실"이라 한다)에서 하게 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그러하지 아니하다. <개정 2014.10.28>', 8564);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14828, '⑤ 법 및 이 영에서 규정한 사항 외에 군수형자, 사형확정자 및 군미결수용자 외의 군수용자에 대한 접견 횟수ㆍ시간ㆍ장소 등에 관하여 필요한 사항은 국방부장관이 정한다.', 8564);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14829, '① 소장은 제53조제1항 및 제2항에도 불구하고 군수형자의 교화 또는 건전한 사회복귀를 위하여 특히 필요하다고 인정하면 군 표준일과표에 따른 근무시간 외의 시간에도 접견하게 할 수 있고, 접견시간을 연장할 수 있다.', 8565);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14830, '② 소장은 제53조제3항에도 불구하고 군수형자가 다음 각 호의 어느 하나에 해당하는 경우에는 접견 횟수를 늘릴 수 있다.', 8565);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14831, '③ 소장은 제53조제4항 본문에도 불구하고 군수형자가 제2항 각 호에 해당하는 경우에는 접견실 외의 장소에서 접견하게 할 수 있다.', 8565);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14832, '① 소장은 법 제42조제2항에 따라 접견내용을 청취ㆍ기록하기 위하여 군교도관이나 교도병(군교정시설에서 군교도관의 업무를 보조하는 병을 말한다. 이하 같다)을 접견에 참여하게 할 수 있다. 다만, 군미결수용자가 변호인과 접견하는 경우는 제외한다.', 8567);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14833, '② 소장은 법 제42조제2항 후단에 따라 군수용자와 군수용자가 아닌 사람에게 외국어를 사용하게 할 때에는 군교도관이나 통역인으로 하여금 통역하게 할 수 있다.', 8567);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14834, '③ 소장은 법 제42조제3항에 따라 군수용자와 그 상대방에게 접견실에 들어가기 전에 미리 접견내용을 청취ㆍ녹음 또는 녹화한다는 사실을 말이나 서면 등 적절한 방법으로 알려주어야 한다.', 8567);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14835, '① 소장은 접견내용을 청취ㆍ기록ㆍ녹음 및 녹화한 경우의 접견기록물에 대한 보호ㆍ관리를 위하여 접견정보 취급자를 지정하여야 한다.', 8568);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14836, '② 제1항에 따라 지정된 접견정보 취급자는 직무상 알게 된 접견정보를 누설하거나, 권한 없이 처리하거나, 다른 사람이 이용하도록 제공하는 등 부당한 목적을 위하여 사용해서는 아니 된다.', 8568);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14837, '③ 소장은 다음 각 호의 어느 하나에 해당하는 경우에는 접견기록물을 관계 기관에 제공할 수 있다.', 8568);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14838, '④ 소장은 제3항에 따라 접견기록물을 제공할 때에는 제1항에 따라 지정된 접견정보 취급자에게 접견기록물을 요청한 기관의 명칭, 받으려는 목적, 제공 근거, 제공을 요청한 범위, 그 밖에 필요한 사항을 접견기록물 관리부에 기록하게 하고, 따로 이동식 저장매체에 옮겨 담아 제공하여야 한다.', 8568);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14839, '① 군수용자는 서신을 보내려는 경우 해당 서신을 봉함하여 군교정시설에 제출한다. 다만, 소장은 다음 각 호의 어느 하나에 해당하는 경우로서 법 제44조제3항에 따른 금지물품의 확인을 위하여 필요한 경우에는 서신을 봉함하지 아니한 상태로 제출하게 할 수 있다. <개정 2013.9.26>', 8571);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14840, '② 소장은 군수용자에게 온 서신에 법령에서 금지한 물품이 들어 있는지를 개봉하여 확인할 수 있다.', 8571);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14841, '① 법 제44조제4항제4호에서 "대통령령으로 정하는 군수용자 사이의 서신"이란 다음 각 호의 어느 하나에 해당하는 군수용자가 다른 군수용자와 주고받는 서신을 말한다.', 8572);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14842, '② 군수용자 사이에 오가는 서신에 대한 검열은 서신을 보내는 군교정시설에서 한다. 다만, 특히 필요하다고 인정되는 경우에는 서신을 받는 군교정시설에서도 할 수 있다.', 8572);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14843, '③ 소장은 군수용자가 주고받는 서신이 법 제44조제4항 각 호의 어느 하나에 해당하면 이를 개봉한 후 검열할 수 있다. <신설 2013.9.26>', 8572);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14844, '④ 소장은 제3항에 따라 서신을 검열한 결과 그 내용이 법 제44조제5항의 발신 또는 수신 금지사유에 해당하지 아니하면 발신서신은 봉함한 후 발송하고, 수신서신은 군수용자에게 교부한다. <신설 2013.9.26>', 8572);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14845, '⑤ 소장은 서신의 내용을 검열하였을 때에는 그 사실을 해당 군수용자에게 지체 없이 알려 주어야 한다. <신설 2013.9.26>', 8572);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14846, '① 군수용자는 법 제45조에 따라 전화통화를 허가받으려면 미리 전화번호와 수신자를 지정하여 신청하여야 한다.', 8576);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14847, '② 전화통화는 발신(發信)으로 한정하고, 통화시간은 특별한 사정이 없으면 3분 이내로 한다.', 8576);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14848, '① 법 제45조에 따른 전화통화는 매일(공휴일 및 국방부장관이 정한 날은 제외한다) 군 표준일과표에 따른 근무시간에 할 수 있다.', 8577);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14849, '② 소장은 제1항에도 불구하고 평일에 전화통화가 곤란한 특별한 사유가 있는 군수용자에 대해서는 전화통화 시간을 따로 정할 수 있다.', 8577);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14850, '① 소장은 법 제45조제2항에 따라 전화통화를 허가할 때에는 법 제42조제2항 각 호의 어느 하나에 해당하지 아니한다고 명백히 인정되는 경우 외에는 군수용자의 통화내용을 청취 또는 녹음하는 것을 조건으로 붙여야 한다.', 8578);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14851, '② 소장은 제45조제4항에 따라 군수용자에게 전화통화를 하기 전에 미리 통화내용을 청취하거나 녹음한다는 사실을 말이나 서면 등 적절한 방법으로 알려주어야 한다.', 8578);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14852, '③ 제1항에 따라 녹음한 기록물은 「공공기록물 관리에 관한 법률」에 따라 관리하고, 특히 녹음한 기록물이 손상되지 않도록 그 보존에 주의하여야 한다.', 8578);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14853, '④ 군교도관은 군수용자 전화통화의 청취ㆍ녹음을 통하여 알게 된 내용을 누설하거나, 권한 없이 처리하거나, 타인의 이용에 제공하는 등 부당한 목적으로 사용해서는 아니 된다.', 8578);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14854, '⑤ 제1항에 따라 녹음한 기록물을 관계 기관에 제공하는 것에 관하여는 제57조제3항 및 제4항을 준용한다.', 8578);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14855, '① 군수용자의 전화통화 요금은 군수용자의 부담으로 한다.', 8579);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14856, '② 소장은 군수용자가 교정성적이 양호하거나 영치금이 없는 등 특히 필요하다고 인정하는 경우에는 예산의 범위에서 요금을 부담할 수 있다.', 8579);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14857, '① 소장은 법 제47조에 따라 군수용자가 쉽게 이용할 수 있도록 도서를 갖춰 두고 그 목록을 정기적으로 공개하여야 한다.', 8582);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14858, '② 제1항에 따라 갖춰 둔 도서의 열람방법, 열람기간 등에 관하여 필요한 사항은 국방부장관이 정한다.', 8582);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14859, '① 법 제50조에 따른 집필에 필요한 집필용구는 거실의 집필용구 보관함에 보관하여 관리한다.', 8584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14860, '② 거실에는 집필용구의 품목과 수량을 기록한 집필용구 품목표를 붙여 두어야 한다.', 8584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14861, '③ 집필용구의 구입비용은 군수용자가 부담한다. 다만, 소장은 군수용자가 그 비용을 부담할 수 없는 경우에는 필요한 집필용구를 지급할 수 있다.', 8584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14862, '① 군수용자는 휴업일과 휴게시간에 시간의 제한 없이 집필할 수 있다. 다만, 부득이한 사정이 있는 경우에는 그러하지 아니하다.', 8585);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14863, '② 군수용자는 거실, 작업장, 그 밖에 지정된 장소에서 집필할 수 있다.', 8585);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14864, '① 소장은 군수용자가 자신이 작성하거나 집필한 문서 또는 도화를 외부로 보내거나 내가려고 하는 경우에는 그 내용을 확인하여 법 제44조제5항 각 호의 어느 하나에 해당하지 아니하면 허가하여야 한다.', 8586);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14865, '② 제1항에 따라 문서 또는 도화를 외부로 보내거나 내가는 데에 드는 비용은 군수용자가 부담한다.', 8586);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14866, '③ 법 및 이 영에서 규정한 사항 외에 군수용자의 집필에 필요한 사항은 국방부장관이 정한다.', 8586);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14867, '① 소장은 자유형(自由刑)이 확정된 군미결수용자에 대해서는 군검사의 집행 지휘서가 도달된 때부터 군수형자로 처우하여야 한다. <개정 2022.6.30>', 8587);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14868, '② 군검사는 집행 지휘를 한 날부터 10일 이내에 재판서(裁判書)나 그 밖에 적법한 서류를 소장에게 보내야 한다. <개정 2022.6.30>', 8587);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14869, '① 소장은 법 제51조에 따른 군수형자의 처우를 위하여 개별처우계획을 수립하여야 한다.', 8588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14870, '② 소장은 제1항에 따른 개별처우계획의 시행에 적합하게 정하거나 조정하기 위하여 교정성적에 따라 처우등급을 부여할 수 있다.', 8588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14871, '③ 군수형자에게 부여하는 처우등급에 관하여 필요한 사항은 국방부령으로 정한다.', 8588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14872, '① 소장은 법 제53조에 따른 교육을 효과적으로 시행하기 위하여 교육실을 설치하는 등 교육에 적합한 환경을 조성하여야 한다.', 8590);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14873, '② 소장은 교육 대상자, 시설 여건 등을 고려하여 교육계획을 수립하여 시행하여야 한다.', 8590);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14874, '① 소장은 법 제55조에 따라 군수형자에게 작업을 부과하는 경우에는 작업의 종류와 작업과정을 정하여 알려야 한다.', 8592);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14875, '② 제1항의 작업과정은 작업성적, 작업시간, 작업의 난이도 및 숙련도를 고려하여 정한다. 이 경우 작업과정을 정하기 어려우면 작업시간을 작업과정으로 본다.', 8592);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14876, '③ 군수형자에게 부과하는 작업의 종류, 작업과정 및 작업시간 등의 세부 사항은 국방부령으로 정한다.', 8592);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14877, '① 소장은 법 제66조에 따라 2일 이상의 귀휴(歸休)를 허가하였을 때에는 귀휴를 허가받은 군수형자의 귀휴지(법 제66조제1항에 따라 정한 행선지를 말한다)를 관할하는 군사경찰부대나 국가경찰관서의 장에게 그 사실을 통보하여야 한다. <개정 2020.2.4>', 8597);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14878, '② 귀휴 중인 군수형자는 천재지변이나 그 밖의 사유로 자신의 신상에 중대한 사고가 발생하였을 때에는 가까운 군교정시설, 군사경찰부대 또는 국가경찰관서에 신고하여야 하고, 필요한 보호를 요청할 수 있다. <개정 2020.2.4>', 8597);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14879, '③ 제2항에 따른 보호 요청을 받은 군교정시설, 군사경찰부대 또는 국가경찰관서의 장은 귀휴를 허가한 소장에게 그 사실을 지체 없이 통보하고 적절한 보호조치를 하여야 한다. <개정 2020.2.4>', 8597);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14880, '① 법 제75조제1항에 따른 군미결수용자에 대한 교육ㆍ교화 프로그램이나 작업은 군교정시설 밖에서 실시하거나 부과하지 아니한다.', 8602);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14881, '② 소장은 법 제75조제1항에 따라 작업이 부과된 군미결수용자가 작업의 취소를 요청하는 경우에는 그 군미결수용자의 의사, 건강 및 군교도관의 의견 등을 고려하여 작업을 취소할 수 있다.', 8602);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14882, '① 소장은 사형을 집행하였을 때에는 군의관에게 시신을 검사하게 하여 사망하였음을 확인한 후가 아니면 시신의 이전 등 다른 조치를 하지 못한다. <개정 2014.10.28>', 8608);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14883, '② 사형 집행 시 군검사는 사형확정자의 유언을 기록하고 날인한 후 친족 또는 친지에게 전달하여야 한다. <개정 2022.6.30>', 8608);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14884, '① 군교정시설의 바깥문, 출입구, 거실, 작업장, 그 밖에 군수용자를 수용하고 있는 장소는 외부와 차단하여야 한다. 다만, 필요에 따라 일시 개방하는 경우에는 그 장소를 경비하여야 한다.', 8613);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14885, '② 군교도관은 접견, 상담, 진료, 그 밖에 군수용자의 처우를 위하여 필요한 경우가 아니면 군수용자와 외부인이 접촉하게 해서는 아니 된다.', 8613);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14886, '① 법 제82조제5항 및 제83조제4항에 따라 군의관이 보호실이나 진정실에 수용된 군수용자의 건강을 확인한 결과 보호실이나 진정실에 계속 수용하는 것이 부적당하다고 인정하는 경우에는 소장에게 즉시 보고하여야 한다. 이 경우 소장은 특별한 사유가 없으면 보호실이나 진정실에 수용하는 것을 즉시 중지하여야 한다.', 8616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14887, '② 소장은 군의관이 출장, 휴가, 그 밖의 부득이한 사유로 법 제82조제5항 또는 제83조제4항의 직무를 수행할 수 없을 때에는 군교정시설에 근무하는 의료 관계자에게 그 직무를 대행하게 할 수 있다.', 8616);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14888, '① 군교도관은 소장의 명령 없이 군수용자에게 법 제85조제1항에 따른 보호장비를 사용해서는 아니 된다. 다만, 소장의 명령을 받을 시간적 여유가 없는 경우에는 보호장비를 사용한 후 소장에게 즉시 보고하여야 한다.', 8617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14889, '② 군교도관이 보호장비를 사용할 때에는 군수용자에게 그 사유를 알려주어야 한다.', 8617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14890, '③ 군의관은 군수용자에게 보호장비를 계속 사용하는 것이 건강상 부적당하다고 인정하는 경우에는 소장에게 즉시 보고하여야 한다. 이 경우 소장은 특별한 사유가 없으면 보호장비 사용을 즉시 중지하여야 한다.', 8617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14891, '④ 군의관이 출장, 휴가, 그 밖의 부득이한 사유로 법 제84조제3항의 직무를 수행할 수 없을 때에는 군교정시설에 근무하는 의료관계자에게 그 직무를 대행하게 할 수 있다.', 8617);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14892, '① 소장은 제106조제1항에 따라 보호장비의 사용을 명령한 경우에는 수시로 그 사용 실태를 확인ㆍ점검하여야 한다.', 8619);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14893, '② 국방부장관은 군교정시설의 보호장비 사용 실태를 정기적으로 점검하여야 한다. <개정 2014.10.28>', 8619);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14894, '① 소장은 교정성적이 우수한 군수형자를 선정하여 법 제89조제1항에 따른 응급용무의 보조에 필요한 훈련을 시킬 수 있다.', 8622);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14895, '② 소장은 법 제89조제3항에 따라 군수용자를 일시 석방할 때에는 출석하여야 할 시한과 출석할 장소를 미리 알려주어야 한다.', 8622);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14896, '① 소장은 군수용자가 도주하거나 법 제117조 각 호의 어느 하나에 해당하는 행위(이하 이 조에서 "도주등"이라 한다)를 하였을 때에는 군교정시설의 소재지와 그 인접 지역 또는 도주등을 한 사람(이하 이 조에서 "도주자등"이라 한다)이 숨을 만한 지역의 군사경찰부대나 국가경찰관서에 도주자등의 사진이나 인상착의를 기록한 서면을 첨부하여 그 사실을 지체 없이 통보하여야 한다. <개정 2020.2.4>', 8623);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14897, '② 소장은 군수용자가 도주등을 하거나 도주자등을 체포한 경우에는 국방부장관에게 지체 없이 보고하여야 한다.', 8623);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14898, null, 8624);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14899, '① 위원회의 외부인사인 위원은 다음 각 호의 어느 하나에 해당하는 사람 중에서 소장이 위촉한다. <개정 2012.2.29>', 8625);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14900, '② 제1항에 따라 위촉된 위원의 임기는 2년으로 한다.', 8625);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14901, '③ 소장은 제1항에 따라 위촉된 위원이 직무를 게을리하거나, 품위를 손상하였거나, 특정한 종파나 특정한 사상에 치우쳐 징벌의 공정성을 해칠 우려가 있다고 인정되면 그 위원을 해촉할 수 있다.', 8625);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14902, '① 위원장은 위원회를 대표하고, 위원회의 업무를 총괄한다.', 8626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14903, '② 위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 위원장이 미리 지명한 위원이 그 직무를 대행한다.', 8626);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14904, '① 위원회에 위원회의 사무를 처리할 간사 1명을 둔다.', 8627);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14905, '② 간사는 군교도관 중에서 소장이 임명한다.', 8627);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14906, '① 소장은 법 제98조에 따라 위원회가 의결한 징벌을 지체 없이 집행하여야 한다.', 8630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14907, '② 소장은 군수용자에 대하여 법 제94조제9호의 전화통화 제한, 같은 조 제11호의 서신수수 제한 또는 같은 조 제12호의 접견 제한 징벌을 부과하였을 때에는 군수용자의 가족에게 그 사실을 알려야 한다. 다만, 군수용자가 통지를 원하지 아니하면 그러하지 아니하다.', 8630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14908, '③ 소장은 법 제94조제14호의 금치(禁置) 징벌을 집행할 때에도 군수용자의 기본적인 건강유지를 위하여 필요하다고 인정하면 실외운동을 허가할 수 있다.', 8630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14909, '④ 소장은 법 제98조제13호의 실외운동 정지나 같은 조 제14호의 금치 징벌의 집행을 마쳤을 때에는 군의관에게 해당 군수용자의 건강 상태를 지체 없이 확인하게 하여야 한다.', 8630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14910, '⑤ 군의관이 출장, 휴가, 그 밖의 부득이한 사유로 법 제98조제4항이나 이 조 제4항의 직무를 수행할 수 없을 때에는 군교정시설에 근무하는 의료 관계자에게 그 직무를 대행하게 할 수 있다.', 8630);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14911, '① 소장은 법 제101조제1항에 따라 군수용자가 면담을 신청하였을 때에는 군수용자의 인적사항을 면담부에 적고, 특별한 사정이 없으면 신청한 순서에 따라 면담하여야 한다.', 8635);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14912, '② 소장은 제1항에 따라 군수용자를 면담하였을 때에는 그 요지를 면담부에 적어야 한다.', 8635);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14913, '③ 소장은 법 제101조제2항 각 호의 어느 하나에 해당하여 군수용자의 면담 신청을 받아들이지 아니하였을 때에는 그 사유를 해당 군수용자에게 알려주어야 한다.', 8635);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14914, '① 소장은 군수용자가 법 제102조제1항에 따라 순회점검공무원(법 제7조에 따라 국방부장관으로부터 순회점검의 명을 받은 공무원을 말한다. 이하 같다)에게 청원하는 경우에는 그 인적사항을 청원부에 기록하여야 한다. <개정 2014.10.28>', 8636);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14915, '② 순회점검공무원은 법 제102조제2항 단서에 따라 군수용자가 말로 청원하는 경우에는 그 요지를 청원부에 기록하여야 한다. <개정 2014.10.28>', 8636);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14916, '③ 순회점검공무원은 법 제102조에 따른 군수용자의 청원에 대하여 결정하였을 때에는 그 요지를 청원부에 기록하여야 한다. <개정 2014.10.28>', 8636);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14917, '④ 순회점검공무원은 법 제102조에 따른 군수용자의 청원에 대하여 스스로 결정하는 것이 부적당하다고 인정하는 경우에는 그 내용을 국방부장관에게 보고하여야 한다. <개정 2014.10.28>', 8636);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14918, '⑤ 군수용자의 청원 처리의 기준ㆍ절차 등에 관하여 필요한 사항은 국방부장관이 정한다.', 8636);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14919, null, 8637);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14920, '① 군의관은 군수용자가 질병으로 사망한 경우에는 사망기록부에 병명, 병력(病歷), 사인 및 사망 일시를 기록하고 서명하여야 한다.', 8645);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14921, '② 소장은 군수용자가 자살하거나 변사(變事)한 경우에는 그 사실을 즉시 군검사(기소된 군수용자인 경우에는 군사법원을 포함한다)에게 통보하고, 그 시신을 검사한 후 사망기록부에 검시자와 참여자의 성명, 신분 및 검시 결과를 기록하여야 한다. <개정 2014.10.28, 2022.6.30>', 8645);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14922, '③ 소장은 법 제78조에 따라 사형을 집행하였을 때에는 사망기록부에 집행일시, 집행장소, 검시자와 참여자의 성명 및 유언이 있었는지를 기록하여야 한다.', 8645);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14923, '④ 소장은 법 제113조에 따라 시신을 인도(引渡)하거나, 화장(火葬), 임시 매장 또는 합장(合葬)한 경우에는 그 사실을 사망기록부에 기록하여야 한다.', 8645);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14924, '① 소장은 법 제113조제2항 단서에 따라 시신을 화장하였을 때에는 유골을 인수할 사람이 없으면 임시 매장하고, 임시 매장 후 2년이 지나도 인도를 청구하는 사람이 없으면 합장할 수 있다.', 8646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14925, '② 소장은 법 제113조제3항에 따라 시신을 화장한 경우에는 그 유골을 합장할 수 있다.', 8646);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14926, '① 소장은 법 제113조제2항에 따라 시신을 임시 매장한 경우에는 그 장소에 사망자의 가족관계등록기준지, 성명, 사망 일시를 적은 표지를 세워야 한다.', 8647);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14927, '② 소장은 법 제113조제3항에 따라 시신 또는 유골을 합장한 경우에는 합장된 사람의 가족관계등록기준지, 성명, 사망 일시를 합장기록부에 기록하고 그 장소에 묘비를 세워야 한다.', 8647);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14928, '① 소장은 군수용자의 안정된 수용생활과 교화를 위하여 법 제114조에 따른 교정위원에게 군수용자를 교화상담하게 할 수 있다.', 8648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14929, '② 교정위원은 군수용자의 고충 처리나 교정ㆍ교화를 위하여 필요한 의견을 소장에게 건의할 수 있다.', 8648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14930, '① 소장은 법 제115조에 따라 기부금품을 접수하였을 때에는 기부금품 접수대장에 등록하고, 기부한 기관, 단체 또는 개인(이하 이 조에서 "기부자"라 한다)에게 영수증을 발급하여야 한다. 다만, 익명으로 기부하거나 기부자를 알 수 없는 경우에는 영수증을 발급하지 아니한다.', 8649);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14931, '② 소장은 기부자가 용도를 지정하여 금품을 기부한 경우에는 기부금품을 그 용도에 사용하여야 한다. 다만, 지정한 용도로 사용하기 어려운 특별한 사유가 있는 경우에는 기부자의 동의를 받아 다른 용도로 사용할 수 있다.', 8649);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14932, '③ 소장은 기부금품 접수대장과 기부금품의 사용결과를 기록한 장부를 갖춰 두고, 기부자가 열람할 수 있도록 하여야 한다.', 8649);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14933, '④ 제1항부터 제3항까지에서 규정한 사항 외에 군교정시설의 기부금품 접수ㆍ사용 등에 필요한 사항은 국방부장관이 정한다.', 8649);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14934, '① 국방부장관은 법 제115조의2에 따라 다음 각 호의 업무에 관한 권한을 각 군의 참모총장에게 위임한다.', 8650);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14935, '② 국방부장관은 법 제115조의2에 따라 다음 각 호의 업무에 관한 권한을 국방부조사본부장에게 위임한다.', 8650);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14936, null, 8652);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14937, '① 군교도관은 직무를 신속ㆍ정확ㆍ공정하게 처리하고, 그 결과를 지체 없이 상관에게 문서 또는 구두로 보고하여야 한다. 다만, 상관으로부터 특별히 명령받은 직무로서 그 직무처리에 많은 시일이 걸리는 경우에는 그 중간 처리상황을 보고하여야 한다.', 8653);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14938, '② 군교도관은 직무수행 중 다음 각 호의 사유가 발생하면 즉시 소장에게 보고하고 그 지시에 따라 필요한 조치를 하여야 한다.', 8653);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14939, '① 군교도소의 교정업무에 관한 중요사항을 심의하기 위하여 군교도소에 군교도관회의를 둔다.', 8656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14940, '② 제1항에 따른 군교도관회의는 소장, 부소장, 과장급 직원 및 군교도관 중에서 소장이 임명하는 4명 이상 10명 이하의 군교도관으로 구성한다.', 8656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14941, '③ 소장은 군교도관회의를 소집하고, 그 의장이 된다.', 8656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14942, '④ 군교도관회의는 구성원 과반수의 출석으로 개의(開議)하고, 출석위원 과반수의 찬성으로 의결한다.', 8656);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14943, '① 법 제22조에 따라 군수용자에게 지급하는 의류의 품목은 수용복, 전투복, 체육복, 고무신 및 활동화로 한다.', 8657);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14944, '② 제1항에 따른 의류의 지급수량, 지급횟수 등에 대한 기준은 「군복 및 군일용품 지급규정」에 따른 현역 군인의 의류지급기준에 따른다.', 8657);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14945, '① 법 제22조에 따라 군수용자에게 지급하는 침구의 품목은 이불, 매트리스, 담요 및 베개로 한다.', 8658);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14946, '② 제1항에 따른 침구는 1명당 1매로 한다.', 8658);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14947, '③ 법 제22조에 따라 군수용자에게 지급하는 생활용품의 품목, 지급수량, 지급횟수 등에 대한 기준은 「군복 및 군일용품 지급규정」에 따른 현역 군인의 생활용품의 지급기준에 따른다.', 8658);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14948, '① 자비구매물품은 군교정시설이나 부대 내에서 판매하는 것으로 하며, 종류는 다음 각 호와 같다.', 8661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14949, '② 국방부장관은 자비구매물품 공급의 군교정시설 간 균형 및 군교정시설의 안전과 질서유지를 위하여 필요한 경우에 공급물품의 품목 및 규격 등에 대한 통일된 기준을 정할 수 있다.', 8661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14950, '③ 제1항 각 호에 해당하는 자비구매물품의 품목, 유형 및 규격 등에 관한 세부사항은 제2항 및 영 제31조의 기준에 어긋나지 아니하는 범위에서 수용생활에 필요한 정도, 가격과 품질, 다른 군교정시설과의 균형, 공급의 용이성 및 군수용자의 선호도 등을 고려하여 소장이 정한다.', 8661);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14951, '① 소장은 군수용자가 자비구매물품의 구매를 신청하는 경우에는 군교정시설의 보관범위 및 군수용자의 소지범위에서 다음 각 호의 구분에 따라 허가할 수 있다.', 8662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14952, '② 소장은 감염병(「감염병의 예방 및 관리에 관한 법률」에 따른 감염병을 말한다)의 유행 또는 군수용자의 징벌 집행 등으로 자비구매물품의 사용이 중지된 경우에는 구매신청을 제한할 수 있다. <개정 2014.11.3>', 8662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14953, '① 소장은 물품공급업무 담당자를 검수관(檢收官)으로 지정하여 자비구매물품 공급자로부터 납품받은 제품의 수량, 상태 및 유통기한 등을 검사하게 하여야 한다.', 8664);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14954, '② 검수관은 공급제품이 부패, 파손, 규격 미달, 그 밖의 사유로 군수용자에게 공급하기에 적당하지 아니하다고 인정하는 경우에는 소장에게 보고하고 필요한 조치를 하여야 한다.', 8664);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14955, '① 소장은 군수용자에게 자비구매물품의 품목ㆍ가격, 그 밖의 구매에 관한 주요사항을 미리 알려주어야 한다.', 8665);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14956, '② 소장은 제품의 변질ㆍ파손, 그 밖의 정당한 사유로 군수용자가 교환 또는 반품을 원하는 경우에는 신속히 적절한 조치를 하여야 한다.', 8665);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14957, '① 소장은 법 제27조에 따라 군수용자 외의 사람이 군수용자에게 금품을 교부하려고 신청하는 경우에는 현금ㆍ수표 및 우편환의 범위에서 허가한다. <개정 2020.2.3>', 8666);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14958, '② 소장은 법 제27조에 따라 군수용자 외의 사람이 군수용자에게 음식물을 교부하려고 신청하는 경우에는 군교정시설에서 판매하는 음식물 중에서 허가한다.', 8666);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14959, '③ 소장은 법 제27조에 따라 군수용자 외의 사람이 군수용자에게 음식물 외의 물품을 교부하려고 신청하는 경우 그 물품이 다음 각 호의 어느 하나에 해당하지 아니하면 군교정시설의 보관범위 및 군수용자의 소지범위에서 허가한다.', 8666);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14960, '① 군교정시설에는「의료법」 제3조에 따른 의료기관 중 의원(醫院)이 갖추어야 하는 시설 이상의 의료시설(진료실 등의 의료용 건축물을 말한다. 이하 같다)을 갖추어야 한다. 다만, 즉시 접근이 가능한 군부대 내에 의료시설을 갖춘 경우는 그러하지 아니하다.', 8667);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14961, '② 군교정시설에 갖춰 둬야 하는 의료장비(혈압측정기 등의 의료기기를 말한다)의 기준은 별표 1과 같다.', 8667);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14962, '③ 의료시설의 세부종류 및 설치기준은 국방부장관이 정한다.', 8667);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14963, '① 소장은 수용정원과 시설여건 등을 고려하여 적정한 양의 비상의료용품을 갖추어야 한다.', 8668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14964, '② 제1항에 따라 군교정시설에 갖춰 둬야 하는 비상의료용품의 기준은 별표 2와 같다.', 8668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14965, null, 8669);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14966, '① 소장은 군교정시설의 안전과 질서를 해치지 아니하는 범위에서 종교단체 또는 종교인이 주관하는 종교행사를 실시한다.', 8670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14967, '② 소장은 종교행사를 위하여 종교별 성상ㆍ성물ㆍ성화ㆍ성구가 구비된 종교관(종교행사를 할 수 있는 종교상담실ㆍ교리교육실 등을 말한다. 이하 같다)을 설치할 수 있으며, 특정 종교행사를 위하여 임시행사장을 설치하는 경우에는 성상 등을 임시로 둘 수 있다.', 8670);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14968, null, 8671);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14969, '① 소장은 군수용자가 종교상담을 신청하거나 군수용자에게 종교상담이 필요한 경우에는 해당 종교를 신봉하는 군교도관 또는 교정참여인사로 하여금 상담하게 할 수 있다.', 8672);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14970, '② 소장은 제1항에 따른 종교상담의 중요 내용을 기록하여 군수용자 처우에 활용할 수 있다. 이 경우 군수용자의 개인정보가 유출되지 아니하도록 하여야 한다.', 8672);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14971, null, 8673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14972, null, 8675);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14973, '① 군수용자를 대상으로 하는 방송은 무상으로 한다.', 8677);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14974, '② 국방부장관은 방송의 전문성을 강화하기 위하여 외부전문가의 협력을 구할 수 있고, 모든 군교정시설의 군수용자를 대상으로 하는 통합방송을 할 수 있다.', 8677);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14975, '③ 소장은 방송에 대한 의견 수렴을 위하여 설문조사 등의 방법으로 군수용자의 반응도 및 만족도를 측정할 수 있다.', 8677);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14976, '① 소장은 방송을 위하여 텔레비전, 비디오카세트레코더(VCR), 앰프, 스피커 등의 장비와 방송선로 등의 시설을 갖추어야 한다.', 8678);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14977, '② 소장은 물품관리법령에 따라 제1항의 장비와 시설을 정상적으로 유지ㆍ관리하여야 한다.', 8678);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14978, '① 소장은 「방송법」 제2조의 텔레비전방송 또는 라디오방송을 생방송하거나 이를 녹음ㆍ녹화한 것을 방송할 수 있으며, 비디오테이프에 의한 영상물 또는 자체 제작한 영상물을 방송할 수 있다.', 8680);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14979, '② 방송프로그램은 그 내용에 따라 다음 각 호와 같이 구분한다.', 8680);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14980, '③ 소장은 방송프로그램을 자체 편성하는 경우 다음 각 호의 어느 하나에 해당하는 내용이 포함되지 아니하도록 특히 유의하여야 한다.', 8680);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14981, '① 군수용자는 소장이 지정한 장소에서 텔레비전을 시청하거나 라디오방송을 청취를 하여야 한다.', 8681);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14982, '② 군수용자는 방송설비 또는 채널을 마음대로 조작ㆍ변경하거나 개인적으로 방송 수신 장비를 소지해서는 아니 된다.', 8681);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14983, '③ 군수용자가 군교정시설에 설치된 방송시설과 장비를 손상하거나 그 밖의 방법으로 그 효용을 해친 경우에는 이를 배상하여야 한다.', 8681);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14984, null, 8682);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14985, null, 8684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14986, '① 정기심사는 영 제76조에 따라 군수형자의 처우가 개시된 날부터 다음 각 호의 구분에 따른 기간마다 실시한다.', 8685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14987, '② 정기심사는 제1항 각 호에 해당하는 날이 해당 월 15일 이전에 속한 경우에는 그 달 25일까지, 해당 월 15일 이후에 속한 경우에는 그 다음달 10일까지 하여야 한다.', 8685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14988, '③ 정기심사일과 제35조에 따른 형기의 3분의 1 심사일이 같을 때에는 형기의 3분의 1 심사를 정기심사에 갈음한다.', 8685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14989, '④ 정기심사 기간에 제35조에 따른 형기의 3분의 1 심사 또는 제36조에 따른 특별심사를 하였을 때에는 그 심사일부터 제1항에 따른 정기심사의 기간을 계산한다.', 8685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14990, null, 8686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14991, '① 특별심사는 다음 각 호의 어느 하나에 해당하는 경우에 실시한다.', 8687);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14992, '② 특별심사 대상자는 군교도관회의에서 결정한다.', 8687);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14993, null, 8688);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14994, '① 군교도소에 처음으로 입소한 군수형자의 처우등급은 4급으로 하고, 차례로 상위등급으로 승급시킨다.', 8690);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14995, '② 법 제93조에 따른 징벌을 받은 군수형자에 대해서는 그 정상(情狀)에 따라 처우등급을 1등급 이상 강등시킬 수 있다.', 8690);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14996, '③ 제2항에 따라 강등된 군수형자에 대해서는 징벌기간이 만료된 날부터 제34조에 따른 정기심사 기간을 계산한다.', 8690);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14997, '① 소장은 군수형자에 대하여 처우등급 심사를 하였을 때에는 별지 제2호서식의 처우등급심사표를 작성ㆍ관리하여야 한다.', 8692);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14998, '② 소장은 군수형자를 다른 교도소로 이송할 때에는 제1항에 따른 처우등급심사표를 그 군수형자가 이송되는 교도소의 소장에게 송부하여야 한다.', 8692);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (14999, '① 소장은 형의 집행정지 중에 있는 사람이 기간만료 그 밖의 정지사유 소멸로 재수용된 경우에는 석방 당시와 동일한 처우등급을 부여한다.', 8694);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15000, '② 소장은 가석방 취소로 재수용되어 남은 형이 집행되는 경우에는 석방 당시보다 한 단계 낮은 처우등급을 부여한다. 다만, 특히 고려할 만한 사유가 있는 때에는 석방 당시와 동일한 처우등급을 부여할 수 있다. <개정 2020.2.3>', 8694);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15001, '① 소장은 처우등급 2급 이상의 군수형자 중 교정성적, 나이, 인성 등을 고려하여 다른 군수형자의 모범이 된다고 인정되는 사람을 봉사원으로 선정하여 담당 군교도관의 사무처리 그 밖의 업무를 보조하게 할 수 있다.', 8697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15002, '② 봉사원의 활동기간은 6개월로 하되, 필요한 경우에는 그 기간을 1회 연장할 수 있다.', 8697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15003, '③ 소장은 봉사원의 활동과 역할수행이 적당하지 아니하다고 인정하는 경우에는 선정을 취소할 수 있다.', 8697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15004, '④ 봉사원의 선정, 기간연장 및 선정취소에 관한 사항은 군교도관회의 의결로 정한다.', 8697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15005, '① 소장은 군수용자의 처우를 위하여 필요하다고 인정되면 처우등급 2급 이상의 군수형자에게 자치생활을 하게 할 수 있다. 다만, 처우상 특히 필요한 경우에는 처우등급 3급 이하의 군수형자를 포함할 수 있다.', 8698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15006, '② 제1항에 따른 자치생활의 범위는 인원 점검, 취미활동, 일정한 구역에서의 생활 등으로 한다.', 8698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15007, '③ 소장은 제1항에 따라 자치생활을 하는 군수형자들이 교육실ㆍ강당 등 적당한 장소에서 월 1회 이상 토론회를 할 수 있도록 하여야 한다.', 8698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15008, '④ 소장은 군수형자가 국방부장관 또는 소장이 정하는 자치생활에 관한 준수사항을 위반한 경우에는 자치생활의 허가를 취소할 수 있다.', 8698);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15009, null, 8699);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15010, '① 소장은 군수형자의 교정ㆍ교화와 사회생활 적응 능력을 기르도록 처우하기 위하여 군교정시설에 수용시설과 별도로 군수형자와 그 가족이 숙식을 함께할 일반주택 형태의 건축물(이하 "가족 만남의 집"이라 한다)을 설치할 수 있고, 군수형자와 그 가족이 군교정시설 내의 일정한 장소에서 다과와 음식을 함께 나누면서 대화의 시간을 갖는 행사(이하 "가족 만남의 날 행사"라 한다)를 할 수 있다.', 8701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15011, '② 소장은 처우등급 2급 이상의 군수형자에 대하여 가족 만남의 집을 이용하게 하거나 가족 만남의 날 행사에 참여하게 할 수 있다. 이 경우 제48조에 따른 접견 허용횟수에는 포함하지 아니한다.', 8701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15012, '③ 소장은 가족이 없는 군수형자에 대해서는 자매결연자 또는 후원자 등에게 가족을 대신하여 가족 만남의 날 행사에 참여하게 할 수 있다.', 8701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15013, '④ 소장은 제2항 전단에도 불구하고 교화를 위하여 특히 필요한 경우에는 처우등급 3급 이하의 군수형자에게도 가족 만남의 집 이용이나 가족 만남의 날 행사에 참여하도록 할 수 있다.', 8701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15014, '① 군수형자의 처우등급별 전화통화의 허용횟수는 다음 각 호와 같다.', 8702);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15015, '② 소장은 제1항에도 불구하고 처우상 특히 필요한 경우에는 처우등급 2급 이상 군수형자의 전화통화 허용횟수를 늘릴 수 있으며, 처우등급 3급 이하 군수형자에게도 전화통화를 허가할 수 있다.', 8702);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15016, '① 소장은 처우등급 2급 이상인 군수형자 중에서 작업기술이 탁월하고 작업성적이 우수한 군수형자에게 자신을 위한 개인작업을 하게 할 수 있다. 이 경우 개인작업 시간은 교도작업에 지장을 주지 아니하는 범위에서 1일 2시간 이내로 한다.', 8704);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15017, '② 소장은 제1항에 따라 개인작업을 하는 군수형자에게 개인작업 용구를 사용하게 할 수 있다. 이 경우 작업용구는 특정한 용기에 보관하도록 하여야 한다.', 8704);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15018, '③ 개인작업에 필요한 작업재료 등의 구입비용은 군수형자가 부담한다. 다만, 처우상 필요한 경우에는 예산의 범위에서 그 비용을 지원할 수 있다.', 8704);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15019, '① 소장은 처우등급 2급 이상인 군수형자 중에서 직업능력 향상을 위하여 특히 필요하다고 인정하는 경우에는 군교정시설 외의 공공기관 또는 기업체 등에서 운영하는 직업훈련을 받게 할 수 있다.', 8705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15020, '② 제1항에 따른 직업훈련의 비용은 군수형자가 부담한다. 다만, 처우상 특히 필요한 경우에는 예산의 범위에서 그 비용을 지원할 수 있다.', 8705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15021, '① 소장은 법 제53조제1항 및 제2항에 따른 교육대상자를 각 교육과정의 교육계획, 교육시설의 규모, 교육대상인원과 군수형자의 나이, 학력, 교정성적, 자체 평가시험 성적, 정신자세, 성실성 등을 고려하여 선발하여야 한다.', 8706);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15022, '② 소장은 군수형자가 정당한 이유 없이 법 제53조에 따른 교육을 기피하였거나 교육기관에서 자퇴(제적을 포함한다)한 사실이 있을 때에는 교육대상자로 선발하지 아니할 수 있다.', 8706);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15023, '① 소장은 교육대상자가 다음 각 호의 어느 하나에 해당하는 경우에는 교육대상자 선발을 취소할 수 있다.', 8707);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15024, '② 소장은 교육대상자가 질병에 걸리거나 부상을 당한 경우, 그 밖의 부득이한 사정이 있는 경우에는 교육과정을 일시 중지할 수 있다.', 8707);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15025, null, 8708);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15026, '① 소장은 다음 각 호의 시험을 준비하는 군수형자 중 제59조제2항 각 호의 요건을 갖춘 사람을 대상으로 검정고시반을 설치ㆍ운영할 수 있다.', 8709);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15027, '② 소장은 교육기간에 검정고시에 합격한 군수형자에 대하여 해당 교육과정을 조기 수료시키거나 상위 교육과정에 임시 배치시킬 수 있다.', 8709);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15028, '① 소장은 고등학교과정의 교육기회를 부여하기 위하여 「초ㆍ중등교육법」 제51조에 따른 방송통신고등학교 교육과정을 설치ㆍ운영할 수 있다.', 8710);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15029, '② 소장은 다음 각 호의 요건을 갖춘 군수형자가 방송통신고등학교 교육과정에 지원하여 합격한 경우에는 교육생으로 선발할 수 있다.', 8710);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15030, '③ 제1항의 교육에 필요한 비용은 자비부담을 원칙으로 한다. 다만, 소장은 제1항의 방송통신고등학교 교육과정의 입학금, 수업료, 교과용 도서구입비 등 교육에 필요한 비용을 예산 범위에서 지원할 수 있다.', 8710);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15031, '① 군사교육훈련은 정신교육, 제식훈련 등 기본군사훈련을 위주로 실시한다.', 8712);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15032, '② 소장은 군사교육훈련이 군수형자에 대한 징벌수단, 보복조치로 악용되지 않도록 주의하여야 한다.', 8712);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15033, '① 소장은 교육ㆍ훈련기간 중 각 교육과목에 대한 성적평가를 위하여 시험 또는 교육사열(敎育査閱)을 실시하여야 한다.', 8716);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15034, '② 소장은 시험 또는 교육사열 결과 성적이 불량하여 교육ㆍ훈련의 효과를 거두지 못하였다고 인정되는 군수형자에 대해서는 다시 교육ㆍ훈련을 실시할 수 있다.', 8716);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15035, '③ 소장은 군사교육훈련과정 외 교육과정에서 성적이 현저히 불량한 군수형자에 대하여 해당 교육과정을 중단시킬 수 있다.', 8716);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15036, null, 8720);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15037, '① 소장은 군수형자와 그 가족의 관계를 유지ㆍ회복하기 위하여 군수형자의 가족이 참여하는 각종 프로그램을 실시할 수 있다. 다만, 가족이 없는 군수형자의 경우 교화를 위하여 필요하면 결연을 맺은 사람이나 그 밖에 가족에 준하는 사람의 참여를 허가할 수 있다.', 8723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15038, '② 제1항에 따른 가족관계 회복프로그램의 대상이 되는 군수형자는 제50조에 따라 가족 만남의 집을 이용하거나 가족 만남의 날 행사에 참여할 수 있는 사람을 대상자로 하여 군교정시설 안에서 실시하며, 참여인원은 5명 이내의 가족으로 한다. 다만, 특히 필요하다고 인정하는 경우에는 참여인원을 늘릴 수 있다.', 8723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15039, '① 소장은 군수형자의 건전한 가치관 형성, 정서안정, 고충 해소 등을 위하여 교화상담을 실시할 수 있다.', 8724);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15040, '② 소장은 제1항에 따른 교화상담을 위하여 군교도관이나 교정참여인사를 교화상담자로 지정할 수 있고, 군수형자의 안정을 위하여 결연을 주선할 수 있다.', 8724);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15041, '① 소장은 교화프로그램을 운영하는 경우에 성폭력, 약물중독, 정신질환 등 군수형자의 개별 특성을 고려하여야 하며, 프로그램의 성격 및 시설의 규모와 인원을 고려하여 이송 등의 적절한 조치를 할 수 있다.', 8725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15042, '② 소장은 교화프로그램의 운영을 위하여 군수형자의 정서적인 안정이 보장될 수 있는 장소를 따로 정하거나 방송설비 및 방송기기를 이용할 수 있다.', 8725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15043, '③ 소장은 교화프로그램의 주요 진행내용을 기록하여 군수형자 처우에 활용하여야 하며, 상담내용 등 개인정보가 유출되지 아니하도록 하여야 한다.', 8725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15044, '① 영 제81조제3항에 따른 작업의 종류는 군납물품 생산 및 관용작업으로 한다.', 8726);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15045, '② 영 제81조제3항에 따른 작업시간은 1일 8시간 이하로 한다.', 8726);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15046, '③ 제1항에 따른 작업의 구체적인 내용은 국방부조사본부장의 승인을 받아 소장이 정한다. <개정 2014.11.3>', 8726);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15047, '① 소장은 작업실적ㆍ작업시간을 참작하여 작업에 종사한 군수형자에게 작업등급을 부여하여야 한다.', 8728);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15048, '② 제1항에 따른 작업등급은 다음 각 호의 구분에 따른다.', 8728);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15049, '③ 소장은 작업성적 및 품행이 특히 우수하다고 인정되는 군수형자에 대해서는 제2항 각 호에 규정된 작업기간의 2분의 1 이상을 종사하였을 때에 바로 상위의 작업등급을 부여할 수 있다.', 8728);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15050, '① 법 제58조제2항에 따른 외부통근자의 선정기준은 다음 각 호와 같다.', 8729);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15051, '② 소장은 제1항에도 불구하고 작업의 성격이나 교화를 위하여 특히 필요하다고 인정하는 경우에는 제1항의 군수형자 외의 군수형자도 외부통근자로 선정할 수 있다.', 8729);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15052, '① 법 제59조에 따른 기술 습득 및 향상을 위한 직업능력개발훈련(이하 "직업훈련"이라 한다)의 직종 선정 및 훈련과정별 인원은 국방부조사본부장의 승인을 받아 소장이 정한다. <개정 2014.11.3>', 8734);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15053, '② 직업훈련 대상자는 소속 기관의 군수형자 중에서 소장이 선정한다.', 8734);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15054, null, 8735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15055, null, 8736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15056, '① 국방부장관은 직업훈련을 위하여 필요한 경우에는 군수형자를 다른 군교정시설로 이송할 수 있다.', 8737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15057, '② 소장은 제1항에 따라 이송된 군수형자나 직업훈련 중인 군수형자를 다른 군교정시설로 이송해서는 아니 된다. 다만, 훈련 취소 등 특별한 사유가 있는 경우에는 그러하지 아니하다.', 8737);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15058, '① 소장은 직업훈련 대상자가 다음 각 호의 어느 하나에 해당하는 경우에는 직업훈련을 보류할 수 있다.', 8738);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15059, '② 소장은 제1항에 따라 직업훈련이 보류된 군수형자의 보류 사유가 소멸된 경우에는 본래의 과정에 복귀시켜 훈련할 수 있게 하여야 한다. 다만, 본래 과정으로 복귀시키는 것이 적당하지 아니하다고 인정되는 경우에는 해당 훈련을 취소할 수 있다.', 8738);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15060, '① 법 제66조제1항제4호에서 "교화나 건전한 사회복귀를 위하여 국방부령으로 정하는 사유"란 다음 각 호의 어느 하나에 해당하는 사유를 말한다.', 8739);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15061, '② 소장은 처우등급 2급 이상인 군수형자에 한정하여 법 제66조에 따라 귀휴를 허가할 수 있다. 다만, 교정ㆍ교화 또는 사회복귀 준비 등을 위하여 특히 필요한 경우에는 처우등급 3급의 군수형자에게도 귀휴를 허가할 수 있다.', 8739);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15062, '① 소장은 법 제66조에 따라 귀휴를 허가할 때에는 제90조의 귀휴심사위원회의 심사를 거쳐야 한다.', 8740);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15063, '② 제1항에도 불구하고 소장은 토요일, 공휴일 그 밖의 사유로 귀휴심사위원회의 소집이 곤란할 때에는 귀휴심사위원회 심사를 거치지 아니하고 귀휴를 허가할 수 있다. 다만, 이 경우 다음 각 호에 해당하는 부서의 장의 의견을 들어야 한다.', 8740);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15064, '③ 제2항 각 호에 해당하는 부서의 장은 제97조의 서류를 검토하여 그 의견을 지체 없이 소장에게 보고하여야 한다.', 8740);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15065, null, 8742);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15066, '① 위원회는 위원장 1명을 포함한 5명 이상 7명 이하의 위원으로 구성한다.', 8743);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15067, '② 위원회의 위원장은 소장이 되고, 위원회의 위원은 소장이 소속 군교도관과 교정에 관한 학식과 경험이 풍부한 사람 중에서 임명하거나 위촉한다. 이 경우 위촉위원은 2명 이상으로 한다.', 8743);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15068, '① 위촉위원의 임기는 2년으로 한다.', 8744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15069, '② 위원장은 위촉위원이 다음 각 호의 어느 하나에 해당하는 경우에는 위촉을 해제할 수 있다.', 8744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15070, '③ 위촉위원에 대해서는 예산의 범위에서 수당과 여비를 지급할 수 있다.', 8744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15071, '① 위원장은 위원회를 대표하고, 위원회의 업무를 총괄한다.', 8745);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15072, '② 위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 위원장이 미리 지명한 위원이 그 직무를 대행한다.', 8745);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15073, '① 위원장은 위원회의 회의를 소집하고, 그 의장이 된다.', 8746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15074, '② 위원회의 회의는 재적위원 과반수의 출석으로 개의(開議)하고, 출석위원 과반수의 찬성으로 의결한다.', 8746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15075, '① 위원회에 위원회의 사무를 처리할 간사 1명을 둔다.', 8747);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15076, '② 간사는 소속 군교도관 중에서 소장이 임명한다.', 8747);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15077, '③ 간사는 별지 제6호서식의 귀휴심사위원회 회의록을 작성하여 보관하여야 한다.', 8747);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15078, '① 귀휴심사에 필요한 서류는 다음 각 호와 같다.', 8748);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15079, '② 소장은 심사대상자에게 별지 제9호서식의 지도보증서를 위원회에 제출하게 하여야 한다. 이 경우 법 제66조제1항제1호부터 제3호까지의 사유에 해당하는 군수형자에 대해서는 별지 제10호서식의 사실확인서를 같이 제출하도록 하여야 한다.', 8748);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15080, '① 소장은 심사대상자의 심사에 필요한 경우에는 군수용자의 가족 등을 면담하거나 군사법원, 군검찰부, 헌병부대 그 밖의 관계 기관이나 단체에 대하여 필요한 사실조회를 할 수 있다.', 8749);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15081, '② 소장은 심사대상자의 보호관계 등을 알아보는 데 필요하다고 인정하는 경우에는 그의 가족 또는 보호관계에 있는 사람에게 위원회의 참석을 요청할 수 있다.', 8749);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15082, null, 8752);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15083, '① 소장은 법 제66조제3항에 따라 군수형자에게 귀휴를 허가하는 경우 필요하다고 인정하면 군교도관 또는 헌병을 동행시킬 수 있다.', 8753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15084, '② 소장은 귀휴자를 출발시키기 전에 귀휴자의 가족 또는 보호관계에 있는 사람으로부터 별지 제13호서식의 지도보증서를 제출받아야 한다.', 8753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15085, '③ 영 제86조제1항에 따라 헌병대 또는 국가경찰관서의 장에게 귀휴사실을 통보하는 경우에는 별지 제14호서식에 따른다.', 8753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15086, '① 귀휴자의 여비와 귀휴 중 착용할 의류 등은 본인이 부담한다.', 8754);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15087, '② 소장은 귀휴자의 신청이 있는 경우에 작업장려금의 전부 또는 일부를 귀휴비용으로 사용하게 할 수 있다.', 8754);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15088, '① 소장은 귀휴자가 정당한 사유없이 귀휴 기간 만료 시까지 군교도소에 복귀하지 아니한 경우에는 지체없이 귀휴지 및 그 부근 또는 연고지 등 숨을 가능성이 많은 지역의 군부대 및 경찰관서의 장에게 사진 또는 인상 설명서를 첨부하여 그 사실을 통보하여야 한다. <개정 2020.2.3>', 8755);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15089, '② 소장은 제1항의 경우 그 사실을 국방부조사본부장에게 보고하여야 한다. 해당 귀휴자를 체포한 경우에도 또한 같다. <개정 2014.11.3>', 8755);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15090, '③ 소장은 귀휴자가 제101조에 따른 귀휴지의 제한이나 그 밖에 소장이 지시한 사항을 위반한 사실을 알게 되었을 때에는 지체 없이 귀휴허가를 취소하거나 군교도관으로 하여금 필요한 조치를 하게 하여야 한다.', 8755);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15091, '① 소장은 사형확정자의 심리적 안정 및 원만한 수용생활을 위하여 소속 군교도관에게 지속적으로 상담하게 하여야 한다.', 8757);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15092, '② 제1항의 상담책임자는 상담 관련 전문교육을 이수한 군교도관을 우선하여 지정하여야 한다.', 8757);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15093, '③ 제2항에 따라 지정된 상담책임자는 상담대상자에 대하여 월 1회 이상 개별상담을 함으로써 신속한 고충 처리와 원만한 수용생활 지도를 위하여 노력하여야 한다.', 8757);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15094, '④ 제3항에 따라 상담책임자가 상담하였을 때에는 그 요지와 처리결과 등을 별지 제15호서식의 사형확정자 상담결과 보고서에 기록하여 소장에게 보고하여야 한다.', 8757);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15095, '① 소장은 법 제77조제2항에 따라 사형확정자를 혼거수용할 때에는 거실 및 작업장 등의 봉사원, 반장, 조장, 분임장, 그 밖에 군수용자를 대표하는 직책을 부여해서는 아니 된다.', 8758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15096, '② 소장은 법 제77조제3항에 따라 사형확정자가 작업을 신청하는 경우에는 군교도관회의를 거쳐 군교정시설 안에서 하는 작업을 부과할 수 있다. 이 경우 부과하는 작업은 심리적 안정과 원만한 수용생활을 도모하는 데 적합한 것이어야 한다.', 8758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15097, '③ 소장은 제2항에 따라 작업을 부과한 사형확정자에 대하여 군교도관회의를 거쳐 제105조를 적용하지 아니할 수 있다.', 8758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15098, '④ 소장은 제2항에 따라 작업이 부과된 사형확정자가 작업의 취소를 요청하는 경우에는 사형확정자의 의사, 건강, 담당 군교도관의 의견 등을 고려하여 작업을 취소할 수 있다.', 8758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15099, '⑤ 제2항에 따른 사형확정자에 대한 작업부과에 관하여는 법 제61조부터 제65조까지의 규정을 준용한다.', 8758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15100, null, 8761);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15101, '① 소장은 교정장비의 보관 및 관리를 위하여 관리책임자와 보조자를 지정한다.', 8762);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15102, '② 제1항에 따라 지정된 관리책임자와 보조자는 교정장비가 적정상태로 보관ㆍ관리될 수 있도록 수시로 점검하는 등 필요한 조치를 하여야 한다.', 8762);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15103, '③ 특정장소에 고정식으로 설치되는 장비 이외의 교정장비는 별도의 장소에 보관ㆍ관리하여야 한다.', 8762);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15104, null, 8764);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15105, '① 소장은 전자장비의 효율적인 운용을 위하여 각종 전자장비를 통합 관리할 수 있는 시스템이 설치된 중앙통제실을 설치하여 운영하여야 한다.', 8765);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15106, '② 소장은 제1항의 중앙통제실에는 외부인의 출입을 제한하여야 한다. 다만, 시찰ㆍ참관 그 밖에 소장이 특별히 허가한 경우에는 그러하지 아니하다.', 8765);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15107, '③ 전자장비의 통합관리시스템, 중앙통제실의 운영ㆍ관리 등에 관하여 필요한 사항은 국방부장관이 정한다.', 8765);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15108, '① 영상정보처리기기 카메라는 군교정시설의 벽둘레ㆍ감시대ㆍ울타리ㆍ운동장ㆍ거실ㆍ작업장ㆍ접견실ㆍ전화실ㆍ조사실ㆍ진료실ㆍ복도ㆍ통용문 그 밖에 법 제81조제1항에 따라 전자장비를 이용하여 계호하여야 할 필요가 있는 장소에 설치한다. <개정 2020.2.3>', 8766);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15109, '② 영상정보처리기기 모니터는 중앙통제실ㆍ관구실 그 밖에 군교도관이 계호하기에 적정한 장소(이하 "중앙통제실등"이라 한다)에 설치한다.', 8766);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15110, '③ 거실에 영상정보처리기기 카메라를 설치하는 경우에는 용변을 보는 하반신의 모습이 촬영되지 아니하도록 카메라의 각도를 한정하거나 화장실 가림막시설을 설치하여야 한다.', 8766);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15111, '① 군교도관 및 교도병(이하 "군교도관등"이라 한다)이 법 제81조제1항에 따라 거실에 있는 군수용자를 계호하는 경우에는 별지 제16호서식의 거실군수용자 영상계호부에 군교도관과 교도병의 직급ㆍ성명, 계호시간 및 계호대상 등을 기록하여야 한다.', 8767);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15112, '② 군교도관이 법 제81조제1항에 따라 계호하는 과정에서 군수용자의 처우 및 관리에 특히 참고할 사항을 알게 된 경우에는 그 요지를 수용기록부에 기록하여 소장에게 지체 없이 보고하여야 한다.', 8767);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15113, '① 고정식 물품검색기는 정문ㆍ수용동입구ㆍ작업장입구, 그 밖에 군수용자 또는 군교정시설을 출입하는 군수용자 외의 사람(이하 "외부인"이라 한다)의 신체ㆍ의류ㆍ휴대품의 검사가 필요한 장소에 설치한다.', 8770);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15114, '② 군교도관등이 법 제80조제1항에 따라 군수용자의 신체ㆍ의류ㆍ휴대품을 검사하는 경우에는 특별한 사정이 없으면 고정식 물품검색기를 통과하게 한 후 휴대식 금속탐지기 또는 손으로 이를 확인한다.', 8770);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15115, '③ 군교도관등이 법 제80조제3항에 따라 외부인의 의류와 휴대품을 검사하는 경우에는 고정식 물품검색기를 통과하게 하거나 휴대식 금속탐지기로 이를 확인한다.', 8770);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15116, null, 8773);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15117, '① 보호장비의 규격은 별표 3과 같다.', 8774);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15118, '② 군교도관은 제1항에 따른 규격에 맞지 아니한 보호장비를 군수용자에게 사용해서는 아니 된다.', 8774);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15119, '① 수갑의 사용방법은 다음 각 호와 같다.', 8776);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15120, '② 제1항제1호에 따라 수갑을 사용하는 경우에는 수갑보호기를 함께 사용할 수 있다.', 8776);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15121, '③ 제1항제2호에 따라 별표 5의 방법으로 수갑을 사용하여 그 목적을 달성한 후에는 즉시 별표 4의 방법으로 전환하거나 사용을 중지하여야 한다.', 8776);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15122, '④ 수갑은 구체적 상황에 적합한 종류를 선택하여 사용할 수 있다. 다만, 일회용 수갑은 일시적으로 사용하여야 하며, 사용목적을 달성한 후에는 즉시 사용을 중지하거나 다른 보호장비로 교체하여야 한다.', 8776);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15123, null, 8778);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15124, null, 8779);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15125, '① 보호의자의 사용은 별표 12의 방법으로 하며, 다른 보호장비로는 법 제84조제1항제2호부터 제4호까지의 어느 하나에 해당하는 행위를 방지하기 어려운 특별한 사정이 있는 경우에만 사용하여야 한다.', 8780);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15126, '② 보호의자의 사용은 제137조제2항에 따라 그 사용을 일시 해제하거나 완화하는 경우를 포함하여 8시간을 초과할 수 없으며, 해제 후 4시간이 지나지 아니하면 다시 사용할 수 없다.', 8780);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15127, '① 보호침대의 사용은 별표 13의 방법으로 하며, 다른 보호장비로는 자살ㆍ자해를 방지하기 어려운 특별한 사정이 있는 경우에만 사용하여야 한다.', 8781);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15128, '② 보호침대의 사용에 관하여는 제129조제2항을 준용한다.', 8781);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15129, '① 보호복의 사용은 별표 14의 방법으로 한다.', 8782);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15130, '② 보호복의 사용에 관하여는 제129제2항을 준용한다.', 8782);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15131, '① 포승의 사용방법은 다음 각 호와 같다.', 8783);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15132, '② 제1항제2호에 따라 포승을 사용하여 2명 이상의 군수용자를 호송하는 경우에는 군수용자 간에 포승을 연결하여 사용할 수 있다.', 8783);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15133, '③ 개인포승은 일시적으로 사용하여야 하며, 계속하여 사용할 필요가 있는 경우에는 일반포승으로 교체하여야 한다.', 8783);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15134, '① 소장은 보호장비를 착용 중인 군수용자에 대하여 보호장비사용 심사부 및 보호장비착용자 관찰부 등의 기록과 관계직원의 의견 등을 토대로 보호장비의 계속 사용 여부를 매일 심사하여야 한다.', 8787);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15135, '② 소장은 영 제106조에 따라 군의관 또는 의료관계 직원이 보호장비 사용의 중지를 건의하였음에도 불구하고 해당 군수용자에 대하여 보호장비를 계속하여 사용할 필요성이 있다고 판단하는 경우에는 군의관 또는 의료관계 직원에게 건강유지에 필요한 조치를 취할 것을 명하고 보호장비를 계속하여 사용할 수 있다. 이 경우 소장은 보호장비사용 심사부에 보호장비를 계속 사용할 필요가 있다고 판단하는 근거를 기록하여야 한다.', 8787);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15136, '① 군교도관은 법 제84조제1항 각 호에서 정한 보호장비 사용 사유가 소멸한 경우에는 소장의 허가를 받아 지체 없이 사용중인 보호장비를 해제하여야 한다. 다만, 군교도관이 소장의 허가를 받을 시간적 여유가 없을 때에는 보호장비를 해제한 후 지체 없이 소장의 승인을 받아야 한다.', 8788);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15137, '② 군교도관은 보호장비 착용 군수용자의 목욕ㆍ식사ㆍ용변ㆍ치료 등을 위하여 필요한 경우에는 보호장비 사용을 일시 해제하거나 완화할 수 있다.', 8788);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15138, null, 8790);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15139, '① 군교도관등이 군수용자에 대하여 사용할 수 있는 보안장비의 종류별 사용요건은 다음 각 호와 같다.', 8791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15140, '② 군교도관등이 군수용자 외의 사람에 대하여 사용할 수 있는 보안장비의 종류별 사용요건은 다음 각 호와 같다.', 8791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15141, '③ 제139조제7호에 해당하는 보안장비의 사용은 국방부장관이 정하는 바에 따른다.', 8791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15142, null, 8792);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15143, null, 8793);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15144, '① 군교도관등이 군수용자에 대하여 사용할 수 있는 무기의 종류별 사용요건은 다음 각 호와 같다.', 8794);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15145, '② 군교도관등이 군수용자 외의 사람에 대하여 사용할 수 있는 무기의 종류별 사용요건은 다음 각 호와 같다.', 8794);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15146, '③ 제142조제4호에 해당하는 무기의 사용은 국방부장관이 정하는 바에 따른다.', 8794);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15147, '① 소장은 소속 군교도관(현역 군인만 해당한다)에 대하여 연 1회 이상 총기의 조작ㆍ정비ㆍ사용에 관한 교육을 실시한다.', 8797);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15148, '② 총기 및 탄약의 정비ㆍ취급 및 사격요령은 각군의 참모총장 또는 국방부조사본부장이 정한다. <개정 2014.11.3>', 8797);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15149, '③ 총기 조작훈련을 받지 아니하였거나 그 조작이 미숙한 사람, 그 밖에 총기휴대가 부적당하다고 인정되는 사람에 대해서는 총기의 휴대를 금지하고 별지 제19호서식의 총기휴대 금지자 명부에 그 명단을 기록한 후 총기를 지급할 때마다 대조ㆍ확인하여야 한다.', 8797);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15150, '④ 제3항의 총기휴대 금지자에 대하여 금지사유가 소멸한 경우에는 그 사유를 총기휴대금지자명부에 기록하고 총기휴대금지를 해제하여야 한다.', 8797);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15151, '① 소장은 법 제92조에 따라 군수용자를 포상할 때에는 제6조에 따른 군교도관회의의 의결을 거쳐야 한다.', 8798);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15152, '② 소장은 군수형자가 법 제92조 각 호의 어느 하나에 해당하면 포상과 함께 제36조에 따른 특별심사를 할 수 있다.', 8798);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15153, null, 8799);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15154, null, 8801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15155, null, 8802);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15156, null, 8803);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15157, '① 소장은 군수용자의 징벌대상행위에 대한 조사를 시작한 날부터 10일 이내에 다음 각 호의 어느 하나에 해당하는 조치를 하여야 한다. 다만, 특히 필요하다고 인정하는 경우에는 7일을 초과하지 아니하는 범위에서 한 차례만 조사기간을 연장할 수 있다.', 8804);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15158, '② 제1항에 따른 조사기간 중 법 제96조제3항에 따라 징벌대상자에 대하여 처우를 제한하는 경우에는 징벌위원회의 의결을 거쳐 그 기간의 전부 또는 일부를 징벌기간에 산입할 수 있다.', 8804);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15159, '③ 소장은 징벌대상행위가 징벌대상자의 정신병적인 원인에 따른 것으로 의심할만한 충분한 사유가 있는 경우에는 징벌절차에 우선하여 의사의 진료, 전문가 상담 등 필요한 조치를 하여야 한다.', 8804);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15160, '④ 소장은 군의관의 소견과 제3항에 따른 의사의 진료, 전문가 상담 등에서 징벌대상자의 징벌대상행위가 정신병적인 원인에 따른 것이라고 판정된 경우에는 징벌위원회에 징벌을 요구할 수 없다.', 8804);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15161, '① 소장은 징벌대상자의 질병이나 그 밖의 특별한 사정으로 조사를 계속하기 어려운 경우에는 조사를 일시적으로 정지할 수 있다.', 8806);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15162, '② 제1항에 따라 정지된 조사기간은 그 사유가 해소된 때부터 다시 진행된다. 이 경우 조사가 정지된 다음 날부터 정지사유가 소멸한 전날까지의 기간은 조사기간에 산입되지 아니 한다.', 8806);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15163, '① 소장은 징벌대상자에 대한 조사가 끝났을 때에는 별지 제20호서식의 징벌의결 요구서를 작성하여 징벌위원회에 징벌 의결을 요구하여야 한다.', 8807);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15164, '② 제1항에 따른 징벌의결 요구서에는 징벌대상행위의 입증에 필요한 관계서류를 첨부할 수 있다.', 8807);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15165, '① 징벌위원회가 제156조에 따른 징벌의결요구서를 접수한 경우에는 지체 없이 징벌대상자에게 별지 제21호서식의 징벌위원회 출석통지서를 전달하여야 한다.', 8808);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15166, '② 제1항에 따른 출석통지서에는 다음 각 호의 내용이 포함되어야 한다.', 8808);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15167, '③ 제1항에 따라 출석통지서를 전달받은 징벌대상자가 징벌위원회에 출석하는 것을 원하지 아니하는 경우에는 별지 제22호서식의 출석포기서를 징벌위원회에 제출하여야 한다.', 8808);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15168, '① 징벌위원회는 출석한 징벌대상자를 심문하고, 필요하다고 인정하는 경우에는 군교도관이나 다른 군수용자 등을 참고인으로 출석시켜 심문할 수 있다.', 8809);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15169, '② 징벌위원회는 징벌대상자에게 제157조제1항에 따른 출석통지서를 전달하였음에도 불구하고 징벌대상자가 출석포기서를 제출하거나 정당한 사유 없이 출석하지 아니한 경우에는 그 사실을 별지 제23호서식의 징벌위원회 회의록에 기록하고 서면심리만으로 징벌을 의결할 수 있다.', 8809);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15170, '③ 징벌의 의결은 별지 제24호서식의 징벌의결서에 따른다.', 8809);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15171, '④ 징벌위원회가 작업장려금의 삭감을 의결하려면 미리 군수용자의 작업장려금을 확인하여야 한다.', 8809);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15172, '⑤ 징벌위원회의 회의에 참여한 사람은 직무상 알게 된 비밀을 누설해서는 아니 된다.', 8809);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15173, '① 금치와 다른 징벌을 함께 집행할 때에는 작업장려금의 삭감과 경고를 제외하고는 금치를 우선하여 집행한다.', 8811);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15174, '② 같은 종류의 징벌은 그 기간이 긴 것부터 집행한다.', 8811);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15175, '③ 금치를 제외한 다른 종류의 징벌은 함께 집행할 수 있다.', 8811);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15176, '① 작업장려금의 삭감은 징벌위원회가 해당 징벌을 의결한 날이 속하는 달의 작업장려금부터 이미 지급된 작업장려금에 대하여 역순(逆順)으로 집행한다.', 8812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15177, '② 소장은 금치를 집행하는 경우에는 징벌집행을 위하여 따로 지정한 거실(이하 "징벌거실"이라 한다)에 해당 군수용자를 수용하여야 한다.', 8812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15178, '③ 소장은 금치 외의 징벌을 집행하는 경우에 그 징벌의 목적을 달성하기 위하여 필요하다고 인정하면 해당 군수용자를 징벌거실에 수용할 수 있다.', 8812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15179, '④ 소장은 징벌 집행을 받고 있거나 집행을 앞둔 군수용자가 같은 행위로 형사법률에 따른 처벌이 확정되어 징벌을 집행할 필요가 없다고 인정하면 징벌 집행을 감경하거나 면제할 수 있다.', 8812);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15180, '① 위원회의 위원은 다음 각 호의 사람 중에서 위원장이 법 제105조제2항에 따라 위촉한 위원으로 구성한다. 이 경우 제1호의 군법무관 3명과 헌병병과 장교 2명이 포함되도록 하되, 특정 군 또는 부대 소속으로만 구성하지 않도록 한다.', 8817);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15181, '② 위원장이 제1항에 따라 위원을 위촉하였을 때에는 그 명단을 국방부조사본부장을 거쳐 국방부장관에게 보고하여야 한다. <개정 2014.11.3>', 8817);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15182, '③ 제2항에 따른 위원 명단은 심사의 공정성과 위원의 신변보호를 위하여 외부에 공개해서는 아니 된다.', 8817);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15183, '① 위원장은 위원회를 대표하고, 위원회의 업무를 총괄한다.', 8819);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15184, '② 위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 위원장이 미리 지정한 위원이 그 직무를 대행한다.', 8819);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15185, '① 위원장은 회의를 소집하고, 그 의장이 된다.', 8820);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15186, '② 위원회의 회의는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.', 8820);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15187, '① 위원회에 위원회의 사무를 처리하기 위하여 간사 1명과 서기 1명을 둔다.', 8821);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15188, '② 간사와 서기는 소속 군교도관 중에서 소장이 임명한다.', 8821);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15189, '③ 간사는 회의에 참석하여 발언할 수 있고, 위원회 결정에 따른 결정서를 작성하여야 한다.', 8821);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15190, '④ 서기는 간사의 업무를 보조한다.', 8821);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15191, '① 간사는 별지 제26호서식의 가석방심사위원회 회의록을 작성ㆍ관리하여야 한다.', 8822);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15192, '② 제1항에 따른 회의록에는 회의의 내용을 기록하고, 위원장 및 간사가 서명ㆍ날인하여야 한다.', 8822);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15193, '① 소장은 「형법」 제72조에 따른 가석방의 요건을 갖춘 군수형자 중 교정성적이 우수하고 뉘우치는 빛이 뚜렷하여 재범의 위험성이 없다고 인정되는 사람을 군교도관회의의 의결을 거쳐 가석방 적격심사 대상자로 선정한다.', 8826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15194, '② 소장은 형의 집행정지를 받게 될 군수형자가 제1항에 해당할 경우에는 우선적으로 위원회에 가석방의 적격심사를 회부하여야 한다.', 8826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15195, '③ 소장은 가석방 적격심사에 필요하다고 인정하는 경우에는 군교도관회의에 담당군교도관을 출석시켜 군수형자의 가석방 적격심사에 관한 의견을 들을 수 있다.', 8826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15196, null, 8827);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15197, '① 신원관계의 조사는 영 제76조제1항에 따라 군수형자로 처우하는 날부터 1개월 이내에 하고, 그 후에는 변경을 요하는 사항을 발견하거나 가석방 적격심사를 위해 필요한 경우에 한다.', 8829);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15198, '② 범죄관계 및 보호관계의 조사는 영 제76조제1항에 따라 군수형자로 처우하는 날부터 2개월 이내에 하여야 한다.', 8829);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15199, '③ 범죄관계의 조사에 필요하다고 인정하는 경우에는 소송기록을 열람할 수 있다.', 8829);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15200, '① 소장은 제175조에 따라 가석방 심사대상자를 선정하였을 때에는 선정한 날부터 5일 이내에 위원회에 가석방 적격심사를 회부하여야 한다.', 8830);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15201, '② 소장은 제1항에 따라 위원회에 가석방 적격심사를 회부할 때에는 별지 제27호서식의 가석방 적격심사 신청서에 별지 제28호서식의 가석방 심사 및 신상조사표를 첨부하여야 한다.', 8830);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15202, '③ 소장은 위원회에 가석방 적격심사를 회부한 사실을 군수형자의 동의를 얻어 보호자 등에게 통지할 수 있다.', 8830);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15203, '① 위원회가 범죄의 동기에 관하여 심사할 때에는 사회 통념상 및 공익상 등 정상을 참작할 만한 사유가 있는지를 심사하여야 한다.', 8832);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15204, '② 범죄의 동기가 군중의 암시 또는 도발, 감독관계에 의한 위협, 그 밖에 이와 유사한 사유에 의한 경우에는 특히 군수형자의 성격 또는 환경의 변화에 유의하고 가석방 후의 환경이 가석방처분을 받은 사람(「보호관찰 등에 관한 법률」에 따른 보호관찰대상자는 제외한다. 이하 "가석방자"라 한다)에게 미칠 영향을 심사하여야 한다.', 8832);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15205, null, 8833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15206, null, 8834);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15207, '① 재산에 관한 죄를 범한 군수형자에 대해서는 특히 그 범행으로 인하여 발생한 손해의 배상 여부 또는 손해를 줄이기 위한 노력 여부를 심사하여야 한다.', 8835);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15208, '② 군수형자 외의 사람이 피해자의 손해를 배상한 경우에는 그 배상이 군수형자 본인의 희망에 따른 것인지를 심사하여야 한다.', 8835);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15209, '① 위원회는 가석방 적격심사에 필요하다고 인정하는 경우에는 군수형자의 주소지 또는 연고지 등을 관할하는 시ㆍ군ㆍ구ㆍ경찰서, 전(前) 소속부대, 그 밖에 학교ㆍ직업알선기관ㆍ보호단체ㆍ종교단체 등 관계기관에 사실조회를 하거나 관계자의 의견을 들을 수 있다.', 8836);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15210, '② 위원회는 가석방 적격심사를 위하여 필요하다고 인정하는 경우에는 위원이 아닌 군법무관 또는 판사ㆍ검사ㆍ변호사에게 의견을 구하거나 위원회에 참여하게 할 수 있다.', 8836);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15211, '① 위원회는 가석방 적격심사에 필요하다고 인정하는 경우에는 심리학ㆍ정신의학ㆍ사회학 또는 교육학을 전공한 전문가에게 군수형자의 정신상태 등 특정 사항에 대한 감정(鑑定)을 촉탁(囑託)할 수 있다.', 8837);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15212, '② 제1항에 따른 촉탁을 받은 사람은 소장의 허가를 받아 군수형자와 접견할 수 있다.', 8837);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15213, '① 위원회가 법 제106조제2항에 따라 가석방 적격결정을 하였을 때에는 별지 제29호서식의 가석방 결정서를 작성하여야 한다.', 8839);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15214, '② 법 제107조에 따른 가석방허가의 신청은 별지 제30호서식에 따른다.', 8839);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15215, '① 소장은 가석방자가 제192조에 따른 가석방 취소의 사유가 있음을 알았거나 소속 부대장 또는 관할 경찰서장으로부터 통보를 받았을 때에는 지체 없이 가석방 취소의 심사를 위원회에 회부하여야 한다.', 8844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15216, '② 제1항에도 불구하고 소장은 위원회를 소집할 수 없거나 긴급한 사유가 있는 때에는 위원회의 심사를 거치지 아니하고 국방부장관에게 가석방 취소를 신청할 수 있다.', 8844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15217, '③ 위원장은 위원회에서 가석방 취소를 결정하였을 때에는 지체 없이 국방부장관에게 가석방 취소를 신청하여야 한다.', 8844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15218, '① 위원회가 가석방 취소 여부를 심사하는 경우에는 제192조에 따른 가석방 취소의 사유에 해당하게 된 경위와 그 위반행위가 군과 사회에 미치는 영향, 가석방 기간 동안의 행실의 양호 여부, 직업의 유무 및 종류, 생활상황과 친족관계, 그 밖의 사정을 고려하여야 한다.', 8845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15219, '② 위원회는 제1항의 심사를 위하여 필요한 경우에는 해당 가석방자를 위원회에 출석시켜 그 진술을 들을 수 있다.', 8845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15220, '① 소장은 가석방자의 가석방이 취소되었을 때에는 지체 없이 남은 형의 집행에 필요한 조치를 하고, 그 결과를 국방부장관에게 보고하여야 한다.', 8846);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15221, '② 소장은 가석방이 취소된 사람이 군교도소 밖에 있을 때에는 관할 헌병대장 또는 관할 경찰서장에게 가석방이 취소된 사람을 구인(拘引)하도록 의뢰하여야 한다.', 8846);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15222, '③ 제2항에 따라 구인의 의뢰를 받은 헌병대장 또는 경찰서장은 즉시 가석방이 취소된 사람을 구인하여 소장에게 인계하여야 한다.', 8846);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15223, '① 이 법은 이 법에 규정된 죄를 범한 대한민국 군인에게 적용한다.', 8849);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15224, '② 제1항에서 "군인"이란 현역에 복무하는 장교, 준사관, 부사관 및 병(兵)을 말한다. 다만, 전환복무(轉換服務) 중인 병은 제외한다.', 8849);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15225, '③ 다음 각 호의 어느 하나에 해당하는 사람에 대하여는 군인에 준하여 이 법을 적용한다. <개정 2016.5.29>', 8849);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15226, '④ 다음 각 호의 어느 하나에 해당하는 죄를 범한 내국인ㆍ외국인에 대하여도 군인에 준하여 이 법을 적용한다.', 8849);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15227, '⑤ 제1항부터 제3항까지에 규정된 사람이 군복무 중이나 재학 또는 재영 중에 이 법에서 정한 죄를 범한 경우에는 전역ㆍ소집해제ㆍ퇴직 또는 퇴교나 퇴영 후에도 이 법을 적용한다.', 8849);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15228, null, 8851);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15229, null, 8854);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15230, '① 제5조 또는 제6조의 죄를 범할 목적으로 예비 또는 음모를 한 사람은 5년 이상의 유기징역이나 유기금고에 처한다. 다만, 그 목적한 죄의 실행에 이르기 전에 자수한 경우에는 그 형을 감경하거나 면제한다.', 8857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15231, '② 제5조 또는 제6조의 죄를 범할 것을 선동하거나 선전한 사람도 제1항의 형에 처한다.', 8857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15232, '① 반란을 알고도 이를 상관 또는 그 밖의 관계관에게 지체 없이 보고하지 아니한 사람은 2년 이하의 징역이나 금고에 처한다.', 8858);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15233, '② 제1항의 경우에 적을 이롭게 할 목적으로 보고하지 아니한 사람은 7년 이하의 징역이나 금고에 처한다.', 8858);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15234, '① 군대 요새(要塞), 진영(陣營) 또는 군용에 공하는 함선이나 항공기 또는 그 밖의 장소, 설비 또는 건조물을 적에게 제공한 사람은 사형에 처한다.', 8860);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15235, '② 병기, 탄약 또는 그 밖에 군용에 공하는 물건을 적에게 제공한 사람도 제1항의 형에 처한다.', 8860);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15236, '① 적을 위하여 간첩행위를 한 사람은 사형에 처하고, 적의 간첩을 방조한 사람은 사형 또는 무기징역에 처한다.', 8862);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15237, '② 군사상 기밀을 적에게 누설한 사람도 제1항의 형에 처한다.', 8862);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15238, '③ 다음 각 호의 어느 하나에 해당하는 지역 또는 기관에서 제1항 및 제2항의 죄를 범한 사람도 제1항의 형에 처한다.', 8862);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15239, null, 8863);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15240, '① 제11조부터 제14조까지의 죄를 범할 목적으로 예비 또는 음모를 한 사람은 3년 이상의 유기징역에 처한다. 다만, 그 목적한 죄의 실행에 이르기 전에 자수한 경우에는 그 형을 감경하거나 면제한다.', 8865);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15241, '② 제11조부터 제14조까지의 죄를 범할 것을 선동하거나 선전한 사람도 제1항의 형에 처한다.', 8865);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15242, null, 8873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15243, null, 8876);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15244, null, 8877);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15245, '① 군무를 기피할 목적으로 부대 또는 직무를 이탈한 사람은 다음 각 호의 구분에 따라 처벌한다.', 8879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15246, '② 부대 또는 직무에서 이탈된 사람으로서 정당한 사유 없이 상당한 기간 내에 부대 또는 직무에 복귀하지 아니한 사람도 제1항의 형에 처한다.', 8879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15247, null, 8881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15248, null, 8884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15249, null, 8885);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15250, null, 8886);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15251, '① 군사(軍事)에 관하여 거짓 명령, 통보 또는 보고를 한 사람은 다음 각 호의 구분에 따라 처벌한다.', 8887);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15252, '② 군사에 관한 명령, 통보 또는 보고를 할 의무가 있는 사람이 제1항의 죄를 범한 경우에는 제1항 각 호에서 정한 형의 2분의 1까지 가중한다.', 8887);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15253, '① 정당한 사유 없이 정하여진 규칙에 따르지 아니하고 초병을 교체하게 하거나 교체한 사람은 다음 각 호의 구분에 따라 처벌한다.', 8889);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15254, '② 초병이 잠을 자거나 술을 마신 경우에도 제1항의 형에 처한다.', 8889);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15255, '① 근무를 기피할 목적으로 신체를 상해한 사람은 다음 각 호의 구분에 따라 처벌한다.', 8890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15256, '② 근무를 기피할 목적으로 질병을 가장하거나 그 밖의 위계(僞計)를 한 사람은 다음 각 호의 구분에 따라 처벌한다.', 8890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15257, '① 독성이 있는 음식물을 군에 공급한 사람은 10년 이하의 징역에 처한다.', 8891);
