INSERT INTO balaw.hang (id, content, jo_id) VALUES (15303, '① 직권을 남용하여 학대 또는 가혹한 행위를 한 사람은 5년 이하의 징역에 처한다.', 8926);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15304, '② 위력을 행사하여 학대 또는 가혹한 행위를 한 사람은 3년 이하의 징역 또는 700만원 이하의 벌금에 처한다.', 8926);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15305, '① 상관을 그 면전에서 모욕한 사람은 2년 이하의 징역이나 금고에 처한다.', 8928);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15306, '② 문서, 도화(圖畵) 또는 우상(偶像)을 공시(公示)하거나 연설 또는 그 밖의 공연(公然)한 방법으로 상관을 모욕한 사람은 3년 이하의 징역이나 금고에 처한다.', 8928);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15307, '③ 공연히 사실을 적시하여 상관의 명예를 훼손한 사람은 3년 이하의 징역이나 금고에 처한다.', 8928);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15308, '④ 공연히 거짓 사실을 적시하여 상관의 명예를 훼손한 사람은 5년 이하의 징역이나 금고에 처한다.', 8928);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15309, '① 불을 놓아 군의 공장, 함선, 항공기 또는 전투용으로 공하는 시설, 기차, 전차, 자동차, 교량을 소훼(燒훼)한 사람은 사형, 무기 또는 10년 이상의 징역에 처한다.', 8930);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15310, '② 불을 놓아 군용에 공하는 물건을 저장하는 창고를 소훼한 사람은 다음 각 호의 구분에 따라 처벌한다.', 8930);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15311, null, 8931);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15312, '① 취역(就役) 중에 있는 함선을 충돌 또는 좌초시키거나 위험한 곳을 항행하게 하여 함선을 복몰(覆沒) 또는 손괴한 사람은 사형, 무기 또는 5년 이상의 징역에 처한다.', 8935);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15313, '② 취역 중에 있는 항공기를 추락시키거나 손괴한 사람도 제1항의 형에 처한다.', 8935);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15314, '③ 제1항 또는 제2항의 죄를 범하여 사람을 사망 또는 상해에 이르게 한 사람은 사형, 무기 또는 10년 이상의 징역에 처한다.', 8935);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15315, '① 과실로 인하여 제66조부터 제71조까지의 죄를 범한 사람은 5년 이하의 징역 또는 300만원 이하의 벌금에 처한다.', 8937);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15316, '② 업무상 과실 또는 중대한 과실로 인하여 제1항의 죄를 범한 사람은 7년 이하의 징역 또는 500만원 이하의 벌금에 처한다.', 8937);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15317, '① 총포, 탄약, 폭발물, 차량, 장구, 기재, 식량, 피복 또는 그 밖에 군용에 공하는 물건 또는 군의 재산상 이익에 관하여 「형법」 제2편제38장부터 제41장까지의 죄를 범한 경우에는 다음 각 호의 구분에 따라 처벌한다.', 8939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15318, '② 제1항의 경우에는 「형법」에 정한 형과 비교하여 중한 형으로 처벌한다.', 8939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15319, '③ 제1항의 죄에 대하여는 3천만원 이하의 벌금을 병과(倂科)할 수 있다.', 8939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15320, null, 8942);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15321, '① 군사상 기밀을 누설한 사람은 10년 이하의 징역이나 금고에 처한다.', 8944);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15322, '② 업무상 과실 또는 중대한 과실로 인하여 제1항의 죄를 범한 경우에는 3년 이하의 징역이나 금고 또는 700만원 이하의 벌금에 처한다.', 8944);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15323, null, 8945);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15324, '① 전투지역 또는 점령지역에서 군의 위력 또는 전투의 공포를 이용하여 주민의 재물을 약취(掠取)한 사람은 무기 또는 3년 이상의 징역에 처한다.', 8946);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15325, '② 전투지역에서 전사자 또는 전상병자의 의류나 그 밖의 재물을 약취한 사람은 1년 이상의 유기징역에 처한다.', 8946);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15326, '① 제82조의 죄를 범하여 사람을 살해하거나 사망에 이르게 한 사람은 사형 또는 무기징역에 처한다.', 8947);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15327, '② 제82조의 죄를 범하여 사람을 상해하거나 상해에 이르게 한 사람은 무기 또는 7년 이상의 징역에 처한다.', 8947);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15328, '① 전투지역 또는 점령지역에서 사람을 강간한 사람은 사형에 처한다. <개정 2013.4.5>', 8948);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15329, '② 삭제 <2013.4.5>', 8948);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15330, '① 포로를 도주하게 한 사람은 10년 이하의 징역에 처한다.', 8952);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15331, '② 포로를 도주시킬 목적으로 포로에게 기구를 제공하거나 그 밖에 그 도주를 용이하게 하는 행위를 한 사람은 7년 이하의 징역에 처한다.', 8952);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15332, '① 정당이나 정치단체에 가입하거나 다음 각 호의 어느 하나에 해당하는 행위를 한 사람은 5년 이하의 징역과 5년 이하의 자격정지에 처한다.', 8965);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15333, '② 제1항에 규정된 죄에 대한 공소시효의 기간은 「군사법원법」 제291조제1항에도 불구하고 10년으로 한다.', 8965);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15334, '① 범죄의 성립과 처벌은 행위 시의 법률에 따른다.', 8966);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15335, '② 범죄 후 법률이 변경되어 그 행위가 범죄를 구성하지 아니하게 되거나 형이 구법(舊法)보다 가벼워진 경우에는 신법(新法)에 따른다.', 8966);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15336, '③ 재판이 확정된 후 법률이 변경되어 그 행위가 범죄를 구성하지 아니하게 된 경우에는 형의 집행을 면제한다.', 8966);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15337, null, 8970);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15338, '①심신장애로 인하여 사물을 변별할 능력이 없거나 의사를 결정할 능력이 없는 자의 행위는 벌하지 아니한다.', 8975);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15339, '②심신장애로 인하여 전항의 능력이 미약한 자의 행위는 형을 감경할 수 있다. <개정 2018.12.18>', 8975);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15340, '③위험의 발생을 예견하고 자의로 심신장애를 야기한 자의 행위에는 전2항의 규정을 적용하지 아니한다.', 8975);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15341, '① 특별히 무거운 죄가 되는 사실을 인식하지 못한 행위는 무거운 죄로 벌하지 아니한다.', 8980);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15342, '② 결과 때문에 형이 무거워지는 죄의 경우에 그 결과의 발생을 예견할 수 없었을 때에는 무거운 죄로 벌하지 아니한다.', 8980);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15343, '① 현재의 부당한 침해로부터 자기 또는 타인의 법익(法益)을 방위하기 위하여 한 행위는 상당한 이유가 있는 경우에는 벌하지 아니한다.', 8986);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15344, '② 방위행위가 그 정도를 초과한 경우에는 정황(情況)에 따라 그 형을 감경하거나 면제할 수 있다.', 8986);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15345, '③ 제2항의 경우에 야간이나 그 밖의 불안한 상태에서 공포를 느끼거나 경악(驚愕)하거나 흥분하거나 당황하였기 때문에 그 행위를 하였을 때에는 벌하지 아니한다.', 8986);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15346, '①자기 또는 타인의 법익에 대한 현재의 위난을 피하기 위한 행위는 상당한 이유가 있는 때에는 벌하지 아니한다.', 8987);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15347, '②위난을 피하지 못할 책임이 있는 자에 대하여는 전항의 규정을 적용하지 아니한다.', 8987);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15348, '③전조 제2항과 제3항의 규정은 본조에 준용한다.', 8987);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15349, '① 법률에서 정한 절차에 따라서는 청구권을 보전(保全)할 수 없는 경우에 그 청구권의 실행이 불가능해지거나 현저히 곤란해지는 상황을 피하기 위하여 한 행위는 상당한 이유가 있는 때에는 벌하지 아니한다.', 8988);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15350, '② 제1항의 행위가 그 정도를 초과한 경우에는 정황에 따라 그 형을 감경하거나 면제할 수 있다.', 8988);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15351, '①범죄의 실행에 착수하여 행위를 종료하지 못하였거나 결과가 발생하지 아니한 때에는 미수범으로 처벌한다.', 8990);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15352, '②미수범의 형은 기수범보다 감경할 수 있다.', 8990);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15353, '①타인을 교사하여 죄를 범하게 한 자는 죄를 실행한 자와 동일한 형으로 처벌한다.', 8996);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15354, '②교사를 받은 자가 범죄의 실행을 승낙하고 실행의 착수에 이르지 아니한 때에는 교사자와 피교사자를 음모 또는 예비에 준하여 처벌한다.', 8996);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15355, '③교사를 받은 자가 범죄의 실행을 승낙하지 아니한 때에도 교사자에 대하여는 전항과 같다.', 8996);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15356, '①타인의 범죄를 방조한 자는 종범으로 처벌한다.', 8997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15357, '②종범의 형은 정범의 형보다 감경한다.', 8997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15358, '①어느 행위로 인하여 처벌되지 아니하는 자 또는 과실범으로 처벌되는 자를 교사 또는 방조하여 범죄행위의 결과를 발생하게 한 자는 교사 또는 방조의 예에 의하여 처벌한다.', 8999);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15359, '②자기의 지휘, 감독을 받는 자를 교사 또는 방조하여 전항의 결과를 발생하게 한 자는 교사인 때에는 정범에 정한 형의 장기 또는 다액에 그 2분의 1까지 가중하고 방조인 때에는 정범의 형으로 처벌한다.', 8999);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15360, '① 금고(禁錮) 이상의 형을 선고받아 그 집행이 종료되거나 면제된 후 3년 내에 금고 이상에 해당하는 죄를 지은 사람은 누범(累犯)으로 처벌한다.', 9000);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15361, '② 누범의 형은 그 죄에 대하여 정한 형의 장기(長期)의 2배까지 가중한다.', 9000);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15362, '① 경합범을 동시에 판결할 때에는 다음 각 호의 구분에 따라 처벌한다.', 9003);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15363, '② 제1항 각 호의 경우에 징역과 금고는 같은 종류의 형으로 보아 징역형으로 처벌한다.', 9003);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15364, '①경합범중 판결을 받지 아니한 죄가 있는 때에는 그 죄와 판결이 확정된 죄를 동시에 판결할 경우와 형평을 고려하여 그 죄에 대하여 형을 선고한다. 이 경우 그 형을 감경 또는 면제할 수 있다. <개정 2005.7.29>', 9004);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15365, '② 삭제 <2005.7.29>', 9004);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15366, '③경합범에 의한 판결의 선고를 받은 자가 경합범 중의 어떤 죄에 대하여 사면 또는 형의 집행이 면제된 때에는 다른 죄에 대하여 다시 형을 정한다.', 9004);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15367, '④전 3항의 형의 집행에 있어서는 이미 집행한 형기를 통산한다.', 9004);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15368, null, 9006);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15369, '①사형, 무기징역 또는 무기금고의 판결을 받은 자는 다음에 기재한 자격을 상실한다.', 9008);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15370, '②유기징역 또는 유기금고의 판결을 받은 자는 그 형의 집행이 종료하거나 면제될 때까지 전항 제1호 내지 제3호에 기재된 자격이 정지된다. 다만, 다른 법률에 특별한 규정이 있는 경우에는 그 법률에 따른다. <개정 2016.1.6>', 9008);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15371, '①전조에 기재한 자격의 전부 또는 일부에 대한 정지는 1년 이상 15년 이하로 한다.', 9009);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15372, '②유기징역 또는 유기금고에 자격정지를 병과한 때에는 징역 또는 금고의 집행을 종료하거나 면제된 날로부터 정지기간을 기산한다.', 9009);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15373, '① 범인 외의 자의 소유에 속하지 아니하거나 범죄 후 범인 외의 자가 사정을 알면서 취득한 다음 각 호의 물건은 전부 또는 일부를 몰수할 수 있다.', 9013);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15374, '② 제1항 각 호의 물건을 몰수할 수 없을 때에는 그 가액(價額)을 추징한다.', 9013);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15375, '③ 문서, 도화(圖畵), 전자기록(電磁記錄) 등 특수매체기록 또는 유가증권의 일부가 몰수의 대상이 된 경우에는 그 부분을 폐기한다.', 9013);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15376, '① 형의 경중은 제41조 각 호의 순서에 따른다. 다만, 무기금고와 유기징역은 무기금고를 무거운 것으로 하고 유기금고의 장기가 유기징역의 장기를 초과하는 때에는 유기금고를 무거운 것으로 한다.', 9015);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15377, '② 같은 종류의 형은 장기가 긴 것과 다액이 많은 것을 무거운 것으로 하고 장기 또는 다액이 같은 경우에는 단기가 긴 것과 소액이 많은 것을 무거운 것으로 한다.', 9015);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15378, '③ 제1항 및 제2항을 제외하고는 죄질과 범정(犯情)을 고려하여 경중을 정한다.', 9015);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15379, null, 9016);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15380, '① 죄를 지은 후 수사기관에 자수한 경우에는 형을 감경하거나 면제할 수 있다.', 9017);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15381, '② 피해자의 의사에 반하여 처벌할 수 없는 범죄의 경우에는 피해자에게 죄를 자복(自服)하였을 때에도 형을 감경하거나 면제할 수 있다.', 9017);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15382, '①법률상의 감경은 다음과 같다. <개정 2010.4.15>', 9020);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15383, '②법률상 감경할 사유가 수개있는 때에는 거듭 감경할 수 있다.', 9020);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15384, null, 9021);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15385, '①판결선고전의 구금일수는 그 전부를 유기징역, 유기금고, 벌금이나 과료에 관한 유치 또는 구류에 산입한다. <개정 2014.12.30>', 9022);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15386, '②전항의 경우에는 구금일수의 1일은 징역, 금고, 벌금이나 과료에 관한 유치 또는 구류의 기간의 1일로 계산한다.', 9022);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15387, '①피해자의 이익을 위하여 필요하다고 인정할 때에는 피해자의 청구가 있는 경우에 한하여 피고인의 부담으로 판결공시의 취지를 선고할 수 있다.', 9023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15388, '② 피고사건에 대하여 무죄의 판결을 선고하는 경우에는 무죄판결공시의 취지를 선고하여야 한다. 다만, 무죄판결을 받은 피고인이 무죄판결공시 취지의 선고에 동의하지 아니하거나 피고인의 동의를 받을 수 없는 경우에는 그러하지 아니하다. <개정 2014.12.30>', 9023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15389, '③ 피고사건에 대하여 면소의 판결을 선고하는 경우에는 면소판결공시의 취지를 선고할 수 있다. <신설 2014.12.30>', 9023);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15390, '① 1년 이하의 징역이나 금고, 자격정지 또는 벌금의 형을 선고할 경우에 제51조의 사항을 고려하여 뉘우치는 정상이 뚜렷할 때에는 그 형의 선고를 유예할 수 있다. 다만, 자격정지 이상의 형을 받은 전과가 있는 사람에 대해서는 예외로 한다.', 9024);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15391, '② 형을 병과할 경우에도 형의 전부 또는 일부에 대하여 선고를 유예할 수 있다.', 9024);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15392, '①형의 선고를 유예하는 경우에 재범방지를 위하여 지도 및 원호가 필요한 때에는 보호관찰을 받을 것을 명할 수 있다.', 9025);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15393, '②제1항의 규정에 의한 보호관찰의 기간은 1년으로 한다.', 9025);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15394, '①형의 선고유예를 받은 자가 유예기간 중 자격정지 이상의 형에 처한 판결이 확정되거나 자격정지 이상의 형에 처한 전과가 발견된 때에는 유예한 형을 선고한다. <개정 1995.12.29>', 9027);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15395, '②제59조의2의 규정에 의하여 보호관찰을 명한 선고유예를 받은 자가 보호관찰기간중에 준수사항을 위반하고 그 정도가 무거운 때에는 유예한 형을 선고할 수 있다. <신설 1995.12.29>', 9027);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15396, '①3년 이하의 징역이나 금고 또는 500만원 이하의 벌금의 형을 선고할 경우에 제51조의 사항을 참작하여 그 정상에 참작할 만한 사유가 있는 때에는 1년 이상 5년 이하의 기간 형의 집행을 유예할 수 있다. 다만, 금고 이상의 형을 선고한 판결이 확정된 때부터 그 집행을 종료하거나 면제된 후 3년까지의 기간에 범한 죄에 대하여 형을 선고하는 경우에는 그러하지 아니하다. <개정 2005.7.29, 2016.1.6>', 9028);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15397, '②형을 병과할 경우에는 그 형의 일부에 대하여 집행을 유예할 수 있다.', 9028);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15398, '①형의 집행을 유예하는 경우에는 보호관찰을 받을 것을 명하거나 사회봉사 또는 수강을 명할 수 있다.', 9029);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15399, '②제1항의 규정에 의한 보호관찰의 기간은 집행을 유예한 기간으로 한다. 다만, 법원은 유예기간의 범위내에서 보호관찰기간을 정할 수 있다.', 9029);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15400, '③사회봉사명령 또는 수강명령은 집행유예기간내에 이를 집행한다.', 9029);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15401, '①집행유예의 선고를 받은 후 제62조 단행의 사유가 발각된 때에는 집행유예의 선고를 취소한다. <개정 1995.12.29>', 9031);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15402, '②제62조의2의 규정에 의하여 보호관찰이나 사회봉사 또는 수강을 명한 집행유예를 받은 자가 준수사항이나 명령을 위반하고 그 정도가 무거운 때에는 집행유예의 선고를 취소할 수 있다. <신설 1995.12.29>', 9031);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15403, '①벌금과 과료는 판결확정일로부터 30일내에 납입하여야 한다. 단, 벌금을 선고할 때에는 동시에 그 금액을 완납할 때까지 노역장에 유치할 것을 명할 수 있다.', 9036);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15404, '②벌금을 납입하지 아니한 자는 1일 이상 3년 이하, 과료를 납입하지 아니한 자는 1일 이상 30일 미만의 기간 노역장에 유치하여 작업에 복무하게 한다.', 9036);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15405, '① 벌금이나 과료를 선고할 때에는 이를 납입하지 아니하는 경우의 노역장 유치기간을 정하여 동시에 선고하여야 한다. <개정 2020.12.8>', 9037);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15406, '② 선고하는 벌금이 1억원 이상 5억원 미만인 경우에는 300일 이상, 5억원 이상 50억원 미만인 경우에는 500일 이상, 50억원 이상인 경우에는 1천일 이상의 노역장 유치기간을 정하여야 한다. <신설 2014.5.14, 2020.12.8>', 9037);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15407, '① 징역이나 금고의 집행 중에 있는 사람이 행상(行狀)이 양호하여 뉘우침이 뚜렷한 때에는 무기형은 20년, 유기형은 형기의 3분의 1이 지난 후 행정처분으로 가석방을 할 수 있다.', 9039);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15408, '② 제1항의 경우에 벌금이나 과료가 병과되어 있는 때에는 그 금액을 완납하여야 한다.', 9039);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15409, '① 형기에 산입된 판결선고 전 구금일수는 가석방을 하는 경우 집행한 기간에 산입한다.', 9040);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15410, '② 제72조제2항의 경우에 벌금이나 과료에 관한 노역장 유치기간에 산입된 판결선고 전 구금일수는 그에 해당하는 금액이 납입된 것으로 본다.', 9040);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15411, '①가석방의 기간은 무기형에 있어서는 10년으로 하고, 유기형에 있어서는 남은 형기로 하되, 그 기간은 10년을 초과할 수 없다.', 9041);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15412, '②가석방된 자는 가석방기간중 보호관찰을 받는다. 다만, 가석방을 허가한 행정관청이 필요가 없다고 인정한 때에는 그러하지 아니하다.', 9041);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15413, '①가석방의 처분을 받은 후 그 처분이 실효 또는 취소되지 아니하고 가석방기간을 경과한 때에는 형의 집행을 종료한 것으로 본다. <개정 1995.12.29>', 9044);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15414, '②전2조의 경우에는 가석방중의 일수는 형기에 산입하지 아니한다.', 9044);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15415, null, 9046);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15416, '①시효는 형의 집행의 유예나 정지 또는 가석방 기타 집행할 수 없는 기간은 진행되지 아니한다. <개정 2014.5.14>', 9047);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15417, '② 시효는 형이 확정된 후 그 형의 집행을 받지 아니한 사람이 형의 집행을 면할 목적으로 국외에 있는 기간 동안은 진행되지 아니한다. <신설 2014.5.14, 2023.8.8>', 9047);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15418, '①형기는 판결이 확정된 날로부터 기산한다.', 9052);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15419, '②징역, 금고, 구류와 유치에 있어서는 구속되지 아니한 일수는 형기에 산입하지 아니한다.', 9052);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15420, null, 9055);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15421, '①제87조 또는 제88조의 죄를 범할 목적으로 예비 또는 음모한 자는 3년 이상의 유기징역이나 유기금고에 처한다. 단, 그 목적한 죄의 실행에 이르기 전에 자수한 때에는 그 형을 감경 또는 면제한다.', 9058);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15422, '②제87조 또는 제88조의 죄를 범할 것을 선동 또는 선전한 자도 전항의 형과 같다.', 9058);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15423, null, 9059);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15424, '①적국을 위하여 모병한 자는 사형 또는 무기징역에 처한다.', 9062);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15425, '②전항의 모병에 응한 자는 무기 또는 5년 이상의 징역에 처한다.', 9062);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15426, '①군대, 요새, 진영 또는 군용에 공하는 선박이나 항공기 기타 장소, 설비 또는 건조물을 적국에 제공한 자는 사형 또는 무기징역에 처한다.', 9063);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15427, '②병기 또는 탄약 기타 군용에 공하는 물건을 적국에 제공한 자도 전항의 형과 같다.', 9063);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15428, '①적국을 위하여 간첩하거나 적국의 간첩을 방조한 자는 사형, 무기 또는 7년 이상의 징역에 처한다.', 9066);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15429, '②군사상의 기밀을 적국에 누설한 자도 전항의 형과 같다.', 9066);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15430, '①제92조 내지 제99조의 죄를 범할 목적으로 예비 또는 음모한 자는 2년 이상의 유기징역에 처한다. 단 그 목적한 죄의 실행에 이르기 전에 자수한 때에는 그 형을 감경 또는 면제한다.', 9069);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15431, '②제92조 내지 제99조의 죄를 선동 또는 선전한 자도 전항의 형과 같다.', 9069);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15432, '①전쟁 또는 사변에 있어서 정당한 이유없이 정부에 대한 군수품 또는 군용공작물에 관한 계약을 이행하지 아니한 자는 10년 이하의 징역에 처한다.', 9071);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15433, '②전항의 계약이행을 방해한 자도 전항의 형과 같다.', 9071);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15434, '①대한민국에 체재하는 외국의 원수에 대하여 폭행 또는 협박을 가한 자는 7년 이하의 징역이나 금고에 처한다.', 9076);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15435, '②전항의 외국원수에 대하여 모욕을 가하거나 명예를 훼손한 자는 5년 이하의 징역이나 금고에 처한다.', 9076);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15436, '①대한민국에 파견된 외국사절에 대하여 폭행 또는 협박을 가한 자는 5년 이하의 징역이나 금고에 처한다.', 9077);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15437, '②전항의 외국사절에 대하여 모욕을 가하거나 명예를 훼손한 자는 3년 이하의 징역이나 금고에 처한다', 9077);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15438, '①외국에 대하여 사전한 자는 1년 이상의 유기금고에 처한다.', 9080);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15439, '②전항의 미수범은 처벌한다.', 9080);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15440, '③제1항의 죄를 범할 목적으로 예비 또는 음모한 자는 3년 이하의 금고 또는 500만원 이하의 벌금에 처한다. 단 그 목적한 죄의 실행에 이르기 전에 자수한 때에는 감경 또는 면제한다. <개정 1995.12.29>', 9080);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15441, '①외교상의 기밀을 누설한 자는 5년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9082);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15442, '②누설할 목적으로 외교상의 기밀을 탐지 또는 수집한 자도 전항의 형과 같다.', 9082);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15443, '① 불특정 또는 다수의 사람의 생명, 신체에 위해를 가할 것을 내용으로 공연히 공중을 협박한 사람은 5년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.', 9086);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15444, '② 상습으로 제1항의 죄를 범한 때에는 그 죄에 정한 형의 2분의 1까지 가중한다.', 9086);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15445, '③ 제1항 및 제2항의 미수범은 처벌한다.', 9086);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15446, '①전쟁, 천재 기타 사변에 있어서 국가 또는 공공단체와 체결한 식량 기타 생활필수품의 공급계약을 정당한 이유없이 이행하지 아니한 자는 3년 이하의 징역 또는 500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9088);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15447, '②전항의 계약이행을 방해한 자도 전항의 형과 같다.', 9088);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15448, '③전 2항의 경우에는 그 소정의 벌금을 병과할 수 있다.', 9088);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15449, '① 폭발물을 사용하여 사람의 생명, 신체 또는 재산을 해하거나 그 밖에 공공의 안전을 문란하게 한 자는 사형, 무기 또는 7년 이상의 징역에 처한다.', 9090);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15450, '② 전쟁, 천재지변 그 밖의 사변에 있어서 제1항의 죄를 지은 자는 사형이나 무기징역에 처한다.', 9090);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15451, '③ 제1항과 제2항의 미수범은 처벌한다.', 9090);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15452, '①전조제1항, 제2항의 죄를 범할 목적으로 예비 또는 음모한 자는 2년 이상의 유기징역에 처한다. 단, 그 목적한 죄의 실행에 이르기 전에 자수한 때에는 그 형을 감경 또는 면제한다.', 9091);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15453, '②전조제1항, 제2항의 죄를 범할 것을 선동한 자도 전항의 형과 같다.', 9091);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15454, '①재판, 검찰, 경찰 기타 인신구속에 관한 직무를 행하는 자 또는 이를 보조하는 자가 그 직권을 남용하여 사람을 체포 또는 감금한 때에는 7년 이하의 징역과 10년 이하의 자격정지에 처한다.', 9095);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15455, '②전항의 미수범은 처벌한다.', 9095);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15456, '①공무원 또는 중재인이 그 직무에 관하여 뇌물을 수수, 요구 또는 약속한 때에는 5년 이하의 징역 또는 10년 이하의 자격정지에 처한다.', 9100);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15457, '②공무원 또는 중재인이 될 자가 그 담당할 직무에 관하여 청탁을 받고 뇌물을 수수, 요구 또는 약속한 후 공무원 또는 중재인이 된 때에는 3년 이하의 징역 또는 7년 이하의 자격정지에 처한다.', 9100);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15458, '①공무원 또는 중재인이 전2조의 죄를 범하여 부정한 행위를 한 때에는 1년 이상의 유기징역에 처한다.', 9102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15459, '②공무원 또는 중재인이 그 직무상 부정한 행위를 한 후 뇌물을 수수, 요구 또는 약속하거나 제삼자에게 이를 공여하게 하거나 공여를 요구 또는 약속한 때에도 전항의 형과 같다.', 9102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15460, '③공무원 또는 중재인이었던 자가 그 재직 중에 청탁을 받고 직무상 부정한 행위를 한 후 뇌물을 수수, 요구 또는 약속한 때에는 5년 이하의 징역 또는 10년 이하의 자격정지에 처한다.', 9102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15461, '④전3항의 경우에는 10년 이하의 자격정지를 병과할 수 있다.', 9102);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15462, '① 제129조부터 제132조까지에 기재한 뇌물을 약속, 공여 또는 공여의 의사를 표시한 자는 5년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.', 9104);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15463, '② 제1항의 행위에 제공할 목적으로 제3자에게 금품을 교부한 자 또는 그 사정을 알면서 금품을 교부받은 제3자도 제1항의 형에 처한다.', 9104);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15464, '①직무를 집행하는 공무원에 대하여 폭행 또는 협박한 자는 5년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9107);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15465, '②공무원에 대하여 그 직무상의 행위를 강요 또는 조지하거나 그 직을 사퇴하게 할 목적으로 폭행 또는 협박한 자도 전항의 형과 같다.', 9107);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15466, '①공무원이 그 직무에 관하여 실시한 봉인 또는 압류 기타 강제처분의 표시를 손상 또는 은닉하거나 기타 방법으로 그 효용을 해한 자는 5년 이하의 징역 또는 700만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9111);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15467, '②공무원이 그 직무에 관하여 봉함 기타 비밀장치한 문서 또는 도화를 개봉한 자도 제1항의 형과 같다. <개정 1995.12.29>', 9111);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15468, '③공무원이 그 직무에 관하여 봉함 기타 비밀장치한 문서, 도화 또는 전자기록등 특수매체기록을 기술적 수단을 이용하여 그 내용을 알아낸 자도 제1항의 형과 같다. <신설 1995.12.29>', 9111);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15469, '①공무소에서 사용하는 서류 기타 물건 또는 전자기록등 특수매체기록을 손상 또는 은닉하거나 기타 방법으로 그 효용을 해한 자는 7년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9113);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15470, '②공무소에서 사용하는 건조물, 선박, 기차 또는 항공기를 파괴한 자는 1년 이상 10년 이하의 징역에 처한다.', 9113);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15471, '①단체 또는 다중의 위력을 보이거나 위험한 물건을 휴대하여 제136조, 제138조와 제140조 내지 전조의 죄를 범한 때에는 각조에 정한 형의 2분의 1까지 가중한다.', 9116);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15472, '②제1항의 죄를 범하여 공무원을 상해에 이르게 한 때에는 3년 이상의 유기징역에 처한다. 사망에 이르게 한 때에는 무기 또는 5년 이상의 징역에 처한다. <개정 1995.12.29>', 9116);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15473, '① 법률에 따라 체포되거나 구금된 자가 도주한 경우에는 1년 이하의 징역에 처한다.', 9117);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15474, '② 제1항의 구금된 자가 천재지변이나 사변 그 밖에 법령에 따라 잠시 석방된 상황에서 정당한 이유없이 집합명령에 위반한 경우에도 제1항의 형에 처한다.', 9117);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15475, '①벌금 이상의 형에 해당하는 죄를 범한 자를 은닉 또는 도피하게 한 자는 3년 이하의 징역 또는 500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9123);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15476, '②친족 또는 동거의 가족이 본인을 위하여 전항의 죄를 범한 때에는 처벌하지 아니한다. <개정 2005.3.31>', 9123);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15477, '①법률에 의하여 선서한 증인이 허위의 진술을 한 때에는 5년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9124);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15478, '②형사사건 또는 징계사건에 관하여 피고인, 피의자 또는 징계혐의자를 모해할 목적으로 전항의 죄를 범한 때에는 10년 이하의 징역에 처한다.', 9124);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15479, '①타인의 형사사건 또는 징계사건에 관한 증거를 인멸, 은닉, 위조 또는 변조하거나 위조 또는 변조한 증거를 사용한 자는 5년 이하의 징역 또는 700만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15480, '②타인의 형사사건 또는 징계사건에 관한 증인을 은닉 또는 도피하게 한 자도 제1항의 형과 같다. <개정 1995.12.29>', 9127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15481, '③피고인, 피의자 또는 징계혐의자를 모해할 목적으로 전2항의 죄를 범한 자는 10년 이하의 징역에 처한다.', 9127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15482, '④친족 또는 동거의 가족이 본인을 위하여 본조의 죄를 범한 때에는 처벌하지 아니한다. <개정 2005.3.31>', 9127);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15483, '① 시체, 유골, 유발 또는 관 속에 넣어 둔 물건을 손괴(損壞), 유기, 은닉 또는 영득(領得)한 자는 7년 이하의 징역에 처한다.', 9133);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15484, '② 분묘를 발굴하여 제1항의 죄를 지은 자는 10년 이하의 징역에 처한다.', 9133);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15485, '① 불을 놓아 사람이 주거로 사용하거나 사람이 현존하는 건조물, 기차, 전차, 자동차, 선박, 항공기 또는 지하채굴시설을 불태운 자는 무기 또는 3년 이상의 징역에 처한다.', 9136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15486, '② 제1항의 죄를 지어 사람을 상해에 이르게 한 경우에는 무기 또는 5년 이상의 징역에 처한다. 사망에 이르게 한 경우에는 사형, 무기 또는 7년 이상의 징역에 처한다.', 9136);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15487, '① 불을 놓아 제164조와 제165조에 기재한 외의 건조물, 기차, 전차, 자동차, 선박, 항공기 또는 지하채굴시설을 불태운 자는 2년 이상의 유기징역에 처한다.', 9138);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15488, '② 자기 소유인 제1항의 물건을 불태워 공공의 위험을 발생하게 한 자는 7년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 9138);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15489, '① 불을 놓아 제164조부터 제166조까지에 기재한 외의 물건을 불태워 공공의 위험을 발생하게 한 자는 1년 이상 10년 이하의 징역에 처한다.', 9139);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15490, '② 제1항의 물건이 자기 소유인 경우에는 3년 이하의 징역 또는 700만원 이하의 벌금에 처한다.', 9139);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15491, '①제166조제2항 또는 전조제2항의 죄를 범하여 제164조, 제165조 또는 제166조제1항에 기재한 물건에 연소한 때에는 1년 이상 10년 이하의 징역에 처한다.', 9140);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15492, '②전조제2항의 죄를 범하여 전조제1항에 기재한 물건에 연소한 때에는 5년 이하의 징역에 처한다.', 9140);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15493, '① 과실로 제164조 또는 제165조에 기재한 물건 또는 타인 소유인 제166조에 기재한 물건을 불태운 자는 1천500만원 이하의 벌금에 처한다.', 9142);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15494, '② 과실로 자기 소유인 제166조의 물건 또는 제167조에 기재한 물건을 불태워 공공의 위험을 발생하게 한 자도 제1항의 형에 처한다.', 9142);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15495, '①보일러, 고압가스 기타 폭발성있는 물건을 파열시켜 사람의 생명, 신체 또는 재산에 대하여 위험을 발생시킨 자는 1년 이상의 유기징역에 처한다.', 9144);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15496, '②제1항의 죄를 범하여 사람을 상해에 이르게 한 때에는 무기 또는 3년 이상의 징역에 처한다. 사망에 이르게 한 때에는 무기 또는 5년 이상의 징역에 처한다.', 9144);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15497, '①가스, 전기, 증기 또는 방사선이나 방사성 물질을 방출, 유출 또는 살포시켜 사람의 생명, 신체 또는 재산에 대하여 위험을 발생시킨 자는 1년 이상 10년 이하의 징역에 처한다.', 9145);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15498, '②제1항의 죄를 범하여 사람을 상해에 이르게 한 때에는 무기 또는 3년 이상의 징역에 처한다. 사망에 이르게 한 때에는 무기 또는 5년 이상의 징역에 처한다.', 9145);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15499, '①가스, 전기 또는 증기의 공작물을 손괴 또는 제거하거나 기타 방법으로 가스, 전기 또는 증기의 공급이나 사용을 방해하여 공공의 위험을 발생하게 한 자는 1년 이상 10년 이하의 징역에 처한다. <개정 1995.12.29>', 9146);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15500, '②공공용의 가스, 전기 또는 증기의 공작물을 손괴 또는 제거하거나 기타 방법으로 가스, 전기 또는 증기의 공급이나 사용을 방해한 자도 전항의 형과 같다. <개정 1995.12.29>', 9146);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15501, '③제1항 또는 제2항의 죄를 범하여 사람을 상해에 이르게 한 때에는 2년 이상의 유기징역에 처한다. 사망에 이르게 한 때에는 무기 또는 3년이상의 징역에 처한다. <개정 1995.12.29>', 9146);
