INSERT INTO balaw.hang (id, content, jo_id) VALUES (15508, '③제176조의 규정은 본조의 경우에 준용한다.', 9153);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15509, '①과실로 인하여 제185조 내지 제187조의 죄를 범한 자는 1천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9163);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15510, '②업무상과실 또는 중대한 과실로 인하여 제185조 내지 제187조의 죄를 범한 자는 3년 이하의 금고 또는 2천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9163);
