INSERT INTO balaw.hang (id, content, jo_id) VALUES (15519, '③행사할 목적으로 외국에서 통용하는 외국의 화폐, 지폐 또는 은행권을 위조 또는 변조한 자는 10년 이하의 징역에 처한다.', 9181);
