INSERT INTO balaw.hang (id, content, jo_id) VALUES (15526, '②위조 또는 변조된 대한민국 또는 외국의 인지, 우표 기타 우편요금을 표시하는 증표를 행사하거나 행사할 목적으로 수입 또는 수출한 자도 제1항의 형과 같다. <개정 1995.12.29>', 9192);
