INSERT INTO balaw.hang (id, content, jo_id) VALUES (15531, '①행사할 목적으로 공무원 또는 공무소의 인장, 서명, 기명  또는 기호를 위조 또는 부정사용한 자는 5년 이하의 징역에 처한다.', 9215);
