INSERT INTO balaw.hang (id, content, jo_id) VALUES (15601, '② 13세 이상 16세 미만의 사람에 대하여 간음 또는 추행을 한 19세 이상의 자는 제297조, 제297조의2, 제298조, 제301조 또는 제301조의2의 예에 의한다. <신설 2020.5.19>', 9287);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15602, '①공연히 사실을 적시하여 사람의 명예를 훼손한 자는 2년 이하의 징역이나 금고 또는 500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15603, '②공연히 허위의 사실을 적시하여 사람의 명예를 훼손한 자는 5년 이하의 징역, 10년 이하의 자격정지 또는 1천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9291);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15604, '①사람을 비방할 목적으로 신문, 잡지 또는 라디오 기타 출판물에 의하여 제307조제1항의 죄를 범한 자는 3년 이하의 징역이나 금고 또는 700만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9293);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15605, '②제1항의 방법으로 제307조제2항의 죄를 범한 자는 7년 이하의 징역, 10년 이하의 자격정지 또는 1천500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9293);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15606, '①제308조와 제311조의 죄는 고소가 있어야 공소를 제기할 수 있다. <개정 1995.12.29>', 9296);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15607, '②제307조와 제309조의 죄는 피해자의 명시한 의사에 반하여 공소를 제기할 수 없다. <개정 1995.12.29>', 9296);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15608, '①제313조의 방법 또는 위력으로써 사람의 업무를 방해한 자는 5년 이하의 징역 또는 1천500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9298);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15609, '②컴퓨터등 정보처리장치 또는 전자기록등 특수매체기록을 손괴하거나 정보처리장치에 허위의 정보 또는 부정한 명령을 입력하거나 기타 방법으로 정보처리에 장애를 발생하게 하여 사람의 업무를 방해한 자도 제1항의 형과 같다. <신설 1995.12.29>', 9298);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15610, '①봉함 기타 비밀장치한 사람의 편지, 문서 또는 도화를 개봉한 자는 3년 이하의 징역이나 금고 또는 500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9300);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15611, '②봉함 기타 비밀장치한 사람의 편지, 문서, 도화 또는 전자기록등 특수매체기록을 기술적 수단을 이용하여 그 내용을 알아낸 자도 제1항의 형과 같다. <신설 1995.12.29>', 9300);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15612, '①의사, 한의사, 치과의사, 약제사, 약종상, 조산사, 변호사, 변리사, 공인회계사, 공증인, 대서업자나 그 직무상 보조자 또는 차등의 직에 있던 자가 그 직무처리중 지득한 타인의 비밀을 누설한 때에는 3년 이하의 징역이나 금고, 10년 이하의 자격정지 또는 700만원 이하의 벌금에 처한다. <개정 1995.12.29, 1997.12.13>', 9301);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15613, '②종교의 직에 있는 자 또는 있던 자가 그 직무상 지득한 사람의 비밀을 누설한 때에도 전항의 형과 같다.', 9301);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15614, '①사람의 주거, 관리하는 건조물, 선박이나 항공기 또는 점유하는 방실에 침입한 자는 3년 이하의 징역 또는 500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15615, '②전항의 장소에서 퇴거요구를 받고 응하지 아니한 자도 전항의 형과 같다.', 9303);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15616, '①폭행 또는 협박으로 사람의 권리행사를 방해하거나 의무없는 일을 하게 한 자는 5년 이하의 징역 또는 3천만원 이하의 벌금에 처한다. <개정 1995.12.29, 2016.1.6>', 9308);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15617, '② 단체 또는 다중의 위력을 보이거나 위험한 물건을 휴대하여 제1항의 죄를 범한 자는 10년 이하의 징역 또는 5천만원 이하의 벌금에 처한다. <신설 2016.1.6>', 9308);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15618, '① 폭행 또는 협박으로 타인의 점유에 속하는 자기의 물건을 강취(强取)한 자는 7년 이하의 징역 또는 10년 이하의 자격정지에 처한다.', 9314);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15619, '② 타인의 점유에 속하는 자기의 물건을 취거(取去)하는 과정에서 그 물건의 탈환에 항거하거나 체포를 면탈하거나 범죄의 흔적을 인멸할 목적으로 폭행 또는 협박한 때에도 제1항의 형에 처한다.', 9314);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15620, '③ 제1항과 제2항의 미수범은 처벌한다.', 9314);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15621, '①직계혈족, 배우자, 동거친족, 동거가족 또는 그 배우자간의 제323조의 죄는 그 형을 면제한다. <개정 2005.3.31>', 9317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15622, '②제1항이외의 친족간에 제323조의 죄를 범한 때에는 고소가 있어야 공소를 제기할 수 있다. <개정 1995.12.29>', 9317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15623, '③전 2항의 신분관계가 없는 공범에 대하여는 전 이항을 적용하지 아니한다.', 9317);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15624, '① 야간에 문이나 담 그 밖의 건조물의 일부를 손괴하고 제330조의 장소에 침입하여 타인의 재물을 절취한 자는 1년 이상 10년 이하의 징역에 처한다.', 9320);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15625, '② 흉기를 휴대하거나 2명 이상이 합동하여 타인의 재물을 절취한 자도 제1항의 형에 처한다.', 9320);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15626, '①야간에 사람의 주거, 관리하는 건조물, 선박이나 항공기 또는 점유하는 방실에 침입하여 제333조의 죄를 범한 자는 무기 또는 5년 이상의 징역에 처한다. <개정 1995.12.29>', 9324);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15627, '②흉기를 휴대하거나 2인 이상이 합동하여 전조의 죄를 범한 자도 전항의 형과 같다.', 9324);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15628, '①다중의 위력으로 해상에서 선박을 강취하거나 선박내에 침입하여 타인의 재물을 강취한 자는 무기 또는 7년 이상의 징역에 처한다.', 9330);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15629, '②제1항의 죄를 범한 자가 사람을 상해하거나 상해에 이르게 한때에는 무기 또는 10년 이상의 징역에 처한다. <개정 1995.12.29>', 9330);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15630, '③제1항의 죄를 범한 자가 사람을 살해 또는 사망에 이르게 하거나 강간한 때에는 사형 또는 무기징역에 처한다. <개정 1995.12.29, 2012.12.18>', 9330);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15631, '①사람을 기망하여 재물의 교부를 받거나 재산상의 이익을 취득한 자는 10년 이하의 징역 또는 2천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9337);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15632, '②전항의 방법으로 제삼자로 하여금 재물의 교부를 받게 하거나 재산상의 이익을 취득하게 한 때에도 전항의 형과 같다.', 9337);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15633, '① 미성년자의 사리분별력 부족 또는 사람의 심신장애를 이용하여 재물을 교부받거나 재산상 이익을 취득한 자는 10년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.', 9339);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15634, '② 제1항의 방법으로 제3자로 하여금 재물을 교부받게 하거나 재산상 이익을 취득하게 한 경우에도 제1항의 형에 처한다.', 9339);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15635, '① 사람의 곤궁하고 절박한 상태를 이용하여 현저하게 부당한 이익을 취득한 자는 3년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 9341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15636, '② 제1항의 방법으로 제3자로 하여금 부당한 이익을 취득하게 한 경우에도 제1항의 형에 처한다.', 9341);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15637, '①사람을 공갈하여 재물의 교부를 받거나 재산상의 이익을 취득한 자는 10년 이하의 징역 또는 2천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9342);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15638, '②전항의 방법으로 제삼자로 하여금 재물의 교부를 받게 하거나 재산상의 이익을 취득하게 한 때에도 전항의 형과 같다.', 9342);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15639, '①타인의 재물을 보관하는 자가 그 재물을 횡령하거나 그 반환을 거부한 때에는 5년 이하의 징역 또는 1천500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9348);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15640, '②타인의 사무를 처리하는 자가 그 임무에 위배하는 행위로써 재산상의 이익을 취득하거나 제삼자로 하여금 이를 취득하게 하여 본인에게 손해를 가한 때에도 전항의 형과 같다.', 9348);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15641, '① 타인의 사무를 처리하는 자가 그 임무에 관하여 부정한 청탁을 받고 재물 또는 재산상의 이익을 취득하거나 제3자로 하여금 이를 취득하게 한 때에는 5년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 2016.5.29>', 9350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15642, '② 제1항의 재물 또는 재산상 이익을 공여한 자는 2년 이하의 징역 또는 500만원 이하의 벌금에 처한다. <개정 2020.12.8>', 9350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15643, '③ 범인 또는 그 사정을 아는 제3자가 취득한 제1항의 재물은 몰수한다. 그 재물을 몰수하기 불가능하거나 재산상의 이익을 취득한 때에는 그 가액을 추징한다. <개정 2016.5.29, 2020.12.8>', 9350);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15644, '①유실물, 표류물 또는 타인의 점유를 이탈한 재물을 횡령한 자는 1년 이하의 징역이나 300만원 이하의 벌금 또는 과료에 처한다. <개정 1995.12.29>', 9353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15645, '②매장물을 횡령한 자도 전항의 형과 같다.', 9353);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15646, '①장물을 취득, 양도, 운반 또는 보관한 자는 7년 이하의 징역 또는 1천500만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15647, '②전항의 행위를 알선한 자도 전항의 형과 같다.', 9355);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15648, '①상습으로 전조의 죄를 범한 자는 1년 이상 10년 이하의 징역에 처한다.', 9356);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15649, '②제1항의 경우에는 10년 이하의 자격정지 또는 1천500만원 이하의 벌금을 병과할 수 있다. <개정 1995.12.29>', 9356);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15650, '①전3조의 죄를 범한 자와 피해자간에 제328조제1항, 제2항의 신분관계가 있는 때에는 동조의 규정을 준용한다.', 9358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15651, '②전3조의 죄를 범한 자와 본범간에 제328조제1항의 신분관계가 있는 때에는 그 형을 감경 또는 면제한다. 단, 신분관계가 없는 공범에 대하여는 예외로 한다.', 9358);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15652, '①전2조의 죄를 범하여 사람의 생명 또는 신체에 대하여 위험을 발생하게 한 때에는 1년 이상 10년 이하의 징역에 처한다.', 9361);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15653, '②제366조 또는 제367조의 죄를 범하여 사람을 상해에 이르게 한 때에는 1년 이상의 유기징역에 처한다. 사망에 이르게 한 때에는 3년 이상의 유기징역에 처한다. <개정 1995.12.29>', 9361);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15654, '①단체 또는 다중의 위력을 보이거나 위험한 물건을 휴대하여 제366조의 죄를 범한 때에는 5년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9362);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15655, '②제1항의 방법으로 제367조의 죄를 범한 때에는 1년 이상의 유기징역 또는 2천만원 이하의 벌금에 처한다. <개정 1995.12.29>', 9362);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15656, null, 9367);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15657, '① 법무부장관은 이 법의 목적을 효율적으로 달성하기 위하여 5년마다 형의 집행 및 수용자 처우에 관한 기본계획(이하 "기본계획"이라 한다)을 수립하고 추진하여야 한다.', 9371);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15658, '② 기본계획에는 다음 각 호의 사항이 포함되어야 한다.', 9371);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15659, '③ 법무부장관은 기본계획을 수립 또는 변경하려는 때에는 법원, 검찰 및 경찰 등 관계 기관과 협의하여야 한다.', 9371);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15660, '④ 법무부장관은 기본계획을 수립하기 위하여 실태조사와 수요예측 조사를 실시할 수 있다.', 9371);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15661, '⑤ 법무부장관은 기본계획을 수립하기 위하여 필요하다고 인정하는 경우에는 관계 기관의 장에게 필요한 자료를 요청할 수 있다. 이 경우 자료를 요청받은 관계 기관의 장은 특별한 사정이 없으면 요청에 따라야 한다.', 9371);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15662, '① 법무부장관은 형의 집행 및 수용자 처우에 관한 사항을 협의하기 위하여 법원, 검찰 및 경찰 등 관계 기관과 협의체를 설치하여 운영할 수 있다.', 9372);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15663, '② 제1항에 따른 협의체의 설치 및 운영 등에 필요한 사항은 대통령령으로 정한다.', 9372);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15664, '① 신설하는 교정시설은 수용인원이 500명 이내의 규모가 되도록 하여야 한다. 다만, 교정시설의 기능ㆍ위치나 그 밖의 사정을 고려하여 그 규모를 늘릴 수 있다. <개정 2020.2.4>', 9373);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15665, '② 교정시설의 거실ㆍ작업장ㆍ접견실이나 그 밖의 수용생활을 위한 설비는 그 목적과 기능에 맞도록 설치되어야 한다. 특히, 거실은 수용자가 건강하게 생활할 수 있도록 적정한 수준의 공간과 채광ㆍ통풍ㆍ난방을 위한 시설이 갖추어져야 한다.', 9373);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15666, '③ 법무부장관은 수용자에 대한 처우 및 교정시설의 유지ㆍ관리를 위한 적정한 인력을 확보하여야 한다. <신설 2019.4.23>', 9373);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15667, '① 법무부장관은 교정시설의 설치 및 운영에 관한 업무의 일부를 법인 또는 개인에게 위탁할 수 있다.', 9374);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15668, '② 제1항에 따라 위탁을 받을 수 있는 법인 또는 개인의 자격요건, 교정시설의 시설기준, 수용대상자의 선정기준, 수용자 처우의 기준, 위탁절차, 국가의 감독, 그 밖에 필요한 사항은 따로 법률로 정한다.', 9374);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15669, '① 판사와 검사는 직무상 필요하면 교정시설을 시찰할 수 있다.', 9376);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15670, '② 제1항의 판사와 검사 외의 사람은 교정시설을 참관하려면 학술연구 등 정당한 이유를 명시하여 교정시설의 장(이하 "소장"이라 한다)의 허가를 받아야 한다.', 9376);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15671, '① 수용자는 다음 각 호에 따라 구분하여 수용한다. <개정 2008.12.11>', 9378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15672, '② 교도소 및 구치소의 각 지소에는 교도소 또는 구치소에 준하여 수용자를 수용한다.', 9378);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15673, '① 다음 각 호의 어느 하나에 해당하는 사유가 있으면 교도소에 미결수용자를 수용할 수 있다.', 9379);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15674, '② 취사 등의 작업을 위하여 필요하거나 그 밖에 특별한 사정이 있으면 구치소에 수형자를 수용할 수 있다.', 9379);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15675, '③ 수형자가 소년교도소에 수용 중에 19세가 된 경우에도 교육ㆍ교화프로그램, 작업, 직업훈련 등을 실시하기 위하여 특히 필요하다고 인정되면 23세가 되기 전까지는 계속하여 수용할 수 있다. <개정 2008.12.11>', 9379);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15676, '④ 소장은 특별한 사정이 있으면 제11조의 구분수용 기준에 따라 다른 교정시설로 이송하여야 할 수형자를 6개월을 초과하지 아니하는 기간 동안 계속하여 수용할 수 있다.', 9379);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15677, '① 남성과 여성은 분리하여 수용한다.', 9380);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15678, '② 제12조에 따라 수형자와 미결수용자, 19세 이상의 수형자와 19세 미만의 수형자를 같은 교정시설에 수용하는 경우에는 서로 분리하여 수용한다. <개정 2008.12.11>', 9380);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15679, null, 9381);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15680, '① 소장은 법원ㆍ검찰청ㆍ경찰관서 등으로부터 처음으로 교정시설에 수용되는 사람(이하 "신입자"라 한다)에 대하여는 집행지휘서, 재판서, 그 밖에 수용에 필요한 서류를 조사한 후 수용한다.', 9383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15681, '② 소장은 신입자에 대하여는 지체 없이 신체ㆍ의류 및 휴대품을 검사하고 건강진단을 하여야 한다. <개정 2017.12.19>', 9383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15682, '③ 신입자는 제2항에 따라 소장이 실시하는 검사 및 건강진단을 받아야 한다. <신설 2015.3.27, 2017.12.19>', 9383);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15683, null, 9384);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15684, null, 9385);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15685, '① 소장은 다른 사람의 건강에 위해를 끼칠 우려가 있는 감염병에 걸린 사람의 수용을 거절할 수 있다. <개정 2009.12.29>', 9386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15686, '② 소장은 제1항에 따라 수용을 거절하였으면 그 사유를 지체 없이 수용지휘기관과 관할 보건소장에게 통보하고 법무부장관에게 보고하여야 한다.', 9386);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15687, '① 소장은 신입자 및 다른 교정시설로부터 이송되어 온 사람에 대하여 다른 사람과의 식별을 위하여 필요한 한도에서 사진촬영, 지문채취, 수용자 번호지정, 그 밖에 대통령령으로 정하는 조치를 하여야 한다.', 9387);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15688, '② 소장은 수용목적상 필요하면 수용 중인 사람에 대하여도 제1항의 조치를 할 수 있다.', 9387);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15689, '① 소장은 수용자의 수용ㆍ작업ㆍ교화ㆍ의료, 그 밖의 처우를 위하여 필요하거나 시설의 안전과 질서유지를 위하여 필요하다고 인정하면 법무부장관의 승인을 받아 수용자를 다른 교정시설로 이송할 수 있다.', 9388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15690, '② 법무부장관은 제1항의 이송승인에 관한 권한을 대통령령으로 정하는 바에 따라 지방교정청장에게 위임할 수 있다.', 9388);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15691, '① 소장은 수용자에게 건강유지에 적합한 의류ㆍ침구, 그 밖의 생활용품을 지급한다.', 9390);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15692, '② 의류ㆍ침구, 그 밖의 생활용품의 지급기준 등에 관하여 필요한 사항은 법무부령으로 정한다.', 9390);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15693, '① 소장은 수용자에게 건강상태, 나이, 부과된 작업의 종류, 그 밖의 개인적 특성을 고려하여 건강 및 체력을 유지하는 데에 필요한 음식물을 지급한다.', 9391);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15694, '② 음식물의 지급기준 등에 관하여 필요한 사항은 법무부령으로 정한다.', 9391);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15695, '① 수용자는 소장의 허가를 받아 자신의 비용으로 음식물ㆍ의류ㆍ침구, 그 밖에 수용생활에 필요한 물품을 구매할 수 있다.', 9392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15696, '② 물품의 자비구매 허가범위 등에 관하여 필요한 사항은 법무부령으로 정한다.', 9392);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15697, '① 소장은 수용자의 휴대금품을 교정시설에 보관한다. 다만, 휴대품이 다음 각 호의 어느 하나에 해당하는 것이면 수용자로 하여금 자신이 지정하는 사람에게 보내게 하거나 그 밖에 적당한 방법으로 처분하게 할 수 있다. <개정 2020.2.4>', 9393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15698, '② 소장은 수용자가 제1항 단서에 따라 처분하여야 할 휴대품을 상당한 기간 내에 처분하지 아니하면 폐기할 수 있다.', 9393);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15699, '① 수용자는 편지ㆍ도서, 그 밖에 수용생활에 필요한 물품을 법무부장관이 정하는 범위에서 지닐 수 있다. <개정 2020.2.4>', 9394);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15700, '② 소장은 제1항에 따라 법무부장관이 정하는 범위를 벗어난 물품으로서 교정시설에 특히 보관할 필요가 있다고 인정하지 아니하는 물품은 수용자로 하여금 자신이 지정하는 사람에게 보내게 하거나 그 밖에 적당한 방법으로 처분하게 할 수 있다. <개정 2020.2.4>', 9394);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15701, '③ 소장은 수용자가 제2항에 따라 처분하여야 할 물품을 상당한 기간 내에 처분하지 아니하면 폐기할 수 있다.', 9394);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15702, '① 수용자 외의 사람이 수용자에게 금품을 건네줄 것을 신청하는 때에는 소장은 다음 각 호의 어느 하나에 해당하지 아니하면 허가하여야 한다. <개정 2020.2.4>', 9395);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15703, '② 소장은 수용자 외의 사람이 수용자에게 주려는 금품이 제1항 각 호의 어느 하나에 해당하거나 수용자가 금품을 받지 아니하려는 경우에는 해당 금품을 보낸 사람에게 되돌려 보내야 한다. <개정 2020.2.4>', 9395);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15704, '③ 소장은 제2항의 경우에 금품을 보낸 사람을 알 수 없거나 보낸 사람의 주소가 불분명한 경우에는 금품을 다시 가지고 갈 것을 공고하여야 하며, 공고한 후 6개월이 지나도 금품을 돌려달라고 청구하는 사람이 없으면 그 금품은 국고에 귀속된다. <개정 2020.2.4>', 9395);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15705, '④ 소장은 제2항 또는 제3항에 따른 조치를 하였으면 그 사실을 수용자에게 알려 주어야 한다.', 9395);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15706, '① 소장은 사망자 또는 도주자가 남겨두고 간 금품이 있으면 사망자의 경우에는 그 상속인에게, 도주자의 경우에는 그 가족에게 그 내용 및 청구절차 등을 알려 주어야 한다. 다만, 썩거나 없어질 우려가 있는 것은 폐기할 수 있다. <개정 2020.2.4>', 9396);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15707, '② 소장은 상속인 또는 가족이 제1항의 금품을 내어달라고 청구하면 지체 없이 내어주어야 한다. 다만, 제1항에 따른 알림을 받은 날(알려줄 수가 없는 경우에는 청구사유가 발생한 날)부터 1년이 지나도 청구하지 아니하면 그 금품은 국고에 귀속된다. <개정 2020.2.4>', 9396);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15708, '① 소장은 수용자가 석방될 때 제25조에 따라 보관하고 있던 수용자의 휴대금품을 본인에게 돌려주어야 한다. 다만, 보관품을 한꺼번에 가져가기 어려운 경우 등 특별한 사정이 있어 수용자가 석방 시 소장에게 일정 기간 동안(1개월 이내의 범위로 한정한다) 보관품을 보관하여 줄 것을 신청하는 경우에는 그러하지 아니하다. <개정 2020.2.4>', 9397);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15709, '② 제1항 단서에 따른 보관 기간이 지난 보관품에 관하여는 제28조를 준용한다. 이 경우 "사망자" 및 "도주자"는 "피석방자"로, "금품"은 "보관품"으로, "상속인" 및 "가족"은 "피석방자 본인 또는 가족"으로 본다. <개정 2020.2.4>', 9397);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15710, '① 수용자는 자신의 신체 및 의류를 청결히 하여야 하며, 자신이 사용하는 거실ㆍ작업장, 그 밖의 수용시설의 청결유지에 협력하여야 한다.', 9400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15711, '② 수용자는 위생을 위하여 머리카락과 수염을 단정하게 유지하여야 한다. <개정 2020.2.4>', 9400);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15712, '① 소장은 수용자가 건강유지에 필요한 운동 및 목욕을 정기적으로 할 수 있도록 하여야 한다.', 9401);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15713, '② 운동시간ㆍ목욕횟수 등에 관하여 필요한 사항은 대통령령으로 정한다.', 9401);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15714, '① 소장은 수용자에 대하여 건강검진을 정기적으로 하여야 한다.', 9402);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15715, '② 건강검진의 횟수 등에 관하여 필요한 사항은 대통령령으로 정한다.', 9402);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15716, '①소장은 수용자가 부상을 당하거나 질병에 걸리면 적절한 치료를 받도록 하여야 한다. <개정 2010.5.4>', 9404);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15717, '② 제1항의 치료를 위하여 교정시설에 근무하는 간호사는 야간 또는 공휴일 등에 「의료법」 제27조에도 불구하고 대통령령으로 정하는 경미한 의료행위를 할 수 있다. <신설 2010.5.4>', 9404);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15718, '① 소장은 수용자에 대한 적절한 치료를 위하여 필요하다고 인정하면 교정시설 밖에 있는 의료시설(이하 "외부의료시설"이라 한다)에서 진료를 받게 할 수 있다.', 9405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15719, '② 소장은 수용자의 정신질환 치료를 위하여 필요하다고 인정하면 법무부장관의 승인을 받아 치료감호시설로 이송할 수 있다.', 9405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15720, '③ 제2항에 따라 이송된 사람은 수용자에 준하여 처우한다.', 9405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15721, '④ 소장은 제1항 또는 제2항에 따라 수용자가 외부의료시설에서 진료받거나 치료감호시설로 이송되면 그 사실을 그 가족(가족이 없는 경우에는 수용자가 지정하는 사람)에게 지체 없이 알려야 한다. 다만, 수용자가 알리는 것을 원하지 아니하면 그러하지 아니하다. <개정 2020.2.4>', 9405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15722, '⑤ 소장은 수용자가 자신의 고의 또는 중대한 과실로 부상 등이 발생하여 외부의료시설에서 진료를 받은 경우에는 그 진료비의 전부 또는 일부를 그 수용자에게 부담하게 할 수 있다.', 9405);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15723, '① 교정시설에는 수용자의 진료를 위하여 필요한 의료 인력과 설비를 갖추어야 한다.', 9407);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15724, '② 소장은 정신질환이 있다고 의심되는 수용자가 있으면 정신건강의학과 의사의 진료를 받을 수 있도록 하여야 한다. <개정 2011.8.4>', 9407);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15725, '③ 외부의사는 수용자를 진료하는 경우에는 법무부장관이 정하는 사항을 준수하여야 한다.', 9407);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15726, '④ 교정시설에 갖추어야 할 의료설비의 기준에 관하여 필요한 사항은 법무부령으로 정한다.', 9407);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15727, '① 소장은 수용자가 진료 또는 음식물의 섭취를 거부하면 의무관으로 하여금 관찰ㆍ조언 또는 설득을 하도록 하여야 한다.', 9408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15728, '② 소장은 제1항의 조치에도 불구하고 수용자가 진료 또는 음식물의 섭취를 계속 거부하여 그 생명에 위험을 가져올 급박한 우려가 있으면 의무관으로 하여금 적당한 진료 또는 영양보급 등의 조치를 하게 할 수 있다.', 9408);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15729, '① 수용자는 교정시설의 외부에 있는 사람과 접견할 수 있다. 다만, 다음 각 호의 어느 하나에 해당하는 사유가 있으면 그러하지 아니하다.', 9409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15730, '② 수용자의 접견은 접촉차단시설이 설치된 장소에서 하게 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 접촉차단시설이 설치되지 아니한 장소에서 접견하게 한다. <신설 2019.4.23, 2022.12.27>', 9409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15731, '③ 제2항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 접촉차단시설이 설치되지 아니한 장소에서 접견하게 할 수 있다. <신설 2019.4.23>', 9409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15732, '④ 소장은 다음 각 호의 어느 하나에 해당하는 사유가 있으면 교도관으로 하여금 수용자의 접견내용을 청취ㆍ기록ㆍ녹음 또는 녹화하게 할 수 있다. <개정 2019.4.23>', 9409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15733, '⑤ 제4항에 따라 녹음ㆍ녹화하는 경우에는 사전에 수용자 및 그 상대방에게 그 사실을 알려 주어야 한다. <개정 2019.4.23>', 9409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15734, '⑥ 접견의 횟수ㆍ시간ㆍ장소ㆍ방법 및 접견내용의 청취ㆍ기록ㆍ녹음ㆍ녹화 등에 관하여 필요한 사항은 대통령령으로 정한다. <개정 2019.4.23>', 9409);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15735, null, 9410);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15736, '① 수용자는 다른 사람과 편지를 주고받을 수 있다. 다만, 다음 각 호의 어느 하나에 해당하는 사유가 있으면 그러하지 아니하다. <개정 2020.2.4>', 9411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15737, '② 제1항 각 호 외의 부분 본문에도 불구하고 같은 교정시설의 수용자 간에 편지를 주고받으려면 소장의 허가를 받아야 한다. <개정 2020.2.4>', 9411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15738, '③ 소장은 수용자가 주고받는 편지에 법령에 따라 금지된 물품이 들어 있는지 확인할 수 있다. <개정 2020.2.4>', 9411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15739, '④ 수용자가 주고받는 편지의 내용은 검열받지 아니한다. 다만, 다음 각 호의 어느 하나에 해당하는 사유가 있으면 그러하지 아니하다. <개정 2020.2.4>', 9411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15740, '⑤ 소장은 제3항 또는 제4항 단서에 따라 확인 또는 검열한 결과 수용자의 편지에 법령으로 금지된 물품이 들어 있거나 편지의 내용이 다음 각 호의 어느 하나에 해당하면 발신 또는 수신을 금지할 수 있다. <개정 2020.2.4>', 9411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15741, '⑥ 소장이 편지를 발송하거나 내어주는 경우에는 신속히 하여야 한다. <개정 2020.2.4>', 9411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15742, '⑦ 소장은 제1항 단서 또는 제5항에 따라 발신 또는 수신이 금지된 편지는 그 구체적인 사유를 서면으로 작성해 관리하고, 수용자에게 그 사유를 알린 후 교정시설에 보관한다. 다만, 수용자가 동의하면 폐기할 수 있다. <개정 2019.4.23, 2020.2.4>', 9411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15743, '⑧ 편지발송의 횟수, 편지 내용물의 확인방법 및 편지 내용의 검열절차 등에 관하여 필요한 사항은 대통령령으로 정한다. <개정 2020.2.4>', 9411);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15744, '① 수용자는 소장의 허가를 받아 교정시설의 외부에 있는 사람과 전화통화를 할 수 있다.', 9412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15745, '② 제1항에 따른 허가에는 통화내용의 청취 또는 녹음을 조건으로 붙일 수 있다.', 9412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15746, '③ 제42조는 수용자의 전화통화에 관하여 준용한다.', 9412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15747, '④ 제2항에 따라 통화내용을 청취 또는 녹음하려면 사전에 수용자 및 상대방에게 그 사실을 알려 주어야 한다.', 9412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15748, '⑤ 전화통화의 허가범위, 통화내용의 청취ㆍ녹음 등에 관하여 필요한 사항은 법무부령으로 정한다.', 9412);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15749, '① 수용자는 교정시설의 안에서 실시하는 종교의식 또는 행사에 참석할 수 있으며, 개별적인 종교상담을 받을 수 있다.', 9413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15750, '② 수용자는 자신의 신앙생활에 필요한 책이나 물품을 지닐 수 있다. <개정 2020.2.4>', 9413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15751, '③ 소장은 다음 각 호의 어느 하나에 해당하는 사유가 있으면 제1항 및 제2항에서 규정하고 있는 사항을 제한할 수 있다.', 9413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15752, '④ 종교행사의 종류ㆍ참석대상ㆍ방법, 종교상담의 대상ㆍ방법 및 종교도서ㆍ물품을 지닐 수 있는 범위 등에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2020.2.4>', 9413);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15753, '① 수용자는 자신의 비용으로 신문ㆍ잡지 또는 도서(이하 "신문등" 이라 한다)의 구독을 신청할 수 있다.', 9415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15754, '② 소장은 제1항에 따라 구독을 신청한 신문등이 「출판문화산업 진흥법」에 따른 유해간행물인 경우를 제외하고는 구독을 허가하여야 한다.', 9415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15755, '③ 제1항에 따라 구독을 신청할 수 있는 신문등의 범위 및 수량은 법무부령으로 정한다.', 9415);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15756, '① 수용자는 정서안정 및 교양습득을 위하여 라디오 청취와 텔레비전 시청을 할 수 있다.', 9416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15757, '② 소장은 다음 각 호의 어느 하나에 해당하는 사유가 있으면 수용자에 대한 라디오 및 텔레비전의 방송을 일시 중단하거나 개별 수용자에 대하여 라디오 및 텔레비전의 청취 또는 시청을 금지할 수 있다.', 9416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15758, '③ 방송설비ㆍ방송프로그램ㆍ방송시간 등에 관하여 필요한 사항은 법무부령으로 정한다.', 9416);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15759, '① 수용자는 문서 또는 도화(<img src="http://www.law.go.kr/flDownload.do?flSeq=56450713"  alt="img56450713" >圖</img>)를 작성하거나 문예ㆍ학술, 그 밖의 사항에 관하여 집필할 수 있다. 다만, 소장이 시설의 안전 또는 질서를 해칠 명백한 위험이 있다고 인정하는 경우는 예외로 한다. <개정 2020.2.4>', 9417);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15760, '② 제1항에 따라 작성 또는 집필한 문서나 도화를 지니거나 처리하는 것에 관하여는 제26조를 준용한다. <개정 2020.2.4>', 9417);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15761, '③ 제1항에 따라 작성 또는 집필한 문서나 도화가 제43조제5항 각 호의 어느 하나에 해당하면 제43조제7항을 준용한다.', 9417);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15762, '④ 집필용구의 관리, 집필의 시간ㆍ장소, 집필한 문서 또는 도화의 외부반출 등에 관하여 필요한 사항은 대통령령으로 정한다.', 9417);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15763, '① 소장은 여성수용자에 대하여 여성의 신체적ㆍ심리적 특성을 고려하여 처우하여야 한다.', 9418);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15764, '② 소장은 여성수용자에 대하여 건강검진을 실시하는 경우에는 나이ㆍ건강 등을 고려하여 부인과질환에 관한 검사를 포함시켜야 한다. <개정 2014.12.30>', 9418);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15765, '③ 소장은 생리 중인 여성수용자에 대하여는 위생에 필요한 물품을 지급하여야 한다. <개정 2014.12.30>', 9418);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15766, '④ 삭제 <2019.4.23>', 9418);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15767, '① 소장은 여성수용자에 대하여 상담ㆍ교육ㆍ작업 등(이하 이 조에서 "상담등"이라 한다)을 실시하는 때에는 여성교도관이 담당하도록 하여야 한다. 다만, 여성교도관이 부족하거나 그 밖의 부득이한 사정이 있으면 그러하지 아니하다.', 9419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15768, '② 제1항 단서에 따라 남성교도관이 1인의 여성수용자에 대하여 실내에서 상담등을 하려면 투명한 창문이 설치된 장소에서 다른 여성을 입회시킨 후 실시하여야 한다.', 9419);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15769, '① 소장은 수용자가 임신 중이거나 출산(유산ㆍ사산을 포함한다)한 경우에는 모성보호 및 건강유지를 위하여 정기적인 검진 등 적절한 조치를 하여야 한다. <개정 2019.4.23>', 9420);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15770, '② 소장은 수용자가 출산하려고 하는 경우에는 외부의료시설에서 진료를 받게 하는 등 적절한 조치를 하여야 한다.', 9420);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15771, '① 여성수용자는 자신이 출산한 유아를 교정시설에서 양육할 것을 신청할 수 있다. 이 경우 소장은 다음 각 호의 어느 하나에 해당하는 사유가 없으면, 생후 18개월에 이르기까지 허가하여야 한다. <개정 2009.12.29>', 9421);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15772, '② 소장은 제1항에 따라 유아의 양육을 허가한 경우에는 필요한 설비와 물품의 제공, 그 밖에 양육을 위하여 필요한 조치를 하여야 한다.', 9421);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15773, '① 소장은 신입자에게 「아동복지법」 제15조에 따른 보호조치를 의뢰할 수 있음을 알려주어야 한다.', 9422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15774, '② 소장은 수용자가 「아동복지법」 제15조에 따른 보호조치를 의뢰하려는 경우 보호조치 의뢰가 원활하게 이루어질 수 있도록 지원하여야 한다.', 9422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15775, '③ 제1항에 따른 안내 및 제2항에 따른 보호조치 의뢰 지원의 방법ㆍ절차, 그 밖에 필요한 사항은 법무부장관이 정한다.', 9422);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15776, '① 소장은 노인수용자에 대하여 나이ㆍ건강상태 등을 고려하여 그 처우에 있어 적정한 배려를 하여야 한다.', 9423);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15777, '② 소장은 장애인수용자에 대하여 장애의 정도를 고려하여 그 처우에 있어 적정한 배려를 하여야 한다.', 9423);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15778, '③ 소장은 외국인수용자에 대하여 언어ㆍ생활문화 등을 고려하여 적정한 처우를 하여야 한다.', 9423);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15779, '④ 소장은 소년수용자에 대하여 나이ㆍ적성 등을 고려하여 적정한 처우를 하여야 한다. <신설 2015.3.27>', 9423);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15780, '⑤ 노인수용자ㆍ장애인수용자ㆍ외국인수용자 및 소년수용자에 대한 적정한 배려 또는 처우에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2015.3.27>', 9423);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15781, '① 소장은 제62조의 분류처우위원회의 의결에 따라 수형자의 개별적 특성에 알맞은 교육ㆍ교화프로그램, 작업, 직업훈련 등의 처우에 관한 계획(이하 "개별처우계획"이라 한다)을 수립하여 시행한다.', 9425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15782, '② 소장은 수형자가 스스로 개선하여 사회에 복귀하려는 의욕이 고취되도록 개별처우계획을 정기적으로 또는 수시로 점검하여야 한다.', 9425);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15783, '① 수형자는 제59조의 분류심사의 결과에 따라 그에 적합한 교정시설에 수용되며, 개별처우계획에 따라 그 특성에 알맞은 처우를 받는다.', 9426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15784, '② 교정시설은 도주방지 등을 위한 수용설비 및 계호의 정도(이하 "경비등급"이라 한다)에 따라 다음 각 호로 구분한다. 다만, 동일한 교정시설이라도 구획을 정하여 경비등급을 달리할 수 있다.', 9426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15785, '③ 수형자에 대한 처우는 교화 또는 건전한 사회복귀를 위하여 교정성적에 따라 상향 조정될 수 있으며, 특히 그 성적이 우수한 수형자는 개방시설에 수용되어 사회생활에 필요한 적정한 처우를 받을 수 있다.', 9426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15786, '④ 소장은 가석방 또는 형기 종료를 앞둔 수형자 중에서 법무부령으로 정하는 일정한 요건을 갖춘 사람에 대해서는 가석방 또는 형기 종료 전 일정 기간 동안 지역사회 또는 교정시설에 설치된 개방시설에 수용하여 사회적응에 필요한 교육, 취업지원 등의 적정한 처우를 할 수 있다. <신설 2015.3.27>', 9426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15787, '⑤ 수형자는 교화 또는 건전한 사회복귀를 위하여 교정시설 밖의 적당한 장소에서 봉사활동ㆍ견학, 그 밖에 사회적응에 필요한 처우를 받을 수 있다. <개정 2015.3.27>', 9426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15788, '⑥ 학과교육생ㆍ직업훈련생ㆍ외국인ㆍ여성ㆍ장애인ㆍ노인ㆍ환자ㆍ소년(19세 미만인 자를 말한다), 제4항에 따른 처우(이하 "중간처우"라 한다)의 대상자, 그 밖에 별도의 처우가 필요한 수형자는 법무부장관이 특히 그 처우를 전담하도록 정하는 시설(이하 "전담교정시설"이라 한다)에 수용되며, 그 특성에 알맞은 처우를 받는다. 다만, 전담교정시설의 부족이나 그 밖의 부득이한 사정이 있는 경우에는 예외로 할 수 있다. <개정 2015.3.27>', 9426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15789, '⑦ 제2항 각 호의 시설의 설비 및 계호의 정도에 관하여 필요한 사항은 대통령령으로 정한다. <개정 2015.3.27>', 9426);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15790, '① 소장은 수형자에 대한 개별처우계획을 합리적으로 수립하고 조정하기 위하여 수형자의 인성, 행동특성 및 자질 등을 과학적으로 조사ㆍ측정ㆍ평가(이하 "분류심사"라 한다)하여야 한다. 다만, 집행할 형기가 짧거나 그 밖의 특별한 사정이 있는 경우에는 예외로 할 수 있다.', 9428);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15791, '② 수형자의 분류심사는 형이 확정된 경우에 개별처우계획을 수립하기 위하여 하는 심사와 일정한 형기가 지나거나 상벌 또는 그 밖의 사유가 발생한 경우에 개별처우계획을 조정하기 위하여 하는 심사로 구분한다.', 9428);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15792, '③ 소장은 분류심사를 위하여 수형자를 대상으로 상담 등을 통한 신상에 관한 개별사안의 조사, 심리ㆍ지능ㆍ적성 검사, 그 밖에 필요한 검사를 할 수 있다.', 9428);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15793, '④ 소장은 분류심사를 위하여 외부전문가로부터 필요한 의견을 듣거나 외부전문가에게 조사를 의뢰할 수 있다.', 9428);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15794, '⑤ 이 법에 규정된 사항 외에 분류심사에 관하여 필요한 사항은 법무부령으로 정한다.', 9428);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15795, '① 소장은 분류심사와 그 밖에 수용목적의 달성을 위하여 필요하면 수용자의 가족 등을 면담하거나 법원ㆍ경찰관서, 그 밖의 관계 기관 또는 단체(이하 "관계기관등"이라 한다)에 대하여 필요한 사실을 조회할 수 있다.', 9429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15796, '② 제1항의 조회를 요청받은 관계기관등의 장은 특별한 사정이 없으면 지체 없이 그에 관하여 답하여야 한다. <개정 2020.2.4>', 9429);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15797, '① 수형자의 개별처우계획, 가석방심사신청 대상자 선정, 그 밖에 수형자의 분류처우에 관한 중요 사항을 심의ㆍ의결하기 위하여 교정시설에 분류처우위원회(이하 이 조에서 "위원회"라 한다)를 둔다.', 9431);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15798, '② 위원회는 위원장을 포함한 5명 이상 7명 이하의 위원으로 구성하고, 위원장은 소장이 되며, 위원은 위원장이 소속 기관의 부소장 및 과장(지소의 경우에는 7급 이상의 교도관) 중에서 임명한다. <개정 2020.2.4>', 9431);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15799, '③ 위원회는 그 심의ㆍ의결을 위하여 외부전문가로부터 의견을 들을 수 있다.', 9431);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15800, '④ 이 법에 규정된 사항 외에 위원회에 관하여 필요한 사항은 법무부령으로 정한다.', 9431);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15801, '① 소장은 수형자가 건전한 사회복귀에 필요한 지식과 소양을 습득하도록 교육할 수 있다.', 9432);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15802, '② 소장은 「교육기본법」 제8조의 의무교육을 받지 못한 수형자에 대하여는 본인의 의사ㆍ나이ㆍ지식정도, 그 밖의 사정을 고려하여 그에 알맞게 교육하여야 한다.', 9432);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15803, '③ 소장은 제1항 및 제2항에 따른 교육을 위하여 필요하면 수형자를 중간처우를 위한 전담교정시설에 수용하여 다음 각 호의 조치를 할 수 있다. <개정 2015.3.27>', 9432);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15804, '④ 교육과정ㆍ외부통학ㆍ위탁교육 등에 관하여 필요한 사항은 법무부령으로 정한다.', 9432);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15805, '① 소장은 수형자의 교정교화를 위하여 상담ㆍ심리치료, 그 밖의 교화프로그램을 실시하여야 한다.', 9433);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15806, '② 소장은 제1항에 따른 교화프로그램의 효과를 높이기 위하여 범죄원인별로 적절한 교화프로그램의 내용, 교육장소 및 전문인력의 확보 등 적합한 환경을 갖추도록 노력하여야 한다. <신설 2019.4.23>', 9433);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15807, '③ 교화프로그램의 종류ㆍ내용 등에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2019.4.23>', 9433);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15808, '① 수형자에게 부과하는 작업은 건전한 사회복귀를 위하여 기술을 습득하고 근로의욕을 고취하는 데에 적합한 것이어야 한다.', 9434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15809, '② 소장은 수형자에게 작업을 부과하려면 나이ㆍ형기ㆍ건강상태ㆍ기술ㆍ성격ㆍ취미ㆍ경력ㆍ장래생계, 그 밖의 수형자의 사정을 고려하여야 한다.', 9434);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15810, '① 소장은 수형자의 건전한 사회복귀와 기술습득을 촉진하기 위하여 필요하면 외부기업체 등에 통근 작업하게 하거나 교정시설의 안에 설치된 외부기업체의 작업장에서 작업하게 할 수 있다.', 9437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15811, '② 외부 통근 작업 대상자의 선정기준 등에 관하여 필요한 사항은 법무부령으로 정한다.', 9437);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15812, '① 소장은 수형자의 건전한 사회복귀를 위하여 기술 습득 및 향상을 위한 직업능력개발훈련(이하 "직업훈련"이라 한다)을 실시할 수 있다.', 9438);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15813, '② 소장은 수형자의 직업훈련을 위하여 필요하면 외부의 기관 또는 단체에서 훈련을 받게 할 수 있다.', 9438);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15814, '③ 직업훈련 대상자의 선정기준 등에 관하여 필요한 사항은 법무부령으로 정한다.', 9438);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15815, '① 소장은 수형자의 신청에 따라 제68조의 작업, 제69조제2항의 훈련, 그 밖에 집중적인 근로가 필요한 작업을 부과하는 경우에는 접견ㆍ전화통화ㆍ교육ㆍ공동행사 참가 등의 처우를 제한할 수 있다. 다만, 접견 또는 전화통화를 제한한 때에는 휴일이나 그 밖에 해당 수용자의 작업이 없는 날에 접견 또는 전화통화를 할 수 있게 하여야 한다.', 9439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15816, '② 소장은 제1항에 따라 작업을 부과하거나 훈련을 받게 하기 전에 수형자에게 제한되는 처우의 내용을 충분히 설명하여야 한다.', 9439);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15817, '① 1일의 작업시간(휴식ㆍ운동ㆍ식사ㆍ접견 등 실제 작업을 실시하지 않는 시간을 제외한다. 이하 같다)은 8시간을 초과할 수 없다.', 9440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15818, '② 제1항에도 불구하고 취사ㆍ청소ㆍ간병 등 교정시설의 운영과 관리에 필요한 작업의 1일 작업시간은 12시간 이내로 한다.', 9440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15819, '③ 1주의 작업시간은 52시간을 초과할 수 없다. 다만, 수형자가 신청하는 경우에는 1주의 작업시간을 8시간 이내의 범위에서 연장할 수 있다.', 9440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15820, '④ 제2항 및 제3항에도 불구하고 19세 미만 수형자의 작업시간은 1일에 8시간을, 1주에 40시간을 초과할 수 없다.', 9440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15821, '⑤ 공휴일ㆍ토요일과 대통령령으로 정하는 휴일에는 작업을 부과하지 아니한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 작업을 부과할 수 있다.', 9440);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15822, '① 소장은 수형자의 가족 또는 배우자의 직계존속이 사망하면 2일간, 부모 또는 배우자의 제삿날에는 1일간 해당 수형자의 작업을 면제한다. 다만, 수형자가 작업을 계속하기를 원하는 경우는 예외로 한다. <개정 2020.2.4>', 9441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15823, '② 소장은 수형자에게 부상ㆍ질병, 그 밖에 작업을 계속하기 어려운 특별한 사정이 있으면 그 사유가 해소될 때까지 작업을 면제할 수 있다.', 9441);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15824, '① 작업수입은 국고수입으로 한다.', 9442);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15825, '② 소장은 수형자의 근로의욕을 고취하고 건전한 사회복귀를 지원하기 위하여 법무부장관이 정하는 바에 따라 작업의 종류, 작업성적, 교정성적, 그 밖의 사정을 고려하여 수형자에게 작업장려금을 지급할 수 있다.', 9442);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15826, '③ 제2항의 작업장려금은 석방할 때에 본인에게 지급한다. 다만, 본인의 가족생활 부조, 교화 또는 건전한 사회복귀를 위하여 특히 필요하면 석방 전이라도 그 전부 또는 일부를 지급할 수 있다.', 9442);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15827, '① 소장은 수형자가 다음 각 호의 어느 하나에 해당하면 법무부장관이 정하는 바에 따라 위로금 또는 조위금을 지급한다.', 9443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15828, '② 위로금은 본인에게 지급하고, 조위금은 그 상속인에게 지급한다. <개정 2022.12.27>', 9443);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15829, '① 제74조의 위로금 또는 조위금을 지급받을 권리는 다른 사람 또는 법인에게 양도하거나 담보로 제공할 수 없으며, 다른 사람 또는 법인은 이를 압류할 수 없다.', 9445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15830, '② 제74조에 따라 지급받은 금전을 표준으로 하여 조세와 그 밖의 공과금(公課金)을 부과하여서는 아니 된다.', 9445);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15831, '① 소장은 6개월 이상 형을 집행받은 수형자로서 그 형기의 3분의 1(21년 이상의 유기형 또는 무기형의 경우에는 7년)이 지나고 교정성적이 우수한 사람이 다음 각 호의 어느 하나에 해당하면 1년 중 20일 이내의 귀휴를 허가할 수 있다. <개정 2020.2.4>', 9446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15832, '② 소장은 다음 각 호의 어느 하나에 해당하는 사유가 있는 수형자에 대하여는 제1항에도 불구하고 5일 이내의 특별귀휴를 허가할 수 있다.', 9446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15833, '③ 소장은 귀휴를 허가하는 경우에 법무부령으로 정하는 바에 따라 거소의 제한이나 그 밖에 필요한 조건을 붙일 수 있다.', 9446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15834, '④ 제1항 및 제2항의 귀휴기간은 형 집행기간에 포함한다.', 9446);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15835, null, 9447);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15836, '① 제41조제4항에도 불구하고 미결수용자와 변호인과의 접견에는 교도관이 참여하지 못하며 그 내용을 청취 또는 녹취하지 못한다. 다만, 보이는 거리에서 미결수용자를 관찰할 수 있다. <개정 2019.4.23, 2022.12.27>', 9453);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15837, '② 미결수용자와 변호인 간의 접견은 시간과 횟수를 제한하지 아니한다.', 9453);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15838, '③ 제43조제4항 단서에도 불구하고 미결수용자와 변호인 간의 편지는 교정시설에서 상대방이 변호인임을 확인할 수 없는 경우를 제외하고는 검열할 수 없다. <개정 2020.2.4>', 9453);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15839, '① 소장은 미결수용자에 대하여는 신청에 따라 교육 또는 교화프로그램을 실시하거나 작업을 부과할 수 있다.', 9455);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15840, '② 제1항에 따라 미결수용자에게 교육 또는 교화프로그램을 실시하거나 작업을 부과하는 경우에는 제63조부터 제65조까지 및 제70조부터 제76조까지의 규정을 준용한다.', 9455);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15841, '① 사형확정자는 독거수용한다. 다만, 자살방지, 교육ㆍ교화프로그램, 작업, 그 밖의 적절한 처우를 위하여 필요한 경우에는 법무부령으로 정하는 바에 따라 혼거수용할 수 있다.', 9458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15842, '② 사형확정자가 수용된 거실은 참관할 수 없다.', 9458);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15843, '① 소장은 사형확정자의 심리적 안정 및 원만한 수용생활을 위하여 교육 또는 교화프로그램을 실시하거나 신청에 따라 작업을 부과할 수 있다. <개정 2008.12.11>', 9459);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15844, '② 사형확정자에 대한 교육ㆍ교화프로그램, 작업, 그 밖의 처우에 필요한 사항은 법무부령으로 정한다. <개정 2008.12.11>', 9459);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15845, '① 사형은 교정시설의 사형장에서 집행한다.', 9460);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15846, '② 공휴일과 토요일에는 사형을 집행하지 아니한다.', 9460);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15847, '① 수용자는 다음 각 호의 물품을 지녀서는 아니 된다. <개정 2019.4.23, 2020.2.4>', 9461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15848, '② 제1항에도 불구하고 소장이 수용자의 처우를 위하여 허가하는 경우에는 제1항제2호의 물품을 지닐 수 있다. <신설 2019.4.23, 2020.2.4>', 9461);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15849, '① 교도관은 시설의 안전과 질서유지를 위하여 필요하면 수용자의 신체ㆍ의류ㆍ휴대품ㆍ거실 및 작업장 등을 검사할 수 있다.', 9462);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15850, '② 수용자의 신체를 검사하는 경우에는 불필요한 고통이나 수치심을 느끼지 아니하도록 유의하여야 하며, 특히 신체를 면밀하게 검사할 필요가 있으면 다른 수용자가 볼 수 없는 차단된 장소에서 하여야 한다.', 9462);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15851, '③ 교도관은 시설의 안전과 질서유지를 위하여 필요하면 교정시설을 출입하는 수용자 외의 사람에 대하여 의류와 휴대품을 검사할 수 있다. 이 경우 출입자가 제92조의 금지물품을 지니고 있으면 교정시설에 맡기도록 하여야 하며, 이에 따르지 아니하면 출입을 금지할 수 있다. <개정 2020.2.4>', 9462);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15852, '④ 여성의 신체ㆍ의류 및 휴대품에 대한 검사는 여성교도관이 하여야 한다.', 9462);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15853, '⑤ 소장은 제1항에 따라 검사한 결과 제92조의 금지물품이 발견되면 형사 법령으로 정하는 절차에 따라 처리할 물품을 제외하고는 수용자에게 알린 후 폐기한다. 다만, 폐기하는 것이 부적당한 물품은 교정시설에 보관하거나 수용자로 하여금 자신이 지정하는 사람에게 보내게 할 수 있다. <개정 2020.2.4>', 9462);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15854, '① 교도관은 자살ㆍ자해ㆍ도주ㆍ폭행ㆍ손괴, 그 밖에 수용자의 생명ㆍ신체를 해하거나 시설의 안전 또는 질서를 해하는 행위(이하 "자살등"이라 한다)를 방지하기 위하여 필요한 범위에서 전자장비를 이용하여 수용자 또는 시설을 계호할 수 있다. 다만, 전자영상장비로 거실에 있는 수용자를 계호하는 것은 자살등의 우려가 큰 때에만 할 수 있다.', 9463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15855, '② 제1항 단서에 따라 거실에 있는 수용자를 전자영상장비로 계호하는 경우에는 계호직원ㆍ계호시간 및 계호대상 등을 기록하여야 한다. 이 경우 수용자가 여성이면 여성교도관이 계호하여야 한다.', 9463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15856, '③ 제1항 및 제2항에 따라 계호하는 경우에는 피계호자의 인권이 침해되지 아니하도록 유의하여야 한다.', 9463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15857, '④ 전자장비의 종류ㆍ설치장소ㆍ사용방법 및 녹화기록물의 관리 등에 관하여 필요한 사항은 법무부령으로 정한다.', 9463);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15858, '① 소장은 수용자가 다음 각 호의 어느 하나에 해당하면 의무관의 의견을 고려하여 보호실(자살 및 자해 방지 등의 설비를 갖춘 거실을 말한다. 이하 같다)에 수용할 수 있다.', 9464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15859, '② 수용자의 보호실 수용기간은 15일 이내로 한다. 다만, 소장은 특히 계속하여 수용할 필요가 있으면 의무관의 의견을 고려하여 1회당 7일의 범위에서 기간을 연장할 수 있다. <개정 2019.4.23>', 9464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15860, '③ 제2항에 따라 수용자를 보호실에 수용할 수 있는 기간은 계속하여 3개월을 초과할 수 없다. <개정 2019.4.23>', 9464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15861, '④ 소장은 수용자를 보호실에 수용하거나 수용기간을 연장하는 경우에는 그 사유를 본인에게 알려 주어야 한다.', 9464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15862, '⑤ 의무관은 보호실 수용자의 건강상태를 수시로 확인하여야 한다.', 9464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15863, '⑥ 소장은 보호실 수용사유가 소멸한 경우에는 보호실 수용을 즉시 중단하여야 한다.', 9464);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15864, '① 소장은 수용자가 다음 각 호의 어느 하나에 해당하는 경우로서 강제력을 행사하거나 제98조의 보호장비를 사용하여도 그 목적을 달성할 수 없는 경우에만 진정실(일반 수용거실로부터 격리되어 있고 방음설비 등을 갖춘 거실을 말한다. 이하 같다)에 수용할 수 있다. <개정 2016.5.29>', 9465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15865, '② 수용자의 진정실 수용기간은 24시간 이내로 한다. 다만, 소장은 특히 계속하여 수용할 필요가 있으면 의무관의 의견을 고려하여 1회당 12시간의 범위에서 기간을 연장할 수 있다. <개정 2019.4.23>', 9465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15866, '③ 제2항에 따라 수용자를 진정실에 수용할 수 있는 기간은 계속하여 3일을 초과할 수 없다. <개정 2019.4.23>', 9465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15867, '④ 진정실 수용자에 대하여는 제95조제4항부터 제6항까지의 규정을 준용한다.', 9465);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15868, '① 교도관은 수용자가 다음 각 호의 어느 하나에 해당하면 보호장비를 사용할 수 있다. <개정 2016.5.29>', 9466);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15869, '② 보호장비를 사용하는 경우에는 수용자의 나이, 건강상태 및 수용생활 태도 등을 고려하여야 한다.', 9466);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15870, '③ 교도관이 교정시설의 안에서 수용자에 대하여 보호장비를 사용한 경우 의무관은 그 수용자의 건강상태를 수시로 확인하여야 한다.', 9466);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15871, '① 보호장비의 종류는 다음 각 호와 같다.', 9467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15872, '② 보호장비의 종류별 사용요건은 다음 각 호와 같다.', 9467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15873, '③ 보호장비의 사용절차 등에 관하여 필요한 사항은 대통령령으로 정한다.', 9467);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15874, '① 교도관은 필요한 최소한의 범위에서 보호장비를 사용하여야 하며, 그 사유가 없어지면 사용을 지체 없이 중단하여야 한다. <개정 2020.2.4>', 9468);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15875, '② 보호장비는 징벌의 수단으로 사용되어서는 아니 된다.', 9468);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15876, '① 교도관은 수용자가 다음 각 호의 어느 하나에 해당하면 강제력을 행사할 수 있다. <개정 2016.5.29>', 9469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15877, '② 교도관은 수용자 외의 사람이 다음 각 호의 어느 하나에 해당하면 강제력을 행사할 수 있다. <개정 2016.5.29, 2020.2.4>', 9469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15878, '③ 제1항 및 제2항에 따라 강제력을 행사하는 경우에는 보안장비를 사용할 수 있다.', 9469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15879, '④ 제3항에서 "보안장비"란 교도봉ㆍ가스분사기ㆍ가스총ㆍ최루탄 등 사람의 생명과 신체의 보호, 도주의 방지 및 시설의 안전과 질서유지를 위하여 교도관이 사용하는 장비와 기구를 말한다. <개정 2016.5.29>', 9469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15880, '⑤ 제1항 및 제2항에 따라 강제력을 행사하려면 사전에 상대방에게 이를 경고하여야 한다. 다만, 상황이 급박하여 경고할 시간적인 여유가 없는 때에는 그러하지 아니하다.', 9469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15881, '⑥ 강제력의 행사는 필요한 최소한도에 그쳐야 한다.', 9469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15882, '⑦ 보안장비의 종류, 종류별 사용요건 및 사용절차 등에 관하여 필요한 사항은 법무부령으로 정한다.', 9469);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15883, '① 교도관은 다음 각 호의 어느 하나에 해당하는 사유가 있으면 수용자에 대하여 무기를 사용할 수 있다. <개정 2016.5.29, 2020.2.4>', 9470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15884, '② 교도관은 교정시설의 안(교도관이 교정시설의 밖에서 수용자를 계호하고 있는 경우 그 장소를 포함한다)에서 자기 또는 타인의 생명ㆍ신체를 보호하거나 수용자의 탈취를 저지하거나 건물 또는 그 밖의 시설과 무기에 대한 위험을 방지하기 위하여 급박하다고 인정되는 상당한 이유가 있으면 수용자 외의 사람에 대하여도 무기를 사용할 수 있다. <개정 2016.5.29>', 9470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15885, '③ 교도관은 소장 또는 그 직무를 대행하는 사람의 명령을 받아 무기를 사용한다. 다만, 그 명령을 받을 시간적 여유가 없으면 그러하지 아니하다. <개정 2016.5.29>', 9470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15886, '④ 제1항 및 제2항에 따라 무기를 사용하려면 공포탄을 발사하거나 그 밖에 적당한 방법으로 사전에 상대방에 대하여 이를 경고하여야 한다.', 9470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15887, '⑤ 무기의 사용은 필요한 최소한도에 그쳐야 하며, 최후의 수단이어야 한다.', 9470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15888, '⑥ 사용할 수 있는 무기의 종류, 무기의 종류별 사용요건 및 사용절차 등에 관하여 필요한 사항은 법무부령으로 정한다.', 9470);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15889, '① 천재지변이나 그 밖의 재해가 발생하여 시설의 안전과 질서유지를 위하여 긴급한 조치가 필요하면 소장은 수용자로 하여금 피해의 복구나 그 밖의 응급용무를 보조하게 할 수 있다.', 9471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15890, '② 소장은 교정시설의 안에서 천재지변이나 그 밖의 사변에 대한 피난의 방법이 없는 경우에는 수용자를 다른 장소로 이송할 수 있다.', 9471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15891, '③ 소장은 제2항에 따른 이송이 불가능하면 수용자를 일시 석방할 수 있다.', 9471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15892, '④ 제3항에 따라 석방된 사람은 석방 후 24시간 이내에 교정시설 또는 경찰관서에 출석하여야 한다. <개정 2020.2.4>', 9471);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15893, '① 교도관은 수용자가 도주 또는 제134조 각 호의 어느 하나에 해당하는 행위(이하 "도주등"이라 한다)를 한 경우에는 도주 후 또는 출석기한이 지난 후 72시간 이내에만 그를 체포할 수 있다. <개정 2019.4.23>', 9472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15894, '② 교도관은 제1항에 따른 체포를 위하여 긴급히 필요하면 도주등을 하였다고 의심할 만한 상당한 이유가 있는 사람 또는 도주등을 한 사람의 이동경로나 소재를 안다고 인정되는 사람을 정지시켜 질문할 수 있다.', 9472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15895, '③ 교도관은 제2항에 따라 질문을 할 때에는 그 신분을 표시하는 증표를 제시하고 질문의 목적과 이유를 설명하여야 한다.', 9472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15896, '④ 교도관은 제1항에 따른 체포를 위하여 영업시간 내에 공연장ㆍ여관ㆍ음식점ㆍ역, 그 밖에 다수인이 출입하는 장소의 관리자 또는 관계인에게 그 장소의 출입이나 그 밖에 특히 필요한 사항에 관하여 협조를 요구할 수 있다. <개정 2020.2.4>', 9472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15897, '⑤ 교도관은 제4항에 따라 필요한 장소에 출입하는 경우에는 그 신분을 표시하는 증표를 제시하여야 하며, 그 장소의 관리자 또는 관계인의 정당한 업무를 방해하여서는 아니 된다.', 9472);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15898, '① 소장은 마약류사범ㆍ조직폭력사범 등 법무부령으로 정하는 수용자에 대하여는 시설의 안전과 질서유지를 위하여 필요한 범위에서 다른 수용자와의 접촉을 차단하거나 계호를 엄중히 하는 등 법무부령으로 정하는 바에 따라 다른 수용자와 달리 관리할 수 있다.', 9473);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15899, '② 소장은 제1항에 따라 관리하는 경우에도 기본적인 처우를 제한하여서는 아니 된다.', 9473);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15900, '① 수용자는 교정시설의 안전과 질서유지를 위하여 법무부장관이 정하는 규율을 지켜야 한다. <개정 2020.2.4>', 9474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15901, '② 수용자는 소장이 정하는 일과시간표를 지켜야 한다. <개정 2020.2.4>', 9474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15902, '③ 수용자는 교도관의 직무상 지시에 따라야 한다. <개정 2020.2.4>', 9474);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15903, null, 9475);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15904, null, 9476);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15905, null, 9477);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15906, '① 제108조제4호부터 제13호까지의 처분은 함께 부과할 수 있다.', 9478);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15907, '② 수용자가 다음 각 호의 어느 하나에 해당하면 제108조제2호부터 제14호까지의 규정에서 정한 징벌의 장기의 2분의 1까지 가중할 수 있다.', 9478);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15908, '③ 징벌은 동일한 행위에 관하여 거듭하여 부과할 수 없으며, 행위의 동기 및 경중, 행위 후의 정황, 그 밖의 사정을 고려하여 수용목적을 달성하는 데에 필요한 최소한도에 그쳐야 한다.', 9478);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15909, '④ 징벌사유가 발생한 날부터 2년이 지나면 이를 이유로 징벌을 부과하지 못한다.', 9478);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15910, '① 소장은 징벌사유에 해당하는 행위를 하였다고 의심할 만한 상당한 이유가 있는 수용자(이하 "징벌대상자"라 한다)가 다음 각 호의 어느 하나에 해당하면 조사기간 중 분리하여 수용할 수 있다.', 9479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15911, '② 소장은 징벌대상자가 제1항 각 호의 어느 하나에 해당하면 접견ㆍ편지수수ㆍ전화통화ㆍ실외운동ㆍ작업ㆍ교육훈련, 공동행사 참가, 중간처우 등 다른 사람과의 접촉이 가능한 처우의 전부 또는 일부를 제한할 수 있다. <개정 2015.3.27, 2020.2.4>', 9479);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15912, '① 징벌대상자의 징벌을 결정하기 위하여 교정시설에 징벌위원회(이하 이 조에서 "위원회"라 한다)를 둔다.', 9480);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15913, '② 위원회는 위원장을 포함한 5명 이상 7명 이하의 위원으로 구성하고, 위원장은 소장의 바로 다음 순위자가 되며, 위원은 소장이 소속 기관의 과장(지소의 경우에는 7급 이상의 교도관) 및 교정에 관한 학식과 경험이 풍부한 외부인사 중에서 임명 또는 위촉한다. 이 경우 외부위원은 3명 이상으로 한다. <개정 2020.2.4>', 9480);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15914, '③ 위원회는 소장의 징벌요구에 따라 개회하며, 징벌은 그 의결로써 정한다.', 9480);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15915, '④ 위원이 징벌대상자의 친족이거나 그 밖에 공정한 심의ㆍ의결을 기대할 수 없는 특별한 사유가 있는 경우에는 위원회에 참석할 수 없다.', 9480);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15916, '⑤ 징벌대상자는 위원에 대하여 기피신청을 할 수 있다. 이 경우 위원회의 의결로 기피 여부를 결정하여야 한다.', 9480);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15917, '⑥ 위원회는 징벌대상자가 위원회에 출석하여 충분한 진술을 할 수 있는 기회를 부여하여야 하며, 징벌대상자는 서면 또는 말로써 자기에게 유리한 사실을 진술하거나 증거를 제출할 수 있다.', 9480);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15918, '⑦ 위원회의 위원 중 공무원이 아닌 사람은 「형법」 제127조 및 제129조부터 제132조까지의 규정을 적용할 때에는 공무원으로 본다. <신설 2016.1.6>', 9480);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15919, '① 징벌은 소장이 집행한다.', 9482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15920, '② 소장은 징벌집행을 위하여 필요하다고 인정하면 수용자를 분리하여 수용할 수 있다.', 9482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15921, '③ 제108조제14호의 처분을 받은 사람에게는 그 기간 중 같은 조 제4호부터 제12호까지의 처우제한이 함께 부과된다. 다만, 소장은 수용자의 권리구제, 수형자의 교화 또는 건전한 사회복귀를 위하여 특히 필요하다고 인정하면 집필ㆍ편지수수 또는 접견을 허가할 수 있다. <개정 2016.12.2, 2020.2.4>', 9482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15922, '④ 소장은 제108조제14호의 처분을 받은 사람에게 다음 각 호의 어느 하나에 해당하는 사유가 있어 필요하다고 인정하는 경우에는 건강유지에 지장을 초래하지 아니하는 범위에서 실외운동을 제한할 수 있다. <신설 2016.12.2, 2020.2.4>', 9482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15923, '⑤ 소장은 제108조제13호에 따른 실외운동 정지를 부과하는 경우 또는 제4항에 따라 실외운동을 제한하는 경우라도 수용자가 매주 1회 이상 실외운동을 할 수 있도록 하여야 한다. <신설 2020.2.4>', 9482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15924, '⑥ 소장은 제108조제13호 또는 제14호의 처분을 집행하는 경우에는 의무관으로 하여금 사전에 수용자의 건강을 확인하도록 하여야 하며, 집행 중인 경우에도 수시로 건강상태를 확인하여야 한다. <개정 2016.12.2, 2020.2.4>', 9482);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15925, '① 소장은 질병이나 그 밖의 사유로 징벌집행이 곤란하면 그 사유가 해소될 때까지 그 집행을 일시 정지할 수 있다.', 9483);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15926, '② 소장은 징벌집행 중인 사람이 뉘우치는 빛이 뚜렷한 경우에는 그 징벌을 감경하거나 남은 기간의 징벌집행을 면제할 수 있다.', 9483);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15927, '① 징벌위원회는 징벌을 의결하는 때에 행위의 동기 및 정황, 교정성적, 뉘우치는 정도 등 그 사정을 고려할 만한 사유가 있는 수용자에 대하여 2개월 이상 6개월 이하의 기간 내에서 징벌의 집행을 유예할 것을 의결할 수 있다.', 9484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15928, '② 소장은 징벌집행의 유예기간 중에 있는 수용자가 다시 제107조의 징벌대상행위를 하여 징벌이 결정되면 그 유예한 징벌을 집행한다.', 9484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15929, '③ 수용자가 징벌집행을 유예받은 후 징벌을 받음이 없이 유예기간이 지나면 그 징벌의 집행은 종료된 것으로 본다.', 9484);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15930, '① 소장은 징벌의 집행이 종료되거나 집행이 면제된 수용자가 교정성적이 양호하고 법무부령으로 정하는 기간 동안 징벌을 받지 아니하면 법무부장관의 승인을 받아 징벌을 실효시킬 수 있다.', 9485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15931, '② 제1항에도 불구하고 소장은 수용자가 교정사고 방지에 뚜렷한 공로가 있다고 인정되면 분류처우위원회의 의결을 거친 후 법무부장관의 승인을 받아 징벌을 실효시킬 수 있다.', 9485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15932, '③ 이 법에 규정된 사항 외에 징벌에 관하여 필요한 사항은 법무부령으로 정한다.', 9485);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15933, '① 수용자는 그 처우에 관하여 소장에게 면담을 신청할 수 있다.', 9486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15934, '② 소장은 수용자의 면담신청이 있으면 다음 각 호의 어느 하나에 해당하는 사유가 있는 경우를 제외하고는 면담을 하여야 한다. <개정 2020.2.4>', 9486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15935, '③ 소장은 특별한 사정이 있으면 소속 교도관으로 하여금 그 면담을 대리하게 할 수 있다. 이 경우 면담을 대리한 사람은 그 결과를 소장에게 지체 없이 보고하여야 한다.', 9486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15936, '④ 소장은 면담한 결과 처리가 필요한 사항이 있으면 그 처리결과를 수용자에게 알려야 한다. <개정 2020.2.4>', 9486);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15937, '① 수용자는 그 처우에 관하여 불복하는 경우 법무부장관ㆍ순회점검공무원 또는 관할 지방교정청장에게 청원할 수 있다.', 9487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15938, '② 제1항에 따라 청원하려는 수용자는 청원서를 작성하여 봉한 후 소장에게 제출하여야 한다. 다만, 순회점검공무원에 대한 청원은 말로도 할 수 있다.', 9487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15939, '③ 소장은 청원서를 개봉하여서는 아니 되며, 이를 지체 없이 법무부장관ㆍ순회점검공무원 또는 관할 지방교정청장에게 보내거나 순회점검공무원에게 전달하여야 한다.', 9487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15940, '④ 제2항 단서에 따라 순회점검공무원이 청원을 청취하는 경우에는 해당 교정시설의 교도관이 참여하여서는 아니 된다. <개정 2016.5.29>', 9487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15941, '⑤ 청원에 관한 결정은 문서로 하여야 한다. <개정 2020.2.4>', 9487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15942, '⑥ 소장은 청원에 관한 결정서를 접수하면 청원인에게 지체 없이 전달하여야 한다.', 9487);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15943, '① 수용자는 「공공기관의 정보공개에 관한 법률」에 따라 법무부장관, 지방교정청장 또는 소장에게 정보의 공개를 청구할 수 있다.', 9488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15944, '② 현재의 수용기간 동안 법무부장관, 지방교정청장 또는 소장에게 제1항에 따른 정보공개청구를 한 후 정당한 사유 없이 그 청구를 취하하거나 「공공기관의 정보공개에 관한 법률」 제17조에 따른 비용을 납부하지 아니한 사실이 2회 이상 있는 수용자가 제1항에 따른 정보공개청구를 한 경우에 법무부장관, 지방교정청장 또는 소장은 그 수용자에게 정보의 공개 및 우송 등에 들 것으로 예상되는 비용을 미리 납부하게 할 수 있다.', 9488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15945, '③ 제2항에 따라 정보의 공개 및 우송 등에 들 것으로 예상되는 비용을 미리 납부하여야 하는 수용자가 비용을 납부하지 아니한 경우 법무부장관, 지방교정청장 또는 소장은 그 비용을 납부할 때까지 「공공기관의 정보공개에 관한 법률」 제11조에 따른 정보공개 여부의 결정을 유예할 수 있다.', 9488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15946, '④ 제2항에 따른 예상비용의 산정방법, 납부방법, 납부기간, 그 밖에 비용납부에 관하여 필요한 사항은 대통령령으로 정한다.', 9488);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15947, '① 위원회는 위원장을 포함한 5명 이상 9명 이하의 위원으로 구성한다. <개정 2020.2.4>', 9491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15948, '② 위원장은 법무부차관이 되고, 위원은 판사, 검사, 변호사, 법무부 소속 공무원, 교정에 관한 학식과 경험이 풍부한 사람 중에서 법무부장관이 임명 또는 위촉한다.', 9491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15949, '③ 위원회의 심사과정 및 심사내용의 공개범위와 공개시기는 다음 각 호와 같다. 다만, 제2호 및 제3호의 내용 중 개인의 신상을 특정할 수 있는 부분은 삭제하고 공개하되, 국민의 알권리를 충족할 필요가 있는 등의 사유가 있는 경우에는 위원회가 달리 의결할 수 있다. <개정 2011.7.18, 2020.2.4>', 9491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15950, '④ 위원회의 위원 중 공무원이 아닌 사람은 「형법」 제127조 및 제129조부터 제132조까지의 규정을 적용할 때에는 공무원으로 본다. <신설 2016.1.6>', 9491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15951, '⑤ 그 밖에 위원회에 관하여 필요한 사항은 법무부령으로 정한다. <신설 2011.7.18, 2016.1.6>', 9491);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15952, '① 소장은 「형법」 제72조제1항의 기간이 지난 수형자에 대하여는 법무부령으로 정하는 바에 따라 위원회에 가석방 적격심사를 신청하여야 한다.', 9492);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15953, '② 위원회는 수형자의 나이, 범죄동기, 죄명, 형기, 교정성적, 건강상태, 가석방 후의 생계능력, 생활환경, 재범의 위험성, 그 밖에 필요한 사정을 고려하여 가석방의 적격 여부를 결정한다.', 9492);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15954, '① 위원회는 가석방 적격결정을 하였으면 5일 이내에 법무부장관에게 가석방 허가를 신청하여야 한다.', 9493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15955, '② 법무부장관은 제1항에 따른 위원회의 가석방 허가신청이 적정하다고 인정하면 허가할 수 있다.', 9493);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15956, '① 사면, 가석방, 형의 집행면제, 감형에 따른 석방은 그 서류가 교정시설에 도달한 후 12시간 이내에 하여야 한다. 다만, 그 서류에서 석방일시를 지정하고 있으면 그 일시에 한다. <개정 2020.2.4>', 9495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15957, '② 형기종료에 따른 석방은 형기종료일에 하여야 한다. <개정 2020.2.4>', 9495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15958, '③ 권한이 있는 사람의 명령에 따른 석방은 서류가 도달한 후 5시간 이내에 하여야 한다. <개정 2020.2.4>', 9495);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15959, '① 소장은 석방될 수형자의 재범방지, 자립지원 및 피해자 보호를 위하여 필요하다고 인정하면 해당 수형자의 수용이력 또는 사회복귀에 관한 의견을 그의 거주지를 관할하는 경찰관서나 자립을 지원할 법인 또는 개인에게 통보할 수 있다. 다만, 법인 또는 개인에게 통보하는 경우에는 해당 수형자의 동의를 받아야 한다.', 9498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15960, '② 제1항에 따라 통보하는 수용이력 또는 사회복귀에 관한 의견의 구체적인 사항은 대통령령으로 정한다.', 9498);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15961, '① 소장은 사망한 수용자의 친족 또는 특별한 연고가 있는 사람이 그 시신 또는 유골의 인도를 청구하는 경우에는 인도하여야 한다. 다만, 제3항에 따라 자연장(自然葬)을 하거나 집단으로 매장을 한 후에는 그러하지 아니하다. <개정 2015.3.27>', 9500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15962, '② 소장은 제127조에 따라 수용자가 사망한 사실을 알게 된 사람이 다음 각 호의 어느 하나에 해당하는 기간 이내에 그 시신을 인수하지 아니하거나 시신을 인수할 사람이 없으면 임시로 매장하거나 화장(火葬) 후 봉안하여야 한다. 다만, 감염병 예방 등을 위하여 필요하면 즉시 화장하여야 하며, 그 밖에 필요한 조치를 할 수 있다. <개정 2015.3.27, 2020.2.4>', 9500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15963, '③ 소장은 제2항에 따라 시신을 임시로 매장하거나 화장하여 봉안한 후 2년이 지나도록 시신의 인도를 청구하는 사람이 없을 때에는 다음 각 호의 구분에 따른 방법으로 처리할 수 있다. <개정 2015.3.27>', 9500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15964, '④ 소장은 병원이나 그 밖의 연구기관이 학술연구상의 필요에 따라 수용자의 시신인도를 신청하면 본인의 유언 또는 상속인의 승낙이 있는 경우에 한하여 인도할 수 있다.', 9500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15965, '⑤ 소장은 수용자가 사망하면 법무부장관이 정하는 범위에서 화장ㆍ시신인도 등에 필요한 비용을 인수자에게 지급할 수 있다.', 9500);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15966, '① 수용자의 관리ㆍ교정교화 등 사무에 관한 지방교정청장의 자문에 응하기 위하여 지방교정청에 교정자문위원회(이하 이 조에서 "위원회"라 한다)를 둔다. <개정 2019.4.23>', 9501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15967, '② 위원회는 10명 이상 15명 이하의 위원으로 성별을 고려하여 구성하고, 위원장은 위원 중에서 호선하며, 위원은 교정에 관한 학식과 경험이 풍부한 외부인사 중에서 지방교정청장의 추천을 받아 법무부장관이 위촉한다. <개정 2019.4.23>', 9501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15968, '③ 이 법에 규정된 사항 외에 위원회에 관하여 필요한 사항은 법무부령으로 정한다.', 9501);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15969, '① 수용자의 교육ㆍ교화ㆍ의료, 그 밖에 수용자의 처우를 후원하기 위하여 교정시설에 교정위원을 둘 수 있다.', 9502);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15970, '② 교정위원은 명예직으로 하며 소장의 추천을 받아 법무부장관이 위촉한다.', 9502);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15971, '① 수용자가 제92조제2항을 위반하여 소장의 허가 없이 무인비행장치, 전자ㆍ통신기기를 지닌 경우 2년 이하의 징역 또는 2천만원 이하의 벌금에 처한다. <개정 2020.2.4>', 9504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15972, '② 수용자가 제92조제1항제3호를 위반하여 주류ㆍ담배ㆍ화기ㆍ현금ㆍ수표를 지닌 경우 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. <개정 2020.2.4>', 9504);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15973, '① 소장의 허가 없이 무인비행장치, 전자ㆍ통신기기를 교정시설에 반입한 사람은 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.', 9505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15974, '② 주류ㆍ담배ㆍ화기ㆍ현금ㆍ수표ㆍ음란물ㆍ사행행위에 사용되는 물품을 수용자에게 전달할 목적으로 교정시설에 반입한 사람은 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 9505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15975, '③ 상습적으로 제2항의 죄를 범한 사람은 2년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.', 9505);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15976, null, 9506);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15977, '① 「형의 집행 및 수용자의 처우에 관한 법률」(이하 "법"이라 한다) 제5조의3에 따른 협의체(이하 "협의체"라 한다)는 위원장을 포함하여 12명의 위원으로 구성한다.', 9511);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15978, '② 협의체의 위원장은 법무부차관이 되고, 협의체의 위원은 다음 각 호의 사람이 된다.', 9511);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15979, '③ 협의체의 위원장은 협의체 회의를 소집하며, 회의 개최 7일 전까지 회의의 일시ㆍ장소 및 안건 등을 각 위원에게 알려야 한다.', 9511);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15980, '④ 협의체의 위원장은 협의체의 회의 결과를 위원이 소속된 기관의 장에게 통보해야 한다.', 9511);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15981, '① 판사 또는 검사가 법 제9조제1항에 따라 교도소ㆍ구치소 및 그 지소(이하 "교정시설"이라 한다)를 시찰할 경우에는 미리 그 신분을 나타내는 증표를 교정시설의 장(이하 "소장"이라 한다)에게 제시해야 한다. <개정 2018.12.24, 2019.10.22>', 9512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15982, '② 소장은 제1항의 경우에 교도관에게 시찰을 요구받은 장소를 안내하게 해야 한다. <개정 2018.12.24>', 9512);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15983, '① 소장은 법 제9조제2항에 따라 판사와 검사 외의 사람이 교정시설의 참관을 신청하는 경우에는 그 성명ㆍ직업ㆍ주소ㆍ나이ㆍ성별 및 참관 목적을 확인한 후 허가 여부를 결정하여야 한다.', 9513);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15984, '② 소장은 외국인에게 참관을 허가할 경우에는 미리 관할 지방교정청장의 승인을 받아야 한다.', 9513);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15985, '③ 소장은 제1항 및 제2항에 따라 허가를 받은 사람에게 참관할 때의 주의사항을 알려주어야 한다.', 9513);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15986, null, 9515);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15987, '① 교도관은 제5조제2호에 따라 독거수용된 사람(이하 "계호상 독거수용자"라 한다)을 수시로 시찰하여 건강상 또는 교화상 이상이 없는지 살펴야 한다.', 9516);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15988, '② 교도관은 제1항의 시찰 결과, 계호상 독거수용자가 건강상 이상이 있는 것으로 보이는 경우에는 교정시설에 근무하는 의사(공중보건의사를 포함한다. 이하 "의무관"이라 한다)에게 즉시 알려야 하고, 교화상 문제가 있다고 인정하는 경우에는 소장에게 지체 없이 보고하여야 한다.', 9516);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15989, '③ 의무관은 제2항의 통보를 받은 즉시 해당 수용자를 상담ㆍ진찰하는 등 적절한 의료조치를 하여야 하며, 계호상 독거수용자를 계속하여 독거수용하는 것이 건강상 해롭다고 인정하는 경우에는 그 의견을 소장에게 즉시 보고하여야 한다.', 9516);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15990, '④ 소장은 계호상 독거수용자를 계속하여 독거수용하는 것이 건강상 또는 교화상 해롭다고 인정하는 경우에는 이를 즉시 중단하여야 한다.', 9516);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15991, '① 소장은 수용자거실에 면적, 정원 및 현재인원을 적은 현황표를 붙여야 한다.', 9522);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15992, '② 소장은 수용자거실 앞에 이름표를 붙이되, 이름표 윗부분에는 수용자의 성명ㆍ출생연도ㆍ죄명ㆍ형명(刑名) 및 형기(刑期)를 적고, 그 아랫부분에는 수용자번호 및 입소일을 적되, 윗부분의 내용이 보이지 않도록 해야 한다. <개정 2014.6.25, 2020.8.5>', 9522);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15993, '③ 소장은 수용자가 법령에 따라 지켜야 할 사항과 수용자의 권리구제 절차에 관한 사항을 수용자거실의 보기 쉬운 장소에 붙이는 등의 방법으로 비치하여야 한다. <개정 2014.6.25>', 9522);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15994, '① 소장은 법원ㆍ검찰청ㆍ경찰관서 등으로부터 처음으로 교정시설에 수용되는 사람(이하 "신입자"라 한다)을 인수한 경우에는 호송인(護送人)에게 인수서를 써 주어야 한다. 이 경우 신입자에게 부상ㆍ질병, 그 밖에 건강에 이상(이하 이 조에서 "부상등"이라 한다)이 있을 때에는 호송인으로부터 그 사실에 대한 확인서를 받아야 한다.', 9523);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15995, '② 신입자를 인수한 교도관은 제1항의 인수서에 신입자의 성명, 나이 및 인수일시를 적고 서명 또는 날인하여야 한다.', 9523);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15996, '③ 소장은 제1항 후단에 따라 확인서를 받는 경우에는 호송인에게 신입자의 성명, 나이, 인계일시 및 부상등의 사실을 적고 서명 또는 날인하도록 하여야 한다.', 9523);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15997, '① 소장은 신입자의 키ㆍ용모ㆍ문신ㆍ흉터 등 신체 특징과 가족 등 보호자의 연락처를 수용기록부에 기록하여야 하며, 교도관이 업무상 필요한 경우가 아니면 이를 열람하지 못하도록 하여야 한다.', 9527);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15998, '② 소장은 신입자 및 다른 교정시설로부터 이송(移送)되어 온 사람(이하 "이입자"라 한다)에 대하여 수용자번호를 지정하고 수용 중 번호표를 상의의 왼쪽 가슴에 붙이게 하여야 한다. 다만, 수용자의 교화 또는 건전한 사회복귀를 위하여 특히 필요하다고 인정하면 번호표를 붙이지 아니할 수 있다.', 9527);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (15999, '① 소장은 신입자가 환자이거나 부득이한 사정이 있는 경우가 아니면 수용된 날부터 3일 동안 신입자거실에 수용하여야 한다.', 9528);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16000, '② 소장은 제1항에 따라 신입자거실에 수용된 사람에게는 작업을 부과해서는 아니 된다.', 9528);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16001, '③ 소장은 19세 미만의 신입자 그 밖에 특히 필요하다고 인정하는 수용자에 대하여는 제1항의 기간을 30일까지 연장할 수 있다.', 9528);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16002, '①소장은 신입자의 신원에 관한 사항을 조사하여 수용기록부에 기록하여야 한다. <개정 2012.1.6>', 9530);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16003, '② 소장은 신입자의 본인 확인 및 수용자의 처우 등을 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보, 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <신설 2012.1.6>', 9530);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16004, '① 지방교정청장은 법 제20조제2항에 따라 다음 각 호의 어느 하나에 해당하는 경우에는 수용자의 이송을 승인할 수 있다.', 9532);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16005, '② 제1항에 따른 지방교정청장의 이송승인은 관할 내 이송으로 한정한다.', 9532);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16006, '① 소장은 법 제22조제1항에 따라 의류ㆍ침구, 그 밖의 생활용품(이하 "의류등"이라 한다)을 지급하는 경우에는 수용자의 건강, 계절 등을 고려하여야 한다.', 9535);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16007, '② 소장은 수용자에게 특히 청결하게 관리할 수 있는 재질의 식기를 지급하여야 하며, 다른 사람이 사용한 의류등을 지급하는 경우에는 세탁하거나 소독하여 지급하여야 한다.', 9535);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16008, '① 소장은 거실ㆍ작업장, 그 밖에 수용자가 생활하는 장소(이하 이 조에서 "거실등"이라 한다)에 수용생활에 필요한 기구를 갖춰 둬야 한다.', 9536);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16009, '② 거실등에는 갖춰 둔 기구의 품목ㆍ수량을 기록한 품목표를 붙여야 한다.', 9536);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16010, '① 수용자에게 지급하는 주식은 쌀로 한다. <개정 2014.6.25>', 9538);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16011, '② 소장은 쌀 수급이 곤란하거나 그 밖에 필요하다고 인정하면 주식을 쌀과 보리 등 잡곡의 혼합곡으로 하거나 대용식을 지급할 수 있다. <개정 2014.6.25>', 9538);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16012, '① 소장은 수용자가 사용하는 의류등을 적당한 시기에 세탁ㆍ수선 또는 교체(이하 이 조에서 "세탁등"이라 한다)하도록 하여야 한다.', 9543);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16013, '② 자비로 구매한 의류등을 세탁등을 하는 경우 드는 비용은 수용자가 부담한다.', 9543);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16014, '① 법 제25조에서 "휴대금품"이란 신입자가 교정시설에 수용될 때에 지니고 있는 현금(자기앞수표를 포함한다. 이하 같다)과 휴대품을 말한다.', 9544);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16015, '② 법 제25조제1항 각 호의 어느 하나에 해당하지 아니한 신입자의 휴대품은 보관한 후 사용하게 할 수 있다. <개정 2020.8.5>', 9544);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16016, '③ 법 제25조제1항 단서에 따라 신입자의 휴대품을 팔 경우에는 그 비용을 제외한 나머지 대금을 보관할 수 있다. <개정 2020.8.5>', 9544);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16017, '④ 소장은 신입자가 법 제25조제1항 각 호의 어느 하나에 해당하는 휴대품을 법무부장관이 정한 기간에 처분하지 않은 경우에는 본인에게 그 사실을 고지한 후 폐기한다.', 9544);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16018, '① 소장은 수용자가 그의 가족(배우자, 직계존비속 또는 형제자매를 말한다. 이하 같다) 또는 배우자의 직계존속에게 도움을 주거나 그 밖에 정당한 용도로 사용하기 위하여 보관금의 사용을 신청한 경우에는 그 사정을 고려하여 허가할 수 있다. <개정 2020.8.5>', 9548);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16019, '② 제1항에 따라 보관금을 사용하는 경우 발생하는 비용은 수용자가 부담한다. <개정 2020.8.5>', 9548);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16020, '③ 보관금의 출납ㆍ예탁(預託), 보관금품의 보관 등에 관하여 필요한 사항은 법무부장관이 정한다. <개정 2020.8.5>', 9548);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16021, '① 소장은 법 제27조제1항에 따라 수용자에 대한 금품의 전달을 허가한 경우에는 그 금품을 보관한 후 해당 수용자가 사용하게 할 수 있다. <개정 2020.8.5>', 9552);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16022, '② 법 제27조제1항에 따라 수용자에게 건네주려고 하는 금품의 허가범위 등에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2020.8.5>', 9552);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16023, '① 소장은 사망자의 유류품을 건네받을 사람이 원거리에 있는 등 특별한 사정이 있는 경우에는 유류품을 받을 사람의 청구에 따라 유류품을 팔아 그 대금을 보낼 수 있다. <개정 2020.8.5>', 9555);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16024, '② 법 제28조에 따라 사망자의 유류금품을 보내거나 제1항에 따라 유류품을 팔아 대금을 보내는 경우에 드는 비용은 유류금품의 청구인이 부담한다.', 9555);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16025, '① 소장은 거실ㆍ작업장ㆍ목욕탕, 그 밖에 수용자가 공동으로 사용하는 시설과 취사장, 주식ㆍ부식 저장고, 그 밖에 음식물 공급과 관련된 시설을 수시로 청소ㆍ소독하여야 한다.', 9557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16026, '② 소장은 저수조 등 급수시설을 6개월에 1회 이상 청소ㆍ소독하여야 한다.', 9557);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16027, null, 9559);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16028, '① 소장은 수용자에 대하여 1년에 1회 이상 건강검진을 하여야 한다. 다만, 19세 미만의 수용자와 계호상 독거수용자에 대하여는 6개월에 1회 이상 하여야 한다.', 9561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16029, '② 제1항의 건강검진은 「건강검진기본법」 제14조에 따라 지정된 건강검진기관에 의뢰하여 할 수 있다. <개정 2009.3.18>', 9561);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16030, '① 소장은 수용자가 감염병에 걸렸다고 의심되는 경우에는 1주 이상 격리수용하고 그 수용자의 휴대품을 소독하여야 한다. <개정 2010.12.29>', 9563);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16031, '② 소장은 감염병이 유행하는 경우에는 수용자가 자비로 구매하는 음식물의 공급을 중지할 수 있다. <개정 2010.12.29>', 9563);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16032, '③ 소장은 수용자가 감염병에 걸린 경우에는 즉시 격리수용하고 그 수용자가 사용한 물품과 설비를 철저히 소독하여야 한다. <개정 2010.12.29>', 9563);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16033, '④ 소장은 제3항의 사실을 지체 없이 법무부장관에게 보고하고 관할 보건기관의 장에게 알려야 한다.', 9563);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16034, null, 9565);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16035, '① 수용자의 접견은 매일(공휴일 및 법무부장관이 정한 날은 제외한다) 「국가공무원 복무규정」 제9조에 따른 근무시간 내에서 한다.', 9569);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16036, '② 변호인(변호인이 되려고 하는 사람을 포함한다. 이하 같다)과 접견하는 미결수용자를 제외한 수용자의 접견시간은 회당 30분 이내로 한다. <개정 2014.6.25>', 9569);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16037, '③ 수형자의 접견 횟수는 매월 4회로 한다.', 9569);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16038, '④ 삭제 <2019.10.22>', 9569);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16039, '⑤ 법 및 이 영에 규정된 사항 외에 수형자, 사형확정자 및 미결수용자를 제외한 수용자의 접견 횟수ㆍ시간ㆍ장소 등에 관하여 필요한 사항은 법무부장관이 정한다.', 9569);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16040, '⑥ 소장은 교정시설의 외부에 있는 사람의 수용자 접견에 관한 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 시행령 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <신설 2012.1.6>', 9569);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16041, '① 소장은 제58조제1항 및 제2항에도 불구하고 수형자의 교화 또는 건전한 사회복귀를 위하여 특히 필요하다고 인정하면 접견 시간대 외에도 접견을 하게 할 수 있고 접견시간을 연장할 수 있다.', 9570);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16042, '② 소장은 제58조제3항에도 불구하고 수형자가 다음 각 호의 어느 하나에 해당하면 접견 횟수를 늘릴 수 있다.', 9570);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16043, '③ 법 제41조제3항제2호에서 "대통령령으로 정하는 경우"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다. <개정 2019.10.22>', 9570);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16044, '① 제58조제2항에도 불구하고 수용자가 다음 각 호의 어느 하나에 해당하는 변호사와 접견하는 시간은 회당 60분으로 한다. <개정 2019.10.22>', 9571);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16045, '② 수용자가 제1항 각 호의 변호사와 접견하는 횟수는 다음 각 호의 구분에 따르되, 이를 제58조제3항, 제101조 및 제109조의 접견 횟수에 포함시키지 아니한다. <개정 2019.10.22>', 9571);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16046, '③ 소장은 제58조제1항과 이 조 제1항 및 제2항에도 불구하고 소송사건의 수 또는 소송내용의 복잡성 등을 고려하여 소송의 준비를 위하여 특히 필요하다고 인정하면 접견 시간대 외에도 접견을 하게 할 수 있고, 접견 시간 및 횟수를 늘릴 수 있다.', 9571);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16047, '④ 소장은 제1항 및 제2항에도 불구하고 접견 수요 또는 접견실 사정 등을 고려하여 원활한 접견 사무 진행에 현저한 장애가 발생한다고 판단하면 접견 시간 및 횟수를 줄일 수 있다. 이 경우 줄어든 시간과 횟수는 다음 접견 시에 추가하도록 노력하여야 한다.', 9571);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16048, '⑤ 수용자가 「형사소송법」에 따른 상소권회복 또는 재심 청구사건의 대리인이 되려는 변호사와 접견하는 경우에는 교정시설의 안전 또는 질서를 해칠 우려가 없는 한 접촉차단시설이 설치되지 않은 장소에서 접견하게 한다. <신설 2019.10.22>', 9571);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16049, '⑥ 제1항부터 제5항까지에서 규정한 사항 외에 수용자와 제1항 각 호의 변호사의 접견에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2019.10.22>', 9571);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16050, '① 수용자와 교정시설 외부의 사람이 접견하는 경우에 법 제41조제4항에 따라 접견내용이 청취ㆍ녹음 또는 녹화될 때에는 외국어를 사용해서는 아니 된다. 다만, 국어로 의사소통하기 곤란한 사정이 있는 경우에는 외국어를 사용할 수 있다. <개정 2019.10.22>', 9572);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16051, '② 소장은 제1항 단서의 경우에 필요하다고 인정하면 교도관 또는 통역인으로 하여금 통역하게 할 수 있다.', 9572);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16052, '① 소장은 법 제41조제4항의 청취ㆍ기록을 위하여 다음 각 호의 사람을 제외한 수용자의 접견에 교도관을 참여하게 할 수 있다. <개정 2016.6.28, 2019.10.22>', 9574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16053, '② 소장은 특별한 사정이 없으면 교도관으로 하여금 법 제41조제5항에 따라 수용자와 그 상대방에게 접견내용의 녹음ㆍ녹화 사실을 수용자와 그 상대방이 접견실에 들어가기 전에 미리 말이나 서면 등 적절한 방법으로 알려 주게 하여야 한다. <개정 2019.10.22>', 9574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16054, '③ 소장은 법 제41조제4항에 따라 청취ㆍ녹음ㆍ녹화한 경우의 접견기록물에 대한 보호ㆍ관리를 위하여 접견정보 취급자를 지정하여야 하고, 접견정보 취급자는 직무상 알게 된 접견정보를 누설하거나 권한 없이 처리하거나 다른 사람이 이용하도록 제공하는 등 부당한 목적을 위하여 사용해서는 아니 된다. <개정 2019.10.22>', 9574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16055, '④ 소장은 관계기관으로부터 다음 각 호의 어느 하나에 해당하는 사유로 제3항의 접견기록물의 제출을 요청받은 경우에는 기록물을 제공할 수 있다.', 9574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16056, '⑤ 소장은 제4항에 따라 녹음ㆍ녹화 기록물을 제공할 경우에는 제3항의 접견정보 취급자로 하여금 녹음ㆍ녹화기록물을 요청한 기관의 명칭, 제공받는 목적, 제공 근거, 제공을 요청한 범위, 그 밖에 필요한 사항을 녹음ㆍ녹화기록물 관리프로그램에 입력하게 하고, 따로 이동식 저장매체에 옮겨 담아 제공한다.', 9574);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16057, '① 수용자는 편지를 보내려는 경우 해당 편지를 봉함하여 교정시설에 제출한다. 다만, 소장은 다음 각 호의 어느 하나에 해당하는 경우로서 법 제43조제3항에 따른 금지물품의 확인을 위하여 필요한 경우에는 편지를 봉함하지 않은 상태로 제출하게 할 수 있다. <개정 2013.2.5, 2017.9.19, 2020.8.5>', 9577);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16058, '② 소장은 수용자에게 온 편지에 금지물품이 들어 있는지를 개봉하여 확인할 수 있다. <개정 2020.8.5>', 9577);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16059, '① 소장은 법 제43조제4항제4호에 따라 다음 각 호의 어느 하나에 해당하는 수용자가 다른 수용자와 편지를 주고받는 때에는 그 내용을 검열할 수 있다. <개정 2020.8.5>', 9578);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16060, '② 수용자 간에 오가는 편지에 대한 제1항의 검열은 편지를 보내는 교정시설에서 한다. 다만, 특히 필요하다고 인정되는 경우에는 편지를 받는 교정시설에서도 할 수 있다. <개정 2020.8.5>', 9578);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16061, '③ 소장은 수용자가 주고받는 편지가 법 제43조제4항 각 호의 어느 하나에 해당하면 이를 개봉한 후 검열할 수 있다. <신설 2013.2.5, 2020.8.5>', 9578);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16062, '④ 소장은 제3항에 따라 검열한 결과 편지의 내용이 법 제43조제5항의 발신 또는 수신 금지사유에 해당하지 아니하면 발신편지는 봉함한 후 발송하고, 수신편지는 수용자에게 건네준다. <신설 2013.2.5, 2020.8.5>', 9578);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16063, '⑤ 소장은 편지의 내용을 검열했을 때에는 그 사실을 해당 수용자에게 지체 없이 알려주어야 한다. <신설 2013.2.5, 2020.8.5>', 9578);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16064, '① 소장은 수용자가 쉽게 이용할 수 있도록 비치도서의 목록을 정기적으로 공개하여야 한다.', 9584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16065, '② 비치도서의 열람방법, 열람기간 등에 관하여 필요한 사항은 법무부장관이 정한다.', 9584);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16066, '① 수용자는 휴업일 및 휴게시간 내에 시간의 제한 없이 집필할 수 있다. 다만, 부득이한 사정이 있는 경우에는 그러하지 아니하다.', 9587);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16067, '② 수용자는 거실ㆍ작업장, 그 밖에 지정된 장소에서 집필할 수 있다.', 9587);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16068, '① 소장은 수용자 본인이 작성 또는 집필한 문서나 도화(<img src="http://www.law.go.kr/flDownload.do?flSeq=72505057"  alt="img72505057" >圖</img>)를 외부에 보내거나 내가려고 할 때에는 그 내용을 확인하여 법 제43조제5항 각 호의 어느 하나에 해당하지 않으면 허가해야 한다. <개정 2020.8.5>', 9588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16069, '② 제1항에 따라 문서나 도화를 외부로 보내거나 내갈 때 드는 비용은 수용자가 부담한다.', 9588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16070, '③ 법 및 이 영에 규정된 사항 외에 수용자의 집필에 필요한 사항은 법무부장관이 정한다.', 9588);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16071, '① 소장은 제50조에 따라 여성수용자의 목욕횟수를 정하는 경우에는 그 신체적 특성을 특히 고려하여야 한다.', 9589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16072, '② 소장은 여성수용자가 목욕을 하는 경우에 계호가 필요하다고 인정하면 여성교도관이 하도록 하여야 한다.', 9589);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16073, '① 소장은 유아의 양육을 허가하지 아니하는 경우에는 수용자의 의사를 고려하여 유아보호에 적당하다고 인정하는 법인 또는 개인에게 그 유아를 보낼 수 있다. 다만, 적당한 법인 또는 개인이 없는 경우에는 그 유아를 해당 교정시설의 소재지를 관할하는 시장ㆍ군수 또는 구청장에게 보내서 보호하게 하여야 한다.', 9592);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16074, '② 법 제53조제1항에 따라 양육이 허가된 유아가 출생 후 18개월이 지나거나, 유아양육의 허가를 받은 수용자가 허가의 취소를 요청하는 때 또는 법 제53조제1항 각 호의 어느 하나에 해당되는 때에도 제1항과 같다.', 9592);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16075, '① 법 제54조제1항에서 "노인수용자"란 65세 이상인 수용자를 말한다.', 9593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16076, '② 법 제54조제2항에서 "장애인수용자"란 시각ㆍ청각ㆍ언어ㆍ지체(肢體) 등의 장애로 통상적인 수용생활이 특히 곤란하다고 인정되는 사람으로서 법무부령으로 정하는 수용자를 말한다.', 9593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16077, '③ 법 제54조제3항에서 "외국인수용자"란 대한민국의 국적을 가지지 아니한 수용자를 말한다. <신설 2015.12.10>', 9593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16078, '④ 법 제54조제4항에서 "소년수용자"란 다음 각 호의 사람을 말한다. <신설 2015.12.10>', 9593);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16079, '① 소장은 미결수용자로서 자유형이 확정된 사람에 대하여는 검사의 집행 지휘서가 도달된 때부터 수형자로 처우할 수 있다.', 9594);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16080, '② 제1항의 경우 검사는 집행 지휘를 한 날부터 10일 이내에 재판서나 그 밖에 적법한 서류를 소장에게 보내야 한다.', 9594);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16081, null, 9595);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16082, '① 법 제57조제3항에서 "교정성적"이란 수형자의 수용생활 태도, 상벌 유무, 교육 및 작업의 성과 등을 종합적으로 평가한 결과를 말한다.', 9596);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16083, '② 소장은 수형자의 처우수준을 개별처우계획의 시행에 적합하게 정하거나 조정하기 위하여 교정성적에 따라 처우등급을 부여할 수 있다.', 9596);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16084, '③ 수형자에게 부여하는 처우등급에 관하여 필요한 사항은 법무부령으로 정한다.', 9596);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16085, '① 수형자의 건전한 사회복귀를 지원하기 위하여 교정시설에 취업알선 및 창업지원에 관한 협의기구를 둘 수 있다.', 9597);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16086, '② 제1항의 협의기구의 조직ㆍ운영, 그 밖에 활동에 필요한 사항은 법무부령으로 정한다.', 9597);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16087, '① 소장은 법 제63조에 따른 교육을 효과적으로 시행하기 위하여 교육실을 설치하는 등 교육에 적합한 환경을 조성하여야 한다.', 9599);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16088, '② 소장은 교육 대상자, 시설 여건 등을 고려하여 교육계획을 수립하여 시행하여야 한다.', 9599);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16089, '① 소장은 수형자에게 작업을 부과하는 경우에는 작업의 종류 및 작업과정을 정하여 고지하여야 한다.', 9603);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16090, '② 제1항의 작업과정은 작업성적, 작업시간, 작업의 난이도 및 숙련도를 고려하여 정한다. 작업과정을 정하기 어려운 경우에는 작업시간을 작업과정으로 본다.', 9603);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16091, '① 소장은 법 제77조에 따라 2일 이상의 귀휴를 허가한 경우에는 귀휴를 허가받은 사람(이하 "귀휴자"라 한다)의 귀휴지를 관할하는 경찰관서의 장에게 그 사실을 통보하여야 한다.', 9609);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16092, '② 귀휴자는 귀휴 중 천재지변이나 그 밖의 사유로 자신의 신상에 중대한 사고가 발생한 경우에는 가까운 교정시설이나 경찰관서에 신고하여야 하고 필요한 보호를 요청할 수 있다.', 9609);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16093, '③ 제2항의 보호 요청을 받은 교정시설이나 경찰관서의 장은 귀휴를 허가한 소장에게 그 사실을 지체 없이 통보하고 적절한 보호조치를 하여야 한다.', 9609);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16094, '① 법 제86조제1항의 미결수용자에 대한 교육ㆍ교화프로그램 또는 작업은 교정시설 밖에서 행하는 것은 포함하지 아니한다.', 9615);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16095, '② 소장은 법 제86조제1항에 따라 작업이 부과된 미결수용자가 작업의 취소를 요청하는 경우에는 그 미결수용자의 의사, 건강 및 교도관의 의견 등을 고려하여 작업을 취소할 수 있다.', 9615);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16096, '①교도관 외의 사람은 「국가공무원 복무규정」 제9조에 따른 근무시간 외에는 소장의 허가 없이 교정시설에 출입하지 못한다. <개정 2014.8.6>', 9627);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16097, '② 소장은 외부인의 교정시설 출입에 관한 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법 시행령」 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다. <신설 2014.8.6>', 9627);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16098, '① 교정시설의 바깥문, 출입구, 거실, 작업장, 그 밖에 수용자를 수용하고 있는 장소는 외부와 차단하여야 한다. 다만, 필요에 따라 일시 개방하는 경우에는 그 장소를 경비하여야 한다.', 9628);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16099, '② 교도관은 접견ㆍ상담ㆍ진료, 그 밖에 수용자의 처우를 위하여 필요한 경우가 아니면 수용자와 외부인이 접촉하게 해서는 아니 된다.', 9628);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16100, '① 법 제95조제5항 및 법 제96조제4항에 따라 의무관이 보호실이나 진정실 수용자의 건강을 확인한 결과 보호실 또는 진정실에 계속 수용하는 것이 부적당하다고 인정하는 경우에는 소장에게 즉시 보고하여야 한다. 이 경우 소장은 특별한 사유가 없으면 보호실 또는 진정실 수용을 즉시 중지하여야 한다.', 9631);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16101, '② 소장은 의무관이 출장ㆍ휴가, 그 밖의 부득이한 사유로 법 제95조제5항 및 법 제96조제4항의 직무를 수행할 수 없을 때에는 그 교정시설에 근무하는 의료관계 직원에게 대행하게 할 수 있다.', 9631);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16102, '① 교도관은 소장의 명령 없이 수용자에게 보호장비를 사용하여서는 아니 된다. 다만, 소장의 명령을 받을 시간적 여유가 없는 경우에는 사용 후 소장에게 즉시 보고하여야 한다.', 9632);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16103, '② 법 및 이 영에 규정된 사항 외에 보호장비의 규격과 사용방법 등에 관하여 필요한 사항은 법무부령으로 정한다.', 9632);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16104, '① 의무관은 수용자에게 보호장비를 계속 사용하는 것이 건강상 부적당하다고 인정하는 경우에는 소장에게 즉시 보고하여야 한다. 이 경우 소장은 특별한 사유가 없으면 보호장비 사용을 즉시 중지하여야 한다.', 9633);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16105, '② 의무관이 출장ㆍ휴가, 그 밖의 부득이한 사유로 법 제97조제3항의 직무를 수행할 수 없을 때에는 제119조제2항을 준용한다.', 9633);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16106, '① 소장은 보호장비의 사용을 명령한 경우에는 수시로 그 사용 실태를 확인ㆍ점검하여야 한다.', 9636);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16107, '② 지방교정청장은 소속 교정시설의 보호장비 사용 실태를 정기적으로 점검하여야 한다.', 9636);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16108, '① 소장은 법 제102조제1항에 따른 응급용무의 보조를 위하여 교정성적이 우수한 수형자를 선정하여 필요한 훈련을 시킬 수 있다.', 9639);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16109, '② 소장은 법 제102조제3항에 따라 수용자를 일시석방하는 경우에는 같은 조 제4항의 출석 시한과 장소를 알려주어야 한다.', 9639);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16110, '① 소장은 수용자가 도주하거나 법 제134조 각 호의 어느 하나에 해당하는 행위(이하 이 조에서 "도주등"이라 한다)를 한 경우에는 교정시설의 소재지 및 인접지역 또는 도주등을 한 사람(이하 이 조에서 "도주자"라 한다)이 숨을 만한 지역의 경찰관서에 도주자의 사진이나 인상착의를 기록한 서면을 첨부하여 그 사실을 지체 없이 통보하여야 한다. <개정 2019.10.22>', 9640);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16111, '② 소장은 수용자가 도주등을 하거나 도주자를 체포한 경우에는 법무부장관에게 지체 없이 보고하여야 한다.', 9640);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16112, '① 법무부장관은 「형법」 제145조ㆍ제146조 또는 법 제134조 각 호에 규정된 죄를 지은 수용자를 체포하거나 행정기관 또는 수사기관에 정보를 제공하여 체포하게 한 사람에게 예산의 범위에서 포상금을 지급할 수 있다. <개정 2019.10.22>', 9641);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16113, '② 포상금의 지급기준ㆍ지급방법, 그 밖에 필요한 사항은 법무부장관이 정한다.', 9641);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16114, '① 포상금을 받으려는 사람은 법무부장관이 정하는 바에 따라 포상금 지급 신청서를 지방교정청장에게 제출해야 한다. <개정 2020.8.5>', 9642);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16115, '② 제1항에 따른 신청서를 접수한 지방교정청장은 그 신청서에 법무부장관이 정하는 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 9642);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16116, null, 9643);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16117, '① 소장은 제132조의 통고를 받은 경우에는 징벌을 지체 없이 집행하여야 한다.', 9648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16118, '② 소장은 수용자가 징벌처분을 받아 접견, 편지수수 또는 전화통화가 제한된 경우에는 그의 가족에게 그 사실을 알려야 한다. 다만, 수용자가 알리는 것을 원하지 않으면 알리지 않는다. <개정 2014.6.25, 2020.8.5>', 9648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16119, '③ 삭제 <2017.9.19>', 9648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16120, '④ 소장은 법 제108조제13호 및 제14호의 징벌집행을 마친 경우에는 의무관에게 해당 수용자의 건강을 지체 없이 확인하게 하여야 한다.', 9648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16121, '⑤ 의무관이 출장, 휴가, 그 밖의 부득이한 사유로 법 제112조제5항 및 이 조 제4항의 직무를 수행할 수 없는 경우에는 제119조제2항을 준용한다. <개정 2019.10.22>', 9648);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16122, '① 소장은 법 제116조제1항에 따라 수용자가 면담을 신청한 경우에는 그 인적사항을 면담부에 기록하고 특별한 사정이 없으면 신청한 순서에 따라 면담하여야 한다.', 9653);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16123, '② 소장은 제1항에 따라 수용자를 면담한 경우에는 그 요지를 면담부에 기록하여야 한다.', 9653);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16124, '③ 소장은 법 제116조제2항 각 호의 어느 하나에 해당하여 수용자의 면담 신청을 받아들이지 아니하는 경우에는 그 사유를 해당 수용자에게 알려주어야 한다.', 9653);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16125, '① 소장은 법 제117조제1항에 따라 수용자가 순회점검공무원(법 제8조에 따라 법무부장관으로부터 순회점검의 명을 받은 법무부 또는 그 소속기관에 근무하는 공무원을 말한다. 이하 같다)에게 청원하는 경우에는 그 인적사항을 청원부에 기록하여야 한다.', 9654);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16126, '② 순회점검공무원은 법 제117조제2항 단서에 따라 수용자가 말로 청원하는 경우에는 그 요지를 청원부에 기록하여야 한다.', 9654);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16127, '③ 순회점검공무원은 법 제117조제1항의 청원에 관하여 결정을 한 경우에는 그 요지를 청원부에 기록하여야 한다.', 9654);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16128, '④ 순회점검공무원은 법 제117조제1항의 청원을 스스로 결정하는 것이 부적당하다고 인정하는 경우에는 그 내용을 법무부장관에게 보고하여야 한다.', 9654);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16129, '⑤ 수용자의 청원처리의 기준ㆍ절차 등에 관하여 필요한 사항은 법무부장관이 정한다.', 9654);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16130, '① 법 제117조의2제2항에 따른 예상비용은 「공공기관의 정보공개에 관한 법률 시행령」 제17조에 따른 수수료와 우편요금(공개되는 정보의 사본ㆍ출력물ㆍ복제물 또는 인화물을 우편으로 송부하는 경우로 한정한다)을 기준으로 공개를 청구한 정보가 모두 공개되었을 경우에 예상되는 비용으로 한다.', 9655);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16131, '② 법무부장관, 지방교정청장 또는 소장은 법 제117조의2제2항에 해당하는 수용자가 정보공개의 청구를 한 경우에는 청구를 한 날부터 7일 이내에 제1항에 따른 비용을 산정하여 해당 수용자에게 미리 납부할 것을 통지할 수 있다.', 9655);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16132, '③ 제2항에 따라 비용납부의 통지를 받은 수용자는 그 통지를 받은 날부터 7일 이내에 현금 또는 수입인지로 법무부장관, 지방교정청장 또는 소장에게 납부하여야 한다.', 9655);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16133, '④ 법무부장관, 지방교정청장 또는 소장은 수용자가 제1항에 따른 비용을 제3항에 따른 납부기한까지 납부하지 아니한 경우에는 해당 수용자에게 정보공개 여부 결정의 유예를 통지할 수 있다.', 9655);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16134, '⑤ 법무부장관, 지방교정청장 또는 소장은 제1항에 따른 비용이 납부되면 신속하게 정보공개 여부의 결정을 하여야 한다.', 9655);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16135, '⑥ 법무부장관, 지방교정청장 또는 소장은 비공개 결정을 한 경우에는 제3항에 따라 납부된 비용의 전부를 반환하고 부분공개 결정을 한 경우에는 공개 결정한 부분에 대하여 드는 비용을 제외한 금액을 반환하여야 한다.', 9655);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16136, '⑦ 제2항부터 제5항까지의 규정에도 불구하고 법무부장관, 지방교정청장 또는 소장은 제1항에 따른 비용이 납부되기 전에 정보공개 여부의 결정을 할 수 있다.', 9655);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16137, '⑧ 제1항에 따른 비용의 세부적인 납부방법 및 반환방법 등에 관하여 필요한 사항은 법무부장관이 정한다.', 9655);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16138, '① 법 제126조의2제1항 본문에 따라 통보하는 수용이력에는 다음 각 호의 사항이 포함되어야 한다.', 9659);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16139, '② 법 제126조의2제1항 본문에 따라 통보하는 사회복귀에 관한 의견에는 다음 각 호의 사항이 포함되어야 한다.', 9659);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16140, '③ 법 제126조의2제1항 본문에 따른 통보를 위한 수용이력 통보서와 사회복귀에 관한 의견 통보서의 서식은 법무부령으로 정한다.', 9659);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16141, '④ 법 제126조의2제1항 본문에 따라 석방될 수형자의 수용이력 또는 사회복귀에 관한 의견을 그의 거주지를 관할하는 경찰관서에 통보하는 경우에는 「형사사법절차 전자화 촉진법」 제2조제4호에 따른 형사사법정보시스템을 통해 통보할 수 있다.', 9659);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16142, null, 9662);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16143, '① 의무관은 수용자가 질병으로 사망한 경우에는 사망장에 그 병명ㆍ병력(病歷)ㆍ사인 및 사망일시를 기록하고 서명하여야 한다.', 9666);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16144, '② 소장은 수용자가 자살이나 그 밖에 변사한 경우에는 그 사실을 검사에게 통보하고, 기소된 상태인 경우에는 법원에도 통보하여야 하며 검시가 끝난 후에는 검시자ㆍ참여자의 신분ㆍ성명과 검시 결과를 사망장에 기록하여야 한다.', 9666);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16145, '③ 소장은 법 제128조에 따라 시신을 인도, 화장(火葬), 임시 매장, 집단 매장 또는 자연장(自然葬)을 한 경우에는 그 사실을 사망장에 기록하여야 한다. <개정 2015.12.10>', 9666);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16146, '① 소장은 시신을 임시 매장하거나 봉안한 경우에는 그 장소에 사망자의 성명을 적은 표지를 비치하고, 별도의 장부에 가족관계 등록기준지, 성명, 사망일시를 기록하여 관리하여야 한다. <개정 2015.12.10>', 9668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16147, '② 소장은 시신 또는 유골을 집단 매장한 경우에는 집단 매장된 사람의 가족관계 등록기준지, 성명, 사망일시를 집단 매장부에 기록하고 그 장소에 묘비를 세워야 한다. <개정 2015.12.10>', 9668);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16148, '① 소장은 법 제130조에 따라 교정위원을 두는 경우 수용자의 개선을 촉구하고 안정된 수용생활을 하게 하기 위하여 교정위원에게 수용자를 교화상담하게 할 수 있다.', 9669);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16149, '② 교정위원은 수용자의 고충 해소 및 교정ㆍ교화를 위하여 필요한 의견을 소장에게 건의할 수 있다.', 9669);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16150, '③ 교정위원의 임기, 위촉 및 해촉, 지켜야 할 사항 등에 관하여 필요한 사항은 법무부장관이 정한다. <개정 2020.8.5>', 9669);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16151, '① 소장은 법 제131조의 기부금품을 접수하는 경우에는 기부한 기관ㆍ단체 또는 개인(이하 이 장에서 "기부자"라 한다)에게 영수증을 발급하여야 한다. 다만, 익명으로 기부하거나 기부자를 알 수 없는 경우에는 그러하지 아니하다.', 9671);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16152, '② 소장은 기부자가 용도를 지정하여 금품을 기부한 경우에는 기부금품을 그 용도에 사용하여야 한다. 다만, 지정한 용도로 사용하기 어려운 특별한 사유가 있는 경우에는 기부자의 동의를 받아 다른 용도로 사용할 수 있다.', 9671);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16153, '③ 교정시설의 기부금품 접수ㆍ사용 등에 관하여 필요한 사항은 법무부장관이 정한다.', 9671);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16154, '① 추진단은 단장, 형사전자소송심의관, 형사전자소송담당관 및 단원으로 구성한다.', 9673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16155, '② 단장과 형사전자소송심의관은 판사로 보한다.', 9673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16156, '③ 형사전자소송담당관은 4급 이상 법원직원으로 보한다.', 9673);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16157, null, 9674);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16158, '① 단장은 추진단 업무를 수행하기 위하여 필요한 때에는 관계 기관, 단체 등에 대하여 자료 또는 의견의 제출 및 지원 활동 등 필요한 협조를 요청할 수 있다.', 9675);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16159, '② 단장은 추진단 업무를 수행하기 위하여 필요한 때에는 법원행정처장의 허가를 받아, 법원행정처 내 각 실ㆍ국과 관계 기관에 형사전자소송 사업의 수행을 위하여 필요한 인원의 파견을 요청할 수 있다.', 9675);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16160, '① 단장은 형사전자소송 시스템 구축 사업의 수행을 위하여 필요한 경우에는 법관, 법원직원 또는 외부전문가에게 협조를 구하거나 조사연구를 위탁할 수 있다.', 9676);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16161, '② 제1항의 경우 추진단은 예산의 범위에서 그 수당 및 여비, 그 밖에 필요한 경비를 지급할 수 있다. 다만, 법관과 법원직원이 그 소관 업무와 관련하여 협조에 응할 경우에는 여비 등 필요한 경비만을 지급할 수 있다.', 9676);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16162, null, 9679);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16163, null, 9680);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16164, '① 이 법은 형사사법절차의 전자적 처리에 관하여 다른 법률에 우선하여 적용한다.', 9681);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16165, '② 형사사법절차의 전자적 처리에 관하여 이 법에 특별한 규정이 없으면 「형사소송법」 및 「형사사법절차 전자화 촉진법」을 적용한다.', 9681);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16166, '① 피의자, 피고인, 피해자, 고소인, 고발인, 변호인 및 그 밖에 대통령령 또는 대법원규칙으로 정하는 자는 제7조에 따른 사용자등록을 한 경우 형사사법업무 처리기관에 제출할 서류 또는 도면ㆍ사진ㆍ음성ㆍ영상자료 등(이하 이 조에서 "서류등"이라 한다)을 대통령령 또는 대법원규칙으로 정하는 바에 따라 전산정보처리시스템을 통하여 전자문서로 제출할 수 있다.', 9682);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16167, '② 「전자문서 및 전자거래 기본법」 제4조의2에 따른 요건을 갖춘 전자문서를 이 법에 따라 작성, 제출ㆍ송달 및 보존한 경우에는 제3조 각 호의 법률에서 정한 요건과 절차에 따라 서류등을 작성, 제출ㆍ송달 및 보존한 것으로 본다.', 9682);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16168, '③ 이 법에 따라 변환ㆍ등재한 전자화문서는 전자화대상문서와 동일한 것으로 본다.', 9682);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16169, '④ 이 법에 따라 전산정보처리시스템을 통하여 전자문서를 출력한 서면은 전자문서와 동일한 것으로 본다.', 9682);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16170, '⑤ 제3조 각 호의 법률에서 서류등의 사본을 발급ㆍ교부, 제출ㆍ송달 및 보존하도록 한 경우 전산정보처리시스템을 통하여 전자문서를 출력한 서면은 제3조 각 호의 법률에 따른 서류등의 원본 또는 사본으로 본다.', 9682);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16171, '① 형사사법업무 처리기관의 장은 전산정보처리시스템을 각각 설치ㆍ운영한다.', 9683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16172, '② 형사사법업무 처리기관은 전자문서의 이용 및 관리에 관한 표준을 마련하기 위하여 서로 협력하여야 한다.', 9683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16173, '③ 형사사법업무 처리기관은 이 법을 적용하거나 전산정보처리시스템을 운영할 때 장애인이나 노약자 등이 형사사법절차에서 권리를 충분히 행사할 수 있도록 노력하여야 한다.', 9683);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16174, '① 전산정보처리시스템을 이용하려는 자(형사사법업무 처리기관 소속 공무원은 제외한다)는 대통령령 또는 대법원규칙으로 정하는 바에 따라 사용자등록을 하여야 한다.', 9684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16175, '② 제1항에 따른 사용자등록(이하 "사용자등록"이라 한다)을 한 자(이하 "등록사용자"라 한다)는 대통령령 또는 대법원규칙으로 정하는 바에 따라 사용자등록을 철회할 수 있다.', 9684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16176, '③ 형사사법업무 처리기관의 장은 다음 각 호의 어느 하나에 해당하는 사유가 있는 경우에는 대통령령 또는 대법원규칙으로 정하는 바에 따라 등록사용자의 전산정보처리시스템 사용을 정지하거나 사용자등록을 말소할 수 있다.', 9684);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16177, '① 형사사법업무 처리기관에 전자문서를 제출하려는 자는 그 전자문서에 전자서명(서명자의 실지명의를 확인할 수 있는 것으로 한정한다. 이하 이 항에서 같다)을 하여야 한다. 다만, 전자서명을 이용할 수 없는 경우로서 제출자의 신원이 확인된 경우 등 대통령령 또는 대법원규칙으로 정하는 경우에는 전자서명을 하지 아니할 수 있다.', 9685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16178, '② 법관 또는 법원사무관등은 재판서, 조서 등을 전자문서로 작성하는 경우에는 대법원규칙으로 정하는 바에 따라 사법전자서명을 한다. 이 경우 제3조 각 호의 법률에 따라 진술자의 서명이 필요한 경우에는 진술자에게 전자서명을 하게 하여야 한다.', 9685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16179, '③ 법원 외의 형사사법업무 처리기관 소속 공무원은 결정문, 조서, 보고서 등을 전자문서로 작성하는 경우에는 대통령령으로 정하는 바에 따라 행정전자서명을 한다. 이 경우 제3조 각 호의 법률에 따라 진술자의 서명이 필요한 경우에는 진술자에게 전자서명을 하게 하여야 한다.', 9685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16180, '④ 제1항부터 제3항까지의 규정에 따른 전자서명, 사법전자서명 또는 행정전자서명을 한 경우에는 제3조 각 호의 법률에 따른 서명, 서명날인 또는 기명날인을 한 것으로 본다.', 9685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16181, '⑤ 제1항부터 제3항까지의 규정에 따라 제출하거나 작성하는 전자문서에 면수(面數)를 표시한 경우에는 제3조 각 호의 법률에 따른 간인(間印)을 한 것으로 본다.', 9685);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16182, '① 전자문서는 전산정보처리시스템에 전자적으로 기록된 때에 접수된 것으로 본다.', 9686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16183, '② 전산정보처리시스템을 통하여 제출된 전자문서를 접수하는 절차와 방법은 대통령령 또는 대법원규칙으로 정한다. 이 경우 제출된 전자문서의 동일성 유지를 위한 기술적 조치에 관한 사항을 그 내용에 포함하여야 한다.', 9686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16184, '③ 형사사법업무 처리기관은 제5조제1항에 따라 전자문서를 제출한 등록사용자가 접수된 전자문서의 동일성 확인을 요구하는 경우 대통령령 또는 대법원규칙으로 정하는 바에 따라 그 동일성을 확인할 수 있는 기회를 주어야 한다.', 9686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16185, '④ 등록사용자는 제5조제1항에 따라 제출한 전자문서와 접수된 전자문서의 내용이 일치하지 아니하는 경우에는 대통령령 또는 대법원규칙으로 정하는 바에 따라 형사사법업무 처리기관에 수정을 요구할 수 있다.', 9686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16186, '⑤ 형사사법업무 처리기관은 접수된 전자문서의 위조 또는 변조 여부를 확인할 필요가 있는 경우에는 제5조제1항에 따라 전자문서를 제출한 등록사용자에게 그 원본을 제시하거나 제출할 것을 요구할 수 있다.', 9686);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16187, '① 형사사법업무 처리기관 소속 공무원은 재판서, 공판조서, 공소장, 불기소결정서, 송치결정서, 피의자신문조서 등 형사사법업무와 관련된 문서를 작성하는 경우에는 전자문서로 작성하여야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우로서 대통령령 또는 대법원규칙으로 정하는 사유가 있는 경우에는 그러하지 아니하다.', 9687);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16188, '② 형사사법업무 처리기관 소속 공무원은 제1항 각 호 외의 부분 본문에 따라 피의자신문조서를 전자문서로 작성하는 경우에는 대통령령으로 정하는 바에 따라 「형사소송법」에 따른 피의자신문조서 작성 절차와 방식이 전자적으로 구현되도록 하여야 한다.', 9687);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16189, '① 형사사법업무 처리기관 소속 공무원은 전자화대상문서를 전자적인 형태로 변환하여 전산정보처리시스템에 등재하여야 한다. 다만, 전자화대상문서를 전자적인 형태로 변환하는 것이 현저히 곤란하거나 적합하지 아니한 경우로서 대통령령 또는 대법원규칙으로 정하는 경우에는 변환ㆍ등재하지 아니할 수 있다.', 9688);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16190, '② 전자화대상문서를 전자적인 형태로 변환하여 전산정보처리시스템에 등재하는 절차와 방법은 대통령령 또는 대법원규칙으로 정한다. 이 경우 전자화대상문서의 동일성 유지를 위한 기술적 조치에 관한 사항을 그 내용에 포함하여야 한다.', 9688);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16191, '① 형사사법업무 처리기관은 제11조에 따라 변환ㆍ등재한 전자화대상문서를 대통령령 또는 대법원규칙으로 정하는 기간까지 보관하여야 한다.', 9689);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16192, '② 형사사법업무 처리기관은 전자화대상문서를 제출한 자의 요청이 있는 경우에는 제1항에도 불구하고 전자화대상문서를 반환할 수 있다.', 9689);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16193, '③ 형사사법업무 처리기관은 제2항에 따라 전자화대상문서를 제출한 사람에게 전자화대상문서를 반환하는 경우 대통령령 또는 대법원규칙으로 정하는 바에 따라 전자화문서와 전자화대상문서의 동일성을 확인할 수 있는 기회를 주고 확인서를 받아야 한다.', 9689);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16194, '① 형사사법업무 처리기관은 형사사법절차와 관련하여 작성한 전자문서를 다른 형사사법업무 처리기관에 송부할 때에는 전산정보처리시스템을 통하여 송부하여야 한다.', 9690);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16195, '② 형사사법업무 처리기관이 형사사법업무 처리기관 외의 기관에 사건을 이송 또는 송치할 때에는 전자문서를 전산정보처리시스템을 통하여 출력한 후 그 서면을 송부한다. 다만, 전자문서를 송신ㆍ수신할 수 있는 시스템을 갖춘 기관으로서 대통령령 또는 대법원규칙으로 정하는 기관에 이송 또는 송치할 때에는 전자문서를 전자적 방법으로 송부할 수 있다.', 9690);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16196, '③ 제2항 본문에 따라 전자문서를 출력하는 절차와 방법은 대통령령 또는 대법원규칙으로 정한다. 이 경우 전자문서의 동일성 유지를 위한 기술적 조치에 관한 사항을 그 내용에 포함하여야 한다.', 9690);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16197, '① 형사사법업무 처리기관은 송달 또는 통지를 받을 자가 다음 각 호의 어느 하나에 해당하는 경우에는 송달 또는 통지를 전산정보처리시스템을 통하여 전자적으로 할 수 있다.', 9691);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16198, '② 제1항에 따른 송달 또는 통지는 형사사법업무 처리기관이 전자문서를 전산정보처리시스템에 등재하고 그 사실을 송달 또는 통지받을 자에게 전자적으로 통지하는 방법으로 한다.', 9691);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16199, '③ 제2항에 따라 송달 또는 통지한 경우에는 그 송달 또는 통지를 받을 자가 전산정보처리시스템에 등재된 전자문서를 대통령령 또는 대법원규칙으로 정하는 절차와 방법에 따라 확인한 때에 송달 또는 통지된 것으로 본다.', 9691);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16200, '④ 제3항에도 불구하고 송달 또는 통지를 받을 자가 전산정보처리시스템에 등재된 전자문서를 확인하지 아니하는 경우에는 제2항에 따라 등재 사실을 전자적으로 통지한 날부터 14일이 지난 날에 송달 또는 통지된 것으로 본다. 다만, 피의자 또는 피고인 등의 형사사법절차상의 권리를 보호하기 위하여 필요한 경우로서 대통령령 또는 대법원규칙으로 정하는 경우에는 통지된 것으로 보지 아니한다.', 9691);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16201, '⑤ 전산정보처리시스템의 장애 등 대통령령 또는 대법원규칙으로 정하는 사유로 송달 또는 통지를 받을 자가 전자문서를 확인할 수 없는 기간은 제4항 본문의 기간에 산입하지 아니한다. 이 경우 전자문서를 확인할 수 없는 기간의 계산 방법은 대통령령 또는 대법원규칙으로 정한다.', 9691);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16202, '① 형사사법업무 처리기관은 다음 각 호의 어느 하나에 해당하는 경우에는 전산정보처리시스템을 통하여 전자문서를 출력한 서면을 「형사소송법」 제60조부터 제65조까지의 규정에 따른 방법으로 송달하여야 한다.', 9692);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16203, '② 제1항에 따라 전자문서를 출력하는 절차와 방법은 대통령령 또는 대법원규칙으로 정한다. 이 경우 전자문서의 동일성 유지를 위한 기술적 조치에 관한 사항을 그 내용에 포함하여야 한다.', 9692);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16204, '① 「형사소송법」 제35조, 제55조, 제59조의2, 제59조의3, 제174조, 제185조, 제200조의4, 제262조의2 단서, 제266조의3, 제266조의4, 제266조의11 및 제294조의4에도 불구하고 이 법에 따라 작성된 전자문서를 열람ㆍ등사 또는 복사하는 경우에는 인터넷이나 전산정보처리시스템을 통하여 전자적으로 열람 또는 복사하거나 전송하는 방법으로 할 수 있다.', 9693);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16205, '② 제1항에도 불구하고 등록사용자가 아닌 자가 전자문서의 열람 또는 복사를 신청하는 경우에는 전자문서를 전산정보처리시스템을 통하여 출력한 서면을 교부하는 방법으로 할 수 있다.', 9693);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16206, '③ 제1항에 따라 전자문서를 열람 또는 복사하거나 전송하는 절차와 방법은 대통령령 또는 대법원규칙으로 정한다. 이 경우 전자문서의 동일성 유지를 위한 기술적 조치에 관한 사항을 그 내용에 포함하여야 한다.', 9693);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16207, '④ 피고인(피고인이었던 사람을 포함한다) 또는 변호인(변호인이었던 사람을 포함한다)은 제1항에 따라 열람 또는 복사하거나 전송받은 「형사소송법」 제266조의3제1항에 따른 서류(그 목록을 포함한다)에 해당하는 전자문서를 해당 사건 또는 관련 사건의 소송을 준비하기 위한 목적이 아닌 다른 목적으로 다른 사람에게 인터넷 또는 전산정보처리시스템을 통하여 전송하거나 교부(전자문서를 서면으로 출력하여 교부하는 것을 말한다) 또는 제시(전자문서를 서면으로 출력하여 제시하는 것과 전기통신설비를 통하여 제공하는 것을 포함한다)하여서는 아니 된다.', 9693);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16208, '① 검사 또는 사법경찰관리는 다음 각 호의 영장, 감정유치장, 허가장, 허가서 및 요청서 등(이하 "영장등"이라 한다)이 전자문서로 발부된 경우에는 대법원규칙으로 정하는 바에 따라 전자문서를 제시하거나 전송하는 방법으로 영장등을 집행할 수 있다.', 9694);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16209, '② 제1항에 따라 영장등을 전자문서의 형태로 집행하는 것이 현저히 곤란하거나 적합하지 아니한 경우에는 전자문서로 발부된 영장등을 전산정보처리시스템을 통하여 출력한 서면으로 집행할 수 있다.', 9694);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16210, '③ 제2항에 따라 전자문서로 발부된 영장등을 전산정보처리시스템을 통하여 출력하는 절차와 방법은 대법원규칙으로 정한다. 이 경우 전자문서의 동일성을 유지하고 법관이 발부한 취지와 다르게 여러 통이 출력되지 아니하도록 하기 위한 기술적 조치에 관한 사항을 그 내용에 포함하여야 한다.', 9694);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16211, null, 9695);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16212, '① 검사는 재판서 또는 재판을 기재한 조서가 전자문서로 작성된 경우에는 「형사소송법」 제461조 본문에도 불구하고 전자문서로 재판의 집행을 지휘한다.', 9696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16213, '② 제1항에도 불구하고 전자문서로 재판의 집행을 지휘하기 곤란한 경우에는 전자문서로 작성된 재판서 또는 재판을 기재한 조서를 전산정보처리시스템을 통하여 출력한 서면으로 재판의 집행을 지휘한다.', 9696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16214, '③ 제2항에 따라 전자문서를 출력하는 절차와 방법은 대통령령 또는 대법원규칙으로 정한다. 이 경우 전자문서의 동일성 유지를 위한 기술적 조치에 관한 사항을 그 내용에 포함하여야 한다.', 9696);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16215, '① 전산정보처리시스템을 통하여 작성된 전자문서는 다음 각 호의 구분에 따라 정하여진 때에 폐기하여야 한다.', 9697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16216, '② 제1항에도 불구하고 국내외적으로 중대한 사건, 공범에 대한 수사가 필요한 사건 등 대통령령 또는 대법원규칙으로 정하는 사건의 경우에는 대통령령 또는 대법원규칙으로 정하는 바에 따라 전자문서를 영구 보관하거나 제1항에 따른 폐기 시기를 늦출 수 있다.', 9697);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16217, null, 9701);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16218, null, 9702);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16219, '① 법 제7조제1항에 따라 사용자등록을 하려는 자는 형사사법포털에 접속해 다음 각 호의 유형별로 필요한 정보를 해당란에 입력한 후 전자서명을 위한 인증서(서명자의 실지명의를 확인할 수 있는 것으로서 법무부장관이 지정해 형사사법포털에 공고하는 것을 말한다. 이하 같다)로 같은 항에 따른 사용자등록(이하 "사용자등록"이라 한다)을 신청해야 한다. 이 경우 사용자등록을 한 자(이하 "등록사용자"라 한다)의 등록 정보는 인증서의 내용과 일치해야 한다.', 9703);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16220, '② 제1항제2호 및 제3호의 등록사용자는 이용권한의 범위를 정해 자기 소속의 사용자를 지정할 수 있고, 그에 따라 지정된 자는 형사사법포털에 접속해 소속사용자로 등록을 할 수 있다.', 9703);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16221, '③ 수사기관등은 사건기록이 전자기록으로 관리되는 사건(이하 "전자기록사건"이라 한다)에서 다음 각 호의 자에 대해 사용자등록을 할 것을 권고할 수 있다.', 9703);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16222, '① 법 제7조제2항에 따라 사용자등록을 철회하려는 등록사용자는 형사사법포털에 접속해 사용자등록 철회의 취지를 입력하는 방법으로 사용자등록을 철회할 수 있다.', 9704);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16223, '② 제1항에 따라 사용자등록을 철회하더라도 철회 이전에 등록사용자가 제출한 문서의 효력 및 수사기관등이 등록사용자에게 전산정보처리시스템을 통해 전자적으로 한 송달 또는 통지의 효력에는 영향을 미치지 않는다.', 9704);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16224, '① 수사기관등의 장은 법 제7조제3항에 따라 등록사용자 외에 제4조제2항에 따라 등록된 소속사용자(이하 "소속사용자"라 한다)에 대해서도 전산정보처리시스템 사용을 정지하거나 소속사용자의 등록을 말소할 수 있다.', 9705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16225, '② 수사기관등의 장이 법 제7조제3항제5호에 따라 등록사용자(소속사용자를 포함한다. 이하 같다)의 전산정보처리시스템 사용을 정지하거나 사용자등록(제1항에 따른 소속사용자의 등록을 포함한다. 이하 같다)을 말소할 수 있는 사유는 다음 각 호와 같다.', 9705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16226, '③ 수사기관등의 장은 법 제7조제3항 각 호(제3호는 제외한다)의 사유에 해당하는지를 결정하기 위해 필요하다고 인정할 경우에는 말소 여부가 결정될 때까지 해당 등록사용자의 사용을 일시적으로 정지할 수 있다. 이 경우 수사기관등의 장은 등록사용자에게 전자우편이나 문자전송 서비스 등을 통해 그 사실을 통지해야 한다.', 9705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16227, '④ 수사기관등의 장은 법 제7조제3항에 따라 사용자등록을 말소(이 조 제2항제3호의 사유로 말소하는 경우는 제외한다)하기 전에 해당 등록사용자에게 미리 그 사유를 전자우편이나 문자전송 서비스 등을 통해 통지하고 소명의 기회를 부여해야 한다.', 9705);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16228, '① 법 제8조제1항에 따라 수사기관등에 전자문서를 제출하려는 자는 이 영에서 달리 정하는 경우를 제외하고는 전자문서에 행정전자서명을 하거나 인증서로 전자서명을 해야 한다.', 9706);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16229, '② 법 제8조제1항 본문에 따른 전자서명(서명자의 실지명의를 확인할 수 있는 것으로 한정한다)을 이용할 수 없는 자가 전자문서를 제출하려는 경우에는 해당 수사기관등으로부터 신원을 확인받은 후 컴퓨터 등 정보처리장치를 이용해 전자서명을 할 수 있다.', 9706);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16230, '③ 법 제8조제1항 본문에 따른 전자서명(서명자의 실지명의를 확인할 수 있는 것으로 한정한다)을 이용할 수 없는 자가 전자문서를 제출하려는 경우에는 해당 수사기관등으로부터 신원을 확인받은 후 전자문서가 저장된 정보저장매체를 제출하는 방식으로 전자문서를 제출할 수 있다. 이 경우 전자문서를 제출받은 수사기관등의 소속 공무원은 제출받은 전자문서에 행정전자서명을 마친 후 전자문서를 전산정보처리시스템에 등재해야 한다.', 9706);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16231, '④ 수사기관등의 소속 공무원은 법 제8조제3항에 따라 결정문, 조서, 보고서 등을 전자문서로 작성하는 경우에는 「전자정부법 시행령」 제30조에 따른 행정전자서명 인증서로 행정전자서명을 한 후 전산정보처리시스템에 저장해야 한다. 이 경우 법 제3조 각 호의 법률에 따른 형사사법절차에서 진술자의 서명을 필요로 하는 경우에는 신원이 확인된 진술자에게 조서 등에 전자서명을 하게 해야 한다.', 9706);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16232, '① 법무부장관은 법 제9조제2항 전단에 따라 전산정보처리시스템을 통해 제출할 수 있는 전자문서의 파일 형식, 구성 방식 및 그 밖의 사항을 지정해 형사사법포털에 공고해야 한다.', 9707);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16233, '② 등록사용자는 주장, 증거 또는 그 밖의 사항을 합쳐 하나의 파일로 제출해서는 안 되고, 형사사법포털에서 요구하는 방식에 따라 각각 별도의 파일로 구분하여 제출해야 한다.', 9707);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16234, '③ 등록사용자는 부득이한 사정이 없는 한 문자정보의 검색 및 추출이 가능한 형식으로 전자문서를 제출해야 한다.', 9707);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16235, '① 등록사용자는 형사사법포털에서 요구하는 방식에 따라 해당 사항을 입력하거나 전자문서를 등재하는 방식으로 서류를 전자문서로 작성하거나 제출할 수 있다.', 9708);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16236, '② 공동의 이해관계를 가진 여러 등록사용자는 다음 각 호의 어느 하나에 해당하는 방법에 따라 공동명의로 하나의 전자문서를 제출할 수 있다.', 9708);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16237, '③ 「공증인법」 제5장의2에 따른 인증이 부여된 전자문서를 제출하는 경우에는 그 취지와 인증의 증명에 관한 사항을 밝혀야 한다.', 9708);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16238, '④ 소속사용자 중 전자문서의 제출 권한을 지정받은 소속사용자는 다음 각 호의 어느 하나에 해당하는 방법으로 전자문서를 제출할 수 있다.', 9708);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16239, '⑤ 수사기관등의 장은 등록사용자가 제출한 전자문서의 동일성 확인을 위해 접수 당시 전자문서의 해시값(Hash value: 전자문서 파일로부터 추출된 고유의 식별값을 말한다. 이하 같다)을 저장하는 등의 기술적 조치를 해야 한다.', 9708);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16240, '① 전자문서를 제출한 등록사용자는 법 제9조제3항에 따라 전자문서를 제출한 날부터 14일 이내에 전자문서의 동일성 확인을 요구해야 한다.', 9709);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16241, '② 수사기관등은 법 제9조제3항에 따라 등록사용자로부터 전자문서의 동일성 확인을 요구받은 경우에는 컴퓨터 등 정보처리장치를 이용해 전자문서를 열람하게 하는 방법으로 그 동일성을 확인할 수 있도록 해야 한다.', 9709);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16242, '③ 수사기관등은 법 제9조제4항에 따라 등록사용자로부터 전자문서의 수정을 요구받은 경우에는 그 요구를 받은 날부터 14일 이내에 등록사용자가 제출한 전자문서와 접수된 전자문서가 동일한지를 판단하고 수정 여부를 결정해야 한다.', 9709);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16243, '① 등록사용자는 형사사법포털을 통해 전자화문서를 제출하는 경우 전자화대상문서(종이문서나 그 밖에 전자적인 형태로 작성되지 않은 서류 또는 도면ㆍ사진ㆍ음성ㆍ영상자료 등을 말한다. 이하 같다)의 원본을 해당 형사사법절차가 확정될 때까지 보관해야 한다.', 9710);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16244, '② 법 제9조제5항에 따라 수사기관등으로부터 전자문서 원본의 제시나 제출을 요구받은 등록사용자는 그 요구에 따라야 한다.', 9710);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16245, '③ 수사기관등은 등록사용자가 법 제9조제5항에 따른 원본의 제시 또는 제출 요구에 따르지 않는 경우에는 제출된 전자화문서를 폐기할 수 있다. 이 경우 등록사용자가 요청하면 제출된 전자화문서를 폐기하기 전에 그 전자화문서를 복제해 교부할 수 있다.', 9710);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16246, '① 등록사용자는 음성이나 영상정보 등 멀티미디어 방식의 자료를 형사사법포털을 통해 제출할 수 있다. 이 경우 형사사법포털에서 요구하는 방식에 따라 제출하되, 해당 자료의 주요 내용, 제출 취지 및 용량을 밝혀야 한다.', 9711);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16247, '② 수사기관등은 제1항 후단에 따라 밝힌 멀티미디어 자료의 주요 내용, 제출 취지 및 용량의 기재가 충분하지 않은 경우 제출자에게 보완을 요구할 수 있다.', 9711);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16248, '① 수사기관등은 변환ㆍ제출된 전자문서의 판독이 곤란하거나 그 밖에 원본을 확인할 필요가 있는 경우에는 상당한 기간을 정해 해당 전자문서를 제출한 자에 대하여 판독이 가능한 전자문서를 다시 제출하거나 원본을 제출할 것을 요구할 수 있다.', 9712);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16249, '② 제1항에 따라 전자문서를 제출한 자가 판독이 가능한 전자문서 또는 원본을 다시 제출한 경우에는 전자문서를 최초로 제출한 때에 판독이 가능한 전자문서 또는 원본을 제출한 것으로 본다.', 9712);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16250, '③ 등록사용자가 형사사법포털을 이용해 전자문서를 제출하여 접수된 후에는 이를 삭제하거나 내용을 수정해 다시 제출할 수 없다.', 9712);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16251, '④ 수사기관등은 전자문서를 제출한 자의 의견을 들어 전자문서가 필요하지 않다고 판단한 경우에는 해당 전자문서를 폐기할 수 있다. 이 경우 전자문서를 제출한 자가 요청하면 제출된 전자문서를 폐기하기 전에 그 전자문서를 복제해 교부할 수 있다.', 9712);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16252, '① 수사기관등은 「형사소송법」 제199조제2항에 따라 공무소나 그 밖의 공사단체에 자료의 제출을 요구하는 경우 전자적 송달 또는 통지의 방법으로 할 수 있다.', 9713);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16253, '② 전자기록사건에서 공무소나 그 밖의 공사단체가 전자문서로 보유하고 있는 자료를 「형사소송법」 제199조제2항에 따라 제출하는 경우에는 전산정보처리시스템을 통해 제출할 수 있다.', 9713);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16254, '③ 수사기관등은 공무소나 그 밖의 공사단체가 제2항에 따라 제출하는 자료가 전자문서가 아닌 경우 이를 전자문서로 변환한 후 전송해 줄 것을 요청할 수 있다.', 9713);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16255, '① 법 제10조제1항 단서에 따라 전자문서로 작성하지 않을 수 있는 경우는 다음 각 호와 같다.', 9714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16256, '② 제1항에도 불구하고 수사기관등은 다음 각 호의 경우에는 전자문서로 작성하지 않은 문서를 전자문서화해야 한다.', 9714);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16257, '① 수사기관등의 소속 공무원은 「형사소송법」에 따른 피의자신문조서를 컴퓨터 등 정보처리장치를 이용해 피의자에게 열람하게 할 수 있다.', 9715);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16258, '② 「형사소송법」 제244조제2항에 따라 피의자가 피의자신문조서의 증감 또는 변경의 청구 등 이의를 제기하거나 의견을 진술해 이를 추가로 기재하는 경우에는 컴퓨터 등 정보처리장치를 이용해 기재하고 전자서명을 할 수 있다.', 9715);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16259, '③ 제2항에도 불구하고 피의자가 종이문서에 기재할 것을 요구하는 경우에는 피의자신문조서를 출력해 종이문서로 해당 내용을 작성하고 해당 종이문서를 전자적인 형태로 변환해 전산정보처리시스템에 등재해야 한다.', 9715);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16260, '④ 「형사소송법」 제244조의2제2항 및 「성폭력범죄의 처벌 등에 관한 특례법」 제30조제4항에 따른 영상녹화 후 기명날인 또는 서명 등의 절차는 영상녹화를 완료한 후 그 영상의 해시값을 전산정보처리시스템에 저장하고 당사자가 이를 확인하는 방식으로 한다.', 9715);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16261, '⑤ 「형사소송법」 제312조제4항에 따른 조서를 작성하는 경우(인터넷 화상장치 등으로 조사해 작성하는 경우를 포함한다)에는 제1항부터 제4항까지의 규정을 준용한다.', 9715);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16262, '① 수사기관등의 소속 공무원은 「특정범죄신고자 등 보호법」 제7조제1항에 따른 조서나 그 밖의 서류(이하 이 조에서 "조서등"이라 한다) 및 같은 조 제3항에 따른 범죄신고자등 신원관리카드(이하 이 조에서 "범죄신고자등 신원관리카드"라 한다)를 전자문서로 작성할 수 있다.', 9716);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16263, '② 수사기관등의 소속 공무원은 제1항에 따라 전자문서로 작성한 조서등 및 범죄신고자등 신원관리카드에 「특정범죄신고자 등 보호법」 제2조제3호의 범죄신고자등이 같은 법에 따라 서명 또는 무인(拇印)을 해야 하는 경우에는 서명 또는 무인 대신 가명으로 전자서명을 하게 해야 한다. 이 경우 가명으로 된 전자서명은 본명(本名)의 서명과 동일한 효력이 있다.', 9716);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16264, null, 9717);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16265, '① 수사기관등의 소속 공무원은 전자화대상문서를 제출받은 경우 전자적인 형태로 변환하고 행정전자서명을 마친 후 전산정보처리시스템에 등재해야 한다.', 9718);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16266, '② 수사기관등의 장은 법 제11조제1항에 따라 전자화대상문서를 전자적인 형태로 변환해 전산정보처리시스템에 등재하는 경우에는 접수 당시 전자화문서의 해시값을 저장하는 등의 기술적 조치를 해야 한다.', 9718);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16267, '① 법 제12조제1항에 따른 전자화대상문서의 보관기간은 법 제20조제1항 각 호의 구분에 따라 정해진 때까지로 한다.', 9719);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16268, '② 수사기관등은 법 제12조제2항에 따라 전자화대상문서의 반환을 요청받은 경우에는 요청을 받은 날부터 14일 이내에 전자화대상문서를 반환할 것인지를 결정해야 한다.', 9719);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16269, '③ 수사기관등은 전자화대상문서를 제출한 사람에게 법 제12조제3항에 따라 전자화문서와 전자화대상문서의 동일성을 확인할 수 있는 기회를 주는 경우에는 컴퓨터 등 정보처리장치를 이용해 전자화문서를 열람하게 하는 방법으로 그 동일성을 확인할 수 있도록 해야 한다.', 9719);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16270, '④ 법 제12조제3항에 따라 형사사법업무 처리기관으로부터 전자화대상문서를 반환받은 사람은 전자화대상문서의 원본을 해당 형사사법절차가 확정될 때까지 보관해야 한다.', 9719);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16271, '① 수사기관등의 소속 공무원은 전자문서에 오류가 있는 것을 확인한 경우 전산정보처리시스템을 이용해 다음 각 호의 구분에 따라 이를 바로잡을 수 있다.', 9720);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16272, '② 제1항에 따라 전자문서를 폐기하거나 정정한 경우에는 전자문서가 폐기 또는 정정되었다는 사실을 전산정보처리시스템에 기록하고 폐기하거나 정정하기 전의 전자문서를 저장ㆍ보관해야 한다.', 9720);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16273, '③ 제1항 및 제2항의 폐기 또는 정정의 세부적인 절차 및 방법은 각 수사기관등의 장이 정한다.', 9720);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16274, '① 형사사법업무 처리기관은 법 제13조제1항에 따라 전자문서를 다른 형사사법업무 처리기관에 전산정보처리시스템을 통해 송부하는 경우 특별한 사정이 없는 한 문자정보의 검색 및 추출이 가능한 형식으로 송부해야 한다.', 9721);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16275, '② 제1항에 따라 송부된 전자문서는 송부받는 형사사법업무 처리기관의 전산정보처리시스템에 전자적으로 기록된 때에 접수된 것으로 본다.', 9721);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16276, '③ 법 제13조제2항 본문에 따라 전산정보처리시스템을 통해 전자문서를 출력하는 경우 전산정보처리시스템에 접속해 해당 시스템에 저장된 전자문서를 출력하는 방법으로 한다. 이 경우 형사사법업무 처리기관의 장은 출력하는 서면에 고유번호가 출력되도록 하는 등 전자문서의 동일성을 확보하기 위한 기술적 조치를 해야 한다.', 9721);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16277, '④ 법 제13조제2항 단서에 따라 전자문서를 전자적 방법으로 송부받을 수 있는 기관은 전자문서를 송신ㆍ수신할 수 있는 시스템을 갖춘 기관 중 형사사법절차와 관련해 전자문서의 유통 필요성이 인정되는 기관으로서 법무부장관이 지정해 형사사법포털에 공고하는 기관으로 한다.', 9721);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16278, '① 법 제14조제1항제3호에 따라 전자적 송달 및 통지에 동의하여 송달 또는 통지를 전산정보처리시스템을 통해 전자적으로 받을 수 있는 등록사용자는 다음 각 호와 같다.', 9722);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16279, '② 수사기관등이 제1항 각 호의 등록사용자에게 전산정보처리시스템을 이용해 전자문서로 송달ㆍ통지하는 경우에는 종이문서를 송달ㆍ통지하는 것과 동일한 효력이 있다.', 9722);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16280, '① 법 제14조제1항 및 제2항에 따라 전자문서를 전산정보처리시스템에 등재하고 그 사실을 송달ㆍ통지하는 방법은 다음 각 호의 방식에 따른다.', 9723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16281, '② 「형사소송법」 제65조에 따라 준용되는 「민사소송법」 제182조에 따라 교도소ㆍ구치소 또는 국가경찰관서의 유치장에 체포ㆍ구속ㆍ구금 또는 유치(留置)되어 있는 사람에게 전자적 송달 또는 통지를 하는 경우에는 그 교도소ㆍ구치소 또는 국가경찰관서의 장에게 전산정보처리시스템을 통해 전자적으로 송달ㆍ통지한다.', 9723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16282, '③ 법 제14조제1항에 따라 전자적으로 송달ㆍ통지한 경우에는 다음 각 호의 구분에 따른 때에 송달ㆍ통지된 것으로 본다.', 9723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16283, '④ 제1항제2호에 따른 방법으로 송달 또는 통지를 받은 등록사용자는 형사사법포털에 접속해 전산정보처리시스템에 등재된 전자문서를 확인 또는 출력할 수 있다.', 9723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16284, '⑤ 법 제14조제4항 단서에 따라 피의자 또는 피고인 등의 형사사법절차상 권리를 보호하기 위해 필요한 경우로서 통지된 것으로 보지 않는 경우는 다음 각 호의 경우를 말한다.', 9723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16285, '⑥ 전산정보처리시스템을 이용해 송달ㆍ통지된 전자문서를 출력한 서면은 전자문서와 동일한 효력이 있다.', 9723);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16286, '① 전산정보처리시스템 또는 정보통신망에 장애가 발생해 송달 또는 통지를 받을 자가 전자문서를 확인할 수 없는 기간이 1일당 1시간을 초과하는 경우에는 그 날을 법 제14조제4항 본문에 따른 기간에 산입하지 않는다.', 9724);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16287, '② 제1항에도 불구하고 수사기관등이 제36조제1항에 따라 전산정보처리시스템의 점검을 위해 일시적으로 전산정보처리시스템의 사용이 중단된다는 사실을 사전에 공지한 경우로서 사용이 중단된 시간이 4시간 이내인 경우에는 그 날을 법 제14조제4항 본문에 따른 기간에 산입한다.', 9724);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16288, '① 법 제15조제1항제3호에 따라 전산정보처리시스템을 통해 전자문서를 출력한 서면을 「형사소송법」 제60조부터 제65조까지의 규정에 따른 방법으로 송달해야 하는 경우는 다음 각 호와 같다.', 9725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16289, '② 법 제15조제1항에 따라 전자문서를 서면으로 출력하는 경우 전산정보처리시스템에 접속해 시스템에 저장된 전자문서를 출력하는 방법으로 한다. 이 경우 수사기관등의 장은 출력하는 서면에 고유번호가 출력되도록 하는 등 전자문서의 동일성을 확보하기 위한 기술적 조치를 해야 한다.', 9725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16290, '③ 수사기관등의 소속 공무원은 법 제15조제1항에 따라 전자문서를 출력한 서면을 송달하는 경우 「우편법」 제15조제3항에 따른 선택적 우편역무 중 법무부장관이 정하는 방식으로 송달할 수 있다.', 9725);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16291, '① 등록사용자는 다음 각 호의 경우 형사사법포털에 접속해 전산정보처리시스템에 저장된 전자문서의 내용을 확인하고 이를 서면으로 출력하거나 해당 사항을 자신의 정보저장매체 등에 내려받는 방식으로 전자문서를 열람ㆍ등사 또는 복사하거나 교부받을 수 있다.', 9726);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16292, '② 수사기관등은 등록사용자가 아닌 자가 제1항 각 호에 따라 전자문서 또는 전자기록의 열람ㆍ등사ㆍ복사 또는 교부를 신청하는 경우 해당 전자문서 또는 전자기록을 정보저장매체 등에 복사해 교부할 수 있다.', 9726);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16293, '③ 전자문서 또는 전자기록을 열람ㆍ등사 또는 복사하거나 교부받으려는 사람이 교도소ㆍ구치소 또는 국가경찰관서의 유치장에 체포ㆍ구속ㆍ구금 또는 유치되어 있는 경우에는 전산정보처리시스템을 통해 전자문서를 출력한 서면을 교부하거나 제4항에 따른 방법으로 열람하게 한다.', 9726);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16294, '④ 수사기관등은 다음 각 호의 경우에는 컴퓨터 등 정보처리장치를 이용해 전자문서를 열람하게 할 수 있다.', 9726);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16295, '⑤ 제4항에도 불구하고 질병이나 부상 등의 사유로 컴퓨터 등 정보처리장치를 이용해 열람하기 어려운 경우에는 전자문서를 출력한 서면을 이용해 열람하게 할 수 있다. 이 경우 출력한 서면은 열람을 마친 후 회수한다.', 9726);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16296, '⑥ 수사기관등의 장은 전자문서를 열람ㆍ등사ㆍ복사 또는 출력할 때 전산정보처리시스템에 저장된 전자문서와 동일한 전자문서가 열람ㆍ등사ㆍ복사 또는 출력될 수 있도록 해시값을 비교하거나 출력하는 서면에 고유번호가 출력되도록 하는 등의 기술적 조치를 해야 한다.', 9726);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16297, '⑦ 수사기관등의 장은 전자문서를 열람ㆍ등사ㆍ복사 또는 출력할 때 개인정보의 일부 또는 전부를 삭제하거나 대체함으로써 특정 개인을 식별할 수 없도록 하는 비식별화 조치를 한 전자문서가 열람ㆍ등사ㆍ복사 또는 출력되도록 할 수 있다.', 9726);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16298, '① 형사사법업무 처리기관 상호 간에 사건기록을 송부하는 경우에는 전산정보처리시스템을 통해 전자기록을 전송하는 방법으로 한다.', 9727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16299, '② 제1항에 따라 사건기록을 전송한 경우로서 법 제11조제1항 단서에 따라 변환ㆍ등재하지 않은 전자화대상문서를 보관하거나 법 제12조제1항에 따라 전자화대상문서를 보관해야 하는 경우 해당 전자화대상문서는 법령에 따라 사건기록을 보존해야 하는 형사사법업무 처리기관에서 보관한다.', 9727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16300, '③ 제2항에 따라 보관하는 전자화대상문서의 송부시기와 방법 등은 해당 형사사법업무 처리기관이 협의하여 정한다.', 9727);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16301, '① 검사는 다음 각 호의 경우를 제외하고는 전산정보처리시스템을 통해 형사사법절차에 관한 법원의 전자소송시스템(이하 "전자소송시스템"이라 한다)으로 전자문서나 전자기록을 제출해야 한다.', 9731);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16302, '② 검사는 법원에 제출해야 하는 문서 등이 전자문서로 작성되었으나 제1항 각 호의 어느 하나에 해당하는 경우에는 전자문서나 전자기록을 전산정보처리시스템을 통해 출력하여 제출하거나 정보저장매체에 저장하여 제출할 수 있다.', 9731);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16303, '① 검사는 공판정에서 컴퓨터, 이동통신단말장치(「전파법」에 따라 할당받은 주파수를 사용하는 기간통신역무를 이용하기 위해 필요한 단말장치를 말한다. 이하 같다) 또는 그 밖에 이에 준하는 정보처리능력을 갖춘 장치로 전산정보처리시스템에 접속해 전자기록ㆍ신원관리카드 등의 열람, 공판카드의 작성, 증거의 신청ㆍ제출 등 공소유지 업무를 수행할 수 있다.', 9732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16304, '② 검사는 공판정에서 컴퓨터, 이동통신단말장치 또는 그 밖에 이에 준하는 정보처리능력을 갖춘 장치를 이용해 증거신청서, 증거 목록, 증인신문청구서, 공소장변경신청서 등 공소유지에 필요한 전자문서를 전자소송시스템으로 송부할 수 있다.', 9732);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16305, '① 수사기관등은 전산정보처리시스템에 기록된 전자문서에 대해 위작ㆍ변작ㆍ훼손ㆍ유출 등을 방지하기 위한 기술적 조치(「개인정보 보호법」 제29조에 따른 안전성 확보에 필요한 조치를 포함한다)를 해야 한다.', 9734);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16306, '② 수사기관등의 소속 공무원은 현장검증, 재택근무, 현장수사, 현장 지도ㆍ감독 그 밖의 업무상 필요하다고 인정되는 경우에는 수사기관등의 청사 외의 곳에서 컴퓨터, 이동통신단말장치 또는 그 밖에 이에 준하는 정보처리능력을 갖춘 장치를 이용해 전자기록을 사용할 수 있다. 이 경우 전자기록이 정당한 사유 없이 공개ㆍ위작ㆍ변작ㆍ훼손 또는 유출되지 않도록 해야 한다.', 9734);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16307, '① 수사기관등의 장은 전산정보처리시스템의 점검을 위해 필요한 시간 동안 전산정보처리시스템의 이용을 일시적으로 제한할 수 있다.', 9735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16308, '② 수사기관등의 장은 전산정보처리시스템에 장애가 발생하거나 그 밖의 부득이한 사정으로 전산정보처리시스템을 사용할 수 없는 때에는 장애가 발생한 사실을, 장애를 복구한 때에는 그 복구한 사실을 각각 수사기관등의 홈페이지 및 형사사법포털에 게시해야 한다.', 9735);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16309, '① 수사기관등은 법 제20조제2항에 따라 교정기관의 수용ㆍ구금ㆍ교정 또는 형집행과 관련된 전자문서나 다음 각 호의 어느 하나에 해당하는 사건의 전자기록을 영구 보관하거나 같은 조 제1항에 따른 폐기 시기를 늦출 수 있다.', 9736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16310, '② 제1항에 따라 전자문서를 영구 보관하거나 폐기 시기를 늦추려는 경우에는 「공공기록물 관리에 관한 법률 시행령」 제43조에 따른 절차를 거쳐야 한다.', 9736);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16311, '① 수사자료표에는 다음 각 호의 사항을 기재한다. <개정 2022.7.5>', 9738);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16312, '② 검찰청ㆍ사법경찰관서 등 수사기관의 장은 수사자료표의 정확한 관리를 위해 입건현황과 처분현황 또는 선고현황 등을 지체 없이 경찰청에 송부해야 한다. <개정 2024.4.2>', 9738);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16313, '③ 경찰청장은 수사자료표의 내용 중 피의자의 인적사항이 일치하지 않는 등으로 처분결과 또는 선고결과가 확인되지 않는 경우에는 관계 기관에 확인을 하는 등 정확한 처분현황 또는 선고현황을 관리하기 위해 필요한 조치를 해야 한다. <개정 2024.4.2>', 9738);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16314, '④ 수사자료표를 작성하는 경우 지문을 채취할 피의자의 범위와 그 밖에 필요한 사항은 법무부령으로 정한다. <개정 2024.4.2>', 9738);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16315, null, 9743);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16316, '①전과기록 또는 수사경력자료의 보존ㆍ관리 또는 조회관련 업무를 담당하는 기관의 장은 그 업무를 직접 담당하고 있는 부서의 최상급책임자를 관리책임자로 지정하여 그 보존ㆍ관리 또는 조회에 관한 운영 및 지도업무를 담당하도록 하여야 한다.', 9744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16317, '②제1항의 규정에 의한 관리책임자는 조회ㆍ회보대장을 비치하고 조회목적, 조회요청자의 소속ㆍ성명, 작성자 및 작성일시 그 밖에 필요한 사항을 기재하여야 한다.', 9744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16318, '③전과기록 또는 수사경력자료의 보존ㆍ관리 또는 조회관련 업무를 담당하는 기관의 장은 전과기록 또는 수사경력자료의 내용이 불법유출되거나 범죄수사ㆍ재판 등 법 및 다른 법령에 규정된 목적외의 다른 목적으로 사용되지 아니하도록 조회ㆍ회보대장을 수시로 점검하는 등 필요한 조치를 하여야 한다.', 9744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16319, '④ 삭제 <2006.7.27>', 9744);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16320, '①법 제6조제1항제1호부터 제4호까지의 경우에는 범죄경력자료 및 수사경력자료 전부에 대하여 범죄경력조회ㆍ수사경력조회 및 그 회보를 할 수 있다. <개정 2022.7.5>', 9745);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16321, '②법 제6조제1항제5호부터 제9호까지의 규정에 따라 수사자료표에 의한 범죄경력조회ㆍ수사경력조회 및 그 회보를 할 수 있는 범위는 다음 각 호와 같다. <개정 2006.7.27, 2015.11.4>', 9745);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16322, '③법 제6조제1항제10호의 경우에는 다른 법률에서 구체적으로 정한 범위에 한하여 조회 및 그 회보를 할 수 있다. <개정 2006.7.27>', 9745);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16323, '④ 삭제 <2007.12.28>', 9745);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16324, '① 「소년법」상의 소년부송치 및 보호처분은 제7조제1항에 해당하는 경우가 아니면 그 결정이 있은 때부터 3년이 지난 후에는 회보를 하여서는 아니 된다.', 9746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16325, '② 제7조제1항에도 불구하고 법 제6조제1항제4호에 따라 수사자료표의 내용을 확인하기 위하여 본인이 신청하는 경우에는 본인이 별도로 요구하지 아니하는 한 다음 각 호의 사항을 제외하고 회보하여야 한다. <개정 2015.11.4, 2024.4.2>', 9746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16326, '③ 제7조제1항에도 불구하고 법 제6조제1항제4호에 따라 외국 입국ㆍ체류 허가에 필요하여 본인이 신청하는 경우에는 다음 각 호의 사항을 제외하고 회보하여야 한다. <신설 2015.11.4, 2024.4.2>', 9746);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16327, '①법 제8조제2항의 규정에 의한 수형인명부의 해당란의 삭제는 수형인명부의 해당란에 가로로 두 줄을 긋고 수형인명부관리자의 직인을 날인하는 방법으로 한다. <개정 2003.9.29, 2006.7.27>', 9747);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16328, '② 법 제8조의2제1항에 따른 수사경력자료의 해당 사항 삭제는 같은 조 제2항부터 제4항까지에 따른 수사경력자료의 보존기간이 경과한 때에 해당 사항을 전산자료에서 지체 없이 삭제하는 방법으로 하되, 삭제한 사람의 소속과 성명 및 삭제 일시 등 삭제에 관한 사항을 삭제한 날부터 5년간 전산으로 관리해야 한다. <개정 2024.4.2>', 9747);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16329, '①경찰청장은 수사자료표에 등재된 사람이 사망한 때에는 그 수사자료표를 폐기할 수 있다.', 9748);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16330, '②경찰청장은 수사자료표를 마이크로필름 또는 전산자료의 형태로 관리ㆍ보존하는 경우에는 종전의 수사자료표를 폐기할 수 있다.', 9748);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16331, null, 9749);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16332, '① 교도소ㆍ구치소 및 그 지소(支所)(이하 "교정시설"이라 한다)의 장은 가석방이 허가된 사람을 석방할 때에는 그 사실을 가석방될 사람의 주거지를 관할하는 지방검찰청의 장(지방검찰청 지청의 장을 포함한다. 이하 같다)과 형을 선고한 법원에 대응하는 검찰청 검사장 및 가석방될 사람을 보호ㆍ감독할 경찰서(이하 "관할경찰서"라 한다)의 장에게 미리 통보하여야 한다.', 9753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16333, '② 교정시설의 장은 가석방이 허가된 사람에게 가석방의 취소 및 실효사유와 가석방자로서 지켜야 할 사항 등을 알리고, 주거지에 도착할 기한 및 관할경찰서에 출석할 기한 등을 적은 가석방증을 발급하여야 한다.', 9753);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16334, '① 가석방자는 그의 주거지에 도착하였을 때에는 지체 없이 종사할 직업 등 생활계획을 세우고 이를 관할경찰서의 장에게 서면으로 신고하여야 한다.', 9755);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16335, '② 가석방자의 보호를 맡은 사람은 제1항의 신고서에 기명날인(記名捺印) 또는 서명하여야 한다.', 9755);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16336, '① 관할경찰서의 장은 가석방자가 가석방 기간 중 정상적인 업무에 종사하고 비행(非行)을 저지르지 아니하도록 적절한 지도를 할 수 있다.', 9756);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16337, '② 관할경찰서의 장은 제1항에 따른 지도 중 가석방자의 재범방지를 위해 특히 필요하다고 인정하는 경우에는 특정 장소의 출입제한명령 등 필요한 조치를 할 수 있다.', 9756);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16338, '③ 관할경찰서의 장은 제2항에 따른 조치를 할 경우 그 사실을 관할 지방검찰청의 장 및 가석방자를 수용하였다가 석방한 교정시설(이하 "석방시설"이라 한다)의 장(이하 "관계기관의 장"이라 한다)에게 통보하여야 한다.', 9756);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16339, '① 관할경찰서의 장은 석방시설의 장의 의견을 들어 가석방자의 보호와 감독을 적당한 사람에게 위임할 수 있다.', 9758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16340, '② 제1항에 따라 보호와 감독을 위임받은 사람은 매월 말일 제8조에서 정한 사항을 관할경찰서의 장에게 보고하여야 한다.', 9758);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16341, '① 가석방자는 국내 주거지 이전(移轉) 또는 1개월 이상 국내 여행(이하 "국내주거지 이전등"이라 한다)을 하려는 경우 관할경찰서의 장에게 신고하여야 한다.', 9759);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16342, '② 제1항에 따른 신고를 하려는 사람은 별지 제2호서식의 신고서(전자문서로 된 신고서를 포함한다)를 관할경찰서의 장에게 제출하여야 한다.', 9759);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16343, '① 관할경찰서의 장은 가석방자가 제10조에 따라 국내주거지 이전등을 신고한 경우에는 제7조제1항 및 제2항에 따른 지도 및 조치를 하여야 한다. 다만, 관할경찰서의 관할 구역에서 주거지를 이전하거나 여행하는 경우에는 그러하지 아니하다. <개정 2016.1.22>', 9760);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16344, '② 제1항의 경우에는 제7조제3항을 준용한다.', 9760);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16345, '① 가석방자는 국외 이주 또는 1개월 이상 국외 여행(이하 "국외 이주등"이라 한다)을 하려는 경우 관할경찰서의 장에게 신고하여야 한다.', 9762);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16346, '② 제1항에 따른 신고를 하려는 사람은 별지 제3호서식의 신고서(전자문서로 된 신고서를 포함한다)에 다음 각 호의 서류(전자문서를 포함한다)를 첨부하여 관할경찰서의 장에게 제출하여야 한다. 이 경우 담당 공무원은 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 가석방자의 주민등록표 초본을 확인하여야 하며, 가석방자가 확인에 동의하지 아니하는 경우에는 이를 제출하도록 하여야 한다. <개정 2017.5.8>', 9762);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16347, '① 법무부장관은 가석방 처분을 취소하였을 때에는 가석방자의 주거지를 관할하는 지방검찰청의 장 또는 교정시설의 장이나 가석방 취소 당시 가석방자를 수용하고 있는 교정시설의 장에게 통보하여 남은 형을 집행하게 하여야 한다.', 9768);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16348, '② 제1항의 경우 제4조제2항에 따라 발급한 가석방증은 효력을 잃는다.', 9768);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16349, '① 가석방자가 사망한 경우 관할경찰서의 장은 그 사실을 관계기관의 장에게 통보하여야 한다.', 9769);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16350, '② 제1항의 통보를 받은 석방시설의 장은 그 사실을 법무부장관에게 보고하여야 한다.', 9769);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16351, null, 9773);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16352, '① 사면, 감형 및 복권의 효과는 다음 각 호와 같다.', 9775);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16353, '② 형의 선고에 따른 기성(旣成)의 효과는 사면, 감형 및 복권으로 인하여 변경되지 아니한다.', 9775);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16354, '① 법무부장관은 대통령에게 특별사면, 특정한 자에 대한 감형 및 복권을 상신(上申)한다.', 9780);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16355, '② 법무부장관은 제1항에 따라 특별사면, 특정한 자에 대한 감형 및 복권을 상신할 때에는 제10조의2에 따른 사면심사위원회의 심사를 거쳐야 한다.', 9780);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16356, '① 제10조제1항에 따른 특별사면, 특정한 자에 대한 감형 및 복권 상신의 적정성을 심사하기 위하여 법무부장관 소속으로 사면심사위원회를 둔다. <개정 2012.2.10>', 9781);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16357, '② 사면심사위원회는 위원장 1명을 포함한 9명의 위원으로 구성한다. <개정 2012.2.10>', 9781);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16358, '③ 위원장은 법무부장관이 되고, 위원은 법무부장관이 임명하거나 위촉하되, 공무원이 아닌 위원을 4명 이상 위촉하여야 한다. <개정 2012.2.10>', 9781);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16359, '④ 공무원이 아닌 위원의 임기는 2년으로 하며, 한 차례만 연임할 수 있다. <개정 2012.2.10>', 9781);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16360, '⑤ 사면심사위원회의 심사과정 및 심사내용의 공개범위와 공개시기는 다음 각 호와 같다. 다만, 제2호 및 제3호의 내용 중 개인의 신상을 특정할 수 있는 부분은 삭제하고 공개하되, 국민의 알권리를 충족할 필요가 있는 등의 사유가 있는 경우에는 사면심사위원회가 달리 의결할 수 있다. <개정 2011.7.18>', 9781);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16361, '⑥ 위원은 사면심사위원회의 업무를 처리하면서 알게 된 비밀을 누설하여서는 아니 된다. <개정 2012.2.10>', 9781);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16362, '⑦ 위원은 「형법」이나 그 밖의 법률에 따른 벌칙을 적용할 때에는 공무원으로 본다. <개정 2012.2.10>', 9781);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16363, '⑧ 제1항부터 제7항까지에서 규정한 사항 외에 사면심사위원회에 관하여 필요한 사항은 법무부령으로 정한다. <개정 2012.2.10>', 9781);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16364, '① 형의 집행을 지휘한 검찰청의 검사와 수형자가 수감되어 있는 교정시설의 장이 특별사면 또는 특정한 자에 대한 감형을 제청하려는 경우에는 제14조에 따른 서류를 첨부하고 제청 사유를 기재한 보고서를 검찰총장에게 제출하여야 한다.', 9783);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16365, '② 교정시설의 장이 제1항의 보고서를 제출하는 경우에는 형의 집행을 지휘한 검찰청의 검사를 거쳐야 한다.', 9783);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16366, null, 9785);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16367, '① 검찰총장은 직권으로 또는 형의 집행을 지휘한 검찰청 검사의 보고 또는 사건 본인의 출원(出願)에 의하여 법무부장관에게 특정한 자에 대한 복권을 상신할 것을 신청할 수 있다.', 9786);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16368, '② 제1항에 따른 상신의 신청은 형의 집행이 끝난 날 또는 집행이 면제된 날부터 3년이 지나지 아니하면 하지 못한다.', 9786);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16369, null, 9787);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16370, '① 법무부장관은 특별사면, 특정한 자에 대한 감형 또는 복권 상신의 신청이 이유 없다고 인정할 때에는 그 사유를 검찰총장에게 통지한다.', 9791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16371, '② 검찰총장은 제1항에 따라 통지받은 사유를 관계 검찰청의 검사, 교정시설의 장 또는 사건 본인에게 통지하여야 한다.', 9791);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16372, '① 검사는 집행정지 중 또는 가출소(假出所) 중에 있는 자에 대한 사면장, 감형장 또는 복권장을 접수하였을 때에는 그 사실을 사건 본인이 수감되어 있던 교정시설의 장과 감독 경찰관서에 통지하여야 한다.', 9794);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16373, '② 검사는 집행유예 중에 있는 자가 특별사면 또는 감형되거나 복권된 경우에는 그 사실을 감독 경찰관서에 통지하여야 한다.', 9794);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16374, '① 사건 본인이 형의 집행을 지휘한 검찰청의 관할구역이 아닌 곳에 거주하는 경우에는 사면장, 감형장 또는 복권장의 부여를 그의 거주지를 관할하는 검찰청의 검사에게 촉탁(囑託)할 수 있다.', 9795);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16375, '② 제1항의 경우에 제23조에 따른 통지는 촉탁받은 검찰청의 검사가 한다.', 9795);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16376, '① 사면, 감형 또는 복권이 있을 때에는 형의 집행을 지휘한 검찰청의 검사는 판결원본에 그 사유를 덧붙여 적어야 한다.', 9796);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16377, '② 특별사면, 특정한 자에 대한 감형 및 복권에 관한 서류는 소송기록에 철한다.', 9796);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16378, null, 9801);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16379, '① 위원은 특별사면등의 심사대상자와 가족 또는 친족관계에 있거나 있었던 경우 또는 그 밖의 사정으로 공정한 심사가 어렵다고 판단되는 경우에는 그 심사대상자에 대한 심사를 회피하여야 한다.', 9803);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16380, '② 제1항에 따른 회피는 위원장에게 구두 또는 서면으로 신청하여야 한다.', 9803);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16381, '③ 위원장은 제2항에 따른 회피신청이 이유가 있다고 인정하는 경우에는 이를 허용하여야 한다.', 9803);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16382, '① 위원장은 위원회를 대표하고, 위원회의 업무를 총괄한다.', 9804);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16383, '② 위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 위원장이 미리 지명한 위원이 그 직무를 대행한다.', 9804);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16384, '① 위원회의 회의는 위원장이 소집한다.', 9805);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16385, '② 위원회의 회의는 재적위원 과반수의 출석으로 개의(開議)하고, 출석위원 과반수의 찬성으로 의결한다.', 9805);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16386, '③ 위원회는 필요한 경우에는 위원이 아닌 자를 회의에 출석하게 하여 그 의견을 들을 수 있다.', 9805);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16387, '① 위원회의 사무를 처리하기 위하여 위원회에 간사 1명과 서기 약간 명을 둔다.', 9806);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16388, '② 간사는 법무부 형사기획과장이 된다. 다만, 법무부장관은 법무부 소속의 다른 공무원을 간사로 임명할 수 있다.', 9806);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16389, '③ 간사는 위원장의 명을 받아 위원회의 사무를 처리하고 회의에 참석하여 발언할 수 있다.', 9806);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16390, '④ 서기는 간사를 보조한다.', 9806);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16391, '① 위원회의 심사가 종료된 때에는 심의서를 작성하여야 한다.', 9808);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16392, '② 심의서에는 위원회에서 특별사면등 상신의 적정성에 관하여 심사한 결과에 따라 심사대상자별로 적정 또는 부적정 의견을 기재한다.', 9808);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16393, '③ 심사과정에서 제시된 개별 위원의 의견은 심의서에 표시하지 아니한다.', 9808);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16394, '④ 심의서에는 위원장 및 출석위원 전원이 서명 또는 기명ㆍ날인한다.', 9808);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16395, '⑤ 위원이 부득이한 사유로 서명 또는 기명ㆍ날인할 수 없는 경우에는 그 사유를 기재하고 위원장이 서명 또는 기명ㆍ날인한다.', 9808);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16396, '① 위원회를 개최하였을 때에는 간사가 회의록을 작성하여야 한다.', 9809);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16397, '② 회의록에는 회의 개요, 심사대상, 위원회의 심사의견, 그 밖의 주요 논의사항 등을 기재한다.', 9809);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16398, '③ 위원회 심사과정에서 심사대상에 대한 특별사면등 상신의 적정성에 관하여 각 위원의 의견이 일치하지 아니한 경우에는 회의록에 개별 위원의 의견을 기재하여야 한다.', 9809);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16399, '④ 회의록에는 위원장과 간사가 서명 또는 기명ㆍ날인한다.', 9809);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16400, null, 9810);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16401, '① 「범죄수익은닉의 규제 및 처벌 등에 관한 법률」(이하 "법"이라 한다) 제13조제1항에 따른 포상금(이하 "포상금"이라 한다) 지급 대상이 되는 신고 또는 공로의 범위는 다음 각 호와 같다.', 9814);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16402, '② 제1항제3호에서 "은닉재산"이란 몰수ㆍ추징의 판결이 확정된 자가 은닉한 현금, 예금, 주식, 그 밖에 재산적 가치가 있는 유형ㆍ무형의 재산을 말한다. 다만, 다음 각 호의 어느 하나에 해당하는 재산은 제외한다. <개정 2021.2.17>', 9814);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16403, '', 9815);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16404, '② 법무부장관은 제1항에 따라 포상금을 결정하는 경우 다음 각 호의 사항을 고려하여야 한다.', 9815);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16405, '③ 포상금의 세부적인 지급 방법과 절차 등에 관하여 필요한 사항은 법무부장관이 정한다.', 9815);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16406, '① 포상금을 받으려는 자는 법무부장관이 정하는 바에 따라 포상금 지급 신청서를 관할 지방검찰청 검사장(지방검찰청 지청장을 포함한다. 이하 같다)에게 제출하여야 한다.', 9816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16407, '② 제1항에 따른 신청은 「민원 처리에 관한 법률 시행령」 제2조제1항제3호에도 불구하고 익명 또는 가명으로 할 수 있다. 이 경우 그 사유에 관하여 신청을 접수한 관할 지방검찰청 검사장의 확인이 있어야 한다. <개정 2016.2.12>', 9816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16408, '③ 제1항에 따른 신청서를 접수한 관할 지방검찰청 검사장은 그 신청서에 법무부장관이 정하는 서류를 첨부하여 법무부장관에게 제출하여야 한다.', 9816);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16409, null, 9817);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16410, null, 9820);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16411, '①피보안관찰자의 주거지를 관할하는 경찰서장(이하 "관할경찰서장"이라 한다)은 피보안관찰자의 동태를 관찰하고 사회에 복귀하도록 선도하여 보안관찰해당범죄를 다시 범하지 아니하도록 예방하여야 한다.', 9822);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16412, '②관할경찰서장은 보안관찰부를 작성ㆍ비치하고 매월 1회이상 피보안관찰자의 동태를 관찰하여 그 결과를 보안관찰부에 기재하여야 한다.', 9822);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16413, '①관할경찰서장은 매 3월마다 법 제18조제2항의 규정에 의하여 신고된 사항을 포함한 피보안관찰자의 주요동태를 주거지 관할검사에게 보고하여야 한다.', 9823);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16414, '②관할경찰서장은 피보안관찰자에게 다음 각호의 1에 해당하는 사유가 발생한 때에는 지체없이 이를 주거지 관할검사에게 보고하여야 한다.', 9823);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16415, '①보안관찰처분대상자가 법 제6조제1항의 규정에 의하여 출소전에 신고할 때에는 다음 각호의 사항을 기재한 신고서 5부를 작성하여 교도소, 소년교도소, 구치소, 유치장 또는 군교도소(이하 "교도소등"이라 한다)의 장에게 제출하여야 한다. <개정 2020.7.28>', 9824);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16416, '②교도소등의 장은 제1항의 규정에 의하여 접수한 신고서 1부씩을 법 제12조의 규정에 의한 보안관찰처분심의위원회(이하 "위원회"라 한다)와 거주예정지관할 검사 및 경찰서장에게 각각 송부하여야 한다.', 9824);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16417, '③교도소등의 장은 제2항의 규정에 의하여 신고서를 송부할 때에는 보안관찰해당범죄에 대한 판결문사본ㆍ행형성적 기타 필요한 서류를 각각 첨부하여야 한다.', 9824);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16418, '①교도소등의 장은 법 제6조제1항의 규정에 의하여 보안관찰처분대상자 신고를 한 자가 출소한 때에는 지체없이 다음 각호의 사항을 거주예정지 관할경찰서장에게 통보하여야 한다.', 9826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16419, '②거주예정지 관할경찰서장은 출소한 보안관찰처분대상자가 법 제6조제1항의 규정에 의한 신고기간내에 신고를 하지 아니한 때에는 지체없이 이를 거주예정지 관할검사에게 보고하여야 한다.', 9826);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16420, '① 출소한 보안관찰처분대상자는 법 제6조제1항에 따라 출소사실을 신고할 때에는 출소일ㆍ출소교도소ㆍ출소사유와 그 밖에 필요한 사항을 기재한 신고서를 작성ㆍ제출해야 하며, 신고서에는 2명 이상의 신원보증인이 서명ㆍ날인해야 한다. 이 경우 신원보증인이 없는 경우에는 그 사유를 명확히 기재해야 한다. <개정 2021.1.5>', 9827);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16421, '②보안관찰처분대상자는 교도소등에서 출소한 후 제6조제1항의 신고사항중에 변동이 있는 때에는 그 변동사항을 기재한 신고서를 작성하여 관할경찰서장에게 제출하여야 한다.', 9827);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16422, '③제1항 및 제2항의 신고서를 접수한 거주예정지 관할경찰서장 또는 관할경찰서장은 신고인에게 신고필증을 교부하여야 하며, 지체없이 이를 그 거주예정지 또는 주거지 관할검사에게 보고하여야 한다.', 9827);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16423, '④거주예정지 관할경찰서장 또는 관할경찰서장은 보안관찰처분대상자가 신고한 거주예정지를 변경하거나 주거지를 이전한 때에는 그 사실여부를 확인한 후 보안관찰처분대상자신고서ㆍ출소사실신고서 기타 관계서류를 변경된 거주예정지 또는 신주거지 관할경찰서장에게 송부하여야 한다.', 9827);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16424, '⑤제4항의 규정에 의하여 관계서류를 송부받은 변경된 거주예정지 또는 신주거지 관할경찰서장은 지체없이 이를 주거지 관할검사에게 보고하여야 한다.', 9827);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16425, '①교도소등의 장은 법 제6조제3항의 규정에 의한 통고를 할 때에는 다음 각호의 사항을 기재한 통고서를 작성하여 위원회와 거주예정지 관할검사 및 경찰서장에게 송부하여야 한다.', 9828);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16426, '②교도소등의 장은 수용되어 있는 보안관찰처분대상자에 대하여 다음 각호의 1에 해당하는 사유가 발생한 때에는 지체없이 이를 위원회와 거주예정지 관할검사 및 경찰서장에게 통보하여야 한다.', 9828);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16427, null, 9829);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16428, '①법 제8조제1항의 규정에 의한 보안관찰처분청구서에는 피청구자의 성명 기타 피청구자를 특정할 수 있는 사항ㆍ청구의 원인이 되는 사실ㆍ청구연월일을 기재하고 검사가 서명ㆍ날인하여야 한다. 이 경우 법 제20조제3항의 규정에 의하여 거소를 제공한 때에는 거소제공 결정연월일 및 제공된 사회복지시설등의 명칭과 그 소재지를 함께 기재하여야 한다.', 9830);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16429, '②법 제8조제3항의 의견서에는 청구취지와 적용법조에 관한 의견을 기재하여야 한다.', 9830);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16430, null, 9831);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16431, '①법 제11조제2항에 따른 보안관찰처분면제결정 신청을 하려는 보안관찰처분대상자는 관할경찰서장에게 다음 각 호의 서류를 첨부한 보안관찰처분면제결정신청서(전자문서로 된 신청서를 포함한다)를 제출해야 한다. 이 경우 관할경찰서장은 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 보안관찰처분대상자의 주민등록표 등본을 확인해야 하며, 보안관찰처분대상자가 확인에 동의하지 않는 경우에는 이를 첨부하도록 해야 한다. <개정 2004.3.17, 2007.7.18, 2010.5.4, 2010.11.2, 2019.10.8>', 9832);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16432, '②관할경찰서장은 제1항의 규정에 의한 신청서를 접수한 때에는 20일이내에 전과관계를 증명할 수 있는 서류와 의견서를 첨부하여 검사에게 송부하여야 한다.', 9832);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16433, '③검사는 제2항의 규정에 의하여 신청서와 관계서류를 송부받은 때에는 20일이내에 의견서를 첨부하여 법무부장관에게 송부하여야 한다.', 9832);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16434, '④제1항제4호의 규정에 의한 신원보증인이 될 수 있는 자는 보안관찰처분대상자가 아닌 자로서 다음 각호의 1에 해당하는 자이어야 한다.', 9832);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16435, '⑤검사는 법 제11조제3항의 규정에 의한 보안관찰처분면제결정 청구를 함에 있어서는 보안관찰처분면제결정청구서에 보안관찰처분대상자가 법 제11조제1항제1호 및 제2호에 해당한다는 의견서와 기타 필요한 서류를 첨부하여 법무장관에게 제출하여야 한다.', 9832);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16436, '①법무부장관은 법 제12조제9항 각호의 1에 해당하는 결정의 신청을 받은 때에는 이를 심사한 후 지체없이 위원회에 그 사안을 회부하여야 한다.', 9833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16437, '②위원회는 제1항의 규정에 의하여 사안을 회부받은 때에는 이를 심의ㆍ의결하고 그 결과를 위원장과 출석위원 전원이 서명ㆍ날인한 문서로써 법무부장관에게 통보하여야 한다.', 9833);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16438, '①위원회에 간사 2인과 서기 약간인을 둔다.', 9834);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16439, '②간사 및 서기는 법무부소속 직원중에서 법무부장관이 임명한다.', 9834);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16440, '③간사는 위원장의 명을 받아 위원회의 서무를 처리하고 회의에 참석하여 발언할 수 있으며, 서기는 간사를 보조한다.', 9834);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16441, '①서기는 위원장의 명을 받아 위원회의 회의록을 작성ㆍ비치하여야 한다.', 9835);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16442, '②회의록에는 회의의 전말을 기재하고 위원장이 서명ㆍ날인하여야 한다.', 9835);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16443, '①관할경찰서장은 법 제17조제3항의 규정에 의한 사유가 발생한 때에는 주거지 관할검사에게 주거지 리ㆍ통ㆍ반의 장의 확인서 기타 피보안관찰자가 도주 또는 소재불명임을 인정할 수 있는 자료를 첨부하여 보안관찰처분집행중지결정을 신청하여야 한다. 이 경우 주거지 관할검사는 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 피보안관찰자의 주민등록표 등본을 확인하여야 한다. <개정 2004.3.17, 2007.7.18, 2010.5.4, 2010.11.2>', 9841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16444, '②검사는 법 제17조제3항 전단의 규정에 의하여 보안관찰처분의 집행중지결정을 할 때에는 피보안관찰자의 성명 기타 피보안관찰자를 특정할 수 있는 사항, 보안관찰처분 결정일 및 그 기간갱신일, 집행중지사유, 집행중지결정일 기타 필요한 사항을 기재한 보안관찰처분 집행중지결정서를 작성하여야 한다.', 9841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16445, '③검사는 보안관찰처분의 집행중지결정을 한 때에는 관할경찰서장에게 보안관찰처분 집행중지결정의 집행지휘를 하고 지체없이 이를 법무부장관에게 보고하여야 한다.', 9841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16446, '④검사는 법 제17조제3항 후단의 규정에 의하여 보안관찰처분의 집행중지결정을 취소할 때에는 피보안관찰자의 성명 기타 피보안관찰자를 특정할 수 있는 사항, 집행중지결정일, 집행중지결정취소사유, 취소결정일 기타 필요한 사항을 기재한 보안관찰처분집행중지 취소결정서를 작성하여야 한다.', 9841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16447, '⑤피보안관찰자는 검사의 보안관찰처분 집행중지결정에 이의가 있거나 그 집행중지결정의 사유가 소멸된 때에는 관할경찰서장을 거쳐 검사에게 보안관찰처분 집행중지결정의 취소신청을 할 수 있다.', 9841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16448, '⑥검사는 제5항의 취소신청이 이유있다고 인정하는 때에는 보안관찰처분의 집행중지결정을 취소하고 지체없이 이를 신청인에게 고지하여야 한다. 신청이 이유없다고 인정하여 기각하는 때에는 그 취지를 고지하여야 한다.', 9841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16449, '⑦검사는 제4항 및 제6항의 규정에 의한 취소를 한 때에는 관할경찰서장에게 보안관찰처분 집행중지결정의 취소지휘 또는 보안관찰처분의 잔기간집행지휘를 하고 지체없이 이를 법무부장관에게 보고하여야 한다.', 9841);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16450, '①법 제18조제1항제8호의 규정에 의하여 피보안관찰자가 신고하여야 할 사항은 다음과 같다.', 9842);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16451, '②피보안관찰자는 법 제18조제4항의 규정에 의한 신고를 할 때에는 다음 각호의 구분에 따라 관련사항을 기재한 신고서를 작성ㆍ제출하여야 한다.', 9842);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16452, '③관할경찰서장은 제2항제1호 및 제3호의 규정에 의한 신고서를 접수한 때에는 지체없이 그 사실을 이전예정지 또는 여행목적지 관할경찰서장에게 통보하여야 한다.', 9842);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16453, '④관할경찰서장은 피보안관찰자가 주거지를 이전한 때에는 지체없이 신주거지 관할경찰서장에게 보안관찰부 기타 관계서류를 송부하여야 한다.', 9842);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16454, '⑤제4항의 규정에 의하여 관계서류를 송부받은 신거주지 관할경찰서장은 지체없이 그 주거지 이전의 사실을 신주거지 관할검사에게 보고하여야 한다.', 9842);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16455, '①검사 및 사법경찰관리는 피보안관찰자의 재범을 방지하고 건전한 사회복귀를 촉진하기 위하여 피보안관찰자와의 면접과 통신, 가족 및 그 관계인과의 협의, 거소제공된 사회복지시설등의 장 및 관계기관과의 협조에 의하여 계속적으로 관찰ㆍ지도하여야 하며, 피보안관찰자 및 그 관계인의 신뢰와 협력을 얻도록 노력하여야 한다.', 9843);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16456, '②검사 및 사법경찰관은 법 제19조제2항의 규정에 의하여 피보안관찰자의 재범방지를 위한 조치를 할 때에는 피보안관찰자에게 조치의 취지를 설명하고 조치사항을 기재한 서면을 교부하여야 한다.', 9843);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16457, '③사법경찰관은 제2항의 조치를 할 때에는 긴급을 요하는 경우를 제외하고는 미리 주거지 관할검사에게 보고하여야 한다.', 9843);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16458, '④제2항의 조치는 피보안관찰자의 재범방지를 위하여 특히 필요하다고 인정되는 구체적 사항으로서 피보안관찰자의 자유를 부당하게 제한하지 아니하도록 하여야 한다.', 9843);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16459, '①법 제20조제3항의 규정에 의한 거소제공은 검사의 청구에 의하여 법무부장관이 결정한다.', 9844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16460, '②교도소등의 장은 수용중인 보안관찰처분대상자 또는 피보안관찰자중 거소제공이 필요한 자(이하 "거소제공대상자"라 한다)가 생긴 때에는 특별한 사유가 있는 경우를 제외하고는 출소예정일 2월전까지 교도소등의 소재지 관할검사에게 거소제공의 청구를 신청하여야 한다.', 9844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16461, '③관할경찰서장은 그 관할구역내에 거소제공대상자가 생긴때에는 지체없이 주거지 관할검사에게 거소제공의 청구를 신청하여야 한다.', 9844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16462, '④교도소등의 장 및 관할경찰서장은 제2항 또는 제3항의 규정에 의한 신청을 하는 때에는 거소제공대상자의 성명 기타 거소제공대상자임을 특정할 수 있는 사항, 거소제공의 필요사유, 행형성적 또는 최근의 동태를 기재한 신청서와 거소제공에 필요한 자료를 제출하여야 한다.', 9844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16463, '⑤검사는 법무부장관에게 거소제공을 청구하는 때에는 청구서와 거소제공에 필요한 자료를 제출하여야 한다.', 9844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16464, '⑥법무부장관은 거소제공대상자에 대하여 거소제공이 필요하다고 인정하는 때에는 사회복지사업법에 의한 사회복지시설 기타 본인의 건전한 사회복귀를 위하여 도움이 되는 적절한 시설을 지정하여야 한다.', 9844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16465, '⑦검사는 법무부장관이 제6항의 규정에 의하여 거소제공의 결정을 한 때에는 지체없이 교도소등의 장 또는 관할 경찰서장, 사회복지시설등의 장에게 결정내용 및 결정일을 통보하여야 한다.', 9844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16466, '⑧거소제공대상자에 대한 거소제공결정의 고지는 검사가 거소제공결정서등본을 송달하는 방법으로 한다.', 9844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16467, '⑨교도소등의 장은 거소제공대상자가 출소하는 때에 지체없이, 관할경찰서장은 거소제공결정의 통보를 받은 때에 지체없이 거소제공결정을 받은 보안관찰처분대상자 또는 피보안관찰자를 지정된 사회복지시설등의 장에게 인계하고 즉시 이를 검사에게 보고하여야 한다.', 9844);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16468, '①거소제공을 받은 자는 법 제20조제5항의 규정에 의하여 거소변경을 신청하는 때에는 관할경찰서장에게 거소변경 신청서와 거소변경이 필요함을 인정할 수 있는 서류를 제출하여야 한다.', 9845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16469, '②관할경찰서장은 제1항의 규정에 의하여 신청서와 관계서류를 접수한 때에는 20일이내에 의견서와 거소변경에 필요한 자료를 첨부하여 주거지 관할 검사에게 송부하여야 한다.', 9845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16470, '③검사는 제2항의 규정에 의하여 신청서와 관계서류를 송부받은 때에는 20일이내에 의견서와 거소변경에 필요한 자료를 첨부하여 법무부장관에게 송부하여야 한다.', 9845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16471, '④검사는 법 제20조제5항의 규정에 의하여 거소변경의 청구를 하는 때에는 법무부장관에게 거소변경 청구서와 의견서 및 거소변경에 필요한 자료를 제출하여야 한다.', 9845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16472, '⑤제26조제6항 내지 제9항의 규정은 법무부장관이 거소변경결정을 하는 경우에 이를 준용한다.', 9845);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16473, '①검사는 긴급을 요하여 법무부장관의 거소제공결정 또는 거소변경결정을 기다릴 여유가 없는 때에는 사회복지시설등의 장과 협의하여 거소제공대상자에게 임시거소를 제공할 수 있다.', 9846);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16474, '②검사는 제1항의 규정에 의한 임시거소의 제공을 한 때에는 지체없이 이를 법무부장관에게 보고하여야 한다.', 9846);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16475, '①법 제20조제4항의 사회복지시설은 사회복지사업법에 의한 사회복지시설중 기거와 침식을 제공할 수 있는 시설로 한다.', 9847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16476, '②법무부장관은 제1항의 시설을 거소로 지정하는 때에는 보건복지부장관의 의견을 들어야 한다. <개정 1994.12.23, 2008.2.29, 2010.3.15>', 9847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16477, '③사회복지시설등의 장은 보호하고 있는 보안관찰처분대상자 또는 피보안관찰자에 대하여 다음 각호의 1에 해당하는 사유가 발생한 때에는 지체없이 이를 관할경찰서장에게 통보하여야 한다.', 9847);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16478, '①법 제21조의 규정에 의한 응급구호는 다음 각호의 1에 해당하는 경우에 실시할 수 있다.', 9848);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16479, '②사법경찰관리는 제1항의 규정에 의한 응급구호를 행한 때에는 지체없이 이를 검사에게 보고하여야 한다.', 9848);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16480, null, 9854);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16481, '① 검사는 회복대상재산을 보관하게 된 때에는 피해자등에게 회복대상재산을 환부하기 위한 절차(이하 "범죄피해재산 환부절차"라 한다)를 개시해야 한다. 다만, 회복대상재산의 가액이 비용에 미치지 못할 것으로 예상되는 등 범죄피해재산 환부절차를 개시하는 것이 적절하지 않다고 인정하는 경우에는 그렇지 않다.', 9855);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16482, '② 검사는 회복대상재산을 추가적으로 보관하게 될 가능성이나 회복대상재산의 환가(換價) 절차에 걸리는 기간 등을 고려하여 제1항에 따른 범죄피해재산 환부절차의 개시시기를 조정할 수 있다.', 9855);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16483, '③ 검사는 회복대상재산이 금전 외의 재산으로서 그 재산의 성질, 권리관계 등에 비추어 그대로 보관하는 것이 적절하지 않다고 인정하는 경우에는 이를 환가하거나 징수해서 금전으로 보관할 수 있다.', 9855);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16484, '① 검사는 범죄피해재산 환부절차를 개시한 경우 다음 각 호의 사항을 피해자등에게 신속하게 통지해야 한다.', 9857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16485, '② 검사는 피해자등이 소재불명(所在不明)이거나 그 밖의 사유로 제1항에 따른 통지를 할 수 없는 경우에는 제1항 각 호의 사항을 관보와 검사가 소속된 검찰청 인터넷 홈페이지에 공고해야 한다.', 9857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16486, '③ 제1항에 따른 통지 및 제2항에 따른 공고에 필요한 사항은 법무부령으로 정한다.', 9857);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16487, '① 피해자등은 회복대상재산의 환부를 받으려는 경우에는 제5조제1항에 따른 통지를 받은 날 또는 같은 조 제2항에 따른 공고일부터 60일 이내에 회복대상재산을 보관하고 있는 검사에게 다음 각 호의 사항을 적은 청구서를 작성하여 법무부령으로 정하는 바에 따라 회복대상재산의 환부를 청구해야 한다. 이 경우 청구서에는 다음 각 호의 사항을 소명(疏明)할 수 있는 자료를 첨부해야 한다.', 9858);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16488, '② 청구인은 제1항에 따라 청구서를 제출한 후 청구사항을 변경하려는 경우에는 제7조에 따른 회복대상재산 환부결정이 있기 전에 제1항에 따른 청구를 한 검사에게 법무부령으로 정하는 바에 따라 변경사항을 신고해야 한다.', 9858);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16489, '① 검사는 제6조에 따른 환부청구를 받은 경우에는 다음 각 호의 구분에 따라 신속하게 피해인정재산 및 그 가액과 회복대상재산의 환부 여부를 결정해야 한다.', 9859);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16490, '② 검사는 제1항 각 호에 따른 결정을 하는 데 필요한 조사를 할 수 있다.', 9859);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16491, '③ 검사는 제1항 각 호에 따른 결정을 했을 때에는 지체 없이 그 결정 취지와 이유를 법무부령으로 정하는 바에 따라 청구인에게 통지해야 한다.', 9859);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16492, '① 검사는 제7조제1항제1호 또는 제3호의 결정을 했을 때에는 지체 없이 청구인에게 피해인정재산의 범위에서 각 호의 구분에 따라 회복대상재산을 환부해야 한다.', 9860);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16493, '② 청구인은 제1항제1호에 따라 금전 외의 재산을 환부받으려는 경우에는 검사가 소속된 검찰청에 비용을 납부해야 한다.', 9860);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16494, '③ 검사는 제7조제1항제1호 또는 제3호의 결정을 받은 청구인이 2인 이상인 경우로서 보관하고 있는 회복대상재산으로 각 청구인의 피해인정재산을 모두 환부할 수 없을 때에는 각 청구인의 피해인정재산의 가액에 비례하여 환부한다.', 9860);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16495, '① 청구인은 제7조제1항제2호부터 제4호까지에 따른 결정에 불복하는 경우 그 결정에 대한 통지를 받은 날부터 30일 이내에 해당 결정을 한 검사가 소속된 검찰청의 장에게 법무부령으로 정하는 바에 따라 이의신청을 할 수 있다.', 9862);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16496, '② 제1항에 따른 이의신청을 받은 검찰청의 장은 제11조에 따른 범죄피해재산환부심의회를 거쳐 다음 각 호의 구분에 따라 결정한다.', 9862);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16497, '③ 검찰청의 장은 제2항 각 호에 따른 결정을 한 경우 지체 없이 결정의 취지와 이유를 법무부령으로 정하는 바에 따라 이의신청을 한 청구인에게 통지해야 한다.', 9862);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16498, '① 회복대상재산의 환부에 관한 사항을 심의하기 위해 각 검찰청에 범죄피해재산환부심의회(이하 "심의회"라 한다)를 둔다.', 9863);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16499, '② 심의회는 다음 각 호의 사항을 심의한다.', 9863);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16500, '③ 심의회는 위원장 1명을 포함하여 4명 이상 7명 이내의 위원으로 구성한다.', 9863);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16501, '④ 심의회의 위원장은 각 검찰청의 장이 소속 직원 중에서 지명한다.', 9863);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16502, '⑤ 심의회의 위원(이하 "위원"이라 한다)은 각 검찰청의 장이 위촉하거나 임명하되, 변호사 자격이 있는 사람을 2명 이상 포함해야 한다.', 9863);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16503, '⑥ 제5항에 따라 위촉된 위원의 임기는 2년으로 하고, 한 차례만 연임할 수 있다.', 9863);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16504, '⑦ 심의회의 사무를 처리하기 위해 심의회에 간사를 두며, 간사는 범죄피해재산 환부절차를 담당하는 검사가 된다.', 9863);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16505, '⑧ 제1항부터 제7항까지에서 규정한 사항 외에 심의회의 구성 및 운영에 필요한 사항은 법무부령으로 정한다.', 9863);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16506, null, 9867);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16507, null, 9868);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16508, '① 검사는 사람에 대하여 성폭력범죄를 저지른 성도착증 환자로서 성폭력범죄를 다시 범할 위험성이 있다고 인정되는 19세 이상의 사람에 대하여 약물치료명령(이하 "치료명령"이라고 한다)을 법원에 청구할 수 있다. <개정 2012.12.18>', 9869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16509, '② 검사는 치료명령 청구대상자(이하 "치료명령 피청구자"라 한다)에 대하여 정신건강의학과 전문의의 진단이나 감정을 받은 후 치료명령을 청구하여야 한다. <개정 2011.8.4>', 9869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16510, '③ 제1항에 따른 치료명령의 청구는 공소가 제기되거나 치료감호가 독립청구된 성폭력범죄사건(이하 "피고사건"이라 한다)의 항소심 변론종결 시까지 하여야 한다.', 9869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16511, '④ 법원은 피고사건의 심리결과 치료명령을 할 필요가 있다고 인정하는 때에는 검사에게 치료명령의 청구를 요구할 수 있다.', 9869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16512, '⑤ 피고사건에 대하여 판결의 확정 없이 공소가 제기되거나 치료감호가 독립청구된 때부터 15년이 지나면 치료명령을 청구할 수 없다.', 9869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16513, '⑥ 제2항에 따른 정신건강의학과 전문의의 진단이나 감정에 필요한 사항은 대통령령으로 정한다. <개정 2011.8.4>', 9869);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16514, '① 검사는 치료명령을 청구하기 위하여 필요하다고 인정하는 때에는 치료명령 피청구자의 주거지 또는 소속 검찰청(지청을 포함한다. 이하 같다) 소재지를 관할하는 보호관찰소(지소를 포함한다. 이하 같다)의 장에게 범죄의 동기, 피해자와의 관계, 심리상태, 재범의 위험성 등 치료명령 피청구자에 관하여 필요한 사항의 조사를 요청할 수 있다.', 9870);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16515, '② 제1항의 요청을 받은 보호관찰소의 장은 조사할 보호관찰관을 지명하여야 한다.', 9870);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16516, '③ 제2항에 따라 지명된 보호관찰관은 검사의 지휘를 받아 지체 없이 필요한 사항을 조사한 후 검사에게 조사보고서를 제출하여야 한다.', 9870);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16517, '① 치료명령 청구사건의 관할은 치료명령 청구사건과 동시에 심리하는 피고사건의 관할에 따른다.', 9871);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16518, '② 치료명령 청구사건의 제1심 재판은 지방법원 합의부(지방법원지원 합의부를 포함한다. 이하 같다)의 관할로 한다.', 9871);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16519, '① 치료명령 청구서에는 다음 각 호의 사항을 적어야 한다.', 9872);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16520, '② 법원은 치료명령 청구를 받으면 지체 없이 치료명령 청구서의 부본을 치료명령 피청구자 또는 그 변호인에게 송달하여야 한다. 이 경우 공소제기 또는 치료감호의 독립청구와 동시에 치료명령 청구가 있는 때에는 제1회 공판기일 5일 전까지, 피고사건 심리 중에 치료명령 청구가 있는 때에는 다음 공판기일 5일 전까지 송달하여야 한다.', 9872);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16521, '① 법원은 치료명령 청구가 이유 있다고 인정하는 때에는 15년의 범위에서 치료기간을 정하여 판결로 치료명령을 선고하여야 한다.', 9873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16522, '② 치료명령을 선고받은 사람(이하 "치료명령을 받은 사람"이라 한다)은 치료기간 동안 「보호관찰 등에 관한 법률」에 따른 보호관찰을 받는다.', 9873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16523, '③ 법원은 다음 각 호의 어느 하나에 해당하는 때에는 판결로 치료명령 청구를 기각하여야 한다.', 9873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16524, '④ 치료명령 청구사건의 판결은 피고사건의 판결과 동시에 선고하여야 한다.', 9873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16525, '⑤ 치료명령 선고의 판결 이유에는 요건으로 되는 사실, 증거의 요지 및 적용 법조를 명시하여야 한다.', 9873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16526, '⑥ 치료명령의 선고는 피고사건의 양형에 유리하게 참작되어서는 아니 된다.', 9873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16527, '⑦ 피고사건의 판결에 대하여 「형사소송법」에 따른 상소 및 상소의 포기ㆍ취하가 있는 때에는 치료명령 청구사건의 판결에 대하여도 상소 및 상소의 포기ㆍ취하가 있는 것으로 본다. 상소권회복 또는 재심의 청구나 비상상고가 있는 때에도 또한 같다.', 9873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16528, '⑧ 검사 또는 치료명령 피청구자 및 「형사소송법」 제340조ㆍ제341조에 규정된 사람은 치료명령에 대하여 독립하여 「형사소송법」에 따른 상소 및 상소의 포기ㆍ취하를 할 수 있다. 상소권회복 또는 재심의 청구나 비상상고의 경우에도 또한 같다.', 9873);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16529, '① 징역형과 함께 치료명령을 받은 사람 및 그 법정대리인은 주거지 또는 현재지를 관할하는 지방법원(지원을 포함한다. 이하 같다)에 치료명령이 집행될 필요가 없을 정도로 개선되어 성폭력범죄를 다시 범할 위험성이 없음을 이유로 치료명령의 집행 면제를 신청할 수 있다. 다만, 징역형과 함께 치료명령을 받은 사람이 치료감호의 집행 중인 경우에는 치료명령의 집행 면제를 신청할 수 없다.', 9874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16530, '② 제1항 본문에 따른 신청은 치료명령의 원인이 된 범죄에 대한 징역형의 집행이 종료되기 전 12개월부터 9개월까지의 기간에 하여야 한다. 다만, 치료명령의 원인이 된 범죄가 아닌 다른 범죄를 범하여 징역형의 집행이 종료되지 아니한 경우에는 그 징역형의 집행이 종료되기 전 12개월부터 9개월까지의 기간에 하여야 한다.', 9874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16531, '③ 징역형과 함께 치료명령을 받은 사람은 제1항 본문에 따른 치료명령의 집행 면제를 신청할 때에는 신청서에 치료명령의 집행 면제의 심사에 참고가 될 자료를 첨부하여 제출하여야 한다.', 9874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16532, '④ 법원은 제1항 본문의 신청을 받은 경우 징역형의 집행이 종료되기 3개월 전까지 치료명령의 집행 면제 여부를 결정하여야 한다.', 9874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16533, '⑤ 법원은 제4항에 따른 결정을 하기 위하여 필요한 경우에는 그 법원의 소재지를 관할하는 보호관찰소의 장에게 치료명령을 받은 사람의 교정성적, 심리상태, 재범의 위험성 등 필요한 사항의 조사를 요청할 수 있다. 이 경우 조사에 관하여는 제5조를 준용하며, "검사"는 "법원"으로 본다.', 9874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16534, '⑥ 법원은 제4항에 따른 결정을 하기 위하여 필요한 때에는 치료명령을 받은 사람에 대하여 정신건강의학과 전문의의 진단이나 감정을 받게 할 수 있다.', 9874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16535, '⑦ 제1항에 따른 치료명령 집행 면제 신청사건의 관할에 관하여는 제6조제2항을 준용한다.', 9874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16536, '⑧ 징역형과 함께 치료명령을 받은 사람 및 그 법정대리인은 제4항의 결정에 대하여 항고(抗告)를 할 수 있다.', 9874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16537, '⑨ 제8항의 항고에 관하여는 제22조제5항부터 제11항까지를 준용한다. 이 경우 "성폭력 수형자"는 "치료명령을 받은 사람"으로 본다.', 9874);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16538, '① 「치료감호 등에 관한 법률」 제37조에 따른 치료감호심의위원회(이하 "치료감호심의위원회"라 한다)는 같은 법 제16조제1항에 따른 피치료감호자 중 치료명령을 받은 사람(피치료감호자 중 징역형과 함께 치료명령을 받은 사람의 경우 형기가 남아 있지 아니하거나 9개월 미만의 기간이 남아 있는 사람에 한정한다)에 대하여 같은 법 제22조 또는 제23조에 따른 치료감호의 종료ㆍ가종료 또는 치료위탁 결정을 하는 경우에 치료명령의 집행이 필요하지 아니하다고 인정되면 치료명령의 집행을 면제하는 결정을 하여야 한다.', 9875);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16539, '② 치료감호심의위원회는 제1항의 결정을 하기 위하여 필요한 경우에는 치료명령을 받은 사람에 대하여 정신건강의학과 전문의의 진단이나 감정을 받게 할 수 있다.', 9875);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16540, '① 치료명령을 받은 사람은 치료기간 동안 「보호관찰 등에 관한 법률」 제32조제2항 각 호(제4호는 제외한다)의 준수사항과 다음 각 호의 준수사항을 이행하여야 한다.', 9878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16541, '② 법원은 제8조제1항에 따라 치료명령을 선고하는 경우 「보호관찰 등에 관한 법률」 제32조제3항 각 호의 준수사항을 부과할 수 있다.', 9878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16542, '③ 법원은 치료명령을 선고할 때에 치료명령을 받은 사람에게 치료명령의 취지를 설명하고 준수사항을 적은 서면을 교부하여야 한다.', 9878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16543, '④ 제1항제3호의 인지행동 치료 등 심리치료 프로그램에 관하여 필요한 사항은 대통령령으로 정한다.', 9878);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16544, '① 법원은 제8조제1항에 따라 치료명령을 선고한 때에는 그 판결이 확정된 날부터 3일 이내에 치료명령을 받은 사람의 주거지를 관할하는 보호관찰소의 장에게 판결문의 등본과 준수사항을 적은 서면을 송부하여야 한다.', 9879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16545, '② 교도소, 소년교도소, 구치소 및 치료감호시설의 장은 치료명령을 받은 사람이 석방되기 3개월 전까지 치료명령을 받은 사람의 주거지를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다.', 9879);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16546, '① 치료명령은 검사의 지휘를 받아 보호관찰관이 집행한다.', 9881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16547, '② 제1항에 따른 지휘는 판결문 등본을 첨부한 서면으로 한다.', 9881);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16548, '① 치료명령은 「의료법」에 따른 의사의 진단과 처방에 의한 약물 투여, 「정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률」에 따른 정신보건전문요원 등 전문가에 의한 인지행동 치료 등 심리치료 프로그램의 실시 등의 방법으로 집행한다. <개정 2016.5.29>', 9882);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16549, '② 보호관찰관은 치료명령을 받은 사람에게 치료명령을 집행하기 전에 약물치료의 효과, 부작용 및 약물치료의 방법ㆍ주기ㆍ절차 등에 관하여 충분히 설명하여야 한다.', 9882);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16550, '③ 치료명령을 받은 사람이 형의 집행이 종료되거나 면제ㆍ가석방 또는 치료감호의 집행이 종료ㆍ가종료 또는 치료위탁으로 석방되는 경우 보호관찰관은 석방되기 전 2개월 이내에 치료명령을 받은 사람에게 치료명령을 집행하여야 한다.', 9882);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16551, '④ 다음 각 호의 어느 하나에 해당하는 때에는 치료명령의 집행이 정지된다.', 9882);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16552, '⑤ 제4항에 따라 집행이 정지된 치료명령의 잔여기간에 대하여는 다음 각 호의 구분에 따라 집행한다.', 9882);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16553, '⑥ 그 밖에 치료명령의 집행 및 정지에 관하여 필요한 사항은 대통령령으로 정한다.', 9882);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16554, '① 치료명령을 받은 사람은 치료기간 중 상쇄약물의 투약 등의 방법으로 치료의 효과를 해하여서는 아니 된다.', 9883);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16555, '② 치료명령을 받은 사람은 형의 집행이 종료되거나 면제ㆍ가석방 또는 치료감호의 집행이 종료ㆍ가종료 또는 치료위탁되는 날부터 10일 이내에 주거지를 관할하는 보호관찰소에 출석하여 서면으로 신고하여야 한다.', 9883);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16556, '③ 치료명령을 받은 사람은 주거 이전 또는 7일 이상의 국내여행을 하거나 출국할 때에는 미리 보호관찰관의 허가를 받아야 한다.', 9883);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16557, '① 치료 경과 등에 비추어 치료명령을 받은 사람에 대한 약물치료를 계속 하여야 할 상당한 이유가 있거나 다음 각 호의 어느 하나에 해당하는 사유가 있으면 법원은 보호관찰소의 장의 신청에 따른 검사의 청구로 치료기간을 결정으로 연장할 수 있다. 다만, 종전의 치료기간을 합산하여 15년을 초과할 수 없다. <개정 2017.12.19>', 9884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16558, '② 법원은 치료명령을 받은 사람이 제1항 각 호의 어느 하나에 해당하는 경우에는 보호관찰소의 장의 신청에 따른 검사의 청구로 제10조제2항의 준수사항을 추가 또는 변경하는 결정을 할 수 있다.', 9884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16559, '③ 제1항 각 호에 규정된 사항 외의 사정변경이 있는 경우에도 법원은 상당한 이유가 있다고 인정되면 보호관찰소의 장의 신청에 따른 검사의 청구로 제10조제2항의 준수사항을 추가, 변경 또는 삭제하는 결정을 할 수 있다.', 9884);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16560, '① 보호관찰소의 장 또는 치료명령을 받은 사람 및 그 법정대리인은 해당 보호관찰소를 관할하는 「보호관찰 등에 관한 법률」 제5조에 따른 보호관찰 심사위원회(이하 "심사위원회"라 한다)에 치료명령의 임시해제를 신청할 수 있다. <개정 2020.2.4>', 9885);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16561, '② 제1항의 신청은 치료명령의 집행이 개시된 날부터 6개월이 지난 후에 하여야 한다. 신청이 기각된 경우에는 기각된 날부터 6개월이 지난 후에 다시 신청할 수 있다.', 9885);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16562, '③ 임시해제의 신청을 할 때에는 신청서에 임시해제의 심사에 참고가 될 자료를 첨부하여 제출하여야 한다. <개정 2020.2.4>', 9885);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16563, '① 심사위원회는 임시해제를 심사할 때에는 치료명령을 받은 사람의 인격, 생활태도, 치료명령 이행상황 및 재범의 위험성에 대한 전문가의 의견 등을 고려하여야 한다. <개정 2020.2.4>', 9886);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16564, '② 심사위원회는 임시해제의 심사를 위하여 필요한 때에는 보호관찰소의 장으로 하여금 필요한 사항을 조사하게 하거나 치료명령을 받은 사람이나 그 밖의 관계인을 직접 소환ㆍ심문 또는 조사할 수 있다. <개정 2020.2.4>', 9886);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16565, '③ 제2항의 요구를 받은 보호관찰소의 장은 필요한 사항을 조사하여 심사위원회에 통보하여야 한다.', 9886);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16566, '④ 심사위원회는 치료명령을 받은 사람이 치료명령이 계속 집행될 필요가 없을 정도로 개선되어 죄를 다시 범할 위험성이 없다고 인정하는 때에는 치료명령의 임시해제를 결정할 수 있다. <개정 2020.2.4>', 9886);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16567, '⑤ 심사위원회는 치료명령의 임시해제를 하지 아니하기로 결정한 때에는 결정서에 그 이유를 명시하여야 한다. <개정 2020.2.4>', 9886);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16568, '⑥ 제4항에 따라 치료명령이 임시해제된 경우에는 제10조제1항 각 호 및 같은 조 제2항에 따른 준수사항이 임시해제된 것으로 본다. <개정 2020.2.4>', 9886);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16569, '① 보호관찰소의 장은 치료명령이 임시해제된 사람이 성폭력범죄를 저지르거나 주거 이전 상황 등의 보고에 불응하는 등 재범의 위험성이 있다고 판단되는 때에는 심사위원회에 임시해제의 취소를 신청할 수 있다. 이 경우 심사위원회는 임시해제된 사람의 재범의 위험성이 현저하다고 인정될 때에는 임시해제를 취소하여야 한다. <개정 2020.2.4>', 9887);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16570, '② 임시해제가 취소된 사람은 잔여 치료기간 동안 약물치료를 받아야 한다. 이 경우 임시해제기간은 치료기간에 산입하지 아니한다. <개정 2020.2.4>', 9887);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16571, null, 9888);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16572, '① 치료명령을 받은 사람은 그 판결이 확정된 후 집행을 받지 아니하고 함께 선고된 피고사건의 형의 시효 또는 치료감호의 시효가 완성되면 그 집행이 면제된다.', 9889);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16573, '② 치료명령의 시효는 치료명령을 받은 사람을 체포함으로써 중단된다.', 9889);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16574, '① 검사는 사람에 대하여 성폭력범죄를 저질러 징역형 이상의 형이 확정되었으나 제8조제1항에 따른 치료명령이 선고되지 아니한 수형자(이하 "성폭력 수형자"라 한다) 중 성도착증 환자로서 성폭력범죄를 다시 범할 위험성이 있다고 인정되고 약물치료를 받는 것을 동의하는 사람에 대하여 그의 주거지 또는 현재지를 관할하는 지방법원에 치료명령을 청구할 수 있다. <개정 2012.12.18, 2017.12.19>', 9890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16575, '② 제1항의 수형자에 대한 치료명령의 절차는 다음 각 호에 따른다. <개정 2011.8.4>', 9890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16576, '③ 제2항제6호의 결정에 따른 치료기간은 15년을 초과할 수 없다.', 9890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16577, '④ 검사는 제2항제5호에 따른 정신건강의학과 전문의의 진단이나 감정을 위하여 필요한 경우 수용시설의 장에게 성폭력 수형자를 치료감호시설 등에 이송하도록 할 수 있다. <개정 2011.8.4>', 9890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16578, '⑤ 제2항제6호의 결정이 다음 각 호의 어느 하나에 해당하면 결정을 고지받은 날부터 7일 이내에 검사, 성폭력 수형자 본인 또는 그 법정대리인은 고등법원에 항고할 수 있다.', 9890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16579, '⑥ 항고를 할 때에는 항고장을 원심법원에 제출하여야 하며, 항고장을 제출받은 법원은 3일 이내에 의견서를 첨부하여 기록을 항고법원에 송부하여야 한다.', 9890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16580, '⑦ 항고법원은 항고 절차가 법률에 위반되거나 항고가 이유 없다고 인정한 경우에는 결정으로써 항고를 기각하여야 한다.', 9890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16581, '⑧ 항고법원은 항고가 이유 있다고 인정한 경우에는 원결정을 파기하고 스스로 결정을 하거나 다른 관할 법원에 이송하여야 한다.', 9890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16582, '⑨ 항고법원의 결정에 대하여는 그 결정이 법령에 위반된 때에만 대법원에 재항고를 할 수 있다.', 9890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16583, '⑩ 재항고의 제기기간은 항고기각 결정을 고지받은 날부터 7일로 한다.', 9890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16584, '⑪ 항고와 재항고는 결정의 집행을 정지하는 효력이 없다.', 9890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16585, '⑫ 수용시설의 장은 성폭력 수형자가 석방되기 5일 전까지 그의 주소를 관할하는 보호관찰소의 장에게 그 사실을 통보하여야 한다.', 9890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16586, '⑬ 제2항제6호에 따라 고지된 치료명령은 성폭력 수형자에게 선고된 제1항의 징역형 이상의 형이 사면되어 그 선고의 효력을 상실하게 된 때에 그 집행이 종료된다.', 9890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16587, '⑭ 치료명령을 받은 사람은 치료명령 결정이 확정된 후 집행을 받지 아니하고 10년이 경과하면 시효가 완성되어 집행이 면제된다.', 9890);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16588, '① 수용시설의 장은 제22조제2항제6호의 결정이 확정된 성폭력 수형자에 대하여 법무부령으로 정하는 바에 따라 「형의 집행 및 수용자의 처우에 관한 법률」 제119조의 가석방심사위원회에 가석방 적격심사를 신청하여야 한다.', 9891);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16589, '② 가석방심사위원회는 성폭력 수형자의 가석방 적격심사를 할 때에는 치료명령이 결정된 사실을 고려하여야 한다.', 9891);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16590, '① 제22조제2항제6호의 치료명령의 결정을 받은   사람은 치료기간 동안 치료비용을 부담하여야 한다. 다만, 치료비용을 부담할 경제력이 없는 사람의 경우에는 국가가 비용을 부담할 수 있다.', 9892);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16591, '② 비용부담에 관하여 필요한 사항은 대통령령으로 정한다.', 9892);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16592, '① 「치료감호 등에 관한 법률」 제37조에 따른 치료감호심의위원회(이하 "치료감호심의위원회"라 한다)는 성폭력범죄자 중 성도착증 환자로서 치료감호의 집행 중 가종료 또는 치료위탁되는 피치료감호자나 보호감호의 집행 중 가출소되는 피보호감호자(이하 "가종료자 등"이라 한다)에 대하여 보호관찰 기간의 범위에서 치료명령을 부과할 수 있다. <개정 2017.12.19>', 9893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16593, '② 치료감호심의위원회는 제1항에 따라 치료명령을 부과하는 결정을 할 경우에는 결정일 전 6개월 이내에 실시한 정신건강의학과 전문의의 진단 또는 감정 결과를 반드시 참작하여야 한다. <개정 2011.8.4>', 9893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16594, '③ 치료감호심의위원회는 제1항에 따라 치료명령을 부과하는 결정을 한 경우에는 즉시 가종료자 등의 주거지를 관할하는 보호관찰소의 장에게 통보하여야 한다.', 9893);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16595, null, 9896);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16596, '① 이 장에 따른 치료명령에 관하여는 제10조제1항ㆍ제4항, 제14조제1항ㆍ제2항ㆍ제4항제1호 및 제2호ㆍ제5항제1호 및 제2호, 제15조, 제17조부터 제19조까지 및 제20조제3호를 준용한다.', 9897);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16597, '② 제22조에 따른 치료명령에 관하여는 제1항의 규정 외에 제6조제2항, 제7조, 제8조제2항ㆍ제5항, 제9조, 제10조제2항, 제11조제1항, 제12조, 제13조, 제14조제3항ㆍ제4항제3호ㆍ제5항제3호, 제16조, 제20조제1호 및 제21조제2항을 준용한다.', 9897);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16598, null, 9899);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16599, '① 이 법에 따른 약물치료를 받아야 하는 사람이 도주하거나 정당한 사유 없이 제15조제1항의 의무를 위반한 때에는 7년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.', 9903);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16600, '② 이 법에 따른 약물치료를 받아야 하는 사람이 정당한 사유 없이 제10조제1항 각 호의 준수사항을 위반한 때에는 3년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.', 9903);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16601, '③ 이 법에 따른 약물치료를 받아야 하는 사람이 정당한 사유 없이 제10조제2항에 따른 준수사항을 위반한 때에는 1천만원 이하의 벌금에 처한다.', 9903);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16602, '① 「성폭력범죄자의 성충동 약물치료에 관한 법률」(이하 "법"이라 한다) 제4조제2항 및 제6항에 따라 검사는 같은 조 제1항에 따른 성충동 약물치료명령(이하 "치료명령"이라 한다)을 청구하기 전에 다음 각 호의 어느 하나에 해당하는 시설 또는 기관의 정신건강의학과 전문의에게 치료명령 청구대상자(이하 "치료명령피청구자"라 한다)에 대한 진단이나 감정을 의뢰하여야 한다. <개정 2011.11.23, 2016.11.29, 2017.5.29>', 9905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16603, '② 제1항에 따라 치료명령피청구자를 진단하거나 감정하는 정신건강의학과 전문의는 치료명령피청구자를 직접 면접하여 진단이나 감정을 실시하여야 하며, 진단이나 감정에 필요하면 심리적ㆍ생리적 평가도구를 사용할 수 있다. <개정 2011.11.23>', 9905);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16604, '① 검사는 법 제5조제1항에 따라 보호관찰소(지소를 포함한다. 이하 같다)의 장에게 조사를 요청할 때에는 치료명령피청구자의 인적사항 및 범죄사실의 요지를 통보하여야 한다. 이 경우 법무부령으로 정하는 참고자료를 함께 보낼 수 있다.', 9906);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16605, '② 보호관찰소의 장은 법 제5조제1항에 따른 조사를 위하여 필요하면 교도소ㆍ소년교도소ㆍ구치소ㆍ군교도소(이하 "수용시설"이라 한다)의 장, 경찰서장, 치료감호시설의 장에게 필요한 협조를 요청할 수 있다. 이 경우 요청을 받은 기관의 장은 특별한 사유가 없으면 협조하여야 한다.', 9906);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16606, '① 법 제7조제1항제1호에서 "치료명령 피청구자를 특정할 수 있는 사항"이란 다음 각 호의 사항을 말한다.', 9907);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16607, '② 법 제7조제1항제4호에서 "대통령령으로 정하는 사항"이란 다음 각 호의 사항을 말한다.', 9907);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16608, '① 법 제8조의2제1항부터 제3항까지의 규정에 따라 치료명령의 집행 면제를 신청하려는 사람은 법무부령으로 정하는 신청서를 주거지 또는 현재지를 관할하는 지방법원(지원을 포함한다)에 제출하여야 한다.', 9908);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16609, '② 법원은 보호관찰소의 장에게 법 제8조의2제5항에 따라 필요한 사항의 조사를 요청하는 경우에는 치료명령을 받은 사람의 인적사항 및 범죄사실의 요지를 통보하여야 한다. 이 경우 법원은 필요하다고 인정하는 경우에는 참고자료를 송부할 수 있다.', 9908);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16610, '① 법 제10조제1항제3호에 따른 인지행동 치료 등 심리치료 프로그램(이하 "심리치료프로그램"이라 한다)은 다음 각 호의 내용을 포함하여야 한다.', 9909);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16611, '② 심리치료프로그램은 성충동 약물치료(이하 "약물치료"라 한다) 기간 동안 월 1회 이상 실시되어야 한다.', 9909);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16612, '③ 법무부장관은 심리치료프로그램의 개발과 전문 집행 인력의 양성을 위하여 노력하여야 한다.', 9909);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16613, '① 검사는 치료명령의 판결이 확정된 경우에는 지체 없이 치료명령을 선고받은 사람(이하 "치료명령을 받은 사람"이라 한다)의 주거지를 관할하는 보호관찰소의 장에게 법 제13조제2항에 따라 지휘 서면을 보내야 한다.', 9910);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16614, '② 제1항에 따른 지휘 서면에는 법 제4조제2항에 따른 정신건강의학과 전문의의 감정서를 첨부하여야 한다. <개정 2011.11.23>', 9910);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16615, '① 법 제13조제1항에 따라 치료명령을 집행하는 보호관찰관은 치료명령을 집행하기 전에 다음 각 호의 서류 모두를 확인하여야 한다. <개정 2011.11.23, 2017.12.29>', 9911);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16616, '② 보호관찰관은 치료명령을 집행하기 전에 치료명령을 받은 사람에게 다음 각 호의 사항 모두를 알려 주어야 한다.', 9911);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16617, '③ 보호관찰관은 약물 투여의 방법으로 치료명령을 집행할 때에는 치료기관 의사의 진단과 처방에 따라 약물을 투여하여야 하며, 약물 투여와 함께 호르몬 수치 검사를 실시하여야 한다.', 9911);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16618, '① 법 제14조제1항에 따라 치료명령을 받은 사람에게 투여할 약물은 다음 각 호의 약물 중에서 법무부장관이 정하여 고시하는 약물로 한다.', 9912);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16619, '② 법무부장관은 제1항에 따라 약물을 지정ㆍ고시할 때에는 반드시 정신건강의학과 전문의, 비뇨의학과 전문의 등 관계 전문가의 의견을 들어야 한다. <개정 2011.11.23, 2017.11.21>', 9912);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16620, '① 법 제14조제1항 및 제6항에 따라 보호관찰관은 다음 각 호의 시설 또는 기관(이하 "치료기관"이라 한다)으로 하여금 약물치료를 실시하게 할 수 있다. <개정 2017.5.29>', 9913);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16621, '② 제1항에 따라 약물치료를 실시한 치료기관에 대해서는 예산의 범위에서 치료비용의 전부를 지급하여야 한다.', 9913);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16622, '① 치료명령을 받은 사람을 수용하고 있는 수용시설의 장은 치료명령을 받은 사람이 형의 집행이 종료되거나 면제ㆍ가석방 등의 사유로 석방되기 3개월 전부터 2개월 전까지 사이에 「형의 집행 및 수용자의 처우에 관한 법률」 제37조제2항에 따라 치료명령을 받은 사람을 치료감호시설로 이송하여야 한다.', 9914);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16623, '② 치료감호시설의 장은 제1항에 따라 치료명령을 받은 사람을 이송 받은 경우에는 지체 없이 그 사실을 그 사람의 주거지를 관할하는 보호관찰소의 장에게 통보하여야 한다.', 9914);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16624, '③ 치료감호시설의 장은 치료명령을 받은 사람이 형 또는 치료감호의 집행이 종료되거나 면제ㆍ가석방, 가종료 등의 사유로 석방되기 5일 전까지 석방 예정 사실을 그 사람의 주거지를 관할하는 보호관찰소의 장에게 통보하여야 한다.', 9914);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16625, '① 보호관찰관은 약물 투여의 방법으로 치료명령을 집행하는 경우에는 치료기관의 의사로 하여금 부작용에 대한 검사 및 치료도 함께 실시하게 하여야 한다. 이 경우 치료기관에서 부작용에 대한 검사 및 치료를 실시하기 어려운 때에는 치료기관의 장으로 하여금 「의료법」에 따른 의료기관(이하 "의료기관"이라 한다)과 연계하여 부작용에 대한 검사 및 치료를 실시하게 할 수 있다.', 9915);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16626, '② 보호관찰관은 제1항에 따른 검사 결과 치료명령을 받은 사람의 신체에 회복하기 어려운 손상이 발생할 수 있다는 의사의 소견이 있거나 그 밖에 약물 투여에 따른 부작용이 크다고 인정되는 경우에는 약물 투여를 일시 중단할 수 있다.', 9915);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16627, '③ 제2항에 따라 약물 투여를 일시 중단한 경우 보호관찰관이 소속된 보호관찰소의 장은 즉시 「보호관찰 등에 관한 법률」 제5조에 따른 보호관찰 심사위원회(이하 "심사위원회"라 한다)에 약물 투여 일시 중단의 승인을 서면으로 신청하여야 한다.', 9915);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16628, '④ 심사위원회는 제3항의 신청을 받은 때에는 지체 없이 약물 투여 일시 중단의 승인 여부를 결정하여야 한다. 이 경우 심사위원회는 의료기관에 치료명령을 받은 사람에 대한 약물치료 부작용 관련 진단을 의뢰할 수 있다.', 9915);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16629, '⑤ 보호관찰관은 제4항에 따른 약물 투여 일시 중단의 승인일부터 1개월마다 치료명령을 받은 사람의 부작용 치료 내용, 신체상태의 변화 및 약물 투여 적합 여부 등에 대한 의사의 진단과 처방 결과를 심사위원회에 보고하여야 한다.', 9915);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16630, '⑥ 심사위원회는 제5항에 따른 보호관찰관의 보고에 따라 약물 투여 재개 여부를 심사ㆍ결정하여야 한다.', 9915);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16631, '⑦ 심사위원회가 제3항에 따른 신청을 기각하거나 제6항에 따라 약물 투여 재개를 결정하였을 때에는 보호관찰관은 지체 없이 치료명령을 다시 집행하여야 한다.', 9915);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16632, '① 법 제14조제4항에 따라 집행이 정지된 치료명령의 잔여기간은 다음 각 호의 구분에 따라 집행한다.', 9916);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16633, '② 제1항제2호의 경우에 치료명령을 받은 사람은 석방된 날부터 10일 이내에 주거지를 관할하는 보호관찰소에 출석하여 신고하고, 보호관찰관의 치료명령 집행 지시에 따라야 한다.', 9916);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16634, '③ 제1항에 따른 치료명령의 집행기간은 다시 치료 약물을 투여한 날부터 진행한다.', 9916);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16635, '④ 수용시설 또는 치료감호시설의 장은 법 제14조제5항에 따른 치료명령의 잔여기간 집행 사유가 발생하였을 때에는 치료명령의 집행이 정지된 사람이 석방되기 5일 전까지 석방 예정 사실을 그 사람의 주거지를 관할하는 보호관찰소의 장에게 통보하여야 한다.', 9916);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16636, '① 보호관찰관은 치료명령을 받은 사람이 법 제15조제1항에 따른 의무를 준수하는지 확인할 필요가 있으면 호르몬 수치 검사 또는 상쇄약물 투약 여부 검사를 실시할 수 있다.', 9917);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16637, '② 치료명령을 받은 사람은 보호관찰관이 제1항에 따른 검사를 위하여 소변 등 시료(試料)의 제출을 지시할 때에는 이에 따라야 한다.', 9917);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16638, '③ 보호관찰소의 장은 치료명령을 받은 사람이 제출한 소변 등의 시료를 대검찰청 또는 국립과학수사연구원에 송부하여 제1항에 따른 검사를 의뢰하여야 한다. <개정 2015.12.30>', 9917);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16639, '① 보호관찰관은 법 제15조제3항에 따라 주거 이전 등의 허가 신청을 받은 때에는 그 신청을 받은 날부터 7일 이내에 다음 각 호의 사항을 종합적으로 고려하여 허가 여부를 결정하여야 한다.', 9918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16640, '② 법 제15조제3항에 따라 치료명령을 받은 사람이 주거 이전 허가를 받아 다른 보호관찰소의 관할구역으로 주거를 이전한 경우에는 3일 이내에 새로운 주거지를 관할하는 보호관찰소에 출석하여 주거이전의 신고를 하여야 한다.', 9918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16641, '③ 보호관찰소의 장은 소속 보호관찰관이 제1항에 따라 치료명령을 받은 사람의 출국을 허가한 경우에는 출입국 사무를 관장하는 기관의 장에게 치료명령을 받은 사람의 출입국 사실을 통보하여 줄 것을 요청할 수 있다.', 9918);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16642, '① 보호관찰소의 장은 법 제16조제1항 또는 제2항에 따라 치료기간의 연장 또는 준수사항의 추가ㆍ변경을 신청하는 경우에는 다음 각 호의 사항을 적은 서면으로 하여야 한다.', 9919);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16643, '② 보호관찰소의 장은 제1항에 따른 신청을 할 때에는 신청 사유를 소명할 수 있는 자료를 함께 제출하여야 한다.', 9919);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16644, '③ 법원은 법 제16조에 따른 청구의 심리를 위하여 필요하면 담당 보호관찰관을 출석시켜 의견을 들을 수 있고, 치료명령을 받은 사람을 소환하여 심문하거나 필요한 사항을 확인할 수 있다.', 9919);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16645, '① 법 제17조제1항에 따른 치료명령의 가해제 신청은 심사위원회에 서면으로 하여야 한다.', 9920);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16646, '② 심사위원회는 치료명령을 받은 사람 또는 그 법정대리인이 치료명령의 가해제를 신청한 경우에는 지체 없이 그 사실을 보호관찰소의 장에게 통보하여야 한다.', 9920);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16647, '① 심사위원회는 법 제18조제1항에 따라 치료명령의 가해제를 심사할 때에는 치료를 실시한 정신건강의학과 전문의와 보호관찰관의 의견을 들어야 하며, 필요하면 그 밖의 전문가의 의견을 들을 수 있다. <개정 2011.11.23>', 9921);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16648, '② 심사위원회는 법 제18조제4항 및 제5항에 따른 결정을 한 때에는 지체 없이 그 결정서 등본을 관할 보호관찰소의 장과 신청인에게 송달하여야 한다.', 9921);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16649, '③ 제1항에 따라 심사위원회에 의견 또는 자료를 제출한 정신건강의학과 전문의, 그 밖의 전문가 등에게는 예산의 범위에서 수당 또는 비용을 지급할 수 있다. <개정 2011.11.23>', 9921);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16650, '① 법 제19조제1항에 따른 가해제 취소 신청은 심사위원회에 서면으로 하여야 한다.', 9922);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16651, '② 심사위원회는 법 제19조제1항에 따라 치료명령의 가해제 취소 결정을 한 때에는 지체 없이 그 사실을 관할 보호관찰소의 장과 가해제가 취소된 사람에게 통보하여야 한다.', 9922);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16652, '③ 가해제가 취소된 경우에 치료명령의 집행기간은 가해제 취소 후 최초로 성호르몬 조절약물을 투여한 날부터 진행한다.', 9922);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16653, null, 9924);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16654, '① 검사는 법 제22조제2항제5호에 따라 약물치료 동의 여부를 확인할 때에는 약물치료에 관한 사항을 서면으로 제시하여 설명하고, 약물치료에 동의한 경우에는 이를 서면으로 확인하여야 한다.', 9926);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16655, '② 법 제22조제2항제5호에 따른 정신건강의학과 전문의의 진단이나 감정 및 치료명령의 청구에 관하여는 제2조 및 제4조를 각각 준용한다. <개정 2011.11.23>', 9926);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16656, '① 검사는 법 제22조제2항제6호에 따라 치료명령이 결정된 경우에는 지체 없이 그 사실을 성폭력수형자를 수용하고 있는 수용시설의 장에게 통보하여야 한다.', 9928);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16657, '② 법 제22조제2항제6호에 따라 치료명령이 결정된 경우에 검사의 집행지휘에 관하여는 제6조를 준용한다.', 9928);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16658, '① 보호관찰관은 법 제22조제2항제6호에 따라 치료명령의 결정을 받은 사람에게 치료행위마다 금액을 특정하여 서면으로 치료비용의 납부를 명하여야 한다.', 9930);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16659, '② 치료명령을 받은 사람은 제1항의 서면을 받은 날부터 30일 이내에 치료비용을 내야 한다.', 9930);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16660, '③ 치료명령을 받은 사람이 치료비용을 부담할 경제력이 없는 경우에는 제1항에 따라 치료비용 납부를 명하는 서면을 받을 때마다 다음 각 호의 서류를 보호관찰관에게 제출하여 치료비용 국가 부담 결정을 받아야 한다.', 9930);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16661, '④ 제3항에 따른 신청을 받은 보호관찰관은 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 다음 각 호의 행정정보를 확인하여야 한다. 다만, 신청인이 확인에 동의하지 아니하는 경우에는 그 서류를 첨부하게 하여야 한다.', 9930);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16662, '⑤ 보호관찰관은 제3항에 따른 결정을 위하여 필요한 경우에는 치료명령을 받은 사람에게 출석 또는 자료의 제출을 요구하거나, 치료명령을 받은 사람의 동의를 받아 공공기관ㆍ민간단체 등에 치료비용 부담 능력 확인에 필요한 자료의 제출을 요구할 수 있다.', 9930);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16663, '⑥ 보호관찰관은 제5항에 따라 공공기관ㆍ민간단체 등에 치료비용 부담 능력 확인에 필요한 자료의 제출을 요구할 때에는 다음 각 호의 사항이 적힌 치료명령을 받은 사람의 동의서를 첨부하여야 한다.', 9930);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16664, '⑦ 보호관찰관은 제3항에 따라 국가 부담 결정을 하였을 때에는 치료기관에 대하여 치료행위마다 예산의 범위에서 비용의 전부를 지급하여야 한다.', 9930);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16665, '① 「치료감호 등에 관한 법률」 제37조에 따른 치료감호심의위원회(이하 "치료감호심의위원회"라 한다)는 법 제25조제1항에 따른 가종료자 등(이하 "가종료자등"이라 한다)에 대하여 치료명령을 부과할 필요가 있다고 인정되는 경우에는 치료감호시설의 정신건강의학과 전문의에게 진단 및 감정을 의뢰하여야 한다. <개정 2011.11.23, 2016.11.29>', 9931);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16666, '② 치료감호심의위원회는 제1항에 따른 치료감호시설의 정신건강의학과 전문의의 진단 및 감정만으로 성도착증 여부를 판단하기 어려울 때에는 다른 정신건강의학과 전문의에게 다시 진단 및 감정을 의뢰할 수 있다. <개정 2011.11.23>', 9931);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16667, '③ 치료감호심의위원회가 피보호감호자에 대하여 제1항에 따른 진단 및 감정을 의뢰한 경우 보호감호시설의 장은 「형의 집행 및 수용자의 처우에 관한 법률」 제37조제2항에 따라 피보호감호자를 치료감호시설로 이송하여야 한다.', 9931);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16668, '① 치료감호심의위원회는 법 제25조제1항에 따라 치료명령을 부과한 경우 가종료자등에게는 그 결정서를, 치료감호시설 또는 보호감호시설(이하 "감호시설"이라 한다)의 장에게는 결정서 등본을 각각 송달하여야 한다.', 9932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16669, '② 제1항에 따라 결정서 등본을 송달받은 감호시설의 장은 치료명령을 받게 될 피치료감호자 또는 피보호감호자에게 약물치료의 내용ㆍ방법ㆍ절차ㆍ효과ㆍ부작용 등에 관하여 알려 주어야 한다.', 9932);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16670, '① 법 제4장(제22조부터 제29조까지)에 따른 치료명령에 관하여는 제7조부터 제14조까지 및 제16조부터 제18조까지의 규정을 준용한다.', 9933);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16671, '② 법 제22조에 따른 치료명령에 관하여는 제1항에서 준용하는 규정 외에 제4조, 제6조 및 제15조를 준용한다.', 9933);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16672, '① 검사는 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 「개인정보 보호법」 제23조에 따른 건강에 관한 정보, 같은 법 시행령 제18조제2호에 따른 범죄경력자료에 해당하는 정보, 같은 영 제19조제1호 또는 제4호에 따른 주민등록번호 또는 외국인등록번호가 포함된 자료를 처리할 수 있다.', 9934);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16673, '② 교도소, 소년교도소, 구치소 또는 치료감호시설의 장은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다.', 9934);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16674, '③ 심사위원회는 법 제18조제4항ㆍ제5항 또는 제19조제1항에 따른 치료명령 가해제 또는 가해제 취소 결정에 관한 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다.', 9934);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16675, '④ 치료감호심의위원회는 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <개정 2017.12.29>', 9934);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16676, '⑤ 보호관찰소의 장 또는 보호관찰관은 다음 각 호의 사무를 수행하기 위하여 불가피한 경우 제1항에 따른 개인정보가 포함된 자료를 처리할 수 있다. <개정 2017.12.29>', 9934);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16677, null, 9936);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16678, '① 법 제5조제1항 및 제22조제2항제3호에 따른 조사 요청은 별지 제2호서식에 따른다.', 9937);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16679, '② 「성폭력범죄자의 성충동 약물치료에 관한 법률 시행령」(이하 "영"이라 한다) 제3조제1항 후단에서 "법무부령으로 정하는 참고자료"란 다음 각 호의 자료를 말한다.', 9937);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16680, '① 법 제7조제1항 및 제22조제2항제5호 후단에 따른 치료명령 청구서는 별지 제3호서식에 따른다. 다만, 공소제기와 동시에 치료명령을 청구하는 경우에는 별지 제4호서식에 따른 청구서로 할 수 있다.', 9938);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16681, '② 공소를 제기한 후에 치료명령을 청구하는 경우에는 다음 각 호의 사항을 구체적으로 밝혀 치료명령 청구사건의 관할법원에 병합심리(倂合審理)를 신청하여야 한다.', 9938);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16682, '① 지방검찰청 검사장 또는 지청장은 법 제4조 및 제22조에 따라 치료명령을 청구하였을 때에는 지체 없이 법무부장관과 상급 검찰청의 장에게 그 사실을 보고하여야 한다.', 9939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16683, '② 제1항에 따른 치료명령 청구사건의 재판이 확정되었을 때에는 그 법원에 대응하는 검찰청의 장은 지체 없이 법무부장관과 상급 검찰청의 장에게 그 사실을 보고하여야 한다.', 9939);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16684, '① 법 제13조 및 영 제6조에 따른 집행지휘는 별지 제6호서식에 따른다.', 9942);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16685, '② 검사는 치료명령과 병과(倂科)된 형(刑)에 대한 집행지휘서의 비고란에 "치료명령"이라고 붉은색으로 적어야 한다.', 9942);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16686, '① 보호관찰소의 장은 치료명령을 받은 사람별로 보호관찰을 담당하는 보호관찰관을 지명하여야 한다.', 9945);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16687, '② 제1항에 따른 담당 보호관찰관은 치료명령을 받은 사람으로부터 별지 제9호서식의 서약서를 받아 치료기간 동안 준수사항을 이행할 것을 지시하여야 한다.', 9945);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16688, '① 법 제15조제2항에 따른 치료명령을 받은 사람의 신고 및 영 제14조제2항에 따른 주거 이전 신고는 별지 제19호서식에 따른다.', 9955);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16689, '② 법 제15조제3항 및 영 제14조제1항에 따른 주거 이전 등의 허가 신청 및 허가는 각각 별지 제20호서식과 별지 제21호서식에 따른다.', 9955);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16690, '③ 영 제14조제3항에 따른 출입국 사실 통보 요청은 별지 제22호서식에 따른다.', 9955);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16691, '① 법 제16조 및 영 제15조에 따른 치료기간의 연장 또는 준수사항의 추가ㆍ변경 등의 신청 및 청구는 각각 별지 제23호서식과 별지 제24호서식에 따른다.', 9956);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16692, '② 법원이 법 제16조에 따라 치료기간의 연장 또는 준수사항의 추가ㆍ변경 등을 결정한 경우에 검사의 집행지휘는 별지 제25호서식에 따른다. 다만, 법원이 검사의 청구를 기각한 경우에는 검사는 그 결정문 사본을 보호관찰소의 장에게 송부하여야 한다.', 9956);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16693, '① 영 제26조제5항에 따른 치료명령을 받은 사람의 자료 제출 동의는 별지 제32호서식에 따른다.', 9964);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16694, '② 영 제26조제5항에 따른 공공기관 등에 대한 자료 제출 요구는 별지 제33호서식에 따른다. 다만, 다른 법령에서 금융거래정보ㆍ신용정보 등의 자료 제출 요구에 관한 서식을 정하고 있는 경우에는 그에 따를 수 있다.', 9964);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16695, '① 법 제25조제1항 및 영 제28조제1항에 따른 치료명령 결정은 별지 제35호서식에 따른다.', 9966);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16696, '② 법 제25조제3항에 따른 치료명령 결정 통보는 별지 제36호서식에 따른다.', 9966);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16697, '①이 법은 국가의 안전을 위태롭게 하는 반국가활동을 규제함으로써 국가의 안전과 국민의 생존 및 자유를 확보함을 목적으로 한다.', 9968);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16698, '②이 법을 해석적용함에 있어서는 제1항의 목적달성을 위하여 필요한 최소한도에 그쳐야 하며, 이를 확대해석하거나 헌법상 보장된 국민의 기본적 인권을 부당하게 제한하는 일이 있어서는 아니된다. <신설 1991ㆍ5ㆍ31>', 9968);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16699, '①이 법에서 "반국가단체"라 함은 정부를 참칭하거나 국가를 변란할 것을 목적으로 하는 국내외의 결사 또는 집단으로서 지휘통솔체제를 갖춘 단체를 말한다. <개정 1991ㆍ5ㆍ31>', 9969);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16700, '② 삭제 <1991ㆍ5ㆍ31>', 9969);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16701, '①반국가단체를 구성하거나 이에 가입한 자는 다음의 구별에 따라 처벌한다.', 9970);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16702, '②타인에게 반국가단체에 가입할 것을 권유한 자는 2년 이상의 유기징역에 처한다.', 9970);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16703, '③제1항 및 제2항의 미수범은 처벌한다.', 9970);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16704, '④제1항제1호 및 제2호의 죄를 범할 목적으로 예비 또는 음모한 자는 2년 이상의 유기징역에 처한다.', 9970);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16705, '⑤제1항제3호의 죄를 범할 목적으로 예비 또는 음모한 자는 10년 이하의 징역에 처한다. <개정 1991ㆍ5ㆍ31>', 9970);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16706, '①반국가단체의 구성원 또는 그 지령을 받은 자가 그 목적수행을 위한 행위를 한 때에는 다음의 구별에 따라 처벌한다. <개정 1991ㆍ5ㆍ31>', 9971);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16707, '②제1항의 미수범은 처벌한다.', 9971);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16708, '③제1항제1호 내지 제4호의 죄를 범할 목적으로 예비 또는 음모한 자는 2년 이상의 유기징역에 처한다.', 9971);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16709, '④제1항제5호 및 제6호의 죄를 범할 목적으로 예비 또는 음모한 자는 10년 이하의 징역에 처한다.', 9971);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16710, '①반국가단체나 그 구성원 또는 그 지령을 받은 자를 지원할 목적으로 자진하여 제4조제1항 각호에 규정된 행위를 한 자는 제4조제1항의 예에 의하여 처벌한다.', 9972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16711, '②국가의 존립ㆍ안전이나 자유민주적 기본질서를 위태롭게 한다는 정을 알면서 반국가단체의 구성원 또는 그 지령을 받은 자로부터 금품을 수수한 자는 7년 이하의 징역에 처한다. <개정 1991ㆍ5ㆍ31>', 9972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16712, '③제1항 및 제2항의 미수범은 처벌한다.', 9972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16713, '④제1항의 죄를 범할 목적으로 예비 또는 음모한 자는 10년 이하의 징역에 처한다.', 9972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16714, '⑤ 삭제 <1991ㆍ5ㆍ31>', 9972);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16715, '①국가의 존립ㆍ안전이나 자유민주적 기본질서를 위태롭게 한다는 정을 알면서 반국가단체의 지배하에 있는 지역으로부터 잠입하거나 그 지역으로 탈출한 자는 10년 이하의 징역에 처한다. <개정 1991ㆍ5ㆍ31>', 9973);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16716, '②반국가단체나 그 구성원의 지령을 받거나 받기 위하여 또는 그 목적수행을 협의하거나 협의하기 위하여 잠입하거나 탈출한 자는 사형ㆍ무기  또는 5년 이상의 징역에 처한다.', 9973);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16717, '③ 삭제 <1991ㆍ5ㆍ31>', 9973);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16718, '④제1항 및 제2항의 미수범은 처벌한다. <개정 1991ㆍ5ㆍ31>', 9973);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16719, '⑤제1항의 죄를 범할 목적으로 예비 또는 음모한 자는 7년 이하의 징역에 처한다.', 9973);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16720, '⑥제2항의 죄를 범할 목적으로 예비 또는 음모한 자는 2년 이상의 유기징역에 처한다. <개정 1991ㆍ5ㆍ31>', 9973);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16721, '①국가의 존립ㆍ안전이나 자유민주적 기본질서를 위태롭게 한다는 정을 알면서 반국가단체나 그 구성원 또는 그 지령을 받은 자의 활동을 찬양ㆍ고무ㆍ선전 또는 이에 동조하거나 국가변란을 선전ㆍ선동한 자는 7년 이하의 징역에 처한다. <개정 1991ㆍ5ㆍ31>', 9974);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16722, '② 삭제 <1991ㆍ5ㆍ31>', 9974);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16723, '③제1항의 행위를 목적으로 하는 단체를 구성하거나 이에 가입한 자는 1년 이상의 유기징역에 처한다. <개정 1991ㆍ5ㆍ31>', 9974);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16724, '④제3항에 규정된 단체의 구성원으로서 사회질서의 혼란을 조성할 우려가 있는 사항에 관하여 허위사실을 날조하거나 유포한 자는 2년 이상의 유기징역에 처한다. <개정 1991ㆍ5ㆍ31>', 9974);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16725, '⑤제1항ㆍ제3항 또는 제4항의 행위를 할 목적으로 문서ㆍ도화 기타의 표현물을 제작ㆍ수입ㆍ복사ㆍ소지ㆍ운반ㆍ반포ㆍ판매 또는 취득한 자는 그 각항에 정한 형에 처한다. <개정 1991ㆍ5ㆍ31>', 9974);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16726, '⑥제1항 또는 제3항 내지 제5항의 미수범은 처벌한다. <개정 1991ㆍ5ㆍ31>', 9974);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16727, '⑦제3항의 죄를 범할 목적으로 예비 또는 음모한 자는 5년 이하의 징역에 처한다. <개정 1991ㆍ5ㆍ31>', 9974);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16728, '①국가의 존립ㆍ안전이나 자유민주적 기본질서를 위태롭게 한다는 정을 알면서 반국가단체의 구성원 또는 그 지령을 받은 자와 회합ㆍ통신 기타의 방법으로 연락을 한 자는 10년 이하의 징역에 처한다. <개정 1991ㆍ5ㆍ31>', 9975);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16729, '② 삭제 <1991ㆍ5ㆍ31>', 9975);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16730, '③제1항의 미수범은 처벌한다. <개정 1991ㆍ5ㆍ31>', 9975);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16731, '④ 삭제 <1991ㆍ5ㆍ31>', 9975);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16732, '①이 법 제3조 내지 제8조의 죄를 범하거나 범하려는 자라는 정을 알면서 총포ㆍ탄약ㆍ화약 기타 무기를 제공한 자는 5년 이상의 유기징역에 처한다. <개정 1991ㆍ5ㆍ31>', 9976);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16733, '②이 법 제3조 내지 제8조의 죄를 범하거나 범하려는 자라는 정을 알면서 금품 기타 재산상의 이익을 제공하거나 잠복ㆍ회합ㆍ통신ㆍ연락을 위한 장소를 제공하거나 기타의 방법으로 편의를 제공한 자는 10년 이하의 징역에 처한다. 다만, 본범과 친족관계가 있는 때에는 그 형을 감경 또는 면제할 수 있다. <개정 1991ㆍ5ㆍ31>', 9976);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16734, '③제1항 및 제2항의 미수범은 처벌한다.', 9976);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16735, '④제1항의 죄를 범할 목적으로 예비 또는 음모한 자는 1년 이상의 유기징역에 처한다.', 9976);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16736, '⑤ 삭제 <1991ㆍ5ㆍ31>', 9976);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16737, '①타인으로 하여금 형사처분을 받게 할 목적으로 이 법의 죄에 대하여 무고 또는 위증을 하거나 증거를 날조ㆍ인멸ㆍ은닉한 자는 그 각조에 정한 형에 처한다.', 9979);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16738, '②범죄수사 또는 정보의 직무에 종사하는 공무원이나 이를 보조하는 자 또는 이를 지휘하는 자가 직권을 남용하여 제1항의 행위를 한 때에도 제1항의 형과 같다. 다만, 그 법정형의 최저가 2년미만일 때에는 이를 2년으로 한다.', 9979);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16739, '①이 법의 죄를 범하고 그 보수를 받은 때에는 이를 몰수한다. 다만, 이를 몰수할 수 없을 때에는 그 가액을 추징한다.', 9982);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16740, '②검사는 이 법의 죄를 범한 자에 대하여 소추를 하지 아니할 때에는 압수물의 폐기 또는 국고귀속을 명할 수 있다.', 9982);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16741, null, 9983);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16742, '①검사 또는 사법경찰관으로부터 이 법에 정한 죄의 참고인으로 출석을 요구받은 자가 정당한 이유없이 2회 이상 출석요구에 불응한 때에는  관할법원판사의 구속영장을 발부받아 구인할 수 있다.', 9985);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16743, '②구속영장에 의하여 참고인을 구인하는 경우에 필요한 때에는 근접한 경찰서 기타 적당한 장소에 임시로 유치할 수 있다.', 9985);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16744, '①지방법원판사는 제3조 내지 제10조의 죄로서 사법경찰관이 검사에게 신청하여 검사의 청구가 있는 경우에 수사를 계속함에 상당한 이유가 있다고 인정한 때에는 형사소송법 제202조의 구속기간의 연장을 1차에 한하여 허가할 수 있다.', 9986);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16745, '②지방법원판사는 제1항의 죄로서 검사의 청구에 의하여 수사를 계속함에 상당한 이유가 있다고 인정한 때에는 형사소송법 제203조의 구속기간의 연장을 2차에 한하여 허가할 수 있다.', 9986);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16746, '③제1항 및 제2항의 기간의 연장은 각 10일 이내로 한다.', 9986);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16747, '①검사는 이 법의 죄를 범한 자에 대하여 형법 제51조의 사항을 참작하여 공소제기를 보류할 수 있다.', 9987);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16748, '②제1항에 의하여 공소보류를 받은 자가 공소의 제기없이 2년을 경과한 때에는 소추할 수 없다.', 9987);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16749, '③공소보류를 받은 자가 법무부장관이 정한 감시ㆍ보도에 관한 규칙에 위반한 때에는 공소보류를 취소할 수 있다.', 9987);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16750, '④제3항에 의하여 공소보류가 취소된 경우에는 형사소송법 제208조의 규정에 불구하고 동일한 범죄사실로 재구속할 수 있다.', 9987);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16751, '①이 법의 죄를 범한 자를 수사기관 또는 정보기관에 통보하거나 체포한 자에게는 대통령령이 정하는 바에 따라 상금을 지급한다.', 9988);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16752, '②이 법의 죄를 범한 자를 인지하여 체포한 수사기관 또는 정보기관에 종사하는 자에 대하여도 제1항과 같다.', 9988);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16753, '③이 법의 죄를 범한 자를 체포할 때 반항 또는 교전상태하에서 부득이한 사유로 살해하거나 자살하게 한 경우에는 제1항에 준하여 상금을 지급할 수 있다.', 9988);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16754, '①제21조의 경우에 압수물이 있는 때에는 상금을 지급하는 경우에 한하여 그 압수물 가액의 2분의 1에 상당하는 범위안에서 보로금을 지급할 수 있다.', 9989);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16755, '②반국가단체나 그 구성원 또는 그 지령을 받은 자로부터 금품을 취득하여 수사기관 또는 정보기관에 제공한 자에게는 그 가액의 2분의 1에 상당하는 범위안에서 보로금을 지급할 수 있다. 반국가단체의 구성원 또는 그 지령을 받은 자가 제공한 때에도 또한 같다.', 9989);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16756, '③보로금의 청구 및 지급에 관하여 필요한 사항은 대통령령으로 정한다.', 9989);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16757, '①이 법에 의한 상금과 보로금의 지급 및 제23조에 의한 보상대상자를 심의ㆍ결정하기 위하여 법무부장관소속하에 국가보안유공자 심사위원회(이하 "委員會"라 한다)를 둔다. <개정 1991ㆍ5ㆍ31>', 9991);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16758, '②위원회는 심의상 필요한 때에는 관계자의 출석을 요구하거나 조사할 수 있으며, 국가기관 기타 공ㆍ사단체에 조회하여 필요한 사항의 보고를 요구할 수 있다.', 9991);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16759, '③위원회의 조직과 운영에 관하여 필요한 사항은 대통령령으로 정한다.', 9991);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16760, '① 법무부장관은 수요기관에 대하여 법 제4조에 따른 공고에 필요한 자료의 제출을 요청할 수 있다.', 9996);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16761, '② 제1항에 따른 요청을 받은 수요기관은 지정된 기간 내에 필요한 자료를 성실하게 작성하여 제출하여야 한다.', 9996);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16762, '① 법무부장관은 제3조에 따라 제출된 생산공급계획과 제4조에 따라 제출된 자료를 검토하고 다음 각 호의 사항을 고려하여 법 제4조에서 정한 기한까지 다음 연도에 생산할 교도작업제품의 종류와 수량을 결정하여 공고하여야 한다.', 9997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16763, '② 법무부장관은 교도작업제품을 공급할 수 없을 때에는 해당 지역 또는 해당 수요기관을 미리 공고하여야 한다.', 9997);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16764, '① 소장은 다음 각 호의 사항을 고려하여 법무부장관의 승인을 받아 교도작업의 시행방법에 따른 교도작업의 종류를 교도작업제품별로 정한다. 교도작업의 종류를 변경하는 경우에도 또한 같다.', 9998);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16765, '② 제1항에 따른 교도작업의 종류 및 그 승인 절차는 법무부령으로 정한다.', 9998);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16766, '① 특별회계의 회계처리는 「국가회계법」 제11조에 따른 국가회계기준에 따른다.', 10000);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16767, '② 법무부장관은 특별회계 재무구조의 건전화와 효율적인 경영성과의 분석을 위하여 필요하다고 인정하면 별도의 회계기준을 마련하여 특별회계 운영의 분석에 활용할 수 있다.', 10000);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16768, null, 10001);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16769, null, 10002);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16770, '① 삭제 <1996.11.23>', 10006);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16771, '② 1953년 2월 14일까지 제정된 법령 중 벌금 또는 과태료에 관한 규정을 적용할 때에는 그 규정에 정하여진 화폐단위 원(圓)을 원으로 본다. <개정 2010.3.24>', 10006);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16772, '③ 1953년 2월 15일부터 1962년 6월 9일까지 제정된 법령 중 벌금 또는 과태료에 관한 규정을 적용할 때에는 그 규정에 정하여진 화폐단위 <img src="http://www.law.go.kr/flDownload.do?flSeq=105924337"  alt="img105924337" >환(?)</img>을 원으로 본다. <개정 2010.3.24>', 10006);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16773, '④ 1962년 6월 10일부터 1966년 12월 31일까지 제정된 법령 중 벌금 또는 과태료에 관한 규정을 적용할 때에는 그 벌금 또는 과태료의 금액은 규정된 금액의 4배에 상당하는 금액으로 한다. <개정 2010.3.24>', 10006);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16774, '⑤ 1967년 1월 1일부터 1973년 12월 31일까지 제정된 법령 중 벌금 또는 과태료에 관한 규정을 적용할 때에는 그 벌금 또는 과태료의 금액은 규정된 금액의 2배에 상당하는 금액으로 한다. <개정 2010.3.24>', 10006);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16775, null, 10010);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16776, '① 위원은 특별사면등의 심사대상자와 가족 또는 친족관계에 있거나 있었던 경우 또는 그 밖의 사정으로 공정한 심사가 어렵다고 판단되는 경우에는 그 심사대상자에 대한 심사를 회피하여야 한다.', 10012);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16777, '② 제1항에 따른 회피는 위원장에게 구두 또는 서면으로 신청하여야 한다.', 10012);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16778, '③ 위원장은 제2항에 따른 회피신청이 이유가 있다고 인정하는 경우에는 이를 허용하여야 한다.', 10012);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16779, '① 위원장은 위원회를 대표하고, 위원회의 업무를 총괄한다.', 10013);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16780, '② 위원장이 부득이한 사유로 직무를 수행할 수 없을 때에는 위원장이 미리 지명한 위원이 그 직무를 대행한다.', 10013);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16781, '① 위원회의 회의는 위원장이 소집한다.', 10014);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16782, '② 위원회의 회의는 재적위원 과반수의 출석으로 개의(開議)하고, 출석위원 과반수의 찬성으로 의결한다.', 10014);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16783, '③ 위원회는 필요한 경우에는 위원이 아닌 자를 회의에 출석하게 하여 그 의견을 들을 수 있다.', 10014);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16784, '① 위원회의 사무를 처리하기 위하여 위원회에 간사 1명과 서기 약간 명을 둔다.', 10015);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16785, '② 간사는 법무부 형사기획과장이 된다. 다만, 법무부장관은 법무부 소속의 다른 공무원을 간사로 임명할 수 있다.', 10015);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16786, '③ 간사는 위원장의 명을 받아 위원회의 사무를 처리하고 회의에 참석하여 발언할 수 있다.', 10015);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16787, '④ 서기는 간사를 보조한다.', 10015);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16788, '① 위원회의 심사가 종료된 때에는 심의서를 작성하여야 한다.', 10017);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16789, '② 심의서에는 위원회에서 특별사면등 상신의 적정성에 관하여 심사한 결과에 따라 심사대상자별로 적정 또는 부적정 의견을 기재한다.', 10017);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16790, '③ 심사과정에서 제시된 개별 위원의 의견은 심의서에 표시하지 아니한다.', 10017);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16791, '④ 심의서에는 위원장 및 출석위원 전원이 서명 또는 기명ㆍ날인한다.', 10017);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16792, '⑤ 위원이 부득이한 사유로 서명 또는 기명ㆍ날인할 수 없는 경우에는 그 사유를 기재하고 위원장이 서명 또는 기명ㆍ날인한다.', 10017);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16793, '① 위원회를 개최하였을 때에는 간사가 회의록을 작성하여야 한다.', 10018);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16794, '② 회의록에는 회의 개요, 심사대상, 위원회의 심사의견, 그 밖의 주요 논의사항 등을 기재한다.', 10018);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16795, '③ 위원회 심사과정에서 심사대상에 대한 특별사면등 상신의 적정성에 관하여 각 위원의 의견이 일치하지 아니한 경우에는 회의록에 개별 위원의 의견을 기재하여야 한다.', 10018);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16796, '④ 회의록에는 위원장과 간사가 서명 또는 기명ㆍ날인한다.', 10018);
INSERT INTO balaw.hang (id, content, jo_id) VALUES (16797, null, 10019);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1, '1.  영업을 시작하지 않았거나 휴업 또는 영업중단 등으로 영업실적이 없는 경우', 1);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2, '2.  재해 등으로 매출액 산정 관련 자료가 소멸되거나 훼손되는 등 매출액의 산정이 곤란한 경우', 1);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3, '1.  법 제12조제1항 각 호의 위반 사실을 알게 된 즉시 이를 환경부장관에게 자발적으로 신고하고 시정한 자: 같은 항 각 호 외의 부분 본문에 따른 위반부과금액(이하 "위반부과금액"이라 한다)의 100분의 30에 상당하는 금액 이하', 3);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4, '2.  제1호에 해당하는 자로서 조사가 끝날 때까지 일관되게 위반 사실을 인정하고 관련 자료를 제출하는 등 조사에 적극적으로 협력한 자: 위반부과금액의 100분의 50에 상당하는 금액 이하', 3);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5, '3.  제1호 및 제2호에 해당하는 자로서 공동불법행위를 환경부장관에게 최초로 신고하고 관련 자료를 제출한 자: 위반부과금액의 100분의 80에 상당하는 금액 이하', 3);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6, '1.  환경부의 다음 각 목의 업무를 담당하는 부서에 소속된 3급부터 7급까지의 공무원', 16);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7, '2.  지방환경관서의 환경오염물질 배출시설 감시 및 환경수사 업무를 담당하는 부서에 소속된 4급부터 9급까지의 공무원', 16);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8, '1.  제11조제1항제1호 또는 제2호에 따른 부서의 소속으로 근무하지 아니하게 된 경우', 19);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9, '2.  제11조제3항에 따른 전담반이 해산된 경우', 19);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10, '1.  강등ㆍ정직처분을 받은 경우: 1년 6개월', 21);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11, '2.  감봉처분을 받은 경우: 1년', 21);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (12, '3.  견책처분을 받은 경우: 6개월', 21);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (13, '1.  환경관계법령위반행위의 단속 및 예방', 22);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (14, '2.  환경오염사고 조사', 22);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (15, '3.  삭제 <2020.11.10>', 22);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (16, '4.  환경관계법령위반행위의 단속 및 예방을 위하여 환경부장관 또는 지방환경관서의 장이 지시한 사항', 22);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (17, '5.  그 밖에 환경관계법령위반행위의 단속 및 예방을 위하여 필요한 자료의 수집ㆍ분석 및 통계관리', 22);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (18, '1.  국립환경과학원 및 그 소속 기관', 25);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (19, '2.  특별시ㆍ광역시ㆍ도ㆍ특별자치도의 보건환경연구원', 25);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (20, '3.  지방환경관서', 25);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (21, '4.  「한국환경공단법」에 따른 한국환경공단', 25);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (22, '1.  삭제 <2020.11.10>', 26);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (23, '2.  법 제13조제1항 및 제3항에 따른 불법배출시설의 사용중지ㆍ철거ㆍ폐쇄 명령 및 대집행', 26);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (24, '3.  법 제13조제4항에 따른 표지판 설치', 26);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (25, '3의2.  법 제14조제2항에 따른 종전사업자의 행정처분이력등 확인 요청의 접수 및 그 확인 서류의 발급', 26);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (26, '4.  법 제16조에 따른 사업장의 출입ㆍ검사(제2호 또는 제3호에 따라 위임된 권한을 행사하기 위한 경우로 한정한다)', 26);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (27, '5.  법 제17조에 따른 자료제출 요구(제2호 또는 제3호에 따라 위임된 권한을 행사하기 위한 경우로 한정한다)', 26);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (28, '1.  「폐기물관리법」 제25조제3항에 따라 지정폐기물을 대상으로 하는 폐기물처리업의 허가를 받은 자', 27);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (29, '2.  「화학물질관리법」 제18조제1항 단서에 따른 제조ㆍ수입ㆍ판매의 허가를 받은 자 또는 같은 법 제27조 각 호의 어느 하나에 해당하는 영업의 허가를 받거나 신고를 한 자', 27);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (30, '1.  법 제33조제1항제1호 내지 제6호의 어느 하나에 해당하는 때에는 변호인 없이 개정할 수 없는 취지와 피고인 스스로 변호인을 선임하지 아니할 경우에는 법원이 국선변호인을 선정하게 된다는 취지', 66);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (31, '2.  법 제33조제2항에 해당하는 때에는 법원에 대하여 국선변호인의 선정을 청구할 수 있다는 취지', 66);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (32, '3.  법 제33조제3항에 해당하는 때에는 법원에 대하여 국선변호인의 선정을 희망하지 아니한다는 의사를 표시할 수 있다는 취지', 66);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (33, '1.  피고인 또는 피의자에게 변호인이 선임된 때', 70);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (34, '2.  국선변호인이 제14조제1항 및 제2항에 규정한 자격을 상실한 때', 70);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (35, '3.  법원 또는 지방법원 판사가 제20조의 규정에 의하여 국선변호인의 사임을 허가한 때', 70);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (36, '1.  국선변호인이 그 직무를 성실하게 수행하지 아니하는 때', 71);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (37, '2.  피고인 또는 피의자의 국선변호인 변경 신청이 상당하다고 인정하는 때', 71);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (38, '3.  그 밖에 국선변호인의 선정결정을 취소할 상당한 이유가 있는 때', 71);
