INSERT INTO balaw.ho (id, content, hang_id) VALUES (145, '1.  피해자등이나 피해자 변호사가 이미 해당 사건에 관하여 충분히 진술하여 다시 진술할 필요가 없다고 인정되는 경우', 370);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (146, '2.  의견진술 또는 질문으로 인하여 공판절차가 현저하게 지연될 우려가 있다고 인정되는 경우', 370);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (147, '3.  의견진술과 질문이 해당 사건과 관계없는 사항에 해당된다고 인정되는 경우', 370);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (148, '4.  범죄사실의 인정에 관한 것이거나, 그 밖의 사유로 피해자등의 의견진술로서 상당하지 아니하다고 인정되는 경우', 370);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (149, '1.  검사 또는 피해자 변호사에게 의견조회서를 교부 또는 송부하여 그로부터 해당 의견조회서를 제출받는 방법', 376);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (150, '2.  서면ㆍ전화ㆍ전자우편ㆍ모사전송ㆍ휴대전화 문자전송 그 밖에 적당한 방법으로 피해자등의 의견을 확인하는 방법. 이 경우 법원사무관등은 의견 확인의 상대방ㆍ방법ㆍ연월일 및 피해자등이 제출한 의견(피해자등이 의견제출을 거절하는 등의 경우에는 그러한 취지)을 기재한 서면을 기록에 편철하여야 한다. 다만, 조서에 그 내용을 기재한 경우에는 그러하지 아니하다.', 376);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (151, '1.  피해자등이 이미 해당 사건에서 피고인의 공탁에 관하여 의사를 진술하여 다시 그 의사를 확인할 필요가 없는 경우', 377);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (152, '2.  피해자등의 의견 청취로 인하여 공판절차가 현저하게 지연될 우려가 있는 경우', 377);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (153, '3.  피공탁자의 인적사항을 확인할 수 없는 등의 사유로 피해자등의 의견을 듣기 곤란한 경우', 377);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (154, '4.  그 밖에 심리나 절차 진행의 상황 등에 비추어 피해자등의 의견을 듣기 곤란한 경우', 377);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (155, '1.  사건번호, 사건명', 379);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (156, '2.  신청인 및 피해자와의 관계', 379);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (157, '3.  열람 또는 등사할 대상', 379);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (158, '4.  열람 또는 등사를 신청하는 이유', 379);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (159, '1.  재판장은 제127조의 규정에 따라 피고인에게 진술거부권 등을 고지한 후 법 제284조에 따른 인정신문을 하여 피고인임에 틀림없음을 확인하여야 한다.', 395);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (160, '2.  재판장은 검사로 하여금 공소장 또는 공소장변경허가신청서에 의하여 공소사실, 죄명 및 적용법조를 낭독하게 하거나 그 요지를 진술하게 하여야 한다.', 395);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (161, '3.  재판장은 피고인에게 공소사실의 인정 여부 및 정상에 관하여 진술할 기회를 주어야 한다.', 395);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (162, '4.  재판장은 갱신전의 공판기일에서의 피고인이나 피고인이 아닌 자의 진술 또는 법원의 검증결과를 기재한 조서에 관하여 증거조사를 하여야 한다. 다만, 이 규칙 제29조에 따라 조서의 일부로 된 녹음물에 대한 녹취서가 있으면 그 녹취서를 법 제292조에서 정한 방법에 따라 조사하는 것으로 그 녹음물에 대한 증거조사를 갈음할 수 있다.', 395);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (163, '5.  재판장은 갱신전의 공판기일에서 증거조사된 서류 또는 물건에 관하여 다시 증거조사를 하여야 한다. 다만, 증거능력 없다고 인정되는 서류 또는 물건과 증거로 함이 상당하지 아니하다고 인정되고 검사, 피고인 및 변호인이 이의를 하지 아니하는 서류 또는 물건에 대하여는 그러하지 아니하다.', 395);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (164, '1.  제1심에서 조사되지 아니한 데에 대하여 고의나 중대한 과실이 없고, 그 신청으로 인하여 소송을 현저하게 지연시키지 아니하는 경우', 426);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (165, '2.  제1심에서 증인으로 신문하였으나 새로운 중요한 증거의 발견 등으로 항소심에서 다시 신문하는 것이 부득이하다고 인정되는 경우', 426);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (166, '3.  그 밖에 항소의 당부에 관한 판단을 위하여 반드시 필요하다고 인정되는 경우', 426);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (167, '1.  항소법원은 판결확정일로부터 7일 이내에 소송기록과 증거물을 환송 또는 이송받을 법원에 송부하고, 항소법원에 대응하는 검찰청 검사 또는 수사처검사에게 그 사실을 통지하여야 한다.', 432);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (168, '2.  제1호의 송부를 받은 법원은 지체없이 그 법원에 대응한 검찰청 검사 또는 수사처검사에게 그 사실을 통지하여야 한다.', 432);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (169, '3.  피고인이 교도소 또는 구치소에 있는 경우에는 항소법원에 대응한 검찰청 검사 또는 수사처검사는 제1호의 통지를 받은 날로부터 10일 이내에 피고인을 환송 또는 이송받을 법원소재지의 교도소나 구치소에 이감한다.', 432);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (170, '1.  철도운임 및 선박운임은 그 운임에 등급구별이 있는 경우에는 중간등급이하의 운임, 등급구별이 없는 경우에는 승차나 승선에 요하는 실비액', 455);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (171, '2.  자동차운임은 실비액', 455);
