INSERT INTO balaw.ho (id, content, hang_id) VALUES (597, '3.  전자충격기, 전자충격총 및 고무탄총의 경우: 상대방의 얼굴을 향해 전자충격을 가하거나 전극침 또는 고무탄을 발사하지 말 것', 1046);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (598, '4.  최루제와 그 발사장치의 경우: 다음 각 목의 어느 하나에 해당하는 경우에 최소한의 범위에서 사용할 것. 이 경우 30도 이상의 발사각을 유지해야 하며, 1미터 이내의 거리에서 상대방의 얼굴을 향하여 발사해서는 안 된다.', 1046);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (599, '1.  신규도입장비의 주요 특성 및 기본적인 작동 원리', 1050);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (600, '2.  안전성 검사의 방법 및 기준', 1050);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (601, '3.  안전성 검사에 참여한 외부 전문가의 의견', 1050);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (602, '4.  안전성 검사 결과 및 종합의견', 1050);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (603, '1.  손실을 입은 물건을 수리할 수 있는 경우: 수리비에 해당하는 금액', 1052);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (604, '2.  손실을 입은 물건을 수리할 수 없는 경우: 손실을 입은 당시의 해당 물건의 교환가액', 1052);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (605, '3.  영업자가 손실을 입은 물건의 수리나 교환으로 인하여 영업을 계속할 수 없는 경우: 영업을 계속할 수 없는 기간 중 영업상 이익에 해당하는 금액', 1052);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (606, '1.  청구인이 같은 청구 원인으로 보상신청을 하여 보상금 지급 여부에 대하여 결정을 받은 경우. 다만, 기각 결정을 받은 청구인이 손실을 증명할 수 있는 새로운 증거가 발견되었음을 소명하는 경우는 제외한다.', 1057);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (607, '2.  손실보상 청구가 요건과 절차를 갖추지 못한 경우. 다만, 그 잘못된 부분을 시정할 수 있는 경우는 제외한다.', 1057);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (608, '1.  보상금을 지급하기로 결정한 경우: 별지 제3호서식의 보상금 지급 청구 승인 통지서', 1058);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (609, '2.  보상금 지급 청구를 각하하거나 보상금을 지급하지 않기로 결정한 경우: 별지 제4호서식의 보상금 지급 청구 각하ㆍ기각 통지서', 1058);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (610, '1.  별표 3 제2호에 따른 부상등급이 변경된 경우(부상등급 외의 부상에서 제1급부터 제8급까지의 등급으로 변경된 경우를 포함한다)', 1061);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (611, '2.  별표 3 제2호에 따른 부상등급 외의 부상에 대하여 부상등급의 변경은 없으나 보상금의 추가 지급이 필요한 경우', 1061);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (612, '1.  판사ㆍ검사ㆍ군법무관 또는 변호사로 5년 이상 재직한 사람', 1064);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (613, '2.  「고등교육법」 제2조에 따른 학교에서 법학 또는 행정학을 가르치는 부교수 이상으로 5년 이상 재직한 사람', 1064);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (614, '3.  손실보상에 관하여 학식과 경험이 풍부한 사람', 1064);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (615, '1.  위원 또는 그 배우자나 배우자였던 사람이 심의 안건의 청구인인 경우', 1073);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (616, '2.  위원이 심의 안건의 청구인과 친족이거나 친족이었던 경우', 1073);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (617, '3.  위원이 심의 안건에 대하여 증언, 진술, 자문, 용역 또는 감정을 한 경우', 1073);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (618, '4.  위원이나 위원이 속한 법인이 심의 안건 청구인의 대리인이거나 대리인이었던 경우', 1073);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (619, '5.  위원이 해당 심의 안건의 청구인인 법인의 임원인 경우', 1073);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (620, '1.  심신장애로 인하여 직무를 수행할 수 없게 된 경우', 1076);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (621, '2.  직무태만, 품위손상이나 그 밖의 사유로 위원으로 적합하지 않다고 인정되는 경우', 1076);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (622, '3.  제19조제1항 각 호의 어느 하나에 해당하는데도 불구하고 회피하지 않은 경우', 1076);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (623, '4.  제21조를 위반하여 직무상 알게 된 비밀을 누설한 경우', 1076);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (624, '1.  법 제5조제1항제3호의 직무: 「개인정보 보호법 시행령」 제18조제2호에 따른 범죄경력자료에 해당하는 정보, 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호', 1077);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (625, '2.  법 제5조제1항제4호의 직무: 「개인정보 보호법」 제23조에 따른 건강에 관한 정보 또는 같은 법 시행령 제19조제1호에 따른 주민등록번호', 1077);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (626, '1.  법 제11조에 따른 관련사건. 이 경우 이미 검찰청 또는 이에 상응하는 관서에 송치하거나 이송한 후에 수리한 사건도 포함한다.', 1104);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (627, '2.  불기소처분을 한 사건과 그 처분을 한 후 검사의 지휘에 따라 다시 수사를 개시한 사건', 1104);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (628, '3.  1건으로 함께 수사하도록 검사의 수사지휘를 받은 사건', 1104);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (629, '4.  다른 기관이나 다른 관서로부터 1건으로 이송된 사건', 1104);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (630, '1.  피혐의자의 수사기관 출석조사', 1113);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (631, '2.  피의자신문조서의 작성', 1113);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (632, '3.  긴급체포', 1113);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (633, '4.  체포ㆍ구속영장의 신청', 1113);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (634, '5.  사람의 신체, 주거, 관리하는 건조물, 자동차, 선박, 항공기 또는 점유하는 방실에 대한 압수ㆍ수색 또는 검증영장(부검을 위한 검증영장은 제외한다)의 신청', 1113);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (635, '1.  압수ㆍ수색ㆍ검증(법에 따른 사람의 신체, 주거, 관리하는 건조물, 자동차, 선박, 항공기 또는 점유하는 방실에 대한 압수ㆍ수색ㆍ검증은 제외한다) 영장, 「통신비밀보호법」 제6조 및 제8조에 따른 통신제한조치허가서 및 같은 법 제13조에 따른 통신사실 확인자료제공요청 허가서 등 법원으로부터 법 및 다른 법률에 따라 발부받은 영장 또는 허가서에 의한 대물적(對物的) 강제처분의 집행', 1117);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (636, '2.  현행범인의 체포 또는 인수', 1117);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (637, '1.  사건관계인이 검사에게 이의를 제기한 경우', 1118);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (638, '2.  검사가 사건관계인의 인권이 침해되었다고 인정할 만한 현저한 이유가 있다고 판단하는 경우', 1118);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (639, '1.  내란의 죄(「형법」 제2편제1장에 따른 죄 및 다른 법률에 따라 가중처벌되는 죄를 말한다)', 1124);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (640, '2.  외환의 죄(「형법」 제2편제2장에 따른 죄 및 다른 법률에 따라 가중처벌되는 죄를 말한다)', 1124);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (641, '3.  공안(公安)을 해하는 죄(「형법」 제2편제5장에 따른 죄 및 다른 법률에 따라 가중처벌되는 죄를 말한다)', 1124);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (642, '4.  폭발물과 방화 및 실화에 관한 죄(「형법」 제2편제6장 및 제13장에 따른 죄 및 다른 법률에 따라 가중처벌되는 죄를 말한다)', 1124);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (643, '5.  살인의 죄(「형법」 제2편제24장에 따른 죄 및 다른 법률에 따라 가중처벌되는 죄를 말한다)', 1124);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (644, '6.  상해치사ㆍ폭행치사죄(「형법」 제259조 및 제262조에 따른 죄 및 다른 법률에 따라 가중처벌되는 죄를 말한다)', 1124);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (645, '7.  공무원의 직무에 관한 죄 및 공무방해에 관한 죄(「형법」 제2편제7장ㆍ제8장에 따른 죄 및 다른 법률에 따라 가중처벌되는 죄를 말한다)', 1124);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (646, '8.  「국가보안법」 제3조부터 제12조까지의 규정에 따른 범죄', 1124);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (647, '9.  「군형법」 제2편제1장에 따른 반란의 죄, 같은 법 제81조에 따른 암호부정사용죄, 「군사기밀보호법」 제10조, 제11조, 제11조의2, 제12조, 제13조, 제13조의2, 제14조부터 제18조까지의 규정에 따른 범죄 및 「군용물 등 범죄에 관한 특별조치법」 제3조ㆍ제4조에 따른 범죄', 1124);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (648, '10.  다음 각 목의 어느 하나에 해당하는 범죄 중 피해규모, 광역성, 연쇄성, 범죄 태양 등에 비추어 사회적 이목을 끌만한 중대한 범죄', 1124);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (649, '11.  지방검찰청 검사장 또는 지청장이 특별히 지휘한 사항', 1124);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (650, '1.  해당 범죄가 진행 중에 있는 등 시급한 조치가 필요한 때', 1125);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (651, '2.  해당 범죄의 법정형에 징역형이 포함되어 있을 때', 1125);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (652, '1.  혐의없음', 1128);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (653, '2.  공소권없음', 1128);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (654, '3.  죄가안됨', 1128);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (655, '4.  각하', 1128);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (656, '5.  참고인중지', 1128);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (657, '1.  구체적 사건과 관련된 검사의 수사지휘의 적법성 또는 정당성에 이견이 있는 경우', 1137);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (658, '2.  구체적 사건과 관련된 검사의 수사지휘 내용이 명확하지 않아 이행하기 어려운 경우', 1137);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (659, '1.  내란의 죄(「형법」 제2편제1장에 따른 죄 및 다른 법률에 따라 가중처벌되는 죄를 말한다)', 1141);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (660, '2.  외환의 죄(「형법」 제2편제2장에 따른 죄 및 다른 법률에 따라 가중처벌되는 죄를 말한다)', 1141);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (661, '3.  공안을 해하는 죄(「형법」 제2편제5장에 따른 죄 및 다른 법률에 따라 가중처벌되는 죄를 말한다)', 1141);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (662, '4.  「국가보안법」 제3조부터 제12조까지의 규정에 따른 범죄', 1141);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (663, '5.  「군사기밀보호법」 제10조, 제11조, 제11조의2, 제12조, 제13조, 제13조의2 및 제14조부터 제18조까지의 규정에 따른 범죄', 1141);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (664, '1.  출석요구를 하기 전에 우편ㆍ전자우편ㆍ전화를 통한 진술 등 출석을 대체할 수 있는 방법의 선택 가능성을 고려할 것', 1144);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (665, '2.  출석요구의 방법, 출석의 일시ㆍ장소 등을 정할 때에는 피의자의 명예 또는 사생활의 비밀이 침해되지 않도록 주의할 것', 1144);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (666, '3.  출석요구를 할 때에는 피의자의 생업에 지장을 주지 않도록 충분한 시간적 여유를 두도록 하고, 피의자가 출석 일시의 연기를 요청하는 경우 특별한 사정이 없으면 출석 일시를 조정할 것', 1144);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (667, '4.  불필요하게 여러 차례 출석요구를 하지 않을 것', 1144);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (668, '1.  피의자를 체포한 후 48시간 이내에 구속영장의 청구 또는 신청 여부를 판단하기 위해 불가피한 경우', 1152);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (669, '2.  공소시효가 임박한 경우', 1152);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (670, '3.  피의자나 사건관계인이 출국, 입원, 원거리 거주, 직업상 사유 등 재출석이 곤란한 구체적인 사유를 들어 심야조사를 요청한 경우(변호인이 심야조사에 동의하지 않는다는 의사를 명시한 경우는 제외한다)로서 해당 요청에 상당한 이유가 있다고 인정되는 경우', 1152);
