INSERT INTO balaw.ho (id, content, hang_id) VALUES (799, '1.  영치금은 발송관서에서 수송관서에 전자금융을 이용하여 송금한다. 다만, 소액의 금전 또는 당일 호송을 마칠 수 있는 때에는 호송관에게 탁송(託送)할 수 있다.', 1372);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (800, '2.  피호송자가 법령에 의하여 호송 중에 물품 등을 자신의 비용으로 구매할 수 있는 때에 그 청구가 있으면 필요한 금액을 호송관에게 탁송하여야 한다.', 1372);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (801, '3.  영치품은 호송관에게 탁송한다. 다만, 위험하거나 호송관이 휴대하기 적당하지 아니한 영치품은 발송관서에서 수송관서에 직송(直送)할 수 있다.', 1372);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (802, '4.  송치중의 영치금품을 호송관에게 탁송한 때에는 호송관서에 보관책임이 있고, 그러하지 아니한 때에는 발송관서에 보관책임이 있다.', 1372);
