INSERT INTO balaw.ho (id, content, hang_id) VALUES (851, '3.  몰수의 확정재판에 관한 집행공조 또는 몰수를 목적으로 한 보전공조요청에 관계된 재산이 대한민국 법령에 따라 몰수재판 또는 몰수보전을 할 수 있는 재산에 해당되지 아니하는 경우', 1533);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (852, '4.  추징의 확정재판에 관한 집행공조 또는 추징을 목적으로 한 보전공조요청에 관계된 공조범죄에 대하여 대한민국 법령에 따라 추징재판 또는 추징보전을 할 수 없다고 인정되는 경우', 1533);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (853, '5.  몰수의 확정재판에 관한 집행공조요청에 관계된 재산을 가지거나 그 재산상에 지상권ㆍ저당권 또는 그 밖의 권리를 가지고 있다고 인정할 만한 상당한 이유가 있는 제3자가 자기의 책임으로 돌릴 수 없는 사유로 그 재판 절차에서 자기의 권리를 주장할 수 없었다고 인정되는 경우', 1533);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (854, '6.  몰수 또는 추징을 목적으로 한 보전공조에 대하여 제33조제1항 또는 제52조제1항에 따른 사유가 없다고 인정되는 경우. 다만, 보전공조요청이 요청국의 법원이나 법관이 집행한 몰수 또는 추징을 목적으로 한 보전재판에 근거한 요청이거나 몰수재판 또는 추징재판 확정 후의 요청인 경우에는 그러하지 아니하다.', 1533);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (855, '1.  몰수 확정재판의 집행공조인 경우에는 요청에 관계된 재산을 가지거나 그 재산상에 지상권ㆍ저당권 또는 그 밖의 권리를 가지고 있다고 인정할 만한 상당한 이유가 있는 자 또는 이들 재산이나 권리에 관하여 몰수보전이 되기 전에 강제경매 개시 결정 또는 강제집행에 의한 압류ㆍ가압류가 되어 있는 경우의 압류채권자 또는 가압류채권자', 1542);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (856, '2.  추징 확정재판의 집행공조인 경우에는 그 재판을 받은 자', 1542);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (857, '1.  신고자가 종사하고 있는 금융기관의 명칭 및 소재지', 1562);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (858, '2.  신고와 관계되는 자금거래(이하 "불법자금거래"라 한다)가 발생한 일시 및 장소', 1562);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (859, '3.  불법자금거래의 내용', 1562);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (860, '4.  불법자금거래의 상대방인 개인 또는 단체의 성명이나 명칭', 1562);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (861, '5.  불법자금거래의 상대방인 개인 또는 단체의 주소나 거소', 1562);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (862, '6.  불법자금거래를 신고하는 이유', 1562);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (863, '1.  "형사사법포털"이란 전자문서를 이용해 형사사법절차를 진행할 수 있도록 구축된 「형사사법절차 전자화 촉진법」 제2조제6호의 형사사법포털을 말한다.', 1563);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (864, '2.  "전자기록"이란 전자문서 또는 전자화문서를 사건별로 모아둔 것을 말한다.', 1563);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (865, '3.  "수사기관등"이란 법원을 제외한 형사사법업무 처리기관을 말한다.', 1563);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (866, '4.  "정보통신망"이란 「전기통신기본법」 제2조제2호에 따른 전기통신설비를 이용하거나 전기통신설비와 컴퓨터 및 컴퓨터의 이용기술을 활용해 정보를 수집ㆍ가공ㆍ저장ㆍ검색ㆍ송신 또는 수신하는 정보통신체제를 말한다.', 1563);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (867, '1.  피의자ㆍ피고인ㆍ피해자ㆍ고소인ㆍ고발인의 법정대리인(피해자가 사망한 경우 피해자의 배우자, 직계친족 및 형제자매를 포함한다)', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (868, '2.  피의자ㆍ피고인ㆍ피해자ㆍ고소인ㆍ고발인이 법인인 경우 그 대표자', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (869, '3.  「형사소송법」 제28조에 따른 특별대리인', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (870, '4.  「형사소송법」 제29조에 따른 보조인', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (871, '5.  「형사소송법」 제34조에 따른 변호인이 되려는 자', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (872, '6.  피해자ㆍ고소인의 대리인(다음 각 목의 자를 포함한다)', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (873, '7.  「형사소송법」 제244조의5에 따른 피의자와 신뢰관계에 있는 자, 같은 법 제276조의2에 따른 피고인과 신뢰관계에 있는 자 및 같은 법 제163조의2에 따른 피해자와 신뢰관계에 있는 자', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (874, '8.  「노인복지법」 제39조의8, 「아동복지법」 제21조 또는 「장애인복지법」 제59조의8 등 관계 법령에 따른 피해자의 보조인', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (875, '9.  「성폭력범죄의 처벌 등에 관한 특례법」 제35조(「아동학대범죄의 처벌 등에 관한 특례법」 제17조에서 준용하는 경우를 포함한다) 또는 「장애인복지법」 제59조의16 등 관계 법령에 따라 성폭력범죄, 아동학대범죄 또는 장애인학대범죄 등의 피해자에 대해 형사사법절차 등에서 조력을 하는 진술조력인', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (876, '10.  「형사소송법」 제245조의2에 따른 전문수사자문위원', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (877, '11.  수사기관으로부터 「성폭력범죄의 처벌 등에 관한 특례법」 제33조제4항에 따라 의견 조회를 받은 정신건강의학과의사ㆍ심리학자ㆍ사회복지학자 또는 그 밖의 관련 전문가', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (878, '12.  통역인ㆍ번역인 및 감정인', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (879, '13.  수사기관등으로부터 감정을 촉탁받은 기관', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (880, '14.  압수물의 소유자ㆍ소지자ㆍ보관자 및 제출인(압수물의 환부 또는 가환부를 청구하는 경우로 한정한다)', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (881, '15.  참고인', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (882, '16.  피내사자ㆍ피혐의자', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (883, '17.  진정인ㆍ피진정인', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (884, '18.  「형사소송법」 제199조제2항에 따라 필요한 사항의 보고를 요구받은 공무소나 그 밖의 공사단체', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (885, '19.  법 제17조에 따라 영장, 허가장, 허가서 및 요청서 등을 전송받은 피압수자', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (886, '20.  무죄 판결이 확정된 경우 해당 사건의 피고인이었던 사람', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (887, '21.  「보호관찰 등에 관한 법률」 제3조제1항에 따른 보호관찰 대상자  및 같은 조 제2항에 따른 사회봉사ㆍ수강명령 대상자', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (888, '22.  「보호관찰 등에 관한 법률」 제15조에 따른 보호관찰소의 관장사무와 관련해 문서를 제출할 정당한 권한 또는 의무가 있는 다음 각 목의 자', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (889, '23.  「보호소년 등의 처우에 관한 법률」 제7조제3항에 따른 보호자등과 같은 법 제4조에 따른 소년원ㆍ소년분류심사원의 소관 업무와 관련해 문서를 제출할 정당한 권한 또는 의무가 있는 자', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (890, '24.  「소년법」에 따른 소년 보호사건의 소년 및 그 소년의 법정대리인ㆍ보조인', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (891, '25.  그 밖에 법 제3조 각 호의 법률에 따른 형사사법절차에 따라 문서를 제출할 정당한 권한 또는 의무가 있는 자', 1564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (892, '1.  개인회원', 1565);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (893, '2.  법인회원', 1565);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (894, '3.  변호사회원', 1565);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (895, '1.  피의자, 피고인, 피해자, 고소인, 고발인 및 변호인', 1567);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (896, '2.  제3조 각 호의 자', 1567);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (897, '3.  전자기록사건에서 사용자등록을 하지 않은 자', 1567);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (898, '1.  사용자등록이 형사사법절차를 지연시키려는 목적 등 본래의 용도와 다른 목적으로 이용되는 경우', 1571);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (899, '2.  등록사용자에게 의사능력이 없는 경우', 1571);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (900, '3.  등록사용자가 형사사법포털을 이용해 전자문서를 제출ㆍ열람한 마지막 날부터 5년이 지난 경우', 1571);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (901, '4.  그 밖에 전산정보처리시스템 사용을 정지하거나 사용자등록을 말소할 필요가 있는 경우로서 법 제7조제3항제1호부터 제4호까지 또는 이 항 제1호부터 제3호까지에 준하는 경우', 1571);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (902, '1.  해당 전자문서에 공동명의자 전원이 인증서로 전자서명을 하여 제출하는 방법', 1582);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (903, '2.  해당 전자문서를 최초로 제출하는 등록사용자가 그 전자문서 속에 다른 공동명의자 전원의 전자서명을 포함시켜 제출하는 방법', 1582);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (904, '3.  해당 전자문서를 최초로 제출하는 등록사용자가 다른 공동명의자 전원의 서명 또는 날인이 이루어진 확인서를 전자문서로 변환해 함께 제출하는 방법', 1582);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (905, '1.  해당 전자문서에 소속사용자를 지정한 등록사용자의 인증서로 전자서명을 하여 제출하는 방법', 1584);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (906, '2.  소속사용자를 지정한 등록사용자의 위임장과 그 등록사용자의 서명 또는 날인이 이루어진 확인서를 전자문서로 변환해 함께 제출하는 방법', 1584);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (907, '1.  전산정보처리시스템 또는 정보통신망에 발생한 장애의 복구 시기를 알 수 없거나 장애의 복구를 기다릴 경우 절차가 현저히 지연될 우려가 있는 경우', 1601);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (908, '2.  「형사소송법」 등 관계 법령에 따라 체포영장, 구속영장, 압수ㆍ수색ㆍ검증영장 등 영장을 집행할 때 급속을 요하거나 집행시한이 임박한 경우 또는 영장집행의 원활한 진행을 위해 필요한 경우', 1601);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (909, '3.  현장에서 관계 서류를 긴급히 작성하거나 교부해야 하는 등 전자문서로 작성하는 것이 현저히 곤란하거나 적합하지 않은 경우', 1601);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (910, '4.  수사기관등이 수사기관등 외의 기관으로부터 전자문서가 아닌 형태로 사건의 송치 등을 받아 그 사건에 대한 수사를 계속하는 경우', 1601);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (911, '5.  수사기관등이 보관ㆍ관리하고 있는 전자기록이 외부로 유출될 경우 국가의 존립ㆍ안전이나 자유민주적 기본질서에 해를 끼칠 우려가 있는 경우', 1601);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (912, '1.  제1항제1호부터 제3호까지의 각 사유가 해소된 경우', 1602);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (913, '2.  형사사법업무 처리기관에 전자기록을 전송하는 경우', 1602);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (914, '1.  현황이 중요한 의미가 있어 그 자체로 보관할 필요가 있는 경우', 1610);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (915, '2.  서적, 대형 도면 등 제출된 전자화대상문서의 크기, 선명도 등을 고려할 때 해당 전자화대상문서의 전부 또는 일부를 전자적인 형태로 변환ㆍ등재하는 것이 적절하지 않은 경우. 이 경우 일부 중요한 내용을 전자적인 형태로 변환ㆍ등재할 수 있다.', 1610);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (916, '3.  전자적인 형태로 변환하는 것이 기술적으로 어려운 경우', 1610);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (917, '4.  사건관계인의 영업비밀(「부정경쟁방지 및 영업비밀보호에 관한 법률」 제2조제2호의 영업비밀을 말한다)로서 외부로 유출될 경우 영업상의 이익이 침해되거나 침해될 우려가 있는 경우', 1610);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (918, '5.  수사기관등이 보관ㆍ관리하고 있는 전자기록이 외부로 유출될 경우 국가의 존립ㆍ안전이나 자유민주적 기본질서에 해를 끼칠 우려가 있는 경우', 1610);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (919, '6.  전자적인 형태로 변환할 경우 피해자에게 추가적인 피해가 발생할 우려가 있는 경우', 1610);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (920, '7.  사건과 관련이 없는 자료가 대량으로 제출되거나 반복적으로 제출되어 전자화대상문서를 전자적인 형태로 변환하는 것이 적절하지 않은 경우', 1610);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (921, '1.  전산등재 과정에서의 잘못 등으로 효력이 없음이 분명한 경우: 폐기', 1617);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (922, '2.  잘못된 계산이나 기재 등이 있음이 분명한 경우: 정정', 1617);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (923, '1.  개별 사건에 대해 전자적 송달 및 통지에 동의한 등록사용자', 1624);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (924, '2.  「형사소송법」 제60조에 따라 송달영수인으로 신고한 등록사용자', 1624);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (925, '3.  1년의 범위에서 일정한 기간을 정해 피의자ㆍ피고인ㆍ피해자ㆍ고소인ㆍ고발인ㆍ변호인 또는 제3조 각 호의 자가 될 것을 예정해 전자적 송달 및 통지에 동의한 등록사용자', 1624);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (926, '1.  법 제14조제1항제1호 또는 제2호의 경우: 전자문서를 전산정보처리시스템에 등재하고 그 전자문서를 송달ㆍ통지받을 형사사법업무 처리기관(그 소속 공무원이 송달ㆍ통지받는 경우를 포함한다)의 전산정보처리시스템으로 전송하는 방법', 1626);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (927, '2.  법 제14조제1항제3호의 경우: 전자문서를 전산정보처리시스템에 등재하고 그 전자문서를 송달ㆍ통지받을 등록사용자가 형사사법포털에 입력한 전자우편 및 문자전송 서비스를 이용해 보내는 방법(등록사용자가 요청한 경우에는 문자전송 서비스는 제외한다)', 1626);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (928, '1.  법 제14조제1항제1호 또는 제2호의 경우: 형사사법업무 처리기관의 전산정보처리시스템에 해당 전자문서가 전자적으로 기록된 때', 1628);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (929, '2.  법 제14조제1항제3호의 경우: 송달ㆍ통지를 받을 자가 전산정보시스템에 등재된 전자문서를 확인한 때', 1628);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (930, '1.  등록사용자가 사물을 변별하거나 의사를 결정할 능력이 없는 경우', 1630);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (931, '2.  등록사용자가 중대한 질병이나 부상 등으로 형사사법포털에 접속하기 어려운 경우', 1630);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (932, '1.  전산정보처리시스템 또는 정보통신망에 장애가 발생해 송달받을 자가 전산정보처리시스템에서 정상적으로 전자문서를 확인할 수 없는 경우', 1634);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (933, '2.  그 밖에 송달받을 자의 권익을 보호하기 위해 출력서면의 송달이 필요하다고 수사기관등이 인정하는 경우', 1634);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (934, '1.  법 제16조제1항에 따른 「형사소송법」의 각 규정에 따라 전자기록을 열람ㆍ등사 또는 복사하는 경우', 1637);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (935, '2.  「검사와 사법경찰관의 상호협력과 일반적 수사준칙에 관한 규정」 제69조에 따라 수사서류 등을 열람ㆍ복사하는 경우', 1637);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (936, '3.  「검사와 사법경찰관의 상호협력과 일반적 수사준칙에 관한 규정」 제42조제2항 후단에 따라 전자정보의 삭제ㆍ폐기 또는 반환 확인서를 교부받는 경우', 1637);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (937, '1.  변호인이 「형사소송법」 제243조의2제4항 및 「검사와 사법경찰관의 상호협력과 일반적 수사준칙에 관한 규정」 제14조제1항에 따라 피의자신문조서를 열람하는 경우', 1640);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (938, '2.  피고인이 「형사소송법」 제266조의3제1항 단서에 따라 공소제기된 사건에 관한 서류 또는 물건을 열람하는 경우', 1640);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (939, '1.  전산정보처리시스템(전자소송시스템을 포함한다) 또는 정보통신망에 장애가 있는 경우', 1647);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (940, '2.  피해자의 사생활 보호 또는 추가적인 피해 발생의 예방이 필요한 경우', 1647);
