INSERT INTO balaw.ho (id, content, hang_id) VALUES (1037, '1.  법 제3조ㆍ법 제4조제2항(미수범을 포함한다)ㆍ법 제5조제4항 또는 법 제8조에 따라 유죄판결을 받은 사람의 공범(법 제5조제4항에 따라 유죄판결을 받은 사람에 대응하여 법 제6조의 죄를 범한 사람을 포함한다. 이하 이 항에서 같다)이나 공범의 직계 존ㆍ비속, 형제자매, 배우자가 출자한 기업체로서 그 출자한 금액의 합계액이 발행주식 또는 출자금의 총액의 100분의 5 이상인 기업체', 1898);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1038, '2.  법 제3조ㆍ법 제4조제2항 (미수범을 포함한다) 법 제5조제4항 또는 법 제8조에 따라 유죄판결을 받은 사람의 공범이 그 범행 당시 임원 또는 과장급 이상의 간부직원으로 있었거나 임원 또는 과장급 이상의 간부직원으로 있는 기업체', 1898);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1039, '3.  법 제3조ㆍ법 제4조제2항(미수범을 포함한다)ㆍ법 제5조제4항 또는 법 제8조에 따라 유죄판결된 범죄행위로 인하여 재산상 이득을 취득한 기업체 또는 재산상 손해를 입은 기업체', 1898);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1040, '4.  법 제3조ㆍ법 제5조제4항 및 법 제8조에 따라 유죄판결을 받은 사람의 범죄행위로 인하여 재산상 이득을 취득한 제3자 또는 그 제3자의 직계 존ㆍ비속, 형제자매, 배우자가 출자한 기업체로서 그 출자한 금액의 합계액이 제1호에 규정된 기준 이상인 기업체', 1898);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1041, '5.  제4호에 따른 제3자가 범죄행위 당시 임원 또는 과장급 이상의 간부직원으로 있었거나 임원 또는 과장급 이상의 간부직원으로 있는 기업체', 1898);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1042, '6.  제1호부터 제5호까지의 어느 하나에 해당하는 기업체가 출자한 기업체로서 그 출자한 금액이 제1호에 규정된 기준 이상인 기업체', 1898);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1043, '1.  법 제14조제1항 단서 또는 같은 조 제2항 단서에 따른 취업 승인이나 허가등의 승인에 관한 사무', 1905);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1044, '2.  법 제14조제4항에 따른 해임이나 허가등의 취소 요구에 관한 사무', 1905);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1045, '3.  제1호 또는 제2호에 규정된 사무를 수행하기 위하여 필요한 사무', 1905);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1046, '1.  "수형인"이란 「형법」 제41조에 규정된 형을 받은 자를 말한다.', 1907);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1047, '2.  "수형인명부"란 자격정지 이상의 형을 받은 수형인을 기재한 명부로서 검찰청 및 군검찰부에서 관리하는 것을 말한다.', 1907);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1048, '3.  "수형인명표"란 자격정지 이상의 형을 받은 수형인을 기재한 명표로서 수형인의 등록기준지 시ㆍ구ㆍ읍ㆍ면 사무소에서 관리하는 것을 말한다.', 1907);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1049, '4.  "수사자료표"란 수사기관이 피의자의 지문을 채취하고 피의자의 인적사항과 죄명 등을 기재한 표(전산입력되어 관리되거나 자기테이프, 마이크로필름, 그 밖에 이와 유사한 매체에 기록ㆍ저장된 표를 포함한다)로서 경찰청에서 관리하는 것을 말한다.', 1907);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1050, '5.  "범죄경력자료"란 수사자료표 중 다음 각 목에 해당하는 사항에 관한 자료를 말한다.', 1907);
