INSERT INTO balaw.ho (id, content, hang_id) VALUES (1082, '4.  법원의 공소기각 결정이 확정된 경우', 1924);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1083, '5.  가정법원소년부 또는 지방법원소년부의 불처분 결정 또는 심리불개시 결정이 있는 경우', 1924);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1084, '1.  법정형(法定刑)이 사형, 무기징역, 무기금고, 장기(長期) 10년 이상의 징역ㆍ금고에 해당하는 죄: 10년', 1925);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1085, '2.  법정형이 장기 2년 이상의 징역ㆍ금고에 해당하는 죄: 5년', 1925);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1086, '3.  법정형이 장기 2년 미만의 징역ㆍ금고, 자격상실, 자격정지, 벌금, 구류 또는 과료에 해당하는 죄: 즉시 삭제. 다만, 제1항제1호의 불송치결정이 있는 경우는 6개월간 보존하고, 제1항제2호의 기소유예나 제1항제3호ㆍ제4호의 판결 또는 결정이 있는 경우는 5년간 보존한다.', 1925);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1087, '1.  제1항제1호의 불송치결정: 그 결정일부터 4개월', 1926);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1088, '2.  제1항제2호의 기소유예의 불기소처분: 그 처분일부터 3년', 1926);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1089, '3.  제1항제2호의 혐의없음, 공소권없음, 죄가안됨의 불기소처분: 그 처분 시까지', 1926);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1090, '4.  제1항제3호의 판결 또는 같은 항 제4호의 결정: 그 판결 또는 결정의 확정 시까지', 1926);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1091, '1.  전과기록 또는 수사경력자료를 손상시키거나 은닉(隱匿)하거나 그 밖의 방법으로 그 효용을 해친 행위', 1931);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1092, '2.  전과기록 또는 수사경력자료의 내용을 거짓으로 기재하거나 정당한 사유 없이 그 내용을 변경한 행위', 1931);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1093, '3.  전과기록 또는 수사경력자료에 의한 증명사항의 내용을 거짓으로 기재한 행위', 1931);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1094, '1.  손상, 은닉 또는 그 밖의 방법으로 그 효용을 해친 행위', 1932);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1095, '2.  그 내용을 거짓으로 기재하거나 변작(變作)한 행위', 1932);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1096, '1.  피의자의 성명, 국적, 주민등록번호, 외국인등록번호(피의자가 외국인인 경우로 한정한다), 여권번호(피의자의 주민등록번호 또는 외국인등록번호가 없는 경우로 한정한다) 등 인적 사항', 1936);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1097, '2.  죄명, 입건관서, 입건일자, 처분결과, 선고결과 등 수사경력 또는 범죄경력에 관한 사항', 1936);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1098, '1.  「형사소송법」 제197조제1항의 사법경찰관', 1940);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1099, '2.  「군사법원법」 제43조의 군사법경찰관', 1940);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1100, '3.  다른 법률에 따라 사법경찰관의 직무를 수행하는 사람', 1940);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1101, '1.  법 제6조제1항제5호ㆍ제6호 및 제8호의 경우에는 범죄경력자료와 수사 또는 재판 중에 있는 사건의 수사경력자료', 1946);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1102, '2.  법 제6조제1항제7호의 경우에는 범죄경력자료와 소년부송치ㆍ기소유예 또는 공소권없음으로 결정되거나 수사 또는 재판 중에 있는 사건의 수사경력자료', 1946);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1103, '3.  법 제6조제1항제9호의 경우에는 그 결격사유, 징계절차가 개시된 공무원의 구체적인 징계 사유 또는 지급제한사유 등(이하 "결격사유등"이라 한다)을 확인하기 위하여 필요한 자료로 하되, 결격사유등에 해당하는 범죄경력을 특정하기 어려운 때에는 다음 각 목의 자료. 다만, 징계절차가 개시된 공무원의 구체적인 징계 사유를 확인하기 위한 경우에는 범죄경력자료에 한정한다.', 1946);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1104, '1.  법 제7조 또는 「형법」 제81조에 따라 실효된 형', 1950);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1105, '2.  사면 또는 복권이 있은 형', 1950);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1106, '3.  결정이 있은 때부터 3년이 지난 「소년법」상의 소년부송치 및 보호처분', 1950);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1107, '4.  「형법」 제60조에 따라 면소된 것으로 간주된 선고유예', 1950);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1108, '5.  「형법」 제65조에 따라 선고의 효력을 잃은 집행유예', 1950);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1109, '1.  법 제7조 또는 「형법」 제81조에 따라 실효된 형', 1951);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1110, '2.  「사면법」에 따라 형 선고의 효력을 상실하게 하는 사면 또는 복권을 받은 형', 1951);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1111, '3.  결정이 있은 때부터 3년이 지난 「소년법」상의 소년부송치 및 보호처분', 1951);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1112, '4.  「형법」 제60조에 따라 면소된 것으로 간주된 선고유예', 1951);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1113, '5.  「형법」 제65조에 따라 선고의 효력을 잃은 집행유예', 1951);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1114, '1.  법 제3조ㆍ제4조 및 제8조에 따른 수형인명부 및 수형인명표에 관한 사무', 1956);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1115, '2.  법 제5조 및 제5조의2에 따른 수사자료표에 관한 사무', 1956);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1116, '3.  법 제6조에 따른 범죄경력조회 및 수사경력조회와 그 회보에 관한 사무', 1956);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1117, '4.  법 제8조의2에 따른 수사경력자료의 정리에 관한 사무', 1956);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1118, '5.  법 제8조의3에 따른 전과기록이나 수사경력자료의 제출 및 시정에 관한 사무', 1956);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1119, '1.  "부패범죄"란 불법 또는 부당한 방법으로 물질적ㆍ사회적 이득을 얻거나 다른 사람으로 하여금 얻도록 도울 목적으로 범한 죄로서 별표에 규정된 죄를 말한다.', 1967);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1120, '2.  "부패재산"이란 범죄수익 및 범죄수익에서 유래한 재산을 말한다.', 1967);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1121, '3.  "범죄피해재산"이란 별표에 규정된 죄 가운데 다음 각 목의 어느 하나에 해당하는 죄의 범죄행위에 의하여 그 피해자로부터 취득한 재산 또는 그 재산의 보유ㆍ처분에 의하여 얻은 재산을 말한다.', 1967);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1122, '4.  "집행재산등"이란 다음 각 목의 어느 하나에 해당하는 경우 그 공조실시에 관계된 재산 또는 가액을 말한다.', 1967);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1123, '5.  "요청국"이란 부패범죄에 해당하는 행위에 대한 형사사건과 관련하여 대한민국에 대하여 몰수 또는 추징의 확정재판의 집행이나 몰수 또는 추징을 위한 재산보존의 공조를 요청하는 국가를 말한다.', 1967);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1124, '1.  공조요청의 대상이 되는 범죄와 관련된 행위가 대한민국 내에서 행하여지고 그 행위가 대한민국의 법령에 따라 부패범죄에 해당하지 아니한다고 인정되는 경우', 1978);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1125, '2.  대한민국이 행하는 같은 종류의 공조요청에 응한다는 취지의 요청국의 보증이 없는 경우', 1978);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1126, '3.  요청국이 집행재산등의 원소유자, 범죄피해자 또는 정당한 권리있는 사람에게 집행재산등을 양도할 것이라는 보증을 하지 아니하는 경우', 1978);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1127, '4.  「마약류 불법거래방지에 관한 특례법」 제64조제1항 각 호의 어느 하나에 해당하는 경우', 1978);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1128, '1.  집행재산등의 반환요청에 응하여야 할 상당한 개연성이 있다고 판단되는 경우', 1981);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1129, '2.  요청국으로부터 반환요청이 있을 것으로 예상되는 경우', 1981);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1130, '1.  "피해자등"이란 「부패재산의 몰수 및 회복에 관한 특례법」(이하 "법"이라 한다) 제6조제1항에 따른 범죄피해재산의 몰수ㆍ추징의 원인이 되는 범죄로 인해 재산상 손해를 입은 자와 그 포괄승계인을 말한다.', 1997);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1131, '2.  "피해인정재산"이란 범죄피해재산에서 다음 각 목의 재산을 제외한 재산으로서 검사가 그 제외한 범위를 확인한 재산을 말한다.', 1997);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1132, '3.  "회복대상재산"이란 법 제6조제1항에 따라 몰수ㆍ추징된 범죄피해재산으로서 환부의 대상이 되는 재산(법 제17조에 따라 외국으로부터 환수받은 집행재산등을 포함한다)을 말한다.', 1997);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1133, '4.  "피해회복금"이란 회복대상재산에서 통지ㆍ공고 등 법무부령으로 정하는 환부절차에 드는 비용(이하 "비용"이라 한다)을 빼고 피해인정재산의 범위에서 피해자등에게 지급하는 금전을 말한다.', 1997);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1134, '1.  회복대상재산을 보관하고 있는 검사 및 그가 소속된 관할 검찰청', 2001);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1135, '2.  회복대상재산의 명세 및 그 가액', 2001);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1136, '3.  회복대상재산과 관련된 몰수재판 또는 추징재판을 한 법원, 재판 연월일 및 확정 연월일, 사건번호, 재판을 받은 피고인의 성명, 그 몰수 또는 추징의 이유가 된 범죄사실의 요지 및 죄명', 2001);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1137, '4.  제6조제1항에 따라 환부를 청구해야 하는 기간', 2001);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1138, '1.  청구인이 피해자등이라는 사실', 2004);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1139, '2.  반환을 청구하는 범죄피해재산 및 그 가액', 2004);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1140, '3.  피해자등이 범죄피해재산 중 반환받거나 범죄피해재산에 관하여 손해배상을 받은 때에는 그 재산이나 가액', 2004);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1141, '4.  그 밖에 범죄피해재산의 환부청구를 위해 필요한 사항으로서 법무부령으로 정하는 사항', 2004);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1142, '1.  청구가 이유 있다고 인정하는 경우: 청구를 인용(認容)하여 회복대상재산을 환부한다는 결정', 2006);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1143, '2.  청구가 이유 없다고 인정하는 경우: 청구를 기각한다는 결정', 2006);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1144, '3.  청구가 일부만 이유 있다고 인정하는 경우: 청구의 일부를 인용하여 회복대상재산의 일부를 환부하고, 청구의 일부를 기각한다는 결정', 2006);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1145, '4.  제6조제1항에 따른 청구기간이 지난 후에 청구한 경우: 청구를 각하한다는 결정', 2006);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1146, '1.  회복대상재산이 금전 외의 재산인 경우: 그 재산을 환부', 2009);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1147, '2.  회복대상재산이 금전이거나 제3조제3항에 따라 회복대상재산을 환가 또는 징수한 경우: 피해회복금을 환부', 2009);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1148, '1.  이의신청이 이유 있다고 인정하는 경우: 이의신청을 인용하여 회복대상재산을 환부한다는 결정', 2013);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1149, '2.  이의신청이 이유 없다고 인정하는 경우: 이의신청을 기각한다는 결정', 2013);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1150, '3.  이의신청의 일부만 이유 있다고 인정하는 경우: 이의신청의 일부를 인용하여 회복대상재산의 일부를 환부하고, 일부는 기각한다는 결정', 2013);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1151, '4.  제1항에 따른 이의신청 기간이 지난 후에 이의신청을 한 경우: 이의신청을 각하한다는 결정', 2013);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1152, '1.  검사가 제6조에 따른 환부청구에 관하여 필요하다고 판단하여 심의회에 심의를 요청한 사항', 2016);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1153, '2.  제10조에 따른 이의신청', 2016);
