INSERT INTO balaw.ho (id, content, hang_id) VALUES (1336, '2.  보류결정전의 새로운 범죄사실이 발견되었거나 보류결정을 한 범행의 수사에 있어서 허위진술을 한 사실이 발견된 때', 2219);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1337, '3.  반국가적 집단을 찬양ㆍ고무하거나, 이에 동조 기타의 방법으로서 그 집단을 이롭게 하는 언동을 한 때', 2219);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1338, '4.  반국가행위자와 과거 반국적 노선에서 동조하던 자를 은폐하거나 고발하지 아니한 때', 2219);
