INSERT INTO balaw.ho (id, content, hang_id) VALUES (1389, '6.  해당 사업장에서 최근 5년 내 중대산업재해의 발생 여부', 2244);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1390, '1.  명칭', 2250);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1391, '2.  사무소의 소재지', 2250);
