INSERT INTO balaw.ho (id, content, hang_id) VALUES (1394, '2.  이사회의 운영과 그 업무에 관한 사항을 감사하는 일', 2257);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1395, '3.  제1호 또는 제2호의 감사 결과 부정 또는 부당한 점을 발견한 경우 이사회와 법무부장관에게 보고하는 일', 2257);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1396, '4.  제3호의 보고를 하기 위하여 이사회의 소집을 요구하는 일', 2257);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1397, '5.  교정법인의 재산 상황 또는 이사회의 운영과 그 업무에 관한 사항에 대하여 대표자 또는 이사에게 의견을 진술하는 일', 2257);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1398, '1.  교정법인의 예산, 결산, 차입금 및 재산의 취득ㆍ처분과 관리에 관한 사항', 2259);
