INSERT INTO balaw.ho (id, content, hang_id) VALUES (1498, '1.  피의자, 피해자, 참고인 등 사건관계인이 직접 작성하는 문서', 2339);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1499, '2.  시스템에 작성 기능이 구현되어 있지 아니한 문서', 2339);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1500, '3.  시스템을 이용할 수 없는 시간 또는 장소에서 불가피하게 작성하여야 하거나 시스템 장애 또는 전산망 오류 등으로 시스템을 이용할 수 없는 상황에서 불가피하게 작성하여야 하는 문서', 2339);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1501, '1.  송신 대상 형사사법정보는 전자문서 출력물의 내용과 동일할 것', 2340);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1502, '2.  전자문서 출력물의 내용과 송신 대상 형사사법정보가 동일하다는 사실을 추정할 수 있도록 전자문서 출력물에는 출력기관, 출력일, 면수 및 총면수, 문서의 고유식별번호 등이 표시될 것', 2340);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1503, '1.  형사사법업무 처리기관 간에 송신ㆍ수신되는 정보의 세부적인 사항은 제5조에 따른 각 기관의 운영세칙에 명시할 것', 2342);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1504, '2.  형사사법업무 처리기관은 유통문서의 내용과 송신 정보가 정확히 일치되도록 노력하여야 하며, 일치하지 않은 정보가 송신된 경우에는 일치하는 정보를 다시 송신할 것', 2342);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1505, '3.  형사사법업무 처리기관은 다른 형사사법업무 처리기관의 시스템에 영향을 미칠 수 있는 시스템상의 장애가 발생한 경우에는 즉시 그 사실을 통보하고, 시스템 개발 등의 사유로 시스템 가동을 일시 정지할 필요가 있는 경우에는 미리 그 사실을 통보하여 다른 형사사법업무 처리기관의 업무 처리에 지장이 없도록 할 것', 2342);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1506, '1.  공통시스템 관련 하드웨어, 시스템소프트웨어, 응용소프트웨어 등에 대한 운영ㆍ관리 및 정보보호에 관한 업무', 2347);
