INSERT INTO balaw.ho (id, content, hang_id) VALUES (1563, '2.  "국제형사재판소"란 1998년 7월 17일 이탈리아 로마에서 개최된 국제연합 전권외교회의에서 채택되어 2002년 7월 1일 발효된 「국제형사재판소에 관한 로마규정」(이하 "국제형사재판소규정"이라 한다)에 따라 설립된 재판소를 말한다.', 2425);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1564, '3.  "제네바협약"이란 「육전에 있어서의 군대의 부상자 및 병자의 상태 개선에 관한 1949년 8월 12일자 제네바협약」(제1협약), 「해상에 있어서의 군대의 부상자, 병자 및 조난자의 상태 개선에 관한 1949년 8월 12일자 제네바협약」(제2협약), 「포로의 대우에 관한 1949년 8월 12일자 제네바협약」(제3협약) 및 「전시에 있어서의 민간인의 보호에 관한 1949년 8월 12일자 제네바협약」(제4협약)을 말한다.', 2425);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1565, '4.  "외국인"이란 대한민국의 국적을 가지지 아니한 사람을 말한다.', 2425);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1566, '5.  "노예화"란 사람에 대한 소유권에 부속되는 모든 권한의 행사를 말하며, 사람 특히 여성과 아동을 거래하는 과정에서 그러한 권한을 행사하는 것을 포함한다.', 2425);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1567, '6.  "강제임신"이란 주민의 민족적 구성에 영향을 미치거나 다른 중대한 국제법 위반을 실행할 의도로 강제로 임신시키거나 강제로 임신하게 된 여성을 정당한 사유 없이 불법적으로 감금하여 그 임신 상태를 유지하도록 하는 것을 말한다.', 2425);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1568, '7.  "인도(人道)에 관한 국제법규에 따라 보호되는 사람"이란 다음 각 목의 어느 하나에 해당하는 사람을 말한다.', 2425);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1569, '1.  제1항의 집단의 구성원에 대하여 중대한 신체적 또는 정신적 위해(危害)를 끼치는 행위', 2434);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1570, '2.  신체의 파괴를 불러일으키기 위하여 계획된 생활조건을 제1항의 집단에 고의적으로 부과하는 행위', 2434);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1571, '3.  제1항의 집단 내 출생을 방지하기 위한 조치를 부과하는 행위', 2434);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1572, '4.  제1항의 집단의 아동을 강제로 다른 집단으로 이주하도록 하는 행위', 2434);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1573, '1.  식량과 의약품에 대한 주민의 접근을 박탈하는 등 일부 주민의 말살을 불러올 생활조건을 고의적으로 부과하는 행위', 2439);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1574, '2.  사람을 노예화하는 행위', 2439);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1575, '3.  국제법규를 위반하여 강제로 주민을 그 적법한 주거지에서 추방하거나 이주하도록 하는 행위', 2439);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1576, '4.  국제법규를 위반하여 사람을 감금하거나 그 밖의 방법으로 신체적 자유를 박탈하는 행위', 2439);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1577, '5.  자기의 구금 또는 통제하에 있는 사람에게 정당한 이유 없이 중대한 신체적 또는 정신적 고통을 주어 고문하는 행위', 2439);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1578, '6.  강간, 성적 노예화, 강제매춘, 강제임신, 강제불임 또는 이와 유사한 중대한 성적 폭력 행위', 2439);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1579, '7.  정치적ㆍ인종적ㆍ국민적ㆍ민족적ㆍ문화적ㆍ종교적 사유, 성별 또는 그 밖의 국제법규에 따라 인정되지 아니하는 사유로 집단 또는 집합체 구성원의 기본적 인권을 박탈하거나 제한하는 행위', 2439);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1580, '8.  사람을 장기간 법의 보호로부터 배제시킬 목적으로 국가 또는 정치단체의 허가ㆍ지원 또는 묵인하에 이루어지는 다음 각 목의 어느 하나에 해당하는 행위', 2439);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1581, '9.  제1호부터 제8호까지의 행위 외의 방법으로 사람의 신체와 정신에 중대한 고통이나 손상을 주는 행위', 2439);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1582, '1.  인도에 관한 국제법규에 따라 보호되는 사람을 인질로 잡는 행위', 2444);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1583, '2.  인도에 관한 국제법규에 따라 보호되는 사람에게 고문이나 신체의 절단 등으로 신체 또는 건강에 중대한 고통이나 손상을 주는 행위', 2444);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1584, '3.  인도에 관한 국제법규에 따라 보호되는 사람을 강간, 강제매춘, 성적 노예화, 강제임신 또는 강제불임의 대상으로 삼는 행위', 2444);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1585, '1.  인도에 관한 국제법규에 따라 보호되는 사람을 국제법규를 위반하여 주거지로부터 추방하거나 이송하는 행위', 2445);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1586, '2.  공정한 정식재판에 의하지 아니하고 인도에 관한 국제법규에 따라 보호되는 사람에게 형을 부과하거나 집행하는 행위', 2445);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1587, '3.  치료의 목적 등 정당한 사유 없이 인도에 관한 국제법규에 따라 보호되는 사람을 그의 자발적이고 명시적인 사전 동의 없이 생명ㆍ신체에 중대한 위해를 끼칠 수 있는 의학적ㆍ과학적 실험의 대상으로 삼는 행위', 2445);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1588, '4.  조건 없이 항복하거나 전투능력을 잃은 군대의 구성원이나 전투원에게 상해(傷害)를 입히는 행위', 2445);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1589, '5.  15세 미만인 사람을 군대 또는 무장집단에 징집 또는 모병의 방법으로 참여하도록 하거나 적대행위에 참여하도록 하는 행위', 2445);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1590, '1.  정당한 사유 없이 인도에 관한 국제법규에 따라 보호되는 사람을 감금하는 행위', 2447);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1591, '2.  자국의 주민 일부를 점령지역으로 이주시키는 행위', 2447);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1592, '3.  인도에 관한 국제법규에 따라 보호되는 사람으로 하여금 강제로 적국의 군대에 복무하도록 하는 행위', 2447);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1593, '4.  적국의 국민을 강제로 자신의 국가에 대한 전쟁 수행에 참여하도록 하는 행위', 2447);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1594, '1.  국제연합헌장에 따른 인도적 원조나 평화유지임무와 관련된 요원ㆍ시설ㆍ자재ㆍ부대 또는 차량이 무력충돌에 관한 국제법에 따라 민간인 또는 민간 대상물에 부여되는 보호를 받을 자격이 있는데도 그들을 고의적으로 공격하는 행위', 2453);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1595, '2.  제네바협약에 규정된 식별표장(識別表裝)을 정당하게 사용하는 건물, 장비, 의무부대, 의무부대의 수송수단 또는 요원을 공격하는 행위', 2453);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1596, '1.  사람을 사망에 이르게 한 사람은 사형, 무기 또는 7년 이상의 징역에 처한다.', 2454);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1597, '2.  사람의 신체에 중대한 손상을 입힌 사람은 무기 또는 5년 이상의 징역에 처한다.', 2454);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1598, '1.  민간인 주민을 공격의 대상으로 삼거나 적대행위에 직접 참여하지 아니한 민간인 주민을 공격의 대상으로 삼는 행위', 2456);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1599, '2.  군사목표물이 아닌 민간 대상물로서 종교ㆍ교육ㆍ예술ㆍ과학 또는 자선 목적의 건물, 역사적 기념물, 병원, 병자 및 부상자를 수용하는 장소, 무방비 상태의 마을ㆍ거주지ㆍ건물 또는 위험한 물리력을 포함하고 있는 댐 등 시설물을 공격하는 행위', 2456);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1600, '3.  군사작전상 필요에 비하여 지나치게 민간인의 신체ㆍ생명 또는 민간 대상물에 중대한 위해를 끼치는 것이 명백한 공격 행위', 2456);
