INSERT INTO balaw.ho (id, content, hang_id) VALUES (1602, '5.  인도에 관한 국제법규를 위반하여 민간인들의 생존에 필수적인 물품을 박탈하거나 그 물품의 공급을 방해함으로써 기아(飢餓)를 전투수단으로 사용하는 행위', 2456);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1603, '6.  군대의 지휘관으로서 예외 없이 적군을 살해할 것을 협박하거나 지시하는 행위', 2456);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (1604, '7.  국제법상 금지되는 배신행위로 적군 또는 상대방 전투원을 살해하거나 상해를 입히는 행위', 2456);
