INSERT INTO balaw.ho (id, content, hang_id) VALUES (2062, '1.  19세 미만의 사람을 대상으로 성폭력범죄를 저지른 사람: 제1항제1호 및 제3호의 준수사항을 포함할 것. 다만, 제1항제1호의 준수사항을 부과하여서는 아니 될 특별한 사정이 있다고 판단하는 경우에는 해당 준수사항을 포함하지 아니할 수 있다.', 3542);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2063, '2.  스토킹범죄를 저지른 사람: 제1항제3호의 준수사항을 포함할 것', 3542);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2064, '1.  부착명령의 원인이 된 특정범죄사건이 아닌 다른 범죄사건으로 형이나 치료감호의 집행이 계속될 경우에는 부착명령의 원인이 된 특정범죄사건이 아닌 다른 범죄사건에 대한 형의 집행이 종료되거나 면제ㆍ가석방 되는 날 또는 치료감호의 집행이 종료ㆍ가종료 되는 날부터 집행한다.', 3547);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2065, '2.  피부착명령자가 부착명령 판결 확정 시 석방된 상태이고 미결구금일수 산입 등의 사유로 이미 형의 집행이 종료된 경우에는 부착명령 판결 확정일부터 부착명령을 집행한다.', 3547);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2066, '1.  부착명령의 집행 중 다른 죄를 범하여 구속영장의 집행을 받아 구금된 때', 3552);
