INSERT INTO balaw.ho (id, content, hang_id) VALUES (2073, '2.  제6항제2호의 경우에는 그 형의 집행이 종료되거나 면제된 후 또는 가석방된 때부터 그 잔여기간을 집행한다.', 3554);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2074, '3.  제6항제3호의 경우에는 그 형이나 치료감호의 집행이 종료되거나 면제된 후 그 잔여기간을 집행한다.', 3554);
