INSERT INTO balaw.ho (id, content, hang_id) VALUES (2077, '3.  정당한 사유 없이 제14조제3항을 위반하여 허가를 받지 아니하고 주거 이전ㆍ국내여행 또는 출국을 하거나, 거짓으로 허가를 받은 경우', 3559);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2078, '4.  정당한 사유 없이 제14조제3항에 따른 출국허가 기간까지 입국하지 아니한 경우', 3559);
