INSERT INTO balaw.ho (id, content, hang_id) VALUES (2083, '1.  부착명령과 함께 선고된 형이 「형법」 제81조에 따라 실효된 때', 3569);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2084, '2.  부착명령과 함께 선고된 형이 사면으로 인하여 그 효력을 상실한 때', 3569);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2085, '3.  전자장치 부착이 종료된 자가 자격정지 이상의 형 또는 이 법에 따른 전자장치 부착을 받음이 없이 전자장치 부착을 종료한 날부터 5년이 경과한 때', 3569);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2086, '1.  부착명령기간이 경과한 때', 3591);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2087, '2.  부착명령과 함께 선고한 형이 사면되어 그 선고의 효력을 상실하게 된 때', 3591);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2088, '3.  삭제 <2008.6.13>', 3591);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2089, '4.  부착명령이 임시해제된 자가 그 임시해제가 취소됨이 없이 잔여 부착명령기간을 경과한 때', 3591);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2090, '1.  성폭력범죄를 저지른 사람으로서 성폭력범죄를 다시 범할 위험성이 있다고 인정되는 사람', 3594);
