INSERT INTO balaw.ho (id, content, hang_id) VALUES (2097, '1.  가석방되는 날', 3613);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2098, '2.  가종료 또는 치료위탁되거나 가출소되는 날. 다만, 제23조제1항에 따른 피치료감호자에게 치료감호와 병과된 형의 잔여 형기가 있거나 치료감호의 원인이 된 특정범죄사건이 아닌 다른 범죄사건으로 인하여 집행할 형이 있는 경우에는 해당 형의 집행이 종료ㆍ면제되거나 가석방되는 날 부착한다.', 3613);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2099, '1.  가석방 기간이 경과하거나 가석방이 실효 또는 취소된 때', 3615);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2100, '2.  가종료자등의 부착기간이 경과하거나 보호관찰이 종료된 때', 3615);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2101, '3.  가석방된 형이 사면되어 형의 선고의 효력을 상실하게 된 때', 3615);
