INSERT INTO balaw.ho (id, content, hang_id) VALUES (2108, '2.  보석이 취소된 경우', 3634);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2109, '3.  「형사소송법」 제102조에 따라 보석조건이 변경되어 전자장치를 부착할 필요가 없게 되는 경우', 3634);
