INSERT INTO balaw.ho (id, content, hang_id) VALUES (2111, '2.  주민등록번호', 3637);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2112, '3.  주소 및 실제 거주지', 3637);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2113, '4.  직장 소재지', 3637);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2114, '5.  전화번호', 3637);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2115, '6.  그 밖에 대통령령으로 정하는 피해자의 보호를 위하여 필요한 사항', 3637);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2116, '1.  정당한 사유 없이 제2항에 따라 법원이 지정한 일시까지 보호관찰소에 출석하여 신고하지 아니하거나 전자장치 부착을 거부하는 경우', 3638);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2117, '2.  잠정조치 기간 중 「스토킹범죄의 처벌 등에 관한 법률」 제9조제1항제2호를 위반하였거나 위반할 우려가 있는 경우', 3638);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2118, '3.  잠정조치 기간 중 「스토킹범죄의 처벌 등에 관한 법률」 제9조제4항을 위반하였거나 위반하였다고 의심할 상당한 이유가 있는 경우', 3638);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2119, '4.  그 밖에 잠정조치의 이행 및 피해자의 보호를 위하여 적절한 조치가 필요한 경우로서 대통령령으로 정하는 사유가 있는 경우', 3638);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2120, '1.  잠정조치의 기간이 경과한 때', 3643);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2121, '2.  잠정조치가 변경 또는 취소된 때', 3643);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2122, '3.  잠정조치가 효력을 상실한 때', 3643);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2123, '1.  「스토킹범죄의 처벌 등에 관한 법률」 제2조제2호에 따른 스토킹범죄 혐의에 대한 수사 또는 재판자료로 사용하는 경우', 3645);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2124, '2.  「스토킹범죄의 처벌 등에 관한 법률」 제9조제1항제2호 및 제3호의2에 따른 잠정조치 이행 여부를 확인하기 위하여 사용하는 경우', 3645);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2125, '3.  「스토킹범죄의 처벌 등에 관한 법률」 제11조에 따른 잠정조치의 연장ㆍ변경ㆍ취소의 청구 또는 그 신청을 위하여 사용하는 경우', 3645);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2126, '4.  「스토킹범죄의 처벌 등에 관한 법률」 제20조제1항제1호 및 같은 조 제2항에 해당하는 범죄 혐의에 대한 수사를 위하여 사용하는 경우', 3645);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2127, '1.  잠정조치가 효력을 상실한 때', 3647);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2128, '2.  잠정조치의 원인이 되는 스토킹범죄사건에 대해 법원의 무죄, 면소, 공소기각 판결 또는 공소기각 결정이 확정된 때', 3647);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2129, '3.  잠정조치 집행을 종료한 날부터 5년이 경과한 때', 3647);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2130, '1.  피부착자가 제14조제1항을 위반하여 전자장치를 신체로부터 분리하거나 손상하는 등 그 효용을 해한 기간', 3649);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2131, '2.  피부착자의 치료, 출국 또는 그 밖의 적법한 사유로 전자장치가 신체로부터 일시적으로 분리된 후 해당 분리사유가 해소된 날부터 정당한 사유 없이 전자장치를 부착하지 아니한 기간', 3649);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2132, '1.  부착명령 및 보호관찰명령을 청구하기 위하여 필요한 피의자에 대한 조사', 3650);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2133, '2.  부착명령 및 보호관찰명령의 집행', 3650);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2134, '3.  피부착자 및 보호관찰대상자의 재범방지와 건전한 사회복귀를 위한 치료 등 필요한 조치의 부과', 3650);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2135, '4.  그 밖에 피부착자 및 보호관찰대상자의 「보호관찰 등에 관한 법률」 등에 따른 준수사항 이행 여부 확인 등 피부착자 및 보호관찰대상자에 대한 지도ㆍ감독 및 원호', 3650);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2136, '1.  휴대용 추적장치: 전자장치가 부착된 사람(이하 "피부착자"라 한다)이 휴대하는 것으로서 피부착자의 위치를 확인하는 장치', 3663);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2137, '2.  재택(在宅) 감독장치: 피부착자의 주거지에 설치하여 피부착자의 위치를 확인하는 장치', 3663);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2138, '3.  부착장치: 피부착자의 신체에 부착하는 장치로서, 휴대용 추적장치와 재택 감독장치에 전자파를 송신하거나 피부착자의 위치를 확인하는 장치', 3663);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2139, '1.  휴대용 추적장치는 피부착명령자가 휴대할 수 있도록 교부한다. 다만, 부착장치에 피부착자의 위치를 확인하는 기능이 있는 경우에는 교부하지 아니한다.', 3675);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2140, '2.  부착장치는 피부착명령자의 발목에 부착한다. 다만, 발목에 부착할 수 없는 특별한 사유가 있으면 다른 신체 부위에 부착할 수 있다.', 3675);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2141, '3.  재택 감독장치는 피부착명령자의 석방 후 지체 없이 피부착명령자의 주거지에 고정하여 설치한다. 다만, 피부착명령자의 주거가 일정하지 아니하거나 그 밖에 재택 감독장치를 설치하기 어려운 사정이 있는 경우에는 설치하지 아니할 수 있다.', 3675);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2142, '1.  전자장치의 기능이 정상적으로 유지될 수 있도록 전자장치를 충전, 휴대 또는 관리할 것', 3685);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2143, '2.  전자장치가 정상적으로 작동하지 아니하는 경우 지체 없이 그 사실을 보호관찰관에게 알릴 것', 3685);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2144, '3.  전자장치의 기능 유지를 위한 보호관찰관의 정당한 지시에 따를 것', 3685);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2145, '1.  「출입국관리법」 제4조 등 다른 법률의 규정에 따라 출국이 금지된 경우', 3689);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2146, '2.  출국의 목적에 관한 소명자료를 제출하지 아니하는 경우', 3689);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2147, '3.  부착명령 집행기간 중 정당한 사유 없이 출국 허가기간 내에 귀국하지 아니하였거나 허가를 받지 아니하고 출국한 전력(前歷)이 있는 경우', 3689);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2148, '1.  피부착자 또는 피부착명령자의 성명, 주민등록번호, 직업 및 주거', 3695);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2149, '2.  신청의 취지', 3695);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2150, '3.  부착기간의 연장 또는 준수사항의 부과ㆍ추가ㆍ변경ㆍ삭제가 필요한 사유', 3695);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2151, '1.  「정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률」 제3조제4호에 따른 정신건강증진시설', 3698);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2152, '2.  「성폭력방지 및 피해자보호 등에 관한 법률」 제10조에 따른 성폭력피해상담소, 같은 법 제27조에 따른 전담의료기관', 3698);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2153, '3.  특정 범죄자를 치료하고 특정 범죄자 교정프로그램을 개발ㆍ실시한 경험이 있는 민간 단체 또는 기관', 3698);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2154, '1.  피부착자의 인적사항, 긴급한 사유, 수신자료 제공기관, 요청사유 및 필요한 자료의 범위를 적은 긴급 열람ㆍ조회 요청서', 3706);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2155, '2.  자신의 신분을 표시할 수 있는 증표', 3706);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2156, '1.  성명', 3718);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2157, '2.  주민등록번호. 다만, 외국인 및 「재외동포의 출입국과 법적 지위에 관한 법률」 제2조제1호에 따른 재외국민(주민등록을 하지 아니한 경우만 해당하며, 이하 이 호에서 "재외국민"이라 한다)과 같은 조 제2호에 따른 외국국적동포(이하 "외국국적동포"라 한다)에 대해서는 다음 각 목의 구분에 따라 표기한다.', 3718);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2158, '3.  주소 및 실제 거주지', 3718);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2159, '4.  연락처', 3718);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2160, '5.  사진', 3718);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2161, '6.  죄명 및 판결ㆍ결정 내용', 3718);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2162, '7.  전자장치 부착기간(법 제14조의2에 따라 부착기간이 연장된 경우에는 그 연장된 기간)', 3718);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2163, '8.  직업', 3718);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2164, '9.  그 밖에 보호관찰소의 장이 범죄예방 및 수사에 필요하다고 인정하는 사항', 3718);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2165, '1.  제1항 각 호의 사항', 3719);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2166, '2.  피부착자가 저지른 범죄 또는 저지른 것으로 의심되는 범죄사건의 발생일시, 장소 및 범행내용', 3719);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2167, '1.  피부착자의 성명 및 주민등록번호', 3720);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2168, '2.  피부착자의 범죄사실', 3720);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2169, '3.  피부착자의 체포 또는 구속 일시 및 장소', 3720);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2170, '1.  보호관찰대상자의 성명, 주민등록번호, 직업 및 주거', 3733);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2171, '2.  신청의 취지', 3733);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2172, '3.  보호관찰 기간의 연장 또는 준수사항의 추가ㆍ변경ㆍ삭제가 필요한 사유', 3733);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2173, '1.  성명', 3736);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2174, '2.  주민등록번호', 3736);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2175, '3.  죄명', 3736);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2176, '4.  전체 형명 및 형기', 3736);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2177, '5.  최초 형기 및 최종 형기의 기산일', 3736);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2178, '6.  최종 형기종료일', 3736);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2179, '7.  처우등급(「형의 집행 및 수용자의 처우에 관한 법률 시행령」 제84조제2항에 따른 처우등급 중 도주 등의 위험성에 따라 구분한 처우등급을 말한다) 및 재범위험에 관한 사항', 3736);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2180, '1.  전자장치의 효용 유지를 위해 필요한 다음 각 목에 따른 의무 사항', 3750);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2181, '2.  법 제31조의3제3항에 따라 보호관찰관이 전자장치 보석피고인의 보석조건 이행 여부를 확인하기 위해 필요한 조치를 할 수 있다는 것', 3750);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2182, '3.  법원이 정한 보석조건을 위반한 경우 「형사소송법」 제102조제2항제5호에 따라 보석이 취소될 수 있다는 것', 3750);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2183, '4.  그 밖에 법원이 정한 보석조건의 이행에 필요한 사항', 3750);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2184, '1.  부착장치는 전자장치 보석피고인의 발목 또는 손목에 부착한다. 다만, 발목 또는 손목에 부착할 수 없는 특별한 사유가 있으면 다른 신체 부위에 부착할 수 있다.', 3751);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2185, '2.  재택 감독장치는 전자장치 보석피고인이 제23조의4에 따라 보호관찰소에 신고한 날 해당 피고인의 주거지에 고정하여 설치한다. 다만, 전자장치 보석피고인의 주거가 일정하지 않거나 그 밖에 재택 감독장치를 설치하기 어려운 사정이 있는 경우에는 설치하지 않을 수 있다.', 3751);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2186, '1.  정당한 사유 없이 법 제31조의3제2항에 따라 법원이 지정한 일시까지 보호관찰소에 출석하여 신고하지 않은 경우', 3755);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2187, '2.  전자장치 부착을 거부하는 경우', 3755);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2188, '3.  전자장치의 효용 유지를 위해 필요한 보호관찰관의 정당한 지시에 따르지 않는 경우', 3755);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2189, '4.  「형사소송법」에 따른 다른 보석조건을 위반하거나 위반 사실의 확인을 위해 필요한 보호관찰관의 정당한 지시에 따르지 않는 경우', 3755);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2190, '5.  전자장치를 신체에서 임의로 분리ㆍ손상, 전파 방해 또는 수신자료의 변조를 하는 경우', 3755);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2191, '6.  소재를 알 수 없는 경우', 3755);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2192, '1.  「스토킹범죄의 처벌 등에 관한 법률」 제9조제1항제3호의2에 따른 잠정조치 결정을 받은 스토킹행위자(이하 이 장에서 "전자장치 스토킹행위자"라 한다)의 사건 수사를 관할하는 경찰관서(이하 이 장에서 "관할경찰관서"라 한다)의 장', 3757);
