INSERT INTO balaw.ho (id, content, hang_id) VALUES (2598, '1.  혐의 내용 및 동기, 진정인 또는 피해자와의 관계 등에 비추어 통지로 인해 진정인 또는 피해자의 생명ㆍ신체ㆍ명예 등에 위해(危害) 또는 불이익이 우려되는 경우', 4529);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2599, '2.  사안의 경중 및 경위, 진정인 또는 피해자의 의사, 피진정인ㆍ피혐의자와의 관계, 분쟁의 종국적 해결에 미치는 영향 등을 고려하여 통지하지 않는 것이 타당하다고 인정되는 경우', 4529);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2600, '1.  고소인 또는 고발인의 진술이나 고소장 또는 고발장에 따른 내용이 불분명하거나 구체적 사실이 적시되어 있지 않은 경우', 4531);
