INSERT INTO balaw.ho (id, content, hang_id) VALUES (2605, '2.  변사자의 소지품이나 그 밖에 변사자가 남겨 놓은 물건이 수사에 필요하다고 인정되는 경우에는 이를 보존하는 데 유의할 것', 4550);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2606, '3.  검시하는 경우에는 잠재지문 및 변사자의 지문 채취에 유의할 것', 4550);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2607, '4.  자살자나 자살로 의심되는 사체를 검시하는 경우에는 교사자(敎唆者) 또는 방조자의 유무와 유서가 있는 경우 그 진위를 조사할 것', 4550);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2608, '5.  등록된 지문이 확인되지 않거나 부패 등으로 신원확인이 곤란한 경우에는 디엔에이(DNA) 감정을 의뢰하고, 입양자로 확인된 경우에는 입양기관 탐문 등 신원확인을 위한 보강 조사를 할 것', 4550);
