INSERT INTO balaw.ho (id, content, hang_id) VALUES (2849, '1.  법 제14조의2제2항 각 호의 어느 하나에 해당하는 경우에는 별표 1의 방법으로 할 것', 5085);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2850, '2.  법 제14조의2제2항제1호 또는 제3호에 해당하는 경우로서 별표 1의 방법으로는 사용 목적을 달성할 수 없다고 인정되는 경우에는 별표 1의2의 방법으로 할 것. 이 경우 별표 1의2의 방법으로 수갑을 사용하여 그 목적을 달성했을 때에는 즉시 별표 1의 방법으로 바꾸거나 사용을 중지해야 한다.', 5085);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2851, '3.  외부 의료기관에 입원 중인 보호소년등에 대하여 한 손 수갑을 사용할 경우에는 별표 1의3의 방법으로 할 것', 5085);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2852, '1.  환자, 진학ㆍ취업 등을 위한 면접 대상자 등을 개별 호송하는 경우로서 이탈할 위험성이 크지 않다고 판단되는 경우에는 별표 1의4부터 별표 1의6까지의 방법으로 할 것', 5086);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2853, '2.  법 제14조의2제2항제2호의 경우(이 항 제1호의 경우는 제외한다)에는 별표 1의7 또는 별표 1의8의 방법으로 할 것. 다만, 3명 이상의 보호소년등을 호송하는 경우에는 별표 1의4의 방법으로 할 수 있다.', 5086);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2854, '3.  법 제14조의2제2항 각 호의 어느 하나에 해당하는 경우로서 별표 1의4부터 별표 1의8까지의 방법으로는 사용 목적을 달성할 수 없다고 인정되는 경우에만 별표 1의9의 방법으로 할 것', 5086);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2855, '4.  3명 이상의 보호소년등을 인솔하거나 호송하는 경우에는 연속으로 포승을 할 것. 이 경우 성별이 다른 보호소년등은 서로 분리하여 연결해야 한다.', 5086);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2856, '1.  가스총은 법 제14조의2제3항 각 호의 어느 하나에 해당하는 경우만 사용할 것', 5087);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2857, '2.  가스총을 사용하려면 법 제14조의2제4항에 따라 상대방에게 이를 경고할 것', 5087);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2858, '3.  가스총을 발사할 때는 해당 보호소년등의 안전 및 가스총 발사효과 등을 고려하여 발사거리를 2미터 이상 유지할 것', 5087);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2859, '1.  전자충격기는 법 제14조의2제3항 각 호의 어느 하나에 해당하는 경우로서 상황이 긴급하여 가스총만으로는 그 목적을 달성할 수 없는 경우에만 사용할 것', 5088);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2860, '2.  전자충격기를 사용하려면 법 제14조의2제4항에 따라 상대방에게 이를 경고할 것', 5088);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2861, '3.  전자충격기를 사용할 때에는 상대방의 피해를 최소화하도록 노력할 것', 5088);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2862, '4.  전자충격기를 사용할 때에는 상대방의 머리, 얼굴, 가슴, 그 밖에 치명적 피해를 줄 수 있는 부위에는 사용하지 말 것', 5088);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2863, '5.  전자충격기를 사용했을 때에는 충격 즉시 전자충격기를 떼어낼 것', 5088);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2864, '1.  영상정보처리기기: 일정한 공간에 지속적으로 설치되어 사람 또는 사물의 영상 및 이에 따르는 음성ㆍ음향 등을 수신하거나 유ㆍ무선망을 통하여 이를 전송하는 장치', 5098);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2865, '2.  전자감지기: 일정한 공간에 지속적으로 설치되어 사람 또는 사물의 움직임을 빛ㆍ온도ㆍ소리ㆍ압력 등을 이용하여 감지하고 전송하는 장치', 5098);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2866, '3.  전자이름표: 전자파를 발신하고 추적하는 원리를 이용하여 사람의 위치를 확인하거나 이동경로를 탐지하는 일련의 기계적 장치', 5098);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (2867, '4.  물품검색기(고정식 물품검색기와 휴대식 금속탐지기를 말한다)', 5098);
