INSERT INTO balaw.ho (id, content, hang_id) VALUES (3122, '1.  "인도조약"이란 대한민국과 외국 간에 체결된 범죄인의 인도에 관한 조약ㆍ협정 등의 합의를 말한다.', 5430);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3123, '2.  "청구국"이란 범죄인의 인도를 청구한 국가를 말한다.', 5430);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3124, '3.  "인도범죄"란 범죄인의 인도를 청구할 때 그 대상이 되는 범죄를 말한다.', 5430);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3125, '4.  "범죄인"이란 인도범죄에 관하여 청구국에서 수사나 재판을 받고 있는 사람 또는 유죄의 재판을 받은 사람을 말한다.', 5430);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3126, '5.  "긴급인도구속"이란 도망할 염려가 있는 경우 등 긴급하게 범죄인을 체포ㆍ구금(拘禁)하여야 할 필요가 있는 경우에 범죄인 인도청구가 뒤따를 것을 전제로 하여 범죄인을 체포ㆍ구금하는 것을 말한다.', 5430);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3127, '1.  대한민국 또는 청구국의 법률에 따라 인도범죄에 관한 공소시효 또는 형의 시효가 완성된 경우', 5431);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3128, '2.  인도범죄에 관하여 대한민국 법원에서 재판이 계속(係屬) 중이거나 재판이 확정된 경우', 5431);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3129, '3.  범죄인이 인도범죄를 범하였다고 의심할 만한 상당한 이유가 없는 경우. 다만, 인도범죄에 관하여 청구국에서 유죄의 재판이 있는 경우는 제외한다.', 5431);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3130, '4.  범죄인이 인종, 종교, 국적, 성별, 정치적 신념 또는 특정 사회단체에 속한 것 등을 이유로 처벌되거나 그 밖의 불리한 처분을 받을 염려가 있다고 인정되는 경우', 5431);
