INSERT INTO balaw.ho (id, content, hang_id) VALUES (3274, '3.  예산 또는 자금의 배정 지연으로 인하여 경쟁에 부칠 시간적 여유가 없어 교도작업 및 사업상 지장이 초래된다고 인정되는 경우', 5681);
