INSERT INTO balaw.ho (id, content, hang_id) VALUES (3281, '1.  직영작업: 법 제6조에 따른 민간기업의 참여 없이 교도작업제품을 생산하는 작업', 5687);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3282, '2.  위탁작업: 법 제6조에 따라 교도작업에 참여한 민간기업을 통하여 교도작업제품을 생산하는 작업', 5687);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3283, '3.  노무작업: 수용자의 노무를 제공하여 교도작업제품을 생산하는 작업', 5687);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3284, '4.  도급작업: 국가와 제3자 간의 공사 도급계약에 따라 수용자에게 부과하는 작업', 5687);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3285, '1.  계약의 목적은 그 내용을 구성하는 품명ㆍ산지(産地)ㆍ규격ㆍ형상ㆍ수량ㆍ단가 및 금액을 구체적으로 적을 것', 5689);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3286, '2.  이행 기한은 해당 회계연도로 하되, 이행의 난이도, 수량의 많고 적음, 계절 및 시장의 상황, 그 밖의 여건 및 자금사정을 고려하여 사업 운영에 적합하도록 할 것', 5689);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3287, '3.  이행 장소는 계약금액을 고려하여 결정한 후 계약서 본문에 명시할 것', 5689);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3288, '4.  계약서는 계약서ㆍ명세서ㆍ예정가격조서ㆍ설계사양서ㆍ도면ㆍ설계설명서ㆍ주의서ㆍ입찰서ㆍ입찰단가명세서, 그 밖의 부속서류 순으로 철하여 양쪽 당사자가 간인(間印)하고 이를 계약서의 원본으로 할 것', 5689);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3289, '1.  약식명령청구의 접수', 5697);
