INSERT INTO balaw.ho (id, content, hang_id) VALUES (3292, '4.  검사가 정식재판 청구를 한 경우에는 그 사실', 5697);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3293, '5.  그 밖에 송달할 서류 또는 통지할 사항으로서 법원이 전자적 송달이나 통지를 할 것을 결정한 것', 5697);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3294, '1.  검사가 시스템을 통하여 제출한 전자문서 및 전자화문서', 5703);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3295, '2.  피고인이 형사사법포털을 통하여 제출한 전자문서 및 전자화문서', 5703);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3296, '3.  법원에서 작성한 전자문서 및 전자화문서', 5703);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3297, '1.  기록의 열람ㆍ출력：1건마다 500원(이 경우 출력이 열람과 동시에 또는 열람 후 즉시 이루어지는 경우에는 1건의 출력으로 본다)', 5707);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3298, '2.  기록의 출력서면 교부 : 출력서면 1장마다 50원(다만, 100원 단위 미만 금액은 이를 계산하지 아니한다)', 5707);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3299, '1.  "오염물질"이란 다음 각 목의 어느 하나에 해당하는 물질을 말한다.', 5709);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3300, '2.  "불법배출"이란 다음 각 목의 어느 하나에 해당하는 행위(제5호가목 또는 나목의 불법배출시설을 운영하는 사업자가 하는 가목 또는 나목의 행위를 포함한다)를 말한다.', 5709);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3301, '3.  "배출시설"이란 다음 각 목의 어느 하나에 해당하는 시설을 말한다.', 5709);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3302, '4.  "영업"이란 다음 각 목의 어느 하나에 해당하는 업(業)을 말한다.', 5709);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3303, '5.  "불법배출시설"이란 다음 각 목의 어느 하나에 해당하는 시설을 말한다.', 5709);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3304, '6.  "사업자"란 배출시설이나 불법배출시설을 설치ㆍ운영하는 자 또는 영업을 하는 자를 말한다.', 5709);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3305, '7.  "환경보호지역"이란 다음 각 목의 어느 하나에 해당하는 지역, 구역 또는 섬을 말한다.', 5709);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3306, '8.  "환경법위반행위"란 다음 각 목의 어느 하나에 해당하는 행위를 말한다.', 5709);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3307, '1.  농업, 축산업, 임업 또는 원예업에 이용되는 300제곱미터 이상의 토지를 해당 용도로 이용할 수 없게 한 자', 5712);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3308, '2.  바다, 하천, 호소(湖沼) 또는 지하수를 별표 1에서 정하는 규모 및 기준 이상으로 오염시킨 자', 5712);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3309, '3.  어패류를 별표 2에서 정하는 규모 이상으로 집단폐사(集團斃死)에 이르게 한 자', 5712);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3310, '1.  다음 각 목의 어느 하나에 해당하는 물질을 불법배출(제2조제2호가목부터 아목까지 또는 타목의 행위만 해당한다. 이하 이 조에서 같다)한 자', 5721);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3311, '2.  다음 각 목의 어느 하나를 위반하여 배출시설에 부착된 측정기기를 조작하거나 가동하지 아니하거나 거짓으로 측정결과를 작성하거나 서류 또는 자료를 거짓, 그 밖의 부정한 방법으로 작성ㆍ기록 또는 제출하면서 제1호가목부터 다목까지의 물질 중 어느 하나를 배출한 자', 5721);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3312, '3.  「화학물질관리법」 제23조제1항 또는 제46조제2항 중 어느 하나를 위반하여 서류나 자료를 거짓, 그 밖의 부정한 방법으로 작성, 기록 또는 제출하면서 인체급성유해성물질, 인체만성유해성물질, 생태유해성물질을 불법배출한 자', 5721);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3313, '4.  「화학물질관리법」 제13조에 따른 유해화학물질 취급기준에 적합하지 아니하게 유해화학물질을 관리함으로써 같은 법 제2조제3호부터 제5호까지의 규정에 따른 허가물질, 제한물질, 금지물질 중 어느 하나를 배출ㆍ누출한 자', 5721);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3314, '5.  다음 각 목의 어느 하나를 고의로 위반하여 허가나 변경허가 또는 승인이나 변경승인을 받지 아니하거나 신고나 변경신고를 하지 아니하고 설치 또는 변경한 배출시설을 운영하면서 오염물질을 배출한 자', 5721);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3315, '6.  「잔류성오염물질 관리법」 제2조제2호에 따른 배출시설이나 방지시설을 정당한 사유 없이 정상적으로 가동하지 아니하여 같은 법 제14조제3항을 위반한 자', 5721);
