INSERT INTO balaw.ho (id, content, hang_id) VALUES (3368, '1.  법 제12조제1항 각 호의 위반 사실을 알게 된 즉시 이를 환경부장관에게 자발적으로 신고하고 시정한 자: 같은 항 각 호 외의 부분 본문에 따른 위반부과금액(이하 "위반부과금액"이라 한다)의 100분의 30에 상당하는 금액 이하', 5744);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3369, '2.  제1호에 해당하는 자로서 조사가 끝날 때까지 일관되게 위반 사실을 인정하고 관련 자료를 제출하는 등 조사에 적극적으로 협력한 자: 위반부과금액의 100분의 50에 상당하는 금액 이하', 5744);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3370, '3.  제1호 및 제2호에 해당하는 자로서 공동불법행위를 환경부장관에게 최초로 신고하고 관련 자료를 제출한 자: 위반부과금액의 100분의 80에 상당하는 금액 이하', 5744);
