INSERT INTO balaw.ho (id, content, hang_id) VALUES (3398, '4.  "아동학대범죄"란 보호자에 의한 아동학대로서 다음 각 목의 어느 하나에 해당하는 죄를 말한다.', 5769);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3399, '4의2.  "아동학대범죄신고등"이란 아동학대범죄에 관한 신고ㆍ진정ㆍ고소ㆍ고발 등 수사 단서의 제공, 진술 또는 증언이나 그 밖의 자료제출행위 및 범인검거를 위한 제보 또는 검거활동을 말한다.', 5769);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3400, '4의3.  "아동학대범죄신고자등"이란 아동학대범죄신고등을 한 자를 말한다.', 5769);
