INSERT INTO balaw.ho (id, content, hang_id) VALUES (3560, '1.  피해아동등 또는 가정구성원이 법 제21조제3항에 따라 법원에 임시조치 결정의 변경을 신청하는 경우', 5995);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3561, '2.  아동학대행위자, 그 법정대리인이나 보조인이 법 제22조제1항에 따라 법원에 임시조치 결정의 취소 또는 그 종류의 변경을 신청하는 경우', 5995);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3562, '3.  시ㆍ도지사, 시장ㆍ군수ㆍ구청장, 피해아동등 또는 그 법정대리인이나 변호사가 법 제22조제4항에 따라 법원에 임시조치 결정의 변경을 청구하는 경우', 5995);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3563, '1.  휴대용 추적장치: 전자장치가 부착된 사람(이하 "피부착자"라 한다)이 휴대하는 것으로서 피부착자의 위치를 확인하는 장치', 6014);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3564, '2.  재택(在宅) 감독장치: 피부착자의 주거지에 설치하여 피부착자의 위치를 확인하는 장치', 6014);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3565, '3.  부착장치: 피부착자의 신체에 부착하는 장치로서, 휴대용 추적장치와 재택 감독장치에 전자파를 송신하거나 피부착자의 위치를 확인하는 장치', 6014);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3566, '1.  휴대용 추적장치는 피부착명령자가 휴대할 수 있도록 교부한다. 다만, 부착장치에 피부착자의 위치를 확인하는 기능이 있는 경우에는 교부하지 아니한다.', 6026);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3567, '2.  부착장치는 피부착명령자의 발목에 부착한다. 다만, 발목에 부착할 수 없는 특별한 사유가 있으면 다른 신체 부위에 부착할 수 있다.', 6026);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3568, '3.  재택 감독장치는 피부착명령자의 석방 후 지체 없이 피부착명령자의 주거지에 고정하여 설치한다. 다만, 피부착명령자의 주거가 일정하지 아니하거나 그 밖에 재택 감독장치를 설치하기 어려운 사정이 있는 경우에는 설치하지 아니할 수 있다.', 6026);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3569, '1.  전자장치의 기능이 정상적으로 유지될 수 있도록 전자장치를 충전, 휴대 또는 관리할 것', 6036);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3570, '2.  전자장치가 정상적으로 작동하지 아니하는 경우 지체 없이 그 사실을 보호관찰관에게 알릴 것', 6036);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3571, '3.  전자장치의 기능 유지를 위한 보호관찰관의 정당한 지시에 따를 것', 6036);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3572, '1.  「출입국관리법」 제4조 등 다른 법률의 규정에 따라 출국이 금지된 경우', 6040);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3573, '2.  출국의 목적에 관한 소명자료를 제출하지 아니하는 경우', 6040);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3574, '3.  부착명령 집행기간 중 정당한 사유 없이 출국 허가기간 내에 귀국하지 아니하였거나 허가를 받지 아니하고 출국한 전력(前歷)이 있는 경우', 6040);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3575, '1.  피부착자 또는 피부착명령자의 성명, 주민등록번호, 직업 및 주거', 6046);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3576, '2.  신청의 취지', 6046);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3577, '3.  부착기간의 연장 또는 준수사항의 부과ㆍ추가ㆍ변경ㆍ삭제가 필요한 사유', 6046);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3578, '1.  「정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률」 제3조제4호에 따른 정신건강증진시설', 6049);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3579, '2.  「성폭력방지 및 피해자보호 등에 관한 법률」 제10조에 따른 성폭력피해상담소, 같은 법 제27조에 따른 전담의료기관', 6049);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3580, '3.  특정 범죄자를 치료하고 특정 범죄자 교정프로그램을 개발ㆍ실시한 경험이 있는 민간 단체 또는 기관', 6049);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3581, '1.  피부착자의 인적사항, 긴급한 사유, 수신자료 제공기관, 요청사유 및 필요한 자료의 범위를 적은 긴급 열람ㆍ조회 요청서', 6057);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3582, '2.  자신의 신분을 표시할 수 있는 증표', 6057);
