INSERT INTO balaw.ho (id, content, hang_id) VALUES (3711, '2.  「형사소송법」(이하 "법"이라 한다) 제197조의2제2항 및 제3항에 따른 정당한 이유의 유무에 대해 이견이 있는 경우', 6152);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3712, '3.  법 제197조의4제2항 단서에 따라 사법경찰관이 계속 수사할 수 있는지 여부나 사법경찰관이 계속 수사할 수 있는 경우 수사를 계속할 주체 또는 사건의 이송 여부 등에 대해 이견이 있는 경우', 6152);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3713, '4.  법 제245조의8제2항에 따른 재수사의 결과에 대해 이견이 있는 경우', 6152);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3714, '1.  국민의 인권보호, 수사의 신속성ㆍ효율성 등을 위한 제도 개선 및 정책 제안', 6154);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3715, '2.  국가적 재난 상황 등 관련 기관 간 긴밀한 협조가 필요한 업무를 공동으로 수행하기 위해 필요한 사항', 6154);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3716, '3.  그 밖에 제1항의 어느 한 기관이 수사기관협의회의 협의 또는 조정이 필요하다고 요구한 사항', 6154);
