INSERT INTO balaw.ho (id, content, hang_id) VALUES (3721, '5.  사람의 신체, 주거, 관리하는 건조물, 자동차, 선박, 항공기 또는 점유하는 방실에 대한 압수ㆍ수색 또는 검증영장(부검을 위한 검증영장은 제외한다)의 청구 또는 신청', 6172);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3722, '1.  법 제197조의4제2항 단서에 따라 사법경찰관이 범죄사실을 계속 수사할 수 있게 된 때', 6185);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3723, '2.  그 밖에 다른 수사기관에서 수사하는 것이 적절하다고 판단되는 때', 6185);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3724, '1.  출석요구를 하기 전에 우편ㆍ전자우편ㆍ전화를 통한 진술 등 출석을 대체할 수 있는 방법의 선택 가능성을 고려할 것', 6188);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3725, '2.  출석요구의 방법, 출석의 일시ㆍ장소 등을 정할 때에는 피의자의 명예 또는 사생활의 비밀이 침해되지 않도록 주의할 것', 6188);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3726, '3.  출석요구를 할 때에는 피의자의 생업에 지장을 주지 않도록 충분한 시간적 여유를 두도록 하고, 피의자가 출석 일시의 연기를 요청하는 경우 특별한 사정이 없으면 출석 일시를 조정할 것', 6188);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3727, '4.  불필요하게 여러 차례 출석요구를 하지 않을 것', 6188);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3728, '1.  피의자를 체포한 후 48시간 이내에 구속영장의 청구 또는 신청 여부를 판단하기 위해 불가피한 경우', 6195);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3729, '2.  공소시효가 임박한 경우', 6195);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3730, '3.  피의자나 사건관계인이 출국, 입원, 원거리 거주, 직업상 사유 등 재출석이 곤란한 구체적인 사유를 들어 심야조사를 요청한 경우(변호인이 심야조사에 동의하지 않는다는 의사를 명시한 경우는 제외한다)로서 해당 요청에 상당한 이유가 있다고 인정되는 경우', 6195);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3731, '4.  그 밖에 사건의 성질 등을 고려할 때 심야조사가 불가피하다고 판단되는 경우 등 법무부장관, 경찰청장 또는 해양경찰청장이 정하는 경우로서 검사 또는 사법경찰관의 소속 기관의 장이 지정하는 인권보호 책임자의 허가 등을 받은 경우', 6195);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3732, '1.  피의자나 사건관계인의 서면 요청에 따라 조서를 열람하는 경우', 6196);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3733, '2.  제21조제2항 각 호의 어느 하나에 해당하는 경우', 6196);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3734, '1.  조서를 작성하는 경우: 조서에 기록(별도의 서면에 기록한 후 조서의 끝부분에 편철하는 것을 포함한다)', 6206);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3735, '2.  조서를 작성하지 않는 경우: 별도의 서면에 기록한 후 수사기록에 편철', 6206);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3736, '1.  조서를 작성하는 경우에는 다음 각 목의 사항', 6207);
