INSERT INTO balaw.ho (id, content, hang_id) VALUES (3898, '1.  휴대용 추적장치: 전자장치가 부착된 사람(이하 "피부착자"라 한다)이 휴대하는 것으로서 피부착자의 위치를 확인하는 장치', 6397);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3899, '2.  재택(在宅) 감독장치: 피부착자의 주거지에 설치하여 피부착자의 위치를 확인하는 장치', 6397);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3900, '3.  부착장치: 피부착자의 신체에 부착하는 장치로서, 휴대용 추적장치와 재택 감독장치에 전자파를 송신하거나 피부착자의 위치를 확인하는 장치', 6397);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3901, '1.  휴대용 추적장치는 피부착명령자가 휴대할 수 있도록 교부한다. 다만, 부착장치에 피부착자의 위치를 확인하는 기능이 있는 경우에는 교부하지 아니한다.', 6409);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3902, '2.  부착장치는 피부착명령자의 발목에 부착한다. 다만, 발목에 부착할 수 없는 특별한 사유가 있으면 다른 신체 부위에 부착할 수 있다.', 6409);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3903, '3.  재택 감독장치는 피부착명령자의 석방 후 지체 없이 피부착명령자의 주거지에 고정하여 설치한다. 다만, 피부착명령자의 주거가 일정하지 아니하거나 그 밖에 재택 감독장치를 설치하기 어려운 사정이 있는 경우에는 설치하지 아니할 수 있다.', 6409);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3904, '1.  전자장치의 기능이 정상적으로 유지될 수 있도록 전자장치를 충전, 휴대 또는 관리할 것', 6419);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3905, '2.  전자장치가 정상적으로 작동하지 아니하는 경우 지체 없이 그 사실을 보호관찰관에게 알릴 것', 6419);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3906, '3.  전자장치의 기능 유지를 위한 보호관찰관의 정당한 지시에 따를 것', 6419);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3907, '1.  「출입국관리법」 제4조 등 다른 법률의 규정에 따라 출국이 금지된 경우', 6423);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3908, '2.  출국의 목적에 관한 소명자료를 제출하지 아니하는 경우', 6423);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3909, '3.  부착명령 집행기간 중 정당한 사유 없이 출국 허가기간 내에 귀국하지 아니하였거나 허가를 받지 아니하고 출국한 전력(前歷)이 있는 경우', 6423);
