INSERT INTO balaw.ho (id, content, hang_id) VALUES (3914, '2.  「성폭력방지 및 피해자보호 등에 관한 법률」 제10조에 따른 성폭력피해상담소, 같은 법 제27조에 따른 전담의료기관', 6432);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3915, '3.  특정 범죄자를 치료하고 특정 범죄자 교정프로그램을 개발ㆍ실시한 경험이 있는 민간 단체 또는 기관', 6432);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (3916, '1.  피부착자의 인적사항, 긴급한 사유, 수신자료 제공기관, 요청사유 및 필요한 자료의 범위를 적은 긴급 열람ㆍ조회 요청서', 6440);
