INSERT INTO balaw.ho (id, content, hang_id) VALUES (3919, '2.  주민등록번호. 다만, 외국인 및 「재외동포의 출입국과 법적 지위에 관한 법률」 제2조제1호에 따른 재외국민(주민등록을 하지 아니한 경우만 해당하며, 이하 이 호에서 "재외국민"이라 한다)과 같은 조 제2호에 따른 외국국적동포(이하 "외국국적동포"라 한다)에 대해서는 다음 각 목의 구분에 따라 표기한다.', 6452);
