INSERT INTO balaw.ho (id, content, hang_id) VALUES (4020, '4.  법률 제9112호 특정 성폭력범죄자에 대한 위치추적 전자장치 부착에 관한 법률 일부개정법률 부칙 제2조에 따른 부착명령의 청구, 조사, 집행에 관한 사무', 6519);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4021, '5.  제1호부터 제4호까지의 규정에 따른 사무를 수행하기 위해 필요한 사무', 6519);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4022, '1.  법 제16조의2(법 제27조 및 제31조에 따라 준용되는 경우를 포함한다)에 따른 신상정보 제공 등에 관한 사무', 6520);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4023, '2.  법 제31조의6에 따른 전자장치 부착의 집행에 관한 사무', 6520);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4024, '1.  법 제16조(법 제27조 및 제31조에 따라 준용되는 경우를 포함한다)에 따른 수신자료의 열람ㆍ조회ㆍ폐기 등에 관한 사무', 6521);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4025, '2.  법 제31조의8에 따른 스토킹행위자 수신자료의 열람ㆍ조회ㆍ폐기 등에 관한 사무', 6521);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4026, '1.  보호소년등의 의류 및 소지품 등의 검사', 6523);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4027, '2.  신상조사', 6523);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4028, '3.  건강진단 및 신체검사', 6523);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4029, '4.  이발ㆍ목욕 및 피복지급 등 위생에 필요한 조치', 6523);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4030, '5.  사진촬영', 6523);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4031, '1.  「소년법」 제32조제1항제7호부터 제10호까지의 규정에 따라 위탁되거나 송치된 보호소년', 6525);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4032, '2.  제53조에 따른 신입자교육을 받고 있는 보호소년', 6525);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4033, '3.  감염병에 감염된 보호소년등', 6525);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4034, '4.  공동으로 비행을 저지르는 등 특별관리가 필요하다고 인정되는 보호소년등', 6525);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4035, '1.  정신질환자(알코올중독자 및 약물중독자를 포함한다)', 6535);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4036, '2.  신체질환자(뇌전증 환자를 포함한다)', 6535);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4037, '1.  법 제14조의2제2항 각 호의 어느 하나에 해당하는 경우에는 별표 1의 방법으로 할 것', 6543);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4038, '2.  법 제14조의2제2항제1호 또는 제3호에 해당하는 경우로서 별표 1의 방법으로는 사용 목적을 달성할 수 없다고 인정되는 경우에는 별표 1의2의 방법으로 할 것. 이 경우 별표 1의2의 방법으로 수갑을 사용하여 그 목적을 달성했을 때에는 즉시 별표 1의 방법으로 바꾸거나 사용을 중지해야 한다.', 6543);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4039, '3.  외부 의료기관에 입원 중인 보호소년등에 대하여 한 손 수갑을 사용할 경우에는 별표 1의3의 방법으로 할 것', 6543);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4040, '1.  환자, 진학ㆍ취업 등을 위한 면접 대상자 등을 개별 호송하는 경우로서 이탈할 위험성이 크지 않다고 판단되는 경우에는 별표 1의4부터 별표 1의6까지의 방법으로 할 것', 6544);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4041, '2.  법 제14조의2제2항제2호의 경우(이 항 제1호의 경우는 제외한다)에는 별표 1의7 또는 별표 1의8의 방법으로 할 것. 다만, 3명 이상의 보호소년등을 호송하는 경우에는 별표 1의4의 방법으로 할 수 있다.', 6544);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4042, '3.  법 제14조의2제2항 각 호의 어느 하나에 해당하는 경우로서 별표 1의4부터 별표 1의8까지의 방법으로는 사용 목적을 달성할 수 없다고 인정되는 경우에만 별표 1의9의 방법으로 할 것', 6544);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4043, '4.  3명 이상의 보호소년등을 인솔하거나 호송하는 경우에는 연속으로 포승을 할 것. 이 경우 성별이 다른 보호소년등은 서로 분리하여 연결해야 한다.', 6544);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4044, '1.  가스총은 법 제14조의2제3항 각 호의 어느 하나에 해당하는 경우만 사용할 것', 6545);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4045, '2.  가스총을 사용하려면 법 제14조의2제4항에 따라 상대방에게 이를 경고할 것', 6545);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4046, '3.  가스총을 발사할 때는 해당 보호소년등의 안전 및 가스총 발사효과 등을 고려하여 발사거리를 2미터 이상 유지할 것', 6545);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4047, '1.  전자충격기는 법 제14조의2제3항 각 호의 어느 하나에 해당하는 경우로서 상황이 긴급하여 가스총만으로는 그 목적을 달성할 수 없는 경우에만 사용할 것', 6546);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4048, '2.  전자충격기를 사용하려면 법 제14조의2제4항에 따라 상대방에게 이를 경고할 것', 6546);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4049, '3.  전자충격기를 사용할 때에는 상대방의 피해를 최소화하도록 노력할 것', 6546);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4050, '4.  전자충격기를 사용할 때에는 상대방의 머리, 얼굴, 가슴, 그 밖에 치명적 피해를 줄 수 있는 부위에는 사용하지 말 것', 6546);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4051, '5.  전자충격기를 사용했을 때에는 충격 즉시 전자충격기를 떼어낼 것', 6546);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4052, '1.  영상정보처리기기: 일정한 공간에 지속적으로 설치되어 사람 또는 사물의 영상 및 이에 따르는 음성ㆍ음향 등을 수신하거나 유ㆍ무선망을 통하여 이를 전송하는 장치', 6556);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4053, '2.  전자감지기: 일정한 공간에 지속적으로 설치되어 사람 또는 사물의 움직임을 빛ㆍ온도ㆍ소리ㆍ압력 등을 이용하여 감지하고 전송하는 장치', 6556);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4054, '3.  전자이름표: 전자파를 발신하고 추적하는 원리를 이용하여 사람의 위치를 확인하거나 이동경로를 탐지하는 일련의 기계적 장치', 6556);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4055, '4.  물품검색기(고정식 물품검색기와 휴대식 금속탐지기를 말한다)', 6556);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4056, '5.  증거수집장비: 디지털카메라, 녹음기, 비디오카메라 등 증거수집에 필요한 장비', 6556);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4057, '1.  보호소년등이 이탈을 하는 행위', 6568);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4058, '2.  다른 사람을 처벌받게 하거나 직원의 집무집행을 방해할 목적으로 거짓사실을 신고하는 행위', 6568);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4059, '3.  보호장비, 전자장비, 그 밖의 보안시설의 기능을 훼손하는 행위', 6568);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4060, '4.  음란한 행위를 하거나 다른 사람에게 성적 언동 등으로 성적 수치심 또는 혐오감을 느끼게 하는 행위', 6568);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4061, '5.  다른 사람에게 부당한 금품을 요구하는 행위', 6568);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4062, '6.  교육ㆍ면회ㆍ전화통화 등 다른 보호소년등의 정상적인 일과진행 또는 직원의 직무를 방해하는 행위', 6568);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4063, '7.  문신을 하거나 이물질을 신체에 삽입하는 등 신체를 변형시키는 행위', 6568);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4064, '8.  허가 없이 지정된 장소를 벗어나거나 금지구역에 출입하는 행위', 6568);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4065, '9.  허가 없이 다른 사람과 만나거나 연락하는 행위', 6568);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4066, '10.  수용생활의 편의 등 자신의 요구를 관철할 목적으로 이물질을 삼키는 행위', 6568);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4067, '11.  인원점검을 회피하거나 방해하는 행위', 6568);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4068, '12.  시설의 설비나 물품을 고의로 훼손하는 행위', 6568);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4069, '13.  큰 소리를 내거나 시끄럽게 하여 다른 보호소년등의 평온한 생활을 방해하는 행위', 6568);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4070, '14.  도박이나 그 밖에 사행심을 조장하는 놀이나 내기를 하는 행위', 6568);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4071, '15.  지정된 생활실에 입실하기를 거부하는 등 정당한 사유 없이 직원의 직무상 지시나 명령을 따르지 아니하는 행위', 6568);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4072, '1.  훈계: 30점', 6571);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4073, '2.  원내봉사활동: 50점', 6571);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4074, '3.  서면사과: 30점', 6571);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4075, '4.  텔레비전 시청 제한: 50점', 6571);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4076, '5.  단체 체육활동 정지: 50점', 6571);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4077, '6.  공동행사 참가 정지: 50점', 6571);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4078, '7.  7일 미만의 근신: 60점', 6571);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4079, '8.  7일 이상의 근신: 1일에 각 10점', 6571);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4080, '1.  인권침해가 발생하지 아니하도록 유의할 것', 6574);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4081, '2.  조사의 이유를 설명하고, 충분한 진술의 기회를 제공할 것', 6574);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4082, '3.  공정한 절차와 객관적 증거에 따라 조사하고, 선입견이나 추측에 따라 처리하지 아니할 것', 6574);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4083, '4.  형사 법률에 저촉되는 행위에 대하여 징계 부과 외에 형사입건조치가 요구되는 경우에는 형사소송절차에 따라 조사대상자에게 진술을 거부할 수 있다는 것과 변호인을 선임할 수 있다는 것을 알릴 것', 6574);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4084, '1.  교육에 유해하다고 인정되는 물품', 6575);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4085, '2.  위화감을 조장할 수 있다고 판단되는 고가품', 6575);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4086, '3.  적정 소요량을 초과한 것으로 인정되는 물품', 6575);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4087, '1.  면회시간ㆍ절차 및 면회시 유의사항 등이 작성된 안내문', 6578);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4088, '2.  청원함', 6578);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4089, '1.  처음 면회온 사람으로서 면회에 관한 법령을 알지 못한 경우', 6582);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4090, '2.  환자인 보호소년등을 면회하는 경우', 6582);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4091, '3.  보호소년등의 직계존속이 원격지에서 면회를 오는 경우', 6582);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4092, '4.  통신망을 이용한 화상면회를 하는 경우', 6582);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4093, '5.  사전에 면회예약신청을 통하여 원장의 허가를 받은 경우', 6582);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4094, '6.  교정교육 활동의 하나로 사전에 수립된 계획에 포함된 경우', 6582);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4095, '7.  보호소년등의 가족관계 개선 등을 위하여 원장이 특별히 필요하다고 인정하는 경우', 6582);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4096, '1.  재범의 유혹이나 충동을 느낄 수 있는 장소에 출입하지 아니할 것', 6588);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4097, '2.  사행행위를 하지 아니할 것', 6588);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4098, '3.  음주ㆍ흡연을 하지 아니할 것', 6588);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4099, '4.  마약ㆍ향정신성의약품ㆍ대마 등 오ㆍ남용의 위험성이 있거나 건강에 해로운 물질을 사용하지 아니할 것', 6588);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4100, '5.  그 밖에 보호자의 훈육의지에 반하는 행위나 불량한 교우관계를 형성하지 아니할 것', 6588);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4101, '1.  일반분류심사: 문제 또는 비행원인이 비교적 단순한 소년에 대하여 면접조사와 신체의학적 진찰, 집단검사, 자기기록 검토, 자료조회, 행동관찰 등을 주로 하여 실시하는 분류심사', 6605);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4102, '2.  특수분류심사: 일반분류심사결과 문제 또는 비행원인이 중대하고 복잡한 소년에 대하여 개별검사와 정신의학적 진단, 현지조사 등을 추가하여 실시하는 분류심사', 6605);
