INSERT INTO balaw.ho (id, content, hang_id) VALUES (4720, '4.  "위치추적 전자장치(이하 "전자장치"라 한다)"란 전자파를 발신하고 추적하는 원리를 이용하여 위치를 확인하거나 이동경로를 탐지하는 일련의 기계적 설비로서 대통령령으로 정하는 것을 말한다.', 7411);
