INSERT INTO balaw.ho (id, content, hang_id) VALUES (4728, '3.  강도범죄를 2회 이상 범하여(유죄의 확정판결을 받은 경우를 포함한다) 그 습벽이 인정된 때', 7419);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4729, '1.  스토킹범죄로 징역형의 실형을 선고받은 사람이 그 집행을 종료한 후 또는 집행이 면제된 후 10년 이내에 다시 스토킹범죄를 저지른 때', 7420);
