INSERT INTO balaw.ho (id, content, hang_id) VALUES (4731, '3.  스토킹범죄를 2회 이상 범하여(유죄의 확정판결을 받은 경우를 포함한다) 그 습벽이 인정된 때', 7420);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4732, '1.  부착명령 청구대상자(이하 "피부착명령청구자"라 한다)의 성명과 그 밖에 피부착명령청구자를 특정할 수 있는 사항', 7431);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4733, '2.  청구의 원인이 되는 사실', 7431);
