INSERT INTO balaw.ho (id, content, hang_id) VALUES (4738, '3.  법정형 중 징역형의 하한이 3년 미만의 유기징역인 특정범죄(제1호 또는 제2호에 해당하는 특정범죄는 제외한다): 1년 이상 10년 이하', 7433);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4739, '1.  부착명령 청구가 이유 없다고 인정하는 때', 7436);
