INSERT INTO balaw.ho (id, content, hang_id) VALUES (4749, '6.  그 밖에 부착명령을 선고받는 사람의 재범방지와 성행교정을 위하여 필요한 사항', 7442);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4750, '1.  19세 미만의 사람을 대상으로 성폭력범죄를 저지른 사람: 제1항제1호 및 제3호의 준수사항을 포함할 것. 다만, 제1항제1호의 준수사항을 부과하여서는 아니 될 특별한 사정이 있다고 판단하는 경우에는 해당 준수사항을 포함하지 아니할 수 있다.', 7444);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4751, '2.  스토킹범죄를 저지른 사람: 제1항제3호의 준수사항을 포함할 것', 7444);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4752, '1.  부착명령의 원인이 된 특정범죄사건이 아닌 다른 범죄사건으로 형이나 치료감호의 집행이 계속될 경우에는 부착명령의 원인이 된 특정범죄사건이 아닌 다른 범죄사건에 대한 형의 집행이 종료되거나 면제ㆍ가석방 되는 날 또는 치료감호의 집행이 종료ㆍ가종료 되는 날부터 집행한다.', 7449);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4753, '2.  피부착명령자가 부착명령 판결 확정 시 석방된 상태이고 미결구금일수 산입 등의 사유로 이미 형의 집행이 종료된 경우에는 부착명령 판결 확정일부터 부착명령을 집행한다.', 7449);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4754, '1.  부착명령의 집행 중 다른 죄를 범하여 구속영장의 집행을 받아 구금된 때', 7454);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4755, '2.  부착명령의 집행 중 다른 죄를 범하여 금고 이상의 형의 집행을 받게 된 때', 7454);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4756, '3.  가석방 또는 가종료된 자에 대하여 전자장치 부착기간 동안 가석방 또는 가종료가 취소되거나 실효된 때', 7454);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4757, '1.  사법경찰관이 불송치결정을 한 경우', 7455);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4758, '2.  검사가 혐의없음, 죄가안됨, 공소권없음 또는 각하의 불기소처분을 한 경우', 7455);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4759, '3.  법원의 무죄, 면소, 공소기각 판결 또는 공소기각 결정이 확정된 경우', 7455);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4760, '1.  제6항제1호의 경우에는 구금이 해제되거나 금고 이상의 형의 집행을 받지 아니하게 확정된 때부터 그 잔여기간을 집행한다.', 7456);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4761, '2.  제6항제2호의 경우에는 그 형의 집행이 종료되거나 면제된 후 또는 가석방된 때부터 그 잔여기간을 집행한다.', 7456);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4762, '3.  제6항제3호의 경우에는 그 형이나 치료감호의 집행이 종료되거나 면제된 후 그 잔여기간을 집행한다.', 7456);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4763, '1.  정당한 사유 없이 「보호관찰 등에 관한 법률」 제32조에 따른 준수사항을 위반한 경우', 7461);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4764, '2.  정당한 사유 없이 제14조제2항을 위반하여 신고하지 아니한 경우', 7461);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4765, '3.  정당한 사유 없이 제14조제3항을 위반하여 허가를 받지 아니하고 주거 이전ㆍ국내여행 또는 출국을 하거나, 거짓으로 허가를 받은 경우', 7461);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4766, '4.  정당한 사유 없이 제14조제3항에 따른 출국허가 기간까지 입국하지 아니한 경우', 7461);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4767, '1.  피부착자의 특정범죄 혐의에 대한 수사 또는 재판자료로 사용하는 경우', 7467);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4768, '2.  보호관찰관이 지도ㆍ원호를 목적으로 사용하는 경우', 7467);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4769, '3.  「보호관찰 등에 관한 법률」 제5조에 따른 보호관찰심사위원회(이하 "심사위원회"라 한다)의 부착명령 임시해제와 그 취소에 관한 심사를 위하여 사용하는 경우', 7467);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4770, '4.  보호관찰소의 장이 피부착자의 제38조 또는 제39조에 해당하는 범죄 혐의에 대한 수사를 의뢰하기 위하여 사용하는 경우', 7467);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4771, '1.  부착명령과 함께 선고된 형이 「형법」 제81조에 따라 실효된 때', 7471);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4772, '2.  부착명령과 함께 선고된 형이 사면으로 인하여 그 효력을 상실한 때', 7471);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4773, '3.  전자장치 부착이 종료된 자가 자격정지 이상의 형 또는 이 법에 따른 전자장치 부착을 받음이 없이 전자장치 부착을 종료한 날부터 5년이 경과한 때', 7471);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4774, '1.  부착명령기간이 경과한 때', 7493);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4775, '2.  부착명령과 함께 선고한 형이 사면되어 그 선고의 효력을 상실하게 된 때', 7493);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4776, '3.  삭제 <2008.6.13>', 7493);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4777, '4.  부착명령이 임시해제된 자가 그 임시해제가 취소됨이 없이 잔여 부착명령기간을 경과한 때', 7493);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4778, '1.  성폭력범죄를 저지른 사람으로서 성폭력범죄를 다시 범할 위험성이 있다고 인정되는 사람', 7496);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4779, '2.  미성년자 대상 유괴범죄를 저지른 사람으로서 미성년자 대상 유괴범죄를 다시 범할 위험성이 있다고 인정되는 사람', 7496);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4780, '3.  살인범죄를 저지른 사람으로서 살인범죄를 다시 범할 위험성이 있다고 인정되는 사람', 7496);
