INSERT INTO balaw.ho (id, content, hang_id) VALUES (4785, '1.  가석방되는 날', 7515);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4786, '2.  가종료 또는 치료위탁되거나 가출소되는 날. 다만, 제23조제1항에 따른 피치료감호자에게 치료감호와 병과된 형의 잔여 형기가 있거나 치료감호의 원인이 된 특정범죄사건이 아닌 다른 범죄사건으로 인하여 집행할 형이 있는 경우에는 해당 형의 집행이 종료ㆍ면제되거나 가석방되는 날 부착한다.', 7515);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4787, '1.  가석방 기간이 경과하거나 가석방이 실효 또는 취소된 때', 7517);
