INSERT INTO balaw.ho (id, content, hang_id) VALUES (4803, '6.  그 밖에 대통령령으로 정하는 피해자의 보호를 위하여 필요한 사항', 7539);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4804, '1.  정당한 사유 없이 제2항에 따라 법원이 지정한 일시까지 보호관찰소에 출석하여 신고하지 아니하거나 전자장치 부착을 거부하는 경우', 7540);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4805, '2.  잠정조치 기간 중 「스토킹범죄의 처벌 등에 관한 법률」 제9조제1항제2호를 위반하였거나 위반할 우려가 있는 경우', 7540);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4806, '3.  잠정조치 기간 중 「스토킹범죄의 처벌 등에 관한 법률」 제9조제4항을 위반하였거나 위반하였다고 의심할 상당한 이유가 있는 경우', 7540);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4807, '4.  그 밖에 잠정조치의 이행 및 피해자의 보호를 위하여 적절한 조치가 필요한 경우로서 대통령령으로 정하는 사유가 있는 경우', 7540);
