INSERT INTO balaw.ho (id, content, hang_id) VALUES (4809, '2.  잠정조치가 변경 또는 취소된 때', 7545);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4810, '3.  잠정조치가 효력을 상실한 때', 7545);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4811, '1.  「스토킹범죄의 처벌 등에 관한 법률」 제2조제2호에 따른 스토킹범죄 혐의에 대한 수사 또는 재판자료로 사용하는 경우', 7547);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4812, '2.  「스토킹범죄의 처벌 등에 관한 법률」 제9조제1항제2호 및 제3호의2에 따른 잠정조치 이행 여부를 확인하기 위하여 사용하는 경우', 7547);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4813, '3.  「스토킹범죄의 처벌 등에 관한 법률」 제11조에 따른 잠정조치의 연장ㆍ변경ㆍ취소의 청구 또는 그 신청을 위하여 사용하는 경우', 7547);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4814, '4.  「스토킹범죄의 처벌 등에 관한 법률」 제20조제1항제1호 및 같은 조 제2항에 해당하는 범죄 혐의에 대한 수사를 위하여 사용하는 경우', 7547);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4815, '1.  잠정조치가 효력을 상실한 때', 7549);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4816, '2.  잠정조치의 원인이 되는 스토킹범죄사건에 대해 법원의 무죄, 면소, 공소기각 판결 또는 공소기각 결정이 확정된 때', 7549);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4817, '3.  잠정조치 집행을 종료한 날부터 5년이 경과한 때', 7549);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4818, '1.  피부착자가 제14조제1항을 위반하여 전자장치를 신체로부터 분리하거나 손상하는 등 그 효용을 해한 기간', 7551);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4819, '2.  피부착자의 치료, 출국 또는 그 밖의 적법한 사유로 전자장치가 신체로부터 일시적으로 분리된 후 해당 분리사유가 해소된 날부터 정당한 사유 없이 전자장치를 부착하지 아니한 기간', 7551);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4820, '1.  부착명령 및 보호관찰명령을 청구하기 위하여 필요한 피의자에 대한 조사', 7552);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4821, '2.  부착명령 및 보호관찰명령의 집행', 7552);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4822, '3.  피부착자 및 보호관찰대상자의 재범방지와 건전한 사회복귀를 위한 치료 등 필요한 조치의 부과', 7552);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4823, '4.  그 밖에 피부착자 및 보호관찰대상자의 「보호관찰 등에 관한 법률」 등에 따른 준수사항 이행 여부 확인 등 피부착자 및 보호관찰대상자에 대한 지도ㆍ감독 및 원호', 7552);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4824, '1.  휴대용 추적장치: 전자장치가 부착된 사람(이하 "피부착자"라 한다)이 휴대하는 것으로서 피부착자의 위치를 확인하는 장치', 7565);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4825, '2.  재택(在宅) 감독장치: 피부착자의 주거지에 설치하여 피부착자의 위치를 확인하는 장치', 7565);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4826, '3.  부착장치: 피부착자의 신체에 부착하는 장치로서, 휴대용 추적장치와 재택 감독장치에 전자파를 송신하거나 피부착자의 위치를 확인하는 장치', 7565);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4827, '1.  휴대용 추적장치는 피부착명령자가 휴대할 수 있도록 교부한다. 다만, 부착장치에 피부착자의 위치를 확인하는 기능이 있는 경우에는 교부하지 아니한다.', 7577);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4828, '2.  부착장치는 피부착명령자의 발목에 부착한다. 다만, 발목에 부착할 수 없는 특별한 사유가 있으면 다른 신체 부위에 부착할 수 있다.', 7577);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4829, '3.  재택 감독장치는 피부착명령자의 석방 후 지체 없이 피부착명령자의 주거지에 고정하여 설치한다. 다만, 피부착명령자의 주거가 일정하지 아니하거나 그 밖에 재택 감독장치를 설치하기 어려운 사정이 있는 경우에는 설치하지 아니할 수 있다.', 7577);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4830, '1.  전자장치의 기능이 정상적으로 유지될 수 있도록 전자장치를 충전, 휴대 또는 관리할 것', 7587);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4831, '2.  전자장치가 정상적으로 작동하지 아니하는 경우 지체 없이 그 사실을 보호관찰관에게 알릴 것', 7587);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4832, '3.  전자장치의 기능 유지를 위한 보호관찰관의 정당한 지시에 따를 것', 7587);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4833, '1.  「출입국관리법」 제4조 등 다른 법률의 규정에 따라 출국이 금지된 경우', 7591);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4834, '2.  출국의 목적에 관한 소명자료를 제출하지 아니하는 경우', 7591);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4835, '3.  부착명령 집행기간 중 정당한 사유 없이 출국 허가기간 내에 귀국하지 아니하였거나 허가를 받지 아니하고 출국한 전력(前歷)이 있는 경우', 7591);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4836, '1.  피부착자 또는 피부착명령자의 성명, 주민등록번호, 직업 및 주거', 7597);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4837, '2.  신청의 취지', 7597);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4838, '3.  부착기간의 연장 또는 준수사항의 부과ㆍ추가ㆍ변경ㆍ삭제가 필요한 사유', 7597);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4839, '1.  「정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률」 제3조제4호에 따른 정신건강증진시설', 7600);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4840, '2.  「성폭력방지 및 피해자보호 등에 관한 법률」 제10조에 따른 성폭력피해상담소, 같은 법 제27조에 따른 전담의료기관', 7600);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4841, '3.  특정 범죄자를 치료하고 특정 범죄자 교정프로그램을 개발ㆍ실시한 경험이 있는 민간 단체 또는 기관', 7600);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4842, '1.  피부착자의 인적사항, 긴급한 사유, 수신자료 제공기관, 요청사유 및 필요한 자료의 범위를 적은 긴급 열람ㆍ조회 요청서', 7608);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4843, '2.  자신의 신분을 표시할 수 있는 증표', 7608);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4844, '1.  성명', 7620);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4845, '2.  주민등록번호. 다만, 외국인 및 「재외동포의 출입국과 법적 지위에 관한 법률」 제2조제1호에 따른 재외국민(주민등록을 하지 아니한 경우만 해당하며, 이하 이 호에서 "재외국민"이라 한다)과 같은 조 제2호에 따른 외국국적동포(이하 "외국국적동포"라 한다)에 대해서는 다음 각 목의 구분에 따라 표기한다.', 7620);
