INSERT INTO balaw.ho (id, content, hang_id) VALUES (4869, '2.  법 제31조의3제3항에 따라 보호관찰관이 전자장치 보석피고인의 보석조건 이행 여부를 확인하기 위해 필요한 조치를 할 수 있다는 것', 7652);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4870, '3.  법원이 정한 보석조건을 위반한 경우 「형사소송법」 제102조제2항제5호에 따라 보석이 취소될 수 있다는 것', 7652);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4871, '4.  그 밖에 법원이 정한 보석조건의 이행에 필요한 사항', 7652);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4872, '1.  부착장치는 전자장치 보석피고인의 발목 또는 손목에 부착한다. 다만, 발목 또는 손목에 부착할 수 없는 특별한 사유가 있으면 다른 신체 부위에 부착할 수 있다.', 7653);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4873, '2.  재택 감독장치는 전자장치 보석피고인이 제23조의4에 따라 보호관찰소에 신고한 날 해당 피고인의 주거지에 고정하여 설치한다. 다만, 전자장치 보석피고인의 주거가 일정하지 않거나 그 밖에 재택 감독장치를 설치하기 어려운 사정이 있는 경우에는 설치하지 않을 수 있다.', 7653);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4874, '1.  정당한 사유 없이 법 제31조의3제2항에 따라 법원이 지정한 일시까지 보호관찰소에 출석하여 신고하지 않은 경우', 7657);
