INSERT INTO balaw.ho (id, content, hang_id) VALUES (4877, '4.  「형사소송법」에 따른 다른 보석조건을 위반하거나 위반 사실의 확인을 위해 필요한 보호관찰관의 정당한 지시에 따르지 않는 경우', 7657);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (4878, '5.  전자장치를 신체에서 임의로 분리ㆍ손상, 전파 방해 또는 수신자료의 변조를 하는 경우', 7657);
