INSERT INTO balaw.ho (id, content, hang_id) VALUES (5275, '1.  "사안"이란 보안관찰처분 청구, 보안관찰처분 취소청구, 보안관찰처분 기간갱신 청구, 보안관찰처분 면제결정 청구, 보안관찰처분 면제결정 취소청구 및 보안관찰처분 면제결정 신청에 관한 사안을 말한다.', 8202);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5276, '2.  "조사"란 「보안관찰법」(이하 "법"이라 한다) 제9조에 따라 군검사 및 군사법경찰관리가 하는 조사를 말한다.', 8202);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5277, '3.  "용의자"란 보안관찰처분대상자 중 보안관찰해당범죄를 다시 범할 위험성이 있다고 의심을 받는 사람으로서 「군사법원법」 제2조제1항 각 호의 어느 하나에 해당하는 사람을 말한다.', 8202);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5278, '4.  "관할방첩부대장"이란 법 제4조제1항에 따라 보안관찰처분을 받은 자(이하 "피보안관찰자"라 한다) 또는 보안관찰처분대상자가 소속되어 있는 부대를 관할하는 방첩부대의 장을 말한다.', 8202);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5279, '5.  "군검사"란 보통검찰부의 군검사를 말하고, "군사법경찰관리"란 「군사법원법」 제43조제2호 및 제46조제2호에 해당하는 사람을 말한다.', 8202);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5280, '1.  일상생활에서 사용하는 용어에 속하는 쉬운 문구를 사용한다.', 8218);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5281, '2.  복잡한 사항은 항목을 나누어 기술한다.', 8218);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5282, '3.  사투리ㆍ약어(略語)ㆍ은어(隱語) 등은 그 단어 다음에 괄호를 하고 간단한 설명을 붙인다.', 8218);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5283, '4.  외국어나 학술용어는 그 단어 다음에 괄호를 하고 간단한 설명을 붙인다.', 8218);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5284, '5.  지명ㆍ인명 등의 경우에 혼동될 염려가 있거나 특히 필요하다고 인정될 때에는 그 단어 다음에 괄호를 하고 한자 등을 병기(倂記)하거나 설명을 붙인다.', 8218);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5285, '6.  서류는 작성 연월일을 적고 진술인으로 하여금 간인(間印)하게 한 후 서명날인하도록 한다. 다만, 진술인이 서명할 수 없을 때에는 조사자가 대신 서명하되 그 사유를 적고 도장이 없는 경우에는 손도장을 찍도록 한다.', 8218);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5286, '1.  용의자에 대한 법 제18조제1항제1호부터 제7호까지의 사항 및 영 제24조제1항제1호부터 제4호까지의 사항', 8227);
