INSERT INTO balaw.ho (id, content, hang_id) VALUES (5411, '2.  피해자를 상해에 이르게 한 경우에는 3년 이상의 유기징역에 처한다.', 8436);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5412, '1.  「형법」 제329조부터 제331조까지의 죄(미수범을 포함한다)를 범한 경우에는 2년 이상 20년 이하의 징역에 처한다.', 8441);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5413, '2.  「형법」 제333조부터 제336조까지의 죄 및 제340조제1항의 죄(미수범을 포함한다)를 범한 경우에는 무기 또는 10년 이상의 징역에 처한다.', 8441);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5414, '3.  「형법」 제362조의 죄를 범한 경우에는 2년 이상 20년 이하의 징역에 처한다.', 8441);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5415, '1.  피해자를 사망에 이르게 하고 도주하거나, 도주 후에 피해자가 사망한 경우에는 무기 또는 5년 이상의 징역에 처한다.', 8451);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5416, '2.  피해자를 상해에 이르게 한 경우에는 1년 이상의 유기징역 또는 1천만원 이상 1억원 이하의 벌금에 처한다.', 8451);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5417, '1.  어린이를 사망에 이르게 한 경우에는 무기 또는 3년 이상의 징역에 처한다.', 8452);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5418, '2.  어린이를 상해에 이르게 한 경우에는 1년 이상 15년 이하의 징역 또는 500만원 이상 3천만원 이하의 벌금에 처한다.', 8452);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5419, '1.  수출 또는 수입한 물품의 가액(이하 이 조에서 "물품가액"이라 한다)이 1억원 이상인 경우에는 무기 또는 7년 이상의 징역에 처한다.', 8453);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5420, '2.  물품가액이 3천만원 이상 1억원 미만인 경우에는 3년 이상의 유기징역에 처한다.', 8453);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5421, '1.  수입한 물품의 원가가 5억원 이상인 경우에는 무기 또는 5년 이상의 징역에 처한다.', 8454);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5422, '2.  수입한 물품의 원가가 2억원 이상 5억원 미만인 경우에는 3년 이상의 유기징역에 처한다.', 8454);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5423, '1.  포탈(逋脫)ㆍ면탈(免脫)하거나 감면(減免)ㆍ환급받은 세액이 2억원 이상인 경우에는 무기 또는 5년 이상의 징역에 처한다.', 8456);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5424, '2.  포탈ㆍ면탈하거나 감면ㆍ환급받은 세액이 5천만원 이상 2억원 미만인 경우에는 3년 이상의 유기징역에 처한다.', 8456);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5425, '1.  수입한 물품의 원가가 5억원 이상인 경우에는 3년 이상의 유기징역에 처한다.', 8457);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5426, '2.  수입한 물품의 원가가 2억원 이상 5억원 미만인 경우에는 1년 이상의 유기징역에 처한다.', 8457);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5427, '1.  제1항의 경우: 물품가액의 2배 이상 10배 이하', 8458);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5428, '2.  제2항의 경우: 수입한 물품 원가의 2배', 8458);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5429, '3.  제3항의 경우: 수출하거나 반송한 물품의 원가', 8458);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5430, '4.  제4항의 경우: 포탈ㆍ면탈하거나 감면ㆍ환급받은 세액의 2배 이상 10배 이하', 8458);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5431, '5.  제5항의 경우: 수입한 물품의 원가', 8458);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5432, '1.  포탈하거나 환급받은 세액 또는 징수하지 아니하거나 납부하지 아니한 세액(이하 "포탈세액등"이라 한다)이 연간 10억원 이상인 경우에는 무기 또는 5년 이상의 징역에 처한다.', 8461);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5433, '2.  포탈세액등이 연간 5억원 이상 10억원 미만인 경우에는 3년 이상의 유기징역에 처한다.', 8461);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5434, '1.  세금계산서 및 계산서에 기재된 공급가액이나 매출처별세금계산서합계표ㆍ매입처별세금계산서합계표에 기재된 공급가액 또는 매출ㆍ매입금액의 합계액(이하 이 조에서 "공급가액등의 합계액"이라 한다)이 50억원 이상인 경우에는 3년 이상의 유기징역에 처한다.', 8463);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5435, '2.  공급가액등의 합계액이 30억원 이상 50억원 미만인 경우에는 1년 이상의 유기징역에 처한다.', 8463);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5436, '1.  임산물(林産物)의 원산지 가격이 1억원 이상이거나 산림 훼손면적이 5만제곱미터 이상인 경우에는 3년 이상 25년 이하의 징역에 처한다.', 8465);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5437, '2.  임산물의 원산지 가격이 1천만원 이상 1억원 미만이거나 산림 훼손면적이 5천제곱미터 이상 5만제곱미터 미만인 경우에는 2년 이상 20년 이하의 징역에 처한다.', 8465);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5438, '1.  수출입ㆍ제조ㆍ소지ㆍ소유 등을 한 마약이나 향정신성의약품 등의 가액이 5천만원 이상인 경우에는 무기 또는 10년 이상의 징역에 처한다.', 8467);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5439, '2.  수출입ㆍ제조ㆍ소지ㆍ소유 등을 한 마약이나 향정신성의약품 등의 가액이 500만원 이상 5천만원 미만인 경우에는 무기 또는 7년 이상의 징역에 처한다.', 8467);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5440, '1.  소지ㆍ소유ㆍ재배ㆍ사용ㆍ수출입ㆍ제조 등을 한 마약 및 향정신성의약품의 가액이 5천만원 이상인 경우에는 무기 또는 7년 이상의 징역에 처한다.', 8468);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5441, '2.  소지ㆍ소유ㆍ재배ㆍ사용ㆍ수출입ㆍ제조 등을 한 마약 및 향정신성의약품의 가액이 500만원 이상 5천만원 미만인 경우에는 무기 또는 3년 이상의 징역에 처한다.', 8468);
