INSERT INTO balaw.ho (id, content, hang_id) VALUES (5490, '1.  제2조제1호부터 제40호까지, 제45호 및 제46호의 기관 또는 단체와 농업협동조합중앙회, 수산업협동조합중앙회 및 산림조합중앙회의 임원과 과장대리급(과장대리급제가 없는 기관 또는 단체는 과장급) 이상의 직원', 8471);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5491, '2.  한국방송공사, 지역농업협동조합, 지역축산업협동조합, 품목별ㆍ업종별협동조합 및 품목조합연합회(「농업협동조합법」에 따라 설립된 것을 말한다), 지구별수산업협동조합, 업종별수산업협동조합, 수산물가공수산업협동조합, 지역산림조합 및 품목별ㆍ업종별산림조합의 임원', 8471);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5492, '1.  "군사경찰"이란 「군사법원법」 제43조제1호에 따른 병과의 장교ㆍ준사관ㆍ부사관ㆍ병(兵)과 「군무원인사법」에 따른 군무원으로서 군사경찰부대에 소속되어 군사에 관한 경찰의 직무를 수행하는 사람 중 대통령령으로 정하는 사람을 말한다.', 8474);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5493, '2.  "군사지역"이란 「군사기지 및 군사시설 보호법」 제2조제1호ㆍ제2호에 따른 군사기지 및 군사시설과 같은 법 제5조제1항제1호가목의 민간인통제선 이북(以北)지역을 말한다.', 8474);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5494, '3.  "군사경찰장비"란 군사경찰의 직무수행을 위하여 필요한 것으로서 무기, 군사경찰장구, 최루제와 그 발사장치, 음주측정기, 속도측정기, 감식기구, 해안 감시기구, 통신기기, 차량ㆍ선박ㆍ항공기 등의 장치와 기구를 말한다.', 8474);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5495, '4.  "위해성 군사경찰장비"란 군사경찰장비 중 다른 사람의 생명이나 신체에 위해를 끼칠 수 있는 군사경찰장비를 말한다.', 8474);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5496, '5.  "군사경찰장구"란 군사경찰이 휴대하여 범인검거와 범죄 진압 등의 직무수행에 사용하는 수갑ㆍ포승(捕繩)ㆍ경찰봉ㆍ전자충격기ㆍ전자충격총 및 방패 등 대통령령으로 정하는 장치와 기구를 말한다.', 8474);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5497, '6.  "분사기등"이란 「총포ㆍ도검ㆍ화약류 등의 안전관리에 관한 법률」에 따른 분사기와 그에 사용하는 최루 등의 작용제 및 최루탄을 말한다.', 8474);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5498, '7.  "무기"란 사람의 생명이나 신체에 위해를 끼칠 수 있도록 제작된 권총ㆍ소총ㆍ도검 등을 말한다.', 8474);
