INSERT INTO balaw.ho (id, content, hang_id) VALUES (5513, '2.  자신이나 다른 사람의 생명ㆍ신체ㆍ재산 또는 군사지역에 대한 현저한 위해의 발생 억제', 8503);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5514, '1.  「형법」 제21조 및 제22조에 따른 정당방위와 긴급피난에 해당할 때', 8504);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5515, '2.  다음 각 목의 어느 하나에 해당하는 때에 그 행위를 방지하거나 그 행위자를 체포하기 위하여 무기를 사용하지 아니하고는 다른 수단이 없다고 인정되는 상당한 이유가 있을 때', 8504);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5516, '1.  「형법」 제2편제24장 살인의 죄, 제25장 상해와 폭행의 죄, 제32장 강간과 추행의 죄 중 강간에 관한 범죄, 제38장 절도와 강도의 죄 중 강도에 관한 범죄 및 이에 대하여 다른 법률에 따라 가중처벌하는 범죄', 8511);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5517, '2.  「가정폭력범죄의 처벌 등에 관한 특례법」에 따른 가정폭력범죄, 「아동학대범죄의 처벌 등에 관한 특례법」에 따른 아동학대범죄', 8511);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5518, '1.  국방부, 합동참모본부 및 국방부 직할부대ㆍ기관에 소속된 사람: 국방부장관', 8515);
