INSERT INTO balaw.ho (id, content, hang_id) VALUES (5524, '3.  법 제7조제3항에 따라 무기 또는 흉기 소지에 관하여 조사한 경우', 8517);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5525, '4.  법 제8조에 따라 범죄행위를 예방하기 위한 경고를 하거나 범죄행위를 제지한 경우', 8517);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5526, '5.  법 제9조제1항에 따라 다른 사람의 토지ㆍ건물ㆍ배 또는 차에 출입한 경우', 8517);
