INSERT INTO balaw.ho (id, content, hang_id) VALUES (5537, '1.  수갑 및 포승의 경우: 다음 각 목의 어느 하나에 해당하는 경우에 최소한의 범위에서 사용할 것', 8522);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5538, '2.  경찰봉의 경우: 생명 또는 신체에 대한 위해를 최소화하도록 주의할 것', 8522);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5539, '3.  전자충격기, 전자충격총 및 고무탄총의 경우: 상대방의 얼굴을 향해 전자충격을 가하거나 전극침 또는 고무탄을 발사하지 말 것', 8522);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5540, '4.  최루제와 그 발사장치의 경우: 다음 각 목의 어느 하나에 해당하는 경우에 최소한의 범위에서 사용할 것. 이 경우 30도 이상의 발사각을 유지해야 하며, 1미터 이내의 거리에서 상대방의 얼굴을 향하여 발사해서는 안 된다.', 8522);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5541, '1.  신규도입장비의 주요 특성 및 기본적인 작동 원리', 8526);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5542, '2.  안전성 검사의 방법 및 기준', 8526);
