INSERT INTO balaw.ho (id, content, hang_id) VALUES (5545, '1.  손실을 입은 물건을 수리할 수 있는 경우: 수리비에 해당하는 금액', 8528);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5546, '2.  손실을 입은 물건을 수리할 수 없는 경우: 손실을 입은 당시의 해당 물건의 교환가액', 8528);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5547, '3.  영업자가 손실을 입은 물건의 수리나 교환으로 인하여 영업을 계속할 수 없는 경우: 영업을 계속할 수 없는 기간 중 영업상 이익에 해당하는 금액', 8528);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5548, '1.  청구인이 같은 청구 원인으로 보상신청을 하여 보상금 지급 여부에 대하여 결정을 받은 경우. 다만, 기각 결정을 받은 청구인이 손실을 증명할 수 있는 새로운 증거가 발견되었음을 소명하는 경우는 제외한다.', 8533);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5549, '2.  손실보상 청구가 요건과 절차를 갖추지 못한 경우. 다만, 그 잘못된 부분을 시정할 수 있는 경우는 제외한다.', 8533);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5550, '1.  보상금을 지급하기로 결정한 경우: 별지 제3호서식의 보상금 지급 청구 승인 통지서', 8534);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5551, '2.  보상금 지급 청구를 각하하거나 보상금을 지급하지 않기로 결정한 경우: 별지 제4호서식의 보상금 지급 청구 각하ㆍ기각 통지서', 8534);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5552, '1.  별표 3 제2호에 따른 부상등급이 변경된 경우(부상등급 외의 부상에서 제1급부터 제8급까지의 등급으로 변경된 경우를 포함한다)', 8537);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5553, '2.  별표 3 제2호에 따른 부상등급 외의 부상에 대하여 부상등급의 변경은 없으나 보상금의 추가 지급이 필요한 경우', 8537);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5554, '1.  판사ㆍ검사ㆍ군법무관 또는 변호사로 5년 이상 재직한 사람', 8540);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5555, '2.  「고등교육법」 제2조에 따른 학교에서 법학 또는 행정학을 가르치는 부교수 이상으로 5년 이상 재직한 사람', 8540);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5556, '3.  손실보상에 관하여 학식과 경험이 풍부한 사람', 8540);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5557, '1.  위원 또는 그 배우자나 배우자였던 사람이 심의 안건의 청구인인 경우', 8549);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5558, '2.  위원이 심의 안건의 청구인과 친족이거나 친족이었던 경우', 8549);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5559, '3.  위원이 심의 안건에 대하여 증언, 진술, 자문, 용역 또는 감정을 한 경우', 8549);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5560, '4.  위원이나 위원이 속한 법인이 심의 안건 청구인의 대리인이거나 대리인이었던 경우', 8549);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5561, '5.  위원이 해당 심의 안건의 청구인인 법인의 임원인 경우', 8549);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5562, '1.  심신장애로 인하여 직무를 수행할 수 없게 된 경우', 8552);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5563, '2.  직무태만, 품위손상이나 그 밖의 사유로 위원으로 적합하지 않다고 인정되는 경우', 8552);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5564, '3.  제19조제1항 각 호의 어느 하나에 해당하는데도 불구하고 회피하지 않은 경우', 8552);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5565, '4.  제21조를 위반하여 직무상 알게 된 비밀을 누설한 경우', 8552);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5566, '1.  법 제5조제1항제3호의 직무: 「개인정보 보호법 시행령」 제18조제2호에 따른 범죄경력자료에 해당하는 정보, 같은 영 제19조에 따른 주민등록번호, 여권번호, 운전면허의 면허번호 또는 외국인등록번호', 8553);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5567, '2.  법 제5조제1항제4호의 직무: 「개인정보 보호법」 제23조에 따른 건강에 관한 정보 또는 같은 법 시행령 제19조제1호에 따른 주민등록번호', 8553);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5568, '1.  성별, 나이, 거주지역 등 조사대상자의 일반적 특성에 관한 사항', 8554);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5569, '2.  스토킹의 발생 원인 및 배경', 8554);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5570, '3.  스토킹의 유형, 특성 및 빈도', 8554);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5571, '4.  온라인 활동 증대 등 사회환경 변화에 따른 스토킹 현황 및 변화 추세', 8554);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5572, '5.  그 밖에 스토킹 방지를 위한 정책수립의 기초자료로 활용하기 위하여 여성가족부장관이 필요하다고 인정하는 사항', 8554);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5573, '1.  「고등교육법」 제2조 각 호의 학교 및 그 밖에 다른 법령에 따라 설립ㆍ운영되는 이에 준하는 학교', 8556);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5574, '2.  「공직자윤리법 시행령」 제3조의2제2항에 따라 인사혁신처장이 관보에 공직유관단체로 고시한 기관ㆍ단체(같은 조 제3항에 따라 공직유관단체에서 제외된 것으로 보는 기관ㆍ단체는 제외한다)', 8556);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5575, '1.  「공공기관의 운영에 관한 법률」 제5조에 따른 공기업 및 준정부기관', 8557);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5576, '2.  「지방공기업법」 제78조제1항에 따라 경영평가의 대상이 되는 지방공기업', 8557);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5577, '1.  스토킹 사건 처리경과 및 조치결과에 관한 사항', 8559);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5578, '2.  스토킹 방지 조치 및 스토킹 예방교육의 실시 등에 관한 사항', 8559);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5579, '3.  법 제6조에 따른 피해자 또는 스토킹 사실을 신고한 사람에 대한 불이익조치 금지 및 보호조치 마련 등 2차 피해 방지에 관한 사항', 8559);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5580, '4.  그 밖에 해당 기관 내 스토킹 사건의 재발방지를 위하여 필요한 사항', 8559);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5581, '1.  「초ㆍ중등교육법」 제2조제1호에 따른 초등학교', 8561);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5582, '', 8561);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5583, '1.  정부출연기관', 8564);
