INSERT INTO balaw.ho (id, content, hang_id) VALUES (5702, '3.  중앙행정기관ㆍ지방자치단체가 관계 법령에 따라 개선, 시정 등을 명한 사항의 이행에 관한 조치', 8737);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5703, '4.  안전ㆍ보건 관계 법령에 따른 의무이행에 필요한 관리상의 조치', 8737);
