INSERT INTO balaw.ho (id, content, hang_id) VALUES (5708, '3.  중앙행정기관ㆍ지방자치단체가 관계 법령에 따라 개선, 시정 등을 명한 사항의 이행에 관한 조치', 8746);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5709, '4.  안전ㆍ보건 관계 법령에 따른 의무이행에 필요한 관리상의 조치', 8746);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5710, '1.  재해예방에 필요한 인력ㆍ예산ㆍ점검 등 안전보건관리체계의 구축 및 그 이행에 관한 조치', 8747);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5711, '2.  재해 발생 시 재발방지 대책의 수립 및 그 이행에 관한 조치', 8747);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5712, '3.  중앙행정기관ㆍ지방자치단체가 관계 법령에 따라 개선, 시정 등을 명한 사항의 이행에 관한 조치', 8747);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5713, '4.  안전ㆍ보건 관계 법령에 따른 의무이행에 필요한 관리상의 조치', 8747);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5714, '1.  제10조제1항의 경우: 50억원 이하의 벌금', 8752);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5715, '2.  제10조제2항의 경우: 10억원 이하의 벌금', 8752);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5716, '1.  고의 또는 중대한 과실의 정도', 8758);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5717, '2.  이 법에서 정한 의무위반행위의 종류 및 내용', 8758);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5718, '3.  이 법에서 정한 의무위반행위로 인하여 발생한 피해의 규모', 8758);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5719, '4.  이 법에서 정한 의무위반행위로 인하여 사업주나 법인 또는 기관이 취득한 경제적 이익', 8758);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5720, '5.  이 법에서 정한 의무위반행위의 기간ㆍ횟수 등', 8758);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5721, '6.  사업주나 법인 또는 기관의 재산상태', 8758);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5722, '7.  사업주나 법인 또는 기관의 피해구제 및 재발방지 노력의 정도', 8758);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5723, '1.  중대재해의 종합적인 예방대책의 수립ㆍ시행과 발생원인 분석', 8759);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5724, '2.  사업주, 법인 및 기관의 안전보건관리체계 구축을 위한 지원', 8759);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5725, '3.  사업주, 법인 및 기관의 중대재해 예방을 위한 기술 지원 및 지도', 8759);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5726, '4.  이 법의 목적 달성을 위한 교육 및 홍보의 시행', 8759);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5727, '1.  법 제2조제4호가목의 시설 중 별표 2에서 정하는 시설', 8762);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5728, '2.  법 제2조제4호나목의 시설물 중 별표 3에서 정하는 시설물. 다만, 다음 각 목의 건축물은 제외한다.', 8762);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5729, '3.  법 제2조제4호다목의 영업장', 8762);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5730, '4.  법 제2조제4호라목의 시설 중 다음 각 목의 시설(제2호의 시설물은 제외한다)', 8762);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5731, '1.  사업 또는 사업장의 안전ㆍ보건에 관한 목표와 경영방침을 설정할 것', 8763);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5732, '2.  「산업안전보건법」 제17조부터 제19조까지 및 제22조에 따라 두어야 하는 인력이 총 3명 이상이고 다음 각 목의 어느 하나에 해당하는 사업 또는 사업장인 경우에는 안전ㆍ보건에 관한 업무를 총괄ㆍ관리하는 전담 조직을 둘 것. 이 경우 나목에 해당하지 않던 건설사업자가 나목에 해당하게 된 경우에는 공시한 연도의 다음 연도 1월 1일까지 해당 조직을 두어야 한다.', 8763);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5733, '3.  사업 또는 사업장의 특성에 따른 유해ㆍ위험요인을 확인하여 개선하는 업무절차를 마련하고, 해당 업무절차에 따라 유해ㆍ위험요인의 확인 및 개선이 이루어지는지를 반기 1회 이상 점검한 후 필요한 조치를 할 것. 다만, 「산업안전보건법」 제36조에 따른 위험성평가를 하는 절차를 마련하고, 그 절차에 따라 위험성 평가를 직접 실시하거나 실시하도록 하여 실시 결과를 보고받은 경우에는 해당 업무절차에 따라 유해ㆍ위험요인의 확인 및 개선에 대한 점검을 한 것으로 본다.', 8763);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5734, '4.  다음 각 목의 사항을 이행하는 데 필요한 예산을 편성하고 그 편성된 용도에 맞게 집행하도록 할 것', 8763);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5735, '5.  「산업안전보건법」 제15조, 제16조 및 제62조에 따른 안전보건관리책임자, 관리감독자 및 안전보건총괄책임자(이하 이 조에서 "안전보건관리책임자등"이라 한다)가 같은 조에서 규정한 각각의 업무를 각 사업장에서 충실히 수행할 수 있도록 다음 각 목의 조치를 할 것', 8763);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5736, '6.  「산업안전보건법」 제17조부터 제19조까지 및 제22조에 따라 정해진 수 이상의 안전관리자, 보건관리자, 안전보건관리담당자 및 산업보건의를 배치할 것. 다만, 다른 법령에서 해당 인력의 배치에 대해 달리 정하고 있는 경우에는 그에 따르고, 배치해야 할 인력이 다른 업무를 겸직하는 경우에는 고용노동부장관이 정하여 고시하는 기준에 따라 안전ㆍ보건에 관한 업무 수행시간을 보장해야 한다.', 8763);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5737, '7.  사업 또는 사업장의 안전ㆍ보건에 관한 사항에 대해 종사자의 의견을 듣는 절차를 마련하고, 그 절차에 따라 의견을 들어 재해 예방에 필요하다고 인정하는 경우에는 그에 대한 개선방안을 마련하여 이행하는지를 반기 1회 이상 점검한 후 필요한 조치를 할 것. 다만, 「산업안전보건법」 제24조에 따른 산업안전보건위원회 및 같은 법 제64조ㆍ제75조에 따른 안전 및 보건에 관한 협의체에서 사업 또는 사업장의 안전ㆍ보건에 관하여 논의하거나 심의ㆍ의결한 경우에는 해당 종사자의 의견을 들은 것으로 본다.', 8763);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5738, '8.  사업 또는 사업장에 중대산업재해가 발생하거나 발생할 급박한 위험이 있을 경우를 대비하여 다음 각 목의 조치에 관한 매뉴얼을 마련하고, 해당 매뉴얼에 따라 조치하는지를 반기 1회 이상 점검할 것', 8763);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5739, '9.  제3자에게 업무의 도급, 용역, 위탁 등을 하는 경우에는 종사자의 안전ㆍ보건을 확보하기 위해 다음 각 목의 기준과 절차를 마련하고, 그 기준과 절차에 따라 도급, 용역, 위탁 등이 이루어지는지를 반기 1회 이상 점검할 것', 8763);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5740, '1.  안전ㆍ보건 관계 법령에 따른 의무를 이행했는지를 반기 1회 이상 점검(해당 안전ㆍ보건 관계 법령에 따라 중앙행정기관의 장이 지정한 기관 등에 위탁하여 점검하는 경우를 포함한다. 이하 이 호에서 같다)하고, 직접 점검하지 않은 경우에는 점검이 끝난 후 지체 없이 점검 결과를 보고받을 것', 8765);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5741, '2.  제1호에 따른 점검 또는 보고 결과 안전ㆍ보건 관계 법령에 따른 의무가 이행되지 않은 사실이 확인되는 경우에는 인력을 배치하거나 예산을 추가로 편성ㆍ집행하도록 하는 등 해당 의무 이행에 필요한 조치를 할 것', 8765);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5742, '3.  안전ㆍ보건 관계 법령에 따라 의무적으로 실시해야 하는 유해ㆍ위험한 작업에 관한 안전ㆍ보건에 관한 교육이 실시되었는지를 반기 1회 이상 점검하고, 직접 점검하지 않은 경우에는 점검이 끝난 후 지체 없이 점검 결과를 보고받을 것', 8765);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5743, '4.  제3호에 따른 점검 또는 보고 결과 실시되지 않은 교육에 대해서는 지체 없이 그 이행의 지시, 예산의 확보 등 교육 실시에 필요한 조치를 할 것', 8765);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5744, '1.  안전보건관리체계의 구축 등 안전ㆍ보건에 관한 경영 방안', 8767);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5745, '2.  중대산업재해의 원인 분석과 재발 방지 방안', 8767);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5746, '1.  안전보건교육을 실시하는 안전보건교육기관등', 8769);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5747, '2.  교육일정', 8769);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5748, '3.  그 밖에 안전보건교육의 실시에 필요한 사항', 8769);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5749, '1.  다음 각 목의 사항을 이행하는 데 필요한 인력을 갖추어 중대시민재해 예방을 위한 업무를 수행하도록 할 것', 8777);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5750, '2.  다음 각 목의 사항을 이행하는 데 필요한 예산을 편성ㆍ집행할 것', 8777);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5751, '3.  별표 5에서 정하는 원료 또는 제조물로 인한 중대시민재해를 예방하기 위해 다음 각 목의 조치를 할 것', 8777);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5752, '4.  제3호 각 목의 조치를 포함한 업무처리절차의 마련. 다만, 「소상공인기본법」 제2조에 따른 소상공인의 경우는 제외한다.', 8777);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5753, '5.  제1호 및 제2호의 사항을 반기 1회 이상 점검하고, 점검 결과에 따라 인력을 배치하거나 예산을 추가로 편성ㆍ집행하도록 하는 등 중대시민재해 예방에 필요한 조치를 할 것', 8777);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5754, '1.  안전ㆍ보건 관계 법령에 따른 의무를 이행했는지를 반기 1회 이상 점검(해당 안전ㆍ보건 관계 법령에 따라 중앙행정기관의 장이 지정한 기관 등에 위탁하여 점검하는 경우를 포함한다. 이하 이 호에서 같다)하고, 직접 점검하지 않은 경우에는 점검이 끝난 후 지체 없이 점검 결과를 보고받을 것', 8779);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5755, '2.  제1호에 따른 점검 또는 보고 결과 안전ㆍ보건 관계 법령에 따른 의무가 이행되지 않은 사실이 확인되는 경우에는 인력을 배치하거나 예산을 추가로 편성ㆍ집행하도록 하는 등 해당 의무 이행에 필요한 조치를 할 것', 8779);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5756, '3.  안전ㆍ보건 관계 법령에 따라 의무적으로 실시해야 하는 교육이 실시되는지를 반기 1회 이상 점검하고, 직접 점검하지 않은 경우에는 점검이 끝난 후 지체 없이 점검 결과를 보고받을 것', 8779);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5757, '4.  제3호에 따른 점검 또는 보고 결과 실시되지 않은 교육에 대해서는 지체 없이 그 이행의 지시, 예산의 확보 등 교육 실시에 필요한 조치를 할 것', 8779);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5758, '1.  다음 각 목의 사항을 이행하는 데 필요한 인력을 갖추어 중대시민재해 예방을 위한 업무를 수행하도록 할 것', 8780);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5759, '2.  다음 각 목의 사항을 이행하는 데 필요한 예산을 편성ㆍ집행할 것', 8780);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5760, '3.  공중이용시설 또는 공중교통수단에 대한 법 제9조제2항제4호의 안전ㆍ보건 관계 법령에 따른 안전점검 등을 계획하여 수행되도록 할 것', 8780);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5761, '4.  공중이용시설 또는 공중교통수단에 대해 연 1회 이상 다음 각 목의 내용이 포함된 안전계획을 수립하게 하고, 충실히 이행하도록 할 것. 다만, 공중이용시설에 대해 「시설물의 안전 및 유지관리에 관한 특별법」 제6조에 따라 시설물에 대한 안전 및 유지관리계획을 수립ㆍ시행하거나 공중이용시설 또는 공중교통수단에 대해 철도운영자가 「철도안전법」 제6조에 따라 연차별 시행계획을 수립ㆍ추진하는 경우로서 사업주 또는 경영책임자등이 그 수립 여부 및 내용을 직접 확인하거나 보고받은 경우에는 안전계획을 수립하여 이행한 것으로 본다.', 8780);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5762, '5.  제1호부터 제4호까지에서 규정한 사항을 반기 1회 이상 점검하고, 직접 점검하지 않은 경우에는 점검이 끝난 후 지체 없이 점검 결과를 보고받을 것', 8780);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5763, '6.  제5호에 따른 점검 또는 보고 결과에 따라 인력을 배치하거나 예산을 추가로 편성ㆍ집행하도록 하는 등 중대시민재해 예방에 필요한 조치를 할 것', 8780);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5764, '7.  중대시민재해 예방을 위해 다음 각 목의 사항이 포함된 업무처리절차를 마련하여 이행할 것. 다만, 철도운영자가 「철도안전법」 제7조에 따라 비상대응계획을 포함한 철도안전관리체계를 수립하여 시행하거나 항공운송사업자가 「항공안전법」 제58조제2항에 따라 위기대응계획을 포함한 항공안전관리시스템을 마련하여 운용한 경우로서 사업주 또는 경영책임자등이 그 수립 여부 및 내용을 직접 점검하거나 점검 결과를 보고받은 경우에는 업무처리절차를 마련하여 이행한 것으로 본다.', 8780);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5765, '8.  제3자에게 공중이용시설 또는 공중교통수단의 운영ㆍ관리 업무의 도급, 용역, 위탁 등을 하는 경우 공중이용시설 또는 공중교통수단과 그 이용자나 그 밖의 사람의 안전을 확보하기 위해 다음 각 목에 따른 기준과 절차를 마련하고, 그 기준과 절차에 따라 도급, 용역, 위탁 등이 이루어지는지를 연 1회 이상 점검하고, 직접 점검하지 않은 경우에는 점검이 끝난 후 지체 없이 점검 결과를 보고받을 것', 8780);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5766, '1.  안전ㆍ보건 관계 법령에 따른 의무를 이행했는지를 연 1회 이상 점검(해당 안전ㆍ보건 관계 법령에 따라 중앙행정기관의 장이 지정한 기관 등에 위탁하여 점검하는 경우를 포함한다. 이하 이 호에서 같다)하고, 직접 점검하지 않은 경우에는 점검이 끝난 후 지체 없이 점검 결과를 보고받을 것', 8782);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5767, '2.  제1호에 따른 점검 또는 보고 결과 안전ㆍ보건 관계 법령에 따른 의무가 이행되지 않은 사실이 확인되는 경우에는 인력을 배치하거나 예산을 추가로 편성ㆍ집행하도록 하는 등 해당 의무 이행에 필요한 조치를 할 것', 8782);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5768, '3.  안전ㆍ보건 관계 법령에 따라 공중이용시설의 안전을 관리하는 자나 공중교통수단의 시설 및 설비를 정비ㆍ점검하는 종사자가 의무적으로 이수해야 하는 교육을 이수했는지를 연 1회 이상 점검하고, 직접 점검하지 않은 경우에는 점검이 끝난 후 지체 없이 점검 결과를 보고받을 것', 8782);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5769, '4.  제3호에 따른 점검 또는 보고 결과 실시되지 않은 교육에 대해서는 지체 없이 그 이행의 지시 등 교육 실시에 필요한 조치를 할 것', 8782);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5770, '1.  "중대산업재해 발생사실의 공표"라는 공표의 제목', 8784);
