INSERT INTO balaw.ho (id, content, hang_id) VALUES (5774, '5.  중대산업재해의 내용과 그 원인(사업주 또는 경영책임자등의 위반사항을 포함한다)', 8784);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5775, '6.  해당 사업장에서 최근 5년 내 중대산업재해의 발생 여부', 8784);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5776, '1.  외자(外資)의 전대(轉貸)', 8788);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5777, '2.  어음의 매입', 8788);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5778, '3.  설비 또는 운전자금의 투융자, 대부, 지급, 지급보증, 금전융자, 채권취득 등 그 명목에 관계없이 금융회사등이 그 업무와 관련하여 자금수요자에게 자금을 융통하여 주거나 채무를 보증하여 주는 것', 8788);
