INSERT INTO balaw.ho (id, content, hang_id) VALUES (5785, '1.  법 제3조ㆍ법 제4조제2항(미수범을 포함한다)ㆍ법 제5조제4항 또는 법 제8조에 따라 유죄판결을 받은 사람의 공범(법 제5조제4항에 따라 유죄판결을 받은 사람에 대응하여 법 제6조의 죄를 범한 사람을 포함한다. 이하 이 항에서 같다)이나 공범의 직계 존ㆍ비속, 형제자매, 배우자가 출자한 기업체로서 그 출자한 금액의 합계액이 발행주식 또는 출자금의 총액의 100분의 5 이상인 기업체', 8794);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5786, '2.  법 제3조ㆍ법 제4조제2항 (미수범을 포함한다) 법 제5조제4항 또는 법 제8조에 따라 유죄판결을 받은 사람의 공범이 그 범행 당시 임원 또는 과장급 이상의 간부직원으로 있었거나 임원 또는 과장급 이상의 간부직원으로 있는 기업체', 8794);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5787, '3.  법 제3조ㆍ법 제4조제2항(미수범을 포함한다)ㆍ법 제5조제4항 또는 법 제8조에 따라 유죄판결된 범죄행위로 인하여 재산상 이득을 취득한 기업체 또는 재산상 손해를 입은 기업체', 8794);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5788, '4.  법 제3조ㆍ법 제5조제4항 및 법 제8조에 따라 유죄판결을 받은 사람의 범죄행위로 인하여 재산상 이득을 취득한 제3자 또는 그 제3자의 직계 존ㆍ비속, 형제자매, 배우자가 출자한 기업체로서 그 출자한 금액의 합계액이 제1호에 규정된 기준 이상인 기업체', 8794);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5789, '5.  제4호에 따른 제3자가 범죄행위 당시 임원 또는 과장급 이상의 간부직원으로 있었거나 임원 또는 과장급 이상의 간부직원으로 있는 기업체', 8794);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5790, '6.  제1호부터 제5호까지의 어느 하나에 해당하는 기업체가 출자한 기업체로서 그 출자한 금액이 제1호에 규정된 기준 이상인 기업체', 8794);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (5791, '1.  법 제14조제1항 단서 또는 같은 조 제2항 단서에 따른 취업 승인이나 허가등의 승인에 관한 사무', 8801);
