INSERT INTO balaw.ho (id, content, hang_id) VALUES (6011, '1.  "사안"이라 함은 보안관찰처분청구, 보안관찰처분취소청구, 보안관찰처분기간갱신청구, 보안관찰처분면제결정청구, 보안관찰처분면제결정취소청구 및 보안관찰처분면제결정신청에 관한 사안을 말한다.', 9061);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6012, '2.  "관할검사장"이라 함은 관할지방검찰청 검사장 또는 지청장을 말한다.', 9061);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6013, '3.  "관할경찰서장"이라 함은 보안관찰처분대상자 또는 피보안관찰자의 주거지를 관할하는 경찰서장을 말한다.', 9061);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6014, '4.  "조사"라 함은 법 제9조의 규정에 의한 조사를 말한다.', 9061);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6015, '5.  "용의자"라 함은 보안관찰처분대상자 중 보안관찰해당범죄를 다시 범할 위험성이 있다고 의심을 받는 자를 말한다.', 9061);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6016, '1.  일상용어에 속하는 쉬운 문구를 사용한다.', 9081);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6017, '2.  복잡한 사항은 항목을 나누어 기술한다.', 9081);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6018, '3.  사투리ㆍ약어ㆍ은어등은 그 다음에 괄호를 하고 간단한 설명을 붙인다.', 9081);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6019, '4.  외국어 또는 학술용어는 그 다음에 괄호를 하고 간단한 설명을 붙인다.', 9081);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6020, '5.  지명ㆍ인명 등에 있어서 혼동될 염려가 있거나 특히 필요하다고 인정될 때에는 그 다음에 괄호를 하고 한자등을 기입하거나 설명을 붙인다.', 9081);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6021, '6.  서류는 작성연월일을 기재하고 진술인으로 하여금 간인하게 한 후 서명ㆍ날인하도록 한다. 다만, 진술인이 서명할 수 없는 때에는 조사자가 대신 서명하되, 그  사유를 기재하고 인장이 없는 때에는 무인하도록 한다.', 9081);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6022, '1.  용의자에 대한 법 제18조제1항제1호 내지 제7호 및 영 제24조제1항제1호 내지 제4호의 사항', 9090);
