INSERT INTO balaw.ho (id, content, hang_id) VALUES (6077, '1.  "형사사법업무"란 수사, 공소, 공판, 재판의 집행 등 형사사건의 처리와 관련된 업무를 말한다.', 9178);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6078, '2.  "형사사법업무 처리기관"이란 법원, 법무부, 검찰청, 경찰청, 해양경찰청, 고위공직자범죄수사처 및 그 소속 기관과 그 밖에 형사사법업무를 처리하는 기관으로서 대통령령으로 정하는 기관을 말한다.', 9178);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6079, '3.  "형사사법정보"란 형사사법업무 처리기관이 형사사법업무 처리와 관련하여 형사사법정보시스템을 이용하여 작성하거나 취득하여 관리하고 있는 자료로서 전자적 방식으로 처리되어 부호, 문자, 음성, 음향 또는 영상 등으로 표현된 것을 말한다.', 9178);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6080, '4.  "형사사법정보시스템"이란 형사사법업무 처리기관이 형사사법정보를 작성, 취득, 저장, 송신ㆍ수신하는 데 이용할 수 있도록 하드웨어, 소프트웨어, 데이터베이스, 네트워크, 보안요소 등을 결합시켜 구축한 전자적 관리체계를 말한다.', 9178);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6081, '5.  "형사사법정보공통시스템"이란 형사사법정보시스템(이하 "시스템"이라 한다) 중 둘 이상의 형사사법업무 처리기관이 공동으로 사용하는 시스템을 말한다.', 9178);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6082, '6.  "형사사법포털"이란 국민이 형사사법정보에 쉽고 신속하게 접근할 수 있도록 형사사법정보공통시스템(이하 "공통시스템"이라 한다)에 구축된 형사사법 관련 서비스 포털을 말한다.', 9178);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6083, '1.  형사사법업무 전자화 추진의 기본방향', 9181);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6084, '2.  형사사법업무 전자화 추진조직 및 체계에 관한 사항', 9181);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6085, '3.  전자화 대상 문서 등의 선정ㆍ개발 등에 관한 사항', 9181);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6086, '4.  공동 활용되는 형사사법정보의 범위에 관한 사항', 9181);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6087, '5.  형사사법업무 전자화에 따르는 관련 법령 및 제도의 정비에 관한 사항', 9181);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6088, '6.  전자화된 형사사법절차에서의 정보공개, 정보보호 대책 등 기본권 보장에 관한 사항', 9181);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6089, '7.  그 밖에 형사사법업무의 전자화 촉진을 위하여 필요한 사항', 9181);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6090, '1.  형사사법업무의 전자화를 통한 형사사법절차의 개선에 관한 사항', 9198);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6091, '2.  형사사법정보의 유통표준 및 그 변경에 관한 사항', 9198);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6092, '3.  시스템을 통한 형사사법업무 처리기관 간 형사사법정보의 공동 활용 및 그 변경에 관한 사항', 9198);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6093, '4.  공통시스템을 통한 형사사법정보의 공개 등 형사사법포털의 내용 및 운영에 관한 사항', 9198);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6094, '5.  공통시스템의 대상, 범위, 변경, 운영 및 관리에 관한 사항', 9198);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6095, '6.  형사사법업무 처리기관 간 공동 활용되는 형사사법정보의 보호에 관한 사항', 9198);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6096, '7.  형사사법정보의 유통표준에 영향을 미치는 시스템의 변경, 개발 및 개선에 관한 사항', 9198);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6097, '1.  피의자, 피해자, 참고인 등 사건관계인이 직접 작성하는 문서', 9210);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6098, '2.  시스템에 작성 기능이 구현되어 있지 아니한 문서', 9210);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6099, '3.  시스템을 이용할 수 없는 시간 또는 장소에서 불가피하게 작성하여야 하거나 시스템 장애 또는 전산망 오류 등으로 시스템을 이용할 수 없는 상황에서 불가피하게 작성하여야 하는 문서', 9210);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6100, '1.  송신 대상 형사사법정보는 전자문서 출력물의 내용과 동일할 것', 9211);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6101, '2.  전자문서 출력물의 내용과 송신 대상 형사사법정보가 동일하다는 사실을 추정할 수 있도록 전자문서 출력물에는 출력기관, 출력일, 면수 및 총면수, 문서의 고유식별번호 등이 표시될 것', 9211);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6102, '1.  형사사법업무 처리기관 간에 송신ㆍ수신되는 정보의 세부적인 사항은 제5조에 따른 각 기관의 운영세칙에 명시할 것', 9213);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6103, '2.  형사사법업무 처리기관은 유통문서의 내용과 송신 정보가 정확히 일치되도록 노력하여야 하며, 일치하지 않은 정보가 송신된 경우에는 일치하는 정보를 다시 송신할 것', 9213);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6104, '3.  형사사법업무 처리기관은 다른 형사사법업무 처리기관의 시스템에 영향을 미칠 수 있는 시스템상의 장애가 발생한 경우에는 즉시 그 사실을 통보하고, 시스템 개발 등의 사유로 시스템 가동을 일시 정지할 필요가 있는 경우에는 미리 그 사실을 통보하여 다른 형사사법업무 처리기관의 업무 처리에 지장이 없도록 할 것', 9213);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6105, '1.  공통시스템 관련 하드웨어, 시스템소프트웨어, 응용소프트웨어 등에 대한 운영ㆍ관리 및 정보보호에 관한 업무', 9218);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6106, '2.  형사사법업무 처리기관 간 정보유통 연계관리 등 공통시스템의 지원 업무', 9218);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6107, '3.  공통시스템의 고도화 등 공통시스템 개발사업에 관한 업무', 9218);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6108, '4.  그 밖에 운영단의 업무를 추진하기 위하여 필요한 업무', 9218);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6109, '1.  법 제3조에 따른 형사사법절차의 전자화 촉진에 관한 사무', 9249);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6110, '2.  법 제5조에 따른 시스템의 안정적 운영을 위한 사무', 9249);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6111, '3.  법 제6조에 따른 형사사법정보 공동 활용에 관한 사무', 9249);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6112, '4.  법 제7조에 따른 형사사법 관련 서비스 제공에 관한 사무', 9249);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6113, '5.  법 제8조에 따른 시스템의 운영ㆍ관리를 위한 사무', 9249);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6114, '6.  제1호부터 제5호까지의 규정에 따른 사무를 수행하기 위하여 필요한 사무', 9249);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6115, '1.  법에서 규정한 범죄의 단속 사무에 종사하는 공무원이 직무와 관련하여 신고를 한 경우', 9257);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6116, '2.  법 제7조제1항의 규정에 의하여 수사기관에 신고할 의무가 있는 자 또는 그 대리인이 신고를 한 경우', 9257);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6117, '3.  성을 사는 행위를 한 자가 이와 관련하여 신고를 한 경우', 9257);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6118, '4.  삭제 <2008.10.20>', 9257);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6119, '1.  "벌금 미납자"란 법원으로부터 벌금을 선고받아 확정되었는데도 그 벌금을 내지 아니한 사람을 말한다.', 9258);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6120, '2.  "사회봉사"란 보호관찰관이 지정한 일시와 장소에서 공공의 이익을 위하여 실시하는 무보수 근로를 말한다.', 9258);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6121, '3.  "사회봉사 대상자"란 벌금 미납자의 신청에 따른 검사의 청구로 법원이 사회봉사를 허가한 사람을 말한다.', 9258);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6122, '1.  징역 또는 금고와 동시에 벌금을 선고받은 사람', 9260);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6123, '2.  「형법」 제69조제1항 단서에 따라 법원으로부터 벌금 선고와 동시에 벌금을 완납할 때까지 노역장에 유치할 것을 명받은 사람', 9260);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6124, '3.  다른 사건으로 형 또는 구속영장이 집행되거나 노역장에 유치되어 구금 중인 사람', 9260);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6125, '4.  사회봉사를 신청하는 해당 벌금에 대하여 법원으로부터 사회봉사를 허가받지 못하거나 취소당한 사람. 다만, 사회봉사 불허가 사유가 소멸한 경우에는 그러하지 아니하다.', 9260);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6126, '1.  제4조제1항에 따른 벌금의 범위를 초과하거나 신청 기간이 지난 사람이 신청을 한 경우', 9269);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6127, '2.  제4조제2항에 따라 사회봉사를 신청할 수 없는 사람이 신청을 한 경우', 9269);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6128, '3.  정당한 사유 없이 제3항에 따른 법원의 출석 요구나 자료제출 요구를 거부한 경우', 9269);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6129, '4.  신청인이 일정한 수입원이나 재산이 있어 벌금을 낼 수 있다고 판단되는 경우', 9269);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6130, '5.  질병이나 그 밖의 사유로 사회봉사를 이행하기에 부적당하다고 판단되는 경우', 9269);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6131, '1.  정당한 사유 없이 제8조제1항의 신고를 하지 아니하는 경우', 9289);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6132, '2.  제11조의 기간 내에 사회봉사를 마치지 아니한 경우', 9289);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6133, '3.  정당한 사유 없이 「보호관찰 등에 관한 법률」 제62조제2항의 준수사항을 위반하거나 구금 등의 사유로 사회봉사를 계속 집행하기에 적당하지 아니하다고 판단되는 경우', 9289);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6134, '1.  사회봉사의 집행을 마친 경우', 9297);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6135, '2.  사회봉사 대상자가 벌금을 완납한 경우', 9297);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6136, '3.  제14조에 따라 사회봉사 허가가 취소된 경우', 9297);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6137, '4.  사회봉사 대상자가 사망한 경우', 9297);
