INSERT INTO balaw.ho (id, content, hang_id) VALUES (6161, '3.  법 제12조제2항에 따른 사회봉사 집행 확인에 관한 사무', 9313);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6162, '4.  법 제14조에 따른 사회봉사 허가의 취소에 관한 사무', 9313);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6163, '1.  「공중화장실 등에 관한 법률」 제2조제1호부터 제5호까지의 규정에 따른 공중화장실, 개방화장실, 이동화장실, 간이화장실 또는 유료화장실', 9316);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6164, '2.  「공중위생관리법」 제2조제1항제3호에 따른 목욕장업의 목욕장', 9316);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6165, '3.  「모자보건법」 제10조의3에 따른 모유수유시설로서 임산부가 영유아에게 모유를 먹일 수 있도록 설치된 장소', 9316);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6166, '4.  다음 각 목의 어느 하나에 해당하는 시설에 설치된 탈의실 또는 목욕실', 9316);
