INSERT INTO balaw.ho (id, content, hang_id) VALUES (6168, '2.  법 제22조의2제2항제3호 각 목에 해당하는 촬영물 또는 복제물 등을 구입하거나 무상으로 제공받는 등의 방법', 9320);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6169, '1.  촬영물 또는 복제물의 제공ㆍ판매 여부', 9324);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6170, '2.  제1호에 따른 제공ㆍ판매가 이루어진 경우 그 대상ㆍ범위ㆍ기간ㆍ장소 및 방법', 9324);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6171, '1.  「성폭력방지 및 피해자보호 등에 관한 법률」 제7조의4에 따른 중앙디지털성범죄피해자지원센터 및 지역디지털성범죄피해자지원센터', 9332);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6172, '2.  「성폭력방지 및 피해자보호 등에 관한 법률」 제10조에 따른 성폭력피해상담소, 같은 법 제12조에 따른 성폭력피해자보호시설 및 같은 법 제18조에 따른 성폭력피해자통합지원센터', 9332);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6173, '3.  「범죄피해자 보호법」 제7조제2항에 따른 일시적 보호시설 및 같은 법 제33조에 따른 범죄피해자 지원법인', 9332);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6174, '1.  성명: 한글과 한자(한자 성명이 있는 경우만 해당한다)로 표기하되, 외국인인 경우 한글과 영문으로 표기한다.', 9333);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6175, '2.  주민등록번호. 다만, 외국인 및 「재외동포의 출입국과 법적 지위에 관한 법률」 제2조제1호에 따른 재외국민(주민등록을 하지 아니한 경우만 해당하며, 이하 "재외국민"이라 한다)과 같은 조 제2호에 따른 외국국적동포(이하 "외국국적동포"라 한다)에 대해서는 다음 각 목의 구분에 따라 표기한다.', 9333);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6176, '3.  주소 및 실제거주지: 다음 각 목의 구분에 따라 표기한다.', 9333);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6177, '4.  직업 및 직장 등의 소재지: 직업, 직장명, 직장 소재지의 주소를 표기한다.', 9333);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6178, '5.  연락처: 다음 각 목과 같이 구분하여 표기한다.', 9333);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6179, '6.  신체정보(키와 몸무게): 키는 센티미터로, 몸무게는 킬로그램으로 각각 표기한다.', 9333);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6180, '7.  소유차량의 등록번호: 본인 명의로 등록된 모든 차량의 등록번호를 표기한다.', 9333);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6181, '1.  주민등록증(모바일 주민등록증을 포함하며, 재외국민의 경우에는 여권을 말한다)ㆍ운전면허증 또는 학생증', 9335);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6182, '2.  여권 및 외국인등록증(외국인만 해당한다)', 9335);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6183, '3.  여권 및 「재외동포의 출입국과 법적 지위에 관한 법률」 제7조에 따른 국내거소신고증 또는 국내거소신고 사실증명(외국국적동포인 경우만 해당한다)', 9335);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6184, '4.  재직증명서', 9335);
