INSERT INTO balaw.ho (id, content, hang_id) VALUES (6250, '1.  증거보전기일, 공판준비기일 또는 공판기일에 그 내용에 대하여 피의자, 피고인 또는 변호인이 피해자를 신문할 수 있었던 경우. 다만, 증거보전기일에서의 신문의 경우 법원이 피의자나 피고인의 방어권이 보장된 상태에서 피해자에 대한 반대신문이 충분히 이루어졌다고 인정하는 경우로 한정한다.', 9484);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6251, '2.  19세미만피해자등이 다음 각 목의 어느 하나에 해당하는 사유로 공판준비기일 또는 공판기일에 출석하여 진술할 수 없는 경우. 다만, 영상녹화된 진술 및 영상녹화가 특별히 신빙(信憑)할 수 있는 상태에서 이루어졌음이 증명된 경우로 한정한다.', 9484);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6252, '1.  제3조부터 제8조까지, 제10조, 제14조, 제14조의2, 제14조의3, 제15조(제9조의 미수범은 제외한다) 및 제15조의2에 따른 범죄의 피해자', 9499);
