INSERT INTO balaw.ho (id, content, hang_id) VALUES (6255, '2.  금고 이상의 실형을 선고받고 그 집행이 종료(집행이 종료된 것으로 보는 경우를 포함한다)되거나 집행이 면제된 날부터 5년이 지나지 아니한 사람', 9505);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6256, '3.  금고 이상의 형의 집행을 유예받고 그 유예기간이 완료된 날부터 2년이 지나지 아니한 사람', 9505);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6257, '4.  금고 이상의 형의 선고를 유예받고 그 유예기간 중에 있는 사람', 9505);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6258, '5.  제2호부터 제4호까지의 규정에도 불구하고 다음 각 목의 어느 하나에 해당하는 범죄를 저지른 사람으로서 형 또는 치료감호를 선고받고 확정된 후 그 형 또는 치료감호의 전부 또는 일부의 집행이 끝나거나(집행이 끝난 것으로 보는 경우를 포함한다) 집행이 유예ㆍ면제된 날부터 10년이 지나지 아니한 사람', 9505);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6259, '6.  제35조의3(이 조 제1호에 해당하게 되어 제35조의3제1항제2호에 따라 진술조력인의 자격이 취소된 경우는 제외한다)에 따라 진술조력인 자격이 취소된 후 3년이 지나지 아니한 사람', 9505);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6260, '1.  거짓이나 그 밖의 부정한 방법으로 자격을 취득한 사실이 드러난 경우', 9506);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6261, '2.  제35조의2 각 호의 결격사유 중 어느 하나에 해당하게 된 경우', 9506);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6262, '3.  제38조에 따른 진술조력인의 의무를 위반한 경우', 9506);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6263, '4.  고의나 중대한 과실로 업무 수행에 중대한 지장이 발생하게 된 경우', 9506);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6264, '5.  진술조력인의 업무 수행과 관련하여 부당한 금품을 수령하는 등 부정한 행위를 한 경우', 9506);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6265, '6.  정당한 사유 없이 법무부령으로 정하는 교육을 이수하지 않은 경우', 9506);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6266, '7.  그 밖에 진술조력인의 업무를 수행할 수 없는 중대한 사유가 발생한 경우', 9506);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6267, '1.  성명', 9539);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6268, '2.  주민등록번호', 9539);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6269, '3.  주소 및 실제거주지', 9539);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6270, '4.  직업 및 직장 등의 소재지', 9539);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6271, '5.  연락처(전화번호, 전자우편주소를 말한다)', 9539);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6272, '6.  신체정보(키와 몸무게)', 9539);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6273, '7.  소유차량의 등록번호', 9539);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6274, '1.  등록대상 성범죄 경력정보', 9550);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6275, '2.  성범죄 전과사실(죄명, 횟수)', 9550);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6276, '3.  「전자장치 부착 등에 관한 법률」에 따른 전자장치 부착 여부', 9550);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6277, '1.  신상정보 등록의 원인이 된 성범죄로 사형, 무기징역ㆍ무기금고형 또는 10년 초과의 징역ㆍ금고형을 선고받은 사람: 30년', 9557);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6278, '2.  신상정보 등록의 원인이 된 성범죄로 3년 초과 10년 이하의 징역ㆍ금고형을 선고받은 사람: 20년', 9557);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6279, '3.  신상정보 등록의 원인이 된 성범죄로 3년 이하의 징역ㆍ금고형을 선고받은 사람 또는 「아동ㆍ청소년의 성보호에 관한 법률」 제49조제1항제4호에 따라 공개명령이 확정된 사람: 15년', 9557);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6280, '4.  신상정보 등록의 원인이 된 성범죄로 벌금형을 선고받은 사람: 10년', 9557);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6281, '1.  하나의 판결에서 신상정보 등록의 원인이 된 성범죄로 여러 종류의 형이 선고된 경우에는 가장 무거운 종류의 형을 기준으로 한다.', 9559);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6282, '2.  하나의 판결에서 신상정보 등록의 원인이 된 성범죄로 여러 개의 징역형 또는 금고형이 선고된 경우에는 각각의 기간을 합산한다. 이 경우 징역형과 금고형은 같은 종류의 형으로 본다.', 9559);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6283, '3.  「소년법」 제60조에 따라 부정기형이 선고된 경우에는 단기를 기준으로 한다.', 9559);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6284, '1.  등록대상자가 신상정보 등록의 원인이 된 성범죄로 교정시설 또는 치료감호시설에 수용된 기간', 9561);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6285, '2.  제1호에 따른 기간 이전의 기간으로서 제1호에 따른 기간과 이어져 등록대상자가 다른 범죄로 교정시설 또는 치료감호시설에 수용된 기간', 9561);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6286, '3.  제1호에 따른 기간 이후의 기간으로서 제1호에 따른 기간과 이어져 등록대상자가 다른 범죄로 교정시설 또는 치료감호시설에 수용된 기간', 9561);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6287, '1.  제1항에 따른 등록기간이 30년인 등록대상자: 3개월', 9563);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6288, '2.  제1항에 따른 등록기간이 20년 또는 15년인 등록대상자: 6개월', 9563);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6289, '3.  제1항에 따른 등록기간이 10년인 등록대상자: 1년', 9563);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6290, '1.  「아동ㆍ청소년의 성보호에 관한 법률」 제49조에 따른 공개대상자인 경우: 공개기간', 9564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6291, '2.  「아동ㆍ청소년의 성보호에 관한 법률」 제50조에 따른 고지대상자인 경우: 고지기간', 9564);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6292, '1.  제45조제1항에 따른 등록기간이 30년인 등록대상자: 최초등록일부터 20년', 9566);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6293, '2.  제45조제1항에 따른 등록기간이 20년인 등록대상자: 최초등록일부터 15년', 9566);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6294, '3.  제45조제1항에 따른 등록기간이 15년인 등록대상자: 최초등록일부터 10년', 9566);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6295, '4.  제45조제1항에 따른 등록기간이 10년인 등록대상자: 최초등록일부터 7년', 9566);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6296, '1.  등록기간 중 등록대상 성범죄를 저질러 유죄판결이 확정된 사실이 없을 것', 9567);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6297, '2.  신상정보 등록의 원인이 된 성범죄로 선고받은 징역형 또는 금고형의 집행을 종료하거나 벌금을 완납하였을 것', 9567);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6298, '3.  신상정보 등록의 원인이 된 성범죄로 부과받은 다음 각 목의 명령의 집행을 모두 종료하였을 것', 9567);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6299, '4.  신상정보 등록의 원인이 된 성범죄로 부과받은 다음 각 목의 규정에 따른 보호관찰명령, 사회봉사명령, 수강명령 또는 이수명령의 집행을 완료하였을 것', 9567);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6300, '5.  등록기간 중 다음 각 목의 범죄를 저질러 유죄판결을 선고받아 그 판결이 확정된 사실이 없을 것', 9567);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6301, '1.  제45조제1항의 등록기간이 지난 때', 9569);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6302, '2.  제45조의2에 따라 등록이 면제된 때', 9569);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6303, '1.  제22조의8을 위반하여 직무상 알게 된 신분비공개수사 또는 신분위장수사에 관한 사항을 외부에 공개하거나 누설한 자', 9586);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6304, '2.  제48조를 위반하여 직무상 알게 된 등록정보를 누설한 자', 9586);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6305, '3.  정당한 권한 없이 등록정보를 변경하거나 말소한 자', 9586);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6306, '1.  제24조제1항 또는 제38조제2항에 따른 피해자의 신원과 사생활 비밀 누설 금지 의무를 위반한 자', 9587);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6307, '2.  제24조제2항을 위반하여 피해자의 인적사항과 사진 등을 공개한 자', 9587);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6308, '1.  제43조제1항을 위반하여 정당한 사유 없이 기본신상정보를 제출하지 아니하거나 거짓으로 제출한 자 및 같은 조 제2항에 따른 관할경찰관서 또는 교정시설의 장의 사진촬영에 정당한 사유 없이 응하지 아니한 자', 9588);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6309, '2.  제43조제3항(제44조제6항에서 준용하는 경우를 포함한다)을 위반하여 정당한 사유 없이 변경정보를 제출하지 아니하거나 거짓으로 제출한 자', 9588);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6310, '3.  제43조제4항(제44조제6항에서 준용하는 경우를 포함한다)을 위반하여 정당한 사유 없이 관할 경찰관서에 출석하지 아니하거나 촬영에 응하지 아니한 자', 9588);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6311, '1.  벌금형과 병과된 경우는 500만원 이하의 벌금에 처한다.', 9590);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6312, '2.  징역형 이상의 실형(치료감호와 징역형 이상의 실형이 병과된 경우를 포함한다)과 병과된 경우에는 1년 이하의 징역 또는 5백만원 이하의 벌금에 처한다.', 9590);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6313, '1.  「공중화장실 등에 관한 법률」 제2조제1호부터 제5호까지의 규정에 따른 공중화장실, 개방화장실, 이동화장실, 간이화장실 또는 유료화장실', 9593);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6314, '2.  「공중위생관리법」 제2조제1항제3호에 따른 목욕장업의 목욕장', 9593);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6315, '3.  「모자보건법」 제10조의3에 따른 모유수유시설로서 임산부가 영유아에게 모유를 먹일 수 있도록 설치된 장소', 9593);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6316, '4.  다음 각 목의 어느 하나에 해당하는 시설에 설치된 탈의실 또는 목욕실', 9593);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6317, '1.  대화에 직접 참여하거나 관찰하는 방법', 9597);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6318, '2.  법 제22조의2제2항제3호 각 목에 해당하는 촬영물 또는 복제물 등을 구입하거나 무상으로 제공받는 등의 방법', 9597);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6319, '1.  촬영물 또는 복제물의 제공ㆍ판매 여부', 9601);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6320, '2.  제1호에 따른 제공ㆍ판매가 이루어진 경우 그 대상ㆍ범위ㆍ기간ㆍ장소 및 방법', 9601);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6321, '1.  「성폭력방지 및 피해자보호 등에 관한 법률」 제7조의4에 따른 중앙디지털성범죄피해자지원센터 및 지역디지털성범죄피해자지원센터', 9609);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6322, '2.  「성폭력방지 및 피해자보호 등에 관한 법률」 제10조에 따른 성폭력피해상담소, 같은 법 제12조에 따른 성폭력피해자보호시설 및 같은 법 제18조에 따른 성폭력피해자통합지원센터', 9609);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6323, '3.  「범죄피해자 보호법」 제7조제2항에 따른 일시적 보호시설 및 같은 법 제33조에 따른 범죄피해자 지원법인', 9609);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6324, '1.  성명: 한글과 한자(한자 성명이 있는 경우만 해당한다)로 표기하되, 외국인인 경우 한글과 영문으로 표기한다.', 9610);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6325, '2.  주민등록번호. 다만, 외국인 및 「재외동포의 출입국과 법적 지위에 관한 법률」 제2조제1호에 따른 재외국민(주민등록을 하지 아니한 경우만 해당하며, 이하 "재외국민"이라 한다)과 같은 조 제2호에 따른 외국국적동포(이하 "외국국적동포"라 한다)에 대해서는 다음 각 목의 구분에 따라 표기한다.', 9610);
