INSERT INTO balaw.ho (id, content, hang_id) VALUES (6362, '1.  "차"란 「도로교통법」 제2조제17호가목에 따른 차(車)와 「건설기계관리법」 제2조제1항제1호에 따른 건설기계를 말한다.', 9658);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6363, '2.  "교통사고"란 차의 교통으로 인하여 사람을 사상(死傷)하거나 물건을 손괴(損壞)하는 것을 말한다.', 9658);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6364, '1.  「도로교통법」 제5조에 따른 신호기가 표시하는 신호 또는 교통정리를 하는 경찰공무원등의 신호를 위반하거나 통행금지 또는 일시정지를 내용으로 하는 안전표지가 표시하는 지시를 위반하여 운전한 경우', 9660);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6365, '2.  「도로교통법」 제13조제3항을 위반하여 중앙선을 침범하거나 같은 법 제62조를 위반하여 횡단, 유턴 또는 후진한 경우', 9660);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6366, '3.  「도로교통법」 제17조제1항 또는 제2항에 따른 제한속도를 시속 20킬로미터 초과하여 운전한 경우', 9660);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6367, '4.  「도로교통법」 제21조제1항, 제22조, 제23조에 따른 앞지르기의 방법ㆍ금지시기ㆍ금지장소 또는 끼어들기의 금지를 위반하거나 같은 법 제60조제2항에 따른 고속도로에서의 앞지르기 방법을 위반하여 운전한 경우', 9660);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6368, '5.  「도로교통법」 제24조에 따른 철길건널목 통과방법을 위반하여 운전한 경우', 9660);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6369, '6.  「도로교통법」 제27조제1항에 따른 횡단보도에서의 보행자 보호의무를 위반하여 운전한 경우', 9660);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6370, '7.  「도로교통법」 제43조, 「건설기계관리법」 제26조 또는 「도로교통법」 제96조를 위반하여 운전면허 또는 건설기계조종사면허를 받지 아니하거나 국제운전면허증을 소지하지 아니하고 운전한 경우. 이 경우 운전면허 또는 건설기계조종사면허의 효력이 정지 중이거나 운전의 금지 중인 때에는 운전면허 또는 건설기계조종사면허를 받지 아니하거나 국제운전면허증을 소지하지 아니한 것으로 본다.', 9660);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6371, '8.  「도로교통법」 제44조제1항을 위반하여 술에 취한 상태에서 운전을 하거나 같은 법 제45조를 위반하여 약물의 영향으로 정상적으로 운전하지 못할 우려가 있는 상태에서 운전한 경우', 9660);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6372, '9.  「도로교통법」 제13조제1항을 위반하여 보도(步道)가 설치된 도로의 보도를 침범하거나 같은 법 제13조제2항에 따른 보도 횡단방법을 위반하여 운전한 경우', 9660);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6373, '10.  「도로교통법」 제39조제3항에 따른 승객의 추락 방지의무를 위반하여 운전한 경우', 9660);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6374, '11.  「도로교통법」 제12조제3항에 따른 어린이 보호구역에서 같은 조 제1항에 따른 조치를 준수하고 어린이의 안전에 유의하면서 운전하여야 할 의무를 위반하여 어린이의 신체를 상해(傷害)에 이르게 한 경우', 9660);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6375, '12.  「도로교통법」 제39조제4항을 위반하여 자동차의 화물이 떨어지지 아니하도록 필요한 조치를 하지 아니하고 운전한 경우', 9660);
