INSERT INTO balaw.ho (id, content, hang_id) VALUES (6388, '1.  "인적사항등"이란 「디엔에이신원확인정보의 이용 및 보호에 관한 법률」(이하 "법"이라 한다) 제5조 또는 제6조에 따른 디엔에이감식시료 채취대상자의 성명, 주민등록번호(외국인의 경우에는 외국인등록번호, 여권번호 등을 말한다) 등 인적사항 및 디엔에이감식시료의 채취 또는 그 원인이 된 사건과 관련된 정보를 말한다.', 9674);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6389, '2.  "식별코드"란 개인 식별을 위하여 법 제5조 또는 제6조에 따른 디엔에이감식시료 채취대상자의 인적사항을 대신하여 디엔에이신원확인정보데이터베이스(이하 "데이터베이스"라 한다)에 수록되는 것으로 숫자, 문자 또는 기호 등을 조합하여 생성된 분류체계를 말한다.', 9674);
