INSERT INTO balaw.ho (id, content, hang_id) VALUES (6401, '1.  채취 일시와 장소 및 방법, 채취한 디엔에이감식시료의 종류 등을 적은 서류', 9688);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6402, '2.  디엔에이감식시료채취영장 또는 디엔에이감식시료채취동의서', 9688);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6403, '1.  검사 또는 사법경찰관(군사법경찰관은 제외한다)이 법 제7조에 따라 디엔에이감식시료를 채취한 경우: 검찰 디엔에이신원확인정보담당자 또는 경찰 디엔에이신원확인정보담당자', 9691);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6404, '2.  군사법경찰관이 법 제7조에 따라 디엔에이감식시료를 채취한 경우: 법 제10조 및 이 영 제12조제2항제2호에 따라 법 제7조에 따라 채취한 디엔에이감식시료의 감식업무를 위탁받은 국방부 조사본부장(이하 "군 디엔에이감식기관"이라 한다)', 9691);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6405, '1.  법 제10조제1항 각 호의 업무(제2호의 업무는 제외한다): 국립과학수사연구원에 위탁', 9694);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6406, '2.  군사법경찰관이 법 제7조에 따라 채취한 디엔에이감식시료의 감식업무: 국방부 조사본부장에게 위탁', 9694);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6407, '1.  법 제5조 또는 제6조에 따른 디엔에이감식시료 채취대상자로부터 채취한 디엔에이감식시료를 감식하여 취득한 디엔에이신원확인정보를 법 제7조에 따라 채취한 디엔에이감식시료를 감식하여 취득한 디엔에이신원확인정보가 수록된 데이터베이스에서 검색ㆍ대조한 결과 디엔에이신원확인정보가 일치하는 사실을 발견한 경우: 법 제5조 또는 제6조에 따른 디엔에이감식시료 채취대상자로부터 채취한 디엔에이감식시료를 감식한 디엔에이신원확인정보담당자', 9700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6408, '2.  법 제7조에 따라 채취한 디엔에이감식시료를 감식하여 취득한 디엔에이신원확인정보를 법 제5조 및 제6조에 따른 디엔에이감식시료 채취대상자로부터 채취한 디엔에이감식시료를 감식한 디엔에이신원확인정보를 수록한 데이터베이스에서 검색ㆍ대조한 결과 디엔에이신원확인정보가 일치하는 사실을 발견한 경우: 법 제5조 또는 제6조에 따른 디엔에이감식시료 채취대상자로부터 채취한 디엔에이감식시료를 감식한 디엔에이신원확인정보담당자', 9700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6409, '3.  법 제7조에 따라 채취한 디엔에이감식시료를 감식하여 취득한 디엔에이신원확인정보를 법 제7조에 따라 채취한 디엔에이감식시료를 감식하여 취득한 디엔에이신원확인정보가 수록된 데이터베이스에서 검색ㆍ대조한 경우: 해당 데이터베이스를 관리하는 디엔에이신원확인정보담당자', 9700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6410, '4.  그 밖의 경우: 디엔에이신원확인정보를 검색ㆍ대조한 디엔에이신원확인정보담당자', 9700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6411, '1.  법 제11조제1항제1호 및 제4호에 따른 디엔에이신원확인정보 검색결과의 회보의 경우: 해당 사건을 담당한 검사 또는 사법경찰관', 9701);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6412, '2.  법 제11조제1항제2호 및 제3호에 따른 디엔에이신원확인정보 검색결과의 회보의 경우: 검색을 요청한 검사, 사법경찰관 또는 법원(군사법원을 포함한다. 이하 같다)', 9701);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6413, '1.  법 제13조제1항부터 제3항까지 규정에 따른 디엔에이신원확인정보의 삭제 사유가 발생한 경우(제2호의 경우는 제외한다): 검사 또는 사법경찰관이 검찰 디엔에이인적관리자 또는 경찰 디엔에이인적관리자에게 통보', 9708);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6414, '2.  수용기관에 수용되어 있던 사람에게 법 제13조제3항의 사유가 발생한 경우: 수용기관의 장이 검찰 디엔에이인적관리자 또는 경찰 디엔에이인적관리자에게 통보', 9708);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6415, '1.  법 제4조제3항 및 이 영 제5조에 따른 데이터베이스 간의 전자적 연계를 통한 디엔에이신원확인정보의 상호 검색에 관한 사항', 9712);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6416, '2.  식별코드 표준화에 관한 사항', 9712);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6417, '3.  디엔에이신원확인정보 표준화에 관한 사항', 9712);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6418, '1.  심신장애로 인하여 직무를 수행할 수 없게 된 경우', 9720);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6419, '2.  직무수행 과정에서 취득한 비밀을 누설하거나 직무수행 과정에서 취득한 정보를 허가되지 아니한 방법으로 연구 등에 활용하는 경우', 9720);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6420, '3.  직무와 관련된 비위사실이 있는 경우', 9720);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6421, '4.  직무태만, 품위손상이나 그 밖의 사유로 인하여 위원으로 적합하지 아니하다고 인정되는 경우', 9720);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6422, '5.  위원 스스로 직무를 수행하는 것이 곤란하다고 의사를 밝히는 경우', 9720);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6423, '1.  이미 해당 사건에 관하여 충분히 진술하여 다시 진술할 필요가 없다고 인정되는 경우', 9731);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6424, '2.  의견진술 또는 질문으로 인하여 공판절차가 현저하게 지연될 우려가 있다고 인정되는 경우', 9731);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6425, '3.  의견진술과 질문이 해당사건과 관계없는 사항에 해당된다고 인정되는 경우', 9731);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6426, '4.  기타 피해자 변호사의 의견진술로서 상당하지 아니하다고 인정되는 경우', 9731);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6427, '1.  재판의 진행절차, 법정의 구조와 좌석의 위치, 증인신문의 의미, 증인신문의 순서와 방법, 증언과 피해자 의견진술의 방법 및 절차, 재판서 등ㆍ초본 교부청구 절차 등에 대한 안내', 9749);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6428, '2.  증인신문 전후 증인의 심리적 안정을 위한 상담', 9749);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6429, '3.  증인지원시설의 적정한 관리 및 운영에 필요한 업무', 9749);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6430, '4.  피해자 증인의 요청에 의한 재판장의 명에 따른 공판진행 사항에 관한 정보제공 업무', 9749);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6431, '5.  그 밖에 증인의 보호 및 지원을 위하여 필요한 업무로서 증인지원위원회의 심의를 거쳐 각급 법원장(지원의 경우에는 지원장)이 증인지원관의 업무로 정한 업무', 9749);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6432, '1.  증인지원시설의 설치 및 운영에 관한 사항', 9752);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6433, '2.  증인지원관의 업무에 관한 사항', 9752);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6434, '3.  증인 보호 및 지원 업무의 개선에 관한 사항', 9752);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6435, '4.  그 밖에 증인의 보호 및 지원을 위하여 필요한 사항', 9752);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6436, '1.  피고인 또는 피해자의 친족 또는 친족 관계에 있었던 사람', 9761);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6437, '2.  피고인 또는 피해자의 법정대리인', 9761);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6438, '3.  피고인의 대리인 또는 변호인', 9761);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6439, '3.  피해자의 대리인 또는 변호사', 9761);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6440, '1.  「성폭력범죄의 처벌 등에 관한 특례법」제35조의3(다른 법률에서 위 규정을 준용하는 경우를 포함한다)에 따라 진술조력인 자격이 취소된 경우', 9763);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6441, '2.  제19조제3항 각 호에서 정한 선정 금지 사유가 발견된 경우', 9763);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6442, '3.  피해자, 법정대리인 또는 변호사가 진술조력인 선정의 취소를 요청하고 그 요청에 상당한 이유가 있는 경우', 9763);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6443, '4.  진술조력인이 사임의 의사를 표시하고 이에 상당한 이유가 있는 경우', 9763);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6444, '5.  진술조력인이 그 업무를 성실하게 수행하지 아니하는 경우', 9763);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6445, '6.  그 밖에 진술조력인 업무를 수행하기 어려운 중대한 사유가 발생한 경우', 9763);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6446, '1.  증인이 이해할 수 있는 증인신문의 방식', 9772);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6447, '2.  증인이 이해하지 못하거나 휴식이 필요할 때 법원에 알리는 방식', 9772);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6448, '3.  그 밖에 진술조력인에 의한 증인의 의사소통이나 의사표현의 중개ㆍ보조에 필요한 사항', 9772);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6449, '1.  "교정업무(矯正業務)"란 「형의 집행 및 수용자의 처우에 관한 법률」 제2조제4호에 따른 수용자(이하 "수용자"라 한다)의 수용ㆍ관리, 교정(矯正)ㆍ교화(敎化), 직업교육, 교도작업(矯導作業), 분류ㆍ처우, 그 밖에 「형의 집행 및 수용자의 처우에 관한 법률」에서 정하는 업무를 말한다.', 9788);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6450, '2.  "수탁자(受託者)"란 제3조에 따라 교정업무를 위탁받기로 선정된 자를 말한다.', 9788);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6451, '3.  "교정법인"이란 법무부장관으로부터 교정업무를 포괄적으로 위탁받아 교도소ㆍ소년교도소 또는 구치소 및 그 지소(이하 "교도소등"이라 한다)를 설치ㆍ운영하는 법인을 말한다.', 9788);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6452, '4.  "민영교도소등"이란 교정법인이 운영하는 교도소등을 말한다.', 9788);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6453, '1.  수탁자가 교도소등의 설치비용을 부담하는 경우: 10년 이상 20년 이하', 9795);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6454, '2.  그 밖의 경우: 1년 이상 5년 이하', 9795);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6455, '1.  위탁업무를 수행할 때 수탁자가 제공하여야 하는 시설과 교정업무의 기준에 관한 사항', 9796);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6456, '2.  수탁자에게 지급하는 위탁의 대가와 그 금액의 조정(調整) 및 지급 방법에 관한 사항', 9796);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6457, '3.  계약기간에 관한 사항과 계약기간의 수정ㆍ갱신 및 계약의 해지에 관한 사항', 9796);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6458, '4.  교도작업에서의 작업장려금ㆍ위로금 및 조위금 지급에 관한 사항', 9796);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6459, '5.  위탁업무를 재위탁할 수 있는 범위에 관한 사항', 9796);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6460, '6.  위탁수용 대상자의 범위에 관한 사항', 9796);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6461, '7.  그 밖에 법무부장관이 필요하다고 인정하는 사항', 9796);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6462, '1.  제22조제2항에 따른 보정명령(補正命令)을 받고 상당한 기간이 지난 후에도 이행하지 아니한 경우', 9801);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6463, '2.  이 법 또는 이 법에 따른 명령이나 처분을 크게 위반한 경우로서 제6조제1항에 따른 위탁업무의 정지명령으로는 감독의 목적을 달성할 수 없는 경우', 9801);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6464, '3.  사업 경영의 현저한 부실 또는 재무구조의 악화, 그 밖의 사유로 이 법에 따른 위탁업무를 계속하는 것이 적합하지 아니하다고 인정되는 경우', 9801);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6465, '1.  「국가공무원법」 제33조 각 호의 어느 하나에 해당하는 자', 9808);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6466, '2.  제12조에 따라 임원취임 승인이 취소된 후 2년이 지나지 아니한 자', 9808);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6467, '3.  제36조에 따른 해임명령으로 해임된 후 2년이 지나지 아니한 자', 9808);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6468, '1.  제13조를 위반하여 겸직하는 경우', 9810);
