INSERT INTO balaw.ho (id, content, hang_id) VALUES (6652, '1.  "판결서 등"이란 판결서ㆍ증거목록ㆍ기록목록(각 그 등본을 포함한다) 또는 이에 해당하는 정보를 말한다.', 9961);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6653, '2.  "법원사무관 등"이란 법원서기관ㆍ법원사무관ㆍ법원주사 또는 법원주사보를 말한다.', 9961);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6654, '3.  "전산정보처리시스템"이란 법에 따른 절차에 필요한 서류를 작성ㆍ제출ㆍ송달하거나 관리하는 데에 이용되는 정보처리능력을 가진 전자적 장치 또는 체계로서 법원행정처장이 지정하는 것을 말한다.', 9961);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6655, '4.  "비실명 처리"란 판결서 등에 나타난 정보 중에서 그대로 공개될 경우 개인의 사생활이 침해될 수 있는 사항에 관하여 제3자가 인식하지 못하도록 비실명으로 표시하는 것을 말한다.', 9961);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6656, '5.  "개인정보"란 「개인정보 보호법」 제2조제1호의 개인정보를 말한다.', 9961);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6657, '6.  "소송관계인"이란 피고인ㆍ검사ㆍ변호인ㆍ보조인ㆍ법인인 피고인의 대표자ㆍ법 제28조에 따른 특별대리인ㆍ법 제340조 및 제341조제1항에 따른 상소권자ㆍ피해자 또는 그 법정대리인ㆍ증인 또는 그 법정대리인을 말한다.', 9961);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6658, '7.  "이해관계 있는 제3자"란 제6호의 소송관계인 외에 고소인ㆍ고발인ㆍ참고인ㆍ감정인ㆍ통역인ㆍ번역인 등 해당 사건에 관여하거나 직접적인 이해관계를 가지는 사람을 말한다.', 9961);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6659, '1.  (빈집 등에의 침입) 다른 사람이 살지 아니하고 관리하지 아니하는 집 또는 그 울타리ㆍ건조물(建造物)ㆍ배ㆍ자동차 안에 정당한 이유 없이 들어간 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6660, '2.  (흉기의 은닉휴대) 칼ㆍ쇠몽둥이ㆍ쇠톱 등 사람의 생명 또는 신체에 중대한 위해를 끼치거나 집이나 그 밖의 건조물에 침입하는 데에 사용될 수 있는 연장이나 기구를 정당한 이유 없이 숨겨서 지니고 다니는 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6661, '3.  (폭행 등 예비) 다른 사람의 신체에 위해를 끼칠 것을 공모(共謀)하여 예비행위를 한 사람이 있는 경우 그 공모를 한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6662, '4.  삭제 <2013.5.22>', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6663, '5.  (시체 현장변경 등) 사산아(死産兒)를 감추거나 정당한 이유 없이 변사체 또는 사산아가 있는 현장을 바꾸어 놓은 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6664, '6.  (도움이 필요한 사람 등의 신고불이행) 자기가 관리하고 있는 곳에 도움을 받아야 할 노인, 어린이, 장애인, 다친 사람 또는 병든 사람이 있거나 시체 또는 사산아가 있는 것을 알면서 이를 관계 공무원에게 지체 없이 신고하지 아니한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6665, '7.  (관명사칭 등) 국내외의 공직(公職), 계급, 훈장, 학위 또는 그 밖에 법령에 따라 정하여진 명칭이나 칭호 등을 거짓으로 꾸며 대거나 자격이 없으면서 법령에 따라 정하여진 제복, 훈장, 기장 또는 기념장(記念章), 그 밖의 표장(標章) 또는 이와 비슷한 것을 사용한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6666, '8.  (물품강매ㆍ호객행위) 요청하지 아니한 물품을 억지로 사라고 한 사람, 요청하지 아니한 일을 해주거나 재주 등을 부리고 그 대가로 돈을 달라고 한 사람 또는 여러 사람이 모이거나 다니는 곳에서 영업을 목적으로 떠들썩하게 손님을 부른 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6667, '9.  (광고물 무단부착 등) 다른 사람 또는 단체의 집이나 그 밖의 인공구조물과 자동차 등에 함부로 광고물 등을 붙이거나 내걸거나 끼우거나 글씨 또는 그림을 쓰거나 그리거나 새기는 행위 등을 한 사람 또는 다른 사람이나 단체의 간판, 그 밖의 표시물 또는 인공구조물을 함부로 옮기거나 더럽히거나 훼손한 사람 또는 공공장소에서 광고물 등을 함부로 뿌린 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6668, '10.  (마시는 물 사용방해) 사람이 마시는 물을 더럽히거나 사용하는 것을 방해한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6669, '11.  (쓰레기 등 투기) 담배꽁초, 껌, 휴지, 쓰레기, 죽은 짐승, 그 밖의 더러운 물건이나 못쓰게 된 물건을 함부로 아무 곳에나 버린 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6670, '12.  (노상방뇨 등) 길, 공원, 그 밖에 여러 사람이 모이거나 다니는 곳에서 함부로 침을 뱉거나 대소변을 보거나 또는 그렇게 하도록 시키거나 개 등 짐승을 끌고 와서 대변을 보게 하고 이를 치우지 아니한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6671, '13.  (의식방해) 공공기관이나 그 밖의 단체 또는 개인이 하는 행사나 의식을 못된 장난 등으로 방해하거나 행사나 의식을 하는 자 또는 그 밖에 관계 있는 사람이 말려도 듣지 아니하고 행사나 의식을 방해할 우려가 뚜렷한 물건을 가지고 행사장 등에 들어간 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6672, '14.  (단체가입 강요) 싫다고 하는데도 되풀이하여 단체 가입을 억지로 강요한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6673, '15.  (자연훼손) 공원ㆍ명승지ㆍ유원지나 그 밖의 녹지구역 등에서 풀ㆍ꽃ㆍ나무ㆍ돌 등을 함부로 꺾거나 캔 사람 또는 바위ㆍ나무 등에 글씨를 새기거나 하여 자연을 훼손한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6674, '16.  (타인의 가축ㆍ기계 등 무단조작) 다른 사람 또는 단체의 소나 말, 그 밖의 짐승 또는 매어 놓은 배ㆍ뗏목 등을 함부로 풀어 놓거나 자동차 등의 기계를 조작한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6675, '17.  (물길의 흐름 방해) 개천ㆍ 도랑이나 그 밖의 물길의 흐름에 방해될 행위를 한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6676, '18.  (구걸행위 등) 다른 사람에게 구걸하도록 시켜 올바르지 아니한 이익을 얻은 사람 또는 공공장소에서 구걸을 하여 다른 사람의 통행을 방해하거나 귀찮게 한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6677, '19.  (불안감조성) 정당한 이유 없이 길을 막거나 시비를 걸거나 주위에 모여들거나 뒤따르거나 몹시 거칠게 겁을 주는 말이나 행동으로 다른 사람을 불안하게 하거나 귀찮고 불쾌하게 한 사람 또는 여러 사람이 이용하거나 다니는 도로ㆍ공원 등 공공장소에서 고의로 험악한 문신(文身)을 드러내어 다른 사람에게 혐오감을 준 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6678, '20.  (음주소란 등) 공회당ㆍ극장ㆍ음식점 등 여러 사람이 모이거나 다니는 곳 또는 여러 사람이 타는 기차ㆍ자동차ㆍ배 등에서 몹시 거친 말이나 행동으로 주위를 시끄럽게 하거나 술에 취하여 이유 없이 다른 사람에게 주정한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6679, '21.  (인근소란 등) 악기ㆍ라디오ㆍ텔레비전ㆍ전축ㆍ종ㆍ확성기ㆍ전동기(電動機) 등의 소리를 지나치게 크게 내거나 큰소리로 떠들거나 노래를 불러 이웃을 시끄럽게 한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6680, '22.  (위험한 불씨 사용) 충분한 주의를 하지 아니하고 건조물, 수풀, 그 밖에 불붙기 쉬운 물건 가까이에서 불을 피우거나 휘발유 또는 그 밖에 불이 옮아붙기 쉬운 물건 가까이에서 불씨를 사용한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6681, '23.  (물건 던지기 등 위험행위) 다른 사람의 신체나 다른 사람 또는 단체의 물건에 해를 끼칠 우려가 있는 곳에 충분한 주의를 하지 아니하고 물건을 던지거나 붓거나 또는 쏜 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6682, '24.  (인공구조물 등의 관리소홀) 무너지거나 넘어지거나 떨어질 우려가 있는 인공구조물이나 그 밖의 물건에 대하여 관계 공무원으로부터 고칠 것을 요구받고도 필요한 조치를 게을리하여 여러 사람을 위험에 빠트릴 우려가 있게 한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6683, '25.  (위험한 동물의 관리 소홀) 사람이나 가축에 해를 끼치는 버릇이 있는 개나 그 밖의 동물을 함부로 풀어놓거나 제대로 살피지 아니하여 나다니게 한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6684, '26.  (동물 등에 의한 행패 등) 소나 말을 놀라게 하여 달아나게 하거나 개나 그 밖의 동물을 시켜 사람이나 가축에게 달려들게 한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6685, '27.  (무단소등) 여러 사람이 다니거나 모이는 곳에 켜 놓은 등불이나 다른 사람 또는 단체가 표시를 하기 위하여 켜 놓은 등불을 함부로 끈 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6686, '28.  (공중통로 안전관리소홀) 여러 사람이 다니는 곳에서 위험한 사고가 발생하는 것을 막을 의무가 있으면서도 등불을 켜 놓지 아니하거나 그 밖의 예방조치를 게을리한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6687, '29.  (공무원 원조불응) 눈ㆍ비ㆍ바람ㆍ해일ㆍ지진 등으로 인한 재해, 화재ㆍ교통사고ㆍ범죄, 그 밖의 급작스러운 사고가 발생하였을 때에 현장에 있으면서도 정당한 이유 없이 관계 공무원 또는 이를 돕는 사람의 현장출입에 관한 지시에 따르지 아니하거나 공무원이 도움을 요청하여도 도움을 주지 아니한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6688, '30.  (거짓 인적사항 사용) 성명, 주민등록번호, 등록기준지, 주소, 직업 등을 거짓으로 꾸며대고 배나 비행기를 타거나 인적사항을 물을 권한이 있는 공무원이 적법한 절차를 거쳐 묻는 경우 정당한 이유 없이 다른 사람의 인적사항을 자기의 것으로 거짓으로 꾸며댄 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6689, '31.  (미신요법) 근거 없이 신기하고 용한 약방문인 것처럼 내세우거나 그 밖의 미신적인 방법으로 병을 진찰ㆍ치료ㆍ예방한다고 하여 사람들의 마음을 홀리게 한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6690, '32.  (야간통행제한 위반) 전시ㆍ사변ㆍ천재지변, 그 밖에 사회에 위험이 생길 우려가 있을 경우에 경찰청장이나 해양경찰청장이 정하는 야간통행제한을 위반한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6691, '33.  (과다노출) 공개된 장소에서 공공연하게 성기ㆍ엉덩이 등 신체의 주요한 부위를 노출하여 다른 사람에게 부끄러운 느낌이나 불쾌감을 준 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6692, '34.  (지문채취 불응) 범죄 피의자로 입건된 사람의 신원을 지문조사 외의 다른 방법으로는 확인할 수 없어 경찰공무원이나 검사가 지문을 채취하려고 할 때에 정당한 이유 없이 이를 거부한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6693, '35.  (자릿세 징수 등) 여러 사람이 모이거나 쓸 수 있도록 개방된 시설 또는 장소에서 좌석이나 주차할 자리를 잡아 주기로 하거나 잡아주면서, 돈을 받거나 요구하거나 돈을 받으려고 다른 사람을 귀찮게 따라다니는 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6694, '36.  (행렬방해) 공공장소에서 승차ㆍ승선, 입장ㆍ매표 등을 위한 행렬에 끼어들거나 떠밀거나 하여 그 행렬의 질서를 어지럽힌 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6695, '37.  (무단 출입) 출입이 금지된 구역이나 시설 또는 장소에 정당한 이유 없이 들어간 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6696, '38.  (총포 등 조작장난) 여러 사람이 모이거나 다니는 곳에서 충분한 주의를 하지 아니하고 총포, 화약류, 그 밖에 폭발의 우려가 있는 물건을 다루거나 이를 가지고 장난한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6697, '39.  (무임승차 및 무전취식) 영업용 차 또는 배 등을 타거나 다른 사람이 파는 음식을 먹고 정당한 이유 없이 제 값을 치르지 아니한 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6698, '40.  (장난전화 등) 정당한 이유 없이 다른 사람에게 전화ㆍ문자메시지ㆍ편지ㆍ전자우편ㆍ전자문서 등을 여러 차례 되풀이하여 괴롭힌 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6699, '41.  (지속적 괴롭힘) 상대방의 명시적 의사에 반하여 지속적으로 접근을 시도하여 면회 또는 교제를 요구하거나 지켜보기, 따라다니기, 잠복하여 기다리기 등의 행위를 반복하여 하는 사람', 9968);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6700, '1.  (출판물의 부당게재 등) 올바르지 아니한 이익을 얻을 목적으로 다른 사람 또는 단체의 사업이나 사사로운 일에 관하여 신문, 잡지, 그 밖의 출판물에 어떤 사항을 싣거나 싣지 아니할 것을 약속하고 돈이나 물건을 받은 사람', 9969);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6701, '2.  (거짓 광고) 여러 사람에게 물품을 팔거나 나누어 주거나 일을 해주면서 다른 사람을 속이거나 잘못 알게 할 만한 사실을 들어 광고한 사람', 9969);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6702, '3.  (업무방해) 못된 장난 등으로 다른 사람, 단체 또는 공무수행 중인 자의 업무를 방해한 사람', 9969);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6703, '4.  (암표매매) 흥행장, 경기장, 역, 나루터, 정류장, 그 밖에 정하여진 요금을 받고 입장시키거나 승차 또는 승선시키는 곳에서 웃돈을 받고 입장권ㆍ승차권 또는 승선권을 다른 사람에게 되판 사람', 9969);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6704, '1.  (관공서에서의 주취소란) 술에 취한 채로 관공서에서 몹시 거친 말과 행동으로 주정하거나 시끄럽게 한 사람', 9970);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6705, '2.  (거짓신고) 있지 아니한 범죄나 재해 사실을 공무원에게 거짓으로 신고한 사람', 9970);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6706, '1.  범칙행위를 상습적으로 하는 사람', 9972);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6707, '2.  죄를 지은 동기나 수단 및 결과를 헤아려볼 때 구류처분을 하는 것이 적절하다고 인정되는 사람', 9972);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6708, '3.  피해자가 있는 행위를 한 사람', 9972);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6709, '4.  18세 미만인 사람', 9972);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6710, '1.  통고처분서 받기를 거부한 사람', 9974);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6711, '2.  주거 또는 신원이 확실하지 아니한 사람', 9974);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6712, '3.  그 밖에 통고처분을 하기가 매우 어려운 사람', 9974);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6713, '1.  제7조제1항 각 호의 어느 하나에 해당하는 사람', 9984);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6714, '2.  제8조제2항에 따른 납부기간에 범칙금을 납부하지 아니한 사람', 9984);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6715, '1.  통고처분을 받는 사람의 인적사항', 9988);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6716, '2.  위반 내용 및 적용 법조문', 9988);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6717, '3.  범칙금의 액수 및 납부기한', 9988);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6718, '4.  통고처분 연월일', 9988);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6719, '1.  「민법」 제32조에 따라 금융위원회의 허가를 받아 설립된 금융결제원', 9995);
