INSERT INTO balaw.ho (id, content, hang_id) VALUES (6738, '1.  "자유형"이라 함은 국내이송을 실시하는 때에는 징역 또는 금고에 상당하는 외국 법령상의 형을 말하고, 국외이송을 실시하는 때에는 징역 또는 금고를 말한다.', 10035);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6739, '2.  "국내이송"이라 함은 외국에서 자유형을 선고받아 그 형이 확정되어 형집행중인 대한민국 국민(이하 "국내이송대상수형자"라 한다)을 외국으로부터 인도받아 그 자유형을 집행하는 것을 말한다.', 10035);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6740, '3.  "국외이송"이라 함은 대한민국에서 자유형을 선고받아 그 형이 확정되어 형집행중인 외국인(이하 "국외이송대상수형자"라 한다)을 외국으로 인도하여 그 자유형을 집행받도록 하는 것을 말한다.', 10035);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6741, '4.  "국제수형자이송"이라 함은 국내이송 및 국외이송을 말한다.', 10035);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6742, '5.  "외국인"이라 함은 대한민국과 국제수형자이송에 관한 조약ㆍ협정 등(이하 "조약"이라 한다)을 체결한 외국의 국민 및 조약에 의하여 그 외국의 국민으로 간주되는 자를 말한다.', 10035);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6743, '1.  외국에서 자유형이 선고ㆍ확정된 범죄사실이 대한민국의 법률에 의하여 범죄를 구성할 것. 이 경우 수 개의 범죄사실중 한 개의 범죄사실이 대한민국의 법률에 의하여 범죄를 구성하는 경우를 포함한다.', 10038);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6744, '2.  외국에서 선고된 자유형의 판결이 확정될 것', 10038);
