INSERT INTO balaw.ho (id, content, hang_id) VALUES (6872, '35.  특별시ㆍ광역시ㆍ도 및 시ㆍ군ㆍ구에 근무하며 무등록자동차정비업, 자동차 소유권 이전등록 미신청, 자동차 무단방치 및 의무보험 미가입 자동차 운행에 관한 단속 사무에 종사하는 5급부터 9급까지의 지방공무원', 10157);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6873, '36.  삭제 <2017.12.19>', 10157);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6874, '37.  해양수산부와 그 소속 기관, 광역시ㆍ도 및 시ㆍ군ㆍ구에 근무하며 해양환경 관련 단속 사무에 종사하는 4급부터 9급까지의 국가공무원 및 지방공무원', 10157);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6875, '38.  특허청, 특별시ㆍ광역시ㆍ도 및 시ㆍ군ㆍ구에 근무하며 부정경쟁행위, 상표권 및 전용사용권 침해에 관한 단속 사무에 종사하는 4급부터 9급까지의 국가공무원 및 지방공무원', 10157);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6876, '38의2.  특허청에 근무하며 특허권ㆍ전용실시권 침해, 부정경쟁행위, 영업비밀 침해, 디자인ㆍ전용실시권 및 실용신안권ㆍ전용실시권 침해에 관한 단속 사무에 종사하는 4급부터 9급까지의 국가공무원', 10157);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6877, '39.  특별시ㆍ광역시ㆍ도 및 시ㆍ군ㆍ구에 근무하며 여객자동차 운수사업 및 화물자동차 운수사업의 단속 사무에 종사하는 4급부터 9급까지의 지방공무원', 10157);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6878, '40.  「도시공원 및 녹지 등에 관한 법률」 제20조에 따른 공원관리청에 근무하며 같은 법에 따라 도시공원 관리업무에 종사하는 4급부터 9급까지의 지방공무원', 10157);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6879, '41.  병무청과 그 소속 기관에 근무하며 「병역법」 제86조, 제87조, 제87조의2 및 제88조제1항(같은 항 제4호에 해당하는 경우는 제외한다)에 관한 단속 사무에 종사하는 4급부터 9급까지의 국가공무원', 10157);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6880, '42.  농림축산식품부와 그 소속 기관, 산림청, 특별시ㆍ광역시ㆍ도 및 시ㆍ군ㆍ구에 근무하며 「종자산업법」 및 「식물신품종 보호법」에 규정된 품종보호권 침해행위의 조사 사무 및 종자의 유통 조사 등에 관한 사무에 종사하는 4급부터 9급까지의 국가공무원 및 지방공무원', 10157);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6881, '42의2.  「동물보호법」 제88조제1항에 따른 동물보호관', 10157);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6882, '43.  행정안전부와 그 소속 기관, 특별시ㆍ광역시ㆍ도 및 시ㆍ군ㆍ구에 근무하며 「재난 및 안전관리 기본법」 제30조에 따른 긴급안전점검 업무에 종사하는 4급부터 9급까지의 국가공무원 및 지방공무원', 10157);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6883, '44.  산업통상자원부, 특별시ㆍ광역시ㆍ도 및 시ㆍ군ㆍ구에 근무하며 석유 및 석유대체연료 관련 검사ㆍ단속 등에 관한 사무에 종사하는 4급부터 9급까지의 국가공무원 및 지방공무원', 10157);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6884, '45.  특별시ㆍ광역시ㆍ도 및 시ㆍ군ㆍ구에 근무하며 대부업 및 대부중개업의 검사ㆍ단속 등에 관한 사무에 종사하는 4급부터 9급까지의 지방공무원', 10157);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6885, '46.  특별시ㆍ광역시ㆍ도 및 시ㆍ군ㆍ구에 근무하며 방문판매, 전화권유판매, 다단계판매, 후원방문판매, 계속거래 및 사업권유거래 관련 조사ㆍ단속 등에 관한 사무에 종사하는 4급부터 9급까지의 지방공무원', 10157);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6886, '47.  특별시ㆍ광역시ㆍ도 및 시ㆍ군ㆍ구에 근무하며 선불식 할부거래업의 조사ㆍ단속 등에 관한 사무에 종사하는 4급부터 9급까지의 지방공무원', 10157);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6887, '48.  「수산생물질병 관리법」 제7조제1항에 따른 수산생물방역관 및 같은 법 제22조제1항에 따른 수산생물검역관', 10157);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6888, '49.  금융위원회에 근무하며 자본시장 불공정거래 조사ㆍ단속 등에 관한 사무에 종사하는 4급부터 9급까지의 국가공무원', 10157);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6889, '50.  원자력안전위원회와 그 소속기관에 근무하며 원자력안전관리와 관련된 조사ㆍ단속 등에 관한 사무에 종사하는 4급부터 9급까지의 국가공무원', 10157);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6890, '51.  고용노동부와 그 소속 기관에 근무하며 「고용보험법」에 따른 실업급여, 육아휴직 급여, 출산전후휴가 급여등의 부정수급에 관한 사무에 종사하거나 「국민 평생 직업능력 개발법」에 따른 직업능력개발 훈련비용ㆍ훈련수당 등의 부정수급에 관한 사무에 종사하는 4급부터 9급까지의 국가공무원', 10157);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6891, '52.  국토교통부와 그 소속 기관, 특별시ㆍ광역시ㆍ도 및 시ㆍ군ㆍ구에 근무하며 「시설물의 안전 및 유지관리에 관한 특별법」 제13조에 따른 긴급안전점검 업무에 종사하는 4급부터 9급까지의 국가공무원 및 지방공무원', 10157);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6892, '53.  국토교통부, 특별시ㆍ광역시ㆍ도 및 시ㆍ군ㆍ구에 근무하며 부동산 관련 불법행위 조사ㆍ단속 등에 관한 사무에 종사하는 4급부터 9급까지의 국가공무원 및 지방공무원', 10157);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6893, '1.  제5조제1호에 규정된 자의 경우에는 해당 교도소ㆍ소년교도소ㆍ구치소 또는 그 지소 안에서 발생하는 범죄', 10158);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6894, '2.  제5조제2호에 규정된 자의 경우에는 해당 지방교정청이 관할하는 교정시설 안에서 발생하는 범죄', 10158);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6895, '3.  제5조제3호에 규정된 자의 경우에는 소년원 또는 그 분원이나 소년분류심사원 또는 그 지원 안에서 발생하는 범죄 또는 재원자(在院者)나 가위탁자(假委託者)가 도주한 경우에 있어서의 체포. 다만, 그 도주에 관한 수사는 도주 후 72시간 이내로 제한한다.', 10158);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6896, '4.  제5조제4호에 규정된 자의 경우에는 해당 감호소 또는 그 지소 안에서 발생하는 범죄', 10158);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6897, '4의2.  제5조제4호의2에 규정된 자의 경우에는 소속 관서 관할 구역에서 발생하는 「전자장치 부착 등에 관한 법률」 제38조 또는 제39조에 규정된 피부착자의 범죄', 10158);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6898, '5.  제4조와 제5조제5호부터 제7호까지 및 제13호에 규정된 사람의 경우에는 다음 각 목의 구분에 따른 범죄', 10158);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6899, '6.  제5조제8호에 규정된 자의 경우에는 소속 행정관서 관할 구역에서 발생하는「식품위생법」, 「수입식품안전관리 특별법」, 「건강기능식품에 관한 법률」 및 「식품 등의 표시ㆍ광고에 관한 법률」에 규정된 범죄와 「보건범죄 단속에 관한 특별조치법」 중 식품위생에 관한 범죄', 10158);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6900, '7.  제5조제9호에 규정된 자의 경우에는 소속 행정관서 관할 구역에서 발생하는 「약사법」ㆍ「화장품법」ㆍ「의료기기법」ㆍ「식품ㆍ의약품분야 시험ㆍ검사 등에 관한 법률」ㆍ「위생용품 관리법」ㆍ「체외진단의료기기법」에 규정된 범죄와 「보건범죄 단속에 관한 특별조치법」 중 약사(藥事)에 관한 범죄', 10158);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6901, '7의2.  제5조제9호의2에 규정된 자의 경우에는 소속 행정관서 관할 구역에서 발생하는 「마약류 관리에 관한 법률」 제2조제5호에 따른 마약류취급자(같은 법 제2조제5호라목에 따른 대마재배자는 제외한다)에 관하여 「마약류 관리에 관한 법률」에 규정된 범죄. 이 경우 법인의 대표자나 이사, 그 밖에 이에 종사하는 자를 포함하고, 법인이 아닌 경우 그 종사자를 포함한다.', 10158);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6902, '8.  제5조제10호에 규정된 자의 경우에는 소속 등대에서 발생하는 범죄', 10158);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6903, '9.  제5조제11호에 규정된 자의 경우에는 소속 관서 관할 구역인 철도시설 및 열차 안에서 발생하는 「철도안전법」에 규정된 범죄와 그 소속 관서 역 구내 및 열차 안에서의 범죄', 10158);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6904, '10.  제5조제12호에 규정된 자의 경우에는 소속 관서 관할 구역에서 발생하는 「소방기본법」, 「소방시설 설치 및 관리에 관한 법률」, 「소방시설공사업법」, 「위험물안전관리법」, 「다중이용업소의 안전관리에 관한 특별법」, 「119구조ㆍ구급에 관한 법률」 및 「초고층 및 지하연계 복합건축물 재난관리에 관한 특별법」에 규정된 범죄', 10158);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6905, '11.  제5조제14호에 규정된 자의 경우에는 소속 관서 관할 구역에서 발생하는 「문화유산의 보존 및 활용에 관한 법률」, 「자연유산의 보존 및 활용에 관한 법률」, 「매장유산 보호 및 조사에 관한 법률」에 규정된 범죄 및 「문화유산의 보존 및 활용에 관한 법률」 또는 「자연유산의 보존 및 활용에 관한 법률」에 따라 지정된 국가지정문화유산 또는 천연기념물ㆍ명승의 구역이나 그 보호구역과 관리사무소가 설치되어 있는 시ㆍ도지정문화유산 또는 시ㆍ도자연유산의 구역 또는 그 보호구역 안에서 발생하는 「경범죄처벌법」에 규정된 범죄의 현행범', 10158);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6906, '12.  제5조제15호에 규정된 자의 경우에는 그 소속 관서 관할 구역에서 발생하는 「계량에 관한 법률」에 규정된 범죄', 10158);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6907, '13.  제5조제16호에 규정된 자의 경우에는 그 관할 공원구역에서 발생하는 「자연공원법」에 규정된 범죄와 「경범죄처벌법」에 규정된 범죄의 현행범', 10158);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6908, '14.  제5조제17호에 규정된 자의 경우에는 다음 각 목의 범죄', 10158);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6909, '15.  제5조제18호에 규정된 자의 경우에는 소속 관서 관할 구역에서 발생하는 「수산업법」에 규정된 범죄, 「양식산업발전법」에 규정된 범죄, 「어업자원보호법」에 규정된 범죄, 「수산자원관리법」에 규정된 범죄, 「어선법」에 규정된 범죄 및 「내수면어업법」에 규정된 범죄', 10158);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6910, '16.  제5조제19호에 규정된 자의 경우에는 관할 구역에서 발생하는 「광산안전법」에 규정된 범죄', 10158);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6911, '17.  제5조제20호에 규정된 자의 경우에는 「국가유공자 등 예우 및 지원에 관한 법률」 제42조, 제63조 및 제64조에 따른 시설에서 발생하는 범죄', 10158);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6912, '18.  제5조제21호 각 목에 규정된 사람의 경우에는 소속 관서 관할 구역에서 발생하는 다음 각 목의 구분에 따른 범죄', 10158);
