INSERT INTO balaw.ho (id, content, hang_id) VALUES (6972, '1.  "군교정시설"이란 군교도소, 군교도소 지소 및 군미결수용실을 말한다.', 10181);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6973, '2.  "자비구매물품"이란 「군에서의 형의 집행 및 군수용자의 처우에 관한 법률」(이하 "법"이라 한다) 제24조에 따라 군수용자가 소장의 허가를 받아 자신의 비용으로 구매할 수 있는 물품을 말한다.', 10181);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6974, '3.  "군교정시설의 보관범위"란 법 제25조에 따라 군수용자 1명이 군교정시설에 영치하여 보관할 수 있는 물품의 수량으로서 국방부장관이 정하는 범위를 말한다.', 10181);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6975, '4.  "군수용자의 소지범위"란 법 제26조에 따라 군수용자 1명이 군교정시설 안에서 소지하여 사용할 수 있는 물품의 수량으로서 국방부장관이 정하는 범위를 말한다.', 10181);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6976, '5.  "교부금품"이란 법 제27조에 따라 군수용자 외의 사람이 소장의 허가를 받아 군수용자에게 교부할 수 있는 금품을 말한다.', 10181);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6977, '6.  "처우등급"이란 「군에서의 형의 집행 및 군수용자의 처우에 관한 법률 시행령」(이하 "영"이라 한다) 제77조제2항에 따라 군수형자의 교정성적에 따른 처우의 수준과 내용을 구별하는 기준을 말한다.', 10181);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6978, '7.  "자치생활"이란 수형생활 중 일정한 범위에서 군교도관이나 교도병의 통제 없이 자율적으로 생활하는 것을 말한다.', 10181);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6979, '8.  "교정참여인사"란 법 제52조에 따라 군수형자에 대한 상담, 심리치료 또는 생활지도 등을 하는 외부전문가와 법 제114조제2항에 따라 위촉한 교정위원을 말한다.', 10181);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6980, '9.  "외부통근자"란 법 제58조에 따라 외부기업체 또는 군교정시설 안에 설치된 외부기업체의 작업장에 통근하며 작업하는 군수형자를 말한다.', 10181);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6981, '10.  "교정장비"란 군교정시설의 안[군교도관이 군교정시설의 밖에서 군수용자를 계호(戒護)하고 있는 경우 그 장소를 포함한다]에서 사람의 생명과 신체의 보호, 도주의 방지 및 군교정시설의 안전과 질서유지를 위하여 군교도관 또는 교도병이 사용하는 법 제81조에 따른 전자장비, 법 제85조의 보호장비, 법 제87조제4항의 보안장비 및 법 제88조에 따른 무기를 말한다.', 10181);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6982, '1.  군수용자가 도주하였거나 도주할 우려가 있을 때', 10183);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6983, '2.  군수용자의 소요(騷擾), 폭행, 변사(變死) 등의 사고가 발생하였을 때', 10183);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6984, '3.  군수용자가 무기를 사용하였을 때', 10183);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6985, '4.  군수용자로부터 법 제102조에 따른 청원서를 받았을 때', 10183);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6986, '5.  군수용자에게 「군사법원법」 제513조제1항 및 제514조제1항에 따른 형의 집행정지 사유가 발생하였을 때', 10183);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6987, '6.  군수용자 중 환자가 발생하였거나 발생할 우려가 있을 때', 10183);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6988, '7.  군수용자의 건강을 위하여 작업, 운동 또는 급식 등의 방법을 변경할 필요가 있을 때', 10183);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6989, '8.  군수용자를 군교정시설 외의 장소에서 작업에 종사하게 할 필요가 있을 때', 10183);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6990, '9.  그 밖에 업무 수행 중 특이한 상항이 발생하였을 경우', 10183);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6991, '1.  음식물', 10193);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6992, '2.  의약품 및 의료용품', 10193);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6993, '3.  의류ㆍ침구류 및 신발류', 10193);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6994, '4.  신문ㆍ잡지ㆍ도서 및 문구류', 10193);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6995, '5.  군수형자 교육 등 교정ㆍ교화에 필요한 물품', 10193);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6996, '6.  그 밖에 수용생활에 필요하다고 인정하는 물품', 10193);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6997, '1.  의약품 및 의료용품류: 군의관의 확인을 거쳐 위해성(危害性)이 없다고 인정되는 치료용 의약품 및 의료용품류', 10196);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6998, '2.  음식물: 군교정시설에서 판매하는 음식물', 10196);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (6999, '3.  그 밖에 자비구매물품: 군교도관회의의 의결로 정하는 물품', 10196);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7000, '1.  오감(五感) 또는 통상적인 검사장비로는 내부 검색이 어려운 물품', 10204);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7001, '2.  음란하거나 현란한 그림이나 무늬가 포함된 물품', 10204);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7002, '3.  사행심을 조장할 우려가 있는 물품', 10204);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7003, '4.  심리적인 안정을 해칠 우려가 있는 물품', 10204);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7004, '5.  도주ㆍ자살ㆍ자해 등에 이용될 수 있는 금속류, 끈 또는 가죽 등이 포함된 물품', 10204);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7005, '6.  위화감을 조성할 우려가 있는 높은 가격의 물품', 10204);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7006, '7.  그 밖에 군수형자의 교화 또는 건전한 사회복귀를 해칠 우려가 있거나 군교정시설의 안전 또는 질서를 해칠 우려가 있는 물품', 10204);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7007, '1.  종교집회: 예배ㆍ법회ㆍ미사 등', 10210);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7008, '2.  종교의식: 세례ㆍ수계ㆍ영세 등', 10210);
