INSERT INTO balaw.ho (id, content, hang_id) VALUES (7013, '3.  군수용자가 개종(改宗)을 핑계삼아 다른 군수용자의 평온한 신앙생활을 방해하는 경우', 10213);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7014, '4.  그 밖에 감염병 환자, 징벌자 등 법령에 따라 공동행사의 참석이 제한되는 때', 10213);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7015, '1.  다른 군수용자의 평온한 수용생활에 불편을 주는 경우', 10216);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7016, '2.  성물의 재질이나 형태가 교정시설의 안전이나 다른 사람의 생명과 안전을 해칠 수 있는 도구로 사용될 수 있는 경우', 10216);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7017, '3.  군수용자가 공동으로 사용하는 시설 내에 설치하거나 게시하여 다른 군수용자의 종교생활을 방해할 우려가 있는 경우', 10216);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7018, '4.  그 밖에 수용질서를 해칠 우려가 있는 경우', 10216);
