INSERT INTO balaw.ho (id, content, hang_id) VALUES (7020, '2.  그 밖에 국방부장관이 정하는 신문등과 관련된 준수사항을 위반한 경우', 10217);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7021, '1.  교육콘텐츠: 한글ㆍ한자ㆍ외국어 교육, 보건위생 향상, 성(性) 의식 개선, 약물남용 예방 등', 10224);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7022, '2.  교화콘텐츠: 인간성 회복, 근로의식 함양, 가족관계 회복, 질서의식 제고, 국가관 고취 등', 10224);
