INSERT INTO balaw.ho (id, content, hang_id) VALUES (7062, '2.  교육개시일 기준으로 형기의 4분의 1(무기형의 경우에는 7년)이 경과할 것', 10274);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7063, '3.  시험일 기준으로 집행할 형기가 6월 이상 남아 있을 것', 10274);
