INSERT INTO balaw.ho (id, content, hang_id) VALUES (7069, '1.  수: 작업등급이 "우"인 사람으로서 9월 이상 계속하여 작업에 종사하고 작업성적이 특히 우수하여 다른 군수용자의 모범이 되는 사람', 10293);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7070, '2.  우: 작업등급이 "양"인 사람으로서 6월 이상 계속하여 작업에 종사하고 작업성적이 우수한 사람', 10293);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7071, '3.  양: 작업등급이 "가"인 사람으로서 3월 이상 계속하여 작업에 종사하고 작업성적이 양호한 사람', 10293);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7072, '4.  가: 작업에 종사한 기간이 3월 미만인 사람', 10293);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7073, '1.  처우등급 3급 이상일 것', 10295);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7074, '2.  해당 작업 수행에 건강상 장애가 없을 것', 10295);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7075, '3.  가족ㆍ친지 또는 교정위원 등과 접견ㆍ서신ㆍ전화통화 등으로 연락하고 있을 것', 10295);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7076, '4.  외부기업체에 통근하는 군수형자는 집행할 형기가 7년 미만이고 가석방이 제한되지 아니할 것', 10295);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7077, '5.  군교정시설 안에 설치된 외부기업체의 작업장에 통근하는 군수형자는 집행할 형기가 10년 미만이거나 형기 기산일부터 10년 이상이 지났을 것', 10295);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7078, '1.  집행할 형기 중에 해당 훈련과정을 마칠 수 있을 것', 10299);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7079, '2.  직업훈련에 필요한 기본소양을 갖추었다고 인정될 것', 10299);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7080, '3.  해당 과정의 기술이 없거나 재훈련을 희망할 것', 10299);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7081, '4.  석방 후 관련 직종에 취업할 의사가 있을 것', 10299);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7082, '1.  조사 또는 징벌집행 중인 경우', 10300);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7083, '2.  교육생으로 선정된 경우', 10300);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7084, '3.  질병 또는 신체조건 등으로 직업훈련을 감당할 수 없다고 인정되는 경우', 10300);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7085, '1.  법 제93조제1호부터 제5호까지 및 이 규칙 제148조 각 호에 해당하는 행위(이하 "징벌대상행위"라 한다)의 혐의가 있어 조사를 받게 된 경우', 10303);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7086, '2.  심신이 허약하거나 질병 등으로 훈련을 감당할 수 없는 경우', 10303);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7087, '3.  소질ㆍ적성ㆍ훈련성적 등을 종합적으로 고려한 결과 직업훈련을 계속할 수 없다고 인정되는 경우', 10303);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7088, '4.  그 밖에 직업훈련을 계속할 수 없다고 인정되는 사유가 있는 경우', 10303);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7089, '1.  군수형자의 직계존속, 배우자, 배우자의 직계존속 또는 본인의 환갑날일 때', 10305);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7090, '2.  본인 또는 형제자매의 혼례가 있을 때', 10305);
