INSERT INTO balaw.ho (id, content, hang_id) VALUES (7107, '4.  심사 중 알게 된 군수형자의 개인정보를 누설하거나 위원으로서 부적절한 행위를 한 경우', 10314);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7108, '1.  별지 제7호서식의 귀휴심사조서', 10323);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7109, '2.  별지 제8호서식의 신원조서', 10323);
