INSERT INTO balaw.ho (id, content, hang_id) VALUES (7118, '4.  무기', 10345);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7119, '1.  영상정보처리기기: 일정한 공간에 지속적으로 설치되어 사람 또는 사물의 영상 및 이에 따르는 음성ㆍ음향 등을 수신하거나 이를 유선망이나 무선망을 통하여 전송하는 장치', 10349);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7120, '2.  전자감지기: 일정한 공간에 지속적으로 설치되어 사람 또는 사물의 움직임을 빛ㆍ온도ㆍ소리ㆍ압력 등을 이용하여 감지하고 전송하는 장치', 10349);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7121, '3.  전자경보기: 전자파를 발신하고 추적하는 원리를 이용하여 사람의 위치를 확인하거나 이동경로를 탐지하는 일련의 기계적 장치', 10349);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7122, '4.  물품검색기(고정식 물품검색기와 휴대식 금속탐지기로 구분한다)', 10349);
