INSERT INTO balaw.ho (id, content, hang_id) VALUES (7132, '8.  포승(捕繩): 일반포승, 개인포승', 10361);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7133, '1.  법 제84조제1항 각 호의 어느 하나에 해당하는 경우에는 별표 4의 방법으로 할 것', 10364);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7134, '2.  법 제84조제1항제2호부터 제4호까지의 어느 하나에 해당하는 경우 별표 4의 방법으로는 사용목적을 달성할 수 없다고 인정되는 경우에는 별표 5의 방법으로 할 것', 10364);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7135, '3.  진료를 받거나 입원 중인 군수용자에 대하여 한손수갑을 사용하는 경우에는 별표 6의 방법으로 할 것', 10364);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7136, '1.  양발목보호장비의 사용은 별표 8의 방법으로 사용할 것', 10368);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7137, '2.  진료를 받거나 입원 중인 군수용자에 대하여 한발목보호장비를 사용하는 경우에는 별표 9의 방법으로 사용할 것', 10368);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7138, '1.  금속보호대는 수갑과 수갑보호기를 보호대에 연결하여 별표 10의 방법으로 사용할 것', 10369);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7139, '2.  벨트보호대는 보호대에 부착된 고리에 수갑을 연결하여 별표 11의 방법으로 사용할 것', 10369);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7140, '1.  고령자, 환자 등 도주의 위험성이 크지 아니하다고 판단되는 군수용자를 개별 호송하는 경우에는 별표 15의 방법으로 할 수 있다.', 10376);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7141, '2.  제1호의 군수용자 외의 군수용자를 호송하는 경우 또는 법 제84조제1항제2호부터 제4호까지의 어느 하나에 해당하는 경우에는 별표 16의 방법으로 한다.', 10376);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7142, '3.  법 제84조제1항제2호부터 제4호까지의 어느 하나에 해당하는 경우로서 제2호의 방법으로는 사용목적을 달성할 수 없다고 인정되는 경우에는 별표 17의 방법으로 한다. 이 경우 2개의 포승을 연결하여 사용할 수 있다.', 10376);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7143, '1.  교도봉(접이식을 포함한다. 이하 같다)', 10383);
