INSERT INTO balaw.ho (id, content, hang_id) VALUES (7150, '1.  교도봉ㆍ가스분사기ㆍ가스총ㆍ최루탄: 법 제87조제1항제1호부터 제7호까지의 어느 하나에 해당하는 경우', 10384);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7151, '2.  전기교도봉ㆍ전자총: 법 제87조제1항제1호부터 제7호까지의 어느 하나에 해당하는 경우로서 상황이 긴급하여 제1호의 장비만으로는 그 목적을 달성할 수 없는 경우', 10384);
