INSERT INTO balaw.ho (id, content, hang_id) VALUES (7153, '2.  전기교도봉ㆍ전자총: 법 제87조제2항제1호부터 제6호까지의 어느 하나에 해당하는 경우로서 상황이 긴급하여 제1호의 장비만으로는 그 목적을 달성할 수 없는 경우', 10385);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7154, '1.  교도봉ㆍ전기교도봉은 얼굴이나 머리 부분에 사용해서 아니 되며 전기교도봉은 타격 즉시 떼어야 한다.', 10387);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7155, '2.  가스분사기ㆍ가스총은 1미터 이내의 거리에서 상대방의 얼굴을 향하여 발사해서 아니 된다.', 10387);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7156, '3.  투척용 최루탄은 근거리용으로 사용하고, 발사용 최루탄은 50미터 이상의 원거리에서 사용하되 30도 이상의 발사각을 유지하여야 한다.', 10387);
