INSERT INTO balaw.ho (id, content, hang_id) VALUES (7164, '1.  권총ㆍ소총: 법 제88조제2항에 해당하는 경우', 10390);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7165, '2.  기관총: 법 제88조제2항에 해당하는 경우로서 제1호의 무기만으로는 그 목적을 달성할 수 없다고 인정하는 경우', 10390);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7166, '1.  군교정시설의 안전 또는 질서를 해칠 목적으로 사람들을 선동하는 행위', 10398);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7167, '2.  허가되지 아니한 단체를 조직하거나 그 단체에 가입하는 행위', 10398);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7168, '3.  교정장비, 도주방지시설, 그 밖의 보안시설의 기능을 훼손하는 행위', 10398);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7169, '4.  음란한 행위를 하거나 다른 사람에게 성적(性的)인 말이나 행동으로 성적 수치심 또는 혐오감을 느끼게 하는 행위', 10398);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7170, '5.  다른 사람에게 부당한 금품을 요구하는 행위', 10398);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7171, '6.  작업, 교육, 접견, 집필, 전화통화, 운동, 그 밖에 군교도관의 직무 또는 다른 군수용자의 정상적인 일과(日課) 진행을 방해하는 행위', 10398);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7172, '7.  문신을 하거나 이물질을 신체에 삽입하는 등 의료 외의 목적으로 신체를 변형하는 행위', 10398);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7173, '8.  허가 없이 지정된 장소를 벗어나거나 금지구역을 출입하는 행위', 10398);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7174, '9.  허가 없이 다른 사람과 만나거나 연락하는 행위', 10398);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7175, '10.  수용생활의 편의 등 자신의 요구를 관철할 목적으로 이물질을 삼키는 행위', 10398);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7176, '11.  인원점검을 회피하거나 방해하는 행위', 10398);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7177, '12.  군교정시설의 설비나 물품을 고의로 훼손하거나 낭비하는 행위', 10398);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7178, '13.  고의로 군수용자 번호표, 거실표, 작업장 표시표 등을 지정된 위치에 붙이지 아니하거나 그 밖의 방법으로 현황파악을 방해하는 행위', 10398);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7179, '14.  고성으로 떠들거나 소음을 일으켜 다른 군수용자의 평온한 수용생활을 현저히 방해하는 행위', 10398);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7180, '15.  허가 없이 물품을 반입ㆍ제작ㆍ소지ㆍ변조ㆍ수수 또는 교환하는 행위', 10398);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7181, '16.  도박이나 그 밖에 사행심을 조장하는 놀이나 내기를 하는 행위', 10398);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7182, '17.  지정된 거실에의 입실을 거부하는 등 정당한 사유 없이 군교도관의 직무상 지시나 명령을 따르지 아니하는 행위', 10398);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7183, '18.  군수용자 상호간의 욕설 및 구타행위', 10398);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7184, '19.  그 밖에 군수용자의 안전과 수용질서를 유지하기 위하여 군교도관으로부터 지시받은 사항을 고의적으로 위반하는 행위', 10398);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7185, '1.  법 제93조제1호ㆍ제4호 및 이 규칙 제148조제1호부터 제3호까지의 어느 하나에 해당하는 행위: 21일 이상 30일 이하의 금치(禁置)', 10399);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7186, '2.  법 제93조제5호 및 이 규칙 제148조제4호부터 제8호까지의 어느 하나에 해당하는 행위는 다음 각 목의 어느 하나의 징벌을 부과한다.', 10399);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7187, '3.  법 제93조제2호ㆍ제3호 및 이 규칙 제148조제9호부터 제14호까지의 어느 하나에 해당하는 행위는 다음 각 목의 어느 하나의 징벌을 부과한다.', 10399);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7188, '4.  이 규칙 제148조제15호부터 제19호까지의 어느 하나에 해당하는 행위는 다음 각 목의 어느 하나의 징벌을 부과한다.', 10399);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7189, '5.  징벌대상행위를 하였으나 그 위반의 정도가 경미한 경우는 제1호부터 제4호까지의 규정에도 불구하고 다음 각 목의 어느 하나의 징벌을 부과한다.', 10399);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7190, '1.  징벌대상행위를 한 군수용자의 나이ㆍ성향ㆍ지능ㆍ성장환경 및 건강', 10400);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7191, '2.  징벌대상행위의 동기ㆍ수단 및 결과', 10400);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7192, '3.  자수 등 징벌대상행위 후의 정황', 10400);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7193, '4.  교정성적, 그 밖의 수용생활태도', 10400);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7194, '1.  부당한 인권침해가 없도록 할 것', 10401);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7195, '2.  조사의 이유를 설명하고, 충분한 진술의 기회를 제공할 것', 10401);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7196, '3.  공정한 절차와 객관적 증거에 따라 조사하고, 선입견이나 추측에 따라 처리하지 아니할 것', 10401);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7197, '4.  형사법률에 저촉되는 행위에 대하여 징벌처분 외에 형사입건조치가 요구되는 경우에는 형사소송절차에 따라 조사대상자에게 진술을 거부할 수 있음과 변호인을 선임할 수 있음을 알릴 것', 10401);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7198, '1.  징벌위원회 의결 요구', 10402);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7199, '2.  징벌대상자에 대한 무혐의 통고', 10402);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7200, '3.  징벌대상자에 대한 훈계', 10402);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7201, '4.  징벌위원회 회부 보류', 10402);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7202, '1.  혐의사실', 10411);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7203, '2.  출석 장소 및 일시', 10411);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7204, '3.  징벌위원회에 출석하여 자기에게 유리한 사실을 말이나 서면으로 진술할 수 있다는 사실', 10411);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7205, '4.  서면으로 진술하려면 징벌위원회를 개최하기 전까지 진술서를 제출하여야 한다는 사실', 10411);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7206, '5.  증인신청 또는 증거제출이 가능하다는 사실', 10411);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7207, '6.  형사절차상 불리하게 사용될 수 있는 사실에 대하여 진술을 거부할 수 있다는 것과 진술하는 경우에는 형사절차상 불리하게 사용될 수 있다는 사실', 10411);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7208, '1.  군법무관 및 해당 군교정시설에 소속되지 아니한 헌병병과 장교', 10425);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7209, '2.  판사, 변호사, 「고등교육법」 제2조제1호의 대학에서 교정학ㆍ형사정책학ㆍ범죄학ㆍ심리학ㆍ교육학 등 교정에 관한 전문분야를 담당하는 부교수 이상의 직(職)에 있는 사람', 10425);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7210, '3.  그 밖에 교정에 관한 학식과 경험이 풍부한 사람', 10425);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7211, '1.  신원관계', 10441);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7212, '2.  범죄관계', 10441);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7213, '3.  보호관계', 10441);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7214, '1.  범죄의 수단이 참혹 또는 교활하거나 극심한 위해를 발생시킨 경우', 10450);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7215, '2.  해당 범죄로 무기형에 처해진 경우', 10450);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7216, '3.  그 밖에 사회적 물의를 일으킨 죄를 범한 경우', 10450);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7217, '1.  군사보안규정 위반으로 군의 전투력을 훼손한 경우', 10451);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7218, '2.  국민의 군에 대한 신뢰도 또는 군의 명예를 크게 훼손한 경우', 10451);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7219, '3.  군에 심각한 재산상 손실을 가져온 경우', 10451);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7220, '1.  "자비구매물품"이란 수용자가 교도소ㆍ구치소 및 그 지소(이하 "교정시설"이라 한다)의 장의 허가를 받아 자신의 비용으로 구매할 수 있는 물품을 말한다.', 10468);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7221, '2.  "교정시설의 보관범위"란 수용자 1명이 교정시설에 보관할 수 있는 물품의 수량으로서 법무부장관이 정하는 범위를 말한다.', 10468);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7222, '3.  "수용자가 지닐 수 있는 범위"란 수용자 1명이 교정시설 안에서 지닌 채 사용할 수 있는 물품의 수량으로서 법무부장관이 정하는 범위를 말한다.', 10468);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7223, '4.  "전달금품"이란 수용자 외의 사람이 교정시설의 장(이하 "소장"이라 한다)의 허가를 받아 수용자에게 건넬 수 있는 금품을 말한다.', 10468);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7224, '5.  "처우등급"이란 수형자의 처우 및 관리와 관련하여 수형자를 수용할 시설, 수형자에 대한 계호의 정도, 처우의 수준 및 처우의 내용을 구별하는 기준을 말한다.', 10468);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7225, '6.  "외부통근자"란 건전한 사회복귀와 기술습득을 촉진하기 위하여 외부기업체 또는 교정시설 안에 설치된 외부기업체의 작업장에 통근하며 작업하는 수형자를 말한다.', 10468);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7226, '7.  "교정장비"란 교정시설 안(교도관이 교정시설 밖에서 수용자를 계호하고 있는 경우 그 장소를 포함한다)에서 사람의 생명과 신체의 보호, 도주의 방지 및 교정시설의 안전과 질서유지를 위하여 교도관이 사용하는 장비와 기구 및 그 부속품을 말한다.', 10468);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7227, '1.  3년을 초과하는 징역 또는 금고: 10년', 10470);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7228, '2.  3년 이하의 징역 또는 금고: 5년', 10470);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7229, '1.  평상복은 겨울옷ㆍ봄가을옷ㆍ여름옷을 수형자용(用), 미결수용자용 및 피보호감호자(종전의 「사회보호법」에 따라 보호감호선고를 받고 교정시설에 수용 중인 사람을 말한다. 이하 같다)용과 남녀용으로 각각 구분하여 18종으로 한다.', 10473);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7230, '2.  특수복은 모범수형자복ㆍ외부통근자복ㆍ임산부복ㆍ환자복ㆍ운동복 및 반바지로 구분하고, 그 중 모범수형자복 및 외부통근자복은 겨울옷ㆍ봄가을옷ㆍ여름옷을 남녀용으로 각각 구분하여 6종으로 하고, 임산부복은 봄가을옷ㆍ여름옷을 수형자용과 미결수용자용으로 구분하여 4종으로 하며, 환자복은 겨울옷ㆍ여름옷을 남녀용으로 구분하여 4종으로 하고, 운동복 및 반바지는 각각 1종으로 한다.', 10473);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7231, '3.  보조복은 위생복ㆍ조끼 및 비옷으로 구분하여 3종으로 한다.', 10473);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7232, '4.  의복부속물은 러닝셔츠ㆍ팬티ㆍ겨울내의ㆍ장갑ㆍ양말로 구분하여 5종으로 한다.', 10473);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7233, '5.  모자는 모범수형자모ㆍ외부통근자모ㆍ방한모 및 위생모로 구분하여 4종으로 한다.', 10473);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7234, '6.  신발은 고무신ㆍ운동화 및 방한화로 구분하여 3종으로 한다.', 10473);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7235, '1.  평상복: 실내생활 수용자, 교도작업ㆍ직업능력개발훈련(이하 "직업훈련"이라 한다) 수용자, 각종 교육을 받는 수용자 및 다른 교정시설로 이송되는 수용자가 착용', 10474);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7236, '2.  모범수형자복: 제74조제1항제1호의 개방처우급에 해당하는 수형자가 작업ㆍ교육 등 일상생활을 하는 때, 가석방예정자가 실외생활을 하는 때 및 수형자가 사회봉사활동 등 대내외 행사 참석 시 소장이 필요하다고 인정하는 때 착용', 10474);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7237, '3.  삭제 <2013.4.16>', 10474);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7238, '4.  외부통근자복: 외부통근자로서 실외생활을 하는 때에 착용', 10474);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7239, '5.  임산부복: 임신하거나 출산한 수용자가 착용', 10474);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7240, '6.  환자복: 의료거실 수용자가 착용', 10474);
