INSERT INTO balaw.ho (id, content, hang_id) VALUES (7557, '1.  체포영장, 구속영장, 공소장 또는 재판서에 조직폭력사범으로 명시된 수용자', 10832);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7558, '2.  공소장 또는 재판서에 조직폭력사범으로 명시되어 있지는 아니하나 「폭력행위 등 처벌에 관한 법률」 제4조ㆍ제5조 또는 「형법」 제114조가 적용된 수용자', 10832);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7559, '3.  공범ㆍ피해자 등의 체포영장ㆍ구속영장ㆍ공소장 또는 재판서에 조직폭력사범으로 명시된 수용자', 10832);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7560, '4.  삭제 <2013.4.16>', 10832);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7561, '1.  체포영장ㆍ구속영장ㆍ공소장 또는 재판서에 「마약류관리에 관한 법률」, 「마약류 불법거래방지에 관한 특례법」, 그 밖에 마약류에 관한 형사 법률이 적용된 수용자', 10835);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7562, '2.  제1호에 해당하는 형사 법률을 적용받아 집행유예가 선고되어 그 집행유예 기간 중에 별건으로 수용된 수용자', 10835);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7563, '1.  공소장 변경 또는 재판 확정에 따라 지정사유가 해소되었다고 인정되는 경우', 10837);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7564, '2.  지정 후 5년이 지난 마약류수용자로서 수용생활태도, 교정성적 등이 양호한 경우. 다만, 마약류에 관한 형사 법률 외의 법률이 같이 적용된 마약류수용자로 한정한다.', 10837);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7565, '1.  법무부장관이 정하는 바에 따라 교정시설 안에서 판매되는 물품', 10841);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7566, '2.  그 밖에 마약류 반입을 위한 도구로 이용될 가능성이 없다고 인정되는 물품', 10841);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7567, '1.  다른 수용자에게 상습적으로 폭력을 행사하는 수용자', 10844);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7568, '2.  교도관을 폭행하거나 협박하여 징벌을 받은 전력(前歷)이 있는 사람으로서 같은 종류의 징벌대상행위를 할 우려가 큰 수용자', 10844);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7569, '3.  수용생활의 편의 등 자신의 요구를 관철할 목적으로 상습적으로 자해를 하거나 각종 이물질을 삼키는 수용자', 10844);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7570, '4.  다른 수용자를 괴롭히거나 세력을 모으는 등 수용질서를 문란하게 하는 조직폭력수용자(조직폭력사범으로 행세하는 경우를 포함한다)', 10844);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7571, '5.  조직폭력수용자로서 무죄 외의 사유로 출소한 후 5년 이내에 교정시설에 다시 수용된 사람', 10844);
