INSERT INTO balaw.ho (id, content, hang_id) VALUES (7573, '7.  도주(음모, 예비 또는 미수에 그친 경우를 포함한다)한 전력이 있는 사람으로서 도주의 우려가 있는 수용자', 10844);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7574, '8.  중형선고 등에 따른 심적 불안으로 수용생활에 적응하기 곤란하다고 인정되는 수용자', 10844);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7575, '9.  자살을 기도한 전력이 있는 사람으로서 자살할 우려가 있는 수용자', 10844);
