INSERT INTO balaw.ho (id, content, hang_id) VALUES (7579, '13.  그 밖에 교정시설의 안전과 질서유지를 위하여 엄중한 관리가 필요하다고 인정되는 수용자', 10844);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7580, '1.  교정시설의 안전 또는 질서를 해칠 목적으로 다중(多衆)을 선동하는 행위', 10848);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7581, '2.  허가되지 아니한 단체를 조직하거나 그에 가입하는 행위', 10848);
