INSERT INTO balaw.ho (id, content, hang_id) VALUES (7600, '2.  법 제106조제3호 및 제4호에 해당하는 경우 소장표창 및 제89조에 따른 가족만남의 날 행사 참여 대상자 선정', 10849);
