INSERT INTO balaw.ho (id, content, hang_id) VALUES (7602, '2.  법 제107조제5호, 이 규칙 제214조제4호ㆍ제5호ㆍ제5호의2 및 제6호부터 제8호까지의 규정 중 어느 하나에 해당하는 행위는 다음 각 목의 어느 하나에 처할 것', 10850);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7603, '3.  법 제107조제2호ㆍ제3호 및 이 규칙 제214조제9호부터 제14호까지의 규정 중 어느 하나에 해당하는 행위는 다음 각 목의 어느 하나에 처할 것', 10850);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7604, '4.  제214조제15호부터 제18호까지의 규정 중 어느 하나에 해당하는 행위는 다음 각 목의 어느 하나에 처할 것', 10850);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7605, '5.  징벌대상행위를 하였으나 그 위반 정도가 경미한 경우에는 제1호부터 제4호까지의 규정에도 불구하고 다음 각 목의 어느 하나에 처할 것', 10850);
