INSERT INTO balaw.ho (id, content, hang_id) VALUES (7916, '1.  처우상 독거수용: 일과(日課)시간에는 교육ㆍ작업 등의 처우를 위하여 일과에 따른 공동생활을 하게 하면서 휴업일과 일과시간 이후에는 독거수용하는 것', 11378);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7917, '2.  계호(戒護)상 독거수용: 군수용자의 생명과 신체의 보호 또는 군교정시설의 안전과 질서유지를 위하여 항상 독거수용하여 다른 군수용자와의 접촉을 금지하는 것. 다만, 수사ㆍ재판ㆍ목욕ㆍ접견ㆍ진료 등을 위하여 필요한 경우는 제외한다.', 11378);
