INSERT INTO balaw.ho (id, content, hang_id) VALUES (7955, '6.  제108조제2항에 따른 군미결수용실에 대한 보호장비 사용 실태의 점검', 11533);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7956, '7.  그 밖에 법 제4조제2항에 따른 군미결수용실의 시설ㆍ인력 및 예산 등의 운영에 관한 업무 중 법 및 이 영에 따른 소장의 권한에 속하지 아니하는 업무', 11533);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (7957, '1.  법 제19조에 따른 군교도소(법 제4조제2항에 따라 군교도소에 설치하는 군미결수용실을 포함한다. 이하 이 항에서 같다)에 수용된 군수용자의 이송 승인', 11534);
