INSERT INTO balaw.ho (id, content, hang_id) VALUES (8123, '1.  법 제84조제1항 각 호의 어느 하나에 해당하는 경우에는 별표 4의 방법으로 할 것', 11718);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8124, '2.  법 제84조제1항제2호부터 제4호까지의 어느 하나에 해당하는 경우 별표 4의 방법으로는 사용목적을 달성할 수 없다고 인정되는 경우에는 별표 5의 방법으로 할 것', 11718);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8125, '3.  진료를 받거나 입원 중인 군수용자에 대하여 한손수갑을 사용하는 경우에는 별표 6의 방법으로 할 것', 11718);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8126, '1.  양발목보호장비의 사용은 별표 8의 방법으로 사용할 것', 11722);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8127, '2.  진료를 받거나 입원 중인 군수용자에 대하여 한발목보호장비를 사용하는 경우에는 별표 9의 방법으로 사용할 것', 11722);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8128, '1.  금속보호대는 수갑과 수갑보호기를 보호대에 연결하여 별표 10의 방법으로 사용할 것', 11723);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8129, '2.  벨트보호대는 보호대에 부착된 고리에 수갑을 연결하여 별표 11의 방법으로 사용할 것', 11723);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8130, '1.  고령자, 환자 등 도주의 위험성이 크지 아니하다고 판단되는 군수용자를 개별 호송하는 경우에는 별표 15의 방법으로 할 수 있다.', 11730);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8131, '2.  제1호의 군수용자 외의 군수용자를 호송하는 경우 또는 법 제84조제1항제2호부터 제4호까지의 어느 하나에 해당하는 경우에는 별표 16의 방법으로 한다.', 11730);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8132, '3.  법 제84조제1항제2호부터 제4호까지의 어느 하나에 해당하는 경우로서 제2호의 방법으로는 사용목적을 달성할 수 없다고 인정되는 경우에는 별표 17의 방법으로 한다. 이 경우 2개의 포승을 연결하여 사용할 수 있다.', 11730);
