INSERT INTO balaw.ho (id, content, hang_id) VALUES (8143, '2.  전기교도봉ㆍ전자총: 법 제87조제2항제1호부터 제6호까지의 어느 하나에 해당하는 경우로서 상황이 긴급하여 제1호의 장비만으로는 그 목적을 달성할 수 없는 경우', 11739);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8144, '1.  교도봉ㆍ전기교도봉은 얼굴이나 머리 부분에 사용해서 아니 되며 전기교도봉은 타격 즉시 떼어야 한다.', 11741);
