INSERT INTO balaw.ho (id, content, hang_id) VALUES (8146, '3.  투척용 최루탄은 근거리용으로 사용하고, 발사용 최루탄은 50미터 이상의 원거리에서 사용하되 30도 이상의 발사각을 유지하여야 한다.', 11741);
