INSERT INTO balaw.ho (id, content, hang_id) VALUES (8155, '2.  기관총: 법 제88조제2항에 해당하는 경우로서 제1호의 무기만으로는 그 목적을 달성할 수 없다고 인정하는 경우', 11744);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8156, '1.  군교정시설의 안전 또는 질서를 해칠 목적으로 사람들을 선동하는 행위', 11752);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8157, '2.  허가되지 아니한 단체를 조직하거나 그 단체에 가입하는 행위', 11752);
