INSERT INTO balaw.ho (id, content, hang_id) VALUES (8159, '4.  음란한 행위를 하거나 다른 사람에게 성적(性的)인 말이나 행동으로 성적 수치심 또는 혐오감을 느끼게 하는 행위', 11752);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8160, '5.  다른 사람에게 부당한 금품을 요구하는 행위', 11752);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8161, '6.  작업, 교육, 접견, 집필, 전화통화, 운동, 그 밖에 군교도관의 직무 또는 다른 군수용자의 정상적인 일과(日課) 진행을 방해하는 행위', 11752);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8162, '7.  문신을 하거나 이물질을 신체에 삽입하는 등 의료 외의 목적으로 신체를 변형하는 행위', 11752);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8163, '8.  허가 없이 지정된 장소를 벗어나거나 금지구역을 출입하는 행위', 11752);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8164, '9.  허가 없이 다른 사람과 만나거나 연락하는 행위', 11752);
