INSERT INTO balaw.ho (id, content, hang_id) VALUES (8166, '11.  인원점검을 회피하거나 방해하는 행위', 11752);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8167, '12.  군교정시설의 설비나 물품을 고의로 훼손하거나 낭비하는 행위', 11752);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8168, '13.  고의로 군수용자 번호표, 거실표, 작업장 표시표 등을 지정된 위치에 붙이지 아니하거나 그 밖의 방법으로 현황파악을 방해하는 행위', 11752);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8169, '14.  고성으로 떠들거나 소음을 일으켜 다른 군수용자의 평온한 수용생활을 현저히 방해하는 행위', 11752);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8170, '15.  허가 없이 물품을 반입ㆍ제작ㆍ소지ㆍ변조ㆍ수수 또는 교환하는 행위', 11752);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8171, '16.  도박이나 그 밖에 사행심을 조장하는 놀이나 내기를 하는 행위', 11752);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8172, '17.  지정된 거실에의 입실을 거부하는 등 정당한 사유 없이 군교도관의 직무상 지시나 명령을 따르지 아니하는 행위', 11752);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8173, '18.  군수용자 상호간의 욕설 및 구타행위', 11752);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8174, '19.  그 밖에 군수용자의 안전과 수용질서를 유지하기 위하여 군교도관으로부터 지시받은 사항을 고의적으로 위반하는 행위', 11752);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8175, '1.  법 제93조제1호ㆍ제4호 및 이 규칙 제148조제1호부터 제3호까지의 어느 하나에 해당하는 행위: 21일 이상 30일 이하의 금치(禁置)', 11753);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8176, '2.  법 제93조제5호 및 이 규칙 제148조제4호부터 제8호까지의 어느 하나에 해당하는 행위는 다음 각 목의 어느 하나의 징벌을 부과한다.', 11753);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8177, '3.  법 제93조제2호ㆍ제3호 및 이 규칙 제148조제9호부터 제14호까지의 어느 하나에 해당하는 행위는 다음 각 목의 어느 하나의 징벌을 부과한다.', 11753);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8178, '4.  이 규칙 제148조제15호부터 제19호까지의 어느 하나에 해당하는 행위는 다음 각 목의 어느 하나의 징벌을 부과한다.', 11753);
