INSERT INTO balaw.ho (id, content, hang_id) VALUES (8468, '4.  "전달금품"이란 수용자 외의 사람이 교정시설의 장(이하 "소장"이라 한다)의 허가를 받아 수용자에게 건넬 수 있는 금품을 말한다.', 12320);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8469, '5.  "처우등급"이란 수형자의 처우 및 관리와 관련하여 수형자를 수용할 시설, 수형자에 대한 계호의 정도, 처우의 수준 및 처우의 내용을 구별하는 기준을 말한다.', 12320);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8470, '6.  "외부통근자"란 건전한 사회복귀와 기술습득을 촉진하기 위하여 외부기업체 또는 교정시설 안에 설치된 외부기업체의 작업장에 통근하며 작업하는 수형자를 말한다.', 12320);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8471, '7.  "교정장비"란 교정시설 안(교도관이 교정시설 밖에서 수용자를 계호하고 있는 경우 그 장소를 포함한다)에서 사람의 생명과 신체의 보호, 도주의 방지 및 교정시설의 안전과 질서유지를 위하여 교도관이 사용하는 장비와 기구 및 그 부속품을 말한다.', 12320);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8472, '1.  3년을 초과하는 징역 또는 금고: 10년', 12322);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8473, '2.  3년 이하의 징역 또는 금고: 5년', 12322);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8474, '1.  평상복은 겨울옷ㆍ봄가을옷ㆍ여름옷을 수형자용(用), 미결수용자용 및 피보호감호자(종전의 「사회보호법」에 따라 보호감호선고를 받고 교정시설에 수용 중인 사람을 말한다. 이하 같다)용과 남녀용으로 각각 구분하여 18종으로 한다.', 12325);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8475, '2.  특수복은 모범수형자복ㆍ외부통근자복ㆍ임산부복ㆍ환자복ㆍ운동복 및 반바지로 구분하고, 그 중 모범수형자복 및 외부통근자복은 겨울옷ㆍ봄가을옷ㆍ여름옷을 남녀용으로 각각 구분하여 6종으로 하고, 임산부복은 봄가을옷ㆍ여름옷을 수형자용과 미결수용자용으로 구분하여 4종으로 하며, 환자복은 겨울옷ㆍ여름옷을 남녀용으로 구분하여 4종으로 하고, 운동복 및 반바지는 각각 1종으로 한다.', 12325);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8476, '3.  보조복은 위생복ㆍ조끼 및 비옷으로 구분하여 3종으로 한다.', 12325);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8477, '4.  의복부속물은 러닝셔츠ㆍ팬티ㆍ겨울내의ㆍ장갑ㆍ양말로 구분하여 5종으로 한다.', 12325);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8478, '5.  모자는 모범수형자모ㆍ외부통근자모ㆍ방한모 및 위생모로 구분하여 4종으로 한다.', 12325);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8479, '6.  신발은 고무신ㆍ운동화 및 방한화로 구분하여 3종으로 한다.', 12325);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8480, '1.  평상복: 실내생활 수용자, 교도작업ㆍ직업능력개발훈련(이하 "직업훈련"이라 한다) 수용자, 각종 교육을 받는 수용자 및 다른 교정시설로 이송되는 수용자가 착용', 12326);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8481, '2.  모범수형자복: 제74조제1항제1호의 개방처우급에 해당하는 수형자가 작업ㆍ교육 등 일상생활을 하는 때, 가석방예정자가 실외생활을 하는 때 및 수형자가 사회봉사활동 등 대내외 행사 참석 시 소장이 필요하다고 인정하는 때 착용', 12326);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8482, '3.  삭제 <2013.4.16>', 12326);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8483, '4.  외부통근자복: 외부통근자로서 실외생활을 하는 때에 착용', 12326);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8484, '5.  임산부복: 임신하거나 출산한 수용자가 착용', 12326);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8485, '6.  환자복: 의료거실 수용자가 착용', 12326);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8486, '7.  삭제 <2013.4.16>', 12326);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8487, '8.  운동복: 소년수용자로서 운동을 하는 때에 착용', 12326);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8488, '9.  반바지: 수용자가 여름철에 실내생활 또는 운동을 하는 때에 착용', 12326);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8489, '10.  위생복: 수용자가 운영지원작업(이발ㆍ취사ㆍ간병, 그 밖에 교정시설의 시설운영과 관리에 필요한 작업을 말한다. 이하 같다)을 하는 때에 착용', 12326);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8490, '11.  조끼: 수용자가 겨울철에 겉옷 안에 착용', 12326);
