INSERT INTO balaw.ho (id, content, hang_id) VALUES (8492, '13.  러닝셔츠ㆍ팬티ㆍ겨울내의 및 양말: 모든 수형자 및 소장이 지급할 필요가 있다고 인정하는 미결수용자가 착용', 12326);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8493, '14.  장갑: 작업을 하는 수용자 중 소장이 지급할 필요가 있다고 인정하는 자가 착용', 12326);
