INSERT INTO balaw.ho (id, content, hang_id) VALUES (8796, '1.  조직폭력수용자(제199조제1항에 따라 지정된 수용자를 말한다. 이하 같다)', 12677);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8797, '2.  마약류수용자(제205조제1항에 따라 지정된 수용자를 말한다. 이하 같다)', 12677);
