INSERT INTO balaw.ho (id, content, hang_id) VALUES (8801, '3.  마약류수용자: 파란색', 12678);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8802, '1.  체포영장, 구속영장, 공소장 또는 재판서에 조직폭력사범으로 명시된 수용자', 12684);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8803, '2.  공소장 또는 재판서에 조직폭력사범으로 명시되어 있지는 아니하나 「폭력행위 등 처벌에 관한 법률」 제4조ㆍ제5조 또는 「형법」 제114조가 적용된 수용자', 12684);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8804, '3.  공범ㆍ피해자 등의 체포영장ㆍ구속영장ㆍ공소장 또는 재판서에 조직폭력사범으로 명시된 수용자', 12684);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8805, '4.  삭제 <2013.4.16>', 12684);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8806, '1.  체포영장ㆍ구속영장ㆍ공소장 또는 재판서에 「마약류관리에 관한 법률」, 「마약류 불법거래방지에 관한 특례법」, 그 밖에 마약류에 관한 형사 법률이 적용된 수용자', 12687);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8807, '2.  제1호에 해당하는 형사 법률을 적용받아 집행유예가 선고되어 그 집행유예 기간 중에 별건으로 수용된 수용자', 12687);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8808, '1.  공소장 변경 또는 재판 확정에 따라 지정사유가 해소되었다고 인정되는 경우', 12689);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8809, '2.  지정 후 5년이 지난 마약류수용자로서 수용생활태도, 교정성적 등이 양호한 경우. 다만, 마약류에 관한 형사 법률 외의 법률이 같이 적용된 마약류수용자로 한정한다.', 12689);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8810, '1.  법무부장관이 정하는 바에 따라 교정시설 안에서 판매되는 물품', 12693);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8811, '2.  그 밖에 마약류 반입을 위한 도구로 이용될 가능성이 없다고 인정되는 물품', 12693);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8812, '1.  다른 수용자에게 상습적으로 폭력을 행사하는 수용자', 12696);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8813, '2.  교도관을 폭행하거나 협박하여 징벌을 받은 전력(前歷)이 있는 사람으로서 같은 종류의 징벌대상행위를 할 우려가 큰 수용자', 12696);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8814, '3.  수용생활의 편의 등 자신의 요구를 관철할 목적으로 상습적으로 자해를 하거나 각종 이물질을 삼키는 수용자', 12696);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8815, '4.  다른 수용자를 괴롭히거나 세력을 모으는 등 수용질서를 문란하게 하는 조직폭력수용자(조직폭력사범으로 행세하는 경우를 포함한다)', 12696);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8816, '5.  조직폭력수용자로서 무죄 외의 사유로 출소한 후 5년 이내에 교정시설에 다시 수용된 사람', 12696);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8817, '6.  상습적으로 교정시설의 설비ㆍ기구 등을 파손하거나 소란행위를 하여 공무집행을 방해하는 수용자', 12696);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8818, '7.  도주(음모, 예비 또는 미수에 그친 경우를 포함한다)한 전력이 있는 사람으로서 도주의 우려가 있는 수용자', 12696);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8819, '8.  중형선고 등에 따른 심적 불안으로 수용생활에 적응하기 곤란하다고 인정되는 수용자', 12696);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8820, '9.  자살을 기도한 전력이 있는 사람으로서 자살할 우려가 있는 수용자', 12696);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8821, '10.  사회적 물의를 일으킨 사람으로서 죄책감 등으로 인하여 자살 등 교정사고를 일으킬 우려가 큰 수용자', 12696);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8822, '11.  징벌집행이 종료된 날부터 1년 이내에 다시 징벌을 받는 등 규율 위반의 상습성이 인정되는 수용자', 12696);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8823, '12.  상습적으로 법령에 위반하여 연락을 하거나 금지물품을 반입하는 등의 방법으로 부조리를 기도하는 수용자', 12696);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8824, '13.  그 밖에 교정시설의 안전과 질서유지를 위하여 엄중한 관리가 필요하다고 인정되는 수용자', 12696);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8825, '1.  교정시설의 안전 또는 질서를 해칠 목적으로 다중(多衆)을 선동하는 행위', 12700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8826, '2.  허가되지 아니한 단체를 조직하거나 그에 가입하는 행위', 12700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8827, '3.  교정장비, 도주방지시설, 그 밖의 보안시설의 기능을 훼손하는 행위', 12700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8828, '4.  음란한 행위를 하거나 다른 사람에게 성적(性的) 언동 등으로 성적 수치심 또는 혐오감을 느끼게 하는 행위', 12700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8829, '5.  다른 사람에게 부당한 금품을 요구하는 행위', 12700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8830, '5의2.  허가 없이 다른 수용자에게 금품을 교부하거나 수용자 외의 사람을 통하여 다른 수용자에게 금품을 교부하는 행위', 12700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8831, '6.  작업ㆍ교육ㆍ접견ㆍ집필ㆍ전화통화ㆍ운동, 그 밖에 교도관의 직무 또는 다른 수용자의 정상적인 일과 진행을 방해하는 행위', 12700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8832, '7.  문신을 하거나 이물질을 신체에 삽입하는 등 의료 외의 목적으로 신체를 변형시키는 행위', 12700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8833, '8.  허가 없이 지정된 장소를 벗어나거나 금지구역에 출입하는 행위', 12700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8834, '9.  허가 없이 다른 사람과 만나거나 연락하는 행위', 12700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8835, '10.  수용생활의 편의 등 자신의 요구를 관철할 목적으로 이물질을 삼키는 행위', 12700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8836, '11.  인원점검을 회피하거나 방해하는 행위', 12700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8837, '12.  교정시설의 설비나 물품을 고의로 훼손하거나 낭비하는 행위', 12700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8838, '13.  고의로 수용자의 번호표, 거실표 등을 지정된 위치에 붙이지 아니하거나 그 밖의 방법으로 현황파악을 방해하는 행위', 12700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8839, '14.  큰 소리를 내거나 시끄럽게 하여 다른 수용자의 평온한 수용생활을 현저히 방해하는 행위', 12700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8840, '15.  허가 없이 물품을 지니거나 반입ㆍ제작ㆍ변조ㆍ교환 또는 주고받는 행위', 12700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8841, '16.  도박이나 그 밖에 사행심을 조장하는 놀이나 내기를 하는 행위', 12700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8842, '17.  지정된 거실에 입실하기를 거부하는 등 정당한 사유 없이 교도관의 직무상 지시나 명령을 따르지 아니하는 행위', 12700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8843, '18.  공연히 다른 사람을 해할 의사를 표시하는 행위', 12700);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8844, '1.  법 제106조제1호 및 제2호에 해당하는 경우 소장표창 및 제89조에 따른 가족만남의 집 이용 대상자 선정', 12701);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8845, '2.  법 제106조제3호 및 제4호에 해당하는 경우 소장표창 및 제89조에 따른 가족만남의 날 행사 참여 대상자 선정', 12701);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8846, '1.  법 제107조제1호ㆍ제4호 및 이 규칙 제214조제1호부터 제3호까지의 규정 중 어느 하나에 해당하는 행위는 21일 이상 30일 이하의 금치(禁置)에 처할 것. 다만, 위반의 정도가 경미한 경우 그 기간의 2분의 1의 범위에서 감경할 수 있다.', 12702);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (8847, '2.  법 제107조제5호, 이 규칙 제214조제4호ㆍ제5호ㆍ제5호의2 및 제6호부터 제8호까지의 규정 중 어느 하나에 해당하는 행위는 다음 각 목의 어느 하나에 처할 것', 12702);
