INSERT INTO balaw.ho (id, content, hang_id) VALUES (9247, '3.  그 밖에 기부자가 보호소년등과 직접적인 이해관계가 있다고 인정되는 기관ㆍ단체 또는 사람인 경우', 13288);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9248, '1.  보호소년등의 의류 및 소지품 등의 검사', 13297);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9249, '2.  신상조사', 13297);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9250, '3.  건강진단 및 신체검사', 13297);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9251, '4.  이발ㆍ목욕 및 피복지급 등 위생에 필요한 조치', 13297);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9252, '5.  사진촬영', 13297);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9253, '1.  「소년법」 제32조제1항제7호부터 제10호까지의 규정에 따라 위탁되거나 송치된 보호소년', 13299);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9254, '2.  제53조에 따른 신입자교육을 받고 있는 보호소년', 13299);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9255, '3.  감염병에 감염된 보호소년등', 13299);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9256, '4.  공동으로 비행을 저지르는 등 특별관리가 필요하다고 인정되는 보호소년등', 13299);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9257, '1.  정신질환자(알코올중독자 및 약물중독자를 포함한다)', 13309);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9258, '2.  신체질환자(뇌전증 환자를 포함한다)', 13309);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9259, '1.  법 제14조의2제2항 각 호의 어느 하나에 해당하는 경우에는 별표 1의 방법으로 할 것', 13317);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9260, '2.  법 제14조의2제2항제1호 또는 제3호에 해당하는 경우로서 별표 1의 방법으로는 사용 목적을 달성할 수 없다고 인정되는 경우에는 별표 1의2의 방법으로 할 것. 이 경우 별표 1의2의 방법으로 수갑을 사용하여 그 목적을 달성했을 때에는 즉시 별표 1의 방법으로 바꾸거나 사용을 중지해야 한다.', 13317);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9261, '3.  외부 의료기관에 입원 중인 보호소년등에 대하여 한 손 수갑을 사용할 경우에는 별표 1의3의 방법으로 할 것', 13317);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9262, '1.  환자, 진학ㆍ취업 등을 위한 면접 대상자 등을 개별 호송하는 경우로서 이탈할 위험성이 크지 않다고 판단되는 경우에는 별표 1의4부터 별표 1의6까지의 방법으로 할 것', 13318);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9263, '2.  법 제14조의2제2항제2호의 경우(이 항 제1호의 경우는 제외한다)에는 별표 1의7 또는 별표 1의8의 방법으로 할 것. 다만, 3명 이상의 보호소년등을 호송하는 경우에는 별표 1의4의 방법으로 할 수 있다.', 13318);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9264, '3.  법 제14조의2제2항 각 호의 어느 하나에 해당하는 경우로서 별표 1의4부터 별표 1의8까지의 방법으로는 사용 목적을 달성할 수 없다고 인정되는 경우에만 별표 1의9의 방법으로 할 것', 13318);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9265, '4.  3명 이상의 보호소년등을 인솔하거나 호송하는 경우에는 연속으로 포승을 할 것. 이 경우 성별이 다른 보호소년등은 서로 분리하여 연결해야 한다.', 13318);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9266, '1.  가스총은 법 제14조의2제3항 각 호의 어느 하나에 해당하는 경우만 사용할 것', 13319);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9267, '2.  가스총을 사용하려면 법 제14조의2제4항에 따라 상대방에게 이를 경고할 것', 13319);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9268, '3.  가스총을 발사할 때는 해당 보호소년등의 안전 및 가스총 발사효과 등을 고려하여 발사거리를 2미터 이상 유지할 것', 13319);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9269, '1.  전자충격기는 법 제14조의2제3항 각 호의 어느 하나에 해당하는 경우로서 상황이 긴급하여 가스총만으로는 그 목적을 달성할 수 없는 경우에만 사용할 것', 13320);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9270, '2.  전자충격기를 사용하려면 법 제14조의2제4항에 따라 상대방에게 이를 경고할 것', 13320);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9271, '3.  전자충격기를 사용할 때에는 상대방의 피해를 최소화하도록 노력할 것', 13320);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9272, '4.  전자충격기를 사용할 때에는 상대방의 머리, 얼굴, 가슴, 그 밖에 치명적 피해를 줄 수 있는 부위에는 사용하지 말 것', 13320);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9273, '5.  전자충격기를 사용했을 때에는 충격 즉시 전자충격기를 떼어낼 것', 13320);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9274, '1.  영상정보처리기기: 일정한 공간에 지속적으로 설치되어 사람 또는 사물의 영상 및 이에 따르는 음성ㆍ음향 등을 수신하거나 유ㆍ무선망을 통하여 이를 전송하는 장치', 13330);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9275, '2.  전자감지기: 일정한 공간에 지속적으로 설치되어 사람 또는 사물의 움직임을 빛ㆍ온도ㆍ소리ㆍ압력 등을 이용하여 감지하고 전송하는 장치', 13330);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9276, '3.  전자이름표: 전자파를 발신하고 추적하는 원리를 이용하여 사람의 위치를 확인하거나 이동경로를 탐지하는 일련의 기계적 장치', 13330);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9277, '4.  물품검색기(고정식 물품검색기와 휴대식 금속탐지기를 말한다)', 13330);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9278, '5.  증거수집장비: 디지털카메라, 녹음기, 비디오카메라 등 증거수집에 필요한 장비', 13330);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9279, '1.  보호소년등이 이탈을 하는 행위', 13342);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9280, '2.  다른 사람을 처벌받게 하거나 직원의 집무집행을 방해할 목적으로 거짓사실을 신고하는 행위', 13342);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9281, '3.  보호장비, 전자장비, 그 밖의 보안시설의 기능을 훼손하는 행위', 13342);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9282, '4.  음란한 행위를 하거나 다른 사람에게 성적 언동 등으로 성적 수치심 또는 혐오감을 느끼게 하는 행위', 13342);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9283, '5.  다른 사람에게 부당한 금품을 요구하는 행위', 13342);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9284, '6.  교육ㆍ면회ㆍ전화통화 등 다른 보호소년등의 정상적인 일과진행 또는 직원의 직무를 방해하는 행위', 13342);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9285, '7.  문신을 하거나 이물질을 신체에 삽입하는 등 신체를 변형시키는 행위', 13342);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9286, '8.  허가 없이 지정된 장소를 벗어나거나 금지구역에 출입하는 행위', 13342);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9287, '9.  허가 없이 다른 사람과 만나거나 연락하는 행위', 13342);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9288, '10.  수용생활의 편의 등 자신의 요구를 관철할 목적으로 이물질을 삼키는 행위', 13342);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9289, '11.  인원점검을 회피하거나 방해하는 행위', 13342);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9290, '12.  시설의 설비나 물품을 고의로 훼손하는 행위', 13342);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9291, '13.  큰 소리를 내거나 시끄럽게 하여 다른 보호소년등의 평온한 생활을 방해하는 행위', 13342);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9292, '14.  도박이나 그 밖에 사행심을 조장하는 놀이나 내기를 하는 행위', 13342);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9293, '15.  지정된 생활실에 입실하기를 거부하는 등 정당한 사유 없이 직원의 직무상 지시나 명령을 따르지 아니하는 행위', 13342);
