INSERT INTO balaw.ho (id, content, hang_id) VALUES (9296, '3.  서면사과: 30점', 13345);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9297, '4.  텔레비전 시청 제한: 50점', 13345);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9298, '5.  단체 체육활동 정지: 50점', 13345);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9299, '6.  공동행사 참가 정지: 50점', 13345);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9300, '7.  7일 미만의 근신: 60점', 13345);
