INSERT INTO balaw.ho (id, content, hang_id) VALUES (9302, '1.  인권침해가 발생하지 아니하도록 유의할 것', 13348);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9303, '2.  조사의 이유를 설명하고, 충분한 진술의 기회를 제공할 것', 13348);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9304, '3.  공정한 절차와 객관적 증거에 따라 조사하고, 선입견이나 추측에 따라 처리하지 아니할 것', 13348);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9305, '4.  형사 법률에 저촉되는 행위에 대하여 징계 부과 외에 형사입건조치가 요구되는 경우에는 형사소송절차에 따라 조사대상자에게 진술을 거부할 수 있다는 것과 변호인을 선임할 수 있다는 것을 알릴 것', 13348);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9306, '1.  교육에 유해하다고 인정되는 물품', 13349);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9307, '2.  위화감을 조장할 수 있다고 판단되는 고가품', 13349);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9308, '3.  적정 소요량을 초과한 것으로 인정되는 물품', 13349);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9309, '1.  면회시간ㆍ절차 및 면회시 유의사항 등이 작성된 안내문', 13352);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9310, '2.  청원함', 13352);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9311, '1.  처음 면회온 사람으로서 면회에 관한 법령을 알지 못한 경우', 13356);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9312, '2.  환자인 보호소년등을 면회하는 경우', 13356);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9313, '3.  보호소년등의 직계존속이 원격지에서 면회를 오는 경우', 13356);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9314, '4.  통신망을 이용한 화상면회를 하는 경우', 13356);
