INSERT INTO balaw.ho (id, content, hang_id) VALUES (9316, '6.  교정교육 활동의 하나로 사전에 수립된 계획에 포함된 경우', 13356);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9317, '7.  보호소년등의 가족관계 개선 등을 위하여 원장이 특별히 필요하다고 인정하는 경우', 13356);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9318, '1.  재범의 유혹이나 충동을 느낄 수 있는 장소에 출입하지 아니할 것', 13362);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9319, '2.  사행행위를 하지 아니할 것', 13362);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9320, '3.  음주ㆍ흡연을 하지 아니할 것', 13362);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9321, '4.  마약ㆍ향정신성의약품ㆍ대마 등 오ㆍ남용의 위험성이 있거나 건강에 해로운 물질을 사용하지 아니할 것', 13362);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9322, '5.  그 밖에 보호자의 훈육의지에 반하는 행위나 불량한 교우관계를 형성하지 아니할 것', 13362);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9323, '1.  일반분류심사: 문제 또는 비행원인이 비교적 단순한 소년에 대하여 면접조사와 신체의학적 진찰, 집단검사, 자기기록 검토, 자료조회, 행동관찰 등을 주로 하여 실시하는 분류심사', 13379);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9324, '2.  특수분류심사: 일반분류심사결과 문제 또는 비행원인이 중대하고 복잡한 소년에 대하여 개별검사와 정신의학적 진단, 현지조사 등을 추가하여 실시하는 분류심사', 13379);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9325, '1.  법 제3조제2항 각 호의 소년에 대한 면접조사의 경우: 직접 면담하는 방법', 13381);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9326, '2.  법 제3조제2항 각 호의 소년의 보호자 및 그 밖의 참고인에 대한 면접조사의 경우: 직접 면담하거나 전화 등을 이용하는 방법', 13381);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9327, '1.  법무부장관이 정하는 바에 따라 분류심사관의 자격 인정을 받은 사람', 13385);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9328, '2.  분류심사 업무를 목적으로 특별채용된 사람', 13385);
