INSERT INTO balaw.ho (id, content, hang_id) VALUES (9532, '1.  담당검사가 법 제197조의2제1항제2호에 따른 보완수사요구(이하 "보완수사요구"라 한다) 없이 영장을 청구하지 않기로 한 결정서를 송부한 경우: 해당 결정서가 영장을 신청한 사법경찰관 소속 경찰관서에 접수된 날', 13703);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9533, '2.  담당검사가 사법경찰관이 영장을 신청한 날(담당검사가 관계 서류와 증거물을 사법경찰관에게 반환하지 않은 상태로 보완수사요구를 한 경우에는 사법경찰관이 보완수사요구 이행 결과 서면을 검찰청에 접수한 날을 말한다. 이하 이 호에서 같다)부터 5일(토요일과 공휴일은 제외한다)이 지나도록 영장의 청구 여부를 결정하지 않은 경우: 영장신청일부터 5일(토요일과 공휴일은 제외한다)이 지난 날. 다만, 담당검사와 영장을 신청한 사법경찰관이 협의하여 영장신청일부터 10일(토요일과 공휴일은 제외한다) 이내의 범위에서 영장 청구 여부의 결정기한을 연기했을 때에는 그 기한이 지난 날로 한다.', 13703);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9534, '3.  사법경찰관이 죄명과 기본적 사실관계가 동일한 내용의 영장에 대하여 두 차례에 걸쳐 보완수사요구를 받아 이를 이행한 경우: 담당검사로부터 세 번째 보완수사요구를 받은 날', 13703);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9535, '1.  제13조제1항제1호의 경우: 담당검사가 사법경찰관의 영장 신청을 기각한 때', 13725);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9536, '2.  제13조제1항제2호의 경우: 영장신청일부터 5일(토요일과 공휴일은 제외한다) 또는 별도로 협의한 영장 청구 여부의 결정기한이 지난 때', 13725);
