INSERT INTO balaw.ho (id, content, hang_id) VALUES (9724, '2.  청구인이 법원의 보정명령에 따르지 아니할 경우', 13975);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9725, '3.  제8조에 따른 보상청구의 기간이 지난 후에 보상을 청구하였을 경우', 13975);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9726, '1.  「형사소송법」에 따라 면소(免訴) 또는 공소기각(公訴棄却)의 재판을 받아 확정된 피고인이 면소 또는 공소기각의 재판을 할 만한 사유가 없었더라면 무죄재판을 받을 만한 현저한 사유가 있었을 경우', 13992);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9727, '2.  「치료감호법」 제7조에 따라 치료감호의 독립 청구를 받은 피치료감호청구인의 치료감호사건이 범죄로 되지 아니하거나 범죄사실의 증명이 없는 때에 해당되어 청구기각의 판결을 받아 확정된 경우', 13992);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9728, '3.  「헌법재판소법」에 따른 재심 절차에서 원판결보다 가벼운 형으로 확정됨에 따라 원판결에 의한 형 집행이 재심 절차에서 선고된 형을 초과한 경우', 13992);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9729, '1.  본인이 수사 또는 재판을 그르칠 목적으로 거짓 자백을 하거나 다른 유죄의 증거를 만듦으로써 구금된 것으로 인정되는 경우', 13996);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9730, '2.  구금기간 중에 다른 사실에 대하여 수사가 이루어지고 그 사실에 관하여 범죄가 성립한 경우', 13996);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9731, '3.  보상을 하는 것이 선량한 풍속이나 그 밖에 사회질서에 위배된다고 인정할 특별한 사정이 있는 경우', 13996);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9732, '1.  군사법원에서 무죄재판을 받아 확정된 자', 14006);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9733, '2.  군사법원에서 제26조제1항 각 호에 해당하는 재판을 받은 자', 14006);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9734, '3.  군검찰부 군검사로부터 공소를 제기하지 아니하는 처분을 받은 자', 14006);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9735, '1.  청구인이 무죄재판서 중 일부 내용의 삭제를 원하는 의사를 명시적으로 밝힌 경우', 14012);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9736, '2.  무죄재판서의 공개로 인하여 사건 관계인의 명예나 사생활의 비밀 또는 생명ㆍ신체의 안전이나 생활의 평온을 현저히 해칠 우려가 있는 경우', 14012);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9737, '1.  군사법원에서 무죄재판을 받아 확정된 자', 14019);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9738, '2.  군사법원에서 제26조제1항 각 호에 해당하는 재판을 받은 자', 14019);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9739, '1.  해당 지방검찰청 소속 공무원', 14020);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9740, '2.  법관 자격을 가진 사람', 14020);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9741, '3.  의사', 14020);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9742, '1.  청구인의 성명, 주소, 생년월일 및 직업', 14026);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9743, '2.  청구의 취지 및 이유', 14026);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9744, '3.  청구 연월일', 14026);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9745, '1.  청구인의 성명, 주소 및 생년월일', 14031);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9746, '2.  결정주문(決定主文)', 14031);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9747, '3.  결정의 이유', 14031);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9748, '4.  결정 연월일', 14031);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9749, '1.  청구인의 성명, 주소 및 생년월일', 14033);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9750, '2.  보상결정의 사건번호 및 결정주문', 14033);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9751, '3.  청구 연월일', 14033);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9752, '1.  "특정범죄"란 재산상의 부정한 이익을 취득할 목적으로 범한 죄로서 다음 각 목의 어느 하나에 해당하는 것을 말한다.', 14036);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9753, '2.  "범죄수익"이란 다음 각 목의 어느 하나에 해당하는 것을 말한다.', 14036);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9754, '3.  "범죄수익에서 유래한 재산"이란 범죄수익의 과실(果實)로 얻은 재산, 범죄수익의 대가(對價)로 얻은 재산 및 이들 재산의 대가로 얻은 재산, 그 밖에 범죄수익의 보유 또는 처분에 의하여 얻은 재산을 말한다.', 14036);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9755, '4.  "범죄수익등"이란 범죄수익, 범죄수익에서 유래한 재산 및 이들 재산과 그 외의 재산이 합쳐진 재산을 말한다.', 14036);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9756, '5.  "다중인명피해사고"란 고의 또는 과실에 의한 화재, 붕괴, 폭발, 선박ㆍ항공기ㆍ열차 사고를 포함하는 교통사고, 화생방사고, 환경오염사고 등으로서 국가 또는 지방자치단체 차원의 대처가 필요한 인명피해를 야기한 사고를 말한다.', 14036);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9757, '1.  범죄수익등의 취득 또는 처분에 관한 사실을 가장한 자', 14037);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9758, '2.  범죄수익의 발생 원인에 관한 사실을 가장한 자', 14037);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9759, '3.  특정범죄를 조장하거나 적법하게 취득한 재산으로 가장할 목적으로 범죄수익등을 은닉한 자', 14037);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9760, '1.  범죄수익', 14043);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9761, '2.  범죄수익에서 유래한 재산', 14043);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9762, '3.  제3조 또는 제4조의 범죄행위에 관계된 범죄수익등', 14043);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9763, '4.  제3조 또는 제4조의 범죄행위에 의하여 생긴 재산 또는 그 범죄행위의 보수로 얻은 재산', 14043);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9764, '5.  제3호 또는 제4호에 따른 재산의 과실 또는 대가로 얻은 재산 또는 이들 재산의 대가로 얻은 재산, 그 밖에 그 재산의 보유 또는 처분에 의하여 얻은 재산', 14043);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9765, '1.  관계인의 출석 요구 및 진술의 청취', 14050);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9766, '2.  서류나 그 밖의 물건의 소유자ㆍ소지자 또는 보관자에 대한 제출 요구', 14050);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9767, '3.  「특정 금융거래정보의 보고 및 이용 등에 관한 법률」 제10조제1항에 따른 특정금융거래정보의 제공 요청', 14050);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9768, '4.  「국세기본법」 제81조의13에 따른 과세정보의 제공 요청', 14050);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9769, '5.  「금융실명거래 및 비밀보장에 관한 법률」 제4조제1항에 따른 금융거래의 내용에 대한 정보 또는 자료의 제공 요청', 14050);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9770, '6.  그 밖의 공공기관 또는 단체에 대한 사실조회나 필요한 사항에 대한 보고 요구', 14050);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9771, '1.  「아동ㆍ청소년의 성보호에 관한 법률」 제11조, 제12조 및 제15조의 죄', 14053);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9772, '2.  「성폭력범죄의 처벌 등에 관한 특례법」 제14조 및 제14조의2의 죄', 14053);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9773, '1.  공조 요청의 대상이 되는 범죄와 관련된 행위가 대한민국 내에서 행하여진 경우 그 행위가 대한민국의 법령에 따라 특정범죄 또는 제3조 및 제4조의 죄에 해당하지 아니한다고 인정되는 경우', 14054);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9774, '2.  대한민국이 같은 종류의 공조 요청을 할 경우 그 요청에 응한다는 취지의 공조요청국의 보증이 없는 경우', 14054);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9775, '3.  「마약류 불법거래 방지에 관한 특례법」 제64조제1항 각 호의 어느 하나에 해당하는 경우', 14054);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9776, '1.  법 제2조제1호의 특정범죄 또는 법 제3조ㆍ제4조의 죄에 해당하는 행위에 대하여 수사의 단서를 제공한 경우', 14057);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9777, '2.  법 제8조제2항에 따른 몰수대상재산(이하 "몰수대상재산"이라 한다)에 대하여 신고하거나 그 재산의 소재를 확인할 수 있는 중요한 정보를 제공한 경우', 14057);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9778, '3.  몰수ㆍ추징의 판결이 확정된 자의 은닉재산을 신고하거나 그 재산의 소재를 확인할 수 있는 중요한 정보를 제공한 경우', 14057);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9779, '1.  「국세징수법」 제25조 등에 따라 국가 또는 지방자치단체의 청구에 의하여 사해행위(詐害行爲) 취소소송의 대상이 되어 있는 재산', 14058);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9780, '2.  검사가 은닉 사실을 알고 조사 또는 「국세징수법」에 따른 체납처분 절차에 착수한 재산', 14058);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9781, '1.  신고, 고발 등 수사 단서 내용의 정확성', 14060);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9782, '2.  해당 몰수ㆍ추징에 기여한 정도', 14060);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9783, '3.  사건의 난이도', 14060);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9784, '4.  범죄의 경중(輕重)과 규모', 14060);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9785, '1.  거짓이나 그 밖의 부정한 방법으로 포상금을 지급받은 경우', 14065);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9786, '2.  그 밖에 착오 등의 사유로 포상금이 잘못 지급된 경우', 14065);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9787, '1.  "선박"이란 기선(機船), 범선(帆船), 부선(艀船) 및 잠수선(潛水船) 등 해저(海底)에 항상 고착되어 있지 아니한 모든 형태의 배를 말한다. 다만, 군함, 국가가 소유하거나 운영하는 해군보조함 및 세관ㆍ경찰용 선박은 제외한다.', 14066);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9788, '2.  "운항"이란 항해, 정박(碇泊), 계류(繫留), 대기(待機) 등 해양에서의 선박의 모든 사용 상태를 말한다.', 14066);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9789, '3.  "대한민국 선박"이란 「선박법」 및 「어선법」 등 관계 법령에 따라 대한민국에 등록된 선박을 말한다.', 14066);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9790, '4.  "외국선박"이란 외국에 등록된 선박을 말한다.', 14066);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9791, '5.  "해상구조물"이란 자원의 탐사ㆍ개발, 해양과학조사, 그 밖의 경제적 목적 등을 위하여 「해양법에 관한 국제연합 협약」에 따른 대륙붕에 항상 고착된 인공섬, 시설 또는 구조물을 말한다.', 14066);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9792, '6.  "외국인"이란 대한민국의 국적을 가지지 아니한 사람을 말한다.', 14066);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9793, '1.  대한민국 영역 밖에서 대한민국 선박에 대하여 제5조부터 제13조까지의 죄를 범한 외국인', 14067);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9794, '2.  대한민국 영역 밖에서 대한민국 대륙붕에 있는 해상구조물에 대하여 또는 그 해상구조물에서 제5조부터 제13조까지의 죄를 범한 외국인', 14067);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9795, '3.  대한민국 영역 밖에서 제5조부터 제13조까지의 죄를 범하고 대한민국 영역 안에 있는 외국인', 14067);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9796, '1.  "밀항"(密航)이란 관계 기관에서 발행한 여권, 선원수첩, 그 밖에 출국에 필요한 유효한 증명 없이 대한민국 외의 지역으로 도항하거나 국경을 넘는 것을 말한다.', 14085);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9797, '2.  "이선ㆍ이기"(離船ㆍ離機)란 대한민국 외의 지역에서 승선한 선박이나 탑승한 항공기로부터 무단이탈하거나 선장 또는 기장, 그 밖의 책임자가 지정한 시간 내에 귀환하지 아니하는 것을 말한다.', 14085);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9798, '1.  "디엔에이"란 생물의 생명현상에 대한 정보가 포함된 화학물질인 디옥시리보 핵산(Deoxyribonucleic acid, DNA)을 말한다.', 14097);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9799, '2.  "디엔에이감식시료"란 사람의 혈액, 타액, 모발, 구강점막 등 디엔에이감식의 대상이 되는 것을 말한다.', 14097);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9800, '3.  "디엔에이감식"이란 개인 식별을 목적으로 디엔에이 중 유전정보가 포함되어 있지 아니한 특정 염기서열 부분을 검사ㆍ분석하여 디엔에이신원확인정보를 취득하는 것을 말한다.', 14097);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9801, '4.  "디엔에이신원확인정보"란 개인 식별을 목적으로 디엔에이감식을 통하여 취득한 정보로서 일련의 숫자 또는 부호의 조합으로 표기된 것을 말한다.', 14097);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9802, '5.  "디엔에이신원확인정보데이터베이스"(이하 "데이터베이스"라 한다)란 이 법에 따라 취득한 디엔에이신원확인정보를 컴퓨터 등 저장매체에 체계적으로 수록한 집합체로서 개별적으로 그 정보에 접근하거나 검색할 수 있도록 한 것을 말한다.', 14097);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9803, '1.  「형법」 제2편제13장 방화와 실화의 죄 중 제164조, 제165조, 제166조제1항, 제167조제1항 및 제174조(제164조제1항, 제165조, 제166조제1항의 미수범만 해당한다)의 죄', 14103);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9804, '2.  「형법」 제2편제24장 살인의 죄 중 제250조, 제253조 및 제254조(제251조, 제252조의 미수범은 제외한다)의 죄', 14103);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9805, '2의2.  「형법」 제2편제25장 상해와 폭행의 죄 중 제258조의2, 제261조, 제264조의 죄', 14103);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9806, '2의3.  「형법」 제2편제29장 체포와 감금의 죄 중 제278조, 제279조, 제280조(제278조, 제279조의 미수범에 한정한다)의 죄', 14103);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9807, '2의4.  「형법」 제2편제30장 협박의 죄 중 제284조, 제285조, 제286조(제284조, 제285조의 미수범에 한정한다)의 죄', 14103);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9808, '3.  「형법」 제2편제31장 약취(略取), 유인(誘引) 및 인신매매의 죄 중 제287조, 제288조(결혼을 목적으로 제288조제1항의 죄를 범한 경우는 제외한다), 제289조(결혼을 목적으로 제289조제2항의 죄를 범한 경우는 제외한다), 제290조, 제291조, 제292조(결혼을 목적으로 한 제288조제1항 또는 결혼을 목적으로 한 제289조제2항의 죄로 약취, 유인 또는 매매된 사람을 수수 또는 은닉한 경우 및 결혼을 목적으로 한 제288조제1항 또는 결혼을 목적으로 한 제289조제2항의 죄를 범할 목적으로 사람을 모집, 운송 또는 전달한 경우는 제외한다) 및 제294조(결혼을 목적으로 제288조제1항 또는 결혼을 목적으로 제289조제2항의 죄를 범한 경우의 미수범, 결혼을 목적으로 한 제288조제1항 또는 결혼을 목적으로 한 제289조제2항의 죄로 약취, 유인 또는 매매된 사람을 수수 또는 은닉한 죄의 미수범은 제외한다)의 죄', 14103);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9809, '4.  「형법」 제2편제32장 강간과 추행의 죄 중 제297조, 제297조의2, 제298조부터 제301조까지, 제301조의2, 제302조, 제303조 및 제305조의 죄', 14103);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9810, '4의2.  「형법」 제2편제36장 주거침입의 죄 중 제320조, 제322조(제320조의 미수범에 한정한다)의 죄', 14103);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9811, '4의3.  「형법」 제2편제37장 권리행사를 방해하는 죄 중 제324조제2항, 제324조의5(제324조제2항의 미수범에 한정한다)의 죄', 14103);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9812, '5.  「형법」 제2편제38장 절도와 강도의 죄 중 제330조, 제331조, 제332조(제331조의2의 상습범은 제외한다)부터 제342조(제329조, 제331조의2의 미수범은 제외한다)까지의 죄', 14103);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9813, '5의2.  「형법」 제2편제39장 사기와 공갈의 죄 중 제350조의2, 제351조(제350조, 제350조의2의 상습범에 한정한다), 제352조(제350조, 제350조의2의 미수범에 한정한다)의 죄', 14103);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9814, '5의3.  「형법」 제2편제42장 손괴의 죄 중 제369조제1항, 제371조(제369조제1항의 미수범에 한정한다)의 죄', 14103);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9815, '6.  「폭력행위 등 처벌에 관한 법률」 제2조(같은 조 제2항의 경우는 제외한다), 제3조부터 제5조까지 및 제6조(제2조제2항의 미수범은 제외한다)의 죄', 14103);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9816, '7.  「특정범죄가중처벌 등에 관한 법률」 제5조의2제1항부터 제6항까지, 제5조의4제2항 및 제5항, 제5조의5, 제5조의8, 제5조의9 및 제11조의 죄', 14103);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9817, '8.  「성폭력범죄의 처벌 등에 관한 특례법」 제3조부터 제11조까지 및 제15조(제13조의 미수범은 제외한다)의 죄', 14103);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9818, '9.  「마약류관리에 관한 법률」 제58조부터 제61조까지의 죄', 14103);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9819, '10.  「아동ㆍ청소년의 성보호에 관한 법률」 제7조, 제8조 및 제12조부터 제14조까지(제14조제3항의 경우는 제외한다)의 죄', 14103);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9820, '11.  「군형법」 제53조제1항, 제59조제1항, 제66조, 제67조 및 제82조부터 제85조까지의 죄', 14103);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9821, '1.  범죄현장에서 발견된 것', 14105);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9822, '2.  범죄의 피해자 신체의 내ㆍ외부에서 발견된 것', 14105);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9823, '3.  범죄의 피해자가 피해 당시 착용하거나 소지하고 있던 물건에서 발견된 것', 14105);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9824, '4.  범죄의 실행과 관련된 사람의 신체나 물건의 내ㆍ외부 또는 범죄의 실행과 관련한 장소에서 발견된 것', 14105);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9825, '1.  제5조부터 제8조까지 및 제9조에 따라 채취된 디엔에이감식시료의 감식 및 데이터베이스에의 디엔에이신원확인정보의 수록', 14122);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9826, '2.  데이터베이스의 관리', 14122);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9827, '1.  데이터베이스에 새로운 디엔에이신원확인정보를 수록하는 경우', 14124);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9828, '2.  검사 또는 사법경찰관이 범죄수사 또는 변사자 신원확인을 위하여 요청하는 경우', 14124);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9829, '3.  법원(군사법원을 포함한다. 이하 같다)이 형사재판에서 사실조회를 하는 경우', 14124);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9830, '4.  데이터베이스 상호간의 대조를 위하여 필요한 경우', 14124);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9831, '1.  검사의 혐의없음, 죄가안됨 또는 공소권없음의 처분이 있거나, 제5조제1항 각 호의 범죄로 구속된 피의자의 죄명이 수사 또는 재판 중에 같은 항 각 호 외의 죄명으로 변경되는 경우. 다만, 죄가안됨 처분을 하면서 「치료감호법」 제7조제1호에 따라 치료감호의 독립청구를 하는 경우는 제외한다.', 14130);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9832, '2.  법원의 무죄, 면소, 공소기각 판결 또는 공소기각 결정이 확정된 경우. 다만, 무죄 판결을 하면서 치료감호를 선고하는 경우는 제외한다.', 14130);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9833, '3.  법원의 「치료감호법」 제7조제1호에 따른 치료감호의 독립청구에 대한 청구기각 판결이 확정된 경우', 14130);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9834, '1.  디엔에이감식시료의 수집, 운반, 보관 및 폐기에 관한 사항', 14136);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9835, '2.  디엔에이감식의 방법, 절차 및 감식기술의 표준화에 관한 사항', 14136);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9836, '3.  디엔에이신원확인정보의 표기, 데이터베이스 수록 및 삭제에 관한 사항', 14136);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9837, '4.  그 밖에 대통령령으로 정하는 사항', 14136);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9838, '1.  5급 이상 공무원(고위공무원단에 속하는 일반직공무원을 포함한다) 또는 이에 상당하는 공공기관의 직에 있거나 있었던 사람으로서 디엔에이와 관련한 업무에 종사한 경험이 있는 사람', 14138);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9839, '2.  대학이나 공인된 연구기관에서 부교수급 이상 또는 이에 상당하는 직에 있거나 있었던 사람으로서 생명과학 또는 의학 분야에서 전문지식과 연구경험이 풍부한 사람', 14138);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9840, '3.  그 밖에 윤리학계, 사회과학계, 법조계 또는 언론계 등 분야에서 학식과 경험이 풍부한 사람', 14138);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9841, '1.  거짓이나 그 밖의 부정한 방법으로 디엔에이신원확인정보를 열람하거나 제공받은 사람', 14146);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9842, '2.  제11조에 따라 회보된 디엔에이신원확인정보를 업무목적 외에 사용하거나 타인에게 제공 또는 누설한 사람', 14146);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9843, '1.  "인적사항등"이란 「디엔에이신원확인정보의 이용 및 보호에 관한 법률」(이하 "법"이라 한다) 제5조 또는 제6조에 따른 디엔에이감식시료 채취대상자의 성명, 주민등록번호(외국인의 경우에는 외국인등록번호, 여권번호 등을 말한다) 등 인적사항 및 디엔에이감식시료의 채취 또는 그 원인이 된 사건과 관련된 정보를 말한다.', 14148);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9844, '2.  "식별코드"란 개인 식별을 위하여 법 제5조 또는 제6조에 따른 디엔에이감식시료 채취대상자의 인적사항을 대신하여 디엔에이신원확인정보데이터베이스(이하 "데이터베이스"라 한다)에 수록되는 것으로 숫자, 문자 또는 기호 등을 조합하여 생성된 분류체계를 말한다.', 14148);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9845, '1.  인적사항등 및 식별코드의 관리업무', 14149);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9846, '2.  디엔에이감식 및 디엔에이신원확인정보의 검색ㆍ회보와 관련된 인적사항등의 확인업무', 14149);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9847, '3.  디엔에이감식시료의 중복 채취 및 채취 누락 확인업무', 14149);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9848, '4.  디엔에이신원확인정보의 삭제사유 확인업무', 14149);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9849, '1.  채취 일시와 장소 및 방법, 채취한 디엔에이감식시료의 종류 등을 적은 서류', 14156);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9850, '2.  법 제8조제3항에 따른 동의서(이하 "디엔에이감식시료채취동의서"라 한다)', 14156);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9851, '1.  채취 일시와 장소 및 방법, 채취한 디엔에이감식시료의 종류 등을 적은 서류', 14159);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9852, '2.  디엔에이감식시료채취영장', 14159);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9853, '1.  구강점막에서의 채취', 14160);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9854, '2.  모근을 포함한 모발의 채취', 14160);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9855, '3.  그 밖에 디엔에이를 채취할 수 있는 신체부분, 분비물, 체액의 채취(제1호 또는 제2호에 따른 디엔에이감식시료의 채취가 불가능하거나 현저히 곤란한 경우에 한정한다)', 14160);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9856, '1.  채취 일시와 장소 및 방법, 채취한 디엔에이감식시료의 종류 등을 적은 서류', 14162);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9857, '2.  디엔에이감식시료채취영장 또는 디엔에이감식시료채취동의서', 14162);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9858, '1.  검사 또는 사법경찰관(군사법경찰관은 제외한다)이 법 제7조에 따라 디엔에이감식시료를 채취한 경우: 검찰 디엔에이신원확인정보담당자 또는 경찰 디엔에이신원확인정보담당자', 14165);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9859, '2.  군사법경찰관이 법 제7조에 따라 디엔에이감식시료를 채취한 경우: 법 제10조 및 이 영 제12조제2항제2호에 따라 법 제7조에 따라 채취한 디엔에이감식시료의 감식업무를 위탁받은 국방부 조사본부장(이하 "군 디엔에이감식기관"이라 한다)', 14165);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9860, '1.  법 제10조제1항 각 호의 업무(제2호의 업무는 제외한다): 국립과학수사연구원에 위탁', 14168);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9861, '2.  군사법경찰관이 법 제7조에 따라 채취한 디엔에이감식시료의 감식업무: 국방부 조사본부장에게 위탁', 14168);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9862, '1.  법 제5조 또는 제6조에 따른 디엔에이감식시료 채취대상자로부터 채취한 디엔에이감식시료를 감식하여 취득한 디엔에이신원확인정보를 법 제7조에 따라 채취한 디엔에이감식시료를 감식하여 취득한 디엔에이신원확인정보가 수록된 데이터베이스에서 검색ㆍ대조한 결과 디엔에이신원확인정보가 일치하는 사실을 발견한 경우: 법 제5조 또는 제6조에 따른 디엔에이감식시료 채취대상자로부터 채취한 디엔에이감식시료를 감식한 디엔에이신원확인정보담당자', 14174);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9863, '2.  법 제7조에 따라 채취한 디엔에이감식시료를 감식하여 취득한 디엔에이신원확인정보를 법 제5조 및 제6조에 따른 디엔에이감식시료 채취대상자로부터 채취한 디엔에이감식시료를 감식한 디엔에이신원확인정보를 수록한 데이터베이스에서 검색ㆍ대조한 결과 디엔에이신원확인정보가 일치하는 사실을 발견한 경우: 법 제5조 또는 제6조에 따른 디엔에이감식시료 채취대상자로부터 채취한 디엔에이감식시료를 감식한 디엔에이신원확인정보담당자', 14174);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9864, '3.  법 제7조에 따라 채취한 디엔에이감식시료를 감식하여 취득한 디엔에이신원확인정보를 법 제7조에 따라 채취한 디엔에이감식시료를 감식하여 취득한 디엔에이신원확인정보가 수록된 데이터베이스에서 검색ㆍ대조한 경우: 해당 데이터베이스를 관리하는 디엔에이신원확인정보담당자', 14174);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9865, '4.  그 밖의 경우: 디엔에이신원확인정보를 검색ㆍ대조한 디엔에이신원확인정보담당자', 14174);
