INSERT INTO balaw.ho (id, content, hang_id) VALUES (9867, '2.  법 제11조제1항제2호 및 제3호에 따른 디엔에이신원확인정보 검색결과의 회보의 경우: 검색을 요청한 검사, 사법경찰관 또는 법원(군사법원을 포함한다. 이하 같다)', 14175);
