INSERT INTO balaw.ho (id, content, hang_id) VALUES (9938, '2.  「군사기밀보호법」에 따른 군사기밀에 속하는 것(비밀도서, 비밀지도 및 비밀연구기재를 포함한다)', 14345);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9939, '3.  제1호에 따른 군용물을 운용하는 데 필요한 보조장비(탑재 또는 장착되는 장비를 포함한다), 수리부속품, 구성품(構成品), 부분품 및 원료로서 군용 표지(標識)가 있는 것', 14345);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9940, '4.  제1호에 따른 군용물의 검사, 시험 및 정비용 장비로서 군용에 공하기 위하여 특수제작된 것', 14345);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9941, '1.  「형법」 제2편제38장 중 제329조부터 제331조까지, 제331조의2, 제332조, 제333조, 제335조(제333조의 예에 따르는 경우에 한정한다. 이하 이 호에서 같다), 제336조, 제342조(제329조부터 제331조까지, 제331조의2, 제332조, 제333조, 제335조 및 제336조의 미수범에 한정한다) 및 제343조의 죄', 14346);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9942, '2.  「형법」 제2편제39장 중 제347조, 제350조, 제350조의2, 제351조(제347조, 제350조 및 제350조의2의 상습범에 한정한다. 이하 이 호에서 같다) 및 제352조(제347조, 제350조, 제350조의2 및 제351조의 미수범에 한정한다)의 죄', 14346);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9943, '3.  「형법」 제2편제40장 중 제355조제1항, 제356조(업무상 임무에 위배하여 제355조제1항의 죄를 범한 경우에 한정한다. 이하 이 호에서 같다), 제357조, 제359조(제355조제1항, 제356조 및 제357조의 미수범에 한정한다) 및 제360조의 죄', 14346);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9944, '4.  「형법」 제2편제41장 중 제362조, 제363조제1항 및 제364조의 죄', 14346);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9945, '1.  집단적 또는 상습적으로 범행한 경우', 14347);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9946, '2.  물품의 가액(價額)이 1천만원 이상인 경우', 14347);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9947, '3.  1천킬로그램 이상의 물품 또는 2천리터 이상의 유류인 경우', 14347);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9948, '1.  식품, 식품첨가물 또는 건강기능식품이 인체에 현저히 유해한 경우: 무기 또는 5년 이상의 징역에 처한다.', 14357);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9949, '2.  식품, 식품첨가물 또는 건강기능식품의 가액(價額)이 소매가격으로 연간 5천만원 이상인 경우: 무기 또는 3년 이상의 징역에 처한다.', 14357);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9950, '3.  제1호의 죄를 범하여 사람을 사상(死傷)에 이르게 한 경우: 사형, 무기 또는 5년 이상의 징역에 처한다.', 14357);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9951, '1.  의약품이 인체에 현저히 유해한 경우 또는 「약사법」 제53조에 따른 국가출하승인의약품 중 대통령령으로 정하는 의약품으로서 효능 또는 함량이 현저히 부족한 경우: 무기 또는 5년 이상의 징역에 처한다.', 14359);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9952, '2.  의약품의 가액이 소매가격으로 연간 1천만원 이상인 경우: 무기 또는 3년 이상의 징역에 처한다.', 14359);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9953, '3.  제1호의 죄를 범하여 사람을 사상에 이르게 한 경우: 사형, 무기 또는 5년 이상의 징역에 처한다.', 14359);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9954, '1.  유해화학물질의 잔류 독성이 인체에 현저히 유해한 경우: 무기 또는 5년 이상의 징역에 처한다.', 14361);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9955, '2.  유해화학물질의 가액이 소매가격으로 연간 100만원 이상인 경우: 무기 또는 3년 이상의 징역에 처한다.', 14361);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9956, '1.  의사가 아닌 사람이 의료행위를 업(業)으로 한 행위', 14363);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9957, '2.  치과의사가 아닌 사람이 치과의료행위를 업으로 한 행위', 14363);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9958, '3.  한의사가 아닌 사람이 한방의료행위를 업으로 한 행위', 14363);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9959, '1.  항생물질과 그 제제중 내복제 및 주사제', 14368);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9960, '2.  생물학적 제제중 내복제 및 주사제', 14368);
