INSERT INTO balaw.ho (id, content, hang_id) VALUES (9972, '2.  영국약전', 14374);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9973, '3.  독일약전', 14374);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9974, '4.  일본약국방', 14374);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9975, '5.  미국국민의약품집', 14374);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9976, '1.  통보자 또는 검거자에 대한 범죄인지관서장의 증명서', 14377);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9977, '2.  확정판결의 판결문등본 또는 검사의 기소유예 처분증명서', 14377);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9978, '1.  "전자소송시스템"이란 법 제3조 각 호의 어느 하나에 해당하는 법률에 따른 형사사법절차에 필요한 전자문서의 작성, 제출, 송달, 관리 등에 이용하기 위하여 법 제6조제1항에 따라 법원행정처가 설치ㆍ운영하는 전산정보처리시스템을 말한다.', 14378);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9979, '2.  "전자소송포털"이란 이 규칙에서 정한 바에 따라 전자문서를 이용하여 형사사법절차를 진행할 수 있도록 전자소송시스템에 의하여 구축된 인터넷 활용공간을 말한다.', 14378);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9980, '3.  "전자기록"이란 전산정보처리시스템에 전자적으로 기록된 전자문서와 전자적인 형태로 변환하여 등재된 전자화문서를 사건별로 모아둔 것을 말한다.', 14378);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9981, '4.  "정보통신망"이란 「전기통신기본법」 제2조제2호에 의한 전기통신설비를 이용하거나 전기통신설비와 컴퓨터 및 컴퓨터의 이용기술을 활용하여 정보를 수집ㆍ가공ㆍ저장ㆍ검색ㆍ송신 또는 수신하는 정보통신체제를 말한다.', 14378);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9982, '1.  피의자, 피고인: 소년보호사건에서는 "소년"으로, 가정보호사건, 아동보호사건, 성매매관련보호사건에서는 "행위자"로 본다.', 14379);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9983, '2.  변호인: 소년보호사건, 가정보호사건, 아동보호사건, 성매매관련보호사건에서는 "보조인"으로 본다.', 14379);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9984, '3.  피해자: 아동보호사건에서는 "피해아동"으로 본다.', 14379);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9985, '1.  피고인이나 피의자, 피해자의 법정대리인(피해자가 사망한 경우 그 배우자, 직계친족, 형제자매를 포함한다)', 14380);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9986, '2.  피의자 또는 피고인이 법인인 때에는 그 대표자', 14380);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9987, '3.  특별대리인', 14380);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9988, '4.  「형사소송법」 제29조의 보조인', 14380);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9989, '5.  피해자의 변호사 등 대리인, 배상신청인, 배상신청대리인', 14380);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9990, '6.  증인', 14380);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9991, '7.  통역인, 번역인', 14380);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9992, '8.  감정인, 법원으로부터 감정을 촉탁 받은 기관', 14380);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9993, '9.  전문심리위원', 14380);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9994, '10.  법원으로부터 필요한 사항의 보고 또는 보관서류의 송부를 요청받은 자', 14380);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9995, '11.  소년보호사건, 가정보호사건, 아동보호사건, 성매매관련보호사건의 절차관계인으로서 ‘별표 1 보호사건 절차관계인’에서 정한 자(다음부터 "보호사건 절차관계인"이라 한다)', 14380);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9996, '12.  전자문서를 제출할 정당한 이해관계를 소명하여 재판장의 허가를 받은 자', 14380);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9997, '13.  그 밖에 법 제3조 각 호의 법률에 따른 절차에 관하여 서면을 제출할 정당한 권한 내지 의무가 있는 자', 14380);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9998, '1.  개인회원', 14385);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (9999, '2.  법인회원', 14385);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10000, '3.  변호사회원', 14385);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10001, '4.  법무사회원', 14385);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10002, '5.  제3조제11호에 따른 보호사건 절차관계인회원', 14385);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10003, '1.  사용자등록이 소송 지연 등 본래의 용도와 다른 목적으로 이용되는 경우', 14390);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10004, '2.  등록사용자에게 의사능력이 없는 경우', 14390);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10005, '3.  그 밖에 위 각 호의 사유에 준하는 경우', 14390);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10006, '1.  전자소송시스템 또는 정보통신망에 장애가 발생하여 그 장애가 언제 제거될 수 있는지 알 수 없거나, 장애가 제거될 시점에 전자문서를 작성하면 절차가 현저히 지연될 염려가 있는 경우의 재판서, 조서, 그 밖에 이에 준하는 서류', 14400);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10007, '2.  공판기일에서 피고인을 구속하는 경우 등 법원이 영장 발부 및 집행절차의 원활한 진행을 위하여 전자문서로 작성하지 아니할 필요가 있다고 인정하는 경우의 영장 및 이에 준하는 서류와 그 집행 등을 위하여 필요한 관계 서류', 14400);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10008, '3.  그 밖에 법원이 소송절차의 원활한 진행을 위하여 전자문서로 작성하지 아니할 필요가 있다고 인정하는 경우의 재판서, 조서 등 소송서류', 14400);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10009, '1.  전자소송시스템 또는 정보통신망에 장애가 있는 경우', 14402);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10010, '2.  서적을 제출하는 경우(이 경우 서적의 내용 가운데 중요한 부분을 전자문서로 변환하여 그 서적과 함께 제출하여야 한다)', 14402);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10011, '3.  기술적으로 서류를 전자문서로 변환하기 어려운 경우', 14402);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10012, '4.  사생활 보호 또는 그 밖에 이에 준하는 사유로 재판장등이 필요하다고 인정하여 허가한 경우', 14402);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10013, '1.  해당 전자문서에 공동명의자 전원이 전자서명(제8조제1항에 따라 서명자의 실지명의를 확인할 수 있는 것으로서 법원행정처장이 지정ㆍ공고하는 인증서를 말한다)을 하여 제출하는 방법', 14406);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10014, '2.  해당 전자문서를 최초로 제출하는 등록사용자가 그 전자문서 속에 다른 공동명의자 전원의 전자서명(제8조제1항에 따른 인증서에 의한 것임을 요하지 아니한다)을 포함시켜 제출하는 방법', 14406);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10015, '3.  해당 전자문서를 최초로 제출하는 등록사용자가 다른 공동명의자 전원의 서명 또는 날인이 이루어진 확인서를 전자문서로 변환하여 함께 제출하는 방법', 14406);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10016, '1.  제8조에 의한 위임인 본인의 전자서명 정보를 함께 전송하는 방법', 14407);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10017, '2.  제2항제2호 또는 제3호의 방법', 14407);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10018, '1.  해당 전자문서에 등록사용자의 전자서명(서명자의 실지명의를 확인할 수 있는 것으로서 법원행정처장이 지정ㆍ공고하는 인증서를 말한다)을 하여 제출하는 방법', 14410);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10019, '2.  등록사용자의 위임장과 제2항제3호에 따른 확인서를 전자문서로 변환하여 함께 제출하는 방법', 14410);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10020, '1.  전자문서별로 별도의 파일을 제출하고, 이를 합하여 하나의 파일로 제출하지 아니할 것', 14413);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10021, '2.  전자문서를 증거로 제출하고자 하는 경우에는 법원행정처장이 정하는 방법에 따라 증거임을 명시할 것', 14413);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10022, '3.  부득이한 사정이 없는 한 문자정보의 검색 및 추출이 가능한 파일로 제출할 것(단, 전자화문서는 그러하지 아니하다)', 14413);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10023, '1.  피해자, 증인 등 사건관계인의 생명 또는 신체의 안전을 현저히 해칠 우려가 있는 경우', 14414);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10024, '2.  피해자, 증인 등 사건관계인의 명예나 사생활의 비밀 또는 생활의 평온, 영업비밀(「부정경쟁방지 및 영업비밀보호에 관한 법률」 제2조제2호의 영업비밀을 말한다)을 현저히 해칠 우려가 있는 경우', 14414);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10025, '1.  사건의 표시, 정보저장매체등을 제출하는 자의 이름과 연락처, 정보저장매체등에 담긴 전자문서의 표시, 작성자의 이름과 작성한 날짜, 작성자와 제출자와의 관계, 법원의 표시', 14420);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10026, '2.  전자문서를 정보저장매체등에 담아 제출하여야 하는 사유', 14420);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10027, '1.  제10조제1항제2호부터 제4호까지 각 호의 어느 하나에 해당하는 경우', 14425);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10028, '2.  법 제5조제1항 및 이 규칙 제3조에서 규정한 자 이외의 자로부터 동일하거나 유사한 내용의 서류가 반복하여 다량으로 제출하는 경우로서 재판장등이 별도로 관리할 필요가 있다고 인정하는 경우', 14425);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10029, '1.  전자화프로그램 등 시스템 정보', 14429);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10030, '2.  전자화문서 생성일시', 14429);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10031, '3.  파일 형식, 문서 장수, 문서 크기 등 페이지 정보', 14429);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10032, '4.  무결성 검증정보', 14429);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10033, '1.  전자문서의 명칭', 14433);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10034, '2.  전자문서가 전자소송시스템에 기록된 일시', 14433);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10035, '3.  전자문서의 고유번호 및 해시값(파일의 고유값으로서 일종의 전자지문을 말한다)', 14433);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10036, '1.  전산등재 과정에서의 잘못 등으로 효력이 없음이 분명한 경우: 폐기', 14442);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10037, '2.  잘못된 계산이나 기재 등이 있음이 분명한 때: 정정', 14442);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10038, '1.  형사사법절차의 개별 사건에 관하여 전자소송 동의를 한 등록사용자', 14453);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10039, '2.  피고인, 대리인, 대표자, 변호인 또는 보조인이 「형사소송법」 제60조에 의하여 송달영수인으로 신고한 등록사용자', 14453);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10040, '3.  1년의 범위에서 일정한 기간을 정하여 피의자, 피고인, 변호인 또는 제3조 각 호의 자가 될 것을 예정하여 전자소송 동의를 한 등록사용자', 14453);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10041, '1.  법 제14조제1항제1호 및 제2호: 전자문서를 전자소송시스템에 등재하고, 송달 또는 통지를 받을 형사사법업무 처리기관의 전산정보처리시스템을 통해 통지하는 방법', 14457);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10042, '2.  법 제14조제1항제3호: 전자문서를 전자소송시스템에 등재하고, 송달 또는 통지를 받을 등록사용자가 전자소송시스템에 입력한 전자우편 및 문자전송서비스를 이용하여 보내는 방법(다만, 문자전송서비스는 등록사용자의 요청에 따라 이용하지 아니할 수 있다)', 14457);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10043, '1.  피고인이 사물의 변별 또는 의사의 결정을 할 능력이 없는 상태에 있는 때', 14459);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10044, '2.  피고인이 중대한 질병, 부상 등으로 전자소송시스템에 접속하기 어려운 때', 14459);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10045, '1.  전자소송시스템의 장애가 발생한 경우로서 그 장애가 언제 제거될 수 있는지 알 수 없거나, 장애가 제거될 시점에 전자적 송달 또는 통지를 하게 되면 소송이 현저히 지연되거나 피고인 등의 권리 행사에 불이익을 초래할 염려가 있는 경우', 14463);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10046, '2.  송달받을 자가 책임질 수 없는 사유로 전자소송시스템에 등재된 전자문서를 확인할 수 없다는 점을 소명하여 출력서면의 송달을 신청한 경우', 14463);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10047, '3.  그 밖에 재판장등이 출력서면의 송달이 필요하다고 인정하는 경우', 14463);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10048, '1.  출력할 서면의 분량이 상당히 많은 경우', 14464);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10049, '2.  송달받을 상대방의 수가 상당히 많은 경우', 14464);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10050, '3.  당해 전자문서에 표시된 색상이 나타나도록 서면을 출력할 필요가 있는 경우', 14464);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10051, '4.  그 밖에 위 각 호의 사유에 준하는 경우', 14464);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10052, '1.  출력자 정보', 14465);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10053, '2.  출력일시', 14465);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10054, '3.  출력프로그램 등 시스템 정보', 14465);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10055, '1.  열람ㆍ등사ㆍ복사하는 자의 정보', 14469);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10056, '2.  열람ㆍ등사ㆍ복사 일시', 14469);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10057, '3.  발급번호', 14469);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10058, '1.  법원에서 제공되지 아니하는 컴퓨터 등을 이용하여 열람, 출력 또는 복제하는 경우', 14472);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10059, '2.  법원에서 제공되는 컴퓨터 등을 이용하여 열람하는 경우', 14472);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10060, '1.  전자문서를 전자소송시스템에 등재하여 제출하는 방법', 14477);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10061, '2.  전자문서가 전자소송시스템에 등재되어 있는 경우에는 그러한 취지를 진술하는 방법', 14477);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10062, '3.  전자문서가 정보저장매체등에 담긴 경우에는 이를 제출하는 방법', 14477);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10063, '1.  전자문서에 대한 증거조사를 신청하는 자가 전자소송 동의를 하지 아니한 경우', 14478);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10064, '2.  제10조제1항제1호의 사유가 있는 경우', 14478);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10065, '3.  제10조제1항제4호에 해당하는 서류가 전자문서로 작성되어 있는 경우', 14478);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10066, '1.  전자문서가 문자, 그 밖의 기호, 도면, 사진 등에 관한 정보(다음부터 "문자등 정보"라고 한다)인 경우에는 전자문서의 명칭과 작성자 및 작성일(전자문서로 변환하여 제출된 경우에는 원본의 작성자와 작성일을 말한다)', 14479);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10067, '2.  전자문서가 음성ㆍ음향이나 영상정보(다음부터 "음성ㆍ영상등 정보"라고 한다)인 경우에는 음성이나 영상이 녹음 또는 녹화된 자, 녹음 또는 녹화를 한 자 및 그 일시ㆍ장소, 주요내용과 용량, 입증할 사항과 사이의 적합한 관련성', 14479);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10068, '1.  증거로 제출된 전자문서를 취득한 시기 및 방법 등 증거취득의 경위에 관한 정보', 14480);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10069, '2.  압수수색영장 등 증거로 제출된 전자문서의 취득의 적법성을 증명하는 서류', 14480);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10070, '1.  「형사소송법」 제73조, 제200조의2, 제201조에 따른 구속영장, 체포영장', 14494);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10071, '2.  「형사소송법」 제172조 및 제221조의3에 따른 감정유치장', 14494);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10072, '3.  「형사소송법」 제173조 및 제221조의4에 따른 허가장', 14494);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10073, '4.  「형사소송법」 제473조에 따른 형집행장', 14494);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10074, '5.  「보호관찰 등에 관한 법률」 제39조, 제42조에 따른 구인장, 유치허가장', 14494);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10075, '6.  「소년법」 제13조제2항 및 제14조, 「가정폭력범죄의 처벌 등에 관한 특례법」 제24조제2항 및 제25조에 따른 동행영장', 14494);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10076, '7.  「디엔에이신원확인정보의 이용 및 보호에 관한 법률」 제8조에 따른 디엔에이감식시료채취영장', 14494);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10077, '8.  「형사소송법」 제113조 및 제215조에 따른 압수ㆍ수색ㆍ검증영장', 14494);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10078, '9.  「금융실명거래 및 비밀보장에 관한 법률」 제4조에 따른 영장', 14494);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10079, '10.  「통신비밀보호법」 제6조 및 제8조에 따른 통신제한조치허가서', 14494);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10080, '11.  「통신비밀보호법」 제13조에 따른 통신사실 확인자료제공 요청 허가서', 14494);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10081, '12.  「통신비밀보호법」 제13조의2에 따른 통신사실확인자료제공 요청서', 14494);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10082, '13.  「전자장치 부착 등에 관한 법률」 제16조에 따른 수신자료 열람ㆍ조회 허가서', 14494);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10083, '1.  전자소송시스템 또는 「형사사법절차 전자화 촉진법」 제2조제6호의 형사사법포털에 사용자등록을 한 자', 14495);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10084, '2.  「전자서명법」 제2조제2호에 따른 전자서명(서명자의 실지명의를 확인할 수 있는 것을 말한다) 또는 「정보통신망 이용촉진 및 정보보호 등에 관한 법률」 제23조의3에 따른 본인확인기관이 제공하는 본인확인의 방법을 통해 그 신원이 확인된 자', 14495);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10085, '1.  「금융실명거래 및 비밀보장에 관한 법률」 제4조에 따른 영장(피집행자가 같은 법 제2조제1호가목부터 파목까지인 경우에 한한다)', 14496);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10086, '2.  「통신비밀보호법」 제6조 및 제8조에 따른 통신제한조치허가서', 14496);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10087, '3.  「통신비밀보호법」 제13조에 따른 통신사실 확인자료제공 요청 허가서(피집행자가 「전기통신사업법」 제5조제2항의 기간통신사업자인 경우에 한한다)', 14496);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10088, '1.  전자문서로 영장등을 발부하는 경우에 「형사소송규칙」 제96조의18에 따라 법원사무관등이 영장등에 기재하여야 하는 정보', 14500);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10089, '2.  전자문서로 발부된 영장등을 집행하는 때에 「형사소송규칙」 제49조에 따른 집행일시와 장소, 집행할 수 없었을 때에는 그 사유, 그 밖에 이에 준하는 것으로서 영장등에 기재하여야 하는 집행과 관련된 정보', 14500);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10090, '3.  그 밖에 전자문서로 발부되는 영장등의 고유번호 및 해시값을 유지하여 그 동일성과 무결성을 보존할 수 있도록 당해 영장등과 분리하여 작성할 필요성이 있는 정보', 14500);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10091, '1.  사형, 무기 또는 10년 이상의 징역이나 금고가 선고된 사건', 14518);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10092, '2.  「국민의 형사재판 참여에 관한 법률」에 따라 국민참여재판으로 진행된 사건', 14518);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10093, '3.  「고위공직자범죄수사처 설치 및 운영에 관한 법률」 제2조제3호 및 제4호에 따른 고위공직자범죄 및 관련범죄로 공소제기된 사건', 14518);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10094, '4.  「소송촉진 등에 관한 특례법」 제23조에 따라 유죄판결이 선고된 사건', 14518);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10095, '5.  법 제20조제1항제1호 및 제2호에서 정한 기간이 지나기 전에 재심 또는 상소권회복의 청구가 있는 사건', 14518);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10096, '6.  당해 사건기록 전부 또는 일부에 관하여 「형사소송법」 제272조제1항에 따른 송부 요구, 「민사소송법」 제294조 및 제352조에 따른 송부 촉탁이 있는 사건', 14518);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10097, '7.  그 밖에 국내외적으로 중대하거나 역사적 가치가 있는 사건, 관련 사건의 수사나 심리를 위하여 특별히 보존할 필요가 있는 사건으로서 「법원기록물 관리규칙」 제36조의 규정에 의한 법원기록보존소 기록물평가심의회의 심의를 거친 사건', 14518);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10098, '1.  "군수형자"란 「군사법원법」에 따라 징역형, 금고형 또는 구류형을 선고받아 그 형이 확정된 사람과 벌금이나 과료를 완납하지 아니하여 같은 법 제533조에 따라 노역장유치 명령을 받은 사람을 말한다.', 14520);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10099, '2.  "군미결수용자"란 「군사법원법」에 따라 형사피의자 또는 형사피고인으로서 체포되거나 구속영장의 집행을 받은 사람을 말한다.', 14520);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10100, '3.  "사형확정자"란 「군사법원법」에 따라 사형을 선고받아 그 형이 확정되었으나 형이 집행되지 아니한 사람을 말한다.', 14520);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10101, '4.  "군수용자"란 군수형자, 군미결수용자, 사형확정자, 그 밖에 법률과 적법한 절차에 따라 군교도소, 군교도소 지소(支所) 및 군미결수용실(이하 "군교정시설"이라 한다)에 수용된 사람을 말한다.', 14520);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10102, '5.  "소장"이란 군교도소장, 군교도소 지소의 장 및 군미결수용실이 설치된 부대의 장을 말한다.', 14520);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10103, '6.  "군교도관"이란 군교정시설에서 군수용자의 계호(戒護), 군교정시설의 운영 및 경비 등의 업무를 담당하는 장교, 준사관, 부사관 및 군무원을 말한다.', 14520);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10104, '1.  교도소(지소를 포함한다. 이하 같다): 군수형자', 14528);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10105, '2.  미결수용실: 군미결수용자', 14528);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10106, '1.  미결수용실의 수용 인원이 정원을 훨씬 초과하여 미결수용실의 정상적인 운영이 어려울 때', 14529);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10107, '2.  범죄의 증거 인멸을 방지하기 위하여 필요하거나 그 밖에 특별한 사정이 있을 때', 14529);
