INSERT INTO balaw.ho (id, content, hang_id) VALUES (10287, '2.  법 제19조에 따른 군미결수용실에 수용된 군미결수용자의 이송 승인', 14934);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10288, '3.  법 제102조 및 이 영 제125조제4항에 따른 군미결수용실에 수용된 군미결수용자의 청원에 대한 결정 등', 14934);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10289, '4.  법 제114조제2항에 따른 군미결수용실에 두는 교정위원의 위촉', 14934);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10290, '5.  제4조제3항에 따른 군미결수용실에 대한 외국인의 참관 승인', 14934);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10291, '6.  제108조제2항에 따른 군미결수용실에 대한 보호장비 사용 실태의 점검', 14934);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10292, '7.  그 밖에 법 제4조제2항에 따른 군미결수용실의 시설ㆍ인력 및 예산 등의 운영에 관한 업무 중 법 및 이 영에 따른 소장의 권한에 속하지 아니하는 업무', 14934);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10293, '1.  법 제19조에 따른 군교도소(법 제4조제2항에 따라 군교도소에 설치하는 군미결수용실을 포함한다. 이하 이 항에서 같다)에 수용된 군수용자의 이송 승인', 14935);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10294, '2.  법 제114조제2항에 따른 군교도소에 두는 교정위원의 위촉', 14935);
