INSERT INTO balaw.ho (id, content, hang_id) VALUES (10296, '4.  제108조제2항에 따른 군교도소에 대한 보호장비 사용 실태의 점검', 14935);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10297, '5.  그 밖에 법 제4조제1항 및 제2항에 따른 군교도소의 시설ㆍ인력 및 예산 등의 운영에 관한 업무 중 법 및 이 영에 따른 소장의 권한에 속하지 아니하는 업무', 14935);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10298, '1.  "군교정시설"이란 군교도소, 군교도소 지소 및 군미결수용실을 말한다.', 14936);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10299, '2.  "자비구매물품"이란 「군에서의 형의 집행 및 군수용자의 처우에 관한 법률」(이하 "법"이라 한다) 제24조에 따라 군수용자가 소장의 허가를 받아 자신의 비용으로 구매할 수 있는 물품을 말한다.', 14936);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10300, '3.  "군교정시설의 보관범위"란 법 제25조에 따라 군수용자 1명이 군교정시설에 영치하여 보관할 수 있는 물품의 수량으로서 국방부장관이 정하는 범위를 말한다.', 14936);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10301, '4.  "군수용자의 소지범위"란 법 제26조에 따라 군수용자 1명이 군교정시설 안에서 소지하여 사용할 수 있는 물품의 수량으로서 국방부장관이 정하는 범위를 말한다.', 14936);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10302, '5.  "교부금품"이란 법 제27조에 따라 군수용자 외의 사람이 소장의 허가를 받아 군수용자에게 교부할 수 있는 금품을 말한다.', 14936);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10303, '6.  "처우등급"이란 「군에서의 형의 집행 및 군수용자의 처우에 관한 법률 시행령」(이하 "영"이라 한다) 제77조제2항에 따라 군수형자의 교정성적에 따른 처우의 수준과 내용을 구별하는 기준을 말한다.', 14936);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10304, '7.  "자치생활"이란 수형생활 중 일정한 범위에서 군교도관이나 교도병의 통제 없이 자율적으로 생활하는 것을 말한다.', 14936);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10305, '8.  "교정참여인사"란 법 제52조에 따라 군수형자에 대한 상담, 심리치료 또는 생활지도 등을 하는 외부전문가와 법 제114조제2항에 따라 위촉한 교정위원을 말한다.', 14936);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10306, '9.  "외부통근자"란 법 제58조에 따라 외부기업체 또는 군교정시설 안에 설치된 외부기업체의 작업장에 통근하며 작업하는 군수형자를 말한다.', 14936);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10307, '10.  "교정장비"란 군교정시설의 안[군교도관이 군교정시설의 밖에서 군수용자를 계호(戒護)하고 있는 경우 그 장소를 포함한다]에서 사람의 생명과 신체의 보호, 도주의 방지 및 군교정시설의 안전과 질서유지를 위하여 군교도관 또는 교도병이 사용하는 법 제81조에 따른 전자장비, 법 제85조의 보호장비, 법 제87조제4항의 보안장비 및 법 제88조에 따른 무기를 말한다.', 14936);
