INSERT INTO balaw.ho (id, content, hang_id) VALUES (10466, '1.  고령자, 환자 등 도주의 위험성이 크지 아니하다고 판단되는 군수용자를 개별 호송하는 경우에는 별표 15의 방법으로 할 수 있다.', 15131);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10467, '2.  제1호의 군수용자 외의 군수용자를 호송하는 경우 또는 법 제84조제1항제2호부터 제4호까지의 어느 하나에 해당하는 경우에는 별표 16의 방법으로 한다.', 15131);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10468, '3.  법 제84조제1항제2호부터 제4호까지의 어느 하나에 해당하는 경우로서 제2호의 방법으로는 사용목적을 달성할 수 없다고 인정되는 경우에는 별표 17의 방법으로 한다. 이 경우 2개의 포승을 연결하여 사용할 수 있다.', 15131);
