INSERT INTO balaw.ho (id, content, hang_id) VALUES (10495, '4.  음란한 행위를 하거나 다른 사람에게 성적(性的)인 말이나 행동으로 성적 수치심 또는 혐오감을 느끼게 하는 행위', 15153);
