INSERT INTO balaw.ho (id, content, hang_id) VALUES (10559, '11.  제59조제1항의 미수범', 15226);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10560, '12.  제66조부터 제70조까지 및 제71조제1항ㆍ제2항의 미수범', 15226);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10561, '13.  제87조부터 제90조까지의 미수범', 15226);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10562, '1.  "상관"이란 명령복종 관계에서 명령권을 가진 사람을 말한다. 명령복종 관계가 없는 경우의 상위 계급자와 상위 서열자는 상관에 준한다.', 15228);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10563, '2.  "지휘관"이란 중대 이상 단위부대의 장과 함선(艦船)부대의 장 또는 함정(艦艇) 및 항공기를 지휘하는 사람을 말한다.', 15228);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10564, '3.  "초병(哨兵)"이란 경계를 그 고유의 임무로 하여 지상, 해상 또는 공중에 책임 범위를 정하여 배치된 사람을 말한다.', 15228);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10565, '4.  "부대"란 군대, 군의 기관 및 학교와 전시(戰時) 또는 사변 시에 이에 준하여 특별히 설치하는 기관을 말한다.', 15228);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10566, '5.  "적전(敵前)"이란 적에 대하여 공격ㆍ방어의 전투행동을 개시하기 직전과 개시 후의 상태 또는 적과 직접 대치하여 적의 습격을 경계하는 상태를 말한다.', 15228);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10567, '6.  "전시"란 상대국이나 교전단체에 대하여 선전포고나 대적(對敵)행위를 한 때부터 그 상대국이나 교전단체와 휴전협정이 성립된 때까지의 기간을 말한다.', 15228);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10568, '7.  "사변"이란 전시에 준하는 동란(動亂)상태로서 전국 또는 지역별로 계엄이 선포된 기간을 말한다.', 15228);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10569, '1.  수괴(首魁): 사형', 15229);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10570, '2.  반란 모의에 참여하거나 반란을 지휘하거나 그 밖에 반란에서 중요한 임무에 종사한 사람과 반란 시 살상, 파괴 또는 약탈 행위를 한 사람: 사형, 무기 또는 7년 이상의 징역이나 금고', 15229);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10571, '3.  반란에 부화뇌동(附和雷同)하거나 단순히 폭동에만 관여한 사람: 7년 이하의 징역이나 금고', 15229);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10572, '1.  부대ㆍ기지ㆍ군항(軍港)지역 또는 그 밖에 군사시설 보호를 위한 법령에 따라 고시되거나 공고된 지역', 15238);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10573, '2.  부대이동지역ㆍ부대훈련지역ㆍ대간첩작전지역 또는 그 밖에 군이 특수작전을 수행하는 지역', 15238);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10574, '3.  「방위사업법」에 따라 지정되거나 위촉된 방위산업체와 연구기관', 15238);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10575, '1.  적을 위하여 진로를 인도하거나 지리를 알려준 사람', 15239);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10576, '2.  적에게 항복하게 하기 위하여 지휘관에게 이를 강요한 사람', 15239);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10577, '3.  적을 숨기거나 비호(庇護)한 사람', 15239);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10578, '4.  적을 위하여 통로, 교량, 등대, 표지 또는 그 밖의 교통시설을 손괴하거나 불통하게 하거나 그 밖의 방법으로 부대 또는 군용에 공하는 함선, 항공기 또는 차량의 왕래를 방해한 사람', 15239);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10579, '5.  적을 위하여 암호 또는 신호를 사용하거나 명령, 통보 또는 보고의 내용을 고쳐서 전달하거나 전달을 게을리하거나 거짓 명령, 통보나 보고를 한 사람', 15239);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10580, '6.  적을 위하여 부대, 함대(艦隊), 편대(編隊) 또는 대원을 해산시키거나 혼란을 일으키게 하거나 그 연락이나 집합을 방해한 사람', 15239);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10581, '7.  군용에 공하지 아니하는 병기, 탄약 또는 전투용에 공할 수 있는 물건을 적에게 제공한 사람', 15239);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10582, '8.  그 밖에 대한민국의 군사상 이익을 해하거나 적에게 군사상 이익을 제공한 사람', 15239);
