INSERT INTO balaw.ho (id, content, hang_id) VALUES (10597, '1.  지휘관 또는 이에 준하는 장교로서 그 임무를 수행하면서 적과의 교전이 예측되는 경우에 전투준비를 게을리한 사람', 15248);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10598, '2.  장교로서 부대 또는 병원(兵員)을 인솔하여 그 임무를 수행하면서 적을 만나거나 그 밖의 위난(危難)에 처하여 정당한 사유 없이 부대 또는 병원을 유기한 사람', 15248);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10599, '3.  직무상 공격하여야 할 적을 정당한 사유 없이 공격하지 아니하거나 직무상 당연히 감당하여야 할 위난으로부터 이탈한 사람', 15248);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10600, '4.  군사기밀인 문서 또는 물건을 보관하는 사람으로서 위급한 경우에 있어서 부득이한 사유 없이 적에게 이를 방임한 사람', 15248);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (10601, '5.  전시, 사변 시 또는 계엄지역에서 병기, 탄약, 식량, 피복 또는 그 밖에 군용에 공하는 물건을 운반 또는 공급하는 사람으로서 부득이한 사유 없이 이를 없애거나 모자라게 한 사람', 15248);
