INSERT INTO balaw.ho (id, content, hang_id) VALUES (10767, '1.  "수용자"란 수형자ㆍ미결수용자ㆍ사형확정자 등 법률과 적법한 절차에 따라 교도소ㆍ구치소 및 그 지소(이하 "교정시설"이라 한다)에 수용된 사람을 말한다.', 15656);
