INSERT INTO balaw.ho (id, content, hang_id) VALUES (11067, '1.  문자, 그 밖의 기호, 도면ㆍ사진 등에 대한 증거조사: 해당 전자문서를 모니터, 스크린 등을 통하여 열람하는 방법', 16211);
