INSERT INTO balaw.ho (id, content, hang_id) VALUES (11069, '1.  형을 선고하는 재판이 확정된 사건: 형의 시효가 완성된 때. 다만, 구류 또는 과료의 형이 선고된 경우에는 재판 확정일부터 3년이 지난 때로 한다.', 16215);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11070, '2.  무죄, 면소, 형의 면제, 공소기각 또는 선고유예의 재판이 확정된 사건: 공소시효가 완성된 때', 16215);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11071, '3.  불기소처분된 사건 및 「형사소송법」 제245조의5제2호에 따라 불송치결정된 사건: 공소시효가 완성된 때', 16215);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11072, '1.  "형사사법포털"이란 전자문서를 이용해 형사사법절차를 진행할 수 있도록 구축된 「형사사법절차 전자화 촉진법」 제2조제6호의 형사사법포털을 말한다.', 16217);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11073, '2.  "전자기록"이란 전자문서 또는 전자화문서를 사건별로 모아둔 것을 말한다.', 16217);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11074, '3.  "수사기관등"이란 법원을 제외한 형사사법업무 처리기관을 말한다.', 16217);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11075, '4.  "정보통신망"이란 「전기통신기본법」 제2조제2호에 따른 전기통신설비를 이용하거나 전기통신설비와 컴퓨터 및 컴퓨터의 이용기술을 활용해 정보를 수집ㆍ가공ㆍ저장ㆍ검색ㆍ송신 또는 수신하는 정보통신체제를 말한다.', 16217);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11076, '1.  피의자ㆍ피고인ㆍ피해자ㆍ고소인ㆍ고발인의 법정대리인(피해자가 사망한 경우 피해자의 배우자, 직계친족 및 형제자매를 포함한다)', 16218);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11077, '2.  피의자ㆍ피고인ㆍ피해자ㆍ고소인ㆍ고발인이 법인인 경우 그 대표자', 16218);
