INSERT INTO balaw.ho (id, content, hang_id) VALUES (11108, '2.  등록사용자에게 의사능력이 없는 경우', 16225);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11109, '3.  등록사용자가 형사사법포털을 이용해 전자문서를 제출ㆍ열람한 마지막 날부터 5년이 지난 경우', 16225);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11110, '4.  그 밖에 전산정보처리시스템 사용을 정지하거나 사용자등록을 말소할 필요가 있는 경우로서 법 제7조제3항제1호부터 제4호까지 또는 이 항 제1호부터 제3호까지에 준하는 경우', 16225);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11111, '1.  해당 전자문서에 공동명의자 전원이 인증서로 전자서명을 하여 제출하는 방법', 16236);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11112, '2.  해당 전자문서를 최초로 제출하는 등록사용자가 그 전자문서 속에 다른 공동명의자 전원의 전자서명을 포함시켜 제출하는 방법', 16236);
