INSERT INTO balaw.ho (id, content, hang_id) VALUES (11115, '2.  소속사용자를 지정한 등록사용자의 위임장과 그 등록사용자의 서명 또는 날인이 이루어진 확인서를 전자문서로 변환해 함께 제출하는 방법', 16238);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11116, '1.  전산정보처리시스템 또는 정보통신망에 발생한 장애의 복구 시기를 알 수 없거나 장애의 복구를 기다릴 경우 절차가 현저히 지연될 우려가 있는 경우', 16255);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11117, '2.  「형사소송법」 등 관계 법령에 따라 체포영장, 구속영장, 압수ㆍ수색ㆍ검증영장 등 영장을 집행할 때 급속을 요하거나 집행시한이 임박한 경우 또는 영장집행의 원활한 진행을 위해 필요한 경우', 16255);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11118, '3.  현장에서 관계 서류를 긴급히 작성하거나 교부해야 하는 등 전자문서로 작성하는 것이 현저히 곤란하거나 적합하지 않은 경우', 16255);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11119, '4.  수사기관등이 수사기관등 외의 기관으로부터 전자문서가 아닌 형태로 사건의 송치 등을 받아 그 사건에 대한 수사를 계속하는 경우', 16255);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11120, '5.  수사기관등이 보관ㆍ관리하고 있는 전자기록이 외부로 유출될 경우 국가의 존립ㆍ안전이나 자유민주적 기본질서에 해를 끼칠 우려가 있는 경우', 16255);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11121, '1.  제1항제1호부터 제3호까지의 각 사유가 해소된 경우', 16256);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11122, '2.  형사사법업무 처리기관에 전자기록을 전송하는 경우', 16256);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11123, '1.  현황이 중요한 의미가 있어 그 자체로 보관할 필요가 있는 경우', 16264);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11124, '2.  서적, 대형 도면 등 제출된 전자화대상문서의 크기, 선명도 등을 고려할 때 해당 전자화대상문서의 전부 또는 일부를 전자적인 형태로 변환ㆍ등재하는 것이 적절하지 않은 경우. 이 경우 일부 중요한 내용을 전자적인 형태로 변환ㆍ등재할 수 있다.', 16264);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11125, '3.  전자적인 형태로 변환하는 것이 기술적으로 어려운 경우', 16264);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11126, '4.  사건관계인의 영업비밀(「부정경쟁방지 및 영업비밀보호에 관한 법률」 제2조제2호의 영업비밀을 말한다)로서 외부로 유출될 경우 영업상의 이익이 침해되거나 침해될 우려가 있는 경우', 16264);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11127, '5.  수사기관등이 보관ㆍ관리하고 있는 전자기록이 외부로 유출될 경우 국가의 존립ㆍ안전이나 자유민주적 기본질서에 해를 끼칠 우려가 있는 경우', 16264);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11128, '6.  전자적인 형태로 변환할 경우 피해자에게 추가적인 피해가 발생할 우려가 있는 경우', 16264);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11129, '7.  사건과 관련이 없는 자료가 대량으로 제출되거나 반복적으로 제출되어 전자화대상문서를 전자적인 형태로 변환하는 것이 적절하지 않은 경우', 16264);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11130, '1.  전산등재 과정에서의 잘못 등으로 효력이 없음이 분명한 경우: 폐기', 16271);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11131, '2.  잘못된 계산이나 기재 등이 있음이 분명한 경우: 정정', 16271);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11132, '1.  개별 사건에 대해 전자적 송달 및 통지에 동의한 등록사용자', 16278);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11133, '2.  「형사소송법」 제60조에 따라 송달영수인으로 신고한 등록사용자', 16278);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11134, '3.  1년의 범위에서 일정한 기간을 정해 피의자ㆍ피고인ㆍ피해자ㆍ고소인ㆍ고발인ㆍ변호인 또는 제3조 각 호의 자가 될 것을 예정해 전자적 송달 및 통지에 동의한 등록사용자', 16278);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11135, '1.  법 제14조제1항제1호 또는 제2호의 경우: 전자문서를 전산정보처리시스템에 등재하고 그 전자문서를 송달ㆍ통지받을 형사사법업무 처리기관(그 소속 공무원이 송달ㆍ통지받는 경우를 포함한다)의 전산정보처리시스템으로 전송하는 방법', 16280);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11136, '2.  법 제14조제1항제3호의 경우: 전자문서를 전산정보처리시스템에 등재하고 그 전자문서를 송달ㆍ통지받을 등록사용자가 형사사법포털에 입력한 전자우편 및 문자전송 서비스를 이용해 보내는 방법(등록사용자가 요청한 경우에는 문자전송 서비스는 제외한다)', 16280);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11137, '1.  법 제14조제1항제1호 또는 제2호의 경우: 형사사법업무 처리기관의 전산정보처리시스템에 해당 전자문서가 전자적으로 기록된 때', 16282);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11138, '2.  법 제14조제1항제3호의 경우: 송달ㆍ통지를 받을 자가 전산정보시스템에 등재된 전자문서를 확인한 때', 16282);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11139, '1.  등록사용자가 사물을 변별하거나 의사를 결정할 능력이 없는 경우', 16284);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11140, '2.  등록사용자가 중대한 질병이나 부상 등으로 형사사법포털에 접속하기 어려운 경우', 16284);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11141, '1.  전산정보처리시스템 또는 정보통신망에 장애가 발생해 송달받을 자가 전산정보처리시스템에서 정상적으로 전자문서를 확인할 수 없는 경우', 16288);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11142, '2.  그 밖에 송달받을 자의 권익을 보호하기 위해 출력서면의 송달이 필요하다고 수사기관등이 인정하는 경우', 16288);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11143, '1.  법 제16조제1항에 따른 「형사소송법」의 각 규정에 따라 전자기록을 열람ㆍ등사 또는 복사하는 경우', 16291);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11144, '2.  「검사와 사법경찰관의 상호협력과 일반적 수사준칙에 관한 규정」 제69조에 따라 수사서류 등을 열람ㆍ복사하는 경우', 16291);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11145, '3.  「검사와 사법경찰관의 상호협력과 일반적 수사준칙에 관한 규정」 제42조제2항 후단에 따라 전자정보의 삭제ㆍ폐기 또는 반환 확인서를 교부받는 경우', 16291);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11146, '1.  변호인이 「형사소송법」 제243조의2제4항 및 「검사와 사법경찰관의 상호협력과 일반적 수사준칙에 관한 규정」 제14조제1항에 따라 피의자신문조서를 열람하는 경우', 16294);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11147, '2.  피고인이 「형사소송법」 제266조의3제1항 단서에 따라 공소제기된 사건에 관한 서류 또는 물건을 열람하는 경우', 16294);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11148, '1.  전산정보처리시스템(전자소송시스템을 포함한다) 또는 정보통신망에 장애가 있는 경우', 16301);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11149, '2.  피해자의 사생활 보호 또는 추가적인 피해 발생의 예방이 필요한 경우', 16301);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11150, '3.  그 밖에 전자적인 형태로 변환하는 것이 기술적으로 어려운 경우', 16301);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11151, '1.  중대재해사건, 흉악범죄, 부패범죄 등 국내외적으로 사회적 관심이 집중되는 사건', 16309);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11152, '2.  공범에 대한 수사가 필요한 사건', 16309);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11153, '3.  「형사소송법」 제247조 및 「보호관찰 등에 관한 법률」 제15조제3호에 따라 검사가 보호관찰관의 선도(善導)를 조건으로 공소제기를 유예하는 처분을 한 사건', 16309);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11154, '4.  「고위공직자범죄수사처 설치 및 운영에 관한 법률」 제2조제3호의 고위공직자범죄 및 같은 조 제4호의 관련범죄로 공소가 제기된 사건', 16309);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11155, '5.  「국민의 형사재판 참여에 관한 법률」에 따라 국민참여재판으로 진행된 사건', 16309);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11156, '6.  사형, 무기 또는 10년 이상의 징역이나 금고가 선고된 사건', 16309);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11157, '7.  보안처분이 집행된 사건', 16309);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11158, '8.  법 제20조제1항제1호 및 제2호에서 정한 기간이 지나기 전에 상소권회복청구나 재심청구가 있는 사건', 16309);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11159, '9.  상소권회복청구나 재심청구가 예상되는 사건', 16309);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11160, '10.  그 밖에 제1호부터 제9호까지에 준하는 사유로 특별히 영구 보관하거나 폐기를 늦출 필요가 있는 사건으로 수사기관등의 장이 정하는 사건', 16309);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11161, '1.  피의자의 성명, 국적, 주민등록번호, 외국인등록번호(피의자가 외국인인 경우로 한정한다), 여권번호(피의자의 주민등록번호 또는 외국인등록번호가 없는 경우로 한정한다) 등 인적 사항', 16311);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11162, '2.  죄명, 입건관서, 입건일자, 처분결과, 선고결과 등 수사경력 또는 범죄경력에 관한 사항', 16311);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11163, '1.  「형사소송법」 제197조제1항의 사법경찰관', 16315);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11164, '2.  「군사법원법」 제43조의 군사법경찰관', 16315);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11165, '3.  다른 법률에 따라 사법경찰관의 직무를 수행하는 사람', 16315);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11166, '1.  법 제6조제1항제5호ㆍ제6호 및 제8호의 경우에는 범죄경력자료와 수사 또는 재판 중에 있는 사건의 수사경력자료', 16321);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11167, '2.  법 제6조제1항제7호의 경우에는 범죄경력자료와 소년부송치ㆍ기소유예 또는 공소권없음으로 결정되거나 수사 또는 재판 중에 있는 사건의 수사경력자료', 16321);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11168, '3.  법 제6조제1항제9호의 경우에는 그 결격사유, 징계절차가 개시된 공무원의 구체적인 징계 사유 또는 지급제한사유 등(이하 "결격사유등"이라 한다)을 확인하기 위하여 필요한 자료로 하되, 결격사유등에 해당하는 범죄경력을 특정하기 어려운 때에는 다음 각 목의 자료. 다만, 징계절차가 개시된 공무원의 구체적인 징계 사유를 확인하기 위한 경우에는 범죄경력자료에 한정한다.', 16321);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11169, '1.  법 제7조 또는 「형법」 제81조에 따라 실효된 형', 16325);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11170, '2.  사면 또는 복권이 있은 형', 16325);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11171, '3.  결정이 있은 때부터 3년이 지난 「소년법」상의 소년부송치 및 보호처분', 16325);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11172, '4.  「형법」 제60조에 따라 면소된 것으로 간주된 선고유예', 16325);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11173, '5.  「형법」 제65조에 따라 선고의 효력을 잃은 집행유예', 16325);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11174, '1.  법 제7조 또는 「형법」 제81조에 따라 실효된 형', 16326);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11175, '2.  「사면법」에 따라 형 선고의 효력을 상실하게 하는 사면 또는 복권을 받은 형', 16326);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11176, '3.  결정이 있은 때부터 3년이 지난 「소년법」상의 소년부송치 및 보호처분', 16326);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11177, '4.  「형법」 제60조에 따라 면소된 것으로 간주된 선고유예', 16326);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11178, '5.  「형법」 제65조에 따라 선고의 효력을 잃은 집행유예', 16326);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11179, '1.  법 제3조ㆍ제4조 및 제8조에 따른 수형인명부 및 수형인명표에 관한 사무', 16331);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11180, '2.  법 제5조 및 제5조의2에 따른 수사자료표에 관한 사무', 16331);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11181, '3.  법 제6조에 따른 범죄경력조회 및 수사경력조회와 그 회보에 관한 사무', 16331);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11182, '4.  법 제8조의2에 따른 수사경력자료의 정리에 관한 사무', 16331);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11183, '5.  법 제8조의3에 따른 전과기록이나 수사경력자료의 제출 및 시정에 관한 사무', 16331);
