INSERT INTO balaw.ho (id, content, hang_id) VALUES (11294, '1.  질병ㆍ부상 기타 긴급한 사유의 발생으로 피보안관찰자의 생명ㆍ신체에 중대한 위험이 예상될 때', 16478);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11295, '2.  기타 응급구호를 함이 적절하다고 인정되는 긴급한 사유가 있는 때', 16478);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11296, '1.  "피해자등"이란 「부패재산의 몰수 및 회복에 관한 특례법」(이하 "법"이라 한다) 제6조제1항에 따른 범죄피해재산의 몰수ㆍ추징의 원인이 되는 범죄로 인해 재산상 손해를 입은 자와 그 포괄승계인을 말한다.', 16480);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11297, '2.  "피해인정재산"이란 범죄피해재산에서 다음 각 목의 재산을 제외한 재산으로서 검사가 그 제외한 범위를 확인한 재산을 말한다.', 16480);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11298, '3.  "회복대상재산"이란 법 제6조제1항에 따라 몰수ㆍ추징된 범죄피해재산으로서 환부의 대상이 되는 재산(법 제17조에 따라 외국으로부터 환수받은 집행재산등을 포함한다)을 말한다.', 16480);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11299, '4.  "피해회복금"이란 회복대상재산에서 통지ㆍ공고 등 법무부령으로 정하는 환부절차에 드는 비용(이하 "비용"이라 한다)을 빼고 피해인정재산의 범위에서 피해자등에게 지급하는 금전을 말한다.', 16480);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11300, '1.  회복대상재산을 보관하고 있는 검사 및 그가 소속된 관할 검찰청', 16484);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11301, '2.  회복대상재산의 명세 및 그 가액', 16484);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11302, '3.  회복대상재산과 관련된 몰수재판 또는 추징재판을 한 법원, 재판 연월일 및 확정 연월일, 사건번호, 재판을 받은 피고인의 성명, 그 몰수 또는 추징의 이유가 된 범죄사실의 요지 및 죄명', 16484);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11303, '4.  제6조제1항에 따라 환부를 청구해야 하는 기간', 16484);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11304, '1.  청구인이 피해자등이라는 사실', 16487);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11305, '2.  반환을 청구하는 범죄피해재산 및 그 가액', 16487);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11306, '3.  피해자등이 범죄피해재산 중 반환받거나 범죄피해재산에 관하여 손해배상을 받은 때에는 그 재산이나 가액', 16487);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11307, '4.  그 밖에 범죄피해재산의 환부청구를 위해 필요한 사항으로서 법무부령으로 정하는 사항', 16487);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11308, '1.  청구가 이유 있다고 인정하는 경우: 청구를 인용(認容)하여 회복대상재산을 환부한다는 결정', 16489);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11309, '2.  청구가 이유 없다고 인정하는 경우: 청구를 기각한다는 결정', 16489);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11310, '3.  청구가 일부만 이유 있다고 인정하는 경우: 청구의 일부를 인용하여 회복대상재산의 일부를 환부하고, 청구의 일부를 기각한다는 결정', 16489);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11311, '4.  제6조제1항에 따른 청구기간이 지난 후에 청구한 경우: 청구를 각하한다는 결정', 16489);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11312, '1.  회복대상재산이 금전 외의 재산인 경우: 그 재산을 환부', 16492);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11313, '2.  회복대상재산이 금전이거나 제3조제3항에 따라 회복대상재산을 환가 또는 징수한 경우: 피해회복금을 환부', 16492);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11314, '1.  이의신청이 이유 있다고 인정하는 경우: 이의신청을 인용하여 회복대상재산을 환부한다는 결정', 16496);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11315, '2.  이의신청이 이유 없다고 인정하는 경우: 이의신청을 기각한다는 결정', 16496);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11316, '3.  이의신청의 일부만 이유 있다고 인정하는 경우: 이의신청의 일부를 인용하여 회복대상재산의 일부를 환부하고, 일부는 기각한다는 결정', 16496);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11317, '4.  제1항에 따른 이의신청 기간이 지난 후에 이의신청을 한 경우: 이의신청을 각하한다는 결정', 16496);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11318, '1.  검사가 제6조에 따른 환부청구에 관하여 필요하다고 판단하여 심의회에 심의를 요청한 사항', 16499);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11319, '2.  제10조에 따른 이의신청', 16499);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11320, '3.  그 밖에 범죄피해재산 환부절차와 관련하여 검사가 심의를 요청한 사항', 16499);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11321, '1.  "성도착증 환자"란 「치료감호 등에 관한 법률」 제2조제1항제3호에 해당하는 사람 및 정신건강의학과 전문의의 감정에 의하여 성적 이상 습벽으로 인하여 자신의 행위를 스스로 통제할 수 없다고 판명된 사람을 말한다.', 16506);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11322, '2.  "성폭력범죄"란 다음 각 목의 범죄를 말한다.', 16506);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11323, '3.  "성충동 약물치료"(이하 "약물치료"라 한다)란 비정상적인 성적 충동이나 욕구를 억제하기 위한 조치로서 성도착증 환자에게 약물 투여 및 심리치료 등의 방법으로 도착적인 성기능을 일정기간 동안 약화 또는 정상화하는 치료를 말한다.', 16506);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11324, '1.  비정상적 성적 충동이나 욕구를 억제하거나 완화하기 위한 것으로서 의학적으로 알려진 것일 것', 16507);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11325, '2.  과도한 신체적 부작용을 초래하지 아니할 것', 16507);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11326, '3.  의학적으로 알려진 방법대로 시행될 것', 16507);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11327, '1.  치료명령 피청구자의 성명과 그 밖에 치료명령 피청구자를 특정할 수 있는 사항', 16519);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11328, '2.  청구의 원인이 되는 사실', 16519);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11329, '3.  적용 법조', 16519);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11330, '4.  그 밖에 대통령령으로 정하는 사항', 16519);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11331, '1.  치료명령 청구가 이유 없다고 인정하는 때', 16523);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11332, '2.  피고사건에 대하여 무죄(심신상실을 이유로 치료감호가 선고된 경우는 제외한다)ㆍ면소ㆍ공소기각의 판결 또는 결정을 선고하는 때', 16523);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11333, '3.  피고사건에 대하여 벌금형을 선고하는 때', 16523);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11334, '4.  피고사건에 대하여 선고를 유예하거나 집행유예를 선고하는 때', 16523);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11335, '1.  보호관찰관의 지시에 따라 성실히 약물치료에 응할 것', 16540);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11336, '2.  보호관찰관의 지시에 따라 정기적으로 호르몬 수치 검사를 받을 것', 16540);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11337, '3.  보호관찰관의 지시에 따라 인지행동 치료 등 심리치료 프로그램을 성실히 이수할 것', 16540);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11338, '1.  치료명령의 집행 중 구속영장의 집행을 받아 구금된 때', 16551);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11339, '2.  치료명령의 집행 중 금고 이상의 형의 집행을 받게 된 때', 16551);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11340, '3.  가석방 또는 가종료ㆍ가출소된 자에 대하여 치료기간 동안 가석방 또는 가종료ㆍ가출소가 취소되거나 실효된 때', 16551);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11341, '1.  제4항제1호의 경우에는 구금이 해제되거나 금고 이상의 형의 집행을 받지 아니하는 것으로 확정된 때부터 그 잔여기간을 집행한다.', 16552);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11342, '2.  제4항제2호의 경우에는 그 형의 집행이 종료되거나 면제된 후 또는 가석방된 때부터 그 잔여기간을 집행한다.', 16552);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11343, '3.  제4항제3호의 경우에는 그 형이나 치료감호 또는 보호감호의 집행이 종료되거나 면제된 후 그 잔여기간을 집행한다.', 16552);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11344, '1.  정당한 사유 없이 「보호관찰 등에 관한 법률」 제32조제2항(제4호는 제외한다) 또는 제3항에 따른 준수사항을 위반한 경우', 16557);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11345, '2.  정당한 사유 없이 제15조제2항을 위반하여 신고하지 아니한 경우', 16557);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11346, '3.  거짓으로 제15조제3항의 허가를 받거나, 정당한 사유 없이 제15조제3항을 위반하여 허가를 받지 아니하고 주거 이전, 국내여행 또는 출국을 하거나 허가기간 내에 귀국하지 아니한 경우', 16557);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11347, '1.  치료기간이 지난 때', 16571);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11348, '2.  치료명령과 함께 선고한 형이 사면되어 그 선고의 효력을 상실하게 된 때', 16571);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11349, '3.  치료명령이 임시해제된 사람이 그 임시해제가 취소됨이 없이 잔여 치료기간을 지난 때', 16571);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11350, '1.  교도소ㆍ구치소(이하 "수용시설"이라 한다)의 장은 「형법」 제72조제1항의 가석방 요건을 갖춘 성폭력 수형자에 대하여 약물치료의 내용, 방법, 절차, 효과, 부작용, 비용부담 등에 관하여 충분히 설명하고 동의 여부를 확인하여야 한다.', 16575);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11351, '2.  제1호의 성폭력 수형자가 약물치료에 동의한 경우 수용시설의 장은 지체 없이 수용시설의 소재지를 관할하는 지방검찰청의 검사에게 인적사항과 교정성적 등 필요한 사항을 통보하여야 한다.', 16575);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11352, '3.  검사는 소속 검찰청 소재지 또는 성폭력 수형자의 주소를 관할하는 보호관찰소의 장에게 성폭력 수형자에 대하여 제5조제1항에 따른 조사를 요청할 수 있다.', 16575);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11353, '4.  보호관찰소의 장은 제3호의 요청을 접수한 날부터 2개월 이내에 제5조제3항의 조사보고서를 제출하여야 한다.', 16575);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11354, '5.  검사는 성폭력 수형자에 대하여 약물치료의 내용, 방법, 절차, 효과, 부작용, 비용부담 등에 관하여 설명하고 동의를 확인한 후 정신건강의학과 전문의의 진단이나 감정을 받아 법원에 치료명령을 청구할 수 있다. 이 때 검사는 치료명령 청구서에 제7조제1항 각 호의 사항 외에 치료명령 피청구자의 동의사실을 기재하여야 한다.', 16575);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11355, '6.  법원은 제5호의 치료명령 청구가 이유 있다고 인정하는 때에는 결정으로 치료명령을 고지하고 치료명령을 받은 사람에게 준수사항 기재서면을 송부하여야 한다.', 16575);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11356, '1.  해당 결정에 영향을 미칠 법령위반이 있거나 중대한 사실오인이 있는 경우', 16578);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11357, '2.  처분이 현저히 부당한 경우', 16578);
