INSERT INTO balaw.ho (id, content, hang_id) VALUES (11462, '4.  교통ㆍ통신, 국가 또는 공공단체가 사용하는 건조물 기타 중요시설을 파괴하거나 사람을 약취ㆍ유인하거나 함선ㆍ항공기ㆍ자동차ㆍ무기 기타 물건을 이동ㆍ취거한 때에는 사형ㆍ무기 또는 5년 이상의 징역에 처한다.', 16706);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11463, '5.  형법 제214조 내지 제217조ㆍ제257조 내지 제259조 또는 제262조에 규정된 행위를 하거나 국가기밀에 속하는 서류 또는 물품을 손괴ㆍ은닉ㆍ위조ㆍ변조한 때에는 3년 이상의 유기징역에 처한다.', 16706);
INSERT INTO balaw.ho (id, content, hang_id) VALUES (11464, '6.  제1호 내지 제5호의 행위를 선동ㆍ선전하거나 사회질서의 혼란을 조성할 우려가 있는 사항에 관하여 허위사실을 날조하거나 유포한 때에는 2년 이상의 유기징역에 처한다.', 16706);
